      INTEGER :: NID
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: ICT
      INTEGER :: MODE
      INTEGER :: NIEN
      INTEGER :: NTYP
      INTEGER :: NSMR
      INTEGER :: NRET
      INTEGER :: MORT
      INTEGER :: ITRS
      INTEGER :: IENM
      INTEGER :: NOPT
      INTEGER :: NCHAR
      INTEGER :: IDUM2
      INTEGER :: IEXIT
      INTEGER :: IFN10
      INTEGER :: ITRNS
      INTEGER :: IYUNK
      INTEGER :: IRETN
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: JNQNR2
      INTEGER :: INQNR2
      INTEGER :: IPR220
      INTEGER :: NRETURN = 0
      INTEGER :: IUNKNOWN
      REAL :: ANG
      REAL :: FNN
      REAL :: FN1
      REAL :: FN2
      REAL :: DET
      REAL :: DIFF
      REAL :: GEN016
 
      CHARACTER(len=3) :: OPT
      CHARACTER(len=9) :: EXTENS1
C * TEST FOR A 'CALC' = 'CALC ALL' JOB (i.e. IPR(121) > 0)
  10  IF (IPR(121) == 0) THEN
C * DEFAULT POSITION OF LABEL IN ATOM RECORD
        IPR(473) = 2
C * DATA READ SEQUENCE LU1, LU3, LU5
C * GET NEXT INPUT-LINE AND RECORD TYPE (IN IS)
        CALL PLA006 (0, IS)
C * ERROR CHECK
        IF (IPR(2) /= 0) THEN
C * ERROR HANDLING
          IGBL(1) = 3
          RETURN
        END IF
C * CHECK FOR AND HANDLE SHELX(L) TYPE INPUT RECORDS
        CALL PLA383 (IS)
        DO
          SELECT CASE (IS)
C * IS = -4: SHELXL INSTRUCTION RECORD
            CASE (-4)
              EXIT
C * IS = -3: CIF BOND/ANGLE/TORSION/HBOND
            CASE (-3)
              GO TO 10
C * IS = -1 & IS = -2: HANDLE END-OF-FILE (SWITCH TO LU3 OR LU5 RESP. READING)
            CASE (-1, -2)
              IF (IGBL(5) == LU5) THEN
                GO TO 190
              ELSE IF (IGBL(5) == LU3) THEN
                IGBL(5) = LU5
C * OPEN MAIN X-WINDOW (IGBL(24) = 1)
                IGBL(6)  = 10
                IGBL(24) = 1
                GO TO 10
              ELSE
C * CHECK FOR NO-ATOMS & NO-FACES AND NO-CELL INFO FOUND
                IF (IPR(37) == 0 .AND. IPR(367) == 0 .AND.
     1              PAR(101) == 0.0) GO TO 200
C * CHECK FOR 'ENDS'
                IF (IPR(3) == 1) THEN
                  IPR(3) = -1
                  GO TO 200
                ELSE
                  IGBL(5) = LU3
                END IF
              END IF
              CALL GEN108 (LU3, 0)
              GO TO 10
C * IS = 0: FORMAT/READ - ERROR
            CASE (0)
              IPR(2) = 61
              GO TO 200
C * IS = 1, 28: POTENTIAL ATOM LINE/ATOM
            CASE (1, 28)
              IF (IS == 1) THEN
                IF (IGBL(5) == 5) GO TO 10
                IPR(473) = 1
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
                IF (IPR(30) /= 0) THEN
C * UNKNOWN CARD ERROR
                  IPR(2) = 7
                  GO TO 200
                END IF
              END IF
C * ATOMIC COORDS IN FREE-FORMAT INPUT
              IF (IPR(220) < IPR(473) .OR. IPR(221) < 3) THEN
                IPR(471) = IPR(471) + 1
                IF (IGBL(5) == LU5) THEN
C * UNKNOWN CARD ERROR
                  IPR(2) = 7
                  GO TO 200
                END IF
              ELSE
                IF (IGBL(8) /= 2 .OR. IGBL(95) /= 1 .OR.
     1            IFL(1)(1:1) /= 'Q' .OR. FN(7) >= RGBL(26)) THEN
                  CALL PLA450 (INQNR)
C * CHECK FOR ERROR RETURN
                  IF (IPR(2) /= 0) THEN
                    IF (IPR(2) == 10) THEN
                      IGBL(1) = 3
                      RETURN
                    ELSE
                      GO TO 200
                    END IF
                  END IF
                END IF
              END IF
              GO TO 10
C * IS = 3: MESSAGE (ECHO)
            CASE (3)
              WRITE (LU6, 99988, IOSTAT = IOST) ICL(5:80)
              GO TO 10
C * IS = 5: ANGSTROM COORDINATE SCALE
            CASE (5)
              IF (IPR(221) == 1) THEN
                CALL PLA100
                PAR(11) = FN(1)
              END IF
              GO TO 10
C * IS = 6: ROUND ON/OFF OPTION
            CASE (6)
              IF (IPR(221) == 1) THEN
                IPR(68) = MAX (MIN (NINT(FN(1)), 10), 0)
              ELSE
                IPR(68) = 1
              END IF
              IF (IPR(220) > 1) THEN
                IF (IFL(2)(1:3) == 'OFF') THEN
                  IPR(68) = 0
                END IF
              END IF
              IF (IPR(68) > 0) THEN
                CALL GEN040 (IPR(68), NQ1, IP)
                WRITE (LU6, 99990, IOSTAT = IOST) IPR(68) * 10 - 1
              END IF
              GO TO 180
C * IS = 7: FIT MOL1 ON MOL2 (OR INVERTED MOL2)
            CASE (7)
C * SAVE OPTION TEST
              IF (IGBL(45) > 0 .AND. IGBL(5) == LU5) THEN
                IGBL(45) = IGBL(45) + 1
                WRITE (LU3, 99984, IOSTAT = IOST) ICL(1:80)
                WRITE (LU6, 99973, IOSTAT = IOST) ICL(1:70)
              END IF
              IF (IPR(220) == 1 .AND. IPR(221) == 0) THEN
                IPR(1)  = 7
                IPR(81) = -1
                CALL PLA021 (11, NRETURN)
                RETURN
              ELSE
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
                IF (IPR(30) == 0) THEN
C * FIT RES-NR1 RES-NR2
                  IF (IPR(221) == 2) THEN
                    FN1      = FN(1)
                    FN2      = FN(2)
                    IPR(221) = 0
C * NO SORTING WHEN NON-ZERO NUMBER OF ALIASES
                    IF (IPR(759) > 0) IGBL(33) = 0
                    WRITE (LU6, 99963)
C * SET UP CONNECTED SET
                    CALL PLA067
                    IF (IPR(2) /= 0) RETURN
                    CALL PLA073 (-1, -1)
                    FN(1)    = FN1
                    FN(2)    = FN2
                    IPR(221) = 2
                    IPR(220) = - IPR(220)
C * FIT ATOM-NAME1 ATOM-NAME2
                  ELSE IF (IPR(220) == 3) THEN
                    IPR220   = IPR(220)
                    IPR(220) = 1
C * SET UP CONNECTED SET
                    CALL PLA067
                    IF (IPR(2) /= 0) RETURN
                    CALL PLA073 (-1, -1)
                    IPR(220) = - IPR220
                  ELSE
                    NTYP = 0
                    GO TO 20
                  END IF
                ELSE
                  IPR(220) = - IPR(220)
                END IF
                GO TO 30
              END IF
              GO TO 10
C * IS = 8: LSPL: EXPLICIT PLANE SPECIFICATION
            CASE (8)
              NTYP = 4
              GO TO 20
C * IS = 9: RING: EXPLICIT RING SPECIFICATION
            CASE (9)
              NTYP = 2
              GO TO 20
C * IS = 10: NOMOVE (OFF)
            CASE (10)
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
              IF (IPR(30) == 0) THEN
                IF (IPR(220) > 1 .AND. IFL(2)(1:3) == 'OFF') THEN
                  IGBL(30) = 0
C * MOVE MOLECULES CLOSEST TO FN(1), FN(2), FN(3) FRACTIONAL POSITION
                  IF (IPR(221) == 3) THEN
                    DO I = 1, 3
                      PAR(63 + I) = FN(I)
                    END DO
                  END IF
                ELSE
                  IGBL(30) = 1
                END IF
              END IF
              GO TO 10
C * IS = 11: MolVolume
            CASE (11)
C * RESET DEFAULT GRID STEP
              IF (IPR(221) /= 0) PAR(569) = FN(1)
C * SAVE OPTION TEST
              IF (IGBL(45) > 0 .AND. IGBL(5) == LU5) THEN
                IGBL(45) = IGBL(45) + 1
                WRITE (LU3, 99984, IOSTAT = IOST) ICL(1:80)
                WRITE (LU6, 99973, IOSTAT = IOST) ICL(1:70)
              END IF
C * SET TO NO R/S CALC
              IPR(744) = 1
C * Molecular volume  CALCULATION
              CALL PLA396
              RETURN
C * IS = 12: DONOR/ACCEPTOR TYPES
            CASE (12)
              IPR(480) = 0
              DO I = 1, IPR(220)
                CALL PLA037 (I, N, 2)
C * SKIP ELEMENTS THAT ARE NOT PRESENT
                IF (N > 0) THEN
                  IF (IPR(480) <= NP10) THEN
                    IPR(480)        = IPR(480) + 1
                    IDOAC(IPR(480)) = IEN(N)
                  ELSE
                    WRITE (LU6, 99979, IOSTAT = IOST) NP10
                  END IF
                END IF
              END DO
              GO TO 180
C * IS = 13: SPECIAL LINE MANAGEMENT
            CASE (13)
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
              IF (IPR(30) == 0) THEN
                IF (IPR(220) == 3 .AND. IPR(407) < 10) THEN
                  DO I = 2, 3
                    CALL PLA046 (1, IFL(I), IENM, LBB, LBC, LBD,
     1                           INQNR, JNQNR, NIEN)
                    IF (NIEN < 0) GO TO 10
                    SLN(IPR(407) + 1, I - 1) = INQNR
                  END DO
                  IPR(407) = IPR(407) + 1
                  WRITE (LU6, 99987, IOSTAT = IOST)
                END IF
              END IF
              GO TO 10
C * IS = 14: ENDS
            CASE (14)
              IPR(3)  = 1
              IGBL(8) = - IABS (IGBL(8))
              IGBL(5) = LU3
              CALL GEN108 (LU3, 0)
              GO TO 10
C * IS = 15: PLOT
            CASE (15)
              IPR(14) = 0
              GO TO 80
C * IS = 16: YES
            CASE (16)
              GO TO 210
C * IS = 18: CALC
            CASE (18)
              IF (IPR(220) == 2) THEN
                IF (IFL(2)(1:3) == 'ALL') IPR(220) = 1
              END IF
              GO TO 100
C * IS = 19: END
            CASE (19)
              GO TO 190
C * IS = 20/21: (1/0)IN/EXCLUDE NAMED ELEMENTS IN/FROM CALCULATIONS
            CASE (20, 21)
              IF (IS == 20) THEN
                IPR(70) = 1
              ELSE
                IPR(70) = 0
              END IF
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
              IF (IPR(30) == 1) THEN
C * INSTRUCTION NOT ALLOWED
                IPR(2) = 11
                GO TO 200
              ELSE
                IPR(4) = 0
C * LOOP MAXIMUM IS POTENTIALLY REDEFINED WITHIN THE LOOP
                I = 1
                DO WHILE (I < IPR(220))
                  I = I + 1
C * TEST FOR KEYWORD METAL
                  IF (IFL(I)(1:3) == 'MET') THEN
                    DO J = 1, IAN
                      IF (IATPR(IEN(J)) > 0) THEN
                        IPR(220)           = IPR(220) + 1
                        N                  = IEL(IEN(J))
                        N1                 = N / 100
                        IFL(IPR(220))(1:3) =
     1                      CHAR (ICHAR ('A') - 1 + N1)//'  '
                        N1                 = MOD (N, 100)
                        IF (N1 > 0) THEN
                          IFL(IPR(220))(2:2) =
     1                      CHAR (ICHAR ('A') - 1 + N1)
                        END IF
                      END IF
                    END DO
                    CYCLE
                  END IF
                  CALL PLA037 (I, N, 2)
C * SKIP SPECIFIED ELEMENTS THAT ARE NOT PRESENT
                  IF (N > 0) THEN
                    IF (IPR(4) <= NP10) THEN
                      IPR(4) = IPR(4) + 1
C * SCRATCH USE OF ARRAY RADI FOR INCLUDE OPTION
                      RADR(IPR(4), 2) = N
                    ELSE
                      WRITE (LU6, 99978, IOSTAT = IOST) NP10
                    END IF
                  ELSE
                    IPR(2) = 16
                    IPR(4) = 0
                    IAN    = IAN - 1
                    GO TO 200
                  END IF
                END DO
                GO TO 180
              END IF
              GO TO 10
C * IS = 22, 45, 53: STOP/QUIT/EXIT - NO FULL END PROCESSING - TERMINATE JOB
            CASE (22, 45, 53)
              WRITE (LU6, 99999, IOSTAT = IOST)
     1          IGBL(49), NAMEFIL(1 : KNMFIL)
              IGBL(1) = 4
              RETURN
C * IS = 23: HELP (SPGR)
            CASE (23)
              IF (IPR(220) > 1) THEN
                OPT = IFL(2)(1:3)
C * LIST KNOWN SPACE GROUP NAMES
                IF (OPT == 'SPG') THEN
                  CALL SGSM (14, ICL, SGY, 0, LU6, IERR)
                  GO TO 10
                END IF
              END IF
C * HELP MANUAL
              IWIN = IGBL(25) * IGBL(32)
              CALL PLA299 (1)
C * GET NEW INSTRUCTION
              RETURN
C * IS = 24: SAVE INSTRUCTION OPTION ON
            CASE (24)
              IGBL(45) = 1
              ISAVEMOD = 1
              CALL GEN108 (LU3, 0)
              GO TO 10
C * IS = 25,26: UIJ/SUIJ
            CASE (25, 26)
C * UIJ DATA & SUIJ DATA
C * INCLUDE A*,B* AND C* INTO U(I, J) BEFORE TRANSFORMATION
              CALL GEN144 (1, FN(1), PAR(135))
C * CHECK FOR SUIJ
              IF (IS == 26) THEN
                ICT = 3
                GO TO 50
              END IF
              GO TO 40
C * IS = 27, 41: U, B DATA (SHOULD INCLUDE ATOM LABEL)
            CASE (27, 41)
              IF (IS == 41) THEN
                IF (IPR(220) == 1) THEN
                  IS = 1
                  CYCLE
                END IF
                FN(1) = FN(1) / RGBL(8)
                FN(2) = FN(2) / RGBL(8)
              END IF
              IF (IPR(220) == 1) THEN
                IS = 1
                CYCLE
              END IF
              ICT = 4
              GO TO 60
C * IS = 29: LIST/INFO
            CASE (29)
C * LIST OPTION(S) ON DISPLAY (ATOMS/BONDS/SYMM/PAR/IPR/IGBL/RADII/CELL)
              IF (IFL(2)(1:3) == 'UIJ') THEN
                IF (IPR(30) == 0) THEN
                  CALL PLA280 ('CALC TMA')
                  GO TO 10
                END IF
              END IF
              IRETN = 0
              CALL PLA382 (IRETN)
              IF (IRETN /= 0) THEN
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
                IF (IPR(30) == 0) THEN
                  IGBL(52) = MAX (IGBL(52), IPR(23))
                  IPR(205) = 0
                END IF
                CALL PLA021 (11, NRETURN)
                RETURN
              END IF
              GO TO 10
C * IS = 30: CELL CONSTANTS
            CASE (30)
C * ASSUME A = B = C
              IF (IPR(221) == 1) THEN
                FN(2)    = FN(1)
                FN(3)    = FN(1)
                IPR(221) = 3
              END IF
C * ASSUME 90,90,90
              IF (IPR(221) == 3) THEN
                CALL GEN074 (FN, 4, 6, 90.0)
                IPR(221) = 6
              END IF
              IF (IPR(221) < 6 .OR.
     1           (IPR(221) > 7 .AND. IPR(221) /= 12)) THEN
C * NOT ENOUGH DATA ON CARD
                IPR(2) = 5
                GO TO 200
              END IF
C * TEST FOR SHELX STYLE CELL CARD
              IF (IPR(221) == 7) THEN
C * REGISTER SUPPLIED WAVELENGTH (PAR(16))
                PAR(16) = FN(1)
                PAR(17) = FN(1)
                K = 1
              ELSE
                K = 0
              END IF
              DO I = 1, 12
C * TEST CELL CARD FOR ZERO'S
                IF (I <= 3 .AND. ABS (FN(K + I)) < 2.0) THEN
                  IF (IGBL(5) == LU1) IPR(470) = 1
C * NOT ENOUGH DATA ON CARD
                  IPR(2) = 5
                  GO TO 200
                END IF
                PAR(100 + I) = FN(K + I)
              END DO
              IF (K /= 0) CALL PLA293 (FN(1))
              GO TO 10
C * IS = 31: CELL STANDARD DEVIATION (COPY)
            CASE (31)
              CALL GEN113 (FN, PAR(107), 6)
              GO TO 10
C * IS = 32: SYMM (LATT/SPGR/HALL etc.)
            CASE (32)
C * SYMM RECORDS AS (R|T)
              IF (IPR(220) == 1 .AND.
     1           (IPR(221) == 9 .OR. IPR(221) == 12)) THEN
C * SYMM MATRIX R11,R12,..,R33, (T1,T2,T3) INPUT
                IF (IPR(93) == 0) THEN
                  ITRS = 15
                  CALL SGSM (ITRS, ICL, FN,  0,  LU6, IERR)
                  CALL SGSM (18,   ICL, SGZ, 0,    0, IERR)
C * NO SUITABLE SPACE-GROUP
                  IPR(48) = NINT(SGZ(9))
C * CHECK FOR CIF-DATA
                  IF (IGBL(8) == 3) THEN
                    IF (CCIF(7)(1:1) == ' ' .AND.
     1                 CCIF(16)(1:1) == '?') THEN
C * ALERT _121
                      CALL PLA236 (121, 0, 1.0, 1.0, ICL(1:7), ' ')
                      ICL = 'SPGR P1'
                      WRITE (LU6, 99970, IOSTAT = IOST)
                      IS = 32
                      CYCLE
                    END IF
                  END IF
                ELSE
C * NO TRANS ALLOWED WITH SYMM MATRIX INPUT
                  IPR(2) = 27
                  GO TO 200
                END IF
              ELSE
C * OPTIONALLY ADD 'LATT 1' INSTRUCTION FOR COMPATIBILITY
                IF (IGBL(8) == 2) THEN
                  IF (IPR(141) == 0 .AND. IFL(1)(1:4) == 'SYMM')
     1              THEN
                    IDM = 'LATT 1'
                    CALL SGSM (0, IDM, SGY, 0, 0, IERR)
                    IPR(141) = 1
                  END IF
                END IF
C * CHECK FOR CELL TRANSFORMATION OR SHIFT
                IF (IPR(93) == 1 .OR. IPR(139) == 1) THEN
                  ITRS = 16
                ELSE
                  ITRS = 0
                END IF
                CALL SGSM (ITRS, ICL, SGY, 0, LU6, IERR)
                IF (IERR /= 0) THEN
C * PROBLEM WITH CELL TRANSFORMATION
                  IF (IERR == 14) THEN
                    IPR(2) = 66
                    GO TO 200
C * ERROR/PROBLEM IN HALL SYMBOL
                  ELSE IF (IERR == 7) THEN
C * ALERT _126
                    CALL PLA236 (126, 0, 1.0, 1.0, ICL(6:15), ' ')
                      IPR(673) = 1
                    GO TO 10
                  ELSE IF (IERR == 5) THEN
                    CALL GEN047 (ICL, 6, 16)
C * ALERT _129
                    CALL PLA236 (129, 0, 1.0, 1.0, ICL(6:12), ' ')
                    GO TO 10
                  ELSE IF (IERR == 12) THEN
                    GO TO 10
                  ELSE IF (IERR == 2) THEN
C * ALERT _119
                    CALL PLA236 (119, 0, 1.0, 1.0, ICL(6:12), ' ')
                    GO TO 10
                  ELSE
                    IPR(470) = 1
C * NOT ENOUGH DATA ON CARD
                    IPR(2) = 5
                    GO TO 200
                  END IF
                END IF
                CALL SGSM (18, ICL, SGZ, 0, 0, IERR)
                IPR(48) = NINT (SGZ(9))
                IF (IPR(48) == 0) THEN
C * CHECK FOR CIF-DATA
C * ALERT _121
                  IF (IGBL(8) == 3)
     1              CALL PLA236 (121, 0, 1.0, 1.0, ICL(1:7), ' ')
                END IF
              END IF
              IPR(141) = 1
C * HANDLE ERROR CASE
              IF (IPR(48) == 0) THEN
                IF (IGBL(5) == LU1) IPR(470) = 1
C * NOT ENOUGH DATA ON CARD
                IPR(2) = 5
                GO TO 200
              END IF
C * 'LAST-MINUTE SYMM UPDATE'
              IF (IPR(39) == 0) CALL PLA271
              GO TO 10
C * IS = 33: SPGR
            CASE (33)
C * CHECK FOR EXPLICIT SPACE GROUP INFO
              IF (IPR(220) /= 1 .OR. IPR(221) > 2) THEN
                IS = 32
C * DETERMINE SPACE GROUP FROM EXTINCTIONS
              ELSE
C * CHECK FOR REFLECTION DATA
                CALL PLA008
                IF (IGBL(15) >= 0) THEN
                  MODE = 3
                  IF (IPR(221) > 0) THEN
                    MODE = NINT (FN(1))
                    IF (IPR(221) > 1) PAR(141) = FN(2)
                  END IF
                  CALL PLA100
                  IGBL(31) = 5
C * OPEN UNIT #2
                  CALL PLA292
C * OUTPUT CELL HEADER
                  CALL PLA042 (0)
C * DETERMINE SPACEGROUP FROM EXTINCTIONS
                  CALL PLA160 (MODE, TM1)
C * ERROR HANDLING
                  IGBL(1) = 3
                  IF (IPR(3) /= 0) RETURN
                  GO TO 10
                ELSE
C * NO REFL DATA PROBLEM
                  IPR(2) = 55
                  GO TO 200
                END IF
              END IF
              CYCLE
C * IS = 34: LATT
            CASE (34)
C * SUBSTITUTE 'LATT 1' FOR 'LATT' AND 'LATT 0' IN CASE OF SHELX RES
              IF (IGBL(8) == 2) THEN
                IF (FN(1) == 0.0) ICL = 'LATT 1'
              END IF
              IS = 32
              CYCLE
C * IS = 35: DIST
            CASE (35)
              GO TO 30
C * IS = 36: ANGLE
            CASE (36)
              GO TO 30
C * IS = 37: TORSION
            CASE (37)
              GO TO 30
C * IS = 38: HBON: CHANGE H-BOND PARAMETERS FROM ORIGINAL TO NEW DEFAULTS
            CASE (38)
              IF (IPR(220) > 1 .AND. IFL(2)(1:4) == 'NORM') THEN
                IGBL(147) = 1
                IGBL(148) = 1
                IPR(87)   = 1
              ELSE
                IGBL(147) = 0
                IGBL(148) = 0
                IPR(87)   = 0
              END IF
              IF (IPR(221) > 0) THEN
                DO K = 1, IPR(221)
                  RGBL(40 + K) = FN(K)
                  RGBL(43 + K) = FN(K)
                END DO
              END IF
              GO TO 180
C * IS = 39,40: BIJ, SBIJ
            CASE (39, 40)
C * BIJ & SBIJ DATA
C * (BETA-VALUES ARE TRANSFORMED TO U-VALUES AFTER TRANSFORMATION)
              DO I = 1, 6
                FN(I) = FN(I) / RGBL(7)
              END DO
C * CHECK FOR SBIJ
              IF (IS == 40) THEN
                ICT = 3
                GO TO 50
              ELSE
                GO TO 40
              END IF
C * IS = 42: TRNS/TRMX
            CASE (42)
C * STANDARDISE ENTRIES
              CALL GEN074 (SHFT, 1, 3, 0.0)
C * MOVE/FIX ATOM CASE (accept both 3.456 and 3456.01)
              IF (IPR(221) == 1) THEN
                IF (ABS(FN(1)) > 1000.0) THEN
                  ITRNS = INT (FN(1))
                ELSE
                  ITRNS = NINT (FN(1) * 1000.0)
                END IF
C * TEST FOR SYMMETRY NUMBER IN RANGE
                IF (IABS(ITRNS) / 1000 > IPR(48)) THEN
                  IPR(2) = 15
                  GO TO 200
                END IF
                IF (ITRNS <= 0) THEN
                  IPR(95)  = ITRNS
                ELSE IF (ITRNS > 0) THEN
                  IPR(165) = ITRNS
                END IF
                GO TO 10
C * ORIGIN SHIFT ONLY
              ELSE IF (IPR(221) == 3) THEN
                CALL GEN074 (FN, 1, 9, 0.0)
                FN(1)    = 1.0
                FN(5)    = 1.0
                FN(9)    = 1.0
                IPR(139) = 1
                DO I = 1, 3
                  SHFT(I) = - FN(I)
                END DO
              ELSE IF (IPR(221) == 9) THEN
C * GET CRYSTAL SYSTEM
              ELSE IF (IPR(221) == 10 .AND. IPR(220) == 2) THEN
                ILAT0 = IFL(2)(1:1)
                IF (IFL(2)(2:2) /= ' ') ILAT1 = IFL(2)(2:2)
                CALL GEN020 (-1, ILAT0, 1, 1)
                IFN10 = NINT (FN(10))
                IF (IFN10 > 0 .AND. IFN10 < 14) THEN
                  LAUE = NLAUE(NINT(FN(10)))
                ELSE
                  LAUE = ' '
                END IF
C * TRANSLATION COMPONENT (ORIGIN SHIFT)
              ELSE IF (IPR(221) == 12) THEN
                IPR(139) = 1
                DO I = 1, 3
                  SHFT(I) = - FN(9 + I)
                END DO
C * INCORRECT NUMBER OF NUMERIC DATA ON TRMX LINE
              ELSE
                IPR(2) = 63
                GO TO 200
              END IF
C * TRANSFORMATION OF CELL AXES
              IF (IPR(39) > 0) THEN
C * INSTRUCTION NOT ALLOWED
                IPR(2) = 11
                GO TO 200
              END IF
              K = 0
              DO I = 1, 3
                SGY(9 + I) = - SHFT(I)
                DO J = 1, 3
                  K            = K + 1
                  TM1(I, J)    = FN(K)
                  SGY(K)       = FN(K)
C * TRANSFER TO SHELX-HKLF
                  PAR(230 + K) = FN(K)
                END DO
              END DO
C * CALCULATE TRANSPOSED INVERSE TM2 OF TM1
              CALL GEN003 (TM1, DUMV, DET, 0)
              IF (ABS(ABS(DET) - 1.0) > 0.001) THEN
                WRITE (LU6, 99985, IOSTAT = IOST) DET
                PAR(32) = DET
              END IF
              CALL GEN005 (DUMV, TM2)
              IPR(93) = 1
              WRITE (LU6, 99972, IOSTAT = IOST)
     1          ((TM2(I, J), J = 1, 3), SHFT(I), I = 1, 3)
              GO TO 10
C * IS = 44: PARENTHESES ON/OFF OPTION
            CASE (44)
              IPR(71) = 1
              IF (IPR(220) > 1) THEN
                IF (IFL(2)(2:2) == 'F') IPR(71) = 0
              END IF
              GO TO 180
C * IS = 46: SET OPTION(S)
            CASE (46)
C * SET - OPTION(S)
              OPT = IFL(2)(1:3)
C * (RE)SET VAN DER WAALS RADII
              IF (OPT == 'VDW') THEN
                IF (IPR(220) > 2 .AND. IPR(221) == IPR(220) - 2)
     1            THEN
                  DO I = 3, IPR(220)
                    CALL PLA037 (I, NID, 2)
                    IF (NID > 0) RADR(NID, 4) = FN(I - 2)
                  END DO
                END IF
                IF (IGBL(5) == LU5) CALL PLA280 ('LIST RADII')
C * SET RANGE (FOR POLY)
              ELSE IF (OPT == 'RAN') THEN
                IF (IPR(221) == 6) THEN
                  IPR(354) = 0
                  DO I = 1, 6
                    PAR(200 + I) = FN(I)
                  END DO
C * SET OMIT RANGE (POLY)
              ELSE IF (OPT == 'OMI') THEN
                ELSE IF (IPR(221) == 6) THEN
                  IPR(356) = 0
                  DO I = 1, 6
                    PAR(206 + I) = FN(I)
                  END DO
                END IF
C * SET TETR (POLY)
              ELSE IF (OPT == 'TET') THEN
                DO I = 1, 4
                 IF (FN(I) /= 0.0) PAR(213 + I) = FN(I)
                END DO
C * SET OCTA (POLY)
              ELSE IF (OPT == 'OCT') THEN
                DO I = 1, 4
                  IF (FN(I) /= 0.0) PAR(217 + I) = FN(I)
                END DO
C * SET LABEL SIZE
              ELSE IF (OPT == 'LAB') THEN
                IF (IPR(220) == 3 .AND. IFL(3)(1:1) == 'S') THEN
                  WRITE (LU6, 99994, IOSTAT = IOST) PAR(349)
                  IF (IPR(221) == 1) THEN
                    PAR(349) = FN(1)
                    WRITE (LU6, 99993, IOSTAT = IOST) PAR(349)
                  END IF
                END IF
C * SET PRINTER LEVEL (0,1,2,3,4)
              ELSE IF (OPT == 'PRI') THEN
                IF (IPR(220) == 3) THEN
C * LEVEL
                  IF (IFL(3)(1 : 1) == 'L') THEN
                    IF (IPR(221) > 0) THEN
                      IGBL(64) = NINT (FN(1))
                      IGBL(63) = IGBL(64)
                    END IF
                  END IF
                END IF
C * SET REVERSE (IGBL(68) = (0/1) REVERSE TOGGLE
              ELSE IF (OPT == 'REV') THEN
                IGBL(68) = MOD (IGBL(68) + 1, 2)
                CALL GGIP (-999.0, FLOAT (IGBL(68)), IGBL(62) * 0.25, 9)
C * SET IPR/PAR/IGBL/RGBL
              ELSE IF (IPR(221) == 2 .AND. IPR(220) == 2) THEN
                CALL PLA206 (1, OPT)
C * SET PROBABILITY (10 <--> 90 PERCENT)
              ELSE IF (IPR(221) == 1 .AND. IPR(220) == 2) THEN
                IF (OPT == 'PRO') THEN
                  IPR(45)  = MAX (1, MIN (9, NINT (FN(1) / 10)))
C * RESET LABEL POSITIONING STATUS
                  IPR(201) = 0
C * SET WINDOW FRACTION
                ELSE IF (OPT == 'WIN') THEN
                 CALL GGIP (-999.0, FLOAT (IGBL(68)), FN(1) * 1000.0, 9)
                 IGBL(62) = MIN (MAX (1, NINT (FN(1) / 0.25)), 4)
                END IF
              ELSE IF (IPR(220) == 3) THEN
                SELECT CASE (OPT)
C * SET BEEP ON/OFF
                  CASE ('BEE')
                    MEDIUM = 0
C * SET DISPLAY TYPE
                  CASE ('DIS')
                    MEDIUM = 1
C * SET META TYPE
                  CASE ('MET')
                    MEDIUM = 2
                END SELECT
                IF (IPR(220) > 2) CALL GGIP (-999.0, 0.0, 0.0, 6)
              END IF
              GO TO 180
C * IS = 48: SFAC CARD (SHELX) OR IS = 172: SCAT
            CASE (48, 172)
C * ADD 'LATT 1' FOR COMPATIBILITY
              IF (IPR(141) == 0 .AND. IGBL(8) == 2) THEN
                IDM = 'LATT 1'
                CALL SGSM (0, IDM, SGY, 0, 0, IERR)
                IPR(141) = 1
C * 'LAST-MINUTE SYMM UPDATE'
                CALL PLA271
              END IF
              M = IPR(221)
C * LOAD SFAC LABEL TYPE DATA INTO IEN
              IF (IPR(220) > 1) THEN
                DO I = 2, IPR(220)
                  NCHAR = 0
C * SEARCH FOR UPPERCASE CHARACTER ASCII NUMBER
                  CALL GEN105 (1, IFL(I)(1:1), N)
                  IF (N > 0) NCHAR = (N - ICHAR ('A') + 1) * 100
C * SEARCH FOR UPPERCASE CHARACTER ASCII NUMBER
                  CALL GEN105 (1, IFL(I)(2:2), N)
                  IF (N > 0) NCHAR = NCHAR + N - ICHAR ('A') + 1
C * REGISTER FOR ELEMENT 'HO'
                  IF (NCHAR == 815) IPR(435) = 1
                  IUNKNOWN = 1
                  DO J = 1, NP9
                    IF (IEL(J) == NCHAR) THEN
                      IAN          = IAN + 1
                      IEN(IAN)     = J
                      RADR(IAN, 3) = REL(J)
                      RADR(IAN, 4) = ABS (VDWR(J))
                      IF (IFL(I)(2:2) == ' ') THEN
                        LMT(IAN, 1) = ' '//IFL(I)(1:1)
                      ELSE
                        LMT(IAN, 1) = IFL(I)(1:2)
C * TRANSFORM 2nd CHAR to LOWERCASE
                        CALL GEN020 (-1, LMT(IAN, 1), 2, 2)
                      END IF
                      LMT(IAN, 2) = JTP(IABS (IATPR(J)))
C * ASSIGN COLORS FOR SHELX
                      IF (J == 3) THEN
                        IACL(IAN) = 2
                      ELSE IF (J == 4) THEN
                        IACL(IAN) = 4
                      ELSE IF (IATPR(J) == -7) THEN
                        IACL(IAN) = 3
                      ELSE IF (J > 2) THEN
                        IF (ICLR < 8) ICLR = ICLR + 1
                        IACL(IAN) = ICLR
                      END IF
                      IUNKNOWN = 0
                    END IF
                  END DO
C * CATCH UNKNOWN ELEMENT TYPE CASE
                  IF (IUNKNOWN == 1) THEN
                    IPR(2) = 41
                    GO TO 200
                  END IF
                END DO
C * CHECK FOR NEUTRON SCATTERING
                IF (IPR(220) == 2 .AND. IPR(221) > 0
     1            .AND. FN(1) == 0.0) IPR(493) = 7
              END IF
              GO TO 10
C * IS = 51: VIEW CARD(S)
            CASE (51)
C * VIEW MIN
              IF (IFL(2)(1:3) == 'MIN') THEN
C * RESET LABEL POSITIONING STATUS
                IPR(201) = 0
                IGBL(67) = 0
              ELSE
C * VIEW (XR xr YR yr ZR zr)
                N = 1
                IF (IPR(220) == 1) THEN
                  CALL PLA226 (0, 0.0)
                ELSE
C * GENERATE UNIT MATRIX (DET = IGBL(87))
                  CALL GEN021 (RMAT, FLOAT (IGBL(87)))
C * RECREATE ORIENTATION MATRIX
                  DO L = 1, 3
                    CALL GEN051 (0, RMAT, - RGBL(27 + L) / RGBL(6), L)
                  END DO
                  DO I = 2, IPR(220)
                    SELECT CASE (IFL(I)(1:3))
C * UNIT
                      CASE ('UNI')
                        CALL PLA226 (0, 0.0)
C * INVERT
                      CASE ('INV')
                        CALL PLA226 (-4, 0.0)
C * XROT
                      CASE ('XR ', 'XRO')
                        CALL PLA226 (-1, - FN(N) / RGBL(6))
                        N = N + 1
C * YROT
                      CASE ('YR ', 'YRO')
                        CALL PLA226 (-2, - FN(N) / RGBL(6))
                        N = N + 1
C * ZROT
                      CASE ('ZR', 'ZRO')
                        CALL PLA226 (-3, - FN(N) / RGBL(6))
                        N = N + 1
                    END SELECT
                  END DO
                END IF
              END IF
              GO TO 180
C * IS = 52: BOX ON/OFF (1/0)
            CASE (52)
              IF (IPR(220) > 1) THEN
                DO I = 2, IPR(220)
                  SELECT CASE (IFL(I)(1:3))
C * BOX OFF
                    CASE ('OFF')
                      IGBL(103) = 0
C * BOX ON
                    CASE ('ON ')
                      IGBL(103) = 1
C * BOX RATIO
                    CASE ('RAT')
                      PAR(50) = FN(1)
                  END SELECT
                END DO
              END IF
              GO TO 180
C * IS = 56: GEOM
            CASE (56)
              GO TO 30
C * IS = 59: INFO
            CASE (59)
              IS = 29
              CYCLE
C * IS = 60: TABLE OPTION
            CASE (60)
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
              IF (IPR(30) /= 0) THEN
                IPR(2) = 31
                GO TO 200
              END IF
              IPR(430) = 1
C * REPORT NO-ESD STATUS
              IF (IPR(72) == 0) WRITE (LU6, 99966, IOSTAT = IOST)
C * SET NHATOM
              IPR(454) = 1
C * SET RES
              IPR(240) = 1
C * SET PARENTHESES TO NO
              IPR(71) = 0
              IF (IPR(220) > 1) THEN
                DO I = 2, IPR(220)
                  SELECT CASE (IFL(I)(1:3))
C * NO-HATOM
                    CASE ('NHA')
                      IPR(454) = 0
C * RESIDUE SORT/LISTING (NORES)
                    CASE ('NOR')
                      IPR(240) = 0
                    CASE ('SUP')
C * SU  (FULL SUPPLEMENTARY MATERIAL)
                      IPR(431) = 1
                    CASE ('ACC', 'CIF')
C * ACC (ACTA CRYST C - CIF) - NOPARENTHESES
                      IPR(430) =  1
C * ACC-CIF
                      IPR(431) = -1
                      IGBL(31) = 8
C * LOCAL
                    CASE ('LOC')
                      IPR(399) = 1
                  END SELECT
                END DO
              END IF
C * DO A CALC OMEGA CALCULATION WHEN NECESSARY (NO = 0)
              IF (IPR(30) == 0) THEN
                IPR(220)  = 2
                IFL(2)    = 'OMEGA'
                GO TO 100
              ELSE
C * EXECUTE TABLE OPTIONS
                IF (IPR(430) > 0) THEN
                  IPR(31)  = -1
                  IPR(17)  = -1
                  IPR(90)  =  1
                  IGBL(63) =  0
C * SET UP CONNECTED SET
                  CALL PLA067
                  IF (IPR(2) /= 0) RETURN
                  CALL PLA571
                  IPR(1) = 1
                  IF (IPR(2) == 0) IPR(2) = -1
C * ERROR HANDLING
                  IGBL(1) = 3
                  RETURN
                END IF
                RETURN
              END IF
              GO TO 10
C * IS = 61: RADII BONDS ((LIST/NORMAL/TO H/TO MET/ALL) (#lines (radius)))
            CASE (61)
              JB = 0
              JE = 0
              DO I = 3, IPR(220)
                SELECT CASE (IFL(I)(1:3))
C * RADII BONDS TO H
                  CASE ('H  ')
                    JB = 3
                    JE = 3
C * RADII BONDS TO METAL
                  CASE ('MET')
                    JB = 5
                    JE = 5
C * NORMAL
                  CASE ('NOR')
                    JB = 1
                    JE = 1
                  CASE ('ALL')
                    JB = 1
                    JE = 5
                  CASE DEFAULT
                    CYCLE
                END SELECT
                DO J = JB, JE, 2
                  IF (IPR(221) > 0) THEN
                    IF (ABS (FN(1)) > 5.0) FN(1) = SIGN (5.0, FN(1))
                    PAR(84 + J) = FN(1)
                  END IF
                  IF (IPR(221) > 1) PAR(85 + J) = FN(2)
                END DO
                IF (.TRUE.) EXIT
              END DO
C * LIST BOND RADII
              WRITE (PRBUF, 99977, IOSTAT = IOST)
              IF (IWIN == 1) THEN
                CALL GGIP (HORS, VERT, 0.0, 1)
                VRT = VERT - 3.0
                CALL PLA439 (0.0, PRBUF, 75, 0.35, 5 + IGBL(68), 2,
     1             1.0, VRT)
              ELSE
                WRITE (LU6, 99991, IOSTAT = IOST) PRBUF(1:75)
              END IF
              WRITE (PRBUF, 99976, IOSTAT = IOST)
     1          NINT (PAR(85)), 2**NINT (ABS (PAR(85)) - 1) + 1, PAR(86)
              IF (IWIN == 1) THEN
                VRT = VRT - 1.5
                CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
              ELSE
                WRITE (LU6, 99991, IOSTAT = IOST) PRBUF(1:75)
              END IF
              WRITE (PRBUF, 99975, IOSTAT = IOST)
     1          NINT(PAR(87)), 2**NINT (ABS (PAR(87)) - 1) + 1, PAR(88)
              IF (IWIN == 1) THEN
                VRT = VRT - 1.5
                CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
              ELSE
                WRITE (LU6, 99981, IOSTAT = IOST) PRBUF(1:75)
              END IF
C * TEST FOR METAL CONTAINING COMPOUND
              IF (IPR(155) > 0) THEN
                WRITE (PRBUF, 99974, IOSTAT = IOST) NINT (PAR(89)),
     1            2**NINT (ABS (PAR(89)) - 1) + 1, PAR(90)
                IF (IWIN == 1) THEN
                  VRT = VRT - 1.5
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99981, IOSTAT = IOST) PRBUF(1:75)
                END IF
              END IF
              IF (IWIN == 1) CALL PLA297 (1)
              GO TO 180
C * IS = 63: MENU (ON/OFF)
            CASE (63)
              IF (IPR(220) == 2 .AND. IFL(2)(1:3) == 'OFF') THEN
                IGBL(25) = 0
              ELSE
                IGBL(25) = 1
                IF (IGBL(6) < 10 .OR. IGBL(6) > 12)
     1            CALL PLA280 ('PLOT')
              END IF
              GO TO 10
C * IS = 64: OMIT CARD
            CASE (64)
C * CHECK FOR QUOTE COMMENT
              IF (IGBL(8) == 2) IPR(220) = 1
              N = IPR(220)
              IF (N > 1) THEN
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
                IF (IPR(30) == 0) THEN
                  IF (IPR(37) == 0) THEN
                    IPR(2) = 42
                    GO TO 200
                  END IF
                  IGBL(52) = MAX (IGBL(52), IPR(23))
                  CALL PLA287 (0, 1, 0)
                END IF
                DO I = 2, N
                  CALL PLA046 (2, IFL(I), IENM, LBB, LBC, LBD,
     1                            INQNR, JNQNR, NR)
                  IF (NR > 0) THEN
                    CALL GEN048 (1, IFG(1, NR), 30, 1)
                  ELSE
                    WRITE (LU6, 99995) ICL(1:50)
                    CALL PLA015 (0, 28)
                  END IF
                END DO
              ELSE
                M = IPR(221)
C * SHELXL/RES THETA-MAX
                IF (M == 2) THEN
                  PAR(165) = FN(2) / 2.0
                  IGBL(8)  = 2
C * OMIT REFECTIONS + SYMMETRY RELATED ONE'S
                ELSE IF (M == 3) THEN
                  NSMR = IPR(255) * IPR(257)
                  IF (IPR(620) + NSMR  <= NP62) THEN
                    DO J = 1, NSMR
                      DO K = 1, 3
                        SGY(K) = FN(K)
                      END DO
                      CALL SGSM (5, IDM, SGY, J, 0, IERR)
                      IPR(620) = IPR(620) + 1
                      DO I = 1, 3
                        IHKLOMIT(I, IPR(620)) = NINT (SGY(I + 6))
                      END DO
C * AVOID DUPLICATIONS
                      IF (IPR(620) > 1) THEN
                        DO K = 1, IPR(620) - 1
                          IYUNK = 0
                          DO L = 1, 3
                            IYUNK = IYUNK
     1                            + IABS (IHKLOMIT(L, IPR(620))
     2                            -       IHKLOMIT(L, K))
                          END DO
                          IF (IYUNK == 0) THEN
                            IPR(620) = IPR(620) - 1
                            EXIT
                          END IF
                        END DO
                      END IF
                    END DO
                  END IF
                END IF
              END IF
              GO TO 10
C * IS = 67: JOIN ATOMS
            CASE (67)
              IPR(785) = 1
              CALL PLA021 (7, NRETURN)
              IF (NRETURN == 0) THEN
                RETURN
              ELSE IF (NRETURN == 1) THEN
                GO TO 10
              END IF
C * IS = 68: DETACH ATOMS
            CASE (68)
              IPR(785) = -1
              CALL PLA021 (7, NRETURN)
              IF (NRETURN == 0) THEN
                RETURN
              ELSE IF (NRETURN == 1) THEN
                GO TO 10
              END IF
C * IS = 69: DEFINE SUBSTITUTE BOND
            CASE (69)
              IPR(785) = -1
              CALL PLA021 (7, NRETURN)
              IF (NRETURN == 0) THEN
                RETURN
              ELSE IF (NRETURN == 1) THEN
                GO TO 10
              END IF
C * IS = 70: HKLF - LINE
            CASE (70)
              CALL PLA100
              IPR(648) = NINT (FN(1))
              PAR(573) = 1.0
              IF (IPR(221) >= 11) THEN
                DO K = 1, 9
                  I        = ((K - 1) / 3)  + 1
                  J        = MOD (K - 1, 3) + 1
                  QQ(I, J) = FN(K + 2)
                END DO
                IF (FN(12) /= 0.0 .AND. FN(12) /= 1.0) THEN
                  PAR(573) = FN(12)
                END IF
              ELSE
                CALL GEN021 (QQ, 1.0)
              END IF
C * APPLY TRNS/TRMX ON HKLF-TRNS
              CALL GEN004 (TM1, QQ, DUMV)
              K = 0
              DO I = 1, 3
                DO J = 1, 3
                  K = K + 1
                  PAR(230 + K) = DUMV(I, J)
                END DO
              END DO
              WRITE (LU6, 99968, IOSTAT = IOST) (PAR(230 + I), I = 1, 9)
C * GET INVERSE AND DETERMINANT  OF TRANSFORMATION MATRIX
              CALL GEN003 (DUMV, QQ, DET, 0)
              PAR(240) = DET
              IF (ABS (ABS (DET) - 1.0) > 0.001)
     1          WRITE (LU6, 99980, IOSTAT = IOST) DET
              IF (DET < 0.0) THEN
                IPR(2) = 40
                GO TO 200
              END IF
C * APPLY TRANSVERSE AXES TRANSFORMATION
              CALL GEN001 (1, QQ, AA, RAA)
C * GET TRANSFORMED DIRECT AXIS PARAMETERS
              CALL GEN026 (-1, RAA, PAR(241))
C * GET INVERSE TRANSFORMED METRIC
              CALL GEN003 (RAA, RBB, DET, 0)
C * CALL EXIT/STOP
              IF (DET <= 0.0)
     1         CALL GEN127 ('CANNOT INVERT METRICAL MATRIX')
C * GET TRANSFORMED RECIPROCAL AXIS PARAMETERS
              CALL GEN026 (-1, RBB, PAR(135))
              WRITE (LU6, 99969, IOSTAT = IOST) (PAR(100 + I), I = 1, 6)
     1                        ,(PAR(240 + I), I = 1, 6)
              CALL GEN025 (RBB, PAR(391), 1)
C * LOOK FOR REFLECTION DATA
              IF (NINT(FN(1)) == 4) CALL PLA008
              IF (NINT(FN(1)) == 5) CALL PLA008
              GO TO 10
C * IS = 71: RADN LINE
            CASE (71)
              CALL PLA293 (FN(1))
              GO TO 10
C * IS = 72: TRMX
            CASE (72)
              IS = 42
              CYCLE
C * IS = 74: INORG (FORCE INORGANIC MODE)
            CASE (74)
              IGBL(97) = 0
              GO TO 10
C * IS = 75: ORGA (FORCE ORGANIC MODE)
            CASE (75)
              IGBL(97) = 1
              GO TO 10
C * IS = 78: ENTRY (CSD/CIF ETC.-FILE ENTRY)
            CASE (78)
              CALL PLA007
              IF (ICL(1:4) == 'END ') GO TO 190
              GO TO 10
C * IS = 79: ELLIPSOID PARAMETERS
            CASE (79)
              IF (IPR(220) > 1) THEN
                SELECT CASE (IFL(2)(1:3))
                  CASE ('C  ')
                    N = 175
                  CASE ('H  ')
                    N = 177
                  CASE ('OTH')
                    N = 179
                END SELECT
                IF (IPR(221) > 1) THEN
                  IPR(N)     = MAX (0, MIN (1, NINT (ABS (FN(1)))))
                  IPR(N + 1) = NINT (ABS (FN(2)))
                END IF
              END IF
              WRITE (LU6, 99964, IOSTAT = IOST) (IPR(174 + I), I = 1, 6)
              GO TO 10
C * IS = 80: ORMA - CAD4 ORIENTATION MATRIX (Reciprocal Axes)
            CASE (80)
              IF (IPR(221) == 9) THEN
                DO I = 1, 9
                  PAR(180 + I) = FN(I)
                  J = MOD (I - 1, 3) + 1
                  K = ((I - 1) / 3)  + 1
                  DAM(J, K)    = FN(I)
                END DO
                CALL GEN003 (DAM, DUMV, DET, 0)
C * CALL EXIT/STOP
                IF (DET <= 0.0) CALL GEN127 ('CANNOT INVERT ORMA')
                WRITE (LU6, 99965, IOSTAT = IOST) 1.0 / DET
                IPR(16) = 1
              ELSE
C * NOT ENOUGH DATA ON CARD
                IPR(2) = 5
                GO TO 200
              END IF
              GO TO 10
C * IS = 82: SETUP (EXOR.BIN)
            CASE (82)
              IF (IABS (IGBL(8)) == 2) THEN
                CALL PLA151 (0)
                GO TO 210
              ELSE
                GO TO 10
              END IF
C * IS = 83: EXOR
            CASE (83)
              IF (IABS (IGBL(8)) == 2) THEN
                CALL PLA151 (1)
                GO TO 210
              ELSE
                GO TO 10
              END IF
C * IS = 84: ABSG(AUSS)
            CASE (84)
              IPR(78) = 2
              CALL PLA186
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 85: FACE CARD
            CASE (85)
C * TEST FOR DIST >= 0.0
              IF (FN(4) <= 0) THEN
                IPR(2) = 34
                GO TO 210
              END IF
C * TEST FOR PRE-OCCURRENCE
              IF (NFACES > 0) THEN
                DO I = 1, NFACES
                  DIFF = 0.0
                  DO J = 1, 3
                    DIFF = DIFF + ABS (PMILL(I, J) - FN(J))
                  END DO
                  IF (DIFF < 0.001) GO TO 10
                END DO
              END IF
              IPR(367) = IPR(367) + 1
              NFACES   = IPR(367)
              DO J = 1, 4
                PMILL(NFACES, J) = FN(J)
              END DO
              PMILL(NFACES, 5) = FN(4)
              GO TO 10
C * IS = 86: ABST(OMPA) (de MEULENAER-TOMPA)
            CASE (86)
              IPR(78) = 3
              CALL PLA186
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 87: ABSXTAL
            CASE (87)
              PAR(162) = FN(1)
              IPR(78)  = 1
              GO TO 70
C * IS = 88: LEPAGE METRICAL SYMMETRY ANALYSIS
            CASE (88)
              IPR(94) = 2
              IGBL(6) = 20
              IPR(2)  = -1
C * -L1 SWITCH OPTION
              IF (IGBL(3) == 52) THEN
                IPR(504) = 2
                PAR(441) = 0.01
                PAR(439) = 0.01
              ELSE
                IF (IPR(220) > 1) THEN
                  IF (IFL(2) == 'SHELX') IPR(504) = 2
                END IF
                IF (FN(1) /= 0.0) PAR(441) = FN(1)
                IF (FN(2) /= 0.0)
     1            IPR(94)  = MAX (2, MIN (10, NINT(FN(2))))
                IF (FN(3) /= 0.0) PAR(439) = FN(3)
              END IF
C * UNIT CELL CALCULATIONS
              CALL PLA100
C * GET SPACE GROUP INFO
              CALL SGSM (18, ICL, SGY, 0, 0, IERR)
C * CALL LEPAGE
              CALL PLA164 (0, 0, ICL(13:13), TM1, PAR(439), ' ')
              CALL GEN038 (ICL, 1, 80)
C * GET NEW INSTRUCTION
              RETURN
C * IS = 89: ASYM
            CASE (89)
              MODE = 0
              IF (PAR(168) > 0.0) THEN
C * ASYM VALID
                IF (IPR(220) > 1) THEN
                  IF (IFL(2)(1:5) == 'VALID') THEN
                    IFL(4) = IFL(2)
                    MODE   = 2
C * ASYM AVF VALID or ASYM VALID AVF => MODE = 2
                  ELSE IF (IPR(220) == 3) THEN
                    IF (IFL(2)(1:3) == 'AVF' .AND.
     1                  IFL(3)(1:5) == 'VALID') THEN
                      MODE = 2
                    ELSE IF (IFL(2)(1:5) == 'VALID' .AND.
     1                   IFL(3)(1:3) == 'AVF') THEN
                      MODE = 2
                    END IF
C * GET EXPECTED NUMBER OF REFLECTIONS
                  ELSE IF (IFL(2)(1:6) == 'EXPECT') THEN
                    MODE = 1
                  END IF
                END IF
              END IF
              IF (MODE == 3) THEN
                IGBL(22) = -1
                MODE     = 1
                CALL PLA145 (MODE)
                MODE = 3
                REWIND (UNIT = LU13, IOSTAT = IOST)
              END IF
              CALL PLA145 (MODE)
              IF (IPR(2) == 0) IPR(2) = -14
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 90: ABSPSI
            CASE (90)
              CALL PLA008
              IF (IGBL(37) == 0) THEN
                IPR(2)  = 56
C * ERROR HANDLING
                IGBL(1) = 3
                RETURN
              END IF
              PAGET   = 'ABSPSI'
              IPR(78) = 4
              GO TO 70
C * IS = 91: ABSSPHERE
            CASE (91)
              IPR(78) = -1
              GO TO 70
C * IS = 92: CONTOUR-PLOTS - OPTIONS IN PLA251 -
            CASE (92)
              CALL PLA250
              IF (IPR(2) /= 0) THEN
C * ERROR HANDLING
                IGBL(1) = 3
                RETURN
              END IF
              IF (IGGT(1:4) == 'EXIT') THEN
C * ERROR HANDLING
                IGBL(1) = 3
                RETURN
              END IF
              IF (IGBL(3) >= 19 .AND. IGBL(3) <= 22) THEN
C * ERROR HANDLING
                IGBL(1) = 3
                RETURN
              ELSE
C * RESTART
                IGBL(54) = IGBL(54) - 1
                CALL PLA280 ('RESTART')
              END IF
              GO TO 10
C * IS = 93: RESTART
            CASE (93)
              CALL GEN108 (LU1,  0)
              REWIND (UNIT = LU2, IOSTAT = IOST)
              IF (IOST /= 0) CALL GEN148 (LU2, 1)
              CALL GEN108 (LU20, 0)
              IF (IABS (IGBL(8)) == 3) IGBL(8) = 3
              WRITE (LU6, 99967, IOSTAT = IOST)
C * RESTART (FOR NEW) DATASET
              IGBL(1) = 1
              RETURN
C * IS = 94: VALIDATION CHECK MODE (FOR ACTA CRYST ETC)
            CASE (94)
C * CHECK MODE ON  (NOMOVE CASE)
              IF (IGBL(30) == 1) THEN
                IGBL(146) = 0
                IF (IPR(220) > 1) THEN
                  IF (IFL(2)(1:5) == 'TABSF') THEN
                    IGBL(146) = 0
                  ELSE IF (IFL(2)(1:5) == 'CIFSF') THEN
                    IGBL(146) = 1
                    WRITE (LU6, 99962) 'CIF'
                  ELSE IF (IFL(2)(1:5) == 'RESSF') THEN
                    IGBL(146) = 2
                    WRITE (LU6, 99962) 'RES'
                  END IF
                END IF
                IPR(220) = 1
C * SET FOR ATOM LABELS WITHOUT ()
                IPR(71)  = 0
C * SET IUCR CHECK MODE
                IGBL(36) = 1
                LINE = NAMEFIL(1:KNMFIL)//'.chk'
                WRITE (LU6, 99997, IOSTAT = IOST) LINE
C * PRINTER LEVEL 0
                IGBL(64) = 0
                IGBL(63) = IGBL(64)
C * VALIDATION DISPLAY ON
                IGBL(66) = 1
                IGBL(3)  = 1
                GO TO 100
              ELSE
                CALL PLA015 (0, 47)
                IGBL(3) = 0
              END IF
              GO TO 10
C * IS = 95: EXPT - CALCULATE EXPECTED NUMBER OF REFLECTIONS
            CASE (95)
              CALL PLA086 (LU6)
              CALL PLA086 (LU7)
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 96: PLUTON
            CASE (96)
C * PLUTON/PLOT - TEST FOR 'PLUTON' OR 'PLUTON/RENAME' SHORTCUT
              IF (IFL(2)(1:3) == 'NAT') IGBL(3) = 8
              IF (IGBL(3) == 8) THEN
                CALL PLUTON (-1)
C * TERMINATE JOB
                IGBL(1) = 4
                RETURN
              END IF
              IFL(2)   = IFL(1)
              IPR(220) = 2
              GO TO 80
C * IS = 146: HALL
            CASE (146)
