              CYCLE
C * IS = 148: MULABS
            CASE (148)
              CALL PLA008
              IF (IPR(220) > 1) THEN
                DO I = 2, IPR(220)
                  IF (IFL(I)(1:5) == 'LIST')    IGBL(57) = 1
                  IF (IFL(I)(1:7) == 'NOCHECK') IPR(363) = 0
                END DO
              END IF
              IF (IGBL(37) == 0) THEN
                IPR(2)  = 56
C * ERROR HANDLING
                IGBL(1) = 3
                RETURN
              END IF
              IPR(78) = -2
              CALL PLA100
              CALL PLA042 (1)
              PAGET = 'MULABS'
              CALL PLA190
              IF (IPR(2) == 0) IPR(2) = -4
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 149: HKLFTRANS
            CASE (149)
              IF (IABS(IGBL(8)) == 2) THEN
                CALL PLA042 (1)
                CALL PLA330
                IF (IPR(2) == 0) IPR(2) = -15
              ELSE
                IPR(2) = 72
              END IF
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 150: XTAL-HABIT PLOT
            CASE (150)
              IPR(78) = 0
              CALL PLA186
C * TERMINATE JOB
              IGBL(1) = 4
              RETURN
C * IS = 151: HINCLUDE (ORTEP)
            CASE (151)
              DO I = 2, IPR(220)
                CALL PLA046 (3, IFL(I), IENM, LBB, LBC, LBD,
     1                          INQNR, JNQNR, N1)
                CALL GEN048 (1, IFG(2, N1), 12, 1)
              END DO
              GO TO 180
C * IS = 152: HEXCLUDE (ORTEP)
            CASE (152)
              DO I = 2, IPR(220)
                CALL PLA046 (3, IFL(I), IENM, LBB, LBC, LBD,
     1                          INQNR, JNQNR, N1)
                CALL GEN048 (1, IFG(2, N1), 12, 0)
              END DO
              GO TO 180
C * IS = 153: FILE
            CASE (153)
              CALL PLA004 (1)
              IGBL(8)  = 0
              IGBL(19) = 1
