C * INIT & FILE OPEN
              IGBL(1) = -1
              RETURN
C * IS = 154: RENAME (RES)
            CASE (154)
              IF (IABS(IGBL(8)) == 2) THEN
C * SET PLUTON/RENAME
                IGBL(3)   = 12
C * SET DISPLAY ALL LABELS
                IGBL(105) = 1
