                IGBL(1) = 4
                RETURN
              ELSE
                CALL PLA015 (427, 40)
              END IF
              GO TO 10
C STRIP_BEG
C * IS = 155: SYSTEM S
            CASE (155)
              IGBL(3) = 14
              CLOSE (UNIT = LU1)
              CLOSE (UNIT = LU2)
              CLOSE (UNIT = LU3)
              CLOSE (UNIT = LU4)
              CLOSE (UNIT = LU8)
              CLOSE (UNIT = LU9)
              CLOSE (UNIT = LU16)
              CLOSE (UNIT = LU21)
              CLOSE (UNIT = LU22)
              CALL S
              RETURN
C STRIP_END
C * IS = 156: DELAUNEY REDUCTION
            CASE (156)
              IF (IPR(221) > 0) THEN
                PAR(382) = FN(1)
                IF (IPR(221) == 2) PAR(381) = FN(2)
              END IF
              CALL PLA100
C * GET SPACE GROUP INFO
              CALL SGSM (18, ICL, SGY, 0, 0, IERR)
              CALL PLA265 (ICL(13:13), LU7)
C * GET NEW INSTRUCTION
