              NOPT = -1
              CALL PLA405 (0, NOPT)
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 160: FCF2HKL
            CASE (160)
C * LU25 MIGHT BE OPEN DUE TO EMBEDDED HKL
              IF (IPR(664) /= 0) THEN
                CLOSE (LU25, STATUS = 'DELETE', IOSTAT = IOST)
                IPR(664) = 0
              END IF
              OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sx.hkl',
     1          STATUS = 'UNKNOWN', IOSTAT = IOST)
              CALL PLA139 (LU6, LU16, LU61, IPR(384))
              CLOSE (UNIT = LU61)
              IF (IPR(2) == 0) IPR(2) = -16
C * TERMINATE JOB
              IGBL(1) = 4
              RETURN
C * IS = 161: PORTRAIT
            CASE (161)
              IGBL(46) = MOD (IGBL(46) + 1, 2)
              PAR(50)  = (4.0 - IGBL(46)) / 3.0
              NN       = 4 - IGBL(46) * 8
              CALL GGIP (-999.0, 0.0, 0.0, NN)
              GO TO 10
C * IS = 162: SIMULATED POWDER-PATTERN
            CASE (162)
              CALL PLA113
C * TERMINATE JOB (-Q OPTION)
              IF (IGBL(3) == 31) IGBL(1) = 4
              RETURN
C * IS = 163: FSUM
            CASE (163)
              GO TO 10
C * IS = 164: SCAL
            CASE (164)
              IS = 1
              CYCLE
C * IS = 165: CRYS
            CASE (165)
              IS = 1
              CYCLE
C * IS = 166: TWINROTMAT
            CASE (166)
              CALL PLA405 (1, NOPT)
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 167: CAVITY
            CASE (167)
              PAR(571) = 0.025
              IF (IPR(221) > 0) THEN
C * OVERRULE MINIMUM CAVITY RADIUS DEFAULT (1.2)
                PAR(519) = MAX (0.3, FN(1))
                IF (IPR(221) > 1) PAR(520) = MAX (5.0, FN(2))
              END IF
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0) ==> SETUP CONNECTED SET
              IF (IPR(30) == 0) CALL PLA067
C * RUN CAVITY TOOL
              IF (IPR(2)  == 0) CALL PLA207
C * RESTART
              CALL PLA280 ('RESTART')
              GO TO 10
C * IS = 168: SHXABS
            CASE (168)
              IF (IPR(221) > 0) THEN
                PAR(417) = FN(1)
                IF (IPR(221) > 1) THEN
                  PAR(418) = FN(2)
                  IF (IPR(221) > 2) THEN
                    IYUNK = NINT (FN(3))
                    IF (IYUNK <= 8 .AND. MOD (IYUNK, 2) == 0) THEN
                      IPR(523) = IYUNK
                    END IF
                    IF (IPR(221) > 3) THEN
                      IYUNK = NINT (FN(4))
                      IF (IYUNK == 0 .OR.
     1                  (IYUNK < 8 .AND. MOD (IYUNK, 2) == 1)) THEN
                        IPR(524) = IYUNK
                      END IF
                    END IF
                  END IF
                END IF
              END IF
C * SHXABS
              CALL PLA202
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 169: DELETE ATOM (ORTEP/SOLV)
            CASE (169)
              N = IPR(220)
              IF (N > 1) THEN
                DO I = 2, N
                  CALL PLA046 (2, IFL(I), IENM, LBB, LBC, LBD,
     1                         INQNR, JNQNR, NR)
                  IF (NR > 0) THEN
                    CALL GEN048 (1, IFG(2, NR), 27, 1)
                  ELSE
                    CALL PLA015 (0, 28)
                  END IF
                END DO
              END IF
              GO TO 10
C * IS = 170: COLOR TYPE INSTRUCTION
            CASE (170)
              N = IPR(220)
              IF (MOD (N, 2) == 0 .AND. N >= 4) THEN
                DO I = 3, N, 2
                  IEXIT = 0
                  NQ1 = IFL(I)(1:2)
                  NQ2 = IFL(I + 1)(1:3)
                  IF (NQ1(2:2) == ' ') THEN
                    NQ1 = ' '//IFL(I)(1:1)
                  ELSE
                    CALL GEN020 (-1, NQ1, 2, 2)
                  END IF
                  DO J = 1, IAN
                    IF (NQ1(1:2) == LMT(J, 1)) THEN
                      DO K = 1, NP10 + 1
                        IF (NQ2(1:3) == COLR(K)(1:3)) THEN
                          IACL(J) = K
                          IEXIT   = 1
                          EXIT
                        END IF
                      END DO
                    END IF
                    IF (IEXIT /= 0) EXIT
                  END DO
                END DO
              END IF
              GO TO 10
C * IS = 171: RESET
            CASE (171)
              CALL PLA286 (0)
              GO TO 190
C * IS = 173: STIDY (Structure Tidy - Parthe & Gelato)
            CASE (173)
C * RUN STRUCTURE TIDY
              EXTENS1 = EXTENS
              CALL PLA301 (1)
              EXTENS = EXTENS1
              IF (IPR(2) == 0) IPR(2) = -1
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 174: BIJVOET PAIR ANALYSIS
            CASE (174)
C * SET DEFAULTS
C * GAUSSIAN PROBABILITY DISTRIBUTION
              IPR(613) = 0
C * NO PROBALILITY DISTRIBUTION CORRECTION
              IPR(593) = 0
C * NO RECYCLE-T
              IPR(617) = 0
C * Fo/Fc BASED ON CIF
              IPR(594) = 1
              PAR(488) = 0.0
              KN = IPR(221)
              IF (KN.GT. 0) THEN
                DO I = 1, IPR(221)
C * Gaussian/Student-t
                  IF (I == 1) THEN
                    IPR(613) = NINT (FN(1))
C * PP Slope Correction
                  ELSE IF (I == 2) THEN
                    IPR(593) = NINT (FN(2))
C * Recycle Student-t
                  ELSE IF (I == 3) THEN
                    IPR(617) = NINT (FN(3))
C * CIF/FCF Based Fcalc
                  ELSE IF (I == 4) THEN
                    IPR(594) = NINT (FN(4))
C * NU VALUE
                  ELSE IF (I == 5) THEN
                    PAR (488) = FN(5)
                  END IF
                END DO
              END IF
              CALL PLA405 (-1, NOPT)
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 175: FLIPPER (FLIP PATT / FLIP SHOW)
            CASE (175)
              IF (IGBL(80) /= 0) CALL PLA350
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 176: STRUCTURE?
            CASE (176)
              IF (IGBL(80) /= 0) CALL PLA350
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
C * IS = 178: STRAIN
            CASE (178)
              IF (CELAB(1, 1) > 0.0 .AND. TEMPAB(1) /= TEMPAB(2))
     1          THEN
C * DO AN ANALYSIS BASED ON HAZEN ET AL. OR DUNITZ ORTHOGONALIZATION RESP.
                DO I = 1, 2
                  MORT = 3 - I
                  CALL PLA284 (MORT, JID)
                END DO
              ELSE
                WRITE (LU6, 99971, IOSTAT = IOST)
              END IF
              IGBL(1) = 3
              RETURN
C * IS = 179: CELA (STRAIN)
            CASE (179)
              DO I = 1, 6
                CELAB(1, I) = FN(I)
              END DO
              TEMPAB(1) = FN(7)
              IPR(221)  = 6
              IS        = 30
              CYCLE
C * IS = 180: CELB (STRAIN)
            CASE (180)
              DO I = 1, 6
                CELAB(2, I) = FN(I)
              END DO
              TEMPAB(2) = FN(7)
              GO TO 10
C * IS = 181: CSUA (STRAIN)
            CASE (181)
              DO I = 1, 6
                VCAB(1, I) = FN(I)
              END DO
              ICV(1) = 1
              GO TO 10
C * IS = 182: CSUB (STRAIN)
            CASE (182)
              DO I = 1, 6
                VCAB(2, I) = FN(I)
              END DO
              ICV(2) = 1
              GO TO 10
C * IS = 183: CIF2SHELXL
            CASE (183)
              CALL PLA345
              IF (IPR(663) == -2 .OR. IPR(321) > 0) THEN
                IGBL(1) = 4
                RETURN
              END IF
              GO TO 10
C * IS = 184: NOEXPAND
            CASE (184)
              IGBL(136) = 1
              IPR(129)  = 1
              IGBL(30)  = 1
