              CALL PLA428
              IF (IGBL(110) > 0) CALL PLA131 (NINT (FN(1)))
              RETURN
C * IS = 202: ADDSYM (EXPANDED TO CALC ADDSYM)
            CASE (202)
              DO I = IPR(220), 1, -1
                IFL(I + 1) = IFL(I)
              END DO
              IFL(1)   = 'CALC'
              IPR(220) = IPR(220) + 1
              IS       = 18
              CYCLE
C * IS = 203: NEWSYM (EXPANDED TO CALC NEWSYM)
            CASE (203)
              DO I = IPR(220), 1, -1
                IFL(I + 1) = IFL(I)
              END DO
              IFL(1)   = 'CALC'
              IPR(220) = IPR(220) + 1
              IS       = 18
              CYCLE
C * IS = 204: SQUEEZE (EXPANDED TO CALC SQUEEZE)
            CASE (204)
              DO I = IPR(220), 1, -1
                IFL(I + 1) = IFL(I)
              END DO
              IFL(1)   = 'CALC'
