C * IS = 218: CIP (R/S)
            CASE (218)
              IF (IPR(221) /= 0) IPR(492) = MIN (NINT (FN(1)), 10)
              IFL(1) = 'CALC'
              IFL(2) = 'GEOM'
C * R/S OUTPUT DEFAULT
              IPR(777) = 1
              IPR(220) = 2
              IPR(221) = 0
              IS       = 18
              CYCLE
C * IS = 220: DIEDERICHS PLOT
            CASE (220)
              IGBL(66) = 1
              NOPT = 2
              CALL PLA405 (0, NOPT)
C * ERROR HANDLING
              IGBL(1) = 3
              RETURN
            CASE DEFAULT
              GO TO 10
          END SELECT
        END DO
        GO TO 10
C * TEST FOR TOO MANY SPECIFIED ATOMS
   20   IF (IPR(220) > NP1 + 1) THEN
          IPR(2) = 8
          GO TO 200
        END IF
        IF (NTYP == 4) THEN
          IF (IPR(30) == 0) THEN
            DO I = 2, IPR(220)
C * SET UP CONNECTED SET
              IF (IFL(I)(1:4) == 'DIST') CALL PLA067
            END DO
          END IF
        END IF
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
        IF (IPR(30) == 0) THEN
          NRET = 1
          CALL PLA390 (1, NTYP, NRET)
          IF (NRET == 1) THEN
            GO TO 10
          ELSE IF (NRET == 2) THEN
            GO TO 30
          ELSE IF (NRET == 3) THEN
            GO TO 200
          END IF
C * PREVIOUS GEOM CALCULATION CASE
        ELSE
          IF (NTYP == 4) THEN
            IPR(81) = - IPR(220)
C * INTERACTIVE CALCULATION
            CALL PLA440 (1)
            GO TO 10
          END IF
        END IF
        IPR(220) = - IPR(220)
C * SINGLE DISTANCE, ANGLE OR TORSION ANGLE CALCULATION (+GEOM)
C * ALSO: ANGLE BETWEEN TWO CRYSTAL PLANES
   30   IF (IPR(220) == 1) THEN
          IF (IPR(221) == 6) THEN
            CALL PLA100
            ANG = 180.0 - GEN016 (FN(1), RBB, FN(4))
            WRITE (PRBUF, 99996, IOSTAT = IOST) (NINT (FN(I)), I = 1, 6)
     1        , ANG
            WRITE (LU6, 99981, IOSTAT = IOST) PRBUF(1:50)
            SBCD = PRBUF(1:50)//CHAR (0)
            GO TO 10
          ELSE
C * NOT ENOUGH DATA ON CARD
            IPR(2) = 5
            GO TO 200
          END IF
        ELSE IF (IFL(1)(1:3) == 'FIT' .OR. IPR(220) == -1 .OR.
     1          (IPR(220) > 1 .AND. IPR(220) < 6)) THEN
          IPR(1)  = 7
          IPR(81) = IPR(220)
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
          IF (IPR(30) == 0) THEN
            IGBL(52) = MAX (IGBL(52), IPR(23))
            IPR(205) = 0
          END IF
          CALL PLA021 (11, NRETURN)
          RETURN
        ELSE
C * NOT ENOUGH DATA ON CARD
          IPR(2) = 5
          GO TO 200
        END IF
C * CHECK FOR # OF VALUES IN CIF-MODE
   40   IF (IGBL(8) == 3) THEN
          IF (IFL(2)(1:1) == '?') GO TO 10
          IF (IPR(221) /= 12 .OR.
     1        (FN(2) == 0.0 .AND. FN(3) == 0.0 .AND. FN(4) == 0
     2        .AND. FN(5) == 0 .AND. FN(6) == 0)) THEN
            IF (IPR(221) /= 0) THEN
              IF (IGBL(3) == 1) THEN
C * ALERT _217
                CALL PLA236 (217, 0, 1.0, 1.0, IFL(2), ' ')
              ELSE
                IPR(2) = 50
                GO TO 200
              END IF
            ELSE
              GO TO 10
            END IF
          END IF
        END IF
C * LOAD U-MATRIX(6 TO 9 COMPONENTS)
        CALL GEN025 (DUMV, FN, -1)
C * CALCULATE TM2 * UIJ * TR(TM2)
        CALL GEN001 (1, TM2, DUMV, UIJ)
C * EXTRACT FROM TRANSFORMED U-MATRIX (9 TO 6 COMPONENTS)
        CALL GEN025 (UIJ, FN, 1)
        ICT     = 2
        IPR(32) = 2
C * SUIJ DATA
   50   IF (PAR(113) /= 0.0) CALL GEN144 (-1, FN(1), PAR(113))
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
   60   IF (IPR(30) == 1 .OR. IPR(107) == 1) THEN
          IPR(471) = IPR(471) + 1
          IF (IGBL(5) /= LU5) GO TO 10
C * UNKNOWN CARD ERROR
          IPR(2) = 7
          GO TO 200
        ELSE
          NQ2 = IFL(2)
          IF (IGBL(8) == 1) THEN
            IF (NQ4 /= NQ2) THEN
C * LABEL INCONSISTENT
              IPR(2) = 4
              GO TO 200
            END IF
            INQNR2 = INQNR
          ELSE
            MODE = 0
            CALL PLA046 (-2, NQ2, IENM, LBB, LBC, LBD,
     1                       INQNR2, JNQNR2, IDUM2)
          END IF
C * REGISTER (AN)ISO PARAMETER INPUT
          IPR(32) = MAX (IPR(32), 1)
          WRITE (LU4) ICT, INQNR2, (FN(K), K = 1, 8)
C * HANDLE CIF-FILE INPUT
          IF (IGBL(8) == 3) THEN
            IF (IS == 25) THEN
              IS = 26
              DO I = 1, 6
                FN(I) = FN(I + 6)
              END DO
C * UIJ DATA & SUIJ DATA
C * INCLUDE A*,B* AND C* INTO U(I, J) BEFORE TRANSFORMATION
              CALL GEN144 (1, FN(1), PAR(135))
C * CHECK FOR SUIJ
              IF (IS == 26) THEN
                ICT = 3
                GO TO 50
              END IF
              GO TO 40
            END IF
          END IF
          GO TO 10
        END IF
   70   CONTINUE
        CALL PLA186
        IF (IPR(2) == 0) THEN
          SELECT CASE (IPR(78))
            CASE (-1)
              IPR(2) = -5
            CASE (1)
              IPR(2) = -1
            CASE (2)
              IPR(2) = -8
            CASE (3)
              IPR(2) = -7
            CASE (4)
              IPR(2) = -6
          END SELECT
        END IF
C * ERROR HANDLING
        IGBL(1) = 3
        RETURN
C * PLOT INSTRUCTION CARD
C * IPR(14) =  0 : NO PLOTTING
C * IPR(14) = -1 : IPR(55) = -1 NEWMAN
C *              :         =  0
C *              :         =  1 : PLAN
C *              :         =  2 : RING
C *              :         =  3 : RESD
C *              :         =  4 : LSPL
C *         =  4 : ORTEP
C *         =  5 : POLYHEDRA PLOT
C *         =  6 : PLUTON
C * SET GOTO SWITCH
   80   IPR(1)   = 5
        IPR(56)  = 0
        IPR(112) = 0
        IPR(205) = 0
        N        = 1
        K0       = 0
C * SAVE OPTION TEST
        IF (IGBL(45) > 0 .AND. IGBL(5) == LU5) THEN
          IGBL(45) = IGBL(45) + 1
          WRITE (LU3, 99984, IOSTAT = IOST) ICL(1:80)
          WRITE (LU6, 99973, IOSTAT = IOST) ICL(1:70)
        END IF
C * MAKE PLOT ADP DEFAULT FOR 'PLOT-AT-START' INSTRUCTION
        IF ((IPR(14) == 0  .OR. IPR(14) == 4) .AND.
     1       IPR(220) == 1) THEN
C * SET TO PLOT ORTEP AS DEFAULT
          IGBL(3)  = 3
          IPR(220) = 2
          IFL(2)   = 'ADP'
          IF (IPR(346) == 1) THEN
            IPR(220)      = IPR(220) + 1
            IFL(IPR(220)) = 'COLOR'
          END IF
        END IF
        IF (IPR(220) > 1) THEN
          DO I = 2, IPR(220)
            SELECT CASE (IFL(I)(1:4))
              CASE ('RING')
                IPR(55) = 2
                IPR(14) = -1
              CASE ('PLAN')
                IPR(55) = 1
                IPR(14) = -1
              CASE ('RESD')
                IF (IPR(14) > 0) THEN
                  K0 = K0 + 1
                  IF (K0 <= IPR(221)) IPR(140) = NINT (FN(K0))
C * RESET LABEL POSITIONING STATUS
                  IPR(201) = 0
                ELSE
                  IPR(55) = 3
                  IPR(14) = -1
                END IF
              CASE ('LSPL')
                IPR(55) = 4
                IPR(14) = -1
C * DISPLAY ON
              CASE ('DISP')
                CALL GGIP (-999.0, 0.0, 0.0, -3)
                CALL GGIP (-999.0, 0.0, 0.0, 2)
C * META ON
              CASE ('META')
                CALL GGIP (-999.0, 0.0, 0.0, -2)
              CASE ('NEWM')
                IPR(30)  =  0
                IPR(55)  = -1
                IPR(14)  = -1
                IPR(169) = 0
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
                IF (IPR(30) /= 0) CALL GEN108 (LU8, 0)
                IPR(162) = 0
              CASE ('PERP')
                IPR(56) = 0
              CASE ('ALON')
                IPR(56) = 1
              CASE ('ADP ', 'ORTE', 'TME ')
                IPR(14) = 4
                IF (IGBL(3) /= 28) IGBL(3) = 3
                IPR(18) = 0
                IGBL(6) = 1
              CASE ('CIP ')
                IPR(324) = 1
                IPR(18)  = 1
              CASE ('POLY')
                IPR(14) = 5
C * PLUTON (AUTO)
              CASE ('PLUT')
                IPR(14) = 6
              CASE ('HATO')
                IPR(212) = 1
              CASE ('NOHA')
                IPR(212) = 0
              CASE ('LABE')
                IGBL(75) = 1
              CASE ('NOLA')
                IGBL(75) = 0
              CASE ('ENVE')
                IPR(211) = 1
              CASE ('HETE')
                IPR(211) = 0
              CASE ('OCTA')
                IPR(211) = 2
              CASE ('PARE')
                IPR(350) = 1
              CASE ('NOPA')
                IPR(350) = 0
              CASE ('MARG')
                IF (K0 < IPR(221))  THEN
                  K0 = K0 + 1
                  PAR(44) = FN(K0)
                END IF
              CASE ('TAPE')
                IF (K0 < IPR(221))  THEN
                  K0 = K0 + 1
                  PAR(48) = FN(K0)
                END IF
              CASE ('NET ')
                IPR(112) = 1
              CASE ('MONO')
                IPR(116) = 0
              CASE ('STER')
                IPR(116) = 1
              CASE ('COLO')
                IPR(346) = 1
              CASE DEFAULT
                CALL PLA037 (I, L, 2)
                IF (IPR(2) == 0) THEN
                  IF (L < 0)
     1              IPR(162)  = IPR(162) * (NP1 + 1) + IABS (L)
                ELSE
                  IPR(2) = 0
                  WRITE (LU6, 99986, IOSTAT = IOST) IFL(I)
                END IF
            END SELECT
          END DO
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
          IF (IPR(30) == 0) THEN
            IPR(220) = 2
            IF (IPR(14) < 0) THEN
              WRITE (LU6, 99983, IOSTAT = IOST)
            ELSE
              WRITE (LU6, 99982, IOSTAT = IOST)
            END IF
            GO TO 110
          ELSE
            IF (IPR(14) > 0) GO TO 210
C * TEST FOR CALC INTRA AS PREVIOUS INSTRUCTION
            IF (IPR(136) /= 1) THEN
C * MISPLACED PLOT INSTRUCTION
              IPR(2) = 12
              GO TO 200
            END IF
          END IF
          IF (IPR(86) == 0) GO TO 10
        ELSE
          IF (IPR(14) == 0) THEN
C * NOT ENOUGH DATA ON CARD
            IPR(2) = 5
            GO TO 200
          END IF
        END IF
        GO TO 210
C * CALC CONTROL CARD FOR PLA067. THE SUB-KEYWORDS ARE:
