      L = 1
C * HANDLE CALC (ALL) CASE
C * (= ADDSYM, INTRA, INTER, COORDN, METAL, SOLV, (ASYM))
      IF (IPR(220) == 1) THEN
  125   SELECT CASE (IPR(121))
C * GET AVERAGE HKL MULTIPLICITY AND MERGED HKL LISTING
          CASE (9)
