        END SELECT
      END IF
C * SUB-KEYWORDS LOOP
      IF (IPR(221) > 0) PAR(262) = 0.0
      IPR(121) = 1
  130 L        = L + 1
      IF (L <= IPR(220)) THEN
        DO ISS = 1, NP22
          NQ1 = IFL(L)(1:7)
          IF (NQ1(1:4) == ISWSS(ISS)) THEN
            SELECT CASE (ISS)
C * ISS = 1: GEOM
              CASE (1)
