                END IF
                IPR(5)  = -1
                IF (IPR(221) > 0) THEN
                  PAR(34) = FN(1)
                  IF (IPR(221) > 1) IPR(21) = NINT (FN(2))
                END IF
                IF (IPR(220) > 2 .AND. IFL(3)(1:3) == 'CAR')
     1            IPR(347) = 1
