      INTEGER :: ISUGL
      INTEGER :: ISUGR
      INTEGER :: ISANG
      INTEGER :: IPPAR
      INTEGER :: IBPAR
      INTEGER :: NRING
      INTEGER :: NHEAD
      INTEGER, DIMENSION(NP5) :: NQ
      INTEGER, DIMENSION(NP5) :: KQ
      INTEGER, DIMENSION(NP5) :: KZP
      INTEGER, DIMENSION(NP5) :: KTRA
      INTEGER, DIMENSION(NP5) :: KPHI
      INTEGER, DIMENSION(NP5) :: NPHI
      INTEGER, DIMENSION(NP5) :: KRBO
      INTEGER, DIMENSION(NP5) :: NTRA
      INTEGER, DIMENSION(NP5) :: NRBO
      INTEGER, DIMENSION(NP5) :: NRANG
      INTEGER, DIMENSION(NP5) :: KDCSV
      INTEGER, DIMENSION(NP5) :: KDCSB
      INTEGER, DIMENSION(NP5) :: KDC2V
      INTEGER, DIMENSION(NP5) :: KDC2B
      INTEGER, DIMENSION(NP5) :: KRANG
      REAL :: A
      REAL :: D
      REAL :: BQ
      REAL :: CQ
      REAL :: QC
      REAL :: QS
      REAL :: TH
      REAL :: SX
      REAL :: SQ
      REAL :: SD
      REAL :: SBQ
      REAL :: SWT
      REAL :: QQN
      REAL :: QN2
      REAL :: AAZ
      REAL :: ANG
      REAL :: BAV
      REAL :: WBO
      REAL :: TAU
      REAL :: STH
      REAL :: SANG
      REAL :: TAUK
      REAL :: TAUM
      REAL :: TRA0
      REAL :: TRA1
      REAL :: TRA2
      REAL :: QQN2
      REAL :: PPAR
      REAL :: COSF
      REAL :: ATRA
      REAL :: DIFF
      REAL :: BAVK
      REAL :: CSTH
      REAL :: WTAU
      REAL :: YUNK
      REAL :: SZP0
      REAL :: SZP2
      REAL :: SRBO
      REAL :: SNTH
      REAL :: SINF
      REAL :: SIGJ
      REAL :: STWT
      REAL :: RMXMN
      REAL :: RBOMN
      REAL :: RBOMX
      REAL :: SIGAK
      REAL :: SIGBK
      REAL :: SINNF
      REAL :: SPPAR
      REAL :: SRANG
      REAL :: STAUM
      REAL :: STRA0
      REAL :: STRA1
      REAL :: STRA2
      REAL :: YUNK1
      REAL :: ZP0M2
      REAL :: Z0P2S
      REAL :: Z0M2S
      REAL :: ZP0P2
      REAL :: T0M2S
      REAL :: T0P2S
      REAL :: T1M2S
      REAL :: T1P2S
      REAL :: COSNF
      REAL :: ATERM
      REAL :: BTERM
      REAL :: BAVDIF
      REAL :: BAVEXP
      REAL :: SMSIGJ
      REAL, DIMENSION(NP5)    :: Q
      REAL, DIMENSION(NP5)    :: ZP
      REAL, DIMENSION(NP5)    :: FC2
      REAL, DIMENSION(NP5)    :: PHI
      REAL, DIMENSION(NP5)    :: SSQ
      REAL, DIMENSION(NP5)    :: TRA
      REAL, DIMENSION(NP5)    :: RBO
      REAL, DIMENSION(NP5)    :: FCS
      REAL, DIMENSION(NP5)    :: HFCS
      REAL, DIMENSION(NP5)    :: HFC2
      REAL, DIMENSION(3)      :: XYZD
      REAL, DIMENSION(NP5)    :: SPHI
      REAL, DIMENSION(NP5)    :: DCSV
      REAL, DIMENSION(NP5)    :: DCSB
      REAL, DIMENSION(NP5)    :: DC2V
      REAL, DIMENSION(NP5)    :: DC2B
      REAL, DIMENSION(NP5)    :: STRA
      REAL, DIMENSION(NP5, 4) :: XYZR
      REAL, DIMENSION(NP5)    :: RANG
      REAL, DIMENSION(NP5)    :: HDCSV
      REAL, DIMENSION(NP5)    :: HDC2V
      REAL, DIMENSION(NP5)    :: HDCSB
      REAL, DIMENSION(NP5)    :: HDC2B
      REAL, DIMENSION(3)      :: XYZDD
      CHARACTER(len=2)   :: KDES
      CHARACTER(len=5)   :: TXT1
      CHARACTER(len=5)   :: TXT2
      CHARACTER(len=1)   :: ACONF
      CHARACTER(len=158) :: FORMA
      CHARACTER(len=158) :: FORMB
      CHARACTER(len=158) :: FORMC
      CHARACTER(len=158) :: FORMD
      CHARACTER(len=158) :: FORME
      CHARACTER(len=158) :: FORMF
      CHARACTER(len=158) :: FORMG
      CHARACTER(len=158) :: FORMH
      CHARACTER(len=56)  :: FORMI
      CHARACTER(len=73)  :: FORMK
      CHARACTER(len=37)  :: FORML
      CHARACTER(len=106) :: FORMP
      CHARACTER(len=63)  :: FORMQ
      CHARACTER(len=54)  :: FORMX
      CHARACTER(len=3)   :: CHYB
      IF (MODE /= 0) THEN
        CALL GGIP (HORS, VERT, 0.0, 1)
        VRT = VERT
      END IF
      NRAT  = IPR(12)
      NMAX  = IPR(39)
      RBOMN = 1000.0
      RBOMX = 0.0
      D     = 0.0
      SD    = 0.0
      SANG  = 0.0
      SRANG = 0.0
      SRBO  = 0.0
      ANG   = 0.0
      NDEC  = 0
      ISANG = 0
      ISD   = 0
      ION2  = 0
      ION5  = 0
      N     = 0
      IC2   = 0
      ATERM = 0.0
      BTERM = 0.0
      SIGAK = 0.0
      SIGBK = 0.0
      FORMA(1:30)   = '(''Dev (A) from CPplane'',      '
      FORMA(31:46)  = 'F8.4,''('',I3,'')'','
      FORMA(47:94)  = FORMA(31:46)//FORMA(31:46)//FORMA(31:46)
      FORMA(95:158) = FORMA(47:94)//'F8.4,''('',I3,'')'')'
      FORMB(1:30)   = '( ''Cs(I)-Asym-Par (Deg)'',     '
      FORMB(31:158) = FORMA(31:158)
      FORMC(1:30)   = '( ''C2(I)-Asym-Par (Deg)'',     '
      FORMC(31:158) = FORMA(31:158)
      FORMD(1:30)   = '( ''Ring Bond Angle(Deg)'',     '
      FORMD(31:158) = FORMA(31:158)
      FORME(1:30)   = '( ''Tors(I-J) (Deg)'',10X,      '
      FORME(31:158) = FORMA(31:158)
      FORMF(1:30)   = '( ''Cs(I-J)-Asym-Par   (Deg) '','
      FORMF(31:158) = FORMA(31:158)
      FORMG(1:30)   = '( ''C2(I-J)-Asym-Par   (Deg) '','
      FORMG(31:158) = FORMA(31:158)
      FORMH(1:30)   = '( ''Ring Bond Distance (Ang) '','
      FORMH(31:158) = FORMA(31:158)
      FORMI(1:34)   = '(   A,'' - '',A,F10.4,''('',I3,'')'',5X,'
      FORMI(35:56)  = 'F10.2,''('',I3,'')'',2X,A)'
      FORMK( 1:28)  = '(''Q('',I1,'')  ='',F9.4,''('',I5,'
      FORMK(29:58)  = ''') Ang.,  Phi('',I1,'') ='',F8.2,'
      FORMK(59:73)  = '''('',I5,'') Deg'')'
      FORML( 1:37)  = FORMK(1:35)//''')'
      FORMP( 1:34)  = '(''Puckering Amplitude (Q) ='',F8.4,'
      FORMP(35:63)  = '''('',I5,'') Ang, Theta ='',F8.2,'
      FORMP(64:91)  = '''('',I5,'') Deg,  Phi ='',F8.2,'
      FORMP(92:106) = '''('',I5,'') Deg'')'
      FORMQ(1 :38)  = '(''Angle between '',3A,'' and '',3A,'' = '','
      FORMQ(39:63)  = 'F10.0,''('',I3,'')'','' deg.'')'
      FORMX(1:38)   = '(''Total Puckering Amplitude Q ='',F8.4,'
      FORMX(39:54)   ='''('',I5,'') Ang.'')'
C * RECALCULATE LSPL THROUGH RING WITH ESD'S.
      CALL PLA055
      KRC = NMAX + IPR(64) + 1
C * ??? STORE POINTER TO LSPL-DATA IN IATP(KRC)
      IATP(KRC) = NRING
      DO K = 1, 3
        XXO(KRC, K)     = 0.0
        XXO(KRC, K + 3) = 0.0
        XSD(KRC, K)     = 0.0
        XSD(KRC, K + 3) = 0.0
        XYZD(K)         = 0.0
        XYZDD(K)        = 0.0
      END DO
C * LOOK FOR / ANALYSE FURANOSE RING
      ISUGR  = 0
      IF (NRAT == 5) THEN
        DO J = 1, NRAT
          CALL GEN048 (-4, IFG(1, JR(J)), 15, JDUM)
          JDUM = IEN(JDUM + 1)
          IF (JDUM == 2) THEN
            ISUGR = ISUGR + 1
          ELSE IF (JDUM == 3) THEN
            ISUGR = ISUGR + 100
          END IF
        END DO
        IF (ISUGR == 104) THEN
          KYUNK = 0
          ISUGL = 2
          DO
            ISUGL = ISUGL - 1
            IF (ISUGL < 0) THEN
              ISUGR = 0
              EXIT
            END IF
            IC2  = 0
            ION2 = 0
            J2   = JR(2)
            NC   = - NINT (CON(J2, 9))
            IF (NC < 0) NC = 9
            IF (NC <= 3) THEN
              ISUGR = 0
              EXIT
            END IF
            DO K = 1, NC
              M = NINT (CON(J2, K))
              IF (M /= JR(1) .AND. M /= JR(3)) THEN
                CALL GEN048 (-4, IFG(1, M), 15, JDUM)
                JDUM = IEN(JDUM + 1)
                IF (JDUM == 3 .OR. JDUM == 4) THEN
                  ION2 = 1
                END IF
                IF (JDUM == 2) IC2 = 1
              END IF
            END DO
            ION5 = 0
            J5   = JR(5)
            NC = - NINT (CON(J5, 9))
            IF (NC < 0) NC = 9
            IF (NC <= 3) THEN
              ISUGR = 0
              EXIT
            END IF
            DO K = 1, NC
              M = NINT (CON(J5, K))
              IF (M /= JR(1) .AND. M /= JR(4)) THEN
                CALL GEN048 (-4, IFG(1, M), 15, JDUM)
                JDUM = IEN(JDUM + 1)
                IF (JDUM == 3 .OR. JDUM == 4) ION5 = 1
                IF (JDUM == 2) THEN
C * DETERMINE D/L CONFIGURATIE
                  ACONF = 'L'
                  CALL PLA053 (M, JR(5), JR(1), JR(2),
     1                ANG, SANG, ISANG, NDEC, IER)
                  IF (IER == 0 .AND. ANG > 0.0) ACONF = 'D'
                END IF
              END IF
            END DO
            IF (ION5 == 1) THEN
              CALL GEN014 (JR(2), JR(5))
              CALL GEN014 (JR(3), JR(4))
              CYCLE
            END IF
            IF (KYUNK == 0) EXIT
          END DO
        END IF
      END IF
      BAV    = 0.0
      BAVK   = 0.0
      SWT    = 0.0
      TAU    = 0.0
      TAUK   = 0.0
      STWT   = 0.0
      SMSIGJ = 0.0
      NCARB  = 0
      NHAT = 0
      DO J = 1, NRAT
        I    = JR(J)
C * COUNT # CARBON ATOMS IN RING
        CALL GEN048 (-4, IFG(1, I), 15, JDUM)
        IF (IEN(JDUM + 1) == 2) THEN
          NCARB = NCARB + 1
C * COUNT # H's ON RING
          NC = - NINT (CON(I, 9))
          IF (NC < 0) NC = 9
          DO K = 1, NC
            M = NINT (CON(I, K))
            CALL GEN048 (-1, IFG(1, M), 7, IHAT)
            NHAT = NHAT + IHAT
          END DO
        END IF
        NRJ = NRAT + J
C * CALCULATE RING BOND DISTANCES,ANGLES AND TORSION ANGLES
        I1 = JR(MOD (NRJ - 2, NRAT) + 1)
        I2 = JR(MOD (NRJ - 1, NRAT) + 1)
        I3 = JR(MOD (NRJ,     NRAT) + 1)
        I4 = JR(MOD (NRJ + 1, NRAT) + 1)
        CALL PLA053 (I2, I3, 0, 0, RBO(J), SRBO, KRBO(J), NRBO(J),
     1               IER)
        IF (IER /= 0) GO TO 10
        IF (SRBO <= 0.0) THEN
          WBO = 1.0
        ELSE
          WBO = 1.0 / SRBO**2
        END IF
        RBOMX = MAX (RBOMX, RBO(J))
        RBOMN = MIN (RBOMN, RBO(J))
        BAV   = BAV  + WBO * RBO(J)
        BAVK  = BAVK + WBO * RBO(J)**2
        SWT   = SWT  + WBO
C * SKIP SPECIAL DISORDER CASES
        CALL PLA053 (I1, I2, I3, 0, RANG(J), SRANG, KRANG(J),
     1               NRANG(J), IER)
        IF (IER /= 0) GO TO 10
        CALL PLA053 (I1, I2, I3, I4, TRA(J), STRA(J), KTRA(J),
     1               NTRA(J), IER)
        IF (IER /= 0) GO TO 10
        IF (STRA(J) <= 0) THEN
          WTAU  = 1.0
        ELSE
          WTAU  = 1.0 / STRA(J)**2
        END IF
        ATRA = ABS (TRA(J))
        IF (ATRA > 90.0) ATRA = ABS (180.0 - ATRA)
        TAU  = TAU  + WTAU * ATRA
        TAUK = TAUK + WTAU * ATRA**2
        STWT = STWT + WTAU
        IP   = JR(J)
        SIGJ = 0.0
        DO K = 1, 3
          XYZR(J,  K)     = XXO(IP,  K + 3)
          XXO(KRC, K)     = XXO(KRC, K)     + XXO(IP, K)
          XXO(KRC, K + 3) = XXO(KRC, K + 3) + XXO(IP, K + 3)
          XSD(KRC, K)     = XSD(KRC, K)     + XSD(IP, K)
          XSD(KRC, K + 3) = XSD(KRC, K + 3) + XSD(IP, K + 3)
          SIGJ            = SIGJ            + XSD(IP, K + 3)
        END DO
        XYZR(J, 4) = SIGJ / 3
        SMSIGJ     = SMSIGJ + SIGJ / 3
      END DO
      IF (NHEAD == 0 .AND. IGBL(63) > 3) THEN
        NHEAD = 1
        CALL PLA262 (-54)
        WRITE (LU7, 99970, IOSTAT = IOST)
        NRNG = IPR(496)
        IF (MOD (NRNG, 100) > 0) WRITE (LU7, 99969, IOSTAT = IOST)
        NRNG = NRNG / 100
        IF (MOD (NRNG, 100) > 0) WRITE (LU7, 99968, IOSTAT = IOST)
        NRNG = NRNG / 100
        IF (MOD (NRNG, 100) > 0) WRITE (LU7, 99967, IOSTAT = IOST)
        NRNG = NRNG / 100
        IF (NRNG > 0)
     1    WRITE (LU7, 99966, IOSTAT = IOST) '<', '>', '>', '>',
     2      '>', '>'
        WRITE (LU7, 99965, IOSTAT = IOST)
        WRITE (LU7, 99964, IOSTAT = IOST)
        WRITE (LU7, 99982, IOSTAT = IOST)
      END IF
      DO K = 1, 3
        XSD(KRC, K)     = XSD(KRC, K)    / (NRAT**2)
        XSD(KRC, K + 3) = XSD(KRC, K + 3)/ (NRAT**2)
        XXO(KRC, K)     = XXO(KRC, K)    /  NRAT
        XXO(KRC, K + 3) = XXO(KRC, K + 3)/  NRAT
      END DO
C * STORE COORDINATES ALSO IN BACKING STORE 'VOID'
      DO K = 1, 6
        VOID((KRC - 1) * NP71 + K)     = XXO(KRC, K)
        VOID((KRC - 1) * NP71 + K + 6) = XSD(KRC, K)
      END DO
      BAV    = BAV  / SWT
      BAVK   = BAVK / SWT
      KBAV   = MIN (999, NINT (10000.0 / SQRT (SWT)))
      KBAVE  = MIN (999, NINT (10000.0 * SQRT (ABS (BAVK
     1         - BAV**2) / (NRAT - 1))))
      TAU    = TAU / STWT
      TAUK   = TAUK / STWT
      KTAU   = MIN (999, NINT (100.0 / SQRT( STWT)))
      KTAUE  = MIN (999, NINT (100.0 * SQRT ( ABS(TAUK - TAU**2) /
     1         (NRAT - 1))))
      SMSIGJ = SMSIGJ / (NRAT**2)
      DO J = 1, NRAT
        DO K = 1, 3
          XYZR(J, K) = XYZR(J, K) - XXO(KRC, K + 3)
        END DO
        XYZR(J, 4) = XYZR(J, 4) + SMSIGJ
        SINF       = SIN (RGBL(5) * (J - 1) / NRAT)
        COSF       = COS (RGBL(5) * (J - 1) / NRAT)
        DO L = 1, 3
          XYZD(L)  = XYZD(L)  + XYZR(J, L) * SINF
          XYZDD(L) = XYZDD(L) + XYZR(J, L) * COSF
        END DO
      END DO
C * ESD CREMER & POPLE PLANE NORMAL APPROXIMATED WITH LS-PLANE ESD
      CALL GEN008 (XYZD, XYZDD, XPV, 1)
      IE  = 0
      BQ  = 0.0
      SBQ = 0.0
      DO J = 1, NRAT
        ZP(J) = XPV(1) * XYZR(J, 1) + XPV(2) * XYZR(J, 2)
     1        + XPV(3) * XYZR(J, 3)
        IF (ABS (ZP(J)) < 1.0E-15) ZP(J) = 0.0
        BQ    = BQ  + ZP(J)**2
        SBQ   = SBQ + ZP(J)**2 * XYZR(J, 4)
      END DO
      BQ  = SQRT (BQ)
      IF (BQ > 0.0) SBQ = SQRT (SBQ) / BQ
      DO J = 1, NRAT
        DCSV(J)  = 0.0
        DC2V(J)  = 0.0
        DCSB(J)  = 0.0
        DC2B(J)  = 0.0
        FCS(J)   = 0.0
        FC2(J)   = 0.0
        HDCSV(J) = 0.0
        HDC2V(J) = 0.0
        HDCSB(J) = 0.0
        HDC2B(J) = 0.0
        HFCS(J)  = 0.0
        HFC2(J)  = 0.0
        NRD2     = NRAT / 2
        NRD3     = (NRAT - 1) / 2
        NRJ      = NRAT + J
        DO K = 1, NRD2
          ITRA0 = MOD (NRJ + K - 1, NRAT) + 1
          ITRA1 = MOD (NRJ + K - 2, NRAT) + 1
          ITRA2 = MOD (NRJ - K - 1, NRAT) + 1
          TRA0  = TRA(ITRA0)
          STRA0 = STRA(ITRA0)**2
          TRA1  = TRA(ITRA1)
          STRA1 = STRA(ITRA1)**2
          TRA2  = TRA(ITRA2)
          STRA2 = STRA(ITRA2)**2
          SZP0  = SQRT (XYZR(ITRA0, 4))
          SZP2  = SQRT (XYZR(ITRA2, 4))
          T1P2S = (TRA1 + TRA2)**2
          T1M2S = (TRA1 - TRA2)**2
          T0P2S = (TRA0 + TRA2)**2
          T0M2S = (TRA0 - TRA2)**2
          ZP0P2 = ABS (ZP(ITRA0) + ZP(ITRA2))
          ZP0M2 = ABS (ZP(ITRA0) - ZP(ITRA2))
          IF (ZP0P2 < 1.0E-15) THEN
            Z0P2S = 0.0
          ELSE
            Z0P2S = ZP0P2**2
          END IF
          IF (ZP0M2 < 1.0E-15) THEN
            Z0M2S = 0.0
          ELSE
            Z0M2S = ZP0M2**2
          END IF
          DCSV(J)  = DCSV(J)  + T1P2S
          HDCSV(J) = HDCSV(J) + T1P2S * (STRA1 + STRA2)
          DC2V(J)  = DC2V(J)  + T1M2S
          HDC2V(J) = HDC2V(J) + T1M2S * (STRA1 + STRA2)
          IF (K <= NRD3) THEN
            FC2(J)   = FC2(J)   + Z0P2S
            HFC2(J)  = HFC2(J)  + Z0P2S * (SZP0  + SZP2)
            FCS(J)   = FCS(J)   + Z0M2S
            HFCS(J)  = HFCS(J)  + Z0M2S * (SZP0  + SZP2)
            DCSB(J)  = DCSB(J)  + T0P2S
            HDCSB(J) = HDCSB(J) + T0P2S * (STRA0 + STRA2)
            DC2B(J)  = DC2B(J)  + T0M2S
            HDC2B(J) = HDC2B(J) + T0M2S * (STRA0 + STRA2)
          END IF
        END DO
        IF (DCSV(J) < 1E-5) THEN
          HDCSV(J) = 0
        ELSE
          HDCSV(J) = SQRT (ABS (HDCSV(J)) / (NRD2 * DCSV(J)))
        END IF
        DCSV(J) = SQRT (ABS (DCSV(J)) / NRD2)
        IF (DC2V(J) < 1E-5) THEN
          HDC2V(J) = 0
        ELSE
          HDC2V(J) = SQRT (ABS (HDC2V(J)) / (NRD2 * DC2V(J)))
        END IF
        DC2V(J)  = SQRT (ABS (DC2V(J)) / NRD2)
        IF (DCSB(J) < 1E-5) THEN
          HDCSB(J) = 0
        ELSE
          HDCSB(J) = SQRT (ABS (HDCSB(J)) / (NRD3 * DCSB(J)))
        END IF
        DCSB(J) = SQRT (ABS (DCSB(J)) / NRD3)
        IF (FCS(J) < 1E-5) THEN
          HFCS(J) = 0.0
        ELSE
          HFCS(J) = SQRT (ABS (HFCS(J)) / (NRD3 * FCS(J)))
        END IF
        FCS(J) = SQRT (ABS (FCS(J)) / NRD3)
        IF (FC2(J) < 1E-5) THEN
          HFC2(J) = 0.0
        ELSE
          HFC2(J) = SQRT (ABS (HFC2(J)) / (NRD3 * FC2(J)))
        END IF
        FC2(J) = SQRT (ABS (FC2(J)) / NRD3)
        IF (DC2B(J) < 1E-5) THEN
          HDC2B(J) = 0.0
        ELSE
          HDC2B(J) = SQRT (ABS (HDC2B(J)) / (NRD3 * DC2B(J)))
        END IF
        DC2B(J) = SQRT (ABS (DC2B(J)) / NRD3)
      END DO
      NSP2 = 0
      NSP3 = 0
      II1  = -7
      DO
        II1  = II1 + 8
        II2  = II1 + 7
        IF (II2 > NRAT) II2 = NRAT
        JJ = 0
        DO II = II1, II2
          JJ = JJ + 1
          IP = JR(II)
          CALL PLA047 (LABA(IP), NQ1, IDUM, JDUM, IPR(71),
     1      IGBL(55), 0, 1 - IGBL(55))
          NAMS(JJ, 1) = ' '//NQ1(1:NP64 - 1)
          CALL GEN048 (-4, IFG(1, IP), 24, IHYB)
          IF (IHYB == 1) THEN
            CHYB = 'sp'
          ELSE IF (IHYB == 2) THEN
            CHYB = 'sp2'
            NSP2 = NSP2 + 1
          ELSE IF (IHYB == 3) THEN
            CHYB = 'sp3'
            NSP3 = NSP3 + 1
          ELSE
            CHYB = ' '
          END IF
          NAMS(JJ, 2) = CHYB
        END DO
        IF (II1 /= 1) THEN
          IF (IGBL(63) > 2) THEN
            CALL PLA262 (5)
            WRITE (LU7, 99996, IOSTAT = IOST)
     1      (NAMS(II, 1)(2:7), II = 1, JJ)
            WRITE (LU7, 99971, IOSTAT = IOST)
            WRITE (LU7, 99962, IOSTAT = IOST)
     1        (NAMS(II, 2)(1:3), II = 1, JJ)
          END IF
        ELSE
          IF (IGBL(63) > 2) THEN
C * NEWPAGE
            CALL PLA262 (-4)
            IF (ISUGR == 104) THEN
              CALL PLA262 (1)
              IF (IC2 == 1) THEN
                WRITE (LU7, 99991, IOSTAT = IOST)
              ELSE
                WRITE (LU7, 99990, IOSTAT = IOST)
              END IF
            END IF
            WRITE (PRBUF, 99997, IOSTAT = IOST) NRAT, IPR(19) + NRING,
     1        (NAMS(II, 1)(2:7), II = 1, JJ)
            WRITE (LU7, 99961, IOSTAT = IOST) PRBUF
            IF (MODE /= 0) THEN
              VRT = VRT - 0.7
              CALL PLA439 (0.0, PRBUF, 132, 0.3, 5 + IGBL(68), 2, 0.1,
     1          VRT)
            END IF
            WRITE (LU7, 99971, IOSTAT = IOST)
            WRITE (PRBUF, 99962, IOSTAT = IOST)
     1        (NAMS(II, 2)(1:3), II = 1, JJ)
            WRITE (LU7, 99961, IOSTAT = IOST) PRBUF
            IF (MODE /= 0) THEN
              VRT = VRT - 0.9
              CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
            END IF
          END IF
        END IF
        IF (IGBL(63) > 2) THEN
C * ROUND DEV, CS & C2 ARRAYS ON THE BASIS OF ESD
          IFT = 18
          I68 = IPR(68)
          DO II = II1, II2
            IFT = IFT + 16
            SX = SQRT (XYZR(II, 4))
            CALL GEN041 (ZP(II), SX, KZP(II),            4, NDEC, I68)
            FORMA(IFT:IFT) = CHAR (ICHAR ('0') + NDEC)
            CALL GEN041 (DCSV(II), HDCSV(II), KDCSV(II), 2, NDEC, I68)
            FORMB(IFT:IFT) = CHAR (ICHAR ('0') + NDEC)
            CALL GEN041 (DC2V(II), HDC2V(II), KDC2V(II), 2, NDEC, I68)
            FORMC(IFT:IFT) = CHAR (ICHAR ('0') + NDEC)
            FORMD(IFT:IFT) = CHAR (ICHAR ('0') + NRANG(II))
            FORME(IFT:IFT) = CHAR (ICHAR ('0') + NTRA(II))
            CALL GEN041 (DCSB(II), HDCSB(II), KDCSB(II), 2, NDEC, I68)
            FORMF(IFT:IFT) = CHAR (ICHAR ('0') + NDEC)
            CALL GEN041 (DC2B(II), HDC2B(II), KDC2B(II), 2, NDEC, I68)
            FORMG(IFT:IFT) = CHAR (ICHAR ('0') + NDEC)
            FORMH(IFT:IFT) = CHAR (ICHAR ('0') + NRBO(II))
          END DO
          WRITE (PRBUF, FORMA, IOSTAT = IOST)
     1      (ZP(II),   KZP(II),   II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (PRBUF, FORMB, IOSTAT = IOST)
     1      (DCSV(II), KDCSV(II), II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (PRBUF, FORMC, IOSTAT = IOST)
     1      (DC2V(II), KDC2V(II), II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (PRBUF, FORMD, IOSTAT = IOST)
     1      (RANG(II), KRANG(II), II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (LU7, 99974, IOSTAT = IOST)
          WRITE (PRBUF, FORME, IOSTAT = IOST)
     1      (TRA(II),  KTRA(II),  II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.9
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (PRBUF, FORMF, IOSTAT = IOST)
     1      (DCSB(II), KDCSB(II), II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (PRBUF, FORMG, IOSTAT = IOST)
     1      (DC2B(II), KDC2B(II), II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
          WRITE (PRBUF, FORMH, IOSTAT = IOST)
     1      (RBO(II),  KRBO(II),  II = II1, II2)
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
        END IF
        IF (II2 >= NRAT) EXIT
      END DO
      M = (NRAT - 1) / 2
C * TEST FOR CARBON 6-RING
      IF (NRAT == 6 .AND. NCARB == 6) THEN
        IF (NSP2 == 6) THEN
          IF (NHAT > 4) THEN
            NADD   = 0
            BAVEXP = 1.395
            DIFF   = 0.005
          ELSE
            NADD   = 3
            BAVEXP = 1.410
            DIFF   = 0.01
          END IF
          IF (TAU < 5.0) THEN
            BAVDIF = BAV - BAVEXP
            IF (BAVDIF > DIFF) THEN
              IF (NADD == 3) BAVDIF = -999.0
C * ALERT _330 + : Large Average Phenyl C-C
              CALL PLA236 (330 + NADD, 2, BAVDIF, BAV,
     1          NAMS(1, 1) (2:8), NAMS(6, 1) (2:8))
            ELSE IF (BAVDIF < - DIFF) THEN
C * ALERT _331 + : Small Average Phenyl C-C
              CALL PLA236 (331 + NADD, 2, - BAVDIF, BAV,
     1          NAMS(1, 1) (2:8), NAMS(6, 1) (2:8))
            END IF
          END IF
          IF (TAU < 12.0) THEN
            YUNK  = RBOMX - RBOMN
            YUNK1 = YUNK
            IF (NADD == 3) YUNK = -999.0
            IF (YUNK1 > 0.15) THEN
C * ALERT _332 +
              CALL PLA236 (332 + NADD, 2, YUNK, YUNK1,
     1          NAMS(1, 1) (2:8), NAMS(6, 1) (2:8))
            END IF
          END IF
        ELSE IF (NSP3 == 6) THEN
C * ALERT _338
          CALL PLA236 (338, 2, 60.0 - TAU, TAU, NAMS(1, 1)(2:8),
     1      NAMS(6, 1)(2:8))
        END IF
      END IF
      IF (IGBL(63) > 2) THEN
        CALL PLA262 (5)
        WRITE (LU7, 99974, IOSTAT = IOST)
        WRITE (PRBUF, 99960, IOSTAT = IOST) BAV, KBAV, KBAVE
        WRITE (LU7, 99961, IOSTAT = IOST) PRBUF
        IF (MODE /= 0) THEN
          VRT = VRT - 0.9
          CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
        END IF
        WRITE (PRBUF, 99959, IOSTAT = IOST) TAU, KTAU, KTAUE
        WRITE (LU7, 99961, IOSTAT = IOST) PRBUF
        IF (MODE /= 0) THEN
          VRT = VRT - 0.7
          CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
        END IF
        WRITE (LU7, 99974, IOSTAT = IOST)
        IF (NRAT == 4) THEN
          CALL PLA053 (JR(1), JR(2), JR(4), JR(3), TRA(5), STRA(5),
     1        KTRA(5), NTRA(5), IER)
          IF (IER == 0) THEN
            FORMQ(43:43) = CHAR (ICHAR ('0') + NTRA(5))
            WRITE (PRBUF, FORMQ, IOSTAT = IOST)
     1      NAMS(1, 1)(2:7), NAMS(2, 1)(2:7), NAMS(4, 1)(2:7),
     2      NAMS(2, 1)(2:7), NAMS(3, 1)(2:7), NAMS(4, 1)(2:7),
     3      ABS (TRA(5)), KTRA(5)
            CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          END IF
          CALL PLA053 (JR(2), JR(3), JR(1), JR(4), TRA(6), STRA(6),
     1                 KTRA(6), NTRA(6), IER)
          IF (IER == 0) THEN
            FORMQ(43:43) = CHAR (ICHAR ('0') + NTRA(6))
            WRITE (PRBUF, FORMQ, IOSTAT = IOST)
     1      NAMS(1, 1)(2:7), NAMS(2, 1)(2:7), NAMS(3, 1)(2:7),
     2      NAMS(1, 1)(2:7), NAMS(3, 1)(2:7), NAMS(4, 1)(2:7),
     3      ABS (TRA(6)), KTRA(6)
            CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          END IF
          WRITE (LU7, 99974, IOSTAT = IOST)
        END IF
      END IF
C * PUCKERING ANALYSIS FOR RINGS WITH <TAU> > PAR(95) DEGREES
C *                              DISTANCE VARIATION < PAR(328) %
      RMXMN = 100.0 * ABS (RBOMX - RBOMN) / BAV
      IF (TAU > PAR(95)) THEN
        IF (IGBL(63) > 2) THEN
          CALL PLA262 (2)
          WRITE (LU7, 99992, IOSTAT = IOST)
        END IF
        IF (NRAT / 2 > M) IE = 1
        IF (M > 1) THEN
          DO N = 2, M
            QS    = 0.0
            QC    = 0.0
            SQ    = 0.0
            CQ    = 0.0
            ATERM = 0
            BTERM = 0
            SIGAK = 0
            SIGBK = 0
            DO J = 1, NRAT
              COSNF = COS (RGBL(5) * N * (J - 1) / NRAT)
              SINNF = SIN (RGBL(5) * N * (J - 1) / NRAT)
              QC = QC + ZP(J) * COSNF
              QS = QS + ZP(J) * SINNF
              SQ = SQ + XYZR(J, 4) * SINNF**2
              CQ = CQ + XYZR(J, 4) * COSNF**2
              IF (NRAT == 5) THEN
                ATERM = ATERM + TRA(J) * COSNF
                BTERM = BTERM + TRA(J) * SINNF
                SIGAK = SIGAK + (STRA(J) * COSNF)**2
                SIGBK = SIGBK + (STRA(J) * SINNF)**2
              END IF
            END DO
            QC      =  QC * SQRT (2.0 / NRAT)
            QS      = -QS * SQRT (2.0 / NRAT)
            CQ      =  CQ * 2.0 / NRAT
            SQ      =  SQ * 2.0 / NRAT
            Q(N)    = SQRT (QC**2 + QS**2)
            SNTH    = 0.0
            CSTH    = 0.0
            PHI(N)  = 0.0
            SPHI(N) = 0.0
            SSQ(N)  = 0.0
            KQ(N)   = 0
            NQ(N)   = 0
            KPHI(N) = 0
            NPHI(N) = 0
            IF (Q(N) > 0.0001) THEN
              SNTH = QS / Q(N)
              CSTH = QC / Q(N)
              IF (CSTH >= 0) THEN
                PHI(N) = ASIN (SNTH) * RGBL(6)
                IF (PHI(N) < 0) PHI(N) = PHI(N) + 360.0
              ELSE
                PHI(N) = ACOS (CSTH) * RGBL(6)
                IF (SNTH < 0) PHI(N) = 360.0 - PHI(N)
              END IF
              SSQ(N)  = SQRT (ABS(CQ * CSTH**2 + SQ * SNTH**2))
              SPHI(N) = SQRT (ABS(CQ * SNTH**2
     1                + SQ * CSTH**2)) * RGBL(6) / Q(N)
            END IF
            IF (IGBL(63) > 2) THEN
              QQN = Q(N)
              CALL GEN041 (QQN, SSQ(N), KQ(N), 4, NQ(N), IPR(68))
              CALL GEN041 (PHI(N), SPHI(N), KPHI(N), 4, NPHI(N),
     1                  IPR(68))
              IF (N < 10) THEN
                FORMK(8:8)   = '1'
                FORMK(18:18) = '9'
                FORMK(46:46) = '1'
                FORMK(55:55) = '8'
              ELSE
                FORMK(8:8)   = '2'
                FORMK(18:18) = '8'
                FORMK(46:46) = '2'
                FORMK(55:55) = '7'
              END IF
              FORMK(20:20) = CHAR (ICHAR('0') + NQ(N))
              FORMK(57:57) = CHAR (ICHAR('0') + NPHI(N))
              WRITE (PRBUF, FORMK, IOSTAT = IOST)
     1          N, QQN , KQ(N), N, PHI(N), KPHI(N)
              CALL PLA263 (LU7, PRBUF, 132, 1, 1)
              IF (MODE /= 0) THEN
                VRT = VRT - 0.9
                CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
              END IF
            END IF
          END DO
        END IF
        IF (IE == 1) THEN
          N2    = NRAT / 2
          Q(N2) = 0.0
          QN2   = 0
          DO J = 1, NRAT
            Q(N2) = (-1)**(J - 1) * ZP(J) + Q(N2)
            QN2   = QN2 + XYZR(J, 4)
          END DO
          SSQ(N2) = SQRT (ABS (QN2 / NRAT))
          Q(N2)   = Q(N2) * SQRT (1.0 / NRAT)
          IF (IGBL(63) > 2) THEN
            QQN2 = Q(N2)
            CALL GEN041 (QQN2, SSQ(N2), KQ(N2), 4, NQ(N2), IPR(68))
            IF (N2 < 10) THEN
              FORML(8:8)   = '1'
              FORML(18:18) = '9'
            ELSE
              FORML(8:8)   = '2'
              FORML(18:18) = '8'
            END IF
            FORML(20:20) = CHAR (ICHAR ('0') + NQ(N2))
            WRITE (PRBUF, FORML, IOSTAT = IOST) N2, QQN2, KQ(N2)
            CALL PLA263 (LU7, PRBUF, 132, 1, 1)
            IF (MODE /= 0) THEN
              VRT = VRT - 0.7
              CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
            END IF
          END IF
          AAZ = Q(N2)
        ELSE
          AAZ = 0
        END IF
C * OUTPUT TOTAL PUCKERING AMPLITUDE
        IF (NRAT > 6 .AND. IGBL(63) > 2) THEN
          WRITE (LU7, 99974, IOSTAT = IOST)
          CALL GEN041 (BQ, SBQ, KBQ, 4, NBQ, IPR(68))
          FORMX(37:37) = CHAR (ICHAR ('0') + NBQ)
          WRITE (PRBUF, FORMX, IOSTAT = IOST) BQ, KBQ
          CALL PLA263 (LU7, PRBUF, 132, 1, 1)
          IF (MODE /= 0) THEN
            VRT = VRT - 1.0
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
        END IF
        IF (RMXMN > PAR(328) .AND. IGBL(63) > 2) THEN
          CALL PLA262 (4)
          WRITE (LU7, 99994, IOSTAT = IOST) RMXMN, PAR(328)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
          END IF
        END IF
        IF (NRAT == 8) THEN
            IF (IGBL(63) > 3) THEN
              CALL PLA262 (4)
              WRITE (LU7, 99979, IOSTAT = IOST)
            END IF
C * CALCULATE SPECIAL SIX-MEMBERED RING DESCRIPTORS Q, THETA, PHI
        ELSE IF (NRAT == 6) THEN
          IF (BQ > PAR(12)) THEN
            CSTH = Q(N2) / BQ
          ELSE
            CSTH = 0.0
          END IF
          IF (CSTH >  1.0) CSTH =  1.0
          IF (CSTH < -1.0) CSTH = -1.0
          TH  = ACOS (CSTH) * RGBL(6)
          IF (BQ > PAR(12)) THEN
            STH = SQRT (ABS ((SSQ(2)**2 - SSQ(3)**2)
     1          * CSTH**2 + SSQ(3)**2)) * RGBL(6) / BQ
          ELSE
            STH = 0.0
          END IF
          IF (IGBL(63) > 2) THEN
            CALL GEN041 (TH, STH, KTH, 2, NTH, IPR(68))
            CALL GEN041 (BQ, SBQ, KBQ, 4, NBQ, IPR(68))
            CALL PLA262 (1)
            WRITE (LU7, 99974, IOSTAT = IOST)
            FORMP(33:33) = CHAR (ICHAR('0') + NBQ)
            FORMP(62:62) = CHAR (ICHAR('0') + NTH)
            FORMP(90:90) = CHAR (ICHAR('0') + NPHI(2))
            WRITE (PRBUF, FORMP, IOSTAT = IOST)
     1        BQ, KBQ, TH, KTH, PHI(2), KPHI(2)
            CALL PLA263 (LU7, PRBUF, 132, 1, 1)
            IF (MODE /= 0) THEN
              VRT = VRT - 0.9
              CALL PLA439 (0.0, PRBUF, 132, 0.3, 1, 1, 0.1, VRT)
            END IF
            IF (IGBL(63) > 3) THEN
              CALL PLA262 (5)
              WRITE (LU7, 99981, IOSTAT = IOST)
            END IF
          END IF
C * CALCULATE SPECIAL 5-MEMBERED RING DESCRIPTORS
        ELSE IF (NRAT == 5) THEN
          ATERM = ATERM * 0.4
          BTERM = -0.4 * BTERM
          SIGAK = 0.16 * SIGAK
          SIGBK = 0.16 * SIGBK
          TAUM  = SQRT (ATERM**2 + BTERM**2)
          PPAR  = ATAN2 (BTERM, ATERM)
          STAUM = SQRT (SIGAK * ATERM**2 + SIGBK * BTERM**2) / TAUM
          SPPAR = SQRT (SIGBK * ATERM**2 + SIGAK * BTERM**2) / (TAUM**2)
          PPAR  = PPAR  * RGBL(6)
          SPPAR = SPPAR * RGBL(6)
          IPPAR = MIN (999, NINT (SPPAR * 10.0))
          ITAUM = MIN (999, NINT (STAUM * 10.0))
          IP    = JR(1)
C * TEST WHETHER AT1 IS AN OXYGEN ATOM, IF SO ADD 2 * 144 DEG TO P
          CALL GEN048 (-4, IFG(1, IP), 15, NO1)
          IF (IEN(NO1 + 1) == 3) THEN
            PPAR = PPAR + 288.0
            KK = 3
          ELSE
            KK = 1
          END IF
          IF (IGBL(63) > 3) THEN
            CALL PLA262 (5)
            WRITE (LU7, 99980, IOSTAT = IOST)
          END IF
          PPAR = MOD (PPAR + 360.0, 360.0)
          IF (IGBL(63) > 2) THEN
            WRITE (LU7, 99999, IOSTAT = IOST)
            WRITE (PRBUF, 99998, IOSTAT = IOST) PPAR, IPPAR, TAUM,
     1        ITAUM, NAMS(KK, 1)(2:7), NAMS(KK + 1, 1)(2:7)
            CALL GEN065 (LU7, PRBUF, 1, 132, 1)
            WRITE (LU7, 99983, IOSTAT = IOST)
            PRBUF = ' '
            WRITE (LU7, 99958)
            WRITE (PRBUF, 99989, IOSTAT = IOST) 2.0 * PPAR, 2 * IPPAR
            CALL GEN065 (LU7, PRBUF, 1, 132, 1)
            CALL PLA262 (7)
C * PSEUDOROTATION PUCKER DESCRIPTOR FOR FURANOSE RING
            IF (ISUGR == 104 .AND. ION2 == 1) THEN
              CALL PLA262(5)
              WRITE (LU7, 99988, IOSTAT = IOST)
              IBPAR = MOD (NINT (PPAR / 18.0), 20)
              IF (MOD(IBPAR, 2) == 0) THEN
                IBP = (IBPAR / 2) + 3
                IBP1 = MOD (IBP + 4, 5) + 1
                IBP2 = MOD (IBP    , 5) + 1
                TXT1 = '-exo '
                TXT2 = '-endo'
                IF (MOD (IBP, 2) == 0) THEN
                  TXT1 = '-endo'
                  TXT2 = '-exo '
                END IF
                WRITE (LU7, 99987, IOSTAT = IOST)
     1            NAMS(IBP1, 1)(2:7), TXT1, NAMS(IBP2, 1)(2:7), TXT2,
     2            ACONF
              ELSE
                IBP = (IBPAR - 1) / 2 + 3
                IBP1 = MOD (IBP, 5) + 1
                TXT1 = '-endo'
                IF (MOD (IBP, 2) == 0) TXT1 = '-exo '
                WRITE (LU7, 99986, IOSTAT = IOST)
     1            NAMS(IBP1, 1)(2:7), TXT1, ACONF
              END IF
            ELSE
              IBPAR = MOD (NINT (PHI(2) / 18.0), 20)
              CALL PLA262 (3)
C * TWIST
              IF (MOD(IBPAR, 2) == 1) THEN
                IBP = (IBPAR / 2)
                IBP1 = MOD (IBP,     5) + 1
                IBP2 = MOD (IBP + 1, 5) + 1
                WRITE (LU7, 99985, IOSTAT = IOST) NAMS(IBP1, 1)(2:7),
     1                             NAMS(IBP2, 1)(2:7)
C * ENVELOPE
              ELSE
                IBPAR = IBPAR / 2
                IBP1 = MOD (IBPAR, 5) + 1
                WRITE (LU7, 99984, IOSTAT = IOST) NAMS(IBP1, 1)(2:7)
              END IF
            END IF
            WRITE (LU7, 99974, IOSTAT = IOST)
          END IF
        END IF
C * Evans & Boeyens CONFORMATIONAL ANALYSIS
        IF (IGBL(63) > 2) CALL PLA218 (Q, PHI, AAZ, NRAT, LU7)
      ELSE
        IF (TAU < PAR(95) .AND.
     1      IGBL(63) > 2)  THEN
          CALL PLA262 (3)
          WRITE (LU7, 99974, IOSTAT = IOST)
          WRITE (PRBUF, 99995, IOSTAT = IOST) TAU, PAR(95)
          WRITE (LU7, 99961, IOSTAT = IOST) PRBUF
          WRITE (LU7, 99974, IOSTAT = IOST)
          IF (MODE /= 0) THEN
            VRT = VRT - 0.9
            CALL PLA439 (0.0, PRBUF, 132, 0.3, 2, 1, 0.1, VRT)
          END IF
        END IF
      END IF
C * PLANAR TEST
      IF (TAU < PAR(96)) CALL PLA035
      IF (IPR(2) /= 0) IPR(2) = 0
C * SIGNIFICANT (5&6-RING)-PUCKER TEST
      IF (NRAT == 6 .AND. TAU > PAR(97) .OR.
     1    NRAT == 5 .AND. TAU > PAR(94)) THEN
        NBND = 0
C * ANALYSE RING-SUBSTITUENT GEOMETRY
        NHAT = 0
        DO L = 1, 2
          DO I = 1, NRAT
            J  = JR(I)
            NC = - NINT (CON(J, 9))
            IF (NC < 0) NC = 9
            CALL PLA047 (LABA(J), NQ1, IDUM, JDUM, IPR(71),
     1        IGBL(55), 0, 1 - IGBL(55))
            DO K = 1, NC
              M = NINT (CON(J, K))
              N = I + NRAT - 2
              IF (M /= JR(MOD (I, NRAT) + 1) .AND.
     1            M /= JR(MOD (N, NRAT) + 1)) THEN
                CALL GEN048 (-1, IFG(1, M), 7, IHAT)
                IF (L + IHAT /= 2) THEN
                  NHAT = NHAT + IHAT
                  CALL PLA047 (LABA(M), NQ2, IDUM, JDUM, IPR(71),
     1              IGBL(55), 0, 1 - IGBL(55))
                  CALL PLA053 (J, M, 0, 0, D, SD, ISD, NDEC, IER)
                  IF (IER == 0) THEN
                    FORMI(19:19) = CHAR (ICHAR ('0') + NDEC)
                    CALL PLA227 (J, M, VECN)
                    ANG = XPV(1) * VECN(1) + XPV(2) * VECN(2)
     1                  + XPV(3) * VECN(3)
                    ANG = ABS (ANG)
                    IF (ANG > 1.0) ANG = 1.0
                    IANG = 0
                    ANG  = ACOS (ANG) * RGBL(6)
                    A    = 0
                    IF (D /= 0.0) THEN
                      DO KKK = 1, 3
                        A = A + XSPV(KKK)**2 + (VECN(KKK) * SD / D)**2
                      END DO
                      A = RGBL(6) * SQRT (A)
                    END IF
                    CALL GEN041 (ANG, A, IANG, 2, NDEC, IPR(68))
                    FORMI(39:39) = CHAR (ICHAR ('0') + NDEC)
                    KDES = 'Bi'
                    IF (ANG > 60) KDES = 'Eq'
                    IF (ANG < 30) KDES = 'Ax'
                    NBND = NBND + 1
                    IF (IGBL(63) > 2) THEN
                      IF (NBND == 1) THEN
                        CALL PLA262 (4)
                        WRITE (LU7, 99972, IOSTAT = IOST)
                      END IF
                      IF (NHAT == 1) THEN
                        CALL PLA262 (1)
                        WRITE (LU7, 99974, IOSTAT = IOST)
                      END IF
                      WRITE (PRBUF, FORMI, IOSTAT = IOST)
     1                  NQ1(1:7), NQ2(1:7), D, ISD, ANG, IANG, KDES
                      CALL PLA263 (LU7, PRBUF, 132, 1, 1)
                    END IF
                  END IF
                END IF
              END IF
            END DO
          END DO
        END DO
      END IF
   10 IF (MODE /= 0) THEN
        CALL GGIP (0.0, 0.0, 0.0, 3)
C * WHAT NEXT ?
        CALL PLA012 (1, 1)
      END IF
      RETURN
99999 FORMAT (/, 'Pseudorotation Parameters P and Tau(M), (S.T.Rao, ',
     1 'E.Westhof & M.Sundaralingam, Acta Cryst (1981), A37, 421-425)',
     2 /, 132('-'))
99998 FORMAT ('P =', F6.1, '(', I3, ') Degree, Tau(M) =', F6.1,
     1 '(', I3, ') Deg. for Reference Bond ', A, '--> ', A,
     2 ' [add 144 Deg. to P for each shift to next Bond]')
