     1        A, '-- ', A)
99984 FORMAT (/, 'Closest Pucker Descriptor: Envelope on ', A)
99983 FORMAT (84X, '[Ring-Sequence Change of Sense : P ---->>> - P]')
99982 FORMAT (//, '*** NOTE *** ',
     1 '- For Ring Puckering Comparisons: Make Sure that the ',
     2 'Absolute Configuration, Pivot Atom and Cyclic Sense Agree.', /,
     3 13X, '- The "RING AT1 AT2 AT3 ... ATn" Instruction Gives ',
     4 'the User Explicit Choice of Pivot Atom (AT1) and Sense (AT2).',
     5 /, 13X, '- Use TRNS Instructions to Obtain the',
     6 ' Required Absolute Configuration.',/, 13X, '- The Values of',
     7 ' Theta and Phi [ = Phi(2)] Depend on the Abs. Conf. and the',
     8 ' Choice of the First and Second Ring Atom.', /, 13X,
     9 '- Alternatively, Appropriate Phase Shifts may be Applied',
     * ' to the Same Effect (see Below)', /, 13X,
     1 '- C&P Analysis is with reference to the Cremer-Pople plane,',
     2 ' not to be confused with the associated LS-plane.', /, 15X,
     3 'See H.Essen & D.Cremer (1984) Acta Cryst. B40, 418-420.',
     4 //, 13X, 'For Correct Usage of C&P Puckering Parameters see ',
     5 'also: D. Cremer (1984) Acta Cryst. B40, 498-500.', /)
99981 FORMAT (//, '* NOTE * ',
     1 '- A Change of the Absolute Configuration Transforms Theta',
     2 ' into 180 - Theta and Phi into 180 + Phi.', /, 9X,
     3 '- A Cyclic Forward Shift of the Pivot Atom from At1 to At2',
     4 ' Transforms Theta into 180 - Theta and Phi into Phi + 120.',
     5 /, 9X,
     6 '- A Change of the Sense Transforms Theta into 180 - Theta',
     7 ' and Phi into 180 - Phi, and Vice Versa.')
99980 FORMAT (/, '* NOTE * ',
     1 '- A Change of the Absolute Configuration Transforms Phi(2)',
     2 ' into 180 + Phi(2).', /, 9X,
     3 '- A Cyclic Forward Shift of the Pivot Atom from At1 to At2',
     4 ' Transforms Phi(2) into Phi(2) + 144.', /, 9X,
     5 '- A Change of the Sense Transforms Phi(2) into 180 - Phi(2).')
99979 FORMAT (/, '* NOTE * ',
     1 '- A Cyclic Forward Shift of the Pivot Atom from At1 to At2',
     2 ' Transforms Q(4) into - Q(4), Phi(2) into Phi(2) + 90 and', /,
     3 11X, 'Phi(3) into Phi(3) + 135')
99974 FORMAT (1X)
99972 FORMAT (31X, 'Analysis of Ring Substituents', /, 31X,
     1 29('='), /, 6X, 'Bond', 13X, 'Distance', 5X,
     2 'Angle with C&P Plane Normal', /, 63('-'))
99971 FORMAT (132('-'))
99970 FORMAT ('Ring Puckering Analysis (Cremer & Pople) - (e.s.d.',
     1 ' following Norrestam, Acta Cryst. (1981), A37, 764-765)', /,
     2 132('-'), //, 19X, 'Symmetrical Forms', 70X, 'References', /,
     3 19X, 17('-'), 70X, 10('-'))
99969 FORMAT ('5-Membered Rings : E : Envelope  - Phi = k X 36',  24X,
     1 'D. Cremer & J.A. Pople, J.Amer.Chem.Soc., 97,(1975),1354-1358',
     2 /, 19X, 'T : Half Chair- Phi = k X 36 + 18 ', /)
99968 FORMAT ('6-Membered Rings : C : Chair     - Th = 0.0', 37X,
     1 'J.C.A. Boeyens, J.Cryst.Mol.Struct. 8,(1978),317-320', /, 19X,
     2 'H : Half-Chair- Th = 50.8; Phi = k X 60 + 30', /, 19X,
     3 'E : Envelope  - Th = 54.7; Phi = k X 60', /, 19X,
     4 'S : Screw-Boat- Th = 67.5; Phi = k X 60 + 30', /, 19X,
     5 'B : Boat      - Th = 90.0; Phi = k X 60', /, 19X,
     6 'T : Twist-Boat- Th = 90.0; Phi = k X 60 + 30', /)
99967 FORMAT ('7-Membered Rings : C : Chair', 43X,
     1 'I.K. Boessenkool et al., J.Cryst.Mol.Struct., 10,(1980),11-18',
     2 /, 18X, 'TC : Twist-Chair', /, 19X, 'B : Boat', /, 18X,
     3 'TB : Twist-Boat', /)
99966 FORMAT ('8-Membered Rings :CR : Crown     - Q(2)=Q(3)=0,    Q',
     1 '(4)', 2A, '0', 28X, 'Palyulin et al., J.Mol.Struct.,70,(1981',
     2 '),65-75'/19X,'B : Boat      - Q(3)=Q(4)=0,    Q(2)',A,' 0 Ph',
     3 'i(2) = k X 90 + 45'/18X, 'BB : Boat-Boat - Q(3)=Q(4)=0,  ',
     4 '  Q(2)', A, ' 0 Phi(2) = k X 90 '/19X, 'C : Chair     - ',
     5 'Q(2)=Q(4)=0,    Q(3)', A, ' 0 Phi(3) = k X 45 '/18X, 'LC : L',
     6 'ong-Chair- Q(2)=Q(4)=0,    Q(3)', A, ' 0 Phi(3) = k X 45',
     7 ' + 22.5'/)
99965 FORMAT (/, 'Definitions (All Values Rounded on Esd)', /,
     1  40('-'), /, 'Dev', 12X, '- Deviation of Atom I from ',
     2 'Cremer&Pople Plane (Defined Differently from Least-Squares ',
     3 'Plane)', /, 'Cs(I),C2(I)    - Mirror Plane and 2-Axis Asym. ',
     4 'Par. for Atom I (See Duax et al., Topics in Stereochemistry,',
     5 'V-9, (1976) pp.271-383)', /, 'Cs(I-J),C2(I-J)- Asymmetry ',
     6 'Parameters for Bond I-J', /, 'Tors(I-J)      - Torsion Angle',
     7 ' for Bond I-J', /)
99964 FORMAT (//,
     1 'Descriptors for Torsion Angles', 40X, 'Descriptors for Ring ',
     2 'Substituents (J.Appl.Cryst.,1983,16,431)', /, 30('-'), 40X,
     3 62('-'), //, 'Torsion Angle Range', 5X, 'Full Descriptor', 5X,
     4 'Short Descriptor', 10X, 'Angle Range of Subst.   Full ',
     5 'Descriptor', 5X, 'Short Descriptor', /, 60('-'), 10X, 60('-'),
     5 /, 4X, '0   TO   30 Deg', 5X, '+  Syn-Periplanar', 7X, '+sp',
     6 23X, '0    TO  30 Deg.', 12X, 'Axial', 12X, 'ax', /, 3X,
     7 '30   to   90', 9X, '+  Syn-Clinal', 11X, '+sc', 22X,
     8 '30    to  60', 11X, 'Bisectional', 12X, 'bi', /, 3X,
     9 '90   to  150', 9X, '+ Anti-Clinal',11X, '+ac', 22X,
     * '60    to  90', 12X, 'Equatorial', 12X, 'eq', /, 2X,
     1 '150   to  180', 9X, '+ Anti-Periplanar', 7X, '+ap', /, 4X,
     2 '0   to  -30', 9X, '-  Syn-Periplanar', 7X, '-sp', /, 2X,
     3 '-30   to  -90', 9X, '-  Syn-Clinal', 11X, '-sc', /, 2X,
     4 '-90   to -150', 9X, '- Anti-Clinal', 11X, '-ac', /, 1X,
     5 '-150   to -180', 9X, '- Anti-Periplanar', 7X, '-ap')
99962 FORMAT (20X, 8(10X, A))
99961 FORMAT (A)
99960 FORMAT ('Weighted Average Ring Bond Distance = ', F6.4, '(',
     1 I3,',',I3,') Ang. - NOTE: 1st esd. Internal, 2nd esd External.')
99959 FORMAT ('Weighted Average Abs. Torsion Angl. = ', F6.2, '(', I3,
     1 ',',I3,') Deg.',3X,'see: e.g. Domenicano et al., Acta Cryst.',
     2 '(1975), B31, 221-234.')
99958 FORMAT (1X)
      END SUBROUTINE PLA095
 
      SUBROUTINE PLA096 (MODE, XNQ, D, NCI)
C * VALENCE BOND ANALYSIS
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER, PARAMETER :: NP50 = 100
      INTEGER, PARAMETER :: NP51 = 100
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: L
      INTEGER       :: M
      INTEGER       :: N
      INTEGER       :: NB
      INTEGER       :: NE
      INTEGER       :: NT
      INTEGER       :: NTV
      INTEGER       :: IGN
      INTEGER       :: IAT
      INTEGER       :: NCI
      INTEGER       :: IVL
      INTEGER, SAVE :: MAT
      INTEGER, SAVE :: NVL
      INTEGER, SAVE :: NAT
      INTEGER       :: NSUM
      INTEGER       :: IMET
      INTEGER       :: IVAL
      INTEGER       :: MODE
      INTEGER       :: NDUB
      INTEGER, SAVE :: ISKP
      INTEGER, SAVE :: JSKP
      INTEGER       :: IVLMX
      INTEGER       :: IHTEST
      INTEGER       :: IATPRP
      INTEGER, SAVE, DIMENSION(NP51) :: NVAL
      REAL       :: B
      REAL       :: D
      REAL       :: R
      REAL       :: BV
      REAL       :: DMX
      REAL       :: DIF
      REAL, SAVE :: SUMX
      REAL       :: VSUM
      REAL       :: DIFM
      REAL       :: DMAX
      REAL       :: CRIT
      REAL, SAVE, DIMENSION(NP50) :: DIST
      CHARACTER(len=25)      :: SOURCE
      CHARACTER(len=8)       :: XNQ
      CHARACTER(len=7)       :: MQ
      CHARACTER(len=7), SAVE :: MQ1
      CHARACTER(len=2), SAVE :: MQ3
      CHARACTER(len=2), SAVE :: MQ4
      CHARACTER(len=2), SAVE, DIMENSION(9)    :: VL
      CHARACTER(len=7), SAVE, DIMENSION(NP50) :: MQ2
      CHARACTER(len=7), SAVE, DIMENSION(NP51) :: MQ5
C * MODE =  0 : INITIALIZE
C *         1 : STORE CONTACT
C *        -1 : ANALYSE & REPORT
      NB   = 0
      NE   = 0
      NSUM = 0
      VSUM = 0.0
      MQ   = XNQ(2:7)
      CRIT = PAR(454)
C * CHECK FOR COORDINATION MODE (IPR(57) = 0)
      IF (IPR(57) == 0) THEN
C * INITIALISE (GENERAL OR PER-ATOM)
        NSUM = 0
        IF (MODE == 0) THEN
C * GENERAL INIT
          IF (D < 0.0) THEN
            NAT         = 0
            SUMX        = 0.0
            NB          = 0
            NE          = 0
            JSKP        = 0
            T112        = ' '
C * CHECK FOR BOND-VALENCE-ANAL AND NO DISORDER OF NON-H ATOMS
            IF (IGBL(121) > 0) THEN
              ISKP = 0
            ELSE
              ISKP = 1
              IF (JSKP == 0) JSKP = 1
            END IF
C * PER-ATOM INIT
          ELSE
            IAT = NINT (D)
            CALL GEN048 (-1, IFG(1, IAT), 19, IMET)
            CALL GEN048 (-4, IFG(1, IAT), 15, IVAL)
            IATPRP = IATPR(IEN(IVAL + 1))
C * INCLUDE METAL + Te
            IF ((IGBL(121) > 0 .OR.
     1        ((IMET > 0 .OR. IEN(IVAL + 1) == 92) .AND.
     2          IATPRP /= 5 .AND. IATPRP /= 6))
     3        .AND. XNQ(1:1) == ' ') THEN
              ISKP = 0
            ELSE
              ISKP = 1
              IF (JSKP == 0) JSKP = 2
            END IF
            IF (NAT < NP51) THEN
              NAT      = NAT + 1
              MQ1      = MQ
              MQ5(NAT) = MQ
              MAT      = 0
C * DETERMINE WHETHER THIS IS A 1 OR 2 LETTER ATOM TYPE
              CALL GEN105 (2, MQ(2:2), N)
              IF (N < 0) THEN
                MQ3 = MQ(1:1)
              ELSE
                MQ3 = MQ(1:2)
              END IF
C * COLLECT LIST OF VALENCES FOR THIS ELEMENT
              NVL   = 0
              IVLMX = 9
              DO 10 J = 1, NP53
                IF (VALENCE(J)(1:2) == MQ3) THEN
                  IF (NVL == 0) THEN
                    NVL   = 1
                    VL(1) = ' '//VALENCE(J)(3:3)
                  ELSE
                    IF (' '//VALENCE(J)(3:3) /= VL(NVL)) THEN
                      NVL     = NVL + 1
                      VL(NVL) = ' '//VALENCE(J)(3:3)
                    END IF
                  END IF
                ELSE IF (VALENCE(J)(4:5) == MQ3) THEN
                  IF (NVL == 0) THEN
                    NVL   = 1
                    VL(1) = VALENCE(J)(6:7)
                  ELSE
                    DO I = 1, NVL
                      IF (VALENCE(J)(6:7) == VL(I)) GO TO 10
                    END DO
                    NVL     = NVL + 1
                    VL(NVL) = VALENCE(J)(6:7)
                  END IF
                END IF
C * CHECK FOR ORGANIC (LIMIT MAXIMUM ALLOWED VALENCY)
                IF (IPR(325) >= 0 .AND. NVL > 0) THEN
                  READ (VL(NVL), 99995) IVL
                  DO I = 1, NP9
                    IF (MQ3 == ELB(I)) THEN
                      IVLMX = IVALMAX(I)
                      EXIT
                    END IF
                  END DO
                  IF (IVL > IVLMX .OR. IVL < 0) NVL = NVL - 1
                END IF
   10         CONTINUE
            END IF
          END IF
C * STORE CONTACTS (MODE = 1)
        ELSE IF (MODE == 1 .AND. ISKP == 0) THEN
          IF (XNQ(1:1) == ' ') THEN
            IF (MAT < NP50) THEN
              MAT       = MAT + 1
              MQ2(MAT)  = MQ
              DIST(MAT) = D
            END IF
          ELSE
C * IGNORE DISORDERED H-ATOMS
            IF (XNQ(2:3) /= 'H(' .AND. D < 3.5) THEN
              ISKP = 1
              IF (JSKP == 0) JSKP = 3
            END IF
          END IF
C * ANALYSE & REPORT (MODE = -1)
        ELSE IF (MODE == -1) THEN
          IF (ISKP == 0) THEN
            DIFM = 10.0
            DIF  = 10.0
C * LOOP OVER VALENCIES
            DO K = 1, NVL
              READ (VL(K), 99995) IVL
              IF (IGBL(63) > 2) THEN
                CALL PLA262 (0)
                WRITE (LU7, 99998, IOSTAT = IOST) VL(K), CRIT
                WRITE (LU7, 99996, IOSTAT = IOST)
              END IF
              NDUB = 0
              SUMX = 0.0
              DMX  = 0.0
              L    = 0
              IGN  = 0
              IF (MAT > 0) THEN
                DO  30 I = 1, MAT
                  NTV = 0
                  IF (NAT > 0) THEN
                    DO NT = 1, NAT
                      CALL GEN039 (1, MQ5(NT), 1, 7, NB, NE)
                      IF (MQ2(I)(1:NE) == MQ5(NT)(1:NE))
     1                    NTV = NVAL(NT)
                    END DO
                  END IF
                  CALL GEN105 (2, MQ2(I)(2:2), N)
                  IF (N < 0) THEN
                    MQ4 = MQ2(I)(1:1)
                  ELSE
                    MQ4 = MQ2(I)(1:2)
                  END IF
                  IF (MQ3 == MQ4) THEN
                    IF (MQ3 == 'O ' .OR. MQ3 == 'N ') GO TO 30
                  END IF
                  IF (MQ3 == 'N ' .AND. MQ4 == 'C ') GO TO 30
                  DO J = 1, NP53
C * POSITIVE VALENCE
                    IF (VL(K)(1:1) /= '-') THEN
                      IF (VL(K)(2:2) == VALENCE(J)(3:3)) THEN
                        IF (MQ3 == VALENCE(J)(1:2) .AND.
     1                    MQ4 == VALENCE(J)(4:5)) THEN
                          READ (VALENCE(J), 99997) R, B
                          BV = EXP ((R - DIST(I)) / B)
                          IF (BV > IVL * CRIT) THEN
                            SUMX = SUMX + BV
                            DIF  = ABS (IVL - SUMX)
                            L    = L + 1
                            DMX  = MAX (DMX, DIST(I))
                            IF (IGBL(63) > 2) THEN
                              IF (VALENCE(J)(18:18) == '*') THEN
                                SOURCE = 'PLATON'
                              ELSE
                                SOURCE = ' '
                              END IF
                              WRITE (LU7, 99999, IOSTAT = IOST) L, MQ1,
     1                          MQ2(I), DIST(I), R, B, BV, SUMX, DIF,
     2                          SOURCE
                            END IF
                          ELSE
                            IF (IGBL(63) > 0) THEN
                              WRITE (LU7, 99990, IOSTAT = IOST)
     1                          MQ1, MQ2(I), DIST(I), BV, IVL * CRIT
                            END IF
                          END IF
                          GO TO 30
                        END IF
                      END IF
C * NEGATIVE VALENCE
                    ELSE
                      IF (VL(K) == VALENCE(J)(6:7)) THEN
                        IF (MQ3 == VALENCE(J)(4:5) .AND.
     1                      MQ4 == VALENCE(J)(1:2)) THEN
                          IF (NTV > 0) THEN
                            READ (VALENCE(J)(3:3), 99994) M
                            IF (M /= NTV) CYCLE
                          END IF
                          READ (VALENCE(J), 99997) R, B
                          BV  = EXP ((R - DIST(I)) / B)
                          IF (BV > IABS (NTV) * CRIT) THEN
                            SUMX = SUMX + BV
                            DIF  = ABS (IABS (IVL) - SUMX)
                            L    = L + 1
                            DMX  = MAX (DMX, DIST(I))
C * CONTIBUTION TO VALENCE SUMX
                            IF (IGBL(63) > 2) THEN
                              WRITE (LU7, 99999, IOSTAT = IOST) L, MQ1,
     1                          MQ2(I), DIST(I), R, B, BV, SUMX, DIF
                            END IF
                          ELSE
C * CONTRIBUTION BELOW MINIMUM
                            IF (IGBL(63) > 2) THEN
                              WRITE (LU7, 99990, IOSTAT = IOST) MQ1,
     1                          MQ2(I), DIST(I), BV, IABS (NTV) * CRIT
                            END IF
                          END IF
                          EXIT
                        END IF
                      END IF
                    END IF
                  END DO
C * CONTRIBUTION NOT TABULATED
                  IF (IGBL(63) > 2) THEN
                    WRITE (LU7, 99991, IOSTAT = IOST)
     1                MQ1, MQ2(I), DIST(I)
                  END IF
C * CHECK FOR ABSENT DATA (DUBIOUS RESULT)
                  IHTEST = 0
                  IF (MQ2(I)(1:1) == 'H') THEN
C * SEARCH FOR LOWER CASE CHAR
                    CALL GEN105 (2, MQ2(I)(2:2), IHTEST)
                  END IF
                  IF (IHTEST < 0) THEN
                    IF (DIST(I) < 1.0) NDUB = NDUB + 1
                  ELSE
                    IF (I <= NCI) NDUB = NDUB + 1
                    IF (DIST(I) < 2.4) NDUB = NDUB + 1
                  END IF
   30           CONTINUE
                IF (NDUB == 0 .AND. DIF < DIFM .AND. IGN == 0)
     1            THEN
                  NVAL(NAT) = IVL
                  DIFM      = DIF
                  VSUM      = SUMX
                  NSUM      = L
                  DMAX      = DMX
                END IF
              END IF
            END DO
C * END OF LOOP OVER VALENCES
            IF (VSUM > 0.0 .AND. NSUM > 0 .AND.
     1          DIFM < 1.0) THEN
              N = NVAL(NAT)
              IF (N < 1 .OR. N > 9) N = 10
              MQ1 = VALENCES(N)
              IF (MQ5(NAT)(1:2) /= 'Cu' .OR. NSUM /= 4) THEN
                WRITE (T112(1:75), 99993, IOSTAT = IOST)
     1            MQ5(NAT), MQ1, VSUM, DMAX, NSUM
                IF (LU6 /= 0) THEN
                  WRITE (LU6, 99992, IOSTAT = IOST) T112(1:75)
                  T112(76:76) = CHAR (0)
                END IF
                IF (IGBL(63) > 2) THEN
                  WRITE (LU7, 99992, IOSTAT = IOST) T112(1:75)
                END IF
C * ALERT _794
                CALL PLA236 (794, 2, -999.0, VSUM, MQ5(NAT), MQ1)
              END IF
            END IF
            CALL PLA262 (0)
          ELSE
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT (I2, 2X, 2A, F10.4, F7.4, F5.2, 3F6.3, ' - ', A)
99998 FORMAT ('Bond Valence Analysis - Assume Valence = ', A,
     1        ' -- Min. BondVal Contribution = ', F5.2,
     2        ' * Cation Val.', /, 100('='), /,
     1        'N.E. Brese & M. O''Keeffe',
     2        ' (1991) Acta Cryst. B47, 192-197.', /,
     3        'I.D. Brown (2002). The Chemical Bond in Inorganic',
     4        ' Chemistry: The Bond Valence Model. ',
     5        'Oxford University Press.')
99997 FORMAT (7X, F6.0, F4.0)
99996 FORMAT (/, 'Nr', 6X, 'Bond', 12X, 'Dist', 6X, 'R',
     1         4X, 'B  BVal   Sum  Diff - Source')
99995 FORMAT (I2)
99994 FORMAT (I1)
99993 FORMAT (2A, ' Vsum =', F6.2, ', Dmax =', F8.4, ', Nsum =', I3)
99992 FORMAT (/, ':: ', A)
99991 FORMAT (4X, 2A, F10.4, 33X,
     1       '(Contribution not Tabulated, Result Dubious !)')
99990 FORMAT (4X, 2A, F10.4, 33X, '(Contribution =', F6.3,
     1       'Below Minimum =', F6.3, ', Skipped)')
      END SUBROUTINE PLA096
 
      SUBROUTINE PLA097 (MODE, ARU)
C * TRANSLATE ARU TO SYMMETRY
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: ML
      INTEGER :: MODE
      INTEGER :: MOL1
      INTEGER :: MOL2
      INTEGER :: MOL3
      INTEGER :: MOL4
      INTEGER :: IRS0
      INTEGER :: NEWARU
      REAL :: ARU
      IF (MODE == 0) THEN
        IPR(25) = 0
      ELSE IF (MODE > 0) THEN
        IF (IPR(13) + IPR(25) + 2 < NP11) THEN
          NEWARU = NINT (ARU * 100.0)
          IF (IPR(25) > 0) THEN
            DO I = 1, IPR(25)
              IF (NEWARU == MOL(IPR(13) + I)) RETURN
            END DO
          END IF
          IPR(25) = IPR(25) + 1
          MOL(IPR(25) + IPR(13)) = NEWARU
        END IF
C * TRANSLATE ARU TO SYMMETRY CODE
      ELSE IF (MODE < 0) THEN
        IF (IPR(25) > 0) THEN
          CALL PLA262 (1)
          WRITE (LU7, 99998, IOSTAT = IOST)
          DO I = 1, IPR(25)
            ML = MOL(IPR(13) + I)
            CALL PLA455 (ML, MOL1, MOL2, MOL3, MOL4, IRS0)
            SGY(4) = MOL2
            SGY(5) = MOL3
            SGY(6) = MOL4
            CALL SGSM (20, ICL, SGY, MOL1, 0, IERR)
            ML = INT (ML / 100.0)
            CALL PLA262 (1)
            WRITE (LU7, 99999, IOSTAT = IOST) ML, ICL(1:30)
          END DO
        END IF
      END IF
      RETURN
99999 FORMAT ('[', I6, '] = ', A)
99998 FORMAT (1X)
      END SUBROUTINE PLA097
 
      SUBROUTINE PLA098 (N1, N2, KB, DIS, SDIS, DIFF, IDS12, MODE)
C * CALCULATE AVERAGE BOND DISTANCES (+ BP)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: N3
      INTEGER :: I0
      INTEGER :: J0
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: KB
      INTEGER :: NC
      INTEGER :: IM
      INTEGER :: MSP
      INTEGER :: N10
      INTEGER :: N20
      INTEGER :: NOA
      INTEGER :: NOB
      INTEGER :: NO1
      INTEGER :: NO2
      INTEGER :: NO3
      INTEGER :: INR
      INTEGER :: NBH
      INTEGER :: NC1
      INTEGER :: NC2
      INTEGER :: NO12
      INTEGER :: NDIS
      INTEGER :: IFIN
      INTEGER :: IAT1
      INTEGER :: IAT2
      INTEGER :: IEN1
      INTEGER :: IEN2
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: MODE
      INTEGER :: IBPR
      INTEGER :: IDMJ
      INTEGER :: NROXY
      INTEGER :: IEN12
      INTEGER :: IHYB1
      INTEGER :: IHYB2
      INTEGER :: IDS12
      INTEGER :: GEN152
      INTEGER, DIMENSION(71) :: KSM
      REAL :: DIS
      REAL :: SDIS
      REAL :: TDIS
      REAL :: DIFF
      REAL :: SUMR
      REAL :: DIST
      REAL :: RATIO
      REAL :: BNDPX
      CHARACTER(len=1) :: NOTE
      CHARACTER(len=1) :: HYB1
      CHARACTER(len=1) :: HYB2
      CHARACTER(len=8) :: BNDPR
      TDIS  = 0.0
      BNDPX = 0.0
      IDUM  = 0
      JDUM  = 0
C * ASSEMBLE BOND LENGTH STATISTICS
      IF (MODE > 0) THEN
        N10 = N1
        N20 = N2
C * STORE BOND FOR AVERAGE
        CALL GEN048 (-4, IFG(1, N1), 24, IHYB1)
        CALL GEN048 (-4, IFG(1, N2), 24, IHYB2)
        CALL GEN048 (-4, IFG(1, N1), 15, NO1)
        CALL GEN048 (-4, IFG(1, N2), 15, NO2)
        IF (IHYB1 == 0) IHYB2 = 0
        IF (IHYB2 == 0) IHYB1 = 0
        NOA  = NO1 * 10 + IHYB1
        NOB  = NO2 * 10 + IHYB2
        IEN1 = IEN(NO1 + 1)
        IEN2 = IEN(NO2 + 1)
        IAT1 = IATNR(IEN1)
        IAT2 = IATNR(IEN2)
        IF (IAT1 < IAT2) THEN
          CALL GEN014 (NOA,   NOB)
          CALL GEN014 (IEN1, IEN2)
          CALL GEN014 (IAT1, IAT2)
          CALL GEN014 (N10,   N20)
        END IF
C * TEST SELECTED BONDS
        CALL PLA047 (LABA(N10), NQ1, IDUM, JDUM,
     1    IPR(71), IGBL(55), 0, 1 - IGBL(55))
        CALL PLA047 (LABA(N20), NQ2, IDUM, JDUM,
     1    IPR(71), IGBL(55), 0, 1 - IGBL(55))
        IF (IAT2 == 6) THEN
          IF (IAT1 == 17) THEN
C * ALERT _336
            CALL PLA236 (336, 3, DIS - 1.85,  DIS, NQ2(1:7), NQ1(1:7))
          END IF
        END IF
        IF (IAT2 > 1) IPR(315) = IPR(315) + 1
        IF (IDS12 /= 20000) RETURN
        IEN12 = IEN1 * 1000 + IEN2
        IF (IHYB1 < IHYB2) CALL GEN014 (IHYB1, IHYB2)
        INR = 0
C * ALERT _350, _351 : RANGE CHECK C - H (XRAY/NEUTRON)
        IF (IEN12 == 2001) THEN
          IF (IABS (IPR(493)) == 7 .OR. IPR(775) == 1) THEN
            TDIS = 1.08
          ELSE
            TDIS = 0.96
          END IF
          INR  = 350
C * ALERT _356 - BOND (RANGE) CHECK B - H
        ELSE IF (IEN12 == 20001) THEN
          NC1 = - NINT (CON (N1, 9))
          NC2 = - NINT (CON (N2, 9))
          IF (NC1 == 4 .AND. NC2 == 1) THEN
            NBH = 0
            DO I = 1, NC1
              N3 = NINT (CON(N1, I))
              CALL GEN048 (-4, IFG(1, N3), 15, NO3)
              IF (IEN(NO3 + 1) == 1) NBH = NBH + 1
            END DO
C * X-BH3 - ALERTS _356, _357
            IF (NBH == 3) THEN
              TDIS = 1.16
              INR  = 356
C * (X,Y,Z)-B-H - ALERTS _358, _359
            ELSE IF (NBH == 1) THEN
              TDIS = 1.06
              INR  = 358
            ELSE
              INR = 0
            END IF
          END IF
C * RANGE CHECK N - H (XRAY)
        ELSE IF (IEN12 == 4001) THEN
          NC = - NINT(CON (N2, 9))
C * AVOID ACID BRIDGES N..H ..X
          IF (NC == 1) THEN
            IF (IABS (IPR(493)) == 7 .OR. IPR(775) == 1) THEN
              TDIS = 1.009
            ELSE
              TDIS = 0.87
            END IF
            INR  = 352
          END IF
C * RANGE CHECK O - H (XRAY)
        ELSE IF (IEN12 == 3001) THEN
          NC = - NINT(CON (N2, 9))
C * AVOID ACID BRIDGES O..H..O
          IF (NC == 1) THEN
            IF (IABS (IPR(493)) == 7) THEN
              TDIS = 0.983
            ELSE
              TDIS = 0.82
            ENDIF
            INR  = 354
          END IF
C * RANGE CHECK C - C (XRAY)
        ELSE IF (IEN12 == 2002) THEN
C * BOND PRECISION
          IF (SDIS > 0.0001) THEN
            IPR(317) = IPR(317) + 1
            PAR(318) = PAR(318) + SDIS
          END IF
          IF (IPR(483) > 0 .AND. IPR(484) > 0) THEN
            IF (IHYB1 == 3) THEN
C * C(sp3)-C(sp3)
              IF (IHYB2 == 3) THEN
                TDIS = 1.54
                INR  = 360
C * C(sp3)-C(sp2)
              ELSE IF (IHYB2 == 2) THEN
                TDIS = 1.52
                INR  = 362
C * C(sp3)-C(sp)
              ELSE IF (IHYB2 == 1) THEN
                TDIS = 1.46
                INR  = 364
C * C?-C?
              ELSE
                TDIS = 1.50
                INR  = 366
              END IF
            ELSE IF (IHYB1 == 2) THEN
              IF (IHYB2 == 2) THEN
C * C(sp2)-C(sp2)
                NROXY = 0
C * SPECIAL TREATMENT OXALAAT
                DO I = 1, 3
                  M1 = NINT (CON(N1, I))
                  M2 = NINT (CON(N2, I))
                  CALL GEN048 (-4, IFG(1, M1), 15, K)
                  IF (IEN(K + 1) == 3) NROXY = NROXY + 1
                  CALL GEN048 (-4, IFG(1, M2), 15, K)
                  IF (IEN(K + 1) == 3) NROXY = NROXY + 1
                END DO
                IF (NROXY /= 4) THEN
                  TDIS = 1.34
                  INR  = 368
                END IF
C * C(sp2)-C(sp)
              ELSE IF (IHYB2 == 1) THEN
                TDIS = 1.31
                INR  = 370
                MSP  = 0
C * SPECIAL TREATMENT OF C(sp2)-C(sp)-N
                IF (NINT (CON(N1, 9)) == -2) THEN
                  MSP = NINT (CON(N1, 1))
                ELSE IF (NINT (CON(N2, 9)) == -2) THEN
                  MSP = NINT (CON(N2, 1))
                END IF
                IF (MSP /= 0) THEN
                  CALL GEN048 (-4, IFG(1, MSP), 15, K)
                  IF (IEN(K + 1) == 4) TDIS = 1.44
                END IF
              ELSE
C * C?-C? (sp2)
                TDIS = 1.50
                INR  = 366
              END IF
            ELSE IF (IHYB1 == 1) THEN
C * C(sp)-C(sp)
              IF (IHYB2 == 1) THEN
                TDIS = 1.25
                INR  = 372
              ELSE
C * C(?)-C(?)
                TDIS = 1.50
                INR  = 366
              END IF
            ELSE
C * C(?)-C(?)
              TDIS = 1.50
              INR  = 366
            END IF
          END IF
C * CHECK FOR LONG N-N
        ELSE IF (IEN12 == 4004) THEN
          IF (DIS > 1.45) THEN
C * ALERT _374
            CALL PLA236 (374, 2, DIS - 1.45, DIS, NAMS(KB, 1)(1:7),
     1        NAMS(KB, 2)(1:7))
          END IF
          INR = 0
        END IF
        IF (INR /= 0) THEN
          DIFF = ABS (DIS - TDIS)
          IF (DIFF > 0.001) THEN
            IF (DIS > TDIS) INR = INR + 1
C * ALERT _3xx
            IF (INR == 367) DIFF = -999.0
            IF (INR == 371 .AND. DIFF > 0.1) DIFF = -999.0
            CALL PLA236 (
     1        INR, 2, DIFF, DIS, NAMS(KB, 1)(1:7), NAMS(KB, 2)(1:7))
          END IF
        END IF
        NO12 = NOA * 1000 + NOB
        IM   = IPR(47)
        IF (IM > 0) THEN
          DO I = 1, IM
            IF (NO12 == KBO(I, 1)) THEN
              IF (KBO(I, 2) == 0) BOK(I, 1) = 9999.0
              KBO(I, 2) = KBO(I, 2) + 1
              BOK(I, 3) = BOK(I, 3) + DIS
              IF (SDIS > 0.0) THEN
                KBO(I, 5) = KBO(I, 5) + 1
                BOK(I, 6) = BOK(I, 6) + SDIS
              END IF
              IF (DIS < BOK(I, 1)) BOK(I, 1) = DIS
              IF (DIS > BOK(I, 2)) BOK(I, 2) = DIS
              RETURN
            END IF
          END DO
        END IF
        IF (IPR(47) < NP8) THEN
          IPR(47)   = IPR(47) + 1
          I         = IPR(47)
          KBO(I, 1) = NO12
          BOK(I, 1) = DIS
          BOK(I, 2) = DIS
          BOK(I, 3) = DIS
          KBO(I, 2) = 1
          IF (SDIS > 0.0) THEN
            KBO(I, 5) = 1
            BOK(I, 6) = SDIS
          END IF
        END IF
      ELSE IF (MODE < 0) THEN
C * GET BOND AVERAGE LISTING
        IF (IPR(6) /= 0) THEN
          IF (IPR(317) > 0) THEN
            PAR(318) = PAR(318) / IPR(317)
            IF (IPR(22) < 20) THEN
              IBPR = 340
            ELSE IF (IPR(22) >= 40) THEN
              IBPR = 342
            ELSE
              IBPR = 341
            END IF
C * ALERT _340, _341, _342
C * ESTABLISH RELEVANT NUMBER OF DECIMALS
            N = GEN152 (PAR(318))
            CALL PLA236 (IBPR, N, PAR(318), PAR(318), ' ', ' ')
          END IF
          IM = IPR(47)
          IF (IGBL(63) > 2) THEN
            CALL PLA262 (-6)
            WRITE (LU7, 99999, IOSTAT = IOST)
          END IF
          DO I = 1, IM
            CALL GEN097 (KSM, 1, 71, 0)
            IPR(133) = -1
            DO
              IPR(133) = IPR(133) + 1
              IF (IPR(133) > 1) EXIT
              IFIN = -1
              DO
                CALL PLA038 (I0, J0, IFIN)
                IF (IFIN == 1) EXIT
                CALL GEN048 (-4, IFG(1, I0), 24, IHYB1)
                CALL GEN048 (-4, IFG(1, J0), 24, IHYB2)
                CALL GEN048 (-4, IFG(1, I0), 15, NO1)
                CALL GEN048 (-4, IFG(1, J0), 15, NO2)
                IF (IHYB1 == 0) IHYB2 = 0
                IF (IHYB2 == 0) IHYB1 = 0
                NOA = NO1 * 10 + IHYB1
                NOB = NO2 * 10 + IHYB2
                IF (IATNR(IEN(NO1 + 1)) < IATNR(IEN(NO2 + 1))) THEN
                  CALL GEN014 (NOA, NOB)
                END IF
                NO12 = NOA * 1000 + NOB
                IF (KBO(I, 1) == NO12) THEN
                  CALL PLA050 (I0, J0, 0, 0, DIST)
                  NDIS      = MIN (71, NINT (DIST * 20 + 1))
                  KSM(NDIS) = KSM(NDIS) + 1
                END IF
              END DO
            END DO
            DO J = 1, 71
              IDMJ = KSM(J)
              IF (IDMJ <= 0) THEN
                IDM(J:J) = '.'
              ELSE IF (IDMJ <= 9) THEN
                IDM(J:J) = CHAR (ICHAR ('0') + IDMJ)
              ELSE IF (IDMJ <= 35) THEN
                IDM(J:J) = CHAR (ICHAR ('Z') - 35 + IDMJ)
              ELSE
                IDM(J:J) = '*'
              END IF
            END DO
            HYB1 = ' '
            HYB2 = ' '
            K = KBO(I, 1) / 1000
            L = KBO(I, 1) - K * 1000
            IHYB1 = MOD (K, 10)
            IHYB2 = MOD (L, 10)
            K = K / 10 + 1
            L = L / 10 + 1
            IF (IHYB1 /= 0) THEN
              IF (IEN(K) == 2 .OR. IEN(K) == 4)
     1            HYB1 = CHAR (IHYB1 + 49)
              IF (IEN(L) == 2 .OR. IEN(K) == 4)
     1            HYB2 = CHAR (IHYB2 + 49)
            END IF
            SUMR = RADR(K, 2) + RADR(L, 2)
            IF (KBO(I, 2) > 0) BOK(I, 3) = BOK(I, 3) / KBO(I, 2)
            IF (KBO(I, 5) > 0) THEN
              BOK(I, 6) = BOK(I, 6) / KBO(I, 5)
              WRITE (BNDPR, 99995, IOSTAT = IOST) BOK(I, 6)
            ELSE
              CALL GEN038 (BNDPR, 1, 8)
            END IF
            IF (BOK(I, 1) + 0.4 < SUMR .AND. KBO(I, 2) > 0)
     1        THEN
              NOTE = 'S'
            ELSE
              NOTE = ' '
            END IF
C * BOND PRECISION SELECTION
            IF (KBO(I, 5) > 0 .AND. BOK(I, 6) > BNDPX) THEN
              IF (LMT(L, 1) /= ' H' .AND. LMT(L, 1) /= ' D' .AND.
     1            LMT(L, 1) /= 'Hw') THEN
                BNDTP(1) = LMT(K, 1)//'-'//LMT(L, 1)
                BNDPX    = BOK(I, 6)
              END IF
            END IF
            IF (IGBL(63) > 2) THEN
              CALL PLA262 (2)
              WRITE (LU7, 99998, IOSTAT = IOST)
     1          LMT(K, 1), HYB1, LMT(L, 1), HYB2, KBO(I, 2), BNDPR,
     2          (BOK(I, J), J = 1, 3), SUMR, NOTE, IDM(1:71)
            END IF
          END DO
          IF (PAR(318) > 0) THEN
            BNDTP(1) = '  C-C'
          ELSE
            PAR(318) = BNDPX
          END IF
          IF (IGBL(63) > 3) THEN
            CALL PLA262 (22)
            WRITE (LU7, 99997, IOSTAT = IOST)
            WRITE (LU7, 99996, IOSTAT = IOST)
          END IF
        END IF
        IF (IPR(315) /= 0) THEN
          RATIO = FLOAT (IPR(316)) / FLOAT (IPR(315))
C * ALERT _763
          IF (RATIO < 1.0 .AND. IGBL(8) == 3)
     1      CALL PLA236 (763, 2, 1.0 - RATIO, RATIO, ' ', ' ')
C * ALERT _764
          IF (RATIO > 1.1)
     1      CALL PLA236 (764, 2, -999.0, RATIO, ' ', ' ')
        END IF
      ELSE
C * INITIALIZE (MODE = 0)
        IPR(47)  = 0
        IPR(317) = 0
        PAR(318) = 0
        DO I = 1, NP8
          DO J = 1, 5
            KBO(I, J) = 0
          END DO
          DO J = 1, 6
            BOK(I, J) = 0.0
          END DO
        END DO
      END IF
      RETURN
99999 FORMAT ('Statistics of Bond Length per Bond Type (NOTE: ',
     1 'A Indicates 10 Occurrences, B Indicates 11, Etc. and',
     2 ' * more than 35)', /, 132('='), //, 'Bond Type   Nr', 4X,
     3 'B.P.', 2X, 'd(min)', 2X, 'd(max)', 3X, 'd(av) Sumrad Note',
     4 2X, '0.0', 7X, '0.5', 7X, '1.0', 7X, '1.5', 7X, '2.0', 7X,
     5 '2.5', 7X, '3.0 Angstrom', /, 58('-'), 3X, 35('I-'), 'I')
99998 FORMAT (2A, ' -- ', 2A, I4, A, 3F8.4, F7.2, 4X, A, 3X, A, /)
99997 FORMAT (//, 'Selected Bond Lengths (Angstrom) - ',
     1 'see M.F.C. Ladd & R.A. Palmer, ',
     2 'Structure Determination by X-ray Crystallography (1985)', /,
     3 132('='), //, 49X, 'Formal single bonds', /, 49X, 19('-'), /,
     4 'C4-C4 1.54   C4-C3 1.52   C4-C2 1.46   C4-N3 1.47   C4-N2 ',
     5 '1.47   C4-O2 1.43   C3-C3 1.46   C3-C2 1.45   C3-N3 1.40   ',
     6 'C3-N2 1.40', /, 'C3-O2 1.36   C2-C2 1.38   C2-N3 1.33   C2-N2',
     7 ' 1.33   C2-O2 1.36   N3-N3 1.45   N3-N2 1.45   N3-O2 1.36   ',
     8 'N2-N2 1.45   N2-O2 1.41', //, 49X, 'Formal double bonds', /,
     9 49X, 19('-'), /, 'C3-C3 1.34   C3-C2 1.31   C3-N2 1.32   C3-O1',
     * ' 1.22   C2-C2 1.28   C2-N2 1.32   C2-O1 1.16   N3-O1 1.24   ',
     1 'N2-N2 1.25   N2-O1 1.21', /)
99996 FORMAT ('Formal triple bonds', 17X,
     1 'Aromatic bonds', /, 19('-'), 17X, 14('-'), /, 'C2-C2 1.20',
     2 '   C2-N1 1.16   C3-C3 1.40   C2-N2 1.34   N2-N2 1.35', //,
     3 'The notation in the table indicates the connectivity of the',
     4 ' atoms', //,
     5 'For more detailed standard bond distance tabulations see: ',
     6 'J. Chem. Soc. Perkin II, (1987), S1-S19;', /,
     7 'J. Chem. Soc. Dalton Trans. (1989), S1 - S83 or ',
     8 'International Tables C, (1992), 707-791.')
99995 FORMAT (F8.4)
      END SUBROUTINE PLA098
 
      SUBROUTINE PLA099 (MODE, IAT, NANG, ANG1, ANG2, ANG3, NOTE1)
C * GET ATOM CHARACTERISTICS (HYBRIDYSATION ETC.)
      USE parameters
      USE plato
      USE atomdata
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: K1
      INTEGER :: NC
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: KAT
      INTEGER :: NAT
      INTEGER :: NO1
      INTEGER :: NO2
      INTEGER :: NC0
      INTEGER :: IHAT
      INTEGER :: IHYB
      INTEGER :: MSKP
      INTEGER :: MODE
      INTEGER :: NANG
      INTEGER :: IMET
      INTEGER :: NMET
      INTEGER :: NHAT
      INTEGER :: NATX
      INTEGER :: IVL1
      INTEGER :: IVAL
      INTEGER :: NATH
      INTEGER :: JUNK
      INTEGER :: NCEFF
      INTEGER :: NBOBO
      INTEGER :: ISHCN
      INTEGER :: IPPIAT
      INTEGER :: IPPJAT
      INTEGER :: IPPKAT
      INTEGER :: JATPART
      INTEGER :: KATPART
      REAL :: ANG
      REAL :: EFNC
      REAL :: ENCH
      REAL :: DIS0
      REAL :: DISM
      REAL :: DIST
      REAL :: ANG1
      REAL :: ANG2
      REAL :: ANG3
      CHARACTER(len=1) :: NOTE1
C * MODE = 0 - MAJOR DISORDER RUN
C * MODE = 1 - FULL RUN
      CALL GEN048 (-1, IFG(1, IAT), 19, IMET)
      NMET = 0
C * GET NUMBER OF PRIMARY ATOMS
      NATX = IPR(37)
C * GET NUMBER OF ATOMS IN EXPANDED ATOM LIST
      NAT  = IPR(39)
C * GET ELEMENT TYPE
      CALL GEN048 (-4, IFG(1, IAT), 15, NO1)
      NO1 = NO1 + 1
C * GET POPULATION PARAMETER ATOM I
      CALL GEN048 (-8, IFG(2, IAT), 1, IPPIAT)
      IPPIAT = IPPR(IPPIAT + 1, 1)
C * GET # OF CONNECTIONS TO ATOM
      NC = - NINT (CON(IAT, 9))
      IF (NC < 0) THEN
        NC = 9
        CALL GEN048 (-1, IFG(1, IAT), 8, IVAL)
        IF (IVAL > 0) NC = NC + IPR(76)
      END IF
      MSKP  = 0
   10 NANG  = 0
      ANG3  = 0.0
      ANG2  = 0.0
      EFNC  = 0.0
      ENCH  = 0.0
      DISM  = 99.0
      ISHCN = 0
      NHAT  = 0
      IF (NC > 0) THEN
        ANG1 = 9999.0
        NMET = 0
C * LOOP OVER NC CONNECTIONS TO ATOM IAT
        DO J = 1, NC
          IF (J <= 9) THEN
            JAT = NINT (CON(IAT, J))
          ELSE
            IF (IBON(J - 9, 1) /= IAT) CYCLE
            JAT = IBON(J - 9, 2)
          END IF
          CALL GEN048 (-5, IFG(3, JAT), 14, JATPART)
          JATPART = JATPART - 16
          CALL GEN048 (-1, IFG(1, JAT), 7, IHAT)
          NHAT = NHAT + IHAT
C * CHECK FOR CARBON
          IF (IEN(NO1) == 2) THEN
C * GET ELEMENT TYPE JAT
            CALL GEN048 (-4, IFG(1, JAT), 15, NO2)
            NO2 = NO2 + 1
C * CHECK FOR NITROGEN
            IF (IEN(NO2) == 4) THEN
              CALL PLA050 (JAT, IAT, 0, 0, DIS0)
              IF (DIS0 < 1.35) ISHCN = 1
            END IF
          END IF
          IF (IHAT == 0) THEN
            CALL PLA050 (JAT, IAT, 0, 0, DIS0)
            DISM = MIN (DISM, DIS0)
          END IF
C * CHECK FOR METAL
          CALL GEN048 (-1, IFG(1, JAT), 19, IVL1)
          IF (MSKP * IVL1 /= 1) THEN
            NMET = NMET + IVL1
C * GET POPULATION PARAMETER
            CALL GEN048 (-8, IFG(2, JAT), 1, IPPJAT)
            IPPJAT = IPPR(IPPJAT + 1, 1)
            IF (IPPJAT == 10000) THEN
              EFNC = EFNC + 1.0
            ELSE
              IF (IPPIAT /= 0) THEN
                EFNC = EFNC + FLOAT (IPPJAT) / FLOAT (IPPIAT)
              END IF
            END IF
C * HANDLE HYDROGEN
            CALL GEN048 (-1, IFG(1, JAT), 7, IHAT)
            IF (IHAT == 1) THEN
              ENCH = ENCH + FLOAT (IPPJAT) / FLOAT (IPPIAT)
            END IF
            IF (J < NC) THEN
              K1 = J + 1
C * JAT-IAT-KAT ANGLE LOOP
              DO K = K1, NC
                IF (K <= 9) THEN
                  KAT = NINT (CON(IAT, K))
                ELSE
                  IF (IBON(K - 9, 1) /= K) CYCLE
                  KAT = IBON(K - 9, 2)
                END IF
                CALL GEN048 (-5, IFG(3, KAT), 14, KATPART)
                KATPART = KATPART - 16
                JUNK = 0
                IF (JATPART == 0 .OR. KATPART == 0) THEN
                  JUNK = 1
                ELSE IF (JATPART == KATPART) THEN
                  JUNK = 1
                END IF
                IF (JUNK == 1) THEN
C * GET POPULATION PARAMETERS
                  CALL GEN048 (-8, IFG(2, KAT), 1, IPPKAT)
                  IPPKAT = IPPR(IPPKAT + 1, 1)
                  IF (IPPJAT > 0 .AND. IPPKAT > 0) THEN
                    IF (IPPJAT == 10000 .OR. IPPJAT == IPPKAT .OR.
     1                MODE == 0) THEN
                      CALL PLA050 (JAT, IAT, KAT, 0, ANG)
                      IF (IEN(NO1) == 2 .AND. IVL1 == 1 .AND.
     1                  ANG <= 85) THEN
                        MSKP = 1
                        GO TO 10
                      END IF
                      NANG = NANG + 1
                      ANG2 = MAX (ANG2, ANG)
                      ANG1 = MIN (ANG1, ANG)
                      ANG3 = ANG3 + ANG
                    END IF
                  END IF
                END IF
              END DO
            END IF
          END IF
        END DO
        IF (NHAT == 0) ISHCN = 0
        IF (NANG > 0) THEN
          ANG3 = ANG3 / NANG
        ELSE
          ANG1 = 0.0
        END IF
      ELSE
        ANG1 = 0.0
      END IF
      IHYB = 0
      IF (MODE == 0) THEN
        NCEFF = NC
      ELSE
        NCEFF = NINT(EFNC + 0.001)
      END IF
C * TEST FOR BORANE
      IF (IEN(NO1) == 20) THEN
        NBOBO = 0
        IF (NC > 0) THEN
          DO J = 1, NC
            IF (J <= 9) THEN
              JAT = NINT (CON(IAT, J))
C * GET ELEMENT TYPE
              CALL GEN048 (-4, IFG(1, JAT), 15, NO2)
              NO2 = NO2 + 1
              IF (IEN(NO2) == 20) NBOBO = NBOBO + 1
              IF (NBOBO == 2) THEN
                CALL GEN048 (1, IFG(2, IAT), 13, 1)
                EXIT
              END IF
            END IF
          END DO
        END IF
      END IF
C * TEST FOR (C, N, SI) HYBRIDISATION (PRINT FOR ASYMMETRIC UNIT ONLY)
      IF (IAT <= NAT) THEN
C * CHECK FOR C & SI
        IF (IEN(NO1) == 2 .OR. IEN(NO1) == 85) THEN
          IF (ANG1 < 35.0) NOTE1 = 'A'
          IF (NCEFF == 4) THEN
            IF (ABS (ANG3 - 108.0) < 2.5) THEN
              IF (NMET == 2) THEN
                IHYB = 2
              ELSE
                IF (ISHCN == 1) NOTE1 = 'H'
                IHYB = 3
              END IF
            END IF
            IF (ANG2 > 125.0 .AND. ANG1 > 61
     1                          .AND. IMET == 0) THEN
              NOTE1    = 'A'
            END IF
C * SP2
          ELSE IF (NCEFF == 3) THEN
            IF (ABS (ANG3 - 120.0) < 4.0) THEN
              IHYB = 2
            END IF
C * SP1
          ELSE IF (NCEFF == 2) THEN
            IF (ABS (ANG3 - 180.0) < 15.0) THEN
              IHYB = 1
            END IF
          ELSE IF (NCEFF == 1) THEN
            IF (MODE == 1 .AND. IAT <= NATX)
     1          IPR(401) = IPR(401) + 1
C * HANDLE TERMINAL C=-N- (TRIPLE BOND)
            IF (IEN(NO1) == 2) THEN
              IF (IEN(NO2) == 4) THEN
                IF (DISM < 1.2) IHYB = 1
                NOTE1 = ' '
              END IF
            ELSE
              NOTE1    = '?'
            END IF
          END IF
          IF (IHYB == 0 .AND. IMET == 0) THEN
            IF (IEN(NO1) == 2) THEN
              IF (MODE == 1 .AND. IAT <= NATX) THEN
                  IF (ABS (NCEFF - EFNC) < 0.002)
     1                IPR(402) = IPR(402) + 1
              END IF
              NOTE1 = '?'
            END IF
          END IF
C * CHECK FOR OXYGEN
        ELSE IF (IEN(NO1) == 3) THEN
          IF (NC == 2) THEN
            IHYB = 3
          ELSE IF (NC == 1) THEN
            CALL PLA050 (NINT (CON(IAT, 1)), IAT, 0, 0, DIST)
            IHYB = 2
          END IF
C * CHECK FOR NITROGEN
        ELSE IF (IEN(NO1) == 4) THEN
          NC0 = NC - NMET
          IF (NC0 == 1) THEN
            CALL PLA050 (NINT (CON(IAT, 1)), IAT, 0, 0, DIST)
            IF (DIST < 1.2) IHYB = 1
          ELSE IF (NC0 == 2 .AND. DISM < 1.35 .AND. DISM > 1.2)
     1      THEN
            IHYB = 2
          ELSE IF (NC0 == 3) THEN
            IF (ABS (ANG3 - 120.0) < 3.0) THEN
C * (CHECK) .AND. DISM < 1.335) IHYB = 2
              IHYB = 2
            ELSE IF (ANG3 < 112) THEN
              IHYB = 3
            END IF
          ELSE IF (NC0 == 4 .AND. ABS (ANG3 - 109.5) < 1.0) THEN
            IHYB = 3
          END IF
C * CHECK FOR P & S
        ELSE IF (IEN(NO1) == 8 .OR. IEN(NO1) == 6) THEN
          IF (NC == 4 .AND. ABS (ANG3 - 109.5) < 1.0) IHYB = 3
        END IF
      END IF
      IF (IAT <= NATX .AND. IHYB == 0) THEN
        IF (ANG1 < 90.0 .AND. ANG1 > 0.1) THEN
          IF (NO1 == 3 .AND. NC == 2) THEN
            NOTE1 = ' '
          ELSE IF (IMET == 0 .AND. NC < 6 .AND.
     1             IEN(NO1) /= 92) THEN
            NOTE1 = 'A'
          END IF
        END IF
      END IF
      NATH = MIN (NINT (ENCH), 7)
      CALL GEN048 (4, IFG(1, IAT), 24, IHYB)
      CALL GEN048 (3, IFG(2, IAT), 24, NATH)
      CALL GEN048 (3, IFG(3, IAT), 25, NHAT)
      CALL GEN048 (4, IFG(3, IAT), 28, NCEFF)
      RETURN
      END SUBROUTINE PLA099
 
      SUBROUTINE PLA100
C * CALCULATE CELL PARAMETERS AND ORTHOGONAL AXIAL SYSTEM
C * REF. SEE DUNITZ, XRAY ANALYSIS ..., P236
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: N
      INTEGER :: N90
      INTEGER :: MSET
      INTEGER :: NZERO
      INTEGER :: IYUNK
      INTEGER :: IPR293
      INTEGER :: IPR313
      INTEGER :: GEN152
      REAL :: R
      REAL :: DET
      REAL :: XDUM
      REAL :: YUNK
      REAL :: YUNK1
      REAL :: GEN068
      REAL :: AXISMAX
      REAL :: AXISMIN
      REAL :: AXISRAT
C * PAR(101) = A         ; (113) = A*         ; (125) =
C *    (102) = B         ; (114) = B*         ; (126) =
C *    (103) = C         ; (115) = C*         ; (127) =
C *    (104) = ALPHA     ; (116) = COS(ALPHA*); (128) =
C *    (105) = BETA      ; (117) = COS(BETA*) ; (129) = A*A
C *    (106) = GAMMA     ; (118) = COS(GAMMA*); (130) = B*B
C *    (107) = SIG(A)    ; (119) = SIN(ALPHA*); (131) = C*C
C *    (108) = SIG(B)    ; (120) = SIN(BETA*) ; (132) = 2*A*B*COS(GAMMA)
C *    (109) = SIG(C)    ; (121) = SIN(GAMMA*); (133) = 2*A*C*COS(BETA)
C *    (110) = SIG(ALPHA); (122) = SIG(ALFA*) ; (134) = 2*B*C*COS(ALPHA)
C *    (111) = SIG(BETA) ; (123) =
C *    (112) = SIG(GAMMA); (124) =
C * AA  & BB  ARE DIRECT AND RECIPROCAL METRIC FOR COORDINATES CELL
C * RAA & RBB ARE DIRECT AND RECIPROCAL METRIC FOR REFLECTION CELL
C * CHECK FOR PREVIOUS INVOCATION OF THIS ROUTINE
      IF (IPR(786) == 0) THEN
C * NO ATOMS READ YET ?
        IF (IPR(39) == 0) THEN
C * CHECK FOR MAXIMUM ALLOWED RESIDUE NUMBER (ARU = sklm.xx or sklm.y)
C * ANGSTROM COORDINATES ? (I.E. NO CELL DATA)
          IF (PAR(101) < 1.1) THEN
            IGBL(52) = 1
            IPR(23)  = 1
            IPR(34)  = 1
            IPR(35)  = 2
            IPR(36)  = 3
            CALL GEN021 (OR, 1.0)
            CALL GEN021 (AA, 1.0)
          ELSE
C * FRACTIONAL COORDINATES : GET SPACE GROUP INFO
            CALL SGSM (-18, ICL, SGY, 0, 0, IERR)
            SPGRNM(1) = ICL(1:26)
            SPGRNM(4) = ICL(15:26)
            IF (IGBL(8) == 3 .AND. IPR(522) == 0) THEN
C * ALERT _123
              IF (SPGRNM(1)(1:1) == ' ')
     1          CALL PLA236 (123, 0, 1.0, 1.0, ' ', ' ')
            END IF
C * GET CRYSTAL SYSTEM
            KRSYST(2) = ICL(27:38)
            LAUEGR    = ICL(39:43)
            CALL GEN020 (-1, KRSYST(2), 1, 12)
            IF (ICL(72:72) == 'C') THEN
              CHSG    = 'Chiral'
C * SET NO INVERT FLAG FOR NON-CENTRO (DEFAULT)
              IPR(33) = 1
            END IF
C * LOWER CASE HANDLING
            CALL GEN020 (-1, SPGRNM(1), 16, 26)
C * ISGNR
            IPR(202) = NINT (SGY(1))
            IPR(241) = NINT (SGY(7))
            IPR(242) = NINT (SGY(8))
C * NSYMP
            IPR(255) = NINT (SGY(4))
C * IBV
            IPR(256) = NINT (SGY(6))
C * ICENTR
            IPR(257) = NINT (SGY(5))
C * LAUE
            IPR(258) = NINT (SGY(3))
C * IKLS
            IPR(259) = NINT (SGY(2))
C * IFLACK
            IPR(137) = NINT (SGY(13))
C * MONOCLINIC SETTING (a/b/c) = (1, 0, 3)
            IPR(783) = NINT (SGY(14))
            IF (ICL(12:12) == 'h') THEN
              PAR(261) = 120.0
            ELSE
              PAR(261) = 90.0
            END IF
          END IF
          IF (PAR(104) == 0.0) PAR(104) = 90.0
          IF (PAR(105) == 0.0) PAR(105) = 90.0
          IF (PAR(106) == 0.0) PAR(106) = PAR(261)
          PAR(13) = 0
          PAR(14) = 0
C * SOLVE TRIGONAL/RHOMBOHEDRAL ISSUE
          IF (INDEX (KRSYST(2), 'trigonal') /= 0) THEN
            IF (ABS (PAR(106) - PAR(105)) < 0.5) THEN
              KRSYST(2) = 'rhombohedral'
            END IF
          END IF
C * TEST IS NOT DONE FOR 'NON-CSD CIF' AND 'CELL-CHECK '
          IF (IGBL(94) == 0 .AND. IPR(522) == 0) THEN
C * TEST SU A-AXIS
            YUNK    = PAR(107) / PAR(101)
            AXISMIN = MIN (PAR(101), PAR(102), PAR(103))
            AXISMAX = MAX (PAR(101), PAR(102), PAR(103))
            AXISRAT = (AXISMAX - AXISMIN) / AXISMIN
            IF (YUNK < 0.000001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _141
              CALL PLA236 (141, 5, YUNK1, PAR(107), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 3, 1.0, PAR(107), '     a ', ' ')
            END IF
C * TRICLINIC CASE
            IF (INDEX (KRSYST(2), 'triclinic') /= 0) THEN
C * TEST SU B-AXIS
              YUNK = PAR(108) / PAR(102)
              IF (YUNK < 0.000001) THEN
                IF (YUNK > 0.0) THEN
                  YUNK1 = -999.0
                ELSE
                  YUNK1 = 1.0
                ENDIF
C * ALERT _142
              CALL PLA236 (142, 5, YUNK1, PAR(108), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 3, 1.0, PAR(108), '     b ', ' ')
            END IF
C * TEST SU C-AXIS
            YUNK = PAR(109) / PAR(103)
            IF (YUNK < 0.000001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _143
              CALL PLA236 (143, 5, YUNK1, PAR(109), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 3, 1.0, PAR(109), '     c ', ' ')
            END IF
C * TEST FOR EQUAL CELL AXES SU's
            IF (PAR(107) > 0.00001 .AND. AXISRAT > 0.5) THEN
C * ALERT _153
              IF (PAR(107) == PAR(108) .AND. PAR(108) == PAR(109))
     1          THEN
C * ESTABLISH RELEVANT NUMBER OF DECIMALS
                N = GEN152 (PAR(107))
                CALL PLA236 (153, N, -999.0, PAR(107), ' ', ' ')
              END IF
            END IF
C * TEST SU ON ALPHA
            IF (PAR(110) < 0.0005) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _144
              CALL PLA236 (144, 4, YUNK1, PAR(110), ' ', ' ')
            ELSE IF (PAR(110) > 0.05) THEN
C * ALERT _149
              CALL PLA236 (149, 2, PAR(110), PAR(110), ' alpha ', ' ')
            END IF
C * TEST SU ON BETA
            IF (PAR(111) < 0.0005) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _145
              CALL PLA236 (145, 4, YUNK1, PAR(111), ' ', ' ')
            ELSE IF (PAR(111) > 0.05) THEN
C * ALERT _149
              CALL PLA236 (149, 2, PAR(111), PAR(111), '  beta ', ' ')
            END IF
C * TEST SU ON GAMMA
            IF (PAR(112) < 0.0005) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _146
              CALL PLA236 (146, 4, YUNK1, PAR(112), ' ', ' ')
            ELSE IF (PAR(112) > 0.05) THEN
C * ALERT _149
              CALL PLA236 (149, 2, PAR(112), PAR(112), ' gamma ', ' ')
            END IF
C * ALERT _154 - TEST FOR EQUAL CELL ANGLE SU's
            IF (PAR(110) == PAR(111) .AND. PAR(111) == PAR(112))
     1        THEN
              IF (PAR(110) > 0.0) THEN
C * ESTABLISH RELEVANT NUMBER OF DECIMALS
                N = GEN152 (PAR(110))
                CALL PLA236 (154, N, -999.0, PAR(110), ' ', ' ')
              END IF
            END IF
C * ALERT _156
C * MONOCLINIC CASE
          ELSE IF (INDEX (KRSYST(2), 'monoclinic') /= 0) THEN
            IYUNK = INDEX (SPGRNM(3), 'y')
C * CHECK FOR ALL ANGLES EXACTLY 90 DEGREES IN MONOCLINIC
            N90  = 0
            MSET = 0
            IF (PAR(104) /= 90.0) THEN
              N90  = N90 + 1
              MSET = 1
            END IF
            IF (PAR(105) /= 90.0) THEN
              N90  = N90 + 1
              MSET = 2
            END IF
            IF (PAR(106) /= 90.0) THEN
              N90  = N90 + 1
              MSET = 3
            END IF
            IF (N90 == 0) THEN
C * ALERT _181
              CALL PLA236 (181, 0, 1.0, 1.0, ' ', ' ')
              IF (PAR(110) + PAR(111) + PAR(112) == 0.0) THEN
C * ALERT _182
                CALL PLA236 (182, 0, 1.0, 1.0, ' ', ' ')
              END IF
            ELSE IF (N90 == 1) THEN
C * ALERT _159
              IF (IYUNK == 0 .AND. PAR(105) /= 90.0)
     1          CALL PLA236 (159, 0, 1.0, 1.0, ' ', ' ')
            ELSE IF (N90 > 1) THEN
C * ALERT _138 - MORE THAN ONE CELL ANGLE /= 90
              CALL PLA236 (138, 0, 1.0, 1.0, ' ', ' ')
            END IF
C * TEST SU B-AXIS
            YUNK = PAR(108) / PAR(102)
            IF (YUNK < 0.00001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _142
              CALL PLA236 (142, 5, YUNK1, PAR(108), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 4, 1.0, PAR(108), '     b ', ' ')
            END IF
C * TEST SU C-AXIS
            YUNK = PAR(109) / PAR(103)
            IF (YUNK < 0.00001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _143
              CALL PLA236 (143, 5, YUNK1, PAR(109), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 3, 1.0, PAR(109), '     c ', ' ')
            END IF
C * TEST FOR EQUAL CELL AXES SU's
            IF (PAR(107) > 0.00001 .AND. AXISRAT > 0.5) THEN
C * ALERT _153
              IF (PAR(107) == PAR(108) .AND. PAR(108) == PAR(109))
     1          THEN
C * ESTABLISH RELEVANT NUMBER OF DECIMALS
                N = GEN152(PAR(107))
                CALL PLA236 (153, N, -999.0, PAR(107), ' ', ' ')
              END IF
            END IF
            IF (MSET == 1) THEN
C * TEST SU ON ALPHA
              IF (PAR(110) < 0.0005) THEN
                IF (YUNK > 0.0) THEN
                  YUNK1 = -999.0
                ELSE
                  YUNK1 = 1.0
                ENDIF
C * ALERT _145
                CALL PLA236 (145, 4, YUNK1, PAR(110), ' ', ' ')
              ELSE IF (PAR(110) > 0.05) THEN
C * ALERT _149
                CALL PLA236 (149, 2, 1.0, PAR(110), ' alpha ', ' ')
              END IF
            ELSE IF (MSET == 2) THEN
C * TEST SU ON BETA
              IF (PAR(111) < 0.0005) THEN
                IF (YUNK > 0.0) THEN
                  YUNK1 = -999.0
                ELSE
                  YUNK1 = 1.0
                ENDIF
C * ALERT _145
                CALL PLA236 (145, 4, YUNK1, PAR(111), ' ', ' ')
              ELSE IF (PAR(111) > 0.05) THEN
C * ALERT _149
                CALL PLA236 (149, 2, 1.0, PAR(111), '  beta ', ' ')
              END IF
            ELSE IF (MSET == 3) THEN
C * TEST SU ON GAMMA
              IF (PAR(112) < 0.0005) THEN
                IF (YUNK > 0.0) THEN
                  YUNK1 = -999.0
                ELSE
                  YUNK1 = 1.0
                ENDIF
C * ALERT _146
                CALL PLA236 (146, 4, YUNK1, PAR(112), ' ', ' ')
              ELSE IF (PAR(112) > 0.05) THEN
C * ALERT _149
                CALL PLA236 (149, 2, 1.0, PAR(112), ' gamma ', ' ')
              END IF
            END IF
C * ALERT _157
            IF (PAR(105) < 90.0)
     1        CALL PLA236 (157, 2, 1.0, PAR(105), ' ', ' ')
            IF (PAR(104) == 90.0 .AND. PAR(105) /= 90.0 .AND.
     1          PAR(106) == 90.0) THEN
C * ALERT _147
              IF (PAR(110) /= 0.0 .OR. PAR(112) /= 0.0)
     1          CALL PLA236 (147, 0, 1.0, 1.0, ' ', ' ')
            END IF
C * ORTHORHOMBIC CASE
C * ALERT _137
          ELSE IF (INDEX (KRSYST(2), 'orthorhombic') /= 0) THEN
            IF (PAR(104) /= 90.0 .OR. PAR(105) /= 90.0 .OR.
     1          PAR(106) /= 90.0) CALL PLA236 (137, 0, 1.0, 1.0,
     2                                           ' ', ' ')
C * TEST SU B-AXIS
            YUNK = PAR(108) / PAR(102)
            IF (YUNK < 0.00001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _142
              CALL PLA236 (142, 5, YUNK1, PAR(108), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 4, 1.0, PAR(108), '     b ', ' ')
            END IF
C * TEST SU C-AXIS
            YUNK = PAR(109) / PAR(103)
            IF (YUNK < 0.00001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _143
              CALL PLA236 (143, 5, YUNK1, PAR(109), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 3, 1.0, PAR(109), '     c ', ' ')
            END IF
C * TEST FOR EQUAL CELL AXES SU's
            IF (PAR(107) > 0.00001 .AND. AXISRAT > 0.5) THEN
C * ALERT _153
              IF (PAR(107) == PAR(108) .AND. PAR(108) == PAR(109))
     1          THEN
C * ESTABLISH RELEVANT NUMBER OF DECIMALS
                N = GEN152 (PAR(107))
                CALL PLA236 (153, N, -999.0, PAR(107), ' ', ' ')
              END IF
            END IF
C * ALERT _147
            IF (PAR(110) /= 0.0 .OR. PAR(111) /= 0.0 .OR.
     1          PAR(112) /= 0.0)
     2            CALL PLA236 (147, 0, 1.0, 1.0, ' ', ' ')
C * TETRAGONAL CASE
          ELSE IF (INDEX (KRSYST(2), 'tetragonal') /= 0) THEN
C * ALERT _135
            IF (PAR(101) /= PAR(102))
     1        CALL PLA236 (135, 0, 1.0, 1.0, ' ', ' ')
C * TEST SU C-AXIS
            YUNK = PAR(109) / PAR(103)
            IF (YUNK < 0.00001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
C * ALERT _143
              CALL PLA236 (143, 5, YUNK1, PAR(109), ' ', ' ')
            ELSE IF (YUNK > 0.001) THEN
C * ALERT _148
              CALL PLA236 (148, 3, 1.0, PAR(109), '     c ', ' ')
            END IF
C * ALERT _136
            IF (PAR(104) /= 90.0 .OR. PAR(105) /= 90.0 .OR.
     1          PAR(106) /= 90.0)
     2            CALL PLA236 (136, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _147
            IF (PAR(110) /= 0.0 .OR. PAR(111) /= 0.0 .OR.
     1          PAR(112) /= 0.0)
     2            CALL PLA236 (147, 0, 1.0, 1.0, ' ', ' ')
C * RHOMBOHEDRAL CASE
          ELSE IF (INDEX (KRSYST(2), 'rhombohedral') /= 0) THEN
C * ALERT _139
            IF (PAR(101) /= PAR(102) .OR. PAR(101) /= PAR(103))
     1        CALL PLA236 (139, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _140
            IF (PAR(104) /= PAR(105) .OR. PAR(104) /= PAR(106))
     1        CALL PLA236 (140, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _144
            IF (PAR(110) < 0.0005) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
              CALL PLA236 (144, 4, YUNK1, PAR(110), ' ', ' ')
            END IF
C * TRIGONAL/HEXAGONAL CASE
          ELSE IF (INDEX (KRSYST(2), 'trigonal') /= 0 .OR.
     1             INDEX (KRSYST(2), 'hexagonal') /= 0) THEN
C * ALERT _132
            IF (PAR(101) /= PAR(102))
     1        CALL PLA236 (132, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _133
            IF (PAR(104) /= 90.0 .OR. PAR(105) /= 90.0)
     1        CALL PLA236 (133, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _134
            IF (PAR(106) /= 120.0)
     1        CALL PLA236 (134, 0, 1.0, 1.0, ' ', ' ')
C * TEST SU C-AXIS
            YUNK = PAR(109) / PAR(103)
C * ALERT _143
            IF (YUNK < 0.00001) THEN
              IF (YUNK > 0.0) THEN
                YUNK1 = -999.0
              ELSE
                YUNK1 = 1.0
              ENDIF
              CALL PLA236 (143, 5, YUNK1, PAR(109), ' ', ' ')
C * ALERT _148
            ELSE IF (YUNK > 0.001) THEN
              CALL PLA236 (148, 3, 1.0, PAR(109), '     c ', ' ')
            END IF
C * CUBIC CASE
          ELSE IF (INDEX (KRSYST(2), 'cubic') /= 0) THEN
C * ALERT _130
            IF (PAR(101) /= PAR(102) .OR. PAR(101) /= PAR(103))
     1        CALL PLA236 (130, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _131
            IF (PAR(104) /= 90.0 .OR. PAR(105) /= 90.0 .OR.
     1        PAR(106) /= 90.0) CALL PLA236 (131, 0, 1.0, 1.0,
     2         ' ', ' ')
C * ALERT _147
            IF (PAR(110) /= 0.0 .OR. PAR(111) /= 0.0 .OR.
     1          PAR(112) /= 0.0)
     2            CALL PLA236 (147, 0, 1.0, 1.0, ' ', ' ')
          END IF
        END IF
        IF (IABS (IGBL(8)) /= 3)
     1    WRITE (LU6, 99998) (PAR(I), I = 101, 106)
C * SET UP METRICAL MATRIX FOR UNTRANSFORMED INPUT CELL
        CALL GEN026 (1, RAA, PAR(101))
C * COPY/STORE UNTRANSFORMED CELL PARAMETERS
        CALL GEN113 (PAR(101), PAR(241), 6)
C * CALCULATE INVERSE MATRIX
        CALL GEN003 (RAA, RBB, DET, 0)
C * CALL EXIT/STOP
        IF (DET < 0.0) CALL GEN127 ('CANNOT INVERT METRICAL MATRIX')
C * GET UNTRANSFORMED RECIPROCAL CELL PARAMETERS (PAR(135) - PAR(140))
        CALL GEN026 (-1, RBB, PAR(135))
        CALL GEN025 (RBB, PAR(391), 1)
C * APPLY AXES TRANSFORMATION
        CALL GEN001 (1, TM1, RAA, AA)
C * CALCULATE INVERSE METRIC AND VOLUME
        CALL GEN003 (AA, BB, DET, 0)
C * CALL EXIT/STOP
          IF (DET < 0.0) CALL GEN127 ('CANNOT INVERT METRICAL MATRIX')
          PAR(98) = SQRT(DET)
          DO I = 1, 3
            PAR(128 + I) = AA(I, I)
            PAR(112 + I) = SQRT(BB(I, I))
            PAR(190 + I) = BB(I, I)
          END DO
          PAR(194) = BB(2, 3)
          PAR(195) = BB(1, 3)
          PAR(196) = BB(1, 2)
          PAR(132) = AA(1, 2) * 2.0
          PAR(133) = AA(1, 3) * 2.0
          PAR(134) = AA(2, 3) * 2.0
          CALL GEN026 (-1, AA, PAR(101))
C * TRANSFORM CELL-ESD'S
          CALL GEN067 (TM1, PAR(241), PAR(101), PAR(107), PAR(107))
C * APPLY SYMMETRY CONSTRAINTS ON CELL DIMENSIONS
          CALL GEN066 (1, PAR(101), PAR(107), SPGRNM(1)(12:12),
     1      IPR(783))
C * ROUND CELL PARAMETERS
          NZERO = 0
          DO I = 1, 3
C * A,B,C
            CALL GEN041 (PAR(100 + I), PAR(106 + I), IPR(280 + I), 5,
     1         IPR(286 + I), IPR(68))
            IF (IPR(280 + I) > 0) THEN
              IF (MOD (NINT (PAR(100 + I) * 10 ** IPR(286 + I)), 10)
     1          == 0) THEN
                IF (IPR(280 + I) == 10) THEN
                  IPR(280 + I) = 1
                  IPR(286 + I) = IPR(286 + I) - 1
                ELSE
                  NZERO = NZERO + 1
                END IF
              END IF
            END IF
 
C * ALPHA, BETA, GAMMA
            CALL GEN041 (PAR(103 + I), PAR(109 + I), IPR(283 + I), 4,
     1           IPR(289 + I), IPR(68))
            IF (IPR(283 + I) > 0) THEN
              IF (MOD (NINT (PAR(103 + I) * 10 ** IPR(289 + I)), 10)
     1          == 0) THEN
                IF (IPR(283 + I) == 10) THEN
                  IPR(283 + I) = 1
                  IPR(289 + I) = IPR(289 + I) - 1
                ELSE
                  NZERO = NZERO + 1
                END IF
              END IF
            END IF
          END DO
C * ALERT _180
          IF (NZERO > 2)
     1      CALL PLA236 (180, 0, -999.0, FLOAT (NZERO), ' ', ' ')
          DO I = 1, 3
            R = PAR(106 + I) / PAR(100 + I)
            IF (R > PAR(13)) PAR(13) = R
            IF (PAR(109 + I) > PAR(14)) PAR(14) = PAR(109 + I)
          END DO
          DO I = 1, 3
            V4(I) = COS (PAR(103 + I) / RGBL(6))
            IF (ABS (V4(I)) < 1E-6) V4(I) = 0.0
            V3(I) = SIN(PAR(103 + I) / RGBL(6))
          END DO
C * CALCULATE SU IN CELL VOLUME
          PAR(21) = GEN068 (PAR(101), PAR(107), IPR(606))
C * ROUND VOLUME
          CALL GEN041 (PAR(98), PAR(21), IPR(293), 3, IPR(294), IPR(68))
          IF (PAR(21) > 0.0) THEN
            XDUM = ABS (PAR(164) - PAR(98)) / PAR(21)
            IF (IPR(522) == 0) THEN
C * ALERT _150
              IF (XDUM > 0.01 .AND. IGBL(94) == 0)
     1          CALL PLA236 (150, 2, XDUM, PAR(164), ' ', ' ')
C * ALERT _152
              IF (PAR(327) > 0.0) THEN
                IYUNK = MAX (IPR(294), IPR(314))
                IPR293 = IPR(293) * 10**(IYUNK - IPR(294))
                IPR313 = IPR(313) * 10**(IYUNK - IPR(314))
                YUNK = IPR293 - IPR313
                IF (ABS (YUNK) > 1.0) THEN
                  CALL PLA236 (152, 0, -999.0, YUNK, ' ', ' ')
                END IF
              END IF
            END IF
          END IF
C * CALCULATE COS(ALFA*),COS(BETA*),COS(GAMMA*)
          PAR(116) = (V4(2) * V4(3) - V4(1)) / (V3(2) * V3(3))
          PAR(117) = (V4(1) * V4(3) - V4(2)) / (V3(1) * V3(3))
          PAR(118) = (V4(1) * V4(2) - V4(3)) / (V3(1) * V3(2))
C * CALCULATE SIN(ALFA*), SIN(BETA*), SIN(GAMMA*)
          DO K = 16, 18
            PAR(103 + K) = SQRT (1.0 - PAR(100 + K)**2)
          END DO
C * ORTHOGONALIZE
          CALL GEN044 (PAR(101), OR, 1)
C * GET INVERSE MATRIX FOR TRANSFORMATION ORTHOGONAL TO FRACTIONAL
          CALL GEN003 (OR, ROR, DET, 0)
C * CALL EXIT/STOP
          IF (DET < 0.0) CALL GEN127 ('CANNOT INVERT MATRIX OR')
          CALL GEN108 (LU4, 0)
          IF (IPR(23) == 0) THEN
            NEWLAT(1) = 0
            CALL PLA266 (1)
          END IF
C * SET FOR VALIDATION CHECK DONE
          IPR(522) = 1
C * SET PLA100 DONE
          IPR(786) = 1
        END IF
        IF (IABS (IGBL(8)) /= 3)
     1    WRITE (LU6, 99997) (PAR(I), I = 101, 106)
      END IF
      RETURN
99999 FORMAT (':: Maximum number of allowed residues reduced:',
     1        ' Round ARU to 0.1 units!', /)
99998 FORMAT (/, ':: PLA100-CELL-IN ', 6F10.4)
99997 FORMAT (':: PLA100-CELL-OUT', 6F10.4, /)
      END SUBROUTINE PLA100
 
      MODULE ortep
      SAVE
      INTEGER :: NB = 0
      INTEGER :: NP = 0
      INTEGER :: NIA
      INTEGER :: NIB
      INTEGER :: NCD
      INTEGER :: NQD
      INTEGER :: KDEL
      INTEGER :: NPOS
      INTEGER :: KDEL1
      INTEGER :: KDEL2
      INTEGER :: NEXIT
      INTEGER :: NATOM
      INTEGER :: NASUP
      INTEGER :: ICHIRAL
      REAL :: T1
      REAL :: T2
      REAL :: T3
      REAL :: T4
      REAL :: T5
      REAL :: T6
      REAL :: T7
      REAL :: T8
      REAL :: T9
      INTEGER, DIMENSION(8, 2) :: LPOS = RESHAPE (
     1 (/ 2, 2, 2, 5, 1, 1, 1, 5, 3, 6, 4, 4, 4, 6, 3, 3 /), (/8, 2/))
      REAL :: PHOR
      REAL :: PVER
      REAL, DIMENSION(2)       :: YMIN
      REAL, DIMENSION(2   )    :: YMAX
      REAL, DIMENSION(3, 3)    :: AAREV
      REAL, DIMENSION(3, 2)    :: V12
      REAL, DIMENSION(3, 3, 2) :: QA
      REAL, DIMENSION(3, 3, 2) :: QC
      REAL, DIMENSION(9)       :: PROBA = (/0.7644, 1.0026, 1.1932,
     1 1.3672, 1.5382, 1.7164, 1.9144, 2.1544, 2.5003/)
 
      END MODULE ortep
 
      SUBROUTINE PLA101
C * ORTEP/ADP MAIN ROUTINE
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      USE ortep
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IA
      INTEGER :: IG
      INTEGER :: IS
      INTEGER :: ISW
      INTEGER :: IPP
      INTEGER :: NCB
      INTEGER :: NDG
      INTEGER :: KAT
      INTEGER :: NID
      INTEGER :: HINC = 0
      INTEGER :: IDET
      INTEGER :: IRES
      INTEGER :: IREF
      INTEGER :: IHAT
      INTEGER :: ISKP
      INTEGER :: IANI
      INTEGER :: META
      INTEGER :: NPOP
      INTEGER :: NSUP
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: IYUNK
      INTEGER :: IATP1
      INTEGER :: IATP2
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      INTEGER :: NLOOP
      REAL :: X
      REAL :: XG
      REAL :: YG
      REAL :: ZG
      REAL :: XB
      REAL :: TD2
      REAL :: TD3
      REAL :: DET
      REAL :: YNK
      REAL :: XLNG
      REAL :: XBND
      REAL :: DUMMY
      REAL, DIMENSION(3, 3) :: QD
      REAL, DIMENSION(3, 3) :: QCC
      REAL, DIMENSION(3, 3) :: TMAT
      REAL, DIMENSION(3, 3) :: YUNK
C * MAIN OF DISPLACEMENT MOTION ELLIPSOID PLOT ROUTINES
C * ARRAYS XXO, XSD & CON WILL BE OVERWRITTEN TEMPORARILY AND RESTORED AT
C * THE END OF THIS ROUTINE (FROM SCRATCH ARRAY VOID)
C * TEMPORARILY MEMORY LAYOUT FOR ADP ROUTINES
C ***********************************************************************C
C *          I       XXO        I       XSD        I      CON  I IATC/   C
C *          I  1:3      4:6    I   1:3      4:6   I      1:9  I  DATC   C
C *----------------------------------------------------------------------C
C *          I  CART. I  CART   I  EIGEN  I  CART  I EIGEN     I         C
C *          I   XYZ  I  XYZ    I VALUES  I  ESD   I VECTORS   I(SELECT) C
C *  IPR(39) I(SELECT)I  (ORIG) I(SELECT) I (ORIG) I(SELECTED) I         C
C * +IPR(64) I        I         I         I        I           I         C
C * = NASUP  I        I         I         I        I           I         C
C *----------------------------------------------------------------------C
C *  NQD     I          I   I   I         I        I           I         C
C *----------------------------------------------------------------------C
C *  IPR(174)I COVER            I CQ      I SEGM   I CB        I QL      C
C ***********************************************************************C
C * CHECK FOR ANGSTROM DATA
C * ARRANGE FOR STRIPPED SPECIAL NON-X-WINDOWS VERSION
      META = 1
C STRIP_BEG
      META = 0
C STRIP_END
      IF (META == 1) CALL GGIP (-999.0, 0.0, 0.0, -2)
 10   IWIN = IGBL(25) * IGBL(32)
C * INITIATE OVERLAP ROUTINES
      KAT   = 0
      NCD   = 0
      NQD   = 0
      PVER  = 0.0
      PHOR  = 0.0
      NEXIT = 0
C * GET NUMBER OF BONDS (EXPANDED)
      NCB   = IPR(131)
C * GET NUMBER OF ATOMS (EXPANDED)
      NATOM = IPR(39)
C * GET NUMBER OF SUPPORT COORDINATES (CG etc)
      NSUP  = IPR(64)
C * TOTAL NUMBER OF ATOMS (REAL AND SUPPORT)
      NASUP = NATOM + NSUP
C * CALCULATE LOCATION FOR ARRAY COVER
      IPR(174) = NASUP + MAX (NASUP, NCB)
C * TEST FOR OVERFLOW XXO
      IF (IPR(174) + NP15 > NP1) THEN
        IPR(2) = 22
        IF (IGBL(3) == 3) IGBL(3) = 0
        RETURN
      END IF
C * SET FOR PLATON/ORTEP MENU NUMBER
      IF (IGBL(6) /= 8 .AND. IGBL(6) /= 9 .AND.
     1    IGBL(6) /= 22) IGBL(6) = 1
C * SELECT ATOMS FOR PLOTTING (BASED ON INCLUDE/RESIDUE STATUS)
   20 IPR(477) = 0
      DO I = 1, NASUP
C * LOAD ORTHOGONAL COORDINATES [IN XXO(1:3)] FROM BACKUP STORAGE 'VOID'
        DO J = 4, 6
          XXO(I, J) = VOID((I - 1) * NP71 + J)
        END DO
C * REGISTER ATOM FOR LEAST-SQUARES PLANE CALCULATION
        IATP(I) = I + NP1
C * GET H-ATOM BIT
        CALL GEN048 (-1, IFG(1, I), 7,  IHAT)
C * GET H-INCLUDE BIT
        CALL GEN048 (-1, IFG(2, I), 12, HINC)
        IF (IGBL(59) /= 0) THEN
C * GET POPULATION PARAMETER
          CALL GEN048 (-8, IFG(2, I), 1, IPP)
          NPOP = IPPR(IPP + 1, 1)
          IF (NPOP < 10000) THEN
            IF (IGBL(88) == 0) THEN
              IF (IPPR(IPP + 1, 1) < 5000) CYCLE
            ELSE
              IF (IPPR(IPP + 1, 1) > 5000) CYCLE
            END IF
          END IF
        END IF
        IF (IHAT /= 1 .OR. HINC /= 0 .OR. IPR(212) /= 0) THEN
          IF (IPR(140) > 0) THEN
C * GET RESIDUE NUMBER
            CALL GEN048 (-6, IFG(1, I), 9, IRES)
            IF (IRES /= IPR(140)) CYCLE
          END IF
          IPR(477) = IPR(477) + 1
          IATP(I)  = I
        END IF
      END DO
C * GET ORIENTATION MATRIX (IGBL(87) = DETERMINANT)
      IF (IGBL(87) == 0) IGBL(87) = 1
      CALL GEN021 (RMAT, FLOAT(IGBL(87)))
C * SET XROT STEP VALUES
      PAR(389) = 0.0
      IPR(479) = 1
C * CHECK FOR MINIMUM OVERLAP/MATRIX CALCULATIONS-PRELIM ORR MATRIX
      IF (IGBL(67) == 0) THEN
C * CALCULATE MINIMUM OVERLAP VIEW: CALCULATE L.S.-PLANE
        CALL PLA054 (0)
C * MAKE LARGEST COMPONENT Z
        DO I = 1, 3
          YNK        =  DUMV(I, 1)
          DUMV(I, 1) = -DUMV(I, 3)
          DUMV(I, 3) =  YNK
        END DO
C * COPY DUMV INTO RMAT
        CALL GEN004 (DUMV, RMAT, YUNK)
        CALL GEN052 (YUNK, RMAT)
        IGBL(67) = 1
      ELSE
C * SETUP RMAT FROM ROTATIONS
        DO I = 1, 3
          X = - RGBL(27 + I) / RGBL(6)
          CALL GEN051 (0, RMAT, X, I)
        END DO
      END IF
      NLOOP = 2
      GO TO 40
C * INTERRUPT INTERCEPT
   30 IF (LRET == 6 .AND. IWIN == 1) THEN
        XG = 0.0
        YG = 0.0
        ZG = 0.0
        IG = 9
        CALL GGIP (XG, YG, ZG, IG)
        IF (IG == 1) CC = .TRUE.
      END IF
C * RESET LABEL POSITION STATUS
      IPR(201) = 0
C * CHECK FOR STEREO OPTION
      IF (IPR(116) == 0) NLOOP = MOD (NLOOP + 1, 2)
C * MOUSE REORIENT LOOP
   40 IPR(478) = 0
   50 IPR(478) = IPR(478) + 1
      IF (CC) GO TO 70
C * SET PROBABILITY LEVEL
      PAR(46) = PROBA(IPR(45))
C * OPEN FILE FOR RASTER3D
      IF (IPR(108) /= 0) THEN
        OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'.rst',
     1                          STATUS = 'UNKNOWN')
        WRITE (LU65, 99996, IOSTAT = IOST) JID(1:50)
        CALL GEN005 (RMAT, TMAT)
      END IF
C * SETUP RELEVANT TRANSFORMATION MATRICES
C * ORIENTATION MATRIX
      IF (IPR(116) == 1) PAR(389) = PAR(389) -9.0 + 6.0 * IPR(478)
      IF (NLOOP >= 1) THEN
        DUMMY = - PAR(389) / RGBL(6)
        CALL GEN051 (0, RMAT, DUMMY, IPR(479))
      END IF
C * CHECK FOR 'NOT' RECALCULATE LABEL POSITION
      IF (LRET /= 6) PAR(389) = 0.0
C * DERIVE DEORTHOGONALIZATION MATRIX 'ROR' FROM ORTH-MATRIX 'OR'
      CALL GEN003 (OR, ROR, DET, 0)
C * TRANSFORM DEORTHOGONALIZATION MATRIX FOR NEW ORIENTATION
      CALL GEN004 (ROR, RMAT, RORO)
C * GET ORIENTATION MATRIX 'AAREV'
C * ROWS CONTAIN COMPONENTS OF A,B & C RESP IN XO,YO,ZO
      CALL GEN004 (AA, RORO, AAREV)
C * DECOMPOSE RMAT INTO SEQUENCE OF 3 ROTATIONS
      CALL GEN005 (RMAT, DUMV)
      CALL GEN096 (DUMV, IROTX, IROTY, IROTZ, IDET, V6, YNK, RORO)
      RGBL(28) = IROTX
      RGBL(29) = IROTY
      RGBL(30) = IROTZ
      IGBL(87) = IDET
C * ESTABLISH REFERENCE POINT OF VIEW
        DO I = 1, 3
          VIEWV(I) = RORO(I, 3)
        END DO
        CALL GEN007 (AA, VIEWV, VIEWV, -1)
C * AUTOMATIC ORIGIN AND/OR SCAL
      PAR(37) = PAR(38) * PAR(50)
      CALL GEN074 (PAR, 58, 60, -1.E5)
      CALL GEN074 (PAR, 55, 57,  1.E5)
      IPR(477) = 0
C * GET DISPLACEMENT PARAMETERS (EIGENVECTORS & EIGENVALUES) FROM SCRATCH
C * (PREPARED IN PLA024)
      IREF = IPR(297)
      DO I = 1, NASUP
        YNK = 0
        DO J = 1, 9
          YNK       = YNK + ABS (VOID(IREF + J))
          CON(I, J) = VOID(IREF + J)
        END DO
        IF (YNK == 0.0) THEN
          CON(I, 1) = 1.0
          CON(I, 5) = 1.0
          CON(I, 9) = 1.0
        END IF
        IREF = IREF + 21
        DO J = 1, 3
          IF (I > NATOM) THEN
            XSD(I, J) = VOID(IREF + J - 12) / 2.0
          ELSE
            XSD(I, J) = VOID(IREF + J - 12)
          END IF
        END DO
C * CHECK FOR INCLUSION IN THIS PLOT
        IF (IATP(I) <= NP1) THEN
C * FIT BOX AROUND SET OF ATOMS FOR SCALING
          DO J = 1, 3
            V1(J) = VOID((I - 1) * NP71 + J)
          END DO
          CALL GEN002 (-1, AAREV, V1, V7, XLNG)
          IPR(477)       = IPR(477) + 1
          IATC(IPR(477)) = I
          DATC(IPR(477)) = V7(3)
          CALL GEN048 (-1, IFG(2, I), 27, ISKP)
          IF (ISKP == 0) THEN
            DO J = 1, 3
              PAR(57 + J) = MAX (PAR(57 + J), V7(J))
              PAR(54 + J) = MIN (PAR(54 + J), V7(J))
            END DO
          END IF
        END IF
      END DO
C * AUTOMATIC SCALE AND POSITION DETERMINATION SECTION
C * SCALE
      PAR(45) = (PAR(37) - PAR(40) * 2.0) /
     1          (PAR(58) - PAR(55) + 2.0 * PAR(41))
      PAR(45) = MIN (PAR(45), (PAR(38) - PAR(40) * 2.0) /
     1          (PAR(59) - PAR(56) + 2.0 * PAR(41)))
      PAR(47) = PAR(45) * PAR(46)
C * POSITION
      DO I = 1, 2
        V2(I) = (PAR(36 + I) - PAR(45) *
     1          (PAR(57 + I) + PAR(54 + I))) / 2.0
      END DO
      V2(3) = 0.0
C * SORT ATOM LIST BY Z-PARAMETER
      CALL GEN036 (DATC, IATC, 1, IPR(477))
C * STORE PROJECTED ATOM CONICS
C * LOOP THROUGH ALL ATOMS IN SORTED ATOMS LIST
      DO I = 1, IPR(477)
        N  = NASUP + I
        IA = IATC(I)
        IF (IA /= 0) THEN
          CALL GEN048 (-1, IFG(2, IA), 27, ISKP)
          IF (ISKP == 0) THEN
C * GET COORDINATES AND EIGENVALUES**2
            DO J = 1, 3
              V1(J) = VOID((IA - 1) * NP71 + J)
C * CHECK/RESET NEGATIVE Eigenvalues
              IF (XSD(IA, J) < 0.001) XSD(IA,J) = 0.001
              V6(J) = 1.0 / XSD(IA, J)**2
            END DO
C * CALCULATE ORTHOGONAL COORDINATES FOR CURRENT ORIENTATION :
C *                                         V7  = V1 * AAREV
            CALL GEN002 (-1, AAREV, V1, V7, XLNG)
C * TO PDB
C * REST FOR RASTER-3D
            IF (IPR(108) /= 0) THEN
              CALL PLA047 (LABA(IA), NQ2, IDUM, JDUM, 0,
     1          IGBL(55), 1, 0)
              WRITE (LU65, 99998, IOSTAT = IOST)
     1          IA, NQ2(1:7), 0, (V7(J), J = 1, 3), 1.0, 0.0
              L    = 0
              IANI = 1
              CALL GEN048 (-1, IFG(1, IA), 7, IHAT)
              IF (IHAT == 1) THEN
                CALL GEN048 (-1, IFG(1, IA), 4, IANI)
              END IF
              DO J = 1, 3
                DO K = 1, 3
                  L = L + 1
                  UIJC(J, K) = VOID(IPR(297) + IA * 21 + L - 9)
     1                       * 10000.0
                  IF ((IANI == 0 .OR. NQ2(1:2) == 'CG')
     1              .AND. J == K) UIJC(J, K) = 25
                END DO
              END DO
              CALL GEN001 (1, TMAT, UIJC, UIJC)
              WRITE (LU65, 99997, IOSTAT = IOST)
     1          IA, NQ2(1:7), 0, (NINT (UIJC(J, J)), J = 1, 3),
     2          NINT (UIJC(1, 2)), NINT (UIJC(1, 3)), NINT (UIJC(2, 3))
            END IF
C * SCALE AND CENTER MOLECULE COORDINATES (CM)
            DO J = 1, 3
              XXO(I, J) = V7(J) * PAR(45) + V2(J)
            END DO
C * GET CONTRAVARIANT EIGENVECTORS IN COLUMNS OF PAC
            DO M = 1, 9
              J = MOD (M - 1, 3) + 1
              K = ((M - 1) / 3)  + 1
              PAT(J, K) = CON(IA, M)
            END DO
C * TRANSFORM TO CARTESIAN SYSTEMS
C * TRANSPOSE(TRANSPOSE(PAT) * AAREV) = TRANSPOSE(AAREV) * PAT = PAC
            CALL GEN005 (AAREV, QD)
            CALL GEN004 (QD, PAT, PAC)
C * FORM QUADRATIC FORM 'A'
            CALL GEN099 (PAC, V6, QD)
C * CALCULATE ENVELOPING CYLINDER ALONG Z OF WORKING SYSTEM
            DO J = 1, 2
              DO K = 1, 2
                QD(J, K) = QD(J, K) - QD(J, 3) * QD(K, 3) / QD(3, 3)
              END DO
            END DO
            DO J = 1, 2
              QD(J, 3) = 0.0
              QD(3, J) = 0.0
              V6(J)    = XXO(I, J)
            END DO
C * PROJECTED ELLIPSE IN HOMOGENEOUS COORDINATES ABOUT CENTER OF ATOM
            QD(3, 3) = - PAR(47)**2
C * FIT RECTANGLE AROUND ELLIPSE ALLOWING OVERLAP MARGIN
C * FORM MATRIX OF COFACTORS, RESCALED SO THAT QCC(3,3)=1.0
            CALL GEN003 (QD, QCC, DUMMY, 1)
            TD2 = QD(3, 3)
            NDG = 0
            DO J = 1, 2
C * SOLVE QUADRATIC EQUATION
              T1 = QCC(3, J)**2 - QCC(J, J)
              IF (T1 <= 0.0) THEN
C * ROUNDOFF PROBLEMS, RESET LIMITS IN X OR Y
                NDG   = 1
                V5(J) = 0.001 + PAR(44)
              ELSE
                V5(J) = SQRT (T1) + PAR(44)
                V6(J) = V6(J) + QCC(3, J)
                TD2   = TD2 + QD(3, J) * QCC(3, J)
              END IF
              XXO(N, 2 * J - 1) = V6(J) - V5(J)
              XXO(N, 2 * J)     = V6(J) + V5(J)
            END DO
            IF (NDG == 0) THEN
              IF (TD2 < 0.0) THEN
C * STORE NORMALIZED QUADRATIC COEFFICIENTS FOR ELLIPSE
C * SCALED BY OVERLAP MARGIN PARAMETER
                TD3 = - (1.0 - 2.0 * PAR(44) / (V5(1) + V5(2)))**2
     1              / TD2
                XSD(N, 1) = QD(1, 1) * TD3
                XSD(N, 2) = QD(1, 2) * TD3
                XSD(N, 3) = QD(2, 2) * TD3
                CYCLE
              END IF
            END IF
C * ELLIPSE IMAGINARY DUE TO ROUNDOFF, RESET TO REAL VALUE
            XSD(N, 1) = 4.0 / (XXO(N, 2) - XXO(N, 1))**2
            XSD(N, 2) = 0.0
            XSD(N, 3) = 4.0 / (XXO(N, 4) - XXO(N, 3))**2
          END IF
        END IF
      END DO
C * GET BOND DATA: AT1, AT2, NR-LINES, RADIUS
      K   = NASUP + 1
      NCD = 0
      DO I = 1, NCB
C * GET ATOM NUMBERS IN BOND
        IATP1 = IATP(NINT (VOID(IPR(298) + I * 3 - 2)))
        IATP2 = IATP(NINT (VOID(IPR(298) + I * 3 - 1)))
C * SKIP BONDS IN EXCLUDED RESIDUES
        IF (IATP1 < NP1 .AND. IATP2 < NP1) THEN
          XSD(K, 4) = IATP1
          XSD(K, 5) = IATP2
C * NEGATIVE VALUE INDICATES DASHED BOND
          XBND = VOID(IPR(298) + I * 3)
C * 'NUMBER OF LINES ON BONDS'
          XB   = PAR(84 + NINT (ABS (XBND)))
          IF (XB < 0) THEN
            XB   = - XB
            XBND = - ABS (XBND)
          END IF
          XSD(K, 6) = SIGN (128 / 2**XB, XBND)
          XXO(K, 5) = PAR(85 + NINT (ABS (XBND)))
          NCD = NCD + 1
          K   = K   + 1
        END IF
      END DO
C * CHECK FOR RASTER3D
      IF (IPR(108) /= 0) THEN
        CLOSE (UNIT = LU65)
        IF (IPR(477) > 1) CALL PLA209
        IPR(108) = 0
        GO TO 50
      END IF
C * INITIALIZE ARRAYS SCIR (3 * 130) AND DP (2 * 130) ON 0
   60 CALL GEN074 (SCIR, 1, 390, 0.0)
      CALL GEN074 (DP,   1, 260, 0.0)
C * GRAPHICS OUTPUT SECTION
      PVER = PAR(349)
C * INIT GRAPHICS AND SET SCALING
      IF (IPR(478) <= 1 .AND. NLOOP >= 1) THEN
        BCD(1:12) = 'P.L.A.T.O.N'//CHAR (0)
        CALL GGIP (PAR(37), PAR(38), 0.0, 1)
      END IF
C * CHECK FOR RECALCULATE LABEL POSITION
      IF (IWIN == 1 .AND. LRET == 6) THEN
        BCD = 'Click on Window to STOP Rotation'//CHAR (0)
        CALL GGIP (-999.0, 2.0, 33.0, 111)
      END IF
      IF (IPR(116) == 0) THEN
C * SET DEFAULT COLOR
        CALL GGIP (0.0, 1.0, 0.0, 0)
      ELSE
C * RG-STEREO COLORS
        CALL GGIP (0.0, FLOAT (IPR(143 + IPR(478) - 1)), 0.0, 0)
      END IF
C * PLOT BOX
      CALL PLA110 (PAR(37), PAR(38), 1)
C * DRAW BONDS
      IF (NCD > 0 .OR. IPR(201) == 0) THEN
        CALL PLA102
        IF (CC) GO TO 70
      END IF
C * LOOP THROUGH ATOM LIST TO DRAW ELLIPSOIDS
      CALL PLA103
      IF (CC) GO TO 70
      IF (LRET == 6) GO TO 30
C * PLOT SPECIAL TEXT
      LMOD = 0
      CALL PLA109 (2, 0, 0.0, 0.0)
      IF (IGBL(75) > 0) IPR(201) = 1
C * CHECK FOR STEREO
      IF (IPR(478) > 0 .AND. IPR(478) == IPR(116)) GO TO 50
      IF (LRET == 6) GO TO 30
C * (MOUSE_LOOP) ISSUE AN END-OF-PICTURE
   70 IF (IGBL(6) == 22) THEN
        CALL PLA439 (-90.0, 'ORTEP: CONTOUR-MAP INPUT', 24, 0.8,
     1    5 + IGBL(68), 3, PAR(37) - 1.0 , PAR(38) - 2.0)
        IF (IGBL(3) == 3) IGBL(3) = 0
        RETURN
      END IF
      NLOOP = 2
C * SPECIAL VERSION
      IF (META == 1) THEN
        CALL GGIP (0.0, 0.0, 0.0, -1)
        IGGT = 'END'
      ELSE
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IF (IGBL(3) == 28) LRET = 7
        SELECT CASE (LRET)
          CASE (1)
            DO
* LOOK FOR GEOMETRY INSTRUCTIONS
              CALL PLA006 (0, IS)
              IF (IS == 1) THEN
                WRITE (LU6, 99995, IOSTAT = IOST)
                CALL PLA015 (0, 10)
                CYCLE
              END IF
C * REM
              IF (IFL(1)(1:3) == 'REM') THEN
                IGBL(6)  = 10
                IPR(351) = 0
                EXIT
C * END/EXIT
              ELSE IF (IFL(1)(1:3) == 'END' .OR.
     1           IFL(1)(1:4) == 'EXIT') THEN
                IF (IFL(1)(1:3) == 'END')
     1            REWIND (UNIT = LU2, IOSTAT = IOST)
C * END OF INSTRUCTION SAVE OPTION
                IF (IGBL(3) == 3) THEN
                  IGBL(45) = -1
                END IF
                EXIT
C * SELECT ADP RESIDUE TO BE PLOTTED
              ELSE IF (IS == 185) THEN
                IYUNK = NINT (FN(1))
                IF (IYUNK >= 0 .AND. IYUNK <= IPR(75)) THEN
                  WRITE (ICL, 99994, IOSTAT = IOST) NINT (FN(1))
                  CALL PLA280 (ICL)
                EXIT
                END IF
              END IF
C * INTERACTIVE DIST, ANGLE AND TORSION LISTING
              SELECT CASE (IFL(1)(1:4))
                CASE ('DIST', 'ANGL', 'TORS')
                  IPR(81) = IPR(220)
                  CALL PLA440 (1)
                  GO TO 70
C * CHANGE B&W REVERSE
                CASE ('SET ')
                  IF (IFL(2)(1:3) == 'REV') THEN
                    IGBL(68) = MOD (IGBL(68) + 1, 2)
                    CALL GGIP (-999.0, FLOAT (IGBL(68)),
     1                IGBL(62) * 0.25, 9)
                    CALL GGIP (0.0, 0.0, 0.0, 6)
                    IGGT = 'MENU ON'
                    GO TO 70
                  ELSE IF (IFL(2)(1:3) == 'WIN') THEN
                    CALL GGIP (-999.0, FLOAT (IGBL(68)),
     1                FN(1) * 1000.0, 9)
                    IGBL(62) = MIN (MAX (1, NINT (FN(1) / 0.25)), 4)
                    CALL GGIP (0.0, 0.0, 0.0, 6)
                  ELSE
                    ISW = 1
                  END IF
C * LABEL (ON/OFF) TOGGLE
                CASE ('LABE')
                  IF (IPR(220) > 1) THEN
                    SELECT CASE (IFL(2)(1:5))
                      CASE ('ON   ')
                        IGBL(75) = 1
                      CASE ('OFF  ')
                        IGBL(75) = 0
                    END SELECT
 
                  ELSE
                    IGBL(75) = MOD (IGBL(75) + 1, 2)
                  END IF
                  GO TO 20
C * LIST OPTIONS
                CASE ('LIST')
                  ISW = -1
                  SELECT CASE (IFL(2)(1:5))
                    CASE ('ARU  ')
                      ISW = 0
                      CALL PLA043 (0, -2, LU6, 0)
C * WHAT NEXT ?
                      CALL PLA012 (1, 1)
                      IGBL(6) = 9
                      GO TO 20
C * LIST UIJ
                    CASE ('UIJ  ')
                      ISW = 0
                      IGBL(6) = 9
C * LIST UEQ
                    CASE ('UEQ  ')
                      ISW = 0
                      IGBL(6) = 9
C * LIST ATOMS
                    CASE ('ATOM ', 'ATOMS')
                      ISW = 0
                      IGBL(6) = 9
C * LIST FLAGS
                    CASE ('FLAG ')
                      ISW = 0
                      IGBL(6) = 9
C * LIST RADII
                    CASE ('RADII')
                      ISW = 0
                      IGBL(6) = 9
C * LIST FLAGS
                    CASE ('FLAGS')
                      ISW = 0
                      IGBL(6) = 9
                  END SELECT
C * CALC
                CASE ('CALC')
                  ISW = 0
                  IF (IFL(2)(1:4) == 'COOR') THEN
                    IF (IFL(3)(1:6) == '******') CYCLE
                    CALL PLA037 (3, NID, 3)
                    IF (IPR(2) /= 0) THEN
                      WRITE (LU6, 99993) IFL(3)
                      IPR(2) = 0
                      CYCLE
                    END IF
                  END IF
                CASE DEFAULT
                  ISW = 0
              END SELECT
              IF (ISW /= 0 .AND. IPR(220) > 1) THEN
C * SET META TYPE
                IF (IFL(2)(1:3) == 'MET') THEN
                  MEDIUM = 2
                  IF (IPR(220) > 2) CALL GGIP (-999.0, 0.0, 0.0, 6)
                ELSE
C * LIST AND SET OF IPR/PAR/IGBL/RGBL
                  CALL PLA206 (ISW, IFL(2)(1:3))
                END IF
                ISW = 0
                GO TO 70
              END IF
C * TRANSFER TO PLUTON
              IF (IFL(1)(1:6) == 'PLUTON') THEN
                CALL PLA280 (IFL(1)(1:7))
              ELSE
                CALL PLA280 (ICL)
              END IF
              IF (NEXIT == 0) EXIT
            END DO
          CASE (2)
            GO TO 50
          CASE (3)
            GO TO 60
C * NEW CONTENT AND ORIENTATION PLOT
          CASE (4)
            GO TO 20
          CASE (5)
C * SPECIAL TEXT
            LMOD = 0
            CALL PLA109 (1, 0, 0.0, 0.0)
            GO TO 70
          CASE (6)
            GO TO 30
          CASE (7)
          CASE (8)
            GO TO 10
          CASE DEFAULT
            GO TO 30
        END SELECT
      END IF
C * RECOVER ARRAYS (XXO, XSD, CON)
      CALL PLA269 (-1, NASUP)
      IF (IGBL(3) == 3) IGBL(3) = 0
      RETURN
99998 FORMAT ('ATOM  ', I5, 1X, A, 2X, I5, 4X, 3F8.3, 2F6.2)
99997 FORMAT ('ANISOU', I5, 1X, A, 2X, I5, 2X, 6I7)
99996 FORMAT ('HEADER ', A)
99995 FORMAT ('>> UNKNOWN INSTRUCTION - IGNORED', /)
99994 FORMAT ('PLOT ADP RESD ', I5)
99993 FORMAT (/,':: Label Error: ', A)
      END SUBROUTINE PLA101
 
      SUBROUTINE PLA102
 
C * ADP/ORTEP DRAW BONDS
      USE files
      USE atomdata
      USE parameters
      USE plato
      USE cggt
      USE ortep
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: K0
      INTEGER :: K1
      INTEGER :: L1
      INTEGER :: KL
      INTEGER :: IA
      INTEGER :: IB
      INTEGER :: IQ
      INTEGER :: II
      INTEGER :: ID1
      INTEGER :: ID2
      INTEGER :: IQN
      INTEGER :: KAT
      INTEGER :: NA1
      INTEGER :: NA2
      INTEGER :: NB1
      INTEGER :: NB2
      INTEGER :: KD1
      INTEGER :: KD2
      INTEGER :: MNB
      INTEGER :: MLP
      INTEGER :: IPOS
      INTEGER :: NO1
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: IBND
      INTEGER :: KSTP
      INTEGER :: ISKP
      INTEGER :: NREF
      INTEGER :: NTOM
      INTEGER :: MILP
      INTEGER :: NBLP
      INTEGER :: NBND
      INTEGER :: HINC
      INTEGER :: IHAT
      INTEGER :: JHAT
      INTEGER :: NBM1
      INTEGER :: ITYPE
      INTEGER :: LPOS1
      INTEGER :: LPOS2
      INTEGER :: NSTEP
      INTEGER :: IDASH
      INTEGER :: MLOOP
      INTEGER :: NASIQ
      INTEGER :: NA1P1
      INTEGER :: LPOS12
      INTEGER :: NSHIFT
      INTEGER :: IATCIA
      REAL :: TX
      REAL :: DSX
      REAL :: DSY
      REAL :: DIF
      REAL :: DUMP
      REAL :: DIST
      REAL :: XSFT
      REAL :: YSFT
      REAL :: BDIR
      REAL :: DELX
      REAL :: DELY
      REAL :: XLNG
      REAL :: PAR71
      REAL :: XCONK
      REAL :: YCONK
      REAL :: SCONX
      REAL :: SCONY
      REAL :: XSHFT
      REAL :: YSHFT
      REAL :: RADIUS
      REAL :: GEN006
      REAL :: GEN009
      REAL, DIMENSION(3, 3) :: B
      REAL, DIMENSION(3, 3) :: S
      REAL, DIMENSION(4, 2) :: W
      REAL, DIMENSION(2)    :: Y1
      REAL, DIMENSION(2)    :: Y2
      REAL, DIMENSION(4, 4) :: FL
      REAL, DIMENSION(3, 4) :: QUA
      REAL, DIMENSION(6)    :: POSL
C * TEMPORARILY MEMORY LAYOUT FOR ADP ROUTINES
C ***********************************************************************C
C *          I       XXO        I       XSD        I      CON  I IATC/   C
C *          I  1:3      4:6    I   1:3      4:6   I      1:9  I  DATC   C
C *----------------------------------------------------------------------C
C *          I  CART. I  CART   I  EIGEN  I  CART  I EIGEN     I         C
C *          I   XYZ  I  XYZ    I VALUES  I  ESD   I VECTORS   I(SELECT) C
C *  IPR(39) I(SELECT)I  (ORIG) I(SELECT) I (ORIG) I(SELECTED) I         C
C * +IPR(64) I        I         I         I        I           I         C
C * = NASUP  I        I         I         I        I           I         C
C *----------------------------------------------------------------------C
C *  NQD     I          I   I   I         I        I           I         C
C *----------------------------------------------------------------------C
C *  IPR(174)I COVER            I CQ      I SEGM   I CB        I QL      C
C * GET ACTIVE NUMBER OF BONDS
      NQD   = 0
      IDASH = 0
      V8(1) = 0.0
      V8(2) = 0.0
      V8(3) = 1.0
C * MLOOP = 1 : BOND OUTLINE STORAGE RUN
C * MLOOP = 2 : BOND PLOT RUN
C * MLOOP = 3 : LABEL SETTING RUN
      IF (NCD == 0) THEN
        MILP = 3
      ELSE
        MILP = 1
      END IF
      IF (IGBL(75) /= 0 .AND. IPR(201) == 0) THEN
        MLP = 3
      ELSE
        MLP = 2
      END IF
      DO MLOOP = MILP, MLP
C * DETERMINE BOND/LABEL LOOP MAXIMUM
        IF (MLOOP < 3) THEN
          MNB = NCD
        ELSE
          MNB = IPR(477)
        END IF
C * LOOPS OVER ACTIVE BONDS/OR LABELS
        DO 80 NBLP = 1, MNB
          IF (CC) RETURN
C * LOOP OVER ACTIVE BONDS
          NSHIFT = 1
   10     IF (MLOOP < 3) THEN
            NBND = NINT (XSD(NASUP + NBLP, 6))
            IF (NBND > 0) THEN
              IDASH = 0
            ELSE
              IDASH = 1
              NBND  = IABS (NBND)
            END IF
C * GET DATA RELEVANT TO THIS BOND IN W
C *
C * W(I, J)   1       2    ATOM WITH HIGHEST Z IN FIRST POSITION
C * ====================
C *    1     KD1     KD2   ADDRESSES OF BOND ATOMS IN PRIM. ATOM LIST
C *    2     X1      X2  -I
C *    3     Y1      Y2  -I - TRANSFORMED COORDINATES
C *    4     Z1      Z2  -I
            KD1     = NINT (XSD(NASUP + NBLP, 4))
            KD2     = NINT (XSD(NASUP + NBLP, 5))
            W(1, 1) = KD1
            W(1, 2) = KD2
            NA1     = 0
            NA2     = 0
            ID1     = 0
            DO K = 1, IPR(477)
              L = IATC(K)
              IF (L /= 0) THEN
                I = 0
                IF (L == KD1) THEN
                  NA1 = K
                  I   = 1
                  CALL GEN048 (-1, IFG(2, L), 27, ISKP)
                  IF (ISKP == 1) GO TO 80
                ELSE IF (L == KD2) THEN
                  NA2 = K
                  I   = 2
                  CALL GEN048 (-1, IFG(2, L), 27, ISKP)
                  IF (ISKP == 1) GO TO 80
                END IF
                IF (I /= 0) THEN
C * OBTAIN POSITIONAL PARAMETERS (PROJECTED)
                  DO J = 2, 4
                    W(J, I) = XXO(K, J - 1)
                  END DO
                  IF (NA1 > 0 .AND. NA2 > 0) THEN
C * FIND UPPERMOST ATOM PUT IN POSITION ONE
                    IF (W(4, 1) < W(4, 2)) THEN
C * SWAP ATOMS AND RELATED DATA
                      DO J = 1, 4
                        CALL GEN018 (W(J, 1), W(J, 2))
                      END DO
                      CALL GEN014 (NA1, NA2)
                    END IF
                    ID1 = NA1 * (NP1 + 1) + NA2
                    IF (NEXIT == 0) EXIT
                  END IF
                END IF
              END IF
            END DO
            IF (ID1 == 0) GO TO 80
C * FORM VECTOR SET RADIAL TO BOND
            DO I = 1, 3
              DAM(I, 3) = W(1 + I, 2) - W(1 + I, 1)
            END DO
            CALL GEN007 (AA, DAM(1, 3), V3, 1)
C * CALCULATE DISTANCE
            IF (MLOOP == 2) DIST = SQRT (DAM(1, 3)**2 + DAM(2, 3)**2
     1         + DAM(3, 3)**2) / PAR(45)
C * UNIT VECTOR FROM BOND MIDPOINT TO REFERENCE VIEWPOINT
            CALL GEN002 (-1, RORO, AAREV(1, 3), V2, XLNG)
            CALL GEN007 (AA, V2, V2, 1)
            T6 = ABS(GEN009 (V3, V2))
C * SKIP BOND IF BOND IS ALONG REFERENCE VIEW DIRECTION
            IF (0.9994 <= T6) GO TO 80
            CALL GEN019 (AA, BB, V3, V2, B, 1)
            TX = XXO(NASUP + NBLP, 5) / PAR(46)
C * GENERATE ELLIPSE FROM TWO CONJUGATE VECTORS
C * ORTHONORMAL VECTORS PRODUCE 8-128 SPOKED CIRCLE
C * ND DENOTES NUMBER OF SUBDIVISIONS (1 TO 5)
            DO J = 1, 3
              T1           = - B(J, 2) * TX
              SCIR(J, 1)   =   T1
              SCIR(J, 129) =   T1
              SCIR(J, 65)  = - T1
              T1           = - B(J, 3) * TX
              SCIR(J, 33)  =   T1
              SCIR(J, 97)  = - T1
            END DO
            DO K = 1, 3
              T1 = SQRT (1.0 /
     1          (2.0 * (1.0 + COS (RGBL(5) / (2**(K + 1))))))
              KDEL  = 2**(6 - K)
              KDEL1 = KDEL + 1
              KDEL2 = KDEL / 2
              DO L = KDEL1, 65, KDEL
                J = L - KDEL
                M = L - KDEL2
                DO N = 1, 3
                  T2 = (SCIR(N, L) + SCIR(N, J)) * T1
                  SCIR(N, M)      =  T2
                  SCIR(N, M + 64) = -T2
                END DO
              END DO
            END DO
C * DERIVE QUADRICS FOR EACH ATOM CONSTITUTING THE BOND
            DO II = 1, 2
              N = NINT (W(1, II))
C * CONTRAVARIANT EIGENVECTORS FOR Q IN COLUMNS OF PAC
              DO I = 1, 9
                J = MOD (I - 1, 3) + 1
                K = ((I - 1) / 3)  + 1
                PAT(J, K) = CON(N, I)
              END DO
C * TRANSFORM TO CARTESIAN SYSTEMS
C * TRANSPOSE(TRANSPOSE(PAT) * AAREV) = TRANSPOSE(AAREV) * PAT = PAC
              CALL GEN005 (AAREV, QM)
              CALL GEN004 (QM, PAT, PAC)
C * FORM DIAGONAL MATRIX OR ITS INVERSE
              DO J = 1, 3
                IF (XSD(N, J) /= 0.0) THEN
                  V6(J) = 1.0 / XSD(N, J)**2
                ELSE
                  V6(J) = 1.0
                END IF
              END DO
C * FORM QUADRATIC FORM
              CALL GEN099 (PAC, V6, QM)
C * DOES BOND GOTO ELLIPSOID OR TO ENVELOPE
              T1 = 3 - II * 2
              DO J = 1, 3
                V3(J) = V3(J) * T1
              END DO
              IF (GEN006 (V3, QM, V8) < 0.0) THEN
                IBND = 0
C * DERIVE TANGENT CYLINDER WITH AXIS ALONG Z
                T1 = - 1.0 / QM(3, 3)
                DO J = 1, 2
                  DO K = 1, 2
                    S(K, J) = QM(K, J) + QM(K, 3) * QM(J, 3) * T1
                  END DO
                  S(3, J) = 0.0
                  S(J, 3) = 0.0
                END DO
                S(3, 3) = 0.0
              ELSE
C * TRANSFER ELLIPSOID
                DO J = 1, 3
                  DO K = 1, 3
                    S(J, K) = QM(J, K)
                  END DO
                END DO
                IBND = II
              END IF
              T5 = 1.0
C * CHECK FOR BOND TAPER
              IF (II < 2) THEN
                RADIUS = 1.0 + T6 * PAR(48)
              ELSE
                RADIUS = 1.0 - T6 * PAR(48)
              END IF
              CALL GEN002 (1, S, V3, V4, XLNG)
              T2 = GEN009 (V3, V4)
C * COMPUTE BOND INTERSECTION
              KL = 5 - 2 * II
              IF (MLOOP == 2) THEN
                KSTP = 4
              ELSE
                KSTP = 32
              END IF
              DO K = 1, 65, KSTP
                DO J = 1, 3
                  V6(J) = SCIR(J, K) * RADIUS
                  V5(J) = V6(J)
                END DO
                T3 = GEN009 (V5, V4)
                T4 = T3 * T3 - T2 * (GEN006(V5, S, V5) - T5)
                IF (T4 < 0.0000001) GO TO 80
                T4 = SQRT (T4)
                T1 = ( T4 - T3) / T2
                T3 = (-T4 - T3) / T2
                L  = K + KL - 1
                DO J = 1, 3
                  SCIR(J, L)     = ( V6(J) + T1 * V3(J)) * PAR(47)
                  SCIR(J, L + 1) = (-V6(J) - T3 * V3(J)) * PAR(47)
                END DO
              END DO
              IF (IBND + MLOOP == 2) THEN
C * FOR OVERLAP, MAKE BOND QUADRANGLE TANGENT TO ENVELOPING CONE
                T4 = T2 * T5
                IF (T4 < 0.0) GO TO 80
                T1 = SQRT (T4)  / T2
                DO J = 1, 3
                  T4 = (T1 * V3(J) * PAR(47) - 0.5 * (SCIR(J, KL)
     1               + SCIR(J, KL + 64))) * 1.001
                  SCIR(J, KL)      = SCIR(J, KL) + T4
                  SCIR(J, KL + 64) = SCIR(J, KL + 64) + T4
                END DO
              END IF
C * 3D CARTESIAN TO 2D PLOTTER COORDINATES
              DO I = 1, 65, KSTP
                DP(1, II - 1 + I) = SCIR(1, KL - 1 + I) + W(2, II)
                DP(2, II - 1 + I) = SCIR(2, KL - 1 + I) + W(3, II)
              END DO
              IF (IBND == 1) THEN
C * 3D CARTESIAN TO 2D PLOTTER COORDINATES
                DO I = 68, 128, KSTP
                  DP(1, II + I) = SCIR(1, KL - 63 + I) + W(2, II)
                  DP(2, II + I) = SCIR(2, KL - 63 + I) + W(3, II)
                END DO
                CYCLE
              END IF
C * RETRACE TOP HALF
              DO K = 4, 64, 4
                L = K + II
                M = L + 64
                N = 66 - L
                IF (N <= 0) EXIT
                DP(1, M) = DP(1, N)
                DP(2, M) = DP(2, N)
              END DO
            END DO
C * CHECK FOR OVERLAP OR HIDDEN BOND
            DO K = 1, 65, 32
              T1 = 0.0
              T2 = 0.0
              DO J = 1, 2
                T1 = T1 + (DP(J, K)     - W(J + 1, 1))**2
                T2 = T2 + (DP(J, K + 1) - W(J + 1, 1))**2
              END DO
              IF (T2 <= T1) GO TO 80
            END DO
          ELSE
C * LOOP OVER LABELS (MLOOP = 3 CASE)
            NTOM = NASUP + NBLP
 
C * GET ATOM NUMBER IN FULL ATOM DATA LIST
            KAT  = IATC(NBLP)
            IF (KAT == 0) GO TO 80
C * IGNORE SUPPORT ATOM (CG etc)
            IF (KAT > NATOM) THEN
              IF (IPR(506) == 0) GO TO 80
            END IF
C * GET ATOM TYPE
            CALL GEN048 (-4, IFG(1, KAT), 15,  NO1)
C * GET H-ATOM BIT
            CALL GEN048 (-1, IFG(1, KAT),  7, IHAT)
C * GET H-INCLUDE BIT
            CALL GEN048 (-1, IFG(2, KAT), 12, HINC)
            NO1 = NO1 + 1
            CALL GEN048 (-2, IFG(1, KAT), 28, ICHIRAL)
C * PLOT LABEL FOR NON-HATOMS + (HATOMS OPTIONAL)
            IF ((IHAT /= 1 .AND. IEN(NO1) /= 2 * IPR(618)) .OR.
     1        (MAX (IPR(212), HINC) * IPR(232) == 1 .AND.
     2         IPR(618) == 0)) THEN
              NPOS = 0
C * GET LABEL AND NUMBER OF NON-BLANK POSITIONS (NP)
              CALL PLA047 (LABA(KAT), NQ1, IDUM, JDUM,
     1          IPR(350), IGBL(55), 0, 1 - IGBL(55))
C * STRIP BLANKS
              CALL GEN039 (1, NQ1, 1, 6, NB, NP)
C * ADD CHIRAL INFO TO ATOM LABEL
              IF (IPR(18) == 1) THEN
                IF (ICHIRAL == 1 .OR. ICHIRAL == 3) NP = NP + 2
              END IF
C * FETCH ENCLOSING LABEL BOX DIMENSIONS FOR THIS ATOM
C * XXO(NTOM, 1:4) = XMIN, XMAX, YMIN, YMAX
              NSHIFT  = NSHIFT + 2
              PAR71   = NSHIFT * PAR(71)
              XSFT    = (XXO(NTOM, 2) - XXO(NTOM, 1)) / 7.0
              YSFT    = (XXO(NTOM, 4) - XXO(NTOM, 3)) / 7.0
              PHOR    = PVER * NP * 6.0 / 7.0
              POSL(1) = XXO(NTOM, 1) - PHOR - PAR71
              POSL(2) = XXO(NTOM, 2) + PAR71
              POSL(3) = XXO(NTOM, 3) - PVER - PAR71
              POSL(4) = XXO(NTOM, 4) + PAR71
              POSL(5) = (POSL(1) + POSL(2)) / 2.0
              POSL(6) = (POSL(3) + POSL(4)) / 2.0
C * DETERMINE STARTING POSITION FOR SEARCH
              IF (POSL(5) > PAR(37) / 2.0) THEN
                IF (POSL(6) > PAR(38) / 2.0) THEN
                  IPOS = 2
                ELSE
                  IPOS = 0
                END IF
              ELSE
                IF (POSL(6) > PAR(37) / 2.0) THEN
                  IPOS = 4
                ELSE
                  IPOS = 6
                END IF
              END IF
            ELSE
              GO TO 80
            END IF
          END IF
C * MLOOP/1/2 -HANDLING
          IF (MLOOP == 1) THEN
C * STORES BOND OUTLINE INFORMATION
            NQD = NQD + 1
C * CALCULATE OVERLAP MARGIN FOR BOND QUADRANGLE
            T1 = 0.0
            T2 = 0.0
            DO J = 1, 2
              Y1(J) = DP(J, 1) - DP(J, 65)
              Y2(J) = DP(J, 2) - DP(J, 66)
              T1    = T1 + Y1(J)**2
              T2    = T2 + Y2(J)**2
            END DO
            IF (T1 * T2 <= 0.0) THEN
              T1 = 0.0
              T2 = 0.0
            ELSE
              T1 = PAR(44) / SQRT (T1)
              T2 = PAR(44) / SQRT (T2)
            END IF
C * STORE BOND QUADRANGLE
            NREF = NASUP + NQD
            DO J = 1, 2
              Y1(J)            = Y1(J) * T1
              Y2(J)            = Y2(J) * T2
              CON(NREF, J)     = DP(J, 1)  + Y1(J)
              CON(NREF, J + 2) = DP(J, 2)  + Y2(J)
              CON(NREF, J + 4) = DP(J, 66) - Y2(J)
              CON(NREF, J + 6) = DP(J, 65) - Y1(J)
            END DO
            JNSC(1, NQD) = ID1
          ELSE
C * LABEL OVERLAP TEST
   20       IF (MLOOP == 3) THEN
C * GET LABEL COORDINATES
C * POSITION LABEL CLOSE TO ASSOCIATED ELLIPSOID OUTLINE BOX
   30         IPOS = MOD (IPOS, 8) + 1
              NPOS = NPOS + 1
              N = KAT * NP71
              IF (NPOS > 8) THEN
                IF (NSHIFT < 10) GO TO 10
C * REPORT LABEL POSITIONING PROBLEM
                IF (LRET /= 6) THEN
C * CHECK FOR ZERO ROTATION STEP
                  IF (PAR(389) == 0.0) THEN
                    WRITE (LU6, 99999, IOSTAT = IOST) NQ1
                  END IF
                END IF
                IF (IGBL(105) == 0) THEN
                  VOID(N - 2) = 0.0
                  VOID(N - 1) = 0.0
                  VOID(N    ) = 0.0
                ELSE
                  VOID(N - 2) = POSL(LPOS(8, 1))
                  VOID(N - 1) = POSL(LPOS(8, 2))
                  VOID(N    ) = PHOR
                END IF
                GO TO 80
              END IF
              LPOS1  = LPOS(IPOS, 1)
              LPOS2  = LPOS(IPOS, 2)
              LPOS12 = LPOS1 * 10 + LPOS2
              SELECT CASE (LPOS12)
                CASE (23)
                  XSHFT = - XSFT
                  YSHFT =   YSFT
                CASE (24)
                  XSHFT = - XSFT
                  YSHFT = - YSFT
                CASE (14)
                  XSHFT =   XSFT
                  YSHFT = - YSFT
                CASE (13)
                  XSHFT =   XSFT
                  YSHFT =   YSFT
                CASE DEFAULT
                  XSHFT  = 0.0
                  YSHFT  = 0.0
              END SELECT
              VOID(N - 2) = POSL(LPOS1) + XSHFT
              VOID(N - 1) = POSL(LPOS2) + YSHFT
              VOID(N    ) = PHOR
              DP(1, 1)    = VOID(N - 2)
              DP(2, 1)    = VOID(N - 1)
              DP(1, 2)    = DP(1, 1)
              DP(2, 2)    = DP(2, 1) + PVER
              DP(1, 65)   = DP(1, 1) + PHOR
              DP(2, 65)   = DP(2, 1)
              DP(1, 66)   = DP(1, 65)
              DP(2, 66)   = DP(2, 2)
C * CHECK BOUNDARY
              IF (DP(1, 1) < 0.0 .OR. DP(1, 65) > PAR(37) .OR.
     1            DP(2, 1) < 0.0 .OR. DP(2, 65) > PAR(38))
     2            GO TO 30
              ID1 = 0
              NA1 = 0
              NA2 = 0
C * CHECK FOR LABEL_LABEL OVERLAP
              IF (NBLP > 1) THEN
                NBM1 = NBLP - 1
                DO J = 1, NBM1
                  N = IATC(J)
                  IF (N /= 0) THEN
                    CALL GEN048 (-1, IFG(2, N), 27, ISKP)
                    IF (ISKP == 0) THEN
                      IF (IPR(232) == 0) THEN
                        CALL GEN048 (-1, IFG(1, N), 7, JHAT)
                        ISKP = JHAT
                      END IF
                      IF (ISKP == 0) THEN
                        L    = KAT * NP71
                        M    = N   * NP71
                        DSX  = ABS (VOID(L - 2) - VOID(M - 2))
                        DSY  = ABS (VOID(L - 1) - VOID(M - 1))
                        IF (DSY < 1.1 * PAR(349)) THEN
                          IF (DSX < MAX (PHOR, VOID(M)))
     1                        GO TO 30
                        END IF
                      END IF
                    END IF
                  END IF
                END DO
              END IF
C * SHOW LABEL BOXES (IN DEBUG MODE)
              IF (IGBL(74) /= 0) THEN
                CALL GGIP (DP(1, 1),  DP(2, 1),  0.0, 3)
                CALL GGIP (DP(1, 65), DP(2, 65), 0.0, 2)
                CALL GGIP (DP(1, 66), DP(2, 66), 0.0, 2)
                CALL GGIP (DP(1, 2),  DP(2, 2),  0.0, 2)
                CALL GGIP (DP(1, 1),  DP(2, 1),  0.0, 2)
                CALL PLA439 (0.0, CHAR (48 + IPOS), 1, 0.3, 2, 1,
     1            DP(1, 1), DP(2, 1))
              END IF
            END IF
C * CHECK FOR ATOMS AND BONDS OVERLAPPING BOND OR LABEL NA1-NA2
C * ATOM WITH HIGHEST Z-VALUE HAS HIGHEST ATOM NUMBER
            IPR(151) = 0
            IPR(152) = 0
            IQ       = NQD + 1
            IQN      = NASUP + IQ
C * FIT RECTANGLE AROUND QUADRANGLE & SAVE QUADRANGLE TEMPORARILY
            DO J = 1, 2
              YMIN(J) = MIN (DP(J, 1), DP(J, 2), DP(J, 66), DP(J, 65))
              YMAX(J) = MAX (DP(J, 1), DP(J, 2), DP(J, 66), DP(J, 65))
              CON(IQN, J)     = DP(J, 1)
              CON(IQN, J + 2) = DP(J, 2)
              CON(IQN, J + 4) = DP(J, 66)
              CON(IQN, J + 6) = DP(J, 65)
            END DO
            JNSC(1, IQ) = ID1
C * CHECK FOR ATOM-OVER-BOND OVERLAP
            DUMP = 0.0
            CALL PLA105 (0, 0, 0, DUMP)
            NA1P1 = NA1 + 1
            DO IA = NA1P1, IPR(477)
              IATCIA = IATC(IA)
              IF (IATCIA /= 0) THEN
                IF (IA /= NA2 .AND. IATCIA <= NATOM) THEN
                  NIA = NASUP + IA
                  CALL GEN048 (-1, IFG(2, IATCIA), 27, ISKP)
                  IF (ISKP == 0) THEN
C * ROUGH CHECK FOR ATOM-OVER-BOND OVERLAP
                    DO J = 1, 2
                      IF (YMAX(J) <= XXO(NIA, 2 * J - 1)) ISKP = 1
                      IF (YMIN(J) >= XXO(NIA, 2 * J    )) ISKP = 1
                    END DO
                    IF (ISKP == 1) CYCLE
C * CHECK FOR TRUE ATOM-OVER-BOND OVERLAP
                    DUMP = 0.0
                    CALL PLA105 (1, IQ, IA, DUMP)
                    IF (DUMP > 0.0) THEN
                      IF (IPR(151) >= NP15) EXIT
                    ELSE IF (DUMP < 0.0) THEN
                      GO TO 80
                    END IF
                  END IF
                END IF
              END IF
            END DO
C * ROUGH CHECK FOR BOND-OVER-BOND OVERLAP OF BOND/LABEL NA1-NA2
C * SKIP IN CASE OF NO-BOND OUTLINES STORED
C * TEST FOR # BONDS > 0
            IF (NQD > 0) THEN
C * GET UNIT VECTOR ALONG BOND
              IF (MLOOP < 3) THEN
                DO J = 1, 3
                  V1(J)  = XXO(NA2, J) - XXO(NA1, J)
                END DO
                CALL GEN007 (AA, V1, V1, 1)
              END IF
C * LOOP OVER PROJECTED BOND OUTLINES
              DO 60 IB = 1, NQD
                NIB = NASUP + IB
                ID2 = JNSC(1, IB)
                IF (ID1 == ID2) GO TO 60
                NB2 = MOD (ID2, NP1 + 1)
                NB1 = ID2 / (NP1 + 1)
                IF (NA2 > NB1) GO TO 60
                DO J = 1, 2
                  IF (YMAX(J) <= MIN (CON(NIB, J), CON(NIB, J + 2),
     1              CON(NIB, J + 4), CON(NIB, J + 6))) GO TO 60
                  IF (YMIN(J) >= MAX (CON(NIB, J), CON(NIB, J + 2),
     1              CON(NIB, J + 4), CON(NIB, J + 6))) GO TO 60
                END DO
C * SET UP LINEAR FORMS FOR EDGES OF QUADRANGLE
                DO L = 1, 4
                  K         = 2 * L
                  K1        = MOD (K, 8) + 2
                  QUA(1, L) = CON(NIB, K)      - CON(NIB, K1)
                  QUA(2, L) = CON(NIB, K1 - 1) - CON(NIB, K - 1)
                  QUA(3, L) = CON(NIB, K - 1)  * CON(NIB, K1)
     1                      - CON(NIB, K)      * CON(NIB, K1 - 1)
C * NORMALIZE LINE EQUATION COEFFICIENTS
                  T1 = SQRT (QUA(1, L)**2 + QUA(2, L)**2)
                  IF (T1 <= 0.0) GO TO 60
                  DO J = 1, 3
                    QUA(J, L) = QUA(J, L) / T1
                  END DO
                END DO
C * EVALUATE LINEAR FORMS AND SIGNATURES FOR QUADRANGLE
                T3    = 3.0
                NASIQ = NASUP + IQ
                SCONX = 0.0
                SCONY = 0.0
                DO K = 1, 4
                  T2 = 3.0
                  J  = K * 2
                  XCONK = CON(NASIQ, J - 1)
                  YCONK = CON(NASIQ, J)
                  SCONX = SCONX + XCONK
                  SCONY = SCONY + YCONK
                  DO L = 1, 4
                    T1 = XCONK * QUA(1, L)
     1                 + YCONK * QUA(2, L) + QUA(3, L)
                    IF (T1 < 0.0) T2 = T2 - 1.0
                    FL(L, K) = T1
                  END DO
                  IF (T2 < 0.0) T3 = T3 - 1.0
                END DO
                IF (MLOOP == 3) THEN
                  XCONK = SCONX / 4.0
                  YCONK = SCONY / 4.0
                  T2    = 3.0
                  DO L = 1, 4
                    T1 = XCONK * QUA(1, L)
     1                 + YCONK * QUA(2, L) + QUA(3, L)
                    IF (T1 < 0.0) T2 = T2 - 1.0
                  END DO
                  IF (T2 < 0.0) GO TO 20
                END IF
C * CHECK FOR 4 POINTS INSIDE QUADRANGLE
                IF (T3 < 0.0) THEN
                  ITYPE = -1
C * CHECK FOR 1 TO 3 POINTS INSIDE QUADRANGLE
                ELSE IF (T3 < 3.0) THEN
                  ITYPE = 0
                ELSE
C * DETERMINE WHICH EDGES ARE CROSSED BY THE 4 LINE SEGMENTS
                  NASIQ = NASUP + IQ
                  DO L = 1, 4
                    L1 = MOD (L, 4) + 1
C * LINE SEGMENT L FROM POINT Y1 TO POINT Y2
                    Y1(1) = CON(NASIQ, L  * 2 - 1)
                    Y1(2) = CON(NASIQ, L  * 2)
                    Y2(1) = CON(NASIQ, L1 * 2 - 1)
                    Y2(2) = CON(NASIQ, L1 * 2)
                    DO K = 1, 4
                      T1 = FL(K, L)
                      T2 = FL(K, L1)
                      T3 = T1 - T2
C * T1 AND T2 MUST HAVE OPPOSITE SIGNS FOR INTERSECTION TO OCCUR
                      IF (T1 * T2 <= 0.0) THEN
C * COMPONENT OF SEGMENT L PERPENDICULAR TO EDGE K OF IB IS T3
                        IF (ABS(T3) > PAR(54)) THEN
C * CALCULATE COORDINATES OF INTERSECTION
                          T4 = (T1 * Y2(1) - T2 * Y1(1)) / T3
                          T5 = (T1 * Y2(2) - T2 * Y1(2)) / T3
                          K0 = 2 * K
                          K1 = 2 * (MOD (K, 4) + 1)
C * IS INTERSECTION WITHIN QUADRANGLE IQ
                          IF ((T4 - CON(NIB, K0 - 1)) *
     1                      (CON(NIB, K1 - 1) - T4)
     2                      + (T5 - CON(NIB, K0)) *
     3                      (CON(NIB, K1) - T5) > -1.E-4) GO TO 40
                        END IF
                      END IF
                    END DO
                  END DO
                  GO TO 60
   40             ITYPE = 1
                END IF
                IF (MLOOP < 3) THEN
C * CHECK FOR EXACT DISORDERED BOND OBERLAP
                  DIF = 0.0
                  DO J = 1, 3
                    DIF = DIF + ABS (XXO(NA1,J) - XXO(NB1, J)) +
     1                          ABS (XXO(NA2,J) - XXO(NB2, J))
                  END DO
                  IF (DIF < 0.001) GO TO 60
C * CHECK OVER/UNDER AMBIGUITY
                  IF (NA1 == NB1 .OR. NA1 == NB2 .OR.
     1                NA2 == NB2 .OR. NA2 == NB1) THEN
C * BONDS SHARE AN ATOM
                    IF ((NA1 + NA2) < (NB1 + NB2)) THEN
                      GO TO 50
                    ELSE
                      GO TO 60
                    END IF
                  END IF
                  DO J = 1, 3
                    V2(J) = XXO(NB2, J) - XXO(NB1, J)
                    V4(J) = XXO(NB1, J) - XXO(NA1, J)
                  END DO
C * GET UNIT-VECTORS
                  CALL GEN007 (AA, V2, V2, 1)
                  CALL GEN007 (AA, V4, V4, 1)
                  CALL GEN011 (BB, V1, V2, V3, 1)
                  IF (GEN009 (V3, V3) <= PAR(54)) THEN
C * PARALLEL BONDS, RECALCULATE V3
                    CALL GEN011 (BB, V1, V4, V5, 1)
                    CALL GEN011 (BB, V5, V1, V3, 1)
C * CHECK FOR COLLINEAR BONDS
                    IF (GEN009 (V3, V3) > PAR(54)) THEN
                      IF (V3(3) <= 0.0) GO TO 60
                    END IF
                    GO TO 50
                  END IF
                  IF (GEN009 (V3, V4) < - PAR(54)) THEN
                    DO J = 1, 3
                      V3(J) = - V3(J)
                    END DO
                  END IF
C * V3 IS NORMAL TO BONDS IQ AND IB GOING FROM IQ TOWARD IB
                  IF (V3(3) <= 0.0) GO TO 60
C * OVERLAPPING BOND FOUND
C * HIDDEN BOND
                END IF
   50           IF (ITYPE < 0) GO TO 80
C * STORE INTERFERING QUADRANGLE
                IF (IPR(152) < NP7) THEN
                  IPR(152) = IPR(152) + 1
                  DO K = 1, 4
                    DO J = 1, 3
                      XDIR(IPR(152), J, K) = QUA(J, K)
                    END DO
                  END DO
                  IDIR(IPR(152)) = IB
                ELSE
C * OVERFLOW WARNING
                  WRITE (6, 99998)
                  GO TO 70
                END IF
   60         CONTINUE
            END IF
C * DRAW BOND ENDS OUTLINE
   70       IF (MLOOP < 3) THEN
              CALL PLA106 (1, 4, 129, 3)
              CALL PLA106 (2, 4, 66,  3)
C * DRAW BOND DETAIL (DIRECTION OF DRAWING ALTERNATED)
              BDIR = - 0.5
              DO K = 1, 65, NBND
                BDIR = - BDIR
                DO J = 1, 2
                  DP(J, 130 + NINT (1.5 - BDIR)) = DP(J, K)
                  DP(J, 130 + NINT (1.5 + BDIR)) = DP(J, K + 1)
                END DO
C * FULL/DASHED BOND
                IF (IDASH == 1) THEN
                  NSTEP = NINT(DIST / 0.4) * 2 + 1
                ELSE
                  NSTEP = 1
                END IF
                DELX  = (DP(1, 132) - DP(1, 131)) / NSTEP
                DELY  = (DP(2, 132) - DP(2, 131)) / NSTEP
                DO J = 1, NSTEP, 2
                  DP(1, 132) = DP(1, 131) + DELX
                  DP(2, 132) = DP(2, 131) + DELY
                  CALL PLA106 (131, 1, 132, 3)
                  DP(1, 131) = DP(1, 131) + 2 * DELX
                  DP(2, 131) = DP(2, 131) + 2 * DELY
                END DO
              END DO
            ELSE
C * CHECK FOR CROT
              IF (IPR(151) > 0 .OR. IPR(152) > 0) GO TO 20
            END IF
          END IF
   80   CONTINUE
      END DO
      RETURN
99999 FORMAT (':: Label Positioning Problem for ', A)
99998 FORMAT ('NP7 OVERFLOW WARNING IN ORTEP/OVERLAP')
      END SUBROUTINE PLA102
 
      SUBROUTINE PLA103
C * ADP/ORTEP - DRAW ELLIPSOIDS
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      USE ortep
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: II
      INTEGER :: IJ
      INTEGER :: IA
      INTEGER :: ID
      INTEGER :: KA
      INTEGER :: KB
      INTEGER :: IQ
      INTEGER :: NA1
      INTEGER :: NA2
      INTEGER :: NO1
      INTEGER :: KAT
      INTEGER :: NRI
      INTEGER :: II0
      INTEGER :: II1
      INTEGER :: II2
      INTEGER :: NIQ
      INTEGER :: JEND
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: HINC
      INTEGER :: IHAT
      INTEGER :: ITOM
      INTEGER :: NTOM
      INTEGER :: IVAL
      INTEGER :: ISKP
      INTEGER :: NBIS
      INTEGER :: NRES1
      INTEGER :: NFRST
      INTEGER :: LINES
      INTEGER :: IATCIA
      INTEGER :: NFIRST
      INTEGER :: NRESOL
      REAL :: TX
      REAL :: DET
      REAL :: YNK
      REAL :: PHI
      REAL :: AOV3
      REAL :: BOV3
      REAL :: POV3
      REAL :: ROOT
      REAL :: XLNG
      REAL :: OVMR
      REAL :: QOV2
      REAL :: COLX
      REAL :: DUMP
      REAL :: XLPOS
      REAL :: YLPOS
      REAL :: PQTEST
      REAL :: AOV3SQ
      REAL :: POV3CU
      REAL :: QOV2SQ
      REAL :: GEN006
      REAL :: GEN009
      REAL, DIMENSION(2) :: DETER
      DO 60 ITOM = 1, IPR(477)
        IF (CC) RETURN
        NTOM = NASUP + ITOM
C * GET ATOM NUMBER IN FULL ATOM DATA LIST
        KAT = IATC(ITOM)
        IF (KAT == 0) GO TO 60
C * IGNORE SUPPORT ATOM (CG etc)
        IF (KAT > NATOM) THEN
          IF (IPR(506) == 0) GO TO 60
        END IF
C * IGNORE ELIMINATED ATOMS
        CALL GEN048 (-1, IFG(2, KAT), 27, ISKP)
        IF (ISKP == 1) GO TO 60
C * GET ENCLOSING BOX DIMENSIONS
        DO I = 1, 2
          YMIN(I) = XXO(NTOM, 2 * I - 1)
          YMAX(I) = XXO(NTOM, 2 * I    )
        END DO
C * GET ATOM TYPE
        CALL GEN048 (-4, IFG(1, KAT), 15, NO1)
        NO1 = NO1 + 1
C * SET ELLIPSOID GRAPHIC DETAILS
C * C-ATOM
        IF (IEN(NO1) == 2) THEN
          NFRST = IPR(175)
          LINES = IPR(176)
C * H-ATOM (H, D OR Hw)
        ELSE IF (IEN(NO1) == 1 .OR. IEN(NO1) == 33 .OR.
     1           IEN(NO1) == 113) THEN
          NFRST = IPR(177)
          LINES = IPR(178)
C * OTHER
        ELSE
          NFRST = IPR(179)
          LINES = IPR(180)
        END IF
C * ENVELOPE
        IF (IPR(211) == 1) THEN
          NFRST = 0
C * OCTANT
        ELSE IF (IPR(211) == 2) THEN
          CALL GEN048 (-1, IFG(1, KAT), 7, IVAL)
          IF (IVAL == 0) THEN
            NFRST = 1
          ELSE
            NFRST = IPR(177)
          END IF
          LINES = IPR(180)
        END IF
C * NFRST = 1 : 3D ELLIPSOIDS, NFRST = 0 : 2D OUTLINE
        DO I = 1, 3
          V1(I) = VOID((KAT - 1) * NP71 + I)
          V7(I) = XXO(ITOM, I)
        END DO
C * GET LABEL AND NUMBER OF NON-BLANK POSITIONS
        CALL PLA047 (LABA(KAT), NQ1, IDUM, JDUM, IPR(350),
     1               IGBL(55), 0, 1 - IGBL(55))
C * PLOT LABEL
        IF (IGBL(75) > 0) THEN
          CALL GEN048 (-1, IFG(2, KAT), 11, IVAL)
          CALL GEN048 (-1, IFG(2, KAT), 12, HINC)
          CALL GEN048 (-1, IFG(1, KAT),  7, IHAT)
          CALL GEN048 (-2, IFG(1, KAT), 28, ICHIRAL)
          CALL GEN039 (1, NQ1, 1, NP64 - 2, NB, NP)
C * ADD CHIRAL INFO TO DISPLAYED ATOM LABEL
          IF (IPR(18) == 1) THEN
            IF (ICHIRAL == 1) THEN
              NQ1(NP + 1 : NP + 2) = ':S'
              NP = NP + 2
            ELSE IF (ICHIRAL == 3) THEN
              NQ1(NP + 1 : NP + 2) = ':R'
              NP = NP + 2
            END IF
          END IF
          IF ((IHAT /= 1 .AND. IEN(NO1) >  IPR(618) * 2) .OR.
     1      (MAX (IPR(212), HINC) * IPR(232) > 0 .AND.
     2       IPR(618) .EQ.0)) THEN
C * SET COLOR BLACK
            IF (IPR(116) == 0) THEN
              IF (IPR(328) == 0) THEN
                COLX = FLOAT (IVAL)
              ELSE
                COLX = FLOAT (2 - IVAL)
              END IF
              CALL GGIP (0.0, COLX, 0.0, 0)
            END IF
            XLPOS = VOID(KAT * NP71 - 2)
            YLPOS = VOID(KAT * NP71 - 1)
            IF ((XLPOS > 1.0 .OR. YLPOS > 1.0) .AND. COLX /= 0.0)
     1        CALL PLA439 (0.0, NQ1, NP, PAR(349), -1, 1, XLPOS, YLPOS)
            IF (IPR(116) == 0) CALL GGIP (0.0, 1.0, 0.0, 0)
          END IF
        END IF
C * IGNORE CG-ELLIPSOIDS
        IF (KAT > NATOM) GO TO 60
C * SET ATOM COLOR
        IF (IPR(116) == 0 .AND. IPR(346) == 1) THEN
          CALL GEN048 (-4, IFG(1, KAT), 15, NRI)
          CALL GGIP (0.0, FLOAT (IACL(NRI + 1)) , 0.0, 0)
        END IF
C * OVERLAP HANDLING (NCOVR, NQOVR)
        IPR(151) = 0
        IPR(152) = 0
        IF (IPR(477) > ITOM) THEN
C * ROUGH CHECK FOR OVERLAPPING ATOMS
          L = 0
          DO 40 IA = ITOM, IPR(477)
C * IGNORE SUPPORT ATOMS (EG Cg ..)
            IATCIA = IATC(IA)
            IF (IATCIA == 0) GO TO 40
            IF (IATCIA > NATOM) GO TO 40
            CALL GEN048 (-1, IFG(2, IATCIA), 27, ISKP)
            IF (ISKP == 1) GO TO 40
            NIA = NASUP + IA
            IF (IA > ITOM) THEN
              DO I = 1, 2
                IF (YMAX(I) <= XXO(NIA, 2 * I - 1)) GO TO 40
                IF (YMIN(I) >= XXO(NIA, 2 * I    )) GO TO 40
              END DO
            END IF
C * EXACT CHECK FOR OVERLAPPING ATOMS
            IF (L < 2) L = L + 1
            IF (L == 2) THEN
              OVMR = 0.0
            ELSE
              OVMR = PAR(44)
            END IF
C * TRANSFORM CONIC TO PLOTTER HOMOGENEOUS COORDINATE SYSTEM
            V12(1, L)   = (XXO(NIA, 1) + XXO(NIA, 2)) * 0.5
            V12(2, L)   = (XXO(NIA, 3) + XXO(NIA, 4)) * 0.5
            V12(3, L)   = 1.0
            QA(1, 1, L) = XSD(NIA, 1)
            QA(1, 2, L) = XSD(NIA, 2)
            QA(2, 1, L) = XSD(NIA, 2)
            QA(2, 2, L) = XSD(NIA, 3)
            TX = XXO(NIA, 2) - XXO(NIA, 1) + XXO(NIA, 4) - XXO(NIA, 3)
            QA(3, 3, L) = -(1.0 - 4.0 * OVMR / TX)**2
            DO K = 1, 2
              QA(K, 3, L) = 0.0
              DO J = 1, 2
                QA(K, 3, L) = QA(K, 3, L) - V12(J, L) * QA(J, K, L)
              END DO
              QA(3, K, L) = QA(K, 3, L)
              QA(3, 3, L) = QA(3, 3, L) - QA(3, K, L) * V12(K, L)
            END DO
C * CALCULATE COFACTORS AND DETERMINANTS
            CALL GEN003 (QA(1, 1, L), QC(1, 1, L), DET, -1)
            DETER(L) = DET * 3.0
C * DETER(L) IS THE DETERMINANT TIMES 3
            IF (L < 2) GO TO 40
C * FORM CHARACTERISTIC EQUATION AND EXAMINE ITS ROOTS
            AOV3 = 0.0
            BOV3 = 0.0
            DO J = 1, 3
              DO K = 1, 3
                AOV3 = AOV3 + QC(J, K, 2) * QA(J, K, 1)
                BOV3 = BOV3 + QC(J, K, 1) * QA(J, K, 2)
              END DO
            END DO
            AOV3   = AOV3 / DETER(2)
            AOV3SQ = AOV3**2
            BOV3   = BOV3 / DETER(2)
            POV3   = BOV3 - AOV3SQ
            QOV2   = AOV3 * (AOV3SQ - BOV3 * 1.5) + DETER(1) /
     1               (DETER(2) * 2.0)
C * CHECK DISCRIMINANT OF CHARACTERISTIC CUBIC EQUATION
            POV3CU = POV3**3
            QOV2SQ = QOV2**2
            PQTEST = POV3CU + QOV2SQ
            IF (PQTEST > 0.0) THEN
              IF (PQTEST + POV3CU * 0.00001 > 0.0) THEN
                GO TO 30
              END IF
            ELSE IF (PQTEST < 0.0) THEN
              IF (PQTEST + QOV2SQ * 0.00001 < 0.0) THEN
C * THREE REAL ROOTS, ALL DIFFERENT
C * NO INTERSECTION IF A/3 AND B/3 INVARIANTS ARE NEGATIVE
                IF (AOV3 < 0.0) THEN
                  IF (BOV3 < 0.0) GO TO 40
                END IF
C * CALCULATE ONE ROOT OF CHARACTERISTIC CUBIC EQUATION
                IF (QOV2 == 0.0) THEN
                  PHI = RGBL(5) / 4.0
                ELSE
                  PHI = ATAN (- SQRT ( - PQTEST) / QOV2)
                  IF (PHI < 0.0) PHI = PHI + RGBL(5) / 2.0
                END IF
                ROOT = 2.0 * SQRT ( - POV3) * COS (PHI / 3.0) - AOV3
                GO TO 10
              END IF
            END IF
C * THREE REAL ROOTS, AT LEAST TWO ARE EQUAL
C * CHECK SIGNS OF INVARIANTS A/3 AND B/3
            IF (AOV3 < 0.0 .AND. BOV3 < 0.0) GO TO 40
C * CALCULATE REPEATED ROOT OF CUBIC EQUATION
            ROOT = SIGN (SQRT( - POV3), QOV2) - AOV3
C * FORM DEGENERATE CONIC (LINE PAIR WHICH MAY BE COINCIDENT)
   10       DO J = 1, 3
              DO K = 1, 3
                DAM(J, K) = QA(J, K, 1) + ROOT * QA(J, K, 2)
              END DO
            END DO
C * EXAMINE INVARIANTS OF THE DEGENERATE CONIC
            T6 = DAM(1, 1) * DAM(2, 2)
            T7 = DAM(1, 2)**2
C * NEGATIVE DENOTES REAL INTERSECTING LINE PAIR
C * POSITIVE DENOTES IMAGINARY LINES INTERSECTING AT REAL POINT
            IF (T6 > 1.0001 * T7) THEN
              GO TO 20
            ELSE IF (T6 <  0.9999 * T7) THEN
              GO TO 30
            ELSE
              T8 = DAM(3, 3) * (DAM(1, 1) + DAM(2, 2))
              T9 = DAM(1, 3)**2 + DAM(2, 3)**2
C * NEGATIVE DENOTES REAL PARALLEL LINE PAIR
C * POSITIVE DENOTES IMAGINARY PARALLELS
C * ZERO DENOTES ONE REAL LINE (COINCIDENT PARALLELS)
              IF (T8 * 1.0001 < T9) GO TO 30
            END IF
C * COINCIDENT LINE PAIR FOUND FOR THE REPEATED ROOT
C * COMPARE AREAS OF CONICS
   20       IF (QC(3, 3, 1) < QC(3, 3, 2)) THEN
              KA = 2
              KB = 1
            ELSE
              KA = 1
              KB = 2
            END IF
C * SEE IF ONE CONIC IS INSIDE THE OTHER CONIC
            T1 = 0.0
            DO J = 1, 3
              T2 = QA(J, 3, KB)
              DO K = 1, 2
                T2 = T2 + QA(J, K, KB) * V12(K, KA)
              END DO
              T1 = T1 + V12(J, KA) * T2
            END DO
C * DISCARD IF KA IS OUTSIDE KB
            IF (T1 > 0.0) GO TO 40
C * THE OVERLAPPING ATOM HIDES THE ORIGINAL ATOM FOR KA = 1
            IF (KA == 1) GO TO 60
C * STORE OVERLAPPING ATOM
   30       IF (IPR(151) <  NP15) IPR(151) = IPR(151) + 1
            IJ = 1
            DO I = 1, 3
              DO J = I, 3
                XXO(IPR(174) + IPR(151), IJ) = QA(I, J, 2)
                IJ = IJ + 1
              END DO
            END DO
   40     CONTINUE
C * SECOND PART OF SUBROUTINE CHECKS FOR BONDS OVER THE ATOM
          IF (NQD > 0) THEN
            DUMP = 0.0
            CALL PLA105 (0, 0, 0, DUMP)
C * ROUGH CHECK FOR OVERLAPPING BONDS
            DO 50 IQ = 1, NQD
              NIQ = NASUP + IQ
              ID  = JNSC(1, IQ)
              NA1 = ID / (NP1 + 1)
              NA2 = MOD (ID, NP1 + 1)
              IF (ITOM <= NA2) THEN
                DO J = 1, 2
                  IF (YMAX(J) <= MIN (CON(NIQ, J),
     1              CON(NIQ, J + 2), CON(NIQ, J + 4),
     2              CON(NIQ, J + 6))) GO TO 50
                  IF (YMIN(J) >= MAX (CON(NIQ, J),
     1              CON(NIQ, J + 2), CON(NIQ, J + 4),
     2              CON(NIQ, J + 6))) GO TO 50
                END DO
C * EXACT CHECK FOR OVERLAPPING BONDS
                CALL PLA105 (-1, IQ, ITOM, YNK)
                IF (YNK < 0.0) GO TO 60
                IF (IPR(152) >= NP7) EXIT
              END IF
   50       CONTINUE
          END IF
        END IF
C * ELLIPSOID PRINCIPAL VECTORS TOWARD VIEWER
C * CONTRAVARIANT EIGENVECTORS FOR Q IN COLUMNS OF PAC
 
        DO I = 1, 9
          J = MOD (I - 1, 3) + 1
          K = ((I - 1) / 3)  + 1
          PAT(J, K) = CON(KAT, I)
        END DO
C * TRANSFORM TO CARTESIAN SYSTEMS
C * TRANSPOSE(TRANSPOSE(PAT) * AAREV) = TRANSPOSE(AAREV) * PAT = PAC
        CALL GEN005 (AAREV, QM)
        CALL GEN004 (QM, PAT, PAC)
C * FORM DIAGONAL MATRIX OR ITS INVERSE
        DO J = 1, 3
          T1 = XSD(KAT, J)
          IF (T1 /= 0.0) THEN
            V6(J)  = 1.0 / (T1**2)
          ELSE
            V6(J)  = 1.0
          END IF
          RMS(J) = T1
        END DO
C * FORM QUADRATIC FORM
        CALL GEN099 (PAC, V6, QM)
        CALL GEN002 (-1, AA, VIEWV, V2, XLNG)
        DO I = 1, 3
          IF (GEN009 (V2, PAT(1, I)) < 0.0) THEN
            DO J = 1, 3
              PAC(J, I) = - PAC(J, I)
              PAT(J, I) = - PAT(J, I)
            END DO
          END IF
        END DO
        DO J = 1, 3
          PAC(J, 4) = PAC(J, 1)
          PAC(J, 5) = PAC(J, 2)
        END DO
C * V4 = VECTOR NORMAL TO POLAR PLANE
        CALL GEN002 (-1, AAREV, VIEWV, V6, XLNG)
        CALL GEN007 (AA, V6, V6, 1)
        CALL GEN002 (1, QM, V6, V4, XLNG)
        CALL GEN007 (AA, V4, V4, 1)
C * SET PLOTTING RESOLUTION FOR ELLIPSOID
        T3     = RMS(3) * PAR(47)
        NRESOL = 1
        NBIS   = 5
        DO J = 1, 3
          IF (T3 < PAR(50 + J)) THEN
            NBIS   = NBIS - 1
            NRESOL = NRESOL * 2
          ELSE
            EXIT
          END IF
        END DO
        NRES1 = NRESOL + 1
C * LOOP THROUGH PRINCIPAL AND POLAR PLANES
        NFIRST = 4 - 3 * NFRST
        DO II = NFIRST, 4
          II0 = MOD (II + 2, 3) + 1
          II1 = MOD (II, 3) + 1
          II2 = MOD (II + 1, 3) + 1
C * GENERATE CONJUGATE DIAMETERS
          IF (0.99938 <= ABS (GEN009 (V4, PAC(1, II2)))) THEN
            T1 = RMS(II0) * PAR(47)
            T2 = RMS(II1) * PAR(47)
            DO J = 1, 3
              DAM(J, 1) = PAC(J, II0) * T1
              DAM(J, 2) = PAC(J, II1) * T2
            END DO
          ELSE
            CALL GEN011 (BB, PAC(1, II0), PAC(1, II1), V1, 1)
            CALL GEN011 (BB, V1, V4, V2, 1)
            CALL GEN007 (AA, V2, V2, 1)
            CALL GEN002 (1, QM, V2, V3, XLNG)
            IF (II < 4) THEN
 
              CALL GEN011 (BB, V3, V1, V5, 1)
            ELSE
              CALL GEN011 (BB, V3, V4, V5, 1)
            END IF
            CALL GEN007 (AA, V5, V5, 1)
            T1 = MAX (1.0E-10, GEN006 (V2, QM, V2))
            T2 = MAX (1.0E-10, GEN006 (V5, QM, V5))
            DO J = 1, 3
              DAM(J, 1) = V2(J) * PAR(47) / SQRT (T1)
              DAM(J, 2) = V5(J) * PAR(47) / SQRT (T2)
            END DO
          END IF
C * GENERATE ELLIPSE FROM TWO CONJUGATE VECTORS
C * ORTHONORMAL VECTORS PRODUCE 8-128 SPOKED CIRCLE
C * ND DENOTES NUMBER OF SUBDIVISIONS (1 TO 5)
          DO J = 1, 3
            T1           = DAM(J, 1)
            SCIR(J, 1)   = T1
            SCIR(J, 129) = T1
            SCIR(J, 65)  = -T1
            T1           = DAM(J, 2)
            SCIR(J, 33)  = T1
            SCIR(J, 97)  = -T1
          END DO
          DO K = 1, NBIS
            T1    =
     1        SQRT (1.0 / (2.0 * (1.0 + COS (RGBL(5) / 2**(K + 1)))))
            KDEL  = 2**(6 - K)
            KDEL1 = KDEL + 1
            KDEL2 = KDEL / 2
            DO L = KDEL1, 65, KDEL
              J = L - KDEL
              M = L - KDEL2
              DO N = 1, 3
                T2 = (SCIR(N, L) + SCIR(N, J)) * T1
                SCIR(N, M)      =   T2
                SCIR(N, M + 64) = - T2
              END DO
            END DO
          END DO
          IF (II < 4) THEN
C * PLOT HALF AN ELLIPSE
            JEND = 65
          ELSE
C * PLOT SOLID BOUNDARY ELLIPSE
            JEND = 129
          END IF
C * 3D CARTESIAN TO 2D PLOTTER COORDINATES
          DO J = 1, JEND, NRESOL
            DP(1, J) = SCIR(1, J) + V7(1)
            DP(2, J) = SCIR(2, J) + V7(2)
          END DO
          CALL PLA106 (1, 1, 1, 3)
          CALL PLA106 (NRES1, NRESOL, JEND, 2)
          IF (II < 4) THEN
C * DETAIL INTERIOR FEATURES
            DO J = 1, 3
              T1 = PAC(J, II0) * RMS(II0) * PAR(47)
              DAM(J, 1) = T1
              DAM(J, 2) = PAC(J, II1) * RMS(II1) * PAR(47)
              DAM(J, 3) = 0.0
            END DO
C * SOLID LINE FOR FORWARD AXIS
            IF (LINES > 0) THEN
C * 3D CARTESIAN TO 2D PLOTTER COORDINATES
              DO I = 1, 3, 1
                DP(1, I) = DAM(1, I) + V7(1)
                DP(2, I) = DAM(2, I) + V7(2)
              END DO
              CALL PLA106 (1, 2, 3, 3)
C * SHADE QUADRANT BETWEEN TWO PRINCIPAL AXES
              L = LINES - 1
              IF (L > 0) THEN
                DO I = 1, L
                  T1 = FLOAT (I) / LINES
                  T3 = SQRT (1.0 - T1**2)
                  IF (MOD (I, 2) /= 0) THEN
                    M = I * 2
                    N = M - 1
                  ELSE
                    N = I * 2
                    M = N - 1
                  END IF
                  DO J = 1, 3
                    T4 = DAM(J, 1) * T1
                    SCIR(J, M) = T4
                    SCIR(J, N) = DAM(J, 2) * T3 + T4
                  END DO
                END DO
                L = L * 2
C * 3D CARTESIAN TO 2D PLOTTER COORDINATES
                DO I = 1, L
                  DP(1, I) = SCIR(1, I) + V7(1)
                  DP(2, I) = SCIR(2, I) + V7(2)
                END DO
                CALL PLA106 (1, 1, L, -3)
              END IF
            END IF
          END IF
        END DO
   60 CONTINUE
      RETURN
      END SUBROUTINE PLA103
 
      SUBROUTINE PLA104
C * MANAGE MOL-LIST FOR ORTEP
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: KN
      INTEGER :: NS
      INTEGER :: MLS
      INTEGER :: NMOL
      KN   = IPR(221)
      NMOL = IPR(53)
      IF (KN > 0) THEN
        DO 10 I = 1, KN
          NS = INT (ABS (FN(I)) / 1000.0)
          IF (NS <= IPR(48)) THEN
            MLS = NINT (FN(I) * 100.0)
            IF (NINT (FN(I)) * 100 == MLS) THEN
              IF (MLS > 0) THEN
                MLS = MLS + 1
              ELSE
                MLS = MLS - 1
              END IF
            END IF
C * SKIP/DELETE ARU
            IF (NMOL > 0) THEN
              DO J = 1, NMOL
                IF (IABS (MLS) == MOLS(J)) THEN
                  IF (MLS > 0) THEN
                    GO TO 10
                  ELSE
                    IF (J .LT. NMOL) THEN
                      DO K = J + 1, NMOL
                        MOLS(K - 1) = MOLS(K)
                      END DO
                    END IF
                    NMOL = NMOL - 1
                    GO TO 10
                  END IF
                END IF
              END DO
            END IF
C * ADD ARU
            NMOL       = NMOL + 1
            MOLS(NMOL) = MLS
          END IF
   10   CONTINUE
      END IF
      IPR(53) = NMOL
      DO I = 1, IPR(53)
        MOL(I) = MOLS(I)
      END DO
      IPR(13) = IPR(53)
      IF (IPR(17) /= 0) THEN
        IPR(17) = 0
C * SET FLAGS ETC
        CALL PLA087
      END IF
      IPR(39) = IPR(37)
C * GENERATE ATOMS FOR SYMMETRY RELATED UNIT
      CALL PLA072 (-1)
C * OUTPUT CONNECTED SET
      CALL PLA024
C * SYMMETRY CODE LISTING
      CALL PLA043 (0, -2, LU6, 0)
C * REPOSITION LABELS
      IPR(201) = 0
C * RESET # OF CENTROIDS
      IPR(64)  = 0
      RETURN
      END SUBROUTINE PLA104
 
      SUBROUTINE PLA105 (MODE, IQ, IA, PCQ)
C * SUBROUTINE CHECKS FOR OVERLAP BETWEEN ATOMS AND BONDS
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: L
      INTEGER       :: K1
      INTEGER       :: L1
      INTEGER       :: IQ
      INTEGER       :: IA
      INTEGER       :: ID
      INTEGER, SAVE :: ITY
      INTEGER       :: NIA
      INTEGER       :: NIQ
      INTEGER       :: NA1
      INTEGER       :: NA2
      INTEGER       :: MODE
      INTEGER       :: NSUP
      INTEGER       :: NASUP
      INTEGER       :: NATOM
      INTEGER       :: ITYPE
      REAL :: T1
      REAL :: T2
      REAL :: T3
      REAL :: T4
      REAL :: T5
      REAL :: TX
      REAL :: PCQ
      REAL :: OVMG
      REAL :: GEN009
      REAL, DIMENSION(4)    :: BF
      REAL, DIMENSION(5)    :: QF
      REAL, DIMENSION(3, 4) :: QUA
      REAL, DIMENSION(3, 3) :: CONX
C * MODE = 0, INITIALIZE
C * MODE > 0, CHECK FOR ATOMS OVER A BOND
C * MODE < 0, CHECK FOR BONDS OVER AN ATOM
      IF (MODE == 0) THEN
        ITY = 0
      ELSE
C * GET NUMBER OF ATOMS
        NATOM = IPR(39)
C * GET NUMBER OF SUPPORT POSITIONS
        NSUP  = IPR(64)
        NASUP = NATOM + NSUP
        NIA   = NASUP + IA
        NIQ   = NASUP + IQ
        PCQ   = 0.0
        ID    = JNSC(1, IQ)
        NA1   = ID / (NP1 + 1)
        NA2   = MOD (ID, NP1 + 1)
        ITY   = ITY + MODE
        IF (ITY > 0) THEN
          OVMG = 0.0
        ELSE
          OVMG = PAR(44)
        END IF
        IF (ITY > -2) THEN
C * TRANSFORM CONIC TO PLOTTER HOMOGENEOUS COORDINATE SYSTEM
          V1(1)      = (XXO(NIA, 1) + XXO(NIA, 2)) * 0.5
          V1(2)      = (XXO(NIA, 3) + XXO(NIA, 4)) * 0.5
          V1(3)      = 1.0
          CONX(1, 1) = XSD(NIA, 1)
          CONX(1, 2) = XSD(NIA, 2)
          CONX(2, 1) = XSD(NIA, 2)
          CONX(2, 2) = XSD(NIA, 3)
          TX = XXO(NIA, 2) - XXO(NIA, 1) + XXO(NIA, 4) - XXO(NIA, 3)
          CONX(3, 3) = - (1.0 - 4.0 * OVMG / TX)**2
          DO K = 1, 2
            CONX(K, 3) = 0.0
            DO J = 1, 2
              CONX(K, 3) = CONX(K, 3) - V1(J) * CONX(J, K)
            END DO
            CONX(3, K) = CONX(K, 3)
            CONX(3, 3) = CONX(3, 3) - CONX(3, K) * V1(K)
          END DO
        END IF
        IF (ITY < 2) THEN
C * SET UP LINEAR FORMS FOR EDGES OF QUADRANGLE
          DO L = 1, 4
            K         = 2 * L
            K1        = MOD (K, 8) + 2
            QUA(1, L) = CON(NIQ, K)      - CON(NIQ, K1)
            QUA(2, L) = CON(NIQ, K1 - 1) - CON(NIQ, K - 1)
            QUA(3, L) = CON(NIQ, K - 1)  * CON(NIQ, K1) -
     1                  CON(NIQ, K)      * CON(NIQ, K1 - 1)
            T1 = SQRT (QUA(1, L)**2 + QUA(2, L)**2)
            IF (T1 <= 0.0) THEN
              ITY = 0
              RETURN
            END IF
C * TRANSFORM COEFFICIENTS FOR EDGES TO NORMAL FORM
            DO J = 1, 3
              QUA(J, L) = QUA(J, L) / T1
            END DO
          END DO
        END IF
C * EVALUATE 4 QUADRATIC AND 4 BILINEAR FORMS
        V2(3) = 1.0
        V3(3) = 1.0
        T2    = 3.0
        DO L = 1, 4
          L1    = (MOD (L, 4) + 1) * 2
          V2(1) = CON(NIQ, 2 * L - 1)
          V2(2) = CON(NIQ, 2 * L)
          V3(1) = CON(NIQ, L1 - 1)
          V3(2) = CON(NIQ, L1)
          QF(L) = 0.0
          BF(L) = 0.0
          DO K = 1, 3
            T1 = CONX(3, K)
            DO J = 1, 2
              T1 = T1 + V2(J) * CONX(J, K)
            END DO
            QF(L) = QF(L) + T1 * V2(K)
            BF(L) = BF(L) + T1 * V3(K)
          END DO
          IF (QF(L) == 0.0)  THEN
            T2 = T2 - 0.8
          ELSE IF (QF(L) < 0.0) THEN
            T2 = T2 - 1.0
          END IF
        END DO
        QF(5) = QF(1)
C * CHECK FOR 4 POINTS OF QUADRANGLE INSIDE OR ON ELLIPSE
        IF (T2 < 0.0) THEN
          ITYPE = -1
        END IF
C * CHECK FOR 1 TO 3 POINTS OF QUADRANGLE INSIDE THE ELLIPSE
        IF (T2 >= 2.2)  THEN
C * CHECK FOR QUADRANGLE-ELLIPSE INTERSECTION
          DO K = 1, 4
C * EVALUATE DISCRIMINANT
            T1 = BF(K)**2 - QF(K) * QF(K + 1)
            IF (T1 > 0.0) THEN
              T1 = SQRT (T1)
C * IS INTERSECTION WITHIN BOUNDS OF QUADRANGLE
              T3 = QF(K) - BF(K)
              T4 = T3 + QF(K + 1) - BF(K)
              IF (ABS (T4) > PAR(54)) THEN
                T5 = (T3 - T1) / T4
                IF (T5 >= 0.0 .AND. T5 < 1.0) THEN
                  ITYPE = 0
                  IF (NA2 == IA) THEN
                    GO TO 20
                  ELSE IF (NA2 > IA) THEN
                    IF (NA1 >= IA) THEN
                      GO TO 20
                    ELSE
                      GO TO 10
                    END IF
                  ELSE
                    GO TO 10
                  END IF
                END IF
              END IF
            END IF
          END DO
C * NO VALID INTERSECTION FOUND
C * CHECK FOR CENTER OF ELLIPSE WITHIN THE QUADRANGLE
          T3 = 3.0
          DO K = 1, 4
            T1 = QUA(3, K)
            DO J = 1, 2
              T1 = T1 + V1(J) * QUA(J, K)
            END DO
            IF (T1 < 0.0) T3 = T3 - 1.0
          END DO
          IF (T3 >= 0.0) RETURN
          ITYPE = 1
          IF (IA >= NA2 .OR. IA <= NA1) GO TO 20
        ELSE
          ITYPE = 0
          IF (NA2 == IA .OR. (NA2 > IA .AND. NA1 >= IA))
     1        GO TO 20
        END IF
C * HANDLE ID, NA1 & NA2 = 0 CASE (LABELS ?)
   10   IF (ID == 0) GO TO 30
C * CHECK OVER/UNDER AMBIGUITY
        DO I = 1, 3
          V2(I) = XXO(NA2, I) - XXO(NA1, I)
          V3(I) = XXO(IA,  I) - XXO(NA1, I)
        END DO
        CALL GEN007 (AA, V2, V2, 1)
        CALL GEN007 (AA, V3, V3, 1)
        CALL GEN011 (BB, V2, V3, V4, 1)
        IF (GEN009 (V4, V4) <= PAR(54)) THEN
C * CENTER OF ATOM IQ IS ON THE BOND LINE
          IF (ITY > 0) THEN
            GO TO 30
          ELSE
            RETURN
          END IF
        END IF
C * CENTER OF ATOM IQ IS NOT ON THE BOND LINE
        CALL GEN011 (BB, V4, V2, V5, 1)
        T1 = - V5(3)
C * NO INTERFERENCE FOUND : PCQ = 0
        IF (T1 * FLOAT(ITY) > 0.0) RETURN
C * ITYPE = 1 ENCLOSED ELLIPSE / ITYPE = -1 ENCLOSED QUADRANGLE
   20   IF (ITYPE * ITY < 0) THEN
C * HIDDEN ATOM OR HIDDEN BOND
          PCQ = -1.0
          RETURN
        END IF
   30   PCQ = 1.0
        IF (ITY < 0) THEN
C * STORE INTERFERING QUADRANGLE
          IF (IPR(152) < NP7) THEN
            IPR(152) = IPR(152) + 1
            DO K = 1, 4
              DO J = 1, 3
                XDIR(IPR(152), J, K) = QUA(J, K)
              END DO
            END DO
            IDIR(IPR(152)) = IQ
          END IF
        ELSE
C * STORE INTERFERING ELLIPSE
          IF (IPR(151) < NP15) THEN
            IPR(151) = IPR(151) + 1
            L = 1
            DO I = 1, 3
              DO J = I, 3
                XXO(IPR(174) + IPR(151), L) = CONX(I, J)
                L                           = L + 1
              END DO
            END DO
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA105
 
      SUBROUTINE PLA106 (IND1, IND2, IND3, NPEN)
C * ELIMINATE HIDDEN AND DRAW VISIBLE LINE PARTS
      USE parameters
      USE plato
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IM
      INTEGER :: I12
      INTEGER :: NCO
      INTEGER :: KCQ
      INTEGER :: KBG
      INTEGER :: NIQ
      INTEGER :: IND1
      INTEGER :: IND2
      INTEGER :: IND3
      INTEGER :: NPEN
      INTEGER :: LPEN
      INTEGER :: KEND
      INTEGER :: MINT
      INTEGER :: NCOK
      INTEGER :: NQOVR
      INTEGER :: NCOVR
      INTEGER :: NCTOT
      INTEGER :: NASUP
      INTEGER :: NEXIT
      REAL :: P0
      REAL :: P1
      REAL :: T1
      REAL :: T2
      REAL :: T3
      REAL :: T4
      REAL :: T5
      REAL :: T6
      REAL, DIMENSION(3) :: Y
      REAL, DIMENSION(3) :: Z
      REAL, DIMENSION(2) :: YN
      REAL, DIMENSION(2) :: YO
      REAL, DIMENSION(2) :: SEG
C * NPEN =  3 - FIRST MOVE, THEN DRAW SEQUENCE
C * NPEN =  2 = DRAW SEQUENCE
C * NPEN = -3 = ALTERNATING MOVE,DRAW SEQUENCE
C * IND1 = BEGIN
C * IND2 = STEP
C * IND3 = END
C * NUMBER OF ATOM TYPE OBJECTS
      NASUP = IPR(39) + IPR(64)
C * NUMBER OF OVERLAPPING ATOM OBJECTS
      NCOVR = IPR(151)
C * NUMBER OF OVERLAPPING BOND OBJECTS
      NQOVR = IPR(152)
C * TOTAL NUMBER OF OVERLAPPING OBJECTS
      NCTOT = NCOVR + NQOVR
C * GET ADDRESS -1 OF COVER DATA
      NCO   = IPR(174)
      ZGGIP = 0.0
      LPEN  = IABS(NPEN)
      NEXIT = 0
C * LOOP OVER MOVE/DRAW INSTRUCTIONS IN ARRAY DP
      DO N = IND1, IND3, IND2
C * GET X & Y ; CHECK THEM AGAINST BOUNDRY LIMITS
        DO J = 1, 2
          Y(J) = MAX (0.0, MIN (DP(J, N), PAR(36 + J)))
        END DO
C * CHECK FOR NO OVERLAP
        IF (NCTOT == 0) THEN
          CALL GGIP (Y(1), Y(2), ZGGIP, LPEN)
        ELSE
C * CHECK ALL OVERLAPPING ATOMS AND BONDS
          IF (LPEN == 2) THEN
C * SAVE INFORMATION FROM LAST POINT IF PEN IS DOWN
            DO K = 1, 2
              YO(K) = YN(K)
            END DO
C * LOAD COVER DATA
            DO K = 1, NCTOT
              XSD(NCO + K, 1) = XSD(NCO + K, 2)
            END DO
            IF (NQOVR > 0) THEN
              DO K = 1, NQOVR
                DO J = 1, 4
                  CON(NCO + K, J) = CON(NCO + K, J + 4)
                END DO
              END DO
            END IF
          END IF
C * EVALUATE CONIC QUADRATIC FORMS AT NEW POINT YN (YN(3) = 1.0)
          DO K = 1, 2
            YN(K) = Y(K)
          END DO
          IF (NCOVR > 0) THEN
            KBG  = NCO + 1
            KEND = NCO + NCOVR
            DO K = KBG, KEND
              Z(1) = YN(1) * XXO(K, 1) + YN(2) * XXO(K, 2) + XXO(K, 3)
              Z(2) = YN(1) * XXO(K, 2) + YN(2) * XXO(K, 4) + XXO(K, 5)
              Z(3) = YN(1) * XXO(K, 3) + YN(2) * XXO(K, 5) + XXO(K, 6)
              XSD(K, 2) = Z(1) * YN(1) + Z(2) * YN(2) + Z(3)
C * EVALUATE CONIC BILINEAR FORM IF PEN IS DOWN
              IF (LPEN == 2) THEN
                XSD(K, 5) = Z(1) * YO(1) + Z(2) * YO(2) + Z(3)
              END IF
            END DO
          END IF
C * EVALUATE LINEAR FORMS AND SIGNATURE FOR QUADRANGLE
          IF (NQOVR > 0) THEN
            KCQ = NCO + NCOVR
            DO K = 1, NQOVR
              T2 = 3.0
              DO J = 1, 4
                T1 = YN(1) * XDIR(K, 1, J) + YN(2) * XDIR(K, 2, J)
     1             + XDIR(K, 3, J)
                IF (T1 < 0) T2 = T2 - 1.0
                CON(NCO + K, J + 4) = T1
              END DO
              KCQ = KCQ + 1
C * T2 = -1 INSIDE, = 0 ACROSS ANY EDGE, = 1 ACROSS ANY VERTEX
              XSD(KCQ, 2) = T2
            END DO
          END IF
C * IF PEN IS UP, OMIT ALL SUBSEQUENT CHECKING
          IF (LPEN == 3) THEN
            CALL GGIP (YN(1), YN(2), ZGGIP, 3)
            GO TO 20
          ELSE
C * CHECK FOR HIDDEN SEGMENT
            DO K = 1, NCTOT
              IF (XSD(NCO + K, 1) < 0.0 .AND.
     1            XSD(NCO + K, 2) < 0.0) THEN
                CALL GGIP (YN(1), YN(2), ZGGIP, 3)
                GO TO 20
              END IF
            END DO
          END IF
C * FIND ENTRY AND EXIT POINTS ON EACH CONIC
          MINT = 0
          IF (NCOVR > 0) THEN
            DO K = 1, NCOVR
              NCOK = NCO + K
C * EVALUATE DISCRIMINANT
              T1 = XSD(NCOK, 5)**2 - XSD(NCOK, 1) * XSD(NCOK, 2)
              IF (T1 > 0.0) THEN
                T1 = SQRT (T1)
C * SOLVE QUADRATIC EQUATION
                T2 =      XSD(NCOK, 1) - XSD(NCOK, 5)
                T3 = T2 + XSD(NCOK, 2) - XSD(NCOK, 5)
                IF (ABS (T3) > PAR(54)) THEN
                  T4 = (T2 - T1) / T3
                  T5 = (T2 + T1) / T3
C * VALID INTERSECTION IF T4 < 1 AND T5 > 0
                  IF (T4 < 1.0 .AND. T5 > 0.0) THEN
C * SAVE VALID CONIC INTERSECTIONS
                    MINT               = MINT + 1
                    XSD(NCO + MINT, 3) = T4
                    XSD(NCO + MINT, 4) = T5
                  END IF
                END IF
              END IF
            END DO
          END IF
C * FIND ENTRY AND EXIT POINTS FOR EACH QUADRANGLE
          IF (NQOVR > 0) THEN
            DO K = 1, NQOVR
              I12 = 1
              KCQ = NCO + NCOVR + K
C * CHECK FOR SINGLE INSIDE POINT
              SEG(1) = XSD(KCQ, 1)
              IF (SEG(1) >= 0.0) THEN
                SEG(1) = 1.0 - XSD(KCQ, 2)
                IF (SEG(1) <= 1.0) I12 = 0
              END IF
C * I12 = 1 : INSIDE POINT FOUND, ONLY ONE INTERSECTION POSSIBLE
C * FIND WHICH EDGES ARE CROSSED BY THE SEGMENT
              DO J = 1, 4
                T1 = CON(NCO + K, J)
                T2 = CON(NCO + K, J + 4)
                T3 = T1 - T2
                IF (T1 * T2 <= 0.0) THEN
C * CHECK FOR SEGMENT ON AN EDGE
                  IF (ABS (T3) <= PAR(54)) THEN
                    I12 = 0
                    EXIT
                  END IF
C * CALCULATE COORDINATES OF INTERSECTION
                  T4  = (T1 * YN(1) - T2 * YO(1)) / T3
                  T5  = (T1 * YN(2) - T2 * YO(2)) / T3
                  L   = 2 * (MOD (J, 4) + 1)
                  NIQ = NASUP + IDIR(K)
C * IS INTERSECTION WITHIN LIMITS OF QUADRANGLE
                  T6 = (T4 - CON(NIQ, 2 * J - 1)) *
     1                 (CON(NIQ, L - 1) - T4) +
     2                 (T5 - CON(NIQ, 2 * J)) * (CON(NIQ, L) - T5)
                  IF (T6 > -1.E-4) THEN
C * CALCULATE FRACTION PARAMETER AND STORE IT
                    T1 = T1 / T3
                    IF (I12 < 1) THEN
C * STORE FIRST INTERSECTION
                      I12    = 1
                      SEG(1) = T1
                    ELSE IF (I12 == 1) THEN
C * STORE SECOND INTERSECTION
                      I12 = 2
                      IF (T1 >= SEG(1)) THEN
                        SEG(2) = T1
                      ELSE
                        SEG(2) = SEG(1)
                        SEG(1) = T1
                      END IF
                    ELSE
C * MORE THAN TWO INTERSECTIONS (I.E., QUADRANGLE DIAGONAL)
                      IF (T1 < SEG(1)) THEN
                        SEG(1) = T1
                      ELSE IF (T1 > SEG(1)) THEN
                        IF (T1 > SEG(2)) SEG(2) = T1
                      END IF
                    END IF
                  END IF
                END IF
              END DO
              IF (I12 > 1) THEN
C * STORE FRACTION PARAMETERS
                MINT               = MINT + 1
                XSD(NCO + MINT, 3) = SEG(1)
                XSD(NCO + MINT, 4) = SEG(2)
              END IF
            END DO
          END IF
C * END OF ENTRY-AND-EXIT-POINT CALCULATIONS
          IF (MINT == 0) THEN
C * NO INTERFERENCE FOUND, DRAW ENTIRE SEGMENT
            CALL GGIP (YN(1), YN(2), ZGGIP, 2)
            GO TO 20
          ELSE
C * SHELL-SORT SEGMENT INTERSECTION LIST
            M  = MINT
            DO
              M = M / 2
              IF (M == 0) EXIT
              K = MINT - M
              J = 1
              DO
                I = J
                DO
                  IM = I + M
                  IF (XSD(NCO + I, 3) < 0.0) THEN
                    IF (XSD(NCO + IM, 3) > 0.0) EXIT
                    IF (XSD(NCO + I, 4) <= XSD(NCO + IM, 4)) EXIT
                  ELSE
                    IF (XSD(NCO + I, 3) <= XSD(NCO + IM, 3)) EXIT
                  END IF
C * SWAP
                  CALL GEN018 (XSD(NCO + I, 3), XSD(NCO + IM, 3))
                  CALL GEN018 (XSD(NCO + I, 4), XSD(NCO + IM, 4))
                  I = I - M
                  IF (I <= 0) EXIT
                END DO
                J = J + 1
                IF (J >  K) EXIT
              END DO
            END DO
          END IF
C * FIND STARTING POINT P0 AND END POINT P1
          P0 = 0.0
          K  = 0
          DO
            K  = K + 1
            IF (K > MINT) THEN
              P1 = 1.0
            ELSE
              P1 = XSD(NCO + K, 3)
              IF (P1 < 0.0 .OR. P1 <= P0) THEN
                P0 = MAX (P0, XSD(NCO + K, 4))
                IF (P0 < 1.0) CYCLE
                P0 = 1.0
              END IF
            END IF
C * DRAW SEGMENT FROM P0 TO P1
   10       IF (P0 > 0.0) THEN
              Z(1) = YO(1) * (1.0 - P0) + YN(1) * P0
              Z(2) = YO(2) * (1.0 - P0) + YN(2) * P0
              CALL GGIP (Z(1), Z(2), ZGGIP, 3)
              IF (P0 >= 1.0) GO TO 20
            END IF
            Z(1) = YO(1) * (1.0 - P1) + YN(1) * P1
            Z(2) = YO(2) * (1.0 - P1) + YN(2) * P1
            CALL GGIP (Z(1), Z(2), ZGGIP, 2)
            IF (P1 < 1.0) THEN
              P0 = MAX (P0, XSD(NCO + K, 4))
              IF (P0 < 1.0) CYCLE
              P0 = 1.0
              GO TO 10
            END IF
            IF (NEXIT == 0) EXIT
          END DO
        END IF
C * CHANGE MOVE/DRAW MODE FOR NEXT STEP DEPENDING ON NPEN-MODE
   20   IF (NPEN > 0) THEN
          LPEN = 2
        ELSE
          IF (LPEN == 3) THEN
            LPEN = 2
          ELSE
            LPEN = 3
          END IF
        END IF
      END DO
      RETURN
      END SUBROUTINE PLA106
 
      SUBROUTINE PLA109 (MODE, NTYP, X, Y)
C * PLOT SPECIAL TEXT (PLATON/PLUTON)
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE tpos
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: MODE
      INTEGER :: NTYP
      INTEGER :: ITEM
      INTEGER :: IASU
      REAL :: X
      REAL :: Y
      REAL :: XX
      REAL :: YY
      REAL :: XN
      REAL :: XMAX
      REAL :: YMAX
      I    = 0
      IASU = 0
      XMAX = 0.0
      YMAX = 0.0
C * NTYP = 0 - PLATON
C * NTYP = 1 - PLUTON
      IF (NTYP == 0) THEN
        XMAX = PAR(37)
        YMAX = PAR(38)
      ELSE IF (NTYP == 1) THEN
        XMAX = - PAR(61)
        YMAX = - PAR(62)
      END IF
C * MODE = 1 : NEW TEXT
   10 IF (MODE == 1) THEN
        IF (IWIN == 1) THEN
          I = IPR(447) + 1
          WRITE (SBCD, 99999) PAR(350), CHAR (0)
          CALL GEN038 (IGGT, 1, 80)
C * WHAT NEXT ?
          CALL PLA012 (0, 0)
          TKST(I) = IGGT(1:10)
          LINE    = IGGT
          CALL GEN038 (ICL,  1, 80)
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          CALL GEN125 (0, LU6, 'Give Text [ncharmax = 10] :')
          READ  (LU5, 99998) LINE
        END IF
        IF (LINE(1:1) == '!'    .OR. LINE(1:4) == 'TEXT' .OR.
     1      LINE(1:4) == 'PLOT' .OR. LINE(1:3) == 'END'  .OR.
     2      LINE(1:3) == 'REM'  .OR. LINE(1:4) == 'EXIT') THEN
          IPR(453)  = 0
          IPR(448)  = 0
          LINE      = '!'
          IF (NTYP == 1) THEN
            IGBL(6) = 3
          ELSE
            IGBL(6) = 8
          END IF
          RETURN
        END IF
C * STORE POSITION WITH REFERENCE TO CENTRE OF DRAWING
        IF (I == 1) THEN
          KMX = 1
          K   = KMX
        ELSE
          IF (KMX > 0) THEN
            DO J = 1, KMX
              IF (NTK(J) == 0) THEN
                K = J
                GO TO 20
              END IF
            END DO
          END IF
          KMX = KMX + 1
          K   = KMX
        END IF
   20   XTK(I, 1) = XMAX - 5.0
        XTK(I, 2) = YMAX - 1.0 - K
        NTK(K)    = 1
        XTK(I, 3) = PAR(350)
        IPR(447)  = I
        CALL PLA439 (0.0, TKST(I), 10, XTK(I, 3), -1, 1,
     1               XTK(I, 1), XTK(I, 2))
        GO TO 10
C * MODE = 2 : SPECIAL TEXT (RE-PLOT)
      ELSE IF (MODE == 2) THEN
        IF (IPR(173) * IPR(447) > 0) THEN
          DO I = 1, IPR(447)
            CALL PLA439 (0.0, TKST(I), 10, XTK(I, 3), 1, 1, XTK(I, 1),
     1                    XTK(I, 2))
          END DO
        END IF
C * MODE = 3 : DELETE TEXT
      ELSE IF (MODE == 3) THEN
        IASU = 0
        CALL PLA014 (3, NTYP, X, Y, ITEM, IASU)
        IF (ITEM /= 0) THEN
          CALL PLA439 (0.0, TKST(ITEM), 10, XTK(ITEM, 3), 0, 1,
     1                  XTK(ITEM, 1), XTK(ITEM, 2))
          CALL GGIP (0.0, 1.0, 0.0, 0)
          IF (IPR(447) > 1) THEN
            DO I = 1, 3
              XTK(ITEM, I) = XTK(IPR(447), I)
            END DO
            TKST(ITEM) = TKST(IPR(447))
          END IF
          IPR(447) = IPR(447) - 1
        END IF
C * MODE = 4 : CHANGE TEXT SIZE
      ELSE IF (MODE == 4) THEN
        CALL PLA014 (3, NTYP, X, Y, ITEM, IASU)
        IF (ITEM /= 0) THEN
          CALL PLA439 (0.0, TKST(ITEM), 10, XTK(ITEM, 3), 0, 1,
     1                 XTK(ITEM, 1), XTK(ITEM, 2))
          XTK(ITEM, 3) = PAR(350)
          CALL PLA439 (0.0, TKST(ITEM), 10, XTK(ITEM, 3), 1, 1,
     1                   XTK(ITEM, 1), XTK(ITEM, 2))
        END IF
C * MODE = 5 : MOVE TEXT ITEM
      ELSE IF (MODE == 5) THEN
        IF (IPR(448) /= 0) THEN
          IF (IPR(447) > 0) THEN
            IF (LMOD == 0) THEN
              CALL PLA014 (3, NTYP, X, Y, IMIN, IASU)
              XX = XTK(IMIN, 1)
              YY = XTK(IMIN, 2)
              LMOD = 1
              XN = - XTK(IMIN, 2) + YMAX
              N  =  NINT (-XTK(IMIN, 2) + YMAX)
              IF (ABS (XN - N) < 0.05) THEN
                NTK(N) = 0
              END IF
            ELSE
              XX = - (NTYP * XMAX) + X
              YY =   YMAX - Y
              XTK(IMIN, 1) =  XX
              XTK(IMIN, 2) =  YY
              LMOD = 0
            END IF
            YGGIP = FLOAT (1 - LMOD)
            CALL PLA439 (0.0, TKST(IMIN), 10, XTK(IMIN, 3),
     1                        NINT (YGGIP), 1, XX, YY)
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT ('Give Text[ncharmax = 10, size =', F5.2, ']', A)
99998 FORMAT (A)
      END SUBROUTINE PLA109
 
      SUBROUTINE PLA110 (HORS, VERT, MODE)
C * PLOT BOX
      USE parameters
      USE atomdata
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IP
      INTEGER :: IPRB
      INTEGER :: IDET
      INTEGER :: MODE
      INTEGER :: NJID
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      REAL :: VR
      REAL :: VRT
      REAL :: P14
      REAL :: HORS
      REAL :: VERT
      REAL :: TSHFT
C * MODE -1 : BOX/TITL ONLY
C * MODE  0 : BOX/TITL/ROT'S
C * MODE  1 : BOX/TITL/ROT'S/PROB
      IF (IGBL(103) /= 0) THEN
        CALL GGIP (0.0,  0.0,  0.0, 3)
        CALL GGIP (HORS, 0.0,  0.0, 2)
        CALL GGIP (HORS, VERT, 0.0, 2)
        CALL GGIP (0.0,  VERT, 0.0, 2)
        CALL GGIP (0.0,  0.0,  0.0, 2)
        P14 = 0.4
        IF (MODE >= 0) THEN
C * INCLUDE FILENAME
           CALL PLA439 (-90.0, FNLU1, 50, 0.35, 1, 1, HORS - 0.5,
     1       VERT - 1.5)
C * (NO)MOVE WARNING
          IF (IPR(116) == 0 .AND. IABS (IGBL(6)) /= 25) THEN
            IF (IGBL(30) == 1) THEN
              IF (IGBL(136) == 1) THEN
                CALL PLA439 (0.0, 'NOMOVE AND NO EXPAND FORCED', 27,
     1            P14, 3, 1, HORS - 45 * P14, VERT - 0.15 - P14)
              ELSE
                CALL PLA439 (0.0, 'NOMOVE FORCED', 13, P14, 3, 1,
     1            HORS - 31 * P14, VERT - 0.15 - P14)
              END IF
            ELSE
              IF (IGBL(60) > 0) THEN
                CALL PLA439 (0.0, 'INPUT ATOMS MOVED', 17, P14, 2, 1,
     1                       HORS - 35 * P14, VERT - 0.15 - P14)
              END IF
            END IF
          END IF
C * DISPLAY LITERATURE REFERENCE
          IF (MODE == 1 .AND. IGBL(104) == 1 .AND.
     1                          IPR(116) == 0) THEN
            VRT = VERT - 1.0
            DO I = 1, 2 + IPR(565)
              VRT = VRT - 0.4
              CALL PLA439 (0.0, LREF(I), 79, 0.25, 5, 1, 1.0, VRT)
            END DO
          END IF
C * PLOT ROTATION ANGLES XR, YR AND ZR AND DETERMINANT
          IROTX = NINT (RGBL(28))
          IROTY = NINT (RGBL(29))
          IROTZ = NINT (RGBL(30))
          IDET  = IGBL(87)
          IF (IDET == -1 .AND. IPR(116) == 0)
     1        CALL PLA439 (0.0, 'INVERT', 6, P14, 3, 1,
     2        HORS - 16 * P14, VERT - 0.15 - P14)
          CALL GEN040 (IROTX, NQ1, IP)
          NQ1(IP + 1:IP + 2) = ' X'
          IP                 = IP + 2
          CALL PLA439 (0.0, NQ1, IP, P14, -1, 1, HORS - IP * P14, 0.15)
          CALL GEN040 (IROTY, NQ2, IP)
          NQ2(IP + 1:IP + 2) = ' Y'
          IP                 = IP + 2
          CALL PLA439 (90.0, NQ2, IP, P14, -1, 1, P14 + 0.15, VERT
     1                  - IP * P14)
          NQ3(1:1) = 'Z'
          CALL PLA439 (0.0, NQ3, 1, P14, -1, 1, 0.15, 0.15)
          CALL GEN040 (IROTZ, NQ3, IP)
          CALL PLA439 (0.0, NQ3, IP, P14, -1, 1, 0.15 + 2 * P14, 0.15)
          IF (MODE == 1) THEN
C * PLOT PROBABILITY LEVEL IN RIGHT UPPER CORNER
            IPRB = IPR(45) * 10
            CALL GEN040 (IPRB, NQ1, IP)
            CALL PLA439 (0.0, 'Prob =  '//NQ1(1:IP)//'%', 9 + IP,
     1        P14, -1, 1, HORS - (8 + IP) * P14, VERT - 0.15 - P14)
C * PLOT TEMPERATURE
            IF (IABS (IGBL(8)) == 3 .AND. IPR(310) > 0) THEN
              CALL GEN040 (IPR(310), NQ1, IP)
              CALL PLA439 (0.0, 'Temp = '//NQ1(1:IP)//'K', 8 + IP, P14,
     1          -1, 1, HORS - (7 + IP) * P14, VERT - 0.25 - 2 * P14)
            END IF
          END IF
          IF (IABS(IGBL(6)) /= 25) THEN
            NQ1 = 'RES=   '
            CALL GEN040 (IPR(140), NQ1(6:7), IP)
            CALL PLA439 (0.0, NQ1, 7, P14, -1, 1, HORS - 11 * P14,
     1                   0.15)
          END IF
        END IF
C * PLOT TITL
        NJID = MAX (74, NINT (HORS / 0.4) - 12)
        IF (MODE == -1) THEN
          TSHFT = 1.0
        ELSE
          TSHFT = 3.0
        END IF
        CALL PLA439 (0.0,  JID, NJID, 0.4, -1, 1, TSHFT, 0.15)
        CALL GEN040 (IGBL(4), NQ2, IP)
        IF (MODE < 0) THEN
          VR = 0.5
        ELSE
          VR = 1.5
        END IF
        CALL pla439 (90.0, PROGNM//' - (VERSION='//NQ2(1:IP)//')',
     1               IP + 41, 0.35, -1, 1, 0.6,  VR)
      END IF
      RETURN
      END SUBROUTINE PLA110
 
      SUBROUTINE PLA111
C * ALL (NEWMAN AND RING/PLANE PLOTTING IS INITIATED FROM FROM HERE)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: L0
      INTEGER :: L4
      INTEGER :: NR
      INTEGER :: JM
      INTEGER :: IS
      INTEGER :: IP
      INTEGER :: II
      INTEGER :: NAT
      INTEGER :: NWM
      INTEGER :: NL4
      INTEGER :: NK0
      INTEGER :: ISH
      INTEGER :: IHAT
      INTEGER :: KHAT
      INTEGER :: IDET
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: MARK
      INTEGER :: IENR
      INTEGER :: IVAL
      INTEGER :: IVWP
      INTEGER :: IPHI
      INTEGER :: IPR12
      INTEGER :: IPHIP
      INTEGER :: NRING
      INTEGER :: NHEAD
      INTEGER :: IOPEN
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      INTEGER :: NWMNR
      REAL :: XR
      REAL :: YR
      REAL :: ZR
      REAL :: SX
      REAL :: SY
      REAL :: SZ
      REAL :: SC
      REAL :: SXY
      REAL :: XOS
      REAL :: YOS
      REAL :: XAG
      REAL :: ZR1
      REAL :: ZR2
      REAL :: XPL
      REAL :: YPL
      REAL :: XOR
      REAL :: YOR
      REAL :: XLB
      REAL :: YLB
      REAL :: YST
      REAL :: YRR
      REAL :: XR0
      REAL :: XR1
      REAL :: XR2
      REAL :: XR3
      REAL :: YR0
      REAL :: YR1
      REAL :: YR2
      REAL :: YR3
      REAL :: YAG
      REAL :: XST
      REAL :: PHI
      REAL :: YANK
      REAL :: XYR3
      REAL :: PMAX
      REAL :: PHIL
      REAL :: PHIB
      REAL :: RADSP
      REAL :: RADCP
      CHARACTER(len=4) :: TYPEX
      J1    = 0
      J2    = 0
      XOS   = 0.0
      YOS   = 0.0
      IENR  = 0
      NRING = 0
      NHEAD = 0
C * IPR(55) = -1 NEWMAN
C *         =  0
C *         =  1 : PLAN
C *         =  2 : RING
C *         =  3 : RESD
C *         =  4 : LSPL
      IGBL(6) = 13
   10 IOPEN   = 0
      NR      = 0
      NAT     = IPR(39)
   20 READ (LU8, IOSTAT = IOST) MARK, IPR(12), JR, RMAT
      IF (MARK == -100 .OR. IOST /= 0) THEN
C * NO MORE RESD, LSPL, RING, CRDN DATA
        CALL PLA015 (0, 18)
        CALL GEN108 (LU8, 0)
        IPR(169) = 0
        GO TO 70
      END IF
      NL4 = NAT
      IF (MARK == -1) NL4 = 240
      READ (LU8) (IATP(L4), L4 = 1, NL4)
      IF (MARK /= IPR(55)) THEN
        IF (IPR(55) == 1) THEN
          IF (MARK < 1 .OR. MARK > 4) GO TO 20
        ELSE
          GO TO 20
        END IF
      END IF
C * INITIALIZE GRAPHICS
   30 IF (IOPEN == 0) THEN
        HORS = 25.0
        VERT = 25.0
        CALL GGIP (HORS, VERT, 0.0, 1)
C * PLOT BOX
        CALL PLA110 (HORS, VERT, -1)
        IOPEN = 1
        IF (IPR(55) /= -1)
     1    CALL PLA439 (0.0, JID(75:80), 6, 0.45, 1, 2, 10.5, 24.25)
      END IF
C * PLAN, RING, RESD, LSPL
      IF (IPR(55) > 0) THEN
        CALL PLA112 (PMAX, SX, SY, SZ)
        IF (MARK == 1) THEN
          TYPEX = 'Plan'
        ELSE IF (MARK == 2) THEN
          TYPEX = 'Ring'
          NRING = NRING + 1
        ELSE IF (MARK == 3) THEN
          TYPEX = 'Resd'
        ELSE IF (MARK == 4) THEN
          TYPEX = 'Lspl'
        END IF
        CALL PLA439 (0.0, TYPEX, 4, 0.45, 1, 2, 23.0, 24.0)
        NR  = NR + 1
        SXY = VERT / 2.0
        SC  = SXY  * 0.8 / PMAX
C * PLOT ROTATION ANGLES (FOR PLUTON, ADP, STICK, SOLID, CPK)
        CALL GEN096 (RMAT, IROTX, IROTY, IROTZ, IDET, V6, YANK, QM)
        RGBL(28) = IROTX
        RGBL(29) = IROTY
        RGBL(30) = IROTZ
        IGBL(87) = IDET
        IGBL(67) = 1
        CALL GEN040 (IROTX, NQ1, IP)
        CALL GEN040 (IROTY, NQ2, IP)
        CALL GEN040 (IROTZ, NQ3, IP)
        CALL PLA439 (0.0, NQ1, 4, 0.4, 1, 2, 23.6, 0.15)
        CALL PLA439 (0.0, NQ2, 4, 0.4, 1, 2, 0.15, 24.5)
        CALL PLA439 (0.0, NQ3, 4, 0.4, 1, 2, 0.15, 0.15)
        CALL GEN040 (IPR(140), NQ1, IP)
        CALL PLA439 (0.0, NQ1, 2, 0.4, 1, 2, 22.5, 0.15)
        YRR   = 0.4
        IPR12 = IPR(12)
        IF (IPR12 <= 20) THEN
          DO I = 1, IPR12
            CALL PLA047 (LABA(IATP(I)), NQ1, IDUM, JDUM, IPR(71),
     1                   IGBL(55), 0, 0)
            YRR = YRR + 0.5
            YR  = YRR
            XR  = 1.0
            CALL PLA439 (0.0, NQ1, 5, 0.35, 1 + IPR(346), 2, XR, YR)
          END DO
        END IF
        IF (IPR(56) /= 0) THEN
C * PLOT LEAST-SQUARES PLANE
          CALL PLA044 (RMAT, -NR, XR, YR, ZR, SX, SY, SZ, SC, SXY)
          YR = YR + 0.05
          CALL GGIP (2.0,  YR, 0.0, 3)
          CALL GGIP (23.0, YR, 0.0, 2)
          YR = YR - 0.1
          CALL GGIP (23.0, YR, 0.0, 3)
          CALL GGIP (2.0,  YR, 0.0, 2)
          CALL GEN040 (NR, NQ1, IP)
          CALL PLA439 (0.0, NQ1, IP, 0.5, 1, 2, 23.0, 24.3)
        END IF
C * PLOT ATOMS & BONDS
        I = 0
        DO WHILE (I < NAT)
          I = I + 1
          IF (IATC(I) /= 0) THEN
C * ATOMS
            CALL GEN048 (-1, IFG(1, I), 7, IVAL)
            IF (IVAL <= 0) THEN
              CALL PLA044 (RMAT, I, XR, YR, ZR, SX, SY, SZ, SC, SXY)
              XR0      = XR
              YR0      = YR
              NQ1(1:1) = '.'
              DO II = 1, IPR12
                IF (I == IATP(II)) THEN
                  NK0 = 1 + IPR(346)
                  GO TO 40
                END IF
              END DO
              CALL GGIP (0.0, 1.0, 0.0, 0)
              NK0 = 1
   40         CALL PLA439 (0.0, NQ1, 1, 0.5, NK0, 2, XR0, YR0)
              CALL PLA047 (LABA(I), NQ1, IDUM, JDUM, IPR(71),
     1          IGBL(55), 0, 0)
              XR0 = XR + 0.4
              YR0 = YR + 0.4
              CALL PLA439 (0.0, NQ1, 6, 0.3, NK0, 2, XR0, YR0)
            END IF
C * BONDS
            CALL GGIP (0.0, -3.0, 0.0, 0)
            JM = - NINT (CON(I, 9))
            IF (JM < 0) JM = 9
            IF (JM > 0) THEN
              CALL GEN048 (-1, IFG(1, I), 7, IHAT)
              CALL PLA044 (RMAT, I, XR1, YR1, ZR1, SX, SY, SZ, SC, SXY)
              DO J = 1, JM
                K = NINT (CON(I, J))
                IF (I < K) THEN
                  IF (IATC(K) /= 0) THEN
                    CALL GEN048 (-1, IFG(1, K), 7, KHAT)
                    IF (IHAT + KHAT > 0) THEN
                      IF (IPR(346) > 0) CALL GGIP (0.0, 4.0, 0.0, 0)
                    ELSE
                      DO II = 1, IPR12
                        IF (I == IATP(II) .OR. K == IATP(II)) THEN
                          IF (IPR(346) > 0) CALL GGIP (0.0, 2.0,
     1                      0.0, 0)
                          GO TO 50
                        END IF
                      END DO
                      IF (IPR(346) > 0) CALL GGIP (0.0, 3.0, 0.0, 0)
                    END IF
   50               CALL PLA044 (RMAT, K, XR2, YR2, ZR2, SX, SY, SZ, SC,
     1                           SXY)
                    XR3   = XR2 - XR1
                    YR3   = YR2 - YR1
                    XYR3  = SQRT (XR3**2 + YR3**2 + PAR(12))
                    XR3   = 0.4 * XR3 / XYR3
                    YR3   = 0.4 * YR3 / XYR3
                    XR1   = XR1 + XR3
                    YR1   = YR1 + YR3
                    ZGGIP = 0.0
                    CALL GGIP (XR1, YR1, ZGGIP, 3)
                    XR1 = XR1 - XR3
                    YR1 = YR1 - YR3
                    XR2 = XR2 - XR3
                    YR2 = YR2 - YR3
                    CALL GGIP (XR2, YR2, ZGGIP, 2)
                  END IF
                END IF
              END DO
            END IF
          END IF
        END DO
C * NEWMAN PLOT
      ELSE IF (IPR(55) == -1) THEN
        IPR(169) = IPR(169) + 1
C * PLOT REQUESTED NEWMAN PLOT ONLY CASE
        IF (IPR(162) > 0) THEN
          J1 = IPR(162) / (NP1 + 1)
          J2 = MOD (IPR(162), NP1 + 1)
        END IF
        IF (IOPEN == 1) THEN
C * PLOT DIVISION
C * HORIZONTAL
          CALL GGIP (0.0,   VERT, 0.0, 3)
          CALL GGIP (HORS,  VERT, 0.0, 2)
          CALL GGIP (0.0,   0.0,  0.0, 3)
          CALL GGIP (HORS,  0.0,  0.0, 2)
          XGGIP = IGBL(103)
          YGGIP = VERT / 2.0
          CALL GGIP (XGGIP, YGGIP, 0.0, 3)
          CALL GGIP (HORS,  YGGIP, 0.0, 2)
          YGGIP = VERT - 1.0
          CALL GGIP (XGGIP, YGGIP, 0.0, 3)
          CALL GGIP (HORS,  YGGIP, 0.0, 2)
          YGGIP = VERT / 2.0 - 1.0
          CALL GGIP (XGGIP, YGGIP, 0.0, 3)
          CALL GGIP (HORS,  YGGIP, 0.0, 2)
          YGGIP = IGBL(103)
          CALL GGIP (XGGIP, YGGIP, 0.0, 3)
          CALL GGIP (HORS,  YGGIP, 0.0, 2)
C * VERTICAL
          XGGIP = HORS / 2.0
          YGGIP = IGBL(103)
          CALL GGIP (XGGIP, YGGIP,  0.0, 3)
          CALL GGIP (XGGIP, VERT,   0.0, 2)
          XGGIP = IGBL(103)
          CALL GGIP (XGGIP, YGGIP,  0.0, 3)
          CALL GGIP (XGGIP, VERT,   0.0, 2)
          XGGIP = HORS / 2.0 + IGBL(103)
          CALL GGIP (XGGIP, YGGIP,  0.0, 3)
          CALL GGIP (XGGIP, VERT,   0.0, 2)
          CALL GGIP (HORS,  YGGIP,  0.0, 3)
          CALL GGIP (HORS,  VERT,   0.0, 2)
          IOPEN = 2
        END IF
        IVWP = 0
        DO
          IVWP = IVWP + 1
          IF (IVWP > IPR(12)) THEN
            IF (IPR(162) > 0) THEN
              GO TO 20
            ELSE
              GO TO 60
            END IF
          END IF
          ISH = (IVWP - 1) * 60
          J   = IATP(2 + ISH)
          K   = IATP(3 + ISH)
C * CHECK FOR DESIRED NEWMAN PLOT (WHEN SPECIFIED)
          IF (IPR(162) > 0) THEN
            IF ((J1 /= J .OR. J2 /= K) .AND.
     1          (J1 /= K .OR. J2 /= J)) THEN
              CYCLE
            ELSE
              IPR(162) = 0
              IVWP     = 0
              CYCLE
            END IF
          END IF
          CALL PLA047 (LABA(J), NQ1, IDUM, JDUM, 0, IGBL(55),
     1      0, 0)
          CALL PLA047 (LABA(K), NQ2, IDUM, JDUM, 0, IGBL(55),
     1      0, 0)
          IF (IVWP == 1) THEN
            XOR = HORS / 4.0
            YOR = 3.0 * VERT / 4.0
            XOS = XOR
            YOS = YOR
          ELSE IF (IVWP == 2) THEN
            XOR = HORS / 2.0
            YOR = 0.0
            XOS = XOS + XOR
          ELSE IF (IVWP == 3) THEN
            XOR = - HORS / 2.0
            YOR = - VERT / 2.0
            XOS = XOS + XOR
            YOS = YOS + YOR
          ELSE IF (IVWP == 4) THEN
            XOR = HORS / 2.0
            YOR = 0.0
            XOS = XOS + XOR
          END IF
C * RESET ORIGIN
          CALL GGIP (XOR, YOR, 0.0, -3)
C * PLOT CURRENT CENTRAL BOND
          XR = -2.5
          YR =  5.5
          NK0 = 1
          IF (IPR(346) == 1) NK0 = 5
          CALL PLA439 (0.0, NQ1//'-'//NQ2, 15, 0.5, NK0, 2, XR, YR)
C * PLOT SERIAL NUMBER OF NEWMAN-PLOT
          NWMNR = (IPR(169) - 1) * 4 + IVWP
          CALL GEN040 (NWMNR, NQ1, IP)
          XR = 5.9 - (IP * 0.4 * 6.0) / 7.0
          CALL PLA439 (0.0, NQ1, IP, 0.4, 1, 2, XR, YR)
C * PLOT CIRCLE
          CALL PLA289 (0.0, 0.0, 1.0, 24)
C * PLOT BRANCHES/ANGLES & LABELS
          NWM   = IATP(1 + ISH)
          IPHIP = 90
          DO I = 1, NWM
            PHI   = IATP(20 + ISH + I) / (RGBL(6) * 100.0)
            PHIL  = IATP(38 + ISH + I) / (RGBL(6) * 100.0)
            IPHI  = NINT ((IATP(21 + ISH + I) - IATP(20 + ISH + I))
     1            / 100.0)
            CALL GEN040 (IPHI, NQ1, IP)
            PHIB  = PHI + IPHI / (RGBL(6) * 2)
            RADCP = PAR(24) * COS (PHI)
            RADSP = PAR(24) * SIN (PHI)
            XPL   = RADCP * 3
            YPL   = RADSP * 3
            XLB   = PAR(24) * COS (PHIL) * 4
            YLB   = PAR(24) * SIN (PHIL) * 4
C * DETERMINE POSITION FOR ANGLE
            XAG   = PAR(24) * COS (PHIB) * 2
            YAG   = PAR(24) * SIN (PHIB) * 2
            IF (IP <= 1) THEN
              XAG   = XAG * 1.75
              YAG   = YAG * 1.75
            ELSE
              IF (IPHI <= 40) THEN
                XAG  = XAG * 1.4
                YAG  = YAG * 1.4
              END IF
            END IF
            XAG   = XAG - IP * PAR(25) / 2
            YAG   = YAG - PAR(25) / 2
            IF (IATP(I + 3 + ISH) <= NP1) THEN
              XST = RADCP
              YST = RADSP
            ELSE
              XST = 0.0
              YST = 0.0
            END IF
            L = MOD (IATP(I + 3 + ISH), NP1)
            CALL PLA047 (LABA(L), NQ3, IDUM, IENR, 0, IGBL(55),
     1        0, 0)
            DO L0 = 1, 5
              IF (NQ3(6-L0:6-L0) /= ' ') EXIT
            END DO
            L0 = 6 - L0
            IF (COS (PHIL) < 0) THEN
              XLB = XLB + L0 * PAR(25) * COS (PHIL) * 5.0 / 6.0
              IF (IGBL(103) == 1) XLB = MAX (XLB, -5.0)
              IF (IPHIP < 25) THEN
                YLB = YLB - PAR(25) - 0.05
              END IF
            ELSE
              IF (IPHIP < 25) THEN
                YLB = YLB + PAR(25) + 0.05
              END IF
            END IF
            CALL GGIP (XST, YST, 0.0, 3)
            CALL GGIP (XPL, YPL, 0.0, 2)
            NK0 = 1
            IF (IPR(346) == 1 .AND. IENR /= 1) NK0 = 2
            CALL PLA439 (0.0, NQ3, L0, PAR(25), NK0, 2, XLB, YLB)
            IF (IPR(346) == 1) NK0 = 3
            CALL PLA439 (0.0, NQ1, IP, 0.5, NK0, 2, XAG, YAG)
            IPHIP = IPHI
          END DO
        END DO
      END IF
C * TERMINATE THIS PLOT
   60 CALL GGIP (0.0, 1.0, 0.0, 0)
      CALL GGIP (0.0, 0.0, 0.0, 3)
C * RESET ORIGIN
   70 CALL GGIP (-XOS, - YOS, 0.0, -3)
C * WHAT NEXT ?
      CALL PLA012 (1, 1)
      IF (IGBL(5) == LU5) THEN
C * CHECK FOR INPUT FROM GGIP
        CALL GEN020 (1, IGGT, 1, 80)
        IF (IGGT(1:1) == ' ') WRITE (LU6, 99999, IOSTAT = IOST)
        IF (IGGT(1:1) == '!' .OR. IGGT(1:1) == 'Y') GO TO 10
C * TEST FOR CREMER & POPLE RING ANALYSIS
        IF (IGGT(1:5) == 'CANDP') THEN
          IF (IPR(55) == 2 .AND. IPR(12) > 0 .AND. IPR(12) <= 8)
     1      CALL PLA095 (NRING, NHEAD, 1)
          GO TO 10
        END IF
        CALL PLA006 (0, IS)
C * REFRESH
        IF (IFL(1)(1:3) == 'REF') THEN
          IOPEN    = 0
          IPR(169) = IPR(169) - 1
          GO TO 30
        ELSE
          IPR(201) = 0
          CALL PLA280 (ICL)
C * RESET TO MAIN PLATON MENU
          IGBL(6) = 10
        END IF
      ELSE
        GO TO 10
      END IF
      IPR(1) = 5
C * RESET
      CALL PLA286 (0)
      RETURN
99999 FORMAT (':: Type Y(es) to continue this plot sequence, ',
     1 ' or another instruction', /)
      END SUBROUTINE PLA111
 
      SUBROUTINE PLA112 (PMAX, SX, SY, SZ)
C * SUPPORT PLA111
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: NAT
      INTEGER :: IRESI
      REAL :: PMAX
      REAL :: SX
      REAL :: SY
      REAL :: SZ
      REAL :: TEMP
      REAL :: XLNG
      IF (IPR(56) /= 0) THEN
        DO I = 1, 3
          TEMP       = RMAT(1, I)
          RMAT(1, I) = RMAT(2, I)
          RMAT(2, I) = RMAT(3, I)
          RMAT(3, I) = TEMP
        END DO
      END IF
      NAT = IPR(39)
C * CALCULATE SCALING, POSITIONING AND MINIMUM OVERLAP ORIENTATION
      DO I = 1, 3
        PAR(54 + I) = 1.0E10
        PAR(57 + I) =-1.0E10
      END DO
      DO I = 1, NAT
        IATC(I) = 1
        IF (IPR(140) > 0) THEN
          CALL GEN048 (-6, IFG(1, I), 9, IRESI)
          IF (IRESI /= IPR(140)) THEN
            IATC(I) = 0
            CYCLE
          END IF
        END IF
        DO K = 1, 3
          V5(K) = XXO(I, K + 3)
        END DO
        CALL GEN002 (1, RMAT, V5, V6, XLNG)
        DO K = 1, 3
          PAR(57 + K) = MAX (PAR(57 + K), V6(K))
          PAR(54 + K) = MIN (PAR(54 + K), V6(K))
        END DO
      END DO
      SX   = (PAR(55) + PAR(58)) * 0.5
      SY   = (PAR(56) + PAR(59)) * 0.5
      SZ   = (PAR(57) + PAR(60)) * 0.5
      PMAX = MAX (PAR(58) - SX, PAR(59) - SY)
      IF (ABS (PMAX) < 0.0001) PMAX = 1.0
      RETURN
      END SUBROUTINE PLA112
 
      MODULE simp
      SAVE
      INTEGER :: NP
      INTEGER :: IFN
      INTEGER :: NREFL
      REAL :: D
      REAL :: VM
      REAL :: SCL
      REAL :: FIN
      REAL :: AMX
      REAL :: HWHM
      REAL :: STHKMAX
      END MODULE simp
 
      SUBROUTINE PLA113
C * GENERATION OF SIMULATED POWDER PATTERNS FROM HKL OR COORDINATE DATA
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE spgrdata
      USE simp
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IP
      INTEGER :: IR
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: NREFS
      REAL :: A
      REAL :: AL
      REAL :: TH
      REAL :: THM
      REAL :: TTH
      REAL :: AMN
      REAL :: FACT
      REAL :: STHK
      REAL :: GEN095
C * IPR(511) = 0 - SIMPOW from coordinates
C *            1 - SIMPOW from I(obs)
C *            2 - SIMPOW from I(calc)
C * CHECK FOR FRACTIONAL COORDINATES
      IF (IPR(23) == 0) THEN
C * SET RETURN MODE IN MAIN MENU
        IGBL(1)  = 2
C * SET MENU #
        IGBL(6)  = 21
C * NO .HKP FILE
        IGBL(17) = 0
C * SET SIMPOWDER DEFAULT
        IPR(511) = 0
C * SIMPOWDER PLOT BASED ON IOBS FROM HKL OBS DATA
        IF (IPR(220) == 2) THEN
          IPR(220) = 1
C * ASYM AVF 1
          IPR(393) = 1
C * EXPAND HKL
          IPR(408) = -1
C * OBS OR CALC
          IF (IFL(2)(2:4) == 'OBS') THEN
            IPR(511) = 1
C * SIMPOWDER PLOT BASED ON IOBS FROM HKL CALC DATA
          ELSE IF (IFL(2)(2:5) == 'CALC') THEN
C * SHELXL HKLF 4 ONLY
            IF (IGBL(9) == 1) THEN
              IPR(511) = 2
            ELSE
              RETURN
            END IF
          END IF
        END IF
C * HANDLE .cpi file output (powder icalc Q option)
        IF (IGBL(25) == 0 .AND. IGBL(3) == 31) IPR(650) = 1
        IWIN = IGBL(25) * IGBL(32)
        IF (IWIN == 0) THEN
          MEDIUM      = 1
          IGGT(16:22) = 'OFF    '
          CALL GGIP (-999.0, 0.0, 0.0, 6)
        END IF
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
        IF (IPR(30) == 0) THEN
C * SET TWO-THETA-MAX
          IPR(500) = NINT (FN(1))
          IF (IPR(511) == 0 .AND. IGBL(143) /= 0) THEN
            PAR(17) = STWL(IGBL(143))
          END IF
C * CHECK FOR HKL CALC DATA FROM COORDINATES
   10     IF (IPR(511) == 0) THEN
C * CHECK WAVELENGTH
            CALL PLA293 (PAR(17))
C * CHECK FOR NON-ZERO # OF ATOMS
            IF (IPR(37) == 0) RETURN
C * EXPAND COORDINATE DATA TO TRICLINIC
            CALL PLA287 (1, 1, 0)
          ELSE
C * EXPAND REFLECTION DATA IN IOBS/ICAL MODE (FROM FCF)
C * RUN ASYM
            CALL PLA145 (0)
          END IF
C * SET DEFAULT POWDER 2-THETA-MAX VALUES FOR DISPLAY
   20     IF (IPR(500) <= 0 .OR. IPR(500) > 6) THEN
            IF (IPR(493) < 8) THEN
              IF (PAR(17) > 1.0) THEN
                IPR(500) = 2
                PAR(371) = 0.1
              ELSE
                IPR(500) = 1
                PAR(371) = 1
              END IF
C * ELECTRON
            ELSE  IF (IPR(493) == 8) THEN
C * LINE WIDTH
              PAR(371) = 1.0
C * STEPSIZE
              PAR(411) = 0.00075
C * THETA MAX RANGE
              IPR(500) = 1
            END IF
          END IF
C * SIMULATE POWDER DIFFRACTION PLOTS
C * GET REFLECTION DATA
          NREFL = 0
          AMX   = 0.0
          IF (IPR(511) == 0) THEN
C * SIMPOWDER PLOT WITH HKL DATA FROM COORDINATES
C * CHECK FOR COMMAND LINE TWOTHETA-MAX OPTION OVERRULE
            IF (RGBL(23) > 0.0 .AND. PAR(17) > 0.0) THEN
              PAR(287) = SIN (RGBL(23) / (2.0 * RGBL(6))) / PAR(17)
            END IF
            STHKMAX = PAR(287)**2
C * GENERATE REFLECTIONS IN HEMISPHERE + CALCULATED STRUCTURE FACTORS
            CALL PLA114
C * HKL2POWDER - ICAL OR IOBS
          ELSE IF (IPR(511) > 0) THEN
C * READ AND STORE ICAL/IOBS REFLECTIONS 'AS I(OBS)'
            STHKMAX = PAR(287)**2
            CALL GEN108 (LU17, 0)
            DO
              READ (LU17, 99996, IOSTAT = IOST) IH, IK, IL, A
              IF (IOST == -1) EXIT
              IF (IH == 0 .AND. IK == 0 .AND. IL == 0) EXIT
              STHK = GEN095 (PAR(191), IH, IK, IL)
              IF (STHK <= STHKMAX) THEN
                TH = ASIN (SQRT (STHK) * PAR(17))
C * LP 'CORRECTION' TO BE APPLIED BACKWARDS
                A  = A * (1.0 + COS(2 * TH) ** 2) /
     1               (SIN (TH) **2 * COS (TH))
                NREFL = NREFL + 1
                VOID(NP73 + NREFL * 5 - 4) = IH
                VOID(NP73 + NREFL * 5 - 3) = IK
                VOID(NP73 + NREFL * 5 - 2) = IL
                VOID(NP73 + NREFL * 5 - 1) = TH
                VOID(NP73 + NREFL * 5)     = A
                AMX                        = MAX (AMX, A)
              END IF
            END DO
          END IF
C * GENERATE PROFILE
   30     AMN = AMX / 2500.0
          IF (RGBL(23) == 0.0) THEN
C * CHECK FOR ELECTRON DIFFRACTION
            IF (IPR(493) == 8) THEN
              FIN = 0.50 + 0.25 * IPR(500)
            ELSE
              FIN = 20.0 * IPR(500)
            END IF
          ELSE
            FIN      = RGBL(23)
            IPR(500) = 6
          END IF
C * GET NUMBER OF STEPS
          IFN = NINT (FIN / PAR(411))
          CALL GEN074 (VOID, 1, IFN, 0.0)
          AL  = PAR(371)
          SCL = PAR(372)
          NP  = 0
          HWHM = 0.01
          DO N = 1, NREFL
            TH = VOID(NP73 + N * 5 - 1)
            A  = VOID(NP73 + N * 5)
            IP = NINT (2.0 * TH * RGBL(6) / PAR(411))
            IF (IP <= IFN) THEN
              VOID(IP) = VOID(IP) + A
              NP   = NP + 1
              I    = 0
              FACT = A
 
              DO WHILE (FACT > AMN)
                I  = I + 1
                FACT = A / (1 + AL * I * I)
                IF (IP + I <= IFN) VOID(IP + I) = VOID(IP + I) + FACT
                IF ((IP - I) > 0)  VOID(IP - I) = VOID(IP - I) + FACT
              END DO
            END IF
          END DO
          VM = 0.0
          DO I = 1, IFN
            VM = MAX (VOID(I), VM)
          END DO
          VM = VM / (VERT - 4.0)
C * PLOT SIMULATED POWDER PATTERN
   40     CALL PLA115
C * CHECK FOR 'WHAT NEXT ?'
          DO
            IGBL(6) = 21
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
            CALL GEN072 (IGGT, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7,
     1         NP17)
            IF (IFL(1)(1:4) == 'EXIT') THEN
              RETURN
            ELSE IF (IFL(1)(1:3) == 'END') THEN
              RETURN
C * CHANGE WAVELENGTH
            ELSE IF (IFL(1)(1:4) == 'RADN') THEN
              CALL PLA293 (FN(1))
              IPR(549) = 0
              GO TO 20
C * LIST REFLECTIONS SORTED ON 2TH VALUE
            ELSE IF (IFL(1)(1:4) == 'LIST') THEN
              OPEN (UNIT = LU61, FILE = NAMEFIL(1:KNMFIL)//'.pow',
     1        STATUS = 'UNKNOWN')
              IF (KN /= 0) THEN
                THM = FN(1) / 2.0
              ELSE
                THM = FIN / 2.0
              END IF
              NREFS = 0
              DO I = 1, NREFL
                TH = VOID(NP73 + I * 5 - 1) * RGBL(6)
                IF (TH < THM) THEN
                  NREFS          = NREFS + 1
                  JNSC(1, NREFS) = NINT (TH * 1000.0)
                  JNSC(2, NREFS) = I
                END IF
              END DO
              CALL PLA015 (0, 39)
C * SORT/LIST ON 2-THETA
              CALL GEN037 (JNSC, 1, NREFS)
              CALL PLA262 (0)
              WRITE (LU61, 99999, IOSTAT = IOST)
              CALL PLA262(5)
              DO I = 1, NREFS
                TTH = 0.002 * JNSC(1, I)
                J   = JNSC(2, I)
                IH  = NINT (VOID(NP73 + J * 5 - 4))
                IK  = NINT (VOID(NP73 + J * 5 - 3))
                IL  = NINT (VOID(NP73 + J * 5 - 2))
                IR  = NINT (10000000 * VOID(NP73 + J * 5) / AMX)
                CALL PLA262 (1)
                D = PAR(17) / (2.0 * SIN (TTH / (2.0 * RGBL(6))))
                WRITE (LU61, 99997, IOSTAT = IOST) IH, IK, IL, TTH, IR,
     1            D
              END DO
              CLOSE (UNIT = LU61, IOSTAT = IOST)
              WRITE (LU6, 99998) NAMEFIL(1:KNMFIL)//'.pow'
              CYCLE
            END IF
            SELECT CASE (LRET)
              CASE (-1)
                CYCLE
C * REFRESH DISPLAY
              CASE (1)
                GO TO 40
C * EXIT
              CASE (2)
               GO TO 50
C * REGENERATE PROFILE
              CASE (3)
                IF (IPR(799) == 1) WRITE (LU6, 99994)
     1            NAMEFIL(1:KNMFIL)//'.xy'
                IF (IPR(650) == 1) WRITE (LU6, 99995)
     1            NAMEFIL(1:KNMFIL)//'.cpi'
                GO TO 30
C * NEW 2-THETA-MAX RESTART
              CASE (4)
                GO TO 20
C * RESTART WITH CURRENT FCF IOBS/ICAL SETTING
              CASE (5)
                GO TO 10
            END SELECT
          END DO
        END IF
      END IF
C * CLOSE name.ckf
   50 CLOSE (UNIT = LU13, STATUS = 'DELETE', IOSTAT = IOST)
      CLOSE (UNIT = LU2 , STATUS = 'DELETE', IOSTAT = IOST)
      RETURN
99999 FORMAT ('2-Theta Sorted Reflection Listing', /, 80('='), //, 4X,
     1        'H    K    L 2-Theta', 6X, 'Intensity',5X, 'd Ang',
     1        /, 80('='))
99998 FORMAT (/, ':: Powder data written to ', A, /)
99997 FORMAT (3I5, F8.2, I15, F10.3)
99996 FORMAT (3I4, F8.0)
99995 FORMAT (/, ':: SIETRONICS File Written to:  ', A, /)
99994 FORMAT (/, ':: XY File Written: ', A, /)
      END SUBROUTINE PLA113
 
      SUBROUTINE PLA114
C * GENERATE REFLECTIONS IN HEMISPHERE + CALCULATED STRUCTURE FACTORS
      USE files
      USE parameters
      USE cchar
      USE simp
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHMAX
      INTEGER :: IKMAX
      INTEGER :: ILMAX
      REAL :: TH
      REAL :: CALC
      REAL :: STHK
      REAL :: ACAL   = 0.0
      REAL :: BCAL   = 0.0
      REAL :: ACALA  = 0.0
      REAL :: BCALA  = 0.0
      REAL :: SNTHA  = 0.0
      REAL :: ACALAF = 0.0
      REAL :: BCALAF = 0.0
      REAL :: GEN095
      IHMAX = INT (2 * PAR(101) * PAR(287)) + 1
      IKMAX = INT (2 * PAR(102) * PAR(287)) + 1
      ILMAX = INT (2 * PAR(103) * PAR(287)) + 1
      IL = - 1
      DO WHILE (IL < ILMAX)
        IL = IL + 1
        IF (IL > 0) THEN
          IK = - IKMAX - 1
        ELSE
          IK = -1
        END IF
        DO WHILE (IK < IKMAX)
          IK = IK + 1
          IF (IL == 0 .AND. IK == 0) THEN
            IH = 0
          ELSE
            IH = - IHMAX - 1
          END IF
          DO WHILE (IH < IHMAX)
            IH = IH + 1
            IF (IH /= 0 .OR. IK /= 0 .OR. IL /= 0) THEN
              SGX(1) = IH
              SGX(2) = IK
              SGX(3) = IL
C * ELIMINATE LATTICE CENTERING AND SYSTEMATIC ABSENCES
              SGX(12) = 0.0
              CALL SGSM (27, LINE, SGX, 0, 0, IERR)
              IF (NINT (SGX(12)) == 0) THEN
                STHK = GEN095 (PAR(191), IH, IK, IL)
                IF (STHK < STHKMAX + 0.00001) THEN
C * CALCULATE STRUCTURE FACTOR (EXCL f' & f'' CONTRIBUTION)
                  CALL PLA137 (IH, IK, IL, ACAL, BCAL, ACALA, BCALA,
     1              ACALAF, BCALAF, SNTHA)
                  CALC = ACAL ** 2 + BCAL ** 2
                  IF (SNTHA < 1.0) THEN
                    TH = ASIN (SNTHA)
C * LP 'CORRECTION' TO BE APPLIED BACKWARDS
                    CALC = CALC * (1.0 + COS (2 * TH) ** 2) /
     1                 (SIN (TH) **2 * COS (TH))
                    NREFL = NREFL + 1
                    VOID(NP73 + NREFL * 5 - 4) = IH
                    VOID(NP73 + NREFL * 5 - 3) = IK
                    VOID(NP73 + NREFL * 5 - 2) = IL
                    VOID(NP73 + NREFL * 5 - 1) = TH
                    VOID(NP73 + NREFL * 5)     = CALC
                    AMX                        = MAX (AMX, CALC)
                  END IF
                END IF
              END IF
            END IF
          END DO
        END DO
      END DO
      RETURN
      END SUBROUTINE PLA114
 
      SUBROUTINE PLA115
C * PLOT SIMPOWDER
      USE files
      USE parameters
      USE cchar
      USE cggt
      USE simp
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: M
      INTEGER :: IS
      INTEGER :: IP
      INTEGER :: NB
      INTEGER :: NE
      REAL :: Q
      REAL :: XP
      REAL :: YP
      REAL :: XM
      REAL :: XST
      REAL :: XPP
      REAL :: YPP
      REAL :: XSTEP
      REAL :: THETA
      REAL :: SCALE
C * OPEN WINDOW + HEADER
      CALL GGIP (HORS, VERT, 0.0, 1)
      BCD(1:25) = 'Simulated Powder Pattern'//CHAR (0)
      CALL PLA439 (0.0, BCD, 25, 1.2, 4, 8, 0.6, VERT - 1.8)
      CALL PLA439 (0.0, BCD, 25, 1.2, 2, 8, 0.5, VERT - 1.9)
      VRT = VERT - 2.5
C * DATA SOURCE (REFL OR COORD)
      CALL PLA439 (0.0, 'Xtal Data:'//FNLU1,  KNMXT + 10, 0.20,
     1  1, 1, 0.2, VRT)
      IF (IPR(511) /= 0) THEN
        VRT = VRT - 0.4
        CALL PLA439 (0.0, 'Refl Data:'//FNLU16,
     1  KNM16 + 10, 0.20, 1, 1, 0.2, VRT)
      END IF
      IF (IPR(511) == 0) THEN
        LINE(1:11) = 'Coord, Calc'
      ELSE IF (IPR(511) == 1) THEN
        LINE(1:11) = 'hkl, Obs'
      ELSE IF (IPR(511) == 2) THEN
        LINE(1:11) = 'hkl, Calc'
      END IF
      VRT = VRT - 0.4
      CALL PLA439 (0.0, 'PlotType:'//LINE(1:11), 20, 0.20, 1, 1, 0.2,
     1  VRT)
      IF (IPR(511) > 0) THEN
C * SUMFORMULA
        N = INDEX (RLWS(5), '''') - 1
        IF (N > 0) THEN
          CALL PLA439 (0.0, 'SumFormula '//RLWS(5), N + 11, 0.30,
     1      5 + IGBL(68), 2, 10.0, VRT)
        END IF
      ELSE
C * SumFormula
        CALL PLA283 (2, FLOAT (IPR(260)), N, CFORM)
        M = NP52 - N + 1
        CALL PLA439 (0.0, CFORM(N:NP52), M, 0.30,
     1    5 + IGBL(68), 2, 10.0, VRT)
      END IF
      IF (IPR(493) < 7) THEN
        LINE = '   X-Ray'
      ELSE IF (IPR(493) == 7) THEN
        LINE = ' Neutron'
      ELSE IF (IPR(493) == 8) THEN
        LINE = 'Electron'
      ElSE
        LINE = '        '
      END IF
      CALL PLA439 (0.0, LINE, 8, 0.35, 1, 1, HORS - 7.55, VRT)
      WRITE (LINE, 99989, IOSTAT = IOST) PAR(17)
      CALL PLA439 (0.0, LINE, 17, 0.35, 1, 1, HORS - 5.0, VRT)
      VRT = VRT - 0.7
      IF (IPR(261) > 0) THEN
        WRITE (LINE, 99987, IOSTAT = IOST) IPR(261)
        CALL PLA439 (0.0, LINE, 15, 0.35, 1, 1, HORS - 5.0, VRT)
        VRT = VRT - 0.7
      END IF
      WRITE (LINE, 99990, IOSTAT = IOST) SPGRNM(1)(1:7)
      CALL PLA439 (0.0, LINE, 20, 0.35, 1, 1, HORS - 6.0, VRT)
C * DISPLAY DIRECT CELL
      WRITE (LINE, 99986, IOSTAT = IOST) 'a    ', PAR(101)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
      WRITE (LINE, 99986, IOSTAT = IOST) 'b    ', PAR(102)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
      WRITE (LINE, 99986, IOSTAT = IOST) 'c    ', PAR(103)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
      WRITE (LINE, 99986, IOSTAT = IOST) 'alpha', PAR(104)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
      WRITE (LINE, 99986, IOSTAT = IOST) 'beta ', PAR(105)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
      WRITE (LINE, 99986, IOSTAT = IOST) 'gamma', PAR(106)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 14, 0.35, 1, 1, HORS - 4.0, VRT)
      WRITE (LINE, 99993, IOSTAT = IOST) 'V  ',   PAR(98)
      VRT = VRT - 0.7
      CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
      IF (IPR(511) * IPR(386) /= 0) THEN
        WRITE (LINE, 99991, IOSTAT = IOST) IPR(386)
        CALL PLA439 (90.0, LINE, 35, 0.45, 2, 2, 2.50, 2.20)
      END IF
      IF (IPR(511) == 0) THEN
        LINE(1:10) = 'SimPowderP'
      ELSE
        LINE(1:10) = 'hkl2Powder'
      END IF
      CALL PLA439 (90.0, LINE, 10, 0.5, 1, 2, 1.65, VERT - 12.0)
C * PLOT BOX
      CALL PLA110 (HORS, VERT, -1)
      IF (IPR(55) /= -1) CALL PLA439
     1  (0.0, JID(75:80), 6, 0.45, 1, 2, 10.5, 24.25)
      CALL GGIP (0.0, 0.0, 0.0, 6)
      XSTEP = (HORS - 2.0) / IFN
      IF (NP > 0) THEN
C * OPEN SIETRONICS STYLE PATTERN OUTPUT
        IF (IPR(650) == 1) THEN
          OPEN (UNIT = LU62, FILE = NAMEFIL(1:KNMFIL)//'.cpi',
     1      STATUS = 'UNKNOWN')
          WRITE (LU62, 99999, IOSTAT = IOST)
          WRITE (LINE, 99998, IOSTAT = IOST) PAR(411)
          CALL GEN039 (-1, LINE, 1, 10, NB, NE)
          WRITE (LU62, 99997, IOSTAT = IOST) LINE(NB:NE)
          WRITE (LINE, 99998, IOSTAT = IOST) FIN
          CALL GEN039 (-1, LINE, 1, 10, NB, NE)
          WRITE (LU62, 99997, IOSTAT = IOST) LINE(NB:NE)
C * GET NUMBER OF STEPS
          WRITE (LINE, 99998, IOSTAT = IOST) PAR(411)
          CALL GEN039 (-1, LINE, 1, 10, NB, NE)
          WRITE (LU62, 99997, IOSTAT = IOST) LINE(NB:NE)
          WRITE (LU62, 99995, IOSTAT = IOST)
     1      KRAD(1:2), PAR(17), DATIJD
          CALL GEN039 (-1, JID, 1, 50, NB, NE)
          WRITE (LU62, 99997, IOSTAT = IOST) JID(NB:50)
          WRITE (LU62, 99994, IOSTAT = IOST)
        END IF
C * XY FORMAT OUTPUT
        IF (IPR(799) == 1) THEN
          OPEN (UNIT = LU62, FILE = NAMEFIL(1:KNMFIL)//'.xy',
     1      STATUS = 'UNKNOWN')
          WRITE (LU62, 99985) PAR(17)
        END IF
C * REFL PLOT
        SCALE = 2.0 * RGBL(6) * (HORS - 2.0) / (IPR(500) * 20.0)
        DO I = 1, NREFL
          XP = VOID(NP73 + I * 5-1) * SCALE + 1.0
          YP = 1.2
          IF (XP <= HORS - 1.0) THEN
            CALL GGIP (XP, 1.4, 0.0, 3)
            CALL GGIP (XP, 1.6, 0.0, 2)
          END IF
        END DO
C * OUTPUT CURVE
        XP = 1.0
        NB = 1
        NE = 1
        CALL GGIP (XP, 1.7, 0.0, 3)
        DO I = 1, IFN
          XP = XP + XSTEP
          YP = MIN (VERT - 4.0, 1.7 + VOID(I) * SCL / VM)
          CALL GGIP (XP, YP, 0.0, 2)
          IF (IPR(569) + IPR(570) + IPR(649) > 0) THEN
            IF (I > 1 .AND. I < IFN .AND. YP > 3.0) THEN
              IF (VOID(I - 1) < VOID(I) .AND.
     1            VOID(I + 1) < VOID(I)) THEN
                THETA = I * PAR(411) / 2
                D = PAR(17) / (2.0 * SIN (THETA / RGBL(6)))
                Q = RGBL(5) / D
C * DISPLAY D-VALUES
                IF (IPR(569) == 1) THEN
                  WRITE (NQ1, 99996, IOSTAT = IOST) D
C * DISPLAY TWO-THETA VALUES
                ELSE IF (IPR(570) == 1) THEN
                  WRITE (NQ1, 99996, IOSTAT = IOST) 2 * THETA
C * DISPLAY LAMBDA / (2 * SIN(THETA( = Q VALUES
                ELSE IF (IPR(649) == 1) THEN
                  WRITE (NQ1, 99988, IOSTAT = IOST) Q
                END IF
                XPP = XP + 0.0875
                YPP = YP
                CALL PLA439 (90.0, NQ1, 7, 0.175, 2, 1, XPP, YPP)
                CALL GGIP (XP, YP, 0.0, 3)
              END IF
            END IF
          END IF
          WRITE (LINE, 99992, IOSTAT = IOST)
     1      NINT (VOID(I) * 10000.0 / VM)
          CALL GEN039 (-1, LINE, 1, 10, NB, NE)
          IF (IPR(650) == 1)
     1      WRITE (LU62, 99997, IOSTAT = IOST) LINE(NB:NE)
          IF (IPR(799) == 1)
     1      WRITE (LU62, 99984) I * PAR(411), VOID(I)
        END DO
        IF (IPR(650) == 1) CLOSE (UNIT = LU62, IOSTAT = IOST)
        IF (IPR(799) == 1) CLOSE (UNIT = LU62, IOSTAT = IOST)
      END IF
      IF (FIN > 40.0) THEN
        IS = 5
      ELSE
        IS = 1
      END IF
      XP  = 1.0
      XST = IS * XSTEP / PAR(411)
      N   = 0
      DO WHILE (N <= NINT (FIN))
        CALL GGIP (XP, 0.8, 0.0, 3)
        CALL GGIP (XP, 1.2, 0.0, 2)
        CALL GEN040 (N, NQ1, IP)
        CALL PLA439 (0.0, NQ1, IP, 0.2, 1, 1, XP + 0.1, 1.0)
        IF (N > 0 .AND. (IPR(569) + IPR(649) /= 0)) THEN
          XM = 0.5 * PAR(17) / SIN (N / (RGBL(6) * 2.0))
          IF (IPR(569) == 1) THEN
            M = NINT (100.0 * XM)
          ELSE IF (IPR(649) == 1) THEN
            M = NINT (1000.0 * RGBL(5) / XM)
          END IF
          CALL GEN040 (M, NQ1, IP)
          CALL PLA439 (0.0, NQ1, IP, 0.175, 2, 1, XP + 0.01, 0.6)
        END IF
        XP = XP + XST
        N  = N  + IS
      END DO
      IF (IPR(649) == 0) THEN
        CALL PLA439 (0.0, '2-Theta Deg. / d * 100 Ang.',
     1    12 + 15 * IPR(569), 0.35, 1, 1, HORS - 8.0, 0.1)
      ELSE
        CALL PLA439 (0.0, '2-Theta Deg. / d * 1000 A-1',
     1       27, 0.35, 1, 1, HORS - 8.0, 0.1)
      END IF
      RETURN
99999 FORMAT ('SIETRONICS XRD SCAN')
99998 FORMAT (F10.3)
99997 FORMAT (A)
99996 FORMAT (F6.2)
99995 FORMAT (A, /, F7.5, /, A, /, '1')
99994 FORMAT ('SCANDATA')
99993 FORMAT (A, F9.2)
99992 FORMAT (I10)
99991 FORMAT ('Missing Low Order Reflections =', I4)
99990 FORMAT ('SpaceGroup ', A)
99989 FORMAT ('Lambda ', F8.5)
99988 FORMAT (F6.3)
99987 FORMAT ('Temp', 5X, I5, 'K')
99986 FORMAT (A, F7.2)
99985 FORMAT (F8.5)
99984 FORMAT (F10.2, F10.2)
      END SUBROUTINE PLA115
 
      MODULE vscr
      SAVE
      INTEGER :: IER
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: N23
      INTEGER :: NGB
      INTEGER :: NGE
      INTEGER :: NJB
      INTEGER :: NJE
      INTEGER :: NJGR
      INTEGER :: ISLA
      INTEGER :: NSAV
      INTEGER :: NSYM
      INTEGER :: NTGRD
      INTEGER, DIMENSION(4, 2) :: NJG
      INTEGER, DIMENSION(3, 2) :: IGR
      INTEGER, DIMENSION(3)    :: JGR
      INTEGER, DIMENSION(3)    :: KGR
      INTEGER, DIMENSION(3)    :: MGR
      INTEGER, DIMENSION(3)    :: NGNX
      INTEGER, DIMENSION(4, 3) :: I123
      INTEGER, DIMENSION(3, 2) :: NXYZ
      REAL :: DOT
      REAL :: CSLA
      REAL :: OR11
      REAL :: OR12
      REAL :: OR13
      REAL :: OR22
      REAL :: OR23
      REAL :: OR33
      REAL :: GRTR
      REAL, DIMENSION(6)    :: V9
      REAL, DIMENSION(3, 3) :: EV
      REAL, DIMENSION(3)    :: EW
      REAL, DIMENSION(3, 3) :: DUMW
      CHARACTER(len=255)       :: PLPATH
      END MODULE vscr
 
      SUBROUTINE PLA118
C * VOID/SOLV ROUTINE
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE vscr
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IZ
      INTEGER :: LU
      INTEGER :: NX
      INTEGER :: NY
      INTEGER :: NZ
      INTEGER :: KAT
      INTEGER :: ISL
      INTEGER :: IVD
      INTEGER :: NXY
      INTEGER :: NHV
      INTEGER :: LAST
      INTEGER :: MXYZ
      INTEGER :: NHVL
      INTEGER :: IVDX
      INTEGER :: IVDY
      INTEGER :: IVDZ
      INTEGER :: ISLL
      INTEGER :: IVAL
      INTEGER :: ISAV
      INTEGER :: IAN0
      INTEGER :: NADD
      INTEGER :: ICHR
      INTEGER :: IDUM
      INTEGER :: LVKX
      INTEGER :: LVKY
      INTEGER :: LVKZ
      INTEGER :: LSKX
      INTEGER :: LSKY
      INTEGER :: LSKZ
      INTEGER :: LVDX
      INTEGER :: LVDY
      INTEGER :: LVDZ
      INTEGER :: NGRID
      INTEGER :: IATCK
      INTEGER :: LXMAX
      INTEGER :: LYMAX
      INTEGER :: LZMAX
      INTEGER :: LXMIN
      INTEGER :: LYMIN
      INTEGER :: LZMIN
      INTEGER :: FINDEXE
      INTEGER :: MAXSGRID
      REAL :: ANG
      REAL :: AVOL
      REAL :: CMIN
      REAL :: CRIT
      REAL :: DIST
      REAL :: VMAX
      REAL :: XLNG
      REAL :: PERC
      REAL :: XXOM5
      REAL :: XXOM6
      REAL :: XXOM7
      REAL :: CRIT2
      REAL :: APERC
      REAL :: OHASH
      REAL :: OHASHI
      REAL :: GEN009
C * IPR(189) = 1 - VOID SEARCH + PACKING INDEX
C * IPR(189) = 2 - SOLV(ent accessible void) SEARCH
C * IPR(210) = -2 - NEWSYM MODE
C * IPR(210) = -1 - CALC FCF MODE
C * IPR(210) =  0 - NONE
C * IPR(210) =  1 - SQUEEZE MODE
C * IPR(210) =  2 - DIFF MAP DISPLAY MODE
      PAGET = 'VOIDS'
C * OPEN/REWIND SAV-FILE (SOLVENT ACCESSIBLE VOLUME)
      INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.sav', OPENED = OPEND)
      IF (OPEND) THEN
        REWIND (UNIT = LU15, IOSTAT = IOST)
      ELSE
        OPEN (UNIT = LU15, FILE = NAMEFIL(1:KNMFIL)//'.sav',
     1    STATUS = 'UNKNOWN', FORM = 'UNFORMATTED')
      END IF
C * SET SUB-MENU #
C * SQUEEZE MODE
      IF (IPR(210) == 1) THEN
        IGBL(6) = 36
C * SOLVENT ACCESSIBLE VOLUME DISPLAY
      ELSE IF (IPR(326) == 2) THEN
        IGBL(6) = 24
C * PLATON
      ELSE
        IGBL(6) = 10
      END IF
      CALL GEN097 (I123, 1, 12, 0)
      I123(2, 1) = 1
      I123(3, 2) = 1
      I123(4, 3) = 1
C * GET NUMBER OF SYMMETRY OPERATIONS
      NSYM = IPR(48)
      NGB  = 0
      NGE  = 0
      NADD = 0
      CSLA = 0.0
      GRTR = FLOAT(ICHAR ('>'))
      DOT  = FLOAT(ICHAR ('.'))
C * GET RELEVANT ELEMENTS OF THE ORTHOGONALISATION MATRIX FOR DIST. CALC.
      OR11 = OR(1, 1)
      OR12 = OR(1, 2)
      OR13 = OR(1, 3)
      OR22 = OR(2, 2)
      OR23 = OR(2, 3)
      OR33 = OR(3, 3)
C * SETUP DLIM
      DO K = 1, 3
        DUMA(K + 3) = PAR(112 + K)
      END DO
C * ATOM ARRAY UPPER BOUND CHECK
      IF (IPR(39) <  NP1) THEN
C * STARTING ADDRESS OF CG-SOLVENT VOLUMES IN ATOM ARRAY
        NSAV = IPR(39) + 1
 
      ELSE
        IF (IGBL(3) /= 1) IPR(2) = 25
        GO TO 40
      END IF
C * INIT SOLVENT GRID-POINT COUNTER
   10 IPR(188) = 0
C * INIT OUT OF VDW-RADIUS GRID-POINTS COUNTER
      IPR(190) = 0
C * INIT NUMBER OF VOIDS
      IPR(198) = 0
C * VOID TEST RESULT (-1, 0, 1)
      IPR(199) = 0
C * SET MAXIMUM NUMBER OF GRIDPOINT FURTHER OUT THAN PROBE RAD [= 1.2 A]
C *   FROM VDW
      IF (IPR(491) == 0) THEN
        IF (IGBL(3) == 0) THEN
          IPR(491) = 40000
        ELSE
          IPR(491) = 5000
        END IF
      END IF
      MAXSGRID = IPR(491) * NSYM
C * DETERMINE GRID STEP = PAR(80) FROM PROBE RADIUS = PAR(84) (ANGSTROM)
      IF (IPR(214) > 0) PAR(80) = PAR(84) / IPR(214)
C * SET DMAX0
      PAR(19) = PAR(84)
C * SET DMAXS FOR VOID OR SOLV MODE
      IF (IPR(189) == 1) THEN
C * VOID MODE
        PAR(20) = PAR(84)
      ELSE
C * SOLV MODE
        PAR(20) = 0.0
      END IF
C * CALCULATE VOID SEARCH (PROBE) GRID
      DO K = 1, 3
        NGRID        = NINT (PAR(100 + K) / (PAR(80) * 2)) * 2
        PAR(80  + K) = 1.0 / NGRID
        IPR(193 + K) = NGRID
        MGR(K)       = IFIX (NGRID * PAR(84) * PAR(112 + K)) + 1
      END DO
C * GET NUMBER OF STEPS IN THE THREE DIRECTIONS (X, Y, Z)
      N1    = IPR(194)
      N2    = IPR(195)
      N3    = IPR(196)
      N23   = N2 * N3
      NTGRD = N1 * N23
      WRITE (LU6, 99986, IOSTAT = IOST) PAR(80), NTGRD * 100.0 / NVDR
C * INCREASE GRIDSTEP IN CASE OF OVERFLOW
      IF (NTGRD > NVDR) THEN
        IPR(214) = IPR(214) - 1
        IF (IPR(214) > 0) THEN
          IF (PAR(84) / IPR(214) < 0.41) THEN
            GO TO 10
          END IF
        END IF
C * ALERT _603 - Report TOO large VOID for VOID search
        IF (IGBL(3) == 1) THEN
          CALL PLA236 (603, 0, -999.0, 1.0, ' ', ' ')
        ELSE
          IPR(2) = 19
        END IF
        GO TO 40
      END IF
      KGR(1) = N23
      KGR(2) = N3
      KGR(3) = 1
C * INIT VOID GRID ARRAY
      CALL GEN074 (VOID, 1, NTGRD, 0.0)
      WRITE (PRBUF, 99999, IOSTAT = IOST) PAR(80), PAR(84)
C * START GRAPHICS WINDOW FOR SOLV/VOID RESULTS
      IF (IGBL(25) * IGBL(32) == 1 .AND. IPR(121) == 0 .AND.
     1    IGBL(3) /= 5) THEN
        IWIN = 1
        CALL GGIP (HORS, VERT, 0.0, 1)
        VRT = VERT - 0.6
        CALL PLA439 (0.0, PRBUF, 69, 0.4, 5 + IGBL(68), 2, 1.0, VRT)
        IF (IPR(483) > 0 .AND. IPR(484) == 0) THEN
          WRITE (PRBUF, 99968, IOSTAT = IOST)
          WRITE (LU6, 99971, IOSTAT = IOST) PRBUF(1:80)
          CALL PLA439 (0.0, PRBUF, 60, 0.5, 2, 2, 3.0, 1.0)
        END IF
        CALL PLA439 (0.0, 'WorkinG', 7, 3.0, 2, 10, 5.0, 8.0)
C * INIT GRIDPOINT COUNT TEXT
        WRITE (PRBUF, 99990, IOSTAT = IOST) PAR(84), IPR(198)
        CALL PLA439 (0.0, PRBUF, 68, 0.35, 1, 2, 0.5, 5.0)
        CALL PLA439 (0.0, PRBUF(70:77), 8, 0.35, 1, 2, 21.0, 5.0)
        CALL GGIP (0.0, 0.0, 0.0, 6)
        VRT = VRT - 0.2
      END IF
C * GRID SIZE HEADER: LAYER, DOWN, ACROSS
      IF (IGBL(63) > 2) THEN
C * NEWPAGE
        CALL PLA262 (0)
        CALL PLA262 (14)
C * BUT DO NOT INCLUDE 'CG' ENTRY IN LISTING
        IF (LMT(IENS(IAN), 1) == 'Cg') THEN
          IAN0 = IAN - 1
        ELSE
          IAN0 = IAN
        END IF
        DO L = 1, 2
          IF (L == 1) THEN
            LU = LU6
            WRITE (LU, 99963, IOSTAT = IOST) PAR(80), PAR(84), IPR(214)
          ELSE
            LU = LU7
            WRITE (LU, 99999, IOSTAT = IOST) PAR(80), PAR(84), IPR(214)
          END IF
C * LIST ELEMENT TYPES AND RADII
          WRITE (LU, 99975, IOSTAT = IOST)(LMT(IENS(I), 1), I = 1, IAN0)
          WRITE (LU, 99974, IOSTAT = IOST)
     1    (RADR(IENS(I), 4), I = 1, IAN0)
C * LIST GRID PARAMETERS
          WRITE (LU, 99983)
          WRITE (LU, 99989, IOSTAT = IOST)
     1      (CHAR (K + ICHAR ('W')), PAR(80 + K),
     2       IPR(193 + K), PAR(100 + K) / IPR(193 + K),
     3       K = 1, 3)
          WRITE (LU, 99983)
        END DO
C * TEST FOR 'LIST VOID MAP AND DISPLAY LEGEND'
        IF (IPR(197) == 1) THEN
          WRITE (LU7, 99997, IOSTAT = IOST)
          DO K = 1, IAN
            L = IEL(IEN(K))
            M = L / 100
            N = MOD (L, 100)
            NQ1(1 : 1) = CHAR (ICHAR ('A') + M - 1)
            IF (N /= 0) THEN
              NQ1(2 : 2) = CHAR (ICHAR ('a') + N - 1)
            ELSE
              NQ1(2 : 2) = ' '
            END IF
            WRITE (LU7, 99996, IOSTAT = IOST) K, NQ1(1:2)
          END DO
        END IF
      END IF
C * SCAN FOR IN/OUT WITH DUMMY H-ATOM PROBE
C * START GRID LOOP X, Y, Z
      NHV = 0
C * VOID GRID LOOP X (PAGE-TO-PAGE)
      V9(1) = - PAR(81)
      DO K = 1, N1
        V9(1) = V9(1) + PAR(81)
C * VOID GRID Y LOOP (DOWN PAGE)
        V9(2) = - PAR(82)
        DO L = 1, N2
          V9(2) = V9(2) + PAR(82)
C * VOID GRID Z LOOP (ACROSS PAGE)
          V9(3) = - PAR(83)
          DO M = 1, N3
            V9(3) = V9(3) + PAR(83)
            NHV   = NHV + 1
C * SKIP PREVIOUSLY HANDLED GRID POINTS
            IF (NINT (VOID(NHV)) == 0) THEN
C * START LOOP OVER UNIQUE AND AND SYMMETRY RELATED ATOMS
              CALL PLA119 (KAT)
C * CHECK FOR ERROR
              IF (IPR(2) /= 0) THEN
                IF (IGBL(3) == 1) IPR(2) = 0
                GO TO 20
              END IF
C * GET NEXT POINT OF VOID MAP
              IF (IPR(199) < 0) THEN
C * COUNT OUT-OF-VDW GRID-POINTS
                IPR(190)  = IPR(190) + 1
C * SET CHARACTER SPACE
                VOID(NHV) = 32.0
              ELSE IF (IPR(199) == 0) THEN
                DO J = 1, NSYM
                  DO I = 1, 3
                    SGY(I + 3) = 0.0
                    SGY(I)     = V9(I)
                  END DO
                  CALL SGSM (3, ICL, SGY, J, LU6, IERR)
                  IVDX = MOD (NINT (SGY(7) / PAR(81)) + N1, N1)
                  IVDY = MOD (NINT (SGY(8) / PAR(82)) + N2, N2)
                  IVDZ = MOD (NINT (SGY(9) / PAR(83)) + N3, N3)
                  NHVL = IVDX * N23 + IVDY * N3 + IVDZ + 1
                  IF (NINT (VOID(NHVL)) == 0) THEN
                    IPR(190) = IPR(190) + 1
                    IPR(198) = IPR(198) + 1
                    IF (IPR(198) == 1 .AND. IGBL(63) > 0)
     1                WRITE (LU6, 99991, IOSTAT = IOST)
                    IF (MOD (IPR(198), 10000) == 0) THEN
C * UPDATE NUMBER OF GRIDPOINTS FOUND
                      IF (IGBL(25) * IGBL(32) == 1 .AND.
     1                    IGBL(3) /= 5 .AND. IPR(121) == 0) THEN
                        CALL PLA439 (0.0, PRBUF(70:77), 8, 0.35, 0, 2,
     1                               21.0, 5.0)
                        WRITE (PRBUF, 99990, IOSTAT = IOST)
     1                    PAR(84), IPR(198)
                        CALL PLA439 (0.0, PRBUF(70:77), 8, 0.35, 1, 2,
     1                               21.0, 5.0)
                        CALL GGIP (0.0, 0.0, 0.0, 6)
                      END IF
                    END IF
C * TEST FOR VALIDATION RUN
                    IF (IGBL(3) == 1) THEN
                      IF (IPR(198) > MAXSGRID) THEN
C * TEST FOR SQUEEZE
                        IF (PAR(437) == 0.0 .AND. IPR(651) == 0)
     1                    THEN
C * ALERT _602 - VOID TOO LARGE
                          CALL PLA236 (602, 0,  1.0, 1.0, ' ', ' ')
                        ELSE
C * ALERT _606 - VERY LARGE VOID
                          CALL PLA236 (606, 0, -999.0, 1.0, ' ', ' ')
                        END IF
                        GO TO 40
                      END IF
                    END IF
C * SET CHARACTER >
                    VOID(NHVL) = GRTR
                  END IF
                END DO
C * IPR(199) > 0 - GRIDPOINT WITHIN VAN DER WAALS RADIUS
              ELSE
                CRIT  = PAR(23) - PAR(20)
                CRIT2 = CRIT**2
                LSKX  = INT (CRIT / (PAR(81) * PAR(101))) + 1
                LSKY  = INT (CRIT / (PAR(82) * PAR(102))) + 1
                LSKZ  = INT (CRIT / (PAR(83) * PAR(103))) + 1
                IVD   = IPR(59) + 1
C * SET NUMERICAL CHARACTER TO IDENTIFY WITHIN-ATOM-TYPE RANGE
                IF (IVD < 10) THEN
                  ICHR = ICHAR ('0') + IVD
                ELSE
                  ICHR = ICHAR ('*')
                END IF
                DO J = 1, NSYM
                  DO I = 1, 3
                    SGY(I + 3) = 0.0
                    SGY(I)     = XXO(KAT, I)
                  END DO
                  CALL SGSM (3, ICL, SGY, J, LU6, IERR)
                  XXOM5 = SGY(7)
                  XXOM6 = SGY(8)
                  XXOM7 = SGY(9)
                  LVKX  = NINT (XXOM5 / PAR(81))
                  LVKY  = NINT (XXOM6 / PAR(82))
                  LVKZ  = NINT (XXOM7 / PAR(83))
                  LXMIN = MAX (LVKX - LSKX, K - 1)
                  LYMIN = MAX (LVKY - LSKY, 0)
                  LZMIN = MAX (LVKZ - LSKZ, 0)
                  LXMAX = MIN (LVKX + LSKX, N1 - 1)
                  LYMAX = MIN (LVKY + LSKY, N2 - 1)
                  LZMAX = MIN (LVKZ + LSKZ, N3 - 1)
                  LVDX  = LXMIN
                  DO WHILE (LVDX <= LXMAX)
                    SGY(1) = LVDX * PAR(81) - XXOM5
                    LVDY   = LYMIN
                    DO WHILE (LVDY <= LYMAX)
                      SGY(2) = LVDY * PAR(82) - XXOM6
                      NHVL   = LVDX * N23 + LVDY * N3 + LZMIN
                      LVDZ   = LZMIN
                      DO WHILE (LVDZ <= LZMAX)
                        NHVL = NHVL + 1
                        IF (NINT (VOID(NHVL)) == 0) THEN
                          SGY(3) = LVDZ * PAR(83) - XXOM7
                          IF ((OR11 * SGY(1) + OR12 * SGY(2)
     1                      + OR13 * SGY(3))**2 + (OR22 * SGY(2)
     2                      + OR23 * SGY(3))**2 + (OR33 * SGY(3))**2
     3                      < CRIT2) VOID(NHVL) = ICHR
                        END IF
                        LVDZ = LVDZ + 1
                      END DO
                      LVDY = LVDY + 1
                    END DO
                    LVDX = LVDX + 1
                  END DO
                END DO
                IF (NINT (VOID(NHV)) == 0) VOID(NHV) = 32.0
              END IF
            END IF
          END DO
C * END OF M LOOP
        END DO
C * END OF L LOOP
      END DO
C * END OF K LOOP
C * DISPLAY SOLV/VOID SEARCH PROGRESS
      IF (IPR(198) > 0) THEN
        IF (IGBL(25) * IGBL(32) == 1 .AND.
     1    IPR(121) == 0 .AND. IGBL(3) /= 5) THEN
          CALL PLA439 (0.0, PRBUF(70:77), 8, 0.35, 0, 2, 21.0, 5.0)
          WRITE (PRBUF, 99990, IOSTAT = IOST)
     1      PAR(84), IPR(198)
          CALL PLA439 (0.0, PRBUF(70:77), 8, 0.35, 1, 2, 21.0, 5.0)
          WRITE (LU6, 99972, IOSTAT = IOST) PRBUF(1:80)
          CALL PLA439 (0.0, 'Collect S.A.V.', 14, 0.35, 3, 2, 11.0,
     1                 3.0)
          CALL GGIP (0.0, 0.0, 0.0, 6)
        END IF
      END IF
C * TEST FOR VOID-MODE
      IF (IPR(189) == 1) THEN
C * Calculate PACKING INDEX (Kitaigorodskii)
        IF (IPR(43) == 0) THEN
          PERC = 100.0 * (1.0  - (IPR(190) / FLOAT (NTGRD)))
          WRITE (PRBUF, 99992, IOSTAT = IOST) IPR(198), PERC
        ELSE
          WRITE (PRBUF, 99976, IOSTAT = IOST)
        END IF
        IF (IWIN == 1) THEN
          VRT = VRT - 0.8
          CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
        END IF
        WRITE (LU6, 99993, IOSTAT = IOST) PRBUF(1:80)
        IF (IGBL(63) > 1) THEN
          CALL PLA262 (5)
          WRITE (LU7, 99993, IOSTAT = IOST) PRBUF(1:80)
          WRITE (LU7, 99985, IOSTAT = IOST)
        END IF
      END IF
C * SET-UP PROBE
      IER = 0
      CALL PLA120
      IF (IER /= 0) GO TO 40
C * EXPAND
      IER = 0
      CALL PLA121
      IF (IER > 0) GO TO 40
      IF (IER < 0) GO TO 10
C * LIST VOID MAP (IPR(197) = 1)
      IF (IPR(197) == 1 .AND. IGBL(63) > 2) THEN
        DO I = 0, IPR(194) - 1
C * HEADER
          CALL PLA262 (-2)
          WRITE (LU7, 99998, IOSTAT = IOST)
     1      'X', I, IPR(194) - 1, 'Y', 'Z'
          DO J = 0, IPR(195) - 1
            N = I * N23 + J * N3
            M = N + N3
            N = N + 1
            CALL PLA262 (1)
            WRITE (LU7, 99995, IOSTAT = IOST)
     1        (CHAR (NINT (VOID(L))), L = N, M)
          END DO
        END DO
      END IF
      PAR(79)  = PAR(98)  / NTGRD
      PAR(150) = IPR(188) * PAR(79)
      IF (IWIN == 1) THEN
        WRITE (PRBUF, 99990, IOSTAT = IOST) PAR(84), IPR(198)
        CALL PLA439 (0.0, PRBUF, 76, 0.35, 0, 2, 0.5, 5.0)
        CALL PLA439 (0.0, PRBUF(70:77), 8, 0.35, 0, 2, 21.0, 5.0)
        CALL PLA439 (0.0, 'WorkinG', 7, 3.0, 0, 10, 5.0, 8.0)
        CALL PLA439 (0.0, 'Collect S.A.R.', 14, 0.35, 0, 2, 11.0,
     1               3.0)
        IF (IPR(483) > 0 .AND. IPR(484) == 0) THEN
          WRITE (PRBUF, 99968, IOSTAT = IOST)
          CALL PLA439 (0.0, PRBUF, 60, 0.5, 0, 2, 3.0, 1.0)
        END IF
        CALL GGIP (0.0, 0.0, 0.0, 6)
      END IF
C * TEST SOLVENT  VOLUME
      IF (PAR(150) > 0.0) THEN
        IF (IGBL(63) > 1) THEN
          IF (IPR(197) == 1) CALL PLA262 (0)
          CALL PLA262 (3)
          PAR(409) = PAR(150) * 100.0 / PAR(98)
          WRITE (LU6, 99994, IOSTAT = IOST)
     1      PAR(150), PAR(98), PAR(409)
          WRITE (LU7, 99994, IOSTAT = IOST)
     1      PAR(150), PAR(98), PAR(409)
C * TEST FOR CALC SOLV MODE
          IF (IPR(189) > 0) THEN
            WRITE (LU6, 99981, IOSTAT = IOST)
            CALL PLA262 (6)
            WRITE (LU7, 99981, IOSTAT = IOST)
            IF (IPR(210) <= 0) THEN
              CALL PLA262 (4)
              WRITE (LU7, 99980, IOSTAT = IOST)
              WRITE (LU6, 99980, IOSTAT = IOST)
            END IF
C * SOLV/VOID TABLE HEADER
            WRITE (PRBUF, 99984, IOSTAT = IOST)
            WRITE (LU6, 99970, IOSTAT = IOST) PRBUF(1:80)
            CALL PLA262 (3)
            WRITE (LU7, 99970, IOSTAT = IOST) PRBUF(1:80)
            IF (IWIN == 1) THEN
              IF (ISLA - NSAV > 15)
     1          PRBUF(55:) = ' Sqrt(Eigenvalues) (Ang.)'
              VRT = VRT - 0.8
              CALL PLA439 (0.0, PRBUF, 80, 0.35, 5 + IGBL(68),
     1                     2, 1.0, VRT)
              VRT = VRT - 0.2
            END IF
          END IF
        END IF
        PAR(549) = 0.0
        DO K = NSAV + 1, ISLA
          ISAV     = K - NSAV
          APERC    = JATC(K) * 100.0 / NTGRD
          AVOL     = APERC * PAR(98) / 100.0
          PAR(549) = PAR(549) + AVOL
C * REGISTER LARGEST SOLVENT ACCESSIBLE VOLUME
          PAR(289) = MAX (PAR(289), AVOL)
          DO L = 1, 3
            XXO(K, L) = XXO(K, L) / JATC(K)
            SXYZ(9 + L, ISAV) = XXO(K, L)
          END DO
          DUMW(1, 1) = SXYZ(4, ISAV) - SXYZ(1, ISAV)**2 / JATC(K)
          DUMW(1, 2) = SXYZ(7, ISAV)
     1               - SXYZ(1, ISAV) * SXYZ(2, ISAV) / JATC(K)
          DUMW(1, 3) = SXYZ(8, ISAV)
     1               - SXYZ(1, ISAV) * SXYZ(3, ISAV) / JATC(K)
          DUMW(2, 2) = SXYZ(5, ISAV)
     1               - SXYZ(2, ISAV)**2 / JATC(K)
          DUMW(2, 3) = SXYZ(9, ISAV)
     1               - SXYZ(2, ISAV) * SXYZ(3, ISAV) / JATC(K)
          DUMW(3, 3) = SXYZ(6, ISAV)
     1               - SXYZ(3, ISAV)**2 / JATC(K)
          CALL GEN024 (DUMW, EV, EW, DUMV)
C * TRANSFORM TO FRACTIONAL COORDINATES
          CALL GEN004 (ROR, DUMV, DUMW)
          DO I = 1, 3
            VMAX = 0.0
            DO J = 1, 3
              VMAX = MAX (VMAX, ABS (DUMW(J, I)))
              SXYZ ((I - 1) * 3 + J, ISAV) = DUMV(J, I)
            END DO
            OHASHI = IATC(K) * AVOL / JATC(K)
            IATCK  = MIN (999999, IATC(K))
            OHASH  = MIN (9999.9, OHASHI)
            WRITE (PRBUF, 99987, IOSTAT = IOST)
     1        K - NSAV, JATC(K), IATCK, NINT (APERC), NINT (AVOL),
     2        OHASH, (XXO(K, L), L = 1, 3), I,
     3        (DUMW(J, I) / VMAX, J = 1, 3),
     4        SQRT (MAX (0.0, EW(I) / JATC(K)))
            IF (I /= 1) CALL GEN038 (PRBUF, 1, 53)
            IF (IGBL(63) > 1) THEN
              WRITE (LU6, 99972, IOSTAT = IOST) PRBUF(1:80)
              CALL PLA262 (1)
              WRITE (LU7, 99972, IOSTAT = IOST) PRBUF(1:80)
            END IF
            IF (IWIN == 1) THEN
              IF (ISLA - NSAV > 15) THEN
                IF (I == 3) THEN
                    WRITE (PRBUF, 99967, IOSTAT = IOST)
     1              K - NSAV, JATC(K), IATCK, NINT (APERC),
     2              NINT (AVOL), OHASH, (XXO(K, L), L = 1, 3),
     3              (SQRT (MAX (0.0, EW(L) / JATC(K))), L = 1, 3)
                  VRT = VRT - 0.4
                  CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
                END IF
              ELSE
                VRT = VRT - 0.4
                CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
              END IF
            END IF
          END DO
        END DO
C * ANALYSE DIFFERENCE FOURIER MAP
        CALL PLA143 (2, 4.5, NSAV + 1, ISLA, IDUM)
      ELSE
        WRITE (PRBUF, 99988, IOSTAT = IOST)
        IF (IGBL(63) > 1) THEN
          WRITE (LU6, 99971, IOSTAT = IOST) PRBUF
          WRITE (LU7, 99971, IOSTAT = IOST) PRBUF
        END IF
        IF (IWIN == 1) THEN
          VRT = VRT - 5.0
          CALL PLA439 (0.0, PRBUF, 61, 0.45, 3, 2, 1.0, VRT)
          VRT = VRT - 3.0
          IF (IPR(210) == 1) THEN
            WRITE (PRBUF, 99962, IOSTAT = IOST)
            CALL PLA439 (0.0, PRBUF, 21, 0.45, 3, 2, 9.0, VRT)
          END IF
        END IF
C * RESET CALC SQUEEZE
        IPR(210) = 0
        RETURN
      END IF
      IF (IPR(200) == 2) THEN
        IF (IGBL(63) > 0) THEN
          WRITE (LU6, 99978, IOSTAT = IOST)
          CALL PLA262 (3)
          WRITE (LU7, 99978, IOSTAT = IOST)
        END IF
C * TEST FOR SQUEEZE
        IF (PAR(437) == 0.0 .AND. IPR(651) == 0) THEN
C * ALERT _601 - Report Largest Isolated VOID size
          CALL PLA236 (601, 0, PAR(289), PAR(289), ' ', ' ')
        ELSE
C * ALERT _605
          CALL PLA236 (605, 0, -999.0, PAR(289), ' ', ' ')
        END IF
        IF (PAR(289) > 20.0) THEN
          CALL PLA015 (0, 4)
        ELSE
          CALL PLA015 (0, 3)
        END IF
      END IF
C * CHECK FOR CONTINUE (TEST # GRIDPOINTS > 0)
   20 IF (IPR(188) > 0) THEN
C * DETERMINE DIMENSIONS OF THE VOIDS
        IF (IPR(189) > 0 .AND. IGBL(63) > 1) THEN
          ISLL = 0
          LAST = 0
          CMIN = 0.95
          NADD = 0
          REWIND (UNIT = LU15, IOSTAT = IOST)
          DO
            READ (LU15, IOSTAT = IOST) IX, IY, IZ, ISL, NADD, V3
            LAST = IOST
            IF (IOST /= 0 .OR. ISL /= ISLL) THEN
C * REPORT VOID SIZE DATA
              IF (ISLL == 0) THEN
C * OUPUT HEADER TEXT FOR VOID MAIN AXES VALUES
                CALL PLA262 (5)
                WRITE (LU6, 99982, IOSTAT = IOST)
                WRITE (LU7, 99982, IOSTAT = IOST)
              ELSE
C * REPORT VOID MAIN AXIS VALUES
                CALL PLA262 (1)
                WRITE (LU6, 99979, IOSTAT = IOST)
     1            ISLL, (VECN(K), K = 1, 7)
                WRITE (LU7, 99979, IOSTAT = IOST)
     1            ISLL, (VECN(K), K = 1, 7)
                DO I = 1, 3
                  SXYZ(12 + I, ISLL) = VECN(2 * I)
                END DO
                IF (LAST /= 0) GO TO 30
              END IF
              CALL GEN074 (VECN, 1, 7, 0.0)
              ISLL = ISLL + 1
              DO I = 1, 3
                V4(I) = SXYZ(9 + I, ISLL)
                V5(I) = SXYZ(I,     ISLL)
                V6(I) = SXYZ(3 + I, ISLL)
                V8(I) = SXYZ(6 + I, ISLL)
              END DO
              CALL GEN002 (1, OR, V4, V2, XLNG)
            END IF
            DO I = 1, 3
              V4(I) = V3(I) - V2(I)
            END DO
            DIST = SQRT (GEN009 (V4, V4))
            IF (DIST > VECN(7)) VECN(7) = DIST
C * CHECK WITH LARGEST EW DIRECTION
            ANG = GEN009 (V5, V4) / DIST
            IF (ANG > CMIN) THEN
              IF (DIST > VECN(2)) VECN(2) = DIST
            ELSE IF (ANG < - CMIN) THEN
              IF (DIST > ABS (VECN(1))) VECN(1) = - DIST
            ELSE
              ANG = GEN009 (V6, V4) / DIST
              IF (ANG > CMIN) THEN
                IF (DIST > VECN(4)) VECN(4) = DIST
              ELSE IF (ANG < - CMIN) THEN
                IF (DIST > ABS (VECN(3))) VECN(3) = - DIST
              ELSE
                ANG = GEN009 (V8, V4) / DIST
                IF (ANG > CMIN) THEN
                  IF (DIST > VECN(6)) VECN(6) = DIST
                ELSE IF (ANG < - CMIN) THEN
                  IF (DIST > ABS (VECN(5))) VECN(5) = - DIST
                END IF
              END IF
            END IF
          END DO
        END IF
C * TEST FOR SOLV-PLOT TYPE
   30   IF (IPR(326) == 2) THEN
          IF (IWIN == 1) CALL PLA123
C * TEST FOR F3D PLOT TYPE
        ELSE IF (IPR(326) == 3) THEN
          IPR(580) = 2
C * GENERATE F3D STYLE INPUT FOR SOLV-MAP
          OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'.slv',
     1          STATUS = 'UNKNOWN')
          WRITE (LU65, 99966, IOSTAT = IOST) JID(1:50),
     1          ((OR(I, J), J = 1, 3), I = 1, 3),
     2          (PAR(I), I = 101, 106), (IPR(I), I = 395, 397)
          NX   = IPR(395)
          NY   = IPR(396)
          NZ   = IPR(397)
          MXYZ = NX * NY * NZ
          NXY  = NX * NY
          CALL GEN074 (VOID, 1, MXYZ, 0.0)
C * NV   = VOID #
C * NADD = 1 - OHASHI
C * NADD = 2 - SOLV
          REWIND (UNIT = LU15, IOSTAT = IOST)
          DO
            READ (LU15, IOSTAT = IOST) IX, IY, IZ
            IF (IOST /= 0) EXIT
            IF (IX < 0)   IX = IX + NX
            IF (IY < 0)   IY = IY + NY
            IF (IZ < 0)   IZ = IZ + NZ
            IF (IX >= NX) IX = IX - NX
            IF (IY >= NY) IY = IY - NY
            IF (IZ >= NZ) IZ = IZ - NZ
            VOID(IZ * NXY + IY * NX + IX + 1) = 1.0
          END DO
          DO K = 1, NZ
            M = (K - 1) * NXY
            WRITE (LU65, 99965, IOSTAT = IOST) K - 1
            DO J = 1, NY
              N = M + (J - 1) * NX
              WRITE (LU65, 99969, IOSTAT = IOST)
     1          (NINT (VOID(N + I)), I = 1, NX)
            END DO
          END DO
          WRITE (LU65, 99973, IOSTAT = IOST) IPR(39)
          DO I = 1, IPR(39)
            CALL GEN048 (-4, IFG(1, I), 15, IVAL)
            NQ1 = LMT(IVAL + 1, 1)
            CALL GEN020 (1, NQ1, 2, 2)
            N = 0
            IF (NQ1(1:1) == ' ') N = 1
            WRITE (LU65, 99977, IOSTAT = IOST)
     1        NQ1(1+N:4+N), (XXO(I, J), J = 1, 3)
          END DO
          CLOSE (UNIT = LU65)
C * F3D
          PLPATH = ' '
          IGBL(145) = FINDEXE ('F3DEXE', PLPATH, 'f3d')
          IF (IGBL(145) > 0) THEN
            PLPATH(IGBL(145) + 1:) = ' '//NAMEFIL(1:KNMFIL)//'.slv &'
            IER = 0
            CALL SPAWN (PLPATH, LU6, .true., IER)
          END IF
          IPR(580) = -2
          IPR(2)   = -1
        END IF
      END IF
      RETURN
C * ERROR -> NO-SQUEEZE
   40 IPR(210) = 0
      WRITE (LU6, 99964, IOSTAT = IOST)
C * RESET MENU #
      IGBL(6) = 10
      RETURN
99999 FORMAT ('Search for and Analysis of Solvent Accessible Voids',
     1        ' in ''P1'' Structure - Grid =', F5.2,
     2        ' Ang., Probe Radius =', F6.2, ' Ang., NStep =', I2)
99998 FORMAT (A, '-Section : ', I5, ' - (Max =', I5, ') --- ',
     1        A, '-Vertical and ', A, '-Horizontal', /)
99997 FORMAT (/, 'SOLV- or VOID-Map Gridpoint Entries: ', //,
     1           '- Numerical  : Atom Type Number', /,
     2           '- ''*''        : Atom Type Number > 9', /,
     3           '- Alphabetic : Independent Solvent Accessible Void',
     4           ' with Extension = Dots', /)
99996 FORMAT (/, 'Atom Type Number ', I3, ' = Label ', A)
99995 FORMAT (130A)
99994 FORMAT (':: Total Potential Solvent Area Vol', F9.1, ' Ang^3', /,
     1        18X, 'per Unit Cell Vol', F9.1, ' Ang^3 [',F4.1,'%]', /)
99993 FORMAT (/, A, /)
99992 FORMAT (':: Nr of VOID Grid-points =', I8,
     1       ', Model Filled Space', F5.1, '% (= Packing Index)')
99991 FORMAT (':: Note: VOID/SOLV/SQUEEZE is relatively compute',
     1       ' compute intense', /)
99990 FORMAT (':: Nr of gridpoints at least', F5.2, ' Ang.',
     1        ' from nearest vdWaals Surface =', I8)
99989 FORMAT ('Grid: ', A, '-Axis Step =', F10.6,
     1        ' = Points', I4, ', Angstrom Step =', F8.5)
99988 FORMAT (':: Unit cell Contains NO Residual Solvent',
     1       ' Accessible Void(s).')
99987 FORMAT (I2, I7, '[', I6, ']', I3, I6, '[', F6.1, ']', 1X, 3F6.3,
     1        I2, 1X, 3F6.3, F6.2)
99986 FORMAT (/, ':: VOID/SOLV Gridstep (Angstrom) (re)set to', F5.2,
     1       ', Percent Memory =', F5.1)
99985 FORMAT ('(See A.I. Kitajgorodskij, Molecular Crystals and',
     1        ' Molecules, New-York, Academic Press, 1973.)', /)
99984 FORMAT ('Void #GridPoint VolPerc.  Vol(A^3)', 2X,
     1        'X(av) Y(av) Z(av) Eigenvector(frac) Sig(Ang)')
99983 FORMAT (1X)
99982 FORMAT (5X, 'Report the Distance from VOID-CG to Boundary in ',
     1        'EigenVector-Directions', //, ' Nr', 1X, 'MinEV1', 1X,
     2        'MaxEV1', 1X, 'MinEV2', 1X, 'MaxEV2', 1X, 'MinEV3', 1X,
     3        'MaxEV3', 1X, 'MaxDist (Ang)', /, 80('='))
99981 FORMAT ('Note: Expected volumes for solvent molecules are:',
     1       /, 6X, 'A hydrogen bonded H2O-molecule      40 Ang^3',
     2       /, 6X, 'Small molecules (e.g. Toluene) 100-300 Ang^3',
     3      //, 6X, 'The maximum number of molecules of a given type',
     4       /, 6X, 'in a void can be estimated by deviding the void',
     5       /, 6X, 'volume by twice the molecular volume of that',
     6       /, 6X, 'molecule as calculated with the MOLVOL routine.',
     3      //, 6X, 'Values below for gridpoints and volumes in [] ',
     4       /, 6X, 'refer to areas where atom centers may reside.')
99980 FORMAT (/, ':: Use the CALC SQUEEZE instruction to calculate ',
     1        'and optionally correct for', /,
     2        ':: Density identified in solvent accessible areas',
     3        ' (Reflection data required)')
99979 FORMAT (I3, 7F7.2)
99978 FORMAT (':: Note: use CALC VOID (not CALC SOLV) for',
     1       ' Packing Index. ', /)
99977 FORMAT (A, 3F10.4)
99976 FORMAT (':: No Packing Index - Disordered Structure')
99975 FORMAT ('van der Waals (or ion) Radii used in the Analysis',
     1        /, 80('='), /, 16(3X, A))
99974 FORMAT (80('-'), /, 16F5.2)
99973 FORMAT ('ATOMS',  I8)
99972 FORMAT (A)
99971 FORMAT (/, A, /)
99970 FORMAT (/, A, /, 80('-'))
99969 FORMAT (250I1)
99968 FORMAT ('Warning: No Hydrogen Atoms in VOID/SQUEEZE Model')
99967 FORMAT (I2, I7, '[', I6, ']', I3, I6, '[', F6.1, ']', 1X, 3F6.3,
     1        3F8.3)
99966 FORMAT ('TITL ', A, /, 'TRAN ', 3F9.4, F8.4, 2F9.4, 2F8.4, F9.4,
     1        /, 'CELL ', 6F9.4, /, 'SIZE', 3I8)
99965 FORMAT ('SECTION', I8)
99964 FORMAT (/, 'Problem, IPR(210) set to zero')
99963 FORMAT (':: Search for and Analysis of Solvent Accessible Voids',
     1        ' in ''P1'' Structure', /, ':: Grid =', F5.2, ' Ang.,',
     2        ' Probe Radius =', F6.2, ' Ang., NStep =', I2, /)
99962 FORMAT ('SQUEEZE Job Cancelled')
      END SUBROUTINE PLA118
 
      SUBROUTINE PLA119 (KAT)
C * SUBROUTINE HANDLES ATOM LOOP
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE sgxyz
      USE vscr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      INTEGER :: N
      INTEGER :: JAT
      INTEGER :: JP3
      INTEGER :: KAX
      INTEGER :: KAT
      INTEGER :: NAT
      INTEGER :: NPOW
      INTEGER :: IOMT
      INTEGER :: IHLP0
      INTEGER :: ILOOP
      REAL :: DIJ
      REAL :: DIJK
      REAL :: P23K
      CHARACTER(len=1) :: CSCRAT
C * ORTHOGONALIZE GRID POINT COORDINATES
      V9(4) = OR11 * V9(1) + OR12 * V9(2) + OR13 * V9(3)
      V9(5) = OR22 * V9(2) + OR23 * V9(3)
      V9(6) = OR33 * V9(3)
      IPR(199) = 0
      P23K     = 0.0
C * GET NUMBER OF UNIQUE ATOMS
      NAT      = IPR(37)
C * COPY AND ORDER ATOM NP1 COORDINATES,
      KAX      = -1
      DO
        IF (KAX == 0) THEN
          GO TO 20
        ELSE IF (KAX > 0) THEN
          KAX = KAX - 1
          GO TO 40
        END IF
C * SYMMETRY ELEMENT LOOP
        IPR(54) = 0
   10   IPR(54) = IPR(54) + 1
        KAX     = -1
        IF (IPR(54) > NSYM) RETURN
C * ATOM J LOOP
        JAT = 0
   20   JAT = JAT + 1
        IF (JAT > NAT) GO TO 10
        CALL GEN048 (-1, IFG(2, JAT), 27, IOMT)
        IF (IOMT /= 0) GO TO 20
C * GET BIT 9-18   (IPR(59), IPR(62))
        CALL GEN048 (-10, IFG(1, JAT), 9, IHLP0)
C * RETRIEVE EL.TYPE (BIT 15 - 18) AND RESD NUMB (BIT 9-14) FOR ATOM JAT
        IPR(59)  = IHLP0 / 64
        IPR(62)  = MOD (IHLP0, 64)
        PAR(23)  = PAR(19)
        PAR(293) = 0.0
C * GET ELEMENT TYPE (E.G. 1 = H)
        IPR(510) = IEN(IPR(59) + 1)
        PAR(23)  = PAR(23) + RADR(IPR(59) + 1, 2) + PAR(293)
        P23K     = PAR(23)**2
C * SET D-LIMITS ON EACH AXIS AND ZERO INITIAL SHIFTS
        DO I = 1, 3
          DUMA(I) = DUMA(I + 3) * PAR(23)
          ITR(I)  = 0
        END DO
        DO I = 1, 3
          SGZ(I + 3) = 0.0
          SGZ(I)     = XXO(JAT, I)
        END DO
        CALL SGSM (3, CSCRAT, SGZ, IPR(54), LU7, IERR)
        DO I = 1, 3
          SGZ(I) = SGZ(I + 6)
        END DO
C * BEGIN TRANSLATIONAL SEARCH ROUTINE (SEE ROLLETT)
        KAX = 1
C * TRANSLATE SGZ ON AXIS KAX TO A POINT BELOW LOWER LIMIT
   30   IF (V9(KAX) - SGZ(KAX) <= DUMA(KAX)) THEN
          SGZ(KAX) = SGZ(KAX) - 1.0
          GO TO 30
        END IF
   40   DO
C * ADVANCE 1 UNIT ON AXIS KAX
          SGZ(KAX) = SGZ(KAX) + 1.0
          IF (V9(KAX) - SGZ(KAX) < DUMA(KAX)) THEN
            IF (SGZ(KAX) - V9(KAX) <= DUMA(KAX)) EXIT
C * TEST GIVES ATOM OUT OF RANGE. REDUCE AXIS KAX BY 1
            KAX = KAX - 1
            IF (KAX <= 0) GO TO 20
          END IF
        END DO
C * KAX = 0 SIGNALS THE END OF THE TRANSLATION SEARCH
C * IF SGZ WAS WITHIN RANGE ON AXIS KAX THEN WE ADVANCE KAX BY 1
        KAX = KAX + 1
        IF (KAX < 4) GO TO 30
C * CALCULATE ITR  AND IPR(26)
        NPOW    = 1000
        IPR(26) = IPR(54) * NPOW + 555
        ILOOP   = 0
        DO J = 1, 3
          NPOW       = NPOW / 10
          ITR(J)     = ITR(J) + NINT (SGZ(J) - SGZ(J + 6))
          SGZ(J + 6) = SGZ(J)
          IF (IABS(ITR(J)) > 4) THEN
C * OUT OF +/- 4 TRANSLATION RANGE
            IPR(494) = IPR(494) + 1
            ILOOP = 1
            EXIT
          END IF
          IPR(26) = IPR(26) + ITR(J) * NPOW
        END DO
        IF (ILOOP == 1) CYCLE
        KAT = IPR(39) + IPR(24) + 1
        IF (KAT > NP1 - IPR(75)) THEN
C * ATTEMPT TO EXCEED MAX ATOM LIMIT
          IPR(2) = 1
          RETURN
        END IF
        DO N = 1, 3
          J   = 4 - N
          JP3 = J + 3
          IF (JAT /= KAT) THEN
            XXO(KAT, J) = SGZ(J + 6)
          END IF
          XXO(KAT, JP3) = 0
          DO L = J, 3
            XXO(KAT, JP3) = XXO(KAT, JP3) + XXO(KAT, L) * OR(J, L)
          END DO
        END DO
C * ATOM IN RANGE FOR ALL 3 AXES. NOW CALCULATE EXACT DISTANCE AND TEST
        DIJK = (V9(4) - XXO(KAT, 4))**2 + (V9(5) - XXO(KAT, 5))**2 +
     1         (V9(6) - XXO(KAT, 6))**2
        IF (DIJK <= P23K) THEN
          DIJ = SQRT (DIJK)
C * IPR(199) RANGE:  I ... 1 ... VDW ... -1 ... VDW + PAR(19) .... 0
          IF (DIJ > PAR(23) - PAR(20)) THEN
            IPR(199) = -1
            CYCLE
          ELSE
            IPR(199) = 1
            RETURN
          END IF
        END IF
      END DO
      END SUBROUTINE PLA119
 
      SUBROUTINE PLA120
C * SOLV - SETUP PROBE
      USE files
      USE parameters
      USE plato
      USE vscr
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: I3
      INTEGER :: I1N
      INTEGER :: I2N
      INTEGER :: I3N
      INTEGER :: IND3
      INTEGER :: INDX
      INTEGER :: INDX3
      REAL :: GEN006
C * SETUP LIST OF GRIDPOINTS WITHIN PAR(84) Angstrom OF CENTRAL GRIDPOINT
      NJG(1, 1) = - 1
      NJG(1, 2) = 25
      L         = 0
      DO
        L      =   L      + 1
        JGR(L) = - MGR(L) - 1
   10   JGR(L) =   JGR(L) + 1
        IF (JGR(L) > MGR(L)) THEN
          L = L - 1
          IF (L == 0) THEN
C * GENERATE SHIFTED SETS (IN X, Y & Z)
            NJGR = NJG(1, 2)
            DO N = 2, 4
              NJG(N, 1) = NJG(N - 1, 2) - 1
              NJG(N, 2) = NJG(N - 1, 2) + 8
              DO 20 I = 1, NJGR
                I1 = JNSX(I * 3 - 2)
                I2 = JNSX(I * 3 - 1)
                I3 = JNSX(I * 3)
                IF (ABS (I1) < 2 .AND. ABS (I2) < 2 .AND.
     1              ABS (I3) < 2) THEN
                  IF (JNSX(I * 3 - 4 + N) == 1) THEN
                    NJG(N, 1) = NJG(N, 1) + 1
                    INDX      = NJG(N, 1)
                  ELSE
                    GO TO 20
                  END IF
                ELSE
                  I1N = I1 + I123(N, 1)
                  I2N = I2 + I123(N, 2)
                  I3N = I3 + I123(N, 3)
                  M   = 0
                  DO J = 1, NJGR
                    IF (ABS (JNSX(M + 1) - I1N) +
     1                  ABS (JNSX(M + 2) - I2N) +
     2                  ABS (JNSX(M + 3) - I3N) == 0) GO TO 20
                    M = M + 3
                  END DO
                  NJG(N, 2) = NJG(N, 2) + 1
                  INDX      = NJG(N, 2)
                END IF
                INDX3 = INDX * 3
                IF (INDX3 + 3 > 2 * NP23) THEN
                  WRITE (LU6, 99999, IOSTAT = IOST)
                  IER = 1
                  RETURN
                END IF
                DO K = 1, 3
                  JNSX(INDX3 + K) = JNSX(I * 3 - 3 + K)
                END DO
   20         CONTINUE
            END DO
            RETURN
          END IF
          GO TO 10
        ELSE
          IF (L >= 3) THEN
C * PUT FIRST COORDINATION SPHERE IN FRONT
            IF (ABS (JGR(1)) < 2 .AND. ABS (JGR(2)) < 2 .AND.
     1          ABS (JGR(3)) < 2) THEN
              IF (ABS (JGR(1)) + ABS (JGR(2)) + ABS (JGR(3)) == 0)
     1          GO TO 10
              NJG(1, 1) = NJG(1, 1) + 1
              INDX  = NJG(1, 1)
            ELSE
              DO K = 1, 3
                V6(K) = PAR(80 + K) * JGR(K)
              END DO
              IF (SQRT (GEN006 (V6, AA, V6)) > PAR(84)) GO TO 10
              NJG(1, 2) = NJG(1, 2) + 1
              INDX      = NJG(1, 2)
            END IF
            IND3 = INDX * 3
            IF (IND3 + 3 > 2 * NP23) THEN
              WRITE (LU6, 99999, IOSTAT = IOST)
              IER = 1
              RETURN
            END IF
C * STORE GRIDPOINT WITHIN PROBE SPHERE
            DO K = 1, 3
              JNSX(IND3 + K) = JGR(K)
            END DO
            GO TO 10
          END IF
        END IF
      END DO
      RETURN
99999 FORMAT (/, ':: Internal Problem: Request Aborted')
      END SUBROUTINE PLA120
 
      SUBROUTINE PLA121
C * EXPAND
      USE parameters
      USE files
      USE plato
      USE vscr
 
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NJ
      INTEGER :: NJI
      INTEGER :: NJ3
      INTEGER :: NGRD
      INTEGER :: IJGRL
      INTEGER :: I193L
      INTEGER :: NXYZP
      INTEGER :: NXYZI
      INTEGER :: NXYZM
      INTEGER, DIMENSION(3) :: NGPV
 
C * ANALYSE WHAT WE HAVE GOT IN TERMS OF DISCRETE CONNECTED SOLVENT VOLUMES
C * SOLVENT-VOLUME CG-S ARE STORED BELOW THE REGULAR ATOMS IN XXO
      NGPV(1) = -1000
      NGPV(2) = -1000
      NGPV(3) = -1000
      ISLA    = NSAV
C * INIT NUMBER OF SOLVENT VOLUMES
      IPR(530) = 0
C * LOOP OVER ALL GRIDPOINTS
      DO N = 1, NTGRD
C * TEST FOR GRIDPOINTS AT MORE THAN VAN DER WAALS DISTANCE : CHARACTER >
        IF (VOID(N) == GRTR) THEN
          NGRD = N
C * TEST FOR CALC SOLV MODE
          IF (IPR(189) > 0) THEN
C * INITIATE NEW SOLVENT VOLUME AND (RE)SET TEMPORARY STACK POINTERS
            NGB      = NTGRD
            NGE      = NTGRD
            ISLA     = ISLA + 1
            IPR(530) = IPR(530) + 1
C * TEST FOR XXO-ARRAY OVERFLOW
            IF (ISLA > NP1 - IPR(75)) THEN
              IF (IGBL(3) /= 1) IPR(2) = 25
              IER = 1
              RETURN
            END IF
C * GENERATE APPROPRIATE ALPHABETIC CHARACTER TO DESIGNATE THIS VOLUME
            IF (ISLA - NSAV > 26) THEN
              IF (ISLA - NSAV > NP41) THEN
                WRITE (LU6, 99999, IOSTAT = IOST)
C * ALERT _604
                CALL PLA236 (604, 2, -999.0, 1.0, ' ', ' ')
                IER = 1
                RETURN
              END IF
              CSLA = ICHAR ('Z')
            ELSE
              CSLA = ICHAR ('A') + IPR(530) - 1
            END IF
C * ZERO VOID CG-DETERMINATION AND VARIANCE COUNTERS
            IATC(ISLA) = 0
            JATC(ISLA) = 0
            DO K = 1, 3
              XXO(ISLA, K) = 0.0
              NXYZ(K, 2)   = 0
            END DO
            DO K = 1, 9
              SXYZ(K, IPR(530)) = 0.0
            END DO
            VOID(NGRD) = CSLA
          END IF
C * RECOVER GRID COORDINATES IGR(1, 2) (0:N1-1), IGR(2, 2) (0:N2-1),
C *   IGR(3, 2) (0:N3-1)
   10     M         = NGRD - 1
          IGR(1, 2) = M / N23
          IGR(3, 2) = M - IGR(1, 2) * N23
          IGR(2, 2) = IGR(3, 2) / N3
          IGR(3, 2) = IGR(3, 2) - IGR(2, 2) * N3
C * ADD TO SOLVENT VOLUME STATISTICS
          CALL PLA122 (2)
C * COMPARE NEXT WITH PREVIOUS EXPAND POINT
          DO L = 1, 3
            NGNX(L) = NXYZ(L, 2) + IGR(L, 2)
          END DO
          NJI = 1
C * + Z
          IF (NGPV(3) + 1 == NGNX(3)) THEN
            IF (NGPV(2) == NGNX(2)) THEN
              IF (NGPV(1) == NGNX(1)) NJI = 4
            END IF
C * + Y
          ELSE IF (NGPV(2) + 1 == NGNX(2)) THEN
            IF (NGPV(1) == NGNX(1)) THEN
              IF (NGPV(3) == NGNX(3)) NJI = 3
            END IF
C * + X
          ELSE IF (NGPV(1) + 1 == NGNX(1)) THEN
            IF (NGPV(2) == NGNX(2)) THEN
              IF (NGPV(3) == NGNX(3)) NJI = 2
            END IF
          END IF
          IF (NJI == 1) THEN
            NJ3 = - 3
            NJB = 1
            NJE = NJGR
          ELSE
            NJ3 = NJG(NJI - 1, 2) * 3 - 3
            NJB = NJG(NJI - 1, 2) + 1
            NJE = NJG(NJI    , 2)
          END IF
          DO L = 1, 3
            NGPV(L) = NGNX(L)
          END DO
C * GRID SEARCH AROUND POINT (WITHIN PAR(84) Angstrom FROM BASE-POINT
          DO NJ = NJB, NJE
            NJ3 = NJ3 + 3
            M   = 1
            DO L = 1, 3
              I193L      = IPR(193 + L)
              NXYZ(L, 1) = NXYZ(L, 2)
              IJGRL      = IGR(L, 2) + JNSX(NJ3 + L)
C * BRING IJGRL - GRIDPOINT IN UNIT BOX RANGE (REGISTER SHIFTS)
   20         IF (IJGRL < 0) THEN
                IJGRL      = IJGRL      + I193L
                NXYZ(L, 1) = NXYZ(L, 1) - I193L
                GO TO 20
              ELSE
   30           IF (IJGRL >= I193L) THEN
                  IJGRL      = IJGRL   - I193L
                  NXYZ(L, 1) = NXYZ(L, 1) + I193L
                  GO TO 30
                END IF
              END IF
C * ACCUMULATE GRIDPOINT ADDRESS (IN UNITCELL RANGE)
              M         = M + IJGRL * KGR(L)
              IGR(L, 1) = IJGRL
            END DO
C * TEST FOR CHARACTERS . AND > ( = PREVIOUSLY TAKEN CARE OF GRIDPOINTS)
C * TEST FOR ZERO, BLANK AND DOT
            IF (VOID(M) < GRTR) THEN
              IF (VOID(M) /= DOT) THEN
C * TEST FOR VOID-MODE
                IF (IPR(189) == 1) THEN
C * SET CHARACTER DOT
                  VOID(M) = DOT
                ELSE
                  VOID(M) = CSLA
                END IF
C * ADD TO SOLVENT VOLUME STATISTICS
                CALL PLA122 (1)
              END IF
            ELSE IF (VOID(M) == GRTR) THEN
C * TEST FOR SOLV MODE
              IF (IPR(189) > 0) THEN
C * OVERFLOW CHECK
                IF (NGE + 2 > NVDR) THEN
C * TRY TO SHIFT BACK TO MAKE SPACE
                  IF (NGB > NTGRD) THEN
                    I = NTGRD
                    J = NGB
                    DO WHILE (J < NGE)
                      I           = I + 2
                      VOID(I - 1) = VOID(J + 1)
                      VOID(I)     = VOID(J + 2)
                      J           = J + 2
                    END DO
                    NGB = NTGRD
                    NGE = I
                  END IF
                  IPR(214) = IPR(214) - 1
                  IER = -1
                  RETURN
                END IF
                NGE = NGE + 2
C * TEMPORARILY STORE THIS GRIDPOINT ON A STACK
                NXYZP = 555
                NXYZM = 100
                DO I = 1, 3
                  NXYZP = NXYZP
     1                  + NXYZ(I, 1) * NXYZM / IPR(193 + I)
                  NXYZM = NXYZM / 10
                END DO
                VOID(NGE - 1) = NXYZP
                VOID(NGE)     = M
C * MARK VOLUME
                VOID(M)       = CSLA
              END IF
            END IF
          END DO
C * TEST FOR CALC SOLV MODE
          IF (IPR(189) > 0) THEN
C * GET NEXT 'GRTR' GRIDPOINT FROM BOTTOM OF STACK
            IF (NGE > NGB) THEN
              NGB   = NGB + 2
              NXYZP = NINT (VOID(NGB - 1))
              NXYZM = 100
              DO I = 1, 3
                NXYZI      = NXYZP / NXYZM
                NXYZ(I, 2) = (NXYZI - 5) * IPR(193 + I)
                NXYZP      = NXYZP - NXYZI * NXYZM
                NXYZM      = NXYZM / 10
              END DO
              NGRD = NINT (VOID(NGB))
              GO TO 10
            END IF
          END IF
        END IF
      END DO
      RETURN
99999 FORMAT ('Too Many Voids')
      END SUBROUTINE PLA121
 
      SUBROUTINE PLA122 (NADD)
C * OHASHI/SOLV VOLUME STATISTICS
      USE files
      USE parameters
      USE plato
      USE vscr
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: ISL
      INTEGER :: IJG
      INTEGER :: ISLB
      INTEGER :: NADD
      INTEGER, DIMENSION(3) :: IJGRD
      REAL, DIMENSION(3) :: VO
      REAL, DIMENSION(3) :: VG
C * NADD = 1 - OHASHI
C * NADD = 2 - SOLV
C * SOLVENT GRID-POINT COUNTER
      IPR(188) = IPR(188) + 1
C * TEST FOR CALC SOLV MODE
      IF (IPR(189) > 0) THEN
C * GET CURRENT VOID NUMBER
        ISL        = IPR(530)
        ISLB       = IPR(39) + ISL + 1
        JATC(ISLB) = JATC(ISLB) + 1
        IF (NADD == 2) IATC(ISLB) = IATC(ISLB) + 1
C * GET VOLUME CODE
        IATP(ISLB) = IATP(ISLB) + 1
C * GET FRACTIONAL COORDINATES OF GRID POINT
        DO I = 1, 3
          J            = NXYZ(I, NADD) + IGR(I, NADD)
          VG(I)        = PAR(80 + I)  * J
          XXO(ISLB, I) = XXO(ISLB, I) + VG(I)
C * BRING GRID POINTS IN 0-1 RANGE FOR SQUEEZE
          IF (IPR(326) == 1) THEN
            IJG = MOD (J, IPR(193 + I))
            IF (IJG < 0) IJG = IJG + IPR(193 + I)
            IJGRD(I) = IJG
          ELSE
            IJGRD(I) = J
          END IF
        END DO
C * TRANSFORM TO ORTHOGONAL GRID POINT COORDINATES
        VO(1) = OR11 * VG(1) + OR12 * VG(2) + OR13 * VG(3)
        VO(2) =                OR22 * VG(2) + OR23 * VG(3)
        VO(3) =                               OR33 * VG(3)
C * ACCUMULATE DATA FOR FIRST AND SECOND MOMENT CALCULATIONS
        SXYZ(1, ISL) = SXYZ(1, ISL) + VO(1)
        SXYZ(2, ISL) = SXYZ(2, ISL) + VO(2)
        SXYZ(3, ISL) = SXYZ(3, ISL) + VO(3)
        SXYZ(4, ISL) = SXYZ(4, ISL) + VO(1)**2
        SXYZ(5, ISL) = SXYZ(5, ISL) + VO(2)**2
        SXYZ(6, ISL) = SXYZ(6, ISL) + VO(3)**2
        SXYZ(7, ISL) = SXYZ(7, ISL) + VO(1) * VO(2)
        SXYZ(8, ISL) = SXYZ(8, ISL) + VO(1) * VO(3)
        SXYZ(9, ISL) = SXYZ(9, ISL) + VO(2) * VO(3)
C * WRITE 'SAV'-FILE (SOLV, SQUEEZE=1, PLOT=2, F3D=3, SAV= -1)
        IF (IPR(326) /= 0) WRITE (LU15) IJGRD, ISL, NADD, VO
      END IF
      RETURN
      END SUBROUTINE PLA122
 
      SUBROUTINE PLA123
C * SOLVENT ACCESSIBLE VOLUME DISPLAY
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE vscr
      USE sgxyz
      IMPLICIT NONE
      INTEGER, PARAMETER :: NP81 = 100000
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NJ
      INTEGER :: I0
      INTEGER :: J0
      INTEGER :: N0
      INTEGER :: IB
      INTEGER :: IE
      INTEGER :: MN
      INTEGER :: MB
      INTEGER :: NB
      INTEGER :: NF
      INTEGER :: NI
      INTEGER :: NL
      INTEGER :: NP
      INTEGER :: NS
      INTEGER :: NV
      INTEGER :: NP0
      INTEGER :: NLA
      INTEGER :: NLB
      INTEGER :: NLC
      INTEGER :: NVL
      INTEGER :: NF0
      INTEGER :: NBJ
      INTEGER :: NBK
      INTEGER :: MBJ
      INTEGER :: MBK
      INTEGER :: IP1
      INTEGER :: IP2
      INTEGER :: IP3
      INTEGER :: NAT
      INTEGER :: NO1
      INTEGER :: NO2
      INTEGER :: NOF
      INTEGER :: NRES
      INTEGER :: NOFF
      INTEGER :: NLAB
      INTEGER :: NADD
      INTEGER :: IENR
      INTEGER :: IDET
      INTEGER :: IADR
      INTEGER :: INDX1
      INTEGER :: INDX2
      INTEGER :: INDX3
      INTEGER :: NBOND
      INTEGER :: IRESI
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      INTEGER :: ISTER
      INTEGER, DIMENSION(3)     :: ISH
      INTEGER, DIMENSION(3)     :: IMX
      INTEGER, DIMENSION(3)     :: IGMN
      INTEGER, DIMENSION(3)     :: IGMX
      INTEGER, DIMENSION(2, 12) :: IUNCL = RESHAPE ((/1, 2, 1, 3, 1, 5,
     13, 4, 2, 4, 2, 6, 5, 6, 4, 8, 7, 8, 3, 7, 6, 8, 5, 7/), (/2, 12/))
      REAL :: X
      REAL :: ANG
      REAL :: CL1
      REAL :: CL2
      REAL :: HRS
      REAL :: SHX
      REAL :: SHY
      REAL :: V61
      REAL :: V81
      REAL :: DXYZ
      REAL :: YANK
      REAL :: XLNG
      REAL :: VRTH
      REAL :: HRSH
      REAL :: COL1
      REAL :: COL2
      REAL :: DIST
      REAL :: DISTI
      REAL :: SCHAAL
      REAL :: DUMMY
      REAL :: DISTMX
      REAL, DIMENSION(3) :: V0
      REAL, DIMENSION(3) :: XMN
      REAL, DIMENSION(3) :: XMX
      INTEGER, ALLOCATABLE, DIMENSION(:,:) :: MBOND
      ALLOCATE (MBOND(2, NP81))
C * DEFAULT SETTINGS
C * STEREO ON
      IPR(116) = 1
C * DISPLAY ALL RESIDUES
      IPR(140) = 0
C * RMAT-DEFAULT
      IPR(526) = 0
      INDX3    = 3
      INDX2    = 2
      INDX1    = 1
C * UNIT CELL ON
      IPR(527) = 1
C * SHOW MOL ON
      IPR(528) = 1
C * OHASHI-VOL OFF
      IPR(529) = 0
C * R/G- STEREO
      IPR(533) = 1
C * DOTS DEFAULT
      IPR(534) = 1
C * ATOM LABELS OFF
      IGBL(75) = 0
      NAT      = IPR(39)
      NRES     = IPR(75)
C * INTERACTIVE I/O LOOP
      DO
C * WHAT NEXT ?
        CALL PLA012 (1, 1)
C * CHECK FOR BLACK TO WHITE BACKGROUND
        IF (IGGT(1:3) == 'REV') THEN
          IGBL(68) = MOD (IGBL(68) + 1, 2)
          CALL GGIP (-999.0, FLOAT (IGBL(68)), IGBL(62) * 0.25, 9)
        END IF
        IF (IGGT(1:4) == 'EXIT' .OR. IGGT(1:1) == 'N') RETURN
        IF (LRET == 1) THEN
        ELSE IF (LRET == 3) THEN
          IPR(526) = -1
        ELSE IF (LRET == 4) THEN
          GO TO 20
        ELSE
          IPR(526) = -1
        END IF
C * SETUP RMAT FROM ROTATIONS
C * INCREMENTAL XROT, YROT, ZROT
        IF (IPR(526) == -1) THEN
          DUMMY = PAR(389) / RGBL(6)
          CALL GEN051 (1, RMAT, DUMMY, IPR(479))
          IPR(526) = 0
C * TAKE CURRENT MATRIX
        ELSE IF (IPR(526) == 0) THEN
C * GENERATE UNIT MATRIX
          CALL GEN021 (RMAT, 1.0)
          DO I = 1, 3
            X = - RGBL(27 + I) / RGBL(6)
            L = I
            CALL GEN051 (0, RMAT, X, L)
          END DO
C * VIEW XO
        ELSE IF (IPR(526) == 1) THEN
          CALL GEN043 (2, RMAT,  90.0 / RGBL(6))
          INDX3 = 1
          INDX2 = 2
          INDX1 = 3
C * VIEW YO
        ELSE IF (IPR(526) == 2) THEN
          CALL GEN043 (1, RMAT, -90.0 / RGBL(6))
          INDX3 = 2
          INDX2 = 1
          INDX1 = 3
C * VIEW ZO
        ELSE IF (IPR(526) == 3) THEN
          CALL GEN043 (1, RMAT,   0.0 / RGBL(6))
          INDX3 = 3
          INDX2 = 2
          INDX1 = 1
        ELSE
          GO TO 10
        END IF
        CALL GEN096 (RMAT, IROTX, IROTY, IROTZ, IDET, V6, YANK, QM)
        RGBL(28) = IROTX
        RGBL(29) = IROTY
        RGBL(30) = IROTZ
        IPR(526) = 4
   10   ANG = IPR(116) * 3.0 / RGBL(6)
        CALL GEN043 (2, ROTM1, - ANG)
        CALL GEN043 (2, ROTM2, + ANG)
   20   CALL GGIP (HORS, VERT, 0.0, 1)
        ISTER = IPR(533)
        HRS   = HORS / ISTER
        CALL PLA110 (HORS, VERT, 0)
        DO I = 1, 3
          IGMN(I) =  999
          IGMX(I) = -999
          XMN(I)  =  999.0
          XMX(I)  = -999.0
        END DO
        NOFF  = 0
        NBOND = 0
        NP    = 0
C * UNITCELL OUTLINE
        IF (IPR(527) == 1) THEN
          DO I = 1, 2
            V3(1) = I - 1
            DO J = 1, 2
              V3(2) = J - 1
              DO K = 1, 2
                V3(3) = K - 1
                CALL GEN002 (1, OR, V3, V2, XLNG)
                VOID(NOFF + 1) = - (V3(1) * 4 + V3(2) * 2 + V3(3))
                DO M = 1, 3
                  XMN(M) = MIN (XMN(M), V2(M))
                  XMX(M) = MAX (XMX(M), V2(M))
                  VOID(NOFF + 1 + M) = V2(M)
                END DO
                NP   = NP + 1
                NOFF = NOFF + 7
              END DO
            END DO
          END DO
          NP0 = NP
C * INCLUDE UNITCELL 'BONDS'
          DO I = 1, 2
            DO J = 1, 12
              MBOND(I, J) = IUNCL(I, J)
            END DO
          END DO
          NBOND = 12
        END IF
C * LOAD ATOMIC COORDINATES
        IF (IPR(528) == 1) THEN
          DO K = 1, NRES
            IF (IPR(140) == 0 .OR. K == IPR(140)) THEN
C * GET CENTER-OF-GRAVITY (CG)
              CALL GEN074 (V5, 1, 3, 0.0)
              N = 0
              DO I = 1, NAT
                CALL GEN048 (-6, IFG(1, I), 9, IRESI)
                IF (IRESI == K) THEN
                  N = N + 1
                  DO J = 1, 3
                    V5(J) = V5(J) + XXO(I, J)
                  END DO
                END IF
              END DO
              DO J = 1, 3
                V5(J) = V5(J) / N
              END DO
              IF (IPR(537) == 1) THEN
                NS = NSYM
              ELSE
                NS = 1
              END IF
              DO N = 1, NS
                DO I = 1, 3
                  SGY(I + 3) = 0.0
                  SGY(I)     = V5(I)
                END DO
                CALL SGSM (3, IDM, SGY, N, LU6, IERR)
                DO I = 1, 3
                  SGY(I + 3) =  - (INT (SGY(6 + I) + 5.0) - 5)
                END DO
                DO I = 1, NAT
                  CALL GEN048 (-6, IFG(1, I), 9, IRESI)
                  IF (IRESI == K) THEN
                    DO J = 1, 3
                      SGY(J) = XXO(I, J)
                    END DO
                    CALL SGSM (3, IDM, SGY, N, LU6, IERR)
                    V2(1) = OR11 * SGY(7) + OR12 * SGY(8)
     1                    + OR13 * SGY(9)
                    V2(2) = OR22 * SGY(8) + OR23 * SGY(9)
                    V2(3) = OR33 * SGY(9)
                    DO J = 1, 3
                      XMN(J) = MIN (XMN(J), V2(J))
                      XMX(J) = MAX (XMX(J), V2(J))
                      VOID(NOFF + 1 + J) = V2(J)
                    END DO
                    VOID(NOFF + 1) = I
                    DXYZ = 1.0
                    IF (NP > NP0 .AND. N > 1) THEN
                      DO L = NP0 + 1, NP
                        M = (L - 1) * 7 + 1
                       DXYZ = ABS (VOID(M + 1) - V2(1)) +
     1                         ABS (VOID(M + 2) - V2(2)) +
     2                         ABS (VOID(M + 3) - V2(3))
                        IF (DXYZ < 0.001) EXIT
                      END DO
                    END IF
                    IF (DXYZ > 0.001) THEN
                      NP   = NP   + 1
                      NOFF = NOFF + 7
                    END IF
                  END IF
                END DO
              END DO
            END IF
          END DO
C * LOAD BONDS
          NOF = IPR(527) * 8
          DO I = NOF + 1, NP - 1
            NI = NINT (VOID(I * 7 - 6))
            DO K = 1, 3
              V2(K) = VOID(I * 7 - 6 + K)
            END DO
            CALL GEN048 (-4, IFG(1, NI), 15, NO1)
            DISTI = REL(IEN(NO1 + 1)) + 0.4
            DO J = I + 1, NP
              NJ = NINT (VOID(J * 7 - 6))
              DO K = 1, 3
                V3(K) = VOID(J * 7 - 6 + K)
              END DO
              CALL GEN048 (-4, IFG(1, NJ), 15, NO2)
              DISTMX = DISTI + REL(IEN(NO2 + 1))
              DIST   = 0
              DO K = 1, 3
                DIST = DIST + (V2(K) - V3(K))**2
              END DO
              IF (SQRT (DIST) < DISTMX) THEN
                IF (NBOND < NP81) THEN
                  NBOND           = NBOND + 1
                  MBOND(1, NBOND) = I
                  MBOND(2, NBOND) = J
                ELSE
                  GO TO 40
                END IF
              END IF
            END DO
          END DO
        END IF
C * DISPLAY CG & EIGENVECTORS
        IF (IPR(598) /= 0) THEN
C * UNIT MATRIX
          CALL GEN021 (QQ, 1.0)
C * DETERMINE ALL OR SELECTED VOID(S)
          IF (IPR(531) == 0) THEN
            IB = 1
            IE = IPR(530)
          ELSE
            IB = IPR(531)
            IE = IPR(531)
          END IF
          DO I = IB, IE
            DO J = 1, 3
              V4(J) = SXYZ(9 + J, I)
              V5(J) = SXYZ(J    , I)
              V6(J) = SXYZ(3 + J, I)
              V8(J) = SXYZ(6 + J, I)
            END DO
            CALL GEN002 (1, OR, V4, V4, XLNG)
            CALL GEN002 (2, QQ, V5, V5, XLNG)
            CALL GEN002 (2, QQ, V6, V6, XLNG)
            CALL GEN002 (2, QQ, V8, V8, XLNG)
C * LOAD PSEUDO ATOMS FOR DIRECTION/SIZE DISPLAY
            DO J = 1, 3
              VOID(NOFF +  1 + J) = V4(J)
              VOID(NOFF +  8 + J) = V4(J) + V5(J) * SXYZ(13, I)
              VOID(NOFF + 15 + J) = V4(J) + V6(J) * SXYZ(14, I)
              VOID(NOFF + 22 + J) = V4(J) + V8(J) * SXYZ(15, I)
            END DO
            NOFF = NOFF + 28
C * ADD DIRECTIONS AS PSEUDO-BONDS
            IF (NBOND - 2 < NP81) THEN
              DO J = 1, 3
                NBOND          = NBOND + 1
                MBOND(1, NBOND) = NP + 1
                MBOND(2, NBOND) = NP + J + 1
              END DO
            ELSE
              GO TO 40
            END IF
            NP = NP   + 4
          END DO
        END IF
C * READ SOLVENT DATA FOR SCALING
        NVL = IPR(531)
        NF  = NOFF
        REWIND (UNIT = LU15, IOSTAT = IOST)
        DO
          READ (LU15, IOSTAT = IOST) (IGR(I, 2), I = 1, 3), NV, NADD
          IF (IOST /= 0) EXIT
          IF (NVL == 0 .OR. NV == NVL) THEN
C * TEST FOR NO OHASHI SURFACE DISPLAY
            IF (IPR(529) == 0 .OR. NADD == 2) THEN
              DO I = 1, 3
                IF (IPR(535) /= 0) THEN
                  IF (IGR(I, 2) < 0) IGR(I, 2) =
     1              IGR(I, 2) + IPR(193 + I)
                END IF
                V3(I) = FLOAT(IGR(I, 2)) / IPR(193 + I)
              END DO
              V2(1) = OR11 * V3(1) + OR12 * V3(2) + OR13 * V3(3)
              V2(2) =                OR22 * V3(2) + OR23 * V3(3)
              V2(3) =                               OR33 * V3(3)
              NP    = NP + 1
              NOFF  = NOFF + 7
              IF (NOFF > NVDR) GO TO 30
              DO I = 1, 3
                IGMN(I)            = MIN (IGMN(I), IGR(I, 2))
                IGMX(I)            = MAX (IGMX(I), IGR(I, 2))
                XMN(I)             = MIN (XMN(I),  V2(I))
                XMX(I)             = MAX (XMX(I),  V2(I))
                VOID(NOFF - 6 + I) = V2(I)
                VOID(NOFF - 3 + I) = IGR(I, 2)
              END DO
            END IF
          END IF
        END DO
C * ADD ONE BORDER AND SHIFT TO MAKE ALL GRIDPOINTS >= 0
        DO I = 1, 3
          ISH(I) = - IGMN(I) + 1
          IMX(I) =   IGMX(I) + ISH(I) + 1
          V0(I)  =   (XMN(I) + XMX(I)) / 2.0
        END DO
C * DETERMINE SCHAAL FACTOR
        CALL GEN074 (XMN, 1, 3,  999.0)
        CALL GEN074 (XMX, 1, 3, -999.0)
        DO I = 1, NP
          N = (I - 1) * 7
          DO M = 1, 3
            V4(M) = VOID(N + 1 + M) - V0(M)
          END DO
          CALL GEN002 (1, RMAT, V4, V5, XLNG)
          DO M = 1, 3
            XMN(M) = MIN (XMN(M),  V5(M))
            XMX(M) = MAX (XMX(M),  V5(M))
            VOID(N + 1 + M) = V5(M)
            VOID(N + 4 + M) = VOID(N + 4 + M) + ISH(M)
          END DO
        END DO
        SHX    = HORS / ((XMX(1) - XMN(1)) * ISTER)
        SHY    = VERT / (XMX(2) - XMN(2))
        SCHAAL = MIN (SHX, SHY) * 0.80
C * APPLY SCHAAL ON VOID, UNITCELL & ATOM COORDINATES
        DO I = 1, NP
          N = (I - 1) * 7 + 1
          DO M = 1, 2
            VOID(N + M) = SCHAAL * VOID(N + M)
          END DO
          VOID(N + 3) = SCHAAL * (VOID(N + 3) - XMX(3))
        END DO
C * GRID PACKING
        IP1 =  IMX(INDX1) + 1
        IP2 = (IMX(INDX2) + 1) * IP1
        IP3 = (IMX(INDX3) + 1) * IP2
        IB  = NOFF + 1
        IE  = NOFF + IP3 * 4
        IF (IE > NVDR) GO TO 30
        CALL GEN074 (VOID, IB, IE, 0.0)
C * RE-READ SOLVENT DATA POINTS FOR STORAGE & PLOTTING
        NF0 = NF + 7
        DO WHILE (NF0 <= NOFF)
          DO I = 1, 3
            V2(I)     = VOID(NF0 - 6 + I)
            IGR(I, 2) = NINT (VOID(NF0 - 3 + I))
          END DO
          IADR = (IGR(INDX3, 2) * IP2 + IGR(INDX2, 2) * IP1
     1         + IGR(INDX1, 2)) * 4  + NOFF
          VOID(IADR + 1) = 99.0
          VOID(IADR + 2) = V2(1)
          VOID(IADR + 3) = V2(2)
          VOID(IADR + 4) = V2(3)
          NF0            = NF0 + 7
        END DO
C * ELIMINATE 'INTRA' POINTS
        DO K = 1, IMX(INDX3) + 1
          NBK = (K - 1) * IP2
          DO J = 1, IMX(INDX2) + 1
            NBJ = (J - 1) * IP1
            DO I = 1, IMX(INDX1) + 1
              NB = (NBK + NBJ + I - 1) * 4 + 1 + NOFF
              N  = - 1
              IF (VOID(NB) > 0.0) THEN
                  MBK = (K  - 1) * IP2
                  DO J0 = 1, 3
                    MBJ = (J + J0 - 3) * IP1
                    DO I0 = 1, 3
                      MB = (MBK + MBJ + I + I0 - 3) * 4 + 1 + NOFF
                      IF (VOID(MB) /= 0.0) THEN
                        N = N + 1
                      END IF
                    END DO
                  END DO
                VOID(NB) =  N
              END IF
            END DO
          END DO
        END DO
C * PLOT SOLVENT OUTLINE
        HRSH = HORS / (2.0 * ISTER)
        VRTH = VERT / 2.0
        IF (ISTER == 1) THEN
          COL1 = 1.0 + IPR(116)
          COL2 = 3.0
        ELSE
          COL1 = 1.0
          COL2 = 1.0
        END IF
        IF ((IPR(116) == 0 .OR. IPR(533) == 2) .AND.
     1       IPR(346) == 1) THEN
C * TEST FOR OHASHI SURFACE  DISPLAY
          IF (IPR(529) == 1) THEN
            CL1 = 2
            CL2 = 2
          ELSE
            CL1 = 3
            CL2 = 3
          END IF
        ELSE
          CL1 = COL1
          CL2 = COL2
        END IF
        N0 = 8
        IF (IPR(534) == 2) THEN
          NLA = 1
          NLB = 3
          NLC = 1
        ELSE
          NLA = 2
          NLB = 2
          NLC = 0
        END IF
        CALL GGIP (HRSH, VRTH, 0.0, -3)
        DO K = 1, IMX(INDX3) + 1
          NBK = (K - 1) * IP2
          DO J = 1, IMX(INDX2) + 1
            NBJ = (J - 1) * IP1
            DO I = 1, IMX(INDX1) + 1
              NB = (NBK + NBJ + I - 1) * 4 + NOFF
              N = NINT (VOID(NB + 1))
              IF (N > 0) THEN
                IF (N < N0) THEN
                  DO L = 1, 3
                    V2(L) = VOID(NB + 1 + L)
                  END DO
                  CALL GEN002 (1, ROTM1, V2, V4, XLNG)
                  DO J0 = NLA, NLB
                    DO I0 = NLA, NLB
                      IF (ABS (J0 - 2) + ABS (I0 - 2) == NLC) THEN
                        MB = NB + ((J0 - 2) * IP1 + I0 - 2) * 4
                        M = NINT (VOID(MB + 1))
                        IF (M > 0 .AND. M < N0) THEN
                          DO L = 1, 3
                            V3(L) = VOID(MB + 1 + L)
                          END DO
                          CALL GEN002 (1, ROTM1, V3, V5, XLNG)
                          CALL GGIP (0.0, CL1, 0.0, 0)
                          CALL GGIP (V4(1), V4(2), 0.0, 3)
                          CALL GGIP (V5(1), V5(2), 0.0, 2)
                          IF (IPR(116) == 1) THEN
                            CALL GEN002 (1, ROTM2, V2, V6, XLNG)
                            CALL GEN002 (1, ROTM2, V3, V8, XLNG)
                            CALL GGIP (0.0, CL2, 0.0, 0)
                            IF (ISTER == 2) THEN
                              V61 = V6(1) + HRS
                              V81 = V8(1) + HRS
                            ELSE
                              V61 = V6(1)
                              V81 = V8(1)
                            END IF
                            CALL GGIP (V61, V6(2), 0.0, 3)
                            CALL GGIP (V81, V8(2), 0.0, 2)
                          END IF
                        END IF
                      END IF
                    END DO
                  END DO
                END IF
              END IF
            END DO
          END DO
        END DO
C * PLOT UNITCELL AND OR MOLECULE
        CALL GGIP (0.0, -2.0, 0.0, 0)
        IF (NBOND > 0) THEN
          DO I = 1, NBOND
            DO J = 1, 3
              V3(J) = VOID((MBOND(1, I) - 1) * 7 + 1 + J)
              V4(J) = VOID((MBOND(2, I) - 1) * 7 + 1 + J)
            END DO
            CALL GEN002 (1, ROTM1, V3, V5, XLNG)
            CALL GEN002 (1, ROTM1, V4, V6, XLNG)
            CALL GGIP (0.0, COL1, 0.0, 0)
            CALL GGIP (V5(1), V5(2), 0.0, 3)
            CALL GGIP (V6(1), V6(2), 0.0, 2)
            IF (IPR(116) == 1) THEN
              CALL GEN002 (1, ROTM2, V3, V5, XLNG)
              CALL GEN002 (1, ROTM2, V4, V6, XLNG)
              IF (ISTER == 2) THEN
                V5(1) = V5(1) + HRS
                V6(1) = V6(1) + HRS
              ELSE
                CALL GGIP (0.0, COL2, 0.0, 0)
              END IF
              CALL GGIP (V5(1), V5(2), 0.0, 3)
              CALL GGIP (V6(1), V6(2), 0.0, 2)
            END IF
          END DO
C * LABELS
          NLAB = IPR(527) * 8 + IGBL(75) * NAT
          IF (NLAB > 0) THEN
            DO I = 1, NLAB
              NQ1 = ' '
              NL = NINT (VOID((I - 1) * 7 + 1))
              DO J = 1, 3
                V2(J) = VOID((I - 1) * 7 + J + 1)
              END DO
              CALL GEN002 (1, ROTM1, V2, V3, XLNG)
              CALL GEN002 (1, ROTM2, V2, V4, XLNG)
              IENR = 0
              IF (NL <= 0) THEN
                IF (IPR(532) /= 0) THEN
                  IF (NL == 0) THEN
                    NQ1 = 'O'
                  ELSE IF (NL == -4) THEN
                    NQ1 = 'a'
                  ELSE IF (NL == -2) THEN
                    NQ1 = 'b'
                  ELSE IF (NL == -1) THEN
                    NQ1 = 'c'
                  END IF
                END IF
              ELSE
                CALL PLA047 (LABA(NL), NQ1, MN, IENR, 0, IGBL(55),
     1                       0, 0)
              END IF
              IF (IENR /= 1 .OR. IPR(232) == 1) THEN
              CALL PLA439 (0.0, NQ1, 5, PAR(349), NINT (COL1), 2,
     1                V3(1) + 0.4, V3(2) - 0.4)
                IF (IPR(116) == 1) THEN
                  IF (ISTER == 2) V4(1) = V4(1) + HRS
                  CALL PLA439 (0.0, NQ1, 5, PAR(349), NINT (COL2), 2,
     1                V4(1) + 0.4, V4(2) - 0.4)
                END IF
              END IF
            END DO
          END IF
        END IF
      END DO
      DEALLOCATE (MBOND)
      RETURN
C * CALL EXIT/STOP
   30 CALL GEN127
     1 ('VOID Array too small; raise NVDR parameter for larger version')
      RETURN
   40 CALL GEN127 ('Bond Overflow: NBOND >= NP81 (Raise par. value)')
      RETURN
      END SUBROUTINE PLA123
 
      MODULE squeeze
      SAVE
      INTEGER :: HMAX
      INTEGER :: KMAX
      INTEGER :: LMAX
      INTEGER :: NREF
      INTEGER :: NREFS
      REAL :: RF
      REAL :: RFS
      REAL :: DRHOMN
      REAL :: DRHOMX
      REAL, DIMENSION(20, 9) :: STAT
      CHARACTER(len=62), DIMENSION(3)  :: TXT1
      CHARACTER(len=62), DIMENSION(30) :: TXT = (/
     1 '==============================================================',
     2 'SQUEEZE produces and analyzes a phase enhanced difference map ',
     3 'using the files name.ins & name.hkl. Density found in solvent ',
     4 'accessible voids is back-fourier transformed into A(solv) &   ',
     5 'B(solv) contributions to F(calc) to be used for subsequent    ',
     6 'L.S. refinement. No model refinement is done by PLATON/SQUEEZE',
     7 '==============================================================',
     8 'HOW TO PROCEED with L.S. refinement after running SQUEEZE:    ',
     9 '==============================================================',
     * 'SHELXL201n: Continue refinement in the presence of the three  ',
     1 'files name_sq.ins, name_sq.hkl & name_sq.fab                  ',
     2 'Additional info on name_sq.sqf , name_sq.sqz & name_sq.lis    ',
     3 '==============================================================',
     4 'Citation: Spek, A.L. (2015). Acta Cryst. C71, 9-18.           ',
     5 '==============================================================',
     6 'SHELXL97 (Deprecated): Refine in the presence of the files    ',
     7 'name_sqd.ins, name_sqd.hkl, name_sqd.sqz & name_sqd.sqf:      ',
     8 '-The file name_sqd.hkl contains solvent free reflection data. ',
     9 ' (Original I(obs), A(solv) and B(solv) are beyond column 80)  ',
     * '-Use this name_sqd.hkl file to continue (SHELXL97) refinement ',
     1 ' with the solvent free name_sqd.ins. (A copy of the original  ',
     2 ' name.res file).                                              ',
     3 '-After SHELXL(97) L.S.-convergence, run PLATON again with the ',
     4 ' instruction "CALC FCF-SQ" using the new name_sqd.ins and     ',
     5 ' name_sqd.hkl files in order to produce a proper final        ',
     6 ' FoFc-CIF on a file named name_sqd_pl.fcf.                    ',
     7 '-The name_sqd.sqf file produced by PLATON (detailing the      ',
     8 ' SQUEEZE results) is appended to name_sqd.cif (created by     ',
     9 ' SHELXL(97)) to generate a final name_sqd_pl.cif file.        ',
     * '-Optionally inspect the improved peak list on name_sqd.sqz    '
     1 /)
      END MODULE squeeze
 
      MODULE reflex
      SAVE
      INTEGER, PARAMETER :: NP60 = 1000
      INTEGER, PARAMETER :: NP69 = 16
      INTEGER :: MHK
      INTEGER :: MPH
      INTEGER :: IND1
      INTEGER :: IND2
      INTEGER :: IND3
      INTEGER :: NSYM
      INTEGER :: NSYMH
      INTEGER :: ICNTR
      INTEGER, DIMENSION(5, 48)   :: IHKLS
      INTEGER, DIMENSION(4, NP60) :: MISSING
      REAL, DIMENSION(48) :: PHIS
      END MODULE reflex
 
      SUBROUTINE PLA125
C * SQUEEZE: HANDLE (DISORDERED) SOLVENT CONTRIBUTION TO STRUCTURE FACTORS
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE reflex
      USE squeeze
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: NM
      INTEGER :: NV
      INTEGER :: LOC
      INTEGER :: IR3D
      INTEGER :: ITOP
      INTEGER :: ILOC
      INTEGER :: IBOT
      INTEGER :: IADR
      INTEGER :: NVOID
      INTEGER :: NGRID
      INTEGER :: NLOOP
      INTEGER :: NLOPM
      INTEGER :: NLPMX
      INTEGER :: NREFA
      INTEGER :: NREFB
      REAL :: FC
      REAL :: FO
      REAL :: ST
      REAL :: VA
      REAL :: FCS
      REAL :: EPS
      REAL :: AVA
      REAL :: AVB
      REAL :: SIGF
      REAL :: SMDL
      REAL :: SMFO
      REAL :: F000
      REAL :: AVOL
      REAL :: ACAL
      REAL :: BCAL
      REAL :: BVOL
      REAL :: VVOL
      REAL :: YUNK
      REAL :: ACALS
      REAL :: BCALS
      REAL :: DELTA
      REAL :: FS000
      REAL :: FSOLD
      REAL :: SUMDL
      REAL :: SUMFO
      REAL :: SUMFC
      REAL :: RFSOD
      REAL :: DELRHO
C * PLA125 (MAIN SQUEEZE ROUTINE)
C *       - PLA292 (FILE OPEN .sqz FILE WITH DIFF. DENS. PEAKS)
C *       - PLA024 (GET CONNECTED COORDINATE SET)
C *       - PLA023 (LOAD AND EXPAND COORDINATE SET)
C *       - PLA133 (GET NUMBER OF REFLNS,H-,K-,LMAX)
C *               - PLA134 (HKL-READ /TRANS)
C *                       - PLA132 (GET REFL. DATA - FCF OR HKL)
C *       - PLA126 (REMAP GRID)
C *       - PLA130 (STORE REFLECTION DATA)
C *               - PLA136
C *               - PLA137
C *       - PLA142
C *               - PLA140
C *                       - PLA141
C *               - PLA143
C *       - PLA127 (GENERATE CIF-STRUCTURED VOID INFO)
C *               - PLA129
C *                       - PLA128
C *               - PLA139
C *
C * REFLECTION DATA STORAGE (INCLUDING '3D' POINTER ARRAY TO DATA)
C *
C * LAYOUT VOID ARRAY
C *
C *         NVDR I - TOP REFLECTION DATA POINTER ARRAY (HALF REFL. SPHERE)
C *              I
C *              I      INDEX TO THE DIFFERENCE MAP REFLECTION DATA STORAGE
C *              I
C *         IADR I - ADDRESS 0,0,0 Reflection Pointer
C *              I
C *              V
C *              I      (EMPTY)
C *--------------------------------------------------------------------
C *              ^
C *              I
C *         IR3D I - TOP R3D ARRAY (DENSITY MAP SECTIONS)
C *              I
C *              I      THREE R3D SECTIONS (3 * (M1 + 2) * (M2 + 2))
C *              I
C *         ITOP I - TOP FFT ARRAY
C *              I
C *              I      FFT ARRAY SIZE = NGRID * 2
C *              I
C * NREFA * NP69 I - TOP TOTAL REFLECTION DATA STORAGE
C *              I
C *              I      ENTRIES FOR MISSING REFLECTION DATA
C *              I
C * NREFB * NP69 I - TOP (SYMMETRY EXPANDED) REFLECTION DATA STORAGE
C *              I
C *              I      VOID(N +  1) - F(obs)
C *              I      VOID(N +  2) - SIG(F(obs))
C *              I      VOID(N +  3) - NON-SOLVENT ACAL
C *              I      VOID(N +  4) - NON-SOLVENT BCAL
C *              I      VOID(N +  5) - SOLVENT     ACALSOLVENT
C *              I                     (ACALS = ACAL + ACALSOLVENT)
C *              I      VOID(N +  6) - SOLVENT     BCALSOLVENT
C *              I                     (BCALS = BCAL + BCALSOLVENT)
C *              I      VOID(N +  7) - DIFF-MAP    ACAL
C *              I      VOID(N +  8) - DIFF-MAP    BCAL
C *              I      VOID(N +  9) - H
C *              I      VOID(N + 10) - K
C *              I      VOID(N + 11) - L
C *              I      VOID(N + 12) - ANOM-DISP   ACALA
C *              I      VOID(N + 13) - ANOM-DISP   ACALB
C *              I      VOID(N + 14) - SIN(THETA)/LAMBDA
C *              I      VOID(N + 15) - ASYMMETRIC REFL INFO
C *              I      VOID(N + 16) - SUM WEIGHTS AVERAGED REFLNS
C *              I
C *
C * SQUEEZE LISTING HEADER
      PAGET = 'SQUEEZE'
      CALL PLA262 (-2)
      WRITE (LU7, 99999, IOSTAT = IOST)
C * SQUEEZE GRAPHICS HEADER
      IF (IGBL(25) * IGBL(32) == 1 .AND. IGBL(3) /= 5) THEN
        IWIN = 1
        CALL GGIP (HORS, VERT, 0.0, 1)
        VRT = VERT - 0.8
        WRITE (BCD, 99988, IOSTAT = IOST)
        CALL PLA439 (0.0, BCD, 80, 0.50, 5 + IGBL(68), 2, 1.0, VRT)
        WRITE (BCD, 99990, IOSTAT = IOST)
        VRT = VERT - 2.0
        CALL PLA439 (0.0, BCD, 80, 0.30, 5 + IGBL(68), 2, 0.1, VRT)
        CALL GGIP (0.0, 0.0, 0.0, 6)
        VRT = VRT - 0.2
      ELSE
        IWIN = 0
      END IF
C * GET PREVIOUSLY DETERMINED CONNECTED COORDINATE SET
      CALL PLA024
C * LOAD AND EXPAND COORDINATE DATA TO UNIT CELL CONTENTS
C * (BUT EXCLUDING BRAVAIS CENTERING)
      CALL PLA023 (0)
C * CHECK FOR NON-ERROR RETURN  (POSITIVE = NUMBER OF ATOMS (NATO))
      IF (IPR(589) > 0) THEN
C * TOTAL NUMBER OF SYMMETRY OPERATIONS
        NSYM  = IPR(48)
C * GET NUMBER OF OPERATIONS EXCLUDING INVERSION AND BRAVAIS CENTERING
        NSYMH = IPR(255)
C * GET CENTER OF SYMMETRY NUMBER  [(1/2) ACENT/CENT]
        ICNTR = IPR(257)
        HMAX  = -999
        KMAX  = -999
        LMAX  = -999
        NREF  = 0
        NREFA = 0
        NREFB = 0
C * GET NR OF REFLECTIONS (SHELX(L) HKLF4 FORMAT OR FCF & HMAX, KMAX, LMAX
C * TWINNED DATA SHOULD HAVE BEEN DETWINNED USING A SHELXL/LIST 8 SHELXL JOB
C * REFLECTIONS ARE WRITTEN TO FILE LU27
        CALL PLA133 (NREF, HMAX, KMAX, LMAX)
C * CHECK FOR ERROR RETURN
        IF (IPR(2) <= 0) THEN
C * TRANSFORM SOLV GRID POINTS TO FFT SOLV GRID POINTS
          CALL PLA126
C * FFT GRID
          M1    = IPR(395)
          M2    = IPR(396)
          M3    = IPR(397)
          NGRID = M1 * M2 * M3
C * STORE REFLECTION DATA
          CALL PLA130 (HMAX, KMAX, LMAX, NREF, IADR, NREFA, NREFB)
C * CHECK FOR ERROR RETURN (NO SUITABLE REFLECTIONS)
          IF (NREFB > 0) THEN
C * OPEN UNIT #2 FOR SQUEEZED DIFFERENCE MAP PEAK LIST (_sq.sqz or _sqd.sqz)
            IGBL(31) = 10
            CALL PLA292
C * LOOP TO CONVERGENCE (MAXLOOP = IPR(142))
            NLPMX = IPR(142)
C * SET MODIFYABLE LOOP-MAXIMUM
            NLOPM = NLPMX
            FS000 = 0.0
            FSOLD = 0.0
            RFSOD = 999.0
            DO NLOOP = 1, NLPMX
C * EPS - FUDGE
              IF (NLOOP == 1) THEN
                EPS = 0.0
              ELSE IF (NLOOP == 2) THEN
                EPS = 3.0 - IPR(257)
              ELSE
                EPS = 1.0
              END IF
C * GET Fobs/Fcalc SCALING AND R-FACTOR
              SUMFO = 0.0
              SUMFC = 0.0
              SMFO  = 0.0
              N     = 0
              DO I = 1, NREFB
                ST       = VOID(N + 14)
                PAR(572) = MAX (PAR(572), ST)
C * EXCLUDE REFLECTIONS BELOW MINIMUM SIN(THETA)/LAMBDA
                IF (ST > PAR(290)) THEN
                  FO   = VOID(N + 1)
                  ACAL = VOID(N + 3)
                  BCAL = VOID(N + 4)
                  IF (EPS > 0.0) THEN
                    ACAL = ACAL + EPS * VOID(N + 5)
                    BCAL = BCAL + EPS * VOID(N + 6)
                  END IF
                  FC    = SQRT (ACAL**2 + BCAL**2)
                  SUMFO = SUMFO + FO
                  SUMFC = SUMFC + FC
                END IF
                N = N + NP69
              END DO
              PAR(566) = SUMFC / SUMFO
C * REPORT Fo/Fc SCALING DATA
              WRITE (LU6, 99991, IOSTAT = IOST) PAR(566), PAR(290)
              CALL PLA262 (3)
              WRITE (LU7, 99991, IOSTAT = IOST) PAR(566), PAR(290)
C * GENERATE DIFFERENCE FOURIER COEFFICIENTS
              SUMFO = SUMFO * PAR(566)
              SUMDL = 0.0
              SMFO  = 0.0
              SMDL  = 0.0
              M     = 0
C * (0/1) ADD DUMMY SOLVENT CONTRIBUTION FOR MISSING REFLECTIONS
              IF (IPR(681) == 1) THEN
                NREF = NREFA
              ELSE
                NREF = NREFB
              END IF
              WRITE (LU6, 99978) NREFB, NREFA - NREFB, NREFA, NREF
              NM = 0
              N  = 0
              DO I = 1, NREF
                FO   = VOID(N + 1) * PAR(566)
                SIGF = MAX (VOID(N + 2) * PAR(566), 0.0001)
C * F-CALC WITHOUT SOLVENT CONTRIBUTION
                ACAL = VOID(N + 3)
                BCAL = VOID(N + 4)
C * SOLVENT CONTRIBUTION
                AVA  = VOID(N + 5)
                AVB  = VOID(N + 6)
                IF (NLOOP > 1) THEN
                  IF (I > NREFB) THEN
                    IF (VOID(N + 14) <= PAR(486)) THEN
C * CHECK FOR ASYMMETRIC UNIT REFLECTION
                      IF (VOID(N + 15) > 0) THEN
                        NM = NM + 1
                        IF (NM == 1) THEN
                          WRITE (LU6, 99992) PAR(486)
                          WRITE (LU7, 99992) PAR(486)
                        END IF
                        IH = NINT (VOID(N +  9))
                        IK = NINT (VOID(N + 10))
                        IL = NINT (VOID(N + 11))
                        WRITE (LU6, 99989) IH, IK, IL, AVA, AVB
                        WRITE (LU7, 99989) IH, IK, IL, AVA, AVB
                      END IF
                    END IF
                  END IF
                END IF
C * F-CALC WITH SOLVENT CONTRIBUTION
                IF (EPS > 0.0) THEN
                  ACALS = ACAL + EPS * AVA
                  BCALS = BCAL + EPS * AVB
                ELSE
                  ACALS = ACAL
                  BCALS = BCAL
                END IF
                IF (I <= NREFB) THEN
                  FCS         = SQRT (ACALS**2 + BCALS**2)
                  DELTA       = ABS (FO - FCS)
                  VOID(N + 7) = FO * ACALS / FCS - ACAL
                  VOID(N + 8) = FO * BCALS / FCS - BCAL
                ELSE
                  VOID(N + 7) = AVA
                  VOID(N + 8) = AVB
                END IF
C * ZERO SOLVENT AREA CONTRIBUTION
                IF (NLOOP < NLOPM) THEN
                  VOID(N + 5) = 0.0
                  VOID(N + 6) = 0.0
                END IF
                IF (I <= NREFB) THEN
                  SUMDL = SUMDL + DELTA
                  IF (FO > 4.0 * SIGF) THEN
                    SMFO = SMFO + FO
                    SMDL = SMDL + DELTA
                    M    = M    + 1
                  END IF
                END IF
                N = N + NP69
              END DO
              RF    = SUMDL / SUMFO
              RFS   = SMDL  / SMFO
              NREFS = M
              WRITE (BCD, 99993, IOSTAT = IOST) NLOOP, RF, NREF, RFS,
     1          NREFS
              WRITE (LU6, 99986, IOSTAT = IOST) BCD
              CALL PLA262 (5)
              WRITE (LU7, 99986, IOSTAT = IOST) BCD
              IF (IWIN == 1) THEN
                WRITE (BCD, 99980, IOSTAT = IOST)
     1            NLOOP, RF, NREF, RFS, M, NINT (FS000)
                VRT = VRT - 0.50
                CALL PLA439 (0.0, BCD, 80, 0.35, 1, 2, 0.1, VRT)
                CALL GGIP (0.0, 0.0, 0.0, 6)
              END IF
              IF (NLOOP < NLOPM) THEN
                CALL GEN108 (LU15, 0)
                DO I = 1, 2
                  DO J = 1, NP41
                    SXYZ(I, J) = 0.0
                  END DO
                END DO
                NV = 0
C * FFT
                IBOT = NREFA * NP69
                ITOP = IBOT + NGRID * 2
C * CHECK FOR SCRATCH OVERRUN (FFT + R3D)
                IR3D = ITOP + 3 * (M1 + 2) * (M2 + 2)
                IF (IR3D >= IADR) THEN
                  WRITE (LU6, 99996, IOSTAT = IOST) 2, CHAR(IPR(223))
                  WRITE (LU7, 99996, IOSTAT = IOST) 2, CHAR(IPR(223))
                  RETURN
                END IF
C * SQUEEZE MODE ? (i.e. ELECTRON COUNT OR FFT_F000
                IF (IPR(304) == 0) THEN
                  F000 = PAR(149)
                ELSE IF (IPR(304) == 1) THEN
                  F000 = PAR(539)
                END IF
C * FFT & PEAKSEARCH
                CALL PLA142 (-1, VOID(1), VOID(IBOT + 1), VOID(ITOP + 1)
     1            , NREF, F000)
C * REPORT TOTAL ELECTRON COUNT IN (FO-FC)-MAP
                IF (NLOOP > 1) THEN
                  VA = 0
                  DO I = IBOT + 1, ITOP, 2
                    VA = VA + VOID(I)
                  END DO
                  PAR(353) = VA / NGRID
                END IF
C * READ .sav FILE
                CALL GEN108 (LU9, 0)
C * GET LOCATION AND NUMBER OF VOIDMAP GRIDPOINT
                DO
                  READ (LU15, IOSTAT = IOST) ILOC, NVOID
                  IF (IOST /= 0) EXIT
                  LOC    = IBOT + ILOC
C * GET REAL-PART DIFFERENCE MAP DENSITY
                  DELRHO = VOID(LOC - 1) / NGRID
C * REMOVE DENSITY ON SOLVENT SITE
                  VOID(LOC - 1) = 0.0
                  VOID(LOC)     = 0.0
                  WRITE (LU9) LOC, DELRHO
                  SXYZ(1, NVOID) = SXYZ(1, NVOID) + 1
                  SXYZ(2, NVOID) = SXYZ(2, NVOID) + DELRHO
                  NV = MAX (NV, NVOID)
                END DO
                FS000 = 0
                WRITE (PRBUF, 99995, IOSTAT = IOST)
                WRITE (LU6, 99987, IOSTAT = IOST) PRBUF(1:80)
                CALL PLA262 (3)
                WRITE (LU7, 99987, IOSTAT = IOST) PRBUF(1:80)
                PAR(525) = 0.0
                PAR(526) = 0.0
                DO I = 1, NV
                  VVOL = SXYZ(1, I) * PAR(79)
                  AVOL = 0.0
                  BVOL = 0.0
                  YUNK = SXYZ(2, I)
                  IF (VVOL > PAR(525)) THEN
                    PAR(525) = VVOL
                    PAR(526) = YUNK
                  END IF
                  IF (YUNK > 0.0) THEN
                    FS000 = FS000 + YUNK
                    AVOL  = VVOL  / (YUNK / 8)
                    BVOL  = VVOL  / YUNK
                  END IF
                  PAR(354) = FS000
                  WRITE (PRBUF, 99984, IOSTAT = IOST)
     1              I, (SXYZ(J, I), J = 10, 12),
     2              NINT (VVOL), NINT (YUNK), BVOL, NINT (AVOL)
                  WRITE (LU6, 99981, IOSTAT = IOST) PRBUF(1:80)
                  CALL PLA262 (1)
                  WRITE (LU7, 99981, IOSTAT = IOST) PRBUF(1:80)
                END DO
                PAR(149) = FS000
                IF (NLOOP > 1) THEN
                  WRITE (LU6, 99985, IOSTAT = IOST) NINT (PAR(353))
                  CALL PLA262 (2)
                  WRITE (LU7, 99985, IOSTAT = IOST) NINT (PAR(353))
                END IF
                WRITE (TXT1(1), 99994, IOSTAT = IOST) NINT (PAR(354))
                WRITE (LU6, 99982, IOSTAT = IOST) TXT1(1)
                CALL PLA262 (2)
                WRITE (LU7, 99982, IOSTAT = IOST) TXT1(1)
C * ELECTRON COUNT OUTSIDE VOIDS
                PAR(355) = 0.0
                DO I = IBOT + 1, ITOP, 2
                  PAR(355)    = PAR(355) + VOID(I) / NGRID
                  VOID(I)     = 0.0
                  VOID(I + 1) = 0.0
                END DO
                WRITE (TXT1(1), 99998, IOSTAT = IOST) NINT (PAR(355))
                WRITE (LU6, 99982, IOSTAT = IOST) TXT1(1)
                CALL PLA262 (2)
                WRITE (LU7, 99982, IOSTAT = IOST) TXT1(1)
C * CALCULATE SOLVENT AREA CONTRIBUTION TO STRUCTURE FACTORS
                CALL GEN108 (LU9, 0)
                DRHOMN =  99999.0
                DRHOMX = -99999.0
                DO
                  READ (LU9, IOSTAT = IOST) LOC, DELRHO
                  IF (IOST /= 0) EXIT
                  DRHOMN = MIN (DRHOMN, DELRHO)
                  DRHOMX = MAX (DRHOMX, DELRHO)
                  IF (DELRHO > PAR(285)) VOID(LOC - 1) = DELRHO
                END DO
                DRHOMX = DRHOMX * NGRID / PAR(98)
                DRHOMN = DRHOMN * NGRID / PAR(98)
                WRITE (LU6, 99983, IOSTAT = IOST) DRHOMN, DRHOMX,
     1            PAR(285), PAR(329), PAR(330), PAR(269)
                CALL PLA262 (3)
                WRITE (LU7, 99983, IOSTAT = IOST) DRHOMN, DRHOMX,
     1            PAR(285), PAR(329), PAR(330), PAR(269)
C * DO FOURIER TRANSFORMATION (DIRECT TO RECIPROCAL)
                CALL GEN028 (VOID(IBOT + 1), IPR(395), 3, 1)
C * SAVE FFT-F000
                PAR(539) = VOID(IBOT + 1)
                WRITE (LU6, 99979) PAR(539)
                DO I = 1, NREFA
                  N  = (I - 1) * NP69
                  IH = NINT (VOID(N +  9))
                  IK = NINT (VOID(N + 10))
                  IL = NINT (VOID(N + 11))
                  IF (IH < 0) IH = IH + M1
                  IF (IK < 0) IK = IK + M2
                  IF (IL < 0) IL = IL + M3
                  LOC = IBOT + 2 * ((IL * M2 + IK) * M1 + IH + 1)
                  VOID(N + 5) = VOID(LOC - 1)
                  IF (ICNTR == 1) THEN
                    VOID(N + 6) = VOID(LOC)
                  ELSE
                    VOID(N + 6) = 0.0
                  END IF
                END DO
C * CHECK FOR ITERATION STOP CRITERIUM
                IF (ABS (ABS (FS000) - ABS (FSOLD)) < PAR(250) * NSYM
     1            .AND. FS000 > 1.0 .AND. RFSOD - RFS < PAR(249)) THEN
                  NLOPM = NLOOP + 1
                ELSE
                  FSOLD = FS000
                  RFSOD = RFS
                END IF
              ELSE
                IF (IWIN == 1) THEN
                  VRT = VERT - 2.0
                  WRITE (PRBUF, 99976)
                  CALL PLA439 (0.0, PRBUF, 34, 0.30, 5 + IGBL(68), 2,
     1              17.0, VRT)
                  VRT = VRT - 0.2
                  DO I = 1, NV
                    WRITE (PRBUF, 99977) I, (SXYZ(J, I), J = 10, 12),
     1                NINT (SXYZ(1, I) * PAR(79)), NINT (SXYZ(2, I))
                    VRT = VRT - 0.5
                    CALL PLA439 (0.0, PRBUF, 34, 0.30, 1, 2, 17.0, VRT)
                  END DO
                  VRT = 3.0
                  WRITE (PRBUF, 99975) NINT (PAR(353))
                  CALL PLA439 (0.0, PRBUF, 80, 0.30, 1, 2, 0.1, VRT)
                  VRT = VRT - 0.5
                  WRITE (PRBUF, 99974) NINT (PAR(354))
                  CALL PLA439 (0.0, PRBUF, 80, 0.30, 1, 2, 0.1, VRT)
                  VRT = VRT - 0.5
                  WRITE (PRBUF, 99973) NINT (PAR(355))
                  CALL PLA439 (0.0, PRBUF, 80, 0.30, 1, 2, 0.1, VRT)
                  VRT = VRT - 0.7
                  WRITE (PRBUF, 99972, IOSTAT = IOST) DRHOMN, DRHOMX,
     1            PAR(285)
                  CALL PLA439 (0.0, PRBUF, 80, 0.30, 1, 2, 0.1, VRT)
                  VRT = VRT - 0.5
                  WRITE (PRBUF, 99971, IOSTAT = IOST)
     1            PAR(329), PAR(330), PAR(269)
                  CALL PLA439 (0.0, PRBUF, 80, 0.30, 1, 2, 0.1, VRT)
                END IF
C * REPORT, WRITE FILES, TERMINATE
                CALL PLA127 (IADR, NREFA, NV)
                RETURN
              END IF
            END DO
C * SET RETURN SUBMENU NUMBER
            IGBL(6) = 10
          ELSE
            WRITE (LU6, 99997, IOSTAT = IOST)
          END IF
        END IF
      ELSE
        IPR(1) = 1
      END IF
      RETURN
99999 FORMAT ('SQUEEZE - Procedure (A.L.Spek (2015). Acta Cryst. C71',
     1 ', 9-18)', /, 132('='))
99998 FORMAT (':: Total (Fo-Fc)map Electron Count Outside Voids =', I9)
99997 FORMAT (/, 'F: No Suitable Reflections Found', /)
99996 FORMAT (/, 'F: Scratch Array Overrun Code', I2, ' (Fatal)', /,
     1        '    Use larger program version i.e. larger NVDR', A, /)
99995 FORMAT ('Void  X(av) Y(av) Z(av) Volume Ang^3 El-Count (e-)',
     1        ' Vol/Electron Vol/Atom')
99994 FORMAT (':: Total (Fo-Fc)map Electron Count in Voids/Cell =', I9)
99993 FORMAT (':: Cycle =', I3, ', R(F) =', F5.2, ', Nref(Hemi) =',
     1        I6, ', R(F > 4SIGF) =', F5.2, ' Nref =', I6)
99992 FORMAT (':: Missing Reflections Below sin(theta)/lambda =', F5.2,
     1  /, 4X, 'H', 4X, 'K', 4X, 'L', 5X,  'ASOLV', 5X, 'BSOLV')
99991 FORMAT (/, ':: Fo-Scale =', E14.6, ' - SinT/L-Min =', F5.2,
     1        ' for Fo/Fc-Scaling', /)
99990 FORMAT ('Cycle   R(F)   Nref(Hemi)  R(F)>4*sig(F)   Nref',
     1        ' El(Solv)/Cell')
99989 FORMAT (3I5, 2F10.2)
99988 FORMAT (24X, 'PLATON/SQUEEZE ')
99987 FORMAT (A, /, 80('='))
99986 FORMAT (/, A, /)
99985 FORMAT (/, ':: Total (Fo-Fc)map Electron Count in  Unit Cell =',
     1        I9)
99984 FORMAT (I4, 1X, 3F6.3, 3X, I10, I9, 8X, F10.1, I9)
99983 FORMAT (/, 'VOID-Fo-Fc-Map:    Rho(min) =', F10.2,
     1        ', Rho(max) =', F10.2, ', RhoCutOff =', F6.2, /,
     2        'PeaksCloseToAtoms: Rho(min) =', F10.2, ', Rho(max) =',
     3        F10.2, ', RhoCutOff =', F6.2)
99982 FORMAT (/, A)
99981 FORMAT (A)
99980 FORMAT (I3, F8.3, I10, F9.3, I10, I9)
99979 FORMAT (/, ':: FFT-F000 = ', F10.2)
99978 FORMAT (/, ':: NREFB - SYMMETRY EXPANDED  REFL. SET:', I10,
     1        /, ':: NREFC - ADDED MISSING REFLECTION SET:', I10,
     2        /, ':: NREFA - TOTAL NUMBER IN HEMISPHERE  :', I10,
     3        /, ':: NREF  - USED NUMBER OF REFLECTIONS  :', I10, /)
99977 FORMAT (I3, 3F7.3, 2I5)
99976 FORMAT ('sav  x(av)  y(av)  z(av)  vol   e-')
99975 FORMAT ('Total (Fo-Fc)map Electron Count in  Unit Cell =', I9)
99974 FORMAT ('Total (Fo-Fc)map Electron Count in Voids/Cell =', I9)
99973 FORMAT ('Total (Fo-Fc)map Electron Count Outside Voids =', I9)
99972 FORMAT ('VOID-Fo-Fc-Map:    Rho(min) =', F10.2,
     1        ', Rho(max) =', F10.2, ', RhoCutOff =', F6.2)
99971 FORMAT ('PeaksCloseToAtoms: Rho(min) =', F10.2, ', Rho(max) =',
     1        F10.2, ', RhoCutOff =', F6.2)
      END SUBROUTINE PLA125
 
      SUBROUTINE PLA126
C * REMAP SAV-FILE GRID TO FFT 2**N GRID (ROUTINE SCRATCHES IN VOID)
      USE files
      USE parameters
      USE squeeze
      USE vscr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IZ
      INTEGER :: LU
      INTEGER :: JX
      INTEGER :: JY
      INTEGER :: JZ
      INTEGER :: LOC
      INTEGER :: NGRID
      INTEGER :: NLOCS
      INTEGER :: NLOCF
C * INIT SAV-GRID
      CALL GEN074 (VOID, 1, NTGRD, 0.0)
C * LOAD SOLV GRID IN VOID ARRAY FROM FILE LU15
      CALL GEN108 (LU15, 0)
      NLOCS = 0
      DO
        READ (LU15, IOSTAT = IOST)  IX, IY, IZ, N
        IF (IOST /= 0) EXIT
        VOID(IX * N23 + IY * N3 + IZ + 1) = N
        NLOCS                             = NLOCS + 1
      END DO
      CALL GEN108 (LU15, 0)
C * GET SUITABLE FFT-GRID AS A POWER OF 2
      DO I = 1, 3
        DO J = 4, 8
          IPR(394 + I) = 2**J
          IF (PAR(100 + I) * 3.0 < IPR(394 + I)) EXIT
        END DO
      END DO
      IF (IPR(395) < 2 * HMAX + 1) IPR(395) = IPR(395) * 2
      IF (IPR(396) < 2 * KMAX + 1) IPR(396) = IPR(396) * 2
      IF (IPR(397) < 2 * LMAX + 1) IPR(397) = IPR(397) * 2
      M1      = IPR(395)
      M2      = IPR(396)
      M3      = IPR(397)
      NGRID   = M1 * M2 * M3
      PAR(79) = PAR(98) / NGRID
      NLOCF   = 0
C * MAP SOLV GRID ON FFT GRID
      DO I = 0, M1 - 1
        JX = NINT (FLOAT (I) * N1 / FLOAT (M1)) * N23
        DO J = 0, M2 - 1
          JY = NINT (FLOAT (J) * N2 / FLOAT (M2)) * N3
          DO K = 0, M3 - 1
            JZ = NINT (FLOAT (K) * N3 / FLOAT (M3))
            N = NINT(VOID(JX + JY + JZ + 1))
            IF (N /= 0) THEN
              LOC = 2 * ((K * M2 + J) * M1 + I + 1)
              WRITE (LU15) LOC, N
              NLOCF = NLOCF + 1
            END IF
          END DO
        END DO
      END DO
C * REPORT GRID REMAPPING STATISTICS
      DO I = 1, 2
        IF (I == 1) THEN
          LU = LU6
        ELSE
          LU = LU7
          CALL PLA262 (5)
        END IF
        WRITE (LU, 99999, IOSTAT = IOST)
     1    (PAR(100 + J), J = 1, 3), N1, N2, N3, NLOCS, M1, M2, M3,
     2    NLOCF, PAR(101) / M1, PAR(102) / M2, PAR(103) / M3
      END DO
      RETURN
99999 FORMAT (/, ':: A,  B,  C  (Angstrom) = ', 3F8.3, /,
     1 ':: NX, NY, NZ (SOLV-MAP) = ', 3I8, ' - SAV-GridPoints =', I8,/,
     2 ':: NX, NY, NZ (FFT-MAP)  = ', 3I8, ' - SAV-GridPoints =', I8,/,
     3 ':: Resolution (FFT-MAP)  = ', 3F8.2, ' Angstrom')
      END SUBROUTINE PLA126
 
      MODULE fab
      SAVE
      INTEGER :: IOBS
      INTEGER :: NDEC
      INTEGER :: IEND
      INTEGER :: ISKIP
      INTEGER :: ITSKP
      INTEGER :: ICALC
      INTEGER :: UNITMAT
      REAL :: SHXMP
      REAL :: STHKM
      REAL :: ABSCOR
      REAL, DIMENSION(3, 3) :: TRMX
      END MODULE fab
 
      SUBROUTINE PLA127 (IADR, NREFA, NV)
C * GENERATE FAB-FILE AND CIF-STRUCTURED VOID INFO
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cif
      USE reflex
      USE squeeze
      USE fab
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: NV
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      INTEGER :: ILS
      INTEGER :: IXI
      INTEGER :: NXI
      INTEGER :: ISGN
      INTEGER :: IHKL
      INTEGER :: IADR
      INTEGER :: NMIN
      INTEGER :: NPRT
      INTEGER :: ISIGI
      INTEGER :: IWGHT
      INTEGER :: NREFA
      INTEGER :: IABIN
      INTEGER :: IACTA
      INTEGER :: ITWMT
      INTEGER :: NEXTRA
      REAL :: FO
      REAL :: ST
      REAL :: XI
      REAL :: FOA
      REAL :: FOB
      REAL :: FCM
      REAL :: FCS
      REAL :: XXI
      REAL :: DEL1
      REAL :: DEL2
      REAL :: DELS
      REAL :: DUM1
      REAL :: DUM2
      REAL :: DUM3
      REAL :: PFCS
      REAL :: PFCM
      REAL :: PFCT
      REAL :: SIGI
      REAL :: XNXI
      REAL :: SIGIW
      REAL :: SCLI8
      REAL :: FCALT
      REAL :: ACALM
      REAL :: ACALS
      REAL :: ACALT
      REAL :: BCALM
      REAL :: BCALS
      REAL :: BCALT
      REAL :: X8MAX
      REAL :: XSIGI
      REAL :: GEN095
C * OPEN FILE TO RECEIVE SQUEEZE RESULTS IN CIF FORMAT
      IF (IPR(663) == 0) THEN
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sqd.sqf',
     1    STATUS = 'UNKNOWN')
      ELSE
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sq.sqf',
     1    STATUS = 'UNKNOWN')
      END IF
      WRITE (LU61, 99999, IOSTAT = IOST) IGBL(4),
     1  (CIFDIR(I), I = 503, 509)
      DO I = 1, NV
        WRITE (LU61, 99993, IOSTAT = IOST)
     1    I, SXYZ(10, I), SXYZ(11, I), SXYZ(12, I),
     2    NINT (SXYZ(1,  I) * PAR(79)), NINT (SXYZ(2, I)), ''' '''
      END DO
      WRITE (LU61, 99990, IOSTAT = IOST) CIFDIR(639), PAR(84)
      WRITE (LU61, 99988, IOSTAT = IOST) CIFDIR(510)
      CLOSE (UNIT = LU61)
C * COPY .res to _sqd.ins
C * TEST FOR CIF BASED INPUT
      IF (IABS(IGBL(8)) == 3) THEN
        CLOSE (UNIT = LU1)
        IF (IPR(663) < 0) THEN
          REWIND  (UNIT = LU24, IOSTAT = IOST)
          OPEN (LU1, FILE = NAMEFIL(1:KNMFIL)//'.dum',
     1      STATUS = 'UNKNOWN')
          DO
            READ  (LU24, 99989, IOSTAT = IOST) IDM
              IF (IOST /= 0) EXIT
            WRITE (LU1,  99989, IOSTAT = IOST) IDM
          END DO
          REWIND (UNIT = LU1, IOSTAT = IOST)
          EXST = .TRUE.
        ELSE
          INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.res', EXIST = EXST)
          IF (EXST) OPEN (LU1, FILE = NAMEFIL(1:KNMFIL)//'.res',
     1      STATUS = 'UNKNOWN')
        END IF
C * TEST FOR RES INPUT CASE
      ELSE IF (IABS(IGBL(8)) == 2) THEN
        EXST = .TRUE.
      ELSE
        EXST = .FALSE.
      END IF
      IF (EXST) THEN
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sqd.ins',
     1    STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.ins',
     1    STATUS = 'UNKNOWN')
        REWIND (UNIT = LU1, IOSTAT = IOST)
        NEXTRA = NINT ((PAR(149) * 9) / (IPR(48) * 8))
        IABIN = 0
        IACTA = 0
        ILS   = 0
        IWGHT = 0
        ITWMT = 0
C * PREPARE _sq.ins FILE
        DO
          READ  (LU1,  99989, IOSTAT = IOST) IDM
          IF (IOST /= 0) EXIT
          CALL GEN020 (1, IDM, 1, 4)
          IF (IDM(1:4) == 'WGHT') THEN
            IWGHT = 1
            WRITE (LU62, 99985, IOSTAT = IOST)
            IABIN = 1
C * HANDLE BASF/TWIN CASE
          ELSE IF (IDM(1:4) == 'TWIN') THEN
            READ (IDM(5:80), *, IOSTAT = IOST)
     1        ((RMAT(I, J), J = 1, 3), I = 1, 3), ITWMT
            IF (IOST /= 0) THEN
              READ (IDM(5:80), *, IOSTAT = IOST)
     1          ((RMAT(I, J), J = 1, 3), I = 1, 3)
              IF (IOST == 0) ITWMT = 2
            END IF
            IF (IOST == 0 .AND. ITWMT > 0) WRITE (LU6, 99980) ITWMT,
     1        ((RMAT(I, J), J = 1, 3), I = 1, 3)
          ELSE IF (IDM(1:4) == 'ABIN') THEN
            CYCLE
          ELSE IF (IDM(1:4) == 'ACTA') THEN
            IACTA = 1
C * REMOVE LIST INSTRUCTION WHEN ENCOUNTERED
          ELSE IF (IDM(1:4) == 'LIST') THEN
            CYCLE
          ELSE IF (IDM(1:4) == 'L.S.') THEN
            WRITE (IDM, 99984) NEXTRA
            ILS = 1
          ELSE IF (IDM(1:4) == 'FVAR') THEN
            IF (ILS == 0) THEN
              WRITE (LU62, 99982, IOSTAT = IOST) NEXTRA
              ILS = 1
            END IF
            IF (IACTA == 0) THEN
              WRITE (LU61, 99985, IOSTAT = IOST)
              WRITE (LU62, 99983, IOSTAT = IOST)
              IACTA = 1
            END IF
            IF (IABIN == 0) THEN
              WRITE (LU61, 99985, IOSTAT = IOST)
              WRITE (LU62, 99985, IOSTAT = IOST)
              IABIN = 1
            END IF
            IF (IWGHT == 0) THEN
              WRITE (LU61, 99981, IOSTAT = IOST)
              WRITE (LU62, 99981, IOSTAT = IOST)
              IWGHT = 1
            END IF
          END IF
          WRITE (LU61, 99989, IOSTAT = IOST) IDM
          WRITE (LU62, 99989, IOSTAT = IOST) IDM
        END DO
C * CHECK FOR SHELXL21x - EMBEDDED RES
        IF (IPR(663) /= 0) THEN
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU1,  STATUS = 'DELETE')
        ELSE
          CLOSE (UNIT = LU61)
        END IF
        CLOSE (UNIT = LU62)
      END IF
C * CHECK FOR (EMBEDDED) SHELXL201n HKL
      IF (IPR(664) == 0) THEN
        REWIND (UNIT = LU16, IOSTAT = IOST)
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sq.hkl',
     1    STATUS = 'UNKNOWN')
C * TEST FOR SHELXL LIST 4 FCF
        IF (IGBL(9) == 1) THEN
          CALL PLA139 (LU6, LU16, LU61, IPR(384))
        ELSE
          DO
            READ  (LU16, 99989, IOSTAT = IOST) IDM
            IF (IOST /= 0) EXIT
            WRITE (LU61, 99989, IOSTAT = IOST) IDM
          END DO
        END IF
C * CHECK FOR (EMBEDDED) SHELXL201n HKL
      ELSE IF (IPR(664) == -1) THEN
        REWIND (UNIT = LU25, IOSTAT = IOST)
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sq.hkl',
     1    STATUS = 'UNKNOWN')
        DO
          READ  (LU25, 99989, IOSTAT = IOST) IDM
          IF (IOST /= 0) EXIT
          WRITE (LU61, 99989, IOSTAT = IOST) IDM
        END DO
      END IF
      CLOSE (UNIT = LU61)
C * GENERATE '_sqd.hkl' FILE FOR SHELXL97 AND CRYSTALS
      OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sqd.hkl',
     1  STATUS = 'UNKNOWN')
      DO I = 1, 20
        DO J = 1, 9
          STAT(I, J) = 0.0
        END DO
      END DO
      X8MAX = 0
      SCLI8 = 1.0
C * DOUBLE LOOP FOR SCALING TO SHELXL FORMAT
      DO K = 1, 2
        IF (K == 2) THEN
          IF (X8MAX > 0.99999E8) SCLI8 = 0.99999E8 / X8MAX
        END IF
        NPRT = 0
        IEND = -1
C * TRANSFORM REFLECTIONS FOR SF-CALCULATION (EXCLUDE NON-INTEGRAL H,K,L)
        DO
          CALL PLA134 (IH, IK, IL, IHT, IKT, ILT, XI, SIGI,
     1      SIGIW, DUM1, DUM2, DUM3)
          IF (IEND > 0) EXIT
          IF (IGBL(9) == -1) XI = DUM1
          XSIGI = SCLI8 * SIGI
          IHKL  = ILT * MHK + IKT * MPH + IHT
          IF (IHKL > 0) THEN
            ISGN = 1
          ELSE
            ISGN = -1
            IHKL = - IHKL
          END IF
          N = NP69 * (NINT (VOID(IADR + IHKL)) - 1)
          IF (N >= 0) THEN
C * TEST FOR SHELXL STYLE FCF
            IF (IGBL(9) == 1) THEN
              XI    = XI    * 0.01
              XSIGI = XSIGI * 0.01
            END IF
            FO    = SQRT (MAX (0.0, XI)) * PAR(566)
            ACALM = VOID(N + 3)        + VOID(N + 12)
            BCALM = VOID(N + 4) * ISGN + VOID(N + 13)
            ACALS = VOID(N + 5)
            BCALS = VOID(N + 6) * ISGN
            ACALT = ACALS + ACALM
            BCALT = BCALS + BCALM
            FCALT = SQRT(ACALT**2 + BCALT**2)
C * CALCULATE CORRECTED FO BY SUBSTRACTING THE SOLVENT CONTRIBUTION
            FOA   = (FO * ACALT / FCALT - ACALS) / PAR(566)
            FOB   = (FO * BCALT / FCALT - BCALS) / PAR(566)
            XXI   = SCLI8 * (FOA**2 + FOB**2)
            XNXI  = SCLI8 * XI
            IF (K == 1) THEN
              X8MAX = MAX (X8MAX, XXI)
              X8MAX = MAX (X8MAX, XSIGI)
              X8MAX = MAX (X8MAX, XNXI)
            ELSE
              IXI   = NINT (XXI)
              ISIGI = NINT (XSIGI)
              NXI   = NINT (XNXI)
C * WRITE SOLVENT CONTRIBUTION FREE HKL WITH/WITHOUT DIRECTION COSINES
              IF (IGBL(37) /= 0) THEN
                WRITE (LU61, 99996, IOSTAT = IOST) IH, IK, IL, IXI,
     1            ISIGI, (V2(I), V3(I), I = 1, 3), NXI, ACALS, BCALS,
     2            1.0
              ELSE
                WRITE (LU61, 99995, IOSTAT = IOST)
     1            IH, IK, IL, IXI, ISIGI, NXI, ACALS, BCALS, 1.0
              END IF
              ST   = VOID(N + 14)
              FCS  = SQRT (ACALS**2 + BCALS**2)
              FCM  = SQRT (ACALM**2 + BCALM**2)
              PFCS = 0.0
              PFCM = 0.0
              PFCT = 0.0
              IF (ACALS /= 0.0 .OR. BCALS /= 0.0)
     1          PFCS = ATAN2 (BCALS, ACALS) * RGBL(6)
              IF (ACALM /= 0.0 .OR. BCALM /= 0.0)
     1          PFCM = ATAN2 (BCALM, ACALM) * RGBL(6)
              IF (ACALT /= 0.0 .OR. BCALT /= 0.0)
     1          PFCT = ATAN2 (BCALT, ACALT) * RGBL(6)
              DEL1 = MOD (PFCM + 360.0 - PFCS, 360.0)
              IF (DEL1 > 180.0) DEL1 = 360.0 - DEL1
              DEL2  = MOD (PFCM + 360.0 - PFCT, 360.0)
              IF (DEL2 > 180.0) DEL2 = 360.0 - DEL2
              IF (SIGI > 0.0) THEN
                DELS = ABS (FO**2 - FCALT**2) / (PAR(566)**2 * SIGI)
                IF (ST <= PAR(286) .AND. DELS > PAR(288)) THEN
                  NPRT = NPRT + 1
                  IF (NPRT == 1) THEN
                    CALL PLA262 (-2)
                    WRITE (LU7, 99997, IOSTAT = IOST)
                  END IF
                  CALL PLA262 (1)
                  WRITE (LU7, 99994, IOSTAT = IOST)
     1              IH, IK, IL, ST, FO, FCM, FCS,
     2              FCALT, DELS, XI * PAR(566)**2, SIGI * PAR(566)**2
                END IF
              END IF
              N = MAX (1, MIN (20, INT (ST * 20 + 0.5)))
              STAT(N, 1) = STAT(N, 1) + FCM
              STAT(N, 2) = STAT(N, 2) + FCS
              STAT(N, 3) = STAT(N, 3) + FCALT
              STAT(N, 4) = STAT(N, 4) + FO
              STAT(N, 5) = STAT(N, 5) + DEL1
              STAT(N, 6) = STAT(N, 6) + DEL2
              STAT(N, 7) = STAT(N, 7) + 1.0
              STAT(N, 8) = STAT(N, 8) + ABS (FCM   - FO)
              STAT(N, 9) = STAT(N, 9) + ABS (FCALT - FO)
            END IF
          END IF
        END DO
      END DO
      IF (IPR(664) /= 0) CLOSE (LU61, STATUS = 'DELETE')
C * GENERATE '.fab' FILE FOR SHELXL201n: H, K, L, ASOLV, BSOLV
C * ASYMMETRIC UNIT, INCLUDING MISSING REFLECTION CONTRIBUTIONS
      OPEN (LU65, FILE = NAMEFIL(1:KNMFIL)//'_sq.fab',
     1  STATUS = 'UNKNOWN')
      K = 0
      DO I = 1, NREFA
C * CHECK FOR ASYMMETRIC REFLECTION UNIT REFLECTION
        N = (I - 1) * NP69
        IF (NINT(VOID(N + 15)) > 0) THEN
          V1(1) = VOID(N +  9)
          V1(2) = VOID(N + 10)
          V1(3) = VOID(N + 11)
          ACALS = VOID(N + 5)
          IF (ICNTR == 1) THEN
            BCALS = VOID(N + 6)
          ELSE
             BCALS = 0.0
          END IF
          WRITE (LU65, 99992, IOSTAT = IOST)
     1      (NINT(V1(J)), J = 1, 3), ACALS, BCALS
C * ADD DUMMY OUT-OF-RESOLUTION TWIN COMPONENT REFLECTIONS TO FAB
          IF (ITWMT == 2) THEN
            K = K + 1
            IF (K == 1) WRITE (LU6, 99978)
            IH   = NINT(V1(1))
            IK   = NINT(V1(2))
            IL   = NINT(V1(3))
            DUM1 = ASIN (VOID(N + 14) * PAR(17)) * RGBL(6)
            CALL GEN002 (1, RMAT, V1, V2, DUM3)
            JH   = NINT(V2(1))
            JK   = NINT(V2(2))
            JL   = NINT(V2(3))
            DUM3 = SQRT (GEN095 (PAR(191), JH, JK, JL))
            DUM2 = ASIN (DUM3 * PAR(17)) * RGBL(6)
            IF (VOID(N + 14) <= PAR(572) .AND. DUM3 > PAR(572)) THEN
              WRITE (LU65, 99992, IOSTAT = IOST) JH, JK, JL, 0.0, 0.0
              WRITE (LU6, 99979) IH, IK, IL, DUM1, JH, JK, JL, DUM2
            END IF
          END IF
        END IF
      END DO
C * ADD TERMINATING DUMMY REFLECTION
      WRITE (LU65, 99992, IOSTAT = IOST) 0, 0, 0, 0.0, 0.0
C * COPY SQF & SQZ INFO AT THE END OF THE FAB FILE
C * HEADER LOOP FOR .SQF
      WRITE (LU65, 99999, IOSTAT = IOST) IGBL(4),
     1  (CIFDIR(I), I = 503, 509)
      DO I = 1, NV
        WRITE (LU65, 99993, IOSTAT = IOST)
     1    I, SXYZ(10, I), SXYZ(11, I), SXYZ(12, I),
     2    NINT (SXYZ(1,  I) * PAR(79)), NINT (SXYZ(2,  I)), ''' '''
      END DO
C * HEADER LOOP FOR MISSING (LOW ANGLE) REFLECTIONS
      IF (IPR(610) > 0) THEN
        WRITE (LU65, 99998, IOSTAT = IOST) PAR(486),
     1    (CIFDIR(I), I = 642, 645)
        NMIN = MIN (IPR(610), NP60)
        DO I = 1, NMIN
          WRITE (LU65, 99991) (MISSING(J, I), J = 1, 3),
     1      FLOAT (MISSING(4, I)) / 1000.0
        END DO
      END IF
      WRITE (LU65, 99990, IOSTAT = IOST) CIFDIR(639), PAR(84)
      WRITE (LU65, 99987, IOSTAT = IOST) CIFDIR(510)
      REWIND (UNIT = LU2, IOSTAT = IOST)
C * COPY .SQZ DATA
      DO
        READ (LU2, 99989, IOSTAT = IOST) IDM
        IF (IOST /= 0) EXIT
        WRITE (LU65, 99989, IOSTAT = IOST) IDM
      END DO
      WRITE (LU65, 99986)
C * REPORT SQUEEZE RESULT
      CALL PLA129
C * REMOVE DUMMY FILES
      CLOSE (UNIT = LU17, STATUS = 'DELETE', IOSTAT = IOST)
      CLOSE (UNIT = LU13, STATUS = 'DELETE', IOSTAT = IOST)
      RETURN
99999 FORMAT ('# SQUEEZE RESULTS (Version =', I7, ')', /,
     1        '# Note: Data are Listed for all Voids in the P1 Unit',
     2        ' Cell', /,
     3        '# i.e. Centre of Gravity, Solvent Accessible Volume,', /,
     4        '# Recovered number of Electrons in the Void and', /,
     5        '# Details about the Squeezed Material', /,
     6        'loop_', 7(/, 2X, A))
99998 FORMAT ('# Missing Reflections Below sin(th)/lambda =', F5.2, /,
     1        'loop_', 4(/, 2X, A))
99997 FORMAT ('  H  K  L  Sinth/l F(obs)  F(mod) F(solv)  ',
     1        'F(tot) D(F^2)/S       I       Sig(I)', /)
99996 FORMAT (3I4, 2I8, 4X, 6F8.5, I8, 2F8.2, F8.4)
99995 FORMAT (3I4, 2I8, 52X, I8, 2F8.2, F8.4)
99994 FORMAT (3I3, 6F8.2, F12.2, F10.2)
99993 FORMAT (I4, 3(F7.3), 2I10, 1X, A)
99992 FORMAT (3I5, 2F10.2)
99991 FORMAT (3I5, F10.3)
99990 FORMAT (A, F6.2)
99989 FORMAT (A)
99988 FORMAT (A, ' ?')
99987 FORMAT (A, /, ';')
99986 FORMAT (';')
99985 FORMAT ('ABIN')
99984 FORMAT ('L.S. 5 0', I5)
99983 FORMAT ('ACTA')
99982 FORMAT ('L.S. 5', I5)
99981 FORMAT ('WGHT 0.1')
99980 FORMAT (':: Twin Matrix (', I1, ') from Embedded RES file',
     1       3(/, 3F8.3))
99979 FORMAT (3I5, F10.2, 3I5, F10.2)
99978 FORMAT (/, 'Listing of added component(2) reflections to FAB ',
     1       'file beyond Theta(max)', //,
     2       3X, 'Component(1)  Theta(1)   Component(2)  Theta(2)')
      END SUBROUTINE PLA127
 
      SUBROUTINE PLA128
C * SQUEEZE SUMMARY (GRAPHICS)
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE squeeze
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      REAL :: X
      REAL :: Y
      REAL :: XOR
      REAL :: YOR
      REAL :: DSH
      REAL :: PEN
      REAL :: OLDX
      REAL :: OLDY
      REAL :: RVAL
      REAL :: STLM
      REAL :: RMODEL
      REAL :: SCALHOR
      REAL :: SCALVER
      CHARACTER(len=4)  :: A
      CHARACTER(len=10) :: B
      IF (IWIN == 1) THEN
        MEDIUM = 2
        IGGT(16:22) = 'ON     '
        CALL GGIP (-999.0, 0.0, 0.0, 6)
      END IF
   10 DO I = 1, 20
        N = 21 - I
        IF (STAT(N, 7) /= 0.0) THEN
          STLM = N * 0.05
          EXIT
        END IF
      END DO
      M = 1
      DO I = 1, N
        IF (STAT(I, 7) /= 0.0) THEN
          M = I
          EXIT
        END IF
      END DO
      RMODEL = 0.0
      DO I = 1, N
        RMODEL = MAX (STAT(I, 8), RMODEL)
      END DO
      RMODEL = MIN (1.0, RMODEL)
      DSH  = 0.05
      HORS = 25.0
      VERT = 25.0
      XOR  = 1.0
      YOR  = 1.0
      SCALHOR = (HORS - XOR) / STLM
      SCALVER = (VERT - YOR) / (RMODEL + 0.02)
C * OPEN WINDOW
      CALL GGIP (HORS, VERT, 0.0, 1)
C * OUTLINE FRAME
      CALL PLA110 (HORS, VERT, -1)
      CALL PLA439 (0.0, 'SQUEEZE SUMMARY', 15, 0.45, 6, 2,
     1  9.0, VERT - 0.6)
      CALL GGIP (0.0, 1.0, 0.0, 0)
C * MOVE ORIGIN
      CALL GGIP (XOR, YOR, 0.0, -3)
C * VERTICAL AND HORIZONTAL AXES
      CALL GGIP (0.0, VERT - YOR, 0.0, 2)
      CALL GGIP (0.0, 0.0, 0.0, 3)
      CALL GGIP (HORS - XOR, 0.0, 0.0, 2)
C * HORIZONTAL SCALE
      DO I = 1, N
        X = I * 0.05 * SCALHOR
        Y = 0.0
        CALL GGIP (X, Y, 0.0, 3)
        CALL GGIP (X, Y + 0.3, 0.0, 2)
        WRITE (A, 99999) I * 0.05
        CALL PLA439 (90.0, A, 4, 0.2, 1, 1, X -0.1, Y + 0.1)
      END DO
      CALL PLA439 (0.0, 'sin(theta)/lambda', 17, 0.25, 1, 1,
     1  HORS - XOR - 4.0, -0.35)
C * VERTICAL SCALE
      DO I = 1, 20
        RVAL = I * 0.05
        IF (RVAL < RMODEL) THEN
          X = 0.0
          Y = RVAL * SCALVER
          CALL GGIP (X, Y, 0.0, 3)
          CALL GGIP (X + 0.3, Y, 0.0, 2)
          WRITE (A, 99999) RVAL
          CALL PLA439 (0.0, A, 4, 0.2, 1, 1, X + 0.1, Y + 0.1)
        END IF
      END DO
C * PLOT CURVES
      DO J = 8, 9
        OLDX = 0.0
        OLDY = 0.0
        IF (J == 8) THEN
          PEN = 2
          B   = '  R(Model)'
          Y   = 3.0
        ELSE
          PEN = 3
          B   = 'R(Squeeze)'
          Y   = 2.0
        END IF
        CALL PLA439 (0.0, B, 10, 0.3, NINT (PEN), 1, HORS - XOR - 2.8,
     1       Y)
        CALL GGIP (0.0, PEN, 0.0, 0)
        DO I = M, N
          X = (I - 0.5) * 0.05 * SCALHOR
          Y =  MIN (STAT(I, J) * SCALVER, VERT - XOR)
          IF (I > M) THEN
            CALL GGIP (OLDX, OLDY, 0.0, 3)
            CALL GGIP (X   , Y   , 0.0, 2)
          END IF
          OLDX = X
          OLDY = Y
C * PLOT MARKER
          CALL PLA406 (X, Y, DSH, -1.0)
        END DO
      END DO
C * INFO
      VRT = VERT - XOR - 2.0
      K   = 14 + KNMFIL + KXT + 1
      WRITE (LINE, 99988) FNLU1(1 : KNMFIL + KXT + 1)
      CALL PLA439 (0.0, LINE, K, 0.35, 1, 1, 8.0, VRT)
      VRT = VRT - 0.6
      WRITE (LINE, 99987) FNLU16(1 : KNM16)
      CALL PLA439 (0.0, LINE, 14 + KNM16, 0.35, 1, 1, 8.0, VRT)
      IF (IABS (IGBL(8)) == 3) THEN
        VRT = VRT - 0.6
        K   = INDEX (RLWS(5)(1:65), CHAR (39)) - 1
        WRITE (LINE, 99983) RLWS(5)(1:K)
        CALL PLA439 (0.0, LINE, 14 + K, 0.35, 1, 1, 8.0, VRT)
      END IF
      VRT = VRT - 0.6
      WRITE (LINE, 99986) ZSPG
      CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, 8.0, VRT)
      VRT = VRT - 0.6
      PAR(166) = ASIN (SQRT (PAR(166)) * PAR(17)) * RGBL(6)
      WRITE (LINE, 99985) MAX (PAR(166), PAR(168), 0.0)
      CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, 8.0, VRT)
      VRT = VRT - 0.6
      WRITE (LINE, 99984) MAX (IPR(261), 0)
      CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, 8.0, VRT)
      IF (PAR(197) > 0.0) THEN
        VRT = VRT - 0.6
        WRITE (LINE, 99982) PAR(197)
        CALL PLA439 (0.0, LINE, 26, 0.35, 1, 1, 8.0, VRT)
      END IF
      IF (PAR(173) > 0.0) THEN
        VRT = VRT - 0.6
        WRITE (LINE, 99981) PAR(173)
        CALL PLA439 (0.0, LINE, 26, 0.35, 1, 1, 8.0, VRT)
      END IF
      IF (PAR(174) > 0.0) THEN
        VRT = VRT - 0.6
        WRITE (LINE, 99980) PAR(174)
        CALL PLA439 (0.0, LINE, 26, 0.35, 1, 1, 8.0, VRT)
      END IF
      X = - XOR + HORS
      Y = - YOR
      CALL GGIP (X, Y, 0.0, -3)
C * CELL VOLUME
      WRITE (LINE, 99998) NINT (PAR(98))
      VRT = VERT - 0.6
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * VOID VOLUME
      WRITE (LINE, 99997) NINT (PAR(150))
      VRT = VRT - 0.6
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * VOID PERCENTAGE
      WRITE (LINE, 99996) NINT (PAR(409))
      VRT = VRT - 0.6
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * ELECTRON COUNT IN CELL
      WRITE (LINE, 99995) NINT (PAR(354))
      VRT = VRT - 0.6
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * VOID MAX
      WRITE (LINE, 99993) NINT (PAR(525))
      VRT = VRT - 1.2
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * ELECTRON COUNT VOID MAX
      WRITE (LINE, 99992) NINT (PAR(526))
      VRT = VRT - 0.6
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * TOTAL # OF REFLECTIONS
      VRT = VRT - 1.2
      WRITE (LINE, 99989) IPR(712)
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * MISSING # OF REFLECTIONS
      VRT = VRT - 0.6
      WRITE (LINE, 99991) IPR(609)
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
C * MISSING # OF LOW ANGLE REFLECTIONS
      VRT = VRT - 0.6
      WRITE (LINE, 99990) IPR(610)
C * NUMBER OF HEMI-SPHERE REFLECTIONS
      VRT = VRT - 1.2
      WRITE (LINE, 99979) NREF
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
      VRT = VRT - 0.6
      WRITE (LINE, 99978) RF
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
      VRT = VRT - 0.6
      WRITE (LINE, 99977) NREFS
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
      VRT = VRT - 0.6
      WRITE (LINE, 99994) RFS
      CALL PLA439 (0.0, LINE, 24, 0.4, 1, 1, 0.1, VRT)
      CALL GGIP (0.0, 0.0, 0.0, -1)
      DO
C * WHAT NEXT ?
        CALL PLA012 (2, 1)
        SELECT CASE (IGGT(1:4))
          CASE ('!   ', 'END ', 'EXIT')
            EXIT
          CASE ('PLOT')
            GO TO 10
          CASE DEFAULT
            EXIT
        END SELECT
      END DO
99999 FORMAT (F4.2)
99998 FORMAT ('Cell Vol ....', I6, ' A**3')
99997 FORMAT ('Void Vol ....', I6, ' A**3')
99996 FORMAT ('Void Perc ...', I6, ' %')
99995 FORMAT ('Cell Count ..', I6, ' e-')
99994 FORMAT ('R(F > 4sig(F)', F6.3)
99993 FORMAT ('Void Max ....', I6, ' A**3')
99992 FORMAT ('ElCountMax ..', I6, ' e-')
99991 FORMAT ('Missing .....', I6, ' Refl')
99990 FORMAT ('MissingLowAng', I6, ' Refl')
99989 FORMAT ('Unique Number', I6, ' Refl')
99988 FORMAT ('FormData ....', 1X, A)
99987 FORMAT ('ReflData ....', 1X, A)
99986 FORMAT ('SpaceGroup ..', 1X, A)
99985 FORMAT ('ThetaMax ....', F6.2, ' Deg.')
99984 FORMAT ('Temperature .', I4, ' K')
99983 FORMAT ('Model .......', 1X, A)
99982 Format ('R(int) ......', F6.3, ' (CIF)')
99981 Format ('R1(I>2sig(I))', F6.3, ' (CIF)')
99980 FORMAT ('wR2 .........', F6.3, ' (CIF)')
99979 FORMAT ('Hemi-Sphere .', I6, ' Refl')
99978 FORMAT ('R(F) ........', F6.3)
99977 FORMAT ('F > 4sig(F)  ', I6, ' Refl')
      END SUBROUTINE PLA128
 
      SUBROUTINE PLA129
C * REPORT SQUEEZE RESULT
      USE files
      USE parameters
      USE cggt
      USE squeeze
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: IB
      INTEGER :: IC
      REAL :: ST
C * COMMENT ON SQUEEZE RUN
      IGBL(6) = 36
      CALL PLA262 (0)
      WRITE (LU7, 99993, IOSTAT = IOST)
      DO I = 1, 20
        IF (STAT(I, 7) > 0.0) THEN
          IF (STAT(I, 4) /= 0.0) THEN
            STAT(I, 8) = STAT(I, 8) / STAT(I, 4)
            STAT(I, 9) = STAT(I, 9) / STAT(I, 4)
          ELSE
            STAT(I, 8) = 0.0
            STAT(I, 9) = 0.0
          END IF
          DO J = 1, 6
            STAT(I, J) = STAT(I, J) / STAT(I, 7)
          END DO
          ST = I / 20.0
          WRITE (LU7, 99992, IOSTAT = IOST) ST, (STAT(I, K), K = 1, 9)
        END IF
      END DO
C * DISPLAY SQUEEZE RESULT
      IF (IWIN == 1) THEN
C * WHAT NEXT ?
        CALL PLA012 (2, 1)
      ELSE
        CALL PLA431
      END IF
      CALL PLA128
      WRITE (LU7, 99998, IOSTAT = IOST)
      IF (MAX (-PAR(329), PAR(330)) > 1.0)
     1  WRITE (LU7, 99997, IOSTAT = IOST) PAR(329), PAR(330)
      IF (IPR(489) + IPR(490) > 0)
     1  WRITE (LU7, 99996, IOSTAT = IOST) IPR(489) + IPR(490)
C * NOTE ON HOW TO PROCEED
      IF (IGBL(29) == 1 .OR. IGBL(29) == 3) THEN
        IB = 7
        IC = 15
      ELSE
        IB = 1
        IC = 30
      END IF
      WRITE (LU6, 99999, IOSTAT = IOST) (TXT(I), I = IB, IC)
      WRITE (LU7, 99999, IOSTAT = IOST) (TXT(I), I = IB, IC)
      IF (IWIN == 1) THEN
        CALL GGIP (HORS, VERT, 0.0, 1)
        VRT = VERT - 1.0
        CALL PLA439 (0.0, 'S U M M A R Y', 13, 0.60, 5 + IGBL(68),
     1               2, 10.0, VRT)
        VRT = VRT - 0.9
        CALL PLA439 (0.0, TXT1(1), 62, 0.30, 1, 2, 5.0, VRT)
        IF (MAX (-PAR(329), PAR(330)) > 1.0) THEN
          WRITE (TXT1(2), 99995, IOSTAT = IOST) PAR(329), PAR(330)
          VRT = VRT - 0.40
          CALL PLA439 (0.0, TXT1(2), 62, 0.30, 1, 2, 5.0, VRT)
        END IF
        IF (IPR(610) > 0) THEN
          WRITE (TXT1(3), 99994, IOSTAT = IOST) PAR(486), IPR(610)
          VRT = VRT - 0.40
          CALL PLA439 (0.0, TXT1(3), 62, 0.30, 2, 2, 5.0, VRT)
          VRT = VRT - 0.40
          CALL PLA439 (0.0,
     1  'Estimates Substituted for Missing Reflexion Intensites',
     2   54, 0.30, 2, 2, 5.0, VRT)
        END IF
        DO I = IB, IC
          VRT = VRT - 0.60
          CALL PLA439 (0.0, TXT(I), 62, 0.45, 1, 2, 1.0, VRT)
        END DO
        CALL PLA297 (0)
      END IF
      IPR(1) = 1
      RETURN
99999 FORMAT (/, 30(A, /), /)
99998 FORMAT (/, 'Comments on and Analysis of the SQUEEZE run',
     1        /, 80('='))
99997 FORMAT (/, '- Significant Residual Density Excursion(s) in  the',
     1        /, '  Ordered part of the Structure:', 2F6.1)
99996 FORMAT (/, '- Model includes', I4, ' Isotropic Non-H-Atoms', /,
     1           '  Rerun SQUEEZE with Anisotropically Refined Model')
99995 FORMAT ('Significant Residual Model Density Excursions:',
     1        F5.1, ',', F5.1)
99994 FORMAT ('Number of Missing Reflections Below sin(th)/L =',
     1         F5.2, ' =', I4)
99993 FORMAT ('SQUEEZE Statistics on the Difference Map Phasing', /,
     1        80('='), //,
     2  '<FcMod>  = Average contribution to Fc from discrete model', /,
     3  '<FcSolv> = Average contribution to Fc from solvent region', /,
     4  '<FcTot>  = Average Fc-total ( = model + solvent contrib.)', /,
     5  '<DelMS>  = Average Phase difference between model and',
     6  ' solvent contrib.', /,
     7  '<DelMT>  = Average Phase difference between model  and',
     8  ' combined contrib.', /,
     9  'Fo       = Observed Fobs scaled on Fc-total', /,
     *  'N        = Number of reflections in Sin(Theta)/Lambda range',/,
     1  'R(Mod)   = SUM(ABS(ABS(FcMod) - Fo)) / SUM(Fo)', /,
     2  'R(Tot)   = SUM(ABS(ABS(FcTot) - Fo)) / SUM(Fo)', /,
     3  /, 'SinT/L <FcMod> <FcSolv>  <FcTot>    <Fo> ',
     4        ' <DelMS> <DelMT>    N  R(Mod) R(Tot)', /, 80('='))
99992 FORMAT (F4.2, 4F9.2, 2F8.2, F7.0, 2F7.3)
      END SUBROUTINE PLA129
 
      SUBROUTINE PLA130 (HMAX, KMAX, LMAX, NREF, IADR, NREFA, NREFB)
C * REFLECTION DATA SUPPORT ROUTINE FOR : PLA125 - SQUEEZE
      USE files
      USE parameters
      USE spgrdata
      USE reflex
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NR
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: ISN
      INTEGER :: IHQ
      INTEGER :: IKQ
      INTEGER :: ILQ
      INTEGER :: IHP
      INTEGER :: IKP
      INTEGER :: ILP
      INTEGER :: MPK
      INTEGER :: MPL
      INTEGER :: NRF
      INTEGER :: IASM
      INTEGER :: NRF1
      INTEGER :: IADD
      INTEGER :: HMAX
      INTEGER :: KMAX
      INTEGER :: LMAX
      INTEGER :: NREF
      INTEGER :: IADR
      INTEGER :: NIND
      INTEGER :: MHKL
      INTEGER :: NEXT
      INTEGER :: JUNK
      INTEGER :: NREFA
      INTEGER :: NREFB
      INTEGER :: MHKLH
      REAL :: TH
      REAL :: XI
      REAL :: F1
      REAL :: F2
      REAL :: F3
      REAL :: F4
      REAL :: F1I
      REAL :: F2I
      REAL :: F3I
      REAL :: FC1
      REAL :: FC2
      REAL :: FC3
      REAL :: ARG
      REAL :: SGI
      REAL :: STL
      REAL :: WGHT
      REAL :: XCAL
      REAL :: STLK
      REAL :: SUM1
      REAL :: SUM2
      REAL :: SUM3
      REAL :: SUM4
      REAL :: ASOL
      REAL :: BSOL
      REAL :: ACAL
      REAL :: BCAL
      REAL :: FOBS
      REAL :: SGIK
      REAL :: YUNK
      REAL :: ZCAL
      REAL :: SNTHA
      REAL :: SIGXI
      REAL :: FOBSX
      REAL :: ACALT
      REAL :: BCALT
      REAL :: FCALT
      REAL :: ACALA
      REAL :: BCALA
      REAL :: SIGIW
      REAL :: XFCAL
      REAL :: SCHAAL
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: FACTOR
      REAL :: GEN095
      CHARACTER(len=80) :: LINE
C * LAYOUT VOID ARRAY
C *         NVDR I - TOP REFLECTION DATA POINTER ARRAY (HALF REFL. SPHERE)
C *              I
C *              I      INDEX TO THE DIFFERENCE MAP REFLECTION DATA STORAGE
C *              I
C *         IADR I - ADDRESS 0,0,0 Reflection
C *              I
C *              I      (EMPTY)
C *              I
C *         IR3D I - TOP R3D ARRAY
C *              I
C *              I      THREE R3D SECTIONS (3 * (M1 + 2) * (M2 + 2))
C *              I
C *         ITOP I - TOP FFT ARRAY
C *              I
C *              I      FFT ARRAY SIZE = NGRID * 2
C *              I
C * NREFA * NP69 I - TOP TOTAL REFLECTION DATA STORAGE
C *              I
C *              I      ENTRIES FOR MISSING REFLECTION DATA
C *              I
C * NREFB * NP69 I - TOP (SYMMETRY EXPANDED) REFLECTION DATA STORAGE
C *              I
C *              I      VOID(N +  1) - F(obs)
C *              I      VOID(N +  2) - SIG(F(obs))
C *              I      VOID(N +  3) - NON-SOLVENT ACAL
C *              I      VOID(N +  4) - NON-SOLVENT BCAL
C *              I      VOID(N +  5) - SOLVENT     ACALSOLVENT
C *              I                     (ACALS = ACAL + ACALSOLVENT)
C *              I      VOID(N +  6) - SOLVENT     BCALSOLVENT
C *              I                     (BCALS = BCAL + BCALSOLVENT)
C *              I      VOID(N +  7) - DIFF-MAP    ACAL
C *              I      VOID(N +  8) - DIFF-MAP    BCAL
C *              I      VOID(N +  9) - H
C *              I      VOID(N + 10) - K
C *              I      VOID(N + 11) - L
C *              I      VOID(N + 12) - ANOM-DISP   ACALA
C *              I      VOID(N + 13) - ANOM-DISP   ACALB
C *              I      VOID(N + 14) - SIN(THETA)/LAMBDA
C *              I      VOID(N + 15) - ASYMMETRIC REFL INFO
C *              I      VOID(N + 16) - SUM WEIGHTS AVERAGED REFLNS
C *              I
      IND1  = 1
      IND2  = 2
      IND3  = 3
      NIND  = 0
      NREFA = 0
C * GET CENTROSYMMETRY NUMBER
      ICNTR = IPR(257)
C * DETERMINE PACKING CONSTANTS AND ADRESSES
      MPH   = 2 * HMAX + 1
      MPK   = 2 * KMAX + 1
      MPL   = 2 * LMAX + 1
      MHK   = MPH * MPK
      MHKL  = MPL * MHK
      MHKLH = (MHKL - 1) / 2
C * TOP-DOWN STORAGE ARRAY OF REFLECTION ADDRESSES
C * CALCULATE ADDRESS OF 0,0,0 REFLECTION
      IADR  = NVDR - MHKLH
C * PRELIMINARY CHECK FOR SUFFICIENT SPACE
      IF (IADR < 1) THEN
        IF (IGBL(63) > 0)
     1    WRITE (LU6, 99998, IOSTAT = IOST) NIND, IADR, NVDR
C * ERROR/PROBLEM
        NREFA = -1
        RETURN
      END IF
C * INIT & LOAD POINTERS TO REFLECTION DATA FOR ALL REFLECTIONS
      CALL GEN074 (VOID, IADR + 1, NVDR, 0.0)
      NEXT  = 0
C * REWIND REFLECTION FILE LU27 CREATED BY PLA133
      REWIND (LU27, IOSTAT = IOST)
      IF (IOST /= 0) THEN
        WRITE (6, 99993)
        STOP
      END IF
C * TEST FOR SHELXL LIST 4 TYPE HKL FILE (IGBL(9) = 1)
C * TEST FOR SHELXL HKLF 4 TYPE HKL FILE (IGBL(9) = 0)
C * ??  IF (IGBL(9) == 1 .OR. IGBL(9) .EQ. 0) THEN
      IF (IGBL(9) == 1) THEN
        SCHAAL   = 1.0 / PAR(230)
        PAR(230) = 1.0
C * ASSUME FCF FILE
      ELSE
        SCHAAL = 1.0
      END IF
      NRF    = 0
      NRF1   = 0
      SUM1   = 0.0
      SUM2   = 0.0
      SUM3   = 0.0
      SUM4   = 0.0
      ACAL   = 0.0
      BCAL   = 0.0
      ACALA  = 0.0
      BCALA  = 0.0
      ACALAF = 0.0
      BCALAF = 0.0
      DO NR = 1, NREF
        READ (LU27, IOSTAT = IOST) IHP, IKP, ILP, XI, SGI, SIGIW,
     1    ASOL, BSOL
        IF (IOST /= 0) THEN
          IF (IGBL(63) /= 0) WRITE (LU6, 99996, IOSTAT = IOST)
C * ERROR/PROBLEM
          NREFA = -1
          RETURN
        END IF
C * APPLY NONSTANDARD ABIN PARAMETERS
        IF (PAR(575) /= 1.0) THEN
          ASOL = ASOL * PAR(575)
          BSOL = BSOL * PAR(575)
        END IF
        IF (PAR(576) /= 0.0) THEN
          STLK = GEN095 (PAR(191), IHP, IKP, ILP)
          YUNK = EXP (- RGBL(8) * STLK * PAR(576))
          ASOL = ASOL * YUNK
          BSOL = BSOL * YUNK
        END IF
C * CALCULATE (SIN(THETA) / LAMBDA)**2
C * TAKE SWAT CORRECTION TO I(obs) INTO ACCOUNT
        IF (IPR(698) /= 0) THEN
C * CALCULATE (SIN(THETA) / LAMBDA)**2
          STLK = GEN095 (PAR(191), IHP, IKP, ILP)
          ARG  = RGBL(8) * PAR(502) * STLK
          IF (PAR(501) == 0.0 .OR. ARG > 20) THEN
            FACTOR = 1.0
          ELSE
            FACTOR = 1.0 - PAR(501) * EXP (- ARG)
          END IF
          XI  = XI  * SCHAAL / FACTOR**2
          SGI = SGI * SCHAAL / FACTOR**2
        ELSE
          XI  = XI  * SCHAAL
          SGI = SGI * SCHAAL
        END IF
        FOBS  = SQRT (MAX (0.0, XI))
        SIGXI = 0.7071068 * AMIN1 (SQRT (SGI),
     1              SGI / MAX (FOBS, 0.0001))
C * CHECK FOR SYSTEMATIC EXTINCTIONS ABSENCES
        SGX(1)  = IHP
        SGX(2)  = IKP
        SGX(3)  = ILP
        SGX(12) = 0.0
        CALL SGSM (27, LINE, SGX, 0, 0, IERR)
        IF (NINT (SGX(12)) == 0) THEN
          CALL PLA136 (1, IHP, IKP, ILP, IASM)
C * LOOP OVER SYMMETRY (EXCLUDING Lattice Centering and Inversion)
          DO I = 1, NSYMH
            M = IADR + IHKLS(4, I)
C * CALCULATE STRUCTURE FACTOR
            ISN = IHKLS(5, I)
            IHQ = IHKLS(1, I) * ISN
            IKQ = IHKLS(2, I) * ISN
            ILQ = IHKLS(3, I) * ISN
            F4  = PHIS(I) * RGBL(6)
            IF (I == 1) THEN
              CALL PLA137 (IHQ, IKQ, ILQ, ACAL, BCAL, ACALA, BCALA,
     1          ACALAF, BCALAF, SNTHA)
              IF (IPR(210) == 2) THEN
                ACAL = ACAL + ASOL
                BCAL = BCAL + BSOL
              END IF
              FC1    = SQRT (ACAL**2   + BCAL**2)
              FC2    = SQRT (ACALA**2  + BCALA**2)
              FC3    = SQRT (ACALAF**2 + BCALAF**2)
              F1     = ATAN2 (BCAL,   ACAL)   * RGBL(6)
              F2     = ATAN2 (BCALA,  ACALA)  * RGBL(6)
              F3     = ATAN2 (BCALAF, ACALAF) * RGBL(6)
            ELSE
              F1I    = MOD (F1 + F4 + 360.0, 360.0) / RGBL(6)
              F2I    = MOD (F2 + F4 + 360.0, 360.0) / RGBL(6)
              F3I    = MOD (F3 - F4 + 360.0, 360.0) / RGBL(6)
              ACAL   = FC1 * COS (F1I)
              BCAL   = FC1 * SIN (F1I)
              ACALA  = FC2 * COS (F2I)
              BCALA  = FC2 * SIN (F2I)
              ACALAF = FC3 * COS (F3I)
              BCALAF = FC3 * SIN (F3I)
            END IF
C * CORRECT (SUBSTRACT) ANOMALOUS DISPERSION FROM F(obs) [X-RAYS]
            IF (IPR(493) < 7) THEN
              IF (IPR(210) == 2) THEN
                ACALT = ACAL + ACALA
                BCALT = BCAL + BCALA
              ELSE
                ACALT = ACAL + ACALA + ASOL
                BCALT = BCAL + BCALA + BSOL
              END IF
              XCAL  = ACALT ** 2 + BCALT ** 2
C * HANDLE FLACK PARAMETER
              IF (PAR(433) < 999999.0) THEN
                IF (IPR(210) == 2) THEN
                  ZCAL = ( ACAL + ACALAF)**2
     1                 + (-BCAL + BCALAF)**2
                ELSE
                  ZCAL = ( ACAL + ASOL + ACALAF)**2
     1                 + (-BCAL - BSOL + BCALAF)**2
                END IF
                XFCAL = MAX (0.0,
     1                  (1.0 - PAR(433)) * XCAL + PAR(433) * ZCAL)
              ELSE
                XFCAL = XCAL
              END IF
              FCALT = SQRT (ACALT ** 2 + BCALT ** 2)
              FOBSX = SQRT ((FOBS * ACALT / FCALT - ACALA) ** 2 +
     1                      (FOBS * BCALT / FCALT - BCALA) ** 2)
            ELSE
              XFCAL = ACAL ** 2 + BCAL ** 2
              FOBSX = FOBS
            END IF
C * CALCULATE R, wR2, S CONTRIBUTIONS
            IF (I == 1) THEN
              NRF1 = NRF1 + 1
              IF (XI > PAR(484) * SGI) THEN
                SUM1 = SUM1 + ABS (FOBS - SQRT (XFCAL))
                SUM2 = SUM2 + FOBS
                NRF  = NRF  + 1
              END IF
              SGIK = SIGIW ** 2
              IF (IPR(698) /= 0) THEN
                XI    = XI    * FACTOR**2
                XFCAL = XFCAL * FACTOR**2
              END IF
C * AVOID SIGMA = 0.0 (e.g. LIST 3)
              IF (SGIK > 0.0001) THEN
                SUM3 = SUM3 + ((XI - XFCAL) ** 2) / SGIK
                SUM4 = SUM4 + (XI ** 2) / SGIK
              END IF
            END IF
            IF (SIGXI > 0.0) THEN
              WGHT = 1.0 / SIGXI**2
            ELSE
              WGHT = 0.0
            END IF
            IF (NINT (VOID(M)) == 0) THEN
              IH = IHKLS(1, I)
              IK = IHKLS(2, I)
              IL = IHKLS(3, I)
C * STORE REFLECTION DATA BOTTOM UP
              VOID(NIND + 1)  = WGHT * FOBSX
              VOID(NIND + 2)  = SIGXI
              VOID(NIND + 3)  = ACAL
              VOID(NIND + 4)  = BCAL * ISN
C * SOLVENT AREA CONTRIBUTION
              VOID(NIND + 5)  = 0.0
              VOID(NIND + 6)  = 0.0
C * DIFF-MAP COEFFICIENTS
              VOID(NIND + 7)  = 0.0
              VOID(NIND + 8)  = 0.0
              VOID(NIND + 9)  = IH
              VOID(NIND + 10) = IK
              VOID(NIND + 11) = IL
              VOID(NIND + 12) = ACALA
              VOID(NIND + 13) = BCALA
              VOID(NIND + 14) = SQRT (GEN095 (PAR(191), IH, IK, IL))
              CALL PLA136 (0, IH, IK, IL, IASM)
              VOID(NIND + 15) = 2 * IASM - 1
              VOID(NIND + 16) = WGHT
              NREFA           = NREFA + 1
              NIND            = NIND  + NP69
C * STORE REFERENCE
              VOID(M) = NREFA
C * CHECK FOR SCRATCH ARRAY OVERRUN
              IF (NIND + NP69 >= IADR) THEN
                IF (IGBL(63) > 0) THEN
                  WRITE (LU6, 99998, IOSTAT = IOST)
     1              NIND, IADR, NVDR, CHAR (IPR(223))
                  WRITE (LU7, 99998, IOSTAT = IOST)
     1              NIND, IADR, NVDR, CHAR (IPR(223))
                END IF
C * ERROR/PROBLEM
                NREFA = -1
                RETURN
              END IF
            ELSE
C * FIND INDEX IN REFLECTION DATA STORAGE
              N            = (NINT(VOID(M)) - 1) * NP69
              VOID(N + 1)  = VOID(N +  1) + WGHT * FOBSX
              VOID(N + 16) = VOID(N + 16) + WGHT
            END IF
          END DO
        ELSE
          NEXT = NEXT + 1
        END IF
      END DO
      IF (NRF1 < IPR(266) + IPR(767)) THEN
C * ERROR/PROBLEM
        NREFA = -1
        RETURN
      END IF
      IF (SUM2 /= 0.0) PAR(480) = SUM1 / SUM2
      IF (SUM4 /= 0.0) PAR(481) = SQRT (SUM3 / SUM4)
      JUNK = NRF1 - IPR(266) - IPR(767)
      IF (JUNK /= 0) PAR(482) = SQRT (SUM3 / JUNK)
      IPR(625) = NRF
      IPR(626) = NRF1
      IF (IGBL(9) .NE. 0) THEN
        IF (IGBL(63) > 0) THEN
          WRITE (LU6, 99997, IOSTAT = IOST)
     1      PAR(480), NRF, PAR(481), NRF1, PAR(482)
          CALL PLA262 (5)
          WRITE (LU7, 99997, IOSTAT = IOST)
     1      PAR(480), NRF, PAR(481), NRF1, PAR(482)
        END IF
      END IF
C * CHECK FOR SHELXL WEIGHT PARAMETERS AND TWINNING
      IF (PAR(493) >= 0.0 .AND. IPR(619) == 0) THEN
C * CHECK ONLY FOR NON-NEUTRON
        IF (IPR(493) < 7) THEN
C * CHECK FOR JANA WEIGHT + EXTINCTION
          IF (IPR(632) /= 2 .OR. PAR(229) <= 0.0) THEN
            IF (IPR(651) == 0 .AND. ABS (PAR(481)) > 0.001) THEN
              YUNK = PAR(173) - PAR(480)
C * SUPPRESS ALERTS FOR MOPRO & IDEAL & anharm & Pseudo Flack Twin
              IF (IPR(725) /= 9 .AND. IPR(667) /= -1 .AND.
     1            IPR(756) == 0 .AND. IPR(757) == 0 .AND.
     2            IPR(779) == 0) THEN
C * ALERT _926 - COMPARE REPORTED AND CALCULATED R-VALUE DIFFERENCE
                IF (ABS (YUNK) > 0.001 .AND. IPR(775) == 0)
     1            CALL PLA236 (926, 4, ABS (YUNK), YUNK, ' ', ' ')
              YUNK = PAR(174) - PAR(481)
C * ALERT _927 - COMPARE REPORTED AND CALCULATED wR2-VALUE DIFFERENCE
                IF (ABS (YUNK) > 0.001 .AND. IPR(775) == 0)
     1            CALL PLA236 (927, 4, ABS (YUNK), YUNK, ' ', ' ')
              YUNK = PAR(299) - PAR(482)
C * ALERT _928 - COMPARE REPORTED AND CALCULATED S-VALUE DIFFERENCE
                IF (ABS (YUNK) > 0.005 .AND. IPR(775) == 0)
     1            CALL PLA236 (928, 3, ABS (YUNK), YUNK, ' ', ' ')
              END IF
            END IF
          END IF
        END IF
      END IF
C * AVERAGE
      NREFB = NREFA
      IADD  = LMAX * MHK + KMAX * MPH + HMAX
      DO I = 1, MHKLH
        K = NINT (VOID(IADR + I))
        IF (K /= 0) THEN
          K = (K - 1) * NP69
          IF (VOID(K + 16) > 0.0) THEN
            VOID(K + 1) = VOID(K + 1) / VOID(K + 16)
          ELSE
            VOID(K + 1) = 0.0
          END IF
        ELSE
C * HANDLE MISSING REFLECTION IN SQUEEZE CASE (I.E. APPEND REFL. RECORD)
          IF (.TRUE.) THEN
            IH = I  + IADD
            IL = IH / MHK
            IH = IH - IL * MHK
            IL = IL - LMAX
            IK = IH / MPH
            IH = IH - IK * MPH - HMAX
            IK = IK - KMAX
C * CHECK FOR BRAVAIS AND SPACE GROUP ABSENCES
            SGX(1)  = IH
            SGX(2)  = IK
            SGX(3)  = IL
            SGX(12) = 0.0
            CALL SGSM (27, LINE, SGX, 0, 0, IERR)
            IF (NINT (SGX(12)) /= 0) CYCLE
            CALL PLA136 (0, IH, IK, IL, IASM)
            STL = SQRT(GEN095 (PAR(191), IH, IK, IL))
C * TEST AGAINST SIN(THETA)/LAMBDA-MAX + TOLERANCE
            IF (STL < (PAR(287) + PAR(442))) THEN
C * STORE REFLECTION DATA BOTTOM UP
              VOID(NIND + 1)  = 0.0
              VOID(NIND + 2)  = 0.0
              VOID(NIND + 3)  = 0.0
              VOID(NIND + 4)  = 0.0
C * SOLVENT AREA CONTRIBUTION
              VOID(NIND + 5)  = 0.0
              VOID(NIND + 6)  = 0.0
C * DIFF-MAP COEFFICIENTS
              VOID(NIND + 7)  = 0.0
              VOID(NIND + 8)  = 0.0
              VOID(NIND + 9)  = IH
              VOID(NIND + 10) = IK
              VOID(NIND + 11) = IL
              VOID(NIND + 14) = STL
              VOID(NIND + 15) = FLOAT (IASM) * 2 - 1
              NREFA           = NREFA + 1
              NIND            = NIND  + NP69
              VOID(IADR + I)  = NREFA
C * CHECK FOR SCRATCH ARRAY OVERRUN
              IF (NIND + NP69 >= IADR) THEN
                IF (IGBL(63) > 0) THEN
                  WRITE (LU6, 99998, IOSTAT = IOST)
     1              NIND, IADR, NVDR, CHAR (IPR(223))
                  WRITE (LU7, 99998, IOSTAT = IOST)
     1              NIND, IADR, NVDR, CHAR (IPR(223))
                END IF
C * ERROR/PROBLEM
                NREFA = -1
                RETURN
              END IF
C * CHECK FOR IN ASYMMETRIC REFLECTION UNIT (IASM = 1)
              IF (IASM /= 0) THEN
C * COUNT NUMBER OF MISSING REFLECTIONS
                IF (STL <= PAR(486)) THEN
                  TH = ASIN (STL * PAR(17)) * RGBL(6)
                  IF (IPR(610) < NP60) THEN
C * COUNT NUMBER OF MISSING LOW ORDER REFLECTIONS (AND REGISTER)
                    IPR(610)             = IPR(610) + 1
                    MISSING(1, IPR(610)) = IH
                    MISSING(2, IPR(610)) = IK
                    MISSING(3, IPR(610)) = IL
                    MISSING(4, IPR(610)) = NINT (TH * 1000)
C * WRITE HEADER
                    IF (IPR(610) == 1) THEN
                      CALL PLA262 (4)
                      WRITE (LU6, 99995, IOSTAT = IOST) PAR(486)
                      WRITE (LU7, 99995, IOSTAT = IOST) PAR(486)
                    END IF
                    CALL PLA262 (1)
                    WRITE (LU6, 99994, IOSTAT = IOST)
     1                IPR(610), IH, IK, IL, TH
                    WRITE (LU7, 99994, IOSTAT = IOST)
     1                IPR(610), IH, IK, IL, TH
                  END IF
                END IF
              END IF
            END IF
          END IF
        END IF
      END DO
C * REPORT REFLECTION STATISTICS
      IPR(609) = IPR(553) + IPR(555) + IPR(557)
      IF (IGBL(63) > 0) THEN
        WRITE (LU6, 99999, IOSTAT = IOST)
     1    NEXT, NREF - NEXT, IPR(609), IPR(610)
        CALL PLA262 (5)
        IPR(712) = NREF - NEXT
        WRITE (LU7, 99999, IOSTAT = IOST)
     1    NEXT, IPR(712), IPR(609), IPR(610)
      END IF
      RETURN
99999 FORMAT (/,
     1        ':: Number of Removed Systematic Absences    = ', I7, /,
     2        ':: Number of Non-Syst.Absence   Reflections = ', I7, /,
     3        ':: Number of Missing            Reflections = ', I7, /,
     4        ':: Number of Missing Low Order  Reflections = ', I7)
99998 FORMAT (/, 'F: Scratch Array Overrun (NXX,IADR,NVDR =)', 3I6, /,
     1        3X, 'Use larger program version i.e. recompile with ',
     2        'larger NVDR', A, /)
99997 FORMAT (/, ':: R1   =', F9.4, ' for', I6,
     1        ' Refl. with I > 2 s(I) and', /,
     2        ':: wR2  =', F9.4, ' for', I6, ' reflections', /,
     3        ':: S    =', F9.4, /)
99996 FORMAT (/, ':: Problem Reading .hkp File in PLA130.', /)
99995 FORMAT (/, 'Missing Reflections Below sin(theta)/lambda=', F5.2,
     1        /, 47('='), /,
     2        '   N    H    K    L     Theta', /, 29('='))
99994 FORMAT (I4, 3I5, F10.2)
99993 FORMAT (/, '** REWIND PROBLEM OF FILE LU27 ** - STOP')
      END SUBROUTINE PLA130
      SUBROUTINE PLA131 (MLOOP)
C * HYBRID: SQUEEZE/SHELXL201n CYCLE BASED ON SUPPLIED SHELX201n <name>.cif
      USE files
      USE parameters
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: LU
      INTEGER :: MLOOP
      INTEGER :: NLOOP
      INTEGER :: NLOOPMAX
      REAL, DIMENSION(10, 7) :: RESULTX
      CHARACTER(len=80)  :: DUM
      CHARACTER(len=132) :: DUMA
      DO J = 1, 7
        RESULTX(1, J) = 0.0
      END DO
      IF (IPR(221) > 0) IPR(682) = MIN (10, MLOOP)
      IGBL(31) = 10
C * CHECK FOR SHELXL201n CIF OR INS/RES + HKL
C * SHELXL201n CIF WITH EMBEDDED .res & .hkl test)
      IF (IABS(IGBL(8)) == 3 .AND. IPR(663) /= 0
     1  .AND. IPR(664) /= 0) THEN
        CLOSE (UNIT = LU24)
        CLOSE (UNIT = LU25)
        CLOSE (UNIT = LU26)
        CLOSE (UNIT = LU1)
        CLOSE (UNIT = LU16)
        OPEN (LU1,  FILE = NAMEFIL(1:KNMFIL)//'_sx.ins',
     1    STATUS = 'UNKNOWN')
        OPEN (LU16, FILE = NAMEFIL(1:KNMFIL)//'_sx.hkl',
     1    STATUS = 'UNKNOWN')
C * INS/RES + HKL
      ELSE IF (IGBL(29) /= -1) THEN
        IPR(2) = 71
        IF (IPR(2) == 0) IPR(2) = -1
C * ERROR HANDLING
        IGBL(1) = 3
        RETURN
      END IF
C * CREATE SCRATCH .INS & .HKL FILES FOR SHELXL201n REFINEMENT
      OPEN (LU62, FILE = 'x_dummy.hkl', STATUS = 'UNKNOWN')
      REWIND (UNIT = LU16, IOSTAT = IOST)
      DO
        READ (LU16, 99999, IOSTAT = IOST) DUM
        IF (IOST /= 0) EXIT
        WRITE (LU62, 99999) DUM
      END DO
      IF (IGBL(29) > 0) THEN
        CLOSE (UNIT = LU16, STATUS = 'DELETE')
      ELSE
        CLOSE (UNIT = LU16)
      END IF
      CLOSE (UNIT = LU62)
C * OUTER REFINEMENT LOOP - GET NUMBER OF MAJOR REFINEMENT LOOPS
      LU       = LU1
      NLOOP    = 1
      NLOOPMAX = IPR(682)
      DO
        OPEN (LU62, FILE = 'x_dummy.ins', STATUS = 'UNKNOWN')
        REWIND (UNIT = LU, IOSTAT = IOST)
        DO
          READ (LU, 99999, IOSTAT = IOST) DUM
          IF (IOST /= 0) EXIT
          IF (DUM(1:3) == 'REM') THEN
          ELSE IF (DUM(1:4) == 'L.S.') THEN
            CALL GEN072 (DUM, IFL, FN, KL, KN, 0, 0, 1, 5, 80, 7, NP17)
            WRITE (LU62, 99995) (IPR(619) + 1) * 4
            FN(1) = 5
            WRITE (DUM, 99996) 'L.S.', (NINT (FN(I)), I = 1, KN)
            WRITE (LU6, 99999) ':: Substituted:'//DUM(1:65)
          ELSE IF (DUM(1:4) == 'LIST') THEN
            CYCLE
          ELSE IF (DUM(1:4) == 'ACTA') THEN
            CYCLE
          ELSE IF (DUM(1:4) == 'DAMP') THEN
            WRITE (LU6, 99999) 'Deleted:    '//DUM(1:65)
            CYCLE
          ELSE IF (DUM(1:4) == 'MORE') THEN
            WRITE (LU6, 99999) 'Deleted:    '//DUM(1:65)
            CYCLE
          ELSE IF (DUM(1:4) == 'WPDB') THEN
            WRITE (LU6, 99999) 'Deleted:    '//DUM(1:65)
            CYCLE
          ELSE IF (DUM(1:4) == 'OMIT') THEN
            CALL GEN072 (DUM, IFL, FN, KL, KN, 0, 0, 1, 5, 80, 7, NP17)
            IF (KN == 3)
     1         WRITE (LU6, 99999) ':: Omitted:   '//DUM(1:65)
          END IF
          WRITE (LU62, 99999) DUM
        END DO
        IF (IPR(663) /= 0) THEN
          CLOSE (UNIT = LU, STATUS = 'DELETE')
          IPR(663) = 0
        ELSE
          CLOSE (UNIT = LU)
        END IF
        CLOSE (UNIT = LU62)
C * REFINE AND CREATE .cif AND .fcf IN A SPAWNED SHELXL201n JOB
        KERR = 0
        CALL SPAWN (SHLPATH(1:IGBL(110))//' x_dummy', LU6, .true., KERR)
        IF (KERR /= 0) WRITE (6, 99994)
C * REGISTER REFINEMENT RESULTS
        OPEN (LU61, FILE = 'x_dummy.cif', STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99999, IOSTAT = IOST) DUM
          IF (IOST /= 0) EXIT
          IF (DUM(1:22) == '_refine_ls_R_factor_gt') THEN
            READ (DUM(34:40), *) RESULTX(NLOOP, 1)
          ELSE IF (DUM(1:24) == '_refine_ls_wR_factor_ref') THEN
            READ (DUM(34:40), *) RESULTX(NLOOP, 2)
          ELSE IF (DUM(1:30) == '_refine_ls_goodness_of_fit_ref') THEN
            READ (DUM(34:40), *) RESULTX(NLOOP, 3)
          ELSE IF (DUM(1:24) == '_refine_diff_density_max') THEN
            READ (DUM(25:33), *) RESULTX(NLOOP, 4)
          ELSE IF (DUM(1:24) == '_refine_diff_density_min') THEN
            READ (DUM(25:33), *) RESULTX(NLOOP, 5)
            EXIT
          END IF
        END DO
        CLOSE (UNIT = LU61)
C * RUN SPAWNED PLATON/SQUEEZE JOB
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -q x_dummy.cif', LU6, .true.,
     1    KERR)
        IF (KERR /= 0) WRITE (6, 99993)
C * REGISTER SQUEEZE RESULT
        OPEN (LU61, FILE = 'x_dummy_sq.sqz', STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99999, IOSTAT = IOST) DUM
          IF (IOST /= 0) EXIT
          IF (DUM(1:9) == '# Solvent') THEN
            READ (DUM(30:39), *) RESULTX(NLOOP, 7)
          ELSE IF (DUM(1:11) == '# Electrons') THEN
            READ (DUM(30:39), *) RESULTX(NLOOP, 6)
            EXIT
          END IF
        END DO
        CLOSE (UNIT = LU61)
C * TERMINATION TEST AND HANDLING
        IF (NLOOP > 1) THEN
          IF (NINT (RESULTX(NLOOP, 6)) == NINT (RESULTX(NLOOP - 1, 6)))
     1      NLOOPMAX = NLOOP
        END IF
        IF (NLOOP < NLOOPMAX) THEN
          NLOOP = NLOOP + 1
C * COPY HKL & RES FILES FOR SCRATCH USE
C * COPY FAB FILE
          OPEN (LU61, FILE = 'x_dummy_sq.fab', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = 'x_dummy.fab',    STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUM
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUM
          END DO
          CLOSE (UNIT = LU61)
          CLOSE (UNIT = LU62)
C * COPY 'RES' FILE
          OPEN (LU61, FILE = 'x_dummy_sq.ins', STATUS = 'UNKNOWN')
          LU = LU61
        ELSE
C * FINAL FILE RENAME TO NAME_sq.ins
          OPEN (LU61, FILE = 'x_dummy_sq.ins', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.ins',
     1      STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUM
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUM
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
C * FINAL FILE RENAME TO NAME_sq.hkl
          OPEN (LU61, FILE = 'x_dummy_sq.hkl', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.hkl',
     1      STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUM
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUM
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
C * FINAL FILE RENAME TO NAME_sq.fab
          OPEN (LU61, FILE = 'x_dummy_sq.fab', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.fab',
     1      STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUM
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUM
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
C * FINAL FILE RENAME TO NAME_sq.sqz
          OPEN (LU61, FILE = 'x_dummy_sq.sqz', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.sqz',
     1      STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUM
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUM
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
C * FINAL FILE RENAME TO NAME_sq.sqf
          OPEN (LU61, FILE = 'x_dummy_sq.sqf', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.sqf',
     1      STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUM
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUM
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
C * FINAL FILE RENAME TO NAME_sq.lis
          OPEN (LU61, FILE = 'x_dummy_sq.lis', STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_sq.lis',
     1      STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99999, IOSTAT = IOST) DUMA
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99999) DUMA
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
C * REMOVE INTERMEDIATES
          OPEN (LU61, FILE = 'x_dummy.ins', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.res', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.eld', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.fab', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.hkl', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.cif', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.lst', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          OPEN (LU61, FILE = 'x_dummy.fcf', STATUS = 'UNKNOWN')
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          WRITE (LU6, 99998)
          DO I = 1, NLOOPMAX
            WRITE (LU6, 99997) I, (RESULTX(I, J), J = 1, 5),
     1        (NINT (RESULTX(I, J)), J = 6, 7)
          END DO
          IF (IPR(2) == 0) IPR(2) = -1
C * ERROR HANDLING
          IGBL(1) = 3
          EXIT
        END IF
      END DO
      RETURN
99999 FORMAT (A)
99998 FORMAT (//, ':: HYBRID: SQUEEZE/SHELXL LOOP RESULTS', //,
     1 '  -------------S.H.E.L.X.L.2.0.n.m--------- -----SQUEEZE----',/,
     1 '  CYC      R1     wR2       S RhoMax RhoMin Electrons Volume')
99997 FORMAT (I5, 3F8.4, 2F6.2, 2I8)
99996 FORMAT (A, I3, 10I5)
99995 FORMAT ('ACTA', /, 'LIST', I3)
99994 FORMAT (/, '*** PROBLEM WITH SPAWNING OF SHELXL JOB', /)
99993 FORMAT (/, '*** PROBLEM WITH SPAWNING PLATON/SQUEEZE JOB', /)
      END SUBROUTINE PLA131
 
      SUBROUTINE PLA132 (IH, IK, IL, XI, SIGI, SIGIW, CALI, UCINT,
     1 ACALS, BCALS)
C * GET REFLECTION DATA FROM VARIOUS FCF & HKL FILE FORMATS
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE mentry
      USE fab
      USE sgxyz
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: M
      INTEGER       :: NB
      INTEGER       :: NE
      INTEGER       :: IH
      INTEGER       :: IK
      INTEGER       :: IL
      INTEGER       :: ID1
      INTEGER       :: ID2
      INTEGER, SAVE :: IH0
      INTEGER, SAVE :: IK0
      INTEGER, SAVE :: IL0
      INTEGER       :: NCR
      INTEGER       :: NBAT
      INTEGER       :: IDIF
      INTEGER       :: IDTW
      INTEGER, SAVE :: HMAX
      INTEGER, SAVE :: KMAX
      INTEGER, SAVE :: LMAX
      INTEGER       :: IDIND
      INTEGER       :: IOSTY
      INTEGER       :: IYUNK
      INTEGER       :: NSKIP
      INTEGER       :: MARKER
      INTEGER       :: GEN135
      REAL :: XI
      REAL :: YI
      REAL :: FC
      REAL :: TH
      REAL :: YI1
      REAL :: YI2
      REAL :: ACAL
      REAL :: BCAL
      REAL :: DLDS
      REAL :: SIGI
      REAL :: CALI
      REAL :: STHK
      REAL :: YUNK
      REAL :: SIGIW
      REAL :: XFCAL
      REAL :: XFOBS
      REAL :: XSIGI
      REAL :: UCINT
      REAL :: ACALS
      REAL :: BCALS
      REAL :: XSIGIW
      REAL :: GEN095
      REAL :: PLA179
      REAL, DIMENSION(2) :: XINT
      CHARACTER(len=5) :: CNT
      CHARACTER(len=4) :: FOFC
      CHARACTER(len=4) :: INEX
      CHARACTER(len=1) :: STATUSX
C * IEND = -1 : Initialize
C *      =  0 : Next Reflection
C *      =  1 : Termination
      CALI   = 0.0
      UCINT  = 0.0
      ACALS  = 0.0
      BCALS  = 0.0
      ABSCOR = 1.0
C * INITIALIZE
      IF (IEND == -1) THEN
        ISKIP    = 0
        ITSKP    = 0
        SHXMP    = 1.0
        PAR(166) = 0.0
C * CHECK FOR HKL GENERATE MODE
        IF (IPR(408) == 1) THEN
          PAR(287) = PAR(540)
          PAR(165) = ASIN (MIN (1.0, PAR(287) * PAR(17))) * RGBL(6)
C * CHECK EXPECT MODE
        ELSE IF (IPR(408) == 2 .AND. PAR(168) > 0.0) THEN
          PAR(165) = PAR(168)
          IF (PAR(17) > 0)
     1      PAR(287) = SIN (PAR(165) / RGBL(6)) / PAR(17)
        END IF
        STHKM = (SIN (PAR(165) / RGBL(6)) / PAR(17))**2
C * HANDLE HKL TRANSFORMATION MATRICES
        IF (IABS (IGBL(8)) /= 2) THEN
C * COPY TM1 TO TRMX
          CALL GEN052 (TM1, TRMX)
        ELSE
C * SHELX-HKLF MATRIX
          IF ((IGBL(9) <= 0 .OR. IABS (IGBL(8)) == 2) .AND.
     1        IPR(408) /= 2) THEN
            K = 230
            DO I = 1, 3
              DO J = 1, 3
                K = K + 1
                TRMX(I, J) = PAR(K)
              END DO
            END DO
          ELSE
C * INIT TO UNIT MATRIX
            CALL GEN021 (TRMX, 1.0)
          END IF
        END IF
        UNITMAT = GEN135 (TRMX)
        WRITE (LU6, 99981, IOSTAT = IOST)
     1    ((TRMX(I, J), J = 1, 3), I = 1, 3)
        WRITE (LU6, 99979, IOSTAT = IOST) (PAR(I), I = 101, 106)
        CALL GEN074 (V2, 1, 3, 0.0)
        CALL GEN074 (V3, 1, 3, 0.0)
        NDEC = 0
C * GET REFLECTION DATA - SHELX(L) HKLF 4 FORMAT or FCF-CIF
        IF (IPR(408) <= 0) THEN
          IF (IGBL(9) == 0) THEN
            FOFC = 'Iobs'
          ELSE
            FOFC = 'FoFc'
            IF (IPR(132) == 0) THEN
              FOFC = ' OBS'
            ELSE IF (IPR(132) == 1) THEN
              FOFC = 'CALC'
            ELSE IF (IPR(132) == 2) THEN
              FOFC = 'DELT'
            ELSE IF (IPR(132) == 3) THEN
              FOFC = 'DELG'
            END IF
          END IF
          WRITE (LU6, 99998, IOSTAT = IOST) FNLU16(1:KNM16), FOFC
          IF (IGBL(63) > 0) THEN
            CALL PLA262 (2)
            WRITE (LU7, 99998, IOSTAT = IOST) FNLU16(1:KNM16), FOFC
          END IF
C * REWIND
          CALL GEN108 (LU16, 0)
C * FCF-CIF (SHELXL ETC.)
C * LOAD MATCHING DATA-SET
          IGBL(9) = IENTRY(IGBL(54), 3)
          IF (IGBL(9) > 0) THEN
            NSKIP = IENTRY(IGBL(54), 4)
            IF (NSKIP > 0) THEN
              DO I = 1, NSKIP
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) EXIT
                IF (IABS (IGBL(8)) /= 3) GO TO 10
              END DO
              GO TO 10
            END IF
            IPR(2) = 69
C * OPEN FCF-CHECK OUTPUT
            INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.ckf',
     1               OPENED = OPEND)
            IF (.NOT. OPEND) THEN
              OPEN (UNIT = LU13, FILE = NAMEFIL(1:KNMFIL) //'.ckf',
     1              STATUS = 'UNKNOWN')
            END IF
C * COUNT # 900 ALERTS
            IPR(659) = IPR(659) + 1
            IF (IPR(659) == 1) THEN
              WRITE (LU13, 99990, IOSTAT = IOST) JID(1:10)
C * ALERT _900
              CALL PLA236 (900, 0, 1.0, 1.0, ' ', ' ')
              CALL PLA015 (0, 51)
            END IF
            IEND = 1
            RETURN
          END IF
C * HANDLE FILE TYPE HEADER SECTION UP TO FIRST REFLECTION DATA
   10     SELECT CASE (IGBL(9))
C * FCF TYPE 1 - SHELXL
            CASE (1)
              SHXMP = 1.0
              NDEC  = 2
              ICALC = 0
              IOBS  = 0
              IDIF  = 0
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST == 0) THEN
                  IF (INDEX (IDM, 'cell_') /= 0) THEN
                    IF (PAR(101) > 0.0 .AND. IABS (IGBL(8)) == 3)
     1                THEN
C * REMOVE SU WHEN PRESENT
                      M = INDEX (IDM, '(')
                      IF (M /= 0) IDM(M:) = '        '
                      NB = INDEX (IDM, '_cell_length_a')
                      IF (NB /= 0) THEN
                        READ (IDM(NB + 14:), *, IOSTAT = IOST) PAR(455)
                        DLDS = MAX (0.01, PAR(107) * 2.0)
                        IF (ABS (PAR(455) - PAR(101)) > DLDS .OR.
     1                    IOST /= 0) IDIF = IDIF + 1
                      ELSE
                        NB = INDEX (IDM, '_cell_length_b')
                        IF (NB /= 0) THEN
                          READ (IDM(NB + 14:), *, IOSTAT = IOST)
     1                      PAR(456)
                          DLDS = MAX (0.01, PAR(108) * 2.0)
                          IF (ABS(PAR(456) - PAR(102)) > DLDS .OR.
     1                      IOST /= 0) IDIF = IDIF + 1
                        ELSE
                          NB = INDEX (IDM, '_cell_length_c')
                          IF (NB /= 0) THEN
                            READ (IDM(NB + 14:), *, IOSTAT = IOST)
     1                        PAR(457)
                            DLDS = MAX (0.01, PAR(109) * 2.0)
                            IF (ABS(PAR(457) - PAR(103)) > DLDS .OR.
     1                        IOST /= 0) IDIF = IDIF + 1
                          ELSE
                            NB = INDEX (IDM, '_cell_angle_alpha')
                            IF (NB /= 0) THEN
                              READ (IDM(NB + 17:), *, IOSTAT = IOST)
     1                              PAR(458)
                              DLDS = MAX (0.01, PAR(110) * 2.0)
                              IF (ABS(PAR(458) - PAR(104)) > DLDS
     1                          .OR. IOST /= 0) IDIF = IDIF + 1
                            ELSE
                              NB = INDEX (IDM, '_cell_angle_beta')
                              IF (NB /= 0) THEN
                                READ (IDM(NB + 16:), *, IOSTAT = IOST)
     1                                PAR(459)
                                DLDS = MAX (0.01, PAR(111) * 2.0)
                                IF (ABS(PAR(459) - PAR(105)) > DLDS
     1                            .OR. IOST /= 0) IDIF = IDIF + 1
                              ELSE
                                NB = INDEX (IDM, '_cell_angle_gamma')
                                IF (NB /= 0) THEN
                                  READ (IDM(NB + 17:), *, IOSTAT = IOST)
     1                                  PAR(460)
                                  DLDS = MAX (0.01, PAR(112) * 2.0)
                                  IF (ABS (PAR(460) - PAR(106))
     1                              > DLDS .OR. IOST /= 0)
     2                              IDIF = IDIF + 1
                                END IF
                              END IF
                            END IF
                          END IF
                        END IF
                      END IF
                      IF (IDIF > 0) THEN
C * ALERT _901
                        IPR(674) = IPR(674) + 1
                        IPR(676) = 0
                        IF (IPR(674) == 1)
     1                    CALL PLA236 (901, 0, 1.0, 1.0, ' ', ' ')
                        IF (IGBL(22) == -1) THEN
                          WRITE (LU13, 99984, IOSTAT = IOST)
     1                      (PAR(M), M = 455, 460)
                          WRITE (LU13, 99986, IOSTAT = IOST)
                        END IF
                        IPR(2) = 76
                        IEND   = 2
                        RETURN
                      END IF
                    END IF
                  ELSE IF (INDEX (IDM, '_refln_F_squared_calc') /= 0)
     1                       THEN
                    IF (IOBS == 1) THEN
                      ICALC = 2
                    ELSE
                      ICALC = 1
                    END IF
                  ELSE IF (INDEX (IDM, '_refln_F_squared_meas') /= 0)
     1                     THEN
                    IF (ICALC == 1) THEN
                      IOBS = 2
                    ELSE
                      IOBS = 1
                    END IF
                  ELSE IF (INDEX (IDM, '_shelx_F_squared_multiplier')
     1                   /= 0) THEN
                    IYUNK = INDEX (IDM, '_shelx_F_squared_multiplier')
                    READ (IDM(IYUNK + 27:80), *, IOSTAT = IOST) SHXMP
                    IF (IOST /= 0) THEN
                      IEND = 1
                      RETURN
                    END IF
                  ELSE IF (INDEX (IDM, '_refln_observed_status') /= 0
     1                .OR. INDEX (IDM, '_refln_include_status') /= 0)
     2                     THEN
                    DO
                      READ (LU16, 99997, IOSTAT = IOST) IDM
                      IF (IOST /= 0) THEN
                        IEND = 1
                        RETURN
                      END IF
                      IF (INDEX (IDM, '_refln_sint/lambda') == 0) EXIT
                    END DO
                    BACKSPACE LU16
                    EXIT
                  ELSE IF (INDEX (IDM, '_twin_refln') /= 0) THEN
                    IEND = 1
                    RETURN
                  END IF
                ELSE
                  IEND = 1
                  RETURN
                END IF
              END DO
              IF (IPR(132) == 0 .AND. IOBS == 0 .OR.
     1            IPR(132) == 1 .AND. ICALC == 0) THEN
                IEND = 1
                RETURN
              END IF
C * FCF TYPE 2 - XTAL Fobs/Fcal
            CASE (2)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_scale_group_code') /= 0) EXIT
              END DO
              NDEC = 3
C * FCF TYPE 3 - NRCVAX
            CASE (3)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_F_squared_sigma') /= 0) EXIT
              END DO
              IOBS  = 1
              ICALC = 2
              NDEC  = 3
C * FCF TYPE 4 - MOLEN
            CASE (4)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_10*F_sigm') /= 0 .OR.
     1              INDEX (IDM, '_refln_F_10*sigm') /= 0) EXIT
              END DO
              IOBS  = 1
              ICALC = 2
              NDEC  = 0
              FMOL  = '(I4,2I3,2F7.0,F6.0)'
   20         READ (LU16, 99997, IOSTAT = IOST) IDM
              IF (IOST /= 0) THEN
                IEND = 1
                RETURN
              END IF
              NB = 1
              NE = 80
              CALL GEN039 (1, IDM, 1, 80, NB, NE)
              IF (NE == 0) THEN
                GO TO 20
              ELSE IF (NE == 31) THEN
                FMOL(3:3) = '5'
              END IF
             BACKSPACE LU16
C * FCF TYPE 5, 8, 17, 18 - CRYSTALS
            CASE (5, 8, 17, 18)
              IF (IGBL(9) == 17 .OR. IGBL(9) == 18) THEN
                PAR(564) = 0.0
                IPR(764) = 0
              END IF
C * READ UP TO FIRST '_refln_ DATANAME
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_') /= 0) EXIT
              END DO
C * LOOK FOR SELECTED DATANAMES
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
C * LOOK FOR WEIGHT DATANAME
                IF (INDEX (IDM, '_refln_refinement_weight') /= 0) THEN
C * SET WEIGHT TYPE
                  IF (IPR(632) == 0) IPR(632) = 5
                END IF
                IF (INDEX (IDM, '_refln_') == 0) EXIT
              END DO
              IOBS  = 1
              ICALC = 2
              BACKSPACE LU16
C * FCF TYPE 6, 10, 13 & 15 - TEXSAN1 & TEXSAN2 & TEXSAN3 &  RIGAKU
            CASE (6, 10, 13, 15)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_observed_status') /= 0 .OR.
     1              INDEX (IDM, '_refln_include_status') /= 0) EXIT
              END DO
C * FCF TYPE 7 - MOLEN1
            CASE (7)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_observed_status') /= 0) EXIT
              END DO
              IOBS  = 1
              ICALC = 2
              FMOL  = '(3I4,3F8.0)'
              BACKSPACE LU16
C * FCF TYPE 9 & 14 - JANA2
            CASE (9, 14, 16)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_observed_status') /= 0 .OR.
     1              INDEX (IDM, '_refln_include_status') /= 0) EXIT
              END DO
C * FCF TYPE 11 - XD
            CASE (11)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
                IF (INDEX (IDM, '_refln_XD_refine_code') /= 0) EXIT
              END DO
C * FCF TYPE 12 - RAELS - Fobs/Fcalc/sigma
            CASE (12)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  IF (INDEX (IDM, '_refln_F_sigma') /= 0) EXIT
                END IF
              END DO
C * HKL TYPE 21 - SHELXL - LIST3
            CASE (21)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  IF (INDEX (IDM, '_refln_B_calc') /= 0) EXIT
                END IF
              END DO
C * HKL TYPE 22 - SHELXL - LIST5
            CASE (22)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  IF (INDEX (IDM, '_refln_phase_calc') /= 0) EXIT
                END IF
              END DO
C * HKL TYPE 23 - SHELXL - LIST6
            CASE (23)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  IF (INDEX (IDM, '_refln_phase_calc') /= 0) EXIT
                END IF
              END DO
C * HKL TYPE 24 - SHELXL - LIST7
            CASE (24)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  READ (IDM, *, IOSTAT = IOST)
     1              IYUNK, IYUNK, IYUNK, YUNK, YUNK, YUNK, YUNK
                END IF
              END DO
C * HKL TYPE
C * DUMMY STATEMENT
              YUNK = YUNK + FLOAT (IYUNK)
              BACKSPACE LU16
C * HKL TYPE 25 - SHELXL - LIST8
            CASE (25)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  IF (INDEX (IDM, '_shelx_refinement_sigma') /= 0) EXIT
                END IF
              END DO
C * TYPE JANA-TWIN
            CASE (27)
              DO
                READ (LU16, 99997, IOSTAT = IOST) IDM
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                ELSE
                  IF (INDEX (IDM, '_twin_refln_include_status') /= 0)
     1            EXIT
                END IF
              END DO
            CASE DEFAULT
C * HKL TYPE 0 & -1 - SHELX-HKL
              READ (LU16, 99997, IOSTAT = IOST) PRBUF(1:20)
              IF (IOST /= 0) THEN
                IEND = 1
                RETURN
              ELSE
C * REWIND LU16
                CALL GEN108 (LU16, 0)
                NDEC = INDEX (PRBUF(13:20), '.')
                IF (NDEC > 0) NDEC = 8 - NDEC
C * DETERMINE SHORT/LONG SHELX HKLF RECORD
                IF (IGBL(9) == -1) THEN
                  IF (IPR(210) == -1)
     1              WRITE (LU6, 99999, IOSTAT = IOST)
                END IF
              END IF
          END SELECT
          PAR(230) = 10**NDEC
        ELSE
C * GENERATE REFLECTION SERIES
          HMAX = INT (2 * PAR(101) * PAR(287)) + 1
          KMAX = INT (2 * PAR(102) * PAR(287)) + 1
          LMAX = INT (2 * PAR(103) * PAR(287)) + 1
          IH0  = - HMAX - 1
          IK0  = - KMAX - 1
          IF ((IPR(408) == 1 .AND. IPR(257) == 1) .OR.
     1         IPR(408) == 2) THEN
            IL0 = - LMAX - 1
          ELSE
            IL0 = -1
          END IF
          XI       = 100000.00
          SIGI     = 10.00
          SIGIW    = SIGI
          PAR(230) = 1.0
        END IF
      END IF
C * TRANSFORM REFLECTIONS FOR SF-CALCULATION (EXCLUDE NON-INTEGRAL H,K,L)
      IF (IPR(408) <= 0) THEN
C * REFLECTION READ LOOP
   30   READ (LU16, 99997, IOSTAT = IOST) PRBUF
        IF (IOST /= 0) THEN
          IEND = 1
          RETURN
        END IF
C * REMOVE DOS <CR>
        NCR = INDEX (PRBUF, CHAR (13))
        IF (NCR /= 0) PRBUF(NCR:NCR) = ' '
C * SELECT REFLECTION FILE TYPE
        SELECT CASE (IGBL(9))
C * HKL TYPE 0 - HKLF
          CASE (0)
            IF (IGBL(37) == 0) THEN
              READ (PRBUF, 99987, IOSTAT = IOST)
     1        IH, IK, IL, XI, SIGI, NBAT
            ELSE
              READ (PRBUF, 99987, IOSTAT = IOST)
     1        IH, IK, IL, XI, SIGI, NBAT, (V2(I), V3(I), I = 1, 3)
            END IF
            IF (IH == 0 .AND. IK == 0 .AND. IL == 0) THEN
              IEND = 1
              RETURN
            END IF
C * EXCLUDE TWIN COMPONENTS
            IF (NBAT < 0) GO TO 30
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (NBAT > 1 .AND. IPR(193) < 100) THEN
              IF (IPR(513) >= NBAT - 1 .AND. IPR(513) > 0) THEN
                XI   = BASF(NBAT - 1) * XI
                SIGI = BASF(NBAT - 1) * SIGI
              END IF
            END IF
            CALI  = XI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * HKL TYPE -1 - HKLF - EXTENDED
          CASE (-1)
            READ (PRBUF, 99996, IOSTAT = IOST) IH, IK, IL, XI, SIGI,
     1        (V2(I), V3(I), I = 1, 3), UCINT, ACALS, BCALS, ABSCOR
            IF (IOST == -1) GO TO 30
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * FCF TYPE 1 - SHELXL LIST 4
          CASE (1)
            CNT = PRBUF(1:5)
            IF (CNT == 'data_') THEN
              IEND = 1
              RETURN
            ELSE IF (CNT == '     ') THEN
              GO TO 30
            ELSE
              READ (PRBUF, *, IOSTAT = IOST) IH, IK, IL,
     1             (XINT(I), I = 1, 2), SIGI, STATUSX
              IF (IOST /= 0) THEN
C * TRY SHELXL FIXED FORMAT
                READ (PRBUF, 99991, IOSTAT = IOST) IH, IK, IL,
     1            (XINT(I), I = 1, 2), SIGI, STATUSX
                IF (IOST /= 0) THEN
                  IEND = 1
                  RETURN
                END IF
              END IF
            END IF
C * EXCLUDE 'x' AND '-' FLAGGED REFLECTIONS
            IF (STATUSX == 'x' .OR. STATUSX == '-') THEN
              WRITE (LU6, 99977) IH, IK, IL, STATUSX
              GO TO 30
            END IF
            XI   = XINT(IOBS)  * SHXMP
            YI   = XINT(ICALC) * SHXMP
            CALI = YI
            IF (IPR(132) == 1) THEN
              XI = YI
            ELSE IF (IPR(132) == 2) THEN
              XI = ABS (XI - YI)
            ELSE IF (IPR(132) == 3) THEN
              XI = MAX (XI - YI, 0.0)
            ELSE IF (IPR(132) == -1) THEN
              UCINT = YI
            END IF
            SIGI = MAX (0.0, SIGI * SHXMP)
            IF (PAR(493) >= 0.0 .OR. PAR(494) >= 0.0) THEN
C * SHELXL WEIGHT
              IF (IABS (IPR(632)) == 1) THEN
                SIGIW = PLA179 (IH, IK, IL, XI, YI, SIGI)
C * JANA WEIGHT
              ELSE IF (IPR(632) == 2) THEN
                SIGIW = SQRT (SIGI**2 + PAR(493) * XI**2)
              ELSE
                SIGIW = SIGI
              END IF
            ELSE
              SIGIW = SIGI
            END IF
C * FCF TYPE 2 - XTAL-F
          CASE (2)
            READ (PRBUF, 99995, IOSTAT = IOST) IH, IK, IL, XFOBS, XFCAL,
     1                                     XSIGI
            IF (IOST == -1) GO TO 30
            XI    = XFOBS**2
            SIGI  = 2.0 * SQRT (XI) * XSIGI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * FCF TYPE 3 - NRCVAX
          CASE (3)
            READ (PRBUF, 99994, IOSTAT = IOST) IH, IK, IL,
     1            (XINT(I), I = 1, 2), SIGI
            IF (IOST > 0) GO TO 30
            XI = XINT(IOBS)  * SHXMP
            YI = XINT(ICALC) * SHXMP
            IF (IPR(132) == 1) XI = YI
            SIGI  = MAX (0.0, SIGI * SHXMP)
            SIGIW = SIGI
C * FCF TYPE 4 & 7 - MOLEN & MOLEN1 FCF
          CASE (4, 7)
            READ (PRBUF, FMOL, IOSTAT = IOST) IH, IK, IL,
     1        XFOBS, XFCAL, XSIGI
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (IABS (IH) + IABS (IK) + IABS (IL) == 0) GO TO 30
            XI   = XFOBS**2
            SIGI = 2.0 * SQRT(XI) * XSIGI
            CALI = XFCAL**2
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * FCF TYPE 5 - CRYSTALS FCF(F)
          CASE (5)
            IF (IPR(769) == 0) THEN
              READ (PRBUF, 99993, IOSTAT = IOST) IH, IK, IL,
     1              XFOBS, XFCAL, XSIGI, STATUSX, XSIGIW
              INEX = '    '
            ELSE
              READ (PRBUF, 99980, IOSTAT = IOST) IH, IK, IL,
     1              XFOBS, XFCAL, XSIGI, STATUSX, INEX, XSIGIW
            END IF
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
C * ELIMINATE 'SPECIAL' REFLECTIONS
            IF (STATUSX == 'x' .OR. STATUSX == '<' .OR.
     1          STATUSX == 'l' .OR. STATUSX == 'h') GO TO 30
            IF (XSIGIW <= 0.0) GO TO 30
            IF (INEX == 'excl') GO TO 30
            XI    = SIGN (ABS (XFOBS)**2, XFOBS)
            SIGI  = 2.0 * ABS (XFOBS) * XSIGI
            SIGIW = 2.0 * ABS (XFOBS) / SQRT (XSIGIW)
            CALI  = XFCAL**2
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
C * FCF TYPE 6 - TEXSAN1 FCF
          CASE (6)
            READ (PRBUF, 99992, IOSTAT = IOST)
     1        IH, IK, IL, XFOBS, XSIGI, XFCAL
            IF (IOST /= 0) THEN
              IF (PRBUF(1:1) == '#') THEN
                IEND = 1
                RETURN
              END IF
              IF (INDEX (PRBUF, 'data_') /= 0) THEN
                IEND = 1
                RETURN
              END IF
C * ERROR IN RECORD
              WRITE (LU6, 99988, IOSTAT = IOST) PRBUF(1:65)
              GO TO 30
            END IF
            XI = SIGN (XFOBS**2, XFOBS)
            IF (XFOBS > XSIGI / 2.0) THEN
              SIGI = 2.0 * ABS (XFOBS) * XSIGI
            ELSE
              SIGI = 2.0 * ABS (XFCAL) * XSIGI
            END IF
            CALI = XFCAL**2
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * FCF TYPE 8 - CRYSTALS FCF(I)
          CASE (8)
            READ (PRBUF, 99993, IOSTAT = IOST) IH, IK, IL,
     1            XI, CALI, SIGI, STATUSX, SIGIW
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
C * GET TH-MAX INCLUDING EXCLUDED REFLECTIONS
            STHK = GEN095 (PAR(191), IH, IK, IL)
            TH   = ASIN (SQRT (STHK) * PAR(17)) * RGBL(6)
            PAR(517) = MAX (PAR(517), TH)
            IF (STATUSX == 'x' .OR. STATUSX == '<' .OR.
     1          STATUSX == 'l' .OR. STATUSX == 'h') GO TO 30
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            IF (SIGIW /= 0.0) THEN
              SIGIW = 1.0 / SQRT (SIGIW)
            ELSE
              SIGIW = 0.1E+15
            END IF
C * FCF TYPE 9 - JANA
          CASE (9)
            READ (PRBUF, *, IOSTAT = IOST) IH, IK, IL,
     1            XI, CALI, SIGI
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            IF (PAR(493) > 0.0) THEN
              SIGIW = SQRT (SIGI**2 + PAR(493) * (MAX (XI, 0.0))**2)
            ELSE
              SIGIW = SIGI
            END IF
C * FCF TYPE 16 - JANA3
          CASE (16)
            READ (PRBUF, 99976, IOSTAT = IOST)
     1        IH, IK, IL, CALI, XI, SIGI, STATUSX
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (IH == 0 .AND. IK == 0 .AND. IL == 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            IF (PAR(493) > 0.0) THEN
              SIGIW = SQRT (SIGI**2 + PAR(493) * (MAX (XI, 0.0))**2)
            ELSE
              SIGIW = SIGI
            END IF
C * FCF TYPE 17 - CRYSTALS FCF(I,TWIN)
          CASE (17)
C * QUIET NAG COMPILER FOR ID1
            ID2 = ID1
            READ (PRBUF, 99975, IOSTAT = IOST) ID1, ID2,
     1            IH, IK, IL, XI, CALI, SIGI, STATUSX, INEX, SIGIW
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (ID2 > 1) GO TO 30
C * GET TH-MAX INCLUDING EXCLUDED REFLECTIONS
            STHK = GEN095 (PAR(191), IH, IK, IL)
            TH   = ASIN (SQRT (STHK) * PAR(17)) * RGBL(6)
            IF (STATUSX == 'x' .OR.
     1          STATUSX == 'l' .OR. STATUSX == 'h') GO TO 30
            PAR(517) = MAX (PAR(517), TH)
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            IF (SIGIW /= 0.0) THEN
              IF(INEX == 'incl') THEN
                PAR(564) = PAR(564) + SIGIW*(XI - CALI)**2
                IPR(764) = IPR(764) + 1
              END IF
              SIGIW = 1.0 / SQRT (SIGIW)
            ELSE
              SIGIW = 0.1E+15
            END IF
            IF (XI > 2*SIGI) IPR(747) = IPR(747) + 1
            IPR(748) = IPR(748) + 1
C * FCF TYPE 18 - CRYSTALS FCF(I) + incl/excl
          CASE (18)
            READ (PRBUF, 99989, IOSTAT = IOST) IH, IK, IL,
     1        XI, CALI, SIGI, STATUSX, INEX, SIGIW
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (STATUSX == 'x' .OR.
     1          STATUSX == 'l' .OR. STATUSX == 'h') GO TO 30
C * GET TH-MAX INCLUDING EXCLUDED REFLECTIONS
            STHK = GEN095 (PAR(191), IH, IK, IL)
            TH   = ASIN (SQRT (STHK) * PAR(17)) * RGBL(6)
            PAR(517) = MAX (PAR(517), TH)
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            IF (SIGIW /= 0.0) THEN
              IF(INEX == 'incl') THEN
                PAR(564) = PAR(564) + SIGIW*(XI - CALI)**2
                IPR(764) = IPR(764) + 1
              END IF
              SIGIW = 1.0 / SQRT (SIGIW)
            ELSE
              SIGIW = 0.1E+15
            END IF
C * FCF TYPE 10 - TEXSAN2 FCF
          CASE (10)
            READ (PRBUF, 99985, IOSTAT = IOST)
     1              IH, IK, IL, CALI, XI, SIGI
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * FCF TYPE 11 - XD
          CASE (11)
            MARKER = 0
            READ (PRBUF, *, IOSTAT = IOST) IH, IK, IL,
     1            CALI, XI, SIGI, YUNK, MARKER
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (MARKER /= 0) THEN
              GO TO 30
            ELSE
              GO TO 40
            END IF
            READ (PRBUF, *, IOSTAT = IOST) IH, IK, IL,
     1            CALI, XI, SIGI, YUNK
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
   40       IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
C * SHELXL STYLE WEIGHT
            IF (IABS(IPR(632)) == 1) THEN
              SIGIW = PLA179 (IH, IK, IL, XI, CALI, SIGI)
            ELSE
              SIGIW = SIGI
            END IF
C * FCF TYPE 12 - RAELS FCF
          CASE (12)
            READ (PRBUF, 99982, IOSTAT = IOST) IH, IK, IL,
     1            XFOBS, XFCAL, XSIGI
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            XI   = SIGN (ABS (XFOBS)**2, XFOBS)
            SIGI = 2.0 * ABS (XFOBS) * XSIGI
            CALI = XFCAL**2
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
C * FCF TYPE 13,15 - TEXSAN3/RIGAKU FCF
          CASE (13, 15)
            READ (PRBUF, *, IOSTAT = IOSTY)
     1              IH, IK, IL, XI, SIGI, CALI
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * JANA1 FCF
          CASE (14)
            READ (PRBUF, 99978, IOSTAT = IOST) IH, IK, IL,
     1            XFOBS, XFCAL, XSIGI
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            XI   = SIGN (ABS (XFOBS)**2, XFOBS)
            SIGI = 2.0 * ABS (XFOBS) * XSIGI
            CALI = XFCAL**2
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * HKL TYPE 21 - SHELXL - LIST3
          CASE (21)
            READ (PRBUF, *, IOSTAT = IOST)
     1        IH, IK, IL, XFOBS, XSIGI, ACAL, BCAL
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            XI   = XFOBS**2
            SIGI = 2.0 * XFOBS * XSIGI
            YI   = ACAL**2 + BCAL**2
            CALI = YI
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * HKL TYPE 22 - SHELXL - LIST5
          CASE (22)
            READ (PRBUF, 99983, IOSTAT = IOST)
     1            IH, IK, IL, XFOBS, XFCAL
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            IF (IH == 0 .AND. IK == 0 .AND. IL == 0) THEN
              IEND = 1
              RETURN
            END IF
C * HKL TYPE 23 - SHELXL - LIST6
          CASE (23)
            IH   = 0
            IK   = 0
            IL   = 0
            READ (PRBUF, *, IOSTAT = IOST)
     1        IH, IK, IL, XI, SIGI, FC
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            YI   = FC ** 2
            CALI = YI
            IF (IPR(132) == -1) UCINT = CALI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * HKL TYPE 24 - SHELXL - LIST 7
          CASE (24)
            READ (PRBUF, *, IOSTAT = IOST)
     1        IH, IK, IL, XI, SIGI, YI1, YI2
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            YI = 0.0
            IF (YI1 > 0.0) YI = YI1
            IF (YI2 > 0.0) YI = YI + YI2
            CALI  = YI
            UCINT = YI
            SIGI  = MAX (0.0, SIGI)
            SIGIW = SIGI
C * HKL TYPE 25 - SHELXL - LIST 8
          CASE (25)
            READ (PRBUF, *, IOSTAT = IOST)
     1        IH, IK, IL, XI, SIGI, YI, YUNK, YUNK, SIGIW
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
            CALI = YI
            IF (IPR(132) == -1) UCINT = CALI
C * JANA-TW TYPE 27
          CASE (27)
            READ (PRBUF, *, IOSTAT= IOST) IDTW, IDIND, IH, IK, IL,
     1        CALI, XI, SIGI
C * DUMMY INSTRUCTION TO SATISFY FTNCHEK
            IDTW = IDTW * 0
            IF (IOST /= 0) THEN
              IEND = 1
              RETURN
            END IF
C * CHECK FOR SKIP THIS REFLECTION
            IF (IDIND /= 1) GO TO 30
            IF (IPR(132) == -1) UCINT = CALI
            SIGI = MAX (0.0, SIGI)
            IF (PAR(493) > 0.0) THEN
              SIGIW = SQRT (SIGI**2 + PAR(493) * (MAX (XI, 0.0))**2)
            ELSE
              SIGIW = SIGI
            END IF
        END SELECT
C * ELIMINATE SHELXL OMIT REFLECTIONS
        M = IPR(620)
        IF (M /= 0) THEN
          DO I = 1, M
            IF (IH == IHKLOMIT(1, I) .AND. IK == IHKLOMIT(2, I)
     1        .AND. IL == IHKLOMIT(3, I)) GO TO 30
          END DO
        END IF
      ELSE
C * GENERATE REFLECTION INDICES
        GO TO 70
   50   IL0 = IL0 + 1
        IF (IL0 > LMAX) THEN
          IEND = 1
          RETURN
        END IF
        IK0 = - KMAX - 1
   60   IK0 = IK0 + 1
        IF (IK0 > KMAX) GO TO 50
        IH0 = - HMAX - 1
   70   DO
          IH0 = IH0 + 1
          IF (IH0 > HMAX) GO TO 60
C * SKIP 0 0 0 REFLECTION
          IF (IABS (IH0) + IABS (IK0) + IABS (IL0) == 0) CYCLE
C * ACCEPT WHEN WITHIN RESOLUTION SPHERE
          IF (SQRT (GEN095 (PAR(191), IH0, IK0, IL0)) < PAR(287) +
     1      0.00001)  EXIT
        END DO
        IH = IH0
        IK = IK0
        IL = IL0
      END IF
      IEND = 0
      RETURN
99999 FORMAT (':: Expanded HKLF Data Record found',
     1        ' (SQUEEZE contribution added - if any)')
99998 FORMAT (/, ':: Reflection Data are READ from File : ', A,
     1        ' - (', A, '-Data)')
99997 FORMAT (A)
99996 FORMAT (3I4, 2F8.0, 4X, 6F8.5, F8.0, 2F8.0, F8.4)
99995 FORMAT (I5, 2I4, 3F8.0)
99994 FORMAT (I4, 2I5, 3F10.3)
99993 FORMAT (3I4, 3F12.2, 1X, A, E13.4)
99992 FORMAT (I4, 2I5, 3F11.2)
99991 FORMAT (3I4, 2F14.2, F13.2, 1X, A)
99990 FORMAT (/, ':: No Matching Reflection Data Entry found for ', A)
99989 FORMAT (3I4, 3F12.2, 2(1X, A), E13.4)
99988 FORMAT (/, 'ERROR/SKIPPED: ', A)
99987 FORMAT (3I4, 2F8.0, I4, 6F8.5)
99986 FORMAT (/, ':: CIF & FCF CELL DIMENSIONS Inconsistent (ABORT!)',
     1        /)
99985 FORMAT (3I4, 2F12.2, F10.2)
99984 FORMAT ('Unit Cell (FCF)  : ', 3F9.4, 3F9.3)
99983 FORMAT (3I4, 2F10.0, F7.0)
99982 FORMAT (3I4, 2F9.0, F7.0)
99981 FORMAT (/, ':: TRMX = (', 3F6.2, '/', 3F6.2, '/', 3F6.2, ')')
99980 FORMAT (3I4, 3F12.2, 2(1X, A), E13.4)
99979 FORMAT (':: CELL =', 6F10.3)
99978 FORMAT (3I4, 3F10.0)
99977 FORMAT (3I4, 1X, 'Flag = ', A, ' Removed')
99976 FORMAT (3I4, 3F9.0, 1X, A)
99975 FORMAT (I10, I2, 3I4, 3F12.2, 2(1X, A), E13.4)
      END SUBROUTINE PLA132
 
      SUBROUTINE PLA133 (NREF, HMAX, KMAX, LMAX)
C * DETERMINE HMAX, KMAX & LMAX
      USE files
      USE parameters
      USE fab
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NS
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      INTEGER :: NFAB
      INTEGER :: HMAX
      INTEGER :: KMAX
      INTEGER :: LMAX
      INTEGER :: MPH0
      INTEGER :: MPK0
      INTEGER :: MPL0
      INTEGER :: NREF
      INTEGER :: MHK0
      INTEGER :: MHKL0
      INTEGER :: IADR0
      INTEGER :: IHKL0
      INTEGER :: HMAX0
      INTEGER :: KMAX0
      INTEGER :: LMAX0
      INTEGER :: IHEXL
      INTEGER :: NSYMH
      INTEGER :: MHKLH0
      INTEGER, DIMENSION(3) :: IND
      REAL :: XI
      REAL :: PHI
      REAL :: SIGI
      REAL :: YUNK
      REAL :: ASOL
      REAL :: BSOL
      REAL :: FSOL
      REAL :: ASOL0
      REAL :: BSOL0
      REAL :: ACALS
      REAL :: BCALS
      REAL :: SIGIW
      REAL :: UCINT
      CHARACTER(len=80)     :: IDUM
C * FILES: LU26 - FAB FILE
C *        LU27 - (TRANSFORMED) HKL FILE PREPARED BY PLA134
C * TEST FOR AND HANDLE HEXAGONAL LATTICE TYPE
      IF (IPR(259) == 5 .OR. IPR(259) == 6) THEN
        IHEXL = 1
      ELSE
        IHEXL = 0
      END IF
C * HANDLE FAB FILE (LU26)
      IF (IPR(665) /= 0) THEN
C * GET MAX H,K,L FOR REFLECTIONS IN FAB FILE
        NSYMH = IPR(255)
        HMAX0 = -999
        KMAX0 = -999
        LMAX0 = -999
        REWIND (UNIT = LU26, IOSTAT = IOST)
        WRITE (LU6, 99998)
        DO
          READ (LU26, *, IOSTAT = IOST) IH, IK, IL, ASOL, BSOL
          IF (IOST /= 0) EXIT
          IF (IH == 0 .AND. IK == 0 .AND. IL == 0) EXIT
C * KEEP TRACK OF REFLECTION INDEX MAXIMA
          DO I = 1, NSYMH
            SGX(1) = IH
            SGX(2) = IK
            SGX(3) = IL
            NS     = I
            CALL SGSM (5, IDUM, SGX, NS, 0, IERR)
            HMAX0 = MAX (HMAX0, IABS (NINT (SGX(7))))
            KMAX0 = MAX (KMAX0, IABS (NINT (SGX(8))))
            LMAX0 = MAX (LMAX0, IABS (NINT (SGX(9))))
          END DO
        END DO
C * DETERMINE PACKING CONSTANTS AND ADRESSES
        MPH0   = 2 * HMAX0 + 1
        MPK0   = 2 * KMAX0 + 1
        MPL0   = 2 * LMAX0 + 1
        MHK0   = MPH0 * MPK0
        MHKL0  = MPL0 * MHK0
        MHKLH0 = (MHKL0 - 1) / 2
C * TOP-DOWN STORAGE ARRAY OF REFLECTION ADDRESSES
C * CALCULATE ADDRESS OF 0,0,0 REFLECTION
        IADR0  = NVDR - MHKLH0
        CALL GEN074 (VOID, NVDR - MHKL0 + 1, NVDR, 0.0)
        REWIND (UNIT = LU26, IOSTAT = IOST)
        NFAB = 0
        WRITE (LU6, 99998)
        DO
          READ (LU26, *, IOSTAT = IOST) IH, IK, IL, ASOL, BSOL
          IF (IOST /= 0) EXIT
          IF (IH == 0 .AND. IK == 0 .AND. IL == 0) EXIT
          IF (ASOL.EQ. 0.0 .AND. BSOL == 0.0) THEN
            SGX(4) = 0.0
          ELSE
            SGX(4) = ATAN2 (BSOL, ASOL) * RGBL(6)
          END IF
          FSOL   = SQRT (ASOL**2 + BSOL**2)
          DO I = 1, NSYMH
            SGX(1) = IH
            SGX(2) = IK
            SGX(3) = IL
            NS     = I
            CALL SGSM (5, IDUM, SGX, NS, 0, IERR)
            DO J = 1, 3
              IND(J) = NINT (SGX(J + 6))
            END DO
            IHKL0 = IND(3) * MHK0 + IND(2) * MPH0 + IND(1)
            PHI            = SGX(10) / RGBL(6)
            ASOL0          = FSOL * COS (PHI)
            BSOL0          = FSOL * SIN (PHI)
            NFAB           = NFAB + 2
            VOID(NFAB - 1) = ASOL0
            VOID(NFAB)     = BSOL0
            IF ((IADR0 + IHKL0) > NVDR) THEN
              WRITE (LU6, 99996, IOSTAT = IOST) HMAX0, KMAX0, LMAX0,
     1          IADR0, MHKLH0, IND(1), IND(2), IND(3), IADR0 + IHKL0
              STOP
            END IF
            VOID(IADR0 + IHKL0) =  NFAB - 1
            NFAB                =  NFAB + 2
            VOID(NFAB - 1)      =  ASOL0
            VOID(NFAB)          = -BSOL0
            VOID(IADR0 - IHKL0) =  NFAB - 1
          END DO
        END DO
      END IF
      NREF = 0
      IHT  = 0
      IKT  = 0
      ILT  = 0
      HMAX = -999
      KMAX = -999
      LMAX = -999
      INQUIRE (UNIT = LU27, OPENED = OPEND)
      IF (OPEND) CLOSE (UNIT = LU27)
      OPEN (UNIT = LU27, STATUS = 'SCRATCH', FORM = 'UNFORMATTED',
     1   IOSTAT = IOST)
      IF (IOST /= 0) THEN
        WRITE (LU6, '(''PROBLEM OF LU27'')')
        IPR(2) = 74
        RETURN
      END IF
      IEND = -1
C * TRANSFORM REFLECTIONS FOR SF-CALCULATION (EXCLUDE NON-INTEGRAL H,K,L)
C * WITH TRANSFORMATION MATRIX FROM HKLF LINE ON INSTRUCTION FILE
C * REFLECTION DATA FROM LU16, TRANSFORMED DATA ON LU17
      WRITE (LU6, 99997)
      DO
        CALL PLA134 (IH, IK, IL, IHT, IKT, ILT, XI, SIGI,
     1    SIGIW, UCINT, ACALS, BCALS)
        IF (IEND > 0) EXIT
C * HANDLE FAB FILE
        IF (IPR(665) /= 0) THEN
          IHKL0 = ILT * MHK0 + IKT * MPH0 + IHT
          N     = NINT (VOID(IADR0 + IHKL0))
          ASOL  = VOID(N)
          BSOL  = VOID(N + 1)
        ELSE
          ASOL = 0.0
          BSOL = 0.0
        END IF
C * KEEP TRACK OF REFLECTION INDEX MAXIMA
        HMAX = MAX (HMAX, IABS (IHT))
        KMAX = MAX (KMAX, IABS (IKT))
C * HEXAGONAL LATTICE CASE
        IF (IHEXL == 1) THEN
          HMAX = MAX (KMAX, HMAX, IABS (IHT + IKT))
          KMAX = HMAX
        END IF
        LMAX = MAX (LMAX, IABS (ILT))
        NREF = NREF + 1
C * TEST FOR hkl-ext FILE TYPE
        IF (IGBL(9) == -1) THEN
          YUNK = UCINT
        ELSE
          YUNK = XI
        END IF
        WRITE (LU27, IOSTAT = IOST) IHT, IKT, ILT, YUNK, SIGI, SIGIW,
     1    ASOL, BSOL
      END DO
C * TETRAGONAL LATTICE CASE
      IF (IPR(259) == 4) THEN
        HMAX = MAX (HMAX, KMAX)
        KMAX = HMAX
C * CUBIC LATTICE CASE
      ELSE IF (IPR(259) == 7) THEN
        HMAX = MAX (HMAX, KMAX, LMAX)
        KMAX = HMAX
        LMAX = HMAX
      END IF
C * CHECK FOR 'ANY" VALID REFLECTIONS READ
      IF (NREF == 0) THEN
        IPR(1) = 1
        IF (IPR(2) == 0) IPR(2) = 39
        RETURN
      END IF
C * REPORT # REFLECTIONS AND INDEX MAXIMA
      WRITE (LU6, 99999, IOSTAT = IOST) NREF, HMAX, KMAX, LMAX
      CALL PLA262 (3)
      WRITE (LU7, 99999, IOSTAT = IOST) NREF, HMAX, KMAX, LMAX
      RETURN
99999 FORMAT (/, ':: # Accepted Reflns     Hmax Kmax Lmax', /,
     1           '::', 12X, I6, 3X, 3I5)
99998 FORMAT (':: READ .fab FILE')
99997 FORMAT (':: READ Reflection File')
99996 FORMAT (3I5, 2I12, 3I5, I12)
      END SUBROUTINE PLA133
 
      SUBROUTINE PLA134 (IH, IK, IL, IHT, IKT, ILT, XI, SIGI,
     1  SIGIW, UCINT, ACALS, BCALS)
C * HKL - READ / TRANS
      USE files
      USE parameters
      USE spgrdata
      USE fab
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      REAL :: XI
      REAL :: STHK
      REAL :: CALI
      REAL :: SIGI
      REAL :: SIGIW
      REAL :: UCINT
      REAL :: ACALS
      REAL :: BCALS
      REAL :: GEN049
      REAL :: GEN050
      REAL :: GEN095
      DO
        CALL PLA132 (IH, IK, IL, XI, SIGI, SIGIW, CALI, UCINT, ACALS,
     1               BCALS)
        IF (IEND == 2) RETURN
        IF (IEND <= 0) THEN
          IF (IABS (IH) + IABS (IK) + IABS (IL) /= 0) THEN
C * APPLY TRANSFORMATION (IF ANY) AND ELIMINATE REFL WITH NON-INTEGRAL INDICES
            IF (GEN050 (TRMX, IH, IK, IL, IHT, IKT, ILT) > 0.0) THEN
C * FIRST HANDLE BRAVAIS EXTINCTIONS
              IF (IPR(241) > 1) THEN
                IF (GEN049 (LAT(IPR(241)), IHT, IKT, ILT) <= 0.0) THEN
C * COUNT NUMBER OF SKIPPED REFLECTIONS
                  ISKIP = ISKIP + 1
                  CYCLE
                END IF
              END IF
            ELSE
C * COUNT NUMBER OF SKIPPED REFLECTIONS
              ISKIP = ISKIP + 1
              CYCLE
            END IF
C * TEST ON THETAMAX
            STHK = GEN095 (PAR(191), IHT, IKT, ILT)
            IF (IGBL(30) == 0) THEN
              IF (STHK > STHKM) THEN
                ITSKP = ITSKP + 1
                CYCLE
              END IF
            END IF
            PAR(166) = MAX (PAR(166), STHK)
            XI       = XI   * PAR(230)
            SIGI     = SIGI * PAR(230)
          END IF
          EXIT
        ELSE
C * REPORT THE NUMBER OF REFLECTION SKIPPED
          IEND = 1
          IF (ISKIP > 0 .AND. IPR(408) <= 0) THEN
            WRITE (LU6, 99999, IOSTAT = IOST) ISKIP
            CALL PLA262 (3)
            WRITE (LU7, 99999, IOSTAT = IOST) ISKIP
          END IF
          ISKIP = 0
          IF (ITSKP > 0 .AND. IPR(408) <= 0) THEN
            WRITE (LU6, 99998, IOSTAT = IOST) PAR(165), ITSKP
            CALL PLA262 (3)
            WRITE (LU7, 99998, IOSTAT = IOST) PAR(165), ITSKP
          END IF
          ITSKP = 0
          EXIT
        END IF
      END DO
      RETURN
99999 FORMAT (/, ':: Nr. of Eliminated Reflections (Latt Ext. etc.)',
     1 ' =', I5, /)
99998 FORMAT (/, ':: Nr. of Eliminated Reflections (Theta Limit = ',
     1 F5.1, ' Deg) =', I10, /)
      END SUBROUTINE PLA134
 
      SUBROUTINE PLA135
C * STRUCTURE FACTOR CALCULATION FOR CALC FCF - IPR(210) = -1
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cif
      USE reflex
      USE fab
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: NR
      INTEGER :: NS
      INTEGER :: IS
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      INTEGER :: IH2
      INTEGER :: IK2
      INTEGER :: IL2
      INTEGER :: MPK
      INTEGER :: MPL
      INTEGER :: NR0
      INTEGER :: NR7
      INTEGER :: NRF
      INTEGER :: NREF
      INTEGER :: NRF1
      INTEGER :: NATO
      INTEGER :: ISYM
      INTEGER :: HMAX
      INTEGER :: KMAX
      INTEGER :: LMAX
      INTEGER :: IHKL
      INTEGER :: IADR
      INTEGER :: IHTN
      INTEGER :: IKTN
      INTEGER :: ILTN
      INTEGER :: MHKL
      INTEGER :: MHKLH
      INTEGER :: IADR1
      INTEGER :: IHEXL
      INTEGER :: IHKL0
      INTEGER :: IHKLN
      INTEGER :: NSYMC
      REAL :: ACL
      REAL :: BCL
      REAL :: XCL
      REAL :: SCF
      REAL :: RID
      REAL :: RK2
      REAL :: RL2
      REAL :: RH2
      REAL :: ACLA
      REAL :: BCLA
      REAL :: FCLM
      REAL :: FCLS
      REAL :: ACAL
      REAL :: BCAL
      REAL :: XOBS
      REAL :: XCAL
      REAL :: WGHT
      REAL :: SUM1
      REAL :: SUM2
      REAL :: SUM3
      REAL :: SUM4
      REAL :: SUMN
      REAL :: SUMT
      REAL :: STHL
      REAL :: STLK
      REAL :: SGIK
      REAL :: SIGI
      REAL :: PCAL
      REAL :: PCALN
      REAL :: SIGI1
      REAL :: SIGI2
      REAL :: UCINT
      REAL :: ACALA
      REAL :: BCALA
      REAL :: ACALS
      REAL :: BCALS
      REAL :: ACALX
      REAL :: BCALX
      REAL :: XCALC
      REAL :: XOBS1
      REAL :: XOBS2
      REAL :: WGTI1
      REAL :: WGTI2
      REAL :: WGTIS
      REAL :: SOMXC
      REAL :: SOMXO
      REAL :: SNTHA
      REAL :: SN2TH
      REAL :: SIGIW
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN095
      REAL :: PLA179
C * LOAD ATOMS AND EXPAND (EXCLUDING BRAVAIS CENTERING)
      CALL PLA023 (0)
      NATO = IPR(589)
      IF (NATO < 0) THEN
        IPR(1) = 1
        IPR(2) = 42
        RETURN
      END IF
      NSYMH = IPR(255)
      ICNTR = IPR(257)
      IND1  = 1
      IND2  = 2
      IND3  = 3
C * READ SHELX(L).HKL - TYPE 4 OR FCF
      NREF  = 0
      SOMXO = 0.0
      SOMXC = 0.0
C * TEST FOR HEXAGONAL LATTICE TYPE
      IF (IPR(259) == 5 .OR. IPR(259) == 6) THEN
        IHEXL = 1
      ELSE
        IHEXL = 0
      END IF
C * TRANSFORM REFLECTIONS FOR SF-CALCULATION (EXCLUDE NON-INTEGRAL H,K,L)
      CALL GEN108 (LU9, 0)
      HMAX = -999
      KMAX = -999
      LMAX = -999
      IHT  = 0
      IKT  = 0
      ILT  = 0
      IEND = -1
      DO WHILE (IEND /= 1)
        CALL PLA134 (IH, IK, IL, IHT, IKT, ILT, XOBS, SIGI,
     1    SIGIW, UCINT, ACALS, BCALS)
C * END_OF_DATA HANDLING
        IF (IEND == 1) THEN
          IF (NREF == 0) THEN
            WRITE (LU6, 99998, IOSTAT = IOST)
            IPR(210) = 0
            RETURN
          ELSE
C * THETA-MAX
            PAR(166) = ASIN (SQRT (PAR(166)) * PAR(17)) * RGBL(6)
C * TETRAGONAL LATTICE
            IF (IPR(259) == 4) THEN
              HMAX = MAX (HMAX, KMAX)
              KMAX = HMAX
C * CUBIC LATTICE
            ELSE IF (IPR(259) == 7) THEN
              HMAX = MAX (HMAX, KMAX, LMAX)
              KMAX = HMAX
              LMAX = HMAX
            END IF
          END IF
        ELSE
          HMAX = MAX (HMAX, IABS (IHT))
          KMAX = MAX (KMAX, IABS (IKT))
          LMAX = MAX (LMAX, IABS (ILT))
C * HEXAGONAL LATTICE
          IF (IHEXL == 1) THEN
            HMAX = MAX (KMAX, HMAX, IABS (IHT + IKT))
            KMAX = HMAX
          END IF
C * TETRAGONAL LATTICE
          IF (IPR(259) == 4) THEN
            HMAX = MAX (HMAX, KMAX)
            KMAX = HMAX
C * CUBIC LATTICE
          ELSE IF (IPR(259) == 7) THEN
            HMAX = MAX (HMAX, KMAX, LMAX)
            KMAX = HMAX
            LMAX = HMAX
          END IF
          NREF   = NREF + 1
          ACAL   = 0.0
          BCAL   = 0.0
          ACALA  = 0.0
          BCALA  = 0.0
          ACALAF = 0.0
          BCALAF = 0.0
C * CHECK FOR 'LONG' HKLF FORMAT (FCF-MODE)
          IF (IGBL(9) == -1) THEN
C * FCF CASE
            IF (IPR(210) == -1) THEN
C * START WITH SOLVENT CONTRIBUTION
              ACAL = ACALS
              BCAL = BCALS
              XOBS = UCINT * ABSCOR
            END IF
          END IF
C * CALCULATE STRUCTURE FACTOR
          CALL PLA137 (IHT, IKT, ILT, ACALX, BCALX, ACALA, BCALA,
     1      ACALAF, BCALAF, SNTHA)
C * ADD ANOMALOUS (F' & F") CONTRIBUTION
          ACAL = ACAL + ACALX + ACALA
          BCAL = BCAL + BCALX + BCALA
          XCAL = ACAL ** 2 + BCAL ** 2
C * HANDLE TWIN CONTRIBUTION
          IF (IPR(193) == 101) THEN
            RH2 = PAR(332) * IHT + PAR(333) * IKT + PAR(334) * ILT
            RK2 = PAR(335) * IHT + PAR(336) * IKT + PAR(337) * ILT
            RL2 = PAR(338) * IHT + PAR(339) * IKT + PAR(340) * ILT
            IH2 = NINT (RH2)
            IK2 = NINT (RK2)
            IL2 = NINT (RL2)
            RID = ABS (RH2 - IH2) + ABS (RK2 - IK2) + ABS (RL2 - IL2)
            IF (RID <= 0.01) THEN
C * CALCULATE STRUCTURE FACTOR FOR TWIN PART
              ACL = 0.0
              BCL = 0.0
              CALL PLA137 (IH2, IK2, IL2, ACL, BCL, ACLA, BCLA,
     1          ACALAF, BCALAF, SNTHA)
C * ADD ANOMALOUS (F' & F") CONTRIBUTION
              ACL = ACL + ACLA
              BCL = BCL + BCLA
              XCL = ACL ** 2 + BCL ** 2
              XCAL = (1.0 - PAR(341)) * XCAL + PAR(341) * XCL
            ELSE
              XCAL = (1.0 - PAR(341)) * XCAL
            END IF
          END IF
C * TAKE SWAT CORRECTION TO XCAL INTO ACCOUNT (NOT FOR SHELXL.FCF OR GENER)
          IF (IPR(408) <= 0 .AND. IPR(698) /= 0) THEN
C * CALCULATE (SIN(THETA) / LAMBDA)**2
            STLK  = GEN095 (PAR(191), IHT, IKT, ILT)
            XCAL = XCAL * (1.0 - PAR(501) *
     1        EXP (- RGBL(8) * PAR(502) * STLK))**2
          END IF
C * TAKE EXTINCTION CORRECTION INTO ACCOUNT (NOT FOR SHELXL.FCF OR GENER)
          IF (IPR(408) <= 0) THEN
            IF (PAR(229) > -99999.0 .AND. IGBL(9) /= 1) THEN
              SN2TH = 2 * SNTHA * SQRT (1.0 - MIN (SNTHA, 1.0) ** 2)
              XOBS = XOBS *
     1      (1.0 + 0.001 * PAR(229) * XCAL * PAR(17)**3 / SN2TH) ** 0.5
              SIGI = SIGI *
     1      (1.0 + 0.001 * PAR(229) * XCAL * PAR(17)**3 / SN2TH) ** 0.5
            END IF
          END IF
          IF (XOBS > 2 * SIGI) THEN
            SOMXO = SOMXO + XOBS
            SOMXC = SOMXC + XCAL
          END IF
C * WRITE TO SCRATCH REFLECTION FILE
          IF (ACAL == 0.0 .AND. BCAL == 0.0) THEN
            PCAL = 0.0
          ELSE
            PCAL = ATAN2 (BCAL, ACAL) * RGBL(6)
          END IF
          WRITE (LU9) IH, IK, IL, IHT, IKT, ILT, XOBS, XCAL, SIGI,
     1      PCAL, ACAL, BCAL, ACALA, BCALA
        END IF
      END DO
C * END HKL READ/CALC LOOP
C * PATT
      IF (IGBL(9) == 1) THEN
        IF (IPR(516) == 0) THEN
          SCF = 0.01 * PAR(240)
        ELSE
          SCF = SOMXC / (SOMXO * PAR(240))
        END IF
      ELSE
        SCF = SOMXC / (SOMXO * PAR(240))
      END IF
      WRITE (LU6, 99984, IOSTAT = IOST) SCF
      CALL GEN108 (LU9,  0)
      CALL GEN108 (LU17, 0)
      FCLM = 0.0
      NR7  = 0
C * READ SCRATCH REFLECTION FILE
      DO I = 1, NREF
        READ (LU9) IH, IK, IL, IHT, IKT, ILT, XOBS, XCAL, SIGI,
     1   PCAL, ACAL, BCAL, ACALA, BCALA
        XOBS = MAX (0.0, XOBS) * SCF
        SIGI = SIGI * SCF
        XCAL = XCAL / PAR(240)
        IF (IPR(414) > 0) THEN
C * HANDLE CONTOUR 'REAL MAP' CASE
          IF (.TRUE.) THEN
            XCALC = XCAL
            BCAL  = BCAL - BCALA
            IF (ACAL == 0.0 .AND. BCAL == 0) THEN
              PCAL = 0.0
            ELSE
              PCAL = ATAN2 (BCAL, ACAL) * RGBL(6)
            END IF
            XCAL = ACAL**2 + BCAL**2
            XOBS = XOBS * XCAL / XCALC
          ELSE
          XOBS = (SQRT (XOBS) * ACAL / SQRT (XCAL) - ACALA) ** 2 +
     1           (SQRT (XOBS) * BCAL / SQRT (XCAL) - BCALA) ** 2
          ACAL = ACAL - ACALA
          BCAL = BCAL - BCALA
          IF (ACAL == 0.0 .AND. BCAL == 0) THEN
            PCAL = 0.0
          ELSE
            PCAL = ATAN2 (BCAL, ACAL) * RGBL(6)
          END IF
          XCAL = ACAL ** 2 + BCAL ** 2
          END IF
        END IF
        VOID(NR7 + 1) = IHT
        VOID(NR7 + 2) = IKT
        VOID(NR7 + 3) = ILT
        VOID(NR7 + 4) = XOBS * PAR(240)
        VOID(NR7 + 5) = XCAL * PAR(240)
        VOID(NR7 + 6) = SIGI * PAR(240)
        VOID(NR7 + 7) = PCAL
        FCLM          = MAX (FCLM, SQRT (XCAL * PAR(240)))
        NR7           = NR7  + 7
      END DO
C * CALC FCF MODE
      SUM1     = 0.0
      SUM2     = 0.0
      SUM3     = 0.0
      SUM4     = 0.0
      IPR(411) = HMAX
      IPR(412) = KMAX
      IPR(413) = LMAX
      MPH      = 2 * HMAX + 1
      MPK      = 2 * KMAX + 1
      MPL      = 2 * LMAX + 1
      MHK      = MPH * MPK
      MHKL     = MPL * MHK
      MHKLH    = (MHKL - 1) / 2
C * CALCULATE ADDRESS OF 0,0,0
      IADR     = NVDR - MHKLH
      IADR1    = NVDR - MHKL
      IF (IADR1 < NR7) THEN
        WRITE (LU6, 99994, IOSTAT = IOST)
        RETURN
      END IF
      DO I = 1, MHKL
        VOID(IADR1 + I) = - 1.0
      END DO
      NR7 = 0
      DO I = 1, NREF
        IHT  = NINT (VOID(NR7 + 1))
        IKT  = NINT (VOID(NR7 + 2))
        ILT  = NINT (VOID(NR7 + 3))
        IHKL = ILT * MHK + IKT * MPH + IHT
        N = NINT (VOID(IADR + IHKL))
        IF (N < 0) THEN
          VOID(IADR + IHKL) = I
        ELSE
          XOBS1 = VOID((N - 1) * 7 + 4)
          SIGI1 = VOID((N - 1) * 7 + 6)
          IF (SIGI1 > 0.0) THEN
            WGTI1 = 1.0 / SIGI1**2
          ELSE
            WGTI1 = 1.0
          END IF
          XOBS2 = VOID(NR7 + 4)
          SIGI2 = VOID(NR7 + 6)
          IF (SIGI2 > 0.0) THEN
            WGTI2 = 1.0 / SIGI2**2
          ELSE
            WGTI2 = 1.0
          END IF
          WGTIS = WGTI1 + WGTI2
          VOID((N - 1) * 7 + 4) =
     1         (WGTI1 * XOBS1 + WGTI2 * XOBS2) / WGTIS
          VOID((N - 1) * 7 + 6) = 1.0 / SQRT (WGTIS)
        END IF
        NR7  = NR7 + 7
      END DO
C * AVERAGE
      NSYMC = NSYMH * ICNTR
      IF (NSYMC > 1) THEN
        DO I = 1, MHKL
          J = MHKL + 1 - I
          K = NINT (VOID(IADR1 + J))
          IF (K > 0) THEN
            VOID(IADR1 + J) = -1
            IHT   = NINT (VOID((K - 1) * 7 + 1))
            IKT   = NINT (VOID((K - 1) * 7 + 2))
            ILT   = NINT (VOID((K - 1) * 7 + 3))
            XOBS  =       VOID((K - 1) * 7 + 4)
            SIGI  =       VOID((K - 1) * 7 + 6)
            PCAL  =       VOID((K - 1) * 7 + 7)
            IHKL0 = ILT * MHK + IKT * MPH  + IHT
            IHKLN = IHKL0
            PCALN = PCAL
            IHTN  = IHT
            IKTN  = IKT
            ILTN  = ILT
            IF (SIGI /= 0.0) THEN
              SUMT  = XOBS / SIGI**2
              SUMN  = 1.0  / SIGI**2
            ELSE
              SUMT = XOBS
              SUMN = 1.0
            END IF
            DO L = 2, NSYMC
              SGY(1) = IHT
              SGY(2) = IKT
              SGY(3) = ILT
              SGY(4) = PCAL
              IF (L > NSYMH) THEN
                NS = L - NSYMH
                IS = -1
              ELSE
                NS = L
                IS = 1
              END IF
              CALL SGSM (5, ICL, SGY, NS, LU7, IERR)
              IH   = NINT (SGY(7))
              IK   = NINT (SGY(8))
              IL   = NINT (SGY(9))
              IHKL = (IL * MHK + IK * MPH  + IH) * IS
              IF (IHKL > IHKLN) THEN
                IHKLN = IHKL
                IHTN  = IH
                IKTN  = IK
                ILTN  = IL
                PCALN = SGY(10)
              END IF
              IF (IHKL /= IHKL0) THEN
                NR = NINT (VOID(IADR + IHKL))
                IF (NR > 0) THEN
                  XOBS = VOID((NR - 1) * 7 + 4)
                  SIGI = VOID((NR - 1) * 7 + 6)
                  IF (SIGI /= 0.0) THEN
                    WGHT = 1.0 / SIGI**2
                  ELSE
                    WGHT = 1.0
                  END IF
                  SUMT = SUMT + XOBS * WGHT
                  SUMN = SUMN + WGHT
                  VOID(IADR + IHKL) = - 1.0
                END IF
              END IF
            END DO
            VOID(IADR + IHKLN) = K
            NR = (K - 1) * 7
            VOID(NR + 1) = IHTN
            VOID(NR + 2) = IKTN
            VOID(NR + 3) = ILTN
            VOID(NR + 4) = SUMT / SUMN
            VOID(NR + 6) = 1.0  / SQRT (SUMN)
            VOID(NR + 7) = PCALN
          END IF
        END DO
      END IF
C * GENERATE SHELXL.CIF & SHELXL.FCF LOOK-ALIKES
      FCLS = 1.0
      IF (FCLM < 250.0) FCLS = 100.0
C * CIF LOOK-ALIKE
      INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.cif', EXIST = EXST)
      IF (EXST) THEN
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_pl.cif',
     1        STATUS = 'UNKNOWN')
        IF (IABS (IGBL(8)) == 3) CLOSE (UNIT = LU1)
        OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'.cif',
     1        STATUS = 'UNKNOWN')
        DO WHILE (.TRUE.)
          READ (LU62, 99989, IOSTAT = IOST) IDM
          IF (IOST /= 0) EXIT
          IF (INDEX (IDM, 'data_') /= 0) THEN
            WRITE (LU61, 99995, IOSTAT = IOST) NAMEFIL(1:KNMFIL)
          ELSE
            WRITE (LU61, 99989, IOSTAT = IOST) IDM
          END IF
        END DO
        CLOSE (UNIT = LU62)
        INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.sqf', EXIST = EXST)
        IF (EXST) THEN
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'.sqf',
     1          STATUS = 'UNKNOWN')
          DO WHILE (.TRUE.)
            READ (LU62, 99989, IOSTAT = IOST) IDM
            IF (IOST /= 0) EXIT
            WRITE (LU61, 99989, IOSTAT = IOST) IDM
          END DO
          CLOSE (UNIT = LU62)
        END IF
C * ADD _iucr_refine_instructions_details  ???
        IF (IABS(IGBL(8)) == 2) THEN
          STOP
          REWIND (UNIT = LU1, IOSTAT = IOST)
          WRITE (LU61, 99989, IOSTAT = IOST) CIFDIR(513)
          WRITE (LU61, 99988, IOSTAT = IOST)
          DO WHILE (.TRUE.)
            READ (LU1,   99989, IOSTAT = IOST) IDM
            IF (IOST /= 0) EXIT
            WRITE (LU61, 99989, IOSTAT = IOST) IDM
          END DO
          WRITE (LU61, 99988, IOSTAT = IOST)
        END IF
        CLOSE (UNIT = LU61)
      END IF
C * GENERATE FCF LOOK-ALIKE
      OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_pl.fcf',
     1        STATUS = 'UNKNOWN')
      WRITE (LU61, 99987)
      IF (IPR(408) == 1) WRITE (LU61, 99986)
      WRITE (LU61, 99985, IOSTAT = IOST)
     1  NAMEFIL(1:KNMFIL), JID(1: 50), FCLM, PAR(157),
     2  1.0 / (2.0 * PAR(287))
      NSYM   = IPR(48)
      SGY(4) = 0.0
      SGY(5) = 0.0
      SGY(6) = 0.0
      DO K = 1, NSYM
        ISYM = K
        CALL SGSM (20, ICL, SGY, ISYM, 0, IERR)
        CALL GEN020 (-1, ICL, 1, 30)
        N = INDEX (ICL, ' ') -1
        WRITE (LU61, 99991, IOSTAT = IOST) ICL(1:N)
      END DO
      WRITE (LU61, 99997, IOSTAT = IOST)
     1  (PAR(K), K = 101, 106), 1.0 / FCLS
      NRF  = 0
      NRF1 = 0
      CALL GEN108 (LU9, 0)
      DO I = 1, MHKL
        NR0 = NINT (VOID(IADR1 + I))
        IF (NR0 > 0) THEN
          IHT  = NINT (VOID((NR0 - 1) * 7 + 1))
          IKT  = NINT (VOID((NR0 - 1) * 7 + 2))
          ILT  = NINT (VOID((NR0 - 1) * 7 + 3))
          XCAL =      VOID((NR0 - 1) * 7 + 5)
          IF (IPR(408) <= 0) THEN
            XOBS =    VOID((NR0 - 1) * 7 + 4)
            SIGI =    VOID((NR0 - 1) * 7 + 6)
          ELSE
            XOBS = XCAL
            SIGI = SQRT (XOBS)
          END IF
          PCAL    = VOID((NR0 - 1) * 7 + 7)
          SGX(1)  = IHT
          SGX(2)  = IKT
          SGX(3)  = ILT
          SGX(12) = 0.0
          CALL SGSM (27, LINE, SGX, 0, 0, IERR)
          IF (NINT (SGX(12)) == 0) THEN
            NRF1 = NRF1 + 1
            IF (XOBS >= 2 * SIGI) THEN
              SUM1 = SUM1 + ABS (SQRT (XOBS) - SQRT (XCAL))
              SUM2 = SUM2 + SQRT(XOBS)
              NRF  = NRF  + 1
            END IF
C * SHELXL WEIGHT
            IF (PAR(493) >= 0.0) THEN
              SGIK = PLA179 (IHT, IKT, ILT, XOBS, XCAL, SIGI) ** 2
            ELSE
              SGIK = SIGI ** 2
            END IF
            SUM3 = SUM3 + ((XOBS - XCAL) ** 2) / SGIK
            SUM4 = SUM4 + (XOBS ** 2) / SGIK
            STHL = SQRT (GEN095 (PAR(191), IHT, IKT, ILT))
C * FCF GENERATE (SNTL_MAX = 0.65 - copper sphere)
              WRITE (LU61, 99993, IOSTAT = IOST)
     1          IHT, IKT, ILT, XCAL * FCLS,
     1          XOBS * FCLS, SIGI * FCLS, STHL
          END IF
        END IF
      END DO
      IF (IPR(408) <= 0) THEN
        CALL PLA262 (3)
        WRITE (LU6, 99999, IOSTAT = IOST)
        WRITE (LU7, 99999, IOSTAT = IOST)
      END IF
C * R-VALUES (NOT FOR SQUEEZE_CONTOUR AND PATTERSON MAPS)
      IF (IPR(414) < 4) THEN
        N = 0
        IF (PAR(493) >= 0) THEN
          N = INDEX (RLWS(1)(2:80), '''')
          IF (N >= 2) WRITE (LU6, 99992, IOSTAT = IOST) RLWS(1)(2:N)
        END IF
        WRITE (LU6, 99996, IOSTAT = IOST)
     1    SUM1 / SUM2, NRF, SQRT (SUM3 / SUM4), NRF1,
     1    SQRT(SUM3 / (NRF1 - IPR(226)))
        IF (N >= 2) THEN
          CALL PLA262 (2)
          WRITE (LU7, 99992, IOSTAT = IOST) RLWS(1)(2:N)
        END IF
        CALL PLA262 (6)
        WRITE (LU7, 99996, IOSTAT = IOST)
     1    SUM1 / SUM2, NRF, SQRT (SUM3 / SUM4), NRF1,
     2    SQRT (SUM3 / (NREF - IPR(226)))
      END IF
      WRITE (LU61, 99990, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU17, STATUS = 'DELETE')
      RETURN
99999 FORMAT (/, ':: Structure Factor Calculation including SQUEEZE',
     1           ' Contribution', /)
99998 FORMAT (/, ':: However, no reflection data found', /)
99997 FORMAT (/, '_cell_length_a', F9.5,/,
     1        '_cell_length_b', F9.4, /,
     2        '_cell_length_c', F9.4, /,
     3        '_cell_angle_alpha', F9.3, /,
     4        '_cell_angle_beta', F9.3, /,
     5        '_cell_angle_gamma', F9.3, //,
     6 '_shelx_F_squared_multiplier', F10.3, //,
     7 'loop_', /,
     8 ' _refln_index_h', /,
     9 ' _refln_index_k', /,
     * ' _refln_index_l', /,
     1 ' _refln_F_squared_calc', /,
     2 ' _refln_F_squared_meas', /,
     3 ' _refln_F_squared_sigma', /,
     4 ' _refln_include_status', /,
     5 ' _refln_sint/lambda')
99996 FORMAT (':: R1   =', F9.3, ' for', I6,
     1        ' Refl. with I > 2 s(I) and', /,
     2        ':: wR2  =', F9.3, ' for', I6, ' reflections', /,
     3        ':: S    =', F9.3, /)
99995 FORMAT ('data_', A)
99994 FORMAT (/, 'NVDR too Small in PLA135', /)
99993 FORMAT (3I4, 2F12.2, F10.2, ' o', F10.5)
99992 FORMAT (/, ':: ', A)
99991 FORMAT (1X, '''', A, '''')
99990 FORMAT (1X)
99989 FORMAT (A)
99988 FORMAT (';')
99987 FORMAT ('#', /, '# h,k,l, Fc-squared, Fo-squared,',
     1 ' sigma(Fo-squared) and status flag', /, '#')
99986 FORMAT ('# !!! FCF Generated for TEST Purposes only, ',
     1 'NOT for FCF Deposition !!!')
99985 FORMAT ('data_', A, /, '_shelx_title '' ', A, ' ''', /,
     3 '_shelx_refln_list_code   4', /,
     4 '_shelx_F_calc_maximum', F10.2, /,
     5 '_exptl_crystal_F_000 ', F10.2, /,
     6 '_reflns_d_resolution_high', F10.4, //,
     6 'loop_', /,
     7 ' _symmetry_equiv_pos_as_xyz')
99984 FORMAT (':: SCF =', F10.6)
      END SUBROUTINE PLA135
 
      SUBROUTINE PLA136 (MODE, IH, IK, IL, IASM)
C * HANDLE ASYMMETRIC REFLECTION UNIT
      USE parameters
      USE reflex
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: NS
      INTEGER :: IASM
      INTEGER :: IHKL
      INTEGER :: MODE
      INTEGER :: ISHKL
      INTEGER :: IHKLM
      INTEGER, DIMENSION(3) :: IND
C * IASM = 0 - NOT IN ASYM UNIT
C *      = 1 - IN ASYM UNIT
      IASM  = 1
      IHKLM = 0
      DO I = 1, NSYMH
        SGX(1) = IH
        SGX(2) = IK
        SGX(3) = IL
        SGX(4) = 0.0
        NS     = I
        CALL SGSM (5, ICL, SGX, NS, 0, IERR)
        IND(1) = NINT (SGX(IND1 + 6))
        IND(2) = NINT (SGX(IND2 + 6))
        IND(3) = NINT (SGX(IND3 + 6))
        IHKL   = IND(3) * MHK + IND(2) * MPH + IND(1)
C * UPPER HALF OF REFLECTION SPHERE ONLY (L >= 0)
        IF (IHKL < 0) THEN
          DO J = 1, 3
            IND(J) = - IND(J)
          END DO
          IHKL  = - IHKL
          ISHKL = - 1
        ELSE
          ISHKL =   1
        END IF
        IF (IHKL > IHKLM) THEN
          IHKLM = IHKL
          IF (I > 1) IASM = 0
        END IF
        IHKLM = MAX (IHKLM, IHKL)
        IF (MODE == 1) THEN
          DO J = 1, 3
            IHKLS(J, I) = IND(J)
          END DO
          IHKLS(4, I) = IHKL
          IHKLS(5, I) = ISHKL
C * PHASE SHIFT IN RADIANS
          PHIS(I) = SGX(10) / RGBL(6)
        END IF
      END DO
      RETURN
      END SUBROUTINE PLA136
 
      SUBROUTINE PLA137 (IH, IK, IL, ACAL, BCAL, ACALA, BCALA,
     1  ACALAF, BCALAF, SNTHA)
C * STRUCTURE FACTOR CALCULATION ROUTINE
C * (BASED ON SYMMETRY EXPANDED COORD SET)
C * CALLED FROM PLA130, PLA135, PLA145, PLA146, PLA147, PLA160,
C *             PLA186, PLA202, PLA253, PLA351, PLA405
      USE parameters
      USE plato
      USE atomdata
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IBV
      INTEGER :: NAT
      INTEGER :: ICENT
      REAL :: TF
      REAL :: TF1
      REAL :: TF2
      REAL :: ARG
      REAL :: FSC
      REAL :: CARG
      REAL :: SARG
      REAL :: FACT
      REAL :: ACAL
      REAL :: BCAL
      REAL :: STLK
      REAL :: YUNK
      REAL :: FACTC
      REAL :: FACTD
      REAL :: FACTR
      REAL :: ACALA
      REAL :: BCALA
      REAL :: SNTHA
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN095
      REAL, DIMENSION(6) :: D
C * NUMBER OF ATOMS IN THE UNIT CELL (EXCLUDING LATTICE CENTERING)
      NAT    = IPR(589)
C * BRAVAIS LATTICE TYPE/MULT
      IBV    = IPR(256)
C * (A)CENTROSYMMETRIC  (1/2)
      ICENT  = IPR(257)
      ACAL   = 0.0
      BCAL   = 0.0
      ACALA  = 0.0
      BCALA  = 0.0
      ACALAF = 0.0
      BCALAF = 0.0
C * T = exp(-2pi^2^[h^2^(a*)^2^U11+k^2^(b*)^2^U22+ ... + 2hka*b*U12])
      D(1) = IH**2   * PAR(191)
      D(2) = IK**2   * PAR(192)
      D(3) = IL**2   * PAR(193)
      D(4) = IK * IL * PAR(114) * PAR(115) * 2.0
      D(5) = IH * IL * PAR(113) * PAR(115) * 2.0
      D(6) = IH * IK * PAR(113) * PAR(114) * 2.0
C * CALCULATE (SIN(THETA) / LAMBDA)**2 AND SIN(THETA)
      STLK  = GEN095 (PAR(191), IH, IK, IL)
      SNTHA = SQRT (STLK) * PAR(17)
C * IPR(414) = 0 - SF-CALC
C *            1 - FO-MAP      (CONTOUR)
C *            2 - 2FO-FC-MAP  (CONTOUR)
C *            3 - FO-FC-MAP   (CONTOUR)
C *            4 - SQUEEZE-MAP (CONTOUR)
C *            5 - PATT-MAP    (CONTOUR)
C * SF-CALC EXCEPT FOR SQUEEZE-CONTOUR AND PATTERSON
        TF1 = - RGBL(8) * STLK
        TF2 = - TF1 * 100
C * CALCULATE STRUCTURE FACTOR (ACAL, BCAL, ACALA, BCALA for HKL & -H-K-L)
        DO I = 1, NAT
C * CHECK FOR NON-ZERO POPULATION
          IF (XXO(I, 4) > 0.0) THEN
            ARG  = RGBL(5) * (IH * XXO(I, 1) + IK * XXO(I, 2)
     1           + IL * XXO(I, 3))
            CARG = COS (ARG)
            SARG = SIN (ARG)
C * DISPLACEMENT PARAMETERS - ISO/ANISO FLAG
C * ISOTROPIC
            IF (XSD(I, 1) > 99.0) THEN
              YUNK = - TF1 * XSD(I, 1) - TF2
C * ANISOTROPIC
            ELSE
              TF = 0.0
              DO J = 1, 6
                TF = TF + XSD(I, J) * D(J)
              END DO
              YUNK = RGBL(7) * TF
            END IF
            IF (YUNK < 30) THEN
              TF = EXP (- YUNK)
            ELSE
              TF = 0.0
            END IF
            FACT = XXO(I, 4) * IBV * TF
C * GET SCATTERING FACTOR
            FSC = CON(I, 9)
C * CONSTANT Z VALUE SCATTERING FACTORS FOR E**2 PATTERSON
            IF (IABS (IPR(493)) < 9) THEN
              DO J = 1, 7, 2
C * HANDLE UNDERFLOW
                YUNK = CON(I, J + 1) * STLK
                IF (YUNK < 30) FSC = FSC + CON(I, J) * EXP (- YUNK)
              END DO
            END IF
C * REAL SCATTERING CONTRIBUTION  (ACAL, BCAL)
            FACTR = FACT * FSC
            ACAL  = ACAL + FACTR * CARG
            IF (ICENT == 1) BCAL = BCAL + FACTR * SARG
C * COMPLEX SCATTERING CONTRIBUTION DUE TO F'' (ACALA, BCALA) FOR XRAY
C * EXCLUDED FOR NEUTRON AND ELECTRON SCATTERING
            IF (IABS(IPR(493)) < 7) THEN
              J = IATP(I)
              IF (J /= 0) THEN
                FACTD = FACT  * ANOM(J, 1)
                FACTC = FACT  * ANOM(J, 2)
                ACALA = ACALA + FACTD * CARG
                BCALA = BCALA + FACTC * CARG
C * ANOMALOUS CONTRIBUTION TO FRIEDEL PAIRED REFLECTION
                ACALAF = ACALAF + FACTD * CARG
                BCALAF = BCALAF + FACTC * CARG
C * ADD FOR NON-CENTRO CASE
                IF (ICENT == 1) THEN
                  ACALA = ACALA - FACTC * SARG
                  BCALA = BCALA + FACTD * SARG
C * ANOMALOUS CONTRIBUTION TO FRIEDEL PAIRED REFLECTION
                  ACALAF = ACALAF + FACTC * SARG
                  BCALAF = BCALAF - FACTD * SARG
                END IF
              END IF
            END IF
          END IF
        END DO
      RETURN
      END SUBROUTINE PLA137
 
