      SUBROUTINE PLA139 (LUN0, LUN1, LUN2, NREFF)
C * FCF TO HKL EXTRACTION
      USE parameters
      USE atomdata
      USE cchar
      USE mentry
      USE analysis
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: JE
      INTEGER :: NL
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: LUN0
      INTEGER :: LUN1
      INTEGER :: LUN2
      INTEGER :: NREFF
      INTEGER :: IOST
      INTEGER :: IDTYP
      INTEGER :: IYUNK
      INTEGER :: NSKIP
      INTEGER :: IFTYPE
      INTEGER :: ISTATE
      REAL :: XT
      REAL :: TH
      REAL :: ST
      REAL :: FC
      REAL :: FCK
      REAL :: FOK
      REAL :: SCF
      REAL :: FKMX
      REAL :: YUNK
      REAL :: SFOK
      REAL :: XFCAL
      REAL :: XFOBS
      REAL :: XSIGI
      REAL :: GEN095
      CHARACTER(len=1) :: STATX
      IDTYP = IENTRY(IGBL(54), 3)
      CALL GEN074 (REFLCELL, 1, 6, 0.0)
      IF (IDTYP /= 0) THEN
        IFTYPE = 0
        SCF    = 0.0
        FKMX   = 0.0
        NREFF  = 0
        NSKIP  = 0
        IF (IABS (IDTYP) == 7) THEN
          FMOL = '(3I4,3F8.0)'
        ELSE
          FMOL = '(I4,2I3,2F7.0,F6.0)'
        END IF
C * REFLECTION FILE TYPES ARE IDENTIFIED IN PLA008-10
C * IDTYP =  1 - FCF (SHELXL LIST 4)
C * IDTYP =  2 - XTAL-F
C * IDTYP =  3 - NRCVAX
C * IDTYP =  4 - MOLEN
C * IDTYP =  5 - CRYSTALS(F)
C * IDTYP =  6 - TEXSAN1
C * IDTYP =  7 - MOLEN1 VARIANT
C * IDTYP =  8 - CRYSTALS(I)
C * IDTYP =  9 - JANA2 (F**2)
C * IDTYP = 10 - TEXSAN2
C * IDTYP = 11 - XD
C * IDTYP = 12 - REALS
C * IDTYP = 13 - TEXSAN3
C * IDTYP = 14 - JANA1 (F)
C * IDTYP = 15 - RIGAKU
C * IDTYP = 16 - JANA3-STYLE
C * IDTYP = 17 - CRYSTALS(I,TWIN)
C * IDTYP = 18 - CRYSTL3
C * IDTYP = 21 - SHELXL - LIST 3
C * IDTYP = 22 - SHELXL - LIST 5
C * IDTYP = 23 - SHELXL - LIST 6
C * IDTYP = 24 - SHELXL - LIST 7
C * IDTYP = 25 - SHELXL - LIST 8
C * IDTYP = 26 - REALS - FCF
        IF (IDTYP > 0 .AND. IABS (IGBL(8)) == 3) THEN
          NSKIP = IENTRY(IGBL(54), 4)
          IF (NSKIP > 0) THEN
            GO TO 10
          ELSE
            GO TO 50
          END IF
        ELSE
          IDTYP = IABS (IDTYP)
        END IF
C * LOOP TWICE TO DETERMINING SCALING WITHIN FORMAT
   10   DO I = 1, 2
          REWIND (UNIT = LUN1, IOSTAT = IOST)
          REWIND (UNIT = LUN2, IOSTAT = IOST)
          DO J = 1, NSKIP
            READ (LUN1, 99996) LINE
          END DO
          IF (I == 2) THEN
            IF (FKMX < 999999.0) THEN
              SCF = 100.0
            ELSE
              SCF = FLOAT (90000000) / FKMX
            END IF
          END IF
   20     READ (LUN1, 99996, IOSTAT = IOST) LINE
          IF (IOST == -1) CYCLE
C * HANDLE EXTRA LF & CR
          NL = INDEX (LINE, CHAR (13))
          IF (NL /= 0) LINE(NL:NL) = CHAR (32)
          SELECT CASE (IDTYP)
C * SHELXL FCF
            CASE (1)
              IFTYPE = 0
              ISTATE = 0
              IDM = 'LATT P A'
              CALL SGSM (0, IDM, SGX, 0, 0, IERR)
              DO
                READ (LUN1, 99996, IOSTAT = IOST) LINE
                IF (IOST == -1) EXIT
                NL = INDEX (LINE, CHAR (13))
                IF (NL /= 0) LINE(NL:NL) = CHAR (32)
                IF (I == 1) THEN
                  IF (ISTATE == 0) THEN
                    J = INDEX (LINE, '_space_group_symop_operation_xyz')
                    IF (J == 0) THEN
                      J = INDEX (LINE, '_symmetry_equiv_pos_as_xyz')
                    END IF
                    IF (J > 0) ISTATE = 1
                  ELSE IF (ISTATE == 1) THEN
                    J = INDEX (LINE, '_cell_length_a')
                    IF (J > 0) THEN
                      JE = INDEX (LINE(J+14:80), '(')
                      IF (JE /= 0) THEN
                        JE = J + JE + 12
                      ELSE
                        JE = 80
                      END IF
                      READ (LINE(J+14:JE), *) REFLCELL(1)
                      ISTATE = 2
                      CALL SGSM (18, IDM, SGX, 0, 0, IERR)
                      SPGRNAMF = IDM(15:26)
                      IPR(241) = NINT (SGX(7))
                      IPR(255) = NINT (SGX(4))
                    ELSE
                      J  = INDEX (LINE, '''')
                      IF (J /= 0) THEN
                        K = INDEX (LINE(J+1:80), '''')
                        IF (K /= 0) THEN
                          IDM = 'SYMM '//LINE(J+1:K +J -1)
                          CALL SGSM (0, IDM, SGX, 0, 0, IERR)
                        END IF
                      END IF
                    END IF
                  ELSE IF (ISTATE == 2) THEN
                    J = INDEX (LINE, '_cell_length_b')
                    IF (J > 0) THEN
                      JE = INDEX (LINE(J+14:80), '(')
                      IF (JE /= 0) THEN
                        JE = J + JE + 12
                      ELSE
                        JE = 80
                      END IF
                      READ (LINE(J+14:JE), *) REFLCELL(2)
                    ELSE
                      J = INDEX (LINE, '_cell_length_c')
                      IF (J > 0) THEN
                        JE = INDEX (LINE(J+14:80), '(')
                        IF (JE /= 0) THEN
                          JE = J + JE + 12
                        ELSE
                          JE = 80
                        END IF
                        READ (LINE(J+14:JE), *) REFLCELL(3)
                      ELSE
                        J = INDEX (LINE, '_cell_angle_alpha')
                        IF (J > 0) THEN
                          JE = INDEX (LINE(J+17:80), '(')
                          IF (JE /= 0) THEN
                            JE = J + JE + 15
                          ELSE
                            JE = 80
                          END IF
                          READ (LINE(J+17:JE), *) REFLCELL(4)
                        ELSE
                          J = INDEX (LINE, '_cell_angle_beta')
                          IF (J > 0) THEN
                            JE = INDEX (LINE(J+16:80), '(')
                            IF (JE /= 0) THEN
                              JE = J + JE + 14
                            ELSE
                              JE = 80
                            END IF
                            READ (LINE(J+16:JE), *) REFLCELL(5)
                          ELSE
                            J = INDEX (LINE, '_cell_angle_gamma')
                            IF (J > 0) THEN
                              JE = INDEX (LINE(J+17:80), '(')
                              IF (JE /= 0) THEN
                                JE = J + JE + 15
                              ELSE
                               JE = 80
                              END IF
                               READ (LINE(J+17:JE), *) REFLCELL(6)
                               ISTATE = 3
                            END IF
                          END IF
                        END IF
                      END IF
                    END IF
                  END IF
                END IF
                IF (INDEX (LINE,  '_refln_F_squared_calc') /= 0) THEN
                  IFTYPE = IFTYPE * 10 + 2
                ELSE IF (INDEX (LINE, '_refln_F_squared_meas') /= 0)
     1            THEN
                  IFTYPE = IFTYPE * 10 + 1
                END IF
                IF (INDEX (LINE, '_refln_observed_status') /= 0 .OR.
     1              INDEX (LINE, '_refln_include_status')  /= 0) THEN
                  READ (LUN1, 99996, IOSTAT = IOST) LINE
                  IF (IOST == -1) CYCLE
                  IF (INDEX (LINE, '_refln_sint/lambda') == 0)
     1               BACKSPACE (LUN1)
                  GO TO 40
                END IF
              END DO
C * MOLEN
            CASE (4)
              IF (INDEX (LINE, '_refln_10*F_sigm') == 0 .OR.
     1            INDEX (LINE, '_refln_F_10*sigm') == 0) GO TO 20
              GO TO 40
C * CRYSTALS(F)
            CASE (5)
              DO
                READ  (LUN1, 99996, IOSTAT = IOST) LINE
                IF (IOST == -1) CYCLE
                WRITE (LUN0, 99996) LINE
                IF (INDEX (LINE, '_refln_refinement_weight') /= 0)
     1            GO TO 40
              END DO
C * TEXSAN & RIGAKU
            CASE (6, 13, 15)
              IF (INDEX (LINE, '_refln_observed_status') == 0 .AND.
     1            INDEX (LINE, '_refln_include_status') == 0) GO TO 20
              GO TO 40
C * MOLEN1
            CASE (7)
              IF (INDEX (LINE, '_refln_observed_status') == 0)
     1          GO TO 20
              GO TO 40
C * CRYSTALS(I)
            CASE (8)
              IF (INDEX (LINE, '_refln_index') == 0) THEN
                GO TO 20
              ELSE
                DO
                  READ (LUN1, 99996, IOSTAT = IOST) LINE
                  IF (IOST == -1) CYCLE
                  IF (INDEX (LINE, '_refln_') == 0) THEN
                    BACKSPACE LUN1
                    GO TO 40
                  END IF
                END DO
              END IF
C * JANA1 & JANA2
            CASE (9, 14)
              IF (INDEX (LINE, '_refln_observed_status') == 0 .AND.
     1            INDEX (LINE, '_refln_include_status') == 0) GO TO 20
              GO TO 40
C * XD
            CASE (11)
              IF (INDEX (LINE, '_refln_XD_refine_code') == 0)
     1          GO TO 20
              GO TO 40
C * JANA3-STYLE FCF
            CASE (16)
              IF (INDEX (LINE, '_refln_observed_status') == 0)
     1          GO TO 20
              GO TO 40
C * SHELXL LIST 3
            CASE (21)
              IF (INDEX (LINE, '_refln_B_calc') == 0) GO TO 20
              GO TO 40
C * SHELXL LIST 6
            CASE (23)
              IF (INDEX (LINE, '_refln_phase_calc') == 0) GO TO 20
              GO TO 40
C * SHELXL LIST 7
            CASE (24)
              READ (LINE, *, IOSTAT = IOST)
     1          IYUNK,IYUNK,IYUNK,YUNK,YUNK,YUNK,YUNK
              IF (IOST /= 0) GO TO 20
C * DUMMY STATEMENT
              YUNK = FLOAT (IYUNK) + YUNK
            CASE (25)
              IF (INDEX (LINE, '_shelx_refinement_sigma') == 0) THEN
                GO TO 20
              ELSE
                GO TO 40
              END IF
C * REALS
            CASE (26)
              IF (INDEX (LINE, '_refln_F_sigma') == 0) GO TO 20
              GO TO 40
C * DEFAULT
            CASE DEFAULT
              CYCLE
          END SELECT
          BACKSPACE LUN1
          GO TO 40
   30     IF (I == 1) WRITE (LUN0, 99989, IOSTAT = IOST) LINE(1:50)
C * DUMMY
          IF (IOST == -999) RETURN
C * FCF REFLECTION READ LOOP
   40     DO
            READ (LUN1, 99996, IOSTAT = IOST) LINE
            IF (IOST == -1) EXIT
            NL = INDEX (LINE, CHAR (13))
            IF (NL /= 0) LINE(NL:NL) = CHAR (32)
            SELECT CASE (IDTYP)
C * SHELXL
              CASE (1)
                IF (LINE(1:1) == '#') EXIT
                IF (LINE(1:10) == '          ') CYCLE
                IF (INDEX (LINE, 'data_') /= 0) EXIT
                IF (IFTYPE == 12) THEN
                  READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FOK, FCK,
     1                                          SFOK
                  IF (IOST /= 0) THEN
                    IF (IOST == -1) THEN
                      EXIT
                    ELSE
                      GO TO 30
                    END IF
                  END IF
                ELSE IF (IFTYPE == 21) THEN
                  READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FCK, FOK,
     1                                          SFOK
                  IF (IOST /= 0) THEN
                    IF (IOST == -1) THEN
                      EXIT
                    ELSE
                      GO TO 30
                    END IF
                  END IF
                END IF
C * HANDLE EXTINCTION CORRECTION (SHELXL ONLY)
                IF (PAR(229) > 0.0) THEN
                  ST  = SQRT (GEN095 (PAR(191), IH, IK, IL)) * PAR(17)
                  TH  = ASIN (ST)
                  XT  = (1.0 + (0.001 * PAR(229) * FCK * PAR(17)**3) /
     1                  SIN (2.0 * TH)) ** 0.5
                  FOK  = FOK  / XT
                  SFOK = SFOK / XT
                END IF
C * DUMMY
                FCK = FCK + 0.0
C * MOLEN
              CASE (4, 7)
                READ (LINE, FMOL, IOSTAT = IOST) IH, IK, IL,
     1                XFOBS, XFCAL, XSIGI
                IF (IOST /= 0) EXIT
                FOK  = SIGN (XFOBS**2, XFOBS) / 100.0
                SFOK = 2.0 * ABS (XFOBS) * XSIGI / 100.0
C * CRYSTALS(F)
              CASE (5)
                READ (LINE, 99998, IOSTAT = IOST)
     1            IH, IK, IL, XFOBS, XFCAL, XSIGI, STATX
                IF (IOST  /= 0) CYCLE
                IF (STATX == 'x') CYCLE
                IF (STATX == '<') CYCLE
                IF (STATX == 'l') CYCLE
                IF (STATX == 'h') CYCLE
                FOK  = SIGN (XFOBS**2, XFOBS)
                SFOK = 2.0 * ABS (XFOBS) * XSIGI
C * CRYSTALS(I)
              CASE (8)
                READ (LINE, 99998, IOSTAT = IOST) IH, IK, IL, FOK, FCK,
     1                                      SFOK, STATX
                IF (IOST == -1) EXIT
                IF (STATX == 'x') CYCLE
                IF (STATX == '<') CYCLE
                IF (STATX == 'l') CYCLE
                IF (STATX == 'h') CYCLE
C * JANA2
              CASE (9)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FOK, FCK,
     1                                        SFOK
                IF (IOST == -1) EXIT
C * JANA1
              CASE (14)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, XFOBS, XFCAL,
     1                                        XSIGI
                IF (IOST == -1) EXIT
                FOK = XFOBS ** 2
                FCK = XFCAL ** 2
                IF (XFOBS > XSIGI / 2.0) THEN
                  SFOK = 2.0 * ABS (XFOBS) * XSIGI
                ELSE
                  SFOK = 2.0 * ABS (XFCAL) * XSIGI
                END IF
C * JANA3-STYLE FCF
              CASE (16)
                READ (LINE, 99997, IOSTAT = IOST)
     1            IH, IK, IL, XFCAL, FOK, SFOK, STATX
                IF (IOST == -1) EXIT
C * TEXSAN1 FCF
              CASE (6)
                READ (LINE, 99993, IOSTAT = IOST) IH, IK, IL, XFOBS,
     1                                            XSIGI, XFCAL
                IF (IOST == -1) EXIT
                FOK = SIGN (XFOBS**2, XFOBS)
                FCK = XFCAL ** 2
                IF (XFOBS > XSIGI / 2.0) THEN
                  SFOK = 2.0 * ABS (XFOBS) * XSIGI
                ELSE
                  SFOK = 2.0 * ABS (XFCAL) * XSIGI
                END IF
C * TEXSAN3/RIGAKU FCF
              CASE (13, 15)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FOK, SFOK,
     1                                        FCK
                IF (IOST == -1) EXIT
C * XD FCF (F)
              CASE (11)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FCK, FOK,
     1                                        SFOK, YUNK
                IF (IOST == -1) EXIT
C * SHELXL - LIST 3
              CASE (21)
                IF (LINE(1:1) == '#') EXIT
                IF (LINE(1:10) == '          ') CYCLE
                IF (INDEX (LINE, 'data_') /= 0) EXIT
                READ (LINE, 99991, IOSTAT = IOST) IH, IK, IL, XFOBS,
     1                                            XSIGI
                IF (IOST == -1) EXIT
                IF (XFOBS > 0.0 .AND. XSIGI > 0) THEN
                  FOK  = XFOBS**2
                  SFOK = 2.0 * SQRT (FOK) * XSIGI
                ELSE
                  CYCLE
                END IF
C * SHELXL - LIST 6
              CASE (23)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FOK, SFOK, FC
                IF (IOST == -1) EXIT
                FCK = FC**2
C * SHELXL - LIST 7
              CASE (24)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FOK, SFOK, FCK
                IF (IOST == -1) EXIT
C * SHELXL - LIST 8
              CASE (25)
                READ (LINE, *, IOSTAT = IOST) IH, IK, IL, FOK, SFOK, FCK
                IF (IOST == -1) EXIT
C * REALS FCF F
                CASE (26)
                READ (LINE, 99990, IOSTAT = IOST) IH, IK, IL, XFOBS,
     1                                            XFCAL, XSIGI
                IF (IOST == -1) EXIT
                FOK  = SIGN (XFOBS**2, XFOBS)
                SFOK = 2.0 * ABS (XFOBS) * XSIGI
                IF (SFOK < 0.0001) CYCLE
            END SELECT
            IF (IH == 0 .AND. IK == 0 .AND. IL == 0) EXIT
            IF (I == 1) THEN
              IF (FOK  > FKMX) FKMX = FOK
              IF (SFOK > FKMX) FKMX = SFOK
            ELSE
              NREFF = NREFF + 1
              WRITE (LUN2, 99999, IOSTAT = IOST)
     1          IH, IK, IL, NINT (FOK * SCF), NINT (SFOK * SCF)
            END IF
          END DO
        END DO
      ELSE
        CALL GEN127 ('No Recognizable FCF')
      END IF
        IF (IDTYP == 1 .AND. PAR(229) > 0.0)
     1    WRITE (LUN0, 99988, IOSTAT = IOST) PAR(229)
      IF (NREFF == 0) THEN
        WRITE (LUN0, 99994, IOSTAT = IOST)
      ELSE
        WRITE (LUN2, 99992, IOSTAT = IOST)
      END IF
      RETURN
   50 WRITE (LUN0, 99995, IOSTAT = IOST) NREFF
      CALL GEN127 (' ')
99999 FORMAT (3I4, 2I8)
99998 FORMAT (3I4, 3F12.2, 1X, A, E13.4)
99997 FORMAT (3I4, 3F9.0, 1X, A)
99996 FORMAT (A)
99995 FORMAT (':: STOP: Free Read Problem in FCF-file NREFF =', I6)
99994 FORMAT (/, ':: No Suitable Reflections found in FCF-file', /)
99993 FORMAT (I4, 2I5, 3F11.2)
99992 FORMAT (//)
99991 FORMAT (3I4, 4F12.0)
99990 FORMAT (3I4, 2F9.0, F7.0)
99989 FORMAT ('Free Format READ Problem: ', A)
99988 FORMAT (/, ':: Retro Extinction Correction Applied on Fo**2',
     1        ' - EXTI =', F7.4, /)
      END SUBROUTINE PLA139
 
      SUBROUTINE PLA140 (FFT, R3D, NATO, RHOMIN, MODE, NPK, IPOSNEG,
     1 NSYM)
C * PEAK SEARCH
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: IR
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IZ
      INTEGER :: MN
      INTEGER :: MX
      INTEGER :: NO
      INTEGER :: NZ
      INTEGER :: NAT
      INTEGER :: NPK
      INTEGER :: ISW
      INTEGER :: NNX
      INTEGER :: NNY
      INTEGER :: NNZ
      INTEGER :: NXY
      INTEGER :: MAXX
      INTEGER :: NOP1
      INTEGER :: NPIC
      INTEGER :: KSYM
      INTEGER :: NATO
      INTEGER :: MODE
      INTEGER :: NSYM
      INTEGER :: NXY3
      INTEGER :: LIMIT
      INTEGER :: KUSER
      INTEGER :: IPOSNEG
      INTEGER, DIMENSION(19) :: IDF
      REAL :: C
      REAL :: D
      REAL :: E
      REAL :: F
      REAL :: B1
      REAL :: B2
      REAL :: DX
      REAL :: DY
      REAL :: DZ
      REAL :: DM
      REAL :: XX
      REAL :: YY
      REAL :: ZZ
      REAL :: DELTAX
      REAL :: DELTAY
      REAL :: DELTAZ
      REAL :: RHOMIN
      REAL :: XLEVEL
      REAL :: GEN006
      REAL, DIMENSION(*)  :: FFT
      REAL, DIMENSION(*)  :: R3D
      REAL, DIMENSION(3)  :: XS
      REAL, DIMENSION(3)  :: X1
      REAL, DIMENSION(3)  :: DXMAX
      REAL, DIMENSION(19) :: B
C * MODE = -3 : DIFFERENCE MAP
      IF (MODE /= 0) THEN
        ISW = 3
      ELSE
        ISW = -3
      END IF
C * INPUT DATA FROM FFT FILE
      NNX   = IPR(395)
      NNY   = IPR(396)
      NNZ   = IPR(397)
C * INPUT DIMENSIONS OF MAP AND CHECK ARRAY SIZE
      NXY   = (NNX + 2) * (NNY + 2)
      NXY3  = 3 * NXY
C * INITIALISE CONSTANTS
      DX    = 1.0 / FLOAT (NNX)
      DY    = 1.0 / FLOAT (NNY)
      DZ    = 1.0 / FLOAT (NNZ)
C * KUSER = MAXIMUM NUMBER OF PEAKS TO BE FOUND + 20,
C *         ALSO MAXIMUM NUMBER OF PEAKS FOR INTERPRETATION
      KUSER = NP1 - NATO
      NAT   = KUSER - 20
      NPIC  = KUSER - 20
      LIMIT = MIN (KUSER, 2 * NAT)
C * IF 2 PEAKS ARE CLOSER THAN DM THE SMALLER IS ELIMINATED
      DM    = 0.50
C * SET UP CONSTANTS
      DO I = 1, 3
        DXMAX(I) = DM * PAR(112 + I)
      END DO
      DM = DM ** 2
C * SEARCH MAP FOR PEAK POSITIONS AND RECORD PEAK HEIGHTS
C * FIND POSITIONS OF PEAKS BY FITTING QUADRATIC FUNCTION TO 19 POINTS
      XLEVEL  = RHOMIN
C * SET UP TABLE OF OFFSETS TO LOOK UP 19 POINTS IN MAP
      IDF(1)  = - NXY - 1
      IDF(2)  = - NXY - NNX - 2
      IDF(3)  = - NXY
      IDF(4)  = - NXY + NNX + 2
      IDF(5)  = - NXY + 1
      IDF(6)  = - NNX - 3
      IDF(7)  = - 1
      IDF(8)  =   NNX + 1
      IDF(9)  = - NNX - 2
      IDF(10) = 0
      DO I = 1, 9
        IDF(20 - I) = - IDF(I)
      END DO
C * INITIALISE VARIABLES
      NO = 0
      IZ = - 1
      NZ = 0
   10 N  = - 1
      IF (IZ + 2 /= NNZ) THEN
C * READ IN FIRST SECTION (END OF LAST UNIT CELL)
        MAXX = NXY
        N    = NNZ - 1
        CALL PLA141 (FFT, R3D, MAXX, NNX, NNY, NXY3, N, IPOSNEG)
C * READ SECOND SECTION (START OF UNIT CELL)
        N   = 0
        CALL PLA141 (FFT, R3D, MAXX, NNX, NNY, NXY3, N, IPOSNEG)
      END IF
C * READ IN THE NEXT SECTION
   20 MX = MAXX - NXY + NNX + 1
      N  = N + 1
      CALL PLA141 (FFT, R3D, MAXX, NNX, NNY, NXY3, N, IPOSNEG)
      IZ = IZ + 1
      NZ = MOD (NZ + 2, 3) - 1
      M  = ISIGN (NXY3, NZ)
      IF (NZ <= 0) THEN
        DO I = 1, 5
          IDF(I) = IDF(I) - M
        END DO
        IF (NZ == 0) GO TO 30
      END IF
      DO I = 15, 19
        IDF(I) = IDF(I) - M
      END DO
C * SEARCH ONE SECTION OF THE MAP
   30 DO IY = 1, NNY
        MN = MX + 3
        MX = MX + NNX + 2
        DO 70 IX = MN, MX
          IF (R3D(IX) >= XLEVEL) THEN
C * LOCATE GRID POINT WITH MAXIMUM DENSITY
            DO I = 1, 9
              J = IDF(I) + IX
              IF (R3D(IX) <= R3D(J)) GO TO 70
            END DO
            DO I = 11, 19
              J = IDF(I) + IX
              IF (R3D(IX) < R3D(J)) GO TO 70
            END DO
C * FIT QUADRATIC FUNCTION TO 19 POINTS
C * DENS = A + C*X + D*Y + E*Z - 0.5*F*(X*X + Y*Y + Z*Z)
            DO I = 1, 19
              B(I) = R3D(IDF(I) + IX)
            END DO
            B1 = B(3)  + B(7)  + B(9)  + B(11) + B(13) + B(17)
            B2 = B(1)  + B(2)  + B(4)  + B(5)  + B(6)  + B(8) + B(12)
     1         + B(14) + B(15) + B(16) + B(18) + B(19)
            F  = (30.0 * B(10) + 11.0 * B1 - 8.0 * B2) / 63.0
            C  = (B(5) + B(12) + B(13) + B(14) + B(19) - B(1) - B(6)
     1         - B(7) - B(8) - B(15)) / 10.0
            DELTAX = C / F
            IF (ABS (DELTAX) <= 1.0) THEN
              D = (B(15) + B(16) + B(17) + B(18) + B(19) - B(1) - B(2)
     1          - B(3) - B(4) - B(5)) / 10.0
              DELTAY = D / F
              IF (ABS (DELTAY) <= 1.0) THEN
                E  = (B(4) + B(8) + B(11) + B(14) + B(18) - B(2) - B(6)
     1             - B(9) - B(12) - B(16)) / 10.0
                DELTAZ = E / F
                IF (ABS (DELTAZ) <= 1.0) GO TO 40
              END IF
            END IF
            DELTAX = 0.0
            DELTAY = 0.0
            DELTAZ = 0.0
   40       XX     = (FLOAT (IX - MN + 1) + DELTAX) * DX
            YY     = (FLOAT (IY)          + DELTAY) * DY
            ZZ     = (FLOAT (IZ)          + DELTAZ) * DZ
            NOP1                = NO + 1
            XXO(NATO + NOP1, 1) = XX
            XXO(NATO + NOP1, 2) = YY
            XXO(NATO + NOP1, 3) = ZZ
            XXO(NATO + NOP1, 4) = B(10)
            XXO(NATO + NOP1, 5) = F
            IF (NO > 0) THEN
              IR = 0
C * IF TWO PEAKS ARE CLOSER THAN DM ANGSTROMS ELIMINATE THE SMALLER
              DO K = 1, 3
                SGY(K)     = XXO(NATO + NOP1, K)
                SGY(K + 3) = 0.0
              END DO
              DO K = 1, NSYM
                KSYM = K
                CALL SGSM (ISW, ICL, SGY, KSYM, 6, IERR)
                XS(1) = SGY(7)
                XS(2) = SGY(8)
                XS(3) = SGY(9)
                DO 60 I = 1, NO
                  DO L = 1, 3
                    X1(L) = XXO(NATO + I, L) - XS(L)
   50               IF (ABS (X1(L)) <= 0.5) THEN
                      IF (ABS (X1(L)) > DXMAX(L)) THEN
                        GO TO 60
                      ELSE
                        CYCLE
                      END IF
                    END IF
                    X1(L) = X1(L) - SIGN (1.0, X1(L))
                    IF (.TRUE.) GO TO 50
                  END DO
                  IF (GEN006 (X1, AA, X1) <= DM) THEN
                    IF (B(10) <= XXO(NATO + I, 4)) GO TO 70
                    IF (IR > 0) XXO(NATO + IR, 4) =  -1.0
                    IR               = 0
                    XXO(NATO + I, 1) = XX
                    XXO(NATO + I, 2) = YY
                    XXO(NATO + I, 3) = ZZ
                    XXO(NATO + I, 4) = B(10)
                    XXO(NATO + I, 5) = F
                    IR               = I
                  END IF
   60           CONTINUE
              END DO
              IF (IR > 0) GO TO 70
            END IF
            NO = NOP1
            IF (NO >= LIMIT) THEN
              CALL GEN091 (XXO, DUMA, NP1, 6, NATO, NO, 4)
              NO     = NPIC
              XLEVEL = XXO(NATO + NPIC, 4)
            END IF
          END IF
   70   CONTINUE
      END DO
      IF (IZ < NNZ) THEN
        IF (IZ == (NNZ - 2)) THEN
          GO TO 10
        ELSE
          GO TO 20
        END IF
      END IF
C * SORT PEAKS IN ORDER OF PEAK HEIGHT (EL #4)
      CALL GEN091 (XXO, DUMA, NP1, 6, NATO, NO, 4)
      NPK = NO
      IF (MODE < 0) THEN
        N1 = NATO + 1
        N2 = NATO + NPK
C * GET ENVIRONMENT OF THE MAXIMA
C * DIFFERENCE MAP MODE
        IF (NPK > 0) THEN
          IF (MODE == -3) THEN
            N2 = MIN (N2, N1 + 24)
            CALL PLA143 (-1, 3.2, N1, N2, IPOSNEG)
            CALL PLA361 (1.2, N1, N2, IPOSNEG)
          ELSE
            CALL PLA143 (1, 3.2, N1, N2, IPOSNEG)
          END IF
        ELSE
          IF (IGBL(63) > 0) THEN
            IF (IPOSNEG > 0) THEN
              WRITE (LU6, 99999, IOSTAT = IOST)  RHOMIN / PAR(98)
            ELSE
              WRITE (LU6, 99998, IOSTAT = IOST) -RHOMIN / PAR(98)
            END IF
          END IF
        END IF
      END IF
99999 FORMAT (/, ':: No Positive Density Peaks > ', F5.2, ' eA^3', /)
99998 FORMAT (/, ':: No Negative Density Peaks < ', F5.2, ' eA^3', /)
      RETURN
      END SUBROUTINE PLA140
 
      SUBROUTINE PLA141 (FFT, R3D, IMAX, NNX, NNY, NXY3, NZ, IPOSNEG)
C * FOURIER + PEAKS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: MX
      INTEGER :: NZ
      INTEGER :: LOC
      INTEGER :: NNX
      INTEGER :: NNY
      INTEGER :: IMIN
      INTEGER :: IMAX
      INTEGER :: NXY3
      INTEGER :: IPOSNEG
      REAL, DIMENSION(*) :: FFT
      REAL, DIMENSION(*) :: R3D
C * LOAD XY-LAYER (+ 2 ADDITIONAL COLUMNS AND ROWS)
      IF (IMAX >= NXY3) IMAX = 0
      MX   = IMAX
      IMAX = IMAX - 2
      LOC  = NNX * NNY * NZ
      DO IY = 1, NNY
        IMIN = IMAX + 3
        IMAX = IMAX + NNX + 2
        DO I = IMIN, IMAX
          LOC    = LOC + 1
          R3D(I) = AMAX1 (0.0, FFT(2 * LOC - 1) * IPOSNEG)
        END DO
C * ADD/COPY TWO COLUMN ENTRIES
        R3D(IMAX + 1) = R3D(IMIN)
        R3D(IMAX + 2) = R3D(IMIN + 1)
      END DO
C * ADD/COPY TWO ROWS
      IMIN = IMAX + 3
      IMAX = IMAX + 2 * NNX + 6
      DO IX = IMIN, IMAX
        MX      = MX + 1
        R3D(IX) = R3D(MX)
      END DO
      RETURN
      END SUBROUTINE PLA141
 
      SUBROUTINE PLA142 (MODE, VOD, FFT, R3D, NREF, FS000)
C * FFT & PEAKSEARCH
      USE files
      USE parameters
      USE reflex
 
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: NPK
      INTEGER :: LOC
      INTEGER :: NATO
      INTEGER :: NMAX
      INTEGER :: MODE
      INTEGER :: NREF
      INTEGER :: NGRD2
      REAL :: AC
      REAL :: BC
      REAL :: FS000
      REAL :: RHOMIN
      REAL, DIMENSION(*) :: VOD
      REAL, DIMENSION(*) :: FFT
      REAL, DIMENSION(*) :: R3D
      WRITE (LU6, 99999) FS000
      WRITE (LU7, 99999) FS000
C * FILL FFT ARRAY WITH FRIEDEL MERGED REFLECTION DATA
      NATO  = IPR(589)
      M1    = IPR(395)
      M2    = IPR(396)
      M3    = IPR(397)
      NGRD2 = 2 * M1 * M2 * M3
C * ZERO FFT-ARRAY
      CALL GEN074 (FFT, 1, NGRD2, 0.0)
      FFT(1) = FS000
      NMAX   = (NREF - 1) * NP69
      DO I = 0, NMAX, NP69
C * LOAD H, K, L DATA
        AC           = VOD(I + 7)
        BC           = VOD(I + 8)
        IH           = MOD (NINT (VOD(I +  9)) + M1, M1)
        IK           = MOD (NINT (VOD(I + 10)) + M2, M2)
        IL           = MOD (NINT (VOD(I + 11)) + M3, M3)
        LOC          = 2 * ((IL * M2 + IK) * M1 + IH + 1)
        FFT(LOC - 1) = AC
        FFT(LOC)     = BC
C * LOAD -H, -K, -L DATA
        IH           = MOD (-IH + M1, M1)
        IK           = MOD (-IK + M2, M2)
        IL           = MOD (-IL + M3, M3)
        LOC          = 2 * ((IL * M2 + IK) * M1 + IH + 1)
        FFT(LOC - 1) =  AC
        FFT(LOC)     = -BC
      END DO
C * FFT-TRANSFORM DATA FROM RECIPROCAL TO DIRECT SPACE
      CALL GEN028 (FFT, IPR(395), 3, -1)
C * ANALYSE GRID DENSITY DISTRIBUTION (VALIDATION MODE)
      IF (IGBL(129) /= 0) CALL PLA362 (FFT)
C * PEAK-SEARCH (POSITIVE AND NEGATIVE)
      RHOMIN = PAR(269) * PAR(98)
      CALL PLA140 (FFT, R3D, NATO, RHOMIN, MODE, NPK,  1, IPR(48))
      CALL PLA140 (FFT, R3D, NATO, RHOMIN, MODE, NPK, -1, IPR(48))
      RETURN
99999 FORMAT (':: F000 Input for FFT:', F10.2)
      END SUBROUTINE PLA142
 
      SUBROUTINE PLA143 (MODE, DMX, NB, NE, IPOSNEG)
C * Difference Fourier Map and Peak list Analysis
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: MN
      INTEGER :: NS
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: ISW
      INTEGER :: IXL
      INTEGER :: NPK
      INTEGER :: NAT
      INTEGER :: NSYM
      INTEGER :: NPKM
      INTEGER :: NCCD
      INTEGER :: MODE
      INTEGER :: IHAT
      INTEGER :: IHYB
      INTEGER :: JMET
      INTEGER :: IENR
      INTEGER :: NPKV
      INTEGER :: NPKM1
      INTEGER :: IENR1
      INTEGER :: IENR2
      INTEGER :: JTEST
      INTEGER :: IPOSNEG
      REAL :: DMX
      REAL :: DIST
      REAL :: XDENS
      REAL :: ALERT
      CHARACTER(len=1)  :: TYP
      CHARACTER(len=2)  :: AREA
      CHARACTER(len=4)  :: TYPEX
      CHARACTER(len=6)  :: MAXMIN
      CHARACTER(len=10) :: ENHANCED
C * MODE = -1 - DiffMap Listing
C * MODE =  1 - SQUEEZE-LISTING
C * MODE =  2 - SOLV-LISTING
C * DMX = MAXIMUM COORDINATION SEARCH DISTANCE
      V2(1) = DMX / (PAR(101) * SIN (PAR(105) / RGBL(6)) * PAR(121))
      V2(2) = DMX / (PAR(102) * SIN (PAR(106) / RGBL(6)) * PAR(119))
      V2(3) = DMX / (PAR(103) * SIN (PAR(104) / RGBL(6)) * PAR(120))
C * NB = FIRST DIFFERENCE MAP PEAK ADDRESS IN XXO COORDINATE ARRAY
C * NE = LAST  DIFFERENCE MAP PEAK ADDRESS IN XXO COORDINATE ARRAY
C * IPOSNEG =  1 - POSITIVE DENSITY PEAK ANALYSIS
C *         = -1 - NEGATIVE DENSITY PEAK ANALYSIS
C * GET NUMBER OF SYMMETRY OPERATIONS
      NSYM = IPR(48)
C * GET NUMBER OF INDEPENDENT ATOMS
      NAT  = IPR(37)
      NPKV = 0
      NCCD = 0
C * FIND DISTANCES BETWEEN ATOMS - ROLLETT, COMP. METH. IN CRYST. 1965
      IF (NE >= NB) THEN
        ENHANCED = ' '
        IF (ABS (MODE) == 1) THEN
          IF (IPOSNEG > 0) THEN
            MAXMIN = 'Maxima'
            IF (MODE == -1) PAR(330) = XXO(NB, 4) / PAR(98)
            IF (MODE == 1) THEN
              ENHANCED = ' Enhanced '
              PAR(330) = 0.0
              REWIND (UNIT = LU2, IOSTAT = IOST)
              IF (IOST /= 0) CALL GEN148 (LU2, 1)
              WRITE (LU2, 99994, IOSTAT = IOST)
     1          JID(1:74), (PAR(100 + I), I = 1, 6)
C * OUTPUT EITHER EXPLICIT SYMMETRY OR SPACEGROUP NAME (IF KNOWN)
              IF (SPGRNM(1)(1:3) == '   ') THEN
                WRITE (LU2, 99990, IOSTAT = IOST)
     1            SPGRNM(1)(13:13), SPGRNM(1)(14:14)
                ISW = 2
                DO I = 2, IPR(255)
                  CALL SGSM (ISW, ICL, SGY, I, 0, IERR)
                  WRITE (LU2, 99989, IOSTAT = IOST) ICL(1:60)
                END DO
              ELSE
                IF (SPGRNM(1)(8:11) == '    ') THEN
                  I = ICHAR (' ')
                ELSE
                  I = ICHAR ('.')
                END IF
                WRITE (LU2, 99988, IOSTAT = IOST)
     1            SPGRNM(1)(1:7), CHAR (I), SPGRNM(1)(8:11)
              END IF
              WRITE (LU2, 99991, IOSTAT = IOST)
     1          NINT (PAR(150)), NINT (PAR(354))
            END IF
          ELSE
            MAXMIN   = 'Minima'
            PAR(329) = 0.0
            IF (MODE == -1) PAR(329) = XXO(NB, 4) / PAR(98)
          END IF
          IF (IGBL(129) /= 0) THEN
            WRITE (LU13, 99998, IOSTAT = IOST)
            WRITE (LU13, 99999, IOSTAT = IOST) MAXMIN, ENHANCED,
     1        MAX (0.10, PAR(269)) * IPOSNEG, DMX
          END IF
          IF (IGBL(63) > 0) THEN
            CALL PLA262 (0)
            WRITE (LU6, 99999, IOSTAT = IOST) MAXMIN, ENHANCED,
     1        MAX (0.10, PAR(269)) * IPOSNEG, DMX
            CALL PLA262 (5)
            WRITE (LU7, 99999, IOSTAT = IOST) MAXMIN, ENHANCED,
     1        MAX (0.10, PAR(269)) * IPOSNEG, DMX
          END IF
        ELSE
          WRITE (PRBUF, 99996, IOSTAT = IOST) DMX
          IF (IGBL(63) > 0) THEN
            WRITE (LU6, 99987, IOSTAT = IOST) PRBUF(1:80)
            CALL PLA262 (3)
            WRITE (LU7, 99987, IOSTAT = IOST) PRBUF(1:80)
          END IF
        END IF
C * LOOP OVER ADDITIONAL MAXIMA IN DIFFERENCE MAP PEAK LIST
        DO I = NB, NE
C * INIT NUMBER OF ATOMS WITHIN MAX COORDINATION DISTANCE DMX
          NPK = 0
C * LOOP OVER ATOMS
          DO J = 1, NAT
C * TEST FOR HYDROGEN (SKIPPED)
            CALL GEN048 (-1, IFG(1, J), 7, IHAT)
            IF (IHAT == 0) THEN
C * SYMMETRY LOOP
              DO N = 1, NSYM
                DO K = 1, 3
                  SGY(K)     = XXO(J, K)
                  SGY(K + 3) = 0.0
                END DO
                NS = N
                CALL SGSM (3, LINE, SGY, NS, LU6, IERR)
                K = 1
                GO TO 20
   10           SGY(6 + K) = SGY(6 + K) - 1.0
   20           IF ((XXO(I, K) - SGY(6 + K)) <= V2(K)) GO TO 10
                DO
                  SGY(6 + K) = SGY(6 + K) + 1.0
                  IF ((XXO(I, K) - SGY(6 + K)) < - V2(K)) THEN
                    K = K - 1
                    IF (K == 0) EXIT
                    CYCLE
                  END IF
                  IF (ABS (XXO(I, K) - SGY(6 + K)) <= V2(K)) THEN
                    K = K + 1
                    IF (K > 3) THEN
                      DO L = 1, 3
                        V3(L) = XXO(I, L) - SGY(6 + L)
                      END DO
                      CALL GEN002 (2, OR, V3, V4, DIST)
                      IF (DIST < DMX) THEN
                        IF (NPK == 0) THEN
                          JTEST = 0
                        ELSE
                          JTEST = IATC(NPK)
                        END IF
                        IF (J /= JTEST) THEN
                          NPK = NPK + 1
                          DATC(NPK) = DIST
                          IATC(NPK) = J
                        ELSE
                          IF (DIST < DATC(NPK)) DATC(NPK) = DIST
                        END IF
                      END IF
                      K = K - 1
                      CYCLE
                    END IF
                    GO TO 20
                  END IF
                END DO
              END DO
            END IF
          END DO
C * SORT SHORT CONTACTS AND LIST
          IENR1 = 0
          IENR2 = 0
          IF (MODE == 1) THEN
            TYPEX = 'void'
          ELSE
            TYPEX = '    '
          END IF
          CALL GEN036 (DATC, IATC, 1, NPK)
          NPKM1 = MIN (NPK, 9)
          IF (NPKM1 > 0) THEN
            DO J = 1, NPKM1
              IXL = - LABA(IATC(J))
              CALL PLA047 (IXL, NQ1, MN, IENR, 0, IGBL(55), 0,
     1          1 - IGBL(55))
              NAMS(J, 1) = NQ1
              IF (MODE == 1 .AND. IENR > 0) THEN
                IF (DATC(J) < ABS (VDWR(IENR)) + 1.2) TYPEX = '    '
              END IF
              IF (J == 1) IENR1 = IENR
              IF (J == 2) IENR2 = IENR
 
C * TEST FOR METAL CONTAINING STRUCTURE
              IF (IPR(155) == 1) THEN
                IF (DATC(J) < 1.2) THEN
C * TEST FOR METAL
                  CALL GEN048 (-1, IFG(1, IATC(J)), 19, JMET)
                  IF (JMET == 1) THEN
                    IF (DATC(J) < 0.2) THEN
                      IF (MODE == -1) THEN
                        XDENS = IPOSNEG * XXO(I, 4) / PAR(98)
                        IF (ABS(XDENS) > 0.75) THEN
C * CHECK FOR TWINNING AND NoSpherA2 AND _UNHARM_
                          IF (IPR(619) == 0 .AND. IPR(775) == 0 .AND.
     1                        IPR(756) == 0) THEN
                            IF (IPOSNEG > 0) THEN
C * ALERT _973 - LARGE POSITIVE DENSITY ON METAL
                              CALL PLA236 (973, 2,   XDENS, XDENS,
     1                          NQ1, ' ')
                            ELSE
C * ALERT _974 - LARGE NEGATIVE DENSITY ON METAL
                              CALL PLA236 (974, 2, - XDENS, XDENS,
     1                          NQ1, ' ')
                            END IF
                          END IF
                        END IF
                      END IF
                    END IF
                  END IF
                END IF
              END IF
            END DO
          END IF
          NPKM = MIN (NPK, 4)
C * SOLV-LISTING MODE
          IF (MODE == 2) THEN
            WRITE (AREA, 99992, IOSTAT = IOST) I + 1 - NB
C * DIFF MAP & SQUEEZE MAP MODE
          ELSE IF (ABS (MODE) == 1) THEN
            XDENS = IPOSNEG * XXO(I, 4) / PAR(98)
            IF (ABS (XDENS) < 0.1) THEN
              NE = I
              GO TO 30
            END IF
            NPKV = NPKV + 1
C * SQUEEZE MODE = 1
            IF (NPKM > 0) THEN
              IF (DATC(1) < 2.0) THEN
                IF (IPOSNEG > 0) THEN
                  PAR(330) = MAX (PAR(330), XDENS)
                ELSE
                  PAR(329) = MIN (PAR(329), XDENS)
                END IF
              END IF
            END IF
          END IF
          IF (IGBL(63) > 0) CALL PLA262 (1)
          IF (ABS (MODE) == 1) THEN
C * TEST FOR FCF CHECKING
            IF (IGBL(129) /= 0) THEN
              IF (ABS (XDENS) > 0.75) THEN
C * CHECK FOR TWINNING, SQUEEZE/SQF, anharm
                IF (IPR(619) == 0 .AND. IPR(756) == 0) THEN
C * TEST FOR METAL TYPE OF NEAREST ATOM
                  CALL GEN048 (-1, IFG(1, IATC(1)), 19, JMET)
                  IF (JMET == 0 .OR. DATC(1) >= 0.2) THEN
                    WRITE (NQ2, 99986, IOSTAT = IOST) DATC(1)
C * CHECK FOR NoSpherA2
                    IF (IPR(775) == 0 .AND. NPKM > 0) THEN
                      IF (IPOSNEG > 0) THEN
C * ALERT _971 - Large + calculated resdidual density outside metal location
                        IF (IPR(725) /= 9) THEN
                          CALL PLA236 (971, 2,   XDENS, XDENS,
     1                      NAMS(1, 1)(1:7)//' .', NQ2)
                        ELSE
                          CALL PLA236 (971, 2,  -999.0, XDENS,
     1                      NAMS(1, 1)(1:7)//' .', NQ2)
                        END IF
                      ELSE
C * ALERT _972 - Large - calculated residual density outside metal location
                        IF (IPR(725) /= 9) THEN
                          CALL PLA236 (972, 2, -XDENS, XDENS,
     1                      NAMS(1, 1)(1:7)//' .', NQ2)
                        ELSE
                          CALL PLA236 (972, 2, -999.0, XDENS,
     1                      NAMS(1, 1)(1:7)//' .', NQ2)
                        END IF
                      END IF
                    END IF
                  END IF
                END IF
              END IF
C * CHECK FOR TWINNING
              IF (IPR(619) == 0) THEN
                ALERT = 0.0
                TYPEX = '    '
                IF (ABS (XDENS) > 0.4) THEN
                  WRITE (NQ2, 99986, IOSTAT = IOST) DATC(1)
                  IF (ABS (DATC(1) - 0.75) < 0.35) THEN
                    IF (NPKM > 1) THEN
                      IF (DATC(2) > 1.75) THEN
C * CHECK FOR NITROGEN OR OXYGEN
                        IF (IENR1 >= 2 .AND. IENR1 <= 4) THEN
                          IF (IENR1 == 2) THEN
                            CALL GEN048 (-4, IFG(1, IATC(1)), 24, IHYB)
                            IF (IHYB == 0) ALERT = XDENS
                          ELSE
                            ALERT = XDENS
                          END IF
                        END IF
                      END IF
                    ELSE
                      IF (IENR1 == 3) ALERT = XDENS
                    ENDIF
C * CHECK FOR NoSpherA2
                    IF (IPR(775) == 0) THEN
                      IF (ALERT > 0.0) THEN
C * ALERT _975 - POSITIVE DENSITY NEAR C, N OR O
                        CALL PLA236 (975, 2,   ALERT, ALERT,
     1                    NAMS(1, 1)(1:7)//' .', NQ2)
                        TYPEX = '+H?'
                      ELSE IF (ALERT < 0.0) THEN
C * ALERT _976 - NEGATIVE DENSITY NEAR N OR O
                        CALL PLA236 (976, 2, - ALERT, ALERT,
     1                    NAMS(1, 1)(1:7)//' .', NQ2)
                        TYPEX = '-H?'
                      END IF
                    END IF
                  END IF
                END IF
              END IF
              IF (MODE == -1) THEN
                IF (IPOSNEG > 0 .AND. NPKM >= 2) THEN
                  IF (DATC(1) < 0.9 .AND. DATC(2) < 0.9) THEN
                    IF (IENR1 == 2 .AND. IENR2 == 2) THEN
                      TYPEX = 'C-C'
                      NCCD = NCCD + 1
                    ELSE IF ((IENR1 == 2 .AND. IENR2 == 4) .OR.
     1                       (IENR1 == 4 .AND. IENR2 == 2)) THEN
                      TYPEX = 'C-N'
                    ELSE IF ((IENR1 == 2 .AND. IENR2 == 3) .OR.
     1                       (IENR1 == 3 .AND. IENR2 == 2)) THEN
                      TYPEX = 'C-O'
                    END IF
                  END IF
                END IF
              END IF
              WRITE (LU13, 99997, IOSTAT = IOST)
     1          NPKV, (XXO(I, J), J = 1, 3), XDENS, TYPEX,
     2          (NAMS(J, 1)(1:5), DATC(J), J = 1, NPKM)
            END IF
            IF (IGBL(63) > 0) THEN
              WRITE (LU6, 99997, IOSTAT = IOST)
     1          NPKV, (XXO(I, J), J = 1, 3), XDENS, TYPEX,
     2          (NAMS(J, 1)(1:5), DATC(J), J = 1, NPKM)
              WRITE (LU7, 99997, IOSTAT = IOST)
     1          NPKV, (XXO(I, J), J = 1, 3), XDENS, TYPEX,
     2          (NAMS(J, 1)(1:5), DATC(J), J = 1, NPKM1)
            END IF
            IF (IPOSNEG > 0) THEN
              IF (MODE == 1 .AND. NPKV < 100) THEN
                IF (TYPEX == 'void') THEN
                  TYP = 'C'
                ELSE
                  TYP = 'Q'
                END IF
                WRITE (LU2, 99993, IOSTAT = IOST)  TYP, 100 + NPKV,
     1            (XXO(I, J), J = 1, 3), XXO(I, 4) / PAR(98)
              END IF
            END IF
          ELSE
            IF (IGBL(63) > 0) THEN
              IF (NPKM == 0) TYPEX = 'none'
              WRITE (LU6, 99995, IOSTAT = IOST)
     1          AREA, (XXO(I, J), J = 1, 3), TYPEX,
     2          (NAMS(J, 1)(1:5), DATC(J), J = 1, NPKM)
              WRITE (LU7, 99995, IOSTAT = IOST)
     1          AREA, (XXO(I, J), J = 1, 3), TYPEX,
     2          (NAMS(J, 1)(1:5), DATC(J), J = 1, NPKM1)
            END IF
          END IF
        END DO
   30   WRITE (LU6, 99998, IOSTAT = IOST)
        IF (IGBL(63) > 0) THEN
          CALL PLA262 (1)
          WRITE (LU7, 99998, IOSTAT = IOST)
        END IF
C * SKIP FOR IDEAL
        IF (BNDTP(1) == '  C-C' .AND. IPR(667) /= -1 .AND.
     1    IPR(757) == 0) THEN
C * ALERT _978 - REPORT DENSITY ON C-C BONDS (X-RAY ONLY)
          IF (MODE == -1 .AND. IPR(493) /= 7) THEN
            IF (IPOSNEG > 0 .AND. IPR(325) >= 0) THEN
              IF (NCCD > 0) THEN
                CALL PLA236 (978, 0, -999.0, FLOAT (NCCD), ' ', ' ')
              ELSE
                CALL PLA236 (978, 0, -999.0, FLOAT (NCCD), ' ', ' ')
              END IF
            END IF
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT (79('='), /, 'Unique Density ', A, ' in', A, 'Difference ',
     1 'Map (CutOff level =', F9.2, ' eA-3)', /, 79('='), /, 3X, '#',
     2 3X, 'x', 5X, 'y', 5X, 'z  (e/A^3)', 5X,
     3 'Shortest Contacts within', F4.1, ' Ang. (Excl. H)', /, 79('='))
99998 FORMAT (' ')
99997 FORMAT (I4, 3F6.3, F6.2, 1X, A, 1X, 9(A, F4.2, '; '))
99996 FORMAT (7X, 'x', 5X, 'y', 5X, 'z', 14X, 'Shortest ',
     1 'Contacts within', F4.1, ' Ang. (Excl. H)')
99995 FORMAT (1X, A, 1X, 3F6.3, 7X, A, 1X, 9(A, F4.2, '; '))
99994 FORMAT ('TITL ', A, /, 'CELL', 3F10.4, 3F10.2)
99993 FORMAT (A, I3, 3F6.3, ' ! ', F10.2, ' eA-3')
99992 FORMAT (I2)
99991 FORMAT ('# Solvent Accessible Volume =', I10, /,
     1        '# Electrons Found in S.A.V. =', I10, /,
     2        '# Note: Atoms in Void are Labelled as Cxxx and Qxxx ',
     3        'for all Others')
99990 FORMAT ('LATT ', A, 2X, A)
99989 FORMAT ('SYMM ', A)
99988 FORMAT ('SPGR ', 3A)
99987 FORMAT (/, A, /, 80('='))
99986 FORMAT (F6.2, 'Ang')
      END SUBROUTINE PLA143
 
      SUBROUTINE PLA144 (MODE, IAT)
C * CALCULATE AND DISPLAY RADIAL DISTRIBUTION FUNCTION
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: N
      INTEGER       :: NC
      INTEGER       :: JJ
      INTEGER       :: KL
      INTEGER       :: KN
      INTEGER       :: NI
      INTEGER       :: NK
      INTEGER       :: NM
      INTEGER       :: NIJ
      INTEGER       :: NCI
      INTEGER       :: NDB
      INTEGER       :: IAT
      INTEGER       :: IER
      INTEGER       :: IHA
      INTEGER       :: IPP
      INTEGER       :: KAT
      INTEGER       :: LBB
      INTEGER       :: LBC
      INTEGER       :: LBD
      INTEGER       :: MNI
      INTEGER       :: MNJ
      INTEGER       :: MNX
      INTEGER       :: MNY
      INTEGER       :: NDEC
      INTEGER       :: NORM
      INTEGER       :: KATP
      INTEGER       :: MKAT
      INTEGER       :: IDUB
      INTEGER       :: IDUM
      INTEGER       :: MODE
      INTEGER       :: IENI
      INTEGER       :: IENK
      INTEGER       :: ILMP
      INTEGER, SAVE :: NPNT
      INTEGER       :: MULTI
      INTEGER       :: ISDIJ
      INTEGER       :: IRESJ
      INTEGER       :: ILABX
      INTEGER       :: IDUM1
      INTEGER       :: IDUM3
      INTEGER       :: JNQNR
      INTEGER, SAVE :: NPNTM
      INTEGER, SAVE :: NBOND
      REAL :: A
      REAL :: XP
      REAL :: YP
      REAL :: XST
      REAL :: DIJ
      REAL :: SCF
      REAL :: AMX
      REAL :: SDIJ
      REAL :: FACT
      REAL :: PADD
      REAL :: XSTEP
      REAL :: SIGMA
C * MODE =  0 - INIT RADIAL DISTRIBUTION FUNCTION
C *      =  1 - COORDINATION LOOP OVER ATOMS
C *      = -1 - PLOT RADIAL DISTRIBUTION FUNCTION
C * GET NUMBER OF ATOMS IN COORDN ARRAYS (IATC AND DATC)
      IF (MODE > 0) THEN
        NC = IPR(79)
        IF (NC > 0) THEN
          CALL PLA047 (LABA(IAT), NQ3, MNX, IENI, 0, IGBL(55), 0,
     1                                             1 - IGBL(55))
          CALL GEN048 (-8, IFG(2, IAT), 1, IPP)
          MULTI = IPR(48) / IPPR(IPP + 1, 3)
C * GET LABEL ETC. IAT
          CALL PLA036 (IAT, 1, 1, IDUM1, MNI, IDUM3, IPR(71),
     1         IGBL(55))
C * DETERMINE NUMBER OF BONDED ATOMS
          NCI = 0
          NDB = 0
          DO J = 1, NC
            KAT  = IATC(J)
            MKAT = MOD (KAT, NP1)
C * ELIMINATE SOME REDUNDANCY
            IDUB = 0
            IF (J > 1) THEN
              DO K = 2, J
                IF (MKAT == MOD(IATC(K - 1), NP1)) THEN
                  IDUB = 2
                  NDB  = NDB + 1
                END IF
              END DO
            END IF
C * CHECK FOR H
            CALL GEN048 (-1, IFG(1, MKAT), 7, IHA)
C * MAKE NON-BOND TO SORT DOWNWARDS IN THE BOND-LIST
            PADD = (IDUB + IHA + 1) * PAR(23)
            IF (KAT <= NP1) THEN
C * CHECK WHETHER THIS CONNECTION IS IN THE BOND ARRAY
              CALL PLA040 (-1, IAT, JJ, KAT)
              IF (JJ > 0) THEN
                NCI  = NCI + 1
                PADD = 0
              END IF
            END IF
            DATC(J) = PADD + DATC(J)
          END DO
C * SORT COORDINATION BONDS IN IATC ACCORDING TO DISTANCE IN DATC
          CALL GEN036 (DATC, IATC, 1, NC)
          NC = NC - NDB
C * LOOP OVER CONTACTS
          DO J = 1, NC
            KAT     = IATC(J)
            IPR(20) = 0
            IF (KAT > NP1) THEN
              KAT     = KAT - NP1
              IATC(J) = KAT
              IPR(20) = 1
            END IF
            CALL GEN048 (-6, IFG(1, KAT), 9, IRESJ)
C * GET LABEL ETC. INFORMATION KAT
            CALL PLA036 (KAT, 1, 2, IDUM1, MNJ, IDUM3, IPR(71),
     1           IGBL(55))
C * FIRST GET SEQUENCE # IN PRIMARY LIST
            ILABX = - LABA(KAT)
            CALL PLA047 (ILABX, NQ4, MNY, IENK, IPR(71), IGBL(55),
     1        0, 1 - IGBL(55))
            CALL PLA046 (2, NQ4, IDUM, LBB, LBC, LBD, ILMP, JNQNR, KATP)
            CALL PLA047 (LABA(KAT), NQ3, MNY, IENK, IPR(71),
     1        IGBL(55), 0, 1 - IGBL(55))
            CALL PLA053 (IAT, KAT, 0, 0, DIJ, SDIJ, ISDIJ, NDEC, IER)
            NBOND     = NBOND + 1
            NI        = IATNR(IENI)
            NK        = IATNR(IENK)
            NIJ       = NINT (DIJ * 100.0) + NPNT + 1
            DATC(NIJ) = DATC(NIJ) + FLOAT (NI * NK) / FLOAT (MULTI)
          END DO
        END IF
C * INIT RADIAL DISTRIBUTION FUNCTION CALCULATION
      ELSE IF (MODE == 0) THEN
        NBOND = 0
        NPNT  = NINT (PAR(262) * 100.0) + 1
        NPNTM = 2 * NPNT
        CALL GEN074 (DATC, NPNT + 1, NPNTM, 0.0)
C * PLOT RADIAL DISTRIBUTION FUNCTION
      ELSE IF (MODE == -1) THEN
        DO
C * INDIVIDUAL PEAK SIGMA
          SIGMA = PAR(451)
C * NORMALIZE RDF (0/1)
          NORM  = IPR(581)
C * ZERO RDF-Y ARRAY
          CALL GEN074 (DATC, 1, NPNT, 0.0)
          DO I = 2, NPNT
            A = DATC(NPNT + I)
            IF (A > 0.0) THEN
C * NORMALIZE
              IF (NORM /= 0) A = A / (I - 1)
              DATC(I) = DATC(I) + A
              DO J = 1, 199
                FACT = A * EXP (- (J / SIGMA) ** 2)
                IF (FACT < 0.1E-30) EXIT
                IF (I + J <= NPNT) DATC(I + J) = DATC(I + J) + FACT
                IF (I - J > 0)     DATC(I - J) = DATC(I - J) + FACT
              END DO
            END IF
          END DO
          AMX = 0.0
          DO I = 1, NPNT
            AMX = MAX (AMX, DATC(I))
          END DO
          DO
            IGBL(6)   = 28
            BCD(1:30) = 'Simulated Radial Distribution'//CHAR (0)
            CALL GGIP (HORS, VERT, 0.0, 1)
            CALL PLA439 (0.0,  BCD, 29, 1.0, 4, 8, 0.6, VERT - 1.6)
            CALL PLA439 (0.0,  BCD, 29, 1.0, 2, 8, 0.5, VERT - 1.7)
            CALL PLA110 (HORS, VERT, -1)
            VRT = VERT - 3.0
            CALL PLA283 (0, 1.0, N, CFORM)
            WRITE (LINE, 99989, IOSTAT = IOST) CFORM(N:NP52)
            CALL PLA439 (0.0, LINE, 60, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99999,IOSTAT = IOST) SPGRNM(1)(1:7)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 17, 0.35, 1, 1, 1.5, VRT)
C * DISPLAY DIRECT CELL
            WRITE (LINE, 99998, IOSTAT = IOST) PAR(101)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99997, IOSTAT = IOST) PAR(102)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99996, IOSTAT = IOST) PAR(103)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99995, IOSTAT = IOST) PAR(104)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99994, IOSTAT = IOST) PAR(105)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99993, IOSTAT = IOST) PAR(106)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            WRITE (LINE, 99990, IOSTAT = IOST) PAR(98)
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.5, VRT)
            XSTEP = (HORS - 2.0) / (NPNT - 1)
            SCF   = (VERT - 4.0) / AMX
            CALL GGIP (1.0, 2.0, 0.0, 3)
            OPEN (UNIT = LU64, FILE = NAMEFIL(1:KNMFIL)//'.rdf',
     1        STATUS = 'UNKNOWN')
            DO I = 1, NPNT
              XP = 1.0 + (I - 1) * XSTEP
              YP = 2.0 + SCF * DATC(I)
              CALL GGIP (XP, YP, 0.0, 2)
              WRITE (LU64, 99988) FLOAT (I - 1) / 100.0, SCF * DATC(I)
            END DO
            CLOSE (LU64)
            WRITE (LU6, 99987) NAMEFIL(1:KNMFIL)//'.rdf'
            CALL GGIP (0.0, 0.0, 0.0, 3)
C * PLOT HORIZONTAL SCALE
            XP  = 1.0
            N   = 0
            NM  = NPNT / 50
            XST = XSTEP * 50
            DO WHILE (N <= NM)
              CALL GGIP (XP, 1.0, 0.0, 3)
              CALL GGIP (XP, 1.4, 0.0, 2)
              IF (N < 20) THEN
                WRITE (NQ1, 99992, IOSTAT = IOST) N * 0.5
              ELSE
                WRITE (NQ1, 99991, IOSTAT = IOST) N * 0.5
              END IF
              CALL PLA439 (0.0, NQ1, 4, 0.2, 2, 2, XP + 0.1, 1.2)
              XP = XP + XST
              N  = N  + 1
            END DO
            CALL PLA439 (0.0, 'Angstrom', 8, 0.3, 2,2, HORS - 2.4, 0.2)
C * WHAT NEXT ?
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
              CALL GEN072 (IGGT, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7,
     1          NP17)
            IF (IFL(1)(1:4) == 'EXIT') THEN
              RETURN
            ELSE IF (IFL(1)(1:4) == 'CALC') THEN
              EXIT
            ELSE IF (IFL(1)(1:3) == 'END') THEN
              IGGT = ' '
              IGBL(6) = 10
C * RESET
              CALL PLA286 (0)
              RETURN
            ELSE IF (LRET == 2) THEN
              EXIT
            END IF
          END DO
          IF (LRET /= 2) EXIT
        END DO
      END IF
      RETURN
99999 FORMAT ('SpGroup ', A)
99998 FORMAT ('a    ', F8.2)
99997 FORMAT ('b    ', F8.2)
99996 FORMAT ('c    ', F8.2)
99995 FORMAT ('alpha', F8.2)
99994 FORMAT ('beta ', F8.2)
99993 FORMAT ('gamma', F8.2)
99992 FORMAT (F3.1)
99991 FORMAT (F4.1)
99990 FORMAT ('Volume', F7.1)
99989 FORMAT ('Formula ', A)
99988 FORMAT (2F10.3)
99987 FORMAT (/, ':: RDF on: ', A, /)
      END SUBROUTINE PLA144
 
      MODULE asym
      SAVE NONE
      INTEGER, PARAMETER :: NP44 = 512
      INTEGER, PARAMETER :: NP63 = 1000
      INTEGER, PARAMETER :: NP68 = 48
      INTEGER, PARAMETER :: NP79 = 24
      INTEGER, PARAMETER :: NP80 = 30
      INTEGER, PARAMETER :: NP82 = 6
      INTEGER, PARAMETER :: NP83 = 24
      INTEGER, PARAMETER :: NP84 = 24
      INTEGER, PARAMETER :: NP89 = 24
      INTEGER :: IPL
      INTEGER :: NHEAD
      INTEGER :: NMISS
      INTEGER, DIMENSION(252)     :: ID
      INTEGER, DIMENSION(NP63)    :: IT
      INTEGER, DIMENSION(NP68, 2) :: IRC
      INTEGER, DIMENSION(NP68, 2) :: IRD
      INTEGER, DIMENSION(3)       :: IKS
      INTEGER, DIMENSION(6)       :: IHM
      INTEGER, DIMENSION(2, 2)    :: IRAB
      INTEGER, DIMENSION(3)       :: IHKL
      INTEGER, DIMENSION(NP68)    :: MULT
      INTEGER, DIMENSION(20, 2)   :: ICNT
      INTEGER, DIMENSION(3)       :: IHKLE
      INTEGER, DIMENSION(3, NP79) :: NTHMN
      INTEGER, DIMENSION(3, NP80) :: NTHMX
      INTEGER, DIMENSION(3, NP82) :: NBSTP
      INTEGER, DIMENSION(3, NP83) :: NOUTX
      INTEGER, DIMENSION(3, NP84) :: NSTRM
      INTEGER, DIMENSION(3, NP89) :: IOLTC
      REAL :: ATHM
      REAL :: ATHMN
      REAL :: CALIM
      REAL, DIMENSION(2, 3)    :: SM
      REAL, DIMENSION(NP68, 2) :: RA
      REAL, DIMENSION(NP68, 2) :: RB
      REAL, DIMENSION(12)      :: FULL
      REAL, DIMENSION(20, 12)  :: STAT
      REAL, DIMENSION(NP68)    :: PERCENT
      CHARACTER(len=NP44) :: CID
      CHARACTER(len=60), DIMENSION(104) :: AR
      CHARACTER(len=1),  DIMENSION(3)   :: ZONE = (/'H', 'K', 'L'/)
      END MODULE asym
 
      SUBROUTINE PLA145 (MODE)
C *********************************************************************
C * ASYM - PROGRAM FOR THE DISPLAY AND EXTRACTION OF A UNIQUE SET OF  *
C *        REFLECTIONS OUT OF A REDUNDANT SET + AB-INITIO GENERATION. *
C *        A.L.SPEK, Utrecht University, The Netherlands (1975-2026)  *
C *********************************************************************
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE mentry
      USE cggt
      USE spgrdata
      USE reflex
      USE fab
      USE asym
      USE sgxyz
      USE cif
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: I6
      INTEGER :: N2
      INTEGER :: JM
      INTEGER :: IS
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IA
      INTEGER :: JP
      INTEGER :: MH
      INTEGER :: MK
      INTEGER :: ML
      INTEGER :: MM
      INTEGER :: NB
      INTEGER :: NN
      INTEGER :: N01
      INTEGER :: N02
      INTEGER :: N11
      INTEGER :: N12
      INTEGER :: IJK
      INTEGER :: IHK
      INTEGER :: IHT = 0
      INTEGER :: IKT = 0
      INTEGER :: ILT = 0
      INTEGER :: IND
      INTEGER :: NID
      INTEGER :: NPZ
      INTEGER :: INTM
      INTEGER :: NLEV
      INTEGER :: MAXI
      INTEGER :: MAXM
      INTEGER :: JUNK
      INTEGER :: JMAX
      INTEGER :: ITEL
      INTEGER :: IRM1
      INTEGER :: IRM2
      INTEGER :: IOB1
      INTEGER :: IOB2
      INTEGER :: IOB3
      INTEGER :: IOB4
      INTEGER :: IMAX
      INTEGER :: IJKM
      INTEGER :: IHKA
      INTEGER :: IHKB
      INTEGER :: IDUM
      INTEGER :: MODE
      INTEGER :: IBVT
      INTEGER :: NORI
      INTEGER :: NTEL
      INTEGER :: NOPT
      INTEGER :: NSMAL
      INTEGER :: NOUTL
      INTEGER :: NFUL1
      INTEGER :: NFULL
      INTEGER :: IVGNR
      INTEGER :: IHKL2
      INTEGER :: IASIG
      INTEGER :: LUP17
      INTEGER :: LUP18
      INTEGER :: IGETAL
      INTEGER :: IOBUF1
      INTEGER :: LOGMAX
      INTEGER :: COUNTY
      INTEGER :: COUNTZ
      INTEGER :: IGBL6SAVE = 0
      REAL :: R
      REAL :: S
      REAL :: TH
      REAL :: SA
      REAL :: R1
      REAL :: R2
      REAL :: AI
      REAL :: RS
      REAL :: XI
      REAL :: CR1
      REAL :: CR2
      REAL :: CR3
      REAL :: WR2
      REAL :: GOF
      REAL :: STH
      REAL :: STL
      REAL :: THM
      REAL :: TEL
      REAL :: STHK
      REAL :: REFA
      REAL :: REFB
      REAL :: CRIT
      REAL :: ACAL
      REAL :: BCAL
      REAL :: CALI
      REAL :: DIFF
      REAL :: DIFH
      REAL :: DIFK
      REAL :: DIFL
      REAL :: DOSW
      REAL :: RSIG
      REAL :: SIGI
      REAL :: SIGK
      REAL :: SIGS
      REAL :: YDUM
      REAL :: YUNK
      REAL :: SCAL
      REAL :: XSIGM
      REAL :: XIMAX
      REAL :: UCINT
      REAL :: STLMX
      REAL :: PSCFA
      REAL :: PSCFB
      REAL :: DOSAV
      REAL :: DOSAW
      REAL :: ACALA
      REAL :: BCALA
      REAL :: ACALS
      REAL :: BCALS
      REAL :: CRITO
      REAL :: SIGIW
      REAL :: SMCAL
      REAL :: SMEXB
      REAL :: SMEXT
      REAL :: SMOBS
      REAL :: SNTHA
      REAL :: WEIGHT
      REAL :: SINTHL
      REAL :: SCFHKL
      REAL :: DOVERS
      REAL :: FACTOR
      REAL :: COUNTB
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN013
      REAL :: GEN050
      REAL :: GEN095
      REAL :: AVERAGE
      REAL :: SIGIMAX
      CHARACTER(len=80) :: AA
      CHARACTER(len=1)  :: IUU
      CHARACTER(len=60) :: XAR
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=1)  :: QMRK
      CHARACTER(len=80) :: ICRD
      CHARACTER(len=38) :: STAR
      CHARACTER(len=39) :: BLANKO
      CHARACTER(len=3)  :: FILETYPE
      INTEGER, ALLOCATABLE, DIMENSION(:) :: IAR
C * MODE     =  0 - DEFAULT ASYM
C * MODE     =  1 - EXPECT NUMBER OF REFLECTIONS
C * MODE     =  2 - VALIDATION MODE (+ AVF)
C * MODE     =  3 - VALIDATION MODE
C * IPR(408) = -1 - EXPAND (IOBS)
C *          =  0 - NORMAL-MODE
C *          =  1 - GENERATE
C *          =  2 - EXPECT
C * IPR(392) =  0 - LISTING OF SYMMETRY ABSENT REFLECTIONS ONLY
C *          =  1 - LISTING OF REFLECTIONS ONLY
C *          =  2 - LISTING OF RECIPROCAL LATTICE ONLY
C *          =  3 - FULL LISTING OPTION
      IF (IGBL(74) > 0) THEN
        WRITE (LU6, '(''MODE, IPR(408), IPR(392), IPR(511), IPR(220)'',
     1    5I10)') MODE, IPR(408), IPR(392), IPR(511), IPR(220)
        IF (IPR(220) > 0) WRITE (LU6,'(''IFL(1)='', 5A)')
     1    (IFL(I), I = 1, IPR(220))
      END IF
 
      ALLOCATE (IAR(NVDI))
      PAGET    = 'ASYM'
      LUP17    = LU17
      LUP18    = LU18
      IRM1     = 0
      IRM2     = 0
      IPR(512) = 0
C * SET DEFAULT RESOLUTION (0/1)
      IPR(387) = 1
C * SET AXES (0/1)
      IPR(388) = 1
C * SET SUMMARY (0/1)
      IPR(406) = 1
C * SPECIAL OPTION GENERATION MODES
      IPR(221) = 0
C * SET EXOR/SS
      PAR(284) = 2.0
      NOUTL    = 0
      NSMAL    = 0
      SMOBS    = 0.0
      SMCAL    = 0.0
      WRITE (BLANKO, 99920)
      WRITE (STAR  , 99919)
C * CHECK FOR PROPER UNITCELL
      IF (PAR(101) < 1.001) THEN
C * CHECK FOR VALIDATION MODE
        IF (IGBL(22) == -1) THEN
          WRITE (LU13, 99954, IOSTAT = IOST)
        ELSE
          WRITE (LU6,  99954, IOSTAT = IOST)
        END IF
        RETURN
      END IF
C * CHECK FOR RADIATION TYPE
      CALL PLA293 (PAR(17))
C * CREATE FCF WHEN ABSENT (GIVEN SHELXL-20xy CIF INPUT BASED)
C * OR COPY FROM EMBEDDED FCF
      CALL PLA346
C * OPEN .hks file for ASYM reflection output
      OPEN (UNIT = LUP18, FILE = NAMEFIL(1:KNMFIL) //'.hks',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
C * DEFAULT ASYM RUN
      IF (MODE == 0) THEN
C * REPORT DEFAULT MODE
        WRITE (LU6, 99917)
        REWIND (UNIT = LUP17, IOSTAT = IOST)
        REWIND (UNIT = LUP18, IOSTAT = IOST)
C * EXPECT NUMBER OF REFLECTIONS
      ELSE IF (MODE == 1) THEN
        WRITE (LU6, 99916)
        IFL(2)   = 'EXPECT'
        IPR(220) = 2
C * VALIDATION MODE (+ AVF VALID)
      ELSE IF (MODE == 2) THEN
        WRITE (LU6, 99915)
C * SET ANOMALOUS DISPERSION VALUES
        IF (IPR(704) == 0) CALL PLA340
        IFL(2)   = 'AVF'
        IFL(3)   = 'VALID'
        IPR(220) = 3
C * ZERO # OBSERVED SPGR ABSENT REFLECTIONS
        IPR(754) = 0
C * VALIDATION MODE
      ELSE IF (MODE == 3) THEN
        WRITE (LU6, 99914)
        IFL(2)   = 'VALID'
        IPR(220) = 2
      END IF
C * LOOP OVER COMMAND OPTIONS
      N = 0
      IF (IPR(220) > 1) THEN
        DO I = 2, IPR(220)
          SELECT CASE (IFL(I)(1:6))
C * ASYM EXPECT MODE (BASED ON REPORTED THETA-MAX) [MODE = 1]
            CASE ('EXPECT')
              PAGET    = 'EXPECT'
              PAR(165) = PAR(168)
              IPR(408) = 2
              IPR(392) = 0
              IPR(393) = 0
              WRITE (LU6, 99940, IOSTAT = IOST)
C * ASYM VALIDATION MODE [MODE = 2 & 3]
            CASE ('VALID ')
C * ALERT _998 - LIST 3 (UNSUITABLE)
              IF (IGBL(9) == 21) THEN
                CALL PLA236 (998, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _999 - LIST 6 (UNSUITABLE)
              ELSE IF (IGBL(9) == 23) THEN
                CALL PLA236 (999, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _997 - NO-SHELXL CIF/FCF COMBINATION
              ELSE IF (IPR(725) > 0 .AND. IPR(725) < 3) THEN
                IF (IGBL(9) /= 1 .AND. IGBL(9) /= 25) THEN
                  CALL PLA236 (997, 0, 1.0, 1.0, ' ', ' ')
                END IF
              END IF
              INQUIRE (FILE = FNLU16(1:KNM16), EXIST = EXST)
              IF (.NOT. EXST) THEN
                WRITE (6, 99963, IOSTAT = IOST)
     1          FNLU16(1:KNM16-3)//'hkl or fcf'
                WRITE (LU13, 99963, IOSTAT = IOST)
     1          FNLU16(1:KNM16-3)//'hkl or fcf'
                GO TO 90
              END IF
              PAR(165)  = PAR(168)
              IPR(408)  = 0
              IPR(392)  = 3
              IGBL(22)  = -1
              IGBL(129) = 1
C * OPEN FCF-CHECK OUTPUT
              INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.ckf',
     1                 OPENED = OPEND)
              IF (.NOT. OPEND) THEN
                OPEN (UNIT = LU13, FILE = NAMEFIL(1:KNMFIL) //'.ckf',
     1                STATUS = 'UNKNOWN')
              END IF
C * ASYM HKL EXPAND MODE
            CASE ('EXPAND')
              IPR(408) = -1
C * ASYM GENERATE MODE
            CASE ('GENERA')
C * CHECK FOR ATOMS
              IF (IPR(37) > 0) THEN
                IPR(408) = 1
                IPR(700) = NINT (FN(1))
                CLOSE (UNIT = LU17, STATUS = 'DELETE', IOSTAT = IOST)
                OPEN (UNIT = LU17,
     1            FILE = NAMEFIL(1:KNMFIL)//'_gener.hkl',
     2            STATUS = 'UNKNOWN', IOSTAT = IOST)
              ELSE
                IPR(2) = 42
                RETURN
              END IF
C * ASYM AVERAGE FRIEDEL PAIRS
            CASE ('AVF   ')
              IPR(393) = 1
C * ASYM VIEW MODE
            CASE ('VIEW  ')
              IGBL(22) = 1
C * ASYM LEVEL h RECIPROCAL LATTICE DISPLAY
            CASE ('ZONEH ')
              IPR(394) = 1
C * ASYM LEVEL k RECIPROCAL LATTICE DISPLAY
            CASE ('ZONEK ')
              IPR(394) = 2
C * ASYM LEVEL l RECIPROCAL LATTICE DISPLAY
            CASE ('ZONEL ')
              IPR(394) = 3
C * REFLECTION LIST OPTION
            CASE ('LIST  ')
              N        = N + 1
              IPR(392) = NINT (FN(N))
C * THETA MAX OF RECIPROCAL LATTICE DISPLAY
            CASE ('THM   ')
              N        = N + 1
              PAR(165) = FN(N)
          END SELECT
        END DO
      END IF
C * CHECK FOR REGULAR REFLECTION DATA INPUT OR REFLECTION DATA TO BE GENERATED
C * REFLECTION GENERATE MODE
      IF (IPR(408) == 1) THEN
        PAR(165) = ASIN (MIN (1.0, PAR(287) * PAR(17))) * RGBL(6)
C * EXPAND COORDINATE DATA TO TRICLINIC
        CALL PLA287 (1, 1, 0)
C * INIT RANDOM NUMBER GENERATOR
        IDUM = -1
        YUNK = GEN013 (IDUM)
C * REPORT NUMBER OF EXPECTED REFLECTIONS
      ELSE IF (IPR(408) == 2) THEN
        IF (IGBL(63) > 0) THEN
          CALL PLA262 (0)
          WRITE (LU7, 99978, IOSTAT = IOST)
          CALL PLA262 (2)
        END IF
C * REGULAR REFLECTION MODE
      ELSE
        IF (IPR(39) == 0 .OR. MODE == 0) THEN
C * CELL PARAMETERS
          CALL PLA100
C * LATTICE/SYMMETRY HEADER
          CALL PLA042 (1)
        END IF
      END IF
      CALL PLA262 (0)
C * CHECK FOR VALIDATION MODE
      IF (IGBL(22) == -1) THEN
        IF (IPR(37) /= 0) CALL PLA287 (1, 0, 0)
        IGBL(63) = 0
        IPR(676) = 1
C * WRITE .CKF LISTING HEADER
        WRITE (LU13, 99971, IOSTAT = IOST) IGBL(4), MODE, JID(1:16),
     1    HTTPSERVER(1:IGBL(135)),
     2    NAMEFIL(1:KNMFIL)//'.'//EXTENS(1:KXT), FNLU16(1:KNM16),
     3    RDTYP(IGBL(9)), SPGRNM(1)(1:7), PAR(17),
     4    (PAR(100 + M), M = 1, 6)
C * SHELXL WEIGHT PARAMETERS
        IF (PAR(493) >= 0.0) THEN
          IF (IABS(IPR(632)) == 1) THEN
            WRITE (LU13, 99952, IOSTAT = IOST) (PAR(I), I = 493, 498)
C * JANA WEIGHT PARAMETER
          ELSE IF (IPR(632) == 2) THEN
            WRITE (LU13, 99936, IOSTAT = IOST) PAR(493)
C * CRYSTALS WEIGHT PARAMETERS
          ELSE IF (IABS(IPR(632)) == 3) THEN
            WRITE (LU13, 99952, IOSTAT = IOST) PAR(493), PAR(494)
          ENDIF
        ENDIF
        IF (PAR(229) > -999999.0)
     1    WRITE (LU13, 99951, IOSTAT = IOST) PAR(229)
      END IF
C * CHECK FOR VALIDATION (= -1) OR VIEW (= 1) MODE
      IF (IGBL(22) /= 0) THEN
        LUP17 = 0
        LUP18 = 0
        NMISS = 0
      END IF
      NLEV = -2
      NID  =  0
      GO TO 40
C * INPUT EVENT LOOP
   10 CALL PLA012 (0, 1)
      SELECT CASE (LRET)
        CASE (2)
          GO TO 90
        CASE (3)
          NLEV = -2
          NID  =  0
          GO TO 40
        CASE (4)
          IF (NLEV == -2) GO TO 40
      END SELECT
C * TEST FOR FULL LISTING OPTION (=3)
   20 IF (IPR(392) /= 3) GO TO 90
C * LEVEL UP/DOWN
      NLEV = MAX (0, NLEV + IPR(389))
C * LOOP OVER LEVELS
      IF (NLEV > -1) THEN
        NHEAD = 0
        DO
          CALL PLA147 (NLEV)
          IF (IGBL(22) < 0) THEN
            IF (IKS(IND3) > NLEV) THEN
              GO TO 60
            ELSE
              NLEV = NLEV + 1
              CYCLE
            END IF
          ELSE
            GO TO 10
          END IF
        END DO
      END IF
C * ZONE(X) - X = H,K,L
   40 IND3 = IPR(394)
      IF (IPR(394) == 2) THEN
        IND1 = 1
        IND2 = 3
      ELSE IF (IPR(394) == 1) THEN
        IND1 = 2
        IND2 = 3
      ELSE
        IND1 = 1
        IND2 = 2
      END IF
      IPR(362) = 0
      CALL GEN097 (IHM,   1,   6, 0)
      CALL GEN097 (IPR, 370, 386, 0)
      CALL GEN097 (ICNT,  1,  40, 0)
      CALL GEN097 (IT,    1, 200, 0)
      THM   = PAR(165)
      STHKM = (SIN (THM / RGBL(6)) / PAR(17))**2
 
C * READ REFLECTIONS
      ITEL  = 0
      NLEV  = -1
      INTM  = 0
      XSIGM = 0.0
      ATHM  = 0.0
      ATHMN = 999.0
      DOSAV = 0.0
      DOSAW = 0.0
      CALIM = 0.0
      SMEXT = 0.0
      SMEXB = 0.0
      NSYMH = IPR(255)
      ICNTR = IPR(257)
      IBVT  = IPR(241)
C * CHECK FOR CENTRO
      IF (ICNTR == 1 .AND. IPR(275) == 2) NSYMH = NSYMH / 2
      IMAX   = NSYMH * 6 + 3
      FACTOR = 10.0 / (0.65**3 + 0.0001)
C * REFLECTION INTENSITY SCALING (LOOP)
C * GENERATE MODE RUN
      IF (IPR(408) == 1) THEN
        PSCFA = 100.0
        PSCFB =  10.0
C * EXPECT MODE RUN
      ELSE IF (IPR(408) == 2) THEN
        PSCFA = 1.0
        PSCFB = 1.0
C * NORMAL & EXPAND MODE RUNS
      ELSE
        XIMAX   = 0.0
        SIGIMAX = 0.0
        LOGMAX  = 0.0
        IEND    = -1
        DO WHILE (IEND <= 0)
          CALL PLA132 (IH, IK, IL, XI, SIGI, SIGIW, CALI, UCINT,
     1      ACALS, BCALS)
          IF (IEND /= 1) THEN
            IF (IEND == 2) THEN
              RETURN
            ELSE
              IF (IABS (IH) + IABS (IK) + IABS (IL) > 0) THEN
C * USE IOBS (OR ICALC FOR SIMULATED POWDER DIAGRAM)
                IF (IPR(511) == 2) XI = CALI
                XIMAX   = MAX (XIMAX, XI)
                SIGIMAX = MAX (SIGIMAX, SIGI)
              END IF
            END IF
          END IF
        END DO
        IF (SIGIMAX /= 0.0) THEN
          LOGMAX = INT (MAX (LOG10 (XIMAX), LOG10 (SIGIMAX)))
        END IF
        IPR(746) = LOGMAX
        PSCFA    = 10.0**(6 - LOGMAX)
        PSCFB    = PSCFA
      END IF
C * REWIND
      CALL GEN108 (LU8, 0)
      NFUL1 = 0
      DO I = 1, 20
        DO J = 1, 12
          STAT(I, J) = 0.0
        END DO
      END DO
      IPR(371) = 0
C * INIT Nmeas counts
      IPR(637) = 0
      IPR(638) = 0
      NMISS    = 0
      NTEL     = 0
      PAR(373) = 0.0
      PAR(374) = 0.0
C * INIT INTENSITY DISTRIBUTION STATISTICS
      CALL PLA169 (0, 0.0, 0.0, 0.0, 0)
      CALL GEN097 (MULT, 1, NP68, 0)
C * REFLECTION FILE READ LOOP
      M    = 0
      IEND = -1
      COUNTY = 0
      COUNTZ = 0
      DO WHILE (IEND <= 0)
        CALL PLA132 (IH, IK, IL, XI, SIGI, SIGIW, CALI, UCINT,
     1               ACALS, BCALS)
C * USE IOBS (OR ICALC FOR SIMULATED POWDER DIAGRAM)
        IF (IPR(511) == 2) XI = CALI
        IF (IEND == 2) RETURN
          COUNTY = COUNTY + 1
        IF (IEND /= 1 .AND. (IABS(IH) + IABS(IK) + IABS(IL)) > 0) THEN
          COUNTZ = COUNTZ + 1
C * APPLY TRANSFORMATION (IF ANY) AND ELIMINATE REFL WITH NON-INTEGRAL INDICES
C * TEST FOR NON-GENERATE MODE
          IHT = IH
          IKT = IK
          ILT = IL
          IF (IPR(408) /= 1) THEN
C * CHECK FOR NON-UNIT TRANSFORMATION MATRIX (VALUE 0 OR 1)
              IF (GEN050 (TRMX, IH, IK, IL, IHT, IKT, ILT) < 0.0)
     1          THEN
                IPR(371) = IPR(371) + 1
                IF (XI > 5.0 * SIGI) THEN
                  ITEL = ITEL + 1
C * TEST FOR NON-VALIDATION MODE (= -1)
                  IF (IGBL(22) /= -1) THEN
                    IF (ITEL == 1) WRITE (LU7, 99992, IOSTAT = IOST)
                    WRITE (LU7, 99991, IOSTAT = IOST) IH, IK, IL, XI,
     1                SIGI
                  END IF
                END IF
                CYCLE
              END IF
          END IF
C * ELIMINATE BRAVAIS LATTICE ABSENCES
          IF (IBVT > 1) THEN
            SGX(1)  = IHT
            SGX(2)  = IKT
            SGX(3)  = ILT
            SGX(12) = -1.0
            CALL SGSM (27, LINE, SGX, 0, 0, IERR)
            IF (NINT (SGX(12)) > 0) THEN
              IF (IPR(408) <= 0) THEN
                IPR(370) = IPR(370) + 1
                IF (XI > 5.0 * SIGI) THEN
                  ITEL = ITEL + 1
                  IF (IGBL(22) /= -1) THEN
                    IF (ITEL == 1) WRITE (LU7, 99992, IOSTAT = IOST)
                    WRITE (LU7, 99994, IOSTAT = IOST)
     1                IHT, IKT, ILT, XI, SIGI
                  END IF
                END IF
              END IF
              CYCLE
            END IF
          END IF
C * DETERMINE THETA-MAX AND SKIP REFLECTIONS ON THETA
          STHK = GEN095 (PAR(191), IHT, IKT, ILT)
          CALL PLA169 (1, XI * 100.0,
     1                 SIGI * 100.0, SQRT (STHK), 0)
          IF (STHK > (STHKM + 0.00001)) THEN
            IF (IPR(408) <= 0) IPR(372) = IPR(372) + 1
            IF (IPR(408) == 2 .OR. IGBL(129) <= 0) CYCLE
            IPR(379) = IPR(379) + 1
          END IF
          IF (IPR(648) /= 2) THEN
            TH = ASIN (SQRT (STHK) * PAR(17)) * RGBL(6)
            IF (STHK < ATHMN + 0.00001) THEN
              ATHMN = STHK
              PAR(445) = ASIN (MIN (1.0, SQRT (ATHMN) * PAR(17)))
     1                 * RGBL(6)
            END IF
          END IF
          IF (STHK > ATHM) THEN
            ATHM = STHK
          END IF
C * COUNT NUMBER OF REFLECTIONS WITH NEGATIVE INTENSITIES
          IF (MODE > 1) THEN
            IF (XI < 0.0) THEN
              IPR(627) = IPR(627) + 1
              IF (XI < - 2.0 * SIGI) THEN
                  IPR(628) = IPR(628) + 1
              END IF
            END IF
C * COUNT NUMBER OF REFLECTIONS WITH SIGMA = 0.0
            IF (IGBL(9) /= 21 .AND. IGBL(9) /= 23 .AND.
     1          IGBL(9) /= 5) THEN
              IF (SIGI == 0.0) IPR(631) = IPR(631) + 1
            END IF
          END IF
          IPR(373) = IPR(373) + 1
C * TEST FOR FCF-VALIDATION (= -1)
          IF (IGBL(22) < 0) THEN
            CALIM = MAX (CALIM, CALI)
            SIGS  = SIGI**2
C * INCLUDE L.S. WEIGHT PARAMETERS IN SIGMAI (SHELXL & JANA)
            SIGK  = SIGIW**2
C * PSEUDO EXTINCTION PARAMETER
            IF (CALI > 0 .AND. XI > 0) THEN
              IF (SIGI > 0.0) THEN
                WEIGHT = 1.0
                SMEXT  = SMEXT + WEIGHT * (LOG (XI / CALI)) * CALI
                SMEXB  = SMEXB + WEIGHT * CALI**2
              END IF
            END IF
C * DELTA-I OUTLIERS
            IF (CALI > 0.0) THEN
              IF (CALI < 2 * SIGI) THEN
                SMOBS = SMOBS + XI
                SMCAL = SMCAL + CALI
                NSMAL = NSMAL + 1
              END IF
              IF (SIGI > 0.0) THEN
                DOVERS = (XI - CALI) / SIGI
                IF (DOVERS < -100.0) THEN
                  QMRK = '?'
C * I(obs) << I(calc)
                  IPR(641) = IPR(641) + 1
                  IF (IPR(641) <= NP89) THEN
                    IOLTC(1, IPR(641)) = IH
                    IOLTC(2, IPR(641)) = IK
                    IOLTC(3, IPR(641)) = IL
                  END IF
                ELSE
                  QMRK = ' '
                END IF
C * INCLUDE L.S. WEIGHT PARAMETERS IN SIGMAI
                IF (IPR(632) /= 0) THEN
                  DOSW = (XI - CALI) / SIGIW
                  IF (DOSW < -10.0 .AND. TH < 3.0) THEN
                    TH = - TH
                    IF (IPR(588) < NP82) THEN
                      IPR(588) = IPR(588) + 1
                      NBSTP(1, IPR(588)) = IH
                      NBSTP(2, IPR(588)) = IK
                      NBSTP(3, IPR(588)) = IL
            END IF
                  END IF
                  CRIT  = 3.0
                  CRITO = 10.0
                  IF (ABS (DOSW) > CRIT .OR. QMRK == '?') THEN
                    IF (ABS (DOSW) > CRITO .AND. IPR(642) < NP83) THEN
                      IPR(642) = IPR(642) + 1
                      NOUTX(1, IPR(642)) = IH
                      NOUTX(2, IPR(642)) = IK
                      NOUTX(3, IPR(642)) = IL
                    END IF
                    NOUTL = NOUTL + 1
                    DOSAW = DOSAW + DOSW
                    DOSAV = DOSAV + DOVERS
                    IF (NOUTL == 1) WRITE (LU13, 99967, IOSTAT = IOST)
     1                'SigW(I)', CRIT, 'SigW(I) RatioW'
                    IF (IPR(746) < 8) THEN
                      WRITE (LU13, 99966, IOSTAT = IOST)
     1                  NOUTL, IH, IK, IL, TH, XI, CALI, SIGI,
     2                  MAX (-9999.99, DOVERS), QMRK,
     3                  MIN (99999.99, SIGIW), DOSW
                    ELSE
                      WRITE (LU13, 99921, IOSTAT = IOST)
     1                  NOUTL, IH, IK, IL, TH, INT (XI), INT (CALI),
     2                  INT (SIGI), MAX (-9999.99, DOVERS), QMRK,
     3                  MIN (99999.99, SIGIW), DOSW
                    END IF
                  END IF
                ELSE
                  IF (DOVERS < -10.0 .AND. TH < 3.0) THEN
                    TH = - TH
                    IF (IPR(588) < NP82) THEN
                      IPR(588) = IPR(588) + 1
                      NBSTP(1, IPR(588)) = IH
                      NBSTP(2, IPR(588)) = IK
                      NBSTP(3, IPR(588)) = IL
                    END IF
                  END IF
                  CRIT = 5.0
                  IF (ABS (DOVERS) > CRIT .OR. QMRK == '?') THEN
                    NOUTL = NOUTL + 1
                    DOSAV = DOSAV + DOVERS
                    IF (NOUTL == 1) WRITE (LU13, 99967, IOSTAT = IOST)
     1                'Sigma(I)', CRIT, ' '
                    IF (IPR(746) < 8) THEN
                      WRITE (LU13, 99966, IOSTAT = IOST)
     1                  NOUTL, IH, IK, IL, TH, XI, CALI, SIGI,
     2                  MAX (-9999.99, DOVERS), QMRK
                    ELSE
                      WRITE (LU13, 99921, IOSTAT = IOST)
     1                  NOUTL, IH, IK, IL, TH, INT (XI), INT (CALI),
     2                  INT (SIGI), MAX (-9999.99, DOVERS), QMRK
                    END IF
                  END IF
                END IF
              END IF
            END IF
C * R-GAP
            IF (SIGI > 0.0 .AND. SIGIW > 0.0) THEN
              NTEL     = NTEL + 1
              PAR(373) = PAR(373) + XI**2 / SIGI**2
              PAR(374) = PAR(374) + XI**2 / SIGIW**2
            END IF
C * STATISTICS
            IPR(585)   = MAX (IPR(585), IABS (IH))
            IPR(586)   = MAX (IPR(586), IABS (IK))
            IPR(587)   = MAX (IPR(587), IABS (IL))
            N          = MAX (1, MIN (20, 1 + INT (STHK ** 1.5 *
     1                   FACTOR)))
            STAT(N, 1) = STAT(N, 1) + XI
            STAT(N, 2) = STAT(N, 2) + MAX (0.0, CALI)
            STAT(N, 3) = STAT(N, 3) + SIGI
            STAT(N, 9) = STAT(N, 9) + 1.0
C * PAR(484) GENERALLY SHELXL 2 & JANA 3
            IF (XI > PAR(484) * SIGI) THEN
              NFUL1      = NFUL1 + 1
              STAT(N, 4) = STAT(N, 4) + SQRT (MAX(0.0, XI))
              STAT(N, 5) = STAT(N, 5) +
     1          ABS (SQRT (MAX(0.0, XI)) - SQRT (MAX (0.0, CALI)))
            END IF
            IF (SIGI. GT. 0.0) THEN
              IF (SIGK /= 0.0) THEN
                STAT(N, 6)  = STAT(N, 6)
     1                      + (XI - MAX (0.0, CALI)) ** 2 / SIGK
                STAT(N, 7)  = STAT(N, 7)  + XI ** 2 / SIGK
                STAT(N, 11) = STAT(N, 11)
     1                      + (XI - MAX (0.0, CALI)) ** 2 / SIGS
                STAT(N, 12) = STAT(N, 12) + XI ** 2 / SIGS
 
              END IF
              STAT(N, 8)  = STAT(N, 8)  + XI / SIGIW
              IF (SIGIW < 0.1E+15)
     1          STAT(N, 10) = STAT(N, 10) + SIGIW
            END IF
          END IF
C * CALCULATE STRUCTURE FACTORS ?
C * CHECK FOR GENERATE MODE (= 1)
          IF (IPR(408) == 1) THEN
            ACAL   = 0
            BCAL   = 0
            ACALA  = 0.0
            BCALA  = 0.0
            ACALAF = 0.0
            BCALAF = 0.0
            CALL PLA137 (IHT, IKT, ILT, ACAL, BCAL, ACALA, BCALA,
     1        ACALAF, BCALAF, SNTHA)
            ACAL = ACAL + ACALA
            BCAL = BCAL + BCALA
            XI   = (ACAL ** 2 + BCAL ** 2)
            SIGI = SQRT (XI) + 0.02 * XI
            IF (IPR(647) == 1) THEN
              XI = XI + (2.0 * GEN013 (IDUM) - 1.0) * SIGI
            END IF
 
C * CALC MODE (IUCR-CHECK) - EXPECT
          ELSE IF (IPR(408) == 2) THEN
            XI   = 100000.0
            SIGI = 10.0
          END IF
C * CHECK FOR SPACE GROUP ABSENCES
          SGX(1)  = IHT
          SGX(2)  = IKT
          SGX(3)  = ILT
          SGX(12) = 1.0
          CALL SGSM (27, LINE, SGX, 0, 0, IERR)
          NORI = NINT (SGX(12))
C * GENERATE BUFFER WITH NSYMH * 6 + 3 ENTRIES
C * STORE SYMMETRY RELATED REFLECTIONS AND DETERMINE MAX H, MAX K, MAX L
C * ONE BUFFER PER REFLECTION + SYMMETRY RELATED ONES
C * CHECK FOR ROOM FOR ADDITIONAL SYMMETRY EXPANDED SET FOR ANOTHER HKL
          IF (M + IMAX > NVDI) THEN
            WRITE (LU6, 99990, IOSTAT = IOST)
C * ALERT _810
            CALL PLA236 (810, 0, -999.0, 1.0, ' ', ' ')
            GO TO 90
          END IF
          SGX(4) = 0.0
          DO J = 1, NSYMH
            CALL SGSM (5, ICRD, SGX, J, LU7, IERR)
            DO I = 1, 3
              L          = NINT (SGX(I + 6))
              IHM(I)     = MAX (IHM(I), IABS (L))
              IAR(M + I) = L
            END DO
            IAR(M + 4) = NORI
            M          = M + 6
          END DO
          IAR(M + 1) = NINT (XI   * PSCFA)
          IAR(M + 2) = NINT (SIGI * PSCFB)
          IAR(M + 3) = 10000
          M          = M + 3
        END IF
      END DO
C * REFLECTION READ COMPLETED
      IF (MODE > 1) THEN
        IF (NOUTL > 0) THEN
          IF (PAR(493) >= 0.0) THEN
            WRITE (LU13, 99949, IOSTAT = IOST)
     1        DOSAV / NOUTL, DOSAW / NOUTL
          ELSE
            WRITE (LU13, 99962, IOSTAT = IOST) DOSAV / NOUTL
          END IF
        END IF
        IF (IPR(632) /= 0) WRITE (LU13, 99931, IOSTAT = IOST)
        IF (NSMAL > 0) WRITE (LU13, 99960, IOSTAT = IOST)
     1      SMOBS / NSMAL, SMCAL / NSMAL
C * TELL ABOUT LIKELY BEAMSTOP EFFECTED LOW ORDER REFLECTIONS
        IF (IPR(588) > 0) WRITE (LU13, 99935, IOSTAT = IOST)
        IF (MODE > 1 .AND. IPR(373) > 0) THEN
C * REPORT PSEUDO EXTINCTION PARAMETER VALUE
 
C * ALERT _935
        END IF
      ENDIF
      IF (IPR(392) > 1) THEN
C * CHANGE SORTING ORDER (H,K) WHEN HORIZONTAL MAX > 29
        IF (IHM(IND1) > IHM(IND2)) THEN
          CALL GEN014 (IND1, IND2)
        END IF
        IPR(394) = IND3
      END IF
      IHM(4)   =  2 * IHM(IND1) + 1
      IHM(5)   = (2 * IHM(IND2) + 1) * IHM(4)
      IHM(6)   = IHM(IND3) * IHM(5) + IHM(IND2) * IHM(4) + IHM(IND1)
      NPZ      = IHM(6) + 1
      MPH      = IHM(4)
      MHK      = IHM(5)
      IPR(305) = IHM(1)
      IPR(306) = IHM(2)
      IPR(307) = IHM(3)
C * CHECK FOR VALIDATION MODE (=-1)
      IF (IGBL(22) /= -1) THEN
        WRITE (LU6, 99996, IOSTAT = IOST)
     1    (IHM(MM), MM = 1, 3), ZONE(IND1), ZONE(IND2), ZONE(IND3)
        IF (IGBL(63) > 0) WRITE (LU7, 99996, IOSTAT = IOST)
     1    (IHM(MM), MM = 1, 3), ZONE(IND1), ZONE(IND2), ZONE(IND3)
      END IF
C * Check for 'any reflections accepted ?'
      IF (IPR(373) == 0) THEN
        IF (IGBL(22) /= -1) THEN
          WRITE (LU6, 99995, IOSTAT = IOST) JID(1:10)
          WRITE (LU7, 99995, IOSTAT = IOST) JID(1:10)
        END IF
        IF (IGBL(22) /= 0) THEN
          INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.ckf',
     1      OPENED = OPEND)
          IF (.NOT. OPEND) THEN
            OPEN (UNIT = LU13, FILE = NAMEFIL(1:KNMFIL) //'.ckf',
     1        STATUS = 'UNKNOWN')
          END IF
          WRITE (LU13, 99995, IOSTAT = IOST) JID(1:10)
        END IF
C * ALERT _902
        IF (IPR(659) == 0 .AND. IPR(674) == 0) THEN
          IPR(676) = 0
          CALL PLA236 (902, 0, 1.0, 1.0, ' ', ' ')
        END IF
        GO TO 90
      ELSE IF (IPR(373) < IPR(266)) THEN
        IF (IGBL(22) /= -1) THEN
          WRITE (LU6, 99956, IOSTAT = IOST) JID(1:10)
          WRITE (LU7, 99956, IOSTAT = IOST) JID(1:10)
        END IF
        WRITE (LU13, 99956, IOSTAT = IOST) JID(1:10)
C * ALERT _904
        CALL PLA236 (904, 0, FLOAT (IPR(373)), FLOAT (IPR(373)),
     1               ' ', ' ')
        GO TO 90
      END IF
C * TRANSFORM H,K,L BY SYMMETRY OPERATION TO THE ONE WITH HIGHEST
C * PACKING INDEX = IHKL
      I = 0
      L = - IMAX
      DO N = 1, IPR(373)
C * EXTINCTION REFLECTIONS ARE ELIMINATED
        NORI = 0
C * GENERATE SYMMETRY RELATED REFLECTIONS
        L = L + IMAX
        M = L
        K = L - 6
        DO J = 1, NSYMH
          K          = K + 6
          IAR(K + 5) = 1
          IF (IAR(K + 4) > 0) NORI = -1
C * ADD PACKING INDEX
          IAR(K + 6) = IHM(5) * IAR(K + IND3)
     1               + IHM(4) * IAR(K + IND2) + IAR(K + IND1)
C * TEST PACKING INDEX RANGE
          IF (IABS (IAR(K + 6)) >= NPZ) THEN
            WRITE (LU6, 99999, IOSTAT = IOST)
     1        N, IAR(K + IND1), IAR(K + IND2),
     2        IAR(K + IND3), IAR(K + 6), IHM(4), IHM(5), IHM(6), NPZ
            GO TO 90
          END IF
C * LOOK FOR STANDARD REFLECTION  (MAXIMUM  VALUE  OF  PACKED  INDICES)
          JUNK = IABS (IAR(K + 6)) - IABS (IAR(M + 6))
          IF (JUNK >= 0) THEN
            IF (JUNK == 0) THEN
              IF (IAR(K + 6) <= 0) CYCLE
            END IF
            M = K
          END IF
        END DO
C * MAKE THE FIRST REFLECTION THE STANDARD ONE (INTERCHANGE 1 & MX6 DATA)
        IOB4 = IAR(L + 6)
        DO J = 1, 6
          CALL GEN014 (IAR(L + J), IAR(M + J))
        END DO
        IF (IAR(L + 6) /= 0) THEN
          IF (IAR(L + 4) > 0) NORI = 1
          DO J = 1, NSYMH
            IOB1 = IAR(L + IND3 + (J - 1) * 6)
            IOB2 = IAR(L + J * 6)
            IOB3 = 0
            IF (J == 1) IOB3 = IOB4
            IF (NORI /= 0) THEN
              IF (IOB3 == 0) CYCLE
              IPR(381) = IPR(381) + 1
              IOBUF1   = -1
            ELSE
              IOBUF1   = IABS (IOB1)
            END IF
C * MAKE SURE THAT SIGMA (=SIGI) GREATER THAN ZERO
            IA    = IAR(L + IMAX - 2)
            IASIG = IAR(L + IMAX - 1)
            INTM  = MAX (INTM, IA)
            XSIGM = MAX (XSIGM, FLOAT (IASIG))
C * STORE NOT TRANSFORMED PACKED HKL
            NID       = NID + 1
            ID(I + 1) = IOBUF1
            ID(I + 2) = IOB2
            ID(I + 3) = IOB3
            ID(I + 4) = IA
            ID(I + 5) = IASIG
            ID(I + 6) = IAR(L + IMAX)
            I         = I + 6
            IF (I >= 252) THEN
              WRITE (LU8) ID
              I = 0
            END IF
          END DO
        END IF
      END DO
C * END OF FILE, CLEAR BUFFER
      WRITE (LU8) ID
      CALL GEN108 (LU8, 0)
C * DETERMINE SCALEFACTOR TO FIT OUTPUT FORMAT (2I8) FOR HKL
      SCFHKL = 99999999.0 / FLOAT (INTM)
      IF (SCFHKL > 1.0) SCFHKL = 1.0
      IF (IGBL(63) > 0 .AND. IPR(408) /= 2) THEN
        IF (IGBL(22) /= -1) THEN
          WRITE (LU6, 99998, IOSTAT = IOST) PSCFA, PSCFB, SCFHKL
          WRITE (LU7, 99998, IOSTAT = IOST) PSCFA, PSCFB, SCFHKL
          IF (PAR(426) > 0.0) THEN
            WRITE (LU6, 99939, IOSTAT = IOST)
     1        PSCFA * SCFHKL * PAR(426)**2
            WRITE (LU7, 99939, IOSTAT = IOST)
     1        PSCFA * SCFHKL * PAR(426)**2
          END IF
          WRITE (LU7, 99993, IOSTAT = IOST) PAR(284)
        END IF
      END IF
C * TEST FOR HKL - MODE
C * TEST FOR AVERAGING FRIEDEL RELATED REFLECTIONS
      IF (IPR(393) == 1 .AND. IGBL(22) /= -1)
     1  WRITE (LU7, 99997, IOSTAT = IOST)
      PAR(446) = ASIN (MIN (1.0, SQRT (ATHM) * PAR(17))) * RGBL(6)
      WRITE (LU6, 99989) PAR(446), PAR(165)
      IF (IGBL(63) > 0 .AND. IGBL(22) /= -1) THEN
        WRITE (LU7, 99989, IOSTAT = IOST) PAR(446), THM
C * LIST RECIPROCAL LATTICE SYMMETRY
        CALL SGSM (4, ICRD, SGX, 0, LU7, IERR)
      END IF
C * DATA ARE NOW COLLECTED PER NEXT RECIPRICAL LATTICE SECTION
C * THE BOTTOM UP PART OF IAR CONTAINS THE PACKED REFLECTION INDICES
C * INCLUDING A POINTER TO THE CORRESPONDING DATA (IF ANY)
C * THE RELEVANT DATA ARE STACKED TOP-DOWN-WARDS (6 WORDS / REFLECTION)
      CALL GEN108 (LU14, 0)
      IPL = 1
      CR1 = 0.0
      CR2 = 0.0
      CR3 = 0.0
      CALL GEN074 (SM, 1, 6, 0.0)
C * TAKE CARE OF EXTINCTION REFLECTION LISTING (# = IPR(381)
      IF (IPR(381) == 0) THEN
        IKS(IND3) = -1
      ELSE
        IKS(IND3) = -2
      END IF
      DO
        CALL GEN108 (LU8, 0)
        IKS(IND3) = IKS(IND3) + 1
        IF (IKS(IND3) <= IHM(IND3)) THEN
C * BOTTOM UP COUNTER
          N = 0
C * TOP DOWN COUNTER
          K = 0
          L = NVDI
          M = 252
          DO I = 1, NID
            M = M + 6
C * GET NEW BUFFER
            IF (M >= 252) THEN
              M = 0
              READ (LU8) ID
            END IF
C * GET ZONE NUMBER FOR THIS REFLECTION
C * TEST WHETHER THIS REFLECTION FITS IN THE CURRENT ZONE IKS(IND3)
            IF (ID(M + 1) == IKS(IND3)) THEN
C * GET PACKED HKL VALUE OF ORIGINAL (UNTRANSFORMED) REFLECTION
              IF (ID(M + 3) == 0) THEN
                IOB2 = 0
              ELSE
                K    = K + 1
                L    = L - 6
                IOB2 = K
C * TEST WHETHER THIS IS AN NON-ASYMMETRIC UNIT REFLECTION
                IAR(L + 1) = ID(M + 2)
                IAR(L + 2) = MAX (0, ID(M + 4))
                IAR(L + 3) = ID(M + 6)
                IAR(L + 4) = ID(M + 3)
                IAR(L + 5) = ID(M + 5)
                IAR(L + 6) = I
              END IF
              N2 = N + N
              IF (N2 + 2 > L) THEN
                WRITE (LU7, 99979, IOSTAT = IOST)
                GO TO 90
              END IF
              IAR(N2 + 1) = IABS (ID(M + 2))
              IAR(N2 + 2) = IOB2
              N = N + 1
            END IF
          END DO
C * SORT AND OUTPUT THE DATA OF THIS LEVEL
C * SKIP THIS LATTICE LEVEL FOR N = 0 - UNLESS VIEW or FCF-CHK MODE
          IF (N > 0 .OR. IGBL(22) /= 0) THEN
C * SORT DATA
            IF (N > 1) THEN
              N2 = N * 2
              CALL GEN124 (IAR, 1, N2)
              NB = 2
              CALL GEN014 (IAR(1), IAR(2))
              DO I = 4, N2, 2
                CALL GEN014 (IAR(I - 1), IAR(I))
                IF (IAR(I) /= IAR(NB)) THEN
                  CALL GEN124 (IAR, NB - 1, I - 2)
                  NB = I
                END IF
              END DO
              CALL GEN124 (IAR, NB - 1, N2)
C * ELIMINATE THE OVERREDUNDANCY OF SYMMETRY REL. REFL.
C * GET FIRST ELEMENT
              N01 = IAR(2)
              N02 = IAR(1)
              J   = 0
C * LOOP OVER ALL OTHER ENTRIES
              DO I = 2, N
C * N11 CONTAINS PACKED HKL VALUE
                N11 = IAR((I - 1) * 2 + 2)
C * N12 CONTAINS REFERENCE TO DATA (IF ANY)
                N12 = IAR((I - 1) * 2 + 1)
C * IS THIS ENTRY DIFFERENT FROM PREVIOUS ONE ?
                IF (N11 /= N01 .OR. N12 /= N02) THEN
                  IF (N11 == N01 .AND. N02 == 0) THEN
                    N02 = N12
                  ELSE
                    IAR(J * 2 + 1) = N01
                    IAR(J * 2 + 2) = N02
                    J              = J + 1
                    N01            = N11
                    N02            = N12
                  END IF
                END IF
              END DO
              IAR(J * 2 + 1) = N01
              IAR(J * 2 + 2) = N02
C * RETURN NEW NUMBER OF ELEMENTS IN N
              N              = J + 1
            END IF
C * SET VERTICAL INDEX ON MINIMUM VALUE
            IKS(IND2) = - IHM(IND2)
            IF (IKS(IND3) >= 0) THEN
              IF (IPR(392) > 1) THEN
                CALL PLA148
                IJKM = IHM(IND1) + 1
C * PREPARE NUMERICAL ( = IND1 INDEX) LINE
                DO IJK = 1, IJKM
                  IUU      = CHAR (ICHAR('0') + MOD (IJK - 1, 10))
                  I        = 2 * (IHM(IND1) + IJK)
                  IF (I <= NP44) CID(I:I) = IUU
                  J        = 2 * (IHM(IND1) - IJK + 2)
                  IF (J <= NP44) CID(J:J) = IUU
                END DO
                WRITE (LU14, 99977, IOSTAT = IOST) ZONE(IND3),
     1            IKS(IND3), ZONE(IND1), CID(1:150), ZONE(IND2)
                CALL PLA148
              END IF
            END IF
C * REFLECTION ZONE HEADER PRINT
            IF (IABS (IPR(392) - 2) == 1 .OR. IKS(IND3) == -1) THEN
C * PRINT PAGE HEADER
              IF (IPL > 98) THEN
                IF (IPL <= 102) THEN
                  DO I = IPL, 102
                    CALL GEN038 (AR(I), 1, 60)
                  END DO
                END IF
                IPL   = 1
                IF (IGBL(22) /= -1) THEN
                  CALL PLA262 (0)
                  WRITE (LU7, 99973, IOSTAT = IOST)
                  DO I = 1, 51
                    WRITE (LU7, 99972, IOSTAT = IOST) AR(I), AR(I + 51)
                  END DO
                END IF
              END IF
              DO I = 1, 3
                CALL GEN038 (AR(IPL + I - 1), 1, 60)
              END DO
              IF (IPR(408) /= 2) THEN
                IF (IKS(IND3) == -1) THEN
C * EXTINCTION PRINT HEADER
                  WRITE (XAR, 99975, IOSTAT = IOST)
                ELSE
C * ZONE HEADER PRINT
                  WRITE (XAR, 99976, IOSTAT = IOST) ZONE(IND3),
     1              IKS(IND3)
                END IF
              END IF
              AR(IPL + 1) = XAR
              IPL         = IPL + 3
            END IF
            JP             = 0
            JM             = 0
            IHKA           = - NPZ
            IAR(N * 2 + 1) = 2100000000
            IAR(N * 2 + 2) = 0
            NN             = N + 1
            DO K = 1, NN
              IHKB = IAR((K - 1) * 2 + 1)
              I    = IAR((K - 1) * 2 + 2)
              I6   = NVDI - I * 6
              IF (I > 0) IHKB = IAR(I6 + 1)
              IF (IABS (IHKB) /= IABS (IHKA)) THEN
                IF (IHKA  > - NPZ) THEN
                  IHK = IABS(IHKA)
                  IND        = IHK + IHM(6)
                  IL         = IND / IHM(5)
                  IS         = IND - IHM(5) * IL
                  IK         = IS  / IHM(4)
                  IH         = IS  - IHM(4) * IK - IHM(IND1)
                  IK         = IK  - IHM(IND2)
                  IL         = IL  - IHM(IND3)
                  IHKL(IND1) = IH
                  IHKL(IND2) = IK
                  IHKL(IND3) = IL
                  DO MM = 1, 3
                    IHKLE(MM) = IHKL(MM)
                  END DO
C * ADD INFORMATION TO R.L. PRINT BUT SKIP THIS SECTION IN CASE OF
C * EXTINCTION REFLECTIONS
                  IF (IKS(IND3) >= 0) THEN
C * START A NEW LINE TEST
                    IF (IPR(392) > 1) THEN
                      DO WHILE (IHKL(IND2) > IKS(IND2))
C * OUTPUT THIS LINE
                        WRITE (LU14, 99974, IOSTAT = IOST) IKS(IND2),
     1                    CID(1:(4 * IHM(IND1) + 2))
                        IKS(IND2) = IKS(IND2) + 1
C * CLEAR BUFFER
                        CALL PLA148
                      END DO
                    END IF
                  END IF
C * OUTPUT (LISTING & FILE) (IRM1 = AVERAGE OBS ON RETURN)
                  IF (IKS(IND3) == -1) IPR(754) = IPR(754) + JP
                  CALL PLA146 (JP, 1, LUP17, IRM1)
                  IF (IPR(275) /= 2 .AND. IPR(393) /= 1) THEN
                    IF (IPR(408) /= 2) IGBL(18) = 1
                    CALL PLA146 (JM, 2, LUP18, IRM2)
                    IF (JP /= 0 .AND. JM /= 0) THEN
                      SM(1, 3) = ABS(IRM1 - IRM2) + SM(1, 3)
                      SM(2, 3) = SM(2, 3) + IRM1 + IRM2
C * FRIEDEL COUNT - EXCLUDE SYSTEMATIC EXTINCTIONS
                      IF (IKS(IND3) /= -1) IPR(380) = IPR(380) + 1
                    END IF
                  END IF
                  JP  = 0
                  JM  = 0
                  IF (IPR(275) == 2) THEN
                    IHKA = IABS (IHKB)
                  ELSE
                    IHKA = IHKB
                  END IF
                ELSE
                  IF (IPR(275) == 2) IHKB = IABS (IHKB)
                  IHKA = IHKB
                END IF
              END IF
              IF (I > 0 .AND. I < NN) THEN
                REFA  = IAR(I6 + 2) * SCFHKL
                REFB  = IAR(I6 + 5) * SCFHKL
C * MAKE ESD AT LEAST SMALL POSITIVE
                IF (REFB <= 0) REFB = 0.001
                IVGNR = IAR(I6 + 6)
                IHKL2 = IAR(I6 + 4)
                IF (IPR(275) /= 2 .AND. IPR(393) /= 1 .AND.
     1            IHKB < 0) THEN
C * REFLECTION H,K,L WITH PACKING ADDRES NEGATIVE
                  IF (JM < NP68) JM = JM + 1
                  RA(JM,  2) = REFA
                  RB(JM,  2) = REFB
                  IRC(JM, 2) = IVGNR
                  IRD(JM, 2) = IHKL2
                ELSE
C * REFLECTION H,K,L WITH PACKING ADDRESS POSITIVE
                  IF (JP < NP68) JP = JP + 1
                  RA(JP,  1) = REFA
                  RB(JP,  1) = REFB
                  IRC(JP, 1) = IVGNR
                  IRD(JP, 1) = IHKL2
                END IF
              END IF
            END DO
            IF (IKS(IND3) >= 0) THEN
              IF (IPR(392) > 1) THEN
                DO WHILE (IKS(IND2) <= IHM(IND2))
                  WRITE (LU14, 99974, IOSTAT = IOST)
     1              IKS(IND2), CID(1:(4 * IHM(IND1) + 2))
                  IKS(IND2) = IKS(IND2) + 1
                  CALL PLA148
                END DO
              END IF
            END IF
          END IF
          CYCLE
        ELSE
          EXIT
        END IF
      END DO
C * CLEAR PRINTBUFFER IF ANY
      IF (IPL > 1 .AND. IPR(408) /= 2) THEN
        IF (IPL <= 102) THEN
          DO I = IPL, 102
            CALL GEN038 (AR(I), 1, 60)
          END DO
        END IF
        IPL   = 1
        IF (IGBL(22) /= -1) THEN
          CALL PLA262 (0)
          WRITE (LU7, 99973, IOSTAT = IOST)
          DO I = 1, 51
            WRITE (LU7, 99972, IOSTAT = IOST) AR(I), AR(I + 51)
          END DO
        END IF
      END IF
C * PRINT RECIPROCAL LATTICE (NOT FOR VALIDATION)
      IF (IPR(392) > 1 .AND. IGBL(22) /= -1) THEN
        CALL GEN108 (LU14, 0)
        DO WHILE (.TRUE.)
          READ (LU14, 99959, IOSTAT = IOST) PRBUF
          IF (IOST /= 0) EXIT
          IF (PRBUF(8:8) == ZONE(IND3)) THEN
            CALL PLA262 (0)
          END IF
          WRITE (LU7, 99959, IOSTAT = IOST) PRBUF
        END DO
      END IF
      IF (IGBL(22) /= -1) THEN
        IF (IPR(408) /= 2) THEN
          CALL PLA262 (0)
        ELSE
          CALL PLA262 (2)
        END IF
        IF (IPR(408) <= 0) THEN
          WRITE (LU6, 99982, IOSTAT = IOST)
     1      IPR(372), IPR(371), IPR(370), IPR(754)
          WRITE (LU7, 99982, IOSTAT = IOST)
     1      IPR(372), IPR(371), IPR(370), IPR(754)
        END IF
        IF (IPR(408) < 2) THEN
          WRITE (LU6, 99984, IOSTAT = IOST) IPR(373), IPR(375)
          WRITE (LU7, 99984, IOSTAT = IOST) IPR(373), IPR(375)
          IF (IPR(376) > 0 .AND. IPR(408) < 1) THEN
            WRITE (LU6, 99983, IOSTAT = IOST) IPR(376)
            WRITE (LU7, 99983, IOSTAT = IOST) IPR(376)
          END IF
        END IF
      END IF
C * COMBINE .hkp & .hks
      IF ((IPR(408) == 0 .AND. IGBL(22) == 0) .OR.
     1    (IPR(408) == 1 .AND. IPR(393) == 0)) THEN
        IF (IPR(378) > 0) THEN
C * ENDFILE/REWIND
          CALL GEN108 (LUP18 , 1)
          DO I = 1, IPR(378)
            READ  (LUP18, 99959) AA
            WRITE (LUP17, 99959, IOSTAT = IOST) AA
          END DO
        END IF
        WRITE (LUP17, 99930) 0, 0, 0, 0, 0, 0
C * APPEND TRAILER INFO TO GENERATED 'OBSERVED' REFLECTION FILE
        IF (IPR(408) == 1) THEN
          WRITE (LUP17, 99926) IPR(377) + IPR(378)
          WRITE (LUP17, 99928) SPGRNM(1)(1:11), (PAR(I), I = 101, 106),
     1      PAR(17)
          N = INDEX (RLWS(5), '''')
          WRITE (LUP17, 99927) RLWS(5)(1:N - 1)
          WRITE (LU6  , 99927) RLWS(5)(1:N - 1)
          DO I = 1, IAN
            WRITE (LUP17, 99929)
     1        LMT(IENS(I), 1), ANOM(IENS(I), 1), ANOM(IENS(I), 2)
            WRITE (LU6  , 99929)
     1        LMT(IENS(I), 1), ANOM(IENS(I), 1), ANOM(IENS(I), 2)
          END DO
        END IF
      END IF
C * CHECK FOR 'NON-FCF VALIDATION'
      IF (IGBL(22) /= -1) THEN
        WRITE (LU6, 99988, IOSTAT = IOST) IPR(377)
C * CHECK PRINT LEVEL
        IF (IGBL(63) > 0) WRITE (LU7, 99988, IOSTAT = IOST) IPR(377)
        IF (IPR(378) > 0 .AND. IPR(408) /= 1) THEN
          WRITE (LU6, 99987, IOSTAT = IOST) IPR(378),
     1      IPR(377) + IPR(378)
          IF (IGBL(63) > 0) THEN
            WRITE (LU7, 99987, IOSTAT = IOST) IPR(378),
     1        IPR(377) + IPR(378)
          END IF
        END IF
        IF (IPR(380) > 0) THEN
          IF (IPR(408) < 1) THEN
            WRITE (LU6, 99985, IOSTAT = IOST) IPR(380)
            IF (IGBL(63) > 0)
     1        WRITE (LU7, 99985, IOSTAT = IOST) IPR(380)
          END IF
        END IF
      END IF
      IF (SM(2, 1) > 0.0) THEN
        CR1 = SM(1, 1) / SM(2, 1)
      END IF
      IF (SM(2, 2) > 0.0) THEN
        CR2 = SM(1, 2) / SM(2, 2)
        IF (IPR(380) > 0) CR3 = 2 * SM(1, 3) / SM(2, 3)
      END IF
      IF (IPR(408) < 1) THEN
        IF (IGBL(22) /= -1) THEN
          IF (CR1 /= 0.0) THEN
            WRITE (LU6, 99981, IOSTAT = IOST) CR1
            WRITE (LU7, 99981, IOSTAT = IOST) CR1
            IF (IPR(378) > 0) THEN
              WRITE (LU6, 99980, IOSTAT = IOST) CR2, CR3
              WRITE (LU7, 99980, IOSTAT = IOST) CR2, CR3
            END IF
          END IF
        END IF
        MAXM = 0
        TEL  = 0
        MAXI = 0
        DO I = 1, NP68
          MAXM = MAX (MAXM, MULT(I))
          TEL  = TEL + MULT(I)
          IF (MULT(I) > 0) MAXI = I
        END DO
        PERCENT(MAXI) = MULT(MAXI)
        DO I = MAXI -1, 1, -1
          PERCENT(I) = PERCENT(I + 1) + MULT(I)
        END DO
        SCAL = 38.0 / MAXM
        IF (IGBL(9) > 0) THEN
          FILETYPE = 'FCF'
        ELSE
          FILETYPE = 'HKL'
        END IF
        WRITE (LU6, 99923) FILETYPE
        WRITE (LU7, 99923) FILETYPE
        AVERAGE = 0.0
        COUNTB  = 0
        DO I = 1, MAXI
          IF (MULT(I) > 0) THEN
            IGETAL  = I * MULT(I)
            COUNTB  = COUNTB  + IGETAL
            AVERAGE = AVERAGE + IGETAL
            N       = MAX (1, NINT (SCAL * MULT(I)))
            WRITE (LU6, 99924) I, MULT(I), IGETAL, STAR(1:N),
     1        BLANKO(N+1:39), PERCENT(I) * 100.0 / TEL, I
            WRITE (LU7, 99924) I, MULT(I), IGETAL, STAR(1:N),
     1        BLANKO(N+1:39), PERCENT(I) * 100.0 / TEL, I
          END IF
        END DO
        AVERAGE = AVERAGE / TEL
        WRITE (LU6, 99922) NINT (TEL), NINT (COUNTB), AVERAGE,
     1    FILETYPE
        WRITE (LU7, 99922) NINT (TEL), NINT (COUNTB), AVERAGE,
     !    FILETYPE
      END IF
      IF (IGBL(22) /= 0) GO TO 20
C * FCF VALIDATION REPORT
   60 IF (IGBL(22) < 0) THEN
        WRITE (LU13, 99970, IOSTAT = IOST)
        STLMX = SIN (PAR(446) / RGBL(6)) / PAR(17)
        JMAX  = MIN (29, INT (STLMX / 0.05) + 1)
        STL   = 0.45
        DO I = 10, JMAX
          STL = STL + 0.05
          STH = MIN (1.0, STL * PAR(17), STLMX * PAR(17))
          IF (STH <= 1.0) THEN
            TH  = ASIN (STH) * RGBL(6)
            IF (ICNT(I - 9, 1) /= 0) THEN
              YDUM = FLOAT (ICNT(I - 9, 2)) / ICNT(I - 9, 1)
            ELSE
              YDUM = 0.0
            END IF
            WRITE (LU13, 99969, IOSTAT = IOST)
     1        TH, STH / PAR(17), YDUM, (ICNT(I - 9, J), J = 1, 2),
     2        ICNT(I - 9, 1) - ICNT(I - 9, 2)
            IF (I == 12) WRITE (LU13, 99957, IOSTAT = IOST)
          END IF
        END DO
        WRITE (LU13, 99938, IOSTAT = IOST)
        IF (PAR(493) >= 0.0) THEN
          WRITE (LU13, 99948, IOSTAT = IOST)
        ELSE
          WRITE (LU13, 99965, IOSTAT = IOST)
        END IF
        CALL GEN074 (FULL, 1, 12, 0.0)
        NFULL  = 0
        DO I = 1, 20
          DO J = 1, 12
            FULL(J) = FULL(J) + STAT(I, J)
          END DO
          N = NINT (STAT(I, 9))
          IF (N > 0) THEN
            NFULL = NFULL + N
            R1    = 0.0
            R2    = 0.0
            IF (NINT (STAT(I, 4)) /= 0) R1 = STAT(I, 5) / STAT(I, 4)
            IF (STAT(I, 7) > 0.0) R2 = SQRT (STAT(I, 6) / STAT(I, 7))
            S   = SQRT(STAT(I, 6) / N)
            R   = STAT(I, 8)  / N
            AI  = STAT(I, 1)  / N
            SA  = STAT(I, 10) / N
            IF (STAT(I, 1) /= 0.0) THEN
              RS = STAT(I, 3) / STAT(I, 1)
            ELSE
              RS = 0.0
            ENDIF
            SINTHL = (I / FACTOR) ** 0.333333
            IF (I < 20) THEN
              STH = MIN (1.0, SINTHL * PAR(17), STLMX * PAR(17))
            ELSE
              STH = MIN (1.0, STLMX * PAR(17))
            END IF
            TH  = ASIN(STH) * RGBL(6)
            WRITE (LU13, 99964, IOSTAT = IOST)
     1        TH, STH / PAR(17), N, R1, R2, S, RS, R, AI, SA
          END IF
        END DO
C * LIST TOTALS
        IF (FULL(4)  /= 0.0) PAR(477) = FULL(5) / FULL(4)
        IF (FULL(7)  /= 0.0) PAR(478) = SQRT (FULL(6) / FULL(7))
        IF (FULL(12) /= 0.0) WR2      = SQRT (FULL(11) / FULL(12))
        IF (FULL(1)  /= 0.0) RSIG     = FULL(3) / FULL(1)
        JUNK = NFULL - MAX (0, IPR(266) + IPR(767))
        IF (JUNK /= 0) THEN
          PAR(479) = SQRT (FULL(6)  / JUNK)
          GOF      = SQRT (FULL(11) / JUNK)
        END IF
        IPR(623) = NFUL1
        IPR(624) = NFULL
C * PREDICTED wR2's  (BASED ON SIG(I) AND SIGW(I) RESP.)
        PAR(373) = SQRT ((NTEL - IPR(266)) / PAR(373))
        PAR(374) = SQRT ((NTEL - IPR(266)) / PAR(374))
C * _969 ALERT - R-FACTOR GAP
        IF (IPR(105) == 0) THEN
          CALL PLA236 (-969, 3, -999.0, PAR(478) / PAR(373), ' ', ' ')
C * REPORT PREDICTED wR2's
          WRITE (LU68, 99918) PAR(373) * 100.0, PAR(374) * 100.0
        END IF
        IF (IGBL(9) == 17 .OR. IGBL(9) == 18) THEN
          PAR(479) = SQRT (PAR(564) / (IPR(764) - IPR(266)))
        END IF
C * DIFFERENCE CIF REPORTED AND FCF ACTUAL OBSERVED REFL COUNT
        YUNK = FLOAT (IPR(264) - IPR(623))
C * ALERT _992 - _reflns_number_gt CIF/FCF inconsistency
        IF (ABS (YUNK) > 1.0 .AND. ABS (YUNK) <= 100) THEN
          CALL PLA236 (992, 0, -999.0, YUNK, ' ', ' ')
        ELSE
          CALL PLA236 (992, 0, ABS (YUNK), YUNK, ' ', ' ')
        END IF
        WRITE (LU13, 99932, IOSTAT = IOST) RSIG
        WRITE (LU13, 99942, IOSTAT = IOST)
     1    PAR(477), NFUL1, PAR(478), NFULL, PAR(479)
        IF (PAR(173) > 0.0 .AND. PAR(174) > 0.0) THEN
          WRITE (LU13, 99941, IOSTAT = IOST)
     1      PAR(173), IPR(264), PAR(174), MAX (IPR(265), IPR(765)),
     2 PAR(299), MAX (0, IPR(266))
C * CHECK FOR SHELXL WEIGHT PARAMETERS
          IF (PAR(493) >= 0.0) THEN
              IF (ABS(PAR(478)) < 0.001) THEN
C * ALERT _903 - Fobs = Fcalc in FCF
                CALL PLA236 (903, 0, 1.0, 1.0, ' ', ' ')
              ELSE
                YUNK = PAR(173) - PAR(477)
C * ALERT _921 - COMPARE REPORTED AND CALCULATED R-VALUE DIFFERENCE
                IF (ABS(YUNK) > 0.001)
     1             CALL PLA236 (921, 4, ABS (YUNK), YUNK, ' ', ' ')
                  YUNK = PAR(174) - PAR(478)
C * ALERT _922 - COMPARE REPORTED AND CALCULATED wR2-VALUE DIFFERENCE
                IF (ABS(YUNK) > 0.001) THEN
C * TEST FOR XD
                  IF (IGBL(9) /= 11) THEN
                    CALL PLA236 (922, 4, ABS(YUNK), YUNK, ' ', ' ')
                  ELSE
                    CALL PLA236 (922, 4, -999.0, YUNK, ' ', ' ')
                  END IF
                END IF
                YUNK = PAR(299) - PAR(479)
C * ALERT _923 - COMPARE REPORTED AND CALCULATED S-VALUE DIFFERENCE
                IF (ABS(YUNK) > 0.005) THEN
C * TEST FOR XD
                  IF (IGBL(9) /= 11) THEN
                    CALL PLA236 (923, 3, ABS (YUNK), YUNK, ' ', ' ')
                  ELSE
                    CALL PLA236 (923, 3, -999.0, YUNK, ' ', ' ')
                  END IF
                END IF
              END IF
C * ALERT _929 - TEST FOR NO WEIGHT PARAMETERS
          ELSE
            CALL PLA236 (929, 0, -999.0, 0.0, ' ', ' ')
          END IF
        END IF
        WRITE (LU13, 99934, IOSTAT = IOST) WR2, GOF
C * ALERT _939 - High GOF
        IF (GOF > 5.0 .AND. IPR(651) == 0)
     1    CALL PLA236 (939, 2, GOF, GOF, ' ', ' ')
C * CHECK FOR HKL-RANGE REPORTED IN THE CIF WITH THAT FOUND IN THE FCF
        IF (IPR(672) == 6) THEN
C * CHECK FOR LAUE GROUP TRICLINIC, MONOCLINIC, ORTHORHOMBIC
          IF (IPR(258) < 4) THEN
C * ALERT _953
            DIFH = ABS(IPR(585) - MAX (0, -IPR(267), IPR(268)))
            IF (DIFH /= 0.0)
     1        CALL PLA236 (953, 0, -999.0, DIFH, ' ', ' ')
C * ALERT _954
            DIFK = ABS(IPR(586) - MAX (0, -IPR(269), IPR(270)))
            IF (DIFK /= 0.0)
     1        CALL PLA236 (954, 0, -999.0, DIFK, ' ', ' ')
          END IF
C * ALERT _955
          DIFL = ABS (IPR(587) - MAX (0, -IPR(271), IPR(272)))
          IF (DIFL /= 0.0)
     1      CALL PLA236 (955, 0, -999.0, DIFL, ' ', ' ')
        END IF
C * CHECK CALCULATED H,K,L RANGE VERSUS H,K,L RANGE IN FCF
C * CHECK FOR LAUE GROUP TRICLINIC, MONOCLINIC, ORTHORHOMBIC
        IF (IPR(258) < 4 .AND. IGBL(9) /= 11) THEN
C * ALERT _956
          DIFH = ABS (IPR(585) - IPR(561))
          IF (DIFH > 1.0)
     1      CALL PLA236 (956, 0, -999.0, DIFH, ' ', ' ')
C * ALERT _957
          DIFK = ABS (IPR(586) - IPR(562))
          IF (DIFK > 1.0)
     1      CALL PLA236 (957, 0, -999.0, DIFK, ' ', ' ')
        END IF
C * ALERT _958
        DIFL = ABS (IPR(587) - IPR(563))
        IF (DIFL > 1.0)
     1    CALL PLA236 (958, 0, -999.0, DIFL, ' ', ' ')
C * SUMMARY
        YUNK = MIN (STLMX, 0.6)
        IF (IPR(393) == 1 .OR. IPR(275) == 2) THEN
          WRITE (LU13, 99947, IOSTAT = IOST)
        ELSE
          WRITE (LU13, 99946, IOSTAT = IOST)
        END IF
        MH = MAX (0, -IPR(267), IPR(268))
        MK = MAX (0, -IPR(269), IPR(270))
        ML = MAX (0, -IPR(271), IPR(272))
        WRITE (LU13, 99968, IOSTAT = IOST)
     1    IPR(373), (MIN (999, IPR(M)), M = 585, 587), IPR(379),
     2    PAR(446), (MIN (999, IHM(M)), M = 1, 3), MAX (0.0, PAR(168)),
     3    MH, MK, ML, PAR(445), MAX(0.0, PAR(167))
        IF (IPR(393) == 1 .OR. IPR(275) == 2) THEN
          WRITE (LU13, 99944, IOSTAT = IOST)
     1      IPR(559), IPR(377), IPR(383), IPR(375), IPR(627), IPR(628)
C * ALERT _960
          IF (IPR(628) > 0) THEN
            CALL PLA236 (960, 0, -999.0, FLOAT (IPR(628)), ' ', ' ')
          END IF
C * ALERT _961 - REPORT NO NEGATIVE INTENSITIES (EXCL CRYSTALS-5)
          IF (IPR(627) == 0 .AND. IGBL(9) .NE. 5) THEN
            CALL PLA236 (961, 0, -999.0, 0.0, ' ', ' ')
          END IF
C * ALERT _962 - REPORT # OF REFLECTIONS IN FCF WITH SIGMA = 0.0
          IF (IABS(IGBL(8)) .EQ. 3 .AND. IPR(631) .GT. 0)
     1      CALL PLA236 (962, 0, -999.0, FLOAT (IPR(631)),
     2                   ' FCF File', ' ')
        ELSE
          WRITE (LU13, 99945, IOSTAT = IOST)
     1      IPR(559) + IPR(560), IPR(559), IPR(560),
     2      IPR(377) + IPR(378), IPR(377), IPR(378),
     3      IPR(383) + IPR(362), IPR(383), IPR(362),
     4      IPR(375) + IPR(376), IPR(375), IPR(376),
     5      IPR(559) - IPR(377) + IPR(560) - IPR(378),
     6      IPR(559) - IPR(377) , IPR(560) - IPR(378)
        END IF
        WRITE (LU13, 99943, IOSTAT = IOST)
     1    IPR(386), IPR(553), YUNK, IPR(555), YUNK,
     2    IPR(557), IPR(584), IPR(588), IPR(385)
        CALL PLA169 (-1, 0.0, 0.0, 0.0, 0)
        CALL PLA169 (-3, 0.0, 0.0, 0.0, LU13)
C * ALERT _910 - Report (Number of reflections) below Theta(min)
        IF (IPR(553) > 0) THEN
          YUNK = -999.0
          IF (IPR(553) >= 5) YUNK = FLOAT(IPR(553))
          CALL PLA236 (-910, 2, YUNK, PAR(445), ' ', ' ')
          CALL PLA239 (LU68, NP79, IPR(553), NTHMN)
        END IF
        YUNK = MIN(SIN(PAR(446) / RGBL(6)) / PAR(17), 0.6)
        WRITE (LIJN(1:7), 99953, IOSTAT = IOST) YUNK
        IF (IPR(559) > 0) THEN
C * ALERT _911 - TEST for missing refl between Th-min and sinth/l=0.6
          IF (IPR(555) > 1) THEN
            YUNK = -999.0
            IF (IPR(309) == 2)
     1        YUNK = (FLOAT (IPR(555)) * 100.0) / IPR(559)
            CALL PLA236 (-911, 0, YUNK, FLOAT (IPR(555)),
     2          LIJN(1:7), ' ')
            CALL PLA239 (LU68, NP80, IPR(555), NTHMX)
          END IF
C * ALERT _912
          IF (IPR(557) > 0 .AND. STLMX > 0.6) CALL PLA236
     1      (912, 0, -999.0, FLOAT (IPR(557)), ' ', ' ')
        END IF
C * ALERT _913 - REPORT NUMBER MISSING STRONG REFLECTIONS (AVOID CRYSTL1)
        IF (IPR(584) > 0 .AND. IGBL(9) /= 5) THEN
          YUNK = -999.0
          IF (IPR(584) > 3) YUNK = FLOAT (IPR(584))
          CALL PLA236 (-913, 0, YUNK, FLOAT (IPR(584)), ' ', ' ')
          CALL PLA239 (LU68, NP84, IPR(584), NSTRM)
        END IF
C * REPORT BEAMSTOP EFFECTED REFLECTIONS
C * ALERT _919
        IF (IPR(588) > 0) THEN
          CALL PLA236 (-919, 0, FLOAT (IPR(588)), FLOAT (IPR(588)),
     1      ' ', ' ')
          CALL PLA239 (LU68, NP82, IPR(588), NBSTP)
        END IF
C * ALERT _918 - REPORT ON # I(obs) << I(calc)
        IF (IPR(641) > 0) THEN
          CALL PLA236 (-918, 0, FLOAT (IPR(641)), FLOAT (IPR(641)),
     2      ' ', ' ')
          CALL PLA239 (LU68, NP89, IPR(641), IOLTC)
        END IF
C * ALERT _934 - REPORT ON # OF OUTLIERS > 10 (SKIPPED FOR HKLF 5)
        IF (IPR(619) == 0) THEN
          IF (IPR(642) > 0) THEN
            CALL PLA236 (-934, 0, FLOAT (IPR(642)), FLOAT (IPR(642)),
     1        ' ', ' ')
            CALL PLA239 (LU68, NP83, IPR(642), NOUTX)
          ENDIF
        END IF
        IF (IPR(380) > 0) WRITE (LU13, 99961, IOSTAT = IOST) IPR(380)
C * TAKE EXCLUDED REFLECTION INTO ACCOUNT FOR CRYSTALS(I)
        IF (IGBL(9) == 8) THEN
          YUNK = PAR(517)
        ELSE
          YUNK = PAR(446)
        END IF
C * USE _diffrn_reflns_theta_full when _diffrn_reflrn_theta_max NOT GIVEN
        IF (PAR(168) < 0.0 .AND. PAR(312) > 0.0) THEN
          DIFF = PAR(312) - YUNK
 
        ELSE
          DIFF = PAR(168) - YUNK
        END IF
C * ALERT _920
        IF (ABS (DIFF) > 0.01)
     1    CALL PLA236 (920, 2, ABS (DIFF), DIFF, ' ', ' ')
 
C * CHECK FOR TWINNING & BIJVOET PAIR ANALYSIS (DUMMY !!)
        CALL PLA405 (2, NOPT)
C * GRAPHICS OUTPUT
        IF (IPR(123) == 0 .AND. IGBL(3) /= 1 .AND. IGBL(3) /= 33
     1      .AND. IGBL(3) /= 34) THEN
          CALL GEN108 (LU13, 1)
C * INACTIVATE CLICKABLE MENU-OPTIONS
          IGBL6SAVE = IGBL(6)
          IGBL(6)   = 0
          N         = 0
          DO
            VRT = 19.4
            BCD = 'FCF-VALIDATION'//CHAR (0)
            CALL GGIP (HORS, VERT, 0.0, 1)
            N   = N + 1
            IF (N == 1) THEN
              LIJN = 'VALIDATION REPORT FOR CURRENT FCF'
              CALL PLA439 (0.0, LIJN, 33, 0.375, 5 + IGBL(68), 2, 7.0,
     1                     VRT - 0.6)
              VRT = VRT - 1.1
            END IF
            DO WHILE (VRT > 0.6)
              READ (LU13, 99959, IOSTAT = IOST) LIJN
              IF (IOST == -1) GO TO 80
              WRITE (6, 99959) LIJN
              VRT = VRT - 0.5
              CALL PLA439 (0.0, LIJN, 80, 0.35, 1, 2, 1.0, VRT)
            END DO
C * WHAT NEXT ?
   70       CALL PLA012 (1, 1)
            IF (IGGT(1:4) == 'PLOT') GO TO 70
            IF (IGGT(1:4) == 'CALC' .OR. IGGT(1:1) == 'Y') CYCLE
            IF (IGGT(1:4) == 'EXIT') GO TO 90
            IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
              IF (IGGT(1:1) == 'N') GO TO 90
              IF (LRET == 2) THEN
                CALL GEN108 (LU13, 0)
                CYCLE
              END IF
              LINE = IGGT
              CALL GEN038 (IGGT, 1, 80)
            END IF
          END DO
   80     CALL PLA297 (0)
        END IF
      END IF
   90 IGBL(6) = IGBL6SAVE
      IF (IPR(408) == 2) THEN
C * SAVE 'EXACT' VALUES FOR VALIDATION OUTPUT
        IPR(559) = IPR(377)
        IPR(560) = IPR(378)
        IPR(561) = IPR(305)
        IPR(562) = IPR(306)
        IPR(563) = IPR(307)
C * REPORT DIFFERENCES BETWEEN CALCULATED AND REPORTED INDEX MAXIMA
        DIFH     = IPR(561) - MAX (0, -IPR(267), IPR(268))
        IF (IPR(105) == 0 .AND. IPR(672) == 6 .AND.
     1    IGBL(9) /= 11) THEN
C * ALERT _950 - DIFF (HMAX-CALC & HMAX-REPORTED)
          IF (ABS (DIFH) > 1.0)
     1      CALL PLA236 (950, 0, -999.0, DIFH, ' ', ' ')
          DIFK = IPR(562) - MAX (0, -IPR(269), IPR(270))
C * ALERT _951 - DIFF (KMAX-CALC & HMAX-REPORTED)
          IF (ABS(DIFK) > 1.0)
     1      CALL PLA236 (951, 0, -999.0, DIFK, ' ', ' ')
          DIFL = IPR(563) - MAX (0, -IPR(271), IPR(272))
C * ALERT _952 - DIFF (LMAX-CALC & LMAX-REPORTED)
          IF (ABS(DIFL) > 1.0)
     1      CALL PLA236 (952, 0, -999.0, DIFL, ' ', ' ')
        END IF
      END IF
C * HANDLE .hks STATUS
      IF (IGBL(18) == 0 .OR.  IGBL(22) == -1 .OR.
     1   (IGBL(18) == 1 .AND. IPR(408) > 0) .OR.
     2   (IGBL(22) == 0 .AND. IPR(408) < 1)) THEN
        CLOSE (UNIT = LU18, STATUS = 'DELETE', IOSTAT = IOST)
        IF (IOST /= 0) RETURN
        IGBL(18) = 0
      ELSE
        CLOSE (UNIT = LU18, IOSTAT = IOST)
      END IF
      DEALLOCATE (IAR)
      RETURN
