      SUBROUTINE PLA146 (JP, IND, LPUN, IRM)
C * ASYM (2)
      USE files
      USE parameters
      USE reflex
      USE asym
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: JP
      INTEGER :: MM
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: NDC
      INTEGER :: IHU
      INTEGER :: ILT
      INTEGER :: ISM
      INTEGER :: IND
      INTEGER :: JPA
      INTEGER :: JPB
      INTEGER :: IRM
      INTEGER :: LPAB
      INTEGER :: LPUN
      REAL :: RM
      REAL :: SA
      REAL :: SB
      REAL :: SY
      REAL :: SZ
      REAL :: SM0
      REAL :: DEL
      REAL :: ACAL
      REAL :: BCAL
      REAL :: STHK
      REAL :: ACALA
      REAL :: BCALA
      REAL :: SNTHA
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN095
      CHARACTER(len=60) :: XAR
      CHARACTER(len=80) :: ICRD
      CHARACTER(len=1)  :: IDSM
      IF (JP == 1 .AND. IND == 1) IPR(727) = IPR(727) + 1
      NSYMH = IPR(255)
      IHU   = 2 * (IHKL(IND1) + IHM(IND1) + 1) + 1 - IND
      IF (IND == 1) THEN
        IDSM = '+'
      ELSE
        IDSM = '-'
      END IF
      IF (JP == 1) THEN
        IPR(637) = IPR(637) + 1
      ELSE IF (JP > 1) THEN
        IPR(638) = IPR(638) + 1
      ENDIF
      IF (JP > 0) THEN
        IF (IKS(IND3) >= 0) MULT(JP) = MULT(JP) + 1
        SA = 0.0
        SB = 0.0
        DO K = 1, JP
          SY = RB(K, IND)
          SZ = 1.0 / (SY**2)
          SA = SA + RA(K, IND) * SZ
          SB = SB + SZ
        END DO
C * CALCULATE AVERAGE INTENSITY
        RM  = SA  / SB
        IRM = NINT (RM)
        IF (IPR(408) /= 1) THEN
          SM0 = 1.0 / SQRT(SB)
C * SIGI(I) = SQRT(I) FOR GENERATED DATA (IPR(408) = 1)
        ELSE
          SM0 = SQRT (RM)
        END IF
        ISM = NINT (SM0)
C * CHECK FOR NON SPACEGROUP ABCENT REFLECTION
        IF (IKS(IND3) >= 0 .AND. JP > 1) THEN
          DO K = 1, JP
            IPR(755)   = IPR(755) + 1
            DEL        = ABS (ABS (RA(K, IND)) - ABS (RM))
            SM(1, IND) = SM(1, IND) + DEL
            SM(2, IND) = SM(2, IND) + RA(K, IND)
          END DO
        END IF
        IF (IND /= 1) THEN
          DO MM = 1, 3
            IHKLE(MM) = - IHKL(MM)
          END DO
        END IF
        ILT = 1
        IF (RM < PAR(284) * SM0) ILT = 2
        IF (IKS(IND3) /= -1) THEN
          IDSM = '*'
C * DISPLAY INTENSITY OR FREQUENCY
          IF (IPR(468) == 0) THEN
            IF (SM0 /= 0.0) THEN
              NDC = NINT (RM / SM0)
            ELSE
              NDC = 10
            END IF
          ELSE
            NDC = JP
          END IF
          IF (NDC < 10) IDSM = CHAR (ICHAR ('0') + NDC)
          IF (ILT == 2) THEN
            IF (IPR(468) == 0) IDSM = 'L'
            IPR(374 + IND) = IPR(374 + IND) + 1
          END IF
        END IF
        IF (IABS (IPR(392) - 2) == 1 .OR. IKS(IND3) == -1) THEN
          DO JPA = 1, JP, 2
            JPB = JPA + 1
            IF (JPB > JP) JPB = JP
            LPAB = 0
            DO K = JPA, JPB
              LPAB = LPAB + 1
              IRAB(LPAB, 1) = NINT (RA(K, IND))
              IRAB(LPAB, 2) = NINT (RB(K, IND))
            END DO
            IF (IPR(408) /= 2) THEN
              WRITE (XAR, 99999, IOSTAT = IOST)
     1          (IRAB(K, 1), IRAB(K, 2), K = 1, LPAB)
              AR(IPL) = XAR
              IF (JPA == 1) WRITE (XAR, 99997, IOSTAT = IOST)
     1          (IHKLE(MM), MM = 1, 3), IRM, ISM, ILT
              AR(IPL)(1:30) = XAR(1:30)
              IPL = IPL + 1
              IF (IPL > 102) THEN
                IPL = 1
C * NO PRINT FOR VALIDATION RUN
                IF (IGBL(22) /= -1) THEN
                  CALL PLA262 (0)
                  WRITE (LU7, 99998, IOSTAT = IOST)
                  WRITE (LU7, 99995, IOSTAT = IOST)
     1              (AR(I), AR(I + 51), I = 1, 51)
                END IF
              END IF
            END IF
          END DO
        END IF
        IF (IKS(IND3) /= -1) THEN
C * IPR(377) & IPR(378) COUNTS
          IPR(376 + IND) = IPR(376 + IND) + 1
          IF (ILT == 1) THEN
            IF (IND == 1) THEN
              IPR(383) = IPR(383) + 1
            ELSE
              IPR(362) = IPR(362) + 1
            END IF
          END IF
          IF (IPR(408) < 2) THEN
            IF (IPR(408) == 1 .AND. IRM == 0) ISM = 1
            IF (LPUN > 0) THEN
              IH = IHKLE(1)
              IK = IHKLE(2)
              IL = IHKLE(3)
              IF (IPR(700) == 0) THEN
                WRITE (LPUN, 99996, IOSTAT = IOST) IH, IK, IL,
     1            MIN (IRM, 99999999), ISM
              ELSE
                ACAL   = 0
                BCAL   = 0
                ACALA  = 0.0
                BCALA  = 0.0
                ACALAF = 0.0
                BCALAF = 0.0
                CALL PLA137 (IH, IK, IL, ACAL, BCAL, ACALA,
     1            BCALA, ACALAF, BCALAF, SNTHA)
                WRITE (LPUN, 99994, IOSTAT = IOST)
     1                  IH, IK, IL, ACAL, BCAL
              END IF
            END IF
C * EXPAND DATASET TO P-1
            IF (IPR(408) < 0) THEN
              IF (NSYMH > 1) THEN
                DO I = 1, 3
                  SGX(I)      = IHKLE(I)
                  IHKLS(I, 1) = IHKLE(I)
                END DO
                SGX(4) = 0.0
                N     = 1
                DO 20 I = 2, NSYMH
                  CALL SGSM (5, ICRD, SGX, I, LU7, IERR)
                  DO J = 1, 3
                    IHKLS(J, N + 1) = NINT (SGX(J + 6))
                  END DO
                  DO K = 1, N
                    IF (IHKLS(1, K) == IHKLS(1, N + 1)) THEN
                      IF (IHKLS(2, K) == IHKLS(2, N + 1)) THEN
                        IF (IHKLS(3, K) == IHKLS(3, N + 1)) GO TO 20
                      END IF
                    END IF
                    IF (IHKLS(1, K) == - IHKLS(1, N + 1)) THEN
                      IF (IHKLS(2, K) == - IHKLS(2, N + 1)) THEN
                        IF (IHKLS(3, K) == - IHKLS(3, N + 1))
     1                    GO TO 20
                      END IF
                    END IF
                  END DO
                  N = N + 1
                  IF (LPUN > 0) THEN
                    IH = IHKLS(1, N)
                    IK = IHKLS(2, N)
                    IL = IHKLS(3, N)
                    WRITE (LPUN, 99996, IOSTAT = IOST)
     1                IH, IK, IL, IRM, ISM
                  END IF
   20           CONTINUE
              END IF
            END IF
          END IF
        END IF
      END IF
      IF (IHU > 0 .AND. IHU <= NP44) THEN
        CID(IHU:IHU) = IDSM
        IF (IDSM /= '+' .AND. IDSM /= '-') THEN
          STHK = GEN095 (PAR(191), IHKLE(1), IHKLE(2), IHKLE(3))
        END IF
      END IF
      RETURN
99999 FORMAT (28X, 2(I9, I7))
99998 FORMAT (
     1 '   H  K  L     <I>   <SIG> ILT     I  &  SIG       I  &  SIG',
     2 15X,
     3 'H  K  L     <I>   <SIG> ILT     I  &  SIG       I  &  SIG', /,
     4 132('-'))
99997 FORMAT (1X, 3I3, I9, I7, I2)
99996 FORMAT (3I4, 2I8, 3X, '1')
99995 FORMAT (A, 12X, A)
99994 FORMAT (3I4, 2F10.2)
      END SUBROUTINE PLA146
 
      SUBROUTINE PLA147 (LEV)
C * ASYM (3) - SHOW RECIPROCAL LATTICE IN GRAPHICAL WINDOW
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE mentry
      USE cggt
      USE reflex
      USE asym
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NK
      INTEGER :: NL
      INTEGER :: NS
      INTEGER :: LEV
      INTEGER :: JMX
      INTEGER :: NCOL
      INTEGER :: ISTH
      INTEGER :: JMAX
      REAL :: CR
      REAL :: CX
      REAL :: CY
      REAL :: TH
      REAL :: CYS
      REAL :: CXH
      REAL :: CXS
      REAL :: CXV
      REAL :: CYV
      REAL :: STL
      REAL :: TH25
      REAL :: THOR
      REAL :: YDUM
      REAL :: STPA
      REAL :: STPB
      REAL :: SVER
      REAL :: SCA1
      REAL :: SCA2
      REAL :: SCAL
      REAL :: SHFT
      REAL :: SHOR
      REAL :: STEP
      REAL :: STHK
      REAL :: STHL
      REAL :: ANG1
      REAL :: ANG2
      REAL :: ANG3
      REAL :: ACAL
      REAL :: BCAL
      REAL :: CALC
      REAL :: CHOR
      REAL :: ACALA
      REAL :: BCALA
      REAL :: SNTHA
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN095
      CHARACTER(len=1) :: THFL
      JMAX = 0
      SHOR = 0.0
      STEP = 0.0
      STPA = 0.0
      STPB = 0.0
      SVER = 0.0
      CHOR = 0.0
      SCAL = 0.0
      TH25 = MIN (ASIN  (0.6 * PAR(17)) * RGBL(6), PAR(446))
C * CHECK FOR ASYM VIEW MODE (1)
      IF (IGBL(22) > 0) THEN
        IGBL(6) = 14
        CALL GGIP (HORS, VERT, 0.0, 1)
        CALL GGIP (0.0, 1.0, 0.0, 0)
        CALL PLA110 (HORS, VERT, -1)
C * REPORT ON PARAMETER & REFLECTION INPUT FILES
        IF (IPR(406) == 1) THEN
          KNMXT = KNMFIL + KXT + 1
          WRITE (PRBUF, 99989, IOSTAT = IOST)
     1      FNLU1(1:KNMXT), DTYPE(IABS (IGBL(8)))
          CALL PLA439 (0.0,  PRBUF, KNMXT + 8, 0.3, -1, 2, 17.0, 1.0)
          IF (IPR(408) <= 0) THEN
            WRITE (PRBUF, 99989, IOSTAT = IOST) FNLU16(1:KNM16),
     1      RDTYP(IGBL(9))
            CALL PLA439 (0.0,  PRBUF, KNM16 + 8, 0.3, -1, 2, 17.0, 0.2)
          ELSE
            WRITE (PRBUF, 99988, IOSTAT = IOST)
            CALL PLA439 (0.0, PRBUF, 14, 0.3, -1, 2, 17.0, 0.2)
          END IF
          THOR = VERT + 2.5
          IF (IPR(275) == 1) THEN
            IF (IPR(393) == 1) THEN
              WRITE (PRBUF, 99991, IOSTAT = IOST)
            ELSE
              WRITE (PRBUF, 99990, IOSTAT = IOST)
            END IF
            CALL PLA439 (0.0, PRBUF, 18, 0.3, 2, 2, VERT + 1.9,
     1                   VERT - 0.8)
          END IF
          IF (IPR(132) ==  0) THEN
            WRITE (PRBUF, 99997, IOSTAT = IOST) ' Iobs Data'
          ELSE IF (IPR(132) == 1) THEN
            WRITE (PRBUF, 99997, IOSTAT = IOST) ' Icalc Data'
          ELSE IF (IPR(132) == 2) THEN
            WRITE (PRBUF, 99997, IOSTAT = IOST)
     1        'abs(Iobs-Icalc)/sig(Iobs)'
          ELSE IF (IPR(132) == 3) THEN
            WRITE (PRBUF, 99997, IOSTAT = IOST)
     1        'Pos(Iobs-Icalc)/sig(Iobs)'
          END IF
          CALL PLA439 (0.0, PRBUF, 36, 0.3, 2, 2, 1.6 , 0.9)
          WRITE (PRBUF, 99987, IOSTAT = IOST) 'SpaceGr ', SPGRNM(1)(1:7)
          CALL PLA439 (0.0, PRBUF, 15, 0.3, 1, 2, THOR, VERT - 1.5)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'a      ', PAR(101)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 2.0)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'b      ', PAR(102)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 2.5)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'c      ', PAR(103)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 3.0)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'alpha  ', PAR(104)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 3.5)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'beta   ', PAR(105)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 4.0)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'gamma  ', PAR(106)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 4.5)
          WRITE (PRBUF, 99984, IOSTAT = IOST) 'lambda ', PAR(17)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 5.0)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'Th(min)', PAR(445)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 5.5)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'Th(max)', PAR(446)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 6.0)
          WRITE (PRBUF, 99996, IOSTAT = IOST) 'SigOmit', PAR(284)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 6.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST)   'Total  ', IPR(373)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 7.0)
          WRITE (PRBUF, 99995, IOSTAT = IOST)   'Unique ', IPR(377)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 7.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST)   'Obsd   ', IPR(383)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, VERT - 8.0)
        END IF
C * RECIPROCAL LAYER PLOTS
        ANG1 = ACOS (PAR(115 + IND1))
        ANG2 = ACOS (PAR(115 + IND2))
        ANG3 = ACOS (PAR(115 + IND3))
        SHOR = PAR(112 + IND1)
        STEP = 1.0 / PAR(100 + IND3)
        STPA = PAR(112 + IND3) *  COS (ANG2)
        STPB = PAR(112 + IND3) * (COS (ANG1) - COS (ANG2) * COS (ANG3))
     1                         /  SIN (ANG3)
        SVER = PAR(112 + IND2) *  SIN (ANG3)
        CHOR = PAR(112 + IND2) *  COS (ANG3)
C * GET SCALE FACTOR
        SHFT = 0.8
        SCA1 = (VERT - 1.0) /
     1         (PAR(112 + IND2) * SIN (ANG3) * (IHM(IND2) * 2 + 4))
        SCA2 = (VERT - SHFT) /
     1         (PAR(112 + IND1) * (IHM(IND1) * 2 + 1))
        SCAL = MIN (SCA1, SCA2)
        SVER = SVER * SCAL
        SHOR = SHOR * SCAL
        CHOR = CHOR * SCAL
        STEP = STEP * SCAL
        STPA = STPA * SCAL
        STPB = STPB * SCAL
      END IF
      CALL GEN108 (LU14, 0)
      DO
        READ (LU14, 99997, IOSTAT = IOST) CID
        IF (IOST == -1) GO TO 10
        IF (CID(1:4) == 'ZONE') THEN
          READ (CID(11:15), 99994) NL
          IF (NL > NP63 - 1) THEN
            WRITE (6, 99981) NP63
            STOP
          END IF
          IF (NL == LEV) EXIT
        END IF
      END DO
      IKS(IND3) = NL
      IPR(382)  = MAX (IPR(382), NL)
C * Zone
      WRITE (CID(16:29), 99993, IOSTAT = IOST) IHM(IND3)
      IF (IGBL(22) >= 0) THEN
        HRT = SHFT
        VRT = VERT - 0.4
        CALL PLA439 (0.0, CID, 29, 0.2, -1, 1, HRT, VRT)
      END IF
      READ (LU14, 99997, IOSTAT = IOST) CID
      IF (IOST == -1) GO TO 10
      NS = - IHM(IND2)
      READ (LU14, 99997, IOSTAT = IOST) CID
      IF (IOST == -1) GO TO 10
C * GET/PLOT HORIZONTAL INDEX MARKERS
      IF (IGBL(22) >= 0) THEN
        VRT = VRT - SVER
        CALL PLA439 (0.0, CID(1:5), 5, 0.2, -1, 1, HRT, VRT)
        HRT = HRT + 1.45 + SHOR + NS * CHOR
        DO I = 11, NP44, 2
          IF (HRT > (SHFT + 1.0)) THEN
            CALL PLA439 (0.0, CID(I:I), 1, 0.2, -1, 1, HRT, VRT)
          END IF
          HRT = HRT + SHOR
        END DO
      END IF
C * GET DOWN INDEX LABEL
      READ (LU14, 99997, IOSTAT = IOST) CID
      IF (IOST == -1) GO TO 10
      IF (IGBL(22) >= 0) THEN
C * PLOT DOWN INDEX LABEL
        VRT = VRT - SVER
        CALL PLA439 (0.0, CID, 15, 0.2, -1, 2, SHFT, VRT)
C * PLOT AXES
        CX  = SHFT + 1.5 +
     1        (IHM(IND1) + 1) * SHOR + (NS + IHM(IND2) + 1) * CHOR
        CY  = VRT - (IHM(IND2) + 1) * SVER
C * PLOT RESOLUTION CIRCLES
        IF (IPR(387) == 1) THEN
          CXS = CX - LEV * STPA
          CYS = CY + LEV * STPB
          JMAX = NINT(SIN(PAR(446) / RGBL(6)) / (PAR(17) * 0.05))
          DO J = 10, JMAX
            STL = J * 0.05
            IF (J == 12) THEN
              CALL GGIP (0.0, 2.0, 0.0, 0)
            ELSE
              CALL GGIP (0.0, 1.0, 0.0, 0)
            END IF
            CR = SCAL * 2.0 * STL
            CR = SQRT (MAX (0.0, CR**2 - (NL * STEP)**2))
C * PLOT CIRCLE
            CALL PLA289 (CXS, CYS, CR, 120)
          END DO
C * MINIMUM resolution CIRCLE
          IF (PAR(445) > 0.0) THEN
            STL = SIN(PAR(445) / RGBL(6)) / PAR(17)
            CALL GGIP (0.0, 5.0, 0.0, 0)
            CR = SCAL * 2.0 * STL
            CR = SQRT (MAX (0.0, CR**2 - (NL * STEP)**2))
C * PLOT CIRCLE
            CALL PLA289 (CXS, CYS, CR, 120)
          END IF
        END IF
C * PLOT AXES
        IF (IPR(388) == 1) THEN
          CALL GGIP (0.0, 5.0 + IGBL(68), 0.0, 0)
          CXV  = CX + IHM(IND2) * CHOR
          CYV  = CY - IHM(IND2) * SVER
          CXH  = CX + IHM(IND1) * SHOR
          CALL GGIP (CXV, CYV, 0.0, 3)
          CALL GGIP (CX,  CY,  0.0, 2)
          CALL GGIP (CXH, CY,  0.0, 2)
          CALL GGIP (CX,  CY,  0.0, 3)
          CALL GGIP (0.0, 1.0, 0.0, 0)
          CXV  = CX - IHM(IND2) * CHOR
          CYV  = CY + IHM(IND2) * SVER
          CXH  = CX - IHM(IND1) * SHOR
          CALL GGIP (CXV, CYV, 0.0, 3)
          CALL GGIP (CX,  CY,  0.0, 2)
          CALL GGIP (CXH, CY,  0.0, 2)
          CALL GGIP (CX,  CY,  0.0, 3)
        END IF
      END IF
C * READ BLANK LINE
      READ (LU14, 99997, IOSTAT = IOST) CID
      IF (IOST == -1) GO TO 10
      DO
        READ (LU14, 99997, IOSTAT = IOST) CID
        IF (IOST == -1) GO TO 10
        IF (CID(1:4) == 'ZONE') THEN
          GO TO 20
        ELSE
          NS = NS + 1
C * ONE STEP DOWN
          IF (IGBL(22) >= 0) THEN
            VRT = VRT - SVER
            CALL GGIP (0.0, 1.0, 0.0, 0)
          END IF
          READ (CID(1:4), 99992) NK
          IKS(IND2) = NK
          IF (IGBL(22) >= 0) THEN
            CALL PLA439 (0.0, CID(1:5), 5 + IGBL(68), 0.2, -1, 1, SHFT,
     1                   VRT)
            HRT = SHFT + 1.5 + SHOR + NS * CHOR
          END IF
          IKS(IND1) = - IHM(IND1) - 1
          DO I = 11, NP44, 2
            IF (IT(NL + 1) == 0) THEN
              IKS(IND1) = IKS(IND1) + 1
              IF (CID(I:I) == 'E') THEN
                IF (IPR(776) == 0) CID(I:I) = ' '
                IPR(385) = IPR(385) + 1
              END IF
              IF (CID(I + 1:I + 1) /= ' ' .AND. CID(I + 1:I + 1) /= '-'
     1            .AND. CID(I + 1:I + 1) /= '#') THEN
                IPR(390) = IPR(390) + 1
                IF (CID(I + 1:I + 1) == '?') THEN
                  IPR(391) = IPR(391) + 1
                END IF
              END IF
              IF (CID(I:I) /= ' ' .AND. CID(I:I) /= '+'
     1            .AND. CID(I:I) /= '#') THEN
                STHK = GEN095 (PAR(191), IKS(1), IKS(2), IKS(3))
                STHL = SQRT (STHK)
C * HANDLE MISSING REFLECTIONS
                IF (CID(I:I) == '?') THEN
                  IPR(386) = IPR(386) + 1
C * NO PRINT FOR VALIDATION RUN
                  IF (IGBL(22) /= -1) THEN
                    IF (IPR(386) == 1) THEN
                      CALL PLA262 (0)
                      WRITE (LU7, 99999, IOSTAT = IOST)
     1                  MIN (0.6, PAR(446))
                      CALL PLA262 (3)
                    END IF
                    CALL PLA262 (1)
                    WRITE (LU7, 99998, IOSTAT = IOST)
     1                IPR(386), IKS(1), IKS(2), IKS(3), STHL
                  END IF
C * TEST FOR NON-HKLF 2
                  IF (IPR(648) /= 2) THEN
                    TH = ASIN (STHL * PAR(17)) * RGBL(6)
C * CHECK FOR MISSING REFLECTION BELOW DATASET  TH(MIN) (= PAR(445))
                    IF (TH < PAR(445)) THEN
                      IPR(553) = IPR(553) + 1
                      IF (IPR(553) <= NP79) THEN
                        DO J = 1, 3
                          NTHMN(J, IPR(553)) = IKS(J)
                        END DO
                      END IF
                    ELSE IF (TH > TH25) THEN
                      IPR(557) = IPR(557) + 1
                    ELSE
C * CHECK FOR MISSING REFLECTIONS BETWEEN Sin(ThMin) AND MIN(SinThmax, 0.6)
                      IPR(555) = IPR(555) + 1
                      IF (IPR(555) <= NP80) THEN
                        DO J = 1, 3
                          NTHMX(J, IPR(555)) = IKS(J)
                        END DO
                      END IF
                    END IF
                  END IF
                  IF (IGBL(22) == 1) THEN
                    NMISS = NMISS + 1
                    IF (NMISS == 1) WRITE (LU6, 99979)
                    WRITE (LU6, 99980) NMISS, IKS(1), IKS(2), IKS(3), TH
                  END IF
                  IF (TH <= TH25) THEN
                    ACAL   = 0.0
                    BCAL   = 0.0
                    ACALA  = 0.0
                    BCALA  = 0.0
                    ACALAF = 0.0
                    BCALAF = 0.0
                    CALL PLA137 (IKS(1), IKS(2), IKS(3), ACAL, BCAL,
     1                ACALA, BCALA, ACALAF, BCALAF, SNTHA)
                    CALC = (ACAL + ACALA) ** 2 + (BCAL + BCALA) ** 2
                    IF (IGBL(22) < 0) THEN
                      NHEAD = NHEAD + 1
                      IF (NHEAD == 1) WRITE (LU13, 99999, IOSTAT = IOST)
     1                  MIN (0.6, PAR(446))
                      IF (TH < PAR(445)) THEN
                        THFL = '*'
                      ELSE
                        THFL = ' '
                      END IF
                      IF (CALIM > 0.0) THEN
                        IF (CALC / CALIM > 1.0) THEN
                          IPR(584) = IPR(584) + 1
                          IF (IPR(584) <= NP84) THEN
                            DO J = 1, 3
                              NSTRM(J, IPR(584)) = IKS(J)
                            END DO
                          END IF
                        END IF
                        WRITE (LU13, 99998, IOSTAT = IOST)
     1                    NHEAD, IKS(1), IKS(2), IKS(3), STHL, TH, THFL,
     2                    CALC, CALC / CALIM
                      END IF
                    END IF
                  END IF
                END IF
                IPR(384) = IPR(384) + 1
                ISTH     = INT (STHL * 20.0) - 8
                DO J = 1, 20
                  IF (ISTH <= J .AND. CID(I:I) /= 'E') THEN
                    ICNT(J, 1) = ICNT(J, 1) + 1
                    IF (CID(I:I) /= '?') ICNT(J, 2) = ICNT(J, 2) + 1
                  END IF
                END DO
              END IF
            END IF
            IF (IGBL(22) >= 0) THEN
              IF (CID(I:I) == '*') THEN
                NCOL = 2
              ELSE IF (CID(I:I) == 'L') THEN
                NCOL = 4
              ELSE IF (CID(I:I) == 'E') THEN
                IF (IPR(776) == 0) CID(I:I) = ' '
                NCOL = 1
              ELSE IF (CID(I:I) == '+') THEN
                NCOL = 1
              ELSE IF (CID(I:I) == '?') THEN
                NCOL = 5 + IGBL(68)
              ELSE IF (CID(I:I) == '#') THEN
                NCOL = 5 + IGBL(68)
              ELSE
                IF (IPR(468) == 0 .OR. CID(I:I) == '1') THEN
                  NCOL = 3
                ELSE
                  NCOL = 2
                END IF
              END IF
              IF (IPR(369) /= 0) THEN
                IF (CID(I:I) /= '?' .AND. CID(I:I) /= '#'
     1              .AND. CID(I:I) /= ' ') THEN
                  NCOL = 4
                  CID(I:I) = '.'
                END IF
              END IF
              CALL PLA439 (0.0, CID(I:I), 1, 0.2, NCOL, 1, HRT - 0.1,
     1                     VRT - 0.1)
C * ADD 1 STEP TO THE RIGHT
              HRT = HRT + SHOR
            END IF
          END DO
        END IF
      END DO
   10 IF (NHEAD > 0) THEN
C * ACTUAL THETA-MIN FROM HKL/FCF
        WRITE (LU13, 99983, IOSTAT = IOST) MAX (0.0, PAR(445))
C * THETA-MIN FROM CIF
        IF (PAR(167) > 0.0)
     1    WRITE (LU13, 99982, IOSTAT = IOST) PAR(167)
      END IF
      CALL GEN108 (LU14, 0)
      LEV = -1
   20 IT (NL + 1) = 1
      IF (IPR(406) == 1) THEN
        IF (IGBL(22) >= 0) THEN
          PRBUF = 'Resol Perc'
          CALL PLA439 (0.0, PRBUF(1:10), 10, 0.3, 2, 2, THOR, 1.6)
        END IF
        DO I = 10, JMAX
          IF (I < 20) THEN
            IF (I == 12) THEN
              NCOL = 2
            ELSE
              NCOL = 1
            END IF
            IF (ICNT(I - 9, 1) /= 0) THEN
              YDUM = ICNT(I - 9, 2) * 100.0 / ICNT(I - 9, 1)
            ELSE
              YDUM = 0.0
            END IF
            IF (IGBL(22) >= 0) THEN
              WRITE (PRBUF, 99986, IOSTAT = IOST) I * 0.05, YDUM
              CALL PLA439 (0.0, PRBUF(1:10), 10, 0.3, NCOL, 2, THOR,
     1                    (I - 6) * 0.5)
            END IF
          END IF
        END DO
        IF (IGBL(22) >= 0) THEN
          JMX = MIN (JMAX, 20) + 1
          WRITE (PRBUF, 99985, IOSTAT = IOST) 'Layer 0 -', IPR(382)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 2, 2, THOR, JMX * 0.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST) 'SpGrExt', IPR(385)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 4, 2, THOR, (JMX - 1) * 0.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST) 'MaxUniq', IPR(384)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, (JMX - 2) * 0.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST) 'Missing', IPR(386)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 5 + IGBL(68), 2, THOR,
     1                 (JMX - 3) * 0.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST) 'N eq 1 ', IPR(637)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, (JMX - 4) * 0.5)
          WRITE (PRBUF, 99995, IOSTAT = IOST) 'N gt 1 ', IPR(638)
          CALL PLA439 (0.0, PRBUF, 13, 0.3, 1, 2, THOR, (JMX - 5) * 0.5)
          CALL GGIP (0.0, 1.0, 0.0, 0)
        END IF
      END IF
      RETURN
99999 FORMAT (/, 'Section 3', /, 79('='), /,
     1 'Missing Reflections (Asym. Refl. Unit)',
     2 ' below sin(th)/lambda =', F6.3, /, 79('='), /,
     3 '   Nr       H    K    L  sin(th)/lambda', 3X,
     4 'Theta', 8X, 'I(calc)', 2X, 'I(calc)/I(max)', /, 79('-'))
99998 FORMAT (I5, 3X, 3I5, F11.3, 6X, F7.2, A, F14.2, F13.5)
99997 FORMAT (A)
99996 FORMAT (A, F6.2)
99995 FORMAT (A, I6)
99994 FORMAT (I5)
99993 FORMAT (3X, '(Max =', I4, ')')
99992 FORMAT (I4)
99991 FORMAT ('Friedels Averaged ')
99990 FORMAT ('No Friedel Average')
99989 FORMAT (A, '-', A)
99988 FORMAT ('Generated Data')
99987 FORMAT (2A)
99986 FORMAT (F4.2, F6.1)
99985 FORMAT (A, I4)
99984 FORMAT (A, F6.4)
99983 FORMAT (/, '  ** Note: I(max) is the maximum I(obs) ',
     1        'encountered in the fcf-file **', //, 6X,
     2 'Starred Reflections have a Theta below Theta(Min) =', F6.2, /)
99982 FORMAT (35X, 'From CIF: Theta(Min) =', F6.2, /)
99981 FORMAT ('** Too Many Layers (Max =', I4, ') **')
99980 FORMAT (I5, ' : ', 3I5, F8.2)
99979 FORMAT (//, 6X, 'Missing Reflections', /, 3X, 'Nr', 7X, 'H', 4X,
     1        'K', 4X, 'L', 3X, 'THETA')
      END SUBROUTINE PLA147
 
      SUBROUTINE PLA148
 
C * ASYM (4)
      USE files
      USE parameters
      USE reflex
      USE sgxyz
      USE asym
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IASM
      REAL :: STHK
      REAL :: GEN095
      CHARACTER(len=80) :: LINE
      CALL GEN038 (CID, 1, NP44)
      N = 2 * IHM(IND1) + 1
      J = -1
      DO I = 1, N
        IKS(IND1) = - IHM(IND1) - 1 + I
        J = J + 2
        IF (IKS(IND3) == 0) THEN
          IF (IKS(IND2) < 0) THEN
            CYCLE
          ELSE IF (IKS(IND2) == 0) THEN
            IF (IKS(IND1) <= 0) CYCLE
          END IF
        END IF
        STHK = GEN095 (PAR(191), IKS(1), IKS(2), IKS(3))
        IF (STHK < ATHM) THEN
C * CHECK FOR LATTICE AND NON-LATTICE ABSENCES
          DO K = 1, 3
            SGX(K) = IKS(K)
          END DO
          SGX(12) = 0.0
          CALL SGSM (27, LINE, SGX, 0, 0, IERR)
          IF (NINT (SGX(12)) == 2) CYCLE
C * CHECK FOR IASM
          CALL PLA136 (0, IKS(1), IKS(2), IKS(3), IASM)
          IF (J > 0 .AND. J < NP44) THEN
            IF (NINT (SGX(12)) == 0) THEN
              IF (IASM == 1) THEN
                CID(J:) = ' ?'
              ELSE
                CID(J:) = ' #'
              END IF
            ELSE
              IF (IASM == 1) THEN
                IF (IPR(275) == 2 .OR. IPR(393) == 1) THEN
                  CID(J:) = ' E'
                ELSE
                  CID(J:) = 'EE'
                END IF
              END IF
            END IF
          END IF
        END IF
      END DO
      RETURN
      END SUBROUTINE PLA148
 
      SUBROUTINE PLA149
C * ASYM - HKL AVERAGING AND REFLECTION MULTIPLICITY REPORTING
      USE FILES
      USE PARAMETERS
      USE cchar
      IMPLICIT NONE
      REAL :: YUNK
C * COPY _sx.ins -> lasym.ins
      OPEN (UNIT = LU60, FILE = 'lasym.ins', STATUS = 'UNKNOWN',
     1  IOSTAT = IOST)
      REWIND (UNIT = LU24, IOSTAT = IOST)
      DO
        READ (LU24, 99999, IOSTAT = IOST) LINE
        IF (IOST /= 0) EXIT
        WRITE (LU60, 99999) LINE
      END DO
      CLOSE  (UNIT = LU60, IOSTAT = IOST)
C * COPY _sx.hkl -> lasym.hkl
      OPEN (UNIT = LU60, FILE = 'lasym.hkl', STATUS = 'UNKNOWN',
     1  IOSTAT = IOST)
      REWIND (UNIT = LU25, IOSTAT = IOST)
      DO
        READ (LU25, 99999, IOSTAT = IOST) LINE
        IF (IOST /= 0) EXIT
        WRITE (LU60, 99999) LINE
      END DO
      CLOSE (UNIT = LU60, IOSTAT = IOST)
      KERR = 0
C * SPAWN PLATON/ASYM JOB
      IF (DOS) THEN
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -o -l2 '//
     1    ' +0lasym.log lasym.ins', LU6, .true., KERR)
      ELSE
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -o -l2 '//
     1    'lasym.ins > lasym.log', LU6, .true., KERR)
      END IF
      IF (KERR /= 0) WRITE (6, 99997)
C * REMOVE lasym.ckf
      OPEN (UNIT = LU60, FILE = 'lasym.ckf',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      CLOSE (UNIT = LU60, STATUS = 'DELETE', IOSTAT = IOST)
C * REMOVE lasym.ins
      OPEN (UNIT = LU60, FILE = 'lasym.ins',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      CLOSE (UNIT = LU60, STATUS = 'DELETE', IOSTAT = IOST)
C * REMOVE lasym.hkl
      OPEN (UNIT = LU60, FILE = 'lasym.hkl',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      CLOSE (UNIT = LU60, STATUS = 'DELETE', IOSTAT = IOST)
C * GET AVERAGE MULTIPLICITY FROM lasym.log
      OPEN (UNIT = LU60, FILE = 'lasym.log', STATUS = 'old',
     1  IOSTAT = IOST)
      PAR(558) = 0.0
      DO
        READ  (LU60, 99999, IOSTAT = IOST) ICL(1:41)
        IF (IOST /= 0) EXIT
        IF (ICL(1:4) == 'Aver') THEN
          READ (ICL(36:41), 99998, IOSTAT = IOST) PAR(558)
          EXIT
        END IF
      END DO
C * ALERT _941 - REPORT LOW HKL MULTIPLICITY
      YUNK = 5.0 - PAR(558)
      IF (YUNK > 0.0 .AND. PAR(558) /= 0.0)
     1  CALL PLA236 (941, 1, -999.0, PAR(558), ' ', ' ')
        CLOSE (UNIT = LU60, STATUS = 'DELETE', IOSTAT = IOST)
C * LOWER THE NUMBER OF REQUESTED TASKS
      IPR(121) = IPR(121) - 1
      RETURN
99999 FORMAT (A)
99998 FORMAT (F7.1)
99997 FORMAT (/, '*** SPAWNING OF PLATON/ASYM JOB FAILED ****', /,
     1           '*** CHECK WHETHER PLATON IS ACCESSIBLE/EXECUTABLE', /)
      END SUBROUTINE PLA149
 
      MODULE exor
      SAVE
      INTEGER, PARAMETER          :: MP3 = 1000
      INTEGER, DIMENSION(MP3, 40) :: ICON
      INTEGER, DIMENSION(MP3)     :: NCON
      REAL,    DIMENSION(84)      :: F
      REAL,    DIMENSION(1616)    :: SFC
      REAL,    DIMENSION(MP3, 46) :: PEAK
      REAL,    DIMENSION(5001, 2) :: RCURVE
      END MODULE exor
 
      SUBROUTINE PLA151 (MODE)
C * SETUP EXOR.BIN/EXOR (1)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE spgrdata
      USE fab
      USE exor
      USE sgxyz
      IMPLICIT NONE
 
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: L0
      INTEGER :: N0
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: MF
      INTEGER :: MR
      INTEGER :: NE
      INTEGER :: NM
      INTEGER :: NO
      INTEGER :: NI
      INTEGER :: NJ
      INTEGER :: NK
      INTEGER :: NS
      INTEGER :: NT
      INTEGER :: NPK
      INTEGER :: NEK
      INTEGER :: NAT
      INTEGER :: ISW
      INTEGER :: MPM
      INTEGER :: NUMS
      INTEGER :: NPKM
      INTEGER :: NPRV
      INTEGER :: NEL0
      INTEGER :: NDIF
      INTEGER :: NATR
      INTEGER :: MDIP
      INTEGER :: KEEP
      INTEGER :: JMAX
      INTEGER :: IAN0
      INTEGER :: IBVT
      INTEGER :: MODE
      INTEGER :: NRSH
      INTEGER :: LOOP
      INTEGER :: NSYM
      INTEGER :: NSYMH
      INTEGER :: NSTAR
      INTEGER :: NRNEW
      INTEGER :: LATTS
      INTEGER :: ICNT3
      INTEGER :: IHMAX
      INTEGER :: IHMIN
      INTEGER :: IKMAX
      INTEGER :: IKMIN
      INTEGER :: ILMAX
      INTEGER :: ILMIN
      INTEGER :: IRMIN
      INTEGER :: KNOWN
      INTEGER, DIMENSION(NP10) :: IA
      INTEGER, DIMENSION(NP10) :: MCONT
      REAL :: P
      REAL :: Q
      REAL :: R
      REAL :: S
      REAL :: T
      REAL :: U
      REAL :: V
      REAL :: W
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: U1
      REAL :: Q1
      REAL :: QS
      REAL :: EE
      REAL :: GA
      REAL :: GD
      REAL :: HB
      REAL :: SS
      REAL :: UT
      REAL :: X1
      REAL :: Y1
      REAL :: Z1
      REAL :: EKW
      REAL :: QSMX
      REAL :: STLM
      REAL :: TEMP
      REAL :: HGHT
      REAL :: CALI
      REAL :: CENT
      REAL :: CRIT
      REAL :: DELT
      REAL :: DIST
      REAL :: FACT
      REAL :: PMAX
      REAL :: RSHN
      REAL :: XPEAK
      REAL :: UCINT
      REAL :: THMAX
      REAL :: THMIN
      REAL :: SIGIW
      REAL :: PHMIN
      REAL :: EXPMX
      REAL :: DELTA
      REAL :: CRIT0
      REAL :: ACALS
      REAL :: BCALS
      REAL :: RATIO
      REAL :: PICKUP
      REAL :: BONDIJ
      REAL :: GEN049
      REAL :: GEN050
      REAL :: GEN095
      REAL, DIMENSION(84)   :: E
      REAL, DIMENSION(52)   :: G
      REAL, DIMENSION(NP10) :: DA
      CHARACTER(len=4)  :: LABI
      CHARACTER(len=2)  :: ATTP
      CHARACTER(len=50) :: STAR
C * MODE =  0 - SETUP/PATTERSON
C * MODE >  0 - EXOR
C * MODE = -1 - FLIPPER
      IWIN  = 0
      S     = 0
      NSYM  = IPR(48)
      NSYMH = IPR(255)
      CENT  = 2 - IPR(257)
      IBVT  = IPR(241)
      LATTS = IPR(256) * IPR(257)
      ISW   = 5
      KEEP  = 1
      STLM  = 0.6
      QSMX  = STLM **2
C * MANAGE MENU (ON/OFF)
      IGBL(63) = 0
      IF (IPR(220) > 1) THEN
        IF (IFL(2)(1:4) == 'AUTO') IGBL(25) = 0
      END IF
      IF (IGBL(25) * IGBL(32) == 1 .AND. IGBL(50) == 0) IWIN = 1
C * SETUP-MODE PARAMETERS
      IF (MODE == 0) THEN
        IPR(525) = 0
        IF (IPR(220) > 1) THEN
          DO I = 2, IPR(220)
            IF (IFL(I)(1:4) == 'PATT') THEN
              IPR(525) = 1
            ELSE IF (IFL(I)(1:4) == 'PATR') THEN
              IPR(525) = -1
            END IF
          END DO
        END IF
        IF (FN(1) /= 0) IPR(548) = 1
C * FLIPPER SETUP MODE
      ELSE IF (MODE == -1) THEN
        IPR(525) =  0
        CENT     =  0
        ISW      = -5
C * ISW EXOR MODE
      ELSE
C * CALL EXIT/STOP
        IF (IPR(37) > MP3) CALL GEN127 ('MEMORY (MP3) PROBLEM')
C * EXOR-MODE PARAMETERS
C * OMIT CRITERIUM
        IF (FN(1) >  0.0) PAR(284) = FN(1)
C * SINTH/LAMBDA MIN
        IF (FN(2) >= 0.0) PAR(281) = FN(2)
C * SINTH/LAMBDA MAX
        IF (FN(3) >  0.0) PAR(282) = FN(3)
C * STOP CRITERIUM
        IF (FN(4) >  0.0) PAR(283) = FN(4)
C * NUMBER OF CYCLES
        IF (FN(5) >  0.0) IPR(482) = NINT (FN(5))
C * NUMBER OF CYCLES
        IF (FN(6) /= 0.0) IPR(467) = NINT (FN(6))
        IGBL(31) = 6
C * PLATON/SYSTEM-S MODE
        IF (FN(7) /= 0.0) IPR(548) = 1
C * KEEP BIN
        KEEP = NINT (FN(8))
C * OPEN UNIT #2
        CALL PLA292
      END IF
C * GRAPHICS
      IF (IWIN == 1) THEN
C * SET MENU #
        IGBL(6)    = 27
        IGGT(2:21) = NAMEFIL(1:20)
C * GENERAL GRAPHICS OPEN
        CALL GGIP (-999.0, FLOAT (-KNMFIL), 0.0, 5)
        IF (MODE == 0) THEN
          IF (IPR(525) /= 0) THEN
            IF (IPR(548) == 1) BCD = 'S.Y.S.T.E.M - S'//CHAR (0)
            CALL GGIP (HORS, VERT, 0.0, 1)
            BCD = 'FO**2 - PATTERSON'//CHAR (0)
            CALL PLA439 (0.0,  BCD, 18, 1.0, 4, 6,  6.1, VERT - 1.5)
            CALL PLA439 (0.0,  BCD, 18, 1.0, 2, 6,  5.9, VERT - 1.6)
            CALL GGIP (0.0, 0.0, 0.0, 6)
            VRT = VERT - 1.8
          END IF
        ELSE IF (MODE == 1) THEN
          IF (IPR(548) == 1) BCD = 'S.Y.S.T.E.M - S'//CHAR (0)
          CALL GGIP (HORS, VERT, 0.0, 1)
          BCD = 'E.X.O.R'//CHAR (0)
          CALL PLA439 (0.0,  BCD, 7, 1.8, 4, 15, 1.7, VERT - 2.3)
          CALL PLA439 (0.0,  BCD, 7, 1.8, 2, 15, 1.5, VERT - 2.4)
        END IF
      END IF
C * BIN-SETUP/EXOR, SET 'LPS' OFF
      IGBL(70) = 0
C * CALCULATE CELL PARAMETERS
      CALL PLA100
C * SETUP SFAC TABLES
      ICNT3 = 3
C * CHECK FOR NON-RES DATA
      IF (IABS(IGBL(8)) /= 2 .AND. IPR(30) == 0) THEN
C * SETUP CONNECTED SET
        CALL PLA067
        IF (IPR(2) /= 0) RETURN
        CALL PLA073 (-1, 1)
        ICNT3   = 2
      END IF
      Z = 0.004 / PAR(17)**2
      L = 1
      DO I = 1, IAN
        N = IEN(I)
        L = L - 1
        W = 0.0
        DO N0 = 1, 51
          X = 0.0
          Y = 0.0
          DO K = 1, 6
            M = L + K
            SFC(M) = SFAC((N - 1) * 19 + 9)
            DO J = 1, 7, 2
              V = - SFAC((N - 1) * 19 + J + 1) * (W + X)
C * CHANGED FROM 87 TO 84 FOR UNDERFLOW PROTECTION
              IF (ABS(V) < 84.0) THEN
                SFC(M) = SFC(M) + SFAC((N - 1) * 19 + J) * EXP (V)
              END IF
            END DO
            X = X + Z
            Y = Y + SFC(M)
          END DO
          SFC(L + 2) = 1.25 * Y - 3.75 * (SFC(L + 1) + SFC(L + 6))
          L          = L + 2
          W          = W + 5.0 * Z
        END DO
      END DO
C * BIN-SETUP FOR EXOR
      IF (IGBL(16) == 0) THEN
C * REWIND BIN
        CALL GEN108 (LU19, 0)
C * GET DATA ON SYMMETRY
        MF = 1
C * SETUP/CONTENTS
        DO J = 1, 51
          G(J) = 0.0
          F(J) = 0.0
          M = 2 * J - 1
          DO K = 1, IAN
            Y    = SFC(M) * SFC(M) * CONT(K, ICNT3)
            G(J) = G(J) + Y
            F(J) = F(J) + Y * SFC(M)
            M    = M + 101
          END DO
        END DO
        WRITE (LU6, 99967, IOSTAT = IOST) PAR(17)
C * READ REFLECTION DATA, KEEP TRACK OF H, K, L, THETA MIN, MAX
        CALL GEN074 (VOID, 4, 6,  999.0)
        CALL GEN074 (VOID, 7, 9, -999.0)
        IPR(602) = 0
        IHMIN    =  999
        IKMIN    =  999
        ILMIN    =  999
        IHMAX    = -999
        IKMAX    = -999
        ILMAX    = -999
        THMAX    =  0.0
        THMIN    =  1.0
        IEND     = -1
        MR       = 0
        IH       = 0
        IK       = 0
        IL       = 0
C * READ H,K,L, F**2 , SIGMA(F**2), N
        DO
          CALL PLA132 (NI, NJ, NK, T, W, SIGIW, CALI, UCINT,
     1      ACALS, BCALS)
C * HANDLE HKLF-EXT (FROM SQUEEZE)
          IF (IGBL(9) == -1) T = UCINT
          K = 0
C * TEST FOR END OF DATA (H=0, K=0, L=0)
          IF (IEND == 0 .AND. ABS(NI) + ABS(NJ) + ABS(NK) /= 0) THEN
            IF (W <= 0.0) THEN
              IF (T <= 0.0) CYCLE
              W = SQRT (ABS(T))
            END IF
            IPR(602) = IPR(602) + 1
C * APPLY TRANSF.TION (IF ANY) AND ELIMINATE REFL WITH NON-INTEGRAL INDICES
            IF (GEN050 (TRMX, NI, NJ, NK, IH, IK, IL) >= 0.0) THEN
C * ELIMINATE BRAVAIS EXTINCTIONS
              IF (IBVT > 1) THEN
                IF (GEN049 (LAT(IBVT), IH, IK, IL) < 0) GO TO 10
              END IF
C * MULTIPLICITY
              U      = -9999999.0
              U1     = U
              P      = 0.0
              R      = 0.0
              SGY(1) = IH
              SGY(2) = IK
              SGY(3) = IL
              SGY(4) = 0.0
              DO N = 1, NSYMH
                CALL SGSM (ISW, LINE, SGY, N, 0, IERR)
                IF (MAX (ABS (SGY(7)), ABS (SGY(8))) >= 99.5) GO TO 10
                Q1 = SGY(7) + 200.0 * (SGY(8) + 200.0 * SGY(9))
                Q  = ABS (Q1)
                IF (CENT == 0) Q1 = Q
                IF (NINT (Q1) >= NINT (U1)) THEN
                  TEMP = SGY(10) / RGBL(6)
                  TEMP = COS (TEMP) + 21.42 * SIN (TEMP) * CENT
                  R = R + TEMP
                  IF (NINT (Q1) > NINT (U1)) THEN
                    R  = TEMP
                    U1 = Q1
                  END IF
                END IF
                IF (NINT (Q) >= NINT (U)) THEN
                  P = P + 1.0
                  IF (NINT (Q) > NINT (U)) THEN
                    P = 1.0
                    U = Q
                  END IF
                END IF
              END DO
              IF (ABS(R) >= 0.1) THEN
C * GET (SIN(TH)/Lambda)**2 FOR H,K,L
                QS = GEN095 (PAR(191), IH, IK, IL)
C * LIMIT TO SIN(THETA)/LAMBDA = 0.65 FOR FLIP
                IF (MODE == -1) THEN
                  IF (QS > QSMX) CYCLE
                END IF
C * UNPACK REFLECTION HKL
                CALL GEN046 (U, X1, Y1, Z1)
                IHMAX = MAX (IHMAX, IH)
                IKMAX = MAX (IKMAX, IK)
                ILMAX = MAX (ILMAX, IL)
                IHMIN = MIN (IHMIN, IH)
                IKMIN = MIN (IKMIN, IK)
                ILMIN = MIN (ILMIN, IL)
                VOID(7)  = MAX (VOID(7), X1)
                VOID(8)  = MAX (VOID(8), Y1)
                VOID(9)  = MAX (VOID(9), Z1)
                VOID(4)  = MIN (VOID(4), X1)
                VOID(5)  = MIN (VOID(5), Y1)
                VOID(6)  = MIN (VOID(6), Z1)
C * GET (SIN(TH)**2
                S     = QS * PAR(17)**2
                TEMP  = S * 50.0
                K     = INT (TEMP)
                IF (K > 50) GO TO 10
                THMAX = MAX (THMAX, S)
                THMIN = MIN (THMIN, S)
                TEMP  = MOD (TEMP, 1.0)
                EE    = SQRT ((TEMP * (G(K + 2) - G(K + 1)) + G(K + 1))
     1                  * P)
                IF (EE. NE. 0.0) EE = EXP (3.94784 * QS) / EE
C * STORE F(OBS) DATA
                V = T * 100.0
                W = W * 100.0
                IF (V < W) V = 0.5 * W
                V = SQRT (V)
                W = W / (2.0 * V)
C * PACKED H,K,L
                F(MF)     = U
C * F(OBS)
                F(MF + 1) = V
                IF (ABS (W) > 0.00001) THEN
                  F(MF + 2) = W**2
                ELSE
                  F(MF + 2) = 1.E-10
                END IF
C * STORE 8PI**2(SIN(TH)/LAMBDA)**2
                F(MF + 3) = RGBL(8) * QS
                F(MF + 4) = MIN (EE * V, 900.0)
                F(MF + 5) = 0.0
                MF        = MF + 6
                IF (MF > 79) THEN
                  WRITE (LU19) F
                  MF = 1
                END IF
                CYCLE
              END IF
            END IF
C * ERRORS IN REFLECTION DATA
   10       MR = MR + 1
            IF (MR == 1) WRITE (LU6, 99983, IOSTAT = IOST)
            IF (K > 50) THEN
              WRITE (LU6, 99980, IOSTAT = IOST) NI, NJ, NK, T, W, S
            ELSE
              WRITE (LU6, 99980, IOSTAT = IOST) NI, NJ, NK, T, W
            END IF
            CYCLE
          ELSE
            EXIT
          END IF
        END DO
        WRITE (LU6, 99994, IOSTAT = IOST) IPR(602), MR
        IF (IPR(602) == 0) GO TO 190
        THMIN = NINT (ASIN (SQRT (THMIN)) * 572.9578) / 10.0
        IF (THMAX > 1.0) THEN
          THMAX = 90.0
        ELSE
          THMAX = NINT (ASIN (SQRT (THMAX)) * 572.9578) / 10.0
        END IF
        WRITE (LU6, 99966) STLM
        WRITE (LU6, 99991, IOSTAT = IOST)
     1    IHMIN, IHMAX, IKMIN, IKMAX, ILMIN, ILMAX,
     1   THMIN, THMAX
        IPR(267) = IHMIN
        IPR(268) = IHMAX
        IPR(269) = IKMIN
        IPR(270) = IKMAX
        IPR(271) = ILMIN
        IPR(272) = ILMAX
        F(MF)    = 0.0
        WRITE (LU19) F
        CALL GEN108 (LU19, 1)
        HB = VOID(7) - VOID(4) + 1.0
        GD = VOID(8) - VOID(5) + 1.0
        GA = 1.0  - VOID(4) - HB * (VOID(5) + GD * VOID(6))
        NE = -5
        R  = 0.0
        S  = 0.0
        NM = 0
C * ZERO C
        CALL GEN074 (VOID, 1, NVDR, 0.0)
        NT  = 0
        MPM = NVDR - 8
        M   = MPM
C * SORT/MERGE
        DO
          READ (LU19) F
          DO I = 1, 79, 6
            IF (0.5 > ABS (F(I))) THEN
              CALL GEN108 (LU19, 0)
              IF (M == MPM) THEN
                DO K = 1, NT
                  IF (K + 10 > M) EXIT
                  IF (VOID(K) >= 1.0) THEN
                    M    = M - 8
                    VOID(K) = M + 1
                  END IF
                END DO
                CALL GEN074 (VOID, NT + 1, MPM, 0.0)
                M = NT
                EXIT
              END IF
              GO TO 20
            END IF
            CALL GEN046 (F(I), X, Y, Z)
            N = NINT (GA + X + HB * (Y + GD * Z))
            IF (N > 0 .AND. N <= M) THEN
              IF (M /= MPM) THEN
                N        = NINT (VOID(N))
                V        = F(I + 1)
                W        = 1.0 / F(I + 2)
                VOID(N + 1) = VOID(N + 1) + V * W
                VOID(N + 2) = VOID(N + 2) + W
                VOID(N + 3) = F(I + 3)
                VOID(N + 4) = VOID(N + 4) + F(I + 4) * W
                VOID(N + 6) = VOID(N + 6) + V * V * W
                VOID(N + 7) = F(I)
              ELSE
                NT = MAX (N, NT)
              END IF
              VOID(N) = VOID(N) + 1.0
            END IF
          END DO
        END DO
C * R-INDEX AND INCONSISTENCIES
   20   DO J = 1, NT
          M = NINT (VOID(J))
          IF (M /= 0) THEN
            NE        = NE + 6
            E(NE)     = VOID(M + 7)
            W         = 1.0 / VOID(M + 2)
            E(NE + 1) = VOID(M + 1) * W
            E(NE + 2) = W
            E(NE + 3) = VOID(M + 3)
            E(NE + 4) = MIN (900.0, VOID(M + 4) * W)
            E(NE + 5) = 0.0
            IF (NE >= 79) THEN
              WRITE (LU9) E
              NE = - 5
            END IF
            NM = NM + 1
            IF (void(M) > 1.0 .AND. VOID(M + 1) >= 1.E-8) THEN
              X = VOID(M + 2) * VOID(M + 6)
              Y = VOID(M + 1) **2
              S = S + W * X * (VOID(M) - 1.0)
              R = R + W * VOID(M) * (X - Y)
              IF (1.04 * Y <= X) THEN
                U = 1.0 / (SQRT (W) * VOID(M + 1))
                W = SQRT (ABS (X / Y - 1.0))
                N = NINT (VOID(M))
                CALL GEN046 (VOID(M + 7), X, Y, Z)
              END IF
            END IF
          END IF
        END DO
        E(NE + 6) = 0.0
        WRITE (LU9) E
        T = 0.0
        IF (S /= 0.0) T = SQRT (ABS (R / S))
        WRITE (LU6, 99985, IOSTAT = IOST) NM, T
        CALL GEN108 (LU9, 1)
C * NORMALISE E-VALUES
        L = 0
        CALL GEN074 (VOID, 1, 64, 0.0)
        CALL GEN074 (E, 1, 64, 0.0)
        DO M = 1, 2
   30     READ (LU9) F
          I = -5
          DO
            I = I + 6
            IF (0.5 <= ABS (F(I))) THEN
              X = 1.0 + SQRT (2.584724 * F(I + 3))
              K = MIN (14, INT (X))
              T = MIN (X - FLOAT (K), 1.0)
              W = F(I + 4)
              P = 1.0 - T
              IF (M == 1) THEN
                VOID(K)      = VOID(K)      + P * W**2
                VOID(K + 1)  = VOID(K + 1)  + T * W**2
                VOID(K + 15) = VOID(K + 15) + P
                VOID(K + 16) = VOID(K + 16) + T
              ELSE
                W        = W * (P * VOID(K + 30) + T * VOID(K + 31))
                F(I + 4) = MIN (W, 9.0)
                F(I + 1) = F(I + 1) * Q
                F(I + 2) = F(I + 2) * Q**2
                V        = ABS (1.0 - W**2)
                VOID(K)     = VOID(K) + P * V / MAX (VOID(K + 15), 0.01)
                VOID(K + 1) = VOID(K + 1) + T * V / MAX (VOID(K + 16),
     1            0.01)
                CALL GEN046 (F(I), X, Y, Z)
                IF (L >= 4) L = 0
                L = L + 1
                VOID(L + 45) = F(I + 1)
                VOID(L + 49) = SQRT (F(I + 2))
              END IF
              IF (I >= 79) THEN
                IF (M == 2) WRITE (LU19) F
                GO TO 30
              END IF
            ELSE
              EXIT
            END IF
          END DO
          IF (M == 1) THEN
            Q = 1.0
            U = 0.0
            DO J = 1, 10
              CALL GEN074 (E, 1, 8, 0.0)
              DO I = 1, 15
                X    = E(8)**2
                P    = EXP (X * U) * VOID(I)
                V    = P / MAX (1.E-5, VOID(I + 15))
                W    = P * Q
                Z    = VOID(I + 15) - W
                E(1) = E(1) + V * P
                W    = W * X
                E(2) = E(2) + V * W
                P    = Q * X
                E(3) = E(3) + V * W * P
                E(4) = E(4) + Z * V
                E(5) = E(5) + Z * V * P
                E(6) = E(6) + VOID(I)
                E(7) = E(7) + VOID(I + 15)
                E(8) = E(8) + 0.622004
              END DO
              X = 1.0 / (0.1 + E(1))
              W = - X * E(2)
              Z = 1.0 / (0.1 + E(3) + W * E(2))
              Y = Z * W
              X = X + W * Y
              U = U + E(4) * Y + E(5) * Z
              IF (ABS (U) >= 0.1) THEN
                U = SIGN (0.09999, U)
                X = 0.0
                Y = 1.0 / (0.1 + E(3))
              END IF
              Q = Q + E(4) * X + E(5) * Y
            END DO
            IF (Q <= 0.0) Q = 1.0
            Q = SQRT (MAX (Q, 0.0)) * SQRT (FLOAT (LATTS)) * 0.96
            U = 0.05 - 0.5 * U
            DO I = 1, 15
              VOID(I + 30) = SQRT ((VOID(I + 15) + 0.01 * E(7))
     1                  / (VOID(I) + 0.01 * E(6)))
            END DO
          END IF
          CALL GEN108 (LU9, 0)
        END DO
        WRITE  (LU19) F
        WRITE (LU6, 99984, IOSTAT = IOST) Q, U
        PAR(465) = U
C * WRITE UNIQUE REFLECTION FILE FOR DIRECT METHODS
        IF (IPR(525) <= 0 .AND. IPR(409) == 0) THEN
          CALL GEN108 (LU19, 1)
          CALL GEN108 (LU17, 0)
          EKW = 0.0
          NEK = 0
          DO WHILE (.TRUE.)
            READ (LU19) F
            DO I = 1, 79, 6
              IF (0.5 > ABS (F(I))) GO TO 50
              CALL GEN046 (F(I), VOID(1), VOID(2), VOID(3))
              V = F(I + 1) * 100.0
              W = SQRT (F(I + 2)) * 100.0
              WRITE (LU17, 99982, IOSTAT = IOST) NINT (VOID(1)),
     1          NINT (VOID(2)), NINT (VOID(3)), NINT (V), NINT (W)
C * E-VALUES IN F(I+4)
              EKW = EKW + ABS (F(I + 4)**2 - 1.0)
              NEK = NEK + 1
            END DO
          END DO
   50     WRITE (LU17, 99981, IOSTAT = IOST)
          WRITE (LU6,  99979, IOSTAT = IOST) EKW / NEK
          IGBL(16) = 1
        END IF
      END IF
C * EXOR (MODE > 0)
      IF (MODE > 0) THEN
C * UNIT CONTENT KNOWN ?  (i.e. => 1)
        KNOWN = 0
        DO I = 2, IAN
          IF (LMT(I, 1) /= ' Q') THEN
            IF (CONT(I, 3) /= CONT(1, 3)) KNOWN = 1
          END IF
        END DO
C * EDIT (OMIT)
        UT = 2.0 * (RGBL(5) / PAR(17))**2
        SS = PAR(284)**2
        N  = 0
        M  = 0
C * LU19 - BINARY REFLECTION FILE
        CALL GEN108 (LU19, 0)
        CALL GEN108 (LU4, 0)
        IF (SS <= 1.E9) THEN
          DO
            READ  (LU19) F
            WRITE (LU4)  F
            DO I = 1, 79, 6
              IF (NINT (F(I)) == 0) THEN
                CALL GEN108 (LU19, 0)
                CALL GEN108 (LU4, 1)
                DO
                  READ (LU4) F
                  DO J = 1, 79, 6
                    IF (NINT (F(J)) == 0) THEN
                      WRITE (LU19) F
                      CALL GEN108 (LU19, 1)
                      CALL GEN108 (LU4, 0)
                      WRITE (LU6, 99999, IOSTAT = IOST) SQRT (SS), M, N
                      GO TO 60
                    END IF
                    X = 0.0
C * OMIT TEST
                    IF (SS * F(J + 2) > F(J + 1)**2) THEN
                      X = 1.0
                      M = M + 1
                    END IF
C * RESET OMIT FLAG
                    F(J + 3) = MOD (F(J + 3), UT) + UT * X
                  END DO
                  WRITE (LU19) F
                END DO
              END IF
              N = N + 1
            END DO
          END DO
        END IF
C * EXOR RECYCLE
C * ROUGH (OVER)ESTIMATE  OF # OF ATOMS/ASYM UNIT
   60   EXPMX  = PAR(98) / (12.0 * NSYM)
        CRIT0  = 0.33
        PICKUP = 1.0
C * ORDER SCATTERING TYPES ON SCATTERING POWER (EXCLUDE Q)
        IAN0 = IAN
        IF (LMT(IAN, 1) == ' Q') IAN0 = IAN - 1
        DO I = 1, IAN0
          DA(I) = 1000.0 - IATNR(IEN(I))
          IA(I) = I
        END DO
        CALL GEN036 (DA, IA, 1, IAN0)
C * DETERMINE MAX/MIN SCATTERING POWER RATIO (EXCLUDING H)
        IRMIN = IAN0
        DO I = 1, IAN0
          DA(I) = 1000.0 - DA(I)
          IF (NINT (DA(I)) <= 1) IRMIN = IRMIN - 1
        END DO
        RATIO = DA(1) / DA(IRMIN)
C * SET POPULATION CUTOFF CRITERIUM
        CRIT = CRIT0 / RATIO
C * MAX DIST IN DISTANCE SCAN
        DO I = 1, 3
          V2(I) = 2.0 * PAR(112 + I)
        END DO
C * EXOR-LOOP
        NPK  = 0
        LOOP = 0
        VRT  = VERT - 3.0
   70   LOOP = LOOP + 1
        NAT  = MIN (MP3, IPR(37) + NPK)
C * LOAD INPUT ATOMS IN LOOP # 1
        IF (LOOP == 1) THEN
C * PEAK(I, 1)    = X
C * PEAK(I, 2)    = Y
C * PEAK(I, 3)    = Z
C * PEAK(I, 4)    = POP. PAR.
C * PEAK(I, 5)    = PEAK HEIGHT
C * PEAK(I, 6)    = SOF PAR (SYMM)
C * PEAK(I, 7:46) = BONDS (DISTANCE)
          DO J = 1, NAT
            DO I = 1, 3
              SGY(I)     = CON(J, I + 2)
              PEAK(J, I) = SGY(I)
            END DO
            PEAK(J, 5) = 100.0
            SGY(10)    = 0.0
C * GET SOF (SYMMETRY PART = TO BE MULTIPLIED WITH POP.PAR)
            CALL SGSM (19, LINE, SGY, 0, LU6, IERR)
            PEAK(J, 6) = SGY(10)
C * SET STARTING 'POPULATION' BASED ON STORED ATOM TYPE
            ATTP = LMT(NINT (CON(J, 8)), 1)
            DO I = 1, IAN0
              IF (ATTP == LMT(IA(I), 1)) GO TO 80
            END DO
   80       PEAK(J, 4) = SGY(10) * DA(I) / DA(1)
          END DO
C * ANALYZE (refined population + difmap peaks) (LOOP > 1)
        ELSE
          DO I = 1, NAT
            IF (I <= IPR(37)) THEN
              DO J = 1, 3
                SGY(J)     = CON(I, J + 2)
                PEAK(I, J) = SGY(J)
              END DO
              PEAK(I, 4) = CON(I, 9)
              PEAK(I, 5) = 0.0
C * ADD PEAKS FROM DIFF-MAP
            ELSE
              DO J = 1, 3
                SGY(J)     = XXO(I - IPR(37), J)
                PEAK(I, J) = SGY(J)
              ENDDO
              PEAK(I, 4) = PEAK(I, 6) * CRIT
              PEAK(I, 5) = XXO(I - IPR(37), 4) / PAR(98)
              IF (PEAK(I, 5) < PICKUP) PEAK(I, 4) = 0.0
            END IF
            SGY(10) = 0.0
C * GET SOF (SYMMETRY PART = TO BE MULTIPLIED WITH POP.PAR)
            CALL SGSM (19, LINE, SGY, 0, 6, IERR)
            PEAK(I, 6) = SGY(10)
          END DO
        END IF
C * ANALYSE GEOMETRY
C * RESET NR OF BONDS TO ATOM TO ZERO
        CALL GEN097 (NCON, 1, NAT, 0)
C * FIND DISTANCES BETWEEN ATOMS - ROLLETT, COMP. METH. IN CRYST. 1965
        DO I = 1, NAT
          DO J = I, NAT
            DO 150 N = 1, NSYM
              IF (J /= I .OR. N /= 1) THEN
                DO K = 1, 3
                  SGY(K)     = PEAK(J, K)
                  SGY(K + 3) = 0.0
                END DO
                NS = N
                CALL SGSM (3, LINE, SGY, NS, LU6, IERR)
                K = 1
                GO TO 100
   90           SGY(6 + K) = SGY(6 + K) - 1.0
  100           IF ((PEAK(I, K) - SGY(6 + K)) <= V2(K)) GO TO 90
                GO TO 120
  110           IF (ABS (PEAK(I, K)  - SGY(6 + K)) <= V2(K)) GO TO 130
  120           SGY(6 + K) = SGY(6 + K) + 1.0
                IF ((PEAK(I, K)  - SGY(6 + K)) >= - V2(K)) GO TO 110
                K = K - 1
                IF (K == 0) GO TO 150
                GO TO 120
  130           K = K + 1
                IF (K > 3) THEN
                  DO L = 1, 3
                    V3(L) = PEAK(I, L) - SGY(6 + L)
                  END DO
                  CALL GEN002 (2, OR, V3, V4, DIST)
                  IF (DIST < 2.0) THEN
                    IF (I /= J .OR. DIST > 0.05) THEN
                      IF (NCON(I) < 40) THEN
                        NCON(I)              = NCON(I) + 1
                        PEAK(I, 6 + NCON(I)) = DIST
                        ICON(I, NCON(I))     = J
                      END IF
                      IF (NCON(J) < 40) THEN
                        NCON(J)              = NCON(J) + 1
                        PEAK(J, 6 + NCON(J)) = DIST
                        ICON(J, NCON(J))     = I
                      END IF
                    END IF
                  END IF
                  GO TO 140
                END IF
                GO TO 100
  140           K = K - 1
                GO TO 120
              END IF
  150       CONTINUE
          END DO
        END DO
        NRNEW = 0
C * CONVERT/SELECT PEAKS TO EXOR INPUT FOR POPULATION REFINEMENT
        NRSH = 0
        RSHN = 0.0
        DO 160 I = 1, NAT
C * TEST FOR OCCUPANCY
          IF (PEAK(I, 4) / PEAK(I, 6) >= CRIT) THEN
C * ELIMINATE SHORT DISTANCE PEAKS
            JMAX = NCON(I)
            DO J = 1, JMAX
C * GET BOND
              BONDIJ = PEAK(I, J + 6)
C * ELIMINATE (ABSORPTION) GHOSTS
              IF (BONDIJ < 1.3) THEN
                K = ICON(I, J)
                IF (BONDIJ < 0.9 .OR.
     1            PEAK(I, 4) > PEAK(K, 4) * 3) THEN
C * SET POPULATION ZERO FOR GHOST
                  PEAK(K, 4) = 0.0
                END IF
              END IF
              IF (PEAK(I, 5) > 0.0 .AND. PEAK(I, 5) < 2.0) THEN
                IF (BONDIJ > 1.6) GO TO 160
              END IF
              IF (LOOP == 1) THEN
                PHMIN = 2.0
              ELSE
                PHMIN = 1.0
              END IF
              IF (BONDIJ < 1.8 .AND. PEAK(I, 5) > 0.0
     1           .AND. PEAK(I, 5) < PHMIN) GO TO 160
            END DO
C * LIMIT LIST TO MAXIMUM
            IF (RSHN < EXPMX) THEN
              NRSH  = NRSH + 1
              RSHN  = RSHN + PEAK(I, 6)
              DO J = 1, 3
                CON(NRSH, J + 2) = PEAK(I, J)
              END DO
              CON(NRSH, 8) = IA(1)
              CON(NRSH, 9) = PEAK(I, 4)
              IF (PEAK(I, 5) > 0.0) NRNEW = NRNEW + 1
              DATC(NRSH) = 1000.0 - PEAK(I, 4) / PEAK(I, 6)
              IATC(NRSH) = I
            END IF
          END IF
  160   CONTINUE
C * CHECK FOR NO ATOMS - PROBLEM
        IF (NRSH == 0) WRITE (LU6, 99969, IOSTAT = IOST)
        IPR(37) = NRSH
C * STOP WHEN NO NEW ATOMS HAVE BEEN PICKED UP
        IF (NRNEW /= 0 .OR. LOOP <= 2) THEN
          IF (LOOP < IABS (IPR(467))) THEN
C * SOF REFINEMENT
            CALL PLA152 (LOOP)
C * CHECK NO-ERROR - CALC DIFFERENCE MAP (NO GEOM)
            IF (IPR(2) == 0) CALL PLA153 (-2, NPK)
            GO TO 70
          END IF
        END IF
C * ANALYZE EXOR RESULT
        REWIND (UNIT = LU2, IOSTAT = IOST)
        IF (IOST /= 0) CALL GEN148 (LU2, 1)
        HRT = 0.57 * HORS
        VRT = VERT - 3.4
C * TITL, CELL, SPGR, SFAC, UNIT
        WRITE (LU2, 99990, IOSTAT = IOST)
     1    JID(1:6), PAR(17), (PAR(100  + I), I = 1, 12)
        WRITE (LU2, 99989, IOSTAT = IOST) IPR(242)
        DO I = 2, IPR(255)
          NUMS = I
          CALL SGSM (17, LINE, SGY, NUMS, 0, IERR)
          WRITE (LU2, 99988, IOSTAT = IOST) LINE(1:60)
        END DO
C * SFAC
        WRITE (LU2, 99987, IOSTAT = IOST) (LMT(I, 1), I = 1, IAN0)
C * UNIT
        WRITE (LU2, 99986, IOSTAT = IOST)
     1    (NINT(CONT(I, 3)), I = 1, IAN0)
        WRITE (LU2, 99995, IOSTAT = IOST) PAR(74)
C * ANALYSE POPULATION PEAKLIST
        FACT  = 0.5
        XPEAK = 999.0
        N     = 0
        DELTA = 1.0
        CALL GEN097 (MCONT, 1, NP10, 0)
        CALL GEN036 (DATC, IATC, 1, NRSH)
        DO I = 1, NRSH
          DATC(I) = (1000.0 - DATC(I)) * DA(1)
          IF (XPEAK - DATC(I) > DELTA) THEN
            IF (N < IRMIN) THEN
              N = N + 1
              IF (N < IRMIN) THEN
                DELT = DA(N) - DA(N + 1)
              ELSE
                DELT = 999.0
              END IF
            END IF
          END IF
          XPEAK    = DATC(I)
          DELTA    = DELT * FACT * XPEAK / DA(N)
          MCONT(N) = MCONT(N) + 1
        END DO
C * WRITE OUT ATOM-LIST
        N    = 0
        NEL0 = 1
        L    = 0
        NATR = 0
        HGHT = DATC(1)
C * LOOP OVER ATOMS
        DO I = 1, NRSH
          K    = IATC(I)
          NATR = NATR + 1
          N    = N + 1
C * HANDLE MULTIPLICITY
          L    = L + NINT(NSYM * PEAK(K, 6))
C * AVOID ASSIGNING TO H SCATTERERS
          IF (NEL0 < IAN0 .AND. NINT (DA(NEL0 + 1)) /= 1) THEN
            IF (KNOWN == 0) THEN
              IF (N <= MCONT(NEL0)) GO TO 170
            ELSE IF (KNOWN == 1) THEN
              IF (DA(NEL0) .gt. 15 .AND.
     1            (DA(NEL0) - DA(NEL0 + 1)) > 5) THEN
                IF ((HGHT - DATC(I)) / HGHT < 0.20) GO TO 170
              ELSE
                IF (L <= NINT (CONT(IA(NEL0), 3))) GO TO 170
              END IF
            END IF
            L    = NINT (NSYM * PEAK(K, 6))
            NEL0 = NEL0 + 1
            N    = 1
          END IF
  170     HGHT = DATC(I)
          LABI(1:4) = LMT(IA(NEL0), 1)(1:2)//'  '
          IF (LABI(1:1) /= ' ') THEN
            L0 = 1
            NO = 50 + N
          ELSE
            LABI(1:4) = LMT(IA(NEL0), 1)(2:2)//'   '
            L0 = 0
            NO = 500 + N
          END IF
          IF (NO < 100) THEN
            WRITE (LABI(2 + L0 : 3 + L0), 99971, IOSTAT = IOST) NO
          ELSE
            WRITE (LABI(2:4), 99972, IOSTAT = IOST) NO
          END IF
          WRITE (LU2, 99993, IOSTAT = IOST)
     1      LABI, IA(NEL0), (PEAK(K, J), J = 1, 3), 10 + PEAK(K, 6),
     2      RP(2)
          IF (IWIN == 1) THEN
            IF (I == 1) THEN
              WRITE (IDM, 99975, IOSTAT = IOST)
              VRT = VERT - 0.5
              CALL PLA439 (0.0, IDM, 38, 0.3, 5 + IGBL(68), 2, HRT, VRT)
            END IF
            IF (I <= 42) THEN
              WRITE (IDM, 99976, IOSTAT = IOST)
     1          I, LABI, (PEAK(K, J), J = 1, 3), DATC(I)
              VRT = VRT - 0.45
              CALL PLA439 (0.0, IDM, 38, 0.3, 1, 2, HRT, VRT)
            END IF
          END IF
        END DO
        WRITE (LU2, 99996, IOSTAT = IOST) (PAR(I), I = 231, 239)
        WRITE (IDM, 99992, IOSTAT = IOST) PAR(281), PAR(282), NATR
        WRITE (LU6, 99970, IOSTAT = IOST) IDM
        IF (IWIN == 1)
     1      CALL PLA439 (0.0, IDM, 56, 0.3, 5 + IGBL(68), 2, 0.2, 0.2)
C * PATTERSON
      ELSE
        IF (IABS (IPR(525)) == 1) THEN
          NPK  = 30
          MDIP = 0
          CALL PLA153 (0, NPK)
          IF (XXO(1, 4) > 0.0) THEN
            PMAX = 999.0 / XXO(1, 4)
          ELSE
            PMAX = 1.0
          END IF
          DO I = 1, NPK
            DO J = 1, 3
              XXO(I, J) = MOD (XXO(I, J), 1.0)
            END DO
            XXO(I, 4) = XXO(I, 4) * PMAX
          END DO
          NPKM = MIN (35, NPK)
          NPRV = 50
C * PATTERSON PEAK LISTING
          WRITE (LU6, 99978, IOSTAT = IOST)
          VRT = VERT - 1.8
          DO I = 1, NPKM
            NSTAR = NINT (XXO(I, 4) * 50 / 999.0)
            STAR  = ' '
            IF (NSTAR > 0) THEN
              DO J = 1, NSTAR
                STAR(J:J) = '*'
              END DO
            END IF
            NDIF = NPRV - NSTAR
            NPRV = NSTAR
            IF (NDIF > 0) THEN
              IF (I > 2) MDIP = MAX (MDIP, NDIF)
              DO J = 1, NDIF
                STAR(51-J:51-J) = '<'
              END DO
            END IF
            WRITE (LINE, 99998, IOSTAT = IOST)
     1        I, (XXO(I, J), J = 1, 4), STAR
            WRITE (LU6, 99968, IOSTAT = IOST) LINE
            IF (IWIN == 1) THEN
              VRT = VRT - 0.5
              CALL PLA439 (0.0, LINE, 80, 0.3, 1, 2, 2.2, VRT)
            END IF
          END DO
          WRITE (LU6, 99974, IOSTAT = IOST) MDIP, IGBL(89)
          IF (MDIP < IGBL(89)) THEN
            LINE = 'EQUAL ATOM TYPE PATTERSON'
          ELSE
            LINE = 'HEAVY ATOM TYPE PATTERSON'
          END IF
          WRITE (LU6, 99970, IOSTAT = IOST) LINE
          CALL PLA439 (0.0, LINE, 80, 0.4, 5 + IGBL(68), 2, 12.0, 2.0)
        END IF
      END IF
      IF (IWIN == 1) THEN
        IF (MODE > 0 .OR. IPR(525) /= 0) THEN
  180     IF (IPR(467) > 0) THEN
            WRITE (SBCD, 99997, IOSTAT = IOST) CHAR (0)
          ELSE
            WRITE (SBCD, 99973, IOSTAT = IOST) CHAR (0)
          END IF
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          IF (IGGT(1:4) == 'PLOT') GO TO 180
          OPEN (LU61, FILE = 'NEXT', STATUS = 'UNKNOWN')
          WRITE (LU61, 99968, IOSTAT = IOST) IGGT
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
        END IF
      END IF
  190 IF (MODE == 0 .AND. IPR(2) == 0) IPR(2) = -13
      IGBL(16) = KEEP
      RETURN
99999 FORMAT (':: Omit = ', F5.1, ' => ', I6,
     1' Reflections Suppressed out of', I6, /)
99998 FORMAT (I3, 3F6.3, F6.0, 2X, A)
99997 FORMAT ('[END]', A)
99996 FORMAT ('HKLF 4 1', 9F7.4, /, 'END')
99995 FORMAT ('FVAR', F10.3)
99994 FORMAT (/, I7,' Reflections Read, of Which', I5, ' Rejected', /)
99993 FORMAT (A, I4, 5F10.4)
99992 FORMAT ('Sin(Th)/Lam =', F5.2, '-', F4.2,
     1        ' - Number of Remaining Atoms:', I3)
99991 FORMAT (':: Hmin,   Hmax =', 2I5, /,
     1        ':: Kmin,   Kmax =', 2I5, /,
     2        ':: Lmin,   Lmax =', 2I5, /,
     3        ':: THmin, THMAX =', 2F5.1)
99990 FORMAT ('TITL ', A, ' - EXOR', /,
     1        'CELL ', F7.5, 6F10.4, /,
     2        'ZERR 1', 6X, 6F10.4)
99989 FORMAT ('LATT ', I3)
99988 FORMAT ('SYMM ', A)
99987 FORMAT ('SFAC ', 16(1X, A))
99986 FORMAT ('UNIT ', 2I5, 14I4)
99985 FORMAT (':: Nr Unique Reflections =', I6, '(Rav =', F8.4, ')')
99984 FORMAT (':: Overall Scale', F12.5, /, ':: Estimated U =', F6.3)
99983 FORMAT (/, ':: Excluded Weak Reflections from F(obs)',
     1        ' based S.o.f Refinement')
99982 FORMAT (3I4, 2I8)
99981 FORMAT (1X)
99980 FORMAT (3I4, 2F12.2, F10.2)
99979 FORMAT (':: Aver ABS(E**2-1) =', F5.2)
99978 FORMAT (/, 'PATTERSON', /)
99976 FORMAT (I2, 1X, A, 3F7.3, F6.1)
99975 FORMAT ('Nr Label     x      y      z    PP')
99974 FORMAT (/, 'PATT DIP', I3, ', [TEST CRIT = >', I3, ']')
99973 FORMAT ('[REF-XYZU]', A)
