              END IF
            ELSE
C * n GLIDE(hk0)
              IF (EX(15)) THEN
                IF (.NOT. EX(18)) THEN
                  CALL PLA163 ('Pm21n  ')
                  CALL PLA163 ('P21mn  ')
                  CALL PLA163 ('Pmmn   ')
                END IF
C * b GLIDE(hk0)
              ELSE IF (EX(14)) THEN
                IF (.NOT. EX(18)) THEN
                  CALL PLA163 ('Pm21b  ')
                  CALL PLA163 ('P2mb   ')
                  CALL PLA163 ('Pmmb   ')
                END IF
C * a GLIDE(hk0)
              ELSE IF (EX(13)) THEN
                IF (.NOT. EX(18)) THEN
                  CALL PLA163 ('P21ma  ')
                  CALL PLA163 ('Pm2a   ')
                  CALL PLA163 ('Pmma   ')
                END IF
C * no GLIDE(c)
              ELSE
C * 21 screw h00
                IF (EX(16)) THEN
C * 21 screw 0k0
                  IF (EX(17)) THEN
C * 21 screw 00l
                    IF (EX(18)) THEN
                      CALL PLA163 ('P212121')
                      IF (EXT(16) == '?') CALL PLA163 ('P22121 ')
                      IF (EXT(17) == '?') CALL PLA163 ('P21221 ')
                      IF (EXT(18) == '?') CALL PLA163 ('P21212 ')
                      IF (EXT(16) == '?' .AND. EXT(17) == '?')
     1                    CALL PLA163 ('P2221  ')
                      IF (EXT(16) == '?' .AND. EXT(18) == '?')
     1                    CALL PLA163 ('P2212  ')
                      IF (EXT(17) == '?' .AND. EXT(18) == '?')
     1                    CALL PLA163 ('P2122  ')
                    ELSE
                      CALL PLA163 ('P21212 ')
                    END IF
                  ELSE
C * 21 screw 00l
                    IF (EX(18)) THEN
                      CALL PLA163 ('P21221 ')
                    ELSE
                      CALL PLA163 ('P2122  ')
                    END IF
                  END IF
                ELSE
C * 21 screw 0k0
                  IF (EX(17)) THEN
C * 21 screw 00l
                    IF (EX(18)) THEN
                      CALL PLA163 ('P22121 ')
                    ELSE
                      CALL PLA163 ('P2212  ')
                    END IF
                  ELSE
C * 21 screw 00l
                    IF (EX(18)) THEN
                      CALL PLA163 ('P2221  ')
                    ELSE
                      CALL PLA163 ('P222   ')
                      CALL PLA163 ('Pmm2   ')
                      CALL PLA163 ('Pm2m   ')
                      CALL PLA163 ('P2mm   ')
                      CALL PLA163 ('Pmmm   ')
                    END IF
                  END IF
                END IF
              END IF
            END IF
          END IF
        END IF
C *********************************************************************
C * TETRAGONAL : LAUE CLASSES 4 = 4/M AND 5 = 4/M 2/M 2/M             *
C *********************************************************************
      ELSE IF (ILAT0 == 't') THEN
C * POINT GROUPS: 4, -4, 4/M, 422, 4MM, -42M, -4M2, 4/MMM
C * I CENTERING
        IF (ILAT1 == 'I') THEN
          IF (LAUE == '  4/m') THEN
            IF (EX(13) .AND. EX(14)) THEN
              CALL PLA163 ('I41/a  ')
            ELSE
C * 00L = L = 4N
              IF (EX(24)) THEN
                CALL PLA163 ('I41    ')
              ELSE
                CALL PLA163 ('I-4    ')
                CALL PLA163 ('I4     ')
                CALL PLA163 ('I4/m   ')
              END IF
            END IF
          ELSE IF (LAUE == '4/mmm') THEN
C * HK0 H,K
            IF (EX(13) .AND. EX(14)) THEN
              IF (EX(28)) THEN
C * 0KL H+L, (H0L H+L)
                IF (EX(9) .OR. EX(12)) THEN
                  CALL PLA163 ('I41/amd')
                ELSE
                  CALL PLA163 ('I41/acd')
                END IF
              END IF
            ELSE
              IF (EX(7) .AND. EX(8)) THEN
                IF (EX(28)) THEN
                  CALL PLA163 ('I41cd  ')
                ELSE
                  CALL PLA163 ('I4cm   ')
                  CALL PLA163 ('I-4c2  ')
                  CALL PLA163 ('I4/mcm ')
                END IF
              ELSE
                IF (EX(28)) THEN
                  CALL PLA163 ('I41md  ')
                  CALL PLA163 ('I-42d  ')
                ELSE
C * 00L = L = 4N
                  IF (EX(24)) THEN
                    CALL PLA163 ('I4122  ')
                  ELSE
                    CALL PLA163 ('I-42m  ')
                    CALL PLA163 ('I-4m2  ')
                    CALL PLA163 ('I4mm   ')
                    CALL PLA163 ('I422   ')
                    CALL PLA163 ('I4/mmm ')
                  END IF
                END IF
              END IF
            END IF
          END IF
        ELSE IF (ILAT1 == 'P') THEN
C * P CENTERING
          IF (LAUE == '  4/m') THEN
C * n - glide
            IF (EX(15)) THEN
C * 42 screw 00l
              IF (EX(18)) THEN
                CALL PLA163 ('P42/n  ')
              ELSE
                CALL PLA163 ('P4/n   ')
              END IF
            ELSE
C * 00L = L = 4N
              IF (EX(24)) THEN
                CALL PLA163 ('P41    ')
                CALL PLA163 ('P43    ')
C * 42 screw 00l
              ELSE IF (EX(18)) THEN
                CALL PLA163 ('P42    ')
                CALL PLA163 ('P42/m  ')
              ELSE
                CALL PLA163 ('P-4    ')
                CALL PLA163 ('P4     ')
                CALL PLA163 ('P4/m   ')
              END IF
            END IF
          ELSE IF (LAUE == '4/mmm') THEN
C * hk0 - h+k = 2n
            IF (EX(15)) THEN
C * 0kl - k+l = 2n
              IF (EX(9)) THEN
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P4/nnc ')
                ELSE
                  CALL PLA163 ('P42/nnm')
                END IF
C * 0kl - l = 2n
              ELSE IF (EX(8)) THEN
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P4/ncc ')
                ELSE
                  CALL PLA163 ('P42/ncm')
                END IF
C * 0kl - k = 2n
              ELSE IF (EX(7)) THEN
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P42/nbc')
                ELSE
                  CALL PLA163 ('P4/nbm ')
                END IF
              ELSE
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P42/nmc')
                ELSE
                  CALL PLA163 ('P4/nmm ')
                END IF
              END IF
            ELSE
C * 0kl - k+l = 2n
              IF (EX(9)) THEN
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P4nc   ')
                  CALL PLA163 ('P4/mnc ')
                ELSE
                  CALL PLA163 ('P-4n2  ')
                  CALL PLA163 ('P42nm  ')
                  CALL PLA163 ('P42/mnm')
                END IF
C * 0kl - l = 2n
              ELSE IF (EX(8)) THEN
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P4cc   ')
                  CALL PLA163 ('P4/mcc ')
                ELSE
                  CALL PLA163 ('P-4c2  ')
                  CALL PLA163 ('P42cm  ')
                  CALL PLA163 ('P42/mcm')
                END IF
C * 0kl - k = 2n
              ELSE IF (EX(7)) THEN
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
                  CALL PLA163 ('P42bc  ')
                  CALL PLA163 ('P42/mbc')
                ELSE
                  CALL PLA163 ('P-4b2  ')
                  CALL PLA163 ('P4bm   ')
                  CALL PLA163 ('P4/mbm ')
                END IF
              ELSE
C * hhl or h-hl - l = 2n
                IF (EX(25) .OR. EX(33)) THEN
C * 21 screw 0k0
                  IF (EX(17)) THEN
                    CALL PLA163 ('P-421c ')
                  ELSE
                    CALL PLA163 ('P42mc  ')
                    CALL PLA163 ('P-42c  ')
                    CALL PLA163 ('P42/mmc')
                  END IF
                ELSE
C * 00L = L = 4N
                  IF (EX(24)) THEN
C * 21 screw 0k0
                    IF (EX(17)) THEN
                      CALL PLA163 ('P41212 ')
                      CALL PLA163 ('P43212 ')
                    ELSE
                      CALL PLA163 ('P4122  ')
                      CALL PLA163 ('P4322  ')
                    END IF
C * 21 screw 00l
                  ELSE IF (EX(18)) THEN
C * 21 screw 0k0
                    IF (EX(17)) THEN
                      CALL PLA163 ('P42212 ')
                    ELSE
                      CALL PLA163 ('P4222  ')
                    END IF
                  ELSE
C * 21 screw 0k0
                    IF (EX(17)) THEN
                      CALL PLA163 ('P4212  ')
                      CALL PLA163 ('P-421m ')
                    ELSE
                      CALL PLA163 ('P-42m  ')
                      CALL PLA163 ('P422   ')
                      CALL PLA163 ('P-4m2  ')
                      CALL PLA163 ('P4mm   ')
                      CALL PLA163 ('P4/mmm ')
                    END IF
                  END IF
                END IF
              END IF
            END IF
          END IF
        END IF
C **********************************************************************
C * TRI/HEXAGONAL LAUE CLASSES 6=-3, 7=-3m1, 8=-31m, 9=6/m, 10=6/mmm   *
C **********************************************************************
      ELSE IF (ILAT0 == 'h') THEN
C * POINT GROUPS: 6    -6    6/m    622   6mm   -62m     6/mmm  -6m2
        IF (LAUE == '  6/m') THEN
          IF (EX(31)) THEN
            CALL PLA163 ('P61    ')
            CALL PLA163 ('P65    ')
          ELSE IF (EX(39)) THEN
            CALL PLA163 ('P62    ')
            CALL PLA163 ('P64    ')
C * 21 screw 00l
          ELSE IF (EX(18)) THEN
            CALL PLA163 ('P63    ')
            CALL PLA163 ('P63/m  ')
          ELSE
            CALL PLA163 ('P-6    ')
            CALL PLA163 ('P6     ')
            CALL PLA163 ('P6/m   ')
          END IF
        ELSE IF (LAUE == '6/mmm') THEN
C * CHECK 0KL,H0L and H-HL, L=2N
          IF (EX(33) .OR. EX(11) .OR. EX(8)) THEN
            IF (EX(25) .OR. EX(35) .OR. EX(36)) THEN
              CALL PLA163 ('P6cc   ')
              CALL PLA163 ('P6/mcc ')
            ELSE
              CALL PLA163 ('P63cm  ')
              CALL PLA163 ('P-6c2  ')
              CALL PLA163 ('P63/mcm')
            END IF
          ELSE
            IF (EX(25) .OR. EX(35) .OR. EX(36)) THEN
              CALL PLA163 ('P63mc  ')
              CALL PLA163 ('P-62c  ')
              CALL PLA163 ('P63/mmc')
            ELSE
              IF (EX(31)) THEN
                CALL PLA163 ('P6122  ')
                CALL PLA163 ('P6522  ')
              ELSE IF (EX(39)) THEN
                CALL PLA163 ('P6222  ')
                CALL PLA163 ('P6422  ')
C * 21 screw 00l
              ELSE IF (EX(18)) THEN
                CALL PLA163 ('P6322  ')
              ELSE
                CALL PLA163 ('P-62m  ')
                CALL PLA163 ('P6mm   ')
                CALL PLA163 ('P622   ')
                CALL PLA163 ('P-6m2  ')
                CALL PLA163 ('P6/mmm ')
              END IF
            END IF
          END IF
        ELSE
C * TRIGONAL CLASSES: 3, -3, 32, 3m, -3m, 312, 31m, -31m
C * R(obs) or R(Rev) Lattice
          IF (ILAT1 == 'R') THEN
            IF (LAUE == '   -3') THEN
              CALL PLA163 ('R3     ')
              CALL PLA163 ('R-3    ')
            ELSE IF (LAUE == ' -3m1') THEN
              IF (EX(33) .OR. EX(11) .OR. EX(8)) THEN
                CALL PLA163 ('R3c    ')
                CALL PLA163 ('R-3c   ')
              ELSE
                CALL PLA163 ('R3m    ')
                CALL PLA163 ('R32    ')
                CALL PLA163 ('R-3m   ')
              END IF
            END IF
          ELSE IF (ILAT1 == 'P') THEN
            IF (LAUE == '   -3') THEN
              IF (EX(39)) THEN
                CALL PLA163 ('P31    ')
                CALL PLA163 ('P32    ')
C * TWINNING ? ABOUT (1 0 0)
                IF (EXT(5) == '>') THEN
                  CALL PLA163 ('P-3    ')
                  CALL PLA163 ('R-3    ')
                END IF
              ELSE
                CALL PLA163 ('P3     ')
                CALL PLA163 ('P-3    ')
              END IF
            ELSE IF (LAUE == ' -3m1') THEN
              IF (EX(33) .OR. EX(8) .OR. EX(11)) THEN
                CALL PLA163 ('P3c1   ')
                CALL PLA163 ('P-3c1  ')
              ELSE
                IF (EX(39)) THEN
                  CALL PLA163 ('P3121  ')
                  CALL PLA163 ('P3221  ')
C * OBVERSE/REVERSE TWINNING ?
                  IF (EXT(47) /= '  ') THEN
                    CALL PLA163 ('R-3    ')
                  END IF
                ELSE
                  CALL PLA163 ('P321   ')
                  CALL PLA163 ('P3m1   ')
                  CALL PLA163 ('P-3m1  ')
                END IF
              END IF
            ELSE IF (LAUE == ' -31m') THEN
              IF (EX(25) .OR. EX(35) .OR. EX(36)) THEN
                CALL PLA163 ('P31c   ')
                CALL PLA163 ('P-31c  ')
              ELSE
                IF (EX(39)) THEN
                  CALL PLA163 ('P3112  ')
                  CALL PLA163 ('P3212  ')
C * OBVERSE/REVERSE TWINNING ?
                  IF (EXT(47) /= '  ') THEN
                    CALL PLA163 ('R-3    ')
                  END IF
                ELSE
                  CALL PLA163 ('P312   ')
                  CALL PLA163 ('P31m   ')
                  CALL PLA163 ('P-31m  ')
                END IF
              END IF
            END IF
          END IF
        END IF
C **********************************************************************
C * CUBIC   LAUE CLASS 11 : m-3 , 12 : m-3m                            *
C **********************************************************************
C * POINT GROUPS:  23, M-3, 432, -43M, M-3M
      ELSE IF (ILAT0 == 'c') THEN
C * F - CENTERING
        IF (ILAT1 == 'F') THEN
C * 0KL - TEST FOR K + l = 4N (K,L IMPLICIET IN F !)
          IF (EX(19)) THEN
C * HHL (H-HL)
            IF ((EX(25) .OR. EX(33)) .AND. (EX(26) .OR. EX(43))) THEN
              CALL PLA163 ('Fd-3c  ')
            ELSE
              IF (LAUE == ' m-3m') THEN
                CALL PLA163 ('Fd-3m  ')
              ELSE
                CALL PLA163 ('Fd-3   ')
              END IF
            END IF
          ELSE
C * HHL (H-HL)
            IF ((EX(25) .OR. EX(33)) .AND. (EX(26) .OR. EX(43))) THEN
              CALL PLA163 ('F-43c  ')
              CALL PLA163 ('Fm-3c  ')
            ELSE
C * 00L = L = 4N
              IF (EX(24)) THEN
                CALL PLA163 ('F4132  ')
              ELSE
                IF (LAUE == ' m-3m') THEN
                  CALL PLA163 ('F-43m  ')
                  CALL PLA163 ('F432   ')
                  CALL PLA163 ('Fm-3m  ')
                ELSE
                  CALL PLA163 ('F23    ')
                  CALL PLA163 ('Fm-3   ')
                END IF
              END IF
            END IF
          END IF
C * I - CENTERING
        ELSE IF (ILAT1 == 'I') THEN
C * 0KL
          IF (EX(7) .AND. EX(8)) THEN
C * HHL
            IF (EX(25) .AND. EX(28)) THEN
              CALL PLA163 ('Ia-3d  ')
            ELSE
              CALL PLA163 ('Ia-3   ')
            END IF
          ELSE
            IF (EX(25) .AND. EX(28)) THEN
              CALL PLA163 ('I-43d  ')
            ELSE
C * 00L = L = 4N
              IF (EX(24)) THEN
                CALL PLA163 ('I4132  ')
              ELSE
                IF (LAUE == ' m-3m') THEN
                  CALL PLA163 ('I-43m  ')
                  CALL PLA163 ('I432   ')
                  CALL PLA163 ('Im-3m  ')
                ELSE
                  CALL PLA163 ('I23    ')
                  CALL PLA163 ('I213   ')
                  CALL PLA163 ('Im-3   ')
                END IF
              END IF
            END IF
          END IF
C * P - CENTERING
        ELSE IF (ILAT1 == 'P') THEN
C * 0KL
          IF (EX(9)) THEN
            IF (LAUE == ' m-3m') THEN
C * HHL , H-HL
              IF (EX(25) .OR. EX(33)) THEN
                CALL PLA163 ('Pn-3n  ')
              ELSE
                CALL PLA163 ('Pn-3m  ')
              END IF
            ELSE
              CALL PLA163 ('Pn-3   ')
            END IF
          ELSE IF (EX(7) .OR. EX(11) .OR. EX(13)) THEN
            CALL PLA163 ('Pa-3   ')
          ELSE IF (EX(8) .OR. EX(10) .OR. EX(14)) THEN
            CALL PLA163 ('Pb-3   ')
          ELSE
C * HHL , H-HL
            IF (EX(25) .OR. EX(33)) THEN
              CALL PLA163 ('P-43n  ')
              CALL PLA163 ('Pm-3n  ')
            ELSE
              IF (LAUE == '  m-3') THEN
C * 21 screw 00l
                IF (EX(18)) THEN
                  CALL PLA163 ('P213   ')
                ELSE
                  CALL PLA163 ('P23    ')
                  CALL PLA163 ('Pm-3   ')
                END IF
              ELSE
C * 00L = L = 4N
                IF (EX(24)) THEN
                  CALL PLA163 ('P4132  ')
                  CALL PLA163 ('P4332  ')
C * 21 screw 00l
                ELSE IF (EX(18)) THEN
                  CALL PLA163 ('P4232  ')
                ELSE
                  CALL PLA163 ('P432   ')
                  CALL PLA163 ('P-43m  ')
                  CALL PLA163 ('Pm-3m  ')
                END IF
              END IF
            END IF
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA168
 
      MODULE stat
      SAVE
      INTEGER, DIMENSION(20, 3) :: NSTAT
      INTEGER, DIMENSION(20)    :: NSTOT
      REAL :: PERCMAX
      REAL, DIMENSION(20, 3) :: ST
      END MODULE stat
 
      SUBROUTINE PLA169 (MODE, RII, RISIG, SINTL, LUO)
C * LAUE (3)
      USE files
      USE parameters
      USE cggt
      USE dfspgr
      USE stat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LUO
      INTEGER :: LUX
      INTEGER :: MODE
      INTEGER :: MSHEL
      REAL :: RI
      REAL :: RII
      REAL :: RSIG
      REAL :: YUNK
      REAL :: SINTL
      REAL :: RISIG
      REAL :: XIDSI
      CHARACTER(len=40) :: BALK
      CHARACTER(len=80) :: PRBUF
C * MODE =  0 - INIT
C * MODE =  1 - ADD TO STATISTICS
C * MODE = -1 - CALC STATISTICS
C * MODE = -2 - OUTPUT STATISTICS
C * MODE = -3 - OUTPUT STATISTICS WITH ALERT
      IF (MODE == 0) THEN
        CALL GEN097 (NSTOT, 1, 20, 0)
        CALL GEN097 (NSTAT, 1, 60, 0)
        CALL GEN074 (ST,    1, 60, 0.0)
        PERCMAX = 0.0
      ELSE IF (MODE == 1) THEN
        DO I = 1, 20
          IF (SINTL < STLS(I)) THEN
            NSTOT(I) = NSTOT(I) + 1
            RSIG     = RISIG
            RI       = RII
            IF (RI <= 0.0) RI = 1.0
            IF (RSIG <= 0.0) RSIG = SQRT (RI)
            XIDSI = RI / RSIG
            IF (XIDSI >= 0.25) THEN
              NSTAT(I, 1) = NSTAT(I, 1) + 1
              IF (XIDSI > 1.0) THEN
                NSTAT(I, 2) = NSTAT(I, 2) + 1
                IF (XIDSI >= 2.0) THEN
                  NSTAT(I, 3) = NSTAT(I, 3) + 1
                END IF
              END IF
            END IF
            EXIT
          END IF
        END DO
      ELSE IF (MODE == -1) THEN
        DO I = 1, 20
          IF (NSTOT(I) > 0) THEN
            DO J = 1, 3
              ST(I, J) = 100.0 * NSTAT(I, J) / NSTOT(I)
            END DO
          END IF
          IF (ST(I, 3) > PERCMAX) PERCMAX = ST(I, 3)
        END DO
C * OUTPUT STATISTICS
      ELSE IF (MODE <= -2) THEN
        IF (LUO == 0) THEN
C * SPGR-EXT MODE
          IF (IPR(548) == 0) THEN
            M = 2 + IWIN
C * SYSTEM S MODE
          ELSE
            M = 2
          ENDIF
        ELSE
          M = 1
        END IF
        DO N = 1, M
          IF (N == 1) THEN
            IF (M == 1) THEN
              LUX = LUO
            ELSE
              LUX = LU6
            END IF
          ELSE IF (N == 2) THEN
            LUX = LU7
            WRITE (LUX, 99999, IOSTAT = IOST)
          ELSE
            LUX = 0
          ENDIF
   10     IF (LUX == 0) THEN
            CALL GGIP (HORS, VERT, 0.0, 1)
            VRT = VERT
          END IF
          WRITE (PRBUF, 99998, IOSTAT = IOST)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99990, IOSTAT = IOST)
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 0.8
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 5, 2, 0.3, VRT)
          END IF
          WRITE (PRBUF, 99997, IOSTAT = IOST)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 0.5
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 5, 2, 0.3, VRT)
          END IF
          WRITE (PRBUF, 99996, IOSTAT = IOST)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 0.5
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 5, 2, 0.3, VRT)
          END IF
          WRITE (PRBUF, 99997, IOSTAT = IOST)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 5, 2, 0.3, VRT)
          END IF
          MSHEL = 0
          DO I = 1, 20
            IF (NSTOT(I) > 0) THEN
              MSHEL = I
              L = NINT (ST(I, 3) * 0.4)
              DO K = 1, 40
                IF (K > L) THEN
                  BALK(K:K) = '.'
                ELSE
                  BALK(K:K) = '*'
                END IF
              END DO
              WRITE (PRBUF, 99995, IOSTAT = IOST)
     1          I, STLS(I), 1 / (2 * STLS(I)), NSTOT(I),
     2          (ST(I, J), J = 1, 3), BALK
              IF (LUX /= 0) THEN
                WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
              ELSE
                VRT = VRT - 0.7
                CALL PLA439 (0.0, PRBUF, 80, 0.37, 1, 2, 0.3, VRT)
              END IF
            END IF
          END DO
          WRITE (PRBUF, 99994, IOSTAT = IOST)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 0.7
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 5, 2, 0.3, VRT)
          END IF
          WRITE (PRBUF, 99993, IOSTAT = IOST)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 0.5
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 5, 2, 0.3, VRT)
          END IF
          WRITE (PRBUF, 99992, IOSTAT = IOST) NINT (PERCMAX)
          IF (LUX /= 0) THEN
            WRITE (LUX, 99990, IOSTAT = IOST)
            WRITE (LUX, 99991, IOSTAT = IOST) PRBUF
          ELSE
            VRT = VRT - 1.0
            CALL PLA439 (0.0, PRBUF, 80, 0.37, 1, 2, 0.3, VRT)
C * WHAT NEXT ?
            CALL PLA012 (2, 1)
            IF (IGGT(1:4) == 'PLOT') GO TO 10
          END IF
        END DO
        IF (MODE == -3) THEN
          WRITE (LUO, 99999, IOSTAT = IOST)
C * ALERT _908
          IF (PERCMAX < 75.0) THEN
            CALL PLA236 (908, 2, -999.0, PERCMAX, ' ', ' ')
          END IF
          IF (MSHEL <= 8) THEN
            YUNK = ST(MSHEL, 3)
C * ALERT _909
            IF (YUNK > 30.0) THEN
              CALL PLA236 (909, 2, -999.0, YUNK, ' ', ' ')
            END IF
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT (/, 'Section 7', /, 79('='),
     1        /, 'Analysis of Variance (F(obs) and F(calc) from FCF)',
     2        /, 79('='))
99998 FORMAT ('Intensity Distribution',
     1 ' [Decay of I/Sigma(I) versus sin(theta)/lambda]')
99997 FORMAT (79('='))
99996 FORMAT ('sh  st/l   Ang     #  0.25   1.0   2.0', 2X,
     3        'Percent  Distr. for I .gt. 2.0 * sig(I)')
99995 FORMAT (I2, 2F6.3, I6, 3F6.1, 1X, A)
99994 FORMAT (38X, 'I', 19X, 'I', 19X, 'I')
99993 FORMAT (18X, 'Percent Observed:   0',18X, '50', 17X, '100')
99992 FORMAT ('Maximum Percentage of Reflections with I >  2*sig(I)',
     3        ' in any Resolution Shell', I3, '%')
99991 FORMAT (A)
99990 FORMAT (/)
      END SUBROUTINE PLA169
 
      SUBROUTINE PLA170 (RS, N, I, M)
C * LAUE (4)
      USE files
      USE parameters
      USE lplat
      USE dfspgr
      USE hklmx
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: INZJ
      INTEGER :: NCNT
      REAL, DIMENSION(*) :: RS
C * N = LAUE CLASS
C * NUMBER OF POSSIBLE ASYMMETRIC REFLECTIONS
      FMN(N) = 0.0
      ITL(N) = 0
      NCNT   = 0
      IF (RS(INZ(I)) > -1.5) NTL(N, 1) = NTL(N, 1) + 1
      DO J = I, M
        DO K = 1, 2
          IF (K == 1) THEN
            INZJ = INZ(J)
            L    = J
          ELSE
            INZJ = - INZ(J) + 2 * IHKP
            L    = J + 24
          END IF
          XN(L)    = RS(INZJ)
          RS(INZJ) = -2.0
          IF (XN(L) > - 0.5) THEN
            NCNT = 1
            IF (XN(L) > 0.0) THEN
              FMN(N) = FMN(N) + XN(L)
              ITL(N) = ITL(N) + 1
            END IF
          END IF
        END DO
      END DO
C * NUMBER OF OBSERVED REFLECTIONS (AT LEAST ONCE)
      NTL(N, 2) = NTL(N, 2) + NCNT
      IF (ITL(N) > 1) THEN
        FMN(N)    = FMN(N) / ITL(N)
C * NUMBER OF REFLECTIONS MEASURED MORE THAN ONCE
        NTL(N, 3) = NTL(N, 3) + 1
        DO J = I, M
          DO K = 1, 2
            IF (K == 1) THEN
              INZJ = INZ(J)
              L    = J
            ELSE
              INZJ = - INZ(J) + 2 * IHKP
              L    = J + 24
            END IF
            IF (XN(L) > 0.0) THEN
              XTL(N) = XTL(N) + ABS (XN(L) - FMN(N))
              XNM(N) = XNM(N) + XN(L)
            END IF
          END DO
        END DO
      END IF
      RETURN
      END SUBROUTINE PLA170
 
      SUBROUTINE PLA171 (MODE)
C * CIF-READ ROUTINE
C * HANDLES, data_, loop_ and stop_ INSTRUCTIONS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cif
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IESC
      INTEGER :: MODE
      CHARACTER(len=1)   :: QT
      CHARACTER(len=50)  :: SAV
      CHARACTER(len=1)   :: ICH
      CHARACTER(len=1)   :: ICHU
      CHARACTER(len=1)   :: ICHUS
      CHARACTER(len=NKW) :: KEYWRD
C * PLA171 - MAIN CIF READ
C * PLA172 - CHECK FOR EMBEDDED MATERIAL BETWEEN ;;
C * PLA173 - SAVE EMBEDDED MATERIAL BETWEEN ;;
C * PLA174 - DATANAME -> VALUE
C * PLA176 - BUILDING KEYWORD
C * PLA177 - HANDLE CELL DATA
C * PLA178 - INSPECT EMBEDDED RES FILE
C * PLA179 - CALCULATE SIGIW
C * PLA180 - HANDLE WEIGHT EXPRESSION
C * PLA181 - BOND, ANGLE ETC
C * CIF-READ MODE = 0 : PLATON,
C *          MODE = 1 : PLUTON
C * LRETCIF = -2
C * LRETCIF - -1
C * LRETCIF =  0 :                                                (Input)
C * LRETCIF =  1 : NORMAL RETURN
C * LRETCIF =  2 : ERROR RETURN
C * LRETCIF =  3 : SYSTEM-S RETURN
C * LRETCIF =  4 : BOND, ANGLE, TORSION, HBOND
C * LRETCIF = 10 : LEAVE PLA171, GET NEW RECORD
C * LRETCIF = 12 :
C * INTERPRETE THE CIF-RECORD IN ICL
C * CHECK FOR/HANDLE/SAVE MATERIAL BETWEEN ;;
      IF (ISEMCOL == 0 .AND. ICL(1:1) == '#') RETURN
C * CHECK FOR/EMBEDDED MATERIAL BETWEEN ;:
      CALL PLA172
      IF (LRETCIF > 0) THEN
        LRETCIF = MOD (LRETCIF, 10)
      ELSE
        IF (ICL(1:1) /= '#') THEN
C * SKIP BLANK RECORDS
          DO I = 1, IRECMAX
            IF (ICL(I : I) /= CHAR (32)) GO TO 10
          END DO
        END IF
      END IF
      RETURN
C * TEST FOR DATASET HEADER data_ RECORD
   10 K = INDEX (ICL, 'data_')
      IF (K > 0) THEN
        IF (INDEX (ICL(1:80), '_data_') == 0) THEN
          IPR(752) = INDEX (ICL(1:80), 'global')
C * (RE)SET # H-M TO ZERO
          IPR(713) = 0
C * CHECK FOR TRAILING GLOBAL RECORD
          IF (IPR(499) > 0) THEN
            IF (INDEX (ICL(1:80), 'global') /= 0) THEN
              LRETCIF = 2
              RETURN
            END IF
          END IF
          ISEMCOL = 0
          N = INDEX (ICL(1:80), 'CSD_CIF')
          IF (N == 0) THEN
            N = K + 5
          ELSE
            IF (ICL(N+8:N+11) == 'MIF_') THEN
              N = N + 12
            ELSE
              N = N + 8
            END IF
C * CSD CIF STYLE DATA
            IGBL(94) = 1
          END IF
C * TEST FOR 'No-Atom-Yet'
          IF (IPR(39) == 0) THEN
            CALL GEN151 (ICL, N)
            JID = ICL(N:79 + N)
          END IF
C * INIT CELL/CIF
          LRETCIF = 0
          CALL PLA177 (0)
C * COUNT # DATASETS IN CIF
          IPR(499) = IPR(499) + 1
C * HANDLE INCOMPLETE STRUCTURE DATA ENTRY
          IF (IPR(499) > 1) THEN
C * TEST FOR 'No-Atom-Yet'
            IF (IPR(39) == 0) THEN
C * TEST FOR AUTO-S-MODE
              IF (IGBL(50) == 0)
     1          WRITE (LU6, 99999, IOSTAT = IOST) JID
C * TEST FOR CSD-CIF
              IF (IGBL(94) == 1) THEN
C * TEST FOR PREVIOUS/HANDLE CURRENT ENTRY NUMBER
                IF (IGBL(58) == 0) THEN
                  IGBL(54) = IGBL(54) + 1
                ELSE
                  IGBL(54) = IGBL(54) - 1
                END IF
              END IF
              RETURN
            END IF
            BACKSPACE IGBL(5)
            IFL(1)   = 'ENDS'
            ICL      = 'ENDS'
            IPR(220) = 1
            IPR(221) = 0
            IGBL(8)  = - IABS (IGBL(8))
            LRETCIF  = 1
            RETURN
          END IF
          ICL    = 'TITL '//JID(1:75)
          IFL(1) = 'TITL'
          IF (IGBL(3) /= 14) CALL GEN108 (LU11, 0)
          CALL PLA236 (0, 0, 0.0, 0.0, LINE(I:80), ' ')
          IPR(220) = 1
          IPR(221) = 0
          LRETCIF  = 1
          RETURN
        END IF
C * TEST FOR loop_ RECORD
      ELSE IF (ICL(I : I + 4) == 'loop_') THEN
C * SAVE POSSIBLE REMAINING CONTENTS
        DO J = I + 5, 80
          IF (ICL(J:J) /= CHAR (32)) THEN
            IGGT(1:80) = ICL(J:80)
            EXIT
          END IF
        END DO
        NSTRS    = 0
        ILOOP    = 1
        NLPM     = 0
        IPR(220) = 0
        IPR(221) = 0
        RETURN
C * TEST FOR stop_ RECORD
      ELSE IF (ICL(I : I + 4) == 'stop_') THEN
        RETURN
      END IF
C * RESET (NON)KEYWORD STATUS FOR NEW RECORD
C * KW = NUMBER OF CHARACTERS IN KEYWORD
C * NW = NUMBER OF CHARACTERS IN NON-KEYWORD STRING(TEXT OR NUMBER)
      KW = 0
      NW = 0
      NL = 0
C * BLANK KEYWORD (MAX KEYWORD LENGTH = NKW
      CALL GEN038 (KEYWRD, 1, NKW)
C * DEFAULT ESCAPE
   20 IESC = 0
      DO I = 1, IRECMAX + 1
        ICH = ICL(I : I)
C * SUBSTITUTE BLANK FOR CONTROL CHARACTERS ETC.
        IF (ICHAR (ICH) < 32 .OR. ICHAR (ICH) > 126)
     1    ICH = CHAR (32)
C * UPPERCASE
        ICHU  = ICH
        ICHUS = ICH
        CALL GEN020 (1, ICHU, 1, 1)
C * CONTINUE/FINISH BUILDING KEYWORD
        IF (KW /= 0) THEN
          CALL PLA176 (ICH, KEYWRD)
          IF (LRETCIF > 0) RETURN
        ELSE
C * START NEW WORD
          IF (NW == 0) THEN
C * START NEW KEYWORD
            IF (ICH == '_') THEN
              KW          = 1
              KEYWRD(1:1) = ICH
              IF (ILOOP == 0) NLPM = 0
              LINE = ' '
C * START NEW STRING
            ELSE IF (ICH /= CHAR (32)) THEN
              IF (ICH /= '''' .AND. ICH /= '"') THEN
                CALL GEN038 (NWRD, 3, NP70)
                NW         = 2
                NWRD(2:2)  = ICHU
                NWRDS(2:2) = ICHUS
                QT         = CHAR (32)
              ELSE
                NW         = 1
                QT         = ICH
              END IF
            END IF
          ELSE
            IF (NW > 0 .AND. NW <= NP70 - 2) THEN
              NW            = NW + 1
              NWRD(NW:NW)   = ICHU
              NWRDS(NW:NW)  = ICHUS
            ELSE IF (NW == NP70 - 1) THEN
              NW            = NW + 1
              NWRD(NW:NW)   = NWRD(1:1)
              NWRDS(NW:NW)  = NWRDS(1:1)
C * REPORT RECORD OVERFLOW
              WRITE (LU6, 99998, IOSTAT = IOST) CIFDIR(116),
     1          ICL(1:76), ICL(77:154)
            END IF
C * HANDLE \' AND \" IN
            IF ((ICH == '''' .OR. ICH == '"') .AND. IESC == 1)
     1        THEN
              IESC = 0
            ELSE IF (ICH == CHAR (92)) THEN
              IESC = 1
            ELSE IF (ICH == QT) THEN
              IF (QT == ' ' .OR. QT == '"') NWRD(NW:NW) = ''''
              ILOOP = 0
              IF (NL == 0) THEN
                IPR(220) = 0
                IPR(221) = 0
              END IF
C * ANALYSE DATUM IN POSITION 2 TO END (I.E. QUOTE)
              CALL GEN042 (NWRD, FA, KNUM)
C * REPORT ERROR (OVERFLOW)
              IF (KNUM == -2) THEN
                WRITE (LU6, 99997, IOSTAT = IOST) KEYWRD, NWRD
              END IF
              IF (NL < NLPM) THEN
                NL    = NL + 1
                K     = I
                CALL PLA174 (MODE, K)
                IF (LRETCIF > 0) THEN
                  LRETCIF = MOD (LRETCIF, 10)
                  RETURN
                ELSE
C * OUTPUT RESULTS
                  IF (NL == NLPM) THEN
                    IF (NLPM > 1) THEN
                      IF (ICL(1:4) /= 'SYMM') THEN
                        DO J = I, I + 10
                          IF (ICL(J:J) /= CHAR(32)) THEN
C * CHECK FOR QUOTE
                            IF (ICL(J:J) /= CHAR (39)) THEN
C *  SAVE RESIDUAL CONTENT
                              IGGT(1:80) = ICL(J : J + 79)
                            END IF
                            EXIT
                          END IF
                        END DO
                      END IF
                    END IF
 
                    IF (IPR(220) <= 0) THEN
C * CHECK FOR BOND/ANGLE/TORSION/CONTACT/HBONDS
                      IF (IPR(751) == 1) CALL PLA181 (MODE)
                    ELSE
                      LRETCIF = 1
                      RETURN
                    END IF
                  END IF
                END IF
              END IF
              CALL GEN038  (NWRD, 1, NP70)
              NW = 0
            ELSE
              IESC = 0
            END IF
          END IF
        END IF
      END DO
C * HANDLE INCOMPLETE LOOP (CONTINUE ON NEW LINE)
   30 IF (KW == 0 .AND. NL > 0) THEN
        IF (NL < NLPM) THEN
          READ (LU1, 99996, IOSTAT = IOST) ICL
          IF (IOST == 0) THEN
   40       N = INDEX (ICL, 'data_')
            IF (N /= 0) THEN
              I     = N
              NLPM  = 0
              ILOOP = 0
              GO TO 10
            ELSE
              IF (ICL(1:1) == ';') THEN
                IF (NLPM > 1) THEN
                  IF (ISEMCOL == 0) THEN
                    ISEMCOL = 1
                    DO J = 2, 51
                      IF (ICL(J:J) /= ' ') THEN
                        SAV = ICL(J:J+49)
                        ICL = SAV
                        GO TO 40
                      END IF
                    END DO
                    GO TO 30
                  ELSE
                    BACKSPACE LU1
                    ICL = '?'
                    GO TO 40
                  END IF
                END IF
C * HANDLE ; PROBLEM IN LOOP
                DO
                  READ (LU1, 99996, IOSTAT = IOST) ICL
                  IF (IOST /= 0) THEN
                    IF (ICL(1:1) /= ';') CYCLE
                    ICL(1:9) = ' '' ? '' # '
                    EXIT
                  ELSE
                    LRETCIF = 2
                    RETURN
                  END IF
                END DO
              END IF
              NW = 0
              GO TO 20
            END IF
          ELSE
            LRETCIF = 2
          END IF
        END IF
      END IF
C * RETURN TO PLA006
      RETURN
99999 FORMAT ('W: CIF Data_Record with no Atom Data: Skipped', //,
     1        ':: New Data Set ', A, /)
99998 FORMAT (':: OVERFLOW PROBLEM in RECORD:', A, /, 3X, A, /, 3X, A,
     1 /, '   ... etc ...', /, ':: RECORD TRUNCATED to 80 Characters',
     2 /)
99997 FORMAT (':: ERROR: KEYWORD/DATUM OVERFLOW ', A, /, A)
99996 FORMAT (A)
      END SUBROUTINE PLA171
 
      SUBROUTINE PLA172
C * CHECK FOR/EMBEDDED MATERIAL BETWEEN ;:
      USE files
      USE parameters
      USE cif
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: NZERO
      REAL :: VAL1
      REAL :: VAL2
      REAL :: RATIO
C * SKIP/SAVE TEXT WITHIN SECTION STRINGS AND EMBEDDED INFO
      NZERO   = 0
      LRETCIF = 0
      IF (ISEMCOL == 0) THEN
        NSTRS = 0
        NSTR  = 0
      END IF
      IF (ICL(1:1) /= ';') THEN
C * CHECK FOR CURRENT SEMICOLUMN SECTION STATUS
        IF (ISEMCOL == 1) THEN
C * INIT VOID COUNTS
          IF (INDEX (ICL, '_platon_squeeze_void_nr') /= 0) THEN
            PAR(437) = 0.0
            PAR(438) = 0.0
          END IF
          IF (IVOID == -1) THEN
            IF (INDEX (ICL, '_platon_squeeze_void_content') /= 0)
     1        IVOID = 1
          ELSE IF (IVOID == 1) THEN
            IF (INDEX (ICL, '_platon_squeeze_details') /= 0) THEN
                IVOID = 0
            ELSE
              IF (IPR(665) == 1) THEN
                READ (ICL, *, IOSTAT = IOST) (FN(I), I = 1, 6)
                PAR(437) = PAR(437) + FN(5)
                PAR(438) = PAR(438) + FN(6)
              END IF
            END IF
C * TEST FOR SQUEEZE DETAILS
          ELSE IF (ICL(1:9) == '# SQUEEZE') THEN
            IF (IPR(665) == 1) THEN
              IF (MOD (IPR(651), 10) /= 1) IPR(651) = IPR(651) + 1
              IF (IPR(665) /= 0) IVOID = -1
            END IF
          END IF
C * COPY _shelx_res DATA
          IF (IPR(663) == 1) THEN
            CALL GEN155 (1, ICL, NZERO)
C * INSPECT .RES FILE CONTENT
            CALL PLA178
            WRITE (LU24, 99998, IOSTAT = IOST) ICL(1:80)
            IPR(653) = IPR(653) + 1
C * COPY _shelx_hkl DATA
          ELSE IF (IPR(664) == 1) THEN
            CALL GEN155 (1, ICL, NZERO)
            IF (ICL(1:1) /= '_') THEN
C * HANDLE SPURIOUS BLANK RECORDS IN EMBEDDED HKL FILE
              IF (ICL(1:4) == '    ') THEN
                READ (LU1, 99998, IOSTAT = IOST) ICL
                IF (IOST == 0) THEN
                  IF (ICL(1:1) == ';') THEN
                    BACKSPACE (LU1)
                  ELSE
                    READ (ICL, 99997, IOSTAT = IOST) IH, IK, IL,
     1                VAL1, VAL2
                    IF (IOST == 0) THEN
                      IF (IABS (IH) + IABS (IK) + IABS (IL) /= 0) THEN
                        BACKSPACE (LU1)
C * REPORT/COUNT REMOVED BLANK RECORDS
                        WRITE (LU6, 99994)
                        IPR(770) = IPR(770) + 1
                      ELSE
                        WRITE (LU25, 99996)
                      END IF
                    ELSE
                      IF (ICL(88:88) == ' ') THEN
                        WRITE (LU25, 99995) ICL(1:80)
                      ELSE
                        WRITE (LU25, 99995) ICL(1:112)
                      END IF
                      CALL GEN155 (1, ICL, NZERO)
                    END IF
                  END IF
                END IF
              ELSE
                IF (ICL(88:88) == ' ') THEN
                  WRITE (LU25, 99998, IOSTAT = IOST) ICL(1:80)
                ELSE
                  WRITE (LU25, 99998, IOSTAT = IOST) ICL(1:112)
                END IF
                READ (ICL(1:28), 99997, IOSTAT = IOST)
     1            IH, IK, IL, VAL1, VAL2
                IF (IOST == 0) THEN
                  IF (IABS (IH) + IABS (IK) + IABS (IL) /= 0)
     1              IPR(742) = IPR(742) + 1
C * CHECK FOR UNUSUAL (CALCULATED) DATA
                  IF (VAL1 > 0.0 .AND. VAL2 /= 0.0) THEN
                    IF (IPR(741) == 0)
     1                REWIND (UNIT = LU67, IOSTAT = IOST)
                    RATIO    = VAL2 / SQRT (VAL1)
                    PAR(555) = PAR(555) + RATIO
                    IPR(741) = IPR(741) + 1
                    WRITE (LU67) RATIO
                  END IF
                END IF
              END IF
            END IF
            IF (ICL(1:7) == '_platon')
     1        CALL PLA236 (991, 0, -999.0, 1.0, ' ', ' ')
C * COPY _shelx_fab DATA
          ELSE IF (IPR(665) == 1) THEN
            CALL GEN155 (1, ICL, NZERO)
            WRITE (LU26, 99998, IOSTAT = IOST) ICL(1:80)
C * COPY EMBEDDED FCF DATA
          ELSE IF (IPR(666) == 1) THEN
            WRITE (LU28, 99998, IOSTAT = IOST) ICL(1:80)
C * COPY EMBEDDED FILE (e.g. .bodd - IDEAL Invariom Software)
          ELSE IF (IPR(667) == 1) THEN
            WRITE (LU65, 99998, IOSTAT = IOST) ICL(1:80)
C * COPY OTHER TEXT DATA
          ELSE
C * COUNT LINES BETWEEN ;; FOR NONE OF THE ABOVE
            IPR(654) = IPR(654) + 1
C * CHECK ACTUAL RECORD LENGTH - ASSUME 80 WHEN FOLLOWED BY 10 BLANKS
            IF (ICL(81:90) /= '          ') THEN
C * SKIP IN CASE OF _iucr_refine_reflections_details
              IF (NLP(1) /= 569) THEN
                IPR(544) = IPR(544) + 1
                IF (IPR(544) == 1)
     1            WRITE (LU6, 99999, IOSTAT = IOST) ICL(1:15)
              END IF
            END IF
            CALL GEN039 (1, ICL, 1, 250, NB, NE)
            IF (NSTR < 0) NSTR = 0
            IF (NE - NB + 1 > 0 .AND. NSTR + NE - NB + 2 < 5000)
     1        THEN
              STRSAVE(NSTR + 1:) = ICL(1:NE + 1)
              NSTR = NSTR + NE - NB + 2
            END IF
            NSTRS = NSTR
          END IF
          LRETCIF = 10
          RETURN
        END IF
C * END ISEMCOL = 1 SECTION
C * SECTION STRINGS (IN-STRING FLIP-FLOP ISEMCOL)
      ELSE
        CALL PLA173
        IF (LRETCIF == 10) RETURN
      END IF
C * SKIP EMPTY RECORDS
      IF (ICL(1:1) /= CHAR(13)) THEN
        NSTR = -1
C * CHECK ACTUAL RECORD LENGTH - ASSUME 80 WHEN FOLLOWED BY 10 BLANKS
C * EXCEPT FOR THE EMBEDDED REFLECTION SECTION
        IRECMAX = 80
        IF (IPR(646) <= 0) THEN
          IF (ICL(81:81) == CHAR (13)) ICL(81:81) = CHAR (32)
          IF (ICL(81:90) /= '          ') THEN
            IRECMAX = NP45 - 1
            IF (IPR(654) == 0) THEN
              IPR(544) = IPR(544) + 1
              IF (IPR(544) == 1)
     1          WRITE (LU6, 99999, IOSTAT = IOST) ICL(1:15)
            END IF
          END IF
        END IF
        N    = INDEX (ICL(1:IRECMAX), ' #')
C * BLANK DATA FROM #
        IF (N > 1) CALL GEN038 (ICL, N, IRECMAX)
      END IF
      RETURN
99999 FORMAT (':: Record(s) Longer than 80 Bytes found,',
     1        ' 2048 Bytes Assumed: ', A, ' ...')
99998 FORMAT (A)
99997 FORMAT (3I4, 2F8.0)
99996 FORMAT (1X)
99995 FORMAT (/, A)
99994 FORMAT (':: Empty Record in Embedded HKL File Removed !')
      END SUBROUTINE PLA172
 
      SUBROUTINE PLA173
C * SAVE EMBEDDED MATERIAL BETWEEN ;;
      USE files
      USE parameters
      USE cchar
      USE cif
      IMPLICIT NONE
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: MSTR
      INTEGER :: NZERO
      ISEMCOL = MOD (ISEMCOL + 1, 2)
C * ISEMCOL = 1 : HANDLE TEXT SECTIONS BETWEEN SEMI-COLONS
      IF (ISEMCOL == 1) THEN
C * _shelx_res_file (SHELXL201n) (578)
C * _iucr_refine_instructions_details + WINGX (513)
        IF (IPR(663) == 0 .AND. (NLP(1) == 578 .OR. NLP(1) == 513)) THEN
          IPR(663) = 1
          IPR(719) = -1
C * INIT CHECKSUM RES
          CALL GEN155 (0, ICL, NZERO)
C *HANDLE RARE CASE WHERE BOTH _shelx_res_file and
C * _iucr_refine_instructions_details are erroneously embedded
C * _shelx_res_file
          IF (NLP(1) == 578) THEN
            IF (IPR(701) /= 1) IPR(701) = 1
C * _iucr_refine_instructions_details
          ELSE IF (NLP(1) == 513) THEN
            IF (IPR(701) /= 1) IPR(701) = 2
          END IF
C * INIT RES CHECKSUM (NOT) PRESENT
          IF (IPR(725) /= 5 .AND. IPR(725) /= 7) THEN
            IF (IPR(677) == 0) THEN
              IPR(677) = -1
            ELSE
              IPR(677) = IABS (IPR(677))
            END IF
          END IF
          INQUIRE (UNIT = LU24, OPENED = OPEND)
          IF (OPEND) CLOSE (UNIT = LU24, STATUS = 'DELETE')
          OPEN (UNIT = LU24, FILE =  NAMEFIL(1:KNMFIL)//'_sx.ins',
     1      STATUS = 'UNKNOWN', IOSTAT = IOST)
          IF (IOST /= 0) REWIND (UNIT = LU24, IOSTAT = IOST)
          WRITE (LU6, 99999) NAMEFIL(1:KNMFIL)//'_sx.ins'
C * _shelx_hkl_file (SHELXL201n) (580)
C * _iucr_refine_reflections_details + WINGX (569)
        ELSE IF (NLP(1) == 580 .OR.
     1    (NLP(1) == 569 .AND. IPR(725) == 7)) THEN
          IF (NLP(1) == 580) THEN
            IPR(702) = 1
          ELSE IF (NLP(1) == 569) THEN
            IPR(702) = 2
          END IF
          IPR(664) = 1
          IPR(676) = 1
          IPR(646) = 1
C * INIT CHECKSUM HKL
          CALL GEN155 (0, ICL, NZERO)
C * INIT HKL CHECKSUM (NOT) PRESENT
          IF (IPR(725) /= 7) THEN
            IF (IPR(678) == 0) THEN
              IPR(678) = -1
            ELSE
              IPR(678) = IABS (IPR(678))
            END IF
          END IF
          INQUIRE (UNIT = LU25, OPENED = OPEND)
          IF (OPEND) CLOSE (UNIT = LU25, STATUS = 'DELETE')
          OPEN (UNIT = LU25, FILE = NAMEFIL(1:KNMFIL)//'_sx.hkl',
     2      STATUS = 'UNKNOWN', IOSTAT = IOST)
          IF (IOST /= 0) REWIND (UNIT = LU25, IOSTAT = IOST)
          WRITE (LU6, 99999) NAMEFIL(1:KNMFIL)//'_sx.hkl'
C * _shelx_fab_file (SHELXL201n) (601)
        ELSE IF (NLP(1) == 601) THEN
          IPR(665) =  1
C * INIT CHECKSUM FAB
          CALL GEN155 (0, ICL, NZERO)
C * INIT FAB CHECKSUM (NOT) PRESENT
          IF (IPR(679) == 0) THEN
            IPR(679) = -1
          ELSE
            IPR(679) = IABS (IPR(679))
          END IF
          INQUIRE (UNIT = LU26, OPENED = OPEND)
          IF (OPEND) CLOSE (UNIT = LU26, STATUS = 'DELETE')
          OPEN (UNIT = LU26, FILE =
     1      NAMEFIL(1:KNMFIL)//'_sx.fab', STATUS = 'UNKNOWN')
          IF (IOST /= 0) REWIND (UNIT = LU26, IOSTAT = IOST)
          WRITE (LU6, 99999) NAMEFIL(1:KNMFIL)//'_sx.fab'
C * _shelx_fcf_file (905)
C * _iucr_refine_fcf_details (761)
        ELSE IF (NLP(1) == 761 .OR. NLP(1) == 905) THEN
          IPR(666) = 1
          INQUIRE (UNIT = LU28, OPENED = OPEND)
          IF (OPEND) CLOSE (UNIT = LU28, STATUS = 'DELETE')
          OPEN (UNIT = LU28, FILE = NAMEFIL(1:KNMFIL)//'_sx.fcf',
     1    STATUS = 'UNKNOWN')
          WRITE (LU6, 99999) NAMEFIL(1:KNMFIL)//'_sx.fcf'
C * INIT CHECKSUM INCLUDE FILE
        ELSE IF (NLP(1) == 892) THEN
          CALL GEN155 (0, ICL, NZERO)
C * SCIP _Jana_M40_file, Jana_M50_file, Jana_M60_file, Jana_M90_file
        ELSE IF (NLP(1) == 1005 .OR. NLP(1) == 1006 .OR.
     1           NLP(1) == 1007 .OR. NLP(1) == 1008) THEN
          IPR(725) = 6
C * REGULAR TEXT SECTION
        ELSE
          IPR(654) = 0
          CALL GEN039 (1, ICL, 1, 250, NB, NE)
          IF (NE > 1) THEN
            STRSAVE(1:NE) = ICL(2:NE + 1)
            NSTR    = NE
          ELSE
            STRSAVE = ' '
            NSTR    = 0
            NSTRS   = 0
          END IF
        END IF
        LRETCIF = 10
        RETURN
C * ISEMCOL = 0: TERMINATE TEXT SECTION
      ELSE
        IPR(646) = - IABS (IPR(646))
        IF (IPR(663) == 1) THEN
          CALL GEN155 (-1, ICL, IPR(721))
          IF (IPR(725) == 5) THEN
            IPR(663) = 0
            CLOSE (UNIT = LU24, IOSTAT = IOST)
          ELSE
            IPR(663) = -1
            ENDFILE (LU24, IOSTAT = IOST)
          END IF
C * END EMBEDDED HKL
        ELSE IF (IPR(664) == 1) THEN
          IPR(664) = -1
          CALL GEN155 (-1, ICL, IPR(722))
C * END EMBEDDED FAB
        ELSE IF (IPR(665) == 1) THEN
          IPR(665) = -1
          CALL GEN155 (-1, ICL, IPR(723))
C * END EMBEDDED FCF
        ELSE IF (IPR(666) == 1) THEN
          IPR(666) = -1
          CLOSE (UNIT = LU28, IOSTAT = IOST)
C * END EMBEDDED INCLUDE FILE
        ELSE IF (IPR(667) == 1) THEN
          IPR(667) = -1
          CALL GEN155 (-1, ICL, IPR(724))
          CLOSE (UNIT = LU65, IOSTAT = IOST)
        ELSE
          MSTR = MIN (78, MAX (NSTR, 1))
          ICL  = CHAR (39)//STRSAVE(1:MSTR)//CHAR (39)
        END IF
      END IF
      RETURN
99999 FORMAT (':: Extracted from CIF: ', A)
      END SUBROUTINE PLA173
 
      SUBROUTINE PLA174 (MODE, I0)
C * DATANAME > VALUE
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cif
      USE cggt
      USE symsav
      USE sgxyz
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: M
      INTEGER       :: N
      INTEGER       :: N1
      INTEGER       :: N2
      INTEGER       :: I0
      INTEGER, SAVE :: JH = 0
      INTEGER, SAVE :: JK = 0
      INTEGER, SAVE :: JL = 0
      INTEGER       :: LB
      INTEGER       :: LE
      INTEGER       :: NB
      INTEGER       :: NE
      INTEGER       :: JSGR
      INTEGER       :: MODE
      INTEGER       :: NORC
      INTEGER       :: NWMX
      INTEGER       :: NLPNL
      INTEGER       :: NZERO
      INTEGER       :: NELTYPE
      REAL, SAVE :: FSQ = 0.0
      REAL, SAVE :: SIG = 0.0
      REAL       :: YUNK
      REAL       :: RATIO
      REAL       :: RATIO1
      CHARACTER(len=9)        :: NQY
      CHARACTER(len=18), SAVE :: FORMA
      CHARACTER(len=2)        :: ELTYPE
      NZERO = 0
      NLPNL = NLP(NL)
      SELECT CASE (NLPNL)
C * _pd_block_id
        CASE (937)
          IPR(105) = 1
C * _reflns_special_details
        CASE (417)
C * _shelx_space_group_comment
        CASE (574)
C * _geom_special_details
        CASE (277)
C * _chemical_name_systematic
        CASE (116)
C * _ATOM_SITES_SOLUTION_PRIMARY
        CASE (48)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(10) = NWRD(2:NW - 1)
            NCIF(10) = NW - 2
C * CHECK FOR NON-DEFAULT INFO
            IF (INDEX(CCIF(10), '?') == 0) IPR(740) = 1
          END IF
          CALL GEN020 (-1, CCIF(10),  1, NP57)
C * _atom_sites_solution_secondary
        CASE (49)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(11) = NWRD(2:NW-1)
            NCIF(11) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(11),  1, NP57)
C * _atom_sites_solution_hydrogen
        CASE (50)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(12) = NWRD(2:NW-1)
            NCIF(12) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(12),  1, NP57)
C * NOTE GENERATION BY SHELXL/CRYSTALS etc
C * _audit_creation_method
        CASE (72)
          NWMX     = MIN (NW - 2, NP57)
          CCIF(23) = NWRD(2:NWMX + 1)
          NCIF(23) = NWMX
          IF (INDEX (NWRD, 'SHELXL-97') /= 0 .OR.
     1        INDEX (NWRD, 'SHELXL97')  /=0) THEN
            IF (IPR(725) /= 1) THEN
              IPR(725) = 1
C * ALERT _899
              CALL PLA236 (899, 0, -999.0, 2019.0, '   2019/3',
     1          'SHELXL-97 ')
            END IF
            XLDTP = '97'
C * APEX
          ELSE IF (INDEX (NWRD, 'APEX') /= 0) THEN
            IPR(725) = 1
C * SHELXL-20xx
          ELSE IF (INDEX (NWRD, 'SHELXL-20') /= 0) THEN
            IPR(725) = 2
            N = INDEX (NWRD, '-20')
            XLDTP = NWRD(N + 3:N + 4)
            IF (XLDTP == '18')
C * ALERT _899
     1        CALL PLA236 (899, 0, -999.0, 2019.0, '   2019/3',
     2          'SHELXL2018')
C * PLATON
          ELSE IF (INDEX (NWRD, 'PLATON') /= 0) THEN
            IPR(725) = 3
C * CRYSTALSTRUCTURE
          ELSE IF (INDEX (NWRD, 'CRYSTALSTRUCTURE') /= 0)
     1      THEN
            IPR(725) = 4
C * CRYSTALS
          ELSE IF (INDEX (NWRD, 'CRYSTALS') /= 0) THEN
            IPR(725) = 5
C * JANA
          ELSE IF (INDEX (NWRD, 'JANA') /= 0) THEN
            IPR(725) = 6
C * WINGX
          ELSE IF (INDEX (NWRD, 'WINGX') /= 0) THEN
            IPR(725) = 7
C * OLEX2-REFINE
          ELSE IF (INDEX (NWRD, 'OLEX2') /= 0) THEN
            IPR(725) = 8
C * MOPRO - REFINE
          ELSE IF (INDEX (NWRD, 'MOPRO') /= 0) THEN
            IPR(725) = 9
C * SET MOPRO WEIGHT DEFAULT
            IPR(632) = 4
          END IF
C * _computing_data_collection
        CASE (118)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(20) = NWRD(2:NW-1)
            NCIF(20) = NW - 2
          END IF
C * _computing_data_reduction
        CASE (119)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(21) = NWRD(2:NW - 1)
            NCIF(21) = NW - 2
          END IF
C * _computing_structure_refinement
        CASE (122)
          NWMX = MIN(NW -2, NP57)
          CCIF(22) = NWRD(2:NW - 1)
          NCIF(22) = NWMX
C * _diffrn_measurement_method
        CASE (137)
          IF (INDEX (NWRD, 'LAUE') /= 0) IPR(106) = 1
C * _diffrn_radiation_source, _diffrn_source (e.g. Rotating Anode)
        CASE (162, 492)
          IF (INDEX (NWRD, 'SYNCHROTRON') > 0) THEN
            IPR(493) = 6
            IPR(671) = 6
          END IF
C * GET ABSORPTION CORRECTION TYPE
C * _diffrn_radiation_probe
        CASE (481)
          IF (INDEX (NWRD, 'X-RAY') > 0) THEN
            IPR(630) = 0
          ELSE IF (INDEX (NWRD, 'NEUTRON') > 0) THEN
            IPR(671) = 7
            IPR(493) = 7
            IPR(630) = 1
          ELSE IF (INDEX (NWRD, 'ELECTRON') > 0) THEN
            IPR(493) = 8
            IPR(671) = 8
            IPR(630) = 2
          ELSE IF (INDEX (NWRD, 'SYNCHROTRON') > 0) THEN
            IPR(671) = 6
            IPR(630) = 3
          ELSE IF (INDEX (NWRD, 'GAMMA') > 0) THEN
C * NOT YET IMPLEMENTED
          END IF
        CASE (232)
          RLWS(3)  = ''''//NWRD(2:79)
          IPR(485) = -2
          IF (KNUM < 0) THEN
            IPR(485) = -1
          ELSE
            SELECT CASE (NWRD(2:3))
C * NONE
              CASE ('NO')
                IPR(485) = 0
C * ANALYTICAL
              CASE ('AN')
                IPR(485) = 1
C * GAUSSIAN
              CASE ('IN', 'GA')
                IPR(485) = 2
C * NUMERICAL
              CASE ('NU')
                IPR(485) = 3
C * PSI-SCAN
              CASE ('EM', 'PS')
                IPR(485) = 4
C * MULTI-SCAN
              CASE ('MU')
                IPR(485) = 5
C * REFINE/DIFABS
              CASE ('RE')
                IPR(485) = 6
C * SPHERICAL ABS CORRECTION REPORTED
              CASE ('SP')
                IPR(485) = 7
C * CYLINDER
              CASE ('CY')
                IPR(485) = 8
            END SELECT
          END IF
C * _exptl_absorpt_process_details
        CASE (233)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(19) = NWRD(2:NW-1)
            NCIF(19) = NW - 2
          END IF
C * _exptl_crystal_color
        CASE (234)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(14) = NWRD(2:NW-1)
            NCIF(14) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(14),  1, NP57)
C * _exptl_crystal_description
        CASE (239)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(5) = NWRD(2:NW-1)
            NCIF(5) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(5),  1, NP57)
C * EXTINCTION EXPRESSION
        CASE (353)
          RLWS(2) = ''''//NWRD(2:79)
C * _refine_ls_structure_factor_coef
        CASE (369)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(2) = NWRD(2:NW-1)
            NCIF(2) = NW - 2
          END IF
          IF (CCIF(2)(1:4) == 'FSQD') THEN
            CCIF(2) = 'Fsqd'
            IPR(309) = 2
          ELSE
            IPR(309) = 1
          END IF
C * _refine_ls_extinction_method
        CASE (354)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(4) = NWRD(2:NW-1)
            NCIF(4) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(4),  1, NP57)
C * _refine_ls_matrix_type
        CASE (358)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(3) = NWRD(2:NW-1)
            NCIF(3) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(3),  1, NP57)
C * _refine_ls_number_restraints
        CASE (362)
          IPR(273) = NINT(FA(1))
C * ALERT FOR MORE THAN 1 RESTRAINTS IN NON-CENTRO AND 0 FOR CENTRO
C * ALERT _860
          CALL SGSM (18, IDM, SGY, 0, 0, IERR)
          NORC = 0
          DO K = 1, 3
            IF (NINT (SGY(9 + K)) /= 0) NORC = NORC + 1
          END DO
          IF (IPR(273) > NORC) THEN
            CALL PLA236 (860, 0, -999.0, FA(1), ' ', ' ')
          END IF
C *  _refine_ls_weighting_scheme
        CASE (370)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(9) = NWRD(2 : NW - 1)
            NCIF(9) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(9), 1, 9)
C * RESET VOID VOLUME & COUNT INFO
        CASE (503)
          IF (NINT(FA(1)) == 1) THEN
            IF (IPR(651) == 0) IPR(651) = 1
            PAR(437) = 0.0
            PAR(438) = 0.0
          END IF
C * _refine_special_details
        CASE (373)
C * _reflns_observed_criterion
C * _reflns_threshold_expression
        CASE (412, 443)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(1) = NWRD(2:NW-1)
            NCIF(1) = NW - 2
          END IF
C * TEST FOR '>' AND '\'
          N1 = INDEX (CCIF(1)(1:NCIF(1)), CHAR (62))
          N2 = INDEX (CCIF(1)(1:NCIF(1)), CHAR (92))
          IF (N2 - N1 > 1) THEN
            READ (CCIF(1)(N1+1:N2-1), *, IOSTAT = IOST) YUNK
            IF (IOST == 0) THEN
              PAR(484) = YUNK
C * ALERT _966 - NON-STANDARD THRESHOLD VALUE
              IF (YUNK /= 2.0) THEN
                CALL PLA236 (966, 1, -999.0, YUNK, ' ', ' ')
              END IF
            END IF
          END IF
          CALL GEN020 (-1, CCIF(1),  1, NP57)
C * _refine_ls_weighting_details
        CASE (451)
          CALL PLA180
C * _iucr_refine_instruction(s)_details
C * _iucr_refine_instructions_details_restraints
C * _iucr_refine_instructions_details_constraints
        CASE (513, 518, 519, 520)
C * _chemical_absolute_configuration
        CASE (758)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(17) = NWRD(2:NW-1)
            NCIF(17) = NW - 2
          END IF
C * POWDER 2Thetamin
        CASE (544)
          IPR(105) = 1
C * POWDER 2Thetamax
        CASE (545)
          IPR(105) = 1
          PAR(168) = FA(1) / 2.0
C * _iucr_refine_reflections_details
        CASE (569)
          IPR(646) = 1
          IPR(660) = IPR(654)
          IPR(676) = 1
C * _reflns_Friedel_fraction_max
        CASE (572)
C * _reflns_Friedel_fraction_full
        CASE (573)
C * _shelx_res_checksum
        CASE (579)
          IF (IPR(677) == 0) THEN
            IPR(677) = -2
          ELSE
            IPR(677) = NINT (FA(1))
          END IF
C * _shelx_hkl_checksum
        CASE (581)
          IF (IPR(678) == 0) THEN
            IPR(678) = -2
          ELSE
            IPR(678) = NINT(FA(1))
          END IF
C * _diffrn_reflns_Laue_measured_fraction_max
        CASE (585)
C * _diffrn_reflns_Laue_measured_fraction_full
        CASE (586)
C * _diffrn_reflns_point_group_measured_fraction_max
        CASE (587)
C * _diffrn_reflns_point_group_measured_fraction_full
        CASE (588)
C * _reflns_Friedel_coverage
        CASE (589)
C * _shelx_fab_checksum
        CASE (602)
          IF (IPR(679) == 0) THEN
            IPR(679) = -1
          ELSE
            IPR(679) = NINT(FA(1))
          END IF
C * _diffrn_measurement_device & _diffrn_measurement_device_type'
        CASE (136, 441)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(18) = NWRD(2:NW-1)
            NCIF(18) = NW - 2
          END IF
C * LS-HYDROGEN TREATMENT
        CASE (357)
          IF (NW > 2) THEN
            IF (NW > NP57 + 2) NW = NP57 + 2
            CCIF(13) = NWRD(2:NW-1)
            NCIF(13) = NW - 2
          END IF
          CALL GEN020 (-1, CCIF(13),  1, NP57)
C * JOURNAL_NAME_FULL
        CASE (308)
          LREF(1)  = NWRD(2:NW-1)
          IPR(565) = 0
C * JOURNAL_YEAR
        CASE (321)
          LREF(2)(1:NW) = NWRD(2: NW - 1)//', '
C * JOURNAL_VOLUME
        CASE (320)
          LREF(2)(7:NW + 6) = NWRD(2:NW-1)//', '
C * JOURNAL_PAGE_FIRST
        CASE (309)
          LREF(2)(12:NW + 11) = NWRD(2:NW-1)
C * _publ_author_name
        CASE (323)
          IF (IPR(565) < 23) THEN
            IPR(565) = IPR(565) + 1
            LREF(2 + IPR(565)) = NWRD(2:NW-1)
          END IF
C * _publ_author_address
        CASE (322)
C * _publ_author_footnote
        CASE (469)
C * _publ_author_email
        CASE (532)
C * _publ_contact_author_name
C * _publ_contact_author_address
        CASE (438)
C * _publ_contact_author_email
C * _symmetry_equiv_pos_site_id & _space_group_symop_id
        CASE (480, 489)
          NSCF = NSCF + 1
          NSID(NSCF) = NINT (FA(1))
C * _symmetry_equiv_pos_as_xyz & _space_group_symop_operation_xyz
        CASE (419, 490)
          IF (IPR(319) == 0) THEN
            IPR(319) = 1
C * INIT SPACE GROUP SYMMETRY TO P1
            CALL SGSM (1, IDM, FN, 0, 0, IERR)
            IPR(48)  = 1
          END IF
C * SAVE POSSIBLE REMAINING CONTENTS
          DO J = I0 + 1, 80
            IF (ICL(J:J) /= ' ') THEN
              IGGT(1:80) = ICL(J:80)
              EXIT
            END IF
          END DO
          IFL(1)   = 'SYMM   '
          ICL      = 'SYMM '//NWRD(2:NW-1)
          IPR(220) = 1
          IPR(221) = 0
C * SAVE FOR BOND/ANGLE/TORSION VALIDATION (IFL & FN ARE DUMMY)
          IF (MODE == 0 .AND. IGBL(3) /= 14) THEN
             WRITE (LU11) ICL(1:80), (IFL(J), J = 1, 4),
     1       (FN(J), J = 1, 6)
          END IF
C * REFLECTION FILE LOOP (HKL & FCF)
C * _refln_index_h
        CASE (385)
          FN(1) = FA(1)
C * _refln_index_k
        CASE (386)
          FN(2) = FA(1)
C * _refln_index_l
        CASE (387)
          FN(3) = FA(1)
C * _refln_F_squared_calc & _refln_intensity_calc
        CASE (382, 388)
          FN(6) = FA(1)
C * _refln_F_squared_meas &_refln_intensity_meas
        CASE (383, 389)
          FN(4) = FA(1)
C * _refln_F_squared_sigma & _refln_F_intensity_sigma
        CASE (384, 390)
          FN(5) = FA(1)
          IF (NLPM == 5) CALL PLA175 (0)
C * _refln_observed_status, _refln_include_status
        CASE (392, 763)
          IF (NLPM > 5) CALL PLA175 (1)
C * Cromer_Mann scat. fact & DISPERSION LOOP
C * _atom_type_symbol
        CASE (70)
          CALL GEN020 (1, NWRD, 2, NW - 1)
          IF (NW == 3) THEN
            ELTYPE = ' '//NWRD(2:2)
          ELSE
            CALL GEN020 (-1, NWRD, 3, 3)
            ELTYPE = NWRD(2:3)
          END IF
          NELTYPE = 1
          IF (IPR(761) > 0) THEN
            DO I = 1, IPR(761)
              IF (DISPTYPE(I, 1) == ELTYPE) THEN
                NELTYPE = 0
              END IF
            END DO
          END IF
          IF (NELTYPE == 1) THEN
          IPR(761) = IPR(761) + 1
            DISPTYPE(IPR(761), 1) = ELTYPE
          END IF
C * _atom_type_scat_dispersion_real
        CASE (67)
          DISPVAL(IPR(761), 1) = FA(1)
C * _atom_type_scat_dispersion_imag
        CASE (66)
          DISPVAL(IPR(761), 2) = FA(1)
C * _atom_type_scat_source
        CASE (68)
C * HANDLE INFO BETWEEN SEMI-COLUMNS
          IF (ISEMCOL == 1) THEN
            DO
              READ (LU1, 99997) ICL
              IF (ICL(1:1) == ';') THEN
                ISEMCOL = 0
                EXIT
              END IF
            END DO
          ELSE
            IF (INDEX(NWRD(2 : NW - 1), 'NOSPHERA2') > 0) IPR(775) = 1
          ENDIF
C * _atom_type_scat_Cromer_Mann_a1
        CASE (57)
          IPR(762) = IPR(762) + 1
          CIFSF(IPR(762), 1, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_b1
        CASE (61)
          CIFSF(IPR(762), 2, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_a2
        CASE (58)
          CIFSF(IPR(762), 3, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_b2
        CASE (62)
          CIFSF(IPR(762), 4, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_a3
        CASE (59)
          CIFSF(IPR(762), 5, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_b3
        CASE (63)
          CIFSF(IPR(762), 6, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_a4
        CASE (60)
          CIFSF(IPR(762), 7, 1) = FA(1)
C * _atom_type_scat_Cromer_Mann_b4
        CASE (64)
          CIFSF(IPR(762), 8, 1) = FA(1)
