          LINE     = 'ANGLE '
          IFL(1)   = NWRD(2:NW - 1)
          FN(3)    = 1.555
          FN(4)    = 1.555
          FN(5)    = 1.555
C * _geom_angle_atom_site_label_2
        CASE (259)
