          IFL(1)   = NWRD(2:NW - 1)
          FN(3)    = 1.555
          FN(4)    = 1.555
          FN(5)    = 1.555
          FN(6)    = 1.555
C * _geom_torsion_atom_site_label_2
        CASE (280)
          IFL(2) = NWRD(2:NW - 1)
C * _geom_torsion_atom_site_label_3
        CASE (281)
          IFL(3) = NWRD(2:NW - 1)
C * _geom_torsion_atom_site_label_4
        CASE (282)
          IFL(4) = NWRD(2:NW - 1)
C * _geom_torsion
        CASE (278)
          FN(1)  = FA(1)
          FN(2)  = FA(2)
C * _geom_torsion_site_symmetry_1
        CASE (284)
          FN(3)  = FA(1)
C * _geom_torsion_site_symmetry_2
        CASE (285)
          FN(4)  = FA(1)
C * _geom_torsion_site_symmetry_3
        CASE (286)
          FN(5)  = FA(1)
C * _geom_torsion_site_symmetry_4
        CASE (287)
          FN(6)  = FA(1)
C * H-BOND
C * _geom_hbond_atom_site_label_D
        CASE (426)
          IPR(751) = 1
          LINE     = 'HBOND '
          IFL(1)   = NWRD(2:NW - 1)
          FN(9)    = 1.555
          FN(10)   = 1.555
          FN(11)   = 1.555
C * _geom_hbond_atom_site_label_H
        CASE (427)
          IFL(2) = NWRD(2:NW - 1)
C * _geom_hbond_atom_site_label_A
        CASE (428)
          IFL(3) = NWRD(2:NW - 1)
C * _geom_hbond_distance_DH
        CASE (429)
          FN(1)  = FA(1)
          FN(2)  = FA(2)
C * _geom_hbond_distance_HA
        CASE (430)
          FN(3)  = FA(1)
          FN(4)  = FA(2)
C * _geom_hbond_distance_DA
        CASE (431)
          FN(5)  = FA(1)
          FN(6)  = FA(2)
C * _geom_hbond_angle_DHA
        CASE (432)
          FN(7)  = FA(1)
          FN(8)  = FA(2)
C * SYMMETRY D
        CASE (466)
          FN(9)  = FA(1)
C * SYMMETRY H
        CASE (467)
          FN(10) = FA(1)
C * SYMMETRY A
        CASE (433)
          FN(11) = FA(1)
C * GSAS _restr_rigid_body loop
C * _restr_rigid_body_class.class_id
        CASE (907)
          IPR(639) = 1
C * _restr_rigid_body_class.details
        CASE (908)
          IPR(639) = 1
C * _restr_rigid_body.id
        CASE (909)
          IPR(639) = 1
C * _restr_rigid_body.atom_site_label
        CASE (910)
          IPR(639) = 1
C * _restr_rigid_body.site_symmetry
        CASE (911)
          IPR(639) = 1
C * _restr_rigid_body.class_id
        CASE (912)
          IPR(639) = 1
C * _restr_rigid_body.details
        CASE (913)
          IPR(639) = 1
C * SUM & MOIETY FORMULA
C * _chemical_formula_moiety
        CASE (107)
          CALL GEN134 (NWRD, RLWS(4), 2, 80)
          RLWS(4)(80:80) = CHAR(39)
          J = INDEX (RLWS(4), 'SOLVENT')
          IF (J /= 0) RLWS(4)(j:J + 6) = 'solvent'
C * _chemical_formula_sum
        CASE (109)
          CALL GEN134 (NWRD, RLWS(5), 2, 79)
          IFL(1)  = 'FSUM'
          ICL     = RLWS(5)
          J = INDEX (RLWS(5), 'SOLVENT')
          IF (J /= 0) RLWS(5)(j:J + 6) = 'solvent'
          LRETCIF = 1
          RETURN
C * _symmetry_cell_setting & _space_group_crystal_system
C * Note: _symmetry_cell_setting superseded
        CASE (418, 483)
          IF (INDEX (NWRD, 'TRICLINIC') /= 0) THEN
            KRSYST(1) = '   triclinic'
            IPR(606)  = 1
          ELSE IF (INDEX (NWRD, 'MONOCLINIC') /= 0) THEN
            KRSYST(1) = '  monoclinic'
            IPR(606)  = 2
          ELSE IF (INDEX (NWRD, 'ORTHORHOMBIC') /= 0) THEN
            KRSYST(1) = 'orthorhombic'
            IPR(606)  = 3
          ELSE IF (INDEX (NWRD, 'TRIGONAL') /= 0) THEN
            KRSYST(1) = '    trigonal'
            IPR(606)  = 4
          ELSE IF (INDEX (NWRD, 'TETRAGONAL') /= 0) THEN
            KRSYST(1) = '  tetragonal'
            IPR(606)  = 5
          ELSE IF (INDEX (NWRD, 'HEXAGONAL') /= 0) THEN
            KRSYST(1) = '   hexagonal'
            IPR(606)  = 6
          ELSE IF (INDEX (NWRD, 'CUBIC') /= 0) THEN
            KRSYST(1) = '       cubic'
            IPR(606)  = 7
          ELSE IF (INDEX (NWRD, 'RHOMBOHEDRAL') /= 0) THEN
            IF (IPR(606) == 0) THEN
              KRSYST(1) = 'rhombohedral'
              IPR(606) = 8
            END IF
          END IF
C * _symmetry_Int_Tables_number & _space_group_IT_number
        CASE (420, 485)
C * _symmetry_space_group_name_Hall & _space_group_name_Hall (OLD & NEW FORMS)
        CASE (421, 486)
          IF (IPR(37) == 0) THEN
            IF (IPR(319) == 0) IPR(318) =  1
            IF (NW > 2) THEN
              IF (NW > NP57 + 2) NW = NP57 + 2
C * STRIP HEADER AND TRAILING BLANKS
              LINE = NWRD(2:NW-1)
              LB   = 1
              LE   = NW - 2
              NB   = 1
              NE   = NW - 2
              CALL GEN039 (0, LINE, LB, LE, NB, NE)
              CCIF(16) = LINE(NB:NE)
              NCIF(16) = NE - NB + 1
            END IF
            CALL GEN020 (-1, CCIF(16), 3, NP57)
            IF (NWRD(2:2) /= '?' .AND. NWRD(2:2) /= ' ') THEN
              IFL(1) = 'HALL'
              ICL    = 'HALL '//NWRD(2:NW-1)
              IPR(220) = 2
              IPR(221) = 0
              LRETCIF  = 1
              RETURN
            END IF
          ELSE
C * ALERT _800 - MISPLACED SYMMETRY INFO
            CALL PLA236 (-800, 0, 1.0, 1.0, ' ', ' ')
            CALL PLA236 (0, 0, 0.0, 0.0,
     1        '              '//ICL(1:50), ' ')
          END IF
C * H-M SPACEGROUP SYMBOL (OLD & NEW FORMS - 488 preferred)
        CASE (422, 917, 487, 488, 923)
C * REPORT DUPLICATION OF H-M Symbol
          IF (IPR(713) > 0)
     1      CALL PLA236 (898, 0, -999.0, 0.0, ' ', ' ')
          IF (IPR(37) == 0 .AND. IPR(713) == 0) THEN
            IPR(713) = IPR(713) + 1
            IF (IPR(319) == 0) IPR(318) =  1
            IF (NW > NP57 + 2) NW = NP57 + 2
            NB = 2
            NE = NW - 1
C * ELIMINATE BLANKS
            CALL GEN039 (0, NWRD, 2, NW -1, NB, NE)
            CCIF(6) = NWRD(NB:NE)
            NCIF(6) = NE - NB + 1
            CALL GEN020 (-1, CCIF(6), 2, NP57)
            IF (CCIF(6)(NCIF(6):NCIF(6)) == 'h') THEN
                CCIF(6)(NCIF(6):NCIF(6)) = 'H'
            ELSE IF (CCIF(6)(NCIF(6):NCIF(6)) == 'r') THEN
                CCIF(6)(NCIF(6):NCIF(6)) = 'R'
            END IF
            IF (NWRD(NB:NB) /= '?' .AND.
     1          NWRD(NB:NB) /= ' ') THEN
              IFL(1) = 'SPGR'
              ICL    = 'SPGR '//CCIF(6)(1:NCIF(6))
              JID(18:18 + NE - NB) = CCIF(6)(1:NCIF(6))
              IPR(220) = 2
              IPR(221) = 0
              LRETCIF  = 1
              RETURN
            ELSE
C * NO H-M SPACEGROUP SPECIFIED
C * ALERT _122
              CALL PLA236 (122, 0, 1.0, 1.0, ' ', ' ')
            END IF
          ELSE IF (IPR(37) > 0) THEN
C * ALERT _800 - MISPLACED SYMMETRY INFO
            CALL PLA236 (-800, 0, 1.0, 1.0, ' ', ' ')
            CALL PLA236 (0, 0, 0.0, 0.0,
     1        '              '//ICL(1:50), ' ')
          END IF
C * _space_group_ssg_name
        CASE (622)
          IGBL(140) = 1
C * ALERT _814 - (In)Commensurate Structure
          CALL PLA236 (814, 0, -999.0, 0.0, ' ', ' ')
C * NUMERAL
        CASE DEFAULT
          IF (KNUM == 1) THEN
            SELECT CASE (NLPNL)
C * ALPHA
              CASE (74)
                CALL PLA177 (4)
C * BETA
              CASE (75)
                CALL PLA177 (5)
C * GAMMA
              CASE (76)
                CALL PLA177 (6)
C * REPORTED Z  (FLOAT & INT)
              CASE (77)
                PAR(568) = FA(1)
                IPR(276) = NINT (FA(1))
                IF (ABS (PAR(568) - IPR(276)) > 0.0001)
     1            CALL PLA236 (100, 3, -999.0, PAR(568), ' ', ' ')
C * A-AXIS
              CASE (78)
                CALL PLA177 (1)
C * B-AXIS
              CASE (79)
                CALL PLA177 (2)
C * C-AXIS
              CASE (80)
                CALL PLA177 (3)
C * CELL_MEASUREMENT_TEMPERATURE
              CASE (88)
                IPR(261) = NINT (FA(1))
                IPR(220) = 1
                IPR(221) = 1
                IFL(1)   = 'TEMP'
                IFL(2)   = 'K'
                FN(1)    = FA(1)
                LRETCIF  = 1
C * CELL_MEASUREMENT_REFLNS_USED
              CASE (87)
                IPR(601) = NINT (FA(1))
C * CELL_MEASUREMENT_THETA_MAX
              CASE (89)
                PAR (228) = FA(1)
                PAR (470) = FA(1)
C * CELL_MEASUREMENT_THETA_MIN
              CASE (90)
                PAR(227) = FA(1)
C * VOLUME
              CASE (93)
                PAR(164) = FA(1)
                PAR(327) = MAX (0.0, FA(2))
C * ALERT _151
                IF (FA(2) <= 0.0 .AND. IGBL(94) == 0) THEN
                  CALL PLA236 (151, 0, 1.0, 1.0, ' ', ' ')
                ELSE
C * ROUND VOLUME
                  CALL GEN041 (PAR(164), PAR(327), IPR(313),
     1              3, IPR(314), IPR(68))
                END IF
C * MOL-WEIGHT
              CASE (110)
                PAR(308) = FA(1)
C * CELL_AMBIENT_TEMPERATURE
              CASE (133)
                IPR(310) = NINT (FA(1))
C * R(int)
              CASE (196)
                PAR(197) = FA(1)
C * R(sig)
              CASE (197, 497)
                PAR(198) = FA(1)
C * HMIN... LMAX, THETA-MIN THETA-MAX
              CASE (198, 404)
                IPR(268) = NINT (FA(1))
                IPR(672) = IPR(672) + 1
              CASE (199, 405)
                IPR(267) = NINT (FA(1))
                IPR(672) = IPR(672) + 1
              CASE (200, 406)
                IPR(270) = NINT (FA(1))
                IPR(672) = IPR(672) + 1
              CASE (201, 407)
                IPR(269) = NINT (FA(1))
                IPR(672) = IPR(672) + 1
              CASE (202, 408)
                IPR(272) = NINT (FA(1))
                IPR(672) = IPR(672) + 1
              CASE (203, 409)
                IPR(271) = NINT (FA(1))
                IPR(672) = IPR(672) + 1
C * NR REFL & PARAMETERS
              CASE (204)
C * _diffrn_reflns_number
                IPR(262) = NINT (FA(1))
C * REFLECTION -_diffrn_reflns_theta_max
              CASE (206)
                PAR(168) = FA(1)
                IF (PAR(17) > 0) PAR(287) =
     1            SIN (PAR(168) / RGBL(6)) / PAR(17)
C * REFLECTION -THETA-MIN
              CASE (207)
                PAR(167) = FA(1)
C * DATA RELATED TO ABSORPTION
              CASE (229)
                PAR(301) = FA(1)
C * transmission min
              CASE (230, 582)
                PAR(306) = FA(1)
C * transmission max
              CASE (231, 583)
                PAR(307) = FA(1)
C * DENSITY(diffrn)
              CASE (235)
                PAR(267) = FA(1)
C * DENSITY(meas)
              CASE (236)
                PAR(158) = FA(1)
C * REPORTED F000
              CASE (240)
                PAR(324) = FA(1)
C * DIFF-DENS-MAX
              CASE (347)
                PAR(177) = FA(1)
C * DIFF-DENS-MIN
              CASE (348)
                PAR(176) = FA(1)
C * FLACK PARAMETER
              CASE (350)
                CALL GEN041 (FA(1), FA(2), IPR(279), 3,
     1                       IPR(280), IPR(68))
                PAR(433) = FA(1)
                PAR(434) = FA(2)
                IF (FA(2) <= 0.0 .AND. IPR(105) == 0) THEN
C * ALERT _036 - Test for no-su on Flack x
                  IF (FA(1) /= 0.500) THEN
                    CALL PLA236 (36, 3, 1.0, 1.0, ' ', ' ')
                  END IF
                ELSE
C * ALERT _032
                  IF (FA(2) > 0.2)
     1              CALL PLA236 (32, 3, -999.0, FA(2), ' ', ' ')
                END IF
C * CENTRO/NON-CENTRO CRIT FOR ADDSYM
                IF (FA(2) < 0.1 .AND. FA(2) < 0.2) IPR(773) = 1
C * ALERT _033 - TEST FOR FLACK PARAMETER VALUE OFF ZERO
                IF (FA(1) < 99999.0) THEN
C * CHECK FOR ACENTRO
                  IF (IPR(275) == 1) THEN
C * TEST FOR 'CHIRAL'
                    IF (CHSG(1:1) == 'C') THEN
                      IF (FA(1) > 3.0 * FA(2)) THEN
                        CALL PLA236 (33, 3, -999.0, FA(1), ' ', ' ')
                      END IF
                    END IF
                  ELSE
C * ALERT _781 - NO FLACK PARAMETER FOR CENTRO STRUCTURE
                    CALL PLA236 (781, 0, 1.0, 1.0, ' ', ' ')
                  END IF
C * ALERT _907 - Flack x > 0.5
                  CALL PLA236 (907, 2, PAR(433), PAR(433), ' ', ' ')
                END IF
C * ALERT _850
                IF (FA(1) == 0.0 .AND. FA(2) > 0.0)
     1            CALL PLA236 (850, 2, -999.0, FA(2), ' ', ' ')
C * XTAL-SIZE-MAX
              CASE (251)
                PAR(302) = FA(1)
C * XTAL-SIZE-MID
              CASE (252)
                PAR(303) = FA(1)
C * XTAL-SIZE-MIN
              CASE (253)
                PAR(304) = FA(1)
C * XTAL-RADIUS
              CASE (254)
                PAR(305) = FA(1)
C * EXTINCTION PARAMETER
              CASE (352)
                RATIO = 0.0
                IF (FA(2) > 0.0) THEN
                  IF (FA(1) < 0.1 * FA(2)) THEN
                    RATIO1 = 10.0
                  ELSE
                    RATIO  = FA(1) / FA(2)
                    RATIO1 = 1.0 / RATIO
                  END IF
C * ALERT _031
                  CALL PLA236 (31, 3, RATIO1, RATIO, ' ', ' ')
                END IF
                IF (FA(2) > 0.0) THEN
                  CALL GEN041 (FA(1), FA(2), IPR(277), -8,
     1                         IPR(278), IPR(68))
                ELSE
                  IPR(277) = 0
                END IF
                PAR(229) = FA(1)
C * S(all/ref/obs)
              CASE (355, 447, 356)
                PAR(299) = FA(1)
C * NUMBER OF L.S.-PARAMETERS
              CASE (360)
                IPR(266) = NINT (FA(1))
C * NUMBER OF UNIQUE REFLECTIONS _refine_ls_number_reflns
              CASE (361)
                IPR(265) = NINT (FA(1))
C * NUMBER OF UNIQUE REFLEXTIONS _reflns_number_all
              CASE (906)
                IPR(765) = NINT (FA(1))
C * R-all
              CASE (363)
                IF (FA(1) > 1.0) FA(1) = FA(1) * 0.01
                PAR(309) = FA(1)
C * R-obs/gt  _refine_ls_R_factor_gt
              CASE (364, 445)
                IF (FA(1) > 1.0) FA(1) = FA(1) * 0.01
                PAR(173) = FA(1)
                WRITE (JID(31:38), 99999, IOSTAT = IOST) FA(1)
C * S(Restrained-obs)
              CASE (365)
                PAR(300) = FA(1)
C * SHIFT/ESD(SU)-MAX
              CASE (367, 448)
                IF (PAR(178) < 0.0) PAR(178) = FA(1)
C * SHIFT/ESD(SU)-MEAN
              CASE (368, 461)
                PAR(179) = FA(1)
C * wR-All/Ref
              CASE (371, 446)
                IF (FA(1) > 1.0) FA(1) = FA(1) * 0.01
                PAR(174) = FA(1)
C * wR-obs/gt
              CASE (372, 460)
                IF (FA(1) > 1.0) FA(1) = FA(1) * 0.01
                PAR(310) = FA(1)
C * _reflns_number_total
              CASE (410)
                IPR(263) = NINT (FA(1))
C * _reflns_number_observed
              CASE (411)
                IPR(264) = NINT (FA(1))
C * _reflns_number_gt
              CASE (442)
                IPR(264) = NINT (FA(1))
C * _diffrn_reflns_theta_full
              CASE (444)
                PAR(312) = FA(1)
C * MEAS FRACTION THETA-MAX
              CASE (458)
                PAR(313) = FA(1)
C * MEAS FRACTION THETA-FULL
              CASE (459)
                PAR(314) = FA(1)
C * DIFF-DENS-RMS
              CASE (462)
                PAR(175) = FA(1)
C * SHIFT/ESD(SU)-MAX_LT
              CASE (511)
                IF (PAR(178) < 0.0) PAR(178) = FA(1)
C * HOOFT PARAMETER
              CASE (512)
                CALL GEN041 (FA(1), FA(2), IPR(615), 3,
     1                       IPR(616), IPR(68))
                PAR(435) = FA(1)
                PAR(436) = FA(2)
C * FACE LOOP (H,K,K,D)
C * _exptl_crystal_face_index_h
              CASE (245)
                FN(1) = FA(1)
C * _exptl_crystal_face_index_k
              CASE (246)
                FN(2) = FA(1)
C * _exptl_crystal_face_index_l
              CASE (247)
                FN(3) = FA(1)
C * _exptl_crystal_face_perp_dist
              CASE (248)
                IF (FA(1) > 0.0) THEN
                  FN(4)    = FA(1)
                  IPR(220) = 1
                  IPR(221) = 4
                  IFL(1)   = 'FACE'
                  LRETCIF  = 1
                END IF
            END SELECT
          END IF
      END SELECT
      RETURN
99999 FORMAT ('R =', F5.2)
99998 FORMAT (':: ERROR: Wavelength = NOT-A-NUMBER', A)
99997 FORMAT (A)
99996 FORMAT (':: INCLUDE FILE ', A)
      END SUBROUTINE PLA174
 
      SUBROUTINE PLA175 (MODE)
C * GENERATE HKL AND/OR FCF FROM CIF EMBEDDED LOOP(S)
      USE files
      USE parameters
      USE cchar
      USE cif
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: MODE
      REAL :: RATIO
      IPR(321) = IPR(321) + 1
 
C * CHECK FOR UNUSUAL (CALCULATED) DATA
      IF (FN(4) > 0.0 .AND. FN(5) /= 0.0) THEN
        IF (IPR(741) == 0) REWIND (UNIT = LU67, IOSTAT = IOST)
        RATIO    = FN(5) / SQRT (FN(4))
        PAR(555) = PAR(555) + RATIO
        IPR(741) = IPR(741) + 1
        WRITE (LU67) RATIO
      END IF
C * 'CIF' embedded HKL loop
      IF (MODE == 0) THEN
        IF (IPR(321) == 1) THEN
          INQUIRE (UNIT = LU25, OPENED = OPEND)
          IPR(664) = -1
          IF (OPEND) THEN
            REWIND (LU25, IOSTAT = IOST)
          ELSE
            OPEN (UNIT = LU25, FILE =
     1      NAMEFIL(1:KNMFIL)//'_sx.hkl',
     2      STATUS = 'UNKNOWN', IOSTAT = IOST)
            IF (IOST /= 0) REWIND (UNIT = LU25, IOSTAT = IOST)
          END IF
        END IF
C * MAKE SURE THAT INTENSITY FITS WITHIN THE SHELXL HKLF FORMAT
        IF (FN(4) < 99999.0) THEN
          WRITE (LU25, 99998)
     1      (NINT (FN(I)), I = 1, 3), (FN(I), I = 4, 5)
        ELSE IF (FN(4) < 999999.0) THEN
          WRITE (LU25, 99997)
     1      (NINT (FN(I)), I = 1, 3), (FN(I), I = 4, 5)
        ELSE IF (FN(4) < 9999999.0) THEN
          WRITE (LU25, 99996)
     1      (NINT (FN(I)), I = 1, 3), (FN(I), I = 4, 5)
        END IF
C * EXPORT 'EMBEDDED' FCF
      ELSE IF (MODE == 1) THEN
        IF (IPR(321) == 1) THEN
C * COPY JANA CIF EMBEDDED 'FCF' TO EXTERNAL FCF
          OPEN (UNIT = LU28, FILE = NAMEFIL(1:KNMFIL)//'_sx.fcf',
     1      STATUS = 'UNKNOWN', IOSTAT = IOST)
          WRITE (LU28, 99999)
        END IF
        WRITE (LU28, 99995)
     1    (NINT (FN(I)), I = 1, 3), FN(6), FN(4), FN(5), NWRD(1:2)
      END IF
      RETURN
99999 FORMAT ('data_I', /,
     1        '_shelx_refln_list_code 4', /,
     2        'loop_', /,
     3        ' _refln_index_h',/,
     4        ' _refln_index_k', /,
     5        ' _refln_index_l', /,
     6        ' _refln_F_squared_calc', /,
     7        ' _refln_F_squared_meas', /,
     8        ' _refln_F_squared_sigma' /,
     9        ' _refln_include_status')
99998 FORMAT (3I4, 2F8.2)
99997 FORMAT (3I4, 2F8.1)
99996 FORMAT (3I4, 2F8.0)
99995 FORMAT (3I4, 3F10.2, A)
      END SUBROUTINE PLA175
 
      SUBROUTINE PLA176 (ICH, KEYWRD)
C * HANDLE CELL/CIF
      USE files
      USE parameters
      USE cif
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      CHARACTER(len=1)   :: ICH
      CHARACTER(len=1)   :: ICHU
      CHARACTER(len=NKW) :: UCIFD
      CHARACTER(len=NKW) :: KEYWRD
C * CONTINUE/FINISH BUILDING THE KEYWORD
      LRETCIF = 0
      ICHU    = ICH
      CALL GEN020 (1, ICHU, 1, 1)
C * CHECK FOR END-OF-KEYWORD
      IF (ICH /= CHAR(32)) THEN
C * HANDLE NEW CANONICAL KEYWORD FORMAT ('_' <> '.')
        IF (ICH == '.') ICH = '_'
C * CHECK FOR MAX KEYWORD LENGTH
        IF (KW < NKW) THEN
          KW            = KW + 1
          KEYWRD(KW:KW) = ICH
        END IF
C * HANDLE KEYWORD
      ELSE
        NLPM = NLPM + 1
C * CHECK FOR MAXIMUM NUMBER OF LOOP ENTRIES
        IF (NLPM <= NP58) THEN
          NLP(NLPM) = 0
C * REPORT KEYWORD LOOP NUMBER OVERFLOW
        ELSE
          IPR(2)  = 60
C * ERROR
          LRETCIF = 2
          RETURN
        END IF
        IPR(751) = 0
C * CHECK FOR OFFICIAL KEYWORDS (I = 1) OR UPPERCASE VARIANT (I = 2)
        DO I = 1, 2
          IF (I == 2) CALL GEN020 (-1, KEYWRD, 1, NKW)
          DO J = 1, NP34
            UCIFD = CIFDIR(J)
            IF (I == 2) CALL GEN020 (-1, UCIFD,  1, NKW)
            IF (KEYWRD == UCIFD) THEN
              IF (NLPM <= NP58) THEN
C * CHECK FOR EMPTY BOND LOOP
                IF (NLP(1) == 265) THEN
                  IF (J < 265 .OR. J > 270) THEN
                    NLPM  = 1
                    ILOOP = 0
                  END IF
C * CHECK FOR EMPTY ANGLE LOOP
                ELSE IF (NLP(1) == 258) THEN
                  IF (J < 257 .OR. J > 264) THEN
                    NLPM  = 1
                    ILOOP = 0
                  END IF
C * CHECK FOR EMPTY TORSION LOOP
                ELSE IF (NLP(1) == 279) THEN
                  IF (J < 278 .OR. J > 288) THEN
                    NLPM  = 1
                    ILOOP = 0
                  END IF
                END IF
                NLP(NLPM) = J
C * REPORT KEYWORD LOOP NUMBER OVERFLOW
              ELSE
                IPR(2)  = 60
                LRETCIF = 2
                RETURN
              END IF
              GO TO 10
            END IF
          END DO
        END DO
        J  = 0
        IF (KEYWRD(1:5) /= '_vrf_' .AND.
     1    KEYWRD(1:4) /= '_pd_' .AND.
     2    KEYWRD(1:11) /= '_jana_atom_') THEN
          IPR(429) = IPR(429) + 1
C * COUNT _atom_site_anharm_GC* datanames in CIF
          IF (KEYWRD(1:20) == '_atom_site_anharm_gc' .OR.
     1        KEYWRD(1:20) == '_atom_site_anharm_GC') THEN
            IPR(756) = IPR(756) + 1
          ELSE
            IF (KEYWRD(1:6) /= '_stoe_' .AND.
     1          KEYWRD(1:9) /= '_publcif_') THEN
              WRITE (LU6, 99999, IOSTAT = IOST) KEYWRD
            END IF
          END IF
        END IF
C * CHECK FOR POWDER DATANAMES
        IF (KEYWRD(1:4) == '_pd_') IPR(105) = 1
   10   CALL GEN038 (KEYWRD, 1, NKW)
        KW = 0
C * CHECK FOR '_refln_index_h'
        IF (J == 385) THEN
C * TEST FOR SYSTEM - S
          IF (IGBL(3) == 14) THEN
            LRETCIF = 3
            RETURN
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT ('W: Keyword NOT in PLATON/CIFDIR - Ignored:', /, 3X, A)
      END SUBROUTINE PLA176
 
      SUBROUTINE PLA177 (N)
C * HANDLE CELL DATA
      USE parameters
      USE cif
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: N
      INTEGER, SAVE :: M
C * REGISTER UNTIL 6 CELL PARAMETERS
      IF (N /= 0) THEN
        CELL(N)     = FA(1)
        CELL(6 + N) = FA(2)
        M           = M + 1
C * CELL DATA COMPLETE
        IF (M == 6) THEN
          IFL(1) = 'CELL'
          DO I = 1, 12
            FN(I) = CELL(I)
          END DO
          IPR(220) = 1
          IPR(221) = 6
          LRETCIF  = 1
        END IF
C * N = 0: INIT
      ELSE
        M       = 0
        LRETCIF = 0
      END IF
      RETURN
      END SUBROUTINE PLA177
 
      SUBROUTINE PLA178
C * INSPECT .RES FILE CONTENT
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE sgxyz
      USE cif
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: N
      INTEGER       :: N1
      INTEGER       :: N2
      INTEGER       :: N3
      INTEGER       :: KL
      INTEGER       :: KN
      INTEGER       :: JUNK
      INTEGER       :: IYUNK
      INTEGER       :: JUNK1
      INTEGER       :: NRSYM
      INTEGER, SAVE :: ITEMP
      INTEGER, SAVE :: NRFABSF
      INTEGER, SAVE :: NRFABU
      REAL :: YUNC
      REAL :: YUNK
      REAL :: YUNK1
      REAL, DIMENSION(99), SAVE :: FVAR
      CHARACTER(len=4) :: KEY
      CHARACTER(len=2) :: ELTYP
      KEY = ICL(1:4)
C * UPPER CASE
      CALL GEN020 (1, KEY, 1, 4)
      CALL GEN074 (FN, 1, 13, 0.0)
C * TITL
      IF (KEY == 'TITL') THEN
        ITEMP = -2
C * CHECK CELL REPORTED WAVELENGTH AGAINST CIF REPORTED VALUE
      ELSE IF (KEY == 'CELL') THEN
        IF (PAR(17) > 0.0) THEN
          READ (ICL(5:80), *, IOSTAT = IOST) FN(1)
          IF (ABS(PAR(17) - FN(1)) > 0.0001) THEN
C * ALERT _105
            CALL PLA236 (105, 0, 1.0, 0.0, ' ', ' ')
          END IF
        END IF
C * REPORT ON EXPLICITLY SUPPLIED SCATTERING FACTOR DATA
      ELSE IF (KEY == 'SFAC') THEN
        N = INDEX (ICL(1:80), '=')
        IF (N > 0) THEN
          N = N - 1
        ELSE
          N = 80
        END IF
        CALL GEN072 (ICL, IFL, FN, KL, KN, 0, 0, 1, 1, N, 7, NP17)
        IF (KN >= 5) THEN
          IPR(763) = IPR(763) + 1
          IF (IFL(2)(2 : 2) == ' ') THEN
            ELTYP = ' '//IFL(2)(1:1)
          ELSE
            ELTYP = IFL(2)(1:2)
          END IF
          DISPTYPE(IPR(763), 2) = ELTYP
          DO I = 1, KN
            CIFSF(IPR(763), I, 2) = FN(I)
          END DO
        END IF
C * REGISTER FVAR VALUE
      ELSE IF (KEY == 'FVAR') THEN
       READ (ICL(5:80), *, IOSTAT = IOST) (FVAR(I), I = 1, 10)
       PAR(74) = FVAR(1)
C * REGISTER WEIGHT PARAMETER VALUES
      ELSE IF (KEY == 'WGHT') THEN
        FN(6) = 1.0 / 3.0
        READ (ICL(5:80), *, IOSTAT = IOST) (FN(I), I = 1, 6)
        IF (PAR(563) < 0.0) PAR(563) =
     1    ABS (FN(3)) + ABS (FN(4)) + ABS (FN(5)) + ABS (FN(6))
     2    - 1.0 / 3.0
        IF (PAR(559) < 0.0) THEN
          PAR(559) = FN(1)
          PAR(560) = FN(2)
        ELSE
          PAR(561) = FN(1)
          PAR(562) = FN(2)
        ENDIF
C * GET # OF PART -N RECORDS IN THE CIF-EMBEDDED RES
      ELSE IF (KEY == 'PART') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) JUNK
        IF (JUNK < 0) IPR(780) = IPR(780) + 1
C * GET NEXTRA (SQUEEZE)
      ELSE IF (KEY == 'L.S.') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) JUNK, JUNK, IPR(767)
C * REPORT ON AFIX 1 RECORDS
      ELSE IF (KEY == 'AFIX') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) YUNK
        IF (IOST == 0) THEN
          IF (NINT (YUNK) == 1) IPR(709) = IPR(709) + 1
        END IF
C * REPORT ON DAMP INSTRUCTION IN EMBEDDED RES FILE
      ELSE IF (KEY == 'DAMP') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) YUNK
C * ALERT _936
        IF (IOST == 0) THEN
          IF (YUNK == 0.0) THEN
          YUNC = 2
          ELSE IF (YUNK > 0.7) THEN
            YUNC = 1
          ELSE
            YUNC = 0.001
          END IF
          CALL PLA236 (936, 1, YUNC, YUNK, ' ', ' ')
        END IF
C * TEST FOR AND REGISTER ABIN INSTRUCTION IN EMBEDDED .res
      ELSE IF (KEY == 'ABIN') THEN
        IPR(766) = 1
        IF (IPR(651) < 10) IPR(651) = IPR(651) + 10
        NRFABSF = 0
        NRFABU  = 0
        READ (ICL(5:80), *, IOSTAT = IOST) NRFABSF, NRFABU
C * REGISTER MERG INSTRUCTION
      ELSE IF (KEY == 'MERG') THEN
        IPR(703) = 1
        READ (ICL(5:20), *, IOSTAT = IOST) IPR(719)
C * REGISTER EXYZ CONSTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'EXYZ') THEN
        IPR(684) = IPR(684) + 1
C * REGISTER EADP CONSTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'EADP') THEN
        IPR(685) = IPR(685) + 1
C * REGISTER DFIX RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'DFIX') THEN
        IPR(686) = IPR(686) + 1
C * ALERT _195
        IF (FN(2) /= 0.0 .AND. FN(2) /= 0.02)
     1    CALL PLA236 (195, 4, -999.0, FN(2), ' ', ' ')
C * REGISTER DANG RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'DANG') THEN
        IPR(687) = IPR(687) + 1
C * ALERT _167
        IF (FN(2) /= 0.0 .AND. FN(2) /= 0.02)
     1    CALL PLA236 (167, 4, -999.0, FN(2), ' ', ' ')
C * REGISTER FLAT RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'FLAT') THEN
        IPR(688) = IPR(688) + 1
C * REGISTER SAME RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'SAME') THEN
        IPR(689) = IPR(689) + 1
C * ALERT _189 - CHECK FOR NON-DEFAULT CONSTRAINT VALUE
        READ (ICL(5:80), *, IOSTAT = IOST) FN(1), FN(2)
        IF (FN(1) /= 0.0 .AND. FN(1) /= 0.02)
     1    CALL PLA236 (189, 4, -999.0, FN(1), 'First Par', ' ')
        IF (FN(2) /= 0.0 .AND. FN(2) /= 0.04)
     1    CALL PLA236 (189, 4, -999.0, FN(2), 'SecondPar', ' ')
C * REGISTER SADI RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'SADI') THEN
        IPR(690) = IPR(690) + 1
C * ALERT _191 - CHECK FOR NON-DEFAULT CONSTRAINT VALUE
        READ (ICL(5:80), *, IOSTAT = IOST) FN(1)
        IF (FN(1) /= 0.0 .AND. FN(1) /= 0.02)
     1    CALL PLA236 (191, 4, -999.0, FN(1), ' ', ' ')
C * REGISTER DELU RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'DELU') THEN
        IPR(691) = IPR(691) + 1
C * ALERT _192 - CHECK FOR NON-DEFAULT CONSTRAINT VALUE
        READ (ICL(5:80), *, IOSTAT = IOST) FN(1), FN(2)
        IF (FN(1) /= 0.0 .AND. FN(1) /= 0.01)
     1    CALL PLA236 (192, 4, -999.0, FN(1), 'First Par', ' ')
        IF (FN(2) /= 0.0 .AND. FN(2) /= 0.01)
     1    CALL PLA236 (192, 4, -999.0, FN(2), 'SecondPar', ' ')
C * REGISTER SIMU RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'SIMU') THEN
        IPR(692) = IPR(692) + 1
C * ALERT _188 - CHECK FOR NON-DEFAULT CONSTRAINT VALUE
        READ (ICL(5:80), *, IOSTAT = IOST) FN(1)
        IF (FN(1) /= 0.0 .AND. FN(1) /= 0.04)
     1    CALL PLA236 (188, 4, -999.0, FN(1), ' ', ' ')
C * REGISTER CHIV RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'CHIV') THEN
        IPR(693) = IPR(693) + 1
C * REGISTER ISOR RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'ISOR') THEN
        IPR(694) = IPR(694) + 1
C * REGISTER RIGU RESTRAINT INSTRUCTION RECORD(S)
      ELSE IF (KEY == 'RIGU') THEN
        IPR(710) = IPR(710) + 1
C * ALERT _190 - CHECK FOR NON-DEFAULT RESTRAINT VALUE
        READ (ICL(5:80), *, IOSTAT = IOST) FN(1), FN(2)
        IF (FN(1) /= 0.0 .AND. FN(1) /= 0.004)
     1    CALL PLA236 (190, 4, -999.0, FN(1), 'First Par', ' ')
        IF (FN(2) /= 0.0 .AND. FN(2) /= 0.004)
     1    CALL PLA236 (190, 4, -999.0, FN(2), 'SecondPar', ' ')
C * CHECK FOR NON-DEFAULT DEFS RESTRAINT VALUE
      ELSE IF (KEY == 'DEFS') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) (FN(I), I = 1, 5)
        IF (FN(1) /= 0.0 .AND. FN(1) /= 0.02)
     1    CALL PLA236 (194, 4, -999.0, FN(1), ' for sd', ' ')
        IF (FN(2) /= 0.0 .AND. FN(2) /= 0.1)
     1    CALL PLA236 (194, 4, -999.0, FN(2), ' for sf', ' ')
        IF (FN(3) /= 0.0 .AND. FN(3) /= 0.01)
     1    CALL PLA236 (194, 4, -999.0, FN(3), ' for su', ' ')
        IF (FN(4) /= 0.0 .AND. FN(4) /= 0.04)
     1    CALL PLA236 (194, 4, -999.0, FN(4), ' for ss', ' ')
        IF (FN(5) /= 0.0 .AND. FN(5) /= 1.0)
     1    CALL PLA236 (194, 4, -999.0, FN(5), ' maxsof', ' ')
C * REGISTER SWAT INSTRUCTION
      ELSE IF (KEY == 'SWAT') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) PAR(501), PAR(502)
        IPR(698) = 1
      ELSE IF (KEY == 'EXTI') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) PAR(226)
C * CHECK FOR LIST 6 OR 8
      ELSE IF (KEY == 'LIST') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) IYUNK
        IF (IYUNK == 8) THEN
          CALL PLA236 (766, 0, 1.0, 0.0, ' ', ' ')
        ELSE IF (IYUNK == 6) THEN
          CALL PLA236 (767, 0, 1.0, 0.0, ' ', ' ')
        END IF
C * CHECK HKLF RECORD
      ELSE IF (KEY == 'HKLF') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) (FN(I), I = 1, 13)
        IF (FN(12) /= 0.0 .AND. FN(12) /= 1) THEN
          PAR(573) = FN(12)
C * ALERT _610 - NON-STANDARD SCALING FACTOR FOR SIG(I) OM HKLF
          CALL PLA236 (610, 2, -999.0, PAR(573), ' ', ' ')
        END IF
C * HANDLE ABIN SCALING FACTOR & U
C * ALERT _823
        IF (NRFABSF /= 0) THEN
          PAR(575) = FVAR(NRFABSF)
          CALL PLA236 (823, 3, -999.0, PAR(575), ' ', ' ')
        END IF
C * ALERT _824
        IF (NRFABU /= 0) THEN
          PAR(576) = FVAR(NRFABU)
          CALL PLA236 (824, 3, -999.0, PAR(576), ' ', ' ')
        END IF
C * ALERT _196 - TEMP CHECK
        IF (ITEMP == -2 .AND. IPR(310) /= 293)
     1    CALL PLA236 (196, 0, 1.0, 293.0, ' ', ' ')
        READ (ICL(5:80), *, IOSTAT = IOST) IYUNK
        IF (IOST == 0) THEN
          IPR(648) = IYUNK
C * TEST FOR HKLF 2 REFINEMENT (LAUE)
          IF (IYUNK == 2) THEN
            IPR(106) = 1
C * TEST FOR HKLF 5
          ELSE IF (IYUNK == 5) THEN
            IPR(619) = 1
          END IF
        ELSE
          IPR(2)  = 70
          LRETCIF = 12
        END IF
C * TWINNING (BUT NOT INVERSION TWINNING)
      ELSE IF (KEY == 'TWIN') THEN
        N = 10
        DO
          READ (ICL(5:80), *, IOSTAT = IOST) (FN(I), I = 1, N)
          IF (IOST == 0) THEN
            EXIT
          ELSE
            N = N - 1
            IF (N == 0) EXIT
          END IF
        END DO
C * REGISTER TWINNING
        IF (N >= 9) THEN
          IPR(619) = 1
          IPR(779) = 0
          JUNK     = 0
          JUNK1    = 0
C * LOOP OVER SPACE GROUP SYMMETRY TO CHECK FOR 'FLACK INVERSION TWINNING'
          DO I = 1, IPR(48)
            NRSYM = I
            YUNK  = 0.0
            YUNK1 = 0.0
            IERR  = 0
            CALL SGSM (6, LINE, SGX, NRSYM, 0, IERR)
            DO J = 1, 9
              YUNK  = YUNK  + ABS (SGX(J) + FN(J))
              YUNK1 = YUNK1 + ABS (SGX(J) - FN(J))
            END DO
            IF (YUNK < 0.01) THEN
              JUNK = I
              IF (JUNK == 1) THEN
                IPR(619) = 0
              ELSE IF (JUNK > 1) THEN
C * REGISTER AS FLACK TWIN
                IPR(619) = 0
                IPR(779) = 1
C * ALERT _109 - Twinning Matrix is Alternate Inversion Twinning
                IF (IPR(257) == 1) THEN
                  IF (JUNK > 1)
     1              CALL PLA236 (109, 1, FLOAT (JUNK), FLOAT (JUNK),
     2                '  ', ' ')
C * ALERT _107 - Twinning Matrix Invalid in Centrosymmetric Space Group
                ELSE
                  CALL PLA236 (107, 1, FLOAT (JUNK), FLOAT (JUNK),
     1              ' ', ' ')
                END IF
              END IF
              EXIT
            END IF
            IF (YUNK1 < 0.01) THEN
              JUNK1 = I
              IF (JUNK1 > 0) THEN
                IPR(619) = 0
                IPR(779) = 1
C * ALERT _108 - Twinning Matrix is inverted Laue Group operation
                CALL PLA236 (108, 1, FLOAT (JUNK1), FLOAT (JUNK1),
     1            ' ', ' ')
                EXIT
              END IF
            END IF
          END DO
        END IF
        IF (IPR(619) == 0) IPR(193) = IPR(193) + 100
        IPR(705) = IPR(705) + 1
C * TEMP
      ELSE IF (KEY == 'TEMP') THEN
        ITEMP = -1
C * BASF
      ELSE IF (KEY == 'BASF') THEN
        IPR(193) = IPR(193) + 1
        IPR(705) = IPR(705) + 1
C * CATCH DISP MU VALUE
      ELSE IF (KEY == 'DISP') THEN
        CALL GEN020 (1, ICL, 1, 80)
        DO K = 1, IAN
          ELTYP = DISPTYPE(K, 1)
          CALL GEN020 (1, ELTYP, 1, 2)
          J = INDEX (ICL(5:80), ELTYP)
          IF (J /= 0) THEN
            READ (ICL(J + 7: 80), *, IOSTAT = IOST)
     1        FN(1), FN(2), FN(3)
            IF (IOST == 0) THEN
              IF (DISPVAL(K, 3) == 0.0) DISPVAL(K, 3) = FN(3)
            END IF
          END IF
        END DO
C * REGISTER NUMBER OF OMIT RECORDS
      ELSE IF (KEY == 'OMIT') THEN
        READ (ICL(5:80), *, IOSTAT = IOST) N1, N2, N3
        IF (IOST == 0) THEN
          IF (IABS (N1) + IABS (N2) + IABS (N3) > 0) THEN
            IPR(714) = IPR(714) + 1
            IF (IPR(714) <= NP78) THEN
              NOMIT(1, IPR(714)) = N1
              NOMIT(2, IPR(714)) = N2
              NOMIT(3, IPR(714)) = N3
            END IF
          END IF
C * _967 - THETA CUTOFF OMIT RECORD
        ELSE
          READ (ICL(5:80), *, IOSTAT = IOST) YUNK, YUNK1
          IF (IOST == 0) THEN
            PAR(500) = YUNK1
            IF (YUNK1 < 180.0)
     1        CALL PLA236 (967, 1, -999.0, PAR(500), ' ', ' ')
          END IF
        END IF
C * REGISTER INCLUDE FILE
      ELSE IF (ICL(1:1) == '+') THEN
        IPR(738)    = -1
        INCLUDEFILE = ICL(2:80)
C * REGISTER LONE/BEDE
      ELSE IF (KEY == 'BEDE' .OR. KEY == 'LONE') THEN
        IPR(757) = IPR(757) + 1
      END IF
      RETURN
      END SUBROUTINE PLA178
 
      REAL FUNCTION PLA179 (IH, IK, IL, OBS, CALC, SIGOBS)
C * CALCULATE SIGIW
      USE parameters
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      REAL :: P
      REAL :: Q
      REAL :: F1
      REAL :: F2
      REAL :: F3
      REAL :: OBS
      REAL :: CALC
      REAL :: SIGOBS
      REAL :: GEN095
C * PAR_A = PAR(493)
C * PAR_B = PAR(494)
C * PAR_C = PAR(495)
C * PAR_D = PAR(496)
C * PAR_E = PAR(497)
C * PAR_F = PAR(498)
      P  = PAR(498) * MAX (OBS, 0.0) + (1.0 - PAR(498)) * CALC
      F2 = SIGOBS**2 + (PAR(493)*P)**2 + PAR(494) * P + PAR(496)
C * CHECK FOR NONZERO PAR_C OR PAR_E
      IF (PAR(495) /= 0.0 .OR. PAR(497) /= 0.0) THEN
        Q = GEN095(PAR(191), IH, IK, IL)
      END IF
      IF (PAR(495) > 0.0) THEN
        F1 = EXP (PAR(495) * Q)
      ELSE IF (PAR(495) < 0.0) THEN
        F1 = 1.0 - EXP (PAR(495) * Q)
      ELSE
        F1 = 1.0
      END IF
      IF (PAR(497) /= 0.0) THEN
        F3 = PAR(497) * SQRT (Q)
      ELSE
        F3 = 0.0
      END IF
      PLA179 = SQRT (F2 + F3 / F1)
      END FUNCTION PLA179
 
      SUBROUTINE PLA180
C * PARSE WEIGHT EXPRESSION
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cif
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: JB
      INTEGER :: JC
      INTEGER :: JD
      INTEGER :: JE
      INTEGER :: JX
      INTEGER :: JEP
      INTEGER :: IER
      INTEGER :: ISTP
      REAL :: PAR_A
      REAL :: PAR_B
      REAL :: PAR_C
      REAL :: PAR_D
      REAL :: PAR_E
      REAL :: PAR_F
C * HANDLE WEIGHT EXPRESSION
      PAR_A = 0.0
      PAR_B = 0.0
      PAR_C = 0.0
      PAR_D = 0.0
      PAR_E = 0.0
      PAR_F = 0.33333
      M1    = 0
      M2    = 0
      IER   = 0
      RLWS(1) = ''''//NWRD(2 : NP70)
C * MoPro STYLE WEIGHT
      IF (IPR(725) == 9) THEN
        RLWS(1) = ' w'//NWRD(9 : NP70)
        N = INDEX (RLWS(1), 'S')
        IF (N /= 0) RLWS(1)(N : N) = 's'
        N = INDEX (RLWS(1), 'FO')
        IF (N /= 0) RLWS(1)(N : N + 1) = 'Fo'
      END IF
C * SHELXL20xy REFINEMENT STYLE WEIGHT
      IF (IPR(725) == 2) THEN
C * GET A PARAMETER VALUE
        N = INDEX (RLWS(1), 'P)^2^')
        IF (N > 0) THEN
          M1 = N + 4
          M  = N - 1
          DO I = 1, 9
            M = M - 1
            IF (RLWS(1)(M:M) == '(') THEN
              READ (RLWS(1)(M + 1:N - 1), *, IOSTAT = IOST) PAR_A
              IF (IOST /= 0) IER = IER + 1
              EXIT
            END IF
          END DO
        END IF
C * GET B PARAMETER VALUE
        N = MAX(INDEX (RLWS(1), 'P+'), INDEX (RLWS(1), 'P-'),
     1          INDEX (RLWS(1), 'P]'))
        IF (N > 0) THEN
          M1 = N
          M  = N - 1
          DO I = 1, 9
            M = M - 1
            IF (RLWS(1)(M:M) == '+' .OR. RLWS(1)(M:M) == '-') THEN
              READ (RLWS(1)(M:N - 1), *, IOSTAT = IOST) PAR_B
              IF (IOST /= 0) IER = IER + 1
              EXIT
            END IF
          END DO
        END IF
C * GET E PARAMETER VALUE
        N = INDEX (RLWS(1), 'L] WHERE') - 8
        IF (N > 0) THEN
          M = N
          DO I = 1, 9
            M = M - I
            IF (RLWS(1)(M:M) == '+' .OR. RLWS(1)(M:M) == '-') THEN
              M2 = M
              READ (RLWS(1)(M:N), *, IOSTAT = IOST) PAR_E
              IF (IOST /= 0) IER = IER + 1
              EXIT
            END IF
          END DO
        ELSE
          N = INDEX (RLWS(1), '] WHERE')
          IF (N > 0) M2 = N
        END IF
C * GET D PARAMETER VALUE
        IF (M1 /= 0 .AND. M2 - M1 > 1) THEN
          READ (RLWS(1)(M1+1:M2-1), *, IOSTAT = IOST) PAR_D
          IF (IOST /= 0) IER = IER + 1
        END IF
C * GET C PARAMETER VALUE
        IF (RLWS(1)(2:4) == 'W=1') THEN
          PAR_C = 0.0
        ELSE IF (RLWS(1)(2:7) == 'W=EXP[') THEN
          N = INDEX (RLWS(1), '(SIN')
          READ(RLWS(1)(8:N-1), *, IOSTAT = IOST) PAR_C
          IF (IOST /= 0) IER = IER + 1
        ELSE IF (RLWS(1)(2:10) == 'W={1-EXP[') THEN
          N = INDEX (RLWS(1), '(SIN')
          READ(RLWS(1)(11:N-1), *, IOSTAT = IOST) PAR_C
          IF (IOST /= 0) IER = IER + 1
        END IF
C * GET F PARAMETER VALUE
        IF (INDEX (RLWS(1), 'WHERE P=') > 0) THEN
          N = INDEX (RLWS(1), '^)/')
          M = INDEX (RLWS(1)(N+3:), '''')
 
          IF (M == 2) THEN
            READ(RLWS(1)(N+3:N+3), *, IOSTAT = IOST) K
            IF (IOST /= 0) THEN
              PAR_F = 0.3333
            ELSE
              PAR_F = 1.0 / K
            END IF
          END IF
        END IF
        IF (IER /= 0) GO TO 10
        PAR(493) = PAR_A
        PAR(494) = PAR_B
        PAR(495) = PAR_C
        PAR(496) = PAR_D
        PAR(497) = PAR_E
        PAR(498) = PAR_F
        IPR(632) = 1
C * ALERT _083 : TEST FOR EXTREME SECOND WEIGHTING PARAMETER VALUE (SHELXL)
                  IF (PAR(494) > 5.0) CALL PLA236
     1              (83, 2, -999.0, PAR(494), ' ', ' ')
C * ALERT _085 : TEST FOR SHELXL DEFAULT
                  IF (PAR(493) == 0.1 .AND. PAR(494) == 0.0)
     1              CALL PLA236 (85, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _963 : TEST FOR BOTH WEIGHT PARAMETERS ZERO
            IF (PAR(493) == 0.0 .AND. PAR(494) == 0.0)
     1        CALL PLA236 (963, 0, -999.0, 1.0, ' ', ' ')
C * IGNORE TEXSAN
C * HANDLE MOPRO WEIGHT EXPRESSION
      ELSE IF (IPR(725) == 9) THEN
C * IPR(725) = 1 : SHELXL97; IGBL(725) = 2 : SHELXL(20XX)
      ELSE IF (IPR(725) < 2  .OR.
     1   (IGBL(9) /= 6  .AND. IGBL(9) /= 10 .AND.
     2    IGBL(9) /= 13 .AND. IGBL(9) /= 15)) THEN
C * HANDLE EXTENDED SHELXL SCHEME
        IF (INDEX (RLWS(1), 'CALC  [') /= 0) THEN
          READ (STRSAVE, 99999, IOSTAT = IOST) (PAR(492 + K), K = 1, 8)
          IF (IOST /= 0) GO TO 10
          WRITE (LU6, 99997, IOSTAT = IOST) (PAR(K), K = 493, 500)
          IF (PAR(493) == 1.0) THEN
            IPR(632) = -1
            CALL GEN018 (PAR(493), PAR(494))
          ELSE
            GO TO 10
          END IF
C * NORMAL SHELXL SCHEME ?
        ELSE
          IF (RLWS(1)(70:70) == '3') THEN
            ISTP = 0
          ELSE IF (RLWS(1)(71:71) == '3') THEN
            ISTP = 1
          ELSE
            ISTP = -1
          END IF
          IF (ISTP >= 0) THEN
            CALL GEN020 (-1, RLWS(1),  2, 13)
C * SHELXL-97 FORMAT
            IF (RLWS(1)(18:19) == 'FO') RLWS(1)(19:19) = 'o'
C * SHELXL-93 FORMAT
            IF (RLWS(1)(17:18) == 'FO')
     1          RLWS(1)(12:25) = CHAR (92)//'s^2^(Fo^2^)+('
            CALL GEN020 (-1, RLWS(1), 47 + ISTP, 51 + ISTP)
            CALL GEN020 (-1, RLWS(1), 57 + ISTP, 57 + ISTP)
            CALL GEN020 (-1, RLWS(1), 64 + ISTP, 64 + ISTP)
            IF (RLWS(1)(37:45) == '+0.0000P]')
     1          RLWS(1)(37:45) =    ']        '
          END IF
C * FIND WEIGHT PARAMETERS (TEST FOR SHELXL/JANA)
          JE = INDEX (RLWS(1), '(I)')
          JC = INDEX (RLWS(1), 'I^2')
C * JANA
          IF (JE > 0 .AND. JC > 0) THEN
            JEP = INDEX (RLWS(1)(JE:), '+')
            IPR(632) = 2
            PAR(484) = 3.0
            READ (RLWS(1)(JE + JEP + 1: JC - 1), *, IOSTAT = IOST)
     1        PAR(493)
            IF (IOST > 0) GO TO 10
            PAR(494) = 0.0
C * SHELXL
          ELSE
C * HANDLE CASE WITH THIRD PARAMETER 'C' NOT EQUAL 1.0
            JE = INDEX (RLWS(1), 'W=EXP[')
            IF (JE /= 0) THEN
              JC = INDEX (RLWS(1), '(SIN')
              IF (JC /= 0) THEN
                JE = JE + 6
                JC = JC - 1
                READ (RLWS(1)(JE:JC), *, IOSTAT = IOST) PAR(495)
              END IF
            END IF
            JE = INDEX (RLWS(1), 'P)')
            JC = INDEX (RLWS(1), 'P]')
            IF (JE /= 0 .OR. JC /= 0) THEN
              PAR(498) = 0.33333
              IPR(632) = 1
C * CRYSTALS: Pseudo Shelx weights
              JX = INDEX (RLWS(1), 'SHELDRICK')
              IF (JX /= 0) IPR(632) = 3
              IF (JE == 0 .AND. JC /= 0) PAR(493) = 0.0
              IF (JE /= 0) THEN
                JD = 2
                JB = INDEX (RLWS(1)(1:JE), '+(')
                IF (JB == 0) THEN
                  JB = INDEX (RLWS(1)(1:JE), '+ (')
                  IF (JB /= 0) JD = 3
                END IF
                IF (JB > 0) THEN
                  READ (RLWS(1)(JB + JD: JE - 1), *, IOSTAT = IOST)
     1              PAR(493)
                  IF (IOST /= 0) GO TO 10
                  IF (PAR(493) >= 0.0) THEN
                    PAR(494) = 0.0
C * ALERT _072 : TEST FOR EXTREME FIRST WEIGHTING PARAMETER VALUE (SHELXL)
                    IF (PAR(493) > 0.1) CALL PLA236
     1                 (72, 2, -999.0, PAR(493), ' ', ' ')
                  END IF
                END IF
              END IF
              IF (JC /= 0) THEN
                JB = INDEX (RLWS(1)(JE + 1:JC - 1), '+')
                IF (JB > 0 .AND. JB + JE <= JC - 1) THEN
                  READ (RLWS(1)(JB + JE + 1: JC - 1), *,
     1              IOSTAT = IOST) PAR(494)
                  IF (IOST /= 0) GO TO 10
C * ALERT _083 : TEST FOR EXTREME SECOND WEIGHTING PARAMETER VALUE (SHELXL)
                  IF (PAR(494) > 5.0) CALL PLA236
     1              (83, 2, -999.0, PAR(494), ' ', ' ')
C * ALERT _085 : TEST FOR SHELXL DEFAULT
                  IF (PAR(493) == 0.1 .AND. PAR(494) == 0.0)
     1              CALL PLA236 (85, 0, 1.0, 1.0, ' ', ' ')
                END IF
              END IF
            ELSE
              JB = INDEX (RLWS(1), '(FO^2^)')
              IF (JB /= 0) THEN
                PAR(493) = 0.0
                PAR(494) = 0.0
                IPR(632) = 1
              END IF
            END IF
C * ALERT _963 : TEST FOR BOTH WEIGHT PARAMETERS ZERO
            IF (PAR(493) == 0.0 .AND. PAR(494) == 0.0)
     1        CALL PLA236 (963, 0, -999.0, 1.0, ' ', ' ')
          END IF
        END IF
        RETURN
      END IF
      RETURN
C * PROBLEM WITH PARSING THE WEIGHT EXPRESSION STRING
   10 WRITE (LU6, 99998, IOSTAT = IOST) RLWS(1)
      IPR(632) = 0
      PAR(493) = -999999.0
      PAR(494) = -999999.0
      CALL PLA236 (809, 0, -999.0, 0.0, ' ', ' ')
99999 FORMAT (8X, F7.0, F8.0, 4X, F4.0, 33X, F7.0, F7.0, 4X, F6.0, 5X,
     1        F7.0, 20X, F8.0)
99998 FORMAT (':: Problem with Weight Formula:', /, A)
99997 FORMAT (8F8.4)
      END SUBROUTINE PLA180
 
      SUBROUTINE PLA181 (MODE)
C * SUPPORT PLA171 -BOND, ANGLE,TORSION, HBOND etc. loop data
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cif
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: NIEN
      INTEGER :: MODE
      INTEGER :: IENM0
      INTEGER :: IENM1
      INTEGER :: IENM2
      INTEGER :: IENM3
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: MSUBST
      REAL :: VDWR1
      REAL :: VDWR2
      REAL :: VDWR3
      REAL :: DELTA
      IF (MODE == 0 .AND. IGBL(3) /= 14) THEN
        IF (LINE(1:4) == 'BOND'  .OR.
     1      LINE(1:5) == 'ANGLE' .OR.
     2      LINE(1:5) == 'TORSI' .OR.
     3      LINE(1:7) == 'CONTACT') THEN
C * TEST/REMOVE '^' ISSUES
          CALL PLA392 (4)
          WRITE (LU11) LINE, (IFL(N), N = 1, 4), (FN(N), N = 1, 6)
          LRETCIF = 4
C * H-BOND
        ELSE IF (LINE(1:5) == 'HBOND') THEN
          IF (IFL(1)(1:1) /= '?') THEN
C * TEST/REMOVE '^' ISSUES
            CALL PLA392 (4)
            CALL PLA046 (1, IFL(1), IENM1, LBB, LBC, LBD, INQNR,
     1        JNQNR, NIEN)
            IF (NIEN < 0) THEN
C * ALERT _715
              CALL PLA236 (715, 0, 1.0, 1.0, IFL(1)(1:9), ' ')
            ELSE
              VDWR1 = VDWR(IEN(IENM1))
              CALL PLA046 (1, IFL(2), IENM2, LBB, LBC, LBD, INQNR,
     1          JNQNR, NIEN)
              IF (NIEN < 0) THEN
C * ALERT _716 - UNKNOWN LABEL
                CALL PLA236 (716, 0, 1.0, 1.0, IFL(2)(1:9), ' ')
              ELSE
                VDWR2 = VDWR(IEN(IENM2))
                CALL PLA046 (1, IFL(3), IENM3, LBB, LBC, LBD, INQNR,
     1            JNQNR, NIEN)
                IF (NIEN < 0) THEN
                  CALL GEN020 (1, IFL(3), 1, 9)
C * ALERT _717 - UNKNON LABEL IN D...A
                  IF (INDEX (IFL(3), 'CG') == 0) THEN
                    CALL PLA236 (717, 0, 1.0, 1.0, IFL(3)(1:9), ' ')
                  ELSE
                    CALL PLA236 (717, 0, -999.0, 1.0, IFL(3)(1:9), ' ')
                  END IF
                ELSE
                  IENM0 = IEN(IENM3)
                  VDWR3 = VDWR(IENM0)
                  IF (FN(1) > 0.0) THEN
                    LINE = 'D-H'
                    WRITE (LU11) LINE, (IFL(N), N = 1, 4),
     1                (FN(N), N = 1, 2), FN(9), FN(10), 0.0, 0.0
                  END IF
                  IF (FN(3) > 0.0 .AND. (IFL(2)(1:1) == 'H' .OR.
     1              IFL(2)(1:1) == 'D')) THEN
                    DELTA = FN(3) - VDWR2 - VDWR3
                    IF (DELTA > -0.12) THEN
                      NQ2 = IFL(2)
C * TRANSLATE TO ALAB
                      MSUBST = 0
                      CALL PLA281 (-1, NQ2, MSUBST)
C * ALERT _480
                      IF (IFL(3)(1:2) /= 'CG')
     1                  CALL PLA236 (480, 2, -999.0, FN(3), NQ2, IFL(3))
                    END IF
                    LINE = 'H..A'
                    WRITE (LU11) LINE, (IFL(N), N = 2, 5),
     1                (FN(N), N = 3, 4), FN(10), FN(11), 0.0, 0.0
                  END IF
                  IF (FN(5) > 0.0 .AND. (IFL(2)(1:1) == 'H' .OR.
     1              IFL(2)(1:1) == 'D')) THEN
                    DELTA = FN(5) - VDWR1 - VDWR3
                    IF (DELTA > 0.0) THEN
C * ALERT _481
                      CALL PLA236 (481, 2, DELTA, FN(5), IFL(1), IFL(3))
                    END IF
                    LINE = 'D..A'
                    WRITE (LU11) LINE, IFL(1), (IFL(N), N = 3, 5),
     1                (FN(N), N = 5, 6), FN(9), FN(11), 0.0, 0.0
                  END IF
                  IF (FN(7) > 0.0 .AND. (IFL(2)(1:1) == 'H' .OR.
     1              IFL(2)(1:1) == 'D')) THEN
                    DELTA = 180.0 - FN(7)
                    IF (DELTA > 60.0) THEN
C * ALERT _482
                      CALL PLA236 (482, 2, DELTA, FN(7), IFL(1), IFL(3))
                    END IF
C * TEST FOR PROPER ROUNDING OF D-H..A without SU
                    IF (FN(8) == 0.0 .AND. IPR(105) == 0) THEN
C * ALERT _484
                      IF (ABS (FN(7) - NINT (FN(7))) > 0.001)
     1                  CALL PLA236 (484, 0, -999.0, FN(7), IFL(1),
     2                    IFL(3))
                    END IF
                    LINE = 'D-H..A'
                    WRITE (LU11) LINE, (IFL(N), N = 1, 4),
     1                (FN(N), N = 7, 8), FN(9), FN(10), FN(11), 0.0
                  END IF
                END IF
              END IF
              LINE(1:1) = CHAR (32)
            END IF
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA181
 
 
      MODULE abspsi
      SAVE
      INTEGER :: NPSI
      INTEGER, DIMENSION(4, 10) :: IHKLPS
      REAL, DIMENSION(3,  3, 11) :: OP
      REAL, DIMENSION(38, 4, 10) :: PSIS
      END MODULE abspsi
 
      SUBROUTINE PLA186
C * SELECTOR FOR ABSORPTION CORRECTION
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE crystal
      USE abspsi
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: IG
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IS
      INTEGER :: NRF
      INTEGER :: ILP
      INTEGER :: ITEL
      INTEGER :: IPH1
      INTEGER :: IPH2
      INTEGER :: ICRT
      INTEGER :: MODE
      INTEGER :: NATO
      INTEGER :: NREF
      INTEGER :: NRET
      INTEGER :: NOCLS
      INTEGER :: NAUTO
      INTEGER :: INEXT
      INTEGER, DIMENSION(3) :: IHMIN
      INTEGER, DIMENSION(3) :: IHMAX
      REAL :: TT
      REAL :: XG
      REAL :: YG
      REAL :: ZG
      REAL :: DUM
      REAL :: STH
      REAL :: TH1
      REAL :: TH2
      REAL :: XINT
      REAL :: XLNG
      REAL :: SUMT
      REAL :: PHI1
      REAL :: PHI2
      REAL :: FMAX
      REAL :: YUNK
      REAL :: RELI
      REAL :: SIGI
      REAL :: SINT
      REAL :: TMAX
      REAL :: TMIN
      REAL :: ACAL
      REAL :: BCAL
      REAL :: ACALA
      REAL :: BCALA
      REAL :: TPRIM
      REAL :: TDIFF
      REAL :: THETA
      REAL :: ANGLE
      REAL :: ASTAR
      REAL :: DUMMY
      REAL :: FSCAL
      REAL :: REANAS
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN006
      REAL :: GEN009
      REAL :: GEN056
      REAL :: GEN095
      REAL :: ABSCOR
      MODE = IPR(78)
C * MODE = -2 - MULABS
C * MODE = -1 - SPHERICAL CORRECTION
C * MODE =  0 - XTAL-HABIT PLOT
C * MODE =  1 - MODEL <-> PSISCAN TEST
C * MODE =  2 - GAUSSIAN INTEGRATION
C * MODE =  3 - MEULENAER & TOMPA
C * MODE =  4 - PSI-SCAN BASED CORRECTION
C * SPHERICAL ABSORPTION CORRECTION (INITIALIZATION)
      IF (MODE == -1) THEN
        IF (IPR(221) == 2) THEN
          PAR(321) = FN(1) * FN(2)
          CALL PLA191 (1, PAR(321), YUNK)
        END IF
        IPR(363) = 0
      ELSE IF (MODE == 2) THEN
C * CHECK FOR PROPER FILE ASSOCIATION AND DIRECTION COSINES
        CALL PLA008
        IF (IGBL(37) /= 0) THEN
          PAR(162) = FN(1)
          IF (IPR(221) == 4) THEN
            DO I = 2, 4
              IPR(419 + I) = NINT (FN(I))
            END DO
          END IF
          PAGET = 'ABSGAUSS'
        ELSE
          IPR(2) = 56
          RETURN
        END IF
      ELSE IF (MODE == 3) THEN
        CALL PLA008
        IF (IGBL(37) /= 0) THEN
          PAR(162) = FN(1)
          PAGET = 'ABSTOMPA'
        ELSE
          IPR(2) = 56
          RETURN
        END IF
      END IF
C * ABSORPTION CORRECTION QUALIFIERS/OPTIONS
      IF (IPR(220) > 1) THEN
        DO I = 2, IPR(220)
          IF (IFL(I)(1:5) == 'LIST')    IGBL(57) = 1
          IF (IFL(I)(1:7) == 'NOCHECK') IPR(363) = 0
        END DO
      END IF
      NRF      = 0
      I2       = 0
      PAR(301) = PAR(162)
      IPR(388) = 1
      IGBL(75) = 1
      IGBL(6)  = 16
C * TEST FOR DIRECTION COSINE OUTPUT ON .HKP REQUESTED
      IF (IPR(220) > 1) THEN
        IF (IFL(2)(1:4) == 'DIRC') IPR(445) = 1
      END IF
      IF (MODE == 4) PAR(321) = FN(1)
      IF (PAR(301) == 0.0 .OR.
     1   (MODE == -1 .AND. PAR(321) == 0.0)) THEN
        NAUTO = IGBL(25)
      ELSE
        NAUTO = 0
      END IF
C * CELL-CALCULATION
      CALL PLA100
C * DEFAULT XTAL-PLOT ORIENTATION MATRIX (COPY)
      CALL GEN052 (OR, OP(1, 1, 11))
C * OUTPUT PROGRAM HEADER AND CELL DATA
      CALL PLA042 (0)
      IF (MODE == -1 .AND. PAR(321) > 0.0) GO TO 60
C * ANALYSE CRYSTAL DESCRIPTION
   10 IF (NFACES > 0 .AND. MODE /= -1) THEN
        NRET = 0
        CALL PLA201 (NRET, NAUTO)
        IF (NRET == 1) GO TO 150
      END IF
   20 IF (NAUTO == 1) THEN
        INEXT   = 0
        IGBL(6) = 16
        IF (MODE /= -2) THEN
          ICRT  = 0
          ANGLE = 0
          NOCLS = 0
   30     CALL PLA198 (MODE, INEXT, NOCLS, 0)
          IF (ICRT > 0) THEN
            BCD = 'Click on Window to STOP Rotation'//CHAR (0)
            CALL GGIP (-999.0, 2.0, 33.0, 111)
            XG = 0.0
            YG = 0.0
            ZG = 0.0
            IG = 9
            CALL GGIP (XG, YG, ZG, IG)
            IF (IG > 0) THEN
              ICRT  = 0
              NOCLS = 0
            ELSE
              NOCLS = -1
              CALL PLA198 (MODE, INEXT, NOCLS, 0)
              NOCLS =  1
              CALL GEN051 (1, OP(1, 1, 11), ANGLE, ICRT)
              GO TO 30
            END IF
          END IF
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          CALL PLA006 (0, IS)
          SELECT CASE (IFL(1)(1:5))
C * SET MU
            CASE ('MU   ')
              PAR(301) = FN(1)
              IPR(441) = 0
C * SET MUR
            CASE ('MUR  ')
              PAR(321) = FN(1)
              IPR(443) = 0
              CALL PLA191 (1, PAR(321), YUNK)
C * ADD FACE
            CASE ('FACE ')
              IF (IPR(221) == 4) THEN
C * TEST FOR PRE-OCCURRENCE
                IF (NFACES > 0) THEN
                  DO 40 I = 1, NFACES
                    DO J = 1, 3
                      IF (ABS (PMILL(I, J) - FN(J)) > 0.001) GO TO 40
                    END DO
                    GO TO 50
   40             CONTINUE
                END IF
                NFACES = NFACES + 1
                I      = NFACES
   50           DO J = 1, 4
                  PMILL(I, J) = FN(J)
                END DO
                PMILL(I, 5) = FN(4)
                IPR(451) = 0
                GO TO 10
              END IF
C * DELETE FACES
            CASE ('DELF ')
              IF (IPR(221) == 3) THEN
                DO I = 1, NFACES
                  IF (PMILL(I, 1) == FN(1) .AND.
     1                PMILL(I, 2) == FN(2) .AND.
     2                PMILL(I, 3) == FN(3)) THEN
                    IF (I < NFACES) THEN
                      DO J = 1, 5
                        PMILL(I, J) = PMILL(NFACES, J)
                      END DO
                    END IF
                    NFACES = NFACES - 1
                    GO TO 10
                  END IF
                END DO
              END IF
C * SET GAUSS GRID
            CASE ('GRID ')
              IF (IPR(221) == 3) THEN
                IPR(421) = NINT (FN(1))
                IPR(422) = NINT (FN(2))
                IPR(423) = NINT (FN(3))
                IPR(444) = 0
              END IF
            CASE ('NEXT ', 'CALC ')
              IF (IPR(432) > 0) GO TO 140
              IF (PAR(301) == 0.0) THEN
                IF (MODE /= -1 .AND. MODE /= 4) THEN
                  CALL PLA015 (0, 46)
                  GO TO 30
                END IF
              END IF
              INEXT = INEXT + 1
              GO TO 60
            CASE ('XROT ')
              CALL GEN051 (1, OP(1, 1, 11), FN(1) / RGBL(6), 1)
            CASE ('YROT ')
              CALL GEN051 (1, OP(1, 1, 11), FN(1) / RGBL(6), 2)
            CASE ('ZROT ')
              CALL GEN051 (1, OP(1, 1, 11), FN(1) / RGBL(6), 3)
            CASE ('CROTX')
              ANGLE = FN(1) / RGBL(6)
              CALL GEN051 (1, OP(1, 1, 11), ANGLE, 1)
              ICRT = 1
            CASE ('CROTY')
              ANGLE = FN(1) / RGBL(6)
              CALL GEN051 (1, OP(1, 1, 11), ANGLE, 2)
              ICRT = 2
            CASE ('CROTZ')
              ANGLE = FN(1) / RGBL(6)
              CALL GEN051 (1, OP(1, 1, 11), ANGLE, 3)
              ICRT = 3
            CASE ('PLOT ')
              GO TO 30
            CASE ('END  ')
              GO TO 140
            CASE ('EXIT ')
              GO TO 140
          END SELECT
          GO TO 30
        END IF
      END IF
C * CHECK FOR INPUT ATOMS
   60 IF (IPR(39) > 0) THEN
C * LOAD ATOMS AND EXPAND (EXCLUDING BRAVAIS CENTERING)
        CALL PLA023 (0)
        NATO = IPR(589)
C * CALL EXIT/STOP
        IF (NATO < 0) CALL GEN127 ('PLA186')
      END IF
C * STORE REFLECTION FILE IN SCRAT
C * IHLP(1)     = NUMBER OF SUB-SETS SEPARATED BY BLANK LINES
C * IHLP(N) + 1 = STARTING ADDRESS (N - 1)TH DATASET
      IHLP(1) = 0
      IHLP(2) = 10000
      I1      = IHLP(2) + 1
      I2      = IHLP(2) + 11
      NREF    = 0
      WRITE (LU6, 99998, IOSTAT = IOST) NAMEFIL(1:KNMFIL)//'.hkl'
      IF (IGBL(37) == 0 .AND. IPR(78) /= -1) THEN
        IPR(2) = 37
        GO TO 140
      ELSE IF (IGBL(37) == 1) THEN
        IF (IPR(648) == 3) THEN
          WRITE (LU6, 99988, IOSTAT = IOST)
        ELSE
          WRITE (LU6, 99987, IOSTAT = IOST)
        END IF
        I2 = IHLP(2) + 11
      ELSE IF (IGBL(37) == 2) THEN
        WRITE (LU6, 99986, IOSTAT = IOST)
        I2 = IHLP(2) + 6
      END IF
      CALL GEN108 (LU16, 0)
C * CHECK DIRCOS
      CALL PLA199 (0)
      GO TO 80
   70 READ (LU16, 99985, IOSTAT = IOST) PRBUF
      IF (IOST == -1) GO TO 90
      IF (INDEX (PRBUF, '<?') /= 0) GO TO 90
      BACKSPACE LU16
   80 IF (IGBL(37) == 1 .OR. MODE == -1) THEN
        IF (IGBL(9) == 0) THEN
          READ (LU16, 99981, IOSTAT = IOST) (VOID(I), I = I1, I1 + 4),
     1        VOID(I1 + 13), (VOID(I), I = I1 + 5, I2)
          IF (IOST == -1) GO TO 90
        ELSE
C * HKLF4 NEEDED
          IPR(2) = 65
          GO TO 140
        END IF
      ELSE
        READ (LU16, 99980, IOSTAT = IOST) (VOID(I), I = I1, I2)
        IF (IOST == -1) GO TO 90
      END IF
      VOID(I1 + 11) = 1.0
      VOID(I1 + 12) = 0.0
      IF (NINT (VOID(I1 + 13)) == 0) VOID(I1 + 13) = 1.0
      IH = NINT (VOID(I1))
      IK = NINT (VOID(I1 + 1))
      IL = NINT (VOID(I1 + 2))
      IF (ABS (IH) + ABS (IK) + ABS (IL) > 0.1) THEN
        STH = SQRT (GEN095 (PAR(391), IH, IK, IL)) * PAR(17)
C * CHECK DIRECTION COSINES ON VALIDITY
        IF (IGBL(37) /= 2) THEN
          L = 3
          DO K = 1, 3
            L = L + 2
            V4(K) = PAR(134 + K) * VOID(I1 + L)
            V5(K) = PAR(134 + K) * VOID(I1 + L + 1)
          END DO
          TPRIM = GEN009 (VOID(I1), V4)
          TDIFF = GEN009 (VOID(I1), V5)
C * CHECK/CORRECT FOR OUT-OF-RANGE
          DUMMY = GEN006 (V4, RAA, V5) /
     1            SQRT (GEN006 (V4, RAA, V4) * GEN006 (V5, RAA, V5))
          IF (ABS (DUMMY) > 1.0) DUMMY = SIGN (1.0, DUMMY)
          IF (ABS (STH) > 0.99999999)
     1      WRITE (LU6, 99984, IOSTAT = IOST) IH, IK, IL, STH
          TH1 = 90.0 - ACOS (DUMMY) * RGBL(6) / 2.0
          TH2 = ASIN (STH) * RGBL(6)
          CALL PLA200 (TPRIM, TDIFF, TH1, TH2)
        ELSE
C * TRANSFORM PSI-VALUES TO DIRECTION COSINES
          CALL GEN106 (VOID(I1), STH, VOID(I1 + 5) / RGBL(6),
     1                 RAA, RBB, V6, V8, PAR(135))
          L = 3
          DO K = 1, 3
            L                = L + 2
            VOID(I1 + L)     = V6(K)
            VOID(I1 + L + 1) = V8(K)
          END DO
        END IF
        NREF = NREF + 1
        IF (MODE == -1) THEN
          CALL PLA191 (0, STH, ASTAR)
          VOID(I2 + 1) = ASTAR
        END IF
        IF (IPR(39) > 0) THEN
          ACAL = 0
          BCAL = 0
          CALL PLA137 (IH, IK, IL, ACAL, BCAL, ACALA, BCALA,
     1      ACALAF, BCALAF,  DUM)
C * ADD ANOMALOUS (F' & F") CONTRIBUTION
          ACAL = ACAL + ACALA
          BCAL = BCAL + BCALA
          VOID(I2 + 2) = ACAL**2 + BCAL**2
        END IF
        I1 = I1 + 14
        IF (IGBL(37) == 1 .OR. MODE == -1) THEN
          I2 = I1 + 10
        ELSE
          I2 = I1 + 5
        END IF
      ELSE
        IF (VOID(I1 - 1) > -1000.0) THEN
          VOID(I1)          = - 1000.0
          IHLP(1)           = IHLP(1) + 1
          IHLP(IHLP(1) + 2) = I1
          I1                = I1 + 1
          I2                = I1 + 10
        END IF
      END IF
      GO TO 70
   90 IF (NREF == 0) THEN
        IPR(2) = 39
        GO TO 140
      END IF
      IPR(383) = NREF
C * CHECK DIRCOS
      IF (IGBL(37) == 1) CALL PLA199 (-1)
      IF (VOID(I1 - 1) > -1000.0) THEN
        VOID(I1) = - 1000.0
        IHLP(1)  = IHLP(1) + 1
      END IF
C * PSI-SCAN/XTAL
      IF (MODE == 1) THEN
        CALL PLA193 (IHLP(1) + 1)
        CALL PLA189
        IF (NPSI <= 0) THEN
          IPR(2) = 38
        ELSE
          CALL PLA188 (MODE, 1, NPSI)
        END IF
        IF (NAUTO == 1) GO TO 20
        GO TO 140
C * ABSGAUSS
      ELSE IF (MODE == 2) THEN
        IF (IGBL(25) == 0 .AND. PAR(301) == 0.0) THEN
          IPR(2) = 35
          GO TO 140
        END IF
        CALL PLA192 (2)
C * ABSTOMPA
      ELSE IF (MODE == 3) THEN
        IF (IGBL(25) == 0 .AND. PAR(301) == 0.0) THEN
          IPR(2) = 35
          GO TO 140
        END IF
        CALL PLA193 (2)
C * ABSPSI
      ELSE IF (MODE == 4) THEN
        IF (IHLP(1) <= 1) THEN
          IPR(2) = 38
          GO TO 140
        END IF
        CALL PLA191 (1, PAR(321), YUNK)
C * CALCULATE PSISCAN CURVES
        CALL PLA189
        IF (NPSI <= 0) THEN
          IPR(2) = 38
          GO TO 130
        END IF
C * CORRECT REFLECTION DATA
        CALL PLA262 (0)
        WRITE (LU7, 99997, IOSTAT = IOST) NPSI
        ILP  = 1
        I1   = IHLP(2) - 13
  100   I1   = I1 + 14
        IH   = NINT (VOID(I1))
        IK   = NINT (VOID(I1 + 1))
        IL   = NINT (VOID(I1 + 2))
        XINT = VOID(I1 + 3)
        SINT = VOID(I1 + 4)
        IF (IH < - 999) THEN
          ILP = ILP + 1
          IF (ILP > IHLP(1)) THEN
            GO TO 110
          ELSE
            I1 = I1 - 13
            GO TO 100
          END IF
        END IF
        THETA = ASIN (GEN056 (IH, IK, IL, RBB) * PAR(17))
        V2(1) = VOID(I1 + 5)  * PAR(135)
        V3(1) = VOID(I1 + 6)  * PAR(135)
        V2(2) = VOID(I1 + 7)  * PAR(136)
        V3(2) = VOID(I1 + 8)  * PAR(136)
        V2(3) = VOID(I1 + 9)  * PAR(137)
        V3(3) = VOID(I1 + 10) * PAR(137)
        TT    = 0.0
        DO K = 1, NPSI
          CALL GEN002 (2, OP(1, 1, K), V2, V4, XLNG)
          CALL GEN002 (2, OP(1, 1, K), V3, V5, XLNG)
          IF (V4(3) < 0.99999) THEN
            PHI1 = MOD (ATAN2 (V4(2), V4(1)) * RGBL(6) + 360.0, 360.0)
          ELSE
            PHI1 = 0.0
          END IF
          IPH1 = INT (PHI1 / 10.0)
          IF (V5(3) < 0.99999) THEN
            PHI2 = MOD (ATAN2 (V5(2), V5(1)) * RGBL(6) + 360.0, 360.0)
          ELSE
            PHI2 = 0.0
          END IF
          IPH2 = INT (PHI2 / 10.0)
          DBUF(K) = (PSIS(IPH1 + 1, 2, K) + PSIS(IPH1 + 2, 2, K) +
     1               PSIS(IPH2 + 1, 2, K) + PSIS(IPH2 + 2, 2, K)) / 4
          TT      = TT + DBUF(K)
        END DO
        TT = TT / NPSI
        CALL PLA191 (0, THETA, ABSCOR)
        VOID(I1 + 11) = TT * ABSCOR
        WRITE (LU7, 99996, IOSTAT = IOST)
     1   IH, IK, IL, XINT, SINT, TT, XINT / TT, (DBUF(J), J = 1, NPSI)
        GO TO 100
  110   CALL PLA189
        CALL PLA188 (MODE, 1, NPSI)
      END IF
C * FIND OUTPUT SCALE AND STATISTICS
      FMAX = 0.0
      SUMT = 0.0
      TMAX = 0.0
      TMIN = 1.0
      ITEL = 0
      I    = IHLP(2) - 13
  120 I    = I + 14
      ITEL = ITEL + 1
      IH   = NINT (VOID(I))
      IF (IH /= -1000) THEN
        TT   = VOID(I + 11)
        FMAX = MAX (FMAX, VOID(I + 3) / TT)
        SUMT = SUMT + TT
C * KEEP TRACK OF THE MAXIMUM (TMAX) AND MINIMUM (TMIN) TRANSMISSION
        IF (TT > TMAX) THEN
          TMAX = TT
          DO J = 1, 3
            IHMAX(J) = NINT (VOID(I + J - 1))
          END DO
        END IF
        IF (TT < TMIN) THEN
          TMIN = TT
          DO J = 1, 3
            IHMIN(J) = NINT (VOID(I + J - 1))
          END DO
        END IF
        GO TO 120
      END IF
      FSCAL = 1.0
      DO WHILE (FMAX * FSCAL > 99998.0)
        FSCAL = FSCAL * 0.1
      END DO
      WRITE (LU6, 99979, IOSTAT = IOST) FSCAL
      WRITE (LU7, 99979, IOSTAT = IOST) FSCAL
C * GENERATE OUTPUT FILE
      CALL GEN108 (LU17, 0)
      I  = IHLP(2) - 13
  130 I  = I + 14
      IH = NINT (VOID(I))
      IF (IH /= -1000) THEN
        NRF  = NRF + 1
        IK   = NINT (VOID(I + 1))
        IL   = NINT (VOID(I + 2))
        DUM  = VOID(I + 11)
C * HKLF3 CASE
        IF (IPR(648) == 3) THEN
          DUM = SQRT (DUM)
          RELI = FSCAL * VOID(I + 3) / DUM
          SIGI = FSCAL * VOID(I + 4) / SQRT (DUM)
C * HKLF4 CASE
        ELSE IF (IPR(648) == 4) THEN
          RELI = FSCAL * VOID(I + 3) / DUM
          SIGI = FSCAL * VOID(I + 4) / DUM
        END IF
C * FIT INTO 2F8.x FORMAT
        IF (RELI <= 99999.0) THEN
          LINE = '(3I4,2F8.2,I4,6F8.5)'
        ELSE IF (RELI <= 999999.0) THEN
          LINE = '(3I4,2F8.1,I4,6F8.5)'
        ELSE
          LINE = '(3I4,2F8.0,I4,6F8.5)'
        END IF
        IF (MODE == 5 .OR. IPR(445) == 1) THEN
          WRITE (LU17, LINE(1:20), IOSTAT = IOST)
     1     IH, IK, IL, RELI, SIGI, NINT (VOID(I + 13)),
     2     (VOID(I + K), K = 5, 10)
        ELSE
          WRITE (LU17, LINE(1:20), IOSTAT = IOST)
     1      IH, IK, IL, RELI, SIGI, NINT (VOID(I + 13))
        END IF
        GO TO 130
      END IF
      WRITE (LU17, 99983, IOSTAT = IOST)
C * OUTPUT STATISTICS
      IF (NRF > 0) THEN
        REANAS = SUMT / FLOAT (NRF)
        IF (MODE == 4) THEN
          WRITE (LU6, 99982, IOSTAT = IOST) NPSI
          WRITE (LU7, 99982, IOSTAT = IOST) NPSI
        END IF
        PAR(315) = TMIN
        PAR(317) = TMAX
        IPR(432) = NRF
        WRITE (LU6, 99999, IOSTAT = IOST)
     1    IPR(383), IPR(432), TMIN, IHMIN, TMAX, IHMAX, REANAS
        WRITE (LU7, 99999, IOSTAT = IOST)
     1   IPR(383), IPR(432), TMIN, IHMIN, TMAX,  IHMAX, REANAS
      END IF
      IF (NAUTO == 1) GO TO 20
  140 IPR(432) = NRF
  150 IF (IPR(2) == 0) THEN
        SELECT CASE (IPR(78))
          CASE (-1)
            IPR(2) = -5
          CASE (1)
            IPR(2) = -1
          CASE (2)
            IPR(2) = -8
          CASE (3)
            IPR(2) = -7
          CASE (4)
            IPR(2) = -6
        END SELECT
      END IF
      RETURN
99999 FORMAT ('::', I8, ' Reflections on Input', /,
     1 '::', I8, ' Reflections Processed', //,
     2 ':: MIN  Transmission =', F9.5, ' for the ', 2(I3, ','), I3, /,
     3 ':: MAX  Transmission =', F9.5, ' for the ', 2(I3, ','), I3, /,
     4 ':: MEAN Transmission =', F9.5)
99998 FORMAT (/, ':: Reflection Data are Expected/READ on/from File: ',
     1         A)
99997 FORMAT ('Absorption correction based on', I3, ' Psi-Scan(s)',
     1 ' following:', /,
     2 ' North, A.C.T, Phillips, D.C. & Scott Mathews, F., (1968)',
     3 ' Acta Cryst. A24, 351-359', //,
     4 '   H   K   L      INT       SIG     T   INT(COR)  T(s)',
     1 /, 80('='))
99996 FORMAT (3I4, 2F10.0, F6.3, F10.0, 10F6.3)
99988 FORMAT (/, ':: H K L F SIG(F) Direction Cosine Data Assumed', /)
99987 FORMAT (/, ':: H K L I SIG(I) Direction Cosine Data Assumed', /)
99986 FORMAT ('N: H K L I SIG(I) Psi-Data Assumed', /)
99985 FORMAT (A)
99984 FORMAT ('|SIN(THETA)| > 1.0 ?', 3I5, F10.5, /)
99983 FORMAT (1X)
99982 FORMAT (/, ':: Correction Based on', I3, ' Psi-scans', /)
99981 FORMAT (3F4.0, 2F8.0, F4.0, 6F8.0)
99980 FORMAT (3F4.0, 2F8.0, F9.0)
99979 FORMAT (':: Multiplicative Output Scaling Factor:', F10.4, /)
      END SUBROUTINE PLA186
 
 
      SUBROUTINE PLA187 (MODE, SCL, NR, NOCLS)
C * XTAL
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE crystal
      USE abspsi
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: I0
      INTEGER :: J0
      INTEGER :: MC
      INTEGER :: NR
      INTEGER :: NV
      INTEGER :: IVIS
      INTEGER :: MODE
      INTEGER :: NSTEP
      INTEGER :: NOCLS
      REAL :: XB
      REAL :: XE
      REAL :: XG
      REAL :: YB
      REAL :: YE
      REAL :: DX
      REAL :: DY
      REAL :: SCL
      REAL :: DIS
      REAL :: DET
      REAL :: SHT
      REAL :: DIST
      REAL :: DELX
      REAL :: DELY
      REAL :: SCAL
      REAL :: VERT
      REAL :: STEPX
      REAL :: STEPY
      REAL :: ANGLE
      REAL :: COLOR
      REAL :: GEN009
      CHARACTER(len=6) :: NRV
      VERT = 25.0
      IDM  = '  H  K  L  DIST(mm)'
      CALL PLA439 (0.0, IDM, 19, 0.5, 5, 2, VERT + 0.1, VERT - 3.0)
      DO I = 1, NFACES
        WRITE (IDM, 99999, IOSTAT = IOST)
     1   (NINT (PMILL(I, J)), J = 1, 3), PMILL(I, 5)
        CALL PLA439 (0.0, IDM, 18, 0.5, -1, 2, VERT + 0.1,
     1       VERT - 3.5 - I * 0.8)
      END DO
C * MOVE ORIGIN
      CALL GGIP (13.0, 12.0, 0.0, -3)
C * CHECK FOR FINITENESS OF CRYSTAL WITH EULERS RULE
      IF (NVER > NXT2) THEN
        CALL PLA439 (0.0, 'Too Many Vertices ', 18, 0.75,
     1                         2, 2, 1.0, -6.5)
        GO TO 20
      ELSE IF (NFACES + NVRR - 2 /= NEDGE) THEN
        WRITE (PRBUF, 99994, IOSTAT = IOST)
        WRITE (LU6,   99998, IOSTAT = IOST) PRBUF
        WRITE (LU7,   99998, IOSTAT = IOST) PRBUF
        CALL PLA439 (0.0, PRBUF, 18, 0.75, 2, 2, 1.0, -8.0)
        GO TO 20
      END IF
C * RAA - DIRECT CELL METRIC (REFLECTION CELL)
C * GENERATE CRYSTAL PLOT DATA
C * COPY MATRIX
      CALL GEN052 (OP(1, 1, NR), DUMV)
      CALL GEN003 (OP(1, 1, NR), PAT, DET, 0)
      CALL GEN007 (RAA, DUMV(1, 1), V3, 1)
      CALL GEN007 (RAA, DUMV(1, 2), V4, 1)
      CALL GEN007 (RAA, DUMV(1, 3), V5, 1)
      DO I = 1, 2
        V3(I)     = V3(I) * SCL * 0.5
        V4(I)     = V4(I) * SCL * 0.5
        V5(I)     = V5(I) * SCL * 0.5
        V1(I)     =   1000000.0
        V1(I + 2) = - 1000000.0
      END DO
      IF (NVER > 0) THEN
        CALL GEN074 (V2, 1, 3, 0.0)
        DO I = 1, NVER
          CALL GEN002 (MODE, DUMV, XTLV(1, I), XYZPL(1, I), XG)
          V1(1) = MIN (V1(1), XYZPL(1, I))
          V1(2) = MIN (V1(2), XYZPL(2, I))
          V1(3) = MAX (V1(3), XYZPL(1, I))
          V1(4) = MAX (V1(4), XYZPL(2, I))
          V2(1) = V2(1) + XYZPL(1, I)
          V2(2) = V2(2) + XYZPL(2, I)
          V2(3) = V2(3) + XYZPL(3, I)
        END DO
        V2(1) = V2(1) / NVER
        V2(2) = V2(2) / NVER
        V2(3) = V2(3) / NVER
        DO I = 1, NVER
          XYZPL(1, I) = XYZPL(1, I) - V2(1)
          XYZPL(2, I) = XYZPL(2, I) - V2(2)
          XYZPL(3, I) = XYZPL(3, I) - V2(3)
        END DO
        DIS = 0.0
        DO I = 1, NVER
          DIS = MAX (DIS, SQRT (GEN009 (XYZPL(1, I), XYZPL(1, I))))
        END DO
        SCAL = PAR(325) * SCL / DIS
        DO I = 1, NFACES
          ANGLE = 0
          DO J = 1, 3
            ANGLE       = ANGLE + PAT(J, 3) * PMILL(I, J)
            CFACE(J, I) = 0.0
          END DO
          CFACE(4, I) = 0
          CFACE(5, I) = ANGLE
          DO K = 1, NVER
            DO J = 4, 6
              N = IABS (NINT (XTLV(J, K)))
              IF (N == I) THEN
                IF (ANGLE < 0.0) N = - N
                XTLV(J, K)  = N
                CFACE(1, I) = CFACE(1, I) + XYZPL(1, K)
                CFACE(2, I) = CFACE(2, I) + XYZPL(2, K)
                CFACE(3, I) = CFACE(3, I) + XYZPL(3, K)
                CFACE(4, I) = CFACE(4, I) + 1.0
              END IF
            END DO
          END DO
        END DO
        IF (NOCLS >= 0) THEN
          COLOR = 1.0
        ELSE
          COLOR = 0.0
        END IF
        CALL GGIP (0.0, COLOR, 0.0, 0)
        DO I = 1, NVER
          DO K = 1, 3
            XYZPL(K, I) = SCAL * XYZPL(K, I)
          END DO
          IF (IGBL(75) == 1) THEN
            IF (NVER < 100) THEN
              NV = 2
              WRITE (NRV, 99997, IOSTAT = IOST) NINT (XTLV(7, I))
            ELSE
              NV = 3
              WRITE (NRV, 99996, IOSTAT = IOST) NINT (XTLV(7, I))
            END IF
            CALL PLA439 (0.0, NRV, NV, 0.3, -1, 2,
     1                   XYZPL(1, I), XYZPL(2, I))
          END IF
        END DO
        DO I = 1, NFACES
          DO K = 1, 3
            CFACE(K, I) = SCAL * (CFACE(K, I) / CFACE(4, I))
          END DO
          IF (IGBL(75) == 1) THEN
            IF (CFACE(5, I) > 0.0) THEN
              COLOR = 1.0
              SHT = 0.15
            ELSE
              COLOR = 4.0
              SHT = -0.15
            END IF
            IF (NOCLS < 0) THEN
              COLOR = 0.0
            END IF
            CALL GGIP (0.0, COLOR, 0.0, 0)
            WRITE (NRV, 99995, IOSTAT = IOST)
     1        (NINT (PMILL(I, K)), K = 1, 3)
            CALL PLA439 (0.0, NRV, 6, 0.25, -1, 2,
     1                   CFACE(1, I) - 0.5, CFACE(2, I) + SHT)
          END IF
        END DO
      END IF
      DO 10 I0 = 1, NEDGE
        I  = IDG(I0, 3)
        J0 = IDG(I0, 4)
        MC   = 0
        IVIS = 0
        IF (NOCLS < 0) THEN
          COLOR = 0.0
        ELSE
          COLOR = 1.0
        END IF
        CALL GGIP (0.0, COLOR, 0.0, 0)
        DO K = 1, 3
          DO L = 1, 3
            IF (ABS (XTLV(K + 3, I)) == ABS (XTLV(L + 3, J0))) THEN
              MC = MC + 1
              IF (XTLV(K + 3, I) > 0.0) IVIS = IVIS + 1
              IF (MC == 2) THEN
                IF (IVIS < 1) THEN
C * DRAW OBSCURED EDGE - DASHED
                  XB = XYZPL(1, I)
                  YB = XYZPL(2, I)
                  DIST = SQRT ((XYZPL(1, J0) - XB)**2
     1                 +       (XYZPL(2, J0) - YB)**2)
                  NSTEP = NINT (DIST / 0.3)
                  IF (NSTEP > 0) THEN
                    STEPX = (XYZPL(1, J0) - XB) / NSTEP
                    STEPY = (XYZPL(2, J0) - YB) / NSTEP
                    DO M = 1, NSTEP, 2
                      CALL GGIP (XB, YB, 0.0, 3)
                      XB = XB + STEPX
                      YB = YB + STEPY
                      CALL GGIP (XB, YB, 0.0, 2)
                      XB = XB + STEPX
                      YB = YB + STEPY
                    END DO
                  END IF
C * DRAW UNOBSCURED EDGE
                ELSE
                  IF (NOCLS < 0) THEN
                    COLOR = 0.0
                  ELSE
                    COLOR = 1.0
                  END IF
                  CALL GGIP (0.0, COLOR, 0.0, 0)
                  DELX = XYZPL(1, J0) - XYZPL(1, I)
                  DELY = XYZPL(2, J0) - XYZPL(2, I)
                  IF (DELX == 0) THEN
                    DX = 0.025
                    DY = 0.0
                  ELSE IF (DELY == 0) THEN
                    DX = 0.0
                    DY = 0.025
                  ELSE
                    DY = - (DELX / DELY)
                    DX = SQRT (0.000625 / (1 + DY**2))
                    DY = DX * DY
                  END IF
                  XB = XYZPL(1, I)  - DX
                  YB = XYZPL(2, I)  - DY
                  XE = XYZPL(1, J0) - DX
                  YE = XYZPL(2, J0) - DY
                  DO M = 1, 2
                    CALL GGIP (XB, YB, 0.0, 3)
                    CALL GGIP (XE, YE, 0.0, 2)
                    XB = XB + 2 * DX
                    YB = YB + 2 * DY
                    XE = XE + 2 * DX
                    YE = YE + 2 * DY
                  END DO
                END IF
                GO TO 10
              END IF
            END IF
          END DO
        END DO
   10 CONTINUE
C * AXIAL SYSTEM
      IF (IPR(388) == 1) THEN
        IF (NOCLS < 0) THEN
          COLOR = 0.0
        ELSE
          COLOR = 2.0
        END IF
        CALL GGIP (0.0, COLOR, 0.0, 0)
        CALL GGIP (0.0,   0.0,   0.0, 3)
        CALL GGIP (V3(1), V3(2), 0.0, 2)
        CALL PLA439 (0.0, 'a', 1, 0.35,  -1, 2, V3(1) + 0.2, V3(2))
        CALL GGIP (0.0,   0.0,   0.0, 3)
        CALL GGIP (V4(1), V4(2), 0.0, 2)
        CALL PLA439 (0.0, 'b', 1, 0.35,  -1, 2, V4(1) + 0.2, V4(2))
        CALL GGIP (0.0,   0.0,   0.0, 3)
        CALL GGIP (V5(1), V5(2), 0.0, 2)
        CALL PLA439 (0.0, 'c', 1, 0.35,  -1, 2, V5(1) + 0.2, V5(2))
      END IF
C * MOVE ORIGIN
   20 CALL GGIP (-13.0, -12.0, 0.0, -3)
      CALL GGIP (0.0, 0.0, 0.0, 0)
      RETURN
99999 FORMAT (3I3, F8.3)
99998 FORMAT (':: ', A)
99997 FORMAT (I2)
99996 FORMAT (I3)
99995 FORMAT (3I2)
99994 FORMAT ('Crystal not Finite')
      END SUBROUTINE PLA187
 
      SUBROUTINE PLA188 (MODE, JB, JE)
C * CRYSTAL & PSI-SCAN PLOTS
      USE parameters
      USE atomdata
      USE cchar
      USE abspsi
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: JB
      INTEGER :: JE
      INTEGER :: IS
      INTEGER :: JJ
      INTEGER :: IPX
      INTEGER :: MODE
      INTEGER :: IPERC
      REAL :: DS
      REAL :: DX
      REAL :: DY
      REAL :: XP
      REAL :: YP
      REAL :: XPL
      REAL :: YPL
      REAL :: XP0
      REAL :: YP0
      REAL :: PSI
      REAL :: PSS
      REAL :: TEMP1
      CHARACTER(len=3), DIMENSION(3) :: TXT
      TXT(1) = 'Obs'
      TXT(2) = 'Cal'
      TXT(3) = 'Cor'
C * LOOP OVER REQUESTED PSI-SCAN RANGE
      DO J = JB, JE
C * PLOT-PSI ROUTINE
   10   CALL PLA198 (MODE, 1, 0, 0)
C * GENERATE CRYSTAL PLOT DATA
C * MOVE ORIGIN
        CALL GGIP (13.0, 12.0, 0.0, -3)
        CALL PLA439 (0.0, 'Psi-Scan', 8,  0.6, 1, 2, 15.3, -11.5)
        CALL PLA439 (0.0, '0',        1, 0.25, 1, 2, 12.0,  -0.1)
        CALL PLA439 (0.0, '270',      3, 0.25, 1, 2, -0.2, -11.3)
        CALL PLA439 (0.0, '180',      3, 0.25, 1, 2,-12.1,   0.3)
        CALL PLA439 (0.0, '90',       2, 0.25, 1, 2, -0.2,  11.4)
        DO K = 1, 4
C * SET COLOR
          CALL GGIP (0.0, FLOAT (K), 0.0, 0)
          IF (K > 1) THEN
            TEMP1 = 9999999.0
            DO I = 1, 36
              IF (PSIS(I, K, J) >= 0.01)
     1          TEMP1 = MIN (TEMP1, PSIS(I, K, J))
            END DO
            IPERC = NINT (TEMP1 * 100.0)
            IPX = 0
            YPL = 10.5 + 1.5 - K * 0.75
            CALL PLA439 (0.0, TXT(K - 1), 3, 0.5, -1, 2, 8.4, YPL)
            CALL GEN040 (IPERC, NQ1, IPX)
            CALL PLA439 (0.0, NQ1, IPX, 0.5, -1, 2, 11.0, YPL)
          END IF
          DO I = 1, 36
            PSI = PSIS(I, 1, J) / RGBL(6)
            XPL = COS (PSI)
            YPL = SIN (PSI)
            XP  = 6.0
            YP  = 6.0
            DS  = 0.1 * (K - 1)
            IF (K > 1) THEN
              PSS = PSIS(I, K, J)
              IF (PSS < 0.0) PSS = 0.0
              XP = PSS * XP
              YP = PSS * YP
            END IF
            XPL = XPL * (XP + 5.0)
            YPL = YPL * (YP + 5.0)
            IF (K > 1) THEN
              IF (I == 1) THEN
                XP0 = XPL
                YP0 = YPL
                GO TO 20
              END IF
              CALL GGIP (XPL, YPL, 0.0, 2)
            END IF
   20       YPL = YPL - DS
            CALL GGIP (XPL, YPL, 0.0, 3)
            IF (K <= 1) THEN
              XPL = XPL * (5.0 / 11.5)
              YPL = YPL * (5.0 / 11.5)
              CALL GGIP (XPL, YPL, 0.0, 2)
              CYCLE
            END IF
            DO L = 1, 3, 2
              DY = DS * (2 - L)
              DO M = 1, 3, 2
                DX  = DS * (2 - M) * (2 - L)
                XPL = XPL + DX
                YPL = YPL + DY
                CALL GGIP (XPL, YPL, 0.0, 2)
              END DO
            END DO
            YPL = YPL + DS
            CALL GGIP (XPL, YPL, 0.0, 3)
          END DO
          IF (K /= 1) THEN
            CALL GGIP (XP0, YP0, 0.0, 2)
            CALL GGIP (0.0, 0.0, 0.0, 3)
          END IF
        END DO
C * SET COLOR
        CALL GGIP (0.0, 1.0, 0.0, 0)
        DO JJ = 1, 3
          XPL = 5 + JJ * 2
          CALL GEN040 (IHKLPS(JJ, J), NQ1, IPX)
          CALL PLA439 (0.0, NQ1, IPX, 0.5, -1, 2, XPL, -11.5)
        END DO
        CALL GGIP (0.0, 0.0, 0.0, 3)
C * ENDPLT
        CALL GGIP (0.0, 0.0,   0.0, -1)
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        CALL PLA006 (0, IS)
        SELECT CASE (IFL(1)(1:4))
          CASE ('PLOT')
            GOTO 10
          CASE ('EXIT')
            GO TO 30
        END SELECT
      END DO
   30 RETURN
      END SUBROUTINE PLA188
 
      SUBROUTINE PLA189
C * PSI SCAN HANDLING
      USE files
      USE parameters
      USE plato
      USE crystal
      USE abspsi
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: KAS
      INTEGER :: IHO
      INTEGER :: IKO
      INTEGER :: ILO
      INTEGER :: MPSI
      INTEGER :: ICHANGE
      REAL :: T1
      REAL :: T2
      REAl :: T3
      REAl :: T4
      REAL :: PH1
      REAL :: PH2
      REAL :: PHI
      REAL :: XLNG
      REAL :: YUNK
      REAL :: PMAX2
      REAL :: PMAX3
      REAL :: PMAX4
      REAL :: PSISJ
      REAL :: PSISL
      REAL :: YUNKM
      REAL :: GEN009
C * ANALYSE PSI-SCAN DATA
C * DUNITZ p 237: OR = Tr(beta), ROR = Tr(alpha)
C * A-AXIS etc. VERTICAL i.e. (OR(1, 1), OR(2, 1), OR(3, 1)
      IHO  = 0
      IKO  = 0
      ILO  = 0
      NPSI = 0
      MPSI = 0
      KAS  = 0
      N    = IHLP(IHLP(1) + 1) - 13
      DO
        N     = N + 14
C * GET HKL & DIRECTION COSINES (REFERRED TO DIRECT CELL AXES)
        V6(1) = VOID(N)
        V6(2) = VOID(N + 1)
        V6(3) = VOID(N + 2)
        V2(1) = VOID(N + 5)  * PAR(135)
        V3(1) = VOID(N + 6)  * PAR(135)
        V2(2) = VOID(N + 7)  * PAR(136)
        V3(2) = VOID(N + 8)  * PAR(136)
        V2(3) = VOID(N + 9)  * PAR(137)
        V3(3) = VOID(N + 10) * PAR(137)
        IH = NINT (V6(1))
        IK = NINT (V6(2))
        IL = NINT (V6(3))
C * END-TEST
        IF (IH < - 999.0) EXIT
C * TRANSFORM HKL TO ORTHONORMAL COORDINATES
        CALL GEN002 (-2, ROR, V6, V8, XLNG)
C * IS THIS A NEW PSI-SCAN ?
        IF (IH /= IHO .OR. IK /= IKO .OR. IL /= ILO) THEN
          IF (NPSI > 0) THEN
            IF (IHKLPS(4, NPSI) < 37) THEN
              WRITE (LU6, 99999, IOSTAT = IOST) IHO, IKO, ILO
              NPSI = NPSI - 1
              IF (IHKLPS(4, NPSI + 1) == 2) RETURN
            END IF
          END IF
          IHO  = IH
          IKO  = IK
          ILO  = IL
          MPSI = 1
C * AVOID OVERFLOW OF NUMBER OF PSI-SCANS
          IF (NPSI == 10) THEN
            WRITE (LU6, 99998, IOSTAT = IOST)
            EXIT
          END IF
          NPSI            = NPSI + 1
          IHKLPS(1, NPSI) = IH
          IHKLPS(2, NPSI) = IK
          IHKLPS(3, NPSI) = IL
C * HKL- VERTICAL
          DO J = 1, 3
            QM(J, 3) = V8(J)
            QM(J, 2) = 0.0
          END DO
C * CALCULATE ANGLES OF H WITH A,B & C
          YUNKM = 2.0
          IF (NPSI == 1) THEN
            DO J = 1, 3
              YUNK = GEN009(OR(1, J), V8) /
     1               SQRT (GEN009(OR(1, J), OR(1, J)))
              IF (ABS(YUNK) < YUNKM) THEN
                YUNKM = ABS (YUNK)
                KAS = J
              END IF
            END DO
          END IF
          QM(KAS, 2) = 1.0
C * A(B OR C)-AXIS IN YZ-PLANE
C * X PERP TO H & A(B OR C)
          CALL GEN008 (QM(1, 2), QM(1, 3), QM(1, 1), 1)
C * Y PERPENDICULAR TO XZ
          CALL GEN008 (QM(1, 3), QM(1, 1), QM(1, 2), 1)
C * TRANSPOSE
          CALL GEN005 (QM, DUMV)
C * TRANSFORM AND SAVE ORTHOGONALIZATION MATRIX
          CALL GEN004 (DUMV, OR, OP(1, 1, NPSI))
        END IF
        CALL GEN002 (2, OP(1, 1, NPSI), V2, V4, XLNG)
        CALL GEN002 (2, OP(1, 1, NPSI), V3, V5, XLNG)
        IF (V5(3) < 0.99999) THEN
          PHI = ATAN2(V5(2), V5(1)) * RGBL(6)
        ELSE
          PHI = 0.0
        END IF
        MPSI                = MPSI + 1
        PSIS(MPSI, 1, NPSI) = MOD (360.0 + PHI, 360.0)
        PSIS(MPSI, 2, NPSI) = VOID(N + 3)
        PSIS(MPSI, 3, NPSI) = VOID(N + 11)
        IHKLPS(4, NPSI)     = MPSI
      END DO
      IF (NPSI > 0) THEN
        DO K = 1, NPSI
          MPSI = IHKLPS(4, K)
C * BUBBLE SORT ON PHI
   10     ICHANGE = 0
          DO J = 2, MPSI - 1
            IF (PSIS(J, 1, K) > PSIS(J + 1, 1, K)) THEN
              DO I = 1, 3
                CALL GEN018 (PSIS(J, I, K), PSIS(J + 1, I, K))
              END DO
              ICHANGE = 1
            END IF
          END DO
          IF (ICHANGE /= 0) GO TO 10
          L = 2
          PSISL = PSIS(L, 1, K)
          DO J = 3, MPSI
            PSISJ = PSIS(J, 1, K)
            IF (ABS (PSISJ - PSISL) > 0.05) THEN
              L = L + 1
              DO I = 1, 3
                PSIS(L, I, K) = PSIS(J, I, K)
              END DO
              PSISL = PSIS(L, 1, K)
            END IF
          END DO
          IHKLPS(4, NPSI) = L
          PSIS(1, 1, K)   = PSIS(37, 1, K) - 360.0
          PSIS(1, 2, K)   = PSIS(37, 2, K)
          PSIS(1, 3, K)   = PSIS(37, 3, K)
C * INTERPOLATE TO 0, 10, 20 ETC.
          DO I = 1, 36
            PHI = (I - 1) * 10.0
            PH1 = 2 - I + PSIS(I, 1, K) / 10.0
            PH2 = I     - PSIS(I + 1, 1, K) / 10.0
            T1  = PSIS(I,     2, K)
            T2  = PSIS(I + 1, 2, K)
            T3  = PSIS(I,     3, K)
            T4  = PSIS(I + 1, 3, K)
            PSIS(I, 1, K) = PHI
            PSIS(I, 2, K) = (PH1 * T1 + PH2 * T2) / (PH1 + PH2)
            PSIS(I, 3, K) = (PH1 * T3 + PH2 * T4) / (PH1 + PH2)
            IF (PSIS(I, 3, K) > 0.0) THEN
              PSIS(I, 4, K) = PSIS(I, 2, K) / PSIS(I, 3, K)
            ELSE
              PSIS(I, 4, K) = 0.0
            END IF
          END DO
          PSIS(37, 1, K) = 360.0
          PSIS(37, 2, K) = PSIS(1, 2, K)
          PSIS(37, 3, K) = PSIS(1, 3, K)
          PSIS(37, 4, K) = PSIS(1, 4, K)
C * NORMALIZE CURVE TO 1.0
          PMAX2 = 0.0
          PMAX3 = 0.0
          PMAX4 = 0.0
          DO I = 1, MPSI
            PMAX2 = MAX (PMAX2, PSIS(I, 2, K))
            PMAX3 = MAX (PMAX3, PSIS(I, 3, K))
            PMAX4 = MAX (PMAX4, PSIS(I, 4, K))
          END DO
          DO I = 1, MPSI
            PSIS(I, 2, K) = PSIS(I, 2, K) / PMAX2
            PSIS(I, 3, K) = PSIS(I, 3, K) / PMAX3
            PSIS(I, 4, K) = PSIS(I, 4, K) / PMAX4
          END DO
        END DO
      END IF
      RETURN
99999 FORMAT ('E: PSI-SCAN FOR', 3I4,
     1 ' SKIPPED (CONTAINS NOT EXACTLY 36*10 DEG. STEPS)')
99998 FORMAT ('E: TOO MANY PSI-SCANS - (ADDITIONAL ONES IGNORED)')
      END SUBROUTINE PLA189
 
