      END SUBROUTINE PLA190
 
      SUBROUTINE PLA191 (MODE, VALUEX, ASTER)
C * Spherical Absorption Correction
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: MODE
      REAL :: Y
      REAL :: STH
      REAL :: RAD
      REAL :: ASTER
      REAL :: VALUEX
      REAL,       DIMENSION(6, 6) :: A
      REAL,       DIMENSION(6)    :: D
      REAL,       DIMENSION(5, 7) :: RMF
      REAL, SAVE, DIMENSION(7)    :: TMC
      REAL, SAVE, DIMENSION(6)    :: X
      RMF = RESHAPE ( (/
     1  1.4997809, -0.07413433, -0.00943029,  0.00040669,  0.00015026,
     2  1.4999662, -0.09367724, -0.01235379, -0.00058663,  0.00050426,
     3  1.4988822, -0.14574555, -0.02797312,  0.00817433, -0.00049362,
     4  1.4995843, -0.24116768, -0.01740035,  0.01511804, -0.00195657,
     5  1.5018433, -0.36087828,  0.03103321,  0.00846806, -0.00183552,
     6  1.5037652, -0.46125653,  0.08544717, -0.00449737, -0.00059269,
     7  1.5043426, -0.49981128,  0.10691309, -0.00980878, -0.00007175/),
     8  (/5, 7/))
C * SPHERICAL ABSORPTION CORRECTION, USING  CURVE FITTING CONSTANTS
C * BASED ON (DWIGGENS, ACTA CRYST(1975),A31,395)
      RAD = ATAN (1.0) / 45.0
C * MODE = 1 : SET UP ANALYTICAL FUNCTIONS (INIT CALL) VALUE = MU*R
C *      = 0 : CALCULATE CORRECTION                    VALUE = THETA
      IF (MODE == 1) THEN
C * GENERATE CURVE FITTING FUNCTION FOR A*(MU*R)
        DO J = 1, 7
          Y = 0.0
          DO I = 1, 5
            Y = Y + RMF(I, J) * VALUEX ** I
          END DO
          TMC(J) = EXP (-Y)
        END DO
C * GENERATE CURVE FITTING FUNCTION FOR AT
        DO K = 1, 6
          STH  = SIN (K * 15.0 * RAD)
          D(K) = TMC(K + 1) - TMC(1)
          DO I = 1, 6
            A(K, I) = STH**(2 * I)
          END DO
        END DO
C * SOLVE A * X = D
        CALL GEN057 (A, X, D, 6)
      ELSE
        ASTER = TMC(1)
        DO J = 1, 6
          K = 2 * J
          ASTER = ASTER + X(J) * VALUEX ** K
        END DO
      END IF
      RETURN
      END SUBROUTINE PLA191
 
      SUBROUTINE PLA192 (NBEG)
C * ABSORPTION CORRECTION ROUTINE (GAUSSIAN INTEGRATION)
C * See Ph. Coppens, Crystallographic computing, 1970
      USE files
      USE parameters
      USE crystal
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: L
      INTEGER :: I0
      INTEGER :: J0
      INTEGER :: I1
      INTEGER :: K1
      INTEGER :: N1
      INTEGER :: JJ
      INTEGER :: KK
      INTEGER :: LL
      INTEGER :: LO
      INTEGER :: MO
      INTEGER :: NIA
      INTEGER :: NIB
      INTEGER :: NIC
      INTEGER :: NLO
      INTEGER :: NMO
      INTEGER :: NPA
      INTEGER :: NPB
      INTEGER :: NPC
      INTEGER :: NCOR
      INTEGER :: INTN
      INTEGER :: ICOR
      INTEGER :: JGRD
      INTEGER :: NBEG
      INTEGER :: NPOINT
      INTEGER :: ISIGMA
      INTEGER, DIMENSION(NXT1) :: NIN
      INTEGER, DIMENSION(NXT1) :: NOUTT
      INTEGER, DIMENSION(3)    :: IGA
      REAL :: R1
      REAL :: R2
      REAL :: GK
      REAL :: HK
      REAL :: DET
      REAL :: GAB
      REAL :: HAB
      REAL :: XMU
      REAL :: AXTL
      REAL :: PXTL
      REAL :: TBAR
      REAL :: TBMU
      REAL :: TXTL
      REAL :: XMAX
      REAL :: XMIN
      REAL :: YMAX
      REAL :: YMIN
      REAL :: ZMAX
      REAL :: ZMIN
      REAL :: RDOTN
      REAL :: RINTN
      REAL :: CHECK
      REAL :: SIGMA
      REAL :: ASTAR
      REAL :: VOLUME
      REAL :: TRANSM
      REAL :: DELTAZ
      REAL, DIMENSION(NXT1)   :: COSIN
      REAL, DIMENSION(NXT1)   :: COSOUT
      REAL, DIMENSION(3)      :: SD
      REAL, DIMENSION(3)      :: SOD
      REAL, DIMENSION(2, 2)   :: BBOUND
      REAL, DIMENSION(2, 2)   :: DBOUND
      REAL, DIMENSION(3)      :: XYZ
      REAL, DIMENSION(3)      :: HKL
      REAL, DIMENSION(4)      :: GRD
      REAL, DIMENSION(3)      :: TEMP
      REAL, DIMENSION(500, 2) :: GAUSS
C * NOTE: REFLECTION DATA STORED BOTTOM UP & GAUSS GRID TOP DOWN
      WRITE (LU6, 99996)
      XMU    = PAR(301)
      NIA    = IPR(421)
      NIB    = IPR(422)
      NIC    = IPR(423)
      NPOINT = 0
C * CONSTRUCTS GAUSSIAN GRID WITHIN CRYSTAL. GRID AXES PARALLEL TO XTAL
C * DETERMINE AND STORE THE GAUSS GRID LIMITS
C * DETERMINE LOWER AND UPPER LIMITS IN X (Y AND Z)
      VOLUME = 0.0
      XMAX   = XTLV(1, 1)
      YMAX   = XTLV(2, 1)
      ZMAX   = XTLV(3, 1)
      XMIN   = XTLV(1, 1)
      YMIN   = XTLV(2, 1)
      ZMIN   = XTLV(3, 1)
      DO I = 2, NVER
        XMAX = MAX (XMAX, XTLV(1, I))
        YMAX = MAX (YMAX, XTLV(2, I))
        ZMAX = MAX (ZMAX, XTLV(3, I))
        XMIN = MIN (XMIN, XTLV(1, I))
        YMIN = MIN (YMIN, XTLV(2, I))
        ZMIN = MIN (ZMIN, XTLV(3, I))
      END DO
      JGRD  = NVDR
      VOID(JGRD)     = XMIN
      VOID(JGRD - 1) = XMAX
      JGRD           = JGRD - 1
      IF (NIA == 0) THEN
        NIA = MAX (8, NINT (4.0 * XMU * (XMAX - XMIN) * PAR(241)))
        NIB = MAX (8, NINT (4.0 * XMU * (YMAX - YMIN) * PAR(241)))
        NIC = MAX (8, NINT (4.0 * XMU * (ZMAX - ZMIN) * PAR(241)))
        IPR(421) = NIA
        IPR(422) = NIB
        IPR(423) = NIC
      END IF
      NIA    = 2 * MAX (1, (NIA + 1) / 2)
      IGA(1) = 0
      CALL GEN115 (GAUSS(1, 1), GAUSS(1, 2), NIA)
      NIB    = 2 * MAX (1, (NIB + 1) / 2)
      IGA(2) = NIA
      CALL GEN115 (GAUSS(IGA(2) + 1, 1), GAUSS(IGA(2) + 1, 2), NIB)
      NIC    = 2 * MAX (1, (NIC + 1) / 2)
      IGA(3) = NIA + NIB
      CALL GEN115 (GAUSS(IGA(3) + 1, 1), GAUSS(IGA(3) + 1, 2), NIC)
      DO NPA = 1, NIA
C * XYZ(IA) ARE FRACTIONAL COORDINATES OF GRID POINTS ALONG A AXIS
         LL = IGA(1) + NPA
         XYZ(1) = XMIN + (XMAX - XMIN) * GAUSS(LL, 1)
C * R1 IS THE GAUSSIAN WEIGHT CORRESPONDING TO XYZ(IA)
         R1 = GAUSS(LL, 2) * (XMAX - XMIN)
C * SCAN OVER ALL POSSIBLE COMBINATIONS OF TWO FACES TO DETERMINE COOR
C * OF EDGES OF CRYSTAL FOR A GIVEN X
         YMIN =  99999.0
         YMAX = -99999.0
         N1   = NFACES - 1
         DO K = 1, N1
           BBOUND(1, 1) = PMILL(K, 2)
           BBOUND(1, 2) = PMILL(K, 3)
           TEMP(1) = PMILL(K, 4) - PMILL(K, 1) * XYZ(1)
           K1 = K + 1
           DO 10 L = K1, NFACES
             BBOUND(2, 1) = PMILL(L, 2)
             BBOUND(2, 2) = PMILL(L, 3)
C * INVERTS ASYMMETRIC 2X2 MATRIX
             DET = BBOUND(1, 1) * BBOUND(2, 2)
     1           - BBOUND(1, 2) * BBOUND(2, 1)
             IF (DET /= 0) THEN
               DBOUND(1, 1) =  BBOUND(2, 2) / DET
               DBOUND(1, 2) = -BBOUND(1, 2) / DET
               DBOUND(2, 1) = -BBOUND(2, 1) / DET
               DBOUND(2, 2) =  BBOUND(1, 1) / DET
               TEMP(2) = PMILL(L, 4) - PMILL(L, 1) * XYZ(1)
               XYZ(2) = DBOUND(1, 1) * TEMP(1)
     1                + DBOUND(1, 2) * TEMP(2)
               XYZ(3) = DBOUND(2, 1) * TEMP(1)
     1                + DBOUND(2, 2) * TEMP(2)
               DO J0 = 1, NFACES
                 CHECK = 0.0
                 DO I0 = 1, 3
                   CHECK = CHECK + PMILL(J0, I0) * XYZ(I0)
                 END DO
                 IF (PMILL(J0, 4) < CHECK - 0.0000001) GO TO 10
               END DO
               YMAX = MAX (YMAX, XYZ(2))
               YMIN = MIN (YMIN, XYZ(2))
             END IF
   10      CONTINUE
         END DO
C * STORE LOWER AND UPPER LIMITS IN Y FOR GIVEN X
         VOID(JGRD - 1) = YMIN
         VOID(JGRD - 2) = YMAX
         JGRD           = JGRD - 2
         DO NPB = 1, NIB
            KK = IGA(2) + NPB
            XYZ(2) = YMIN + (YMAX - YMIN) * GAUSS(KK, 1)
            R2 = GAUSS(KK, 2) * R1 * (YMAX - YMIN)
            ZMAX = - 99999.0
            ZMIN =   99999.0
C * SCAN OVER ALL FACES TO DETERMINE UPPER AND LOWER LIMITS OF Z FOR G
            DO 20 I = 1, NFACES
               IF (PMILL(I, 3) /= 0) THEN
                 XYZ(3) = (PMILL(I, 4) - XYZ(1) * PMILL(I, 1)
     1                  - XYZ(2) * PMILL(I, 2)) / PMILL(I, 3)
                 DO J0 = 1, NFACES
                   CHECK = 0.0
                   DO I0 = 1, 3
                     CHECK = CHECK + PMILL(J0, I0) * XYZ(I0)
                   END DO
                   IF (PMILL(J0, 4) < CHECK - 0.0000001) GO TO 20
                 END DO
                 ZMAX = MAX (ZMAX, XYZ(3))
                 ZMIN = MIN (ZMIN, XYZ(3))
               END IF
   20       CONTINUE
            VOID(JGRD - 1) = ZMIN
            VOID(JGRD - 2) = ZMAX
            JGRD           = JGRD - 2
            DELTAZ = ZMAX - ZMIN
            DO NPC = 1, NIC
              NPOINT = NPOINT + 1
C * STORE FRACTIONAL COORDINATES OF SAMPLING POINTS AND CORRESPONDING
              JJ = IGA(3) + NPC
C * VOL IS EQUAL TO THE VOLUME OF THE CRYSTAL AS A FRACTION OF THE VOL
C * A PARALLELOPIPED WHOSE EDGES ARE PARALLEL TO A,B,C AND OF LENGTH A
C * B(CMS),C(CMS)
              VOLUME = VOLUME + GAUSS(JJ, 2) * R2 * DELTAZ
            END DO
         END DO
      END DO
      WRITE (LU7, 99997, IOSTAT = IOST)
     1  PAR(301), NIA, NIB, NIC, NPOINT, VOLUME * PAR(98)
      NCOR = 0
C * READ REFLECTION LOOP
      I1 = IHLP(NBEG) - 13
      DO
        I1     = I1 + 14
        HKL(1) = VOID(I1)
        HKL(2) = VOID(I1 + 1)
        HKL(3) = VOID(I1 + 2)
        RINTN  = VOID(I1 + 3)
        SIGMA  = VOID(I1 + 4)
        SOD(1) = VOID(I1 + 5)
        SD(1)  = VOID(I1 + 6)
        SOD(2) = VOID(I1 + 7)
        SD(2)  = VOID(I1 + 8)
        SOD(3) = VOID(I1 + 9)
        SD(3)  = VOID(I1 + 10)
        IF (HKL(1) < - 999.0) EXIT
        INTN   = NINT(RINTN)
C * CONVERT FROM 'SHELX' DIRECTION COSINES (WITH RECIPROCAL AXES) TO
C * DIRECT LATTICE COMPONENTS FOR So & S (See Dunitz page 229, 5.11)
C * s = (s.a*)a + (s.b*)b + (s.c*)c ;  PAR(135)..PAR(137) = a*, b*, c*
C * INCEDENT BEAM REVERSED
        DO I = 1, 3
          SOD(I) = SOD(I) * PAR(134 + I)
          SD(I)  = SD(I)  * PAR(134 + I)
        END DO
        NCOR = NCOR + 1
C * WRITE HEADER-LINE
        IF (NCOR == 1) THEN
          CALL PLA262 (0)
          CALL PLA262 (2)
          WRITE (LU7, 99999, IOSTAT = IOST)
        END IF
C * CALCULATE ABSORPTION CORRECTION FOR THIS REFLECTION
C * DETERMINES COMPONENTS OF INCIDENT AND DIFFRACTED BEAMS AND COMPONENTS
C * OF NORMAL TO DIFFRACTION PLANE AND NORMAL TO INCIDENT BEAM IN
C * DIFFRACTION PLANE AND CALCULATES THE ABSORPTION CORRECTION
C * SOD AND SD ARE THE COMPONENTS OF THE INCIDENT AND DIFFRACTED RAYS
C * IN DIRECT SPACE
C * CALCULATES PATH LENGTH OF RAY IN CRYSTAL FOR EACH OF THE SAMPLING
C * POINTS OF THE GAUSSIAN GRID AND THE ABSORPTION CORRECTION
        TRANSM = 0.0
        TBAR   = 0
        MO     = 1
        LO     = 1
C * CALCULATE COSINES OF ANGLES OF REVERSED INCIDENT AND DIFFRACTED RAYS
C * WITH A FACE
        DO K = 1, NFACES
          COSIN(MO)  = 0.0
          COSOUT(LO) = 0.0
          DO I = 1, 3
            COSIN(MO)  = COSIN(MO)  + SOD(I) * PMILL(K, I)
            COSOUT(LO) = COSOUT(LO) + SD(I)  * PMILL(K, I)
          END DO
C * REJECT FACES FOR WHICH ANGLE BETWEEN INCIDENT BEAM AND FACENORM ACUTE
          IF (COSIN(MO) > 0.0) THEN
            NIN(MO) = K
            MO      = MO + 1
          END IF
C * REJECT FACE IF ANGLE BETWEEN DIFFRACTED RAY AND FACE NORMAL IS OBTUSE
          IF (COSOUT(LO) > 0.0) THEN
            NOUTT(LO) = K
            LO        = LO + 1
          END IF
        END DO
        MO = MO - 1
        LO = LO - 1
C * CALCULATE PATH LENGTH AND ABSORPTION FOR EACH OF THE SAMPLING POINTS
        JGRD = NVDR
        XMIN = VOID(JGRD)
        XMAX = VOID(JGRD - 1)
        JGRD = JGRD - 1
        DO NPA = 1, NIA
          LL     = IGA(1) + NPA
          GRD(1) = XMIN + (XMAX - XMIN) * GAUSS(LL, 1)
          R1     = GAUSS(LL, 2) * (XMAX - XMIN)
          YMIN   = VOID(JGRD - 1)
          YMAX   = VOID(JGRD - 2)
          JGRD   = JGRD - 2
          DO NPB = 1, NIB
            KK     = IGA(2) + NPB
            GRD(2) = YMIN + (YMAX - YMIN) * GAUSS(KK, 1)
            R2     = GAUSS(KK, 2) * R1 * (YMAX - YMIN)
            ZMIN   = VOID(JGRD - 1)
            ZMAX   = VOID(JGRD - 2)
            JGRD   = JGRD - 2
            DELTAZ = ZMAX - ZMIN
            DO NPC = 1, NIC
              JJ     = IGA(3) + NPC
              GRD(3) = ZMIN + DELTAZ * GAUSS(JJ, 1)
              GRD(4) = GAUSS(JJ, 2) * R2 * DELTAZ
              GK     = 100000.0
              HK     = 100000.0
              DO K = 1, MO
                RDOTN = 0.0
                NMO   = NIN(K)
                DO I = 1, 3
                  RDOTN = RDOTN + GRD(I) * PMILL(NMO, I)
                END DO
                GAB = (PMILL(NMO, 4) - RDOTN) / COSIN(K)
C * CHOOSE MINIMUM PATH AS TRUE PATH LENGTH
                GK = MIN (GK, GAB)
              END DO
              DO K = 1, LO
                RDOTN = 0.0
                NLO = NOUTT(K)
                DO I = 1, 3
                  RDOTN = RDOTN + GRD(I) * PMILL(NLO, I)
                END DO
                HAB = (PMILL(NLO, 4) - RDOTN) / COSOUT(K)
                HK = MIN (HK, HAB)
              END DO
C * MULTIPLY ABSORPTION FOR EACH GRID POINT BY ITS GAUSSIAN WEIGHT
C * SUM ABSORPTION OVER ALL SAMPLING POINTS
              PXTL   = GK + HK
              AXTL   = EXP (-XMU * PXTL)
              TXTL   = PXTL * AXTL
              TBAR   = TBAR   + GRD(4) * TXTL
              TRANSM = TRANSM + GRD(4) * AXTL
            END DO
          END DO
        END DO
        ASTAR = VOLUME / TRANSM
        TBAR  = TBAR   / VOLUME
        TBMU  = ALOG (ASTAR)
C * COMPUTE I(COR)
        ICOR   = NINT (RINTN * ASTAR)
        TRANSM = 1.0 / ASTAR
        ISIGMA = NINT (SIGMA * ASTAR)
        VOID(I1 + 11) = TRANSM
C * PAPER OUTPUT AND WRITE HEADING
        IF (IGBL(57) > 0) THEN
          CALL PLA262 (1)
          WRITE (LU7, 99998, IOSTAT = IOST)
     1      (NINT (HKL(I)), I = 1, 3), TRANSM, TBMU, INTN, NINT(SIGMA),
     2      ICOR, ISIGMA, TBAR
        END IF
      END DO
C * END OF FILE
      RETURN
99999 FORMAT ('  H  K  L  Transm    Mu*T   Intensity  Sigma    I(cor) ',
     1  ' Sig(cor)    Tbar', /, 80('='), /)
99998 FORMAT (3I3, F8.5, F9.4, I10, I7, I10, I7, F12.6)
99997 FORMAT (//, 'Mu = ', F10.2, ' mm-1', /,
     1        'A Grid of ', 2(I2, ' X '), I2, ' =', I6,
     2 ' Sampling Points.', //,
     3 'Crystal Volume =', 8X, F13.8, ' MM**3.')
99996 FORMAT (':: Gaussian Integration - ',
     1 'See Ph. Coppens, Crystallographic computing, 1970', /)
      END SUBROUTINE PLA192
 
      MODULE tompa
      SAVE
      INTEGER, PARAMETER :: NTMP = 4000
      INTEGER :: ND
      INTEGER :: NF
      INTEGER :: NG
      INTEGER :: IL
      INTEGER :: NC
      INTEGER :: IEX
      INTEGER :: ISK
      INTEGER :: JNK
      INTEGER :: ISK2
      INTEGER :: JNK1
      INTEGER :: JNK3
      INTEGER :: ISTED
      INTEGER :: ISTVT
      INTEGER :: ISTNV
      INTEGER :: ISTTR
      INTEGER :: ISTNP
      INTEGER :: IENPL
      INTEGER :: IENNP
      INTEGER :: IENNV
      INTEGER :: IENED
      INTEGER :: IENVT
      INTEGER :: IENTR
      INTEGER :: IENPT
      INTEGER :: MAXUTL
      INTEGER, DIMENSION(4)    :: IB
      INTEGER, DIMENSION(2)    :: IE
      INTEGER, DIMENSION(2)    :: JI
      INTEGER, DIMENSION(2)    :: JT
      INTEGER, DIMENSION(NTMP) :: ISTK
      DOUBLE PRECISION :: VT
      DOUBLE PRECISION :: TT
      DOUBLE PRECISION :: AMU
      DOUBLE PRECISION :: VMUL
      DOUBLE PRECISION, DIMENSION(12)   :: D
      DOUBLE PRECISION, DIMENSION(2)    :: CX
      DOUBLE PRECISION, DIMENSION(2)    :: CY
      DOUBLE PRECISION, DIMENSION(2)    :: CZ
      DOUBLE PRECISION, DIMENSION(2)    :: DEV
      DOUBLE PRECISION, DIMENSION(NTMP) :: RSTK
      END MODULE tompa
 
      SUBROUTINE PLA193 (NBEG)
C * DE MEULENAER & TOMPA ABSORPTION CORRECTION (ADAPTED FROM ALCOCK VERSION)
      USE files
      USE parameters
      USE crystal
      USE tompa
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: I1
      INTEGER :: KA
      INTEGER :: LA
      INTEGER :: II
      INTEGER :: JJ
      INTEGER :: JA
      INTEGER :: NU
      INTEGER :: INV
      INTEGER :: IP1
      INTEGER :: JP1
      INTEGER :: NPP
      INTEGER :: INED
      INTEGER :: IERR
      INTEGER :: JUN1
      INTEGER :: NBEG
      INTEGER :: NFMX
      INTEGER :: NMEM
      INTEGER :: NFMX1
      INTEGER :: NFMX2
      INTEGER :: JUN11
      DOUBLE PRECISION :: C1
      DOUBLE PRECISION :: C2
      DOUBLE PRECISION :: C3
      DOUBLE PRECISION :: C4
      DOUBLE PRECISION :: C5
      DOUBLE PRECISION :: C6
      DOUBLE PRECISION :: AI
      DOUBLE PRECISION :: AJ
      DOUBLE PRECISION :: BI
      DOUBLE PRECISION :: BJ
      DOUBLE PRECISION :: CI
      DOUBLE PRECISION :: CJ
      DOUBLE PRECISION :: DA
      DOUBLE PRECISION :: DB
      DOUBLE PRECISION :: DC
      DOUBLE PRECISION :: DI
      DOUBLE PRECISION :: DJ
      DOUBLE PRECISION :: RM
      DOUBLE PRECISION :: SH
      DOUBLE PRECISION :: VA
      DOUBLE PRECISION :: VM
      DOUBLE PRECISION :: XH
      DOUBLE PRECISION :: XK
      DOUBLE PRECISION :: XL
      DOUBLE PRECISION :: XP
      DOUBLE PRECISION :: YP
      DOUBLE PRECISION :: ZP
      DOUBLE PRECISION :: YAR
      DOUBLE PRECISION :: ZAR
      DOUBLE PRECISION :: DEN
      DOUBLE PRECISION :: AIJ
      DOUBLE PRECISION :: BIJ
      DOUBLE PRECISION :: CIJ
      DOUBLE PRECISION :: CPD
      DOUBLE PRECISION :: CPX
      DOUBLE PRECISION :: CPY
      DOUBLE PRECISION :: CPZ
      DOUBLE PRECISION :: RAD
      DOUBLE PRECISION :: VV1
      DOUBLE PRECISION :: VV2
      DOUBLE PRECISION :: XAR
      DOUBLE PRECISION :: VOLM
      DOUBLE PRECISION :: SIGF
      DOUBLE PRECISION :: QHKL
      DOUBLE PRECISION :: DIST
      DOUBLE PRECISION :: FREL
      DOUBLE PRECISION :: CPBS
      DOUBLE PRECISION :: COSA
      DOUBLE PRECISION :: SINA
      DOUBLE PRECISION :: SINBS
      DOUBLE PRECISION :: SINGS
      DOUBLE PRECISION :: COSAS
      DOUBLE PRECISION :: COSBS
      DOUBLE PRECISION :: COSGS
      DOUBLE PRECISION :: CACBS
      DOUBLE PRECISION :: ABCGS
      DOUBLE PRECISION :: BCCAS
      DOUBLE PRECISION :: SINPBS
      CHARACTER(len=8) :: ITX
C * NOTE MOST CALCULATIONS ARE IN DOUBLE PRECISION - ESSENTIAL FOR 32 BIT
C * STORAGE FOR MAIN ARRAYS IS OPEN-ENDED, 1-DIMENSIONAL IN RSTK/ISTK
C * FROM IENPL ON ARE THE START AND END MARKERS AND INCREMENTS FOR EACH
C * SECTION OF THE ARRAY.  ISTXX AND IENXX MARK THE FIRST AND LAST
C * POINTS OF THE GROUPS, EACH INCXX LONG.  SO IENXX + INCXX = ISTYY
C * VT  = TOTAL VOLUME
C * TT  = TOTAL TRANSMISSION
C * AMU = LINEAR ABS COEFF
      NMEM   = 0
      RAD    = DBLE (RGBL(6))
      MAXUTL = 0
C * GET MU
      AMU    = DBLE (PAR(301))
      CALL PLA262 (0)
      WRITE (LU7, 99999, IOSTAT = IOST)
      WRITE (LU6, 99999, IOSTAT = IOST)
      WRITE (LU7, 99998, IOSTAT = IOST) AMU
      WRITE (LU6, 99998, IOSTAT = IOST) AMU
C * GET CELL PARAMETERS
      SINA  = SIN (DBLE (PAR(244)) / RAD)
      COSA  = COS (DBLE (PAR(244)) / RAD)
C * CALCULATE RECIPROCAL LATTICE CONSTANTS
      COSAS = COS (DBLE (PAR(138)) / RAD)
      COSBS = COS (DBLE (PAR(139)) / RAD)
      COSGS = COS (DBLE (PAR(140)) / RAD)
      SINBS = SIN (DBLE (PAR(139)) / RAD)
      SINGS = SIN (DBLE (PAR(140)) / RAD)
      BCCAS = DBLE (PAR(136)) * DBLE (PAR(137)) * COSAS
      CACBS = DBLE (PAR(137)) * DBLE (PAR(135)) * COSBS
      ABCGS = DBLE (PAR(135)) * DBLE (PAR(136)) * COSGS
C * FIRST PROCESS PLANE DATA
C * AN HKL PLANE - PLANES GIVEN IN TERMS OF MILLER INDICES MUST BE CONVERTED.
C * FOR SPEED OF COMPUTING THE CRYSTAL IS SPECIFIED ON ORTHOGONAL AXES
C * THE ANGLES FROM THE PLANE NORMAL TO THE REAL AXES ARE GIVEN BY
C * N - C = L.D/C, WHERE D = INTERPLANE SPACING.  THIS IS THE ANGLE OZ -N
C * ANGLES TO A* = L AND B* = M CAN BE FOUND AS COMPLEMENTS OF THE
C * INTERFACIAL ANGLES TO 100 AND 010 - FORMULA OF INT. TAB. II, 106
C * N-A*(L) IS OX - N DIRECTLY
C * FOR OY - N CONSIDER SPHERICAL TRIANGLE N - A* - B*.  SIDES GAMMA*
C * AND L AND M.    ANGLE N - B*-A* = D COMES FROM STANDARD FORMULA.
C * SO IN TRIANGLE N - B* - Y, KNOWN ANGLES ARE M, 180-D, 90-GAMMA*,
C * AND THIS IS SOLUBLE FOR N - Y
      IENPL = - 5
      DO I = 1, NFACES
        IENPL = IENPL + 6
        XH    = DBLE (PMILL(I, 1))
        XK    = DBLE (PMILL(I, 2))
        XL    = DBLE (PMILL(I, 3))
        DA    = DBLE (PMILL(I, 5))
        QHKL  =  SQRT (
     1   (XH * DBLE (PAR(135)))**2 + (XK * DBLE (PAR(136)))**2
     2 + (XL * DBLE (PAR(137)))**2
     3       + 2 * XK * XL * BCCAS + 2 * XL * XH * CACBS
     4       + 2 * XH * XK * ABCGS)
        CPZ  = XL / (DBLE (PAR(243)) * QHKL)
        CPX  = (XH * DBLE (PAR(135))**2 + XL * CACBS + XK * ABCGS) /
     1          (QHKL * DBLE (PAR(135)))
        CPBS = (XK * DBLE (PAR(136))**2 + XL * BCCAS + XH * ABCGS) /
     1          (QHKL * DBLE (PAR(136)))
        SINPBS = SQRT(ABS(1 - CPBS**2 ))
C * FIRST FIND ANGLE D, IF N COINCIDES WITH B* THEN D IS INDETERMINATE
        IF (ABS (SINPBS) < 1.0D-6) THEN
          CPY = CPBS * SINGS
        ELSE
          CPD = (CPX - COSGS * CPBS) / (SINPBS * SINGS)
C * ITS COMPLEMENT JUST HAS NEGATIVE COSINE
          CPY = CPBS * SINGS - SINPBS * COSGS * CPD
        END IF
        RSTK(IENPL    ) = CPX
        RSTK(IENPL + 1) = CPY
        RSTK(IENPL + 2) = CPZ
        RSTK(IENPL + 3) = DA
      END DO
C * END OF LOOP FOR PLANES CALCULATION
C * INITIALISE POINTERS
C * TEMP STORAGE AT END OF ARRAY
      NPP   = NTMP
      ISTNV = IENPL + 6
      INV   = ISTNV - 10
      NFMX  = IENPL
      NFMX1 = IENPL - 6
      NFMX2 = NFMX1 - 6
C * FIRST FACE
      DO I = 1, NFMX2, 6
        AI  = RSTK(I)
        BI  = RSTK(I + 1)
        CI  = RSTK(I + 2)
        DI  = RSTK(I + 3)
        IP1 = I + 6
C * SECOND FACE
        DO J = IP1, NFMX1, 6
          AJ  = RSTK(J)
          BJ  = RSTK(J + 1)
          CJ  = RSTK(J + 2)
          DJ  = RSTK(J + 3)
          AIJ = BI * CJ - BJ * CI
          BIJ = CI * AJ - CJ * AI
          CIJ = AI * BJ - AJ * BI
          DEN = AIJ * AIJ + BIJ * BIJ + CIJ * CIJ
          IF (DEN /= 0) THEN
            DA  = DI * AJ - DJ * AI
            DB  = DI * BJ - DJ * BI
            DC  = DI * CJ - DJ * CI
            XAR = (DB * CIJ - DC * BIJ) / DEN
            YAR = (DC * AIJ - DA * CIJ) / DEN
            ZAR = (DA * BIJ - DB * AIJ) / DEN
            JP1 = J + 6
C * THIRD FACE
            DO 30 K = JP1, NFMX, 6
              DEN = RSTK(K) * AIJ + RSTK(K + 1) * BIJ
     1            + RSTK(K + 2) * CIJ
              IF (DEN /= 0) THEN
                SH = (RSTK(K + 3) - RSTK(K) * XAR - RSTK(K + 1) * YAR
     1             - RSTK(K + 2) * ZAR) / DEN
                XP = XAR + SH * AIJ
                YP = YAR + SH * BIJ
                ZP = ZAR + SH * CIJ
                NF = 2
C * FURTHER FACES - REALITY OF VERTEX
                DO 20 NU = 1, NFMX, 6
                  IF (NU /= I .AND. NU /= J .AND. NU /= K) THEN
                    DIST = RSTK(NU + 3) - RSTK(NU) * XP
     1                   - RSTK(NU + 1) * YP - RSTK(NU + 2) * ZP
                    IF (DIST > 1.0D-7) THEN
                      GO TO 20
                    ELSE IF (DIST == 1.0D-7) THEN
                      GO TO 10
                    END IF
                    IF (DIST < -1.0D-7) GO TO 30
   10               IF (NU <= K) GO TO 30
C * OTHERWISE WE HAVE THIS VERTEX ALREADY
                    NF = NF + 1
                    ISTK(NPP - NF) = NU
                  END IF
   20           CONTINUE
C * STORE FIRST FACES
                ISTK(NPP)     = I
                ISTK(NPP - 1) = J
                ISTK(NPP - 2) = K
C * STORE VERTICES
                INV           = INV + 10
                RSTK(INV)     = XP
                RSTK(INV + 1) = YP
                RSTK(INV + 2) = ZP
C * THESE MUST BE THE TRUE LOCATIONS AFTER RE-STORING
                ISTK(INV + 4) = ISTNV + NTMP - NPP
                ISTK(INV + 5) = ISTK(INV + 4) + NF
                NPP           = NPP - NF - 1
              END IF
   30       CONTINUE
          END IF
        END DO
      END DO
C * ASSIGN SPACE FOR EDGES, USING EULERS RULE
      IENNV = ISTNV  + NTMP - NPP - 1
      ISTED = IENNV  + 1
      JNK   = (IENPL + 5) / 6
      JNK1  = (INV   + 10 - ISTNV) / 10
      IENED = JNK    + JNK1 - 2
      IENED = ISTED  + (IENED - 1) * 6
      ISTVT = IENED  + 6
      IENVT = ISTVT  + (JNK1 - 1) * 10
      I     = IENVT  + 9
      J     = INV    + 9
C * -1 BECAUSE K RUNS 1 TO 3 NOT 0 TO 2
   40 I = I - 10
      J = J - 10
      IF (I - ISTVT >= -1) THEN
        DO K = 1, 3
          RSTK(I + K) = RSTK(J + K)
        END DO
        ISTK(I + 5) = ISTK(J + 5)
        ISTK(I + 6) = ISTK(J + 6)
        GO TO 40
      END IF
C * TRANSFER NV LIST
      J = NTMP
      DO I = ISTNV, IENNV
        ISTK(I) = ISTK(J)
        J       = J - 1
      END DO
C * AN EDGE BETWEEN TWO VERTICES WITH TWO FACES IN COMMON
      INED = ISTED - 6
      NFMX = IENVT - 10
      II = 0
      DO I = ISTVT, NFMX, 10
        II = II + 1
        NFMX1 = ISTK(I + 4)
        NFMX2 = ISTK(I + 5)
        JNK   = I + 10
        JJ    = II
        DO 50 J = JNK, IENVT, 10
          JJ  = JJ + 1
          NPP = ISTK(J + 4)
          NF  = ISTK(J + 5)
          M   = 0
          DO K = NFMX1, NFMX2
            JUN1 = ISTK(K)
            DO L = NPP, NF
              JUN11 = ISTK(L)
              IF (JUN1 == JUN11) THEN
                IF (M <= 0) THEN
                  M = 1
                  NMEM = JUN11
                ELSE
C * SUCCESS
                  INED           = INED + 6
                  ISTK(INED)     = NMEM
                  ISTK(INED + 1) = JUN1
                  ISTK(INED + 2) = I
                  ISTK(INED + 3) = J
                  NMEM = 1 + (NMEM - 1) / 6
                  JUN1 = 1 + (JUN1 - 1) / 6
                  GO TO 50
                END IF
              END IF
            END DO
          END DO
   50   CONTINUE
      END DO
C * CHECK CORRECT NO OF EDGES
      IF (INED /= IENED) THEN
        WRITE (LU6, 99997, IOSTAT = IOST)
        WRITE (LU7, 99997, IOSTAT = IOST)
        IENPL = 0
      END IF
      IF (IENPL > 0) THEN
        VM = 0.0D+0
        RM = 0.0D+0
        DO I = 1, 3
          D(I + 3) = 0.0D+0
          D(I)     = 0.0D+0
        END DO
        DO I = ISTVT, IENVT, 10
          DO J = 1, 3
            VT = RSTK(I + J - 1)
            IF (D(J) > VT) THEN
              D(J) = VT
            ELSE IF (D(3 + J) < VT) THEN
              D(3 + J) = VT
            END IF
          END DO
        END DO
        DO I = 1, 3
          VT = D(3 + I) - D(I)
          IF (RM <  VT)       RM =  VT
          IF (VM <  D(3 + I)) VM =  D(3 + I)
          IF (VM < -D(I))     VM = -D(I)
        END DO
C * NOW RESCALE
        VMUL = 1.0D+0 / VM
        DO I = 1, IENPL, 6
          RSTK(I + 3) = RSTK(I + 3) * VMUL
        END DO
        JNK = ISTVT - 1
        DO I = JNK, IENVT, 10
          DO J = 1, 3
            RSTK(I + J) = RSTK(I + J) * VMUL
          END DO
        END DO
        VOLM = 1.0D+0 / (6.0D+0 * VMUL * VMUL * VMUL)
        CALL PLA194 (1)
C * CALL DETERMINES VOLUME ONLY (ALTERED FROM ORIG, NOT RESCALED IN SUBR.
        VT = VT * VOLM
        TT = 1.0D+0
        WRITE (LU7, 99993, IOSTAT = IOST) VT
        VA  = 0.1D-2 * VT
        VV1 = VT - VA
        VV2 = VT + VA
        AMU = AMU / VMUL
        CALL PLA262 (0)
        IF (IGBL(57) > 0) THEN
          CALL PLA262 (2)
C * SHELX(L) INPUT DATA HAS F AND SIGMA(F) - TREAT AS SUCH
          IF (IPR(648) == 3) THEN
            WRITE (LU7, 99995, IOSTAT = IOST) '   F', '   Sig(F)'
C * SHELX(L) INPUT DATA HAS F**2 AND SIGMA(F**2) - TREAT AS SUCH
          ELSE IF (IPR(648) == 4) THEN
            WRITE (LU7, 99995, IOSTAT = IOST) 'F**2', 'Sig(F**2)'
          END IF
        END IF
        I1   = IHLP(NBEG) - 13
        DO
          I1   = I1 + 14
          JA   = NINT (VOID(I1))
          IF (JA /= - 1000) THEN
            KA   = NINT (VOID(I1 + 1))
            LA   = NINT (VOID(I1 + 2))
            FREL = DBLE (VOID(I1 + 3))
            SIGF = DBLE (VOID(I1 + 4))
            C1   = DBLE (VOID(I1 + 5))
            C2   = DBLE (VOID(I1 + 6))
            C3   = DBLE (VOID(I1 + 7))
            C4   = DBLE (VOID(I1 + 8))
            C5   = DBLE (VOID(I1 + 9))
            C6   = DBLE (VOID(I1 + 10))
C * DIRECTION COSINES OF INCIDENT AND REVERSED
C * TRANSFORM FROM SHELX TO TOMPA STYLE DIRECTION COSINES
C * DIFFRACTED RAYS IN CX(1), CY(1), CZ(1), CX(2), CY(2), CZ(2)
            CX(1) = - C1
            CX(2) = - C2
            C3    =  (C3 - C1 * COSGS) / SINGS
            C4    =  (C4 - C2 * COSGS) / SINGS
            CY(1) = - C3
            CY(2) = - C4
            CZ(1) = -(C5 - C1 * COSBS + C3 * SINBS * COSA)
     1            / (SINBS * SINA)
            CZ(2) = -(C6 - C2 * COSBS + C4 * SINBS * COSA)
     1            / (SINBS * SINA)
            IERR  = 2
            CALL PLA194 (2)
            VT = VT * VOLM
            IF (TT > 0.9995D0) THEN
              TT = 1.0D+0
              IF (TT < 1.0D0) THEN
                IF (TT > 0) THEN
                  IF (VT <= VV2) THEN
                    IF (VV1 <= VT) GO TO 60
                  END IF
                  IF (TT > 0.999D0) THEN
                    TT = 1.0D+0
                    IERR = 2
                  ELSE
                    IERR = 1
                    ITX = 'VOLUME  '
                    GO TO 60
                  END IF
                END IF
              END IF
              IF (TT > 0.999D0) THEN
                TT = 1.0D+0
                IERR = 2
              ELSE
                ITX = 'TRANS.'
                TT  = ABS (TT)
                IF (TT < 0.01D0) TT = 0.1D-1
                IERR = 1
              END IF
            END IF
C * ERROR MONITOR IF ERROR FLAG SET
   60       IF (IERR == 1) THEN
              GO TO 70
            ELSE IF (IERR == 2) THEN
              GO TO 80
            END IF
   70       CALL PLA262 (1)
            WRITE (LU7, 99992, IOSTAT = IOST) JA, KA, LA, TT, VT, ITX
   80       IF (IPR(648) == 3) THEN
C * CORRECTS F & SIG(F)
              FREL = FREL / SQRT (TT)
              SIGF = SIGF / SQRT (SQRT (TT))
            ELSE IF (IPR(648) == 4) THEN
C * CORRECTS F**2 & SIGMA
              FREL = FREL / TT
              SIGF = SIGF / TT
            ENDIF
            VOID(I1 + 11) = SNGL (TT)
            IF (IGBL(57) > 0) THEN
              CALL PLA262 (1)
              WRITE (LU7, 99994, IOSTAT = IOST)
     1          JA, KA, LA, FREL, SIGF, TT, VT
            END IF
          ELSE
            EXIT
          END IF
        END DO
        WRITE (LU7, 99996, IOSTAT = IOST) MAXUTL
      END IF
      RETURN
99999 FORMAT ('Analytical Absorption Correction Program', /, 80('-'),
     1  /, '(see. N.W. Alcock (1970). Cryst. Computing, p271)', /)
99998 FORMAT (':: Mu = ', F8.3, ' mm(-1)', /)
99997 FORMAT (':: Crystal not Finite - Additional Bounding Planes ',
     1        'Needed')
99996 FORMAT (/, ':: Array Size Needed = ', I5)
99995 FORMAT (3X, 'H   K   L', 7X, A, 5X, A, 5X, 'Transmission', 6X,
     1       'Volume (mm3)', /, '   -   -   -', 7X, '----', 5X, 9('-'),
     2       5X, 12('-'), 6X, 12('-'))
99994 FORMAT (3I4, 2F12.2, 4X, F12.5, 7X, F14.11)
99993 FORMAT (/, 'Crystal Volume =', 2X, F14.11, ' mm3', //)
99992 FORMAT (3I4, ' Transm ', E12.5, ' Volume ', F12.6, 1X, A,
     1        ' in Error')
      END SUBROUTINE PLA193
 
      SUBROUTINE PLA194 (IZ)
C * ABSTOMPA (2)
      USE files
      USE tompa
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: K5
      INTEGER :: J2
      INTEGER :: J3
      INTEGER :: J4
      INTEGER :: J5
      INTEGER :: J6
      INTEGER :: J7
      INTEGER :: J8
      INTEGER :: I0
      INTEGER :: IZ
      INTEGER :: LA
      INTEGER :: LB
      INTEGER :: JA
      INTEGER :: JB
      INTEGER :: IP
      INTEGER :: IQ
      INTEGER :: IT
      INTEGER :: IT2
      INTEGER :: IPC
      INTEGER :: JPC
      INTEGER :: JSK
      INTEGER :: IND
      INTEGER :: NPER
      INTEGER :: LRETX
      INTEGER, DIMENSION(6) :: NE
      DOUBLE PRECISION       :: TX
      DOUBLE PRECISION, SAVE :: VZ
      DOUBLE PRECISION       :: DE2
      DOUBLE PRECISION       :: DEN
      DOUBLE PRECISION       :: FRP
      DOUBLE PRECISION, SAVE :: FLIM
C * MAJOR STORAGE ARRAY IS RSTK/ISTK.  THIS IS IN GROUPS
C * 1 TO IENPL(6) IS PLANES
C * +0,1,2,3 = X,Y,Z,D FOR PLANE
C * +4,5   = 1/-1 FOR LIT/SHADED IN DIR 1/2
C * ISTNV TO IENNV (NVLIST) HAS FACES OF EACH VERTEX. SEE BELOW
C * ISTED TO IENED(6) IS EDGES
C * +0,1   = TWO CONTRIBUTING FACES
C * +2,3   = TWO CONTRIBUTING VERTICES
C * +4,5   = 1/0/-1 FOR LIT/EDGE/SHADED IN DIR 1/2
C * ISTVT TO IENPT(10) IS POINTS (IENVT WITHIN THIS ENDS VERTICES)
C * STORAGE DIFFERS FOR EACH TYPE OF POINT, BUT 0-3 ARE CONSTANT
C * +0,1,2 = X,Y,Z COORDINATES
C * +3     = RHO, THE DISTANCE*MU TO IT FROM ITS SHADING FACE(S)
C *  VERTICES
C * +4,5   = FIRST(4) AND LAST(5) LOCATION IN NVLIST OF FACES ROUND
C *          THIS VERTEX
C * +6,7   = LOCATION FOR SP0(6) OR SQ0(7) POINT
C * +8,9   = NO OF FACE SHADING IT IN DIR 1/2
C *  POINTS SP0 OR SQ0
C * +4     = FACE CONTAINING IT
C * +5     = POSSIBLE FACE SHADING IT
C * +6     = 1 FOR SP0, 2 FOR SQ0
C *  POINTS SPQ
C * +4     = EDGE GENERATING IT
C * +6     = 3 FOR S12, 4 FOR S21
C *  POINTS S0P (S0Q)
C * +4     = EDGE GENERATING IT
C * +5     = EDGE CONTAINING IT
C * +6     = ZERO
C * +7     = FACE SHADING IT IN DIRECTION Q
C *   POINTS S00
C * +4     = EDGE GENERATING IT FROM DIRECTION P
C * +5     = EDGE GENERATING IT FROM DIRECTION Q
C * THE VOLUME CALCULATION CONTINUES
C * ISTNP TO IENNP FOR LIST OF FACES
C * ISTTR TO IENTR(INCTR) FOR THE TETRAHEDRA
C * +0,1,2 = THREE MINORS
C * +3,4,5 FOR NUMBERS OF THREE FACES
C * OTHER STORAGE
C * D        COLLECTS EQUATION COEFFICIENTS
C * JI,JT    GIVE LIMITS OF SOP STORAGE
C * IL       INDICATES CURRENT TYPE OF POINT
C * NE       GIVES NUMBER OF EACH TYPE OF POINT
C *
C * DOUBLE PRECISION FUNCTIONS NOT NEEDED HERE
C * THIS PROGRAM REALLY MUST BE READ WITH TOMPA'S MANUAL
C * OR WITH HIS PAPER OR WITH THE SUMMARY IN' CRYSTALLOGRAPHIC COMPUTING'
      JSK = 0
      DE2 = 0
      J   = 0
C * HERE JUST TO FIND VOLUME.  NB. THESE FORM PART OF THE PRELIM ASSIGNS
      IF (IZ == 1) THEN
        IEX   = 1
        ISK   = 1
        ISK2  = 1
        VT    = 0.0D+0
        IENPT = IENVT
        ISTNP = IENVT + 10
        IENNP = ISTNP - 1
        DO I = ISTVT, IENVT, 10
          IENNP       = IENNP + 1
          ISTK(IENNP) = I
        END DO
        GO TO 220
      END IF
C * HERE FOR MAIN CALC
C * LABEL B IN BLOCK A
C * ENTRY POINT WITH DIR COSINES
C * INITIALISE AND THEN DISCOVER WHICH EDGES ARE LIT OR SHADED
      DO I = 1, 6
        NE(I) = 0
      END DO
      DE2    = 0
      DEV(2) = 0
      VT     = 0.0D+0
      TT     = 0
      IL     = 1
      IENPT  = IENVT
      DO IP = 1, 2
        DO I = 1, IENPL, 6
C * TEST FACES IF IN LIGHT OR SHADE
          DEN = RSTK(I) * CX(IP) + RSTK(I + 1) * CY(IP)
     1        + RSTK(I + 2) * CZ(IP)
C * THIS CALCS. THE ANGLE BETWEEN THE RAY AND THE FACE NORMAL.
C * REMEMBER THE ORIGIN IS WITHIN THE CRYSTAL
          IF (DEN < 0.0D0) THEN
C * FACES SHADED IF ON EDGE
            ISTK(I + IP + 3) = 1
          ELSE
            ISTK(I + IP + 3) = -1
          END IF
        END DO
        DO I = ISTED, IENED, 6
C * TEST EDGES IF IN LIGHT OR SHADE
C * LIT IF BOTH FACES LIT, OR SHADED IF NEITHER. OTHERWISE ON EDGE.
          JA  = ISTK(I)
          JB  = ISTK(I + 1)
          IND = ISTK(JA + IP + 3) + ISTK(JB + IP + 3)
          IF (IND < 0) THEN
            ISTK(I + IP + 3) = -1
          ELSE IF (IND == 0) THEN
            ISTK(I + IP + 3) = 0
          ELSE
            ISTK(I + IP + 3) = 1
          END IF
        END DO
      END DO
C * IN B FINDS POINTS SP0.  IN C POINTS SPQ. FOR ALL LIT VERTICES
C * AND FOR BOTH RAY DIRECTIONS
C * BLOCK B
      IENPT = IENVT
      DO 20 IP = 1, 2
        JNK1 = IP
        IQ   = 3 - IP
        DO 10 J = ISTVT, IENVT, 10
          JNK = J
C * KEEP THESE JNK AND JNK1 IN THIS LOOP
          ISTK(J + IP + 5) = 0
          ISTK(J + IP + 7) = 0
          IF (IP == 1) RSTK(J + 3) = 0.0D+0
          M  = ISTK(J + 4)
          LA = ISTK(J + 5)
C * LIST OF FACES
          LB = ISTK(M)
          NC = ISTK(LB + IP + 3)
C * FIRST FACE IS THIS.  ALL OTHERS MUST AGREE
          M = M + 1
          DO J5 = M, LA
            LB = ISTK(J5)
            IF (NC /= ISTK(LB + IP + 3)) GO TO 10
C * IF VERTEX IS ON BOUNDARY NO ACTION TO 10
          END DO
          IF (NC < 0) THEN
            ND = 1
C * SHADED VERTEX
            CALL PLA195 (DEN)
            RSTK(J + 3) = RSTK(J + 3) + DEN * AMU
C * NO OF FACE SHADING IT
            ISTK(J + IP + 7) = NC
          ELSE IF (NC == 0) THEN
            GO TO 20
          ELSE
            ND = -1
C * VERTEX IN LIGHT FIND ITS SPO
            CALL PLA195 (DEN)
            NE(IL) = NE(IL) + 1
            IENPT  = IENPT + 10
C * STORE NO OF SPO FOR VERTEX
            ISTK(J + IP + 5) = IENPT
C * CONTAINING FACE FOR SPO
            ISTK(IENPT + 4) = NC
C * IDENTIFICATION
            ISTK(IENPT + 6) = IL
            ISTK(IENPT + 5) = 0
C * CLEAR REST TO ZERO. STRICTLY NOT ESSENTIAL, BUT HELPS DIAGNOSTICS
            ISTK(IENPT + 7) = 0
            ISTK(IENPT + 8) = 0
            ISTK(IENPT + 9) = 0
C * COORDINATES AND R VALUE
            RSTK(IENPT)     = RSTK(J)     + DEN * CX(IP)
            RSTK(IENPT + 1) = RSTK(J + 1) + DEN * CY(IP)
            RSTK(IENPT + 2) = RSTK(J + 2) + DEN * CZ(IP)
            FRP = DEN
            RSTK(IENPT + 3) = DEN * AMU
C * IS IT SHADED IN DIRECTION Q
            IF (ISTK(NC + IQ + 3) == -1) THEN
              ND   = 1
              JNK  = IENPT
              JNK1 = IQ
              CALL PLA195 (DEN)
              JNK1 = IP
              JNK  = J
C * STORE SHADING FACE AND R
              ISTK(IENPT + 5) = NC
              RSTK(IENPT + 3) = (FRP + DEN) * AMU
            END IF
C * THIS IS BLOCK C SEARCH FOR POINTS SPQ
            IL = IL + 2
            DO K = ISTED, IENED, 6
              IF (ISTK(K + IQ + 3) == 1) THEN
C * A POSSIBLE EDGE. COMPUTE DELTAS WITH S=1, SE1=3,SE2=4
                IB(1) = J
                IB(2) = J
                IB(3) = ISTK(K + 2)
                IB(4) = ISTK(K + 3)
                CALL PLA196
C * ASSEMBLE EQU COEFFICIENTS
                D(10) = - D(3)
C * THESE DETERMINE THE INTERSECTION OF THE RAY WITH THE PLANE THROUGH
C * ANY EDGE
                D(11) = - D(6)
                D(12) = - D(9)
                D(7)  = - D(2)
                D(9)  = - D(8)
                D(8)  = - D(5)
                D(1)  =   CX(IP)
                D(2)  =   CY(IP)
                D(3)  =   CZ(IP)
                D(4)  = - CX(IQ)
                D(5)  = - CY(IQ)
                D(6)  = - CZ(IQ)
C * FOR EQUATION SOLUTIONS
                CALL GEN157 (D, 3)
C * RETURNS WITH D1 TO D4 = 4 DETERMINANTS(NMP,NMQ,NM,DN)
                NC = 1
                IF (ABS (D(4)) > 1.D-9) THEN
                  DEN = D(3) / D(4)
                  IF (DEN >= - 0.00001D0) THEN
                    IF (1.00001D0 >= DEN) THEN
                      NC = 0
C * A VALID SOLUTION, K LESS THAN 1
                      IF (D(1) /= 0) THEN
C * NOT COINCIDENT WITH VERTEX. OTHERWISE USED ANYWAY
C * THIS IS A NEW TEST.  IT REDUCES THE NUMBER OF POINTS.
                        DEN = D(1) / D(4)
                        IF (DEN > 0) THEN
                          IF (DEN <= FRP) THEN
C * THE INTERSECTION OF EDGE PLANE AND RAY IS WITHIN THE CRYSTAL.
                            NE(IL)          = NE(IL) + 1
                            IENPT           = IENPT  + 10
                            RSTK(IENPT)     = RSTK(J)     + DEN * CX(IP)
                            RSTK(IENPT + 1) = RSTK(J + 1) + DEN * CY(IP)
                            RSTK(IENPT + 2) = RSTK(J + 2) + DEN * CZ(IP)
                            TX              = D(2) / D(4)
                            RSTK(IENPT + 3) = (DEN + TX) * AMU
C * STORE EDGE CONTAINING AN SPQ AND ITS IDENTIFICATION
                            ISTK(IENPT + 4) = K
                            ISTK(IENPT + 5) = 0
                            ISTK(IENPT + 6) = IL
C * CLEAR
                            ISTK(IENPT + 7) = 0
                            ISTK(IENPT + 8) = 0
                            ISTK(IENPT + 9) = 0
                          END IF
                        END IF
                      END IF
                    END IF
                  END IF
                END IF
              END IF
            END DO
            IL = IL - 2
          END IF
  10    CONTINUE
        IL = IL + 1
  20  CONTINUE
C * THIS IS BLOCK D FOR POINTS SOP
      ND = 1
      IL = IL + 2
      DO IP = 1, 2
        JI(IP) = IENPT + 10
        IQ     = 3 - IP
        JNK1   = IQ
        DO K = ISTED, IENED, 6
          IF (ISTK(K + IP + 3) == 1) THEN
C * EDGE LIT
            DO K5 = ISTED, IENED, 6
C * 2ND EDGE SHADED
              IF (ISTK(K5 + IP + 3) == -1) THEN
                IB(1) = ISTK(K  + 2)
                IB(2) = ISTK(K  + 3)
                IB(3) = ISTK(K5 + 2)
                IB(4) = ISTK(K5 + 3)
C * USES FOUR VERTICES OF EDGES
                CALL PLA196
                D(10) = D(3)
                D(11) = D(6)
                D(12) = D(9)
                D(3)  = D(7)
                D(6)  = D(8)
                TX    = D(2)
                D(2)  = D(4)
                D(4)  = TX
                D(7)  = - CX(IP)
                D(8)  = - CY(IP)
                D(9)  = - CZ(IP)
                CALL GEN157 (D, 3)
                NC = 1
                IF (ABS (D(4)) > 1.D-9) THEN
                  DEN = D(1) / D(4)
                  IF (DEN >= - 0.00001D0) THEN
                    IF (1.00001D0 >= DEN) NC = 0
                  END IF
                END IF
                IF (NC == 0) THEN
                  NC = 1
                  IF (ABS (D(4)) > 1.D-9) THEN
                    TX = D(2) / D(4)
                    IF (TX >= - 0.00001D0) THEN
                      IF (1.00001D0 >= TX) NC = 0
                    END IF
                  END IF
                  IF (NC == 0) THEN
C * BOTH K.S LESS THAN 1
                    IENPT = IENPT + 10
                    RSTK(IENPT    ) = RSTK(IB(4)    )
     1                + TX * (RSTK(IB(3)    ) - RSTK(IB(4)    ))
                    RSTK(IENPT + 1) = RSTK(IB(4) + 1)
     1                + TX * (RSTK(IB(3) + 1) - RSTK(IB(4) + 1))
                    RSTK(IENPT + 2) = RSTK(IB(4) + 2)
     1                + TX * (RSTK(IB(3) + 2) - RSTK(IB(4) + 2))
                    TX = D(3) / D(4)
                    RSTK(IENPT + 3) = TX * AMU
C * STORE FOR SOP EDGES GENERATING AND CONTAINING IT
                    ISTK(IENPT + 4) = K
                    ISTK(IENPT + 5) = K5
                    ISTK(IENPT + 6) = 0
                    ISTK(IENPT + 7) = 0
C * CLEAR
                    ISTK(IENPT + 8) = 0
                    ISTK(IENPT + 9) = IL
C * SHADED FROM OTHER DIR
                    IF (ISTK(K5 + IQ + 3) == -1) THEN
                      JNK = IENPT
                      CALL PLA195 (TX)
                      RSTK(IENPT + 3) = RSTK(IENPT + 3) + TX * AMU
C * STORE FACE SHADING IT
                      ISTK(IENPT + 7) = NC
                    END IF
                  END IF
                END IF
              END IF
            END DO
          END IF
        END DO
        JT(IP) = IENPT
        IL     = IL + 1
      END DO
C * THIS IS BLOCK E POINTS S00
      DO 100 I = 1, IENPL, 6
C * FOR ALL FACES SHADED IN BOTH DIRS
        IF (ISTK(I + 4) + ISTK(I + 5) == -2) THEN
          IP  = 1
          IPC = 0
C * TESTS ALL EDGES WITH 1ST DIR AND FOR EVERY HIT EACH EDGE IN OTHER
          K      = ISTED
   30     IE(IP) = 2
          JPC    = 0
          IF(ISTK(K + IP + 3) /= 1) GO TO 70
C * EDGE LIT
          J = JI(IP)
   40     IF (J <= JT(IP)) THEN
            IF (ISTK(J + 4) == K) THEN
C * SOP IS GENERATED BY EDGE
              IT = ISTK(J + 5)
C * IS IT IN THE RIGHT FACE
              IF (I /= ISTK(IT)) THEN
                IF (I /= ISTK(IT + 1)) GO TO 50
              END IF
              IF (JPC <= 0) THEN
C * FIRST POINT
                JPC         = 1
                ND          = J
                IB(IPC + 1) = J
                GO TO 50
              END IF
C * SECOND POINT, BUT IS IT DIFFERENT
              NF          = J
              IB(IPC + 2) = J
C * NEGLIGIBLE DIFFERENCE IN TWO COORDINATES, COMPARES POINTS AT ND AND NF
C * NC = 0 IF IDENTICAL, 1 OTHERWISE
              NC = 1
              IF (ABS(RSTK(ND) - RSTK(NF)) <= 0.3D-4) THEN
                IF (ABS(RSTK(ND + 1) - RSTK(NF + 1)) <= 0.3D-4) THEN
                  IF (ABS(RSTK(ND + 2) - RSTK(NF + 2)) <= 0.3D-4)
     1               NC = 0
                END IF
              END IF
              IF (NC > 0) GO TO 80
            END IF
   50       J = J + 10
            GO TO 40
          END IF
C * TEST VERTICES OF EDGE
          DO M = 2, 3
            J   = ISTK(K + M)
            IND = ISTK(J + 4)
            IT  = ISTK(J + 5)
            DO IT2 = IND, IT
C * IS VERTEX IN FACE
              IF (ISTK(IT2) == I) THEN
                IF (JPC <= 0) THEN
                  JPC         = 1
                  ND          = J
                  IB(IPC + 1) = J
                  GO TO 60
                END IF
                NF          = J
                IB(IPC + 2) = J
C * NEGLIGIBLE DIFFERENCE IN TWO COORDINATES, COMPARES POINTS AT ND AND NF
                IF (ABS (RSTK(ND) - RSTK(NF)) <= 0.3D-4) THEN
                  IF (ABS (RSTK(ND + 1) - RSTK(NF + 1)) <= 0.3D-4)
     1               THEN
                    IF (ABS (RSTK(ND + 2) - RSTK(NF + 2)) <= 0.3D-4)
     1                GO TO 60
                  END IF
                END IF
                GO TO 80
              END IF
            END DO
   60       IT = ISTK(J + IP + 5)
            IF (IT > 0) THEN
C * IS SPO OF VERTEX IN FACE
              IF (ISTK(IT + 4) == I) THEN
                IF (JPC > 0) THEN
                  NF          = IT
                  IB(IPC + 2) = IT
C * NEGLIGIBLE DIFFERENCE IN TWO COORDINATES, COMPARES POINTS AT ND AND NF
C * NC = 0 IF IDENTICAL, 1 OTHERWISE
                  NC = 1
                  IF (ABS (RSTK(ND) - RSTK(NF)) <= 0.3D-4) THEN
                    IF (ABS (RSTK(ND + 1) - RSTK(NF + 1)) <= 0.3D-4)
     1                THEN
                      IF (ABS (RSTK(ND + 2) - RSTK(NF + 2)) <= 0.3D-4)
     1                   NC = 0
                    END IF
                  END IF
                  IF (NC > 0) GO TO 80
                ELSE
                  JPC         = 1
                  ND          = IT
                  IB(IPC + 1) = IT
                END IF
              END IF
            END IF
          END DO
C * THIS IS LABEL S1
          IF (JPC > 0) THEN
            IE(IP) = 1
C * HAVE FOUND ONE POINT
            GO TO 80
          END IF
   70     K = K + 6
          IF (K <= IENED) GO TO 30
          IF (IP /= 2) GO TO 100
          IP  = 1
          IPC = 0
          K   = JSK
          GO TO 70
   80     IF (IP <= 1) THEN
            JSK = K
            K   = ISTED
            IP  = 2
            IPC = 2
            GO TO 30
          END IF
C * FINAL PART OF BLOCK E TO CALC COORDS OF POINTS
C * THIS IS LABEL T
          IF (K == JSK) GO TO 70
          IF (IE(1) == 2) THEN
            IF (IE(2) == 2) THEN
              CALL PLA196
              D(10) = D(1) * D(1) + D(4) * D(4) + D(7) * D(7)
              D(11) = D(1) * D(2) + D(4) * D(5) + D(7) * D(8)
              D(12) = D(1) * D(3) + D(4) * D(6) + D(7) * D(9)
              D(1)  = D(10)
              D(10) = D(2) * D(3) + D(5) * D(6) + D(8) * D(9)
              FRP   = D(2) * D(2) + D(5) * D(5) + D(8) * D(8)
              D(2)  = D(11)
              D(3)  = D(11)
              D(4)  = FRP
              D(5)  = D(12)
              D(6)  = D(10)
              CALL GEN157 (D, 2)
C * RETURNS WITH D(1 TO 3) = 3 DETERMINANTS
              NC = 1
              IF (ABS (D(3)) > 1.D-9) THEN
                DEN = D(1) / D(3)
                IF (DEN >= - 0.1D-4) THEN
                  IF (1.00001D0 >= DEN) NC = 0
                END IF
              END IF
              IF (NC /= 0) GO TO 70
              NC = 1
              IF (ABS (D(3)) > 1.D-9) THEN
                DEN = D(2) / D(3)
                IF (DEN >= - 0.1D-4) THEN
                  IF (1.00001D0 >= DEN) NC = 0
                END IF
              END IF
              IF (NC /= 0) GO TO 70
              IENPT = IENPT + 10
              RSTK(IENPT)     = RSTK(IB(4))     + DEN * (RSTK(IB(3))
     1                        - RSTK(IB(4)))
              RSTK(IENPT + 1) = RSTK(IB(4) + 1) + DEN * (RSTK(IB(3) + 1)
     1                        - RSTK(IB(4) + 1))
              RSTK(IENPT + 2) = RSTK(IB(4) + 2) + DEN * (RSTK(IB(3) + 2)
     1                        - RSTK(IB(4) + 2))
              GO TO 90
            END IF
          END IF
C * MUST HAVE FOUND AT LEAST ONE POINT IN EACH DIR, TO BE HERE
          JNK = IE(1)
          DO JA = 1, JNK
            ND = IB(JA)
            JNK1 = IE(2)
            DO JB = 1, JNK1
              NF = IB(2 + JB)
              IF (ABS (RSTK(ND) - RSTK(NF)) <= 0.3D-4) THEN
                IF (ABS (RSTK(ND + 1) - RSTK(NF + 1)) <= 0.3D-4) THEN
                  IF (ABS (RSTK(ND + 2) - RSTK(NF + 2)) <= 0.3D-4)
     1              THEN
                    IENPT           = IENPT + 10
                    RSTK(IENPT)     = RSTK(ND)
                    RSTK(IENPT + 1) = RSTK(ND + 1)
                    RSTK(IENPT + 2) = RSTK(ND + 2)
                    GO TO 90
                  END IF
                END IF
              END IF
            END DO
          End DO
          GO TO 70
   90     ND   = 1
          JNK  = IENPT
          JNK1 = 1
          CALL PLA195 (DEN)
          JNK1 = 2
          CALL PLA195 (TX)
          RSTK(IENPT + 3) = (DEN + TX) * AMU
          ISTK(IENPT + 4) = JSK
          ISTK(IENPT + 5) = K
          ISTK(IENPT + 6) = 0
          ISTK(IENPT + 7) = 0
          ISTK(IENPT + 8) = 0
          ISTK(IENPT + 9) = IL
          GO TO 70
        END IF
  100 CONTINUE
C * THIS IS BLOCK F  TO SELECT THE CORNERS OF POLYHEDRA FOR EACH
C * PAIR OF FACES BOTH LIT
C * IT CONTINUES IN BLOCK G
C * A VERTEX S IS A VERTEC OF THE HOWELLS POLYHEDRON BASED ON A PAIR OF
C * FACES F1 AND F2 IF IT IS IN F1 OR SHADED BY F1 AND IS AT THE SAME TIM
C * IN F2 OR SHADED BY F2.  IF S IS IN F1, ITS ASSOCIATED S10 IS A VERTEX
C * OF THE HOWELLS POLYHEDRON IF IT IS IN F2 OR SHADED BY F2 AND E ERY A
C * ASSOCIATED POINT S12 IS A VERTEX OF THE HOWELLS POLYHEDRON IF IT IS
C * GENERATED BY AN EDGE CONTAINED IN F2.  AND SIMILARLY FOR S20 AND S21.
C * A POINT S01 IS A VERTEX OF THE HOWELLS POLYHEDRON IF IT IS GENERATED
C * BY AN EDGE CONTAINED IN F1 AND IS IN F2 OR IS SHADED BY F2. AND SIMIL
C * ARLY FOR S02.  FINALLY A POINTF S00 IS A VERTEX OF THE HOWELLS
C * POLYHEDRON IF ONE OF THE EDGES CONTAINING IT IS CONTAINED IN F1
C * AND THE OTHER IN F2.
C * THESE DECISIONS ARE PURELY LOGICAL
      I     = 1
      ISTNP = IENPT + 10
  110 IF (ISTK(I + 4) /= 1) GO TO 330
      J     = 1
  120 IB(2) = J
      IB(1) = I
      IF (ISTK(J + 5) /= 1) GO TO 320
      IENNP = ISTNP - 1
      DO J5 = ISTVT, IENVT, 10
        IP = 1
  130   IQ = 3 - IP
        IF (ISTK(J5 + IP + 7) /= IB(IP)) THEN
          JA = ISTK(J5 + 4)
          JB = ISTK(J5 + 5)
          DO J2 = JA, JB
            IF (ISTK(J2) == IB(IP)) GO TO 140
          END DO
          IE(IP) = 1
          GO TO 170
  140     IND = ISTK(J5 + IP + 5)
          IF (IND /= 0) THEN
            IF (ISTK(IND + 5) /= IB(IQ)) THEN
              IF (ISTK(IND + 4) /= IB(IQ)) GO TO 150
            END IF
C * STORING AN SPO
            IENNP = IENNP + 1
            ISTK(IENNP) = IND
  150       JA = ISTK(IND + 6) + 2
  160       IND = IND + 10
            IF (IND <= IENPT) THEN
              IF (ISTK(IND + 6) == JA) THEN
                JB = ISTK(IND + 4)
                IF (ISTK(JB) /= IB(IQ)) THEN
                  IF (ISTK(JB + 1) /= IB(IQ)) GO TO 160
                END IF
C * STORE A POINT SPQ
                IENNP = IENNP + 1
                ISTK(IENNP) = IND
                GO TO 160
              END IF
            END IF
          END IF
        END IF
        IE(IP) = 0
  170   IP     = IP + 1
        IF (IP == 2) GO TO 130
        IF (IE(1) == 0 .AND. IE(2) == 0) THEN
          IENNP       = IENNP + 1
          ISTK(IENNP) = J5
        END IF
      END DO
C * THIS IS BLOCK G TO FIND POINTS SOP SOO CONTRIBUTING
      DO IP = 1, 2
        IQ = 3 - IP
        J6 = JT(IP)
        J5 = JI(IP)
  180   IF (J5 <= J6) THEN
          IND = ISTK(J5 + 4)
          IF (ISTK(IND) /= IB(IP)) THEN
            IF (ISTK(IND + 1) /= IB(IP)) GO TO 190
          END IF
          IF (ISTK(J5 + 7) /= IB(IQ)) THEN
            IND = ISTK(J5 + 5)
            IF (ISTK(IND) /= IB(IQ)) THEN
              IF (ISTK(IND + 1) /= IB(IQ)) GO TO 190
            END IF
          END IF
          IENNP       = IENNP + 1
          ISTK(IENNP) = J5
  190     J5          = J5 + 10
          GO TO 180
        END IF
      END DO
C * NOW WE DO SOO
      J5 = JT(2) + 10
  200 IF (J5 <= IENPT) THEN
        IND = ISTK(J5 + 4)
        IF (ISTK(IND) /= I) THEN
          IF (ISTK(IND + 1) /= I) GO TO 210
        END IF
        IND = ISTK(J5 + 5)
        IF (ISTK(IND) /= J) THEN
          IF (ISTK(IND + 1) /= J) GO TO 210
        END IF
        IENNP       = IENNP + 1
        ISTK(IENNP) = J5
  210   J5          = J5 + 10
        GO TO 200
      END IF
      IF (IENNP - ISTNP <= 2) GO TO 320
C * HERE IS AN ADDITION.  I SEARCH FOR COINCIDENCES IN THE LIST.  THESE
C * OFTEN OCCUR BECAUSE MANY POINTS HAVE MULTIPLE FUNCTIONS.  THEIR
C * ELIMINATION HERE SAVES TIME IN THE NEXT SECTION.
C * JUMP HERE FOR ORIGINAL VOLUME CALC.
  220 J3 = IENNP
  230 J4 = J3 - 1
  240 ND = ISTK(J3)
      NF = ISTK(J4)
C * NEGLIGIBLE DIFFERENCE IN TWO COORDINATES, COMPARES POINTS AT ND AND NF
C * NC = 0 IF IDENTICAL, 1 OTHERWISE
      NC = 1
      IF (ABS (RSTK(ND) - RSTK(NF)) <= 0.3D-4) THEN
        IF (ABS (RSTK(ND + 1) - RSTK(NF + 1)) <= 0.3D-4) THEN
          IF (ABS (RSTK(ND + 2) - RSTK(NF + 2)) <= 0.3D-4) NC = 0
        END IF
      END IF
      IF (NC <= 0) THEN
        J7 = J4
  250   J8 = J7 + 1
        ISTK(J7) = ISTK(J8)
        J7 = J8
        IF (J8 < IENNP) GO TO 250
        J3 = J3 - 1
        IENNP = IENNP - 1
      END IF
      J4 = J4 - 1
      IF (J4 >= ISTNP) GO TO 240
      J3 = J3 - 1
      IF (J3 > ISTNP) GO TO 230
      IF (IENNP - ISTNP <= 2) GO TO 320
C * THIS IS SUBROUTINE VOL, INCORPORATED IN TRANS
      ISTTR = IENNP + 1
      NPER  = ISTNP + 2
C * TAKE FOUR POINTS AND FIND THEIR VOLUME
  260 IENTR = ISTTR - 6
      ND = ISTNP
      NF = ISTNP + 1
      NG = ISTNP + 2
C * TO CALCULATE AND STORE MINORS AND IDENTIFIERS OF FACES
C * THREE COORDINATE POINTERS ARE ND,NF,NG, TO LIST IN ISTNP TO IENNP
      IB(1) = ISTK(ND)
      IB(2) = ISTK(NF)
      IB(3) = ISTK(NF)
      IB(4) = ISTK(NG)
      CALL PLA196
      IENTR           =  IENTR + 6
C * CALL EXIT/STOP
      IF (IENTR + 6 >= NTMP) CALL GEN127 ('INCREASE NTMP')
      ISTK(IENTR + 3) =  ND
      ISTK(IENTR + 4) =  NF
      ISTK(IENTR + 5) =  NG
      RSTK(IENTR    ) =  D(4) * D(9) - D(7) * D(6)
      RSTK(IENTR + 1) = -D(1) * D(9) + D(3) * D(7)
      RSTK(IENTR + 2) =  D(1) * D(6) - D(3) * D(4)
C * CALC VOLUME FROM MINORS AT IENTR + COORDS AT ISTNP+3
      ND = ISTK(ISTNP + 3)
      NF = ISTK(IENTR + 3)
      NF = ISTK(NF)
C * LOCATION OF FIRST COORDINATE OF FACE
      DEN = (RSTK(NF) - RSTK(ND)) * RSTK(IENTR) + (RSTK(NF + 1)
     1    - RSTK(ND + 1)) * RSTK(IENTR + 1) + (RSTK(NF + 2)
     2    - RSTK(ND + 2)) * RSTK(IENTR + 2)
C * BETWEEN THESE LIMITS THE POINTS ARE APPARENTLY COPLANAR
C * WITH A +VE VOLUME WE SIMPLY EXCHANGE TWO POINTS.  N.B. THIS IS DONE
C * USING THE VALUES WHERE THEY ARE KNOWN TO HAVE BEEN STORED.  CARE
      IF (DEN > 1.0D-5) THEN
        ISTK(ISTNP)     = ISTK(ISTNP + 1)
        ISTK(ISTNP + 1) = IB(1)
        GO TO 260
      END IF
      IF (DEN > - 1.0D-5) THEN
        NPER = NPER + 1
C * PERMUTE VERTICES UNTIL FIND A NON-ZERO SET
        IF (NPER > IENNP) GO TO 310
        IQ = ISTNP + 1
        DO IP = IQ, IENNP
          ISTK(IP - 1) = ISTK(IP)
        END DO
        ISTK(IENNP) = IB(1)
        GO TO 260
      END IF
      VT  = VT - DEN
      DEN = - DEN
C * A NEGATIVE VOLUME AS NEEDED
C * JUMP OVER WITH INITIAL VOL CALC
      IF (ISK == 2) THEN
        DEV(1) = DEN
        JNK    = IENTR
        NC     = ISTNP+3
        CALL PLA197
        TT  = TT  + DEV(1)
        DE2 = DE2 + DEV(2)
      END IF
C * SPECIFIC CALLS TO STORE FIRST MINORS IF MORE POINTS
      IF (IENNP - ISTNP > 3) THEN
        ND = ISTNP + 1
        NF = ISTNP
        NG = ISTNP + 3
C * TO CALCULATE AND STORE MINORS AND IDENTIFIERS OF FACES
C * THREE COORDINATE POINTERS ARE ND,NF,NG, TO LIST IN ISTNP TO IENNP
        IB(1) = ISTK(ND)
        IB(2) = ISTK(NF)
        IB(3) = ISTK(NF)
        IB(4) = ISTK(NG)
        CALL PLA196
        IENTR           =  IENTR + 6
        IF (IENTR + 6 >= NTMP) GO TO 350
        ISTK(IENTR + 3) =  ND
        ISTK(IENTR + 4) =  NF
        ISTK(IENTR + 5) =  NG
        RSTK(IENTR    ) =  D(4) * D(9) - D(7) * D(6)
        RSTK(IENTR + 1) = -D(1) * D(9) + D(3) * D(7)
        RSTK(IENTR + 2) =  D(1) * D(6) - D(3) * D(4)
        NF = ND
        ND = ISTNP + 2
C * TO CALCULATE AND STORE MINORS AND IDENTIFIERS OF FACES
C * THREE COORDINATE POINTERS ARE ND,NF,NG, TO LIST IN ISTNP TO IENNP
        IB(1) = ISTK(ND)
        IB(2) = ISTK(NF)
        IB(3) = ISTK(NF)
        IB(4) = ISTK(NG)
        CALL PLA196
        IENTR           =  IENTR + 6
        IF (IENTR + 6 >= NTMP) GO TO 350
        ISTK(IENTR + 3) =  ND
        ISTK(IENTR + 4) =  NF
        ISTK(IENTR + 5) =  NG
        RSTK(IENTR    ) =  D(4) * D(9) - D(7) * D(6)
        RSTK(IENTR + 1) = -D(1) * D(9) + D(3) * D(7)
        RSTK(IENTR + 2) =  D(1) * D(6) - D(3) * D(4)
        NF = ND
        ND = ISTNP
C * TO CALCULATE AND STORE MINORS AND IDENTIFIERS OF FACES
C * THREE COORDINATE POINTERS ARE ND,NF,NG, TO LIST IN ISTNP TO IENNP
        IB(1) = ISTK(ND)
        IB(2) = ISTK(NF)
        IB(3) = ISTK(NF)
        IB(4) = ISTK(NG)
        CALL PLA196
        IENTR           =  IENTR + 6
        IF (IENTR + 6 >= NTMP) GO TO 350
        ISTK(IENTR + 3) =  ND
        ISTK(IENTR + 4) =  NF
        ISTK(IENTR + 5) =  NG
        RSTK(IENTR    ) =  D(4) * D(9) - D(7) * D(6)
        RSTK(IENTR + 1) = -D(1) * D(9) + D(3) * D(7)
        RSTK(IENTR + 2) =  D(1) * D(6) - D(3) * D(4)
C * NOW WE GRADUALLY INCLUDE ALL FURTHER VERTICES, ADDING TETRAHEDRON
C * AFTER TETRAHEDRON.
        L = ISTNP + 3
  270   L = L + 1
        IF (IENNP >= L) THEN
          NC = L
          M  = IENTR
C * THIS MUST BE SAVED AS IT IS CHANGED DURING THE LOOP
          IP = ISTTR
  280     IF (ISTK(IP + 5) > 0) THEN
C * ELIMINATE IF DELETED
            ND  = ISTK(L)
            NF  = ISTK(IP + 3)
            NF  = ISTK(NF)
            DEN = (RSTK(NF)     - RSTK(ND))     * RSTK(IP)
     1          + (RSTK(NF + 1) - RSTK(ND + 1)) * RSTK(IP + 1)
     2          + (RSTK(NF + 2) - RSTK(ND + 2)) * RSTK(IP + 2)
            IF (DEN > 1.D-9) THEN
C * THIS IS CRUCIAL
C * THE OMISSION OF EVEN A SMALL VOLUME MAY LEAD TO RAPIDLY ACCUMULATING
C * ERRORS IF IT HAS ONE OR MORE LARGEISH FACES AS TETRAHEDRA BASED ON THE
C * THESE WILL BE INCLUDED OR EXCLUDED WRONGLY.  E-5 WAS FOUND TO BE MUCH
C * TOO BIG.
C * IF THE DISTANCE OF CONFUSION AS TESTED IN CC  IS 3.E-5, AS HERE
C * A GOOD VALUE CAN BE SELECTED BY LOOKING AT A LIST OF POINTS.
C * THE WORST POSSIBLE REAL TETRAHEDRON WOULD HAVE A VOLUME OF APP. E-15.
C * BUT 4 REALLY COPLANAR POINTS COULD GIVE AN APPARENT VOLUME OF ABOUT
C * THIS, SO BY MAKING THE TEST VOLUME A BIT LARGER I HOPE TO INCLUDE ALL
C * REAL BUT EXCLUDE ALL FALSE TETRAHEDRA
              VT = VT + DEN
C * SKIPPED IN INITIAL VOL CALC
              IF (ISK2 == 2) THEN
                DEV(1) = DEN
                IF (DEN > FLIM) THEN
C * CHECK IF WORTHWHILE
                  JNK = IP
                  CALL PLA197
                  DE2 = DE2 + DEV(2)
                  TT  = TT  + DEV(1)
                END IF
              END IF
              JNK1 = ISTK(IP + 5)
              JNK3 = ISTK(IP + 3)
C * DELETE OLD MINOR
              ISTK(IP + 5) = 0
C * INSERT NEW MINORS
              ND    = ISTK(IP + 4)
              NF    = JNK1
              NG    = L
              LRETX = -1
C * TEST IF ALREADY EXISTS, IF SO, DONT DELETE AND COMPACT,
C * JUST SET MARKER TO ZERO
C * THIS MAY USE SIGNIFICANT STORAGE, BUT BUT SHOULD SAVE A LOT OF TIME
  290         DO I0 = ISTTR, IENTR, 6
C * WITH THIS MARKER ALREADY ZERO, THIS TESXT ALWAYS FAILS
                IF (NG == ISTK(I0 + 5)) THEN
                  IF (ND == ISTK(I0 + 4)) THEN
                    IF (NF == ISTK(I0 + 3)) THEN
                      ISTK(I0 + 5) = 0
                      GO TO 300
                    END IF
                  END IF
                END IF
              END DO
C * TO CALCULATE AND STORE MINORS AND IDENTIFIERS OF FACES
C * THREE COORDINATE POINTERS ARE ND,NF,NG, TO LIST IN ISTNP TO IENNP
              IB(1) = ISTK(ND)
              IB(2) = ISTK(NF)
              IB(3) = ISTK(NF)
              IB(4) = ISTK(NG)
              CALL PLA196
              IENTR           =  IENTR + 6
              IF (IENTR + 6 >= NTMP) GO TO 350
              ISTK(IENTR + 3) =  ND
              ISTK(IENTR + 4) =  NF
              ISTK(IENTR + 5) =  NG
              RSTK(IENTR    ) =  D(4) * D(9) - D(7) * D(6)
              RSTK(IENTR + 1) = -D(1) * D(9) + D(3) * D(7)
              RSTK(IENTR + 2) =  D(1) * D(6) - D(3) * D(4)
  300         IF (LRETX < 0) THEN
                NF    = ND
                ND    = JNK3
                LRETX = 0
                GO TO 290
              ELSE IF (LRETX == 0) THEN
                NF    = ND
                ND    = JNK1
                LRETX = 1
                GO TO 290
              END IF
            END IF
          END IF
          IP = IP + 6
          IF (IP <= M) GO TO 280
          GO TO 270
        END IF
      END IF
C * RESET ASSIGNMENTS FOR MAIN CALC
  310 IF (IEX == 1) THEN
        IEX  = 2
        ISK  = 2
        ISK2 = 2
        VZ   = 0.001D+0 * VT
        FLIM = VZ  * 0.03D+0
C * VOL AS RETURNED IS 6* TRUE
        GO TO 340
      END IF
  320 J = J + 6
      IF (J <= IENPL) GO TO 120
  330 I = I + 6
      IF (I <= IENPL) GO TO 110
      TT = TT * 6.0D+0 / VT
      DEV(2) = DE2 * 6.0D+0 / VT
C * TRANSMISSION SHOULD NOW BE FOUND
  340 J = IENTR + 6
      IF (J > MAXUTL) MAXUTL = J
      IF (MAXUTL <= NTMP) RETURN
  350 WRITE (LU7, 99999, IOSTAT = IOST) NTMP
      RETURN
99999 FORMAT ('Available Array Size Exceeded. NTMP =', I7)
      END SUBROUTINE PLA194
 
      SUBROUTINE PLA195 (TX)
C * ABSTOMPA (3)
      USE tompa
      IMPLICIT NONE
      INTEGER :: I
      DOUBLE PRECISION :: TX
      DOUBLE PRECISION :: DN
      DOUBLE PRECISION :: ANM
      TX = 2000.0D+0
      NC = 0
      DO I = 1, IENPL, 6
        IF (ND == ISTK(I + JNK1 + 3)) THEN
          ANM = RSTK(I + 3) - RSTK(I) * RSTK(JNK)
     1        - RSTK(I + 1) * RSTK(JNK + 1)
     2        - RSTK(I + 2) * RSTK(JNK + 2)
          DN  = RSTK(I)     * CX(JNK1) + RSTK(I + 1) * CY(JNK1)
     1        + RSTK(I + 2) * CZ(JNK1)
          DN  = ABS (DN)
          ANM = ABS (ANM)
          IF (ANM < TX * DN) THEN
            TX = ANM / DN
            NC = I
          END IF
        END IF
      END DO
C * IF NC IS NON-ZERO, A FACE HAS BEEN FOUND
      RETURN
      END SUBROUTINE PLA195
 
      SUBROUTINE PLA196
C * ABSTOMPA (4)
      USE tompa
      D(1) = RSTK(IB(1))     - RSTK(IB(2))
      D(2) = RSTK(IB(3))     - RSTK(IB(4))
      D(3) = RSTK(IB(1))     - RSTK(IB(4))
      D(4) = RSTK(IB(1) + 1) - RSTK(IB(2) + 1)
      D(5) = RSTK(IB(3) + 1) - RSTK(IB(4) + 1)
      D(6) = RSTK(IB(1) + 1) - RSTK(IB(4) + 1)
      D(7) = RSTK(IB(1) + 2) - RSTK(IB(2) + 2)
      D(8) = RSTK(IB(3) + 2) - RSTK(IB(4) + 2)
      D(9) = RSTK(IB(1) + 2) - RSTK(IB(4) + 2)
      RETURN
      END SUBROUTINE PLA196
 
      SUBROUTINE PLA197
C * ABSTOMPA (5)
      USE tompa
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IAL
      INTEGER :: IBL
      INTEGER :: ICL
      INTEGER :: ISW
      DOUBLE PRECISION :: AF
      DOUBLE PRECISION :: BF
      DOUBLE PRECISION :: HA
      DOUBLE PRECISION :: HAB
      DOUBLE PRECISION :: DEN
      DOUBLE PRECISION :: HPA
      DOUBLE PRECISION :: HABC
      DOUBLE PRECISION :: HP2A
      DOUBLE PRECISION :: HP3A
      DOUBLE PRECISION :: HP4A
      DOUBLE PRECISION :: HPAB
      DOUBLE PRECISION :: HP2AB
      DOUBLE PRECISION :: HP3AB
C * CALCULATES THE CONTRIBUTION FOR AN ELEMENTARY TETRAHEDRON(=A). VOL=V.
C * IF MU*R FOR THE FOUR APICES ARE G1,G2,G3,G4 (ORDERED) AND A=G2-G1,B=
C * G3-G2,C=G4-G3, THEN CONTRIBUTION
C * = 6V*EXP(-G1)*(((H(A)-H(A+B)/B-(H(A+B)-H(A+B+C))/C)/(B+C))
C * WHERE H(A)=(1-EXP(-X))/X.  ALSO H2(A,B)=(H(A)-H(A+B))/B
C * H(3(A,B,C)=(H2(A,B)-H2(A+B,C))/(B+C), = THE INNER EXPRESSION ABOVE.
C *   TOMPA FINDS H(A) BY A CHEBYSHEV SERIES.  THIS IS UNNECCESSARY ON
C * A LARGE COMPUTER AND EXPLICIT EVALUATION IS FASTER.
C * H,H2 AND H3 ALL BECOME INDERERMINATE OF THEIR DENOMINATORS ARE SMALL.
C * THEY MUST THEN BE EVALUATED DIFFERENTLY.  TOMPA ASSUMES THE DENOMINAR
C * OR TO BE EXACTLY ZERO IF IT IS SMALL.  HERE A SERIES EXPANSION IS
C * USED, GIVING THE DENOMINAROT ITS EXACT VALUE.  ALL TERMS IN X**3 ARE
C * IGNORED.  WITH THIS APPROXIMATION A COMPARISON BETWEEN DIRECT CALC.
C * (BY SUBTRACTION AND DIVISION) ABD SERIES EVALUATION TO THIS ACCURACY
C * SHOWS THAT ON ATLAS,WITH ACCURACY OF E-11, THE ERRORS OF BOTH ROUTES
C * ARE EQUAL WHEN D(X)=3.E-3,  AND SO THIS BREAKPOINT IS USED(LABEL22)
C * I   THEN WITH D(2).LT.D, H(D(2)) IS GIVEN BY -LABEL12-
C * II  H(D(2)+D(3)),D(2).GT.D,D(3).LT.D, BY 4TH LINE AFTER -19-
C *      WHERE HPA=1ST DERIVATIVE OF H(D(2)),HP2A,HP3A= 2ND,3RD DERIVATIVES
C * III(A) H2(D(2),D(3)),D(2).GT.D,  BY 3RD LINE AFTER -19-
C * III(B) H2(D(2),D(3)), D(2),D(3).LT.D,  BY LABEL11-
C * FOR H3 -WITH ONE OF D(2),D(3), D(4) SMALL
C * D(2) SMALL - H(D(2)) BY I AND USE TO CALC H2(D(2),D(3))
C * D(3) SMALL - H(D(2) +D(3)) BY II, H2(D(2),D(3)) BY III(A).
C * D(4) SMALL - H2(D(2) +D(3),D(4)) BY III(A)
C * FOR H3 - WITH TWO SMALL
C * D(2) LARGE - TAYLOR EXPANSION. 5TH LINE AFTER -13-
C * D(3) LARGE - H(A) BY I, H2(D(2)+D(3),D(4)) BY III(A)
C * CX LARGE - H(D(2)+D(3)) BY II, H2(D(2),D(3)) BY III(B)
C * FOR H3 WITH ALL SMALL - USE SERIES EXPANSION -LABEL 10-
C * THE NTH DERIV. OF H(X) =D*(H(X)-(1+D*N*F)/X), WHERE
C * D= (-1)**N,  F= (N-1)TH DERIVATIVE.
C * AT LABEL 20 A SWITCH IS USED.  IF D(2),D(3),D(4) ARE LARGE/SMALL,
C * IAL,IBL,ICL ARE 5/1, 2/0, 1/0
C * THEN  D(2)  D(3)  D(4)  SUM  LABEL
C *        S   S   S    1     10
C *        S   S   L    2     11
C *        S   L   S    3     12
C *        L   S   S    5     13
C *        S   L   L    4     12
C *        L   S   L    6     15
C *        L   L   S    7     15
C *        L   L   L    8     15
C * LOCATIONS ARE JNK FOR MINORS, NC FOR VERTEX, DEN IS VOLUME
      DEN  = DEV(1)
      D(4) = RSTK(ISTK(NC) + 3)
      D(1) = RSTK(ISTK(ISTK(JNK + 3)) + 3)
      D(2) = RSTK(ISTK(ISTK(JNK + 4)) + 3)
      D(3) = RSTK(ISTK(ISTK(JNK + 5)) + 3)
      DO I = 1, 3
        AF = D(I)
C * THESE ARE NOW ORDERED
        JNK = I + 1
        DO J = JNK, 4
          IF (AF > D(J)) THEN
            BF   = D(J)
            D(J) = AF
            AF   = BF
          END IF
        END DO
        D(I) = AF
      END DO
C * THE DIFFERENCES BETWEEN SUCCESSIVE ONES ARE TAKEN
C * G = D1, A = D2, ETC, THEN A+B, B+C, A+B+C
      D(4) = D(4) - D(3)
      D(3) = D(3) - D(2)
      D(2) = D(2) - D(1)
      D(5) = D(2) + D(3)
      D(6) = D(3) + D(4)
      D(7) = D(6) + D(2)
      IF (D(1) < 15) THEN
C * HERE THE SWITCHING DEPENDING ON SIZE IS SET UP
        IAL = 1
        IBL = 0
        ICL = 0
        IF (D(2) > 3.D-3) IAL = 5
        IF (D(3) > 3.D-3) IBL = 2
        IF (D(4) > 3.D-3) ICL = 1
        ISW = IAL + IBL + ICL
        I   = 1
C * NOW THE CALCULATION IS STARTED (LABEL 20)
        IF (ISW == 1) THEN
          D(10) = 0.166667D+0 - 0.125D+0 * (D(2) + D(3)) + 0.0416667D+0
     1          * (D(3) - D(4)) + 0.0083333D+0 * (D(2)
     2          * (D(2) + D(2) + D(3)) + D(4) * D(4) +(D(2) + D(3)
     3          + D(4)) * (4.0D+0 * D(2) + 3.0D+0 * D(3)))
          GO TO 30
        ELSE IF (ISW == 2) THEN
          D(8) = 0.5D+0 - D(2) * (0.33333D+0 - 0.125D+0 * (D(2) + D(3)))
     1         - D(3) * (0.166667D+0 - 0.0416667D+0 * D(3))
          HAB = 1.0D+0 - D(5) * (0.5D+0 - 0.166667D+0 * D(5))
          GO TO 10
        ELSE IF (ISW == 3 .OR. ISW == 4) THEN
          HA = 1.0D+0 - D(2) * (0.5D+0 - 0.166667D+0 * D(2))
        ELSE IF (ISW == 5) THEN
          HA   =  (1.0D+0 - EXP (- D(2))) / D(2)
          HPA  = -HA + (1.0D+0 - HA) / D(2)
          HP2A =  HA - (1.0D+0 + HPA + HPA) / D(2)
          HP3A = -HA + (1.0D+0 - HP2A - HP2A - HP2A) / D(2)
          HP4A =  HA - (1.0D+0 + 4.0D+0 * HP3A) / D(2)
          D(10)  =  0.5D+0 * HP2A + 0.166667D+0 * HP3A * (D(3) + D(3)
     1           + D(4)) + 0.0416667D+0 * HP4A * (3.0D+0 * D(3) * (D(3)
     2           + D(4)) + D(4) * D(4))
          GO TO 30
        ELSE
          HA = (1.0D+0 - EXP (- D(2))) / D(2)
          IF (IBL <= 0) THEN
            HPA  = -HA  + (1.0D+0 - HA) / D(2)
            HP2A =  HA  - (1.0D+0 + HPA + HPA) / D(2)
            HP3A = -HA  + (1.0D+0 - HP2A - HP2A - HP2A) / D(2)
            D(8) = -HPA - D(3) * (0.5D+0 * HP2A
     1           + 0.166667D+0 * HP3A * D(3))
            HAB  =  HA  + D(3) * (HPA + 0.5D+0 * D(3) * HP2A)
            GO TO 10
          END IF
        END IF
        HAB  = (1.0D+0  - EXP (- D(5))) / D(5)
        D(8) = (HA - HAB) / D(3)
        IF (ICL <= 0) THEN
          HPAB  = -HAB + (1.0D+0 - HAB) / D(5)
          HP2AB =  HAB - (1.0D+0 + HPAB + HPAB) / D(5)
          HP3AB = -HAB + (1.0D+0 - HP2AB - HP2AB - HP2AB) / D(5)
          D(9)  = -HPAB - D(4) * (0.5D+0 * HP2AB
     1          + 0.166667D+0 * D(4) * HP3AB)
          GO TO 20
        END IF
  10    HABC   = (1.0D+0 - EXP (- D(7))) / D(7)
        D(9)   = (HAB - HABC) / D(4)
  20    D(10)  = (D(8) - D(9)) / D(6)
  30    DEV(I) = DEN * D(10) * EXP (-D(1))
      ELSE
        DEV(1) = 0
        DEV(2) = 0
      END IF
      RETURN
      END SUBROUTINE PLA197
 
      SUBROUTINE PLA198 (MODE, INEXT, NOCLS, NREPL)
C * GUI - Absorption Correction
      USE parameters
      USE atomdata
      USE cchar
      USE crystal
      USE abspsi
      IMPLICIT NONE
      INTEGER       :: IOST
      INTEGER       :: MODE
      INTEGER       :: INEXT
      INTEGER       :: NOCLS
      INTEGER       :: NREPL
      INTEGER, SAVE :: IPR371
      INTEGER, SAVE :: IPR372
      REAL :: HORS
      REAL :: VERT
      IPR371 = 0
      IPR372 = 0
      VERT   = 25.0
      HORS   = PAR(50) * VERT
      IF (NREPL == 0) THEN
        IF (NOCLS == 0) CALL GGIP (HORS, VERT, 0.0, 1)
      ELSE
        GO TO 10
      END IF
      CALL GGIP (0.0, 1.0, 0.0, 0)
      CALL PLA110 (HORS, VERT, -1)
C * HEADER
      IF (MODE == -1) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'Spherical Absorption Correction '
      ELSE IF (MODE == 0) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'Xtal Habit Display+Manipulation '
      ELSE IF (MODE == 1) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'Analytical Correction of PsiScan'
      ELSE IF (MODE == 2) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'Gaussian Integration Correction '
      ELSE IF (MODE == 3) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'de Meulenaer- Tompa  Correction '
      ELSE IF (MODE == 4) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'Psi-Scan  Absorption Correction '
      ELSE IF (MODE == 6) THEN
        WRITE (PRBUF, 99999, IOSTAT = IOST)
     1    'MULtiscan ABSorption Correction '
      END IF
      CALL PLA439 (0.0, PRBUF, 32, 0.75, 5 + IGBL(68), 2, 3.0,
     1             VERT - 1.0)
C * REPORT MUR
      IF (MODE == -1 .OR. MODE == 4) THEN
        WRITE (PRBUF, 99998, IOSTAT = IOST) PAR(321)
        IF (PAR(321) == 0.0) THEN
          CALL GGIP (0.0, 2.0, 0.0, 0)
          IF (MODE == -1) THEN
            CALL PLA439 (0.0, 'Enter MuR         Datum <<', 26, 0.50,
     1                  -1, 2, 21.0, 2.0)
          ELSE IF (MODE == 4 .AND. NPSI == 0) THEN
            CALL PLA439 (0.0,
     1           'Optionally Enter MuR for Additional Theta Correction',
     2             52, 0.50, -1, 2, 10.0, 4.0)
          END IF
        ELSE
          CALL GGIP (0.0, 3.0, 0.0, 0)
        END IF
        CALL PLA439 (0.0, PRBUF, 14, 0.5, -1, 2, VERT + 0.1, VERT - 1.0)
        IF (MODE == 4 .AND. NPSI > 0) THEN
          WRITE (PRBUF, 99997, IOSTAT = IOST)
     1      'Nr. Psi Scans =', NPSI
          CALL PLA439 (0.0, PRBUF, 18, 0.5, 1, 2,
     1                 VERT + 0.1, VERT - 3.0)
        END IF
C * REPORT MU
      ELSE IF (MODE /= 0 .AND. MODE /= 4 .AND. MODE /= 7) THEN
        WRITE (PRBUF, 99996, IOSTAT = IOST) PAR(301)
        IF (PAR(301) == 0.0) THEN
          CALL GGIP (0.0, 2.0, 0.0, 0)
          CALL PLA439 (0.0, 'Enter Mu (mm)     Datum <<', 26, 0.50,
     1                 -1, 2, 21.0, 2.0)
        ELSE
          CALL GGIP (0.0, 3.0, 0.0, 0)
        END IF
        CALL PLA439 (0.0, PRBUF, 19, 0.5, -1, 2, VERT + 0.1, VERT - 1.0)
      END IF
C * REPORT GAUSS GRID
      IF (MODE == 2) THEN
        WRITE (PRBUF, 99995, IOSTAT = IOST) IPR(421), IPR(422), IPR(423)
        CALL PLA439 (0.0, PRBUF, 19, 0.5, 1, 2, VERT + 0.1, VERT - 2.0)
      END IF
C * MULABS MODE
      IF (MODE == 6) THEN
C * REPORT RADIUS
        WRITE (PRBUF, 99994, IOSTAT = IOST) PAR(305)
        IF (PAR(305) == 0.0) THEN
          CALL GGIP (0.0, 2.0, 0.0, 0)
          CALL PLA439 (0.0, 'Enter Radius (mm) Datum', 23, 0.75, -1, 2,
     1                 17.0, 1.0)
        ELSE
          CALL GGIP (0.0, 3.0, 0.0, 0)
        END IF
        CALL PLA439 (0.0, PRBUF, 18, 0.5, -1, 2, VERT + 0.1,
     1       VERT - 2.0)
        WRITE (PRBUF, 99993, IOSTAT = IOST) PAR(304)
        CALL PLA439 (0.0, PRBUF, 17, 0.5, 1, 2, VERT + 0.1,
     1       VERT - 3.0)
        WRITE (PRBUF, 99992, IOSTAT = IOST) PAR(306)
        CALL PLA439 (0.0, PRBUF, 17, 0.5, 1, 2, VERT + 0.1,
     1       VERT - 4.0)
        WRITE (PRBUF, 99991, IOSTAT = IOST) IPR(373)
        CALL PLA439 (0.0, PRBUF, 14, 0.5, 1, 2, VERT + 0.1,
     1       VERT - 5.0)
        WRITE (PRBUF, 99990, IOSTAT = IOST) IPR(374)
        CALL PLA439 (0.0, PRBUF, 14, 0.5, 1, 2, VERT + 0.1,
     1       VERT - 6.0)
        WRITE (PRBUF, 99989, IOSTAT = IOST) PAR(321)
        CALL PLA439 (0.0, PRBUF, 17, 0.5, 1, 2, VERT + 0.1,
     1       VERT - 7.0)
      END IF
      IF (MODE == 2 .OR. MODE == 3 .OR. MODE == 4
     1      .OR. MODE == 6 .OR. MODE == -1 .OR. MODE == 0) THEN
        IF (MODE == 2 .OR. MODE == 3 .OR. MODE == 0)
     1      PAR(305) = 0.0001
        IF (PAR(301) * PAR(305) > 0.0 .OR. MODE == 4
     1      .OR. (MODE == -1 .AND. PAR(321) > 0.0)) THEN
          CALL GGIP (0.0, 2.0, 0.0, 0)
          IF (PAR(315) == 0.0) THEN
            IF (IPR(375) == 0) THEN
              CALL PLA439 (0.0, 'Click on NEXT-STEP to PROCEED', 29,
     1                 0.60, -1, 2, 18.0, 1.5)
            END IF
          ELSE
            CALL PLA439 (0.0, 'Click on END to Terminate    ', 29,
     1                 0.75, -1, 2, 15.0, 1.0)
          END IF
        END IF
      END IF
      IF (IPR(331) == 1) THEN
        WRITE (IDM, 99988, IOSTAT = IOST) PAR(101)
        CALL PLA439 (0.0, IDM, 16, 0.35, 1, 2, 0.5, VERT - 2.0)
        WRITE (IDM, 99987, IOSTAT = IOST) PAR(102)
        CALL PLA439 (0.0, IDM, 16, 0.35, 1, 2, 0.5, VERT - 2.6)
        WRITE (IDM, 99986, IOSTAT = IOST) PAR(103)
        CALL PLA439 (0.0, IDM, 16, 0.35, 1, 2, 0.5, VERT - 3.2)
        WRITE (IDM, 99985, IOSTAT = IOST) PAR(104)
        CALL PLA439 (0.0, IDM, 16, 0.35, 1, 2, 0.5, VERT - 3.8)
        WRITE (IDM, 99984, IOSTAT = IOST) PAR(105)
        CALL PLA439 (0.0, IDM, 16, 0.35, 1, 2, 0.5, VERT - 4.4)
        WRITE (IDM, 99983, IOSTAT = IOST) PAR(106)
        CALL PLA439 (0.0, IDM, 16, 0.35, 1, 2, 0.5, VERT - 5.0)
        IF (NFACES > 0) THEN
          WRITE (PRBUF, 99982, IOSTAT = IOST) NFACES
          CALL PLA439 (0.0, PRBUF, 13, 0.35, 1, 2, 0.5, VERT - 6.0)
          WRITE (PRBUF, 99981, IOSTAT = IOST) NVRR
          CALL PLA439 (0.0, PRBUF, 13, 0.35, 1, 2, 0.5, VERT - 6.5)
          WRITE (PRBUF, 99980, IOSTAT = IOST) NEDGE
          CALL PLA439 (0.0, PRBUF, 13, 0.35, 1, 2, 0.5, VERT - 7.0)
        END IF
      END IF
C * MULABS
   10 IF (MODE == 6) THEN
        WRITE (PRBUF, 99979, IOSTAT = IOST) IPR371
        CALL PLA439 (0.0, PRBUF, 29, 0.5, 0, 2, 3.0, VERT - 8.0)
        IPR371 = IPR(371)
        WRITE (PRBUF, 99979, IOSTAT = IOST) IPR(371)
        CALL PLA439 (0.0, PRBUF, 29, 0.5, 5, 2, 3.0, VERT - 8.0)
        WRITE (PRBUF, 99978, IOSTAT = IOST) IPR372
        CALL PLA439 (0.0, PRBUF, 29, 0.5, 0, 2, 3.0, VERT - 9.0)
        IPR372 = IPR(372)
        WRITE (PRBUF, 99978, IOSTAT = IOST) IPR(372)
        CALL PLA439 (0.0, PRBUF, 29, 0.5, 5, 2, 3.0, VERT - 9.0)
        IF (NREPL == 0) THEN
          WRITE (PRBUF, 99977, IOSTAT = IOST) SPGRNM(1)(1:11)
          CALL PLA439 (0.0, PRBUF, 21, 0.5, 5, 2, 3.0, VERT - 7.0)
          IF (IPR(375) > 0) THEN
            WRITE (PRBUF, 99976, IOSTAT = IOST) IPR(375)
            CALL PLA439 (0.0, PRBUF, 36, 0.5, 5 + IGBL(68), 2, 3.0,
     1                   VERT - 10.0)
            WRITE (PRBUF, 99975, IOSTAT = IOST) IPR(376)
            CALL PLA439 (0.0, PRBUF, 35, 0.5, 5 + IGBL(68), 2, 3.0,
     1                   VERT - 11.0)
            WRITE (PRBUF, 99974, IOSTAT = IOST) IPR(377)
            CALL PLA439 (0.0, PRBUF, 36, 0.5, 5 + IGBL(68), 2, 3.0,
     1                   VERT - 12.0)
            WRITE (PRBUF, 99973, IOSTAT = IOST) PAR(322)
            CALL PLA439 (0.0, PRBUF, 44, 0.5, 5 + IGBL(68), 2, 3.0,
     1                   VERT - 14.0)
            WRITE (PRBUF, 99972, IOSTAT = IOST) PAR(323)
            CALL PLA439 (0.0, PRBUF, 50, 0.5, 5 + IGBL(68), 2, 3.0,
     1                         VERT - 15.0)
C * ANISOTROPY EXTREMA
            IF (PAR(319) > 0.0) THEN
              WRITE (PRBUF, 99971, IOSTAT = IOST) PAR(319)
              CALL PLA439 (0.0, PRBUF, 16, 0.5, 1, 2, 1.0,
     1                     VERT - 21.0)
              WRITE (PRBUF, 99970, IOSTAT = IOST) PAR(320)
              CALL PLA439 (0.0, PRBUF, 16, 0.5, 1, 2, 1.0,
     1                     VERT - 22.0)
              END IF
          END IF
        END IF
C * FLUSH
        CALL GGIP (0.0, 0.0, 0.0, 6)
      END IF
      IF (MODE /= 0 .AND. PAR(315) /= 0.0) THEN
        IF (MODE /= 6) THEN
          WRITE (PRBUF, 99969, IOSTAT = IOST) IPR(432)
          CALL PLA439 (0.0, PRBUF, 28, 0.5, 5 + IGBL(68), 2, 1.3,
     1                 VERT - 22.0)
        END IF
        WRITE (PRBUF, 99968, IOSTAT = IOST) PAR(315)
        CALL PLA439 (0.0, PRBUF, 16, 0.5, 5 + IGBL(68), 2, 1.3,
     1               VERT - 23.0)
        WRITE (PRBUF, 99967, IOSTAT = IOST) PAR(317)
        CALL PLA439 (0.0, PRBUF, 16, 0.5, 5 + IGBL(68), 2, 1.3,
     1               VERT - 24.0)
      END IF
      IF (INEXT == 0 .AND. MODE /= 4 .AND. MODE /= -1 ) THEN
        CALL PLA187 (1, 9.0, 11, NOCLS)
      END IF
      IF (IOST /= 0) RETURN
      RETURN
