99996 FORMAT ('Mu      ', F6.2, ' mm-1')
99995 FORMAT ('Grid   ', 3I4)
99994 FORMAT ('Radius  ', F6.3, ' mm')
99993 FORMAT ('Tmin   ', F7.3, ' mm')
99992 FORMAT ('Tmax   ', F7.3, ' mm')
99991 FORMAT ('Lomax  ', I7)
99990 FORMAT ('L1max  ', I7)
99989 FORMAT ('MuR    ', F7.3)
99988 FORMAT ('a     = ', F8.4)
99987 FORMAT ('b     = ', F8.4)
99986 FORMAT ('c     = ', F8.4)
99985 FORMAT ('alpha = ', F8.3)
99984 FORMAT ('beta  = ', F8.3)
99983 FORMAT ('gamma = ', F8.3)
99982 FORMAT ('Faces    ', I4)
99981 FORMAT ('Vertices ', I4)
