     1        F5.1, ',', 2X, 'Nref/Npar =', F6.1)
99959 FORMAT ('# w=1/(sigma**2(I)+', F7.4, 'I**2) - (JANA)')
99958 FORMAT ('# Reported   Rho(min) =', F6.2, ', Rho(max) =', F5.2,
     1        ' e/Ang**3 (From CIF)')
99957 FORMAT (A, I8, ' Ang**3, Total El.Count =', I8, ' e-')
99956 FORMAT (A, F6.4, 2A, '+(', F6.4, 'P)**2]', A)
99955 FORMAT (A, F6.4, 2A, '+(', F6.4, 'P)**2+', F8.4,'P]')
99954 FORMAT ('# Number Bijvoet Pairs =', I5, ' (', I3, '%),', 5X,
     1 I5, ' Selected for:  Parsons', A)
99953 FORMAT ('#', 79('='), /, '# For Documentation:',
     1 A, 'CIF-VALIDATION.pdf')
99952 FORMAT ('# ', A, 6X, 'R =', F6.3)
99951 FORMAT ('# SWAT ', F12.2, F12.6)
99950 FORMAT (F5.3)
99949 FORMAT (I5)
      END SUBROUTINE PLA237
 
      SUBROUTINE PLA238 (LU, NP, NMX, N, A)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: M
      INTEGER :: LU
      INTEGER :: NP
      INTEGER :: NMX
      CHARACTER(len=NP), DIMENSION(NMX) :: A
      M = MIN (N, NMX)
      DO I = 1, M, 8
        K = MIN (7, M - I)
        WRITE (LU, 99999) (A(I + J)(1:8), J = 0, K)
      END DO
      IF (N > NMX) WRITE (LU, 99998) N - NMX
      RETURN
99999 FORMAT (14X, 8A)
99998 FORMAT (25X, '***', I5, ' More NOT listed ***')
      END SUBROUTINE PLA238
 
      SUBROUTINE PLA239 (LU, NMX, N, A)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: M
      INTEGER :: LU
      INTEGER :: NMX
      INTEGER, DIMENSION(3, NMX) :: A
      M = MIN (N, NMX)
      DO I = 1, M, 6
        K = MIN (5, M - I)
        WRITE (LU, 99999) ((A(L, I + J), L = 1, 3), J = 0, K)
      END DO
      IF (N > NMX) WRITE (LU, 99998) N - NMX
      RETURN
99999 FORMAT (14X, 6(3I3, ', '))
99998 FORMAT (19X, '(', I5, ' More NOT listed: see .ckf listing file)')
      END SUBROUTINE PLA239
 
