      INTEGER, PARAMETER :: IP6 = 99
      INTEGER, PARAMETER :: IP7 = 25
      INTEGER, PARAMETER :: IP8 = 25
      INTEGER, PARAMETER :: IP9 = 100
      INTEGER :: ISG
