      REAL :: SCFOVFL
      REAL, DIMENSION(12)            :: CELL
      REAL, DIMENSION(3)             :: DVECT
      REAL, DIMENSION(IP1)           :: X
      REAL, DIMENSION(IP1)           :: F
      REAL, DIMENSION(IP1)           :: W
      REAL, DIMENSION(IP5, IP3, IP2) :: A
      REAL, DIMENSION(IP5, IP3, IP2) :: B
      REAL, DIMENSION(IP5, IP3, IP2) :: C
      REAL, DIMENSION(IP5, IP3, IP2) :: D
      REAL, DIMENSION(IP5, IP3, IP2) :: P
