      SUBROUTINE PLA240
C **********************************************************************
C *                                                                    *
C * * * * * * * * P R O G R A M    H E L E N A * * * * * * * * * * * * *
C *                                                                    *
C **********************************************************************
C *                                                                    *
C *      PROGRAM FOR THE HANDLING OF CAD4-DIFFRACTOMETER OUTPUT        *
C *          A SHELX(S/L) STYLE HKL-CARD FILE IS PREPARED              *
C *       ALONG WITH A DOCUMENT ON THE DATA COLLECTION                 *
C *                         A.L. SPEK,                                 *
C *                     UTRECHT UNIVERSITY                             *
C *                                                                    *
C *--------------------------------------------------------------------*
C * INPUT = UNIT5  - NORMAL INPUT FILE                        (CONNEC) *
C * OUTPUT= UNIT6  - INTERACTIVE OUTPUT FILE                  (CONNEC) *
C * .cad  = UNIT16 - CAD4 - PROTOCOLFILE                      (INPUT)  *
C * .hkl  = UNIT17 - H,K,L,I,SIG(I),DIR COS (HKLF 4 / SHELX)  (OUTPUT) *
C * .PSI  = UNIT4  - PSI-SCAN DATA (SHELX     )               (OUTPUT) *
C * .LIS  = UNIT7  - NORMAL OUTPUT LISTING FILE               (OUTPUT) *
C * .PAR  = UNIT8  - PARAMETER FILE                           (OUTPUT) *
C *         UNIT9  - REFERENCE REFLECTIONS                    (SCRATCH)*
C *         UNIT10 - NON-REFERENCE REFLECTIONS                (SCRATCH)*
C *         UNIT11 - PSI-SCANS                                (SCRATCH)*
C *--------------------------------------------------------------------*
C *                  ---  L I M I T S  ---                             *
C *                  =====================                             *
C *  MAX NUMBER OF REFERENCE REFLECTIONS                       = IP3-1 *
C *  MAX NUMBER OF MEASUREMENTS OF A REFERENCE REFLECTION      = IP1   *
C *  MAX NUMBER OF SCALING GROUPS                              = IP2   *
C *  MAX NUMBER OF PSI-SCAN REFLECTIONS                        = IP4   *
C *  MAX DEGREE OF POLYNOMIAL THROUGH REFERENCE REFLECTIONS    = IP5-1 *
C *  MAX NUMBER OF ORIENTATION MATRICES                        = IP6   *
C *--------------------------------------------------------------------*
C **********************************************************************
C **********************************************************************
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE helena
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: IP
      INTEGER :: INS
      INTEGER :: IVAL
      INTEGER :: LUNIT
      INTEGER :: NAUTO
      REAL :: STM
      CHARACTER(len=25) :: FLNAM
      CHARACTER(len=10) :: VERSION
      PAGET = 'HELENA'
      CALL GEN038 (JID, 1, 80)
C * NUMBER OF LINES/PAGE (LINE PRINTER)
      IPR(83)   = 0
      IGBL(1)   = 4
      IPR(370)  = 0
      IGBL(63)  = 3
      IGBL(49)  = 0
      IGBL(102) = 56
      NAUTO     = 0
C * LU16 - INPUT OF CAD4-FILE  (CAD4)
      LUNIT     = LU16
      FLNAM = NAMEFIL(1:KNMFIL)//'.'//EXTENS(1:KXT)
      OPEN (UNIT = LU16, FILE = FLNAM, STATUS = 'UNKNOWN',
     1  IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
C * LU17 - OUTPUT OF HKL-FILE  (FOR SHELX)
C * LU60 - FOR ABSPSI
C * LU4  - OUTPUT PSI-SCAN REFLECTIONS
C * LU11 - INTERMEDIATE SCRATCH FILE FOR PSI-REFLECTIONS
      LUNIT = LU11
      OPEN (UNIT = LU11, STATUS = 'SCRATCH', FORM = 'UNFORMATTED',
     1 IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
C * LU10 - INTERMEDIATE SCRATCH FILE ( NON-STANDARD REFLECTIONS)
      LUNIT = LU10
      OPEN (UNIT = LU10, STATUS = 'SCRATCH', FORM = 'UNFORMATTED',
     1 IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
C * LU9 - INTERMEDIATE SCRATCH FILE OF REFERENCE REFLECTIONS
      LUNIT = LU9
      OPEN (UNIT = LU9, STATUS = 'SCRATCH', FORM = 'UNFORMATTED',
     1 IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
C * LU7 - LIST OUTPUT
      LUNIT = LU7
      OPEN (UNIT = LU7, FILE = NAMEFIL(1:KNMFIL)//'.lis',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
C * LU1 - INPUT FILE FOR INSTRUCTIONS
C * SET HELENA-MENU
      IGBL(6) = 15
      VERT    = 25.0
      HORS    = VERT * 4.0 / 3.0
      LU15    = LU1
      OPEN (UNIT = LU15, FILE = NAMEFIL(1:KNMFIL)//'.ins',
     1      STATUS = 'UNKNOWN')
      CALL GEN108 (LU10, 0)
      CALL GEN108 (LU11, 0)
      CALL GEN108 (LU9, 0)
      CALL GEN040 (IGBL(4), VERSION, IP)
      CALL PLA262 (0)
      WRITE (LU7, 99999, IOSTAT = IOST) VERSION(1:IP)
C * INITIALISE
      CALL GEN097 (IHPR, 1, IP7, 0)
      IHPR(1)  = IP3 - 1
      IHPR(2)  = IP1
      IHPR(3)  = IP2
      IHPR(4)  = IP4
      IHPR(5)  = IP5 - 1
      IPR(446) = 1
      XIMX     = 0
      SIMX     = 0
      SCFOVFL  = 1.0
      IORF     = 0
      PERF     = 0.5
      XNPSIFL  = '******'
      CALL GEN097 (IORREF, 1, 100, 0)
      DO I = 1, 25
        HTAOIS(I) = XNPSIFL
      END DO
      CILT = 2.5
      CALL GEN097 (IPR(371), 1, 9, 1)
      CALL GEN097 (ISW, 1, 3, 0)
      CALL GEN074 (CELL, 1, 12, 0.0)
      CALL GEN097 (NMBR, 1, 20, 0)
      CALL GEN097 (IRFY, 1, IP3, 0)
      CALL GEN074 (XRF , 1, IP3, 0.0)
      DO I = 1, 26
        CALL GEN038 (RDMP(I), 1, 62)
      END DO
      CALL GEN074 (PSIS, 1, IP4 * 36, 0.0)
      ANPI     = 0.0
      HPAR(1)  = 1.0000
      HPAR(2)  = 1.0000
      HPAR(3)  = 0
      HPAR(4)  = 0
C * SET WAIT TIMES FOR SCALING AND PSI-SCAN IN SECONDS
      HPAR(20) = 2
      HPAR(21) = 2
      HPAR(24) = RGBL(6)
      IPR(424) = 1
C * LSR BACKGROUND DEFAULT
      IPR(425) = 0
C * DIRCOS DEFAULT
      IPR(426) = 0
C * SCALE/NO-SCALE
      IPR(428) = 0
      STM      = (SIN (35.0 / HPAR(24)) / 0.71073) ** 3 / IP9
      DO I = 1, IP9
        BAK(I, 1) = (STM * I) ** 0.3333333
        DO J = 2, 5
          BAK(I, J) = 0.0
        END DO
      END DO
      WRITE (LU6, 99998, IOSTAT = IOST) VERSION
      GO TO 20
C * READ INSTRUCTIONS
   10 LU15 = LU5
   20 IF (LU15 == LU5) THEN
        BCD(1:12) = 'H.E.L.E.N.A'//CHAR (0)
        CALL GGIP (HORS, VERT, 0.0, 1)
        LINE = 'H E L E N A'
        CALL PLA439 (0.0, LINE, 11, 2.2, 4, 15, 5.0, VERT - 3.0)
        CALL PLA439 (0.0, LINE, 11, 2.2, 2, 15, 4.7, VERT - 3.2)
C * INSTRUCTIONS
        LINE =
     1   'Version '//VERSION(1:IP)//' - A.L.Spek, Utrecht University'
        CALL PLA439 (0.0, LINE, 50, 0.6, 1, 2, 4.0, VERT - 5.0)
        LINE = 'INSTRUCTIONS + SUB-KEYWORDS (# = DEFAULT)'
        CALL PLA439 (0.0, LINE, 50, 0.6, 5 + IGBL(68), 2, 4.0,
     1               VERT - 7.0)
        LINE = 'CALC            - TO EXECUTE THE CALCULATION'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 8.0)
        LINE = '      - #SHELX  - INPUT FILE FOR SHELX (TYPE=4)'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 9.0)
        LINE = '      -  ABSPSI - ABSOLUTE PSI - VALUES'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 10.0)
        LINE = '      - #LSR    - NORMAL  BACKGROUND PROCEDURE'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 11.0)
        LINE = '      -  MSM    - SPECIAL BACKGROUND PROCEDURE'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 12.0)
        LINE = '      -  MSA    - SPECIAL BKG PROC. (ADD B+ TO ISC)'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 13.0)
        LINE = '      -  SUB    - SKIP REFLECTIONS WITH UNUSUAL BG,BL'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 14.0)
        LINE = '      -  AVE    - AVERAGE BACKGROUND SCALING'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 15.0)
        LINE = 'MONOCHR         - SET MONOCHROMATOR TYPE'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 16.0)
        LINE = '      -  BETA   - BETA-FILTER'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 17.0)
        LINE = '      -  PERP   - MONOCHROMATOR PERPENDICULAR'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 18.0)
        LINE = '      -  PARAL  - MONOCHROTOR PARALLEL'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 19.0)
        LINE = 'SCALE           - SCALING FUNCTION'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 20.0)
        LINE = '      -  DEGREE [ value ]'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 21.0)
        LINE = '      -  NONE    - SCALE = 1.0'
        CALL PLA439 (0.0, LINE, 60, 0.5, 1, 2, 4.0, VERT - 22.0)
        LINE = 'Data Read From: '//FLNAM
        CALL PLA439 (0.0, LINE, 60, 0.5, 3, 2, 4.0, VERT - 24.0)
C * WHAT NEXT ?
        CALL PLA012 (5, 1)
C * REFRESH
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
          GO TO 20
        ELSE IF (IGGT(1:1) == '!') THEN
          CALL PLA280 ('CALC')
        END IF
        IF (IGGT(1:1) /= ' ') THEN
          ICL = IGGT
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          GO TO 20
        END IF
      ELSE
        READ  (LU15, 99989, IOSTAT = IOST) ICL(1:80)
        IF (IOST == -1) GO TO 10
      END IF
      CALL GEN072 (ICL, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
C * SET INSTRUCTION
      IF (IFL(1)(1:3) == 'SET') THEN
C * SET DISPLAY TYPE
        IF (IFL(2)(1:4) == 'DISP') THEN
          MEDIUM = 1
C * SET META-FILE TYPE
        ELSE IF (IFL(2)(1:4) == 'META') THEN
          MEDIUM = 2
        END IF
        IF (KL > 2) THEN
          IGGT(16:22) = IFL(3)(1:7)
          CALL GGIP (-999.0, 0.0, 0.0, 6)
        END IF
        GO TO 20
      END IF
      IF (IFL(1)(1:3) == 'MON') THEN
        IF (KL == 2) THEN
C * SET MONOCHROMATOR SWITCH (BETA/PERP/PAR)
          IF (IFL(2)(1:4) == 'BETA') THEN
            IPR(424) = 0
          ELSE IF (IFL(2)(1:4) == 'PERP') THEN
            IPR(424) = 1
          ELSE IF (IFL(2)(1:3) == 'PAR') THEN
            IPR(424) = 2
          END IF
          GO TO 20
        END IF
      END IF
C * CALC OPTIONS
      IF (IFL(1)(1:4) == 'CALC') THEN
        K = 0
        IF (KL > 1) THEN
          DO I = 2, KL
            IF (IFL(I)(1:6) == 'ABSPSI') THEN
              IPR(426) = 1
            ELSE IF (IFL(I)(1:3) == 'LSR') THEN
              IF (IPR(370) == 0) IPR(425) =  0
            ELSE IF (IFL(I)(1:3) == 'MSM') THEN
              IF (IPR(370) == 0) IPR(425) =  1
            ELSE IF (IFL(I)(1:3) == 'MSA') THEN
              IF (IPR(370) == 0) IPR(425) =  2
            ELSE IF (IFL(I)(1:3) == 'AVE') THEN
              IF (IPR(370) == 0) IPR(425) =  3
            ELSE IF (IFL(I)(1:3) == 'SUB') THEN
              IF (IPR(370) == 0) IPR(425) = -1
            ELSE IF (IFL(I)(1:4) == 'AUTO') THEN
              NAUTO = 1
              GO TO 60
            END IF
          END DO
        END IF
        IF (LU15 == LU1 .AND. NAUTO == 0) GO TO 20
        GO TO 60
C * HELP OPTIONS
      ELSE IF (IFL(1)(1:4) == 'HELP') THEN
C * MANUAL PRINT
          WRITE (LU6, 99991, IOSTAT = IOST)
        GO TO 20
C * STOP/EXIT/QUIT
      ELSE IF (IFL(1)(1:4) == 'STOP') THEN
        GO TO 70
      ELSE IF (IFL(1)(1:4) == 'EXIT') THEN
        GO TO 70
      ELSE IF (IFL(1)(1:4) == 'QUIT') THEN
        GO TO 70
      ELSE IF (IFL(1)(1:5) == 'SCALE') THEN
C * SCALING PARAMETERS
        IF (KL > 1) THEN
          K = 0
          IPR(428) = 0
          DO I = 2, KL
            IF (IFL(I)(1:6) == 'DEGREE') THEN
              K      = K + 1
              IPR(446) = MIN (IP5 - 1, NINT (FN(K)))
            ELSE IF (IFL(I)(1:4) == 'NONE') THEN
              IPR(428) = 1
            END IF
          END DO
        END IF
        CALL PLA241
        GO TO 20
      ELSE IF (IFL(1)(1:2) == 'RR') THEN
        N = NINT (FN(1))
        IPR(370 + N) = MOD (IPR(370 + N) + 1, 2)
        IF (IPR(370 + N) == 1) THEN
          GO TO 30
        ELSE
          GO TO 40
        END IF
      ELSE IF (IFL(1)(1:2) == 'IN') THEN
        GO TO 30
      ELSE IF (IFL(1)(1:2) == 'EX') THEN
        GO TO 40
      ELSE IF (IFL(1)(1:3) == 'END') THEN
        GO TO 70
      END IF
      WRITE (LU6, 99997, IOSTAT = IOST) ICL(1:80)
      GO TO 20
C * INCLUDE/EXCLUDE OF REFERENCE REFLECTIONS
   30 INS = 1
      GO TO 50
   40 INS = -1
   50 IF (IPR(370) == 0) CALL PLA248
      DO I = 1, KN
         IVAL = NINT (FN(I))
         IF (IVAL > 0 .AND. IVAL <= IHPR(9)) THEN
           IRFY(IVAL) = INS * IABS (IRFY(IVAL))
         END IF
      END DO
      GO TO 20
   60 OPEN (UNIT = LU17, FILE = NAMEFIL(1:KNMFIL)//'.hkl',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
      CALL GEN108 (LU17, 0)
      OPEN (UNIT = LU60, FILE = NAMEFIL(1:KNMFIL)//'.rap',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
      OPEN (UNIT = LU4, FILE = NAMEFIL(1:KNMFIL)//'.psi',
     1  STATUS = 'UNKNOWN', IOSTAT = IOST)
      IF (IOST > 0) GO TO 80
        WRITE (LU6, 99993, IOSTAT = IOST)
      IF (ISW(1) == 0) CALL PLA241
      CALL PLA244 (2)
      CALL PLA247
      CALL PLA244 (3)
   70 WRITE (LU6, 99994, IOSTAT = IOST)
     1  NAMEFIL(1:KNMFIL), NAMEFIL(1:KNMFIL)
      CLOSE (UNIT = LU17)
      IF (IGBL(70) == 1) THEN
        WRITE (LU6, 99995, IOSTAT = IOST)
     1    NAMEFIL(1:KNMFIL), NAMEFIL(1:KNMFIL)
C * CREATE PostScript Listing Output
        CALL GEN108 (LU7, 1)
        CLOSE  (UNIT = LU1)
        READ (LU7, 99989, IOSTAT = IOST) PRBUF
        IF (IOST == 0) THEN
          CALL GEN108 (LU7, 0)
          FNLU1  = NAMEFIL(1:KNMFIL) //'.lps'
          OPEN (UNIT = LU1,  FILE = FNLU1, STATUS = 'UNKNOWN')
          CALL GEN089 (LU7, LU1, IGBL(49), IGBL(102))
          GO TO 90
        END IF
        CLOSE (UNIT = LU7, STATUS = 'DELETE')
      ELSE
        WRITE (LU6, 99990, IOSTAT = IOST) NAMEFIL(1:KNMFIL)
      END IF
      GO TO 90
   80 WRITE (LU6, 99996, IOSTAT = IOST) LUNIT
   90 IF (IPR(426) == 0) THEN
        CLOSE (UNIT = LU60, STATUS = 'DELETE')
      ELSE
        WRITE (LU6, 99992, IOSTAT = IOST) NAMEFIL(1:KNMFIL)
      END IF
      RETURN
99999 FORMAT ('P R O G R A M   H E L E N A   F O R   T H E   ',
     1 'H A N D L I N G   O F   C A D 4 - O U T P U T : V E R S I',
     2 ' O N = ', A, /, 120('='), //)
99998 FORMAT(/, 'HELENA - Version:', A,
     1 ' - <RETURN> for default run (= CALC SHELX)',/)
99997 FORMAT (':: Instruction Ignored', /, A, /)
99996 FORMAT (':: Cannot Open Unit:', I5)
99995 FORMAT (/, 80('='), /, ':: List Output   on: ', A, '.lis', /,
     1                       ':: EPS  Output   on: ', A, '.lps')
99994 FORMAT (':: SHELX-HKL     on: ', A, '.hkl', /,
     1        ':: SHELX-PSI     on: ', A, '.psi')
99993 FORMAT (/, '>> SHELX(L) - HKLF 4 FILE Will be Produced', /)
99992 FORMAT (':: ABSPSI-HKL    on: ', A, '.rap')
99991 FORMAT ('*EXCLUDE - EXCLUDES SPECIFIED REF.REFL NRS'//)
99990 FORMAT (/, 80('='), /, ':: List Output   on: ', A, '.lis')
99989 FORMAT (A)
      END SUBROUTINE PLA240
 
      SUBROUTINE PLA241
C * HELENA (2)
C * CALCULATION OF OVERALL SCALING FUNCTIONS. AN EXTRA PSEUDO REFERENCE
C * REFLECTION IS GENERATED FOR THIS PURPOSE BEING AN APPROPRIATELY
C * WEIGHTED AVERAGE OF THE OBSERVED REFERENCE REFLECTIONS.
      USE files
      USE parameters
      USE helena
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IX
      INTEGER :: ICY
      INTEGER :: IMX
      INTEGER :: IPC
      INTEGER :: IRF
      INTEGER :: NRF
      INTEGER :: NST
      INTEGER :: IRFX
      INTEGER :: ISGR
      INTEGER :: ISGX
      INTEGER :: NIRF
      INTEGER :: IORGR
      REAL :: SI
      REAL :: FJ
      REAL :: XI
      REAL :: XRT
      REAL :: SCF
      REAL :: STIJ
      REAL :: WGHT
      REAL :: FMNX
      REAL :: SJKIJ
      REAL :: FMNXK
      REAL :: DELTA
      REAL :: CHISI
      NST    = 0
      ISW(1) = 1
      IF (IPR(370) == 0) CALL PLA248
C * RETURN IN CASE OF NO REFERENCE REFLECTIONS
      IF (IPR(428) == 1) THEN
        WRITE (LU7, 99999, IOSTAT = IOST)
        GO TO 50
      END IF
      CALL GEN074 (FMN, 1, IP2 * IP3 * 9, 0.0)
C * SCALING FACTOR CALCULATION LOOP (GENERATE ONE ADDITIONAL AVERAGE REFL)
      IRFX = IHPR(9) + 1
      ISW(2) = 0
      DO ICY = 1, 7, 6
C * LOOP OVER SCALING GROUP
        DO ISGR = 1, ISG
          PC(IRFX, ISGR) = 0.0
          IPC = 0
          IMX = IHPR(2)
          CALL GEN074 (WAV, 1, IMX, 1.0)
          CALL GEN074 (FAV, 1, IMX, 0.0)
C * LOOP OVER REFERENCE REFLECTIONS
          DO 40 IRF = 1, IRFX
            IX = IRFY(IRF)
            IF (IX == 0) THEN
C * AVERAGE  SCALING CURVE(S)
              IF (ICY /= 1) GO TO 40
              NRF = IRFZ(ISW(2), ISGR)
              IRFZ(IRF, ISGR) = NRF
              DO I = 1, NRF
                F(I) = FAV(I)
                W(I) = WAV(I)
              END DO
            ELSE IF (IX > 0) THEN
C * INDIVIDUAL SCALING CURVE(S)
              CHISI = 0.0
              SJKIJ = 0.0
              STIJ  = 0.0
              NST   = 0
              IF (ISW(2) == 0) ISW(2) = IRF
C * GET DATA FOR REFERENCE REFLECTION 'IRF' AND SCALING GROUP 'ISGR'
              CALL GEN108 (LU9, 0)
   10         READ (LU9, IOSTAT = IOST) NIRF, XI, SI, XRT, ISGX, IORGR
              IF (IOST == 0) THEN
                IF (NIRF == IRF) THEN
                  IF (ISGR < ISGX) THEN
                    GO TO 20
                  ELSE IF (ISGR == ISGX) THEN
                    NST = NST + 1
                    IF (NST > IHPR(2)) CALL PLA245 (4)
                    SCF = 1
                    IF (ICY /= 1) THEN
                      CALL PLA246 (SCF, IRFX, ISGR, XRT)
C * CALCULATE CONTRIBUTION TO INSTABILITY CONSTANT
                      CHISI = CHISI + (XI - P(1, IRF, 1) / SCF)**2
                      SJKIJ = SJKIJ + XI**2
                      STIJ  = STIJ + SI**2
                      XI    = XI * SCF
                      SI    = SI * SCF
                    END IF
                    IF (SI > 0.0) THEN
                      WGHT = 1.0 / (SI**2)
                    ELSE
                      WGHT = 0.0
                    END IF
                    X(NST) = XRT
                    F(NST) = XI
                    W(NST) = WGHT
                    IF (IRF == ISW(2)) IONR(NST) =  IORGR
                    FMN(ICY, IRF, ISGR)     = FMN(ICY, IRF, ISGR) + XI
                    FMN(ICY + 1, IRF, ISGR) = FMN(ICY + 1, IRF, ISGR)
     1                                      + XI**2
                  END IF
                END IF
                GO TO 10
              END IF
C * END-OF-FILE REACHED ON FILE LU9
   20         IF (NST > 0) THEN
                IF (ICY /= 1) THEN
                  IF (IX == 0) THEN
                    PC(IRFX, ISGR) = PC(IRFX, ISGR) / IPC
                  ELSE IF (IX > 0) THEN
                    PC(IRF, ISGR)  = (ABS (CHISI - STIJ)) / SJKIJ
                    PC(IRFX, ISGR) = PC(IRFX, ISGR) + PC(IRF, ISGR)
                    IPC = IPC + 1
                  END IF
                END IF
              END IF
              IRFZ(IRF, ISGR) = NST
C * HANDLE CASE OF 0,1 REFERENCE VALUES IN SCALING GROUP
              IF (NST == 0) THEN
                GO TO 40
              ELSE IF (NST == 1) THEN
                P(1, IRF, ISGR) = F(1)
                GO TO 30
              ELSE
                FMNX  = FMN(ICY,     IRF, ISGR) / NST
                FMNXK = FMN(ICY + 1, IRF, ISGR) / NST
                FMN(ICY, IRF, ISGR) = FMNX
                DELTA = ABS (FMNXK - FMNX**2)
                FMN(ICY + 1, IRF, ISGR) = SQRT (DELTA) * 100.0 / FMNX
              END IF
            ELSE
              GO TO 40
            END IF
C * CALCULATE POLYNOMIAL FUNCTION THROUGH THE REFERENCE REFLECTIONS
            IF (NST == 0) THEN
              GO TO 40
            ELSE IF (NST == 1) THEN
              P(1, IRF, ISGR) = F(1)
            ELSE
              CALL GEN070 (IRFZ(IRF, ISGR), X, F, W, IPR(446),
     1         A(1, IRF, ISGR), B(1, IRF, ISGR), C(1, IRF, ISGR),
     2         G(1, IRF, ISGR), V(1, IRF, ISGR))
              CALL GEN069 (IPR(446), A(1, IRF, ISGR), B(1, IRF, ISGR),
     1        C(1, IRF, ISGR), P(1, IRF, ISGR), SIGMA,
     2         D(1, IRF, ISGR), G(1, IRF, ISGR))
            END IF
C * PLOT SCALING FUNCTION(S) FOR REFERENCE REFLECTION(S)
   30       CALL PLA249 (IRF, ISGR)
            IF (IX > 0) THEN
C * EVALUATE THE RESCALED VALUES OF THE REFERENCE REFLECTIONS AND THEIR
C * AVERAGE VALUE THAT MAY BE USED FOR THE SCALING OF THIS SET OF DATA
C * WITH RESPECT TO RELATED DATA SETS.
              DO J = 1, NST
                XRT = X(J)
                CALL PLA246 (SCF, IRF, ISGR, XRT)
                FJ   = F(J) * SCF
                WGHT = W(J)
                IF (ICY == 1) THEN
                  FMN(4, IRF, ISGR) = FMN(4, IRF, ISGR) + FJ
                  FMN(5, IRF, ISGR) = FMN(5, IRF, ISGR) + FJ**2
                  FAV(J)            = FAV(J) + 1.0 / SCF
                END IF
              END DO
              IF (ICY == 1) THEN
                FMNX  = FMN(4, IRF, ISGR) / NST
                FMNXK = FMN(5, IRF, ISGR) / NST
                FMN(4, IRF, ISGR) = FMNX
                FMN(5, IRF, ISGR) = SQRT (ABS (FMNXK - FMNX**2))
     1                            * 100.0 / FMNX
              END IF
            END IF
   40     CONTINUE
        END DO
C * END LOOP OVER REFERENCE REFLECTIONS - CLOSE PLOT
        CALL PLA249 (0, 0)
      END DO
C * END OF SCALING FACTOR CALCULATION LOOP
   50 RETURN
99999 FORMAT (/, '>>>> SCF = 1.00 <<<< ', /)
      END SUBROUTINE PLA241
 
      SUBROUTINE PLA242 (CELL, DC, VOL, OR, D, NR, COMPID, LU, RAD)
C * HELENA (3)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: NR
      INTEGER :: LU
      INTEGER :: IOST
      REAL :: V
      REAL :: SV
      REAL :: SVS
      REAL :: DET
      REAL :: VOL
      REAL :: RAD
      REAL :: VSTAR
      REAL, DIMENSION(3, 3) :: OR
      REAL, DIMENSION(3, 3) :: D
      REAL, DIMENSION(3, 3) :: GD
      REAL, DIMENSION(3, 3) :: GR
      REAL, DIMENSION(12)   :: CELL
      REAL, DIMENSION(6)    :: DC
      REAL, DIMENSION(9)    :: RC
      REAL, DIMENSION(9)    :: SA
      REAL, DIMENSION(9)    :: SAR
      CHARACTER(len=6) :: COMPID
      IF (NR <= 1 .AND. LU > 0) THEN
        CALL PLA262 (0)
        WRITE (LU, 99998, IOSTAT = IOST) COMPID, NR
      END IF
C * BEREKEN DE DIREKTE RECIPROKE ASSEN MATRIX
      CALL GEN003 (OR, D, V, 0)
C * EN PRINT BEIDE
      IF (NR < 1 .AND. LU > 0)
     1  WRITE (LU, 99996, IOSTAT = IOST) ((OR(I, J), J = 1, 3),
     2                      (D(I, J), J = 1, 3), I = 1, 3)
C * CALCULATE THE CELL PARAMETERS FROM MATRIX OR
C * ----------------------------------------------------------------------
C * BEREKENT RECIPROKE CELCONSTANTEN UIT DE RECIPROKE ASSEN/ORIENTATI
C * MATRIX VAN DE CAD3 OF CAD4.
C * INPUTPARAMETERS   OR(3,3)     ASSEN/ORIENTATIE MATRIX
C * OUTPUTPARAMETERS  RC(6)       A*,   .....  ,COS(GAMMA*)
C * ----------------------------------------------------------------------
      DO I = 1, 3
        J = I + 3
        K = MOD (I, 3) + 1
        L = MOD (I + 1, 3) + 1
        RC(I) = 0.0
        RC(J) = 0.0
        DO M = 1, 3
          RC(I) = RC(I) + OR(M, I)**2
          RC(J) = RC(J) + OR(M, K) * OR(M, L)
        END DO
      END DO
      DO I = 1, 3
        RC(I) = SQRT (RC(I))
      END DO
      DO I = 1, 3
        J = I + 3
        K = MOD (I, 3) + 1
        L = MOD (I + 1, 3) + 1
        RC(J) = RC(J) / (RC(K) * RC(L))
      END DO
      DO J = 1, 3
        RC(J + 6) = RC(J + 3)
        RC(J + 3) = ACOS (RC(J + 6)) * RAD
      END DO
C * METRIC TENSOR
      CALL GEN026 (1, GR, RC)
C * INVERT
      CALL GEN003 (GR, GD, DET, 0)
C * DIRECT CELL PARAMETERS
      CALL GEN026 (-1, GD, DC)
      VOL = 1 / SQRT (DET)
C * PRINT METRICAL TENSORS
      IF (NR < 1 .AND. LU > 0) THEN
        WRITE (LU, 99995, IOSTAT = IOST) ((GR(I, J), J = 1, 3),
     1    (GD(I, J), J = 1, 3), I = 1, 3)
        WRITE (LU, 99994, IOSTAT = IOST) GD(1, 1), GD(2, 2), GD(3, 3),
     1    GD(2, 3), GD(1, 3), GD(1, 2)
      END IF
C * PRINT CELL PARAMETERS
      VSTAR = 1.0 / VOL
      SV    = 0.0
      SVS   = 0.0
      CALL GEN074 (SAR, 1, 9, 0.0)
      CALL GEN074 (SA,  1, 9, 0.0)
      IF (LU > 0) THEN
        IF (NR < 1) WRITE (LU, 99993, IOSTAT = IOST)
     1    (DC(I), SA(I), RC(I), SAR(I), I = 1, 6), VOL, SV, VSTAR, SVS
        IF (NR == 0) THEN
          IF (CELL(1) == 0.0) THEN
            DO I = 1, 6
              CELL(I) = DC(I)
            END DO
          END IF
          WRITE (LU, 99999, IOSTAT = IOST) (CELL(I), I = 1, 6),
     1     (CELL(I), I = 7, 12)
        END IF
        IF (NR > 0) THEN
          WRITE (LU, 99997, IOSTAT = IOST)
     1      NR, ((OR(I, J), J = 1, 3), I = 1, 3), VOL
        END IF
      END IF
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT (//, 'CELL : ', 3F10.4, 3F10.3/'CESD : ', 3F10.4, 3F10.3)
99998 FORMAT ('L A T T I C E  G E O M E T R Y  D O C U M E N T  O F :'
     1 , 5X, A, /, 65('=')//25X, 'MATRIX NR:', I2, /, 25X, 12('=')//)
99997 FORMAT (I5, 2X, 9F10.6, F10.2)
99996 FORMAT (4X, 'RECIPROCAL AXES MATRIX', 12X,'DIRECT AXES MATRIX'/
     1 , 2(30('-'), 5X)/3(3F10.6, 3X, 3F11.5/))
99995 FORMAT (4X, 'RECIPROCAL METRICAL TENSOR', 9X, 'DIRECT METRICAL',
     1 ' TENSOR', /, 2(30('-'), 5X), /, 3(3F10.6, 3X, 3F11.5/))
99994 FORMAT (21X, 'NIGGLI VALUES ', /, 21X, '-------------'/, 2X,
     1 'A.A = ', F9.4, '  B.B = ', F9.4, ' C.C = ', F9.4/2X, 'B.C = ',
     2 F9.4, '  A.C = ', F9.4, ' A.B = ', F9.4/)
99993 FORMAT (//, 22X, 'CELL PARAMETERS'/, 22X, 15('-')//'A      = ',
     1 F9.4, '(', F6.4, ')', 7X, 'A(STAR)      = ', F8.5, '(',
     2 F7.5, ')', /, 'B      = ', F9.4, '(', F6.4, ')', 7X, 'B(STAR',
     3 ')      = ', F8.5, '(', F7.5, ')'/'C      = ', F9.4, '(',
     4 F6.4, ')', 7X, 'C(STAR)      = ', F8.5, '(', F7.5, ')'/
     5 'ALPHA  = ', F9.2, '(', F6.2, ')', 7X, 'ALPHA(STAR)  = ',
     6 F8.2, '(', F7.2, ')'/'BETA   = ', F9.2, '(', F6.2, ')', 7X,
     7 'BETA(STAR)   = ', F8.2, '(', F7.2, ')'/'GAMMA  = ',
     8 F9.2, '(', F6.2, ')', 7X, 'GAMMA(STAR)  = ', F8.2, '(',
     9 F7.2, ')', /, 'V      = ', F9.1, '(', F6.1, ')', 7X, 'V(STAR',
     * ')      = ', F8.5, '(', F7.5, ')')
      END SUBROUTINE PLA242
 
      SUBROUTINE PLA243 (ISW, NMBR, IPRT)
C * HELENA (4)
      IMPLICIT NONE
      INTEGER :: ISW
      INTEGER :: IPRT
      INTEGER, DIMENSION(20) :: NMBR
      NMBR(ISW)      = NMBR(ISW) + 1
      NMBR(ISW + 10) = NMBR(ISW + 10) + 1
      SELECT CASE (ISW)
        CASE (1)
          IPRT = 0
        CASE (2)
          IPRT = IPRT + 2
        CASE (3)
          IPRT = IPRT + 1
        CASE (5)
          IPRT = IPRT + 4
        CASE (6)
          IPRT = IPRT + 8
        CASE (7)
          IPRT = IPRT + 32
        CASE (8)
          IPRT = IPRT + 64
        CASE (10)
          IPRT = IPRT + 16
      END SELECT
      RETURN
      END SUBROUTINE PLA243
 
      SUBROUTINE PLA244 (MODE)
C * HELENA (5)
C * THIS SUBROUTINE PREPARES A DATA COLLECTION AND REDUCTION
C * DOCUMENT IN A4-FORMAT.
      USE files
      USE parameters
      USE helena
      IMPLICIT NONE
      INTEGER :: MODE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: II
      INTEGER :: KK
      INTEGER :: NR
      INTEGER :: IX
      INTEGER :: NST
      INTEGER :: IRF
      INTEGER :: KOR
      INTEGER :: IRFX
      INTEGER :: ISGR
      REAL :: VOL
      REAL :: SQPC
      REAL :: SSSI
C * DATAREDUCTION DOCUMENT (MODE = 3)
      IF (MODE == 3) THEN
        CALL PLA262 (0)
        WRITE (LU7, 99986, IOSTAT = IOST) COMPID
        WRITE (LU7, 99985, IOSTAT = IOST) HPAR(1), HPAR(2), IPR(446)
        WRITE (LU7, 99995, IOSTAT = IOST) DTHMIN, DTHMAX, RLPMN,
     1                    RLPMX, IHMIN, IHMAX, KMIN, KMAX, LMIN, LMAX
        ANPI = ANPI / NMBR(11)
        WRITE (LU7, 99990, IOSTAT = IOST)
     1    (NMBR(I), RDMP(26), I = 11, 20)
        IF (IHPR(12) > 0) THEN
          WRITE (LU7, 99978, IOSTAT = IOST) IHPR(12)
        END IF
        WRITE (LU7, 99989, IOSTAT = IOST) ANPI
        SSSI = HPAR(3) / HPAR(4)
        WRITE (LU7, 99977, IOSTAT = IOST) SSSI
C * REPORT SPECIAL BACKGROUND TREATMENT
        IF (IPR(425) == 1) WRITE (LU7,  99973, IOSTAT = IOST)
        IF (IPR(425) == 2) WRITE (LU7,  99972, IOSTAT = IOST)
C * LIST DATACOLLECTION DOC. (MODE = 1)
      ELSE IF (MODE == 1) THEN
        NR = IHPR(8)
        DO I = 1, 3
          DO J = 1, 3
            R(I, J) = ORM(I, J, NR)
          END DO
        END DO
        CALL PLA242 (CELL, DC, VOL, R, ROR, NR - 1, COMPID, 0, RGBL(6))
        CALL PLA262 (0)
        WRITE (LU7, 99994, IOSTAT = IOST)
     1    COMPID, DATC, ISG, DATIJD
        WRITE (LU7, 99993, IOSTAT = IOST)
     1    TEXT(31:36), RDMP(1), TEXT(23:25), RDMP(2), TEXT(8:11),
     2    TEXT(27:29), RDMP(3), TEXT(13:16), TEXT(17:21), RDMP(4)
        WRITE (LU7, 99992, IOSTAT = IOST)
     1    IRADIUS, RDMP(5), SLIT, RDMP(6), APTA, APTB, RDMP(7), APMIN,
     2    APMAX, RDMP(8), DTHMIN, DTHMAX, RDMP(9), DOMA, DOMB, RDMP(10)
        WRITE (LU7, 99991, IOSTAT = IOST)
     1    ISCANT, RDMP(11), NPIPRE, RDMP(12), SIGPRE, SIGMA, RDMP(13),
     2    ITMAX, RDMP(14), NBALF,NFRIDL,NEQFL, RDMP(15)
        WRITE (LU7, 99981, IOSTAT = IOST) IHPR(11), RDMP(16)
        WRITE (LU7, 99990, IOSTAT = IOST)
     1    (NMBR(I), RDMP(I + 16), I = 1, 10)
        WRITE (LU7, 99988, IOSTAT = IOST)
     1   IHMIN, IHMAX, NR - 1, KMIN, KMAX, LMIN, LMAX, XSEQ, PSIST,
     2   DELPSI, NRPSI, NFMS, (R(1, I), I = 1, 3),(ROR(1, I), I = 1, 3),
     3   IZZH, IZZK, IZZL, (R(2, I), I = 1, 3), (ROR(2, I), I = 1, 3),
     4   XNPSIFL, (R(3, I), I = 1, 3),
     4   (ROR(3, I), I = 1, 3), (DVECT(I), I = 1, 3), IHPR(9), ICHKT,
     5    SIGMI, FADING, NORCHK, DANG
C * DETERMINE WHICH CAD4 (UTRECHT) FROM CON1 AND CON2
        ICAD = '    '
        IF (NINT (CON1 *  1000000) == 586423) THEN
          ICAD = 'CAD0'
          IPR(424) = 0
        ELSE IF (NINT (CON1 * 1000000) == 586211) THEN
          ICAD = 'CAD1'
          IPR(424) = 0
        ELSE IF (NINT (CON1 * 1000000) == 587277) THEN
          ICAD = 'CAD2'
          IPR(424) = 2
        END IF
        WRITE (LU7, 99987, IOSTAT = IOST)
     1   FLAM1, FLAM2, WL21, PERF, IPR(424), DC(1), 0.0, DC(4), 0.0,
     2   BETA, DC(2), 0.0, DC(5), 0.0, ICAD, CON1, CON2, DC(3), 0.0,
     3   DC(6), 0.0, XRAYT(ISG), VOL, 0.0
C * MODE 2 DOCUMENT LISTING
      ELSE IF (MODE == 2) THEN
C * FIRST LIST THE ORIENTATION MATRICES
        KOR = IHPR(8)
        DO K = 1, KOR
          DO I = 1, 3
            DO J = 1, 3
              R(I, J) = ORM(I, J, K)
            END DO
          END DO
          CALL PLA242 (CELL, DC, VOL, R, ROR, K - 1, COMPID, LU7,
     1      RGBL(6))
        END DO
C * OUTPUT SCALING FACTOR DATA
        IF (IPR(428) == 0) THEN
          DO ISGR = 1, ISG
            IF (IRFZ(ISW(2), ISGR) > 1) THEN
              CALL PLA262 (0)
              WRITE (LU7,  99999, IOSTAT = IOST) COMPID, ISGR
              IRFX = IHPR(9) + 1
              DO 70 IRF = 1, IRFX
                IX = IRFY(IRF)
                IH = 0
                IK = 0
                IL = 0
                IF (IX < 0) THEN
                  GO TO 70
                ELSE IF (IX > 0) THEN
                  IH = IORREF(IX, 1)
                  IK = IORREF(IX, 2)
                  IL = IORREF(IX, 3)
                END IF
                IF (IRF == 4) CALL PLA262 (0)
                WRITE (LU7,  99984, IOSTAT = IOST) IH, IK, IL
                KK = IPR(446) + 1
                DO I = 1, KK
                  II = I - 1
                  WRITE (LU7, 99983, IOSTAT = IOST)
     1              II, P(I, IRF, ISGR), II, D(I, IRF, ISGR)
                END DO
                NST = IRFZ(IRF, ISGR)
                WRITE (LU7, 99998, IOSTAT = IOST) NST
                SQPC = SQRT (PC(IRF, ISGR))
                WRITE (LU7, 99997, IOSTAT = IOST)
     1            (FMN(I, IRF, ISGR), I = 1, 9), SQPC
   70         CONTINUE
            END IF
          END DO
        END IF
      END IF
      RETURN
99999 FORMAT ('R E F E R E N C E   A N D   S C A L I N G   D A T A'
     1 , '   FOR: ', A, /, 65('='), //, 25X, 'DATCOL SET:', I3,
     2 /, 25X, 14('=')/)
99998 FORMAT ('FREQUENCY OF THIS REFERENCE REFLECTION', 18('.'), I9)
99997 FORMAT ('MEAN OF UNSCALED REFERENCE REFLECTION', 19('.'),
     1 F9.0, /, 11X, 'R.M.S. DEVIATION (PERCENT)', 19('.'),
     2 F9.2, /, 26X, 'CHI-SQUARED', 19('.'),
     3 F9.2, /, 'MEAN OF 1-SCALED REFERENCE REFLECTION', 19('.'),
     4 F9.0, /, 11X, 'R.M.S. DEVIATION (PERCENT)', 19('.'),
     5 F9.2, /, 26X, 'CHI-SQUARED', 19('.'),
     6 F9.2, /, 'MEAN OF RESCALED REFERENCE REFLECTION', 19('.'),
     7 F9.0, /, 11X, 'R.M.S. DEVIATION (PERCENT)', 19('.'),
     8 F9.2, /, 26X, 'CHI-SQUARED', 19('.'),
     9 F9.2, /, 'INSTABILITY CONSTANT P ', 33('.'), F9.4)
99995 FORMAT ('THETA MIN / THETA MAX (DEG) (ACTUAL VALUES)', 4('.'),
     1 2F9.2,/,'1/LP  MIN / 1/LP  MAX', 26('.'), 2F9.2/'HMIN , HMAX ',
     2 ' (ACTUAL)', 26('.'), 2I9/'KMIN , KMAX  (ACTUAL)', 26('.'),
     3 2I9/'LMIN , LMAX  (ACTUAL)', 26('.'), 2I9)
99994 FORMAT (65('='), /, 'D A T A  C O L L E C T I O N  ',
     1 'D O C U M E N T  F O R :', 5X, A, /, 65('='), /, A,
     2 ' SET:', I3, 7X, 'ANALYSIS DATE: ', A, '   TIME: ', A, 22X,
     3 'R E F D U M P  L I S T', /, 65('-'), 22X, 22('='), /)
