      END SUBROUTINE PLA244
 
      SUBROUTINE PLA245 (NR)
C * HELENA(6)
      USE files
      USE helena
      IMPLICIT NONE
      INTEGER :: NR
      IF (NR < 0) THEN
        RETURN
      ELSE IF (NR == 1) THEN
        WRITE (LU6, 99999, IOSTAT = IOST) IHPR(3)
        WRITE (LU7, 99999, IOSTAT = IOST) IHPR(3)
      ELSE IF (NR == 2) THEN
        WRITE (LU6, 99998, IOSTAT = IOST) IHPR(1)
        WRITE (LU7, 99998, IOSTAT = IOST) IHPR(1)
      ELSE IF (NR == 3) THEN
        WRITE (LU6, 99997, IOSTAT = IOST)
        WRITE (LU7, 99997, IOSTAT = IOST)
      ELSE IF (NR == 4) THEN
        WRITE (LU6, 99996, IOSTAT = IOST) IHPR(2)
        WRITE (LU7, 99996, IOSTAT = IOST) IHPR(2)
      ELSE IF (NR == 5) THEN
        WRITE (LU6, 99995, IOSTAT = IOST)
        WRITE (LU7, 99995, IOSTAT = IOST)
      ELSE IF (NR == 6) THEN
        WRITE (LU6, 99994, IOSTAT = IOST) ISG
        WRITE (LU7, 99994, IOSTAT = IOST) ISG
      ELSE
        RETURN
      END IF
C * CALL EXIT/STOP
      CALL GEN127 (' ')
      RETURN
99999 FORMAT (//, ':: STOP, THERE ARE MORE THAN', I4,
     1 ' SCALING GROUPS')
99998 FORMAT (/, ':: EXIT - REASON : MORE THAN', I2,
     1 ' REFERENCE REFLECTIONS')
99997 FORMAT (/, ':: N O  D A T A  O N  F I L E   C A D 4'/)
99996 FORMAT (/, ':: MAXIMUM NUMBER OF REFL./SCGR:',I4,' EXCEEDED')
99995 FORMAT (/, ':: STOP - PROBLEM WITH REFDUMP REFLECTIONS',/)
99994 FORMAT (/, ':: STOP - INCOMPLETE REF. REFL. SET IN GROUP',I5,/)
      END SUBROUTINE PLA245
 
      SUBROUTINE PLA246 (SCF, IR, ISGR, XRT)
C * HELENA (7)
      USE files
      USE parameters
      USE helena
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: J0
      INTEGER :: IR
      INTEGER :: ISGR
      INTEGER :: ISGR0
      REAL :: DER
      REAL :: SCF
      REAL :: XRT
      REAL :: GEN071
      J0    = 0
      ISGR0 = 0
      DER   = 0.0
      SCF   = 1.0
      I     = IR
      J     = ISGR
   10 IF (IRFZ(I, J) == 0) THEN
C * NO REFERENCE REFLECTION IN THIS GROUP. ASSUME PREVIOUS GROUP SCALING
        J = J - 1
        IF (J > 0) GO TO 10
      ELSE IF (IRFZ(I, J) == 1) THEN
C * ONE OCCURRENCE OF REFERENCE REFLECTION
        SCF = P(1, I, 1) / P(1, I, J)
      ELSE
        SCF = P(1, I, 1) / GEN071 (IPR(446), A(1, I, J), B(1, I, J),
     1        C(1, I, J), XRT, DER)
      END IF
      IF (J < ISGR) THEN
        IF (J /= J0 .AND. ISGR /= ISGR0) THEN
          WRITE (LU7, 99999, IOSTAT = IOST) J, ISGR
          J0 = J
          ISGR0 = ISGR
        END IF
      END IF
      RETURN
99999 FORMAT (':: Note: SCALING GROUP', I3,' Used for SCALING GROUP',
     1   I3)
      END SUBROUTINE PLA246
 
      SUBROUTINE PLA247
C * HELENA (8)
      USE files
      USE parameters
      USE cggt
      USE helena
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: LX
      INTEGER :: IC
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: II
      INTEGER :: JJ
      INTEGER :: NN
      INTEGER :: NPI
      INTEGER :: ILN
      INTEGER :: ILT
      INTEGER :: IPX
      INTEGER :: IRI
      INTEGER :: ISC
      INTEGER :: ISGR
      INTEGER :: IRI0
      INTEGER :: IORM
      INTEGER :: IISC
      INTEGER :: IBGL
      INTEGER :: IBGR
      INTEGER :: IPNR
      INTEGER :: IPRT
      INTEGER :: NREFL
      INTEGER :: MORMO
      INTEGER :: IXRYT
      INTEGER :: IPSI0
      INTEGER :: IPSI1
      INTEGER :: IPSI2
      INTEGER :: IPERC
      INTEGER :: IORM0
      INTEGER :: IIBGL
      INTEGER :: IIBGR
      INTEGER :: IBTST
      INTEGER :: IRIMIN
      INTEGER :: IRISIG
      INTEGER :: IFRIDL
      INTEGER :: IIRISIG
      REAL :: Z1
      REAL :: X1
      REAL :: X2
      REAL :: Y1
      REAL :: Y2
      REAL :: Y3
      REAL :: Y4
      REAL :: YP
      REAL :: DD
      REAL :: DS
      REAL :: DY
      REAL :: OM
      REAL :: SI
      REAL :: XI
      REAL :: TH
      REAL :: XP
      REAL :: XP0
      REAL :: XPL
      REAL :: PHI
      REAL :: OMK
      REAL :: YP0
      REAL :: YPL
      REAL :: XXX
      REAL :: YYY
      REAL :: ZZZ
      REAL :: ETA
      REAL :: DUM
      REAL :: DDX
      REAL :: DEN
      REAL :: AOM
      REAL :: CDD
      REAL :: CHI
      REAL :: COM
      REAL :: CTT
      REAL :: HXY
      REAL :: PSI
      REAL :: PSS
      REAL :: RLP
      REAL :: RRR
      REAL :: SCF
      REAL :: SDD
      REAL :: SOM
      REAL :: SSS
      REAL :: STH
      REAL :: STT
      REAL :: TTH
      REAL :: XLP
      REAL :: XRT
      REAL :: XRLP
      REAL :: XBGL
      REAL :: XBGR
      REAL :: TMON
      REAL :: SPSI
      REAL :: STHL
      REAL :: SPHI
      REAL :: SETA
      REAL :: SCTT
      REAL :: SCHI
      REAL :: SCFX
      REAL :: PHIK
      REAL :: FSCF
      REAL :: CPSI
      REAL :: CTTM
      REAL :: CETA
      REAL :: BACK
      REAL :: APHI
      REAL :: ABAK
      REAL :: ACHI
      REAL :: ACOM
      REAL :: ASOM
      REAL :: CCHI
      REAL :: CPHI
      REAL :: COSQ
      REAL :: SINQ
      REAL :: TEMP
      REAL :: XIOSI
      REAL :: WIDTH
      REAL :: THETA
      REAL :: TEMP1
      REAL :: SINAL
      REAL :: COSAL
      REAL :: ACCHI
      REAL :: ACPHI
      REAL :: ASCHI
      REAL :: ASPHI
      REAL :: BGMAX
      REAL :: BGMIN
      REAL :: SQCHI
      REAL :: CKWTTM
      REAL :: PSICRY
      REAL :: RKAPPA
      REAL :: SQACHI
      REAL :: SQSCHI
      REAL :: XMONCU
      REAL :: XMONMO
      REAL, DIMENSION(3) :: DX
      REAL, DIMENSION(3) :: TX
      REAL, DIMENSION(3) :: RFL
      REAL, DIMENSION(3) :: SFL
      CHARACTER(len=80) :: LINE
      CHARACTER(len=6)  :: CODE
      CHARACTER(len=1)  :: C1
      CHARACTER(len=1)  :: C2
      XLP    = 0.0
      IRIMIN = - 10000
      IF (IPR(425) == 3) THEN
        DO I = 1, IP9
          ABAK = BAK(I, 1) * WL21
          IF (ABAK < 1.0) THEN
            ABAK = ASIN (ABAK) * HPAR(24)
          ELSE
            ABAK = 0.0
          END IF
          BAK(I, 1) = ABAK
        END DO
        CALL GEN108 (LU10, 0)
        DO
          READ (LU10, IOSTAT = IOST) NREFL, IH, IK, IL, CODE, PSI, NPI,
     1      IBGL, ISC, IBGR, THETA, PHIK, OMK, RKAPPA, WIDTH, IXRYT,
     2      IFRIDL, ILT, ISGR, XI, SI, IPRT, IORM, IBTST, FSCF
          IF (IOST /= 0) EXIT
          IF (IH == 0 .AND. IK == 0 .AND. IL == 0) EXIT
          SCF = 1.0
          IF (IPR(428) /= 1) THEN
            XRT = IXRYT / 3600.0
            CALL PLA246 (SCF, IHPR(9) + 1, ISGR, XRT)
          END IF
          DO J = 2, IP9, 2
            IF (THETA < BAK(J, 1)) EXIT
          END DO
          XBGL = IBGL * SCF * FSCF / NPI
          XBGR = IBGR * SCF * FSCF / NPI
          BGMIN = MIN (XBGL, XBGR)
          BGMAX = MAX (XBGL, XBGR)
          IF (BGMAX < 3.0 * BGMIN) THEN
            BAK(J, 4) = BAK(J, 4) + 1.0
            BAK(J, 5) = BAK(J, 5) + BGMIN
          END IF
        END DO
        DO I = 2, IP9, 2
          IF (NINT (BAK(I, 4)) > 0) THEN
            BAK(I,     5) = 4.0 * BAK(I, 5) / BAK(I, 4)
            BAK(I - 1, 5) = BAK(I, 5)
          END IF
        END DO
        DO I = 2, IP9 - 2, 2
          IF (NINT (BAK(I, 4)) > 0.0 .AND.
     1        NINT (BAK(I + 2, 4)) > 0.0) THEN
            BAK(I, 5) = (BAK(I - 1, 5) + BAK(I + 1, 5)) / 2.0
          END IF
        END DO
        DO I = 1, IP9
          IF (BAK(I, 5) > 0.0) THEN
            WRITE (LU6, '(I5, 3F10.2)', IOSTAT = IOST)
     1     I, BAK(I, 1), BAK(I, 4), BAK(I, 5)
          END IF
        END DO
      END IF
C * INITIALIZE INTENSITY STATISTICS ROUTINE
      CALL PLA169 (0, DUM, DUM, DUM, LU6)
      DTHMAX = 0.0
      DTHMIN = 90.0
      RLPMX  = 0.0
      RLPMN  = 10.0
      XMONCU = 26.6 / HPAR(24)
      XMONMO = 12.2 / HPAR(24)
      IPNR   = 0
      TMON   = XMONMO
      NN     = 1
      IF (WL21 > 1.0) TMON = XMONCU
      CTTM   = COS (TMON)
      CKWTTM = CTTM**2
C * DETERMINE OUTPUT SCALING FACTOR
      SCFOVFL = 10.0
      DO
      SCFOVFL = SCFOVFL * 0.1
        IF (SCFOVFL * SIMX < 10000.0) EXIT
        IF (SCFOVFL * XIMX <   1.0E8) EXIT
      END DO
      IHMAX = -999
      IHMIN =  999
      KMAX  = -999
      KMIN  =  999
      LMAX  = -999
      LMIN  =  999
      MORMO =  0
      SINAL = SQRT (CON1)
      COSAL = CON2
      CALL GEN108 (LU10, 0)
      LX  = LU11
      CALL GEN108 (LX, 0)
      ILN = IGBL(102)
      DO
   10   READ (LX, IOSTAT = IOST) NREFL, IH, IK, IL, CODE, PSI, NPI,
     1    IBGL, ISC, IBGR, THETA, PHIK, OMK, RKAPPA, WIDTH, IXRYT,
     2    IFRIDL, ILT, ISGR, XI, SI, IPRT, IORM, IBTST, FSCF
        IF (IOST == -1) GO TO 20
        IF (IH == 0 .AND. IK == 0 .AND. IL == 0) THEN
          WRITE (LU7, 99999, IOSTAT = IOST)
          GO TO 10
        END IF
C * CALCULATE PSI_FLACK
        IF ((IH == IK) .AND. (IK == IL)) THEN
          RFL(1) = REAL (IH)
          RFL(2) = REAL (-IH)
          RFL(3) = 0.0
        ELSE
          RFL(1) = REAL (IK - IL)
          RFL(2) = REAL (IL - IH)
          RFL(3) = REAL (IH - IK)
        END IF
C * UFL(TRANSPOSE)*ROR
        DO I = 1, 3
          SFL(I) = 0.0
          DO J = 1, 3
            SFL(I) = SFL(I) + RFL(J) * ROR(J, I)
          END DO
        END DO
        SINQ   = SIN (PHIK / HPAR(24))
        COSQ   = COS (PHIK / HPAR(24))
        RFL(1) =   SFL(1) * COSQ + SFL(2) * SINQ
        RFL(2) = - SFL(1) * SINQ + SFL(2) * COSQ
        RFL(3) =   SFL(3)
        SFL(1) =   RFL(1) * COSAL - RFL(3) * SINAL
        SFL(2) =   RFL(2)
        SFL(3) =   RFL(1) * SINAL + RFL(3) * COSAL
        SINQ   = SIN (RKAPPA / HPAR(24))
        COSQ   = COS (RKAPPA / HPAR(24))
        RFL(1) =   SFL(1) * COSQ + SFL(2) * SINQ
        RFL(2) = - SFL(1) * SINQ + SFL(2) * COSQ
        RFL(3) =   SFL(3)
        SFL(1) =   RFL(1) * COSAL + RFL(3) * SINAL
        SFL(2) =   RFL(2)
        SFL(3) = - RFL(1) * SINAL + RFL(3) * COSAL
        SINQ   = SIN ((OMK - THETA) / HPAR(24))
        COSQ   = COS ((OMK - THETA) / HPAR(24))
        RFL(1) =   SFL(1) * COSQ + SFL(2) * SINQ
        RFL(2) = - SFL(1) * SINQ + SFL(2) * COSQ
        RFL(3) =   SFL(3)
        IF (THETA < 0.0) THEN
          RFL(2) = - RFL(2)
          RFL(3) = - RFL(3)
        END IF
        PSICRY = HPAR(24) * ATAN2 (RFL(1), RFL(3))
C * CALCULATE EULERIAN ANGLES FROM KAPPA ANGLES
        GO TO 40
   20   IF (LX == LU10) GO TO 70
        LX   = LU10
        CALL GEN108 (LX, 0)
C * PLOT-PSI ROUTINE
        IF (IPNR  > 0) THEN
C * PSI-SCAN ANALYSIS AND PLOT
          DO J = 1, IPNR
C * NAMPLT
   30       IF (LU15 == 1) THEN
              CALL GGIP (-999.0, 0.0, 0.0, -2)
            ELSE
              CALL GGIP (-999.0, 0.0, 0.0, 3)
            END IF
            CALL GGIP (25.0, 25.0, 0.0, 1)
C * PLOT BOX
            CALL GGIP (0.0,   0.0, 0.0, 3)
            CALL GGIP (0.0,  25.0, 0.0, 2)
            CALL GGIP (25.0, 25.0, 0.0, 2)
            CALL GGIP (25.0,  0.0, 0.0, 2)
            CALL GGIP (0.0,   0.0, 0.0, 2)
            CALL PLA439 (0.0, COMPID, 6, 0.7, 1, 2, 0.3, 24.0)
            CALL GGIP (12.5, 12.5, 0.0, -3)
            CALL PLA439 (0.0, 'Psi-Scan', 8,  0.6, 1, 2, -12.0, -12.2)
            CALL PLA439 (0.0, '0',        1, 0.25, 1, 2,  12.0,  -0.1)
            CALL PLA439 (0.0, '90',       2, 0.25, 1, 2,  -0.2, -12.0)
            CALL PLA439 (0.0, '180',      3, 0.25, 1, 2, -12.4,  -0.1)
            CALL PLA439 (0.0, '270',      3, 0.25, 1, 2,  -0.2,  11.6)
            TEMP  = 0.0
            TEMP1 = 1.0E10
            DO I = 1, 36
              IF (PSIS(I, J) >= 0.01) THEN
                TEMP  = MAX (TEMP,  PSIS(I, J))
                TEMP1 = MIN (TEMP1, PSIS(I, J))
              END IF
            END DO
            IPERC = NINT (TEMP1 * 100.0 / TEMP)
            DO K = 1, 2
C * SET COLOR
              CALL GGIP (0.0, FLOAT (K), 0.0, 0)
              DO I = 1, 36
                PSI = (I - 1) * 10.0 / HPAR(24)
                XPL =  COS (PSI)
                YPL = -SIN (PSI)
                XP  = 6.5
                YP  = 6.5
                DS  = 0.1 * (K - 1)
                IF (K /= 1) THEN
                  PSS = PSIS(I, J) / TEMP
                  IF (PSS < 0.0) PSS = 0.0
                  XP = PSS * XP
                  YP = PSS * YP
                END IF
                XPL = XPL * (XP + 5.0)
                YPL = YPL * (YP + 5.0)
                IF (K /= 1) THEN
                  IF (I < 2) THEN
                    XP0 = XPL
                    YP0 = YPL
                  ELSE
                    CALL GGIP (XPL, YPL, 0.0, 2)
                  END IF
                END IF
                YPL = YPL - DS
                CALL GGIP (XPL, YPL, 0.0, 3)
                IF (K < 2) THEN
                  XPL = XPL * (5.0 / 11.5)
                  YPL = YPL * (5.0 / 11.5)
                  CALL GGIP (XPL, YPL, 0.0, 2)
                ELSE
                  DO L = 1, 3, 2
                    DY = DS * (2 - L)
                    DO M = 1, 3, 2
                      DDX  = DS * (2 - M) * (2 - L)
                      XPL = XPL + DDX
                      YPL = YPL + DY
                      CALL GGIP (XPL, YPL, 0.0, 2)
                    END DO
                  END DO
                  YPL = YPL + DS
                  CALL GGIP (XPL, YPL, 0.0, 3)
                END IF
              END DO
              IF (K /= 1) THEN
                CALL GGIP (XP0, YP0, 0.0, 2)
                CALL GGIP (0.0, 0.0, 0.0, 3)
              END IF
            END DO
            DO JJ = 1, 3
              XPL = 5 + JJ * 2
              CALL GEN040 (IHKLP(JJ, J), NQ1, IPX)
              CALL PLA439 (0.0, NQ1, IPX, 0.5, 1, 2, XPL, -12.2)
            END DO
            IPX = 0
            CALL GEN040 (IPERC, NQ1, IPX)
            CALL PLA439 (0.0, NQ1, IPX, 0.5, -1, 2, 11.0, 11.5)
            CALL GGIP (0.0, 0.0, 0.0, 3)
C * ENDPLT
            CALL GGIP (0.0, 0.0, 0.0, -1)
C * WHAT NEXT ?
            CALL PLA012 (4, 1)
C * REFRESH
            IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
              GO TO 30
            ELSE IF (IGGT(1:1) == '!') THEN
              CALL PLA280 ('NEXT')
            END IF
            IF (IGGT(1:4) == 'EXIT') GO TO 10
            CALL GEN038 (IGGT, 1, 80)
          END DO
        END IF
        GO TO 10
   40   IF (MORMO /= IORM) MORMO = IORM
        SCF  = 1.0
        ANPI = ANPI + IABS(NPI)
        IF (LX /= LU11) THEN
          IF (CODE(1:1) /= 'I') THEN
            IHMAX = MAX (IHMAX, IH)
            KMAX  = MAX (KMAX,  IK)
            LMAX  = MAX (LMAX,  IL)
            IHMIN = MIN (IHMIN, IH)
            KMIN  = MIN (KMIN,  IK)
            LMIN  = MIN (LMIN,  IL)
          END IF
C * SKIP SCALING IN CASE OF IPR(428) = 1
          IF (IPR(428) /= 1) THEN
            XRT = IXRYT / 3600.0
            CALL PLA246 (SCF, IHPR(9) + 1, ISGR, XRT)
            HPAR(2) = MAX (HPAR(2), SCF)
            HPAR(1) = MIN (HPAR(1), SCF)
          END IF
        END IF
C * CALCULATE NET INTENSITY WITH 'AVERAGE BACKGROUND CURVE'
        IF (IPR(425) == 3) THEN
          IF (MAX(IBGL, IBGR) > 3.0 * MIN (IBGL, IBGR)) THEN
            DO II = 1, IP9
              IF (THETA < BAK(II, 1)) EXIT
            END DO
            SCFX = FSCF / FLOAT (IABS (NPI))
            BACK = BAK(II, 5) / (SCF * SCFX)
            XI = (ISC - BACK)     * 100.0 * SCFX
            SI = SQRT (FLOAT (ISC)) * 100.0 * SCFX
          END IF
        END IF
        XI = XI * SCF
        SI = SI * SCF
C * CALCULATE LP - CORRECTION
        PSI = PSI / HPAR(24)
        XXX = IH * ORM(1, 1, IORM) + IK * ORM(1, 2, IORM)
     1                             + IL * ORM(1, 3, IORM)
        YYY = IH * ORM(2, 1, IORM) + IK * ORM(2, 2, IORM)
     1                             + IL * ORM(2, 3, IORM)
        ZZZ = IH * ORM(3, 1, IORM) + IK * ORM(3, 2, IORM)
     1                             + IL * ORM(3, 3, IORM)
        HXY  = XXX**2   + YYY**2
        RRR  = SQRT (HXY + ZZZ**2)
        HXY  = SQRT (HXY)
        STH  = 0.5 * WL11 * RRR
        TH   = ASIN (STH)
        TTH  = 2 * TH
        IF (HXY < 1.0E-7) THEN
          CHI = 90.0 / HPAR(24)
          PHI = 0.0
        ELSE
          PHI = ATAN2 (-XXX, YYY)
          CHI = ATAN2 ( ZZZ, HXY)
        END IF
        OM   = TH
        CPHI = COS (PHI)
        SPHI = SIN (PHI)
        CCHI = COS (CHI)
        SCHI = SIN (CHI)
        CTT  = COS (TTH)
        STT  = SIN (TTH)
        SCTT = CTT**2
        COM  = COS (OM)
        SOM  = SIN (OM)
        IF (IPR(424) == 0) THEN
          XLP =  (1 + SCTT) / 2.0
        ELSE IF (IPR(424) == 1) THEN
C * PERPENDICULAR MODE (CAD4)
          XLP = PERF * (CKWTTM + SCTT) / (1.0 + CKWTTM)
     1        + (1.0 - PERF) * (CTTM + SCTT) / (1.0 + CTTM)
        ELSE IF (IPR(424) == 2) THEN
C * PARALLEL MODE (CAD4T)
          XLP = PERF * (1 + CKWTTM * SCTT) / (1 + CKWTTM)
     1        + (1.0 - PERF) * (1.0 + CTTM * SCTT) / (1.0 + CTTM)
        END IF
        RLP = STT / XLP
C * DETERMINE THMIN, THMAX, LPMIN, LPMAX
        DTHMAX = MAX (DTHMAX, ABS (THETA))
        DTHMIN = MIN (DTHMIN, ABS (THETA))
        RLPMX  = MAX (RLPMX, RLP)
        RLPMN  = MIN (RLPMN, RLP)
        SQSCHI = SCHI**2
        SQCHI  = SQRT (SQSCHI)
        IF (SQCHI > 0.0) THEN
          SSS = SCHI / SQCHI
        ELSE
          SSS = 1
        END IF
        IF (ABS (PSI) > 0.0) THEN
          CPSI   = COS (PSI)
          SPSI   = SIN (PSI)
          ACCHI  = CPSI * CCHI
          SQACHI = ACCHI**2
          ASCHI  = SSS * SQRT (ABS (1 - SQACHI))
          ACHI   = ATAN2(ASCHI, ACCHI)
          SETA   = CCHI * SPSI / ASCHI
          CETA   = SCHI / ASCHI
          ETA    = ATAN2 (SETA, CETA)
          AOM    = ETA + TH
          SDD    = -SPSI / ASCHI
          CDD    = CPSI * SCHI / ASCHI
          DD     = ATAN2 (SDD, CDD)
          APHI   = DD + PHI
          ACPHI  = COS (APHI)
          ASPHI  = SIN (APHI)
          ACOM   = COS (AOM)
          ASOM   = SIN (AOM)
        ELSE
          ACCHI = CCHI
          ASCHI = SCHI
          ACPHI = CPHI
          ASPHI = SPHI
          ACOM  = COM
          ASOM  = SOM
          ACHI  = CHI
          APHI  = PHI
          AOM   = OM
        END IF
        DO I = 1, 3
          DEN = SQRT (ORM(1, I, IORM)**2 + ORM(2, I, IORM)**2
     1                                   + ORM(3, I, IORM)**2)
          X1    = ORM(1, I, IORM) / DEN
          Y1    = ORM(2, I, IORM) / DEN
          Z1    = ORM(3, I, IORM) / DEN
          X2    =   X1 * ACPHI + Y1 * ASPHI
          Y2    = - X1 * ASPHI + Y1 * ACPHI
          Y3    =   Y2 * ACCHI + Z1 * ASCHI
          TX(I) =   X2 * ACOM  + Y3 * ASOM
          Y4    = - X2 * ASOM  + Y3 * ACOM
          DX(I) = - TX(I) * CTT + Y4 * STT
        END DO
        ACHI = ACHI * HPAR(24)
        APHI = APHI * HPAR(24)
        AOM  = AOM  * HPAR(24)
        PSI  = PSI  * HPAR(24)
        TH   = TH   * HPAR(24)
C * TEST FOR CONSISTENCY
        XRLP = RLP
C * ACCUMULATE SUM(SIGMA) AND SUM(INT)
        HPAR(3) = HPAR(3) + SI
        HPAR(4) = HPAR(4) + XI
        IRI     = MAX (IRIMIN, NINT (XI * XRLP * SCFOVFL))
C * AVOID DEVISION BY ZERO (MINIMUM IRISIG = 1)
        IRISIG = MAX (1, NINT (SI * XRLP * SCFOVFL))
        ILT    = 1
        IF (IRI < CILT * IRISIG) ILT = 2
        C1 = CODE(1:1)
        C2 = CODE(2:2)
        IC = 0
        IF (C1 == 'N') IC = 2
        IF (C1 == 'I') IC = 1
        IF (LX /= LU10 .AND. IC /= 1) THEN
          IF (IPNR /= 0) THEN
            IF (IH == IHKLP(1, IPNR) .AND. IK == IHKLP(2, IPNR)
     1        .AND. IL == IHKLP(3, IPNR)) GO TO 50
          END IF
          IF (IPNR < IP4) THEN
            IPNR = IPNR + 1
          ELSE
            GO TO 60
          END IF
          IHKLP(1, IPNR) = IH
          IHKLP(2, IPNR) = IK
          IHKLP(3, IPNR) = IL
C * CALCULATE ARRAY INDEX
   50     IPSI0 = NINT (PSI)
          IF (IPSI0 < 0) IPSI0 = IPSI0 + 360
          IPSI1 = IPSI0 / 10 + 1
          PSIS(IPSI1, IPNR) = IRI
C * CALCULATE ARRAY INDEX
          IPSI0 = MOD (NINT (PSI + 180.0), 360)
          IF (IPSI0 < 0) IPSI0 = IPSI0 + 360
          IPSI2 = IPSI0 / 10 + 1
          IRI0 = NINT (PSIS(IPSI2, IPNR))
          IF (IRI0 > 0) GO TO 60
          PSIS(IPSI2, IPNR) = - IRI
        END IF
C * INTENSITY AND EXTINCTION STATISTICS FOR NON-PSISCAN REFLECTIONS
   60   IF (LX /= LU11) THEN
          STHL = SIN (THETA * 0.01745329) / WL21
          CALL PLA169 (1, FLOAT (IRI), FLOAT (IRISIG), STHL, LU6)
        END IF
C * SET WEAK REFLECTIONS TO 1/2 SIGMA(I) FOR SHELX-FORMAT
        IF (IAND(IPRT, 8189) /= 0) THEN
          XIOSI = FLOAT (IRI) / FLOAT (IRISIG)
          IORM0 = IORM - 1
          IIBGL = MIN (99999,  IBGL)
          IISC  = MIN (9999999, ISC)
          IIBGR = MIN (99999,  IBGR)
          IF (IBTST < 0) ILT = 0
          IFRIDL = IABS (IFRIDL)
          IF (IPR(320) > 0) THEN
            ILN = ILN + 1
            IF (ILN > IGBL(102)) THEN
              CALL PLA262 (0)
              ILN = 6
              WRITE (LU7, 99993, IOSTAT = IOST)
            END IF
            WRITE (LU7, 99992, IOSTAT = IOST)
     1        IH, IK, IL, CODE, IFRIDL, ILT, ISGR, IORM0, SCF, 1.0, RLP,
     2        NPI, IIBGL, IISC, IIBGR, THETA, PHIK,  RKAPPA, OMK, WIDTH,
     3        IXRYT, IRI, IRISIG, XIOSI, PSI, NREFL
          END IF
        END IF
        IF (C1 /= 'I' .AND. C2 /= 'X' .AND. C2 /= 'C'
     1          .AND. IBTST >= 0) THEN
          IIRISIG = MIN (99999, IRISIG)
          IF (LX == LU11) THEN
            WRITE (LU4, 99994, IOSTAT = IOST)
     1        IH, IK, IL, IRI, IIRISIG, NN, (TX(I), DX(I), I = 1, 3)
          ELSE
            WRITE (LU17, 99994, IOSTAT = IOST)
     1        IH, IK, IL, IRI, IIRISIG, NN, (TX(I), DX(I), I = 1, 3)
            IF (IPR(426) == 1) WRITE (LU60, 99998, IOSTAT = IOST)
     1        IH, IK, IL, IRI, IIRISIG, PSICRY
          END IF
        END IF
      END DO
C * WRITE BLANK CARD TO TERMINATE
   70 WRITE (LU17, 99991, IOSTAT = IOST)
      IF (IPR(426) == 1) WRITE (LU60, 99991, IOSTAT = IOST)
C * COPY PSI-SCAN DATA AFTER BLANK LINE (INVISIBLE FOR SHELX(L/S)
      CALL GEN108 (LU4, 1)
      DO
        READ (LU4, 99997, IOSTAT = IOST) LINE
        IF (IOST /= 0) EXIT
        WRITE (LU17, 99997, IOSTAT = IOST) LINE
      END DO
      WRITE (LU17, 99991, IOSTAT = IOST)
C * CLOSE FILES
      RETURN
99999 FORMAT (25('*'), ' REFLECTION H=0,K=0,L=0 DELETED ', 25('*'))
99998 FORMAT (3I4, 2I8, F9.3)
99997 FORMAT (A)
99994 FORMAT (3I4, 2I8, I4, 6F8.5)
99993 FORMAT ('  H  K  L  CODE FL S O  SCF  1/T 1/LP NPI  BL    ISC',
     1 3X, 'BR THETA   PHIK  KAPPA    OMK WIDTH XRAYT  I(NET) SIG(I) '
     2 , 'I/S(I)    PSI NREFL'/)
99992 FORMAT (3I3, 1X, A, 2I1, 2I2, 3F5.2, I3, I5, I7, I5, F6.2,
     1 3F7.2, F5.2, I7, I9, I6, F7.1, F7.2, I6)
99991 FORMAT (1X)
      END SUBROUTINE PLA247
 
      SUBROUTINE PLA248
C * HELENA (9)
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE helena
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IX
      INTEGER :: LX
      INTEGER :: NR
      INTEGER :: LNR
      INTEGER :: KEY
      INTEGER :: ILT
      INTEGER :: IRF
      INTEGER :: ISC
      INTEGER :: NPI
      INTEGER :: MAXB
      INTEGER :: MINB
      INTEGER :: IRFD
      INTEGER :: IRFX
      INTEGER :: IBGL
      INTEGER :: IBGR
      INTEGER :: ICNT
      INTEGER :: IHKL
      INTEGER :: IPR8
      INTEGER :: IPRM
      INTEGER :: IPRT
      INTEGER :: NREFL
      INTEGER :: NCARD
      INTEGER :: IORR4
      INTEGER :: IBTST
      INTEGER :: IXRYT
      INTEGER :: NREFLC
      INTEGER :: NREFLN
      INTEGER :: NERROR
      INTEGER :: IXRAYT
      INTEGER :: IORR40
      INTEGER :: ICDTYP
      INTEGER :: IDCDOC
      INTEGER :: IFRIDL
      INTEGER :: IXRYT0
      INTEGER :: IXRYTB
      REAL :: XI
      REAL :: SI
      REAL :: SCF
      REAL :: OMK
      REAL :: XIS
      REAL :: DIF
      REAL :: XRT
      REAL :: RAT
      REAL :: PSI
      REAL :: PHIK
      REAL :: FSCF
      REAL :: BACK
      REAL :: THETA
      REAL :: WIDTH
      REAL :: XIMAX
      REAL :: XIMIN
      REAL :: XRFIRF
      REAL :: RKAPPA
      CHARACTER(len=11) :: FORMC
      CHARACTER(len=77) :: CARD
      CHARACTER(len=6)  :: CODE
      CHARACTER(len=1)  :: C1
      CHARACTER(len=1)  :: C2
      CHARACTER(len=1)  :: C4
      CALL GEN108 (LU16, 0)
      IPR(370) = 1
      IHPR(9)  = 0
      IDCDOC   = 0
      ISG      = 0
      IXRYT0   = 0
      XIMAX    = 1.0
      XIMIN    = 1.0
      NREFL    = 0
      ICNT     = 0
      IRF      = 0
      IRFX     = 0
      LX       = 0
      IRFD     = 0
      NERROR   = -1
   10 NERROR   = NERROR + 1
      IF (NERROR > 100) GO TO 120
   20 READ  (LU16, 99985, IOSTAT = IOST) ICDTYP
      IF (IOST /= 0) THEn
        IF (IOST == -1) THEN
          GO TO 120
        ELSE
          GO TO 10
        END IF
      END IF
      IF (ICDTYP == 0) THEN
        GO TO 20
      ELSE IF (ICDTYP == 21) THEN
        FORMC = '(1X, I2, A)'
      ELSE
        FORMC = '(2X, I2, A)'
      END IF
      CALL GEN108 (LU16, 0)
      NCARD = 0
C * LOOP TO READ CAD4-PROTOCOL FILE RECORDS
   30 NERROR = NERROR + 1
      IF (NERROR > 100) GO TO 120
   40 READ (LU16, FORMC, IOSTAT = IOST) KEY, CARD
      IF (IOST /= 0) THEN
        IF (IOST == -1) THEN
          GO TO 120
        ELSE
          GO TO 30
        END IF
      END IF
      NCARD = NCARD + 1
C * TYPE 0 RECORD:LISTNR,RH,RK,RL,HTAOIS,RTHETA,RPHIK,ROMK,RKAPPA,
C * IRNPI,RSCANG,RSCINT
      IF (KEY == 0) THEN
        IF (IRFD == 0) GO TO 40
        READ (CARD, 99998, IOSTAT = IOST) LNR
        IF (IOST > 0) GO TO 130
        IF (LNR > 0 .AND. LNR <= 25) THEN
          RDMP(LNR) = CARD(1:59)
          READ (CARD, 99997, IOSTAT = IOST) (IORREF(LNR, I), I = 1, 3),
     1          HTAOIS(LNR)
          IF (IOST > 0) GO TO 130
C * RTHETA,RPHI,ROMK,KKAPPA,IRNPI,RSCANG,INTIRSC
          IORR4  = IORREF(LNR, 1) * 40000 + IORREF(LNR, 2) * 200 +
     1             IORREF(LNR, 3)
          IORR40 = IORREF(LNR, 4)
          IF (IORR40 /= 0) THEN
            IF (IORR40 == IORR4) GO TO 40
            CALL PLA245 (5)
          END IF
          IORREF(LNR, 4) = IORR4
          IORF = IORF + 1
          IF (HTAOIS(LNR)(5:5) == 'I') THEN
            IHPR(9) = IHPR(9) + 1
            IF (IHPR(9) > IHPR(1)) CALL PLA245 (2)
            IRFY(IHPR(9)) = LNR
          END IF
        END IF
C * TYPE 1 RECORD:NREFL, H, K, L, CODE, PSI, NPI, BGL, INT, BGR
      ELSE IF (KEY == 1) THEN
        READ (CARD, 99988, IOSTAT = IOST) NREFLN, IH, IK, IL, CODE, PSI,
     1        NPI, IBGL, ISC, IBGR
        IF (IOST > 0) GO TO 130
        IF (NREFLN /= NREFL + 1) THEN
          WRITE (LU7, 99983, IOSTAT = IOST) NREFLN
          WRITE (LU6, 99983, IOSTAT = IOST) NREFLN
        END IF
C * TYPE 2 RECORD:NREFL,THETA,PHIK,OMK,KAPPA,WIDTH,XRAYT,FRIDL
      ELSE IF (KEY == 2) THEN
        READ (CARD, 99996, IOSTAT = IOST) NREFLC, THETA, PHIK, OMK,
     1                     RKAPPA, WIDTH, IXRYT, IFRIDL
        IF (IOST > 0) GO TO 130
        IF (NREFLC /= NREFLN) THEN
          WRITE (LU7, 99984, IOSTAT = IOST) NREFLC
          WRITE (LU6, 99984, IOSTAT = IOST) NREFLC
        ELSE
          NREFL = NREFLN
C * KEEP TRACK OF THE CURRENT CUMULATIVE XRAY-TIME
          IF (ISW(3) >= 0) THEN
            IXRYTB = IXRYT
            IF (MOD (NMBR(3), IHPR(1)) /= 0) CALL PLA245 (6)
            IF (ISW(3) /= 2) THEN
C * DATCOL CASE
              IF (NREFL == 1) IXRYTB = 0
            ELSE
C * DATCON CASE
              IXRYTB = IXRYT
            END IF
            IXRYT0 = - IXRYTB
            IF (ISG > 1) IXRYT0 = IXRYT0 + NINT (XRAYT(ISG - 1)
     1                             * 3600.0)
            ISW(3) = - IABS (ISW(3))
          END IF
          IXRAYT     = IXRYT + IXRYT0
          XRT        = IXRAYT / 3600.0
          XRAYT(ISG) = XRT
          C1         = CODE(1:1)
          C2         = CODE(2:2)
          C4         = CODE(4:4)
          IHPR(11)   = NREFL
          CALL PLA243 (1, NMBR, IPRT)
          IF (C1 == 'N') CALL PLA243 (2, NMBR, IPRT)
          IF (C1 == '?') CALL PLA243 (2, NMBR, IPRT)
          IF (C1 == '!') CALL PLA243 (2, NMBR, IPRT)
          IF (C1 == 'I') CALL PLA243 (3, NMBR, IPRT)
          IF (C4 == 'W') CALL PLA243 (4, NMBR, IPRT)
          IF (C4 == 'S') CALL PLA243 (5, NMBR, IPRT)
          IF (C4 == 'T') CALL PLA243 (6, NMBR, IPRT)
          IF (C2 == 'X' .OR. C2 == 'C') CALL PLA243 (9, NMBR, IPRT)
          IF (LX == LU11) IPRT = IPRT + 512
          IF (C1 == '?')  IPRT = IPRT + 1024
          IF (C1 == '!')  IPRT = IPRT + 2048
          ILT  = 1
          FSCF = 1.0
          IF (NPI < 0) THEN
            FSCF = BETA
            CALL PLA243 (8, NMBR, IPRT)
          END IF
C * LIST LOW ANGLE DATA (.LT. 5 DEG)
          IF (THETA < 5) IPRT = IPRT + 256
          XI = 0
          SI = 0
          IF (NPI /= 0) THEN
            RAT   = 2.0
            SCF   = FSCF * 100.0
            MINB  = MIN (IBGL, IBGR)
            MAXB  = MAX (IBGL, IBGR)
            IBTST = 0
            IF (MAXB > 3.0 * MINB .OR. MAXB > ISC) IBTST = 1
            IF (IBTST == 1) IPRT = IPRT + 4096
            IF (IPR(425) == 0) THEN
              GO TO 60
            ELSE IF (IPR(425) > 0) THEN
              GO TO 50
            END IF
            IBTST = - IBTST
   50       IF (IBTST /= 0) THEN
              BACK = MINB
              IF (IPR(425) == 1) THEN
                RAT = 4.0
              ELSE
                RAT = 5.0
                ISC = ISC + MAXB
              END IF
              GO TO 70
            END IF
C * CALCULATE I AND SIGMA(I)
   60       BACK = IBGL + IBGR
   70       XI = (ISC - RAT * BACK) * SCF / FLOAT (IABS (NPI))
            SI = (SQRT (FLOAT (ISC) + (RAT**2) * BACK)) * SCF /
     1            FLOAT (IABS (NPI))
          END IF
          IF (IPR(425) < 0) IHPR(12) = IHPR(12) + IABS (IBTST)
C * IDENTIFY NEGATIVE INTENSITIES (I < 2.5(SIGI))
          IF (XI + 2.5 * SI < 0) IPRT = IPRT + 128
          IF (XI > XIMX) XIMX = XI
          IF (SI > SIMX) SIMX = SI
          IF (C2 == 'D' .AND. XI > 5.0 * SI)
     1        CALL PLA243 (7, NMBR, IPRT)
C * TEST FOR SPIKE RESCAN CASES
          IF (IABS(NPI) > NPIPRE .AND. WIDTH < 0.0)
     1      CALL PLA243 (10, NMBR, IPRT)
          WRITE (LX) NREFL, IH, IK, IL, CODE, PSI, NPI, IBGL, ISC,
     1      IBGR, THETA, PHIK, OMK,RKAPPA, WIDTH, IXRAYT, IFRIDL,
     2      ILT, ISG, XI, SI, IPRT, IHPR(8), IBTST, FSCF
C * TEST FOR REFERENCE REFLECTION
          IF (C1 == 'I') THEN
            IHKL = IH * 40000 + IK * 200 + IL
            IRFX = IHPR(9)
            DO I = 1, IRFX
              IRF = MOD (IRF, IRFX) + I
              IX  = IRFY(IRF)
              IF (IX <= 0) GO TO 40
              IF (IORREF(IX, 4) == IHKL) GO TO 80
            END DO
            GO TO 40
   80       ICNT = MOD (ICNT, IRFX) + 1
            IF (ICNT /= IRF) THEN
              WRITE (LU9) ICNT, XRF(IRF), 0.0, XRT, ISG, IHPR(8)
              WRITE (LU6, 99980, IOSTAT = IOST) NREFL, ICNT
              GO TO 80
            ELSE
              WRITE (LU9) IRF, XI, SI, XRT, ISG, IHPR(8)
C * KEEP TRACK OF DYNAMICS OF THE REFERENCE REFLECTION
   90         XRFIRF = XRF(IRF)
              IF (XRFIRF <= 0.0) THEN
                XRF(IRF) = XI
                GO TO 90
              END IF
              XIS   = XI / XRFIRF
              XIMAX = MAX (XIS, XIMAX)
              XIMIN = MIN (XIS, XIMIN)
            END IF
          END IF
        END IF
C * TYPE 21 RECORD: NREFL,TEXT,IRADIUS,SLIT,APMIN,APMAX
      ELSE IF (KEY == 21) THEN
        IF (ISG > 0) THEN
          IF (NMBR(2) == 0) WRITE (LU6, 99982, IOSTAT = IOST) ISG
        END IF
C * MAKE SHURE THAT THE REFERENCE REFLECTION SET IS COMPLETE
  100   IF (IRFX > 0) THEN
          ICNT = MOD (ICNT, IRFX) + 1
          IF (ICNT /= 1) THEN
            WRITE (LU9) ICNT, XRF(ICNT), 0.0, XRT, ISG, IHPR(8)
            WRITE (LU6, 99980) NREFL, ICNT
            GO TO 100
          END IF
          IRF  = 0
          ICNT = 0
        END IF
        IF (IDCDOC /= 0) THEN
          CALL PLA244 (IDCDOC)
          IDCDOC = 1
        END IF
        READ (CARD, 99986, IOSTAT = IOST) COMPID
        IF (IOST > 0) GO TO 130
        JID = COMPID
        IF (IDCDOC == 0) CALL PLA244 (IDCDOC)
        IDCDOC = 1
        READ (CARD, 99995, IOSTAT = IOST) NR, TEXT, IRADIUS, SLIT,
     1    APMIN, APMAX
        IF (IOST > 0) GO TO 130
C * IDENTIFY DATCOL/DATCON CASE AND SCALING GROUP
        ISG = ISG + 1
        IF (ISG > IHPR(3)) CALL PLA245 (1)
        IF (NR <= 1) THEN
C * DATCOL CASE
          ISW(3) = 1
          DATC   = 'DATCOL'
        ELSE
C * DATCON CASE
          ISW(3) = 2
          DATC   = 'DATCON'
        END IF
C * INITIALISE FOR THIS SCALING GROUP
        CALL GEN097 (NMBR, 1, 10, 0)
C * TEST FOR MONOCHROMATOR
        IF (TEXT(27:29) == 'ZR ') IPR(424) = 0
C * TYPE 22 RECORD: DTHMIN,DTHMAX,DOMA,DOMB,APTA,APTB,ISCANT,SIGPRE,
C *                 SIGMA,NPIPRE,ITMAX,IDUMPF,NBALF,NFRIDL
      ELSE IF (KEY == 22) THEN
        READ (CARD, 99994, IOSTAT = IOST) DTHMIN, DTHMAX, DOMA, DOMB,
     1    APTA, APTB, ISCANT, SIGPRE, SIGMA, NPIPRE, ITMAX, NBALF,
     2    NBALF, NFRIDL
        IF (IOST > 0) GO TO 130
C * TYPE 23 RECORD: NPSIFL,NRPSI,PSIST,DELPSI,DVECT(1),DVECT(2),DVECT(3)
      ELSE IF (KEY == 23) THEN
        READ (CARD, 99993, IOSTAT = IOST) NEQFL, XNPSIFL, NRPSI, PSIST,
     1        DELPSI, (DVECT(I), I = 1, 3)
        IF (IOST > 0) GO TO 130
        IF (XNPSIFL == 'AZIMUT' .AND. NRPSI >= 36) THEN
          LX = LU11
        ELSE
          LX = LU10
        END IF
C * TYPE 24 RECORD: XSEQ,NFMS,ZZH,HMIN,HMAX,ZZK,KMIN,KMAX,ZZL,LMIN,LMAX
      ELSE IF (KEY == 24) THEN
        READ (CARD, 99992, IOSTAT = IOST) XSEQ, NFMS, IZZH, IHMIN,
     1        IHMAX, IZZK, KMIN, KMAX, IZZL, LMIN, LMAX
        IF (IOST > 0) GO TO 130
        IHPR(16) = MAX (IHPR(16), IHMAX, - IHMIN)
        IHPR(17) = MAX (IHPR(17), KMAX,  - KMIN)
        IHPR(18) = MAX (IHPR(18), LMAX,  - LMIN)
C * TYPE 26 RECORD: ICHKT,SIGMI,FADING,NORCHK,DANG,CON1,CON2,XRAYT
      ELSE IF (KEY == 26) THEN
        IRFD = 1
        READ (CARD, 99990, IOSTAT = IOST) ICHKT, SIGMI, FADING, NORCHK,
     1                                 DANG, CON1, CON2, IXRAYT
        IF (IOST > 0) GO TO 130
C * TYPE 31 RECORD: R(1,1),R(1,2),R(1,3),R(2,1)...............R(2,3)
      ELSE IF (KEY == 31) THEN
        IRFD = 0
        READ (CARD, 99989, IOSTAT = IOST) R(1, 1), R(1, 2), R(1, 3),
     1                                    R(2, 1), R(2, 2), R(2, 3)
        IF (IOST > 0) GO TO 130
C * TYPE 32 RECORD:   R(3,1),R(3,2),R(3,3),FLAM1,FLAM2,BETA/FF
      ELSE IF (KEY == 32) THEN
        READ (CARD, 99989, IOSTAT = IOST) R(3, 1), R(3, 2), R(3, 3),
     1                                    FLAM1, FLAM2, BETA
        IF (IOST > 0) GO TO 130
        DIF  = 0.0
        IPRM = IHPR(8)
        IF (IPRM < IP6) THEN
          IPR8 = IPRM + 1
          DO I = 1, 3
            DO J = 1, 3
              ORM(I, J, IPR8) = R(I, J)
              IF (IPR8 > 1) THEN
                DIF = DIF + ABS (ABS (ORM(I, J, IPRM)) - ABS (R(I, J)))
              END IF
            END DO
          END DO
          IF (IPR8 /= 1) THEN
            IF (DIF < 0.000005) GO TO 110
          END IF
          IHPR(8) = IPR8
        ELSE
          WRITE (LU7, 99981, IOSTAT = IOST)
          WRITE (LU6, 99981, IOSTAT = IOST)
        END IF
C * CALCULATE AVERAGE WAVELENGTH
  110   WL21 = (2.0 * FLAM1 + FLAM2) / 3.0
        WL11 = (FLAM1 + FLAM2) / 2.0
C * SET FILTER FACTOR TO 16.00 IN CASE OF BETA == 0 (OLD CONVENT.)
        IF (BETA < 0.1) BETA = 16.00
C * TYPE 33 RECORD: A, B, C, SIG(A), SIG(B), SIG(C)
      ELSE IF (KEY == 33) THEN
        READ (CARD, 99989, IOSTAT = IOST) (CELL(I), I = 1, 3),
     1                                    (CELL(I), I = 7, 9)
        IF (IOST > 0) GO TO 130
C * TYPE 34 RECORD: ALFA, BETA, GAMMA, SIG(ALFA), SIG(BETA), SIG(GAMMA)
      ELSE IF (KEY == 34) THEN
        READ (CARD, 99989, IOSTAT = IOST) (CELL(I), I = 4, 6),
     1                                    (CELL(I), I = 10, 12)
        IF (IOST > 0) GO TO 130
      END IF
      GO TO 40
C * END-OF-FILE REACHED.
  120 IF (IRFX > 0) THEN
        ICNT = MOD (ICNT, IRFX) + 1
        IF (ICNT /= 1) THEN
          WRITE (LU9) ICNT, XRF(ICNT), 0.0, XRT, ISG, IHPR(8)
          WRITE (LU6, 99980, IOSTAT = IOST) NREFL, ICNT
          GO TO 120
        END IF
      END IF
C * FIND OUT THE REQUIRED DYNAMICS IN THE SCALING PLOT
      IHPR(6) = NINT(MAX(XIMAX - 1.0, 1.0 - XIMIN) * 100) * 2 + 10
      IF (NMBR(2)  == 0) WRITE (LU6, 99982, IOSTAT = IOST) ISG
      IF (NMBR(12) == 0) CALL PLA245 (3)
      IF (IHPR(9)  == 0) IPR(428) = 1
      CALL PLA244 (IDCDOC)
      CALL GEN097 (IPR(IHPR(9) + 371), 1, 9 - IHPR(9), 0)
      RETURN
  130 WRITE (LU6, 99999, IOSTAT = IOST) NCARD
      WRITE (LU6, FORMC, IOSTAT = IOST) KEY, CARD
C * CALL EXIT/STOP
      CALL GEN127 (' ')
99999 FORMAT (/, 'Fatal Error in CAD4-data : Offending Line =', I6, /)
99998 FORMAT (I2)
99997 FORMAT (2X, 3I3, A)
99996 FORMAT (I6, F8.3, 3F9.3, F7.3, I7, I3)
99995 FORMAT (I6, A, I4, F4.1, F4.1, F4.1)
99994 FORMAT (2F6.2, 4F5.2, I2, 2F6.3, I2, I4, 3I2)
99993 FORMAT (I2, 1X, A, I5, F7.2, F7.2, 3(F10.6))
99992 FORMAT (1X, A, 2X, A, I5, 9I5)
99990 FORMAT (I7, F7.3, F6.3, I5, F6.3, F10.7, F10.7, I7)
99989 FORMAT (2(2X, 3F9.6))
99988 FORMAT (I6, 3I5, 1X, A, F7.0, I4, I6, I7, I6)
99986 FORMAT (6X, A)
99985 FORMAT (I3)
99984 FORMAT (':: DATA FOR REFLECTION ',I5,' INCOMPLETE AND SKIPPED'/)
99983 FORMAT (':: WARNING: DISCONTINUITY AT REFLECTION NR:',I6,/)
99982 FORMAT (':: DATA SET NR.', I3, ' DOES NOT CONTAIN NORMAL',
     1  ' REFLECTIONS'/)
99981 FORMAT (19X, 'REORIENTATION MATRIX SKIPPED')
99980 FORMAT ('Reference reflection missing at reflection',
     1         I6,/,'Zero weight reflection substituted for r.r.',I3)
      END SUBROUTINE PLA248
 
      SUBROUTINE PLA249 (IRF, ISGR)
C * HELENA (10)
      USE files
      USE parameters
      USE cggt
      USE helena
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: IV
      INTEGER       :: IRF
      INTEGER       :: IPN
      INTEGER       :: IPX
      INTEGER       :: NST
      INTEGER       :: NUMB
      INTEGER       :: IRFX
      INTEGER       :: ISGR
      INTEGER, SAVE :: IXRT
      INTEGER       :: NOGR
      INTEGER       :: NSGR
      REAL, SAVE    :: VS
      REAL          :: XX
      REAL          :: YY
      REAL          :: XRT
      REAL          :: SCF
      REAL, SAVE    :: XPL
      REAL, SAVE    :: YPL
      REAL, SAVE    :: SCFX
      CHARACTER(len=7)  :: NQ
      CHARACTER(len=46) :: PLTXT1
      CHARACTER(len=36) :: PLTXT2
      CHARACTER(len=7)  :: PLTXT3
      CHARACTER(len=20) :: PLTXT4
      NSGR = 0
      HORS = 33.3333
      VERT = 25.0
      CALL GEN040 (ISG, NQ, IPX)
   10 PLTXT1 = 'HELENA....'//TEXT
      PLTXT2 = DATIJD//' ,SET NR :'//NQ(1:6)
      PLTXT3 = 'PERCENT'
      PLTXT4 = 'HOURS XRAY EXP. TIME'
      IF (IRF < ISW(2)) THEN
C * ISSUE AN ENDPLOT
        CALL GGIP (0.0, 0.0, 0.0, -1)
C * WHAT NEXT ?
        CALL PLA012 (4, 1)
C * REFRESH
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
          GO TO 10
        ELSE IF (IGGT(1:1) == '!') THEN
          CALL PLA280 ('NEXT')
        END IF
        CALL GEN038 (IGGT, 1, 80)
        RETURN
      ELSE IF (IRF > ISW(2)) THEN
        GO TO 20
      END IF
      IF (ISGR <= 1) THEN
        SCFX = HORS / XRAYT(ISG)
        IXRT = IFIX (XRAYT(ISG))
C * NAMPLT
        IF (LU15 == 1) THEN
          CALL GGIP (-999.0, 0.0, 0.0, -2)
        ELSE
          CALL GGIP (-999.0, 0.0, 0.0, 3)
        END IF
        CALL GGIP (HORS, VERT, 0.0, 1)
        CALL GGIP (0.0, 0.0, 0.0, 3)
C * NEWPEN
        CALL GGIP (0.0, 1.0, 0.0, 0)
        DO I = 1, IXRT
          XX = (I - 1) * SCFX
          YY = 0.5
          IF (MOD (I, 10) == 0) YY = 1.0
          CALL GGIP (XX, 0.0, 0.0, 2)
          CALL GGIP (XX,  YY, 0.0, 2)
          CALL GGIP (XX, 0.0, 0.0, 2)
        END DO
        CALL GGIP (HORS, 0.0, 0.0, 2)
        YY = 0.0
        IV = IHPR(6)
        VS = VERT / IV
        DO I = 1, IV
          XX = HORS - 0.2
          IF (MOD (I - IV / 2, 10) == 0) XX = HORS - 0.6
          YY = YY + VS
          CALL GGIP (HORS, YY, 0.0, 2)
          CALL GGIP (XX,   YY, 0.0, 2)
          CALL GGIP (HORS, YY, 0.0, 2)
        END DO
        CALL GGIP (0.0, VERT, 0.0, 2)
        YY = VERT
        DO I = 1, IV
          XX = 0.3
          IF (MOD (I - IV / 2, 10) == 0) XX = 0.60
          YY = YY - VS
          CALL GGIP (0.0, YY, 0.0, 2)
          CALL GGIP (XX,  YY, 0.0, 2)
          CALL GGIP (0.0, YY, 0.0, 2)
        END DO
        CALL GGIP (0.0, 0.0, 0.0, 2)
C * PLOT IDENTIFICATION AND TEXT
        XX = 1.0
        YY = VERT - 1.0
        CALL PLA439 (0.0, PLTXT1, 46, 0.5, -1, 2, XX, YY)
        XX = 1.0
        YY = 1.3
        CALL PLA439 (0.0, PLTXT2, 36, 0.5, -1, 2, XX, YY)
        XX = 1.4
        YY = VERT - 5.0
        CALL PLA439 (90.0, PLTXT3, 7, 0.5, -1, 2, XX, YY)
        XX = HORS - 11.0
        YY = 1.3
        CALL PLA439 (0.0, PLTXT4, 20, 0.5, -1, 2, XX, YY)
        WRITE (BCD, '(''Scale Degree ='', I3)', IOSTAT = IOST) IPR(446)
        CALL PLA439 (0.0, BCD, 17, 0.5, 1, 2, 7.5, VERT - 3.0)
      END IF
      CALL GGIP (0.0, 0.0, 0.0, 3)
C * SET COLOR
   20 CALL GGIP (0.0, FLOAT (IRF), 0.0, 0)
      IF (ISGR <= 1) THEN
        XPL = 2.3
        YPL = VERT - 1.5 - IRF * 0.7
        CALL PLA439 (0.0, CHAR (ICHAR ('A') - 1 + IRF), 2, 0.3,
     1              -1, 0, XPL, YPL)
        IRFX = IRFY(IRF)
        DO I = 1, 3
          XPL  = 2.3 + 1.0 * I
          IPX  = 0
          NUMB = 0
          IF (IRFX > 0) NUMB = IORREF(IRFX, I)
          CALL GEN040 (NUMB, NQ, IPX)
          CALL PLA439 (0.0, NQ, 3, 0.3, -1, 2, XPL, YPL)
        END DO
      END IF
      IF (IRF == ISW(2)) NSGR = MOD (ISGR, 10)
      NST = IRFZ(IRF, ISGR)
      DO I = 1, NST
        XX = X(I) * SCFX
        YY = (F(I) / P(1, IRF, 1) - 1.0) * VS * 100.0 + VERT / 2.0
        CALL PLA439 (0.0, CHAR (ICHAR ('A') - 1 + IRF), 1, 0.3,
     1              -1, 0, XX, YY)
        IF (IRF == ISW(2)) THEN
          CALL PLA439 (0.0, CHAR (ICHAR ('0') + NSGR), 1, 0.3, -1, 0,
     1                 XX, 2.8)
          NOGR = MOD(IONR(I) - 1, 10)
          CALL PLA439 (0.0, CHAR (ICHAR ('0') + NOGR), 1, 0.3, -1, 0,
     1                 XX, 2.3)
        END IF
      END DO
      DO I = 1, NST
        IPN = 2
        IF (I == 1) IPN = 3
        XRT = X(I)
        CALL PLA246 (SCF, IRF, ISGR, XRT)
        XX = X(I) * SCFX
        YY = (1.0 / SCF - 1.0) * VS * 100.0 + VERT / 2.0
        CALL GGIP (XX, YY, 0.0, IPN)
      END DO
      CALL GGIP (0.0, 0.0, 0.0, 3)
      RETURN
      END SUBROUTINE PLA249
C STRIP_END
      MODULE map
      SAVE
