      INTEGER, PARAMETER :: NCT5 = 2000
      INTEGER, PARAMETER :: NCT6 = 100
      INTEGER, PARAMETER :: NCT7 = NCT6 + 1
      INTEGER, PARAMETER :: NCT8 = 5000
      INTEGER, PARAMETER :: NCT9 = 2000
      INTEGER :: NN
      INTEGER :: NS
      INTEGER :: NT
      INTEGER :: NE
      INTEGER :: MX
      INTEGER :: MY
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IV
      INTEGER :: IC
      INTEGER :: L7
      INTEGER :: N7
      INTEGER :: NST
      INTEGER :: NAX
      INTEGER :: NAT
      INTEGER :: JVX
      INTEGER :: JVY
      INTEGER :: INX
      INTEGER :: IXY
      INTEGER :: NS7
      INTEGER :: NE7
      INTEGER :: NXP
      INTEGER :: NXM
      INTEGER :: NYP
      INTEGER :: NYM
      INTEGER :: IHM
      INTEGER :: IKM
      INTEGER :: ILM
      INTEGER :: MODE
