            GN(I, J) = G(I, J)
            IF (ABS (G(I, J)) < 0.00006) G(I, J) = 0.0
            IF (MC == 0 .AND. J > I .AND. G(I, J) > 0.0)
     1        MC = J + 2 * I - 3 - I / 3
          END DO
        END DO
        IF (MC /= 0) THEN
C * TRANSFORMATION OF MATRIX AD AND METRIC TENSOR G
          DO I = 1, 4
            DO J = 1, 4
              G(I, J) = 0.0
              AD(I, J) = 0.0
              DO K = 1, 4
                AD(I, J) = AD(I, J) + A(I, K) * PP(K, J, MC)
                DO L = 1, 4
                  G(I, J) = G(I, J) +
     1                      GN(K, L) * PP(K, I, MC) * PP(L, J, MC)
