                            IF (I /= 3) E(I, J) = - E(I, J)
     1                                            * SIGN (1.0, GV(1, 3))
                          END DO
                        END DO
                      ELSE IF (ISYS > 3) THEN
                        GO TO 10
                      ELSE
C * ORTHORHOMBIC CASE
                        IF (GV(1, 1) > GV(2, 2)) IZ = IZ + 1
                        IF (GV(1, 1) > GV(3, 3)) IZ = IZ + 2
                        IF (GV(2, 2) > GV(3, 3)) IZ = IZ + 4
                        DO L = 1, 3
                          DO M = 1, 3
                            E(L, M) = TR(L, M, MVV(IZ))
                          END DO
                        END DO
                        IF (NBR > 1 .AND. NBR < 5)
     1                    NBR = 4 - IZ / 3
                      END IF
                    ELSE
C * TRICLINIC CASE, SEARCH FOR A BASIS OF SHORTEST VECTORS
                      DO I = 1, 7
                        DO J = 1, 7
