                      ZW2 = GS(MQ(2), MQ(2))
                      ZW3 = GS(MQ(3), MQ(3))
                      IF (IV(MQ(1), MQ(2)) == MQ(3))
     1                    ZW3 = GS(MQ(4), MQ(4))
                      DO I = 1, 5
                        ID = MQ(I)
                        IF (ZW1 >= GS(ID, ID)) THEN
                          DO J = I, 6
                            JD = MQ(J)
                            IF (J /= I .AND. ZW2 >= GS(JD, JD)) THEN
                              DO K = J, 7
                                KD = MQ(K)
                                IF (K /= J .AND. ZW3 >= GS(KD, KD)
     1                            .AND. KD /= IV(ID, JD)) THEN
                                  IF (O(ID, JD) + O(JD, KD)
     1                                        + O(ID, KD) >= ZW4) THEN
                                    KJ(1) = ID
                                    KJ(2) = JD
                                    KJ(3) = KD
                                    ZW4   = O(ID, JD) + O(ID, KD)
     1                                    + O(JD, KD)
                                  END IF
                                END IF
                              END DO
                            END IF
                          END DO
                        END IF
                      END DO
C * STANDARDIZATION
                      DO M = 1, 3
                        DO L = 1, 3
                          GV(M, L) = GS(KJ(M), KJ(L))
                          GN(M, L) = 0.0
                          IF (GV(M, L) /= 0.0) GN(M, L) =
     1                        GV(M, L) / ABS (GV(M, L))
                          DO J = 1, 3
                            AV(L, M) =
     1                      AV(L, M) + A(L, J) * INC(J, KJ(M))
                          END DO
                        END DO
                      END DO
                      N = INT (14.5 + GN(1, 2) + 3.0 * GN(1, 3)
     1                  + 9.0 * GN(2, 3))
                      IF (GV(1, 1) == GV(2, 2) .AND.
     1                   ABS (GV(2, 3)) > ABS (GV(1, 3))) IZ = IZ + 1
                      IF (GV(3, 3) == GV(2, 2) .AND.
     1                   ABS (GV(1, 3)) > ABS (GV(1, 2))) IZ = IZ + 2
                      IF (GV(1, 1) == GV(3, 3) .AND.
     1                   ABS (GV(2, 3)) > ABS (GV(1, 2))) IZ = IZ + 4
                      DO I = 1, 3
                        DO J = 1, 3
                          E(I, J) = 0.0
                          DO K = 1, 3
                            E(I, J) = E(I, J) + TR(I, K, 23 + Q(N))
     1                              * TR(K, J, NVV(IZ))
                          END DO
                        END DO
                      END DO
                    END IF
                    DO I = 1, 3
                      DO J = 1, 3
                        A(I, J)  = AV(I, J)
                        GN(I, J) = GV(I, J)
                      END DO
                    END DO
                    DO I = 1, 3
                      DO J = 1, 3
                        AV(I, J) = A(I, 1) * E(1, J) + A(I, 2) * E(2, J)
     1                           + A(I, 3) * E(3, J)
                        GV(I, J) = 0.0
                        DO K = 1, 3
                          DO L = 1, 3
                            GV(I, J) = GV(I, J)
     1                               + GN(K, L) * E(L, J) * E(K, I)
                          END DO
                        END DO
                      END DO
                    END DO
                    IF (ISYS == 2 .AND. GV(1, 3) > 0.0) THEN
                      DO I = 1, 3
                        AV(I, 3) = - AV(I, 3)
                      END DO
                      GV(1, 3) = - GV(1, 3)
                      GV(3, 1) =   GV(1, 3)
                    END IF
C * INVERSION OF AV
   10               DO I = 1, 2
                      II = I + 1
                      DO J = II, 3
                        N       = 6 - I - J
                        A(N, N) = AV(I, I) * AV(J, J)
     1                          - AV(I, J) * AV(J, I)
                        A(J, I) = AV(N, I) * AV(J, N)
     1                          - AV(N, N) * AV(J, I)
                        A(I, J) = AV(N, J) * AV(I, N)
     1                          - AV(N, N) * AV(I, J)
                      END DO
                    END DO
                    ZW1 = A(1, 1) * AV(1, 1) + A(1, 2) * AV(2, 1)
     1                  + A(1, 3) * AV(3, 1)
C * PREPARATION OF OUTPUT
                    DO I = 1, 3
                      DO J = 1, 3
                        AV(I, J) = AV(I, J) * SIGN (1.0, ZW1)
                        IF (IS == 1) THEN
                          AW(I, J) = AV(I, J)
                          GW(I, J) = GV(I, J)
                        END IF
                        A(J, I) = A(J, I) / ABS (ZW1)
                      END DO
                      AC(I) = SQRT (GV(I, I))
                      J     = I + 1 - 3 * (I / 3)
                      ZW    = GV(I, J) / SQRT (GV(I, I) * GV(J, J))
                      AC(9 - I - J) = 57.29578
     1                              * ATAN2 (SQRT (1.0 - ZW * ZW), ZW)
                    END DO
                    IF (ISYS == 2) THEN
                      XM = GV(1, 1) / GV(2, 2)
                      YM = GV(3, 3) / GV(2, 2)
                      ZM = XM + YM + 2.0 * GV(1, 3) / GV(2, 2)
                      IF (NBR /= 1) THEN
                        ZW = GV(3, 3) + FLOAT (NBR / 4)
     1                     * (GV(1, 1) - GV(3, 3))
     2                     + FLOAT (NBR / 6) * (GV(3, 3)
     3                     + GV(1, 3) * 2.0)
                        ZM = (GV(1, 1) + FLOAT ((NBR / 4) - (NBR / 6)) *
     1                       (GV(3, 3) - GV(1, 1))) / ZW
                        YM = GV(2, 2) / ZW
                        XM = ((GV(1, 1) + GV(3, 3) + GV(1, 3) * 2.0) *
     1                       FLOAT ((NBR / 2) - (NBR / 4)) *
     2                       FLOAT (1 - (NBR / 6))
     2                     + FLOAT (NBR / 6) * GV(3, 3)) / ZW
                      END IF
                    END IF
                    IF (IS == 1) THEN
   20                 CALL PLA015 (0, 39)
C * WHAT NEXT ?
                      CALL PLA012 (1, 1)
                      CALL GEN020 (1, IGGT, 1, 80)
                      IF (IGGT(1:4) == 'PLOT') THEN
                        GO TO 20
                      ELSE IF (IGGT(1:4) == 'EXIT' .OR.
     1                         IGGT(1:1) == 'N') THEN
                        CALL GEN038 (IGGT, 1, 80)
                        RETURN
                      END IF
                      CALL PLA262 (0)
                      CALL GGIP (HORS, VERT, 0.0, 1)
                      WRITE (PRBUF, 99993, IOSTAT = IOST)
     1                  NCP, IC, IST, Y(ISYS), HT(NBR)
                      WRITE (LU, 99987, IOSTAT = IOST) PRBUF(1:80)
                      VRT = VERT - 0.7
                      CALL PLA439 (0.0, PRBUF, 80, 0.40, 5 + IGBL(68),
     1                             2, 0.2, VRT)
                      VRT = VRT - 0.2
                    END IF
                    ISJ = IS - 1
                    IF (IS /= 1) THEN
                      WRITE (PRBUF, 99991, IOSTAT = IOST)
     1                  ISJ, Y(ISYS), HT(NBR)
                      WRITE (LU, 99988, IOSTAT = IOST) PRBUF(1:80)
                      VRT = VRT - 0.7
                      CALL PLA439 (0.0, PRBUF, 80, 0.40, 3, 2, 0.2, VRT)
                    END IF
                    IF (ISYS == 2) THEN
                      WRITE (PRBUF, 99989, IOSTAT = IOST) XM, YM, ZM
                      WRITE (LU, 99988, IOSTAT = IOST) PRBUF(1:80)
                    END IF
                    IF ((ISYS /= 1 .AND. ISYS /= 5 .AND.
     1                (ABS (AC(4) - 90.0) >= PAR(381) .OR.
     2                 ABS (AC(6) - 90.0) >= PAR(381))) .OR.
     3                 (ISYS > 2 .AND. ABS (AC(5) - 90.0)
     4                 >= PAR(381))
     5                 .OR. (ISYS == 5 .AND. (ABS (AC(6) - 120.0) .GE.
     6                 PAR(381) .OR. ABS (AC(4) - 90.0) >= PAR(381)))
     7                 .OR. (ISYS > 3 .AND. ABS (AC(1) - AC(2)) .GE.
     8                 PAR(382)) .OR. (ISYS == 6
     9                .AND. (ABS (AC(1) - AC(3)) >= PAR(382) .OR.
     *                 ABS(AC(2) - AC(3)) >= PAR(382)))) THEN
                      WRITE (PRBUF, 99990, IOSTAT = IOST)
     1                  (AC(I), I = 1, 6)
                      VRT = VRT - 0.40
                      CALL PLA439 (0.0, PRBUF, 80, 0.30, 2, 2, 0.2, VRT)
                      WRITE (LU, 99988, IOSTAT = IOST) PRBUF(1:80)
                      IF (INO /= 1) GO TO 30
                    END IF
                    WRITE (PRBUF, 99996, IOSTAT = IOST)
     1                (AC(I), I = 1, 3)
                    VRT = VRT - 0.7
                    CALL PLA439 (0.0, PRBUF, 80, 0.40, 1, 2, 0.2, VRT)
                    WRITE (LU, 99988, IOSTAT = IOST) PRBUF(1:80)
                    WRITE (PRBUF, 99995, IOSTAT = IOST)
     1                (AC(I), I = 4, 6)
                    VRT = VRT - 0.55
                    CALL PLA439 (0.0, PRBUF, 80, 0.40, 1, 2, 0.2, VRT)
                    WRITE (LU, 99987, IOSTAT = IOST) PRBUF(1:80)
                    WRITE (PRBUF, 99994, IOSTAT = IOST)
                    VRT = VRT - 0.7
                    CALL PLA439 (0.0, PRBUF, 80, 0.40, 5 + IGBL(68),
     1                           2, 0.2, VRT)
                    WRITE (LU, 99988, IOSTAT = IOST) PRBUF(1:80)
                    DO I = 1, 3
                      WRITE (PRBUF, 99992, IOSTAT = IOST)
     1                  (GV(I, J), J = 1, 3),
     2                  (AV(I, K), K = 1, 3), (A(I, L), L = 1, 3)
                      WRITE (LU, 99987, IOSTAT = IOST) PRBUF(1:80)
                      VRT = VRT - 0.55
                      CALL PLA439 (0.0, PRBUF, 80, 0.40, 1, 2, 0.2, VRT)
                    END DO
   30               DO I = 1, 13
                      IF (IS == 1 .AND. 10 * ISYS + NBR == IDT(I))
     1                    IK = I
                    END DO
                    IF (IK == 7 .AND. IC == 6) IK = 14
                  END DO
   40           CONTINUE
              END IF
            END DO
          END DO
        END DO
      END DO
      IPR(772) = 0
      CALL PLA015 (0, 39)
C * WHAT NEXT ?
      CALL PLA012 (1, 1)
      RETURN
99999 FORMAT ('Delaunay Cell Reduction [Tol-Axis =', F5.2,
     1        ', Tol-Angle =', F5.2, ']')
99998 FORMAT ('See: H. Zimmermann & H. Burzlaff, ',
     1        'Z. fur Krist. (1985) 170, 241-246')
99997 FORMAT ( 'INPUT CELL:   ', A, 6F9.3)
99996 FORMAT (9X, 'a =', F9.3, 11X, 'b =', F9.3, 11X, 'c =', F9.3)
99995 FORMAT ( 5X, 'alpha =', F9.3, 8X, 'beta =', F9.3, 7X,
     1       'gamma =', F9.3)
99994 FORMAT (7X, 'Metric Tensor', 12X, 'Transf.-Matrix', 6X,
     1        'Inverse Matrix')
99993 FORMAT (2X, ' Proposal', I3, '   Delaunay Case',
     1        I3, 4X, 'Cycle', I3, 6X, 'Lattice Type: ', 2A)
99992 FORMAT (3(F9.2), 2X, 3(F6.2), 2X, 3(F6.2))
99991 FORMAT (4X, 'Subgroup Cell No.', I3, 24X, 'Lattice Type: ', 2A)
99990 FORMAT (5X, 'Out of Range [', 6F9.3, ']')
99989 FORMAT (' Reduced Monoclinic Lattice Coordinates:',
     1        3X, 'xm = ', F6.3, 1X, 'ym = ', F6.3, 1X, 'zm = ', F6.3)
99988 FORMAT (/, A)
99987 FORMAT (A)
99986 FORMAT (A, /, 80('='), /)
99985 FORMAT (A, /)
      END SUBROUTINE PLA265
 
      SUBROUTINE PLA266 (N)
C * CELL REDUCTION, SEE KRIVY & GRUBER, ACTA CRYST (1976), A32, 297-298)
      USE parameters
      USE plato
      USE latice
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      REAL :: DET
      REAL,  DIMENSION(3, 3) :: YUNK
C * GET LATTICE TYPE = NLT (P, A, B, C, F, I, R, X)
C * GET TRANSFORMATION MATRIX TO PRIMITIVE LATTICE
      IF (N == 1) THEN
        L = IPR(241)
      ELSE
        L = 128
      END IF
      DO J = 1, 3
        DO K = 1, 3
          TRNS(J, K) = TRNSX(J, K, L)
        END DO
      END DO
C * TRANSFORM METRICAL MATRIX
      CALL GEN001 (1, TRNS, AA, DUMV)
C * KRIVY & GRUBER
      CALL PLA267 (DUMV, TRNS, PAR(440))
C * AVOID TRIVIAL TRANSFORMATIONS
C * SAVE REDUCED CELL (NIGGLI) PARAMETERS
      CALL GEN025 (DUMV, PAR(151), 1)
C * RECOVER CELL PARAMETERS FROM METRIC
      CALL GEN026 (-1, DUMV, PAR(123))
C * TRANSPOSE INPUT TO REDUCED CELL TRANSFORMATION MATRIX
      CALL GEN005 (TRNS, YUNK)
C * COPY MATRIX
      CALL GEN052 (YUNK, TRNS)
C * GET INVERTED MATRIX
      CALL GEN003 (TRNS, TRNSM1, DET, 0)
      PAR(99) = PAR(98) * DET
C * DESCRIBE THE REDUCED DIRECT AND RECIPROCAL CELLS BY THEIR CARTESIAN
C * COORDINATES ADIR AND AINV.
      CALL GEN044 (PAR(123), ADIR, 1)
C * INVERT
      CALL GEN003 (ADIR, AINV, DET, 0)
      RETURN
      END SUBROUTINE PLA266
 
      SUBROUTINE PLA267 (DUMV, TRNS, SCALE)
C * CELL REDUCTION, SEE KRIVY & GRUBER, ACTA CRYST (1976), A32, 297-298)
      USE latice
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IA
      INTEGER :: IB
      INTEGER :: IC
      INTEGER :: IETA
      INTEGER :: IKSI
      INTEGER :: IZETA
      INTEGER :: NLOOP
      REAL :: SCL
      REAL :: SCALE
      REAL :: DUMVMX
      REAL, DIMENSION(3, 3) :: TRNS
      REAL, DIMENSION(3, 3) :: DUMV
      REAL, DIMENSION(3, 3) :: YUNK
C * AVOID OVERFLOW
      DUMVMX = DUMV(1, 1)
      DUMVMX = MAX (DUMVMX, DUMV(2, 2))
      DUMVMX = MAX (DUMVMX, DUMV(3, 3))
      SCL    = SCALE
      DO I = 1, 4
        IF (DUMVMX * SCL > 5000000.0) THEN
          SCL = SCL / 10.0
        ELSE
          EXIT
        END IF
      END DO
      IA    = NINT (DUMV(1, 1) * SCL)
      IB    = NINT (DUMV(2, 2) * SCL)
      IC    = NINT (DUMV(3, 3) * SCL)
      IKSI  = NINT (2.0 * SCL * DUMV(2, 3))
      IETA  = NINT (2.0 * SCL * DUMV(1, 3))
      IZETA = NINT (2.0 * SCL * DUMV(1, 2))
C * LIMIT NUMBER OF ITERATION LOOPS
      DO NLOOP = 1, 25
C * REDUCTION STEP 1
        IF ((IA > IB) .OR. ((IA == IB) .AND.
     1      (IABS (IKSI) > IABS (IETA)))) THEN
          CALL GEN014 (IA, IB)
          CALL GEN014 (IKSI, IETA)
          IETA = - IETA
          IKSI = - IKSI
          CALL GEN004 (TRNSX(1, 1, 8), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
        END IF
C * REDUCTION STEP 2
        IF ((IB > IC) .OR. ((IB == IC) .AND.
     1     (IABS (IETA) > IABS (IZETA)))) THEN
          CALL GEN014 (IB, IC)
          CALL GEN014 (IETA, IZETA)
          IETA  = - IETA
          IZETA = - IZETA
          CALL GEN004 (TRNSX(1, 1, 9), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
          CYCLE
        END IF
C * REDUCTION STEP 3
        IF (FLOAT (IKSI) * FLOAT (IETA) * FLOAT (IZETA) > 0.0) THEN
          TRNSX(1, 1, 10) = ISIGN (1, IKSI)
          TRNSX(2, 2, 10) = ISIGN (1, IETA)
          TRNSX(3, 3, 10) = ISIGN (1, IZETA)
          IKSI            = IABS (IKSI)
          IETA            = IABS (IETA)
          IZETA           = IABS (IZETA)
          CALL GEN004 (TRNSX(1, 1, 10), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
C * REDUCTION STEP 4
        ELSE
          TRNSX(1, 1, 11) = - ISIGN (1, IKSI)
          TRNSX(2, 2, 11) = - ISIGN (1, IETA)
          TRNSX(3, 3, 11) = - ISIGN (1, IZETA)
          IF (IKSI == 0)
     1       TRNSX(1, 1, 11) = TRNSX(2, 2, 11) * TRNSX(3, 3, 11)
          IF (IETA == 0)
     1       TRNSX(2, 2, 11) = TRNSX(1, 1, 11) * TRNSX(3, 3, 11)
          IF (IZETA == 0)
     1       TRNSX(3, 3, 11) = TRNSX(1, 1, 11) * TRNSX(2, 2, 11)
          IKSI  = - IABS (IKSI)
          IETA  = - IABS (IETA)
          IZETA = - IABS (IZETA)
          CALL GEN004 (TRNSX(1, 1, 11), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
        END IF
C * REDUCTION STEP 5
        IF ((IABS (IKSI) > IB) .OR. ((IKSI == IB) .AND.
     1    (2 * IETA < IZETA)) .OR. ((IKSI == -IB) .AND.
     2    (IZETA < 0))) THEN
          TRNSX(3, 2, 12) = - ISIGN (1, IKSI)
          IC   = IB   + IC - IKSI * ISIGN (1, IKSI)
          IETA = IETA - IZETA * ISIGN (1, IKSI)
          IF (IABS (IETA) == 1) IETA = 0
          IKSI = IKSI - 2 * IB * ISIGN (1, IKSI)
          IF (IABS (IKSI) == 1) IKSI = 0
          CALL GEN004 (TRNSX(1, 1, 12), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
          CYCLE
        END IF
C * REDUCTION STEP 6
        IF ((IABS (IETA) > IA) .OR. ((IETA == IA) .AND.
     1    (2 * IKSI < IZETA)) .OR. ((IETA == -IA) .AND.
     2    (IZETA < 0))) THEN
          TRNSX(3, 1, 13) = - ISIGN (1, IETA)
          IC   = IA + IC - IETA * ISIGN (1, IETA)
          IKSI = IKSI - IZETA * ISIGN (1, IETA)
          IETA = IETA - 2 * IA * ISIGN (1, IETA)
          CALL GEN004 (TRNSX(1, 1, 13), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
          CYCLE
        END IF
C * REDUCTION STEP 7
        IF ((IABS (IZETA) > IA) .OR. ((IZETA == IA) .AND.
     1    (2 * IKSI < IETA)) .OR. ((IZETA == -IA) .AND.
     2    (IETA < 0))) THEN
          TRNSX(2, 1, 14) = - ISIGN (1, IZETA)
          IB    = IA + IB - IZETA * ISIGN (1, IZETA)
          IKSI  = IKSI - IETA * ISIGN (1, IZETA)
          IZETA = IZETA - 2 * IA * ISIGN (1, IZETA)
          CALL GEN004 (TRNSX(1, 1, 14), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
          CYCLE
        END IF
C * REDUCTION STEP 8
        IF ((IKSI + IETA + IZETA + IA + IB < 0) .OR.
     1     ((IKSI + IETA + IZETA + IA + IB == 0) .AND.
     2      (2 * (IA + IETA) + IZETA > 0))) THEN
          IC   = IA + IB + IC + IKSI + IETA + IZETA
          IKSI = 2 * IB + IKSI + IZETA
          IETA = 2 * IA + IETA + IZETA
          CALL GEN004 (TRNSX(1, 1, 15), TRNS, YUNK)
          CALL GEN052 (YUNK, TRNS)
          CYCLE
        END IF
        EXIT
      END DO
      DUMV(1, 1) = IA / SCL
      DUMV(2, 2) = IB / SCL
      DUMV(3, 3) = IC / SCL
      DUMV(1, 2) = IZETA * 0.5 / SCL
      DUMV(1, 3) = IETA  * 0.5 / SCL
      DUMV(2, 3) = IKSI  * 0.5 / SCL
      DUMV(3, 2) = DUMV(2, 3)
      DUMV(3, 1) = DUMV(1, 3)
      DUMV(2, 1) = DUMV(1, 2)
      RETURN
      END SUBROUTINE PLA267
 
      SUBROUTINE PLA268 (IAT, JAT, MODE, DASH)
C * BOND IN SCRATCH VOID LIST MANAGEMENT
C * MODE =  1  : ADD BOND TO LIST
C * MODE = -1  : DELETE BOND FROM LIST
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IA
      INTEGER :: JA
      INTEGER :: NA
      INTEGER :: NB
      INTEGER :: NC
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: IPP
      INTEGER :: JPP
      INTEGER :: NAK
      INTEGER :: NAN
      INTEGER :: MODE
      INTEGER :: IHAT
      INTEGER :: JHAT
      INTEGER :: METI
      INTEGER :: METJ
      INTEGER :: NANB
      REAL :: DASH
      REAL :: DASH0
      REAL :: XBND
      DASH0 = DASH
      NA    = IPR(298)
C * GET NUMBER OF BONDS IN BOND ARRAY
      NB = IPR(131)
      NC = NB
      I  = IAT
      J  = JAT
      N  = 0
      IF (I > J) CALL GEN014 (I, J)
C * TEST FOR PREVIOUS OCCURRENCE OF THIS BOND
      IF (NB > 0) THEN
        DO K = 1, NB
          NAK = NA + K * 3
          IA  = NINT (VOID(NAK - 2))
          JA  = NINT (VOID(NAK - 1))
          IF (I == IA .AND. J == JA) THEN
C * BOND FOUND
            IF (MODE == -1) THEN
C * REPLACE THIS ENTRY WITH THE LAST ENTRY FROM THE LIST
              NANB          = NA + NB * 3
              IF (NANB /= NAK) THEN
                VOID(NAK - 2) = VOID(NANB - 2)
                VOID(NAK - 1) = VOID(NANB - 1)
                VOID(NAK)     = VOID(NANB)
              END IF
              NC = NC - 1
            ELSE
              N = K
            END IF
            EXIT
          END IF
        END DO
      END IF
      IF (MODE > 0) THEN
        IF (N == 0) THEN
          NC = NC + 1
          N  = NC
        END IF
C * NORMAL BOND RADIUS CODE
        XBND = 1.0
C * TO METAL BOND RADIUS CODE
        CALL GEN048 (-1, IFG(1, I), 19, METI)
        CALL GEN048 (-1, IFG(1, J), 19, METJ)
        IF (METI == 1 .OR. METJ == 1) XBND = 5.0
C * TO H BOND RADIUS CODE
        CALL GEN048 (-1, IFG(1, I), 7, IHAT)
        CALL GEN048 (-1, IFG(1, J), 7, JHAT)
        IF (IHAT == 1 .OR. JHAT == 1) XBND = 3.0
        IF (DASH0 < 2.0) THEN
C * DISORDER DETAILS
          CALL GEN048 (-8, IFG(2, I), 1, IPP)
          CALL GEN048 (-8, IFG(2, J), 1, JPP)
          IPP = IPPR(IPP + 1, 1) / 5000
          JPP = IPPR(JPP + 1, 1) / 5000
          IF (IPP < 2 .OR. JPP < 2) THEN
            XBND = 7.0
            IF (IPP * JPP == 0) DASH0 = -1.0
          END IF
        ELSE
          DASH0 = 1.0
        END IF
        IF (DASH0 < -1.0) THEN
          DASH0 = -1.0
          XBND  = 7.0
        END IF
        NAN           = NA + N * 3
        VOID(NAN - 2) = I
        VOID(NAN - 1) = J
        VOID(NAN)     = SIGN (XBND, DASH0)
      END IF
      IPR(131) = NC
      IPR(299) = NA + NC * 3
      RETURN
      END SUBROUTINE PLA268
 
      SUBROUTINE PLA269 (MODE, NAT)
C * SAVE/RESTORE XXO, XSD, CON TO/FROM SCRAT/VOID
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: MODE
      INTEGER :: NAT
      REAL, SAVE, DIMENSION(NP1*NP71) :: BUP
      K = 0
C * SAVE CONTENTS OF XXO, XSD, CON TO VOID  (SCRATCH)
      IF (MODE == 1) THEN
        DO I = 1, NAT
          DO J = 1, 6
            VOID(K + J)     = XXO(I, J)
            VOID(K + J + 6) = XSD(I, J)
          END DO
          DO J = 1, 9
            VOID(K + J + 12) = CON(I, J)
          END DO
          K = K + NP71
        END DO
        CALL GEN113 (VOID, BUP, NP71 * NAT)
C * SAVE ORTHOGONAL COORDINATES FOR HIRSHFELD R-B TEST
      ELSE IF (MODE == 2) THEN
        DO I = 1, NAT
          DO J = 1, 3
            VOID(K + J + 21) = XXO(I, J)
          END DO
          K = K + NP71
        END DO
C * COPY DATA FROM BUP TO VOID
      ELSE IF (MODE == 3) THEN
        CALL GEN113 (BUP, VOID, NP1 * NP71)
C * RESTORE XXO, XSD AND CON ARRAYS FROM SCRATCH COMMON
      ELSE IF (MODE == -1) THEN
        DO I = 1, NAT
          DO J = 1, 6
            XXO(I, J) = VOID(K + J)
            XSD(I, J) = VOID(K + J + 6)
          END DO
          DO J = 1, 9
            CON(I, J) = VOID(K + J + 12)
          END DO
          K = K + NP71
        END DO
      END IF
      RETURN
      END SUBROUTINE PLA269
 
      SUBROUTINE PLA270 (XM1, XM2, XM3)
C * MULTIPLY OR GET INVERSE SYMMETRY OPERATION(S)
      USE files
      USE parameters
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: MR3
      INTEGER :: MS1
      INTEGER :: MS2
      INTEGER :: ISW
      INTEGER :: MT11
      INTEGER :: MT12
      INTEGER :: MT13
      INTEGER :: MT21
      INTEGER :: MT22
      INTEGER :: MT23
      REAL :: XM1
      REAL :: XM2
      REAL :: XM3
      IPR(2) = 0
C * UNPACK ARU XM1
      ISW    = 9
      M1     = NINT (XM1 * 100)
      CALL PLA455 (M1, MS1, MT11, MT12, MT13, MR3)
      SGX(1) = MS1
      SGX(2) = MT11
      SGX(3) = MT12
      SGX(4) = MT13
C * UNPACK XM2
      M2     = NINT (XM2 * 100)
      IF (M2 /= 0) THEN
        ISW    = 8
        CALL PLA455 (M2, MS2, MT21, MT22, MT23, MR3)
        SGX(5) = MS2
        SGX(6) = MT21
        SGX(7) = MT22
        SGX(8) = MT23
      END IF
C * MULTIPLY OR INVERT
      CALL SGSM (ISW, ICL, SGX, 0, LU6, IERR)
      IF (IERR == 0) THEN
C * TEST FOR ARU-OUT-OF-RANGE STATUS
        DO I = 10, 12
          IF (ABS (SGX(I)) > 4.1) THEN
            WRITE (LU6, 99999, IOSTAT = IOST)
     1        XM1, XM2, (SGX(J), J = 9, 12)
            IF (IGBL(63) > 2) WRITE (LU7, 99999, IOSTAT = IOST)
     1        XM1, XM2, (SGX(J), J = 9, 12)
C * REGISTER/COUNT ARU-OUT-OF-RANGE CASES
            IPR(600) = IPR(600) + 1
            XM3      = 0.0
C * SET NO SQUEEZE
            IPR(210) = 0
            RETURN
          END IF
        END DO
        XM3 = (((SGX(9) * 10 + SGX(10)) * 10 + SGX(11)) * 10 + SGX(12))
        XM3 = NINT (XM3) + 555 + FLOAT (MR3) / 100.0
      ELSE
C * ERROR
        IPR(600) = IPR(600) + 1
        XM3      = 0.0
C * SET NO SQUEEZE
        IPR(210) = 0
      END IF
      RETURN
99999 FORMAT (':: ARU-Pack Problem :', 2F10.2, 4F5.0, /,
     1        ':: IPR(210) Reset to ZERO i.e. no SQUEEZE etc.')
      END SUBROUTINE PLA270
 
      SUBROUTINE PLA271
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: J
C * LAST MINUTE SYMMETRY UPDATE
C * GET SPACE GROUP INFO
      CALL SGSM (18, ICL, SGZ, 0, 0, IERR)
      SPGRNM(1) = ICL(1:26)
      SPGRNM(3) = ICL(44:60)
      SPGRNM(4) = ICL(15:26)
      IF (ICL(73:73) /= ' ') THEN
        ZSPG = ICL(73:79)
        J    = INDEX (ZSPG(2:7), 'r')
        IF (J /= 0) ZSPG(J+1:J+1) = 'R'
      END IF
      KRSYST(2) = ICL(27:38)
      LAUEGR    = ICL(39:43)
      CHSG      = ICL(72:72)
C * LOWER CASE HANDLING
      CALL GEN020 (-1, SPGRNM(1), 16, 24)
      CALL GEN020 (-1, KRSYST(2), 1,  12)
      IPR(202) = NINT (SGZ(1))
      IPR(241) = NINT (SGZ(7))
      IPR(242) = NINT (SGZ(8))
      IPR(255) = NINT (SGZ(4))
      IPR(256) = NINT (SGZ(6))
      IPR(257) = NINT (SGZ(5))
      IPR(258) = NINT (SGZ(3))
      IPR(259) = NINT (SGZ(2))
      IPR(48)  = NINT (SGZ(9))
      IPR(137) = NINT (SGZ(13))
      IPR(783) = NINT (SGZ(14))
C * CHECK FOR CIF-DATA
      IF (IGBL(8) == 3) THEN
C * CCIF(6) = H-M SYMBOL (SUPPLIED)
C * CCIF(7) = H-M SYMBOL (AS UNDERSTOOD)
C * CCIF(8) = FROM EXPLICIT SYMMETRY
        IF (CCIF(7)(1:1) == ' ') THEN
          CCIF(7) = SPGRNM(4)(1:11)
        ELSE
          CCIF(8) = SPGRNM(4)(1:11)
        END IF
      END IF
C * GET (A)CENTRIC INFO (DIFFERS FRPM IPR(257) FOR SHIFTED ORIGIN)
      CALL SGSM (13, ICL, SGZ, 0, 0, IERR)
      IPR(275) = NINT (SGZ(1))
      RETURN
      END SUBROUTINE PLA271
 
      SUBROUTINE PLA272
C * ROUTINE CHECKS THE GEOMETRY DATA AS REPORTED IN THE CIF AGAINST VALUES
C * CALCULATED FROM THE COORDINATES REPORTED IN THE CIF
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE symsav
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: IX
      INTEGER :: M7
      INTEGER :: M8
      INTEGER :: N3
      INTEGER :: N4
      INTEGER :: N5
      INTEGER :: N6
      INTEGER :: N7
      INTEGER :: IER
      INTEGER :: INR
      INTEGER :: ISA
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: NAT
      INTEGER :: NO1
      INTEGER :: NO2
      INTEGER :: IAT1
      INTEGER :: IAT2
      INTEGER :: IDIS
      INTEGER :: IEN1
      INTEGER :: IEN2
      INTEGER :: IENM
      INTEGER :: IVAL
      INTEGER :: ISP2
      INTEGER :: ISP3
      INTEGER :: NDEC
      INTEGER :: NHAT
      INTEGER :: NPOP
      INTEGER :: IRAT2
      INTEGER :: IGAT2
      INTEGER :: IEN12
      INTEGER :: IDAR2
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: IYUNK
      INTEGER :: NAHAT
      INTEGER :: NBHAT
      INTEGER :: NCSYM
      INTEGER :: NRTORS
      INTEGER, DIMENSION(4) :: NRAT
      REAL :: A
      REAL :: Y
      REAL :: A1
      REAL :: A2
      REAL :: SA
      REAL :: SB
      REAL :: RX
      REAL :: YUNK
      REAL :: RATIO
      REAL :: RATIO1
C * SYMMETRY CODES, BONDS, ANGLES, TORSIONS, CONTACTS,HBONDS HAVE BEEN COPIED
C * FROM THE CIF TO FILE LU11 IN ROUTINE PLA181
      A       = 0.0
      SA      = 0.0
      ISA     = 0
      NDEC    = 0
      NRAT(3) = 0
      NRAT(4) = 0
      N3      = 0
      N4      = 0
      N5      = 0
      N6      = 0
      N7      = 0
      NAT     = IPR(39) + IPR(64)
      NAHAT   = 0
      NBHAT   = 0
      NSCF    = 0
      NRTORS  = 0
      CALL GEN108 (LU11, 0)
C * READ SYMM AND GEOMETRY DATA RECOVERED FROM CIF
      DO
        READ (LU11, IOSTAT = IOST) LINE, (IFL(I), I = 1, 4),
     1    (FN(I), I = 1, 6)
        IF (IOST /= 0) EXIT
        NHAT = 0
        IER  = 0
        SELECT CASE (LINE(1:4))
C * SYMM FROM SAVED FROM CIF
          CASE ('SYMM')
            CALL SGSM (22, LINE, SGY, 0, 0, IERR)
            NSCF = NSCF + 1
            DO I = 1, 4
              NSCIF(I, NSCF) = NINT (SGY(I + 8))
            END DO
            IF (NSID(NSCF) == 0) NSID(NSCF) = NSCF
            CYCLE
C * ALERT _701 BOND TEST [LABEL1, LABEL2, DIST, SIGMA, SYMM1, SYMM2]
          CASE ('BOND')
C * COUNT BOND SEQUENCE #
            N5 = N5 + 1
            N7 = N5
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (2)
            N  = 2
            M7 = 1
C * ALERT _702 ANGLE TEST [LAB1, LAB2, LAB3, DIST, SIGMA, SYM1, SYM2, SYM3]
          CASE ('ANGL')
C * COUNT ANGLE SEQUENCE #
            N4 = N4 + 1
            N7 = N4
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (3)
            N  = 3
            M7 = 2
C * ALERT _703 TORSION ANGLE TEST
          CASE ('TORS')
C * COUNT TORSION SEQUENCE #
            N3 = N3 + 1
            N7 = N3
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (4)
            N  = 4
            M7 = 3
C * ALERT _704 CONTACT DISTANCE TEST
          CASE ('CONT')
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (2)
            N  = 2
            M7 = 4
C * ALERT _705 DONOR-H DISTANCE TEST
          CASE ('D-H ')
            N6 = N6 + 1
            N7 = N6
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (2)
            N  = 2
            M7 = 5
C * ALERT _706 H..ACCEPTOR DISTANCE TEST
          CASE ('H..A')
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (2)
            N  = 2
            M7 = 6
C * ALERT _707 DONOR..ACCEPTOR DISTANCE TEST
          CASE ('D..A')
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (2)
            N  = 2
            M7 = 7
C * ALERT _708 DONOR-H..ACCEPTOR ANGLE TEST
        CASE ('D-H.')
C * REMOVE '_$1' FROM LABEL                                 *
            CALL PLA391 (3)
            N  = 3
            M7 = 8
          CASE DEFAULT
            CYCLE
        END SELECT
        NPOP  = 0
        NCSYM = 0
        IDAR2 = 0
        IRAT2 = 0
        IGAT2 = 0
        IER   = 0
C * LOOP OVER SYMMETRY CODES IN GEOMETRY RECORD (BOND, ANGLE etc.)
        DO I = 1, N
          RX = FN(I + 2)
          IX = INT (ABS (RX))
          IF (IX == 0) THEN
            RX = 1.555
          ELSE IF (ABS (RX) - FLOAT (IX) < 0.01) THEN
            IF (RX > 0.0) THEN
              RX = RX + 0.555
            ELSE
              RX = RX - 0.555
            END IF
          END IF
          FN(I + 2) = RX
C * CHANGE s.ijk CODE INTO s_ijk STRING
          WRITE (IFL(I + 10), 99987) RX
          IFL(I + 10)(5:5) = '_'
C * ANALYSE CIF-SYMMETRY CODE(S)
          CALL PLA273 (0, FN(I + 2), IPR(54), ITR(1), ITR(2),
     1                 ITR(3), IER)
          IF (IER /= 0) EXIT
          NQ2 = IFL(I)
          IF (NQ2(1:1) == '?') THEN
            IER = -1
            EXIT
          END IF
C * GET SERIAL NUMBER IN ATOM ARRAY
          CALL PLA046 (-2, NQ2, IENM, LBB, LBC, LBD, INQNR, JNQNR, L)
          IF (L > 0) THEN
            NRAT(I) = L
C * CHECK FOR 'D' Restraint
            CALL GEN048 (-1, IFG(3, L), 7, IVAL)
            IDAR2 = MAX (IDAR2, IVAL)
C * CHECK FOR 'R' Constraint
            CALL GEN048 (-1, IFG(3, L), 6, IVAL)
            IRAT2 = MAX (IRAT2, IVAL)
C * CHECK FOR 'G' Constraint
            CALL GEN048 (-1, IFG(3, L), 5, IVAL)
            IGAT2 = MAX (IGAT2, IVAL)
C * COUNT H-ATOMS
            CALL GEN048 (-1, IFG(1, L), 7, IVAL)
            NHAT = NHAT + IVAL
            IF (M7 == 1) NBHAT = NBHAT + IVAL
            IF (M7 == 2) NAHAT = NAHAT + IVAL
C * ADDRESS POPULATION
            CALL GEN048 (-8, IFG(2, L), 1, IDIS)
            NPOP = NPOP + IPPR(IDIS + 1, 1) / 10000
          ELSE
            IF (NQ2(1:2) /= 'Cg'.AND. NQ2(1:2) /= 'CG') THEN
C * ALERT _710 (+M7) [including _718]
              CALL PLA236 (-(710 + M7), 2, 1.0, 1.0, NQ2, ' ')
              WRITE (LINE, 99995, IOSTAT = IOST) (IFL(J)(1:9), J = 1, N)
              CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
            END IF
            IER = -1
            EXIT
          END IF
          IF (FN(I + 2) /= 1.555) THEN
            NCSYM   = NCSYM + 1
            K       = NAT + I
            NRAT(I) = K
            LABA(K) = LABA(L)
C * ORTHOGONALIZE (USES ITR() & IPR(54) CONTENT
            CALL PLA059 (L, K)
            DO J = 1, 3
              IFG(J, K) = IFG(J, L)
            END DO
            CALL GEN048 (1, IFG(1, K), 5, 1)
          END IF
        END DO
        IF (IER == 0) THEN
C * DISTANCES
          IF (N == 2) THEN
C * CHECK ABSOLUTE BOND-DISTANCE VALUES SUPPLIED IN CIF
            INR = 0
            IF (M7 == 1) THEN
              YUNK = 1.0
              CALL GEN048 (-4, IFG(1, NRAT(1)), 15, NO1)
              CALL GEN048 (-4, IFG(1, NRAT(2)), 15, NO2)
              IEN1 = IEN(NO1 + 1)
              IEN2 = IEN(NO2 + 1)
              IAT1 = IATNR(IEN1)
              IAT2 = IATNR(IEN2)
              IF (IAT1 < IAT2) THEN
                CALL GEN014 (IEN1, IEN2)
                CALL GEN014 (IAT1, IAT2)
              END IF
              IEN12 = IEN1 * 1000 + IEN2
              INR   = 0
C * RANGE CHECK C - H (XRAY)
              IF (IEN12 == 2001) THEN
                IF (FN(1) > 1.3) INR = 770
C * RANGE CHECK N - H (XRAY)
              ELSE IF (IEN12 == 4001) THEN
                IF (FN(1) > 1.3) THEN
                  CALL GEN048 (-4, IFG(3, NRAT(2)), 28, IYUNK)
                  IF (IYUNK == 1) THEN
                    YUNK = FN(1)
                    INR = 771
                  ELSE
                    YUNK = -999.0
                    INR = 777
                  END IF
                END IF
C * RANGE CHECK O - H (XRAY)
              ELSE IF (IEN12 == 3001) THEN
                IF (FN(1) > 1.3) THEN
                  CALL GEN048 (-4, IFG(3, NRAT(2)), 28, IYUNK)
                  IF (IYUNK == 1) THEN
                    YUNK = FN(1)
                    INR  = 772
                  ELSE
                    YUNK = -999.0
                    INR  = 778
                  END IF
                END IF
C * RANGE CHECK C - C (XRAY)
              ELSE IF (IEN12 == 2002) THEN
                IF (FN(1) > 1.7) INR = 773
                YUNK = -999.0
C * 'BOND' CHECK FOR LONG/ERRONEOUS BOND [(METAL)ORGANIC ONLY]
              ELSE IF (FN(1) > 4.0) THEN
                IF (IGBL(97) == 1) THEN
                  YUNK = -999.0
                  INR  = 774
                END IF
              END IF
C * 'CONT' CHECK FOR LONG/ERRONEOUS CONTACT
            ELSE IF (M7 == 4) THEN
              IF (FN(1) > 4.0) THEN
                YUNK = FN(1)
                INR  = 775
              END IF
C * 'D-H'  CHECK FOR LONG/ERRONEOUS D-H
            ELSE IF (M7 == 5) THEN
              IF (FN(1) > 1.3 .AND. IFL(2)(1:1) == 'H') THEN
                YUNK = FN(1)
                INR  = 776
              END IF
            END IF
C * ALERT _77x
            IF (INR > 0) THEN
              CALL GEN020 (-1, IFL(1), 2, 2)
              CALL GEN020 (-1, IFL(2), 2, 2)
              IF (IFL(2)(1:2) /= 'Cg')
     1          CALL PLA236 (INR, 2, YUNK, FN(1), IFL(1), IFL(2))
            END IF
            M8 = M7
            IF (M7 == 1 .AND. NHAT == 0) IPR(316) = IPR(316) + 1
            CALL PLA053 (NRAT(1), NRAT(2), 0, 0, A, SA, ISA, NDEC, IER)
            IF (IER /= 0) CYCLE
            SB = MAX (0.0, SA)
            RATIO = ABS (FN(1) - A)
            IF (FN(2) <= 0.0 .OR. SA <= 0.0) THEN
              M8     = M8 + 20
              IF (FN(2) <= 0.0 .AND. SA <= 0) THEN
                RATIO1 = -999.0
              ELSE
                RATIO1 = RATIO * 100
              END IF
            ELSE
              RATIO  = RATIO / SA
              RATIO1 = RATIO
            END IF
C * ALERT _70x,_72x
            IF (RATIO1 > 1.0 .OR.
     1        (RATIO1 == -999.0 .AND. RATIO > 0.01)) THEN
              IF (A < 9.9) THEN
                WRITE (NQ3, 99997, IOSTAT = IOST) A
                WRITE (NQ4, 99997, IOSTAT = IOST) SB
                CALL PLA236 (-(700 + M8), 2, RATIO1, RATIO, NQ3, NQ4)
                WRITE (LINE, 99993, IOSTAT = IOST) (FN(I), I = 1, 2),
     1            (IFL(I)(1:9), I = 1, 2), (IFL(I)(1:8), I = 11, 12),
     2            N7
                CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
              ELSE IF (A < 99.9) THEN
                WRITE (NQ3, 99998, IOSTAT = IOST) A
                WRITE (NQ4, 99997, IOSTAT = IOST) SB
                CALL PLA236 (-(700 + M8), 2, RATIO1, RATIO, NQ3, NQ4)
                WRITE (LINE, 99988, IOSTAT = IOST) (FN(I), I = 1, 2),
     1            (IFL(I)(1:9), I = 1, 2), (IFL(I)(1:8), I = 11, 12),
     2            N7
                CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
              END IF
            END IF
C * CHECK BOND SU's
            IF (NPOP == 2) THEN
              IF (SA > 0.0) THEN
                IF (FN(2) > 0) THEN
                  RATIO  = MIN (9.9, FN(2) / SA)
                  IF (RATIO > 1.5) THEN
                    M7 = M7 + 30
C * ALERT _73x
                    IF (IDAR2 == 0) THEN
                      Y = ABS (FN(3) - FN(4))
                      IF (M7 /= 31 .OR. Y == 0.0 .OR. Y >= 1.0)
     1                  THEN
                        IF (A < 9.9) THEN
                          WRITE (NQ3, 99997, IOSTAT = IOST) A
                          WRITE (NQ4, 99997, IOSTAT = IOST) SB
                          CALL PLA236 (-(700 + M7), 1, RATIO, RATIO,
     1                      NQ3, NQ4)
                          WRITE (LINE, 99993, IOSTAT = IOST)
     1                      (FN(I), I = 1, 2), (IFL(I)(1:9), I = 1, 2),
     2                      (IFL(I)(1:8), I = 11, 12), N7
                          CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                        ELSE IF (A < 99.9) THEN
                          WRITE (NQ3, 99998, IOSTAT = IOST) A
                          WRITE (NQ4, 99997, IOSTAT = IOST) SB
                          CALL PLA236 (-(700 + M7), 2, RATIO, RATIO,
     1                      NQ3, NQ4)
                          WRITE (LINE, 99990, IOSTAT = IOST)
     1                      (FN(I), I = 1, 2), (IFL(I)(1:9), I = 1, 2),
     2                      (IFL(I)(1:8), I = 11, 12), N7
                          CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                       END IF
                      END IF
                    END IF
                  END IF
                ELSE
                  IF (IRAT2 + IDAR2 + IGAT2 + IPR(639) == 0) THEN
                    M7 = M7 + 40
C * ALERT _74x
                    IF (A < 9.9) THEN
                      WRITE (NQ3, 99997, IOSTAT = IOST) A
                      WRITE (NQ4, 99997, IOSTAT = IOST) SB
                      CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                      WRITE (LINE, 99993, IOSTAT = IOST)
     1                  (FN(I), I = 1, 2), (IFL(I)(1:9), I = 1, 2),
     2                  (IFL(I)(1:8), I = 11, 12), N7
                      CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                    ELSE IF (A < 99.9) THEN
                      WRITE (NQ3, 99998, IOSTAT = IOST) A
                      WRITE (NQ4, 99997, IOSTAT = IOST) SB
                      CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                      WRITE (LINE, 99990, IOSTAT = IOST)
     1                  (FN(I), I = 1, 2), (IFL(I)(1:9), I = 1, 2),
     2                  (IFL(I)(1:8), I = 11, 12), N7
                      CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                    END IF
                  END IF
                END IF
C * TEST FOR SENSELESS SU (NOT FOR POWDER)
              ELSE IF (FN(2) > 0.0 .AND. IPR(105) == 0) THEN
                M7 = M7 + 50
C * ALERT _75x
                IF (A < 9.9) THEN
                  WRITE (NQ3, 99997, IOSTAT = IOST) A
                  WRITE (NQ4, 99997, IOSTAT = IOST) SB
                  CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                  WRITE (LINE, 99993, IOSTAT = IOST) (FN(I), I = 1, 2),
     1              (IFL(I)(1:9), I = 1, 2), (IFL(I)(1:8), I = 11, 12),
     2              N7
                  CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                ELSE IF (A < 99.9) THEN
                  WRITE (NQ3, 99998, IOSTAT = IOST) A
                  WRITE (NQ4, 99997, IOSTAT = IOST) SB
                  CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                  WRITE (LINE, 99990, IOSTAT = IOST) (FN(I), I = 1, 2),
     1              (IFL(I)(1:9), I = 1, 2), (IFL(I)(1:8), I = 11, 12),
     2              N7
                CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                END IF
              END IF
            END IF
C * CHECK ANGLES
          ELSE IF (N == 3) THEN
C * CHECK FOR METAL [(METAL)ORGANIC ONLY]
            IF (FN(1) < 45.0 .AND. IGBL(97) == 1) THEN
              CALL GEN048 (-1, IFG(1, NRAT(2)), 19, IVAL)
              IF (IVAL == 0) THEN
C * ALERT _779
                WRITE (NQ3, 99999, IOSTAT = IOST) FN(1)
                CALL PLA236 (-779, 2, -999.0, 0.0, NQ3, ' ')
                WRITE (LINE, 99989, IOSTAT = IOST)
     1            (IFL(I)(1:5), I = 1, 3), (IFL(I)(1:8), I = 11, 13),
     2             N7
                CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
              END IF
            END IF
C * CHECK ABSOLUTE BOND ANGLE VALUES
            M8 = M7
            CALL PLA053 (NRAT(1), NRAT(2), NRAT(3), 0, A, SA, ISA,
     1        NDEC, IER)
            IF (IER /= 0) CYCLE
            SB    = MAX (0.0, SA)
            RATIO = ABS (FN(1) - A)
            IF (FN(2) <= 0.0 .OR. SA <= 0.0) THEN
              M8 = M8 + 20
              IF (FN(2) <= 0.0 .AND. SA <= 0.0) THEN
                RATIO1 = -999.0
              ELSE
                RATIO1 = RATIO
              END IF
            ELSE
              RATIO  = RATIO / SA
              RATIO1 = RATIO
            END IF
            IF (RATIO1 > 1.0 .OR.
     1        (RATIO1 == -999.0 .AND. RATIO > 1.0)) THEN
              WRITE (NQ3, 99999, IOSTAT = IOST) A
              WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _70x,_72x
              CALL PLA236 (-(700 + M8), 2, RATIO1, RATIO, NQ3, NQ4)
              WRITE (LINE, 99994, IOSTAT = IOST) (FN(I), I = 1, 2),
     1          (IFL(I)(1:8), I = 1, 3), (IFL(I)(2:8), I = 11, 13), N7
              CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
            END IF
C * CHECK BOND ANGLE SU's
            IF (NPOP == 3) THEN
              IF (NCSYM == 0) THEN
                IF (SA > 0.0 .AND. ABS(A) < 179.95) THEN
                  IF (FN(2) > 0.0) THEN
                    RATIO  = MIN (9.9, FN(2) / SA)
C * CHECK FOR RIDING H'S
                    CALL GEN048 (-1, IFG(1, NRAT(1)), 7, IVAL)
                    IF (IVAL /= 0) THEN
                      CALL GEN048 (-1, IFG(3, NRAT(1)), 6, IVAL)
                      IF (IVAL /= 0) CYCLE
                    END IF
                    CALL GEN048 (-1, IFG(1, NRAT(3)), 7, IVAL)
                    IF (IVAL /= 0) THEN
                      CALL GEN048 (-1, IFG(3, NRAT(3)), 6, IVAL)
                      IF (IVAL /= 0) CYCLE
                    END IF
                    IF (SA > 0.01 .AND. FN(2) > 0.007) THEN
                      IF (RATIO > 1.5) THEN
                        M7 = M7 + 30
                        IF (IDAR2 == 0) THEN
                          WRITE (NQ3, 99999, IOSTAT = IOST) A
                          WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _73x
                          CALL PLA236 (-(700 + M7), 2, RATIO, RATIO,
     1                      NQ3, NQ4)
                          WRITE (LINE, 99994, IOSTAT = IOST)
     1                      (FN(I), I = 1, 2), (IFL(I)(1:8), I = 1, 3),
     2                      (IFL(I)(2:8), I = 11, 13), N7
                          CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                        END IF
                      END IF
                    END IF
                  ELSE
                    IF (IRAT2 + IGAT2 + IDAR2 + IPR(639) == 0) THEN
                      M7 = M7 + 40
                      WRITE (NQ3, 99999, IOSTAT = IOST) A
                      WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _74x
                      CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                      WRITE (LINE, 99994, IOSTAT = IOST)
     1                  (FN(I), I = 1, 2), (IFL(I)(1:8), I = 1, 3),
     2                  (IFL(I)(2:8), I = 11, 13), N7
                      CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                    END IF
                  END IF
C * TEST FOR SENSELESS SU (NOT FOR POWDER)
                ELSE IF (FN(2) > 0.0 .AND. ABS (A) < 179.95 .AND.
     1            IPR(105) == 0) THEN
                  M7 = M7 + 50
                  WRITE (NQ3, 99999, IOSTAT = IOST) A
                  WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _75x
                  CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                  WRITE (LINE, 99994, IOSTAT = IOST) (FN(I), I = 1, 2),
     1              (IFL(I)(1:8), I = 1, 3), (IFL(I)(2:8), I = 11, 13),
     2              N7
                  CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                END IF
              END IF
            END IF
C * TORSIONS
          ELSE IF (N == 4) THEN
            NRTORS = NRTORS + 1
C * CHECK ABSOLUTE TORSION ANGLE VALUES
            M8 = M7
            CALL PLA050 (NRAT(1), NRAT(2), NRAT(3), 0, A1)
            CALL PLA050 (NRAT(2), NRAT(3), NRAT(4), 0, A2)
            IF (A1 < 170 .AND. A2 < 170) THEN
              CALL PLA053 (NRAT(1), NRAT(2), NRAT(3), NRAT(4), A, SA,
     1          ISA, NDEC, IER)
              IF (IER /= 0) CYCLE
              SB = MAX (0.0, SA)
              RATIO = ABS (FN(1) - A)
              IF (RATIO > 180.0) RATIO = 360.0 - RATIO
              IF (FN(2) <= 0.0 .OR. SA <= 0.0) THEN
                M8 = M8 + 20
                RATIO1 = RATIO
              ELSE
                RATIO  = RATIO / SA
                RATIO1 = RATIO
              END IF
              IF (RATIO > 1.0) THEN
                WRITE (NQ3, 99999, IOSTAT = IOST) A
                WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _70x,_72x
                CALL PLA236 (-(700 + M8), 2, RATIO1, RATIO, NQ3, NQ4)
                WRITE (LINE, 99992, IOSTAT = IOST)
     1            (FN(I), I = 1, 2), (IFL(I)(1:4), I = 1, 4),
     2          (IFL(I)(2:8), I = 11, 14), N7
                CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
              END IF
C * CHECK TORSION ANGLE SU's
              IF (NPOP == 4) THEN
                CALL GEN048 (-1, IFG(1, NRAT(2)), 6, ISP2)
                CALL GEN048 (-1, IFG(1, NRAT(3)), 6, ISP3)
                IF (ABS (A) > 0.05 .AND. ABS (A) < 179.95 .AND.
     1             ABS (ABS (A) - 60.0) > 0.01) THEN
                  IF (SA > 0.0) THEN
                    IF (ISP2 == 0 .AND. ISP3 == 0) THEN
                      IF (FN(2) > 0.0) THEN
                        RATIO = MIN (9.9, MAX (FN(2) / SA, SA / FN(2)))
C * CHECK FOR MOPRO
                        IF (RATIO > 1.5 .AND. IPR(725) /= 9) THEN
                          M7 = M7 + 30
                          WRITE (NQ3, 99999, IOSTAT = IOST) A
                          WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _73x
                          CALL PLA236 (-(700 + M7), 2, RATIO, RATIO,
     1                      NQ3, NQ4)
                          WRITE (LINE, 99992, IOSTAT = IOST)
     1                      (FN(I), I = 1, 2), (IFL(I)(1:4), I = 1, 4),
     2                      (IFL(I)(2:8), I = 11, 14), N7
                          CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                        END IF
                      ELSE
                        IF (IRAT2 + IDAR2 + IGAT2 == 0) THEN
                          M7 = M7 + 40
                          WRITE (NQ3, 99999, IOSTAT = IOST) A
                          WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _74x
                          CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3,
     1                      NQ4)
                          WRITE (LINE, 99992, IOSTAT = IOST)
     1                      (FN(I), I = 1, 2), (IFL(I)(1:4), I = 1, 4),
     2                      (IFL(I)(2:8), I = 11, 14), N7
                          CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                        END IF
                      END IF
                    END IF
C * TEST FOR SENSELESS SU (NOT FOR POWDER)
                  ELSE IF (FN(2) > 0.0 .AND. IPR(105) == 0) THEN
                    M7 = M7 + 50
                    WRITE (NQ3, 99999, IOSTAT = IOST) A
                    WRITE (NQ4, 99999, IOSTAT = IOST) SB
C * ALERT _75x
                    CALL PLA236 (-(700 + M7), 2, 1.0, 1.0, NQ3, NQ4)
                    WRITE (LINE, 99992, IOSTAT = IOST)
     1                (FN(I), I = 1, 2), (IFL(I)(1:4), I = 1, 4),
     2                (IFL(I)(2:8), I = 11, 14), N7
                    CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
                  END IF
                END IF
              END IF
            ELSE
              WRITE (LINE, 99996, IOSTAT = IOST) N7
C * ALERT _710
              CALL PLA236 (-710, 0, -999.0, 0.0, LINE(1:7), ' ')
              WRITE (LINE, 99991, IOSTAT = IOST)
     1          (IFL(I)(1:4), I = 1, 4), (FN(I), I = 1, 2),
     2          (IFL(I)(1:8), I = 11, 14)
              CALL PLA236 (0, 0, 0.0, 0.0, LINE, ' ')
            END IF
          END IF
        END IF
      END DO
C * CHECK FOR NON-CSD CIF
      IF (IGBL(94) == 0) THEN
C * CHECK FOR ORGANIC
        IF (IGBL(97) == 1) THEN
C * ALERT _760
          IF (NRTORS == 0 .AND. IPR(105) == 0)
     1      CALL PLA236 (760, 1, -999.0, 1.0, ' ', ' ')
C * CHECK H-PRESENT
          IF (IPR(484) > 0) THEN
C * ALERT _761
            IF (NBHAT == 0) CALL PLA236 (761, 0, 1.0, 1.0, ' ', ' ')
C * ALERT _762
            IF (NAHAT == 0) CALL PLA236 (762, 0, 1.0, 1.0, ' ', ' ')
          END IF
        END IF
      END IF
      CALL GEN108 (LU11, 0)
99999 FORMAT (F7.2)
99998 FORMAT (F7.4)
99997 FORMAT (F7.5)
99996 FORMAT (I5, 2X)
99995 FORMAT (20X, 4A)
99994 FORMAT (2F7.2, 2(A, '-'), A, 1X, 3A, 5X, '#', I5,
     1       ' Check')
99993 FORMAT (F7.5, F7.5, A, '-', A, 4X, 2A, 1X, 8('.'), 5X, '#',
     1        I5, ' Check')
99992 FORMAT (2F7.2, 3(A, '-'), A, 4A, 6X, '#', I5, ' Check')
99991 FORMAT (14X, 3(A, '-'), A, F8.2, F6.2, 4A)
99990 FORMAT (F7.4, F7.5, A, '-', A, 4X, 2A, 1X, 8('.'), 5X, '#',
     1       I5, ' Check')
99989 FORMAT (14X, 2(A, '-'), A, 3A, 1X, 6('.'), 5X, '#', I5, ' Check')
99988 FORMAT (F7.4, F7.5, A, '-', A, 4X, 2A, 1X, 8('.'), 5X, '#',
     1        I5, ' Check')
99987 FORMAT (F8.3)
      RETURN
      END SUBROUTINE PLA272
 
      SUBROUTINE PLA273 (MODE, CODE, NS, IT1, IT2, IT3, IER)
C * SAVE ORIGINAL SYMMETRY CODES AS SUPPLIED IN CIF
      USE symsav
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IX
      INTEGER :: NS
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: MS
      INTEGER :: IT1
      INTEGER :: IT2
      INTEGER :: IT3
      INTEGER :: IER
      INTEGER :: MODE
      REAL :: Z
      REAL :: RX
      REAL :: CODE
C * HANDLE/STORE EXPLICIT SYMMETRY CODES IN CIF
      RX  = CODE
      IER = 0
 
C * MODE = 0 - ANALYSE CIF-SYMMETRY CODE
      IF (MODE == 0) THEN
C * HANDLE SYMMETRY CODES 'X':  ('.' = DEFAULT = 1.555)
        IF (RX == 0.0) THEN
          CODE = 1.555
          NS   = 1
          IT1  = 0
          IT2  = 0
          IT3  = 0
        ELSE
          IX = INT (ABS (RX))
          IF (ABS (RX) - FLOAT (IX) < 0.01) THEN
            IF (RX > 0.0) THEN
              RX = RX + 0.555
            ELSE
              RX = RX - 0.555
            END IF
          END IF
C * REPLACE SYMM ID BY SEQUENCE NUMBER
          IF (RX >= 0.0) THEN
            N = INT (RX)
            Z = RX - N
          ELSE
            N = - INT (ABS (RX))
            Z = ABS(RX) + N
          END IF
          DO I = 1, NSCF
            IF (NSID(I) == N) THEN
              RX = Z + I
              EXIT
            END IF
          END DO
          M  = NINT (RX  * 1000.0)
          MS = M  / 1000
          IF (MS <= 0 .OR. MS > NSCF) THEN
            IER = 1
            RETURN
          END IF
          M    = M  - MS * 1000
          M1   = M  / 100
          M    = M  - M1 * 100
          M1   = M1 - 5
          M2   = M  / 10
          M3   = M  - M2 * 10 - 5
          M2   = M2 - 5
          CODE = RX
          NS   = NSCIF(1, MS)
          IT1  = M1 + NSCIF(2, MS)
          IT2  = M2 + NSCIF(3, MS)
          IT3  = M3 + NSCIF(4, MS)
        END IF
C * MODE = 1 - GET CIF-SYMMETRY CODE
      ELSE IF (MODE == 1) THEN
        M  = INT (RX)
        MS = M  / 1000
        M  = M  - MS * 1000
        M1 = M  / 100
        M  = M  - M1 * 100
        M1 = M1 - 5
        M2 = M  / 10
        M3 = M  - M2 * 10 - 5
        M2 = M2 - 5
        IF (NSCF > 0) THEN
          DO I = 1, NSCF
            IF (MS == NSCIF(1, I)) THEN
              NS  = NSID(I)
              IT1 = M1 - NSCIF(2, I)
              IT2 = M2 - NSCIF(3, I)
              IT3 = M3 - NSCIF(4, I)
              RETURN
            END IF
          END DO
        END IF
        IER = 1
        RETURN
      END IF
      RETURN
      END SUBROUTINE PLA273
 
      SUBROUTINE PLA274
      USE files
      USE parameters
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      CHARACTER(len=1) :: ICH
C * LIST SYMMETRY
      IF (IWIN == 1) THEN
        VRT = VERT - 0.2
        CALL GGIP (HORS, VERT, 0.0, 1)
        OPEN (LU61, FILE = 'srcsrc', STATUS = 'UNKNOWN')
        CALL SGSM (2, ICL, SGX, 0, LU61, IERR)
        CALL GEN108 (LU61, 0)
        DO
          READ (LU61, 99999, IOSTAT = IOST) ICL(1:80)
          IF (IOST /= 0) EXIT
          IF (VRT - 0.5 < 0.0) THEN
C * WHAT NEXT ?
            CALL PLA012 (1, 1)
            ICH = IGGT(1:1)
            CALL GGIP (HORS, VERT, 0.0, 1)
            IF (ICH /= 'Y' .AND. ICH /= '!') EXIT
            VRT = VERT
          END IF
          VRT = VRT - 0.5
          CALL PLA439 (0.0, ICL, 80, 0.35, 1, 2, 1.0, VRT)
        END DO
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
        CALL PLA297 (0)
      ELSE
        CALL SGSM (2, ICL, SGX, 0, LU6, IERR)
      END IF
      RETURN
99999 FORMAT (A)
      END SUBROUTINE PLA274
 
      SUBROUTINE PLA275
C * PACK check.def FILE CONTENT INTO FORTRAN source CODE: check.f ( = CHECK)
C * check.def SOURCE LOCATION TAKEN FROM THE 'CHECKDEF' VARIABLE
C * The check.f FILE IS PUT IN THE CURRENT DIRECTORY AND SHOULD BE APPENDED
C * TO THE FORTRAN SOURCE OR REPLACE THE PREVIOUS VERSION OF THE CHECK ROUTINE
      USE files
      USE parameters
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: N0
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: N4
      INTEGER :: NUM
      INTEGER :: ICKVERS
      INTEGER, DIMENSION(4) :: IC
      INTEGER, DIMENSION(6) :: IBUF
      CHARACTER(len=80) :: LINE
      CHARACTER(len=72), DIMENSION(50)    :: BUF
      CHARACTER(len=1),  DIMENSION(4, 20) :: A
      DO I = 1, 4
        IC(I) = 256**(I - 1)
      END DO
C * DEFAULT check.def LOCATION: /usr/local/lib/platon/check.def
      OPEN (UNIT = LU12, FILE = CHECKDEF, STATUS = 'OLD', IOSTAT = IOST)
C * OPEN FILE FOR RECEIVING THE FORTRAN SOURCE
      IF (IOST == 0) THEN
        OPEN  (LU61, FILE = 'check.f', STATUS = 'UNKNOWN')
C * IBUF() =  0 : END-OF-FILE
C *        = -1 : #==== RECORD
C *        = -2 : BLANK RECORD
C *        = -3 : END-OF-RECORD
        N2 = 0
C * L      =  0 : DETERMINE REQUIRED SIZE OF ARRAY BUF
C *        =  1 : FILL BUF WITH ENCODED check.def CONTENT
        DO L = 0, 1
          REWIND (LU12)
          IF (L > 0) WRITE (LU61, 99997) N2
          ICKVERS = 0
          N0      = 0
          N1      = 1
          N2      = 0
          M       = 0
          DO
            READ (LU12, 99998, IOSTAT = IOST) LINE
            IF (IOST /= 0) THEN
              M       = M + 1
              IBUF(M) = 0
              CALL PLA276 (L, N0, N1, N2, BUF, IBUF, 1)
              IF (L > 0) WRITE (LU61, 99996)
              EXIT
C * GET VERSION # IN check.def (yymmdd)
            ELSE IF (LINE(1:6) == '!check') THEN
              N = INDEX (LINE, 'version')
              IF (N > 0) THEN
                READ (LINE(N + 7:N + 14), *) ICKVERS
                M = M + 1
                IBUF(M) = - ICKVERS
              ELSE
                EXIT
              END IF
            ELSE IF (LINE(1:5) == '#====') THEN
              M       = M + 1
              IBUF(M) = -1
              IF (M == 6) THEN
                CALL PLA276 (L, N0, N1, N2, BUF, IBUF, 0)
                M = 0
              END IF
            ELSE
              K  = 20
              N3 = 77
              N4 = 80
              DO
                IF (LINE(N3:N4) == '    ') THEN
                  K = K - 1
                  IF (K == 0) THEN
                    M       = M + 1
                    IBUF(M) = -2
                    IF (M == 6) THEN
                      CALL PLA276 (L, N0, N1, N2, BUF, IBUF, 0)
                      M = 0
                    END IF
                    EXIT
                  ELSE
                    N3 = N3 - 4
                    N4 = N4 - 4
                  END IF
                ELSE
                  EXIT
                END IF
              END DO
C * REGULAR TEXT RECORD
              IF (K > 0) THEN
                READ (LINE, 99999, IOSTAT = IOST)
     1            ((A(J, I), J = 1, 4), I = 1, K)
                DO I = 1, K
                  NUM = 0
                  DO J = 1, 4
                    NUM = NUM + ICHAR (A(J, I)) * IC(5 - J)
                  END DO
                  M       = M + 1
                  IBUF(M) = NUM
                  IF (M == 6) THEN
                    CALL PLA276 (L, N0, N1, N2, BUF, IBUF, 0)
                    M = 0
                  END IF
                END DO
C * EARLY END-OF-RECORD
                IF (K < 20) THEN
                  M = M + 1
                  IBUF(M) = -3
                  IF (M == 6) THEN
                    CALL PLA276 (L, N0, N1, N2, BUF, IBUF, 0)
                    M = 0
                  END IF
                END IF
              END IF
            END IF
          END DO
        END DO
        WRITE (LU6, 99995) ICKVERS, N2
      ELSE
        WRITE (LU6, 99994) 'No '//CHECKDEF(1:70)//' found'
      END IF
      RETURN
99999 FORMAT (80A)
99998 FORMAT (A)
99997 FORMAT (6X, 'SUBROUTINE CHECK (MODE, IVERS)', /,
     1        'C', /,
     2        'C * EMBEDDED ENCODED check.def FILE', /,
     3        'C', /,
     4        6X, 'IMPLICIT NONE', /,
     5        6X, 'INTEGER                            :: MODE', /,
     6        6X, 'INTEGER                            :: IVERS', /,
     7        6X, 'INTEGER, ALLOCATABLE, DIMENSION(:) :: ICK', /,
     8        6X, 'ALLOCATE (ICK(', I6, '))')
99996 FORMAT (6X, 'IF (MODE == 0) THEN', /,
     1        'C * GET VERSION NUMBER yymmdd', /,
     2        6X, '  IVERS = - ICK(1)', /,
     3        6X, 'ELSE', /,
     4        'C * RE-CREATE check.def FILE', /,
     5        6X, '  CALL PLA277 (ICK)', /,
     6        6X, 'END IF', /,
     7        6X, 'RETURN', /,
     8        6X, 'END SUBROUTINE CHECK')
99995 FORMAT ('Create check.f for check.def version =', I7, 5X,
     1        '[', I6,']')
99994 FORMAT (/, A, /)
      END SUBROUTINE PLA275
 
      SUBROUTINE PLA276 (L, N0, N1, N2, BUF, IBUF, M)
C * PACK check.def > check.f
      USE files
      USE parameters
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N0
      INTEGER :: N1
      INTEGER :: N2
      INTEGER, DIMENSION(*) :: IBUF
      CHARACTER(len=72) :: LINE
      CHARACTER(len=72), DIMENSION(50) :: BUF
      IF (L > 0) WRITE (LINE, 99999) (IBUF(I), I = 1, 6)
      N0 = N0 + 1
      N2 = N2 + 6
      IF (N0 == 50 .OR. M == 1) THEN
        LINE (72:72) = '/'
        BUF(N0) = LINE
        IF (L > 0) THEN
          WRITE (LU61, 99997) N1, N2
          WRITE (LU61, 99998) (BUF(I), I = 1, N0)
          WRITE (LU61, 99996)
        END IF
        N0 = 0
        N1 = N1 + 300
      ELSE
        BUF(N0) = LINE
      END IF
      RETURN
99999 FORMAT (5X, '*', 6(I10, ','))
99998 FORMAT (A)
99997 FORMAT (6X, 'ICK(', I6,':', I6, ') = (/')
99996 FORMAT (5X, '* )')
      END SUBROUTINE PLA276
 
      SUBROUTINE PLA277 (ICK)
      USE files
      USE parameters
C * RE-CREATE A check.def FROM THE PACKED VERSION IN ARRAY ICK
C * check.def IS PUT IN THE CURRENT DIRECTORY
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M1
      INTEGER :: ICKVERS
      INTEGER, DIMENSION(4) :: IC
      INTEGER, DIMENSION(*) :: ICK
      CHARACTER(len=80) :: LINE
      INQUIRE (UNIT = LU12, OPENED = OPEND)
      IF (OPEND) CLOSE (UNIT = LU12, IOSTAT = IOST)
      OPEN (UNIT = LU12, FILE = 'check.def', STATUS = 'UNKNOWN',
     1  IOSTAT = IOST)
      IF (IOST /= 0) CALL GEN127 ('check.def file open problem')
      ICKVERS = 0
      LINE    = ' '
      DO I = 1, 4
        IC(I) = 256**(I - 1)
      END DO
      N  = 0
      I  = 0
C * LOOP OVER ARRAY WITH PACKED CHECK.DEF CONTENT
      DO
        I  = I + 1
        M  = ICK(I)
C * GENERAL ENTRIES
        IF (M > 0) THEN
          DO K = 1, 4
            M1 = M / IC(5 - K)
            N  = N + 1
            LINE(N:N) = CHAR (M1)
            M  = M - M1 * IC(5 - K)
          END DO
          IF (N == 80) THEN
            WRITE (LU12, 99997, IOSTAT = IOST) LINE
            N = 0
          END IF
C * SPECIAL KEYWORD ENTRIES
        ELSE
C * CHECK FOR END-OF-FILE
          IF (M == 0) THEN
            IF (ICKVERS > 0) WRITE (LU6, 99996) ICKVERS
            RETURN
C * CHECK FOR SEPARATOR RECORD
          ELSE IF (M == -1) THEN
            WRITE (LU12, 99999, IOSTAT = IOST)
C * CHECK FOR BLANK RECORD
          ELSE IF (M == -2) THEN
            WRITE (LU12, 99998, IOSTAT = IOST)
C * CHECK FOR 'END-OF-RECORD' RECORD
          ELSE IF (M == -3) THEN
            WRITE (LU12, 99997, IOSTAT = IOST) LINE(1:N)
            N = 0
          ELSE
            ICKVERS = - M
            WRITE (LU12, 99995, IOSTAT = IOST) ICKVERS
          END IF
        END IF
      END DO
      IGBL(21) = ICKVERS
      RETURN
99999 FORMAT ('#', 77('='))
99998 FORMAT (80X)
99997 FORMAT (A)
99996 FORMAT (/, ':: check.def version', I7,
     1 ' created from embedded data')
99995 FORMAT ('!check.def version', I7, 1X, 51('='))
      END SUBROUTINE PLA277
 
      SUBROUTINE PLA278
C * GENERATE platon_special.f from platon.f
      USE files
      IMPLICIT NONE
      INTEGER :: NB = 1
      INTEGER :: NE = 80
      INTEGER :: ISKIP = 0
      CHARACTER(len=80) :: LINE
      OPEN (UNIT = LU60, FILE = 'platon.f', STATUS = 'OLD',
     1  IOSTAT = IOST)
      IF (IOST == 0) THEN
        OPEN  (LU61, FILE = 'platon_special.f', STATUS = 'UNKNOWN')
        DO
          READ (LU60, 99999, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          IF (LINE(1 : 11) == 'C STRIP_BEG') THEN
            ISKIP = 1
          ELSE IF (LINE(1 : 11) == 'C STRIP_END') THEN
            ISKIP = 0
          END IF
          CALL GEN039 (1, LINE, 1, 80, NB, NE)
          IF (ISKIP ==0) WRITE (LU61, 99999, IOSTAT = IOST) LINE (1:NE)
        END DO
      ELSE
        CALL GEN127 ('No platon.f file found in this directory')
      END IF
        STOP 'platon_special.f created from platon.f'
      RETURN
99999 FORMAT (A)
      END SUBROUTINE PLA278
 
      SUBROUTINE PLA279 (IAT, N)
C * PROGRAM TO CALCULATE POLYHEDRAL VOLUMES AND DISTORTION PARAMETERS (4 & 6)
C * See R.M.Hazen & L.W.Finger, Comparative Crystal Chemistry, 1982, p86 AND
C *   APPENDIX III (Original Fortran Source Code by L.W. Finger 9/21/71)
C * ORIGINAL PROGRAM VOLCAL CODE ADAPTED AND EXTENDED FOR USE IN PLATON
      USE files
      USE parameters
      USE atomdata
      USE plato
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NA
      INTEGER :: NM
      INTEGER :: MN
      INTEGER :: NP
      INTEGER :: IAT
      INTEGER :: NPMN
      INTEGER :: NPMX
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER, DIMENSION(3) :: IH
      REAL :: Z
      REAL :: ZO
      REAL :: QE
      REAL :: VLO
      REAL :: VOL
      REAL :: SOM4
      REAL :: SOM6
      REAL :: SIGA
      REAL :: ANG1
      REAL :: ANG2
      REAL :: AREA
      REAL :: CONS
      REAL :: TEMP
      REAL :: SUMTH
      REAL :: SUMTH2
      REAL :: FACTOR
      REAL :: GEN009
      REAL, DIMENSION(3)     :: D
      REAL, DIMENSION(3, 12) :: XP
      REAL, DIMENSION(20)    :: DM
      CHARACTER(len=80)  :: LINE
      CHARACTER(len=11)  :: POLY
      CHARACTER(len=132) :: PRBUF
      CHARACTER(len=NP64), DIMENSION(12) :: CXP
C * EXCLUDE SOME CENTRAL ELEMENT TYPES
      CALL GEN048 (-4, IFG(1, IAT), 15, K)
      K = IEN(K + 1)
      IF (ELB(K) /= 'O ') THEN
C * CALCULATE NP COORDINATION DISTANCES (CENTRE AT 0,0,0)
        L    = 0
        SOM4 = 0.0
        SOM6 = 0.0
        DO J = 1, N
C * EXCLUDE 'COORDINATING' METALS
          CALL GEN048 (-1, IFG(1, IATC(J)), 19, K)
          IF (K == 0) THEN
            L    = L + 1
            TEMP = 0.0
            DO I = 1, 3
              XP(I, L) = XXO(IATC(J), I + 3) - XXO(IAT, I + 3)
              TEMP = TEMP + XP(I, L)**2
            END DO
            IF (L <= 4) SOM4 = SOM4 + TEMP
            IF (L <= 6) SOM6 = SOM6 + TEMP
            DM(L)  = SQRT (TEMP)
C * GET ATOM LABEL
            CALL PLA047 (LABA(IATC(J)), CXP(L), IDUM, JDUM, IPR(71),
     1        IGBL(55), 0, 0)
          END IF
        END DO
        IF (L >= 4) THEN
          NPMX = L
          NPMN = L
          IF (IGBL(144) > 0) THEN
            NPMN = 4
            WRITE (LU6, 99988)
          END IF
          DO NP = NPMN, NPMX
            NA     = 0
            VOL    = 0.0
            ANG1   = 0.0
            ANG2   = 0.0
            SUMTH  = 0.0
            SUMTH2 = 0.0
C * FIND TRIANGULAR FACES, CHOOSE ANY THREE POINTS
C * LOOP OVER FIRST VERTEX
            DO I = 1, NP - 2
              IH(1) = I
C * LOOP OVER SECOND VERTEX
              DO J = I + 1, NP - 1
                IH(2) = J
                DO K = 1, 3
                  V1(K) = XP(K, J) - XP(K, I)
                END DO
C * LOOP OVER THIRD VERTEX
                DO K = J + 1, NP
                  IH(3) = K
                  DO N = 1, 3
                    V2(N) = XP(N, K) - XP(N, I)
                  END DO
C * VECTOR PRODUCT. PLANE EQUATION. DISTANCE ORIGIN
                  CALL GEN008 (V1, V2, D, 0)
                  AREA = SQRT (GEN009 (D, D))
                  ZO   = (XP(1, I) * D(1) + XP(2, I) * D(2)
     1                 +  XP(3, I) * D(3)) / AREA
C * CHECK FOR AND AVOID PLANE THROUGH ORIGIN
                  IF (ABS(ZO) >= 0.0025) THEN
                    FACTOR = 6.0
                    DO L = 1, NP
                      IF (L /= I .AND. L /= J .AND. L /= K) THEN
C * CALCULATE DISTANCE OF POINT L FROM PLANE OF I,J,K
                        Z = ((XP(1, I) - XP(1, L)) * D(1)
     1                    +  (XP(2, I) - XP(2, L)) * D(2)
     2                    +  (XP(3, I) - XP(3, L)) * D(3)) / AREA
C * Z AND ZO MUST HAVE THE SAME SIGN
                        IF (Z * ZO < -0.001) THEN
                          FACTOR = 0.0
                          EXIT
                        ELSE
C * IF MORE THAN 3 CORNERS ON THIS FACE, THE AREA WILL BE COUNTED TWICE.
C * CHANGE FACTOR TO HANDLE THIS CASE.
                          IF (ABS (Z * ZO) < 0.001) FACTOR = 12.0
                        END IF
                      END IF
                    END DO
                    IF (FACTOR > 0.0) THEN
                      VOL = VOL + AREA * ABS (ZO) / FACTOR
                      DO L = 1, 2
                        NM = IH(L)
                        DO M = L + 1, 3
                          MN   = IH(M)
                          TEMP = 0.0
                          DO N = 1, 3
                            TEMP = TEMP + XP(N, NM) * XP(N, MN)
                          END DO
                          TEMP   = TEMP / (DM(NM) * DM(MN))
                          TEMP   = RGBL(6)
     1                      * ATAN2 (SQRT (ABS (1.0 - TEMP**2)), TEMP)
                          SUMTH  = SUMTH  + TEMP
                          SUMTH2 = SUMTH2 + TEMP**2
                        END DO
                      END DO
                      NA = NA + 3
                    END IF
                  END IF
                END DO
              END DO
            END DO
C * ALL FACES FOUND, CALCULATE QUADRATIC ELONGATION FOR TETRA- AND OCTAHEDRON
            NA     = (NA + 1) / 2
            QE     = 0.0
            VLO    = 0.0
            SIGA   = 0.0
            SUMTH2 = SUMTH2 / 2
            SUMTH  = SUMTH / 2
            IF (NP == 4) THEN
C * SET UP FOR TETRAHEDRON
              CONS = 9.0 * SQRT(3.0) / 8.0
C * CALC LO**2 (= VLO) OF EQUIVALENT VOLUME TETRAEDER
              IF (VOL > 0.0) THEN
                VLO = EXP (2.0 * ALOG (CONS * VOL) / 3.0)
C * CALC LAMBDA (QUADRATIC ELONGATION)
                QE   = SOM4 / (4.0 * VLO)
                SIGA = (SUMTH2 - 2.0 * 109.45 * SUMTH + NA * 109.45**2)
     1               / (NA - 1)
                POLY = 'Tetrahedral'
              ELSE
                POLY = 'Planar'
              END IF
C * TAU(4) CALCULATION
              DO I = 1, 3
                DO J = I + 1, 4
                  TEMP = 0.0
                  DO N = 1, 3
                    TEMP = TEMP + XP(N, I) * XP(N, J)
                  END DO
                  TEMP = TEMP / (DM(I) * DM(J))
                  TEMP = RGBL(6)
     1                 * ATAN2 (SQRT (ABS (1.0 - TEMP * TEMP)), TEMP)
C * REGISTER LARGEST ANGLES
                  IF (TEMP >= ANG1) THEN
                    IF (ANG1 > ANG2) ANG2 = ANG1
                    ANG1 = TEMP
                  ELSE IF (TEMP > ANG2) THEN
                    ANG2 = TEMP
                  END IF
                END DO
              END DO
            ELSE IF (NP == 6) THEN
C * SET UP FOR OCTAHEDRON
              CONS  = 0.75
C * CALC LO**2 (= VLO) OF EQUIVALENT VOLUME OCTAHEDRON
              IF (VOL > 0.0) THEN
                VLO = EXP (2.0 * ALOG (CONS * VOL) / 3.0)
C * CALC LAMBDA (QUADRATIC ELONGATION)
                QE   = SOM6 / (6 * VLO)
                SIGA = (SUMTH2 - 2.0 * 90.0 * SUMTH + NA * 90.0**2)
     1             / (NA - 1)
                POLY = 'Octahedral '
              ELSE
                POLY = 'Planar'
              END IF
            ELSE
              CALL PLA262 (2)
              WRITE (LU7, 99998, IOSTAT = IOST) VOL, NP
            END IF
            IF (IGBL(144) > 0) WRITE (LU6, 99997, IOSTAT = IOST)
     1        NAMS(1, 1)(1:8), VOL, NP
            IF (NP == 4 .OR. NP == 6) THEN
              IF (VOL > 1.0) THEN
                CALL PLA262 (2)
                WRITE (LU7, 99999, IOSTAT = IOST) POLY, VOL, QE, SIGA
                IF (IGBL(144) > 0) WRITE (LU6, 99987, IOSTAT = IOST)
     1            QE, SIGA
                IF (IWIN == 1) THEN
                  VRT = 3.0
                  HRT = 17.0
                  WRITE (LINE, 99991, IOSTAT = IOST) POLY
                  CALL PLA439 (0.0, LINE, 34, 0.30, 5 + IGBL(68), 2,
     1                         HRT, VRT)
                  VRT = VRT - 0.5
                  WRITE (LINE, 99996, IOSTAT = IOST) VOL
                  CALL PLA439 (0.0, LINE, 34, 0.30, 5 + IGBL(68), 2,
     1                         HRT, VRT)
                  VRT = VRT - 0.5
                  WRITE (LINE, 99995, IOSTAT = IOST) QE
                  CALL PLA439 (0.0, LINE, 34, 0.30, 5 + IGBL(68), 2,
     1                         HRT, VRT)
                  VRT = VRT - 0.5
                  WRITE (LINE, 99994, IOSTAT = IOST) SIGA
                  CALL PLA439 (0.0, LINE, 34, 0.30, 5 + IGBL(68), 2,
     1                         HRT, VRT)
                END IF
              END IF
C * 4-COORDINATION - TAU(4)
              IF (NP == 4) THEN
                IF (IGBL(63) > 2) THEN
                  CALL PLA262 (5)
                  WRITE (LU7,   99993, IOSTAT = IOST)
                  WRITE (PRBUF, 99992, IOSTAT = IOST)
     1                   (360.0 - (ANG1 + ANG2)) /  141.0
                  IF (IGBL(144) > 0) WRITE (LU6, 99986, IOSTAT = IOST)
     1                   (360.0 - (ANG1 + ANG2)) /  141.0
                  WRITE (LU7, 99991, IOSTAT = IOST) PRBUF
                  IF (IWIN == 1) THEN
                    VRT = VRT - 0.6
                    CALL PLA439 (0.0, PRBUF, 132, 0.25, 5 + IGBL(68),
     1                    2, 0.2, VRT)
                  END IF
                END IF
              END IF
            END IF
C * LIST COORDINATING ATOM DATA
            IF (IGBL(144) > 0) THEN
              IF (NP .EQ. NPMX) THEN
                WRITE (LU6, 99989)
                DO J = 1, NP
                  WRITE (LU6, 99990) J, CXP(J), (XP(K, J), K = 1, 3),
     1              DM(J)
                END DO
              END IF
            END IF
          END DO
        END IF
      END IF
      RETURN
99999 FORMAT(/, A, ' Volume', F7.3, ' Ang**3, Quadratic Elongation',
     1       F7.3, ', Angle Variance', F7.2, ' Deg**2',
     2       ' [K.Robinson +, Science 1971,172,567-570]')
99998 FORMAT (/, 'Polyhedral Volume', F7.3, ' Ang**3 - Coordn = ', I3)
99997 FORMAT (/, ':: ', A, ' - Polyhedral Volume', F10.3, 1X,
     1        'Ang**3 - Coordn =', I2)
99996 FORMAT ('Volume', 14X, F7.3, ' Ang**3')
99995 FORMAT ('Quadratic Elongation', F7.3)
99994 FORMAT ('Angle Variance', 6X, F7.2, ' Deg**2')
99993 FORMAT (/, 'Tau(4)-Descriptor for 4-Coordination (L.Yang, D.R.',
     1 'Powell, R.P.Houser, Dalton Trans. (2007), 955-964)', /,
     2 132('-'))
99992 FORMAT ('Tau(4) = (360 - (Beta + Alpha)) / 141 =' , F5.2, ' :: ',
     1 '(Extreme Forms: 0.00 for SQP and 1.00 for TET; 0.85 for TRP)')
99991 FORMAT (A)
99990 FORMAT (I5, 2X,  A, 3F10.4, F12.4)
99989 FORMAT (/, 3X, 'Nr', 2X, 'Label', 16X, 'X', 9X, 'Y', 9X, 'Z', 8X,
     1 'Dist')
99988 FORMAT (/, 61('='))
99987 FORMAT ('::', 12X, 'Quadratic Elongation', F7.3, /,
     1        '::', 12X, 'I-O-J Angle Variance', F7.2, ' Deg**2')
99986 FORMAT ('::', 12X, 'Tau(4)', 16X , F5.2)
      END SUBROUTINE PLA279
 
      SUBROUTINE PLA280 (STR)
C * AUTO INSTRUCTIONS - EMULATE COMMAND IN 'STR' AS GRAPHICAL INPUT
      USE parameters
      USE cggt
      USE files
      IMPLICIT NONE
      INTEGER :: LENM
      CHARACTER(len=*) :: STR
      LENM = MIN (80, LEN (STR))
      IGGT = STR(1:LENM)
      IF (IGBL(74) == 1) WRITE (LU6, 99999) STR(1:LENM)
      RETURN
99999 FORMAT ('<< 280-IGGT-Instruction : ', A, /)
      END SUBROUTINE PLA280
 
      SUBROUTINE PLA281 (MODE, NQ, MSUBST)
C * ALIAS SUBSTITUTION
      USE parameters
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: MODE
      INTEGER :: MSUBST
      INTEGER :: NALIAS
      CHARACTER(len=NP64) :: NQ
C * HANDLE ALIASES
      MSUBST = 0
      NALIAS = IPR(759)
      IF (NALIAS > 0) THEN
        CALL GEN020 (-1, NQ, 2, 2)
C * TRANSLATE NQ TO ALAB
        IF (MODE == -1) THEN
          DO I = 1, NALIAS
            IF (BLAB(I) == NQ) THEN
              NQ     = ALAB(I)
              MSUBST = MODE
              EXIT
            END IF
          END DO
C * TRANSLATE NQ TO BLAB
        ELSE IF (MODE == 1) THEN
          DO I = 1, NALIAS
            IF (ALAB(I) == NQ) THEN
              NQ     = BLAB(I)
              MSUBST = MODE
              EXIT
            END IF
          END DO
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA281
 
      SUBROUTINE PLA282 (MODE, NQA, NQB, LU)
C * ALIAS SUBSTITUTION (REGISTER & LISTING)
      USE parameters
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: MODE
      CHARACTER(len=NP64) :: NQA
      CHARACTER(len=NP64) :: NQB
C * GET # OF LABEL ALIASES
      N = IPR(759)
C * ADD ALIAS RELATION
      IF (MODE == 1) THEN
        N        = N + 1
        IPR(759) = N
        NQ1      = NQA
        CALL GEN020 (-1, NQ1, 2, 2)
        ALAB(N) = NQ1
        BLAB(N) = NQB
C * LIST ALIASES
      ELSE IF (MODE == -1 .AND. N > 0) THEN
        WRITE (LU, 99999)
        DO I = 1, N, 3
          M = MIN (2, N - I)
          WRITE (LU, 99998)
     1      (I + J, ALAB(I + J), BLAB(I + J)(1:6), J = 0, M)
        END DO
      END IF
99999 FORMAT (80('='), /,
     1':: Temp. ALIASES used for ATOM labels that',
     2 ' are unsuitable for PLATON/checkCIF', /, 80('='))
99998 FORMAT (3(I4, 1X, A, ' > ', A))
      RETURN
      END SUBROUTINE PLA282
 
      SUBROUTINE PLA283 (MODE, XMZ, N, CDUMMY)
C * GENERATE MOIETY & SUM STRINGS
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: K0
      INTEGER :: N0
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: K1
      INTEGER :: KB
      INTEGER :: KE
      INTEGER :: KZ
      INTEGER :: IP
      INTEGER :: KZZ
      INTEGER :: IP0
      INTEGER :: IOST
      INTEGER :: MINT
      INTEGER :: MODE
      INTEGER :: INTT
      INTEGER :: INTTA
      INTEGER :: INTTB
      INTEGER :: IMODE
      INTEGER, DIMENSION(NP10) :: IENSS
      REAL :: XKZ
      REAL :: XMZ
      REAL :: CKK1
      CHARACTER(NP52) :: JDM
      CHARACTER(NP52) :: CDUMMY
      XKZ = 0.0
      KZ  = 0
C * MODE = 0 - MOIETY  FORMULA
C * MODE = 1 - RESIDUE FORMULA
C * MODE = 2 - SUM     FORMULA
      N = NP52 + 1
C * SPECIFIC 'MOIETY' NUMBER
      IF (MODE /= 0) THEN
        KB = MODE
        KE = MODE
C * MOIETY FORMULA MODE
      ELSE IF (MODE == 0) THEN
        KB = 4
        KE = IPR(488)
      END IF
      DO K0 = KB, KE
        K1 = KB + KE - K0
C * CHECK FOR CARBON /NON-CARBON FORMULA MODE
        IMODE = 0
        DO I = 1, IAN
          IF (IEN(I) == 2) THEN
            IF (CONT(I, K1) > 0.001) THEN
              IMODE = 1
              EXIT
            END IF
          END IF
        END DO
C * ORDER ELEMENTS IN FORMULA
        CALL GEN123 (IMODE, IEN, IENSS, IEL, IAN)
        N0 = NP52 + 1
        DO I = 1, IAN
          K = IENSS(IAN + 1 - I)
C * EXCLUDE 'Cg'
          IF (LMT(K, 1) /= 'Cg') THEN
            CKK1 = CONT(K, K1)
            IF (CKK1 > 0.001) THEN
              M = NINT (CKK1 / XMZ)
              IF (ABS (M * XMZ - CKK1) > XMZ * PAR(331)) THEN
C * ROUND UP
                CKK1 = CKK1 / XMZ
                INTT = INT (CKK1 * 1000.0 + 0.01)
                MINT = MOD (INTT, 10)
                IF (MINT > 4) INTT = INTT + 10 - MINT
                INTTA = INTT / 1000
                INTTB = MOD (INTT, 1000) / 10
                WRITE (NQ1, 99998, IOSTAT = IOST) INTTA, INTTB
                IF (CKK1 < 10.0) THEN
                  IP = 4
                ELSE IF (CKK1 < 100.0) THEN
                  IP = 5
                ELSE
                  IP = 6
                END IF
                N0 = N0 - IP
                JDM(N0:N0 + IP - 1) = NQ1 (8 - IP:7)
              ELSE
                IP = 0
                IF (M > 1) THEN
                  CALL GEN040 (M, NQ1, IP)
                  N0 = N0 - IP
                  JDM(N0:N0 + IP - 1) = NQ1(1:IP)
                END IF
              END IF
              N0 = N0 - 1
              JDM(N0:N0) = LMT(K, 1)(2:2)
              IF (LMT(K, 1)(1:1) /= CHAR (32)) THEN
                N0 = N0 - 1
                JDM(N0:N0) = LMT(K, 1)(1:1)
              END IF
              N0         = N0 - 1
              JDM(N0:N0) = CHAR (32)
            END IF
          END IF
        END DO
        IF (N0 < NP52 + 1) THEN
          IF (JDM(N0:N0) == CHAR (32)) N0 = N0 + 1
        END IF
        IF (MODE == 0) THEN
          XKZ = CONT(NP10 + 1, K1) * 2 / IPR(260)
          KZ  = NINT (CONT(NP10 + 1, K1) * 2) / IPR(260)
          IF (ABS (XKZ - KZ) > 0.0015 * KZ) THEN
            KZ = 0
          END IF
          IF (KZ /= 2) THEN
            IF (N == 1) RETURN
            N = N - 1
            CDUMMY(N:N) = ')'
          END IF
        END IF
        DO N1 = N0, NP52
          N2 = NP52 + N0 - N1
          IF (N == 1) RETURN
          N  = N  - 1
          CDUMMY(N:N) = JDM(N2:N2)
        END DO
        IF (MODE == 0) THEN
          IP0 = 1
          IF (KZ /= 2) THEN
            IF (KZ == 0) THEN
              IP = 6
              IF (XKZ / 2.0 < 10.0) IP0 = 2
              WRITE (NQ1(1:IP), 99999, IOSTAT = IOST) XKZ / 2.0
              IF (NQ1(5:6) == '00') THEN
                IP = 4
              ELSE IF (NQ1(6:6) == '0') THEN
                IP = 5
              END IF
            ELSE IF (MOD (KZ, 2) == 1) THEN
              IP = 3
              WRITE (NQ1(1:IP), 99997, IOSTAT = IOST)
     1         (KZ + 0.00001) / 2.0
            ELSE
              KZZ = KZ / 2
              CALL GEN040 (KZZ, NQ1, IP)
            END IF
            IF (N < IP + 2) RETURN
            N = N - 1
            CDUMMY(N:N) = '('
            CDUMMY(N - IP + IP0 - 1:N - 1) = NQ1(IP0:IP)
            N = N - IP + IP0 - 1
          END IF
          IF (K0 /= KE) THEN
            IF (N <= 2) RETURN
            N = N - 1
            CDUMMY(N:N) = CHAR (32)
            N = N - 1
            CDUMMY(N:N) = ','
          END IF
        END IF
      END DO
      IF (N > 1) CALL GEN038 (CDUMMY, 1, N - 1)
      RETURN
99999 FORMAT (F6.3)
99998 FORMAT (I4, '.', I2.2)
99997 FORMAT (F3.1)
      END SUBROUTINE PLA283
 
      MODULE strain2
      SAVE
      REAL, DIMENSION(12)   :: C
      REAL, DIMENSION(3, 3) :: Q
      REAL, DIMENSION(13)   :: S
      REAL, DIMENSION(2, 6) :: VC
      REAL, DIMENSION(3, 3) :: QI
      REAL, DIMENSION(13)   :: FO
      REAL, DIMENSION(3, 3) :: DC
      END MODULE strain2
 
      SUBROUTINE PLA284 (MORT, JID)
C ******************************************************************
C * STRAIN TENSOR CALCULATION PROGRAM FROM TWO SETS OF CELL PARAMETERS
C * VERSION 1 (1972). CODED BY Y.OHASHI, GEOPHYSICAL LABORATORY,
C * CARNEGIE INSTITUTION C OF WASHINGTON. ADAPTED FOR PLATON 2015
C ******************************************************************
      USE parameters
      USE strain1
      USE strain2
      USE files
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: LU
      INTEGER :: MODE
      INTEGER :: MORT
      INTEGER :: MORTH
      INTEGER :: ITEMP
      REAL :: EX
      REAL :: PX
      REAL :: PY
      REAL :: RHO
      REAL :: PHI
      REAL :: RAD
      REAL :: DET
      REAL :: DTEM
      REAL :: TEMP
      REAL :: TEMP1
      REAL, DIMENSION(3, 3) :: E
      REAL, DIMENSION(3)    :: AN
      REAL, DIMENSION(3, 3) :: EVC
      REAL, DIMENSION(3, 3) :: DUM
      REAL, DIMENSION(3)    :: EVL
      REAL, DIMENSION(3, 3) :: YUNK
      CHARACTER(len=*)  :: JID
      CHARACTER(len=1)  :: IZ
      CHARACTER(len=80) :: LINE
      CHARACTER(len=70) :: TXT1
      CHARACTER(len=70) :: TXT2
      CHARACTER(len=2),  DIMENSION(6) :: IAX
      CHARACTER(len=54), DIMENSION(2) :: TXT3
      IAX = (/ '+X', '+Y', '+Z', '+A', '+B', '+C'/)
      TXT1 = 'Axis      Strain  Unit Strain (* 1000000)   Angle With'
      TXT2 =
     1'                                     +A         +B         +C'
      TXT3(1) =
     1 'x//a, z//c*, y//z^x (Dunitz p236)'
      TXT3(2) =
     1 'z//c, x//a*, y//z^x (Hazen & Finger, Comp.Cryst.Chem.)'
      PAGET = 'STRAIN'
      RAD   = RGBL(6)
C * MORT = 1 - DUNITZ STYLE ORTHOGONALIZATION
C *      = 2 - HAZEN & FINGER STYLE ORTHOGONALISATION
      MORTH = - IABS(MORT)
      DO MODE = 1, 2
        IF (MODE == 1) THEN
          LU = LU6
        ELSE
          LU = LU7
          CALL PLA262 (0)
          CALL GGIP (HORS, VERT, 0.0, 1)
          CALL PLA110 (HORS, VERT, -1)
          CALL GGIP (0.0, 0.0, 0.0, 6)
          BCD = 'Strain Analysis'//CHAR (0)
          CALL PLA439 (0.0,  BCD, 15, 1.4, 4, 8, 4.0, VERT - 1.8)
          CALL PLA439 (0.0,  BCD, 15, 1.4, 2, 8, 3.8, VERT - 1.9)
        END IF
C * WRITE JOB-NAME
        WRITE (LU, 99999, IOSTAT = IOST) JID, TXT3(MORT)
C * WRITE CELL PARAMETERS (+ CELLSU) AND TEMPERATURES
        DO K = 1, 2
          WRITE (LINE, 99998, IOSTAT = IOST)
     1      NINT (TEMPAB(K)), (CELAB(K, I), I = 1, 6)
          WRITE (LU, 99983, IOSTAT = IOST) LINE(1:78)
          IF (MODE == 2) THEN
            IF (K == 1) THEN
              VRT = VERT - 3.0
              CALL PLA439 (0.0, 'Cell Parameters - Orth: '//TXT3(MORT),
     1                     78, 0.37, 5 + IGBL(68), 2, 1.0, VRT)
            END IF
            VRT = VRT - 1.0
            CALL PLA439 (0.0, LINE, 78, 0.3, 1, 2, 1.0, VRT)
          END IF
          IF (ICV(K) == 1) THEN
            WRITE (LINE, 99986, IOSTAT = IOST) (VCAB(K, J), J = 1, 6)
            WRITE (LU, 99983, IOSTAT = IOST) LINE(1:78)
            IF (MODE == 2) THEN
              VRT = VRT - 1.0
              CALL PLA439 (0.0, LINE, 78, 0.3, 1, 2, 1.0, VRT)
            END IF
          END IF
        END DO
        DO I = 1, 3
          C(I)     = CELAB(1, I)
          C(I + 3) = COS (CELAB(1, I + 3) / RAD)
          C(I + 6) = CELAB(2, I)
          C(I + 9) = COS (CELAB(2, I + 3) / RAD)
        END DO
        DO I = 1, 2
          IF (ICV(I) == 1) THEN
            DO J = 1, 3
              VC(I, J + 3) = (VCAB(I, J + 3) / RAD)**2
              VC(I, J)     = VCAB(I, J)**2
            END DO
          END IF
        END DO
        DTEM = TEMPAB(2) - TEMPAB(1)
C * INVERSE ORTHOGONALISATION MATRIX FOR FIRST CELL
        CALL GEN044 (C(1), DC, MORTH)
C * TRANSPOSE DC => Q
        CALL GEN005 (DC, Q)
C * INVERT
        CALL GEN003 (Q, QI, DET, 0)
C * ORTHOGONALISATION MATRIX FOR SECOND CELL
        CALL GEN044 (C(7), Q, MORTH)
C * TRANSPOSE MATRIX
        CALL GEN005 (Q, YUNK)
C * COPY MATRIX
        CALL GEN052 (YUNK, Q)
C * E =  QI * Q
        CALL GEN004 (QI, Q, E)
C * ASYMMETRIC STRAIN TENSOR: E = QI * Q - I
        DO I = 1, 3
          E(I, I) = E(I, I) - 1.0
        END DO
        WRITE (LU, 99981, IOSTAT = IOST)
     1    NINT (TEMPAB(1)), NINT (TEMPAB(2)), ((DC(I, J), J = 1, 3),
     2    (Q(J, I),  J = 1, 3), (E(I, J) * 1.0E+6, J = 1, 3), I = 1, 3)
        DO I = 1, 3
          DO J = 1, 3
            DC(I, J) = DC(I, J) / C(J)
          END DO
        END DO
C * SYMMETRIC STRAIN TENSOR Epsilon
        DO I = 1, 3
          DO J = I, 3
            E(I, J) = 0.5 * (E(I, J) + E(J, I))
            E(J, I) = E(I, J)
          END DO
        END DO
C * Write angles between XYZ and ABC systems & (Unit)Strain Tensor
        DO K = 1, 2
          IF (K == 1) THEN
            WRITE (LU, 99992, IOSTAT = IOST) '     '
          ELSE
            WRITE (LU, 99992, IOSTAT = IOST) 'Unit '
          END IF
          WRITE (LU, 99982, IOSTAT = IOST)
          DO I = 1, 3
            DO J = 1, 3
              AN(J) = RAD * ACOS (DC(I, J))
            END DO
            IF (K == 1) THEN
              WRITE (LU, 99991, IOSTAT = IOST)
     1          IAX(I), AN, (E(I, J) * 1.0E+6, J = 1, 3)
            ELSE
              WRITE (LU, 99980, IOSTAT = IOST)
     1        IAX(I), AN, (E(I, J) * 1.0E+6 / DTEM, J = 1, 3)
            END IF
          END DO
        END DO
C * EIGEN VECTOR/VALUE
        CALL GEN024 (E, EVC, EVL, DUM)
        WRITE (LU, 99993, IOSTAT = IOST)
        DO I = 1, 3
          DO J = 1, 3
            AN(J) = RAD * ACOS (EVC(I, J))
          END DO
C * RHO-PHI AND PROJECTION COORDINATES
          RHO = AN(3)
          PHI = ATAN2 (EVC(I, 2), EVC(I, 1))
          IF (EVC(I, 3) < 0.0) THEN
            IZ   = '-'
            TEMP = TAN ((180.0 - RHO) / (2.0 * RAD)) * 100.0
          ELSE
            IZ   = '+'
            TEMP = TAN (RHO / (2.0 * RAD)) * 100.0
          END IF
          PX  = TEMP * COS (PHI)
          PY  = TEMP * SIN (PHI)
          PHI = PHI  * RAD
          EX  = EVL(I) / DTEM
          WRITE (LU, 99996, IOSTAT = IOST)
     1      I, EVL(I) * 1.0E+6, EX * 1.0E+6, AN, RHO, PHI, PX, PY, IZ
        END DO
C * CALCULATE DIRECTIONS OF A,B,C AXES WITH RESPECT TO X,Y,Z AXES
        WRITE (LU, 99988, IOSTAT = IOST)
        DO K = 1, 3
          DO J = 1, 3
            AN(J) = ACOS (DC(J, K)) * RAD
          END DO
          RHO = AN(3)
          IF (ABS (DC(2, K)) < 0.0000001 .AND.
     1        ABS (DC(1, K)) < 0.0000001) THEN
            PHI = ATAN2 (DC(2, K), DC(1, K))
          ELSE
            PHI = 0.0
          END IF
          IF (DC(3, K) < 0.0) THEN
            IZ   = '-'
            TEMP = TAN ((180.0 - RHO) / (2.0 * RAD)) * 100.0
          ELSE
            IZ   = '+'
            TEMP = TAN (RHO / (2.0 * RAD)) * 100.0
          END IF
          PX  = TEMP * COS (PHI)
          PY  = TEMP * SIN (PHI)
          PHI = PHI * RAD
          WRITE (LU, 99990, IOSTAT = IOST)
     1      IAX(3 + K), AN, RHO, PHI, PX, PY, IZ
        END DO
C * RESULT ANALYSIS
        IF (MODE == 2) CALL PLA262 (0)
        WRITE (LU, 99994, IOSTAT = IOST) TXT1, TXT2
        IF (MODE == 2) THEN
          VRT = VRT - 2.0
          CALL PLA439 (0.0, TXT1, 70, 0.3, 5 + IGBL(68), 2, 1.0, VRT)
          VRT = VRT - 1.0
          CALL PLA439 (0.0, TXT2, 70, 0.3, 5 + IGBL(68), 2, 1.0, VRT)
        END IF
        DO I = 1, 3
          DO J = 1, 3
            TEMP = 0.0
            DO K = 1, 3
              TEMP = TEMP + EVC(I, K) * DC(K, J)
            END DO
            FO(3 * J + I) = ACOS (TEMP)
          END DO
          FO(I) = EVL(I)
        END DO
        TEMP   = EVL(1) + EVL(2) + EVL(3)
        FO(13) = TEMP
        ITEMP  = ICV(1) + ICV(2)
C * GET SU'S
        IF (ITEMP /= 0) CALL PLA285 (MORTH)
        DO I = 1, 3
          DO J = 1, 3
            AN(J) = RAD * FO(3 * J + I)
          END DO
          TEMP  = EVL(I) / DTEM
          TEMP1 = S(I)   / DTEM
          WRITE (LINE, 99995, IOSTAT = IOST)
     1      I, EVL(I) * 1.0E+6, TEMP * 1.0E+6, (AN(J), J = 1, 3)
          WRITE (LU, 99983, IOSTAT = IOST) LINE
          IF (MODE == 2) THEN
            VRT = VRT - 1.0
            CALL PLA439 (0.0, LINE, 78, 0.3, 1, 2, 1.0, VRT)
          END IF
          IF (ITEMP /= 0) THEN
            WRITE (LINE, 99997, IOSTAT = IOST)
     1        S(I) * 1.0E+6, TEMP1 * 1.0E+6, (S(3 * J + I), J = 1, 3)
            WRITE (LU, 99983, IOSTAT = IOST) LINE
            IF (MODE == 2) THEN
              VRT = VRT - 1.0
              CALL PLA439 (0.0, LINE, 78, 0.3, 1, 2, 1.0, VRT)
            END IF
          END IF
        END DO
        TEMP  = FO(13) / DTEM
        TEMP1 = S(13)  / DTEM
        WRITE (LU, 99987, IOSTAT = IOST)
     1   FO(13) * 1.0E+6, S(13) * 1.0E+6, TEMP * 1.0E+6, TEMP1 * 1.0E+6
C * LIST EXPLANATION
        IF (MODE == 2) THEN
          IF (MORT == 1) THEN
            CALL PLA262 (0)
            WRITE (LU, 99985, IOSTAT = IOST)
          END IF
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
        END IF
      END DO
      RETURN
99999 FORMAT ('Titl: ', A, /, 'Cell Parameters - Orth: ', A, /,
     1  78('='))
99998 FORMAT ('At', I6, 'C:', 6(F11.5))
99997 FORMAT (6X, '(', F9.2, ')  (', F9.4, ')',
     1        3(4X, '(', F5.2, ')'))
99996 FORMAT (2X, I1, F13.2, F11.4, 3F6.1, 2X, F5.1,
     1        F7.1, 2F7.1, 4X, A)
99995 FORMAT (2X, I1, F13.2, F13.4, 3(F11.2))
99994 FORMAT (/, A, /, 78('='), /, A)
99993 FORMAT (/, 'Strain Ellipsoid (Strain values multiplied by 10^6)',
     1 /, 51('='), /, 'Axis', 6X,
     1 'Strain', 2X, 'Unit Strain', 4X, 'Angle With', 6X,
     2 'Rho', 4X, 'Phi', 1X, 'Proj.X Proj.Y Hemi', /, 78('='), /,
     3 31X, '+X', 4X, '+Y', 4X, '+Z')
99992 FORMAT (/, 'Angles Between XYZ and ABC Systems', 5X, A,
     1           'Strain Tensor * 10^6 Based on XYZ')
99991 FORMAT (A, 1X, 3F9.2, 10X, '(', 3F9.2, ')')
99990 FORMAT (A, '-Axis', 20X, 3F6.1, F7.1, F7.1, 2F7.1, 4X, A)
99988 FORMAT (/, 'Crystallographic Axes', /, 78('='))
99987 FORMAT (/, 'Volume * 1000000', 1X, F10.2, '(', F10.2, ')', /,
     1            '(Unit Vol)', 7X, F10.4, '(', F10.4, ')', /)
99986 FORMAT (11X, 6(2X, '(', F7.5, ')'))
99985 FORMAT ('Explanation of the Printout', //, 'See:', /,
     1'Y.Ohashi & C.W. Burnham (1973). Amer. Mineralogist, 58, 843-849'/
     2'R.M. Hazen & L.W. Finger (1982). Comparative Crystal Chemistry,'/
     3'Wiley & Sons, Chapter #5.', /,
     4'**************************************************************'//
     5'1. ABC and XYZ coordinate systems:', /,
     6'   Direction of principle axis of strain ellipsoid is given in',/
     7'   terms of two coordinate systems. A,B and C are the', /
     8'   crystallographic axes and can be oblique. X,Y and Z are', /,
     9'   orthogonal axes set up in the program. angular relations,', /,
     *'   between ABC and XYZ systems are printed.', //,
     1'2. Dimensions of strain and unit strain:', /,
     2'   Strain is dimensionless (change in length original length),',/
     3'   and unit strain is (strain per unit change of temperature', /,
     4'   or composition)', //,
     5'3. Polar coordinates and stereographic projection coordinates:',/
     6'   System XYZ is used for stereo projection axes with Z', /,
     7'   being the azimuthal axis.', /,
     8'   RHO is an azimuthal angle and PHI is a longitudinal angle,', /
     9'   Thus X(RHO=90, PHI=0), Y(RHO=90, PHI=90) and Z(RHO=0).', /,
     *'   Proj.X and Proj.Y are projected components on a stereo-', /,
     1'   graphic projection plane and scaled as RADIUS=100.', /,
     2'   + and - denote upper and lower hemispheres respectively.', //,
     3'   To obtain stereographic projection of principle axes and', /,
     4'   also of crystallographic axes, plot Proj.X and Proj.Y on', /,
     5'   graph paper and draw a circle with radius 100.')
99983 FORMAT (A)
99982 FORMAT (77('='), /, 9X, '+A', 7X, '+B', 7X, '+C')
99981 FORMAT (/, 'Orth.', I9, 'C', 19X, I4, 'C', 14X,
     1 'Asymmetric Tensor * 10^6', /, 78('='),
     2 3(/, '(', 3F7.3, ') (', 3F7.3, ')  (', 3F9.2, ')'))
99980 FORMAT (A, 1X, 3F9.2, 10X, '(', 3F9.4, ')')
      END SUBROUTINE PLA284
 
      SUBROUTINE PLA285 (MORTH)
C * STRAIN
      USE parameters
      USE strain1
      USE strain2
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: II
      INTEGER :: JJ
      INTEGER :: IP
      INTEGER :: LP
      INTEGER :: MORTH
      REAL :: RAD
      REAL :: DEL
      REAL :: DET
      REAL :: TEMP
      REAL, DIMENSION(13)     :: F
      REAL, DIMENSION(12, 13) :: D
      REAL, DIMENSION(3, 3)   :: A
      REAL, DIMENSION(3, 3)   :: B
      REAL, DIMENSION(3, 3)   :: R
      REAL, DIMENSION(3, 3)   :: E
      REAL, DIMENSION(3)      :: XX
      REAL, DIMENSION(3, 3)   :: VV
      REAL, DIMENSION(3, 3)   :: DUM
      REAL, DIMENSION(3, 3)   :: YUNK
      RAD = RGBL(6)
C * DETERMINE DERIVATIVES OF EIGEN VALUES AND DIRECTION COSINES WITH RESPECT
C * TO CELL CONSTANTS
      DO I = 1, 2
        DO J = 1, 6
          M = (I - 1) * 6 + J
          IF (VC(I, J) <= 1.E-10) THEN
            DO K = 1, 13
              D(M, K) = 0.0
            END DO
          ELSE
            DEL = 0.1 * SQRT (VC(I, J))
            IF (J <= 3) THEN
              C(M) = C(M) + DEL
            ELSE
              C(M) = COS (ACOS (C(M)) + DEL)
            END IF
C * CHANGE OF QI OR Q MATRICES
            IF (I. EQ. 1) THEN
C * ORTHOGONALIZE
              CALL GEN044 (C(1), R, MORTH)
              CALL GEN005 (R, DUM)
C * INVERT
              CALL GEN003 (DUM, A, DET, 0)
              CALL GEN052 (Q, B)
              DO II = 1, 3
                DO JJ = 1, 3
                  R(II, JJ) = R(II, JJ) / C(JJ)
                END DO
              END DO
            ELSE
C * ORTHOGONALIZE
              CALL GEN044 (C(7), B, MORTH)
C * TRANSPOSE MATRIX
              CALL GEN005 (B, YUNK)
C * COPY MATRIX
              CALL GEN052 (YUNK, B)
              CALL GEN052 (QI, A)
              CALL GEN052 (DC, R)
            END IF
            CALL GEN004 (A, B, E)
            DO L = 1, 3
              E(L, L) = E(L, L) - 1.0
            END DO
            DO L = 1, 3
              DO N = L, 3
                E(L, N) = 0.5 * (E(L, N) + E(N, L))
                E(N, L) = E(L, N)
              END DO
            END DO
C * EIGENVECTOR/EIGENVALUE
            CALL GEN024 (E, VV, XX, DUM)
            DO L = 1, 3
              F(L) = XX(L)
              DO N = 1, 3
                TEMP = 0.0
                DO K = 1, 3
                  TEMP = TEMP + VV(L, K) * R(K, N)
                END DO
                F(3 * N + L) = ACOS (TEMP)
              END DO
            END DO
            F(13) = F(1) + F(2) + F(3)
            DO K = 1, 13
              D(M, K) = (F(K) - FO(K)) / DEL
            END DO
C * RESTORE TO ORIGINAL CELL PARAMETER VALUE
            IF (J <= 3) THEN
              C(M) = C(M) - DEL
            ELSE
              C(M) = COS (ACOS (C(M)) - DEL)
            END IF
          END IF
        END DO
      END DO
      CALL GEN074 (S, 1, 13, 0.0)
C * VARIANCE CALCULATION
      DO I = 1, 2
        L = 6 * (I - 1)
        IF (ICV(I) == 1) THEN
C * ZERO COVARIANCE CASE
          DO K = 1, 13
            TEMP = 0.0
            DO IP = 1, 6
              LP   = L + IP
              TEMP = TEMP + D(LP, K)**2 * VC(I, IP)
            END DO
            S(K) = S(K) + TEMP
          END DO
C * NON-ZERO COVARIANCE CASE
        END IF
      END DO
      DO K = 1, 3
        S(K) = SQRT (S(K))
      END DO
      DO K = 4, 12
        S(K) = RAD * SQRT (S(K))
      END DO
      S(13) = SQRT (S(13))
      RETURN
      END SUBROUTINE PLA285
 
      SUBROUTINE PLA286 (MODE)
C * RESET INPUT FOR THIS ENTRY
      USE files
      USE parameters
      IMPLICIT NONE
      INTEGER :: MODE
      WRITE (LU6, 99999) MODE
C * DELETE THE COPIES OF THE EMBEDDED FILES
      IF (IPR(663) /= 0) THEN
        CLOSE (LU24, STATUS = 'DELETE', IOSTAT = IOST)
        IPR(663) = 0
      END IF
      IF (IPR(664) /= 0 .OR. IPR(321) /= 0) THEN
        CLOSE (LU25, STATUS = 'DELETE', IOSTAT = IOST)
        IPR(664) = 0
      END IF
      IF (IPR(665) /= 0) THEN
        CLOSE (LU26, STATUS = 'DELETE', IOSTAT = IOST)
        IPR(665) = 0
      END IF
C * REWIND BINARY ALERT FILE
      REWIND (UNIT = LU68, IOSTAT = IOST)
C * CHECK FOR SPF OR CIF FILE
      IF (IABS (IGBL(8)) == 1 .OR. IABS (IGBL(8)) == 3) THEN
        IPR(220) = 0
        IPR(221) = 1
        FN(1)    = IGBL(54)
C * SEARCH AND LOAD ENTRY
        CALL PLA007
        IGBL(24) = 0
        CALL PLA280 ('END')
        IF (MODE /= 0) IGBL(1) = 1
      ELSE
        IGBL(54) = 0
        CALL PLA280 ('RESTART')
        IF (MODE /= 0) IGBL(1) = 2
      END IF
C * REWIND CHECK-SCRATCH FILE
      IF (MODE == 0) THEN
        CALL GEN108 (LU20, 0)
        IGBL(31) = 0
      END IF
      RETURN
99999 FORMAT (/, ':: Reset Input, Mode =', I3)
      END SUBROUTINE PLA286
 
      SUBROUTINE PLA287 (MODE1, MODE2, MODE3)
      USE parameters
      IMPLICIT NONE
      INTEGER :: MODE1
      INTEGER :: MODE2
      INTEGER :: MODE3
C * SETUP CONNECTED SET
      CALL PLA067
      IF (IPR(2) == 0) THEN
C * OUTPUT COORDINATES AND CONNECTION TABLES
        IF (MODE2 /= 0) CALL PLA073 (-1, 1)
C * LIST ANISOTROPIC PARAMETERS
        IF (IPR(85) == 0) THEN
          CALL PLA024
        END IF
C * LOAD & EXPAND COORDINATE DATA
        IF (MODE1 /= 0) CALL PLA023 (MODE3)
      END IF
      RETURN
      END SUBROUTINE PLA287
 
      SUBROUTINE PLA288 (MODE)
C * DEFINE BOND
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: IP
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: NCG
      INTEGER :: NFN
      INTEGER :: IENM
      INTEGER :: ICGA
      INTEGER :: MODE
      INTEGER :: NIEN
      INTEGER :: INQNR
      INTEGER :: JNQNR
      REAL :: DASH
      DASH = 1.0
      NCG  = 0
      NFN  = 0
C * DEFINE BOND
      DO I = 2, IPR(220)
        IF (IFL(I) == 'DASH') THEN
          DASH = -1.0
        ELSE IF (IFL(I) == 'NODASH') THEN
          DASH = 2.0
        ELSE IF (IFL(I) == 'LDASH') THEN
          DASH = -2.0
        ELSE IF (IFL(I) == 'TO') THEN
          NCG  = 1
          IPR(64) = IPR(64) + 1
          ICGA = IPR(39) + IPR(64)
          DO J = 1, 6
            XXO(ICGA, J) = 0.0
            XSD(ICGA, J) = 0.0
          END DO
        ELSE
C * LOOK IN EXPANDED + CG ATOM LIST
          CALL PLA046 (4, IFL(I), IENM, LBB, LBC, LBD,
     1                 INQNR, JNQNR, NIEN)
          IF (NIEN < 0) THEN
            CALL PLA015 (0, 28)
            RETURN
          END IF
          NFN       = NFN + 1
          IATC(NFN) = NIEN
        END IF
      END DO
      DO J = 2, NFN
        CALL PLA268 (IATC(1), IATC(J), MODE, DASH)
        IF (NCG == 1) THEN
          DO K = 1, 6
            XXO(ICGA, K) =  XXO(ICGA, K) + XXO(IATC(J), K)
            XSD(ICGA, K) =  XSD(ICGA, K) + XSD(IATC(J), K)
          END DO
        END IF
      END DO
      IF (NCG == 1) THEN
        DO K = 1, 3
          IFG(K, ICGA) = IFG(K, IATC(2))
        END DO
C * GENERATE NEW LABEL CGnm
        CALL GEN040 (IPR(64), NQ2, IP)
        NQ1           = 'CG'
        NQ1(3:2 + IP) = NQ2(1:IP)
        CALL PLA046 (1, NQ1, IENM, LBB, LBC, LBD,
     1               INQNR, JNQNR, NIEN)
        LABA(ICGA) = INQNR
C * STORE COORDINATES (ALSO IN BACKING STORE)
        DO K = 1, 6
          XXO(ICGA, K) = XXO(ICGA, K) / (NFN - 1)
          XSD(ICGA, K) = XSD(ICGA, K) / ((NFN - 1)**2)
          VOID((IPR(39) + IPR(64) - 1) * NP71 + K) =
     1              XXO(ICGA, K)
          VOID((IPR(39) + IPR(64) - 1) * NP71 + K + 6) =
     1              XSD(ICGA, K)
        END DO
        WRITE (LU6, 99999, IOSTAT = IOST)
     1    NQ1(1:7), (XXO(ICGA, K), K = 1, 6),
     2    (SQRT (XSD(ICGA, K)), K = 1, 6)
        WRITE (LU7, 99999, IOSTAT = IOST)
     1    NQ1(1:7), (XXO(ICGA, K), K = 1, 6),
     2    (SQRT (XSD(ICGA, K)), K = 1, 6)
        CALL PLA268 (IATC(1), ICGA, 1, -1.0)
      END IF
      RETURN
99999 FORMAT (/, ':: ', A, 6F10.5, /, 10X, 6F10.5)
      END SUBROUTINE PLA288
 
      SUBROUTINE PLA289 (X, Y, R, N)
C * PLOT CIRCLE
      USE parameters
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      REAL :: X
      REAL :: Y
      REAL :: R
      REAL :: RT0
      RT0 = RGBL(5) / N
      CALL GGIP (X + R, Y, 0.0, 3)
      DO I = 1, N
        XGGIP = X + R * COS (I * RT0)
        YGGIP = Y + R * SIN (I * RT0)
        CALL GGIP (XGGIP, YGGIP, 0.0, 2)
      END DO
      CALL GGIP (0.0, 0.0, 0.0, 3)
      RETURN
      END SUBROUTINE PLA289
 
      SUBROUTINE PLA292
C * FILE OPEN ON UNIT LU2
      USE files
      USE parameters
      USE cchar
      IMPLICIT NONE
      CHARACTER(len=80) :: FNLU2
      CHARACTER(len=80) :: FILEN
C * IGBL(31) =  -3 :  _sx.ins
C *             -2 :  _pl.res
C *             -1 :  _pl.res
C *              1 :     .ome
C *              3 :  _pl.spf
C *              4 :     .que
C *              5 :     .par
C *              6 :     .res
C *              7 :  _pl.pdb
C *              8 : -acc.cif
C *             10 : _sqd.sqz or _sq.sqz
C *             11 :     .dif
      IF (IGBL(31) /= IPR(437)) THEN
        SELECT CASE (IGBL(31))
          CASE (-3)
            FNLU2 = NAMEFIL(1:KNMFIL)//'_sx.ins'
            INQUIRE (UNIT = LU24, OPENED = OPEND)
            IF (OPEND) CLOSE (UNIT = LU24)
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (-2)
            INQUIRE (UNIT = LU2, OPENED = OPEND)
            IF (OPEND) CLOSE (UNIT = LU2)
            INQUIRE (UNIT = LU21, OPENED = OPEND)
            IF (OPEND) CLOSE (UNIT = LU21)
            FNLU2 = NAMEFIL(1:KNMFIL)//'_pl.res'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (-1)
            FNLU2 = NAMEFIL(1:KNMFIL)//'_pl.res'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (1)
            IPR(438) = 1
            FNLU2 = NAMEFIL(1:KNMFIL)//'.ome'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (3)
            IF (IPR(777) /= 1) THEN
              FNLU2   = NAMEFIL(1:KNMFIL)//'_pl.spf'
              WRITE (LU6, 99998) FNLU2
              IGBL(2) = IGBL(2) + 1
              INQUIRE (UNIT = LU2, OPENED = OPEND)
C * WORK-AROUND FOR THE SALFORD-COMPILER
              FILEN = ' '
              IF (OPEND) THEN
                INQUIRE (UNIT = LU2, NAME = FILEN)
              END IF
              IF (OPEND .AND. FILEN /= 'UNDEFINED') THEN
                WRITE (LU2, 99999, IOSTAT = IOST)
              ELSE
                OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
              END IF
            END IF
          CASE (4)
            FNLU2 = NAMEFIL(1:KNMFIL)//'.que'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (5)
            FNLU2 = NAMEFIL(1:KNMFIL)//'.par'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (6)
            FNLU2 = NAMEFIL(1:KNMFIL)//'.res'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (7)
            FNLU2 = NAMEFIL(1:KNMFIL)//'_pl.pdb'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (8)
            FNLU2 = NAMEFIL(1:KNMFIL)//'_acc.cif'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
            IPR(438) = 1
C * OPEN DIFFERENCE MAP PEAK LIST
          CASE (10)
            IF (IPR(663) == 0) THEN
              FNLU2 = NAMEFIL(1:KNMFIL)//'_sqd.sqz'
            ELSE
              FNLU2 = NAMEFIL(1:KNMFIL)//'_sq.sqz'
            END IF
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
          CASE (11)
            FNLU2 = NAMEFIL(1:KNMFIL)//'.dif'
            OPEN (UNIT = LU2, FILE = FNLU2, STATUS = 'UNKNOWN')
        END SELECT
        IPR(437) = IGBL(31)
        IF (IGBL(2) <= 1) THEN
           REWIND (UNIT = LU2, IOSTAT = IOST)
           IF (IOST /= 0) CALL GEN148 (LU2, 1)
        END IF
C * WRITE ENDS
      ELSE
        WRITE (LU2, 99999, IOSTAT = IOST)
      END IF
      RETURN
99999 FORMAT ('ENDS')
99998 FORMAT (/, ':: Create ', A)
      END SUBROUTINE PLA292
 
      SUBROUTINE PLA293 (WAVEL)
      USE parameters
      USE atomdata
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      REAL :: WL
      REAL :: WAVEL
C * CHECK WAVELENGTH
      WL = WAVEL
C * ASSUME ELECTRON DIFFRACTION
      IF (WL > 0.0 .AND. WL <= 0.1) THEN
        IPR(493) = 8
        IPR(671) = 8
        IPR(630) = 2
      END IF
C * DEFAULT MOKa RADIATION
      IF (WL <= 0.0 .AND. IPR(493) < 7) THEN
        WL       = STWL(3)
        IPR(493) = -3
        KRAD     = CSTWL(3)
      ELSE
        IF (IABS (IPR(493)) == 8) THEN
          KRAD = 'elec'
        ELSE IF (IABS (IPR(493)) == 7) THEN
          KRAD = 'neut'
C * DEFAULT SYNCHROTRON RADIATION
        ELSE IF (IPR(493) == 0) THEN
          IPR(493) = 6
          KRAD     = 'sync'
        ELSE
C * TEST FOR InKa, AgKa, MoKa, GaKa or CuKa
          DO I = 1, 5
            IF (ABS (WL - STWL(6 - I)) < PAR(63)) THEN
              IPR(493) = I
              KRAD     = CSTWL(6 - I)
              EXIT
            END IF
          END DO
        END IF
      END IF
      PAR(17) = WL
      IF (PAR(168) > 0.0) THEN
        PAR(287) = SIN (PAR(168) / RGBL(6)) / PAR(17)
      END IF
      RETURN
      END SUBROUTINE PLA293
 
      SUBROUTINE PLA294 (MODE)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NE
      INTEGER :: IOK
      INTEGER :: NENT
      INTEGER :: NRES
      INTEGER :: MODE
      INTEGER :: FINDEXE
      IGBL(70) = 0
      IF (MODE == 1) THEN
        IF (SPGRNM(1)(13:13) /= ' ') THEN
          CLOSE (UNIT = LU2, IOSTAT = IOST)
          IGBL(31) = 4
          IPR(437) = 0
C * FILE OPEN #2
          CALL PLA292
          LINE = ' '
          WRITE (IDM, 99998, IOSTAT = IOST) (PAR(122 + I), I = 1, 6),
     1    PAR(28)
C * REMOVE MULTIPLE SEPARATING SPACES
          J = 14
          LINE(1:14) = IDM(1:14)
          DO I = 15, 68
            IF (LINE(J:J) /= ' ') THEN
              J = J + 1
              LINE(J:J) = IDM(I:I)
            ELSE IF (IDM(I:I) /= ' ') THEN
              J = J + 1
              LINE(J:J) = IDM(I:I)
            END IF
          END DO
          WRITE (LU2, 99995) LINE
          WRITE (LU2, 99999, IOSTAT = IOST)
        ELSE
          BCD = 'No SPGR info Given ...'//CHAR (0)
          CALL GGIP (-999.0, 2.0, 30.0, 111)
          RETURN
        END IF
      ELSE
        WRITE (LU2, 99997, ADVANCE = 'NO', IOSTAT = IOST)
C * GET NUMBER OF RESIDUES
        NRES = IPR(75)
        IF (NRES > 1) THEN
          DO I = 2, NRES
            IF (RCONT(I) >= IPR(735)) THEN
              WRITE (LU2, 99996, ADVANCE = 'NO', IOSTAT = IOST) I
            END IF
          END DO
        END IF
        WRITE (LU2, 99993, IOSTAT = IOST)
      END IF
      CLOSE (UNIT = LU2, IOSTAT = IOST)
C * FIND CONQUEST (cqbatch)
      CALL GEN038 (CGETENV, 1, 80)
      NE = FINDEXE ('QUESTEXE', CGETENV, 'cqbatch')
      IF (NE > 0) THEN
        CGETENV(NE + 1:) =
     1' -j cqbatch -rerun '//NAMEFIL(1:KNMFIL)//'.que'//' -export cif'
        KERR = 0
        CALL SPAWN (CGETENV, LU6, .true., KERR)
        NENT = 0
        OPEN (LU61, FILE = 'cqbatch.cif', STATUS = 'UNKNOWN',
     1        IOSTAT = IOK)
        IF (IOK == 0) THEN
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_cq.cif',
     1              STATUS = 'UNKNOWN')
          DO
            READ (LU61, 99995, IOSTAT = IOST) LINE
            IF (IOST /= 0) EXIT
            WRITE (LU62, 99995, IOSTAT = IOST) LINE
            IF (LINE(1:12) == 'data_CSD_CIF') NENT = NENT + 1
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          CLOSE (UNIT = LU62)
          BCD = 'Number of Hits =      '//CHAR (0)
          WRITE (BCD(17:21), 99994, IOSTAT = IOST) NENT
          CALL GGIP (-999.0, 2.0, 30.0, 111)
          IF (IGBL(80) * NENT > 0) THEN
            KERR = 0
            CALL SPAWN
     1      (PLAPATH(1:IGBL(80))//' -a '//NAMEFIL(1:KNMFIL)//'_cq.cif',
     2        LU6, .true., KERR)
          END IF
          OPEN (UNIT = LU61, FILE = 'cqbatch.cqs', STATUS = 'UNKNOWN',
     1      IOSTAT = IOST)
          IF (IOST == 0) CLOSE (LU61, STATUS = 'DELETE')
          OPEN (UNIT = LU61, FILE = NAMEFIL(1:KNMFIL)//'_cq.eld',
     1      IOSTAT = IOST)
          IF (IOST == 0) CLOSE (LU61, STATUS = 'DELETE')
          OPEN (UNIT = LU61, FILE = NAMEFIL(1:KNMFIL)//'_cq.lis',
     1      IOSTAT = IOST)
          IF (IOST == 0) CLOSE (LU61, STATUS = 'DELETE')
        END IF
      ELSE
        CALL PLA015 (0, 9)
      END IF
      RETURN
99999 FORMAT ('QUESTION T1')
99998 FORMAT ('T1 *PCELL TRIC', 3F9.3, 3F7.2, F6.3)
99997 FORMAT ('QUESTION T1')
99996 FORMAT (' .OR. T', I1)
99995 FORMAT (A)
99994 FORMAT (I5)
99993 FORMAT (1X)
      END SUBROUTINE PLA294
 
      SUBROUTINE PLA296 (LU, LINE)
      USE cggt
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: IOST
      CHARACTER(len=*) :: LINE
      IF (LU /= 0) THEN
        WRITE (LU, 99999, IOSTAT = IOST) LINE
      ELSE
        VRT = VRT - 0.5
        CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
      END IF
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT (A)
      END SUBROUTINE PLA296
 
      SUBROUTINE PLA297 (MODE)
      USE parameters
      USE cggt
      IMPLICIT NONE
      INTEGER :: MODE
C * WHAT NEXT ?
      CALL PLA012 (2, 5)
      IF (IPR(736) == 1) THEN
        CALL PLA280 ('RESET')
      ELSE
        IF (IGGT(1:4) == 'PLOT') THEN
          IF (MODE == 2) IGGT(1:4) = 'CALC'
        END IF
        IF (IGGT(1:4) /= 'CALC') CALL GEN038 (IGGT, 1, 80)
        IF (MODE == 1) THEN
          IF (IGBL(6) == 10) THEN
            CALL PLA280 ('!')
          ELSE
            CALL PLA280 ('PLOT')
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA297
 
