     5 'VIEW DIRECTION x y z (rotations)                              ',
     6 'VIEW LINE atom-name1 atom-name2 (ARU/rotations)               ',
     7 'VIEW BISECT atom-name1 atom-name2 atom-name3 (rotations)      ',
     8 'VIEW PERP atom-name1 atom-name2 atom-name3 (rotations)        ',
     9 'VIEW CURRENT (rotations)                                      ',
     * 'VIEW INVERT (rotations)                                       ',
     1 '  rotations:                                                  ',
     2 '  (XROT xr)(YROT yr)(ZROT zr)(LROT lr x y z)(INVERT)          ',
     3 '  (OROT or x y z)(PROT pr x y z)(BROT br at-name1 at-name2)   ',
     4 'XROT xr                                                       ',
     5 'YROT yr                                                       ',
     6 'ZROT zr                                                       '/
     7 )
      END MODULE man
 
      SUBROUTINE PLA299 (MODE)
      USE files
      USE cggt
      USE man
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: MODE
      IF (IWIN == 1) CALL GGIP (HORS, VERT, 0.0, 1)
      VRT = VERT
      HRT = HORS / 2.0
C * PLATON INSTRUCTIONS
      IF (MODE == 1) THEN
        DO I = 1, 131
          WRITE (LU6, 99999, IOSTAT = IOST) MANUAL(I)
        END DO
        IF (IWIN == 1) THEN
          DO I = 1, 70
            VRT = VRT - 0.25
            CALL PLA439 (0.0, MANUAL(I), 29, 0.2, 1, 1, 0.2, VRT)
          END DO
          VRT = VERT
          DO I = 71, 131
            VRT = VRT - 0.25
            CALL PLA439 (0.0, MANUAL(I), 29, 0.2, 1, 1, HRT, VRT)
          END DO
C * WHAT NEXT ?
          CALL PLA012 (1, 1)
          IGGT = '!'
        END IF
C * PLUTON INSTRUCTIONS
      ELSE
        DO I = 1, 70
          VRT = VRT - 0.25
          CALL PLA439 (0.0, PLUMAN(I), 62, 0.2, 1, 1, 0.2, VRT)
        END DO
        IF (IWIN == 1) THEN
          VRT = VERT
          DO I = 71, 116
            VRT = VRT - 0.25
            CALL PLA439 (0.0, PLUMAN(I), 62, 0.2, 1, 1, HRT, VRT)
          END DO
          DO I = 1, 116
            WRITE (LU6, 99999, IOSTAT = IOST) PLUMAN(I)
          END DO
C * WHAT NEXT ?
          CALL PLA012 (1, 1)
          IGGT = '!'
        END IF
      END IF
      RETURN
99999 FORMAT (A)
      END SUBROUTINE PLA299
 
      SUBROUTINE PLA300 (M1, M2, M3)
C * GET WEB-PAGE - BROWSER-HTML HELP
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE menus
      USE cggt
      IMPLICIT NONE
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: NB
      INTEGER :: NC
      INTEGER :: NX
      INTEGER :: NF
      INTEGER :: NE
      INTEGER :: LNX
      INTEGER :: IER
      CHARACTER(len=2)  :: N1
      CHARACTER(len=2)  :: N2
      CHARACTER(len=2)  :: N3
      CHARACTER(len=11) :: MOPTION
 
      NB = M2
      NC = M3
C * LENGTH OF BROWSER PATH (MacOS & LINUX ONLY - ZERO FOR MS-WINDOWS)
      NF = IGBL(47)
C * CLICK ON CANVAS = AREA #1
      IF (M1 == 1) THEN
        IF (NC > NP46) THEN
          IF (NF > 0 .OR. DOS) THEN
            IF (NB == 1) THEN
              PRBUF = HTTPSERVER(1:IGBL(135))//
     1                'PLATON-MANUAL.pdf'
            ELSE IF (NB == 2) THEN
              PRBUF = HTTPSERVER(1:IGBL(135))//
     1                'PLATON_HOW_TO.pdf'
            ELSE
              NB = 0
              NC = 0
            END IF
C STRIP_BEG
            IF (NB > 0) THEN
C * CODE ADDED FOR THE MS-WINDOWS VERSION OF PLATON (By L. Farrugia)
              IF (DOS) THEN
                CALL USE_URL (PRBUF)
              ELSE
                IER = 0
                CALL GEN039 (1, PRBUF, 1, 132, NX, NE)
                BROWSER(NF + 1:) = ' '//PRBUF(1:NE)
                IF (IGBL(74) == 1)
     1            WRITE (LU6, 99999) BROWSER(1:NF + NE + 1)
                CALL SPAWN ('sh -c '''//BROWSER(1:NF + NE + 1)//'''',
     1            LU6, .false., IER)
              END IF
              RETURN
            END IF
C STRIP_END
          END IF
        ELSE
          MOPTION = OPTS(M2, M3)
          N1 = '00'
        END IF
        WRITE (N2, 99997, IOSTAT = IOST) NB
C * CLICK ON SIDE MENU  = AREA #2
      ELSE IF (M1 == 2) THEN
        WRITE (N1, 99997, IOSTAT = IOST) IGBL(6)
        MOPTION = MENUSUB(NC)
        N2 = '02'
C * CLICK IN AREA #3
      ELSE IF (M1 == 3) THEN
        N1 = '10'
        N2 = '03'
        N3 = '00'
C * CLICK ELSEWHERE
      ELSE IF (M1 == 0) THEN
        WRITE (N1, 99997, IOSTAT = IOST) NB
        N2      = '00'
      END IF
      WRITE (N3, 99997, IOSTAT = IOST) MAX (0, NC)
C * PREPARE URL IN PRBUF
      CALL GET_ENVIRONMENT_VARIABLE ('PLAHTM', VALUE = LINE)
      IF (LINE(1:1) == ' ') THEN
        PRBUF = HTTPSERVER(1:IGBL(135))//'platon/'
      ELSE
        PRBUF = 'file:'//LINE
      END IF
      NX = 1
      CALL GEN039 (1, PRBUF, 1, 132, NX, NE)
      PRBUF(NE + 1:) = 'pl'//N1//N2//N3//'.html'
      LNX = NE + 13
      WRITE (LINE, 99998) MOPTION, PRBUF(1:LNX)
      LNX = LNX + 30
C * REPORT INFO LOCATION
      WRITE (LU6, 99996) LINE(1:LNX)
C STRIP_BEG
C * CODE ADDED FOR THE MS-WINDOWS VERSION OF PLATON (By L. Farrugia)
      IF (DOS) THEN
        CALL USE_URL (PRBUF)
        RETURN
      END IF
C STRIP_END
C * PREPARE BROWSER COMMAND LINE IN CGETENV
      IF (NF > 0) THEN
        IER = 0
        BROWSER(NF + 1: )  = ' '//PRBUF(1:NE + 13)
        IF (IGBL(74) == 1)
     1    WRITE (LU6, 99996) BROWSER(1:NF+NE+15)
        CALL SPAWN ('sh -c '''//BROWSER(1:NF + NE + 15)//'''',
     1    LU6, .false., IER)
        IGGT(1:1) = CHAR (12)
      ELSE
C * REPORT INFO LOCATION
        BCD = LINE(1:LNX)//CHAR (0)
        CALL GGIP (-999.0, 3.0, 80.0, 111)
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT (':: Info for "', A, '" at: ', A)
99997 FORMAT (I2.2)
99996 FORMAT (/, A)
      END SUBROUTINE PLA300
 
