      SUBROUTINE PLA330
C * APPLY HKL-FILE TRANSFORMATION (AND DIRECTION COSINES)
      USE files
      USE parameters
      USE plato
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      REAL :: DET
      REAL :: XLNG
      REAL :: GEN050
      REAL, DIMENSION(3, 3) :: YUNK
      CHARACTER(len=20) :: CH
      OPEN (UNIT = LU61, FILE = NAMEFIL(1:KNMFIL)//'_trans.hkl',
     1    STATUS = 'UNKNOWN')
C * HKL + DIRECTION COSINE TRANSFORMATION
      CALL GEN003 (QQ, DUMV, DET, 0)
      IF (ABS (DET) < 0.01) THEN
        IPR(2) = 73
        RETURN
      END IF
      IHT = 0
      IKT = 0
      ILT = 0
C * TRANSPOSE MATRIX
      CALL GEN005 (QQ, YUNK)
C * COPY MATRIX
      CALL GEN052 (YUNK, QQ)
      WRITE (LU6, 99996, IOSTAT = IOST) DET
      WRITE (LU6, 99997, IOSTAT = IOST)
     1  ((DUMV(I, J), J = 1, 3), I = 1, 3)
      WRITE (LU6, 99995, IOSTAT = IOST)
      WRITE (LU6, 99997, IOSTAT = IOST) ((QQ(I, J), J = 1, 3), I = 1, 3)
C * ZERO ARRAYS
      CALL GEN074 (PAC,  1, 9, 0.0)
      CALL GEN074 (UIJC, 1, 9, 0.0)
      PAC(1, 1)  = PAR(135)
      PAC(2, 2)  = PAR(136)
      PAC(3, 3)  = PAR(137)
      UIJC(1, 1) = 1.0 / PAR(113)
      UIJC(2, 2) = 1.0 / PAR(114)
      UIJC(3, 3) = 1.0 / PAR(115)
      CALL GEN132 (UIJC, QQ, PAC, PAT)
      WRITE (LU6, 99994, IOSTAT = IOST)
      WRITE (LU6, 99997, IOSTAT = IOST)
     1  ((PAT(I, J), J = 1, 3), I = 1, 3)
      IF (IGBL(37) == 0) WRITE (LU6, 99992, IOSTAT = IOST)
      N = 0
C * CHECK FOR XML AFTER DUMMY REFLECTION
      DO
        READ (LU16, 99999, IOSTAT = IOST) IH, IK, IL, CH,
     1     (V1(K), V2(K), K = 1, 3)
        IF (IOST /= 0) GO TO 10
        IF (IH == 0 .AND. IK == 0 .AND. IL == 0) THEN
          WRITE (LU61, 99990, IOSTAT = IOST)
          READ (LU16, 99998, IOSTAT = IOST) PRBUF
          IF (IOST == -1) GO TO 10
          IF (INDEX (PRBUF, '<?') /= 0) GO TO 10
          BACKSPACE LU16
          CYCLE
        END IF
        IF (GEN050 (DUMV, IH, IK, IL, IHT, IKT, ILT) > 0.0) THEN
          N = N + 1
          IF (IGBL(37) == 1) THEN
            CALL GEN002 (1, PAT,  V1, V4, XLNG)
            CALL GEN002 (1, PAT,  V2, V5, XLNG)
            WRITE (LU61, 99999, IOSTAT = IOST) IHT, IKT, ILT, CH,
     1          (V4(K), V5(K), K = 1, 3)
          ELSE
            WRITE (LU61, 99999, IOSTAT = IOST) IHT, IKT, ILT, CH
          END IF
        END IF
      END DO
   10 WRITE (LU61, 99990, IOSTAT = IOST)
      WRITE (LU6,  99991, IOSTAT = IOST) N
      CLOSE (UNIT = LU61)
C * COPY, ADAPT INS FILE
      OPEN (UNIT = LU61, FILE = NAMEFIL(1:KNMFIL)//'_trans.ins',
     1    STATUS = 'UNKNOWN')
      REWIND (UNIT = LU1, IOSTAT = IOST)
      DO
        READ (LU1, 99998, IOSTAT = IOST) PRBUF
        IF (IOST == -1) GO TO 20
        IF (PRBUF(1:4) == 'HKLF') THEN
          READ (PRBUF(5:10), *) N1
          WRITE (PRBUF, 99993) N1
        ELSE IF (PRBUF(1:4) == 'HKLT') THEN
          CYCLE
        END IF
        N2 = LEN_TRIM (PRBUF)
        WRITE (LU61, 99998) PRBUF(1:N2)
      END DO
   20 CLOSE (UNIT = LU61)
      RETURN
99999 FORMAT (3I4,  A, 6F8.5)
99998 FORMAT (A)
99997 FORMAT (3F10.4)
99996 FORMAT (/, 'Direct Cell axes and HKL Transformation Matrix',
     1           ' (Determinant = ', F5.2, /)
99995 FORMAT (/, 'Coordinate Transformation Matrix', /)
99994 FORMAT (/, 'Transformation Matrix for SHELX Direction Cosines', /)
99993 FORMAT ('HKLF', I2, ' 1')
99992 FORMAT (/, ':: No Direction Cosines on INPUT/OUTPUT', /)
99991 FORMAT (/, ':: Number of Reflections processed = ', I7, /)
99990 FORMAT (1X)
      END SUBROUTINE PLA330
 
      SUBROUTINE PLA340
C * ANOMALOUS SCATTERING AND ABSORPTION CONTRIBUTIONS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: IATNUM
      REAL :: YUNK1
      REAL :: YUNK2
      REAL :: YUNK3
      REAL :: YUNK4
C *   IPR(493) = -3 IPR(630) = 0 MoKa - Default
C *               1            0 InKa
C *               2            0 AgKa
C *               3            0 MoKa
C *               4            0 GaKa
C *               5            0 CuKa
C *               6            0 MoKb
C *               6            3 Synchrotron
C *               7            1 Neutron
C *               8            2 Electron
      IF (IABS (IPR(493)) > 0 .AND. IABS (IPR(493)) < 7) THEN
        DO I = 1, IAN
          L = IENS(I)
C * NON-In,Ag, Mo, Ga, Cu WAVELENGTH (f' AND f'')
          IF (IABS(IPR(493)) == 6) THEN
            IATNUM = IATNR(IEN(L))
            CALL PLA386 (IATNUM, PAR(17), ANOM(L, 1),
     1      ANOM(L, 2), ANOM(L, 3), 0)
C * CuKa, GaKa, MoKa, AgKa or InKa  WAVELENGTH (f' AND f'')
C * 5     4     3     2       1     = IPR(493)
          ELSE IF (IABS (IPR(493)) < 6) THEN
            DO K = 1, 2
              J = IEN(L) * 19 + K - 2 * IABS (IPR(493))
              ANOM (L, K) = SFAC(J)
              PAR(512 + K) = MAX (PAR(512 + K), SFAC(J))
            END DO
            ANOM(L, 3) = AMR(IEN(L), IABS (IPR(493)))
          ELSE
            ANOM(L, 3) = 0.0
          END IF
        END DO
        IF (IPR(761) > 0 .AND. IGBL(104) /= 1) THEN
          YUNK1 = 0
          YUNK2 = 0
          DO I = 1, IPR(761)
            YUNK1 = YUNK1 + ABS (DISPVAL(I, 1))
            YUNK2 = YUNK2 + ABS (DISPVAL(I, 2))
          END DO
C * ALERT _986 - No 'NON-ZERO f's' FOUND
          IF (YUNK1 == 0.0)
     1      CALL PLA236 (986, 0, -999.0, 0.0, ' ', ' ')
C * ALERT _981 - No 'NON-ZERO f"s' FOUND
          IF (YUNK2 == 0.0)
     1      CALL PLA236 (981, 0, -999.0, 0.0, ' ', ' ')
          DO I = 1, IAN
            L = IENS(I)
            DO K = 1, IPR(761)
              IF (LMT(L, 1) == DISPTYPE(K, 1)) THEN
                NQ1 = ' '//DISPTYPE(K, 1)(1:2)//'-f''='
                NQ2 = ' '//DISPTYPE(K, 1)(1:2)//'-f"='
                WRITE (NQ3, 99995, IOSTAT = IOST) ANOM(L, 1)
                WRITE (NQ4, 99995, IOSTAT = IOST) ANOM(L, 2)
C * Check for NoSpherA2
                IF (IPR(775) == 0) THEN
                  YUNK3 = ABS (DISPVAL(K, 1) - ANOM(L, 1))
                  IF (YUNK1 > 0.001 .AND. YUNK3 > 0.001) THEN
C * ALERT _982 - F' (SKIP IN & GA & Synchrotron)
                    IF (IPR(493) /= 1 .AND. IPR(493) /= 4 .AND.
     1                IPR(493) /= 6) THEN
                      CALL PLA236 (982, 84, -999.0, DISPVAL(K, 1), NQ1,
     1                             NQ3)
                    ELSE
C * ALERT _984
                      IF (ANOM(L, 1) /= 0.0) THEN
                        CALL PLA236 (984, 84, -999.0, DISPVAL(K, 1),
     1                    NQ1, NQ3)
                      ELSE
C * ALERT _988
                        CALL PLA236 (988, 3, -999.0, DISPVAL(K, 1),
     1                    NQ1(2:6), ' ')
                        ANOM(L, 1) = DISPVAL(K, 1)
                      END IF
                    END IF
                  END IF
                  YUNK4 = ABS (DISPVAL(K, 2) - ANOM(L, 2))
                  IF (YUNK2 > 0.001 .AND. YUNK4 > 0.001) THEN
C * ALERT _983 - F'' (SKIP In & Ga & Synchrotron)
                    IF (IPR(493) /= 1 .AND. IPR(493) /= 4 .AND.
     1                IPR(493) /= 6) THEN
                      CALL PLA236 (983, 84, -999.0, DISPVAL(K, 2), NQ2,
     1                             NQ4)
                    ELSE
C * ALERT _985
                      IF (ANOM(L, 2) /= 0.0) THEN
                        CALL PLA236 (985, 84, -999.0, DISPVAL(K, 2),
     1                      NQ2, NQ4)
                      ELSE
C * ALERT _989
                        CALL PLA236 (989, 3, -999.0, DISPVAL(K, 2),
     1                     NQ2(2:6), ' ')
                        ANOM(L, 2) = DISPVAL(K, 2)
                      END IF
C * HANDLE MISSING ABSORPTION CONTRIBUTION
                      IF (ANOM(L, 3) == 0.0) THEN
                        ANOM(L, 3) = DISPVAL(K, 3)
                      END IF
                    END IF
                  END IF
                END IF
              END IF
            END DO
          END DO
        ELSE
C * ALERT _980 - Anomalous Scattering Factors
          IF (IGBL(104) /= 1 .AND. IPR(105) == 0) THEN
            CALL PLA236 (980, 0, -999.0, 0.0, ' ', ' ')
          END IF
        END IF
C * TEST FOR PRINT LEVEL
        IF (IGBL(63) > 3) THEN
          CALL PLA262 (2)
          WRITE (LU7, 99997, IOSTAT = IOST)
     1      (ANOM(IENS(I), 1), I = 1, IAN)
          WRITE (LU7, 99996, IOSTAT = IOST)
     1      (ANOM(IENS(I), 2), I = 1, IAN)
        END IF
      END IF
C * MASS ABSORPTION COEFFICIENTS
      IF (IABS (IPR(493)) > 0 .AND. IABS (IPR(493)) < 7) THEN
        DO I = 1, IAN
          IF (SATWT(IENS(I)) > 0.1) THEN
            FN(I) = ANOM(IENS(I), 3) / (SATWT(IENS(I)) * 1.66054)
          ELSE
            FN(I) = 0.0
          END IF
        END DO
        IF (IGBL(63) > 3) THEN
          CALL PLA262 (2)
          WRITE (LU7, 99998, IOSTAT = IOST) KRAD, (FN(I), I = 1, IAN)
          WRITE (LU7, 99999, IOSTAT = IOST)
     1      (LMT(IENS(I), 2), I = 1, IAN)
        END IF
      END IF
      IPR(704) = 1
      RETURN
99999 FORMAT ('Elem. Type  : ', 16(4X, A, 1X))
99998 FORMAT ('Mu(a) (', A, '):', 16F7.2)
99997 FORMAT ('Scat.Fact.f'':', 16F7.3)
99996 FORMAT ('Scat.Fact.f":',  16F7.3)
99995 FORMAT (F9.4)
      END SUBROUTINE PLA340
 
      SUBROUTINE PLA343
C * RECOVER ORIGINAL HKL FILE HKLF5 FILE
      USE files
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: N
      INTEGER :: M
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      CHARACTER(len=16) :: A
      K = 0
      N = 0
      M = 0
      IF (COMMAND_ARGUMENT_COUNT() >= 2) THEN
        CALL GET_COMMAND_ARGUMENT (2, FILENAMES(1))
        N = INDEX (FILENAMES(1), '.hkl')
      END IF
      IF (N /= 0) THEN
        OPEN (LU60, FILE = FILENAMES(1)(1:N-1)//'.hkl',
     1    STATUS = 'UNKNOWN', IOSTAT = IOST)
        IF (IOST /= 0) THEN
          WRITE (LU6, 99997, IOSTAT = IOST) FILENAMES(1)(1:N-1)//'.hkl'
          RETURN
        END IF
        OPEN (LU61, FILE = FILENAMES(1)(1:N - 1)//'_org.hkl',
     1    STATUS = 'UNKNOWN', IOSTAT = IOST)
        DO
          READ (LU60, 99999, IOSTAT = IOST) IH, IK, IL, A, I
          IF (IOST /= 0) EXIT
          IF (IH /= 0 .OR. IK /= 0 .OR. IL /= 0) THEN
            IF (I > 0) THEN
              M = M + 1
              WRITE (LU61, 99999, IOSTAT = IOST) IH, IK, IL, A, I
            ELSE IF (I < 0) THEN
              K = K + 1
            END IF
          ELSE
            EXIT
          END IF
        END DO
      END IF
      WRITE (LU6, 99998) M, FILENAMES(1)(1:N - 1)//'_org.hkl'
      WRITE (LU6, 99996) K
      RETURN
99999 FORMAT (3I4, A, I4)
99998 FORMAT (/, I8, ' Reflections on ', A)
99997 FORMAT (/, 'FILE: ', A, ' NOT FOUND')
99996 FORMAT (/, I8, ' Refections eliminated')
      END SUBROUTINE PLA343
 
      SUBROUTINE PLA344
C * RECOVER original hkl file from solvent contribution subtracted Iobs file
      USE files
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: ISIG
      INTEGER :: IINT
      REAL, DIMENSION(6) :: DIR
      IF (COMMAND_ARGUMENT_COUNT() >= 2) THEN
        CALL GET_COMMAND_ARGUMENT (2, FILENAMES(1))
        N = INDEX (FILENAMES(1), '.hkl')
      END IF
      IF (N /= 0) THEN
        OPEN (LU60, FILE = FILENAMES(1)(1:N-1)//'.hkl',
     1    STATUS = 'UNKNOWN', IOSTAT = IOST)
        OPEN (LU61, FILE = FILENAMES(1)(1:N - 1)//'_org.hkl',
     1    STATUS = 'UNKNOWN', IOSTAT = IOST)
        M = 0
        DO
          READ (LU60, 99999, IOSTAT = IOST)
     1      IH, IK, IL, IINT, ISIG, (DIR(I), I = 1, 6), IINT
          IF (IOST /= 0) EXIT
          IF (IH /= 0 .OR. IK /= 0 .OR. IL /= 0) M = M + 1
          IF (DIR(1) /= 0.0) THEN
            WRITE (LU61, 99998)
     1        IH, IK, IL, IINT, ISIG, (DIR(I), I = 1, 6)
          ELSE
            WRITE (LU61, 99998) IH, IK, IL, IINT, ISIG
          END IF
        END DO
      END IF
      WRITE (LU6, 99997) M, FILENAMES(1)(1:N - 1)//'_org.hkl'
      RETURN
99999 FORMAT (3I4, 2I8, 4X, 6F8.5, I8)
99998 FORMAT (3I4, 2I8, 4X, 6F8.5)
99997 FORMAT (/, I8, ' Reflections on ', A)
      END SUBROUTINE PLA344
 
      SUBROUTINE PLA345
C * GENERATE _sx.ins AND _sx.hkl
C * FROM .cif AND .fcf for L.S. refinement
      USE files
      USE parameters
      USE cchar
      IMPLICIT NONE
C * SHELXL201n CASE
      IF (IPR(663) == -1) IPR(663) = -2
      IF (IPR(664) == -1) IPR(664) = -2
      IF (IPR(665) == -1) IPR(665) = -2
C * SHELXL97 CASE, CHECK FOR HKL CIF LOOP
      IF (IPR(753) == 0) THEN
        IF (IPR(664) == 0 .AND. IPR(321) == 0)  THEN
          OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sx.hkl',
     1     STATUS = 'UNKNOWN', IOSTAT = IOST)
          IF (IOST == 0) CALL PLA139 (LU6, LU16, LU61, IPR(384))
          CLOSE (UNIT = LU61)
          IGBL(131) = 1
          PAR(74)   = 10.0
          IPR(675)  = 1
          IPR(664)  = -3
        END IF
      ELSE
        CLOSE (UNIT = LU25, IOSTAT = IOST)
        IPR(664) = -3
      END IF
      IF (IPR(663) == 0) CALL PLA280 ('CALC SHELX NOSF')
      RETURN
      END SUBROUTINE PLA345
 
      SUBROUTINE PLA346
C * CREATE FCF FROM SHELXL20xy BASED CIF (With EMBEDDED .ins & .hkl (.fab))
C * OR COPY-ATTACH IN CASE OF CIF-EMBEDDED FCF FILE
      USE files
      USE parameters
      USE cchar
      USE mentry
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER, SAVE :: M
      IGBL(9) = IENTRY(IGBL(54), 3)
      IF (IGBL(9) == 1) THEN
        WRITE (LU6, 99997)
        RETURN
      END IF
C * TEST FOR CIF INPUT, A MAXIMUM OF NP54 ENTRIES STORED
      IF (IABS(IGBL(8)) == 3 .AND. IGBL(54) <= NP54) THEN
        NKAR = MIN(INDEX (CENTRY(IGBL(54)), ' ') - 1, 16)
C * CHECK FOR ELECTRON DIFFRACTION [IPR(493)=8]
C * CHECK FOR EXTERNALLY STORED SCATTERING FACTORS IN CIF [IPR(762>0]
        IGBL(9) = IENTRY(IGBL(54), 3)
        FNLU16(KNM16-2:KNM16) = 'fcf'
        IF ((IENTRY(IGBL(54), 4) == 0 .OR. IPR(762) > 0)) THEN
C * Check for shelx/iucr_fcf_details (=+-1)
C * USE CIF-EMBEDDED _sx.fcf
          IF (IPR(666) == -1) THEN
            WRITE (LU6, 99996)
            CLOSE (UNIT = LU16, IOSTAT = IOST)
C * CREATE *_sx.fcf file USING EMBEDDED *_sx.ins, *_sx.hkl (*_sx.fab)
          ELSE IF (IPR(663) /= 0 .AND. IPR(664) /= 0) THEN
            CALL PLA347
            WRITE (LU6, 99995)
            CLOSE (UNIT = LU16, IOSTAT = IOST)
          END IF
C * COPY/APPEND/DELETE _sx.fcf AND MAKE DATANAMES CONSISTENT
C * CHECK FOR (NEW) _sx.fcf TO BE APPENDED
          INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'_sx.fcf', EXIST = EXST61)
          IF (EXST61) THEN
C * OPEN _sx.fcf FILE ON LU61 TO BE APPENDED TO FILE LU16
            OPEN (UNIT = LU61, FILE = NAMEFIL(1:KNMFIL)//'_sx.fcf',
     1        STATUS = 'UNKNOWN')
C * CHECK FOR EXISTING fcf FILE ON LU16
            INQUIRE (FILE = NAMEFIL(1:KNMFIL)//'.fcf', EXIST = EXST16)
C * APPEND FCF
            IF (.NOT. EXST16) THEN
              OPEN (UNIT = LU16, FILE = NAMEFIL(1:KNMFIL)//'.fcf',
     1        STATUS = 'NEW')
              M = 0
            ELSE
              CLOSE (UNIT = LU16, IOSTAT = IOST)
              OPEN (UNIT = LU16, FILE = NAMEFIL(1:KNMFIL)//'.fcf',
     1        STATUS = 'OLD')
              OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'.copy',
     1          STATUS = 'UNKNOWN')
C * COPY (EXISTING?) FCF FILE
              M = 0
              DO
                READ (LU16, 99999, IOSTAT = IOST) IDM
                IF (IOST /= 0) EXIT
                M = M + 1
                WRITE (LU65, 99999, IOSTAT = IOST) IDM
              END DO
              REWIND (UNIT = LU65, IOSTAT = IOST)
              REWIND (UNIT = LU16, IOSTAT = IOST)
              DO I = 1, M
                READ  (LU65, 99999, IOSTAT = IOST) IDM
                WRITE (LU16, 99999, IOSTAT = IOST) IDM
              END DO
              CLOSE (UNIT = LU65, STATUS = 'DELETE', IOSTAT = IOST)
            END IF
C * APPEND
            DO
              READ (LU61, 99999, IOSTAT = IOST) IDM
              IF (IOST /= 0) EXIT
              M = M + 1
              IF (IDM(1:5) == 'data_') THEN
                IDM(1:) = 'data_'//CENTRY(IGBL(54))
                IENTRY(IGBL(54), 3) = 1
                IENTRY(IGBL(54), 4) = M
              END IF
              WRITE (LU16, 99999, IOSTAT = IOST) IDM
            END DO
            CLOSE  (UNIT = LU61, STATUS = 'DELETE')
            REWIND (UNIT = LU16, IOSTAT = IOST)
            IGBL(9)  = 1
            IF (IPR(725) /= 7 .AND. IPR(725) /= 8 .AND.
     1        IPR(725) /= 2) IPR(725) = 1
            IGBL(15) = 1
          ELSE
C * CHECK FOR POWDER, CRYSTL1 OR CRYSTL2 BASED REFINEMENT
            IPR(720) = IPR(720) + 1
            IF (IPR(105) == 0 .AND. IGBL(9) /= 5 .AND. IPR(720) == 1)
     1        THEN
              WRITE(LINE, 99998) CENTRY(IGBL(54))(1:MIN(NKAR,15))
              CALL PRINTX (LU6, LINE, 1, 1)
C * ALERT _995
              CALL PLA236 (995, 0, 1.0, 1.0, ' ', ' ')
            END IF
          END IF
C * REMOVE SOME LEFT-OVER FILES
          OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'_sx.cif',
     1      STATUS = 'OLD', IOSTAT = IOST)
          IF (IOST == 0) CLOSE (UNIT = LU65, STATUS = 'DELETE')
          OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'_sx.lst',
     1      STATUS = 'OLD', IOSTAT = IOST)
          IF (IOST == 0) CLOSE (UNIT = LU65, STATUS = 'DELETE')
          OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'_sx.res',
     1      STATUS = 'OLD', IOSTAT = IOST)
          IF (IOST == 0) CLOSE (UNIT = LU65, STATUS = 'DELETE')
        END IF
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT ('** PROBLEM to Recreate FCF for ', A,
     1        ' (Native SHELXL20xy Job Needed) **')
99997 FORMAT (/, '** FCF Present: No FCF Generation Needed')
99996 FORMAT (':: APPEND CIF-Embedded *_sx.fcf to FCF')
99995 FORMAT (':: APPEND Calc FCF from CIF-embedded res,hkl,fab to FCF')
 
      END SUBROUTINE PLA346
 
      SUBROUTINE PLA347
C * CREATE FCF FROM SHELXL20xy BASED CIF (With EMBEDDED .ins & .hkl (.fab))
      USE files
      USE parameters
      USE cchar
      USE mentry
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: LS
      INTEGER :: IEND
      CHARACTER(len=80) :: DUM
C * CHECK FOR SHELXL20xy AVAILABLE (i.e. IGBL(139) = 1)
      CALL PLA428
      IF (IGBL(139) == 1) THEN
C * REPORT FCF FROM .INS + .HKL
        WRITE (LU13, 99996) CENTRY(IGBL(54))(1:NKAR)
        WRITE (LU13, 99995)
C * OPEN DUMMY FILE FOR EDITED _shelx.ins
        OPEN (UNIT = LU65, FILE = NAMEFIL(1:KNMFIL)//'.junk',
     1    STATUS = 'UNKNOWN')
C * EDIT _sx.ins FILE
        REWIND (UNIT = LU24, IOSTAT = IOST)
        IEND = 0
        LS   = 0
        DO
          READ (LU24, 99999, IOSTAT = IOST) DUM
          IF (IOST /= 0) EXIT
          IF (DUM(1:1) /= '+') CALL GEN020 (1, DUM, 1, 4)
C * HANDLE MISSING L.S. RECORD
          IF (DUM(1:4) == 'ACTA') THEN
            IF (LS == 0) WRITE (LU65, 99992) IGBL(93)
            WRITE (LU65, 99999) DUM
          END IF
          IF (DUM(1:4) == 'L.S.') THEN
            LS = 1
            CALL GEN072 (DUM, IFL, FN, KL, KN, 0, 0, 1, 5, 80, 7, NP17)
            FN(1) = IGBL(93)
            WRITE (DUM,  99998) 'L.S.', (NINT (FN(I)), I = 1, KN)
            WRITE (LU65, 99999) DUM(1:70)
            WRITE (LU13, 99999)
     1       'Substituted SHELXL Instruction: '//DUM(1:48)
          ELSE IF (DUM(1:4) == 'SFAC') THEN
            WRITE (LU65, 99999) DUM
            N = INDEX (DUM, '=')
            IF (N > 0) DUM(N:N) = ' '
            CALL GEN072 (DUM, IFL, FN, KL, KN, 0, 0, 1, 5, 80, 7, NP17)
          ELSE IF (DUM(1:4) == 'LIST') THEN
            WRITE (DUM, 99999) 'LIST 4'
            WRITE (LU65, 99999) DUM
            WRITE (LU13, 99999) 'Substituted SHELXL Instruction: LIST 4'
          ELSE IF (DUM(1:3) == 'END') THEN
            WRITE (LU65, 99999) DUM
            IEND = 1
          ELSE IF (DUM(1:4) == 'WGHT') THEN
            WRITE (LU65, 99999) DUM
          ELSE IF (DUM(1:4) == 'DAMP') THEN
            WRITE (LU13, 99999) 'Deleted:    '//DUM(1:65)
          ELSE IF (DUM(1:4) == 'FMAP') THEN
            WRITE (LU13, 99999) 'Deleted:    '//DUM(1:65)
          ELSE IF (DUM(1:4) == 'WPDB') THEN
            WRITE (LU13, 99999) 'Deleted:    '//DUM(1:65)
          ELSE IF (DUM(1:4) == 'MORE') THEN
            WRITE (LU13, 99999) 'Deleted:    '//DUM(1:65)
          ELSE IF (DUM(1:4) == 'BIND') THEN
            CALL GEN072 (DUM, IFL, FN, KL, KN, 0, 0, 1, 1, 80, 7, NP17)
            IF (KL == 2 .OR. KN == 2) THEN
              WRITE (LU65, 99999) DUM
            ELSE
              N = KL / 2
              DO I = 1, N
                WRITE (LU65, 99993)
     1            IFL(1), IFL(I*2), IFL(I * 2 + 1)
              END DO
            END IF
          ELSE IF (DUM(1:4) == 'FREE') THEN
            CALL GEN072 (DUM, IFL, FN, KL, KN, 0, 0, 1, 1, 80, 7, NP17)
            IF (KL == 3 .OR. KN == 2) THEN
              WRITE (LU65, 99999) DUM
            ELSE
              N = KL / 2
              DO I = 1, N
                WRITE (LU65, 99993)
     1            IFL(1), IFL(I*2), IFL(I * 2 + 1)
              END DO
            END IF
          ELSE
            WRITE (LU65, 99999) DUM
          END IF
        END DO
C * COPY EDITED _shelx_ins BACK TO LU24
        REWIND (UNIT = LU24, IOSTAT = IOST)
        REWIND (UNIT = LU65, IOSTAT = IOST)
        DO
          READ (LU65, 99999, IOSTAT = IOST) DUM
          IF (IOST /= 0) EXIT
          WRITE (LU24, 99999) DUM
        END DO
        CLOSE (UNIT = LU65, STATUS = 'DELETE')
C * CLOSE FILES *_sx.ins, *_sx.hkl (*_sx.fab)
        CLOSE (UNIT = LU24, IOSTAT = IOST)
        CLOSE (UNIT = LU25, IOSTAT = IOST)
        IF (IPR(665) /= 0) ENDFILE (UNIT = LU26, IOSTAT = IOST)
C * RUN SHELXL20nm
        DUM(1:9) = ' -b5000  '
        DO I = 1, 5
          KERR = 0
          CALL SPAWN (
     1      SHLPATH(1:IGBL(110))//DUM(1:9)//
     2      NAMEFIL(1:KNMFIL)//'_sx > '//NAMEFIL(1:KNMFIL)//
     3      '_sx.log', LU6, .true., KERR)
C * CHECK MESSAGES FROM SHELXL
          OPEN (UNIT = LU65, FILE =
     1      NAMEFIL(1:KNMFIL)//'_sx.log', IOSTAT = IOST)
          IF (IOST == 0) THEN
C * READ-LOOP OF SHELXL LOGFILE
            DO
              READ (LU65, 99999, IOSTAT = IOST) DUM
              IF (IOST == 0) THEN
                IF (INDEX (DUM, 'INCREASE -b') > 0) THEN
                  WRITE (DUM(1:9), 99997) (I + 1) * 5000
                  EXIT
                END IF
              ELSE
                RETURN
              END IF
            END DO
C * END READ-LOOP OF SHELXL LOGFILE
          ELSE
            RETURN
          END IF
          CLOSE (UNIT = LU65, STATUS = 'DELETE', IOSTAT = IOST)
        END DO
      ELSE
        WRITE (LINE, 99994)
        CALL PRINTX (LU6, LINE, 1, 1)
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT (A, I3, 10I5)
99997 FORMAT (' -b', I5, 1X)
99996 FORMAT ('Create FCF from embedded  *.ins, *.hkl (& *.fab) for:',
     1        A)
99995 FORMAT (80('='))
99994 FORMAT (' ** SHELXL20xy Type Executable Required! **')
99993 FORMAT (A, A, 1X, A)
99992 FORMAT ('L.S.', I3)
      END SUBROUTINE PLA347
 
      SUBROUTINE PLA348
C * PROGRAM SPGR
C * THIS TOOL IS DESIGNED TO TEST THE FUNCTIONS OF THE GENERAL SPACE GROUP
C * SYMMETRY HANDLING ROUTINE - SGSM - IN ADDITION IT MAY BE USED INTERACTIVELY
C * FOR SYMMETRY RELATED EXERCISES
      USE files
      USE parameters
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: IBV
      INTEGER :: ISM
      INTEGER :: ISW
      INTEGER :: ISWX
      INTEGER :: JARG
      INTEGER :: NRSM
      INTEGER :: ICNTR
      INTEGER :: ITRNS
      INTEGER :: NSYMP
      INTEGER :: NSYMR
      INTEGER, DIMENSION(192) :: ICRD
      REAL, DIMENSION(192)  :: CRD
      REAL, DIMENSION(3, 3) :: TM1
      REAL, DIMENSION(3)    :: OSHFT
      CHARACTER(len=80) :: LINE
      CHARACTER(len=4)  :: IFL21
C * WRITE SPACE GROUP TOOL HEADER
      WRITE (LU6, 99993)
      LINE(1:4) = 'LATT'
      ITRNS     = 0
      JARG      = COMMAND_ARGUMENT_COUNT()
      KL        = 1
      KN        = 0
      ISW       = 0
      ISWX      = 1
      DO
        IF (JARG > 1) THEN
          IF (JARG == 2) THEN
            CALL GET_COMMAND_ARGUMENT (1, LINE)
            CALL GET_COMMAND_ARGUMENT (2, LINE(6:80))
            JARG = -1
            KL   = 2
            KN   = 0
            GO TO 10
          END IF
          CALL GET_COMMAND_ARGUMENT (1, LINE(6:80))
          LINE(1:5) = 'SPGR'
          JARG      = -1
        ELSE IF (JARG < 0) THEN
          LINE = 'LIST'
          JARG = 0
        ELSE
C * WRITE PROMPT, READ INSTRUCTION
          WRITE (LU6, 99992, ADVANCE = 'NO')
          READ (LU5, 99997) LINE
        ENDIF
        ISW  = 0
        ISWX = 1
C * UPPER CASE
        CALL GEN020 (1, LINE, 1, 4)
        CALL GEN072 (LINE, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
        IF (LINE(1:4) == 'HELP') THEN
          CALL SGSM(14, LINE, SGX, 5, LU6, IERR)
          CYCLE
        ELSE IF (LINE(1:4) == 'SYMM' .AND. KN == 12) THEN
          CALL SGSM (15, LINE, FN, 0, 0, IERR)
          CYCLE
        ELSE IF (LINE(1:4) == 'INFO') THEN
          CALL SGSM (18, LINE, SGX, 0, LU6, IERR)
          CYCLE
        ELSE IF (LINE(1:4) == 'SITE') THEN
          DO I = 1, 3
            SGX(I) = FN(I)
          END DO
          SGX(10) = FN(4)
          CALL SGSM (19, LINE, SGX, 0, LU6, IERR)
          WRITE (LU6, 99999) LINE(1:5), NINT (SGX(11)),
     1      SGX(7), SGX(8), SGX(9), SGX(10), NINT (1.0 / SGX(10))
          CYCLE
        ELSE IF (LINE(1:3) == 'END' .OR. LINE(1:4) == 'STOP' .OR.
     1    LINE(1:4) == 'QUIT') THEN
            RETURN
        ELSE IF (LINE(1:4) == 'TRNS' .OR. LINE(1:4) == 'TRMX') THEN
          K = 0
          DO I = 1, 3
            OSHFT(I) = FN(I + 9)
            DO J = 1, 3
              K = K + 1
              TM1(I, J) = FN(K)
            END DO
          END DO
          ITRNS = 1
          CYCLE
        ENDIF
C * LAUE/PATT
        IFL21 = IFL(2)(1:4)
        IF ((IFL21 == 'PATT' .OR. IFL21 == 'LAUE') .AND.
     1    KL > 1) ISWX = -1
        NRSM = NINT (FN(1))
   10   CALL GEN020 (1, LINE, 1, 4)
        IF (LINE(1:4) == 'LATT' .AND. KN == 0 .AND. KL == 1) THEN
          ISW = 1
        ELSE IF (LINE(1:4) == 'LIST') THEN
          ISW = 2 * ISWX
        ELSE IF (LINE(1:4) == 'DMAT') THEN
          ISW = 6
        ELSE IF (LINE(1:4) == 'GSNR') THEN
          ISW = 7
          LINE(1:4) = 'SYMM'
          ISW = 22
          CALL SGSM (22, LINE, SGX, 0, 0, IERR)
          WRITE (LU6, 99995) SGX(9), SGX(10), SGX(11), SGX(12)
          CYCLE
C * MULTIPLY TWO SYMMETRY OPERATIONS
        ELSE IF (LINE(1:4) == 'MULT') THEN
          ISW = 8
C * INVERT SYMMETRY OPERATION
        ELSE IF (LINE(1:4) == 'INVT') THEN
          ISW = 9
        ELSE IF (LINE(1:4) == 'ATOM' .OR. LINE(1:3) == 'HKL') THEN
          IF (LINE(1:4) == 'ATOM') THEN
            ISW = 3 * ISWX
          ELSE
            ISW = 5 * ISWX
          END IF
          CALL SGSM (18, LINE, SGX, 0, 0, IERR)
          NSYMP = NINT (SGX(4))
          ICNTR = NINT (SGX(5))
          IBV   = NINT (SGX(6))
          DO I = 1 ,6
            SGX(I) = 0.0
            IF (I <= KN) SGX(I) = FN(I)
          END DO
          NSYMR = NSYMP * ICNTR
          IF (IABS (ISW) < 4) NSYMR = NSYMR * IBV
          IF (ICNTR == 1 .AND. ISW < 0) NSYMR = NSYMR * 2
          IF (IABS (ISW) /= 5) THEN
            DO I = 1, NSYMR
              CRD(I)  = 0
              ICRD(I) = I
              CALL SGSM (ISW, LINE, SGX, I, LU6, IERR)
              DO J = 7, 9
                CRD(I) = CRD(I) + MOD (SGX(J) + 10.0, 1.0) * 100**(9-J)
              END DO
            END DO
            CALL GEN036 (CRD, ICRD, 1, NSYMR)
            DO K = 1, NSYMR
              I = ICRD(K)
              CALL SGSM (ISW, LINE, SGX, I, LU6, IERR)
              DO J = 7, 9
                SGX(J) = MOD (SGX(J) + 10.0, 1.0)
              END DO
              IF (ISW > 0) THEN
                CALL SGSM (2,  LINE, SGX, I, 0, IERR)
              ELSE
                CALL SGSM (-2, LINE, SGX, I, 0, IERR)
              ENDIF
              WRITE (LU6, 99991) I, SGX(7), SGX(8), SGX(9), LINE(1:50)
            END DO
          ELSE
            DO I = 1, NSYMR
              CALL SGSM (ISW, LINE, SGX, I, LU6, IERR)
              WRITE (LU6, 99994) I, SGX(7), SGX(8), SGX(9), SGX(10)
            END DO
          ENDIF
          CYCLE
        ELSE IF (LINE(1:4) == 'VECT') THEN
          ISW = -3
        ELSE IF (LINE(1:4) == 'RLST') THEN
          ISW = 4 * ISWX
C * SHELX-TYPE SYMM
        ELSE IF (LINE(1:4) == 'SHEL') THEN
          ISM = NINT (FN(1))
          CALL SGSM (17, LINE, SGX, ISM, LU6, IERR)
          CYCLE
C * RTM
        ELSE IF (LINE(1:3) == 'RTM') THEN
          ISW = 15
        END IF
C * LATT/SYMM/LIST/RLST/SPGR/DMAT/GSNR INSTRUCTION
        IF (ISW >= 7) THEN
          DO I = 1, 12
            IF (I > KN) FN(I) = 0.0
            SGX(I) = FN(I)
          END DO
        END IF
        IF (LINE(1:4) == 'LATT' .OR. LINE(1:4) == 'SPGR'
     1    .OR. LINE(1:4) == 'SYMM' .OR. LINE(1:4) == 'HALL') THEN
          IF (ITRNS == 1) THEN
            ISW = 16
            K   = 0
            DO I = 1, 3
              SGX(I + 9) = OSHFT(I)
              DO J = 1, 3
                K      = K + 1
                SGX(K) = TM1(I, J)
              END DO
            END DO
          ENDIF
        ENDIF
C * SPGR
        IF (LINE(1:4) == 'SPGR' .AND. KL == 1 .AND. KN == 0) CYCLE
        CALL SGSM (ISW, LINE, SGX, NRSM, LU6, IERR)
        IF (ISW == 6) WRITE (LU6, 99990)  (SGX(J), J = 1, 3), SGX(10),
     1 (SGX(J), J = 4, 6), SGX(11), (SGX(J), J = 7, 9), SGX(12)
        IF (ISW > 6 .AND. ISW < 15) WRITE (LU6, 99998) NINT (SGX(9)),
     1    SGX(10), SGX(11), SGX(12)
      END DO
99999 FORMAT('site: ', A, I6, ' pos:', 3F8.4, ' sof', F7.4, ' mult', I3)
99998 FORMAT ('SYMM NR', I4, ' UNIT TRANSL.', 3F5.0)
99997 FORMAT (A)
99995 FORMAT (4F10.2)
99994 FORMAT (I5, 6X, F10.0, 3(7X, F10.0))
99993 FORMAT (/, 20X, 36('='),
     1        /, 20X, '=== SPACE GROUP EXERCISE PROGRAM ===',
     2        /, 20X, 36('='),
     3       //, 20X, 'TYPE <HELP> FOR HELP OR INSTRUCTION', /)
99992 FORMAT (/,'>>')
99991 FORMAT (I4, 3(F8.4), 2X, A)
99990 FORMAT (2X, 3F10.0, F10.5)
      END SUBROUTINE PLA348
 
      SUBROUTINE PLA349
C * RELOAD SPACE-GROUP BY NAME FOR CONSISTENCY
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER NRXX
      IF (SPGRNM(1)(1:1) /= ' ') THEN
        NRXX = 0
        IF (INDEX (SPGRNM(1)(1:11), ':') /= 0) THEN
          WRITE (ICL, 99999, IOSTAT = IOST) SPGRNM(1)(1:11)
        ELSE
          WRITE (ICL, 99998, IOSTAT = IOST)
     1      SPGRNM(1)(1:7)//' '//SPGRNM(1)(8:11)
          IF (SPGRNM(1)(13:13) /= ' ') ICL(13:13) = '.'
        END IF
        CALL SGSM (0, ICL, SGY, NRXX, LU6, IERR)
      END IF
      RETURN
99999 FORMAT ('SPGR ', A, 64X)
99998 FORMAT ('SPGR ' , A, 63X)
      END SUBROUTINE PLA349
 
      MODULE cflip
      SAVE
      INTEGER :: NTRY
      INTEGER :: MTRY
      INTEGER :: NTEL
      INTEGER :: IPEN
      INTEGER :: NREF
      INTEGER :: MXSOL
      INTEGER :: MFTRY
      INTEGER :: NLOOP
      INTEGER :: NSPGR
      INTEGER :: NSOLVED
      INTEGER :: NSOLVMIN
      INTEGER, DIMENSION(4) :: MLOOP
      INTEGER, DIMENSION(3) :: IHKLMAX
      REAL :: UISO
      REAL :: VRTY
      REAL :: RVAL0
      REAL :: RVMIN
      REAL :: PFLIP
      REAL :: FACTOR
      REAL :: FOBSMIN
      END MODULE cflip
 
      SUBROUTINE PLA350
C * CHARGE FLIPPING DRIVER ROUTINE
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE cflip
      USE exor
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: KL
      INTEGER :: KN
      REAL :: VRTYI
      IWIN = IGBL(25) * IGBL(32)
C * DEFAULTS
      MLOOP(1) = 5000
      MLOOP(2) = 500
      MLOOP(3) = 1000
      MLOOP(4) = 2000
      FACTOR   = PAR(475)
      PFLIP    = 0.25
      UISO     = 0.02
      MXSOL    = 3
      NSOLVED  = 0
C * CHECK FOR CLOSED LU7
      INQUIRE (UNIT = LU7, OPENED = OPEND)
      IF (.NOT. OPEND)
     1  OPEN (UNIT = LU7, FILE = 'flip_dummy.lis', FORM = 'FORMATTED',
     2        IOSTAT = IOST)
C * CLOSE CHECK.DEF (NOT NEEDED FOR CHARGE FLIPPING)
      INQUIRE (UNIT = LU12, OPENED = OPEND)
      IF (OPEND) CLOSE (UNIT = LU12)
C * CLOSE <NAME>.DEF (NOT NEEDED FOR CHARGE FLIPPING)
      INQUIRE (UNIT = LU23, OPENED = OPEND)
      IF (OPEND) CLOSE (UNIT = LU23)
C * DELETE previous _sol.res
      CALL GEN129 (LU62, NAMEFIL(1:KNMFIL)//'_sol.res')
C * DELETE previous _res.res
      CALL GEN129 (LU62, NAMEFIL(1:KNMFIL)//'_res.res')
C * DELETE previous _res.new
      CALL GEN129 (LU62, NAMEFIL(1:KNMFIL)//'_res.new')
C * OPEN FILE FOR THE COLLECTION OF RAW SOLUTIONS
      OPEN (LU60, FILE = NAMEFIL(1:KNMFIL)//'_flp.res',
     1        STATUS = 'UNKNOWN')
C * OPEN FILE FOR THE COLLECTION OF CONVERGED SOLUTIONS
      OPEN (LU63, FILE = NAMEFIL(1:KNMFIL)//'_sol.res',
     1        STATUS = 'UNKNOWN')
C * COPY (HKL OR FCF FILE TYPE) REFLECTION FILE FOR EXOR RUN
      OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_xor.hkl',
     1      STATUS = 'UNKNOWN')
      REWIND (UNIT = LU16, IOSTAT = IOST)
C * CHECK FOR NON-HKLF4 FILE
      IF (IGBL(9) > 0) THEN
        CALL PLA139 (LU6, LU16, LU61, IPR(384))
      ELSE
        DO
          READ  (LU16, 99999, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          WRITE (LU61, 99999, IOSTAT = IOST) LINE
        END DO
      END IF
      CLOSE (UNIT = LU61)
C * INSTRUCTIONS
      KL = IPR(220)
      DO I = 1, KL
C * IPR(640) = 0 - FLIPPER MODE (25 RANDOM TRIAL)
        IF (IFL(I)(1:4) == 'FLIP') THEN
          NTRY     = 25
C * RVMIN TERMINATE R
          PAR(570) = 0.0
          IPR(640) = 0
C * IPR(640) = 1 - 'STRUCTURE' MODE
        ELSE IF (IFL(I)(1:4) == 'STRU') THEN
          NTRY     = 25
C * RVMIN TERMINATE R
          PAR(570) = 0.25
          IPR(640) = 1
C * PATT MODE (ONE TRY ONLY STARTING WITH PHASES ZERO)
        ELSE IF (IFL(I)(1:4) == 'PATT') THEN
          NTRY     = 1
C * RVMIN TERMINATE R
          PAR(570) = 0.0
          IPR(640) = 0
C * DISPLAY OPTION
        ELSE IF (IFL(I)(1:4) == 'SHOW') THEN
          IPR(614) = 1
        ELSE IF (IFL(I)(1:4) == 'MENU') THEN
          IF (IWIN == 1) IGBL(6) = 31
        END IF
      END DO
      IF (NTRY > 1) MLOOP(1) = 250
C * HANDLE FLIP ARGUMENTS
      KN = IPR(221)
      IF (KN > 0) THEN
C * GET NUMBER OF ATTEMPTS
        IF (FN(1) < 0.0) THEN
C * SET TO PHASES FROM F-CALC
          IPR(604) = 1
          UISO     = 0.0
          MLOOP(1) = 500
        END IF
        NTRY = MAX (1, MIN (25, NINT (ABS(FN(1)))))
C * GET # OF FLIP CYCLES
        IF (KN > 1) THEN
          IF (FN(2) /= 0.0) THEN
            MLOOP(1) = NINT (FN(2))
            MLOOP(2) = MLOOP(1)
            MLOOP(3) = MLOOP(1)
            MLOOP(4) = MLOOP(1)
          END IF
C * GET MAX # OF SOLUTIONS
          IF (KN > 2) THEN
            IF (FN(3) > 0) MXSOL = NINT (FN(3))
C * GET FLIP FACTOR
            IF (KN > 3) THEN
              FACTOR = MIN (0.05, FN(4))
C * PHASE FLIP
              IF (KN > 4) THEN
                PFLIP = MIN (0.50, FN(5) / 100.0)
C * GET 'NORMALIZING' U
                IF (KN > 5) THEN
                  UISO = MIN (0.06, FN(6))
                END IF
              END IF
            END IF
          END IF
        END IF
      END IF
C * PARAMETER CHANGE MENU MODE
      IF (IGBL(6) == 31) THEN
        NTRY     = 1
        IPR(640) = 0
        DO WHILE (.TRUE.)
          VRT  = VERT - 1.5
          LINE = 'Flipper Menu - Current Settings'
          CALL GGIP (HORS, VERT, 0.0, 1)
          CALL PLA439 (0.0, LINE, 31, 0.85, 5, 2, 1.0, VRT)
          VRT = VRT - 3.0
          WRITE (LINE,
     1      '(''NTRY   - Number of Trials           '', I10)',
     2      IOSTAT = IOST) NTRY
          CALL PLA439 (0.0, LINE, 46, 0.5, 1, 2, 1.0, VRT)
          VRT = VRT - 1.0
          WRITE (LINE,
     1      '(''NLOOP  - Maximum Number of Flips    '', I10)',
     2      IOSTAT = IOST) MLOOP(1)
          CALL PLA439 (0.0, LINE, 46, 0.5, 1, 2, 1.0, VRT)
          VRT = VRT - 1.0
          WRITE (LINE,
     1      '(''NSOLVE - Maximum Number of Solutions'', I10)',
     2      IOSTAT = IOST) MXSOL
          CALL PLA439 (0.0, LINE, 46, 0.5, 1, 2, 1.0, VRT)
          VRT = VRT - 1.0
          WRITE (LINE,
     1      '(''DELTA  - Flip Factor Delta          '', F10.3)',
     2      IOSTAT = IOST) FACTOR
          CALL PLA439 (0.0, LINE, 46, 0.5, 1, 2, 1.0, VRT)
          VRT = VRT - 1.0
          WRITE (LINE,
     1      '(''PERC   - Phase Shift Percentage     '', F10.3)',
     2      IOSTAT = IOST) PFLIP
          CALL PLA439 (0.0, LINE, 46, 0.5, 1, 2, 1.0, VRT)
          VRT = VRT - 1.0
          WRITE (LINE,
     1      '(''UISO   - Normalizing Uiso           '', F10.3)',
     2      IOSTAT = IOST) UISO
          CALL PLA439 (0.0, LINE, 46, 0.5, 1, 2, 1.0, VRT)
          VRT = VRT - 3
          WRITE (LINE,
     1      '(''Enter New Parameter Data Values, Continue or END'')',
     2      IOSTAT = IOST)
          CALL PLA439 (0.0, LINE, 50, 0.5, 5, 2, 1.0, VRT)
C * CHANGE PARAMETER VALUE LOOP
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          CALL GEN072 (IGGT, IFL, FN, IPR(220), IPR(221), 0, LU6,
     1               1, 1, 80, 7, NP17)
          KN = IPR(221)
          IF (IFL(1)(1:4) == 'UISO') THEN
            IF (KN > 0) UISO = FN(1)
          ELSE IF (IFL(1)(1:5) == 'NLOOP') THEN
            IF (KN > 0) THEN
              MLOOP(1) = NINT (FN(1))
              MLOOP(2) = MLOOP(1)
              MLOOP(3) = MLOOP(2)
              MLOOP(4) = MLOOP(3)
            END IF
          ELSE IF (IFL(1)(1:4) == 'NTRY') THEN
            IF (KN > 0) NTRY = NINT (FN(1))
          ELSE IF (IFL(1)(1:6) == 'NSOLVE') THEN
            IF (KN > 0) MXSOL = NINT (FN(1))
          ELSE IF (IFL(1)(1:5) == 'DELTA') THEN
            IF (KN > 0) FACTOR = FN(1)
          ELSE IF (IFL(1)(1:4) == 'PERC') THEN
            IF (KN > 0) PFLIP = FN(1)
          ELSE IF (IFL(1)(1:4) == 'SHOW') THEN
            IPR(614) = 1
          ELSE IF (IFL(1)(1:3) == 'END') THEN
            EXIT
          ELSE IF (IFL(1)(1:4) == 'CONT') THEN
            EXIT
          ELSE IF (IFL(1)(1:4) == 'STRU') THEN
            IPR(640) = 1
          ELSE IF (IFL(1)(1:4) == 'EXIT') THEN
            GOTO 80
          END IF
        END DO
        KN   = 0
      END IF
C * CHECK FOR SF-CALCULATION (TEST OPTION)
      IF (IPR(604) > 0 .AND. IPR(37) > 0) THEN
C * ANALYSES OF ANIS. TEMP. AND OUTPUT OF CONNECTED SET
        CALL PLA024
C * LOAD AND EXPAND COORDINATE DATA TO UNIT CELL CONTENTS
C * (EXCLUDING BRAVAIS CENTERING)
        CALL PLA023 (0)
      END IF
C * SETUP BINARY F(obs) REFLECTION FILE
      IGBL(16) = 0
      WRITE (LU6, 99993)
      CALL PLA151 (-1)
C * CHECK FOR NON-ZERO NUMBER OF REFLECTIONS
      IF (IPR(602) > 0) THEN
        DO I = 1, 3
          J          = 2 * I
          IHKLMAX(I) = MAX (-IPR(265 + J), IPR(266 + J))
        END DO
C * SORT REFLECTIONS ON F(OBS) AND COPY
        CALL GEN108 (LU19, 0)
        NREF = 0
   50   READ (LU19) F
        DO I = 1, 79, 6
          IF (NINT (F(I)) == 0) GO TO 70
          NREF       = NREF + 1
          VOID(NREF) = - F(I + 1)
        END DO
        GO TO 50
C * SORT RELECTIONS AND DETERMINE 'WEAK' LEVEL
   70   CALL GEN034 (VOID, 1, NREF)
        FOBSMIN  = - VOID(NINT (PFLIP * NREF))
C * OPEN GRAPHICS
        IGBL(6) = 31
        WRITE (LINE, 99998, IOSTAT = IOST)
        WRITE (LU6,  99997, IOSTAT = IOST) LINE
        WRITE (LU7,  99997, IOSTAT = IOST) LINE
        IF (IWIN == 1) THEN
          CALL GGIP (HORS, VERT, 0.0, 1)
          CALL PLA110 (HORS, VERT, -1)
          BCD = 'Click on Window to STOP Loops'//CHAR (0)
          CALL GGIP (-999.0, 2.0, 33.0, 111)
          VRT = VERT - 1.1
          IF (NTRY == 1) THEN
            VRTY = 0.80 * VERT
          ELSE
            VRTY = 0.38 * VERT
          END IF
          CALL PLA439 (0.0, LINE, 80, 0.55, 5, 2, 3.0, VRT)
          CALL GGIP (1.0,   0.0, 0.0, 3)
          CALL GGIP (HORS,  0.0, 0.0, 2)
          CALL GGIP (HORS, VRTY, 0.0, 2)
          CALL GGIP (1.0,  VRTY, 0.0, 2)
          CALL GGIP (1.0,   0.0, 0.0, 2)
          DO I = 1, 7
            VRTYI = (I - 1) * VRTY / 7.0
            CALL GGIP (1.0, VRTYI, 0.0, 3)
            CALL GGIP (1.3, VRTYI, 0.0, 2)
            WRITE (NQ1, 99995, IOSTAT = IOST) I * 10
            CALL PLA439 (0.0, NQ1, 2, 0.15, 1, 1, 1.05, VRTYI + 0.08)
          END DO
          CALL PLA439 (90.0, 'R-Value' , 7, 0.35, 1, 2, 1.8, 0.2)
          CALL PLA439 (0.0,  'Log(N)-Iteration', 16, 0.35, 1, 2,
     1                 HORS -5.2, 0.1)
          CALL PLA439 (0.0, 'Experimental !', 14, 0.6, 2, 2, 2.1, 1.2)
          WRITE (LINE, 99996, IOSTAT = IOST)
     1      FACTOR, PFLIP * 100.0, UISO, PAR(466), PAR(467)
          CALL PLA439 (0.0, LINE, 80, 0.25, 5, 1, 3.0, VRTY - 0.3)
          CALL PLA439 (0.0, 'Spgr    Rexor Frq Nsl Try', 25, 0.25,
     1                 5, 1, HORS - 5.5, VRTY - 0.35)
          CALL GGIP (0.0, 0.0, 0.0, 6)
        END IF
        WRITE (LU6, 99994, IOSTAT = IOST)
     1    NTRY, (MLOOP(I), I = 1, 4), MXSOL, FACTOR, PFLIP * 100.0, UISO
        WRITE (LU7, 99994, IOSTAT = IOST)
     1    NTRY, (MLOOP(I), I = 1, 4), MXSOL, FACTOR, PFLIP * 100.0, UISO
C * FLIP
        CALL PLA351
C * VIEW/REFINE RESULT
        IF (NSOLVED > 0) THEN
C * FLIPPER MODE
          IF (IPR(640) == 0) THEN
            CALL GEN129 (LU23, 'satom.def')
C * RUN PLUTON
            KERR = 0
            IF (DOS) THEN
              CALL SPAWN (PLAPATH(1:IGBL(80))//' -r +0pluton.log '//
     1          NAMEFIL(1:KNMFIL)//'_res.res', LU6, .true., KERR)
            ELSE
              CALL SPAWN (PLAPATH(1:IGBL(80))//' -r '//
     1          NAMEFIL(1:KNMFIL)//'_res.res', LU6, .true., KERR)
            END IF
C * STRUCTURE? MODE
          ELSE IF (IPR(640) == 1) THEN
            IF (IGBL(110) > 0) CALL PLA353
          END IF
        END IF
C * CLEANUP .bin, INTERMEDIATE AND NEXT FILES
        IF (IGBL(16) == 1) THEN
          CLOSE (UNIT = LU19, STATUS = 'DELETE')
          IGBL(16) = 0
        END IF
        CLOSE (UNIT = LU7, STATUS = 'DELETE')
        CALL GEN129 (LU64, 'NEXT')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_res.pjn')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_xor.ins')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_xor.hkl')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_xor.bin')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'.def')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_ads_pl.spf')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_ads.ins')
        CALL GEN129 (LU64, NAMEFIL(1:KNMFIL)//'_ads.lis')
        CALL GEN129 (LU64, 'satom.spf')
      END IF
   80 IGBL(6) = 10
      RETURN
99999 FORMAT (A)
99998 FORMAT ('Charge Flipping Ab Initio Structure Solution')
99997 FORMAT (/, A, /)
99996 FORMAT ('Delta =', F7.3, ', Perc =', F5.1, ', UISO =',
     1         F6.3, ', RFLMX =', F5.2, ', REXMX =', F5.2)
99995 FORMAT (I2)
99994 FORMAT ('Number of Trials ....... =', I6, /,
     1        'Max Number of Flips .... =', 4I6, /,
     2        'Max Mumber of Solutions  =', I6, /,
     3        'Flip Factor Delta ...... =', F6.3, /,
     4        'Phase Shift Percentage . =', F6.1, /,
     5        'Normalizing U .......... =', F6.2, /)
99993 FORMAT (/, '** SETUP BINARY F(OBS) REFLECTION FILE **', /)
      END SUBROUTINE PLA350
 
      SUBROUTINE PLA351
C * THIS ROUTINE IMPLEMENTS THE CHARGE FLIPPING CONCEPT - Oszlanyi et al.
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE cflip
      USE comdrie
      USE exor
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      INTEGER :: ISN
      INTEGER :: LOC
      INTEGER :: IDUM
      INTEGER :: ITOP1
      INTEGER :: ITOP2
      INTEGER :: NSYMH
      INTEGER :: NTITLE
      REAL :: PHI
      REAL :: PHIA
      REAL :: YUNK
      REAL :: AOBS
      REAL :: BOBS
      REAL :: FOBS
      REAL :: ACAL
      REAL :: BCAL
      REAL :: ACALA
      REAL :: BCALA
      REAL :: FS000
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: GEN013
      CHARACTER(len=7) :: SPGRSAV
C * GET # OF TRIALS
      RVMIN    = 1.0
      NSOLVMIN = 0
      IPEN     = 4
      NSPGR    = 0
      MFTRY    = 0
C * INITIALIZE RANDOM NUMBER GENERATOR
      IDUM     = -1
      PHI      = GEN013 (IDUM)
C * GET SPGR NAME (FOR DATA EXPANSION TO P1)
      CALL SGSM (18, IDM, SGX, 0, 0, IERR)
      SPGRSAV = IDM(1:7)
      CALL GEN038 (PRBUF, 1, 132)
      IPR(409) = 1
C * GET SUITABLE FFT-GRID
      DO I = 1, 3
        DO J = 4, 8
          IPR(I + 394) = 2**J
          IF (PAR(I + 100) * 3.0 < IPR(I + 394)) EXIT
        END DO
      END DO
      DO I = 1, 3
        J = IPR(394 + I)
        IF (2 * IHKLMAX(I) >= IPR(J)) IPR(J) = IPR(J) * 2
      END DO
      M1    = IPR(395)
      M2    = IPR(396)
      M3    = IPR(397)
      NGRID = M1 * M2 * M3
      WRITE (LU6, 99999, IOSTAT = IOST) M1, M2, M3
      WRITE (LU7, 99999, IOSTAT = IOST) M1, M2, M3
C * FFT
      ITOP  = NGRID * 2
      ITOP1 = 2 * ITOP
      ITOP2 = ITOP1 + 3 * (M1 + 2) * (M2 + 2)
C * CHECK FOR SCRATCH OVERRUN (2*FFT + R3D)
      IF (ITOP2 > NVDR) THEN
        IPR(2) = 49
      ELSE
        WRITE (LINE, 99997, IOSTAT = IOST)
        WRITE (LU6,  99998, IOSTAT = IOST) LINE
        WRITE (LU7,  99998, IOSTAT = IOST) LINE
        IF (IWIN == 1) THEN
          VRT = VRT - 0.7
          CALL PLA439 (0.0, LINE, 80, 0.32, 5, 2, 1.0, VRT)
          VRT = VRT - 0.2
        END IF
        CALL GGIP (0.0, 0.0, 0.0, 6)
        NSYMH   = IPR(255)
        NSOLVED = 0
        NLOOP   = MLOOP(1)
        NTEL    = 0
C * LOOP FOR NTRY TRIALS
        DO M = 1, NTRY
          IF (CC) GO TO 40
          IDM = 'SPGR '//SPGRSAV
          CALL SGSM (0, IDM, SGX, 0, LU6, IERR)
          IPEN = MOD (IPEN + 1, 5) + 1
          MTRY = M
          IF (NSOLVED == 0) THEN
            IF (M > 3) THEN
              NLOOP = MLOOP(2)
              IF (M > 6) THEN
                NLOOP = MLOOP(3)
                IF (M > 10) THEN
                  NLOOP = MLOOP(4)
                END IF
              END IF
            END IF
          ELSE IF (NSOLVED == 1) THEN
            IF (M > 5) THEN
              NLOOP = MLOOP(2)
              IF (M > 10) THEN
                NLOOP = MLOOP (3)
                IF (M > 15) THEN
                  NLOOP = MLOOP(4)
                END IF
              END IF
            END IF
          END IF
          VRT = VRT - 0.4
C * LOAD SAVE-FFT array from data in .bin
C * F(I)     = PACKED HKL (0 = END)
C * F(I + 1) = F(OBS)
C * F(I + 2) = SIGMA**2(F)
C * F(I + 3) = 8*PI**2*(SINTH/LAMBDA)**2
C * F(I + 4) = ACALC
C * F(I + 5) = BCALC
C * ZERO ARRAY
          CALL GEN074 (VOID, 1, ITOP1, 0.0)
          RVAL0   = 1.0
          FS000   = 0.0
          VOID(1) = FS000
          CALL GEN108 (LU19, 0)
   20     READ (LU19) F
          DO I = 1, 79, 6
            IF (NINT (F(I)) == 0) GO TO 30
            CALL GEN046 (F(I), SGX(1), SGX(2), SGX(3))
            FOBS = F(I + 1) * EXP (UISO * F(I + 3))
            PHI  = 0.0
C * TEST for PHASES TO BE CALCULATES FROM INPUT MODEL
            IF (IPR(604) /= 0) THEN
              ACAL = 0.0
              BCAL = 0.0
              CALL PLA137 (NINT (SGX(1)), NINT (SGX(2)), NINT (SGX(3)),
     1          ACAL, BCAL, ACALA, BCALA, ACALAF, BCALAF, YUNK)
              ACAL = ACAL + ACALA
              BCAL = BCAL + BCALA
              PHI  = ATAN2 (BCAL, ACAL) * RGBL(6)
            END IF
C * EXPAND
            DO N = 1, NSYMH
              SGX(4) = PHI
              CALL SGSM (5, LINE, SGX, N, LU6, IERR)
              IHT = NINT (SGX(7))
              IKT = NINT (SGX(8))
              ILT = NINT (SGX(9))
C * ASSIGN RANDOM PHASE (FOR MTRY > 1)
              IF (MTRY > 1 .OR. NTRY > 1) THEN
C * GET RANDOM PHASE
                PHI  = GEN013(IDUM) * RGBL(5)
                AOBS = FOBS * COS (PHI)
                BOBS = FOBS * SIN (PHI)
              ELSE
                IF (IPR(604) == 0) THEN
                  AOBS = FOBS
                  BOBS = 0.0
                ELSE
                  PHIA = SGX(10) / RGBL(6)
                  AOBS = FOBS * COS (PHIA)
                  BOBS = FOBS * SIN (PHIA)
                END IF
              END IF
              ISN  = -1
              DO J = 1, 2
                ISN = - ISN
                IH = ISN * IHT
                IK = ISN * IKT
                IL = ISN * ILT
                IF (IH < 0) IH = IH + M1
                IF (IK < 0) IK = IK + M2
                IF (IL < 0) IL = IL + M3
                LOC = 2 * ((IL * M2 + IK) * M1 + IH + 1)
                VOID(LOC - 1)        = ISN * ABS (FOBS)
                VOID(LOC)            = 4 * SQRT (F(I + 2))
                VOID(ITOP + LOC - 1) = AOBS
                VOID(ITOP + LOC)     = ISN * BOBS
              END DO
            END DO
          END DO
          GO TO 20
   30     IDM = 'SPGR '//SPGRSAV(1:1)//'1'
          CALL SGSM (0,  IDM, SGX, 0, 0, IERR)
          CALL SGSM (18, IDM, SGX, 0, 0, IERR)
          IPR(48) = NINT (SGX(9))
C * FLIP ROUTINE
          CALL PLA352 (VOID(1), VOID(ITOP + 1), VOID(ITOP1 + 1))
          IF ( RVMIN < PAR(570)) EXIT
        END DO
   40   CLOSE (UNIT = LU60)
        CLOSE (UNIT = LU63)
        IF (NSOLVED > 0) THEN
C * SELECT/COPY THE MOST PROMISING SOLUTION
          OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_sol.res',
     1          STATUS = 'UNKNOWN')
          OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_res.res',
     1          STATUS = 'UNKNOWN')
          NTITLE = 0
   50     READ (LU61, 99998, IOSTAT = IOST) LINE
          IF (IOST == -1) GO TO 70
          IF (LINE(1:4) == 'TITL') THEN
            NTITLE = NTITLE + 1
            IF (NTITLE /= NSOLVMIN) GO TO 50
            WRITE (LU62, 99998, IOSTAT = IOST) LINE
   60       READ (LU61, 99998, IOSTAT = IOST) LINE
            IF (IOST == -1) GO TO 70
            IF (LINE(1:4) == 'SFAC') THEN
              WRITE (LU62, 99998, IOSTAT = IOST) LINE
            ELSE IF (LINE(1:4) == 'UNIT') THEN
              WRITE (LU62, 99998, IOSTAT = IOST) LINE
            ELSE IF (LINE(1:4) == '    ') THEN
            ELSE IF (LINE(1:4) == 'TITL') THEN
              GO TO 70
            ELSE
              WRITE (LU62, 99998, IOSTAT = IOST) LINE
            END IF
            GO TO 60
          ELSE
            GO TO 50
          END IF
   70     CLOSE (UNIT = LU61)
          CLOSE (UNIT = LU62)
        END IF
      END IF
      RETURN
99999 FORMAT ('FFT grid =', 3I5, /)
99998 FORMAT (A)
99997 FORMAT ('Try Loop(  max) Delta Phi Rho(min) Rho(max) F000 ',
     1        ' R(F) DeltaR Npk Rexor Nat Spgr')
      END SUBROUTINE PLA351
 
      SUBROUTINE PLA352 (FFT1, FFT2, R3D)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE cflip
      USE comdrie
      USE exor
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IG
      INTEGER :: NAT
      INTEGER :: ISN
      INTEGER :: NPK
      INTEGER :: NSP
      INTEGER :: NPK0
      INTEGER :: ITEL
      INTEGER :: MTEL
      INTEGER :: ISKIP
      INTEGER :: NCURC
      INTEGER :: NCOUNT
      INTEGER :: NCURVE
      REAL :: XG
      REAL :: YG
      REAL :: XP
      REAL :: YP
      REAL :: ZG
      REAL :: ACAL
      REAL :: BCAL
      REAL :: DELR
      REAL :: DELT
      REAL :: DENS
      REAL :: F000
      REAL :: FCAL
      REAL :: FFTX
      REAL :: FOBS
      REAL :: RMAX
      REAL :: RMIN
      REAL :: RVAL
      REAL :: SUMX
      REAL :: SXSQ
      REAL :: TERM
      REAL :: XPOLD
      REAL :: YPOLD
      REAL :: SUMDL
      REAL :: SUMFC
      REAL :: SUMFO
      REAL :: REXOR
      REAL :: VRT20
      REAL :: RHOMIN
      REAL :: SCHAAL
      REAL, DIMENSION(*) :: R3D
      REAL, DIMENSION(*) :: FFT1
      REAL, DIMENSION(*) :: FFT2
      CHARACTER(len=4)  :: SFT
      CHARACTER(len=7)  :: SPGR
      CHARACTER(len=80) :: SLINE
C * RES-STYLE OUTPUT
      IF (ABS(IGBL(8)) == 3) THEN
        M = 2
      ELSE
        M = 3
      END IF
      RHOMIN = 2.0 * PAR(98)
      RVAL   = 1.0
      DELR   = 1.0
      REXOR  = 0.0
      TERM   = 1.0
      ITEL   = 0
      MTEL   = 0
      NCURVE = 0
      NCURC  = 0
C * FLIP CYCLE ITERATION
      DO N = 1, NLOOP
C * FIRST CHECK FOR INTERRUPT RETURNED IN IG
        XG = 0.0
        YG = 0.0
        ZG = 0.0
        IG = 9
        CALL GGIP (XG, YG, ZG, IG)
        IF (IG == 1) THEN
C * INQUIRE ON HOW TO PROCEED
          CALL PLA012 (0, 1)
          CALL GEN072 (IGGT, IFL, FN, IPR(220), IPR(221), 0, LU6,
     1                   1, 1, 80, 7, NP17)
          IF (IGGT(1:1) == 'N' .OR. IGGT(1:3) == 'END' .OR.
     1        IGGT(1:4) == 'EXIT') THEN
            CC   = .TRUE.
            GO TO 20
          ELSE IF (IGGT(1:4) == 'CONV') THEN
            CC   = .TRUE.
            TERM = 0.0
          ELSE IF (IGGT(1:4) == 'CONT') THEN
            CC   = .FALSE.
          ELSE IF (IFL(1)(1:4) == 'FACT') THEN
            FACTOR = FN(1)
            CC   = .FALSE.
          END IF
          IF (IWIN == 1) THEN
            CALL PLA439 (0.0, SLINE, 80, 0.32, 1, 2, 1.0, VRT)
            CALL GGIP (0.0, 0.0, 0.0, 6)
          END IF
        END IF
C * TRANSFORM TO DIRECT SPACE
        CALL GEN028 (FFT2, IPR(395), 3, -1)
C * GET DENSITY EXTREMA
        RMIN = 0.0
        RMAX = 0.0
        F000 = 0.0
        SXSQ = 0.0
        SUMX = 0.0
        DO I = 1, ITOP - 1, 2
          FFTX = FFT2(I)
          SXSQ = SXSQ + FFTX ** 2
          SUMX = SUMX + FFTX
          RMIN = MIN (RMIN, FFTX)
          RMAX = MAX (RMAX, FFTX)
        END DO
C * DETERMINE ACTUAL FLIP FRACTION AND FLIP DENSITY
        DENS = TERM * FACTOR * RMAX
        DO I = 1, ITOP -1, 2
          IF (TERM > 0) THEN
            IF (FFT2(I) < DENS) FFT2(I) = - FFT2(I)
          ELSE
            IF (FFT2(I) < FACTOR * RMAX) FFT2(I) = 0.0
          END IF
          FFT2(I + 1) = 0.0
        END DO
C * PEAK-SEARCH
        IF (IPR(614) > 0) THEN
            CALL PLA140 (FFT2, R3D, 0, RHOMIN, 1, NPK0, 1, 1)
            NPK = MIN (999, MIN (NPK0, NINT (PAR(98) / 14.0)))
            CALL PLA355 (0, LU60, NPK, M, N, RVAL)
          CALL PLA355 (1, LU61, NPK, M, N, RVAL)
        END IF
C * TRUNCATE HIGHEST DENSITIES
        IF (RVAL > PAR(468)) THEN
          DO I = 1, ITOP -1, 2
            IF (FFT2(I) > RMAX + 0.25 * RMIN) THEN
              FFT2(I) = 0.5 * FFT2(I)
            END IF
          END DO
        END IF
C * TRANSFORM BACK TO STRUCTURE FACTOR SPACE
        CALL GEN028 (FFT2, IPR(395), 3, 1)
C * DETERMINE SCALING FACTOR
        SUMFO = 0.0
        SUMFC = 0.0
        DO I = 3, ITOP, 2
          FOBS = ABS (FFT1(I))
          IF (FOBS > 0.0) THEN
            FCAL  = SQRT (FFT2(I) ** 2 + FFT2(I + 1) ** 2) / NGRID
            SUMFO = SUMFO + FOBS
            SUMFC = SUMFC + FCAL
          END IF
        END DO
        SCHAAL = SUMFC / SUMFO
        SUMDL  = 0.0
C * F000
        F000  = FFT2(1) / (SCHAAL * NGRID)
C * APPLY UPDATED PHASES TO FOBS
        FFT2(1) = 0.0
        FFT2(2) = 0.0
        DO 10 I = 3, ITOP, 2
          ISN = 1
          FOBS = FFT1(I)
          IF (FOBS /= 0.0) THEN
            IF (FOBS < 0.0) THEN
              FOBS = - FOBS
              ISN  = -1
            END IF
            ACAL = FFT2(I)     / (SCHAAL * NGRID)
            BCAL = FFT2(I + 1) / (SCHAAL * NGRID)
            FCAL = SQRT (ACAL ** 2 + BCAL ** 2)
            SUMDL = SUMDL + ABS (FOBS - FCAL)
C * SHIFT PHASES BY 90 DEGREES FOR WEAK REFLECTIONS
            SFT = ' '
            IF (PFLIP > 0.0) THEN
              IF (RVAL > 0.40 .AND. N > 100) THEN
                SFT = '  90'
                IF (FOBS < FOBSMIN) THEN
                  FFT2(I)     = - BCAL
                  FFT2(I + 1) =   ACAL * ISN
                  GO TO 10
                END IF
              END IF
            END IF
            FFT2(I)     = FOBS * ACAL / FCAL
            FFT2(I + 1) = FOBS * BCAL / FCAL
          ELSE
            FFT2(I)     = 0.0
            FFT2(I + 1) = 0.0
          END IF
   10   CONTINUE
C * REPORT STATUS AND RESULTS FOR THIS CYCLE
        RVAL  = SUMDL / SUMFO
        RMIN  = RMIN  / (2.0 * PAR(98))
        RMAX  = RMAX  / (2.0 * PAR(98))
        DELT  = DENS  / (2.0 * PAR(98))
        DELR  = RVAL0 - RVAL
        RVAL0 = RVAL
        IF (IWIN == 1) THEN
          IF (IPR(614) == 1) THEN
            VRT20 = 0.2
          ELSE
            VRT20 = VRT
            CALL PLA439 (0.0, SLINE, 80, 0.32, 0, 2, 1.0, VRT20)
          END IF
          WRITE (SLINE, 99991, IOSTAT = IOST)
     1      MTRY, N, NLOOP, DELT, SFT, RMIN, RMAX, NINT (F000), RVAL,
     2      DELR
          CALL PLA439 (0.0, SLINE, 80, 0.32, IPEN, 2, 1.0, VRT20)
          CALL GGIP (0.0, FLOAT (IPEN), 0.0, 0)
          XP = 1.0 + (HORS - 1.0) * LOG (FLOAT(N)) / LOG (FLOAT (NLOOP))
          YP = VRTY * (MIN (0.8, RVAL) - 0.1) / 0.7
          IF (IPR(614) == 0) THEN
            IF (N > 1) THEN
              CALL GGIP (XPOLD, YPOLD , 0.0, 3)
              CALL GGIP (XP,    YP    , 0.0, 2)
            END IF
            XPOLD = XP
            YPOLD = YP
          ELSE
            IF (NCURVE < 5001) THEN
              NCURVE            = NCURVE + 1
              RCURVE(NCURVE, 1) = XP
              RCURVE(NCURVE, 2) = YP
              IF (RVAL < PAR(467) .AND. NCURC == 0) NCURC = NCURVE
            END IF
            CALL GGIP (0.0, 2.0, 0.0, 0)
            IF (NCURVE > 1) THEN
              CALL GGIP (RCURVE(1, 1), RCURVE(1, 2), 0.0, 3)
              DO I = 2, NCURVE
                IF (I == NCURC) CALL GGIP (0.0, 3.0, 0.0, 0)
                CALL GGIP (RCURVE(I, 1), RCURVE(I, 2), 0.0, 2)
              END DO
            END IF
          END IF
          CALL GGIP (0.0, 0.0, 0.0, 6)
        END IF
        WRITE (LU7, 99996, IOSTAT = IOST) LINE
C * CHECK FOR LOOP TERMINATION
        IF (N < NLOOP - 10) THEN
          IF (RVAL < 0.35) THEN
            IF (RVAL < PAR(467)) THEN
              IF (ABS (DELR) < 0.005) THEN
                ITEL = ITEL + 1
                IF (ITEL > 5) TERM = 0.0
                IF (ITEL > 20) GO TO 20
              ELSE
                ITEL = 0
              END IF
            ELSE
              IF (ABS (DELR) < 0.005) THEN
                MTEL = MTEL + 1
                IF (MTEL > 25) THEN
                  TERM = TERM * 0.5
                  MTEL = 0
                  ITEL = 0
                END IF
                IF (TERM < 0.01) TERM = 0.0
              ELSE
                MTEL = 0
                ITEL = 0
              END IF
            END IF
          END IF
        ELSE
          TERM = 0.0
          RETURN
        END IF
      END DO
   20 WRITE (LU6, 99996, IOSTAT = IOST) LINE
      IF (RVAL < PAR(466)) THEN
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_ads.ins',
     1        STATUS = 'UNKNOWN')
C * FINAL MAP
        CALL GEN028 (FFT2, IPR(395), 3, -1)
C * PEAK-SEARCH
        CALL PLA140 (FFT2, R3D, 0, RHOMIN, 1, NPK0, 1, 1)
        NPK = MIN (999, MIN (NPK0, NINT (PAR(98) / 14.0)))
        CALL PLA355 (0, LU60, NPK, M, N, RVAL)
        CALL PLA355 (0, LU61, NPK, M, N, RVAL)
        CLOSE (UNIT = LU61)
        CALL GEN129 (LU61, NAMEFIL(1:KNMFIL)//'_xor.bin')
        SPGR   = ' '
C * RUN ADDSYM
        KERR = 0
        IF (DOS) THEN
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -N +0addsym.log '//
     1      NAMEFIL(1:KNMFIL)//'_ads.ins', LU6, .true., KERR)
        ELSE
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -N '//
     1      NAMEFIL(1:KNMFIL)//'_ads.ins', LU6, .true., KERR)
        END IF
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_ads_pl.res',
     1      STATUS = 'UNKNOWN')
C * FILTER TO EXOR INPUT
        OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_xor.ins',
     1      STATUS = 'UNKNOWN')
        ISKIP = 0
   30   READ (LU61, 99996, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 40
        IF (LINE(1:4) == 'TITL') THEN
          SPGR = LINE(39:45)
        ELSE IF (LINE(1:4) == 'UNIT') THEN
          ISKIP = 0
          WRITE (LU62, 99983, IOSTAT = IOST)
     1      (LMT(IENS(K), 1), K = 1, IAN)
          WRITE (LU62, 99982, IOSTAT = IOST)
     1      (NINT (CONT(IENS(L), M)), L = 1, IAN)
          GO TO 30
        ELSE IF (LINE(1:4) == 'SFAC') THEN
          ISKIP = 1
        END IF
        IF (ISKIP == 0) WRITE (LU62, 99996, IOSTAT = IOST) LINE
        GO TO 30
   40   CLOSE (UNIT = LU61, STATUS = 'DELETE')
        CLOSE (UNIT = LU62)
C * RUN EXOR
        REXOR = 0.0
        KERR  = 0
        IF (DOS) THEN
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -E +0exor.log '//
     1      NAMEFIL(1:KNMFIL)//'_xor.ins', LU6, .true., KERR)
        ELSE
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -E '//
     1      NAMEFIL(1:KNMFIL)//'_xor.ins', LU6, .true., KERR)
        END IF
C * GET RESULT FROM LOG FILE
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_xor_log',
     1        STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99996, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          N = INDEX (LINE, 'RVAL=')
          IF (N /= 0) READ (LINE(13:18), 99998) REXOR
        END DO
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_xor.res',
     1        STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = NAMEFIL(1:KNMFIL)//'_ads.ins',
     1      STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99996, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          WRITE (LU62, 99996, IOSTAT = IOST) LINE
        END DO
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
        CLOSE (UNIT = LU62)
C * RUN ADDSYM
        KERR = 0
        IF (DOS) THEN
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -N +0addsym.log '//
     1      NAMEFIL(1:KNMFIL)//'_ads.ins', LU6, .true., KERR)
        ELSE
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -N  '//
     1      NAMEFIL(1:KNMFIL)//'_ads.ins', LU6, .true., KERR)
        END IF
        OPEN (LU61, FILE = NAMEFIL(1:KNMFIL)//'_ads_pl.res')
        NAT    = 0
        NCOUNT = 0
        DO
          READ  (LU61, 99996, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          IF (LINE(1:4) == 'TITL') THEN
C * GET PROPOSED NEW SPGR NAME FROM TITL RECORD
            I = INDEX (LINE, 'New:') + 4
            SPGR = LINE(I:I + 6)
          ELSE IF (LINE(1:4) == 'FVAR') THEN
            NCOUNT = 1
          ELSE IF (LINE(1:4) == 'HKLF') THEN
            NCOUNT = 0
          ELSE
            NAT = NAT + NCOUNT
          END IF
          WRITE (LU63, 99996, IOSTAT = IOST) LINE
        END DO
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
        IF (IWIN == 1) CALL PLA439 (0.0, PRBUF, 25, 0.25, 0, 1,
     1    HORS - 5.5, VRTY - 0.7)
        CALL GGIP (0.0, 0.0, 0.0, 6)
        NSOLVED = NSOLVED + 1
          IDM     = 'SPGR '//SPGR
          CALL SGSM (0,  IDM, SGY, 0, LU6,  IERR)
          CALL SGSM (18, IDM, SGY, 0,   0,  IERR)
          NSP = NINT (SGY(1))
          IF (REXOR < RVMIN) THEN
            IF (NSP > NSPGR) THEN
              PRBUF(1:7) = SPGR
              NSPGR      = NSP
              NTEL       = 0
            END IF
          END IF
          IF (NSP > NSPGR) THEN
            IF (REXOR < RVMIN) THEN
              PRBUF(1:7) = SPGR
              NSPGR      = NSP
              RVMIN      = REXOR
              NSOLVMIN   = NSOLVED
              MFTRY      = MTRY
              NTEL       = 1
            END IF
          ELSE IF (NSP == NSPGR) THEN
            NTEL = NTEL + 1
            IF (REXOR < RVMIN) THEN
              RVMIN    = REXOR
              NSOLVMIN = NSOLVED
              MFTRY    = MTRY
            END IF
          END IF
        WRITE (PRBUF(8:49), 99980, IOSTAT = IOST)
     1     RVMIN, NTEL, NSOLVMIN, MFTRY
        IF (IWIN == 1 .AND. RVMIN < 1.0) THEN
          CALL PLA439 (0.0, PRBUF, 25, 0.25, 1, 1, HORS - 5.5,
     1                 VRTY - 0.7)
          CALL GGIP (0.0, 0.0, 0.0, 6)
        END IF
C * REPORT REXOR AND SPACE GROUP
        IF (IWIN == 1) THEN
          WRITE (LINE, 99981, IOSTAT = IOST) NPK
          IF (REXOR > 0.0) THEN
            WRITE (LINE(5:10), 99998, IOSTAT = IOST) REXOR
              WRITE (LINE(11:), 99997, IOSTAT = IOST) NAT, SPGR
              WRITE (LU6, 99996) LINE
          END IF
          CALL PLA439 (0.0, LINE(1:23), 23, 0.32, IPEN, 2, 17.8, VRT)
          CALL GGIP (0.0, FLOAT (IPEN), 0.0, 0)
          CALL GGIP (0.0, 0.0, 0.0, 6)
        END IF
      END IF
      RETURN
99998 FORMAT (F6.3)
99997 FORMAT (I4, 1X, A)
99996 FORMAT (A)
99991 FORMAT (I3, I5, '(', I5, ')', F6.3, A, 2F9.3, I5, F6.3, F7.3)
99983 FORMAT ('SFAC', 16(1X, A))
99982 FORMAT ('UNIT ', 2I5, 14I4)
99981 FORMAT (I4)
99980 FORMAT (F6.3, 3I4)
      END SUBROUTINE PLA352
 
      SUBROUTINE PLA353
      USE files
      USE parameters
      USE cchar
      USE cggt
      IMPLICIT NONE
      IF (IWIN == 1) THEN
        CALL PLA439 (0.0, 'RefinemenT', 10, 2.5, 2, 10, 3.0, 12.0)
        CALL GGIP (0.0, 0.0, 0.0, 6)
      END IF
C * SHELXL ISO
      CALL PLA354 (0, LU61, LU62, '_res.res', '_shx.ins')
      CALL PLA354 (0, LU61, LU62, '_xor.hkl', '_shx.hkl')
      KERR = 0
      CALL SPAWN (SHLPATH(1:IGBL(110))//' '//
     1            NAMEFIL(1:KNMFIL)//'_shx', LU6, .true., KERR)
C * SHELXL ANISO
      CALL PLA354 (1, LU61, LU62, '_shx.res', '_shx.ins')
      KERR = 0
      CALL SPAWN (SHLPATH(1:IGBL(110))//' '//
     1            NAMEFIL(1:KNMFIL)//'_shx', LU6, .true., KERR)
C * DIFFOURIER
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -D '//
     1            NAMEFIL(1:KNMFIL)//'_shx.res', LU6, .true., KERR)
C * AUTO RENAME
      CALL PLA354 (0, LU61, LU62, '_shx.res', '_shx.ins')
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -R '//
     1            NAMEFIL(1:KNMFIL)//'_shx.ins', LU6, .true., KERR)
C * RUN HFIX
      CALL PLA354 (0, LU61, LU62, '_shx.res', '_shx.ins')
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -f '//
     1            NAMEFIL(1:KNMFIL)//'_shx.ins', LU6, .true., KERR)
C * RUN SHELXL HATOMS
      CALL PLA354 (0, LU61, LU62, '_shx.new', '_shx.ins')
      KERR = 0
      CALL SPAWN (SHLPATH(1:IGBL(110))//' '//
     1            NAMEFIL(1:KNMFIL)//'_shx', LU6, .true., KERR)
C * RUN ORTEP
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -a '//
     1            NAMEFIL(1:KNMFIL)//'_shx.cif', LU6, .true., KERR)
 
      RETURN
      END SUBROUTINE PLA353
 
      SUBROUTINE PLA354 (MODE, LUA, LUB, EXTENA, EXTENB)
      USE files
      USE cchar
      IMPLICIT NONE
      INTEGER          :: MODE, LUA, LUB
      CHARACTER(len=8) :: EXTENA, EXTENB
      CHARACTER(len=4) :: KEY
      OPEN (LUA, FILE = NAMEFIL(1:KNMFIL)//EXTENA, STATUS = 'UNKNOWN')
      OPEN (LUB, FILE = NAMEFIL(1:KNMFIL)//EXTENB, STATUS = 'UNKNOWN')
      DO
        READ  (LUA, 99999, IOSTAT = IOST) KEY, LINE
        IF (IOST /= 0) EXIT
        IF (MODE == 1) THEN
          IF (KEY == 'L.S.') WRITE (LUB, 99998, IOSTAT = IOST) 1000
        END IF
        WRITE (LUB, 99999, IOSTAT = IOST) KEY, LINE
      END DO
      CLOSE (UNIT = LUA)
      CLOSE (UNIT = LUB)
      RETURN
99999 FORMAT (2A)
99998 FORMAT ('ANIS', I5)
      END SUBROUTINE PLA354
 
      SUBROUTINE PLA355 (MODE, LU, NPK, M, N, RVAL)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE cflip
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: K1
      INTEGER :: LU
      INTEGER :: KEL
      INTEGER :: NPK
      INTEGER :: MODE
      INTEGER :: KNM1
      INTEGER :: IGBL8
      INTEGER :: IANSAVE
      INTEGER, DIMENSION(NP12) :: IPRSAVE
      REAL :: RVAL
      REAL :: SHORT
      REAL :: USIMUL
      REAL, DIMENSION(NP13) :: PARSAVE
      CHARACTER(len=10) :: PROJ
      CHARACTER(len=80) :: NAME1
      CHARACTER(len=43) :: FORMA
      FORMA(1:43) = '(A,I1,4X,I3,3F10.3,'' 11'',F10.4,'' ! '',F12.2)'
C * OPEN FOR SHOW MODE
      IF (MODE == 1) THEN
        OPEN (LU, FILE = 'satom.spf', STATUS = 'UNKNOWN')
      END IF
C * SELECT DEFAULT ATOM-TYPE
      DO K = 1, IAN
        IF (LMT(IENS(K), 1) == ' C') THEN
          KEL = K
          K1  = 2
          GO TO 10
        END IF
      END DO
      DO K = 1, IAN
        IF (LMT(IENS(K), 1) /= ' H') THEN
          KEL = K
          K1  = 1
          IF (LMT(IENS(K), 1)(1:1) == ' ') K1 = 2
          GO TO 10
        END IF
      END DO
   10 WRITE (LU, 99998, IOSTAT = IOST) MTRY, N, RVAL
      WRITE (LU, 99999, IOSTAT = IOST) PAR(17), (PAR(100 + I), I = 1, 6)
      WRITE (LU, 99992, IOSTAT = IOST) (PAR(106 + I), I = 1, 6)
      WRITE (LU, 99991, IOSTAT = IOST)  - IABS (IPR(242))
      WRITE (LU, 99990, IOSTAT = IOST) (LMT(IENS(K), 1), K = 1, IAN)
      WRITE (LU, 99995, IOSTAT = IOST)
     1  (NINT (CONT(IENS(L), M)), L = 1, IAN)
      WRITE (LU, 99993, IOSTAT = IOST)
      DO J = 1, NPK
        USIMUL = 0.05 * SQRT (XXO(J, 4) / XXO(1, 4))
        IF (J < 10) THEN
          FORMA(5:5) = '1'
        ELSE IF (J. LT. 100) THEN
          FORMA(5:5) = '2'
        ELSE IF (J < 1000) THEN
          FORMA(5:5) = '3'
        END IF
        WRITE (LU, FORMA, IOSTAT = IOST)
     1    LMT(IENS(KEL), 1)(K1:2), J, KEL,
     2    (XXO(J, K), K = 1, 3), USIMUL,  XXO(J, 4)
      END DO
      WRITE (LU, 99994, IOSTAT = IOST)
C * SHOW MODE
      IF (MODE == 1) THEN
        CLOSE (UNIT = LU61)
        IGBL(3)  = 8
        IGBL(92) = 1
        IGBL(50) = 1
        DO I = 1, NP12
          IPRSAVE(I) = IPR(I)
        END DO
        DO I = 1, NP13
          PARSAVE(I) = PAR(I)
        END DO
        IANSAVE = IAN
        OPEN (LU23, FILE = 'satom.def', STATUS = 'UNKNOWN')
        SHORT = MIN (PAR(101), PAR(102), PAR(103))
        IF (SHORT == PAR(101)) THEN
          IF (PAR(102) >= PAR(103)) THEN
            PROJ = 'XO'
          ELSE
            PROJ = 'XO ZROT 90'
          END IF
          WRITE (LU23, 99997, IOSTAT = IOST)
     1      -5.0, 5.0, -0.01, 1.01, -0.01, 1.01
        ELSE IF (SHORT == PAR(102)) THEN
          IF (PAR(103) > PAR(101)) THEN
            PROJ = 'YO'
          ELSE
            PROJ = 'YO ZROT 90'
          END IF
          WRITE (LU23, 99997, IOSTAT = IOST)
     1      -0.01, 1.01, -5.0, 5.0, -0.01, 1.01
        ELSE
          IF (PAR(101) > PAR(102)) THEN
            PROJ = 'ZO'
          ELSE
            PROJ = 'ZO ZROT 90'
          END IF
          WRITE (LU23, 99997, IOSTAT = IOST)
     1      -0.01, 1.01, -0.01, 1.01, -5.0, 5.0
        END IF
        WRITE (LU23, 99996, IOSTAT = IOST) PROJ
        CLOSE (UNIT = LU23)
        CLOSE (UNIT = LU1)
        NAME1   = NAMEFIL
        KNM1    = KNMFIL
        IGBL8   = IGBL(8)
        IGBL(8) = 1
        CALL GGIP (HORS, VERT, 0.0, 1)
        CALL PLUTON (0)
        IGBL(8) = IGBL8
        NAMEFIL = NAME1
        KNMFIL  = KNM1
        CLOSE (UNIT = LU1)
        DO I = 1, NP12
          IPR(I) = IPRSAVE(I)
        END DO
        DO I = 1, NP13
          PAR(I) = PARSAVE(I)
        END DO
        IAN = IANSAVE
        CLOSE (UNIT = LU1)
      END IF
      RETURN
99999 FORMAT ('CELL ', F9.5, 3F10.4, 3F10.3)
99998 FORMAT ('TITL F', I2.2, I3.3, ' R =', F5.2)
99997 FORMAT ('OMIT OUTSIDE', 6F6.3)
99996 FORMAT ('JOIN RADII UNIQUE', /, 'SET IPR 231 1', /,
     1        'VIEW ', A, /, 'UNITCELL', /, 'STRAW', /,
     2        'BOX OFF', /, 'PACK RANGE -0.5 1.5 -0.5 1.5 -0.5 1.5', /,
     3        'PLOT')
99995 FORMAT ('UNIT ', 2I5, 14I4)
99994 FORMAT ('HKLF 4', /, 'END')
99993 FORMAT ('FVAR 1.0')
99992 FORMAT ('ZERR 1 ', 3F10.4, 3F10.3)
99991 FORMAT ('LATT ', I5)
99990 FORMAT ('SFAC', 16(1X, A))
      END SUBROUTINE PLA355
 
      SUBROUTINE PLA360
C * Subroutine Analyses the Refinement results with a Difference Fourier
      USE files
      USE parameters
      USE reflex
      USE fab
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: HMAX
      INTEGER :: KMAX
      INTEGER :: LMAX
      INTEGER :: NSEL
      INTEGER :: NREF
      INTEGER :: IADR
      INTEGER :: IBOT
      INTEGER :: ITOP
      INTEGER :: NGRID
      INTEGER :: NREFA
      INTEGER :: NREFB
      REAL :: FO
      REAL :: FC
      REAL :: SCF
      REAL :: ACAL
      REAL :: BCAL
      REAL :: SIGF
      REAL :: SUMFO
      REAL :: SUMFC
C * PLA360 - PLA024 (CONNECTED COORD SET)
C *        - PLA023 (EXPAND COORD SET)
C *        - PLA133 (GET REFNS, H-,K-,LMAX) - PLA134 - PLA132
C *        - PLA130                         - PLA136 - PLA137
C * CHECK FOR NON-ZERO NUMBER OF ATOMS
      IF (IPR(37) > 0) THEN
C * ANALYSES OF ADP's AND OUTPUT OF CONNECTED SET
        IF (IPR(85) == 0) CALL PLA024
C * LOAD AND EXPAND COORDINATE DATA TO UNIT CELL CONTENTS
C * (EXCLUDING BRAVAIS CENTERING)
        CALL PLA023 (0)
C * TOTAL NUMBER OF OF EXPANDED ATOM SET
C * TOTAL NUMBER OF SYMMETRY OPERATIONS
        NSYM  = IPR(48)
C * GET NUMBER OF OPERATIONS EXCLUDING INVERSION AND BRAVAIS CENTERING
        NSYMH = IPR(255)
C * GET CENTER OF SYMMETRY NUMBER
        ICNTR = IPR(257)
 
C * GET REFLECTION DATA
C * IGBL(15) =  1 - fcf/FCF
C *          =  0 - hkl/HKL
C *          = -1 - no hkl or fcf reflection file association found
C * CHECK FOR TWINNING (i.e. IPR(619) = 1)
        IF (IGBL(15) >= 0 .AND. IPR(619) == 0) THEN
          PAGET = 'DiffFour'
          IF (IGBL(63) > 0) THEN
            CALL PLA262 (0)
            WRITE (LU7, 99995, IOSTAT = IOST)
          END IF
          NREF  = 0
          HMAX  = -999
          KMAX  = -999
          LMAX  = -999
C * GET NR OF REFLECTIONS (SHELX(L) HKLF4 OR FCF FORMAT
C * GET HMAX, KMAX, LMAX
C * WRITE REFLECTIONS TO LU27
          CALL PLA133 (NREF, HMAX, KMAX, LMAX)
          IF (IPR(2) == 0) THEN
C * GET SUITABLE FFT-GRID
            DO I = 1, 3
              DO J = 4, 8
                IPR(394 + I) = 2**J
                IF (PAR(100 + I) * 3.0 < IPR(394 + I)) EXIT
              END DO
            END DO
            IF (IPR(395) <= 2 * HMAX) IPR(395) = IPR(395) * 2
            IF (IPR(396) <= 2 * KMAX) IPR(396) = IPR(396) * 2
            IF (IPR(397) <= 2 * LMAX) IPR(397) = IPR(397) * 2
            M1 = IPR(395)
            M2 = IPR(396)
            M3 = IPR(397)
            IF (IGBL(63) > 0) THEN
              WRITE (LU6, 99998, IOSTAT = IOST) (IPR(I), I = 395, 397)
            END IF
C * ADAPT GRID-PARAMETERS TO NEW FFT GRID
            NGRID   = M1 * M2 * M3
            PAR(79) = PAR(98) / NGRID
C * GET/STORE REFLECTION DATA - SHELX(L) HKLF 4 FORMAT OR REFL.CIF
            CALL PLA130 (HMAX, KMAX, LMAX, NREF, IADR, NREFA, NREFB)
C * NO DIFMAP FOR SQUEEZE (TO BE CHANGED)
C * CHECK FOR ERROR RETURN
            IF (NREFB > 0) THEN
C * GET SCALING AND R- FACTOR FOR NON-FCF FILE
C * (OR REQUESTED WITH IPR(516))
              SCF = 1.0
              IF (IGBL(9) /= 1 .OR. IPR(516) /= 0) THEN
                M     = 0
                SUMFO = 0.0
                SUMFC = 0.0
                DO N = 1, NREFB
                  IF (VOID(M + 1) > 6.0 * VOID(M + 2)) THEN
                    ACAL  = VOID(M + 3)
                    BCAL  = VOID(M + 4)
                    SUMFO = SUMFO + VOID(M + 1)
                    SUMFC = SUMFC + SQRT (ACAL**2 + BCAL**2)
                  END IF
                  M = M + NP69
                END DO
                SCF = SUMFC / SUMFO
              END IF
C * GENERATE DIFFERENCE FOURIER COEFFICIENTS
              M    = 0
              NSEL = 0
              DO N = 1, NREFB
                FO   = VOID(M + 1) * SCF
                ACAL = VOID(M + 3)
                BCAL = VOID(M + 4)
                FC   = SQRT (ACAL**2 + BCAL**2)
                SIGF = MAX (VOID(M + 2) * SCF, 0.0001)
                IF (FC > 2 * IPR(515) * SIGF .AND. FC /= 0.0) THEN
                  VOID(M + 7) = FO * ACAL / FC - ACAL
                  VOID(M + 8) = FO * BCAL / FC - BCAL
                  NSEL        = NSEL + 1
                ELSE
                  VOID(M + 7) = 0.0
                  VOID(M + 8) = 0.0
                END IF
                VOID(M + 5) = 0.0
                VOID(M + 6) = 0.0
                M           = M + NP69
              END DO
              IF (IGBL(63) > 0) THEN
                WRITE (LU6, 99997, IOSTAT = IOST) SCF, NSEL,
     1            2 * IPR(515)
                CALL PLA262 (3)
                WRITE (LU7, 99997, IOSTAT = IOST) SCF, NSEL,
     1            2 * IPR(515)
              END IF
C * FFT
              IBOT = NREFA * NP69
              ITOP = IBOT + NGRID * 2
C * CHECK FOR SCRATCH OVERRUN (FFT + R3D)
              IF (ITOP + 3 * (M1 + 2) * (M2 + 2) > IADR) THEN
                IF (IGBL(63) > 0) THEN
                  WRITE (LU6, 99996, IOSTAT = IOST) 2, CHAR (IPR(223))
                  WRITE (LU7, 99996, IOSTAT = IOST) 2, CHAR (IPR(223))
                END IF
              ELSE
C * SET CUT-OFF DENSITY, TEST FOR FCF-CHECK MODE
                IF (IGBL(129) <= 0) THEN
                  PAR(269) = 0.25
                ELSE
                  PAR(269) = 0.05
                END IF
C * CALCULATE DIFFERENCE DENSITY MAP
                CALL PLA142 (-3, VOID(1), VOID(IBOT + 1),
     1                         VOID(ITOP + 1), NREFB, 0.0)
                IF (IGBL(63) > 0) THEN
                  IF (PAR(329) /= 0.0 .AND. PAR(330) /= 0.0) THEN
                    CALL PLA262 (1)
                    WRITE (LU6, 99999, IOSTAT = IOST)
     1                PAR(329), PAR(330), PAR(269)
                    WRITE (LU7, 99999, IOSTAT = IOST)
     1                PAR(329), PAR(330), PAR(269)
                  END IF
                END IF
              END IF
            END IF
          END IF
          IPR(1) = 1
        END IF
      END IF
      RETURN
99999 FORMAT ('PeaksCloseToAtoms: Rho(min) =', F10.2, ', Rho(max) =',
     3        F10.2, ', RhoCutOff =', F6.2)
99998 FORMAT (':: FFT-grid:', 11X,  3I5)
99997 FORMAT (/, ':: Fo-scale =', E14.6, /,
     1        ':: # Selected Refl.=', I6,
     2       ', with Fo > ', I2, ' * sig(Fo)', /)
99996 FORMAT (/, 'F: Scratch Array Overrun Code', I2, ' (Fatal)', /,
     1        '    Use larger program version i.e. larger NVDR', A, /)
99995 FORMAT ('Analysis of the (Final) Difference Fourier Map', /,
     1        80('='))
      END SUBROUTINE PLA360
 
      SUBROUTINE PLA361 (DMX, N1, N2, IPOSNEG)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: NS
      INTEGER :: NAT
      INTEGER :: NPK
      INTEGER :: NSYM
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: JTEST
      INTEGER :: NPKM1
      INTEGER :: IPOSNEG
      REAL :: DIST
      REAL :: DMX
      REAL :: XDENS
      CHARACTER(len=6) :: MAXMIN
      IF (N2 >= N1) THEN
C * GET NUMBER OF SYMMETRY OPERATIONS
        NSYM = IPR(48)
C * GET NUMBER OF INDEPENDENT ATOMS
        NAT  = IPR(37)
C * FIND DISTANCES BETWEEN ATOMS - ROLLETT, COMP. METH. IN CRYST. 1965
        V2(1) = DMX / (PAR(101) * SIN (PAR(105) / RGBL(6)) * PAR(121))
        V2(2) = DMX / (PAR(102) * SIN (PAR(106) / RGBL(6)) * PAR(119))
        V2(3) = DMX / (PAR(103) * SIN (PAR(104) / RGBL(6)) * PAR(120))
        IF (IPOSNEG > 0) THEN
          MAXMIN   = 'Maxima'
          REWIND (UNIT = LU2, IOSTAT = IOST)
          IF (IOST /= 0) CALL GEN148 (LU2, 1)
        ELSE
          MAXMIN   = 'Minima'
        END IF
        WRITE (LINE, 99999, IOSTAT = IOST) MAXMIN, DMX,
     1      MAX (0.10, PAR(269)) * IPOSNEG
        IF (IGBL(129) /= 0) THEN
          CALL PRINTX (LU13, LINE, 1, 0)
          WRITE (LU13, 99995)
          WRITE (LU13, 99998)
          WRITE (LU13, 99995)
        END IF
        IF (IGBL(63) > 0) THEN
          CALL PLA262 (4)
          CALL PRINTX (LU6, LINE, 0, 0)
          CALL PRINTX (LU7, LINE, 0, 0)
          WRITE (LINE, 99995)
          CALL PRINTX (LU6, LINE, 0, 0)
          CALL PRINTX (LU7, LINE, 0, 0)
          WRITE (LINE, 99998)
          CALL PRINTX (LU6, LINE, 0, 0)
          CALL PRINTX (LU7, LINE, 0, 0)
          WRITE (LINE, 99995)
          CALL PRINTX (LU6, LINE, 0, 0)
          CALL PRINTX (LU7, LINE, 0, 0)
        END IF
C * LOOP OVER ATOMS
        DO I = 1, NAT
          CALL PLA047 (LABA(I), NQ1, IDUM, JDUM, 0, IGBL(55), 0, 0)
          NPK = 0
C * LOOP OVER ADDITIONAL MAXIMA
          DO J = N1, N2
            DO N = 1, NSYM
              DO K = 1, 3
                SGY(K)     = XXO(J, K)
                SGY(K + 3) = 0.0
              END DO
              NS = N
              CALL SGSM (3, LINE, SGY, NS, LU6, IERR)
              K = 1
              GO TO 20
   10         SGY(6 + K) = SGY(6 + K) - 1.0
   20         IF ((XXO(I, K) - SGY(6 + K)) <= V2(K)) GO TO 10
              GO TO 40
   30         IF (ABS (XXO(I, K)  - SGY(6 + K)) <= V2(K)) THEN
                K = K + 1
                IF (K > 3) THEN
                  DO L = 1, 3
                    V3(L) = XXO(I, L) - SGY(6 + L)
                  END DO
                  CALL GEN002 (2, OR, V3, V4, DIST)
                  IF (DIST < DMX) THEN
                    IF (NPK == 0) THEN
                      JTEST = 0
                    ELSE
                      JTEST = IATC(NPK)
                    END IF
                    IF (J /= JTEST) THEN
                      NPK       = NPK + 1
                      DATC(NPK) = DIST
                      IATC(NPK) = J
                    ELSE
                      IF (DIST < DATC(NPK)) DATC(NPK) = DIST
                    END IF
                  END IF
                  K = K - 1
                  GO TO 40
                END IF
                GO TO 20
              END IF
   40         SGY(6 + K) = SGY(6 + K) + 1.0
              IF ((XXO(I, K)  - SGY(6 + K)) >= - V2(K)) GO TO 30
              K = K - 1
              IF (K /= 0) GO TO 40
            END DO
          END DO
          CALL GEN036 (DATC, IATC, 1, NPK)
          NPKM1 = MIN (NPK, MIN (4, 9))
          IF (NPKM1 > 0) THEN
            DO J = 1, NPKM1
              XDENS = IPOSNEG * XXO(IATC(J), 4) / PAR(98)
              WRITE (NAMS(J, 1), 99996, IOSTAT = IOST) XDENS
            END DO
            WRITE (LINE, 99997, IOSTAT = IOST)
     1        NQ1(1:11), (IATC(J) - N1 + 1, NAMS(J, 1)(1:6),
     2        DATC(J), J = 1, NPKM1)
            IF (IGBL(129) /= 0)
     1        CALL PRINTX (LU13, LINE, 0, 0)
            IF (IGBL(63) > 0) THEN
              CALL PLA262 (1)
              CALL PRINTX (LU6, LINE, 0, 0)
              CALL PRINTX (LU7, LINE, 0, 0)
            END IF
          END IF
        END DO
        IF (IGBL(63) > 0) THEN
          CALL PLA262 (1)
          WRITE (LINE, 99994)
          CALL PRINTX (LU6, LINE, 0, 0)
          CALL PRINTX (LU7, LINE, 0, 0)
        END IF
      END IF
      RETURN
99999 FORMAT ('Density ', A, ' within', F5.1, ' Angstrom from Atoms',
     1 ' (CutOff level =', F9.2, ' eA-3)')
99998 FORMAT ( 'Atom', 7X, 4(3X, '# e/A^3   Ang '))
99997 FORMAT (A, 4(I4, A, F6.2, ':'))
99996 FORMAT (F6.2)
99995 FORMAT (80('='))
99994 FORMAT (' ')
      END SUBROUTINE PLA361
 
      SUBROUTINE PLA362 (FFT)
C * ANALYSE DIFFERENCE MAP GRID DENSITY DISTRIBUTION
      USE files
      USE parameters
      IMPLICIT NONE
      INTEGER, PARAMETER :: NPOINT = 200
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: MM
      INTEGER :: LOC
      INTEGER :: NAT
      INTEGER :: IHAT
      INTEGER :: NSTATM
      INTEGER, DIMENSION(NPOINT + 1) :: NSTAT
      REAL :: D
      REAL :: V
      REAL :: RHO
      REAL :: FFTI
      REAL :: AVER
      REAL :: XMAX
      REAL :: XMIN
      REAL :: SMXI
      REAL :: SMXIK
      REAL :: SIGMA
      REAL, DIMENSION(*)  :: FFT
      CHARACTER(len=60)   :: BALK
      CHARACTER(len=NP64) :: LAB
      CALL GEN097 (NSTAT, 1, NPOINT + 1, 0)
      NAT   = IPR(37)
      V     = PAR(98)
      M1    = IPR(395)
      M2    = IPR(396)
      M3    = IPR(397)
      N     = 2 * M1 * M2 * M3
      IHAT  = 0
      XMIN  = 0.0
      XMAX  = 0.0
      SMXI  = 0.0
      SMXIK = 0.0
 
C * REPORT MIN/MAX RESIDUAL DENSITY DISTRIBUTION
      DO I = 1, N, 2
        FFTI  = FFT(I) / V
        SMXI  = SMXI  + FFTI
        SMXIK = SMXIK + FFTI**2
        IF (FFTI > XMAX) XMAX = FFTI
        IF (FFTI < XMIN) XMIN = FFTI
        M = NINT (FFTI * 20) +  NPOINT / 2 + 1
        IF (M > 0 .AND. M < NPOINT + 2) NSTAT(M) = NSTAT(M) + 1
      END DO
      AVER  = 2 * SMXI / N
      SIGMA = SQRT (2 * SMXIK / N + AVER**2)
      WRITE (LU13, 99999, IOSTAT = IOST) XMIN, XMAX
C * REPORT RESIDUAL DENSITY (+/-) ON ATOM SITES
      MM  = 0
      LOC = 0
      DO I = 1, NAT
        J = I
        CALL PLA363 (J, LAB, LOC, IHAT)
        RHO = FFT(LOC - 1) / PAR(98)
        IF (ABS (RHO) > 0.25) THEN
          MM = MM + 1
          IF (MM == 1) THEN
            WRITE (LU13, 99996)
          END IF
          WRITE (LU13, 99995) LAB, RHO
C * ALERT _977 - NEGATIVE DENSITY ON H-POSITION (Check for NoSpherA2, MOPRO)
          IF (IHAT == 1) THEN
            IF (IPR(775) == 0 .AND. IPR(725) /= 9) THEN
              CALL PLA236 (977, 2, -RHO, RHO, LAB, ' ')
            ELSE
              CALL PLA236 (977, 2, -999.0, RHO, LAB, ' ')
            END IF
          END IF
        END IF
      END DO
      IF (MM > 0) WRITE (LU13, 99994)
C * REPORT DIFFERENCE MAP DENSITY DISTRIBUTION
      WRITE (LU13, 99998, IOSTAT = IOST) AVER, SIGMA
      NSTATM = 0
      DO I = 1, NPOINT + 1
        IF (NSTAT(I) > NSTATM) NSTATM = NSTAT(I)
      END DO
      DO I = 1, NPOINT + 1
        N = I - (NPOINT / 2 + 1)
        D = N * 0.05
        K = NINT (SQRT (FLOAT (NSTAT(I))) * 60.0 /
     1      SQRT (FLOAT (NSTATM)))
        DO M = 1, 60
          IF (M > K) THEN
            BALK(M:M) = ' '
          ELSE
            BALK(M:M) = '*'
          END IF
        END DO
        IF (D > XMIN - 0.1 .AND. D < XMAX + 0.1) THEN
          WRITE (LU13, 99997, IOSTAT = IOST) D, NSTAT(I), BALK
        END IF
      END DO
      RETURN
99999 FORMAT (/, 'Section 10:', /, 80('='), /,
     1 'Analysis of Difference Map Grid Point Density - (MIN =',
     2 F6.2, ', MAX = ', F6.2, ' eA-3)', /, 80('='))
99998 FORMAT ('Frequency Plot Sqrt(Frequency) - Average =', F7.3,
     4 ', Sigma =', F7.3, ' eA-3', /, 79('='), /,
     5 31X, 'Note: F(obs) from FCF and F(calc) from CIF model')
99997 FORMAT (F6.2, I10, 1X, A)
99996 FORMAT ('Atomic sites with Residual Density Maxima/Minima',
     1 ' > 0.25 eA-3, (misplaced H''s?)', /, 80('-'))
99995 FORMAT (A, 1X, F8.2, ' eA-3')
99994 FORMAT (80('='))
      END SUBROUTINE PLA362
 
      SUBROUTINE PLA363 (I, NQQ, LOC, IHAT)
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: LOC
      INTEGER :: IHAT
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IZ
      REAL :: X
      REAL :: Y
      REAL :: Z
      CHARACTER(len=NP64) :: NQQ
      CALL GEN048 (-1, IFG(1, I), 7, IHAT)
      CALL PLA047 (LABA(I), NQQ, IDUM, JDUM, IPR(71), IGBL(55), 0,
     1  1 - IGBL(55))
      M1  = IPR(395)
      M2  = IPR(396)
      M3  = IPR(397)
      X   = MOD (10.0 + XXO(I, 1), 1.0)
      Y   = MOD (10.0 + XXO(I, 2), 1.0)
      Z   = MOD (10.0 + XXO(I, 3), 1.0)
      IX  = MOD (NINT (X * M1), M1)
      IY  = MOD (NINT (Y * M2), M2)
      IZ  = MOD (NINT (Z * M3), M3)
      LOC = 2 * ((IZ * M2 + IY) * M1 + IX + 1)
      RETURN
      END SUBROUTINE PLA363
 
      MODULE normal
