      SUBROUTINE PLA370 (MODE)
C * WILSON-PLOT & E-STATISTICS ROUTINE (MODELLED ON PROGRAM NORMAL)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE normal
      USE sgxyz
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER       :: J
      INTEGER       :: K
      INTEGER       :: L
      INTEGER       :: M
      INTEGER       :: N
      INTEGER       :: KL
      INTEGER       :: KN
      INTEGER, SAVE :: NAT
      INTEGER       :: MODE
      INTEGER       :: IYUNK
      REAL :: T
      REAL :: TT
      REAL :: FNCH
      REAL, DIMENSION(NP10, 9) :: SFC
      DOUBLE PRECISION :: FZ
 
      CHARACTER(len=1) :: ICH
      CHARACTER(len=2) :: ACH
      CHARACTER(len=9) :: NCH
      CHARACTER(len=2), DIMENSION(NP10) :: NN
C * TEST FOR FORMULA PRESENT
      IF (IAN == 0) RETURN
      IWIN = IGBL(25) * IGBL(32)
      HORS = 26.0
      VERT = 19.5
C * CREATE MERGED UNIQUE SET OF REFLECTIONS FILE
      IPR(408) = 0
      IPR(392) = 0
      IPR(393) = 1
      IPR(220) = 0
      CALL PLA145 (0)
      CALL PLA262 (0)
      WRITE (LU7, 99999)
C * SET UP INITIAL VALUES
      RHOMAX = 0.0
      NSYM   = 0
      TH     = 1.0
      EN     = 1.2
      ER     = 0.3
      MZ     = 100
      MM     = 0
      NB     = 0
      BT     = 0.0
C * LOAD/LIST SYMMETRY
      CALL PLA371
C * LOAD SFAC/UNIT CONTENT FROM CIF DATA
      IF (IABS (IGBL(8)) == 3) THEN
        ICH = RLWS(5)(1:1)
        IF (ICH == CHAR(32) .OR. ICH == CHAR(39)) RETURN
        CALL GEN020 (1, RLWS(5), 1, NP52)
        M = 0
        DO
          K   = 0
          ACH = '  '
          L   = 0
          NCH = '         '
          DO I = M + 1, NP52
            ICH = RLWS(5)(I:I)
            DO J = 65, 90
              IF (ICH == CHAR (J)) THEN
                K = K + 1
                IF (K == 1) ACH(K + 1:K + 1) = ICH
                IF (K == 2) THEN
                  ACH(1:1) = ACH(2:2)
                  ACH(2:2) = ICH
                  CALL GEN020 (-1, ACH, 2, 2)
                END IF
                EXIT
              END IF
            END DO
            IF (ICH == '.') THEN
              L = L + 1
              NCH(L:L) = ICH
            ELSE
              DO J = 48, 57
                IF (ICH == CHAR (J)) THEN
                  L = L + 1
                  NCH(L:L) = ICH
                  EXIT
                END IF
              END DO
            END IF
            IF (ICH == CHAR (32) .OR. ICH == CHAR (39)) THEN
              IF (L == 0) NCH = '1'
              READ (NCH, *) FNCH
              DO N = 1, IAN
                IF (ACH == LMT(N, 1)) THEN
                  CONT(N, 3) = FNCH
                  EXIT
                END IF
              END DO
              M = I
              EXIT
            END IF
          END DO
          IF (ICH == CHAR (39)) THEN
            EXIT
          END IF
        END DO
      END IF
      DO I = 1, IAN
        NN(I) = LMT(IENS(I), 1)
        NWX(I) = NINT (CONT(IENS(I), 3))
        K     = (IEN(IENS(I)) - 1) * 19
        DO J = 1, 9
          SFC(I, J) = SFAC(K + J)
        END DO
      END DO
      NAT = 0
      DO I = 1, IAN
        NOX(I) = INT (SFC(I, 1) + SFC(I, 3) + SFC(I, 5) + SFC(I, 7)
     1        + SFC(I, 9) + 0.5)
        IF (NOX(I) /= 1) NAT = NAT + NWX(I)
      END DO
      WRITE (LU7, 99998) (NN(I), NWX(I), NOX(I), (SFC(I, J), J = 1, 9),
     1  I = 1, IAN)
      DO I = 1, 142
        T      = 0.01 * FLOAT (I - 1)
        TT     = T * T
        GIW(I) = 0.0
        DO J = 1, IAN
          FZ = DBLE (SFC(J, 9))
          DO K = 1, 7, 2
            FZ = FZ + DBLE (SFC(J, K)) * DEXP (-DBLE (SFC(J, K + 1))
     1         * DBLE(TT))
          END DO
          GIW(I) = GIW(I) + SNGL (FZ * FZ) * FLOAT (NWX(J))
        END DO
      END DO
C * READ REFLECTION DATA FROM BINARY FILE
      CALL PLA372
      IF (NREF == 0) RETURN
C * OBTAIN SUMS FOR WILSON PLOT AND FIT LEAST SQUARES STRAIGHT LINE
      CALL PLA373
C * PLOT WILSON CURVE AND LEAST SQUARES STRAIGHT LINE
      CALL PLA374
      BT = 2.0 * BT
C * CALCULATE SCALE FACTORS FOR APPROPRIATE REFLECTION GROUPS
      CALL PLA375
      CALL PLA376
      WRITE (GRAPH(5)(20:32), '(A, '' - '')') JID(1:10)
      WRITE (GRAPH(7)(20:30 + KNMFIL + KXT + 1), '(''FormData = '', A)')
     1  FNLU1(1 : KNMFIL + KXT + 1)
      WRITE (GRAPH(9)(20:30 + KNM16), '(''ReflData = '', A)')
     1  FNLU16(1 : KNM16)
      IF (IABS (IGBL(8)) == 3) THEN
        IYUNK = INDEX (RLWS(5)(1:65), CHAR (39)) - 1
        WRITE (GRAPH(11)(20:30 + IYUNK), '(''Content  = '', A)')
     1    RLWS(5)(1:IYUNK)
      END IF
      IF (MODE == 0)
     1  WRITE (GRAPH(13)(20:37), '(''SpaceGroup '',    A)') ZSPG
      WRITE (GRAPH(15)(20:37), '(''ThetaMax = '', F7.3)') THM
      WRITE (GRAPH(17)(20:37), '(''Nr Refln = '',   I7)') NREF
      WRITE (GRAPH(19)(20:38), '(''Temp     = '',   I7,''K'')')
     1  MAX (IPR(261), 0)
      WRITE (GRAPH(21)(20:37), '(''Wilson U = '', F7.3)') UT
      IF (MODE /= 0) THEN
        WRITE (GRAPH(40)(85:), '(''Space Group  Determination Steps'')')
        WRITE (GRAPH(41)(85:), '(''==============================='')')
        WRITE (GRAPH(42)(85:), '(''1 - (A)Centric Tests (Optional)'')')
        WRITE (GRAPH(43)(85:), '(''2 - Check Resolution/Decay'')')
        WRITE (GRAPH(44)(85:), '(''3 - Get Bravais Lattice Type'')')
        WRITE (GRAPH(45)(85:), '(''4 - Select Laue Group'')')
        WRITE (GRAPH(46)(85:), '(''5 - Inspect Systematic Ext.Refln'')')
        WRITE (GRAPH(47)(85:), '(''6 - Select Space Group from Set'')')
      END IF
      IGBL(6) = 35
   10 CALL GGIP (HORS, VERT, 0.0, 1)
      VRT = VERT - 0.5
      DO I = 1, 55
        VRT = VRT - 0.34
        CALL PLA439 (0.0, GRAPH(I), 120, 0.25, 1, 1, 0.0, VRT)
      END DO
      CALL GGIP (0.0, 0.0, 0.0, 6)
      DO
C * WHAT NEXT ?
        CALL PLA012 (2, 1)
        CALL GEN072 (IGGT, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
        IF (IGGT(1:1) == '!') EXIT
        SELECT CASE (IFL(1)(1:6))
          CASE ('END   ', 'EXIT  ')
            EXIT
          CASE ('PLOT')
            GO TO 10
          CASE ('NZSTAT')
            CALL PLA379 (1)
          CASE ('NZPLOT')
            CALL PLA379 (2)
          CASE DEFAULT
            IGBL(1) = 4
        END SELECT
      END DO
      RETURN
99999 FORMAT ('Wilson Plot and E-Value Statistics Modelled on the ',
     1 'NORMAL Program Code of the Multan80 Package', /, 120('='), /)
99998 FORMAT(//, 51X, 'UNIT CELL CONTENTS', //,
     1 'ATOM',2X, 'NUMBER IN CELL', 2X, 'ATOMIC NUMBER', 2X,
     2 'SCATTERING FACTOR CONSTANTS', 5X,
     3 '(F = A*EXP(-B*RHO)+C*EXP(-D*RHO)+E*EXP(-F*RHO)+G*EXP(-H*RHO)+K)'
     4 , /, (1X, A, I12, I12, 6X, 9F11.5))
      END SUBROUTINE PLA370
 
      SUBROUTINE PLA371
 
      USE files
      USE parameters
      USE spgrdata
      USE normal
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: IC
      INTEGER :: INZ
      INTEGER :: ISN
      INTEGER :: IIMX
      REAL :: TRV
      CHARACTER(len=80) :: ICLL
      CHARACTER(len=1),  DIMENSION(14) :: KX
      CHARACTER(len=3),  DIMENSION(2)  :: ICAP
      KX = (/'1','2','3','4','5','6','X','Y','Z',' ',',','+','-','/'/)
      ICAP = (/'NON','   '/)
C * DETERMINE LATTICE MULTIPLICITY (PTS) AND CRYSTAL SYSTEM (KSYS)
      LATT  = IPR(241)
      ICENT = IPR(257) - 1
      NSYM  = 0
      IIMX  = IPR(255)
      WRITE (LU7, 99999) ICAP(ICENT + 1), IIMX, LAT(LATT)
      DO L = 1, IIMX
        CALL SGSM (2, ICLL, SGX, L, 0, IERR)
        WRITE (LU7, 99998) ICLL
        NSYM = NSYM + 1
        IC   = 1
        ISN  = 1
        TRV  = -1.0
        INZ  = 1
        DO I = 1, 80
          DO J = 1, 14
            IF (ICLL(I:I) == KX(J)) EXIT
          END DO
C * CHECK FOR ','
          IF (J == 11) THEN
            IF (INZ == 2) IS(2, IC, NSYM) = 0
            IF (TRV < 0.0) TS(IC, NSYM) = 0.0
            INZ = 1
            TRV = -1.0
            IC  = IC + 1
C * CHECK FOR '-'
          ELSE IF (J == 13) THEN
            ISN = -1
C * CHECK FOR 'X', 'Y' OR 'Z'
          ELSE IF (J >= 7 .AND. J <= 9) THEN
            IS(INZ, IC, NSYM) = ISN * (J - 6)
            ISN = 1
            INZ = INZ + 1
C * CHECK FOR '1' TO '6'
          ELSE IF (J < 7) THEN
            IF (TRV < 0.0) TRV = FLOAT (J)
            IF (TRV > 0.0) TS(IC, NSYM) = TRV / FLOAT (J)
          END IF
        END DO
      END DO
C * DETERMINE LATTICE MULTIPLICITY
C * PRIMITIVE
      PTS = 1.0
      IF (LATT /= 7) THEN
C * A, B, C OR I CENTRED
        IF (LATT /= 1) PTS = 2.0
C * F CENTRED
        IF (LATT == 5) PTS = 4.0
      ELSE
C * CENTRED HEXAGONAL
        PTS = 3.0
        DO I = 1, NSYM
C * PRIMITIVE RHOMBOHEDRAL  (PTS=1.0)
          IF (IABS(IS(1, 1, I)) == 3) THEN
            PTS = 1.0
            EXIT
          END IF
        END DO
      END IF
C * DETERMINE CRYSTAL SYSTEM
      DO I = 1, 2
        DO J = 1, NSYM
          DO INZ = 1, 2
            IF (IABS (IS(INZ, 1, J)) == 4 - I) THEN
              IF (I /= 1) THEN
C * TETRAGONAL
                KSYS = 4
                IF (NSYM /= 4 .AND. NSYM /= 8) THEN
C * TRIGONAL OR RHOMBOHEDRAL INDEXED ON HEXAGONAL AXES
                  KSYS = 5
C * TEST FOR 6-FOLD AXIS - GENERAL FORM -X, -Y, Z + T
                  DO K = 2, NSYM
                    IF (IABS (IS(1, 1, K)) > 1  .OR. IABS (IS(2, 1, K))
     1                 > 1) CYCLE
                    IF (IABS (IS(1, 2, K)) == 1 .OR. IABS (IS(2, 2, K))
     1                 == 1) CYCLE
C * HEXAGONAL
                    KSYS = 6
                  END DO
                END IF
              ELSE
C * CUBIC
                KSYS = 8
C * PRIMITIVE RHOMBOHEDRAL
                IF (LATT == 7) KSYS = 7
                IF (KSYS == 7) LATT = 1
              END IF
              RETURN
            END IF
          END DO
        END DO
      END DO
C * 1 - TRICLINIC, 2 - MONOCLINIC, 3 - ORTHORHOMBIC
      KSYS = MIN0(NSYM, 3)
      RETURN
99999 FORMAT (/, 'THE STRUCTURE IS ', A3, 'CENTROSYMMETRIC', 8X, I3, 3X,
     1 'GENERAL EQUIVALENT POSITIONS', 10X, 'LATTICE IS OF TYPE',
     2  3X, A1, /)
99998 FORMAT (30X, A)
      END SUBROUTINE PLA371
 
      SUBROUTINE PLA372
      USE files
      USE parameters
      USE atomdata
      USE normal
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: ID
      INTEGER :: IG
      INTEGER :: K1
      INTEGER :: K2
      INTEGER :: KG
      INTEGER :: JG
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: LG
      INTEGER :: IK1
      INTEGER :: MLT
      REAL :: AF
      REAL :: BF
      REAL :: FF
      REAL :: FK
      REAL :: FO
      REAL :: EW
      REAL :: EPS
      REAL :: RHO
      REAL :: SIG
      REAL :: SFK
      REAL :: FRAC
      REAL :: SINTH
      REAL :: FORMX
      REAL :: GEN095
      CHARACTER(len=80) :: LINE
C * SCRATCH FILE
      OPEN (LU65, STATUS = 'SCRATCH', FORM = 'UNFORMATTED')
      REWIND (UNIT = LU17, IOSTAT = IOST)
      REWIND (UNIT = LU65, IOSTAT = IOST)
      DO
        READ (LU17, 99999, IOSTAT = IOST) IH, IK, IL, FK, SFK
        IF (IOST /= 0 .OR.
     1    IH == 0 .AND. IK == 0 .AND. IL == 0) THEN
          FO = -1.0
        ELSE
          IF (FK > 0.0) THEN
            FO  = SQRT (FK)
            SIG = SFK / (2.0 * FO)
          ELSE
            FO  = 0.0
            SIG = 0.0
          END IF
        END IF
C * CALCULATE RHO, EPSILON, MULTIPLICITY AND SCATTERING FACTOR
C * FOR EACH REFLECTION AND CREATE THE SCRATCH TAPE (LU65)
        IF (FO >= 0.0) THEN
          NREF   = NREF + 1
          RHO    = GEN095 (PAR(191), IH, IK, IL)
          RHOMAX = AMAX1 (RHOMAX, RHO)
C * COMPUTE EPSILON AND MULTIPLICITY BY GENERATING EQUIVALENT REFLECTIONS
C * EPSILON = NUMBER OF TIMES SAME REFLECTION APPEARS IN LIST
C * MULTIPLICITY = NUMBER DIFFERENT REFLECTIONS IN LIST
          EPS = 1.0
          MLT = 1
C * IN TRICLINIC SPACE GROUPS EPS = 1.0 AND MLT = 1
          IF (NSYM > 1) THEN
            SGX(1) = IH
            SGX(2) = IK
            SGX(3) = IL
            SGX(4) = 0.0
            K1      = 65536 * IH + 256 * (IK + 128) + IL + 128
            IK1     = 65792 - K1
            DO J = 2 ,NSYM
              CALL SGSM (5, LINE, SGX, J, LU6, IERR)
              K2 = 65536 * NINT (SGX(7)) + 256 * (NINT (SGX(8)) + 128)
     1           + NINT (SGX(9)) + 128
              IF (K2 == K1) EPS = EPS + 1.0
              IF (ICENT /= 0 .AND. K2 == IK1) EPS = EPS + 1.0
              IF (K2 == K1 .OR. K2 == IK1) MLT = MLT + 1
            END DO
          END IF
          FF = FO * FO / PTS
          ID = NSYM / MLT
C * DETERMINE INDEX GROUP (FOR RESCALING)
          IF (KSYS < 7) THEN
            LG = MOD (IABS (IL), 2)
            IF (KSYS < 5) THEN
              KG = MOD (IABS (IK), 2)
              JG = MOD (IABS (IH), 2)
C * TRICLINIC, MONCLINIC AND ORTHORHOMBIC
              IF (KSYS <= 3) IG = JG + 2 * KG + 4 * LG
C * TETRAGONAL
              IF (KSYS == 4) IG = JG + KG + 3 * LG
            ELSE
C * TRIGONAL, HEXAGONAL AND RHOMBOHEDRAL INDEXED ON HEXAGONAL AXES
              IG = 3 * LG
              IF (MOD (IH, 3) == 0) IG = IG + 1
              IF (MOD (IK, 3) == 0 .OR. MOD (IH + IK, 3) == 0)
     1          IG = IG + 1
            END IF
          ELSE
C * CUBIC AND PRIMITIVE RHOMBOHEDRAL
            IG = 3 * MOD (IABS (IH + IK + IL), 2)
            IF (MOD (IH - IL, 3) == 0) IG = IG + 1
            IF (MOD (IK - IL, 3) == 0 .OR. MOD (IH - IK, 3) == 0)
     1        IG = IG + 1
          END IF
C * PACK SYMMETRY FUNCTIONS FOR LATER USE
          ID = 10000 * ID + 100 * INT (EPS + 0.5) + IG + 1
C * LOOK UP SCATTERING FACTOR TABLES GENERATED BY ATREC
          SINTH = 100.0 * SQRT (RHO)
          I     = MAX0 (2, INT (SINTH + 1.5))
          FRAC  = SINTH - FLOAT (I - 1)
          BF    = 0.5 * (GIW(I + 1) - GIW(I - 1))
          AF    = BF + GIW(I - 1) - GIW(I)
          FORMX = AF * FRAC * FRAC + BF * FRAC + GIW(I)
C * 'WILSON' STRUCTURE FACTOR
          EW    = FF / (FORMX * EPS)
        END IF
C * CREATE SCRATCH TAPE
        WRITE (LU65) IH, IK, IL, FO, ID, EW, RHO, SIG
        IF  (FO < 0) EXIT
      END DO
      THM = ASIN (SQRT (RHOMAX) * PAR(17)) * RGBL(6)
      RETURN
99999 FORMAT (3I4, 2F8.0)
      END SUBROUTINE PLA372
 
      SUBROUTINE PLA373
C * LEAST SQUARES PLOT, INCLUDING SUMMATION OVER NB RANGES OF RHO
      USE files
      USE normal
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: ID
      INTEGER :: IE
      INTEGER :: MLT
      INTEGER :: KYUNK
      INTEGER :: NUMBERX
      INTEGER, DIMENSION(30) :: NSUM
      REAL :: T
      REAL :: Q
      REAL :: R
      REAL :: S
      REAL :: EW
      REAL :: FO
      REAL :: PI
      REAL :: PP
      REAL :: RR
      REAL :: WT
      REAL :: ED
      REAL :: ADD
      REAL :: AVI
      REAL :: EPS
      REAL :: DIV
      REAL :: RHO
      REAL :: ENDX
      REAL :: TMULX
      REAL :: START
      REAL :: ESQAV
      REAL, DIMENSION(30) :: SW
      REAL, DIMENSION(30) :: SD
      REAL, DIMENSION(30) :: SR
      REAL, DIMENSION(30) :: SI
      NB = INT (8.0 * ALOG10 (0.05 * FLOAT (MAX0 (NREF, 100)) + 0.5))
C * MAXIMUM OF 30 POINTS ON WILSON PLOT
      IF (NB > 30) NB = 30
      WRITE (LU7, 99995) NREF, RHOMAX, NB
      WRITE (LU7, 99999)
C * SET INITIAL VALUES
      PI      = 4.0 * ATAN (1.0)
      PP      = 0.0
      Q       = 0.0
      R       = 0.0
      S       = 0.0
      T       = 0.0
      NUMBERX = 0
      ADD     = RHOMAX / FLOAT (NB)
      START   = - ADD
      ENDX    = ADD
      RR      = FLOAT (NB) / RHOMAX
      DO I = 1, 30
        SW(I)   = 0.0
        SD(I)   = 0.0
        SR(I)   = 0.0
        SI(I)   = 0.0
        NSUM(I) = 0
      END DO
      REWIND (UNIT = LU65, IOSTAT = IOST)
C * READ SCRATCH TAPE
      DO
        READ (LU65) KYUNK, KYUNK, KYUNK, FO, ID, EW, RHO
        ED = EW
C * TAPE ENDS WITH FO < 0.0
        IF (FO < 0.0) THEN
          KYUNK = 0
          EXIT
        END IF
C * N STORES RANGE OF RHO
        N     = MIN0 (INT (1.0 + RR * RHO), NB)
        MLT   = ID / 10000
        IE    = (ID - 10000 * MLT) / 100
        EPS   = FLOAT (IE)
        TMULX = FLOAT (MLT)
C * WEIGHTED SUMS
C * NUMBER OF REFLECTIONS
        NSUM(N) = NSUM(N) + MLT
C * WILSON
        SW(N) = SW(N) + EW * TMULX
C * DEBYE
        SD(N) = SD(N) + ED * TMULX
C * RHO
        SR(N) = SR(N) + RHO * TMULX
C * INTENSITY
        SI(N) = SI(N) + TMULX * FO * FO / (EPS*PTS)
      END DO
      IF (KYUNK == 0) THEN
        DO I = 1, NB
C * SMOOTH CURVE BY ADDING ADJACENT RANGES
          NUMBERX = NUMBERX + NSUM(I)
          NSUM(I) = NSUM(I) + NSUM(I + 1)
          SW(I)   = SW(I)   + SW(I + 1)
          SD(I)   = SD(I)   + SD(I + 1)
          SR(I)   = SR(I)   + SR(I + 1)
          SI(I)   = SI(I)   + SI(I + 1)
C * CALCULATE WEIGHTED AVERAGES AND LOGS
          WT      = FLOAT (NSUM(I))
          DIV     = 1.0 / AMAX1 (1.0, WT)
          ESQAV   = SD(I) * DIV
          FLGD(I) = ALOG (ESQAV)
          AVI     = SI(I) * DIV
          AVR(I)  = SR(I) * DIV
          FLGW(I) = ALOG (SW(I) * DIV)
          START   = START + ADD
          ENDX    = AMIN1 (ENDX + ADD, RHOMAX)
          WRITE (LU7, 99998) I, START, ENDX, NSUM(I), AVR(I), AVI,
     1      ESQAV, FLGW(I)
C * COEFFICIENTS OF NORMAL EQUATIONS
          PP = PP + WT * AVR(I) * AVR(I)
          Q  = Q  + WT * AVR(I)
          R  = R  + WT * AVR(I) * FLGD(I)
          S  = S  + WT * FLGD(I)
          T  = T  + WT
        END DO
      END IF
      WRITE (LU7, 99997) PP, Q, R, Q, T, S
C * LEAST SQUARES
      DIV   =  PP * T - Q * Q
      SLOPE = (R  * T - Q * S) / DIV
      FLGK  = (PP * S - Q * R) / DIV
      SC    = EXP (-FLGK)
      BT    = -0.5 * SLOPE
      UT    = BT / (8 * PI**2)
      WRITE (LU6, 99994) UT
      WRITE (LU7, 99996) SLOPE, FLGK, BT, UT, SC
      RETURN
99999 FORMAT (//, 20X, 'LEAST SQUARES PLOT', //, 'RANGE', 6X,
     1 'RHO=(SINTH/LAM)**2', 6X, 'NUMBER', 6X, 'MEAN RHO', 7X,
     2 'MEAN I', 7X, 'MEAN EXP(-2*B*RHO)*E**2', 7X, 'WILSON')
99998 FORMAT (I3, F15.4, '  -', F8.4, I11, F14.4, F14.1, F23.4,
     1 7X, F13.4)
99997 FORMAT (/, 'NORMAL EQUATIONS', /, (E11.3, ' * SLOPE +', E11.3,
     1 ' * INTERCEPT =', E11.3))
99996 FORMAT (/, 'SLOPE =', F8.4, 4X, 'INTERCEPT =', F8.4, 4X,
     1 'TEMPERATURE FACTOR (B) =', F8.4, 4X, 'U =', F8.4, 4X, 'SCALE =',
     2 F8.4, /, 51X, 'F(ABSOLUTE)**2 = SCALE*F(OBSERVED)**2')
99995 FORMAT (//, 'NUMBER OF REFLECTIONS =', I6, 8X,
     1 'MAXIMUM (SIN(THETA)/LAMBDA)**2 =', F7.4, 8X,
     2 'NUMBER OF POINTS ON WILSON PLOT =', I3)
99994 FORMAT (/, ':: Wilson U = ', F10.4, //)
      END SUBROUTINE PLA373
 
      SUBROUTINE PLA374
      USE files
      USE cchar
      USE normal
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: JP
      INTEGER :: IL
      INTEGER :: IR
      INTEGER :: ITEMP
      REAL :: Q
      REAL :: SK
      REAL :: FD
      REAL :: FN
      REAL :: FX
      REAL :: RX
      REAL, DIMENSION(4) :: R
      REAL, DIMENSION(6) :: FH
      REAL, DIMENSION(6) :: RH
      REAL, DIMENSION(4) :: AW
C * LINE PRINTER PLOT AT 50 VALUES OF RHO
C * DETERMINE RANGES OF LOGS
      RX = AVR(NB)
      FX = FLGK
      FN = SLOPE * RX + FLGK
      DO I = 1, NB
        FX = AMAX1 (FX, FLGW(I), FLGD(I))
        FN = AMIN1 (FN, FLGW(I), FLGD(I))
      END DO
      FD = FX - FN
      DO I = 1, 6
        RH(I) = 0.2 * FLOAT (I - 1) * RX
        FH(I) = FN + 0.2 * FLOAT (I - 1) * FD
      END DO
C * TOP FRAME
      WRITE (LU7, 99993)
      WRITE (GRAPH(1), 99999)
      WRITE (GRAPH(2), 99998) FH
      WRITE (GRAPH(3), 99997) RH(1)
      J  = 1
      IR = 2
      DO I = 1, 50
        DCV(I) = -1000000.0
C * SIDE FRAME
        IF (MOD (I, 10) /= 0) THEN
          WRITE (GRAPH(I + 3), 99996)
        ELSE
          WRITE (GRAPH(I + 3), 99995) RH(IR)
          IR = IR + 1
        END IF
C * INTERPOLATION
        Q = 0.02 * FLOAT (I) * RX
        IL = INT ((SLOPE * Q + FLGK - FN) * 100.0 / FD + 16.5)
        IF (IL > 117) IL = 117
        IF (IL < 1)   IL = 1
C * STRAIGHT LINE OUTPUT (*)
        GRAPH(I + 3)(IL:IL) = '*'
        IF (Q >= AVR(1)) THEN
          IF (J == 1 .OR.
     1        J /= 1 .AND. J /= NB - 2 .AND. Q >= AVR(J + 1)) THEN
            J = J + 1
            DO K = 1, 4
              ITEMP = J - 2 + K
              R(K)  = AVR(ITEMP)
            END DO
            CALL GEN153 (R, FLGW(J - 1), FLGW(J), FLGW(J + 1),
     1        FLGW(J + 2), AW)
          END IF
C * WILSON PLOT INTERPOLATION
          IL =
     1      INT (100.0 * (AW(4) + Q * (AW(3) + Q * (AW(2) + Q * AW(1)))
     2      - FN) / FD + 16.5)
          IF (IL > 117) IL = 117
          IF (IL < 1)   IL = 1
C * WILSON PLOT OUTPUT (W)
          GRAPH(I + 3)(IL:IL) = 'W'
C * STORE K-CURVE
          DCV(I) = EXP (AW(4) + Q * (AW(3) + Q * (AW(2) + Q * AW(1))))
        END IF
        IF (I == 2)   GRAPH(I + 3)(40:91) =
     1    'PLOT OF WILSON CURVE AND LEAST SQUARES STRAIGHT LINE'
        IF (I == 25) GRAPH(I + 3)(1:14) = '(sin(TH)/L)**2'
      END DO
      WRITE (LU7, 99994) (GRAPH(I), I = 1, 53)
C * K-CURVE PARAMETERS
      DEL = 50.0 / AVR(NB)
      J   = 0
      JP  = 0
      DO I = 1, 50
        SK = EXP (SLOPE * FLOAT (I) / DEL + FLGK)
        IF (DCV(I) >= (-999999.0)) THEN
          JP = -1
          IF (DCV(I) > SK) JP = 1
          IF (J == (-JP)) EXIT
          J = JP
        END IF
        DCV(I) = SK
      END DO
      RETURN
99999 FORMAT (50X, 'LN(F(OBS)**2/SIGFSQ)')
99998 FORMAT (F18.3, 5F20.3)
99997 FORMAT (F12.3, 2X, '-', 5('I', 19('-')), 'I-')
99996 FORMAT (15X, 'I')
99995 FORMAT (F11.3, 3X, '-I-')
99994 FORMAT (A)
99993 FORMAT(/, 26X, 'PLOT OF WILSON CURVE AND LEAST SQUARES',
     1 ' STRAIGHT LINE', //)
      END SUBROUTINE PLA374
 
      SUBROUTINE PLA375
C * INDEX GROUP RESCALING
      USE files
      USE normal
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: ID
      INTEGER :: IG
      INTEGER :: NN
      INTEGER :: NW
      INTEGER :: MLT
      INTEGER :: KYUNK
      INTEGER, DIMENSION(8) :: NG
      REAL :: ED
      REAL :: EW
      REAL :: FO
      REAL :: RHO
      REAL :: ESQ
      REAL :: TOT
      REAL :: TMULX
      REAL, DIMENSION(8) :: SCS
      TOT = 0.0
      NW  = 0
      DO I = 1, 8
        SCS(I) = 0.0
        NG(I)  = 0
      END DO
      REWIND (UNIT = LU65, IOSTAT = IOST)
      DO
        READ (LU65) KYUNK, KYUNK, KYUNK, FO, ID, EW, RHO
        ED = EW
        IF (FO < 0.0) THEN
          KYUNK = 0
          EXIT
        END IF
        CALL PLA377 (ESQ, RHO, ED)
C * UNPACK SYMMETRY FUNCTIONS
        MLT     = ID / 10000
        TMULX   = FLOAT(MLT)
        TOT     = TOT + ESQ * TMULX
        NW      = NW  + MLT
        IG      = MOD(ID, 100)
        SCS(IG) = SCS(IG) + ESQ * TMULX
        NG(IG)  = NG(IG)  + MLT
      END DO
      IF (KYUNK == 0) TOT = TOT / FLOAT(NW)
C * 8 PARITY GROUPS FOR TRICLINIC, MONOCLINIC AND ORTHORHOMBIC
      NN = 8
C * 6 MODIFIED PARITY GROUPS FOR TETRAGONAL
C * 6 INDEX GROUPS IN OTHER SYSTEMS
      IF (KSYS >= 4) NN = 6
      DO I = 1, NN
        IF (NG(I) > 0) SCS(I) = SCS(I) / FLOAT (NG(I))
      END DO
      WRITE (LU7, 99999)
      IF (KSYS <= 3) WRITE (LU7, 99998)
      IF (KSYS == 4) WRITE (LU7, 99997)
      IF (KSYS > 4) THEN
        WRITE (LU7, 99996)
        IF (KSYS <= 6) WRITE (LU7, 99995)
        IF (KSYS >= 7) WRITE (LU7, 99994)
        WRITE (LU7, 99993)
      END IF
      WRITE (LU7, 99992) TOT, (SCS(I), I = 1, NN)
      WRITE (LU7, 99991) NW,  (NG(I),  I = 1, NN)
      TOT = 1.0 / TOT
      DO I = 1, NN
        IF (NG(I) > 0 .AND. ABS(SCS(I)) > 0.0001) SCAL(I) = 1.0 / SCS(I)
      END DO
      RETURN
99999 FORMAT (/, 27X, 'AVERAGE E**2 ACCORDING TO APPROPRIATE INDEX ',
     1 'GROUP BEFORE RESCALING')
99998 FORMAT (53X, 'PARITY GROUPS', /, 18X, 'ALL', 9X, 'EEE', 9X,
     1 'OEE', 9X, 'EOE', 9X, 'OOE', 9X, 'EEO', 9X, 'OEO', 9X, 'EOO',
     2 9X, 'OOO')
99997 FORMAT (49X,'MODIFIED PARITY GROUPS', /, 18X, 'ALL', 9X, 'EEE',
     1 7X, 'EOE', 'OEE', 7X, 'OOE', 9X, 'EEO', 7X, 'EOO', 'OEO', 7X,
     2 'OOO')
99996 FORMAT ('INDEX GROUPS DIVIDED ON -')
99995 FORMAT ('+', 30X, '1) MOD(H,3)', 4X, '2) MOD(K,3)', 4X,
     1 '3) MOD(H+K,3)',4X, '4) MOD(L,2)')
99994 FORMAT ('+', 30X, '1) MOD(H-L,3)', 4X, '2) MOD(K-L,3)', 4X,
     1 '3) MOD(H-K,3)', 4X, '4) MOD(H+K+L,2)')
99993 FORMAT (30X, 'E - ZERO REMAINDER', 4X, 'O - NON-ZERO REMAINDER',/,
     1 '0', 18X, 'ALL', 9X, 'OOOE', 5X, 'OOEE,OEOE', 6X, 'EEEE', 8X,
     2 'OOOO', 5X, 'OOEO,OEOO', 6X, 'EEEO', /, ' ', 42X, 'EOOE', 32X,
     3 'EOOO')
99992 FORMAT (2X, 'E**2', 3X, 9F12.3)
99991 FORMAT (1X, 'NUMBER', 2X, 9I12)
      END SUBROUTINE PLA375
 
      SUBROUTINE PLA376
C * WILSON PLOT - PART 7
      USE files
      USE parameters
      USE cchar
      USE normal
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: ID
      INTEGER :: IE
      INTEGER :: IG
      INTEGER :: LH
      INTEGER :: LK
      INTEGER :: LL
      INTEGER :: NC
      INTEGER :: NL
      INTEGER :: NS
      INTEGER :: LIM
      INTEGER :: NRW
      INTEGER :: NET
      INTEGER :: INP
      INTEGER, DIMENSION(1000) :: IX
      INTEGER, DIMENSION(25)   :: NU
      INTEGER, DIMENSION(10)   :: NHR
      REAL :: E
      REAL :: T
      REAL :: ED
      REAL :: ZZ
      REAL :: XX
      REAL :: EW
      REAL :: FO
      REAL :: RRX
      REAL :: SIG
      REAL :: SCF
      REAL :: RHO
      REAL :: ESQ
      REAL, DIMENSION(1000) :: EX
      REAL, DIMENSION(1000) :: FX
      REAL, DIMENSION(10)   :: RHR
      REAL, DIMENSION(10)   :: STL
      REAL, DIMENSION(10)   :: AVA
      REAL, DIMENSION(10)   :: AVC
      REAL, DIMENSION(10)   :: AVH
      CHARACTER(len=1)   :: NOB
      CHARACTER(len=1)   :: IOBS
      CHARACTER(len=1)   :: IUNOBS
      CHARACTER(len=120) :: RECORD
C * TABLES OF THEORETICAL DISTRIBUTIONS
      ZT(1:25, 9) = (/
     1 0.368, 0.463, 0.526, 0.574, 0.612, 0.643, 0.670, 0.694, 0.715,
     2 0.733, 0.765, 0.791, 0.813, 0.832, 0.848, 0.863, 0.875, 0.886,
     3 0.896, 0.905, 0.913, 0.920, 0.926, 0.932, 0.938/)
      AVA = (/0.886, 1.0, 1.329, 2.0, 3.323, 6.0, 0.736, 1.0, 2.0,
     1        2.415/)
      AVC = (/0.798, 1.0, 1.596, 3.0, 6.383, 15.0, 0.968, 2.0, 8.0,
     1        8.691/)
      AVH = (/0.718, 1.0, 1.916, 4.5, 12.26, 37.5, 1.145, 3.5, 26.0,
     1        26.903/)
      IOBS   = ' '
      IUNOBS = 'U'
C * CALCULATE FINAL E-VALUES AND RESCALED F'S
C * CREATE NEW LU65 IF REQUIRED
C * PREPARE TABLES OF STATISTICS
C * SET INITIAL VALUES
      CALL GEN097 (NST, 1,  5, 0)
      CALL GEN097 (NU,  1, 25, 0)
      CALL GEN097 (NHR, 1, 10, 0)
      DO I = 1, 10
        RHR(I) = 0.0
        DO J = 1, 5
          VST(I, J) = 0.0
        END DO
      END DO
      DO I = 1, 8
        DO J = 1, 25
          ZT(J, I) = 0.0
        END DO
      END DO
      NRW = 0
      LIM = 1000
      NC  = 0
      NS  = 0
      NL  = 0
      SCF = SQRT (SC)
      RRX = 10.0 / SQRT (RHOMAX)
      REWIND (UNIT = LU65, IOSTAT = IOST)
      DO
        READ (LU65) LH, LK, LL, FO, ID, EW, RHO, SIG
        ED  = EW
        INP = 32896
C * TEST FOR END OF DATA
        IF (FO < 0.0) EXIT
C * SPECIAL TEST OPTION  (GENERALLY, ALL REFLECTION SHOULD BE INCLUDED)
        IF (FO < PAR(550) * SIG) CYCLE
        MULT =  ID / 10000
        IE   = (ID - 10000 * MULT) / 100
        IG   =  ID - 10000 * MULT - 100 * IE
C * CALCULATE E
        CALL PLA377 (ESQ, RHO, ED)
        ESQ = ESQ * SCAL(IG)
        E   = SQRT (ESQ)
        ED  = E
C * CALCULATE RESCALED F
        FO = FO * SCF
C * PACK INDICES FOR TAPE LU65
        INP = 65536 * LH + 256 * (LK + 128) + LL + 128
C * SET OBS/UNOBS FLAG
        NOB = IOBS
        IF (SIG < 0.0) NOB = IUNOBS
C * (DUMMY)
        NOB = ' '
        IF (NOB == ' ') GO TO 20
        IF (RHO > TH) GO TO 20
C * STORE REFLECTIONS FOR MULTAN
        IF (SIG >= 0.0) THEN
          NL = NL + 1
          IF (E > EN) GO TO 10
          NL = NL - 1
        END IF
        E  = E + 0.2 * RHO
        IF (E > ER) GO TO 20
        NS     = NS + 1
   10   NC     = NC + 1
        IX(NC) = INP
        EX(NC) = E
        FX(NC) = FO
        IF (NC == LIM) THEN
C * SORT
          CALL GEN154 (EX, FX, IX, 1000)
          IF (MZ > 0) ER = AMIN1 (ER, EX(1001 - MZ))
          EN  = AMAX1 (EN, EX(MM))
          NC  = MIN0 (MM, NL)
          LIM = 1000 - MZ
        END IF
C * WORK OUT FINAL STATISTICS
 
   20   TMUL = FLOAT(MULT)
C * DISTRIBUTION OF E WITH SIN(THETA)/LAMBDA
        N      = MIN0 (10, INT (1.0 + RRX * SQRT (RHO)))
        NHR(N) = NHR(N) + MULT
        RHR(N) = RHR(N) + ESQ * TMUL
        NZR    = INT (10.0 * ESQ) + 1
        IF (NZR > 10) NZR = 10 + (NZR - 9) / 2
        EE(1) = ED
        DO J = 2, 6
          EE(J) = EE(J - 1) * ED
        END DO
        EE(7)  = ESQ - 1.0
        EE(8)  = EE(7) * EE(7)
        EE(9)  = EE(8) * EE(7)
        EE(10) = ABS (EE(9))
        EE(7)  = ABS (EE(7))
        DO J = 1, 10
          EE(J) = TMUL * EE(J)
        END DO
C * ADD FUNCTIONS OF E TO APPROPRIATE ZONES
        IND = 1
        J   = LH
        K   = LK
        L   = LL
        CALL PLA378 (1)
C * TRICLINIC, MONOCLINIC AND ORTHORHOMBIC
        IF (KSYS <= 3) THEN
          IF (J == 0) CALL PLA378 (3)
          IF (K == 0) CALL PLA378 (4)
          IF (L == 0) CALL PLA378 (5)
C * TETRAGONAL
        ELSE IF (KSYS == 4) THEN
          IF (J == 0 .OR. K == 0) CALL PLA378 (3)
          IF (IABS (J) == IABS (K)) CALL PLA378 (4)
          IF (L == 0) CALL PLA378 (5)
C * TRIGONAL, HEXAGONAL AND RHOMBOHEDRAL INDEXED ON HEXAGONAL AXES
        ELSE IF (KSYS == 5 .OR. KSYS == 6) THEN
          IF (J == 0 .OR. K == 0 .OR. J + K == 0)
     1      CALL PLA378 (3)
          IF (J == K .OR. J + 2 * K == 0 .OR. 2 * J + K == 0)
     1      CALL PLA378 (4)
          IF (L == 0) CALL PLA378 (5)
C * PRIMITIVE RHOMBOHEDRAL
        ELSE IF (KSYS == 7) THEN
          IF (J == K .OR. J == L .OR. K == L) CALL PLA378 (3)
          IF (L == 2 * K - J .OR. K == 2 * J - L .OR. J .EQ.
     1      2 * L - K) CALL PLA378 (4)
          IF (J + K + L == 0) CALL PLA378 (5)
C * CUBIC
        ELSE IF (KSYS == 8) THEN
          IF (J == 0 .OR. K == 0 .OR. L == 0) CALL PLA378 (3)
          IF (IABS (J) == IABS (K) .OR. IABS (J) == IABS (L) .OR.
     1     IABS (K) == IABS (L)) CALL PLA378 (4)
C * H,H,2H IS IN TWO PRINCIPAL ZONES BUT NOT ON A PRINCIPAL AXIS
          IF (IND == 4) IND = 0
          IF (IABS (L) == IABS (J + K) .OR. IABS (K) == IABS (J + L)
     1      .OR.  IABS (J) == IABS (K + L)) CALL PLA378 (5)
        END IF
C * REFLECTIONS NOT BELONGING TO PRINCIPAL ZONES
        IF (IND == 1) CALL PLA378 (2)
C * DISTRIBUTION OF E FOR COMPLETE DATA
        NET = MIN0 (25, INT (10.0 * ED))
        IF (NET /= 0) NU(NET) = NU(NET) + 1
        NRW = NRW + MULT
      END DO
C * OUTPUT STATISTICS
      RRX = 1.0 / RRX
      DO I = 1, 10
        STL(I) = RRX * FLOAT (I)
        IF (NHR(I) > 0) RHR(I) = RHR(I) / FLOAT (NHR(I))
        DO J = 1, 5
          IF (NST(J) > 0) VST(I, J) = VST(I, J) / FLOAT (NST(J))
        END DO
      END DO
      WRITE (LU7, 99997) STL, RHR, NHR
      WRITE (LU7, 99996)
      WRITE (LU7, 99995)
      WRITE (RECORD, 99980)
      WRITE (RECORD(5:11), 99994)
C * CAPTION ACCORDING TO CRYSTAL SYSTEM
      IF (KSYS /= 7) WRITE (RECORD(51:53), 99993)
      IF (KSYS == 7) WRITE (RECORD(48:55), 99992)
      IF (KSYS <= 3) WRITE (RECORD(63:65), 99991)
      IF (KSYS >= 4) WRITE (RECORD(63:65), 99990)
      IF (KSYS <= 6) WRITE (RECORD(75:77), 99989)
      IF (KSYS >= 7) WRITE (RECORD(72:79), 99988)
      WRITE (LU7, 99979) RECORD
      GRAPH(54) = RECORD
      WRITE (LU7, 99987)
     1 ((VST(I, J), J = 1, 5), AVA(I), AVC(I), AVH(I), I = 1, 6)
      WRITE (RECORD, 99986)
     1 ((VST(I, J), J = 1, 5), AVA(I), AVC(I), AVH(I), I = 7, 7)
      WRITE (LU7, 99979) RECORD
      GRAPH (55)(2:120) = RECORD(2:116)
      WRITE (LU7, 99985)
     1 ((VST(I, J), J = 1, 5), AVA(I), AVC(I), AVH(I), I = 8, 10)
      WRITE (LU7, 99977) NST
      WRITE (LU7, 99984)
      WRITE (LU7, 99995)
      WRITE (RECORD, 99980)
      WRITE (RECORD(6:6), 99978)
C * CAPTION ACCORDING TO CRYSTAL SYSTEM
      IF (KSYS /= 7) WRITE (RECORD(51:53), 99993)
      IF (KSYS == 7) WRITE (RECORD(48:55), 99992)
      IF (KSYS <= 3) WRITE (RECORD(63:65), 99991)
      IF (KSYS >= 4) WRITE (RECORD(63:65), 99990)
      IF (KSYS <= 6) WRITE (RECORD(75:77), 99989)
      IF (KSYS >= 7) WRITE (RECORD(72:79), 99988)
      WRITE (LU7, 99979) RECORD
      DO I = 1, 25
        DO J = 2, 6
          IF (NST(J - 1) > 0) ZT(I, J) = ZT(I, J) / FLOAT (NST(J - 1))
          IF (I /= 1) ZT(I, J) = ZT(I, J) + ZT(I - 1, J)
        END DO
C * THEORETICAL DISTRIBUTION
        ZZ = 0.1 * FLOAT (I)
        IF (I > 10) ZZ = 2.0 * ZZ - 1.0
        ZT(I, 1) = ZZ
C * ACENTRIC DISTRIBUTION
        ZT(I, 7) = 1.0 - EXP(-ZZ)
C * CENTRIC DISTRIBUTION
        XX       = SQRT (0.5 * ZZ)
        T        = 1.0 / (1.0 + 0.47047 * XX)
        ZT(I, 8) = 1.0 - ((0.74786 * T -0.09588) * T + 0.34802) * T *
     1    EXP (-0.5 * ZZ)
        WRITE (LU7, 99983) (ZT(I, J), J = 1, 9)
      END DO
C * WEIGHTED SAMPLE SIZE
      WRITE (LU7, 99977) NST
      DO I = 1, 24
        J     = 25 - I
        NU(J) = NU(J) + NU(J + 1)
      END DO
      WRITE (LU7, 99982)
      DO I = 1, 25
        AVR(I) = 0.1 * FLOAT (I)
      END DO
      WRITE (LU7, 99981) (AVR(I), I = 7, 25), (NU(I), I = 7, 25)
      RETURN
99997 FORMAT (///, 52X, 'FINAL STATISTICS', //, 38X,
     1 'DISTRIBUTION OF E**2 WITH SIN(THETA)/LAMBDA', /, 'SINTH/LAM',
     2 10F10.4, /, 3X, 'E**2', 2X, 10F10.4, /, 2X, 'NUMBER', 10I10)
99996 FORMAT (//, 53X, 'AVERAGE VALUES', /)
99995 FORMAT (45X, 'EXPERIMENTAL', 39X, 'THEORETICAL')
99994 FORMAT('AVERAGE')
99993 FORMAT('0KL')
99992 FORMAT('H,K,2K-H')
99991 FORMAT('H0L')
99990 FORMAT('HHL')
99989 FORMAT('HK0')
99988 FORMAT('H,K,-H-K')
99987 FORMAT(6X, '|E|', 9X, 5F12.3, 2X, 3F12.3, /,
     1 6X, 'E**2', 8X, 5F12.3, 2X, 3F12.3, /,
     2 6X, 'E**3', 8X, 5F12.3, 2X, 3F12.3, /,
     3 6X, 'E**4', 8X, 5F12.3, 2X, 3F12.3, /,
     4 6X, 'E**5', 8X, 5F12.3, 2X, 3F12.3, /,
     5 6X, 'E**6', 8X, 5F12.3, 2X, 3F12.3)
99986 FORMAT (6X, '|E**2-1|', 4X, 5F12.3, 2X, 3F12.3)
99985 FORMAT (6X, '(E**2-1)**2', 1X, 5F12.3, 2X, 3F12.3, /,
     1        6X, '(E**2-1)**3', 1X, 5F12.3, 2X, 3F12.3, /,
     2        6X, '|E**2-1|**3', 1X, 5F12.3, 2X, 3F12.3)
99984 FORMAT (//, 40X, 'N(Z) CUMULATIVE PROBABILITY DISTRIBUTION')
99983 FORMAT (F7.1, 11X, 5F12.3, 2X, 3F12.3)
99982 FORMAT (/, 38X, 'DISTRIBUTION OF E - NUMBER OF E''S > LIMIT', /)
99981 FORMAT (2X, 'E  ', 19F6.1, /, 1X, 'NO. ', 19I6)
99980 FORMAT (23X, 'ALL DATA', 7X, 'HKL', 9X, '0kl', 9X, 'h0l', 9X,
     1  'hk0', 8X, 'ACENTRIC', 5X, 'CENTRIC', 2X, 'HYPERCENTRIC')
99979 FORMAT (A)
99978 FORMAT ('Z')
99977 FORMAT ('Weighted Sample Size', I10, 4I12)
      END SUBROUTINE PLA376
 
      SUBROUTINE PLA377 (ESQ, RHO, ED)
C * K-CURVE INTERPOLATION
      USE normal
      IMPLICIT NONE
      INTEGER :: I
      REAL :: EI
      REAL :: ED
      REAL :: SK
      REAL :: ESQ
      REAL :: RHO
      EI = RHO * DEL
      I  = INT (EI)
C * FOR SMALL RHO THE CURVE IS EXTRAPOLATED FROM THE FIRST POINT
C * USING THE LEAST SQUARES SLOPE
      IF (I == 0) SK = EXP (SLOPE * RHO + FLGK)
C * INTERPOLATION
      IF (I > 0 .AND. I < 50)
     1  SK = DCV(I) + (EI - FLOAT (I)) * (DCV(I + 1) - DCV(I))
C * FOR LARGE RHO THE CURVE IS EXTRAPOLATED FROM THE LAST POINT
      IF (I >= 50) SK = DCV(50) * EXP (SLOPE * (AVR(NB) - RHO))
      ESQ = ED / SK
      RETURN
      END SUBROUTINE PLA377
 
      SUBROUTINE PLA378 (N)
      USE normal
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      REAL    :: S
C * SUMS FOR REFLECTION IN ZONE N
      M = 1
      J = N
      IF (N > 2 .AND. IND > 1) THEN
C * REFLECTION IS ON PRINCIPAL AXIS - THEREFORE IGNORE IT
        J = IND
        M = -1
      END IF
      S = FLOAT (M)
      DO I = 1, 10
        VST(I, J) = VST(I, J) + S * EE(I)
      END DO
      NST(J) = NST(J) + M * MULT
      IF (NZR <= 25) ZT(NZR, J + 1) = ZT(NZR, J + 1) + S * TMUL
      IND = N
      RETURN
      END SUBROUTINE PLA378
 
      SUBROUTINE PLA379 (MODE)
C * N(Z)-PLOT
      USE cggt
      USE normal
      USE cchar
      USE parameters
      USE files
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: MODE
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: ZZ
      REAL :: SCALEX
      REAL :: SCALEY
      CHARACTER(len=3) :: TXT
      CALL GGIP (HORS, VERT, 0.0, 1)
C * N(Z)-STATISTICS DISPLAY
      IF (MODE == 1) THEN
        VRT = VERT - 0.5
C * N(Z) HEADER
        WRITE (PRBUF, 99998)
        CALL PLA439 (0.0, PRBUF, 120, 0.25, 1, 1, 0.0, VRT)
        VRT = VRT - 0.5
        WRITE (PRBUF, 99997)
        CALL PLA439 (0.0, PRBUF, 120, 0.25, 1, 1, 0.0, VRT)
        VRT = VRT - 0.5
        WRITE (PRBUF, 99996)
        CALL PLA439 (0.0, PRBUF, 120, 0.25, 1, 1, 0.0, VRT)
        DO I = 1, 25
          WRITE (PRBUF, 99999) (ZT(I, J), J = 1, 9)
          VRT = VRT - 0.5
          CALL PLA439 (0.0, PRBUF, 120, 0.25, 1, 1, 0.0, VRT)
        END DO
        WRITE (PRBUF, 99994)
        VRT = VRT - 2.0
        CALL PLA439 (0.0, PRBUF, 80, 0.3, 1, 1, 1.0, VRT)
C * N(Z)-PLOT
      ELSE IF (MODE == 2) THEN
        VRT = VERT - 1.2
        CALL PLA439 (0.0, 'N(Z)-PLOT for '//JID(1:10), 24, 0.6, 5, 2,
     1    2.0, VRT)
C * SOURCE REFLECTION DATA
        VRT = VRT - 1.0
        N   = KNMFIL + KXT + 12
        CALL PLA439 (0.0, 'ReflData = '//FNLU1(1:N - 11),
     1    N, 0.4, 5, 2, 2.0, VRT)
C * SPGR
        VRT = VRT - 1.0
        CALL PLA439 (0.0, 'SpGrName = '//ZSPG, 18, 0.4, 5, 2, 2.0, VRT)
C * SHOW SUMFORMULA
        N = INDEX (RLWS(5), '''') - 1
        IF (N > 0) THEN
          VRT = VRT - 1.0
          CALL PLA439 (0.0, 'SumFormula '//RLWS(5), N + 11, 0.30,
     1      5 + IGBL(68), 2, 2.0, VRT)
        END IF
        SCALEX = (HORS - 1.0) / 4.0
        SCALEY =  VERT - 1.0
        CALL GGIP (1.0, 1.0, 0.0, -3)
        CALL GGIP (0.0, 0.0, 0.0, 3)
C * LABEL AXES
        X = HORS - 1.0
        CALL GGIP (X, 0.0, 0.0, 2)
        CALL GGIP (0.0, 0.0, 0.0, 3)
        CALL PLA439 (0.0, 'Z', 1, 0.5, 1, 2, X - 0.6, 0.6)
        DO I = 1, 4
          WRITE (TXT, 99995) FLOAT (I)
          X = SCALEX * I
          CALL GGIP (X, 0.0, 0.0, 3)
          CALL GGIP (X, -0.5, 0.0, 2)
          CALL PLA439 (0.0, TXT, 3, 0.4, 1, 2, X - 1.3, -0.5)
        END DO
        Y = VERT - 1.0
        CALL GGIP (0.0, 0.0, 0.0, 3)
        CALL GGIP (0.0, Y, 0.0, 2)
        CALL GGIP (0.0, 0.0, 0.0, 3)
        DO I = 1, 10
          Z  = I * 0.1
          ZZ = Z * SCALEY
          WRITE (TXT, 99995) Z
          CALL PLA439 (0.0, TXT, 3, 0.3, 1, 2, -0.9, ZZ - 0.4)
          CALL GGIP ( 0.0, ZZ, 0.0, 3)
          CALL GGIP (-0.5, ZZ, 0.0, 2)
          CALL GGIP (0.0, 0.0, 0.0, 3)
        END DO
C * HYPER-CENTRIC
        CALL PLA439 (0.0, 'HYPER-CENTRIC', 13, 0.5, 4, 2, 16.0, 10.0)
        CALL GGIP (0.0, 4.0, 0.0, 0)
        CALL GGIP (0.0, 0.0, 0.0, 3)
        DO I = 1, 25
          X = ZT(I, 1) * SCALEX
          Y = ZT(I, 9) * SCALEY
          CALL GGIP (X, Y, 0.0, 2)
        END DO
C * CENTRIC
        CALL PLA439 (0.0, 'CENTRIC', 7, 0.5, 2, 2, 16.0,  8.5)
        CALL GGIP (0.0, 2.0, 0.0, 0)
        CALL GGIP (0.0, 0.0, 0.0, 3)
        DO I = 1, 25
          X = ZT(I, 1) * SCALEX
          Y = ZT(I, 8) * SCALEY
          CALL GGIP (X, Y, 0.0, 2)
        END DO
C * ACENTRIC
        CALL PLA439 (0.0, 'ACENTRIC', 8, 0.5, 3, 2, 16.0,  7.0)
        CALL GGIP (0.0, 3.0, 0.0, 0)
        CALL GGIP (0.0, 0.0, 0.0, 3)
        DO I = 1, 25
          X = ZT(I, 1) * SCALEX
          Y = ZT(I, 7) * SCALEY
          CALL GGIP (X, Y, 0.0, 2)
        END DO
C * EXPERIMENTAL
        CALL PLA439 (0.0, 'EXPERIMENTAL', 12, 0.5, 1, 2, 16.0,  5.5)
        CALL GGIP (0.0, 1.0, 0.0, 0)
        CALL GGIP (0.0, 0.0, 0.0, 3)
        DO I = 1, 25
          X = ZT(I, 1) * SCALEX
          Y = ZT(I, 3) * SCALEY
          CALL GGIP (X, Y, 0.0, 2)
        END DO
      END IF
      CALL GGIP (0.0, 0.0, 0.0, 6)
      RETURN
99999 FORMAT (F7.1, 11X, 5F12.3, 2X, 3F12.3)
99998 FORMAT (40X, 'N(Z) CUMULATIVE PROBABILITY DISTRIBUTION')
99997 FORMAT (45X, 'EXPERIMENTAL', 39X, 'THEORETICAL')
99996 FORMAT (23X, 'ALL DATA', 7X, 'HKL', 9X, '0kl', 9X, 'h0l', 9X,
     1  'hk0', 8X, 'ACENTRIC', 5X, 'CENTRIC', 2X, 'HYPERCENTRIC')
99995 FORMAT (F3.1)
99994 FORMAT ('N(Z): Howells, E.R., Phillips, D.C. & Rogers,D. (1950),',
     1 ' Acta Cryst., 3, 210-214')
      END SUBROUTINE PLA379
 
      SUBROUTINE PLA381 (MODE, LRETPDB)
C * PDB-READ
      USE files
      USE parameters
      USE atomdata
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: IP
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: NAT
      INTEGER :: IER
      INTEGER :: NAT2
      INTEGER :: NATC
      INTEGER :: NATH
      INTEGER :: NATN
      INTEGER :: NATO
      INTEGER :: NATS
      INTEGER :: NCRY
      INTEGER :: MODE
      INTEGER :: INQNR
      INTEGER :: LRETPDB
      REAL :: ADD
      REAL :: XADD
      IF (LRETPDB == 0) THEN
        NATC = 0
        NATO = 0
        NATN = 0
        NATS = 0
        NATH = 0
        NAT  = 0
        NAT2 = 0
        NCRY = 0
        XADD = 25.0
        ADD  = 0.0
        DO
          READ (IGBL(5), 99997, IOSTAT = IOST) ICL(1:80)
          IF (IOST /= 0) THEN
            IF (IOST == -1) THEN
              GO TO 20
            ELSE
              GO TO 30
            END IF
          END IF
          CALL GEN020 (1, ICL, 1, 80)
          IF (ICL(1:4) == 'ATOM' .OR. ICL(1:4) == 'HETA') THEN
            READ (ICL, 99998) NQ1(1:7), (FN(L), L = 1, 3)
            FN(1) = FN(1) + ADD
            NB    = 1
            NE    = 2
            N1    = 0
            N2    = 0
C * TEST FOR A-Z OF FIRST CHARACTER
            IF (ICHAR (NQ1(1:1)) > 64 .AND. ICHAR (NQ1(1:1)) < 91)
     1        N1 = 1
C * TEST FOR A-Z OF SECOND CHARACTER
            IF (ICHAR (NQ1(2:2)) > 64 .AND. ICHAR (NQ1(2:2)) < 91)
     1        N2 = 1
            IF (N1 == 1 .AND. N2 == 0) THEN
              NE = 1
            ELSE IF (N1 == 0 .AND. N2 == 1) THEN
              NB = 2
            ELSE IF (N1 == 1 .AND. N2 == 1) THEN
              NAT2 = NAT2 + 1
              N    = NAT2
              GO TO 10
            ELSE
              WRITE (LU6, 99995, IOSTAT = IOST) NQ1
              RETURN
            END IF
            IF (NQ1(NB:NE) == 'C') THEN
              NATC = NATC + 1
              N    = NATC
            ELSE IF (NQ1(NB:NE) == 'O') THEN
              NATO = NATO + 1
              N    = NATO
            ELSE IF (NQ1(NB:NE) == 'N') THEN
              NATN = NATN + 1
              N    = NATN
            ELSE IF (NQ1(2:2) == 'S') THEN
              NATS = NATS + 1
              N    = NATS
            ELSE IF (NQ1(2:2) == 'H') THEN
              NATH = NATH + 1
              N    = NATH
            ELSE
              NAT  = NAT + 1
              N    = NAT
            END IF
   10       N  = MOD (N, 1000)
            CALL GEN040 (N, NQ2, IP)
            IFL(1)   = NQ1(NB:NE)//NQ2(1:IP)
            IPR(473) = 1
            IPR(220) = 1
            IPR(221) = 3
            IF (MODE == 0) THEN
              CALL PLA450 (INQNR)
              IF (INQNR == 0) THEN
                IGBL(54) = IGBL(54) + 1
                GO TO 20
              END IF
            ELSE
              CALL PLUT03 (IER)
            END IF
C * ANISOU
          ELSE IF (ICL(1:6) == 'ANISOU') THEN
            READ (ICL(29:70), 99996)
     1      FN(1), FN(2), FN(3), FN(6), FN(5), FN(4)
            DO I = 1, 6
              FN(I) = FN(I) / 10000.0
            END DO
            FN(7) = 0.0
            FN(8) = 0.0
C * REGISTER (AN)ISO PARAMETER INPUT
            IPR(32) = MAX (IPR(32), 1)
            WRITE (LU4) 2, INQNR, (FN(K), K = 1, 8)
            CYCLE
          ELSE IF (ICL(1:3) == 'ADD') THEN
            XADD = FN(1)
          ELSE IF (ICL(1:5) == 'CRYST') THEN
            NCRY = NCRY + 1
            IF (NCRY == 2) ADD = XADD
          ELSE IF (ICL(1:3) == 'END') THEN
            IFL(1)   = 'ENDS'
            ICL      = 'ENDS'
            IPR(220) = 1
            IPR(221) = 0
            IGBL(8) = - IABS (IGBL(8))
            RETURN
          ELSE IF (ICL(1:5) == 'CONECT') THEN
          ELSE IF (ICL(1:5) == 'MASTER') THEN
          END IF
        END DO
      ELSE IF (LRETPDB == -1) THEN
C * CHECK FOR PDB-FILE-STRUCTURE (TRIGGERED BY KEYWORD HEADER ON LINE 1)
        IF (ICL(1:6) == 'HEADER' .OR.
     1      ICL(1:6) == 'REMARK' .OR.
     2      ICL(1:6) == 'COMPND') THEN
          IGBL(8) = 4
          IF (ICL(63:66) /= '    ') THEN
            JID(1:72) = ICL(63:66)
          ELSE
            JID(1:72) = ICL(8:50)
          END IF
          WRITE (LU6, 99999, IOSTAT = IOST)
          IPR(220) = 1
          IPR(221) = 0
C * GET NUMBER OF ENTRIES IN MENU MODE
          IF (IGBL(25) /= 0) THEN
            CALL PLA007
          ELSE
            CALL GEN108 (LU1, 0)
          END IF
          RETURN
        END IF
        IF (ICL(1:5) == 'CRYST') THEN
          IGBL(8) = 4
          WRITE (LU6, 99999, IOSTAT = IOST)
          RETURN
        END IF
      END IF
      RETURN
C * ERROR
   20 LRETPDB = 1
      RETURN
C * END
   30 LRETPDB = 2
      RETURN
99999 FORMAT (/, ':: PDB Type File Format Assumed (HEADER/CRYST)', /)
99998 FORMAT (12X, A, 11X, 3F8.0)
99997 FORMAT (A)
99996 FORMAT (6F7.0)
99995 FORMAT ('Atom ', A, ' - Skipped')
      END SUBROUTINE PLA381
 
      SUBROUTINE PLA382 (IRETN)
C * LIST OPTION(S) ON DISPLAY
C * ATOMS/BONDS/SYMM/PAR/IPR/IGBL/RADII/CELL/UIJ/UEQ,ARU
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
 
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NAT
      INTEGER :: IF1
      INTEGER :: IF2
      INTEGER :: IF3
      INTEGER :: IF4
      INTEGER :: IF5
      INTEGER :: IF6
      INTEGER :: IF7
      INTEGER :: IF8
      INTEGER :: IF9
      INTEGER :: IF10
      INTEGER :: IF11
      INTEGER :: IF12
      INTEGER :: IF13
      INTEGER :: IF14
      INTEGER :: IF15
      INTEGER :: IF16
      INTEGER :: IF17
      INTEGER :: IF18
      INTEGER :: IF19
      INTEGER :: IF20
      INTEGER :: IF21
      INTEGER :: IF22
      INTEGER :: IF23
      INTEGER :: JMAX
      INTEGER :: KMAX
      INTEGER :: MODE
      INTEGER :: IVAL
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: IRETN
      CHARACTER(len=1) :: ICH
      IF (IGBL(8) /= 2 .OR. IGBL(5) == LU5) THEN
        IPR(84) = 0
        IPR(1)  = 4
        IWIN    = IGBL(25) * IGBL(32)
        IF (IPR(220) > 1) THEN
C * LIST IPR/PAR/IGBL/RGBL/CHK
          IF (IPR(220) >= 2) THEN
            SELECT CASE (IFL(2)(1:3))
              CASE ('IPR')
                CALL PLA206 (-1, 'IPR')
              CASE ('PAR')
                CALL PLA206 (-1, 'PAR')
              CASE ('IGB')
                CALL PLA206 (-1, 'IGB')
              CASE ('RGB')
                CALL PLA206 (-1, 'RGB')
              CASE ('CHK')
                CALL PLA206 (-1, 'CHK')
C * LIST FLAGS
              CASE ('FLA')
                NAT = IPR(39) + IPR(64)
                WRITE (PRBUF, 99995, IOSTAT = IOST)
                IF (IWIN == 1) THEN
                  CALL GGIP (HORS, VERT, 0.0, 1)
                  VRT = VERT - 0.6
                  CALL PLA439 (0.0, PRBUF, 80, 0.35, 5 + IGBL(68),
     1              2, 1.0, VRT)
                  VRT = VRT - 0.2
                ELSE
                  WRITE (LU6, 99997, IOSTAT = IOST) PRBUF(1:80)
                END IF
                DO I = 1, NAT
                  CALL PLA047 (LABA(I), NQ1, IDUM, JDUM,
     1              IPR(71), IGBL(55), 0, 1 - IGBL(55))
C * DONE/FIX/NEXT
                  CALL GEN048 (-3,  IFG(1, I), 1,  IF1)
C * ISO/ANISO
                  CALL GEN048 (-1,  IFG(1, I), 4,  IF2)
C * SYMMETRY RELATED
                  CALL GEN048 (-1,  IFG(1, I), 5,  IF3)
C * SPECIAL POSITION
                  CALL GEN048 (-1,  IFG(1, I), 6,  IF4)
C * H-ATOM
                  CALL GEN048 (-1,  IFG(1, I), 7,  IF5)
C * ATOM WITH MORE THAN 9 CONNECTIONS
                  CALL GEN048 (-1,  IFG(1, I), 8,  IF6)
C * RESIDUE #
                  CALL GEN048 (-6,  IFG(1, I), 9,  IF7)
C * ATOM TYPE # IN IEN
                  CALL GEN048 (-4,  IFG(1, I), 15, IF8)
C * METAL
                  CALL GEN048 (-1,  IFG(1, I), 19, IF9)
C * POTENTIAL H-BOND H-ATOM
                  CALL GEN048 (-1,  IFG(1, I), 20, IF10)
C * POTENTIAL DONOR ATOM
                  CALL GEN048 (-1,  IFG(1, I), 21, IF11)
C * POTENTIAL ACCEPTOR ATOM
                  CALL GEN048 (-1,  IFG(1, I), 22, IF12)
C * DONOR/ACCEPTOR ATOM
                  CALL GEN048 (-1,  IFG(1, I), 23, IF13)
C * HTYBRIDASATION TYPE
                  CALL GEN048 (-4,  IFG(1, I), 24, IF14)
C * OMIT  (FROM SFCalc)
                  CALL GEN048 (-1,  IFG(1, I), 30, IF15)
C * C(O2), N(O3), S(O4), Cl(O4), P(O4)
                  CALL GEN048 (-1,  IFG(1, I), 31, IF16)
C * POP
                  CALL GEN048 (-8,  IFG(2, I),  1, IF17)
C * ISI(0/1)
                  CALL GEN048 (-1,  IFG(2, I), 10, IF18)
C * LABEL (0/1)
                  CALL GEN048 (-1,  IFG(2, I), 11, IF19)
C * HINC (0/1)
                  CALL GEN048 (-1,  IFG(2, I), 12, IF20)
C * LABUTTE #
                  CALL GEN048 (-10, IFG(2, I), 14, IF21)
C * # ATTACHED H
                  CALL GEN048 (-3,  IFG(2, I), 24, IF22)
C * PART
                  CALL GEN048 (-5,  IFG(3, I), 14, IF23)
                  WRITE (PRBUF, 99983, IOSTAT = IOST) I, NQ1, IF1,
     1              IF2, IF3, IF4, IF5, IF6, IF7, IF8, IF9, IF10,
     2              IF11, IF12, IF13, IF14, IF15, IF16, IF17, IF18,
     3              IF19, IF20, IF21, IF22, IF23 -16
                  IF (IWIN == 1) THEN
                    IF (VRT - 0.4 < 0) THEN
C * WHAT NEXT ?
                      CALL PLA012 (1, 1)
                      ICH = IGGT(1:1)
                      CALL GGIP (HORS, VERT, 0.0, 1)
                      IF (ICH /= 'Y' .AND. ICH /= '!') RETURN
                      VRT = VERT
                    END IF
                    VRT = VRT - 0.4
                    CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
                  ELSE
                    WRITE (LU6, 99994, IOSTAT = IOST) PRBUF(1:80)
                  END IF
                END DO
                IF (IWIN == 1) CALL PLA297 (1)
C * LIST/INFO SYMM
              CASE ('SYM')
                CALL PLA274
C * LIST/INFO CELL
              CASE ('CEL')
                WRITE (BCD, 99991, IOSTAT = IOST)
     1            (PAR(J), J = 101, 106), CHAR (0)
                IF (IWIN == 1) THEN
                  IF (ABS (IGBL(6)) >= 10 .AND.
     1                ABS (IGBL(6)) <= 12) IGBL(6) = - IABS (IGBL(6))
                  CALL GGIP (-999.0, 5.0 + FLOAT (IGBL(68)), 66.0, 111)
                ELSE
                  WRITE (LU6, 99985, IOSTAT = IOST) BCD(1:65)
                END IF
C * LIST/INFO RADII
              CASE ('RAD')
                WRITE (PRBUF, 99998, IOSTAT = IOST)
                IF (IWIN == 1) THEN
                  CALL GGIP (HORS, VERT, 0.0, 1)
                  VRT = VERT - 2.0
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99984, IOSTAT = IOST) PRBUF(1:75)
                END IF
                WRITE (PRBUF, 99982, IOSTAT = IOST)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.6
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99984, IOSTAT = IOST) PRBUF(1:75)
                END IF
                WRITE (PRBUF, 99993, IOSTAT = IOST) PAR(2)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.9
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99985, IOSTAT = IOST) PRBUF(1:75)
                END IF
                WRITE (PRBUF, 99981, IOSTAT = IOST) PAR(542)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.6
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99984, IOSTAT = IOST) PRBUF(1:75)
                END IF
                WRITE (PRBUF, 99980, IOSTAT = IOST) IGBL(97) * PAR(26)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.6
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99984, IOSTAT = IOST) PRBUF(1:75)
                END IF
                WRITE (PRBUF, 99990, IOSTAT = IOST) PAR(3)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.6
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                ELSE
                  WRITE (LU6, 99984, IOSTAT = IOST) PRBUF(1:75)
                END IF
                WRITE (PRBUF, 99999, IOSTAT = IOST)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.9
                  CALL PLA439 (0.0, PRBUF, 75, 0.35, 5 + IGBL(68), 2,
     1                         1.0, VRT)
                ELSE
                  WRITE (LU6, 99985, IOSTAT = IOST) PRBUF(1:75)
                END IF
                DO I = 1, IAN
                  WRITE (PRBUF, 99996, IOSTAT = IOST)
     1              LMT(I, 1), RADR(I, 3), RADR(I, 4), RADR(I, 2)
                  IF (IWIN == 1) THEN
                    VRT = VRT - 0.6
                    CALL PLA439 (0.0, PRBUF, 75, 0.35, 1, 2, 1.0, VRT)
                  ELSE
                    WRITE (LU6, 99984, IOSTAT = IOST) PRBUF(1:75)
                  END IF
                END DO
                IF (IWIN == 1) CALL PLA297 (1)
C * LIST/INFO U1, U2, U3, U(eq) and U3/U1 VALUES
 
              CASE ('UIJ','UEQ')
C * TEST FOR PREVIOUS CALC UNIQUE (NO = 0)
                IF (IFL(2)(1:3) == 'UIJ') THEN
                  MODE = 0
                ELSE
                  MODE = 1
                END IF
                IF (IPR(30) /= 0) THEN
                  IF (MODE == 0) THEN
                    WRITE (PRBUF, 99987, IOSTAT = IOST)
                  ELSE
                    WRITE (PRBUF, 99988, IOSTAT = IOST)
                  END IF
                  IF (IWIN == 1) THEN
                    CALL GGIP (HORS, VERT, 0.0, 1)
                    VRT = VERT - 0.6
                    CALL PLA439 (0.0, PRBUF, 75, 0.35, 5 + IGBL(68),
     1                           2, 1.0, VRT)
                    VRT = VRT - 0.2
                  ELSE
                    WRITE (LU6, 99994, IOSTAT = IOST) PRBUF(1:75)
                  END IF
                  NAT = IPR(39)
                  DO I = 1, NAT
                    DO J = 1, 12
                      FN(J) = VOID(IPR(297) + (I - 1) * 21 + J)
                    END DO
                    CALL PLA047 (LABA(I), NQ1, IDUM, JDUM,
     1                IPR(71), IGBL(55), 0, 0)
C * TEST FOR (AN)ISOTROPIC
                    CALL GEN048 (-1, IFG(1, I), 4, IVAL)
                    IF (IVAL == 1) THEN
                      IF (MODE == 0) THEN
                        KMAX = 6
                        JMAX = 4
                      ELSE
                        JMAX  = 5
                        FN(4) = 0.0
                        DO J = 1, 3
                          FN(J) = FN(J + 9)**2
                          FN(4) = FN(4) + FN(J) / 3.0
                        END DO
                        FN(5) = FN(3) / FN(1)
                      END IF
                    ELSE
C * SKIP ISOTROPIC H-ATOMS
                      CALL GEN048 (-1, IFG(1, I), 7, IVAL)
                      IF (IVAL == 1) CYCLE
                      KMAX = 1
                      JMAX = 1
                      IF (MODE == 1) FN(1) = FN(10)**2
                    END IF
                    IF (MODE == 0) THEN
                      WRITE (PRBUF, 99986, IOSTAT = IOST)
     1                  NQ1(1:10), (ANIS(I, J), J = 1, KMAX)
                    ELSE
                      WRITE (PRBUF, 99989, IOSTAT = IOST)
     1                  NQ1, (FN(J), J = 1, JMAX)
                    END IF
                    IF (IWIN == 1) THEN
                      IF (VRT - 0.4 < 0.0) THEN
C * WHAT NEXT ?
                        CALL PLA012 (1, 1)
                        ICH = IGGT(1:1)
                        CALL GGIP (HORS, VERT, 0.0, 1)
                        IF (ICH /= 'Y' .AND. ICH /= '!') RETURN
                        VRT = VERT
                      END IF
                      VRT = VRT - 0.4
                      CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
                    ELSE
                      WRITE (LU6, 99994, IOSTAT = IOST) PRBUF(1:80)
                    END IF
                  END DO
                  IF (IWIN == 1) CALL PLA297 (1)
                END IF
C * LIST ARU
              CASE ('ARU')
                CALL PLA043 (0, -2, LU6, 1)
                IF (IWIN == 1) CALL PLA297 (1)
C * LIST/INFO ATOMS AND BONDS
              CASE ('ATO')
                IF (IPR(39) > 0) THEN
                  IPR(84) = 1
                  IRETN   = 1
                  RETURN
                ELSE
                  WRITE (LU6, 99992, IOSTAT = IOST)
                ENDIF
              CASE ('BON')
                IF (IPR(39) > 0) THEN
                  IPR(84) = 2
                  IRETN   = 1
                  RETURN
                ELSE
                  WRITE (LU6, 99992, IOSTAT = IOST)
                END IF
            END SELECT
            RETURN
          END IF
        END IF
        IRETN = 1
      END IF
      RETURN
99999 FORMAT ('Element   Covalent(RC) van der Waals(RW) Current')
99998 FORMAT ('INTRA BONDS    for Dist(I-J) < RC(I) + RC(J)',
     1        ' + TOLA + (TOLEA/TOLCUO)')
99997 FORMAT (/, A, /)
99996 FORMAT (A, 1X, 4(4X, F10.2))
99995 FORMAT ('Atom Label', 8X, 'DFN A S P H C  R  T M P D A A  H O O',
     1        '  P U L H    L N PT')
99994 FORMAT (A)
99993 FORMAT ('TolA   [=PAR(2)]   = ', F5.2,
     1        ' Ang., current INTRA tolerance')
99992 FORMAT (':: No ATOMS supplied as yet')
99991 FORMAT ('CELL ', 3F10.4, 3F10.2, A)
99990 FORMAT ('TolR   [=PAR(3)]   = ', F5.2,
     1        ' Ang., current INTER tolerance')
99989 FORMAT (A, 1X, 3F8.4, 3X, F8.4, F10.2)
99988 FORMAT ('Atom', 13X , 'U1', 6X, 'U2', 6X, 'U3', 8X, 'U(eq)',
     1         5X, 'U3/U1')
99987 FORMAT ('Atom', 12X, 'U11', 6X, 'U22', 6X, 'U33', 6X, 'U23', 6X,
     1        'U13', 6X, 'U12')
99986 FORMAT (A, 6F9.4)
99985 FORMAT (/, ':: ', A)
99984 FORMAT (':: ', A)
99983 FORMAT (I4, 1X, A, I4, 5I2, 2I3, 5I2, I3, 2I2, I3, 3I2, I5, I2,
     1        I3)
99982 FORMAT ('INTER CONTACTS for Dist(I-J) < RW(I) + RW(J) + TOLR')
99981 FORMAT ('TolCuO [=PAR(542)] = ', F5.2,
     1        ' Ang., add for (Cu...O,N) Contacts')
99980 FORMAT ('TolEA  [=PAR(26)]  = ', F5.2,
     1        ' Ang., add for (Earth)Alkali- non-metal contacts')
      END SUBROUTINE PLA382
 
      SUBROUTINE PLA383 (IS)
C * HANDLE SHELXL TYPE INSTRUCTION RECORDS (.ins OR .res FILES)
      USE parameters
      USE files
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IS
      IF (IS > 0) THEN
        SELECT CASE (IS)
C * IS = 2: TITL RECORD
          CASE (2)
            M = 1
            N = 0
            CALL GEN039 (0, ICL, 5, 80, M, N)
            IF (N >= M) THEN
              JID = ICL(M:N)
              IF (N - M + 1 > 32) N = M + 31
              L = INDEX (ICL(M:N), ' ')
              IF (L /= 0) N = M + L - 2
              DATANM = ICL(M:N)
            ELSE
              DATANM = 'X'
            END IF
            CALL GEN020 (-1, DATANM, 1, 32)
            WRITE (LU6, 99999, IOSTAT = IOST) JID(1:50)
            IF (IGBL(100) == 0 .AND. (IABS (IGBL(8)) == 2 .OR.
     1                                IABS (IGBL(8)) == 1)) THEN
              IPR(220) = 1
              IPR(221) = 0
              IGBL(54) = -1
              CALL PLA007
            END IF
            IF (IGBL(100) > 0) THEN
              IGBL(54) = IGBL(54) + 1
            ELSE
              IGBL(54) = 1
            END IF
C * IS = 4: REM RECORD
          CASE (4)
C * IS = 29: LIST RECORD
          CASE (29)
            RETURN
C * IS = 30: CELL RECORD
          CASE (30)
            RETURN
C * IS = 32: SYMM RECORD
          CASE (32)
            RETURN
C * IS = 34: LATT RECORD
          CASE (34)
            RETURN
C * IS = 43: FVAR RECORD
          CASE (43)
            IGBL(8) = 2
            IF (IPR(109) + IPR(221) > NP25) THEN
              IPR(2) = 30
              IS     = 0
              RETURN
            END IF
C * STORE STRIPPED FREE VARIABLES
            DO I = 1, IPR(221)
              IF (IPR(109) + I == 1) THEN
                RP(1) = FN(1)
              ELSE
                RP(IPR(109) + I) = MOD (FN(I) + 5.0, 10.0) - 5.0
              END IF
            END DO
C * SAVE FVAR SCALE
            IF (IPR(109) == 0) THEN
              PAR(74) = RP(1)
              RP(1)   = 1.0
            END IF
            IPR(109) = IPR(109) + IPR(221)
C * IS = 47: AFIX RECORD
          CASE (47)
            IGBL(8) = 2
C * IS = 48: SFAC RECORD
          CASE (48)
            RETURN
C * IS = 49: UNIT RECORD (SHELX)
          CASE (49)
            IGBL(8) = 2
            DO I = 1, IPR(221)
              CONT(I, 3) = FN(I) * PAR(32)
            END DO
C * IS = 50: WGHT RECORD (SHELX)
          CASE (50)
            IGBL(8)  = 2
            IPR(632) = 1
            PAR(493) = FN(1)
            PAR(494) = FN(2)
            PAR(495) = FN(3)
C * IS = 54: BOND RECORD (SHELX)
          CASE (54)
            IGBL(8) = 2
C * IS = 55: ZERR RECORD (SHELXTL/SHELXL)
          CASE (55)
            DO I = 2, 7
              PAR(105 + I) = FN(I)
            END DO
            IGBL(8) = 2
C * IS = 57: L.S. RECORD (SHELX)
          CASE (57)
            IGBL(8) = 2
C * IS = 58: FMAP RECORD (SHELX)
          CASE (58)
            IGBL(8) = 2
C * IS = 62: BLOC RECORD (SHELX)
          CASE (62)
            IGBL(8) = 2
C * IS = 64: OMIT RECORD
          CASE (64)
            RETURN
C * IS = 65: GRID RECORD (SHELX)
          CASE (65)
            IGBL(8) = 2
C * IS = 66: DFIX RECORD (SHELX)
          CASE (66)
            IGBL(8) = 2
C * IS = 73: PART RECORD - SHELXL STYLE
          CASE (73)
            IPR(612) = NINT (FN(1))
            IGBL(30) = 1
C * IS = 76 : RTAB RECORD
          CASE (76)
            RETURN
C * IS = 77 : SIMU RECORD
          CASE (77)
            RETURN
C * IS = 81: EXTI RECORD (SHELXL)
          CASE (81)
            PAR(229) = FN(1)
C * IS = 98: PLAN RECORD
          CASE (98)
            RETURN
C * IS = 99: TWIN RECORD
          CASE (99)
            IF (IPR(221) == 0) THEN
              PAR(332) = -1.0
              PAR(336) = -1.0
              PAR(340) = -1.0
            ELSE
              DO I = 1, 9
                PAR(331 + I) = FN(I)
              END DO
            END IF
            IPR(193) = IPR(193) + 100
C * IS = 100: SPEC RECORD
          CASE (100)
            RETURN
C * IS = 101: MERG RECORD
          CASE (101)
            RETURN
C * IS = 102: SUMP RECORD
          CASE (102)
            RETURN
C * IS = 103: RESI RECORD
          CASE (103)
            IPR(538) = NINT (FN(1))
C * IS = 104: SHEL RECORD
          CASE (104)
            IF (IPR(221) == 2 .AND. FN(1) > 0.0) THEN
              IF (FN(2) /= 0.0) THEN
                PAR(165) = ASIN (PAR(17) / (2.0 * FN(2))) * RGBL(6)
              END IF
              IGBL(8)  = 2
            END IF
C * IS = 105: MORE RECORD
          CASE (105)
            RETURN
C * IS = 107: CGLS RECORD
          CASE (107)
            RETURN
C * IS = 108: ACTA RECORD
          CASE (108)
            RETURN
C * IS = 109: DAMP RECORD
          CASE (109)
            RETURN
C * IS = 110: DISP RECORD
          CASE (110)
            RETURN
C * IS = 112: CRYSTAL SIZE RECORD
          CASE (112)
            IF (IPR(221) == 3) THEN
              CALL GEN034 (FN, 1, 3)
              DO I = 1, 3
                PAR(301 + I) = FN(I)
              END DO
            END IF
C * IS = 113: EQIV RECORD
          CASE (113)
            RETURN
C * IS = 114: EXYZ RECORD
          CASE (114)
            RETURN
C * IS = 115: EADP RECORD
          CASE (115)
            RETURN
C * IS = 116: NCSY RECORD
          CASE (116)
C * IS = 117: FREE RECORD
          CASE (117)
            RETURN
C * IS = 118: BIND RRCORD
          CASE (118)
            RETURN
C * IS = 119: SAME RECORD
          CASE (119)
            RETURN
C * IS = 120: CONF RECORD
          CASE (120)
            RETURN
C * IS = 121: MPLA RECORD
          CASE (121)
            RETURN
C * IS = 122: FLAT RECORD
          CASE (122)
            RETURN
C * IS = 123: CHIV RECORD
          CASE (123)
            RETURN
C * IS = 124: DELU RECORD
          CASE (124)
            RETURN
C * IS = 125: ISOR RECORD
          CASE (125)
            RETURN
C * IS = 126: SADI RECORD
          CASE (126)
            RETURN
C * IS = 127: ANIS RECORD
          CASE (127)
            RETURN
C * IS = 129: HFIX RECORD
          CASE (129)
            RETURN
C * IS = 130: LAUE RECORD
          CASE (130)
            RETURN
C * IS = 131: BUMP RECORD
          CASE (131)
            RETURN
C * IS = 132: TEMP RECORD (SHELX ==> DEG. C) ([C]/K)
          CASE (132)
            IF (IFL(2)(1:1) == 'K') THEN
              IPR(261) = NINT (FN(1))
            ELSE
              IPR(261) = NINT (FN(1)) + 273
            END IF
C * IS = 133: DEFS RECORD
          CASE (133)
C * IS = 135: SWAT RECORD
          CASE (135)
C * IS = 141: WPDB RECORD
          CASE (141)
C * IS = 142: BASF RECORD
          CASE (142)
            IF (IPR(221) > 0) THEN
              DO I = 1, IPR(221)
                BASF(I) = FN(I)
              END DO
              IPR(513) = IPR(221)
              PAR(341) = FN(1)
              IPR(193) = IPR(193) + 1
            END IF
C * IS = 144: FRAG RECORD
          CASE (144)
C * IS = 189: ABIN RECORD (SHELXL COMMAND)
          CASE (189)
            IPR(766) = 1
C * IS = 190: ANSC RECORD (SHELXL COMMAND)
          CASE (190)
C * IS = 191: ANSR RECORD (SHELXL COMMAND)
          CASE (191)
C * IS = 192: NEUT RECORD (SHELXL COMMAND)
          CASE (192)
            IPR(493) = 7
C * IS = 193: PRIG RECORD (SHELXL COMMAND)
          CASE (193)
C * IS = 194: RIGU RECORD (SHELXL COMMAND)
          CASE (194)
C * IS = 195: STIR RECORD (SHELXL COMMAND)
          CASE (195)
C * IS = 196: TWST RECORD (SHELXL COMMAND)
          CASE (196)
C * IS = 197: WIGL RECORD (SHELXL COMMAND)
          CASE (197)
C * IS = 198: XNPD RECORD (SHELXL COMMAND))
          CASE (198)
C * IS = 201: DANG RECORD
          CASE (201)
            IGBL(8) = 2
C * IS = 207: PAIR RECORD
          CASE (207)
          CASE DEFAULT
            RETURN
        END SELECT
        IS = -4
      END IF
      RETURN
99999 FORMAT (/, ':: Loaded Data Set: ', A, /)
      END SUBROUTINE PLA383
 
      SUBROUTINE PLA384
C * TEST FOR INORGANIC/ORGANIC/METALORGANIC
      USE parameters
      USE atomdata
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: NORGA
      INTEGER :: NORGB
      INTEGER :: NORGC
      NORGA    =  0
      NORGB    =  0
      NORGC    =  0
      IPR(325) = -1
      DO I = 1, IAN
        IF (IEN(I) == 2) THEN
          NORGA = 1
C * H/D/HW
        ELSE IF (IEN(I) ==  1 .OR. IEN(I) == 33 .OR.
     1    IEN(I) == 113) THEN
          NORGB = 1
C * F
        ELSE IF (IEN(I) == 38) THEN
          NORGB = 1
C * METAL
        ELSE IF (IATPR(IEN(I)) > 0) THEN
          NORGC = 1
        END IF
      END DO
      IF (NORGA + NORGB == 2) THEN
        IPR(325) = NORGC
C * TEST FOR _publ_requested_category 'FI,CI,OI'
        IF (IGBL(99) /= 1) IGBL(97) = 1
      END IF
      RETURN
      END SUBROUTINE PLA384
 
      SUBROUTINE PLA385 (IMODE)
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: NB
      INTEGER :: NN
      INTEGER :: N12
      INTEGER :: JEL
      INTEGER :: MRK
      INTEGER :: NMX
      INTEGER :: NSTP
      INTEGER :: NBCD
      INTEGER :: NELM
      INTEGER :: MARK
      INTEGER :: MODE
      INTEGER :: IMODE
      INTEGER, DIMENSION(NP10) :: IZ
      REAL :: X1
      REAL :: X2
      REAL :: Y1
      REAL :: Y2
      REAL :: Z1
      REAL :: FP
      REAL :: WL
      REAL :: WLB
      REAL :: WLE
      REAL :: SGN
      REAL :: FPP
      REAL :: DWL
      REAL :: FMX
      REAL :: WDF
      REAL :: XMU
      REAL :: FMUM
      REAL :: HRTM
      REAL :: VRTH
      REAL :: VRTM
      REAL :: XMARK
      REAL :: SCALEM
      REAL :: SCALEV
      PAGET = 'ANOM'
      IF (IGBL(7) == 1) THEN
        CLOSE (UNIT = LU7, IOSTAT = IOST)
      END IF
      OPEN (UNIT = LU7, FILE = 'ANOM_Brennan_Cowan.lis',
     1  STATUS = 'UNKNOWN')
      IGBL(7) = 1
      CALL PLA262(-2)
      MODE    = IMODE
      IGBL(6) = 33
      IWIN    = IGBL(25) * IGBL(32)
C * DETERMINE AND PLOT F', F'' AND MU-VALUES
C * MODE = 1 - ANOM (PLOT)
C * MODE = 2 - MU   (PLOT)
C * GENERAL INSTRUCTION LOOP
      DO
        FP    = 0.0
        FPP   = 0.0
        XMU   = 0.0
        N12   = 0
        IZ(1) = 0
        VRTM  = VERT - 1.0
        HRTM  = HORS - 1.0
        VRTH  = VRTM / 2.0
C * GET ATOM TYPE WHEN SPECIFIED
        IF (IPR(220) == 2) THEN
          DO I = 1, 27
C * QUIT LOOP WHEN NOT A..Z
            IF (I == 27) GO TO 20
            IF (IFL(2)(1:1) == CHAR (ICHAR ('A') + I - 1)) THEN
              N12 = I * 100
              IF (IFL(2)(2:2) /= ' ') THEN
                DO J = 1, 27
C * QUIT LOOP WHEN NOT A..Z
                  IF (J == 27) GO TO 20
                  IF (IFL(2)(2:2) == CHAR (ICHAR ('A') + J - 1)) THEN
                    N12 = N12 + J
                    EXIT
                  END IF
                END DO
              END IF
              DO K = 1, NP9 + 1
C * QUIT WHEN ELEMENT NOT IN RANGE H..U (1..92)
                IF (K == NP9 + 1) GO TO 20
                IF (IEL(K) == N12) THEN
                  IZ(1) = IATNR(K)
                  GO TO 10
                END IF
              END DO
            END IF
          END DO
        END IF
C * GET WAVELENGTH
   10   IF (IPR(221) == 1) THEN
          IF (IZ(1) /= 0) THEN
            CALL PLA386 (IZ(1), FN(1), FP, FPP, XMU, LU6)
            CALL GEN020 (-1, IFL(2), 2, 2)
            WRITE (SBCD, 99999, IOSTAT = IOST) IZ(1), IFL(2)(1:2),
     1        FN(1), FP, FPP, XMU, CHAR (0)
            WRITE (LU6, 99998, IOSTAT = IOST) SBCD(1:76)
C * LOOP OVER ALL ELEMENTS FOR THIS WAVELENGTH
          ELSE
            M    = 0
            FMX  = 0.0
            FMUM = 0.0
            JEL = 0
            WRITE (LU6, 99992)
            REWIND (UNIT = LU7, IOSTAT= IOST)
            WRITE (LU7, 99992)
            DO I = 1, 92
              IZ(1) = I
              DO J = 1, NP9
                IF (IATNR(J) == IZ(1)) THEN
                  JEL = J
                  EXIT
                ENDIF
              END DO
              CALL PLA386 (IZ(1), FN(1), FP, FPP, XMU, 0)
              WRITE (SBCD, 99999, IOSTAT = IOST) I, ELB(JEL), FN(1),
     1          FP, FPP, XMU, CHAR (0)
              WRITE (LU6, 99998, IOSTAT = IOST) SBCD(1:76)
              WRITE (LU7, 99998, IOSTAT = IOST) SBCD(1:76)
              VOID(M + 1) = FLOAT (JEL)
              VOID(M + 2) = FP
              VOID(M + 3) = FPP
              VOID(M + 4) = XMU
              M           = M + 4
              FMX         = MAX (FMX, ABS (FP), FPP)
              FMUM        = MAX (FMUM, XMU)
            END DO
C * PLOT f',f" & mu of elements 1:92 for give wavelength
            IF (IWIN /= 0) THEN
              SCALEV   = (VRTH - 1.0) / FMX
              SCALEM   = (VERT - 3.0) / FMUM
              IF (MODE == 1) THEN
                WRITE (BCD, 99994, IOSTAT = IOST) FN(1)
              ELSE
                WRITE (BCD, 99993, IOSTAT = IOST) FN(1)
              END IF
              CALL GGIP (HORS, VERT, 0.0, 1)
              CALL PLA439 (0.0, BCD, 35, 0.8, 4, 8, 1.0, VERT - 1.2)
              CALL PLA439 (0.0, BCD, 35, 0.8, 2, 8, 0.9, VERT - 1.3)
              CALL PLA110 (HORS, VERT, -1)
C * MOVE TO NEW ORIGIN
              X1 = 1.0
C * ANOM f',f'' PLOT
              IF (MODE == 1) THEN
                Y1 = VRTH
C * ANOM Mu PLOT
              ELSE IF (MODE == 2) THEN
                Y1 = 1.0
              END IF
              Z1 = 0.0
              CALL GGIP (X1, Y1, Z1, -3)
              CALL GGIP (0.0,  0.0, 0.0, 3)
              CALL GGIP (HRTM, 0.0, 0.0, 2)
              CALL GGIP (0.0,  0.0, 0.0, 3)
              IF (MODE == 1) THEN
                CALL PLA439 (0.0,
     1          'S.Brennan&P.L.Cowan(1992).Rev.Sci.Instr.,63,850-853',
     2          51, 0.30, 1, 1, 1.0, VRTH - 1.0)
                CALL PLA439 (0.0, 'o = f''',   6, 0.3, 1, 1, 1.0,
     1                       VRTH - 3.0)
                CALL PLA439 (0.0, 'x = f''''', 7, 0.3, 1, 1, 1.0,
     1                       VRTH - 4.0)
                DO I = -INT(FMX), INT (FMX), 1
                  CALL GGIP (HRTM,      I * SCALEV, 0.0, 3)
                  CALL GGIP (HRTM -0.2, I * SCALEV, 0.0, 2)
                END DO
 
              END IF
              DO I = 1, 92
                X1 = I * (HRTM - 0.5) / 92
                JEL = NINT (VOID((I - 1) * 4 + 1))
                IF (MODE == 1) THEN
                  Y1 = VOID((I - 1) * 4 + 2) * SCALEV
                  CALL PLA439 (-90.0, 'o '//ELB(JEL), 4, 0.2, 1, 1,
     1                X1 - 0.2, Y1)
                  Y1 = VOID((I - 1) * 4 + 3) * SCALEV
                  CALL PLA439 (90.0, 'x '//ELB(JEL), 4, 0.2, 1, 1, X1,
     1              Y1)
                ELSE IF (MODE == 2) THEN
                  Y1 = VOID((I - 1) * 4 + 4) * SCALEM
                  CALL PLA439 (90.0, 'x '//ELB(JEL), 4, 0.2, 1, 1, X1,
     1              Y1)
                END IF
              END DO
            END IF
          END IF
C * PLOT f' &  f'' as a function of Lambda for elements in CIF
        ELSE IF (IPR(221) == 0) THEN
          IF (IPR(220) == 1) THEN
            NELM = 0
            DO I = 1, IAN
              N = IATNR(IEN(I))
              IF (N > 6) THEN
                NELM = NELM + 1
                IFL(NELM + 1) = LMT(I, 1)
                IZ(NELM)      = N
              END IF
            END DO
            IF (NELM == 0) GO TO 20
          ELSE
            NELM = 1
          ENDIF
          N    = 0
          FMX  = 0.0
          FMUM = 0.0
          WLB  = 2.0
          WLE  = 0.1
          WDF  = WLB - WLE
          MRK  = NINT (WDF * 10)
          NSTP = 500
          DWL  = WDF / NSTP
          DO J = 1, NELM
            WL = WLB + DWL
            DO I = 1, NSTP + 1
              WL = WL - DWL
              CALL PLA386 (IZ(J), WL, FP, FPP, XMU, 0)
              VOID(N + 1) = WL
              VOID(N + 2) = FP
              VOID(N + 3) = FPP
              VOID(N + 4) = XMU
              N           = N + 4
              FMX         = MAX (FMX, ABS (FP), FPP)
              FMUM        = MAX (FMUM, XMU)
            END DO
          END DO
          SCALEV   = VRTH / FMX
          SCALEM   = (VERT - 3.0) / FMUM
          IF (MODE == 1) THEN
            XMARK = 1.0
            NMX   = INT (FMX / XMARK)
            IF (NMX < 3) THEN
              XMARK = XMARK / 2.0
              NMX   = INT (FMX / XMARK)
            END IF
          ELSE IF (MODE == 2) THEN
            NN = INT (LOG (FMUM) / LOG (10.0))
            MARK = 10**NN
            NMX  = INT (FMUM / MARK)
            IF (NMX < 3) THEN
              MARK = MARK / 2
              NMX  = INT (FMUM / MARK)
            END IF
          ENDIF
          IF (IWIN /= 0) THEN
            IF (MODE == 1) THEN
              NBCD = 21
              BCD(1:NBCD) = 'Anomalous Dispersion'//CHAR (0)
            ELSE
              NBCD = 23
              BCD(1:NBCD) = 'Mu-value versus Lambda'//CHAR (0)
            END IF
            CALL GGIP (HORS, VERT, 0.0, 1)
            CALL PLA439 (0.0, BCD, NBCD, 1.2, 4, 8, 3.0, VERT - 1.7)
            CALL PLA439 (0.0, BCD, NBCD, 1.2, 2, 8, 2.9, VERT - 1.8)
            CALL PLA110 (HORS, VERT, -1)
C * MOVE TO NEW ORIGIN
            X1 = 1.0
            IF (MODE == 1) THEN
              Y1 = VRTH
            ELSE IF (MODE == 2) THEN
              Y1 = 1.0
            END IF
            Z1 = 0.0
            CALL GGIP (X1, Y1, Z1, -3)
C * ELECTRON SCALE
            IF (MODE == 1) THEN
              SGN = 1.0
              DO J = 1, 2
                IF (J == 2) SGN = -1.0
                X1 = 0.0
                Y1 = 0.0
                CALL GGIP (X1, Y1, Z1, 3)
                DO I = 1, NMX
                  Y1 = I * XMARK * SCALEV * SGN
                  CALL GGIP (X1, Y1, Z1, 2)
                  X2 = 0.2
                  CALL GGIP (X2, Y1, Z1, 2)
                  WRITE (NQ1, 99996, IOSTAT = IOST) I * XMARK * SGN
                  CALL PLA439 (0.0, NQ1, 6, 0.2, 1, 1, 0.1, Y1 + 0.1)
                  CALL GGIP (X1, Y1, Z1, 3)
                END DO
                Y1 = VRTH * SGN
                CALL GGIP (X1, Y1, Z1, 2)
                Y1 = 0.0
                CALL GGIP (X1, Y1, Z1, 3)
              END DO
            ELSE
              DO I = 1, NMX
                X1 = 0.0
                Y1 = I * MARK * SCALEM
                CALL GGIP (X1, Y1, 0.0, 2)
                X2 = 0.2
                CALL GGIP (X2, Y1, 0.0, 2)
                WRITE (NQ1, 99995, IOSTAT = IOST) I * MARK
                CALL PLA439 (0.0, NQ1, 6, 0.2, 1, 1, 0.1, Y1 + 0.1)
                CALL GGIP (X1, Y1, Z1, 3)
              END DO
              Y1 = VERT - 2.0
              CALL GGIP (X1, Y1, 0.0, 2)
              Y1 = 0.0
              CALL GGIP (X1, Y1, 0.0, 3)
            END IF
C * ANGSTROM SCALE
            X1 = 0.0
            Y1 = 0.0
            X2 = WLB
            WRITE (NQ1, 99997, IOSTAT = IOST) WLB
            CALL PLA439 (0.0, NQ1, 3, 0.2, 1, 1, 0.1, -0.3)
            CALL GGIP (X1, Y1, Z1, 3)
            DO I = 1, MRK
              X1 = I * HRTM / MRK
              CALL GGIP (X1, Y1, Z1, 2)
              Y2 = Y1 - 0.2
              CALL GGIP (X1, Y2, Z1, 2)
              IF (I < MRK) THEN
                WLB = WLB - 0.1
                WRITE (NQ1, 99997, IOSTAT = IOST) WLB
                CALL PLA439 (0.0, NQ1, 3, 0.2, 1, 1, X1 + 0.1, -0.3)
              END IF
              CALL GGIP (X1, Y1, Z1, 3)
            END DO
            DO I = 1, 5
              X1 = HRTM * (1.0 - ((STWL(I) - WLE) / WDF))
              Y1 = 0.5
              CALL PLA439 (90.0, CSTWL(I), 4, 0.30, 1, 2, X1 + 0.15,
     1                     Y1 + 0.1)
              CALL GGIP (0.0, 5.0, 0.0, 0)
              CALL GGIP (X1, 0.0, 0.0, 3)
              CALL GGIP (X1, Y1, 0.0, 2)
              CALL GGIP (0.0, 0.0, 0.0, 3)
            END DO
            CALL PLA439 (0.0, 'Angstrom', 8, 0.25, 1, 1, HRTM - 1.8,
     1        -0.8)
            NB = 0
            DO K = 1, NELM
C * DISPLAY ELEMENT-NAME
              NQ2 = IFL(K + 1)(1:2)
              IF (NQ2(1:1) /= ' ') CALL GEN020 (-1, NQ2, 2, 2)
              CALL PLA439 (0.0, NQ2, 2, 0.3, K, 1, HRTM - 1.0,
     1            2.0 + K * 0.4)
              IF (MODE == 1) THEN
C * DISPLAY f'
                X1 = 0.0
                Y1 = VOID(NB + 2) * SCALEV
                CALL PLA439 (0.0, 'f''', 2, 0.3, K, 1, 1.4, Y1 - 1.0)
                CALL GGIP (0.0, FLOAT (K), 0.0, 0)
                CALL GGIP (X1, Y1, Z1, 3)
                DO I = 2, NSTP + 1
                  X1 = HRTM * (I - 1) / NSTP
                  Y1 = VOID(NB + I * 4 + 2) * SCALEV
                  CALL GGIP (X1, Y1, Z1, 2)
                END DO
                X1 = 0.0
                Y1 = 0.0
                CALL GGIP (X1, Y1, Z1, 3)
C * DISPLAY f''
                X1 = 0.0
                Y1 = VOID(NB + 3) * SCALEV
                CALL PLA439 (0.0, 'f''''', 3, 0.3, K, 1, 1.4, Y1 )
                CALL GGIP (0.0, FLOAT (K), 0.0, 0)
                CALL GGIP (X1, Y1, Z1, 3)
                DO I = 2, NSTP + 1
                  X1 = HRTM * (I - 1) / NSTP
                  Y1 = VOID(NB + I * 4 + 3) * SCALEV
                  CALL GGIP (X1, Y1, Z1, 2)
                END DO
              ELSE
                X1 = 0.0
                Y1 = 0.0
                CALL GGIP (X1, Y1, Z1, 3)
C * DISPLAY MU
                X1 = 0.0
                Y1 = VOID(NB + 4) * SCALEM
                CALL GGIP (0.0, FLOAT (K), 0.0, 0)
                CALL GGIP (X1, Y1, Z1, 3)
                DO I = 2, NSTP + 1
                  X1 = HRTM * (I - 1) / NSTP
                  Y1 = VOID(NB + I * 4 + 4) * SCALEM
                  CALL GGIP (X1, Y1, Z1, 2)
                END DO
              END IF
              CALL GGIP (0.0, 0.0, 0.0, 3)
              NB = NB + (NSTP + 1) * 4
            END DO
          END IF
        END IF
C * CHECK FOR 'WHAT NEXT ?'
   20   IF (IWIN /= 0) THEN
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          IF (IGGT(1:4) /= 'PLOT') THEN
            CALL GEN072 (IGGT, IFL, FN, KL, KN, 0, LU6, 1,
     1        1, 80, 7, NP17)
            IPR(220) = KL
            IPR(221) = KN
            IF (IFL(1)(1:4) == 'ANOM') THEN
              MODE  = 1
              IZ(1) = 0
            ELSE IF (IFL(1)(1:2) == 'MU') THEN
              MODE  = 2
              IZ(1) = 0
            ELSE IF (IFL(1)(1:3) == 'END') THEN
              EXIT
            ELSE IF (IFL(1)(1:4) == 'EXIT') THEN
              EXIT
            END IF
          END IF
        ELSE
          IFL(1) = 'END'
          EXIT
        END IF
      END DO
      IF (IGBL(7) /= 0) THEN
        WRITE (LU6, 99991)
        IGBL(7) = 0
      END IF
      IGBL(6) = 10
      RETURN
99999 FORMAT ('Element', I3, ', ', A, ', WaveLength:', F8.5, ', f'':',
     1  F8.4, ', f":', F8.4, ', Mu:', F10.1, A)
99998 FORMAT (A)
99997 FORMAT (F3.1)
99996 FORMAT (F6.2)
99995 FORMAT (I6)
99994 FORMAT ('f'' and f" at Lambda =', F8.5, ' Ang.')
99993 FORMAT ('Mu-Values at Lambda =', F8.5, ' Ang.')
99992 FORMAT (/, 'f'', f" and Mu values based on:', /,
     1 'S. Brennan & P.L. Cowan (1992). Rev.Sci.Instr., 63, 850-853',
     2 /)
99991 FORMAT (/, 'Listing output on File: ANOM_Brennan_Cowan.lis', /)
      END SUBROUTINE PLA385
 
