     4   0.674899995D0,   0.637000024D0,  0.303943723D0,  0.295067102D0,
     5   0.261255294D0,   0.206171408D0,  0.163234457D0, 8.313610405D-2,
     6  7.693891972D-2,  4.046359286D-2, 2.518509701D-2, 1.840208657D-2/
C * DATA FOR TH ELEMENT #90
      DATA (BINDNRG(I, 90), I = 1, 24)/
     1    109.650902D0,    20.4720993D0,   19.6932011D0,   16.3003006D0,
     2    5.18230009D0,    4.83039999D0,   4.04610014D0,   3.49079990D0,
     3    3.33200002D0,    1.32949996D0,   1.16820002D0,  0.967299998D0,
     4   0.714100003D0,   0.676400006D0,  0.344399989D0,  0.335200012D0,
     5   0.290199995D0,   0.229399994D0,  0.181800008D0, 9.430000186d-2,
     6  8.789999783D-2,  5.950000137D-2, 4.899999872D-2, 4.300000146D-2/
C * DATA FOR PA ELEMENT #91
      DATA (BINDNRG(I, 91), I = 1, 24)/
     1    112.601402D0,    21.1045990D0,   20.3136997D0,   16.7331009D0,
     2    5.36689997D0,    5.00090027D0,   4.17379999D0,   3.61119986D0,
     3    3.44179988D0,    1.38710010D0,   1.22430003D0,   1.00670004D0,
     4   0.743399978D0,   0.708199978D0,  0.371199995D0,  0.359499991D0,
     5   0.309599996D0,   0.233623788D0,  0.183050051D0, 9.667889029D-2,
     6  8.924079686D-2,  4.545853287D-2, 2.854512073D-2, 2.032056637D-2/
C * DATA FOR U  ELEMENT #92
      DATA (BINDNRG(I, 92), I = 1, 24)/
     1    115.606102D0,    21.7574005D0,   20.9475994D0,   17.1662998D0,
     2    5.54799986D0,    5.18219995D0,   4.30340004D0,   3.72760010D0,
     3    3.55169988D0,    1.44080007D0,   1.27259994D0,   1.04489994D0,
     4   0.780399978D0,   0.737699986D0,  0.391299993D0,  0.380899996D0,
     5   0.323700011D0,   0.259299994D0,  0.195100009D0,  0.104999997D0,
     6  9.629999846D-2,  7.069999725D-2, 4.230000079D-2, 3.229999915D-2/
      FTOMU            = 0.420803153D+8
      BARNSTOELECTRONS = 1.43110541D-8 ! barns to f"
      AU               = 2.80022D+7
      KEVPERRYD        = 0.02721D0
      FINEPI           = 0.6942325D+1
      PI               = 3.1415927D0
      INVFINESTRUCT    = 1.37036D+2
      IF (IZED > 0 .AND. IZED < 93 .AND. WAVELENGTH > 0.0) THEN
C * Conversion E = hc/lambda = 41.3566733*299.792458/lambda
        ENERGY = 12398.52D0 / DBLE (WAVELENGTH)
C * bind_nrg(1) = K in keV
C * bind_nrg(2) = LI "  "
C * bind_nrg(5) = M1 "  "
        NEDGE = NORB(IZED)
        DO I = 1, NEDGE
          ABSEDGE(I) = SNGL (BINDNRG(I, IZED) * 1000.0D0)
        END DO
        IF (LU > 0) THEN
          WRITE (LU, 99971)
          IF (NEDGE == 1) THEN
            WRITE (LU, 99972, IOSTAT = IOST) ABSEDGE(1)
          ELSE IF (NEDGE == 2) THEN
            WRITE (LU, 99973, IOSTAT = IOST) (ABSEDGE(I), I = 1, 2)
          ELSE IF (NEDGE .eq. 3) THEN
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99974, IOSTAT = IOST) (ABSEDGE(I), I = 1, 3)
            WRITE (LU, 99975, IOSTAT = IOST) KA2
          ELSE IF (NEDGE == 4) THEN
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99977, IOSTAT = IOST) KA1, KA2
          ELSE IF (NEDGE == 5) THEN
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99979, IOSTAT = IOST) KA1, KA2
            WRITE (LU, 99980, IOSTAT = IOST) ABSEDGE(5)
          ELSE IF (NEDGE == 6) THEN
            KB3 = ABSEDGE(1) - ABSEDGE(6)
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99982, IOSTAT = IOST) KA1, KA2, KB3
            WRITE (LU, 99983, IOSTAT = IOST) (ABSEDGE(I), I = 5, 6)
          ELSE IF (NEDGE == 7) THEN
            KB1 = ABSEDGE(1) - ABSEDGE(7)
            KB3 = ABSEDGE(1) - ABSEDGE(6)
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99995, IOSTAT = IOST) KA1, KA2, KB1, KB3
            WRITE (LU, 99986, IOSTAT = IOST) (ABSEDGE(I), I = 5, 7)
          ELSE IF (NEDGE == 8) THEN
            LB1 = ABSEDGE(2) - ABSEDGE(8)
            KB1 = ABSEDGE(1) - ABSEDGE(7)
            KB3 = ABSEDGE(1) - ABSEDGE(6)
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99995, IOSTAT = IOST) KA1, KA2, KB1, KB3
            WRITE (LU, 99989, IOSTAT = IOST) (ABSEDGE(I), I = 5, 8), LB1
          ELSE IF ((NEDGE == 9) .AND. (NEDGE < 14)) THEN
            LB1 = ABSEDGE(2) - ABSEDGE(8)
            LA1 = ABSEDGE(3) - ABSEDGE(9)
            KB1 = ABSEDGE(1) - ABSEDGE(7)
            KB3 = ABSEDGE(1) - ABSEDGE(6)
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99995, IOSTAT = IOST) KA1, KA2, KB1, KB3
            WRITE (LU, 99996, IOSTAT = IOST) (ABSEDGE(I), I = 5, 9)
            WRITE (LU, 99993, IOSTAT = IOST) LB1, LA1
C * N_EDGE >13
          ELSE
            KA1 = ABSEDGE(1) - ABSEDGE(4)
            KA2 = ABSEDGE(1) - ABSEDGE(3)
            KB1 = ABSEDGE(1) - ABSEDGE(7)
            KB3 = ABSEDGE(1) - ABSEDGE(6)
            LB1 = ABSEDGE(3) - ABSEDGE(8)
            LB2 = ABSEDGE(4) - ABSEDGE(14)
            LB3 = ABSEDGE(2) - ABSEDGE(7)
            LB4 = ABSEDGE(2) - ABSEDGE(6)
            LA1 = ABSEDGE(4) - ABSEDGE(9)
            LA2 = ABSEDGE(4) - ABSEDGE(8)
            LG1 = ABSEDGE(3) - ABSEDGE(13)
            LG3 = ABSEDGE(2) - ABSEDGE(12)
            LI  = ABSEDGE(4) - ABSEDGE(5)
            LE  = ABSEDGE(3) - ABSEDGE(5)
            WRITE (LU, 99994, IOSTAT = IOST) (ABSEDGE(I), I = 1, 4)
            WRITE (LU, 99995, IOSTAT = IOST) KA1, KA2, KB1, KB3
            WRITE (LU, 99996, IOSTAT = IOST) (ABSEDGE(I), I = 5, 9)
            WRITE (LU, 99997, IOSTAT = IOST)
     1        LB1, LB2, LB3, LB4, LA1, LA2
            WRITE (LU, 99998, IOSTAT = IOST) (ABSEDGE(I), I = 10, 14)
            WRITE (LU, 99999, IOSTAT = IOST) LG1, LG3, LI, LE
          END IF
          WRITE (LU, 99971)
        END IF
C * LOAD DATA FOR ELEMENT NUMBER IZED FROM XNRG
        IF (IZED > 2) THEN
          DO J = 1, NORB(IZED)
            DO K = 1, 5
              YNRG(J, K) = XNRG(K, 1, 1)
            END DO
            DO K = 6, NPARMS(IZED, J)
              YNRG (J, K) = XNRG(K - 5, J, IZED)
            END DO
          END DO
        END IF
        P1         = DLOG (ENERGY / 1000.0D0)
        P2         = P1 * P1
        P3         = P1 * P2
C * Change to keV
        DENERGY    = ENERGY / 1000.0D0
        DLOGENERGY = DLOG (DENERGY)
        DENERGYAU  = DENERGY / KEVPERRYD
        DSUMFP     = 0.D0
        DSUMFPP    = 0.D0
C * RELCOR is the relativistic correction term
C * BARNS_TO ELECTRONS[is a constant that converts the cross section in
C * barns/atom into a cross-section in electrons/atom which is the same
C * as f''. It is calculated as:
C *   1/(10^8 [b/A^2]*2* rsube=2.8179^-5 * hc=12398.52)
        IF (IZED == 1) THEN
C * Hydrogen
          IF (ENERGY >= 14.0D-3) THEN
            FPP = SNGL (BARNSTOELECTRONS * ENERGY *
     1            DEXP (2.44964D0 - 3.34953D0 * P1 - 0.047137D0 * P2
     2                           + 0.0070996D0 * P3))
            FP  = 0.0
          END IF
        ELSE IF (IZED == 2) THEN
C * Helium
          IF (ENERGY >= 25.0D-3) then
            FPP = SNGL (BARNSTOELECTRONS * ENERGY *
     1            DEXP (6.06488D0 - 3.2905D0 * P1 - 0.107256D0 * P2
     2                           + 0.0144465D0 * P3))
            FP  = 0.0
          END IF
        ELSE
C * MAIN LOOP THROUGH THE ORBITALS
          DO IRB = 1, NORB(IZED)
            DFPORB      = 0.D0
            DFPCORR     = 0.D0
            DFPPORB     = 0.D0
            DXSECTBARNS = 0.D0
            DBINDNRGAU  = BINDNRG(IRB, IZED) / KEVPERRYD
            IF (NPARMS(IZED, IRB) == 11) THEN
              DXSECTEDGEAU = XSC(IRB, 11, IZED) / AU
            END IF
C * also copy subset into second array
            DO I = 6, 10
              DXSECTINT(I - 5) = XSC(IRB, I, IZED) / AU
              DNRGINT(I - 5)   = YNRG(IRB, I)
            END DO
C * the sorting routine messes up subsequent calls with same energy
C * so copy to second array before sorting.
            DO I = 1, NPARMS(IZED, IRB)
              DXSECTS(I) = XSC(IRB, I, IZED)
              DNRGS(I)   = YNRG(IRB, I)
            END DO
            CALL GEN150 (NPARMS(IZED, IRB), DNRGS, DXSECTS)
            CALL GEN150 (5, DNRGINT, DXSECTINT)
C * convert to log of energy, xsect
            DLOGNRG(11)   = 0.0D0
            DLOGXSECT(11) = 0.0D0
            DO I = 1, NPARMS(IZED, IRB)
              DLOGNRG(I) = DLOG (DNRGS(I))
              IF (DXSECTS(I) == 0.0D0) THEN
                DLOGXSECT(I) = 0.0D0
              ELSE
                DLOGXSECT(I) = DLOG (DXSECTS(I))
              END IF
            END DO
            IF (BINDNRG(IRB, IZED) <= DENERGY) THEN
              IZERO = 0
              I     = 1
              DO WHILE(DLOGXSECT(I) == 0.0D0)
                IZERO = IZERO + 1
                I     = I + 1
              END DO
              INXSECT     = NPARMS(IZED, IRB) - IZERO
              IZERO       = IZERO + 1
              DXSECTBARNS = GEN149 (DLOGENERGY, INXSECT,
     1                      DLOGNRG(IZERO), DLOGXSECT(IZERO))
              DXSECTBARNS = DEXP (DXSECTBARNS) / AU
              DFPPORB     = INVFINESTRUCT * DXSECTBARNS
     1                    * DENERGYAU / (4.0D0 * PI)
              DVAR        = DENERGYAU - DBINDNRGAU
              IF (DVAR == 0.0D0) DVAR = 1.0D0
              DFPCORR = -0.5D0 * DXSECTBARNS * DENERGYAU * FINEPI
     1                  * DLOG ((DENERGYAU + DBINDNRGAU) / DVAR)
            END IF
            IF (BINDNRG(IRB, IZED) > DENERGY .AND.
     1        IFUNTYP(IZED, IRB) == 0) THEN
                DFPORB  = PLA387 (3) * FINEPI
                DFPCORR = 0.5D0 * DXSECTEDGEAU * DBINDNRGAU**2
     1                  * DLOG ((-DBINDNRGAU + DENERGYAU) /
     2                      (-DBINDNRGAU - DENERGYAU)) /
     3                      DENERGYAU * FINEPI
            ELSE
              DFPORB = PLA387 (IFUNTYP(IZED, IRB)) * FINEPI
            END IF
            DSUMFP  = DSUMFP  + DFPORB + DFPCORR
            DSUMFPP = DSUMFPP + DFPPORB
          END DO
C * this is the end of the loop over orbits
          FPP = SNGL(DSUMFPP)
C * Kissel and Pratt give better corrections.  The relativistic correction
C * that Ludwig used is (5/3)(E_tot/mc^2).  Kissel and Pratt say that this
C * should be simply (E_tot/mc^2), but their correction (XKPCOR) apparently
C * takes this into account.  So we can use the old RELCOR and simply add
C * the (energy independent) XKPCOR term:
          FP = SNGL (DSUMFP - RELCOR(IZED) + XKPCOR(IZED))
        END IF
C * Calculate elastic and compton cross-sections (in electrons/atom)
C * BARNSTOELECTRONS is a constant that converts the cross section in
C * barns/atom into a cross-section in electrons/atom which is the same
C * as f''. It is calculated as
C * BARNSTOELECTRONS= 1/( 10^8 [b/A^2]*2* rsube=2.8179^-5* hc=12398.52)
        RAY  = BARNSTOELECTRONS * ENERGY *
     1         DEXP (DRAY(1, IZED) + DRAY(2, IZED) * P1 +
     2         DRAY(3, IZED) * P2 + DRAY(4, IZED) * P3)
        COMP = BARNSTOELECTRONS * ENERGY *
     1         DEXP (DCMP(1, IZED) + DCMP(2, IZED) * P1 +
     2         DCMP(3, IZED) * P2 + DCMP(4, IZED) * P3)
        MU   = SNGL (1.66043D0 * FTOMU * (DBLE (FPP) + RAY + COMP) /
     1         ENERGY)
      END IF
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT ('Lg1:',f8.1,' Lg3:',f8.1,' Li: ',f8.1,' Le: ',f8.1)
99998 FORMAT ('N1: ',f8.1,' N2: ',f8.1,' N3: ',f8.1,' N4: ',f8.1,
     1 ' N5: ',f8.1)
99997 FORMAT ('Lb1:',f8.1,' Lb2:',f8.1,' Lb3:',f8.1,' Lb4:',f8.1,
     1 ' La1:',f8.1,' La2:',f9.1)
99996 FORMAT ('M1: ',f8.1,' M2: ',f8.1,' M3: ',f8.1,' M4: ',f8.1,
     1 ' M5: ',f8.1)
99995 FORMAT ('Ka1:',f8.1,' Ka2:',f8.1,' Kb1:',f8.1,' Kb3:',f8.1)
99994 FORMAT ('K:  ',f8.1,' L1: ',f8.1,' L2: ',f8.1,' L3: ',f8.1)
99993 FORMAT ('Lb1:',f8.1,' La1:',f8.1)
99989 FORMAT ('M1: ',f8.1,' M2: ',f8.1,' M3: ',f8.1,' M4: ',f8.1,
     1 ' Lb1:',f8.1)
99986 FORMAT ('M1: ',f8.1,' M2: ',f8.1,' M3: ',f8.1)
99983 FORMAT ('M1: ',f8.1,' M2: ',f8.1)
99982 FORMAT ('Ka1:',f8.1,' Ka2:',f8.1,' Kb3:',f8.1)
99980 FORMAT ('M1: ',f8.1)
99979 FORMAT ('Ka1:',f8.1,' Ka2:',f8.1)
99977 FORMAT ('Ka1:',f8.1,' Ka2:',f8.1)
99975 FORMAT ('Ka2:',f8.1)
99974 FORMAT ('K:  ',f8.1,' L1: ',f8.1,' L2: ',f8.1)
99973 FORMAT ('K:  ',f8.1,' L1: ',f8.1)
99972 FORMAT ('K-edge: ',f8.1)
99971 FORMAT (/)
      END SUBROUTINE PLA386
 
      DOUBLE PRECISION FUNCTION PLA387 (MODE)
      USE danom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IP
      INTEGER :: MODE
      DOUBLE PRECISION :: A
      DOUBLE PRECISION :: B
      DOUBLE PRECISION :: C
      DOUBLE PRECISION :: D
      DOUBLE PRECISION :: E
      DOUBLE PRECISION :: F
      DOUBLE PRECISION :: P1
      DOUBLE PRECISION :: P2
      DOUBLE PRECISION :: P3
      DOUBLE PRECISION :: P4
      DOUBLE PRECISION :: DCONST
      DOUBLE PRECISION :: DP
      DOUBLE PRECISION :: SMALL
      DOUBLE PRECISION :: SIGMA
      DOUBLE PRECISION, DIMENSION(2) :: DX
      DOUBLE PRECISION, DIMENSION(3) :: DA
      DX(1) = 0.04691007703067D0
      DX(2) = 0.23076534494716D0
      DA(1) = 0.11846344252810D0
      DA(2) = 0.23931433524968D0
      DA(3) = 0.28444444444444D0
      SMALL = 1.0D-31
      A     = 0.d0
      DO I = 1, 5
        P1     = 0.5D0
        DCONST = 0.D0
        IP     = I
C * IP limited to 1,2,3
        IF (IP > 3) THEN
          IP     = 6 - IP
          DCONST = -1.D0
        END IF
        IF (IP /= 3) P1 = - DCONST + DSIGN (DX(IP), DCONST)
        P2 = P1 * P1
        P3 = P1 * P2
        P4 = P1 * P3
        B  = DXSECTINT(6 - I)
        C  = DENERGYAU
        D  = DBINDNRGAU
        E  = DXSECTBARNS
        F  = DXSECTEDGEAU
        SELECT CASE (MODE)
          CASE (0)
            DP = C**2 * P2 - D**2
            IF (DABS (DP) < 1.D-30) THEN
              SIGMA = B * D / P2
            ELSE
              SIGMA = (B * D**3 / P2 - D * E * C**2) / DP
            END IF
          CASE (1)
            SIGMA = 0.5D0 * D**3 * B /
     1              (DSQRT (P1) * (C**2 * P2 - D**2 * P1))
          CASE (2)
            IF (DABS (P1) < SMALL) THEN
              SIGMA = 0.0D0
            ELSE IF (C < SMALL) THEN
              SIGMA = 0.0D0
            ELSE IF (DABS (B - E) < 1.0D-30) THEN
              SIGMA = -2.0D0 * B * D / P3
            ELSE
              DP = P3 * C**2 - D**2 / P1
              IF (DABS (DP) < SMALL) THEN
                SIGMA = -2.0D0 * B * D / P3
              ELSE
                SIGMA = 2.0D0 * (B * D**3 / P4 - D * E * C**2) / DP
              END IF
            ENDIF
          CASE (3)
            SIGMA = D**3 * (B - F * P2) / (P2 * (P2 * C**2 - D**2))
        END SELECT
        A = A + DA(IP) * SIGMA
      END DO
      PLA387 = A
      END FUNCTION PLA387
 
      SUBROUTINE PLA390 (MODE, NTYP, NRET)
C * PRE-GEOM LSPL REQUESTS
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: MODE
      INTEGER :: NTYP
      INTEGER :: NRET
      INTEGER :: IENM
      INTEGER :: NIEN
      INTEGER :: NMAX
      INTEGER :: IXLBL
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: IJXLS
      INTEGER :: IATPI
      REAL :: VARDIST
      INTEGER, SAVE, DIMENSION(9, 25) :: IXLS
C * HANDLE PRE-CALC GEOMETRY REQUESTS
      IF (MODE == 1) THEN
        IF (IPR(145) < 25) THEN
          IPR(145)          = IPR(145) + 1
          IXLS(1, IPR(145)) = NTYP
          DO K = 2, 9
            IXLS(K, IPR(145)) = -1
          END DO
          IPR(146) = 1
          DO I = 2, IPR(220)
            CALL PLA046 (1, IFL(I), IENM, LBB, LBC, LBD, INQNR, JNQNR,
     1        NIEN)
            IF (NIEN < 0) THEN
              IF (IFL(I)(1:3) == 'DIS') THEN
                IPR(220) = - IPR(220)
                NRET = 2
                RETURN
              ELSE IF (IFL(I)(1:4) == 'WITH') THEN
                IPR(220) = - IPR(220)
                NRET = 2
                RETURN
              ELSE
C * UNSUITABLE ATOM LABEL ERROR
                NQ0    = IFL(I)(1:7)
                IPR(2) = 3
                NRET   = 3
                RETURN
              END IF
            END IF
            IPR(146) = IPR(146) + 1
            IF (IPR(146) > 9) THEN
              IPR(145) = IPR(145) + 1
              IPR(146) = 2
              DO K = 1, 9
                IXLS(K, IPR(145)) = -1
              END DO
            END IF
            IXLS(IPR(146), IPR(145)) = INQNR
          END DO
          WRITE (LU6, 99999, IOSTAT = IOST)
        END IF
C * LOAD USER SPECIFIED FITS, RINGS AND PLANES FROM XLS-SCRATCH
      ELSE
C * NUMBER OF ATOMS IN SYMMETRY EXPANDED LIST
        NMAX = IPR(39)
        N    = 0
        DO WHILE (N < IPR(145))
          N       = N + 1
          IPR(12) = 0
          NTYP    = IXLS(1, N)
          IF (NTYP >= 0) THEN
            DO I = 1, NMAX
              IATPI = NP1 + I
              IXLBL = LABA(I)
              J    = N
              K    = 1
              DO
                K = K + 1
                IF (K > 9) THEN
                  J = J + 1
                  IF (IXLS(1, J) > 0) THEN
                    EXIT
                  ELSE
                    K = 1
                    CYCLE
                  END IF
                END IF
                IJXLS = IXLS(K, J)
                IF (IJXLS >= 0) THEN
                  IF (ABS (IXLBL - IJXLS) == 0) THEN
                    IPR(12)                 = IPR(12) + 1
                    JR((J - N) * 8 + K - 1) = I
                    IATPI                   = I
                    EXIT
                  ELSE
                    CYCLE
                  END IF
                ELSE
                  EXIT
                END IF
              END DO
              IATP(I) = IATPI
            END DO
            IF (IPR(12) < NP7) THEN
              IF (NTYP == 0) THEN
                IF (IPR(12) >= 2) THEN
C * QUATERNION FIT
                  VARDIST = 999.0
                  CALL PLA442 (0, VARDIST)
                ELSE
                  WRITE (LU6, 99998, IOSTAT = IOST)
                END IF
              ELSE
                IF (IPR(12) >= 3) THEN
                  CALL PLA045 (NTYP)
                ELSE
                  WRITE (LU6, 99998, IOSTAT = IOST)
                END IF
              END IF
            ELSE
              WRITE (LU6, 99998, IOSTAT = IOST)
            END IF
          END IF
        END DO
      END IF
      RETURN
99999 FORMAT (':: LSPL/RING/FIT/LINE calculation will be included in ',
     1        'next CALC GEOM/INTRA run', /)
99998 FORMAT ('W: User-specified Ring/Plane/Fit/Line not accepted', /)
      END SUBROUTINE PLA390
 
      SUBROUTINE PLA391 (N)
      USE parameters
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
 
      CHARACTER(len=NP64) :: NQ
C * REMOVE '_$#'
      DO I = 1, N
        NQ = IFL(I)
        M  = INDEX (IFL(I), '_$')
        IF (M /= 0) IFL(I) = NQ(1:M - 1)
      END DO
      RETURN
      END SUBROUTINE PLA391
 
      SUBROUTINE PLA392 (N)
C * TEST/REMOVE '^' ISSUES
      USE parameters
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: IENM
      INTEGER :: NIEN
      DO I = 1, N
        M  = INDEX (IFL(I), '^')
        IF (M > 0) THEN
C * CHECK FOR ATOM LABELS CONTAINING '^'
          IF (IPR(768) .EQ. 0) THEN
            IFL(I)(M:M+1) = '  '
          ELSE
C * CHECK WHETHER THIS LABEL IS IN THE ATOM LIST, OTHERWISE REMOVE '^' PART
            CALL PLA046 (1, IFL(I), IENM, LBB, LBC, LBD, IDUM, JDUM,
     1        NIEN)
            IF (NIEN < 0) IFL(I)(M:M+1) = '  '
          END IF
        END IF
      END DO
      RETURN
      END SUBROUTINE PLA392
 
      SUBROUTINE PLA393 (M, C)
C * CREATE CIF-STYLE SYMMETRY CODE
      USE files
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: M
      INTEGER :: N
      INTEGER :: N0
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: M0
      INTEGER :: M1
      INTEGER :: M2
      INTEGER :: M3
      INTEGER :: IER
      INTEGER :: IDUM
      REAL :: XML
      CHARACTER(len=80) :: C
      CHARACTER(len=80) :: D
C * BLANK STRING C
      CALL GEN038 (C, 1, 80)
C * SPLIT-UP ARU-CODE INTO COMPONENTS
      CALL PLA455 (M, M0, M1, M2, M3, IDUM)
      SGX(4) = M1
      SGX(5) = M2
      SGX(6) = M3
C * GET SYMMETRY OPERATION
      CALL SGSM (20, D, SGX, M0, 0, IERR)
      N = INDEX (D, ' ')
C * CONVERT TO LOWER CASE
      CALL GEN020 (-1, D, 1, N)
      C(61 - N:61) = D(1:N)
      XML = M / 100
      CALL PLA273 (1, XML, N0, N1, N2, N3, IER)
      IF (IER == 0) THEN
        WRITE (C(62:80), 99999, IOSTAT = IOST)
     1    N0, N1 + 5, N2 + 5, N3 + 5
      ELSE
        WRITE (C(62:80), 99998, IOSTAT = IOST)
      END IF
      RETURN
99999 FORMAT ('=', I7,'_', 3I1, ' Check')
99998 FORMAT (12X, ' Check')
      END SUBROUTINE PLA393
 
      SUBROUTINE PLA394
C * (SOLVENT) ACCESSIBLE SURFACE AREA CALCULATION ROUTINE - SASA
C * LOOSELY BASED ON THE TOOL NONORTHOSA
C * T.DUREN ET Al. J. Phys. Chem C 2007, 111,15350-15356
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER, PARAMETER :: NP87 = 100000
      REAL, ALLOCATABLE, DIMENSION(:,:) :: X
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: NC
      INTEGER :: NS
      INTEGER :: NEL
      INTEGER :: NELA
      INTEGER :: NIEN
      INTEGER :: NADD
      INTEGER :: INEL
      INTEGER :: NSYML
      INTEGER :: ISEED
      INTEGER, DIMENSION(16) :: NCOUNT
      REAL :: PI
      REAL :: ST
      REAL :: TH
      REAL :: XQ
      REAL :: YQ
      REAL :: ZQ
      REAL :: CTH
      REAL :: RAD
      REAL :: PHI
      REAL :: DIFF
      REAL :: TEST
      REAL :: SFRAC
      REAL :: DIST2
      REAL :: PROBE
      REAL :: STRED
      REAL :: SJREAL
      REAL :: GEN006
      DOUBLE PRECISION :: GEN160
      REAL, DIMENSION(16) :: VDW
      CHARACTER(len=2) :: ELM
      CHARACTER(len=2), DIMENSION(16) :: ELEM
      ALLOCATE (X(NP87, 4))
C * INIT COUNT OF ATOMS PER ATOM TYPE
      CALL GEN097 (NCOUNT, 1, 16, 0)
      DO I = 1, 16
        ELEM(I) = '  '
      END DO
      ISEED = -52907
      PI    = RGBL(5) / 2.0
      NS    = IPR(743)
      PROBE = PAR(557)
      NSYML = IPR(255) * IPR(256) * IPR(257)
C * ELEMENT NUMBER COUNTER
      NEL   = 0
C * GET AND EXPAND COORDINATE SET TO FILL THE WHOLE UNIT CELL
      N = 0
      DO I = 1, IPR(37)
        NELA = 1
C * GET ELEMENT TYPES AND VAN DER WAALS RADII
        CALL GEN048 (-4, IFG(1, I), 15, NIEN)
        RAD = ABS (VDWR(IEN(NIEN + 1)))
        ELM = ELB(IEN(NIEN + 1))
        IF (NEL > 0) THEN
          DO K = 1, NEL
            IF (ELM == ELEM(K)) THEN
              INEL = K
              NELA = 0
              EXIT
            END IF
          END DO
        END IF
        IF (NELA == 1) THEN
          NEL       = NEL + 1
          INEL      = NEL
          ELEM(NEL) = ELM
          VDW(NEL)  = RAD
        END IF
C * COMPLETE UNITCELL CONTENT
        DO K = 1, 3
          SGY(K)     = XXO(I, K)
          SGY(K + 3) = 0.0
        END DO
        M = 0
        DO L = 1, NSYML
          CALL SGSM (3, ICL, SGY, L, 0, IERR)
          IF (N >= NP87) THEN
            WRITE (LU6, 99994) NP87
            GO TO 10
          END IF
C * TEMPORARILY ADD THIS ATOM TO THE CELL CONTENT
          N            = N + 1
          M            = M + 1
          X(N, 4)      = RAD + PROBE
          NCOUNT(INEL) = NCOUNT(INEL) + 1
          DO K = 1, 3
            X(N, K) = MOD (SGY(K + 6) + 1.0, 1.0)
          END DO
C * CHECK FOR DUPLICATION
          IF (M > 1) THEN
            DO K = 1, M - 1
              DIFF = 0.0
              DO J = 1, 3
                DIFF = DIFF + ABS (X(N, J) - X(N - K, J))
              END DO
              IF (DIFF < 0.0001) THEN
                NCOUNT(INEL) = NCOUNT(INEL) - 1
                N = N  - 1
                M = M - 1
                EXIT
              END IF
            END DO
          END IF
        END DO
      END DO
C * SASA LOOPS
      ST = 0.0
C * LOOP OVER UNITCELL CONTENT ATOMS
      DO I = 1, N
C * MONTE CARLO LOOP OF TEST LOCATIONS ON SPHERE with RADIUS X(I, 4)
        NC = 0
        DO J = 1, NS
          PHI = SNGL(GEN160 (ISEED)) * 2.0 * PI
          CTH = 1.0 - SNGL(GEN160 (ISEED)) * 2.0
          TH  = ACOS (CTH)
          XQ  = X(I, 4) * SIN (TH) * COS (PHI)
          YQ  = X(I, 4) * SIN (TH) * SIN (PHI)
          ZQ  = X(I, 4) * CTH
          DO M = 1, 3
            V4(M) = (XQ * ROR(M, 1) + YQ * ROR(M, 2) + ZQ * ROR(M, 3))
          END DO
          DO M = 1, 3
            V3(M) = MOD (V4(M) + X(I, M) + 2.0, 1.0)
          END DO
C * CHECK THIS POINT TO BE OUTSIDE ANY OTHER ATOM ENVIRONMENT
          NADD = 1
          DO K = 1, N
            IF (K /= I) THEN
              TEST = (0.999 * X(K, 4))**2
C * HANDLE UNITCELL OUTLINE CROSSINGS
              DO M = 1, 3
                V2(M) = V3(M) - X(K, M)
              END DO
              DO M = 1, 3
                V2(M) = V2(M) - INT (2.0 * V2(M))
              END DO
              DIST2 = GEN006(V2, AA, V2)
              IF (DIST2 < TEST) THEN
                NADD = 0
                EXIT
              END IF
            END IF
          END DO
          NC = NC + NADD
        END DO
C * OUTPUT RESULT ON TERMINAL AND AS LISTING
        SFRAC  = FLOAT (NC) / NS
        SJREAL = 4 * PI * SFRAC * X(I, 4) ** 2
        ST     = ST + SJREAL
        STRED  = ST / PAR(98) * 1.0E4
      END DO
      DO I = 1, 2
        IF (I == 1) THEN
          LU = LU6
        ELSE
          LU = LU7
        END IF
        WRITE (LU, 99996) PROBE, NS, N, PAR(387)
        DO J = 1, IAN
          WRITE (LU, 99995) ELEM(J), VDW(J), NCOUNT(J)
        END DO
        WRITE (LU, 99999) NINT (ST)
        WRITE (LU, 99998) NINT (STRED)
        WRITE (LU, 99997) NINT (STRED / PAR(387))
      END DO
   10 DEALLOCATE (X)
      RETURN
99999 FORMAT (/, 'Total Surface Area            =', I8, ' Angstrom^2')
99998 FORMAT (   'Total Surface Area per Volume =', I8, ' m^2/cm^3')
99997 FORMAT (   'Total Surface Area per Mass   =', I8, ' m^2/g')
99996 FORMAT (/, '(Solvent) Accessible Surface Area Calculation', /,
     1 '(Loosely Implementing: T.Duren et al.,J.Chem.Phys.C,',
     2 '111(2007)15350-15356)', //,
     3 ':: Probe Radius     =', F6.3, ' Angstrom', /,
     4 ':: MonteCarlo #     =', I6,   ' Random Tests/atom', /,
     5 ':: Expanded # ATOMS =', I6,   ' in Unitcell', /,
     6 ':: Frame Density    =', F6.3, ' g/cm**3', /)
99995 FORMAT (':: vdW Radius ', A, 4X, '=', F6.3, I12, ' in Unitcell')
99994 FORMAT ('Number of atoms in unitcell exceeds ', I10)
      END SUBROUTINE PLA394
 
      REAL FUNCTION PLA395 (NELI, NELJ)
C * CHECK FOR CONTACTS NEEDING SPECIAL TOLERANCES
      IMPLICIT NONE
      INTEGER, PARAMETER :: N = 21
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: NELI
      INTEGER :: NELJ
      INTEGER, DIMENSION(2, N) :: NTAB
      REAL, DIMENSION(N) :: XTAB
      DATA (NTAB(1, I), NTAB(2, I), XTAB(I), I = 1, N) /
     1  10,  10, -0.3,  10,  11, -9.9, 10,  60, -9.9, 11,  11, -9.9,
     2  26,  26, -9.9,  30,  30, -9.9, 54,  85, -9.9, 59,  59, -9.9,
     3  85,  94, -9.9, 103, 103, -9.9, 85, 104, -9.9, 69,  69, -0.74,
     4  10,  99, -9.9,  23,  23, -0.5, 13,  13,  0.0, 39,  39,  0.2,
     5  54,  87, 0.55,  42,  42,  0.2,  5,  82,  0.4,  7,  84,  0.2,
     6   5,  92, 0.20/
C *AVOID OR FORCE SPECIAL 'BOND' COMBINATIONS
C * CU-CU, CU-NI, CU-MO, NI-NI, CD-CD, CO-CO, LI-SI, MN-MN, TI-SI, ZN-ZN,
C * SI-ZR, PB-PB, CU-W , BI-BI, AG-AG, FE-FE, SN-LI, GA-GA, SB-CL, BR-SE.
C * CL-TE
C * CL =  5
C * BR =  7
C * CU = 10
C * NI = 11
C * AG = 13
C * BI = 23
C * CD = 26
C * CO = 30
C * FE = 39
C * GA = 42
C * LI = 54
C * MN = 59
C * MO = 60
C * PB = 69
C * SB = 82
C * SE = 84
C * SI = 85
C * SN = 87
C * TE = 92
C * TI = 94
C * W  = 99
C * ZN = 103
C * ZR = 104
      PLA395 = 0.0
C * IGNORE C, H, N, O
      IF (NELI > 4 .AND. NELJ > 4) THEN
        I = NELI
        J = NELJ
        IF (I > J) CALL GEN014 (I, J)
        DO K = 1, N
          IF (NTAB(1, K) == I .AND. NTAB(2, K) == J) THEN
            PLA395 = XTAB(K)
            EXIT
          END IF
        END DO
      END IF
      RETURN
      END FUNCTION PLA395
 
      SUBROUTINE PLA396
C * MolVolume
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE sgxyz
 
      IMPLICIT NONE
      INTEGER, ALLOCATABLE, DIMENSION(:,:,:) :: IGRID
      REAL,    ALLOCATABLE, DIMENSION(:,:)   :: ATOMS
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: MX
      INTEGER :: MY
      INTEGER :: MZ
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: KDUM
      INTEGER :: IRES
      INTEGER :: JRES
      INTEGER :: LSYM
      INTEGER :: NGRID
      INTEGER :: NXMIN
      INTEGER :: NYMIN
      INTEGER :: NZMIN
      INTEGER :: NXMAX
      INTEGER :: NYMAX
      INTEGER :: NZMAX
      REAL :: XS
      REAL :: YS
      REAL :: ZS
      REAL :: VDWK
      REAL :: STEP
      REAL :: XMIN
      REAL :: XMAX
      REAL :: YMIN
      REAL :: YMAX
      REAL :: ZMIN
      REAL :: ZMAX
      REAL :: TVOL
      REAL :: VDWRX
      REAL :: VOLUME
      TVOL = 0
      STEP = PAR(569)
      WRITE (LU6, 99995) STEP
C * GET CONNECTED SETS
      CALL PLA067
C * LIST UNITCELL CONTENT
      CALL PLA080
      ALLOCATE (ATOMS(4, IPR(39)))
C * LOOP OVER RESIDUES
      DO JRES = 1, IPR(75)
        WRITE (LU6, 99998) JRES
        WRITE (LU6, 99996)
C * LOAD ATOM DATA FOR THIS RESIDUE (Xort, Yort, Zort, vdW radius)
        N    = 0
        LSYM = 0
        KDUM = 0
        DO I = 1, IPR(39)
          CALL GEN048 (-6, IFG(1, I), 9, IRES)
          IF (IRES == JRES) THEN
            N = N + 1
            CALL PLA047 (LABA(I), NQ1, IDUM, JDUM,
     1        IPR(71), IGBL(55), 0, 0)
            ATOMS(4, N) = ABS (VDWR(JDUM))
            DO J = 1, 3
              ATOMS(J, N) = XXO(I, J + 3)
            END DO
C * GET SITE MULTIPLICITLY
            IF (IDUM /= KDUM) THEN
              LSYM = LSYM + 1
              KDUM = IDUM
            END IF
            WRITE (LU6, 99999) NQ1(1:8), (ATOMS(J, N), J = 1, 4)
          END IF
        END DO
C * GET MINIMUM AND MAXIMUM SIZE OF MOLECULE
 
        XMIN =  99999.0
        YMIN =  99999.0
        ZMIN =  99999.0
        XMAX = -99999.0
        YMAX = -99999.0
        ZMAX = -99999.0
        DO I = 1, N
          XMIN = MIN (XMIN, ATOMS(1, I) - ATOMS(4, I))
          YMIN = MIN (YMIN, ATOMS(2, I) - ATOMS(4, I))
          ZMIN = MIN (ZMIN, ATOMS(3, I) - ATOMS(4, I))
          XMAX = MAX (XMAX, ATOMS(1, I) + ATOMS(4, I))
          YMAX = MAX (YMAX, ATOMS(2, I) + ATOMS(4, I))
          ZMAX = MAX (ZMAX, ATOMS(3, I) + ATOMS(4, I))
        END DO
C * SHIFT ORIGIN
        DO I = 1, N
          ATOMS(1, I) = ATOMS(1, I) - XMIN
          ATOMS(2, I) = ATOMS(2, I) - YMIN
          ATOMS(3, I) = ATOMS(3, I) - ZMIN
        END DO
        XMAX = XMAX - XMIN
        YMAX = YMAX - YMIN
        ZMAX = ZMAX - ZMIN
C * SET-UP ANGSTROM GRID
        XS = XMAX / STEP
        YS = YMAX / STEP
        ZS = ZMAX / STEP
        MX = INT(XS) + 1
        MY = INT(YS) + 1
        MZ = INT(ZS) + 1
        ALLOCATE (IGRID(-1:MX, -1:MY, -1:MZ))
        DO I = -1, MX
          DO J = -1, MY
            DO K = -1, MZ
              IGRID(I, J, K) = 0
            END DO
          END DO
        END DO
C * ACCUMULATE GRIDPOINT IN MOLECULE/RESIDUE
        VOLUME = 0.0
        NGRID  = 0
        DO M = 1, N
          VDWRX = ATOMS(4, M)
          VDWK  = VDWRX ** 2
          NXMIN = MAX(-1, INT ((ATOMS(1, M) - VDWRX) / STEP))
          NYMIN = MAX(-1, INT ((ATOMS(2, M) - VDWRX) / STEP))
          NZMIN = MAX(-1, INT ((ATOMS(3, M) - VDWRX) / STEP))
          NXMAX = MIN(MX, INT ((ATOMS(1, M) + VDWRX) / STEP) + 1)
          NYMAX = MIN(MY, INT ((ATOMS(2, M) + VDWRX) / STEP) + 1)
          NZMAX = MIN(MZ, INT ((ATOMS(3, M) + VDWRX) / STEP) + 1)
          DO I = NXMIN, NXMAX
            DO J = NYMIN, NYMAX
              DO K = NZMIN, NZMAX
                L = IGRID (I, J, K)
                IF (L == 0) THEN
                  IF ((ATOMS(1, M) - I * STEP)**2 +
     1                (ATOMS(2, M) - J * STEP)**2 +
     2                (ATOMS(3, M) - K * STEP)**2 < VDWK) THEN
                    IGRID(I, J, K) = 1
                    NGRID          = NGRID + 1
                  END IF
                END IF
              END DO
            END DO
          END DO
        END DO
        DEALLOCATE (IGRID)
        VOLUME = NGRID * STEP ** 3
        WRITE (LU6, 99997) JRES, NGRID, VOLUME, RFORM(JRES)
        TVOL = TVOL + VOLUME * IPR(255) * IPR(256) * IPR(257) / LSYM
      END DO
      IF (IPR(43) == 0) THEN
        WRITE (LU6, 99994) 100.0 * TVOL / PAR(98)
        WRITE (LU6, 99993)
      ELSE
        WRITE (LU6, 99992)
      END IF
      DEALLOCATE (ATOMS)
      IPR(2)  = -1
      IGBL(1) = 3
      RETURN
99999 FORMAT (A, 3F8.3, F6.2)
99998 FORMAT (/, 'Molecular Volume (Ang**3) Calculation for Residue',
     1  I5, ' - (Grid Approach)', /, 80('='), /)
99997 FORMAT (/, 'Res   Ngrid  Volume Formula', /,
     1 I3, I8, F8.1, 1X, A)
99996 FORMAT ('Label       Xort    Yort    Zort  vdWR')
99995 FORMAT ('MOLVOL - GRID-STEP = ', F5.2, ' Ang', /, 80('='), /)
99994 FORMAT (/, 'Packing Index      =', F5.1, '% - (Expected range ',
     1        '65 to 77%)')
99993 FORMAT (/,
     1 'NOTE: The Packing Index is calculated assuming that the above ',
     2 'molecular volumes', /, 'do not overlap (i.e. with only van der',
     3 ' Waals contacts). In case of hydrogen', /, 'bonding, the',
     4 ' ''CALC K.P.I'' tool calculation of the Kitaigorodskii Packing',
     5 ' Index', /, 'should be used for a better estimate.')
99992 FORMAT (/, ':: No Packing Index calculated for disordered ',
     1        'structure')
      END SUBROUTINE PLA396
 
      MODULE mp
      SAVE
      INTEGER, PARAMETER :: MP8 = 50
      INTEGER, PARAMETER :: MP9 = 16
      INTEGER :: NLINES
      CHARACTER(len=4),  DIMENSION(20, 40) :: XLINE
      CHARACTER(len=12), DIMENSION(26)     :: TARG
 
      END MODULE mp
 
      SUBROUTINE PLA400
C * MP.FOR (MidPoint.FOR): generates the "loci" (halfsums) and differences
C * between pairs of molecules.
C * Original version by Ricardo Baggio (Acta Cryst C75. (2019) 837-850.
C * Restructured version: A.L.Spek - 13-Jun-2019
C * INPUT FILE: COMMAND LINE ARGUMENT OR DEFAULT 'MP1.INS', a SHELXL style
C * RES file with one extra 'dummy' line (to be places before the first ATOMS
C * card), beginning with the flag "REM ****", and followed by six numbers in
C * free FORMAT, viz.: REM **** NATOM, NMOL, NWRITE, NSUCC, NRES, XLIM
C * where:
C * NATOM: number of atoms in the molecule (Max. MP8) (N Hs, only Uiso)
C * NMOL:  number of molecules (all sorted in the same way) (Max. MP9).
C * NSUCC: (MP_name.RES output filter) Expected to allow/filter some symmetry
C *        elements
C * = 0:  no filter (all MPs included)
C * = 1:  only inversion included (-1)
C * = 2:  only two fold/screw (2/21)
C * = 3:  only mirror/glide  (m/a/b/c)
C * = 4:  only A,B,C centering
C * = 12: only inversion and two fold included (-1 + 2/21)
C * = 13: only inversion and mirror/glide  (-1 + m/a/b/c)
C * = 14: only inversion and A,B,C centering   (-1 + A,B,C )
C * = 23: only two fold/screw and mirror/glide  (2/21 + m/a/b/c)
C * = 24: only two fold/screw and A,B,C centering   (2/21 + A,B,C)
C * = 34: only mirror/glide and A,B,C centering   (m/a/b/c + A,B,C)
C * = 123:only inversion, two fold and mirror/glide included
C *
C * Negative NSUCC: as above, but "EXCLUDED" instead of "INCLUDED"
C *
C * NOTE: this option should be used with care, as it only refers to
C *       symmetry elements "recognized" a priori by MP, a rather
C *       limiting option at present.
C *
C * NRES: output RES indicator
C * = 0, Restricted MP_name.RES file WITH all MPs but WITHOUT original atoms.
C *         NO short AB.RES output.
C * = 1, Restricted MP_name.RES file WITH all MPs but WITHOUT original atoms.
C *         ALL short AB.RES included.
C * = 2, Extended MP_name.RES file WITH all MPs and WITH all the original atoms.
C *         NO short AB.RES output.
C * = 3, Extended MP_name.RES file WITH all MPs and WITH all the original atoms.
C *         ALL short AB.RES included.
C *
C * XLIM: threshold to define the acceptance of a symmetry
C *          (The larger, the more stringent. Typical: 2)
C *
C * NWRITE: LST OUTPUT OPTIONS
C * = 0, Default Listing
C * = 2, Include Individual midpoint data
C *
C * If the problem requires changing dimensions, change in the appropriate
C *   lines: MP8: max.atoms, MP9: max.molecules
      USE mp
      IMPLICIT NONE
      REAL, ALLOCATABLE, DIMENSION(:,:,:)            :: A
      REAL, ALLOCATABLE, DIMENSION(:,:,:,:)          :: VP
      REAL, ALLOCATABLE, DIMENSION(:,:,:,:)          :: VM
      CHARACTER(len=80), ALLOCATABLE, DIMENSION(:,:) :: ZLINE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: K1
      INTEGER :: K2
      INTEGER :: K5
      INTEGER :: K6
      INTEGER :: IJK
      INTEGER :: IARG
      INTEGER :: MARG
      INTEGER :: NARG
      INTEGER :: NMOL
      INTEGER :: NRES
      INTEGER :: I1I2
      INTEGER :: IOST
      INTEGER :: NATOM
      INTEGER :: ISUCC
      INTEGER :: NSUCC
      INTEGER :: ICASE
      INTEGER :: NWRITE
      INTEGER :: ICOUNT1
      INTEGER :: ICOUNT2
      REAL :: X12
      REAL :: XD
      REAL :: XS
      REAL :: XLIM
      REAL :: YUNK
      REAL :: DELTA1
      REAL :: DELTA2
      REAL :: SUCCESS
      REAL, DIMENSION(3) :: SUMM
      REAL, DIMENSION(3) :: DIFF
      REAL, DIMENSION(3) :: SUMSQDEV
      REAL, DIMENSION(3) :: DIFSQDEV
      REAL, DIMENSION(6) :: XSORTED
      CHARACTER(len=4)  :: XK
      CHARACTER(len=2)  :: AB
      CHARACTER(len=80) :: ARG
      CHARACTER(len=6)  :: NAAM
      CHARACTER(len=12) :: XX12
      CHARACTER(len=8)  :: CARTEL
      CHARACTER(len=40) :: XINPUT
      CHARACTER(len=28), DIMENSION(8)   :: CELL
      CHARACTER(len=80), DIMENSION(MP8) :: TMP
 
      CELL = (/
     1 'X000 1  0   0   0  11.00 .05', 'X100 1  1   0   0  11.00 .05',
     2 'X010 1  0   1   0  11.00 .05', 'X001 1  0   0   1  11.00 .05',
     3 'X011 1  0   1   1  11.00 .05', 'X101 1  1   0   1  11.00 .05',
     4 'X110 1  1   1   0  11.00 .05', 'X111 1  1   1   1  11.00 .05'/)
      TARG = (/
     1 '(    -1   ) ', '( .  .  2 ) ', '( .  .  21) ', '( .  2  . ) ',
     2 '( .  21 . ) ', '( 2  .  . ) ', '( 21 .  . ) ', '( m  .  . ) ',
     3 '( b  .  . ) ', '( c  .  . ) ', '( n  .  . ) ', '( .  m  . ) ',
     4 '( .  a  . ) ', '( .  c  . ) ', '( .  n  . ) ', '( .  .  m ) ',
     5 '( *  *  * ) ', '( *  *  . ) ', '( *  .  * ) ', '( *  .  . ) ',
     6 '( .  *  * ) ', '( .  .  a ) ', '( .  .  b ) ', '( .  .  n ) ',
     7 '( .  *  . ) ', '( .  .  * ) '/)
      ALLOCATE (A(3, MP8, MP9), Vp(3, MP8, MP9, MP9),
     1 VM(3, MP8, MP9, MP9))
      ALLOCATE (ZLINE(MP8, MP9))
      ICASE = 0
C * GET FILENAME FROM COMMAND LINE OR USE DEFAULT 'MP1'
      IARG  = COMMAND_ARGUMENT_COUNT()
      IF (IARG == 1) THEN
        CALL GET_COMMAND_ARGUMENT (1, ARG)
      ELSE
        ARG = 'MP1.INS'
      END IF
      NARG = INDEX (ARG, '.') - 1
      MARG = INDEX (ARG, ' ') - 1
C * a RES file with a dummy card added.
      OPEN (UNIT = 7,  FILE = ARG(1:MARG))
C * halfsums and differences table
      OPEN (UNIT = 8,  FILE = ARG(1:NARG)//'.LST')
C * a new RES, with renamed (real) atoms and halfsums (meant as further atoms)
      OPEN (UNIT = 10, FILE = ARG(1:NARG)//'.RES')
C *  Copy Input up and including REM record (NLINES)
      DO I = 1, 40
C * READ FROM name.INS
        READ   (7, 99999) (XLINE(J, I), J = 1, 20)
C * WRITE TO name.RES
        WRITE (10, 99999) (XLINE(J, I), J = 1, 20)
        IF ((XLINE(1, I) == 'REM ' ) .AND. (XLINE(2, I) == '****'))
     1    THEN
          NLINES = I
          WRITE (XINPUT, 99998) (XLINE(J, NLINES), J = 3, 12)
C * See at the top of the program the meaning of each variable
          READ (XINPUT, *) NATOM, NMOL, NWRITE, NSUCC, NRES, XLIM
          EXIT
        END IF
      END DO
C * STORE ATOM RECORDS
      DO I = 1, NMOL
C * WRITE TO name.RES (10)
      IF (IABS(NRES) > 1) WRITE (10, 99997) I
        DO J = 1, NATOM
          READ (7, 99996, IOSTAT = IOST) XK, L, (A(K, J, I), K = 1, 3)
          IF (IOST == -1) GO TO 40
          DO WHILE (XK == 'FVAR' .OR. XK == '    ')
            READ (7, 99996, IOSTAT = IOST) XK, L, (A(K, J, I), K = 1, 3)
            IF (IOST == -1) GO TO 40
          END DO
          WRITE (ZLINE(J, I), 99995)
     1      CHAR (64 + I), J, L, (A(K, J, I), K = 1, 3)
C * WRITE TO name.RES (10)
          IF (IABS(NRES) > 1) WRITE (10, 99994) ZLINE(J, I)
        END DO
      END DO
C * MOL1, MOL2 LOOPS
      I1I2 = 100
      DO I1 = 1, NMOL
        DO I2 = I1 + 1, NMOL
          AB = CHAR (64 + I1)//CHAR (64 + I2)
          I1I2 = I1I2 + 1
          DO K = 1, 3
            SUMM(K) = 0.0
            DIFF(K) = 0.0
            SumSqdev(K) = 0.0
            DifSqdev(K) = 0.0
          END DO
          DO J = 1, NATOM
            DO K = 1, 3
              Vp(K,J,I1,I2) =     (A(K,J,I1) + A(K,J,I2)) / 2
              Vm(K,J,I1,I2) = ABS (A(K,J,I1) - A(K,J,I2))
              SUMM(K)       = SUMM(K) + Vp(K,J,I1,I2)
              DIFF(K)       = DIFF(K) + Vm(K,J,I1,I2)
            END DO
          END DO
          DO K = 1, 3
            SUMM(K) = SUMM(K) / NATOM
            DIFF(K) = DIFF(K) / NATOM
          END DO
          DO J = 1, NATOM
            DO K = 1, 3
              Xs = ((A(K,J,I1) + A(K,J,I2)) / 2 - SUMM(K))**2
              Xd = (ABS (A(K,J,I1) - A(K,J,I2)) - DIFF(K))**2
              SumSqdev(K) = SumSqdev(K) + XS
              DifSqdev(K) = DifSqdev(K) + XD
            END DO
          END DO
          DO K = 1, 3
            SumSqdev(K) = sqrt (SumSqdev(K) / NATOM)
            Difsqdev(K) = sqrt (Difsqdev(K) / NATOM)
          END DO
          ICASE = ICASE + 1
          XX12 = '***  '//AB//'  ***'
          WRITE (8, 99993) ICASE,  XX12
          WRITE (XX12, 99992) 'Case', ICASE, '('//AB//')'
C * This block is meant to generate the "two-molecules" RES files, including
C * both molecules and the halfsums in between. Used for a simpler recognition.
          IF (IABS(NRES) == 1 .OR. IABS(NRES) == 3) THEN
C * generates the small RES, with pair of molecules and MP's
            NAAM = AB//'.RES'
            OPEN (UNIT = 12, FILE = ARG(1:NARG)//'_'//NAAM)
            DO K1 = 1, NLINES
              WRITE (12, 99999) (XLINE(K2, K1), K2 = 1, 20)
            END DO
            IF (NRES < 0) THEN
C * Negative code, include cell corners
              WRITE (12, 99991) 'PART 999'
              DO IJK = 1, 8
                WRITE (12, 99990) CELL(IJK)
              END DO
            ENDIF
C * Negative code, include cell corners
            WRITE (12, 99989) 'PART 1'
            DO K5 = 1, NATOM
              WRITE (12, 99994) ZLINE(K5, I1)
            END DO
            DO K6 = 1, NATOM
              WRITE (12, 99994) ZLINE(K6, I2)
            END DO
            WRITE (12, 99994)
            WRITE (12, 99989) "PART 2"
          ENDIF
C * generates the small RES, with pair of molecules and MP's
C * WRITE TO name.RES
          WRITE (10, 99997) I1I2
          DO J = 1, NATOM
C * iNWRITE = 2 - WRITE ON 8
            IF (NWRITE == 2) WRITE (8, 99988) AB, J,
     2        (Vp(K,J,I1,I2), K = 1, 3), (Vm(K,J,I1,I2), K = 1, 3)
C * WRITE ON TMP(J) (ATOMTYPE = H = 2)
            N = 2
            WRITE (TMP(J), 99987) AB, J, N, (Vp(K,J,I1,I2), K = 1, 3)
C * IABS(NRES) = 1 or 3 - WRITE on (12)
            IF (IABS (NRES) == 1 .OR. IABS (NRES) == 3)
     1        WRITE (12, 99994) TMP(J)
          END DO
          WRITE (8, 99986)
          WRITE (8, 99985) 'Average', (SUMM(I), I = 1, 3),
     1      (DIFF(I), I = 1, 3)
          WRITE (8, 99985) 'Sigma  ', (Sumsqdev(I), I = 1, 3),
     1      (Difsqdev(I), I = 1, 3)
          SUCCESS = 1
          DO I = 1, 3
            XSORTED(I)     = SumSqdev(I)
            XSORTED(I + 3) = DifSqdev(I)
          END DO
          DO J = 1, 6
C * SORT XSORTED FROM SMALL TO LARGE
            DO K = 1, J - 1
              IF (XSORTED(K) > XSORTED(J)) THEN
                YUNK = XSORTED(K)
                XSORTED(K) = XSORTED(J)
                XSORTED(J) = YUNK
              END IF
            END DO
          END DO
          IF (XSORTED(1) * XSORTED(2) * XSORTED(3) /= 0.0) THEN
            X12 = XSORTED(4) / XSORTED(3)
            IF (X12 < XLIM) THEN
              SUCCESS = 0
            ELSE IF (X12 > XLIM       .AND. X12 <= XLIM * 1.2) THEN
              CARTEL = '# POOR #'
            ELSE IF (X12 > XLIM * 1.2 .AND. X12 <= XLIM * 1.5) THEN
              CARTEL = '# FAIR #'
            ELSE IF (X12 > XLIM * 1.5 .AND. X12 <= XLIM * 2.0) THEN
              CARTEL = '# GOOD #'
            ELSE IF (X12 > XLIM * 2.0) THEN
              CARTEL = '# EXCEL#'
            ENDIF
          ENDIF
          DELTA1 = XSORTED(3) + 0.00001
          DELTA2 = XSORTED(4) - 0.00001
          ICOUNT1 = 0
          ICOUNT2 = 0
          DO I = 1, 3
            IF (SumSqdev(I) < 0.00000001) SumSqdev(I) = 0.0
            IF (SumSqdev(I) < delta1) ICOUNT1 = ICOUNT1 + 1
          END DO
          DO I = 1, 3
            IF (DifSqdev(I) < 0.00000001) DifSqdev(I) = 0.0
            IF (DifSqdev(I) < delta1) ICOUNT2 = ICOUNT2 + 1
          END DO
C * 'CHECK'
          CALL PLA401 (ICOUNT1, ICOUNT2, SUMM, Sumsqdev, DIFF, DifSqdev,
     1      DELTA1, DELTA2, SUCCESS, ISUCC, CARTEL, XX12)
          WRITE (8, 99984)
C * See at the top of the program the meaning of the Nsucc variable
          I = ISUCC
          IF (NSUCC == 0) THEN
            GOTO 20  ! pasan todas
          ELSE IF (NSUCC > 0) THEN
            N = NSUCC
            IF (I == 0) GOTO 30
            if (N == I) GOTO 20
            If (N == 12 .AND. (I == 1 .OR. I == 2)) GOTO 20
            If (N == 13 .AND. (I == 1 .OR. I == 3)) GOTO 20
            If (N == 14 .AND. (I == 1 .OR. I == 4)) GOTO 20
            If (N == 23 .AND. (I == 2 .OR. I == 3)) GOTO 20
            If (N == 24 .AND. (I == 2 .OR. I == 4)) GOTO 20
            If (N == 34 .AND. (I == 3 .OR. I == 4)) GOTO 20
            If (N == 123.AND. (I == 1 .OR. I == 2 .OR.
     1        I == 3)) GOTO 20
            goto 30
          ELSE IF (NSUCC < 0) THEN
            N = - NSUCC
            if (N == I)  goto 30
            If (N == 12 .AND. (I == 1 .OR. I == 2)) GOTO 30
            If (N == 13 .AND. (I == 1 .OR. I == 3)) GOTO 30
            If (N == 14 .AND. (I == 1 .OR. I == 4)) GOTO 30
            If (N == 23 .AND. (I == 2 .OR. I == 3)) GOTO 30
            If (N == 24 .AND. (I == 2 .OR. I == 4)) GOTO 30
            If (N == 34 .AND. (I == 3 .OR. I == 4)) GOTO 30
            if (N == 123.AND. (I == 1 .OR. I == 2 .OR.
     1        I == 3)) GOTO 30
            goto 20
          END IF
C * WRITE TO name.RES
  20      DO J = 1, NATOM
            WRITE (10, 99994) TMP(J)
          END DO
  30      CONTINUE
        END DO
      END DO
      CALL PLA402 (NWRITE)
  40  CLOSE (7)
      CLOSE (8)
      CLOSE (12)
      DEALLOCATE (A, VP, VM)
      DEALLOCATE (ZLINE)
      STOP
99999 FORMAT (20A)
99998 FORMAT (10A)
99997 FORMAT ('PART', I4)
99996 FORMAT (A, 2X, I1, 3F10.4)
99995 FORMAT (A, I2.2, I4, 3F10.4, ' 11.0 0.05')
99994 FORMAT (A)
99993 FORMAT ('Case # ', I3, 24X, A12, /, 20X, 'Halfsum', 26X,
     1  'Difference')
99992 FORMAT (A4, 1X, I3, A4)
99991 FORMAT (A8)
99990 FORMAT (A28)
99989 FORMAT (A6)
99988 FORMAT (A, I2.2, 3X, 3F10.4, 5x, 3F10.4)
99987 FORMAT (A, I2.2, I4, 3F10.4, ' 11.0 0.05')
99986 FORMAT (1X)
99985 FORMAT (A, 3F10.4, 5X, 3F10.4)
99984 FORMAT (79('#'), /)
      END SUBROUTINE PLA400
      SUBROUTINE PLA401 (ICOUNT1, ICOUNT2, SUMX, Sumsqdev, DIF,
     1 DifSqdev, DELTA1, DELTA2, SUCCESS, ISUCC, CARTEL, XX12)
      USE mp
      IMPLICIT NONE
      INTEGER :: ICOUNT1
      INTEGER :: ICOUNT2
      INTEGER :: ISUCC
      REAL :: ZERO
      REAL :: TRUE1
      REAL :: TRUE2
      REAL :: DELTA2
      REAL :: DELTA1
      REAL :: SUCCESS
      REAL, DIMENSION(3) :: SUMX
      REAL, DIMENSION(3) :: SUMSQDEV
      REAL, DIMENSION(3) :: DIF
      REAL, DIMENSION(3) :: DIFSQDEV
      CHARACTER(len=96) :: TXT
      CHARACTER(len=96) :: TXT1
      CHARACTER(len=96) :: TXT2
      CHARACTER(len=96) :: TXT3
      CHARACTER(len=96) :: TEXT
      CHARACTER(len=12) :: XX12
      CHARACTER(len=8)  :: CARTEL
      CHARACTER(len=8)  :: CHAR1
      CHARACTER(len=8)  :: CHAR2
      DATA TXT2/
     1'# REAL #   *********  Real Symmetry operation   *******   '/
      DATA TXT3/
     1'     ***************   No local symmetry found  ***************'/
      CARTEL = '# POOR #'
      WRITE (CHAR1, 99999) DELTA1
      WRITE (CHAR2, 99999) DELTA2
      TXT1 = CARTEL//
     1 '                Delta1:'//CHAR1//',  Delta2:'//CHAR2
      ZERO  = 0.0
      TRUE1 = SumSqdev(1) * SumSqdev(2) * SumSqdev(3)
      TRUE2 = DifSqdev(1) * DifSqdev(2) * DifSqdev(3)
      TXT   = TXT1
      IF (ABS (TRUE1) < 0.00001 .OR. ABS (TRUE2) < 0.00001)
     1   TXT = TXT2
      WRITE (TEXT, 99998) TXT3
C * Here the big loop starts
      ISUCC = 0
      IF (SUCCESS == 0) THEN
C * It goes on:  Delta1 y Delta2 NO DO not seem to be reasonables)
      ELSE IF ((ICOUNT1 == 3) .AND. (ICOUNT2 == 0)) THEN
C * possible -1
        ISUCC = 1
        WRITE (TEXT, 99997) TARG(1), SUMX(1), SUMX(2), SUMX(3), XX12
      ELSE IF ((ICOUNT1 == 2) .AND. (ICOUNT2 == 1)) THEN
C * possible 2-2-Axis
        Isucc = 2
        IF ((SumSqdev(1) < delta1) .AND. (SumSqdev(2) < DELTA1)
     1    .AND. (DifSqdev(3) < DELTA1)) THEN
C * // <001>
        IF (ABS (DIF(3)) < DELTA2)
     1    WRITE (TEXT, 99996) TARG(2), SUMX(1), SUMX(2), XX12
        IF (ABS (DIF(3)) > DELTA2)
     1    WRITE (TEXT, 99995) TARG(3), SUMX(1), SUMX(2), DIF(3), XX12
      ELSE IF ((SumSqdev(1) < DELTA1) .AND. (SumSqdev(3) <
     1 DELTA1) .AND. (DifSqdev(2) < DELTA1)) THEN
C * // <010>
        IF (ABS (DIF(2)) < DELTA2) WRITE (TEXT, 99994)
     1    TARG(4), SUMX(1), SUMX(3), XX12
        IF (ABS (DIF(2)) > DELTA2) WRITE (TEXT, 99993)
     1    TARG(5), SUMX(1), SUMX(3), DIF(2), XX12
      ELSE IF ((SumSqdev(2) < DELTA1) .AND. (SumSqdev(3) <
     1 DELTA1) .AND. (DifSqdev(1) < DELTA1)) THEN
C * // <100>
        IF (ABS (DIF(1)) < DELTA2) WRITE (TEXT, 99992)
     1    TARG(6), SUMX(2), SUMX(3), XX12
        IF (ABS (DIF(1)) > DELTA2) WRITE (TEXT, 99991)
     1   TARG(7), SUMX(2), SUMX(3), DIF(1), XX12
        END IF
      ELSE IF ((ICOUNT1 == 1) .AND. (ICOUNT2 == 2)) THEN
C * posible plano
        ISUCC = 3
        IF ((SumSqdev(1) < DELTA1) .AND. (DifSqdev(2) < DELTA1)
     1    .AND. (DifSqdev(3) < DELTA1)) THEN
C * // (001)
          IF (ABS (DIF(2)) < DELTA2 .AND. ABS (DIF(3))
     1      < DELTA2 ) WRITE (TEXT, 99990) TARG(8), SUMX(1), XX12
          IF (ABS (DIF(2)) > DELTA2 .AND. ABS (DIF(3))
     1      < DELTA2 ) WRITE (TEXT, 99989) TARG(9), SUMX(1), DIF(2),
     2      XX12
          IF (ABS (DIF(2)) < DELTA2 .AND. ABS (DIF(3))
     1      > DELTA2 ) WRITE (TEXT, 99988) TARG(10), SUMX(1),
     2       DIF(3), XX12
          IF (ABS (DIF(2)) > DELTA2 .AND. ABS (DIF(3))
     1      > DELTA2 ) WRITE (TEXT, 99987) TARG(11), SUMX(1),
     2      DIF(2), DIF(3), XX12
        ELSE IF ((SumSqdev(2) < DELTA1) .AND. (DifSqdev(1)
     1    < DELTA1) .AND. (DifSqdev(3) < DELTA1)) THEN
C * // (010)
          IF (ABS (DIF(1)) < DELTA2 .AND. ABS (DIF(3))
     1      < DELTA2 ) WRITE (TEXT, 99986) TARG(12), SUMX(2), XX12
          IF (ABS (DIF(1)) > DELTA2 .AND. ABS (DIF(3))
     1      < DELTA2 ) WRITE (TEXT, 99985) TARG(13), SUMX(2),
     2      DIF(1), XX12
          IF (ABS (DIF(1)) < DELTA2 .AND. ABS (DIF(3))
     1      > DELTA2 ) WRITE (TEXT, 99984) TARG(14), SUMX(2),
     2      DIF(3), XX12
          IF (ABS (DIF(1)) > DELTA2 .AND. ABS (DIF(3))
     1      > DELTA2 ) WRITE (TEXT, 99983) TARG(15), SUMX(2),
     2      DIF(1), DIF(3),
     2      XX12
        ELSE IF ((SumSqdev(3) < delta1) .AND. (DifSqdev(1)
     1    < DELTA1) .AND. (DifSqdev(2) < DELTA1)) THEN
C * // (100)
          IF (ABS (DIF(1)) < DELTA2 .AND. ABS (DIF(2))
     1      < DELTA2 ) WRITE (TEXT, 99982) TARG(16), SUMX(3), XX12
          IF (ABS (DIF(1)) > DELTA2 .AND. ABS (DIF(2))
     1      < DELTA2 ) WRITE (TEXT, 99981) TARG(22), SUMX(3),
     2      DIF(1), XX12
          IF (ABS (DIF(1)) < DELTA2 .AND. ABS (DIF(2))
     1      > DELTA2 ) WRITE (TEXT, 99980) TARG(23), SUMX(3),
     2      DIF(2), XX12
          IF (ABS (DIF(1)) > DELTA2 .AND. ABS (DIF(2))
     1      > DELTA2 ) WRITE (TEXT, 99979) TARG(24), SUMX(3),
     2      DIF(1), DIF(2), XX12
          END IF
        ELSE IF ((ICOUNT2 == 3)) THEN
C * possible cell centering
          Isucc = 4
      IF (ABS (DIF(1)) > DELTA2) THEN
        IF (ABS (DIF(2)) > DELTA2) THEN
          IF (ABS (DIF(3)) > DELTA2) THEN
            WRITE (TEXT, 99978) TARG(17), DIF(1), DIF(2), DIF(3), XX12
          ELSE
            WRITE (TEXT, 99978) TARG(18), DIF(1), DIF(2), ZERO, XX12
          ENDIF
        ELSE IF (ABS (DIF(3)) > DELTA2) THEN
            WRITE (TEXT, 99978) TARG(19), DIF(1), ZERO, DIF(3), XX12
          ELSE
            WRITE (TEXT, 99978) TARG(20), DIF(1), ZERO, ZERO, XX12
          END IF
        ELSE IF (ABS (DIF(2)) > DELTA2) THEN
          IF (ABS (DIF(3)) > DELTA2 ) THEN
            WRITE (TEXT, 99978) TARG(21), ZERO, DIF(2), DIF(3), XX12
          ELSE
            WRITE (TEXT, 99978) TARG(25), ZERO, DIF(2), ZERO, XX12
          END IF
        ELSE IF (ABS (DIF(3)) > DELTA2) THEN
          WRITE (TEXT, 99978) TARG(26), ZERO, ZERO, DIF(3), XX12
        END IF
      END IF
      WRITE (8, 99971) TEXT
      if (TRUE1 == 0.0 .OR. TRUE2 == 0.0) TXT = TXT2
      if (TEXT == TXT3)  WRITE (TXT, 99970)
      WRITE (8, 99969) TXT
99999 FORMAT (F7.4)
99998 FORMAT (A)
99997 FORMAT (A, 'Possible inversion at (', 2(F8.4, ','), F8.4, ')',
     1        T75, A)
99996 FORMAT (A, 'Possible   twofold at (', 2(F8.4, ','), ' z)', T75, A)
99995 FORMAT (A, 'Possible     screw at (', 2(F8.4, ','), ' z)  shift:',
     1        F8.4, T75, A)
99994 FORMAT (A, 'Possible   twofold at (', F8.4, ', y, ',F8.4, ')',
     1        T75, A)
99993 FORMAT (A, 'Possible   screw  at (',
     1        F8.4,', y,', F8.4,'),   shift:', F8.4, T75, A)
99992 FORMAT (A, 'Possible   twofold at (',' x,', F8.4,',',F8.4,')',
     1        T75, A)
99991 FORMAT (A, 'Possible   screw at (',' x,',
     1        F8.4, ',', F8.4,'),   shift:', f8.4, T75, A)
99990 FORMAT (A, 'Possible   mirror at (', F8.4,', y',', z)', T75, A)
99989 FORMAT (A, 'Possible   glide at (',
     1        F8.4,', y',', z),         shift:', F8.4, T75, A)
99988 FORMAT (A, 'Possible   glide at (',
     1        F8.4,', y',', z),        shift: ', F8.4, T75, A)
99987 FORMAT (A, 'Possible   glide at (',
     1        F8.4,', y',', z), shift:', 2F8.4, T75, A)
99986 FORMAT (A, 'Possible   mirror at (',' x,', F8.4,', z)', T75, A)
99985 FORMAT (A, 'Possible   glide at (',' x,',
     1        F8.4,', z),         shift: ', F8.4, T75, A)
99984 FORMAT (A, 'Possible   glide at (',' x,',
     1        F8.4,', z),         shift:', F8.4, T75, A)
99983 FORMAT (A, 'Possible   glide at (',' x,',
     1        F8.4,', z), shift:', 2F8.4, T75, A)
99982 FORMAT (A, 'Possible   mirror at (',' x,',' y,', F8.4,')', T75, A)
99981 FORMAT (A, 'Possible   glide at (',' x,', ' y,',
     1        F8.4,'),       shift: ', F8.4, T75, A)
99980 FORMAT (A, 'Possible   glide at (',' x,', ' y,',
     1        F8.4,'),       shift: ', F8.4, T75, A)
99979 FORMAT (A, 'Possible   glide at (',' x,', ' y,',
     1        F8.4,'), shift:', 2F8.4, T75, A)
99978 FORMAT (A, 'Possible   cell centering', ' shift: ', 3F8.4, T75, A)
99971 FORMAT (/, A)
99970 FORMAT (96X)
99969 FORMAT (/, A, /)
      RETURN
      END SUBROUTINE PLA401
      SUBROUTINE PLA402 (NWRITE)
      USE mp
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: NL
      INTEGER :: IOST
      INTEGER :: IPUNCH
      INTEGER :: NWRITE
      CHARACTER(8) :: CARTEL
      CHARACTER(len=12), DIMENSION(10) :: XYLINE
      OPEN (UNIT = 14, status = 'SCRATCH')
      REWIND (UNIT = 8)
      NL = 0
      DO
        READ (8, 99999, IOSTAT = IOST) (XYLINE(J), J = 1, 8)
        IF (IOST /= 0) EXIT
        WRITE (14, 99999) (XYLINE(J), J = 1, 8)
        NL = NL + 1
      END DO
      REWIND (UNIT = 8)
      REWIND (UNIT = 14)
      IF (NWRITE == 2) THEN
        DO K = 1, NL
          READ (14, 99999) (XYLINE(J), J = 1, 8)
          WRITE (8, 99999) (XYLINE(J), J = 1, 8)
        END DO
      END IF
      DO J = 1, NLINES
        WRITE (8, 99996) (XLINE(I, J), I = 1, 20)
      END DO
      WRITE (8, 99995)
      OPEN (UNIT = 15, STATUS = 'SCRATCH')
      DO I = 1, 26
        IPUNCH = 0
        REWIND (UNIT = 14)
        DO
          READ (14, 99999, IOSTAT = IOST) (XYLINE(J), J = 1, 8)
          IF (IOST /= 0) EXIT
          IF (XYLINE(1) == TARG(I)) THEN
            READ (14, 99998)
            READ (14, 99997) CARTEL
            XYLINE(2)(1:8) = CARTEL
            WRITE (8, 99999) (XYLINE(J), J = 1, 8)
            IPUNCH = 1
          ENDIF
        END DO
        if (IPUNCH == 1) THEN
          WRITE (8, 99998)
        ELSE
          WRITE (8, 99997) TARG(I)//'No Match'
          WRITE (8, 99998)
        ENDIF
      END DO
      RETURN
99999 FORMAT (8A)
99998 FORMAT (1X)
99997 FORMAT (A)
99996 FORMAT (20A)
99995 FORMAT (//, '  ########  Sorted Summary of Results  ########', /)
      END SUBROUTINE PLA402
 
      SUBROUTINE PLA405 (MODE, NOPT)
C * ANALYSIS OF VARIANCE + ANALYSIS FOR TWINNING + BIJVOET PAIR ANALYSIS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE reflex
      USE analysis
      USE fab
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IHO
      INTEGER :: IKO
      INTEGER :: ILO
      INTEGER :: MODE
      INTEGER :: NOPT
      INTEGER :: NFEXP
      INTEGER :: IHEXL
      INTEGER :: ITHETA
      REAL :: TH
      REAL :: ST
      REAL :: STL
      REAL :: SIG
      REAL :: FCK
      REAL :: FOK
      REAL :: FOKM
      REAL :: FCKP
      REAL :: ACAL
      REAL :: BCAL
      REAL :: CALI
      REAL :: SIGI
      REAL :: SIGK
      REAL :: YUNK
      REAL :: SIGIW
      REAL :: ACALA
      REAL :: BCALA
      REAL :: ACALS
      REAL :: BCALS
      REAL :: SCHAAL
      REAL :: ACALAF
      REAL :: BCALAF
      REAL :: SUMFCK
      REAL :: SUMFOK
      REAL :: GEN050
      REAL :: GEN095
      REAL :: THETAMAX
C * MODE = -2 : Bijvoet Pair Analysis          - PLA421 (Validation Mode)
C *      = -1 : Bijvoet Pair Analysis          - PLA421 (Standard   Mode)
C *      =  0 : Analysis-of-Variance           - PLA412
C *      =  1 : TwinRotMat                     - PLA414
C *      =  2 : TwinRotMat (Non-Graphics Mode) - PLA414
C * REFLECTION DATA STORAGE SCHEME
C * VOID(NADR + 1)  = IH
C * VOID(NADR + 2)  = IK
C * VOID(NADR + 3)  = IL
C * VOID(NADR + 4)  = FOK
C * VOID(NADR + 5)  = FCK (FROM CIF)
C * VOID(NADR + 6)  = MAX (SIG, 0.0)
C * VOID(NADR + 7)  = TH
C * VOID(NADR + 8)  = (FOK - FCK) / SIGI
C * VOID(NADR + 9)  = (FOK - FCK) / SIGIW
C * VOID(NADR + 10) =
C * VOID(NADR + 11) = FCK' (FROM FCF)
C * VOID(NADR + 12) = SIGIW
C * NO ANALYSIS FOR JANA(F) REFLECTION DATA CASE
      IF (IGBL(9) == 14 .OR. IGBL(9) == 13 .OR. IGBL(9) == 15) THEN
        IGGT = ' '
        WRITE (LU6, 99991, IOSTAT = IOST)
        RETURN
      ENDIF
C * NO ANALYSIS WHEN PAR(493) < 0.0 (NEGATIVE WEIGHT-PAR-A)
      IF (PAR(493) < 0.0) THEN
        IF (IPR(725) /= 6 .AND. IPR(725) /= 9) THEN
          IGGT = ' '
          WRITE (LU6, 99990, IOSTAT = IOST)
          RETURN
C * JANA REFINEMENT
        ELSE
          PAR(493) = 0.0
          PAR(494) = 0.0
        END IF
      END IF
C * SET X-WINDOWS GRAPHICS MODE
      IWIN = IGBL(25) * IGBL(32)
      IH   = 0
      IK   = 0
      IL   = 0
C * PREPARE FOR THE CALCULATION OF FCALC (IGBL(9) = 0 => HKLF 4)
      IF (IGBL(9) == 0 .AND. MODE < 0) THEN
C * SET ASYM NORMAL MODE
        IPR(408) = 0
C * SET ASYM MODE TO 0 (LISTING OF SYMMETRY ABSENCES REFLECTIONS ONLY)
        IPR(392) = 0
C * RUN DEFAULT ASYM
        IPR(220) = 1
        CALL PLA145 (0)
        LU16 = LU17
        REWIND (UNIT = LU16, IOSTAT = IOST)
      ELSE
C * HANDLE CELL DATA
        CALL PLA100
C * LIST CELL DATA
        CALL PLA042 (2)
C * CHECK WAVELENGTH DATA
        CALL PLA293 (PAR(17))
      END IF
      IF (MODE < 2) THEN
C * MODE = -1 : BIJVOET PAIR ANALYSIS CASE
        IF (MODE == -1) THEN
          IF (IPR(220) > 1 .AND. IFL(2)(1:3) == 'FCF') IPR(594) = 0
C * IGNORE BASF/TWIN IN .RES
          IPR(193) = 0
          IPR(513) = 0
C * CHECK FOR EXPECTED BIJVOET PAIR NUMBER CALCULATION DONE
          NFEXP = IPR(560)
          IF (NFEXP <= 0) THEN
            IF (PAR(168) < 0.0) THEN
              WRITE (LU6, 99995, IOSTAT = IOST)
C * DETERMINE THETAMAX
              THETAMAX = 0.0
              IEND     = -1
              DO WHILE (IEND <= 0)
                CALL PLA132 (IHO, IKO, ILO, FOK, SIG, SIGIW, CALI, FCK,
     1                       ACALS, BCALS)
                IF (IEND == 2) STOP 'INCONSISTENT CIF/FCF (PLA405)'
                IF (IEND /= 1 .AND.
     1            (IHO /= 0 .OR. IKO /= 0 .OR. ILO /= 0)) THEN
                  IF (GEN050 (TRMX, IHO, IKO, ILO, IH, IK, IL) == -1.0)
     1              CYCLE
                  STL = SQRT (GEN095 (PAR(191), IH, IK, IL))
                  ST  = STL * PAR(17)
                  IF (ST < 1.0) THEN
                    THETAMAX = MAX (THETAMAX, ASIN (ST) * RGBL(6))
                  END IF
                END IF
              END DO
              PAR(168) = THETAMAX
              WRITE (LU6, 99994, IOSTAT = IOST) THETAMAX
            END IF
C * RUN ASYM: SET FOR EXPECT MODE - CHECK FOR THETA(MAX) VALUE
            IF (PAR(168) > 0.0) THEN
              CALL PLA145 (1)
              IPR(408) = 0
            END IF
          END IF
C * SETUP CONNECTED SET
          IF (IGBL(3) /= 1) THEN
            CALL PLA287 (1, 1, 0)
          END IF
C * SET PAGE HEADER FOR LISTING
          PAGET = 'BIJVOET'
          CALL PLA262 (0)
          IPR(2) = -1
C * MODE = 1 : TWINROTMAT CASE
        ELSE IF (MODE == 1) THEN
C * EXTRACT EMBEDDED .ins & .hkl
          CALL SGSM (25, ICL, SGX, J, 0, IERR)
          CALL PLA345
          CALL SGSM (26, ICL, SGX, J, 0, IERR)
          IF (IPR(664) /= 0) THEN
            CLOSE (UNIT = LU25, STATUS = 'DELETE')
            IPR(664) = 0
          END IF
C * NO FCAL FOR -T OPTION
          IF (IGBL(9) < 1 .OR.
     1      (IGBL(9) > 12 .AND. IGBL(9) /= 25)) THEN
            WRITE (LU6, 99993, IOSTAT = IOST)
            IGGT = ' '
            RETURN
          END IF
C * TEST FOR -T OPTION
          IF (IGBL(3) == 30) THEN
            IPR(594) = 0
          ELSE
            IF (ABS (IGBL(8)) /= 3) THEN
              WRITE (LU6, 99993, IOSTAT = IOST)
              IGGT = ' '
              RETURN
            END IF
            IPR(594) = 1
C * SETUP CONNECTED SET
            CALL PLA287 (1, 1, 0)
          END IF
C * SET PAGE HEADER FOR LISTING
          PAGET    = 'TWINROTM'
          IGBL(6) = 25
          CALL PLA262 (0)
          WRITE (LU7, 99998, IOSTAT = IOST)
C * MODE = 0 : ANALYSIS OF VARIANCE CASE
        ELSE IF (MODE == 0) THEN
C * SET PAGE HEADER FOR LISTING
          PAGET    = 'ANALVAR'
          IPR(594) = 0
C * SETUP CONNECTED SET
          IF (IGBL(9) <= 0) CALL PLA287 (1, 1, 0)
          CALL PLA262 (0)
          IPR(2) = -1
        END IF
C * REPORT ON WEIGHTING
        IF (PAR(493) >= 0.0)
     1    WRITE (LU6, 99997, IOSTAT = IOST) PAR(493), PAR(494)
        WRITE (LU7, 99996, IOSTAT = IOST) RLWS(1)
      END IF
C * INIT
      IPR(132) = -1
      IEND     = -1
      NADR     = 0
      FOKM     = 0.0
      IND1     = 1
      IND2     = 2
      IND3     = 3
      NSYM     = IPR(48)
      NSYMH    = IPR(255)
      ICNTR    = IPR(257)
      HMAX     = -999
      KMAX     = -999
      LMAX     = -999
      SUMFOK   = 0.0
      SUMFCK   = 0.0
      SIGK     = 0.0
      ACAL     = 0.0
      BCAL     = 0.0
      ACALA    = 0.0
      BCALA    = 0.0
      ACALAF   = 0.0
      BCALAF   = 0.0
      DO I = 1, 90
        DO J = 1, 5
          AVIOSIG(I, J) = 0.0
        END DO
      END DO
C * TEST FOR HEXAGONAL LATTICE TYPE
      IF (IPR(259) == 5 .OR. IPR(259) == 6) THEN
        IHEXL = 1
      ELSE
        IHEXL = 0
      END IF
C * INPUT REFLECTION DATA ARE STORED BOTTOM UP IN THE VOID SCRATCH ARRAY
C * 3D POINTERS TO THOSE DATA ARE STORED TOP DOWN IN THE VOID SCRATCH ARRAY
C * REFLECTION FILE READ LOOP
      DO WHILE (IEND <= 0)
        CALL PLA132 (IHO, IKO, ILO, FOK, SIGI, SIGIW, CALI, FCKP, ACALS,
     1               BCALS)
        IF (IEND == 2) STOP 'INCONSISTENT CIF/FCF (PLA405)'
        IF (IEND /= 1 .AND.
     1    (IHO /= 0 .OR. IKO /= 0 .OR. ILO /= 0)) THEN
C * TRANSFORM AND ELIMINATE REFLECTIONS WITH NON-INTEGER INDICES
          IF (GEN050 (TRMX, IHO, IKO, ILO, IH, IK, IL) > 0.0) THEN
C * CALCULATE FCALC**2 FOR HKL I SIGMA(I) DATA
            IF (IGBL(9) <= 0 .OR. IPR(594) /= 0) THEN
              CALL PLA137 (IH, IK, IL, ACAL, BCAL, ACALA, BCALA,
     1          ACALAF, BCALAF, YUNK)
              FCK = (ACAL + ACALA) ** 2 + (BCAL + BCALA) ** 2
            END IF
            STL = SQRT (GEN095 (PAR(191), IH, IK, IL))
            ST  = STL * PAR(17)
            IF (ST < 1.0) THEN
              SIGI            = MAX (SIGI, 0.0)
              TH              = ASIN (ST) * RGBL(6)
              VOID(NADR + 1)  = IH
              VOID(NADR + 2)  = IK
              VOID(NADR + 3)  = IL
              VOID(NADR + 4)  = FOK
              VOID(NADR + 5)  = FCK
              VOID(NADR + 6)  = SIGI
              VOID(NADR + 7)  = TH
              VOID(NADR + 8)  = 0.0
              VOID(NADR + 9)  = 0.0
              VOID(NADR + 10) = 0.0
              VOID(NADR + 11) = MAX (0.0, FCKP)
              VOID(NADR + 12) = SIGIW
              SUMFOK          = SUMFOK + FOK
              SUMFCK          = SUMFCK + FCK
              NADR            = NADR   + NREC
C * COLLECT AV(I/SIGMA) VERSUS THETA STATISTICS
              IF (SIGI > 0.0) THEN
                ITHETA             = INT (TH) + 1
                AVIOSIG(ITHETA, 1) = AVIOSIG(ITHETA, 1) + FOK / SIGI
                AVIOSIG(ITHETA, 2) = AVIOSIG(ITHETA, 2) + 1.0
                AVIOSIG(ITHETA, 3) = AVIOSIG(ITHETA, 3) + FOK
                AVIOSIG(ITHETA, 4) = AVIOSIG(ITHETA, 4) + SIGI
              END IF
C * KEEP TRACK OF REFLECTION INDEX MAXIMA
              HMAX = MAX (HMAX, IABS (IH))
              KMAX = MAX (KMAX, IABS (IK))
C * HEXAGONAL LATTICE
              IF (IHEXL == 1) THEN
                HMAX = MAX (KMAX, HMAX, IABS (IH + IK))
                KMAX = HMAX
              END IF
              LMAX = MAX (LMAX, IABS (IL))
            END IF
          END IF
        END IF
      END DO
C * I / SIGMA AVERAGES
      DO I = 1, 90
        IF (AVIOSIG(I, 2) > 0.0) THEN
          AVIOSIG(I, 1) = AVIOSIG(I, 1) / AVIOSIG(I, 2)
          AVIOSIG(I, 3) = AVIOSIG(I, 3) / AVIOSIG(I, 2)
          AVIOSIG(I, 4) = AVIOSIG(I, 4) / AVIOSIG(I, 2)
          AVIOSIG(I, 5) = AVIOSIG(I, 3) / AVIOSIG(I, 4)
        END IF
      END DO
C * SCALE AND ADD WEIGHTS
      IF (NADR > 0) THEN
        NREF = NADR / NREC
C * SCALE FOBS**2 FOR HKL I SIG(I) DATA
        IF (IGBL(9) <= 0) THEN
          SCHAAL = SUMFCK / SUMFOK
        ELSE
          SCHAAL = 1.0
        END IF
        NADR = 0
        DO I = 1, NREF
          FOK  = VOID(NADR + 4) * SCHAAL
          FOKM = MAX (FOKM, FOK)
          FCK  = VOID(NADR + 5)
          SIG  = VOID(NADR + 6) * SCHAAL
          SIGK = VOID(NADR + 12)**2
          FCKP = VOID(NADR + 11)
C * INCLUDE L.S. WEIGHT PARAMETERS IN SIGMAI
          IF (SIG > 0.0) THEN
            VOID(NADR + 8) = MAX ((FOK - FCKP) / SIG, 0.0)
            VOID(NADR + 9) = (FOK - FCKP) / SQRT (SIGK)
          END IF
          VOID(NADR + 4) = FOK
          VOID(NADR + 6) = SIG
          NADR           = NADR + NREC
        END DO
C * TETRAGONAL LATTICE
        IF (IPR(259) == 4) THEN
          HMAX = MAX (HMAX, KMAX)
          KMAX = HMAX
C * CUBIC LATTICE
        ELSE IF (IPR(259) == 7) THEN
          HMAX = MAX (HMAX, KMAX, LMAX)
          KMAX = HMAX
          LMAX = HMAX
        END IF
        SCL = 10 ** (INT (ALOG (10000000 / FOKM) / ALOG (10.0)))
        IF (NOPT == 2) THEN
          IF (MODE == 0) CALL PLA409 (NOPT)
          RETURN
        END IF
C * INCLUDE ANALYSIS OF VARIANCE
 
        CALL PLA412 (MODE, NOPT)
        IF (MODE /= 0 .AND. IPR(493) .NE. 8) THEN
C * ANALYSE FOR TWINNING (+ BIJVOET PAIRS)
          IF (MODE > 0) THEN
            IF (MODE == 1) THEN
C * USE REFLECTION DATA CALCULATED FROM CIF DATA (GRAPHICS MODE)
              IPR(608) = 1
              CALL PLA414 (1)
            ELSE
C * USE REFLECTION DATA CALCULATED FROM CIF DATA (NON-GRAPHICS MODE)
              IPR(608) = 1
              CALL PLA414 (2)
C * CHECK FOR TWIN CORRECTED FCF (NON-GRAPHICS MODE)
              IF (IGBL(9) > 0 .AND. IGBL(9) < 13) THEN
                IPR(608) = 0
                CALL PLA414 (2)
              END IF
C * FCF BASED (=0) ON CIF DATA (=1)
              IPR(594) = 1
C * STUDENT-T MODE
              IPR(613) = 1
C * SLOPE
              IPR(593) = 1
C * RECYCLE STUDENT-T
              IPR(617) = 1
C * AUTO NU
              PAR(488) = 0.0
              CALL PLA421
            END IF
C * ANALYSIS OF BIJVOET-PAIRS
          ELSE IF (MODE == -1) THEN
C * HANDLE JANA & MOPRO
            IF (IGBL(9) > 0 .AND. IGBL(9) < 13) THEN
              CALL PLA421
            ELSE
              WRITE (LU6, 99992, IOSTAT = IOST)
            END IF
          END IF
        END IF
      ELSE
        WRITE (LU6, 99999, IOSTAT = IOST)
      END IF
      IGGT = ' '
      RETURN
99999 FORMAT (/, ':: No Reflections found')
99998 FORMAT (/, 'TwinRotMat: Analysis of the Fo/Fc CIF for Unaccounted'
     1        ,' (Non)Merohedral Twinning', /, 79('='), /)
99997 FORMAT (/, ':: Weight W1, W2 =', 2F10.4)
99996 FORMAT (/, A, /)
99995 FORMAT (/, ':: Determine Theta(max) Dataset')
99994 FORMAT (/, ':: Theta(max) =', F6.2)
99993 FORMAT (/, ':: Sorry: CIF & FCF (LIST 4 or 8) style data required'
     1        , ' for running TwinRotMat', /)
99992 FORMAT (/,
     1   ':: Bijvoet/Hooft Analysis with SHELXL/FCF(hklf4/LIST4)',
     2   ' Only !', /)
99991 FORMAT (/, ':: Sorry, No Analysis for JANA(F), CrystalStructure',
     1  ' data.', /)
99990 FORMAT (/, ':: Sorry, No Analysis when Weight Parameter A ',
     1        'Negative', /)
      END SUBROUTINE PLA405
 
      SUBROUTINE PLA406 (X, Y, DSH, PEN)
      IMPLICIT NONE
      REAL :: X
      REAL :: Y
      REAL :: DSH
      REAL :: PEN
      IF (PEN >= 0) CALL GGIP (0.0, PEN, 0.0, 0)
      CALL GGIP (X,       Y + DSH, 0.0, 3)
      CALL GGIP (X + DSH, Y,       0.0, 2)
      CALL GGIP (X,       Y - DSH, 0.0, 2)
      CALL GGIP (X - DSH, Y,       0.0, 2)
      CALL GGIP (X,       Y + DSH, 0.0, 2)
      RETURN
      END SUBROUTINE PLA406
 
      MODULE npplot
      SAVE
      REAL :: YCC
      REAL :: YINT
      REAL :: YSLOPE
      END MODULE npplot
 
      SUBROUTINE PLA407 (MODUS, SCAL, IDTYP1, IDTYP2, LU)
C * SCATTER PLOT ROUTINE
      USE files
      USE parameters
      USE cchar
      USE analysis
      USE npplot
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: MODE
      INTEGER :: MODUS
      INTEGER :: IDTYP1
      INTEGER :: IDTYP2
      INTEGER :: IYELLOW
      REAL :: X
      REAL :: Y
      REAL :: YM
      REAL :: YP
      REAL :: XOR
      REAL :: YOR
      REAL :: PEN
      REAL :: DSH
      REAL :: FCK
      REAL :: FOK
      REAL :: VRT
      REAL :: VAL4
      REAL :: VAL5
      REAL :: VAL6
      REAL :: TICK
      REAL :: FCKM
      REAL :: FOKM
      REAL :: SCAL
      REAL :: HORS
      REAL :: VERT
      REAL :: SCHAAL
      REAL :: SCALCAL
      REAL :: SCALOBS
      CHARACTER(len=12) :: THOR
      CHARACTER(len=12) :: TVER
C * FCF REFLECTION DATA STORAGE SCHEME
C * VOID(NADR + 1)  = IH
C * VOID(NADR + 2)  = IK
C * VOID(NADR + 3)  = IL
C * VOID(NADR + 4)  = FOK
C * VOID(NADR + 5)  = FCK (FROM CIF)
C * VOID(NADR + 6)  = MAX (SIG, 0.0)
C * VOID(NADR + 7)  = TH
C * VOID(NADR + 8)  = (FOK - FCK) / SIGI
C * VOID(NADR + 9)  = (FOK - FCK) / SIGIW
C * VOID(NADR + 10) =
C * VOID(NADR + 11) = FCK' (FROM FCF)
C * VOID(NADR + 12) = SIGIW
C * HANDLE POOR VISIBILITY OF YELLOW ON WHITE BACKGROUND
      IF (IGBL(68) == 1 .OR. IGBL(149) == 1) THEN
        IYELLOW = 6
      ELSE
        IYELLOW = 5
      END IF
      MODE = MODUS
C * SECECT I OR F PLOTS
      IF (MODE == 0) MODE = - IPR(711)
C * DUMMY INSTRUCTION
      N = IDTYP1 + IDTYP2
C * MODE = -1: F(OBS)  VERSUS F(CALC)
C * MODE =  0: I(OBS)  VERSUS I(CALC)
C * MODE =  1: I(OBS)1 VERSUS I(OBS)2
      IF (MODE == -1) THEN
C * CHECK FOR 'LOGLOG' or 'LINEAR'
        IF (IPR(633) == 0) THEN
          THOR = 'F(calc)'
          TVER = 'F(obs)'
        ELSE
          THOR = 'log[F(calc)]'
          TVER = 'log[F(obs)]'
        END IF
      ELSE IF (MODE == 0) THEN
C * CHECK FOR 'LOGLOG' or 'LINEAR'
        IF (IPR(633) == 0) THEN
          THOR = 'I(calc)'
          TVER = 'I(obs)'
        ELSE
          THOR = 'log[I(calc)]'
          TVER = 'log[I(obs)]'
        END IF
      ELSE IF (MODE == 1) THEN
        IF (SPGRA /= SPGRB) THEN
          WRITE (LU, 99999, IOSTAT = IOST) SPGRA, SPGRB
C * DUMMY
          IF (IOST == -999) RETURN
        END IF
C * CHECK FOR 'LOGLOG' or 'LINEAR'
        IF (IPR(633) == 0) THEN
          THOR = 'I(obs)1'
          TVER = 'I(obs)2'
        ELSE
          THOR = 'log[I(obs)1]'
          TVER = 'log[I(obs)2]'
        END IF
      ELSE
        RETURN
      ENDIF
      LINE = TVER//' versus '//THOR//' Scatter Plot'
      HORS = 25.0
      VERT = 25.0
      XOR  = 1.0
      YOR  = 1.0
C * OPEN WINDOW
      CALL GGIP (HORS, VERT, 0.0, 1)
C * OUTLINE FRAME
      CALL PLA110 (HORS, VERT, -1)
      CALL GGIP (0.0, 1.0, 0.0, 0)
      CALL PLA110 (HORS, VERT, -1)
      CALL PLA439 (0.0, LINE, 45, 0.35, IYELLOW, 2, 5.0,
     1  VERT - 0.6)
      IF (IPR(633) == 0) THEN
        CALL PLA439 (0.0,  THOR, 8, 0.35, 1, 1, HORS - 2.3, 0.4)
        CALL PLA439 (90.0, TVER, 8, 0.35, 1, 1, 0.6, VERT - 2.0)
      ELSE IF (IPR(633) == 1) THEN
        CALL PLA439 (0.0, 'RED dots for I(obs) < 2 * Sig(I(obs))',
     1               36, 0.35, 2, 2, 3.0, VERT - 3.0)
        CALL PLA439 (0.0,  THOR, 12, 0.35, 1, 1, HORS - 4.1,
     1               0.4)
        CALL PLA439 (90.0, TVER, 12, 0.35, 1, 1, 0.6, VERT - 3.8)
      END IF
C * MOVE ORIGIN
      CALL GGIP (XOR, YOR, 0.0, -3)
C * VERTICAL AND HORIZONTAL AXES
 
      CALL GGIP (0.0, VERT - YOR, 0.0, 2)
      CALL GGIP (0.0, 0.0, 0.0, 3)
      CALL GGIP (HORS - XOR, 0.0, 0.0, 2)
      DSH  = 0.06
      NADR = 0
      FOKM = 0.0
      FCKM = 0.0
C * GET MAXIMA OF FOK & FCK
      DO I = 1, NREF
        FOK  = VOID(NADR + 4)
        IF (MODE == 1) THEN
          FCK  = VOID(NADR + 5)
        ELSE
          FCK  = VOID(NADR + 11)
        END IF
        FOKM = MAX (FOKM, FOK)
        FCKM = MAX (FCKM, FCK)
        NADR = NADR + NREC
      END DO
C * CHECK FOR 'LOGLOG' or 'LINEAR'
      IF (IPR(633) == 0) THEN
        IF (MODE == -1) THEN
          FOKM = SQRT (FOKM)
          FCKM = SQRT (FCKM)
        END IF
        SCALOBS = (VERT - YOR) / FOKM
        SCALCAL = (HORS - XOR) / FCKM
      ELSE IF (IPR(633) == 1) THEN
        SCALOBS = (VERT - YOR) / (LOG10 (FOKM) + 1)
        SCALCAL = (HORS - XOR) / (LOG10 (FCKM) + 1)
      ENDIF
      SCHAAL = MIN (SCALOBS, SCALCAL)
C * TICKS
C * CHECK FOR 'LOGLOG' or 'LINEAR'
      IF (IPR(633) == 1) THEN
        TICK = 1.0
        DO WHILE (TICK * SCHAAL < HORS - XOR)
          N    = 10 ** (NINT (TICK - 1))
          X    = TICK * SCHAAL
          TICK = TICK + 1.0
          WRITE (LINE(1:8), 99996, IOSTAT = IOST) N
          CALL GGIP (X, 0.0, 0.0, 3)
          CALL GGIP (X, 0.3, 0.0, 2)
          CALL GGIP (0.0, X, 0.0, 3)
          CALL GGIP (0.3, X, 0.0, 2)
          IF (N > 10000000) EXIT
          CALL PLA439 (0.0,  LINE, 8, 0.3, 1, 1, X - 2.2, 0.1)
          CALL PLA439 (90.0, LINE, 8, 0.3, 1, 1, 0.4, X - 2.2)
        END DO
      END IF
C * SCALE = 1 LINE
      CALL GGIP (0.0, 2.0, 0.0, 0)
      CALL GGIP (0.0, 0.0, 0.0, 3)
      CALL GGIP (HORS - XOR, VERT - YOR, 0.0, 2)
      CALL GGIP (0.0, 1.0, 0.0, 0)
      NADR = 0
      DO I = 1, NREF
        VAL4 = VOID(NADR + 4)
        IF (MODE == 1) THEN
          VAL5 = VOID(NADR + 5)
        ELSE
          VAL5 = VOID(NADR + 11)
        END IF
        IF (IPR(634) == 1) THEN
          VAL6 = VOID(NADR + 6)
        ELSE
          VAL6 = 0.0
        END IF
        IF (MODE == -1) THEN
          VAL4 = SQRT (MAX (0.0, VAL4))
          VAL5 = SQRT (MAX (0.0, VAL5))
          IF (VAL5 > 0.0) THEN
            VAL6 = VAL6 / (2.0 * VAL5)
          ELSE
            VAL6 = 0.0
          END IF
        END IF
C * CHECK FOR 'LOGLOG' or 'LINEAR'
        IF (IPR(633) == 0) THEN
          X  =            VAL5         * SCHAAL
          Y  = MAX (0.0,  VAL4         * SCHAAL)
          YP = MAX (0.0, (VAL4 + VAL6) * SCHAAL)
          YM = MAX (0.0, (VAL4 - VAL6) * SCHAAL)
        ELSE IF (IPR(633) == 1) THEN
          IF (VAL4 > 0.0 .AND. VAL4 - VAL6 > 0.0 .AND.
     1        VAL5 > 0.0) THEN
            X  =           (1.0 + LOG10 (VAL5))        * SCHAAL
            Y  =           (1.0 + LOG10 (VAL4))        * SCHAAL
            YP = MAX (0.5, (1.0 + LOG10 (VAL4 + VAL6)) * SCHAAL)
            YM = MAX (0.5, (1.0 + LOG10 (VAL4 - VAL6)) * SCHAAL)
          ELSE
            X  = 0.0
            Y  = 0.0
            YP = 0.0
            YM = 0.0
          END IF
        ENDIF
        X = MIN (X,  HORS - XOR -0.1)
        Y = MIN (Y,  VERT - YOR -0.1)
        IF (X > 0.0 .AND. Y > 0.0) THEN
          IF (IPR(634) == 1) THEN
            CALL GGIP (X, YP, 0.0, 3)
            CALL GGIP (X, YM, 0.0, 2)
          END IF
C * CHECK FOR REVERSE DISPLAY (BLACK/WHITE BACKGROUND)
          IF (VOID(NADR + 4) < 2 * VOID(NADR + 6)) THEN
            PEN = 2
          ELSE
            PEN = FLOAT (IYELLOW)
          END IF
C * PLOT MARKER
          CALL PLA406 (X, Y, DSH, PEN)
          CALL GGIP (0.0, 1.0, 0.0, 0)
        END IF
        NADR = NADR + NREC
      END DO
      VRT = VERT
      CALL GGIP (-XOR, -YOR, 0.0, -3)
      VRT = VRT - 0.75
      CALL PLA439 (0.0, FILENAMES(1)(1:25), 25, 0.35, 1, 1, VERT + 0.2,
     1             VRT)
      IF (MODE == 1) THEN
        VRT = VRT - 0.75
        CALL PLA439 (0.0, FILENAMES(2)(1:25), 25, 0.35, 1, 1,
     1               VERT + 0.2, VRT)
      END IF
      VRT = VRT - 0.75
      IF (IPR(633) == 0) THEN
        WRITE (LINE, 99995, IOSTAT = IOST) THOR(1:8), FCKM
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.75
        WRITE (LINE, 99995, IOSTAT = IOST) TVER(1:8), FOKM
        CALL PLA439 (0.0, LINE(1:26), 25, 0.35, 1, 1, VERT + 0.2, VRT)
C * CHECK FOR 'LOGLOG'
      ELSE IF (IPR(633) == 1) THEN
        IF (MODE == 0) THEN
          WRITE (LINE, 99995, IOSTAT = IOST) 'I(calc) ', FCKM
          CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
          VRT = VRT - 0.75
          WRITE (LINE, 99995, IOSTAT = IOST) 'I(obs)  ', FOKM
          CALL PLA439 (0.0, LINE(1:26), 25, 0.35, 1, 1, VERT + 0.2, VRT)
          VRT = VRT - 0.75
        ELSE
          WRITE (LINE, 99995, IOSTAT = IOST) 'I(obs)1 ', FCKM
          CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
          VRT = VRT - 0.75
          WRITE (LINE, 99995, IOSTAT = IOST) 'I(obs)2 ', FOKM
          CALL PLA439 (0.0, LINE(1:26), 25, 0.35, 1, 1, VERT + 0.2, VRT)
          VRT = VRT - 0.75
        END IF
        WRITE (LINE, 99994, IOSTAT = IOST) THOR(1:12), LOG10 (FCKM)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.75
        WRITE (LINE, 99994, IOSTAT = IOST) TVER(1:12), LOG10 (FOKM)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
      END IF
      VRT = VRT - 0.75
      IF (MODE <= 0) THEN
        N = 16
        DO I = 1, 6
          CELLA(I) = PAR(100 + I)
        END DO
        CELLA(7) = PAR(98)
        NREFF1   = NREF
        SCAL     = 1.0
      ELSE
        N = 25
      END IF
      WRITE (LINE, '(''N(refl)'', 2I9)', IOSTAT = IOST) NREFF1, NREFF2
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.75
      WRITE (LINE, '(''N(plot) '',  I8)', IOSTAT = IOST) NREF
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.75
      WRITE (LINE, '(''Scale'', 12X, F8.4)', IOSTAT = IOST) SCAL
      CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.90
      WRITE (LINE, '(''NP-Plot-CC'', 7X, F8.4)', IOSTAT = IOST) YCC
      IF (MODE > 0) WRITE (6, 99998, IOSTAT = IOST) LINE(1:75)
      CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''NP-Plot-INTERCEPT'', F8.4)', IOSTAT = IOST) YINT
      IF (MODE > 0) WRITE (6, 99998, IOSTAT = IOST) LINE(1:75)
      CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, 99993, IOSTAT = IOST) YSLOPE
      IF (MODE > 0) WRITE (6, 99998) LINE(1:75)
      CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.90
      WRITE (LINE, '(''A       '', 2F8.4)', IOSTAT = IOST)
     1   CELLA(1), CELLB(1)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''B       '', 2F8.4)', IOSTAT = IOST)
     1  CELLA(2), CELLB(2)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''C       '', 2F8.4)', IOSTAT = IOST)
     1  CELLA(3), CELLB(3)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''Alpha   '', 2F8.2)', IOSTAT = IOST)
     1  CELLA(4), CELLB(4)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''Beta    '', 2F8.2)', IOSTAT = IOST)
     1  CELLA(5), CELLB(5)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''Gamma   '', 2F8.2)', IOSTAT = IOST)
     1  CELLA(6), CELLB(6)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      VRT = VRT - 0.70
      WRITE (LINE, '(''Volume  '', 2F8.1)', IOSTAT = IOST)
     1  CELLA(7), CELLB(7)
      CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
      IF (MODE <= 0) THEN
        VRT = VRT - 0.90
        WRITE (LINE, '(''R1  (CIF)'', F7.4)', IOSTAT = IOST) PAR(173)
        CALL PLA439 (0.0, LINE(1:26), 16, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.75
        WRITE (LINE, '(''wR2 (CIF)'', F7.4)', IOSTAT = IOST) PAR(174)
        CALL PLA439 (0.0, LINE(1:26), 16, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.75
        WRITE (LINE, '(''S   (CIF)'', F7.4)', IOSTAT = IOST) PAR(299)
        CALL PLA439 (0.0, LINE(1:26), 16, 0.35, 1, 1, VERT + 0.2, VRT)
        IF (PAR(197) > 0.0) THEN
          VRT = VRT - 0.75
          WRITE (LINE, '(''R(int)   '', F7.4)', IOSTAT = IOST) PAR(197)
          CALL PLA439 (0.0, LINE(1:16), 16, 0.35, 1, 1, VERT + 0.2, VRT)
        END IF
      ELSE
        VRT = VRT - 0.90
        WRITE (LINE, '(''SPGR1'', 4X, A)', IOSTAT = IOST) SPGRA
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''SPGR2'', 4X, A)', IOSTAT = IOST) SPGRB
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.90
        WRITE (LINE, '(''R_A     '', 2F8.4)', IOSTAT = IOST)
     1    RCELLA(1), RCELLB(1)
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''R_B     '', 2F8.4)', IOSTAT = IOST)
     1    RCELLA(2), RCELLB(2)
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''R_C     '', 2F8.4)', IOSTAT = IOST)
     1    RCELLA(3), RCELLB(3)
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''R_Alpha '', 2F8.2)', IOSTAT = IOST)
     1    RCELLA(4), RCELLB(4)
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''R_Beta  '', 2F8.2)', IOSTAT = IOST)
     1    RCELLA(5), RCELLB(5)
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''R_Gamma '', 2F8.2)', IOSTAT = IOST)
     1    RCELLA(6), RCELLB(6)
        CALL PLA439 (0.0, LINE(1:N), N, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.90
        WRITE (LINE, '(''('', 3F7.3, '')'')', IOSTAT = IOST)
     1    (TRNSA(1, J), J = 1, 3)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''('', 3F7.3, '') A'')', IOSTAT = IOST)
     1    (TRNSA(2, J), J = 1, 3)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''('', 3F7.3, '')'')', IOSTAT = IOST)
     1    (TRNSA(3, J), J = 1, 3)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.90
        WRITE (LINE, '(''('', 3F7.3, '')'')', IOSTAT = IOST)
     1    (TRNSB(1, J), J = 1, 3)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''('', 3F7.3, '') B'')', IOSTAT = IOST)
     1    (TRNSB(2, J), J = 1, 3)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        VRT = VRT - 0.70
        WRITE (LINE, '(''('', 3F7.3, '')'')', IOSTAT = IOST)
     1    (TRNSB(3, J), J = 1, 3)
        CALL PLA439 (0.0, LINE(1:25), 25, 0.35, 1, 1, VERT + 0.2, VRT)
        WRITE (LINE, '(''Pearsons-CC = '', F7.4)') PAR(565)
        CALL PLA439 (0.0, LINE(1:20), 20, 0.35, 5, 1, HORS -XOR - 5.5,
     1    2.0)
      END IF
      CALL GGIP (0.0, 0.0, 0.0, -1)
      RETURN
99999 FORMAT (/, ':: Space Groups Differ: ', A, ' & ', A, /)
99998 FORMAT (':: ', A)
99996 FORMAT (I8)
99995 FORMAT (A, '-Max ', F12.2)
99994 FORMAT (A, '-Max', F9.4)
99993 FORMAT ('NP-Plot-SLOPE', 4X, F8.4)
      END SUBROUTINE PLA407
 
      SUBROUTINE PLA408 (NRPLOT)
C * PLOT I/Sig(I) versus I etc.
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE analysis
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: IY
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: NTH
      INTEGER :: IAVMX
      INTEGER :: NRPLOT
      INTEGER :: IYELLOW
      REAL :: X
      REAL :: Y
      REAL :: YA
      REAL :: YB
      REAL :: PEN
      REAL :: FOK
      REAL :: VRT
      REAL :: DSH
      REAL :: SIG
      REAL :: XORG
      REAL :: YORG
      REAL :: SIGA
      REAL :: SIGB
      REAL :: HORS
      REAL :: VERT
      REAL :: FOKM
      REAL :: TICK
      REAL :: YUNK
      REAL :: XIOSM
      REAL :: TICKM
      REAL :: TICKS
      REAL :: VERTO
      REAL :: SIGMX
      REAL :: HORSO
      REAL :: SCALHOR
      REAL :: SCALVER
      REAL, DIMENSION(5) :: AVMX
      REAL, DIMENSION(5) :: SKALVER
C * HANDLE POOR VISIBILITY OF YELLOW ON WHITE BACKGROUND
      IF (IGBL(68) == 1 .OR. IGBL(149) == 1) THEN
        IYELLOW = 6
      ELSE
        IYELLOW = 5
      END IF
      HORS = 25.0
      VERT = 25.0
      XORG = 1.0
      YORG = 1.0
      DSH  = 0.1
C * OPEN WINDOW
      CALL GGIP (HORS, VERT, 0.0, 1)
C * OUTLINE FRAME
      CALL PLA110 (HORS, VERT, -1)
      CALL GGIP (0.0, 1.0, 0.0, 0)
      CALL PLA110 (HORS, VERT, -1)
      IF (NRPLOT == 2) THEN
        LINE = 'I/Sig versus Log(I) Plot - (Diederichs Plot)'
      ELSE IF (NRPLOT == 3) THEN
        LINE = 'I/SigW versus Log(I) Plot - (Diederichs Plot)'
      ELSE IF (NRPLOT == 4) THEN
        LINE = 'Sig & SigW versus Log(I) Plot'
      ELSE IF (NRPLOT == 5) THEN
        LINE = 'Log(Sig) versus Log(I) Plot'
      ELSE IF (NRPLOT == 6) THEN
        LINE = 'Sig versus Sqrt(I) Plot'//
     1         ' + POISSON Sig(I) = SQRT(I) LINE'
      ELSE IF (NRPLOT == 7) THEN
        LINE = '<I/Sig> and <I>/<Sig> versus Theta'
        NTH  = 90
        DO I = 90, 1, -1
          IF (AVIOSIG(I, 2) > 0.0) THEN
            NTH = I
            EXIT
          END IF
        END DO
        AVMX(1) = 0.0
        AVMX(5) = 0.0
        DO I = 1, NTH
          AVMX(1) = MAX (AVMX(1), AVIOSIG(I, 1))
          AVMX(5) = MAX (AVMX(5), AVIOSIG(I, 5))
        END DO
      ENDIF
      CALL PLA439 (0.0, LINE, 60, 0.35, IYELLOW, 2, 4.5,
     1  VERT - 0.6)
      VRT = VERT - 0.2
C * REPORT TITL
      WRITE (LINE, 99993, IOSTAT = IOST) JID(1:8)
      IF (IOST == 0) THEN
        VRT = VRT - 0.45
        CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, HORS + 0.1, VRT)
      END IF
C * REPORT FVAR
      IF (PAR(74) /= 0.0) THEN
        WRITE (LINE, 99992, IOSTAT = IOST) PAR(74)
        IF (IOST == 0) THEN
          VRT = VRT - 0.45
          CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, HORS + 0.1, VRT)
        END IF
      END IF
C * REPORT EXTI
      IF (PAR(229) > 0.0) THEN
        WRITE (LINE, 99991, IOSTAT = IOST) PAR(229)
        IF (IOST == 0) THEN
          VRT = VRT - 0.45
          CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, HORS + 0.1, VRT)
        END IF
      END IF
C * REPORT SHELXL A & B WEIGHT PARAMETERS
      IF (PAR(493) >= 0.0) THEN
        DO I = 0, 5
          WRITE (LINE, 99996, IOSTAT = IOST)
     1      CHAR (ICHAR ('a') + I), PAR(493 + I)
          IF (IOST == 0) THEN
            VRT = VRT - 0.45
            CALL PLA439 (0.0, LINE, 25, 0.35, 1, 1, HORS + 0.1, VRT)
          END IF
        END DO
      END IF
C * MOVE ORIGIN
      CALL GGIP (XORG, YORG, 0.0, -3)
      HORSO = HORS - XORG
      VERTO = VERT - YORG
C * VERTICAL AND HORIZONTAL AXES
      CALL GGIP (0.0, VERTO, 0.0, 2)
      CALL GGIP (0.0, 0.0,   0.0, 3)
      CALL GGIP (HORSO, 0.0, 0.0, 2)
      VRT = VERTO - 1.5
C * REPORT DIEDERICHS PLOT & REFERENCE
      IF (NRPLOT == 2 .OR. NRPLOT == 3) THEN
        LINE = 'See K. Diederichs (2010). Acta Cryst., D66, 733-740'
        CALL PLA439 (0.0, LINE, 51, 0.30, 1, 1, 0.75, VRT)
        VRT = VRT - 1.0
      END IF
C * REPORT DATA SET INFO
      LINE = 'Data ............... '//FNLU16(1:KNM16)
      CALL PLA439 (0.0, LINE, KNM16 + 21, 0.30, 1, 1, 0.75, VRT)
      VRT  = VRT - 0.5
      N    = MIN (NCIF(18), 59)
      LINE = 'Device Type ........ '//CCIF(18)(1:N)
      CALL PLA439 (0.0, LINE, N + 21, 0.30, 1, 1, 0.75, VRT)
      VRT  = VRT - 0.5
      N    = MIN (NCIF(20), 59)
      LINE = 'Data Collection .... '//CCIF(20)(1:N)
      CALL PLA439 (0.0, LINE, N + 21, 0.30, 1, 1, 0.75, VRT)
      VRT  = VRT - 0.5
      N    = MIN (NCIF(21), 59)
      LINE = 'Data Reduction ..... '//CCIF(21)(1:N)
      CALL PLA439 (0.0, LINE, N + 21, 0.30, 1, 1, 0.75, VRT)
      VRT  = VRT - 0.5
      N    = MIN (NCIF(19), 59)
      LINE = 'Absorb Details ..... '//CCIF(19)(1:N)
      CALL PLA439 (0.0, LINE, N + 21, 0.30, 1, 1, 0.75, VRT)
      VRT  = VRT - 0.5
      N    = MIN (NCIF(22), 59)
      LINE = 'Structure Refinement '//CCIF(22)(1:N)
      CALL PLA439 (0.0, LINE, N + 21, 0.30, 1, 1, 0.75, VRT)
      IF (NRPLOT == 4 .OR. NRPLOT == 5) THEN
        VRT  = VRT - 1.0
        LINE = 'Yellow Dots      = Sig(I)'
        CALL PLA439 (0.0, LINE, 25, 0.30, 1, 1, 0.75, VRT)
        CALL PLA439 (0.0, LINE, 11, 0.30, 5 + IGBL(68), 1, 0.75, VRT)
        VRT  = VRT - 0.5
        LINE = 'White/Black Dots = SigW(I)'
        CALL PLA439 (0.0, LINE, 26, 0.30, 1, 1, 0.75, VRT)
      END IF
C * <I/sigma> AND <I>/<sigma(I> VERSUS THETA PLOT
      VRT = VRT - 0.5
      IF (NRPLOT == 7) THEN
        SCALHOR = VERTO / NTH
        DO J = 1, 5, 4
          SKALVER(J) = (VERTO - 6.0) / AVMX(J)
          IF (J == 1) THEN
            PEN = 1.0
          ELSE
            PEN = FLOAT (IYELLOW)
          END IF
          IY  = 0
          CALL GGIP (0.0, PEN, 0.0, 0)
          CALL GGIP (0.0, 0.0, 0.0, 3)
          DO I = 1, NTH
            X  = I * SCALHOR
            Y  = AVIOSIG(I, J) * SKALVER(J)
            IF (Y == 0.0) CYCLE
            IF (IY > 0) CALL GGIP (X, Y, 0.0, 2)
C * PLOT MARKER
            CALL PLA406 (X, Y, DSH, -1.0)
            CALL GGIP (X, Y, 0.0, 3)
            IF (Y > 0.0) IY = 1
          END DO
        END DO
C * PLOT TWO-SIGMA NOISE LEVEL
        Y = 2.0 * SKALVER(1)
        CALL GGIP (0.0, 2.0, 0.0, 0)
        CALL GGIP (0.0,   Y, 0.0, 3)
        CALL GGIP (VERTO, Y, 0.0, 2)
        LINE(1:21) = 'Two Sigma Noise Level'
        CALL PLA439 (0.0, LINE, 21, 0.3, 1, 1, 1.0, Y + 0.2)
C * HORIZONTAL IICKS
        CALL GGIP (0.0, 1.0, 0.0, 0)
        DO I = 5, NTH, 5
          X = I * SCALHOR
          Y = 0.0
          CALL GGIP (X, Y,       0.0, 3)
          CALL GGIP (X, Y - 0.3, 0.0, 2)
          WRITE (LINE(1:8), 99999, IOSTAT = IOST) I
          CALL PLA439 (0.0, LINE, 8, 0.25, 1, 1, X - 1.8, -0.3)
        END DO
        CALL PLA439 (0.0, 'Theta', 5, 0.3, 1, 1, VERTO - 1.3, - 0.8)
C * VERTICAL TICKS
        DO J = 1, 5, 4
          IF (J == 1) THEN
            CALL GGIP (0.0, 1.0, 0.0, 0)
          ELSE
            CALL GGIP (0.0, FLOAT (IYELLOW), 0.0, 0)
          END IF
 
          IAVMX = INT (AVMX(J) + 1)
          Y     = IAVMX * SKALVER(J)
          IF (J == 1) THEN
            X = 0.0
            LINE(1:11) = '<I/Sig>  '
            CALL PLA439 (0.0, LINE, 9, 0.4, J, 1, X + 0.1, Y + 1.0)
          ELSE
            X = VERTO
            LINE(1:20) = '<I>/<Sig>   R(sig)'
            CALL PLA439 (0.0, LINE, 18, 0.4, IYELLOW, 1, X + 0.1,
     1        Y + 1.0)
          END IF
          DO I = 10, IAVMX, 10
            Y = I * SKALVER(J)
            CALL GGIP (X,       Y, 0.0, 3)
            CALL GGIP (X + 0.3, Y, 0.0, 2)
            WRITE (LINE, 99990, IOSTAT = IOST) I, 1.0 / FLOAT (I)
            IF (J == 1) THEN
              CALL PLA439 (0.0, LINE,  3, 0.25, J, 1, X + 0.4, Y)
            ELSE
              CALL PLA439 (0.0, LINE, 23, 0.25, IYELLOW, 1, X + 0.4, Y)
            END IF
          END DO
        END DO
        CALL GGIP (0.0, 0.0, 0.0, -1)
        RETURN
      ELSE
        NADR  = 0
        FOKM  = 0.0
        XIOSM = 0.0
        SIGMX = 0.0
        N     = 0
        DO I = 1, NREF
          FOK = VOID(NADR + 4)
          SIG = 0.0
C * DETERMINE WHETHER TO SCALE USING  SIG(I) = 6 OR SIGW(I) = 12
          IF (NRPLOT == 2) THEN
            SIG = VOID(NADR + 6)
          ELSE IF (NRPLOT == 3) THEN
            SIG = VOID(NADR + 12)
          ELSE IF (NRPLOT == 4) THEN
            SIG = VOID(NADR + 6)
          ELSE IF (NRPLOT == 5) THEN
            SIG = VOID(NADR + 12)
          ELSE IF (NRPLOT == 6) THEN
            SIG = VOID(NADR + 6)
          END IF
          IF (SIG > 0.0) THEN
            IF (NRPLOT == 4) THEN
              SIGMX = MAX (SIGMX, SIG)
              FOKM  = MAX (FOKM, FOK)
            ELSE IF (NRPLOT == 5) THEN
              SIGMX = MAX (SIGMX, SIG)
              FOKM  = MAX (FOKM, FOK)
            ELSE IF (NRPLOT == 6) THEN
              SIGMX = MAX (SIGMX, SIG)
              FOKM  = MAX (FOKM, FOK)
            ELSE IF (NRPLOT == 2 .OR. NRPLOT == 3) THEN
              IF (FOK / SIG < PAR(485)) THEN
                XIOSM = MAX (XIOSM, FOK / SIG)
                FOKM  = MAX (FOKM, FOK)
              ELSE
                N = N + 1
                IF (N == 1) THEN
                  WRITE (LINE, 99994, IOSTAT = IOST) PAR(485)
                  VRT = VRT - 0.32
                  CALL PLA439 (0.0, LINE, 56, 0.25, 5, 1, 0.75, VRT)
                  VRT = VRT - 0.03
                END IF
                IF (N <= 50) THEN
                  IF (N == 50) THEN
                    WRITE (LINE, 99997, IOSTAT = IOST)
                  ELSE
                    IH = NINT (VOID(NADR + 1))
                    IK = NINT (VOID(NADR + 2))
                    IL = NINT (VOID(NADR + 3))
                    WRITE (LINE, 99998, IOSTAT = IOST)
     1                IH, IK, IL, FOK, SIG, FOK / SIG
                  END IF
                  VRT = VRT - 0.33
                  CALL PLA439 (0.0, LINE, 37, 0.25, 1, 1, 0.75, VRT)
                END IF
              END IF
            END IF
          END IF
          NADR = NADR + NREC
        END DO
      END IF
      IF (NRPLOT == 6) THEN
        SCALHOR = (HORSO - 0.5) / SQRT (FOKM)
      ELSE
        SCALHOR = HORSO / (FLOAT (INT (LOG10 (FOKM) + 1)))
      END IF
      IF (NRPLOT == 2 .OR. NRPLOT == 3) THEN
        SCALVER = (VERT - YORG - 1.0) /
     1    MIN ((INT (XIOSM / 10.0) + 1) * 10.0, PAR(485))
      ELSE IF (NRPLOT == 4) THEN
        SCALVER = 1.25 * (VERT - YORG - 1.0) / SIGMX
      ELSE IF (NRPLOT == 5) THEN
        SCALVER = (VERT - YORG - 1.0) / (LOG10 (SIGMX) + 1.0)
      ELSE IF (NRPLOT == 6) THEN
        SCALVER = (VERT - YORG - 1.0) / SIGMX
      END IF
      TICK = 0.0
      IF (NRPLOT == 7) THEN
      ELSE IF (NRPLOT == 6) THEN
        CALL GGIP (0.0, 0.0, 0.0, 3)
        X = SQRT (FOKM)
C * USE FVAR VALUE TO SCALE TO ACTUAL SIG(I) OF EMBEDDED HKL
        IF (PAR(74) /= 0.0) THEN
          Y = X * SCALVER / PAR(74)
        ELSE
          Y = X * SCALVER
        END IF
        X = X * SCALHOR
        IF (Y > 23.0) THEN
          YUNK = X / Y
          Y = 23.0
          X = Y * YUNK
        END IF
        CALL GGIP (X, Y, 0.0, 2)
        CALL GGIP (0.0, 0.0, 0.0, 3)
      ELSE
        IF (SCALHOR < 0.0) THEN
          CALL GGIP (0.0, 0.0, 0.0, -1)
          RETURN
        END IF
        DO WHILE (TICK * SCALHOR < HORSO + 0.001)
          N    = 10 ** (NINT (TICK))
          X    = TICK * SCALHOR
          TICK = TICK + 1.0
          CALL GGIP (X,  0.0, 0.0, 3)
          CALL GGIP (X, -0.3, 0.0, 2)
          WRITE (LINE(1:8), 99999, IOSTAT = IOST) N
          CALL PLA439 (0.0,  LINE, 8, 0.25, 1, 1, X - 1.8, -0.3)
        END DO
      END IF
      IF (NRPLOT /= 4 .AND. NRPLOT /= 6 .AND. NRPLOT .NE. 7) THEN
        TICKM = (VERT - YORG) / SCALVER
        IF (TICKM < 16) THEN
          TICKS = 1.0
        ELSE IF (TICKM < 160.0) THEN
          TICKS = 10.0
        ELSE
          TICKS = 50.0
        END IF
        TICK = 0.0
        DO WHILE ((TICK + TICKS) * SCALVER < VERT - YORG)
          TICK = TICK + TICKS
          N    = NINT (TICK)
          X    = TICK * SCALVER
          WRITE (LINE(1:8), 99999, IOSTAT = IOST) N
          CALL GGIP (0.0, X, 0.0, 3)
          CALL GGIP (0.3, X, 0.0, 2)
          CALL PLA439 (90.0,  LINE, 8, 0.25, 1, 1, 0.4, X - 1.8)
        END DO
      END IF
      IF (NRPLOT == 6) THEN
        CALL PLA439 (90.0, 'Sig', 3, 0.35, 1, 1, -0.2 , VERTO - 2.0)
        CALL PLA439 (0.0,  'sqrt(I)', 7, 0.35, 1, 1, HORSO - 2.2, -0.55)
      END IF
      PEN = FLOAT (IYELLOW)
      NADR = 0
      DO I = 1, NREF
        FOK  = VOID(NADR + 4)
        SIGA = VOID(NADR + 6)
        SIGB = VOID(NADR + 12)
        IF (NRPLOT == 2) THEN
          SIG = SIGA
        ELSE IF (NRPLOT == 3) THEN
          SIG = SIGB
        ELSE IF (NRPLOT == 4) THEN
          SIG = SIGA
        ELSE IF (NRPLOT == 5) THEN
        ELSE IF (NRPLOT == 6) THEN
          SIG = SIGA
        END IF
        IF (FOK >= 1.0 .AND. SIG > 0.0) THEN
          IF (NRPLOT == 2 .OR. NRPLOT == 3) THEN
            X = LOG10 (FOK) * SCALHOR
            IF (X >= 0.0) THEN
              Y = FOK / SIG
              IF (Y < PAR(485)) THEN
                Y = Y * SCALVER
C * PLOT MARKER
                CALL PLA406 (X, Y, DSH, PEN)
              END IF
            END IF
C * SIGMA & SIGMAW VERSUS LOG10(I)
C * LOG10(SIGMA) & LOG10(SIGMAW) VERSUS LOG10(I)
          ELSE IF (NRPLOT == 4 .OR. NRPLOT == 5) THEN
            X = LOG10 (FOK) * SCALHOR
            IF (X >= 0.0) THEN
              IF (NRPLOT == 4) THEN
                YA = SIGA * SCALVER
                YB = SIGB * SCALVER
              ELSE
                YA = (LOG10 (SIGA) + 1.0) * SCALVER
                YB = (LOG10 (SIGB) + 1.0) * SCALVER
              ENDIF
C * PLOT MARKER
              CALL PLA406 (X, YA, DSH, PEN)
C * PLOT MARKER
              CALL PLA406 (X, YB, DSH, 1.0)
            END IF
C * SIGMA(I) VERSUS SQRT(I)
          ELSE IF (NRPLOT == 6) THEN
            IF (FOK > 0.0) THEN
              X  = SQRT (FOK) * SCALHOR
              YA = SIGA * SCALVER
              YB = SIGB * SCALVER
C * PLOT MARKER
              CALL PLA406 (X, YA, DSH, PEN)
C * PLOT MARKER
            END IF
          END IF
        END IF
        NADR = NADR + NREC
      END DO
      CALL GGIP (0.0, 0.0, 0.0, -1)
      RETURN
99999 FORMAT (I8)
99998 FORMAT (3I4, F9.1, 2F8.1)
99997 FORMAT (5X, '... etc ...')
99996 FORMAT ('SHELXL-weight-', A, F10.3)
99994 FORMAT ('   H   K   L     Iobs SigIobs  I/SigI',
     1  2X, '[I/SigI > ', F6.1, ']')
99993 FORMAT ('TITL', 13X, A)
99992 FORMAT ('FVAR', 11X,  F10.4)
99991 FORMAT ('EXTI', 11X,  F10.5)
99990 FORMAT (I3, 10X, F10.3)
      END SUBROUTINE PLA408
 
      SUBROUTINE PLA409 (NOPT)
      USE files
      USE parameters
      USE cggt
 
      IMPLICIT NONE
 
      INTEGER :: NOPT
      INTEGER :: NPLT
 
      REAL :: SCHAAL
      NPLT = 0
C * Normal Probability Plot
      DO
        IF (NOPT == 0) THEN
          CALL PLA204
C * I(obs) - I(calc) scatter plot
        ELSE IF (NOPT == 1) THEN
          SCHAAL = 1.0
          CALL PLA407 (0, SCHAAL, IGBL(9), 0, LU6)
C * I/SIG VERSUS LOG(I) PLOT
        ELSE IF (NOPT == 2) THEN
          CALL PLA408 (NOPT)
C * I/SIGW VERSUS LOG(I) PLOT
        ELSE IF (NOPT == 3) THEN
          CALL PLA408 (NOPT)
C * SIG & SIGW VERSUS LOG(I) PLOT
        ELSE IF (NOPT == 4) THEN
          CALL PLA408 (NOPT)
C * LOG(SIG) & LOG(SIGW) VERSUS LOG(I) PLOT
        ELSE IF (NOPT == 5) THEN
          CALL PLA408 (NOPT)
C * SIGMA(I)  VERSUS SQRT(I) PLOT
        ELSE IF (NOPT == 6) THEN
          CALL PLA408 (NOPT)
C * AV(I/SIG) VERSUS THETA
        ELSE IF (NOPT == 7) THEN
          CALL PLA408 (NOPT)
C * VARIANCE ANALYSIS RESULTS
        ELSE IF (NOPT == -1) THEN
          CALL PLA413 (0)
        END IF
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        CALL GEN020 (1, IGGT, 1, 10)
        IF (LRET == 2) THEN
          IF (NPLT == 1) THEN
            IGGT(1:4) = 'NPP '
          ELSE IF (NPLT == 2) THEN
            IGGT(1:4) = 'LINE'
          ELSE IF (NPLT == 3) THEN
            IGGT(1:4) = 'LOGL'
          END IF
          LRET = 0
        END IF
        CALL GEN072 (IGGT, IFL, FN, IPR(220), IPR(221), 0, LU6,
     1    1, 1, 80, 7, NP17)
        SELECT CASE (IFL(1)(1:4))
C * END PLOT
          CASE ('END ')
            RETURN
C * EXIT
          CASE ('EXIT')
            RETURN
C * PLOT
          CASE ('PLOT')
C * PLOT
          CASE ('!   ')
C * NORMAL PROBABILITY PLOT
          CASE ('NPP ')
            NPLT = 1
            NOPT = 0
C * SCATTER-PLOT
          CASE ('SCAT')
            IPR(633) = 0
            NPLT = 2
            NOPT = 1
C * LOGLOG-SCATTER PLOT
          CASE ('LOGL')
            IPR(633) = 1
            NPLT     = 3
            NOPT     = 1
C * LINEAR-PLOT
          CASE ('LINE')
            IPR(633) = 0
            NPLT     = 2
            NOPT     = 1
C * I/SIGMA VERSUS LOG(I) PLOT DI
          CASE ('IOSL')
            NOPT = 2
C * I/SIGMAW VERSUS LOG(I) PLOT
          CASE ('IOSW')
            NOPT = 3
C * SIG(I) VERSUS LOG(I)
          CASE ('SIGL')
            NOPT = 4
C * LOG(SIG(I)) VERSUS LOG(I)
          CASE ('LSLI')
            NOPT = 5
C * SIGMA(I) VERSUS SQRT(I)
          CASE ('SIRI')
            NOPT = 6
C * AV(I/SIG) VERSUS THETA
          CASE ('ISST')
            NOPT = 7
          CASE ('STAN')
C * SET MAXIMUM VERTICAL I/SIGMA Y-COORDINATE
          CASE ('SET')
            IF (IFL(2)(1:3) == 'PAR') THEN
              IF (IPR(221) > 0) PAR(485) = FN(1)
            END IF
C * VARIANCE ANALYSIS RESULTS
          CASE ('VARI')
            NOPT = -1
C * LIST CONTENT FIRST Fc/Fmax BIN
            IF (IPR(778) > 0) THEN
              REWIND (LU60)
              DO
                READ (LU60, 99999, IOSTAT = IOST) ICL
                IF (IOST /= 0) EXIT
                WRITE (LU6, 99999) ICL(1:80)
              END DO
            END IF
        END SELECT
      END DO
      RETURN
99999 FORMAT (A)
      END SUBROUTINE PLA409
 
      SUBROUTINE PLA412 (MODE, NOPT)
C * ANALYSIS OF VARIANCE
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE analysis
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: JB
      INTEGER :: JE
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: LUX
      INTEGER :: MODE
      INTEGER :: NOBS
      INTEGER :: NOPT
      INTEGER :: NTOT
      INTEGER :: IHEAD
      INTEGER :: NADRM
      INTEGER :: NFCAL
      INTEGER :: NOBSFRAC
      REAL :: S
      REAL :: R1
      REAL :: R2
      REAL :: FCK
      REAL :: FOK
      REAL :: SIG
      REAL :: STL
      REAL :: R2XX
      REAL :: YUNK
      REAL :: STON
      REAL :: STOT
      REAL :: SIGK
      REAL :: SIGNX
      REAL :: RESOL
      REAL :: FCMAX
      REAL :: SCHAAL
      REAL :: SINTHL
      REAL :: FCOFCM
      REAL :: FACTOR
      REAL :: R1TELL
      REAL :: R2TELL
      REAL :: R2TELN
      REAL :: R2NOEM
      REAL :: R2NOEN
      REAL :: R1NOEM
      REAL :: GEN095
      NFCAL  = 11
      IHEAD  = 0
      NOBS   = 0
      NTOT   = 0
      STOT   = 0.0
      STON   = 0.0
      R1TELL = 0.0
      R1NOEM = 0.0
      R2TELL = 0.0
      R2NOEM = 0.0
      R2TELN = 0.0
      R2NOEN = 0.0
      NADRM  = NREF * NREC
      IF (IGBL(22) < 0) THEN
        JB = 3
        JE = 3
      ELSE
        JB = 1
        JE = 2
      END IF
      FACTOR = 10.0 / (0.65**3 + 0.0001)
      DO I = 1, 20
        DO J = 1, 12
          STAT(I, J) = 0.0
        END DO
      END DO
      DO I = 1, 11
        DO J = 1, 5
          VSTATA (I, J) = 0.0
          VSTATB (I, J) = 0.0
          VSTATC (I, J) = 0.0
        END DO
      END DO
      DO I = 1, 14
        DO J = 1, 3
          NSTATH(I, J) = 0
          NSTATK(I, J) = 0
          NSTATL(I, J) = 0
        END DO
      END DO
C * GET 10 EQUALLY POPULATED BOXES AS A FUNCTION OF F/FMAX
      NADR = 0
      DO I = 1, NREF
        VOID(NADRM + I) = SQRT (VOID(NADR + NFCAL))
        NADR            = NADR + NREC
      END DO
C * SORT ON F(CALC)
      CALL GEN034 (VOID, NADRM + 1, NADRM + NREF)
      FCMAX = VOID(NADRM + 1)
      IF (FCMAX == 0.0) THEN
C * REPORT PROBLEM IN PLA412
        WRITE (LU6, 99986)
        RETURN
      END IF
      VSTATA(1,  1) = 0.0
      VSTATA(11, 1) = 1.0
      DO I = 1, 9
        N = NINT (FLOAT (I * NREF) / 10.0) + NADRM
        VSTATA(11 - I, 1) = VOID(N) / FCMAX
      END DO
C * GET 10 EQUALLY POPULATED BOXES ORDERED ON RESOLUTION
      NADR = 0
      DO I = 1, NREF
        IH  = NINT (VOID(NADR + 1))
        IK  = NINT (VOID(NADR + 2))
        IL  = NINT (VOID(NADR + 3))
        STL = SQRT (GEN095 (PAR(191), IH, IK, IL))
        VOID(NADRM + I) = 0.5 / STL
        NADR = NADR + NREC
      END DO
C * SORT ON RESOLUTION
      CALL GEN034 (VOID, NADRM + 1, NADRM + NREF)
      VSTATB(1,  1) = VOID(NADRM + NREF)
      VSTATB(11, 1) = VOID(NADRM + 1)
      VSTATC(1,  1) = VOID(NADRM + NREF)
      VSTATC(11, 1) = VOID(NADRM + 1)
      DO I = 1, 9
        N = NINT (FLOAT (I * NREF) / 10.0) + NADRM
        VSTATB(11 - I, 1) = VOID(N)
        VSTATC(11 - I, 1) = VOID(N)
      END DO
C * COLLECT STATISTICS
      OPEN (UNIT = LU60, FILE = 'scratch', STATUS = 'UNKNOWN')
      NADR = 0
      DO I = 1, NREF
        JH  = ABS (NINT (VOID(NADR + 1)))
        JK  = ABS (NINT (VOID(NADR + 2)))
        JL  = ABS (NINT (VOID(NADR + 3)))
        FOK = VOID(NADR + 4)
        FCK = VOID(NADR + NFCAL)
        SIG = VOID(NADR + 6)
C * COLLECT STATISTICS FOR ABS(H), ABS(K) & ABS(L)
        IF (JH < 14) THEN
          NSTATH(JH + 1, 1) = NSTATH(JH + 1, 1) + 1
          IF (FOK > 3.0 * SIG) THEN
            NSTATH(JH + 1, 2) = NSTATH(JH + 1, 2) + 1
          END IF
          IF (FCK > 3.0 * SIG) THEN
            NSTATH(JH + 1, 3) = NSTATH(JH + 1, 3) + 1
          END IF
        END IF
        IF (JK < 14) THEN
          NSTATK(JK + 1, 1) = NSTATK(JK + 1, 1) + 1
          IF (FOK > 3.0 * SIG) THEN
            NSTATK(JK + 1, 2) = NSTATK(JK + 1, 2) + 1
          END IF
          IF (FCK > 3.0 * SIG) THEN
            NSTATK(JK + 1, 3) = NSTATK(JK + 1, 3) + 1
          END IF
        END IF
        IF (JL < 14) THEN
          NSTATL(JL + 1, 1) = NSTATL(JL + 1, 1) + 1
          IF (FOK > 3.0 * SIG) THEN
            NSTATL(JL + 1, 2) = NSTATL(JL + 1, 2) + 1
          END IF
          IF (FCK > 3.0 * SIG) THEN
            NSTATL(JL + 1, 3) = NSTATL(JL + 1, 3) + 1
          END IF
        END IF
        SIGNX  = SIG**2
C * INCLUDE L.S. WEIGHT PARAMETERS IN SIGMAI
        SIGK       = VOID(NADR + 12)**2
        STL        = SIN ((VOID(NADR + 7) / RGBL(6))) / PAR(17)
        N          = MIN (20,  1 + INT (STL**3 * FACTOR))
        STAT(N, 1) = STAT(N, 1) + ABS (FOK)
        STAT(N, 2) = STAT(N, 2) + ABS (FCK)
        STAT(N, 3) = STAT(N, 3) + 1.0
        IF (FOK > 2 * SIG) THEN
          STAT(N, 10) = STAT(N, 10) + 1.0
          STAT(N, 4)  = STAT(N, 4) + SQRT (ABS (FOK))
          STAT(N, 5)  = STAT(N, 5)
     1                + ABS (SQRT (ABS (FOK)) - SQRT (ABS (FCK)))
        END IF
        IF (SIGK /= 0.0) THEN
          STAT(N,  6) = STAT(N,  6) + (FOK - FCK) ** 2 / SIGK
          STAT(N,  7) = STAT(N,  7) + FOK ** 2 / SIGK
        END IF
        IF (SIGNX /= 0.0) THEN
          STAT(N, 11) = STAT(N, 11) + (FOK - FCK) ** 2 / SIGNX
          STAT(N, 12) = STAT(N, 12) + FOK ** 2 / SIGNX
        END IF
        NADR   = NADR + NREC
        FCOFCM = SQRT (FCK) / FCMAX
        DO J = 2, 11
          IF (FCOFCM <= VSTATA(J, 1)) THEN
            VSTATA(J, 2) = VSTATA(J, 2) + 1.0
            IF (SIGK /= 0.0) THEN
              VSTATA(J, 3) = VSTATA(J, 3) + (FOK - FCK)**2 / SIGK
            END IF
            VSTATA(J, 4) = VSTATA(J, 4) + FOK
            VSTATA(J, 5) = VSTATA(J, 5) + FCK
C * LIST CONTRIBUTIONS TO FIRST BIN
            IF (I == 1) WRITE (LU60, 99987)
            IF (J == 2) WRITE (LU60, 99988) JH, JK, JL,
     1        FOK, FCK, SIG, VSTATA(2,4), VSTATA(2,5), STL
            IF (J <= 3) THEN
              RESOL = 0.5 / STL
              DO K = 2, 11
                IF (RESOL <= VSTATC(K, 1)) THEN
                  VSTATC(K, 2) = VSTATC(K, 2) + 1.0
                  IF (SIGK /= 0.0) THEN
                    VSTATC(K, 3) = VSTATC(K, 3) + (FOK - FCK)**2 / SIGK
                  END IF
                  VSTATC(K, 4) = VSTATC(K, 4) + FOK
                  VSTATC(K, 5) = VSTATC(K, 5) + FCK
                  EXIT
                END IF
              END DO
            END IF
            EXIT
          END IF
        END DO
        RESOL = 0.5 / STL
        DO J = 2, 11
          IF (RESOL <= VSTATB(J, 1)) THEN
            VSTATB(J, 2) = VSTATB(J, 2) + 1.0
            IF (SIGK /= 0.0) THEN
              VSTATB(J, 3) = VSTATB(J, 3) + (FOK - FCK)**2 / SIGK
            END IF
            VSTATB(J, 4) = VSTATB(J, 4) + FOK
            VSTATB(J, 5) = VSTATB(J, 5) + FCK
            EXIT
          END IF
        END DO
      END DO
      DO I = 2, 11
        YUNK = VSTATA(I, 2) - IPR(266) / 10.0
        IF (YUNK > 0.0) THEN
          VSTATA(I, 3) = SQRT (VSTATA(I, 3) / YUNK)
        ELSE
          VSTATA(I, 3) = 0.0
        END IF
        IF (VSTATA(I, 2) > 0.0 .AND. VSTATA(I, 5) /= 0.0) THEN
          VSTATA(I, 4) = VSTATA(I, 4) / VSTATA(I, 5)
        ELSE
          VSTATA(I, 4) = 0.0
        END IF
        IF (VSTATA(I, 4) > 2.0) THEN
          CALL PLA236 (906, 3, 0.5, VSTATA(I, 4), ' ', ' ')
        ELSE IF (VSTATA(I, 4) < 0.0) THEN
          CALL PLA236 (905, 3, 0.5, VSTATA(I, 4), ' ', ' ')
        END IF
        YUNK = VSTATB(I, 2) - IPR(266) / 10.0
        IF (YUNK > 0.0) THEN
          VSTATB(I, 3) = SQRT (VSTATB(I, 3) / YUNK)
        ELSE
          VSTATB(I, 3) = 0.0
        END IF
        IF (VSTATB(I, 2) > 0.0 .AND. VSTATB(I, 5) /= 0.0) THEN
          VSTATB(I, 4) = VSTATB(I, 4) / VSTATB(I, 5)
        ELSE
          VSTATB(I, 4) = 0.0
        END IF
        IF (VSTATB(I, 4) > 2.0) THEN
          CALL PLA236 (906, 3, 0.5, VSTATB(I, 4), ' ', ' ')
        ELSE IF (VSTATB(I, 4) < 0.0) THEN
          CALL PLA236 (905, 3, 0.5, VSTATB(I, 4), ' ', ' ')
        END IF
        YUNK = VSTATC(I, 2) - IPR(266) / 100.0
        IF (YUNK > 0.0) THEN
          VSTATC(I, 3) = SQRT (VSTATC(I, 3) / YUNK)
        ELSE
          VSTATC(I, 3) = 0.0
        END IF
        IF (VSTATC(I, 2) > 0.0 .AND. VSTATC(I, 5) /= 0.0) THEN
          VSTATC(I, 4) = VSTATC(I, 4) / VSTATC(I, 5)
        ELSE
          VSTATC(I, 4) = 0.0
        END IF
      END DO
      DO I = 1, 14
        IF (NSTATH(I, 1) /= 0) THEN
          NSTATH(I, 2) = NINT (100.0 * NSTATH(I, 2) / NSTATH(I, 1))
          NSTATH(I, 3) = NINT (100.0 * NSTATH(I, 3) / NSTATH(I, 1))
        END IF
        IF (NSTATK(I, 1) > 0) THEN
          NSTATK(I, 2) = NINT (100.0 * NSTATK(I, 2) / NSTATK(I, 1))
          NSTATK(I, 3) = NINT (100.0 * NSTATK(I, 3) / NSTATK(I, 1))
        END IF
        IF (NSTATL(I, 1) > 0) THEN
          NSTATL(I, 2) = NINT (100.0 * NSTATL(I, 2) / NSTATL(I, 1))
          NSTATL(I, 3) = NINT (100.0 * NSTATL(I, 3) / NSTATL(I, 1))
        END IF
      END DO
      DO J = JB, JE
C * TERMINAL WINDOW LISTING
        IF (J == 1) THEN
          LU = LU6
C * LIS LISTING FILE
        ELSE IF (J == 2) THEN
          LU = LU7
C * CKF LISTING FILE
        ELSE
          LU = LU13
        END IF
        WRITE (LU, 99993, IOSTAT = IOST) HMAX, KMAX, LMAX
        IF (J == 2) CALL PLA262 (2)
        CALL PLA413 (LU)
      END DO
      IF (IGBL(22) >= 0 .OR. IABS (IGBL(36)) == 1) THEN
        DO I = 1, 20
          IF (STAT(I, 3) /= 0.0 .AND. STAT(I, 7) /= 0.0 .AND.
     1        STAT(I, 4) /= 0.0) THEN
            R1TELL = R1TELL + STAT(I,  5)
            R1NOEM = R1NOEM + STAT(I,  4)
            R2TELL = R2TELL + STAT(I,  6)
            R2NOEM = R2NOEM + STAT(I,  7)
            R2TELN = R2TELN + STAT(I, 11)
            R2NOEN = R2NOEN + STAT(I, 12)
            R1   = STAT(I, 5) / STAT(I, 4)
            R2   = SQRT (STAT(I, 6) / STAT(I, 7))
            S    = SQRT (STAT(I, 6) /
     1             (STAT(I, 3) - IPR(266) * STAT(I, 3) / NREF))
            STOT = STOT + STAT(I, 6)
            STON = STON + STAT(I, 11)
            NTOT = NTOT + NINT (STAT(I, 3))
            NOBS = NOBS + NINT (STAT(I, 10))
            IF (IHEAD == 0) THEN
              WRITE (LU6, 99998, IOSTAT = IOST)
              WRITE (LU7, 99998, IOSTAT = IOST)
              IHEAD = 1
            END IF
            SINTHL   = (I / FACTOR) ** 0.333333
            NOBSFRAC = INT (STAT(I, 10) * 39.0 / STAT(I, 3)) + 1
            DO J = 1, 40
              IF (J > NOBSFRAC) THEN
                IDM(40 + J: 40 + J) = '.'
              ELSE
                IDM(40 + J: 40 + J) = '*'
              END IF
            END DO
            WRITE (IDM(1:40), 99994, IOSTAT = IOST) SINTHL,
     1        0.5 / SINTHL,
     2        NINT (STAT(I, 3)), NINT (STAT(I, 10)), R1, R2, S
            WRITE (LU6, 99999, IOSTAT = IOST) IDM
            WRITE (LU7, 99999, IOSTAT = IOST) IDM
          END IF
        END DO
        WRITE (LU6, 99992, IOSTAT = IOST)
        WRITE (LU7, 99992, IOSTAT = IOST)
        STOT = SQRT (STOT / (NTOT - MAX (0, IPR(266))))
        STON = SQRT (STON / (NTOT - MAX (0, IPR(266))))
        IF (R1NOEM /= 0.0) R1   = R1TELL / R1NOEM
        IF (R2NOEM /= 0.0) R2   = SQRT (R2TELL / R2NOEM)
        IF (R2NOEN /= 0.0) R2XX = SQRT (R2TELN / R2NOEN)
        IF (STOT < 99.999) THEN
          WRITE (LU6, 99997, IOSTAT = IOST)
     1      R1, R2, STOT, NTOT, NOBS, MAX (0, IPR(266))
          WRITE (LU7, 99997, IOSTAT = IOST)
     1      R1, R2, STOT, NTOT, NOBS, MAX (0, IPR(266))
        ELSE
          WRITE (LU6, 99990, IOSTAT = IOST)
     1      R1, R2, MIN (999.99, STOT), NTOT, NOBS, MAX (0, IPR(266))
          WRITE (LU7, 99990, IOSTAT = IOST)
     1      R1, R2, MIN (999.99, STOT), NTOT, NOBS, MAX (0, IPR(266))
        END IF
        IF (STON < 99.999) THEN
          WRITE (LU6, 99991, IOSTAT = IOST) R2XX, STON
        ELSE
          WRITE (LU6, 99989, IOSTAT = IOST) R2XX, MIN (999.99, STON)
        ENDIF
C * NORMAL PROBABILITY PLOT
C * CHECK FOR VALIDATION MODE
        IF (IABS(IGBL(36)) == 1) THEN
          LUX = LU
          WRITE (LU, 99995)
        ELSE
          LUX = LU7
          CALL PLA262 (0)
        END IF
C * COPY (Fo-Fc)/SigW TO SEPARATE SECTION IN VOID
        DO I = 1, NREF
          VOID(NADR + I) = VOID((I - 1) * NREC + 9)
        END DO
        CALL GEN116 (2, VOID(NADR + 1), VOID(NADR + NREF + 1), NREF,
     1     GRAPH, 0)
        GRAPH(5)(52:95) =
     1    'NPP for (Fobs**2 - Fcalc**2) / SigW(Fobs**2)'
        IF (PAR(493) >= 0.0)
     1    WRITE (GRAPH(7)(52:103), 99996, IOSTAT = IOST)
     2    PAR(493), PAR(494)
        WRITE (GRAPH(9)(52: 57 + KNM16), 99999)
     1    'Data: '//FNLU16(1:KNM16)
        WRITE (LUX, 99999) (GRAPH(I), I = 1, 44)
C * DISPLAY=OFF/META=ON MODE ONLY
        IF (IGBL(149) == 1 .AND. IGBL(3) == 1) THEN
          IGGT(2:80) = NAMEFIL(1:79)
C * GENERAL GRAPHICS OPEN
          CALL GGIP (-999.0, FLOAT(-KNMFIL), 0.0, 5)
C * SET FOR DISPLAY = OFF/META = ON
          CALL GGIP (-999.0, 0.0, 0.0, -2)
C * Normal Probability Plot
          CALL PLA204
C * I(obs) - I(calc) scatter plot
          IPR(633) = 0
          SCHAAL   = 1.0
          CALL PLA407 (0, SCHAAL, IGBL(9), 0, LU6)
C * Log(I(obs)) versus Log(I)calc)) scatter plot
          IPR(633) = 1
          SCHAAL   = 1.0
          CALL PLA407 (0, SCHAAL, IGBL(9), 0, LU6)
C * VARIANCE ANALYSIS RESULTS
          CALL PLA413 (0)
C * I/SIG VERSUS LOG(I) PLOT (Diederichs)
          CALL PLA408 (2)
C * I/SIGW VERSUS LOG(I) PLOT (Diederichs)
          CALL PLA408 (3)
C * AV(I/SIG) VERSUS THETA
          CALL PLA408 (7)
        ELSE
          IF (MODE == 0) CALL PLA409 (NOPT)
        END IF
      END IF
      CLOSE (LU60, STATUS = 'DELETE', IOSTAT = IOST)
      RETURN
99999 FORMAT (A)
99998 FORMAT (/, 'ST/L    d     #  Nobs    R1   wR2     S',
     1        ' 0  Percent Distr. for I .gt. 2*s(I)  100', /, 80('='))
99997 FORMAT (/, ':: R1 =', F6.3, ', wR2 =', F6.3, ', S =', F6.3,
     1        ', Nref =', I7, ', Nobs =', I7, ', Npar =', I5)
99996 FORMAT ('SigW Includes the SHELXL WGHT Par.', 2F9.4)
99995 FORMAT (//)
99994 FORMAT (F4.2, F5.2, 2I6, 3F6.3, 1X, A)
99993 FORMAT (/, ':: Hmax =', I5, ', Kmax =', I5, ', Lmax =', I5)
99992 FORMAT (39X, 'I', 19X, 'I', 19X, 'I', /,
     1        19X, 'Percent Observed:   0',18X, '50', 17X, '100')
99991 FORMAT ('::',13X, 'wR2 =', F6.3, ', S =', F6.3,
     1        ' (Non Optimized Weights)')
99990 FORMAT (/, ':: R1 =', F6.3, ', wR2 =', F6.3, ', S =', F6.2,
     1        ', Nref =', I7, ', Nobs =', I7, ', Npar =', I5)
99989 FORMAT ('::',13X, 'wR2 =', F6.3, ', S =', F6.2,
     1        ' (Non Optimized Weights)')
99988 FORMAT (3I4, 6F10.2)
99987 FORMAT (/, '   H   K   L    I(obs)    I(calc)    Sig(I)',
     1           '    SumObs   SumCalc   SinTh/L')
99986 FORMAT (':: Problem in PLA412, SKIP', /)
      END SUBROUTINE PLA412
 
      SUBROUTINE PLA413 (LU)
C * ANALYSIS OF VARIANCE LISTINGS
      USE files
      USE parameters
      USE cggt
      USE analysis
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: LU
      INTEGER :: HM
      INTEGER :: KM
      INTEGER :: LM
      INTEGER :: IYELLOW
      CHARACTER(len=80) :: LINE
C * HANDLE POOR VISIBILITY OF YELLOW ON WHITE BACKGROUND
      IF (IGBL(68) == 1 .OR. IGBL(149) == 0) THEN
        IYELLOW = 6
      ELSE
        IYELLOW = 5
      END IF
      IF (LU == 0) THEN
        CALL GGIP (HORS, VERT, 0.0, 1)
        LINE =
     1    'Analysis of Variance for data: '//FNLU16(1:KNM16)
        CALL PLA439 (0.0, LINE, 31 + KNM16, 0.45, IYELLOW,
     1    2, 2.5, VERT - 0.9)
        VRT = VERT - 1.0
      END IF
C * TEST FOR AND LIST SHELXL WEIGHT PARAMETERS
      IF (PAR(493) >= 0.0) THEN
        WRITE (LINE, 99999, IOSTAT = IOST)
C * DUMMY
        IF (IOST == -999) RETURN
        CALL PLA296 (LU, LINE)
        WRITE (LINE, 99998, IOSTAT = IOST) PAR(493), PAR(494)
        CALL PLA296 (LU, LINE)
      END IF
C * Goof & K as function of Fc/Fc(max)
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99991, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99997, IOSTAT = IOST) (VSTATA(I, 1), I = 1, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99996, IOSTAT = IOST)
     1  (NINT (VSTATA(I, 2)), I = 2, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99995, IOSTAT = IOST) (VSTATA(I, 3), I = 2, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99994, IOSTAT = IOST)
     1  MAX (-99.999, MIN (VSTATA(2, 4), 99.999)),
     2  (MAX (-9.999, MIN (9.999, VSTATA(I, 4))), I = 3, 11)
C * Goof & K as function of the resolution
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99993, IOSTAT = IOST) (VSTATB(I, 1), I = 1, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99996, IOSTAT = IOST)
     1  (NINT (VSTATB(I, 2)), I = 2, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99995, IOSTAT = IOST) (VSTATB(I, 3), I = 2, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99994, IOSTAT = IOST)
     1  MAX (-99.999, MIN (VSTATB(2, 4), 99.999)),
     2  (MAX (-9.999, MIN (9.999, VSTATB(I, 4))), I = 3, 11)
      CALL PLA296 (LU, LINE)
C * Goof & K as function of the resolution for FC/Fc(max) < 0.016
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99992, IOSTAT = IOST) VSTATA(3, 1)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99993, IOSTAT = IOST) (VSTATC(I, 1), I = 1, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99996, IOSTAT = IOST)
     1  (NINT (VSTATC(I, 2)), I = 2, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99995, IOSTAT = IOST) (VSTATC(I, 3), I = 2, 11)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99994, IOSTAT = IOST)
     1  MAX (-99.999, MIN (VSTATC(2, 4), 99.999)),
     2  (MAX (-9.999, MIN (9.999, VSTATC(I, 4))), I = 3, 11)
      CALL PLA296 (LU, LINE)
C * PerObs Fo2 & PerObs Fc2 as a function of H
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      HM = MIN (HMAX + 1, 14)
      WRITE (LINE, 99990, IOSTAT = IOST) 'H',   (I - 1, I = 1, HM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99989, IOSTAT = IOST) (NSTATH(I, 1), I = 1, HM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99988, IOSTAT = IOST) (NSTATH(I, 2), I = 1, HM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99987, IOSTAT = IOST) (NSTATH(I, 3), I = 1, HM)
      CALL PLA296 (LU, LINE)
C * PerObs Fo2 & PerObs Fc2 as a function of K
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      KM = MIN(KMAX + 1, 14)
      WRITE (LINE, 99990, IOSTAT = IOST) 'K',   (I - 1, I = 1, KM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99989, IOSTAT = IOST) (NSTATK(I, 1), I = 1, KM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99988, IOSTAT = IOST) (NSTATK(I, 2), I = 1, KM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99987, IOSTAT = IOST) (NSTATK(I, 3), I = 1, KM)
      CALL PLA296 (LU, LINE)
C * PerObs Fo2 & PerObs Fc2 as a function of L
      WRITE (LINE, 99999, IOSTAT = IOST)
      CALL PLA296 (LU, LINE)
      LM = MIN (LMAX + 1, 14)
      WRITE (LINE, 99990, IOSTAT = IOST) 'L',   (I - 1, I = 1, LM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99989, IOSTAT = IOST) (NSTATL(I, 1), I = 1, LM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99988, IOSTAT = IOST) (NSTATL(I, 2), I = 1, LM)
      CALL PLA296 (LU, LINE)
      WRITE (LINE, 99987, IOSTAT = IOST) (NSTATL(I, 3), I = 1, LM)
      CALL PLA296 (LU, LINE)
      IF (LU == 0) THEN
        CALL GGIP (0.0, 0.0, 0.0, -1)
      END IF
      RETURN
99999 FORMAT (1X)
99998 FORMAT (':: SigW(I) Includes the SHELXL WGHT a & b Parameter',
     1        ' Values', 2F9.4)
99997 FORMAT ('Fc/Fc(max)', 4X, 11F6.3)
99996 FORMAT ('Number in Group ', 10I6)
99995 FORMAT ('           GooF ', 10F6.3)
99994 FORMAT ('              K', F7.3, 9F6.3)
99993 FORMAT ('Resolution(A)', 1X, 11F6.2)
99992 FORMAT ('Resolution Dependence for Fc/Fc(max) .LT.', F7.3)
99991 FORMAT (':: K = Mean[Fo^2]/Mean[Fc^2] for Group - ',
     1        '(Fo^2, Fc^2 from FCF)')
99990 FORMAT ('Abs(', A, ')', 4X, 14I5)
99989 FORMAT ('Number    ', 14I5)
99988 FORMAT ('PerObs Fo2', 14I5)
99987 FORMAT ('PerObs Fc2', 14I5)
      END SUBROUTINE PLA413
 
      MODULE twin
      SAVE
      INTEGER :: HMAX0
      INTEGER :: KMAX0
      INTEGER :: LMAX0
      REAL    :: DELS
      END MODULE twin
 
 
      SUBROUTINE PLA414 (MODE)
C * TWINROTMAT - ANALYSE REFLECTION DATA FOR TWINNING BY REFLECTION OVERLAP
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE spgrdata
      USE reflex
      USE lepage
      USE analysis
      USE twin
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: II
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      INTEGER :: IS
      INTEGER :: LL
      INTEGER :: NS
      INTEGER :: NX
      INTEGER :: IHI
      INTEGER :: IHJ
      INTEGER :: IKI
      INTEGER :: IKJ
      INTEGER :: ILI
      INTEGER :: ILJ
      INTEGER :: ILP
      INTEGER :: ISN
      INTEGER :: LIV
      INTEGER :: NVC
      INTEGER :: MPK
      INTEGER :: MPL
      INTEGER :: NVCM
      INTEGER :: NMIN
      INTEGER :: NEQL
      INTEGER :: MHKL
      INTEGER :: LINV
      INTEGER :: MODE
      INTEGER :: IBLP
      INTEGER :: IBRV
      INTEGER :: MSEL
      INTEGER :: LOOP
      INTEGER :: NSYMR
      INTEGER :: IADR1
      INTEGER :: IHKLP
      INTEGER :: IIMAX
      INTEGER :: ISHOW
      INTEGER :: IYUNK
      INTEGER :: KSMAL
      INTEGER :: MHKLH
      INTEGER :: NEXIT
      INTEGER :: IHKLSUM
      INTEGER, DIMENSION(3)    :: IA
      INTEGER, DIMENSION(NP75) :: IB
      INTEGER, DIMENSION(NP75) :: IC
      INTEGER, DIMENSION(3)    :: IHKL
      REAL :: SCA
      REAL :: OME
      REAL :: PHI
      REAL :: DTH
      REAL :: CHI
      REAL :: DET
      REAL :: THI
      REAL :: THJ
      REAL :: SUMT
      REAL :: XHKL
      REAL :: XLNG
      REAL :: FCKI
      REAL :: FCKJ
      REAL :: FOKI
      REAL :: FOKJ
      REAL :: COSA
      REAL :: DELI
      REAL :: DELJ
      REAL :: ALFA
      REAL :: SIGI
      REAL :: SIGJ
      REAL :: SPRD
      REAL :: RDROP
      REAL :: RATIO
      REAL :: DELSJ
      REAL :: DELSIG
      REAL :: GEN009
      REAL, DIMENSION(3)    :: V
      REAL, DIMENSION(9)    :: TMT
      REAL, DIMENSION(3)    :: TAU
      REAL, DIMENSION(3, 3) :: ORT
      REAL, DIMENSION(3, 3) :: YUNK
      REAL, DIMENSION(3)    :: VTAU
      CHARACTER(len=3) :: FCFMODE
C * MODE = 1 - GRAPHICS MODE
C * MODE = 2 - NON-GRAPHICS MODE
C * IPR(608) = 0 - FCF FCALC DATA SOURCE
C * IPR(608) = 1 - CIF FCALC DATA SOURCE
C * REFLECTION DATA ARE STORED BOTTOM-UP IN SCRATCH ARRAY VOID WITH TOTAL SIZE:
      NADR  = NREF * NREC
C * POINTERS TO REFLECTION DATA ARE STORED TOP-DOWN IN ScRATCH ARRAY VOID
C * INDEX TO REFLECTION RECORD (SIZE NREC)
C * VOID(N +  1) = H
C * VOID(N +  2) = K
C * VOID(N +  3) = L
C * VOID(N +  4) = FOK
C * VOID(N +  5) = FCK (FROM CIF PARAMETERS)
C * VOID(N +  6) = SIG
C * VOID(N +  7) = THETA
C * VOID(N +  8) = (FOK - FCK) / SIG
C * VOID(N +  9) =
C * VOID(N + 10) = FCKT (OVERLAPPING INTENSITY)
C * VOID(N + 11) = FCK (FROM FCF DATA)
C * VOID(N + 12) = SIGIW
      NX    = NP23 / 2
      NEXIT = 0
C * ZERO SGX ARRAY
      CALL GEN074 (SGX, 1, 13, 0.0)
C * GET ORTHOGONALISATION MATRIX FROM INPUT-CELL (ORT)
      CALL GEN044 (PAR(101), OR, 1)
C * GET TRANSPOSE
      CALL GEN005 (OR, ORT)
C * GET DE-ORTHOGONALISATION MATRIX (ROTQ)
      CALL GEN003 (ORT, ROTQ, DET, 0)
C * CHECK FOR -T OPTION (RL-PLOT)
   10 IF (IGBL(3) == 30) IPR(608) = 0
C * TOGGLE FOr FC FROM FCF (= 0) OR CIF (=1)
      ICALT    = 11 - IPR(608) * 6
C * INIT NUMBER OF SELECTED TWIN REFLECTION PAIR CANDIDATES
      NSEL     = 0
C * INIT NUMBER / OF POTENTIAL TWINLAWS
      IPR(771) = 0
C * NUMBER OF NON-BRAVAIS SYMMETRY OPERATIONS
      NSYMR = NSYMH * ICNTR
C * NUMBER OF BRAVAIS SYMMETRY OPERATIONS
      IBRV  = IPR(241)
C * CHECK FOR R-LATTICE (OBVERSE/REVERSE)
      IF (IBRV == 7) THEN
        IBLP = 2
      ELSE
        IBLP = 1
      END IF
C * CHECK IPR(259) FOR MONOCLINIC CLASS OR OTHERWISE
      IF (IPR(259) == 2) THEN
C * SET B AXIS UNIQUE
        IPR(394) = 2
      ELSE
C * SET C-AXIS UNIQUE
        IPR(394) = 3
      END IF
C * (A)CENTRO LOOP MAX (1 OR 2 TIMES)
      LINV = 3 - ICNTR
      CALL GEN097 (IB, 1, NP75, 0)
      CALL GEN097 (IC, 1, NP75, 0)
      MSEL = 0
      JH   = 0
      JK   = 0
      JL   = 0
C * CREATE H,K,L to REFLECTION DATA POINTER ARRAY (TOP-DOWN)
C * DETERMINE PACKING CONSTANTS AND ADDRESSES OF REFLECTION DATA HKL
      HMAX0 = MAX (HMAX, IPR(561))
      KMAX0 = MAX (KMAX, IPR(562))
      LMAX0 = MAX (LMAX, IPR(563))
      MPH   = 2 * HMAX0 + 1
      MPK   = 2 * KMAX0 + 1
      MPL   = 2 * LMAX0 + 1
      MHK   = MPH * MPK
      MHKL  = MPL * MHK
      MHKLH = (MHKL - 1) / 2
C * CALCULATE ADDRESS OF 0,0,0 REFLECTION
      IADR  = NVDR - MHKLH
      IADR1 = NVDR - MHKL
C * CHECK FOR OVERFLOW VOID SCRATCH
      IF (IADR1 < NADR) THEN
        WRITE (6, 99989)
        RETURN
      END IF
C * SET DEFAULTS IN HKL-ADDRESS ARRAY
      DO I = 1, MHKL
        IH = I - 1
        IL = IH / MHK
        IH = IH - IL * MHK
        IL = IL - LMAX0
        IK = IH / MPH
        IH = IH - IK * MPH - HMAX0
        IK = IK - KMAX0
C * MARK BRAVAIS AND SPACE GROUP ABSENCES (-2 OR -1), ALL OTHERS AS (0)
        SGX(1)  = IH
        SGX(2)  = IK
        SGX(3)  = IL
        SGX(12) = 0.0
        CALL SGSM (27, LINE, SGX, 0, 0, IERR)
        VOID(IADR1 + I) = - SGX(12)
      END DO
C * LOAD POINTERS TO STORED REFLECTION DATA IN HKL-ADDRESS ARRAY
C * THE REFLECTION SET IS EXPANDED FOLLOWING THE SPACE GROUP SYMMETRY
C * FOR NON-CENTRO STRUCTURES, MISSING SITES IN THE EWALD SPHERE ARE
C * FILLED UP IN A SECOND CYCLE WITH POINTERS TO INVERSION RELATED DATA.
      DO K = 1, LINV
        N = - NREC
        DO I = 1, NREF
          N = N + NREC
          DO J = 1, 3
            SGX(J) = VOID(N + J)
          END DO
C * LOOP OVER SYMMETRY RELATED REFLECTIONS (EXCLUDING BRAVAIS)
          DO NS = 1, NSYMR
            CALL SGSM (5, LINE, SGX, NS, LU7, IERR)
            IHKLP = NINT (SGX(9)) * MHK + NINT (SGX(8)) * MPH
     1            + NINT (SGX(7))
            IF (K == 1) THEN
              IF (VOID(IADR + IHKLP) == 0.0) VOID(IADR + IHKLP) = I
C * TAKE CARE OF NON-CENTRO CASE (TO COMPLETE MISSING DATA)
            ELSE
              IF (VOID(IADR - IHKLP) == 0.0) VOID(IADR - IHKLP) = I
            END IF
          END DO
        END DO
      END DO
C * FIND TWIN LAW LOOPS
   20 ISHOW = 0
C * SELECT SUFFICIENT TWIN-OVERLAPPED-CANDIDATES
C * NOTE: FRIEDEL REDUNDANCY NOT HANDLED
      DO LOOP = 1, IPR(774)
        IF (LOOP == 2) THEN
C * CHECK FOR SKIPPING ROW LOOP
          IF (MSEL == 0) THEN
            ISHOW = 1
            EXIT
          ELSE
C * New Attempt after Deleting Overlap Candidate
            WRITE (LU6, 99990) JH, JK, JL
          END IF
        END IF
C * INITIAL LOWER TARGET SETTING
        RATIO = 32.0
        DO
          NSEL = 0
          DO I = 1, NREF
            N    = (I - 1) * NREC
            THI  = VOID(N + 7)
            SIGI = VOID(N + 6)
C * TEST
            IF (LOOP == 2) THEN
              IH = NINT (VOID(N + 1))
              IK = NINT (VOID(N + 2))
              IL = NINT (VOID(N + 3))
              IF (JH * IH + JK * IK + JL * IL == 0) CYCLE
            END IF
C * TEST THETA > 0.0 AND SIGI > 0.0
            IF (THI > 0.0 .AND. SIGI > 0.0) THEN
              FOKI   = VOID(N + 4)
              FCKI   = VOID(N + ICALT)
              DELSIG = MIN ((FOKI - FCKI) / SIGI, 100000.0)
C * TEST THE RATIO: (FOK - FCK) / SIG
              IF (DELSIG > RATIO) THEN
                 DO J = 1, NREF
                  IF (J /= I) THEN
                    M = (J - 1) * NREC
                    IF (ABS (THI - VOID(M + 7)) < PAR(414)) THEN
                      IF (VOID(M + ICALT) > FCKI) THEN
                        IF (NSEL < NSMAX) THEN
                          NSEL        = NSEL + 1
C * PACK FOR SORTING
                          SDAT(NSEL)  = 100000.0 - DELSIG
                          ISDAT(NSEL) = I
                          EXIT
                        END IF
                      END IF
                    END IF
                  END IF
                END DO
              END IF
            END IF
          END DO
C * DECREASE CRITERIUM WHEN TARGET REFLECTION NUMBER IS NOT REACHED
          IF (NSEL >= IPR(550) .OR. RATIO < PAR(413)) EXIT
          RATIO = RATIO / 2.0
        END DO
C * SORT ON DELTA/SIGMA
        IF (NSEL >= 25) THEN
          CALL GEN036 (SDAT, ISDAT, 1, NSEL)
          NSEL = MIN (NSEL, IPR(550))
          IF (LOOP == 1) THEN
            MSEL = 0
            DO K = 1, NSEL
              I   = (ISDAT(K) - 1) * NREC
              IHI = NINT (VOID(I + 1))
              IKI = NINT (VOID(I + 2))
              ILI = NINT (VOID(I + 3))
              DO L = 1, NSEL
                IF (L >  K) THEN
                  I       = (ISDAT(L) - 1) * NREC
                  IHJ     = NINT (VOID(I + 1))
                  IKJ     = NINT (VOID(I + 2))
                  ILJ     = NINT (VOID(I + 3))
                  IHKL(1) = IKI * ILJ - ILI * IKJ
                  IHKL(2) = ILI * IHJ - IHI * ILJ
                  IHKL(3) = IHI * IKJ - IKI * IHJ
C * COPY ARRAY
                  CALL GEN133 (IHKL, IA, 3)
                  IF (IABS (IA(1)) < 10 .AND. IABS (IA(2)) < 10 .AND.
     1              IABS (IA(3)) < 10) THEN
                    IF (IA(1) < 0) THEN
                      IA(1) = - IA(1)
                      IA(2) = - IA(2)
                      IA(3) = - IA(3)
                    ELSE IF (IA(1) == 0) THEN
                      IF (IA(2) < 0) THEN
                        IA(2) = - IA(2)
                        IA(3) = - IA(3)
                      ELSE IF (IA(2) == 0) THEN
                        IA(3) = IABS (IA(3))
                      END IF
                    END IF
                    CALL GEN107 (IA, 3, M)
                    IC(MSEL + 1) =
     1                IA(1) * 62500 + (IA(2) + 125) * 250 + IA(3) + 125
                    IF (IC(MSEL + 1) /= 31375) THEN
                      IF (MSEL == 0) THEN
                        MSEL = MSEL + 1
                        IB(MSEL) = 1000
                      ELSE
                        DO J = 1, MSEL
                          IF (IC(MSEL + 1) == IC(J)) THEN
                            IB(J) = IB(J) + 1000
                            GO TO 30
                          END IF
                        END DO
                      ENDIF
                      IF (MSEL < NP75 - 1) THEN
                        MSEL     = MSEL + 1
                        IB(MSEL) = 1000
                      END IF
                    END IF
   30               CONTINUE
                  END IF
                END IF
              END DO
            END DO
C * SORT
            IF (MSEL > 0) THEN
              WRITE (LU6, 99992)
              CALL GEN033 (IB, IC, 1, MSEL)
              DO J = MSEL, 1, -1
                IHI = IC(J) / 62500
                ILI = IC(J) - IHI * 62500
                IKI = ILI / 250
                ILI = ILI - IKI * 250
                IKI = IKI - 125
                ILI = ILI - 125
                IF (J > MSEL - 5) THEN
C * COUNT NUMBER OF NSEL VECTORS PERPENDICULAR TO J
                  N = 0
                  DO K = 1, NSEL
                    I   = (ISDAT(K) - 1) * NREC
                    IHJ = NINT (VOID(I + 1))
                    IKJ = NINT (VOID(I + 2))
                    ILJ = NINT (VOID(I + 3))
                    IF (IHI * IHJ + IKI * IKJ + ILI * ILJ == 0)
     1                N = N + 1
                  END DO
                  IB(J) = IB(J) + N
                  WRITE (LU6, 99991) IHI, IKI, ILI, IB(J) / 1000, N
                END IF
                IF (J == MSEL) THEN
                  JH = IHI
                  JK = IKI
                  JL = ILI
                END IF
              END DO
            END IF
          END IF
C * TEST FOR/START GRAPHICS MODE WINDOW
          IF (MODE == 1) THEN
C * REPORT I(CALC) SOURCE
            IF (IPR(608) == 0) THEN
              FCFMODE = 'FCF'
            ELSE
              FCFMODE = 'CIF'
            END IF
            WRITE (LU6, 99998, IOSTAT = IOST) FCFMODE
            CALL PLA262 (0)
            IF (IPR(469) /= 0) THEN
              WRITE (LU7, 99994, IOSTAT = IOST)
              CALL PLA262 (2)
            END IF
            WRITE (LU7, 99999, IOSTAT = IOST)
            CALL PLA262 (3)
          END IF
          NVC = 0
C * LOOP OVER OVERLAPPED REFLECTION CANDIDATES
          DO K = 1, NSEL
            I    = (ISDAT(K) - 1) * NREC
            THI  = VOID(I + 7)
            IHI  = NINT (VOID(I + 1))
            IKI  = NINT (VOID(I + 2))
            ILI  = NINT (VOID(I + 3))
            FOKI = VOID(I + 4)
            FCKI = VOID(I + ICALT)
            SIGI = VOID(I + 6)
            DELI = FOKI - FCKI
            DELS = DELI / SIGI
C * TEST FOR GRAPHICS MODE AND LIST SELECTED REFLECTIONS
            IF (MODE == 1) THEN
              IF (FCKI /= 0.0) THEN
                SCA = MIN (FOKI / FCKI, 999999.0)
              ELSE
                SCA = 1.0
              END IF
              WRITE (LU6, 99993, IOSTAT = IOST) K, IHI, IKI, ILI, FOKI,
     1          FCKI, SIGI, DELS, THI, SCA
              IF (IPR(469) /= 0) THEN
                CALL PLA262 (3)
                WRITE (LU7, 99997, IOSTAT = IOST)
              ELSE
                CALL PLA262 (1)
              END IF
              WRITE (LU7, 99993, IOSTAT = IOST) K, IHI, IKI, ILI, FOKI,
     1          FCKI, SIGI, DELS, THI, SCA
              IF (IPR(469) /= 0) WRITE (LU7, 99995, IOSTAT = IOST)
            END IF
C * LOOK/SELECT ELIGABLE CANDIDATES FOR OVERLAP WITHIN THETA TOLERANCE
            J = - NREC
            DO L = 1, NREF
              J = J + NREC
              IHJ = NINT (VOID(J + 1))
              IKJ = NINT (VOID(J + 2))
              ILJ = NINT (VOID(J + 3))
              IF (IABS (IHI - IHJ) + IABS (IKI - IKJ)
     1          + IABS (ILI - ILJ) /= 0) THEN
                THJ = VOID(J + 7)
                IF (THJ > 0.0) THEN
                  DTH = ABS (THI - THJ)
                  IF (DTH < PAR(414)) THEN
                    SGX(1) = IHJ
                    SGX(2) = IKJ
                    SGX(3) = ILJ
                    SGX(4) = 0.0
                    FOKJ  = VOID(J + 4)
                    FCKJ  = VOID(J + ICALT)
                    SIGJ  = VOID(J + 6)
                    IF (SIGJ > 0.0) THEN
                      DELSJ = (FOKJ - FCKJ) / SIGJ
C * LOOP OVER SYMMETRY RELATED REFLECTIONS
                      DO NS = 1, NSYMR
                        CALL SGSM (5, LINE, SGX, NS, LU7, IERR)
                        DO ILP = 1, IBLP
                          IF (ILP == 1) THEN
                            IHJ = NINT (SGX(7))
                            IKJ = NINT (SGX(8))
                            ILJ = NINT (SGX(9))
                          ELSE
C * OBVERSE <> REVERSE
                            IHJ = - NINT (SGX(8))
                            IKJ =   NINT (SGX(7)) + NINT (SGX(8))
                            ILJ =   NINT (SGX(9))
                            IF (MOD (-IHJ + IKJ + ILJ, 3) == 0) CYCLE
                          END IF
C * SPECIAL LOOP FOR NON-CENTRO SPACEGROUPS
                          DO LIV = 1, LINV
                            IF (LIV == 2) THEN
                              IHJ = - IHJ
                              IKJ = - IKJ
                              ILJ = - ILJ
                            END IF
C * POTENTIAL ROTATION AXIS
                            IHKL(1) = IHI + IHJ
                            IHKL(2) = IKI + IKJ
                            IHKL(3) = ILI + ILJ
                            IF (IHKL(1) < 0) THEN
                              IHKL(1) = - IHKL(1)
                              IHKL(2) = - IHKL(2)
                              IHKL(3) = - IHKL(3)
                            ELSE IF (IHKL(1) == 0) THEN
                              IF (IHKL(2) < 0) THEN
                                IHKL(2) = - IHKL(2)
                                IHKL(3) = - IHKL(3)
                              ELSE IF (IHKL(2) == 0) THEN
                                IHKL(3) = IABS (IHKL(3))
                              END IF
                            END IF
C * REDUCE VECTOR
                            CALL GEN107 (IHKL, 3, IYUNK)
                            IHKLP = IHKL(1)
     1                            + 200 * (IHKL(2) + 200 * IHKL(3))
                            IF (IHKLP /= 0) THEN
C * ELIMINATE IN VERSION REDUNDANCY
                              IF (NVC > 0) THEN
C * CHECK FOR PRIOR OCCURRENCE OF THIS ROTATION
                                DO N = 1, NVC
                                  ISN = 1
C * TAKE CARE OF NON-CENTRO CASE
                                  DO M = 1, LINV
                                    IF (IHKLP == ISN * JNSC(2, NX + N))
     1                                GO TO 40
                                    ISN = -1
                                  END DO
                                END DO
                              END IF
                              IF (NVC < NX - 1) THEN
                                NVC               = NVC + 1
                                N                 = NVC
C * INIT SUPPORT FREQ COUNT ROTATION AXIS
                                JNSC(1, NVC)      = 10000
                                JNSC(2, NVC)      = NVC
                                JNSC(1, NX + NVC) = 0
                                JNSC(2, NX + NVC) = IHKLP
                              END IF
C * COUNT SUPPORT FOR THIS TWIN LAW
   40                         JNSC(1, N) = JNSC(1, N) - 1
C * CONSIDER REFLECTIONS WITH LARGER F(calc) ONLY
                              DELJ = FCKJ - FCKI
                              IF (DELJ /= 0.0) THEN
                                ALFA = MIN (DELI / DELJ, 1.0)
                              ELSE
                                ALFA = 1.0
                              END IF
                              IF (ALFA >= PAR(416)) THEN
                                IF (IPR(469) /= 0) THEN
                                  CALL PLA262 (1)
                                  WRITE (LU7, 99996, IOSTAT = IOST)
     1                              IHJ, IKJ, ILJ, FOKJ, FCKJ, SIGJ,
     2                              DELSJ, THJ, DTH, ALFA, IHKL(1),
     3                              IHKL(2), IHKL(3)
                                END IF
C * COUNT SUPPORT FREQ FOR ROTATION AXIS
                                JNSC(1, NX + N) = JNSC(1, NX + N)
     1                                          + NINT (ALFA * 100.0)
                              END IF
                            END IF
                          END DO
                        END DO
                      END DO
                    END IF
                  END IF
                END IF
              END IF
            END DO
          END DO
C * ANALYSE RESULT OF ACCUMULATION
          IPR(771) = 0
          IF (NVC > 0) THEN
            IPR(543) = 0
C * SORT ROTATION AXES ON SUPPORT FREQUENCY
            CALL GEN037 (JNSC, 1, NVC)
            NMIN  = NSEL / 4
            NTWIN = 0
            CALL GEN097 (NTW, 1, MXTWN, 0)
            NVCM = MIN (IPR(607), NVC)
            DO I = 1, NVCM
              NFRQ(MXTWN) = 10000 - JNSC(1, I)
              IF (NFRQ(MXTWN) > NMIN) THEN
C * GET ORTHOGONAL COORDINATES (TAU) FOR () ROTATION AXIS IN H
                XHKL = JNSC(2, JNSC(2, I) + NX)
                CALL GEN046 (XHKL, H(1), H(2), H(3))
                IHKLSUM = 0
                DO J = 1, 3
                  IHKLR(J, MXTWN) = NINT (H(J))
                  IHKLSUM     = IHKLSUM + NINT (H(J))
                END DO
                CALL GEN002 (2, ROTQ, H, TAU, XLNG)
C * GET SUPPORT COUNT
                COSA = 0.0
C * GET MaxInd
                N1 = IPR(567)
                N2 = 2 * N1 + 1
                DO K = 1, N2
                  V(1) = K - N1 - 1
                  DO L = 1, N2
                    V(2) = L - N1 - 1
                    DO M = 1, N2
                      V(3) = M - N1 - 1
C * GET ORTHOGONAL COORDINATES (T)   FOR [] ROTATION AXIS IN V
                      IF (ABS (V(1)) + ABS (V(2)) + ABS (V(3)) > 0.5)
     1                  THEN
                        CALL GEN002 (2, OR, V, T, XLNG)
                        IF (XLNG /= 0) THEN
                          SPRD = GEN009 (T, TAU)
                          IF (SPRD > COSA) THEN
                            COSA = SPRD
                            DO J = 1, 3
                              IHKL(J) = NINT (V(J))
                              VTAU(J) = T(J)
                            END DO
                          END IF
                        END IF
                      END IF
                    END DO
                  END DO
                END DO
                ALPHA(5) = ACOS (MIN (1.0, COSA)) * RGBL(6)
C * REDUCE VECTOR
                CALL GEN107 (IHKL, 3, IYUNK)
                DO K = 1, 3
                  IHKLD(K, MXTWN) = IHKL(K)
                END DO
C * (NON)MEROHEDRAL TEST
                IF (ALPHA(MXTWN) > PAR(473)) THEN
                  IIMAX = 2
                ELSE
                  IIMAX = 1
                END IF
                DO 60 II = 1, IIMAX
                  IF (II == 2) CALL GEN113 (VTAU, TAU, 3)
C * FIND CORRESPONDING ROTATION MATRIX
                  IF (ABS(TAU(1)) + ABS(TAU(2)) < 0.0001) THEN
                    OME = 0.0
                    CHI = 90.0 / RGBL(6)
                  ELSE
                    OME = ATAN2 (TAU(2), TAU(1))
                    CHI = ATAN2 (TAU(3), SQRT (TAU(1)**2 + TAU(2)**2))
                  END IF
C * GET ROTATION MATRIX FOR OMEGA
                  CALL GEN043 (3, TP, OME)
C * GET ROTATION MATRIX FOR CHI
                  CALL GEN043 (2, TG, - CHI)
C * MULTIPLY
                  CALL GEN004 (TG, TP, TM)
                  PHI = 180.0 / RGBL(6)
                  CALL GEN043 (1, G, PHI)
C * MULTIPLY
                  CALL GEN004 (G, TM, TPS)
C * TRANSPOSE
                  CALL GEN005 (TM, YUNK)
C * COPY MATRIX
                  CALL GEN052 (YUNK, TM)
C * MULTIPLY
                  CALL GEN004 (TM, TPS, TPQ)
C * HANDLE ORTHOGONALISATION TRANSFORM
                  CALL GEN004 (TPQ, ROTQ, TPS)
C * MULTIPLY
                  CALL GEN004 (ORT, TPS, TWM(1, 1, MXTWN))
C * ELIMINATE SPACE GROUP SYMMETRY
                  IF (NSYMH > 1) THEN
                    N = 0
                    DO J = 1, 3
                      DO K = 1, 3
                        TM(J, K) = TWM(J, K, MXTWN)
                        N       = N + 1
                        TMT(N)  = TM(J, K)
                      END DO
                    END DO
                    DO J = 1, NSYMR
                      NS = J
                      CALL SGSM (6, LINE, SGX, NS, LU6, IERR)
                      IS = 1
                      DO N = 1, LINV
                        IF (N == 2) IS = -1
                        SUMT = 0.0
                        DO M = 1, 9
                          SUMT = SUMT + ABS(TMT(M) - IS * SGX(M))
                        END DO
                        IF (SUMT < 0.1) GO TO 60
                      END DO
                    END DO
C * ELIMINATE REDUNDANCY
                    DO J = 2, NSYMR
                      NS = J
C * GET TRANSPOSE OF SYMMETRY OPERATION
                      CALL SGSM (6, LINE, SGX, NS, LU6, IERR)
                      DO K = 1, 9
                        N = INT ((K - 1) / 3) + 1
                        M = MOD (K  - 1 ,  3) + 1
                        TPS(M, N) = SGX(K)
                      END DO
C * MULTIPLY
                      CALL GEN004 (TPS, TM, TPQ)
                      IS = 1
                      DO LL = 1, LINV
                        IF (LL == 2) IS = -1
                        DO 50 K = 1, IPR(771) + 1
                          DO N = 1, 3
                            DO M = 1, 3
                              IF (K <= IPR(771)) THEN
                                IF (ABS (TWM(N, M, K) - IS * TPQ(N, M))
     1                            > 0.05) GO TO 50
                              ELSE
                                IF (ABS (TWM(N, M, K) - IS * TPS(N, M))
     1                            > 0.05) GO TO 50
                              END IF
                            END DO
                          END DO
                          GO TO 60
   50                   CONTINUE
                      END DO
                    END DO
                  END IF
                  IF (MODE == 1) THEN
                    CALL PLA262 (1)
                    WRITE (LU7, 99997, IOSTAT = IOST)
                  END IF
C * ANALYSE EFFECT ON R (FUNCTION OF BASF)
                  CALL PLA415
C * CONSIDER THIS LAW AS SIGNIFICANT
                  IF (DRVAL(MXTWN) < -0.003) THEN
C * TEST FOR IDENTICAL RECIP AND DIRECT AXES
                    NEQL = 0
                    IF (IPR(771) > 0) THEN
                      DO N = 1, IPR(771)
                        NEQL = 0
                        DO M = 1, 3
                          IF (IHKLR(M, N) == IHKLR(M, MXTWN))
     1                      NEQL = NEQL + 1
                          IF (IHKLD(M, N) == IHKLD(M, MXTWN))
     1                      NEQL = NEQL + 1
                        END DO
                        IF (NEQL == 6) THEN
                          IF (DRVAL(MXTWN) < DRVAL(N)) THEN
                            KSMAL = N
                            RDROP = DRVAL(N)
                            EXIT
                          ELSE
                            GO TO 60
                          END IF
                        END IF
                      END DO
                    END IF
                    IF (NEQL < 6) THEN
                      IF (IPR(771) < 4) THEN
                        IPR(771) = IPR(771) + 1
                        KSMAL    = IPR(771)
                        RDROP    = 999.0
                      ELSE
C * REPLACE THE SMALLEST R-DROP ENTRY
                        RDROP = -999.0
                        KSMAL = 0
                        DO K = 1, 4
                          IF (DRVAL(K) > RDROP) THEN
                            RDROP = DRVAL(K)
                            KSMAL = K
                          END IF
                        END DO
                      END IF
                    END IF
                    IF (DRVAL(MXTWN) <= RDROP) THEN
                      IF (II == 1) THEN
                        NFRQ(KSMAL)  = NFRQ(MXTWN)
                      ELSE
                        NFRQ(KSMAL)  = - NFRQ(MXTWN)
                      END IF
                      NTW(KSMAL)           = NTW(MXTWN)
                      DRVAL(KSMAL)         = DRVAL(MXTWN)
                      BASFM(KSMAL)         = BASFM(MXTWN)
                      ALPHA(KSMAL)         = ALPHA(MXTWN)
                      MTWIN(KSMAL * 2 - 1) = MTWIN(2 * MXTWN - 1)
                      MTWIN(KSMAL * 2)     = KSMAL
                      DO K = 1, 3
                        IHKLR(K, KSMAL) = IHKLR(K, MXTWN)
                        IHKLD(K, KSMAL) = IHKLD(K, MXTWN)
                        DO L = 1, 3
                          TWM (K, L, KSMAL) = TWM(K, L, MXTWN)
                        END DO
                      END DO
                    END IF
                  END IF
                  NTW(MXTWN) = 0
   60           CONTINUE
              END IF
            END DO
C * SORT TWIN LAWS
            CALL GEN124 (MTWIN, 1, IPR(771) * 2)
          END IF
C * CHECK FOR NON-ZERO NUMBER OF TWIN LAWS
          IF (IPR(771) == 0 .AND. LOOP < IPR(774)) CYCLE
C * SHOW RESULTS
          ISHOW = 1
        END IF
        IF (NEXIT == 0) EXIT
      END DO
C * (ISHOW = 0) REPORT ABOUT TOO FEW TWIN OVERLAP CANDIDATES FOUND
   70 CALL PLA416 (ISHOW, MODE)
C * TEST FOR SILENT AUTO-TWIN ANALYSIS
      IF (MODE == 1) THEN
C * INSTRUCTION CYCLE
        DO
C * TEST FOR -M OPTION (FILTER MODE)
          IF (IGBL(3) /= 37) THEN
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
            IF (IGGT(1:1) == '!' .OR. IGGT(1:4) == 'PLOT') GO TO 70
            CALL PLA006 (0, IS)
C * FIND TWIN LAWS
            IF (IS == 18) THEN
              GO TO 20
C * CALC HKLF (GENERATE HKLF 5 FILE)
            ELSE IF (IS == 70) THEN
              CALL PLA417
              RETURN
C * ICALC FROM CIF/FCF TOGGLE
            ELSE IF (IS == 177) THEN
              GO TO 10
C * END (RETURN)
            ELSE IF (IS == 19) THEN
              RETURN
C * LIST (IPR/PAR/IGBL/RGBL)
            ELSE IF (IS == 29) THEN
              CALL PLA206 (-1, IFL(2)(1:3))
              CYCLE
C * SET (IPR/PAR/IGBL/RGBL)
            ELSE IF (IS == 46) THEN
              CALL PLA206 (1, IFL(2)(1:3))
              CYCLE
C * EXIT
            ELSE IF (IS == 53) THEN
              RETURN
C * TWIN PLOT
            ELSE IF (IS == 99) THEN
              IF (IWIN == 1) THEN
                CALL PLA418
              END IF
              GO TO 70
            ELSE
              CYCLE
            END IF
          ELSE
C * GENERATE HKLF 5 FILE
            IF (IPR(771) > 0) THEN
              CALL PLA417
            END IF
            RETURN
          END IF
        END DO
      END IF
      RETURN
99999 FORMAT (' Nr    H  K  L         Iobs        Icalc     SigI',
     1        ' Delt/Sig  Theta', ' DTheta  Alpha     Rot Axis', /,
     2        94('='))
99998 FORMAT (/, 7X, 'Sorted List of Twin Overlap Candidates [',
     1 A, '-Mode]', /, 76('='), /,
     1 ' Nr    H  K  L         Iobs        Icalc     SigI',
     2 ' Delt/Sig  Theta Iobs/Icalc', /, 76('='))
99997 FORMAT (1X)
99996 FORMAT (5X, 3I3, 2F13.2, 2F9.2, 3F7.2, '  (', I3, 2I4, ')')
99995 FORMAT (65('='))
99994 FORMAT (/, 'Alpha = (Iobs - Icalc) / (Jcalc - Icalc)', /)
99993 FORMAT (I3, 2X, 3I3, 2F13.2, 2F9.2, F7.2, F11.3)
99992 FORMAT (/, 'Possible Twinning Direct Lattice Rows (Experimental)')
99991 FORMAT ('[', 3I5, '], Frequency = ', I5, ', Perp to', I5)
99990 FORMAT (/, '** No Significant Twinning Matrices Found for ',
     1        'Selected Overlap Set.', /
     2        '** New Attempt after Deleting Overlap Candidates ',
     1        'Perp to [', I4,',',I4,',',I4,']')
99989 FORMAT (/, '** NADR > IADR1, STORAGE OVERFLOW IN VOID SCRATCH', /)
      END SUBROUTINE PLA414
 
      SUBROUTINE PLA415
      USE files
      USE parameters
      USE reflex
      USE lepage
      USE analysis
      USE twin
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      INTEGER :: IHKLTP
      INTEGER, DIMENSION(3) :: IHKL
      REAL :: ST
      REAL :: TH
      REAL :: THT
      REAL :: ALF
      REAL :: FCK
      REAL :: FOK
      REAL :: SIG
      REAL :: STAL
      REAL :: RVAL
      REAL :: FCKS
      REAL :: FOKS
      REAL :: FCKT
      REAL :: BASF
      REAL :: XDUM
      REAL :: YUNK
      REAL :: TERM1
      REAL :: TERM2
      REAL :: FCKT0
      REAL :: SUMFO
      REAL :: GEN095
      REAL, DIMENSION(NP76) :: SUMT
      REAL, DIMENSION(NP76) :: SUMN
      REAL, DIMENSION(NP76) :: SCLA
      REAL, DIMENSION(NP76) :: SUMFC
C * ANALYSE EFFECT ON R AS A FUNCTION OF BASF
      DO K = 1, NREF
        I = (K - 1) * NREC
        DO J = 1, 3
          IHKL(J) = NINT (VOID(I + J))
          H(J)    = IHKL(J)
        END DO
        FOK = VOID(I + 4)
        FCK = VOID(I + ICALT)
        TH  = VOID(I + 7)
        CALL GEN002 (1, TWM(1, 1, MXTWN), H, T, XDUM)
        IHT = NINT (T(1))
        IKT = NINT (T(2))
        ILT = NINT (T(3))
C * DETERMINE F(CALC) OF OVERLAPPING TWIN COMPONENT
        FCKT = 0.0
        IF (ABS (T(1) - IHT) < PAR(415)) THEN
          IF (ABS (T(2) - IKT) < PAR(415)) THEN
            IF (ABS (T(3) - ILT) < PAR(415)) THEN
              IHKLTP = ILT * MHK + IKT * MPH + IHT
              L = IADR + IHKLTP
              IF (L <= NVDR) THEN
                J = NINT (VOID(L))
                IF (J <= 0) THEN
                  N = I + 10
                  VOID(N) = FCKT
                  CYCLE
                ELSE IF (J > 0) THEN
                  FCKT0 = VOID((J - 1) * NREC + ICALT)
                END IF
                ST  = SQRT (GEN095 (PAR(191), IHT, IKT, ILT)) * PAR(17)
                IF (ST < 1.0) THEN
                  THT = ASIN (ST) * RGBL(6)
                ELSE
                  THT = 0.0
                END IF
                IF (ABS (TH - THT) <= PAR(420)) THEN
                  IF (ABS (IHT) <= HMAX0 .AND. ABS (IKT) <= KMAX0 .AND.
     1                ABS (ILT) <= LMAX0) THEN
                    NTW(MXTWN) = NTW(MXTWN) + 1
                    FCKT       = FCKT0
                  END IF
                END IF
              END IF
            END IF
          END IF
        END IF
        VOID(I + 10) = FCKT
      END DO
C * GET R-VALUE AS A FUNCTION OF BASF (0 to 1)
      SUMFO = 0.0
C * NP76 BASF TEST VALUES
      STAL  = 1.0 / (NP76 - 1)
C * ZERO SUMFC ARRAY
      CALL GEN074 (SUMFC, 1, NP76, 0.0)
C * LOOP OVER ALL REFLECTIONS TO DETERMINE NEW SCALING FACTOR
      DO K = 1, NREF
        J     = (K - 1) * NREC
        FOK   = VOID(J + 4)
        FCKT  = VOID(J + 10)
        FCK   = VOID(J + ICALT)
        SUMFO = SUMFO + FOK
        DO I = 1, NP76
          ALF = (I - 1) * STAL
          TERM1 = (1.0 - ALF) * FCK
          IF (FCKT > 0.0) THEN
            TERM2 = ALF * FCKT
          ELSE
            TERM2 = 0.0
          END IF
          SUMFC(I) = SUMFC(I) + TERM1 + TERM2
        END DO
      END DO
C * LOOP OVER ALL REFLECTIONS AND APPLY SCALING FACTOR
      DO I = 1, NP76
        SCLA(I) = SUMFC(I) / SUMFO
        SUMT(I) = 0.0
        SUMN(I) = 0.0
      END DO
      DO K = 1, NREF
        J   = (K - 1) * NREC
        FOK = VOID(J + 4)
        SIG = VOID(J + 6)
        IF (FOK > 2.0 * SIG) THEN
          FCKT = VOID(J + 10)
          FCK  = VOID(J + ICALT)
          DO I = 1, NP76
            ALF     = (I - 1) * STAL
            FCKS    = SQRT ((1.0 - ALF) * FCK + ALF * FCKT)
            FOKS    = SQRT (SCLA(I) * FOK)
            SUMT(I) = SUMT(I) + ABS (FOKS - FCKS)
            SUMN(I) = SUMN(I) + FOKS
          END DO
        END IF
      END DO
C * FIND MINIMUM RVAL/BASF VALUE
      BASF = 0.0
      IF (SUMN(1) > 0) THEN
        RVAL = SUMT(1) / SUMN(1)
        DRVAL(MXTWN) = - RVAL
        DO I = 2, NP76
          IF (SUMN(I) /= 0.0) THEN
            YUNK = SUMT(I) /SUMN(I)
            IF (YUNK < RVAL) THEN
              BASF = (I - 1) * STAL
              RVAL = YUNK
            END IF
          END IF
        END DO
      ELSE
        RVAL = 0.0
      END IF
C * STORE MINIMUM
      DRVAL(MXTWN)         = DRVAL(MXTWN) + RVAL
      BASFM(MXTWN)         = BASF
      MTWIN(MXTWN * 2 - 1) = NINT (DRVAL(MXTWN) * 1000.0)
      MTWIN(MXTWN * 2    ) = MXTWN
      RETURN
      END SUBROUTINE PLA415
 
      SUBROUTINE PLA416 (ISHOW, MODE)
C * SHOW TWINROTMAT RESULTS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE analysis
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: MODE
      INTEGER :: LOUT
      INTEGER :: NCOL
      INTEGER :: NCOL3
      INTEGER :: NLIST
      INTEGER :: ISHOW
      CHARACTER(len=9) :: LIST
C * ISHOW  0 = Report 'No Twinning Detected'
C *        1 = Show Twinning Laws
C * MODE   1 = GRAPHICS MODE
C *        2 = NON-GRAPHICS MODE
C * IPR(771) = Number of Twinning Laws for Display
      NLIST = 0
C * REPORT ABOUT TOO FEW TWIN CANDIDATES
      IF (ISHOW == 0) THEN
        IF (MODE == 2) THEN
          LOUT = LU13
        ELSE
          LOUT = LU6
          IF (IWIN == 1) THEN
            CALL GGIP (HORS, VERT, 0.0, 1)
            CALL PLA439 (0.0,
     1 'Too Few Fobs > Fcalc Reflections for TwinRotMat Analysis',
     2   56, 0.45, 2, 2, 1.0, 8.0)
          END IF
        END IF
        WRITE (LOUT, 99984, IOSTAT = IOST) NSEL
        IF (ICALT == 5) THEN
          WRITE (LOUT, 99978, IOSTAT = IOST)
        ELSE
          WRITE (LOUT, 99986, IOSTAT = IOST)
        END IF
        WRITE (LOUT, 99982, IOSTAT = IOST)
      ELSE
        IF (MODE == 1) THEN
          IF (IWIN == 1) THEN
            CALL GGIP (HORS, VERT, 0.0, 1)
            CALL PLA110 (HORS, VERT, -1)
C * FCF FILE TYPE
            LIST = ' '
            IF (IGBL(9) == 1) THEN
              LIST = 'FCF-LIST4'
            ELSE IF (IGBL(9) == 23) THEN
              LIST = 'FCF-LIST6'
            ELSE IF (IGBL(9) == 25) THEN
              LIST = 'FCF-LIST8'
            END IF
C * REPORT SOURCE OF F(calc)  (i.e. CIF or FCF)
            IF (ICALT == 5) THEN
              BCD  = 'Ical from Coordinates, Iobs from '//LIST
              NCOL = 1
            ELSE
              BCD  = 'Ical from FCF File, Iobs from '//LIST
              NCOL = 2
            END IF
            CALL PLA439 (90.0, BCD, 42, 0.35, NCOL, 1, 1.5, 0.8)
            CALL GGIP (0.0, 2.0, 0.0, 0)
            BCD = 'TwinRotMat'//CHAR (0)
            CALL PLA439 (0.0,  BCD, 10, 1.4, 4, 8, 7.0, VERT - 1.8)
            CALL PLA439 (0.0,  BCD, 10, 1.4, 2, 8, 6.8, VERT - 1.9)
            WRITE (BCD, 99996, IOSTAT = IOST) JID(1:14)
            VRT = VERT - 3.0
            CALL PLA439 (0.0,  BCD, 80, 0.35, 5 + IGBL(68), 2, 1.0, VRT)
            WRITE (BCD, 99991, IOSTAT = IOST)
     1        PAR(17), (PAR(100 + I), I = 1, 6), SPGRNM(1)(1:11)
            VRT = VRT - 1.0
            CALL PLA439 (0.0,  BCD, 80, 0.35, 1, 2, 1.0, VRT)
          END IF
        ELSE
          WRITE (LU13, 99984, IOSTAT = IOST) NSEL
          IF (ICALT == 5) THEN
            WRITE (LU13, 99978, IOSTAT = IOST)
          ELSE
            WRITE (LU13, 99986, IOSTAT = IOST)
          END IF
        END IF
        IF (MODE == 1) NLIST = NLIST + 1
C * LIST/DISPLAY SELECTION CRITERIA
        WRITE (BCD, 99990, IOSTAT = IOST) PAR(413), PAR(414), IPR(550)
        IF (NLIST == 1) THEN
          CALL PLA262 (0)
          CALL PLA262 (9)
          WRITE (LU6, 99997, IOSTAT = IOST)
          WRITE (LU7, 99997, IOSTAT = IOST)
          WRITE (LU6, 99998, IOSTAT = IOST) BCD
          WRITE (LU7, 99998, IOSTAT = IOST) BCD
        END IF
        IF (IWIN == 1 .AND. MODE == 1) THEN
          VRT = VRT - 0.7
          CALL PLA439 (0.0,  BCD, 80, 0.35, 1, 2, 1.0, VRT)
        END IF
        WRITE (BCD, 99983, IOSTAT = IOST)
     1    NREF, NSEL, IPR(567), PAR(415), PAR(420)
        IF (NLIST == 1) THEN
          WRITE (LU6, 99997, IOSTAT = IOST)
          WRITE (LU7, 99997, IOSTAT = IOST)
          WRITE (LU7, 99987, IOSTAT = IOST) PAR(17)
          WRITE (LU6, 99998, IOSTAT = IOST) BCD
          WRITE (LU7, 99998, IOSTAT = IOST) BCD
          WRITE (LU6, 99997, IOSTAT = IOST)
          WRITE (LU7, 99997, IOSTAT = IOST)
        END IF
        IF (IWIN == 1 .AND. MODE == 1) THEN
          VRT = VRT - 0.7
          CALL PLA439 (0.0,  BCD, 80, 0.35, 1, 2, 1.0, VRT)
          CALL GGIP (0.0, 0.0, 0.0, 6)
        END IF
        IF (NSEL == 0) THEN
          IF (IWIN == 1 .AND. MODE == 1) THEN
            CALL PLA439 (0.0, 'No Refl Selected', 16, 1.2, 2, 10, 4.0,
     1                   8.0)
          END IF
          IF (MODE == 2) WRITE (LU13, 99985, IOSTAT = IOST)
          RETURN
        END IF
        IF (IPR(771) > 0) THEN
          IF (IWIN == 1 .AND. MODE == 1) THEN
            CALL GGIP (0.0,        VRT - 0.5, 0.0, 3)
            CALL GGIP (HORS,       VRT - 0.5, 0.0, 2)
            CALL GGIP (1.8,        VRT - 0.5, 0.0, 3)
            CALL GGIP (1.8,        0.0,       0.0, 2)
            CALL GGIP (HORS - 4.1, VRT - 0.5, 0.0, 3)
            CALL GGIP (HORS - 4.1, 0.0      , 0.0, 2)
          END IF
          NCOL3 = 1
          DO J = 1, IPR(771)
            I = MTWIN(J * 2)
            IF (BASFM(I) > 0.0 .AND. DRVAL(I) <= -0.01 .AND.
     1        (NTW(I) > 0.5 * NTW(MTWIN(2)))) THEN
                NCOL         = 3
                IPR(570 + J) = NCOL3
                NCOL3        = 0
            ELSE
              NCOL = 4
            END IF
            WRITE (BCD, 99999, IOSTAT = IOST)
     1        (IHKLR(K, I), K = 1, 3), (IHKLD(K, I), K = 1, 3),
     2        ALPHA(I), IABS (NFRQ(I))
            IF (NFRQ(I) > 0) THEN
              WRITE (PRBUF, 99981, IOSTAT = IOST)
            ELSE
              WRITE (PRBUF, 99980, IOSTAT = IOST)
            END IF
            IF (NLIST == 1) THEN
              CALL PLA262 (2)
              WRITE (LU6, 99997, IOSTAT = IOST)
              WRITE (LU7, 99997, IOSTAT = IOST)
              WRITE (LU6, 99998, IOSTAT = IOST) BCD
              WRITE (LU7, 99998, IOSTAT = IOST) BCD
            END IF
            IF (NCOL == 3) THEN
              IF (MODE == 2) THEN
                WRITE (LU13, 99997, IOSTAT = IOST)
                WRITE (LU13, 99998, IOSTAT = IOST) BCD
                WRITE (LU13, 99998, IOSTAT = IOST) PRBUF(1:37)
                WRITE (LU13, 99997, IOSTAT = IOST)
              END IF
              WRITE (NQ1, 99989, IOSTAT = IOST) (IHKLR(K, I), K = 1, 3)
              WRITE (NQ2, 99988, IOSTAT = IOST) (IHKLD(K, I), K = 1, 3)
C * TEST FOR ROTATION ABOUT () or []
              IF (NFRQ(I) > 0) THEN
                NQ2 = ' '
              ELSE
                NQ1 = ' '
              END IF
C * ALERT _930 - TWINNING INDICATION IN FCF
              IF (ICALT == 11) THEN
                CALL PLA236 (930, 2, -999.0,   BASFM(I), NQ1, NQ2)
              ELSE
C * ALERT _931 - TWINNING INDICATION IN CIF/HKL
                CALL PLA236 (931, 2, -999.0, BASFM(I), NQ1, NQ2)
              END IF
            END IF
            IF (IWIN == 1 .AND. MODE == 1) THEN
              VRT = VRT - 1.0
              BCD(80:80) = CHAR (0)
              CALL PLA439 (0.0,  BCD, 80, 0.3, NCOL, 2, 2.0, VRT)
              VRT = VRT - 0.4
              CALL PLA439 (0.0,  PRBUF, 37, 0.3, NCOL, 2, 2.0, VRT)
            END IF
            IF (NLIST == 1) THEN
              CALL PLA262 (4)
              WRITE (LU6, 99998, IOSTAT = IOST) PRBUF(1:37)
              WRITE (LU7, 99998, IOSTAT = IOST) PRBUF(1:37)
            END IF
            WRITE (BCD, 99994, IOSTAT = IOST)
     1        (TWM(1, L, I), L = 1, 3), NTW(I)
            IF (NLIST == 1) THEN
              WRITE (LU6, 99998, IOSTAT = IOST) BCD
              WRITE (LU7, 99998, IOSTAT = IOST) BCD
            END IF
            IF (NCOL == 3 .AND. MODE == 2)
     1        WRITE (LU13, 99998, IOSTAT = IOST) BCD
            IF (IWIN == 1 .AND. MODE == 1) THEN
              VRT = VRT - 0.6
              CALL PLA439 (0.0,  BCD, 80, 0.3, NCOL, 2, 2.0, VRT)
            END IF
            WRITE (BCD, 99993, IOSTAT = IOST)
     1        (TWM(2, L, I), L = 1, 3), BASFM(I)
            IF (NLIST == 1) THEN
              WRITE (LU6, 99998, IOSTAT = IOST) BCD
              WRITE (LU7, 99998, IOSTAT = IOST) BCD
            END IF
            IF (NCOL == 3 .AND. MODE == 2)
     1        WRITE (LU13, 99998, IOSTAT = IOST) BCD
            IF (IWIN == 1 .AND. MODE == 1) THEN
              VRT = VRT - 0.6
              CALL PLA439 (0.0,  BCD, 80, 0.3, NCOL, 2, 2.0, VRT)
              WRITE (NQ1, 99995, IOSTAT = IOST) J
              CALL PLA439 (0.0, NQ1, 1, 1.5, 1, 2 , HORS - 2.5, VRT)
            END IF
            WRITE (BCD, 99992, IOSTAT = IOST)
     1        (TWM(3, L, I), L = 1, 3), DRVAL(I)
            IF (NLIST == 1) THEN
              WRITE (LU6, 99998, IOSTAT = IOST) BCD
              WRITE (LU7, 99998, IOSTAT = IOST) BCD
            END IF
            IF (NCOL == 3 .AND. MODE == 2)
     1        WRITE (LU13, 99998, IOSTAT = IOST) BCD
            IF (IWIN == 1 .AND. MODE == 1) THEN
              VRT = VRT - 0.6
              CALL PLA439 (0.0,  BCD, 80, 0.3, NCOL, 2, 2.0, VRT)
              CALL GGIP (1.8,  VRT - 0.4, 0.0, 3)
              CALL GGIP (HORS, VRT - 0.4, 0.0, 2)
            END IF
          END DO
C * WARNING ABOUT SYMMETRY RELATED TWINLAWS
          IF (NLIST == 1) THEN
            WRITE (LU6, 99979, IOSTAT = IOST)
            WRITE (LU7, 99979, IOSTAT = IOST)
          ENDIF
        ELSE
          IF (MODE == 1) THEN
            IF (IWIN == 1) THEN
              CALL PLA439 (0.0, 'No Twin Law Detected', 20, 1.2, 2, 10,
     1                     3.0, 8.0)
            END IF
          END IF
        END IF
        IF (MODE == 2) THEN
          IF (MODE == 2) WRITE (LU13, 99985, IOSTAT = IOST)
          WRITE (LU13, 99997, IOSTAT = IOST)
        END IF
      END IF
      RETURN
99999 FORMAT ('2-axis (', 3I4, ' ) [',3I4, ' ]',
     1        ', Angle () [] =', F6.2, ' Deg, Freq =', I6)
99998 FORMAT (A)
99997 FORMAT (1X)
99996 FORMAT ('Analysis of Fo/Fc Data for Unaccounted (Non)Merohedral',
     1        ' Twinning for: ', A)
99995 FORMAT (I1)
99994 FORMAT ('(', F6.3, 2F9.3, ')   (h1)   (h2)', 19X,
     1         'Nr Overlap =', I6)
99993 FORMAT ('(', F6.3, 2F9.3, ') * (k1) = (k2)', 25X,
     1         'BASF =', F6.2)
99992 FORMAT ('(', F6.3, 2F9.3, ')   (l1)   (l2)', 24X,
     1         'DEL-R =', F6.3)
99991 FORMAT ('Cell:', F8.5, 3F7.3, 3F7.2, 2X, 'Spgr: ', A)
99990 FORMAT ('Criteria: DeltaI/SigmaI .GT.', F5.1, ', DeltaTheta',
     1        F5.2, ' Deg., NselMin =', I4)
99989 FORMAT (' (', 3I2, ')')
99988 FORMAT ('[', 3I2, '] ')
99987 FORMAT ('Wavelength Used in this Analysis', F10.5, ' Ang.', /)
99986 FORMAT ('Note: This Analysis is Based on Fc Taken from Fo/Fc',
     1        ' File (FCF)', /, 79('='))
99985 FORMAT (/,
     1  'No Applicable Twin Law(s) Detected from Fo/Fc Analysis',
     2  '-or Already Accounted for')
99984 FORMAT (/, 'Section 8', /, 79('='), /,
     1 'Check for Unaccounted Twinning with the TwinRotMat Algorithm',
     2  ' - N(selec) =', I6, /, 79('='))
99983 FORMAT ('N(refl) =', I7, ', N(selected) =', I5, ', IndMax =',
     1        I3, ', CritI =', F4.1, ', CritT =', F5.2)
99982 FORMAT (/, ':: Too few Fobs >> Fcalc Reflections for',
     1        ' TwinRotMat Analysis', /)
99981 FORMAT (8X,  13('*'))
99980 FORMAT (24X, 13('*'))
99979 FORMAT (/, 'Note: Symmetry Equivalent Twin Laws are not Listed !',
     1        /)
99978 FORMAT ('Note: This Analysis is Based on Fc calculated from',
     1        ' Coordinates in the CIF.', /
     1        79('='))
      END SUBROUTINE PLA416
 
      SUBROUTINE PLA417
C * GENERATE HKLF5 FILE
      USE files
      USE parameters
      USE cchar
      USE reflex
      USE lepage
      USE analysis
      USE twin
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IHT
      INTEGER :: IKT
      INTEGER :: ILT
      INTEGER :: IRT
      INTEGER :: NTC
      INTEGER :: NTX
      INTEGER :: NTY
      INTEGER :: NRTW
      INTEGER :: ISIG
      INTEGER :: IFOK
      INTEGER :: IPRN
      INTEGER :: NRTWIN
      INTEGER :: IHKLTP
      INTEGER, DIMENSION(3) :: IHKL
      REAL :: ST
      REAL :: TH
      REAL :: THT
      REAL :: SIG
      REAL :: FCK
      REAL :: FOK
      REAL :: XDUM
      REAL :: FCKT
      REAL :: FCKT0
      REAL :: GEN095
      CHARACTER(len=4)  :: KEY
      CHARACTER(len=76) :: JDM
      NTX = 0
      IRT = (2 - ICNTR) * IPR(575) + 1
      CALL PLA262 (0)
      CALL PLA262 (2)
      WRITE (LU7, 99999, IOSTAT = IOST)
      NTWIN = 0
C * SELECT/COPY ACTIVE TWIN MATRICES
      DO K = 1, MXTWN - 1
        IF (IPR(570 + K) == 1) THEN
          NTWIN       = NTWIN + 1
          MTW(NTWIN)  = MTWIN(K * 2)
          NTW0(NTWIN) = K
        END IF
      END DO
      IPR(2) = -11
      DO K = 1, NREF
        N = (K - 1) * NREC
        DO I = 1, 3
          IHKL(I) = NINT (VOID(N + I))
          H(I)    = IHKL(I)
        END DO
        FOK  = VOID(N + 4)
        FCK  = VOID(N + ICALT)
        SIG  = VOID(N + 6)
        TH   = VOID(N + 7)
        IFOK = NINT (FOK * SCL)
        ISIG = NINT (SIG * SCL)
        NTY  = 0
        DO NRTW = 1, NTWIN
          NRTWIN = MTW(NRTW)
          CALL GEN002 (1, TWM(1, 1, NRTWIN), H, T, XDUM)
          IHT  = NINT (T(1))
          IKT  = NINT (T(2))
          ILT  = NINT (T(3))
          FCKT = 0.0
          IPRN = 0
          IF (ABS (T(1) - IHT) < PAR(415)) THEN
            IF (ABS (T(2) - IKT) < PAR(415)) THEN
              IF (ABS (T(3) - ILT) < PAR(415)) THEN
                IHKLTP = ILT * MHK + IKT * MPH + IHT
                J      = NINT (VOID(IADR + IHKLTP))
                IF (J < 0) THEN
                  WRITE (LU6, 99989) IHT,IKT,ILT
                  CYCLE
                ELSE IF (J > 0) THEN
                  FCKT0 = VOID((J - 1) * NREC + 5)
                ELSE
                  WRITE (LU6, 99993, IOSTAT = IOST)
     1              (IHKL(J), J = 1, 3), (NINT (T(J)), J = 1, 3)
                END IF
                ST = SQRT (GEN095 (PAR(191), IHT, IKT, ILT)) * PAR(17)
                IF (ST < 1.0) THEN
                  THT = ASIN (ST) * RGBL(6)
                  IF (THT > 28.3) WRITE(6,'(3I4,F8.2)')IHT,IKT,ILT,THT
                ELSE
                  THT = 0.0
                END IF
                IF (ABS (TH - THT) <= PAR(420)) THEN
                  IF (ABS (IHT) <= HMAX0 .AND. ABS (IKT) <= KMAX0 .AND.
     1                ABS (ILT) <= LMAX0) THEN
                    NTY  = 1
                    FCKT = FCKT0
                    NTC  = - (NRTW + 1) * IRT
C * TEST FOR RACEMIC TWIN INCLUDE
                    IF (IPR(575) == 1) THEN
                      WRITE (LU17, 99998, IOSTAT = IOST)
     1                  -IHT, -IKT, -ILT, IFOK, ISIG, NTC
                    END IF
                    WRITE (LU17, 99998, IOSTAT = IOST)
     1                IHT,  IKT,  ILT, IFOK, ISIG, NTC + (IRT - 1)
                    WRITE (LU6, 99998, IOSTAT = IOST)
     1                IHT,  IKT,  ILT, IFOK, ISIG, NTC + (IRT - 1)
                    IPRN = 1
                  END IF
                END IF
              END IF
            END IF
          END IF
        END DO
C * TEST FOR RACEMIC TWIN INCLUDE
        IF (IPR(575) == 1) THEN
          WRITE (LU17, 99998, IOSTAT = IOST)
     1      ( -NINT (H(J)), J = 1, 3), IFOK, ISIG, -2
        END IF
        WRITE (LU17, 99998, IOSTAT = IOST)
     1   (NINT (H(J)), J = 1, 3), IFOK, ISIG, 1
        NTX = NTX + NTY
        IF (IPR(469) /= 0) THEN
          CALL PLA262 (1)
          IF (IPRN /= 0) THEN
            WRITE (LU7, 99997, IOSTAT = IOST)
     1        NTX, (NINT (H(J)), J = 1, 3), FOK, FCK, SIG, IHT, IKT,
     2        ILT, FCKT, TH, THT, TH - THT
          ELSE
            WRITE (LU7, 99996, IOSTAT = IOST)
     1        (NINT (H(J)), J = 1, 3), FOK, FCK, SIG
          END IF
        END IF
        VOID(N + 10) = FCKT
      END DO
      WRITE (LU6, 99995, IOSTAT = IOST) (NTW0(K), K = 1, NTWIN)
      CALL PLA262 (0)
      WRITE (LU7, 99995, IOSTAT = IOST) (NTW0(K), K = 1, NTWIN)
      IF (IRT == 1) THEN
        WRITE (LU6, 99994, IOSTAT = IOST) NREF, NTX, (BASFM(MTW(I)),
     1                     I = 1, NTWIN)
        WRITE (LU7, 99994, IOSTAT = IOST) NREF, NTX, (BASFM(MTW(I)),
     1                     I = 1, NTWIN)
      ELSE
        WRITE (LU6, 99994, IOSTAT = IOST) NREF, NTX,
     1                     (BASFM(MTW(NTWIN + 1 - I)) / 2.0,
     2                      BASFM(MTW(NTWIN + 1 - I)) / 2.0,
     3                     I = 1, NTWIN)
        WRITE (LU7, 99994, IOSTAT = IOST) NREF, NTX,
     1                     (BASFM(MTW(NTWIN + 1 - I)) / 2.0,
     2                      BASFM(MTW(NTWIN + 1 - I)) / 2.0,
     3                     I = 1, NTWIN)
      END IF
C * COPY/EDIT embedded .ins FILE
 
      IF (IPR(663) /= 0) THEN
        REWIND (UNIT = LU24, IOSTAT = IOST)
        OPEN (UNIT = LU62, FILE = NAMEFIL(1:KNMFIL)//'_tw.ins',
     1    STATUS = 'UNKNOWN')
        DO
          READ (LU24, 99990, IOSTAT = IOST) KEY, JDM
          IF (IOST /= 0) EXIT
          CALL GEN020 (1, KEY, 1, 4)
          IF (KEY == 'HKLF') THEN
            WRITE (LU62, 99992, IOSTAT = IOST) 'HKLF 5'
            CYCLE
          ELSE IF (KEY == 'FVAR') THEN
            WRITE (LU62, 99991) (BASFM(MTW(I)), I = 1, NTWIN)
          ELSE IF (KEY == 'BASF') THEN
            CYCLE
          ELSE IF (KEY == 'TWIN') THEN
            CYCLE
          ELSE IF (KEY == 'OMIT') THEN
            CYCLE
          ELSE IF (KEY == 'WGHT') THEN
            JDM = ' 0.1'
          ELSE IF (KEY == 'MERG') THEN
            JDM = ' 0'
          END IF
          WRITE (LU62, 99990, IOSTAT = IOST) KEY, JDM
        END DO
        CLOSE (UNIT = LU24, STATUS = 'DELETE', IOSTAT = IOST)
        IPR(663) = 0
      END IF
C * COPY HKLF5 REFLECTION SET
      OPEN (UNIT = LU63, FILE = NAMEFIL(1:KNMFIL)//'_tw.hkl',
     1  STATUS = 'UNKNOWN')
      REWIND (UNIT = LU17, IOSTAT = IOST)
      DO
        READ  (LU17, 99992, IOSTAT = IOST) IDM
        IF (IOST /= 0) EXIT
        WRITE (LU63, 99992, IOSTAT = IOST) IDM
      END DO
      CLOSE (UNIT = LU63)
      CLOSE (UNIT = LU17, STATUS = 'DELETE')
      IF (IPR(2) == 0) IPR(2) = -11
      RETURN
99999 FORMAT (3X, 'nr', 6X, 'H   K   L', 7X, 'FOK', 7X, 'FCK', 7X,
     1        'SIG', 5X, 'HT  KT  LT', 6X, 'FCKT',
     2        8X, 'TH', 7X, 'THT', 4X, 'DEL-TH', /, 105('='))
99998 FORMAT (3I4, 2I8, I4)
99997 FORMAT (I5, I7, 2I4, 3F10.2, I7, 2I4, 4F10.2)
99996 FORMAT (5X, I7, 2I4, 3F10.2)
99995 FORMAT (/, ':: TwinRotMatrix #', 4I5)
99994 FORMAT (':: Total Number of Reflections in HKLF 5 file   =', I6,
     2  /, '::       Number of which with Twin Contribution =', I6,
     3  /, '::                          Estimated BASF Line =', 8F6.2)
99993 FORMAT (':: Unobserved Partner for ', 3I5, ' : ', 3I5)
99992 FORMAT (A)
99991 FORMAT ('BASF', 9F6.3)
99990 FORMAT (A, A)
99989 FORMAT ('Missing', 3I5)
      END SUBROUTINE PLA417
 
      SUBROUTINE PLA418
C * PLOT TWIN LATTICE OVERLAP
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE spgrdata
      USE reflex
      USE lepage
      USE analysis
      USE twin
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: NV
      INTEGER :: NADD
      INTEGER :: IASJ
      INTEGER :: IBRV
      INTEGER :: IPEN
      INTEGER :: IPLT
      INTEGER :: IHKLP
      INTEGER :: NSTEP
      INTEGER :: NTPLT
      INTEGER, DIMENSION(3) :: IMX
      INTEGER, DIMENSION(3) :: JMX
      INTEGER, DIMENSION(8) :: IAS
      REAL :: HH
      REAL :: RD
      REAL :: VH
      REAL :: STL
      REAL :: SCF
      REAL :: OME
      REAL :: CHI
      REAL :: FOK
      REAL :: FCK
      REAL :: FCX
      REAL :: FCMX
      REAL :: BAS1
      REAL :: BAS2
      REAL :: SCPR
      REAL :: RADM
      REAL :: XDUM
      REAL :: XLNG
      REAL :: XTAU
      REAL :: YUNK
      REAL :: SCPR0
      REAL :: RADIUS
      REAL :: GEN009
      REAL :: SIGI
      REAL, DIMENSION(3, 8) :: AS
      REAL, DIMENSION(3)    :: XYZ
      REAL, DIMENSION(3)    :: TAU
      REAL, DIMENSION(3, 3) :: ROT
      REAL, DIMENSION(3, 3) :: YUNKAR
C * CHECK FOR AND DISPLAY OF TWINLAW IN THE RANGE (1, 2, 3, 4)
      IF (IPR(543) <= 0 .OR. IPR(543) > 4) RETURN
C * CHECK TWIN DATA
      NTPLT = MTWIN(IPR(543) * 2)
      IF (NTPLT == 0) RETURN
C * LOCATE ORIGIN IN CENTER WINDOW
      HH   = HORS / 2.0
      VH   = VERT / 2.0
      RD   = 0.9 * VH
      IBRV = IPR(241)
C * ZERO SGX ARRAY
      CALL GEN074 (SGX, 1, 13, 0.0)
      DO
C * GET REQUESTED RECIPROCAL LATTICE RESOLUTION (SIN(THETA) / LAMBDA)
        STL  = PAR(449)
        RADM = RD
        DO I = 1, 3
          IMX(I) = INT (2 * STL * PAR(100 + I))
          JMX(I) = 2 * IMX(I) + 1
          RADM   = MIN (RADM, RD / IMX(I))
        END DO
        RADM = RADM * 0.45
C * TOP STORED REFLECTION DATA FOR STORING LATTICE DATA
        NV   = NADR
        FCMX = 0.0
        DO I = 1, JMX(1)
          H(1) = I - IMX(1) - 1
          DO J = 1, JMX(2)
            H(2) = J - IMX(2) - 1
            DO K = 1, JMX(3)
              H(3) = K - IMX(3) - 1
C * CHECK FOR BRAVAIS LATTICE ABSENCE
              YUNK = 0.0
              IF (IBRV > 1) THEN
                SGX(1)  = H(1)
                SGX(2)  = H(2)
                SGX(3)  = H(3)
                SGX(12) = -1
                CALL SGSM (27, LINE, SGX, 0, 0, IERR)
                IF (NINT (SGX(12)) > 0) YUNK = -1.0
              END IF
C * COLLECT INFO FOR MAIN LATTICE & OVERLAPPING TWIN-LATTICE
              DO L = 1, 2
C * MAIN COMPONENT (L = 1)
                IF (L == 1) THEN
                  T(1) = H(1)
                  T(2) = H(2)
                  T(3) = H(3)
                  FCK  = 0.0
                  IPEN = 1
                  IF (IABS (NINT (T(1))) <= HMAX0 .AND.
     1                IABS (NINT (T(2))) <= KMAX0 .AND.
     2                IABS (NINT (T(3))) <= LMAX0) THEN
                    IHKLP = NINT (T(3)) * MHK + NINT (T(2)) * MPH
     1                    + NINT (T(1))
                    N     = NINT(VOID(IADR + IHKLP))
                    IF (N > 0) THEN
                      FOK  = VOID((N - 1) * NREC + 4)
                      FCK  = VOID((N - 1) * NREC + 5)
                      SIGI = VOID((N - 1) * NREC + 6)
C * REGISTER STRONG OVERLAP CANDIDATE 'SIZE'
                      IF (SIGI /= 0.0) THEN
                        IF ((FOK - FCK) / SIGI > DELS) THEN
                          IPEN = 5
                        END IF
                      END IF
                    END IF
                  END IF
                  IF (FCK > 0) THEN
                    FCX = LOG (FCK)
                  ELSE
                    FCX = 0.0
                  END IF
                  FCMX = MAX (FCMX, FCX)
C * TWIN COMPONENT (L = 2)
                ELSE
                  CALL GEN002 (1, TWM(1, 1, NTPLT), H, T, XDUM)
                  IPEN = 2
                END IF
                CALL GEN002 (1, ROTQ, T, XYZ, XDUM)
C * REGISTER STRONG OVERLAP CANDIDATE 'SIZE'
                IF (SQRT (GEN009 (XYZ, XYZ)) < 2 * STL) THEN
                  VOID(NV + 1)  = IPEN
                  VOID(NV + 2)  = H(1)
                  VOID(NV + 3)  = H(2)
                  VOID(NV + 4)  = H(3)
                  VOID(NV + 5)  = XYZ(1)
                  VOID(NV + 6)  = XYZ(2)
                  VOID(NV + 7)  = XYZ(3)
                  VOID(NV + 9)  = YUNK
                  VOID(NV + 10) = FCX
                  NV            = NV + 10
                END IF
              END DO
            END DO
          END DO
        END DO
   10   CALL GEN097 (IAS, 1, 8, 0)
C * ROTATE ZONE AXIS (A, B or C) ALONG Z
   20   DO I = 1, 3
          TAU(I) = OR(I, IPR(394))
        END DO
        XTAU = SQRT (GEN009 (TAU, TAU))
        DO I = 1, 3
          TAU(I) = TAU(I) / XTAU
        END DO
        IF (ABS (TAU(1)) + ABS (TAU(2)) < 0.0001) THEN
          OME = 0.0
          CHI = 90.0 / RGBL(6)
        ELSE
          OME = ATAN2 (TAU(2), TAU(1))
          CHI = ATAN2 (TAU(3), SQRT(TAU(1)**2 + TAU(2)**2))
        END IF
C * ROTATION MATRIX FOR OMEGA
        CALL GEN043 (3, TP, OME)
C * GET ROTATION MATRIX FOR 90 - CHI
        CALL GEN043 (2, TG, 90.0 / RGBL(6) - CHI)
        CALL GEN004 (TG, TP, ROT)
        IF (IPR(394) == 2 .OR. IPR(394) == 3) THEN
          CALL GEN043 (3, TG, 180.0 / RGBL(6))
        ELSE
          CALL GEN043 (3, TG, 90.0 / RGBL(6))
        END IF
        CALL GEN004 (TG, ROT, YUNKAR)
        CALL GEN052 (YUNKAR, ROT)
        BCD = 'PlotTwinLat'//CHAR (0)
        CALL GGIP (HORS, VERT, 0.0, 1)
        CALL PLA439 (90.0,  BCD, 11, 1.2, 2, 8, 2.3, 2.5)
        CALL PLA110 (HORS, VERT, -1)
C * DISPLAY TWIN MATRIX
        VRT = VERT - 0.4
        CALL PLA439 (0.0, 'Twin Matrix', 11, 0.25, 5, 1, 2.0, VRT)
        VRT = VRT - 0.2
        DO I = 1, 3
          WRITE (LINE, 99999, IOSTAT = IOST)
     1      (TWM(I, J, NTPLT), J = 1, 3)
C * DUMMY
          IF (IOST == -999) RETURN
          VRT = VRT - 0.4
          CALL PLA439 (0.0, LINE, 21, 0.25, 1, 1, 0.5, VRT)
        END DO
C * DISPLAY (DIRECT) ROTATION AXIS
        VRT = VRT - 0.7
        WRITE (LINE, 99996, IOSTAT = IOST) (IHKLD(I, NTPLT), I = 1, 3)
        CALL PLA439 (0.0, LINE, 17, 0.30, 1, 1, 1.0, VRT)
C * DISPLAY (RECIPROCAL) ROTATION AXIS
        VRT = VRT - 0.6
        WRITE (LINE, 99998, IOSTAT = IOST) (IHKLR(I, NTPLT), I = 1, 3)
        CALL PLA439 (0.0, LINE, 17, 0.30, 1, 1, 1.0, VRT)
C * DISPLAY ZONE AXIS
        IF (IPR(394) == 1) THEN
          LINE = 'Zone - H ='
        ELSE IF (IPR(394) == 2) THEN
          LINE = 'Zone - K ='
        ELSE
          LINE = 'Zone - L ='
        END IF
C * DISPLAY LEVEL
        WRITE (LINE(11:13), 99997, IOSTAT = IOST) IPR(576)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 13, 0.35, 5, 1, 1.0, VRT)
C * DISPLAY RESOLUTION
        WRITE (LINE, '(''Resol = '', F5.1)', IOSTAT = IOST) PAR(449)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.0, VRT)
C * DISPLAY BASF
        WRITE (LINE, '('' BASF ='', F6.2)', IOSTAT = IOST) BASFM(NTPLT)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.0, VRT)
        WRITE (LINE, '(''DRVAL ='', F6.3)', IOSTAT = IOST) DRVAL(NTPLT)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 13, 0.35, 1, 1, 1.0, VRT)
C * DISPLAY DIRECT CELL
        VRT = VERT
        WRITE (LINE, '(''SpGr '', A)', IOSTAT = IOST) SPGRNM(1)(1:7)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
        WRITE (LINE, '(''a    '', F7.2)', IOSTAT = IOST) PAR(101)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
        WRITE (LINE, '(''b    '', F7.2)', IOSTAT = IOST) PAR(102)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
        WRITE (LINE, '(''c    '', F7.2)', IOSTAT = IOST) PAR(103)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
        WRITE (LINE, '(''alpha'', F7.2)', IOSTAT = IOST) PAR(104)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
        WRITE (LINE, '(''beta '', F7.2)', IOSTAT = IOST) PAR(105)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 12, 0.35, 1, 1, HORS - 4.0, VRT)
        WRITE (LINE, '(''gamma'', F7.2)', IOSTAT = IOST) PAR(106)
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 14, 0.35, 1, 1, HORS - 4.0, VRT)
        VRT = 2.0
        CALL PLA439 (0.0, 'Main Lattice', 12, 0.35, 1, 1,
     1    HORS - 4.0, VRT)
        VRT = VRT - 0.5
        CALL PLA439 (0.0, 'Twin Lattice', 12, 0.35, 2, 1,
     1    HORS - 4.0, VRT)
        VRT = VRT - 0.5
        CALL PLA439 (0.0, 'Iobs >> Ical', 12, 0.35, 5, 1,
     1    HORS - 4.0, VRT)
C * DRAW REFLECTION SPHERE
        CALL GGIP (HH, VH, 0.0, -3)
        CALL PLA289 (0.0, 0.0, RD, 36)
        SCF   = RD / (2 * STL)
        BAS2  = BASFM(NTPLT)
        BAS1  = 1.0 - BAS2
        SCPR0 = IPR(576) / XTAU
C * LOOP OVER REFLECTIONS
        DO N = NADR, NV, 10
C * CHECK WHETHER REFLECTION INDEX MATCHES LEVEL # (SCALAR PRODUCT)
          SCPR = GEN009 (TAU, VOID(N + 5))
          IF (ABS (SCPR0 - SCPR) < 0.01) THEN
            IPEN = NINT (VOID(N + 1))
            I    = NINT (VOID(N + 2))
            J    = NINT (VOID(N + 3))
            K    = NINT (VOID(N + 4))
            IPLT = NINT (VOID(N + 9))
            DO L = 1, 3
              T(L) = VOID(N + L + 4) * SCF
            END DO
            IF (IPEN /= 2) THEN
              NADD = 0
            ELSE
              NADD = 4
            END IF
C * ZONE PERPENDICULAR TO A, B OR C
            IF (IPR(394) == 1) THEN
              IF (I == IPR(576) .AND. J == 0 .AND. K == 0)
     1          IAS(1 + NADD) = N
              IF (I == IPR(576) .AND. J == 1 .AND. K == 0)
     1          IAS(2 + NADD) = N
              IF (I == IPR(576) .AND. J == 1 .AND. K == 1)
     1          IAS(3 + NADD) = N
              IF (I == IPR(576) .AND. J == 0 .AND. K == 1)
     1          IAS(4 + NADD) = N
            ELSE IF (IPR(394) == 2) THEN
              IF (I == 0 .AND. J == IPR(576) .AND. K == 0)
     1          IAS(1 + NADD) = N
              IF (I == 1 .AND. J == IPR(576) .AND. K == 0)
     1          IAS(2 + NADD) = N
              IF (I == 1 .AND. J == IPR(576) .AND. K == 1)
     1          IAS(3 + NADD) = N
              IF (I == 0 .AND. J == IPR(576) .AND. K == 1)
     1          IAS(4 + NADD) = N
            ELSE IF (IPR(394) == 3) THEN
              IF (I == 0 .AND. J == 0 .AND. K == IPR(576))
     1          IAS(1 + NADD) = N
              IF (I == 1 .AND. J == 0 .AND. K == IPR(576))
     1          IAS(2 + NADD) = N
              IF (I == 1 .AND. J == 1 .AND. K == IPR(576))
     1          IAS(3 + NADD) = N
              IF (I == 0 .AND. J == 1 .AND. K == IPR(576))
     1          IAS(4 + NADD) = N
            END IF
            CALL GEN002 (1, ROT, T, XYZ, XLNG)
            IF (IPLT == 0) THEN
              RADIUS = RADM * VOID(N + 10) / FCMX
C * MAIN RECIPROCAL LATTICE
              IF (IPEN /= 2) THEN
                RADIUS = MAX (RADIUS, 0.02)
                NSTEP  = 12
C * OVERLAPPING RECIPROCAL LATTICE
              ELSE
                RADIUS = MAX (RADIUS * BAS2 / BAS1, 0.02)
                NSTEP  = 4
              END IF
C * DRAW LATTICE POINT (CIRCLE)
              CALL GGIP (0.0, FLOAT (IPEN), 0.0, 0)
              CALL PLA289 (XYZ(1), XYZ(2), RADIUS, NSTEP)
              IF (IPEN == 5) THEN
                CALL GGIP (0.0, FLOAT (IPEN), 0.0, 0)
                CALL PLA289 (XYZ(1), XYZ(2), RADIUS * 1.2, NSTEP)
              END IF
            END IF
          END IF
        END DO
        DO J = 1, 8
          DO I = 1, 3
            IASJ = IAS(J)
            IF (IASJ == 0) IASJ = IAS(2)
            T(I) = VOID(IASJ + I + 4) * SCF
          END DO
          CALL GEN002 (1, ROT, T, AS(1, J), XLNG)
        END DO
C * DRAW RECIPROCAL UNITCELL
        DO I = 1, 2
          NADD = (2 - I) * 4
          CALL GGIP (0.0, FLOAT (3 - I), 0.0, 0)
          CALL GGIP (AS(1, 1 + NADD), AS(2, 1 + NADD), 0.0, 3)
          CALL GGIP (AS(1, 2 + NADD), AS(2, 2 + NADD), 0.0, 2)
          CALL GGIP (AS(1, 3 + NADD), AS(2, 3 + NADD), 0.0, 2)
          CALL GGIP (AS(1, 4 + NADD), AS(2, 4 + NADD), 0.0, 2)
          CALL GGIP (AS(1, 1 + NADD), AS(2, 1 + NADD), 0.0, 2)
        END DO
        CALL PLA439 (0.0, 'O', 1, 0.25, 1, 2, AS(1, 1) -0.3,
     1    AS(2, 1) - 0.3)
        IF (IPR(394) == 1) THEN
          CALL PLA439 (0.0, 'K', 1, 0.25, 1, 2, AS(1, 2),
     1       AS(2, 2) + 0.1)
          CALL PLA439 (0.0, 'L', 1, 0.25, 1, 2, AS(1, 4) + 0.1,
     1       AS(2, 4))
        ELSE IF (IPR(394) == 2) THEN
          CALL PLA439 (0.0, 'H', 1, 0.25, 1, 2, AS(1, 2),
     1      AS(2, 2) + 0.1)
          CALL PLA439 (0.0, 'L', 1, 0.25, 1, 2, AS(1, 4) + 0.1,
     1      AS(2, 4))
        ELSE IF (IPR(394) == 3) THEN
          CALL PLA439 (0.0, 'H', 1, 0.25, 1, 2, AS(1, 2),
     1      AS(2, 2) + 0.1)
          CALL PLA439 (0.0, 'K', 1, 0.25, 1, 2, AS(1, 4) + 0.1,
     1      AS(2, 4))
        END IF
C * GET NEW INSTRUCTION
        CALL PLA012 (0, 1)
        SELECT CASE (IGGT(1:4))
          CASE ('!   ')
            GO TO 10
C * TWIN
          CASE ('TWIN')
C * NEXT
          CASE ('NEXT')
            IPR(576) = MAX (-IMX(IPR(394)), MIN (IMX(IPR(394)),
     1                 IPR(576) + IPR(389)))
            GO TO 20
C * ZONE
          CASE ('ZONE')
            GO TO 10
C * RESOLUTION
          CASE ('RESO')
C * LIST (IPR/PAR/IGBL/RGBL)
          CASE ('LIST')
            CALL PLA206 (-1, IFL(2)(1:3))
C * SET (IPR/PAR/IGBL/RGBL)
          CASE ('SET ')
            CALL PLA206 (1, IFL(2)(1:3))
          CASE DEFAULT
C * RESET DspTwinMat#
            IPR(543) = 0
            EXIT
        END SELECT
      END DO
      RETURN
99999 FORMAT (3F7.3)
99998 FORMAT ('(', I3, 2I5, ' )')
99997 FORMAT (I3)
99996 FORMAT ('[', I3, 2I5, ' ]')
      END SUBROUTINE PLA418
      MODULE bijvoet
      SAVE
      INTEGER :: NFR
      INTEGER :: NFH
      INTEGER :: NSTP
      INTEGER :: NSPT
      INTEGER :: NSPP
      INTEGER :: NSPM
      INTEGER :: NPLS
      INTEGER :: NMIN
      INTEGER :: IPR615
      INTEGER :: IPR616
      REAL :: RCO
      REAL :: RCT
      REAL :: RCN
      REAL :: DDM
      REAL :: DDP
      REAL :: SUMX
      REAL :: SUMW
      REAL :: PAR435
      REAL :: PAR436
      REAL :: FCKSLM
      REAL :: FODIFMAX
      REAL :: BIJVOETMAX
      DOUBLE PRECISION :: XG
      DOUBLE PRECISION :: XG0
      DOUBLE PRECISION :: XG1
      DOUBLE PRECISION :: XG2
      DOUBLE PRECISION :: DDIF
      DOUBLE PRECISION :: XPLLL
      DOUBLE PRECISION :: XMNLL
      DOUBLE PRECISION :: XPLL2
      DOUBLE PRECISION :: XTWLL
      DOUBLE PRECISION :: XSMLL
      DOUBLE PRECISION :: DPDATM
      DOUBLE PRECISION :: DPVALUE
      END MODULE bijvoet
 
      SUBROUTINE PLA421
C * Analysis of Bijvoet (Friedel) Pair Differences (1)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE reflex
      USE bijvoet
      USE analysis
      USE sgxyz
      IMPLICIT NONE
      INTEGER, ALLOCATABLE, DIMENSION(:,:) :: IBPR
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: LU
      INTEGER :: NS
      INTEGER :: NF
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IH1
      INTEGER :: IH2
      INTEGER :: IK1
      INTEGER :: IK2
      INTEGER :: IL1
      INTEGER :: IL2
      INTEGER :: IMM
      INTEGER :: MPK
      INTEGER :: MPL
      INTEGER :: NFP
      INTEGER :: NSP1
      INTEGER :: MHKL
      INTEGER :: MHKLH
      INTEGER :: IADR1
      INTEGER :: IBPRM
      INTEGER :: IHKLP
      INTEGER :: ICRIT1
      INTEGER :: NROUTL
      INTEGER :: ISTATUS
      INTEGER :: NOUTLIST
      REAL :: YK
      REAL :: WP
      REAL :: TH
      REAL :: XNU
      REAL :: SIG1
      REAL :: SIG2
      REAL :: STEP
      REAL :: SIGM
      REAL :: THMX
      REAL :: XMXP
      REAL :: BDIF
      REAL :: BSUM
      REAL :: CHIN
      REAL :: CHIT
      REAL :: FCK1
      REAL :: FCK2
      REAL :: FCKD
      REAL :: FCKP
      REAL :: FCKS
      REAL :: FOK1
      REAL :: FOK2
      REAL :: FOKD
      REAL :: FOKP
      REAL :: FOKS
      REAL :: PBOT
      REAL :: PTOP
      REAL :: RASD
      REAL :: RASN
      REAL :: YUNK
      REAL :: YMXP
      REAL :: XMAX
      REAL :: YMAX
      REAL :: RDFD
      REAL :: RDFN
      REAL :: SIG1K
      REAL :: SIG2K
      REAL :: PSUMW
      REAL :: DIFFS
      REAL :: PSUMWX
      REAL :: PSUMWY
      REAL :: PSUMWXK
      REAL :: PSUMWXY
      REAL :: PARSONSMAX
      DOUBLE PRECISION, ALLOCATABLE, DIMENSION(:) :: DPDAT
C * CHECK FOR FCF VALID MODE
      IF (IPR(734) == 1) RETURN
C * CHECK FOR UNIQUE SET OF REFLECTIONS (INCLUDING THETA-MAX TOLERANCE)
C * CHECK FOR TWINNING
      IF (IPR(619) == 0) THEN
        IF (NREF > IPR(559) + IPR(560) + 10) THEN
C * _996 - ALERT
          CALL PLA236 (996, 0, -999.0, 1.0, ' ', ' ')
          WRITE (LU6, 99998)
          RETURN
        END IF
      END IF
      ISTATUS = 0
      IBPRM   = (NREF + 1)
      ALLOCATE (IBPR(3, IBPRM), DPDAT(401), STAT = ISTATUS)
C * MODE     = -1 (Standard Listing Mode on Terminal)
C * IPR(594) = 0 - FCALC FROM FCF
C *          = 1 - FCALC FROM CIF
C * NO BIJVOET ANALYSIS FOR NEUTRON DATA
      IF (IPR(493) > 6) THEN
        WRITE (LU6, 99991, IOSTAT = IOST)
C * NO BIJVOET PAIR ANALYSIS FOR CENTROSYMMETRIC STRUCTURE
      ELSE IF (IPR(275) == 2) THEN
        IF (IGBL(36) == 1 .AND. IPR(594) == 1)
     1    WRITE (LU6, 99999, IOSTAT = IOST)
C * CHECK MEMORY ALLOCATE STATUS
      ELSE IF (ISTATUS /= 0) THEN
        WRITE (LU6, 99990)
C * BIJVOET PAIR ANALYSIS
      ELSE
C * DEFAULT = s.u.-bar
        IPR(634) = 1
C * DEFAULT = HKL-Display
        IPR(636) = 1
C * IPR(613) - (0/1) Gaussian/Student-t
C * IPR(593) - (0/1) PP Slope Correction
C * IPR(617) - (0/n) Recycle Student-t
C * IPR(594) - (0/1) FCF/CIF BASED Fcalc data
C * PAR(488) - Nu-Value
 
C * CHECK MODE (=1)
        IF (IGBL(36) == 1) THEN
          LU = LU13
        ELSE
          LU = LU6
        END IF
        NADR = NREF * NREC
C * REFLECTION DATA FOR NREF REFLECTIONS ARE ALREADY STORED IN LOW VOID
C *  ARRAY MEMORY
C * CREATE ADDRESS ARRAY TO REFLECTION DATA IN HIGH VOID MEMORY
C * DETERMINE PACKING CONSTANTS AND ADDRESSES
        MPH   = 2 * HMAX + 1
        MPK   = 2 * KMAX + 1
        MPL   = 2 * LMAX + 1
        MHK   = MPH * MPK
        MHKL  = MPL * MHK
        MHKLH = (MHKL - 1) / 2
C * CALCULATE ADDRESS OF 0,0,0 REFLECTION
        IADR  = NVDR - MHKLH
        IADR1 = NVDR - MHKL
C * SET DEFAULTS IN HKL-ADDRESS ARRAY
        CALL GEN074 (VOID, IADR1 + 1, NVDR, 0.0)
C * LOAD POINTERS TO DATA IN HKL-ADDRESS ARRAY
C * ONLY THE LATEST REFERENCE IS KEPT
        DO I = 1, NREF
          J = (I - 1) * NREC
          DO K = 1, 3
            SGZ(K) = VOID(J + K)
          END DO
C * LOOP OVER SYMMETRY RELATED REFLECTIONS (EXCLUDING BRAVAIS)
          DO NS = 1, NSYMH
            CALL SGSM (5, LINE, SGZ, NS, LU6, IERR)
            K = NINT (SGZ(9)) * MHK + NINT (SGZ(8)) * MPH
     1        + NINT (SGZ(7))
            VOID(IADR + K) = I
          END DO
        END DO
C * OUTER  LOOP
        DO
C * TOGGLE DETERMINING THE LOCATION OF FC FROM FCF (= 0) OR CIF (=1)
          ICALT = 11 - IPR(594) * 6
C * DETERMINE MAXIMUM CALCULATED BIJVOET AND PARSONS PAIR DIFFERENCE
          IPR(706)   = 0
          BIJVOETMAX = 0.0
          PARSONSMAX = 0.0
          PAR(510)   = 999999.0
          PAR(512)   = 0.0
          DO I = 1, NREF
            J  = (I - 1) * NREC
            IH = NINT (VOID(J + 1))
            IK = NINT (VOID(J + 2))
            IL = NINT (VOID(J + 3))
            K  = IL * MHK + IK * MPH + IH
            N  = NINT (VOID(IADR - K))
C * CHECK FOR 'CENTRO PAIRS'
            IF (N == I) THEN
              IPR(706) = IPR(706) + 1
            ELSE IF (N > I) THEN
              M    = (N - 1) * NREC
              BDIF = ABS (VOID(J + ICALT) - VOID(M + ICALT))
              BSUM = VOID(J + ICALT) + VOID(M + ICALT)
              BIJVOETMAX = MAX (BDIF, BIJVOETMAX)
              IF (BSUM /= 0.0) THEN
                PARSONSMAX = MAX (BDIF / BSUM, PARSONSMAX)
              END IF
            END IF
          END DO
          NOUTLIST = 0
C * UPDATE LOOP ENTRY POINT
   10     IPR(668) = 0
          NFP      = 0
          NF       = 0
          NFR      = 0
          NFH      = 0
          NPLS     = 0
          NMIN     = 0
          STEP     = PAR(515)
          NSP1     = NINT (1.0 / STEP)
          NSTP     = 10 * NSP1 + 1
          NSPT     = 5  * NSP1 + 1
          NSPM     = NSPT - NSP1
          NSPP     = NSPT + NSP1
          DO I = 1, 401
            DPDAT(I) = 0.0D+0
          END DO
          CALL PLA262 (0)
C * OUTLIER HANDLING
          IF (IPR(611) == 0) THEN
            FODIFMAX = 99999.99
          ELSE
            FODIFMAX = IPR(611) * BIJVOETMAX
          END IF
C * TEST FOR STUDENT-T (=1)
          IF (IPR(613) == 1) THEN
C * NU VALUE FOR STUDENT T
            XNU = PAR(487)
          ELSE
            XNU = -1.0
          END IF
          NROUTL  = 0
          RASN    = 0.0
          RASD    = 0.0
          RDFN    = 0.0
          RDFD    = 0.0
          CHIT    = 0.0
          CHIN    = 0.0
          PSUMW   = 0.0
          PSUMWXY = 0.0
          PSUMWX  = 0.0
          PSUMWY  = 0.0
          PSUMWXK = 0.0
          DO I = 1, NREF
            IMM   = (I - 1) * NREC
            IH1   = NINT (VOID(IMM + 1))
            IK1   = NINT (VOID(IMM + 2))
            IL1   = NINT (VOID(IMM + 3))
            FOK1  = VOID(IMM + 4)
            FCK1  = VOID(IMM + ICALT)
            SIG1  = VOID(IMM + 6)
            TH    = VOID(IMM + 7)
            IHKLP = IL1 * MHK + IK1 * MPH + IH1
            N     = NINT (VOID(IADR - IHKLP))
            IF (N > I) THEN
C * COUNT # OF FRIEDEL PAIRS
              IPR(668) = IPR(668) + 1
              IF (IPR(617) > 1) THEN
                IF (IPR(668) == 1) THEN
                  IF (IPR(594) == 1) THEN
                    IF (IGBL(36) == 1) WRITE (LU, 99996, IOSTAT = IOST)
                    WRITE (LU, 99989, IOSTAT = IOST) 'CIF'
                  ELSE
                    WRITE (LU, 99989, IOSTAT = IOST) 'FCF'
                  END IF
                END IF
              END IF
              M     = (N - 1) * NREC
              IH2   = NINT (VOID(M + 1))
              IK2   = NINT (VOID(M + 2))
              IL2   = NINT (VOID(M + 3))
              FOK2  = VOID(M + 4)
              FCK2  = VOID(M + ICALT)
              SIG2  = VOID(M + 6)
              FOKD  = FOK1 - FOK2
              FCKD  = FCK1 - FCK2
              FOKS  = FOK1 + FOK2
              FCKS  = FCK1 + FCK2
              SIG1K = SIG1**2
              SIG2K = SIG2**2
              SIGM  = SQRT (SIG1K + SIG2K)
C * COLLECT DATA FOR RA & RD
              RDFN  = RDFN + ABS (FOKD - FCKD)
              RDFD  = RDFD + ABS (FOKD)
              RASN  = RASN + ABS (FOKS - FCKS)
              RASD  = RASD + ABS (FOKS)
              CHIT  = CHIT + ABS (FOKD) ** 2
              CHIN  = CHIN + ABS (FOKS) / 2.0
C * COLLECT DATA FOR PARSONS Z
              IF (FOKS /= 0.0 .AND. FCKS /= 0.0 .AND.
     1            ABS (FCKD) > 0.001) THEN
C * EXCLUDE OUTLIERS
                IF (SIG1 > 0.0 .AND. SIG2 > 0.0) THEN
                  IF (FOK1 > 3.0 * SIG1 .AND. FOK2 > 3.0 * SIG2)
     1              THEN
                    NFP     = NFP     + 1
                    FOKP    = FOKD / FOKS
                    FCKP    = FCKD / FCKS
                    WP      = 1.0 / ((2.0 * FOK2 * SIG1 / FOKS**2)**2 +
     1                               (2.0 * FOK1 * SIG2 / FOKS**2)**2)
                    PSUMW   = PSUMW   + WP
                    PSUMWX  = PSUMWX  + WP * FCKP
                    PSUMWY  = PSUMWY  + WP * FOKP
                    PSUMWXY = PSUMWXY + WP * FOKP * FCKP
                    PSUMWXK = PSUMWXK + WP * FCKP**2
                  END IF
                END IF
              END IF
              IF (ABS (FOKD) > FODIFMAX .OR. ABS (FCKD) < 0.001)
     1          THEN
                IF (NOUTLIST == 0) THEN
                  NROUTL = NROUTL + 1
                  IF (IPR(617) > 1) THEN
                    IF (NROUTL == 1) THEN
                      WRITE (LU, 99992, IOSTAT = IOST) FODIFMAX
                        IF (IGBL(36) == 0) THEN
                        WRITE (LU7, 99992, IOSTAT = IOST) FODIFMAX
                        CALL PLA262 (5)
                      END IF
                    END IF
                    IF (NROUTL < 51) THEN
                      IF (IPR(746) < 8) THEN
                        WRITE (LU, 99994, IOSTAT = IOST) NROUTL, IH1,
     1                    IK1, IL1, FOK1, IH2, IK2, IL2, FOK2, FOKD,
     2                    FCKD, SIGM
                      ELSE
                        WRITE (LU, 99993, IOSTAT = IOST) NROUTL, IH1,
     1                    IK1, IL1, INT (FOK1), IH2, IK2, IL2,
     2                    INT (FOK2), INT (FOKD), INT (FCKD), INT (SIGM)
                      END IF
                      IF (IGBL(36) == 0) THEN
                        IF (IPR(746) < 8) THEN
                          WRITE (LU7, 99994, IOSTAT = IOST) NROUTL, IH1,
     1                    IK1, IL1, FOK1, IH2, IK2, IL2, FOK2, FOKD,
     2                    FCKD, SIGM
                        ELSE
                          WRITE (LU7, 99993, IOSTAT = IOST) NROUTL, IH1,
     1                      IK1, IL1, INT (FOK1), IH2, IK2, IL2,
     2                      INT (FOK2), INT (FOKD), INT (FCKD), SIGM
                        END IF
                        CALL PLA262 (1)
                      END IF
                    ELSE IF (NROUTL == 51) THEN
                      WRITE (LU, 99995, IOSTAT = IOST)
                      IF (IGBL(36) == 0) THEN
                        WRITE (LU7, 99995, IOSTAT = IOST)
                        CALL PLA262 (3)
                      END IF
                    END IF
                  END IF
                END IF
                ICRIT1 = 0
              ELSE
                ICRIT1 = 1
C * COLLECT BIJVOET PAIRS FOR SORTING & DISPLAY
                IF (ABS (FCK1 - FCK2) > PAR(452) * SIGM) THEN
                  NF          = NF + 1
                  SIGM        = MAX (SIGM, 0.01)
                  IBPR(1, NF) = 100000000
     1                        - NINT (100.0 * ABS (FCK1 - FCK2) / SIGM)
                  IBPR(2, NF) = I
                  IBPR(3, NF) = N
                END IF
              END IF
C * COLLECT PROBABILITY DISTRIBUTION DATA FOR HOOFT (SU)
              IF (TH >= PAR(509)) THEN
                PAR(510) = MIN (TH, PAR(510))
                PAR(512) = MAX (TH, PAR(512))
                NFH      = NFH + 1
                DO J = 1, NSTP
                  YK = (J - NSPT) * STEP
                  DIFFS = ((YK * FCKD - FOKD) / SIGM)**2
C * CHECK FOR STUDENT-T NU VALUE
                  IF (XNU < 0.0) THEN
C * TEST FOR OUTLIER (= 0)
                    IF (ICRIT1 == 0) THEN
                      DPVALUE = 0.0D+0
                    ELSE
                      DPVALUE = - DBLE (DIFFS / 2.0)
                    END IF
                  ELSE
                    DPVALUE = - DLOG (DBLE (1.0 + DIFFS / XNU))
     1                        * DBLE (((XNU + 1.0) / 2.0))
                  END IF
                  DPDAT(J) = DPDAT(J) + DPVALUE
                END DO
              END IF
            END IF
          END DO
C * SELECTED # OF FRIEDEL PAIRS
          IPR(707) = NF
C * SAVE Parsons z data for CIF or RES Based SF ONLY
          IF (IPR(594) == 1 .OR. IABS (IGBL(8)) == 2) THEN
            IF (NFP > 0) THEN
              PTOP     = PSUMW * PSUMWXY - PSUMWX * PSUMWY
              PBOT     = PSUMW * PSUMWXK - PSUMWX**2
              PAR(503) = (1.0 - (PTOP / PBOT)) / 2.0
              PAR(504) = SQRT (PSUMW / PBOT) * 0.5
              CALL GEN041 (PAR(503), PAR(504), IPR(669), 3, IPR(670),
     1                     IPR(68))
            END IF
            IPR(750) = NFP
          END IF
          IF (IPR(668) > 0 .AND. CHIN > 0.0) THEN
            PAR(491) = 10000.0 * SQRT (CHIT / IPR(668)) /
     1        (CHIN / IPR(668))
          END IF
C * CHECK FOR NON-ZERO NUMBER OF SELECTED PAIRS
          IF (IPR(707) < 3) THEN
            IF (PAR(452) > 0.0) THEN
              PAR(452) = 0.0
              NOUTLIST = 1
              GO TO 10
            END IF
          END IF
          SUMX   = 0.0
          SUMW   = 0.0
          XMAX   = 0.0
          YMAX   = 0.0
          THMX   = 0.0
          XMXP   = 0.0
          XMXP   = 0.0
          YMXP   = 0.0
          YMXP   = 0.0
          RCT    = 0.0
          RCN    = 0.0
          FCKSLM = 0.0
          DDP    = -999999.0
          DDM    =  999999.0
          IF (IPR(707) > 0 .AND. RDFD /= 0.0 .AND. RASD /= 0)
     1      THEN
            PAR(489) = RASN / RASD
            PAR(490) = RDFN / RDFD
C * SET MENU
            IGBL(6) = 29
            CALL PLA426 (IBPR, XMAX, YMAX, THMX, XMXP, YMXP, LU)
            CALL PLA425 (DPDAT, LU)
          ELSE
C * NO BIJVOET PAIRS !
            IF (IPR(594) == 1) THEN
              CALL PLA015 (0, 58)
              WRITE (LU, 99988, IOSTAT = IOST)
C * TEST FOR FLACK PARAMETER VALUE GIVEN
C * ALERT _914
              IF (PAR(433) < 99999.0)
     1          CALL PLA236 (914, 0, 1.0, 1.0, ' ', ' ')
            ELSE
              WRITE (LU, 99997, IOSTAT = IOST)
            END IF
            EXIT
          END IF
 
C * PROBABILITY PLOT
          CALL PLA424
          IF (IPR(617) == 2) THEN
             GO TO 10
          END IF
C * SCATTER PLOT DISPLAY
          IF (IPR(707) > 0 .AND. IGBL(36) == 0) THEN
C * TEST FOR BIJVOET-DIFFERENCE/PARSONS-RATIO
   20       IF (IPR(635) == 0) THEN
              IF (XMAX /= 0.0 .AND. YMAX /= 0.0)
     1         CALL PLA422 (IBPR, XMAX, YMAX, THMX)
            ELSE
              IF (XMXP /= 0.0 .AND. YMXP /= 0.0)
     1          CALL PLA422 (IBPR, XMXP, YMXP, THMX)
            END IF
C * WHAT NEXT ?
C * CHECK FOR '-B' OPTION
   30       IF (IGBL(3) /= 46) THEN
C * WHAT NEXT ?
              CALL PLA012 (0, 1)
              CALL GEN072 (IGGT, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7,
     1                     NP17)
              SELECT CASE (IFL(1)(1:6))
                CASE ('END   ', 'EXIT  ')
                EXIT
C * CHANGE SELECT CRITERIUM
                CASE ('SELECT')
                  GO TO 10
C * CHANGE NU CRITERIUM
                CASE ('NUVAL ', 'NUVALU')
                  IPR(617) = 0
                  IF (KN > 0) PAR(488) = FN(1)
                  GO TO 10
C * CHANGE SIGMA DELTA > SIGMA CRITERIUM
                CASE ('SIGMA ')
                  GO TO 10
C * APPLY SLOPE
                CASE ('SLOPE ')
                  GO TO 10
C * FCF/CIF SWITCH
                CASE ('FROM  ')
                  CYCLE
C * WGHT
                CASE ('WGHT  ')
                  IPR(621) = 0
                  GO TO 10
C * SWITCH
                CASE ('SWITCH')
                  IPR(617) = 1
                  GO TO 10
C * NPP
                CASE ('NPP   ')
                  CALL PLA204
                  IF (IPR(621) == 0) IPR(621) = 1
                  GO TO 30
C * SET
                CASE ('SET   ')
                  IF (IFL(2)(1:3) == 'IPR') THEN
                    IPR(656) = NINT (FN(2))
                    CALL GGIP (0.0, 0.0, 0.0, -1)
                    GO TO 20
                  END IF
C * (SCATTER) PLOT
                CASE DEFAULT
                  IPR(656) = 0
                  GO TO 20
              END SELECT
            END IF
          ELSE
            EXIT
          END IF
        END DO
C * CHECK FOR VALID FLACK PARAMETER VALUE
        IF (PAR(433) < 999999.0 .AND. PAR(435) < 999999.0) THEN
          YUNK = ABS(PAR(433) - PAR(435))
C * REPORT LARGE DIFFERENCE BETWEEN FLACK x AND HOOFT y VALUES
C * ALERT _916
          IF (YUNK > 0.10) THEN
            CALL PLA236 (916, 2, -999.0, YUNK, ' ', ' ')
          END IF
        END IF
        DEALLOCATE (IBPR, DPDAT)
      END IF
      RETURN
99999 FORMAT (/, ':: No Bijvoet Pair Analysis for Centrosymmetric',
     1        ' Structure')
99998 FORMAT (/, ':: No Bijvoet Analysis: # entries in FCF > ',
     1        '# unique reflections', /)
99997 FORMAT (/, ':: No Bijvoet Pairs with Significant Fcalc ',
     1 'Differences in FCF Found', /)
99996 FORMAT ('Section 9')
99995 FORMAT (/, 20X, 'etc.', /)
99994 FORMAT (I3, 2(2X, 3I3, F10.2), 4X,  3F10.2)
99993 FORMAT (I3, 2(2X, 3I3, I11), 4X,  3I10)
99992 FORMAT (/, 'Excluded Outliers with Observed Bijvoet Difference',
     1        ' >', F12.2, ', or FCKD=0.0', /, 79('='), /,
     2        'Nr    H1 K1 L1', 6X, 'FOK1   H2 K2 L2', 6X, 'FOK2',
     3        10X, 'FOKD', 6X, 'FCKD', 6X, 'SIGD',  /, 79('='))
99991 FORMAT (/, 'No BIJVOET/HOOFT Analysis for Neutron data')
99990 FORMAT (/, 'Memory Allocate Problem in PLA421', /)
99989 FORMAT (79('='), /, 'Bijvoet Pair Analysis - F(calc) from ',
     1        A, /, 79('='))
99988 FORMAT (/, ':: No Bijvoet Pairs Found', /)
      END SUBROUTINE PLA421
 
      SUBROUTINE PLA422 (IBPR, XMAX, YMAX, THMX)
C * Bijvoet Pair Analysis - SCATTER PLOT (2)
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE bijvoet
      USE analysis
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IMM
      INTEGER :: JMM
      INTEGER :: JUNK
      INTEGER, DIMENSION(3, *) :: IBPR
      REAL :: X
      REAL :: Y
      REAL :: DX
      REAL :: DY
      REAL :: TH
      REAL :: DX0
      REAL :: DY0
      REAL :: ADD
      REAL :: DSH
      REAL :: SIG
      REAL :: XORG
      REAL :: YORG
      REAL :: SIG1
      REAL :: SIG2
      REAL :: FCK1
      REAL :: FCK2
      REAL :: FCKD
      REAL :: FOK1
      REAL :: FOK2
      REAL :: FOKD
      REAL :: DSH1
      REAL :: XMAX
      REAL :: YMAX
      REAL :: THMX
      REAL :: SCLX
      REAL :: SCLY
      REAL :: XHOR
      REAL :: XHDR
      REAL :: FCKSM
      REAL :: FOKSM
      REAL :: FCKDF
      REAL :: FOKDF
      REAL :: COLOR
      REAL :: YMSIG
      REAL :: YPSIG
      REAL :: FRIEDIF
      CHARACTER(len=10) :: FORMX
      ICALT = 11 - IPR(594) * 6
C * OBSERVED VERSUS CALCULATED DIFFERENCE PLOT
      IF (IPR(656) == 0) THEN
        SCLX = 0.90 * VERT / (2.0 * XMAX)
        SCLY = 0.90 * VERT / (2.0 * YMAX)
        XORG = VERT / 2.0
        YORG = VERT / 2.0
C * OBSERVED AND CALCULATED DIFFERENCE VERSUS THETA PLOT
      ELSE IF (ABS(IPR(656)) == 1) THEN
        SCLX = 0.90 * VERT / THMX
        SCLY = 0.90 * VERT / (2.0 * MAX (XMAX, YMAX))
        XORG = 0.05 * VERT
        YORG = VERT / 2.0
C * OBSERVED AND CALCULATED DIFFERENCE VERSUS FCKSL  PLOT
      ELSE IF (ABS(IPR(656)) == 2) THEN
        SCLX = 0.90 * VERT / FCKSLM
        SCLY = 0.90 * VERT / (2.0 * MAX (XMAX, YMAX))
        XORG = 0.05 * VERT
        YORG = VERT / 2.0
      END IF
C * CHECK FOR BIJVOET ANALYSIS
      IF (IGBL(3) == 46) CALL GGIP (-999.0, 0.0, 0.0, -2)
      CALL GGIP (HORS, VERT, 0.0, 1)
C * PLOT BOX AND DISPLAY PARAMETERS
      CALL PLA110 (VERT, VERT, -1)
      CALL PLA262 (0)
      IF (IPR(656) == 0) THEN
        IF (IPR(635) == 0) THEN
          LINE = 'BIJVOET-PAIR BIJVOET-DIFFERENCE SCATTER PLOT'
        ELSE
          LINE = 'BIJVOET-PAIR PARSONS-DIFFERENCE SCATTER PLOT'
        END IF
      ELSE IF (IPR(656) == 1) THEN
        LINE = 'BIJVOET-PAIR DIFFERENCE VERSUS THETA SCATTER PLOT'
      ELSE IF (IPR(656) == -1) THEN
        LINE = 'BIJVOET-PAIR DIF-DIF/SIG VERSUS THETA SCATTER PLOT'
      ELSE IF (IPR(656) == 2) THEN
        LINE = 'BIJVOET-PAIR DIFFERENCE VERSUS LOG(FC2) SCATTER PLOT'
      ELSE IF (IPR(656) == -2) THEN
        LINE = 'BIJVOET-PAIR DIF-DIF/SIG VERSUS LOG(FC2) SCATTER PLOT'
      END IF
      VRT = VERT - 0.6
      CALL PLA439 (0.0, LINE, 53, 0.35, 5 + IGBL(68), 2, 2.6, VRT)
      IF (IPR(656) /= 0) THEN
        VRT = VRT - 0.5
        LINE = 'RED = Difference Signs Disagree'
        CALL PLA439 (0.0, LINE, 31, 0.30, 1, 2, 1.1, VRT)
        VRT = VRT - 0.5
        LINE = 'OBS = Marked'
        CALL PLA439 (0.0, LINE, 12, 0.30, 1, 2, 1.1, VRT)
      END IF
      IF (IPR(656) == 0) THEN
        IF (IPR(594) == 0) THEN
          LINE = 'Fcalc from Fcalc Data in FCF'
        ELSE
          LINE = 'Fcalc from Model Data in '//DTYPE(IABS(IGBL(8)))
        END IF
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LINE, 29, 0.25, 5 + IGBL(68), 2, 1.0, VRT)
C * SumFormula
        CALL PLA283 (2, FLOAT (IPR(260)), N, CFORM)
        JUNK = NP52 - N + 1
        VRT = VRT - 0.5
        CALL PLA439 (0.0, CFORM(N:NP52), JUNK, 0.25,
     1          5 + IGBL(68), 2, 1.0, VRT)
C * Parsons-Z
        CALL GEN146 (FORMX, PAR(503), IPR(669), IPR(670))
        WRITE (LINE, 99993, IOSTAT = IOST) FORMX, IPR(750)
C * DUMMY
        IF (IOST == -999) RETURN
        VRT = VRT - 0.5
        CALL PLA439 (0.0, LINE, 37, 0.25, 5 + IGBL(68), 2, 1.0, VRT)
C * Res.Scat.
        WRITE (LINE, 99996, IOSTAT = IOST) NINT (PAR(425) * 10000.0)
        VRT = VRT - 0.5
        CALL PLA439 (0.0, LINE, 30, 0.25, 5 + IGBL(68), 2, 1.0, VRT)
C * Friedif
        IF (PAR(434) < 999999.0) THEN
          FRIEDIF = PAR(474) * 10000.0
          IF (FRIEDIF > 10.0) THEN
            WRITE (LINE, 99997, IOSTAT = IOST)
     1        NINT (FRIEDIF), NINT (PAR(491))
          ELSE
            WRITE (LINE, 99992, IOSTAT = IOST)
     1        FRIEDIF, NINT (PAR(491))
          END IF
          VRT = VRT - 0.5
          CALL PLA439 (0.0, LINE, 34, 0.25, 5 + IGBL(68), 2, 1.0, VRT)
          WRITE (LINE, 99994, IOSTAT = IOST)
     1      PAR(474) * PAR(434) * 10000.0
          VRT = VRT - 0.5
          CALL PLA439 (0.0, LINE, 26, 0.25, 5 + IGBL(68), 2, 1.0, VRT)
        ENDIF
        WRITE (LINE, 99995, IOSTAT = IOST) PAR(489), PAR(490)
        VRT = VRT - 0.5
        CALL PLA439 (0.0, LINE, 22, 0.25, 5 + IGBL(68), 2, 1.0, VRT)
C * Slope applied Notice
        IF (IPR(593) /= 0) THEN
          VRT = VRT - 0.5
          IF (IPR(613) == 0) THEN
            CALL PLA439 (0.0, 'n-Probability Plot Slope Applied', 32,
     1                         0.25, 5 + IGBL(68), 2, 1.0, VRT)
          ELSE
            CALL PLA439 (0.0, 't-Probability Plot Slope Applied', 32,
     1                         0.25, 5 + IGBL(68), 2, 1.0, VRT)
          END IF
        END IF
        IF (IPR(635) == 0) THEN
          LINE = '      Diff(Fobs**2)'
        ELSE
          LINE = 'Dif(Iobs)/Sum(Iobs)'
        END IF
        CALL PLA439 (90.0, LINE, 19, 0.30, 1, 2, 0.6, VERT - 5.0)
        IF (IPR(635) == 0) THEN
          LINE = '     Diff(Fcalc**2)'
        ELSE
          LINE = 'Dif(Ical)/Sum(Ical)'
        END IF
        CALL PLA439 (0.0, LINE, 19, 0.30, 1, 2, VERT - 5.0, 0.2)
      END IF
C * REPORT PARAMETER VALUES
      CALL PLA423
C * MOVE ORIGIN
      CALL GGIP (XORG, YORG, 0.0, -3)
      CALL GGIP (0.0, FLOAT (5 + IGBL(68)), 0.0, 0)
      IF (IPR(656) == 0) THEN
        DX = 0.45 * VERT
        CALL GGIP (0.0, - DX, 0.0, 3)
        CALL GGIP (0.0, + DX, 0.0, 2)
        CALL GGIP (- DX, 0.0, 0.0, 3)
        CALL GGIP (DX,   0.0, 0.0, 2)
        CALL GGIP (0.0,  0.0, 0.0, 3)
        DY = XMAX * RCO / YMAX
        IF (DY < 1.0) THEN
          DX0 = - DX
          DY0 = - DX * DY
        ELSE
          DX0 = - DX / DY
          DY0 = - DX
        END IF
        CALL GGIP (0.0, 3.0, 0.0, 0)
        CALL GGIP (DX0, DY0, 0.0, 2)
        CALL GGIP (0.0,  0.0, 0.0, 3)
        WRITE (LINE, 99999, IOSTAT = IOST) XMAX
        CALL PLA439 (90.0, LINE, 9, 0.3, 1, 2, DX + 0.4, -1.2)
        WRITE (LINE, 99999, IOSTAT = IOST) YMAX
        CALL PLA439 (0.0, LINE, 9, 0.3, 1, 2, -2.8, DX - 0.3)
      ELSE IF (ABS (IPR(656)) == 1 .OR. ABS (IPR(656)) == 2) THEN
        DX = 0.90 * VERT
        DY = 0.45 * VERT
        CALL GGIP (0.0, 0.0, 0.0, 3)
        CALL GGIP (DX , 0.0, 0.0, 2)
        CALL GGIP (0.0, DY , 0.0, 3)
        CALL GGIP (0.0, -DY, 0.0, 2)
        CALL GGIP (0.0, 0.0, 0.0, 3)
      END IF
      DSH  = 0.05
      DSH1 = 0.075
C * PLOT SELECTED SET OF BIJVOET PAIR DATA
      DO N = 1, IPR(707)
        I     = IBPR(2, N)
        J     = IBPR(3, N)
        IMM   = (I - 1) * NREC
        JMM   = (J - 1) * NREC
        FOK1  = VOID(IMM + 4)
        FCK1  = VOID(IMM + ICALT)
        SIG1  = VOID(IMM + 6)
        TH    = VOID(IMM + 7)
        FOK2  = VOID(JMM + 4)
        FCK2  = VOID(JMM + ICALT)
        SIG2  = VOID(JMM + 6)
        FOKDF = FOK1 - FOK2
        FCKDF = FCK1 - FCK2
        FOKSM = FOK1 + FOK2
        FCKSM = FCK1 + FCK2
C * TEST FOR BIJVOET OR PARSONS DIFFERENCES
        IF (IPR(656) == 0) THEN
          IF (IPR(635) == 0) THEN
            FOKD = SCLY * FOKDF
            FCKD = SCLX * FCKDF
            SIG  = SCLY * SQRT (SIG1**2 + SIG2**2)
          ELSE
            IF (FOK1 + FOK2 /= 0.0) THEN
              FOKD = SCLY * FOKDF / FOKSM
              FCKD = SCLX * FCKDF / FCKSM
              SIG  = SCLY * SQRT ((2.0 * FOK2 * SIG1 / FOKSM**2)**2 +
     1                            (2.0 * FOK1 * SIG2 / FOKSM**2)**2)
            END IF
          END IF
        ELSE IF (ABS (IPR(656)) == 1) THEN
          FOKD = SCLY * FOKDF
          FCKD = SCLY * FCKDF
          XHOR = SCLX * TH
          SIG  = SCLY * SQRT (SIG1**2 + SIG2**2)
        ELSE IF (ABS (IPR(656)) == 2) THEN
          FOKD = SCLY * FOKDF
          FCKD = SCLY * FCKDF
          XHOR = SCLX * LOG (FCKSM)
          SIG  = SCLY * SQRT (SIG1**2 + SIG2**2)
        END IF
        IF (IPR(656) == 0) THEN
          IF (ABS (FOKD) <= 0.45 * VERT) THEN
            DO M = 1, 3, 2
              IF (FOKD * FCKD >= 0.0) THEN
                COLOR = 1.0
              ELSE
                COLOR = 2.0
              END IF
              X = (M - 2) * FCKD
              Y = (M - 2) * FOKD
C * PLOT MARKER
              CALL PLA406 (X, Y, DSH, COLOR)
              IF (X > 0.0) THEN
C * ADD SU BAR TO DATUM POINT
                IF (IPR(634) == 1) THEN
                  YPSIG = MIN ( 0.45 * VERT, Y + SIG)
                  YMSIG = MAX (-0.45 * VERT, Y - SIG)
                  CALL GGIP (X, YPSIG, 0.0, 3)
                  CALL GGIP (X, YMSIG, 0.0, 2)
                END IF
                IF (IPR(636) == 1) THEN
                  IF (X > DX / 2.0 .OR. Y < -DX / 2.0) THEN
                    IH = NINT (VOID(IMM + 1))
                    IK = NINT (VOID(IMM + 2))
                    IL = NINT (VOID(IMM + 3))
                    WRITE (LINE, 99998, IOSTAT = IOST) IH, IK, IL
                    IF (MOD (N, 2) == 1) THEN
                      ADD =  0.1
                    ELSE
                      ADD = -1.1
                    END IF
                    CALL PLA439 (-45.0, LINE, 9, 0.16, 5 + IGBL(68),
     1                                 1, X + ADD , Y - ADD)
                  END IF
                END IF
              END IF
            END DO
          END IF
        ELSE IF (ABS (IPR(656)) == 1 .OR. ABS (IPR(656)) == 2) THEN
          IF (FCKD * FOKD > 0.0) THEN
            COLOR = 3.0
          ELSE
            COLOR = 2.0
          END IF
          IF (IPR(656) < 0) THEN
            Y = FCKD + (FOKD - FCKD) / SIG
          ELSE
            Y = FOKD
          END IF
          CALL GGIP (0.0, COLOR, 0.0, 0)
          CALL GGIP (XHOR,        FCKD,     0.0, 3)
          CALL GGIP (XHOR,        Y,        0.0, 2)
C * PLOT MARKER
          CALL PLA406 (XHDR, Y, DSH1, -1.0)
        END IF
      END DO
      RETURN
99999 FORMAT (F9.2)
99998 FORMAT (3I3)
99997 FORMAT ('Friedif   =', I6, ' stat [', I5, ' obs]')
99996 FORMAT ('Res.Scat. =', I6, ' * 0.0001')
99995 FORMAT ('RA =', F6.3, ', RD =', F6.3)
99994 FORMAT ('Friedif * Flack(su) =', F5.1)
99993 FORMAT ('Parsons z =', A, ',', I5, ' Pairs')
99992 FORMAT ('Friedif   =', F6.1, ' stat [', I5, ' obs]')
      END SUBROUTINE PLA422
 
      SUBROUTINE PLA423
C * Bijvoet Pair Analysis (3) - PARAMETER DISPLAY
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE bijvoet
      USE npplot
      IMPLICIT NONE
      INTEGER :: NB
      INTEGER :: NE
      REAL :: YUNK
      CHARACTER(len=10) :: FORMX
      VRT = VERT - 0.5
C * SPGR
      NB = 1
      NE = 7
      CALL GEN039 (1, SPGRNM(1)(1:7), 1, 7, NB, NE)
      LINE = 'Space Group'
      WRITE (LINE(22-NE:), 99984, IOSTAT = IOST) SPGRNM(1)(1:7)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * WAVELENGTH
      WRITE (LINE, 99993, IOSTAT = IOST) PAR(17)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * FLACK X
      IF (PAR(433) < 999999.0) THEN
        CALL GEN146 (FORMX, PAR(433), IPR(279), IPR(280))
        IF (IPR(705) == 2) THEN
          WRITE (LINE, 99998, IOSTAT = IOST) FORMX
        ELSE
          WRITE (LINE, 99992, IOSTAT = IOST) FORMX
        ENDIF
        WRITE (LU6,  99968, IOSTAT = IOST) LINE
        WRITE (LU7,  99968, IOSTAT = IOST) LINE
        CALL PLA439 (0.0, LINE, 22, 0.335, 1, 2, VERT + 0.2, VRT)
      END IF
      VRT = VRT - 0.6
C * PARSONS z
      IF (PAR(434) < 999999.0) THEN
        CALL GEN146 (FORMX, PAR(503), IPR(669), IPR(670))
        WRITE (LINE, 99980, IOSTAT = IOST) FORMX
        WRITE (LU6,  99968, IOSTAT = IOST) LINE
        WRITE (LU7,  99968, IOSTAT = IOST) LINE
        CALL PLA439 (0.0, LINE, 22, 0.335, 1, 2, VERT + 0.2, VRT)
      END IF
      VRT = VRT - 0.8
C * BIJVOET PAIRS
      WRITE (LU6,  99967, IOSTAT = IOST)
      WRITE (LU7,  99967, IOSTAT = IOST)
      WRITE (LINE, 99990, IOSTAT = IOST) IPR(668)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      CALL PLA439 (0.0, LINE, 14, 0.35, 5 + IGBL(68), 2,
     1                  VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * BIJVOET COVERAGE
      WRITE (LINE, 99959, IOSTAT = IOST) NINT (PAR(464))
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * DIFFCALCMAX
      WRITE (LINE, 99994, IOSTAT = IOST) BIJVOETMAX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * OUTLIER CRIT
      WRITE (LINE, 99983, IOSTAT = IOST) FODIFMAX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.8
C * SCATTER PLOT
      WRITE (LINE, 99969, IOSTAT = IOST)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 12, 0.35, 5 + IGBL(68), 2,
     1                  VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * SCATTER PLOT SIGMA CRIT
      WRITE (LINE, 99987, IOSTAT = IOST) PAR(452)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * SCATTER PLOT SELECTED NUMBER OF PAIRS
      WRITE (LINE, 99989, IOSTAT = IOST) IPR(707)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * SCATTER NUMBER PLUS
      WRITE (LINE, 99986, IOSTAT = IOST) NPLS
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * SCATTER NUMBER MINUS
      WRITE (LINE, 99985, IOSTAT = IOST) NMIN
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * SCATTER PLOT SLOPE
      WRITE (LINE, 99970, IOSTAT = IOST) RCO
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.8
C * PROB PLOT GAUSSIAN/STUDENT-T
      WRITE (LU6,  99967, IOSTAT = IOST)
      WRITE (LU7,  99967, IOSTAT = IOST)
      IF (IPR(613) == 0) THEN
        WRITE (LINE, 99966, IOSTAT = IOST)
      ELSE
        WRITE (LINE, 99999, IOSTAT = IOST)
      END IF
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 5 + IGBL(68), 2,
     1           VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * PROB PLOT SAMPLE SIZE
      WRITE (LINE, 99981, IOSTAT = IOST) NFR
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * PROB PLOT CORRELATION
      WRITE (LINE, 99965, IOSTAT = IOST) YCC
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      IF (YCC < 0.9) THEN
        WRITE (LINE, 99995, IOSTAT = IOST) YCC
        CALL PLA439 (0.0, LINE, 21, 0.35, 2, 2, VERT + 0.2, VRT)
      END IF
      VRT = VRT - 0.6
C * PROB PLOT INTERCEPT
      WRITE (LINE, 99964, IOSTAT = IOST) YINT
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * PROB PLOT SLOPE
      WRITE (LINE, 99963, IOSTAT = IOST) YSLOPE
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.8
C * BAYESIAN STATISTICS
      WRITE (LU6,  99967, IOSTAT = IOST)
      WRITE (LU7,  99967, IOSTAT = IOST)
      WRITE (LINE, 99974, IOSTAT = IOST)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 5 + IGBL(68), 2,
     1                  VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * GAUSSIAN /STUDENT-T NU
      IF (IPR(613) > 0) THEN
        WRITE (LINE, 99982, IOSTAT = IOST) NINT (PAR(487))
      ELSE
        WRITE (LINE, 99988, IOSTAT = IOST)
      END IF
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
      WRITE (LINE, 99973, IOSTAT = IOST) NFH
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * THETA-MIN BIJVOET PAIRS
      WRITE (LINE, 99956, IOSTAT = IOST) MAX (PAR(509), PAR(510))
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * THETA-MAX BIJVOET PAIRS
      WRITE (LINE, 99955, IOSTAT = IOST) MAX (PAR(509), PAR(512))
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * P2(True)
      IF (XPLL2 > 0.001D+0) THEN
        WRITE (FORMX, 99961, IOSTAT = IOST) XPLL2
      ELSE IF (XPLL2 < 0.0D+0) THEN
        WRITE (FORMX, 99957, IOSTAT = IOST)
        CALL PLA439 (0.0, 'Not Enantiopure', 15, 0.35, 1, 2,
     1                   VERT - 4.6, VRT)
      ELSE
        WRITE (FORMX, 99962, IOSTAT = IOST) XPLL2
      END IF
      WRITE (LINE, 99958, IOSTAT = IOST) FORMX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * P3(True)
      IF (XPLLL > 0.001D+0) THEN
        WRITE (FORMX, 99961, IOSTAT = IOST) XPLLL
      ELSE IF (XPLLL < 0.0D+0) THEN
        WRITE (FORMX, 99957, IOSTAT = IOST)
      ELSE
        WRITE (FORMX, 99962, IOSTAT = IOST) XPLLL
      END IF
      WRITE (LINE, 99979, IOSTAT = IOST) FORMX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
C * P3(Twin)
      VRT = VRT - 0.6
      IF (XTWLL > 0.001D+0) THEN
        WRITE (FORMX, 99961, IOSTAT = IOST) XTWLL
      ELSE IF (XTWLL < 0.0D+0) THEN
        WRITE (FORMX, 99957, IOSTAT = IOST)
      ELSE
        WRITE (FORMX, 99962, IOSTAT = IOST) XTWLL
      END IF
      WRITE (LINE, 99977, IOSTAT = IOST) FORMX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
C * P3(False)
      VRT = VRT - 0.6
      IF (XMNLL > 0.001D+0) THEN
        WRITE (FORMX, 99961, IOSTAT = IOST) XMNLL
      ELSE IF (XMNLL < 0.0D+0 .OR. XPLLL < 0.0D+0) THEN
        WRITE (FORMX, 99957, IOSTAT = IOST)
      ELSE
        WRITE (FORMX, 99962, IOSTAT = IOST) XMNLL
      END IF
      WRITE (LINE, 99978, IOSTAT = IOST) FORMX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * G
      WRITE (LINE, 99972, IOSTAT = IOST) XG
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * G (su)
      YUNK = SNGL (DSQRT (XG2 / XG0))
      IF (YUNK > 0.0001) THEN
        WRITE (FORMX, 99960, IOSTAT = IOST) YUNK
      ELSE
        WRITE (FORMX, 99962, IOSTAT = IOST) YUNK
      END IF
      WRITE (LINE, 99971, IOSTAT = IOST) FORMX
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 21, 0.35, 1, 2, VERT + 0.2, VRT)
      VRT = VRT - 0.6
C * Hooft y
      CALL GEN146 (FORMX, PAR435, IPR615, IPR616)
      WRITE (LINE, 99976, IOSTAT = IOST) FORMX(2:10)
      WRITE (LU6,  99968, IOSTAT = IOST) LINE
      WRITE (LU7,  99968, IOSTAT = IOST) LINE
      CALL PLA439 (0.0, LINE, 22, 0.35, 1, 2, VERT + 0.2, VRT)
      IF (PAR(435) . LT. 999999.0) THEN
        IF (ABS (PAR(435) - PAR435) > 2.0 * PAR(436)) THEN
          LINE (1:12) = ' '
          CALL PLA439 (0.0, LINE, 21, 0.35, 2, 2, VERT + 0.2, VRT)
        END IF
      END IF
      VRT = VRT - 0.6
      RETURN
99999 FORMAT ('Student-T Prob. Plot')
99998 FORMAT ('Flack x TWIN', A)
99995 FORMAT ('            ', F9.3)
99994 FORMAT ('DiffCalcMax.', F9.2)
99993 FORMAT ('Wavelength ', F10.5)
99992 FORMAT ('Flack x ....', A)
99990 FORMAT ('Bijvoet Pairs', I8)
99989 FORMAT ('Select Pairs', I9)
99988 FORMAT ('Distribution Gaussian')
