      END SUBROUTINE PLA423
 
      SUBROUTINE PLA424
C * Bijvoet Pair Analysis (4)
C * COLLECT DATA FOR PROBABILITY PLOT
      USE files
      USE parameters
      USE cchar
      USE reflex
      USE bijvoet
      USE analysis
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: IMM
      INTEGER :: LUX
      INTEGER :: IADD
      INTEGER :: IHKLP
      REAL :: FCK1
      REAL :: FCK2
      REAL :: FOK1
      REAL :: FOK2
      REAL :: FOKD
      REAL :: FCKD
      REAL :: SIGM
      REAL :: SIG1K
      REAL :: SIG2K
      ICALT = 11 - IPR(594) * 6
        NFR = 0
C * INCLUDE L.S. WEIGHT PARAMETERS IN SIGMAI
        IF (PAR(493) * IPR(629) > 0.0) THEN
          IADD = 12
        ELSE
          IADD = 6
        END IF
        DO I = 1, NREF
          IMM   = (I - 1) * NREC
          IH    = NINT (VOID(IMM + 1))
          IK    = NINT (VOID(IMM + 2))
          IL    = NINT (VOID(IMM + 3))
          FOK1  = VOID(IMM + 4)
          FCK1  = VOID(IMM + ICALT)
          SIG1K = VOID(IMM + IADD)**2
          IHKLP = IL * MHK + IK * MPH + IH
          N     = NINT (VOID(IADR - IHKLP))
          IF (N > I) THEN
            M     = (N - 1) * NREC
            FOK2  = VOID(M + 4)
            FCK2  = VOID(M + ICALT)
            SIG2K = VOID(M + IADD)**2
            FOKD  = FOK1 - FOK2
            FCKD  = FCK1 - FCK2
            SIGM  = SQRT (MAX (SIG1K + SIG2K, 0.01))
C * DO NOT EXCLUDE OUTLIERS FOR STUDENT-T
            IF (ABS(FOKD) <= FODIFMAX .OR. IPR(613) == 1) THEN
C * COLLECT DATA FOR PP
              NFR = NFR + 1
              VOID(NADR + NFR) = (SNGL (XG) * FCKD - FOKD) / SIGM
            END IF
          END IF
        END DO
        IF (IABS (IGBL(36)) == 1) THEN
          LUX = LU13
        ELSE
          LUX = LU7
        END IF
C * NORMAL OR STUDENT-T PROBABILITY PLOT
        IF (NFR > 0 .AND. IGBL(36) >= 0) THEN
          IF (LUX == LU7) CALL PLA262 (0)
C * TEST NORMAL/STUDENT
          IF (IPR(613) == 0) THEN
            IF (IPR(652) == 1) THEN
C * TEST FOR WRITING .npp / OPENING
              OPEN (UNIT = 62, FILE = NAMEFIL(1:KNMFIL)//'.npp',
     1              STATUS = 'UNKNOWN')
            END IF
            CALL GEN116 (2, VOID(NADR + 1), VOID(NADR + NREF + 1), NFR,
     1                   GRAPH, 0)
          ELSE
C * TEST FOR WRITING .tpp / OPENING
            IF (IPR(652) == 1) THEN
              OPEN (UNIT = 62, FILE = NAMEFIL(1:KNMFIL)//'.tpp',
     1              STATUS = 'UNKNOWN')
            END IF
            PAR(487) = PAR(488)
            CALL GEN142 (VOID(NADR + 1), VOID(NADR + NREF + 1),
     1        PAR(487), NFR, GRAPH, 0)
            IPR(617) = IPR(617) + 1
            IF (IPR(617) == 2) THEN
              IPR(593) = 1
              RETURN
            END IF
          END IF
C * WRITE PROBABILITY PLOT DATA TO .npp or .tpp
          IF (IPR(652) == 1) THEN
            DO I = 1, NFR
              WRITE (LU62, 99995, IOSTAT = IOST)
     1          VOID(NADR + I), VOID(NADR + NREF + I)
            END DO
            CLOSE (UNIT = 62)
          END IF
          GRAPH(5)(52:103) =
     1      'PP for (delta(G * Fcalc**2) - delta(Fobs**2))/Sigma'
          GRAPH(6)(52:104) =
     1      'Sigma = sqrt(sigma(Fobs1**2)**2 + sigma(Fobs2**2)**2)'
          IF (PAR(493) * IPR(629) > 0.0)
     1       WRITE (GRAPH(7)(52:100), 99997, IOSTAT = IOST)
     2         PAR(493), PAR(494)
          IF (IPR(613) == 0) THEN
            WRITE (GRAPH(8)(52:), 99998, IOSTAT = IOST) XG
          ELSE
            WRITE (GRAPH(8)(52:), 99996, IOSTAT = IOST) XG, PAR(487)
          END IF
          WRITE (LUX, 99999, IOSTAT = IOST) (GRAPH(I), I = 1, 44)
          IF (LUX == LU7) CALL PLA262 (0)
        END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT ('G =', F9.4)
99997 FORMAT ('Sigma Includes SHELXL WGHT Par.', 2F9.4)
99996 FORMAT ('G =', F9.4, ' - nu =', F6.2)
99995 FORMAT (2G12.5)
      END SUBROUTINE PLA424
 
      SUBROUTINE PLA425 (DPDAT, LU)
C * Bijvoet Pair Analysis (5)
C * CALCULATE G, SIGMA(G), HOOFT AND SIGMA(HOOFT) WITH BAYESIAN STATISTICS
      USE files
      USE parameters
      USE bijvoet
      USE npplot
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: LU
      REAL :: YK
      REAL :: STEP
      DOUBLE PRECISION :: DPDAT(*)
      CHARACTER(len=48) :: FORMA
      IF (YSLOPE == 0.0) RETURN
C * APPLY NPP OR TPP SLOPE
      IF (IPR(593) /= 0) THEN
        DO J = 1, NSTP
          DPDAT(J) = DPDAT(J) / DBLE (YSLOPE)**2
        END DO
      END IF
      FORMA = '(//,''Hooft y Parameter Value .'',F9.3,''('',I2,'')'')'
      STEP  = PAR(515)
C * DETERMINE LARGEST LOG-PROBABILITY FOR SCALING
      DPDATM = DPDAT(1)
      DO J = 2, NSTP
        IF (DPDAT(J) > DPDATM) DPDATM = DPDAT(J)
      END DO
      XG0 = 0.0D+0
      XG1 = 0.0D+0
      XG2 = 0.0D+0
C * DETERMINE AVERAGE G VALUE OF THE POBABILITY DISTRIBUTION
      DO J = 1, NSTP
        YK   = (J - NSPT) * STEP
        DDIF = DPDAT(J) - DPDATM
        IF (DDIF > -500.0D+0) THEN
          XG1 = XG1 + DBLE (YK) * DEXP (DDIF)
          XG0 = XG0 +             DEXP (DDIF)
        END IF
      END DO
      XG  = XG1 / XG0
C * DETERMINE VARIANCE AND SIGMA(G) OF THE PROBABILITY DISTRIBUTION
      DO J = 1, NSTP
        YK   = (J - NSPT) * STEP
        DDIF = DPDAT(J) - DPDATM
        IF (DDIF > -500.0D+0) THEN
          XG2 = XG2 + (DBLE (YK) - DBLE (XG))**2 * DEXP (DDIF)
        END IF
      END DO
      PAR435 = (1.0 - SNGL (XG)) / 2.0
      PAR436 = SNGL(DSQRT (XG2 / XG0) / 2.0D+0)
C * ROUND
      CALL GEN041 (PAR435, PAR436, IPR615, 3, IPR616, IPR(68))
C * SAVE Hooft y data for CIF or RES Based SF ONLY
      IF (IPR(594) == 1 .OR. IABS (IGBL(8)) == 2) THEN
        PAR(435) = PAR435
        PAR(436) = PAR436
        IPR(615) = IPR615
        IPR(616) = IPR616
      ELSE IF (IPR(594) == 0) THEN
        PAR(471) = PAR435
        PAR(472) = PAR436
        IPR(715) = IPR615
        IPR(716) = IPR616
      END IF
C * CONDITIONALLY OUTPUT Hooft y PARAMETER VALUE
      IF (IPR(619) == 0 .AND. PAR(464) > PAR(476)) THEN
        IF (IPR616 > 0) THEN
          FORMA(36:36) = CHAR (ICHAR ('0') + IPR616)
          WRITE (LU, FORMA, IOSTAT = IOST) PAR435, IPR615
        ELSE
          WRITE (LU, 99999, IOSTAT = IOST) PAR435, PAR436
        END IF
C * TEST FOR FCF/CIF Based
        IF (IPR(594) == 0) THEN
C * CHECK FOR SIGNIFICANT NON-ZERO CIF-BASED HOOFT PARAMETER
          IF (PAR(435) > 5.0 * PAR(436)) THEN
            IF (PAR435 > 5.0 * PAR436 .AND.
     1        ABS (PAR(435) - PAR435) <= 2.0 * PAR(436)) THEN
              WRITE (LU, 99996, IOSTAT = IOST)
C * ALERT _917
              CALL PLA236 (917, 2, -999.0, 0.0, ' ', ' ')
            ELSE
              WRITE (LU, 99997, IOSTAT = IOST)
              WRITE (LU, 99995, IOSTAT = IOST)
            END IF
          END IF
        END IF
      ELSE
C * REPORT LOW FRIEDEL PAIR COVERAGE
        IF (IPR(617) > 1) WRITE (LU, 99994, IOSTAT = IOST)
      END IF
C * CALCULATE P3(0), P3(TW), P3(1)
      XPLLL = DPDAT(NSPP) - DPDATM
      XMNLL = DPDAT(NSPM) - DPDATM
      IF (XPLLL > -500.0D+0) THEN
        XPLLL = DEXP (XPLLL)
      ELSE
        XPLLL = 0.0D+0
      END IF
      IF (XMNLL > -500.0D+0) THEN
        XMNLL = DEXP (XMNLL)
      ELSE
        XMNLL = 0.0D+0
      END IF
      IF (XPLLL > 1.0D-99) THEN
        XPLL2 = 1.0D+0 / (1.0D+0 + XMNLL / XPLLL)
      ELSE
        XPLL2 = -1.0D+0
      END IF
C * TEST FOR F(CALC) FROM CIF
      IF (IPR(594) == 1) THEN
        IF (XPLL2 > -1.0D+0) THEN
          PAR(506) = SNGL (MAX (1.0D-35, XPLL2))
        ELSE
          PAR(506) = -1.0
        END IF
      END IF
      XTWLL = DPDAT(NSPT) - DPDATM
      IF (XTWLL > -500.0D+0) THEN
        XTWLL = DEXP (XTWLL)
      ELSE
        XTWLL = 0.0D+0
      END IF
      XSMLL = XPLLL + XTWLL + XMNLL
C * TEST FOR N/A
      IF (XSMLL > 1.0D-99) THEN
        XPLLL = XPLLL / XSMLL
        XMNLL = XMNLL / XSMLL
        XTWLL = XTWLL / XSMLL
      ELSE
        XPLLL = -1.0D+0
        XTWLL = -1.0D+0
        XSMLL = -1.0D+0
      END IF
      IF (IPR(594) == 1) THEN
        IF (XPLLL > -1.0D+0) THEN
          PAR(507) = SNGL (MAX (1.0D-35, XPLLL))
        ELSE
          PAR(507) = -1.0
        END IF
        IF (XTWLL > -1.0D+0) THEN
          PAR(508) = SNGL (MAX (1.0D-35, XTWLL))
        ELSE
          PAR(508) = -1.0
        END IF
      END IF
C * DO TWO VALUE TEST ONLY FOR y close to zero or one
      IF (ABS (ABS (PAR435 - 0.5) - 0.5) .GT.
     1  MAX (0.1, 3 * PAR436) .AND. XTWLL > 0.1D+0)
     2       XPLL2 = -1.0D+0
      IF (RCN /= 0.0) THEN
        RCO = RCT / RCN
      ELSE
        RCO = 0.0
      END IF
      IF (IGBL(36) == 0) THEN
        WRITE (LU6, 99998, IOSTAT = IOST) SUMX, IPR(707), IPR(668), DDM,
     1    DDP
        CALL PLA262 (3)
        WRITE (LU7, 99998, IOSTAT = IOST) SUMX, IPR(707), IPR(668), DDM,
     1    DDP
      END IF
      RETURN
99999 FORMAT (//, 'Hooft y Parameter Value .', F9.5, '(', F7.5, ')')
99998 FORMAT (/, 'Average Weighted Ratio =', F6.2, ' for', I5,
     1        ' Bijvoet Pairs (out of', I7, ')', /,
     2        ' MIN, MAX = ', 2F8.3, /)
99997 FORMAT (/, '*** Warning *** :', /,
     1           'This y value is invalid when an FCF',
     2        ' based on a BASF/TWIN Refinement is used.')
99996 FORMAT (/, 'Note: The supplied FCF is likely NOT based on a',
     1           ' TWIN/BASF Refinement')
99995 FORMAT (/, 'Note: The Supplied FCF is likely based on a',
     1           ' TWIN/BASF Refinement')
99994 FORMAT (/, 'Low Friedel Pair Coverage: No Hooft y Parameter',
     1           ' Reported in Validation', /)
      END SUBROUTINE PLA425
 
      SUBROUTINE PLA426 (IBPR, XMAX, YMAX, THMX, XMXP, YMXP, LU)
C * Bijvoet Pair Analysis (6)
      USE files
      USE parameters
      USE bijvoet
      USE analysis
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: IH1
      INTEGER :: IK1
      INTEGER :: IL1
      INTEGER :: IH2
      INTEGER :: IK2
      INTEGER :: IL2
      INTEGER :: IMM
      INTEGER :: JMM
      INTEGER, DIMENSION(3, *) :: IBPR
      REAL :: TH
      REAL :: WGHT
      REAL :: FCK1
      REAL :: FCK2
      REAL :: FCKD
      REAL :: FCKS
      REAL :: FOK1
      REAL :: FOK2
      REAL :: FOKD
      REAL :: FOKS
      REAL :: XMAX
      REAL :: YMAX
      REAL :: THMX
      REAL :: XMXP
      REAL :: YMXP
      REAL :: SIG1
      REAL :: SIG2
      REAL :: SIGM
      REAL :: DCDOS
      REAL :: RATIO
      REAL :: RATIO1
      CHARACTER(len=49) :: FORMB
      FORMB = '(/,''Flack Parameter Value (CIF)'',F8.3,''('',I2,'')'')'
      ICALT = 11 - IPR(594) * 6
C * SORT FRIEDEL (BIJVOET) PAIRS
      CALL GEN147 (IBPR, 3, 1, IPR(707))
      DO N = 1, IPR(707)
        I    = IBPR(2, N)
        J    = IBPR(3, N)
        IMM  = (I - 1) * NREC
        JMM  = (J - 1) * NREC
        IH1  = NINT (VOID(IMM + 1))
        IK1  = NINT (VOID(IMM + 2))
        IL1  = NINT (VOID(IMM + 3))
        FOK1 = VOID(IMM + 4)
        FCK1 = VOID(IMM + ICALT)
        SIG1 = VOID(IMM + 6)
        TH   = VOID(IMM + 7)
        IH2  = NINT (VOID(JMM + 1))
        IK2  = NINT (VOID(JMM + 2))
        IL2  = NINT (VOID(JMM + 3))
        FOK2 = VOID(JMM + 4)
        FCK2 = VOID(JMM + ICALT)
        SIG2 = VOID(JMM + 6)
        FOKD = FOK1 - FOK2
        FCKD = FCK1 - FCK2
        FOKS = FOK1 + FOK2
        FCKS = FCK1 + FCK2
        SIGM = MAX (SIG1**2 + SIG2**2, 0.01)
        RCT  = RCT + FOKD * FCKD / SIGM
        RCN  = RCN + FCKD**2 / SIGM
        SIGM = SQRT (SIGM)
        IF (FOKD * FCKD > 0.0) THEN
          NPLS = NPLS + 1
        ELSE
          NMIN = NMIN + 1
        END IF
        IF (ABS (FOKD) < 3.0 * ABS (FCKD)) THEN
C * SCALING FOR BIJVOET SCATTER PLOT
          XMAX   = MAX (XMAX, ABS (FCKD))
          YMAX   = MAX (YMAX, ABS (FOKD))
          THMX   = MAX (THMX, TH)
          FCKSLM = MAX (FCKSLM, LOG (FCKS))
C * SCALING FOR 'PARSONS' SCATTER PLOT
          IF (FCKS /= 0.0) THEN
            XMXP = MAX (XMXP, ABS (FCKD / FCKS))
          END IF
          IF (FOKS /= 0.0) THEN
            YMXP = MAX (YMXP, ABS (FOKD / FOKS))
          END IF
        END IF
        IF (FCKD /= 0.0) THEN
          RATIO  = FOKD / FCKD
          RATIO1 = ABS (FCKD) / FCKS
          DCDOS  = (FCKD - FOKD) / SIGM
          DDP    = MAX (DDP, DCDOS)
          DDM    = MIN (DDM, DCDOS)
          IF (SIGM > 0.0) THEN
            WGHT = ABS (FCKD) / SIGM
            SUMX = SUMX + WGHT * RATIO
            SUMW = SUMW + WGHT
          END IF
          IF (RATIO < -99.99) THEN
            RATIO = -99.99
          ELSE IF (RATIO > 999.99) THEN
            RATIO = 999.99
          END IF
        END IF
        IF (N == 1 .AND. IGBL(36) == 0) THEN
          WRITE (LU7, 99997, IOSTAT = IOST) PAR(452)
          CALL PLA262 (5)
        END IF
C * LIST LARGEST BIJVOET PAIR DIFFERENCES
        IF (N <= IPR(596)) THEN
          IF (N == 1) THEN
C * IPR(560) = # OF EXPECTED FRIEDEL PAIRS
            IF (PAR(433) /= 999999.0 .AND.
     1        PAR(434) /= 999999.0) THEN
              IF (IPR(280) > 0) THEN
                FORMB(37:37) = CHAR (ICHAR ('0') + IPR(280))
                IF (IPR(617) > 1) WRITE (LU, FORMB, IOSTAT = IOST)
     1            PAR(433), IPR(279)
              ELSE
C * REPORT FLACK PARAMETER VALUE
                IF (IPR(617) .GT. 1) WRITE (LU, 99994, IOSTAT = IOST)
     1            PAR(433), PAR(434)
              END IF
            END IF
            IF (IPR(617) > 1) THEN
            WRITE (LU, 99983, IOSTAT = IOST) IPR(668), IPR(560)
            WRITE (LU, 99979, IOSTAT = IOST) IPR(706)
            IF (IPR(560) > 0) THEN
              PAR(464) = IPR(668) * 100.0 / IPR(560)
              WRITE (LU, 99984, IOSTAT = IOST) NINT (PAR(464))
C * ALERT _915 - CHECK FOR LOW FRIEDEL PAIR COVERAGE
              IF (IPR(594) == 1 .AND. IPR(619) == 0) THEN
                IF (IPR(137) > 0) THEN
                  CALL PLA236 (915, 2, 100.0 - PAR(464), PAR(464),
     1              ' ', ' ')
                ELSE IF (IPR(137) < 0) THEN
                  IF (PAR(464) < PAR(476)) THEN
                    CALL PLA236 (915, 2, -999.0, PAR(464), ' ', ' ')
                  END IF
                END IF
              END IF
            END IF
            IF (PAR(425) > 0.0) THEN
              WRITE (LU, 99986, IOSTAT = IOST)
     1          PAR(425), NINT (PAR(474) * 10000.0)
            END IF
            WRITE (LU, 99993, IOSTAT = IOST)
            END IF
          END IF
          IF (IPR(617) .GT. 1) THEN
          IF (FOK1 > 99999.9 .OR. FOK2 > 99999.9  .OR.
     1        SIGM > 999.9) THEN
            WRITE (LU, 99982, IOSTAT = IOST) IH1, IK1, IL1,
     1        NINT (FOK1), IH2, IK2, IL2, NINT (FOK2), NINT (FOKD),
     2        NINT (FCKD), NINT (SIGM), WGHT, RATIO, RATIO1
          ELSE
            WRITE (LU, 99995, IOSTAT = IOST)
     1        IH1, IK1, IL1, FOK1, IH2, IK2, IL2,
     2        FOK2,  FOKD, FCKD, SIGM, WGHT, RATIO, RATIO1
          END IF
          END IF
        END IF
        IF (IGBL(36) == 0 .AND. IPR(617) > 1) THEN
          CALL PLA262 (1)
          WRITE (LU7, 99998, IOSTAT = IOST) IH1, IK1, IL1,
     1      FOK1, FCK1, SIG1, IH2, IK2, IL2, FOK2, FCK2, SIG2,
     2      FOKD, FCKD, SIGM, WGHT, RATIO, DCDOS, RATIO1
        END IF
      END DO
      SUMX = SUMX / SUMW
      RETURN
99998 FORMAT (2(3I3, 2F10.2, F8.2), 2F8.2, F9.2, 2F8.2, F8.3, F9.5)
99997 FORMAT ('Analyses of Bijvoet-Pair (Friedel-Pair) Differences',
     1        ' for abs(Fcalcl**2 - Fcalc2**2))/Sigma > ', F6.2, /,
     2        101('='), 24X, '|I+-I-|', /, 125X, 7('-'), /,
     3        ' H1 K1 L1    FO1**2    FC1**2  SIGMA1',
     4        ' H2 K2 L2    FO2**2    FC2**2  SIGMA2  DELOBS ',
     5        'DELCALC SIG(DEL) DLC/SIG DLO/DLC DC-DO/S  I+ + I-', /,
     6        132('='))
99995 FORMAT (2(3I3, F8.1, 1X), 2F8.1, F7.2, 2F6.2, F8.5)
99994 FORMAT (/, 'Flack Parameter Value ....', F8.3, '(', F6.3, ')')
99993 FORMAT (/, 62X, 'DLC   DLO |I+-I-|', /, 41X, 'DEL', 5X,
     1        'DEL    SIG   ---   --- -------', /,
     2        ' H1 K1 L1 I1(obs)  H2 K2 L2 I2(obs)      OBS',
     3        '    CALC    DEL   SIG   DLC I+ + I-', /, 79('='))
99986 FORMAT ('Res.Scat...................', F8.4, /,
     1        'Friedif_stat ..............', I8)
99984 FORMAT ('Friedel Pair Coverage .....', I8, '%')
99983 FORMAT ('Number of Bijvoet Pairs ...', I8, '[Expected', I6, ']')
99982 FORMAT (2(3I3, I8, 1X), 2I8, I7, 2F6.2, F8.5)
99979 FORMAT ('Number of Centro Reflns ...', I8)
      END SUBROUTINE PLA426
 
      SUBROUTINE PLA427
C * ROUTINE FOR COMPARING TWO FCF STYLE DATA SETS (-d)
      USE files
      USE parameters
      USE plato
      USE cchar
      USE mentry
      USE cggt
      USE analysis
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NS
      INTEGER :: IER
      INTEGER :: NRF1
      INTEGER :: NRF2
      INTEGER :: NOPT
      INTEGER :: IHKL
      INTEGER :: JMAX
      INTEGER :: NTOT
      INTEGER :: NSET1
      INTEGER :: NREFM
      INTEGER :: JDAT1
      INTEGER :: JDAT2
      INTEGER :: IHKLM
      INTEGER :: IDAT1
      INTEGER :: IDAT2
      INTEGER :: NSYMH
      INTEGER :: IDTYP1
      INTEGER :: IDTYP2
      REAL :: DET
      REAL :: SUM1
      REAL :: SUM2
      REAL :: SUM3
      REAL :: SUM4
      REAL :: SUM5
      REAL :: SUMB
      REAL :: SUMT
      REAL :: DUMMY
      REAL :: SCHAAL
C * SET RETURN VALUE
      IGBL(1) = 4
C * CHECK FOR TWO SUPPLIED DATA SET NAMES ON CALLING LINE
      IF (IGBL(19) == 2) THEN
C * SET MAXIMUM NUMBER OF REFLECTIONS
        NREFM    = NP23 / 2
        PAR(440) = 1000.0
C * INIT GRAPHICS
        CALL PLA431
C * SET MENU NUMBER
        IGBL(6) = 34
        IWIN    = IGBL(25) * IGBL(32)
C * GET FIRST DATA SET
        OPEN (LU60, FILE = FILENAMES(1),  STATUS = 'UNKNOWN')
        OPEN (LU61, FILE = 'COMPAREFILE', STATUS = 'UNKNOWN')
C * DETERMINE REFLECTION FILE TYPE
        CALL PLA010 (LU60, IDTYP1, IER)
        IGBL(54)     = 1
        IENTRY(1, 3) = - IDTYP1
        IENTRY(1, 4) = 0
        NREFF1       = 0
C * CONVERT FCF TO HKL (SHELXL FCF STYLE ASSUMED)
        CALL PLA139 (LU6, LU60, LU61, NREFF1)
        IF (NREFF1 == 0) RETURN
        CLOSE  (UNIT = LU60, IOSTAT = IOST)
        REWIND (UNIT = LU61, IOSTAT = IOST)
C * TEST FOR SHELXL STYLE FCF
        IF (IDTYP1 == 1) THEN
C * GET DIRECT CELL DATA FOR FIRST STRUCTURE
          CALL GEN026 (1, AA, REFLCELL)
          CALL GEN003 (AA, BB, DET, 0)
          CALL GEN113 (REFLCELL, CELLA, 6)
          CELLA(7) = SQRT (DET)
          PAR(98)  = CELLA(7)
          NSYMHA   = IPR(255)
          SPGRA    = SPGRNAMF
C * GET REDUCED CELL DATA AND TRANSFORMATION FOR FIRST STRUCTURE
          CALL PLA266 (1)
          CALL GEN113 (PAR(123), RCELLA, 7)
          RCELLA(7) = PAR(99)
          CALL GEN005 (TRNS, TRNSA)
        END IF
C * LOAD REFLECTION DATA TOP DOWN IN VOID AND POINTERS TO THE DATA IN JNSC
C * IH, IK, IL, I, SIG(I)
        N     = NVDR
        NRF1  = 0
C * LIMIT NUMBER OF REFLECTIONS TO NP23/2 MAX
        NREFF1 = MIN (NREFF1, NREFM)
        DO I = 1, NREFF1
          READ  (LU61, 99999) (VOID(J), J = N - 4, N)
          IF (VOID(N) > 0.0) THEN
            NRF1 = NRF1 + 1
            N    = N - 5
          END IF
        END DO
        NREFF1 = NRF1
C * BOTTOM ADDRESS - 1 FOR DATA SET #1
        NSET1 = N
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
C * GET SECOND DATA SET
        OPEN (LU60, FILE = FILENAMES(2),  STATUS = 'UNKNOWN')
        OPEN (LU61, FILE = 'COMPAREFILE', STATUS = 'UNKNOWN')
C * DETERMINE REFLECTION FILE TYPE
        CALL PLA010 (LU60, IDTYP2, IER)
        IGBL(54)     = 2
        IENTRY(2, 3) = -IDTYP2
        IENTRY(2, 4) = 0
        NREFF2       = 0
C * CONVERT FCF TO HKL (SHELXL STYLE ASSUMED)
        CALL PLA139 (LU6, LU60, LU61, NREFF2)
        IF (NREFF2 == 0) RETURN
        CLOSE  (UNIT = LU60, IOSTAT = IOST)
        REWIND (UNIT = LU61, IOSTAT = IOST)
C * TEST FOR SHELXL STYLE FCF
        IF (IDTYP2 == 1) THEN
C * GET DIRECT CELL DATA FOR SECOND STRUCTURE
          CALL GEN026 (1, AA, REFLCELL)
          CALL GEN003 (AA, BB, DET, 0)
          CALL GEN113 (REFLCELL, CELLB, 6)
          CELLB(7) = SQRT (DET)
          PAR(98)  = CELLB(7)
          NSYMHB   = IPR(255)
          SPGRB    = SPGRNAMF
C * GET REDUCED CELL DATA AND TRANSFORMATION FOR SECOND STRUCTURE
          CALL PLA266 (1)
          CALL GEN113 (PAR(123), RCELLB, 6)
          RCELLB(7) = PAR(99)
          CALL GEN005 (TRNS, TRNSB)
        END IF
C * LOAD SECOND DATA SET BELOW THE FIRST ONE
        NRF2   = 0
        NREFF2 = MIN (NREFF2, NREFM)
        DO I = 1, NREFF2
          READ  (LU61, 99999) (VOID(J), J = N - 4, N)
          IF (VOID(N) > 0.0) THEN
            NRF2 = NRF2 + 1
            N    = N - 5
          END IF
        END DO
        NREFF2 = NRF2
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
        NTOT = NREFF1 + NREFF2
C * LOAD DATA TO BE COMPAIRED
   10   DO I = 1, 2
          IF (I == 1) THEN
            IDM = 'SPGR '//SPGRA
            CALL SGSM (0, IDM, SGY, 0, 0, IERR)
            CALL GEN052 (TRNSA, TM1)
            NSYMH = NSYMHA
            JMAX  = NREFF1
            N     = NVDR
            M     = 0
          ELSE
            IDM = 'SPGR '//SPGRB
            CALL SGSM (0, IDM, SGY, 0, 0, IERR)
            CALL GEN052 (TRNSB, TM1)
            NSYMH = NSYMHB
            JMAX  = NREFF2
            N     = NVDR - NREFF1 * 5
            M     = NREFF1
          END IF
          DO J = 1, JMAX
            N  = N - 5
            DO K = 1, 3
              SGY(K) = VOID(N + K)
            END DO
C * REDUCED CELL TOGGLE
            IF (IPR(657) == 0) THEN
              IHKLM = NINT (SGY(3)) * 62500 + NINT (SGY(2)) * 250
     1              + NINT (SGY(1))
            ELSE
              IHKLM = 0
              DO NS = 1, NSYMH
                CALL SGSM (5, IDM, SGY, NS, 0, IERR)
                CALL GEN002 (1, TM1, SGY(7), V2, DUMMY)
                IHKL = NINT (V2(3)) * 62500 + NINT (V2(2)) * 250
     1              + NINT (V2(1))
                IHKLM = MAX (IHKLM, IHKL, -IHKL)
              END DO
            END IF
C * PACK H,K,L IN ONE INTEGER (MAX INDEX 124)
            JNSC (1, M + J) = IHKLM
            JNSC (2, M + J) = N + 1
          END DO
        END DO
C * SORT POINTER TO DATA ARRAY ON PACKED HKL
        CALL GEN037 (JNSC, 1, NTOT)
C * LOAD REFLECTION DATA FOR PAIRED REFLECTIONS BOTTOM UP
        NREF = 0
        M    = 0
        SUMT = 0.0
        SUMB = 0.0
        IDAT1 = JNSC (1, 1)
        DO I = 2, NTOT
          IDAT2 = JNSC (1, I)
          IF (IDAT1 == IDAT2) THEN
            JDAT1 = JNSC (2, I - 1)
            JDAT2 = JNSC (2, I)
            IF (JDAT2 > NSET1) CALL GEN014 (JDAT1, JDAT2)
            VOID(M + 4) = MAX (0.0, VOID(JDAT1 + 3)) / 100.0
            VOID(M + 5) = MAX (0.0, VOID(JDAT2 + 3)) / 100.0
            VOID(M + 6) = MAX (0.0, VOID(JDAT1 + 4)) / 100.0
            VOID(M + 7) = MAX (0.0, VOID(JDAT2 + 4)) / 100.0
            SUMT        = SUMT + VOID(M + 4)
            SUMB        = SUMB + VOID(M + 5)
            NREF        = NREF + 1
            M           = M    + NREC
          ELSE
            IDAT1 = IDAT2
          END IF
        END DO
C * DETERMINE INTER DATA SET SCALE
        SCHAAL = SUMT / SUMB
C * SAVE TOP ADDRESS
        NADR  = M
C * SCALE AND COPY (Fo-Fc)/Sig TO SEPARATE SECTION IN VOID
        M = 0
        DO I = 1, NREF
          VOID(M + 5)    =  VOID(M + 5) * SCHAAL
          VOID(M + 7)    =  VOID(M + 7) * SCHAAL
          VOID(NADR + I) = (VOID(M + 4) - VOID(M + 5)) /
     1                 SQRT (VOID(M + 6)**2 + VOID(M + 7)**2)
          M = M + NREC
        END DO
 
C * CALC PEARSON's CC
        M = 0
        SUM1 = 0.0
        SUM2 = 0.0
        SUM3 = 0.0
        SUM4 = 0.0
        SUM5 = 0.0
        DO I = 1, NREF
          SUM1 = SUM1 + VOID(M + 4)
          SUM2 = SUM2 + VOID(M + 5)
          SUM3 = SUM3 + VOID(M + 4) * VOID(M + 5)
          SUM4 = SUM4 + VOID(M + 4) ** 2
          SUM5 = SUM5 + VOID(M + 5) ** 2
          M = M + NREC
        END DO
        PAR(565) = (NREF * SUM3 - SUM1 * SUM2) /
     1    SQRT ((NREF * SUM4 - SUM1 ** 2) * (NREF * SUM5 - SUM2 **2))
C * CREATE NORMAL PROBABILITY PLOT DATA
        CALL GEN116 (2, VOID(NADR + 1), VOID(NADR + NREF + 1), NREF,
     1    GRAPH, 0)
        GRAPH(5)(52:104) =
     1    'NPP for (Io1 - Io2) / sqrt(sig(Io1)**2 + sig(Io2)**2)'
C * SET LOG-LOG DEFAULT
        IPR(633) = 1
        NOPT     = 1
   20   IF (NREFF1 > 0 .AND. NREFF2 > 0) THEN
          IF (NOPT == 0) THEN
C * DISPLAY NPP DATA
            CALL PLA204
          ELSE IF (NOPT == 1) THEN
C * SCATTER PLOT
            CALL PLA407 (1, SCHAAL, IDTYP1, IDTYP2, LU6)
C * POSTSCRIPT OUTPUT MODE
            IF (IGBL(3) == 47) RETURN
          END IF
C * SCATTER PLOT
          DO
C * WHAT NEXT ?
   30       CALL PLA012 (0, 1)
            IF (LRET == 2) GO TO 20
            CALL GEN020 (1, IGGT, 1, 10)
            SELECT CASE (IGGT(1:4))
C * END
              CASE ('END ')
                RETURN
C * EXIT
              CASE ('EXIT')
                RETURN
C * PLOT
              CASE ('PLOT')
                GO TO 20
C * PLOT
              CASE ('!   ')
                 GO TO 20
C * NORMAL PROBABILITY PLOT
              CASE ('NPP ')
                NOPT = 0
                GO TO 20
C * SCATTER-PLOT
              CASE ('SCAT')
                NOPT = 1
                GO TO 20
C * LOGLOG-PLOT
              CASE ('LOGL')
                IPR(633) = 1
                IPR(634) = 0
                NOPT     = 1
                GO TO 20
C * LINEAR-PLOT
              CASE ('LINE')
                IPR(633) = 0
                IPR(634) = 0
                GO TO 20
              CASE ('STAN')
                GO TO 30
C * REDUCED CELL TOGGLE
              CASE ('REDU')
                IPR(657) = MOD (IPR(657) + 1, 2)
                GO TO 10
            END SELECT
          END DO
        END IF
      END IF
      RETURN
99999 FORMAT (3F4.0, 2F8.0)
      END SUBROUTINE PLA427
 
      SUBROUTINE PLA428
C * CHECK FOR SHELXL20XY AND NOT SHELXL97 (FOR HYBRID & FCFfromCIF)
      USE files
      USE parameters
      USE cchar
      IMPLICIT NONE
      INTEGER :: I
      IF (IGBL(110) > 0 .AND. IGBL(139) == 0) THEN
        KERR = 0
C * RUN DUMMY SHELXL JOB
        CALL SPAWN (SHLPATH(1:IGBL(110))//' > log', LU6, .true., KERR)
        IF (KERR == 0) THEN
          OPEN (UNIT = LU60, FILE = 'log', STATUS = 'UNKNOWN',
     1    IOSTAT = IOST)
          IF (IOST == 0) THEN
            DO I = 1, 5
              READ (LU60, 99999, IOSTAT = IOST) LINE
              IF (IOST == 0) THEN
                IF (INDEX (LINE, 'Version 20') /= 0) THEN
                  IGBL(139) = 1
                  EXIT
                END IF
              END IF
            END DO
            CLOSE (LU60, STATUS = 'DELETE', IOSTAT = IOST)
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT (A)
      END SUBROUTINE PLA428
 
      SUBROUTINE PLA429
C * TEST FOR PLATON & SHELXL  ETC.                          *
      USE files
      USE parameters
      IMPLICIT NONE
      INTEGER :: FINDEXE
C * CHECK For PLATON
      PLAPATH  = ' '
      IGBL(80) = FINDEXE ('PLAEXE', PLAPATH, 'platon')
C * CHECK For SHELXL/XL (REFINEMENT) - VERSION 20xy
      SHLPATH = ' '
      IGBL(110) = FINDEXE ('SHLEXE', SHLPATH, 'shelxl')
      IF (IGBL(110) == 0)
     1    IGBL(110) = FINDEXE ('SHLEXE', SHLPATH, 'xl')
C * CHECK for SHELXT/XT (STRUCTURE SOLUTION)
      SHTPATH = ' '
      IGBL(119) = FINDEXE ('SHTEXE', SHTPATH, 'shelxt')
      IF (IGBL(119) == 0)
     1    IGBL(119) = FINDEXE ('SHTEXE', SHTPATH, 'xt')
C * CHECK FOR POVRAY
      IGBL(79) = FINDEXE ('POVEXE', CGETENV, 'povray')
C * CHECK FOR RASMOL
      IGBL(78) = FINDEXE ('RASEXE', CGETENV, 'rasmol')
C * CHECK FOR RASTER
      IGBL(77) = FINDEXE ('R3DEXE', CGETENV, 'render')
C * CHECK FOR CONQUEST/CQBATCH
      IGBL(76) = FINDEXE ('QUESTEXE', CGETENV, 'cqbatch')
C * CHECK FOR PS2PDF CONVERSION UTILITY
      IGBL(116) = FINDEXE ('PS2PDF', CGETENV, 'ps2pdf')
C * HTTPSERVER LOCATION
      IGBL(135) = LEN_TRIM (HTTPSERVER)
C * CHECK FOR FIREFOX etc.  HELP
C * FIRST CHECK FOR FIREFOX ON MAC
      BROWSER = '/Applications/safari.app/Contents/MacOS/safari'
      INQUIRE (FILE = BROWSER, EXIST = EXST)
      IF (EXST) THEN
        BROWSER = 'open -a safari'
        IGBL(47) = 14
      ELSE
        IGBL(47) = FINDEXE ('NETEXE', BROWSER, 'firefox')
      END IF
C * OPEN SCRATCH FILE FOR ALERTS (AND EXIT IN CASE OF SCRATCH OPEN ERROR)
        OPEN (UNIT = LU68, STATUS = 'SCRATCH', FORM = 'FORMATTED',
     1    IOSTAT = IOST)
        IF (IOST /= 0)
     1    CALL GEN127 ('OPEN ERROR ON ALERT SCRATCH FILE LU20')
        OPEN (UNIT = LU20, STATUS = 'SCRATCH', FORM = 'FORMATTED',
     1    IOSTAT = IOST)
        IF (IOST /= 0)
     1    CALL GEN127 ('OPEN ERROR ON ALERT SCRATCH FILE LU20')
C * SCRATCH I/SIGMA(I) (CALCULATED DATA)
        OPEN (UNIT = LU67, STATUS = 'SCRATCH', FORM = 'UNFORMATTED',
     1    IOSTAT = IOST)
        IF (IOST /= 0)
     1    CALL GEN127 ('OPEN ERROR ON ALERT SCRATCH FILE LU67')
      RETURN
      END SUBROUTINE PLA429
 
      SUBROUTINE PLA430 (UPDATE)
      USE files
      USE parameters
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: I3
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: J3
      INTEGER :: FINDEXE
      CHARACTER(len=*)   :: UPDATE
      CHARACTER(len=12)  :: UPDATE1
      CHARACTER(len=3)   :: MONTH
      CHARACTER(len=255) :: BUFFER
      CHARACTER(len=3), DIMENSION(12) :: MONTHS
      MONTHS = (/ 'JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL',
     1 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'/)
      IF (UPDATE(1:1) /= ' ') RETURN
C STRIP_BEG
C * CHECK FOR CURL
      IF (IGBL(13) == 0) THEN
        CURLPATH = ''
        IGBL(13) = FINDEXE ('CURLEXE', CURLPATH, 'curl')
      END IF
C * GET PLATON UPDATE HISTORY FILE
      WRITE (LU6, 99995) HTTPSERVER(1:IGBL(135))//'xraysoft'
      IF (IGBL(13) > 0 .OR. DOS) THEN
        IF (DOS) THEN
          BUFFER = HTTPSERVER(1:IGBL(135))//
     1      'xraysoft/update_history_platon.html'
          CALL GET_URL (BUFFER, 'curl.html', KERR, 0)
        ELSE
          CALL SPAWN (CURLPATH(1:IGBL(13))//' '//
     1      HTTPSERVER(1:IGBL(135))//
     2      'xraysoft/update_history_platon.html -m 3 -o curl.html'//
     3      ' -k --insecure', 0, .true., KERR)
        END IF
        WRITE (LU6, 99998)
        IF (KERR == 0) THEN
          OPEN (UNIT = LU60, FILE = 'curl.html', STATUS = 'UNKNOWN')
          DO
            READ (LU60, 99999, IOSTAT = IOST) UPDATE
            IF (IOST /= 0) EXIT
            IF (UPDATE(1:5) == '<BODY') EXIT
          END DO
          READ (LU60, 99999, IOSTAT = IOST) UPDATE
          IF (IOST == 0) THEN
            CLOSE (LU60, STATUS = 'DELETE', IOSTAT = IOST)
            UPDATE1 = UPDATE
            WRITE (LU6, 99994) UPDATE
            CALL GEN020 (1, UPDATE1, 1, 12)
            READ (UPDATE1, *, IOSTAT = IOST) MONTH, J1, J3
            J2 = 0
            J3 = MOD (J3, 100)
            IF (IOST == 0) THEN
              DO J = 1, 12
                IF (MONTH == MONTHS(J)) THEN
                  J2 = J
                  EXIT
                END IF
              END DO
              IF (J2 /= 0) THEN
                I1 = IGBL(4) / 10000
                I3 = IGBL(4) - I1 * 10000
                I2 = I3 / 100
                I3 = I3 - I2 * 100
                IGBL(14) = 4
                IF (J3 == I3) THEN
                  IF (J2 == I2) THEN
                    IF (J1 == I1) THEN
                      IGBL(14) = 0
                    ELSE IF (J1 > I1) THEN
                      IGBL(14) = 2
                    END IF
                  ELSE IF (J2 > I2) THEN
                    IGBL(14) = 2
                  END IF
                ELSE IF (J3 > I3) THEN
                  IGBL(14) = 2
                END IF
              ELSE
                IGBL(13) = -1000
              END IF
            ELSE
              IGBL(13) = -1000
            END IF
          ELSE
            IGBL(13) = -1000
          END IF
        ELSE
          IGBL(13) = -1000
          WRITE (LU6, 99996)
        END IF
      ELSE
        IGBL(13) = -1000
        WRITE (LU6, 99997)
      END IF
C * REGISTER curl
      IGBL(142) = 1
C STRIP_END
      RETURN
99999 FORMAT (A)
99998 FORMAT (/)
99997 FORMAT (/, '** curl NOT found; No current PLATON version shown',
     1 /)
99996 FORMAT (/, '** Can not download update-history file', /)
99995 FORMAT (':: Get Info on Latest UNIX PLATON Version on Server:',
     1 /, ':: ', A, /)
99994 FORMAT(':: Latest PLATON Update Version on Server: ', A, /)
      END SUBROUTINE PLA430
 
      SUBROUTINE PLA431
C * INIT GRAPHICS
      USE files
      USE parameters
      USE cchar
      USE cggt
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: N10
      INTEGER :: N11
      INTEGER :: N20
      INTEGER :: N21
      INTEGER :: KFIL
C * INIT GGIP GRAPHICS (NOT FOR -u and -V (-W))
      IF ((IGBL(3) /= 1 .AND. IGBL(3) /= 33 .AND. IGBL(3) /= 34)
     1  .AND. (IGBL(50) > -1 .AND. IGBL(50) < 2))  THEN
        KFIL = KNMFIL
        N10 = 1
        N11 = INDEX (FILENAMES(1), '.') - 1
        DO N = 1, N11
          IF (FILENAMES(1)(N:N) == '/') N10 = N + 1
        END DO
C * CREATE FILENAME FOR POSTSCRIPT RESULT OF FCF FILE COMPARISON (-d, -J)
        IF (IGBL(3) == 6 .OR. IGBL(3) == 47) THEN
          N20 = 1
          N21 = INDEX (FILENAMES(2), '.') - 1
          DO N = 1, N21
            IF (FILENAMES(2)(N:N) == '/') N20 = N + 1
          END DO
          NAMEFIL = FILENAMES(1)(N10:N11)//'_'//FILENAMES(2)(N20:N21)
          KFIL    = N11 - N10 + N21 - N20 + 3
        END IF
        IF (IGBL(3) == 5) THEN
          IGGT(2:80) = FILENAMES(1)(N10:N11)//'_sq'
          KFIL  = N11 + 3
        ELSE
          IGGT(2:80) = NAMEFIL(1:79)
        END IF
C * GENERAL GRAPHICS OPEN
        CALL GGIP (-999.0, FLOAT (-KFIL), 0.0, 5)
C * POSTSCRIPT GRAPHICS FOR SQUEEZE, ADP & POWDER ICALC (-q, -O, -J)
        IF (IGBL(3) == 5 .OR. IGBL(3) == 28 .OR. IGBL(3) == 47) THEN
          MEDIUM      = 1
          IGGT(16:22) = 'OFF    '
          CALL GGIP (-999.0, 0.0, 0.0, 6)
        END IF
C * CHECK FOR X11 (0/1)
        YGGIP = 0.0
        ZGGIP = 0.0
        CALL GGIP (-999.0, YGGIP, ZGGIP, 8)
        IGBL(32) = NINT (YGGIP)
      END IF
      RETURN
      END SUBROUTINE PLA431
 
      SUBROUTINE PLA432 (LRET0, TM, LU, LIS, ISPR47, YPAR, KNN)
C * TRMX - GRAPHICS
      USE files
      USE parameters
      USE cggt
      USE spgrdata
      USE lplat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: LU
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: LIS
      INTEGER :: KNN
      INTEGER :: ICOL
      INTEGER :: IVAL
      INTEGER :: NA12
      INTEGER :: NA13
      INTEGER :: NA23
      INTEGER :: NALF
      INTEGER :: NBET
      INTEGER :: NGAM
      INTEGER :: LRET0
      INTEGER :: ISPR47
      REAL :: DET
      REAL, DIMENSION(3, 3) :: TM
      REAL, DIMENSION(3, 3) :: AA
      REAL, DIMENSION(3, 3) :: BB
      REAL, DIMENSION(3, 3) :: DUM
      REAL, DIMENSION(9)    :: FNN
      REAL, DIMENSION(*)    :: YPAR
      CHARACTER(len=1)  :: ICH
      CHARACTER(len=80) :: LINE
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=1)  :: NSYS
C * SET MENU #
      IGBL(6) = 37
      EXST    = .FALSE.
      IF (KNN == 9) THEN
        DO I = 1, 9
          FNN(I) = FN(I)
        END DO
      END IF
C * LIST BRAVAIS LATTICE SELECTIONS
C * CHECK FOR AUTO-S MODE
   10 IF (IGBL(50) == 0) THEN
C * CHECK FOR SYSTEM-S MODE
        IF (IPR(548) == 1) BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
        CALL GGIP (HORS, VERT, 0.0, 1)
        VRT = VERT - 0.7
        IF (NREXT > 0) THEN
          LIJN = '(Pseudo)Extinctions Found in Input Reflection file'
          CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.1, VRT)
          VRT = VRT - 0.2
          CALL GGIP (0.0,  VRT, 0.0, 3)
          CALL GGIP (HORS, VRT, 0.0, 2)
          VRT = VRT - 0.45
          LIJN = '    Ex. Condition    av[I/sig(I)]  Number of Refl '//
     1           'I/sigI             .T./.F.'
          CALL PLA439 (0.0, LIJN, 80, 0.35, 5 + IGBL(68), 2, 0.1, VRT)
          VRT = VRT - 0.45
          LIJN = '                    .True. .False. .True. .False.'//
     1           '  Max.F    H  K  L   Ratio'
          CALL PLA439 (0.0, LIJN, 80, 0.35, 5 + IGBL(68), 2, 0.1, VRT)
          VRT = VRT - 0.2
          CALL GGIP (0.0,  VRT, 0.0, 3)
          CALL GGIP (HORS, VRT, 0.0, 2)
          VRT = VRT - 0.5
C * LIST GENERAL EXTINCTIONS (IF ANY)
          REWIND (UNIT = LU, IOSTAT = IOST)
          DO
            READ (LU, 99988, IOSTAT = IOST) LINE
            IF (IOST /= 0) EXIT
            IF (LINE(1:4) == 'EXTI') THEN
              CALL PLA439 (0.0, LINE(6:80), 75, 0.35, 1, 2, 0.1, VRT)
              VRT = VRT - 0.45
            END IF
          END DO
          BACKSPACE LU
          VRT = VRT + 0.3
          CALL GGIP (0.0,  VRT, 0.0, 3)
          CALL GGIP (HORS, VRT, 0.0, 2)
          VRT = VRT - 0.5
        END IF
C * LIST/DISPLAY POTENTIAL LATTICE / LAUE CLASS OPTIONS
        LIJN = 'Cell Transformations to Optional Crystal System, '//
     1         'Lattice Type and Laue Class'
        WRITE (LU6, 99986, IOSTAT = IOST) LIJN
        WRITE (LIS, 99986, IOSTAT = IOST) LIJN
        WRITE (LU6, 99984, IOSTAT = IOST)
        WRITE (LIS, 99984, IOSTAT = IOST)
        CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.1, VRT)
        VRT = VRT - 0.3
        CALL GGIP (0.0,  VRT, 0.0, 3)
        CALL GGIP (HORS, VRT, 0.0, 2)
        IF (CLATT(1) == 'a' .AND. CLATT(2) == 'a') THEN
          IF (BLATT(1) /= 'P' .AND. BLATT(2) == 'P') THEN
            IF (RVAL(1, 1) == 0.0 .AND. RVAL(2, 2) /= 0.0) THEN
              DO I = 1, 3
                RVAL(1, I) = RVAL(2, I)
              END DO
            END IF
          ELSE IF (BLATT(1) == 'P' .AND. BLATT(2) == 'P') THEN
            IF (ABS (XCELL(7, 1) - XCELL(7, 2)) < 0.1) THEN
              IF (RVAL(2, 2) == 0.0 .AND. RVAL(1, 2) /= 0.0) THEN
                DO I = 1, 3
                  RVAL(2, I) = RVAL(1, I)
                END DO
              END IF
            END IF
          END IF
        END IF
        LIJN = ' # Latt  Laue Rav %Ct %Nav       '//
     1   'Transformation Matrix / Cell + Volume'
        WRITE (LU6, 99986, IOSTAT = IOST) LIJN
        WRITE (LIS, 99986, IOSTAT = IOST) LIJN
        VRT = VRT - 0.5
        CALL PLA439 (0.0, LIJN, 80, 0.375, 5 + IGBL(68), 2, 0.1, VRT)
        VRT = VRT - 0.2
        CALL GGIP (0.0,  VRT, 0.0, 3)
        CALL GGIP (HORS, VRT, 0.0, 2)
        VRT      = VRT - 0.2
        PAR(360) = VRT
        PAR(361) = 0.75
C * LOOP/LIST OVER BRAVAIS LATTICE OPTIONS
        DO K = 1, NRLT0
          VRT = VRT - 0.5
C * GREEN/RED TESTS ON RVAL, COMPLETENESS
          IF (RVAL(K, 1) < RMAX .AND. (RVAL(K, 2) > PAR(432) .OR.
     1        RVAL(K, 1) < 0.0001)) THEN
            ICOL = 3
          ELSE
            ICOL = 2
          END IF
          WRITE (LIJN, 99998, IOSTAT = IOST)
     1      K, ELATT(K), CLATT(K), BLATT(K), NLAUE(LLAUE(K)),
     2      (NINT (RVAL(K, J)), J = 1, 3), (TLATT(J, K), J = 1, 9)
          WRITE (LU6, 99988, IOSTAT = IOST) LIJN
          WRITE (LIS, 99988, IOSTAT = IOST) LIJN
C * MODIFY PRINT-BUFFER
          CALL GEN065 (0, LIJN, 1, 80, 5)
          CALL PLA439 (0.0, LIJN, 80, 0.35, ICOL, 2, 0.1, VRT)
          WRITE (LIJN, 99997, IOSTAT = IOST) (XCELL(J, K), J = 1, 7)
          WRITE (LU6, 99985, IOSTAT = IOST) LIJN(1:53)
          WRITE (LIS, 99985, IOSTAT = IOST) LIJN(1:53)
          VRT = VRT - 0.25
          CALL PLA439 (0.0, LIJN, 80, 0.20, 1, 1, 9.0, VRT)
        END DO
C * ASK FOR SELECTION NUMBER OR MATRIX (0, 1 OR 9 NUMBERS)
        ISPR47 = 0
        IF (KNN == 9) THEN
          DO I = 1, 9
            FN(I) = FNN(I)
          END DO
          KNN = 0
          KN  = 9
          KL  = 0
        END IF
        IF (KN == 9) GO TO 50
        INQUIRE (FILE = '.newsym.ntr', EXIST = EXST)
C * CHECK FOR ADDSYM GENERATED NEW SYMMETRY
        IF (EXST) THEN
          OPEN (LU61, FILE = '.newsym.ntr', STATUS = 'UNKNOWN')
          READ (LU61, 99988) LINE
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          ISPR47 = 1
          GO TO 40
        END IF
C * SELECT BRAVAIS LATTICE
   30   WRITE (SBCD, 99996, IOSTAT = IOST) NRLT, CHAR (0)
        IGBL(28) = 1
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IGBL(28) = 0
        IF (IGGT(1:4) == 'PLOT') GO TO 10
        IF (IGGT(1:4) == 'EXIT') THEN
          LRET0 = 1
          RETURN
        END IF
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          WRITE (LINE, 99987, IOSTAT = IOST) NRLT
        END IF
C * PARSE SELECTION
   40   CALL GEN072 (LINE, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
   50   IF (KN == 1 .AND. FN(1) > 0 .AND. FN(1) <= NRLT0)  THEN
          NRLT = NINT (FN(1))
        ELSE IF (KN == 0 .AND. KL == 0) THEN
          GO TO 70
        ELSE IF (KN >= 9) THEN
C * CHECK DETERMINANT
          CALL GEN003 (FN(1), DUM, DET, 0)
          IF (ABS (DET) < 0.01) THEN
            WRITE (LU6, 99994, IOSTAT = IOST)
            GO TO 30
          END IF
          DO I = 1, 9
            TLATT(I, NP18) = FN(I)
            K = (I - 1) / 3 + 1
            J = MOD (I - 1, 3) + 1
            TM(K, J) = FN(I)
          END DO
          CLATT(NP18)    = ' '
          BLATT(NP18)    = ' '
          ELATT(NP18)    = ' '
          LLAUE(NP18)    = 13
          RVAL(NP18, 1)  = 0.0
          RVAL(NP18, 2)  = 0.0
          RVAL(NP18, 3)  = 0.0
          IF (KL > 0 .AND. IFL(KL)(1:4) /= 'TRMX') THEN
            CLATT(NP18) = IFL(KL)(1:1)
            BLATT(NP18) = IFL(KL)(2:2)
            ELATT(NP18) = ' '
            CALL GEN020 (-1, CLATT(NP18), 1, 1)
            CALL GEN020 (1,  BLATT(NP18), 1, 1)
          END IF
          DO 60 K = 1, NRLT0
            DO I = 1, 9
              IF (TLATT(I, K) /= TLATT(I, NP18)) GO TO 60
            END DO
            IF (BLATT(K) /= BLATT(NP18)) GO TO 60
            IF (CLATT(K) /= CLATT(NP18)) GO TO 60
            NRLT = K
            GO TO 30
   60     CONTINUE
          NRLT0 = NRLT0 + 1
C * TRANSFORM CELL-PARAMETERS
          CALL GEN026 (1, AA, YPAR(81))
          CALL GEN003 (AA, BB, DET, 0)
          YPAR(95)  = BB(1, 1)
          YPAR(96)  = BB(2, 2)
          YPAR(97)  = BB(3, 3)
          YPAR(98)  = BB(2, 3)
          YPAR(99)  = BB(1, 3)
          YPAR(100) = BB(1, 2)
          CALL GEN001 (1, TM, AA, BB)
          CALL GEN026 (-1, BB, YPAR(101))
          CALL GEN003 (BB, AA, DET, 0)
          YPAR(107) = SQRT (DET)
          DO I = 1, 9
            TLATT(I, NRLT0) = TLATT(I, NP18)
          END DO
          DO I = 1, 7
            XCELL(I, NRLT0) = YPAR(100 + I)
          END DO
          CLATT(NRLT0) = CLATT(NP18)
          BLATT(NRLT0) = BLATT(NP18)
          ELATT(NRLT0) = ELATT(NP18)
          LLAUE(NRLT0) = 13
          NRLT  = NRLT0
          IF (ISPR47 == 0) GO TO 10
        ELSE
          CALL PLA015 (0, 24)
          GO TO 30
        END IF
      END IF
C * CHECK FOR ALREADY KNOWN CRYSTAL SYSTEM
   70 IF (CLATT(NRLT) == ' ') THEN
        IF (ISPR47 == 1) THEN
          IFL(1) = IFL(2)
        ELSE
          DO
            WRITE (BCD, 99993, IOSTAT = IOST) CHAR (0)
            CALL GGIP (-999.0, 3.0, 80.0, 112)
C * GUESS DEFAULT CRYSTAL SYSTEM
            NALF = 0
            NBET = 0
            NGAM = 0
            NA12 = 0
            NA13 = 0
            NA23 = 0
            NSYS = 'a'
            IF (ABS (XCELL(4, NRLT) - 90.0)           < 0.05) NALF = 1
            IF (ABS (XCELL(5, NRLT) - 90.0)           < 0.05) NBET = 1
            IF (ABS (XCELL(6, NRLT) - 90.0)           < 0.05) NGAM = 1
            IF (ABS (XCELL(6, NRLT) - 120.0)          < 0.05) NGAM = 2
            IF (ABS (XCELL(1, NRLT) - XCELL(2, NRLT)) < 0.01) NA12 = 1
            IF (ABS (XCELL(1, NRLT) - XCELL(3, NRLT)) < 0.01) NA13 = 1
            IF (ABS (XCELL(2, NRLT) - XCELL(3, NRLT)) < 0.01) NA23 = 1
            IF (NALF + NBET + NGAM == 1) THEN
              NSYS = 'm'
            ELSE IF (NALF == 1 .AND. NBET == 1 .AND. NGAM == 2) THEN
              IF (NA12 == 1) THEN
                NSYS = 'h'
              ELSE
                NSYS = 'm'
              END IF
            ELSE IF (NALF == 1 .AND. NBET == 1 .AND. NGAM == 1) THEN
              IF (NA12 == 1 .AND. NA13 == 1 .AND. NA23 == 1) THEN
                NSYS = 'c'
              ELSE IF (NA12 == 1) THEN
                NSYS = 't'
              ELSE
                NSYS = 'o'
              END IF
            END IF
            WRITE (SBCD, 99987, IOSTAT = IOST) NRLT, NSYS, CHAR (0)
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
            IF (IGGT(1:4) == 'EXIT') THEN
              LRET0 = 1
              RETURN
            END IF
            IF (IGGT(1:4) /= 'PLOT') EXIT
          END DO
          IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
            LINE = IGGT
            CALL GEN038 (IGGT, 1, 80)
          ELSE
            LINE = NSYS
          END IF
          CALL GEN072 (LINE, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
        END IF
        CLATT(NRLT) = IFL(1)(1:1)
        BLATT(NRLT) = IFL(1)(2:2)
        CALL GEN020 (-1, CLATT(NRLT), 1, 1)
        CALL GEN020 ( 1, BLATT(NRLT), 1, 1)
        GO TO 70
      END IF
C * CHECK FOR ALREADY KNOWN BRAVAIS LATTICE TYPE
      IF (BLATT(NRLT) == ' ') THEN
        DO
          WRITE (BCD, 99990, IOSTAT = IOST) CHAR (0)
          CALL GGIP (-999.0, 3.0, 80.0, 112)
          WRITE (SBCD, 99992, IOSTAT = IOST) NRLT, CHAR (0)
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
            IF (IGGT(1:4) == 'EXIT') THEN
            LRET0 = 1
            RETURN
          END IF
          IF (IGGT(1:4) /= 'PLOT') EXIT
        END DO
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          LINE = 'P '
        END IF
        CALL GEN072 (LINE, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
        BLATT(NRLT) = IFL(1)(1:1)
        CALL GEN020 (1, BLATT(NRLT), 1, 1)
      END IF
C * CHECK FOR ALREADY KNOWN LAUE CLASS
      IF (LLAUE(NRLT) == 13) THEN
        IF (ISPR47 == 1) THEN
          FN(1) = FN(10)
        ELSE
          DO
            WRITE (BCD, 99989, IOSTAT = IOST) CHAR (0)
            CALL GGIP (-999.0, 3.0, 80.0, 112)
            ICH = CLATT(NRLT)
            SELECT CASE (ICH)
              CASE ('a')
                IVAL = 1
              CASE ('m')
                IVAL = 2
              CASE ('o')
                IVAL = 3
              CASE ('t')
                IVAL = 4
              CASE ('h')
                IF (BLATT(NRLT) == 'R') THEN
                  IVAL = 6
                ELSE
                  IVAL = 9
                END IF
              CASE ('c')
              IVAL = 11
            END SELECT
            WRITE (SBCD, 99991, IOSTAT = IOST) NRLT, IVAL, CHAR (0)
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
            IF (IGGT(1:4) == 'EXIT') THEN
              LRET0 = 1
              RETURN
            END IF
            IF (IGGT(1:4) /= 'PLOT') EXIT
          END DO
          IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
            LINE = IGGT
            CALL GEN038 (IGGT, 1, 80)
          ELSE
            WRITE (LINE, 99999, IOSTAT = IOST) IVAL
          END IF
          CALL GEN072 (LINE, IFL, FN, KL, KN, 0, LU6, 1, 1, 80, 7, NP17)
          IF (KN == 0) FN(1) = 1.0
          IF (NINT (FN(1)) < 1 .OR. NINT (FN(1)) > 12) FN(1) = 1.0
        END IF
        LLAUE(NRLT) = NINT (FN(1))
        DO I = 1, 3
          RVAL(NRLT, I) = RVL(LLAUE(NRLT), I)
        END DO
        IF (ISPR47 == 0) GO TO 10
      END IF
      RETURN
99999 FORMAT (I3)
99998 FORMAT (I2, A,'= ', A, A, 1X, A, 3I4, 1X, 9F6.3)
99997 FORMAT (3F7.3, 3F7.2, F10.0)
99996 FORMAT ('Enter TRMX Matrix or Click on / Select TRMX #[', I2, ']',
     1         A)
99994 FORMAT (':: Error - Determinant TRMX = 0.0', /)
99993 FORMAT ('a=Anorthic, m=Monoclinic, o=Orthorhombic, ',
     1        't=Tetragonal, h=hexagonal, c=cubic', A)
99992 FORMAT ('Enter Lattice Centering Type for TRMX #', I3, '[P]', A)
99991 FORMAT ('Enter Laue Class for TRMX #', I3, '[', I2, ']', A)
99990 FORMAT ('Options:  P, A, B, C, F, I, R :', A)
99989 FORMAT ('1=-1,2=2/m,3=mmm,4=4/m,5=4/mmm,6=-3,',
     1        '7=-3m1,8=-31m,9=6/m,10=6/mmm,11=m-3,12=m-3m',A)
99988 FORMAT (A)
99987 FORMAT ('Enter Crystal System for TRMX #', I3, '[', A, ']', A)
99986 FORMAT (/, A)
99985 FORMAT (25X, A)
99984 FORMAT (/, 'Note: %Ct  = percentage of Completeness', /,
     1           '      %Nav = Percentage of Symmetry Averaged ',
     2           'Reflections', /)
      END SUBROUTINE PLA432
 
      SUBROUTINE PLA439 (THETA, TEXT, NCHAR, HEIGHT, NCOL, LTHICK, X, Y)
C * PLOT TEXT STRING ROUTINE
C * THETA  = ROTATION ANGLE (DEGREES)
C * TEXT   = ASCII TEXT STRING
C * NCHAR  = NUMBER OF CHARACTERS IN TEXT
C * HEIGHT = CHARACTER HEIGHT
C * NCOL   = COLOUR
C * LTHICK = LINE THICKNESS
C * X      = X-POSITION OF LOWER LEFT CORNER OF FIRST TEXT CHARACTER
C * Y      = Y-POSITION OF LOWER LEFT CORNER OF FIRST TEXT CHARACTER
      USE cggt
      IMPLICIT NONE
      INTEGER          :: NCOL
      INTEGER          :: NCHAR
      INTEGER          :: LTHICK
      REAL             :: X
      REAL             :: Y
      REAL             :: XVAL
      REAL             :: YVAL
      REAL             :: ZVAL
      REAL             :: THETA
      REAL             :: HEIGHT
      CHARACTER(len=*) :: TEXT
      THET = THETA
      CHT  = HEIGHT
      NCHE = NCHAR
      BCD  = TEXT(1:NCHE)
      XVAL = X
      YVAL = Y
      ZVAL = 0.0
      IF (NCOL >= 0) CALL GGIP (0.0, FLOAT (NCOL), 0.0, 0)
      IF (LTHICK /= 0) THEN
        CALL GGIP (0.0, - FLOAT (LTHICK), 0.0, 0)
        CALL GGIP (XVAL, YVAL, ZVAL, 4)
        CALL GGIP (0.0, -1.0, 0.0, 0)
      ELSE
        CALL GGIP (XVAL, YVAL, ZVAL, 4)
      END IF
      IF (NCOL >= 0) CALL GGIP (0.0, 1.0, 0.0, 0)
      RETURN
      END SUBROUTINE PLA439
 
 
      SUBROUTINE PLA440 (MODE)
C * INTERACTIVE DIST, ANGLE, TORSION & FIT CALCULATION
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: J0
      INTEGER :: K0
      INTEGER :: NC
      INTEGER :: NW
      INTEGER :: NAT
      INTEGER :: ISD
      INTEGER :: NEX
      INTEGER :: IER
      INTEGER :: IFT
      INTEGER :: ILP
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: IBEG
      INTEGER :: ISO1
      INTEGER :: ISO2
      INTEGER :: LOOP
      INTEGER :: NIEN
      INTEGER :: ISVI
      INTEGER :: ISVJ
      INTEGER :: NSVI
      INTEGER :: NSVJ
      INTEGER :: MODE
      INTEGER :: NMAX
      INTEGER :: NDIJ
      INTEGER :: IENM
      INTEGER :: IEND
      INTEGER :: IDUM
      INTEGER :: NDEC
      INTEGER :: JDUM
      INTEGER :: IDIJ
      INTEGER :: IATPI
      INTEGER :: IDUM1
      INTEGER :: IDUM2
      INTEGER :: IMODE
      INTEGER :: ISDIS
      INTEGER :: NRES1
      INTEGER :: NRES2
      INTEGER :: NDIST
      INTEGER :: ISANG
      INTEGER :: NANAL
      INTEGER :: INQNR
      INTEGER :: JNQNR
      REAL :: D
      REAL :: SD
      REAL :: VI
      REAL :: VJ
      REAL :: SVI
      REAL :: SVJ
      REAL :: ANG
      REAL :: DET
      REAL :: DIJ
      REAL :: DIS
      REAL :: ANG1
      REAL :: ANG2
      REAL :: DIS1
      REAL :: DIS2
      REAL :: DIS3
      REAL :: SDIJ
      REAL :: SDIS
      REAL :: SANG
      REAL :: YUNK
      REAL :: THIRSH
      REAL :: VARDIST
      CHARACTER(len=1)  :: INQ1
      CHARACTER(len=34) :: FORMD
      CHARACTER(len=35) :: FORMC
      CHARACTER(len=43) :: FORMH
      CHARACTER(len=40) :: FORME
      CHARACTER(len=47) :: FORMR
      CHARACTER(len=48) :: FORMA
      CHARACTER(len=48) :: FORMB
      CHARACTER(len=48) :: FORMT
      CHARACTER(len=58) :: FORML
      CHARACTER(len=86) :: FORMX
      IWIN = IGBL(25) * IGBL(32)
      FORMX(1:28)   = '(''P ='',F8.4,''('',I4,''), Q ='','
      FORMX(29:61)  = 'F8.4,''('',I4,''), R ='',F8.4,''('',I4,'
      FORMX(62:86)  = '''), S ='',F8.4,''('',I4,'')'')'
      FORMB( 1:11) = '( ''DIST '',1'
      FORMB(12:48) = '( A ,''.. ''), A ,'' ='',F9.4,''('',I3,'')'')'
      FORMA( 1:48) = '(''ANGLE '',2'//FORMB(12:48)
      FORMT( 1:48) = '( ''TORS '',3'//FORMB(12:48)
      FORMC( 1:35) = '(1X,A,'' -- '',A,11X,F8.4,''('',I3,'')'')'
      FORMD( 1:34) = '(1X,2(A,'' -- ''),A,F8.2,''('',I3,'')'')'
      FORME( 1:40) = '(A,1X,A,'' : '',F10.0,''('',I2,'')   '',6F8.4)'
      FORML( 1:30) = '( ''ANGLE '',A,''- '',A,''with '',A,'
      FORML(31:58) = '''- '',A,'' ='',F9.3,''('',I3,'')'')'
      FORMH( 1:43) = '(''Dihedral Angle ='',F7.0,''('',I2,'') Degree'')'
      FORMR( 1:26) = '(''Hirshfeld R-B Dif'',F8.5,'
      FORMR(27:47) = '''('',I3,''), Rat'',F5.1)'
      ANG   = 0.0
      SANG  = 0.0
      D     = 0.0
      SD    = 0.0
      ISANG = 0
      ISD   = 0
      PAGET = 'SelGeom'
C * MODE =  0 - LU7 PRINT ONLY
C * MODE =  1 - LU6 + LU7 PRINT
C * SELECTED BOND, ANGLE, TORSION, FIT AND LSPL GEOMETRY CALCULATIONS
C * GET NUMBER OF ATOMS
      NAT     = IPR(39)
C * GET TOTAL NUMBER OF ATOMS + CENTROIDS
      NMAX    = NAT + IPR(64)
      IPR(97) = IPR(97) + 1
      IF (IPR(97) == 1 .AND. IGBL(63) > 1 .AND. MODE == 1) THEN
C * NEWPAGE
        CALL PLA262 (-3)
        WRITE (LU7, 99997, IOSTAT = IOST)
      END IF
C * GET NUMBER OF SPECIFIED LABELS
      N = IPR(81)
      IF (N < 0) THEN
        IPR(12) = 0
        N       = - N
C * INTERACTIVE FIT
        IF (IFL(1) == 'FIT') THEN
          CALL PLA441 (N, NANAL, NRES1, NRES2)
          IF (IPR(2) /= 0) GO TO 30
C * QUATERNION FIT
          IF (IPR(12) >= IPR(28) * 2) THEN
            VARDIST = 999.0
            CALL PLA442 (1, VARDIST)
C * COMPARE BOND & ANGLES IN FITTED RESIDUES
            IF (NANAL /= 0) CALL PLA084 (NRES1, NRES2)
          ELSE
            CALL PLA015 (0, 31)
            WRITE (LU6, 99998, IOSTAT = IOST)
          END IF
        ELSE
          LOOP = 1
          NW   = 0
C * LOOK FOR DIHEDRAL ANGLE REQUEST
          DO I = 2, N
            IF (IFL(I) == 'WITH') THEN
              NW   = I
              LOOP = 2
            END IF
          END DO
          DO ILP = 1, LOOP
            IF (LOOP == 1) THEN
              IBEG = 2
              IEND = N
            ELSE
              IF (ILP == 1) THEN
                IBEG = 2
                IEND = NW - 1
              ELSE
                IBEG = NW + 1
                IEND = N
              END IF
            END IF
C * LEAST-SQUARES PLANE REQUESTED
            DO I = 1, NMAX
              IATP(I) = I + 2 * NP1
            END DO
            IMODE = 0
            NDIST = 0
            DO I = IBEG, IEND
C * DIST SUB-KEYWORD
              IF (IFL(I) == 'DIST') THEN
                IMODE = 1
              ELSE
C * ATOM-NAME
                CALL PLA046 (4, IFL(I), IENM, LBB, LBC, LBD,
     1                       INQNR, JNQNR, NIEN)
                IF (NIEN < 0) THEN
C * UNKNOWN CARD ERROR
                  IF (NIEN == -4) THEN
                    IPR(2) = 7
                    GO TO 30
                  ELSE
                    NQ0    = IFL(I)(1:7)
                    IPR(2) = 3
                    GO TO 30
                  END IF
                END IF
                IPR(12)    = IPR(12) + 1 - IMODE
                NDIST      = NDIST + 1
                IATP(NIEN) = NIEN + IMODE * NP1
              END IF
            END DO
C * SORT IATP
            CALL GEN022 (IATP, 1, NMAX, 1)
C * CALCULATE PLANE
            IF (IEND - IBEG > 1) THEN
              CALL PLA055
              DO I = 1, 4
                XLS(I, ILP)     = XPV(I)
                XLS(I + 4, ILP) = XSPV(I)
              END DO
C * LIST PLANE DATA
              IFT = -10
              DO I = 5, 8
                CALL GEN041 (XPV(I), XSPV(I), ISPV(I), 4, NDEC, IPR(68))
                IFT = IFT + 21
                FORMX(IFT : IFT) = CHAR (ICHAR ('0') + NDEC)
              END DO
C * CALCULATE LINE
            ELSE
              CALL PLA227 (IATP(1), IATP(2), VECN)
              CALL PLA053 (IATP(1),IATP(2), 0, 0, D, SD, IDUM1,
     1          IDUM2, IER)
            END IF
C * X-WINDOW OUTPUT
            IF (IWIN == 1) THEN
              IF (ILP == 1) THEN
                CALL GGIP (HORS, VERT, 0.0, 1)
                VRT = VERT - 0.7
                WRITE (PRBUF, 99990, IOSTAT = IOST)
                CALL PLA439 (0.0, PRBUF, 80, 0.35, 5 + IGBL(68), 2,
     1                       1.0, VRT)
                VRT = VRT - 0.7
                WRITE (PRBUF, 99989, IOSTAT = IOST)
                CALL PLA439 (0.0, PRBUF, 80, 0.35, 5 + IGBL(68), 2,
     1                       1.0, VRT)
                WRITE (LU6, 99992, IOSTAT = IOST)
                WRITE (LU6, 99990, IOSTAT = IOST)
                WRITE (LU6, 99989, IOSTAT = IOST)
              ELSE
                VRT = VRT - 1.0
                WRITE (LU6, 99994, IOSTAT = IOST)
              END IF
C * PLANE CASE
              IF (IEND - IBEG > 1) THEN
                WRITE (PRBUF, FORMX, IOSTAT = IOST)
     1            (XPV(I), ISPV(I), I = 5, 8)
                VRT = VRT - 0.6
                CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
                WRITE (PRBUF, 99991, IOSTAT = IOST)
                VRT = VRT - 0.7
                CALL PLA439 (0.0, PRBUF, 80, 0.35, 5 + IGBL(68), 2,
     1                       1.0, VRT)
C * LINE CASE
              ELSE IF (IEND - IBEG == 1) THEN
                CALL PLA439 (0.0, '  Bond', 6, 0.35, 5 + IGBL(68), 2,
     1                       1.0, VRT)
              END IF
              VRT = VRT - 0.2
            END IF
C * PLANE CASE
            IF (IEND - IBEG > 1) THEN
              WRITE (LU6, FORMX, IOSTAT = IOST)
     1          (XPV(I), ISPV(I), I = 5, 8)
              WRITE (LU6, 99994, IOSTAT = IOST)
              WRITE (LU6, 99991, IOSTAT = IOST)
              IF (IGBL(63) > 1) THEN
                CALL PLA262 (8)
                WRITE (LU7, 99992, IOSTAT = IOST)
                WRITE (LU7, 99990, IOSTAT = IOST)
                WRITE (LU7, 99989, IOSTAT = IOST)
                WRITE (LU7, FORMX, IOSTAT = IOST)
     1            (XPV(I), ISPV(I), I = 5, 8)
                WRITE (LU7, 99994, IOSTAT = IOST)
                WRITE (LU7, 99991, IOSTAT = IOST)
              END IF
            END IF
C * TEMP GET OR-INVERT INTO UIJ
            CALL GEN003 (OR, UIJ, DET, 0)
C * CALL EXIT/STOP
            IF (DET <= 0.0) CALL GEN127 ('CANNOT INVERT OR')
C * PLANE CASE
            IF (IEND - IBEG > 1) THEN
              DO I = 1, NDIST
                IF (I > IPR(12)) THEN
                  INQ1 = ' '
                ELSE
                  INQ1 = '*'
                END IF
                IATPI = MOD (IATP(I), NP1)
                CALL PLA047 (LABA(IATPI), NQ1, IDUM, JDUM,
     1            IPR(71), IGBL(55), 0, 1 - IGBL(55))
                CALL PLA056 (XPV(1), IATPI, DIS, SDIS, ISDIS, 5, NDEC)
                ISDIS = MIN (99, ISDIS)
                FORME(19:19) = CHAR (ICHAR ('0') + NDEC)
                DO J = 1, 3
                  V2(J) = XXO(IATPI, J + 3)
                END DO
                CALL GEN002 (1, UIJ, V2, V1, YUNK)
                WRITE (PRBUF, FORME, IOSTAT = IOST)
     1            INQ1, NQ1(1:7), DIS, ISDIS,
     2            (V1(J), J = 1, 3), (V2(J), J = 1, 3)
                CALL GEN065 (LU6, PRBUF, 1, 80, 1)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.45
                  CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
                END IF
                IF (IGBL(63) > 1) THEN
                  CALL PLA262 (1)
                  WRITE (LU7, 99999, IOSTAT = IOST) PRBUF
                END IF
              END DO
C * LINE CASE
            ELSE IF (IEND - IBEG == 1) THEN
              DO I = 1, 2
                CALL PLA047 (LABA(IATP(I)), NQ1, IDUM, JDUM,
     1            IPR(71), IGBL(55), 0, 1 - IGBL(55))
                DO J = 1, 3
                  V2(J) = XXO(IATP(I), J + 3)
                END DO
                CALL GEN002 (1, UIJ, V2, V1, YUNK)
                WRITE (PRBUF, 99993, IOSTAT = IOST) NQ1(1:7),
     1                (V1(J), J = 1, 3), (V2(J), J = 1, 3)
                CALL GEN065 (LU6, PRBUF, 1, 80, 1)
                IF (IWIN == 1) THEN
                  VRT = VRT - 0.45
                  CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
                END IF
                IF (IGBL(63) > 1) THEN
                  CALL PLA262 (1)
                  WRITE (LU7, 99999, IOSTAT = IOST) PRBUF
                END IF
              END DO
            END IF
          END DO
          IF (LOOP == 2) THEN
C * PLANE CASE
            IF (IEND - IBEG > 1) THEN
              ANG = RGBL(6) * ACOS (MIN (ABS (XLS(1, 1) * XLS(1, 2) +
     1          XLS(2, 1) * XLS(2, 2) + XLS(3, 1) * XLS(3, 2)), 1.0))
                SANG = 0
              DO I = 5, 7
                SANG = SANG + XLS(I, 1)**2 + XLS(I, 2)**2
              END DO
              SANG = RGBL(6) * SQRT (SANG)
              FORMH(3:10) = 'Dihedral'
C * LINE CASE
            ELSE IF (IEND - IBEG == 1) THEN
              ANG = 90.0 - ACOS (MIN (ABS (XLS(1, 1) * VECN(1) +
     1          XLS(2, 1) * VECN(2) + XLS(3, 1) * VECN(3)), 1.0)) *
     2          RGBL(6)
              SANG = 0.0
              DO L = 1, 3
                SANG = SANG + XLS(L + 4, 1)**2 + (VECN(L) * SD / D)**2
              END DO
              SANG = RGBL(6) * SQRT (SANG)
              FORMH(3:10) = 'LsplBond'
            END IF
            IF (IEND - IBEG > 0) THEN
              CALL GEN041 (ANG, SANG, ISANG, 2, NDEC, IPR(68))
              ISANG        = MIN (99, ISANG)
              FORMH(24:24) = CHAR (ICHAR ('0') + NDEC)
              WRITE (PRBUF, FORMH, IOSTAT = IOST) ANG, ISANG
              WRITE (LU6, 99994)
              CALL GEN065 (LU6, PRBUF, 1, 80, 1)
              IF (IWIN == 1) THEN
                VRT = VRT - 1.00
                CALL PLA439 (0.0, PRBUF, 80, 0.35, 1, 2, 1.0, VRT)
              END IF
            END IF
          END IF
          IF (IPR(41) == 0) THEN
            PRBUF = 'UNIT WEIGHTS'
          ELSE IF (IPR(41) == 1) THEN
            PRBUF = 'ATWT WEIGHTS'
          ELSE
            PRBUF = 'ESD/SU WEIGHTS'
          END IF
          WRITE (LU6, 99988, IOSTAT = IOST) PRBUF
          IF (IGBL(63) > 1) THEN
            CALL PLA262 (2)
            WRITE (LU7, 99988, IOSTAT = IOST) PRBUF
          END IF
          IF (IWIN == 1) THEN
            VRT = VRT - 1.0
            CALL PLA439 (0.0, PRBUF, 30, 0.35, 5 + IGBL(68), 2,
     1                   1.0, VRT)
            CALL PLA297 (0)
          END IF
        END IF
C * DISTANCES & ANGLES
      ELSE
        DO I = 2, N
C * PACK ASCII LABEL INTO NUMBER INCLUDING SYMMETRY CODE
          NQ2 = IFL(I)(1:7)
          DO 10 J = 1, 2
            CALL PLA046 (4, NQ2, IENM, LBB, LBC, LBD,
     1                   INQNR, JNQNR, NIEN)
            IF (NIEN < 0) THEN
              IF (NIEN == -4) THEN
C * NOT FOUND, INTRODUCE _ IN FRONT OF CHARACTER I.E C1A --> C1_A
                DO L = 1, 6
                  IF (NQ2(7-L:7-L) /= ' ') THEN
                    NQ2(8-L:8-L) = NQ2(7-L:7-L)
                    NQ2(7-L:7-L) = '_'
                    GO TO 10
                  END IF
                END DO
              END IF
              NQ0    = NQ2
              IPR(2) = 3
              GO TO 30
            END IF
            CALL PLA047 (INQNR, NQ1, IDUM, JDUM, IPR(71), IGBL(55),
     1                   0, 1 - IGBL(55))
            NAMS(I, 1) = ' '//NQ1(1:NP64-1)
            GO TO 20
   10     CONTINUE
C * UNSUITABLE LABEL ENCOUNTERED
          IPR(2) = 7
          GO TO 30
   20     JATC(I) = NIEN
        END DO
        IF (N == 2) THEN
          I   = JATC(2)
          NC  = - NINT (CON(I, 9))
          IF (NC < 0) NC = 9
          DO J = 1, NC
            J0 = NINT (CON(I, J))
            CALL PLA053 (I, J0, 0, 0, D, SD, ISD, NDEC, IER)
            IF (IER == 0) THEN
              FORMC(23:23) = CHAR (ICHAR ('0') + NDEC)
              ISD = MIN (999, ISD)
              CALL PLA047 (LABA(J0), NQ2, IDUM, JDUM, IPR(71),
     1                     IGBL(55), 0, 1 - IGBL(55))
              IF (MODE == 0) CALL PLA262 (1)
              WRITE (PRBUF, FORMC, IOSTAT = IOST) NQ2(1:7), NQ1(1:7),
     1          D, ISD
              IF (MODE == 1) CALL GEN065 (LU6, PRBUF, 1, 80, 1)
              IF (IGBL(63) > 1) CALL GEN065 (LU7, PRBUF, 1, 80, 1)
              DO K = J + 1, NC
                IF (K <= NC) THEN
                  K0 = NINT (CON(I, K))
                  CALL PLA053 (K0, I, J0, 0, ANG, SANG, ISANG, NDEC,
     1                         IER)
                  IF (IER == 0) THEN
                    FORMD(22:22) = CHAR (ICHAR ('0') + NDEC)
                    ISANG = MIN (999, ISANG)
                    CALL PLA047 (LABA(K0), NQ3, IDUM, JDUM,
     1                IPR(71), IGBL(55), 0, 1 - IGBL(55))
                    IF (MODE == 0) CALL PLA262 (1)
                    WRITE (PRBUF, FORMD, IOSTAT = IOST)
     1                NQ2(1:7), NQ1(1:7), NQ3(1:7), ANG, ISANG
                    IF (MODE == 1) CALL GEN065 (LU6, PRBUF, 1, 80, 1)
                    IF (IGBL(63) > 1)
     1                CALL GEN065 (LU7, PRBUF, 1, 80, 1)
                  END IF
                END IF
              END DO
            END IF
          END DO
C * BOND/DIST
        ELSE IF (N == 3) THEN
          IF (JATC(2) /= JATC(3)) THEN
            CALL PLA053 (JATC(2), JATC(3), 0, 0, D, SD, ISD, NDEC, IER)
          ELSE
            IER = 1
          END IF
          IF (IER == 0) THEN
            ISD          = MIN (99, ISD)
            FORMB(36:36) = CHAR (ICHAR ('0') + NDEC)
            WRITE (PRBUF, FORMB, IOSTAT = IOST)
     1        (NAMS(I, 1)(2:8), I = 2, 3), D, ISD
C * ADD HIRSHFELD RIGID BOND TEST INFO
            IF (IABS(IGBL(8)) == 3 .AND. IPR(5) == 1) THEN
              CALL GEN048 (-1, IFG(1, JATC(2)), 4, ISO1)
              CALL GEN048 (-1, IFG(1, JATC(3)), 4, ISO2)
              IF (ISO1 == 1 .AND. ISO2 == 1) THEN
C * GET ANGSTROM COORDINATES IN INIT SETTING AND UNIT DIRECTION OF BOND
                DO I = 1, 3
                  V7(I) = (VOID((JATC(3) - 1) * NP71 + 21 + I)
     1                  -  VOID((JATC(2) - 1) * NP71 + 21 + I)) / D
                END DO
                VI = 0.0
                VJ = 0.0
                DO K = 1, 3
                  DO L = 1, 3
                    M = K * L
                    IF (M == 6) M = 5
                    IF (M == 9) M = 6
                    VI = VI + V7(K) * SUAN(JATC(2), M) * V7(L)
                    VJ = VJ + V7(K) * SUAN(JATC(3), M) * V7(L)
                  END DO
                END DO
                SVI = SUAN(JATC(2), 7)
                CALL GEN041 (VI, SVI, ISVI, 5, NSVI, IPR(68))
                SVJ = SUAN(JATC(3), 7)
                CALL GEN041 (VJ, SVJ, ISVJ, 5, NSVJ, IPR(68))
                ISVI = MAX (0, MIN (99, ISVI))
                ISVJ = MAX (0, MIN (99, ISVJ))
                DIJ  = ABS(VI - VJ)
                NDIJ = 5
                IF (ISVI > 0 .AND. ISVJ > 0) THEN
                  SDIJ =
     1             SQRT (SUAN(JATC(2), 7)**2 + SUAN(JATC(3), 7)**2)
                  CALL GEN041 (DIJ, SDIJ, IDIJ, 5, NDIJ, IPR(68))
                  IDIJ   = MIN (99, IDIJ)
                  THIRSH = DIJ / SDIJ
                ELSE
                  IDIJ   = 0
                  THIRSH = 0.0
                END IF
                FORMR(25:25) = CHAR (ICHAR ('0') + NDIJ)
                WRITE (PRBUF(40:80), FORMR, IOSTAT = IOST)
     1            DIJ, IDIJ, THIRSH
              END IF
            END IF
            CALL GEN065 (LU6, PRBUF, 1, 80, 1)
          ELSE
C * REPORT INPUT ERROR
            WRITE (PRBUF, 99995, IOSTAT = IOST)
            WRITE (LU6,   99995, IOSTAT = IOST)
          END IF
          IF (IGBL(63) > 1) CALL PLA263 (LU7, PRBUF, 80, 1, 1)
C * ANGLE
        ELSE IF (N == 4) THEN
          CALL PLA053 (JATC(2), JATC(3), JATC(4), 0, ANG, SANG,
     1                 ISANG, NDEC, IER)
          IF (IER == 0) THEN
            ISANG        = MIN (999, ISANG)
            FORMA(36:36) = CHAR (ICHAR('0') + NDEC)
            WRITE (PRBUF, FORMA, IOSTAT = IOST)
     1        (NAMS(I, 1)(2:8), I = 2, 4), ANG, ISANG
            CALL GEN065 (LU6, PRBUF, 1, 80, 1)
            IF (IGBL(63) > 1) CALL PLA263 (LU7, PRBUF, 80, 1, 1)
          ELSE
            WRITE (LU6, 99995, IOSTAT = IOST)
          END IF
C * ANGLE BETWEEN BONDS
        ELSE IF (N == 5) THEN
          IF (IFL(1)(1:3) == 'ANG' .OR. IPR(341) == 5) THEN
            NEX = NMAX + 1
            DO I = 4, 6
              XXO(NEX, I) = XXO(JATC(5), I) + XXO(JATC(2), I)
     1                    - XXO(JATC(4), I)
              XSD(NEX, I) = XSD(JATC(5), I)
            END DO
            CALL PLA053 (JATC(3), JATC(2), NEX, 0, ANG, SANG,
     1                   ISANG, NDEC, IER)
            IF (IER == 0) THEN
              ISANG        = MIN (999, ISANG)
              FORML(46:46) = CHAR (ICHAR('0') + NDEC)
              WRITE (PRBUF, FORML, IOSTAT = IOST)
     1          (NAMS(I, 1)(2:8), I = 2, 5), ANG, ISANG
              CALL GEN065 (LU6, PRBUF, 1, 80, 1)
              IF (IGBL(63) > 1) CALL PLA263 (LU7, PRBUF, 80, 1, 1)
            END IF
C * TORSION
          ELSE
            CALL PLA053 (JATC(2), JATC(3), JATC(4), JATC(5),
     1                   ANG, SANG, ISANG, NDEC, IER)
            IF (IER == 0) THEN
              ISANG        = MIN (999, ISANG)
              FORMT(36:36) = CHAR (ICHAR ('0') + NDEC)
              CALL PLA050 (JATC(2), JATC(3), JATC(4), 0, ANG1)
              CALL PLA050 (JATC(3), JATC(4), JATC(5), 0, ANG2)
              CALL PLA050 (JATC(2), JATC(3), 0, 0, DIS1)
              CALL PLA050 (JATC(3), JATC(4), 0, 0, DIS2)
              CALL PLA050 (JATC(4), JATC(5), 0, 0, DIS3)
              WRITE (PRBUF, FORMT, IOSTAT = IOST)
     1          (NAMS(I, 1)(2:8), I = 2, 5), ANG, ISANG
              CALL GEN065 (LU6, PRBUF, 1, 80, 1)
              WRITE (LU6, 99996, IOSTAT = IOST)
     1          ANG1, ANG2, DIS1, DIS2, DIS3
              IF (IGBL(63) > 1) THEN
                CALL PLA263 (LU7, PRBUF, 80, 1, 1)
                CALL PLA262 (2)
                WRITE (LU7, 99996, IOSTAT = IOST)
     1            ANG1, ANG2, DIS1, DIS2, DIS3
              END IF
            END IF
          END IF
        ELSE
          IPR(2) = 7
          GO TO 30
        END IF
      END IF
   30 IF (MODE == 1) THEN
        IF (IFL(1)(1:3) == 'DIS' .OR. IFL(1)(1:3) == 'ANG'
     1      .OR. IFL(1)(1:3) == 'TOR' .OR. IFL(1)(1:4) == 'LSPL'
     2      .OR. IPR(341) /= 0) THEN
          IF (IPR(2) /= 0) THEN
            PRBUF = 'Label Error :  '//IFL(I)
            IPR(2) = 0
            WRITE (LU6, 99999, IOSTAT = IOST) PRBUF(1:79)
          END IF
          IF (IGBL(25) * IGBL(32) == 1) THEN
            IGBL(6) = - IABS (IGBL(6))
            SBCD = PRBUF(1:79)//CHAR (0)
          END IF
        END IF
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT (/, ':: Not Enough Atoms to Fit on', /)
99997 FORMAT ('Selected Geometrical Data', /, 132('=')/)
99996 FORMAT ('ANGLE', 6X, F9.2, F10.2, /, 'BOND', 2X, 3(F10.4))
99995 FORMAT (':: Input Error, Try again')
99994 FORMAT (1X)
99993 FORMAT (2X, A, 20X, 6F8.4)
99992 FORMAT (//)
99991 FORMAT  (2X, 'Atom', 12X, 'Distance', 8X, 'x', 7X,
     1        'y', 7X, 'z', 6X, 'X', 7X, 'Y', 7X, 'Z')
99990 FORMAT ('The equation of the plane is of the form:',
     1           ' P * x + Q * y + R * z - S = 0')
99989 FORMAT ('where P, Q, R, S are constants and x, y, z',
     1           ' are fractional coordinates.')
99988 FORMAT (/, A)
      END SUBROUTINE PLA440
 
      SUBROUTINE PLA441 (N, NANAL, NRES1, NRES2)
      USE files
      USE parameters
      USE plato
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: NAT
      INTEGER :: IHAT
      INTEGER :: LBN1
      INTEGER :: LBN2
      INTEGER :: NIEN
      INTEGER :: IENM
      INTEGER :: NRES0
      INTEGER :: NRES1
      INTEGER :: NRES2
      INTEGER :: NRESI
      INTEGER :: NRESJ
      INTEGER :: NANAL
      INTEGER :: INQNR
      INTEGER :: JNQNR
C * CHECK FOR CASE OF NO LABELS GIVEN (CHECK MINIMUM NUMBER OF RESIDUES)
      NANAL = 0
   10 IF (N == 1 .AND. IPR(75) > 1) THEN
C * GET NUMBER OF ATOMS
        NAT = IPR(39)
C * SELECT TWO DEFAULT RESIDUE NUMBERS
        IF (IPR(221) == 0) THEN
          FN(1)    = 2
          FN(2)    = 1
          IPR(221) = 2
        END IF
        IF (IPR(221) == 2) THEN
          NRES1 = NINT (FN(1))
          NRES2 = NINT (FN(2))
          N2    = 0
C * FIND PAIRS OF UNIQUE ATOMS
          DO 20 I = 1, NAT
C * SKIP H-ATOMS
            CALL GEN048 (-1, IFG(1, I), 7, IHAT)
            IF (IHAT == 0) THEN
C * GET RESIDUE NUMBER RESD1
              CALL GEN048 (-6, IFG(1, I), 9, NRESI)
              IF (NRESI == NRES1) THEN
C * GET LABUTE NUMBER RESD1
                CALL GEN048 (-10, IFG(2, I), 14, LBN1)
                IF (I < NAT) THEN
                  DO J = 1, NAT
                    IF (J /= I) THEN
C * GET LABUTE NUMBER RESD2
                      CALL GEN048 (-10, IFG(2, J), 14, LBN2)
                      IF (LBN1 == LBN2) THEN
C * GET RESIDUE NUMBER RESD2
                        CALL GEN048 (-6, IFG(1, J), 9, NRESJ)
                        IF (NRESI == NRESJ) GO TO 20
                      END IF
                    END IF
                  END DO
                END IF
                DO J = 1, NAT
                  CALL GEN048 (-1, IFG(1, J), 7, IHAT)
                  IF (IHAT == 0) THEN
                    CALL GEN048 (-6, IFG(1, J), 9, NRESJ)
                    IF (NRESJ == NRES2) THEN
                      CALL GEN048 (-10, IFG(2, J), 14, LBN2)
                      IF (LBN1 == LBN2) THEN
                        N2         = N2 + 2
                        JR(N2 - 1) = I
                        JR(N2)     = J
                        GO TO 20
                      END IF
                    END IF
                  END IF
                END DO
              END IF
            END IF
   20     CONTINUE
          IF (N2 >= IPR(28) * 2) THEN
            IPR(12) = N2
            WRITE (LU6, 99999, IOSTAT = IOST) NRES1, NRES2, N2 / 2
          ELSE
            N = -3
            GO TO 10
          END IF
        ELSE
C * UNKNOWN CARD ERROR
          IPR(2) = 7
          RETURN
        END IF
C * SPECIAL RESIDUE FIT (TWO LABELS, ONE FROM EACH RESIDUE)
      ELSE IF (ABS (N) == 3) THEN
        NANAL = 1
        IF (N == 3) THEN
C * GET TWO RESIDUE NUMBERS FROM THE TWO LABELS
          CALL PLA046 (4, IFL(2), IENM, LBB, LBC, LBD,
     1                 INQNR, JNQNR, N1)
          IF (N1 < 0) THEN
C * UNKNOWN CARD ERROR
            IF (N1 == -4) THEN
              IPR(2) = 7
              RETURN
            ELSE
              NQ0    = IFL(2)(1:7)
              IPR(2) = 3
              RETURN
            END IF
          END IF
          CALL GEN048 (-6, IFG(1, N1), 9, NRES1)
          CALL PLA046 (4, IFL(3), IENM, LBB, LBC, LBD,
     1                 INQNR, JNQNR, N2)
          IF (N2 < 0) THEN
            IF (N2 == -4) THEN
C * UNKNOWN CARD ERROR
              IPR(2) = 7
              RETURN
            ELSE
              NQ0    = IFL(3)(1:7)
              IPR(2) = 3
              RETURN
            END IF
          END IF
          CALL GEN048 (-6, IFG(1, N2), 9, NRES2)
        END IF
        N1 = -1
        N2 =  0
C * ASSUME THE SAME LABEL ORDER IN BOTH SORTED RESIDUES
        DO I = 1, NAT
          CALL GEN048 (-1, IFG(1, I), 7, IHAT)
          IF (IHAT == 0) THEN
            CALL GEN048 (-6, IFG(1, I), 9, NRES0)
            IF (NRES0 == NRES1) THEN
              N1     = N1 + 2
              JR(N1) = I
C * REGISTER COMPANION IN JCA (FOR PLA084)
            ELSE IF (NRES0 == NRES2) THEN
              N2     = N2 + 2
              JR(N2) = I
C * REGISTER COMPANION IN JCA (FOR PLA084)
            END IF
          END IF
        END DO
        IF (N2 /= N1 + 1) THEN
          WRITE (LU6, 99998, IOSTAT = IOST)
          IPR(2) = -1
          RETURN
        END IF
        DO K = 1, N2 - 1, 2
          JCA(JR(K)) = JR(K + 1)
        END DO
        IPR(12) = N2
        WRITE (LU6, 99999, IOSTAT = IOST) NRES1, NRES2, N2 / 2
      ELSE
C * LOOP OVER SPECIFIED ATOM PAIRS
        DO I = 2, N
C * ATOM-NAME
          CALL PLA046 (4, IFL(I), IENM, LBB, LBC, LBD,
     1                 INQNR, JNQNR, NIEN)
          IF (NIEN < 0) THEN
C * UNKNOWN CARD ERROR
            IF (NIEN == -4) THEN
              IPR(2) = 7
              RETURN
            ELSE
              NQ0    = IFL(I)(1:7)
              IPR(2) = 3
              RETURN
            END IF
          END IF
          IPR(12)     = IPR(12) + 1
          JR(IPR(12)) = NIEN
        END DO
      END IF
      RETURN
99999 FORMAT (/, ':: Fit for RESD =', I3,
     1        ' and RESD =', I3, ' [N(fit) =', I3, ']')
99998 FORMAT (/, ':: Residues contain unequal number of atoms, nofit!!')
      END SUBROUTINE PLA441
 
      SUBROUTINE PLA442 (LU, VARDIST)
C * QUATERNION-MOLFIT ROUTINE - CALLED FROM PLA440, PLA085, PLA390
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: NAT
      INTEGER :: ISN
      INTEGER :: ISN0
      INTEGER :: ISN1
      INTEGER :: ISN7
      INTEGER :: ISNB
      INTEGER :: ISNS
      INTEGER :: NAT1
      INTEGER :: NAT2
      INTEGER :: NATC
      INTEGER :: NADD
      INTEGER :: IDUM
      INTEGER :: JDUM
      INTEGER :: IHAT
      INTEGER :: NRES
      INTEGER :: MBST
      INTEGER :: NRES1
      INTEGER :: NRES2
      INTEGER :: NONHA
      INTEGER :: MODNM
      REAL :: F1
      REAL :: F2
      REAL :: F3
      REAL :: F4
      REAL :: TH
      REAL :: DET
      REAL :: DUM
      REAL :: SHH
      REAL :: THH
      REAL :: VAL
      REAL :: WGHT
      REAL :: XLNG
      REAL :: DIST
      REAL :: STHH
      REAL :: SUMW
      REAL :: CTHH
      REAL :: BEST
      REAL :: RMSQ
      REAL :: URMS
      REAL :: V2MAX
      REAL :: URMS1
      REAL :: SUMW1
      REAL :: RMSQ1
      REAL :: THETA
      REAL :: GEN009
      REAL :: VARDIST
      REAL, DIMENSION(3) :: DUMW
      REAL, DIMENSION(3) :: V
      CHARACTER(len=8) :: INVRT
      CHARACTER(len=1) :: INCF
C * OUTPUT JOB-HEADER
      IF (LU == 1) WRITE (LU6, 99999, IOSTAT = IOST)
      CALL PLA262 (-3)
      WRITE (LU7, 99999, IOSTAT = IOST)
C * GENERATE FILE FOR PLUTON-DISPLAY
      IF (LU /= 0) OPEN (UNIT = LU60,
     1   FILE = NAMEFIL(1:KNMFIL)//'_fit.spf', STATUS = 'UNKNOWN')
C * TOTAL NUMBER OF ATOMS
      NAT  = IPR(39)
C * GET NUMBER OF ATOM PAIRS FOR FITTING
      NAT2 = IPR(12)
      NAT1 = NAT2 - 1
      NATC = NAT2 / 2
C * GET THE TWO RESIDUE NUMBERS FOR MOL1 & MOL2
      CALL GEN048 (-6, IFG(1, JR(1)), 9, NRES1)
      CALL GEN048 (-6, IFG(1, JR(2)), 9, NRES2)
C * GET CENTER OF GRAVITY OF MOL1 & MOL2 (UNIT WEIGHT)
      CALL GEN074 (DUMA, 1, 6, 0.0)
      DO I = 1, NAT
        NADD = 1
C * LOOP OVER ATOM PAIRS
        DO J = 1, NAT2
          IF (JR(J) == I) THEN
            K = MOD (J + 1, 2) * 3
            DO N = 1, 3
              DUMA(N + K) = DUMA(N + K) + XXO(JR(J), 3 + N) / NATC
            END DO
            NADD = 0
            EXIT
          END IF
        END DO
C * ADD OTHER ATOMS BELONGING TO RESIDUE 1 or 2 (BUT NOT IN THE FIT SET)
        IF (NADD == 1) THEN
          CALL GEN048 (-6, IFG(1, I), 9, NRES)
          IF (NRES == NRES1) THEN
            NAT1     = NAT1 + 2
            JR(NAT1) = I
          ELSE IF (NRES == NRES2) THEN
            NAT2     = NAT2 + 2
            JR(NAT2) = I
          END IF
        END IF
      END DO
      DO WHILE (NAT2 /= NAT1 + 1)
        IF (NAT2 > NAT1 + 1) THEN
          NAT1     = NAT1 + 2
          JR(NAT1) = 0
        ELSE IF (NAT2 < NAT1 + 1) THEN
          NAT2     = NAT2 + 2
          JR(NAT2) = 0
        END IF
      END DO
      ISN  = 0
      ISN1 = 1
      ISN7 = 7
      ISNS = 1
C * CHECK FOR (YES/NO) INVERT FIT
      IF (IPR(33) /= 0) THEN
        ISNS = 2
        IF (IPR(33) == 2) THEN
          ISN1 = 2
          ISN7 = 8
        END IF
      END IF
      TH   = 0.0
      BEST = 99999.0
      ISNB = 1
      MBST = 0
      DO ISN0 = ISN1, ISN7, ISNS
        IF (ISN0 == ISN7) THEN
          ISN = ISNB
          M   = MBST
          IF (ISN == -1) THEN
            IF (LU == 1) WRITE (LU6, 99994, IOSTAT = IOST)
     1        NRES1, NRES2
            CALL PLA262 (2)
            WRITE (LU7, 99994, IOSTAT = IOST) NRES1, NRES2
            CALL PLA262 (2)
            INVRT = '(INVERT)'
          ELSE
            INVRT = '        '
          END IF
          IF (LU /= 0) WRITE (LU60, 99991, IOSTAT = IOST)
     1      JID(1:8), NRES1, INVRT, NRES2, NATC
        ELSE
          M = INT ((ISN0 - 1) / 2)
          IF (MOD (ISN0, 2) == 0) THEN
            ISN = -1
          ELSE
            ISN = 1
          END IF
        END IF
        CALL GEN021 (DUMV, 0.0)
        CALL GEN074 (DUMW, 1, 3, 0.0)
        CALL GEN074 (V5,   1, 3, 0.0)
        CALL GEN074 (V6,   1, 3, 0.0)
        DO I = 1, IPR(12), 2
          DO J = 1, 3
            V1(J) =  (XXO(JR(I), MOD (J + M, 3) + 4)
     1             - DUMA(MOD (J + M, 3) + 1)) * ISN
            V2(J) = XXO(JR(I + 1), J + 3) - DUMA(J + 3)
            V3(J) =   V1(J) + V2(J)
            V4(J) = - V1(J) + V2(J)
          END DO
          DUMV(1, 1) = DUMV(1, 1) + V3(2)**2 + V3(3)**2
          DUMV(2, 2) = DUMV(2, 2) + V3(1)**2 + V3(3)**2
          DUMV(3, 3) = DUMV(3, 3) + V3(1)**2 + V3(2)**2
          DUMV(1, 2) = DUMV(1, 2) - V3(1) * V3(2)
          DUMV(1, 3) = DUMV(1, 3) - V3(1) * V3(3)
          DUMV(2, 3) = DUMV(2, 3) - V3(2) * V3(3)
          DUMW(1)    = DUMW(1)    - V3(3) * V4(2) + V3(2) * V4(3)
          DUMW(2)    = DUMW(2)    + V3(3) * V4(1) - V3(1) * V4(3)
          DUMW(3)    = DUMW(3)    - V3(2) * V4(1) + V3(1) * V4(2)
        END DO
        DUMV(2, 1) = DUMV(1, 2)
        DUMV(3, 1) = DUMV(1, 3)
        DUMV(3, 2) = DUMV(2, 3)
C * INVERT MATRIX
        CALL GEN003 (DUMV, RMAT, DET, 0)
C * MATRIX * VECTOR
        CALL GEN002 (1, RMAT, DUMW, V8, XLNG)
        THETA = 2 * ATAN (SQRT (GEN009(V8, V8)))
        TH    = THETA * RGBL(6)
C * CATCH IDENTITY CASE
        IF (ABS(TH) < 0.001) THEN
          CALL PLA262 (5)
          IF (LU == 1) THEN
            WRITE (LU6, 99993, IOSTAT = IOST)
            WRITE (LU6, 99998, IOSTAT = IOST) TH, V5, V6
          END IF
          WRITE (LU7, 99993, IOSTAT = IOST)
          WRITE (LU7, 99998, IOSTAT = IOST) TH, V5, V6
        END IF
        DO I = 1, 3
          V(I) = V8(I) / TAN (THETA / 2)
        END DO
        IF (ISN0 == ISN7) THEN
C * CORRECT FOR 'PRE-ROTATION OF RESD #1
          STHH  = SIN (THETA / 2.0)
          CTHH  = COS (THETA / 2.0)
          V5(1) = STHH * V(1)
          V5(2) = STHH * V(2)
          V5(3) = STHH * V(3)
          VAL   = SIN ( -(M + 1) * 60.0 / RGBL(6)) / SQRT (3.0)
          CALL GEN074 (V6, 1, 3, VAL)
          VAL   = COS (-(M + 1) * 60.0 / RGBL(6))
          THH   = CTHH * VAL  - GEN009 (V5, V6)
          THH   = MAX (-1.0, MIN (THH, 1.0))
          TH    = MOD (2.0 * ACOS (THH) *  RGBL(6) + 360.0, 360.0)
          IF (TH > 180.0) TH = TH - 360.0
          CALL GEN008 (V5, V6, V1, 0)
          SHH   = SQRT (1.0 - THH **2)
          IF (SHH /= 0.0) THEN
            DO I = 1, 3
              V1(I) = (V1(I) + V5(I) * VAL + CTHH * V6(I)) / SHH
            END DO
          END IF
          CALL GEN002 (1, ROR, V1, V2, DUM)
          V2MAX = MAX (ABS (V2(1)), ABS (V2(2)), ABS (V2(3)))
          IF (V2MAX /= 0.0) THEN
            DO I = 1, 3
              V2(I) = V2(I) / V2MAX
            END DO
          END IF
          IF (LU == 1) WRITE (LU6, 99998, IOSTAT = IOST)
     1      TH, (V1(I), I = 1, 3), (V2(I), I = 1, 3)
          CALL PLA262 (8)
          WRITE (LU7, 99998, IOSTAT = IOST)
     1      TH, (V1(I), I = 1, 3), (V2(I), I = 1, 3)
        END IF
C * APPLY THE ROTATION FOUND TO ALL ATOMS OF RESD #1
        THH   = THETA / 2
        F1    = COS (THH)**2 - SIN (THH)**2
        F2    = SIN (THETA)
        F3    = 2 * SIN (THH)**2
        RMSQ  = 0.0
        URMS  = 0.0
        SUMW  = 0.0
        RMSQ1 = 0.0
        URMS1 = 0.0
        SUMW1 = 0.0
        NONHA = 0
        DO J = 1, NAT1, 2
          I    = JR(J)
          K    = JR(J + 1)
          WGHT = 0.0
          DO N = 1, 3
            IF (I == 0) THEN
              V1(N) = 0.0
            ELSE
              MODNM = MOD (N + M, 3)
              V1(N) =  (XXO(I, MODNM + 4) - DUMA(MODNM + 1)) * ISN
            END IF
            IF (K == 0) THEN
              V2(N) = 0.0
            ELSE
              V2(N) = XXO(K, N + 3) - DUMA(N + 3)
            END IF
            WGHT  = WGHT + V1(N)**2
          END DO
C * CALCULATE '2 * SIN(THETA/2)**2 (N.R)
          F4 = F3 * GEN009 (V, V1)
C * CALCULATE '(N x R)'
          CALL GEN008 (V, V1, V4, 0)
          DO N = 1, 3
            V3(N) = F1 * V1(N) + F2 * V4(N) + F4 * V(N)
          END DO
          DIST = (V2(1) - V3(1))**2 + (V2(2) - V3(2))**2
     1         + (V2(3) - V3(3))**2
C * STATISTICS FOR FITTED ATOMS ONLY
          IF (J < IPR(12)) THEN
            INCF = '*'
            RMSQ = RMSQ + WGHT * DIST
            SUMW = SUMW + WGHT
            URMS = URMS + DIST
          ELSE
            INCF = ' '
          END IF
C * STATISTICS FOR ALL NON-HYDROGEN ATOMS
          IF (I /= 0) THEN
            CALL GEN048 (-1, IFG(1, I), 7, IHAT)
            IF (IHAT == 0) THEN
              NONHA = NONHA + 1
              RMSQ1 = RMSQ1 + WGHT * DIST
              SUMW1 = SUMW1 + WGHT
              URMS1 = URMS1 + DIST
            END IF
            DIST = SQRT (DIST)
          END IF
          IF (ISN0 == ISN7) THEN
            IF (I /= 0) THEN
              CALL PLA047 (LABA(I), NQ1, IDUM, JDUM, IPR(71),
     1          IGBL(55), 0, 0)
              CALL PLA047 (LABA(I), NQ3, IDUM, JDUM, IPR(71),
     1          1, 0, 0)
            ELSE
              CALL GEN038 (NQ1, 1, 7)
              NQ3 = NQ1
            END IF
            IF (K /= 0) THEN
              CALL PLA047 (LABA(K), NQ2, IDUM, JDUM, IPR(71),
     1          IGBL(55), 0, 0)
            ELSE
              CALL GEN038 (NQ2, 1, 7)
            END IF
C * WRITE FITTED RESIDUE # 1 TO FIT-FILE
            IF (JR(J) /= 0 .AND. LU /= 0) THEN
              WRITE (LU60, 99992, IOSTAT = IOST)
     1          NQ1(1:7), NQ3(1:7), (V3(N), N = 1, 3)
            END IF
            WRITE (PRBUF, 99996, IOSTAT = IOST)
     1        NQ1(1:6), (V3(N), N = 1, 3),
     2        NQ2(1:6), (V2(N), N = 1, 3), DIST, INCF
            IF (I == 0) CALL GEN038 (PRBUF, 1, 32)
            IF (K == 0) CALL GEN038 (PRBUF, 35, 68)
            IF (I == 0 .OR. K == 0) CALL GEN038 (PRBUF, 70, 80)
            CALL PLA262 (1)
            IF (LU == 1) WRITE (LU6, 99989, IOSTAT = IOST) PRBUF(1:80)
            WRITE (LU7, 99989) PRBUF(1:80)
          END IF
        END DO
        URMS  = SQRT (URMS  / NATC)
        RMSQ  = SQRT (RMSQ  / SUMW)
        URMS1 = SQRT (URMS1 / NONHA)
        RMSQ1 = SQRT (RMSQ1 / SUMW1)
        IF (ISN0 == ISN7) THEN
          CALL PLA262 (5)
          IF (LU == 1)
     1      WRITE (LU6, 99995, IOSTAT = IOST) RMSQ, URMS, NATC,
     2        RMSQ1, URMS1, NONHA
          WRITE (LU7, 99995, IOSTAT = IOST)
     1      RMSQ, URMS, NATC, RMSQ1, URMS1, NONHA
        ELSE
          IF (RMSQ < BEST) THEN
            BEST = RMSQ
            ISNB = ISN
            MBST = M
          END IF
        END IF
      END DO
C * WRITE RESD # 2 TO FIT-FILE
      IF (LU /= 0) THEN
        WRITE (LU60, 99990, IOSTAT = IOST)
        DO I = 1, NAT2, 2
          K    = JR(I + 1)
          IF (K /= 0) THEN
            CALL PLA047 (LABA(K), NQ2, IDUM, JDUM, IPR(71),
     1        1, 0, 0)
            CALL PLA047 (LABA(K), NQ4, IDUM, JDUM, IPR(71),
     1        IGBL(55), 0, 0)
            WRITE (LU60, 99992, IOSTAT = IOST) NQ4(1:7), NQ2(1:7),
     1        (XXO(K, N) - DUMA(N), N = 4, 6)
          END IF
        END DO
        WRITE (LU60, 99997, IOSTAT = IOST)
        CLOSE (UNIT = LU60)
C * TEST FOR 'MENU ON' OR '-I MODE'
        IF (IGBL(25) /= 0 .OR. IGBL(3) == 41) THEN
          KERR = 0
C * RUN SPAWNED PLUTON JOB
          CALL SPAWN
     1    (PLAPATH(1:IGBL(80))//' -p '//NAMEFIL(1:KNMFIL)//'_fit.spf',
     2      LU6, .true., KERR)
        END IF
      END IF
      VARDIST = RMSQ
      RETURN
99999 FORMAT ('Molfit with Quaternion Transformation Method',
     1 ' (see: A.L. Mackay, Acta Cryst.(1984), A40, 165-166)', /,
     2 132('='), /)
99998 FORMAT ('Fit Rotation angle about (Pseudo)axis [l,m,n] = ',
     1  F10.2,  ' Degree', /,
     2  'Direction Cosines with Orthogonal Cell l,m,n  = ',
     3 3F10.6, /, 'Components in crystal system', 20X, 3F10.6, //,
     4 'Starred Atom Pairs are those used for the FIT. ',
     5 'Other Atoms are Paired on Sequence Number and need not to ',
     6 'Correspond.', //,  'Transf. Orthogonal Coord. Mol2', 5X,
     8 'Orth. Coord. Mol1 with Resp. to C.G.', 1X,
     9 'Dist (A)', /, 80('-'))
99997 FORMAT ('STRAW', /, 'COLOR RESD', /, 'OVERLAP MARGIN 0.0', /,
     1 'SET PAR 149 0.0', /, 'LABEL ON', /, 'PLOT')
99996 FORMAT (1X, 2(A, 1X, 3F8.3, 4X), F7.3, 1X, A)
99995 FORMAT (/, ':: Weighted and Unit Weight RMS-Fit: ',
     1  2F7.3 ,' Ang, No of Fitted Atoms:', I4, /,
     2        /, ':: Weighted and Unit Weight RMS-Fit: ',
     3  2F7.3 ,' Ang, No of Non-H  Atoms:', I4)
99994 FORMAT (':: FIT Inverted Resd', I2, '  on Resd', I2,
     1        ' gives the best fit', /)
99993 FORMAT (':: Residues are IDENTICAL', /)
99992 FORMAT ('ATOM', 1X, A, A, 3F10.3)
99991 FORMAT ('TITL ', A, ' - FIT RESD', I3, A, ' TO RESD', I3,
     1        ', N =', I3, /, 'RESD 1')
99990 FORMAT ('RESD 2')
99989 FORMAT (A)
      END SUBROUTINE PLA442
 
      SUBROUTINE PLA443 (FILEX)
C * Molecule FIT Following the KABSCH Algorithm
C * W. Kabsch: Acta Cryst. (1976). A32, 922 and (1978). A34, 827
C * Original Coding by  S.C.Nyburg (BMFIT)
C * This streamlined version for PLATON by A.L.Spek
      IMPLICIT NONE
      INTEGER, PARAMETER :: MB = 99
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: JX
      INTEGER :: NA
      INTEGER :: NB
      INTEGER :: NG
      INTEGER :: NP
      INTEGER :: NW
      INTEGER :: LU1
      INTEGER :: LU2
      INTEGER :: LU7
      INTEGER :: LU65
      INTEGER :: LU66
      INTEGER :: NAP
      INTEGER :: NBP
      INTEGER :: NUM
      INTEGER :: NWR
      INTEGER :: NSUM
      INTEGER :: NTOT
      INTEGER :: NMIR
      INTEGER :: NFIX
      INTEGER :: ITAP
      INTEGER :: NFIT
      INTEGER :: IOST
      DOUBLE PRECISION :: AN
      DOUBLE PRECISION :: BS
      DOUBLE PRECISION :: DS
      DOUBLE PRECISION :: XA
      DOUBLE PRECISION :: XB
      DOUBLE PRECISION :: XN
      DOUBLE PRECISION :: YA
      DOUBLE PRECISION :: YB
      DOUBLE PRECISION :: YN
      DOUBLE PRECISION :: ZA
      DOUBLE PRECISION :: ZB
      DOUBLE PRECISION :: ZN
      DOUBLE PRECISION :: A11
      DOUBLE PRECISION :: A12
      DOUBLE PRECISION :: A13
      DOUBLE PRECISION :: A21
      DOUBLE PRECISION :: A22
      DOUBLE PRECISION :: A23
      DOUBLE PRECISION :: A31
      DOUBLE PRECISION :: A32
      DOUBLE PRECISION :: A33
      DOUBLE PRECISION :: DPR
      DOUBLE PRECISION :: SES
      DOUBLE PRECISION :: DDET
      DOUBLE PRECISION :: DETA
      DOUBLE PRECISION :: DETR
      DOUBLE PRECISION :: FACS
      DOUBLE PRECISION, DIMENSION(2)     :: CA
      DOUBLE PRECISION, DIMENSION(2)     :: CB
      DOUBLE PRECISION, DIMENSION(2)     :: CG
      DOUBLE PRECISION, DIMENSION(2)     :: SG
      DOUBLE PRECISION, DIMENSION(2)     :: CR
      DOUBLE PRECISION, DIMENSION(2)     :: CP
      DOUBLE PRECISION, DIMENSION(3)     :: WV
      DOUBLE PRECISION, DIMENSION(9)     :: A
      DOUBLE PRECISION, DIMENSION(9)     :: R
      DOUBLE PRECISION, DIMENSION(MB)    :: D
      DOUBLE PRECISION, DIMENSION(MB)    :: W
      DOUBLE PRECISION, DIMENSION(2, 6)  :: RLC
      DOUBLE PRECISION, DIMENSION(3, 3)  :: CQ
      DOUBLE PRECISION, DIMENSION(3, 3)  :: U
      DOUBLE PRECISION, DIMENSION(3, 3)  :: ZZ
      DOUBLE PRECISION, DIMENSION(3, 3)  :: RC
      DOUBLE PRECISION, DIMENSION(3, 3)  :: B
      DOUBLE PRECISION, DIMENSION(2, MB) :: EX
      DOUBLE PRECISION, DIMENSION(2, MB) :: EY
      DOUBLE PRECISION, DIMENSION(2, MB) :: EZ
      DOUBLE PRECISION, DIMENSION(2, MB) :: FRX
      DOUBLE PRECISION, DIMENSION(2, MB) :: FRY
      DOUBLE PRECISION, DIMENSION(2, MB) :: FRZ
      DOUBLE PRECISION, DIMENSION(2, MB) :: XS
      DOUBLE PRECISION, DIMENSION(2, MB) :: YS
      DOUBLE PRECISION, DIMENSION(2, MB) :: ZS
      DOUBLE PRECISION, DIMENSION(2, MB) :: X
      DOUBLE PRECISION, DIMENSION(2, MB) :: Y
      DOUBLE PRECISION, DIMENSION(2, MB) :: Z
      CHARACTER(len=80) :: TITL
      CHARACTER(len=80) :: FILEX
      CHARACTER(len=8), DIMENSION(2, MB) :: TYPEX
C * INSTRUCTIONS    ON mol.ins    (LU1)
C * DATA FIRST MOL  ON mol.1      (LU65)
C * DATA SECOND MOL ON mol.2      (LU66)
C * RESULT          ON mol_bm.res (LU2)
C * LISTING         ON mol.lis    (LU7)
      LU1  = 1
      LU2  = 2
      LU7  = 7
      LU65 = 65
      LU66 = 66
      IOST = 0
      L = INDEX (FILEX, ' ') - 1
C * INSTRUCTION DATA
      OPEN (LU1, FILE = FILEX(1:L)//'.ins')
C * STRUCTURE 1 COORDINATES
      OPEN (LU65, FILE = FILEX(1:L)//'.1')
C * STRUCTURE 2 COORDINATES
      OPEN (LU66, FILE = FILEX(1:L)//'.2')
C * LISTING OUTPUT
      OPEN (LU7, FILE = FILEX(1:L)//'.lis')
C * FIT FILE
      OPEN (LU2, FILE = FILEX(1:L)//'_bm.res')
   10 READ (LU1, 99999, IOSTAT = IOST) TITL
      IF (IOST /= 0) RETURN
      DPR = 57.2957795D0
      DO I = 1, 9
        R(I) = 0.0D0
        A(I) = 0.0D0
      END DO
      DO I = 1, 3
        DO J = 1, 3
          CQ(I, J) = 0.0D0
        END DO
      END DO
      NMIR = 0
      NWR  = 0
      XA   = 0.0D0
      YA   = 0.0D0
      ZA   = 0.0D0
      DO I = 1, 2
        DO J = 1, MB
          X(I, J) = 0.0D0
          Y(I, J) = 0.0D0
          Z(I, J) = 0.0D0
        END DO
      END DO
      DS = 0.0D0
      JX = 0
C * N      # ATOMS TO BE FITTED (N <= MIN(NA,NB))
C * NFIX   SELECT ATOM AS ORIGIN             [0]
C * NFIT   (0/1) ANGSTROM / FRACTIOAL COORD FIT
C * NW     WEIGHT
      READ (LU1, *, IOSTAT = IOST) N, NFIX, NFIT, NW
C * READ THE DATA FOR THE TWO MOLECULES
      DO K = 1, 2
        IF (K == 1) THEN
          ITAP = LU65
        ELSE
          ITAP = LU66
        END IF
C * GET CELL PARAMETERS FOR BOTH MOLECULES
        READ (ITAP, *, IOSTAT = IOST) (RLC(K, I), I = 1, 6)
C * GET COS AND SIN VALUES OF THE CELL ANGLES
        CA(K) = COS (RLC(K, 4) / DPR)
        CB(K) = COS (RLC(K, 5) / DPR)
        CG(K) = COS (RLC(K, 6) / DPR)
        SG(K) = SQRT (1.0D0 - CG(K)**2)
        CR(K) = (CA(K) - CB(K) * CG(K)) / SG(K)
        CP(K) = SQRT (1.0D0 - CB(K) * CB(K) - CR(K) * CR(K))
        J    = 0
        DO
          J = J + 1
C * READ FRACTIONAL COORDINATES
          READ (ITAP, *, IOSTAT = IOST)
     1      TYPEX(K, J), FRX(K, J), FRY(K, J), FRZ(K, J)
          IF (IOST /= 0) EXIT
C * ORTHOGONALISE FRACTIONAL COORDINATES
          X(K, J) = FRX(K, J) * RLC(K, 1) + FRY(K, J) * RLC(K, 2) *
     1      CG(K) + FRZ(K, J) * RLC(K, 3) * CB(K)
          Y(K, J) = FRY(K, J) * RLC(K, 2) * SG(K) + FRZ(K, J) *
     1      RLC(K, 3) * CR(K)
          Z(K, J) = FRZ(K, J) * RLC(K, 3) * CP(K)
C * READ ASOCIATED WEIGHTS
          IF (NW > 0.0) THEN
            READ (ITAP, *) EX(K, J), EY(K, J), EZ(K, J)
C * ORTHOGONALISE WEIGHTS
            EX(K, J) = EX(K, J) * RLC(K, 1) + EY(K, J) * RLC(K, 2) *
     1        CG(K)  + EZ(K, J) * RLC(K, 3) * CB(K)
            EY(K, J) = EY(K, J) * RLC(K, 2) * SG(K) + EZ(K, J) *
     1        RLC(K, 3) * CR(K)
            EZ(K, J) = EZ(K, J) * RLC(K, 3) * CP(K)
            EX(K, J) = SQRT ((EX(K, J)**2 + EY(K, J)**2 +
     1        EZ(K, J)**2) / 3.0D0)
          ELSE
            W(J) = 1.0D0
          END IF
        END DO
        IF (K == 1) THEN
          NA = J - 1
        ELSE
          NB = J - 1
        END IF
      END DO
      NTOT = MAX (NA, NB)
C * FIND WEIGHT FOR EACH MATCHED ATOM PAIR
      IF (NW > 0) THEN
        SES = 0.0D0
        DO J = 1, N
          EX(1, J) = SQRT (EX(1, J)**2 + EX(2, J)**2)
          SES      = SES + (1.0D0 / (EX(1, J)**2))
        END DO
        AN = N
        AN = AN / SES
        DO J = 1, N
          W(J) = AN / (EX(1, J)**2)
        END DO
      END IF
C * LIST TITL AND CELL PARAMETER SETS
      WRITE (LU7, 99998) TITL
      IF (NW > 0) THEN
        WRITE (LU7, 99997)
      ELSE
        WRITE (LU7, 99996)
      END IF
      WRITE (LU7, 99995)
      WRITE (LU7, 99993) (RLC(1, L), L = 1, 3), (RLC(2, L), L = 1, 3)
      WRITE (LU7, 99992) (RLC(1, L), L = 4, 6), (RLC(2, L), L = 4, 6)
      DO
        IF (JX == 0) THEN
C * LIST ORTHOGOGONAL (ANGSTROM) COORDINATES
          WRITE (LU7, 99966) (K, TYPEX(1, K), X(1, K), Y(1, K), Z(1, K),
     1      TYPEX(2, K), X(2, K),Y(2, K), Z(2, K), K = 1, N)
        ELSE IF (JX > 0) THEN
          DS   = 0.0D0
          NSUM = MIN (NA, NB)
          DO K = 1, NSUM
            D(K) = (X(1, K) - X(2, K))**2 + (Y(1, K) - Y(2, K))**2 +
     1             (Z(1, K) - Z(2, K))**2
          END DO
          DO K = 1, N
            DS = DS + D(K)
          END DO
          DO K = 1, NSUM
            D(K) = SQRT (D(K))
          END DO
          WRITE (LU7, 99962)
          WRITE (LU7, 99980) (K, TYPEX(1, K), X(1, K), Y(1, K), Z(1, K),
     1      TYPEX(2, K), X(2, K), Y(2, K), Z(2, K), D(K), K = 1, N)
          WRITE (LU7, 99964) DS
        END IF
C * REPORT UNMATCHED ATOM PAIRS
        WRITE (LU7, 99963)
C * TYPE OF FORMAT
        IF (NA /= N) THEN
          IF ((NB == N)) THEN
C * OUTPUT ROUTINE F2
            NAP = N + 1
            WRITE (LU7, 99977) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1       Z(1, K), K = NAP, NA)
          ELSE
C * OUTPUT ROUTINE F5
            IF (NA < NB) THEN
              NP  = N + 1
              NAP = NA + 1
              IF (JX == 0) THEN
                WRITE (LU7, 99978) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1           Z(1, K), TYPEX(2, K), X(2, K), Y(2, K), Z(2, K),
     2           K = NP, NA)
                WRITE (LU7, 99979) (K, TYPEX(2, K), X(2, K), Y(2, K),
     1            Z(2, K), K = NAP, NB)
              ELSE
                WRITE (LU7, 99980) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1            Z(1, K), TYPEX(2, K), X(2, K), Y(2, K), Z(2, K),
     2           D(K), K = NP, NA)
                WRITE (LU7, 99979) (K, TYPEX(2, K), X(2, K), Y(2, K),
     1            Z(2, K), K = NAP, NB)
              END IF
            ELSE IF (NA == NB) THEN
C * OUTPUT ROUTINE F6
              NP = N + 1
              IF (JX == 0) THEN
                WRITE (LU7, 99978) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1           Z(1, K), TYPEX(2, K), X(2, K), Y(2, K), Z(2, K),
     2           K = NP, NA)
              ELSE
                WRITE (LU7, 99980) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1            Z(1, K), TYPEX(2, K), X(2, K), Y(2, K), Z(2, K),
     2            D(K), K = NP, NA)
              END IF
            ELSE IF (NA > NB) THEN
C * OUTPUT ROUTINE F4
              NP  = N + 1
              NBP = NB + 1
              IF(JX == 0) THEN
                WRITE (LU7, 99978) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1            Z(1, K), TYPEX(2, K), X(2, K), Y(2, K), Z(2, K),
     2            K  = NP, NB)
                WRITE (LU7, 99977) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1            Z(1, K), K = NBP, NA)
              ELSE
                WRITE (LU7, 99980) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1            Z(1, K), TYPEX(2, K), X(2, K), Y(2, K), Z(2, K),
     2            D(K), K = NP, NB)
                WRITE (LU7, 99977) (K, TYPEX(1, K), X(1, K), Y(1, K),
     1            Z(1, K), K = NBP, NA)
              END IF
            END IF
          END IF
        ELSE
          IF (NB == N) THEN
            WRITE (LU7, 99991)
          ELSE
C * OUTPUT ROUTINE
            NBP = N + 1
            WRITE (LU7, 99979) (K, TYPEX(2, K), X(2, K), Y(2, K),
     1        Z(2, K), K = NBP, NB)
          END IF
        END IF
        IF (JX > 0) THEN
C * THIS FINAL SECTION PERFORMS THE TRANSFORMATION OF 2ND MOLECULE INT
C * THE FRACTIONAL COORDINATES OF THE FIRST.
C * IF THIS IS REQUIRED, PUT NFIT=1.  OTHERWISE NFIT=0.
          IF (NFIT /= 0) THEN
C * BRING 2ND MOLECULE BACK TO SAME CRYSTAL FRAME AS 1ST MOLECULE
C * MOVE 2ND MOLECULE TO CENTROID OF 1ST MOLECULE IN ITS ORIGINAL POSI
            DO NG = 1, NB
              X(2, NG) = X(2, NG) + XA
              Y(2, NG) = Y(2, NG) + YA
              Z(2, NG) = Z(2, NG) + ZA
            END DO
C * INVERSE MATRIX TO BRING TO FRACTIONAL COORDS
            DO K = 1, NB
              X(2, K) = (X(2, K) - (Y(2, K) * CG(1) / SG(1))
     1                + (Z(2, K) / CP(1)) * ((CR(1) * CG(1) / SG(1)) -
     2                  CB(1))) / RLC(1, 1)
              Y(2, K) = (Y(2, K) / SG(1) - ((Z(2, K) * CR(1)) / (CP(1) *
     1                  SG(1)))) / RLC(1, 2)
              Z(2, K) = Z(2, K) / (CP(1) * RLC(1, 3))
            END DO
            WRITE (LU7, 99983)
            NUM = MIN (NA, NB)
C * CREATE (PSEUDO) RES FILE
            WRITE (LU2, 99970) TITL
            WRITE (LU2, 99969) 1.5418, (RLC(1, I), I = 1, 6)
            WRITE (LU2, 99999) 'LATT -1'
            WRITE (LU2, 99999) 'SET PAR 22 0.0001'
            WRITE (LU2, 99999) 'FVAR 1'
            WRITE (LU2, 99999) 'RESD 1'
            WRITE (LU2, 99999) 'PART 1'
            WRITE (LU2, 99971) (TYPEX(1, M), 1, FRX(1, M), FRY(1, M),
     1        FRZ(1, M), 11.0, 0.05, M = 1, NUM)
            WRITE (LU2, 99999) 'RESD 2'
            WRITE (LU2, 99999) 'PART 2'
            WRITE (LU2, 99971) (TYPEX(2, M), 1, X(2, M), Y(2, M),
     1        Z(2, M), 11.0, 0.05, M = 1, NUM)
            WRITE (LU2, 99961)
            WRITE (LU2, 99999) 'HKLF4'
            WRITE (LU2, 99999) 'ENDS'
            WRITE (LU7, 99975) (M, TYPEX(1, M), FRX(1, M), FRY(1, M),
     1        FRZ(1, M), TYPEX(2, M), X(2, M), Y(2, M), Z(2, M),
     2        M = 1, NUM)
            IF (NA < NB) THEN
              NAP = NA + 1
              WRITE (LU7, 99974) (M, TYPEX(2, M), X(2, M), Y(2, M),
     1          Z(2, M), M = NAP, NB)
            ELSE IF (NA > NB) THEN
              NBP = NB +1
              WRITE (LU7, 99973) (M, TYPEX(1, M), FRX(1, M), FRY(1, M),
     1         FRZ(1, M), M = NBP, NA)
            END IF
          END IF
          IF (NMIR == 1) GO TO 10
          NWR = NWR + 1
          IF (NWR == 2) GO TO 10
        ELSE
          WRITE (LU7, 99981)
          WRITE (LU7, 99989)
C * FIND PAIR-WEIGHTED CENTROIDS OF MOLECULES
          IF (NFIX == 0) THEN
            XA = 0.0D0
            YA = 0.0D0
            ZA = 0.0D0
            XB = 0.0D0
            YB = 0.0D0
            ZB = 0.0D0
            AN = N
            DO K  = 1, N
              XA = XA + X(1, K) * W(K) / AN
              YA = YA + Y(1, K) * W(K) / AN
              ZA = ZA + Z(1, K) * W(K) / AN
              XB = XB + X(2, K) * W(K) / AN
              YB = YB + Y(2, K) * W(K) / AN
              ZB = ZB + Z(2, K) * W(K) / AN
            END DO
          ELSE
            XA = X(1, NFIX)
            YA = Y(1, NFIX)
            ZA = Z(1, NFIX)
            XB = X(2, NFIX)
            YB = Y(2, NFIX)
            ZB = Z(2, NFIX)
          END IF
C * OUTPUT CENTROIDS
          WRITE (LU7, 99976) XA, YA, ZA, XB, YB, ZB
          IF (NW /= 0) THEN
            WRITE (LU7, 99997)
          ELSE
            WRITE (LU7, 99996)
          END IF
C * MOVE CENTROIDS TO ORIGIN
          DO K  = 1, NTOT
            X(1,  K) = X(1, K) - XA
            Y(1,  K) = Y(1, K) - YA
            Z(1,  K) = Z(1, K) - ZA
            X(2,  K) = X(2, K) - XB
            Y(2,  K) = Y(2, K) - YB
            Z(2,  K) = Z(2, K) - ZB
            XS(2, K) = X(2, K)
            YS(2, K) = Y(2, K)
            ZS(2, K) = Z(2, K)
          END DO
          DO I = 1, 3
            DO K = 1, 3
              CQ(I, K) = 0.0D0
            END DO
          END DO
C * CALCULATE MATRIX 'R'   (Kabsch Notation)
          DO I = 1, N
            CQ(1, 1) = CQ(1, 1) + X(1, I) * X(2, I) * W(I)
            CQ(1, 2) = CQ(1, 2) + Y(1, I) * X(2, I) * W(I)
            CQ(1, 3) = CQ(1, 3) + Z(1, I) * X(2, I) * W(I)
            CQ(2, 1) = CQ(2, 1) + X(1, I) * Y(2, I) * W(I)
            CQ(2, 2) = CQ(2, 2) + Y(1, I) * Y(2, I) * W(I)
            CQ(2, 3) = CQ(2, 3) + Z(1, I) * Y(2, I) * W(I)
            CQ(3, 1) = CQ(3, 1) + X(1, I) * Z(2, I) * W(I)
            CQ(3, 2) = CQ(3, 2) + Y(1, I) * Z(2, I) * W(I)
            CQ(3, 3) = CQ(3, 3) + Z(1, I) * Z(2, I) * W(I)
          END DO
C * CALCULATE MATRIX 'R~R'  (Kabsch Notation)
          A(1) = CQ(1, 1) * CQ(1, 1) + CQ(1, 2) * CQ(1, 2) +
     1           CQ(1, 3) * CQ(1, 3)
          A(2) = CQ(1, 1) * CQ(2, 1) + CQ(1, 2) * CQ(2, 2) +
     1           CQ(1, 3) * CQ(2, 3)
          A(4) = CQ(1, 1) * CQ(3, 1) + CQ(1, 2) * CQ(3, 2) +
     1           CQ(1, 3) * CQ(3, 3)
          A(3) = CQ(2, 1) * CQ(2, 1) + CQ(2, 2) * CQ(2, 2) +
     1           CQ(2, 3) * CQ(2, 3)
          A(5) = CQ(2, 1) * CQ(3, 1) + CQ(2, 2) * CQ(3, 2) +
     1           CQ(2, 3) * CQ(3, 3)
          A(6) = CQ(3, 1) * CQ(3, 1) + CQ(3, 2) * CQ(3, 2) +
     1           CQ(3, 3) * CQ(3, 3)
C * DOUBLE-PRECISION EIGENVECTOR AND EIGENVALUE CALCULATION
          CALL GEN161 (A, R)
          JX   = 1
          NWR  = 0
          NMIR = 0
          DETA = 0
        END IF
        DO I = 1, 3
          DO J = 1, 3
            U(I, J) = 0.0D0
          END DO
        END DO
        IF (NWR == 0) THEN
C * COPY EIGENVALUES
          WV(1)    = A(1)
          WV(2)    = A(3)
          WV(3)    = A(6)
C * COPY EIGENVECTORS
          ZZ(1, 1) = R(1)
          ZZ(1, 2) = R(2)
          ZZ(1, 3) = R(3)
          ZZ(2, 1) = R(4)
          ZZ(2, 2) = R(5)
          ZZ(2, 3) = R(6)
          ZZ(3, 1) = R(7)
          ZZ(3, 2) = R(8)
          ZZ(3, 3) = R(9)
          DO I = 1, 3
            DO J = 1, 3
              B(I, J)  = 0.0D0
              RC(I, J) = CQ(J, I)
            END DO
           END DO
C * MAKE SURE DET OF RC IS NOT EXACTLY ZERO
          DETR = RC(1, 1) * RC(2, 2) * RC(3, 3)
     1         - RC(1, 1) * RC(2, 3) * RC(3, 2)
     2         + RC(1, 2) * RC(2, 3) * RC(3, 1)
     3         - RC(1, 2) * RC(2, 1) * RC(3, 3)
     4         + RC(1, 3) * RC(2, 1) * RC(3, 2)
     5         - RC(1, 3) * RC(2, 2) * RC(3, 1)
C * CALCULATE MATRIX 'U'  (Kabsch Notation)
          WRITE (LU7, 99968) DETR
          IF (ABS (DETR) >= 0.0001D0) THEN
            DO K = 1, 3
              DO I = 1, 3
                DO J = 1, 3
                  B(K, I) = B(K, I) + RC(I, J) * ZZ(K, J)
                END DO
              END DO
            END DO
          ELSE
C * HANDLE SPECIAL 2 And 1 DIMENSIONAL CASES
            NMIR = 1
            IF (WV(2) < 1.0D-6) THEN
              DO I = 1, 3
                DO J = 1, 3
                  B(1, I) = B(1, I) + RC(I, J) * ZZ(1, J)
                END DO
              END DO
              FACS = 1.0D0 / (B(1, 1)**2 + B(1, 2)**2 + B(1,3)**2)
              DO J = 1, 3
                B(1, J) = SQRT (FACS) * B(1,J)
              END DO
              IF (B(1, 1) /= 0.0D0) THEN
                IF (B(1, 2) == 0.0D0) THEN
                  B(2, 1) = 0.0D0
                  B(2, 2) = 1.0D0
                  B(2, 3) = 0.0D0
                ELSE
                  B(2, 2) = B(1, 1) / SQRT (B(1, 1)**2 + B(1, 2)**2)
                  B(2, 1) = -(B(1, 2) * B(2, 2)) / B(1,1)
                  B(2, 3) = 0.0D0
                END IF
              ELSE
                B(2, 1) = 1.0D0
                B(2, 2) = 0.0D0
                B(2, 3) = 0.0D0
              END IF
              B(3, 1) = B(1, 2) * B(2, 3) - B(1, 3) * B(2, 2)
              B(3, 2) = B(1, 3) * B(2, 1) - B(1, 1) * B(2, 3)
              B(3, 3) = B(1, 1) * B(2, 2) - B(1, 2) * B(2, 1)
              GOTO 20
            ENDIF
            DO K = 1, 2
              DO I = 1, 3
                DO J = 1, 3
                  B(K, I) = B(K, I) + RC(I, J) * ZZ(K, J)
                END DO
              END DO
            END DO
            B(3, 1) = B(1, 2) * B(2, 3) - B(1, 3) * B(2, 2)
            B(3, 2) = B(1, 3) * B(2, 1) - B(2, 3) * B(1, 1)
            B(3, 3) = B(1, 1) * B(2, 2) - B(2, 1) * B(1, 2)
          END IF
          BS = B(1, 1)**2 + B(1, 2)**2 + B(1, 3)**2
          IF (BS /= 0.0D0) THEN
            FACS = 1.0D0 / (B(1, 1)**2 + B(1, 2)**2 + B(1, 3)**2)
            DO J = 1, 3
              B(1, J) = SQRT (FACS) * B(1, J)
            END DO
          END IF
          BS = B(2, 1)**2 + B(2, 2)**2 + B(2,3)**2
          IF (BS /= 0.0D0) THEN
            FACS = 1.0D0 / (B(2, 1)**2 + B(2, 2)**2 + B(2, 3)**2)
            DO J = 1, 3
              B(2, J) = SQRT (FACS) * B(2, J)
            END DO
          END IF
          BS = B(3, 1)**2 + B(3, 2)**2 + B(3, 3)**2
          IF (BS /= 0.0D0) THEN
            FACS = 1.0D0 / (B(3, 1)**2 + B(3, 2)**2 + B(3, 3)**2)
            DO J = 1, 3
              B(3, J) = SQRT (FACS) * B(3, J)
            END DO
          END IF
        ELSE
          B(3, 1) = - B(3, 1)
          B(3, 2) = - B(3, 2)
          B(3, 3) = - B(3, 3)
        END IF
   20   DO I = 1, 3
          DO J = 1, 3
            DO K = 1, 3
              U(I, J) = U(I, J) + B(K, I) * ZZ(K, J)
            END DO
          END DO
        END DO
        A(1) = U(1, 1)
        A(2) = U(1, 2)
        A(3) = U(1, 3)
        A(4) = U(2, 1)
        A(5) = U(2, 2)
        A(6) = U(2, 3)
        A(7) = U(3, 1)
        A(8) = U(3, 2)
        A(9) = U(3, 3)
C * IS A MATRIX ORTHOGONAL?
        A11 = A(1) * A(1) + A(2) * A(2) + A(3) * A(3)
        A12 = A(1) * A(4) + A(2) * A(5) + A(3) * A(6)
        A13 = A(1) * A(7) + A(2) * A(8) + A(3) * A(9)
        A21 = A(4) * A(1) + A(5) * A(2) + A(6) * A(3)
        A22 = A(4) * A(4) + A(5) * A(5) + A(6) * A(6)
        A23 = A(4) * A(7) + A(5) * A(8) + A(6) * A(9)
        A31 = A(7) * A(1) + A(8) * A(2) + A(9) * A(3)
        A32 = A(7) * A(4) + A(8) * A(5) + A(9) * A(6)
        A33 = A(7) * A(7) + A(8) * A(8) + A(9) * A(9)
        WRITE (LU7, 99967) A11, A12, A13
        WRITE (LU7, 99967) A21, A22, A23
        WRITE (LU7, 99967) A31, A32, A33
        DETA = A(1) * A(5) * A(9) - A(1 ) *A(6) * A(8) + A(2) * A(6) *
     1    A(7) - A(2) * A(4) * A(9) + A(3) * A(4) * A(8) -
     2    A(3) * A(5) * A(7)
        IF (NWR == 0) THEN
          IF (NMIR == 1) THEN
            WRITE (LU7, 99984)
          ELSE
            IF(DETA >= 0.0D0) THEN
              WRITE (LU7, 99988)
            ELSE
              WRITE (LU7, 99987)
            END IF
          END IF
          DDET = DETA
          GO TO 30
        END IF
        IF (DDET >= 0.0D0) THEN
          WRITE (LU7, 99986)
        ELSE
          WRITE( LU7, 99985)
        END IF
   30   DO I = 1, NB
          XN = A(1) * XS(2, I) + A(2) * YS(2, I) + A(3) * ZS(2, I)
          YN = A(4) * XS(2, I) + A(5) * YS(2, I) + A(6) * ZS(2, I)
          ZN = A(7) * XS(2, I) + A(8) * YS(2, I) + A(9) * ZS(2, I)
          X(2, I) = XN
          Y(2, I) = YN
          Z(2, I) = ZN
        END DO
      END DO
      CLOSE (UNIT = LU1)
      CLOSE (UNIT = LU2)
      CLOSE (UNIT = LU7)
      CLOSE (UNIT = LU65)
      CLOSE (UNIT = LU66)
      RETURN
99999 FORMAT (A)
99998 FORMAT (A, //)
99997 FORMAT (31X, 'THIS IS A WEIGHTED FIT', /)
99996 FORMAT (30X, 'THIS IS AN UNWEIGHTED FIT',/)
99995 FORMAT (25X, 'ORTHOGONAL COORDINATES OF ATOMS BEFORE MATCHING', /,
     1        21X, 'FIRST MOLECULE', 35X, 'SECOND MOLECULE', /)
99993 FORMAT (3X, 'A =', F9.4, ' B =', F9.4, ' C =', F9.4, 14X,
     1            'A =', F9.4, ' B =', F9.4, ' C =', F9.4)
99992 FORMAT (3X, 'AL=', F9.3, ' BE=', F9.3, ' GA=', F9.3, 14X,
     1            'AL=', F9.3, ' BE=', F9.3, ' GA=', F9.3, //)
99991 FORMAT (29X, 'NONE', /)
99989 FORMAT (22X, 'CENTROID', 31X, 'CENTROID', /)
99988 FORMAT (20X, 'THE BEST FIT IS GIVEN WITH THE SECOND MOLECULE',
     1        ' UN-MIRRORED', /)
99987 FORMAT (20X, 'THE BEST FIT IS GIVEN WITH THE SECOND MOLECULE',
     1        ' MIRRORED', /)
99986 FORMAT (35X, 'THIS IS THE MIRRORED FIT', //)
99985 FORMAT (20X, 'THIS IS THE FIT WITH THE SECOND MOLECULE',
     1        ' UN-MIRRORED', /)
99984 FORMAT (1X, 'EITHER ONE OF THE MOLECULES IS FLAT OR THE FIT IS',
     1        ' THE SAME WHETHER OR NOT THE 2ND MOLECULE IS MIRRORED',
     2        /)
99983 FORMAT (//,'   NO', 4X, ' ATOM ', 6X, 'FRACT. COORDINATES', 11X,
     1        ' ATOM   FRACT. COORDS. OF 2ND MOLECULE', /, 23X,
     2        'FIRST MOLECULE', 31X, 'IN CELL OF FIRST')
99981 FORMAT (/)
99980 FORMAT (I4, 1X,  A, 3F10.6, 3X, A, 4F10.6)
99979 FORMAT (I4, 39X, A, 3F10.6)
99978 FORMAT (I4, 1X,  A, 3F10.6, 3X, A, 3F10.6)
99977 FORMAT (I4, 1X,  A, 3F10.6)
99976 FORMAT (10X, 3F10.6, 9X, 3F10.6, /)
99975 FORMAT (I4, 5X,  A, 3F10.6, 5X, A, 3F10.6)
99974 FORMAT (I4, 46X, A, 3F10.6)
99973 FORMAT (I4, 5X,  A, 3F10.6)
99971 FORMAT (A, I3, 3F10.4, F8.1, F8.2)
99970 FORMAT ('TITL ', A)
99969 FORMAT ('CELL ', 7F10.4)
99968 FORMAT (/, '   VALUE OF DETERMINANT', E14.4)
99967 FORMAT (/, 20X, 3E14.4, /)
99966 FORMAT (I4, 1X, A, 3F10.6, 12X, A, 3F10.6)
99964 FORMAT (/, 35X, 'SUM OF DIFFERENCES SQUARED', 23X, F10.6, /)
99963 FORMAT (/, 41X, 'UNMATCHED ATOMS', /)
99962 FORMAT (89X, 'DELTA', /)
99961 FORMAT ('STRAW', /, 'COLOR RESD', /, 'OVERLAP MARGIN 0.0', /,
     1 'SET PAR 149 0.0', /, 'LABEL ON', /, 'PLOT')
      END SUBROUTINE PLA443
 
      SUBROUTINE PLA450 (INQNR)
C * INVESTIGATE THE PARAMETERS OF A (POTENTIALLY) NEW ATOM RECORD
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: MN
      INTEGER :: IVL
      INTEGER :: ISU
      INTEGER :: ISK
      INTEGER :: NAT
      INTEGER :: IHAT
      INTEGER :: JHAT
      INTEGER :: JSYM
      INTEGER :: KNP1
      INTEGER :: NSYM
      INTEGER :: NPOP
      INTEGER :: NIEN
      INTEGER :: IENM
      INTEGER :: IHYD
      INTEGER :: IENR
      INTEGER :: IPOP
      INTEGER :: IDUM
      INTEGER :: MULT
      INTEGER :: MULTX
      INTEGER :: IENM1
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: ITRNS
      INTEGER, SAVE :: IATYC
      INTEGER, SAVE :: IATYO
      INTEGER, SAVE :: IATYN
      INTEGER :: INTPOP
      INTEGER :: IPOPRES
      REAL :: VERS
      REAL :: XLNG
      REAL :: FNK4
      REAL :: FNMAX
      REAL :: FNMIN
      REAL :: RATIO
      REAL :: RGBL25
      REAL :: POPPARX
      ISU  = 0
      IENR = 0
      IHYD = 0
C * ZERO SKIP-TEST
      IPR(107) = 0
C * DELETE FROM INPUT CRITERIUM
      RGBL25 = MAX (0.05, RGBL(25))
C * GET ATOM LABEL AT POSITION IPR(473) IN ATOM RECORD
      NQ1 = IFL(IPR(473))
C * GET NUMBER OF NON-NUMERICAL ENTRIES ON INPUT RECORD
      KL = IPR(220)
C * GET NUMBER OF NUMERICAL ENTRIES ON INPUT RECORD
      KN = IPR(221)
C * GET NUMBER OF SYMMETRY OPERATIONS
      NSYM = IPR(48)
C * GET NUMBER OF CURRENTLY ACCEPTED ATOMS
      NAT = IPR(39)
C * INIT FLAG ARRAY FOR NEW ATOM
      DO I = 1, 3
        IFG(I, NAT + 1) = 0
      END DO
C * SET PACKING PARAMETERS FOR INTERNAL NUMERICAL LABEL REPRESENTATION
      IF (NAT == 0) THEN
        IPR(463) = 128
        IPR(464) = 51200000
        IPR(465) = 400000
        IPR(466) = IPR(465) * 2
C * DO CELL PARAMETER CALCULATION BEFORE FIRST ATOM RECORD
        IF (IPR(23) == 0) CALL PLA100
C * CHECK FOR PROPER CELL DIMENSIONS
        IF (PAR(101) < 1.1 .AND. IPR(23) == 0) THEN
C * ERROR MESSAGE CODE
          IPR(2) = 58
          RETURN
        END IF
        IGBL(59) = 0
        IATYC    = 0
        IATYO    = 0
        IATYN    = 0
C * CHECK FOR ABSENCE OF EXPLICIT SYMMETRY
        IF (IPR(319) == 0) THEN
C * ALERT _124 - PROBLEM WITH EQUIVALENT POSITIONS
          CALL PLA236 (124, 0, 1.0, 1.0, CCIF(7)(1:7), ' ')
          IF (SPGRNM(1)(1:1) == ' ') THEN
C * ALERT _121 - INVALID SPACE GROUP
            CALL PLA236 (121, 0, 1.0, 1.0, CCIF(6), ' ')
C * INIT SPACE GROUP SYMMETRY TO P1
            CALL SGSM (1, IDM, SGY, 0, 0, IERR)
            IPR(48) = 1
          END IF
        END IF
C * CATCH ATTEMPT TO EXCEED MAX NUMBER OF ATOMS LIMIT
      ELSE IF (NAT > NP1 - 2) THEN
C * ERROR MESSAGE CODE
        IPR(2) = 1
        RETURN
      END IF
C * CHECK FOR AND HANDLE CIF STYLE INPUT (IGBL(8) = 3)
      IF (IGBL(8) == 3) THEN
        CALL PLA454 (KL, KN, NAT, IHYD, IENM1, INQNR, JNQNR, NIEN)
        IF (IPR(2) /= 0) RETURN
C * CHECK FOR AND HANDLE RES STYLE INPUT (IGBL(8) = 2)
      ELSE IF (IGBL(8) == 2) THEN
C * HANDLE SPECIAL L-LABELS (IDEAL)
        IF (NQ1(1:1) == 'L') THEN
          DO I = 1, 10
            IF (NQ1(2:2) == CHAR (ICHAR ('0') + I - 1)) RETURN
          END DO
        END IF
C * FIRST CHECK WHETHER ALPHANUMERIC ITEM IPR(473) IS AN ATOM LABEL
C * ADD RESIDUE NUMBER TO LABEL
        IF (IPR(538) /= 0) THEN
          N = INDEX (NQ1, ' ')
          IF (N /= 0) THEN
            IF (IPR(538) < 10) THEN
              WRITE (NQ1(N:N + 1), 99997, IOSTAT = IOST) IPR(538)
            ELSE
              WRITE (NQ1(N:N + 2), 99996, IOSTAT = IOST) IPR(538)
            END IF
          END IF
          IFL(IPR(473)) = NQ1
        END IF
C * GET NUMERICAL REPRESENTATION FOR THE LABEL IN NQ1
        CALL PLA453 (IENM1, INQNR, JNQNR, NIEN, IHYD)
        IF (IPR(2) /= 0) RETURN
        ISK = 0
        CALL PLA452 (KN, IENR, ISK)
        IF (ISK /= 0 .OR. IPR(2) /= 0) RETURN
C * HANDLE SHELXL/CIF ISSUE
        IF (FN(24) == 1.0 .AND. FN(8) == 0.0) THEN
          IF (FN(4) == 0.330) FN(4) = 0.33333
          IF (FN(4) == 0.670) FN(4) = 0.66667
        END IF
C * IGBL(8) = 1 (SPF) OR IGBL(8) = 4 (PDB)
      ELSE
C * GET NUMERICAL REPRESENTATION FOR THE LABEL IN NQ1
        CALL PLA453 (IENM1, INQNR, JNQNR, NIEN, IHYD)
        IF (IPR(2) /= 0) RETURN
C * HANDLE SPECIAL CASE OF SHELX INPUT STYLE (AS PRODUCED BY SHELX)
        IF (KN == 5) KN = 3
C * COMPLETE WITH ZERO'S
        KNP1 = KN + 1
        CALL GEN074 (FN, KNP1, 9, 0.0)
        IF (KN == 6) THEN
C * SHIFT ESD'S
          DO K = 1, 4
            FN(9 - K) = FN(8 - K)
          END DO
          FN(4) = 0.0
        END IF
C * HANDLE ANGSTROM SCALING (DEFAULT 1.0)
        IF (IPR(23) == 1) THEN
          ISU = 0
          DO K = 1, 3
            FN(K)     = FN(K)     * PAR(11)
            FN(K + 4) = FN(K + 4) * PAR(11)
            IF (FN(K + 4) > 0) ISU = 1
          END DO
        END IF
      END IF
C * APPLY CELL TRANSFORMATION
      CALL GEN002 (1, TM2, FN, SGY, XLNG)
      DO K = 1, 3
        DUMA(K) = 0.0
        FNK4    = FN(K + 4)
        IF (FNK4 > 0.0) IPR(72) = 1
        IF (FNK4 < 0.0) FNK4    = 0.0
        FN(K + 4) = FNK4**2
      END DO
      DO K = 1, 3
        IF (IPR(23) == 0) THEN
          DO L = 1, 3
            DUMA(K) = DUMA(K) + TM2(K, L)**2 * FN(L + 4)
          END DO
        ELSE
          DUMA(K) = FN(K + 4)
        END IF
      END DO
      DO K = 1, 3
C * ADD SHIFT VECTOR
        SGY(K)              = SGY(K) + SHFT(K)
        FN(K)               = SGY(K)
        FN(K + 4)           = SQRT (DUMA(K))
        SGY(K + 3)          = 0.0
        CON(NAT + 1, K + 2) = FN(K)
        CON(NAT + 1, K + 5) = DUMA(K)
        CON(NAT + 2, K + 2) = 0.0
        MULTX               = 0
      END DO
C * SKIP THIS SECTION FOR ANGSTROM DATA (IPR(23) = 1)
      IF (IPR(23) == 1) THEN
        MULT = 1
      ELSE
        MULT = 0
        IF (IGBL(74) > 0) THEN
          WRITE (LU6,'(A, 6F10.4, /, 7X, 5F10.4)') NQ1(1:7),
     1    (FN(I), I = 1,4), FN(9), FN(11), (FN(I), I = 5, 8), FN(10)
        END IF
        SGY(10) = 0.0
        CALL SGSM (19, IDM, SGY, 0, LU6, IERR)
C * HANDLE MULTIPLICITY ARTIFACT (CIF/PDB..)
        IF (IGBL(8) == 3) THEN
          IF (SGY(10) /= 1.0 .AND. IPR(612) >= 0) THEN
            FN(4) = FN(4) * SGY(10)
            IF (FN(8) > 0.0) FN(8) = FN(8) * SGY(10)
          END IF
C * CHECK FOR SU (EXCLUDING H-ATOMS & CSD-CIF FILES)
          IF (IHYD == 0 .AND. IGBL(94) == 0) THEN
C * ALERT _161
C * ALERT _162
C * ALERT _163
            FNMIN = MIN (FN(5) * PAR(101), FN(6) * PAR(102),
     1        FN(7) * PAR(103))
            IF (FNMIN > 0.0) THEN
              FNMAX = MAX (FN(5) * PAR(101), FN(6) * PAR(102),
     1          FN(7) * PAR(103))
C * ALERT _160
              RATIO = FNMAX / FNMIN
              IF (RATIO > 3.0) THEN
                IF (RATIO <= 10.0) THEN
                  CALL PLA236 (160, 2, -999.0, RATIO, NQ2, ' ')
                ELSE
                  CALL PLA236 (160, 2, RATIO, RATIO, NQ2, ' ')
                END IF
              END IF
            END IF
          END IF
        END IF
C * MARK (H)ATOMS IN GENERAL POSITIONS WITHOUT SU
        IF (IHYD == 0) THEN
          IF (SGY(10) == 1.0) THEN
            ISU = 1
            IF (FN(5) <= 0.0 .AND. FN(6) <= 0.0 .AND.
     1          FN(7) <= 0.0) ISU = 0
          ELSE
            ISU = 0
            IF (FN(5) > 0.0 .OR. FN(6) > 0.0 .OR. FN(7) > 0)
     1        ISU = 1
          END IF
        ELSE
          ISU = 0
          IF (FN(5) > 0.0 .OR. FN(6) > 0.0 .OR. FN(7) > 0)
     1      ISU = 1
        END IF
C * TAKE PART -N INTO ACCOUNT
        IF (IGBL(8) == 3 .AND. IPR(612) < 0) THEN
          IPR(696) = IPR(696) + 1
          MULT = 1
        ELSE
          IF (ABS(FN(4) / SGY(10) - 0.5) > 0.4998) THEN
C * LOOP OVER ALL SYMMETRY OPERATIONS
            DO J = 1, NSYM
              JSYM = J
              CALL SGSM (3, ICL, SGY, JSYM, LU7, IERR)
C * LOOP OVER CURRENT SET OF ACCEPTED ATOMS + TENTATIVE NEW ONE
              DO I = 1, NAT + 1
                VERS = 0.0
                DO K = 1, 3
                  DUMA(K) = CON(I, K + 2) - SGY(K + 6)
                  DO WHILE (DUMA(K) > 0.5)
                    SGY(K + 6) = SGY(K + 6) + 1.0
                    DUMA(K)    = DUMA(K)    - 1.0
                  END DO
                  DO WHILE (DUMA(K) <= - 0.5)
                    SGY(K + 6) = SGY(K + 6) - 1.0
                    DUMA(K)    = DUMA(K)    + 1.0
                  END DO
                END DO
                VERS = SQRT (PAR(129) * DUMA(1) ** 2
     1                     + PAR(130) * DUMA(2) ** 2
     2                     + PAR(131) * DUMA(3) ** 2
     3                     + PAR(132) * DUMA(1) * DUMA(2)
     4                     + PAR(133) * DUMA(1) * DUMA(3)
     5                     + PAR(134) * DUMA(2) * DUMA(3))
C * CONSIDER/DELETE CLOSE CONTACT ATOM (Q-ATOMS ...)
                IF (VERS < RGBL25) THEN
C * CONSIDER X-H
                  CALL GEN048 (-1, IFG(1, I), 7, IHAT)
                  IF (IHAT == 1 .OR. IHYD == 1) THEN
                    IF (VERS > PAR(22)) CYCLE
                  END IF
                  IF (NQ2(1:1) /= 'Q' .AND. VERS > PAR(22))
     1              CYCLE
                  IF (I /= (NAT + 1)) THEN
                    CALL PLA047 (LABA(I), NQ2, IENM, IDUM,
     1                IPR(71), IGBL(55), 0, 0)
C * BUT DO NOT ELIMINATE EXPLICITLY DISORDERED ATOMS
                    IPR(100) = IPR(100) + 1
                    WRITE (LU6, 99999, IOSTAT = IOST)
     1                NQ1(1:7), VERS, NQ2(1:7)
C * AVERAGE POSITIONS (FOR SAME ATOM TYPES)
                    IF (VERS < PAR(22)) THEN
                      IF (IEN(IENM1) == IDUM) THEN
                        DO K = 1, 3
                          FN(K) = (CON(I, K + 2) + SGY(K + 6)) / 2.0
                          CON(I, K + 2) = FN(K)
                        END DO
                        FN(4) = - 1.0
C * WRITE CORRECTION
                        WRITE (LU4) 11, CON(I, 2), (FN(K), K = 1, 8)
                      END IF
                      WRITE (LU6, 99998, IOSTAT = IOST)
     1                  NQ1(1:7), VERS, NQ2(1:7), (FN(K), K = 1, 3)
                    END IF
C * ALERT _310
                    CALL PLA236 (310, 3, VERS, VERS, NQ1, NQ2)
                    IPR(471) = IPR(471) + 1
                    IPR(107) = 1
C * ZERO ERROR MESSAGE
                    IPR(2)   = 0
                    RETURN
                  ELSE
                    IF (MULT == 0 .OR. IABS (IGBL(8)) /= 2 .OR.
     1                IABS (IGBL(8)) /= 3) THEN
                      MULTX = MULTX + 1
                      MULT  = MULT + 1
                      DO K = 1, 3
                        CON(NAT + 2, K + 2) = CON(NAT + 2, K + 2)
     1                                      + SGY(K + 6)
                      END DO
                    END IF
                  END IF
                END IF
              END DO
            END DO
          ELSE
            MULT = NINT (1.0 / SGY(10))
          END IF
        END IF
      END IF
      CALL PLA047 (INQNR, NQ2, MN, IDUM, 0, IGBL(55), 0, 0)
      IF (IGBL(8) == 3 .AND. FN(11) == 1.0 .AND. MULT /= 1) THEN
        FN(4) = FN(4) * MULT
        FN(8) = FN(8) * MULT
      END IF
      DO K = 1, NP64
        IF (NQ2(K : K) == '#') THEN
          IF (IPR(759) == 1) THEN
            IPR(71)  = 0
            IPR(350) = 0
          END IF
          CALL PLA282 (1, IFL(IPR(473)), NQ2, LU6)
          EXIT
        END IF
      END DO
      IF (IPR(39) == 0) IPPR(1, 3) = NSYM
      IPR(39)       = IPR(39) + 1
      IPR(37)       = IPR(39)
      LABA(IPR(39)) = INQNR
C * SHELX(L)/RES
      IF (IABS (IGBL(8)) == 2) THEN
        CON(IPR(39), 8) = IENR
        CON(IPR(39), 9) = FN(4)
      END IF
C * DISORDER GROUP
C * SET SHELXL PART #
      IVL = IPR(612) + 16
      CALL GEN048 (5, IFG(3, IPR(39)), 14, IVL)
C * SET SPECIAL POSITION BIT (6)
      IF (MULT > 1) CALL GEN048 (1, IFG(1, IPR(39)), 6 , 1)
C * SET ATOM TYPE NUMBER REFERENCE
      CALL GEN048 (4, IFG(1, IPR(39)), 15, NIEN)
C * HANDLE EXPLICIT MOVE/FIX INSTRUCTION FOR THIS ATOM
      IF (IPR(165) > 0) THEN
        ITRNS    = IPR(165)
        IPR(165) = 0
      ELSE
        ITRNS    = IPR(95)
      END IF
      IATP(IPR(39)) = ITRNS
C * SET SHELXL POPULATION RESTRAINT
      CALL GEN048 (-1, IFG(3, IPR(39)), 10, IPOPRES)
C * REGISTER H-ATOM STATUS
      CALL GEN048 (1, IFG(1, IPR(39)), 7, IHYD)
C * TEST FOR ELEMENT TYPE  (METAL) - SET METAL BIT
      IF (IATPR(IEN(NIEN + 1)) > 0) THEN
        CALL GEN048 (1, IFG(1, IPR(39)), 19, 1)
C * REGISTER METAL CONTAINING COMPOUND
        IPR(155) = 1
C * RESET FROM ORGANIC DEFAULT BOND RADII TO METAL STRUCTURE RADII
        PAR(85)  = 2
        PAR(87)  = 1
      END IF
      NPOP    = IPR(65)
      POPPARX = FN(4) * MULT
C * CHECK POPULATION PARAMETER RANGE (FOR NON-CSD DATA)
      IF (IABS (IGBL(8)) == 3) THEN
C * ALERT _075 - IMPOSSIBLE POPULATION PARAMETER VALUE > 1.0
        IF (POPPARX > 1.001 .AND. IGBL(94) == 0)
     1    CALL PLA236 (75, 3, 1.0, POPPARX, IFL(IPR(473)), ' ')
C * ALERT _076
        IF (POPPARX < 1.0 .AND. MULT /= 1
     1    .AND. ABS (MULT * POPPARX - 1.0) < 0.01
     2    .AND. IPOPRES == 0) THEN
            CALL PLA236 (76, 3, 0.5, POPPARX, IFL(IPR(473)), ' ')
        END IF
      END IF
C * CHECK LABEL ORDER IN CIF
      IF (IGBL(8) == 3) THEN
        IF (MOD (JNQNR, 40) == 0) THEN
          N   = IEN(IENM1)
C * CHECK CARBON ORDER
          IF (N == 2) THEN
            IF (JNQNR > IATYC) THEN
              IATYC = JNQNR
            ELSE
              IPR(545) = IPR(545) + 1
              IF (IPR(545) == 1 .AND. IPR(105) == 0) THEN
C * ALERT _795
                CALL PLA236 (795, 0, -999.0, 1.0, NQ1, ' ')
              END IF
            END IF
C * CHECK OXYGEN ORDER
          ELSE IF (N == 3) THEN
            IF (JNQNR > IATYO) THEN
              IATYO = JNQNR
            ELSE
              IPR(546) = IPR(546) + 1
              IF (IPR(546) == 1 .AND. IPR(105) == 0) THEN
C * ALERT _796
                CALL PLA236 (796, 0, -999.0, 1.0, NQ1, ' ')
              END IF
            END IF
C * CHECK NITROGEN ORDER
          ELSE IF (N == 4) THEN
            IF (JNQNR > IATYN) THEN
              IATYN = JNQNR
            ELSE
              IPR(547) = IPR(547) + 1
              IF (IPR(547) == 1 .AND. IPR(5) == 0) THEN
C * ALERT _797
                CALL PLA236 (797, 0, -999.0, 1.0, NQ1, ' ')
              END IF
            END IF
          END IF
        END IF
      END IF
C * HANDLE POPULATION > 1 FOR NON-CIF
      IF (IABS(IGBL(8)) == 3 .AND. IPR(23) == 0) THEN
        FN(4) = POPPARX
      ELSE
        FN(4) = MIN (1.0, POPPARX)
      END IF
      FN(8) = FN(8) * MULT
C * SET DEFAULT PP TO 1.0 AND ESD TO 0
      IF (IGBL(8) /= 3) THEN
        IF (FN(4) < PAR(12)) FN(4) = 1.0
      END IF
      IF (FN(8) < 0.0) FN(8) = 0.0
      IF (FN(4) < 0.5) JNQNR = JNQNR + 150 * 4000
      JR(IPR(39)) = JNQNR
      INTPOP      = NINT (FN(4) * 10000.0)
      IF (INTPOP == 5000) THEN
        IF (FN(4) > 0.5) INTPOP = 5001
        IF (FN(4) < 0.5) INTPOP = 4999
      END IF
      IPPR(NPOP + 1, 1) = INTPOP
      IPPR(NPOP + 1, 2) = NINT (FN(8) * 10000.0)
      IPPR(NPOP + 1, 3) = NSYM  / MULT
      FN(4)             = FN(4) / MULT
      FN(8)             = FN(8) / MULT
C * PROVISIONAL CALCULATION OF THE DENSITY
      IF (IHYD == 0) PAR(386) = PAR(386) + NSYM * FN(4)
      PAR(388) = PAR(388) + NSYM * FN(4) * ATWT(IEN(NIEN + 1))
      PAR(387) = PAR(388) / (PAR(98) * 0.60221)
C * RESET COORDINATES TO SPECIAL POSITION
      IF (MULTX > 1 .AND. INTPOP == 10000) THEN
        DO K = 1, 3
          CON(NAT + 1, K + 2) = CON(NAT + 2, K + 2) / MULTX
          FN(K) = CON(NAT + 1, K + 2)
        END DO
      END IF
      MULT = NSYM / MULT
      IF (MOD (IPPR(NPOP + 1, 1), 10000) /= 0) THEN
        IPR(44) = 1
        IF (IHYD == 0) IPR(43) = 1
      END IF
C * SET POPULATION PARAMETERS
      DO I = 1, NPOP
        IF (IPPR(I, 3) == IPPR(NPOP + 1, 3) .AND.
     1      IPPR(I, 1) == IPPR(NPOP + 1, 1)) THEN
          IPOP = I - 1
          GO TO 10
        END IF
      END DO
      IPOP = NPOP
      IF (IPOP > MP7) THEN
C * POPULATION PARAMETER OVERFLOW
        IPR(92) = IPR(92) + 1
C * ERROR MESSAGE CODE
        IPR(2) = 10
        RETURN
      ELSE
        IPR(65) = IPR(65) + 1
      END IF
C * SET POPULATION NUMBER
   10 CALL GEN048 (8, IFG(2, IPR(39)), 1, IPOP)
C * SET ISU (0/1) - I.E. STANDARD UNCERTAINTY
      CALL GEN048 (1,  IFG(2, IPR(39)), 10, ISU)
      IF (FN(8) > 0.0)
     1  CALL GEN048 (1, IFG(2, IPR(39)), 29, 1)
      CALL GEN048 (-1, IFG(1, IPR(39)), 7, JHAT)
      IF (JHAT == 1) IPR(564) = IPR(564) + ISU
C * SET LABEL ON
      CALL GEN048 (1, IFG(2, IPR(39)), 11, 1)
C * COUNT # ATOMS WITH SU
      IF (FN(5) + FN(6) + FN(7) > 0.0001) IPR(745) = IPR(745) + 1
      WRITE (LU4) 1, INQNR, (FN(K), K = 1, 8)
C * HANDLE MULTIPLICATIVE UEQ TRANSFER TO U-HATOMS (SHELXL)
      IF (IABS (IGBL(8)) == 2) THEN
        IF (FN(9) < 0.0) THEN
          FN(9) = - FN(9) * PAR(61)
        ELSE
          IF (IHYD == 0) PAR(61) = FN(9)
        END IF
      END IF
      IF (KN == 10) WRITE (LU4) 4, INQNR, (FN(K), K = 9, 16)
      IF (KN == 20) THEN
C * SET ANISO-FLAG
        CALL GEN048 (1, IFG(1, IPR(39)), 4, 1)
        CALL GEN144 (1, FN(9), PAR(135))
C * LOAD U-MATRIX(6 TO 9 COMPONENTS)
        CALL GEN025 (DUMV, FN(9), -1)
C * CALCULATE TM2 * UIJ * TR(TM2)
        CALL GEN001 (1, TM2, DUMV, UIJ)
C * EXTRACT FROM TRANSFORMED U-MATRIX (9 TO 6 COMPONENTS)
        CALL GEN025 (UIJ, FN(9), 1)
        CALL GEN144 (-1, FN(9), PAR(113))
C * SAVE UEQ FOR SHELXL H-ATOMS WITH ASSOCIATED NEGATIVE U'S
        IF (IABS(IGBL(8)) == 2 .AND. IHYD == 0) THEN
          CALL GEN025 (UIJ, FN(9), -1)
C * UIJ - MAIN AXES & VALUES & UEQ
          CALL GEN114 (PAR, OR, UIJ, UIJC, DUMA, DUMV, PAR(61))
        END IF
C * WRITE UIJ AND SUIJ
        WRITE (LU4) 2, INQNR, (FN(K), K =  9, 16)
        WRITE (LU4) 3, INQNR, (FN(K), K = 15, 22)
      END IF
      RETURN
99999 FORMAT (':: ATOM ', A, ' DELETED from INPUT STREAM, ',
     1         F5.2, ' Ang. From ', A)
99998 FORMAT (':: ATOM ', A, ' at', F5.2, ' Ang. from ', A,
     1        ' - New Av Pos:', 3F8.4)
99997 FORMAT ('_', I1)
99996 FORMAT ('_', I2)
      END SUBROUTINE PLA450
 
      SUBROUTINE PLA451
C * CHECK CONSISTENCY H-M WITH EXPLICIT FROM SYMMETRY H-M SPACEGROUPNAME
      USE cchar
      USE parameters
 
      IMPLICIT NONE
      INTEGER :: I
      IF (IGBL(94) == 0) THEN
        IF (CCIF(7)(1:11) /= CCIF(8)(1:11) .AND.
     1    IPR(319) * IPR(318) == 1) THEN
          IDM = CCIF(8)
C * ELIMINATE BLANKS
          CALL GEN047 (IDM, 1, 20)
          NQ2 = IDM(1:7)
          CALL GEN020 (-1, NQ2, 2, 7)
          IF (NQ2(1:1) == ' ') NQ2(1:1) = '?'
          I = INDEX (NQ2(2:7), 'r')
          IF (I /= 0) NQ2(I+1:I+1) = 'R'
          IF (I == 0 .OR. IPR(606) /= 8) THEN
            IDM = CCIF(6)
            CALL GEN047 (IDM, 1, 20)
C * ALERT _120 - H-M <-> SYMM CHECK TEST
            IF (IDM(1:1) /= '?') THEN
              NQ3 = '  '//NQ2(1:7)
              CALL PLA236 (120, 0, -999.0, 1.0, IDM(1:7), NQ3)
            END IF
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA451
 
      SUBROUTINE PLA452 (KN, IENR, ISK)
C * HANDLE SHELXL INS/RES ATOM FORMAT RECORD
      USE parameters
      USE plato
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: KN
      INTEGER :: ISK
      INTEGER :: KNS
      INTEGER :: IENR
      REAL :: Y
      REAL :: SJ
      REAL :: RPI
      IPR(32) = MAX (IPR(32), 1)
C * SKIP DENSITY
      IF (KN == 7) KN = 6
      IF (KN == 20) THEN
        DO J = 12, 20
          FN(9 + J) = FN(J)
          FN(J)     = 0.0
        END DO
        KN  = 11
        KNS = 9
      ELSE IF (KN == 10) THEN
        DO J = 7, 10
          FN(14 + J) = FN(J)
          FN(J)      = 0.0
        END DO
        KN  = 6
        KNS = 4
      ELSE
        KNS = 0
      END IF
C * COMPLETE WHEN NO(OR INCOMPLETE) POPULATION AND/OR U/UIJ GIVEN
      IF (KN /= 6  .AND. KN /= 11) THEN
        IPR(498) = IPR(498) + 1
        IF (KN == 4) FN(5) = 11.0
        FN(6) = PAR(30)
        KN    = 6
      END IF
      IENR = NINT (FN(1))
C * IMPLEMENT FREE-VARIABLE VALUES
      DO J = 2, KN
        Y = FN(J)
        IF (ABS (Y) > 5.0) THEN
          I  = NINT (ABS (Y) * 0.1)
          IF (I == 1) THEN
            RPI = 1.0
          ELSE
            RPI = RP(I)
          END IF
          SJ = SIGN (0.5, Y)
          IF (I /= 1 .AND. I > IPR(109)) THEN
C * ERROR MESSAGE CODE - FVAR ERROR
            IPR(2) = 9
            RETURN
          END IF
          Y = (Y - I * SJ * 20.0) * (RPI + SJ - 0.5)
        END IF
        FN(J - 1) = Y
      END DO
      KN = KN - 1
C * X, Y, Z, POP,U  - CASE
      IF (KN == 5) THEN
        FN(9)  = FN(5)
        FN(10) = 0.0
        KN     = 10
      ELSE
        IPR(32) = 2
C * X, Y, Z, POP, U11, U22, U33, U23, U13, U12 - CASE
        DO J = 1, 6
          FN(15 - J) = FN(11 - J)
        END DO
        CALL GEN074 (FN, 15, 20, 0.0)
        KN = 20
      END IF
      CALL GEN074 (FN, 5, 8, 0.0)
C * SKIP (DUMMY) ATOMS WITH POPULATION 0.0
      IF (FN(4) < 0.0001) THEN
C * DELETED ATOM COUNTER
        IPR(100) = IPR(100) + 1
C * IGNORED ATOM COUNTER
        IPR(471) = IPR(471) + 1
C * ERROR MESSAGE CODE
        IPR(2)   = 0
        ISK      = 1
        RETURN
      END IF
      IF (KNS > 0) THEN
        DO J = 1, 3
          FN(J + 4) = FN(20 + J)
        END DO
        IF (KNS == 4) THEN
          FN(10) = FN(24)
        ELSE
          DO J = 1, 6
            FN(14 + J) = FN(23 + J)
          END DO
        END IF
      END IF
      RETURN
      END SUBROUTINE PLA452
 
      SUBROUTINE PLA453 (IENM1, INQNR, JNQNR, NIEN, IHYD)
C * GET NUMERICAL REPRESENTATION FOR THE LABEL IN NQ1
      USE plato
      USE files
      USE parameters
      USE atomdata
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: KL
      INTEGER :: NAT
      INTEGER :: LBB
      INTEGER :: LBC
      INTEGER :: LBD
      INTEGER :: LOP
      INTEGER :: NCY
      INTEGER :: IHYD
      INTEGER :: NIEN
      INTEGER :: MODE
      INTEGER :: IENM1
      INTEGER :: INQNR
      INTEGER :: JNQNR
      MODE = 100
      NCY  = 0
      LOP  = 0
      NQ2  = NQ1
      NQ4  = NQ1
      NAT  = IPR(39)
C * GET NUMBER OF NON-NUMERICAL ENTRIES ON INPUT RECORD
      KL   = IPR(220)
      DO
        CALL PLA046 (MODE, NQ1, IENM1, LBB, LBC, LBD, INQNR, JNQNR,
     1    NIEN)
C * ALERT FOR LABEL WITHOUT NUMERICAL PART
        IF (LBB == 0 .AND. NIEN >= 0) THEN
          IF (NQ1(2:2) /= '0') THEN
            CALL GEN020 (-1, NQ1, 2, 2)
C * ALERT _069
            IF (IPR(105) == 0)
     1        CALL PLA236 (69, 0, -999.0, 1.0, NQ1, ' ')
          END IF
        END IF
C * CHECK & ATTEMPT TO CORRECT LABEL PROBLEM
        IF (NIEN < 0) THEN
          IF (NIEN == -7) THEN
C * ERROR MESSAGE CODE
            IPR(2) = 67
            RETURN
          ELSE IF (NIEN == -12) THEN
            NQ1    = NQ2
C * ERROR MESSAGE CODE
            IPR(2) = 57
            RETURN
          END IF
C * HANDLE CIF-STYLE DATA LABEL
          IF (IABS (IGBL(8)) == 3) THEN
            IF (KL == 3) THEN
              LOP = LOP + 1
              IF (LOP == 1) THEN
                NQ1 = IFL(3)
              ELSE
C * HANDLE 'Ox' case (avoid infinite loop
                MODE     = 100
                NQ1      = IFL(2)
                IPR(220) = 2
                KL       = 2
              END IF
            ELSE
              LOP = LOP + 1
C * NUMBER CHARACTER OR LEFT PARENTHESIS IN POSITION 2 ?
              IF (((ICHAR (IFL(2)(2:2)) >= 48 .AND.
     1          ICHAR (IFL(2)(2:2)) <= 57) .OR.
     2          IFL(2)(2:2) == '(')  .AND. LOP < 3) THEN
                NQ1 = IFL(2)(1:1)//'      '
              ELSE
C * UNSUITABLE ATOM LABEL
                NQ0    = NQ1
C * ERROR MESSAGE CODE
                IPR(2) = 3
                RETURN
              END IF
            END IF
C * HANDLE SHELXL/RES STYLE DATA LABEL
          ELSE IF (IABS (IGBL(8)) == 2) THEN
            IF (IAN > 0 .AND. NINT (FN(1)) <= IAN) THEN
C * SUBSTITUTE LEGAL LABEL
              NQ1 = LMT(NINT(FN(1)), 1)//'     '
            ELSE
C * EROOR MESSAGE CODE - SHELX/SFAC PROBLEM
              IPR(2) = 46
              RETURN
            END IF
C * HANDLE SPF STYLE DATA LABEL
          ELSE IF (IABS (IGBL(8)) == 1) THEN
            IF (KL == 3) THEN
              NQ1 = IFL(3)
            END IF
            CALL GEN020 (1, NQ1, 1, 2)
            IF (NQ1(1:2) == 'HN') NQ1 = 'H'
            IF (NQ1(1:2) == 'HO') NQ1 = 'H'
            IF (ICHAR (NQ1(2:2)) >= 48 .AND.
     1          ICHAR (NQ1(2:2)) <= 57) THEN
              NQ1(2:) = '      '
            ELSE
              NQ1(3:) = '     '
            END IF
          ELSE
C * UNSUITABLE ATOM LABEL
            NQ0 = NQ1
C * ERROR MESSAGE CODE
            IPR(2) = 3
            RETURN
          END IF
C * CREATE ACCEPTABLE LABEL
          IF (NQ1(1:1) == ' ') THEN
            NQ1(1:1) = NQ1(2:2)
            NQ1(2:4) = '999'
          ELSE IF (NQ1(2:2) == ' ') THEN
            NQ1(2:4) = '999'
          ELSE
            NQ1(3:4) = '99'
          END IF
          MODE = 99
          NCY  = NCY + 1
          IF (NCY < 2) THEN
            CYCLE
          ELSE
            WRITE (LU6, 99995) IFL(1), IFL(2),IFL(3)
            RETURN
            END IF
          END IF
        IF (MODE == 100) THEN
C * CHECK FOR PRE-OCCURRENCE OF THIS LABEL
          DO K = 1, NAT
            IF (LABA(K) == INQNR) THEN
C * ALERT _070 - DUPLICATE LABEL
              CALL PLA236 (70, 0, 1.0, 1.0, NQ2, ' ')
C * LABEL PRE-OCCURRED, GENERATE NEW LABEL WITH #
              MODE = 99
              EXIT
            END IF
          END DO
        ELSE IF (MODE == 99) THEN
          EXIT
        END IF
        IF (MODE /= 99) EXIT
      END DO
C * TEST FOR HYDROGENS (H, D OR Hw)
      IF (IEN(NIEN + 1) == 1 .OR. IEN(NIEN + 1) == 33 .OR.
     1    IEN(NIEN + 1) == 113) THEN
        IHYD = 1
      END IF
      RETURN
99995 FORMAT (':: Label Problem in PLA022', 2X, 3A)
      END SUBROUTINE PLA453
 
      SUBROUTINE PLA454 (KL, KN, NAT, IHYD, IENM1, INQNR, JNQNR, NIEN)
C * CHECK FOR AND HANDLE CIF STYLE INPUT (IGBL(8) = 3)
      USE plato
      USE parameters
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: NAT
      INTEGER :: IHYD
      INTEGER :: NIEN
      INTEGER :: IENM1
      INTEGER :: INQNR
      INTEGER :: JNQNR
C * GET NUMBER OF NUMERICAL ENTRIES ON INPUT RECORD
      KN = IPR(221)
C * CHECK FOR INCOMPLETE CIF-DATA
      IF (KN /= 10) THEN
C * CHECK FOR VALIDATION
        IF (IGBL(3) == 1) THEN
C * ALERT _170 - INSUFFICIENT DATA
          CALL PLA236 (170, 0, 1.0, 1.0, IFL(2), ' ')
        ELSE
C * ERROR MESSAGE CODE
          IPR(2) = 51
        END IF
        RETURN
      END IF
C * CHECK CONSISTENCY OF H-M SYMBOL WITH EXPLICITLY SUPPLIED SYMMETRY
      IF (NAT == 0) CALL PLA451
C * COUNT # OF PART EXTENSIONS ON LABEL
      IF (INDEX (NQ1, '^') > 0) IPR(768) = IPR(768) + 1
C * GET ASSIGNED SCATTERING TYPE TO THIS ATOM (_atom_site_type_symbol)
      IF (KL == 3) THEN
        N = 9
        IF (IFL(3)(3:3) == ' ') N = 2
        IF (IFL(3)(2:2) == ' ') N = 1
C * CHECK
        IF (N <= 2) THEN
          NQ4 = '       '//IFL(3)(1:N)
C * ALERT _017 - SCATTERING TYPE CONSISTENCY (SHELXL-CIF)
          IF (INDEX (IFL(2), IFL(3)(1:N)) == 0) THEN
            CALL PLA236 (17, 0, 1.0, 0.0, IFL(2)(1:9), NQ4(1:9))
          END IF
        END IF
      END IF
C * GET NUMERICAL REPRESENTATION FOR THE LABEL IN NQ1
      CALL PLA453 (IENM1, INQNR, JNQNR, NIEN, IHYD)
      IF (IPR(2) /= 0) RETURN
C * HANDLE SHELXL/CIF ISSUE
      IF (FN(24) == 1.0 .AND. FN(8) == 0.0) THEN
        IF (FN(4) == 0.330) FN(4) = 0.33333
        IF (FN(4) == 0.670) FN(4) = 0.66667
      END IF
C * 'd'
      IF (FN(21) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 1, 1)
C * 'c'
      IF (FN(22) == 1.0) THEN
        CALL GEN048 (1, IFG(3, NAT + 1), 2, 1)
C * ALERT _166
        IF ((FN(5) > 0.0 .OR. FN(6) > 0.0 .OR.
     1       FN(7) > 0.0) .AND. FN(30) /= 1.0 .AND.
     2       FN(26) /= 1.0) THEN
               IPR(792) = IPR(792) + 1
               IF (IPR(792) <= NP93) RLAB(IPR(792)) = IFL(IPR(473))
        END IF
      END IF
C * 'dum'
      IF (FN(23) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 3, 1)
C * 'S'
      IF (FN(24) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 4, 1)
C * 'G'
      IF (FN(25) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 5, 1)
C * 'R'
      IF (FN(26) == 1.0) THEN
        CALL GEN048 (1, IFG(3, NAT + 1), 6, 1)
C * COUNT NON-H R-Status
        IF (IHYD == 0) IPR(164) = IPR(164) + 1
      END IF
C * 'D'
      IF (FN(27) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 7, 1)
C * 'T'
      IF (FN(28) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 8, 1)
C * 'U'
      IF (FN(29) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 9, 1)
C * 'P'
      IF (FN(30) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 10, 1)
C * DISORDER ASSEMBLY
C * 'A'
      IF (FN(31) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 11, 1)
C * 'B'
      IF (FN(32) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 12, 1)
C * 'S'
      IF (FN(33) == 1.0) CALL GEN048 (1, IFG(3, NAT + 1), 13, 1)
      RETURN
      END SUBROUTINE PLA454
 
      SUBROUTINE PLA455 (M, N, ITX, ITY, ITZ, IRES)
C * SPLIT-UP ARU CODE IN COMPONENTS
      IMPLICIT NONE
      INTEGER :: M
      INTEGER :: N
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: IRES
      INTEGER :: IARU
      INTEGER :: MABS
      MABS = IABS (M)
      ITX  = MOD (MABS / 10000, 10) - 5
      ITY  = MOD (MABS / 1000,  10) - 5
      ITZ  = MOD (MABS / 100,   10) - 5
      IRES = MOD (MABS, 100)
      N    = INT (MABS / 100000)
      RETURN
      END SUBROUTINE PLA455
 
      SUBROUTINE PLA500
