     8 '_diffrn_oxdiff_scatteringfactors_ed                ',
     9 '_diffrn_frame_id                                   ',
     * '_diffrn_frame_h                                    ',
C * 941-950
     1 '_diffrn_frame_k                                    ',
     2 '_diffrn_frame_l                                    ',
     3 '_diffrn_frame_start_angle                          ',
     4 '_diffrn_frame_end_angle                            ',
     5 '_diffrn_frame_scale                                ',
     6 '_diffrn_oxdiff_digest_creation                     ',
     7 '_diffrn_oxdiff_digest_hkl                          ',
     8 '_diffrn_oxdiff_digest_hkl_ed                       ',
     9 '_diffrn_oxdiff_digest_od_ed                        ',
     * '_olex2_refine_details                              ',
C * 951-960
     1 '_refln_frame_id                                    ',
     2 '_refln_diffraction_start_angle                     ',
     3 '_refln_diffraction_end_angle                       ',
     4 '_refln_intensity_scale_factor                      ',
     5 '_oxdiff_exptl_crystal_thickness                    ',
     6 '_restr_chirality_atom_site_label_1                 ',
     7 '_restr_chirality_atom_site_label_2                 ',
     8 '_restr_chirality_atom_site_label_3                 ',
     9 '_restr_chirality_atom_site_label_4                 ',
     * '_restr_chirality_site_symmetry_1                   ',
C * 961-970
     1 '_restr_chirality_site_symmetry_2                   ',
     2 '_restr_chirality_site_symmetry_3                   ',
     3 '_restr_chirality_site_symmetry_4                   ',
     4 '_restr_chirality_volume_target                     ',
     5 '_restr_chirality_weight_param                      ',
     6 '_restr_chirality_diff                              ',
