     8 '_restr_equal_distance_class_id                     ',
     9 '_restr_equal_distance_class_average                ',
     * '_restr_equal_distance_class_esd                    ',
C * 971-980
     1 '_restr_equal_distance_class_diff_max               ',
     2 '_restr_u_iso_atom_site_label                       ',
     3 '_restr_u_iso_weight_param                          ',
     4 '_restr_u_similar_atom_site_label_1                 ',
     5 '_restr_u_similar_atom_site_label_2                 ',
     6 '_restr_u_similar_weight_param                      ',
     7 '_shelx_f_squared_multiplier                        ',
     8 '_cell_oxdiff_angle_alpha                           ',
     9 '_cell_oxdiff_angle_beta                            ',
     * '_cell_oxdiff_angle_gamma                           ',
C * 981-990
     1 '_cell_oxdiff_length_a                              ',
     2 '_cell_oxdiff_length_b                              ',
     3 '_cell_oxdiff_length_c                              ',
     4 '_cell_oxdiff_volume                                ',
     5 '_cell_oxdiff_measurement_reflns_used               ',
     6 '_axis_id                                           ',
     7 '_axis_system                                       ',
     8 '_axis_type                                         ',
     9 '_axis_equipment                                    ',
     * '_axis_parity                                       ',
C * 991-1000
     1 '_axis_depends_on                                   ',
     2 '_axis_zero                                         ',
     3 '_axis_vector[1]                                    ',
     4 '_axis_vector[2]                                    ',
     5 '_axis_vector[3]                                    ',
     6 '_diffrn_orient_matrix_axis[1]                      ',
     7 '_diffrn_orient_matrix_axis[2]                      ',
     8 '_diffrn_orient_matrix_axis[3]                      ',
     9 '_refln_F_squared_weight                            ',
     * '_oxford_atom_site_label                            ',
C * 1001-NP34
     1 '_oxford_atom_site_special_uiso                     ',
     2 '_oxford_atom_site_special_siso                     ',
     3 '_oxford_atom_site_special_declination              ',
     4 '_oxford_atom_site_special_azimuth                  ',
