          IF (N > 0) SCTYP(2 : 2) = CHAR (ICHAR ('a') + N - 1)
          IF (IENR == 1 .OR. IENR == 33 .OR. IENR == 113) THEN
            IF (MODE == 1) CYCLE
          ELSE
            IF (MODE == 2) CYCLE
          END IF
          N   =  0
          IPS = -4
          FORMC(5 : 5) = '2'
          IF (IPR(431) == -1) THEN
            FORMC(2 : 2) = '1'
          ELSE
            FORMC(2 : 2) = '3'
          END IF
          IF (MODE < 3) THEN
            IF (IPR(431) == -1) THEN
              FORMC(2 : 2) = '1'
              FORMC(5 : 5) = '3'
            ELSE
              FORMC(2 : 2) = '7'
              FORMC(5 : 5) = '2'
            END IF
            IF (VOID(N2 + 1) < 1.0) THEN
              DISOR = '*'
              NDISO = NDISO + 1
            END IF
            DO M = N1, N2
              N         = N + 1
              IPS   = IPS + 16
              IF (M - N1 == 3) THEN
                FORMC(IPS - 2 : IPS - 2) = '6'
                MDEC = 3
              ELSE
                FORMC(IPS - 2 : IPS - 2) = '9'
                MDEC = MIN (IPR(183), 5)
              END IF
              STDV = MAX (0.0, VOID(IPR(245) + M))
              CALL GEN041 (VOID(M), STDV, ISDV(N), MDEC, IDEC, IPR(68))
              FORMC(IPS : IPS) = CHAR (ICHAR ('0') + IDEC)
              DEV(N)  = VOID(M)
            END DO
          END IF
C * UEQ, U OR UIJ
          DO M = N3, N4
            N    = N + 1
            STDV = MAX (0.0, VOID(IPR(245) + M))
            CALL GEN041 (VOID(M), STDV, ISDV(N), 4, IDEC, IPR(68))
            IPS   = IPS + 16
C * SET FIELDWIDTH UIJ ENTRY
            IF (MODE == 3) THEN
              IF (IPR(431) == -1 .AND. IPS >= 60) THEN
                FORMC(IPS - 2 : IPS - 2) = '8'
              ELSE
                FORMC(IPS - 2 : IPS - 2) = '7'
              END IF
            END IF
            FORMC(IPS : IPS) = CHAR (ICHAR ('0') + IDEC)
            DEV(N) = VOID(M)
          END DO
          IF (IPR(431) == 1) THEN
            ITEL = ITEL + 1
            IF (NR > NRO) THEN
              ITEL = ITEL + 1
              NRO  = NR
              WRITE (LU, 99985, IOSTAT = IOST)
              IF (IDOUBL == 2) WRITE (LU, 99985, IOSTAT = IOST)
            END IF
            IF (ITEL > MXLIN) THEN
              ITEL = LSTART + 1
              IGBL(85) = IGBL(85) + 1
              WRITE (LU, 99982, IOSTAT = IOST) CHAR (12), IGBL(85)
              IF (MODE == 1) THEN
                CALL PLA575 (1, LU, CTAB, NTAB, FORMNH, JID)
                WRITE (LU, 99998, IOSTAT = IOST)
              ELSE IF (MODE == 2) THEN
                CALL PLA575 (1, LU, CTAB, NTAB, FORMHC, JID)
                WRITE (LU, 99995, IOSTAT = IOST)
              ELSE IF (MODE == 3) THEN
                CALL PLA575 (1, LU, CTAB, NTAB, FORMAN, JID)
                WRITE (LU, 99997, IOSTAT = IOST)
              END IF
            END IF
          END IF
C * TEST FOR ACC (= -1) OR SUP (= 1)
          IF (IPR(431) == -1) THEN
            IF (MODE == 1 .OR. MODE == 2) THEN
              ASCF = '. .   . .  '
              NQ4  = NQ1
              CALL PLA046 (2, NQ4, IX, LBB, LBC, LBD, INQNR, JNQNR, NR)
              IF (NR > 0) THEN
C * calc_flag
                CALL GEN048 (-1, IFG(3, NR), 1, IVL)
                IF (IVL > 0) ASCF(1:1) = 'd'
                CALL GEN048 (-1, IFG(3, NR), 2, IVL)
                IF (IVL > 0) ASCF(1:1) = 'c'
                K = 2
C * refinement_flags
                DO J = 4, 10
                  IF (K < 5) THEN
                    CALL GEN048 (-1, IFG(3, NR), J, IVL)
                    IF (IVL /= 0) THEN
                      K = K + 1
                      ASCF(K:K) = CVLAG(J - 3)
                    END IF
                  END IF
                END DO
C * disorder_assembly
                CALL GEN048 (-1, IFG(3, NR), 11, IVL)
                IF (IVL > 0) ASCF(7:7) = 'A'
                CALL GEN048 (-1, IFG(3, NR), 12, IVL)
                IF (IVL > 0) ASCF(7:7) = 'B'
                CALL GEN048 (-1, IFG(3, NR), 13, IVL)
                IF (IVL > 0) ASCF(7:7) = 'S'
C * disorder_group
                CALL GEN048 (-5, IFG(3, NR), 14, IVL)
                IF (IVL /= 16) THEN
                  WRITE (ASCF(9:11), '(I3)', IOSTAT = IOST) IVL - 16
                END IF
              END IF
              WRITE (PRBUF, FORMC, IOSTAT = IOST) NQ1(1:8), SCTYP,
     1          UTYPE, (DEV(M), ISDV(M), M = 1, N)
              PRBUF(82:) = ASCF
            ELSE IF (MODE == 3) THEN
              WRITE (PRBUF, FORMC, IOSTAT = IOST) DISOR, NQ1(1:7),
     1          (DEV(M), ISDV(M), M = 1, N)
            END IF
            CALL GEN065 (0, PRBUF, 1, 92, 1)
C * COMPACT LINE TO ONE BLANK CHARACTER
            CALL GEN103 (PRBUF, 92)
            WRITE (LU, 99983, IOSTAT = IOST) PRBUF(1:80)
          ELSE
            WRITE (PRBUF, FORMC, IOSTAT = IOST) DISOR, NQ1(1:7),
     1          (DEV(M), ISDV(M), M = 1, N)
            CALL GEN065 (LU, PRBUF, 1, 80, 3)
            IF (IDOUBL == 2) WRITE (LU, 99985, IOSTAT = IOST)
          END IF
        END DO
        IF (IPR(431) == 1) THEN
          IF (MODE == 1) THEN
            WRITE (LU, 99993, IOSTAT = IOST)
            IF (NDISO > 0) WRITE (LU, 99996, IOSTAT = IOST)
          ELSE IF (MODE == 2) THEN
            WRITE (LU, 99989, IOSTAT = IOST)
            WRITE (LU, 99988, IOSTAT = IOST)
            WRITE (LU, 99987, IOSTAT = IOST)
          ELSE IF (MODE == 3) THEN
            WRITE (LU, 99989, IOSTAT = IOST)
            WRITE (LU, 99988, IOSTAT = IOST)
            WRITE (LU, 99987, IOSTAT = IOST)
            WRITE (LU, 99986, IOSTAT = IOST)
          END IF
        END IF
C * BOND TABLE
      ELSE IF (MODE == 4) THEN
        CALL PLA573 (MODE, FORMB, FORMHB, LU, CTAB, NTAB, MXLIN,
     1    LSTART, NCOL, INCLH, 33, 11, 4, IDOUBL)
C * ANGLE TABLE
      ELSE IF (MODE == 5) THEN
        CALL PLA573 (MODE, FORMA, FORMHA, LU, CTAB, NTAB, MXLIN,
     1    LSTART, NCOL, INCLH, 39, 11, 2, IDOUBL)
C * TORSION TABLE
      ELSE IF (MODE == 6) THEN
        CALL PLA573 (MODE, FORMT, FORMHT, LU, CTAB, NTAB, MXLIN,
     1    LSTART, NCOL, INCLH, 42, 0, 2, IDOUBL)
C * INTER-CONTACTS
      ELSE IF (MODE == 7 .AND. IPR(431) == 1) THEN
        CALL PLA573 (MODE, FORMB, FORMNB, LU, CTAB, NTAB, MXLIN,
     1    LSTART, NCOL, INCLH, 33, 11, 4, IDOUBL)
C * H-BONDS
      ELSE IF (MODE == 8) THEN
        CALL PLA573 (MODE, FORHBF, FORMBH, LU, CTAB, NTAB, MXLIN,
     1    LSTART, NCOL, INCLH, 42, 0, 4, IDOUBL)
C * FINISH
      ELSE IF (MODE == 9) THEN
        IF (IPR(431) == 1) THEN
          IGBL(85) = IGBL(85) + 1
          WRITE (LU, 99982, IOSTAT = IOST) CHAR (12), IGBL(85)
          WRITE (LU, 99249, IOSTAT = IOST)
          CALL PLA043 (0, -1, LU, 0)
        END IF
        IF (IPR(431) == -1) THEN
C * OPTIONAL EXTRA TABLES
          WRITE (LU, 99001, IOSTAT = IOST)
          WRITE (LU, 99002, IOSTAT = IOST)
          WRITE (LU, 99003, IOSTAT = IOST)
          WRITE (LU, 99004, IOSTAT = IOST)
          WRITE (LU, 99005, IOSTAT = IOST)
          WRITE (LU, 99006, IOSTAT = IOST)
          WRITE (LU, 99007, IOSTAT = IOST)
        END IF
C * ADD RES & HKL (FAB) EMBEDDED TO ACC.CIF
        IF (IPR(431) == -1) THEN
C * COPY/APPEND RES-FILE
          IF (IPR(663) == 0) THEN
C * WRITE PLACEHOLDER FOR RES
            WRITE (LU, 99994, IOSTAT = IOST) CIFDIR(513)
            WRITE (LU, 99992, IOSTAT = IOST)
          ELSE
            REWIND (UNIT = LU24, IOSTAT = IOST)
            WRITE (LU, 99994, IOSTAT = IOST) CIFDIR(578)
            DO
              READ (LU24, 99983, IOSTAT = IOST) LINE
              IF (IOST /= 0) EXIT
              WRITE (LU, 99983) LINE
            END DO
            WRITE (LU, 99992, IOSTAT = IOST)
            IF (IPR(677) > 0)
     1        WRITE (LU, 99991, IOSTAT = IOST) CIFDIR(579), IPR(677)
          END IF
C * COPY/APPEND HKL-FILE
          IF (IPR(664) == 0) THEN
C * WRITE PLACEHOLDER FOR HKL
            WRITE (LU, 99994, IOSTAT = IOST) CIFDIR(569)
            WRITE (LU, 99992, IOSTAT = IOST)
          ELSE
            REWIND (UNIT = LU25, IOSTAT = IOST)
            WRITE (LU, 99994, IOSTAT = IOST) CIFDIR(580)
            DO
              READ (LU25, 99983, IOSTAT = IOST) LINE
              IF (IOST /= 0) EXIT
              WRITE (LU, 99983) LINE
            END DO
            WRITE (LU, 99992, IOSTAT = IOST)
            IF (IPR(678) > 0)
     1        WRITE (LU, 99991, IOSTAT = IOST) CIFDIR(581), IPR(678)
          END IF
C * COPY/APPEND FAB-FILE
          IF (IPR(665) /= 0) THEN
            REWIND (UNIT = LU26, IOSTAT = IOST)
            WRITE (LU, 99994, IOSTAT = IOST) CIFDIR(601)
            DO
              READ (LU26, 99983, IOSTAT = IOST) LINE
              IF (IOST /= 0) EXIT
              WRITE (LU, 99983) LINE
            END DO
            WRITE (LU, 99992, IOSTAT = IOST)
            IF (IPR(679) > 0)
     1        WRITE (LU, 99991, IOSTAT = IOST) CIFDIR(602), IPR(679)
          END IF
C * WRITE END TO CIF-FILE
          WRITE (LU, 99260, IOSTAT = IOST)
        END IF
      END IF
      RETURN
