      END SUBROUTINE PLA572
 
      SUBROUTINE PLA573 (MODE, FORMX, FORMH, LU, CTAB, NTAB, MXLIN,
     1 LSTART, NCOL, INCLH, IPS1, IPS2, IDECM, IDOUBL)
C * TABLE & CIF CREATION (CONT)
      USE files
      USE parameters
      USE plato
      USE atomdata
      USE cchar
      USE cif
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IC
      INTEGER :: LU
      INTEGER :: IM
      INTEGER :: IN1
      INTEGER :: IN2
      INTEGER :: IN3
      INTEGER :: IC3
      INTEGER :: ICS
      INTEGER :: IND
      INTEGER :: INM
      INTEGER :: INP
      INTEGER :: IPS
      INTEGER :: JMX
      INTEGER :: ISOP
      INTEGER :: IN01
      INTEGER :: IN02
      INTEGER :: IN2P
      INTEGER :: IENR
      INTEGER :: IDEC
      INTEGER :: ICP2
      INTEGER :: NTAB
      INTEGER :: MODE
      INTEGER :: NCOL
      INTEGER :: IPS1
      INTEGER :: IPS2
      INTEGER :: ITEL
      INTEGER :: NHET
      INTEGER :: NLIN
      INTEGER :: MISOP
      INTEGER :: JLABN
      INTEGER :: MXLIN
      INTEGER :: IDECM
      INTEGER :: INCLH
      INTEGER :: MJNSC
      INTEGER :: NDECM
      INTEGER :: NHATS
      INTEGER :: MISOPH
      INTEGER :: MISOPT
      INTEGER :: ISPACE
      INTEGER :: LSTART
      INTEGER :: IDOUBL
      INTEGER, DIMENSION(4) :: IDHA
      REAL, DIMENSION(4) :: DHA
      CHARACTER(len=1) :: CTAB
      CHARACTER(len=*) :: FORMX
      CHARACTER(len=*) :: FORMH
      CHARACTER(len=1) :: DASH
      CHARACTER(len=8), DIMENSION(4) :: GSS
      ISPACE = 0
      JMX    = 0
      NHATS  = 0
      NHET   = 0
C * MODE = 4 : BONDS
C * MODE = 5 : ANGLES
C * MODE = 6 : TORSIONS
C * MODE = 7 : INTER-CONTACTS
C * MODE = 8 : H-BONDS
C * MODE = 9 : FINISH
C * MOLECULAR GEOMETRY SECTION
C * MODE = 4 : BONDS
      IF (MODE == 4) THEN
        ISPACE = 8
        IF (IPR(431) == -1) THEN
          WRITE (LU, 99995, IOSTAT = IOST)
          WRITE (LU, 99994, IOSTAT = IOST)
          WRITE (LU, 99993, IOSTAT = IOST) CIFDIR(277)
          WRITE (LU, 99998, IOSTAT = IOST)
     1      CIFDIR(265), CIFDIR(266), CIFDIR(267), CIFDIR(269),
     2      CIFDIR(270), CIFDIR(268)
          ISPACE = 1
        END IF
C * MODE = 5 : ANGLES
      ELSE IF (MODE == 5) THEN
        ISPACE = 4
        IF (IPR(431) == -1) THEN
          WRITE (LU, 99997, IOSTAT = IOST)
     1      CIFDIR(258), CIFDIR(259), CIFDIR(260), CIFDIR(257),
     2      CIFDIR(262), CIFDIR(263), CIFDIR(264), CIFDIR(261)
          ISPACE = 1
        END IF
C * MODE = 6 : TORSIONS
      ELSE IF (MODE == 6) THEN
        ISPACE = 9
        IF (IPR(431) == -1) THEN
          WRITE (LU, 99996, IOSTAT = IOST)
     1      CIFDIR(279), CIFDIR(280), CIFDIR(281), CIFDIR(282),
     2      CIFDIR(278), CIFDIR(284), CIFDIR(285), CIFDIR(286),
     3      CIFDIR(287), CIFDIR(283)
          ISPACE = 1
        END IF
C * WRITE CONTACTS LOOP-HEADER
C * MODE = 7 : INTER-CONTACTS
      ELSE IF (MODE == 7) THEN
        ISPACE = 8
        IF (IPR(431) == -1) THEN
          WRITE (LU, 99998, IOSTAT = IOST)
     1      CIFDIR(271), CIFDIR(272), CIFDIR(273), CIFDIR(275),
     2      CIFDIR(276), CIFDIR(274)
          ISPACE = 1
        END IF
C * MODE = 8 : H-BONDS
      ELSE IF (MODE == 8) THEN
        ISPACE = 1
        IF (IPR(431) == -1) THEN
          WRITE (LU, 99992, IOSTAT = IOST)
     1      CIFDIR(426)(1:29), CIFDIR(427)(1:29), CIFDIR(428)(1:29),
     2      CIFDIR(429)(1:23), CIFDIR(430)(1:23), CIFDIR(431)(1:23),
     3      CIFDIR(432)(1:21), CIFDIR(433)(1:27), CIFDIR(434)(1:21)
            FORMX(84:86) = 'yes'
        END IF
      END IF
      IN01 = IPR(229 + MODE) + 1
      IN02 = IPR(223 + MODE)
C * MODE < 7
      IF (MODE < 7) THEN
        JMX  = MODE - 2
      ELSE IF (MODE == 7) THEN
        JMX = 2
      END IF
      IF (IPR(431) == 1) THEN
        IGBL(85) = IGBL(85) + 1
        WRITE (LU, 99999, IOSTAT = IOST) CHAR (12), IGBL(85)
      END IF
C * NO DASH BETWEEN ATOM LABELS IN CIF-FILE FOR BONDS, ANGLES ETC.
      DASH = ' '
      IF (IPR(431) == 1) THEN
        CALL PLA575 (-1, LU, CTAB, NTAB, FORMH, JID)
        IF (MODE == 7) THEN
          DASH = '.'
        ELSE
          DASH = '-'
        END IF
      END IF
C * LIST HBONDS (ACC OR SUP)
      IF (MODE == 8) THEN
        DO J = IN01, IN02
          L = JNSC(2, J)
          JLABN = LABB(NINT (VOID(L)))
          CALL PLA047 (JLABN, NQ1, ISOP, IENR, IPR(71), IGBL(55), 0, 1)
          JLABN = LABB(NINT (VOID(L + 1)))
          CALL PLA047 (JLABN, NQ2, ISOP, IENR, IPR(71), IGBL(55), 0, 1)
          JLABN = - LABB(NINT (VOID(L + 2)))
          CALL PLA047 (JLABN, NQ3, ISOP, IENR, IPR(71), IGBL(55), 0, 1)
          ISOP  = NINT (VOID(L + 11))
C * TEST FOR ACC OR SUP
          IF (IPR(431) == 1) THEN
            NQ1(6:7) = '--'
            NQ2(6:7) = '..'
          END IF
C * TEST FOR 1555 (UNIT SYMMETRY OPERATION)
          IF (ISOP == 1) THEN
            GSS(3) = '    .   '
          ELSE
            MISOP  = MOL(ISOP) / 100
            MISOPH = MISOP / 1000
            MISOPT = MISOP - MISOPH * 1000
            WRITE (GSS(3)(1:8), 99991, IOSTAT = IOST) MISOPH, MISOPT
          END IF
          NDECM = IDECM
          M = 0
          DO K = 1, 7, 2
            M = M + 1
            IF (K == 7) NDECM = 2
            DHA(M) = VOID(L + K + 2)
            CALL GEN041 (DHA(M), VOID(L + K + 3), IDHA(M), NDECM,
     1           IDEC, IPR(68))
            IPS = 1 + M * 16
            FORMX(IPS:IPS) = CHAR (ICHAR ('0') + IDEC)
          END DO
          WRITE (PRBUF, FORMX, IOSTAT = IOST) NQ1(1:7), NQ2(1:7),
     1      NQ3(1:7), (DHA(M), IDHA(M), M = 1, 4), GSS(3)
          IF (IDOUBL == 2) WRITE (LU, 99990)
          CALL GEN065 (LU, PRBUF, 1, 80, 1)
        END DO
        RETURN
      END IF
      IF (IDOUBL == 2) WRITE (LU, 99990, IOSTAT = IOST)
      FORMX(2 : 2) = CHAR (ICHAR ('0') + ISPACE)
      NLIN        = MXLIN - LSTART
      ITEL        = LSTART
      IN3         = IPR(231)
      IN1         = IN3 + 1
      IN2         = IN3
C * SELECT AND COPY BEFORE SORTING
      DO J = IN01, IN02
        MJNSC = MOD (JNSC(1, J), IPR(466))
        IF (INCLH /= 0 .OR. MJNSC <= IPR(465)) THEN
          IN2          = IN2 + 1
          JNSC(1, IN2) = MJNSC
          JNSC(2, IN2) = JNSC(2, J)
        END IF
      END DO
C * REARRANGE JNSC FOR PRINTING IN A4-FORMAT WITH NLIN LINES AND
C *    NCOL COLUMS  AND N = IN2 - IN1 + 1 ENTRIES
C * UP TO NCOL - 1 ZERO ENTRIES ARE ADDED IN ORDER TO MAKE THE NUMBER OF
C *  ENTRIES DEVISABLE BY NCOL (N TO INP)
      IC  = NLIN * NCOL
C * IC IS THE NUMBER OF ENTRIES IN A FULL PAGE
      ICP2 = NCOL
      N    = IN2 - IN1 + 1
      INP  = (N + NCOL - 1) / NCOL
      INP  = INP * NCOL
C * MAKE THE LINKS IN JNSC ZERO FOR ENTRIES N + 1 TO INP
      INM  = INP - N
      IN2P = IN2 + INM
      DO J = 1, INM
        JNSC(2, J + IN2) = 0
      END DO
C * IM IS THE TOTAL NUMBER OF PAGES FOR THIS TABEL (THE LAST ONE POSSIBLY
C *    INCOMPLETE)
      IM = (INP + IC - 1) / IC
C * IC3 IS THE NUMBER OF ENTRIES ON THE LAST PAGE
      IC3 = INP - (IM - 1) * IC
C * SUPPLY SORTING INFORMATION FOR JNSC(1, J)
      DO M = 1, IM
        I = (M - 1) * NLIN * NCOL + IN1 - 1
        IF (M >= IM) IC = IC3
C * DETERMINE NUMBER OF LINES IN THIS PAGE
        ICS = IC / NCOL
        DO J = 1, NCOL
          DO K = 1, ICS
            IND = I + (J - 1) * ICS + K
            JNSC(1, IND) = (K - 1) * NCOL + J
          END DO
        END DO
        CALL GEN037 (JNSC, I + 1, I + IC)
      END DO
      K = 0
      DO I = IN1, IN2P
        K = K + 1
        L = JNSC(2, I)
        IF (L <= 0) THEN
          ICP2 = ICP2 - 1
        ELSE
          NHATS = 0
          NHET  = 0
          DO J = 1, JMX
            JLABN = LABB(NINT (VOID(L + J - 1)))
            IF (IPR(431) == -1) JLABN = - JLABN
            CALL PLA047 (JLABN, NQ1, ISOP, IENR, IPR(71),
     1        IGBL(55), 0, 1)
C * TEST FOR H-ATOMS
            IF (IENR == 1) NHATS = NHATS + 1
C * COUNT NUMBER OF HETERO ATOMS (= OTHER THAN CARBON, HYDROGEN)
            IF (IENR > 2) NHET  = NHET  + 1
            NAMS(K, J) = NQ1
            IF (IPR(431) == -1) THEN
              IF (ISOP == 1) THEN
                GSS(J) = '    .   '
              ELSE
                MISOP  = MOL(ISOP) / 100
                MISOPH = MISOP / 1000
                MISOPT = MISOP - MISOPH * 1000
                WRITE (GSS(J), 99991, IOSTAT = IOST) MISOPH, MISOPT
              END IF
            END IF
          END DO
          V2(K) = VOID(L + JMX)
          CALL GEN041 (V2(K), VOID(L + JMX + 1), ISDV(K),
     1                IDECM, IDEC, IPR(68))
          IPS = K * IPS1 - IPS2
          FORMX(IPS : IPS) = CHAR (ICHAR ('0') + IDEC)
        END IF
        IF (K >= NCOL) THEN
          ITEL = ITEL + 1
          IF (ITEL > MXLIN) THEN
            ITEL = LSTART + 1
            IF (IPR(431) == 1) THEN
              IGBL(85) = IGBL(85) + 1
              WRITE (LU, 99999, IOSTAT = IOST) CHAR (12), IGBL(85)
            END IF
            IF (IPR(431) == 1) THEN
              CALL PLA575 (1, LU, CTAB, NTAB, FORMH, JID)
            END IF
            IF (IDOUBL == 2) WRITE (LU, 99990, IOSTAT = IOST)
          END IF
          WRITE (PRBUF, FORMX, IOSTAT = IOST)
     1      ((NAMS(M, J)(1:7), DASH, J = 1, JMX - 1),
     2      NAMS(M, JMX)(1:7), V2(M), ISDV(M), M = 1, ICP2)
          IF (IPR(431) == -1) THEN
            DO M = 1, JMX
              J = 38 + M * 8
              PRBUF(J : J + 8) = GSS(M)
            END DO
            IF (MODE < 7 .AND. NHATS == 0 .AND.
     1        NHET > 0 .AND. JMX < 4) THEN
              PRBUF(78:80) = 'yes'
            ELSE
              PRBUF(78:80) = 'no '
            END IF
          END IF
          CALL GEN065 (LU, PRBUF, 1, 80, 1)
          IF (IPR(431) == 1) WRITE (LU, 99990, IOSTAT = IOST)
          K    = 0
          ICP2 = NCOL
        END IF
      END DO
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT (A, 35X, '-', I3, ' -', /)
99998 FORMAT (/, 'loop_',  6(/, A))
99997 FORMAT (/, 'loop_',  8(/, A))
99996 FORMAT (/, 'loop_', 10(/, A))
99995 FORMAT (/, '#', 79('='), /)
99994 FORMAT ('# 10. MOLECULAR GEOMETRY', /)
99993 FORMAT (A, /, ';', /,
     1 ' Bond distances, angles etc. have been calculated using the',
     2 /,
     3 ' rounded fractional coordinates. All su''s are estimated', /,
     4 ' from the variances of the (full) variance-covariance matrix'
     5 , '.', /, ' The cell esds are taken into account in the',
     6 ' estimation of', /,
     7 ' distances, angles and torsion angles', /,
     7 ';')
99992 FORMAT (/, 'loop_', 9(/, A), /, '#', /,
     1 '#D   H   A   D - H  H...A   D...A    D - H...A  symm(A)', /,
     2 '#')
99991 FORMAT (I3, '_', I3, 1X)
99990 FORMAT (1X)
      END SUBROUTINE PLA573
 
      SUBROUTINE PLA574 (MODE, LU, NCIFDIR, STR, IVAR, VAR)
C * TABLE & CIF CREATION (CONT)
      USE cif
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: MODE
      INTEGER :: IVAR
      INTEGER :: IOST
      INTEGER :: NCIFDIR
      REAL :: VAR
      CHARACTER(len=*) :: STR
C * CHARACTER MODE
      IF (MODE == 1) THEN
        WRITE (LU, 99999, IOSTAT = IOST) CIFDIR(NCIFDIR), STR
C * INTEGER MODE
      ELSE IF (MODE == 2) THEN
        IF (IABS(IVAR) < 999999) THEN
          WRITE (LU, STR, IOSTAT = IOST) CIFDIR(NCIFDIR), IVAR
        ELSE
          WRITE (LU, 99999, IOSTAT = IOST) CIFDIR(NCIFDIR), ' ?'
        END IF
C * REAL VARIABLE MODE
      ELSE IF (MODE == 3) THEN
        IF (ABS(VAR) < 10000.0) THEN
          WRITE (LU, STR, IOSTAT = IOST) CIFDIR(NCIFDIR), VAR
        ELSE
          WRITE (LU, 99999, IOSTAT = IOST) CIFDIR(NCIFDIR), ' ?'
        END IF
      END IF
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT (2A)
      END SUBROUTINE PLA574
 
      SUBROUTINE PLA575 (MODE, LU, CTAB, NTB, FORMX, JID)
C * TABLE & CIF CREATION (CONT)
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: NTB
      INTEGER :: MODE
      INTEGER :: IOST
      CHARACTER(len=*)  :: JID
      CHARACTER(len=1)  :: CTAB
      CHARACTER(len=*)  :: FORMX
      CHARACTER(len=11) :: CHCON
      IF (MODE <= 0) THEN
        N     = 1
        CHCON = ' '
      ELSE
        N     = 11
        CHCON = '(continued)'
      END IF
      IF (MODE == 0) NTB         = NTB + 1
      IF (NTB  > 9) FORMX(19:19) = '2'
      WRITE (LU, FORMX, IOSTAT = IOST) CTAB, NTB, CHCON(1:N), JID(1:40)
      IF (IOST /= 0) RETURN
      RETURN
      END SUBROUTINE PLA575
 
      SUBROUTINE DATE_TIME (DATIJD)
C * RETURN IN DATIJD A 20 CHARACTER LONG STRING EQUIVALENT TO THE
C * CHARACTERS 5-24 IN THE STRING RETURNED BY THE OLD FDATE ROUTINE
 
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      CHARACTER(len=2)  :: T2
      CHARACTER(len=2)  :: T3
      CHARACTER(len=8)  :: DATE
      CHARACTER(len=10) :: TIME
      CHARACTER(len=20) :: DATIJD
      CHARACTER(len=3), DIMENSION(12) :: MONTHS = (/
     1  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep',
     2  'Oct', 'Nov', 'Dec'/)
      CALL DATE_AND_TIME(DATE, TIME)
      READ (DATE, 99998) K, N, I
      READ (TIME, 99997) J, T2, T3
      WRITE (DATIJD, 99999) MONTHS(N), I, J, T2, T3, K
      RETURN
99999 FORMAT (A, 2I3, ':', A, ':', A, I5)
99998 FORMAT (I4, 2I2)
99997 FORMAT (I2, 2A)
      END SUBROUTINE DATE_TIME
 
      SUBROUTINE SPAWN (COMMAND, LU, WACHT, IER)
C * CALL SYSTEM HANDLER ROUTINE
      USE files
      IMPLICIT NONE
      INTEGER, INTENT(OUT) :: IER
      INTEGER              :: IER1 = 0
      INTEGER              :: IER2 = 0
      INTEGER              :: LU
      CHARACTER(len = *), INTENT(IN) :: COMMAND
      LOGICAL, INTENT(IN) :: WACHT
C STRIP_BEG
      IF (LU > 0) WRITE (LU, 99999) COMMAND(1:LEN (COMMAND))
      IF (DOS) THEN
        IER = 0
        CALL EXECUTE_DOS_COMMAND (COMMAND(1:LEN (COMMAND)))
      ELSE
        CALL EXECUTE_COMMAND_LINE (COMMAND(1:LEN (COMMAND)),
     1    WAIT = WACHT, EXITSTAT = IER1, CMDSTAT = IER2)
        IER = IER1 + IER2
      END IF
99999 FORMAT (/, ':: SPAWNED: ', A, /)
C STRIP_END
      RETURN
      END SUBROUTINE SPAWN
 
      SUBROUTINE PRINTX (LU, STR, N1, N2)
      USE files
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: N1
      INTEGER :: N2
      CHARACTER(len=*)  :: STR
      CHARACTER(len=80) :: STR1
      CHARACTER(len=80) :: STR2
      STR1 = ' '
      STR2 = ' '
      IF (N1 == 2) WRITE (STR1, 99998)
      IF (N2 == 2) WRITE (STR2, 99998)
 
      IF (LU /= 0) THEN
        IF (LU == LU6) THEN
          IF (N1 > 0) CALL TRAILER(STR1)
          CALL TRAILER (STR)
          IF (N2 > 0) CALL TRAILER(STR2)
        ELSE
          IF (N1 > 0) WRITE (LU, 99999) STR1
          WRITE (LU, 99999) STR
          IF (N2 > 0) WRITE (Lu, 99999) STR2
        END IF
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT (6('** S-Abort **'))
      END SUBROUTINE PRINTX
 
      SUBROUTINE TRAILER(STR)
C * TRAILER LISTING ON UNIT 6
      USE files
      IMPLICIT NONE
      CHARACTER(len=*) :: STR
      IF (DOS) THEN
        WRITE (6, 99999) STR
      ELSE
        WRITE (LU6, 99999) STR
      END IF
      RETURN
99999 FORMAT (A)
      END SUBROUTINE TRAILER
 
      INTEGER FUNCTION FINDEXE (EXE, PADX, PROGRAMX)
C * GET PATH STRING TO EXECUTABLE INTO PADX
      USE files
      IMPLICIT NONE
      INTEGER :: L
      INTEGER :: LE
      INTEGER :: LP
      INTEGER :: LX
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: LC
      INTEGER :: LH
      INTEGER :: IS
      INTEGER :: NB
      CHARACTER(len=1024) :: P
      CHARACTER(len=*)    :: EXE
      CHARACTER(len=*)    :: PADX
      CHARACTER(len=256)  :: FILEX
      CHARACTER(len=1)    :: DELIM1
      CHARACTER(len=1)    :: DELIM2
      CHARACTER(len=4)    :: SUFFIX
      CHARACTER(len=*)    :: PROGRAMX
      CHARACTER(len=256)  :: COMPONENT
C * PROGRAMX = NAME OF PROGRAM EXECUTABLE SEARCHED FOR (e.g. shelxl)
C * EXE      = ENVIRONMENT VARIABLE WITH PATH TO EXECUTABLE (WHEN PRESENT)
C * PADX     = PATH TO EXECUTABLE (OUTPUT) (e.g. /usr/local/bin/shelxl)
      IF (DOS) THEN
        DELIM1 = CHAR (92)
        DELIM2 = CHAR (59)
        SUFFIX = '.exe'
      ELSE
        DELIM1 = CHAR (47)
        DELIM2 = CHAR (58)
        SUFFIX = ' '
      END IF
C * FIND OUT WHETHER 'PROGRAM' IS AVAILABLE
      L  = LEN (PROGRAMX)
      LE = LEN (EXE)
      LP = LEN (PADX)
      IS = 0
      NB = 1
      CALL GET_ENVIRONMENT_VARIABLE (EXE, VALUE = PADX)
      IF (PADX(1:1) /= ' ') THEN
        CALL GEN039 (1, PADX, 1, LP, NB, IS)
        INQUIRE (FILE = PADX(1:IS), EXIST = EXST)
        IF (.NOT. EXST) THEN
          WRITE (6, 99999) PADX(1:IS)
          STOP
        END IF
      ELSE
C * Get the executable search path from the environment
        CALL GET_ENVIRONMENT_VARIABLE ('PATH', VALUE = P)
        LX = LEN (P)
        NB = 0
        LH = LX
        CALL GEN039 (1, P, 1, LX, NB, LH)
        IF (LH > 0) THEN
          I2 = 0
          DO
            I2 = I2 + 1
            I1 = I2
            IF (I2 > LH) EXIT
C * Look for separating ":" .OR. ";" character
            DO
              IF (ICHAR (P(I2:I2)) == ICHAR (DELIM2) .OR. I2 > LH)
     1          EXIT
              I2 = I2 + 1
            END DO
            IF (I2 == I1) THEN
C * Empty path component is equal to current directory.
              COMPONENT = '.'
              LC = 1
            ELSE
C * Found path component
              COMPONENT = P(I1:I2-1)
              LC = I2 - I1
            END IF
C * CHECK FOR TERMINATING SEPARATOR DELIM1
            IF (COMPONENT(LC:LC) == DELIM1) LC = LC - 1
C * Build file name, and see if it exists
            FILEX = COMPONENT(1:LC)//DELIM1//PROGRAMX(1:L)//SUFFIX
            INQUIRE (FILE = FILEX, EXIST = EXST)
            IF (EXST) THEN
              PADX = FILEX(1:LP)
              CALL GEN039 (1, PADX, 1, LP, NB, IS)
              EXIT
            END IF
C * Next path component, if any
          END DO
        END IF
      END IF
      FINDEXE = IS
99999 FORMAT (/, 'Executable ', A, ' not found! ***', /)
      END FUNCTION FINDEXE
 
 
