      SUBROUTINE SGSM (ISWITS, LIN, X, NRSYM, IOUT, IERROR)
C **********************************************************************
C *                   (C) 1980 - 2026, A.L.Spek                        *
C **********************************************************************
C *                            A.L.SPEK,                               *
C *                       UTRECHT UNIVERSITY,                          *
C *                        THE NETHERLANDS.                            *
C **********************************************************************
C *       SUBROUTINE FOR THE HANDLING OF SPACE GROUP SYMMETRY.         *
C **********************************************************************
C *                CURRENT VERSION  22-04-2026                         *
C **********************************************************************
C *           ------- FORMAL PARAMETER DEFINITION -----------          *
C **********************************************************************
C * LIN   : CONTAINS INFORMATION (A) FOR SPGR, LATT OR SYMM    (INPUT) *
C *         SYMMETRY OPERATION CODE (A)                        (OUTPUT)*
C * NRSYM : REQUESTED NUMBER OF SYMM OPERATION                 (INPUT) *
C *         NRSYM < 0 MEANS ONLY ABS VALUES                            *
C *         (IN LIST MODE: NRSYM = 0    - NO NEWPAGE HANDLING,         *
C *                        NRSYM < 0 - LINE COUNT/NEWPAGE HANDLING)    *
C * X(12) : X, Y, Z, TX, TY, TZ, XN, YN, ZN              (INPUT/OUTPUT)*
C * IOUT  : IOUT = 0 >> NO OUTPUT                                      *
C * ISWITS: SWITCH FOR OPTION SELECTION  (+/-)                 (INPUT) *
C * IERROR: REPORT ERROR                                       (OUTPUT)*
C **********************************************************************
C * ISW = 0  - ACTUAL SWITCH IS DERIVED FROM KEYWORD IN STRING 'LIN'   *
C * ISW = 1  - BRAVAIS LATTICE INIT WITH INSTRUCTION 'LATT P A'        *
C * ISW = 2  - LOAD SYMM_CODE IN STRING 'LIN' FOR PRINTING OF SYMM_OP  *
C * ISW = 3  - TRANSFORM X,Y,Z WITH SPECIFIED SYMMETRY OPERATION       *
C * ISW = 4  - RECIPROCAL SPACE SYMMETRY LISTING                       *
C * ISW = 5  - TRANSFORM SPECIFIED H,K,L AND PHI FOLLOWING SYMM_NUMBER *
C *            INPUT:  X(1),X(2),X(3),X(4)                             *
C *            OUTPUT: X(7),X(8),X(9),X(10)                            *
C * ISW = 6  - OUTPUT SYMMETRY OPERATION IN (R/T) FORMAT IN ARRAY X    *
C * ISW = 7  - GET SYMMETRY NUMBER + TRANSLATION FOR THAT SPECIFIED IN *
C *            X(1),X(2),X(3) TO X(9)-RESULT IN X(9),X(10),X(11),X(12) *
C *            e.g. 1 -X, X + Y, 1/2 - z =>> -1 1 3 0 2 0 12 0 6       *
C * ISW = 8  - MULTIPLY SYMM (R'/T') IN X(1),X(2),X(3),X(4)            *
C *            WITH (R/T) IN  X(5),X(6),X(7),X(8)                      *
C *            RESULT IN X(9),X(10),X(11),X(12)                        *
C * ISW = 9  - INVERT SYMM (R/T) IN X(1),X(2),X(3),X(4)                *
C *            RESULT  IN X(9),X(10),X(11),X(12)                       *
C * ISW = 10 - LATT CARD HANDLING                                      *
C * ISW = 11 - SYMM CARD HANDLING                                      *
C * ISW = 12 - SPGR CARD HANDLING                                      *
C * ISW = 13 - GET INFO ABOUT ACENT = 1, CENTRIC = 2 IN FN(1)          *
C *            NON-SOHNCKE/SOHNCKE (0/1) IN FN(2)                      *
C * ISW = 14 - HELP + LIST INTERNALLY KNOWN SPACE GROUPS ON UNIT IOUT  *
C * ISW = 15 - INPUT R/T MATRIX TROUGH X (R(1,2) = X(2), T(2) = X(11) )*
C * ISW = 16 - SPGR/LATT/SYMM WITH VALID TRANSFORMATION IN X           *
C * ISW = 17 - SAME AS ISW = 2 APART FROM SHELX-TYPE                   *
C * ISW = 18 - SPACE-GROUP INFO IN X (SG-NUMBER,CRYST-SYST, ..)        *
C *            CHARACTER DATA IN LINE                                  *
C * ISW = 19 - ANALYSE FOR SPECIAL POSITION X(1),X(2),X(3)             *
C *            TOL (DEFAULT = 0.0) IN X(10))                           *
C *            OUTPUT IN X(7)...X(12)                                  *
C * ISW = 20 - ISW(2) + TRANSLATION IN X(4), X(5), X(6)                *
C * ISW = 21 - HALL SYMBOL PARSING                                     *
C * ISW = 22 - SAME AS ISW = 7 BUT WITH SYMM LINE                      *
C * ISW = 23 : GET INFO ABOUT EQUIV NONST ORTHORHOMBIC SPACEGROUP      *
C * ISW = 24 - SAME AS ISW = 18 BUT STANDARD SETTINGS ONLY             *
C * ISW = 25 - SAVE SYMMETRY      ON FILE 'SAVESYMM'                   *
C * ISW = 26 - RESTORE SYMMETRY FROM FILE 'SAVESYMM'                   *
C * ISW = 27 - CHECK H,K,L IN X(1)..X(3) FOR ABSENCE;RES:.(0/1/2) X(12)*
C *            INP:X(12) -1 = lattice abs, +1 = non-lat abs, 0 = both  *
C * ISW =      NEGATIVE: LAUE/PATT SYMMETRY                            *
C **********************************************************************
C * SG01 - PARSE HALL SYMBOL IN 'LINE'                                 *
C * SG02 - CONVERT (R|T) INTO SYMM LINE                                *
C * SG03 - (GENERAL) LATTICE INIT ETC. GET TRANSFORMATION MATRIX       *
C * SG04 - FIND OUT ABOUT POSSIBLE INVERSION CENTRE (OUTSIDE (0 0 0)   *
C * SG05 - FILL IR(I, J, N) WITH IS(K, L, NSL) (TRANSPOSED FOR HKL)-   *
C * SG06 - CALCULATE (R'|T')(R|T) = (R'R|R'T + T')                     *
C * SG07 - MAKE SURE THAT THE TRANSLATION PART IS ALWAYS POSITIVE      *
C * SG08 - CHECK WHETHER THIS IS A NEW SYMMETRY OPERATION-             *
C * SG09 -                                                             *
C * SG10 - GET SYMMOP NR + UNITCELL TRANSLATIONS FOR GIVEN OPERATOR    *
C * SG11 - ISW = 8 : MULTIPLY EXTERNALLY SUPPLIED SYMM OP AND RETURN   *
C *          SYMM NR AND UNIT TRL                                      *
C *        ISW = 9 : CALCULATE INVERSE OPERATION FOR GIVEN OPERATION   *
C *          IN (X(1), ... X(4))                                       *
C * SG12 - FIND SPACE GROUP NAME WHEN VOID                             *
C * SG13 - FIND NAME OF NON-STANDARD SPACEGROUP WHEN SGSMC(8:11)       *
C *        NON-BLANK                                                   *
C * SG14 - GET SYMMETRY OPERATORS FOR SPGR                             *
C * SG15 - SYMM_NR TO SYMMETRY (R/T) IN X(1)..X(9) AND X(10)..X(12)    *
C * SG16 -                                                             *
C * SG17 - (GENERAL) LATTICE INIT - GET & HANDLE TRANSFORMATION MATRI  *
C * SG18 - HANDLE SAVESYMM FILE                                        *
C * SG19 - TEST FOR SYMMETRY RECORD                                    *
C * SG20 - INTERPRETE SYMMETRY INFORMATION (SYMM TO R|T)               *
C * SG21 - ENTRY POINT FOR SPGR & HALL - TRANSFORM LATTICE TYPE        *
C * SG22 - INITIALIZE                                                  *
C * SG23 - CHECK WHETHER REFLECTION H K L IS ABSENT                    *
C * SG24 - LIST SPACEGROUP HEADER                                      *
C * SG25 - LOAD SPACEGROUP DATA                                        *
      USE cspgr
      USE csgsx
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: NSM
      INTEGER :: LINM
      INTEGER :: IOUT
      INTEGER :: NRSYM
      INTEGER :: ISWITS
      INTEGER :: IERROR
      REAL, DIMENSION(*) :: X
      CHARACTER(len=*) :: LIN
      CHARACTER(len=4) :: NONSTA
C * TEST/LOAD SPGR DATA
      IF (.NOT. SGTLOADED) CALL SG25
C * COPY FROM ARGUMENT LIST
      LINM  = MIN (80, LEN(LIN))
      LINE  = LIN(1:LINM)
      NSM   = NRSYM
      IUIT  = IOUT
      ILAUE = ISIGN (1, ISWITS)
      ISW   = IABS(ISWITS)
C * INIT DEFAULTS
      IER   = 0
      NIC   = 3
      ISWD  = 1
      LRET  = 3
      NSLP  = 0
      ISTO  = 0
      ITRL  = 0
      ISHEL = 0
      NSGET = 0
      NSLPM = 1
C * GLOBAL TRANSFORMATION MATRIX FLAG
      ITRNS = 0
      NTRNS = 0
      TRDET = 0.0
C * SWITCH SELECTION (SPECIAL SWITCHES FIRST)
      DO
        SELECT CASE (ISW)
C * ISW = 0 : HANDLE AND ACT UPON THE EXPLICIT SGSM KEYWORDS
C *           (LATT/SYMM/SPGR/HALL) IN THE INPUT 'LINE' RECORD
          CASE (0)
C * CONVERT LETTERS IN LINE TO UPPER CASE
            CALL GEN020 (1, LINE, 1, 80)
            SELECT CASE (LINE(1:4))
C * LATT RECORD
              CASE ('LATT')
                ISW = 10
C * SYMM RECORD
              CASE ('SYMM')
C * ELIMINATE BLANKS IN SYMM RECORD
                CALL GEN047 (LINE,   4, 80)
C * BLANK
                CALL GEN038 (SGSMC,  1, 11)
                CALL GEN038 (SGSMC, 15, 60)
                ISW = 11
C * SPGR RECORD
              CASE ('SPGR')
                ISW = 12
C * HALL RECORD
              CASE ('HALL')
                ISW = 21
C * UNKNOWN KEYWORD INSTRUCTION ERROR
              CASE DEFAULT
                IF (IUIT /= 0) THEN
                  WRITE (IUIT, 99997, IOSTAT = IOST) LINE(1:40)
                  IER = 13
                END IF
                IERROR = IER
                RETURN
            END SELECT
            CYCLE
C * ISW = 1 :  (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
          CASE (1)
            CALL SG03 (X, TRDET)
C * SET ISBRV, NST, ICNTR
            IF (IER == 0) CALL SG04
            IERROR = IER
            RETURN
C * ISW = 2 : PRINT SYMM (X,Y,Z) LINES
          CASE (2)
            EXIT
C * ISW = 3 : COORDINATE TRANSFORMATION
          CASE (3)
            ISWD = 1
            CALL SG09 (X, NSM)
            IERROR = IER
            RETURN
C * ISW = 4 : PRINT (H,K,L) LINES
          CASE (4)
            EXIT
C * ISW = 5 : HKL TRANSFORMATION
          CASE (5)
            ISWD = -1
            CALL SG09 (X, NSM)
            IERROR = IER
            RETURN
C * ISW = 6 : LOAD ROTATION MATRIX IN X(1:9) AND TRANSLATION VECTOR
C *           IN X(10:12)
          CASE (6)
C * LOAD ROTATION MATRIX FOR NSM IN X(1:9) AND TRANSLATION VECTOR IN X(10:12)
            CALL SG15 (X, NSM)
            IERROR = IER
            RETURN
C * ISW = 7 : GET SYMMOP NR + UNITCELL TRANSLATIONS FOR GIVEN OPERATOR
          CASE (7)
            CALL SG10 (X)
            IERROR = IER
            RETURN
C * ISW = 8 : MULTIPLY EXTERNALLY SUPPLIED SYMM OP AND RETURN SYMM NR
C *           AND UNIT TRL
          CASE (8)
            CALL SG11 (X)
            IERROR = IER
            RETURN
C * ISW = 9 : CALCULATE INVERSE OPERATION FOR GIVEN OPERATION
C *           IN (X(1), ... X(4))
          CASE (9)
            CALL SG11 (X)
            IERROR = IER
            RETURN
C * ISW = 10 : LATTICE CARD (E.G. LATT -4 or LATT I A)
          CASE (10)
            IABSENT = 0
            CALL SG17 (X, TRDET)
            IERROR = IER
            RETURN
C * ISW = 11 : READ SYMM LINE
          CASE (11)
C * INTERPRETE INPUT SYMMETRY INFO
            IABSENT = 0
            CALL SG20 (-1, X, NSM, LIN)
            IERROR = IER
            RETURN
C * ISW = 12 : SEARCH FOR GENERATORS FOR SPECIFIED SPACE GROUP
          CASE (12)
            IABSENT = 0
            CALL SG14 (X, TRDET)
            IF (IER == 0) THEN
              IF (LRET == 2) THEN
                JBG = -19
C * INTERPRETE INPUT SYMMETRY INFO
                CALL SG20 (-1, X, NSM, LIN)
              END IF
            END IF
            IERROR = IER
            RETURN
C * ISW = 13 : (A)CENTRIC, (NON)SOHNCKE
          CASE (13)
            X(1) = FLOAT (ICNTRX)
            X(2) = FLOAT (IMPROP)
            RETURN
C * ISW = 14 : HELP OPTION
          CASE (14)
            IF (IUIT /= 0) WRITE (IUIT, 99993, IOSTAT = IOST)
            IF (NRSYM > 0) THEN
              IF (IUIT /= 0) WRITE (IUIT, 99995, IOSTAT = IOST)
              READ  (NRSYM, 99990) LINE
            END IF
            IF (IUIT /= 0) THEN
              WRITE (IUIT, 99992, IOSTAT = IOST)
              WRITE (IUIT, 99991, IOSTAT = IOST)
            END IF
            IF (NRSYM > 0) THEN
              IF (IUIT /= 0) WRITE (IUIT, 99995, IOSTAT = IOST)
              READ  (NRSYM, 99990) LINE
            END IF
            IF (IUIT /= 0) THEN
              WRITE (IUIT, 99996, IOSTAT = IOST)
              WRITE (IUIT, 99994, IOSTAT = IOST)
     1          (SGT(I)(1:12), I = 1, NRSPGR)
            END IF
            IF (NRSYM > 0) THEN
              IF (IUIT /= 0) WRITE (IUIT, 99995, IOSTAT = IOST)
              READ  (NRSYM, 99990) LINE
            END IF
            IF (IUIT /= 0) THEN
              WRITE (IUIT, 99999, IOSTAT = IOST) (NOSTP(I), I = 1, 6)
              WRITE (IUIT, 99998, IOSTAT = IOST) (NONST(I), I = 1, NSTD)
            END IF
            RETURN
C * ISW = 15 : HANDLE R/T - MATRIX INPUT THROUGH X
          CASE (15)
C * INTERPRETE INPUT SYMMETRY INFO
            CALL SG20 (-1, X, NSM, LIN)
            IERROR = IER
            RETURN
C * ISW = 16 : APPLY TRANSFORMATION IN X ON SYMMETRY IN LINE
          CASE (16)
            ISW   = 0
            ITRNS = 1
            JBG   = 5
            JEG   = 80
            CYCLE
C * ISW = 17 : SHELX-STYLE SYMM CARDS
          CASE (17)
            ISW   = 2
            ISHEL = 1
            EXIT
C * ISW = 18 : INFO OPTION: SPACE GROUP NUMBER, CRYSTAL SYSTEM,
C *             LAUE GROUP NUMBER, NSYMP, ICNTR, IBV
C *             SPACEGROUP NAME (1:11)
          CASE (18)
            EXIT
C * ISW = 19 : FIND OUT ABOUT SPECIAL POSITION
          CASE (19)
            CALL SG16 (LIN, X)
            IERROR = IER
            RETURN
C * ISW = 20 : PRINT SYMM INCLUDING TRANSLATION
          CASE (20)
            ISW  = 2
            ITRL = 12
            EXIT
C * ISW = 21 : PARSE HALL-SYMBOL
          CASE (21)
            IABSENT = 0
C * (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
            CALL SG03 (X, TRDET)
C * SET ISBRV, NST, ICNTR
            IF (IER == 0) CALL SG04
            IF (IER == 0) THEN
C * BLANK SPGR NAME
              CALL GEN038 (ZSPG, 1, 13)
              DO I = 5, 80
                IF (LINE(I:I) /= ' ') EXIT
              END DO
              IF (LINE(I:I) == '-') THEN
                K = 35
              ELSE
                K = 34
              END IF
              SGSMC(33:) = LINE(I : I + 16)
C * MAKE NON-LATT PART LOWER CASE
              CALL GEN020 (-1, SGSMC, K, 49)
C * PARSE HALL-SYMBOL IN 'LINE'
              CALL SG01 (1)
              IF (IER == 0) THEN
                LRET = 2
                JBG  = -19
C * INTERPRETE INPUT SYMMETRY INFO
                CALL SG20 (-1, X, NSM, LIN)
              END IF
            END IF
            IERROR = IER
            RETURN
C * ISW = 22 : GET SYMM NR FOR SYMM
          CASE (22)
            ISW   = 0
            NSGET = 1
            CYCLE
C * ISW = 23 : GET INFO ABOUT EQUIV NONST ORTHORHOMBIC SPACEGROUP
          CASE (23)
            CALL GEN074 (X, 1, 8, 0.0)
            K = NSLOC(ISGNR - 15)
            IF (K == 0) THEN
              CALL GEN074 (X, 1, 6, 1.0)
            ELSE
              NONSTA = SGSMC(8:11)
              CALL GEN020 (1, NONSTA, 1, 4)
              IF (NONSTA == '    ') NONSTA = 'ABC '
              DO J = 1, 6
                IF (NOSTP(J) == NONSTA) EXIT
              END DO
              DO I = 1, 6
                IF (NONST((K - 1) * 6 + I) .EQ.
     1              NONST((K - 1) * 6 + J)) X(I) = 1
              END DO
            END IF
            IERROR = IER
            RETURN
C * ISW = 24 - SAME AS ISW = 18, STANDARD SETTING ONLY
          CASE (24)
            ISTO = 1
            ISW  = 18
            EXIT
C * ISW = 25
          CASE (25)
            CALL SG18 (1)
            IERROR = IER
            RETURN
C * ISW = 26
          CASE (26)
            CALL SG18 (-1)
            IERROR = IER
            RETURN
C * ISW = 27
          CASE (27)
            CALL SG23 (X)
            IERROR = IER
            RETURN
C * DEFAULT
          CASE DEFAULT
            IERROR = IER
            RETURN
        END SELECT
      END DO
C * SPACE GROUP NAME RECOVERY WHEN NAME-FIELD VOID
      IF (SGSMC(1:1) /= ' ') THEN
        CALL SG13 (LIN, X, NRSYM)
C * FIND NAME OF NON-STANDARD SPACEGROUP WHEN SGSMC(8:11) NON-BLANK
      ELSE
        CALL SG20 (0, X, NSM, LIN)
      END IF
      IF (ISW == 18 .AND. IUIT /= 0)
     1  WRITE (IUIT, 99989) LIN(1:LINM), (X(I), I = 1, 14)
      IERROR = IER
      RETURN
99999 FORMAT (/, 'Nonstandard Settings with Cell Transformations',
     1 ' (see Internat. Tables, Vol A)', /,
     1 46('='), /, 6(A4, 7X), /, 66('-'))
99998 FORMAT (6(1X, A, 1X))
99997 FORMAT (/, 'Line Ignored :', A, /)
99996 FORMAT (/, 4X, 'Space Group Names Known to the Program', //)
99995 FORMAT ('====>> Continue with <CR> <<====')
99994 FORMAT (6(1X, A))
99993 FORMAT (/, 'General Space Group Symmetry Handler - Version:',
     1 ' 16-Feb-2021', //, 'Note: only a subset may be accessible',
     2 //, 'There are Five  Groups of Instructions:', /,
     3 'A - Symmetry Specification with <SPGR>,<LATT>,<SYMM>', /,
     4 'B - Symmetry List Options  with <LIST> and <RLST>', /,
     5 'C - Actual Transformations with <ATOM> and <HKL>', /,
     6 'D - Output of R and T Matrices with <DMAT>', /,
     7 'E - Miscellaneous <TRNS>', //,
     8 '<SPGR> - Symmetry may be Specified as <P21/c>, P21.CAB, etc.',/,
     9 '<LATT> - Contains <P/A/B/C/I/F/R> and <C/A>', /
     * '<SYMM> - e.g. < 1/2-X,1/2+Y,1/2-Z>', /,
     1 '<LIST> - Gives a Listing of the Symmetry in X,Y,Z', /
     2 '<RLST> - Gives a Listing of the Symmetry in H,K,L', /,
     3 '<ATOM> - Specify Three Fractional Coordinates; The', /, 9X,
     4 'Program Generates Symm. Related Positions', /,
     5 '<VECT> - as <ATOM> but with Patterson Symmetry', /,
     6 '<HKL > - Specify H,K,L ; The Program Generates the', /, 9X,
     7 'Symm. Related Set. Specification of a Phase', /, 9X,
     6 'as a Fourth Item Gives Phase Values as Well')
99992 FORMAT ('<DMAT> - Specify Symmetry Number ; The Matrices R '/
     1 '         and T are Returned in Array X(1:12)'/,
     2 '<GSNR> - Specify Coded Symmetry Operation in X(1:9),',/
     3 '         Result: Symmetry Number + Unit Translations',/,
     4 '<MULT> - S1,TX1,TY1,TZ1,S2,TX2,TY2,TZ2',/,
     5 '         RESULT: S3,TX3,TY3,TZ3',/,
     6 '<INVT> - S1,TX1,TY1,TZ1 ; RESULT: S2,TX2,TY2,TZ2',/,
     7 '<TRNS> - T11,T12,..,T33,(S1,S2,S3) : Cell Transform+Shift',/,
     8 '<SITE> - X, Y, Z (Fract. TOL);Output Site Symm Nr in X(12)',/,
     9 '<END> or <STOP> Terminates the Program',/)
99991 FORMAT (/'Remarks:'/'1 - A <LATT> Card Initialises the Number',
     1 ' of Known'/4X,'Symmetry Operations to 1: X,Y,Z'/'2 - A <S',
     2 'YMM> Card is Interpreted as a Generator, so-'/4X,'that at ',
     3 'most 4 <SYMM> Cards are Needed'/'3 - The Program Contains ' ,
     4 'data for all Standard Space'/4X, 'Group Symbols (Including',
     5 ' Some Non-Standard Settings)',/,
     6 '4 - The Sub-word <PATT> Together with <LIST>,<ATOM>',
     7 /14X,'or <LAUE> Together with <RLST>,<HKL>',
     8 /4X,'Generates/Applies the Corresponding Symmetries'/)
99990 FORMAT (A)
99989 FORMAT (A, /, 14F5.0)
      END SUBROUTINE SGSM
 
      SUBROUTINE SG01 (MODE)
C * PARSE HALL-SYMBOL IN 'LINE'
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: LH
      INTEGER :: JB
      INTEGER :: JE
      INTEGER :: IHX
      INTEGER :: NLEV
      INTEGER :: LPAR
      INTEGER :: MODE
      INTEGER :: ISGN
      INTEGER :: ISTAT
      CHARACTER(len=1) :: LNI
      CHARACTER(len=1) :: LN0
C * IHALL (1, NLEV) = ROTATION AXIS OFFSET
C * IHALL (2, NLEV) = SIGN
C * IHALL (3, NLEV) = ROTATION AXIS
C * IHALL (4, NLEV) = GLY-X
C * IHALL (5, NLEV) = GLY-Y
C * IHALL (6, NLEV) = GLY-Z
C * IHALL (7, NLEV) = SHIFT-X
C * IHALL (8, NLEV) = SHIFT-Y
C * IHALL (9, NLEV) = SHIFT-Z
C * NLEV = -1 - START
C * NLEV =  0 - LATTICE TYPE FOUND
C * UPPER CASE
      CALL GEN020 (1, LINE, 1, 80)
      IF (MODE == 1) SGSMC(14:14) = 'A'
      JB    = -19
      JE    = 0
      NLEV  = -1
      ISGN  = 1
      LPAR  = -1
      JLAUE = 8
      ISTAT = 0
      DO L = 1, 4
        DO K = 1, 9
          IHALL(K, L) = 0
        END DO
        IHALL(2, L) = 1
      END DO
C * LOOP OVER CHARACTERS IN 'LINE'
      DO 10 I = 5, 80
        LN0 = LINE(I - 1: I - 1)
        LNI = LINE(I : I)
C * FIRST IDENTIFY LATTICE TYPE & (NON)CENTROSYMMETRY
        IF (NLEV == -1) THEN
          IF (LNI == '-') THEN
            IF (MODE == 1) SGSMC(14:14) = 'C'
          ELSE IF (LNI /= ' ') THEN
C * LOOP OVER LATTICE TYPES P, ...,R
            DO J = 1, 7
              IF (LNI == ICHR(36 + J)) THEN
                IF (ZSPG(1:1) == ' ' .AND. MODE == 1)
     1              SGSMC(13:13) = LNI
                NLEV        = 0
                ISTAT       = 1
                IHALL(1, 1) = 10
                GO TO 10
              END IF
            END DO
          END IF
C * IDENTIFY ROTATIONS
        ELSE
          SELECT CASE (LNI)
            CASE ( '-')
              IF (LPAR < 0) THEN
                NLEV  = NLEV + ISTAT
                IF (NLEV > 4) GO TO 20
                ISTAT          = 0
                IHALL(2, NLEV) = -1
              ELSE
                ISGN = -1
              END IF
            CASE ('(')
              IF (NLEV < 2) GO TO 20
              LPAR = 0
            CASE (')')
            CASE ('0')
              IF (LPAR >= 0) LPAR = LPAR + 1
            CASE ('1')
              IF (LPAR >= 0) THEN
                LPAR = LPAR + 1
                IF (NLEV > 4) GO TO 20
                IHALL(6 + LPAR, NLEV) = ISGN
                ISGN = 1
C * 31
              ELSE IF (LN0 == '3') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 4
C * 41
              ELSE IF (LN0 == '4') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 3
C * 61
              ELSE IF (LN0 == '6') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 2
              ELSE
                NLEV  = NLEV + ISTAT
                IF (NLEV > 4) GO TO 20
                ISTAT = 1
                IHALL(3, NLEV) = 0
              END IF
            CASE ('2')
C * 32
              IF (LN0 == '3') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 8
C * 62
              ELSE IF (LN0 == '6') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 4
              ELSE
                NLEV  = NLEV + ISTAT
                IF (NLEV > 4) GO TO 20
                ISTAT = 1
                IF (NLEV > 1) THEN
                  IHX = IHALL(1, NLEV - 1) + IHALL(3, NLEV - 1)
                ELSE
                  IHX = 0
                END IF
                IF (IHX == 2 .OR. IHX == 4) THEN
                  IHALL(1, NLEV) = 15
                  IHALL(3, NLEV) = 0
                ELSE IF (IHX == 7 .OR. IHX == 9) THEN
                  IHALL(1, NLEV) = 15
                  IHALL(3, NLEV) = 2
                ELSE IF (IHX == 12 .OR. IHX == 14 .OR.
     1                   IHX == 21) THEN
                  IHALL(1, NLEV) = 15
                  IHALL(3, NLEV) = 4
                ELSE
                  IHALL(3, NLEV) = 1
                END IF
              END IF
            CASE ('3')
C * 43
              IF (LN0 == '4') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 9
              ELSE
                NLEV  = NLEV + ISTAT
                IF (NLEV > 4) GO TO 20
                ISTAT = 1
                IHALL(3, NLEV) = 2
                IF (NLEV == 3) THEN
                  IHALL(1, NLEV) = 21
                  IHALL(3, NLEV) = 0
                END IF
              END IF
            CASE ('4')
C * 64
              IF (LN0 == '6') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) + 8
              ELSE
                NLEV  = NLEV + ISTAT
                IF (NLEV > 4) GO TO 20
                ISTAT = 1
                IHALL(3, NLEV) = 3
              END IF
            CASE ('5')
              IF (LN0 == '6') THEN
                IF (NLEV > 4) GO TO 20
                IHALL(6, NLEV) = IHALL(6, NLEV) +  10
              END IF
            CASE ('6')
              NLEV  = NLEV + ISTAT
              IF (NLEV > 4) GO TO 20
              ISTAT = 1
              IHALL(3, NLEV) = 4
            CASE ('X')
              IHALL(1, NLEV) = 0
            CASE ('Y')
              IHALL(1, NLEV) = 5
            CASE ('Z')
              IHALL(1, NLEV) = 10
            CASE ('*')
              IHALL(1, NLEV) = 21
              IHALL(3, NLEV) = 0
            CASE ('''')
              IHALL(1, NLEV) = 15
              IHX = IHALL(1, NLEV - 1)
              IF (IHX == 0) THEN
                IHALL(3, NLEV) = 0
              ELSE IF (IHX == 5) THEN
                IHALL(3, NLEV) = 2
              ELSE
                IHALL(3, NLEV) = 4
              END IF
            CASE ('"')
              JLAUE = 7
              IHALL(1, NLEV) = 15
              IF (NLEV == 1) GO TO 20
              IHX = IHALL(1, NLEV - 1)
              IF (IHX == 0) THEN
                IHALL(3, NLEV) = 1
              ELSE IF (IHX == 5) THEN
                IHALL(3, NLEV) = 3
              ELSE
                IHALL(3, NLEV) = 5
              END IF
            CASE ('A')
              IF (NLEV > 4) GO TO 20
              IHALL(4, NLEV) = IHALL(4, NLEV) + 6
            CASE ('B')
              IF (NLEV > 4) GO TO 20
              IHALL(5, NLEV) = IHALL(5, NLEV) + 6
            CASE ('C')
              IF (NLEV > 4) GO TO 20
              IHALL(6, NLEV) = IHALL(6, NLEV) + 6
            CASE ('N')
              IF (NLEV > 4) GO TO 20
              DO J = 4, 6
                IHALL(J, NLEV) = IHALL(J, NLEV) + 6
              END DO
            CASE ('U')
              IHALL(4, NLEV) = IHALL(4, NLEV) + 3
            CASE ('V')
              IHALL(5, NLEV) = IHALL(5, NLEV) + 3
            CASE ('W')
              IHALL(6, NLEV) = IHALL(6, NLEV) + 3
            CASE ('D')
              DO J = 4, 6
                IHALL(J, NLEV) = IHALL(J, NLEV) + 3
              END DO
          END SELECT
        END IF
   10 CONTINUE
      IF (NLEV > 0) THEN
        IF (MODE == 1) CALL SG04
        IF (IER == 0) THEN
          CALL GEN038 (LINE, 1, 80)
          DO LH = 1, NLEV
            JB = JB + 20
            JE = JE + 20
            M  = (IHALL(1, LH) + IHALL(3, LH)) * 9
            DO J = 1, 3
              DO I = 1, 3
                K = (J - 1) * 3 + I
                R0(I, J) = NHRM(M + K) * IHALL(2, LH)
              END DO
            END DO
            DO K = 1, 3
              T0(K) = (IHALL(3 + K, LH) + IHALL(6 + K, LH)) / 12.0
            END DO
            DO I = 1, 3
              DO J = 1, 3
                T0(I) = T0(I) - R0(I, J) * IHALL(6 + J, LH) / 12.0
              END DO
            END DO
            NTRNS = ITRNS
C * CONVERT (R0|T0) INTO SYMM LINE
            CALL SG02 (JB)
            IF (IER /= 0) GO TO 20
          END DO
        END IF
        IF (IER == 0) RETURN
      END IF
   20 IER = 7
      RETURN
      END SUBROUTINE SG01
 
      SUBROUTINE SG02 (JB)
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: JB
      INTEGER :: NR0
      INTEGER :: NTRV
      INTEGER :: NTRVN
      REAL :: TRV
C * CONVERT (R|T) INTO SYMM LINE
C * BLANK
      CALL GEN038 (LINE, JB, JB + 19)
      K = JB
      DO I = 1, 3
        TRV  = AMOD (T0(I) * 12.0, 12.0)
        NTRV = NINT (TRV)
        IF (ABS (TRV - NTRV) > 0.1) THEN
          IF (IUIT /= 0)
     1      WRITE (IUIT, 99999, IOSTAT = IOST) (T0(K), K = 1, 3)
          IER = 8
          RETURN
        END IF
        NTRVN = 12
        IF (NTRV /= 0) THEN
          IF (NTRV < 0) NTRV = NTRV + 12
          IF (NTRV > 0) THEN
            DO WHILE (.TRUE.)
              IF (MOD (NTRV, 2) == 0 .AND. MOD (NTRVN, 2) == 0) THEN
                NTRV  = NTRV  / 2
                NTRVN = NTRVN / 2
                CYCLE
              ELSE IF (MOD (NTRV, 3) == 0 .AND. MOD (NTRVN, 3) == 0)
     1          THEN
                NTRV  = NTRV  / 3
                NTRVN = NTRVN / 3
                CYCLE
              ELSE
                LINE(K:K+2) = ICHR(NTRV)//'/'//ICHR(NTRVN)
                K = K + 3
                EXIT
              END IF
            END DO
          END IF
        END IF
        DO J = 1, 3
          IF (ABS (R0(I, J)) > 0.9) THEN
            NR0 = NINT (R0(I, J))
            IF (NR0 > 0) THEN
              LINE(K:K) = '+'
            ELSE
              LINE(K:K) = '-'
            END IF
            LINE(K + 1:K + 1) = ICHR(11 + J)
            K = K + 2
          END IF
        END DO
        IF (I < 3) THEN
          LINE(K:K) = ','
          K = K + 1
        END IF
      END DO
      RETURN
99999 FORMAT (/, 'E: SYMM TRANSLATION n/a:', 3F8.3)
      END SUBROUTINE SG02
 
      SUBROUTINE SG03 (X, DET)
C * (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      REAL :: DET
      REAL, DIMENSION(*) :: X
      IF (ITRNS == 0) THEN
C * INIT TO UNIT TRANSFORMATION
        CALL GEN021 (R1, 1.0)
        CALL GEN074 (OSFT, 1, 3, 0.0)
        DET = 1
C * LOAD ORIENTATION AND ORIGIN SHIFT DATA
      ELSE
        K = 0
        DO I = 1, 3
          OSFT(I) = - X(I + 9)
          DO J = 1, 3
            K        = K   + 1
            R1(J, I) = X(K)
          END DO
        END DO
C * R1 CONTAINS TRNS TRANSPOSE; R2 RECEIVES TTRNS-1 TRANSPOSE
        CALL GEN003 (R1, R4, DET, 0)
        DO I = 1, 3
          DO J = 1, 4
            IF (J == 4) THEN
              R2(I, J) = 0.0
            ELSE
              R2(I, J) = R4(I, J)
            END IF
          END DO
        END DO
C * CHECK FOR REVERSE HEXAGONAL SETTING
        IF (NINT (DET) == 3) THEN
          IF (R1(1, 1) == -1.0 .AND. R1(1, 2) ==  0.0 .AND.
     1        R1(1, 3) ==  1.0 .AND. R1(2, 1) ==  1.0 .AND.
     2        R1(2, 2) == -1.0 .AND. R1(2, 3) ==  1.0 .AND.
     3        R1(3, 1) ==  0.0 .AND. R1(3, 2) ==  1.0 .AND.
     4        R1(3, 3) ==  1) THEN
            IER = 14
            IF (IUIT /= 0) WRITE (IUIT, 99998, IOSTAT = IOST)
            RETURN
          END IF
C * CHECK FOR TRANSFORMATION WITH DETERMINANT = ZERO
        ELSE IF (ABS(DET) < 0.1) THEN
          IF (IUIT /= 0)
     1      WRITE (IUIT, 99999, IOSTAT = IOST)
     2        DET, ((R1(I, J), I = 1, 3), J = 1, 3)
          IER = 11
          RETURN
        END IF
      END IF
C * NOT SYMM LINE TEST
      IF (ISW /= 11) CALL SG22
      RETURN
99999 FORMAT (':: Transformation Matrix with Determinant =', F6.3, //,
     1 3(3F10.3, /))
99998 FORMAT (':: Transformation to Reverse Setting not Allowed', /,
     1        '   Use (1 -1 0 0 1 -1 1 1 1) for rR to hR.', /)
      END SUBROUTINE SG03
 
      SUBROUTINE SG04
      USE cspgr
      USE spgrdata
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: IBVP
      INTEGER :: NSYMX
      IF (SGSMC(14:14) == 'C') THEN
        ICNTR  = 2
        IFLACK = 0
      ELSE
        ICNTR = 1
      END IF
C * FIND OUT ABOUT POSSIBLE INVERSION CENTRE (OUTSIDE 0,0,0)
      ICNTRX = ICNTR
      NSYMX  = NSYMP
      OCNT(1) = 0.0
      OCNT(2) = 0.0
      OCNT(3) = 0.0
      IF (ICNTR == 1 .AND. NSYMP > 1) THEN
        DO 10 I = 2, NSYMP
          DO K = 1, 3
            IF (IS(2, K, I) /=   0) GO TO 10
            IF (IS(1, K, I) /= - K) GO TO 10
          END DO
          DO K = 1, 3
            OCNT(K) = FLOAT (IS(3, K, I)) / 24
          END DO
          ICNTRX = 2
          IFLACK = 0
          NSYMX  = NSYMP / 2
          EXIT
   10   CONTINUE
      END IF
      DO K = 1, 7
        IF (SGSMC(13:13) == ICHR(K + 29)) THEN
          IBV  = IBV0(K)
          IBVP = IBV1(K)
          DO J = 1, IBV
            DO I = 1, 3
              IF (J == 1) THEN
                ISBRV(J, I) = 0
              ELSE
                ISBRV(J, I) = IBV2(IBVP)
                IBVP        = IBVP + 1
              END IF
            END DO
          END DO
          IF (ILAUE < 0) THEN
            IINV = 2
          ELSE
            IINV = ICNTR
          END IF
          NST  = NSYMP * IBV * IINV
C * GET CRYSTAL SYSTEM
          IKLS  =  8
          LAUE  = 13
          IF (NSYMX == 1) THEN
C * TRICLINIC
            IKLS = 1
C * -1
            LAUE = 1
          ELSE IF (NSYMX == 2) THEN
C * MONOCLINIC
            IKLS = 2
C * 2/m
            LAUE = 2
      ELSE IF (IAXM == 6) THEN
C * HEXAGONAL
            IKLS = 6
            IF (NSYMX == 6) THEN
C * 6/m
              LAUE = 9
            ELSE
C * 6/mmm
              LAUE = 10
            END IF
          ELSE IF (NSYMX >= 12) THEN
C * CUBIC
            IKLS = 7
            IF (NSYMX == 12) THEN
C * m-3
              LAUE = 11
            ELSE
C * m-3m
              LAUE = 12
            END IF
          ELSE IF (IAXM == 4) THEN
C * TETRAGONAL
            IKLS = 4
            IF (NSYMX == 4) THEN
C * 4/m
              LAUE = 4
            ELSE
C * 4/mmm
              LAUE = 5
            END IF
          ELSE IF (IAXM == 3) THEN
C * TRIGONAL/RHOMBOHEDRAL
            IKLS = 5
            IF (NSYMX == 3) THEN
C * -3
              LAUE = 6
            ELSE
C * -3m1 or -31m
              LAUE = 14
            END IF
          ELSE IF (NSYMX == 4) THEN
C * ORTHORHOMBIC
            IKLS  = 3
C * mmm
            LAUE  = 3
          END IF
          JSMI = NSG(2 * LAUE - 1)
          JSMX = NSG(2 * LAUE)
C * DETERMINE RHOMBOHEDRAL OR HEXAGONAL SETTING FOR TRIGONAL
          IF(IKLS == 5 .AND. IABS (IS(1, 3, 2)) == 3) THEN
            SGSMC(12:12) = IBVL(6)
          ELSE
            SGSMC(12:12) = IBVL(IKLS)
          END IF
          RETURN
        ENDIF
      END DO
      IF (IUIT /= 0) WRITE (IUIT, 99999, IOSTAT = IOST) SGSMC(13:13)
      IER = 10
      RETURN
99999 FORMAT (':: Unknown LATTICE Type:', A)
      END SUBROUTINE SG04
 
      SUBROUTINE SG05 (N, NSL, INVOKED)
C * FILL IR(I, J, N) WITH IS(K, L, NSL) (TRANSPOSED FOR HKL)
      USE cspgr
      IMPLICIT NONE
      INTEGER :: INVOKED
      INTEGER :: I
      INTEGER :: K
      INTEGER :: N
      INTEGER :: NS
      INTEGER :: NS0
      INTEGER :: NS1
      INTEGER :: NS2
      INTEGER :: INH
      INTEGER :: NSL
      INTEGER :: INHD
C * N     - TARGET POSITION IN ARRAY IR()
C * NS    - NUMBER SYMMETRY OPERATION OUT OF NSYMP
C * NS0   - 0/1 INVERSION
C * NSL   - NUMBER SYMMETRY OPERATION
C * NSYMP - NUMBER SYMMETRY OPERATIONS EXCLUDING BRAVAIS AND INVERSION
      IF (NSL == 0) THEN
        IF (IUIT /= 0) WRITE (IUIT, 99996, IOSTAT = IOST) INVOKED
        IER = 9
        RETURN
      END IF
      NS0 = (IABS (NSL) - 1) / NSYMP
      NS  =  IABS (NSL) - NS0 * NSYMP
      IF (NS < 1) THEN
        IF (IUIT /= 0)
     1    WRITE (IUIT, 99998, IOSTAT = IOST) NSL, NSYMP, NS0, NS,ISW
        IER = 5
        RETURN
      END IF
      IF (ILAUE < 0) THEN
        IINV = 2
      ELSE
        IINV = ICNTR
      END IF
      NS2 = NS0 / IINV
      NS1 = NS0 + 1 - NS2 * IINV
      NS2 = NS2 + 1
      IF (NS2 < 1 .OR. NS2 > 4) THEN
        IF (IUIT /= 0)
     1    WRITE (IUIT, 99999, IOSTAT = IOST) NS0, NS1, NS2, IINV
        IER = 4
        RETURN
      END IF
      IF (N < 1 .OR. N > 195) THEN
        IF (IUIT /= 0)
     1    WRITE (IUIT, 99997, IOSTAT = IOST) NS, NS0, NS1, NS2, IINV, N
        IER = 3
        RETURN
      END IF
      DO I = 1, 3
        IR(1, I, N) = 0
        IR(2, I, N) = 0
      END DO
      DO I = 1, 3
        DO K = 1, 3
          INH = IS(K, I, NS)
          IF (NS1 == 2) INH = - INH
          IF (K == 3) THEN
            IF (ILAUE > 0) THEN
              INH = MOD (INH + ISBRV(NS2, I), 12)
            ELSE
              INH = MOD (ISBRV(NS2, I), 12)
            END IF
            IF (INH < 0) INH = INH + 12
            IR(K, I, N) = INH
          ELSE IF (ISWD > 0) THEN
            IR(K, I, N) = INH
          ELSE IF (INH /= 0) THEN
            IF (INH < 0) THEN
              INHD = - I
              INH  = - INH
            ELSE
              INHD =  I
            END IF
            IF (IR(1, INH, N) == 0) THEN
              IR(1, INH, N) = INHD
            ELSE
              IR(2, INH, N) = INHD
            END IF
          END IF
        END DO
      END DO
      RETURN
99999 FORMAT ('SGSM Problem:NS0,NS1,NS2,IINV = ', 4I10,
     1        'NS2 < 1 OR NS2 > 4')
99998 FORMAT ('NS < 1 ERROR IN (SGSM)', /,
     1        'NSL, NSYMP, NS0, NS, ISW =', 5I10, /)
99997 FORMAT ('E: SPGR-Problem', 6I5, /)
99996 FORMAT ('nsl = 0 in SG05 From', I4)
      END SUBROUTINE SG05
 
      SUBROUTINE SG06
C * CALCULATE (R'|T')(R|T) = (R'R|R'T+T')
      USE cspgr
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: ISJ
      INTEGER :: ISS
      INTEGER :: ISX
      INTEGER :: ISY
      INTEGER :: ITS
      DO K = 1, 3
        DO M = 1, 3
          ISV(M) = 0
        END DO
        ITS = IR(3, K, 193)
        DO L = 1, 2
          ISJ = IR(L, K, 193)
          IF (ISJ /= 0) THEN
            ISS = IR(3, IABS (ISJ), 194)
            IF (ISJ < 0) ISS = - ISS
            ITS = ITS + ISS
            DO M = 1, 2
              ISX = IR(M, IABS (ISJ), 194)
              IF (ISJ < 0) ISX = - ISX
              IF (ISX /= 0) THEN
                ISY = IABS (ISX)
                ISV(ISY) = ISV(ISY) + ISX
              END IF
            END DO
          END IF
        END DO
        IR(2, K, 195) = 0
        N = 0
        DO M = 1, 3
          IF (ISV(M) /= 0) THEN
            N             = N + 1
            IR(N, K, 195) = ISV(M)
          END IF
        END DO
        IR(3, K, 195) = ITS
      END DO
      RETURN
      END SUBROUTINE SG06
 
      SUBROUTINE SG07
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: NSM
      INTEGER :: NSP
      INTEGER :: IAX
      INTEGER :: ISN
      INTEGER :: ITS
      INTEGER :: ISLK
      INTEGER :: ISLKA
      INTEGER :: ISCOD
C * MAKE SURE THAT THE TRANSLATION PART IS ALWAYS POSITIVE (IT-STANDARD)
      DO K = 1, 3
        ITS = MOD (IR(3, K, 195), 12)
        IF (ITS < 0) ITS = ITS + 12
        IR(3, K, 195) = ITS
      END DO
      NSP  = -1
      CALL SG08 (NSP)
      IF (IER == 0) THEN
        IF (NSP < 0) THEN
          IF (NSYMP < 48) THEN
            NSYMP = NSYMP + 1
            DO L = 1, 3
              DO K = 1, 3
                ISLK            = IR(L, K, 195)
                IS(L, K, NSYMP) = ISLK
                ISLKA           = IABS (ISLK)
                IF (L < 3 .AND. ISLK /= 0) THEN
                  IF (ISLKA < 4)  THEN
                    IORG(ISLKA, K) = IORG(ISLKA, K) + ISLK
                  ELSE
                    IF (IUIT /= 0) WRITE (IUIT, 99998, IOSTAT = IOST)
                    IER = 12
                    RETURN
                  END IF
                END IF
              END DO
            END DO
            IF (IS(1, 3, NSYMP) > 0) THEN
              ISN =  100000
            ELSE
              ISN = -100000
            END IF
            ISCOD = 555555
            DO K = 1, 3
              DO L = 1, 2
                ISCOD = ISCOD + ISN * IS(L, K, NSYMP)
                ISN = ISN / 10
              END DO
            END DO
            IF (ISCOD == 356385 .OR. ISCOD == 856575) THEN
              IAX = 3
            ELSE IF (ISCOD == 356585) THEN
              IAX = 4
            ELSE IF (ISCOD == 636585) THEN
              IAX = 6
            ELSE
              IAX = 0
            END IF
            IAXM = MAX (IAXM, IAX)
          ELSE
            IF (IUIT /= 0) WRITE (IUIT, 99999, IOSTAT = IOST)
            IER = 6
            RETURN
          END IF
C * NSP > 0
        ELSE IF (NSP > 0) THEN
          NSM = 1
          DO
            NSM = NSM + 1
            IF (NSM > 1 .AND. NSM <= NSYMP) THEN
              NSP = -1
              DO I = 1, 3
                DO J = 1, 3
                  IR(I, J, 195) = IS(I, J, NSM)
                END DO
              END DO
              NSP = -1
              CALL SG08 (NSP)
              IF (NSP > 0) THEN
                IF (NSM < NSYMP) THEN
                  DO I = 1, 3
                    DO J = I, 3
                      IS(I, J, NSM) = IS(I, J, NSYMP)
                    END DO
                  END DO
                END IF
                NSYMP = NSYMP - 1
              END IF
            ELSE
              EXIT
            END IF
          END DO
        END IF
      ENDIF
      RETURN
99999 FORMAT (':: Attempt to generate more than 48 ''non-LATT'' ',
     1        'operations', /, '   ** Please check symmetry operations'
     2        , /, '   ** No additional operations accepted!')
99998 FORMAT (':: Problem in SG07 - ERR = 12')
      END SUBROUTINE SG07
 
      SUBROUTINE SG08 (NSP)
      USE cspgr
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: NSM
      INTEGER :: NSP
      INTEGER :: IDV
      INTEGER :: IDT
      INTEGER :: ISN
      INTEGER :: IDT0
      INTEGER :: IDIF
      CHARACTER(len=1) :: JBRV
      CHARACTER(len=1) :: JCNT
C * CHECK WHETHER THIS IS A NEW SYMMETRY OPERATION
 
      JBRV = SGSMC(13:13)
      JCNT = SGSMC(14:14)
      CALL GEN038 (SGSMC, 1, 11)
      DO NSM = 1, NSYMP
        L = NSM
        DO M = 1, 3, 2
          ISN  = 2 - M
          IDIF = 0
          IDT  = 0
          IDT0 = 0
          DO K = 1, 3
            IDIF = IDIF + IABS (IS(1, K, L) - ISN * IR(1, K, 195))
     1                  + IABS (IS(2, K, L) - ISN * IR(2, K, 195))
            IDV  = MOD (IS(3, K, L) - ISN * IR(3, K, 195), 12)
            IF (IDV < 0) IDV = IDV + 12
C * NOTE R-LATTICE CENTERING (4 = 1/3, 8 = 2/3)
            IF (IDV == 4 .OR. IDV == 8) THEN
              IDT = IDT + IDV * 10**(3 - K)
C * NOTE A, B, C, F, I LATTICE (6 = 1/2)
            ELSE IF (IDV == 6) THEN
              IDT = IDT + 2**(3 - K)
            END IF
            IDT0 = IDT0 + IDV
          END DO
          IF (IDIF == 0) THEN
            IF (IDT0 == 0) THEN
              NSP = 0
              IF (ISN < 0) THEN
                IF (JCNT == 'A') THEN
                  SGSMC(14:14) = 'C'
                  NSP = 8
                END IF
              END IF
              RETURN
            ELSE IF (IDT == 3) THEN
              IF (JBRV == 'A' .OR. JBRV == 'F') THEN
                NSP = 0
                IF (ISN < 0) THEN
                  SGSMC(14:14) = 'C'
                  NSP = 8
                END IF
                RETURN
              ELSE IF (ISN > 0) THEN
                NSP = 0
                IF (JBRV == 'P') THEN
                  SGSMC(13:13) = 'A'
                  NSP = 2
                ELSE IF (JBRV /= 'F') THEN
                  SGSMC(13:13) = 'F'
                  NSP = 5
                END IF
                RETURN
              END IF
            ELSE  IF (IDT == 5) THEN
              IF (JBRV == 'B' .OR. JBRV == 'F') THEN
                NSP = 0
                IF (ISN < 0) THEN
                  SGSMC(14:14) = 'C'
                  NSP = 8
                END IF
                RETURN
              ELSE IF (ISN > 0) THEN
                NSP = 0
                IF (JBRV == 'P') THEN
                  SGSMC(13:13) = 'B'
                  NSP = 3
                ELSE IF (JBRV /= 'F') THEN
                  SGSMC(13:13) = 'F'
                  NSP = 5
                END IF
                RETURN
              END IF
            ELSE IF (IDT == 6) THEN
              IF (JBRV == 'C' .OR. JBRV == 'F') THEN
                NSP = 0
                IF (ISN < 0) THEN
                  SGSMC(14:14) = 'C'
                  NSP = 8
                END IF
                RETURN
              ELSE IF (ISN > 0) THEN
                NSP = 0
                IF (JBRV == 'P') THEN
                  SGSMC(13:13) = 'C'
                  NSP = 4
                ELSE IF (JBRV /= 'F') THEN
                  SGSMC(13:13) = 'F'
                  NSP = 5
                END IF
                RETURN
              ELSE IF (ISN < 0) THEN
                IF (JBRV == 'P' .AND. JCNT == 'C') THEN
                  SGSMC(13:13) = 'C'
                  NSP  = 4
                  RETURN
                ENDIF
              END IF
            ELSE IF (IDT == 7) THEN
              IF (JBRV == 'I') THEN
                NSP = 0
                IF (ISN < 1) THEN
                  SGSMC(14:14) = 'C'
                  NSP = 8
                END IF
                RETURN
              ELSE IF (ISN > 0) THEN
                NSP = 0
                IF (JBRV /= 'I') THEN
                  SGSMC(13:13) = 'I'
                  NSP = 6
                END IF
                RETURN
              END IF
C * TEST FOR R-Obverse
            ELSE IF (IDT == 488 .OR. IDT == 844) THEN
              IF (JBRV == 'R') THEN
                NSP = 0
                IF (ISN < 0) THEN
                  SGSMC(14:14) = 'C'
                  NSP = 8
                END IF
                RETURN
              ELSE IF (ISN > 0) THEN
                NSP  = 0
                IF (JBRV /= 'R') THEN
                  SGSMC(13:13) = 'R'
                  NSP = 7
                END IF
                RETURN
              END IF
C * TEST FOR R-Reverse
            ELSE IF (IDT == 848 .OR. IDT == 484) THEN
              IF (IUIT /= 0) WRITE (IUIT, 99999, IOSTAT = IOST)
              IER = 14
              RETURN
            END IF
          END IF
        END DO
      END DO
      RETURN
99999 FORMAT (':: (Transformation to) Obverse Setting Not Allowed.')
      END SUBROUTINE SG08
 
      SUBROUTINE SG09 (X, NSM)
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NSL
      INTEGER :: ISJ
      INTEGER :: NSM
      INTEGER :: ISKP
      INTEGER :: NSTOT
      REAL :: X10
      REAL :: XISJ
      REAL, DIMENSION(*) :: X
      IF (ILAUE < 0 .AND. ICNTR == 1) THEN
        NSTOT = NST * 2
        JSWD  = 0
        ISKP  = 0
      ELSE
        NSTOT = NST
        ISKP  = 1
      END IF
      IF (ISWD /= JSWD) THEN
C * LOAD APPROPRIATE MATRICES IN IR
        DO N = 1, NSTOT
          NSL = N
C * FILL IR(I, J, N) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
          CALL SG05 (NSL, NSL, 91)
          IF (IER /= 0) RETURN
        END DO
        JSWD = ISWD * ISKP
      END IF
      N = IABS(NSM)
      DO J = 1, 3
        IF (NSM > 0) THEN
C * TEST FOR HKL TRANSFORMATION
          IF (ISWD < 0) THEN
            X(J + 6) = 0.0
C * CALCULATE PHASE OF TRANSFORMED REFLECTION
            IF (J == 1) X(10) = X(4) / 360.0
            X(10) = X(10) - IR(3, J, N) * X(J) / 12.0
C * COORDINATE TRANSFORMATION
          ELSE
            X(J + 6) = IR(3, J, N) / 12.0 + X(J + 3)
          END IF
        ELSE
          X(J + 6) = 0.0
        END IF
        DO I = 1, 2
          IF (N > 0 .AND. N < 196) THEN
            ISJ = IR(I, J, N)
          ELSE
            ISJ = 0
          END IF
          IF (ISJ /= 0) THEN
            XISJ = X(IABS (ISJ))
            IF (ISJ < 0 .AND. NSM >= 0) XISJ = - XISJ
            X(J + 6) = X(J + 6) + XISJ
          END IF
        END DO
      END DO
C * TEST FOR HKL TRANSFORMATION
      IF (ISWD < 0) THEN
        X10 = MOD(X(10), 1.0)
        IF (X10 > 0.5) THEN
          X10 = X10 - 1.0
        ELSE IF (X10 <= -0.5) THEN
          X10 = X10 + 1.0
        END IF
        X(10) = X10 * 360.0
      END IF
      RETURN
      END SUBROUTINE SG09
 
      SUBROUTINE SG10 (X)
C * GET SYMMOP NR + UNITCELL TRANSLATIONS FOR GIVEN OPERATOR
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: NSL
      INTEGER :: IDIF
      REAL, DIMENSION(*) :: X
      NSL = NST
C * FILL IR(I, J, 195) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
   10 CALL SG05 (195, NSL, 101)
      IF (IER == 0) THEN
        K = 0
        DO I = 1, 3
          DO J = 1, 3
            K = K + 1
            IDIF = IFIX (X(K)) - IR(I, J, 195)
            IF (I == 3) THEN
              X(9 + J) = FLOAT (IDIF / 12)
              IDIF     = MOD (IDIF, 12)
            END IF
            IF (IDIF /= 0) THEN
              NSL = NSL - 1
              IF (NSL > 0) THEN
                GO TO 10
              ELSE
                X(9) = NSL
                RETURN
              END IF
            END IF
          END DO
        END DO
        X(9) = NSL
      END IF
      RETURN
      END SUBROUTINE SG10
 
      SUBROUTINE SG11 (X)
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: NSL
      INTEGER :: ISJ
      INTEGER :: ISS
      INTEGER :: ITS
      REAL, DIMENSION(*) :: X
      IF (ISW == 9) X(5) = NST
      N   = 193
      NSL = NINT(X(1))
C * FILL IR(I, J, N) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
      CALL SG05 (N, NSL, 111)
      IF (IER == 0) THEN
        DO K = 1, 3
          IR(3, K, 193) = IR(3, K, 193) + NINT(X(K + 1)) * 12
        END DO
C * LOAD SECOND SYMMETRY OPERATION FROM (X(5) .... X(8))
        N   = 194
   10   NSL = NINT(X(5))
        IF (NSL == 0) THEN
          IF (IUIT /= 0)
     1      WRITE (IUIT, 99998, IOSTAT = IOST)
          IER = 1
          RETURN
        END IF
C * FILL IR(I, J, N) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
        CALL SG05 (N, NSL, 112)
        IF (IER == 0) THEN
          IF (ISW /= 9) THEN
            DO K = 1, 3
              IR(3, K, 194) = IR(3, K, 194) + NINT (X(5 + K)) * 12
            END DO
          END IF
C * CALCULATE (R'/T')(R/T) = (R'R/R'T+T')
          CALL SG06
          IF (ISW == 9) THEN
            DO K = 1, 3
              IF (IR(1, K, 195) /= K) GO TO 20
              IF (IR(2, K, 195) /= 0) GO TO 20
              IF (MOD (IABS (IR(3, K, 195)), 12) /= 0) GO TO 20
              ITS = - IR(3, K, 194)
              DO I = 1, 2
                ISJ = IR(I, K, 194)
                IF (ISJ /= 0) THEN
                  ISS = IR(3, IABS (ISJ), 193)
                  IF (ISJ < 0) ISS = - ISS
                  ITS = ITS - ISS
                END IF
              END DO
              X(9 + K) = FLOAT (ITS / 12)
            END DO
            X(9) = X(5)
            RETURN
   20       X(5) = X(5) - 1
            IF (X(5) > 0) THEN
              GO TO 10
            ELSE
              IF (IUIT /= 0) WRITE (IUIT, 99999, IOSTAT = IOST)
              IER = 1
              RETURN
            END IF
          END IF
          K = 0
          DO I = 1, 3
            DO J = 1, 3
              K = K + 1
              X(K) = IR(I, J, 195)
            END DO
          END DO
C * GET SYMMOP NR + UNITCELL TRANSLATIONS FOR GIVEN OPERATOR
          CALL SG10 (X)
        END IF
      END IF
      RETURN
99999 FORMAT ('Error at Label 20 in routine SGSM/SG11')
99998 FORMAT ('Supplied Symmetry number = 0 (ERROR in SG11')
      END SUBROUTINE SG11
 
      SUBROUTINE SG12 (X, NSM)
C * FIND SPACE GROUP NAME WHEN VOID
      USE cspgr
      USE spgrdata
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NSL
      INTEGER :: IND
      INTEGER :: NSM
      INTEGER :: NSLB
      INTEGER :: NSLX
      INTEGER :: ICHS
      INTEGER :: NRSM
      REAL :: TRV
      REAL, DIMENSION(*) :: X
      K    = 0
      NSL  = 1
      NRSM = NSM
      ISWD = 3 - ISW
      IF (ICNTR == 1 .AND. ILAUE < 0) THEN
        NSTT = NST * 2
      ELSE
        NSTT = NST
      END IF
      IF (ISWD < 0) NSTT = NSTT / IBV
      IF (NRSM > NSTT) NRSM = MOD (NRSM, NSTT)
      IF (NRSM /= 0) THEN
        NSL  = NRSM
        NSTT = NRSM
      ELSE
        CALL SG24
      END IF
C * SELECT X,Y,Z (ISW = 2) or H,K,L (ISW = 4)  OUTPUT FORMAT
      IF (ISW == 4) THEN
        ICHS = 26
      ELSE
        ICHS = 11
      END IF
      NSLB = NSL
      DO NSLX = NSLB, NSTT
        NSL = NSLX
        N   = 195
C * FILL IR(I, J, N) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
        CALL SG05 (N, NSL, 121)
        IF (IER /= 0) RETURN
        CALL GEN038 (LINE, 1, 80)
C * BUILD SYMMETRY OPERATION RECORD
        DO I = 1, 3
          IND = 17 * I - 4 + ISHEL * 4
          IF (I < 3) LINE(IND + 2:IND + 2) = ','
          M = IR(2, I, N)
          IF (M /= 0) THEN
            LINE(IND:IND) = ICHR(IABS (M) + ICHS)
            IF (M < 0) THEN
              LINE(IND - 2:IND - 2) = '-'
            ELSE
              LINE(IND - 2:IND - 2) = '+'
            END IF
            IND = IND - 4
          END IF
          LINE(IND:IND) = ICHR(IABS (IR(1, I, N)) + ICHS)
          IF (IR(1, I, N) < 0) LINE(IND - 2:IND - 2) = '-'
          M = IR(3, I, N)
          IF (ITRL /= 0) M = M + ITRL * NINT (X(I + 3))
          IF (M /= 0) THEN
            IF (IR(1, I, N) > 0) LINE(IND - 2:IND - 2) = '+'
            IF (ISHEL == 0) THEN
              IF (M < 0) THEN
                M = - M
                IF (IND > 8) LINE(IND - 8 : IND - 6) = '- -'
              END IF
              IF (MOD (M, 12) == 0) THEN
                K = 12
              ELSE IF (MOD (M, 6) == 0) THEN
                K = 6
              ELSE IF (MOD (M, 4) == 0) THEN
                K = 4
              ELSE IF (MOD (M, 3) == 0) THEN
                K = 3
              ELSE IF (MOD (M, 2) == 0) THEN
                K = 2
              END IF
              IF (K /= 12) THEN
                LINE(IND - 6:IND - 4) = ICHR(M / K)//'/'//ICHR(12 / K)
              ELSE
                LINE(IND - 4:IND - 4) = ICHR(M / K)
                IF (IND > 8) LINE(IND - 8:IND - 8) = ' '
              END IF
            ELSE
              TRV = FLOAT (IR(3, I, N)) / 12.0
              WRITE (LINE(IND - 10:IND - 4), 99998, IOSTAT = IOST) TRV
            END IF
          END IF
        END DO
C * ELIMINATE BLANKS
        IF (ITRL /= 0) CALL GEN047 (LINE, 1, 50)
        IF (IUIT > 0) THEN
          IF (IUIT == 7) CALL PLA262 (1)
          IF (IUIT /= 0)
     1      WRITE (IUIT, 99999, IOSTAT = IOST) NSL, LINE(1:60)
        END IF
      END DO
      RETURN
99999 FORMAT (I4, 3X, A)
99998 FORMAT (F7.5)
      END SUBROUTINE SG12
 
      SUBROUTINE SG13 (LIN, X, NSM)
C * FIND NAME OF NON-STANDARD SPACEGROUP WHEN SGSMC(8:11) NON-BLANK
      USE cspgr
      USE spgrdata
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NSM
      REAL, DIMENSION(*) :: X
      CHARACTER(len=*) :: LIN
      CHARACTER(len=2) :: XIMP
      CHARACTER(len=7) :: LZSPG
      IF (SGSMC(8:8) /= ' ') THEN
        DO I = 2, 6
          IF (SGSMC(8:11) == NOSTP(I)) THEN
            ZSPG = NONST((NSLOC(ISGNR - 15) - 1) * 6 + I)
            CALL GEN047 (ZSPG, 1, 9)
            YSPG(1:9)    = '['//ZSPG(1:7)//']'
            SGSMC(13:13) = ZSPG(1:1)
            GO TO 10
          END IF
        END DO
      END IF
C * GET SPACE GROUP NAME IN PROPER UPPER/LOWER CASE FORMAT
   10 CALL GEN020 (-1, SGSMC, 2, 11)
      CALL GEN020 (-1, YSPG,  3, 8)
      IF (ISW /= 18) THEN
C * FIND SPACE GROUP NAME WHEN VOID
        CALL SG12 (X, NSM)
        LIN = LINE
      ELSE
        IF (LAUE == 14 .AND. SGSMC(1:1) /= 'R') LAUE = JLAUE
        X(1)  = FLOAT (ISGNR)
        X(2)  = FLOAT (IKLS)
        X(3)  = FLOAT (LAUE)
        X(4)  = FLOAT (NSYMP)
        X(5)  = FLOAT (ICNTR)
        X(6)  = FLOAT (IBV)
        X(9)  = FLOAT (NST)
        X(13) = FLOAT (IFLACK)
        X(14) = 0.0
        IF (IKLS == 2) THEN
          IF (SGSMC(60:60) == '1') THEN
            X(14) = 1.0
          ELSE IF (SGSMC(60:60) == '3') THEN
            X(14) = 3.0
          END IF
        END IF
C * BRAVAIS-LATTICE TYPE NUMBERS (7 = SPGR/8 = SHELX ORDER)
        DO I = 1, 7
          IF (SGSMC(13:13) == ICHR(29 + I)) X(7) = I
          IF (SGSMC(13:13) == ICHR(36 + I)) X(8) = I
        END DO
        IF (SGSMC(14:14) == 'A') X(8) = - X(8)
C * 1:7 SG-NAME, 8:11 NOST-TRANS, 12 SYSTEM, 13 LATTICE 14 A/C
C * 15:24 SG-NAME(WITH  EMBEDDED SPACES)
        IF (IMPROP > 0 .AND. ICNTR == 1) THEN
          XIMP = ' C'
        ELSE
          XIMP = '  '
        END IF
        LZSPG = ZSPG(1:7)
        CALL GEN020 (-1, LZSPG, 2, 7)
        IF (SGSMC(9:9) == ' ') THEN
          ZSPG = SGSMC(1:7)
        ELSE
          DO J = 1, NNH
            IF (LZSPG == NHL(1, J)(1:7)) THEN
              SGSMC(15:26) = NHL(2, J)(1:12)
              SGSMC(33:54) = NHL(3, J)
            END IF
          END DO
        END IF
        LIN =
     1 SGSMC(1:26)//XSYST(IKLS)//NLAUE(LAUE)//SGSMC(33:59)//XIMP//LZSPG
C * ORIGIN FIXATION  (X(10), X(11), X(12))
        DO J = 1, 3
          X(J + 9) = 0.0
          IF (ICNTR == 1) THEN
            DO I = 1, 3
              IF (IORG(I, J) /= 0) X(J + 9) = X(J + 9) + 2 ** (I - 1)
            END DO
          END IF
        END DO
      END IF
      RETURN
      END SUBROUTINE SG13
 
      SUBROUTINE SG14 (X, TRDET)
C * GET SYMMETRY OPERATORS FOR SUPPLIED SPACEGROUP NAME
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: JA
      INTEGER :: KB
      INTEGER :: KE
      INTEGER :: IMD
      INTEGER :: ISGN
      INTEGER :: LOOP
      REAL :: TRDET
      REAL, DIMENSION(*) :: X
      CHARACTER(len=1)  :: CH
      CHARACTER(len=3)  :: CH3
      CHARACTER(len=12) :: XSPG
      CHARACTER(len=9)  :: NONSTJ
C * FIRST STANDARDIZE SPACE GROUP NAME (HANDLE SPECIAL CHARACTERS AND BLANCS)
      KB   = 1
      KE   = NRSPGR
      ISGN = 0
      LOOP = 0
      CH3  = '   '
C * BLANK SGSMC RECORD
      CALL GEN038 (SGSMC, 1, 59)
      DO WHILE (LOOP == 0)
        LOOP = 1
        DO I = 5, 80
          CH = LINE(I:I)
C * REMOVE () FROM P2(1)
C * REMOVE ~  FROM P2~1~  ETC.
C * REMOVE _  FROM P_21_21_21
          IF (CH == '(' .OR. CH == ')' .OR.
     1        CH == '_' .OR. CH == '~') THEN
            LINE(I:I) = ' '
C * LOOK FOR PROTECTING [] (ELIMINATE & NO-TRANS)
          ELSE IF (CH == '[' .OR. CH == ']') THEN
            LINE(I:I) = ' '
            ITRNS = 0
            NTRNS = 0
          END IF
        END DO
C * REMOVE BLANKS
        CALL GEN047 (LINE, 5, 80)
C * CHECK FOR AND STANDARDIZE ALTERNATIVE SPELLING AND FORMATS
        DO I = 1, NTRL
          J = INDEX (LINE, TRLT(1, I))
          IF (J /= 0) THEN
            LINE(J:) = TRLT(2, I)(1:7)
            EXIT
          END IF
        END DO
C * (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
        CALL SG03 (X, TRDET)
        IF (IER /= 0) THEN
          LRET = 3
          RETURN
        ELSE
C * SET ISBRV, NST, ICNTR
          CALL SG04
          IF (IER /= 0) THEN
            LRET = 3
            RETURN
          END IF
C * INTERPRET SPACE GROUP NAME LINE
          J   = 0
          K   = 0
          M   = 0
          IMD = 0
          CALL GEN038 (SGSMC, 1, 11)
C * DISTINGUISH SETTING TYPES
          I = INDEX (LINE, ':')
          IF (I /= 0) THEN
            CH3 = LINE(I:I+2)
            DO J = 1, 11
              IF (CH3 == CHLIST(J)) EXIT
              IF (J == 11) LINE(I:I) = '.'
            END DO
          END IF
          DO I = 5, 80
C * SKIP BLANKS AND CHANGE INTERPRET MODE ON . FROM
C * SPACE-GROUP NAME (IMD=0) TO AXIAL EXCHANGE (IMD > 0)
            IF (LINE(I:I) == '.') THEN
              IMD  = 1
              ISGN = 1
            ELSE
              IF (IMD == 0) THEN
                K = K + 1
                IF (K > 9) EXIT
                SGSMC(K:K) = LINE(I:I)
                IF (K == 1) THEN
                  SGSMC(13:13) = SGSMC(1:1)
                ELSE
                  IF (SGSMC(K:K) == 'R') SGSMC(13:13) = 'P'
                END IF
              ELSE
                M = M + 1
                IF (M > 4) EXIT
                SGSMC(M + 7:M + 7) = LINE(I:I)
                IF (LINE(I:I) == '-') ISGN = -1
                DO L = 1, 3
                  IF (LINE(I:I) == CHAR (ICHAR ('A') - 1 + L)) THEN
                    IABC(L + 3) = ISGN
                    JABC(L + 3) = IMD
                    IMD         = IMD + 1
                    ISGN        = 1
                  END IF
                END DO
                IF (IMD == 4) EXIT
              END IF
            END IF
          END DO
        END IF
C * SAVE INPUT SPACEGROUP NAME
        IF (IMD == 0) THEN
          ZSPG = SGSMC(1:9)
        ELSE
          ZSPG = SGSMC(1:7)
        END IF
        IF (ITRNS == 1) THEN
          CALL GEN038 (SGSMC,  1, 11)
          CALL GEN038 (SGSMC, 15, 32)
C * CHECK FOR REVERSE SETTING
          IF (NINT (TRDET) == 3) THEN
            IF (R1(1, 1) == -1.0 .AND. R1(1, 2) ==  1.0 .AND.
     1          R1(1, 3) ==  0.0 .AND. R1(2, 1) ==  0.0 .AND.
     2          R1(2, 2) == -1.0 .AND. R1(2, 3) ==  1.0 .AND.
     3          R1(3, 1) ==  1.0 .AND. R1(3, 2) ==  1.0 .AND.
     4          R1(3, 3) ==  1) THEN
              IER = 14
              WRITE (IUIT, 99998, IOSTAT = IOST)
              WRITE (6,    99998, IOSTAT = IOST)
              RETURN
            END IF
          END IF
C * APPLY TRANSFORMATION ON LATTICE TYPE
          CALL SG21 (TRDET)
        ELSE
          IF (SGSMC(1:1) == 'A') THEN
            SGSMC(13:13) = CHAR (ICHAR ('A') + JABC(4) - 1)
          ELSE IF (SGSMC(1:1) == 'B') THEN
            SGSMC(13:13) = CHAR (ICHAR ('A') + JABC(5) - 1)
          ELSE IF (SGSMC(1:1) == 'C') THEN
            SGSMC(13:13) = CHAR (ICHAR ('A') + JABC(6) - 1)
          END IF
        END IF
C * LOOP OVER SPACE GROUP RANGE IN ARRAY SGT TO FIND SPACE GROUP GENERATORS
        DO K = KB, KE
C * COPY SPACEGROUP NAME FROM SPACE GROUP TABLE (SGT)
            XSPG = SGT(K)(1:12)
C * ELIMINATE BLANKS
            CALL GEN047 (XSPG, 1, 12)
            IF (ZSPG(1:9) == XSPG(1:9)) THEN
              SGSMC(60:60) = SGT(K)(33:33)
              READ (SGT(K)(13:15), 99997) ISGNR
              IF (SGSMC(15:15) == ' ') THEN
                SGSMC(15:54) = SGT(K)(1:12)//SHFL(ISGNR)//SGT(K)(16:32)
              ELSE
                SGSMC(38:54) = SGT(K)(16:32)
              END IF
              IF (ISGNR > 0 .AND. ISGNR <= 230)
     1          WRITE (SGSMC(55:59), 99996, IOSTAT = IOST) NSGF(ISGNR)
C * GET ASSOCIATED HALL SYMBOL
              LINE = '    '//SGT(K)(16:32)
              IF (ITRNS == 1) THEN
                IKLS  = 8
                ISGNR = 0
              END IF
C * PARSE HALL-SYMBOL IN 'LINE'
              CALL SG01 (1)
              IF (IER /= 0) THEN
                LRET = 3
              ELSE
                  LRET = 2
              ENDIF
              RETURN
            END IF
        END DO
C * SPGR NOT FOUND: NOW LOOK IN NON-STANDARD ORTHORHOMBIC SETTING LIST
        YSPG(1:9) = '['//ZSPG(1:7)//']'
        DO J = 1, NSTD
          NONSTJ = NONST(J)
          CALL GEN047 (NONSTJ, 1, 9)
          IF (ZSPG(1:9) == NONSTJ) THEN
            SGSMC(15:24) = NONST(J)
C * GENERATE NEW INPUT LINE AND RECYCLE
            JA = ((J - 1) / 6) * 6
            WRITE (LINE, 99998, IOSTAT = IOST)
     1        NONST(JA + 1), NOSTP(J - JA)
            KB  = NANO + NMON + 1
            KE  = KB + NORT
            LOOP = 0
            EXIT
          END IF
        END DO
      END DO
C * NO SYMMETRY GENERATORS AVAILABLE
      IF (IUIT /= 0) WRITE (IUIT, 99999, IOSTAT = IOST) SGSMC(1:11)
C * (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
      CALL SG03 (X, TRDET)
C * SET ISBRV, NST, ICNTR
      CALL SG04
      IER  = 5
      NST  = 0
      LRET = 3
      RETURN
99999 FORMAT (//, ':: Space Group Symbol not Known ', //,
     1 ':: No GENERATORS for this non-standard Space Group ', A,
     2 ' available ...', //,
     3 ':: Please supply generators explicitly with LATT/SYMM',
     4 ' instructions.', /)
99998 FORMAT ('SPGR ', A, '.', A, 61X)
99997 FORMAT (I3)
99996 FORMAT (I5)
      END SUBROUTINE SG14
 
      SUBROUTINE SG15 (X, NSM)
C * LOAD ROTATION MATRIX FOR NSM IN X(1:9) AND TRANSLATION VECTOR IN X(10:12)
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: NSL
      INTEGER :: NSM
      INTEGER :: IRIK
      INTEGER :: ISIK
      REAL, DIMENSION(*) :: X
      NSL = NSM
C * FILL IR(I, J, 195) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
      CALL SG05 (195, NSL, 151)
      IF (IER == 0) THEN
        DO I = 1, 12
          IF (I > 9) THEN
            X(I) = IR(3, I - 9, 195) / 12.0
          ELSE
            X(I) = 0.0
          END IF
        END DO
        DO I = 1, 2
          DO K = 1, 3
            IRIK = IR(I, K, 195)
            IF (IRIK /= 0) THEN
              ISIK = 1
              IF (IRIK < 0) ISIK = -1
              X((K - 1) * 3 + IABS (IRIK)) = ISIK
            END IF
          END DO
        END DO
      END IF
      RETURN
      END SUBROUTINE SG15
 
      SUBROUTINE SG16 (LIN, X)
C * THIS FUNCTION DETERMINES THE SITE SYMMETRY FOR ANY ATOM INPUT SITES
C * LOCATED ON MIRRORS OR AXES WITH EQUIVALENT POINTS ON <110> OR
C * <1-10> WILL BE PLACED ON <110> OR ON <1-10>.
C * (NOT IMPLEMENTED IN FULL YET)
      USE cspgr
      USE spgrdata
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: IRT
      INTEGER :: NSM
      INTEGER :: NSP
      INTEGER :: NDIF
      INTEGER :: ISYM
      REAL :: TOL
      REAL :: YUNK
      REAL :: DIFF
      REAL, DIMENSION(*) :: X
      REAL, DIMENSION(3) :: AVE
      CHARACTER(len=*) :: LIN
      ISWD = 1
      ISYM = 0
      IF (X(10) > 0.0) THEN
        TOL = X(10)
      ELSE
        TOL = 0.005
      END IF
      DO I = 1, 3
        X(I + 3) = 0.0
        X(I + 6) = 0.0
        AVE(I)   = X(I)
      END DO
      NSP  = 1
C * LOOP OVER ALL SYMMETRY OPERATIONS
      IF (NST > 1) THEN
        DO 10 L = 2, NST
          NSM = L
          CALL SG09 (X, NSM)
          IF (IER /= 0) RETURN
C * TEST FOR SPECIAL POSITION
          DO I = 1, 3
            NDIF = INT (10.0 + X(6 + I) - X(I)) - 10
            X(6 + I) = X(6 + I) - NDIF
            DIFF = X(6 + I) - X(I)
            IF (DIFF > 0.5) THEN
              DIFF = 1.0 - DIFF
              X(6 + I) = X(6 + I) - 1.0
            END IF
            IF (DIFF > TOL) GO TO 10
          END DO
          NSP = NSP + 1
C * ADD TO AVERAGE POSITION
          DO I = 1, 3
            AVE(I) = AVE(I) + X(6 + I)
          END DO
C * ENCODE ROTATION PART OF SYMMETRY OPERATION FOR COMPARISON WITH IOPR
          K   = 0
          IRT = 0
          DO I = 1, 2
            DO J = 1, 3
              IRT = IRT + IR(I, J, NSM) * 7**K
              K   = K + 1
            END DO
          END DO
          DO I = 1, NOPR
            IF (IRT == IOPR(I)) THEN
              ISYM = ISYM + 2**(I - 1)
              GO TO 10
            END IF
          END DO
   10   CONTINUE
      END IF
      DO I = 1, 3
        YUNK = MOD (100.0 + (AVE(I) / NSP), 1.0)
        X(6 + I) = YUNK - NINT (YUNK - X(I))
      END DO
      DO I = 1, NSITE
        IF (ISYM == KSITE(I)) GO TO 20
      END DO
      I     = 1
   20 X(12) = I
      X(11) = ISYM
      X(10) = 1.0 / NSP
C * EDIT
      IF (IKLS == 4) THEN
        IF (I == 3) THEN
          I = 12
        ELSE IF (I == 4) THEN
          I = 9
        ELSE IF (I == 5) THEN
          I = 15
        ELSE IF (I == 12) THEN
          I = 7
        END IF
      END IF
      LIN(1:5) = SITE(I)
      RETURN
      END SUBROUTINE SG16
 
      SUBROUTINE SG17 (X, TRDET)
C * (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      REAL :: TRDET
      REAL, DIMENSION(*) :: X
      CALL GEN038 (SGSMC, 1, 59)
      CALL SG03 (X, TRDET)
      IF (IER == 0) THEN
C * SET ISBRV, NST, ICNTR
        CALL SG04
        J = 0
        DO I = 5, 80
          IF (LINE(I:I) /= ' ' .AND. LINE(I:I) /= '-') THEN
C * SHELX STYLE LATT CARD
            DO L = 1, 7
              IF (LINE(I:I) == CHAR (ICHAR ('0') + L)) THEN
                SGSMC(13:13) = ICHR(36 + L)
                IF (LINE(I - 1:I - 1) /= '-') SGSMC(14:14) = 'C'
                GO TO 10
              END IF
            END DO
C * NON-SHELX STYLE LATT LINE
            J = J + 1
            SGSMC(J + 12:J + 12) = LINE(I:I)
          END IF
        END DO
C * TRANSFORM LATTICE TYPE
   10   IF (ITRNS /= 0) CALL SG21 (TRDET)
        CALL SG04
      END IF
      RETURN
      END SUBROUTINE SG17
 
      SUBROUTINE SG18 (MODE)
C * HANDLE SAVESYMM FILE
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NSM
      INTEGER :: NRET
      INTEGER :: MODE
      REAL :: TRDETX
      REAL, DIMENSION(12) :: X
      CHARACTER(len=80) :: LIN
      OPEN (LU80, FILE = 'SAVESYMM', STATUS = 'UNKNOWN')
      IF (MODE == 1) THEN
        DO I = 1, NST
          NSM = I
C * LOAD ROTATION MATRIX FOR NSM IN X(1:9) AND TRANSLATION VECTOR IN X(10:12)
          CALL SG15 (X, NSM)
          WRITE (LU80, 99999, IOSTAT = IOST) (X(J), J = 1, 12)
        END DO
        CLOSE (LU80)
      ELSE IF (MODE == -1) THEN
        NRET = 0
        CALL SG03 (X, TRDETX)
C * SET ISBRV, NST, ICNTR
        CALL SG04
        DO
          READ (LU80, 99999, IOSTAT = IOST) (X(J), J = 1, 12)
          IF (IOST /= 0) EXIT
          CALL SG19 (LIN, X, NSM, NRET)
        END DO
        CLOSE (LU80, STATUS = 'DELETE')
      END IF
      RETURN
99999 FORMAT (9F5.2, 3F10.5)
      END SUBROUTINE SG18
 
      SUBROUTINE SG19 (LIN, X, NSM, NRET)
C * INTERPRETE INPUT SYMMETRY INFO
      USE cspgr
      USE csgsx
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: JL
      INTEGER :: JM
      INTEGER :: IC
      INTEGER :: INX
      INTEGER :: ISN
      INTEGER :: INM
      INTEGER :: NSM
      INTEGER :: NCOM
      INTEGER :: NFLT
      INTEGER :: KTRV
      INTEGER :: KM11
      INTEGER :: KABC
      INTEGER :: ISNN
      INTEGER :: ITRV
      INTEGER :: IFLT
      INTEGER :: IFRC
      INTEGER :: NRET
      INTEGER :: NSYMO
      INTEGER :: ISKIP
      REAL :: FLT
      REAL :: FFLT
      REAL :: XLNG
      REAL :: FFLT0
      REAL :: GEN130
      REAL, DIMENSION(*) :: X
      REAL, DIMENSION(3) :: XSAV
      CHARACTER(len=*) :: LIN
      CHARACTER(len=2) :: OLAT
      INX  = 0
      NRET = 0
      FLT  = 0.0
      ISNN = 0
      KTRV = 0
      DO
C * TEST FOR SYMM LINE
        IF (ISW == 11) THEN
          DO I = 4, 6
            IABC(I) = 1
            JABC(I) = I - 3
          END DO
          IF (NST == 1) THEN
C * (GENERAL) LATTICE INIT ETC. - GET TRANSFORMATION MATRIX
            CALL SG03 (X, TRDET)
            IF (IER /= 0) RETURN
          END IF
          JBG  = 5
          JEG  = 80
          JSWD = 0
C * R/T INFO
        ELSE IF (ISW == 15 .OR. ISW == 26) THEN
          DO I = 1, 3
            DO J = 1, 3
              R0(J, I) = X(I + (J - 1) * 3)
            END DO
            T0(I) = X(I + 9)
          END DO
          JBG = 1
          JEG = 20
C * CONVERT R/T TO SYMM-LINE
          CALL SG02 (JBG)
          IF (IER /= 0) RETURN
          DO I = 4, 6
            IABC(I) = 1
            JABC(I) = I - 3
          END DO
          JSWD = 0
        ELSE
C * GET AND ANALYSE GENERATORS FROM HALL SYMBOLS
          JBG = JBG + 20
          JEG = JBG + 19
          NIC = 3
          IF (JBG > 100 .OR. LINE(JBG:JBG) == ' ') THEN
            IF (LRET == 1) THEN
              ISGNR = NUMS
              SGSMC(15:54) = SGT(JSG)(1:12)//SHFL(NUMS)//SGT(JSG)(16:32)
              SGSMC(60:60) = SGT(JSG)(33:33)
              IF (NSLP > 1) SGSMC(8:11) = NOSTP(NSLP)
              JLAUE = 8
              M     = 0
              DO L = 1, 12
                IF (SGT(JSG)(L + 15:L + 15) == '"') JLAUE = 7
                IF (SGT(JSG)(L:L) /= ' ') THEN
                  M          = M + 1
                  SGSMC(M:M) = SGT(JSG)(L:L)
                END IF
              END DO
C * FIND NAME OF NON-STANDARD SPACEGROUP WHEN SGSMC(8:11) NON-BLANK
              CALL SG13 (LIN, X, NSM)
            ELSE IF (LRET == 2) THEN
              CALL SG04
            END IF
            RETURN
          END IF
        END IF
        NTRNS = ITRNS
   10   IC    = 0
        JL    = JBG - 1
        NCOM  = 0
C * IC INDICATES CURRENT SUBFIELD OF SYMM-LINE
   20   IF (IC > 0) THEN
C * HANDLE ROTATION PART
          KABC = JABC(IC + NIC)
          IF (INX == 2) THEN
            IR(2, KABC, 195) = 0
          ELSE IF (INX > 2) THEN
C * STANDARDIZE
            IF (IABS (IR(1, KABC, 195)) > IABS (IR(2, KABC, 195)))
     1        CALL GEN014 (IR(1, KABC, 195), IR(2, KABC, 195))
          END IF
C * HANDLE TRANSLATION PART
          FFLT0 = ISNN * FLT * 12.0
          FFLT  = MOD (FFLT0, 12.0)
          IF (FFLT < 0.0) FFLT = FFLT + 12.0
          IF (NSGET == 1) XSAV(IC) = FFLT0 - FFLT
          NFLT = NINT(FFLT)
C * CHECK WHETHER THIS IS AN ALLOWED RATIO
          IF (NFLT == 1  .OR. NFLT == 5 .OR. NFLT == 7 .OR.
     1        NFLT == 11 .OR. ABS (FFLT - NFLT) > 0.01) THEN
            IF (IUIT /= 0)
     1        WRITE (IUIT, 99999, IOSTAT = IOST) LINE(1:40)
            IER = 2
            RETURN
          END IF
          IR(3, JABC(IC + NIC), 195) = MOD (IABC(IC + NIC)
     1        * NFLT + 12, 12)
        END IF
        IC   =  IC + 1
        INX  =  1
        FLT  =  0.0
        ITRV = -1
        IFLT =  0
        IFRC =  0
        ISNN =  1
        ISN  =  1
C * LOOP OVER THE RANGE (JBG, JEG) TO INTERPRETE SYMMETRY INSTRUCTION
   30   IF (JL < JEG) THEN
          JL = JL + 1
C * LOOP OVER ALLOWED CHARACTERS (OTHERS ARE IGNORED)
C * 1, 2, 3, 4, 5, 6, 7, 8, 9, 0, ., X, Y, Z,  , ,, +, -, /, [, ]
          DO K = 1, 21
            IF (LINE(JL:JL) == ICHR(K)) THEN
C * PROTECT FOR TRANSFORMATION WHEN IN [] - AND BLANK
              CALL GEN038 (LINE, JL, JL)
              IF (K == 20 .OR. K == 21) THEN
                ITRNS = 0
                NTRNS = 0
C * NUMERICAL
              ELSE IF (K < 10) THEN
                IF (IFLT == 0) THEN
                  IF (ITRV /= 0) THEN
                    IF (ITRV < 0) THEN
                      ITRV = K
                      KTRV = K
                      INM  = 1
                    ELSE
                      INM  = K
                    END IF
                    ISNN = ISN
                    IF (KTRV > K .AND. NSGET == 0)
     1                  ITRV = MOD (KTRV, K)
                    FLT  = FLOAT (ITRV) / FLOAT (INM)
                    IFRC = IFRC + 1
                    IF (IFRC > 2) THEN
                      IF (IUIT /= 0)
     1                  WRITE (IUIT, 99999, IOSTAT = IOST) LINE(1:40)
                      IER = 2
                    END IF
                  END IF
                ELSE
                  FLT  = FLT  + K * 10.0**IFLT
                  IFLT = IFLT - 1
                  ISNN = ISN
                END IF
C * DECIMAL POINT
              ELSE IF (K == 11) THEN
                IFLT = IFLT - 1
                ISNN = ISN
C * X,Y,Z
              ELSE IF (K > 11 .AND. K < 15) THEN
                KM11 = K - 11
                IR(INX, JABC(IC + NIC), 195) =
     1            IABC(IC + NIC) * ISN * JABC(KM11 + NIC)
     2            * IABC(KM11 + NIC)
                INX   = INX + 1
                ISN  = 1
C * COMMA, START OF NEW SUBFIELD
              ELSE IF (K == 16) THEN
                NCOM = NCOM + 1
                IF (NCOM < 3) GO TO 20
C * PLUS
              ELSE IF (K == 17) THEN
                ISN = 1
C * MINUS
              ELSE IF (K == 18) THEN
                ISN = - 1
              END IF
              GO TO 30
            END IF
          END DO
          IF (IUIT /= 0)
     1      WRITE (IUIT, 99999, IOSTAT = IOST) LINE(1:40)
          IER = 2
          RETURN
        ELSE IF (JL == JEG) THEN
          JL = JL + 1
          GO TO 20
        ELSE
C * CHECK FOR CORRECT SYNTAX
          IF (IC < 3 .OR. (IC == 3 .AND. INX < 2) .OR.
     1        NCOM /= 2) THEN
            IF (IUIT /= 0)
     1        WRITE (IUIT, 99999, IOSTAT = IOST) LINE(1:40)
            IER = 2
            RETURN
          END IF
C * HANDLE 'GET SYMMETRY NUMBER CASE (ISW = 22)
          IF (NSGET == 1) THEN
            DO J = 1, 3
              X(J)     = IR(1, J, 195)
              X(J + 3) = IR(2, J, 195)
              X(J + 6) = IR(3, J, 195) + XSAV(J)
            END DO
            ISW = 7
C * GET SYMMOP NR + UNITCELL TRANSLATIONS FOR GIVEN OPERATOR
            CALL SG10 (X)
            RETURN
          END IF
C * REDUCE FOR LATTICE CENTERING (IN SYMM OR R|T OPERATION)
          IF (ISW == 11 .OR. ISW == 15 .OR. ISW == 26) THEN
            N = IR(3, 1, 195) * 100 + IR(3, 2, 195) * 10 + IR(3, 3, 195)
            ISKIP = 0
            SELECT CASE (SGSMC(13:13))
              CASE ('P')
                ISKIP = 1
              CASE ('A')
                IF (N /= 66)  ISKIP = 1
              CASE ('B')
                IF (N /= 606) ISKIP = 1
              CASE ('C')
                IF (N /= 660) ISKIP = 1
              CASE ('I')
                IF (N /= 666) ISKIP = 1
              CASE ('F')
                IF (N /= 660 .AND. N /= 606 .AND. N /= 66)
     1            ISKIP = 1
              CASE ('R')
                IF (N /= 844 .AND. N /= 488) ISKIP = 1
            END SELECT
C * REDUCE
            IF (ISKIP == 0) THEN
              DO J = 1, 3
                IR(3, J, 195) = 0
              END DO
            END IF
          END IF
C * CONVERT SYMMETRY OPERATION INTO (R|t) MATRICES
          CALL GEN021 (R3, 0.0)
          DO I = 1, 3
            DO J = 1, 2
              N = IR(J, I, 195)
              IF (N /= 0) R3(I, IABS (N)) = SIGN (1.0, FLOAT (N))
            END DO
            T3(I) = FLOAT (IR(3, I, 195)) / 12.0
          END DO
C * TEST FOR SYMM, SPGR, SYMM-R/T, HALL
          IF (ISW == 11 .OR. ISW == 12 .OR. ISW == 15 .OR.
     1        ISW == 21 .OR. ISW == 26) THEN
            IMPROP = MIN (IMPROP, NINT (GEN130 (R3)))
            IF (IMPROP == -1) THEN
              IF (IFLACK /= 0) IFLACK = -1
            END IF
          END IF
          IF (NTRNS > 0) THEN
            NTRNS = 0
C * APPLY T(TRANSPOSE,INVERSE) R T(TRANSPOSE) TO OBTAIN R'
            DO I = 1, 3
              DO J = 1, 3
                R4(I, J) = R2(I, J)
              END DO
            END DO
            CALL GEN132 (R4, R3, R1, R0)
C * APPLY T(TRANSPOSE,INVERSE) t              TO OBTAIN t'
            CALL GEN002 (1, R4, T3, T0, XLNG)
C * APPLY ORIGIN SHIFT
            DO I = 1, 3
              T0(I) = T0(I) + OSFT(I)
              DO J = 1, 3
                T0(I) = T0(I) - R0(I, J) * OSFT(J)
              END DO
            END DO
            NIC = 0
            CALL GEN038 (SGSMC, 1, 1)
            CALL GEN038 (YSPG, 1, 9)
C * CONVERT (R0|T0) INTO SYMM LINE
            CALL SG02 (JBG)
            IF (IER /= 0) RETURN
            JSWD = 0
            GO TO 10
          END IF
C * CHECK FOR PRE-OCCURRENCE OF THIS OPERATOR
          IF (ISW /= 2 .AND. ISW /= 4 .AND. ISW /= 18) THEN
C * SAVE CURRENT SYMMETRY PARAMETERS
            NSYMO = NSYMP
            OLAT  = SGSMC(13:14)
C * CHECK WHETHER THIS IS A NEW SYMMETRY OPERATION
            CALL SG07
            IF (IER /= 0) RETURN
            IF (SGSMC(13:14) /= OLAT) THEN
              GO TO 60
            END IF
C * OVERFLOW (SHOULD BE A REAL ERROR)
            IF (NSYMP >= 48) THEN
              CALL SG04
              RETURN
            END IF
C * EXPAND GENERATOR SET TO FULL SYMMETRY SET
            IF (NSYMP > 1) THEN
              K = 1
              DO WHILE (K < NSYMP)
                K  = K + 1
                I  = K
                JM = 2 * K - 2
C * FILL IR(I, J, 194) WITH IS(K, L, I) (TRANSPOSED FOR HKL)
                CALL SG05 (194, I, 191)
                IF (IER /= 0) RETURN
                DO L = 2, JM
                  J = L
                  IF (L > K) THEN
                    J = K
                    I = 2 * K - L
C * FILL IR(I, J, 194) WITH IS(K, L, I) (TRANSPOSED FOR HKL)
                    CALL SG05 (194, I, 192)
                    IF (IER /= 0) RETURN
                  END IF
C * FILL IR(I, J, 193) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
                  CALL SG05 (193, J, 193)
                  IF (IER /= 0) RETURN
C * MULTIPLY SYMMETRY OPERATIONS
                  CALL SG06
C * CHECK WHETHER THIS IS A NEW SYMMETRY OPERATION
                  CALL SG07
                  IF (IER /= 0) RETURN
                  IF (SGSMC(13:14) /= OLAT) THEN
                    NSYMP = NSYMO
                    GO TO 60
                  END IF
                  IF (NSYMP >= 48) THEN
                    CALL SG04
                    RETURN
                  END IF
                END DO
              END DO
            END IF
          ELSE
            DO 50 I = 1, NST
              DO J = 1, 3
                DO K = 1, 3
                  IF (IR(J, K, I) /= IR(J, K, 195)) GO TO 50
                END DO
              END DO
C * NEW SYMMETRY OPERATION FOUND
              GO TO 60
   50       CONTINUE
            NRET = 1
            RETURN
          END IF
        END IF
   60   IF (ISW == 11 .OR. ISW == 15 .OR. ISW == 26) THEN
          CALL SG04
          RETURN
        END IF
      END DO
      RETURN
99999 FORMAT (/, ':: Error in SYMM line syntax !!, ',
     1        /, ':: Line ignored: ', A, /)
      END SUBROUTINE SG19
 
      SUBROUTINE SG20 (NGO, X, NSM, LIN)
C * TEST FOR SYMM RECORD
      USE cspgr
      USE csgsx
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: NSM
      INTEGER :: NGO
      INTEGER :: IMD
      INTEGER :: NSL
      INTEGER :: NRET
      INTEGER :: ISGC
      INTEGER :: ISGN
      REAL, DIMENSION(*) :: X
 
      CHARACTER(len=*) :: LIN
      CHARACTER(len=1) :: BLAT
      CHARACTER(len=1) :: IBRAV
      CHARACTER(len=1) :: XCHAR
      IF (ABS(NGO) == 1) THEN
        IF (NGO == -1) THEN
          CALL SG19 (LIN, X, NSM, NRET)
          IF (NRET == 0) RETURN
        END IF
        GO TO 20
      ELSE
        ISWD  = 1
        JSWD  = 1
        NTRNS = 0
C * LOAD APPROPRIATE MATRICES IN IR
        DO I = 1, NST
          NSL = I
C * FILL IR(I, J, NSL) WITH IS(K, L, J) (TRANSPOSED FOR HKL)
          CALL SG05 (NSL, NSL, 201)
          IF (IER /= 0) RETURN
        END DO
      END IF
C * LOOP OVER CANDIDATE SPACE GROUPS (BETWEEN JSMI AND JSMX)
      JSG = JSMX + 1
   10 JSG = JSG  - 1
      IF (JSG < JSMI) THEN
C * FIND NAME OF NON-STANDARD SPACEGROUP WHEN SGSMC(8:11) NON-BLANK
        CALL SG13 (LIN, X, NSM)
        RETURN
      END IF
C * AVOID NON-STANDARD SETTING MARKED X
      IF (SGT(JSG)(33:33) == 'X') GOTO 10
      IF (ISTO == 1 .AND. SGT(JSG)(33:33) == ' ') GO TO 10
      NSLP = 0
      NIC  = 3
      BLAT = SGT(JSG)(1:1)
C * TEST FOR CENTRO/NONCENTRO SIMILARITY (E.G. FOR PNNN:1)
      N = INDEX (SGT(JSG)(16:32), '-1')
      IF (N > 0) THEN
        IF (SGT(JSG)(15 + N:N + 17) == '-1)') N = 0
      END IF
      IF (SGT(JSG)(16:16) == '-' .OR. N /= 0) THEN
        ISGC = 2
      ELSE
        ISGC = 1
      END IF
      IF (ISGC /= ICNTRX) GO TO 10
      IBRAV = SGSMC(13:13)
C * NONSTANDARD SUB-LOOP (ORTHORHOMBIC: NSLPM = 6)
   20 NSLP = NSLP + 1
      IF (NSLP == 1) THEN
        NSLPM = 1
        N     = 0
        READ (SGT(JSG)(13:15), 99999) NUMS
C * CHECK FOR ORTHORHOMBIC CASES
        IF (NUMS > 15 .AND. NUMS < 75) THEN
          N = INDEX (SGT(JSG)(1:12), ':1')
          IF (N == 0) THEN
            IF (NSLOC(NUMS - 15) > 0) NSLPM = 6
          END IF
        END IF
C * TEST FOR BRAVAIS LATTICE SIMILARITY
C * SPECIAL RHOMBOHEDRAL SETTING CASE HANDLING
        IF (BLAT == 'R') THEN
          IF (INDEX (SGT(JSG)(2:12), 'R') /= 0) BLAT = 'P'
        END IF
      ELSE
        IF (NSLP > NSLPM) GO TO 10
        BLAT = NONST((NSLOC(NUMS - 15) - 1) * 6 + NSLP)(1:1)
      END IF
      SGSMC(13:13) = IBRAV
      IF (BLAT /= IBRAV) GO TO 20
      IMD  = 1
      ISGN = 1
      DO K = 1, 4
        XCHAR = NOSTP(NSLP)(K:K)
        IF (XCHAR == '-') THEN
          ISGN = -1
        ELSE
          DO L = 1, 3
            IF (XCHAR == CHAR (ICHAR ('A') - 1 + L)) THEN
              IABC(L + 3) = ISGN
              JABC(L + 3) = IMD
              IMD         = IMD + 1
              ISGN        = 1
            END IF
          END DO
        END IF
      END DO
      LINE = '    '//SGT(JSG)(16:32)
C * PARSE HALL-SYMBOL IN 'LINE'
      CALL SG01 (0)
      IF (IER == 0) THEN
        LRET = 1
        JBG  = -19
C * INTERPRETE INPUT SYMMETRY INFO
        CALL SG19 (LIN, X, NSM, NRET)
        IF (NRET == 1) GO TO 20
      END IF
      RETURN
99999 FORMAT (I3)
      END SUBROUTINE SG20
 
      SUBROUTINE SG21 (DET)
C * ENTRY POINT FOR SPGR & HALL - TRANSFORM LATTICE TYPE
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: IDET
      INTEGER :: IBVP
      INTEGER :: IBVX
      REAL :: DET
      K = 0
      DO N = 1, 7
        IF (SGSMC(13:13) == ICHR(N + 29)) THEN
          IDET = NINT (IBV0(N) * DET)
          IF (IDET == 4) THEN
            SGSMC(13:13) = 'F'
          ELSE IF (IDET == 3) THEN
            SGSMC(13:13) = 'R'
          ELSE IF (IDET == 2) THEN
            IBVX = 3
            IF (N > 1) THEN
              IBVP = IBV1(N) - 1
              DO J = 1, 3
                R2(J, 4) = 0.0
                DO K = 1, 3
                  R2(J, 4) = R2(J, 4) + R2(J, K) * IBV2(IBVP + K) / 12.0
                END DO
              END DO
              IBVX = 4
            END IF
            DO J = 1, IBVX
              K = 0
              DO I = 1, 3
                IF (ABS (0.5 - ABS (AMOD (R2(I, J), 1.0))) < 0.1)
     1            K = K + 2**(I - 1)
              END DO
              IF (K > 2 .AND. K /= 4) EXIT
            END DO
            IF (K == 6) THEN
              SGSMC(13:13) = 'A'
            ELSE IF (K == 5) THEN
              SGSMC(13:13) = 'B'
            ELSE IF (K == 3) THEN
              SGSMC(13:13) = 'C'
            ELSE IF (K == 7) THEN
              SGSMC(13:13) = 'I'
            END IF
          ELSE
            SGSMC(13:13) = 'P'
          END IF
          IF (SGSMC(14:14) == 'C') THEN
            DO I = 1, 3
              L = NINT (AMOD (ABS (2.0 * OSFT(I)), 1.0) * 12.0)
              IF (L /= 0 .AND. L /= 6) THEN
                IF (IUIT /= 0) WRITE (IUIT, 99998, IOSTAT = IOST)
                SGSMC(14:14) = 'A'
              END IF
            END DO
          END IF
          RETURN
        END IF
      END DO
      IF (IUIT /= 0) WRITE (IUIT, 99999, IOSTAT = IOST) SGSMC(13:13)
      RETURN
99999 FORMAT (':: Cannot Transform Lattice: ', A)
99998 FORMAT (':: Origin shift not compatible with inversion on 0,0,0')
      END SUBROUTINE SG21
 
 
      SUBROUTINE SG22
C * INITIALIZE
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      DO I = 1, 3
        IABC(I)     = 1
        IABC(I + 3) = 1
        JABC(I)     = I
        JABC(I + 3) = I
        DO J = 1, 3
          IF (I == 1) THEN
            L = J
          ELSE
            L = 0
          END IF
          IS (I, J, 1) = L
          IF (I == J) THEN
            L = I
          ELSE
            L = 0
          END IF
          IORG(I, J) = L
        END DO
      END DO
C * BLANK
      CALL GEN038 (YSPG,  1, 9)
      CALL GEN038 (ZSPG,  1, 13)
      CALL GEN038 (SGSMC, 1, 47)
      SGSMC(13:14) = 'PA'
      JSWD         = 0
      IKLS         = 8
      IAXM         = 0
      NSYMP        = 1
      ISGNR        = 0
      IMPROP       = 1
      IFLACK       = 1
      RETURN
      END SUBROUTINE SG22
 
      SUBROUTINE SG23 (XX)
C * CHECK WHETHER H K L IS ABSENT
      USE cspgr
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IZ
      INTEGER :: NH
      INTEGER :: NK
      INTEGER :: NL
      INTEGER :: MC
      INTEGER :: MODE
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL, DIMENSION(12) :: XX
C * MODE = -1 - Check for Lattice Absences
C *      =  1 - Check for Non-Lattice Absences
C *      =  0 - Check both
      MODE   = NINT (XX(12))
      XX(12) = 0.0
      N      = NSYMP * ICNTR / ICNTRX
C * CHECK FOR/LOAD SYMMETRY DATA
      IF (IABSENT == 0) THEN
        IABSENT = 1
C * LOAD NON-LATTICE OR INVERSION SYMMETRY OPERATIONS
        K = -11
        DO I = 1, N
          K = K + 12
          CALL SG15 (A(K), I)
          IF (I > 1) THEN
            DO J = 1, 3
              A(K + J + 8)  = A(K + J + 8) - 2.0 * OCNT(J)
            END DO
          END IF
        END DO
C * LOAD BRAVAIS LATTICE VECTORS FOR A,B,C,F,I,R
        IF (IBV > 1) THEN
          DO I = 2, 7
            IF (SGSMC(13:13) == ICHR(I + 29)) THEN
              K = IBV1(I) - 1
              L = (IBV0(I) - 1) * 3
              DO J = 1, L
                B(3 + J) = REAL (IBV2(K + J)) / 12.0
              END DO
            END IF
          END DO
        END IF
      END IF
C * check h, k, l
      X  = XX(1)
      Y  = XX(2)
      Z  = XX(3)
      NH = NINT (X)
      NK = NINT (Y)
      NL = NINT (Z)
C * Reject lattice absences
      IF (MODE <= 0) THEN
        I = 0
        DO J = 2, IBV
          I = I + 3
          IF (ABS (AMOD (X * B(I + 1) + Y * B(I + 2) +
     1      Z * B(I + 3) + 999.5, 1.0) -0.5) > 0.01) THEN
            XX(12) = 2.0
            RETURN
          END IF
        END DO
      END IF
C * Reject Non-Lattice systematic absences
      IF (MODE >= 0) THEN
C * Maximize indices
        IF (ICNTRX == 2) THEN
          I = NL
          IF (I == 0) I = NK
          IF (I == 0) I = NH
          IF (I <= 0) THEN
            NH = - NH
            NK = - NK
            NL = - NL
          END IF
        END IF
        K = -12
        DO J = 1, N
          K = K + 12
          IX = NINT (X * A(K + 1) + Y * A(K + 4) + Z * A(K + 7))
          IY = NINT (X * A(K + 2) + Y * A(K + 5) + Z * A(K + 8))
          IZ = NINT (X * A(K + 3) + Y * A(K + 6) + Z * A(K + 9))
          IF (ICNTRX == 2) THEN
            I = IZ
            IF (I == 0) I = IY
            IF (I == 0) I = IX
            IF (I <= 0) THEN
              IX = -IX
              IY = -IY
              IZ = -IZ
            END IF
          END IF
          IF (NL >  IZ) CYCLE
          IF (NL >= IZ) THEN
            IF (NK >  IY) CYCLE
            IF (NK >= IY) THEN
              IF (NH >= IX) CYCLE
            END IF
          END IF
          NH = IX
          NK = IY
          NL = IZ
        END DO
        X = REAL (NH)
        Y = REAL (NK)
        Z = REAL (NL)
C * find systematic absences
        MC = NL
        IF (MC == 0) MC = NK
        IF (MC == 0) MC = NH
        K = -12
        DO J = 1, N
          K = K + 12
          IX = NINT (X * A(K + 1) + Y * A(K + 4) + Z * A(K + 7))
          IY = NINT (X * A(K + 2) + Y * A(K + 5) + Z * A(K + 8))
          IZ = NINT (X * A(K + 3) + Y * A(K + 6) + Z * A(K + 9))
          IF (ICNTRX == 2) THEN
            I = IZ
            IF (I == 0) I = IY
            IF (I == 0) I = IX
            IF (I * MC <= 0) THEN
              IX = - IX
              IY = - IY
              IZ = - IZ
            END IF
          END IF
          IF (IABS (IX - NH) + IABS (IY - NK) + IABS (IZ - NL) == 0)
     1      THEN
            IF (ABS (AMOD (10.5 + ABS (X * A(K + 10) + Y * A(K + 11)
     1        + Z * A(K + 12)), 1.0) -0.5) >= 0.1) THEN
              XX(12) = 1.0
              RETURN
            END IF
          END IF
        END DO
      END IF
      RETURN
      END SUBROUTINE SG23
 
      SUBROUTINE SG24
C * LIST SPACEGROUP HEADER
      USE cspgr
      USE spgrdata
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: N
      INTEGER :: JUNK
      CHARACTER(len=13) :: TXT
      CHARACTER(len=2)  :: ACENT
      CHARACTER(len=7)  :: LZSPG
      IF (ICNTRX == 2 .OR. ILAUE < 0) THEN
        ACENT = ' C'
      ELSE
        ACENT = 'Ac'
      END IF
      IF (LAUE == 14 .AND. SGSMC(1:1) /= 'R') LAUE = JLAUE
      IF (IUIT /= 0) THEN
        N = INDEX (SGSMC(1:11), ':')
        IF (N /= 0) THEN
          TXT = SGSMC(1:11)
        ELSE IF (SGSMC(8:8) /= ' ') THEN
          TXT = SGSMC(1:7)//':'//SGSMC(8:11)
          LZSPG = ZSPG(1:7)
          CALL GEN020 (-1, LZSPG, 2, 7)
          DO J = 1, NNH
            IF (LZSPG == NHL(1, J)(1:7)) THEN
              SGSMC(15:26) = NHL(2, J)(1:12)
              SGSMC(33:49) = NHL(3, J)
            END IF
          END DO
        ELSE
          IF (SGSMC(1:1) == 'R') THEN
            N = INDEX (SGSMC(2:7), 'r')
            IF (N > 0) THEN
              SGSMC(N + 1:N + 2) = ':R'
            ELSE
              N = INDEX (SGSMC(1:7), ' ')
              SGSMC(N:N+1) = ':H'
              N = INDEX (SGSMC(15:26), '  ')
              IF (N /= 0) SGSMC(15 + N:15 + N) = 'H'
            END IF
          END IF
          TXT = SGSMC(1:7)
        END IF
        JUNK = LAUE
        IF (LAUE == 14 .AND. JLAUE == 7) JUNK = 7
        WRITE (IUIT, 99999, IOSTAT = IOST) TXT, YSPG, NLAUE(JUNK),
     1    SGSMC(33:49), SGSMC(27:32), SGSMC(12:13), ACENT,
     2    XSYST(IKLS), NSTT, NSYMP, ISGNR
      END IF
      IF (IUIT == 7) CALL PLA262 (6)
      IF (ICNTR /= ICNTRX) THEN
        IF (IUIT /= 0)
     1    WRITE (IUIT, 99994, IOSTAT = IOST) OCNT(1), OCNT(2), OCNT(3)
        IF (IUIT == 7) CALL PLA262 (2)
      END IF
      IF (ILAUE > 0) THEN
        IF (ICNTRX == 1) THEN
          IF (IMPROP > 0) THEN
            IF (IUIT /= 0) WRITE (IUIT, 99995, IOSTAT = IOST)
     1        'Sohncke SpGr (Absolute Configuration)'
          ELSE IF (IMPROP == -1) THEN
            IF (IUIT /= 0) WRITE (IUIT, 99995, IOSTAT = IOST)
     1        'Non-Sohncke SpGr (Absolute Structure)'
          END IF
        ELSE
          IF (IUIT /= 0) WRITE (IUIT, 99996)
        END IF
        IF (IUIT == 7) CALL PLA262 (2)
        IF (IUIT /= 0) WRITE (IUIT, 99998, IOSTAT = IOST)
      ELSE
        IF (IUIT /= 0) WRITE (IUIT, 99997, IOSTAT = IOST)
      END IF
      RETURN
99999 FORMAT ('Space Group  H-M:  ', 2A, 21X, 'Laue:', A, /,
     1 'Space Group Hall: ', A, 16X, '[Schoenflies: ', A, ']', /,
     2 'Lattice Type: ', A, ', ', A, 'entric, ', A, ', Multiplicity: ',
     3 I3, '(', I2, '), No:', I4, /)
99998 FORMAT (2X, 'Nr', 12X, '***** Symmetry Operation(s) *****', /)
99997 FORMAT (2X, 'Nr', 7X, 'Patterson/Laue Symmetry Operation', /)
99996 FORMAT ('Non-Sohncke - No Absolute Structure', /)
99995 FORMAT (A, ' - P.G.Jones, Acta Cryst. (1986),A42,57.', /)
99994 FORMAT ('Shifted Inversion Centre at (', F6.3, ',', F6.3, ',',
     1        F6.3, ')', /)
      END SUBROUTINE SG24
 
