      SUBROUTINE GEN001 (MODE, Z, T, W)
C * W = Z  * T * Z~  OR  W = Z~ * T * Z
      IMPLICIT NONE
      INTEGER :: MODE
      REAL, DIMENSION(3, 3) :: Z
      REAL, DIMENSION(3, 3) :: T
      REAL, DIMENSION(3, 3) :: V
      REAL, DIMENSION(3, 3) :: W
      REAL, DIMENSION(3, 3) :: ZTR
C * MODE =  1 : W = Z  * T * Z~  - W AND T MAY BE THE SAME MATRIX
C * MODE = -1 : W = Z~ * T * Z   - W AND T MAY BE THE SAME MATRIX
      CALL GEN005 (Z, ZTR)
      IF (MODE == 1) THEN
        CALL GEN004 (Z, T, V)
        CALL GEN004 (V, ZTR, W)
      ELSE
        CALL GEN004 (ZTR, T, V)
        CALL GEN004 (V, Z, W)
      END IF
      RETURN
      END SUBROUTINE GEN001
 
      SUBROUTINE GEN002 (MODE, A, B, C, XLNG)
C * MATVEC & NORM OR VECMAT
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: MODE
      REAL :: XLNG
      REAL :: GEN009
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(3)    :: B
      REAL, DIMENSION(3)    :: C
      REAL, DIMENSION(3)    :: V
C * MODE =    1 : MATRIX * VECTOR : C(3) = A(3, 3) * B(3)
C * MODE =   -1 : VECTOR * MATRIX : C(3) = B(3)    * A(3, 3)
C * MODE = +/-2 : +/-1 + NORMALISE C AND CALCULATE LENGTH C (XLNG)
      XLNG = 0.0
      DO I = 1, 3
        V(I) = 0.0
        IF (MODE > 0) THEN
          DO J = 1, 3
            V(I) = V(I) + A(I, J) * B(J)
          END DO
        ELSE
          DO J = 1, 3
            V(I) = V(I) + B(J) * A(J, I)
          END DO
        END IF
      END DO
      DO I = 1, 3
        C(I) = V(I)
      END DO
      IF (IABS (MODE) == 2) THEN
        XLNG = SQRT (GEN009 (C, C))
        IF (XLNG > 1.E-5) THEN
          DO I = 1, 3
            C(I) = C(I) / XLNG
          END DO
        ELSE
          XLNG = 0.0
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN002
 
      SUBROUTINE GEN003 (A, B, DET, MODE)
C * MINV
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: MODE
      REAL :: DET
      REAL :: DEEL
      REAL :: GEN009
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(3, 3) :: B
      REAL, DIMENSION(3, 3) :: C
C * MODE = 0 : INVERT 3*3 MATRIX
C * MODE = 1 : GET 'NORMALISED' COFACTOR MATRIX
      CALL GEN008 (A(1, 2), A(1, 3), B(1, 1), 0)
      CALL GEN008 (A(1, 3), A(1, 1), B(1, 2), 0)
      CALL GEN008 (A(1, 1), A(1, 2), B(1, 3), 0)
      DET = GEN009 (A(1, 1), B(1, 1))
      IF (MODE == 0) THEN
C * TRANSPOSE B
        CALL GEN005 (B, C)
C * COPY MATRIX BACK
        CALL GEN052 (C, B)
        DEEL = DET
      ELSE IF (MODE == 1) THEN
        DEEL = B(3, 3)
      ELSE IF (MODE == -2) THEN
        DEEL = DET
      ELSE
        DEEL = 0
      END IF
      IF (DEEL /= 0.0) THEN
        DO I = 1, 3
          DO J = 1, 3
            B(I, J) = B(I, J) / DEEL
          END DO
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN003
 
      SUBROUTINE GEN004 (A, B, C)
C * MATRIX PRODUCT C = A * B (THE RECEIVING ARRAY C MIGHT BE B IN THE CALL)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(3, 3) :: B
      REAL, DIMENSION(3, 3) :: C
      REAL, DIMENSION(3, 3) :: V
      DO I = 1, 3
        DO J = 1, 3
          V(I, J) = 0.0
          DO K = 1, 3
            V(I, J) = V(I, J) + A(I, K) * B(K, J)
          END DO
        END DO
      END DO
      CALL GEN052 (V, C)
      RETURN
      END SUBROUTINE GEN004
 
      SUBROUTINE GEN005 (T, TR)
C * TRANSPOSE MATRIX
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL, DIMENSION(3, 3) :: T
      REAL, DIMENSION(3, 3) :: X
      REAL, DIMENSION(3, 3) :: TR
C * TRANSPOSE MATRIX T IN TR (MAYBE T ALSO)
      DO I = 1, 3
        DO J = 1, 3
          X(J, I) = T(I, J)
        END DO
      END DO
      DO I = 1, 3
        DO J = 1, 3
          TR(I, J) = X(I, J)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN005
 
      REAL FUNCTION GEN006 (X1, QM, X2)
C * VECTOR1 * MATRIX * VECTOR2
      IMPLICIT NONE
      INTEGER :: I
      REAL :: T1
      REAL, DIMENSION(3, 3) :: QM
      REAL, DIMENSION(3)    :: X1
      REAL, DIMENSION(3)    :: X2
C * TRANSPOSED VECTOR * MATRIX * VECTOR
C * VMV=X1(3)*QM(3,3)*X2(3) TO EVALUATE QUADRATIC OR BILINEAR FORM
      T1 = 0.0
      DO I = 1, 3
        T1 = T1 + X1(I) * (X2(1) * QM(I, 1) + X2(2) * QM(I, 2)
     1     + X2(3) * QM(I, 3))
      END DO
      GEN006 = T1
      RETURN
      END FUNCTION GEN006
 
      SUBROUTINE GEN007 (AA, X, Z, ITYPE)
C * UNIP
      IMPLICIT NONE
      INTEGER :: ITYPE
      REAL :: TN
      REAL :: GEN006
      REAL :: GEN009
      REAL, DIMENSION(3)    :: X
      REAL, DIMENSION(3)    :: Z
      REAL, DIMENSION(3, 3) :: AA
      IF (ITYPE > 0) THEN
        TN = SQRT(GEN009(X, X))
      ELSE
C * TRANSPOSED VECTOR * MATRIX * VECTOR
        TN = SQRT(GEN006(X, AA, X))
      END IF
C * NORMALIZE
      IF (TN == 0.0) TN = 1.0
      Z(1) = X(1) / TN
      Z(2) = X(2) / TN
      Z(3) = X(3) / TN
      RETURN
      END SUBROUTINE GEN007
 
      SUBROUTINE GEN008 (A, B, C, MODE)
C * VECTOR PRODUCT
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: MODE
      REAL :: D
      REAL :: DSQ
      REAL, DIMENSION(3) :: A
      REAL, DIMENSION(3) :: B
      REAL, DIMENSION(3) :: C
C * MODE =  1 : C = A X B (NORMALISED TO UNIT LENGTH)
C * MODE =  0 : C = A X B
C * MODE = -1 : D = A X B, C(1) = D1**2 + D2**2 + D3**2
      C(1) = A(2) * B(3) - A(3) * B(2)
      C(2) = A(3) * B(1) - A(1) * B(3)
      C(3) = A(1) * B(2) - A(2) * B(1)
      IF (MODE /= 0) THEN
        DSQ = 0.0
        DO I = 1, 3
          IF (ABS (C(I)) < 1.0E-18) C(I) = 0.0
          DSQ = DSQ + C(I)**2
        END DO
        IF (MODE > 0) THEN
          IF (DSQ > 0.0) THEN
            D = SQRT (DSQ)
            C(1) = C(1) / D
            C(2) = C(2) / D
            C(3) = C(3) / D
          END IF
        ELSE
          C(1) = SQRT (DSQ)
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN008
 
      REAL FUNCTION GEN009 (X, Y)
C * TRANSPOSED VECTOR * VECTOR : VV = X(3) * Y(3)
      IMPLICIT NONE
      REAL, DIMENSION(3) :: X
      REAL, DIMENSION(3) :: Y
      GEN009 = X(1) * Y(1) + X(2) * Y(2) + X(3) * Y(3)
      RETURN
      END FUNCTION GEN009
 
      SUBROUTINE GEN010 (R, IDET, MODE)
C * DETERMINANT
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IDET
      INTEGER :: MODE
      REAL :: DET
      REAL :: GEN009
      REAL, DIMENSION(3, 3) :: R
      REAL, DIMENSION(3)    :: V
C * SUBROUTINE CALCULATES DETERMINANT AND RETURNS 0 OR +/-1 IN IDET
C * IDET = -1
C * IDET =  0
C * IDET =  1
      IF (MODE >= 0) THEN
        CALL GEN008 (R(1, 1), R(1, 2), V, 0)
        DET = GEN009 (R(1, 3), V)
        IF (DET > 0.999) THEN
          IDET = 1
        ELSE IF (DET < -0.999) THEN
          IDET = -1
        ELSE
          IDET = 0
        END IF
      END IF
      IF (MODE /= 0) THEN
        DO I = 1, 3
          DO J = 1, 3
            R(I, J) = IDET * R(I, J)
          END DO
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN010
 
      SUBROUTINE GEN011 (BB, X, Y, Z, ITYPE)
C * NORM
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: ITYPE
      REAL :: T1
      REAL :: XLNG
      REAL, DIMENSION(3)    :: X
      REAL, DIMENSION(3)    :: Y
      REAL, DIMENSION(3)    :: Z
      REAL, DIMENSION(3)    :: Z1
      REAL, DIMENSION(3, 3) :: BB
C * ITYPE > 0 FOR CARTESIAN
C * ITYPE < 0 FOR TRICLINIC
      DO I = 1, 3
        I1 = MOD (I + 3, 3) + 1
        I2 = MOD (I + 1, 3) + 1
        T1 = X(I1) * Y(I2) - X(I2) * Y(I1)
        IF (ABS (T1) < 1.E-6) T1 = 0.0
        IF (ITYPE > 0) THEN
          Z(I) = T1
        ELSE
          Z1(I) = T1
        END IF
      END DO
      IF (ITYPE <= 0) CALL GEN002 (1, BB, Z1, Z, XLNG)
      RETURN
      END SUBROUTINE GEN011
 
      SUBROUTINE GEN012 (B, A, NN, DAMP, DA, R)
C * MATRIX INVERSION
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: NI
      INTEGER :: NK
      INTEGER :: NN
      REAL :: R
      REAL :: T
      REAL :: DA
      REAL :: DAMP
      REAL, DIMENSION(*) :: A
      REAL, DIMENSION(*) :: B
C * DA & DAMP MAY BE SET TO 0.0, R TO 1.0
      K = 0
      L = 0
      J = NN + 1
      DO NI = 1, NN
        K = K + 2
        I = J - 1
        M = J + 1
        B(J) = 1.0 / AMAX1 (B(J) + DA * DAMP, 0.1 * DA, 1.E-10)
        IF (NI < NN) THEN
   10     B(K) = - B(J) * B(M)
          M    = M + 1
          K    = K + 1
          IF (K >= J) THEN
            L = J + NI - NN
            J = J + 1
            IF (I >= L) THEN
   20         B(M) = B(J) * B(L) + B(M)
              M    = M + 1
              L    = L + 1
              IF (I < L) THEN
                L = J + NI - NN
                J = J + 1
                IF (I < L) CYCLE
              ENDIF
              GO TO 20
            ELSE
              CYCLE
            ENDIF
          ENDIF
          GO TO 10
        END IF
      END DO
      NI   = NN - 1
   30 NI   = NI - 1
      J    = K
      M    = K + NI - NN
      L    = M - 1
      I    = M + 1
      K    = I + NI - NN
   40 B(I) = 0.0
      I    = I + 1
      IF (I < J) GO TO 40
   50 M    = M + 1
      B(M) = B(K) * B(J) + B(M)
      I    = M
      NK   = K + 1
   60 IF (L >= NK) THEN
        J    = J + 1
        I    = I + 1
        B(I) = B(K)  * B(J) + B(I)
        B(M) = B(NK) * B(J) + B(M)
        NK   = NK + 1
        GO TO 60
      END IF
      B(NK) = B(K) * B(M) + B(NK)
      J     = J + 1
      K     = K + 1
      IF (L  >= K) GO TO 50
      IF (NI > 0) GO TO 30
      CALL GEN074 (B, 1, NN, 0.0)
      L = NN + 1
      DO I = 1, NN
        B(I) = B(I) - B(L) * A(I)
        T = B(L) * R
        DO K = I, NN
          B(I) = B(L) * A(K) + B(I)
          B(K) = B(L) * A(I) + B(K)
          L    = L + 1
        END DO
        A(I) = SQRT (ABS (T))
      END DO
      RETURN
      END SUBROUTINE GEN012
 
      REAL FUNCTION GEN013 (N)
C * RANDOM NUMBER GENERATOR
      IMPLICIT NONE
      INTEGER, PARAMETER :: M  = 714025
      INTEGER, PARAMETER :: IA = 1366
      INTEGER, PARAMETER :: IC = 150889
      INTEGER       :: J
      INTEGER, SAVE :: IY
      INTEGER       :: N
      INTEGER, DIMENSION(97), SAVE :: IR
      REAL, SAVE :: RM
      IF (N < 0) THEN
        RM = 1.0 / M
        N = MOD (IC - N, M)
        DO J = 1, 97
          N = MOD (IA * N + IC, M)
          IR(J) = N
        END DO
        N = MOD (IA * N + IC, M)
        IY   = N
      END IF
      J = 1 + (97 * IY) / M
      IF (J > 97 .OR. J < 1) STOP 'IN RANDOM'
      IY       = IR(J)
      GEN013   = IY * RM
      N        = MOD (IA * N + IC, M)
      IR(J)    = N
      RETURN
      END FUNCTION GEN013
 
      SUBROUTINE GEN014 (I, J)
C * SWAP INTEGERS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      K = I
      I = J
      J = K
      RETURN
      END SUBROUTINE GEN014
 
      SUBROUTINE GEN015 (A, B, C, XMUL)
C * Add/Subtract 3-vector B to/from 3-vector A
      IMPLICIT NONE
      INTEGER :: I
      REAL :: XMUL
      REAL, DIMENSION(3) :: A
      REAL, DIMENSION(3) :: B
      REAL, DIMENSION(3) :: C
      DO I = 1, 3
        C(I) = A(I) + XMUL * B(I)
      END DO
      RETURN
      END SUBROUTINE GEN015
 
      REAL FUNCTION GEN016 (X1, QM, X2)
C * ANGLE BETWEEN TWO VECTORS
      IMPLICIT NONE
      REAL :: A
      REAL :: B
      REAL :: C
      REAL :: RAD
      REAL :: GEN006
      REAL, DIMENSION(3)    :: X1
      REAL, DIMENSION(3)    :: X2
      REAL, DIMENSION(3, 3) :: QM
      RAD    = ATAN2 (1.0, 1.0) / 45.0
      A      = GEN006 (X1, QM, X2)
      B      = GEN006 (X1, QM, X1)
      C      = GEN006 (X2, QM, X2)
      GEN016 = ACOS (A / SQRT (B * C)) / RAD
      RETURN
      END FUNCTION GEN016
 
      REAL FUNCTION GEN017 (V)
C * NORMALIZE VECTOR
      IMPLICIT NONE
      INTEGER :: I
      REAL :: D
      REAL, DIMENSION(3) :: V
      D = SQRT (V(1) ** 2 + V(2) ** 2 + V(3) ** 2)
      IF (D < 0.00001) THEN
        GEN017 = 0.0
      ELSE
        GEN017 = D
        DO I = 1, 3
          V(I) = V(I) / D
        END DO
      END IF
      RETURN
      END FUNCTION GEN017
 
      SUBROUTINE GEN018 (A, B)
C * SWAP REALS
      IMPLICIT NONE
      REAL :: A
      REAL :: B
      REAL :: C
      C = A
      A = B
      B = C
      RETURN
      END SUBROUTINE GEN018
 
      SUBROUTINE GEN019 (AA, BB, U, V, X, ITYPE)
C * STORE THREE ORTHOGONAL VECTORS EACH 1 ANGSTROM LONG
C * ITYPE .GT.0 FOR CARTESIAN,.LT.0 FOR TRICLINIC
C * IABS(ITYPE)=1 W(1)=U,W(2)=(UXV),W(3)=UX(UXV)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IT
      INTEGER :: ITYPE
      REAL, DIMENSION(3)    :: U
      REAL, DIMENSION(3)    :: V
      REAL, DIMENSION(3, 3) :: W
      REAL, DIMENSION(3, 3) :: X
      REAL, DIMENSION(3, 3) :: AA
      REAL, DIMENSION(3, 3) :: BB
      IT = ITYPE
      DO I = 1, 3
         W(I, 1) = U(I)
      END DO
      CALL GEN011 (BB, U, V, W(1, 2), IT)
      CALL GEN011 (BB, U, W(1, 2), W(1, 3), IT)
      DO I = 1, 3
        CALL GEN007 (AA, W(1, I), X(1, I), IT)
      END DO
      RETURN
      END SUBROUTINE GEN019
 
      SUBROUTINE GEN020 (MODE, ICL, IMIN, IMAX)
C * UPPER/LOWER CASE CONVERSION
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: MODE
      INTEGER :: IMIN
      INTEGER :: IMAX
      CHARACTER(len=*) :: ICL
      IF (IMAX >= IMIN) THEN
C * MODE =  1 - CONVERT TO UPPER CASE
C * MODE = -1 - CONVERT TO LOWER CASE
        IF (MODE > 0) THEN
          DO I = IMIN, IMAX
            IF (ICL(I:I) == CHAR (9)) ICL(I:I) = ' '
            CALL GEN105 (2, ICL(I:I), N)
            IF (N > 0) ICL(I:I) = CHAR (N + ICHAR ('A') - ICHAR ('a'))
          END DO
        ELSE
          DO I = IMIN, IMAX
            CALL GEN105 (1, ICL(I:I), N)
            IF (N > 0) ICL(I:I) = CHAR (N - ICHAR ('A') + ICHAR ('a'))
          END DO
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN020
 
      SUBROUTINE GEN021 (X, VAL)
C * INIT MATRIX ON SUPPLIED REAL VALUE ON THE DIAGONAL, 0.0 OTHERWISE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL :: VAL
      REAL, DIMENSION(3, 3) :: X
      DO I = 1, 3
        DO J = 1, 3
          IF (I == J) THEN
            X(I, I) = VAL
          ELSE
            X(I, J) = 0.0
          END IF
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN021
 
      SUBROUTINE GEN022 (NA, N0, N, M)
C * SHELL-SORT NA FROM N0 TO N (M=1:SMALL TO LARGE;M=-1:LARGE TO SMALL)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: M
      INTEGER :: N0
      INTEGER :: ND
      INTEGER :: NY
      INTEGER :: NEL
      INTEGER, DIMENSION(*) :: NA
      NEL = N - N0 + 1
      IF (NEL > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (NEL)) / ALOG (2.0)) + 1.0E-5)) - 1
        DO WHILE (ND > 0)
          I = N0
          DO
            J = I
            NY = NA(I + ND)
            DO
              IF (M == 1) THEN
                IF (NY >= NA(J)) EXIT
              ELSE
                IF (NY <= NA(J)) EXIT
              END IF
              NA(J + ND) = NA(J)
              J = J - ND
              IF (J < N0) EXIT
            END DO
            NA(J + ND) = NY
            I = I + 1
            IF (I + ND >  N) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN022
 
      SUBROUTINE GEN023 (A, R, N)
C * EW, EV FOR SYMMETRICAL MATRIX
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IA
      INTEGER :: IQ
      INTEGER :: JQ
      INTEGER :: IL
      INTEGER :: IM
      INTEGER :: IJ
      INTEGER :: LQ
      INTEGER :: MQ
      INTEGER :: LL
      INTEGER :: LM
      INTEGER :: MM
      INTEGER :: IND
      INTEGER :: ILQ
      INTEGER :: IMQ
      INTEGER :: ILR
      INTEGER :: IMR
      REAL :: X
      REAL :: Y
      REAL :: Y2
      REAL :: SINX
      REAL :: COSX
      REAL :: SINX2
      REAL :: COSX2
      REAL :: SINCS
      REAL :: ANORM
      REAL :: ANRMX
      REAL :: RANGEX
      REAL :: THR
      REAL, DIMENSION(*) :: A
      REAL, DIMENSION(*) :: R
      RANGEX = 1.0E-6
C * GENERATE IDENTITY MATRIX
      IQ = - N
      DO J = 1, N
        IQ = IQ + N
        DO I = 1, N
          IJ = IQ + I
          IF (I == J) THEN
            R(IJ) = 1.0
          ELSE
            R(IJ) = 0.0
          END IF
        END DO
      END DO
C * COMPUTE INITIAL AND FINAL NORMS (ANORM AND ANORMX)
      ANORM = 0.0
      DO I = 1, N
        DO J = I, N
          IF (I /= J) THEN
            IA    = I + (J * J - J) / 2
C * AVOID UNDERFLOW
            IF (ABS (A(IA)) > 0.1E-17) THEN
              ANORM = ANORM + A(IA)**2
            END IF
          END IF
        END DO
      END DO
      IF (ANORM > 0.0) THEN
        ANORM = 1.414 * SQRT (ANORM)
        ANRMX = ANORM * RANGEX / FLOAT(N)
C * INITIALIZE INDICATORS AND COMPUTE THRESHOLD, THR
        IND = 0
        THR = ANORM
        DO
          THR = THR / FLOAT (N)
   10     L   = 1
   20     M   = L + 1
C * COMPUTE SIN AND COS
   30     MQ = (M * M - M) / 2
          LQ = (L * L - L) / 2
          LM = L + MQ
          IF (ABS (A(LM)) >= THR) THEN
            IND = 1
            LL  = L + LQ
            MM  = M + MQ
            X   = 0.5 * (A(LL) - A(MM))
            Y   = -A(LM) / SQRT (A(LM) * A(LM) + X**2)
            IF (X < 0.0) Y  = - Y
            Y2 = Y**2
            IF (Y2 < 1.0) THEN
              SINX = Y / SQRT (2.0 * (1.0 + (SQRT (1.0 - Y2))))
            ELSE
              SINX = Y / SQRT (2.0)
            END IF
            SINX2 = SINX * SINX
            COSX  = SQRT (1.0 - SINX2)
            COSX2 = COSX**2
            SINCS = SINX * COSX
C * ROTATE L AND M COLUMNS
            ILQ = N * (L - 1)
            IMQ = N * (M - 1)
            DO I = 1, N
              IQ = (I * I - I) / 2
              IF (I /= L) THEN
                IF (I > M) THEN
                  IM = M + IQ
                ELSE IF (I == M) THEN
                  GO TO 40
                ELSE
                  IM = I + MQ
                END IF
                IF (I < L) THEN
                  IL = I + LQ
                ELSE
                  IL = L + IQ
                END IF
                X     = A(IL) * COSX - A(IM) * SINX
                A(IM) = A(IL) * SINX + A(IM) * COSX
                A(IL) = X
              END IF
   40         ILR    = ILQ + I
              IMR    = IMQ + I
              X      = R(ILR) * COSX - R(IMR) * SINX
              R(IMR) = R(ILR) * SINX + R(IMR) * COSX
              R(ILR) = X
            END DO
            X     = 2.0 * A(LM) * SINCS
            Y     = A(LL) * COSX2 + A(MM) * SINX2 - X
            X     = A(LL) * SINX2 + A(MM) * COSX2 + X
            A(LM) = (A(LL) - A(MM)) * SINCS + A(LM) * (COSX2 - SINX2)
            A(LL) = Y
            A(MM) = X
          END IF
C * TESTS FOR COMPLETION
C * TEST FOR M = LAST COLUMN
          IF (M /= N) THEN
            M = M + 1
            GO TO 30
          END IF
C * TEST FOR L = SECOND FROM LAST COLUMN
          IF (L /= (N - 1)) THEN
            L = L + 1
            GO TO 20
          END IF
          IF (IND == 1) THEN
            IND = 0
            GO TO 10
          END IF
C * COMPARE THRESHOLD WITH FINAL NORM
          IF (THR <= ANRMX) EXIT
        END DO
      END IF
C * SORT EIGENVALUES AND EIGENVECTORS
      IQ = - N
      DO I = 1, N
        IQ = IQ + N
        LL = I + (I * I - I) / 2
        JQ = N * (I - 2)
        DO J = I, N
          JQ = JQ + N
          MM = J + (J * J - J) / 2
          IF (A(LL) < A(MM)) THEN
            X     = A(LL)
            A(LL) = A(MM)
            A(MM) = X
            DO K = 1, N
              ILR    = IQ + K
              IMR    = JQ + K
              X      = R(ILR)
              R(ILR) = R(IMR)
              R(IMR) = X
            END DO
          END IF
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN023
 
      SUBROUTINE GEN024 (W, EV, EW, DUMV)
C * CALCULATE EIGENVECTORS AND EIGENVALUES FOR SYMM. 3X3 MATRIX W
C * EIGENVECTORS AS COLUMN VECTORS IN DUMV AND ROW VECTORS IN EV
      IMPLICIT NONE
      REAL, DIMENSION(3, 3) :: W
      REAL, DIMENSION(3, 3) :: EV
      REAL, DIMENSION(3)    :: EW
      REAL, DIMENSION(6)    :: DUMA
      REAL, DIMENSION(3, 3) :: DUMV
      DUMA(1) = W(1, 1)
      DUMA(2) = W(1, 2)
      DUMA(3) = W(2, 2)
      DUMA(4) = W(1, 3)
      DUMA(5) = W(2, 3)
      DUMA(6) = W(3, 3)
      CALL GEN023 (DUMA, DUMV, 3)
C * ENSURE THAT THE EIGENVECTORS DETERMINE A RIGHT-HANDED AXIS SYSTEM
      CALL GEN008 (DUMV(1, 1), DUMV(1, 2), DUMV(1, 3), 1)
      CALL GEN005 (DUMV, EV)
      EW(1) = DUMA(1)
      EW(2) = DUMA(3)
      EW(3) = DUMA(6)
      RETURN
      END SUBROUTINE GEN024
 
      SUBROUTINE GEN025 (A, V, MODE)
C * MODE =  1 : SYMMETRIC MATRIX TO VECTOR
C * MODE = -1 : VECTOR TO SYMMETRIC MATRIX
      IMPLICIT NONE
      INTEGER :: MODE
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(6)    :: V
      IF (MODE > 0) THEN
        V(1) = A(1, 1)
        V(2) = A(2, 2)
        V(3) = A(3, 3)
        V(4) = A(2, 3)
        V(5) = A(1, 3)
        V(6) = A(1, 2)
      ELSE
        A(1, 1) = V(1)
        A(2, 2) = V(2)
        A(3, 3) = V(3)
        A(2, 3) = V(4)
        A(3, 2) = V(4)
        A(1, 3) = V(5)
        A(3, 1) = V(5)
        A(1, 2) = V(6)
        A(2, 1) = V(6)
      END IF
      RETURN
      END SUBROUTINE GEN025
 
      SUBROUTINE GEN026 (MODE, A, V)
C * METRIC TO CELL AND VISA VERSA
      IMPLICIT NONE
      INTEGER :: MODE
      REAL :: RAD
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(6)    :: V
      RAD = ATAN2 (1.0, 1.0) / 45.0
      IF (MODE == 1) THEN
C * SET UP METRICAL MATRIX FROM CELL PARAMETERS
        A(1, 2) = 0.0
        A(1, 3) = 0.0
        A(2, 3) = 0.0
        A(1, 1) = V(1) * V(1)
        A(2, 2) = V(2) * V(2)
        A(3, 3) = V(3) * V(3)
        IF (ABS (V(6) - 90.0) > 0.00001)
     1    A(1, 2) = V(1) * V(2) * COS (V(6) * RAD)
        A(2, 1) = A(1, 2)
        IF (ABS (V(5) - 90.0) > 0.00001)
     1    A(1, 3) = V(1) * V(3) * COS (V(5) * RAD)
        A(3, 1) = A(1, 3)
        IF (ABS (V(4) - 90.0) > 0.00001)
     1    A(2, 3) = V(2) * V(3) * COS (V(4) * RAD)
        A(3, 2) = A(2, 3)
      ELSE IF (MODE == -1) THEN
C * RECOVER CELL PARAMETERS FROM METRIC
        V(1) = SQRT (A(1, 1))
        V(2) = SQRT (A(2, 2))
        V(3) = SQRT (A(3, 3))
        V(4) = ACOS (A(2, 3) / (V(2) * V(3))) / RAD
        V(5) = ACOS (A(1, 3) / (V(1) * V(3))) / RAD
        V(6) = ACOS (A(1, 2) / (V(1) * V(2))) / RAD
      END IF
      RETURN
      END SUBROUTINE GEN026
 
      REAL FUNCTION GEN027 (V1, V2, P5)
C * CALCULATE ANGLE BETWEEN VECTORS
      IMPLICIT NONE
      REAL :: P5
      REAL :: ANG
      REAL :: GEN009
      REAL, DIMENSION(*) :: V1
      REAL, DIMENSION(*) :: V2
      ANG = GEN009 (V1, V2)
      IF (ANG >  1.0) ANG =  1.0
      IF (ANG < -1.0) ANG = -1.0
      GEN027 = ACOS (ANG) * P5
      RETURN
      END FUNCTION GEN027
 
      SUBROUTINE GEN028 (XAR, NN, NDM, ITEKEN)
C * FFT
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: IA
      INTEGER :: IB
      INTEGER :: IC
      INTEGER :: KA
      INTEGER :: KB
      INTEGER :: IDM
      INTEGER :: NDM
      INTEGER :: IPA
      INTEGER :: IPB
      INTEGER :: IPC
      INTEGER :: IBIT
      INTEGER :: NPRV
      INTEGER :: NTOT
      INTEGER :: NREM
      INTEGER :: IBRV
      INTEGER :: IFPA
      INTEGER :: IFPB
      INTEGER :: ICRV
      INTEGER :: ITEKEN
      INTEGER, DIMENSION(NDM) :: NN
      REAL :: SWI
      REAL :: SWR
      REAL :: YKI
      REAL :: YKR
      REAL :: XARKB
      REAL :: XARKB1
      REAL, DIMENSION(*) :: XAR
      DOUBLE PRECISION :: WR
      DOUBLE PRECISION :: WI
      DOUBLE PRECISION :: TH
      DOUBLE PRECISION :: WPR
      DOUBLE PRECISION :: WPI
      DOUBLE PRECISION :: WYK
C * REPLACES XAR BY ITS NDM-DIMENSIONAL DISCRETE FOURIER TRANSFORM,
C * IF ISIGN IS INPUT AS 1. NN IS AN INTEGER ARRAY OF LENGTH NDM,
C * CONTAINING THE LENGTHS OF EACH DIMENSION (NUMBER OF COMPLEX VALUES),
C * WHICH MUST ALL BE POWERS OF 2. XAR IS A REAL ARRAY OF LENGTH TWICE
C * THE PRODUCT OF THESE LENGTHS, IN WHICH THE DATA ARE STORED AS IN A
C * MULTIDIMENSIONAL COMPLEX FORTRAN ARRAY. IF ISIGN IS INPUT AS -1,
C * XAR IS REPLACED BY ITS INVERSE TRANSFORM TIMES THE PRODUCT OF THE
C * LENGTHS OF ALL DIMENSIONS.
      NPRV = 1
      NTOT = 1
      DO IDM = 1, NDM
        NTOT = NTOT * NN(IDM)
      END DO
      DO IDM = 1, NDM
        N    = NN(IDM)
        NREM = NTOT / (N * NPRV)
        IPA  = 2 * NPRV
        IPB  = IPA * N
        IPC  = IPB * NREM
        IBRV = 1
        DO IB = 1, IPB, IPA
          IF (IB < IBRV) THEN
            DO IA = IB, IB + IPA - 2, 2
              DO IC = IA, IPC, IPB
                ICRV          = IBRV + IC - IB
                YKR           = XAR(IC)
                YKI           = XAR(IC + 1)
                XAR(IC)       = XAR(ICRV)
                XAR(IC + 1)   = XAR(ICRV + 1)
                XAR(ICRV)     = YKR
                XAR(ICRV + 1) = YKI
              END DO
            END DO
          END IF
          IBIT = IPB / 2
   10     IF ((IBIT >= IPA) .AND. (IBRV > IBIT)) THEN
            IBRV = IBRV - IBIT
            IBIT = IBIT / 2
            GO TO 10
          END IF
          IBRV = IBRV + IBIT
        END DO
        IFPA = IPA
   20   IF (IFPA < IPB) THEN
          IFPB = 2 * IFPA
          TH   = ITEKEN * 6.28318530717959D0 / (IFPB / IPA)
          WPR  = -2.D0 * DSIN (0.5D0 * TH)**2
          WPI  = DSIN (TH)
          WR   = 1.D0
          WI   = 0.D0
          DO IC = 1, IFPA, IPA
            DO IA = IC, IC + IPA - 2, 2
              DO IB = IA, IPC, IFPB
                KA     = IB
                KB     = KA + IFPA
                SWR    = SNGL (WR)
                SWI    = SNGL (WI)
                XARKB  = XAR(KB)
                IF (ABS (XARKB) < 1.0E-15) XARKB = 0.0
                XARKB1 = XAR(KB + 1)
                IF (ABS (XARKB1) < 1.0E-15) XARKB1 = 0.0
                YKR    = SWR * XARKB  - SWI * XARKB1
                YKI    = SWR * XARKB1 + SWI * XARKB
                XAR(KB)     = XAR(KA)     - YKR
                XAR(KB + 1) = XAR(KA + 1) - YKI
                XAR(KA)     = XAR(KA)     + YKR
                XAR(KA + 1) = XAR(KA + 1) + YKI
              END DO
            END DO
            WYK = WR
            WR  = WR * WPR - WI  * WPI + WR
            WI  = WI * WPR + WYK * WPI + WI
          END DO
          IFPA = IFPB
          GO TO 20
        END IF
        NPRV = N * NPRV
      END DO
      RETURN
      END SUBROUTINE GEN028
 
      SUBROUTINE GEN029 (A, VAL, VECTOR, M, IA, IV, W)
C * EWEV1
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: I1
      INTEGER :: M1
      INTEGER :: II
      INTEGER :: IA
      INTEGER :: IV
      REAL :: PP
      REAL, DIMENSION(IA, M) :: A
      REAL, DIMENSION(*)     :: W
      REAL, DIMENSION(M)     :: VAL
      REAL, DIMENSION(IV, M) :: VECTOR
C * THE FOLLOWING ROUTINES ARE FROM THE HARWELL SUBROUTINE LIBRARY
C * Given a real mXm symmetric matrix A = {aij} this routine finds all its
C * eigenvalues (lambda)i i=1,2,.....,m and eigenvectors xj i=1,2,...,m.
C * i.e. finds the non-trivial solutions of Ax=(lambda)x
C * Argument list: SUBROUTINE GEN029(A, VAL, X, M, IA, IX, W)
C * Arguments set by the user -
C * A  is a REAL 2-dimensional array with first dimension IA. The user must
C *    store the lower triangle of matrix A into the lower triangle of the
C *    array A. i.e. put a(ij) into A(I,J) for i>=j and I>=J.
C * M  is an INTEGER and should be set to the order m of the matrix
C * IA is an INTEGER set to the first dimension of the array A, i.e. if the
C *    allocation for the array A was specified by
C *           DIMENSION A(100,50)
C *    then IA would be set to 100
C * IX is an INTEGER set to the first dimension of the 2-dimensional array X
C * Arguments set by the routine -
C * A  the space above the diagonal of the array A is used by the routine as
C *    work space, the lower triangle set by the user will remain unchanged
C *    on return.
C * VALUE is a REAL array in which the routine puts the eigenvalues  (lambda)
C *    i=1,2,...,m. These are not necessarily in any order.
C * X  is a REAL 2-dimensional array, with first dimension IX, containing the
C *   eigenvectors. The components of the eigenvector x(i) corresponding to the
C *   eigenvalue (lambda)i (in VALUE(I)) are placed in X(J,I) J=1,2,...,M.
C *    The eigenvectors are normalized so that xT(i)x(i)=1 i=1,2,...,m.
C * W  is a REAL array used by the routine for work space. It must have
C *   dimension at least 5*M.
      M1   = M + 1
      W(1) = A(1, 1)
      IF (M == 2) THEN
        W(2) = A(2, 2)
        W(4) = A(2, 1)
      ELSE IF (M > 2) THEN
        CALL GEN030 (A, W, W(M1), M, IA, W(M + M1))
      END IF
      CALL GEN031 (W, W(M1), VAL, VECTOR, M, IV, W(M + M1))
      IF (M > 2) THEN
        DO L = 1, M
          DO II = 3, M
            I = M - II + 1
            IF (W(M1 + I) /= 0.0) THEN
              PP = 0.0
              I1 = I + 1
              DO K = I1, M
                PP = PP + A(I, K) * VECTOR(K, L)
              END DO
              PP = PP / (A(I, I + 1) * W(M1 + I))
              DO K = I1, M
                VECTOR(K, L) = VECTOR(K, L) + PP * A(I, K)
              END DO
            END IF
          END DO
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN029
 
      SUBROUTINE GEN030 (A, ALPHA, BETA, M, IA, Q)
C * EWEV2
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: J1
      INTEGER :: M2
      INTEGER :: IA
      INTEGER :: KI
      INTEGER :: KJ
      REAL :: H
      REAL :: PP
      REAL :: QJ
      REAL :: PP1
      REAL :: BIGK
      REAL, DIMENSION(IA, *) :: A
      REAL, DIMENSION(*)     :: ALPHA
      REAL, DIMENSION(*)     :: BETA
      REAL, DIMENSION(*)     :: Q
      ALPHA(1) = A(1, 1)
      DO J = 2, M
        J1 = J - 1
        DO I = 1, J1
          A(I, J) = A(J, I)
        END DO
        ALPHA(J) = A(J, J)
      END DO
      M2 = M - 2
      DO I = 1, M2
        PP = 0.0
        I1 = I + 1
        DO J = I1, M
          PP = PP + A(I, J)**2
        END DO
        PP1 = SQRT (PP)
        IF (A(I, I + 1) >= 0.0) THEN
          BETA(I + 1) = -PP1
        ELSE
          BETA(I + 1) = PP1
        END IF
        IF (PP > 0.0) THEN
          H = PP - BETA(I + 1) * A(I, I + 1)
          A(I, I + 1) = A(I, I + 1) - BETA(I + 1)
          DO KI = I1, M
            QJ = 0.0
            DO KJ = I1, KI
              QJ = QJ + A(KJ, KI) * A(I, KJ)
            END DO
            IF(KI < M) THEN
              I2 = KI + 1
              DO KJ = I2, M
                QJ = QJ + A(KI, KJ) * A(I, KJ)
              END DO
            END IF
            Q(KI) = QJ / H
          END DO
          BIGK = 0.0
          DO KJ = I1, M
            BIGK = BIGK + A(I, KJ) * Q(KJ)
          END DO
          BIGK = BIGK / (2.0 * H)
          DO KJ = I1, M
            Q(KJ) = Q(KJ) - BIGK * A(I, KJ)
          END DO
          DO KI = I1, M
            DO KJ = KI, M
              A(KI, KJ) = A(KI, KJ) - Q(KI) * A(I, KJ)
     1                  - Q(KJ) * A(I, KI)
            END DO
          END DO
        END IF
      END DO
      DO I = 2, M
        H = ALPHA(I)
        ALPHA(I) = A(I, I)
        A(I, I)  = H
      END DO
      BETA(M) = A(M - 1, M)
      RETURN
      END SUBROUTINE GEN030
 
      SUBROUTINE GEN031 (A, B, VAL, VEC, M, IV, W)
C * EWEV3
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: II
      INTEGER :: IV
      INTEGER :: JI
      INTEGER :: JK
      INTEGER :: ITER
      INTEGER :: N2M1
      REAL :: S
      REAL :: SI
      REAL :: CO
      REAL :: XX
      REAL :: V1
      REAL :: V2
      REAL :: A11
      REAL :: A12
      REAL :: A13
      REAL :: A21
      REAL :: A22
      REAL :: A23
      REAL :: A33
      REAL :: A34 = 0.0
      REAL :: EPS = 1E-5
      REAL :: XAX
      REAL :: ROOT
      REAL, DIMENSION(M) :: A
      REAL, DIMENSION(M) :: B
      REAL, DIMENSION(M) :: VAL
      REAL, DIMENSION(*) :: VEC
      REAL, DIMENSION(*) :: W
C * THIS USES QR ITERATION TO FIND THE EIGENVALUES AND EIGENVECTORS
C * OF THE SYMMETRIC TRIDIAGONAL MATRIX WHOSE DIAGONAL ELEMENTS ARE
C * A(I),I=1,M AND OFF-DIAGONAL ELEMENTS ARE B(I),I=2,M.  THE ARRAY
C * W IS USED FOR WORKSPACE AND MUST HAVE DIMENSION AT LEAST 2*M.
C * WE TREAT VEC AS IF IT HAD DIMENSIONS (IV,M).
      CALL GEN032 (A, B, W(M + 1), M, W)
C * SET VEC TO THE IDENTITY MATRIX.
      DO I = 1, M
        VAL(I) = A(I)
        W(I) = B(I)
        K = (I - 1) * IV + 1
        L = K + M - 1
        DO J = K, L
          VEC(J) = 0.0
        END DO
        VEC(K + I - 1) = 1.0
      END DO
      ITER = 0
      IF (M /= 1) THEN
        N2 = M
C * EACH QR ITERATION IS PERFORMED OF ROWS AND COLUMNS N1 TO N2
   10   DO II = 2, N2
          N1 = 2 + N2 - II
          IF (ABS (W(N1)) <= (ABS (VAL(N1 - 1))
     1              + ABS (VAL(N1))) * EPS) GO TO 20
        END DO
        N1 = 1
   20   IF (N2 == N1) THEN
          N2 = N2 - 1
          IF (N2 <= 1) THEN
            GO TO 30
          ELSE
            GO TO 10
          END IF
        END IF
        ROOT = W(M + N2)
        ITER = ITER + 1
        N2M1 = N2 - 1
        A22  = VAL(N1)
        A12  = A22 - ROOT
        A23  = W(N1 + 1)
        A13  = A23
        DO I = N1, N2M1
          A33 = VAL(I + 1)
          IF (I /= N2M1) A34 = W(I + 2)
          S = SIGN (SQRT (A12 * A12 + A13 * A13), A12)
          SI = A13 / S
          CO = A12 / S
          JK = I * IV + 1
          J1 = JK - IV
          J2 = J1 + MIN0 (M, I + ITER) - 1
          DO JI = J1, J2
            V1 = VEC(JI)
            V2 = VEC(JK)
            VEC(JI) = V1 * CO + V2 * SI
            VEC(JK) = V2 * CO - V1 * SI
            JK = JK + 1
          END DO
          IF (I /= N1) W(I) = S
          A11 = CO * A22 + SI * A23
          A12 = CO * A23 + SI * A33
          A13 = SI * A34
          A21 = CO * A23 - SI * A22
          A22 = CO * A33 - SI * A23
          A23 = CO * A34
          VAL(I) = A11 * CO + A12 * SI
          A12 = - A11 * SI + A12 * CO
          W(I + 1) = A12
          A22 = A22 * CO - A21 * SI
        END DO
        VAL(N2) = A22
        GO TO 10
C * RAYLEIGH QUOTIENT
   30   DO J = 1, M
          K = (J - 1) * IV
          XX = VEC(K + 1)**2
          XAX = XX * A(1)
          DO I = 2, M
            XX = XX + VEC(K + I)**2
            XAX = XAX + VEC(K + I) * (2.0 * B(I) * VEC(K + I - 1)
     1          + A(I) * VEC(K + I))
          END DO
          VAL(J) = XAX / XX
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN031
 
      SUBROUTINE GEN032 (A, B, VAL, M, OFF)
C * EWEV4
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: II
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N2M1
      REAL :: S
      REAL :: A11
      REAL :: A12
      REAL :: A13
      REAL :: A21
      REAL :: A22
      REAL :: A23
      REAL :: A33
      REAL :: A34 = 0.0
      REAL :: SI
      REAL :: CO
      REAL :: BB
      REAL :: CC
      REAL :: EPS = 0.6E-7
      REAL :: SBB
      REAL :: ROOT
      REAL, DIMENSION(M) :: A
      REAL, DIMENSION(M) :: B
      REAL, DIMENSION(M) :: VAL
      REAL, DIMENSION(M) :: OFF
      VAL(1) = A(1)
      IF (M == 1) RETURN
      DO I = 2, M
        VAL(I) = A(I)
        OFF(I) = B(I)
      END DO
C * EACH QR ITERATION IS PERFORMED OF ROWS AND COLUMNS N1 TO N2
      N2 = M
   10 IF (N2 > 1) THEN
        DO II = 2, N2
          N1 = 2 + N2 - II
          IF (ABS (OFF(N1)) <= (ABS (VAL(N1 - 1))
     1      + ABS (VAL(N1))) * EPS) GO TO 20
        END DO
        N1 = 1
   20   IF (N2 == N1) THEN
          N2 = N2 - 1
          GO TO 10
        END IF
C * ROOT IS THE EIGENVALUE OF THE BOTTOM 2*2 MATRIX THAT IS NEAREST
C * TO THE LAST MATRIX ELEMENT AND IS USED TO ACCELERATE THE CONVERGENCE
        BB  = (VAL(N2) - VAL(N2 - 1)) * 0.5
        CC  = OFF(N2) * OFF(N2)
        SBB = 1.0
        IF (BB < 0.0) SBB = -1.0
        ROOT = VAL(N2) + CC / (BB + SBB * SQRT (BB * BB + CC))
        N2M1 = N2 - 1
        A22  = VAL(N1)
        A12  = A22 - ROOT
        A23  = OFF(N1 + 1)
        A13  = A23
        DO I = N1, N2M1
          A33 = VAL(I + 1)
          IF (I /= N2M1) A34 = OFF(I + 2)
          S = SQRT (A12 * A12 + A13 * A13)
          SI = A13 / S
          CO = A12 / S
          IF (I /= N1) OFF(I) = S
          A11 = CO * A22 + SI * A23
          A12 = CO * A23 + SI * A33
          A13 = SI * A34
          A21 = CO * A23 - SI * A22
          A22 = CO * A33 - SI * A23
          A23 = CO * A34
          VAL(I) = A11 * CO + A12 * SI
          A12 = - A11 * SI + A12 * CO
          OFF(I + 1) = A12
          A22 = A22 * CO - A21 * SI
        END DO
        VAL(N2) = A22
        GO TO 10
      END IF
      RETURN
      END SUBROUTINE GEN032
 
      SUBROUTINE GEN033 (IA, IB, NB, NE)
C * REARRANGE VALUES IN ARRAY IB BASED ON ORDERING ARRAY IA (ASCENDING)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: ND
      INTEGER :: NY
      INTEGER :: NZ
      INTEGER, DIMENSION(*) :: IA
      INTEGER, DIMENSION(*) :: IB
      N = NE - NB + 1
      IF (N > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (N)) / ALOG (2.0)) + 1.0e-5)) -1
        DO WHILE (ND > 0)
          I  = NB
          DO
            J  = I
            NY = IA(I + ND)
            NZ = IB(I + ND)
            DO WHILE (NY < IA(J))
              IA(J + ND) = IA(J)
              IB(J + ND) = IB(J)
              J          = J - ND
              IF (J < NB) EXIT
            END DO
            IA(J + ND) = NY
            IB(J + ND) = NZ
            I          = I + 1
            IF (I + ND > NE) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN033
 
      SUBROUTINE GEN034 (RA, NB, NE)
C * SORT REAL ARRAY RA ELEMENTS FROM NB TO NE (LARGE TO RMALL)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NB
      INTEGER :: ND
      INTEGER :: NE
      REAL :: Y
      REAL, DIMENSION(*) :: RA
      N = NE - NB + 1
      IF (N > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (N)) / ALOG (2.0)) + 1.0E-5)) - 1
        DO WHILE (ND > 0)
          I = NB
          DO
            J = I
            Y = RA(I + ND)
            DO WHILE (Y > RA(J))
              RA(J + ND) = RA(J)
              J          = J - ND
              IF (J < NB) EXIT
            END DO
            RA(J + ND) = Y
            I          = I + 1
            IF (I + ND > NE) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN034
 
      SUBROUTINE GEN035 (RA, NB, NE)
C * SORT REAL ARRAY RA ELEMENTS FROM NB TO NE (SMALL TO LARGE)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: ND
      REAL :: Y
      REAL, DIMENSION(*) :: RA
      N = NE - NB + 1
      IF (N > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (N)) / ALOG (2.0)) + 1.0E-5)) - 1
        DO WHILE (ND > 0)
          I = NB
          DO
            J = I
            Y = RA(I + ND)
            DO WHILE (Y < RA(J))
              RA(J + ND) = RA(J)
              J          = J - ND
              IF (J < NB) EXIT
            END DO
            RA(J + ND) = Y
            I          = I + 1
            IF (I + ND > NE) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN035
 
      SUBROUTINE GEN036 (RA, IA, NB, NE)
C * SORT (REAL, INT)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: ND
      INTEGER :: NZ
      INTEGER, DIMENSION(*) :: IA
      REAL :: NY
      REAL, DIMENSION(*) :: RA
      N = NE - NB + 1
      IF (N > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (N)) / ALOG (2.0)) + 1.0e-5)) - 1
        DO WHILE (ND > 0)
          I = NB
          DO
            J  = I
            NY = RA(I + ND)
            NZ = IA(I + ND)
            DO WHILE (NY < RA(J))
              RA(J + ND) = RA(J)
              IA(J + ND) = IA(J)
              J          = J - ND
              IF (J < NB) EXIT
            END DO
            RA(J + ND) = NY
            IA(J + ND) = NZ
            I            = I + 1
            IF (I + ND > N) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN036
 
      SUBROUTINE GEN037 (IA, JL, JU)
C * SHEL-SORT ROUTINE: ON FIRST ELEMENT FROM JL TO JU (SMALL TO LARGE)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: JL
      INTEGER :: JU
      INTEGER :: JV
      INTEGER :: ND
      INTEGER :: NX
      INTEGER :: NY
      INTEGER, DIMENSION(2, *) :: IA
      JV = JU - JL + 1
      IF (JV > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (JV)) / ALOG (2.0)) + 1.0E-5)) - 1
        DO
          IF (ND <= 0) EXIT
          I  = JL
          DO
            J  = I
            NX = IA(1, I + ND)
            NY = IA(2, I + ND)
   10       IF (NX < IA(1, J)) THEN
              IA(1, J + ND) = IA(1, J)
              IA(2, J + ND) = IA(2, J)
              J             = J - ND
              IF (J >= JL) GO TO 10
            END IF
            IA(1, J + ND) = NX
            IA(2, J + ND) = NY
            I             = I + 1
            IF (I + ND > JU) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN037
 
      SUBROUTINE GEN038 (LINE, LO, LU)
C * BLANK LINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: LO
      INTEGER :: LU
      CHARACTER(len=*) :: LINE
      IF (LO > 0 .AND. LU >= LO) THEN
        DO I = LO, LU
          LINE(I:I) = ' '
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN038
 
      SUBROUTINE GEN039 (MODE, LINE, LB, LE, NB, NE)
C * STRIP HEADER/TRAILER BLANKS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: N
      INTEGER :: LB
      INTEGER :: LE
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: MODE
      CHARACTER(len=*) :: LINE
C * MODE = -1 STRIP HEADER BLANKS,
C * MODE =  1 STRIP TRAILING BLANKS
C * MODE =  0 STRIP HEADER & TRAILING BLANKS
      NB = LB
      NE = LE
      IF (MODE >= 0) THEN
        N = LE - LB + 1
        K = LE + 1
        DO I = 1, N
          K = K - 1
          IF (K > 0) THEN
            IF (LINE(K:K) /= ' ') EXIT
          ELSE
            EXIT
          END IF
        END DO
        NE = K
      END IF
      IF (MODE <= 0) THEN
        N = NE - LB + 1
        K = LB - 1
        DO I = 1, N
          K = K + 1
          IF (LINE(K:K) /= ' ') GO TO 10
        END DO
        K  = K + 1
   10   NB = K
      END IF
      RETURN
      END SUBROUTINE GEN039
 
      SUBROUTINE GEN040 (NR, NQ, IP)
C * CONVERT NUMBER TO STRING
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: IP
      INTEGER :: NR
      INTEGER :: NR1
      INTEGER :: ISN
      INTEGER :: ISCR
      CHARACTER(*) :: NQ
      NQ  = '-       '
      NR1 = IABS (NR)
      ISN = 6
      IF (NR < 0) ISN = 5
      N = 1
      DO I = 1, ISN
        N = N * 10
        IF (N > NR1) GO TO 10
      END DO
      I = ISN
   10 IP = I - ISN + 6
      DO J = 1, I
        ISCR = MOD (NR1, 10)
        NQ(IP + 1 - J:IP + 1 - J) = CHAR (ICHAR ('0') + ISCR)
        NR1 = NR1 / 10
      END DO
      RETURN
      END SUBROUTINE GEN040
 
      SUBROUTINE GEN041 (X, SX, ISX, NDCD, NDEC, IRND)
C * ROUND ROUTINE
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: ISX
      INTEGER :: IXX
      INTEGER :: NDCD
      INTEGER :: NDEC
      INTEGER :: IRND
      INTEGER :: NEXIT
      REAL :: X
      REAL :: SX
      REAL :: SXX
      REAL :: XM
C * FORMAL PARAMETERS
C * X    = VARIABLE                       (INPUT/OUTPUT)
C * SX   = ESD                            (INPUT/OUTPUT)
C * ISX  = MULTIPLIED ESD                 (OUTPUT)
C * NDCD = DEFAULT NUMBER OF DECIMALS     (INPUT)
C * NDEC = NUMBER OF RELEVANT DECIMALS    (OUTPUT)
C * IRND = (NO)ROUND PARAMETER            (INPUT)
C * IRND = 0 : NO ROUND
C * IRND = 1 : ROUND (1:9)
C * IRND = 2 : ROUND (1:19)
C *        etc
      NDEC  = IABS (NDCD)
      NEXIT = 0
      N     = 0
      IF (SX > 0.0) THEN
        IF (IRND /= 0) THEN
          SXX = SX
          XM  = 1.0
          DO
            IF (N < IABS (NDCD)) THEN
              ISX = INT (SXX * XM + 0.051)
              IF (ISX < IRND) THEN
                XM = XM * 10
                N  = N + 1
                CYCLE
              END IF
            END IF
            IF (NEXIT == 0) EXIT
          END DO
          IXX  = NINT (X * XM + SIGN (0.051, X))
          ISX  = MAX (1, NINT (SXX * XM))
          X    = IXX / XM
          SX   = ISX / XM
          NDEC = N
        ELSE
          ISX = NINT (SX * 10**NDEC)
        END IF
      ELSE
        ISX = 0
        IF (NDCD < 0) THEN
          DO
            IF (ABS (FLOAT (INT (X * 10**N + 0.01)) - X * 10**N)
     1        > 0.1E-6 .AND. N < IABS (NDCD)) THEN
              N = N + 1
              CYCLE
            END IF
            IF (NEXIT == 0) EXIT
          END DO
          NDEC = N
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN041
 
      SUBROUTINE GEN042 (NWRD, A, NUM)
C * GET NUMERICAL VALUE(S) FROM CHARACTER STRING
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IP
      INTEGER :: NP
      INTEGER :: MB = 0
      INTEGER :: ME = 0
      INTEGER :: KE
      INTEGER :: IA2
      INTEGER :: NUM
      INTEGER :: IER
      INTEGER :: IFIN
      INTEGER :: IFRC
      INTEGER :: NLET = 0
      INTEGER :: JPAR = 0
      INTEGER :: NEXP
      REAL :: S
      REAL, DIMENSION(2) :: A
      CHARACTER(len=*) :: NWRD
      CHARACTER(len=1) :: ICH
      CHARACTER(len=1) :: JCH
      CHARACTER(len=1) :: KCH
C * NUM =  1 - Number
C * NUM =  0 - Non-Number
C * NUM = -1 - Default  (? or .)
C * NUM = -2 - Error (overflow)
C * NUM = -3 - Error (Improper Number)
      A(1) = 0.0
      A(2) = 0.0
      IP   = 0
      NP   = 0
      NUM  = 0
      K    = 1
      IFIN = 0
      IFRC = 0
      S    = 1.0
      M    = 0
      IA2  = 0
      NUM  = 0
C * GET NUMBER OF CHARACTERS IN STRING NWRD
      N    = INDEX (NWRD, '''')
      DO I = 2, N - 1
        ICH = NWRD(I:I)
C * CHECK FOR UC ALPHA-CHARACTER
        CALL GEN105 (1, ICH, L)
        IF (L > 0) THEN
C * CHECK FOR FLOATING NUMBER WITH SCIENTIFIC NOTATION
          IF (ICH == 'E') THEN
C * CHECK FOR SINGLE 'E' STRING
            IF (N < 4) THEN
              NUM = 0
              RETURN
            END IF
            NLET = 0
            JPAR = 0
            MB   = 0
            ME   = 0
            DO J = 2, N - 1
              JCH = NWRD(J:J)
C * CHECK FOR 0,1,...,9
              CALL GEN105 (3, JCH, K)
              IF (K < 0) THEN
C * CHECK FOR A,B,...,Z
                CALL GEN105 (1, JCH, K)
                IF (K > 0) THEN
                  NLET = NLET + 1
                  IF (NLET > 1) THEN
                    RETURN
                  ELSE
                    CYCLE
                  END IF
                ELSE IF (JCH == '.') THEN
                  IF (J .EQ. 2) THEN
C * SAVE DECIMAL POINT LOCATION
                    M = J
                    CYCLE
                  ELSE
                    KCH = NWRD(J-1:J-1)
                    IF (KCH == '+' .OR. KCH == '-') THEN
C * GET DECIMAL POINT LOCATION
                      M = J
                      CYCLE
                    END IF
                    CALL GEN105(3, KCH, K)
                    IF (K > 0) THEN
C * GET DECIMAL POINT LOCATION
                      M = J
                      CYCLE
                    ELSE
                      RETURN
                    END IF
                  END IF
                ELSE IF (JCH == '(') THEN
                  IF (J == 2) THEN
                    RETURN
                  ELSE
                    JPAR = 1
C * SAVE BEGIN SU STRING
                    MB   = J
                    CYCLE
                  END IF
                ELSE IF (JCH == ')') THEN
                  IF (JPAR > 0) THEN
C * SAVE END   SU STRING
                    ME = J
                    CYCLE
                  ELSE
                    RETURN
                  END IF
                ELSE IF (JCH == '+') THEN
                  IF (J /= 2) THEN
                    IF (NWRD(J-1:J) /= 'E+') THEN
                      RETURN
                    ELSE
                      CYCLE
                    END IF
                  END IF
                ELSE IF (JCH == '-') THEN
                  IF (J /= 2) THEN
                    IF (NWRD(J-1:J) /= 'E-') THEN
                      RETURN
                    ELSE
                      CYCLE
                    END IF
                  END IF
                ELSE
                  RETURN
                END IF
              END IF
            END DO
C * CHECK FOR SU ()
            K  = 0
C * CHECK BEGIN SU STRING
            IF (MB > 0) THEN
C * CHECK END   SU STRING
              IF (ME > 0) THEN
                IF (ME - MB > 1) THEN
                  READ (NWRD(MB+1:ME-1), *, IOSTAT = IER) IA2
                  IF (IER == 0) THEN
                    K = MB
                    IF (ME < I) THEN
                      DO J = I, N -1
                        NWRD(K:K) = NWRD(J:J)
                        K = K + 1
                      END DO
                      READ (NWRD(MB+1:K-1), *, IOSTAT = IER) NEXP
                      KE = MB - M - 1
                    ELSE
                      READ (NWRD(I+1:MB-1), *, IOSTAT = IER) NEXP
                      KE = I  - M - 1
                    END IF
                    J = N + MB - ME - 2
                    READ (NWRD(1:J), *, IOSTAT = IER) A(1)
                  ELSE
                    NUM = 0
                    RETURN
                  END IF
                END IF
              ELSE
                NUM = 0
                RETURN
              END IF
              A(2) = FLOAT (IA2) * 10.0**(NEXP-KE)
C * NO SU CASE
            ELSE
              READ (NWRD(1:N-1), *, IOSTAT = IER) A(1)
              A(2) = 0.0
            END IF
            IF (IER == 0) THEN
              NUM = 1
              RETURN
            END IF
C * CHARACTER STRING
          ELSE
            NUM = 0
            RETURN
          END IF
        END IF
      END DO
C * NON-SCIENTIFIC NUMBER FORMAT
      DO I = 2, N
        ICH = NWRD(I:I)
        IF (ICH == '''') THEN
          IFIN = 1
        ELSE IF (ICH == '+') THEN
          IF (I == 2) THEN
            S   = 1.0
            NUM = 1
            CYCLE
          ELSE
            NUM  = -3
            RETURN
          END IF
        ELSE IF (ICH == '-') THEN
          IF (I == 2) THEN
            S   = -1.0
            NUM = 1
            CYCLE
          ELSE
            NUM = -3
            RETURN
          END IF
        ELSE IF (ICH == '_') THEN
          IF (NUM == 1) IP = 1
          CYCLE
        ELSE IF (ICH == '.') THEN
          IP  = 1
          IF (NUM == 0) NUM = -1
          CYCLE
        ELSE IF (I == 2 .AND. ICH == '?') THEN
          NUM = -1
          RETURN
        ELSE IF (ICH == '(') THEN
        ELSE IF (ICH == '/') THEN
          IFRC = 1
        ELSE IF (ICH == ')') THEN
          IFIN = 1
        ELSE
          CALL GEN105 (3, ICH, M)
          IF (M >= 0) THEN
            NUM  = 1
            NP   = NP + IP
            IF (K > 0) THEN
              IF (A(K) >= 1.0E37) THEN
                A(1) = 0.0
                A(2) = 0.0
                NUM  = -2
                RETURN
              END IF
            ELSE IF (K == 0) THEN
              A(1) = 0.0
              A(2) = 0.0
              RETURN
            END IF
            A(K) = 10.0 * A(K) + M - 1
          END IF
          CYCLE
        END IF
        A(K) = S * A(K) / 10.0**NP
        IF (IFIN == 1) EXIT
        IP = 0
        S  = 1.0
        K  = 2
      END DO
C * HANDLE FRACTION N/M CASE
      IF (NUM * IFRC /= 0) THEN
        IF (A(1) /= 0.0 .AND. A(2) /=  0.0) THEN
          A(1) = A(1) / A(2)
          A(2) = 0.0
        ELSE
          NUM = 0
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN042
 
      SUBROUTINE GEN043 (MODE, A, ANG)
C * CONVERT X,Y,Z ANGLES TO MATRIX
      IMPLICIT NONE
      INTEGER :: MODE
      REAL :: CA
      REAL :: SA
      REAL :: ANG
      REAL, DIMENSION(3, 3) :: A
      CA = COS (ANG)
      SA = SIN (ANG)
      CALL GEN074 (A, 1, 9, 0.0)
      IF (MODE == 3) THEN
C * Z ROTN
        A(1, 1) =  CA
        A(1, 2) =  SA
        A(2, 1) = -SA
        A(2, 2) =  CA
        A(3, 3) = 1.0
      ELSE IF (MODE == 2) THEN
C * Y ROTN
        A(1, 1) = CA
        A(1, 3) = -SA
        A(2, 2) = 1.0
        A(3, 1) = SA
        A(3, 3) = CA
C * X ROTN
      ELSE IF (MODE == 1) THEN
        A(1, 1) = 1.0
        A(2, 2) = CA
        A(2, 3) = SA
        A(3, 2) = -SA
        A(3, 3) = CA
      END IF
      RETURN
      END SUBROUTINE GEN043
 
      SUBROUTINE GEN044 (P, R, MODE)
C * GET ORTHOGONALISATION MATRIX R FROM CELL PARAMETERS IN P
      IMPLICIT NONE
      INTEGER :: MODE
      REAL :: RAD
      REAL :: CP4RAD
      REAL :: CP5RAD
      REAL :: CP6RAD
      REAL :: SP4RAD
      REAL :: SP6RAD
      REAL :: UNITVOL
      REAL, DIMENSION(6)    :: P
      REAL, DIMENSION(3, 3) :: R
      IF (MODE > 0) THEN
        RAD     = ATAN2 (1.0, 1.0) / 45.0
        CP4RAD  = COS (P(4) * RAD)
        CP5RAD  = COS (P(5) * RAD)
        CP6RAD  = COS (P(6) * RAD)
      ELSE
        CP4RAD = P(4)
        CP5RAD = P(5)
        CP6RAD = P(6)
      END IF
      SP4RAD  = SQRT (1.0 - CP4RAD**2)
      SP6RAD  = SQRT (1.0 - CP6RAD**2)
      UNITVOL = SQRT (1.0 - CP4RAD**2 - CP5RAD**2 - CP6RAD**2
     1        + 2.0  * CP4RAD * CP5RAD * CP6RAD)
C * x||a, z ||c*, z||y ^ x  (SEE DUNITZ p237)
      IF (IABS (MODE) == 1) THEN
        R(1, 1) = P(1)
        R(1, 2) = P(2) * CP6RAD
        R(1, 3) = P(3) * CP5RAD
        R(2, 1) = 0.0
        R(2, 2) = P(2) * SP6RAD
        R(2, 3) = P(3) * (CP4RAD - CP5RAD * CP6RAD) / SP6RAD
        R(3, 1) = 0.0
        R(3, 2) = 0.0
        R(3, 3) = P(3) * UNITVOL / SP6RAD
C * z||c, x||a*, y||z ^ x  (Hazen & Finger, Comparative Crystal Chemistry)
      ELSE IF (IABS (MODE) == 2) THEN
        R(1, 1) = P(1) * UNITVOL / SP4RAD
        R(1, 2) = 0.0
        R(1, 3) = 0.0
        R(2, 1) = P(1) * (CP6RAD - CP4RAD * CP5RAD) / SP4RAD
        R(2, 2) = P(2) * SP4RAD
        R(2, 3) = 0.0
        R(3, 1) = P(1) * CP5RAD
        R(3, 2) = P(2) * CP4RAD
        R(3, 3) = P(3)
      END IF
      RETURN
      END SUBROUTINE GEN044
 
      REAL FUNCTION GEN045 (C)
C * CALCULATE CELL-VOLUME FROM CELL-PARAMETERS
C * A, B, C, ALF, BET, GAM IN [C(1)--C(6)]
      IMPLICIT NONE
      REAL :: CA
      REAL :: CB
      REAL :: CG
      REAL :: DTR
      REAL :: VOL
      REAL, DIMENSION(6) :: C
      DTR = ATAN (1.0) / 45.0
      CA  = COS (C(4) * DTR)
      CB  = COS (C(5) * DTR)
      CG  = COS (C(6) * DTR)
      VOL = (1.0 - CA**2 - CB**2 - CG**2 + 2 * CA * CB * CG)
      IF (VOL < 0.0) STOP 'CELL VOLUME COMPLEX!!'
      GEN045 = C(1) * C(2) * C(3) * SQRT (VOL)
      RETURN
      END FUNCTION GEN045
 
      SUBROUTINE GEN046 (HKLP, X, Y, Z)
C * HKLP  =  (L x 200  +  K) * 200  +  H
      IMPLICIT NONE
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: HKLP
      Z = NINT (HKLP / 40000.0)
      X = (NINT (HKLP) - 40000.0 * Z) / 200.0
      Y = NINT (X)
      X = AINT (201.0 * (X - Y))
      RETURN
      END SUBROUTINE GEN046
 
      SUBROUTINE GEN047 (LINE, N, M)
C * ELIMINATE BLANKS BETWEEN NON-SPACE CHARACTERS FROM STRING LINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: M
      CHARACTER(len=*) :: LINE
      J = N
      DO I = N, M
        IF (LINE(I:I) /= ' ') THEN
          LINE(J:J) = LINE(I:I)
          J         = J + 1
        END IF
      END DO
      CALL GEN038 (LINE, J, M)
      RETURN
      END SUBROUTINE GEN047
 
      SUBROUTINE GEN048 (IKEY, IFLI, IBIT, IVAL)
C * 'BIT' -MANIPULATION ROUTINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: KEY
      INTEGER :: INH
      INTEGER :: IFLI
      INTEGER :: IVAL
      INTEGER :: IBIT
      INTEGER :: IKEY
      INTEGER :: JKEY
      INTEGER :: JBIT
      INTEGER, DIMENSION(32), SAVE :: IBT
      JKEY = IABS (IKEY)
      IF (JKEY == 1) THEN
        KEY = 2
      ELSE IF (JKEY == 10) THEN
        KEY = 1024
      ELSE IF (JKEY /= 0) THEN
        KEY = 2**JKEY
      ELSE
        DO I = 1, 31
          IBT(I) = 2**(I - 1)
        END DO
        RETURN
      END IF
      JBIT = IBT(IBIT)
      INH  = MOD (IFLI / JBIT, KEY)
      IF (IKEY < 0) THEN
        IVAL  = INH
      ELSE
        IFLI = IFLI + (IVAL - INH) * JBIT
      END IF
      RETURN
      END SUBROUTINE GEN048
 
      REAL FUNCTION GEN049 (LATC, JH, JK, JL)
C * CHECK FOR LATTICE ABSENCE
      IMPLICIT NONE
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      REAL :: S
      CHARACTER(len=1) :: LATC
      S = 1.0
      IF (LATC /= 'P') THEN
        IF (LATC == 'A') THEN
          IF (MOD (JK + JL, 2) /= 0) S = - 1.0
        ELSE IF (LATC == 'B') THEN
          IF (MOD (JH + JL, 2) /= 0) S = - 1.0
        ELSE IF (LATC == 'C') THEN
          IF (MOD (JH + JK, 2) /= 0) S = - 1.0
        ELSE IF (LATC == 'F') THEN
          IF (MOD (JH + JK, 2) /= 0 .OR. MOD (JH + JL, 2) .NE. 0)
     1        S = - 1.0
        ELSE IF (LATC == 'I') THEN
          IF (MOD (JH + JK + JL, 2) /= 0) S = - 1.0
        ELSE IF (LATC == 'R') THEN
          IF (MOD (-JH + JK + JL, 3) /= 0) S = -1.0
        END IF
      END IF
      GEN049 = S
      RETURN
      END FUNCTION GEN049
 
      REAL FUNCTION GEN050 (TM, IH, IK, IL, JH, JK, JL)
C * TRANSFORM & ELIMINATE REFLECTIONS WITH NON-INTEGER INDICES
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      REAL :: XH
      REAL :: XK
      REAL :: XL
      REAL, DIMENSION(3, 3) :: TM
      XH = TM(1, 1) * IH + TM(1, 2) * IK + TM(1, 3) * IL
      XK = TM(2, 1) * IH + TM(2, 2) * IK + TM(2, 3) * IL
      XL = TM(3, 1) * IH + TM(3, 2) * IK + TM(3, 3) * IL
      JH = NINT (XH)
      JK = NINT (XK)
      JL = NINT (XL)
      GEN050 = -1.0
      IF (ABS (XH - JH) < 0.01) THEN
        IF (ABS (XK - JK) < 0.01) THEN
          IF (ABS (XL - JL) < 0.01) THEN
            GEN050 = 1.0
          END IF
        END IF
      END IF
      RETURN
      END FUNCTION GEN050
 
      SUBROUTINE GEN051 (MODE, RV, X, L)
C * CONSTRUCT RMAT FROM ROTX, ROTY, ROTZ
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: MODE
      REAL :: X
      REAL, DIMENSION(3, 3) :: RM
      REAL, DIMENSION(3, 3) :: TM
      REAL, DIMENSION(3, 3) :: RV
C * MODE = 0 :GENERATE RMAT FROM ROTX, ROTY, ROTZ
C * MODE = 1  PREMULTIPLY WITH RM
      K        = MOD (L + 2, 3) + 1
      I        = MOD (K, 3) + 1
      J        = MOD (I, 3) + 1
      RM(I, I) = COS (X)
      RM(I, J) = SIN (X)
      RM(I, K) = 0.0
      RM(J, I) = -SIN (X)
      RM(J, J) = COS (X)
      RM(J, K) = 0.0
      RM(K, I) = 0.0
      RM(K, J) = 0.0
      RM(K, K) = 1.0
      IF (MODE == 0) THEN
        CALL GEN004 (RV, RM, TM)
      ELSE IF (MODE == 1) THEN
        CALL GEN004 (RM, RV, TM)
      END IF
C * COPY
      CALL GEN052 (TM, RV)
      RETURN
      END SUBROUTINE GEN051
 
      SUBROUTINE GEN052 (A, B)
C * COPY 3x3 MATRIX
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(3, 3) :: B
      DO I = 1, 3
        DO J = 1, 3
          B(I, J) = A(I, J)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN052
 
      SUBROUTINE GEN053 (N, DATAX, INDY)
C * HEAP SORT
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: INEXT
      INTEGER, DIMENSION(N) :: INDY
      REAL :: T
      REAL, DIMENSION(N) :: DATAX
C * INDEXES THE ARRAY DATA(N) AND RETURNS THE ARRAY INDY(N) SORTED SUCH
C * THAT THE VALUES DATA(INDY(I)) ARE IN ASCENDING ORDER FOR I = 1, 2,
C * ..., N.  THE INPUT VARIABLES N AND DATA(N) ARE NOT CHANGED.
C * EMPLOYS THE "HEAPSORT" ALGORITHM.
      DO I = 1, N
        INDY(I) = I
      END DO
      IF (N > 1) THEN
        I = N / 2 + 1
        J = N
        DO
          IF (I > 1) THEN
            I     = I - 1
            INEXT = INDY(I)
            T     = DATAX(INEXT)
          ELSE
            INEXT   = INDY(J)
            T       = DATAX(INEXT)
            INDY(J) = INDY(1)
            J       = J - 1
            IF (J == 1) THEN
              INDY(1) = INEXT
              RETURN
            END IF
          END IF
          K = I
          L = 2 * I
   10     IF (L <= J) THEN
            IF (L < J) THEN
              IF (DATAX(INDY(L)) < DATAX(INDY(L + 1))) L = L + 1
            END IF
            IF (T < DATAX(INDY(L))) THEN
              INDY(K) = INDY(L)
              K = L
              L = 2 * L
            ELSE
              L = J + 1
            END IF
            GO TO 10
          END IF
          INDY(K) = INEXT
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN053
 
      SUBROUTINE GEN054 (N, M, A, U, V)
C * JOCOBI - DOUBLE PRECISION
C * EIGENVALUES AND EIGENVECTORS OF A REAL SYMMETRIC MATRIX A OF LOGICAL
C * SIZE A(N,N) STORED IN AN ARRAY OF PHYSICAL SIZE A(M,M), WHERE M >= N.
C * ON OUTPUT:
C * (1) ELEMENTS OF A ABOVE THE DIAGONAL ARE DESTROYED.
C * (2) THE ARRAY U(M) RETURNS THE EIGENVALUES OF A(N,N) IN ITS FIRST N
C *     ELEMENTS.
C * (3) THE COLUMNS OF THE MATRIX V(N,N), STORED IN THE ARRAY V(M,M),
C *    CONTAIN THE EIGENVECTORS OF A.
      IMPLICIT NONE
      INTEGER, PARAMETER :: NMAX = 999
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: M
      INTEGER :: NCYCLE
      DOUBLE PRECISION :: T
      DOUBLE PRECISION :: E
      DOUBLE PRECISION :: C
      DOUBLE PRECISION :: S
      DOUBLE PRECISION :: P
      DOUBLE PRECISION :: Q
      DOUBLE PRECISION :: AII
      DOUBLE PRECISION :: AJJ
      DOUBLE PRECISION :: TAU
      DOUBLE PRECISION :: THETA
      DOUBLE PRECISION :: THRESH
      DOUBLE PRECISION, DIMENSION(M, M) :: A
      DOUBLE PRECISION, DIMENSION(M, M) :: V
      DOUBLE PRECISION, DIMENSION(M)    :: U
      DOUBLE PRECISION, DIMENSION(NMAX) :: B
      DOUBLE PRECISION, DIMENSION(NMAX) :: Z
C * INITIALIZE EIGENVECTORS MATRIX TO AN IDENTITY MATRIX.
      DO I = 1, N
        DO J = 1, N
          V(I, J) = 0
        END DO
        V(I, I) = 1
      END DO
C * INITIALIZE EIGENVALUES U AND WORK VECTOR B TO A(I,I) AND ZERO WORK
C * VECTOR Z.
      DO I = 1, N
        T    = A(I, I)
        U(I) = T
        B(I) = T
        Z(I) = 0
      END DO
C * PERFORM UP TO 50 ITERATIONS OF UP TO N*(N - 1)/2 JACOBI ROTATIONS.
      DO NCYCLE = 1, 50
C * TEST FOR NORMAL RETURN WHEN MAXIMUM MAGNITUDE OF AN OFF-DIAGONAL
C * ELEMENT EQUALS ZERO TO MACHINE PRECISION.  THE TEST PRESUMES THAT
C * ARITHMETIC UNDERFLOW VALUES ARE SET TO ZERO.
        T = 0
        DO I = 1, N - 1
          DO J = I + 1, N
            T = T + ABS (A(I, J))
          END DO
        END DO
        IF (T == 0.0) RETURN
C * SET OFF-DIAGONAL THRESHOLD.
        IF (NCYCLE < 4) THEN
          THRESH = T / (5 * N**2)
        ELSE
          THRESH = 0
        END IF
C * ROTATE TO ANNIHILATE OFF-DIAGONAL ELEMENTS.
        DO I = 1, N - 1
          DO J = I + 1, N
            T   = ABS (A(I, J))
            E   = 100 * T
            AII = ABS (U(I))
            AJJ = ABS (U(J))
            IF (NCYCLE > 4 .AND. AII + E == AII .AND.
     1                              AJJ + E == AJJ) THEN
C * AFTER FOUR CYCLES, SKIP THE ROTATION IF ABS(A(I,J)) IS SMALL COMPARED
C * TO BOTH ABS(A(I,I)) AND ABS(A(J,J)).
              A(I, J) = 0
            ELSE IF (T > THRESH) THEN
              T = ABS (AJJ - AII)
              IF (T + E == T) THEN
C * EFFECTIVELY, SET T = 1/(2*THETA)
                T = A(I, J) / (AJJ - AII)
              ELSE
                THETA = (AJJ - AII) / (2 * A(I, J))
                T     = 1 / (ABS (THETA) + SQRT (1 + THETA**2))
                IF (THETA < 0) T = -T
              END IF
              C   = 1 / SQRT (1 + T**2)
              S   = T * C
              TAU = S / (1 + C)
C * ADJUST EIGENVALUES U AND WORK VECTOR Z.
              E       = T * A(I, J)
              Z(I)    = Z(I) - E
              Z(J)    = Z(J) + E
              U(I)    = U(I) - E
              U(J)    = U(J) + E
              A(I, J) = 0
C * ROTATIONS  1 <= K < I.
              DO K = 1, I - 1
                P       = A(K, I)
                Q       = A(K, J)
                A(K, I) = P - S * (Q + P * TAU)
                A(K, J) = Q + S * (P - Q * TAU)
              END DO
C * ROTATIONS  I < K < J.
              DO K = I + 1, J - 1
                P       = A(I, K)
                Q       = A(K, J)
                A(I, K) = P - S * (Q + P * TAU)
                A(K, J) = Q + S * (P - Q * TAU)
              END DO
C * ROTATIONS  J < K <= N.
              DO K = J + 1, N
                P       = A(I, K)
                Q       = A(J, K)
                A(I, K) = P - S * (Q + P * TAU)
                A(J, K) = Q + S * (P - Q * TAU)
              END DO
C * COMPUTE AND STORE EIGENVECTORS.
              DO K = 1, N
                P       = V(K, I)
                Q       = V(K, J)
                V(K, I) = P - S * (Q + P * TAU)
                V(K, J) = Q + S * (P - Q * TAU)
              END DO
            END IF
          END DO
        END DO
C * ADJUST EIGENVALUES AND WORK VECTORS.
        DO I = 1, N
          B(I) = B(I) + Z(I)
          U(I) = B(I)
          Z(I) = 0
        END DO
      END DO
      STOP '50 CYCLES OF JACOBI ROTATIONS SHOULD NEVER BE NECESSARY.'
      END SUBROUTINE GEN054
 
      SUBROUTINE GEN055 (YLM, XYZ, L0MAX, L1MAX)
C * YLM : UN-NORMALIZED REAL SPHERICAL HARMONIC FUNCTIONS
C *  A. PATURLE AND P. COPPENS (1988).  ACTA CRYST. A44, 6-7.
C *  SCALE AND NORMALIZATION FACTORS FOR REAL SPHERICAL HARMONIC FUNCTIONS
C *  C(L,ABS(M)), N(L,ABS(M)); L=0,1,2,...,LMAX; ABS(M)=0,1,2,...,L.
C *  THE C(L,ABS(M)) SCALE THE CARTESIAN YLM(X,Y,Z) TO GIVE THE ASSOCIATED
C *  LEGENDRE FUNCTIONS P(L,M)(COS(THETA))*COS,SIN(M*PHI).
C *  THE N(L,ABS(M)) NORMALIZE TO 2 - DELTA(0,L).
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IP
      INTEGER :: LMAX
      INTEGER :: L0MAX
      INTEGER :: L1MAX
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: F
      REAL :: Q
      REAL :: XK
      REAL :: YK
      REAL :: ZK
      REAL :: XQ
      REAL :: YQ
      REAL :: ZQ
      REAL :: XV
      REAL :: YV
      REAL :: ZV
      REAL :: XP
      REAL :: YP
      REAL :: ZP
      REAL :: XS
      REAL :: YS
      REAL :: ZS
      REAL, DIMENSION(3)    :: XYZ
      REAL, DIMENSION(80)   :: YLM
      REAL, DIMENSION(0:44) :: FCLM = (/
     1 1.0, 1.0, 1.0, 0.5, 3.0, 3.0, 0.5, 1.5, 15.0, 15.0, 0.125, 2.5,
     2 7.5, 105.0, 105.0, 0.125, 1.875, 52.5, 52.5, 945.0, 945.0,
     3 0.0625, 2.625, 13.125, 157.5, 472.5, 10395.0, 10395.0, 0.0625,
     4 0.4375, 7.875, 39.375, 1732.5, 5197.5, 135135.0, 135135.0,
     5 0.0078125, 0.5625, 19.6875, 433.125, 1299.375, 67567.5, 67567.5,
     6 2027025.0, 2027025.0/)
      REAL, DIMENSION(0:44) :: FNLM = (/
     1 0.0795774, 0.3183099, 0.3183099, 0.2067483, 0.7500000, 0.3750000,
     2 0.2448538, 0.3203331, 1.0000000, 0.4244132, 0.0694175, 0.4740025,
     3 0.3305913, 1.2500000, 0.4687500, 0.0767395, 0.3229812, 1.6875000,
     4 0.3451455, 1.5000000, 0.5092958, 0.0417084, 0.4172129, 0.3261107,
     5 0.6513219, 0.3610405, 1.7500000, 0.5468750, 0.0447979, 0.0648780,
     6 0.1573192, 0.1109240, 0.7404370, 0.3772319, 2.0000000, 0.5820523,
     7 0.0059609, 0.0784858, 0.3253786, 0.8780415, 0.3411683, 2.4892756,
     8 0.3933012, 2.2500000, 0.6152344/)
      CALL GEN074 (YLM, 1, 80, 0.0)
C * MONOPOLE:  L = M = 0.
      IF (L0MAX == 0 .AND. L1MAX == 0) RETURN
      X  = XYZ(1)
      Y  = XYZ(2)
      Z  = XYZ(3)
      XK = X ** 2
      YK = Y ** 2
      ZK = Z ** 2
      XQ = X ** 3
      YQ = Y ** 3
      ZQ = Z ** 3
      XV = X ** 4
      YV = Y ** 4
      ZV = Z ** 4
      XP = X ** 5
      YP = Y ** 5
      ZP = Z ** 5
      XS = X ** 6
      YS = Y ** 6
      ZS = Z ** 6
 
C * DIPOLES:  L = 1; M = 0, +1, -1.
      IF (L1MAX >= 1) THEN
        YLM(1) = Z
        YLM(2) = X
        YLM(3) = Y
      END IF
C * QUADRUPOLES:  L = 2; M = 0, +1, -1, +2, -2.
      IF (L0MAX >= 2) THEN
        YLM(4) = 3 * ZK - 1
        YLM(5) = Z * X
        YLM(6) = Z * Y
        YLM(7) = XK - YK
        YLM(8) = 2 * X * Y
      END IF
C * OCTUPOLES:  L = 3; M = 0, +1, -1, +2, -2, +3, -3.
      IF (L1MAX >= 3) THEN
        YLM(9)  = 5 * ZQ - 3 * Z
        Q       = 5 * ZK - 1
        YLM(10) = Q * X
        YLM(11) = Q * Y
        YLM(12) = Z * (XK - YK)
        YLM(13) = 2 * X * Y * Z
        YLM(14) = XQ - 3 * X * YK
        YLM(15) = 3 * XK * Y - YQ
      END IF
C * HEXADECAPOLES:  L = 4; M = 0, +1, -1, +2, -2, +3, -3, +4, -4.
      IF (L0MAX >= 4) THEN
        YLM(16) = 35 * ZV - 30 * ZK + 3
        Q       = 7 * ZQ - 3 * Z
        YLM(17) = Q * X
        YLM(18) = Q * Y
        YLM(19) = (7 * ZK - 1) * (XK - YK)
        YLM(20) = 2 * X * Y * (7 * ZK - 1)
        YLM(21) = Z * (XQ - 3 * X * YK)
        YLM(22) = Z * (3 * XK * Y - YQ)
        YLM(23) = XV - 6 * XK * YK + YV
        YLM(24) = 4 * XQ * Y - 4 * X * YQ
      END IF
C * 2**5 = 32-POLES:  L = 5; M = 0, +1, -1, +2, -2,..., +5, -5.
      IF (L1MAX >= 5) THEN
        YLM(25) = 63 * ZP - 70 * ZQ + 15 * Z
        Q       = 21 * ZV - 14 * ZK + 1
        YLM(26) = Q * X
        YLM(27) = Q * Y
        YLM(28) = (3 * ZQ - Z) * (XK - YK)
        YLM(29) = 2 * X * Y * (3 * ZQ - Z)
        YLM(30) = (9 * ZK - 1) * (XQ - 3 * X * YK)
        YLM(31) = (9 * ZK - 1) * (3 * XK * Y - YQ)
        YLM(32) = Z * (XV - 6 * XK * YK + YV)
        YLM(33) = Z * (4 * XQ * Y - 4 * X * YQ)
        YLM(34) = XP - 10 * XQ * YK + 5 * X * YV
        YLM(35) = 5 * XV * Y - 10 * XK * YQ + YP
      END IF
C * 2**6 = 64-POLES:  L = 6; M = 0, +1, -1, +2, -2,..., +6, -6.
      IF (L0MAX >= 6) THEN
        YLM(36) = 231 * ZS - 315 * ZV + 105 * ZK - 5
        Q       = 33 * ZP - 30 * ZQ + 5 * Z
        YLM(37) = Q * X
        YLM(38) = Q * Y
        YLM(39) = (33 * ZV - 18 * ZK + 1) * (XK - YK)
        YLM(40) = 2 * X * Y * (33 * ZV - 18 * ZK + 1)
        Q       = 11 * ZQ - 3 * Z
        YLM(41) = Q * (XQ - 3 * X * YK)
        YLM(42) = Q * (3 * XK * Y - YQ)
        YLM(43) = (11 * ZK - 1) * (XV - 6 * XK * YK + YV)
        YLM(44) = (11 * ZK - 1) * (4 * XQ * Y - 4 * X * YQ)
        YLM(45) = Z * (XP - 10 * XQ * YK + 5 * X * YV)
        YLM(46) = Z * (5 * XV * Y - 10 * XK * YQ + YP)
        YLM(47) = XS - 15 * XV * YK + 15 * XK * YV - YS
        YLM(48) = 6 * XP * Y - 20 * XQ * YQ + 6 * X * YP
      END IF
C * 2**7 = 128-POLES:  L = 7; M = 0, +1, -1, +2, -2,..., +7, -7.
      IF (L1MAX >= 7) THEN
        YLM(49) = 429 * Z**7 - 639 * ZP + 315 * ZQ - 35 * Z
        Q       = 429 * ZS - 495 * ZV + 135 * ZK - 5
        YLM(50) = Q * X
        YLM(51) = Q * Y
        YLM(52) = (143 * ZP - 110 * ZQ + 15 * Z) * (XK - YK)
        YLM(53) = 2 * X * Y * (143 * ZP - 110 * ZQ + 15 * Z)
        Q       = 143 * ZV - 66 * ZK + 3
        YLM(54) = Q * (XQ - 3 * X * YK)
        YLM(55) = Q * (3 * XK * Y - YQ)
        Q       = 13 * ZQ - 3 * Z
        YLM(56) = Q * (XV - 6 * XK * YK + YV)
        YLM(57) = Q * (4 * XQ * Y - 4 * X * YQ)
        YLM(58) = (13 * ZK - 1) * (XP - 10 * XQ * YK + 5 * X * YV)
        YLM(59) = (13 * ZK - 1) * (5 * XV * Y - 10 * XK * YQ + YP)
        YLM(60) = Z * (XS - 15 * XV * YK + 15 * XK * YV - YS)
        YLM(61) = Z * (6 * XP * Y - 20 * XQ * YQ + 6 * X * YP)
        YLM(62) = X**7 - 21 * XP * YK + 35 * XQ * YV - 7 * X * YS
        YLM(63) = 7 * XS * Y - 35 * XV * YQ + 21 * XK * YP - Y**7
      END IF
C * 2**8 = 256-POLES:  L = 8; M = 0, +1, -1, +2, -2,..., +8, -8.
      IF (L0MAX >= 8) THEN
        YLM(64) = 6435 * Z**8 - 12012 * ZS + 6930 * ZV - 1260 * ZK
     1          + 35
        Q       = 715 * Z**7 - 1001 * ZP + 385 * ZQ - 35 * Z
        YLM(65) = Q * X
        YLM(66) = Q * Y
        Q       = 143 * ZS - 143 * ZV + 33 * ZK - 1
        YLM(67) = Q * (XK - YK)
        YLM(68) = Q * 2 * X * Y
        Q       = 39 * ZP - 26 * ZQ + 3 * Z
        YLM(69) = Q * (XQ - 3 * X * YK)
        YLM(70) = Q * (3 * XK * Y - YQ)
        Q       = 65 * ZV - 26 * ZK + 1
        YLM(71) = Q * (XV - 6 * XK * YK + YV)
        YLM(72) = Q * (4 * XQ * Y - 4 * X * YQ)
        Q       = 5 * ZQ - Z
        YLM(73) = Q * (XP - 10 * XQ * YK + 5 * X * YV)
        YLM(74) = Q * (5 * XV * Y - 10 * XK * YQ + YP)
        Q       = 15 * ZK - 1
        YLM(75) = Q * (XS - 15 * XV * YK + 15 * XK * YV - YS)
        YLM(76) = Q * (6 * XP * Y - 20 * XQ * YQ + 6 * X * YP)
        YLM(77) = Z * (X**7 - 21 * XP * YK + 35 * XQ * YV
     1          - 7 * X * YS)
        YLM(78) = Z * (7 * XS * Y - 35 * XV * YQ + 21 * XK * YP - Y**7)
        YLM(79) = X**8 - 28 * XS * YK + 70 * XV * YV
     1          - 28 * XK * YS + Y**8
        YLM(80) = 8 * X**7 * Y - 56 * XP * YQ + 56 * XQ * YP
     1          - 8 * X * Y**7
      END IF
      I = 0
      J = 0
      LMAX = MAX (L0MAX, L1MAX)
      DO L = 1, LMAX
        DO M = 0, L
          I = I + 1
          F = FCLM(I) * FNLM(I)
          DO IP = 0, MIN (M, 1)
            J = J + 1
            YLM(J) = F * YLM(J)
          END DO
        END DO
      END DO
      I = 0
      N = 0
      DO L = 1, LMAX
        DO M = -L, L
          I = I + 1
          IF ((MOD (L, 2) == 0 .AND. L <= L0MAX) .OR.
     1        (MOD (L, 2) == 1 .AND. L <= L1MAX)) THEN
            N = N + 1
            YLM(N) = YLM(I)
          END IF
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN055
 
      REAL FUNCTION GEN056 (IH, IK, IL, GINV)
C * CALCULATE SIN(THETA)/LAMBDA
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      REAL :: GEN006
      REAL, DIMENSION(3)    :: H
      REAL, DIMENSION(3, 3) :: GINV
      H(1) = IH
      H(2) = IK
      H(3) = IL
      GEN056 = 0.5 * SQRT (GEN006 (H, GINV, H))
      RETURN
      END FUNCTION GEN056
 
      SUBROUTINE GEN057 (A, X, D, N)
C * GAUSS-ELIMINATION METHOD FOR MATRIX INVERSION   A*X=D
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      REAL :: Y
      REAL :: E
      REAL :: RL
      REAL :: RM
      REAL, DIMENSION(N, N) :: A
      REAL, DIMENSION(N)    :: X
      REAL, DIMENSION(N)    :: D
      K  = 0
      I  = 1
   10 J  = I
      RL = 0
   20 IF (ABS (A(J, I)) > RL) THEN
        RL = ABS (A(J, I))
        K  = J
      END IF
      J = J + 1
      IF (J <= N) GO TO 20
      J = I
      IF (K /= I) THEN
   30   Y = A(I, J)
        A(I, J) = A(K, J)
        A(K, J) = Y
        J = J + 1
        IF (J <= N) GO TO 30
        Y    = D(I)
        D(I) = D(K)
        D(K) = Y
      END IF
      J = I + 1
      IF (I /= N) THEN
   40   RM = A(J, I) / A(I, I)
        K  = I
   50   A(J, K) = A(J, K) - RM * A(I, K)
        K = K + 1
        IF (K <= N) GO TO 50
        D(J) = D(J) - RM * D(I)
        J = J + 1
        IF (J <= N) GO TO 40
        I = I + 1
        IF (I <= N) GO TO 10
      END IF
      I = N
   60 E = D(I)
      IF (I /= N) THEN
        J = I + 1
   70   E = - A(I, J) * X(J) + E
        J = J + 1
        IF (J <= N) GO TO 70
      END IF
      X(I) = E / A(I, I)
      I    = I - 1
      IF (I /= 0) GO TO 60
      RETURN
      END SUBROUTINE GEN057
 
      SUBROUTINE GEN058 (LABI, NR)
C * CONVERT NUMBER TO ATOM LABEL
      IMPLICIT NONE
      INTEGER :: NR
      INTEGER :: NO
      INTEGER :: L0
      INTEGER :: IOST
      CHARACTER(len=4) :: LABI
      IOST = 0
      IF (LABI(2:2) /= ' ') THEN
        L0 = 1
        NO = 10 + NR
      ELSE
        L0 = 0
        NO = 500 + NR
      END IF
      IF (NO < 100) THEN
        WRITE (LABI(2+L0:3+L0), 99999, IOSTAT = IOST) NO
      ELSE
        WRITE (LABI(2:4), 99998, IOSTAT = IOST) NO
      END IF
      RETURN
99999 FORMAT (I2)
99998 FORMAT (I3)
      END SUBROUTINE GEN058
 
      SUBROUTINE GEN059 (A, B, C)
C * MATRIX MANIPULATION ROUTINES FOR 4X4 HOMOGENEOUS TRANSFORMATIONS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL, DIMENSION(4, 4) :: C
      REAL, DIMENSION(4, 4) :: A
      REAL, DIMENSION(4, 4) :: B
      DO I = 1, 4
        DO J = 1, 4
          C(I, J) = A(I, 1) * B(1, J) + A(I, 2) * B(2, J)
     1            + A(I, 3) * B(3, J) + A(I, 4) * B(4, J)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN059
 
      SUBROUTINE GEN060 (A, B)
C * TRANSPOSE 4X4 MATRIX
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL, DIMENSION(4, 4) :: B
      REAL, DIMENSION(4, 4) :: A
      DO I = 1, 4
        DO J = 1, 4
          B(I, J) = A(J, I)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN060
 
      REAL FUNCTION GEN061 (A, AI)
C * MATRIX INVERSION FOR A 4X4 MATRIX A
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER, DIMENSION(4) :: INDZ
      REAL :: D
      REAL, DIMENSION(4, 4) :: AI
      REAL, DIMENSION(4, 4) :: A
      REAL, DIMENSION(4, 4) :: TMP
      DO I = 1, 4
        DO J = 1, 4
          TMP(I, J) = A(I, J)
          AI(I, J) = 0.0
        END DO
        AI(I, I) = 1.0
      END DO
      CALL GEN062 (TMP, 4, INDZ, D)
      GEN061 = D * TMP(1, 1) * TMP(2, 2) * TMP(3, 3) * TMP(4, 4)
      DO J = 1, 4
        CALL GEN063 (TMP, 4, INDZ, AI(1, J))
      END DO
      RETURN
      END FUNCTION GEN061
 
      SUBROUTINE GEN062 (A, N, INDZ, D)
C ***********************************************************************
C *            MATRIX INVERSION VIA LU DECOMPOSITION                   *
C *     ADAPTED FROM NUMERICAL RECIPES IN FORTRAN (1986)               *
C ***********************************************************************
      IMPLICIT NONE
      INTEGER, PARAMETER :: NMAX = 10
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IMAX
      INTEGER, DIMENSION(N) :: INDZ
      REAL :: D
      REAL :: SUMX
      REAL :: DUM
      REAL :: AAMAX
      REAL, DIMENSION(N, N) :: A
      REAL, DIMENSION(NMAX) :: VV
C ***********************************************************************
C * INPUT  NXN MATRIX A IS REPLACED BY ITS LU DECOMPOSITION
C * OUTPUT INDZ(N) RECORDS ROW PERMUTATION DUE TO PIVOTING
C * OUTPUT D IS PARITY OF ROW PERMUTATIONS
      IMAX = 0
      D    = 1.0
      DO I = 1, N
        AAMAX = 0.0
        DO J = 1, N
          IF (ABS (A(I, J)) > AAMAX) AAMAX = ABS (A(I, J))
        END DO
        VV(I) = 1.0 / AAMAX
      END DO
      DO J = 1, N
        IF (J > 1) THEN
          DO I = 1, J - 1
            SUMX = A(I, J)
            IF (I > 1) THEN
              DO K = 1, I - 1
                SUMX = SUMX - A(I, K) * A(K, J)
              END DO
              A(I, J) = SUMX
            END IF
          END DO
        END IF
        AAMAX = 0.0
        DO I = J, N
          SUMX = A(I, J)
          IF (J > 1) THEN
            DO K = 1, J - 1
              SUMX = SUMX - A(I, K) * A(K, J)
            END DO
            A(I, J) = SUMX
          END IF
          DUM = VV(I) * ABS (SUMX)
          IF (DUM >= AAMAX) THEN
            IMAX = I
            AAMAX = DUM
          END IF
        END DO
        IF (J /= IMAX) THEN
          DO K = 1, N
            DUM = A(IMAX, K)
            A(IMAX, K) = A(J, K)
            A(J, K) = DUM
          END DO
          D = - D
          VV(IMAX) = VV(J)
        END IF
        INDZ(J) = IMAX
        IF (J /= N) THEN
          DUM = 1.0 / A(J, J)
          DO I = J + 1, N
            A(I, J) = A(I, J) * DUM
          END DO
        END IF
      END DO
      RETURN
      END SUBROUTINE GEN062
 
      SUBROUTINE GEN063 (A, N, INDZ, B)
C * CORRESPONDING BACK-SUBSTITUTION ROUTINE (REF - GEN061)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: II
      INTEGER :: LL
      INTEGER, DIMENSION(N) :: INDZ
      REAL :: SUMX
      REAL,    DIMENSION(N)    :: B
      REAL,    DIMENSION(N, N) :: A
      II = 0
      DO I = 1, N
        LL = INDZ(I)
        SUMX  = B(LL)
        B(LL) = B(I)
        IF (II /= 0) THEN
          DO J = II, I - 1
            SUMX = SUMX - A(I, J) * B(J)
          END DO
        ELSE IF (SUMX /= 0.0) THEN
        II = I
        END IF
        B(I) = SUMX
      END DO
      DO I = N, 1, -1
        SUMX = B(I)
        IF (I < N) THEN
          DO J = I + 1, N
            SUMX = SUMX - A(I, J) * B(J)
          END DO
        END IF
        B(I) = SUMX / A(I, I)
      END DO
      RETURN
      END SUBROUTINE GEN063
 
      SUBROUTINE GEN064 (A, N, NP, D, V)
C **********************************************************************
C * FIND EIGENVALUES AND EIGENVECTORS OF NXN SYMMETRIC MATRIX USING    *
C * CYCLIC JACOBI METHOD. NP IS (FORTRAN) PHYSICAL STORAGE DIMENSION.  *
C * ON RETURN A IS DESTROYED, D CONTAINS EIGENVALUES,AND EACH COLUMN OF*
C * V IS A NORMALIZED EIGENVECTOR                                      *
C **********************************************************************
      IMPLICIT NONE
      INTEGER, PARAMETER :: NMAX=100
C * MACHINE DEPENDENT! (CONVERGE WHEN OFF-DIAGONAL SUM IS LESS THAN THIS)
      REAL, PARAMETER :: TINY = 1.E-37
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: IP
      INTEGER :: IQ
      INTEGER :: NP
      REAL :: G
      REAL :: H
      REAL :: T
      REAL :: S
      REAL :: C
      REAL :: SM
      REAL :: TAU
      REAL :: THETA
      REAL :: THRESH
      REAL, DIMENSION(NP, NP) :: A
      REAL, DIMENSION(NP, NP) :: V
      REAL, DIMENSION(NP)     :: D
      REAL, DIMENSION(NMAX)   :: B
      REAL, DIMENSION(NMAX)   :: Z
C * INITIALIZE V TO IDENTITY MATRIX, B AND D TO DIAGONAL OF A
      DO IP = 1, N
        DO IQ = 1, N
          V(IP, IQ) = 0.0
        END DO
        V(IP, IP) = 1.0
        B(IP)     = A(IP, IP)
        D(IP)     = B(IP)
        Z(IP)     = 0.0
      END DO
C * 50 SWEEPS IS NEVER EXPECTED TO HAPPEN; PRESS ET AL (1986) CLAIM
C * 6 TO 10 ARE TYPICAL FOR MODERATE MATRIX SIZES
      DO I = 1, 50
        SM = 0.0
        DO IP = 1, N - 1
          DO IQ = IP + 1, N
            SM = SM + ABS (A(IP, IQ))
          END DO
        END DO
        IF (SM < TINY) RETURN
C * AFTER 4 SWEEPS SKIP ROTATION IF THE OFF-DIAGONAL IS SMALL
        IF (I < 4) THEN
          THRESH = 0.2 * SM / (N * N)
        ELSE
          THRESH = 0.0
        END IF
        DO IP = 1, N - 1
          DO IQ = IP + 1, N
            G = 100.0 * ABS (A(IP, IQ))
            IF ((I > 4) .AND.
     1         (ABS (D(IP)) + G == ABS (D(IP))) .AND.
     2         (ABS (D(IQ)) + G == ABS (D(IQ)))) THEN
              A(IP,IQ) = 0.0
            ELSE IF (ABS(A(IP, IQ)) > THRESH) THEN
              H = D(IQ) - D(IP)
              IF (ABS (H) + G == ABS (H)) THEN
                T = A(IP, IQ) / H
              ELSE
                THETA = 0.5 * H / A(IP, IQ)
                T = 1.0 / (ABS (THETA) + SQRT (1.0 + THETA * THETA))
                IF (THETA < 0.0) T = -T
              END IF
              C = 1.0 / SQRT (1.0 + T * T)
              S = T * C
              TAU = S / (1.0 + C)
              H = T * A(IP, IQ)
              Z(IP) = Z(IP) - H
              Z(IQ) = Z(IQ) + H
              D(IP) = D(IP) - H
              D(IQ) = D(IQ) + H
              A(IP, IQ) = 0.0
              DO J = 1, IP - 1
                G = A(J, IP)
                H = A(J, IQ)
                A(J, IP) = G - S * (H + G * TAU)
                A(J, IQ) = H + S * (G - H * TAU)
              END DO
              DO J = IP + 1, IQ - 1
                G = A(IP, J)
                H = A(J, IQ)
                A(IP, J) = G - S * (H + G * TAU)
                A(J, IQ) = H + S * (G - H * TAU)
              END DO
              DO J = IQ + 1, N
                G = A(IP, J)
                H = A(IQ, J)
                A(IP, J) = G - S * (H + G * TAU)
                A(IQ, J) = H + S * (G - H * TAU)
              END DO
              DO J = 1, N
                G = V(J, IP)
                H = V(J, IQ)
                V(J, IP) = G - S * (H + G * TAU)
                V(J, IQ) = H + S * (G - H * TAU)
              END DO
            END IF
          END DO
        END DO
C * UPDATE D WITH SUM AND REINITIALIZE Z
        DO IP = 1, N
          B(IP) = B(IP) + Z(IP)
          D(IP) = B(IP)
          Z(IP) = 0.0
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN064
 
      SUBROUTINE GEN065 (LU, PRBUF, JBEG, JBUFL, JSUBST)
C * MODIFY AND PRINT PRINT-BUFFER
      USE genrl
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: I0
      INTEGER :: J0
      INTEGER :: K0
      INTEGER :: JL
      INTEGER :: JB
      INTEGER :: LU
      INTEGER :: IOST
      INTEGER :: JFRM
      INTEGER :: ITAR
      INTEGER :: IPAR
      INTEGER :: IDOT
      INTEGER :: KMAX
      INTEGER :: JBEG
      INTEGER :: IBUFL
      INTEGER :: JBUFL
      INTEGER :: ISUBST
      INTEGER :: JSUBST
      INTEGER :: JSUBST0
      INTEGER :: JSUBST1
      INTEGER :: JSUBST2
      INTEGER :: JSUBST3
      INTEGER :: JSUBST4
      CHARACTER(len=*)   :: PRBUF
      CHARACTER(len=133) :: PRB
      CHARACTER(len=1)   :: PCH
      CHARACTER(len=1)   :: PCH0
      CHARACTER(len=1)   :: PCH1
C * JSUBST0 : NO SUBSTITUTIONS, WITH ELIMINATION BLANKS i.e. (  3)->(3)
C * JSUBST1 : STRING SUBSTITUTION of 0.33333( 0) with 1/3 etc
C * JSUBST2 : STRING SUBST 0.333 WITH 1/3 etc.
C * JSUBST3 : STRING SUBST 0.0000 WITH 0 ETC.
C * JSUBST4 :
      IOST = 0
      J0   = 0
      J    = 0
      JL   = 0
      JB   = JBEG - 1
      PRB  = PRBUF(1:JBUFL)//' '
      IF (JB > 0) CALL GEN038 (PRB, 1, JB)
      IBUFL = JBUFL + 1
C * ALIGN NUMBERS
      IPAR   = 0
      K0     = 0
C * BIT # 1
      JSUBST0 = MOD (JSUBST, 2)
      IF (JSUBST0 == 1) THEN
        DO I = 2, IBUFL
          PCH = PRB(I : I)
          IF (PCH == '(') THEN
C * 1ST HANDLE THE SPECIAL '.(' CASE BY MOVING NUMBER 1 POSN TO THE RIGHT
            I0   = I - 1
            J0   = I0
            PCH0 = PRB(I0 : I0)
            IF (PCH0 == '.') THEN
              IDOT = 1
            ELSE
              IDOT = 0
            END IF
   10       J0   = J0 - 1
C * AVOID FALLOUT ON LEFT OF STRING (WITH DUMMY QUOTE)
            IF (J0 == 0) THEN
              PCH0 = ''''
            ELSE
              PCH0 = PRB(J0 : J0)
            END IF
            IF (IDOT == 1) PRB(J0 + 1 : J0 + 1) = PCH0
            IF (PCH0 /= ' ' .AND. PCH0 .NE. ')' .AND.
     1          PCH0 /= '''' .AND. PCH0 .NE. '"' .AND.
     2          PCH0 /= '-' .AND. J0 > K0) GO TO 10
            IF (IDOT == 1) PRB(J0 : J0) = ' '
            J0 = J0 - 1 + IDOT
            IF (PCH0 == '''' .OR. PCH0 == '"') J0 = J0 + 1
 
            IPAR = 1
            J    = I
            JL   = I
          ELSE IF (IPAR > 0) THEN
            IF (PCH == ')') THEN
              K0 = I + 1
              IF (J > JL) THEN
                J            = J + 1
                PRB(J : J) = PCH
              ELSE
                J      = J - 1
              END IF
C * SHIFT CHARACTER STRING TO THE RIGHT
              IF (J < I) THEN
                KMAX = J - J0
                ITAR = I + 1
                JFRM = J + 1
                DO K = 1, KMAX
                  PCH1 = PRB(JFRM - K : JFRM - K)
                  PRB(ITAR - K : ITAR - K) = PCH1
                END DO
                DO K = J0 + 1, I - KMAX
                  PRB(K : K) = ' '
                END DO
              END IF
              IPAR = 0
            ELSE IF (PCH /= ' ') THEN
C * SKIP BLANK AND ZERO LEADING CHARACTERS WITHIN PARENTHESES
              IF (PCH == '0') THEN
                IF (J > JL) THEN
                  J            = J + 1
                  PRB(J : J) = PCH
                END IF
              ELSE
                J            = J + 1
                PRB(J : J) = PCH
              END IF
            END IF
          END IF
        END DO
      END IF
      ISUBST  = JSUBST / 2
C * BIT # 2
      JSUBST1 = MOD (ISUBST, 2)
C * TYPE 1 - SUBSTITUTIONS
      IF (JSUBST1 == 1) THEN
        DO 20 I = 9, IBUFL
          DO K = 1, 56
            IF (PRB(I - 8 : I) == STR1(K)//' ') THEN
                PRB(I - 8 : I) = STR2(K)//' '
              GO TO 20
            END IF
          END DO
   20   CONTINUE
      END IF
      ISUBST  = ISUBST / 2
C * BIT # 3
      JSUBST2 = MOD (ISUBST, 2)
C * TYPE 2 - SUBSTITUTIONS
      IF (JSUBST2 == 1) THEN
        DO 30 I = 7, IBUFL
          DO K = 1, 48
            IF (PRB(I - 6 : I) == STR3(K)//' ' .OR.
     1          PRB(I - 6 : I) == STR3(K)//'-') THEN
                PRB(I - 6 : I - 1) = STR4(K)
              GO TO 30
            END IF
          END DO
   30   CONTINUE
      END IF
      ISUBST  = ISUBST / 2
C * BIT # 4
      JSUBST3 = MOD (ISUBST, 2)
C * TYPE 3 - SUBSTITUTIONS
      IF (JSUBST3 == 1) THEN
        DO I = 8, IBUFL
          IF (PRB(I - 7: I) == ' 0.0000 ' .OR.
     1        PRB(I - 7: I) == ' 0.0000-') THEN
              PRB(I - 7: I - 1)  =  '      0'
          ELSE IF (PRB(I - 7: I) == ' 1.0000 ' .OR.
     1             PRB(I - 7: I) == ' 1.0000-') THEN
              PRB(I - 7: I - 1)  =  '      1'
          ELSE IF (PRB(I - 7: I) == '-1.0000 ' .OR.
     1             PRB(I - 7: I) == '-1.0000-') THEN
              PRB(I - 7: I - 1)  =  '     -1'
          END IF
        END DO
      END IF
      ISUBST  = ISUBST / 2
C * BIT # 5
      JSUBST4 = MOD (ISUBST, 2)
C * TYPE 4 - SUBSTITUTIONS
      IF (JSUBST4 == 1) THEN
        DO I = 6, IBUFL
          DO J = 1, 16
            IF (PRB(I - 5: I) == STR5(J)) THEN
              PRB(I - 5: I) = STR6(J)
            END IF
          END DO
        END DO
      END IF
      IF (JB > 0) PRB(1:JB) = PRBUF(1:JB)
      PRBUF = PRB(1:JBUFL)
      IF (LU /= 0) THEN
        IF (LU == 6) THEN
          CALL TRAILER (PRBUF(1:JBUFL))
        ELSE
          WRITE (LU, 99999, IOSTAT = IOST) PRBUF(1 : JBUFL)
        END IF
      END IF
      RETURN
99999 FORMAT (A)
      END SUBROUTINE GEN065
 
      SUBROUTINE GEN066 (MODE, PARA, PARS, KS, MSETTING)
C * APPLY SYMMETRY CONSTRAINTS ON CELL DIMENSIONS
      IMPLICIT NONE
      INTEGER :: MODE
      INTEGER :: MSETTING
      REAL :: TOL
      REAL :: AVER
      REAL, DIMENSION(6) :: PARA
      REAL, DIMENSION(6) :: PARS
      CHARACTER(len=1)   :: KS
C * MODE = 0 : CELL PAR ONLY
C * MODE = 1 : + ESD'S TOL = 0.1
C * MODE = 2 : + ESD'S TOL = 0.5
C * MONOCLINIC
      IF (MODE == 2) THEN
        TOL = 0.5
      ELSE
        TOL = 0.1
      END IF
      IF (KS == 'm') THEN
 
        IF (MSETTING == 0) THEN
          IF (ABS(PARA(4) - 90.0) + ABS (PARA(6) - 90.0) < TOL) THEN
            PARA(4) = 90.0
            PARA(6) = 90.0
            IF (MODE > 0) THEN
              PARS(4) = 0.0
              PARS(6) = 0.0
            END IF
          END IF
        ELSE IF (MSETTING == 1) THEN
          IF (ABS(PARA(5) - 90.0) + ABS (PARA(6) - 90.0) < TOL) THEN
            PARA(4) = 90.0
            PARA(5) = 90.0
            IF (MODE > 0) THEN
              PARS(4) = 0.0
              PARS(5) = 0.0
            END IF
          END IF
 
        ELSE IF (MSETTING == 3) THEN
          IF (ABS(PARA(4) - 90.0) + ABS (PARA(5) - 90.0) < TOL) THEN
            PARA(4) = 90.0
            PARA(5) = 90.0
            IF (MODE > 0) THEN
              PARS(4) = 0.0
              PARS(5) = 0.0
            END IF
          END IF
        END IF
C * ORTHORHOMBIC
      ELSE IF (KS == 'o') THEN
        PARA(4) = 90.0
        PARA(5) = 90.0
        PARA(6) = 90.0
        IF (MODE > 0) THEN
          PARS(4) = 0.0
          PARS(5) = 0.0
          PARS(6) = 0.0
        END IF
C * TETRAGONAL
      ELSE IF (KS == 't') THEN
        AVER    = (PARA(1) + PARA(2)) / 2.0
        PARA(1) = AVER
        PARA(2) = AVER
        PARA(4) = 90.0
        PARA(5) = 90.0
        PARA(6) = 90.0
        IF (MODE > 0) THEN
          AVER    = (PARS(1) + PARS(2)) / 2.0
          PARS(1) = AVER
          PARS(2) = AVER
          PARS(4) = 0.0
          PARS(5) = 0.0
          PARS(6) = 0.0
        END IF
C * TRIGONAL (RHOMBOHEDRAL)
      ELSE IF (KS == 'r') THEN
        AVER    = (PARA(1) + PARA(2) + PARA(3)) / 3.0
        PARA(1) = AVER
        PARA(2) = AVER
        PARA(3) = AVER
        AVER    = (PARA(4) + PARA(5) + PARA(6)) / 3.0
        PARA(4) = AVER
        PARA(5) = AVER
        PARA(6) = AVER
        IF (MODE > 0) THEN
          AVER    = (PARS(1) + PARS(2) + PARS(3)) / 3.0
          PARS(1) = AVER
          PARS(2) = AVER
          PARS(3) = AVER
          AVER    = (PARS(4) + PARS(5) + PARS(6)) / 3.0
          PARS(4) = AVER
          PARS(5) = AVER
          PARS(6) = AVER
        END IF
C * HEXAGONAL
      ELSE IF (KS == 'h') THEN
        AVER    = (PARA(1) + PARA(2)) / 2.0
        PARA(1) = AVER
        PARA(2) = AVER
        PARA(4) = 90.0
        PARA(5) = 90.0
        PARA(6) = 120.0
        IF (MODE > 0) THEN
          AVER    = (PARS(1) + PARS(2)) / 2.0
          PARS(1) = AVER
          PARS(2) = AVER
          PARS(4) = 0.0
          PARS(5) = 0.0
          PARS(6) = 0.0
        END IF
C * CUBIC
      ELSE IF (KS == 'c') THEN
        AVER     = (PARA(1) + PARA(2) + PARA(3)) / 3.0
        PARA(1) = AVER
        PARA(2) = AVER
        PARA(3) = AVER
        PARA(4) = 90.0
        PARA(5) = 90.0
        PARA(6) = 90.0
        IF (MODE > 0) THEN
          AVER     = (PARS(1) + PARS(2) + PARS(3)) / 3.0
          PARS(1) = AVER
          PARS(2) = AVER
          PARS(3) = AVER
          PARS(4) = 0.0
          PARS(5) = 0.0
          PARS(6) = 0.0
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN066
 
      SUBROUTINE GEN067 (TM, CELO, CELN, CSDO, CSDN)
C * TRANSFORM CELL-ESD'S
      IMPLICIT NONE
      INTEGER               :: I
      INTEGER               :: J
      REAL                  :: DEL
      REAL, DIMENSION(3, 3) :: AA
      REAL, DIMENSION(3, 3) :: BB
      REAL, DIMENSION(3, 3) :: TM
      REAL, DIMENSION(6)    :: A
      REAL, DIMENSION(6)    :: B
      REAL, DIMENSION(6)    :: C
      REAL, DIMENSION(6)    :: D
      REAL, DIMENSION(6)    :: CELO
      REAL, DIMENSION(6)    :: CELN
      REAL, DIMENSION(6)    :: CSDO
      REAL, DIMENSION(6)    :: CSDN
C * COPY OLD CELL PARAMETERS
      CALL GEN113 (CELO, A, 6)
C * COPY NEW CELL PARAMETERS
      CALL GEN113 (CELN, B, 6)
C * LOOP OVER CELL PARAMETERS
      DO J = 1, 6
        D(J) = 0.0
C * LOOP OVER S.U. CONTRIBUTERS
        DO I = 1, 6
          DEL = CSDO(I)
          IF (DEL > 0.0) THEN
            DEL  = DEL / 2.0
            A(I) = A(I) + DEL
C * CALCULATE METRIC
            CALL GEN026 (1, AA, A)
            A(I) = A(I) - DEL
C * TRANSFORM METRIC
            CALL GEN001 (1, TM, AA, BB)
C * GET REVISED CELL PARAMETERS
            CALL GEN026 (-1, BB, C(1))
            D(J) = D(J) + ((B(J) - C(J)) * 2.0) ** 2
          END IF
        END DO
      END DO
      DO J = 1, 6
        CSDN(J) = SQRT (D(J))
      END DO
      RETURN
      END SUBROUTINE GEN067
 
      REAL FUNCTION GEN068 (C, D, K)
C * CALCULATE VOLUME S.U.
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      REAL :: SV
      REAL :: GEN163
      REAL :: VOLUME
      REAL, DIMENSION(6) :: C
      REAL, DIMENSION(6) :: D
      IF (K == 2) THEN
C * MONOCLINIC-C
        IF (C(4) == 90.0 .AND. C(5) == 90.0) THEN
          K = 9
C * MONOCLINIC-A
        ELSE IF (C(5) == 90.0 .AND. C(6) == 90.0) THEN
          K = 10
        END IF
      END IF
      VOLUME = GEN163(C, D, K, 0)
      SV = 0.0
C * TRICLINIC
      IF (K == 1) THEN
        DO I = 1, 6
          IF (D(I) > 0.0) THEN
            SV = SV + (VOLUME - GEN163(C, D, 1, I))**2
          END IF
        END DO
C * MONOCLINIC
      ELSE IF (K == 2) THEN
        DO I = 1, 3
          SV = SV + (VOLUME - GEN163(C, D, 2, I))**2
        END DO
        SV = SV + (VOLUME - GEN163(C, D, 2, 5))**2
C * ORTHORHOMBIC
      ELSE IF (K == 3) THEN
        DO I = 1, 3
          SV = SV + (VOLUME - GEN163(C, D, 3, I))**2
        END DO
C * TRIGONAL
      ELSE IF (K == 4 .OR. K == 6) THEN
        SV = SV + (VOLUME - GEN163(C, D, K, 1))**2
        SV = SV + (VOLUME - GEN163(C, D, K, 3))**2
C * TETRAGONAL
      ELSE IF (K == 5) THEN
        SV = SV + (VOLUME - GEN163(C, D, 5, 1))**2
        SV = SV + (VOLUME - GEN163(C, D, 5, 3))**2
C * CUBIC
      ELSE IF (K == 7) THEN
        SV = SV + (VOLUME - GEN163(C, D, 7, 1))**2
C * RHOMBOHEDRAL
      ELSE IF (K == 8) THEN
        SV = SV + (VOLUME - GEN163(C, D, 8, 1))**2
        SV = SV + (VOLUME - GEN163(C, D, 8, 4))**2
C * MONOCLINIC-C
      ELSE IF (K == 9) THEN
        DO I = 1, 3
          SV = SV + (VOLUME - GEN163(C, D, 9, I))**2
        END DO
        SV = SV + (VOLUME - GEN163(C, D, 9, 6))**2
C * MONOCLINIC-A
      ELSE IF (K == 10) THEN
        DO I = 1, 3
          SV = SV + (VOLUME - GEN163(C, D, 10, I))**2
        END DO
        SV = SV + (VOLUME - GEN163(C, D, 10, 4))**2
      ENDIF
      GEN068 = SQRT (SV)
      RETURN
      END FUNCTION  GEN068
 
      SUBROUTINE GEN069 (K, A, B, C, P, SIGMA, D, G)
C * TRFORD
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: I1
      INTEGER :: J1
      INTEGER :: K1
      REAL :: H
      REAL :: SIGMA
      REAL, DIMENSION(*)    :: A
      REAL, DIMENSION(*)    :: B
      REAL, DIMENSION(*)    :: C
      REAL, DIMENSION(*)    :: P
      REAL, DIMENSION(*)    :: D
      REAL, DIMENSION(*)    :: G
      REAL, DIMENSION(1000) :: S0
      REAL, DIMENSION(1000) :: S1
      IF (K == 0) THEN
        D(1) = 1.0
        P(1) = C(1)
      ELSE
        S0(1) = 1.0
        S1(2) = 1.0
        S1(1) = -A(1)
        P(1)  = -C(2) * A(1) + C(1)
        P(2)  = C(2)
        D(1)  = A(1)**2 / G(2) + 1.0 / G(1)
        D(2)  = 1.0 / G(2)
        IF (K > 1) THEN
          DO I = 2, K
            D(I + 1) = 0.0
            P(I + 1) = 0.0
          END DO
          K1 = K - 1
          DO J = 1, K1
            S0(J + 2) = 1.0
            S0(J + 1) = S1(J) - A(J + 1)
            IF (J > 1) S0(J) = S1(J - 1) - A(J + 1) * S1(J) - B(J)
            IF (J > 2) THEN
              J1 = J - 2
              DO I1 = 1, J1
                I = J1 - I1 + 1
                S0(I + 1) =
     1            S1(I) - A(J + 1) * S1(I + 1) - B(J) * S0(I + 1)
              END DO
            END IF
            S0(1) = -A(J + 1) * S1(1) - B(J) * S0(1)
            J1 = J + 2
            DO I = 1, J1
              IF (I /= J1) THEN
                H     = S1(I)
                S1(I) = S0(I)
                S0(I) = H
              ELSE
                S1(I) = S0(I)
              END IF
              P(I)  = P(I) + C(J + 2) * S1(I)
              D(I)  = D(I) + S1(I)**2 / G(J + 2)
            END DO
          END DO
        END IF
      END IF
      K1 = K + 1
      DO I = 1, K1
        D(I) = SIGMA * SQRT (D(I))
      END DO
      RETURN
      END SUBROUTINE GEN069
 
      SUBROUTINE GEN070 (N, X, F, W, K, A, B, C, G, V)
C * POLFIW
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: I1
      INTEGER :: I3
      INTEGER :: K3
      REAL :: S
      REAL :: S0
      REAL :: S1
      REAL :: G0
      REAL :: G1
      REAL :: XS
      REAL :: FS
      REAL :: DELTA
      REAL, DIMENSION(*) :: X
      REAL, DIMENSION(*) :: F
      REAL, DIMENSION(*) :: W
      REAL, DIMENSION(*) :: A
      REAL, DIMENSION(*) :: B
      REAL, DIMENSION(*) :: C
      REAL, DIMENSION(*) :: G
      REAL, DIMENSION(*) :: V
      DELTA = 0.0
      DO J = 1, N
        DELTA = DELTA + W(J) * F(J)**2
      END DO
      K3 = K + 1
      DO I3 = 1, K3, 1
        I = I3 - 1
        XS = 0.0
        FS = 0.0
        S1 = 0.0
        S0 = 0.0
        DO J = 1, N
          G1 = 1.0
          G0 = 0.0
          IF (I > 0) THEN
            DO I1 = 1, I, 1
              S = 0.0
              IF (I1 /= 1) S = B(I1 - 1) * G0
              G0 = (X(J) - A(I1)) * G1 - S
              S  = G0
              G0 = G1
              G1 = S
            END DO
          END IF
          S1 = S1 + G1**2 * W(J)
          FS = FS + G1 * F(J) * W(J)
          IF (I /= K) THEN
            S0 = S0 + G0**2 * W(J)
            XS = XS + G1**2 * X(J) * W(J)
          END IF
        END DO
        IF (I /= K) THEN
          A(I + 1) = XS / S1
          IF (I /= 0) B(I) = S1 / S0
        END IF
        C(I + 1) = FS / S1
        G(I + 1) = S1
        IF (I /= 0) V(I + 1) = ABS (V(I)  - C(I + 1)**2 * S1)
        IF (I == 0) V(I + 1) = ABS (DELTA - C(I + 1)**2 * S1)
      END DO
      RETURN
      END SUBROUTINE GEN070
 
      REAL FUNCTION GEN071 (K, A, B, C, T, DER)
C * EVAPOL
      IMPLICIT NONE
      INTEGER, PARAMETER :: IP5=2
      INTEGER :: I
      INTEGER :: K
      REAL :: S
      REAL :: T
      REAL :: D0
      REAL :: D1
      REAL :: G0
      REAL :: G1
      REAL :: S1
      REAL :: DER
      REAL, DIMENSION(IP5) :: A
      REAL, DIMENSION(IP5) :: B
      REAL, DIMENSION(IP5) :: C
      D0  = 0.0
      G0  = 0.0
      S1  = C(1)
      G1  = 1.0
      DER = 0.0
      D1  = 0.0
      IF (K /= 0) THEN
        DO I = 1, K
          S = 0.0
          IF (I /= 1) S = B(I - 1) * D0
          D0  = (T - A(I)) * D1 - S + G1
          S   = D0
          D0  = D1
          D1  = S
          DER = DER + C(I + 1) * D1
          S   = 0.0
          IF (I /= 1) S = B(I - 1) * G0
          G0 = (T - A(I)) * G1 - S
          S  = G0
          G0 = G1
          G1 = S
          S1 = S1 + C(I + 1) * G1
        END DO
      END IF
      GEN071 = S1
      RETURN
      END FUNCTION GEN071
 
      SUBROUTINE GEN072 (LINE, IFL, FN, KL, KN, LU5, LU6, IUP,
     1 JMIN, JMAX, NCHAR, NP17)
C * FREE FORMAT READ ROUTINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: IP
      INTEGER :: NP
      INTEGER :: LU5
      INTEGER :: LU6
      INTEGER :: IUP
      INTEGER :: INUM
      INTEGER :: IMIN
      INTEGER :: IMAX
      INTEGER :: JMIN
      INTEGER :: JMAX
      INTEGER :: IOST
      INTEGER :: NCHAR
      INTEGER :: ICONT
      INTEGER :: NP17
      REAL :: A
      REAL :: S
      REAL, DIMENSION(*) :: FN
      CHARACTER(len=80) :: ICL
      CHARACTER(len=1)  :: ICH
      CHARACTER(len=80) :: LINE
      CHARACTER(len=*), DIMENSION(*) :: IFL
      GO TO 20
   10 IF (LU6 /= 0) THEN
        CALL TRAILER (' ')
        CALL TRAILER ('** ^C Ignored - s[default]')
      END IF
   20 KN    = 0
      KL    = 0
      ICONT = 0
C * INITIALIZE LITERAL AND NUMBER ARRAYS (IFL & FN)
      CALL GEN074 (FN, 1, NP17, 0.0)
      DO I = 1, NP17
        CALL GEN038 (IFL(I), 1, NCHAR)
      END DO
C * READ OR USE CARD-IMAGE IN CHARACTER BUFFER
   30 IF (LU5 /= 0) THEN
        READ (LU5, 99998, IOSTAT = IOST) LINE
        IF (IOST /= 0) THEN
          IF (IOST == -1) THEN
            IFL(1) = 'EOF       '
            KL     = 1
            RETURN
          ELSE
            GO TO 10
          END IF
        END IF
      END IF
      IMIN = JMIN
      IMAX = JMAX
C * AVOID READING SPECIAL CARDS
      IF (LINE(1:4) == 'EXTI') IMAX = 4
      IF (LINE(1:4) == 'TITL') THEN
        N = INDEX (LINE, '=')
        IF (N /= 0) IMAX = N - 1
      END IF
C * ADD BLANKS BETWEEN NUMBER AND CHARACTER (IN THAT ORDER)
      IF (IMAX == 0) THEN
        IMIN = 1
        INUM = 0
        DO I = JMIN, 80
          ICH  = LINE(I:I)
          CALL GEN105 (3, ICH, J)
          IF (J >= 0) THEN
            INUM = 1
            GO TO 40
          END IF
          IF (ICH == '.') THEN
            INUM = 1
            GO TO 40
          END IF
          IF (INUM == 1) THEN
            INUM = 0
            IF (ICH /= ' ') THEN
              IF (IMAX < 80) THEN
                IMAX = IMAX + 1
                ICL(IMAX:IMAX) = ' '
              END IF
            END IF
          END IF
   40     IF (IMAX < 80) THEN
            IMAX = IMAX + 1
            ICL(IMAX:IMAX) = LINE(I:I)
          END IF
        END DO
      ELSE
        ICL = LINE
      END IF
C * REMOVE CTRL-M
      DO I = 1, 80
        IF (ICL(I:I) == CHAR (13)) ICL(I:I) = ' '
      END DO
      IF (IMAX == 0) GO TO 130
C * CONVERT TO UPPER-CASE LETTERS
C * SEARCH FOR CONTINUATION MARK = (ALL REMAINDER CHARACTERS SKIPPED)
      IF (IUP == 1) CALL GEN020 (1, ICL, IMIN, IMAX)
      DO I = IMIN, IMAX
        ICH = ICL(I:I)
        IF (ICH == '=') THEN
          IMAX  = I - 1
          ICONT = 1
          GO TO 50
        END IF
      END DO
C * ANALYSE FORMULA FROM COLUMN IMIN THROUGH IMAX
      ICONT = 0
C * MAXIMUM SIZE LITERAL FIELD : NCHAR
   50 I     = IMIN - 1
C * START OF A NEW FIELD
   60 A     = 0.0
      IP    = 0
      NP    = 0
      L     = 0
      S     = 1.0
C * LOOK FOR A NON-BLANK COLUMN
   70 I     = I + 1
      IF (I <= IMAX) THEN
        ICH = ICL(I:I)
        IF (L == 0 .AND. ICH == ' ') GO TO 70
C * START OF A FIELD
        L     = L + 1
        CALL GEN105 (3, ICH, J)
        IF (J >= 0) THEN
C * START OF A LITERAL FIELD BY A CHARACTER WHICH IS OTHER THAN 0-9+-.
C * NUMERIC FIELD FOUND
          NP = NP + IP
          A  = 10.0 * A + J - 1
          GO TO 70
        END IF
        IF (ICH == '.') THEN
          IP = 1
        ELSE IF (ICH == '+') THEN
          IF (L > 1) GO TO 80
          S = 1.0
        ELSE IF (ICH == '-') THEN
          IF (L > 1) GO TO 80
          S = -1.0
        ELSE IF (ICH == ')') THEN
          GO TO 80
        ELSE
          IF (L > 1) GO TO 80
          GO TO 90
        END IF
        GO TO 70
      END IF
      IF (L <= 0) GO TO 130
C * END OF NUMERIC FIELD
   80 A = S * A / 10.0**NP
      IF (KN < NP17) THEN
        KN     = KN + 1
        FN(KN) = A
      END IF
      IF (ICH == '+' .OR. ICH == '-') I = I - 1
      GO TO 60
C * START NEW LITERAL FIELD
   90 KL = KL + 1
  100 IFL(KL)(L:L) = ICH
      L = L + 1
  110 I = I + 1
      IF (I <= IMAX) THEN
        ICH = ICL(I:I)
C * BREAK LITERAL MODE ON SPACE, COMMA (OR CONDITIONAL LEFT PARENTHESIS)
        IF (ICH /= ' ' .AND. ICH .NE. ',') THEN
C * CATCH SPAR( ) CASE
          IF (ICH /= '(' .OR. L <= 3) THEN
C * PLUS, MINUS OR DOT START NUMERICAL FIELD
            IF (ICH == '+' .OR. ICH == '-' .OR. ICH == '.')
     1        GO TO 120
            IF (L > NCHAR) THEN
              GO TO 110
            ELSE
              GO TO 100
            END IF
C * END OF LITERAL FIELD
  120       I = I - 1
          END IF
        END IF
      END IF
      GO TO 60
C * TEST FOR CONTINUATION OR FINISHED
  130 IF (ICONT == 1) GO TO 30
      RETURN
99998 FORMAT (A)
      END SUBROUTINE GEN072
 
      SUBROUTINE GEN073 (A, B, C, D, E, I, J, K)
C * D*A+B*E=C
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      REAL :: D
      REAL :: E
      REAL, DIMENSION(3, *) :: A
      REAL, DIMENSION(3, *) :: B
      REAL, DIMENSION(3, *) :: C
      C(1, K) = A(1, I) * D + B(1, J) * E
      C(2, K) = A(2, I) * D + B(2, J) * E
      C(3, K) = A(3, I) * D + B(3, J) * E
      RETURN
      END SUBROUTINE GEN073
 
      SUBROUTINE GEN074 (A, NB, NE, VAL)
C * SET REAL ARRAY ON VALUE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: NB
      INTEGER :: NE
      REAL :: VAL
      REAL, DIMENSION(*) :: A
      DO I = NB, NE
        A(I) = VAL
      END DO
      RETURN
      END SUBROUTINE GEN074
 
      SUBROUTINE GEN075 (A, B, C, I, J, K)
C * K = 1 - SCALAR PRODUCT A*B=C [MOLSYM]
C * K = 2 - SQRT (A)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      REAL :: C
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL, DIMENSION(3, *) :: A
      REAL, DIMENSION(3, *) :: B
      X = 0.0
      DO L = 1, 3
        Y = A(L, I)
        Z = B(L, J)
        X = X + Y * Z
      END DO
      IF (K == 1) THEN
        C = X
      ELSE
        C = SQRT(X)
      END IF
      RETURN
      END SUBROUTINE GEN075
 
      SUBROUTINE GEN076 (A, B, C, I, J, K)
C * VECTOR PRODUCT A*B=C [MOLSYM]
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      REAL :: X1
      REAL :: X2
      REAL :: X3
      REAL :: Y1
      REAL :: Y2
      REAL :: Y3
      REAL, DIMENSION(3, *) :: A
      REAL, DIMENSION(3, *) :: B
      REAL, DIMENSION(3, *) :: C
      X1      = A(1, I)
      X2      = A(2, I)
      X3      = A(3, I)
      Y1      = B(1, J)
      Y2      = B(2, J)
      Y3      = B(3, J)
      C(1, K) =  X2 * Y3 - X3 * Y2
      C(2, K) = -X1 * Y3 + X3 * Y1
      C(3, K) =  X1 * Y2 - X2 * Y1
      RETURN
      END SUBROUTINE GEN076
 
      SUBROUTINE GEN077 (A, B, C, I, J, N)
C * MOLSYM ROUTINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      REAL :: Y
      REAL :: Z
      REAL, DIMENSION(3, 3, *) :: A
      REAL, DIMENSION(3, 3, *) :: B
      REAL, DIMENSION(3, 3, *) :: C
      REAL, DIMENSION(3, 3)    :: X
      DO K = 1, 3
        DO L = 1, 3
          X(K, L) = 0.0
          DO M = 1, 3
            Y = A(K, M, I)
            Z = B(M, L, J)
            X(K, L) = X(K, L) + Y * Z
          END DO
        END DO
      END DO
      DO K = 1, 3
        DO L = 1, 3
          C(K, L, N) = X(K, L)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN077
 
      SUBROUTINE GEN078 (A, B, C, I, J, K)
C * MOLSYM ROUTINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      REAL :: Y
      REAL :: Z
      REAL, DIMENSION(3, 3, *) :: A
      REAL, DIMENSION(3, *)    :: B
      REAL, DIMENSION(3, *)    :: C
      REAL, DIMENSION(3)       :: X
      DO L = 1, 3
        X(L) = 0.0
        DO M = 1, 3
          Y    = A(L, M, I)
          Z    = B(M, J)
          X(L) = X(L) + Y * Z
        END DO
      END DO
      DO L = 1, 3
        C(L, K) = X(L)
      END DO
      RETURN
      END SUBROUTINE GEN078
 
      SUBROUTINE GEN079 (A, B, I, J)
C * COPY MATRIX
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      REAL, DIMENSION(3, 3, *) :: A
      REAL, DIMENSION(3, 3, *) :: B
      DO K = 1, 3
        DO L = 1, 3
          B(K, L, J) = A(K, L, I)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN079
 
      SUBROUTINE GEN080 (A, B, I, J)
C * COPY VECTOR
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL, DIMENSION(3, *) :: A
      REAL, DIMENSION(3, *) :: B
      B(1, J) = A(1, I)
      B(2, J) = A(2, I)
      B(3, J) = A(3, I)
      RETURN
      END SUBROUTINE GEN080
 
      SUBROUTINE GEN081 (A, B, M, N)
C * MOLSYM ROUTINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      REAL, DIMENSION(3, 3, *) :: A
      REAL, DIMENSION(3, 3, *) :: B
      REAL, DIMENSION(3, 3)    :: C
      DO I = 1, 3
        DO J = 1, 3
          C(I, J) = A(J, I, M)
        END DO
      END DO
      CALL GEN079 (C, B, 1, N)
      RETURN
      END SUBROUTINE GEN081
 
      SUBROUTINE GEN082 (A, I)
C * MOLSYM ROUTINE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL :: B
      REAL, DIMENSION(3, *) :: A
      CALL GEN075 (A, A, B, I, I, 2)
      IF (B /= 0.0) THEN
        DO J = 1, 3
          A(J, I) = A(J, I) / B
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN082
 
      SUBROUTINE GEN083 (T, U, V, A)
C * PLANE TROUGH POINTS T, U, V
      IMPLICIT NONE
      INTEGER :: I
      REAL :: DIST
      REAL :: GEN084
      REAL, DIMENSION(3)    :: T
      REAL, DIMENSION(3)    :: U
      REAL, DIMENSION(3)    :: V
      REAL, DIMENSION(4)    :: A
      REAL, DIMENSION(3, 3) :: AA
      REAL, DIMENSION(3, 3) :: DD
C * A(1) x X +A(2) x Y + A(3) x Z + A(4) = 0
C * DIR.COS: A(1), A(2), A(3), A(4) = - DISTANCE TO ORIGIN
C * INTERNATIONAL TABLES FOR CRYSTALLOGRAPHY II, P. 43, EQU. 2,3,4, 6
      DD(1, 1) = T(1)
      DD(1, 2) = T(2)
      DD(1, 3) = T(3)
      DD(2, 1) = U(1)
      DD(2, 2) = U(2)
      DD(2, 3) = U(3)
      DD(3, 1) = V(1)
      DD(3, 2) = V(2)
      DD(3, 3) = V(3)
      DO I = 1, 3
        CALL GEN079 (DD, AA, 1, 1)
        CALL GEN074 (AA(1, I), 1, 3, 1.0)
        A(I) = GEN084 (AA, 1)
      END DO
      CALL GEN075 (A, A, DIST, 1, 1, 2)
      A(1) =  A(1) / DIST
      A(2) =  A(2) / DIST
      A(3) =  A(3) / DIST
      A(4) = -GEN084 (DD, 1) / DIST
      RETURN
      END SUBROUTINE GEN083
 
      REAL FUNCTION GEN084 (X, N)
C * DETERMINANT FOR MATRIX X
      IMPLICIT NONE
      INTEGER :: N
      REAL, DIMENSION(3, 3, *) :: X
      GEN084 = X(1, 1, N) * X(2, 2, N) * X(3, 3, N)
     1       - X(1, 1, N) * X(2, 3, N) * X(3, 2, N)
     2       + X(1, 2, N) * X(2, 3, N) * X(3, 1, N)
     3       - X(1, 2, N) * X(2, 1, N) * X(3, 3, N)
     4       + X(1, 3, N) * X(2, 1, N) * X(3, 2, N)
     5       - X(1, 3, N) * X(2, 2, N) * X(3, 1, N)
      RETURN
      END FUNCTION GEN084
 
      SUBROUTINE GEN085 (WORD, L, K)
C * COMPACT (ELIMINATE BLANKS ETC)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      CHARACTER(len=*) :: WORD
      K = 0
      DO I = 1, L
        IF (WORD(I:I) > ' ' .AND. WORD(I:I) <= '~') THEN
          K = K + 1
          WORD(K:K) = WORD(I:I)
        END IF
      END DO
      N = K + 1
      CALL GEN038 (WORD, N, L)
      RETURN
      END SUBROUTINE GEN085
 
      REAL FUNCTION GEN086 (A, B, C, M, N)
C * CHECK  SE A=B A MENO DI C
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: M
      REAL :: C
      REAL, DIMENSION(3, 3, *) :: A
      REAL, DIMENSION(3, 3, *) :: B
C * IUM = 1 - TRUE
C * IUM = 0 - FALSE
      GEN086 = 0.0
      DO I = 1, 3
        DO J = 1, 3
          IF (ABS(A (I, J, M) - B(I, J, N)) > C) RETURN
        END DO
      END DO
      GEN086 = 1.0
      RETURN
      END FUNCTION GEN086
 
      SUBROUTINE GEN087 (LINE, B, C, IA, NB)
C * INTERPRETA IL VETTORE  A COME POSIZIONE EQUIVALENTE O
C *  PREPARA LO STESSO PER LA STAMPA A PARTIRE DA B E C
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: K1
      INTEGER :: IA
      INTEGER :: NB
      INTEGER :: LR
      INTEGER :: KM
      INTEGER :: MS
      INTEGER :: MA
      INTEGER :: KM1
      INTEGER :: MCM
      REAL :: CA
      REAL :: COST
      REAL, DIMENSION(3, 3, *) :: B
      REAL, DIMENSION(3, *)    :: C
      CHARACTER(len=23) :: CAR
      CHARACTER(len=*)  :: LINE
      CHARACTER(len=23) :: CARA
      CAR  = '1234567890 /,+-xyz[]XYZ'
      IF (NB == 1) THEN
C * INTERPRETE THE CONTENT OF LINE
        MCM = 1
        LR  = LEN (LINE)
        CALL GEN085 (LINE, LR, KM)
        K    = 1
        COST = 1.0
        DO I = 1, 3
          C(I, IA) = 0.0
          DO J = 1, 3
            B(I, J, IA) = 0.0
          END DO
        END DO
        DO I = 1, KM
C * IDENTIFY CHARACTER
          CARA = LINE(I:I)
          DO J = 1, 23
            IF (CAR(J:J) == CARA) GO TO 10
          END DO
          RETURN
   10     IF (J == 11) THEN
            CYCLE
          ELSE IF (J > 11) THEN
C * ALPHABETICAL CHARACTERS
            IF (J > 20) J = J - 5
            J = J - 11
C * BARRA
            IF (J == 1) THEN
              MCM = 2
C * CAMBIO LINE MATRICE (VIRGOLA)
            ELSE IF (J == 2) THEN
              K = K + 1
C * PLUS TEKEN
            ELSE IF (J == 3) THEN
              COST = 1.0
C * MIN TEKEN
            ELSE IF (J == 4) THEN
              COST = -1.0
            ELSE IF (J == 5) THEN
              B(K, 1, IA) = COST
              COST = 1.0
            ELSE IF (J == 6) THEN
              B(K, 2, IA) = COST
              COST = 1.0
            ELSE IF (J == 7) THEN
              B(K, 3, IA) = COST
              COST = 1.0
            ELSE IF (J == 8) THEN
            ELSE IF (J == 9) THEN
              RETURN
            END IF
            CYCLE
          ELSE
C * NUMERICAL CHARACTER
            IF (J == 10) J = 0
            IF (MCM == 1) THEN
C * NUMERATORE
              IF (C(K, IA) /= 0.0) C(K, IA) = C(K, IA) * 10
              C(K, IA) = C(K, IA) + COST * J
              COST = 1.0
            ELSE IF (MCM == 2) THEN
C * DENOMINATOR
              C(K, IA) = C(K, IA) / J
              MCM = 1
            END IF
          END IF
        END DO
      ELSE IF (NB == 2) THEN
C * SCRITTURA  DEL VETTORE POSIZIONE EQUIVALENTE ALFANUMERICA
        KM = LEN (LINE)
        DO I = 1, KM
          LINE(I:I) = CAR(11:11)
        END DO
        LINE(12:12) = ','
        LINE(23:23) = ','
        DO I = 1, 3
          MCM = 11 * I
          DO J = 1, 3
            L = 4 - J
            IF (NINT (B(I, L, IA)) /= 0) THEN
              MA = L + 15
              LINE(MCM:MCM) = CAR(MA:MA)
              K = 14
              IF (B(I, L, IA) < -0.1) K = 15
              MCM = MCM - 1
              LINE(MCM:MCM) = CAR(K:K)
              MCM = MCM - 1
            END IF
          END DO
          MS = 11
          IF (ABS (C(I, IA)) >= 0.1) THEN
            IF (C(I, IA) < 0.0) MS = 15
            DO J = 1, 6
              CA = C(I, IA) * J
              K = NINT(CA)
              IF (ABS (FLOAT (K) - CA) < 0.1) EXIT
            END DO
            IF (J /= 1) THEN
              LINE(MCM:MCM) = CAR(J:J)
              MCM = MCM - 1
              LINE(MCM:MCM) = CAR(12:12)
              MCM = MCM - 1
            END IF
   20       J = IABS (MOD (K, 10))
            LINE(MCM:MCM) = CAR(J:J)
            K = K / 10
            MCM = MCM - 1
            IF (K > 0) GO TO 20
            LINE(MCM:MCM) = CAR(MS:MS)
          END IF
        END DO
        KM1 = KM - 1
        CALL GEN085 (LINE(2:KM), KM1, K)
        IF (LINE(2:2) == '+') LINE(2:2) = ' '
        DO I = 1, 2
          K = INDEX (LINE, ',+')
          K1 = K + 1
          IF (K /= 0) LINE(K1:K1) = ' '
        END DO
        CALL GEN085 (LINE(2:KM), KM1, K)
      END IF
      RETURN
      END SUBROUTINE GEN087
 
      SUBROUTINE GEN088 (A, I, M, MSIGN, INVERS)
C * GROUP ORDER
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: M1
      INTEGER :: MSIGN
      INTEGER :: INVERS
      REAL :: GEN084
      REAL :: GEN086
      REAL, DIMENSION(3, 3, *) :: A
      REAL, DIMENSION(3, 3)    :: B
      REAL, DIMENSION(3, 3, 2) :: C
C * M     = GROUP ORDER FOR THE MATRIX SIM(I)
C * MSIGN =  1 -   PROPER ROTATION AXIS
C * MSIGN = -1 - IMPROPER ROTATION AXIS
      CALL GEN074 (C, 1, 18, 0.0)
      C(1, 1, 1) =  1.0
      C(2, 2, 1) =  1.0
      C(3, 3, 1) =  1.0
      C(1, 1, 2) = -1.0
      C(2, 2, 2) = -1.0
      C(3, 3, 2) = -1.0
      INVERS     = 2
      MSIGN      = NINT (GEN084 (A, I))
      CALL GEN077  (A, C, B, I, 1, 1)
      DO M = 1, 16
        IF (GEN086 (C, B, 1.E-2, 2, 1) /= 0.0) INVERS = 1
        IF (GEN086 (C, B, 1.E-2, 1, 1) /= 0.0) GO TO 10
        CALL GEN077  (A, B, B, I, 1, 1)
      END DO
   10 IF (M >= 6 .AND. MSIGN /= 1) THEN
        M1 = (M / 4) * 4
        IF (M1 /= M) M = M / INVERS
      END IF
      RETURN
      END SUBROUTINE GEN088
 
      SUBROUTINE GEN089 (LUA, LUB, NPAG, NLM)
C * ADOBE POSTSCRIPT
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: NP
      INTEGER :: NL
      INTEGER :: LUA
      INTEGER :: LUB
      INTEGER :: NLM
      INTEGER :: NPAG
      INTEGER :: IOST = 0
      CHARACTER(len=1)   :: ICH
      CHARACTER(len=132) :: PRBUF
      CHARACTER(len=250) :: PSBUF
      WRITE (LUB, 99999, IOSTAT = IOST) NPAG
      WRITE (LUB, 99998, IOSTAT = IOST)
      NB = 1
      NE = 132
      NP = 0
      NL = NLM
      DO
        READ (LUA, 99995, IOSTAT = IOST) PRBUF
        IF (IOST == -1) EXIT
        IF (PRBUF(1:1) == CHAR (12)) THEN
          BACKSPACE LUA
          READ (LUA, 99994, IOSTAT = IOST) PRBUF
          IF (IOST == -1) CYCLE
          NP = NP + 1
          IF (NP > 1) WRITE (LUB, 99996, IOSTAT = IOST)
          WRITE (LUB, 99997, IOSTAT = IOST) NP, NP
          NL = 0
        END IF
        NL = NL + 1
        IF (NL >= NLM) THEN
          NP = NP + 1
          IF (NP > 1) WRITE (LUB, 99996, IOSTAT = IOST)
          WRITE (LUB, 99997, IOSTAT = IOST) NP, NP
          NL = 1
        END IF
        N = 0
        CALL GEN039 (1, PRBUF, 1, 132, NB, NE)
        DO I = 1, NE
          ICH = PRBUF(I:I)
          IF (ICH /= CHAR (0)) THEN
            IF (ICH == '(' .OR. ICH == ')') THEN
              N = N + 1
              PSBUF(N:N) = CHAR (92)
            END IF
            N = N + 1
            PSBUF(N:N) = ICH
          END IF
        END DO
        WRITE (LUB, 99993, IOSTAT = IOST) PSBUF(1:N)
      END DO
      WRITE (LUB, 99992, IOSTAT = IOST)
      RETURN
99999 FORMAT ('%!PS-Adobe-2.0', /,'%%Creator: PLATON - A.L.Spek', /,
     1  '%%BoundingBox: 0 0 612 792', /, '%%Pages:', I6, /,
     2  '%%PageOrder: Ascend', /, '%%EndComments', /,
     3  '%%BeginSetup', /,
     3  ' /FONT (Courier) cvn def', /,
     4  ' /FONT_SIZE 9.000000 def', /,
     5  ' /XLMARGIN 25 def', /,
     6  ' /XRMARGIN 10 def', /,
     7  ' /YPAGE 612 def', /,
     8  ' /XPAGE 792 def', /,
     9  ' /YTMARGIN 30 def', /,
     *  ' /YBMARGIN 10 def', /,
     1  ' /PAGENUM 1 def', /,
     2  ' /bd {bind def} bind def', /,
     3  ' /m {moveto} bd ', /,
     4  ' /gs {gsave} bd', /,
     5  ' /gr {grestore} bd',
     6  ' /tr {translate} bd', /,
     7  ' /rt {rotate} bd', /,
     8  ' /PAGES_PER_SHEET 1 def')
99998 FORMAT (
     1  ' /sp {/SAVEOBJ save def gs 0 XPAGE tr -90 rt } bd', /,
     2  ' /np { gr showpage SAVEOBJ restore sp bp} bd', /,
     3  ' FONT findfont FONT_SIZE scalefont setfont', /,
     4  ' /FONT_UPPER currentfont', /,
     5  ' /FontBBox get 3 get 0 exch currentfont', /,
     6  ' /FontMatrix get transform exch pop def', /,
     7  ' /FONT_LOWER currentfont', /,
     8  ' /FontBBox get 1 get 0 exch currentfont', /,
     9  ' /FontMatrix get transform exch pop def', /,
     *  ' /FONT_HT  FONT_UPPER FONT_LOWER sub def', /,
     1  ' FONT_HT 0 eq {/FONT_HT FONT_SIZE def } if', /,
     2  ' /FONT_MOVE FONT_SIZE FONT_HT gt {FONT_SIZE def}',
     3  ' {FONT_HT def} ifelse', /,
     4  ' /FONT_TOL FONT_HT YBMARGIN add def', /,
     4  ' /bp { XLMARGIN YPAGE YTMARGIN sub FONT_UPPER sub m } bd', /,
     5  ' /s { show  currentpoint exch pop dup FONT_TOL',
     6  ' gt {FONT_MOVE sub XLMARGIN  exch m} {np} ifelse}  bd', /,
     7  '%%EndSetup', /, 'sp', /, 'bp')
99997 FORMAT ('%%Page:', 2I7)
