99995 FORMAT (A)
99994 FORMAT (1X, A)
99993 FORMAT ('(', A, ')s')
99992 FORMAT ('np', /, '%%EOF')
      END SUBROUTINE GEN089
 
      INTEGER FUNCTION GEN090 (I, J)
C * BITWISE LOGICAL AND
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: I0
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: I3
      I0 = 0
      I1 = I
      I2 = J
      I3 = 1
      N  = 1
   10 IF (MOD (I1, 2) == 1 .AND. MOD (I2, 2) == 1) I0 = I0 + I3
      IF (N < 15) THEN
        N  = N  + 1
        I1 = I1 / 2
        I2 = I2 / 2
        I3 = I3 * 2
        GO TO 10
      END IF
      GEN090 = I0
      RETURN
      END FUNCTION GEN090
 
      SUBROUTINE GEN091 (X, T, KUSER, KUSR, NATO, NAT, ITEM)
C * SORT ARRAY X(*, *) IN ORDER FOR ITEM
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: NAT
      INTEGER :: KUSR
      INTEGER :: NATO
      INTEGER :: ITEM
      INTEGER :: IFIN
      INTEGER :: KUSER
      REAL, DIMENSION(KUSER, KUSR) :: X
      REAL, DIMENSION(KUSR)        :: T
      IF (NAT > 1) THEN
        M = 2
   10   M = 2 * M
        IF (M < NAT) GO TO 10
        M  = MIN0 (NAT, (3 * M) / 4 - 1)
        DO
          M  = M / 2
          IFIN = NAT - M
          DO L = 1, IFIN
            I = L
            J = I + M
            IF (X(NATO + I, ITEM) < X(NATO + J, ITEM)) THEN
              DO K = 1, KUSR
                T(K) = X(NATO + J, K)
              END DO
   20         DO K = 1, KUSR
                X(NATO + J, K) = X(NATO + I, K)
              END DO
              J = I
              I = I - M
              IF (I > 0) THEN
                IF (X(NATO + I, ITEM) < T(ITEM)) GO TO 20
              END IF
              DO K = 1, KUSR
                X(NATO + J, K) = T(K)
              END DO
            END IF
          END DO
          IF (M == 1) EXIT
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN091
 
      SUBROUTINE GEN092 (MODL, H, TM, NUM)
C * TEST LATTICE TYPE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NUM
      INTEGER :: MODL
      REAL :: DM
      REAL, DIMENSION(3)    :: H
      REAL, DIMENSION(3, 3) :: TM
      NUM = 0
      DO J = 1, 3
        DM = 0.0
        DO I = 1, 3
          DM = DM + H(I) * TM(I, J)
        END DO
        NUM = NUM + MOD (NINT (ABS (DM)), MODL)
      END DO
      RETURN
      END SUBROUTINE GEN092
 
      SUBROUTINE GEN093 (IDOF, CSQ, IP)
C * SUBROUTINE RETURNS IP='P>95' FOR CONF HYPOT. WITH P > 0.95
C *                    IP='P<5 ' FOR                  P < 0.5
C *                    IP='    ' FOR      UNDEFINED
      IMPLICIT NONE
      INTEGER :: IDOF
      REAL :: CSQ
      REAL, DIMENSION(20) :: P95 = (/
     1 0.0, 0.1, 0.22, 0.71, 1.15, 1.70, 2.20, 2.70, 3.30, 3.94, 4.50,
     2 5.2, 6.0, 6.6, 7.26, 8.0, 8.65, 9.4, 10.1, 10.85/)
      REAL, DIMENSION(20) :: P5  = (/
     1 3.84, 5.99, 7.81, 9.49, 11.07, 12.5, 14.0, 15.5, 17.0, 18.31,
     2 19.8, 21.0, 22.2, 23.75, 25.0, 26.2, 27.5, 29.0, 30.2, 31.41/)
      CHARACTER(len=4) :: IP
      IP = '    '
      IF (IDOF <= 20 .AND. IDOF > 0) THEN
        IF (CSQ <= P95(IDOF)) IP = 'P>95'
        IF (CSQ > P5(IDOF))  IP = 'P<5 '
      END IF
      RETURN
      END SUBROUTINE GEN093
 
      SUBROUTINE GEN094 (X, V, IDEV, IDUM)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IDEV
      INTEGER :: IDUM
      REAL :: DM
      REAL, DIMENSION(3, 3) :: X
      REAL, DIMENSION(3)    :: V
C * TEST LATTICE TYPE
      IDUM = 0
      DO J = 1, 3
        DM = 0.0
        DO I = 1, 3
          DM = DM + X(I, J) * V(I)
        END DO
        IDUM = IDUM + MOD (NINT (ABS (DM)), IDEV)
      END DO
      RETURN
      END SUBROUTINE GEN094
 
      REAL FUNCTION GEN095 (P, IH, IK, IL)
C * CALCULATE (SIN(THETA) / LAMBDA)**2
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      REAL, DIMENSION(6) :: P
      GEN095 = 0.25 * (IH**2 * P(1) + IK**2 * P(2)
     1       + IL**2 * P(3) + 2.0 * (IK * IL * P(4)
     2       + IH * IL * P(5) + IH * IK * P(6)))
      RETURN
      END FUNCTION GEN095
 
      SUBROUTINE GEN096 (T, IROTX, IROTY, IROTZ, IDET, U, PHI, ROM)
C * MAP THE NINE ELEMENTS OF T INTO ROTX, ROTY, ROTZ, IDET
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      INTEGER :: IDET
      REAL :: AL
      REAL :: BE
      REAL :: GA
      REAL :: RTD
      REAL :: PHI
      REAL :: T11A
      REAL :: T12A
      REAL :: T22A
      REAL :: T32A
      REAL :: XLNG
      REAL :: XNORM
      REAL :: COSPH
      REAL :: TEKEN
      REAL, DIMENSION(3, 3) :: T
      REAL, DIMENSION(3, 3) :: ROM
      REAL, DIMENSION(3)    :: U
      REAL, DIMENSION(3)    :: V
      REAL, DIMENSION(15)   :: Z
      CALL GEN010 (T, IDET, 0)
      RTD = 0.0
      AL  = 0.0
      BE  = 0.0
      GA  = 0.0
      IF (IDET /= 0) THEN
        CALL GEN010 (T, IDET, -1)
        RTD = 45.0 / ATAN (1.0)
        IF (ABS (T(1, 1)) + ABS (T(2, 1)) > 0.00001)
     1    GA = ATAN2(T(2, 1), T(1, 1))
        T11A =   T(1, 1)  * COS (GA) + T(2, 1) * SIN (GA)
        T12A =   T(1, 2)  * COS (GA) + T(2, 2) * SIN (GA)
        T22A =  -T(1, 2)  * SIN (GA) + T(2, 2) * COS (GA)
        IF (ABS (T(3, 1)) + ABS (T11A) > 0.00001)
     1    BE = ATAN2 (-T(3, 1), T11A)
        T32A = SIN (BE) * T12A + COS (BE) * T(3, 2)
        IF (ABS (T32A) + ABS (T22A) > 0.00001)
     1    AL = ATAN2 (T32A, T22A)
C * DETERMINE EQUIVALENT VIEW DIRECTION AND SUBSEQUENT Z-ROTATION
        DO I = 1, 3
          V(I)      = T(3, I)
          Z(6 + I)  = T(3, I)
          Z(I + 9)  = T(2, I)
          Z(I + 12) = 0.0
        END DO
        IF (ABS (Z(8)) > 0.9999) THEN
          Z(13) = 1.0
        ELSE
          Z(14) = 1.0
        END IF
        CALL GEN008 (Z(13), Z(7), Z(1), 1)
        CALL GEN008 (Z(7), Z(1), Z(4), 1)
        COSPH = MAX (MIN (1.0, Z(4) * Z(10) + Z(5) * Z(11)
     1      + Z(6) * Z(12)), -1.0)
        CALL GEN008 (Z(4), Z(10), Z(13), 1)
        TEKEN = Z(7) * Z(13) + Z(8) * Z(14) + Z(9) * Z(15)
        PHI = SIGN (ACOS (COSPH) * RTD, TEKEN)
        CALL GEN002 (1, ROM, V, U, XLNG)
C * SCALE ABSOLUTE VALUE OF LARGEST COMPONENT OF DIRECTION VECTOR TO 1.0
        XNORM = MAX (ABS (U(1)), ABS (U(2)), ABS (U(3)))
        IF (XNORM /= 0.0) THEN
          DO I = 1, 3
            U(I) = U(I) / XNORM
          END DO
        END IF
C * RESTORE T - MATRIX
        CALL GEN010 (T, IDET, -1)
      END IF
      IROTX = - NINT (AL * RTD)
      IROTY = - NINT (BE * RTD)
      IROTZ = - NINT (GA * RTD)
      RETURN
      END SUBROUTINE GEN096
 
      SUBROUTINE GEN097 (IA, N1, N2, IVALUE)
C * SET INTEGER ARRAY ON VALUE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: IVALUE
      INTEGER, DIMENSION(*) :: IA
      DO I = N1, N2
        IA(I) = IVALUE
      END DO
      RETURN
      END SUBROUTINE GEN097
 
      SUBROUTINE GEN098 (M, X, N, ITX, ITY, ITZ, IRES)
C * SPLIT-UP ARU CODE IN COMPONENTS
      IMPLICIT NONE
      INTEGER :: M
      INTEGER :: N
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: IRES
      INTEGER :: IARU
      INTEGER :: MABS
      REAL :: X
      IARU = NINT (X)
      MABS = IABS (M)
      ITX  = MOD (MABS / (100 * IARU), 10) - 5
      ITY  = MOD (MABS / (10  * IARU), 10) - 5
      ITZ  = MOD (MABS / IARU,         10) - 5
      IRES = MOD (MABS,  IARU)
      N    = MABS / (1000 * IARU)
      RETURN
      END SUBROUTINE GEN098
 
      SUBROUTINE GEN099 (A, B, C)
C * FORM QUADRATIC FORM
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(3, 3) :: C
      REAL, DIMENSION(3)    :: B
      DO I = 1, 3
        DO J = 1, 3
          C(I, J) = 0.0
          DO K = 1, 3
            C(I, J) = C(I, J) + A(I, K) * A(J, K) * B(K)
          END DO
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN099
 
      SUBROUTINE GEN100 (AO, J, X, Y, Z)
C * TLS MATRIX
      IMPLICIT NONE
      INTEGER :: J
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL, DIMENSION(20) :: AO
      CALL GEN074 (AO, 1, 20, 0.0)
      IF (J == 1) THEN
        AO(4)  =   Z * Z
        AO(6)  =   Y * Y
        AO(5)  = - 2 * Y * Z
        AO(19) = - 2 * Y
        AO(16) =   2 * Z
        AO(7)  =   1.0
      ELSE IF (J == 2) THEN
        AO(6)  = - X * Y
        AO(5)  =   X * Z
        AO(3)  =   Y * Z
        AO(2)  = - Z * Z
        AO(13) = - Z
        AO(17) =   Z
        AO(19) =   X
        AO(20) = - Y
        AO(8)  =   1.0
      ELSE IF (J == 3) THEN
        AO(4)  = - X * Z
        AO(5)  =   X * Y
        AO(3)  = - Y * Y
        AO(2)  =   Y * Z
        AO(13) =   2 * Y
        AO(17) =   Y
        AO(18) =   Z
        AO(16) = - X
        AO(9)  =   1.0
      ELSE IF (J == 4) THEN
        AO(1)  =   Z * Z
        AO(6)  =   X * X
        AO(3)  = - 2 * X * Z
        AO(14) = - 2 * Z
        AO(20) =   2 * X
        AO(10) =   1.0
      ELSE IF (J == 5) THEN
        AO(1)  = - Y * Z
        AO(5)  = - X * X
        AO(3)  =   X * Y
        AO(2)  =   X * Z
        AO(13) = - X
        AO(17) = - 2 * X
        AO(14) =   Y
        AO(15) = - Z
        AO(11) =   1.0
      ELSE IF (J == 6) THEN
        AO(1)  =   Y * Y
        AO(4)  =   X * X
        AO(2)  = - 2 * X * Y
        AO(18) = - 2 * X
        AO(15) =   2 * Y
        AO(12) =   1.0
      END IF
      RETURN
      END SUBROUTINE GEN100
 
      SUBROUTINE GEN101 (M, N, DHX)
C * GENERATE INDEX COMBINATIONS
      IMPLICIT NONE
      INTEGER :: M
      INTEGER :: N
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: I1
      INTEGER :: I3
      INTEGER :: I4
      INTEGER :: I5
      INTEGER :: J1
      INTEGER :: J3
      INTEGER :: J4
      INTEGER :: J5
      INTEGER :: K1
      INTEGER :: K3
      INTEGER :: K4
      INTEGER :: K5
      INTEGER :: NN
      INTEGER :: IJK
      REAL, DIMENSION(3, *) :: DHX
      N  = 3
      DO I = 0, M
        I1 = MOD (I, 2)
        I3 = MOD (I, 3)
        I4 = MOD (I, 5)
        I5 = MOD (I, 7)
        J  = - M -1
        DO
          J  = J + 1
          IF (J > M) EXIT
          J1 = MOD (J, 2)
          J3 = MOD (J, 3)
          J4 = MOD (J, 5)
          J5 = MOD (J, 7)
          K  = -M -1
          DO
            K  = K + 1
            IF (K > M) EXIT
            K1 = MOD (K, 2)
            K3 = MOD (K, 3)
            K4 = MOD (K, 5)
            K5 = MOD (K, 7)
            IF (I * J * K == 0) THEN
              IF (ABS (I1) + ABS (J1) + ABS (K1) == 0) CYCLE
              IF (ABS (I3) + ABS (J3) + ABS (K3) == 0) CYCLE
              IF (ABS (I4) + ABS (J4) + ABS (K4) == 0) CYCLE
              IF (ABS (I5) + ABS (J5) + ABS (K5) == 0) CYCLE
              IF (I < 0) THEN
                CYCLE
              ELSE IF (I == 0) THEN
                IF (J < 0) THEN
                  CYCLE
                ELSE IF (J == 0) THEN
                  IF (K < 0) CYCLE
                END IF
              END IF
            ELSE
              IF (ABS (I1) + ABS (J1) == 0) CYCLE
              IF (ABS (I1) + ABS (K1) == 0) CYCLE
              IF (ABS (J1) + ABS (K1) == 0) CYCLE
              IF (ABS (I3) + ABS (J3) == 0) CYCLE
              IF (ABS (I3) + ABS (K3) == 0) CYCLE
              IF (ABS (J3) + ABS (K3) == 0) CYCLE
              IF (ABS (I4) + ABS (J4) == 0) CYCLE
              IF (ABS (I4) + ABS (K4) == 0) CYCLE
              IF (ABS (J4) + ABS (K4) == 0) CYCLE
              IF (ABS (I5) + ABS (J5) == 0) CYCLE
              IF (ABS (I5) + ABS (K5) == 0) CYCLE
              IF (ABS (J5) + ABS (K5) == 0) CYCLE
            END IF
C * PUT 1,0,0 0,1,0 and 0,0,1 up-front
            IJK = I * 10000 + J * 100 + K
            IF (IJK == 10000) THEN
              NN = 1
            ELSE IF (IJK == 100) THEN
              NN = 2
            ELSE IF (IJK == 1) THEN
              NN = 3
            ELSE
              N  = N + 1
              NN = N
            END IF
            DHX(1, NN) = I
            DHX(2, NN) = J
            DHX(3, NN) = K
          END DO
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN101
 
      SUBROUTINE GEN102 (IS, KEY, SWS, NM)
C * TRANSFORM KEYWORD TO ENTRYPOINT NUMBER IN ARRAY
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: IS
      INTEGER :: NM
      CHARACTER(len=4), DIMENSION(*) :: SWS
      CHARACTER(len=4)               :: KEY
      IS = 1
      DO N = 1, NM
        IF (KEY == SWS(N)) THEN
          IS = N + 1
          EXIT
        END IF
      END DO
      RETURN
      END SUBROUTINE GEN102
 
      SUBROUTINE GEN103 (LINE, N)
C * COMPACT LINE TO ONE BLANK SEPARATOR
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NBL
      CHARACTER(len=*) :: LINE
      CHARACTER(len=1) :: ICH
      M   = 0
      NBL = 1
      DO I = 1, N
        ICH = LINE(I:I)
        IF (ICH == ' ') THEN
          NBL = NBL + 1
          IF (NBL == 1) THEN
            M = M + 1
            LINE(M:M) = ICH
          ELSE
            CYCLE
          END IF
        ELSE
          M   = M + 1
          NBL = 0
          LINE(M:M) = ICH
        END IF
      END DO
      M = M + 1
      IF (M <= N) CALL GEN038 (LINE, M, N)
      RETURN
      END SUBROUTINE GEN103
 
 
      SUBROUTINE GEN104 (LAT, C, A)
C * CHECK FOR TRIVIAL TRANSFORMATIONS
      USE genrl
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: LAT
      REAL :: DET
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(3, 3) :: B
      REAL, DIMENSION(3, 3) :: C
C * LAT = 1 TRICLINIC
C * LAT = 2 MONOCLINIC
C * LAT = 3 ORTHORHOMBIC
C * LAT = 4 TETRAGONAL
C * LAT = 5 TRIGONAL/RHOMBOHEDRAL
C * LAT = 6 HEXAGONAL
C * LAT = 7 CUBIC
C * UNIT MATRIX
      CALL GEN021 (A, 1.0)
C * INVERT
      CALL GEN003 (C, B, DET, 0)
      IF (ABS (DET - 1.0) < 0.001 .AND. LAT > 1) THEN
        N1 = NINT (C(1, 1)) * 100 + NINT (C(1, 2)) * 10 + NINT (C(1, 3))
     1     + 111
        N2 = NINT (C(2, 1)) * 100 + NINT (C(2, 2)) * 10 + NINT (C(2, 3))
     1     + 111
        N3 = NINT (C(3, 1)) * 100 + NINT (C(3, 2)) * 10 + NINT (C(3, 3))
     1     + 111
        DO I = 1, 30
          IF (IT (LAT + 2, I) /= 0) THEN
            IF (N1 == IT(1, I) .AND. N2 == IT(2, I) .AND.
     1          N3 == IT(3, I)) THEN
C * COPY
              CALL GEN052 (B, A)
C * UNIT MATRIX
              CALL GEN021 (C, 1.0)
              RETURN
            END IF
          END IF
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN104
 
      SUBROUTINE GEN105 (MODE, ICH, N)
C * MODE = 1 - SEARCH FOR UPPER CASE CHAR
C * MODE = 2 - SEARCH FOR LOWER CASE CHAR
C * MODE = 3 - SEARCH FOR NUMERAL
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER:: MODE
      CHARACTER(len=1) :: ICH
      N = - 1
C * CHECK FOR UPPER CASE
      IF (MODE == 1) THEN
        DO I = ICHAR ('A'), ICHAR ('Z')
          IF (ICH == CHAR (I)) THEN
            N = I
            EXIT
          END IF
        END DO
C * CHECK FOR LOWER CASE
      ELSE IF (MODE == 2) THEN
        DO I = ICHAR ('a'), ICHAR ('z')
          IF (ICH == CHAR (I)) THEN
            N = I
            EXIT
          END IF
        END DO
C * CHECK FOR NUMERAL
      ELSE IF (MODE == 3) THEN
        DO I = 1, 10
          IF (ICH == CHAR (ICHAR ('0') - 1 + I)) THEN
            N = I
            EXIT
          END IF
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN105
 
      SUBROUTINE GEN106 (V, STH, PSI, AA, BB, V6, V8, PAR)
C * SUBROUTINE CONVERTS PSI(H.FLACK) TO DIRECTION COSINES (SHELDRICK)
      IMPLICIT NONE
      INTEGER :: K
      REAL :: STH
      REAL :: CTH
      REAL :: PSI
      REAL :: XLNG
      REAL, DIMENSION(3)    :: V
      REAL, DIMENSION(3)    :: V1
      REAL, DIMENSION(3)    :: V2
      REAL, DIMENSION(3)    :: V3
      REAL, DIMENSION(3)    :: V4
      REAL, DIMENSION(3)    :: V6
      REAL, DIMENSION(3)    :: V8
      REAL, DIMENSION(3, 3) :: AA
      REAL, DIMENSION(3, 3) :: BB
      REAL, DIMENSION(6)    :: PAR
      CTH = SQRT(1.0 - STH**2)
C * GET NORMALIZED CONTRAVARIANT COMPONENTS OF HKL
      CALL GEN002 (-1, BB, V, V6, XLNG)
      CALL GEN007 (AA, V6, V1, -1)
C * FIND VECTOR PERPENDICULAR TO HKL
      IF (V(1) == V(2) .AND. V(2) == V(3)) THEN
        V6(1) =   V(1)
        V6(2) = - V(1)
        V6(3) =   0.0
      ELSE
        V6(1) = V(2) - V(3)
        V6(2) = V(3) - V(1)
        V6(3) = V(1) - V(2)
      END IF
C * NORMALIZE V6
      CALL GEN007 (AA, V6, V2, -1)
C * MAKE NORMALISED VECTOR V1 X V2
      CALL GEN008 (V1, V2, V6, 0)
      CALL GEN002 (-1, BB, V6, V8, XLNG)
      CALL GEN007 (AA, V8, V3, -1)
C * GET VECTOR PERPENDICULAR TO HKL IN DIFFRACTION PLANE
      DO K = 1, 3
        V4(K) =  V3(K) * COS (PSI) + V2(K) * SIN (PSI)
        V6(K) = (V1(K) * STH + V4(K) * CTH) / PAR(K)
        V8(K) = (V1(K) * STH - V4(K) * CTH) / PAR(K)
      END DO
      RETURN
      END SUBROUTINE GEN106
 
      SUBROUTINE GEN107 (IA, N, M)
C * REDUCE VECTOR
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: M
      INTEGER :: MN
      INTEGER, DIMENSION(*) :: IA
      M  = 1
      MN = 99999
      DO I = 1, N
        IF (IA(I) > 0) MN = MIN (MN, IA(I))
      END DO
      DO 10 I = 1, MN
        M = MN + 1 - I
        DO J = 1, N
          IF (MOD (IA(J), M) /= 0) GOTO 10
        END DO
        DO J = 1, N
          IA(J) = IA(J) / M
        END DO
        EXIT
   10 CONTINUE
      RETURN
      END SUBROUTINE GEN107
 
      SUBROUTINE GEN108 (LU, MODE)
C * REWIND/ENDFILE
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: MODE
      INTEGER :: IOST
      CHARACTER(len=80) :: LINE
      IF (MODE /= 0) THEN
        ENDFILE (LU, IOSTAT = IOST)
        IF (IOST /= 0) THEN
          WRITE (LINE, 99998) LU
          CALL TRAILER (LINE)
          RETURN
        END IF
      END IF
      REWIND (LU, IOSTAT = IOST)
      IF (IOST /= 0) THEN
        WRITE (LINE, 99999) LU
        CALL TRAILER (LINE)
      END IF
      RETURN
99999 FORMAT ('W: REWIND  PROBLEM FOR UNIT ', I5)
99998 FORMAT ('W: ENDFILE PROBLEM FOR UNIT ', I5)
      END SUBROUTINE GEN108
 
      SUBROUTINE GEN109 (M, N, X, Y, Z, F, NP)
C * Generates spherical harmonic functions in terms of orthogonal
C * direction cosines up to odd order M and even order N.  X,Y,Z are
C * the direction cosines and the functions are returned in F(1..NP).
C * The functions have not been normalized
      IMPLICIT NONE
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NP
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: U
      REAL :: V
      REAL :: W
      REAL :: Q
      REAL :: T
      REAL :: XX
      REAL :: YY
      REAL :: ZZ
      REAL :: XY
      REAL :: XZ
      REAL :: YZ
      DOUBLE PRECISION, DIMENSION(81) :: F
      XX = X**2
      YY = Y**2
      ZZ = Z**2
      XY = X * Y
      XZ = X * Z
      YZ = Y * Z
      U  = XX - YY
      V  = 3.0 * XX - YY
      W  = XX - 3.0 * YY
      T  = XX * (XX - 6.0 * YY) + YY**2
      NP = 0
C * EVEN TERMS
      IF (N >= 2) THEN
        NP   = 5
        F(1) = 1.5 * ZZ - 0.5
        F(2) = 3.0 * XZ
        F(3) = 3.0 * YZ
        F(4) = 3.0 * U
        F(5) = 6.0 * XY
        IF (N >= 4) THEN
          NP    = 14
          F(6)  = ZZ     * (4.375 * ZZ -3.75) + 0.375
          F(7)  = XZ     * (17.5 * ZZ -7.5)
          F(8)  = YZ     * (17.5 * ZZ -7.5)
          F(9)  = (52.5  * ZZ - 7.5) * U
          F(10) = (105.0 * ZZ - 15.0) * XY
          F(11) = 105.0  * XZ * W
          F(12) = 105.0  * YZ * V
          F(13) = 105.0  * T
          F(14) = 420.0  * XY * U
          IF (N >= 6) THEN
            NP    = 27
            F(15) = ZZ * (ZZ * (14.4375 * ZZ - 19.6875) + 6.5625)
     1            - 0.3125
            F(16) = XZ * (ZZ * (86.625 * ZZ - 78.75) + 13.125)
            F(17) = YZ * (ZZ * (86.625 * ZZ - 78.75) + 13.125)
            F(18) = (ZZ * (433.125 * ZZ - 236.25) + 13.125) * U
            F(19) = (ZZ * (866.25 * ZZ - 472.5) + 26.25) * XY
            F(20) = XZ * (1732.5 * ZZ - 472.5) * W
            F(21) = YZ * (1732.5 * ZZ - 472.5) * V
            F(22) = (5197.5 * ZZ - 472.5) * T
            F(23) = XY * (20790.0 * ZZ - 1890.0) * U
            F(24) = 10395.0 * XZ * (XX * (XX - 10.0 * YY)
     1            + 5.0 * YY**2)
            F(25) = 10395.0 * YZ * (XX * (5.0 * XX - 10.0 * YY)
     1            + YY**2)
            F(26) = 10395.0 * (XX * (XX * (XX - 15.0) * YY
     1            + 15.0 * YY**2) - YY**3)
            F(27) = 62370.0 * XY * (XX * (XX - 3.333333 * YY) + YY**2)
            IF (N >= 8) THEN
              NP    = 44
              F(28) = (((50.2734375 * ZZ - 93.84375) * ZZ
     1              + 54.140625) * ZZ - 9.84375) * ZZ + 0.2734375
              Q     = ((402.1875 * ZZ - 563.0625) * ZZ
     1              + 216.5625) * ZZ - 19.6875
              F(29) = XZ * Q
              F(30) = YZ * Q
              Q     = ((2815.3125 * ZZ - 2815.3125) * ZZ
     1              + 649.6875) * ZZ - 19.6875
              F(31) = U * Q
              F(32) = 2.0 * XY * Q
              Q     = (16891.875 * ZZ - 11261.25) * ZZ + 1299.375
              F(33) = XZ * Q * W
              F(34) = YZ * Q * V
              Q     = (84459.375 * ZZ - 33783.75) * ZZ + 1299.375
              F(35) = Q * T
              F(36) = 4.0 * XY * Q * U
              Q     = 337837.5 * ZZ - 67567.5
              F(37) = XZ * Q * (XX * (XX - 10.0 * YY) + 5.0 * YY**2)
              F(38) = YZ * Q * (XX * (5.0 * XX - 10.0 * YY) + YY**2)
              Q     = 1013512.5 * ZZ - 67567.5
              F(39) = Q * (XX * (XX * (XX - 15.0 * YY)
     1              + 15.0 * YY**2) - YY**3)
              F(40) = Q * XY * (XX * (6.0 * XX - 20.0 * YY)
     1              + 6.0 * YY**2)
              F(41) = 2027025.0 * XZ * (XX * (XX * (XX - 21.0 *YY)
     1              + 35.0 * YY**2) - 7.0 * YY**3)
              F(42) = 2027025.0 * YZ * (XX * (XX * (7.0 * XX
     1              - 35.0 * YY) + 21.0 * YY**2) - YY**3)
              F(43) = 2027025.0 * (XX * (XX * (XX * (XX - 28.0 * YY)
     1              + 70.0 * YY**2) - 28.0 * YY**3) + YY**4)
              F(44) = 16216200.0 * XY * (XX * (XX * (XX - 7.0 * YY)
     1              + 7.0 * YY**2) - YY**3)
            END IF
          END IF
        END IF
      END IF
C * ODD TERMS
      IF (M >= 1) THEN
        NP        = NP + 3
        F(NP - 2) = Z
        F(NP - 1) = X
        F(NP)     = Y
        IF (M >= 3) THEN
          NP        = NP + 7
          F(NP - 6) = Z * (2.5 * ZZ - 1.5)
          Q         = 7.5 * ZZ - 1.5
          F(NP - 5) = X * Q
          F(NP - 4) = Y * Q
          F(NP - 3) = 15.0 * Z * U
          F(NP - 2) = 30.0 * X * YZ
          F(NP - 1) = 15.0 * X * W
          F(NP)     = 15.0 * Y * V
          IF (M >= 5) THEN
            NP         = NP + 11
            F(NP - 10) = Z * (ZZ * (ZZ * 7.875 - 8.75) + 1.875)
            Q          = ZZ * (39.375 * ZZ - 26.25) + 1.875
            F(NP -  9) = X * Q
            F(NP -  8) = Y * Q
            Q          = Z * (157.5 * ZZ - 52.5)
            F(NP -  7) = Q * U
            F(NP -  6) = 2.0 * Q * XY
            Q          = 472.5 * ZZ - 52.5
            F(NP -  5) = Q * X * W
            F(NP -  4) = Q * Y * V
            F(NP -  3) = 945.0 * Z * T
            F(NP -  2) = 3780.0 * Z * XY * U
            F(NP -  1) = 945.0 * X * (XX * (XX - 10.0 * YY)
     1                 + 5.0 * YY**2)
            F(NP)      = 945.0 * Y * (XX * (5.0 * XX - 10.0 * YY)
     1                 + YY**2)
            IF (M >= 7) THEN
              NP         = NP + 15
              F(NP - 14) = Z * (ZZ * (ZZ * (ZZ * 26.8125 - 43.3125)
     1                   + 19.6875) - 2.1875)
              Q          = ZZ * (ZZ * (ZZ * 187.6875 - 216.5625)
     1                   + 59.0625) - 2.1875
              F(NP - 13) = X * Q
              F(NP - 12) = Y * Q
              Q          = Z * (ZZ * (ZZ * 1126.125 - 866.25)
     1                   + 118.125)
              F(NP - 11) = Q * U
              F(NP - 10) = 2.0 * XY * Q
              Q          = ZZ * (ZZ * 5630.625 - 2598.75) + 118.125
              F(NP -  9) = Q * X * W
              F(NP -  8) = Q * Y * V
              Q          = Z * (22522.5 * ZZ - 5197.5)
              F(NP -  7) = Q * T
              F(NP -  6) = 4.0 * Q * XY * U
              Q          = 67567.5 * ZZ - 5197.5
              F(NP -  5) = Q * X * (XX * (XX - 10.0 *YY) + 5.0 * YY**2)
              F(NP -  4) = Q * Y * (XX * (5.0 * XX -10.0 * YY) + YY**2)
              F(NP -  3) = 135135.0 * Z * (XX * (XX * (XX - 15.0 * YY)
     1                   + 15.0 * YY**2) - YY**3)
              F(NP -  2) = 810810.0 * Z * XY * (XX * (XX
     1                   - 3.333333 * YY)
     1               + YY**2)
              F(NP -  1) = 135135.0 * X * (XX * (XX * (XX - 21.0 * YY)
     1                   + 35.0 * YY**2) - 7.0 * YY**3)
              F(NP)      = 135135.0 * Y * (XX * (XX * (7.0 * XX
     1                   - 35.0 * YY) + 21.0 * YY**2) - YY**3)
            END IF
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN109
 
      SUBROUTINE GEN110 (NP, NN, C, B)
C * Cholesky factorization
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NP
      INTEGER :: NN
      INTEGER :: NI
      DOUBLE PRECISION :: DT
      DOUBLE PRECISION, DIMENSION(NP) :: C
      DOUBLE PRECISION, DIMENSION(NN) :: B
C * Invert lower triangular matrix B and multiply by vector C.
C * NN should be NP*(NP+1) where NP is the number of l.s. parameters.
      M = 0
      I = 0
      DO N = 1, NP
        I = I + 1
        L = I
        M = 1
        J = 1
  10    IF (J /= I) THEN
          B(I) = B(I) * B(J)
          C(N) = C(N) - B(I) * C(M)
          M    = M + 1
          NI   = I
          I    = I + 1
          J    = J + 1
          DT   = B(I)
          DO K = L, NI
            DT = DT - B(J) * B(K)
            J  = J  + 1
          END DO
          B(I) = DT
          GO TO 10
        END IF
        B(I) = 1.0 / DSQRT (B(I))
        C(N) = C(N) * B(I)
      END DO
C * Calculate and add shifts
      DT   = C(M)
  20  C(M) = DT * B(I)
      I    = I - M
      M    = M - 1
      IF (M < 1) RETURN
      DT   = C(M)
      K    = I + M
      DO N = M + 1, NP
        DT = DT - C(N) * B(K)
        K  = K  + N
      END DO
      GO TO 20
      RETURN
      END SUBROUTINE GEN110
 
      SUBROUTINE GEN111 (A, B, N, M)
C * MANIPULATE CHEMICAL FORMULA
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: KMOVE
      CHARACTER(len=*) :: A
      CHARACTER(len=2) :: B
      B = ' '
      M = 0
      L = 0
      DO 10 J = 1, N
        DO K = 48, 122
          IF (A(J:J) == CHAR(K)) THEN
            IF (K < 58) THEN
              M = M * 10 + K - 48
              GO TO 10
            ELSE IF (K > 64) THEN
              IF (L < 2) THEN
                IF (K > 96) THEN
                  KMOVE = 32
                ELSE
                  KMOVE = 0
                END IF
                L = L + 1
                B(L:L) = CHAR(K - KMOVE)
              END IF
            END IF
          END IF
        END DO
  10  CONTINUE
      RETURN
      END SUBROUTINE GEN111
 
      SUBROUTINE GEN112 (A, B, MODE)
C * CONVERT 3*3 MATRIX to 9 VECTOR AND REVERSE
      IMPLICIT NONE
      INTEGER :: MODE
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(*)    :: B
      IF (MODE > 0) THEN
        A(1, 1) = B(1)
        A(1, 2) = B(2)
        A(1, 3) = B(3)
        A(2, 1) = B(4)
        A(2, 2) = B(5)
        A(2, 3) = B(6)
        A(3, 1) = B(7)
        A(3, 2) = B(8)
        A(3, 3) = B(9)
      ELSE
        B(1) = A(1, 1)
        B(2) = A(1, 2)
        B(3) = A(1, 3)
        B(4) = A(2, 1)
        B(5) = A(2, 2)
        B(6) = A(2, 3)
        B(7) = A(3, 1)
        B(8) = A(3, 2)
        B(9) = A(3, 3)
      END IF
      RETURN
      END SUBROUTINE GEN112
 
      SUBROUTINE GEN113 (A, B, N)
C * COPY VECTOR WITH N ELEMENTS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      REAL, DIMENSION(*) :: A
      REAL, DIMENSION(*) :: B
      DO I = 1, N
        B(I) = A(I)
      END DO
      RETURN
      END SUBROUTINE GEN113
 
      SUBROUTINE GEN114 (PAR, OR, UIJ, UIL, DUMA, RIK, UEQ)
C * GET MAIN AXES AND VALUES OF UIJ TENSOR
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      REAL :: UEQ
      REAL :: DET
      REAL :: SUMX
      REAL, DIMENSION(*)    :: PAR
      REAL, DIMENSION(6)    :: DUMA
      REAL, DIMENSION(3, 3) :: OR
      REAL, DIMENSION(3, 3) :: ROR
      REAL, DIMENSION(3, 3) :: UIJ
      REAL, DIMENSION(3, 3) :: RIK
      REAL, DIMENSION(3, 3) :: RLJ
      REAL, DIMENSION(3, 3) :: UKL
      REAL, DIMENSION(3, 3) :: UIL
      CALL GEN003 (OR, ROR, DET, 0)
      DO K = 1, 3
        DO L = 1, 3
          RLJ(K, L) = 0.0
          IF (K == L) RLJ(K, K) = PAR(112 + K)
        END DO
      END DO
      CALL GEN004 (OR, RLJ, UKL)
      CALL GEN001 (1, UKL, UIJ, UIL)
C * GET EIGENVECTOR AND VALUES
      CALL GEN024 (UIL, RIK, DUMA, RLJ)
C * SWAP 1 & 3
      CALL GEN018 (DUMA(1), DUMA(3))
      CALL GEN018 (RLJ(1, 1), RLJ(1, 3))
      CALL GEN018 (RLJ(2, 1), RLJ(2, 3))
      CALL GEN018 (RLJ(3, 1), RLJ(3, 3))
      CALL GEN004 (ROR, RLJ, RIK)
      DO J = 1, 3
        SUMX = SQRT (RIK(1, J)**2 + RIK(2, J)**2 + RIK(3, J)**2)
        RIK(1, J) = RIK(1, J) / SUMX
        RIK(2, J) = RIK(2, J) / SUMX
        RIK(3, J) = RIK(3, J) / SUMX
      END DO
      UEQ = (DUMA(1) + DUMA(2) + DUMA(3)) / 3.0
      RETURN
      END SUBROUTINE GEN114
 
      SUBROUTINE GEN115 (X, W, N)
C * GAUSSIAN INTEGRATION COEFFICIENTS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: M
      REAL, DIMENSION(*) :: X
      REAL, DIMENSION(*) :: W
      DOUBLE PRECISION :: Z
      DOUBLE PRECISION :: Z1
      DOUBLE PRECISION :: P1
      DOUBLE PRECISION :: P2
      DOUBLE PRECISION :: P3
      DOUBLE PRECISION :: PP
      DOUBLE PRECISION :: XM
      DOUBLE PRECISION :: XL
      M  = (N + 1) / 2
      XM = 0.5D0
      XL = 0.5D0
      DO I = 1, M
        Z = COS (3.141592654D0 * (I - 0.25D0) / (N + 0.5D0))
   10   CONTINUE
        P1 = 1.D0
        P2 = 0.D0
        DO J = 1, N
          P3 = P2
          P2 = P1
          P1 = ((2.0D0 * J - 1.0D0) * Z * P2 - (J - 1.0D0) * P3) / J
        END DO
        PP = N * (Z * P1 - P2) / (Z * Z - 1.0D0)
        Z1 = Z
        Z  = Z1 - P1 / PP
        IF (ABS (Z - Z1) > 3.0D-14) GO TO 10
        X(I)         = REAL (XM - XL * Z)
        X(N + 1 - I) = REAL (XM + XL * Z)
        W(I)         = REAL (2.D0 * XL / ((1.0D0 - Z * Z) * PP * PP))
        W(N + 1 - I) = W(I)
      END DO
      RETURN
      END SUBROUTINE GEN115
 
      SUBROUTINE GEN116 (MODE, Y, W, N, GRAPH, LU)
C * MODE = 1: SUBROUTINE GENERATES A HALFNORMAL PROBABILITY PLOT.
C * MODE = 2: SUBROUTINE GENERATES A NORMAL (GAUSSIAN) PROBABILITY PLOT
C * THE PROTOTYPE HALFNORMAL DISTRIBUTION USED HEREIN
C * HAS MEAN = SQRT(2/PI) = 0.79788456 AND STANDARD DEVIATION = 1.
C * THIS DISTRIBUTION IS DEFINED FOR ALL NON-NEGATIVE X AND HAS THE
C * PROBABILITY DENSITY FUNCTION F(X) = (2/SQRT(2*PI)) * EXP(-X*X/2).
C * THE PROTOTYPE HALFNORMAL DISTRIBUTION USED HEREIN IS THE DISTRIBUTION
C * OF THE VARIATE X = ABS(Z) WHERE THE VARIATE Z IS NORMALLY DISTRIBUTED
C * WITH MEAN = 0 AND STANDARD DEVIATION = 1. AS USED HEREIN, A PROBABILITY
C * PLOT FOR A DISTRIBUTION IS A PLOT OF THE ORDERED OBSERVATIONS VERSUS
C * THE ORDER STATISTIC MEDIANS FOR THAT DISTRIBUTION. THE HALFNORMAL
C * PROBABILITY PLOT IS USEFUL IN GRAPHICALLY TESTING THE COMPOSITE (THAT IS,
C * LOCATION AND SCALE PARAMETERS NEED NOT BE SPECIFIED) HYPOTHESIS THAT THE
C * UNDERLYING DISTRIBUTION FROM WHICH THE DATA HAVE BEEN RANDOMLY DRAWN
C * IS THE HALFNORMAL DISTRIBUTION. IF THE HYPOTHESIS IS TRUE, THE PROBABILITY
C * PLOT SHOULD BE NEAR-LINEAR. A MEASURE OF SUCH LINEARITY IS GIVEN BY THE
C * CALCULATED PROBABILITY PLOT CORRELATION COEFFICIENT.
C * THE PROTOTYPE NORMAL DISTRIBUTION USED HEREIN HAS MEAN = 0 AND STANDARD
C * DEVIATION = 1. THIS DISTRIBUTION IS DEFINED FOR ALL X AND HAS THE
C * PROBABILITY DENSITY FUNCTION  F(X) = (1/SQRT(2*PI)) * EXP(-X*X/2).
C * AS USED HEREIN, A PROBABILITY PLOT FOR A DISTRIBUTION IS A PLOT OF THE
C * ORDERED OBSERVATIONS VERSUS THE ORDER STATISTIC MEDIANS FOR THAT
C * DISTRIBUTION. THE NORMAL PROBABILITY PLOT IS USEFUL IN GRAPHICALLY TESTING
C * THE COMPOSITE (THAT IS, LOCATION AND SCALE PARAMETERS NEED NOT BE SPECIFIED)
C * HYPOTHESIS THAT THE UNDERLYING DISTRIBUTION FROM WHICH THE DATA HAVE BEEN
C * RANDOMLY DRAWN IS THE NORMAL DISTRIBUTION. IF THE HYPOTHESIS IS TRUE,
C * THE PROBABILITY PLOT SHOULD BE NEAR-LINEAR. A MEASURE OF SUCH LINEARITY
C * IS GIVEN BY THE CALCULATED PROBABILITY PLOT CORRELATION COEFFICIENT.
 
C * INPUT ARGUMENTS - Y = THE SINGLE PRECISION VECTOR OF (UNSORTED)
C * OBSERVATIONS.
C *                 - N = THE INTEGER NUMBER OF OBSERVATIONS IN THE VECTOR Y.
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: MODE
      REAL :: Q
      REAL, DIMENSION(*) :: Y
      REAL, DIMENSION(*) :: W
      CHARACTER(len=*), DIMENSION(*) :: GRAPH
C * SORT THE DATA
      CALL GEN035 (Y, 1, N)
C * GENERATE UNIFORM ORDER STATISTIC MEDIANS
      CALL GEN117 (N, W)
C * COMPUTE (HALF)NORMAL ORDER STATISTIC MEDIANS
      DO I = 1, N
        Q = W(I)
        IF (MODE == 1) Q = (Q + 1.0) / 2.0
        CALL GEN118 (Q, W(I))
      END DO
C * CALCULATE CORRELATION COEFFICIENT, DIRECTION COEFF ETC.
      CALL GEN119 (MODE, Y, W, N)
C * PLOT THE ORDERED OBSERVATIONS VERSUS ORDER STATISTICS MEDIANS. WRITE OUT
C * THE TAIL LENGTH MEASURE OF THE DISTRIBUTION AND THE SAMPLE SIZE.
      CALL GEN120 (MODE, Y, W, N, GRAPH, LU)
      RETURN
      END SUBROUTINE GEN116
 
      SUBROUTINE GEN117 (N, X)
C * THIS SUBROUTINE GENERATES THE N ORDER STATISTIC MEDIANS FROM THE
C * UNIFORM (RECTANGULAR) DISTRIBUTION ON THE UNIT INTERVAL (0,1).
C * THIS DISTRIBUTION HAS MEAN = 0.5 AND STANDARD DEVIATION = SQRT(1/12) =
C * 0.28867513. THIS DISTRIBUTION HAS THE PROBABILITY DENSITY FUNCTION F(X) = 1.
C * A PROBABILITY PLOT FOR A GENERAL DISTRIBUTION IS A PLOT OF THE ORDERED
C * OBSERVATIONS VERSUS THE ORDER STATISTIC MEDIANS FOR THAT DISTRIBUTION.
C * THE I-TH ORDER STATISTIC MEDIAN FOR A GENERAL DISTRIBUTION IS OBTAINED BY
C * TRANSFORMING THE I-TH UNIFORM ORDER STATISTIC MEDIAN BY THE PERCENT POINT
C * FUNCTION OF THE DESIRED DISTRIBUTION--HENCE THE IMPORTANCE OF BEING ABLE TO
C * GENERATE UNIFORM ORDER STATISTIC MEDIANS. IT IS OF THEORETICAL INTEREST
C * TO NOTE THAT THE I-TH UNIFORM ORDER STATISTIC MEDIAN IN A SAMPLE OF SIZE
C * N IS IDENTICALLY THE MEDIAN OF THE BETA DISTRIBUTION WITH PARAMETERS I
C * AND N-I+1.
C * INPUT  - N = THE DESIRED INTEGER NUMBER OF UNIFORM ORDER
C *              STATISTIC MEDIANS TO BE GENERATED.
C * OUTPUT - X = A SINGLE PRECISION VECTOR (OF DIMENSION AT LEAST N)
C *              INTO WHICH THE GENERATED UNIFORM ORDER STATISTIC
C *                     MEDIANS WILL BE PLACED.
C * OUTPUT - THE N ORDER STATISTIC MEDIANS FROM THE RECTANGULAR DISTRIBUTION
C *         ON (0,1).
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      REAL, DIMENSION(*) :: X
C * COMPUTE THE MEDIANS FOR THE FIRST AND LAST ORDER STATISTICS
      X(N) = 0.5 ** (1.0 / FLOAT (N))
      X(1) = 1.0 - X(N)
      IF (N > 2) THEN
C * COMPUTE THE MEDIANS FOR THE OTHER ORDER STATISTICS
C * NOTE: 0.365 = 1.0 - 2 * 0.3175
        DO I = 2, N - 1
          X(I) = (FLOAT (I) - 0.3175) / (FLOAT (N) + 0.365)
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN117
 
      SUBROUTINE GEN118 (P, PPF)
C * THIS SUBROUTINE COMPUTES THE PERCENT POINT FUNCTION VALUE FOR THE
C * NORMAL (GAUSSIAN) DISTRIBUTION WITH MEAN = 0 AND STANDARD DEVIATION = 1.
C * THIS DISTRIBUTION IS DEFINED FOR ALL X AND HAS THE PROBABILITY DENSITY
C * FUNCTION F(X) = (1/SQRT(2*PI))*EXP(-X*X/2). NOTE THAT THE PERCENT POINT
C * FUNCTION OF A DISTRIBUTION IS IDENTICALLY THE SAME AS THE INVERSE
C * CUMULATIVE DISTRIBUTION FUNCTION OF THE DISTRIBUTION.
C * INPUT  - P   = THE SINGLE PRECISION VALUE (BETWEEN 0.0 AND 1.0)
C *                AT WHICH THE PERCENT POINT FUNCTION IS TO BE EVALUATED.
C * OUTPUT - PPF = THE SINGLE PRECISION PERCENT POINT FUNCTION VALUE.
      IMPLICIT NONE
      REAL :: P
      REAL :: R
      REAL :: T
      REAL :: P0
      REAL :: P1
      REAL :: P2
      REAL :: P3
      REAL :: P4
      REAL :: Q0
      REAL :: Q1
      REAL :: Q2
      REAL :: Q3
      REAL :: Q4
      REAL :: PPF
      REAL :: ANUM
      REAL :: ADEN
      DATA P0, P1, P2, P3, P4, Q0, Q1, Q2, Q3, Q4/
     1 -0.322232431088, -1.0, -0.342242088547, -0.204231210245E-1,
     2 -0.453642210148E-4,  0.993484626060E-1, 0.588581570495,
     C  0.531103462366, 0.103537752850, 0.38560700634E-2/
      IF (P == 0.5) THEN
        PPF = 0.0
      ELSE
        R = P
        IF (P > 0.5) R = 1.0 - R
        T = SQRT (-2.0 * ALOG (R))
        ANUM = ((((T * P4 + P3) * T + P2) * T + P1) * T + P0)
        ADEN = ((((T * Q4 + Q3) * T + Q2) * T + Q1) * T + Q0)
        PPF  = T + (ANUM / ADEN)
        IF (P < 0.5) PPF = - PPF
      END IF
      RETURN
      END SUBROUTINE GEN118
 
      SUBROUTINE GEN119 (MODE, Y, X, N)
C * COMPUTE THE PROBABILITY PLOT CORRELATION COEFFICIENT. COMPUTE LOCATION
C * AND SCALE ESTIMATES FROM THE INTERCEPT AND SLOPE OF THE PROBABILITY PLOT.
C * MODE = 1: SUBROUTINE GENERATES A HALFNORMAL PROBABILITY PLOT.
C * MODE = 2: SUBROUTINE GENERATES A NORMAL (GAUSSIAN) PROBABILITY PLOT
      USE npplot
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: MODE
      REAL :: SUM1
      REAL :: SUM2
      REAL :: SUM3
      REAL :: YBAR
      REAL :: WBAR
      REAL, DIMENSION(*) :: X
      REAL, DIMENSION(*) :: Y
      SUM1 = 0.0
      SUM2 = 0.0
      WBAR = 0.0
      DO I = 1, N
        SUM1 = SUM1 + Y(I)
        IF (MODE == 1) SUM2 = SUM2 + X(I)
      END DO
      YBAR = SUM1 / FLOAT (N)
      IF (MODE == 1) WBAR = SUM2 / FLOAT (N)
      SUM1 = 0.0
      SUM2 = 0.0
      SUM3 = 0.0
      DO I = 1, N
        IF (MODE == 1) THEN
          SUM1 = SUM1 + (Y(I) - YBAR) * (Y(I) - YBAR)
          SUM2 = SUM2 + (Y(I) - YBAR) * (X(I) - WBAR)
          SUM3 = SUM3 + (X(I) - WBAR) * (X(I) - WBAR)
        ELSE IF (MODE == 2) THEN
          SUM1 = SUM1 + (Y(I) - YBAR) * (Y(I) - YBAR)
          SUM2 = SUM2 + X(I) * Y(I)
          SUM3 = SUM3 + X(I) * X(I)
        END IF
      END DO
      IF (SUM1 /= 0.0) THEN
        YCC = SUM2 / SQRT (SUM3 * SUM1)
      ELSE
        YCC = 1.0
      END IF
      YSLOPE = SUM2 / SUM3
      YINT   = YBAR - YSLOPE * WBAR
      RETURN
      END SUBROUTINE GEN119
 
      SUBROUTINE GEN120 (MODE, Y, X, N, GRAPH, LU)
C * THIS SUBROUTINE YIELDS A ONE-PAGE PRINTER PLOT OF Y(I) VERSUS X(I).
C * INPUT  - Y  = THE SINGLE PRECISION VECTOR OF (UNSORTED OR SORTED)
C *               OBSERVATIONS TO BE PLOTTED VERTICALLY.
C *        - X  = THE SINGLE PRECISION VECTOR OF (UNSORTED OR SORTED)
C *               OBSERVATIONS TO BE PLOTTED HORIZONTALLY.
C *        - N  = THE INTEGER NUMBER OF OBSERVATIONS IN THE VECTOR Y.
C * OUTPUT - A ONE-PAGE PRINTER PLOT OF Y(I) VERSUS X(I).
C * VALUES IN THE VERTICAL AXIS VECTOR (Y) OR THE HORIZONTAL AXIS
C * VECTOR (X) WHICH ARE EQUAL TO OR IN EXCESS OF 10.0**10 WILL NOT BE PLOTTED.
C * THIS CONVENTION GREATLY SIMPLIFIES THE PROBLEM OF PLOTTING WHEN SOME
C * ELEMENTS IN THE VECTOR Y (OR X) ARE 'MISSING DATA', OR WHEN WE PURPOSELY
C * WANT TO IGNORE CERTAIN ELEMENTS IN THE VECTOR Y (OR X) FOR PLOTTING
C * PURPOSES (THAT IS, WE DO NOT WANT CERTAIN ELEMENTS IN Y (OR X) TO BE
C * PLOTTED).
C * MODE = 1: SUBROUTINE GENERATES A HALFNORMAL PROBABILITY PLOT.
C * MODE = 2: SUBROUTINE GENERATES A NORMAL (GAUSSIAN) PROBABILITY PLOT
      USE npplot
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: MX
      INTEGER :: MY
      INTEGER :: IM2
      INTEGER :: MODE
      INTEGER :: IOST
      INTEGER :: IFLAG
      REAL :: X25
      REAL :: X75
      REAL :: AIM1
      REAL :: XMIN
      REAL :: XMAX
      REAL :: XMID
      REAL :: YMIN
      REAL :: YMAX
      REAL :: RATIOX
      REAL :: RATIOY
      REAL, DIMENSION(*)  :: X
      REAL, DIMENSION(*)  :: Y
      REAL, DIMENSION(11) :: YLABLE
      CHARACTER(len=125), DIMENSION(44) :: GRAPH
      IOST = 0
C * DETERMINE THE VALUES TO BE LISTED ON THE LEFT VERTICAL AXIS
      YMIN = Y(1)
      YMAX = Y(N)
      YMAX = MAX ( 3.5, YMAX)
      YMIN = MIN (-3.5, YMIN)
      IF (MODE == 1) YMIN = 0.0
      DO I = 1, 9
        AIM1 = I - 1
        YLABLE(I) = YMAX - (AIM1 / 8.0) * (YMAX - YMIN)
      END DO
C * DETERMINE THE VALUES TO BE LISTED ON THE BOTTOM HORIZONTAL AXIS
C * DETERMINE XMIN, XMAX, XMID, X25 (=THE 25% POINT), AND X75 (=THE 75% POINT)
      XMIN = X(1)
      XMAX = X(N)
      XMID = (XMIN + XMAX) / 2.0
      X25  = 0.75 * XMIN + 0.25 * XMAX
      X75  = 0.25 * XMIN + 0.75 * XMAX
C * BLANK OUT THE GRAPH
      DO I = 1, 44
        GRAPH(I) = ' '
      END DO
C * PRODUCE THE VERTICAL AXES
      DO I = 2, 42
        GRAPH(I)(20:20)   = 'I'
        GRAPH(I)(124:124) = 'I'
      END DO
      DO I = 2, 42, 5
        GRAPH(I)(20:20)   = '-'
        GRAPH(I)(124:124) = '-'
      END DO
      GRAPH(2)(16:19)   = '=Max'
      GRAPH(22)(16:19)  = '=Mid'
      GRAPH(42)(16:19)  = '=Min'
      GRAPH(42)(64:120) =
     1 'Vertical: Experimental Data, Horizontal: Theoretical Data'
      IF (MODE == 1) THEN
        GRAPH(3)(22:49) = 'Half-Normal Probability Plot'
      ELSE IF (MODE == 2) THEN
        GRAPH(3)(22:44) = 'Normal Probability Plot'
      ELSE IF (MODE == 3) THEN
        GRAPH(3)(22:47) = 'Student-t Probability Plot'
      END IF
      GRAPH(3)(51:111) =
     1 '(S.C.Abrahams and E.T.Keve (1971). Acta Cryst. A27, 157-165.)'
      WRITE (GRAPH(5)(22:47), 99996, IOSTAT = IOST) N
      WRITE (GRAPH(6)(22:47), 99995, IOSTAT = IOST) YCC
      WRITE (GRAPH(7)(22:47), 99994, IOSTAT = IOST) YINT
      WRITE (GRAPH(8)(22:47), 99993, IOSTAT = IOST) YSLOPE
C * PRODUCE THE HORIZONTAL AXES
      DO J = 22, 122
        GRAPH(1)(J:J)  = '-'
        GRAPH(43)(J:J) = '-'
      END DO
      DO J = 22, 122, 25
        GRAPH(1)(J:J)  = 'I'
        GRAPH(43)(J:J) = 'I'
      END DO
      DO J = 35, 122, 25
        GRAPH(1)(J:J)  = 'I'
        GRAPH(43)(J:J) = 'I'
      END DO
C * DETERMINE THE (X,Y) PLOT POSITIONS
      RATIOY =  40.0 / (YMAX - YMIN)
      RATIOX = 100.0 / (XMAX - XMIN)
      DO I = 1, N
        MX = NINT (RATIOX * (X(I) - XMIN))
        MX = MX + 22
        MY = NINT (RATIOY * (Y(I) - YMIN))
        MY = 42 - MY
        GRAPH(MY)(MX:MX) = 'x'
      END DO
C * WRITE OUT THE GRAPH
      DO I = 1, 44
        IF (I == 44) THEN
          WRITE (GRAPH(44), 99997, IOSTAT = IOST)
     1      XMIN, X25, XMID, X75, XMAX
        ELSE
          IM2   = I - 2
          IFLAG = IM2 - (IM2 / 5) * 5
          K     = IM2 / 5 + 1
          IF (IFLAG == 0)
     1      WRITE (GRAPH(I)(1:15), 99998, IOSTAT = IOST) YLABLE(K)
        END IF
        IF (LU /= 0) WRITE (LU, 99999, IOSTAT = IOST) GRAPH(I)
      END DO
      RETURN
99999 FORMAT (A)
99998 FORMAT (F15.3)
99997 FORMAT (5(9X, F16.3))
99996 FORMAT ('Sample Size    =', I10)
99995 FORMAT ('CC             =', F10.4)
99994 FORMAT ('Est. Intercept =', F10.4)
99993 FORMAT ('Est. Slope     =', F10.4)
      END SUBROUTINE GEN120
 
      SUBROUTINE GEN121 (NQ, N)
C * ELIMINATE () FROM STRING
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      CHARACTER(len=*)  :: NQ
      CHARACTER(len=12) :: NQ1
      NQ1 = NQ
      N1  = INDEX (NQ1(1:N), '(')
      N2  = INDEX (NQ1(1:N), ')')
      IF (N1 /= 0 .AND. N2 .NE. 0) THEN
        NQ = NQ1(1:N1 -1)//NQ1(N1+1:N2-1)//NQ1(N2+1:N+2)
      END IF
      RETURN
      END SUBROUTINE GEN121
 
      SUBROUTINE GEN122 (AXES, NS, ITEL)
C * BUBBLE SORT AXES ON VALUE OF COLUMN NS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NS
      INTEGER :: ITEL
      INTEGER :: ICHANGE
      REAL, DIMENSION(15, 23) :: AXES
      DO
        ICHANGE = 0
        DO J = 1, (ITEL - 1)
          IF (AXES(J, NS) > AXES(J + 1, NS)) THEN
            DO I = 1, 13
              CALL GEN018 (AXES(J, I), AXES(J + 1, I))
            END DO
            CALL GEN018 (AXES(J, 23), AXES(J + 1, 23))
            ICHANGE = 1
          END IF
        END DO
        IF (ICHANGE == 0) EXIT
      END DO
      RETURN
      END SUBROUTINE GEN122
 
      SUBROUTINE GEN123 (MODE, IEN, IENS, IEL, IAN)
C * SORT FORMULA INTO C H D .. ALPHABETIC ORDER
C * OR ALPHABETIC WHEN C ABSENT
      IMPLICIT NONE
 
      INTEGER :: I
      INTEGER :: IAN
      INTEGER :: IVAL
      INTEGER :: IENI
      INTEGER :: MODE
      INTEGER, DIMENSION(*) :: IEN
      INTEGER, DIMENSION(*) :: IEL
      INTEGER, DIMENSION(*) :: IENS
      DO I = 1, IAN
        IENI = IEN(I)
        IF (MODE == 1) THEN
          IF (IENI == 2) THEN
            IVAL = 0
          ELSE IF (IENI == 1) THEN
            IVAL = 1
          ELSE IF (IENI == 33) THEN
            IVAL = 2
          ELSE
            IVAL = IEL(IENI)
          END IF
        ELSE
          IVAL = IEL(IENI)
        END IF
        IENS(I) = IVAL * 100 + I
      END DO
      CALL GEN022 (IENS, 1, IAN, 1)
      DO I = 1, IAN
        IENS(I) = MOD (IENS(I), 100)
      END DO
      RETURN
      END SUBROUTINE GEN123
 
      SUBROUTINE GEN124 (NA, NB, NE)
C * SHELL-SORT FROM NB TO NE, STEP 2 (SMALL TO LARGE)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NY
      INTEGER :: NZ
      INTEGER :: ND
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: NEL
      INTEGER :: NDS
      INTEGER, DIMENSION(*) :: NA
      NEL = (NE - NB + 1) / 2
      IF (NEL >= 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (NEL)) / ALOG (2.0)) + 1.0E-5)) - 1
        DO
          IF (ND <= 0) EXIT
          NDS = ND + ND
          I   = NB
          DO
            J   = I
            NY = NA(I + NDS)
            NZ = NA(I + NDS + 1)
   10       IF (NY < NA(J)) THEN
              NA(J + NDS)     = NA(J)
              NA(J + NDS + 1) = NA(J + 1)
              J = J - NDS
              IF (J >= NB) GO TO 10
            END IF
            NA(J + NDS)     = NY
            NA(J + NDS + 1) = NZ
            I = I + 2
            IF (I + NDS > NE) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN124
 
      SUBROUTINE GEN125 (MODE, LO, STR)
C * WRITE SPECIAL STRING
      IMPLICIT NONE
      INTEGER :: IOST = 0
      INTEGER :: MODE
      INTEGER :: LO
      CHARACTER(LEN=*) :: STR
      IF (MODE == 0) THEN
        WRITE (LO, 99999, ADVANCE = 'NO', IOSTAT = IOST) STR
      ELSE
        WRITE (LO, 99998, ADVANCE = 'NO', IOSTAT = IOST) STR
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT (/, A)
      END SUBROUTINE GEN125
 
      SUBROUTINE GEN126 (C, N, M)
C * BLANK STRING ARRAY
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: M
      CHARACTER(len=*), DIMENSION(*)  :: C
      DO I = N, M
        C(I) = ' '
      END DO
      RETURN
      END  SUBROUTINE GEN126
 
      SUBROUTINE GEN127 (C)
C * EXIT/STOP
      IMPLICIT NONE
      INTEGER :: IOST = 0
      CHARACTER(len=*)  :: C
      CHARACTER(len=70) :: LINE
      CHARACTER(len=70) :: LINF
      IF (C(1:1) /= ' ') THEN
        WRITE (LINE, 99999, IOSTAT = IOST) C
        WRITE (LINF, 99998)
        CALL TRAILER (' ')
        CALL TRAILER (LINF)
        CALL TRAILER (LINE)
        CALL TRAILER (LINF)
        STOP
      ELSE
        CALL EXIT
      END IF
99999 FORMAT ('>>> STOP: ', A, ' <<< (Job ABORTED)')
99998 FORMAT (67('*'))
      END SUBROUTINE GEN127
 
      SUBROUTINE GEN129 (LU, STRING)
C * DELETE FILE
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: LENGTH
      LOGICAL :: EXST
      CHARACTER(len=*) :: STRING
      LENGTH = LEN (STRING)
      INQUIRE (FILE = STRING(1:LENGTH), EXIST = EXST)
      IF (EXST) THEN
        OPEN  (LU, FILE = STRING(1:LENGTH), STATUS = 'UNKNOWN')
        CLOSE (LU, STATUS = 'DELETE')
      END IF
      RETURN
      END SUBROUTINE GEN129
 
      REAL FUNCTION GEN130 (A)
C * DETERMINANT OF 3*3 MATRIX
      IMPLICIT NONE
      REAL, DIMENSION(3, 3) :: A
      GEN130 =
     1        A(1, 1) * (A(2, 2) * A(3, 3) - A(2, 3) * A(3, 2))
     2      - A(1, 2) * (A(2, 1) * A(3, 3) - A(2, 3) * A(3, 1))
     3      + A(1, 3) * (A(2, 1) * A(3, 2) - A(2, 2) * A(3, 1))
      RETURN
      END FUNCTION GEN130
 
      SUBROUTINE GEN131 (LHNT, I, J, K, L, IDET)
C * DETERMINANT OF 3*3 MATRIX FROM  EXTENDED ARRAY
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: IDET
      INTEGER, DIMENSION(4, 3, 5) :: LHNT
      IDET =  LHNT(I, 1, L)  * (LHNT(J, 2, L)  *  LHNT(K, 3, L)
     1     -  LHNT(K, 2, L)  *  LHNT(J, 3, L)) +  LHNT(I, 2, L)
     2     * (LHNT(J, 3, L)  *  LHNT(K, 1, L)  -  LHNT(J, 1, L)
     3     *  LHNT(K, 3, L)) +  LHNT(I, 3, L)  * (LHNT(J, 1, L)
     4     *  LHNT(K, 2, L)  -  LHNT(J, 2, L)  *  LHNT(K, 1, L))
      IDET = ABS(IDET)
      RETURN
      END SUBROUTINE GEN131
 
      SUBROUTINE GEN132 (T1, Y, T2, Z)
C * Z = T1 * Y * T2
      IMPLICIT NONE
 
      REAL, DIMENSION(3, 3) :: X
      REAL, DIMENSION(3, 3) :: Y
      REAL, DIMENSION(3, 3) :: Z
      REAL, DIMENSION(3, 3) :: T1
      REAL, DIMENSION(3, 3) :: T2
      CALL GEN004 (Y, T2, X)
      CALL GEN004 (T1, X, Z)
      RETURN
      END SUBROUTINE GEN132
 
      SUBROUTINE GEN133 (IA, IB, N)
C * COPY VECTOR WITH N ELEMENTS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER, DIMENSION(*) :: IA
      INTEGER, DIMENSION(*) :: IB
      DO I = 1, N
        IB(I) = IA(I)
      END DO
      RETURN
      END SUBROUTINE GEN133
 
      SUBROUTINE GEN134 (STR1, STR2, NB, NE)
C * COPY FORMULA STRINGS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LB
      INTEGER :: LE
      INTEGER :: NB
      INTEGER :: NE
      CHARACTER(len=1) :: ICH
      CHARACTER(len=*) :: STR1
      CHARACTER(len=*) :: STR2
      LB = NB
      LE = NE
C * STRIP FRONT AND BACK BLANCS
      CALL GEN039 (0, STR1, NB, NE, LB, LE)
      N = 0
      DO I = LB, LE
        ICH = STR1(I:I)
        IF (ICH == '[') EXIT
C * CHECK FOR UPPER CASE CHARACTER
        CALL GEN105 (1, ICH, M)
        IF (M > 0) THEN
          N = N + 1
        ELSE
          N = 0
        END IF
        IF (N == 2) THEN
          N = 0
          CALL GEN020 (-1, ICH, 1, 1)
          STR1(I:I) = ICH
        END IF
      END DO
      STR2 = STR1(LB:LE)
      RETURN
      END SUBROUTINE GEN134
 
      INTEGER FUNCTION GEN135 (A)
C * UNIT 3*3 MATRIX ?
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL :: DIAG
      REAL, DIMENSION(3, 3) :: A
      GEN135 = 0
      DIAG   = 0.0
      DO I = 1, 3
        DO J = 1, 3
          IF (I == J) THEN
            DIAG = DIAG + ABS (A(I, J) - 1.0)
          ELSE
            DIAG = DIAG + ABS (A(I, J))
          END IF
        END DO
      END DO
      IF (NINT(DIAG) == 0) GEN135 = 1
      RETURN
      END FUNCTION GEN135
 
      SUBROUTINE GEN136 (X, GA)
C * Purpose: Compute the gamma function a(x)
C * Input :  x  --- Argument of a(x)
C *        ( x is not equal to 0,-1,-2,uuu )
C * Output:  GA --- a(x)
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: M
      INTEGER :: M1
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: Z
      DOUBLE PRECISION :: R
      DOUBLE PRECISION :: GA
      DOUBLE PRECISION :: GR
      DOUBLE PRECISION :: PI
      DOUBLE PRECISION, DIMENSION(26) :: G
      G = (/
     1  1.0D0,
     2  0.5772156649015329D0,
     3 -0.6558780715202538D0,
     4 -0.420026350340952D-1,
     5  0.1665386113822915D0,
     6 -0.421977345555443D-1,
     7 -0.96219715278770D-2,
     8  0.72189432466630D-2,
     9 -0.11651675918591D-2,
     * -0.2152416741149D-3,
     1  0.1280502823882D-3,
     2 -0.201348547807D-4,
     3 -0.12504934821D-5,
     4  0.11330272320D-5,
     5 -0.2056338417D-6,
     6  0.61160950D-8,
     7  0.50020075D-8,
     8 -0.11812746D-8,
     9  0.1043427D-9,
     *  0.77823D-11,
     1 -0.36968D-11,
     2  0.51D-12,
     3 -0.206D-13,
     4 -0.54D-14,
     5  0.14D-14,
     6  0.1D-15
     7  /)
      PI = 3.141592653589793D0
      IF (X == INT (X)) THEN
        IF (X > 0.0D0) THEN
          GA = 1.0D0
          M1 = INT (X) - 1
          DO K = 2, M1
            GA = GA * K
          END DO
        ELSE
          GA = 1.0D + 300
        ENDIF
      ELSE
        IF (DABS (X) > 1.0D0) THEN
          Z = DABS (X)
          M = INT (Z)
          R = 1.0D0
          DO K = 1, M
            R = R * (Z - K)
          END DO
          Z = Z - M
        ELSE
          Z = X
        ENDIF
        GR = G(26)
        DO K = 25, 1, -1
          GR = GR * Z + G(K)
        END DO
        GA = 1.0D0 / (GR * Z)
        IF (DABS (X) > 1.0D0) THEN
          GA = GA * R
          IF (X < 0.0D0) GA = - PI / (X * GA * DSIN (PI * X))
        ENDIF
      ENDIF
      RETURN
      END SUBROUTINE GEN136
 
      SUBROUTINE GEN137 (X, PS)
C * Purpose: Compute Psi function
C * Input :  x  --- Argument of psi(x)
C * Output:  PS --- psi(x)
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: N
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: S
      DOUBLE PRECISION :: PS
      DOUBLE PRECISION :: XA
      DOUBLE PRECISION :: PI
      DOUBLE PRECISION :: EL
      DOUBLE PRECISION :: X2
      DOUBLE PRECISION :: A1
      DOUBLE PRECISION :: A2
      DOUBLE PRECISION :: A3
      DOUBLE PRECISION :: A4
      DOUBLE PRECISION :: A5
      DOUBLE PRECISION :: A6
      DOUBLE PRECISION :: A7
      DOUBLE PRECISION :: A8
      XA = DABS (X)
      PI = 3.141592653589793D0
      EL = 0.5772156649015329D0
      S = 0.0D0
      IF (X == INT (X) .AND. X <= 0.0D+0) THEN
        PS = 1.0D + 300
        RETURN
      ELSE IF (XA == INT (XA)) THEN
        N = INT (XA)
        DO K = 1, N - 1
          S = S + 1.0D0 / K
        END DO
        PS = - EL + S
      ELSE IF (XA + 0.5D+0 == INT (XA + 0.5D+0)) THEN
        N = INT (XA - 0.5D+0)
        DO  K = 1, N
          S = S + 1.0D+0 / (2.0D0 * K - 1.0D0)
        END DO
        PS = - EL + 2.0D0 * S - 1.386294361119891D0
      ELSE
        IF (XA < 10.0D+0) THEN
          N = 10 - INT (XA)
          DO K = 0, N - 1
            S = S + 1.0D0 / (XA + K)
          END DO
          XA = XA + N
        END IF
        X2 = 1.0D0 / (XA * XA)
        A1 = -0.8333333333333D-01
        A2 = 0.83333333333333333D-02
        A3 = -0.39682539682539683D-02
        A4 = 0.41666666666666667D-02
        A5 = -0.75757575757575758D-02
        A6 = 0.21092796092796093D-01
        A7 = -0.83333333333333333D-01
        A8 = 0.4432598039215686D0
        PS = DLOG (XA) - 0.5D0 / XA + X2 * (((((((A8 * X2 + A7) * X2 +
     1        A6) * X2 + A5) * X2 + A4) * X2 + A3) * X2 + A2) * X2 + A1)
        PS = PS - S
      END IF
      IF (X < 0.0D+0)
     1    PS = PS - PI * DCOS (PI * X) / DSIN (PI * X) - 1.0D0 / X
      RETURN
      END SUBROUTINE GEN137
 
      SUBROUTINE GEN138 (A, B, C, X, HF)
C * Purpose: Compute hypergeometric function F(a,b,c,x)
C * Input :  a --- Parameter
C *          b --- Parameter
C *          c --- Parameter, c <> 0,-1,-2,...
C *          x --- Argument   ( x < 1 )
C * Output:  HF --- F(a,b,c,x)
C * Routines called:
C *         (1) GEN136 for computing gamma function
C *         (2) GEN137 for computing psi function
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: NM
      INTEGER :: IOST = 0
      DOUBLE PRECISION :: A
      DOUBLE PRECISION :: B
      DOUBLE PRECISION :: C
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: R
      DOUBLE PRECISION :: AA
      DOUBLE PRECISION :: BB
      DOUBLE PRECISION :: F0
      DOUBLE PRECISION :: F1
      DOUBLE PRECISION :: X1
      DOUBLE PRECISION :: R0
      DOUBLE PRECISION :: R1
      DOUBLE PRECISION :: A0
      DOUBLE PRECISION :: C0
      DOUBLE PRECISION :: C1
      DOUBLE PRECISION :: G0
      DOUBLE PRECISION :: G1
      DOUBLE PRECISION :: G2
      DOUBLE PRECISION :: G3
      DOUBLE PRECISION :: GM
      DOUBLE PRECISION :: HW
      DOUBLE PRECISION :: RM
      DOUBLE PRECISION :: RP
      DOUBLE PRECISION :: SM
      DOUBLE PRECISION :: SP
      DOUBLE PRECISION :: PI
      DOUBLE PRECISION :: EL
      DOUBLE PRECISION :: HF
      DOUBLE PRECISION :: GA
      DOUBLE PRECISION :: GB
      DOUBLE PRECISION :: GC
      DOUBLE PRECISION :: PA
      DOUBLE PRECISION :: PB
      DOUBLE PRECISION :: EPS
      DOUBLE PRECISION :: SP0
      DOUBLE PRECISION :: GCA
      DOUBLE PRECISION :: GCB
      DOUBLE PRECISION :: GAM
      DOUBLE PRECISION :: GBM
      DOUBLE PRECISION :: GCAB
      DOUBLE PRECISION :: GABC
      CHARACTER(len=80) :: LINE
      LOGICAL :: L0
      LOGICAL :: L1
      LOGICAL :: L2
      LOGICAL :: L3
      LOGICAL :: L4
      LOGICAL :: L5
      HW = 0.0D+0
      PI = 3.141592653589793D0
      EL = 0.5772156649015329D0
      L0 = C == INT (C) .AND. C < 0.0D+0
      L1 = 1.0D0 - X < 1.0D-15 .AND. C - A - B <= 0.0D+0
      L2 = A == INT (A) .AND. A < 0.0D+0
      L3 = B == INT (B) .AND. B < 0.0D+0
      L4 = C - A == INT (C - A) .AND. C - A .LE .0.0D+0
      L5 = C - B == INT (C - B) .AND. C - B <= 0.0D+0
      IF (L0 .OR. L1) THEN
        WRITE (LINE, 99999, IOSTAT = IOST)
        CALL TRAILER (LINE)
        RETURN
      END IF
      EPS = 1.0D-15
      IF (X > 0.95D+0) EPS = 1.0D-8
      IF (X == 0.0D+0 .OR. A == 0.0D+0 .OR. B == 0.0D+0) THEN
        HF = 1.0D0
        RETURN
      ELSE IF (1.0D0 - X == EPS .AND. C - A - B > 0.0D+0) THEN
        CALL GEN136 (C, GC)
        CALL GEN136 (C - A -B, GCAB)
        CALL GEN136 (C - A, GCA)
        CALL GEN136 (C - B, GCB)
        HF= GC * GCAB / (GCA * GCB)
        RETURN
      ELSE IF (1.0D0 + X <= EPS .AND.
     1         DABS (C - A + B - 1.0D+0) <= EPS) THEN
        G0 = DSQRT (PI) * 2.0D0 ** (-A)
        CALL GEN136 (C, G1)
        CALL GEN136 (1.0D0 + A / 2.0D+0 - B, G2)
        CALL GEN136 (0.5D0 + 0.5D+0 * A, G3)
        HF = G0 * G1 / (G2 * G3)
        RETURN
      ELSE IF (L2 .OR. L3) THEN
        IF (L2) NM = INT (ABS (A))
        IF (L3) NM = INT (ABS (B))
        HF = 1.0D0
        R  = 1.0D0
        DO K = 1, NM
          R = R * (A + K - 1.0D0) * (B + K - 1.0D0) /
     1        (K * (C + K -1.0D0)) * X
          HF = HF + R
        END DO
        RETURN
      ELSE IF (L4 .OR. L5) THEN
        IF (L4) NM = INT (ABS (C - A))
        IF (L5) NM = INT (ABS (C - B))
        HF = 1.0D0
        R  = 1.0D0
        DO K = 1, NM
          R = R * (C - A + K - 1.0D0) * (C - B + K - 1.0D0) /
     1       (K * (C + K - 1.0D0)) * X
          HF = HF + R
        END DO
        HF = (1.0D0 - X) ** (C - A - B ) * HF
        RETURN
      END IF
      AA = A
      BB = B
      X1 = X
      IF (X < 0.0D0) THEN
        X = X / (X - 1.0D0)
        IF (C > A .AND. B < A .AND. B > 0.0) THEN
          A = BB
          B = AA
        END IF
        B = C - B
      END IF
      IF (X >= 0.75D0) THEN
        GM = 0.0D0
        IF (DABS (C - A - B - INT (C - A - B)) < 1.0D-15) THEN
          M = INT (C - A - B)
          CALL GEN136 (A, GA)
          CALL GEN136 (B, GB)
          CALL GEN136 (C, GC)
          CALL GEN136 (A + M, GAM)
          CALL GEN136 (B + M, GBM)
          CALL GEN137 (A, PA)
          CALL GEN137 (B, PB)
          IF (M /= 0) GM = 1.0D0
          DO J = 1, ABS (M) - 1
            GM = GM * J
          END DO
          RM = 1.0D0
          DO J = 1, ABS (M)
            RM = RM * J
          END DO
          F0  = 1.0D0
          R0  = 1.0D0
          R1  = 1.0D0
          SP0 = 0.D0
          SP  = 0.0D0
          IF (M >= 0) THEN
            C0 = GM * GC / (GAM * GBM)
            C1 = - GC * (X - 1.0D0) ** M / (GA * GB * RM)
            DO K = 1, M - 1
              R0 = R0 * (A + K - 1.0D0) * (B + K - 1.0) /
     1             (K * (K - M)) * (1.0 - X)
              F0 = F0 + R0
            END DO
            DO K = 1, M
              SP0 = SP0 + 1.0D0 / (A + K - 1.0) + 1.0 /
     1             (B + K - 1.0) - 1.0 / K
            END DO
            F1 = PA + PB + SP0 + 2.0D0 * EL + DLOG (1.0D0 - X)
            DO K = 1, 250
              SP = SP + (1.0D0 - A) / (K * (A + K - 1.0)) +
     1            (1.0 - B) / (K * (B + K - 1.0))
              SM = 0.0D0
              DO J = 1, M
                SM = SM + (1.0D0 - A) / ((J + K) * (A + J + K - 1.0)) +
     1               1.0 / (B + J + K - 1.0)
              END DO
              RP = PA + PB + 2.0D0 * EL + SP + SM + DLOG (1.0D0 - X)
              R1 = R1 * (A + M + K - 1.0D0) * (B + M + K - 1.0) /
     1             (K * (M + K)) * (1.0 - X)
              F1 = F1 + R1 * RP
              IF (DABS (F1 - HW) < DABS (F1) * EPS) EXIT
              HW = F1
            END DO
            HF = F0 * C0 + F1 * C1
          ELSE IF (M < 0) THEN
            M = - M
            C0 = GM * GC / (GA * GB * (1.0D0 - X)**M)
            C1 = - (-1) ** M * GC / (GAM * GBM * RM)
            DO K = 1, M - 1
              R0 = R0 * (A - M + K - 1.0D0) * (B - M + K - 1.0) /
     1             (K * (K - M)) * (1.0 - X)
              F0 = F0 + R0
            END DO
            DO K = 1, M
              SP0 = SP0 + 1.0D0 / K
            END DO
            F1 = PA + PB - SP0 + 2.0D0 * EL + DLOG (1.0D0 - X)
            DO K = 1, 250
              SP = SP + (1.0D0 - A) / (K * (A + K - 1.0)) +
     1             (1.0 - B) / (K * (B + K - 1.0))
              SM = 0.0D0
              DO J = 1, M
                SM = SM + 1.0D0 / (J + K)
              END DO
              RP = PA + PB + 2.0D0 * EL + SP - SM + DLOG (1.0D0 - X)
              R1 = R1 * (A + K - 1.0D0) * (B + K - 1.0) /
     1            (K * (M + K)) * (1.0 - X)
              F1 = F1 + R1 * RP
              IF (DABS (F1 - HW) < DABS (F1) * EPS) EXIT
              HW = F1
            END DO
            HF = F0 * C0 + F1 * C1
          END IF
        ELSE
          CALL GEN136 (A, GA)
          CALL GEN136 (B, GB)
          CALL GEN136 (C, GC)
          CALL GEN136 (C - A, GCA)
          CALL GEN136 (C - B, GCB)
          CALL GEN136 (C - A - B, GCAB)
          CALL GEN136 (A + B - C, GABC)
          C0 = GC * GCAB / (GCA * GCB)
          C1 = GC * GABC / (GA * GB) * (1.0D0 - X) ** (C - A - B)
          HF = 0.0D0
          R0 = C0
          R1 = C1
          DO K = 1, 250
            R0 = R0 * (A + K - 1.0D0) * (B + K - 1.0) /
     1           (K * (A + B - C + K)) * (1.0 - X)
            R1 = R1 * (C - A + K - 1.0D0) * (C - B + K - 1.0) /
     1          (K * (C - A - B + K)) * (1.0 - X)
            HF = HF + R0 + R1
            IF (DABS (HF - HW) < DABS (HF) * EPS) EXIT
            HW = HF
          END DO
          HF = HF + C0 + C1
        END IF
      ELSE
        A0 = 1.0D0
        IF (C > A .AND. C < 2.0D0 * A .AND.
     1    C > B .AND. C < 2.0D0 * B) THEN
          A0 = (1.0D0 - X) ** (C - A - B)
          A = C - A
          B = C - B
        END IF
        HF = 1.0D0
        R  = 1.0D0
        DO K = 1, 250
          R = R * (A + K - 1.0D0) * (B + K - 1.0D0) /
     1       (K * (C + K - 1.0D0)) * X
          HF = HF + R
          IF (DABS (HF - HW) <= DABS (HF) * EPS) EXIT
          HW = HF
        END DO
        HF = A0 * HF
      END IF
      IF (X1 < 0.0D0) THEN
        X  = X1
        C0 = 1.0D0 / (1.0D0 - X) ** AA
        HF = C0 * HF
      END IF
      A = AA
      B = BB
      IF (K > 120) THEN
        WRITE (LINE, 99998, IOSTAT = IOST)
        CALL TRAILER (LINE)
      END IF
      RETURN
99999 FORMAT ('The hypergeometric series is divergent')
99998 FORMAT ('Warning! check the accuracy')
      END SUBROUTINE GEN138
 
      SUBROUTINE GEN139 (X, XNU, CDFT)
C * CALCULATE CUMULATIVE DISTRIBUTION FUNCTION FOR STUDENT-T PDF
      IMPLICIT NONE
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: A
      DOUBLE PRECISION :: B
      DOUBLE PRECISION :: C
      DOUBLE PRECISION :: D
      DOUBLE PRECISION :: E
      DOUBLE PRECISION :: F
      DOUBLE PRECISION :: G
      DOUBLE PRECISION :: PI
      DOUBLE PRECISION :: XNU
      DOUBLE PRECISION :: CDFT
      PI = 3.141592653589793D0
      A  = 0.5D+0
      B  = (XNU + 1) / 2
      C  = 1.5D+0
      D  = - X**2 / XNU
      E  = 0.0D+0
      CALL GEN138 (A, B, C, D, E)
      A  = (XNU + 1) / 2
      F  = 0.0D+0
      CALL GEN136 (A, F)
      A  = XNU / 2
      G  = 0.0D+0
      CALL GEN136 (A, G)
      CDFT = 0.5D+0 + X * F * E / (SQRT (PI * XNU) * G)
      RETURN
      END SUBROUTINE GEN139
 
      SUBROUTINE GEN140 (X, XNU, CDFTINV)
C * INVERSE CUMULATIVE DISTRIBUTION FOR STUDENT-T DISTRIBUTION
      IMPLICiT NONE
      INTEGER :: IOST = 0
      DOUBLE PRECISION :: A
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: XNU
      DOUBLE PRECISION :: XMID
      DOUBLE PRECISION :: XLOW
      DOUBLE PRECISION :: XHIGH
      DOUBLE PRECISION :: CDFTINV
      CHARACTER(len=80) :: LINE
      IF (X < 0.0D+0 .OR. X >= 1.0D+0) THEN
        WRITE (LINE, 99999, IOSTAT = IOST)
        CALL TRAILER (LINE)
        RETURN
      END IF
      IF (X < 0.5D+0) THEN
        XHIGH =  0.0D+0
        XLOW  = -1.0D+0
        DO WHILE (.TRUE.)
C * CALCULATE CUMULATIVE DISTRIBUTION FUNCTION FOR STUDENT-T PDF
          CALL GEN139 (XLOW, XNU, A)
          IF (A <= X) EXIT
          XHIGH = XLOW
          XLOW  = XLOW * 2.0D+0
        END DO
      ELSE
        XLOW  = 0.0D+0
        XHIGH = 1.0D+0
        DO WHILE (.TRUE.)
C * CALCULATE CUMULATIVE DISTRIBUTION FUNCTION FOR STUDENT-T PDF
          CALL GEN139 (XHIGH, XNU, A)
          IF (A >= X) EXIT
          XLOW  = XHIGH
          XHIGH = XHIGH * 2.0D+0
        END DO
      END IF
      DO WHILE (XHIGH - XLOW > 1D-6)
        XMID = (XHIGH + XLOW) / 2.0D+0
C * CALCULATE CUMULATIVE DISTRIBUTION FUNCTION FOR STUDENT-T PDF
        CALL GEN139 (XMID, XNU, A)
        IF (A < X) THEN
          XLOW = XMID
        ELSE
          XHIGH = XMID
        END IF
        CDFTINV = (XHIGH + XLOW) / 2.0D+0
      END DO
      RETURN
99999 FORMAT ('Argument outside 0 to 1 range')
      END SUBROUTINE GEN140
 
      SUBROUTINE GEN141 (W, RNU, N)
C * INVERSE CUMULATIVE DISTRIBUTION FOR STUDENT-T DISTRIBUTION
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      REAL :: RNU
      REAL, DIMENSION(*) :: W
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: Y
      DOUBLE PRECISION :: XNU
      XNU = RNU
      DO I = 1, N
        X  = (FLOAT (I) - 0.5) / FLOAT(N)
C * INVERSE CUMULATIVE DISTRIBUTION FOR STUDENT-T DISTRIBUTION
        CALL GEN140 (X, XNU, Y)
        W(I) =  SNGL(Y)
      END DO
      END
 
      SUBROUTINE GEN142 (Y, W, RNU, N, GRAPH, LU)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: M
      INTEGER :: LU
      REAL :: RNU
      REAL, DIMENSION(*) :: Y
      REAL, DIMENSION(*) :: W
      CHARACTER(len=125), DIMENSION(44) :: GRAPH
C * SORT DATA
C * NR OF DATA POINTS ......... N
C * LEAVE OUT LOW OUTLIERS .... M
C * LEAVE OUT HIGH OUTLIERS ... M
      M = 5
C * SORT SMALL TO LARGE
      CALL GEN035 (Y, 1, N)
      J = 0
      DO I = M + 1, N - M
        J = J + 1
        Y(J) = Y(I)
      END DO
      N = N - 2 * M
      CALL GEN143 (Y, W, N, RNU)
      CALL GEN141 (W, RNU, N)
      CALL GEN119 (2, Y, W, N)
      CALL GEN120 (3, Y, W, N, GRAPH, LU)
      RETURN
      END SUBROUTINE GEN142
 
      SUBROUTINE GEN143 (Y, W, N, RNU)
      USE npplot
      IMPLICIT NONE
      REAL, PARAMETER :: R = 0.61803399
      REAL, PARAMETER :: C = 1.0 - R
      INTEGER :: N
      REAL :: AX
      REAL :: BX
      REAL :: CX
      REAL :: F1
      REAL :: F2
      REAL :: X0
      REAL :: X1
      REAL :: X2
      REAL :: X3
      REAL :: TOL
      REAL :: RNU
      REAL, DIMENSION(*) :: Y
      REAL, DIMENSION(*) :: W
      IF (RNU == 0.0) THEN
        TOL = 0.0005
        AX  = 2.0
        BX  = 99.0
        CX  = 100.0
        X0  = AX
        X3  = CX
        IF (ABS(CX - BX) > ABS (BX - AX)) THEN
          X1 = BX
          X2 = BX + C * (CX - BX)
        ELSE
          X2 = BX
          X1 = BX - C * (BX - AX)
        END IF
        CALL GEN141 (W, X1, N)
        CALL GEN119 (2, Y, W, N)
        F1 = 1.0 - YCC
        CALL GEN141 (W, X2, N)
        CALL GEN119 (2, Y, W, N)
        F2 = 1.0 - YCC
        DO WHILE (ABS (X3 - X0) > TOL * (ABS (X1) + ABS (X2)))
          IF (F2 < F1) THEN
            X0 = X1
            X1 = X2
            X2 = R * X1 + C * X3
            F1 = F2
            CALL GEN141 (W, X2, N)
            CALL GEN119 (2, Y, W, N)
            F2 = 1.0 - YCC
          ELSE
            X3 = X2
            X2 = X1
            X1 = R * X2 + C * X0
            F2 = F1
            CALL GEN141 (W, X1, N)
            CALL GEN119 (2, Y, W, N)
            F1 = 1.0 - YCC
          END IF
        END DO
        IF  (F1 < F2) THEN
          RNU = X1
        ELSE
          RNU = X2
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN143
 
      SUBROUTINE GEN144 (MODE, A, B)
      IMPLICIT NONE
      INTEGER :: MODE
      REAL, DIMENSION(6) :: A
      REAL, DIMENSION(3) :: B
      IF (MODE == 1) THEN
        A(1) = A(1) * B(1)**2
        A(2) = A(2) * B(2)**2
        A(3) = A(3) * B(3)**2
        A(4) = A(4) * B(2) * B(3)
        A(5) = A(5) * B(1) * B(3)
        A(6) = A(6) * B(1) * B(2)
      ELSE
        A(1) = A(1) / B(1)**2
        A(2) = A(2) / B(2)**2
        A(3) = A(3) / B(3)**2
        A(4) = A(4) / (B(2) * B(3))
        A(5) = A(5) / (B(1) * B(3))
        A(6) = A(6) / (B(1) * B(2))
      ENDIF
      RETURN
      END SUBROUTINE GEN144
 
      SUBROUTINE GEN145 (IH, IK, IL)
C * APPLY FRIEDEL SYMMETRY TO MAKE IL >= 0
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      IF (IL < 0) THEN
        IH = - IH
        IK = - IK
        IL = - IL
      ELSE IF (IL == 0) THEN
        IF (IK < 0) THEN
          IK = - IK
          IH = - IH
        ELSE IF (IK == 0) THEN
          IH = IABS(IH)
        END IF
      END IF
      RETURN
      END SUBROUTINE GEN145
 
      SUBROUTINE GEN146 (FORMX, X, IX, N)
C * Pack Flack,Parsons or Hooft parameter values for listing
 
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: IX
      INTEGER :: IOST = 0
      REAL :: X
      CHARACTER(len=10) :: FORMX
      CHARACTER(len=17) :: FORMA
      FORMA = '(F7.0,''('',I1,'')'')'
      IF (IX >= 10) THEN
        FORMA(3:3)   = CHAR (54)
        FORMA(12:12) = CHAR (50)
      END IF
      FORMA(5:5) = CHAR (N + 48)
      WRITE (FORMX, FORMA, IOSTAT = IOST) X, IX
      RETURN
      END SUBROUTINE GEN146
 
      SUBROUTINE GEN147 (IA, N, JL, JU)
C * SHEL-SORT ROUTINE: ON FIRST ELEMENT FROM JL TO JU (SMALL TO LARGE)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: ND
      INTEGER :: JV
      INTEGER :: JL
      INTEGER :: JU
      INTEGER, DIMENSION(N, *) :: IA
      INTEGER, DIMENSION(N)    :: IB
      JV = JU - JL + 1
      IF (JV > 1) THEN
        ND = 2**(INT ((ALOG (FLOAT (JV)) / ALOG (2.0)) + 1.0E-5)) - 1
        DO
          IF (ND <= 0) EXIT
          I  = JL
          DO
            J  = I
            DO K = 1, N
              IB(K) = IA(K, I + ND)
            END DO
   10       IF (IB(1) < IA(1, J)) THEN
              DO K = 1, N
                IA(K, J + ND) = IA(K, J)
              END DO
              J = J - ND
              IF (J >= JL) GO TO 10
            END IF
            DO K = 1, N
              IA(K, J + ND) = IB(K)
            END DO
            I = I + 1
            IF (I + ND > JU) EXIT
          END DO
          ND = (ND - 1) / 2
        END DO
      END IF
      RETURN
      END SUBROUTINE GEN147
 
      SUBROUTINE GEN148 (LU, IOPER)
C * REPORT REWIND ISSUE
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: IOPER
      CHARACTER(len=80) :: LINE
      IF (IOPER == 1) THEN
        WRITE (LINE, 99999) LU
        CALL TRAILER (LINE)
      END IF
      RETURN
99999 FORMAT ('** Problem with REWIND on UNIT', I4)
      END SUBROUTINE GEN148
 
      DOUBLE PRECISION FUNCTION GEN149 (XP, N, X, Y)
C * Aitken repeated interpolation
C * XP = abscissa at which interpolation is desired
C * X  = vector of n values of abscissa
C * Y  = vector of n values of ordinate
C * T  = temporary storage vector of 4*(m+1) locations)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: INDX
      INTEGER :: MEND
      DOUBLE PRECISION :: XP
      DOUBLE PRECISION :: SGN
      DOUBLE PRECISION :: TEL
      DOUBLE PRECISION :: NOEM
      DOUBLE PRECISION, DIMENSION(*)  :: X
      DOUBLE PRECISION, DIMENSION(*)  :: Y
      DOUBLE PRECISION, DIMENSION(20) :: T
      INDX = 0
      IF (N <= 2) THEN
        CALL TRAILER (' Too few points, funct=y(1)')
        GEN149 = Y(1)
      ELSE
        SGN = SIGN (1.0D0, X(1) - X(2))
        I   = 1
        DO WHILE (SGN * X(I) > SGN * XP .AND. I <= N)
          INDX = I
          I    = I + 1
        END DO
        INDX = INDX - 1
        INDX = MAX0 (INDX, 1)
        INDX = MIN0 (INDX, N - 2)
        MEND  = INDX + 2
        DO I  = INDX, MEND
          K        = I - INDX + 1
          T(K)     = Y(I)
          T(K + 3) = X(I) - XP
        END DO
        DO I = 1, 2
          K = I + 1
          DO J = K, 3
            TEL  = T(I) * T(J + 3) - T(J) * T(I + 3)
            NOEM = X(J + INDX - 1) - X(I + INDX - 1)
            T(J) = TEL / NOEM
          END DO
        END DO
        GEN149 = T(3)
      END IF
      RETURN
      END FUNCTION GEN149
 
      SUBROUTINE GEN150 (N, A, B)
C * bubble sort.  largest becomes last
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      DOUBLE PRECISION :: X
      DOUBLE PRECISION :: Y
      DOUBLE PRECISION, DIMENSION(*) :: A
      DOUBLE PRECISION, DIMENSION(*) :: B
      DO I = 1, N - 1
        DO J = I + 1, N
          IF (A(J) < A(I)) THEN
            X    = A(J)
            Y    = A(I)
            A(I) = X
            A(J) = Y
            X    = B(J)
            Y    = B(I)
            B(I) = X
            B(J) = Y
          END IF
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN150
 
      SUBROUTINE GEN151 (A, N)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      INTEGER :: N
      CHARACTER(len=*) :: A
      L = LEN (A)
      DO I = N, L
C * SUBSTITUTE FORWARD SLASH FOR A BACKWARD SLASH
        IF (A(I:I) == CHAR (92)) A(I:I) = CHAR (47)
C * CHECK FOR HASH CHARACTER AND BLANK COMMENT
        IF (A(I:I) == CHAR (35)) THEN
          DO J = I, L
            A(J:J) = CHAR (32)
          END DO
          RETURN
        END IF
C * SUBSTITUTE BLANK FOR CARRIAGE RETURN CHARACTER
        IF (A(I:I) == CHAR(13)) A(I:I) = CHAR(32)
      END DO
      RETURN
      END SUBROUTINE GEN151
 
      INTEGER FUNCTION GEN152 (X)
C * ESTABLISH RELEVANT NUMBER OF DECIMALS
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      REAL :: X
      CHARACTER(len=10) :: LINE
      WRITE (LINE, 99999) X
      DO I = 1, 5
        J = 11 - I
        IF (LINE(J:J) /= '0') THEN
          GEN152  = J - 5
          EXIT
        END IF
      END DO
      RETURN
99999 FORMAT (F10.5)
      END FUNCTION GEN152
 
      SUBROUTINE GEN153 (R, Y1, Y2, Y3, Y4, A)
C * FIT CURVE TO Y = A(1) * RHO**3 + A(2) * RHO**2 + A(3) * RHO + A(4)
      IMPLICIT NONE
      REAL :: B1
      REAL :: B2
      REAL :: Y1
      REAL :: Y2
      REAL :: Y3
      REAL :: Y4
      REAL :: C11
      REAL :: C12
      REAL :: C21
      REAL :: C22
      REAL :: C31
      REAL :: C32
      REAL, DIMENSION(4) :: R
      REAL, DIMENSION(4) :: A
      B2   = R(4) * (R(4) + R(1))
      B1   = (Y4 - Y1) / (R(4) - R(1))
      C31  = (Y2 - Y1) / (R(2) - R(1)) - B1
      C32  = (Y3 - Y1) / (R(3) - R(1)) - B1
      C11  = R(2) * (R(2) + R(1)) - B2
      C12  = R(3) * (R(3) + R(1)) - B2
      C21  = R(2) - R(4)
      C22  = R(3) - R(4)
      A(1) = (C31 * C22 - C32 * C21) / (C22 * C11 - C12 * C21)
      A(2) = (C31 - C11 * A(1)) / C21
      A(3) = B1 - (R(4) * R(4) + R(1) * R(1) + R(4) * R(1)) * A(1)
     1     - (R(4) + R(1)) * A(2)
      A(4) = Y1 - R(1) * (A(3) + R(1) * (A(2) + R(1) * A(1)))
      RETURN
      END SUBROUTINE GEN153
 
      SUBROUTINE GEN154 (A, B, IX, N)
C * SORT ON A
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: IFIN
      INTEGER :: INTX
      INTEGER, DIMENSION(N) :: IX
      REAL :: X
      REAL :: T
      REAL, DIMENSION(N) :: A
      REAL, DIMENSION(N) :: B
      INTX = 2
   10 INTX = 2 * INTX
      IF (INTX < N) GO TO 10
      INTX  = MIN0 (N, (3 * INTX) / 4 - 1)
   20 INTX  = INTX / 2
      IFIN  = N - INTX
      DO  K = 1, IFIN
        I = K
        J = I + INTX
        IF (A(I) < A(J)) THEN
          T     = A(J)
          X     = B(J)
          L     = IX(J)
   30     A(J)  = A(I)
          B(J)  = B(I)
          IX(J) = IX(I)
          J     = I
          I     = I - INTX
          IF (I > 0) THEN
            IF (A(I) < T) GO TO 30
          END IF
          A(J)  = T
          B(J)  = X
          IX(J) = L
        END IF
      END DO
      IF (INTX > 1) GO TO 20
      RETURN
      END SUBROUTINE GEN154
 
      SUBROUTINE GEN155 (MODE, A, ICKS)
C * CALCULATE CHECKSUM
      IMPLICIT NONE
      INTEGER       :: I
      INTEGER, SAVE :: M
      INTEGER       :: ICH
      INTEGER       :: MODE
      INTEGER       :: ICKS
      CHARACTER(len=*) :: A
C * M =  0 - INIT
C * M =  1 - ADD TO SUM
C * M = -1 - REPORT CHECKSUM
      IF (MODE == 1) THEN
        DO I = 1, LEN_TRIM (A)
          ICH = ICHAR (A(I:I))
          IF (ICH > 32) M = M + ICH
        END DO
      ELSE IF (MODE == 0) THEN
        M = 0
      ELSE IF (MODE == -1) THEN
        ICKS = MOD (MOD (MOD (M, 714025) * 1366 + 150889, 714025),
     1         100000)
      END IF
      RETURN
      END SUBROUTINE GEN155
 
      SUBROUTINE GEN156 (LABA)
C * MOVE LABEL CONTENT RIGHT
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      CHARACTER(len=9) :: LABA
      CHARACTER(len=9) :: LABB
      K = 10
      DO L = 1, 9
        IF (LABA(10 - L:10 - L) /= ' ') THEN
          K         = K - 1
          LABB(K:K) = LABA(10 - L:10 - l)
        END IF
      END DO
      IF (K > 1) THEN
        DO J = 1, K - 1
          LABB(J:J) = ' '
        END DO
      END IF
      LABA = LABB
      RETURN
      END SUBROUTINE GEN156
 
      SUBROUTINE GEN157 (D, IZ)
C * SOLVE EQUATION
      IMPLICIT NONE
      INTEGER :: IZ
      DOUBLE PRECISION :: A
      DOUBLE PRECISION :: B
      DOUBLE PRECISION :: C
      DOUBLE PRECISION :: G
      DOUBLE PRECISION :: E
      DOUBLE PRECISION :: F
      DOUBLE PRECISION, DIMENSION (*) :: D
      IF (IZ == 2) THEN
        A    =  D(1) * D(6)  - D(5)  * D(2)
        B    = -D(3) * D(6)  + D(5)  * D(4)
        D(3) =  D(1) * D(4)  - D(3)  * D(2)
        D(1) =  B
        D(2) =  A
      ELSE
        A    =  D(8) * D(12) - D(9)  * D(11)
        B    =  D(7) * D(12) - D(9)  * D(10)
        C    =  D(7) * D(11) - D(8)  * D(10)
        G    =  D(4) * A     - D(5)  * B     + D(6) * C
        E    = -D(1) * A     + D(2)  * B     - D(3) * C
        F    =  D(1) * (D(5) * D(9)  - D(6) * D(8))
     1       -  D(2) * (D(4) * D(9)  - D(6) * D(7))
     2       +  D(3) * (D(4) * D(8)  - D(5) * D(7))
        D(3) =  D(1) * (D(5) * D(12) - D(6) * D(11))
     1       -  D(2) * (D(4) * D(12) - D(6) * D(10))
     2       +  D(3) * (D(4) * D(11) - D(5) * D(10))
        D(1) =  G
        D(2) =  E
        D(4) =  F
      END IF
      RETURN
      END SUBROUTINE GEN157
 
      REAL FUNCTION GEN158 (CELA, CELSD, X1, X2, X3)
C * CALCULATE CELL ERROR CONTRIBUTION TO BOND ANGLE ERROR
      IMPLICIT NONE
      INTEGER               :: I
      INTEGER               :: J
      REAL                  :: S
      REAL                  :: A
      REAL                  :: B
      REAL                  :: SK
      REAL                  :: GEN159
      REAL, DIMENSION(*)    :: CELA
      REAL, DIMENSION(*)    :: CELSD
      REAL, DIMENSION(3)    :: X1
      REAL, DIMENSION(3)    :: X2
      REAL, DIMENSION(3)    :: X3
      REAL, DIMENSION(3, 3) :: RA
      REAL, DIMENSION(3, 3) :: RB
      REAL, DIMENSION(6)    :: CELB
      S = 45.0 / ATAN2 (1.0, 1.0)
      CALL GEN026 (1, RA, CELA)
      A = GEN159 (X1, X2, X3, RA) * S
      SK = 0.0
      DO I = 1, 6
        DO J = 1, 6
          CELB(J) = CELA(J)
        END DO
        IF (CELSD(I) > 0.0) THEN
          CELB(I) = CELB(I) + CELSD(I)
          CALL GEN026 (1, RB, CELB)
          B = GEN159 (X1, X2, X3, RB) * S
          SK = SK + (A - B)**2
        END IF
      END DO
      GEN158 = SK
      RETURN
      END
 
      REAL FUNCTION GEN159 (X1, X2, X3, R)
C * CALCULATE BOND ANGLE FOR BOND ANGL ERROR CALC
      IMPLICIT NONE
      REAL                  :: D1
      REAL                  :: D2
      REAL                  :: D3
      REAL                  :: GEN006
      REAL                  :: COSA
      REAL, DIMENSION(3, 3) :: R
      REAL, DIMENSION(3)    :: X1
      REAL, DIMENSION(3)    :: X2
      REAL, DIMENSION(3)    :: X3
      REAL, DIMENSION(3)    :: V
      v(1) = X1(1) - X2(1)
      v(2) = X1(2) - X2(2)
      v(3) = X1(3) - X2(3)
      D1 = GEN006 (V, R, V)
      v(1) = X2(1) - X3(1)
      v(2) = X2(2) - X3(2)
      v(3) = X2(3) - X3(3)
      D2 = GEN006 (V, R, V)
      v(1) = X1(1) - X3(1)
      v(2) = X1(2) - X3(2)
      v(3) = X1(3) - X3(3)
      D3 = GEN006 (V, R, V)
      IF (D1 > 0.0 .AND. D2 > 0.0) THEN
        COSA = (D1 + D2 - D3) / (2.0 * SQRT (D1)*SQRT (D2))
        IF (COSA < -1.0) COSA = -1.0
        IF (COSA >  1.0) COSA =  1.0
        GEN159 = ACOS (COSA)
      ELSE
        GEN159 = 0.0
      END IF
      RETURN
      END
 
      DOUBLE PRECISION FUNCTION GEN160 (IS)
C * RANDOM GENERATOR
      IMPLICIT NONE
      INTEGER,          PARAMETER    :: IA   = 16807
      INTEGER,          PARAMETER    :: IM   = 2147483647
      INTEGER,          PARAMETER    :: IQ   = 127773
      INTEGER,          PARAMETER    :: IR   = 2836
      INTEGER,          PARAMETER    :: NTAB = 32
      INTEGER,          PARAMETER    :: NDIV = 67108864
      DOUBLE PRECISION, PARAMETER    :: AM   = 1.0D0 / IM
      DOUBLE PRECISION, PARAMETER    :: EPS  = 1.2D-7
      DOUBLE PRECISION, PARAMETER    :: RNMX = 1.0D0 - EPS
      INTEGER                        :: J
      INTEGER                        :: K
      INTEGER, SAVE                  :: IY
      INTEGER                        :: IS
      INTEGER, SAVE, DIMENSION(NTAB) :: IV
      DATA IV /NTAB*0/, IY /0/
      IF (IS <= 0 .OR. IY == 0) THEN
        IS = MAX (-IS, 1)
        DO J = NTAB + 8, 1, -1
          K = IS / IQ
          IS = IA * (IS - K * IQ) - IR * K
          IF (IS < 0) IS = IS + IM
          IF (J <= NTAB) IV(J) = IS
        END DO
        IY = IV(1)
      END IF
      K  = IS / IQ
      IS = IA * (IS - K * IQ) - IR * K
      IF (IS < 0) IS = IS + IM
      J      = 1 + IY / NDIV
      IY     = IV(J)
      IV(J)  = IS
      GEN160 = MIN (AM * IY, RNMX)
      RETURN
      END FUNCTION GEN160
 
      SUBROUTINE GEN161 (A, R)
C * DP-EIGEN
      IMPLICIT NONE
      INTEGER                        :: I
      INTEGER                        :: J
      INTEGER                        :: K
      INTEGER                        :: L
      INTEGER                        :: M
      INTEGER                        :: IA
      INTEGER                        :: IJ
      INTEGER                        :: IQ
      INTEGER                        :: IL
      INTEGER                        :: IM
      INTEGER                        :: MQ
      INTEGER                        :: LQ
      INTEGER                        :: LM
      INTEGER                        :: LL
      INTEGER                        :: JQ
      INTEGER                        :: MM
      INTEGER                        :: IND
      INTEGER                        :: ILQ
      INTEGER                        :: IMQ
      INTEGER                        :: ILR
      INTEGER                        :: IMR
      DOUBLE PRECISION               :: X
      DOUBLE PRECISION               :: Y
      DOUBLE PRECISION               :: THR
      DOUBLE PRECISION               :: SINX
      DOUBLE PRECISION               :: COSX
      DOUBLE PRECISION               :: SINX2
      DOUBLE PRECISION               :: COSX2
      DOUBLE PRECISION               :: SINCS
      DOUBLE PRECISION               :: ANORM
      DOUBLE PRECISION               :: BEREIK
      DOUBLE PRECISION               :: ANRMX
      DOUBLE PRECISION, DIMENSION(9) :: A
      DOUBLE PRECISION, DIMENSION(9) :: R
      BEREIK = 1.0D-6
      IQ    = -3
      DO J = 1, 3
        IQ = IQ + 3
        DO I = 1, 3
          IJ = IQ + I
          R(IJ) = 0.0D0
          IF (I == J) R(IJ) = 1.0D0
        END DO
      END DO
      ANORM = 0.0D0
      DO I = 1, 3
        DO J = I, 3
          IF (I /= J) THEN
            IA = I + (J * J - J) / 2
            ANORM = ANORM + A(IA) * A(IA)
          END IF
        END DO
      END DO
      IF (ANORM > 0) THEN
        ANORM = 1.414D0 * SQRT (ANORM)
        ANRMX = ANORM * BEREIK / 3.0D0
        IND = 0
        THR = ANORM
        THR = THR / 3.0D0
        L = 1
        M = L + 1
   10   MQ = (M * M - M) / 2
        LQ = (L * L - L) / 2
        LM = L + MQ
        IF (ABS (A(LM)) >= THR) THEN
          IND = 1
          LL = L + LQ
          MM = M + MQ
          X = 0.5D0 * (A(LL) - A(MM))
          Y = -A(LM) / SQRT (A(LM) * A(LM) + X * X)
          IF (X < 0.0D0) Y = -Y
          SINX = Y / SQRT (2.0D0 * (1.0D0 + (SQRT (1.0D0 - Y * Y))))
          SINX2 = SINX * SINX
          COSX = SQRT (1.0D0 - SINX2)
          COSX2 = COSX * COSX
          SINCS = SINX * COSX
          ILQ   = 3 * (L - 1)
          IMQ   = 3 * (M - 1)
          DO I = 1, 3
            IQ = (I * I - I) / 2
            IF (I /= L) THEN
              IF (I /= M) THEN
                IF (I < M) THEN
                  IM = I + MQ
                ELSE IF (I > M) THEN
                  IM = M + IQ
                END IF
                IF (I < L) THEN
                  IL = I + LQ
                ELSE
                  IL = L + IQ
                END IF
                X  = A(IL) * COSX - A(IM) * SINX
                A(IM) = A(IL) * SINX + A(IM) * COSX
                A(IL) = X
              END IF
            END IF
            ILR = ILQ + I
            IMR = IMQ + I
            X = R(ILR) * COSX - R(IMR) * SINX
            R(IMR) = R(ILR) * SINX + R(IMR) * COSX
            R(ILR) = X
          END DO
          X     = 2.0D0 * A(LM) * SINCS
          Y     = A(LL) * COSX2 + A(MM) * SINX2 - X
          X     = A(LL) * SINX2 + A(MM) * COSX2 + X
          A(LM) = (A(LL) - A(MM)) * SINCS + A(LM) * (COSX2 - SINX2)
          A(LL) = Y
          A(MM) = X
        END IF
        IF(M /= 3) THEN
          M = M + 1
          GO TO 10
        END IF
        IF (L /= 2) THEN
          L = L + 1
          M = L + 1
          GOTO 10
        END IF
        IF (IND == 1) THEN
          IND = 0
          L   = 1
          M   = L + 1
          GOTO 10
        END IF
        IF (THR > ANRMX) THEN
          THR = THR / 3.0D0
          L   = 1
          M   = L + 1
          GOTO 10
        END IF
      END IF
      IQ = -3
      DO I = 1, 3
        IQ = IQ + 3
        LL = I + (I * I - I) / 2
        JQ = 3 * (I - 2)
        DO J = I, 3
          JQ = JQ + 3
          MM = J + (J * J - J) / 2
          IF (A(LL) < A(MM)) THEN
            X = A(LL)
            A(LL) = A(MM)
            A(MM) = X
            DO K = 1, 3
              ILR = IQ + K
              IMR = JQ + K
              X   = R(ILR)
              R(ILR) = R(IMR)
              R(IMR) = X
            END DO
          END IF
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN161
 
      SUBROUTINE GEN162 (P, Y, MP0, NP, NDIM, FTOL, FUNK, ITER)
C * AMOEBA
      IMPLICIT NONE
      INTEGER, PARAMETER       :: NMAX  = 20
      INTEGER, PARAMETER       :: ITMAX = 500
      REAL,    PARAMETER       :: ALPHA = 1.0
      REAL,    PARAMETER       :: BETA  = 0.5
      REAL,    PARAMETER       :: GAM   = 2.0
      INTEGER                  :: I
      INTEGER                  :: J
      INTEGER                  :: NP
      INTEGER                  :: MP0
      INTEGER                  :: ILO
      INTEGER                  :: IHI
      INTEGER                  :: INHI
      INTEGER                  :: NDIM
      INTEGER                  :: ITER
      INTEGER                  :: MPTS
      REAL                     :: YPR
      REAL                     :: FUNK
      REAL                     :: YPRR
      REAL                     :: FTOL
      REAL                     :: RTOL
      REAL, DIMENSION(MP0, NP) :: P
      REAL, DIMENSION(MP0)     :: Y
      REAL, DIMENSION(NMAX)    :: PR
      REAL, DIMENSION(NMAX)    :: PRR
      REAL, DIMENSION(NMAX)    :: PBAR
      EXTERNAL FUNK
      MPTS = NDIM + 1
      ITER = 0
      DO WHILE (.TRUE.)
        ILO = 1
        IF (Y(1) > Y(2)) THEN
          IHI  = 1
          INHI = 2
        ELSE
          IHI  = 2
          INHI = 1
        END IF
        DO I = 1, MPTS
          IF (Y(I) < Y(ILO)) ILO = I
          IF (Y(I) > Y(IHI)) THEN
            INHI = IHI
            IHI  = I
          ELSE IF (Y(I) > Y(INHI)) THEN
            IF (I /= IHI) INHI = I
          END IF
        END DO
        RTOL = 2.0 * ABS (Y(IHI) - Y(ILO)) / (ABS (Y(IHI))
     1       + ABS (Y(ILO)))
        IF (RTOL < FTOL) RETURN
        IF (ITER == ITMAX)
     1    CALL TRAILER ('GEN033 exceeding maximum iterations.')
        ITER = ITER + 1
        CALL GEN074 (PBAR, 1, NDIM, 0.0)
        DO I = 1, MPTS
          IF (I /= IHI) THEN
            DO J = 1, NDIM
              PBAR(J) = PBAR(J) + P(I, J)
            END DO
          END IF
        END DO
        DO J = 1, NDIM
          PBAR(J) = PBAR(J) / NDIM
          PR(J)   = (1.0 + ALPHA) * PBAR(J) - ALPHA * P(IHI, J)
        END DO
        YPR = FUNK(PR)
        IF (YPR <= Y(ILO)) THEN
          DO J = 1, NDIM
            PRR(J) = GAM * PR(J) + (1.0 - GAM) * PBAR(J)
          END DO
          YPRR = FUNK(PRR)
          IF (YPRR < Y(ILO)) THEN
            DO J = 1, NDIM
              P(IHI, J) = PRR(J)
            END DO
            Y(IHI) = YPRR
          ELSE
            DO J = 1, NDIM
              P(IHI, J) = PR(J)
            END DO
            Y(IHI) = YPR
          END IF
        ELSE IF (YPR >= Y(INHI)) THEN
          IF (YPR < Y(IHI)) THEN
            DO J = 1, NDIM
              P(IHI, J) = PR(J)
            END DO
            Y(IHI) = YPR
          END IF
          DO J = 1, NDIM
            PRR(J) = BETA * P(IHI, J) + (1.0 - BETA) * PBAR(J)
          END DO
          YPRR = FUNK(PRR)
          IF (YPRR < Y(IHI)) THEN
            DO J = 1, NDIM
              P(IHI, J) = PRR(J)
            END DO
            Y(IHI) = YPRR
          ELSE
            DO I = 1, MPTS
              IF(I /= ILO) THEN
                DO J = 1, NDIM
                  PR(J) = 0.5 * (P(I, J) + P(ILO, J))
                  P(I, J) = PR(J)
                END DO
                Y(I) = FUNK(PR)
              END IF
            END DO
          END IF
        ELSE
          DO J = 1, NDIM
            P(IHI, J) = PR(J)
          END DO
          Y(IHI) = YPR
        END IF
      END DO
      RETURN
      END SUBROUTINE GEN162
 
 
      REAL FUNCTION GEN163 (C, D, K, N)
C * CALCULATE VOLUME FROM CELL DATA (SUPPORT FOR GEN068)
      IMPLICIT NONE
      INTEGER            :: K
      INTEGER            :: N
      REAL               :: V
      REAL               :: SA
      REAL               :: SB
      REAL               :: SG
      REAL               :: CA
      REAL               :: CB
      REAL               :: CG
      REAL               :: DTR
      REAL, DIMENSION(6) :: C
      REAL, DIMENSION(6) :: D
      V   = 0.0
      DTR = 45.0 / ATAN2 (1.0, 1.0)
C * add S.U. for parameter N
      IF (N > 0) C(N) = C(N) + D(N)
      SA  = SIN (C(4) / DTR)
      SB  = SIN (C(5) / DTR)
      SG  = SIN (C(6) / DTR)
      CA  = COS (C(4) / DTR)
      CB  = COS (C(5) / DTR)
      CG  = COS (C(6) / DTR)
C * TRICLINIC
      IF (K == 1) THEN
        V = C(1) * C(2) * C(3) * SQRT (1.0 - CA**2 - CB**2 - CG**2 +
     1       2.0 * CA * CB * CG)
C * MONOCLINIC-b
      ELSE IF (K == 2) THEN
        V = C(1) * C(2) * C(3) * SB
C * ORTHORHOMBIC
      ELSE IF (K == 3) THEN
        V = C(1) * C(2) * C(3)
C * TRIGONAL & HEXAGONAL
      ELSE IF (K == 4 .OR. K == 6) THEN
        V = C(3) * (C(1)**2) * SG
C * TETRAGONAL
      ELSE IF (K == 5) THEN
        V = C(3) * C(1)**2
C * CUBIC
      ELSE IF (K == 7) THEN
        V = C(1)**3
C * RHOMBOHEDRAL
      ELSE IF (K == 8) THEN
        V = (C(1)**3) * SQRT (1.0 - 3.0 * CA**2 + 2.0 * CA**3)
C * MONOCLINIC-c
      ELSE IF (K == 9) THEN
        V = C(1) * C(2) * C(3) * SG
C * MONOCLINIC-a
      ELSE IF (K == 10) THEN
        V = C(1) * C(2) * C(3) * SA
      END IF
      IF (N > 0) C(N) = C(N) - D(N)
      GEN163 = V
      RETURN
      END FUNCTION GEN163
 
      SUBROUTINE GEN164 (A, B)
C * CONVERT A(3, 3) TO B(9)
      IMPLICIT NONE
      INTEGER               :: I
      INTEGER               :: J
      INTEGER               :: K
      REAL, DIMENSION(3, 3) :: A
      REAL, DIMENSION(9)    :: B
      K = 0
      DO J = 1, 3
        DO I = 1, 3
          K = K + 1
          B(K) = A(I, J)
        END DO
      END DO
      RETURN
      END SUBROUTINE GEN164
 
      SUBROUTINE GEN165 (U, T, P)
 
C * MULTIPLY TWO '3X3' MATRICES (stored as rows)
      IMPLICIT NONE
      REAL, DIMENSION(9) :: U
      REAL, DIMENSION(9) :: T
      REAL, DIMENSION(9) :: P
      P(1) = T(1) * U(1) + T(4) * U(2) + T(7) * U(3)
      P(2) = T(2) * U(1) + T(5) * U(2) + T(8) * U(3)
      P(3) = T(3) * U(1) + T(6) * U(2) + T(9) * U(3)
      P(4) = T(1) * U(4) + T(4) * U(5) + T(7) * U(6)
      P(5) = T(2) * U(4) + T(5) * U(5) + T(8) * U(6)
      P(6) = T(3) * U(4) + T(6) * U(5) + T(9) * U(6)
      P(7) = T(1) * U(7) + T(4) * U(8) + T(7) * U(9)
      P(8) = T(2) * U(7) + T(5) * U(8) + T(8) * U(9)
      P(9) = T(3) * U(7) + T(6) * U(8) + T(9) * U(9)
      RETURN
      END SUBROUTINE GEN165
 
      INTEGER FUNCTION GEN166 (ICH)
C * GET CHARACTER TYPE
      IMPLICIT NONE
      INTEGER          :: I
      CHARACTER(len=1) :: ICH
      GEN166 = -3
C * CHECK FOR SPACE
      IF (ICH == CHAR(32)) THEN
        GEN166 = -2
        RETURN
      END IF
C * CHECK FOR UPPER CASE CHARACTER
      DO I = ICHAR ('A'), ICHAR ('Z')
        IF (ICH == CHAR (I)) THEN
          GEN166 = 1
          RETURN
        END IF
      END DO
C * CHECK FOR LOWER CASE CHARACTER
      DO I = ICHAR ('a'), ICHAR ('z')
        IF (ICH == CHAR (I)) THEN
          GEN166 = -1
          RETURN
        END IF
      END DO
C * CHECK FOR NUMERAL
      DO I = 1, 10
        IF (ICH == CHAR (ICHAR ('0') - 1 + I)) THEN
          GEN166 = 0
          RETURN
        END IF
      END DO
      RETURN
      END FUNCTION GEN166
