C *====================================================================C
      SUBROUTINE PLUTON (MPLUT)
C *====================================================================C
C *                                                                    C
C *                          P L U T O N                               C
C *                       =================                            C
C *                                                                    C
C *         PROGRAM FOR THE AUTOMATED DISPLAY AND ANALYSIS OF          C
C *                                                                    C
C *                  CRYSTAL AND MOLECULAR STRUCTURES                  C
C *                           =========                                C
C *                                                                    C
C * (C) 1979-2026  A.L. SPEK, UTRECHT UNIVERSITY, THE NETHERLANDS.     C
C *                                                                    C
C *                         PROGRAM HISTORY                            C
C *                         ===============                            C
C * CDC NOS/BE        IMPLEMENTATION (PLUTO78/Clegg) & EXTENSION  1979 C
C * MICROVAX-II/VMS   IMPLEMENTATION & EXTENSION ................ 1986 C
C * IBM-PC/AT         IMPLEMENTATION ............................ 1986 C
C * CDC-CYBER -NOS/VE IMPLEMENTATION ............................ 1986 C
C * CONVEX-UNIX       IMPLEMENTATION ............................ 1989 C
C * SILICON-GRAPHICS  IMPLEMENTATION ............................ 1990 C
C * DECstation5000    IMPLEMENTATION & EXTENSION ................ 1990 C
C * IBM-RS/6000       IMPLEMENTATION ............................ 1992 C
C * 80386/Linux       IMPLEMENTATION ............................ 1992 C
C * SG-Challenge      IMPLEMENTATION ............................ 1993 C
C * AXP/OSF           IMPLEMENTATION ............................ 1993 C
C * DEC-Alpha         INTEGRATION within PLATON AS A TOOL ....... 1997 C
C * MAC OSX (Intel)   ........................................... 2009 C
C * MAC OS  (M1)      ........................................... 2020 C
C *                                                                    C
C * THIS VERSION INCLUDES  FEATURES FOR INTERACTIVE USE OF THE PROGRAM C
C * WITH                                             X-Window/UNIX     C
C *                HPGL,POSTSCRIPT                 - META FILE         C
C *                                                                    C
C *====================================================================C
C *                        Acknowledgement                             C
C * PLUTON has evolved by an evolutionary proces from the source code  C
C * of PLUTO-78 (Motherwell & Clegg). The current version probably     C
C * doesn't contain any original code and is several times larger than C
C * the original version.                                              C
C *********************************************************************C
C * NP12  -  DIMENSION ARRAY IPR                                       C
C * NP13  -  DIMENSION ARRAY PAR                                       C
C * NP9   -  NUMBER OF ELEMENT LABELS                                  C
C * NP10  -  MAXIMUM NUMBER OF ELEMENT TYPES PER STRUCTURE             C
C * NP32  -  MAX. NR. OF RESIDUES                                      C
C * NP33  -  MAX NUMBER OF BONDS IN FLAG ARRAY                         C
C * NP43  -  NUMBER OF ITEMS STORED PER ATOM                           C
C *********************************************************************C
C * BIT  1- 2    : INTERNAL TO PLUT07                                  C
C * BIT  3- 4    : MOVE BITS                                           C
C * BIT  5-10    : RESIDUE NUMBER OF ATOM AS FOUND BY PLUT07           C
C * BIT 11-16    : ARU-NUMBER - 1 (0:63)                               C
C * BIT    17    : METAL BIT                                           C
C * BIT 18-23    : MULTIPLICITY                                        C
C * BIT 24-26    : NR OF CONNECTIONS TO OXYGEN                         C
C * BIT    27    : INCLUDE ATOM BIT                                    C
C * BIT 28-31    : DISORDER PARAMETER POINTER                          C
C * BIT    32    : DOAC-H                                              C
C * BIT 33-36    : NR OF BONDS (0:15)                                  C
C * BIT 37-40    : LABEL POSITION                                      C
C * BIT    41    : ANIS                                                C
C * BIT    42    : PUT LABEL INSTR                                     C
C * BIT    43    : MOVE ATOM BIT                                       C
C * BIT    44    : H-ATOM BIT                                          C
C * BIT    45    : (NO) LABEL ATOM/ATOM OVERLAP                        C
C * BIT    46    : DOAC -ATOM                                          C
C * BIT    47    : (0/1) GREEN LABEL                                   C
C * BIT 48-52    : SHELXL PART # + 16                                  C
C * BIT  1- 5    : ARU COLOR   ATOM                                    C
C * BIT  6-10    : ARU PATTERN ATOM                                    C
C * BIT 11-15    : ARU COLOR   BOND                                    C
C * BIT 16-20    : ARU LINES   BOND                                    C
C *====================================================================C
C *                      -------------                                 C
C *                      F  I  L  E  S                                 C
C *                      -------------                                 C
C *  UNIT 1  -  STANDARD PARAMETER INPUTFILE (SPF)                     C
C *  UNIT 2  -  DEFAULT INSTRUCTION FILE                               C
C *  UNIT 3  -  SAVE FILE FOR INSTRUCTIONS                             C
C *  UNIT 5  -  INTERACTIVE INPUT FROM CONSOLE                         C
C *  UNIT 6  -  INTERACTIVE OUTPUT TO  CONSOLE                         C
C *  UNIT 9  -  JOURNAL FILE OF INSTRUCTIONS                           C
C *                                                                    C
C *====================================================================C
C * PLUTON            - INPUT read/interpretation                      C
C * PLUT01            - INITIALISATION full/partial                    C
C * PLUT02            - PLOTTING (ATOMS, BONDS, LABELS)                C
C * PLUT03            - ATOM CARD HANDLING                             C
C * PLUT04            - LABEL Setting and plotting                     C
C * PLUT05            - SET UP OF BOND arrays                          C
C * PLUT06            - VIEW option management                         C
C * PLUT07            - BOND DISTANCE scanning                         C
C * PLUT08            - GENERATE MINIMUM OVERLAP ROTATION MATRIX       C
C * PLUT09            - IN/EX-CLUDE MANAGEMENT OF ATOMS                C
C * PLUT10            - BOND DRAWING                                   C
C * PLUT11            - ATOM CIRCLE DRAWING                            C
C * PLUT12            - MANAGEMENT OF MOST PRINTING                    C
C * PLUT13            - ATOM NAME PROCESSING                           C
C * PLUT14            - PLOT ATOM ITEM STORAGE/RETRIEVAL MANAGEMENT    C
C * PLUT15            - ATOM FLAG STORAGE/RETRIEVAL                    C
C * PLUT16            - BOND STORAGE AND RETRIEVAL                     C
C * PLUT17            - MANAGEMENT OF ARU (=MOLES) ARRAY               C
C * PLUT18            - GENERATE OBSCURATION LIST                      C
C * PLUT19            - OBSCURATION MANAGEMENT                         C
C * PLUT20            - INTERSECTION TEST                              C
C * PLUT21            - MANAGEMENT OF THE VARIOUS RADIUS OPTIONS       C
C * PLUT22            - CALCULATE DISTANCE                             C
C * PLUT23            - ORTHOGONALISATION MANAGEMENT                   C
C * PLUT24            - AD_HOC GEOMETRY CALCULATION                    C
C * PLUT25            - UNPACK LABEL INFORMATION                       C
C * PLUT26            - GENERATION OF LABEL POSITIONS                  C
C * PLUT27            - GET RBO & NLI                                  C
C * PLUT28            - HANDLE SPECIAL JOIN/LABEL/VIEW/DIST ARU        C
C * PLUT29            - RENAME/DELETE ETC RES-FILE                     C
C * PLUT30            - ACTUAL CIRCLE PLOTTING                         C
C * PLUT31            - PUT DIAMOND                                    C
C * PLUT32            - RENAME RES FILE LABELS                         C
C * PLUT33            - LOAD UNITCELL PLOT DATA                        C
C * PLUT35            - EXPAND ARU/MOLECULE                            C
C * PLUT36            - SHADE MODE                                     C
C * PLUT37            - ANGLE, TORSION CALCULATION                     C
C * PLUT38            - ERROR HANDLING                                 C
C * PLUT39            - PACK RANGE/PLAN                                C
C * PLUT40            - TEST FOR D-H                                   C
C * PLUT41            - SUPPORT RENAME                                 C
C * PLUT42            - SUPPORT HFIX                                   C
C * PLUT43            - FIND NEAREST ITEM                              C
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE pluto
      USE chdat
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: NA
      INTEGER :: KN
      INTEGER :: KL
      INTEGER :: IP
      INTEGER :: IS
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: NN
      INTEGER :: NS
      INTEGER :: NSS
      INTEGER :: NED
      INTEGER :: NEI
      INTEGER :: KN7
      INTEGER :: KL0
      INTEGER :: KLI
      INTEGER :: KLM
      INTEGER :: IMD
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: IER
      INTEGER :: ISW
      INTEGER :: NAX
      INTEGER :: NQX
      INTEGER :: NATL
      INTEGER :: NATX
      INTEGER :: IVAL
      INTEGER :: ITRS
      INTEGER :: ICOL
      INTEGER :: IDUM
      INTEGER :: IEND
      INTEGER :: IBWC
      INTEGER :: IBEG
      INTEGER :: IAT1
      INTEGER :: IATK
      INTEGER :: IASU
      INTEGER :: IHAT
      INTEGER :: IPDC
      INTEGER :: JUNK
      INTEGER :: KADD
      INTEGER :: MNFX
      INTEGER :: MODE
      INTEGER :: NIEN
      INTEGER :: NQSM
      INTEGER :: NPROP
      INTEGER :: KSTEP
      INTEGER :: IXPK1
      INTEGER :: IXPK2
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: MPLUT
      INTEGER :: IGBL8
      INTEGER :: MADDR
      INTEGER :: MNFIX
      INTEGER :: NHAUTO
      INTEGER :: MSUBST
      INTEGER :: IGBL30
      REAL :: XL
      REAL :: YL
      REAL :: ZL
      REAL :: RL
      REAL :: P15
      REAL :: DET
      REAL :: FNK
      REAL :: XDUM
      REAL :: PAR40
      CHARACTER(len=2)  :: JK12
      CHARACTER(len=3)  :: JK13
      CHARACTER(len=3)  :: N12
      CHARACTER(len=5)  :: J215
      CHARACTER(len=7)  :: CLR
      CHARACTER(len=10) :: BCKG
      CHARACTER(len=10) :: BCOL
      CHARACTER(len=10) :: IFLNQ
      CHARACTER(len=20) :: HCOL
C * MPLUT = -1 - NATIVE, RENAME, HFIX, ANIS FLAGS
C * MPLUT =  0 - SYSTEM S-MODE
C * MPLUT =  1 - CALLED FROM PLATON
C * MPLUT =  2 - CALLED FROM ADDSYM
      IGBL30   = 0
      IGBL8    = 0
      PAR40    = 0.0
      IGBL(63) = 0
C * MAIN PLUTON ROUTINE
      IF (MPLUT /= 0) THEN
C * TEST FOR NATIVE, RENAME, HFIX, ANIS FLAGS
        IF (MPLUT < 0) THEN
          INQUIRE (UNIT = LU1, OPENED = OPEND)
          IF (OPEND) CLOSE (UNIT = LU1)
C * TEST FOR FROM PLATON OR ADDSYM
        ELSE IF (MPLUT > 0) THEN
C * TEST FOR OUTPUT TYPE ON LU2
          IF (IGBL(31) /= 0) THEN
            CLOSE (UNIT = LU2, IOSTAT = IOST)
            IGBL(31) = 0
            IGBL(2)  = 0
          END IF
          IGBL(23) = 0
        END IF
C * TEST FOR CIF
        IF (IABS(IGBL(8)) == 3) THEN
          FN(1) = IGBL(54)
C * SET 'CALC ADDSYM' to DEFAULT ZERO
          IPR(205) = 0
          IPR(220) = 1
          IPR(221) = 1
C * HANDLE MULTIPLE ENTRY INPUT FILE
          CALL PLA007
        END IF
        IGBL30 = IGBL(30)
        IGBL8  = IGBL(8)
        IF (IPR(504) == 1) IGBL(30) = 0
C * MPLUT = 0 CASE
      ELSE
        INQUIRE (UNIT = LU23, OPENED = OPEND)
        IF (OPEND) CLOSE (UNIT = LU23)
      END IF
C * INIT
      CALL PLUT01 (-1)
C * LOOP: READ AND INTERPRET UNTIL FIRST PLOT INSTRUCTION
C * MOUSE LOOP - CHECK # PLOT (= IGBL(2))
   10 IF (IGBL(2) > 0) THEN
C * TEST FOR 'AUTO-S'-MODE
        IF (IGBL(50) == 0) THEN
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          IF (IGGT(1:3) == 'END') IGBL(2) = -1
        ELSE
C * HFIX
          IF (IGBL(3) == 13) THEN
            CALL PLA280 ('HFIX')
C * ANIS
          ELSE IF (IGBL(3) == 26) THEN
            CALL PLA280 ('ANIS')
          END IF
        END IF
      END IF
      IGBL(2) = IGBL(2) + 1
      IF (IGBL(2) == 0) GO TO 300
C * INITIALISE
      ISW = 0
   20 CALL PLUT01 (0)
C * CHECK for AUTO-PLOT
      IF (IGBL(35) == 1) GO TO 50
      IGBL(24) = 1
      IF (IGBL(5) == LU23) IGBL(5) = LU5
C * ALL DATA RECORDS READ HERE (UNIT IGBL(5) = LU1, LU23, LU3 OR LU5)
C * LU1  = CRYSTALLOGRAPHIC PARAMETER DATA
C * LU3  = SAVE FILE INSTRUCTIONS
C * LU5  = INTERACTIVE INPUT INSTRUCTIONS
C * LU23 = DEFAULT INSTRUCTIONS
   30 CALL GEN038 (IGGT, 1, 80)
      IF (IGBL(5) * IGBL(24) * IGBL(25) == LU5) THEN
        IF (IGBL(50) == 0) THEN
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          IF (IGGT(1:1) == ' ') GO TO 30
        ELSE
          GO TO 290
        END IF
      END IF
      GO TO 50
C * AUTO-PLOT
   40 IF (IGBL(5) * IGBL(24) * IGBL(25) == LU5) THEN
        IF (IGBL(35) /= 1) GO TO 30
        CALL PLA280 ('PLOT')
      END IF
C * FREE FORMAT READ LOOP
C * THE INPUT FILE CAN BE SPF, RES, CIF OR PDB STYLE
   50 CALL PLA006 (1, ISW)
      IF (IGBL(8) == 0) THEN
        IF (ICL(1:1) == '#') GO TO 50
      END IF
C * INIT 'RESET'
      IPR(170) = 0
      IF (ISW > 1) THEN
C * CHECK ISAVE (IGBL(45))
        IF (IGBL(5) == LU5 .AND. IGBL(45) > 0) THEN
          WRITE (LU3, 99987, IOSTAT = IOST) ICL(1:80)
          WRITE (LU6, 99978, IOSTAT = IOST) ICL(1:70)
C * ISW = 14 = END
          IF (ISW /= 14) THEN
C * COUNT # SAVE RECORDS
            IGBL(45) = IGBL(45) + 1
          ELSE
            IGBL(45) = -1
          END IF
        END IF
      ELSE IF (ISW < 1) THEN
        GO TO 250
      END IF
      KL = IPR(220)
      KN = IPR(221)
      IF (KL == 0 .AND. KN == 0) GO TO 50
C * ISW = 1: ATOM ? DATA
      IF (ISW == 1) THEN
        GO TO 120
C * ISW = 2: TITL - TITLE FOR PLOT
      ELSE IF (ISW == 2) THEN
        JID(1:74) = ICL(5:78)
        GO TO 220
C * ISW = 3: MESS - MESSAGE DISPLAY
      ELSE IF (ISW == 3) THEN
        WRITE (LU6, 99976, IOSTAT = IOST) ICL(5:80)
        GO TO 220
C * ISW = 4: REMARK
      ELSE IF (ISW == 4) THEN
        GO TO 220
C * ISW = 5: CELL CONSTANTS
      ELSE IF (ISW == 5) THEN
        IF (KN == 1) THEN
          FN(2)    = FN(1)
          FN(3)    = FN(1)
          IPR(221) = 3
          KN       = IPR(221)
        END IF
        IF (KN == 3) THEN
          FN(4)    = 90.0
          FN(5)    = 90.0
          FN(6)    = 90.0
          IPR(221) = 6
          KN       = IPR(221)
        END IF
        IF (KN == 6) THEN
          KN7 = 0
        ELSE IF (KN == 7) THEN
          KN7 = 1
        ELSE
          IPR(72) = 1
          GO TO 220
        END IF
        DO I = 1, 6
          PAR(100 + I) = FN(I + KN7)
        END DO
C * SET FOR FRACTIONAL COORDINATE DATA EXPECTED
        IPR(50) = 0
        GO TO 220
C * ISW = 6: SPGR
      ELSE IF (ISW == 6) THEN
        GO TO 110
C * ISW = 7: LATT
      ELSE IF (ISW == 7) THEN
        GO TO 110
C * ISW = 8: LIST
      ELSE IF (ISW == 8) THEN
        GO TO 240
C * ISW = 9: SYMM
      ELSE IF (ISW == 9) THEN
        GO TO 110
C * ISW = 10: ANGSTROM
      ELSE IF (ISW == 10) THEN
        IF (KL == 1) THEN
          IF (IPR(50) == 0 .AND. PAR(101) > 0.0) THEN
            IPR(156) = 1
          ELSE
            IPR(50) = - 1
            IF (KN >= 1) PAR(11) = FN(1)
          END IF
        END IF
        GO TO 220
C * ISW = 11: ROD MODE
      ELSE IF (ISW == 11) THEN
        IF (IPR(4) /= 2 .OR. KL == 1) THEN
          IPR(4) = 2
          CALL PLUT21 (-1)
        END IF
        GO TO 170
C * ISW = 12: ATOM RECORD
      ELSE IF (ISW == 12) THEN
        GO TO 120
C * ISW = 13: JOIN (CALC)
      ELSE IF (ISW == 13) THEN
        GO TO 140
C * ISW = 14: END
      ELSE IF (ISW == 14) THEN
        IF (IGBL(5) == LU1 .AND. IGBL(8) == 2 .AND.
     1      IGBL(95) /= 0) THEN
          GO TO 30
        ELSE
         GO TO 260
        END IF
C * ISW = 17: U
      ELSE IF (ISW == 17) THEN
        GO TO 130
C * ISW = 18/161: VIE(W)
      ELSE IF (ISW == 18 .OR. ISW == 161) THEN
        CALL PLUT06
        GO TO 220
C * ISW = 19/162: SOL(ID) MODE
      ELSE IF (ISW == 19 .OR. ISW == 162) THEN
        IF (IPR(4) /= 1 .OR. KL == 1) THEN
          IPR(4) = 1
          CALL PLUT21 (-1)
        END IF
      GO TO 170
C * ISW = 20/163: STI(CK) MODE
      ELSE IF (ISW == 20 .OR. ISW == 163) THEN
        IPR(4) = 0
        CALL PLUT21 (-1)
        GO TO 170
C * ISW = 21/158: LAB(EL) - INSTRUCTION
      ELSE IF (ISW == 21 .OR. ISW == 158) THEN
        CALL PLUT04 (2, 0)
        GO TO 220
C * ISW = 22/164: UNL(ABEL) - INSTRUCTION
      ELSE IF (ISW == 22 .OR. ISW == 164) THEN
        CALL PLUT04 (3, 0)
        GO TO 220
C * ISW = 23: PUT INSTRUCTION
      ELSE IF (ISW == 23) THEN
        CALL PLUT04 (4, 0)
        GO TO 220
C * ISW = 24: RADII - INSTRUCTION
      ELSE IF (ISW == 24) THEN
        CALL PLUT21 (0)
        GO TO 220
C * ISW = 25/168: PAC(KING) DIAGRAM CONTROL
      ELSE IF (ISW == 25 .OR. ISW == 168) THEN
        IF (IPR(37) == IPR(69)) THEN
          WRITE (LU6, 99993, IOSTAT = IOST)
          IPR(72) = 8
        ELSE
          IF (IPR(17) == 0) THEN
            CALL PLUT05
C * CALL EXIT/STOP
            IF (IPR(72) /= 0) CALL GEN127 ('304')
          END IF
          CALL PLUT39
          IPR(46) = 1
        END IF
        GO TO 220
C * ISW = 26: MOLES/ARU
      ELSE IF (ISW == 26) THEN
        GO TO 180
C * ISW = 27/165: INC(LUDE)
      ELSE IF (ISW == 27 .OR. ISW == 165) THEN
        N = 1
        GO TO 210
C * ISW = 28/166: EXC(LUDE)
      ELSE IF (ISW == 28 .OR. ISW == 166) THEN
        N = 0
        GO TO 210
C * ISW = 29/167: UNITCELL TO BE PLOTTED(OR UNIT CARD)
      ELSE IF (ISW == 29 .OR. ISW == 167) THEN
        IF (IPR(37) > IPR(69)) THEN
          IF (IPR(50) == 0) THEN
            IF (KL > 1 .AND. IFL(2)(2:2) == 'F') THEN
              IPR(46) = 0
            ELSE
              IPR(46) = 1
            END IF
C * SET INCLUDE BIT
            DO I = 1, 8
              CALL PLUT15 (1, I, 27, IPR(46))
            END DO
            IF (KN == 2) THEN
              PAR(75)  = FN(1)
              IPR(107) = NINT (FN(2))
            END IF
C * SET REBUILD
            IPR(130) = 0
          ELSE
            GO TO 30
          END IF
        ELSE IF (IABS (IGBL(8)) == 2) THEN
          DO I = 1, KN
            NUNIT(I) = NINT (FN(I))
          END DO
          GO TO 220
        END IF
        GO TO 220
C * ISW = 30: RETRACE INSTRUCTION
      ELSE IF (ISW == 30) THEN
        IF (KN > 0) THEN
          IF (KL > 1) THEN
            IF (IFL(2)(1:1) /= 'L') THEN
              IF (IFL(2)(1:1) == 'A') THEN
C * RETRACE ATOMS
                IPR(5) = NINT (FN(1))
                IF (KN == 2) PAR(3) = FN(2)
              ELSE
                IPR(72) = 5
              END IF
            ELSE
C * RETRACE LABELS
              IPR(7) = NINT (FN(1))
              IF (KN >= 2) PAR(4) = FN(2)
            END IF
          ELSE
            IPR(72) = 6
          END IF
        ELSE
          IPR(72) = 7
        END IF
        GO TO 220
C * ISW = 31: STEREO/MONO INSTRUCTION
      ELSE IF (ISW == 31) THEN
        PAR(25)  = 1.0
C * SET REBUILD
        IPR(130) = 0
        IPR(143) = IPR(19)
        IPR(144) = IPR(19)
C * STEREO - MODE
        IF (ICL(1:1) == 'S') THEN
          IPR(116) = -1
          PAR(48)  = PAR(12)
          IPR(6)   = 1
          IF (PAR(18) < 0) PAR(18) = - PAR(50) / 2.0
C * MONO - MODE
        ELSE IF (ICL(1:1) == 'M') THEN
          IPR(346) = IABS (IPR(346))
          IPR(116) = 0
          PAR(48)  = 0.0
          IPR(6)   = 0
          IF (PAR(18) < 0) PAR(18) = - PAR(50)
        END IF
        IF (KL > 1) THEN
          DO I = 2, KL
C * STEREO RedGreen, GreenRed, RedBlue OR BlueRed PAIR
            IF (IFL(I)(1:1) == 'R' .OR. IFL(I)(1:1) == 'G') THEN
              IPR(6)   = 0
              IPR(477) = 0
              IF (IFL(I)(1:1) == 'R') THEN
                IPR(346)   = - IABS (IPR(346))
                IPR(143)   = 2
                IF (IFL(I)(2:2) == 'B') THEN
                  IPR(144) = 4
                ELSE
                  IPR(144) = 3
                END IF
              ELSE
                IPR(346)   = - IABS (IPR(346))
                IPR(144)   = 2
                IF (IFL(I)(1:1) == 'B') THEN
                  IPR(143) = 4
                ELSE
                  IPR(143) = 3
                END IF
              END IF
              IF (PAR(18) < 0) PAR(18) = - PAR(50)
C * CROSSED - SUBKEYWORD
            ELSE IF (IFL(I)(1:1) == 'C') THEN
              IPR(6)  = -1
C * SMALL - SUBKEYWORD
            ELSE IF (IFL(I)(1:1) == 'S') THEN
              PAR(25) = 0.5
C * PERSPECTIVE - SUBKEYWORD
            ELSE IF (IFL(I)(1:1) == 'P') THEN
              PAR(48) = PAR(12)
C * RESET PERSPECTIVE - DEFAULT
              IF (KN > 0) THEN
                IF (FN(1) > 0.1) THEN
                  PAR(48) = FN(1)
                  IF (PAR(48) >= 10000.0) PAR(48) = 0.0
                END IF
              END IF
            END IF
          END DO
        END IF
        GO TO 220
C * ISW = 33: SIZE CONTROL: SIZE OF DRAWING, SCALE, LABELS,TITLE
      ELSE IF (ISW == 33) THEN
        IF (IGBL(8) /= 2) THEN
          IF (KN == KL) THEN
C * SET REBUILD
            IPR(130) = 0
            DO K = 1, KL
              JK13 = IFL(K)(1:3)
C * SIZE
              IF (JK13 == 'SIZ') THEN
C * DUMMY FOR NOW
                PAR(15) = FN(K)
C * RATIO
              ELSE IF (JK13 == 'RAT') THEN
                PAR(18) = FN(K)
C * SCALE
              ELSE IF (JK13 == 'SCA') THEN
                PAR(16) = FN(K)
C * TITLE (SIZE)
              ELSE IF (JK13 == 'TIT') THEN
                PAR(14) = FN(K)
C * CHARARACTER (SIZE)
              ELSE IF (JK13 == 'CHA') THEN
                PAR(349) = FN(K)
              END IF
            END DO
          END IF
          P15 = - PAR(15)
          WRITE (LU6, 99994, IOSTAT = IOST)
     1      PAR(18), PAR(14), P15, PAR(16), VERT, PAR(349)
          GO TO 220
        END IF
C * ISW = 34: PLOT INSTRUCTION
      ELSE IF (ISW == 34) THEN
        IPR(151) = 0
        IF (IPR(157) > 0) THEN
          IPR(130) = 0
          IPR(157) = 0
        END IF
        GO TO 280
C * ISW = 35: RESET - SET DEFAULTS AND CLEAR FLAGS
      ELSE IF (ISW == 35) THEN
        CALL PLUT01 (1)
        GO TO 220
C * ISW = 36: SEGMENT = PLOTSTEP SIZE (CM)
      ELSE IF (ISW == 36) THEN
        IF (KN > 0) THEN
          PAR(5) = FN(1)
          IF (KN > 1) IPR(111) = NINT (FN(2))
        END IF
        WRITE (LU6, 99999, IOSTAT = IOST) PAR(5), IPR(111)
        GO TO 220
C * ISW = 38: HP MANAGEMENT
      ELSE IF (ISW == 38) THEN
        IPDC = -2
        IF (KL > 1) THEN
          IF (IFL(1)(3:3) == 'P') IPDC = -4
          IF (IFL(2)(2:2) == 'N') IPDC = IABS (IPDC)
          CALL GGIP (-999.0, 0.0, 0.0, IPDC)
        END IF
        GO TO 220
C * ISW = 39: CAL MANAGEMENT
      ELSE IF (ISW == 39) THEN
        IPDC = -3
        IF (KL > 1) THEN
          IF (IFL(1)(3:3) == 'P') IPDC = -4
          IF (IFL(2)(2:2) == 'N') IPDC = IABS (IPDC)
          CALL GGIP (-999.0, 0.0, 0.0, IPDC)
        END IF
        GO TO 220
C * ISW = 40: COLOR/BWC MANAGEMENT
      ELSE IF (ISW == 40) THEN
        IF (IFL(1)(1:3) == 'BWC') THEN
          IBWC = 1
        ELSE
          IBWC = 0
        END IF
        IF (KL > 1) THEN
          JK13  = IFL(2)(1:3)
          KSTEP = IBWC + 1
C * COLOR TYPE
          IF (JK13 == 'TYP') THEN
            IF (KL >= 3 .AND. MOD (KL, KSTEP) == 0) THEN
              DO K = 3, KL, KSTEP
                CALL PLUT13 (0, -K, N1, XDUM)
                IF (N1 < 0) THEN
                  N1 = - N1
                  IF (IBWC == 1) THEN
                    DO J = 1, NP10 + 1
                      IF (IFL(K + 1)(1:3) == BWCT(J)(1:3)) GO TO 60
                    END DO
                    J        = 17
   60               IBCL(N1) = J
                  ELSE
                    IF (KN >= K - 2) IACL(N1) = NINT (FN(K - 2))
                    DO J = 1, NP10 + 1
                      IF (IFL(K + 1)(1:3) == COLR(J)(1:3)) GO TO 70
                    END DO
                    J        = 17
   70               IACL(N1) = J
                  END IF
                ELSE
                  WRITE (LU6, 99981, IOSTAT = IOST) IFL(K)
                END IF
              END DO
              IPR(90) = 256
            END IF
C * BWC/COLOR RESD
          ELSE IF (JK13 == 'RES') THEN
            IF (IFL(3)(1:3) == 'OFF') THEN
              IPR(346 - IBWC) = 0
              IPR(477 + IBWC) = 0
            ELSE
              IPR(346 - IBWC) = 1
              IPR(477 + IBWC) = -1
            END IF
C * BWC/COLOR ARU
          ELSE IF (JK13 == 'ARU') THEN
            IF (IFL(3)(1:3) == 'OFF') THEN
              IPR(346 - IBWC) = 0
              IPR(477 + IBWC) = 0
            ELSE
              IPR(346 - IBWC) = 1
              IPR(477 + IBWC) = 1
            END IF
          ELSE IF (JK13 == 'ON ') THEN
            IPR(346 - IBWC) = 1
          ELSE IF (JK13 == 'OFF') THEN
            IPR(346 - IBWC) = 0
          ELSE
            IPR(19) = 1
            IF (JK13 == 'RED') IPR(19) = 2
            IF (JK13 == 'GRE') IPR(19) = 3
            IF (JK13 == 'BLU') IPR(19) = 4
            IF (JK13 == 'YEL') IPR(19) = 5
            IF (JK13 == 'ORA') IPR(19) = 6
            IF (JK13 == 'VIO') IPR(19) = 7
            IF (JK13 == 'BRO') IPR(19) = 8
          END IF
        ELSE
          IF (IBWC == 1) THEN
            IPR(345) = 1
          ELSE
            IPR(346) = 1
          END IF
        END IF
        GO TO 220
C * ISW = 41: SET, PARAMETER MANIPULATION
      ELSE IF (ISW == 41) THEN
        IF (KL > 1) THEN
          JK12 = IFL(2)(1:2)
C * IPR/PAR/IGBL/RGBL - PARAMETER ARRAY
          IF (IFL(2)(1:3) == 'IPR' .OR.
     1        IFL(2)(1:3) == 'PAR' .OR.
     2        IFL(2)(1:3) == 'IGB' .OR.
     3        IFL(2)(1:3) == 'RGB') THEN
            CALL PLA206 (1, IFL(2)(1:3))
            GO TO 30
C * SET DISPLAY TYPE
          ELSE IF (JK12 == 'DI') THEN
            MEDIUM = 1
C * SET META-FILE TYPE
          ELSE IF (JK12 == 'ME') THEN
            MEDIUM = 2
C * SET WINDOW/DISPLAY FRACTION
          ELSE IF (JK12 == 'WI') THEN
            CALL GGIP (-999.0, 0.0, FN(1) * 1000.0, 9)
C * SET REVERSE
          ELSE IF (JK12 == 'RE') THEN
            IGBL(68) = MOD (IGBL(68) + 1, 2)
            CALL GGIP (-999.0, FLOAT (IGBL(68)), IGBL(62) * 0.25, 9)
          ELSE
            IPR(72) = 23
          END IF
          IF (IPR(72) == 0) THEN
            IF (KL > 2) THEN
              CALL GGIP (-999.0, 0.0, 0.0, 6)
            END IF
          END IF
        END IF
        GO TO 220
C * ISW = 42: OMIT
      ELSE IF (ISW == 42) THEN
        N = 0
        GO TO 210
C * ISW = 43/49/150: QUIT/STOP/EXIT
      ELSE IF (ISW == 43 .OR. ISW == 49 .OR. ISW == 150) THEN
        GO TO 290
C * ISW = 44: RESI
      ELSE IF (ISW == 44) THEN
        IPR(538) = NINT (FN(1))
        GO TO 220
C * ISW = 45: ANGLE CALCULATION
      ELSE IF (ISW == 45) THEN
        IF (KL == 4) THEN
          CALL PLUT24 (3, 0, IDUM)
          GO TO 30
        ELSE
          GO TO 220
        END IF
C * ISW = 46: DETACH
      ELSE IF (ISW == 46) THEN
        GO TO 150
C * ISW = 47: SAVE COMMAND
      ELSE IF (ISW == 47) THEN
        IGBL(45) = 1
        CALL GEN108 (LU3, 0)
        GO TO 220
C * ISW = 48: OVERLAP OPTION OFF = 0, BA = 1, BB = 2, ON = 3
      ELSE IF (ISW == 48) THEN
        IF (KL > 1) THEN
          N = 0
          DO K = 2, KL
            JK12 = IFL(K)(1:2)
C * OVERLAP SHADOW
            IF (JK12 == 'SH') THEN
              N = N + 1
              PAR(58) = FN(N)
C * OVERLAP MARGIN
            ELSE IF (JK12 == 'MA') THEN
              N = N + 1
              PAR(36) = FN(N)
C * ON AA, AB, BA, BB
            ELSE IF (JK12 == 'ON') THEN
              IPR(77) = 3
C * AB ATOM OVER BOND
            ELSE IF (JK12 == 'AB') THEN
              IPR(77) = 2
C * BA BOND OVER ATOM
            ELSE IF (JK12 == 'BA') THEN
              IPR(77) = 1
C * OFF
            ELSE IF (JK12 == 'OF') THEN
              IPR(77) = 0
            END IF
          END DO
        END IF
        WRITE (LU6, 99984, IOSTAT = IOST) IPR(77), PAR(36), PAR(58)
        GO TO 220
C * ISW = 51: BOX - INSTRUCTION
      ELSE IF (ISW == 51) THEN
        IF (KL > 1) THEN
C * SET REBUILD
          IPR(130) = 0
          N = 0
          DO K = 2, KL
            JK12 = IFL(K)(1:2)
C * BOX OFF
            IF (JK12 == 'OF') THEN
              IGBL(103) = 0
C * BOX ON
            ELSE IF (JK12 == 'ON') THEN
              IGBL(103) = 1
C * BOX SHRINK
            ELSE IF (JK12 == 'SH') THEN
              N = N + 1
              IF (N > KN) THEN
                IPR(72) = 12
                GO TO 220
              ELSE
                IF (FN(N) <= 1.0 .AND. FN(N) > 0.01) THEN
                  PAR(13) = FN(N)
                ELSE
                  CALL PLUT38 (6, 0, LU6)
                END IF
              END IF
C * BOX RATIO
            ELSE IF (JK12 == 'RA') THEN
              N = N + 1
              IF (N > KN) THEN
                IPR(72) = 13
                GO TO 220
              ELSE
                PAR(18) = FN(N)
              END IF
            END IF
          END DO
        END IF
        IF (IGBL(103) == 1) THEN
          N12 = 'ON '
        ELSE
          N12 = 'OFF'
        END IF
        WRITE (LU6, 99985, IOSTAT = IOST) N12, PAR(13), ABS(PAR(18))
        GO TO 220
C * ISW = 52: FVAR - SHELX76 STYLE
      ELSE IF (ISW == 52) THEN
        IGBL(8) = 2
        IPR(81) = 1
        IF (IPR(13) + KN > NP14) CALL PLUT38 (7, 1, LU6)
        DO I = 1, KN
          RP(IPR(13) + I) = MOD (FN(I) + 5.0, 10.0) - 5.0
        END DO
        IPR(13) = IPR(13) + KN
        GO TO 220
C * ISW = 53: HELP OPTION
      ELSE IF (ISW == 53) THEN
        IWIN  = IGBL(25) * IGBL(32)
        CALL PLA299 (2)
        GO TO 220
C * ISW = 55: B(ISO)
      ELSE IF (ISW == 55) THEN
        GO TO 130
C * ISW = 58: CPK STYLE
      ELSE IF (ISW == 58) THEN
        IF (IABS (IPR(4)) /= 3 .OR. KL == 1) CALL PLUT21 (1)
        GO TO 170
C * ISW = 59: SFAC - SHELX STYLE
      ELSE IF (ISW == 59) THEN
        IF (IABS (IGBL(8)) /= 2) THEN
          IGBL(8) = 2
          NSF     = 0
          NFHAT   = 0
        END IF
        DO I = 2, KL
          NSF = NSF + 1
          SFC(NSF) = IFL(I)(1:2)
          IF (SFC(NSF) == 'H ') NFHAT = 1
        END DO
        GO TO 220
C * ISW = 62: DISTANCE CALCULATION
      ELSE IF (ISW == 62) THEN
        CALL PLUT24 (2, 0, IDUM)
        GO TO 30
C * ISW = 63: TORSION CALCULATION
      ELSE IF (ISW == 63) THEN
        CALL PLUT24 (4, 0, IDUM)
        GO TO 30
C * ISW = 65: TRNS/TRMX INSTRUCTION
      ELSE IF (ISW == 65) THEN
        IF (KN /= 1) THEN
          IF (IPR(37) <= IPR(69)) THEN
            CALL GEN074 (SGX, 1, 13, 0.0)
            SGX(1) = 1.0
            SGX(5) = 1.0
            SGX(9) = 1.0
C * TRANSFORMATION MATRIX
            IF (KN == 9 .OR. KN == 12) THEN
C * REGISTER TRMX
              IPR(127) = 1
              K        = 0
              DO I = 1, 3
                DO J = 1, 3
                  K = K + 1
                  TMX(I, J) = FN(K)
                  SGX(K)    = FN(K)
                END DO
              END DO
C * GET TRANSPOSED INVERTED MATRIX -TMY- FROM -TMX-
              CALL GEN003 (TMX, A, DET, 0)
              WRITE (LU6, 99973, IOSTAT = IOST) DET
              CALL GEN005 (A, TMY)
            END IF
C * STORE ORIGIN SHIFT
            IF (KN == 3 .OR. KN == 12) THEN
              IPR(128) = 1
              DO I = 1, 3
                SHFT(I) = - FN(KN - 3 + I)
                SGX(I + 9) = - SHFT(I)
              END DO
            END IF
          ELSE
            WRITE (LU6, 99972, IOSTAT = IOST)
          END IF
C * SPECIAL FIX OPTION (KN = 1)
        ELSE
C * TEST FOR FIT IN SYMMETRY RANGE
          N = INT(ABS(FN(1)))
          IF (N > IPR(48)) THEN
            WRITE (LU6, 99986, IOSTAT = IOST) N, FN(1), IPR(48)
          ELSE
            IF (FN(1) < 0) THEN
C * FIX FOR FIRST ATOM IN NEW RESIDUE
              PAR(140) = FN(1)
            ELSE
C * FIX FOR NEXT ATOM
              PAR(141) = FN(1)
            END IF
          END IF
        END IF
        GO TO 220
C * ISW = 67: INORG - INSTRUCTION
      ELSE IF (ISW == 67) THEN
        IGBL(97) = 0
        GO TO 220
C * ISW = 68: ORGA - INSTRUCTION
      ELSE IF (ISW == 68) THEN
        IGBL(97) = 1
        GO TO 220
C * ISW = 69: STRAW STYLE
      ELSE IF (ISW == 69) THEN
        IF (IPR(4) /= 4 .OR. KL == 1) THEN
          IPR(4) = 4
          CALL PLUT21 (-1)
        END IF
        GO TO 170
C * ISW = 70: INFO
      ELSE IF (ISW == 70) THEN
        GO TO 240
C * ISW = 72: CROT(X/Y/Z)(M) (STEPS, (NR-STEPS)) (COLOR) INSTRUCTION
      ELSE IF (ISW == 72) THEN
        IF (KN > 0) PAR(145) = FN(1)
        IF (KN > 1) IPR(152) = NINT (FN(2))
        IPR(346) = - IABS (IPR(346))
        IF (IABS(IPR(4)) == 3) IPR(4) = -3
C * CHECK AUTOPLOT
        IGBL(35) = 1
C * TEST FOR X, Y OR Z CROT
        IF (IFL(1)(5:5) == 'X') THEN
          IPR(155) = 1
        ELSE IF (IFL(1)(5:5) == 'Z') THEN
          IPR(155) = 3
        ELSE
          IPR(155) = 2
        END IF
        IF (IFL(1)(6:6) == 'M') THEN
          IPR(164) = -1
        ELSE
          IPR(164) = 1
        END IF
        IPR(336) = 0
        IF (KL > 1 .AND. IFL(2)(1:1) == 'C') IPR(336) = 1
        IPR(151) = IPR(152)
        IPR(130) = 0
C * SET META OFF
        CALL GGIP (-999.0, 0.0, 0.0, -3)
C * PLOT
        IPR(221) = 0
        KN       = IPR(221)
        IPR(220) = 1
        KL       = IPR(220)
        GO TO 280
C * ISW = 73: VIEW DEFINITION  XROT
      ELSE IF (ISW == 73) THEN
        CALL PLUT06
        GO TO 220
C * ISW = 74: VIEW DEFINITION YROT
      ELSE IF (ISW == 74) THEN
        CALL PLUT06
        GO TO 220
C * ISW = 75: VIEW DEFINITION ZROT
      ELSE IF (ISW == 75) THEN
        CALL PLUT06
        GO TO 220
C * ISW = 76: DEFINE INSTRUCTION (CREATE CENTROID PSEUDO-ATOM)
      ELSE IF (ISW == 76) THEN
        IF (IPR(17) == 0) THEN
          CALL PLUT05
C * CALL EXIT/STOP
          IF (IPR(72) /= 0) CALL GEN127 ('305')
        END IF
        IPR(130) = 0
        NATX     = IPR(38)  + 1
        K        = NATX * NP43
        DO I = 1, 3
          RA(K + I) = 0.0
        END DO
C * GENERATE AND SAVE NEW CG# - LABEL
        NQ1 = 'CG'//CHAR (IPR(160) + ICHAR ('1'))//'    '
        CALL PLA046 (9, NQ1, NED, NQX, NSS, NQSM, INQNR, JNQNR, NIEN)
        IF (NIEN < 0) IPR(72) = - NIEN
        M = 0
        IF (KL < 5) THEN
          IPR(72) = 9
          GO TO 220
        END IF
C * TEST FOR -TO- SUB-KEYWORD
        DO I = 2, KL
          IF (IFL(I)(1:2) == 'TO') THEN
            IF (I == 2) THEN
              IPR(161) = -1
            ELSE IF (I == 3) THEN
              IPR(161) = 1
            ELSE
              IPR(72) = 10
              GO TO 220
            END IF
C * TEST FOR CENTRE OF GRAVITY
          ELSE IF (IFL(I)(1:2) == 'CG') THEN
            IF (I == 2) THEN
              IPR(161) = -2
            ELSE
              IPR(72) = 10
              GO TO 220
            END IF
          ELSE
            N = I
            CALL PLUT13 (0, N, IAT, XDUM)
            IF (IAT == 0) THEN
              IPR(72) = 11
              GO TO 220
            END IF
            IF (IPR(161) /= 0) THEN
              M = M + 1
              DO J = 1, 3
                RA(K + J) = RA(K + J) + RA(IAT * NP43 + J)
              END DO
              IF (M == 1) JAT = IAT
            END IF
          END IF
        END DO
        IF (M == 0) THEN
          IPR(71) = 0
          GO TO 220
        END IF
        DO I = 1, 3
          RA(K + I) = RA(K + I) / M
        END DO
        IPR(38)  = NATX
        IPR(37)  = NATX
        IPR(160) = IPR(160) + 1
        CALL PLUT23 (NATX)
        RA(K + 7)  = INQNR
        RA(K + 8)  = RA(JAT * NP43 + 8)
        RA(K + 9)  = RA(JAT * NP43 + 9)
        RA(K + 10) = RA(JAT * NP43 + 10)
        RA(K + 11) = -1.0
        RA(K + 12) = RA(JAT * NP43 + 12)
        CALL PLUT25 (1, NATX, JUNK)
        IFL(KL + 1) = NQ1
        CALL PLUT25 (0, NATX, N1)
        IF (IPR(161) == -2) THEN
          IPR(161) = 0
          IF (IPR(4) /= 0 .AND. RADR(N1, 1) == 0.0)
     1      CALL PLUT21 (-1)
          GO TO 220
        ELSE
C * SET EXCLUDE CG#
        IVAL = 0
        CALL PLUT15 (1, NATX, 27, IVAL)
C * DO DETACH Me# TO ATOM1 ATOM2 ...
          GO TO 150
        END IF
C * ISW = 78/157: REN(AME) ATOM LABELS
      ELSE IF (ISW == 78 .OR. ISW == 157) THEN
        IF (MOD (KL, 2) == 1 .OR. KL == 2) THEN
C * RENAME
          CALL PLUT32
        ELSE
          IPR(72) = 25
        END IF
        GO TO 220
C * ISW = 79: GEOM CALCULATION AROUND ATOM
      ELSE IF (ISW == 79) THEN
        IPR(163) = 0
        CALL PLUT24 (1, IPR(38), IDUM)
        GO TO 30
C * ISW = 80: MENU (ON/OFF)
      ELSE IF (ISW == 80) THEN
        IF (KL == 2 .AND. IFL(2)(1:3) == 'OFF') THEN
          IGBL(25) = 0
        ELSE
          IGBL(25) = 1
        END IF
      GO TO 220
C * ISW = 84: PART - SHELXL STYLE
      ELSE IF (ISW == 84) THEN
        IPR(612) = NINT(FN(1))
        IGBL(30) = 1
        GO TO 220
C * ISW = 87: COORDN AROUND ATOM
      ELSE IF (ISW == 87) THEN
        IPR(163) = 1
        IF (IPR(44) - IPR(43) == 0) THEN
C * TEMPORARILY SAVE ITEM 2
          IFL(4) = IFL(2)
C * SET RADII
          IFL(2)(1:5) = 'RADII'
C * SET INTER
          IFL(3)(1:5) = 'INTER'
          IPR(220) = 3
          KL       = IPR(220)
          CALL PLUT05
C * CALL EXIT/STOP
          IF (IPR(72) /= 0) CALL GEN127 ('306')
C * RESTORE ITEM 2
          IFL(2) = IFL(4)
          IPR(220) = 2
          KL       = IPR(220)
        END IF
        CALL PLUT24 (1, IPR(37), IDUM)
        GO TO 220
C * ISW = 89/159: DEL(ETE)
      ELSE IF (ISW == 89 .OR. ISW == 159) THEN
        N = 0
        GO TO 210
C * ISW = 90: ENTRY - READ UNTIL SPECIFIED DATA-ENTRY FOR KN /= 0
      ELSE IF (ISW == 90) THEN
        CALL PLA007
        IF (ICL(1:4) == 'END ') THEN
          GO TO 260
        ELSE
          GO TO 220
        END IF
C * ISW = 91: DIR
      ELSE IF (ISW == 91) THEN
        CALL PLA007
        IF (ICL(1:4) == 'END ') THEN
          GO TO 260
        ELSE
          GO TO 220
        END IF
C * ISW = 92: HFIX (SHELXL ONLY)
      ELSE IF (ISW == 92) THEN
        IF (KN > 0) GO TO 220
        IF (IGBL(50) > 0) THEN
          IGBL(8) = - IABS (IGBL(8))
        END IF
C * CHECK FOR .RES FILE
        IF (IGBL(8) == -2) THEN
          IF (KL == 1) THEN
            KL0 = 1
          ELSE
            KL0 = 2
          END IF
C * PICKUP AUTO-MODE FROM S
          NHAUTO = IGBL(50)
          DO KLI = KL0, KL
C * ENUMERATED
            IBEG = IPR(69) + 1
            IEND = IPR(39)
            IAT1 = 0
            IF (NHAUTO == 0) THEN
C * NAMED ATOM(TYPE)
              IF (KLI > 1) THEN
                CALL PLUT13 (0, KLI, IAT1, XDUM)
                IF (IAT1 > 0) THEN
                  IF (KN > 0) THEN
                    MNFIX = NINT (FN(1))
                    CALL PLUT29 (3, IFL(KLI), NQ2, MNFIX, 0)
                    CYCLE
                  END IF
                  IBEG = IAT1
                  IEND = IAT1
                ELSE IF (IAT1 == 0) THEN
                  CYCLE
                END IF
              END IF
            END IF
            DO I = IBEG, IEND
   80         IAT = I
C * TEST FOR RESIDUE
              IF (IPR(140) /= 0) THEN
                CALL PLUT15 (-6, IAT, 5, IVAL)
                IF (IVAL /= IPR(140)) CYCLE
              END IF
C * SKIP H-ATOMS
              CALL PLUT15 (-1, IAT, 44, IHAT)
              IF (IHAT == 0) THEN
                CALL PLUT25 (1, IAT, IATK)
                IFL(2) = NQ1
                IF (IAT1 < 0 .AND. -IAT1 /= IATK) CYCLE
                CALL PLA046 (8, NQ1, NEI, NA, NAX, NS, IXPK1, IXPK2,
     1                       NIEN)
                NB = 1
                NE = 7
                CALL GEN039 (1, IFL(2), 1, 7, NB, NE)
                IPR(220) = 2
C * DO GEOM LISTING FOR THIS ATOM
                CALL PLUT24 (-1, IPR(38), MNFX)
                IF (MNFX >= 0) THEN
                  CALL GEN040 (MNFX, NQ2, IP)
                  IF (NHAUTO == 0) THEN
   90               IF (IGBL(25) * IGBL(32) == 1) THEN
                      PAR40 = NE * PAR(349) * PAR(19) / 2.0
                      NATL  = IPR(62) + I
                      IASU  = 0
                      CALL PLUT14 (-1, NATL, IASU, NPROP, XL, YL, ZL,
     1                             RL)
                      IFLNQ = IFL(2)(1:NE)//'['//NQ2(1:IP)//']'
                      CALL PLA439 (0.0, IFLNQ, NE + IP + 2, PAR(349),
     1                  2, 2, XL - PAR40, YL - PAR(28))
                      SBCD      = 'HFIX '//IFL(2)//' mn['
                      SBCD(17:) =
     1                NQ2(1:IP)//'] or -1, AUTO, QUIT or END :'//CHAR(0)
C * WHAT NEXT ?
                      CALL PLA012 (0, 1)
                      ICL = IGGT
                    ELSE
                      WRITE (LU6, 99975, ADVANCE = 'NO', IOSTAT = IOST)
     1                  IFL(2), MNFX
                      READ  (LU5, 99987) ICL(1:80)
                    END IF
                    CALL GEN020 (1, ICL, 1, 4)
                    IF (ICL(1:4) == 'QUIT' .OR.
     1                  ICL(1:3) == 'END') THEN
                      GO TO 100
                    ELSE IF (ICL(1:4) == 'AUTO') THEN
                      NHAUTO = 1
                      MNFIX = MNFX
                    ELSE IF (ICL(1:4) == 'PLOT') THEN
                      CALL PLUT02
                      GO TO 80
                    ELSE IF (ICL(1:4) == 'VIEW') THEN
                      CALL PLA006 (1, IS)
                      CALL PLUT06
                      CALL PLUT02
                      GO TO 80
                    ELSE IF (ICL(1:1) == '!') THEN
                      IF (LRET == 2) THEN
                        CALL PLUT02
                        GO TO 80
                      ELSE
                        MNFIX = MNFX
                      END IF
                    ELSE
                      IF (ICL(1:4) == 'HFIX') THEN
                        MNFIX = 0
                      ELSE
                        READ (ICL, 99997, IOSTAT = IOST) MNFIX
                        IF (IOST > 0) GO TO 90
                      END IF
                      IF (MNFIX == 0) MNFIX = MNFX
                    END IF
                  ELSE
                    MNFIX = MNFX
                  END IF
                  IF (MNFIX > 0) WRITE (LU22, 99998, IOSTAT = IOST
     1            ) MNFIX, IFL(2)
                  CALL GEN038 (NQ2, 1, 7)
                  CALL PLUT29 (3, IFL(2), NQ2, MNFIX, 0)
                  CALL PLA439 (0.0, IFLNQ, NE + IP + 2, PAR(349), 0, 2,
     1                XL - PAR40, YL - PAR(28))
                  CALL PLA439 (0.0, IFL(2), NE, PAR(349), 1, 2,
     1                XL - PAR40, YL - PAR(28))
                END IF
              END IF
            END DO
          END DO
        END IF
  100   IF (IGBL(50) == 0) THEN
          CALL PLA280 ('PLOT')
C * HFIX
          IF (IGBL(3) == 13) THEN
            IPR(332) = 1
            CALL PLA015 (332, 1)
C * ANIS
          ELSE IF (IGBL(3) == 26) THEN
            IPR(352) = 1
            CALL PLA015 (352, 1)
          END IF
          IF (IPR(308) /= 0) IGBL(3) = 8
          GO TO 220
        ELSE
          IGBL(2) = 0
          CALL GEN038 (IGGT, 1, 80)
          GO TO 300
        END IF
C * ISW = 135: ANIS
      ELSE IF (ISW == 135) THEN
        WRITE (LU22, 99987, IOSTAT = IOST) ICL(1:80)
        IF (IGBL(8) == -2) THEN
          IF (KL == 1) THEN
            KL0 = 1
          ELSE
            KL0 = 2
          END IF
C * HANDLE ALIASES
          MSUBST = 0
          CALL PLA281 (1, IFL(KL0), MSUBST)
          DO KLI = KL0, KL
            IAT1 = 0
C * NAMED ATOM(TYPE)
            IF (KLI > 1) THEN
              CALL PLUT13 (0, KLI, IAT1, XDUM)
              IF (IAT1 > 0) THEN
                CALL PLUT29 (5, IFL(KLI), NQ2, 0, 0)
              END IF
            END IF
          END DO
        END IF
C * ANIS
        IF (IGBL(3) == 26) THEN
          IPR(352) = 1
          CALL PLA015 (352, 1)
        END IF
        GO TO 220
C * ISW = 140: ENDS
      ELSE IF (ISW == 140) THEN
        GO TO 260
C * ISW = 143: NOMOVE
      ELSE IF (ISW == 143) THEN
        IF (IPR(17) == 0 .AND. IPR(127) == 0) THEN
          IF (KL > 1 .AND. IFL(2)(1:3) == 'OFF') THEN
            IGBL(30) = 0
          ELSE
            IGBL(30) = 1
          END IF
        END IF
        GO TO 220
C * ISW = 144: RESD
      ELSE IF (ISW == 144) THEN
        IF (IPR(50) == 1) THEN
          IPR(135) = NINT (FN(1))
        ELSE
          IF (IPR(136) /= 0) THEN
            IPR(136) = NINT (FN(1))
          ELSE IF (IPR(37) == IPR(69)) THEN
            IPR(136) = NINT (FN(1))
          END IF
        END IF
        GO TO 220
C * ISW = 145: NOSORT OPTION
      ELSE IF (ISW == 145) THEN
        IGBL(33) = 0
        GO TO 220
C * 147: HALL
      ELSE IF (ISW == 147) THEN
        GO TO 110
C * ISW = 152: PORTRAIT
      ELSE IF (ISW == 152) THEN
        IGBL(46) = MOD (IGBL(46) + 1, 2)
        PAR(50)  = (4.0 - IGBL(46)) / 3.0
        PAR(18)  = - PAR(50)
        NN       = 4 - IGBL(46) * 8
        CALL GGIP (-999.0, 0.0, 0.0, NN)
        GO TO  220
C * ISW = 170: FIT => END
      ELSE IF (ISW == 170) THEN
        GO TO 290
C * ISW = 185: TEXT
      ELSE IF (ISW == 185) THEN
        TEXT = ICL(6:25)
      END IF
      GO TO 50
C * SPGR/LATT/SYMM/HALL - CARD
  110 IF ((ISW == 6 .OR. ISW == 9) .AND.
     1 (IGBL(8) <= 2) .AND.
     1     KL == 1 .AND. KN == 0) THEN
        WRITE (LU6, 99979, IOSTAT = IOST) ICL(1:4)
        GO TO 220
      ELSE IF (KL == 1 .AND. (KN == 9 .OR. KN == 12)) THEN
C * SYMM MATRIX INPUT: R11,R12,..,R33,(T1,T2,T3)
        ITRS = 15
        CALL SGSM (ITRS, ICL, FN, 0, LU6, IERR)
      ELSE
        IF (IPR(127) == 1 .OR. IPR(128) == 1) THEN
          ITRS = 16
        ELSE
          ITRS = 0
        END IF
        CALL SGSM (ITRS, ICL, SGX, 0, LU6, IERR)
      END IF
      CALL SGSM (18, ICL, SGY, 0, 0, IERR)
      SPGRNM(1) = ICL(1:26)
      IPR(48) = NINT(SGY(9))
C * SET TO SKIP FOR UNKNOWN SYMMETRY
      IF (IPR(48) == 0) THEN
        IPR(11) = 1
        WRITE (LU6, 99974, IOSTAT = IOST)
      END IF
      IF (IPR(48) > 48) THEN
        IF (IPR(134) /= 9) WRITE (LU6, 99982, IOSTAT = IOST)
        IPR(134) = 9
        PAR(42)  = 10.0
      END IF
C * SPECIAL DEFAULT SETTING
      IF (ICL(12:12) == 'h') THEN
        PAR(148) = 120.0
      ELSE
        PAR(148) = 90.0
      END IF
      GO TO 220
C * REAL OR POTENTIAL ATOM CARD
  120 IF (IPR(220) == 0 .AND. IPR(221) == 0) GO TO 50
      IF (IFL(1)(1:7) == 'CREATED') GO TO 50
C * CHECK FOR RES FILE
      IF (IGBL(8) == 2) THEN
      END IF
C * ATOM RECORD HANDLING
      CALL PLUT03 (IER)
      IF (IER /= 0) IPR(72) = 2
      GO TO 220
C * U/B
  130 IF (KL == 1) THEN
        GO TO 120
      ELSE
        GO TO 220
      END IF
C * JOIN CARD - SETS UP CONNECTIONS
C * CHECK FOR NUMBER OF LOADED ATOMS
  140 IF (IPR(37) > IPR(69)) THEN
        IMD      = 1
        IPR(110) = 0
C * TEST FOR JOIN INSTRUCTION
C * (TO BE INTERPRETED AS: JOIN RADII UNIQUE EXPAND)
        IF (KL == 1) THEN
C * DO JOIN RADII UNIQUE
          IF (IPR(17) == 0) THEN
            IMD = 0
          ELSE
            WRITE (LU6, 99971, IOSTAT = IOST)
            GO TO 220
          END IF
        ELSE IF (KL == 2) THEN
          J215 = IFL(2)(1:5)
C * JOIN INTRA
          IF (J215 == 'INTRA') THEN
            IF (IPR(17) == 0) IMD = 0
C * JOIN UNIQUE
          ELSE IF (J215 == 'UNIQU') THEN
            IF (IPR(17) == 0) IMD = 0
C * JOIN NONE
          ELSE IF (J215 == 'NONE ') THEN
            IPR(52) = IPR(68)
            IPR(53) = IPR(68)
            IPR(17) = 1
            IF (IPR(75) == 0) THEN
              CALL PLUT33
              IPR(75) = 1
              MADDR = 0
              CALL PLUT17 (0, 1555.0 + 1.0 / PAR(42), MADDR, LU6)
              DO I = 1, 3
                RCG(1, I) = RA(NP43 + I)
              END DO
              RCG(1, 4) = IPR(37) - IPR(69)
            END IF
            GO TO 220
C * JOIN HBONDS (EXPAND TO: JOIN RADII INTER HBONDS EXPAND)
          ELSE IF (J215 == 'HBOND' .OR. J215 == 'XBOND') THEN
C * SET RADII
            IFL(2)(1:5) = 'RADII'
C * SET INTER
            IFL(3)(1:5) = 'INTER'
C * SET HBONDS
            IF (J215 == 'HBOND') THEN
              IFL(4)(1:6) = 'HBONDS'
            ELSE
              IFL(4)(1:6) = 'XBONDS'
            END IF
C * SET EXPAND
            IFL(5)(1:6) = 'EXPAND'
            IPR(220) = 5
            KL       = IPR(220)
            GO TO 140
          END IF
        ELSE IF (KL >= 3) THEN
C * EXECUTE A JOIN RADII UNIQUE FIRST WHEN NOT DONE PREVIOUSLY
          IF (IPR(17) == 0) THEN
C * JOIN RADII INTER
            IF (IFL(3)(1:5) == 'INTER') THEN
              CALL PLUT05
C * CALL EXIT/STOP
              IF (IPR(72) /= 0) CALL GEN127 ('301')
            END IF
          END IF
        END IF
        GO TO 160
      ELSE
        WRITE (LU6, 99993, IOSTAT = IOST)
        IPR(72) = 3
        GO TO 220
      END IF
C * DETACH CARD
  150 IMD = -1
C * DETACH ALL
      IF (KL == 1) THEN
        IPR(52) = IPR(68)
        IPR(53) = IPR(68)
        IPR(17) = -1
        GO TO 220
      END IF
      IF (IPR(37) <= IPR(69)) THEN
        WRITE (LU6, 99993, IOSTAT = IOST)
        IPR(72) = 4
        GO TO 220
      END IF
      IF (IPR(52) == 0) THEN
        CALL PLUT05
        IF (IPR(72) /= 0) THEN
          IPR(72) = 0
          GO TO 50
        END IF
      END IF
  160 IPR(17) = IMD
      CALL PLUT05
C * HANDLE ERROR
      IF (IPR(72) /= 0) THEN
        IPR(72) = 0
        GO TO 50
      END IF
C * CHECK FOR DEFINE
      IF (IABS(IPR(161)) == 1) THEN
C * DO JOIN Me# - CG#
        IMD      = 1
        IF (IPR(161) == -1) THEN
          IFL(2)   = IFL(KL + 1)
        ELSE
          IFL(3)   = IFL(KL + 1)
          IPR(220) = 3
          KL       = IPR(220)
        END IF
        IPR(161) = 0
        IF (IPR(4) /= 0 .AND. RADR(N1, 1) == 0.0) CALL PLUT21 (-1)
        GO TO 160
      END IF
      GO TO 220
C * SET REBUILD
  170 IPR(130) = 0
      IF (IPR(100) == 0) CALL PLUT33
C * # CONTOUR
      IPR(8)   = IPR(74)
C * RESET NONUCL
      IPR(18)  = 0
C * RESET SPOT
      IPR(96)  = 0
C * RESET BWC
      IPR(345) = 0
C * RESET COLOR
      IPR(346) = 0
C * RESET GLOBAL B&W  MODE
      IPR(139) = 0
      PAR(130) = 0.0
      PAR(131) = 0.0
C * RESET SEGMENT STEP
      PAR(125) = 5.25
C * LOOP OVER SUB-KEYWORD OPTIONS
      IF (KL > 1) THEN
        DO K = 2, KL
          JK13 = IFL(K)(1:3)
          IF (JK13 == 'SPO') THEN
C * SET SPOT ON
            IPR(96) = 1
C * CPK/ROD/SOLID/STRAW GLOBE MODE
          ELSE IF (JK13 == 'GLO') THEN
            IPR(139) = 8
          ELSE IF (JK13 == 'CON') THEN
C * CPK/ROD/SOLID/STRAW CONTOUR MODE
            IPR(139) = 1
            IF (KN == 1) IPR(8) = NINT (FN(1))
          ELSE IF (JK13 == 'BLA') THEN
C * CPK/ROD/SOLID/STRAW BLACK MODE
            IPR(139) = 6
          ELSE IF (JK13 == 'SEG') THEN
C * CPK/ROD/SOLID/STRAW SEGMENT MODE
            IPR(139) = 4
C * CPK/ROD/SOLID/STRAW CROSS MODE
          ELSE IF (JK13 == 'CRO') THEN
            IPR(139) = 7
C * CPK/ROD/SOLID/STRAW PARALLEL MODE
          ELSE IF (JK13 == 'PAR') THEN
            IPR(139) = 9
C * CPK/ROD/SOLID/STRAW MERIDIAN MODE
          ELSE IF (JK13 == 'MER') THEN
            IPR(139) = 10
C * CPK/ROD/SOLID/STRAW DOTS
          ELSE IF (JK13 == 'DOT') THEN
            IPR(139) = 5
C * COLOR DOTS MODE
          ELSE IF (JK13 == 'NUC') THEN
C * CPK/ROD/SOLID NUCL MODE
            IPR(18) = 1
          ELSE IF (JK13 == 'SHA') THEN
C * CPK/ROD/SOLID SHADE MODE
            IPR(139) = 3
            IF (KN >= 2) THEN
              PAR(135) = FN(1)
              PAR(136) = FN(2)
              IF (KN > 2)  PAR(134) = FN(3)
            END IF
          ELSE IF (JK13 == 'STI') THEN
C * CPK STICK MODE
            IF (IABS(IPR(4)) == 3) THEN
              IPR(4)      = -3
            END IF
          ELSE IF (JK13 == 'COL') THEN
C * CPK/ROD/SOLID COLOR (SHADE) MODE
            IPR(346) = 1
            IF (K == 2 .AND. K == KL) THEN
            END IF
          ELSE IF (JK13 == 'NET') THEN
C * CPK/ROD/SOLID NET MODE
            IPR(139) = 2
            IF (KN == 2) THEN
              IPR(85) = NINT (FN(1))
              IPR(86) = NINT (FN(2))
            END IF
          ELSE IF (JK13 == 'BWC') THEN
C * CPK/ROD/SOLID BWCOL MODE
            IPR(345) = 1
          END IF
        END DO
      END IF
      GO TO 220
C * ARU/MOLES (TO BE PLOTTED) - INSTRUCTION (SKIP MOLE IN SHELXS.RES)
  180 IF (IGBL(8) /= 2) THEN
        IF (KN == 0 .AND. KL == 1) THEN
          KL = 2
          IFL(1) = 'LIST'
          IFL(2) = 'ARU'
          GO TO 240
        ELSE
          MADDR = 0
          CALL PLUT17 (1001, 0.0, MADDR, LU6)
          MODE = 0
          IF (KL > 1) THEN
C * ARU BOND ...
            IF (IFL(2)(1:4) == 'BOND') THEN
              KLM  = 3
              KADD = 64
C * ARU BWC ...
            ELSE IF (IFL(2)(1:3) == 'BWC') THEN
              KLM  = 3
              KL   = 3
              KADD = 0
              GO TO 190
C * ARU ...
            ELSE
              KLM  = 2
              KL   = 2
              KADD = 0
            END IF
C * FIND OUT ABOUT ARU COLOR
            DO K = 1, 9
              IF (IFL(KLM)(1:3) == COLR(K)(1:3)) THEN
                MODE = K + KADD
                KL   = 1
                GO TO 200
              END IF
            END DO
C * FIND OUT ABOUT ARU BWC
  190       DO K = 1, 17
              IF (IFL(KLM)(1:7) == BWCT(K)(1:7)) THEN
                MODE = K + 32 + KADD
                KL   = 1
                GO TO 200
              END IF
            END DO
          END IF
  200     IF (KN > 0 .OR. KL > 1) THEN
            IF (KN > 0) THEN
              DO K = 1, KN
                CALL PLUT17 (MODE, FN(K), MADDR, LU6)
                IF (IPR(43) > 1) CALL PLUT35 (FN(K), 0)
              END DO
            END IF
            IF (KL > 1) THEN
              DO K = 2, KL
                IF (IFL(K)(2:2) == ' ') THEN
                  CALL GEN105 (1, IFL(K)(1:1), N)
                  IF (N > 0) THEN
                    N = IPR(75) + N - ICHAR ('A')
                    IF (N < IPR(42)) THEN
                      XDUM = ABS (IARU(1, N + 1) / PAR(42))
                      CALL PLUT17 (MODE, XDUM, MADDR, LU6)
                    END IF
                  END IF
                END IF
              END DO
            END IF
          END IF
        END IF
      END IF
      GO TO 220
C * INCLUDE / EXCLUDE / OMIT / DELETE - INSTRUCTION
C * TAKE CARE OF SPECIAL MEANING OF OMIT AS SHELX-INSTRUCTION
  210 IF (IGBL(8) /= 2) THEN
        IF (KL > 1) THEN
          CALL PLUT09 (N, ISW)
        ELSE IF (KL == 1 .AND. KN > 0) THEN
C * OMIT, INCLUDE, EXCLUDE ARU'S
          DO I = 1, KN
            FN(I) = ((N * 2) - 1) * FN(I)
          END DO
          GO TO 180
        END IF
      END IF
C * GENERAL ERROR MESSAGE
  220 IF (IPR(72) > 0) THEN
        IF (IGBL(5) == LU5)
     1    WRITE (LU6, 99983, IOSTAT = IOST) IPR(72), CHAR (7)
        IF (IPR(72) == 24) THEN
          ISW = 140
          GO TO 260
        END IF
        IPR(72) = 0
        GO TO 220
      ELSE
        IF (IGBL(5) == LU5) THEN
C * SAVE INTERACTIVE INSTRUCTION ON FILE -.PJN
          IF (IFL(1)(1:3) /= 'REN') THEN
            WRITE (LU22, 99987, IOSTAT = IOST) ICL(1:80)
          END IF
C * AUTOMATIC PLOT INSTRUCTION
          IF (IFL(1)(2:4) == 'ROT' .OR. IFL(1)(1:4) == 'VIEW') THEN
C * AUTO-PLOT
            IF (IGBL(35) == 1) THEN
              IPR(221) = 0
              KN       = IPR(221)
              IPR(220) = 1
              KL       = IPR(220)
              GO TO 280
            ELSE
              GO TO 30
            END IF
          END IF
        END IF
C * DO MODE=2 RESET WHEN ATOMS HAVE BEEN DELETED OR RENAMED TO NEW ATOM TYPE
        IF (IPR(170) == 2) THEN
          IF (IPR(140) > 0) THEN
            DO I = 1, IPR(39)
C * CHECK RESIDUE
              CALL PLUT15 (-6, I,  5, IVAL)
              IF (IVAL == IPR(140)) THEN
C * CHECK FOR 'INCLUDED'
                CALL PLUT15 (-1, I,  27, IVAL)
                IF (IVAL == 1) THEN
                  IPR(140) = -I
                  GO TO 230
                END IF
              END IF
            END DO
            IPR(140) = 0
          END IF
  230     WRITE (LU6, 99995, IOSTAT = IOST)
          CALL PLUT01 (2)
          CALL PLUT21 (-1)
          IPR(75) = 0
          IPR(17) = 0
          IGBL(5) = LU23
          CALL GEN108 (LU23, 0)
        END IF
      END IF
      GO TO 40
C * LIST/INFO ON DISPLAY OR TRAILER LISTING OF
C * SYMM/ATOM(S)/BOND(S)/ARU/MOLES/LINES LISTS ETC.
  240 IF (KL > 1 .AND.
     1   (IFL(2)(1:3) == 'PAR' .OR. IFL(2)(1:3) == 'IPR') .OR.
     2    IPR(37) > IPR(69)) THEN
        IPR(90)  = 510
        IPR(147) = 0
        IF (KL >= 2) THEN
          IPR(90)  = 0
C * SET LIST INTER FLAG OFF
          IGBL(31) = 0
          DO I = 2, KL
            JK13 = IFL(I)(1:3)
C * LIST CELL
            IF (JK13 == 'CEL') THEN
              WRITE (BCD, 99980, IOSTAT = IOST)
     1          (PAR(100 + J), J = 1, 3),
     2          (ACOS (PAR(103 + J)) * RGBL(6), J = 1, 3), PAR(126),
     3          CHAR (0)
              IF (IGBL(25) * IGBL(32) == 1) THEN
                IGBL(6) = - IABS (IGBL(6))
                CALL GGIP (-999.0, 5.0 + FLOAT (IGBL(68)), 78.0, 111)
              ELSE
                WRITE (LU6, 99977, IOSTAT = IOST) BCD
              END IF
              GO TO 30
C * SET INTER BIT FOR LIST (ATOM(S)/BOND(S)) INTER
            ELSE IF (JK13 == 'INT') THEN
              IGBL(31) = 1
C * SELECT RESIDUE NUMBER FOR PRINTING
            ELSE IF (JK13 == 'RES') THEN
              IF (KN == 1) IPR(147) = NINT (FN(1))
C * LIST IPR/PAR/IGBL/RGBL
            ELSE IF (JK13 == 'IPR' .OR.
     1               JK13 == 'PAR' .OR.
     2               JK13 == 'IGB' .OR.
     3               JK13 == 'RGB') THEN
              CALL PLA206 (-1, JK13)
              CALL GGIP (0.0,0.0,0.0,6)
              GO TO 30
C * LIST SYMM
            ELSE IF (JK13 == 'SYM') THEN
              IPR(90) = IPR(90) + 2
C * LIST ATOM(S)
            ELSE IF (JK13 == 'ATO') THEN
              IPR(90) = IPR(90) + 4
C * LIST BOND(S)
            ELSE IF (JK13 == 'BON') THEN
              IPR(90) = IPR(90) + 8
C * LIST LINES
            ELSE IF (JK13 == 'LIN') THEN
              IPR(90) = IPR(90) + 16
C * LIST ARU
            ELSE IF (JK13 == 'ARU') THEN
              IPR(90) = IPR(90) + 32
C * LIST MOLES
            ELSE IF (JK13 == 'MOL') THEN
              IPR(90) = IPR(90) + 32
C * LIST MATRIX
            ELSE IF (JK13 == 'MAT') THEN
              IPR(90) = IPR(90) + 64
C * LIST STATUS
            ELSE IF (JK13 == 'STA')  THEN
              IPR(90) = IPR(90) + 128
C * LIST TYP
            ELSE IF (JK13 == 'TYP') THEN
              IPR(90) = IPR(90) + 256
C * LIST ATOM-FLAGS
            ELSE IF (JK13 == 'FLA') THEN
              IPR(90) = IPR(90) + 512
C * ATOM/ ATOM TYPE
            ELSE
              CALL PLUT13 (0, -I , IAT, XDUM)
              IF (IAT == 0) THEN
                IPR(72) = 21
                GO TO 220
              END IF
            END IF
         END DO
        END IF
        CALL PLUT12
      ELSE
        IPR(72) = 22
      END IF
      GO TO 220
C * UNCHECKED EOF OR CTRL_D - HANDLING
  250 IF (IGBL(5) == LU1) THEN
C * FRACTIONAL AND NO COORDINATES EXIT
        IF (IPR(39) == 0 .AND. IPR(50) == 1) GO TO 290
C * COUNT NUMBER OF EOF ON UNIT LU1
        IPR(47)  = IPR(47) + 1
        IF (IPR(47) > 1) GO TO 290
      ELSE IF (IGBL(5) == LU23) THEN
        CALL GEN108 (LU23, 0)
        IGBL(5) = LU3
        GO TO 50
      ELSE IF (IGBL(5) == LU3) THEN
        CALL GEN108 (LU3, 0)
        IGBL(5)  = LU5
        IGBL(24) = IABS (IGBL(24))
        IF (IGBL(50) == 0) THEN
          IF (IGBL(24) * IGBL(25) /= 0) CALL PLA280 ('PLOT')
        END IF
        IPR(72) = 0
        GO TO 50
      ELSE IF (IGBL(5) == LU5) THEN
        GO TO 290
      END IF
C * END / ENDS / EOF - HANDLING
  260 IF (ISW == 140) THEN
        IF (IGBL(5) == LU1)
     1    WRITE (LU6, 99989, IOSTAT = IOST) JID(1:19)
        IF (IGBL(5) == LU5) THEN
          ICL(1:4) = '    '
          GO TO 270
        END IF
      ELSE
        IF (IGBL(5) == LU5) THEN
          IF (IGBL(8) /= 0) THEN
            IGBL(8) = IABS (IGBL(8))
            IF (IGBL(8) /= 2) THEN
              IGBL(5) = LU1
              GO TO 270
            END IF
          END IF
          GO TO 290
        END IF
      END IF
C * HANDLE SHELX(L).XXX
      IF (IABS(IGBL(8)) == 2) THEN
        IPR(47) = IPR(47) + 1
        IGBL(8) = 2
      END IF
      IGBL(8) = - IABS (IGBL(8))
      CALL GEN108 (LU3, 0)
C * SWITCH TO DEFAULT INSTRUCTION FILE
      IF (IGBL(5) == LU1) THEN
        IGBL(5) = LU23
        CALL GEN108 (LU23, 0)
        GO TO 50
      END IF
C * HANDLE END & EOF
      IF (ICL(1:4) /= 'ENDS') THEN
        IF (IGBL(5) == LU3 .AND. IPR(47) == 0) GO TO 270
        IF (IPR(47) > 0) GO TO 290
      END IF
      IF (IGBL(5) == LU23) THEN
        IGBL(5) = LU3
        GO TO 50
      END IF
      IF (IGBL(5) == LU3) THEN
        IGBL(5)  = LU5
        IGBL(24) = IABS (IGBL(24))
        GO TO 50
      END IF
  270 IPR(61) = - 1
      GO TO 20
C * ENTRY FROM CROT, XROT, YROT, ZROT
  280 IPR(82)  = 0
      IPR(145) = 0
      IF (KL > 1) THEN
        DO K = 2, KL
          JK13 = IFL(K)(1:3)
C * TRAILER LIST OPTION
          IF (JK13 == 'LIS') THEN
            IPR(145) = 1
C * POVRAY/RASMOL OPTION
          ELSE IF (JK13 == 'POV' .OR. JK13 == 'PDB') THEN
            IPR(130) = 0
            IGBL(67) = 1
            IPR(82)  = 1
            IF (JK13 == 'PDB') THEN
              OPEN (UNIT = LU60,  FILE = NAMEFIL(1:KNMFIL)//'.ras',
     1                                          STATUS = 'UNKNOWN')
              IPR(10)  = 2
              IGBL(11) = 1
              CALL GEN108 (LU60, 0)
              WRITE (LU60, '(''HEADER'', 3X, A)', IOSTAT = IOST)
     1          JID(1:70)
              IPR(340) = 1
            ELSE
              OPEN (UNIT = LU61,  FILE = NAMEFIL(1:KNMFIL)//'.pov',
     1                                          STATUS = 'UNKNOWN')
              CALL GEN108 (LU61, 0)
              IPR(10)  = 1
              IGBL(98) = 1
              IF (IGBL(101) == 0) THEN
                BCKG = 'White '
                BCOL = 'Bronze'
                HCOL = 'rgb <0.6,0.6,0.6>'
              ELSE IF (IGBL(101) == 1) THEN
                BCKG = 'SummerSky '
                BCOL = 'LightGray'
                HCOL = 'White'
              ELSE IF (IGBL(101) == 2) THEN
                BCKG = 'Black '
                BCOL = 'LightGray'
                HCOL = 'White'
              ELSE IF (IGBL(101) == 3) THEN
                BCKG = 'Scarlet '
                BCOL = 'LightGray'
                HCOL = 'White'
              ELSE IF (IGBL(101) == 4) THEN
                BCKG = 'Silver'
                BCOL = 'Bronze'
                HCOL = 'rgb <0.6,0.6,0.6>'
              END IF
              WRITE (LU61, 99992, IOSTAT = IOST)
     1          ABS (PAR(18)), BCOL, HCOL
              WRITE (LU61, 99991, IOSTAT = IOST) BCKG
              DO I = 3, IAN
                ICOL = IACL(I)
                IF (ICOL > 1 .AND. ICOL < 9) THEN
                  CLR = COLR(ICOL)(1:7)
                  CALL GEN020 (0, CLR, 2, 7)
                ELSE
                  CLR = 'Coral  '
                END IF
                N2 = IEL(IEN(I))
                N1 = N2 / 100 + ICHAR ('A') - 1
                N2 = MOD (N2, 100)
                IF (N2 == 0) THEN
                  N2 = ICHAR (' ')
                ELSE
                  N2 = N2 + ICHAR ('a') - 1
                END IF
                WRITE (LU61, 99990, IOSTAT = IOST)
     1            CHAR (N1), CHAR (N2), CLR
              END DO
              WRITE (LU61, 99988, IOSTAT = IOST)
            END IF
          ELSE
C * FIRST DECIDE WHETHER THE META OR DISPLAY SHOULD BE ON
            IPDC = -3
            IF (IFL(K)(1:1) == 'M' .OR. IFL(K)(1:1) == 'C')
     1        IPDC = -2
            CALL GGIP (-999.0, 0.0, 0.0, IPDC)
            IF (IFL(K)(1:1) == 'D') THEN
C * DECIDE WHETHER DISPLAY SHOULD BE ON
              IPDC = 2
              CALL GGIP (-999.0, 0.0, 0.0, IPDC)
            END IF
          END IF
        END DO
      END IF
      IF (IPR(37) > IPR(69)) THEN
C * SET-UP BOND ARRAY
        IF (IPR(17) == 0) THEN
          CALL PLUT05
          IF (IPR(72) /= 0) GO TO 220
        END IF
C * DO AN AUTOMATIC VIEW MIN WHEN NOT SET
        IF (IGBL(67) == 0) THEN
          WRITE (LU6, 99996, IOSTAT = IOST)
          IPR(220)    = 2
          KL          = IPR(220)
          IPR(221)    = 0
          KN          = IPR(221)
          IFL(2)(1:2) = 'MI'
          WRITE (LU6, 99996, IOSTAT = IOST)
          CALL PLUT06
        END IF
      ELSE
        WRITE (LU6, 99993, IOSTAT = IOST)
        IPR(72) = 24
      END IF
C * TEST FOR ERROR
      IF (IPR(72) /= 0) GO TO 220
      GO TO 300
C * END OF JOB (STOP/EXIT)
  290 IGBL(2) = -1
C * EXECUTE THIS PLOT INSTRUCTION / ALL PLOTTING IS DONE IN PLUT02
C * END OF LOOP: TEST (IGBL(2) = 0)
  300 IF (IGBL(2) > 0) THEN
        CALL PLUT02
        GO TO 10
      ELSE
C * SHIFT ORIGIN BACK FROM  PAR(64), PAR(65)
        CALL GGIP (-PAR(64), -PAR(65), 0.0, -3)
        CALL GGIP (-XSH0,       -YSH0, 0.0, -3)
        CALL GGIP (0.0, 0.0, 0.0, 6)
        IPR(308) = 0
        CALL PLA015 (335, 0)
        CALL PLA015 (351, 0)
        CALL PLA015 (349, 0)
        CALL PLA015 (332, 0)
        CALL PLA015 (352, 0)
C * RESTORE IGBL(8)
        IF (IGBL8 /= 0) THEN
          IGBL(30) = IGBL30
          IGBL(8)  = IGBL8
        END IF
      END IF
      RETURN
99999 FORMAT (':: PlotStep =', F4.2, ' cm., Number SubSteps =', I3)
99998 FORMAT ('HFIX', I3, 1X, A)
99997 FORMAT (I3)
99996 FORMAT (':: AEX:VIEW MIN')
99995 FORMAT (':: RESET executed in view of deleted atom(s)',
     1        ' or change of Element type')
99994 FORMAT (
     1 45X, ' RATIO', F6.3, ' TITL', F7.2, ' SIZE', F6.2, /,
     2 45X, ' SCALE', F6.2, ' YLIM', F7.2, ' CHAR', F6.2)
99993 FORMAT (':: NO Coordinates given')
99992 FORMAT ('#include "shapes.inc"', /,
     1        '#include "metals.inc"', /,
     2        '#include "colors.inc"', /,
     3        'global_settings {assumed_gamma 2.0}', /,
     4        'camera { location < 0, 0, +15> up < 0, 1, 0>',
     5        ' right <', F8.4, ', 0, 0> look_at < 0, -0.25, 0>',
     6        ' angle 15 }', /,
     7        'light_source  { < -1, 2, +2 > color White }', /,
     8        'light_source  { < 0, 1, +8 > color White }', /,
     9        '#declare color_bond = ', A, ' ;', /,
     *        '#declare finish_all = finish { phong 0.8 }', /,
     1        '#declare color_H = ', A, ' ;', /,
     2        '#declare color_C = rgb < 0.3, 0.3, 0.3 > ;')
99991 FORMAT ('background { color ', A, ' }')
99990 FORMAT ('#declare color_', 2A, ' = ', A, ' ;')
99989 FORMAT ( ':: Data Set : ', A, ' loaded')
99988 FORMAT ('union {' )
99987 FORMAT (A)
99986 FORMAT (/, ':: Symmetry # :', I4, ' in TRNS (', F8.3,
     1         ') OUT OF RANGE (', I3, '(Ignored)')
99985 FORMAT (':: BOX ',A, ' SHRINKAGE FACTOR:', F6.2,
     1 ' AND WINDOW RATIO:', F7.3)
99984 FORMAT (':: Overlap (OFF=0,BA=1,BB=2,ON=3)=', I2, ', Margin=',
     1        F5.2, ', Shadow = ', F5.2)
99983 FORMAT (':: Instruction Error(', I4,
     1        ') - Ignored , (see HELP ALL)', A)
99982 FORMAT (':: Note: Max. Number of Residues in limited to 9',/)
99981 FORMAT (':: ', A, 'is NOT an Atom-type (Ignored)')
99980 FORMAT ('CELL ', 3F10.4, 3F10.2, F12.2, A)
99979 FORMAT (/, ':: ', A, ' instruction ignored', /)
99978 FORMAT (':: Saved: ', A)
99977 FORMAT (/, A, /)
99976 FORMAT ('** ', A)
99975 FORMAT (/, 'HFIX ', A, ' mn[',I3,'] or Q[uit] :')
99974 FORMAT (/, ':: DATA will be SKIPPED until END-OF-SECTION')
99973 FORMAT (':: Transformation on Input Data: Det =', F6.3)
99972 FORMAT (':: TRNS Instruction NOT ALLOWED here and IGNORED')
99971 FORMAT (':: JOIN Instruction Ignored')
      END SUBROUTINE PLUTON
 
      SUBROUTINE PLUT01 (IMODE)
C * INITIALISATION full/partial
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE menus
      USE pluto
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NM0
      INTEGER :: NMK
      INTEGER :: IVAL
      INTEGER :: IVERM
      INTEGER :: IMODE
C * IMODE = -1
C * IMODE =  0
C * IMODE =  1
C * IMODE =  2
      IF (IMODE == -1) THEN
        CALL GEN038 (IGGT, 1, 80)
        IGBL(100) = 0
        IGBL(2)   = 0
        IGBL(5)   = 0
        IGBL(6)   = 2
        IGBL(24)  = - IABS (IGBL(24))
        IGBL(27)  = 1
        IGBL(32)  = - IABS (IGBL(32))
        IPR(61)   = -1
        SBCD      = CHAR (0)
C * OPEN APPROPRIATE PARAMETER FILE
C * IGBL(3) =  0 - PLATON/_P.SPF-PATH
C *         =  8 - Native PLUTON mode
C *         = 12 - RENAME mode
C *         = 13 - HFIX mode
C *         = 26 - ANIS mode
        IF (IGBL(3) == 8 .OR. IGBL(3) == 12 .OR. IGBL(3) == 13
     1                     .OR. IGBL(3) == 26) THEN
          IGBL(8)  = IABS (IGBL(8))
C * RESET ALIASES FOR CI
          IF (IGBL(8) == 3 .OR. IGBL(8) == 2) IPR(759) = 0
C * SET LABEL ON
          IF (IGBL(3) == 26) IGBL(75) = 1
C * TEST FOR RUN-FROM-S
          IF (IGBL(92) == 1) THEN
            NAMEFIL  = 'satom'
            KNMFIL   = 5
            EXTENS   = 'spf'
            KXT      = 3
            IGBL(26) = 0
            INQUIRE (UNIT = LU98, OPENED = OPEND)
            IF (.NOT. OPEND) THEN
              OPEN (UNIT = LU98, STATUS = 'SCRATCH',
     1          FORM = 'FORMATTED')
            ELSE
              REWIND (UNIT = LU98, IOSTAT = IOST)
            END IF
C * CHANNEL FOR SAVED INSTRUCTIONS
            INQUIRE (UNIT = LU3, OPENED = OPEND)
            IF (.NOT. OPEND) THEN
              OPEN (UNIT = LU3, STATUS = 'SCRATCH',
     1          FORM = 'FORMATTED')
            ELSE
              REWIND (UNIT = LU3, IOSTAT = IOST)
            END IF
            INQUIRE (UNIT = LU23, OPENED = OPEND)
            IF (.NOT. OPEND) THEN
              OPEN (UNIT = LU23, FILE = NAMEFIL(1:KNMFIL)//'.def',
     1                                          STATUS = 'UNKNOWN')
            ELSE
              REWIND (UNIT = LU23, IOSTAT = IOST)
            END IF
            INQUIRE (UNIT = LU21, OPENED = OPEND)
            IF (.NOT. OPEND) THEN
              OPEN (UNIT = LU21,  FILE = NAMEFIL(1:KNMFIL)//'.new',
     1                                           STATUS = 'UNKNOWN')
            ELSE
              REWIND (UNIT = LU21, IOSTAT = IOST)
            END IF
            INQUIRE (UNIT = LU22, OPENED = OPEND)
            IF (.NOT. OPEND) THEN
              OPEN (UNIT = LU22,  FILE = NAMEFIL(1:KNMFIL)//'.pjn',
     1                                           STATUS = 'UNKNOWN')
            ELSE
              REWIND (UNIT = LU22, IOSTAT = IOST)
            END IF
          END IF
C * DATA INPUT FILE
          FNLU1 = NAMEFIL(1:KNMFIL)//'.'//EXTENS
          KNMXT = KNMFIL + KXT + 1
C * RENAME, ANIS AND HFIX FUNCTION
          IF (IGBL(3) == 12 .OR. IGBL(3) == 13 .OR.
     1        IGBL(3) == 26) THEN
            IGBL(48) = 1
            IGBL(6)  = 3
          END IF
        ELSE
          IGBL(8) = 1
          FNLU1   = NAMEFIL(1:KNMFIL)//'_pl.spf'
          KNMXT   = KNMFIL + 7
        END IF
C * CHECK FOR DEFAULT PRESENT
        IF (IGBL(23) == 0 .AND. IGBL(3) /= 8) THEN
          CALL GEN108 (LU23, 0)
C * STRAW COLOR
          WRITE (LU23, 99995, IOSTAT = IOST)
C * LABEL
          IF (IGBL(75) == 1) WRITE (LU23, 99997, IOSTAT = IOST)
          IF (IGBL(87) * IGBL(67) /= 0) THEN
C * VIEW UNIT XROT YROT ZROT
            WRITE (LU23, 99994, IOSTAT = IOST)
     1        RGBL(28), RGBL(29), RGBL(30)
C * VIEW INVERT
            IF (IGBL(87) < 0) WRITE (LU23, 99993, IOSTAT = IOST)
          END IF
C * PLOT (CAL/DISPLAY)
          IF (IGBL(3) == 13 .AND. IGBL(50) > 0) THEN
            WRITE (LU23, 99996, IOSTAT = IOST)
          ELSE
            WRITE (LU23, 99992, IOSTAT = IOST)
          END IF
          CALL GEN108 (LU23, 0)
        END IF
        INQUIRE (FILE = FNLU1, OPENED = OPEND)
        IF (OPEND) WRITE (6,'(''LU1 OPEN ALREADY'')', IOSTAT = IOST)
        OPEN (UNIT = LU1, FILE = FNLU1, STATUS = 'OLD', IOSTAT = IOST)
        IF (IOST > 0) GO TO 10
        GO TO 20
C * OPEN ERROR, SWITCH TO INTERACTIVE DATA INPUT
   10   WRITE (LU6, 99990, IOSTAT = IOST) FNLU1(1:KNMXT)
        LU1 = LU5
        GO TO 20
C * FULL OR PARTIAL INITIALISATION ROUTINE FOR (RE)SETTING OF DEFAULTS.
C * TEST FOR FULL/PARTIAL INITIALISATION (IMODE 0, 1, 2)
      ELSE IF (IMODE == 0) THEN
C * IPR(61) SET IN PLUT00 TO -1
        IF (IPR(61) == 0) GO TO 20
        CALL GEN074 (PAR, 1, NP13, 0.0)
C * INIT BIT
        CALL GEN048 (0, I, 0, I)
        IGBL(5) = LU1
C * GET AND PRINT VERSION DATE
        WRITE (LU6, 99999, IOSTAT = IOST) IGBL(4)
        WRITE (LU6, 99991, IOSTAT = IOST) FNLU1(1:KNMXT)
        IGBL(8) = IABS (IGBL(8))
        IAN     = 4
        DO I = 1, NP10
          IACL(I) = JACL(I)
          IF (I > IAN) THEN
            IEN(I) = 0
          ELSE
C * PRELOAD H C O N
            IEN(I) = I
            RADR(I, 3) = REL(IEN(I))
            RADR(I, 4) = ABS (VDWR(IEN(I)))
          END IF
          IENLB(I)   = 0
          RADR(I, 2) = 0.0
          RADR(I, 1) = 0.0
        END DO
        CALL GEN097 (MNH, 1, NP35, 0)
        MNH(6) = 2
        MNH(7) = 2
        DO I = 1, 31
          IBT(I) = 2**(I - 1)
        END DO
        CALL GEN097 (IPPR, 1, MP7 * 3, 0)
C * DEFAULT RESIDUE COLORS
        DO I = 1, 9
          NCRS(I) = I
        END DO
C * DEFAULT RESIDUE PATTERNS
        DO I = 1, 17
          NPRS(I) = I
        END DO
        DO I = 1, 2
          DO J = 1, NP48
            IARU(I, J) = 0
          END DO
        END DO
C * SET DEFAULT ARU PATTERNS
        DO I = 1, 17
          CALL GEN048 (5, IARU(2, I), 1, I)
        END DO
C * SET DEFAULT ARU (ATOM/BOND) COLORS
        DO I = 1, 17
          CALL GEN048 (5, IARU(2, I), 6, I)
          CALL GEN048 (5, IARU(2, I), 11, I)
        END DO
        IPPR(1, 1) = 10000
        IPPR(1, 2) = 0
        IPPR(1, 3) = 1
        PAR(24)    = 0
        IF (IGBL(47) > 0) THEN
          IPR(590) = 1
        ELSE
          IPR(590) = 0
        END IF
C * SET SPECIAL POSITION PARAMETERS ( ANGSTROM AND CM RESP)
        PAR(22) = 0.3
        PAR(45) = 0.1
C * PACKING CONSTANT IN ARU
        PAR(42) = 100.0
C * SET IPR TO ZERO AND ID TO BLANK
        CALL GEN097 (IPR, 1, NP12, 0)
        CALL GEN038 (JID, 1, 80)
        IPR(9)   = 1
        IPR(460) = 3
        IPR(551) = 3
C * FRAC/ANGSTROM
        IPR(50) = 1
        IPR(69) = 8
        IPR(37) = IPR(69)
        CALL SGSM (1, ICL, SGX, 0, LU6, IERR)
        IPR(48) = 1
C * SAVE NRESMAX
        IPR(134) = NP32
C * MAX NR OF BONDS IN IC
        IPR(36) = 0
C * START OF LINE TYPE STACK (PLACES RESERVED FOR CIF & RES /INPUT)
        IPR(80) = NP49 - 1000000
C * MAX NUMBER OF BOND-TYPES
        IPR(76) = 100
C * TO H-X COVALENT BOND RADIUS PARAMETER (SOLID)
        IPR(103) = 4035
C * TO H-X COVALENT BOND RADIUS PARAMETER (ROD)
        IPR(104) = 3060
C * TO H-X COVALENT BOND RADIUS PARAMETER (STRAW)
        IPR(106) = 2120
C * SKIP Q-ATOMS FROM 'new'-SHELX file
        IPR(176) = 1
C * INIT RENAME
        CALL GEN038 (ICL, 1, 80)
        CALL PLUT29 (0, ICL, NQ1, 0, 0)
C * SET CELL CORNER COORDINATES AND FLAGS
        DO I = 1, 8
          IVAL = 0
C * SET MULTIPLICITY
          CALL PLUT15 (6, I, 18, IVAL)
          IVAL = 1
C * SET INCLUDE BIT
          CALL PLUT15 (1, I, 27, IVAL)
          NM0   = I - 1
          IVERM = 8
          DO J = 1, 3
            IVERM            = IVERM / 2
            NMK              = NM0 / IVERM
            NM0              = NM0 - NMK * IVERM
            RA(I * NP43 + J) = FLOAT (NMK)
          END DO
          RA(I * NP43 + 7) = ICHAR (' ')
        END DO
C * ORIGIN LABEL O
        RA(NP43 + 7)     = ICHAR ('O')
C * ORIGIN LABEL c
        RA(2 * NP43 + 7) = ICHAR ('c')
C * ORIGIN LABEL b
        RA(3 * NP43 + 7) = ICHAR ('b')
C * ORIGIN LABEL a
        RA(5 * NP43 + 7) = ICHAR ('a')
      ELSE
C * MODE 1 & 2 INIT
        IF (IMODE == 1) THEN
          WRITE (LU6, 99998, IOSTAT = IOST)
          DO I = IPR(69) + 1, IPR(37)
C * RESET LABEL POSITION AND PUT INSTRUCTION
            IVAL = 0
            CALL PLUT15 (1, I, 42, IVAL)
            IVAL = 0
            CALL PLUT15 (4, I, 37, IVAL)
C * RESET INCLUDE ATOM BIT
            IVAL = 1
            CALL PLUT15 (1, I, 27, IVAL)
          END DO
        ELSE IF (IMODE == 2) THEN
          IPR(37) = IPR(39)
          IPR(38) = IPR(39)
          DO I = IPR(69) + 1, IPR(37)
            IVAL = 0
            CALL PLUT15 (16, I, 1, IVAL)
C * SET DEFAULT RESIDUE
            IF (IPR(136) == IPR(69)) THEN
              IVAL = 1
            END IF
            CALL PLUT15 (6,  I, 5, IVAL)
            IVAL = 0
C * RESET NUMBER OF CONNECTIONS TO OXYGEN ATOMS
            CALL PLUT15 (3,  I, 24, IVAL)
            IVAL = 0
C * RESET NR OF BONDS
            CALL PLUT15 (4,  I, 33, IVAL)
          END DO
        END IF
      END IF
      CALL GEN038 (IGGT, 1, 80)
C * (GENERAL) INITIALISATION
C * RESET NUMBER OF ARU'S
      IPR(142) = 0
C * RESET NUMBER OF ARU'S (TOTAL, UNIQUE, INTER)
      IPR(42)  = 0
      IPR(43)  = 0
      IPR(44)  = 0
C * SET BONDS
      IPR(52)  = IPR(68)
      IPR(53)  = IPR(68)
C * NON- RESET MODE 2 DEFAULTS
      IF (IMODE /= 2) THEN
C * DEFAULT UNIT VIEW MATRIX
        CALL GEN021 (R, 1.0)
C * BOX ON
      ELSE IF (IMODE == 2) THEN
        GO TO 20
      END IF
C * TOL
      PAR(2) = 0.4
C * PLDEF - PLOTTER RESOLUTION TO BE USED (CM)
      PAR(5)  = 0.09
C * TRDEF - RADIAL DECREMENT (MM) FOR RETRACING ATOMS
      PAR(3)  = 0.1
C * TLDEF - STEP FOR RETRACING LABELS
      PAR(4)  = 0.01
C * ANGSCF- DEFAULT ANGSTROM SCALING FACTOR
      PAR(11) = 1.0
C * RADEF - DEFAULT ATOM RADII
      PAR(21) = 0.5
C * CHDEF - DEFAULT CHARACTER SIZE (CM)
      PAR(349) = 0.25
C * DPDEF - DEFAULT FOR VIEW DISTANCE (CM)
      PAR(12) = 60.0
C * SHRNK - SHRINK RATIO
      PAR(13) = 0.9
C * TDEF  - TEXT DEFAULT SIZE (CM)
      PAR(14) = 0.4
      PAR(15) = 0.0
      PAR(16) = 0.0
C * EYE SEPARATION (CM)
      PAR(17) = 3.0
C * SET DEFAULT RATIO
      PAR(50) = (4.0 - IGBL(46)) / 3.0
      PAR(18) = - PAR(50)
C * RATIO - WIDTH OF CHARACTERS DEVIDED BY HEIGHT
      PAR(19) = 6.0 / 7.0
C * FRACTIONAL SCALING FACTOR
      PAR(25) = 1.0
C * BLACK/COLOR SHADE LINE DISTANCE STEP (TO FILL IN SPHERE)
      PAR(23) = 0.0195
C * SET TOLE - (EARTH) ALKALI - O,N, ... ADDITIONAL TOLERANCE
      PAR(26) = 0.7
C * OVERLAP MARGIN
      PAR(36) = 0.1
C * RBDEF
      PAR(38) = 0.0
C * LABEL SHIFT (CM)
      PAR(39) = 0.2
C * TAPER - DEFAULT FOR TAPERING OF BONDS
      PAR(44) = 0.25
C * SET DEF MONO PERSPECTIVE
      PAR(48) = 0.0
C * ANG1 BRIGHT SPOT
      PAR(51) = 25.0
C * ANG2 BRIGHT SPOT
      PAR(52) = 15.0
C * SPOT SIZE PARAMETER
      PAR(53) = 1.90
C * BOX TEXT OFFSET
      PAR(54) = 0.15
C * SET SHADOW MARGIN( ATOM-INCOMING BOND
      PAR(58) = 0.10
C * LABEL Z OFFSET (CM)
      PAR(60) = -100.0
C * RADII ALL PAR
      PAR(70) = 0.2
C * RADIUS ORIGIN/UNITCELL BONDS
      PAR(75) = 0.01
C * SET MIN D-H...A ANGLE
      PAR(97) = 100.0
C * CIRCLE SEGMENT PARAMETER
      PAR(125) = 5.25
      PAR(127) = - PAR(2)
C * SHADE DIST
      PAR(134) = 0.15
C * BWC-SHADE ANG1
      PAR(135) = 120.0
C * BWC-SHADE ANG2
      PAR(136) = -45
C * DEFAULT TRNS
      PAR(140) = 0
C * DEFAULT CROT ROTATION ANGLE
      PAR(145) = 1.0
C * CLOSENESS DIST CRITERIUM PLUT18
      PAR(149) = 0.05
C * ATOM IDENTITY DISTANCE CRITERIUM
      PAR(150) = 0.001
C * INTERACTIVE TEXT-SIZE
      PAR(350) = 0.50
C * TYPE 1 RADIUS FRACTION
      PAR(351) = 0.5
C * TYPE 2 RADIUS FRACTION
      PAR(352) = 0.5
C * TYPE 4 RADIUS FRACTION
      PAR(354) = 0.3
C * DEFAULT MAX ME-H
      PAR(461) = 2.1
C * ZN-O,N
      PAR(541) = 0.20
C * CU-O,N
      PAR(542) = 0.35
C * MN-O,N
      PAR(543) = 0.40
C * AG-O,N
      PAR(544) = 0.20
C * CR-O,N
      PAR(545) = 0.20
C * TL-O,N
      PAR(546) = 0.3
C * UNITCELL OFF
      IPR(46)  = 0
C * MONO
      IPR(116) = 0
C * STICK MODE O
      IPR(4)   = 0
C * NR OF CONTOURS
      IPR(74)  = 8
C * IENC = 0
      IPR(15)  = 0
C * IJN = 0
      IPR(17)  = 0
C * ILBC = 0
      IPR(18)  = 0
C * SET NUMBER OF MESH LINES
      IPR(54)  = 7
C * SET NON-INVERT
      IPR(65)  = 1
C * NO PARENTHESES
      IPR(71)  = 0
C * NPRH (NET)
      IPR(85)  = 24
C * NPRV (NET)
      IPR(86)  = 24
C * UNITCELL LINE NR
      IPR(107) = 2
C * HBONDS OFF
      IPR(109) = 0
C * EXPAND OFF
      IPR(110) = 0
C * (DE/IN)CREMENT NINC
      IPR(111) = 4
C * NR OF PARALLELS
      IPR(112) = 13
C * NO PUT
      IPR(117) = 0
C * NR OF DOTS ON STANDARD SPHERE
      IPR(124) = 5000
C * REBUILD
      IPR(130) = 0
C * LABEL SHIFT TRIALS
      IPR(131) = 4
C * NUMBER OF MERIDIANS
      IPR(132) = 24
C * SET ICROT-MAX
      IPR(152) = 100000
C * SET DELETE COLOR (CROT)
      IPR(153) = 0
C * SET WRITE COLOR (CROT)
      IPR(154) = 1
C * SET NRINCL
      IPR(165) = 2
C * SET INTER INCLUDE
      IPR(166) = 1
C * POVRAY-SIZE
      IPR(171) = 1024
      IPR(172) = 768
C * INCLUDE H-ATOMS (PLOT)
      IPR(212) = 1
C * DOAC-ATOM TYPES
      IPR(480) = 11
      IPR(19)  = 1
      IPR(5)   = 1
      IPR(6)   = 0
      IPR(7)   = 1
C * SET <CR> --> END for S
      IF (IGBL(50) == 0) THEN
        IF (IGBL(92) /= 0) IPR(308) = 1
      END IF
   20 RETURN
99999 FORMAT (/, ':: Full Init - PLATON/PLUTON (', I6, ') - ',
     1 'type  HELP for information', /, 42X,
     2 ' or   PLOT for default plot', //, 6X,
     3 '********************************************************', /,6X,
     4 '>> PLEASE type ''MENU OFF'' when you dont want the      <<', /,
     5 6X,'>>              MENU feature (X-window only!)         <<', /,
     6 6X,'********************************************************', /)
99998 FORMAT (':: Partial Init')
99997 FORMAT ('LABEL')
99996 FORMAT ('PLOT CAL')
99995 FORMAT ('CREATED BY PLATON ', /,
     1        'STRAW COLOR')
99994 FORMAT ('VIEW UNIT XROT', F7.0, ' YROT', F7.0, ' ZROT', F7.0)
99993 FORMAT ('VIEW INVERT')
99992 FORMAT ('PLOT DISPLAY')
99991 FORMAT (':: Data from: ', A)
99990 FORMAT (':: File ', A, ' NOT Available,',
     1        ' Interactive INPUT Assumed', /)
      END SUBROUTINE PLUT01
 
      SUBROUTINE PLUT02
C * SUBROUTINE CONTROLS ALL PLOTTING OF ATOMS, BONDS AND LABELS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE pluto
      USE chdat
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: I1
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: II
      INTEGER :: JJ
      INTEGER :: IO
      INTEGER :: JO
      INTEGER :: N0
      INTEGER :: IP
      INTEGER :: NE
      INTEGER :: NR
      INTEGER :: NAB
      INTEGER :: NAP
      INTEGER :: NAT
      INTEGER :: IP1
      INTEGER :: IP2
      INTEGER :: IPM
      INTEGER :: IRU
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: IVL
      INTEGER :: JAT
      INTEGER :: MPM
      INTEGER :: MR2
      INTEGER :: MS2
      INTEGER :: NMZ
      INTEGER :: NRS
      INTEGER :: NMLX
      INTEGER :: NTP1
      INTEGER :: NTP2
      INTEGER :: NTYP
      INTEGER :: NSPC
      INTEGER :: NRES
      INTEGER :: NORG
      INTEGER :: NARU
      INTEGER :: NINC
      INTEGER :: NATL
      INTEGER :: NATO
      INTEGER :: LTYP
      INTEGER :: JJJJ
      INTEGER :: IRES
      INTEGER :: ILAB
      INTEGER :: ILPB
      INTEGER :: IASU
      INTEGER :: IATK
      INTEGER :: ICMD
      INTEGER :: IDET
      INTEGER :: IDIS
      INTEGER :: NPROP
      INTEGER :: NINCL
      INTEGER :: JOMIT
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      INTEGER :: IDUM1
      INTEGER :: IDUM2
      INTEGER :: IDUM3
      INTEGER :: IDUM5
      INTEGER :: MADDR
      INTEGER :: IDPLT
      INTEGER :: ICOL0
      INTEGER :: INCLUDEX
      INTEGER :: FINDEXE
      REAL :: Q
      REAL :: RI
      REAL :: XI
      REAL :: YI
      REAL :: ZI
      REAl :: YK
      REAL :: XII
      REAL :: YII
      REAL :: ZII
      REAL :: PHI
      REAL :: P14
      REAL :: CLR
      REAL :: DIS
      REAL :: RAX
      REAL :: XNM
      REAL :: YNM
      REAL :: ZNM
      REAL :: XLAB
      REAL :: RA11
      REAL :: DUM4
      REAL :: DISK
      REAL :: DEYE
      REAL :: DIFF
      REAL :: XLNG
      CHARACTER(len=40)  :: TXT3
      CHARACTER(len=6)   :: TXT2
      CHARACTER(len=10)  :: KLEUR
      CHARACTER(len=255) :: PLPATH
C * CHECK FOR 'CURRENT-RESIDUE-NUMBER' = IPR(140)
      IF (IPR(140) < 0) THEN
        IVL = - IPR(140)
        CALL PLUT15 (-6, IVL, 5, IPR(140))
        DO I = 1, IPR(42)
          XNM = ABS (IARU(1, I) / PAR(42))
          IRES = IABS (IARU(1, I)) - INT (XNM) * NINT (PAR(42))
          IF (IRES /= IPR(140)) THEN
            IARU(1, I) = - NINT (XNM * PAR(42))
          ELSE
            IARU(1, I) =   NINT (XNM * PAR(42))
          END IF
        END DO
      END IF
      IPR(45) = 0
      IF (IGBL(2) > 0) THEN
C * TEST FOR REBUILD
        IF (IPR(130) == 0) THEN
C * SET NUMBER OF MOLECULES TO BE PLOTTED TO AT LEAST ONE (=INP. MOL)
          MADDR = 0
          CALL PLUT17 (0, 0.0, MADDR, LU6)
C * FIRST COUNT THE ACTIVE NUMBER OF MOLECULES
C * SET POINTER FOR ACTIVE ASU LIST
          MADDR = 0
          CALL PLUT17 (1002, 0.0, MADDR, LU6)
C * CALCULATE TOTAL NUMBER OF ACTIVE/PASSIVE PLOT ITEMS = ATOMS/LABELS
C * IN ARRAY RA BEFORE ACTUAL FILLING AND TEST WHETHER THERE IS ENOUGH
C * SPACE AVAILABLE FOR THIS PLOT REQUEST
C * FIRST NUMBER OF ATOM - ITEMS IN IPR(62)
          IPR(62) = IPR(142) * (IPR(37) - IPR(69)) + IPR(69)
C * SAVE NUMBER OF ATOM + ATOMLABEL ITEMS IN IPR(59)
          IPR(59) = IPR(62) + IPR(37) * IPR(452)
C * SAVE TOTAL NUMBER OF ITEMS IN IPR(40)
          IF (IPR(63) == 0) THEN
            IPR(40) = IPR(59)
          ELSE
            IPR(40) = IPR(59) + IPR(42)
          END IF
          IPR(125) = (IPR(37) + 1) * NP43
C * SET BOTTOM POINTER OF XP, YP, ZP, RP INFORMATION IN RA-ARRAY
          IPR(158) = IPR(125) + IPR(62) * IPR(82) * 4
C * RESERVE CROT SPACE
          NSPC     = NP0
          IPR(157) = IPR(158)
          IPR(167) = IPR(158)  + IPR(62) * NP0
          IPR(168) = IPR(158)  + IPR(62) * NP0
          IF (IPR(151) > 0) THEN
            IPR(158) = IPR(158) + IPR(62) * NP0
            NSPC     = 2 * NP0
            IF (IPR(116) /= 0) THEN
              IPR(167) = IPR(158) + IPR(62) * NP0
              IPR(168) = IPR(167) + IPR(62) * NP0
              NSPC     = 4 * NP0
            END IF
          END IF
C * CHECK FOR SUFFICIENT STORAGE
          IF (IPR(157) + NSPC * IPR(40) >= IPR(64) - IPR(52) * 2)
     1      THEN
            CALL PLUT38 (5, 0, LU6)
            GO TO 90
          END IF
        END IF
C * SET COUNTERS FOR PLOT ATOM, ATOM LABELS , MOL LABELS
        NAP  = 0
        NAT  = IPR(37)
        NATO = IPR(39)
        NARU = IPR(42)
        NATL = IPR(62)
        NRES = IPR(75)
        ILPB = IPR(69) + 1
        NAB  = NAT - ILPB + 1
        DISK = PAR(35)**2
C * BUILD UP ARRAY OF PLOT COORDINATES (IPR(130) = 0)
   10   IF (IPR(130) == 0) THEN
          IF (IPR(116) <= 0) THEN
C * INITIALISATION FOR THIS PLOT
            CALL GEN074 (PAR, 61, 63,  1E10)
            CALL GEN074 (PAR, 64, 66, -1E10)
            IF (IPR(49) /= 0) WRITE (IPR(49), 99998, IOSTAT = IOST)
C * SORT ACTIVE ASU LIST
            CALL GEN034 (RA, IPR(159) + 1 - IPR(142), IPR(159) - 1)
C * BEGIN LOOP ON ASU-LIST
            NMLX = IPR(142)
            DO M = 1, NMLX
              IF (M == 1) THEN
                I1 = 1
              ELSE
                I1 = ILPB
              END IF
              XNM = NINT (RA(IPR(159) + 1 - M))
              MPM = NINT (XNM * PAR(42))
              CALL GEN098 (MPM, PAR(42), N, ITX, ITY, ITZ, NR)
              TRL(1) = ITX
              TRL(2) = ITY
              TRL(3) = ITZ
C * DETERMINE ACTIVE RESIDUES (i.e. KRS(J) >= 0) FOR THIS ASU
              DO J = 1, NRES
                KRS(J) = -1
              END DO
C * LOOP OVER ARU'S
              DO J = 1, NARU
                YNM = IARU(1, J) / PAR(42)
                ZNM = INT (YNM)
                IF (XNM == ZNM)
     1              KRS (NINT ((YNM - XNM) * PAR(42))) = IARU(2, J)
              END DO
C * BEGIN LOOP ON ATOMS IN ASU
              DO I = I1, NAT
C * INCLUDEX = -1 EXCLUDE from PLOTTING
C * INCLUDEX =  1 INCLUDE in   PLOT
                INCLUDEX = - 1
C * FIRST GENERATE FRACTIONAL COORDINATES
                DO J = 1, 3
                  SGX(J)     = RA(I * NP43 + J)
                  SGX(J + 3) = TRL(J)
                  SGX(J + 6) = SGX(J)
                END DO
                IF (I >= ILPB) THEN
                  CALL SGSM (3, ICL, SGX, N, LU6, IERR)
C * TEST FOR ATOM OUTSIDE BOX ENCLOSURE FOR PLOT
                  IF (IPR(15) > 0) THEN
                    DO J = 1, 6
                      L    = (J + 1) / 2
                      JJJJ = L * 2 - J
                      DIFF = SGX(L + 6) - PAR(J + 28)
                      IF (DIFF < 0.0) THEN
                        IF (JJJJ /= 0) GO TO 30
                      ELSE IF (DIFF > 0.0) THEN
                        IF (JJJJ == 0) GO TO 30
                      END IF
                    END DO
                  ELSE IF (IPR(15) < 0) THEN
                    GO TO 20
                  END IF
                END IF
                IDIS = 10000
C * CHECK FOR 'MAJOR/MINOR DISORDER FORM ONLY'
                IF (IGBL(59) /= 0 .AND. I >= ILPB) THEN
                  CALL PLUT15 (-4, I, 28, IDIS)
                  IDIS   = IPPR(IDIS + 1, 1)
                END IF
                IF (IDIS < 10000) THEN
                  IF (IGBL(88) == 0) THEN
                    IF (IDIS >= 5000) INCLUDEX = 1
                  ELSE
                    IF (IDIS <= 5000) INCLUDEX = 1
                  END IF
                ELSE
                  INCLUDEX = 1
                END IF
C * MAKE ORTHONORMAL
   20           DO II = 1, 3
                  RA(II) = SGX(II + 6)
                END DO
                CALL PLUT23 (0)
C * TEST FOR ATOM OUTSIDE ENCLOSURE SPHERE FOR PLOT
                IF (IPR(15) < 0) THEN
                  IF (I >= ILPB) THEN
                    DIS = 0
                    DO II = 4, 6
                      DIS = DIS +
     1                   (RA( - IPR(15) * NP43 + II) - RA(II))**2
                    END DO
                    IF (DIS > DISK)  GO TO 30
                    INCLUDEX = 1
                  END IF
                END IF
C * ROTATE THE ORTHONORMAL COORDINATES
                CALL GEN002 (1, R, RA(4), XYZR, XLNG)
C * GET INCLUDE STATUS OF (PARENT) ATOM
                IF (I <= NATO) THEN
                  J = I
                ELSE
                  XLAB = RA(I * NP43 + 7)
                  DO J = ILPB, NATO
                    IF (RA(J * NP43 + 7) == XLAB) GO TO 30
                  END DO
                  GO TO 40
                END IF
   30           CALL PLUT15 (-1, J, 27, NINCL)
                IF (NINCL == 0) INCLUDEX = - 1
C * CHECK FOR 'HANGING' BOND
   40           IF (IPR(166) == 0) THEN
                  IF (I > NATO) THEN
                    CALL PLUT15 (-6, I, 11, IRU)
                    MPM = IABS (IARU(1, IRU + 1))
                    CALL GEN098 (MPM, PAR(42), MS2, ITX, ITY, ITZ, MR2)
                    SGX(6) = ITX
                    SGX(7) = ITY
                    SGX(8) = ITZ
                    SGX(1) = N
                    SGX(2) = TRL(1)
                    SGX(3) = TRL(2)
                    SGX(4) = TRL(3)
                    SGX(5) = MS2
                    CALL SGSM (8, ICL, SGX, 0, LU6, IERR)
                    NMZ = NINT (SGX(9)) * 1000 + NINT (SGX(10)) * 100
     1                  + NINT (SGX(11)) * 10  + NINT (SGX(12)) + 555
                    NMZ = NINT (NMZ * PAR(42)) + MR2
                    DO J = 1, NARU
                      IF (NMZ == IARU(1, J)) GO TO 50
                    END DO
                    INCLUDEX = -1
                  END IF
                END IF
   50           JOMIT = 0
C * LOOK FOR SPACIAL IDENTITY WITH PREVIOUSLY LOADED ATOM
                IF (IPR(4) /= 0 .AND. M > 1 .AND.
     1            INCLUDEX == 1) THEN
                  JO = ILPB - 1
                  II = IPR(158) + JO * NP0
                  DO N0 = ILPB, NAP
                    II = II + NP0
                    JO = JO + 1
                    IF (RA(II) > 0.0) THEN
                      IF (ABS (RA(II - 3) - XYZR(1)) < PAR(150))
     1                  THEN
                        IF (ABS (RA(II - 2) - XYZR(2)) < PAR(150))
     1                    THEN
                          IF (ABS (RA(II - 1) - XYZR(3)) < PAR(150))
     1                      THEN
                            IO = MOD (JO - ILPB, NAB) + ILPB
                            IF (IO <= IPR(39)) THEN
                              CALL PLUT15 (-1, IO, 27, NINC)
                              IF (NINC == 1) THEN
                                JOMIT = 1000
                                GO TO 60
                              END IF
                            END IF
                          END IF
                        END IF
                      END IF
                    END IF
                  END DO
                END IF
   60           NAP = NAP + 1
C * LOAD ATOM POSITIONS FOR CURRENT ARU
                IF (I >= ILPB) THEN
                  CALL PLUT15 (-6, I, 5, NRS)
                  IF (INCLUDEX == 1 .AND. NRS > 0) THEN
C * OMIT NON-ESSENTIAL DUMMY ATOMS
                    IF (I > IPR(38)) THEN
                      CALL PLUT15 (-4, I, 37, ILAB)
                      IF (ILAB == 0 .OR. M > 1) THEN
                        N2 = IPR(64) - IPR(53) * 2 - 1
                        N1 = IPR(64) - IPR(52) * 2 + 1
                        DO N0 = N1, N2, 2
                          ICMD = NINT (RA(N0))
                          IF (ICMD < 0) THEN
                            CYCLE
                          ELSE
                            JAT = NINT (RA(N0 + 1))
                            IF (I == JAT) GO TO 70
                          END IF
                        END DO
                        INCLUDEX = - 1
                        GO TO 80
                      END IF
                    END IF
   70               IF (KRS(NRS) < 0) INCLUDEX = - 1
                  END IF
C * GET ATOM TYPE
 
   80             RA11 = RA(I * NP43 + 11)
                  IF (RA11 < 0.0) THEN
                    IF (IPR(231) == 0) THEN
                      IATK = INT (RA(I * NP43 + 7) / 64000)
                      RAX  = RADR(IATK + 1, 1)
                    ELSE
                      RAX = ABS (RA11) * 0.35
                    END IF
                  ELSE
                    RAX  = RA11
                  END IF
                  IF (NRS /= 0) THEN
                    NPROP = KRS(NRS)
                  ELSE
                    NPROP = 0
                  END IF
                ELSE
C * CELL CORNER
                  IF (IPR(46) == 0) INCLUDEX = - 1
                  RAX   = PAR(75)
                  NPROP = 0
                END IF
C * TEST ASYM RESIDUE ONLY
                IF (IGBL(128) == 1) THEN
                  IF (M /= 1) INCLUDEX = -1
                END IF
                IF (INCLUDEX == 1) THEN
C * KEEP TRACK OF PLOT MAXIMA IN ANGSTROM UNITS
                  DO JJ = 1, 3
                    PAR(63 + JJ) = MAX (XYZR(JJ) + RAX, PAR(63 + JJ))
                    PAR(60 + JJ) = MIN (XYZR(JJ) - RAX, PAR(60 + JJ))
                  END DO
                ELSE
                  JOMIT = - 1000
                  IF (RAX > 0.0) THEN
                    RAX = - RAX
                  ELSE
                    RAX = - 1.0
                  END IF
                END IF
                RAX = RAX + JOMIT
                IASU = I * 1000 + M
                CALL PLUT14 (1, NAP, IASU, NPROP, XYZR(1), XYZR(2),
     1                       XYZR(3), RAX)
              END DO
C * END OF LOOP ON ATOMS
            END DO
C * END OF LOOP ON MOLECULES
C * GET ALL COORDS REFERRED TO CENTRE OF THE PLOT (Or Zoom-Centre) AS ORIGIN
            IF (IPR(342) /= 0) THEN
              CALL PLUT14 (-1, IPR(342), IASU, NPROP, PAR(67), PAR(68),
     1                         PAR(69), YK)
            END IF
            DO I = 1, 3
              IF (IPR(342) == 0)
     1        PAR(66 + I) = (PAR(60 + I) + PAR(63 + I)) / 2.0
              IF (I < 3 .OR. IPR(151) > 0) THEN
                PAR(60 + I) = (PAR(60 + I) - PAR(66 + I))
                PAR(63 + I) = (PAR(63 + I) - PAR(66 + I))
              END IF
            END DO
C * GET MAX AND MIN FOR PLOT BOUNDARIES ALLOWING A SAFETY MARGIN.
C * AND CALCULATE SCALE FACTOR TO FIT DRAWING IN BOX OF
C * VERTICAL   DIMENSION VERT
C * HORIZONTAL DIMENSION PAR(15) = PAR(18) * VERT
            PAR(15) = VERT * ABS (PAR(18))
            IF (PAR(64) + PAR(65) < 0.0001) THEN
              PAR(64) = 5
              PAR(65) = 5
            END IF
C * GET CENTIMETER/ANGSTROM SCALE  (AUTO OR USER SUPPLIED)
            IF (PAR(16) == 0.0 .AND. PAR(65) /= 0.0) THEN
              IF (PAR(64) / PAR(65) > ABS (PAR(18))) THEN
                PAR(24) = PAR(15) * PAR(13) / (2.0 * PAR(64))
              ELSE
                PAR(24) = VERT * PAR(13) / (2.0 * PAR(65))
              END IF
            ELSE
              PAR(24) = PAR(16)
            END IF
            PAR(61) = - PAR(15) / 2
            PAR(62) = - VERT  / 2
            PAR(64) = - PAR(61)
            PAR(65) = - PAR(62)
C * LOAD ACTIVE BONDS FROM IPR(79)
            IPR(79) = IPR(64) - IPR(52) * 2 - IPR(142)
            CALL PLUT16 (-6, IDUM1, IDUM2, IDUM3, DUM4, IDUM5)
C * SET SCRATCH POINTER OF TOP DOWN  OBSCURATION SCRATCH : IPR(66)
            IPR(66) = IPR(79) - IPR(97) * 4
          END IF
C * IF STEREO OR PERSPECTIVE REQUIRED ADJUST CO-ORDINATES.
          NORG = (1 - IPR(46)) * IPR(69)
          II   = IPR(158)
          K    = 0
          IF (IPR(116) > 0) THEN
            IF (IGBL(75) > 0) THEN
              NATL = IPR(40)
            END IF
          END IF
          DO I = 1, NATL
            II = II + NP0
            NPROP = NINT (RA(II - 4))
            XI = RA(II - 3)
            YI = RA(II - 2)
            ZI = RA(II - 1)
            RI = RA(II)
            IF (RI >= 0) THEN
              INCLUDEX =  1
            ELSE
              RI       =  ABS (RI)
              INCLUDEX = -1
            END IF
            IF (RI > 999.9) THEN
              JOMIT = 1000
              RI = RI - JOMIT
            ELSE
              JOMIT = 0
            END IF
            IF (IPR(116) <= 0) THEN
C * MONO AND LEFT STEREO
              XII = XI
              YII = YI
              ZII = ZI
              XI  = (XI - PAR(67)) * PAR(24)
              YI  = (YI - PAR(68)) * PAR(24)
              IF (IPR(151) == 0) THEN
                ZI = (ZI - PAR(66)) * PAR(24)
              ELSE
                ZI = (ZI - PAR(69)) * PAR(24)
              END IF
              RI = PAR(24) * RI
C * APPLY PERSPECTIVE REDUCTION ON RADIUS
              IF (PAR(48) > 0.0)
     1          RI = RI * PAR(48) / (PAR(48) - ZI)
              IF (IPR(82) /= 0 .AND. I <= IPR(62)
     1          .AND. I > NORG) THEN
                CALL PLUT25 (-1, I, IATK)
                IF (INCLUDEX == 1) THEN
C * OUTPUT ANGSTROM DATA TO MOGLI-FILE
                  IF (I <= IPR(69)) THEN
                    NQ1(3:4) = '  '
                    LTYP = NINT (RA(I * NP43 + 7))
                    IF (LTYP /= ICHAR (' ')) THEN
                      NQ1(1:2) = 'AR'
                    ELSE
                      NQ1(1:2) = 'NE'
                    END IF
                  END IF
                  K                              = K + 1
                  RA(IPR(125) + (I - 1) * 4 + 1) = K
                  RA(IPR(125) + (I - 1) * 4 + 2) = XII
                  RA(IPR(125) + (I - 1) * 4 + 3) = YII
                  RA(IPR(125) + (I - 1) * 4 + 4) = ZII
C * FOR POVRAY
                  IF (IPR(10) == 1) THEN
                    IF (IPR(4) /= 0) THEN
                      IO = MOD (I - ILPB, NAB) + ILPB
                      CALL PLUT15 (-1, IO, 27, NINCL)
                      IF (NINCL > 0) THEN
                        IF (IABS (IPR(477)) /= 0) THEN
                          IF (IPR(477) > 0) THEN
                            CALL GEN048 (-5, NPROP, 1, ICOL0)
                          ELSE IF (IPR(477) < 0) THEN
                            CALL PLUT15 (-6, IO, 5, NRS)
                            IF (NRS > 0 .AND. NRS <= 8) THEN
                              ICOL0 = NRS
                            ELSE
                              ICOL0 = 0
                            END IF
                          END IF
                          IF (ICOL0 > 0 .AND. ICOL0 <= 16) THEN
                            KLEUR = COLR(ICOL0)
                            CALL GEN020 (-1, KLEUR, 2, 10)
                            IF (ICOL0 == 16)
     1                        CALL GEN020 (1, KLEUR, 6, 6)
                          ELSE
                            KLEUR = '  color_C '
                          END IF
                        ELSE
                          NTYP = IEL(IEN(IATK))
                          NTP1 = NTYP / 100
                          NTP2 = NTYP - NTP1 * 100 + ICHAR ('a') - 1
                          NTP1 = NTP1 + ICHAR ('A') - 1
                          IF (NTP2 == ICHAR ('a') - 1)
     1                      NTP2 = ICHAR (' ')
                          KLEUR = '  color_'//CHAR (NTP1)//CHAR (NTP2)
                        END IF
                        WRITE (LU61, 99999, IOSTAT = IOST)
     1                    NQ1, XII - PAR(67), YII - PAR(68),
     2                    - ZII + PAR(69), RI / PAR(24), KLEUR
                      END IF
                    END IF
C * PDB (RASMOL)
                  ELSE IF (IPR(10) == 2) THEN
                    IO = MOD (I - ILPB, NAB) + ILPB
                    CALL PLUT15 (-1, IO, 27, NINCL)
                    IF (NINCL > 0) THEN
                      WRITE (LU60, 99997, IOSTAT = IOST)
     1                  I, NQ1(1:5), 0, XII - PAR(67), - YII + PAR(68),
     2                  - ZII + PAR(69),  1.0, 0.0
                    END IF
                  END IF
                END IF
              END IF
            END IF
            IF (IPR(151) == 0) THEN
              Q = 1.0
              IF (PAR(48) > 0.0) Q = PAR(48) / (PAR(48) - ZI)
              IF (IPR(116) == 0) THEN
C * PERSPECTIVE ONLY
                XI = XI * Q
                YI = YI * Q
              ELSE
C * STEREO AND PERSPECTIVE
                IF (IPR(6) < 0) THEN
                  DEYE = - PAR(17)
                ELSE
                  DEYE =   PAR(17)
                END IF
                IF (IPR(116) < 0) THEN
C * STEREO COORDS FOR LEFT EYE VIEW
                  XI = (XI + DEYE) * Q - DEYE
                  YI = YI * Q
                ELSE
C * STEREO COORDS FOR RIGHT EYE VIEW
                  XI = XI + 2.0 * DEYE * (1.0 - Q)
                END IF
              END IF
            END IF
            RA(II - 3) = XI
            RA(II - 2) = YI
            RA(II - 1) = ZI
            RA(II)     = (RI + JOMIT) * INCLUDEX
          END DO
        END IF
        IF (IPR(116) <= 0) THEN
          IGBL(32) = IABS (IGBL(32))
          IWIN     = IGBL(25) * IGBL(32)
 
C * PLOT INITIALISATION
          BCD = 'P.L.U.T.O.N'//CHAR (0)
          IF (IGBL(50) == 0) THEN
            CALL GGIP ((1 + IABS (IPR(6))) * PAR(15), VERT, PAR(25), 1)
          ELSE
            CALL GGIP (XSH0, YSH0, 0.0, -3)
          END IF
C * SHIFT ORIGIN TO PAR(64),PAR(65)
          CALL GGIP (PAR(64), PAR(65), 0.0, -3)
        END IF
        IF (IPR(82) /= 0) THEN
        END IF
C * DEFAULT PEN
        CALL GGIP (0.0, FLOAT (IPR(19)), 0.0, 0)
C * RED/GREEN OR GREEN/RED STEREO
        IF (IPR(6) == 0) THEN
          IF (IPR(116) == -1) THEN
C * LEFT STEREO
            CALL GGIP (0.0, FLOAT (IPR(143)), 0.0, 0)
          ELSE IF (IPR(116) == 1) THEN
C * RIGHT STEREO
            CALL GGIP (0.0, FLOAT (IPR(144)), 0.0, 0)
          END IF
        END IF
C * PLOT SPECIAL TEXT
        LMOD = 0
        CALL PLA109 (2, 1, 0.0, 0.0)
C * PLOT SEQUENCE: ATOMS/LABELS/BONDS
        IF (IPR(151) <= 0) THEN
          IF (IGBL(25) * IGBL(32) == 1) THEN
            IF (IGBL(50) == 0) THEN
              BCD = 'Click HERE to INTERRUPT PLOTTING'//CHAR (0)
              CALL GGIP (-999.0, 2.0, 33.0, 111)
            END IF
            IF (IPR(116) == 0) THEN
C * DEFAULT PEN
              CLR = IPR(19)
            ELSE IF (IPR(116) > 0) THEN
              CLR = IPR(144)
            ELSE
              CLR = IPR(143)
            END IF
              CALL GGIP (0.0, CLR, 0.0, 0)
          END IF
C * PLOT ATOMS
          IF (IPR(10) <= 0) THEN
            CALL PLUT11
C * POSITION AND PLOT LABELS (UNLESS INTERRUPTED I.E. IPR(45) = 0)
            IF (IPR(45) == 0) CALL PLUT04 (1, 0)
          END IF
        ELSE
          IF (IGBL(25) * IGBL(32) == 1) THEN
            BCD = 'Click on Window to STOP Rotation'//CHAR (0)
          ELSE
            TXT3 = 'Freeze CROTX Rotation by pressing CTRL-C'
            TXT3(12:12) = CHAR (ICHAR ('W') + IPR(155))
          END IF
          IF (IPR(169) == 0) THEN
            IF (IGBL(25) * IGBL(32) == 1) THEN
              CALL GGIP (-999.0, 2.0, 33.0, 111)
            ELSE
              CALL PLA439 (0.0, TXT3, 40, PAR(14) * 1.4, 2, 2, PAR(61),
     1          PAR(62) + PAR(14) * 0.7)
            END IF
          END IF
        END IF
C * PLOT BONDS
        IF (IPR(45) == 0) CALL PLUT10
C * PLOT TITLE/BOX WITH DEFAULT PEN SELECTED
        IF (IPR(45) == 0 .AND. IGBL(103) == 1) THEN
          P14  = PAR(14)
          IPM = MIN (NINT ((PAR(64) - PAR(61)) / P14) - 14, 74)
          CALL PLA439 (0.0, JID, IPM, P14, IPR(19), 1,
     1        PAR(61) + 7 * P14, PAR(62) + PAR(54))
          CALL GEN040 (IGBL(4), NQ2, IP)
          CALL PLA439 (90.0, PROGNM//' - ('//NQ2(1:IP)//')',
     1         IP + 33, P14, IPR(19), 1, PAR(61) + P14 + PAR(54),
     2         PAR(62) + 3 * P14)
C * DRAW BOX DEFINING THE LIMIT OF PLOTTING COORDS
          CALL GGIP (PAR(61), PAR(62), 0.0, 3)
          CALL GGIP (PAR(61), PAR(65), 0.0, 2)
          CALL GGIP (PAR(64), PAR(65), 0.0, 2)
          CALL GGIP (PAR(64), PAR(62), 0.0, 2)
          CALL GGIP (PAR(61), PAR(62), 0.0, 2)
C * REPORT ON '.def'
          IF (IGBL(23) == 1) THEN
            CALL PLA439 (0.0, 'DEF-FILE ACTIVE', 15, P14,
     1        5 + IGBL(68), 1, PAR(64) - 55 * P14,
     2        PAR(65) - PAR(54) - P14)
          END IF
C * REPORT ON (NO)MOVE
          IF (IGBL(60) > 0) THEN
            CALL PLA439 (0.0, 'INPUT ATOMS MOVED', 17,
     1        P14, 2, 1, PAR(64) - 41 * P14, PAR(65) - PAR(54) - P14)
          ELSE
            IF (IGBL(30) == 1) THEN
              CALL PLA439 (0.0, 'NOMOVE FORCED', 13, P14,
     1          3, 1, PAR(64) - 37 * P14, PAR(65) - PAR(54) - P14)
            END IF
          END IF
C * PLOT TEXT
          CALL PLA439 (0.0, TEXT, 20, P14, 1, 1, -30 * P14 , PAR(65)
     1      - PAR(54) - P14)
C * PLOT XROT,YROT,ZROT AND VIEW DISTANCE IN BOX CORNERS
          IDPLT = INT(PAR(48))
          IF (IDPLT > 998) IDPLT = 0
          CALL GEN096 (R, IROTX, IROTY, IROTZ, IDET, XYZOR, PHI, ROM)
          IPR(65) = IDET
          IF (IDET == -1) CALL PLA439 (0.0, 'INVERT', 6, P14,
     1        3, 2, PAR(64) - 13 * P14, PAR(65) - PAR(54) - P14)
          CALL GEN040 (IPR(140), NQ1, IP)
          TXT2 = 'RES='//NQ1(1:2)
          CALL PLA439 (0.0, TXT2, 6, P14, 1, 1, PAR(64)
     1              - 21 * P14, PAR(65) - PAR(54) - P14)
          CALL GEN040 (IROTX, NQ1, IP)
          NQ1(IP + 1:IP + 2) = ' X'
          IP                 = IP + 2
          CALL PLA439 (0.0, NQ1, IP, P14, 1, 1, PAR(64) - IP * P14,
     1         PAR(62) + PAR(54))
          CALL GEN040 (IROTY, NQ1, IP)
          NQ1(IP + 1:IP + 2) = ' Y'
          IP                 = IP + 2
          CALL PLA439 (90.0, NQ1, IP, P14, 1, 1,
     1         P14 + PAR(54) + PAR(61), PAR(65) - IP * P14)
          CALL PLA439 (0.0, 'Z', 1, P14, -1, 1, PAR(61) + PAR(54),
     1         PAR(62) + PAR(54))
          CALL GEN040 (IROTZ, NQ1, IP)
          CALL PLA439 (0.0, NQ1, IP, P14, 1, 1,
     1           PAR(61) + PAR(54) + 2 * P14, PAR(62) + PAR(54))
          CALL GEN040 (IDPLT, NQ1, IP)
          CALL PLA439 (0.0, NQ1, IP, P14, 1, 1, PAR(64) - IP * P14,
     1         PAR(65) - PAR(54) - P14)
        END IF
C * TEST IF STEREO PAIR IS TO BE DRAWN
        IF (IPR(116) < 0) THEN
          IPR(116) = 1
C * NO SHIFT OF  PLOTTER ORIGIN FOR IPR(6) = 0
          IF (IABS(IPR(6)) > 0)
     1        CALL GGIP (ABS(PAR(15)), 0.0, 0.0, -3)
          GO TO 10
        ELSE
          IPR(116) = - IPR(116)
C * LIST ATOMS, BONDS, ARU'S, LINES
          IF (IPR(130) == 0 .AND. IPR(145) == 1) THEN
            IPR(90) = 254
          END IF
C * SET REBUILD
          IPR(130) = 1 + IPR(116)
C * POVRAY
          IF (IPR(340) /= 0) THEN
            IF (IGBL(98) == 1) THEN
              CLOSE (UNIT = LU61)
              XGGIP = -999.0
              YGGIP = 0.0
              ZGGIP = 0.0
              IF (IGBL(123) == 0) THEN
              CALL GGIP (XGGIP, YGGIP, ZGGIP, -8)
              IPR(172) = MIN (IPR(172), NINT (YGGIP))
              IPR(171) = NINT (IPR(172) * ABS (PAR(18)))
              ELSE
                IPR(172) = 768 * IGBL(123)
                IPR(171) = NINT (IPR(172) * ABS (PAR(18)))
              END IF
              CALL GEN040 (IPR(171), NQ1, IP1)
              CALL GEN040 (IPR(172), NQ2, IP2)
              CALL GEN038 (PLPATH, 1, 255)
C * FIND povray
              NE = FINDEXE ('POVEXE', PLPATH, 'povray')
              IF (NE > 0) THEN
                PLPATH(NE +1:) =
     1 ' +P +D +A0.3 +W'//NQ1//'+H'//NQ2//'+I'//NAMEFIL(1:KNMFIL)//' &'
                KERR = 0
                CALL SPAWN (PLPATH, LU6, .true., KERR)
                IPR(340) = 0
              ELSE
                CALL PLA015 (0, 9)
              END IF
              IGBL(98) = -1
            ELSE IF (IGBL(11) == 1) THEN
              CLOSE (UNIT = LU60)
              CALL GEN038 (PLPATH, 1, 255)
C * FIND rasmol
              NE = FINDEXE ('RASEXE', PLPATH, 'rasmol')
              IF (NE > 0) THEN
                PLPATH(NE + 1:) = ' '//NAMEFIL(1:KNMFIL)//'.ras &'
                KERR = 0
                CALL SPAWN (PLPATH, LU6, .true., KERR)
                IPR(340) = 0
              ELSE
                CALL PLA015 (0, 9)
              END IF
              IGBL(11) = -1
            END IF
          END IF
        END IF
      END IF
   90 RETURN
99999 FORMAT ('// ', A, /, 7X, 'sphere {', /,
     1        15X, '< ', F9.4, ',', F9.4, ',', F9.4, ' >,', F5.2, /,
     3        15X, 'texture { pigment { color ',A, '}', /,
     4        15X, 'finish { finish_all } } }')
99998 FORMAT (//, ' NR  NARU ATNR LABEL     XMOL', 9X, 'X', 9X, 'Y',
     1       9X, 'Z', 9X, 'RAX'/)
99997 FORMAT ('ATOM', 2X, I5, 1X, A, 4X, I5, 4X, 3F8.3, 2F6.2)
      END SUBROUTINE PLUT02
 
      SUBROUTINE PLUT03 (IER)
C * ATOM CARD HANDLING
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: I4
      INTEGER :: II
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: LOP
      INTEGER :: IWD
      INTEGER :: NED
      INTEGER :: NQX
      INTEGER :: NSS
      INTEGER :: NSYM
      INTEGER :: NQSM
      INTEGER :: NPOP
      INTEGER :: NIEN
      INTEGER :: NATX
      INTEGER :: MODE
      INTEGER :: MULT
      INTEGER :: IDUM
      INTEGER :: IVAL
      INTEGER :: IYUNK
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: IANIS
      INTEGER :: IANP1
      INTEGER :: INTPOP
      INTEGER :: ICLOSE
      INTEGER :: IER
      REAL :: SJ
      REAL :: YY
      REAL :: VRS
      REAL :: XLNG
      REAL :: TRNS
      REAL :: UISO
      REAL :: VERS
      REAL :: PAR22
      REAL :: DCLOSE
      REAL, DIMENSION(3) :: DUMA
      I4   = 0
      KL   = IPR(220)
      KN   = IPR(221)
      NSYM = IPR(48)
      MULT = NSYM
C * HANDLE X (= DISORDER) CHARACTER
      IF (KL == 3 .AND. IFL(3)(1:1) == 'X') THEN
        IPR(220) = 2
        KL       = IPR(220)
      END IF
C * CHECK FOR ADEQUATE NUMBER OF DATA ON CARD
      IF (KL > 3 .OR. KL == 0) THEN
        WRITE (LU6, 99997, IOSTAT = IOST) ICL(1:80)
        IER = 1
        RETURN
      END IF
      IF (KN > 0 .AND. KN < 3) THEN
        IF (INDEX (ICL, '.RES') == 0)
     1    WRITE (LU6, 99998, IOSTAT = IOST) ICL(1:70)
        IER = 1
        RETURN
      END IF
C * DEFAULT S>O>F. TO 1.0
      IF (KN == 3) FN(4) = 1.0
C * CIF STYLE ATOM LABEL
      IF (IGBL(8) == 3) THEN
        NQ1 = IFL(2)
C * RES STYLE ATOM LABEL
      ELSE IF (IGBL(8) == 2) THEN
        NQ1 = IFL(1)
        IF (IPR(538) /= 0) THEN
          N = INDEX (NQ1, ' ')
          IF (N /= 0) THEN
            IF (IPR(538) < 10) THEN
              WRITE (NQ1(N:N + 1), 99994, IOSTAT = IOST)
     1          IPR(538)
            ELSE
              WRITE (NQ1(N:N + 2), 99993, IOSTAT = IOST)
     1          IPR(538)
            END IF
          END IF
          IFL(KL) = NQ1
        END IF
C * SPF STYLE ATOM LABEL
      ELSE IF (IGBL(8) == 1) THEN
C * ADD RESIDUE NUMBER TO LABEL (SHELXL STYLE)
        IF (IFL(1)(1:4) == 'ATOM' .OR. IFL(1)(1:2) == 'U ' .OR.
     1    IFL(1)(2:3) == 'IJ' .OR. IFL(1)(3:4) == 'IJ') THEN
          NQ1 = IFL(2)
          NQ2 = IFL(3)
          CALL GEN020 (-1, IFL(3), 2, 2)
C * ADD ELEMENT TYPES FOR NON C, H, N, O TYPES
          DO I = 1, 105
C * GET ELEMENT 'NUMBER' AND CODING NUMBER
            IF (IFL(3)(1:2) == ELB(I)) THEN
C * SKIP FOR C, H, N, O
              IF (I > 4) THEN
                IANP1      = IAN + 1
                IEN(IANP1) = I
 
                DO J = 5, IANP1
                  IF (IEL(I) == IEL(IEN(J))) THEN
                    IF (J == IANP1) IAN = IANP1
                    EXIT
                  END IF
                END DO
              END IF
              EXIT
            END IF
          END DO
        ELSE
          NQ1 = IFL(1)
        END IF
C * PDB STYLE ATOM LABEL
      ELSE IF (IGBL(8) == 4) THEN
        NQ1 = IFL(1)
      ELSE
        NQ1 = IFL(1)
      END IF
C * PACK LABEL INFORMATION
      MODE = 9
      LOP  = 0
C * SAVE INPUT LABEL
      NQ4  = NQ1
      CALL GEN020 ( 1, NQ4, 1, NP64)
      CALL GEN020 (-1, NQ4, 2, 2)
      NQ1 = NQ4
      DO
        CALL PLA046 (MODE, NQ1, NED, NQX, NSS, NQSM, INQNR, JNQNR, NIEN)
C * CALL EXIT/STOP
        IF (NIEN == -2)
     1    CALL GEN127 ('Stop:: More that 16 atom types !!')
        LOP = LOP + 1
C * CHECK FOR ERROR RETURN
        IF (NIEN < 0) THEN
          IF (IABS (IGBL(8)) >= 1 .OR. IABS (IGBL(8)) <= 3) THEN
            IF (IABS(IGBL(8)) == 1 .AND. KL == 3)
     1        NQ1 = IFL(3)
            CALL GEN020 (1,NQ1, 1, 2)
            IF (IABS(IGBL(8)) == 3 .OR. IABS (IGBL(8)) == 1) THEN
              IF (ICHAR (NQ1(2:2)) >= 48 .AND.
     1            ICHAR (NQ1(2:2)) <= 48) THEN
                NQ1(2:) = ' '
              ELSE
                NQ1(3:) = ' '
              END IF
            ELSE
              NQ1 = SFC(NINT (FN(1)))
            END IF
C * CREATE ACCEPTABLE LABEL
            IF (NQ1(1:1) == ' ') THEN
              NQ1(1:) = NQ1(2:2)
              NQ1(2:4) = '999'
            ELSE IF (NQ1(2:2) == ' ') THEN
              NQ1(2:) = '999'
            ELSE
              NQ1(3:) = '99'
            END IF
            MODE = 10
            IF (LOP == 1) CYCLE
          END IF
        END IF
        IF (LOP >= 1) EXIT
      END DO
      IF (NIEN < 0 .OR. NQSM > 0) THEN
        IF (NIEN < 0 .OR. IPR(50) == 0) THEN
          WRITE (LU6, 99996, IOSTAT = IOST) NQ1
          IER = 1
          RETURN
        END IF
      END IF
C * TEST FOR PREVIOUS CELL CARD HANDLING; IF NOT, DO SO
      IF (IPR(51) == 0) CALL PLUT23 (-1)
      ICLOSE = 0
      IANIS  = 0
      UISO   = -1.0
C * SKIP FOR ANGSTROM (IPR(50) /= 0) COORDINATE INPUT
      IF (IPR(50) == 0) THEN
C * HANDLE CASE OF SHELX INPUT (AS PRODUCED BY SHELX)
        IF (IABS(IGBL(8)) == 2) THEN
          IF (KN == 11) IANIS = 1
          RP(1) = 1
C * IGNORE DIFFERENCE MAP DENSITY WHEN PRESENT
          IF (KN == 7) THEN
            IPR(221) = 6
            KN       = IPR(221)
          END IF
          DO I = 2, KN
            YY = FN(I)
            IF (ABS (YY) > 5.0) THEN
              J  = NINT (ABS (YY) * 0.1)
              SJ = SIGN (0.5, YY)
              IF (J /= 1 .AND. J > IPR(13)) CALL PLUT38 (4, 1, LU6)
              YY = (YY - J * SJ * 20.0) * (RP(J) + SJ - 0.5)
            END IF
            FN(I - 1) = YY
          END DO
          IF (KN == 6 .AND. FN(6) > 0.0) UISO = - FN(6) / 0.04
          FN(KN)   = 0.0
          IPR(221) = IPR(221) -1
          KN       = IPR(221)
        END IF
C * SKIP ATOMS WITH POPULATION ZERO
        IF (IABS (IGBL(8)) /= 2 .AND. KN == 8 .OR.
     1      IABS (IGBL(8)) == 2 .AND. KN > 3) THEN
          IF (FN(4) < 0.0001) THEN
            WRITE (LU6, 99995, IOSTAT = IOST) NQ1
            IER = 1
            RETURN
          END IF
        END IF
C * APPLY CELL TRANSFORMATION OR DE-ORTHOGONALIZATION
        IF (IPR(127) > 0 .OR. IPR(156) > 0) THEN
          IF (IPR(156) == 1) THEN
            CALL GEN002 (1, ROM, FN, SGX, XLNG)
            DO J = 1, 3
              FN(J) = SGX(J)
            END DO
          ELSE
            CALL GEN002 (1, TMY, FN, SGX, XLNG)
            IGBL(30) = 0
            DO J = 1, 3
              FN(J) = MOD (SGX(J), 1.0)
            END DO
          END IF
        END IF
C * CHECK WHETHER THIS ATOM IS NOT ALREADY PRESENT IN THE ATOM LIST
C * IF SO THEN SKIP IT
        I2 = (IPR(37) + 1) * NP43
        I4 = I2 + NP43
        DO J = 1, 3
          SGX(J + 3) = 0.0
C * ADD SHIFT VECTOR
          IF (IPR(128) > 0) FN(J) = FN(J) + SHFT(J)
          SGX(J)     = FN(J)
          RA(I2 + J) = FN(J)
          RA(I4 + J) = 0.0
        END DO
        SGX(10) = 0.0
        CALL SGSM (19, ICL, SGX, 0, LU6, IERR)
C * SPECIAL MULTIPLICITY HANDLING FOR CIF (IGBL(8) = 3)
        IF (IGBL(8) == 3) FN(4) = FN(4) * SGX(10)
        IF (ABS (1.0 - FN(4) / SGX(10)) < 0.001) THEN
          PAR22 = PAR(22)
        ELSE
          PAR22 = 0.1
        END IF
        MULT   = 0
        ICLOSE = 0
        DCLOSE = 999.0
        DO J = 1, NSYM
          CALL SGSM (3, ICL, SGX, J, LU6, IERR)
C * START BEYOND (0 or 8) UNITCELL VERTICE COORDINATES
          I1   = (IPR(69) + 1) * NP43
          II   = IPR(69)
          DO I = I1, I2, NP43
            II   = II + 1
            VERS = 0.0
            DO K = 1, 3
              VRS = RA(I + K) - SGX(K + 6)
              DO
                IF (VRS <= 0.5) EXIT
                SGX(K + 6) = SGX(K + 6) + 1.0
                VRS        = VRS - 1.0
              END DO
              DO
                IF (VRS > - 0.5) EXIT
                SGX(K + 6) = SGX(K + 6) - 1.0
                VRS        = VRS + 1.0
              END DO
              DUMA(K) = VRS
            END DO
            VERS = SQRT ((PAR(101) * DUMA(1)) **2
     1        + (PAR(102) * DUMA(2)) **2
     2        + (PAR(103) * DUMA(3)) **2
     3        + 2.0 * PAR(101) * PAR(102) * PAR(106) * DUMA(1) * DUMA(2)
     4        + 2.0 * PAR(101) * PAR(103) * PAR(105) * DUMA(1) * DUMA(3)
     5        + 2.0 * PAR(102) * PAR(103) * PAR(104) * DUMA(2) * DUMA(3)
     6        )
            IF (VERS < PAR22) THEN
              IF (I == I2) THEN
                MULT = MULT + 1
                DO K = 1, 3
                  RA(I4 + K) = RA(I4 + K) + SGX(K + 6)
                END DO
              ELSE
                CALL PLUT25 (2, II, IDUM)
                ICLOSE = 1
                DCLOSE = VERS
              END IF
            END IF
          END DO
        END DO
      END IF
      IF (IPR(37) == IPR(69)) THEN
        IPPR(1, 3) = NSYM
      END IF
      NATX = IPR(37) + 1
C * STORE BOTTOM UP
      I          = NATX * NP43
      RA(I + 6)  = JNQNR
      RA(I + 7)  = INQNR
      RA(I + 8)  = 0.0
      RA(I + 9)  = 0.0
      RA(I + 10) = 0.0
      IF (PAR(141) > 0.0) THEN
        TRNS     = PAR(141)
        PAR(141) = 0.0
      ELSE
        TRNS     = PAR(140)
      END IF
      RA(I + 11) = UISO
      RA(I + 12) = TRNS
      DO II = 1, 3
        IF (IPR(50) == 1) THEN
          RA(I + II) = FN(II) * PAR(11)
        ELSE
          IF (MULT == 0) MULT = 1
          RA(I + II) = RA(I4 + II) / MULT
        END IF
      END DO
C * HANDLE POPULATION PARAMETER
      NPOP = IPR(9)
        FN(4) = MIN (1.0, FN(4) * MULT)
      IF (NQ1(1:1) == 'Q' .OR. FN(4) < 0.001) FN(4) = 1.0
      INTPOP = NINT (FN(4) * 10000.0)
      IF (MULT == 48 .AND. INTPOP > 9997) INTPOP = 10000
C * SKIP NON-DISORDER CLOSE ATOMS (DUPLICATE ?)
      IF (PAR(22) >= 0.0) THEN
        IF (INTPOP == 10000 .AND. ICLOSE == 1 .AND.
     1    (NQ1(1:1) /= 'Q' .OR.
     2    (NQ1(1:1) == 'Q' .AND. NQ2(1:1) == 'Q'))) THEN
          WRITE (LU6, 99999, IOSTAT = IOST) NQ1, DCLOSE, NQ2
          IER = 1
          RETURN
        END IF
      END IF
      IF (KN > 3) THEN
        IF (INTPOP == 5000 .AND. MULT == 1) THEN
          IF (FN(4) > 0.5) INTPOP = 5001
          IF (FN(4) < 0.5) INTPOP = 4999
        END IF
      END IF
      IPPR(NPOP + 1, 1) = INTPOP
      IPPR(NPOP + 1, 3) = NSYM / MULT
      IPR(37) = NATX
      IPR(38) = NATX
      IPR(39) = NATX
      IF (IABS (IGBL(8)) >= 1 .AND. IABS (IGBL(8)) <= 3) THEN
        CALL PLUT25 (2, NATX, IDUM)
        IF (NQ1 /= NQ4) THEN
          CALL PLA282 (1, NQ4, NQ2, LU6)
        END IF
      END IF
      II = NPOP
      DO N = 1, NPOP
        IF (IPPR(N, 1) == IPPR(NPOP + 1, 1)) THEN
          II = N - 1
          EXIT
        END IF
      END DO
      IF (II == NPOP) THEN
        IF (NPOP < MP7) IPR(9) = NPOP + 1
      END IF
      CALL PLUT15 (4, NATX, 28, II)
C * SET MULTIPLICITY AND INCLUDE TO 1
      CALL PLUT15 (6, NATX, 18, MULT)
      IVAL = 1
      CALL PLUT15 (1, NATX, 27, IVAL)
      IVAL = 0
      CALL PLUT15 (4, NATX, 37, IVAL)
C * SET SHELXL PART #
      IYUNK = IPR(612) + 16
      CALL PLUT15 (5, NATX, 48, IYUNK)
C * SET ISO/ANISO
      CALL PLUT15 (1, NATX, 41, IANIS)
C * GET A CHARACTERISTIC NUMBER TO IDENTIFY ATOM TYPE LATER ON.
      CALL PLUT25 (0, NATX, N1)
      N2 = IEN(N1)
C * TEST FOR INORG/ORGA
      IF (N2 == 2) IGBL(97) = 1
      IF (N1 > 4) THEN
        RADR(N1, 3) = REL(N2)
        RADR(N1, 4) = VDWR(N2)
      END IF
C * SET DO/AC BIT
      DO II = 1, IPR(480)
        IF (N2 == IDOAC(II)) THEN
          IVAL = 1
          CALL PLUT15 (1, NATX, 46, IVAL)
          EXIT
        END IF
      END DO
C * SET METAL BIT
      IF (IATPR(N2) > 0) THEN
        IWD = 1
      ELSE
        IWD = 0
      END IF
      CALL PLUT15 (1, NATX, 17, IWD)
C * H-ATOM BIT (H & D)
      IF (N2 == 1 .OR. N2 == 33) THEN
        IWD = 1
      ELSE
        IWD = 0
      END IF
      CALL PLUT15 (1, NATX, 44, IWD)
C * SET DEFAULT RESIDUE
      IF (IPR(136) == 0) THEN
        IVAL = 0
      ELSE
        IVAL = IPR(136)
      END IF
      CALL PLUT15 (6, NATX, 5, IVAL)
      IER = 0
      IF (IPR(50) * IPR(135) > 0) THEN
        RA(NATX * NP43 + 3) = RA(NATX * NP43 + 3) + IPR(135) * 100.0
      END IF
      RETURN
99999 FORMAT (':: ATOM ', A, ' eliminated. (within', F5.2,' Ang.',
     1 ' from ', A, ')')
99998 FORMAT (':: Less than 3 numbers on ATOM record',
     1        ' (or unrecognized instruction)', /, ':: =>> ', A, /)
99997 FORMAT (':: Inadequate number of text items on ATOM record', /, A)
99996 FORMAT (':: ATOM label ', A, ' not acceptable')
99995 FORMAT (':: (Dummy) Atom ', A, ' with zero population skipped')
99994 FORMAT ('_', I1)
99993 FORMAT ('_', I2)
      END SUBROUTINE PLUT03
 
      SUBROUTINE PLUT04 (MODE, NATR)
C * THIS ROUTINE ATTEMPTS TO FIND MINIMUM OVERLAP POSITIONS FOR LABELS
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE pluto
      USE chdat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: M0
      INTEGER :: MM
      INTEGER :: JB
      INTEGER :: JE
      INTEGER :: II
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: IP
      INTEGER :: NB
      INTEGER :: NM
      INTEGER :: NR
      INTEGER :: NT
      INTEGER :: NTM
      INTEGER :: NT0
      INTEGER :: NRS
      INTEGER :: NMLX
      INTEGER :: KLB
      INTEGER :: IP0
      INTEGER :: ILB
      INTEGER :: IAI
      INTEGER :: IAJ
      INTEGER :: IAT
      INTEGER :: IHA
      INTEGER :: INM
      INTEGER :: IVL
      INTEGER :: NAB
      INTEGER :: NAT
      INTEGER :: NATL
      INTEGER :: NATO
      INTEGER :: NATX
      INTEGER :: NATY
      INTEGER :: MMIN
      INTEGER :: LABL
      INTEGER :: ISET
      INTEGER :: IREN
      INTEGER :: ILBO
      INTEGER :: ILPB
      INTEGER :: IBEG
      INTEGER :: ICOL
      INTEGER :: IEND
      INTEGER :: IATK
      INTEGER :: IASU
      INTEGER :: IVAL
      INTEGER :: LFIX
      INTEGER :: LMAX
      INTEGER :: MODE
      INTEGER :: NATR
      INTEGER :: NPROP
      INTEGER :: MSTEP
      INTEGER :: LMODE
      INTEGER :: LABL0
      INTEGER :: IANIS
      REAL :: RI
      REAL :: XI
      REAL :: YI
      REAL :: ZI
      REAL :: XL
      REAL :: YL
      REAL :: ZL
      REAL :: RL
      REAL :: XNM
      REAL :: XSH
      REAL :: XMOL
      REAL :: XDUM
      CHARACTER(len=3) :: NL123
      CHARACTER(len=2) :: LBPOS
C * MODE = 1 - CALC    MODE
C * MODE = 2 - LABEL   MODE
C * MODE = 3 - UNLABEL MODE
C * MODE = 4 - PUT     MODE
      KL      = IPR(220)
      KN      = IPR(221)
      NAT     = IPR(37)
      ILPB    = IPR(69) + 1
      NATO    = IPR(39)
      NAB     = NAT - IPR(69)
C * SET NO-ERROR STATUS
      IPR(72) = 0
      XSH     = PAR(39)
      IASU    = 0
C * CALC POSITION MODE
      IF (MODE == 1) THEN
C * CHECK FOR 'LOAD LABELS' FLAG
        IF (IGBL(75) == 0) THEN
          IF (IPR(339) == 1) THEN
            NATY = IPR(69)
          ELSE
            NATY = 0
          END IF
        ELSE
          NATY = NAT
        END IF
C * CHECK FOR 'LOAD ARU-LABEL' FLAG
        IF (IPR(63) == 0) THEN
          NATX = NATY
        ELSE
          NATX = NATY + IPR(42)
        END IF
C * TEST FOR LABELS LOADED FOR PLOTTING
        IF (NATX > 0) THEN
          PAR(28) = 0.5 * PAR(349)
C * ENSURE THE USE OF THE SAME LABEL POS. FOR LEFT AND RIGHT STEREO PAIR
          IF (IPR(116) == 1 .OR. IPR(130) == 1) THEN
            NTM = 1
            NT0 = 1
          ELSE
            NTM = 2
C * TEST FOR ANY PUT INSTRUCTIONS ACTIVE
            IF (IPR(117) == 0) THEN
              NT0 = 2
            ELSE
              NT0 = 1
            END IF
          END IF
C * LOOP FIRST OVER PUT INSTRUCTIONS AND THEN OVER AUTO LAB. INSTR.
          DO NT = NT0, NTM
C * LABEL POSITIONS FOLLOW ATOMS ON THE STACK
            NATL = IPR(62)
C * LOOP OVER ALL ATOMS/MOLECULES FOR LABELLING
            IF (NATR /= 0) THEN
              IBEG = NATR
              IEND = NATR
              NATL = IPR(62) + NATR - 1
            ELSE
              IBEG = 1
              IEND = NATX
            END IF
            DO 60 I = IBEG, IEND
              NATL = NATL + 1
              IF (I <= NATY) THEN
C * NO LABELLING OF OVERLAPPED ATOMS
                IF (IPR(4) > 0) THEN
                  CALL PLUT15 (-1, I, 45, IVAL)
                  IF (IVAL == 0 .AND. I >= ILPB) GO TO 60
                END IF
C * TEST FOR LABELLING TYPE ( 0 = NOLABELLING OF THIS ATOM)
                CALL PLUT15 (-4, I, 37, M)
                IF (M == 0)  GO TO 60
C * GET COORDINATES OF PARENT ATOM
                CALL PLUT14 (-1, I, IASU, NPROP, XI, YI, ZI, RI)
                IF (RI < 0.0)  GO TO 60
                IF (IPR(4) <= 0 .AND. RI > 0.0) RI = 0.0
                IF (I < ILPB) THEN
C * LABELLING UNIT CELL CORNERS (TEST)
                  IF (IPR(46) == 0) THEN
                    GO TO 60
                  ELSE
                    NQ0(1:1) = CHAR (INT (RA(I * NP43 + 7)))
                    KLB      = 1
                    GO TO 10
                  END IF
                END IF
C * GET ATOM LABEL IN NQ2
                IAT = I
                IF (I >= ILPB .AND. IPR(14) == 1) IAT = - I
                CALL PLUT25 (2, IAT, IATK)
C * COPY LABEL IN NQ0
                NQ0 = NQ2
                CALL GEN020 (-1, NQ0, 2, 2)
C * ARU LABEL CASE
              ELSE
                M = IABS (IPR(63))
C * GET MOL LABEL
                XNM = IARU(1, I - NATY) / PAR(42)
C * SKIP LABELS FOR EXCLUDED MOLECULES
                IF (XNM < 0)  GO TO 60
                NM = NINT (XNM)
C * GET RESIDUE NUMBER
                NR = NINT ((XNM - NM) * PAR(42))
                CALL GEN040 (NM, NQ0, IP0)
                IP0 = IP0 + 1
                NQ0(IP0:IP0) = '.'
                IF (NR < 10 .AND. IPR(134) > 9) THEN
                  IP0          = IP0 + 1
                  NQ0(IP0:IP0) = '0'
                END IF
                CALL GEN040 (NR, NQ0(IP0 + 1:IP0 + 1), IP)
                IP  = IP0 + IP
C * GET POSITION OF FIRST ATOM IN MOL
                NMLX = IPR(142)
                DO J = 1, NMLX
                  INM = NINT (RA(IPR(159) + 1 - J))
                  IF (NM == INM) EXIT
                END DO
                DO K = ILPB, NATO
                  CALL PLUT15 (-6, K, 5, IVAL)
                  IF (IVAL == NR) THEN
                    CALL PLUT15 (-1, K, 27, IVAL)
                    IF (IVAL == 1) EXIT
                  END IF
                END DO
                K = (J - 1) * NAB + K
                CALL PLUT14 (-1, K, IASU, NPROP, XI, YI, ZI, RI)
              END IF
              NB  = 0
              KLB = 0
              CALL GEN039 (1, NQ0, 1, NP64, NB, KLB)
C * PAR(40) IS THE HALF WIDTH OF THE LABEL IN CM.
   10         PAR(40) = KLB * PAR(349) * PAR(19) / 2.0
              IF (IPR(116) <= 0 .AND. IPR(130) == 0 .AND.
     1            M /= 15) THEN
C * NT = 1 : EXECUTE PUT INSTRUCTIONS
C * NT = 2 : AUTOPOSITIONING CYCLE
                IF (I <= NATY) THEN
                  CALL PLUT15 (-1, I, 42, ILB)
                ELSE
                  IF (IPR(63) < -1) THEN
                    ILB = 1
                  ELSE
                    ILB = 0
                  END IF
                END IF
C * GET DEFAULT LABEL SHIFT
                XSH = PAR(39)
                IF (NT == 1) THEN
C * IS THIS A SPECIFIED LABEL POSITION
                  IF (ILB == 0)  GO TO 60
                  IF (M == 1)  GO TO 60
                  MM = 0
                ELSE
C * AUTO LABELLING
                  IF (ILB == 1)  GO TO 60
                  MMIN = 999
                  M0   = 10
                  XSH0 = 0.0
C * LABEL SHIFT LOOP
                  XSH = 0.0
   20             XSH = XSH + PAR(39)
                  IF (IPR(116) /= 0 .AND. XSH > PAR(39)) GO TO 40
                  IF (XSH > IPR(131) * PAR(39)) GO TO 40
C * EXAMINE LABEL POSITIONS 2 TO 9(10)
                  M = 10 + IPR(18)
C * CHECK WHETHER LABEL WOULD FIT IN ATOM BOUNDERY OUTLINE
                  IF (PAR(40) > RI * 0.9) M = 10
                  IF (I >= ILPB) THEN
                    MSTEP = 1
                  ELSE
                    MSTEP = 2
                    M     = 11
                  END IF
                  DO
                    M = M - MSTEP
                    IF (M < 2) GO TO 20
                    CALL PLUT26 (M, NATL, XI, YI, ZI, RI, XL, YL, ZL,
     1                RL, XSH)
C * TEST FOR LABEL POSITION OUTSIDE PERMITTED PLOT RANGE
                    IF (XL - PAR(40) < PAR(61) .OR.
     1                XL + PAR(40) > PAR(64) .OR.
     2                YL - PAR(28) < PAR(62) .OR.
     3                YL + PAR(28) > PAR(65)) THEN
C * REJECT OUT-OF-BOUNDS LABEL POSITION
                      MM = 999
                      IF (NT == 2) CYCLE
                      IVAL = 1
                      CALL PLUT15 (4, I, 37, IVAL)
                      GO TO 60
                    END IF
                    IPR(67) = 2
                    CALL PLUT18 (NATL, 0)
                    MM = IPR(78)
                    IF (MM == 0) THEN
                      GO TO 50
                    ELSE IF (MM > 0) THEN
                      IF (MM < MMIN) THEN
                        M0   = M
                        XSH0 = XSH
                        MMIN = MM
                      END IF
                    END IF
                  END DO
   40             M = M0
                  IF (IPR(4) > 0 .AND. MMIN > 0
     1              .AND. I <= NATY .AND. I >= ILPB) THEN
                    IVAL = 0
                    CALL PLUT15 (1, I, 45, IVAL)
                    IF (IGBL(105) == 0) GO TO 60
                  END IF
                  XSH = XSH0
                END IF
C * ADD THE COORDINATES FOR THIS LABEL TO THE ATOM LIST
                CALL PLUT26 (M, NATL, XI, YI, ZI, RI, XL, YL, ZL,
     1                       RL, XSH)
   50           IF (I <= NATY) THEN
                  CALL PLUT15 (4, I, 37, M)
                ELSE
                  IF (ILB == 1) THEN
                    IPR(63) = - M
                  ELSE
                    IPR(63) = 1
                  END IF
                END IF
              ELSE
                IF (I <= NATY) THEN
                  CALL PLUT15 (-4, I, 37, M)
                ELSE
                  M = MAX (-IPR(63), 2)
                END IF
                IF (IPR(116) /= 0) THEN
                  XSH =  PAR(39)
                  CALL PLUT26 (M, NATL, XI, YI, ZI, RI, XL, YL, ZL,
     1                         RL, XSH)
                ELSE
                  CALL PLUT14 (-1, NATL, IASU, NPROP, XL, YL, ZL, RL)
                END IF
              END IF
              IF (CC) GO TO 100
C * LABEL PLOT AND RETRACE LOOP
              IF (IPR(477) < 0) THEN
                CALL PLUT15 (-6, I, 5, NRS)
                IF (NRS > 0 .AND. NRS <= 8) THEN
                  ICOL = NCRS(NRS)
                ELSE
                  ICOL = 1
                END IF
                LMAX = 2
              ELSE
                LMAX = IPR(7)
                IF (I > NATY) THEN
                  ICOL = 6
                ELSE
                  ICOL = -1
                  IF (IPR(116) == 0) THEN
C * PLUTON/ANIS
                    IF (IGBL(3) == 26 .OR. IPR(352) == 1) THEN
                      CALL PLUT15 (-1, I, 41, IANIS)
                      IF (IANIS == 1) ICOL = 2
                    END IF
C * PLUTON/RENAME
                    IF (IGBL(3) == 12) THEN
                      CALL PLUT15 (-1, I, 47, IREN)
                      IF (IREN == 1) ICOL = 3
                    END IF
                  END IF
                END IF
              END IF
C * PLOT STRING (RETRACE 'LMAX' TIMES)
              DO L = 1, LMAX
                CALL PLA439 (0.0, NQ0, KLB, PAR(349), ICOL, 1,
     1            XL - PAR(40), YL - PAR(28))
                XL = XL + PAR(4)
              END DO
   60       CONTINUE
          END DO
        END IF
      ELSE
        IF (IPR(17) == 0) THEN
          CALL PLUT05
C * CALL EXIT/STOP
          IF (IPR(72) /= 0) CALL GEN127 ('308')
        END IF
        IF (MODE == 2 .OR. MODE == 3) THEN
C * SET REBUILD
          IPR(130) = 0
C * LABEL SETTING MODE (2)  - SET LABELLING BIT UP
C * LABEL SETTING MODE (3)  - SET LABELLING BIT DOWN
          LABL = 3 - MODE
          IF (KL == 1) THEN
            KL = 2
            IFL(2)(1:3) = 'ON '
          END IF
          IPR(175) = 0
          ISET     = 0
          DO K = 2, KL
            SELECT CASE (IFL(K)(1:3))
C * HANDLE (UN)LABEL ON
              CASE ('ON ')
                IGBL(75) = LABL
                IPR(452) = IGBL(75)
                IPR(175) = 1
                IPR(63)  = 0
                ISET     = 1
C * HANDLE (UN)LABEL OFF
              CASE ('OFF')
                IGBL(75) = 1 - LABL
                IPR(452) = IGBL(75)
                IPR(63)  = 0
                IPR(175) = 1
                ISET     = 1
                LABL     = MOD (LABL + 1, 2)
C * HANDLE (UN)LABEL NONE
              CASE ('NON')
                IPR(63)  = 0
                IPR(175) = 1
                ISET     = 1
                LABL     = MOD (LABL + 1, 2)
C * (UN)LABEL UNITCELL
              CASE ('UNI')
                IPR(175) = 1
C * (UN)LABEL ARU'S
              CASE ('ARU')
                IPR(63) = LABL
C * (UN)LABEL MOLES
              CASE ('MOL')
                IPR(63) = LABL
C * (UN)LABEL ATOMS
              CASE ('ATO')
                IPR(452) = LABL
                IF (LABL == 1) IGBL(75) = LABL
                ISET     = 1
C * (UN)LABEL ALL
              CASE ('ALL')
                IPR(63)  = LABL
                IGBL(75) = LABL
                IPR(175) = 1
                ISET     = 1
C * LABELS WITH PARENTHESES
              CASE ('PAR')
                IPR(71) = 1
C * LABELS WITHOUT PARENTHESES
              CASE ('NOP')
                IPR(71) = 0
C * FULL LABEL
              CASE ('FUL')
                IPR(14) = 0
C * NUMERICAL LABEL PART ONLY FOR H & C
              CASE ('NUM')
                IPR(14) = 1
                IPR(71) = 0
C * HANDLING OF ATOM-TYPES OR ATOM-LABELS (POSSIBLY WITH SYMMETRY CODES)
              CASE DEFAULT
C * GET ATOM-TYPE OR ATOM-NAME (IN THAT ORDER) OF ENTRY-NR K INTO IAT
                CALL PLUT13 (-1, -K, IAT, XMOL)
                IGBL(75) = 1
C * ATOM-TYPE CASE
                IF (IAT < 0) THEN
                  DO I = ILPB, NAT
                    II = I
                    CALL PLUT25 (0, II, IAI)
                    IF (IAI + IAT == 0) THEN
                      IF (KN == 1) CALL PLUT28 (0, II, FN(1))
                      CALL PLUT15 (4, II, 37, LABL)
                    END IF
                  END DO
C * ATOM-NAME CASE
                ELSE IF (IAT > 0) THEN
                  IF (KN == 1) XMOL = FN(1)
                  CALL PLUT28 (0, IAT, XMOL)
                  CALL PLUT15 (4, IAT, 37, LABL)
                END IF
            END SELECT
          END DO
C * EXECUTE GLOBAL (UN)LABEL ATOMS AND UNITCELL CORNERS
          IF (ISET == 1) THEN
            DO I = ILPB, NAT
              IF (LABL == 1) THEN
C * YES/NO INCLUDE H-LABELS
                IF (IPR(232) == 1) THEN
                  LABL0 = 1
                ELSE
                  CALL PLUT15 (-1, I, 44, IHA)
                  LABL0 = 1 - IHA
                END IF
              ELSE
                LABL0 = 0
              END IF
              CALL PLUT15 (4, I, 37, LABL0)
              IF (LABL == 0) THEN
                IVL = 0
                CALL PLUT15 (1, I, 42, IVL)
              END IF
            END DO
          END IF
          IF (IPR(50) == 0 .AND. IPR(175) == 1) THEN
            IPR(339) = LABL
            DO I = 1, 8
              IF (I < 4 .OR. I == 5) THEN
                ILB = LABL
              ELSE
                ILB = 0
              END IF
              CALL PLUT15 (4, I, 37, ILB)
            END DO
          END IF
        ELSE IF (MODE == 4) THEN
C * PUT LABELS WHERE REQUESTED
C * SET REBUILD
          IPR(130) = 0
          L = 2
   70     IF (L > KL)  GO TO 110
          NL123 = IFL(L)(1:3)
C * PUT ARU LABELS
          IF (NL123 == 'ARU') THEN
            LMODE = -1
C * PUT MOLES LABELS
          ELSE IF (NL123 == 'MOL') THEN
            LMODE = -1
C * PUT ATOMS LABELS
          ELSE IF (NL123 == 'ATO') THEN
            IAT   = 0
            LMODE = 1
          ELSE
            CALL PLUT13 (0, -L, IAT, XDUM)
            IF (IAT == 0) THEN
              L = L + 1
              GO TO 90
            END IF
            LMODE = 1
          END IF
          L = L + 1
          IF (L > KL)  GO TO 90
          LBPOS = IFL(L)(1:2)
          DO I = 1, 10
            IF (LABP(I + 1) == LBPOS)  GO TO 80
          END DO
          GO TO 90
   80     IF (LMODE == -1) THEN
            IPR(63) = - MIN (IABS (IPR(63)), 1) * I
          ELSE
            IF (IAT <= 0) THEN
              JB = ILPB
              JE = NAT
            ELSE
              JB = IAT
              JE = IAT
            END IF
            DO J = JB, JE
              CALL PLUT25 (0, J, IAJ)
              IAJ = - IAJ
              CALL PLUT15 (-4, J, 37, ILB)
              ILB = MIN (ILB, 1) * I
              IF (IAT >= 0 .OR. IAT == IAJ) THEN
                CALL PLUT15 (4, J, 37, ILB)
                IF (ILB > 1) THEN
                  LFIX = 1
                ELSE
                  LFIX = 0
                END IF
                CALL PLUT15 (1, J, 42, LFIX)
              END IF
            END DO
          END IF
          L = L + 1
          IPR(117) = 1
          GO TO 70
   90     IPR(72) = 26
        END IF
      END IF
  100 IF (MODE > 1) THEN
        IF (IPR(63) /= 0) THEN
          ILBO = 1
        ELSE
          ILBO = 0
        END IF
        DO I = 1, NAT
          CALL PLUT15 (-4, I, 37, IVAL)
          IF (IVAL > 0) ILBO = 1
          IF (ILBO /= 0) GO TO 110
        END DO
      END IF
  110 IF (MODE == 2 .OR. MODE == 3) THEN
        IF (IPR(63) + IPR(339) + IGBL(75) == 0) THEN
          IGBL(75) = 0
        ELSE
          IGBL(75) = 1
        END IF
      END IF
      RETURN
      END SUBROUTINE PLUT04
 
      SUBROUTINE PLUT05
C * THIS ROUTINE HANDLES ALL JOIN/DETACH INSTRUCTIONS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: KB
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: M13
      INTEGER :: KL0
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: IVL
      INTEGER :: IAIO
      INTEGER :: JAIO
      INTEGER :: IVAL
      INTEGER :: IDASH
      INTEGER :: IDUM0
      INTEGER :: IDUM2
      INTEGER :: MADDR
      REAL :: XMOL
      REAL :: XDUM
      REAL :: DUM1
      CHARACTER(len=5) :: J15
C * IPR(17) = 0 : AUTOMATIC JOIN RADII (UNIQUE) INSTRUCTION
C * IPR(17) = 1 : NORMAL    JOIN                INSTRUCTION
C * IPR(17) =-1 : DETACH                        INSTRUCTION
C * SET REBUILD
      IDASH    = 0
      IPR(130) = 0
      KL       = IPR(220)
      KN       = IPR(221)
      PAR(1)   = PAR(2) / 2
C * SET POINTERS AND LOAD UNITCELL BONDS
      IF (IPR(100) == 0) CALL PLUT33
      IPR(72) = 0
C * TEST FOR AUTOMATIC JOIN RADII UNIQUE
      IF (IPR(17) == 0) THEN
        IDASH    = 0
C * DEFAULT INTRA RADII SETTING
        IPR(35)  = 1 - IPR(50)
C * SET AUTO RADII BIT
        IPR(60)  = 1
C * SET EXPAND BIT
        IPR(110) = (1 - IPR(50)) * IGBL(97)
C * SET NOMOVE BIT FOR DISORDERED STRUCTURES
        IF (IPR(9) > 1 .AND. IPR(127) == 0) THEN
          IGBL(30) = 1
          WRITE (LU6, 99999, IOSTAT = IOST)
        END IF
      ELSE
        IF (KL <= 1) GO TO 30
C * JOIN RADII (..)
        IF (IFL(2)(1:5) == 'RADII') THEN
C * RADII GIVEN FOR DISTANCE SCAN
          IPR(35) = 0
          IPR(60) = 1
          N       = 0
          DO I = 1, NP10
             RADR(I, 2) = -1
          END DO
          IF (KL > 2) THEN
C * SET NOMOVE DEFAULT TO (FRACTIONAL = 0/ANGSTROM = 1)
            IGBL(30) = IPR(50)
            DO K = 3, KL
               J15 = IFL(K)(1:5)
C * NOMOVE OPTION
               IF (J15 == 'NOMOV') THEN
                  IGBL(30) = 1
C * JOIN RADII UNIQUE
               ELSE IF (J15 == 'UNIQU') THEN
C * SET UNIQUE-FLAG UP
                  IPR(35)  = 1 - IPR(50)
                  IPR(110) = 0
C * JOIN RADII INTER
               ELSE IF (J15 == 'INTER') THEN
C * SET INTER-FLAG UP
                 IPR(35) = - 1
C * TOL & TOLE
               ELSE IF (J15(1:3) == 'TOL') THEN
C * CHANGE AUTOMATIC RADII TOLERANCE SETTING
                 N = N + 1
                 IF (N <= KN) THEN
                   IF (J15(4:4) == 'E') THEN
                     PAR(26) = FN(N)
                   ELSE
                     PAR(1) = FN(N)
                   END IF
                   WRITE (LU6, 99998, IOSTAT = IOST)
     1               PAR(1), IGBL(97) * PAR(26)
                 END IF
C * JOIN RADII (UNIQUE/INTER HBONDS) EXPAND
               ELSE IF (J15 == 'EXPAN') THEN
                 IPR(110) = 1
C * JOIN RADII INTER HBONDS
               ELSE IF (J15 == 'HBOND') THEN
                IPR(109) = 1
C * JOIN RADII INTER XBONDS
               ELSE IF (J15 == 'XBOND') THEN
                IPR(109) = 2
               ELSE
C * TEST FOR ATOM TYPE
                 CALL PLUT13 (0, -K, IAT, XDUM)
                 IF (IAT >= 0) GO TO 30
C * TYPE OF ATOM LIST.  THIS IS USED TO SET ATOM RADII FOR SCAN
                 M          = - IAT
                 N          = N + 1
                 RADR(M, 2) = FN(N)
C * DISABLE AUTOMATIC RADII SETTING
                 IPR(60)    = 0
               END IF
            END DO
            IPR(221) = 0
            KN       = IPR(221)
          END IF
C * JOIN INTRA
        ELSE IF (IFL(2)(1:5) == 'INTRA') THEN
          IPR(37) = IPR(38)
          IPR(52) = IPR(53)
          GO TO 40
        ELSE
C * JOIN/DETACH
          IDASH = 0
          IF (IFL(2)(1:4) == 'DASH' .AND. KL == 4) THEN
            IDASH    = 1
            IFL(2)   = IFL(3)
            IFL(3)   = IFL(4)
            KL       = 3
            IPR(220) = KL
          END IF
          IF (KL < 3) GO TO 30
          IF (IPR(52) == (1 - IPR(50)) * 12) THEN
            IPR(75) = 1
            CALL PLUT17 (0, 1555.0 + 1 / PAR(42), MADDR, LU6)
            WRITE (LU6, 99997, IOSTAT = IOST)
C * DO CARTESIAN COORDINATE CALCULATION
            DO I = 1, IPR(37)
              CALL PLUT23 (I)
            END DO
          END IF
C * CHECK FOR DEFINE
          IF (IPR(161) < 0) THEN
            KB = 3
          ELSE
            KB = 2
          END IF
C * SPECIFIC ATOM CONNECTIONS/ OR SEQUENCES
   10     CALL PLUT13 (0, - KB, IAT, XDUM)
C * 'TO' KEYWORD
          IF (IPR(161) == 1) THEN
            KL0 = 4
          ELSE
            KL0 = KB + 1
          END IF
          IF (IAT == 0 .OR. KL < KL0) GO TO 30
          DO K = KL0, KL
            IF (IAT > 0) THEN
              I1 = IAT
              I2 = IAT
            ELSE
              I1 = IPR(69) + 1
              I2 = IPR(37)
            END IF
            IF (KN == 1) THEN
              M13 = -1
            ELSE
              M13 = 0
            END IF
            CALL PLUT13 (M13, -K, JAT, XMOL)
            IF (JAT == 0) THEN
              GO TO 30
            ELSE IF (JAT > 0) THEN
              IF (IAT > 0 .AND. KL == 3) THEN
                IF (KN == 1) XMOL = FN(1)
                CALL PLUT28 (IAT, JAT, XMOL)
                IFL(K) = NQ1
              END IF
              J1 = JAT
              J2 = JAT
            ELSE
              J1 = IPR(69) + 1
              J2 = IPR(37)
            END IF
            DO I = I1, I2
              IAIO =  - INT (RA(I * NP43 + 7) / 64000) - 1
              IF (IAT >= 0 .OR. IAT == IAIO) THEN
                DO J = J1, J2
                  JAIO = - INT (RA(J * NP43 + 7) / 64000) - 1
                  IF (JAT >= 0 .OR. JAT == JAIO) THEN
                    CALL PLUT16 (IPR(17) - 2, IDUM0, I, J, DUM1, IDUM2)
                    IF (IPR(17) == 1) THEN
                      CALL PLUT15 (-4, I, 33, IVAL)
                      IF (IVAL < NP33) THEN
                        IVL = IVAL + 1
                        CALL PLUT15 (4, I, 33, IVL)
                      END IF
                      CALL PLUT15 (-4, J, 33, IVAL)
                      IF (IVAL < NP33) THEN
                        IVL = IVAL + 1
                        CALL PLUT15 (4, J, 33, IVL)
                      END IF
                    END IF
                  END IF
                END DO
              END IF
            END DO
          END DO
C * CHECK FOR DEFINE
          IF (IPR(161) < 0) THEN
            KB = KB + 1
            IF (KB < KL) GO TO 10
          END IF
          GO TO 40
        END IF
      END IF
C * LOAD INTRA/INTER RADII FROM STANDARD TABLE
      IF (IPR(60) /= 0) THEN
        DO I = 1, IAN
          RADR(I, 2) = RADR(I, 3) + PAR(1)
          IF (IPR(35) < 0) THEN
            RADR(I, 2) = RADR(I, 4)
C * HBONDS/XBONDS
            IF (IPR(109) > 0) THEN
              DO N = 1, IPR(480)
                IF (IEN(I) == IDOAC(N)) THEN
                  RADR(I, 2) = RADR(I, 4)
                  GO TO 20
                END IF
              END DO
C * TEST FOR H AND D ATOMS
              IF (MOD (IEN(I), 32) == 1) THEN
                RADR(1, 2) = VDWR(1)
              ELSE
                RADR(I, 2) = 0.0
              END IF
   20         CONTINUE
            END IF
          END IF
        END DO
      END IF
C * EXECUTE JOIN INSTRUCTION
      CALL PLUT07
      GO TO 40
   30 IPR(72) = 27
      WRITE (LU6, 99996, IOSTAT = IOST)
      CALL PLA015 (0, 48)
   40 IF ((IDASH == 1 .OR. IPR(221) > 0) .AND. IPR(4) /= 0) THEN
        IF (IDASH == 1) THEN
          IFL(5)   = IFL(3)
          IFL(4)   = IFL(2)
          IFL(3)   = 'DASH '
          IPR(220) = 5
          IF (IPR(221) < 2) THEN
            FN(1) = 0.02
            FN(2) = 5
            IPR(221) = 2
          END IF
        ELSE
          IFL(4)  = IFL(3)
          IFL(3)  = IFL(2)
          IPR(220) = 4
        END IF
        IFL(2) = 'BONDS'
        CALL PLUT21 (0)
        IPR(220) = 5
        IDASH    = 0
      END IF
      IPR(17) = 1
      RETURN
99999 FORMAT (':: Automatic NOMOVE set because of (partial) disorder')
99998 FORMAT (':: Current JOIN RADII INTRA   TOL /ATOM=', F5.2,' Ang.',/
     1       ,'    +(EARTH)ALKALI-NON-METAL) TOLE/BOND=', F5.2,' Ang.')
99997 FORMAT (':: User-Supplied Bonds only mode')
99996 FORMAT (':: Problem/Error in JOIN - routine')
      END SUBROUTINE PLUT05
 
      SUBROUTINE PLUT06
C * THIS ROUTINE HANDLES THE VARIOUS VIEWPOINT INSTRUCTIONS
      USE files
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: J3
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: KLS
      INTEGER :: KNS
      INTEGER :: IDET
      INTEGER :: ILINE
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      REAL :: CA
      REAL :: CB
      REAL :: SA
      REAL :: PHI
      REAL :: ANG
      REAL :: XDUM
      REAL :: XLNG
      REAL :: TEMP
      REAL :: GEN017
      REAL, DIMENSION(3, 3) :: RSAVE
      REAL, DIMENSION(3, 3) :: YUNK
      CHARACTER(len=6) :: INVERT
      CHARACTER(len=2) :: N12
      CHARACTER(len=1) :: N1
C * SET REBUILD
      IPR(130) = 0
      IPR(150) = 0
      KL       = IPR(220)
      KN       = IPR(221)
C * TEST FOR PREVIOUS JOIN INSTRUCTION EXECUTED, OTHERWISE DO SO
      IF (IPR(17) == 0) THEN
        KNS      = KN
        KLS      = KL
        IPR(221) = 0
        IPR(220) = 1
        CALL PLUT05
C * CALL EXIT/STOP
        IF (IPR(72) /= 0) CALL GEN127 ('309')
        IPR(221) = KNS
        KN       = IPR(221)
        IPR(220) = KLS
        KL       = IPR(220)
      END IF
C * SAVE R IN RSAVE AND RESTORES R IN CASE OF ERROR
      CALL GEN052 (R, RSAVE)
      IF (IPR(51) == 0 .OR. IPR(37) == 0) THEN
        WRITE (LU6, 99994, IOSTAT = IOST)
        GO TO 70
      END IF
      IPR(72)  = 0
      N        = 0
      L        = 2
      IGBL(67) = 1
      IF (KL == 1) THEN
        IPR(220) = 2
        KL       = IPR(220)
        IF (IFL(1)(1:1) == 'V') THEN
C * SET VIEW UNIT
          IFL(2)(1:4) = 'UNIT'
        ELSE
C * XROT, YROT OR ZROT
          IFL(2) = IFL(1)
        END IF
      END IF
      N12 = IFL(L)(1:2)
C * VIEW XR xr YR yr ZR zr INTERPRETED AS VIEW CUR XR xr YR yr ZR zr
C * VIEW INVERT interpreted as VIEW CUR INVERT
      IF (N12 == 'IN' .OR. N12 == 'XR' .OR. N12 == 'YR' .OR.
     1    N12 == 'ZR') THEN
         L = 1
         GO TO 40
      END IF
C * VIEW ALIGN
      IF (N12 == 'AL') THEN
        IF (KL /= 6)  GO TO 70
C * WITH
        IF (IFL(5)(1:1) /= 'W')  GO TO 70
C * XP
        IF (IFL(6)(1:1) == 'X') THEN
          ANG = 0.0
C * YP
        ELSE IF (IFL(6)(1:1) == 'Y') THEN
          ANG = -90.0
        ELSE
          GO TO 70
        END IF
C * GET ATOM NAME NUMBER
        CALL PLUT13 (0, 3, IAT, XDUM)
        CALL PLUT13 (0, 4, JAT, XDUM)
C * TEST FOR NON-VALID ATOM LABELS
        IF (IAT <= 0 .OR. JAT <= 0)  GO TO 70
        IF (KN == 1 .AND. KL == 6) CALL PLUT28 (IAT, JAT, FN(1))
        DO I = 1, 2
          ZU(I + 9)  = 0.0
          ZU(I + 12) = 0.0
          DO J = 4, 6
            ZU(I + 9)  = R(I, J - 3) * RA(IAT * NP43 + J) + ZU(I + 9)
            ZU(I + 12) = R(I, J - 3) * RA(JAT * NP43 + J) + ZU(I + 12)
          END DO
          ZU(I) = ZU(I + 12) - ZU(I + 9)
        END DO
        IF (ABS (ZU(1)) + ABS (ZU(2)) <= 1.0) THEN
          WRITE (LU6, 99998, IOSTAT = IOST)
          RETURN
        END IF
        ANG         = ATAN2(ZU(2), ZU(1)) * RGBL(6) + ANG
        N           = 0
        L           = 0
        IPR(220)    = 1
        KL          = IPR(220)
        IPR(221)    = 1
        KN          = IPR(221)
C * GENERATE A VIEW ZROT INSTRUCTION
        FN(1)       = ANG
        IFL(1)(1:1) = 'Z'
        IGBL(67)    = 1
C * VIEW MATRIX CARD
      ELSE IF (N12 == 'MA') THEN
        IF (KN < 9) THEN
          WRITE (LU6, 99991, IOSTAT = IOST)
          GO TO 70
        END IF
        K = 0
        DO I = 1, 3
          DO J = 1, 3
            K = K + 1
            R(I, J) = FN(K)
          END DO
        END DO
        N = 9
C * VIEW MIN - FIND MINIMUM OVERLAP MATRIX
      ELSE IF (N12 == 'MI') THEN
        CALL PLUT08
        L        = 2
        IPR(150) = 2
C * VIEW XO
      ELSE IF (N12 == 'XO') THEN
        CALL GEN021 (R, 0.0)
        R(1, 2) = 1.0
        R(2, 3) = 1.0
        R(3, 1) = 1.0
        IPR(150) = 3
C * VIEW YO
      ELSE IF (N12 == 'YO') THEN
        CALL GEN021 (R, 0.0)
        R(1, 3) = 1.0
        R(2, 1) = 1.0
        R(3, 2) = 1.0
        IPR(150) = 4
C * VIEW ZO OR UNIT
      ELSE IF (N12 == 'ZO' .OR. N12 == 'UN') THEN
        CALL GEN021 (R, 1.0)
        IF (N12 == 'ZO') THEN
          IPR(150) = 5
        ELSE
          IPR(150) = 1
        END IF
C * VIEW CURRENT
      ELSE IF (N12 == 'CU') THEN
        GO TO 40
      ELSE
C * SUB-KEYWORDS DEFINING A ROTATION MATRIX TO BE CALCULATED
C * AFACE, BFACE, CFACE, DIRECTION, LINE, PERP, BISECT
        CALL GEN021 (R, 0.0)
        CALL GEN074 (RA, 1, 3, 0.5)
C * XFACE CARD
        IF (N12(2:2) == 'F') THEN
          IF (N12(1:1) == 'B') THEN
            J = 2
          ELSE IF (N12(1:1) == 'C') THEN
            J = 3
          ELSE
            J = 1
          END IF
          IPR(150) = 5 + J
          ILINE = 1
          RA(J) = 1.0
          GO TO 10
        END IF
C * VIEW DIRECTION
        IF (N12 == 'DI') THEN
          IF (KN < 3) THEN
            WRITE (LU6, 99987, IOSTAT = IOST)
            GO TO 70
          END IF
          DO K = 1, 3
            RA(K) = FN(K)
          END DO
          ILINE = 1
          L     = 2
          N     = 3
          GO TO 10
        END IF
C * VIEW LINE
        IF (N12 == 'LI') THEN
          ILINE = 1
          IF (KL < 4) THEN
            WRITE (LU6, 99992, IOSTAT = IOST)
            GO TO 70
          END IF
          CALL PLUT13 (0, 3, IAT, XDUM)
          CALL PLUT13 (0, 4, JAT, XDUM)
          IF (IAT <= 0 .OR. JAT <= 0) THEN
            WRITE (LU6, 99993, IOSTAT = IOST)
            GO TO 70
          END IF
          IF (KN == 1 .AND. KL == 4) CALL PLUT28 (IAT, JAT, FN(1))
          DO K = 1, 3
            RA(K) = RA(IAT * NP43 + K) - RA(JAT * NP43 + K)
          END DO
          L = L + 2
          GO TO 10
        END IF
C * VIEW PERP
        IF (N12 == 'PE') THEN
          ILINE = 2
          GO TO 20
        END IF
C * VIEW BISECT
        IF (N12 == 'BI') THEN
          ILINE = 3
          GO TO 20
        END IF
        WRITE (LU6, 99986, IOSTAT = IOST)
         GO TO 70
   10   CALL PLUT23 (0)
C * CALC R MATRIX FOR LINE VIEW
        XDUM = GEN017 (RA(4))
        DO K = 7, 9
C * NEW Z PARALLEL TO VIEW DIRECTION (ZU 7,8,9)
          ZU(K)     = RA(K - 3)
          ZU(K + 6) = 0.0
        END DO
        IF (ABS(ZU(8)) > 0.9999) THEN
          ZU(13) = 1.0
        ELSE
          ZU(14) = 1.0
        END IF
C * DEFINE NEW X (ZU 1,2,3) AND Y (ZU 4,5,6) AXES
        CALL GEN008 (ZU(13), ZU(7), ZU(1), 1)
        CALL GEN008 (ZU(7), ZU(1), ZU(4), 1)
        GO TO 30
C * VIEW BISECT/PERP
   20   IF (KL < 5) THEN
          WRITE (LU6, 99989, IOSTAT = IOST)
          GO TO 70
        END IF
        CALL PLUT13 (0, 3, J1, XDUM)
        CALL PLUT13 (0, 4, J2, XDUM)
        CALL PLUT13 (0, 5, J3, XDUM)
        IF (J1 <= 0 .OR. J2 <= 0 .OR. J3 <= 0) THEN
          WRITE (LU6, 99988, IOSTAT = IOST)
          GO TO 70
        END IF
        L = L + 3
C * CALC R MATRIX FOR PERP AND BISECT VIEWS
        DO K = 1, 3
          M = K + 3
          ZU(K + 6)  = 0.5 * (RA(J1 * NP43 + M)
     1               + RA(J3 * NP43 + M)) - RA(J2 * NP43 + M)
          ZU(K + 9)  = RA(J1 * NP43 + M)  - RA(J2 * NP43 + M)
          ZU(K + 12) = RA(J3 * NP43 + M)  - RA(J2 * NP43 + M)
        END DO
        XDUM = GEN017 (ZU(7))
        XDUM = GEN017 (ZU(10))
        XDUM = GEN017 (ZU(13))
C * NOW GET V2 = V3 X R2  AND THEN V1 = V2 X V3
        CALL GEN008 (ZU(7), ZU(13), ZU(4), 1)
        CALL GEN008 (ZU(4), ZU(7), ZU(1), 1)
        IF (ILINE /= 3) THEN
C * FOR PERP  JUST SWAP AXES
          DO K = 1, 3
            TEMP      = ZU(K + 6)
            ZU(K + 6) = ZU(K + 3)
            ZU(K + 3) = ZU(K)
            ZU(K)     = TEMP
          END DO
        END IF
C * SET R MATRIX
   30   DO I = 1, 9
          J = (I - 1) / 3
          K = I - J * 3
          R(J + 1, K) = ZU(I)
        END DO
      END IF
C * KEYWORDS GIVING ROTATIONS TO BE APPLIED TO THE CURRENT R MATRIX
   40 L = L + 1
      IF (L > KL)  GO TO 60
      N1 = IFL(L)(1:1)
C * VIEW INVERT - INVERT IMAGE
      IF (N1 == 'I') THEN
        CALL GEN010 (R, -1, -1)
        GO TO 40
      END IF
      N = N + 1
      IF (N > KN) THEN
        WRITE (LU6, 99985, IOSTAT = IOST)
        GO TO 70
      END IF
      CALL GEN021 (A, 1.0)
      ANG = FN(N) / RGBL(6)
      CA  = COS (ANG)
      SA  = SIN (ANG)
      IF (N1 == 'B') THEN
C * BOND ROTN
        IF ((L + 2) > KL) THEN
          WRITE (LU6, 99985, IOSTAT = IOST)
          GO TO 70
        END IF
        L = L + 1
        CALL PLUT13 (0, L, I, XDUM)
        L = L + 1
        CALL PLUT13 (0, L, J, XDUM)
        IF (I <= 0 .OR. J <= 0) THEN
          WRITE (LU6, 99988, IOSTAT = IOST)
          GO TO 70
        END IF
        DO K = 1, 3
          RA(K) = RA(I * NP43 + K) - RA(J * NP43 + K)
        END DO
        CALL PLUT23 (0)
        XDUM = GEN017 (RA(4))
        CALL GEN002 (1, R, RA(4), RA(1), XLNG)
        GO TO 50
      ELSE IF (N1 == 'L') THEN
C * LINE ROTN
        IF ((N + 3) > KN)  GO TO 70
        DO I = 1, 3
          N = N + 1
          RA(I) = FN(N)
        END DO
        CALL PLUT23 (0)
        XDUM = GEN017 (RA(4))
        CALL GEN002 (1, R, RA(4), RA(1), XLNG)
        GO TO 50
      ELSE IF (N1 == 'O') THEN
C * ORTHOLINE ROTN
        IF ((N + 3) > KN)  GO TO 70
        DO I = 1, 3
          N = N + 1
          ZU(I + 6) = FN(N)
        END DO
        XDUM = GEN017 (RA(4))
        CALL GEN002 (1, R, RA(4), RA(1), XLNG)
        GO TO 50
      ELSE IF (N1 == 'P') THEN
C * PROT
        IF ((N + 3) > KN)  GO TO 70
        DO I = 1, 3
          N = N + 1
          ZU(I + 3) = FN(N)
        END DO
        XDUM = GEN017 (ZU(4))
         GO TO 50
      ELSE IF (N1 == 'X') THEN
C * X ROTN
        CALL GEN043 (1, A, ANG)
        CALL GEN004 (A, R, YUNK)
        CALL GEN052 (YUNK, R)
        GO TO 40
      ELSE IF (N1 == 'Y') THEN
C * Y ROTN
        CALL GEN043 (2, A, ANG)
        CALL GEN004 (A, R, YUNK)
        CALL GEN052 (YUNK, R)
        GO TO 40
      ELSE IF (N1 == 'Z') THEN
C * Z ROTN
        CALL GEN043 (3, A, ANG)
        CALL GEN004 (A, R, YUNK)
        CALL GEN052 (YUNK, R)
        GO TO 40
      END IF
      GO TO 70
   50 CB = 1.0 - CA
      DO I = 1, 3
        DO J = 1, 3
          A(I, J) = CB * RA(I) * RA(J)
        END DO
      END DO
      A(1, 1) = A(1, 1) + CA
      A(1, 2) = A(1, 2) + RA(3) * SA
      A(1, 3) = A(1, 3) - RA(2) * SA
      A(2, 1) = A(2, 1) - RA(3) * SA
      A(2, 2) = A(2, 2) + CA
      A(2, 3) = A(2, 3) + RA(1) * SA
      A(3, 1) = A(3, 1) + RA(2) * SA
      A(3, 2) = A(3, 2) - RA(1) * SA
      A(3, 3) = A(3, 3) + CA
      CALL GEN004 (A, R, YUNK)
      CALL GEN052 (YUNK, R)
      GO TO 40
   60 CALL GEN096 (R, IROTX, IROTY, IROTZ, IDET, XYZOR, PHI, ROM)
      RGBL(28) = IROTX
      RGBL(29) = IROTY
      RGBL(30) = IROTZ
      IGBL(87) = IDET
      INVERT   = ' '
C * TEST DETERMINANT = +/-1.0000
      IF (IDET == 0) THEN
        WRITE (LU6, 99997, IOSTAT = IOST)
     1    ((R(I, J), J = 1, 3), I = 1, 3)
        GO TO 70
      ELSE IF (IDET < 0) THEN
        WRITE (LU6, 99999, IOSTAT = IOST)
        INVERT = 'INVERT'
      END IF
      IPR(330) = (1 - IDET) / 2
      WRITE (LU6, 99996, IOSTAT = IOST) IROTX, IROTY, IROTZ, INVERT
      WRITE (LU6, 99995, IOSTAT = IOST) (XYZOR(I), I = 1, 3), PHI,
     1  INVERT
      RETURN
C * ERROR HANDLING
   70 IPR(72) = 28
      WRITE (LU6, 99984, IOSTAT = IOST)
C * COPY MATRIX
      CALL GEN052 (RSAVE, R)
      WRITE (LU6, 99990, IOSTAT = IOST)
      RETURN
99999 FORMAT (':: Absolute Configuration changed !!')
99998 FORMAT (':: ATOMS superimposed in this VIEW: VIEW MATRIX ',
     1        'NOT changed')
99997 FORMAT (/, ':: Abs(Determinant) /= 1.00', //, 10X, 'Matrix', /,
     1               3(3F10.5,/))
99996 FORMAT (/, ':: ORIENTATION     : VIEW UNIT XROT', I5,
     1                            ' YROT', I5, ' ZROT', I5, 2X, A)
99995 FORMAT (':: Equivalent with : VIEW DIR', 3F9.4, ' ZROT',
     1         F7.1, 2X, A)
99994 FORMAT (':: VIEW instruction NOT ALLOWED before',
     1        ' ATOM, CELL or ANGSTROM card')
99993 FORMAT (':: One or both ATOMS unacceptable')
99992 FORMAT (':: Less than 2 ATOMS specified')
99991 FORMAT (':: Less than 9 numbers on MATRIX card')
99990 FORMAT (':: Old VIEW Matrix retained')
99989 FORMAT (':: Less than 3 ATOMS specified')
99988 FORMAT (':: One or more ATOM LABELS unacceptable')
99987 FORMAT (':: Too few direction vector components')
99986 FORMAT (':: VIEW instruction not recognized')
99985 FORMAT (':: Inadequate rotation data')
99984 FORMAT (':: Error in VIEW routine')
      END SUBROUTINE PLUT06
 
      SUBROUTINE PLUT07
C * AUTOMATIC SEARCH FOR CONNECTIONS
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M3
      INTEGER :: M4
      INTEGER :: L1
      INTEGER :: II
      INTEGER :: JJ
      INTEGER :: IL
      INTEGER :: I0
      INTEGER :: IT
      INTEGER :: MI
      INTEGER :: MJ
      INTEGER :: MK
      INTEGER :: NT
      INTEGER :: IL0
      INTEGER :: IL1
      INTEGER :: IL2
      INTEGER :: ICG
      INTEGER :: ID0
      INTEGER :: ID1
      INTEGER :: ISW
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: IVL
      INTEGER :: KAT
      INTEGER :: MR1
      INTEGER :: MR2
      INTEGER :: MR4
      INTEGER :: MS1
      INTEGER :: MS2
      INTEGER :: MS3
      INTEGER :: MS4
      INTEGER :: MT4
      INTEGER :: MPM
      INTEGER :: NEW
      INTEGER :: NRI
      INTEGER :: NRJ
      INTEGER :: NSYM
      INTEGER :: MT11
      INTEGER :: MT13
      INTEGER :: MT14
      INTEGER :: MT21
      INTEGER :: MT23
      INTEGER :: MT24
      INTEGER :: MT31
      INTEGER :: MT33
      INTEGER :: MT34
      INTEGER :: NEXT
      INTEGER :: NATC
      INTEGER :: NARU
      INTEGER :: NML0
      INTEGER :: NATO
      INTEGER :: NELI
      INTEGER :: NELJ
      INTEGER :: MOLY
      INTEGER :: MOLZ
      INTEGER :: JDIS
      INTEGER :: IVAL
      INTEGER :: ITST
      INTEGER :: IDIS
      INTEGER :: IDUM
      INTEGER :: IHAT
      INTEGER :: ILPB
      INTEGER :: INXT
      INTEGER :: JDUM
      INTEGER :: JHAT
      INTEGER :: JUNK
      INTEGER :: NRBO
      INTEGER :: NBOND
      INTEGER :: NRESM
      INTEGER :: NRESI
      INTEGER :: NRESJ
      INTEGER :: NMULT
      INTEGER :: MTYPE
      INTEGER :: NTRNS
      INTEGER :: MADDR
      INTEGER :: KSHFT
      INTEGER :: JJRES
      INTEGER :: JDOAC
      INTEGER :: IVAL1
      INTEGER :: IVAL2
      INTEGER :: IPART
      INTEGER :: IDUM0
      INTEGER :: IDUM2
      INTEGER :: I0RES
      INTEGER :: INFIN
      INTEGER :: JPART
      INTEGER :: IATPRI
      INTEGER :: IATPRJ
      INTEGER :: IATPRX
      INTEGER :: ILSTRT
      REAL :: XM1
      REAL :: XM2
      REAL :: XM3
      REAL :: XM4
      REAL :: YM1
      REAL :: YM2
      REAL :: YM3
      REAL :: DIJ
      REAL :: YUNK
      REAL :: YRES
      REAL :: YMM1
      REAL :: XMOL
      REAL :: DUM1
      REAL :: DUM4
      REAL :: DUM5
      REAL :: DMAX
      REAL :: XTRNS
      REAL :: DIJSQ
      REAL :: DMAXSQ
      REAL :: GEN009
      REAL :: PLA395
      ILSTRT = 0
      IT     = 0
C * JOIN RADII UNIQUE  IPR(35) =  1
C * JOIN RADII         IPR(35) =  0
C * JOIN RADII INTER   IPR(35) = -1
      IDUM0 = 0
      IDUM2 = 0
      DUM1  = 0.0
      DO I = 1, 192
        DO J = 1, 3
          XTT(I, J) = 0.0
        END DO
      END DO
      NATO  = IPR(39)
      NSYM  = IPR(48)
      ILPB  = IPR(69) + 1
      NRESM = IPR(134)
      KSHFT = 0
      IF (IPR(35) >= 0) THEN
C * JOIN RADII UNIQUE
        IF (IPR(35) == 1) THEN
          KSHFT = 1
          IF (IPR(110) == 1) THEN
            WRITE (LU6, 99998, IOSTAT = IOST)
          ELSE
            WRITE (LU6, 99993, IOSTAT = IOST)
          END IF
          WRITE (LU22, 99991, IOSTAT = IOST)
C * JOIN RADII
        ELSE
          WRITE (LU6, 99996, IOSTAT = IOST)
C * FULL RESET NUMBER OF BONDS
          IPR(52) = IPR(68)
          IPR(53) = IPR(68)
        END IF
        CALL GEN074 (RCG, 1, NP32 * 4, 0.0)
        IPR(38) = NATO
        IPR(42) = 0
        IPR(43) = 0
        IPR(44) = 0
        IPR(70) = 0
C * SET CONNECTIVITY SEARCH DEFAULTS (NO)-MOVE
C * CONTENTS OF FLAG ARRAY, IDONE = BIT 1, INEXT = BIT 2
        IVAL = MAX (0, IGBL(30) * 4)
        DO I = ILPB, NATO
          IF (IVAL > 0) RA(I * NP43 + 12) = 1.555
          CALL PLUT15 (4, I, 1, IVAL)
C * ORTHOGONALIZE FOR ANGSTROM COORDINATES INPUT
          IF (IPR(50) == 1) CALL PLUT23 (I)
        END DO
        ILSTRT = ILPB
      ELSE
C * JOIN RADII INTER MODE, RESET NUMBER OF BONDS TO UNIQUE
        IPR(52) = IPR(53)
        KSHFT   = 1 - IPR(50)
        I       = ILPB - 1
      END IF
      IPR(37) = IPR(38)
C * SET TO NO-ERROR
      IPR(72)  = 0
C * SET REBUILD
      IPR(130) = 0
      IPR(55)  = 0
      GO TO 160
C * HEADER OF LOOP ON ATOM I:
C * SEQUENTIAL FOR INTER, PROBLEM DEPENDENT SEQUENCE FOR INTRA(UNIQUE)
   10 DO L = 1, 3
        XYZOR(IPR(120 + L)) = RA(I * NP43 + L)
      END DO
C * GET DISORDER PARAMETER ATOM I
      CALL PLUT15 (-4, I, 28, IDIS)
      IDIS   = IPPR(IDIS + 1, 1)
      CALL PLUT15 (-5, I, 48, IPART)
      IPART  = IPART - 16
C * GET ELEMENT RELATED DATA FOR ATOM I
      NRI    = INT (RA(I * NP43 + 7) / 64000) + 1
      NELI   = IEN(NRI)
      IATPRX = IATPR(NELI)
C * TEST FOR ALKALI OR ALKALI-EARTH
      IF (IATPRX == 5 .OR. IATPRX == 6) THEN
        IATPRI = 1
C * TEST FOR NON-METAL
      ELSE IF (IATPRX < 0) THEN
        IATPRI = -1
      ELSE
        IATPRI = 0
      END IF
C * TEST FOR INTRA-CONNECT ORDER
      NEXT = 0
      CALL PLUT15 (-6, I, 5, NRESI)
C * GET H-ATOM IDENTIFICATION
      CALL PLUT15 (-1, I, 44, IHAT)
      IF (IPR(35) < 0) THEN
        IF (IPR(109) > 0) THEN
C * NO P-ACCEPTOR
          IF (NELI == 8) GO TO 160
C * NO CU-ACCEPTOR
          IF (NELI == 10) GO TO 160
C * AVOID O-COORDINATE N=4,S=6 AS DO/AC
          IF (NELI == 4 .OR. NELI == 6) THEN
            CALL PLUT15 (-1, I, 46, IVAL)
            IF (IVAL == 0) GO TO 160
          END IF
        END IF
      ELSE
C * AVOID LOOP ON H-ATOM
        IF (IPR(50) == 0) THEN
          IF (IHAT == 1) THEN
            J    = NATO
            NEXT = 0
            GO TO 150
          END IF
        END IF
      END IF
C * HEADER OF LOOP ON ATOMS J
      J = ILPB
      IF (IPR(50) == 1 .AND. IPR(35) >= 0) J = ILSTRT
C * SHORTCUT FOR INTER/ANGSTROM CASE
   20 IF (IPR(35) >= 0 .AND. IPR(50) == 1 .AND. J < I) THEN
        CALL PLUT15 (-2, J, 1, IVAL)
        IF (IVAL == 1) GO TO 150
      END IF
C * DISORDER INFO ATOM J
      CALL PLUT15 (-4, J, 28, JDIS)
      JDIS = IPPR(JDIS + 1, 1)
      CALL PLUT15 (-5, J, 48, JPART)
      JPART  = JPART - 16
C * GET ELEMENT RELATED DATA FOR ATOM J
      NRJ    = INT (RA(J * NP43 + 7) / 64000) + 1
      NELJ   = IEN(NRJ)
      IATPRX = IATPR(NELJ)
C * TEST FOR ALKALI OR ALKALI-EARTH
      IF (IATPRX == 5 .OR. IATPRX == 6) THEN
        IATPRJ = 1
C * TEST FOR NON-METAL
      ELSE IF (IATPRX < 0) THEN
        IATPRJ = -1
      ELSE
        IATPRJ = 0
      END IF
C * GET H-ATOM IDENTIFICATION
      CALL PLUT15 (-1, J, 44, JHAT)
C * HANDLE H-BONDS/XBONDS
      IF (IPR(35) < 0) THEN
        IF (IPR(109) > 0) THEN
C * NO -P-ACCEPTOR
          IF (NELJ == 8) GO TO 150
C * TEST FOR MIXED H (OR D) AND NON-H (OR D)
          IF (IHAT == JHAT) GO TO 150
C * AVOID O-COORDINATED N,S AS DO/AC
          IF (NELJ == 4 .OR. NELJ == 6) THEN
            CALL PLUT15 (-1, J, 46, IVAL)
            IF (IVAL == 0) GO TO 150
          END IF
        END IF
      END IF
C * GET MULTIPLICITY FOR J
      CALL PLUT15 (-6, J, 18, NMULT)
C * GET RESIDUE NUMBER FOR ATOM J
      CALL PLUT15 (-6, J, 5, NRESJ)
      DMAX = RADR(NRI, 2) + RADR(NRJ, 2)
C * INCLUDE INTERMEDIATE CONTACTS FOR CU,CO ETC
      IF (IPR(35) >= 0) THEN
        IF (IPR(60) == 1) THEN
          ITST = NELI * NELJ
C * ZN..O,N
          IF (ITST == 309 .OR. ITST == 412) THEN
            DMAX = DMAX + PAR(541)
C * CU..O,N
          ELSE IF (ITST == 30 .OR. ITST == 40 .OR.
     1      ITST == 50 .OR. ITST == 120 .OR. ITST == 180) THEN
            DMAX = DMAX + PAR(542)
C * MN..O,N
          ELSE IF (ITST == 177 .OR. ITST == 236) THEN
            DMAX = DMAX + PAR(543)
C * AG..O,N
          ELSE IF (ITST == 39 .OR. ITST == 52) THEN
            DMAX = DMAX + PAR(544)
C * CR..O,N
          ELSE IF (ITST == 93 .OR. ITST == 124) THEN
            DMAX = DMAX + PAR(545)
C * TL..O,N
          ELSE IF (ITST == 285 .OR. ITST == 380) THEN
            DMAX = DMAX + PAR(546)
          ELSE
            IF (IATPRI * IATPRJ < 0) THEN
              DMAX = DMAX + IGBL(97) * PAR(26)
            END IF
C * AVOID CU-CU, NI-NI,MN-MN,TI-TI,ZN-ZN,CU-NI ETC.
              YUNK = PLA395 (NELI, NELJ)
              IF (YUNK < -9.0) THEN
                DMAX = 2.0
              ELSE
                DMAX = DMAX + YUNK
              END IF
          END IF
C * AVOID LONG I ... I- BONDS
          IF (NELI == 9 .AND. NELJ == 9) DMAX = 3.0
          IF (NELI == 1 .OR. NELJ == 1) DMAX = MIN (DMAX, PAR(461))
        END IF
      ELSE
        IF (IPR(109) > 0) THEN
          DMAX = DMAX - 0.12
        END IF
      END IF
      DMAXSQ = DMAX**2
C * SET UP THE D LIMITS FOR EACH AXIS, START LOOP ON SYMMETRY OPERATORS
      NT = 0
      DO L = 1, 3
        DLIM(IPR(120 + L)) = DMAX / PAR(112 + L)
        RASGX(L)           = RA(J * NP43 + L)
      END DO
      MOLY = 1555
      DO 140 N = 1, NSYM
        IF (JPART < 0 .AND. N > 1) GO TO 140
        DO L = 1, 3
          T(L)       = 0.0
          SGX(L + 3) = 0.0
          SGX(L)     = RASGX(L)
        END DO
        CALL SGSM (3, ICL, SGX, N, LU6, IERR)
C * TAKE CARE OF ATOMS ON SPECIAL POSITIONS
        IF (NMULT > 1) THEN
          IF (N > 1) THEN
            DO K = 1, NT
              DO L = 1, 3
                IF (0.5 - ABS (MOD (10.0 + ABS (SGX(L + 6)
     1            - XTT(K, L)), 1.0)
     2            - 0.5) > 0.005) CYCLE
              END DO
            END DO
          END IF
          NT = NT + 1
          DO L = 1, 3
            XTT(NT, L) = SGX(L + 6)
          END DO
        END IF
        DO M = 1, 3
          XJS(IPR(120 + M)) = SGX(M + 6)
        END DO
C * BEGIN TRANSLATIONAL SEARCH ROUTINE
C * SPECIAL 'NOSHIFT' SHORTCUT
        IF (KSHFT == 0) THEN
C * NO CALCULATION OF INTERMOLECULAR DISTANCES
          IF (I == J)  GO TO 140
          DO K = 1, 3
            SEP(K) = XYZOR(K) - XJS(K)
            IF (ABS (SEP(K)) > DLIM(K))  GO TO 140
          END DO
          GO TO 60
        END IF
        K = 1
C * TRANSLATE XJS ON AXIS K TO A POINT BELOW LOWER LIMIT
   30   IF (XYZOR(K) - XJS(K) > DLIM(K))  GO TO 50
        XJS(K) = XJS(K) - 1.0
        T(K)   = T(K)   - 1.0
        GO TO 30
   40   K = K - 1
        IF (KSHFT == 0) GO TO 140
C * ADVANCE +1.0 ON AXIS K
   50   XJS(K) = XJS(K) + 1.0
        T(K)   = T(K)   + 1.0
        SEP(K) = XJS(K) - XYZOR(K)
        IF (SEP(K) < - DLIM(K))  GO TO 50
C * TEST IF XJS - XI LESS THAN OR EQUAL TO DLIM(K)
        IF (SEP(K) > DLIM(K)) THEN
C * TEST GIVES ATOM OUT OF RANGE. REDUCE AXIS K BY 1
          K = K - 1
          IF (K > 0) THEN
            GO TO 50
          ELSE
            GO TO 140
          END IF
C * K = 0 SIGNALS THE END OF THE SEARCH
        END IF
C * IF XJS WAS WITHIN RANGE ON AXIS K THEN WE ADVANCE K BY 1
        K = K + 1
        IF (K < 4)  GO TO 30
C * ATOM IN RANGE FOR ALL 3 AXES
        IT = INT (ABS (T(1)) + ABS (T(2)) + ABS (T(3)))
C * ELIMINATE DISTANCE OF ATOM FROM ITSELF
        IF (N == 1 .AND. IT == 0 .AND. I == J) GO TO 40
C * NOW CALCULATE EXACT DISTANCE
   60   DO M = 1, 3
          RA(M) = SEP(IPR(120 + M))
        END DO
C * ORTHOGONALIZE
        CALL PLUT23 (0)
        DIJSQ = GEN009(RA(4), RA(4))
        IF (DIJSQ < DMAXSQ) THEN
C * ELIMINATE INTRAMOLECULAR DISTANCES IF INTERMOLECULAR SEARCH ONLY
          IF (IPR(35) < 0) THEN
            IF (N == 1) THEN
              IF (NRESI == NRESJ) THEN
C * TEST FOR H-BOND OPTION
                IF (IPR(109) == 0) THEN
                  IF (IT == 0) GO TO 40
                ELSE
C * AVOID DOUBLE STORAGE OF THE SAME INTRA H-BOND
                  IF (IHAT == 1) THEN
                    IF (IT == 0) GO TO 40
                  END IF
C * AVOID C-H..A CONTACTS
                  CALL PLUT40 (I, J, N, ISW)
                  IF (ISW < 0) GO TO 40
                END IF
              ELSE
                IF (IPR(109) > 0) THEN
C * AVOID C-H..A CONTACTS
                  CALL PLUT40 (I, J, N, ISW)
                  IF (ISW < 0) GO TO 40
                END IF
              END IF
            ELSE
C * CHECK INTER CONTACTS (N > 1)
              IF (IPR(109) > 0) THEN
C * AVOID C-H..A CONTACTS
                CALL PLUT40 (I, J, N, ISW)
                IF (ISW < 0) GO TO 40
              END IF
            END IF
          END IF
        ELSE
          GO TO 40
        END IF
C * WE HAVE A DISTANCE LESS THAN OR EQUAL TO DMAX. STORE CONNECTION
        DIJ = SQRT(DIJSQ)
C * AVOID SI-ND
        IF (DIJ > 3.1) THEN
          IF ((NELI == 63 .AND. NELJ == 85) .OR.
     1        (NELJ == 85 .AND. NELI == 63)) GO TO 40
        END IF
        IF (IPR(109) > 0 .AND. DIJ < 1.25) GO TO 40
C * GET TRANSFORMATION
        MOLZ = NINT(N * 1000 + T(IPR(121)) * 100 + T(IPR(122)) * 10
     1       + T(IPR(123)) + 555)
C * TEST FOR ELEMENT TYPE Q
        IF (NELJ == 111) THEN
          IF (DIJ < RGBL(25) .AND. I /= J) THEN
C * GET ATOM LABEL J
            CALL PLUT25 (1, J, JDUM)
C * GET ATOM LABEL I
            CALL PLUT25 (2, I, IDUM)
            WRITE (LU6, 99992, IOSTAT = IOST) NQ1, NQ2, DIJ
C * EXCLUDE THIS ATOM AND MARK AS SETTLED
            IVAL = 0
            CALL PLUT15 (6, J, 18, IVAL)
            IVAL = 0
            CALL PLUT15 (1, J, 27, IVAL)
            IVAL = 1
            CALL PLUT15 (2, J,  1, IVAL)
            GO TO 150
          END IF
        END IF
        DO M = 1, 3
          XYZJS(M) = XJS(IPR(120 + M))
        END DO
        IF (DIJ < 0.05 .AND. I == J) THEN
          IF (J > IPR(37)) GO TO 40
          CALL PLUT15 (-2, J, 3, IVL)
          IVL = MAX (IVL, 1)
          CALL PLUT15 ( 2, J, 3, IVL)
          IVL = 1
          CALL PLUT15 ( 1, J, 1, IVL)
          IF (I == J) GO TO 40
C * DELETE SYMMETRY-EQUIVALENT ATOM
          IVL = 0
          CALL PLUT15 (1, J, 2, IVL)
          L = IPR(68) + 1
   70     CALL PLUT16 (0, L, IL1, IL2, DUM1, IDUM2)
C * AVOID ELIMINATION OF UNIQUE BONDS
          IF (IL1 > IPR(38) .OR. IL2 > IPR(38)) THEN
            IF (IL1 == J) THEN
              GO TO 80
            ELSE IF (IL1 > J) THEN
              GO TO 100
            END IF
            IF (IL2 /= J)  GO TO 90
   80       CALL PLUT16 (-3, IDUM0, IL1, IL2, DUM1, IDUM2)
          END IF
   90     L = L + 1
          IF (L <= IPR(52))  GO TO 70
  100     IVL = 3
          CALL PLUT15 (2, J, 3, IVL)
          GO TO 140
        END IF
C * DECIDE WHAT TO DO WITH THIS CONNECTION
        KAT = J
        NEW = 1
C * JOIN RADII INTER CASE
        IF (IPR(35) < 0) THEN
C * HANDLE CASE OF MORE THAN ONE RESIDUES IN ASYMMETRIC UNIT
          IF (N == 1 .AND. IT == 0 .AND. NRESI /= NRESJ) THEN
            GO TO 130
          ELSE
            GO TO 110
          END IF
        ELSE
C * JOIN RADII (UNIQUE) MODE
          IF (JHAT == 1) THEN
            CALL PLUT15 (-1, I, 46, JDOAC)
            CALL PLUT15 ( 1, J, 32, JDOAC)
          END IF
          CALL PLUT15 (-1, J, 1, IVAL)
          IF (IVAL == 0) THEN
C * SET 'INEXT' FLAG
            IVL = 1
            CALL PLUT15 (1, J, 2, IVL)
            IF (IPR(50) == 0) THEN
              IF (IATPRI >= 0 .AND. IATPRJ < 0) NEXT = 1
            END IF
          END IF
          CALL PLUT15 (-2, J, 3, IVL)
          IF (N == 1 .AND. IT == 0) THEN
            ITX = 1
            IF (IVL > 0) GO TO 130
          ELSE
            ITX = 0
          END IF
          IF (IVL == 0) THEN
            IF (ITX == 0) THEN
C * MOVE ATOM J
              DO II = 1, 3
                RA(J * NP43 + II) = XYZJS(II)
              END DO
              CALL PLUT23 (J)
              IVL = 2
            ELSE
              IVL = 1
            END IF
            CALL PLUT15 (2, J, 3, IVL)
            GO TO 130
          END IF
          IF (IPR(50) == 0) THEN
            DO II = 1, 3
              IF (ABS (RA(J * NP43 + II) - XYZJS(II)) * PAR(100 + II)
     1           > PAR(22)) GO TO  110
            END DO
            GO TO 130
          END IF
        END IF
C * ADD ATOM TO LIST. THE EXTRA ATOMS ARE USED FOR DRAWING BONDS BETWEEN
C * MOLECULES. THE CIRCLES ARE IN GENERAL NOT TO BE DRAWN HOWEVER.
C * TEST FOR DUPLICATION OF ATOM COORDINATES IN LIST
  110   IF (NEW > 0) THEN
          NATC = IPR(38) + IPR(55)
          DO 120 KAT = ILPB, NATC
            DO II = 1, 3
              IF (ABS (RA(KAT * NP43 + II) - XYZJS(II))
     1            * PAR(100 + II) >= PAR(22)) GO TO 120
            END DO
            GO TO 130
  120     CONTINUE
          IPR(55) = IPR(55) + 1
          KAT     = IPR(38) + IPR(55)
C * STACK OVERFLOW TEST
          IF ((KAT + 1) * NP43 > IPR(64) - IPR(52) * 2) THEN
C * SEARCH INTERRUPTED
            IPR(42) = IPR(43)
            IPR(52) = IPR(53)
            IPR(37) = IPR(38)
            IPR(72) = 29
            GO TO 230
          END IF
          DO II = 1, 3
            RA(KAT * NP43 + II) = XYZJS(II)
          END DO
          CALL PLUT23 (KAT)
C * SET AND COPY FLAGS FOR ATOM KAT
C * COPY LABEL POSITION, ATOM TYPE (ELEMENT INDEX), DOAC-BIT
C * COPY IDH-BIT, METAL/HATOM BITS, MULTIPLICITY
          RA(KAT * NP43 + 8)  = RA(J * NP43 + 8)
          RA(KAT * NP43 + 9)  = RA(J * NP43 + 9)
          RA(KAT * NP43 + 10) = RA(J * NP43 + 10)
          RA(KAT * NP43 + 11) = RA(J * NP43 + 11)
          XM1                 = RA(J * NP43 + 12) * 1000.0
          XM2 = MOLZ
          CALL PLA270 (XM1, XM2, XM3)
          RA(KAT * NP43 + 12) = XM3 / 1000.0
          IVL = 0
          CALL PLUT15 (2, KAT, 3, IVL)
          IVL = 0
          CALL PLUT15 (2, I,   1, IVL)
C * SPECIAL INTRA RESIDUE COPY
            CALL PLUT15 (-6, I,   5, IVAL)
            CALL PLUT15 ( 6, KAT, 5, IVAL)
C * SET INCLUDE BIT TO 0
          IVL = 0
          CALL PLUT15 ( 1, KAT, 27, IVL)
        END IF
C * SET RESIDUE NUMBER
        IF (IPR(35) >= 0) THEN
          CALL PLUT15 (6, KAT,  5, IPR(70))
          IVL = IPR(70) - 1
          CALL PLUT15 (6, KAT, 11, IVL)
        END IF
C * ADD THIS ARU TO ARU-LIST
        IF (IPR(35) >= 0) THEN
          CALL PLUT15 (-6, KAT, 5, NRESJ)
        ELSE
          CALL PLUT15 (-6, J, 5, NRESJ)
        END IF
        XM1  = MOLZ
        XM2  = MOLY
        CALL PLA270 (XM1, XM2, XM3)
        XMOL = INT (XM3) + NRESJ / PAR(42)
        IF (IPR(35) < 0) THEN
          MTYPE = -1
        ELSE
          MTYPE =  0
        END IF
C * ADD MOLECULE
        CALL PLUT17 (MTYPE, XMOL, MADDR, LU6)
C * EXPAND TO MOLECULE
        IF (IPR(35) < 0) CALL PLUT35 (XMOL, -1)
        IF (NEW > 0) THEN
C * COPY LABEL
          RA(KAT * NP43 + 7) = RA(J * NP43 + 7)
          CALL PLUT15 (6, KAT, 11, MADDR)
        END IF
C * REGISTER TRANSFORMATION ON INPUT COORDINATES
  130   IF (RA(KAT * NP43 + 12) <= 0.0) THEN
          RA(KAT * NP43 + 12) = MOLZ / 1000.0
          IF (KAT <= NATO) THEN
            XM1 = MOLZ
            XM2 = 0.0
            CALL PLA270 (XM1, XM2, XM3)
            IF (IPR(2) /= 0) THEN
              IPR(72) = 100 + IPR(2)
              GO TO 230
            END IF
            MOLY = INT (XM3)
          END IF
        END IF
 
C * ADD CONNECTION TO LIST
        IF (.TRUE.) THEN
C * AVOID DISORDER BONDS
          JUNK = 0
          IF (IPART /= JPART) THEN
            IF (IPART == 0 .OR. JPART == 0) JUNK = 1
          ELSE IF (IPART == JPART) THEN
            JUNK = 1
          END IF
          IF (JUNK == 1) THEN
            IF (IDIS < 10000 .AND. JDIS < 10000) THEN
              IF (IDIS == 5000 .AND. JDIS == 5000) THEN
                IF (IABS (IPART) > 0 .AND.
     1              IABS (JPART) > 0) THEN
                  IF (IPART /= JPART) GO TO 40
                END IF
              END IF
              IF (ABS (IDIS -JDIS) > 1) THEN
                IF (IABS (2 * IDIS - JDIS) > 1 .AND.
     1              IABS (2 * JDIS - IDIS) > 1) THEN
                  IF (IPART /= JPART .OR.
     1               (IPART == 0 .AND. JPART == 0)) GO TO 40
                END IF
              END IF
            END IF
            IF (NEW > 0) THEN
              CALL PLUT16 (-1, IDUM0, I, KAT, DUM1, IDUM2)
C * REGISTER NUMBER OF BONDS PER ATOM AND NR OF BONDS TO OXYGEN
              IF (IPR(35) >= 0) THEN
                CALL PLUT15 (-3, I, 24, IVAL1)
                IF (NELJ == 3 .AND. IVAL1 < 7) THEN
                  IVL = IVAL1 + 1
                  CALL PLUT15 (3, I, 24, IVL)
                END IF
                CALL PLUT15 (-3, KAT, 24, IVAL2)
                IF (NELI == 3 .AND. IVAL2 < 7) THEN
                  IVL = IVAL2 + 1
                  CALL PLUT15 (3, KAT, 24, IVL)
                END IF
              END IF
            END IF
          END IF
        END IF
        GO TO 40
C * END LOOP ON SYMMETRY OPERATORS ON ATOM J
  140 CONTINUE
C * BREAK SEQUENCE FOR METAL-NEWFIX
  150 IF (NEXT == 0) THEN
        J = J + 1
        IF (J <= NATO)  GO TO 20
C * NOW DECIDE WHAT TO DO ABOUT THE NEXT ATOM I
        IF (IPR(35) >= 0) THEN
C * MARK THIS ATOM AS SETTLED
          IVL = 1
          CALL PLUT15 (2, I, 1, IVL)
C * COLLECT DATA FOR C.G. OF RESIDUE (ASYMMETRIC UNIT)
          DO JJ = 1, 3
            RCG(JJ, NRESI) = RCG(JJ, NRESI) + RA(I * NP43 + JJ)
          END DO
          RCG(4, NRESI) = RCG(4, NRESI) + 1
        END IF
      END IF
C * DETERMINE THE NEXT I-ATOM
  160 IF (IPR(35) >= 0) THEN
        IATPRI = 0
        INXT   = 0
        I      = 0
        IL0    = ILSTRT
C * LOOK FOR THE  NEXT UNSETTLED ATOM
        DO IL = IL0, NATO
C * GET INEXT / IDONE STATUS
          CALL PLUT15 (-2, IL, 1, IVAL)
C * TEST FOR NOT-DONE STATUS
          IF (IVAL /= 1) THEN
C * GET ELEMENT TYPE INDEX IN NON-ANGSTROM CASE
            IF (IPR(50) == 0)
     1      IATPRI = IATPR(IEN(INT(RA(IL * NP43 + 7) / 64000) + 1))
            IF (IVAL == 2) THEN
C * METAL/NON-METAL TEST
              IF (IATPRI < 0) THEN
                I = IL
                GO TO 170
              ELSE
                IF (I == 0) I = - IL
              END IF
            END IF
C * REGISTER POTENTIAL STARTING ATOM TO START NEW RESIDUE (PREF. NON-METAL)
            IF (INXT <= 0) THEN
              IF (IVAL == 0) THEN
                IF (IATPRI < 0) THEN
                  INXT =   IL
                ELSE
                  INXT = - IL
                END IF
              END IF
            END IF
          ELSE
C * RAISE BOTTOM OF SEARCH LOOP
            IF (IL == ILSTRT) ILSTRT = ILSTRT + 1
          END IF
        END DO
C * FINALLY LOOP ON A 'NOT-YET-DONE' METAL ATOM
        IF (I < 0) THEN
          I = IABS (I)
          GO TO 170
        END IF
C * CALCULATE RESIDUE C.G.
        JJ = IPR(70)
        IF (JJ > 0) THEN
          ICG = IPR(38) + IPR(55) + 1
          ID0 = ICG + 1
          ID1 = ID0 + 1
          DO L = 1, 3
            RCG(L, JJ)         = RCG(L, JJ) / RCG(4, JJ)
            RA(ICG * NP43 + L) = RCG(L, JJ)
            RA(ID0 * NP43 + L) = PAR(141 + L)
          END DO
          RA(ICG * NP43 + 12) = 1.555
          CALL PLUT15 (6, ICG, 5, JJ)
C * BRING X,Y,Z OF CENTRE OF GRAVITY IN RANGE 0 TO 1
C * (CLOSEST TO PAR(142), PAR(143), PAR(144))
          IF (IGBL(30) <= 0) THEN
            CALL PLUT23 (ICG)
            CALL PLUT23 (ID0)
            DUM5 = 99999.0
            IF (PAR(140) >= 0.0) THEN
              DO K = 1, NSYM
                DO L = 1, 3
                  SGX(L)     = RA(ICG * NP43 + L)
                  SGX(L + 3) = 0.0
                END DO
                CALL SGSM (3, ICL, SGX, K, LU6, IERR)
                DO L = 1, 3
                  DUM1 = AMOD (SGX(L + 6), 1.0)
                  IF (DUM1 < 0.0) DUM1 = DUM1 + 1.0
                  RA(ID1 * NP43 + L) = DUM1
                  TRL(L)            = DUM1 - SGX(L + 6)
                END DO
                CALL PLUT23 (ID1)
                CALL PLUT22 (ID0, ID1, DUM4)
                IF (DUM4 < DUM5) THEN
                  DUM5 = DUM4
                  N = K
                  DO L = 1, 3
                    T(L) = TRL(L)
                  END DO
                END IF
              END DO
            ELSE
              YM1  = ABS (PAR(140) * 1000.0)
              N    = INT (YM1 / 1000.0)
              YM1  = YM1 - N * 1000.0
              T(1) = INT (YM1 / 100.0)
              YM1  = YM1 - T(1) * 100.0
              T(1) = T(1) - 5
              T(2) = INT (YM1 / 10.0)
              T(3) = INT (YM1 - T(2) * 10.0)
              T(2) = T(2) - 5
              T(3) = T(3) - 5
            END IF
            YM1 = N * 1000.0 + T(1) * 100.0 + T(2) * 10.0 + T(3)
     1          + 555.0
C * CG_TRANSFORMATION AND INVERSE
            CALL PLA270 (YM1, 0.0, YMM1)
C * CALL EXIT/STOP
            IF (IPR(2) /= 0) CALL GEN127 ('105')
C * APPLY TRANSFORMATION TO ALL ATOMS (INCL CG_RESD) IN THIS RESIDUE
            DO I0 = ILPB, ICG
C * GET RESIDUE NUMBER FOR THIS ATOM
              CALL PLUT15 (-6, I0, 5, I0RES)
              IF (I0RES == JJ) THEN
                DO L = 1, 3
                  SGX(L)     = RA(I0 * NP43 + L)
                  SGX(L + 3) = T(L)
                END DO
                CALL SGSM (3, ICL, SGX, N, LU6, IERR)
                DO L = 1, 3
                  RA(I0 * NP43 + L) = SGX(L + 6)
                END DO
                CALL PLUT23 (I0)
                YM2 = RA(I0 * NP43 + 12) * 1000.0
                CALL PLA270 (YM1, YM2, YM3)
                IF (IPR(2) == 0)
     1          RA(I0 * NP43 + 12) = YM3 / 1000.0
              END IF
            END DO
C * RETURN TRANSFORMED CENTRE_OF_GRAVITY
            DO L = 1, 3
              RCG(L, JJ) = RA(ICG * NP43 + L)
            END DO
C * MODIFY ARU [ T R T-1 ]
            L1 = IPR(42)
            IF (L1 > 0) THEN
              DO L = 1, L1
                YRES = MOD (IARU(1, L) / PAR(42), 1.0)
                JJRES = NINT (YRES * PAR(42))
                IF (JJ == JJRES) THEN
                  YM3 = INT (IARU(1, L) / PAR(42))
                  CALL PLA270 (YM1, YM3, YM2)
C * CALL EXIT/STOP
                  IF (IPR(2) /= 0) CALL GEN127 ('103')
                  CALL PLA270 (YM2, YMM1, YM3)
C * CALL EXIT/STOP
                  IF (IPR(2) /= 0) CALL GEN127 ('102')
                  IARU(1, L) = NINT ((YM3 + YRES) * PAR(42))
                END IF
              END DO
            END IF
          END IF
        END IF
C * NO CONNECTED ATOM IS LEFT TO GOTO, THEREFORE WE BEGIN A NEW
C * RESIDUE, UNLESS ALL ATOMS HAVE BEEN DONE
        IF (INXT == 0) GO TO 180
        I = IABS (INXT)
        IF (IGBL(30) == 0) THEN
          NTRNS = IABS (NINT (RA(I * NP43 + 12) * 1000))
          IF (NTRNS > 0) THEN
            IGBL(30) = - 1
            N     = NTRNS / 1000
            NTRNS = NTRNS - N * 1000
            K     = NTRNS / 100
            T(1)  = K - 5
            NTRNS = NTRNS - K * 100
            K     = NTRNS / 10
            T(2)  = K - 5
            NTRNS = NTRNS - K * 10
            T(3)  = NTRNS - 5
            DO L = 1, 3
              SGX(L)     = RA(I * NP43 + L)
              SGX(L + 3) = T(L)
            END DO
            CALL SGSM (3, ICL, SGX, N, LU6, IERR)
            DO L = 1, 3
              RA(I * NP43 + L) = SGX(L + 6)
            END DO
            NTRNS = N * 1000 + NINT (T(1) * 100.0 + T(2) * 10.0 + T(3))
     1            + 555
C * SET MOVE BIT
            IF (NTRNS /= 1555) THEN
              IVL = 1
              CALL PLUT15 (1, I, 43, IVL)
            END IF
            XTRNS = NTRNS / 1000.0
          ELSE
            XTRNS = 1.555
          END IF
        ELSE
          XTRNS = 1.555
        END IF
        RA(I * NP43 + 12) = XTRNS
        IVL = 1
        CALL PLUT15 (2, I, 3, IVL)
C * SET THE NEXT ATOM I FOR CALCULATION
        IF (IPR(70) < NRESM) THEN
          IF (IPR(136) == 0) THEN
            IPR(70) = IPR(70) + 1
          ELSE
            CALL PLUT15 (-6, I, 5, IPR(70))
          END IF
          IPR(75) = MAX (IPR(75), IPR(70))
          IF (IPR(70) == NRESM)
     1      WRITE (LU6, 99999, IOSTAT = IOST) NRESM
        END IF
C * ADD/STORE THIS ARU
        XMOL  = 1555.0 + IPR(70) / PAR(42)
        MADDR = 0
        CALL PLUT17 (0, XMOL, MADDR, LU6)
C * SET RESIDUE AND ARU NUMBERS AND ORTHONORMALISE IN INTRA MODE
  170   CALL PLUT23 (I)
        CALL PLUT15 (6, I,  5, IPR(70))
        IVL = IPR(75) - 1
        CALL PLUT15 (6, I, 11, IVL)
      ELSE
C * ADVANCE I TO I + 1 IF NOT UNIQUE MODE
        I = I + 1
        IF (I > NATO)  GO TO 180
      END IF
      GO TO 10
C * END OF LOOP ON I
  180 IPR(37) = IPR(38) + IPR(55)
      IF (IPR(35) >= 0) THEN
        IPR(38) = IPR(37)
        IPR(53) = IPR(52)
        IPR(20) = 1
C * PRINT OUT WHAT HAS BEEN FOUND
        WRITE (LU6, 99997, IOSTAT = IOST) IPR(75)
        DO I = ILPB, NATO
          CALL PLUT15 (-2, I, 3, IVAL)
          IF (IVAL == 2) THEN
            IVL = 1
            CALL PLUT15 (1, I, 43, IVL)
          END IF
        END DO
      END IF
      IF (IPR(35) < 0) THEN
        MTYPE = -1
      ELSE
        MTYPE   = 0
        IPR(43) = IPR(42)
        IPR(44) = IPR(42)
      END IF
        DO I = ILPB, IPR(39)
          IF (RA(I * NP43 + 12) /= 1.555) IGBL(60) = IGBL(60) + 1
        END DO
C * COMPLETE MOLECULES SITTING ON A SYMMETRY ELEMENT
      IF (IPR(110) == 1) THEN
        INFIN = 0
C * GENERATE ADDITIONAL ARU'S FOR N-ORDER SYMMETRY ELEMENTS
        IF (IPR(42) > 1) THEN
          NML0 = 0
  190     NARU = IPR(42)
          MI   = 0
C * GET AND UNPACK NEXT ARU MI
  200     DO
            MI = MI + 1
            IF (MI > NARU) GO TO 220
            MPM = IARU(1, MI)
            IF (MPM >= 0) EXIT
          END DO
          CALL GEN098 (MPM, PAR(42), MS1, MT11, MT21, MT31, MR1)
          IF (MI > NML0) THEN
            MJ = 0
          ELSE
            MJ = NML0
          END IF
C * GET AND UNPACK NEXT ARU MJ
  210     DO
            MJ = MJ + 1
            IF (MJ > NARU) GO TO 200
            MPM = IARU(1, MJ)
            IF (MPM < 0) CYCLE
            CALL GEN098 (MPM, PAR(42), MS2, ITX, ITY, ITZ, MR2)
            IF (MR2 == MR1) EXIT
          END DO
          SGX(1) = MS1
          SGX(2) = MT11
          SGX(3) = MT21
          SGX(4) = MT31
          SGX(5) = MS2
          SGX(6) = ITX
          SGX(7) = ITY
          SGX(8) = ITZ
          CALL SGSM (8, ICL, SGX, 0, LU6, IERR)
          MS3  = NINT (SGX(9))
          MT13 = NINT (SGX(10))
          MT23 = NINT (SGX(11))
          MT33 = NINT (SGX(12))
          M3   = (MS3 * 1000 + MT13 * 100 + MT23 * 10 + MT33 + 555)
          M3   = NINT(M3 * PAR(42)) + MR1
          XM3  = M3 / PAR(42)
          MK   = 0
          DO
            MK   = MK + 1
            IF (MK > NARU) THEN
C * ADD THIS ARU/ASU TO THE LIST
              CALL PLUT17 (MTYPE, XM3, MADDR, LU6)
              IF (IPR(35) < 0) CALL PLUT35 (XM3, -1)
              GO TO 210
            END IF
            XM4 = IARU(1, MK) / PAR(42)
            IF (XM4 < 0.0) GO TO 210
            IF (XM3 == XM4) GO TO 210
            M4  = INT (XM4)
            MR4 = NINT ((XM4 - M4) * PAR(42))
            IF (MR4 == MR1) THEN
              MS4 = M4 / 1000
              MT4 = M4 - MS4 * 1000
C * AVOID INFINITE NET
              IF (MS3 == MS4) THEN
                MT14 = MT4 / 100
                IF (IABS (MT13 - MT14 + 5) > 0) THEN
                  INFIN = 1
                  GO TO 210
                ELSE
                  MT4 = MT4 - MT14 * 100
                  MT24 = MT4 / 10
                  IF (IABS (MT23 - MT24 + 5) > 0) THEN
                    INFIN = 1
                    GO TO 210
                  ELSE
                    MT34 = MT4 - MT24 * 10
                    IF (IABS (MT33 - MT34 + 5) > 0) THEN
                      INFIN = 1
                      GO TO 210
                    END IF
                  END IF
                END IF
              END IF
            END IF
          END DO
C * RECYCLE WHEN NEW ARU('S) HAS/HAVE BEEN ADDED
  220     IF (IPR(42) > NARU) THEN
            NML0 = NARU
            GO TO 190
          END IF
        END IF
        IF (IPR(35) >= 0) THEN
          IPR(43) = IPR(42)
          IPR(44) = IPR(42)
C * AVOID H-BONDS TO CENTRAL ATOMS IN Phen-NO, NO3, SO4 etc
          DO I = 1, IPR(37)
C * GET ELEMENT RELATED DATA FOR ATOM I
            NRI  = INT (RA(I * NP43 + 7) / 64000) + 1
            NELI = IEN(NRI)
C * N (= 4)
            IF (NELI == 4) THEN
C * GET NUMBER OF BONDS
              CALL PLUT15 (-4, I, 33, NBOND)
              IF (NBOND == 2) THEN
                NRBO = 99
              ELSE IF (NBOND == 3) THEN
                NRBO = 2
              ELSE
                NRBO = 1
              END IF
C * S (= 6)
            ELSE IF (NELI == 6) THEN
              NRBO = 2
C * P (= 8)
            ELSE IF (NELI == 8) THEN
              NRBO = 4
            ELSE
              NRBO = 99
            END IF
C * GET NUMBER OF CONNECTIONS TO O
            CALL PLUT15 (-3, I, 24, IVAL)
            IF (IVAL >= NRBO) THEN
              IVL = 0
              CALL PLUT15 (1, I, 46, IVL)
C * ELIMINATE METAL - N(O3) ETC. BONDS
              DO J = 1, IPR(37)
                NRJ = INT (RA(J * NP43 + 7) / 64000) + 1
                IATPRJ = IATPR(IEN(NRJ))
C * CHECK FOR METAL
                IF (IATPRJ > 0) THEN
                  IF (NELI /= 4 .OR. NBOND /= 3) THEN
C * DELETE THIS BOND
                    CALL PLUT16 (-3, IDUM0, I, J, DUM1, IDUM2)
                  END IF
                END IF
              END DO
            END IF
          END DO
          WRITE (LU6, 99995, IOSTAT = IOST) IPR(43)
          IF (INFIN > 0) THEN
            IGBL(127) = 1
            WRITE (LU6, 99994, IOSTAT = IOST)
          END IF
        END IF
      END IF
C * END MOL EXPAND
  230 IF (IPR(50) * IPR(135) > 0) THEN
        DO I = 1, IPR(37)
          YUNK = MOD (RA(I * NP43 + 3), 100.0)
          IF (YUNK > 50.0) YUNK = YUNK - 100.0
          RA(I * NP43 + 3) = YUNK
          RA(I * NP43 + 6) = YUNK
        END DO
      END IF
      RETURN
99999 FORMAT ( ':: Maximum Residue Number(=', I2, ') reached.',
     1         ' (non-fatal)')
99998 FORMAT ( ':: AEX:JOIN RADII UNIQUE EXPAND')
99997 FORMAT ( ':: Structure contains', I3, ' isolated residue(s)')
99996 FORMAT ( ':: AEX:JOIN RADII')
99995 FORMAT (/':: Number of Unique Asymmetric Residue Units:', I5)
99994 FORMAT (/':: Infinite Structure')
99993 FORMAT ( ':: AEX:JOIN RADII UNIQUE')
99992 FORMAT ( ':: ', A, ' Excluded, DIST TO ', A, ' =', F7.2, ' Ang')
99991 FORMAT ('VIEW MIN')
      END SUBROUTINE PLUT07
 
      SUBROUTINE PLUT08
C * GENERATE MINIMUM OVERLAP ROTATION MATRIX
      USE files
      USE parameters
      USE pluto
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: KM
      INTEGER :: NM
      INTEGER :: NR
      INTEGER :: NS
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: NAT
      INTEGER :: MPM
      INTEGER :: NARU
      INTEGER :: JINC
      INTEGER :: IRES
      INTEGER :: ILPB
      INTEGER :: IDET
      INTEGER :: NINCL
      INTEGER :: MADDR
      REAL :: XX
      REAL :: YY
      REAL :: ZZ
      REAL :: XNM
      REAL :: XSQ
      REAL :: YSQ
      REAL :: ZSQ
      REAL :: TEMP
      REAL, DIMENSION(3,3) :: V
      REAL, DIMENSION(6)   :: XDA
C * COMPUTE MATRIX FOR L.S. PLANE WITH NORMAL ALONG Z-AXIS
C * THE METHOD USED IS TO FIND THE PRINCIPAL AXES OF INERTIA. THE Z-AXIS
C * WILL GIVE THE MAXIMUM MOMENT OF INERTIA, AND THE X-AXIS THE MINIMUM.
C * MAKE SHURE THAT THERE IS AT LEAST ONE ARU
      MADDR = 0
      CALL PLUT17 (0, 0.0, MADDR, LU6)
      NAT  = IPR(37)
      NARU = IPR(42)
      ILPB = IPR(69) + 1
C * GET THE MASS CENTRE
      CALL GEN074 (PAR, 67, 69, 0.0)
      N  = 0
C * GET STACK PARAMETERS
      K  = (NAT + 1) * NP43
      KM = IPR(64) - IPR(52) * 2 - 3
C * LOOP OVER ATOMS
      DO I = ILPB, NAT
        CALL PLUT15 (-1, I, 27, NINCL)
        IF (NINCL > 0) THEN
C * GET RESIDUE NUMBER
          CALL PLUT15 (-6, I, 5, IRES)
          CALL PLUT15 (-6, I, 18, JINC)
          IF (JINC == 1) THEN
            NM = NARU
          ELSE
            NM = 1
          END IF
C * LOOP OVER ARU LIST
          DO M = 1, NM
            XNM = IARU(1, M) / PAR(42)
            IF (XNM > 0.0) THEN
              MPM = NINT (XNM * PAR(42))
              CALL GEN098 (MPM, PAR(42), NS, ITX, ITY, ITZ, NR)
              TRL(1) = ITX
              TRL(2) = ITY
              TRL(3) = ITZ
C * RESIDUE TEST
              IF (NR == 0 .OR. IRES == NR) THEN
C * GENERATE FRACTIONAL COORDINATES
                DO J = 1,3
                  SGX(J)     = RA(I * NP43 + J)
                  SGX(J + 3) = TRL(J)
                END DO
                CALL SGSM (3, ICL, SGX, NS, LU6, IERR)
C * ORTHOGONALIZE
                DO J = 1, 3
                  RA(J) = SGX(J + 6)
                END DO
                CALL PLUT23 (0)
                IF (K < KM) THEN
                  DO J = 1, 3
                    RA(K + J)   = RA(J + 3)
                    PAR(66 + J) = PAR(66 + J) + RA(J + 3)
                  END DO
                  K = K + 3
                  N = N + 1
                ELSE
                  IPR(101) = IPR(101) + 1
                END IF
              END IF
            END IF
          END DO
        END IF
      END DO
      IF (N > 0) THEN
        IF (N > 1) THEN
          IF (N == 2) THEN
            DO J = 1, 3
              PAR(66 + J) = PAR(66 + J) + 0.01
            END DO
          END IF
          CALL GEN074 (XDA, 1, 6, 0.0)
          DO J = 1, 3
            PAR(66 + J) = PAR(66 + J) / N
          END DO
          K = (NAT + 1) * NP43
          DO I = 1, N
            XX = RA(K + 1) - PAR(67)
            YY = RA(K + 2) - PAR(68)
            ZZ = RA(K + 3) - PAR(69)
            K   = K + 3
            XSQ = XX * XX
            YSQ = YY * YY
            ZSQ = ZZ * ZZ
C * STORE MATRIX Q IN COMPACT MODE FOR GEN023
            XDA(1) = XDA(1) + (YSQ + ZSQ)
            XDA(2) = XDA(2) - XX * YY
            XDA(4) = XDA(4) - XX * ZZ
            XDA(3) = XDA(3) + (ZSQ + XSQ)
            XDA(5) = XDA(5) - YY * ZZ
            XDA(6) = XDA(6) + (XSQ + YSQ)
          END DO
C * CALCULATE EIGENVECTORS AND EIGENVALUES
          CALL GEN023 (XDA, V, 3)
C * THE LATENT ROOTS ARE NOW THE DIAGONAL  ELEMENTS OF A
C * THE ROTATION MATRIX R IS THE TRANSPOSE OF V
          CALL GEN005 (V, R)
C * ROTATE 90 DEG. ABOUT Y SO THAT THE Z AXIS IS PERP TO LS PLANE
          DO K = 1, 3
            TEMP = R(1, K)
            R(1, K) = -R(3, K)
            R(3, K) = TEMP
          END DO
          CALL GEN010 (R, IDET, 1)
        ELSE
          CALL GEN021 (R, 1.0)
        END IF
      ELSE
        IPR(72) = 30
      END IF
      RETURN
      END SUBROUTINE PLUT08
 
      SUBROUTINE PLUT09 (NINCL, ISW)
C * HANDLE INCLUDE/EXCLUDE/OMIT/DELETE
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: IS
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: NAT
      INTEGER :: IAI
      INTEGER :: ISW
      INTEGER :: IBEG
      INTEGER :: IEND
      INTEGER :: ILPB
      INTEGER :: NINC
      INTEGER :: IVAL
      INTEGER :: NATO
      INTEGER :: NATOS
      INTEGER :: IMULT
      INTEGER :: IDUM2
      INTEGER :: NINCL
      REAL :: XDUM
      CHARACTER(len=3) :: NTXT
      IS = ISW
      IF (IABS(IGBL(8)) /= 2) THEN
C * CHANGE DEL(ETE) INTO EXCLUDE (DELETE = 89)
        IF (IS == 89 .OR. IS == 159) THEN
          IS    = 28
          NINCL = 0
        END IF
      END IF
C * SET REBUILD
      IPR(130) = 0
      NAT      = IPR(37)
      NATOS    = IPR(38)
      NATO     = IPR(39)
      ILPB     = IPR(69) + 1
      KL       = IPR(220)
      KN       = IPR(221)
      IPR(72)  = 0
      IF (KL > 1) THEN
        NTXT = IFL(2)(1:3)
      ELSE
        NTXT = 'ALL'
      END IF
      NINC = NINCL
C * (IN/EX)CLUDE NONE - CHANGE INTO ALL
      IF (NTXT == 'NON') THEN
        NINC = MOD (NINCL + 1, 2)
        NTXT = 'ALL'
      END IF
C * (IN/EX)CLUDE ALL
      IF (NTXT == 'ALL') THEN
        DO I = ILPB, NAT
          CALL PLUT15 (1, I, 27, NINC)
        END DO
C * (IN/EX)CLUDE C-H ATOMS
      ELSE IF (NTXT == 'CH') THEN
        DO I = ILPB, NATO
          CALL PLUT15 (-1, I, 44, IVAL)
          IF (IVAL == 1) THEN
            CALL PLUT15 (-1, I, 32, IVAL)
            IF (IVAL == 0) THEN
              CALL PLUT15 (1, I, 27, NINCL)
            END IF
          END IF
        END DO
C * (IN/EX)CLUDE D-H ATOMS
      ELSE IF (NTXT == 'DH') THEN
        DO I = ILPB, NATO
          CALL PLUT15 (-1, I, 32, IVAL)
          IF (IVAL == 1) THEN
            CALL PLUT15 (1, I, 27, NINCL)
          END IF
        END DO
C * (IN/EX)CLUDE ZOMBIES
      ELSE IF (NTXT == 'ZOM') THEN
        IPR(166) = NINC
        IPR(130) = 0
C * OMIT OUTSIDE
      ELSE IF (NTXT == 'OUT') THEN
C * SET DEFAULT ENCLOSURE VALUES
        DO I = 1, 3
          PAR(I * 2 + 28) =  1.01
          PAR(I * 2 + 27) = -0.01
        END DO
        PAR(35) = 4.5
C * SET ENCLOSURE BIT ON (I.E. ONLY ATOMS WITHIN ENCLOSURE TO BE PLOTTED)
        IF (KL == 3) THEN
          CALL PLUT13 (0, KL, M, XDUM)
        ELSE
          M = 0
        END IF
        IF (KN == 0 .AND. M <= 0) THEN
          IPR(15) = 1
        ELSE IF (KN == 1) THEN
          PAR(35) = FN(1)
          IF (PAR(35) > 0.0) THEN
            IPR(15) = - M
          ELSE
C * SET ENCLOSURE BIT OFF
            IPR(15) = 0
          END IF
        ELSE IF (KN == 6) THEN
          DO I = 1, KN
            PAR(I + 28) = FN(I)
          END DO
          IF (M > 0) THEN
            DO I = 1, 3
              DO J = 27, 28
                PAR(I * 2 + J) = PAR(I * 2 + J) + RA(M * NP43 + I)
              END DO
            END DO
          END IF
          IPR(15) = 1
        ELSE
          IPR(72) = 31
        END IF
      ELSE
        DO K = 2, KL
C * (IN/EX)CLUDE UNIQUE
           IF (IFL(K)(1:3) == 'UNI') THEN
             M = NATO + 1
             IF (M <= NATOS) THEN
               DO I = M, NATOS
                  CALL PLUT15 (1, I, 27, NINCL)
               END DO
             END IF
C * (IN/EX)CLUDE INTER
           ELSE IF (IFL(K)(1:3) == 'INT') THEN
             M = NATOS + 1
             IF (M <= NAT) THEN
               DO I = M, NAT
                 CALL PLUT15 (1, I, 27, NINCL)
               END DO
             END IF
C * (IN/EX)CLUDE ORIG
           ELSE IF (IFL(K)(1:3) == 'ORI') THEN
             DO I = ILPB, NATO
               CALL PLUT15 (1, I, 27, NINCL)
             END DO
C * (IN/EX)CLUDE ATOM-TYPE/ATOM-NAME
           ELSE
             IF (IS == 89 .OR. IS == 159) THEN
               CALL PLUT13 (0, K, M, XDUM)
             ELSE
               CALL PLUT13 (0, -K, M, XDUM)
             END IF
C * EXCLUDE ON ELEMENT TYPE
             IF (M < 0) THEN
               IBEG = ILPB
               IF (NINC == 0) THEN
                 IEND = NAT
               ELSE
                 IEND = NATO
               END IF
C * EXCLUDE ON ATOM NAME
             ELSE
               CALL PLUT25 (0, M, IAI)
               IBEG = M
               IEND = M
               M    = - IAI
             END IF
             DO I = IBEG, IEND
               CALL PLUT25 (0, I, IAI)
               IF (IAI == - M) THEN
                 IF (IS == 89 .OR. IS == 159) THEN
                   IVAL = 0
                   CALL PLUT15 (6, I, 18, IVAL)
                   CALL PLUT25 (1, I, IDUM2)
                   CALL PLUT29 (4, NQ1, NQ2, 0, 0)
                 ELSE
                   CALL PLUT15 (1, I, 27, NINCL)
                 END IF
               END IF
             END DO
           END IF
        END DO
      END IF
C * ELIMINATE DELETED ATOMS AND DO RESET MODE 2 FOR DELETE ATOMS CASE
      IF (IS == 89 .OR. IS == 159) THEN
        L = IPR(69)
        DO I = ILPB, NATO
          CALL PLUT15 (-6, I, 18, IMULT)
          IF (IMULT > 0) THEN
            L = L + 1
            DO K = 1, 12
              RA(L * NP43 + K) = RA(I * NP43 + K)
            END DO
          END IF
        END DO
        IPR(37)  = L
        IPR(38)  = L
        IPR(39)  = L
        IPR(170) = 2
      END IF
      RETURN
      END SUBROUTINE PLUT09
 
      SUBROUTINE PLUT10
C * BOND DRAWING
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: IO
      INTEGER :: L0
      INTEGER :: L4
      INTEGER :: I1
      INTEGER :: IG
      INTEGER :: NN
      INTEGER :: NAB
      INTEGER :: III
      INTEGER :: IIN
      INTEGER :: IDF
      INTEGER :: IDL
      INTEGER :: IDR
      INTEGER :: NDL
      INTEGER :: NDR
      INTEGER :: NLIN
      INTEGER :: NDL1
      INTEGER :: NDR1
      INTEGER :: ILPB
      INTEGER :: IDL1
      INTEGER :: IDR1
      INTEGER :: IADR
      INTEGER :: ICOL
      INTEGER :: ISTK
      INTEGER :: JADR
      INTEGER :: KADR
      INTEGER :: JCOL
      INTEGER :: INDX1
      INTEGER :: INDX2
      INTEGER :: INDX3
      INTEGER :: NPROP
      INTEGER :: NINCL
      INTEGER :: NBOND
      INTEGER :: NBLNE
      INTEGER :: NATOT
      INTEGER :: KADR1
      INTEGER :: JRADR
      INTEGER :: JADR1
      INTEGER :: IUASU
      INTEGER :: IYANK
      INTEGER :: ISTK1
      INTEGER :: ISTK2
      INTEGER :: IRADR
      INTEGER :: ICOL1
      INTEGER :: IDASH
      INTEGER :: IDELD
      INTEGER :: IPR120
      INTEGER :: IPR151
      INTEGER :: IPR152
      REAL :: CT
      REAL :: ST
      REAL :: XG
      REAL :: YG
      REAL :: ZG
      REAL :: CPH
      REAL :: CSS
      REAL :: RBO
      REAL :: SNS
      REAL :: SPH
      REAL :: RAK2
      REAL :: RAK3
      REAL :: DELT
      REAL :: DIST
      REAL :: THETA
      REAL :: RAXAV
      REAL :: RAXPL
      REAL :: RAYAV
      REAL :: RAYPL
      REAL :: RAXPL1
      REAL :: RAYPL1
      REAL :: DELCOL
      REAL :: PAR145
      REAL :: WRICOL
      REAL, DIMENSION(3, 3) :: YUNK
C * BOND MODE:
      PAR145  = 0.0
      CPH     = 0.0
      SPH     = 0.0
      IDF     = 0
      IRADR   = 0
      JRADR   = 0
      INDX1   = 0
      INDX2   = 0
      INDX3   = 0
      IDL1    = 0
      NDL1    = 0
      IDR1    = 0
      NDR1    = 0
      ICOL    = 0
      JCOL    = 0
      ISTK2   = 0
      ISTK    = IPR(158) + IPR(40) * NP0
      N       = 0
      NAB     = IPR(37) - IPR(69)
C * GET NR OF ATOM ITEMS
      NATOT   = IPR(62)
      ILPB    = IPR(69) + 1
C * SET DEFAULT BOND PARAMETERS
      PAR(37) = 0
C * GET CROT PARAMETERS
      IPR151 = IPR(151)
      IPR152 = IPR(152)
      IF (IPR151 > 0) THEN
        IF (IPR(116) /= 0) IPR(336) = 0
        PAR145   = PAR(145)   * IPR(164)
        CPH      = COS (PAR145 / RGBL(6))
        SPH      = SIN (PAR145 / RGBL(6))
        IDF      = NATOT * NP0
        DELCOL   = IPR(153)
        WRICOL   = IPR(154)
        PAR(146) = 0.0
        IRADR    = IPR(157)
        JRADR    = IPR(167)
C * ESTABLISH ROTATION AXIS
        INDX1    = IPR(155)
        INDX2    = 2
        INDX3    = 3
        IF (INDX1 == 2) THEN
          INDX2  = 1
          INDX3  = 3
          SPH    = - SPH
        ELSE IF (INDX1 == 3) THEN
          INDX2  = 1
          INDX3  = 2
        END IF
      END IF
C * PURE STICK MODE DRAW BOXES FOR ISOLATED ATOMS
      IF (IPR(4) == 0 .OR. IPR(151) > 0) THEN
        CSS = COS (6.0 / RGBL(6))
        SNS = SIN (6.0 / RGBL(6))
        DO K = 1, NATOT
          IF (IPR(116) /= 0) THEN
            I = IPR(158) + K * NP0
            J = IPR(168) + K * NP0
            RA(J - 3) =  CSS * RA(I - 3) + SNS * RA(I - 1)
            RA(J - 2) =  RA(I - 2)
            RA(J - 1) = -SNS * RA(I - 3) + CSS * RA(I - 1)
            RA(J)     =  RA(I)
          END IF
C * CHECK FOR INCLUDED
          IO = MOD (K - ILPB, NAB) + ILPB
          CALL PLUT15 (-1, IO, 27, NINCL)
          IF (NINCL /= 0) THEN
            CALL PLUT14 (-1, K, NPROP, IUASU, XYZK(1), XYZK(2),
     1                   XYZK(3), XYZK(4))
            IF (XYZK(4) < 0.0 .OR. XYZK(4) > 999.9) CYCLE
C * CHECK FOR ISOLATED ATOM STATUS
            IF (IO >= ILPB) THEN
              CALL PLUT15 (-4, IO, 33, NBOND)
            ELSE
              NBOND = 3
            END IF
C * GENERATE DIAMOND TO REPRESENT ISOLATED ATOM
            IF (NBOND == 0) THEN
              I = K * NP0 + IPR(158)
              CALL PLUT31 (I - NP0, -1.0)
              IF (IPR(151) > 0) RA(I) = 100000.0
            END IF
          END IF
        END DO
      END IF
C * LOOP OVER (ACTIVE) BONDS
C * INTERRUPT INTERCEPT
   10 IF (IPR(151) /= 0 .AND. IGBL(25) == 1) THEN
        XG = 0.0
        YG = 0.0
        ZG = 0.0
        IG = 9
        CALL GGIP (XG, YG, ZG, IG)
        IF (IG > 0) CC = .TRUE.
      END IF
      IF (CC) THEN
        IF (IPR(116) == 0) THEN
          IPR(346) =   IABS (IPR(346))
        ELSE
          IPR(346) = - IABS (IPR(346))
        END IF
        IPR(4) = IABS (IPR(4))
        GO TO 50
      END IF
      IPR(56) = 0
      IADR    = IPR(79)
C * LOOP OVER BONDS
   20 IPR(56) = IPR(56) + 1
      IF (IPR(151) <= 0) THEN
C * INTERRUPT INTERCEPT
        IF (CC) THEN
          IPR(346) = IABS (IPR(346))
          GO TO 50
        END IF
      END IF
      IF (IPR(56) > IPR(97)) THEN
        IPR151 = IPR151 - 1
        IF (IPR151 <= 0) THEN
          GO TO 40
        ELSE
          IF (CC) THEN
            IPR(346) = IABS (IPR(346))
            GO TO 50
          END IF
          PAR(146) = PAR(146) + PAR145
          JADR     = IRADR
          KADR     = JADR  + IDF
          JADR1    = JRADR
          KADR1    = JADR1 + IDF
          DO I = 1, NATOT
            RA(JADR + NP0)  = RA(KADR + NP0)
            RA(JADR + INDX1 + NP0 - 4) = RA(KADR + INDX1 + NP0 - 4)
            RAK2                       = RA(KADR + INDX2 + NP0 - 4)
            RAK3                       = RA(KADR + INDX3 + NP0 - 4)
            RA(JADR + INDX2 + NP0 - 4) =   CPH * RAK2 + SPH * RAK3
            RA(JADR + INDX3 + NP0 - 4) = - SPH * RAK2 + CPH * RAK3
            IF (IPR(116) /= 0) THEN
              RA(JADR1 + INDX1 + NP0 - 4) = RA(KADR1 + INDX1 + NP0 - 4)
              RA(JADR1 + NP0)  = RA(KADR1 + NP0)
              RAK2             = RA(KADR1 + INDX2 + NP0 - 4)
              RAK3             = RA(KADR1 + INDX3 + NP0 - 4)
              RA(JADR1 + INDX2 + NP0 - 4) =   CPH * RAK2 + SPH * RAK3
              RA(JADR1 + INDX3 + NP0 - 4) = - SPH * RAK2 + CPH * RAK3
            END IF
 
C * ROTATE DIAMONDS
            IF (RA(KADR + NP0) > 9999.0) THEN
              CALL PLUT31 (KADR, DELCOL)
              IF (IPR(116) /= 0) WRICOL = IPR(144)
              CALL PLUT31 (JADR, WRICOL)
              IF (IPR(116) /= 0) THEN
                CALL PLUT31 (KADR1, DELCOL)
                CALL PLUT31 (JADR1, FLOAT (IPR(143)))
              END IF
            END IF
            JADR    = JADR + NP0
            KADR    = KADR + NP0
            IF (IPR(116) /= 0) THEN
              JADR1 = JADR1 + NP0
              KADR1 = KADR1 + NP0
            END IF
          END DO
          IRADR = IRADR + IDF
          JRADR = JRADR + IDF
          IDF   = - IDF
          GO TO 10
        END IF
      END IF
C * CROT DELETE
      IF (IPR151 > 0) THEN
        IADR = IADR - 4
        IDL  = IRADR + NINT (RA(IADR + 1) * NP0)
        NDL  = IRADR + NINT (RA(IADR + 2) * NP0)
        IDR  = IDL   + IDF
        NDR  = NDL   + IDF
        IF (IPR(116) /= 0) THEN
          IDL1 = JRADR + NINT (RA(IADR + 1) * NP0)
          NDL1 = JRADR + NINT (RA(IADR + 2) * NP0)
          IDR1 = IDL1 + IDF
          NDR1 = NDL1 + IDF
        END IF
        IF (IPR151 < IPR152) THEN
          CALL GGIP (0.0, DELCOL, 0.0, 0)
          CALL GGIP (RA(IDL - 3), RA(IDL - 2), 0.0, 3)
          RAXPL = RA(NDL - 3)
          RAYPL = RA(NDL - 2)
          IF (IPR(336) == 1) THEN
            RAXAV = RA(IDL - 3) + (RAXPL - RA(IDL - 3)) / 2
            RAYAV = RA(IDL - 2) + (RAYPL - RA(IDL - 2)) / 2
            CALL GGIP (RAXAV, RAYAV, 0.0, 2)
          END IF
          CALL GGIP (RAXPL, RAYPL, 0.0, 2)
          IF (IPR(116) /= 0) THEN
            CALL GGIP (RA(IDL1 - 3), RA(IDL1 - 2), 0.0, 3)
            RAXPL1 = RA(NDL1 - 3)
            RAYPL1 = RA(NDL1 - 2)
            CALL GGIP (RAXPL1, RAYPL1, 0.0, 2)
          END IF
        END IF
C * CROT DRAW
        CALL GGIP (RA(IDR - 3), RA(IDR - 2), 0.0, 3)
        RAXPL = RA(NDR - 3)
        RAYPL = RA(NDR - 2)
        IF (IPR(336) == 0) THEN
          CALL GGIP (0.0, WRICOL, 0.0, 0)
        ELSE
          ICOL = MOD (IABS (INT (RA(IADR + 4))), 1024)
          JCOL = MOD(ICOL, 32)
          IF (JCOL > 0)  JCOL = IACL(JCOL)
          IF (JCOL == 0 .OR. JCOL == 17) JCOL = IPR(19)
          ICOL = ICOL / 32
          ICOL = IPR(19)
          IF (ICOL > 0)  ICOL = IACL(ICOL)
          IF (ICOL == 0 .OR. ICOL == 17) ICOL = IPR(19)
          CALL GGIP (0.0, FLOAT (ICOL), 0.0, 0)
          RAXAV = RA(IDR - 3) + (RAXPL - RA(IDR - 3)) / 2
          RAYAV = RA(IDR - 2) + (RAYPL - RA(IDR - 2)) / 2
          CALL GGIP (RAXAV, RAYAV, 0.0, 2)
          CALL GGIP (0.0, FLOAT (JCOL), 0.0, 0)
        END IF
        IF (IPR(116) /= 0) CALL GGIP (0.0, FLOAT (IPR(144)), 0.0, 0)
        CALL GGIP (RAXPL, RAYPL, 0.0, 2)
        IF (IPR(116) /= 0) THEN
          CALL GGIP (RA(IDR1 - 3), RA(IDR1 - 2), 0.0, 3)
          RAXPL1 = RA(NDR1 - 3)
          RAYPL1 = RA(NDR1 - 2)
          CALL GGIP (0.0, FLOAT (IPR(143)), 0.0, 0)
          CALL GGIP (RAXPL1, RAYPL1, 0.0, 2)
        END IF
        GO TO 20
      END IF
C * GET BOND CHARACTERISTICS
      IPR(67) = 0
      CALL PLUT16 (IPR(56), I1, I, N, RBO, NBLNE)
      IF (IPR(56) > IPR(68)) THEN
        IPR120 = IPR(120)
      ELSE
        IPR120 = 1
      END IF
C * CALL EXIT/STOP
      IF (I == 0) CALL GEN127 (' KAN NIET GOTO 20')
      IF (NBLNE < 0) THEN
        NBLNE = IABS (NBLNE)
        IDASH = 1
      ELSE
        IDASH = 0
      END IF
      PAR(37) = RBO * PAR(24)
      NN      = I
      IPR(67) = 5
C * OUTPUT BONDS TO POVRAY FILE
      IF (IPR(82) /= 0 .AND. IPR(116) <= 0) THEN
        III = IPR(125) + I * 4
        IIN = IPR(125) + N * 4
        IF (IPR(4) == 0) THEN
          IF (I <= IPR(69)) THEN
            CALL GEN040 (I, NQ1, IYANK)
          ELSE
            CALL PLUT25 (1, I, IYANK)
          END IF
          IF (N <= IPR(69)) THEN
            CALL GEN040 (N, NQ2, IYANK)
          ELSE
            CALL PLUT25 (2, N, IYANK)
          END IF
          IF (IPR(10) == 1) THEN
            WRITE (LU61, 99999, IOSTAT = IOST)
     1        NQ1, NQ2, RA(III - 2) - PAR(67),
     2        RA(III - 1) - PAR(68), -RA(III) + PAR(69),
     3        RA(IIN - 2) - PAR(67),  RA(IIN - 1) - PAR(68),
     4        -RA(IIN) + PAR(69), MAX (RBO, 0.05)
          END IF
        END IF
      END IF
      IF (IPR(4) > 0) THEN
C * CHECK FOR INTERRUPT
        IF (IGBL(25) * IGBL(32) == 1) THEN
          XG = 0.0
          YG = 0.0
          ZG = 0.0
          IG = 9
          CALL GGIP (XG, YG, ZG, IG)
          IF (IG == 3) THEN
            IPR(45) = 1
            GO TO 50
          END IF
        END IF
C * FIND OBSCURATIONS FOR THIS BOND (WITH PSEUDO ATOMS AS END-POINTS)
        CALL PLUT18 (IPR(40) + 1, IPR(40) + 2)
C * NOW WE CAN DRAW THE BOND I TO N, UNLESS FOUND TO BE FULLY OBSCURED
        IF (IPR(78) < 0)  GO TO 20
      ELSE
        IPR(78) = 0
      END IF
C * BOND MODE
      IF (NBLNE > 1) THEN
        DELT = RGBL(5) / (2 * FLOAT (NBLNE - 1))
      ELSE
        DELT = 0.0
      END IF
C * STICK MODE
      IF (IPR(4) == 0) THEN
C * CHECK FOR COLOR ON
        IF (IPR(346) == 1) THEN
          NBLNE = 2
          IF (IPR(477) == 0 .AND. IPR(120) /= 0) THEN
            ICOL = IACL(IPR(120) / 32)
            IF (ICOL == 17) ICOL = IPR(19)
            JCOL = IACL(MOD (IPR(120), 32))
            IF (JCOL == 17) JCOL = IPR(19)
          ELSE
            ICOL = IPR(120)
            JCOL = IPR(120)
          END IF
        END IF
      END IF
      ZU(4) = 0.0
      ZU(5) = 0.0
      ZU(6) = 1.0
C * SET UP COORD SYSTEM FOR THE SEMI-CIRCLE CROSS SECTION OF BOND
      CALL GEN008 (ZU(4), ZU(7), ZU(1), 1)
      CALL GEN008 (ZU(7), ZU(1), ZU(4), 1)
      DIST  = 0
      L0    = - 2
      IDELD = 2
      ISTK1 = ISTK
      IF (IDASH == 1) THEN
        ISTK1 = ISTK + 2 * NP0
        ISTK2 = ISTK + 4 * NP0
        DO L = 1, 3
          L4 = NP0 + L - 4
          DIST = DIST + (RA(ISTK + NP0 + L4)
     1         - RA(ISTK + L4)) ** 2
        END DO
        IDELD = NINT (3.0 * SQRT (DIST) / PAR(24)) * 2 + 1
        DO L = 1, 3
          L4 = NP0 + L - 4
          RA(ISTK2 + L4) = (RA(ISTK + NP0 + L4)
     1                   - RA(ISTK + L4)) / IDELD
        END DO
        RA(ISTK2 + NP0) = (RA(ISTK + 2 * NP0)
     1                  - RA(ISTK + NP0)) / IDELD
      END IF
   30 L0 = L0 + 2
      IF (L0 >= IDELD) GO TO 20
      IF (IDASH == 1) THEN
        DO L = 1, 4
          L4 = NP0 + L - 4
          RA(ISTK1 + L4)       = RA(ISTK  + L4)
     1                         + RA(ISTK2 + L4) *  L0
          RA(ISTK1 + NP0 + L4) = RA(ISTK  + L4)
     1                         + RA(ISTK2 + L4) * (L0 + 1)
        END DO
      END IF
      IF (IPR(10) == 1 .AND. IPR(4) /= 0) THEN
        IF (I <= IPR(69)) THEN
          CALL GEN040 (I, NQ1, IYANK)
        ELSE
          CALL PLUT25 (1, I, IYANK)
        END IF
        IF (N <= IPR(69)) THEN
          CALL GEN040 (N, NQ2, IYANK)
        ELSE
          CALL PLUT25 (2, N, IYANK)
        END IF
        WRITE (LU61, 99999, IOSTAT = IOST)  NQ1, NQ2,
     1    RA(ISTK1 + NP0 - 3) / PAR(24),
     2    RA(ISTK1 + NP0 - 2) / PAR(24),
     3   -RA(ISTK1 + NP0 - 1) / PAR(24) - PAR(66) + PAR(69),
     4    RA(ISTK1 + 2 * NP0 - 3) / PAR(24),
     5    RA(ISTK1 + 2 * NP0 - 2) / PAR(24),
     6   -RA(ISTK1 + 2 * NP0 - 1) / PAR(24) - PAR(66) + PAR(69),
     7    MAX (RBO, 0.05)
      END IF
      NN    = I
      THETA = 0.0
      NLIN  = 0
C * SET UP POINTS ON SEMICIRCLE AT CENTRES OF ATOMS
      DO
        CT = COS (THETA)
        ST = SIN (THETA)
        DO L = 1, 3
          L4 = NP0 + L - 4
          XYZPL(L)     = (ZU(L) * CT + ZU(3 + L) * ST)
     1                 * RA(ISTK1 + NP0) + RA(ISTK1 + L4)
          XYZPL(L + 3) = (ZU(L) * CT + ZU(3 + L) * ST)
     1                 * RA(ISTK1 + 2 * NP0) + RA(ISTK1 + NP0 + L4)
        END DO
C * START PLOTTING THE LINE XSTART-XEND
        NLIN = NLIN + 1
C * DRAW THIS LINE, TEST FOR OBSCURATION OF THIS BOND BY ATOMS/BONDS
        IF (IPR(4) == 0) THEN
          IF (IPR(346) == 1) THEN
            IF (NN > 0) THEN
              ICOL1 = ICOL
            ELSE
              ICOL1 = JCOL
            END IF
            IF (ICOL1 == 0 .OR. ICOL1 > 15) ICOL1 = IPR(19)
            CALL GGIP (0.0, FLOAT (ICOL1), 0.0, 0)
          END IF
        ELSE
          IF (IPR(477) /= 0) THEN
            ICOL1 = IPR120
            IF (ICOL1 <= 0 .OR. ICOL1 > 15) ICOL1 = IPR(19)
            CALL GGIP (0.0, FLOAT (ICOL1), 0.0, 0)
          END IF
        END IF
        IF (IPR(10) <= 0) CALL PLUT19 (0, NN)
        IF (NLIN >= NBLNE)  GO TO 30
C * DRAW NEXT LINE IN REVERSE DIRECTION
        NN    = - NN
        THETA = THETA + DELT
      END DO
   40 IF (IPR(82) /= 0 .AND. IPR(116) <= 0) THEN
        IF (IPR(10) == 1) THEN
          WRITE (LU61, 99998, IOSTAT = IOST) PAR(24) * 0.16
          IPR(10) = 0
        ELSE IF (IPR(10) == 2) THEN
          IPR(10) = 0
        END IF
      END IF
C * APPLY CROT TO MATRIX
   50 IF (PAR(146) /= 0) THEN
        CALL GEN043 (IPR(155), A, PAR(146) / RGBL(6))
        CALL GEN004 (A, R, YUNK)
        CALL GEN052 (YUNK, R)
        PAR(146) = 0
        IPR(151) = -1
      END IF
      RETURN
99999 FORMAT ('// bond ', A, 1X, A, ' 1', /,
     1        10X, 'cylinder { ', /, 15X, '<', F9.4, ',', F9.4, ',',
     2        F9.4, ' > , < ', F9.4, ',', F9.4, ',', F9.4, ' >,', /,
     3        F7.3, /,
     4        15X, 'texture { pigment { color color_bond }', /,
     5        15X, 'finish { finish_all } } }')
99998 FORMAT ('scale', F7.3, /, 'rotate y*180', /, 'translate y*-0.25',
     1 /, '}', /, '// End-of-Plot')
      END SUBROUTINE PLUT10
 
      SUBROUTINE PLUT11
C * SUBROUTINE DRAWS THE VARIOUS PROJECTION SPHERE OUTLINES,
C * ATOM-ATOM AND ATOM-BOND INTERSECTIONS.
      USE parameters
      USE atomdata
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: MP
      INTEGER :: IG
      INTEGER :: IO
      INTEGER :: NJ
      INTEGER :: NL
      INTEGER :: NN
      INTEGER :: NRS
      INTEGER :: IVL
      INTEGER :: NAB
      INTEGER :: NEL
      INTEGER :: NPNT
      INTEGER :: NPRC
      INTEGER :: NPRH
      INTEGER :: MODE
      INTEGER :: IVAL
      INTEGER :: IPOP
      INTEGER :: ILPB
      INTEGER :: IDUM
      INTEGER :: IASU
      INTEGER :: NPRV
      INTEGER :: NTRCE
      INTEGER :: NPRVM
      INTEGER :: NPROP
      INTEGER :: NPRHM
      INTEGER :: NINCL
      INTEGER :: ICOL0
      INTEGER :: ISEGM
      INTEGER :: NATOT
      INTEGER :: NDOTS
      INTEGER :: ISHADE
      REAL :: PI
      REAL :: XG
      REAL :: YG
      REAL :: ZG
      REAL :: RJB
      REAL :: RJK
      REAL :: RKK
      REAL :: RIN
      REAL :: PHI
      REAL :: ANG
      REAL :: DKJ
      REAL :: CHI
      REAL :: DIN
      REAL :: DMG
      REAL :: DSQ
      REAL :: SCHI
      REAL :: CDTH
      REAL :: XLNG
      REAL :: XPL1
      REAL :: XPL2
      REAL :: XPL3
      REAL :: DMARG
      REAL :: PDTHH
      REAL :: PDTHV
      REAL :: GEN013
      NAB   = IPR(37) - IPR(69)
      NATOT = IPR(62)
      ILPB  = IPR(69) + 1
C * NO SPHERE PLOTTING IN STICK-MODE
C * NEGATIVE IPR(4) : CPK + STICK
      IF (IPR(4) /= 0) THEN
C * LOOP OVER ALL ATOMS K IN PLOT ARRAY
        DO 30 K = ILPB, NATOT
          IO = MOD(K - ILPB, NAB) + ILPB
          CALL PLUT15 (-1, IO, 27, NINCL)
          IF (NINCL /= 0) THEN
C * CHECK FOR INTERRUPT
            IF (IGBL(25) * IGBL(32) == 1) THEN
              XG = 0.0
              YG = 0.0
              ZG = 0.0
              IG = 9
              CALL GGIP (XG, YG, ZG, IG)
              IF (IG == 3) THEN
                IPR(45) = 1
                GO TO 40
              END IF
            END IF
            IF (K <= IPR(37)) THEN
              IF (IPR(130) == 0) THEN
                IVAL = 1
                CALL PLUT15 (1, K, 45, IVAL)
              END IF
            END IF
C * RESET PSEUDO ATOM STACK
            IPR(67) = 0
C * DRAW THE CIRCLE REPRESENTING THE SPHERE PROJECTED ON THE XY-PLANE.
C * GET X, Y, Z AND R DATA FOR ATOM K AND STORE IN XYZK(1:4).
            CALL PLUT14 (-1, K, IASU, NPROP, XYZK(1), XYZK(2), XYZK(3),
     1                                 XYZK(4))
C * EXCLUDE ATOMS WITH NEGATIVE RADIUS OR DUPLICATE ATOMS
            IF (XYZK(4) < 0 .OR. XYZK(4) > 999.9)  GO TO 30
C * GET LIST OF ATOMS AND BONDS WHICH OBSCURE ATOM K
            CALL PLUT18 (K, 0)
C * DO NOT DRAW TOTALLY OBSCURED ATOMS
            IF (IPR(78) < 0) THEN
C * REGISTER FULLY OVERLAPPED ATOMS FOR NOT LABELLING
              IF (K <= IPR(37)) THEN
                IVAL = 0
                CALL PLUT15 (1, K, 45, IVAL)
              END IF
            ELSE
C * GET SERIAL NUMBER OF ELEMENT TYPE IN ARRAY IEN FOR THIS ATOM
              NEL    = INT(RA(IO * NP43 + 7) / 64000) + 1
              ISHADE = 0
              NPRC   = 1
              NPRH   = 0
              NPRV   = 0
              NPRHM  = 0
              NPRVM  = 0
              NDOTS  = 0
              ISEGM  = 0
              PAR(7) = 0.0
              PAR(8) = 0.0
C * DETERMINE COLOR SETTINGS
              IF (IPR(346) == 1) THEN
                ISHADE = 1
                PAR(6) = PAR(23)
                IF (IPR(477) == 0) THEN
                  ICOL0 = IACL(NEL)
                  IF (ICOL0 > 8) ICOL0 = 0
                ELSE IF (IPR(477) < 0) THEN
                  CALL PLUT15 (-6, IO, 5, NRS)
                  IF (NRS > 0 .AND. NRS <= 8) THEN
                    ICOL0 = NCRS(NRS)
                  ELSE
                    ICOL0 = 0
                  END IF
                ELSE
C * ARU-SPECIFIED COLOR
                  CALL GEN048 (-5, NPROP, 1, ICOL0)
                END IF
                IF (ICOL0 == 0 .OR. ICOL0 > 16) THEN
                  IF (IABS (IPR(477)) == 1) THEN
                    ICOL0 = IPR(19)
                  ELSE
                    ISHADE = 0
                  END IF
                END IF
                IPR(88) = ICOL0
              END IF
              PAR(130) = 0.0
              PAR(131) = 0.0
C * DETERMINE PARAMETERS FOR B&W COLOR
              IF (IPR(345) == 1) THEN
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                IF (IPR(478) == 0) THEN
                  IF (IPR(461) == 0) THEN
                    IPR(162) = IBCL(NEL)
                  ELSE
                    IPR(162) = IPR(139)
                  END IF
                ELSE IF (IPR(478) < 0) THEN
                  CALL PLUT15 (-6, IO, 5, NRS)
                  IF (NRS > 0 .AND. NRS <= 16) THEN
                    IPR(162) = NPRS(NRS)
                  ELSE
                    IPR(162) = 0
                  END IF
                ELSE
C * ARU SPECIFIC
                  CALL GEN048 (-5, NPROP, 6, IPR(162))
                END IF
              ELSE
                IPR(162) = IPR(139)
              END IF
C * CONTOUR
              IF (IPR(162) == 1) THEN
                NPRC   = NINT (IPR(8) * PAR(24) / 4) + 1
                ISHADE = 0
              END IF
C * NET
              IF (IPR(162) == 2) THEN
                IF (IPR(4) == 3) THEN
                  NPRH = IPR(85) + 10
                  NPRV = IPR(86) + 10
                ELSE
                  NPRH = IPR(85)
                  NPRV = IPR(86)
                END IF
                NPRH = NINT (NPRH * PAR(24) / 4)
                NPRV = NINT (NPRV * PAR(24) / 4)
                ISHADE = 0
C * CROSS
              ELSE IF (IPR(162) == 7) THEN
                NPRH   = 3
                NPRV   = 3
                NPRHM  = 2
                NPRVM  = 2
                ISHADE = 0
C * GLOBE
              ELSE IF (IPR(162) == 8) THEN
                IF (IPR(4) == 3) THEN
                  NPRC = IPR(112) * 2
                  NPRV = IPR(132) * 2
                ELSE
                  NPRC = IPR(112)
                  NPRV = IPR(132)
                END IF
                NPRC     = NINT (NPRC * PAR(24) / 4)
                NPRV     = NINT (NPRV * PAR(24) / 4)
                PAR(130) = -45.0
                PAR(131) = -35.0
                ISHADE   = 0
C * SET SPECIAL SHADE IN SPOT/GLOBE MODE
                IF (IPR(96) == 1) THEN
                  ISHADE = 1
                  PAR(6) = 0.075
                  PAR(7) = 145.0
                  PAR(8) = -55.0
                END IF
C * PARAL
              ELSE IF (IPR(162) == 9) THEN
                NPRC     = NINT (IPR(112) * PAR(24) / 4)
                NPRV     = 0
                ISHADE   = 0
                PAR(130) = -45.0
                PAR(131) = -35.0
C * MERID
              ELSE IF (IPR(162) == 10) THEN
                NPRC     = 0
                NPRV     = NINT (IPR(132) * PAR(24) / 4)
                ISHADE   = 0
                PAR(130) = -45.0
                PAR(131) = -35.0
              END IF
C * SHADE
              IF (IPR(162) == 3) THEN
                ISHADE = 1
                PAR(6) = PAR(134)
                PAR(7) = PAR(135)
                PAR(8) = PAR(136)
C * HORIZONTAL
              ELSE IF (IPR(162) == 11) THEN
                ISHADE = 1
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                PAR(8) = 0.0
C * VERTICAL
              ELSE IF (IPR(162) == 12) THEN
                ISHADE = 1
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                PAR(8) = 90.0
C * MESH
              ELSE IF (IPR(162) == 13) THEN
                ISHADE = 2
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                PAR(8) = 0.0
C * DIAGONAL
              ELSE IF (IPR(162) == 14) THEN
                ISHADE = 1
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                PAR(8) = -45.0
C * SLANT
              ELSE IF (IPR(162) == 15) THEN
                ISHADE = 1
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                PAR(8) = 45.0
C * TEXTILE
              ELSE IF (IPR(162) == 16) THEN
                ISHADE = 2
                PAR(6) = 2.0 * XYZK(4) / (IPR(54) + 1)
                PAR(8) = -45.0
C * BLACK
              ELSE IF (IPR(162) == 6 .AND. NEL /= 1) THEN
                ISHADE = 1
                PAR(6) = PAR(23)
              END IF
C * SEGMENT
              IF (IPR(162) == 4) THEN
                ISEGM  = 1
                NPRC   = 3
                ISHADE = 0
              END IF
C * DOTS
              IF (IPR(162) == 5) THEN
                NDOTS  = 1
                ISHADE = 0
              END IF
C * DETERMINE NET PARAMETERS FOR THIS ATOM
C * BUT NO NET FOR H-ATOMS
              IF (NEL == 1) THEN
                IF (IPR(162) == 0) THEN
                  NPRH  = 0
                  NPRV  = 0
                  NPRC  = 0
                  ISEGM = 0
                  NDOTS = 0
                END IF
              END IF
              IF (NPRH > 0) THEN
                PDTHH = 180.0 / (NPRH * RGBL(6))
              ELSE
                PDTHH = 0.0
              END IF
              IF (NPRV > 0) THEN
                PDTHV = 180.0 / (NPRV * RGBL(6))
              ELSE
                PDTHV = 0.0
              END IF
C * DETERMINE CONTOUR PARAMETERS
              IF (NPRC > 0) THEN
                CDTH = 90.0 / (NPRC * RGBL(6))
              ELSE
                CDTH =  0.0
              END IF
C * HANDLE SHADE/COLOR OPTION FIRST (IN VIEW OF WET INKING PROBLEMS)
              IF (IPR(346) > 0 .OR. NEL /= 1 .OR.
     1           IABS (IPR(4)) >= 3) THEN
                IF (ISHADE > 0 .AND. IPR(78) >= 0) THEN
                  CALL PLUT36 (K, ISHADE)
                END IF
              END IF
C * DOTS
              IF (NDOTS > 0) THEN
                NPNT = NINT (IPR(124) * RADR(NEL, 1)**2)
C * SELECT COLOR
                IF (IPR(346) == 1 .AND. IPR(139) == 5) THEN
                  CALL GGIP (0.0, FLOAT (ICOL0), 0.0, 0)
                END IF
                PI    = RGBL(5) / 2.0
                IDUM  = -1
                DO J = 1, NPNT
                  PHI  = GEN013 (IDUM) * 2 * PI
                  CHI  = SQRT (GEN013 (IDUM) * GEN013 (IDUM)) *
     1                   (1.0 + 0.99 * COS ((PHI - PI) / 2)) / 2
                  CHI  = ATAN (SQRT (1 - (CHI**2)) / CHI)
                  SCHI = SIN(CHI) * XYZK(4)
                  XPL1 = SCHI * COS (PHI)
                  XPL2 = SCHI * SIN (PHI)
                  XPL3 = SQRT (ABS (XYZK(4)**2 - XPL1**2 - XPL2**2))
                  XYZPL(1) = XYZK(1) + XPL1
                  XYZPL(2) = XYZK(2) + XPL2
                  XYZPL(3) = XYZK(3) + XPL3
                  XYZPL(4) = XYZPL(1)
                  XYZPL(5) = XYZPL(2)
                  XYZPL(6) = XYZPL(3)
C * SELECT COLOR
                  IF (IPR(346) == 1 .AND. IPR(139) == 0) THEN
                    CALL GGIP (0.0, FLOAT (ICOL0), 0.0, 0)
                  END IF
C * TEST FOR OBSCURATION OF THIS POINT
                  NN = 1
                  CALL PLUT19 (K, NN)
                END DO
              END IF
              DO I = 1, 4
                PAR(70 + I) = XYZK(I)
              END DO
C * DETERMINE NUMBER OF SEGMENTS PER 180 DEGREES
              MP = MAX (NINT (PAR(125) * SQRT (PAR(74) * 10.0)), 5)
              IF (IPR(78) == 0) THEN
                IPR(91) = MP
              ELSE
                IPR(91) = MAX (NINT (RGBL(5) * PAR(74) * IPR(111) /
     1                    (4 * PAR(5)) + 1), 5)
              END IF
              PAR(55) = RGBL(5) / FLOAT (IPR(91) * 2)
              PAR(56) = RGBL(5) / FLOAT (MP * 2)
C * TEST THE CIRCLE AS THE SEQUENCE OF NPP LINES
              IF (ABS(PAR(130)) + ABS(PAR(131)) < 0.001) THEN
                NTRCE = 0
              ELSE
                NTRCE = - NPRC
              END IF
              IPR(87) = 2
              PAR(57) = 0.0
              CALL GEN074 (ZU, 2, 15, 0.0)
C * HANDLE SEGMENT PLOT (EXCLUDING H-ATOMS)
              IF (ISEGM == 1 .AND. NEL > 1) THEN
                PAR(57) = 180.0 / RGBL(6)
                IPR(114) = INT (RGBL(5) / (3.0 * PAR(55)))
              END IF
C * CONTOUR LOOP
              DO WHILE (NTRCE < NPRC)
                NTRCE = NTRCE + 1
                IF (IPR(346) == 1)
     1            CALL GGIP (0.0, FLOAT (ICOL0), 0.0, 0)
                PAR(74) = XYZK(4) * COS (NTRCE * CDTH)
                ZU(10)  = 1.0
                ZU(11)  = 0.0
                ZU(12)  = 0.0
                ZU(13)  = 0.0
                ZU(14)  = 1.0
                ZU(15)  = 0.0
                ANG     = PAR(130)
C * GLOBE/PARALLEL OPTION
                IF (IPR(162) == 8 .OR. IPR(162) == 9) THEN
                  ANG = ANG + 90.0
                END IF
                CALL GEN043 (1, A, ANG / RGBL(6))
                CALL GEN002 (1, A, ZU(10), ZU(4), XLNG)
                CALL GEN002 (1, A, ZU(13), ZU(7), XLNG)
C * ROTATE CONTOUR-LEVEL VECTOR
                ZU(13) = 0.0
                ZU(14) = 0.0
                ZU(15) = XYZK(4) * SIN (NTRCE * CDTH)
                CALL GEN002 (1, A, ZU(13), ZU(10), XLNG)
                CALL GEN043 (2, A, PAR(131) / RGBL(6))
                CALL GEN002 (1, A, ZU(4), ZU(1), XLNG)
                CALL GEN002 (1, A, ZU(7), ZU(4), XLNG)
                CALL GEN002 (1, A, ZU(10), ZU(7), XLNG)
                DO I = 1, 3
                  PAR(70 + I) = XYZK(I) + ZU(6 + I)
                END DO
                CALL PLUT19 (0, 0)
              END DO
C * DRAW NET ON ATOM SURFACE
              IPR(114) = 0
              DO I = 1, 4
                PAR(70 + I)  = XYZK(I)
              END DO
              IPR(87) = 1
              DO WHILE (NPRV > NPRVM)
                NPRV = NPRV - 1
C * AVOID DOUBLE CIRCLE PLOT
                IF (NPRV == 0) THEN
                  IF (ABS (PAR(130)) + ABS (PAR(131)) < 0.001) EXIT
                END IF
                IF (IPR(346) == 1) THEN
                  CALL GGIP (0.0, FLOAT (ICOL0), 0.0, 0)
                END IF
                ANG    = NPRV * PDTHV - PAR(131) / RGBL(6)
                ZU(10) = COS (ANG)
                ZU(11) = 0.0
                ZU(12) = SIN (ANG)
                ZU(13) = 0.0
                ZU(14) = 1.0
                ZU(15) = 0.0
                CALL GEN043 (1, A, PAR(130) / RGBL(6))
                CALL GEN002 (1, A, ZU(10), ZU(4), XLNG)
                CALL GEN002 (1, A, ZU(13), ZU(7), XLNG)
                CALL GEN043 (2, A, PAR(131) / RGBL(6))
                CALL GEN002 (1, A, ZU(4), ZU(1), XLNG)
                CALL GEN002 (1, A, ZU(7), ZU(4), XLNG)
C * CALCULATE ANGLE VALUE FOR INTERSECTION WITH XY-PLANE
                CALL GEN008 (ZU(1), ZU(4), ZU(7), 1)
                ZU(10) = 0.0
                ZU(11) = 0.0
                ZU(12) = 1.0
                CALL GEN008 (ZU(7), ZU(10), ZU(13), 1)
                PAR(57) = ACOS (ZU(1) * ZU(13) + ZU(2) * ZU(14)
     1                  + ZU(3) * ZU(15)) - RGBL(5) / 2.0
                CALL PLUT19 (0, 0)
              END DO
              IPR(87) = 1
              DO WHILE (NPRH > NPRHM)
                NPRH = NPRH - 1
                IF (NPRH == 0) THEN
                  IF (ABS (PAR(130)) + ABS (PAR(131)) < 0.001) EXIT
                END IF
                IF (IPR(346) == 1) THEN
                  CALL GGIP (0.0, FLOAT (ICOL0), 0.0, 0)
                END IF
                ANG = NPRH * PDTHH + PAR(130) / RGBL(6)
                ZU(10) = 1.0
                ZU(11) = 0.0
                ZU(12) = 0.0
                ZU(13) = 0.0
                ZU(14) = COS (ANG)
                ZU(15) = SIN (ANG)
                CALL GEN043 (1, A, PAR(130) / RGBL(6))
                CALL GEN002 (1, A, ZU(10), ZU(4), XLNG)
                CALL GEN002 (1, A, ZU(13), ZU(7), XLNG)
                CALL GEN043 (2, A, PAR(131) / RGBL(6))
                CALL GEN002 (1, A, ZU(4), ZU(1), XLNG)
                CALL GEN002 (1, A, ZU(7), ZU(4), XLNG)
C * CALCULATE ANGLE VALUE FOR INTERSECTION WITH XY-PLANE
                CALL GEN008 (ZU(1), ZU(4), ZU(7), 1)
                ZU(10) = 0.0
                ZU(11) = 0.0
                ZU(12) = 1.0
                CALL GEN008 (ZU(7), ZU(10), ZU(13), 1)
                PAR(57) = ACOS (ZU(1) * ZU(13) + ZU(2) * ZU(14)
     1                  + ZU(3) * ZU(15)) - RGBL(5) / 2.0
                CALL PLUT19 (0, 0)
              END DO
C * SELECT DEFAULT PEN
              IF (IPR(346) > 0) THEN
                IF (IPR(139) == 1 .AND. ICOL0 /= 0) THEN
                  CALL GGIP (0.0, FLOAT (ICOL0), 0.0, 0)
                ELSE
                  CALL GGIP (0.0, FLOAT (IPR(19)), 0.0, 0)
                END IF
              END IF
C * NOW WE CAN DRAW THE EQUATORIAL CIRCLE FOR ATOM K
              DO I = 1, 4
                PAR(70 + I) = XYZK(I)
              END DO
              IPR(87) = 2
              PAR(57) = 0.0
              CALL GEN074 (ZU, 1, 15, 0.0)
              ZU(1) = 1.0
              ZU(5) = 1.0
C * CIRCLE LOOP WITH OBSCURATION TEST
              IPR(129) = 0
              CALL PLUT19 (0, 0)
              IF (IPR(129) == 0) THEN
C * REGISTER FULLY OVERLAPPED ATOMS FOR NOT LABELLING
                IF (K <= IPR(37)) THEN
                  IVL = 0
                  CALL PLUT15 (1, K, 45, IVL)
                END IF
              END IF
C * DRAW CIRCLES SHOWING THE SECTION OF OVERLAP OF SPHERES.
              MODE = 0
   10         MODE = MODE - 1
              IF (MODE + IPR(78) < 0) GO TO 30
              IPOP = IPR(66) + MODE * 13
C * GET BONDS OUT OF ATOM K WITH PSEUDO ATOM ENDS NJ AND NL
              NJ = NINT (RA(IPOP + 1))
              IF (NJ > 0) GO TO 10
              NL = NINT (RA(IPOP + 2))
              DO I = 5, 8
                XYZK(I) = RA(IPOP + I - 2)
              END DO
              DMARG  = RA(IPOP + 13)
              DMG    = 0.0
   20         RJB    = XYZK(8) + DMG
              ZU(10) = 0.0
              ZU(11) = 0.0
              ZU(12) = 1.0
C * TESTS TO AVOID DRAWING EACH INTERSECTION MORE THAN ONCE
              DSQ    = 0
              DO M = 1, 3
                ZU(6 + M) = XYZK(M + 4) - XYZK(M)
                DSQ       = DSQ + ZU(6 + M)**2
              END DO
              IF (NL == 0) THEN
                IF (ZU(9) > 0.0)  GO TO 10
              END IF
C * GET THE DISTANCE ALONG LINE KJ OF THE PLANE OF THE INTERSECTION.
C * THIS IS CALCULATED BY SIMPLE COSINE FORMULA.
C * SEE SMITH & GUND, J. CHEM. INF. COMPUT. SCI., 18, 207, 1978.
              DKJ = SQRT(DSQ)
C * THIS IS A TEMP FIX
              IF (DKJ < 0.0001) GO TO 10
              RKK = XYZK(4)**2
              RJK = RJB**2
              DIN = (RKK + DSQ - RJK) / (2.0 * DKJ)
              RIN = RKK - DIN**2
C * THIS IS A TEMP. FIX
              IF (RIN < 0.0) GO TO 10
              PAR(74) = SQRT (RIN)
C * DIRECTION COSINES OF VECTOR
              DO I = 7, 9
                ZU(I)       = ZU(I) / DKJ
                PAR(64 + I) = XYZK(I - 6) + ZU(I) * DIN
              END DO
C * THE INTERSECTION CIRCLE HAS CENTRE AT (XB,YB,ZB) AND RADIUS RIN.
C * SET UP AXIAL SYSTEM WITH U3 ALONG DIRECTION KJ. THE CIRCLE IS
C * GENERATED AS COORDINATES  (XX,YY,0)
              IF (ZU(9) < 0.9999) THEN
                CALL GEN008 (ZU(10), ZU(7), ZU(1), 1)
              ELSE
                ZU(1) = 1.0
                ZU(2) = 0.0
                ZU(3) = 0.0
              END IF
              CALL GEN008 (ZU(7), ZU(1), ZU(4), 1)
              CALL PLUT19 (IABS (NJ), 0)
              IF (IPR(346) > 0 .AND. NL /= 0) THEN
                IF (DMARG > 0.0 .AND. IPR(88) > 0) THEN
                  DMG   = DMARG
                  DMARG = 0.0
                  GO TO 20
                END IF
              END IF
              GO TO 10
            END IF
          END IF
   30   CONTINUE
      END IF
   40 IF (IPR(346) > 0 .OR. IPR(477) < 0)
     1  CALL GGIP (0.0, FLOAT (IPR(19)), 0.0, 0)
      RETURN
      END SUBROUTINE PLUT11
 
      SUBROUTINE PLUT12
C * MANAGEMENT OF MOST PRINTING/LISTING
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE pluto
      USE chdat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: NC
      INTEGER :: KL
      INTEGER :: JF
      INTEGER :: J0
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: J4
      INTEGER :: I0
      INTEGER :: I1
      INTEGER :: I2
      INTEGER :: I4
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: N4
      INTEGER :: N5
      INTEGER :: N6
      INTEGER :: N7
      INTEGER :: N8
      INTEGER :: N9
      INTEGER :: N10
      INTEGER :: N11
      INTEGER :: N12
      INTEGER :: N13
      INTEGER :: N14
      INTEGER :: N15
      INTEGER :: N16
      INTEGER :: ILB
      INTEGER :: IDH
      INTEGER :: IMV
      INTEGER :: NEL
      INTEGER :: NLI
      INTEGER :: NRF
      INTEGER :: NRI
      INTEGER :: NS2
      INTEGER :: NRES
      INTEGER :: NRBO
      INTEGER :: JINC
      INTEGER :: IDUM
      INTEGER :: IAIO
      INTEGER :: IATK
      INTEGER :: IDET
      INTEGER :: IPV1
      INTEGER :: IPV2
      INTEGER :: MULT
      INTEGER :: NSYM
      INTEGER :: NSPEC
      INTEGER :: MADDR
      INTEGER :: JDOAC
      INTEGER :: IYUNK
      INTEGER :: IROTX
      INTEGER :: IROTY
      INTEGER :: IROTZ
      INTEGER :: IDUM2
      INTEGER :: IDASH
      INTEGER :: IPR90
      REAL :: D
      REAL :: RB
      REAL :: RBO
      REAL :: PHI
      REAL :: ARU
      REAL :: DUM1
      REAL :: XDUM
      REAL :: XTRF
      CHARACTER(len=1)  :: J3
      CHARACTER(len=1)  :: J5
      CHARACTER(len=1)  :: J6
      CHARACTER(len=1)  :: J7
      CHARACTER(len=1)  :: ICH
      CHARACTER(len=1)  :: JIN
      CHARACTER(len=1)  :: LFIX
      CHARACTER(len=11) :: ATPR1
      CHARACTER(len=5)  :: ATPR2
      CHARACTER(len=6)  :: PARAM
 
C * LIST INTERNAL TABLES ETC. ROUTINE
      IPR(21) = IPR(90)
      NSPEC   = IPR(41)
      NC      = IPR(52)
      NSYM    = IPR(48)
      KL      = IPR(220)
C * GET LIST OPTIONS FOR ARU'S, LINES, BONDS, ATOMS, SYMM AND PART
      DO I = 1, 9
        K           = 2**(10 - I)
        IPR(31 - I) = IPR(21) / K
        IPR(21)     = IPR(21) - IPR(31 - I) * K
      END DO
C * LIST SYMMETRY TABLE
      IF (IPR(22) == 1 .AND. IPR(50) == 0) CALL PLA274
C * TEST FOR INDIVIDUAL ATOM(S)/BOND(S) LIST REQUEST
      IPV1  = 0
      IPV2  = 0
      IPR90 = IPR(90)
C * SPECIFIED ATOM/BOND
C * TEST FOR LIST INTER
      IF (IGBL(31) == 1) KL = 2
      IF (IPR(147) > 0)  KL = 2
      IF (IABS (IPR90 - 6) == 2 .AND. KL > 2) THEN
        CALL PLUT13 (0, -3, IPV1, XDUM)
C * SPECIFIED BOND
        IF (IPR90 == 8 .AND. KL > 3) THEN
          CALL PLUT13 (0, -4, IPV2, XDUM)
        END IF
      END IF
C * LIST ATOMS
      IF (IPR(23) /= 0) THEN
        WRITE (LINE, 99991, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          CALL GGIP (HORS, VERT, 0.0, 1)
          VRT = VERT - 0.4
          CALL PLA439 (0.0, LINE, 80, 0.35, 5 + IGBL(68), 2, 1.0, VRT)
          VRT = VRT - 0.4
        ELSE
          WRITE (LU6, 99970, IOSTAT = IOST) LINE
        END IF
        IF (IPV1 > 0) THEN
          I1 = IPV1
          I2 = IPV1
        ELSE
C * TEST FOR LIST INTER
          IF (IGBL(31) == 0) THEN
            IF (IPR(46) == 0) THEN
              I1 = IPR(69) + 1
            ELSE
              I1 = 1
            END IF
          ELSE
            I1 = IPR(38) + 1
          END IF
          I2 = IPR(37)
        END IF
        DO I = I1, I2
          CALL PLUT15 (-5, I, 48, IYUNK)
          CALL PLUT15 (-6, I, 5, NRES)
          IF (IPR(147) > 0) THEN
            IF (IPR(147) /= NRES) CYCLE
          END IF
          CALL PLUT25 (1, I, J4)
          IAIO = - J4
          IF (IPV1 >= 0 .OR. IAIO == IPV1) THEN
C * GET HBOND CHARACTERISTICS
            CALL PLUT15 (-1, I, 46, JDOAC)
            CALL PLUT15 (-1, I, 32, IDH)
            IF (JDOAC == 0 .AND. IDH == 0) THEN
              J6 = ' '
              J7 = ' '
            ELSE
              J6 = 'D'
              IF (IDH == 1) THEN
                J7 = 'H'
              ELSE
                J7 = 'A'
              END IF
            END IF
            NEL = INT (RA(I * NP43 + 7) / 64000) + 1
            CALL PLUT15 (-6, I, 18, JINC)
            CALL PLUT15 (-1, I, 27, J1)
            IF (J1 > 0) THEN
              JIN = '*'
            ELSE
              JIN  = ' '
            END IF
            IF (JINC >=  2) THEN
              J3 = 'S'
            ELSE
              J3 = ' '
            END IF
            CALL PLUT15 (-4, I, 37, ILB)
            J2   = ILB + 1
            CALL PLUT15 (-1, I, 42, JF)
            IF (JF == 1) THEN
              LFIX = '*'
            ELSE
              LFIX = '-'
            END IF
C * GET TRANSFORMATION ON INPUT
            CALL PLUT15 (-1, I, 43, IMV)
            IF (IMV > 0) THEN
              J5 = 'M'
            ELSE
              J5 = ' '
            END IF
            XTRF = RA(I * NP43 + 12)
C * HANDLE SPECIAL CASE OF UNITCELL
            IF (I <= IPR(69)) THEN
              NQ1(1:1) = 'O'
              IF (I == 1) THEN
                NQ1(2:2) = 'R'
              ELSE IF (I == 2) THEN
                NQ1(2:2) = 'C'
              ELSE IF (I == 3) THEN
                NQ1(2:2) = 'B'
              ELSE IF (I == 5) THEN
                NQ1(2:2) = 'A'
              ELSE
                NQ1(1:2) = '  '
              END IF
              WRITE (LINE, 99981, IOSTAT = IOST) NQ1(1:2),
     1        (RA(I * NP43 + K), K = 1, 3), JIN, LABP(J2), LFIX
            ELSE
              IF (JINC /= 0) THEN
                MULT = NSYM / JINC
              ELSE
                MULT = NSYM
              END IF
              WRITE (LINE, 99990, IOSTAT = IOST)
     1          NQ1(1:7), (RA(I * NP43 + K), K = 1, 3),
     2          (RADR(J4, 5 - K), K = 1, 4), MULT, J3, JIN, XTRF,
     3          J5, LABP(J2), LFIX, NRES, NEL, J6, J7
            END IF
            IF (IWIN == 1) THEN
              IF (VRT - 0.4 < 0) THEN
C * WHAT NEXT ?
                CALL PLA012 (1, 1)
                ICH = IGGT(1:1)
                CALL GGIP (HORS, VERT, 0.0, 1)
                IF (ICH /= 'Y' .AND. ICH /= '!') GO TO 10
                  VRT = VERT
              END IF
              VRT = VRT - 0.4
              CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
            ELSE
              WRITE (LU6, 99993, IOSTAT = IOST) LINE
            END IF
          END IF
        END DO
        GO TO 10
      END IF
C * LIST BONDS
      IF (IPR(24) /= 0) THEN
C * SKIP FOR NIL-BOND CASE
        IF (NC > IPR(68)) THEN
C * PRINT LIST HEADER
          WRITE (LINE, 99989, IOSTAT = IOST)
          IF (IGBL(25) * IGBL(32) == 1) THEN
            CALL GGIP (HORS, VERT, 0.0, 1)
            VRT = VERT - 0.4
            CALL PLA439 (0.0, LINE, 80, 0.35, 5 + IGBL(68), 2,
     1                   1.0, VRT)
            VRT = VRT - 0.4
          ELSE
            WRITE (LU6, 99970, IOSTAT = IOST) LINE
          END IF
          NRBO = 0
C * SET SEARCH RANGE FOR BOND ATOM I
          IF (IPV1 > 0) THEN
            I1 = IPV1
            I2 = IPV1
          ELSE
            IF (IPR(46) == 0) THEN
              I1 = IPR(69) + 1
            ELSE
              I1 = 1
            END IF
            I2 = IPR(39)
          END IF
          DO I0 = I1, I2
C * TEST ON ELEMENT TYPE
            IF (IPV1 < 0) THEN
              I4 = INT (RA(I0 * NP43 + 7) / 64000)
              IF (IPV1 + I4 + 1 /= 0)  CYCLE
            END IF
C * TEST ON RESIDUE NUMBER
            IF (IPR(147) > 0) THEN
              CALL PLUT15 (-6, I0, 5, NRES)
              IF (IPR(147) /= NRES) CYCLE
            END IF
C * SET SEARCH RANGE FOR ATOM J
            IF (IPV2 > 0) THEN
              J1 = IPV2
              J2 = IPV2
            ELSE
C * TEST FOR LIST INTER
              IF (IGBL(31) == 0) THEN
                IF (IPV2 == 0) THEN
                  J1 = I0 + 1
                ELSE
                  J1 = 1
                END IF
              ELSE
                J1 = IPR(38) + 1
              END IF
              J2 = IPR(37)
            END IF
            DO J0 = J1, J2
C * TEST ON ELEMENT TYPE
              IF (IPV2 < 0) THEN
                J4 = INT (RA(J0 * NP43 + 7) / 64000)
                IF (IPV2 + J4 + 1 /= 0)  CYCLE
              END IF
C * GET LIST NR -K- FOR THIS BOND I0 - J0
              CALL PLUT16 (-4, K, I0, J0, DUM1, IDUM2)
              IF (K > IPR(68)) THEN
C * GET BOND DATA: I, J, RBO, NLI, IDASH
                CALL PLUT16 (0, K, I, J, RBO, NLI)
                IF (NLI < 0) THEN
                  NLI   = IABS (NLI)
                  IDASH = 1
                ELSE
                  IDASH = 0
                END IF
                IF (I /= 0) THEN
C * GET LABELS INTO NQ1 & NQ2
                  CALL PLUT25 (1, I, IDUM)
                  CALL PLUT25 (2, J, IDUM)
C * GET RESIDUE-NUMBER FOR ATOMS I
                  CALL PLUT15 (-6, I, 5, NRI)
C * GET THE ARU-CODE FOR THE SECOND ATOM
                  CALL PLUT15 (-6, J, 11, NS2)
                  ARU = IARU(1, NS2 + 1) / PAR(42)
C * GET DISTANCE
                  CALL PLUT22 (I, J, D)
                  NRBO = NRBO + 1
                  WRITE (LINE, 99988, IOSTAT = IOST) NRBO, NRI,
     1              NQ1(1:7), NQ2(1:7), ARU, D, RBO, NLI, IDASH
                  IF (IGBL(25) * IGBL(32) == 1) THEN
                    IF (VRT - 0.4 < 0) THEN
C * WHAT NEXT ?
                      CALL PLA012 (1, 1)
                      ICH = IGGT(1:1)
                      CALL GGIP (HORS, VERT, 0.0, 1)
                      IF (ICH /= 'Y' .AND. ICH /= '!') GO TO 10
                      VRT = VERT
                    END IF
                    VRT = VRT - 0.4
                    CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
                  ELSE
                    WRITE (LU6, 99993, IOSTAT = IOST) LINE
                  END IF
                END IF
              END IF
            END DO
          END DO
        END IF
        GO TO 10
      END IF
C * LIST BOND-TYPES
      IF (IPR(25) /= 0) THEN
        IF (IPR(12) < 0) THEN
          IDASH = 1
        ELSE
          IDASH = 0
        END IF
        WRITE (LINE, 99987, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          CALL GGIP (HORS, VERT, 0.0, 1)
          VRT = VERT - 1.5
          CALL PLA439 (0.0, LINE, 80, 0.35, 5 + IGBL(68), 2, 1.0, VRT)
          VRT = VRT - 0.8
        ELSE
          WRITE (LU6, 99992, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99986, IOSTAT = IOST)
     1    PAR(38), IABS (IPR(12)), IDASH
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.6
          CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99993, IOSTAT = IOST) LINE
        END IF
        DO K = 1, NSPEC
          NRF = IPR(80) - (K - 1) * 3
          L   = NINT (RA(NRF - 2))
          I   = IABS (L) / 1000
          RB  = 0.001 * FLOAT (MOD (IABS (L), 1000))
          N1  = NINT (RA(NRF))
          N2  = NINT (RA(NRF - 1))
          IF (L < 0) THEN
            IDASH = 1
          ELSE
            IDASH = 0
          END IF
          IF (N1 < 0) THEN
            WRITE (LINE, 99985, IOSTAT = IOST) RB, I, IDASH
            IF (IGBL(25) * IGBL(32) == 1) THEN
              VRT = VRT - 0.6
              CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
            ELSE
              WRITE (LU6, 99993, IOSTAT = IOST) LINE
            END IF
          ELSE IF (N1 == 0) THEN
            N2 = NINT (RA(NRF - 1))
            IF (N2 <= 0) THEN
              N2 = IEL(IEN( - N2))
              N1 = N2 / 100 + ICHAR ('A') - 1
              N2 = MOD(N2, 100)
              IF (N2 == 0) THEN
                N2 = ICHAR (' ')
              ELSE
                N2 = N2 + ICHAR ('a') - 1
              END IF
              NQ1 = CHAR(N1)//CHAR (N2)//'     '
            ELSE
              CALL PLUT25 (1, N2, IATK)
            END IF
            WRITE (LINE, 99983, IOSTAT = IOST) NQ1, RB, I, IDASH
            IF (IGBL(25) * IGBL(32) == 1) THEN
              VRT = VRT - 0.6
              CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
            ELSE
              WRITE (LU6, 99993, IOSTAT = IOST) LINE
            END IF
          ELSE
            CALL PLUT25 (1, N1, IATK)
            CALL PLUT25 (2, N2, IATK)
            WRITE (LINE, 99982, IOSTAT = IOST) NQ1, NQ2, RB, I, IDASH
            IF (IGBL(25) * IGBL(32) == 1) THEN
              VRT = VRT - 0.6
              CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
            ELSE
              WRITE (LU6, 99993, IOSTAT = IOST) LINE
            END IF
          END IF
        END DO
        WRITE (LINE, 99980, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 1.0
          CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99969, IOSTAT = IOST) LINE
        END IF
        GO TO 10
      END IF
C * LIST ARU'S
      IF (IPR(26) /= 0) THEN
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VERT - 0.2
          CALL GGIP (HORS, VERT, 0.0, 1)
          OPEN (LU61, FILE = 'srcsrc', STATUS = 'UNKNOWN')
          MADDR = 0
          CALL PLUT17 (1004, 0.0, MADDR, LU61)
C * REWIND
          CALL GEN108 (LU61, 0)
          DO
            READ (LU61, 99993, IOSTAT = IOST) LINE
            IF (IOST /= 0) EXIT
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          GO TO 10
        ELSE
          CALL PLUT17 (1004, 0.0, MADDR, LU6)
        END IF
      END IF
C * LIST ORIENTATION MATRIX PARAMETERS
      IF (IPR(27) /= 0) THEN
        CALL GEN096 (R, IROTX, IROTY, IROTZ, IDET, XYZOR, PHI, ROM)
        WRITE (LU6, 99997, IOSTAT = IOST) IROTX, IROTY, IROTZ, IDET,
     1    ((R(I, J), J = 1, 3), I = 1, 3)
      END IF
      IF (IPR(28) /= 0) THEN
        WRITE (LU6, 99996, IOSTAT = IOST)
     1    IPR(39), IPR(38), IPR(37), IPR(53), IPR(52), IPR(75),
     2    IPR(42), IPR(43)
        WRITE (LU6, 99995, IOSTAT = IOST)
     1    IPR(46), IPR(116), NINT (PAR(48)), IPR(4), IPR(9), IGBL(67),
     2    IGBL(75), IPR(77), IPR(346), IPR(19), IPR(63)
        WRITE (LU6, 99994, IOSTAT = IOST)
     1    PAR(24), PAR(15), VERT, PAR(48), PAR(13), PAR(36), PAR(39),
     2    PAR(5), PAR(3), PAR(44)
      END IF
C * LIST ATOM TYPE PARAMETERS
      IF (IPR(29) /= 0) THEN
        WRITE (LINE, 99999, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          CALL GGIP (HORS, VERT, 1.0, 1)
          VRT = VERT - 0.8
          CALL PLA439 (0.0, LINE, 80, 0.35, 5 + IGBL(68), 2, 1.0, VRT)
          VRT = VRT - 0.3
        ELSE
          WRITE (LU6, 99992, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99977, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.4
          CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99993, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99976, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.8
          CALL PLA439 (0.0, LINE, 80, 0.35, 6, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99969, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99975, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.8
          CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99969, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99974, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.8
          CALL PLA439 (0.0, LINE, 80, 0.35, 6, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99969, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99973, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.8
          CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99992, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99972, IOSTAT = IOST)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 0.6
          CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
        ELSE
          WRITE (LU6, 99993, IOSTAT = IOST) LINE
        END IF
        WRITE (LINE, 99971, IOSTAT = IOST) PAR(1)
        IF (IGBL(25) * IGBL(32) == 1) THEN
          VRT = VRT - 1.0
          CALL PLA439 (0.0, LINE, 80, 0.35, 5 + IGBL(68), 2, 1.0, VRT)
          VRT = VRT - 0.2
        ELSE
          WRITE (LU6, 99992, IOSTAT = IOST) LINE
        END IF
        DO I = 1, IAN
          N2 = IEL(IEN(I))
          N1 = N2 / 100 + ICHAR ('A') - 1
          N2 = MOD (N2, 100)
          IF (N2 == 0) THEN
            N2 = ICHAR (' ')
          ELSE
            N2 = N2 + ICHAR ('a') - 1
          END IF
          N3 = IATPR(IEN(I))
          ATPR1 = '           '
          IF (N3 <= 0) THEN
            N3 = - N3
            ATPR2 = '     '
          ELSE
            ATPR2 = 'Metal'
          END IF
          IF (N3 == 2) THEN
            ATPR1 = 'Lanthanide '
          ELSE IF (N3 == 3) THEN
            ATPR1 = 'Actinide   '
          ELSE IF (N3 == 4) THEN
            ATPR1 = 'Transition '
          ELSE IF (N3 == 5) THEN
            ATPR1 = 'Alkali     '
          ELSE IF (N3 == 6) THEN
            ATPR1 = 'AlkaliEarth'
          ELSE IF (N3 == 7) THEN
            ATPR1 = 'Halogen    '
          END IF
          PARAM = '      '
          IF (BWCT(IBCL(I))(1:3)  == 'NET') THEN
            WRITE (PARAM, 99984, IOSTAT = IOST) IPR(85), IPR(86)
          ELSE IF (BWCT(IBCL(I))(1:3) == 'GLO') THEN
            WRITE (PARAM, 99984, IOSTAT = IOST) IPR(112), IPR(132)
          END IF
          WRITE (LINE, 99998, IOSTAT = IOST)
     1      CHAR (N1), CHAR (N2), COLR(IACL(I)), BWCT(IBCL(I)), PARAM,
     2      (RADR(I, 5 - J), J = 1, 4), ATPR1, ATPR2
          IF (IGBL(25) * IGBL(32) == 1) THEN
            VRT = VRT - 0.6
            CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
          ELSE
            WRITE (LU6, 99993, IOSTAT = IOST) LINE
          END IF
        END DO
        GO TO 10
      END IF
C * LIST ATOM-FLAGS
      IF (IPR(30) == 1) THEN
        WRITE (LINE, 99978, IOSTAT = IOST)
        IF (IWIN == 1) THEN
          CALL GGIP (HORS, VERT, 0.0, 1)
          VRT = VERT - 0.8
          CALL PLA439 (0.0, LINE, 80, 0.35, 5 + IGBL(68), 2, 1.0, VRT)
          VRT = VRT - 0.3
        ELSE
          WRITE (LU6, 99992, IOSTAT = IOST) LINE
        END IF
        DO I = IPR(69) + 1, IPR(37)
          CALL PLUT25 (1, I, IDUM)
          CALL PLUT15 (-4, I,  1, N1)
          CALL PLUT15 (-6, I,  5, N2)
          CALL PLUT15 (-6, I, 11, N3)
          CALL PLUT15 (-1, I, 17, N6)
          CALL PLUT15 (-6, I, 18, N10)
          CALL PLUT15 (-3, I, 24, N16)
          CALL PLUT15 (-1, I, 27, N11)
          CALL PLUT15 (-4, I, 28, N12)
          CALL PLUT15 (-1, I, 32, N13)
          CALL PLUT15 (-4, I, 33, N14)
          CALL PLUT15 (-4, I, 37, N15)
          CALL PLUT15 (-1, I, 42, N5)
          CALL PLUT15 (-1, I, 43, N4)
          CALL PLUT15 (-1, I, 44, N7)
          CALL PLUT15 (-1, I, 45, N8)
          CALL PLUT15 (-1, I, 46, N9)
          WRITE (LINE, 99979, IOSTAT = IOST)
     1      NQ1, N1, N2, N3, N6, N16, N10, N11, N12, N13, N14, N15, N5,
     2      N4, N7, N8, N9
          IF (IWIN == 1) THEN
            IF (VRT - 0.4 < 0) THEN
C * WHAT NEXT ?
              CALL PLA012 (1, 1)
              ICH = IGGT(1:1)
              CALL GGIP (HORS, VERT, 0.0, 1)
              IF (ICH /= 'Y' .AND. ICH /= '!') GO TO 10
              VRT = VERT
            END IF
            VRT = VRT - 0.4
            CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 1.0, VRT)
          ELSE
            WRITE (LU6, 99993, IOSTAT = IOST) LINE
          END IF
        END DO
        GO TO 10
      END IF
      RETURN
   10 IF (IGBL(25) * IGBL(32) == 1) CALL PLA297 (1)
      RETURN
99999 FORMAT (20X, ' ATOM TYPES AND PARAMETERS')
99998 FORMAT (2X, 2A, 1X, A, 1X, A, A, F5.2, 3F7.2, 2X, A, 1X, A)
