      SUBROUTINE PLUT13 (MODE, KK, IAT, XMOL)
C * SUBROUTINE RETURNS IN IAT : ATOM SERIAL NUMBER (POSITIVE) FOR IFL(KK)
C *           OR              : ELEMENT TYPE NUMB. (IEN ENT)( IAT < 0)
C *           OR              : 0, FOR UNRECOGNISED ATOM NAME OR TYPE
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N
      INTEGER :: KK
      INTEGER :: NA1
      INTEGER :: NA2
      INTEGER :: NE1
      INTEGER :: NE2
      INTEGER :: NS1
      INTEGER :: NS2
      INTEGER :: IAT
      INTEGER :: NIEN
      INTEGER :: NAX1
      INTEGER :: NAX2
      INTEGER :: IATK
      INTEGER :: MODE
      INTEGER :: IXPK1
      INTEGER :: IXPK2
      INTEGER :: MSUBST
      REAL :: XMOL
      CHARACTER(len=1) :: ICH
C * MODE
C * KK > 0 : TEST ON ATOM-NAME, THEN ON ATOM-TYPE
C * KK < 0 : TEST ON ATOM-TYPE, THEN ON ATOM-NAME
C * HANDLE ALIASES
 
      NQ1    = IFL(IABS(KK))
      MSUBST = 0
      CALL PLA281 (1, NQ1, MSUBST)
C * SPLIT ATOM LABEL (NQ1) INTO ELEMENT TYPE (NE1),
C *                           NUMERICAL TYPE (NA1),
C *                      SEMI-NUMERICAL TYPE (NAX1),
C *                        AND SYMMETRY PART (NS1).
      XMOL = 0.0
C * IGNORE 'RENAME'
      IF (NQ1(1:3) == 'REN') THEN
        IAT  = 0
        WRITE (LU6, 99999, IOSTAT = IOST) NQ1
        RETURN
      END IF
      N = INDEX (NQ1, '_')
      IF (N /= 0) THEN
        ICH = NQ1(N+1:N+1)
        DO I = 1, 10
          IF (ICH == CHAR (ICHAR ('0') + I - 1)) THEN
            N = 0
            GO TO 10
          END IF
        END DO
      END IF
   10 CALL PLA046 (8, NQ1, NE1, NA1, NAX1, NS1, IXPK1, IXPK2, NIEN)
C * TEST FOR NUMBER OF ELEMENT IN ARRAY IEN
      IF (NE1 == 0) THEN
        IAT = 0
      ELSE IF (NE1 < NP9 - 3) THEN
        IF (KK < 0) THEN
C * REGISTER ATOM-TYPE
          IF (NA1 < 0) THEN
            IAT = - NE1
            GO TO 20
          END IF
        END IF
C * TEST FOR ATOM NAME
        DO IAT = IPR(69) + 1, IPR(37)
           CALL PLUT25 (2, IAT, IATK)
           CALL PLA046 (8, NQ2, NE2, NA2, NAX2, NS2, IXPK1, IXPK2,
     1       NIEN)
           IF (NE1 == NE2) THEN
             IF (NA1 == NA2 .OR. (NA1 == 0 .AND. NA2 == -1)) THEN
               IF (NAX1 == NAX2) THEN
                 IF (MODE < 0) THEN
                   IF (NS1 > 0) XMOL =
     1               IARU(1, NS1 + IPR(75)) / PAR(42)
                   GO TO 20
                 ELSE
                   IF (NS1 == NS2) GO TO 20
                 END IF
               END IF
             END IF
           END IF
        END DO
        IF (NA1 > 0) THEN
          IAT = 0
          GO TO 20
        END IF
C * TEST FOR ELEMENT NAME
        IAT = - NE1
      ELSE IF (NE1 == NP9 - 3) THEN
        IAT = 1
      ELSE IF (NE1 == NP9 - 2) THEN
        IAT = 5
      ELSE IF (NE1 == NP9 - 1) THEN
        IAT = 3
      ELSE IF (NE1 == NP9) THEN
        IAT = 2
      ELSE
        IAT = 0
      END IF
   20 IF (MODE <= 0 .AND. IAT == 0 .AND. KK > 0) THEN
        WRITE (LU6, 99999, IOSTAT = IOST) NQ1
      END IF
      RETURN
99999 FORMAT (':: ATOM Name/Type ERROR for: ', A)
      END SUBROUTINE PLUT13
 
      SUBROUTINE PLUT14 (MODE, J, IASU, NPROP, X, Y, Z, S)
C * THIS SUBROUTINE HANDLES THE STORAGE AND RETRIEVAL OF ATOM ITEMS
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IASU
      INTEGER :: MODE
      INTEGER :: NPROP
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: S
C * MODE =  1 - PUT FUNCTION
C * MODE =  0 - STACK FUNCTION
C * MODE = -1 - GET FUNCTION
      I = J * NP0 + IPR(158)
      IF (MODE < 0) THEN
C * RETRIEVE MODE
        IASU  = NINT (RA(I - 5))
        NPROP = NINT (RA(I - 4))
        X     = RA(I - 3)
        Y     = RA(I - 2)
        Z     = RA(I - 1)
        S     = RA(I)
      ELSE
C * MODE >= 0
        IF (MODE == 0) THEN
          IPR(67) = IPR(67) + 1
          J       = IPR(40) + IPR(67)
          I       = J * NP0 + IPR(158)
          IF (I >= IPR(66) - IPR(78) * 13) THEN
            IPR(101) = IPR(101) + 1
            J        = 0
            IPR(67)  = IPR(67) - 1
            RETURN
          END IF
        END IF
C * STORE MODE
        RA(I - 5) = IASU
        RA(I - 4) = NPROP
        RA(I - 3) = X
        RA(I - 2) = Y
        RA(I - 1) = Z
        RA(I)     = S
      END IF
      RETURN
      END SUBROUTINE PLUT14
 
      SUBROUTINE PLUT15 (IKEY, IAT, IBITN, IVL)
      USE pluto
      IMPLICIT NONE
      INTEGER :: IX
      INTEGER :: IAT
      INTEGER :: IVL
      INTEGER :: INH
      INTEGER :: IKEY
      INTEGER :: IBTN
      INTEGER :: IFLI
      INTEGER :: IBIT
      INTEGER :: IBITN
C * BITS  1 TO 23 ARE STORED IN RA(I + 8) AND
C * BITS 24 TO 46 ARE STORED IN RA(I + 9)
C * BITS 47 TO 69 ARE STORED IN RA(I + 10)
      IBTN = IBITN
      IX   = IAT * NP43 + 8 + (IBTN - 1) / 23
      IBTN = 1 + MOD (IBTN - 1, 23)
      IFLI = NINT (RA(IX))
      IBIT = IBT(IBTN)
      INH  = MOD (IFLI / IBIT, IBT(IABS (IKEY) + 1))
      IF (IKEY < 0) THEN
        IVL = INH
      ELSE
        RA(IX) = IFLI + (IVL - INH) * IBIT
      END IF
      RETURN
      END SUBROUTINE PLUT15
 
      SUBROUTINE PLUT16 (MODE, IAJAT, IAT, JAT, RBO, NLI)
C * BOND STORAGE AND RETRIEVAL
      USE files
      USE parameters
      USE atomdata
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: KK
      INTEGER :: MD
      INTEGER :: ML
      INTEGER :: NC
      INTEGER :: NC0
      INTEGER :: NCU
      INTEGER :: MDD
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: NLI
      INTEGER :: ICI
      INTEGER :: IBN
      INTEGER :: IM2
      INTEGER :: JCI
      INTEGER :: NAB
      INTEGER :: NLN
      INTEGER :: NRS
      INTEGER :: NSK
      INTEGER :: MNML
      INTEGER :: JAT0
      INTEGER :: IBNB
      INTEGER :: IADR
      INTEGER :: IAT0
      INTEGER :: MODE
      INTEGER :: ICMD
      INTEGER :: IJAT
      INTEGER :: ILPB
      INTEGER :: ISTK
      INTEGER :: IVAL
      INTEGER :: NRJT
      INTEGER :: NMLX
      INTEGER :: IARU0
      INTEGER :: JARU0
      INTEGER :: NPROP
      INTEGER :: NINCL
      INTEGER :: ITYPE
      INTEGER :: JTYPE
      INTEGER :: IAJAT
      INTEGER :: NRINCL
      INTEGER :: IENITP
      INTEGER :: IENJTP
      INTEGER :: IPR158
      REAL :: AL
      REAL :: BE
      REAL :: DK
      REAL :: DX
      REAL :: DY
      REAL :: DZ
      REAL :: RB
      REAL :: RI
      REAL :: RJ
      REAL :: RJK
      REAL :: RAI
      REAL :: RAJ
      REAL :: RIK
      REAL :: RBO
      REAL :: RA4
      REAL :: RA8
      REAL :: RB9
      REAL :: RA12
      REAL :: DXYZ
      REAL :: QMPK
      REAL :: RPKPK
      REAL :: RQKQK
      REAL :: DKQMPK
C * MODE = -1: ADD THIS BOND TO BOND LIST
C * MODE = -2: LOAD UNIT-CELL OUTLINE
C * MODE = -3: DELETE THIS BOND FROM BOND LIST ( = MAKE ENTRY NEGATIVE)
C * MODE = -4: GET LIST NUMBER OF SPECIFIED BOND
C * MODE = -5: CHECK WHETHER IAT AND JAT ARE BONDED ATOMS
C * MODE = -6: LOAD ACTIVE BONDS
C * MODE =  0: UNPACK MODE INTO IAT AND JAT + RBO + NLI FROM BONDLIST
C * MODE = >0: UNPACK MODE INTO IAT AND JAT + RBO + NLI FROM ACTIVE LIST
      RA12   = 0.0
      MD     = MODE
      ILPB   = IPR(69) + 1
      NAB    = IPR(37) - IPR(69)
      IPR158 = IPR(158)
      NSK    = 0
      IF (MD > 0) THEN
C * UNPACK BOND FROM ACTIVE BOND LIST AND GENERATE PSEUDO ATOM ENDPOINTS
C * ON OUTPUT: PSEUDO ATOM ENDPOINT PARAMETERS ON STACK
C *            UNIT VECTOR ALONG BOND IN ZU(7:9)
C *            BOND RADIUS IN RBO
C *            NR OF LINES IN NLI
        IADR     = IPR(79) - MD * 4
        IAT      = NINT (RA(IADR + 1))
        JAT      = NINT (RA(IADR + 2))
        RBO      = RA(IADR + 3)
        NLN      = NINT (RA(IADR + 4))
        IPR(120) = MOD (IABS (NLN), 1024)
        NLI      = IABS (NLN) / 1024
        I        = IAT * NP0 + IPR158
        J        = JAT * NP0 + IPR158
        IF (IPR(477) > 0) THEN
          NPROP  = MAX (NINT (RA(I - 4)), NINT (RA(J - 4)))
          CALL GEN048 (-5, NPROP, 1, IPR(120))
        ELSE IF (IPR(477) < 0) THEN
          IAT0 = MOD (IAT - ILPB, NAB) + ILPB
          CALL PLUT15 (-6, IAT0, 5, NRS)
          IF (NRS > 0 .AND. NRS <= 16) IPR(120) = NRS
        END IF
        ISTK     = IPR158 + (IPR(40) + IPR(67)) * NP0
        IPR(67)  = IPR(67) + 2
        IF (NLN < 0) NLI = - NLI
        IF (RBO < 0.0) RBO = ABS (RBO)
        IF (ISTK + 2 * NP0 >= IPR(66) - IPR(78) * 13)
     1    CALL PLUT38 (3, 1, LU6)
        DK = 0
        DO K = 1, 3
          ZU(K + 6) = RA(J + K - 4) - RA(I + K - 4)
          DK        = DK + ZU(K + 6)**2
        END DO
        IF (DK /= 0.0) THEN
          DXYZ = SQRT (DK)
        ELSE
          DXYZ = 1.0
        END IF
        RI   = AMOD (ABS (RA(I)), 1000.0)
        RJ   = AMOD (ABS (RA(J)), 1000.0)
C * GET BOND RADIUS AT ATOMS IAT AND JAT
        RB   = RBO * PAR(24)
        RA4  = RB
        RA8  = RB
        IF (PAR(48) == 0.0) THEN
          IF (PAR(44) /= 0.0 .AND. IPR(4) /= 4) THEN
C * APPLY TAPER (NO PERSPECTIVE OR STRAW CASE)
            RB9 = RB * ABS (PAR(44) * ZU(9) / DXYZ)
            RA4 = RB + RB9
            RA8 = RB - RB9
          END IF
        ELSE
C * APPLY PERSPECTIVE
          RA4 = RB * PAR(48) / (PAR(48) - RA(I - 1))
          RA8 = RB * PAR(48) / (PAR(48) - RA(J - 1))
        END IF
        RA4 = MAX (MIN (RA4, RI - 0.001), 0.0)
        RA8 = MAX (MIN (RA8, RJ - 0.001), 0.0)
        IF (IPR(4) > 0) THEN
          RA12   = RA8 - RA4
          QMPK   = RA12**2
          RIK    = RI**2
          RJK    = RJ**2
          RPKPK  = DK * (RIK - RA4**2) + RIK * QMPK
          RQKQK  = DK * (RJK - RA8**2) + RJK * QMPK
          DKQMPK = DK + QMPK
          AL     = (SQRT (RPKPK) - RA4 * RA12) / DKQMPK
          BE     = (SQRT (RQKQK) + RA8 * RA12) / DKQMPK
        ELSE
          AL     = 0.0
          BE     = 0.0
        END IF
C * STORE BOND ENDPOINTS AS PSEUDO ATOMS
        DO K = 1, 3
          RA(ISTK + K +     NP0 - 4) = RA(I + K - 4) + AL * ZU(K + 6)
          RA(ISTK + K + 2 * NP0 - 4) = RA(J + K - 4) - BE * ZU(K + 6)
        END DO
        RA(ISTK + NP0)     = RA4 + AL * RA12
        RA(ISTK + 2 * NP0) = RA8 - BE * RA12
        DO K = 7, 9
          ZU(K) = ZU(K) / DXYZ
        END DO
      ELSE IF (MD < 0) THEN
C * HANDLING OF MODE = - 6 - LOAD ACTIVE BONDS
        IF (MD == -6) THEN
C * ACTIVE BOND COUNTER
          IADR    = IPR(79)
          IPR(97) = 0
C * NUMBER OF ASU'S = ASYMMETRIC STRUCTURE UNITS
          NMLX    = IPR(142)
C * NUMBER OF BONDS
          NC      = IPR(52)
C * NUMBER OF UNIQUE BONDS
          NCU     = IPR(53)
C * TEST FOR UNITCELL OFF/ON
          IF (IPR(46) > 0) THEN
            IBNB = 1
          ELSE
            IBNB = IPR(68) + 1
          END IF
C * LOOP THROUGH THE LIST OF CONNECTIONS STORED IN ARRAY RA
          IF (NC >= IBNB) THEN
            DO IBN = IBNB, NC
              ICMD = NINT (RA(IPR(64) + 1 - IBN * 2))
C * SKIP EXCLUDED BOND
              IF (ICMD > 0) THEN
                IAT    = ICMD
                JAT    = NINT (RA(IPR(64) + 2 - IBN * 2))
                NRINCL = 2
C * SKIP BONDS INVOLVING EXCLUDED ATOMS
                IF (IAT >= ILPB) THEN
C * GET ELEMENT TYPE (SPECIAL Cg TREATMENT
                  ITYPE = INT (RA(IAT * NP43 + 7) / 64000) + 1
                  IF (IAT <= IPR(39)) THEN
                    CALL PLUT15 (-1, IAT, 27, NINCL)
                    NRINCL = NRINCL - 1 + NINCL
                  END IF
                  IENITP = IEN(ITYPE)
                ELSE
                  ITYPE  = 0
                  IENITP = 0
                END IF
                IF (JAT >= ILPB) THEN
C * GET ELEMENT TYPE
                  JTYPE = INT (RA(JAT * NP43 + 7) / 64000) + 1
                  IF (JAT <= IPR(39)) THEN
                    CALL PLUT15 (-1, JAT, 27, NINCL)
                    NRINCL = NRINCL - 1 + NINCL
                  END IF
                  IENJTP = IEN(JTYPE)
                ELSE
                  JTYPE  = 0
                  IENJTP = 0
                END IF
                IF (NRINCL >= IPR(165)) THEN
C * GET ARU-NUMBERS
                  CALL PLUT15 (-6, IAT, 11, IARU0)
                  CALL PLUT15 (-6, JAT, 11, JARU0)
                  CALL PLUT27 (IBN, IAT, JAT, RBO, NLI)
                  IF (IBN > IPR(68)) THEN
                    MNML = NMLX
                  ELSE
                    MNML = 1
                  END IF
                  IAT0 = IAT - NAB
                  JAT0 = JAT - NAB
C * LOOP OVER ASU LIST
                  DO ML = 1, MNML
                    IAT0 = IAT0 + NAB
                    JAT0 = JAT0 + NAB
                    IF (IBN > NCU) THEN
                      NRJT = 2
                    ELSE
                      NRJT = 3 - IPR(165)
                    END IF
                    I   = IAT0 * NP0 + IPR(158)
                    J   = JAT0 * NP0 + IPR(158)
                    NSK = 2
C * ELIMINATE REDUNDANT BONDS
                    RAI = ABS (RA(I))
                    IF (RAI > 999.9) THEN
                      NSK = NSK - 1
                      RAI = RAI - 1000.0
                    END IF
                    RAJ = ABS (RA(J))
                    IF (RAJ > 999.9) THEN
                      NSK = NSK - 1
                      RAJ = RAJ - 1000.0
                    END IF
                    IF (NSK < 2) THEN
C * TEST FOR 'OMIT OUTSIDE ATOM'
                      IF (IPR(15) < 0) THEN
                        NSK = 0
                      ELSE
                        NSK = 2
                      END IF
                    END IF
                    IF (NSK > 0) THEN
C * OMIT INTER-MOLECULAR BONDS WHEN BOTH ATOMS ARE OMITTED
                      IF (ITYPE /= 0 .AND. JTYPE /= 0) THEN
C * TEST FOR CG (106)
                        IF (IENITP /= 106 .AND.
     1                      IENJTP /= 106) THEN
                          IF (IARU0 /= JARU0) NRJT = 1
                        ELSE
                          NRJT = 2
                        END IF
                      END IF
C * OMIT INTRA-MOLECULAR BONDS WHEN EITHER ATOM IS OMITTED
                      IF (ITYPE /= 0 .AND. JTYPE /= 0)THEN
                        IF (RA(I) < 0.0) NRJT = NRJT - 1
                        IF (RA(J) < 0.0) NRJT = NRJT - 1
                      END IF
                      IF (NRJT > 0) THEN
                        IF (NLI /= 0) THEN
                          DX = RA(I - 3) - RA(J - 3)
                          DY = RA(I - 2) - RA(J - 2)
                          DZ = RA(I - 1) - RA(J - 1)
                          DK = DX**2 + DY**2 + DZ**2
C * MAKE SHURE THAT ATOM IAT HAS HIGHEST Z-VALUE
                          IF (DZ < 0.0) THEN
                            CALL GEN014 (IAT0, JAT0)
C * EXCHANGE TYPES AS WELL
                            CALL GEN014 (ITYPE, JTYPE)
                          END IF
                          IF (IPR(4) > 0) DK = DK - RAI**2 - RAJ**2
                          IF (DK > 0.0) THEN
                            RA(IADR - 3) = IAT0
                            RA(IADR - 2) = JAT0
                            RA(IADR - 1) = RBO
                            RA(IADR    ) = ISIGN (IABS (NLI) * 1024
     1                                   + ITYPE * 32 + JTYPE, NLI)
                            IPR(97)      = IPR(97) + 1
                            IADR         = IADR - 4
                          END IF
                        END IF
                      END IF
                    END IF
                  END DO
                END IF
              END IF
            END DO
          END IF
C * HANDLING OF MODE = -2 CASE (UNIT CELL OUTLINE)
        ELSE IF (MD == -2) THEN
          DO K = 1, 4
            KK = 2 * ((K - 1) / 2) + K
            RA(IPR(64) - (K - 1) * 2 - 1) = 2 * K - 1
            RA(IPR(64) - (K - 1) * 2)     = 2 * K
            RA(IPR(64) - (K + 3) * 2 - 1) = K
            RA(IPR(64) - (K + 3) * 2)     = K + 4
            RA(IPR(64) - (K + 7) * 2 - 1) = KK
            RA(IPR(64) - (K + 7) * 2)     = KK + 2
          END DO
          IPR(68) = 12
          IPR(52) = IPR(68)
          IPR(53) = IPR(68)
        ELSE
C * HANDLING OF MODE= -1, -3, -4, -5 CASES
          IAT0 = IAT
          JAT0 = JAT
C * HANDLING OF MODE = -5 CASE: REDUCE ATOM NUMBERS TO PRIMARIES
          IF (MD == -5) THEN
            JAT0 = MOD (JAT - ILPB, NAB) + ILPB
            IAT0 = MOD (IAT - ILPB, NAB) + ILPB
          END IF
          IF (JAT0 /= IAT0) THEN
            IF (JAT0 < IAT0) CALL GEN014 (IAT0, JAT0)
            IF (MD == -3) THEN
              MDD = -1
            ELSE
              MDD = 1
            END IF
            IJAT = IAT0 * MDD
            NC   = IPR(52)
            NC0  = IPR(68) + 1
            IF (NC >= NC0) THEN
              DO I = NC0, NC
                ICI = NINT (ABS (RA(IPR(64) + 1 - I * 2)))
                JCI = NINT (RA(IPR(64) + 2 - I * 2))
                IF (ICI == IABS (IJAT) .AND. JCI == JAT0) GO TO 10
              END DO
            END IF
            I = -1
            IF (MD == -1) THEN
              IPR(52) = IPR(52) + 1
C * CHECK FOR STACK OVERFLOW
              IF (((IPR(37) + 1) * NP43) > (IPR(64) - IPR(52) * 2))
     1          CALL PLUT38 (3, 1, LU6)
              I   = IPR(52)
              IM2 = I * 2
              IF (IPR(35) >= 0) THEN
                IF (JAT0 <= IPR(38)) THEN
C * SWAP/SHIFT
                  IPR(53)               = IPR(53) + 1
                  RA(IPR(64) + 1 - IM2) = RA(IPR(64) + 1 - IPR(53) * 2)
                  RA(IPR(64) + 2 - IM2) = RA(IPR(64) + 2 - IPR(53) * 2)
                  I                     = IPR(53)
                END IF
                CALL PLUT15 (-4, IAT, 33, IVAL)
                IF (IVAL < NP33) THEN
                  IVAL = IVAL + 1
                  CALL PLUT15 (4, IAT, 33, IVAL)
                END IF
                CALL PLUT15 (-4, JAT, 33, IVAL)
                IF (IVAL < NP33) THEN
                  IVAL = IVAL + 1
                  CALL PLUT15 (4, JAT, 33, IVAL)
                END IF
              END IF
            ELSE
              GO TO 20
            END IF
   10       IF (IABS (MD + 2) == 1) THEN
              RA(IPR(64) + 1 - I * 2) = IAT0 * MDD
              RA(IPR(64) + 2 - I * 2) = JAT0
            END IF
   20       IAJAT = I
          ELSE
            IAJAT = -1
          END IF
        END IF
      ELSE IF (MD == 0) THEN
C * UNPACK BOND FROM PRIMARY BOND LIST
        ICMD = NINT (RA(IPR(64) + 1 - IAJAT * 2))
        IF (ICMD < 0) THEN
          IAT = 0
          JAT = 0
        ELSE
          IAT = ICMD
          JAT = NINT (RA(IPR(64) + 2 - IAJAT * 2))
          CALL PLUT27 (IAJAT, IAT, JAT, RBO, NLI)
          IF (NLI == 0) THEN
            IAT = 0
            JAT = 0
          END IF
        END IF
      END IF
      RETURN
      END SUBROUTINE PLUT16
 
      SUBROUTINE PLUT17 (MODE, XMOLE, MADDR, LUNIT)
C * SUBROUTINE MANAGES ARU'S
      USE files
      USE parameters
      USE atomdata
      USE pluto
      USE chdat
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: KL
      INTEGER :: NR
      INTEGER :: IM1
      INTEGER :: IM2
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: MPM
      INTEGER :: MXL
      INTEGER :: NMA
      INTEGER :: NMB
      INTEGER :: NR1
      INTEGER :: NR2
      INTEGER :: NMLX
      INTEGER :: NRES
      INTEGER :: NARU
      INTEGER :: LDIF
      INTEGER :: LRES
      INTEGER :: IVAL
      INTEGER :: MODE
      INTEGER :: NSL2
      INTEGER :: NSLM
      INTEGER :: NSYM
      INTEGER :: NRESA
      INTEGER :: NRESB
      INTEGER :: ILAST
      INTEGER :: MADDR
      INTEGER :: LUNIT
      INTEGER :: NARU1
      INTEGER :: NARU2
      INTEGER :: NARU3
      INTEGER :: NARU4
      REAL :: XML
      REAL :: XNM
      REAL :: OXML
      REAL :: DPLN
      REAL :: XMOLL
      REAL :: XMOLE
      CHARACTER(len=3)  :: N1
      CHARACTER(len=10) :: ARU1
      CHARACTER(len=10) :: ARU2
      CHARACTER(len=10) :: ARU3
C * SPF or RES INSTRUCTIONS
C * MODE  = +/-  : ADD/DELETE ARU'S (NEG. =  INTER ARU ADD) (<= 1000)
C *       = -1   :
C *       = 0    :
C *       = 1001 : LIST INSTRUCTIONS
C *       = 1002 : COUNT ACTIVE NUMBER OF ASU'S
C *       = 1003 : UNIQUE AND HBOND ARU'S INACTIVE
C *       = 1004 : LIST ARU'S AND ASU'S
C *       = 1005 : DELETE ARU ON SERIAL #
C * XMOLE        : sttt.rr ARU-CODE
C * MADDR        : SERIAL NUMBER OF ARU 'XMOLE' IN ARU-LIST
C * LUNIT        : OUTPUT UNIT
      KL    = IPR(220)
      NSYM  = IPR(48)
      NRES  = IPR(75)
      NARU  = IPR(42)
      MADDR = 0
C * ADD/DELETE MODE
      IF (IABS (MODE) <= 1000) THEN
        IPR(130) = 0
        IF (MODE > 0) THEN
          NMA = MODE / 32
          NMA = NMA * 5 + 1
          NMB = MOD (MODE, 32)
        END IF
        XML = XMOLE
C * MAKE SHURE THAT THERE IS AT LEAST ONE ARU TO BE PLOTTED
        IF (XML == 0.0) THEN
          IF (NARU > 0) THEN
            DO I = 1, NARU
              IF (IARU(1, I) > 0.0) THEN
                RETURN
              END IF
            END DO
          END IF
          XML = 1555.00
        END IF
        MXL = INT(ABS(XML))
C * IN/EX-CLUDE RESIDUE (EG ARU 2)
        IF (MXL <= NRES) THEN
          IF (NARU > 0) THEN
            DO L = 1, NARU
              XMOLL = ABS (IARU(1, L) / PAR(42))
              MPM = NINT (XMOLL * PAR(42))
              CALL GEN098 (MPM, PAR(42), NSL2, ITX, ITY, ITZ, NR2)
              IF (MXL == NR2) THEN
                IARU(1, L) = NINT (SIGN (XMOLL, XML) * PAR(42))
              END IF
            END DO
          END IF
C * COLOR/RESD & PATTERN/RESD
          IF (MODE > 0) THEN
            IF (NMA == 1) THEN
              NCRS(NINT (XML)) = NMB
            ELSE
              NPRS(NINT (XML)) = NMB
            END IF
          END IF
          RETURN
        ELSE IF (MXL < 100) THEN
          WRITE (LUNIT, 99992, IOSTAT = IOST)
          RETURN
        END IF
C * UNPACK ARU
        MPM = NINT (XML * PAR(42))
        CALL GEN098 (MPM, PAR(42), NSLM, ITX, ITY, ITZ, NR)
C * CHECK VALIDITY OF THIS ARU
        IF (NSLM > NSYM .OR. NSLM == 0) THEN
          WRITE (LUNIT, 99999, IOSTAT = IOST) XML, NSLM
          RETURN
        END IF
C * SAVE FOR CALCULATION  C.G. OF NEW ARU
        SGY(4) = ITX
        SGY(5) = ITY
        SGY(6) = ITZ
        IF (NR > 0) THEN
C * CHECK VALIDITY OF RESIDUE NUMBER
          IF (NR > NRES) THEN
            WRITE (LUNIT, 99998, IOSTAT = IOST) XML, NR
            RETURN
          END IF
          NR1 = NR
          NR2 = NR
        ELSE
          NR1 = 1
          NR2 = NRES
        END IF
        DO NR = NR1, NR2
          IF (XML > 0) THEN
            XML =   MXL + NR / PAR(42)
          ELSE
            XML = - MXL - NR / PAR(42)
          END IF
          IF (IPR(20) > 0) THEN
            DO I = 1, 3
              SGY(I) = RCG(I, NR)
            END DO
            CALL SGSM (3, ICL, SGY, NSLM, LU6, IERR)
C * PACK PLANE TEST
            IF (IPR(36) /= 0) THEN
              DPLN = - RA(IPR(80) + 4)
              DO I = 1, 3
                DPLN = DPLN + SGY(I + 6) * RA(IPR(80) + I)
              END DO
              IF (DPLN > RA(IPR(80) + 6)) RETURN
              IF (DPLN < RA(IPR(80) + 5)) RETURN
            END IF
          END IF
C * CHECK FOR OCCURRENCE OF ARU XML IN THE ARU LIST
          NARU = IPR(42)
          IF (NARU > 0) THEN
            DO 10 L = 1, NARU
              XMOLL = ABS (IARU(1, L) / PAR(42))
              IF (ABS (ABS (XML) - XMOLL) < 0.005) GO TO 20
              IF (IPR(20) > 0) THEN
                MPM = NINT (XMOLL * PAR(42))
                CALL GEN098 (MPM, PAR(42), NSL2, ITX, ITY, ITZ, NR2)
                SGZ(4) = ITX
                SGZ(5) = ITY
                SGZ(6) = ITZ
                DO I = 1, 3
                  SGZ(I) = RCG(I, NR2)
                END DO
                CALL SGSM (3, ICL, SGZ, NSL2, LU6, IERR)
                DO I = 7, 9
                  IF (ABS (SGY(I) - SGZ(I)) > 0.001) GO TO 10
                END DO
                GO TO 20
              END IF
   10       CONTINUE
          END IF
          L       = IPR(42)
          IPR(42) = IPR(42) + 1
C * HANDLE INTER CASE
          IF (MODE < 0) THEN
            IARU(1, L + 1) = IARU(1, IPR(44) + 1)
            L             = IPR(44)
            IPR(44)       = IPR(44) + 1
C * HANDLE INTRA CASE
          ELSE
C * SHIFT ARU'S (WHEN NEEDED) TO INSERT RESIDUE
            LDIF = IPR(42) - IPR(75)
            IF (LDIF > 0) THEN
              IF (NINT ((XML - 1555.0) * PAR(42)) == IPR(75)) THEN
                DO M = 1, LDIF
                  IARU(1, L + 1) = IARU(1, L)
                  L = L - 1
                END DO
                DO M = IPR(39) + 1, IPR(37) + IPR(55)
                  CALL PLUT15 (-6, M, 11, LRES)
                  IF (LRES > IPR(75) - 2) THEN
                    IVAL = LRES + 1
                    CALL PLUT15 (6, M, 11, IVAL)
                  END IF
                END DO
              END IF
            END IF
          END IF
          IF (L < NP48) THEN
            IARU(1, L + 1) = NINT(XML * PAR(42))
          ELSE
            WRITE (LU6, 99990)
            STOP
          END IF
          IF (MODE > 0) THEN
            CALL GEN048 (5, IARU(2, L + 1), NMA, MAX (0, NMB))
          END IF
          GO TO 30
C * ARU PRESENT (SET ARU ON/OFF)
   20     L    = L - 1
          OXML = IARU(1, L + 1) / PAR(42)
          IF (MODE < 0 .AND. L >= IPR(44)) THEN
            IARU(1, L + 1) = IARU(1, IPR(44) + 1)
            L             = IPR(44)
            IPR(44)       = IPR(44) + 1
          END IF
          IF (XML < 0) THEN
            IARU(1, L + 1) = - NINT (ABS (OXML) * PAR(42))
          ELSE
            IARU(1, L + 1) =   NINT (ABS (OXML) * PAR(42))
            IF (MODE > 0)
     1         CALL GEN048 (5, IARU(2, L + 1), NMA, NMB)
          END IF
   30     MADDR = L
        END DO
C * MODE == 1001 - NONE/UNIQUE/INTER/RESTORE LIST INSTRUCTIONS
      ELSE IF (MODE == 1001) THEN
C * SET REBUILD
        IPR(130) = 0
        IF (IPR(17) == 0) THEN
          CALL PLUT05
        END IF
        IF (KL > 1) THEN
          N1 = IFL(2)(1:3)
C * ARU NONE CASE
          IF (N1 == 'NON') THEN
            ILAST = 0
C * ARU UNIQUE
          ELSE IF (N1 == 'UNI') THEN
            ILAST = IPR(43)
C * ARU INTER
          ELSE IF (N1 == 'INT') THEN
            ILAST = IPR(44)
C * ARU RESTORE
          ELSE IF (N1 == 'RES') THEN
            ILAST = NARU
          ELSE
            RETURN
          END IF
          DO I = 1, NARU
            XNM = ABS (IARU(1, I) / PAR(42))
            IF (I > ILAST) THEN
              IARU(1, I) = - NINT (XNM * PAR(42))
            ELSE
              IARU(1, I) =   NINT (XNM * PAR(42))
            END IF
          END DO
        END IF
C * COUNT THE ACTIVE NUMBER OF ASU'S
      ELSE IF (MODE == 1002) THEN
        IPR(159) = IPR(64) - IPR(52) * 2
        NMLX     = 0
        DO 40 I = 1, NARU
          XNM = INT (IARU(1, I) / PAR(42))
          IF (XNM > 0) THEN
            RA(IPR(159) - NMLX) = XNM
            IF (NMLX > 0) THEN
              DO J = 1, NMLX
                IF (RA(IPR(159) + 1 - J) == XNM) GO TO 40
              END DO
            END IF
            NMLX = NMLX + 1
          END IF
   40   CONTINUE
        IPR(142) = NMLX
C * UNIQUE AND HBOND ARU'S INACTIVE
      ELSE IF (MODE == 1003) THEN
        IPR(42) = IPR(44)
        NARU    = IPR(42)
        DO K = 1, NARU
          IARU(1, K) = - IABS (IARU(1, K))
        END DO
C * LIST ARU'S AND ASU'S
      ELSE IF (MODE == 1004) THEN
        WRITE (LUNIT, 99997, IOSTAT = IOST)
     1    IPR(43), IPR(44) - IPR(43), NARU, NRES
        IF (NARU /= 0) THEN
          DO I = 1, NARU
            CALL GEN098 (IARU(1, I), PAR(42), NSL2, ITX, ITY, ITZ, NR)
            ARU1 = '-         '
            ARU2 = ARU1
            ARU3 = ARU1
            CALL GEN048 (-5, IARU(2, I),  1, NARU1)
            IF (NARU1 > 0) ARU1 = COLR(NARU1)
            CALL GEN048 (-5, IARU(2, I),  6, NARU2)
            IF (NARU2 > 0) ARU2 = BWCT(NARU2)
            CALL GEN048 (-5, IARU(2, I), 11, NARU3)
            IF (NARU3 > 0) ARU3 = COLR(NARU3)
            CALL GEN048 (-5, IARU(2, I), 15, NARU4)
            IF (I == 1) WRITE (LUNIT, 99991, IOSTAT = IOST)
            NRESA = 9
            NRESB = 17
            IF (NR < 9)  NRESA = NCRS(NR)
            IF (NR < 17) NRESB = NPRS(NR)
            IF (IPR(134) > 9) THEN
              WRITE (LUNIT, 99996, IOSTAT = IOST)
     1          I, IARU(1, I) / PAR(42), ARU1, ARU2,
     2          ARU3, NARU4, COLR(NRESA), BWCT(NRESB)
            ELSE
              WRITE (LUNIT, 99995, IOSTAT = IOST)
     1          I, IARU(1, I) / PAR(42), ARU1, ARU2,
     2          ARU3, NARU4, COLR(NRESA), BWCT(NRESB)
            END IF
          END DO
          IF (IPR(130) == 1) THEN
            WRITE (LUNIT, 99993, IOSTAT = IOST) IPR(142)
            IM2 = IPR(159)
            IM1 = IM2 + 1 - IPR(142)
            WRITE (LUNIT, 99994, IOSTAT = IOST)
     1        (RA(IM2 + IM1 - I), I = IM1, IM2)
          END IF
        END IF
C * SPECIAL ARU EXCLUDE ON SERIAL #
      ELSE IF (MODE == 1005) THEN
        L = NINT (XMOLE)
        IF (L > 0) THEN
          IARU(1, L) = - IABS (IARU(1, L))
        ELSE
          WRITE (LU6, '(''Cannot exclude #'', I3)', IOSTAT = IOST) L
        END IF
      END IF
      RETURN
99999 FORMAT (':: ARU', F10.2, ' NOT Accepted (Check SYMM.Nr=', I3,')')
99998 FORMAT (':: ARU', F10.2, ' NOT Accepted (Check RESD.Nr=', I3,')')
99997 FORMAT (//, 'Asymmetric Residue Units :: UNIQUE =', I5,
     1        ', INTER =', I5, ', TOTAL =', I5, //,
     2        'The first', I3, ' refer(s) to 1555.nn ARU''s, the',
     3        ' next ones to _a, _b etc', /)
99996 FORMAT (I3, F12.2, 3(2X, A), I5, 2X, 2(2X, A))
99995 FORMAT (I3, F12.1, 3(2X, A), I5, 2X, 2(2X, A))
99994 FORMAT (8F9.0)
99993 FORMAT (/, '(Partially) ACTIVE Asymmetric Structure Units =',
     1        I5, /)
99992 FORMAT (':: Residue number out of range')
99991 FORMAT ('  #', 7X, 'ARU', 4X, 'ARUColor', 4X, 'ARUPattern ',
     1        'BondColor', 2X, '#Lines', 3X, 'ResColor',
     2        4X, 'ResPattrn')
99990 FORMAT (/, '> MOL ARRAY OVERFLOW IN PLUT17 <', /)
      END SUBROUTINE PLUT17
 
      SUBROUTINE PLUT18 (IAT, JAT)
C * GENERATE OBSCURATION LIST
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: MA
      INTEGER :: NJ
      INTEGER :: NL
      INTEGER :: NP
      INTEGER :: JO
      INTEGER :: II
      INTEGER :: IT
      INTEGER :: NPA
      INTEGER :: NLI
      INTEGER :: NAB
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: NDUM
      INTEGER :: MODE
      INTEGER :: MNRB
      INTEGER :: LABI
      INTEGER :: LRET
      INTEGER :: JEQM
      INTEGER :: JEQN
      INTEGER :: JLAB
      INTEGER :: JMAX
      INTEGER :: IVAL
      INTEGER :: IPOP
      INTEGER :: IPHI
      INTEGER :: ILPB
      INTEGER :: IASU
      INTEGER :: NRBD
      INTEGER :: NPROP
      INTEGER :: NOBSC
      INTEGER :: NINCL
      INTEGER :: INOBS
      INTEGER :: IABSNJ
      REAL :: X1
      REAL :: Y1
      REAL :: Z1
      REAL :: X2
      REAL :: Y2
      REAL :: Z2
      REAL :: RI
      REAL :: RJ
      REAL :: RM
      REAL :: RN
      REAL :: XN
      REAL :: YN
      REAL :: XJ
      REAL :: YJ
      REAL :: ZJ
      REAL :: XM
      REAL :: YM
      REAL :: ZM
      REAL :: BX
      REAL :: BY
      REAL :: BZ
      REAL :: CA
      REAL :: CX
      REAL :: CY
      REAL :: CZ
      REAL :: SA
      REAL :: ZN
      REAL :: XS
      REAL :: XT
      REAL :: YT
      REAL :: ZT
      REAL :: ZD
      REAL :: XTA
      REAL :: YTA
      REAL :: XMN
      REAL :: YMN
      REAL :: ZMN
      REAL :: RMJ
      REAL :: DL1
      REAL :: DL2
      REAL :: RBO
      REAL :: ZU7
      REAL :: ZU8
      REAL :: ZU9
      REAL :: ALF
      REAL :: ASQ
      REAL :: BET
      REAL :: YP12
      REAL :: YT12
      REAL :: YQ12
      REAL :: XP12
      REAL :: XQ12
      REAL :: XT12
      REAL :: ZP12
      REAL :: ZQ12
      REAL :: RSV1
      REAL :: RSV2
      REAL :: DL21
      REAL :: DL2C
      REAL :: ZMIN
      REAL :: ZMAX
      REAL :: ZT12
      REAL :: ZSMN
      REAL :: ZSJI
      REAL :: ZRMN
      REAL :: ZRIJ
      REAL :: CPHI
      REAL :: SPHI
      REAL :: ANG1
      REAL :: ANG2
      REAL :: ALFA
      REAL :: BSQ2
      REAL :: BSQ3
      REAL :: CSQ3
      REAL :: PHIQ
      REAL :: PHIP
      REAL :: RMNS
      REAL :: RTST
      REAL :: TANP
      REAL :: SNPHP
      REAL :: SNPHQ
      REAL :: RTEST
      REAL :: RMJSQ
      REAL :: PHIPX
      REAL :: PHIQX
      REAL :: CRADP
      REAL :: CRADQ
      REAL :: CSPHP
      REAL :: CSPHQ
      REAL :: ZTEST
      REAL :: ZMNJI
      REAL :: XMARG
      REAL :: RATIO
      REAL :: DMARG
      REAL :: ZIJMIN
C * SUBROUTINE CALLS - PLUT14, PLUT16
C * SUBROUTINE GENERATES A LIST OF OVERLAP SITUATIONS FOR
C *                        ATOMS, BONDS AND LABELS (ATOM & ARU'S)
C * MODE = 1 : ATOM - OVER - ATOM/LABEL  (JAT == 0)
C * MODE = 2 : ATOM - OVER - BOND
C * MODE = 3 : BOND - OVER - ATOM/LABEL  (JAT == 0)
C * MODE = 4 : BOND - OVER - BOND
C * ON LEAVING PLUT18, IPR(78) CONTAINS THE NUMBER OF OBSCURATIONS
C * IPR(78) = -1 - SKIP THIS PLOT ITEM
C * IPR(78) >  0 - NUMBER OF OBSCURATIONS
      J       = 0
      II      = 0
      NDUM    = 0
      MNRB    = 0
      NRBD    = 0
      IASU    = 0
      XP12    = 0.0
      YP12    = 0.0
      ZP12    = 0.0
      ZMN     = 0.0
      RMNS    = 0.0
      CPHI    = 0.0
      SPHI    = 0.0
      XN      = 0.0
      YN      = 0.0
      ZN      = 0.0
      ZMIN    = 0.0
      DMARG   = 0.0
      ZU7     = 0.0
      ZU8     = 0.0
      ZU9     = 0.0
      ZRIJ    = 0.0
      ZRMN    = 0.0
      CSPHP   = 0.0
      CSPHQ   = 0.0
      SNPHP   = 0.0
      SNPHQ   = 0.0
      PHIP    = 0.0
      RI      = 0.0
      RJ      = 0.0
      DL1     = 0.0
      PHIQ    = 0.0
      XQ12    = 0.0
      YQ12    = 0.0
      ZIJMIN  = 0.0
      ZJ      = 0.0
      ZQ12    = 0.0
      XMARG   = PAR(36)
C * INITIALISE OBSCURATION STACK
      IPR(78) = 0
      ILPB    = IPR(69) + 1
      NAB     = IPR(37) - IPR(69)
C * GET NR OF ATOM TYPE PLOT-ITEMS = NPA IN PLOT-ARRAY
      NPA     = IPR(62)
      JMAX    = NPA
C * GET TOTAL NUMBER OF PLOT ITEMS = NP ( = ATOMS + LABELS)
      NP      = IPR(40)
      M       = IAT
      MA      = M
      N       = JAT
      IF (N > 0) THEN
C * BOND OVERLAP TEST
        MODE = 2
      ELSE
C * ATOM OR LABEL OVERLAP TEST
        MODE = 1
      END IF
      RTEST = PAR(149) * PAR(24)
      LRET  = 1
      CALL PLUT14 (-1, M, IASU, NPROP, XM, YM, ZM, RM)
      LABI = 0
C * ATOMS AND LABEL PLOT-ITEMS ONLY
      IF (M <= NP) THEN
C * TEST FOR LABEL ITEM
        IF (M > NPA) THEN
C * HANDLE LABEL CASE
           LABI  = M - NPA
C * SIMULATE LABEL WITH A BOND BETWEEN TWO PSEUDO ATOMS M AND N
           XP12  = XM
           YP12  = YM
           ZP12  = ZM
           ZMN   = 0.0
           RMNS  = 2 * RM
           DL2   = RM
           PHIP  = 0.0
           CPHI  = 1.0
           SPHI  = 0.0
           XN    = XM + RM
           XM    = XM - RM
           RM    = PAR(28)
           RN    = RM
           YN    = YM
           ZN    = ZM
           M     = NP + 1
           N     = NP + 2
           MODE  = 2
           JMAX  = NP
           RSV1  = RM
           RSV2  = RN
           ZMIN  = ZM - RM
           XMARG = 0
           GO TO 20
        END IF
      END IF
C * TEST FOR ATOM OR BOND OVERLAP LIST CASE
   10 IF (MODE > 1) THEN
        I    = N * NP0 + IPR(158)
        ZN   = RA(I - 1)
        RN   = RA(I)
        IF (MODE == 4) THEN
C * TEST WHETHER BOND M TO N IS ENTIRELY BELOW BOND J TO I
C * M & J ARE RESPECTIVE HIGHEST BOND END-POINTS
          ZMAX = MAX (ZM + RM, ZN + RN)
          IF (ZMAX < ZIJMIN) GO TO 90
        END IF
        XN   = RA(I - 3)
        YN   = RA(I - 2)
        ZMIN = MIN (ZM - RM, ZN - RN)
        RSV1 = RM
        RSV2 = RN
        XMN  = XM - XN
        YMN  = YM - YN
        ZMN  = ZM - ZN
        ASQ  = XMN**2 + YMN**2
        RMNS = ASQ + ZMN**2
        DL21 = SQRT (ASQ)
        DL2  = DL21 / 2.0
C * CALCULATE MIDPOINT BOND M-N
        XP12 = (XM + XN) / 2
        YP12 = (YM + YN) / 2
        ZP12 = (ZM + ZN) / 2
        IF (DL21 /= 0.0) THEN
          ZRMN = ZMN * RN / DL21
          PHIP = ATAN2 (YMN, XMN)
          CPHI = -XMN / DL21
          SPHI = -YMN / DL21
        ELSE
C * ? DL21 CASE RN
          ZRMN = RN
          PHIP = 0.0
          CPHI = 1.0
          SPHI = 0.0
        END IF
        CSPHP = COS (PHIP)
        SNPHP = SIN (PHIP)
        IF (MODE == 4) THEN
C * TEST FOR BOND/BOND - OVERLAP CASE
          PHIQX =   PHIQ - PHIP
          PHIPX = - PHIQX
C * ROTATE BONDS OVER PHIQ AND TRANSLATE ORIGIN TO BOND I-J CENTER
          XT12  =   XP12 - XQ12
          YT12  =   YP12 - YQ12
C * XT, YT, ZT ARE COORDINATES CENTRE BOND M-N IN NEW (ROTATED) SYSTEM
          XT    =   XT12 * CSPHQ + YT12 * SNPHQ
          YT    = - XT12 * SNPHQ + YT12 * CSPHQ
          ZT    =   ZP12 - ZQ12
C * TEST FOR BOND/BOND INTERSECTION
          CALL PLUT20 (DL1 + ZRIJ , RJ, RI, DL2 + ZRMN, RM, RN,
     1      PHIPX, XT, YT, IT, XMARG)
C * GOTO NEXT BOND WHEN NO INTERSECTION FOUND FOR THIS BOND
          IF (IT == 0) THEN
            GO TO 90
          ELSE
C * REVERSE TEST ORDER
C * ROTATE OVER PHIP AND TRANSLATE ORIGIN TO BOND M-N CENTER
            XTA = - XT12 * CSPHP - YT12 * SNPHP
            YTA =   XT12 * SNPHP - YT12 * CSPHP
C * TEST FOR BOND/BOND INTERSECTION
            CALL PLUT20 (DL2 + ZRMN, RM, RN, DL1 + ZRIJ, RJ, RI,
     1        PHIQX, XTA, YTA, IT, XMARG)
            IF (IT == 0) GO TO 90
          END IF
C * FIND OUT WHERE THE BONDS INTERSECT IN Z
C * CALCULATION IS NOT EXACT FOR NON-PARALLEL PERSPECTIVE
          IPHI = MOD (NINT (ABS (PHIQX * RGBL(6) * 10.0)), 1800)
          ALF  = 0.0
          BET  = 0.0
C * TEST FOR PARALLEL BONDS (KIND = 2)
          IF (IPHI == 0) THEN
C * SPECIAL PARALLEL BOND CASE HANDLING
            IF (ABS (ZT) > 0.001)  THEN
              IF (ZT < 0.0) THEN
                GO TO 90
              ELSE
                GO TO 50
              END IF
            END IF
            IF (IPR(56) >= NRBD)    GO TO 90
            IF (IPR(56) <= IPR(68)) GO TO 90
C * SKIP THIS BOND BECAUSE OF REDUNDANCY
            GO TO 100
C * TEST FOR PERPENDICULAR BONDS (KIND = 1)
          ELSE IF (IPHI == 900) THEN
C * SPECIAL PERP BOND CASE HANDLING
            IF (DL2 > 0.0) ALF = -YT / DL2
            IF (DL1 > 0.0) BET =  XT / DL1
          ELSE
            TANP = TAN (PHIPX)
            XS   = (XT * TANP - YT) / TANP
            DL2C = DL2 * COS (PHIPX)
            IF (DL2C > 0.0) ALF = (XS - XT) / DL2C
            IF (DL1  > 0.0) BET =  XS / DL1
          END IF
C * GET Z-VALUES AT 'INTERSECTION' AND DIFFERENCE
          ZSJI  = (ZJ - ZQ12) * BET
          ZSMN  = (ZM - ZP12) * ALF + ZT
          ZMNJI = ZSMN - ZSJI
C * GET SHORT BOND-BOND CONTACT DISTANCE (APPROXIMATE)
          CRADP = (RM + RN) / 2.0
          CRADQ = (RJ + RI) / 2.0
          IF (ABS (ZMNJI) > 0.01) THEN
            IF (ABS (ALF) < 1.0 .AND. ABS (BET) < 1.0) THEN
C * TEST WHETHER BOND M-N PASSES BEHIND BOND J-I
C *             IF (ZMNJI < - (CRADP + CRADQ)) GO TO 90
C * CHANGED TO HANDLE DISORDER
              IF (ZMNJI < + (CRADP + CRADQ)) GO TO 90
            ELSE
              IF (ZT < (CRADP + CRADQ)) GO TO 90
            END IF
          ELSE
C * BONDS JOIN ( ABS(ALF) & ABS(BET) > 0)
            IF (ZT < 0.0) GO TO 90
          END IF
          GO TO 50
        ELSE IF (MODE == 3) THEN
          GO TO 40
        END IF
      END IF
C * GET LIST OF ATOMS WHICH OBSCURE ATOM M (OR BOND (M-N))
C * THIS ALLOWS FOR INTERSECTION OF SPHERES IN V.D. WAALS MODELS
   20 NL = 0
      J  = IPR(69)
      IF (LABI > 0) THEN
C * STICK & CPK-STICK CASE
        IF (IPR(4) <= 0) THEN
          J = NPA
        END IF
      END IF
C * GENERATE BRIGHT SPOT
      IF (MODE == 1) THEN
        IF (IPR(96) == 1) THEN
          ANG1 = PAR(51) / RGBL(6)
          ANG2 = PAR(52) / RGBL(6)
          CA   = COS (ANG1)
          SA   = SIN (ANG1)
          YJ   = YM + RM * SA / 2
          ZJ   = RM * CA / 2
          RJ   = RM / PAR(53)
          CA   = COS (ANG2)
          SA   = SIN (ANG2)
          ZD   = ZJ
          XJ   = XM + ZD * SA
          ZJ   = ZM + ZD * CA
          NJ   = 0
          CALL PLUT14 (0, NJ, IASU, NPROP, XJ, YJ, ZJ, RJ)
          NJ   = - NJ
          GO TO 50
        END IF
      END IF
   30 J = J + 1
      IF (J > JMAX)  GO TO 70
      IF (MODE < 3) THEN
C * SKIP IN CASE OF AUTO OVERLAP (ATOM-ATOM OR LABEL-ATOM)
        IF (J == MA)  GO TO 30
C * SKIP LABEL TO PARENT ATOM OVERLAP
        IF (LABI > 0) THEN
          IF (IGBL(75) == 1) THEN
             IF (LABI <= IPR(37)) THEN
               IF (LABI == J) GO TO 30
             ELSE
               IF ((LABI - NAB) == J) GO TO 30
             END IF
          ELSE
             IF (LABI == (J - IPR(69))) GO TO 30
          END IF
        END IF
      END IF
      JLAB = J - NPA
      IF (JLAB <= 0) THEN
        JO = MOD (J - ILPB, NAB) + ILPB
        CALL PLUT15 (-1, JO, 27, NINCL)
        IF (NINCL == 0) GO TO 30
      END IF
      I   = J * NP0 + IPR(158)
      XJ  = RA(I - 3)
      YJ  = RA(I - 2)
      ZJ  = RA(I - 1)
      RJ  = RA(I    )
C * SKIP VIRTUAL OR EXCLUDED ATOMS
      IF (JLAB > 0) THEN
C * HANDLE LABEL-LABEL OVERLAP
        IF (JLAB <= (IPR(37) * IGBL(75))) THEN
          IF (IPR(46) == 0 .AND. JLAB <= IPR(69)) GO TO 30
C * DO NOT CONSIDER UNSETTLED OR NOT INCLUDED LABELS
          CALL PLUT15 (-4, JLAB, 37, IVAL)
          IF (IVAL <= 1) GO TO 30
        ELSE
C * DO NOT CONSIDER UNSETTLED MOL LABELS
          IF (J > MA) GO TO 30
        END IF
        BX = ABS (XP12 - XJ)
        BY = ABS (YP12 - YJ)
        IF ((BY < 2.0 * PAR(28)) .AND. (BX < DL2 + RJ)) GO TO 100
      END IF
C * CHANGED FROM 499.9 TO 499.99 (16/11/02)
      IF (ABS (RJ - 500.0) > 499.99)  GO TO 30
      RSV1 = RJ
   40 BX   = XJ - XM
      BY   = YJ - YM
      BZ   = ZJ - ZM
C * J AND M ARE CONSIDERED EQUIVALENT WHEN THE DISTANCE BETWEEN THEIR
C * CENTRES IS LESS THAN RJ
      JEQM = 0
      BSQ2 = BX**2 + BY**2
      BSQ3 = BSQ2  + BZ**2
      IF (BSQ3 < RTEST) JEQM = 1
      IF (MODE == 1) THEN
C * SKIP THIS OVERLAP FOR J EQUIV M
        IF (JEQM /= 0) THEN
          IF (M <= J)  GO TO 30
C * SKIP THIS PLOT ITEM
          GO TO 100
        END IF
C * TEST WHETHER SPHERE J IS BELOW SPHERE M
        IF (BZ < - RJ)  GO TO 30
C * INTERSECTING SPHERES ARE MARKED WITH NEGATIVE J
        RMJ   = RM + RJ
C * COMPLETELY OVERLAPPED ATOM
        IF (BSQ2 < PAR(24) * 0.01) THEN
        END IF
C * TEST FOR INTERSECTING CIRCLES M AND J
        RMJSQ = RMJ**2
        IF (BSQ2 > RMJSQ)  GO TO 30
C * ENVELOPE CIRCL INTERS. IN PROJ. DOWN ZP - TEST FOR SPHERE INTERS.
        IF (BSQ3 < RMJSQ) THEN
          NJ = - J
        ELSE
          NJ = J
        END IF
      ELSE
C * BOND OVERLAP CASE
        CX = XJ - XN
        CY = YJ - YN
        CZ = ZJ - ZN
C * TEST FOR CASE J.EQ.N
        JEQN = 0
        CSQ3 = CX**2 + CY**2 + CZ**2
        IF (CSQ3 < RTEST) JEQN = 1
        IF (MODE == 3) THEN
C * SKIP THIS BOND WHEN ZJ ABOVE ZN AND ZM
          IF (BZ > RJ)  GO TO 90
          RSV1 = RN
          IF (JEQN /= 0 .OR. JEQM /= 0) THEN
C * BOND M-N EMERGES FROM ATOM J, GENERATE AUXILLARY PSEUDO ATOM AT
C *      THE POINT WHERE THE BOND INTERSECTS THE SPHERE
            IF (JEQN /= 1) THEN
              NJ = - N + 1
              NL = N
              IF (ZMN >= 0.0001 .AND. RM > 0.001) THEN
                RATIO = RN * SQRT (RMNS) / (RM * ZMN)
                IF (RATIO <= 1)  GO TO 90
              END IF
            ELSE
              NL   = N - 1
              NJ   = - N
              CPHI = - CPHI
              SPHI = - SPHI
            END IF
            GO TO 50
          END IF
C * TEST FOR BOND-CIRCLE INTERSECTION
        ELSE IF (LABI <= 0) THEN
          IF (JEQN == 1)  GO TO 30
          IF (CZ < 0)  GO TO 30
        END IF
C * TEST FOR ATOM/BOND INTERSECTION
        CALL PLUT20 (-1.0, RJ, 0.0, DL2, RM, RN, PHIP, XP12 - XJ,
     1   YP12 - YJ, IT, XMARG)
        IF (IT == 0)  THEN
          IF (LRET == 1) THEN
            GO TO 30
          ELSE IF (LRET == 2) THEN
            GO TO 90
          END IF
        END IF
C * THIS ATOM J / BOND (N-M) INTERSECTS IN PROJECTION (MODE 2 & 3)
C * SHIFT BOND M-N AND ATOM J TO ORIGIN AT BOND CENTRE
        XT12  = XJ - XP12
        YT12  = YJ - YP12
        ZT12  = ZJ - ZP12
C * ROTATE OVER PHIP
        XT    = XT12 * CSPHP + YT12 * SNPHP
        ZTEST = ZT12
        IF (DL2 > 0.0) ZTEST = ZTEST + (ZP12 - ZM) * XT / DL2
C * FIRST APPROXIMATION !
        RTST = (RM + RN) / 2.0 + RJ
C * ATOM OVER BOND CASE
        IF (MODE == 2) THEN
          NJ = J
          IF (BSQ3 < RJ**2) THEN
            NJ = - IABS (J)
          ELSE
            IF (JEQN == 0) THEN
              IF (ZTEST < RTST) GO TO 30
            END IF
          END IF
C * BOND OVER ATOM CASE (MODE = 3)
        ELSE
          IF (JEQN + JEQM == 0) THEN
C * CHANGED TO HANDLE DISORDER
            IF (ZTEST + RTST >= 0.0) GO TO 90
          END IF
        END IF
      END IF
C * ENTER THIS ATOM OR BOND TO THE OBSCURING LIST
   50 IABSNJ = IABS (NJ)
      CALL PLUT14 (-1, IABSNJ, IASU, NPROP, X1, Y1, Z1, RSV1)
C * BUT AVOID MULTIPLE ENTRY DUE TO SYMMETRY
      NOBSC = IPR(78)
      IPOP  = IPR(66)
      IF (NOBSC > 0) THEN
        DO INOBS = 1, NOBSC
          IPOP = IPOP - 13
          IF (ABS (RA(IPOP + 3) - X1) + ABS (RA(IPOP + 4) - Y1) +
     1          ABS (RA(IPOP + 5) - Z1) < 0.01) GO TO 60
        END DO
      END IF
C * STORE THIS OBSCURATION (WITH OVERLAP TYPE VIA +/- INDICATION)
C * NORMAL BOND OVERLAP        :     +NJ    +NL
C * INCOMING BOND IN SPHERE    :     -NJ    +NL
C * NORMAL OVERLAPPING SPHERE  :     +NJ     0
C * INTERPENETRATING SPHERE    :     -NJ     0
      IPR(78) = IPR(78) + 1
      IPOP    = IPR(66) - IPR(78) * 13
      IF (IPOP >= IPR(158) + (IPR(40) + IPR(67) + 1) * NP0) THEN
        RA(IPOP + 1) = NJ
        RA(IPOP + 2) = NL
        RA(IPOP + 3) = X1
        RA(IPOP + 4) = Y1
        RA(IPOP + 5) = Z1
        RA(IPOP + 6) = RSV1
        IF (NL /= 0) THEN
          CALL PLUT14 (-1, NL, IASU, NPROP, X2, Y2, Z2, RSV2)
          RA(IPOP + 7)  = RSV2
          RA(IPOP + 8)  = DL2
          RA(IPOP + 9)  = CPHI
          RA(IPOP + 10) = SPHI
          RA(IPOP + 11) = XP12
          RA(IPOP + 12) = YP12
        END IF
C * SAVE APPROPRIATE MARGIN
        IF (MODE < 4) THEN
          IF (NJ > 0) THEN
            DMARG = XMARG
          ELSE
            IF (MODE == 2) THEN
              DMARG = 0.0
            ELSE IF (MODE == 3) THEN
              IF (Z2 > Z1) THEN
C * SET SHADOW MARGIN
                IF (DL2 > 0.0) THEN
                  ALFA  = ATAN ((Z2 - Z1) / (DL2 * 2.0))
                ELSE
                  ALFA  = 90.0 / RGBL(6)
                END IF
                DMARG = PAR(58) * SIN (ALFA)
              ELSE
                DMARG = 0.0
              END IF
            ELSE
              DMARG = XMARG
            END IF
          END IF
        ELSE IF (MODE == 4) THEN
          DMARG = XMARG
        END IF
C * HANDLE PERSPECTIVE
        IF (PAR(48) > 0.0) DMARG = DMARG * PAR(48) / (PAR(48) - Z1)
        RA(IPOP + 13) = DMARG
      ELSE
        IPR(78) = IPR(78) - 1
      END IF
      NDUM = 0
   60 IF (LABI /= 0) THEN
C * QUIT OVERLAP SEARCH WHEN MORE THAN 2 ITEMS OVERLAPPING LABEL FOUND
        IF (IPR(78) >= 2) RETURN
      END IF
      IF (LRET == 1) THEN
        GO TO 30
      ELSE IF (LRET == 2) THEN
        GO TO 90
      END IF
C * NOW CONSIDER BOND/ATOM AND BOND/BOND OVERLAP
   70 IF (LABI <= 0) THEN
C * SKIP IF NO BOND-OVERLAP TEST REQUESTED
        IF (IPR(77) == 0) RETURN
        IF (MODE == 2 .AND. IABS (IPR(77)) > 1)  GO TO 80
        IF (IABS (IABS (IPR(77)) - 2) /= MODE) RETURN
      END IF
C * START FOR LOOP OVER BONDS
   80 MODE = MODE + 2
      XJ   = XM
      YJ   = YM
      ZJ   = ZM
      RJ   = RM
      LRET = 2
C * TEST FOR BOND OVER ATOM OVERLAP AND COPY DATA
      IF (MODE == 3) THEN
        J      = M
        RTEST  = RJ**2
C * TEST FOR BOND OVER BOND OVERLAP AND COPY DATA
      ELSE IF (MODE == 4) THEN
        RI     = RN
        PHIQ   = PHIP
        CSPHQ  = CSPHP
        SNPHQ  = SNPHP
        DL1    = DL2
        XQ12   = XP12
        YQ12   = YP12
        ZQ12   = ZP12
        ZIJMIN = ZMIN
        ZRIJ   = ZRMN
C * SAVE ZU7-ZU9
        ZU7    = ZU(7)
        ZU8    = ZU(8)
        ZU9    = ZU(9)
      END IF
C * LOOP OVER RELEVANT AND ACTIVE BONDS
      NRBD = 0
      NDUM = 0
      IF (IPR(4) > 0) THEN
        MNRB = IPR(97)
      ELSE
        MNRB = 0
      END IF
   90 NRBD = NRBD + 1
      IF (NRBD > MNRB) THEN
        IF (MODE == 4) THEN
C * RESTORE BOND INFORMATION FOR BOND ENDPOINTS IAT AND JAT
          ZU(7) = ZU7
          ZU(8) = ZU8
          ZU(9) = ZU9
        END IF
        RETURN
      END IF
      IPR(67) = IPR(67) - NDUM
      CALL PLUT16 (NRBD, II, M, N, RBO, NLI)
      IF (NLI < 0) NLI = IABS (NLI)
      NDUM = 2
C * SKIP SELF-OVERLAP OF BOND
      IF (MODE == 4) THEN
        IF (IPR(56) == NRBD) GO TO 90
      END IF
      IF (M == 0) GO TO 90
C * SCALE AND ADD OVERLAP MARGIN (TO) BOND RADIUS
      N  = IPR(67) + NP
      M  = N - 1
      NJ = M
      NL = N
      I  = M * NP0 + IPR(158)
      XM = RA(I - 3)
      YM = RA(I - 2)
      ZM = RA(I - 1)
      RM = RA(I    )
      GO TO 10
  100 IPR(78) = -1
      RETURN
      END SUBROUTINE PLUT18
 
      SUBROUTINE PLUT19 (M, MODE)
C * DRAW OBJECT, TAKING OBSCURATION LIST INTO ACCOUNT
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: NL
      INTEGER :: IP1
      INTEGER :: IP2
      INTEGER :: IPP
      INTEGER :: ITF
      INTEGER :: ITS
      INTEGER :: IUP
      INTEGER :: JNL
      INTEGER :: NPP
      INTEGER :: NRF
      INTEGER :: NRF1
      INTEGER :: IPOP
      INTEGER :: MODE
      INTEGER :: NINC
      INTEGER :: NOBSC
      INTEGER :: IDOWN
      INTEGER :: IDRAW
      INTEGER :: ISLOW
      INTEGER :: ISTEP
      INTEGER :: JMODE
      INTEGER :: LDRAW
      REAL :: X
      REAL :: Y
      REAL :: Z
      REAL :: X0
      REAL :: Y0
      REAL :: XA
      REAL :: YA
      REAL :: ZA
      REAL :: DL
      REAL :: CX
      REAL :: CY
      REAL :: SX
      REAL :: SY
      REAL :: RK
      REAL :: RM
      REAL :: XK
      REAL :: YK
      REAL :: ZK
      REAL :: XM
      REAL :: YM
      REAL :: ZM
      REAL :: XX
      REAL :: YY
      REAL :: XA0
      REAL :: YA0
      REAL :: RMS
      REAL :: RNL
      REAL :: RKB
      REAL :: RKS
      REAL :: DL2
      REAL :: DSQ
      REAL :: DUM
      REAL :: DXK
      REAL :: DYK
      REAL :: DZK
      REAL :: DZS
      REAL :: DXM
      REAL :: DYM
      REAL :: XP12
      REAL :: YP12
      REAL :: SPHI
      REAL :: DELX
      REAL :: DELY
      REAL :: DELZ
      REAL :: D3SQ
      REAL :: CPHI
      REAL :: RBND
      REAL :: DELXN
      REAL :: DELYN
      REAL :: DELZN
      REAL :: DMARG
      REAL :: RADIUS
C * MODE = 0    - DRAW CIRCLE MODE (CIRCLE PLOT TEST)
C *             - M == 0 FOR NORMAL CIRCLE PLOT
C *             - M > 0 FOR REAL OR DUMMY ATOM SPHERE INTERSECTION PLOT
C * MODE = +/-  - DRAW LINE MODE (LINE PLOT TEST)
C *             - M == 0 FOR BOND PLOT
C *             - M /= 0 FOR SHADE OR DOT PLOT OF ATOM M
      IUP     = 0
      IPP     = 0
      NINC    = 0
      ISLOW   = 0
      NOBSC   = IPR(78)
      IPR(98) = 0
      IDOWN   = 3
      LDRAW   = 0
      IDRAW   = 3
      ISTEP   = 1
      DELX    = 0.0
      DELY    = 0.0
      DELZ    = 0.0
      DL      = 0.0
      DZS     = 0.0
      RADIUS  = 0.0
      CX      = 0.0
      SX      = 0.0
      CY      = 0.0
      SY      = 0.0
      RNL     = 0.0
      DL2     = 0.0
      CPHI    = 0.0
      SPHI    = 0.0
      XP12    = 0.0
      YP12    = 0.0
      DYM     = 0.0
      DXM     = 0.0
      RMS     = 0.0
      ZM      = 0.0
C * TEST FOR LINE OR DOT MODE
      IF (MODE /= 0) THEN
        IF (MODE < 0) THEN
          NRF  = 3
          NRF1 = 0
        ELSE
          NRF  = 0
          NRF1 = 3
        END IF
        X    = XYZPL(NRF  + 1)
        Y    = XYZPL(NRF  + 2)
        Z    = XYZPL(NRF  + 3)
        DELX = XYZPL(NRF1 + 1) - X
        DELY = XYZPL(NRF1 + 2) - Y
        DELZ = XYZPL(NRF1 + 3) - Z
C * HANDLE STICK COLOR MODE
        IF (IPR(4) == 0) THEN
          IF (IPR(346) == 1) THEN
            DELX = DELX / 2.0
            DELY = DELY / 2.0
            DELZ = DELZ / 2.0
          END IF
        END IF
        DL = SQRT (DELX ** 2 + DELY ** 2)
        IF (NOBSC > 0) THEN
          NINC = (INT (DL / PAR(5)) + 1) * IPR(111)
          DELX = DELX / NINC
          DELY = DELY / NINC
          DELZ = DELZ / NINC
        ELSE
          NINC  = 1
        END IF
        IF (NOBSC > 0) THEN
          IF (M /= 0) THEN
C * GET COORDINATES AND RADIUS OF ATOM TO SHADE
            XM  = XYZK(1)
            YM  = XYZK(2)
            ZM  = XYZK(3)
            RM  = XYZK(4)
            RMS = RM ** 2
            DXM = X - XM
            DYM = Y - YM
            DZS = (Z - ZM) ** 2
          END IF
        END IF
        GO TO 50
C * MODE = 0 : CIRCLE PLOT TEST SECTION
      ELSE
C * GET NUMBER OF POINTS = SEGMENTS
        NPP = IPR(91) * IPR(87)
C * SKIP OBSCURATION LOOP WHEN NO OBSCURATIONS AND NON-GLOBE MODE
        IF (NOBSC == 0 .AND. IPR(139) == 0 .AND.
     1      IPR(162) /= 8 .AND. IPR(162) /= 9) THEN
           CALL PLUT30 (0, NPP)
           RETURN
        ELSE
          RADIUS = PAR(74)
C * DEFINE ANGLE INCREMENT
          CX     = COS (PAR(55))
          SX     = SIN (PAR(55))
C * DEFINE STARTING POINT
          CY     = COS (PAR(57))
          SY     = SIN (PAR(57))
          IUP    = 1
          ITS    = 0
          ITF    = 0
          IPP    = -1
          GO TO 40
        END IF
      END IF
C * AN OBSCURING ATOM HAS BEEN FOUND IN CIRCLE MODE, LIFT THE PEN.
   10 IF (IUP == 0) ITF = IPP - 1
      IUP = 1
      GO TO 30
C * NO OBSCURING IN CIRCLE MODE SO GO AHEAD WITH PLOTTING OF THIS STEP.
   20 IF (IUP == 1) THEN
        CALL PLUT30 (ITS, ITF)
        ITS = IPP
      END IF
      ITF = IPP
      IUP = 0
C * NEXT POINT OF CIRCLE
   30 DUM = CY * CX - SY * SX
      SY  = SY * CX + CY * SX
      CY  = DUM
   40 IPP = IPP + 1
      IF (IPP > NPP) THEN
C * OUTPUT (FINAL) RESULT AND RETURN
        CALL PLUT30 (ITS, ITF)
        RETURN
      END IF
      XX = CY * RADIUS
      YY = SY * RADIUS
      Z  = ZU(3) * XX + ZU(6) * YY + PAR(73)
C * NOW PLOT THIS POINT, TEST FOR OBSCURATION
      IF (XYZK(3) > Z) GO TO 10
      X = ZU(1) * XX + ZU(4) * YY + PAR(71)
      Y = ZU(2) * XX + ZU(5) * YY + PAR(72)
C * START LOOP OVER OBSCURATIONS
C * NORMAL BOND OVERLAP        :     +J    +NL  : JNL = 3
C * INCOMING BOND IN SPHERE    :     -J    +NL  :     = 2
C * NORMAL OVERLAPPING SPHERE  :     +J     0   :     = 1
C * INTERPENETRATING SPHERE    :     -J     0   :     = 0
   50 JMODE = - 1
      IPOP  = IPR(66)
   60 IF (JMODE + NOBSC >= 0) THEN
        IPOP  = IPOP  - 13
        JMODE = JMODE - 1
        J     = NINT (RA(IPOP + 1))
        IF (J > 0) THEN
          K   = J
          JNL = 1
        ELSE
          K   = - J
          JNL = 0
        END IF
        NL  = NINT(RA(IPOP + 2))
        XK  = RA(IPOP + 3)
        YK  = RA(IPOP + 4)
        ZK  = RA(IPOP + 5)
        RK  = RA(IPOP + 6)
        RKB = RK
        IF (NL > 0) THEN
          JNL  = JNL + 2
          RNL  = RA(IPOP + 7)
          DL2  = RA(IPOP + 8)
          CPHI = RA(IPOP + 9)
          SPHI = RA(IPOP + 10)
          XP12 = RA(IPOP + 11)
          YP12 = RA(IPOP + 12)
        END IF
        DMARG = RA(IPOP + 13)
C * TEST FOR OVERLAP BY ATOM OR INCOMING BOND CASE
        IF (JNL < 3) THEN
C * TEST WHETHER POINT X,Y,Z IS OUTSIDE SPHERE OF RADIUS RK
          DXK = X - XK
          DYK = Y - YK
          DZK = Z - ZK
          DSQ = DXK**2 + DYK**2
          IF (MODE == 0) THEN
C * OVERLAP BY NON-INTERSECTING ATOM
            IF (JNL == 1 .AND. M == 0) THEN
              RK = RK + DMARG
            ELSE IF (JNL > 0) THEN
              IF (M /= 0) THEN
                RK = RK + DMARG
              ELSE
                DMARG = 0.0
              END IF
            END IF
          ELSE
C * MODE /= 0 (DMARG = 0 FOR MODE 3, J < 0)
            RK = RK + DMARG
          END IF
          RKS = RK**2
C * POINT XK, YK IS OBSCURED WHEN WITHIN ENVELOPE CIRCLE K AND ZK > Z
          IF (DSQ < RKS) THEN
C * BOND - ENDPOINT OVERLAP CASE TEST (LINE)
            IF (MODE /= 0 .AND. J < 0) THEN
              IF (DZK < 0.0) GO TO 70
            ELSE IF (J > 0 .OR. MODE == 0) THEN
              IF (DZK <= 0.0)  GO TO 70
            ELSE
C * POINT WITHIN SPHERE TEST
              D3SQ = DSQ + DZK**2
              IF (D3SQ < RKS)  GO TO 70
            END IF
          END IF
          IF (MODE /= 0) THEN
C * LINE  MODE /= 0
            IF (M /= 0) THEN
              IF (RKS >= DSQ) THEN
C * TEST WHETHER X, Y, Z IN SPHERE K
                IF (DZS < 0)  GO TO 70
                DZK = SQRT (DZS) + ZM - ZK
                DSQ = DSQ + DZK**2
                IF (DSQ < RKS)  GO TO 70
              END IF
            END IF
          ELSE
C * CIRCLE MODE = 0 CASE
            IF (J < 0) THEN
C * POINT IS OBSCURED IF WITHIN SPHERE J
              IF (K /= M) THEN
                DZK = Z - ZK
                DSQ = DSQ + DZK**2
                IF (DSQ < RKS)  GO TO 70
              END IF
            END IF
          END IF
          IF (NL == 0)  GO TO 60
        END IF
        IF (M > 0 .OR. J < 0) THEN
          IF (XYZK(3) >= ZK)  GO TO 60
        END IF
C * SET BOND RADIUS EQUAL TO PSEUDO ATOM RADII
C * TEST WHETHER X,Y IS WITHIN BOND
C * ROTATE AXIS SYSTEM (X,Y) SUCH THAT BONDS ARE ALONG X-NEW
        X0  = X - XP12
        Y0  = Y - YP12
        XA0 = CPHI * X0 + SPHI * Y0
        IF (ABS (XA0) > DL2)  GO TO 60
        YA0 = -SPHI * X0 + CPHI * Y0
C * CALCULATE THICKNESS OF BOND AT XA0 (WITH MARGIN)
        IF (DL2 /= 0) THEN
          RBND = ((RKB + RNL) + (RNL - RKB) * XA0 / DL2) / 2.0 + DMARG
        ELSE
          RBND = DMARG
        END IF
        IF (ABS(YA0) > RBND)  GO TO 60
C * OBSCURED POINT FOUND, MAKE THIS OBSCURATION AS THE FIRST ONE IN THE
C * LIST (EXCHANGE) EXCEPT FOR SPHERE INTERSECTION CASE
   70   IF (JMODE < -2) THEN
          IF (M <= 0) THEN
            IP1 = IPR(66) - 13
            IP2 = IPR(66) + (JMODE + 1) * 13
            DO I = 1, 13
              DUM         = RA(IP1 + I)
              RA(IP1 + I) = RA(IP2 + I)
              RA(IP2 + I) = DUM
            END DO
          END IF
        END IF
        IF (MODE == 0) GO TO 10
        IDRAW = 3
      ELSE
C * END OF OBSCURATION LOOP - NO OBSCURATION FOUND FOR THIS POINT
        IF (MODE == 0) GO TO 20
        IDRAW = 2
      END IF
C * IDRAW SIGNALS WHETHER TO DRAW THE LINE AT THE CURRENT POINT
C * (IDRAW = 3/2 FOR NO/YES)
C * IDOWN RECORDS THE APPARENT STATUS OF THE PEN = 3/2 FOR UP/DOWN
      IF (LDRAW /= IDRAW) THEN
C * LDRAW /= 0
        IF (LDRAW /= 0) THEN
          IF (ISTEP > 1) THEN
C * RETEST WITH SMALL STEP
            ISTEP = 1 - ISTEP
            ISLOW = - ISTEP
            NINC  = NINC - ISTEP
            DELXN = DELX * ISTEP
            DELYN = DELY * ISTEP
            DELZN = DELZ * ISTEP
            GO TO 80
          ELSE
            ISTEP = 1
            IF (ISLOW > 0) ISLOW = ISLOW - 1
          END IF
        ELSE
C * LDRAW == 0
          LDRAW = IDRAW
          IF (DL < PAR(5)) THEN
C * EXIT DL == 0.0
            IF (IDRAW == 3 .AND. ABS (DL) < 0.0001) THEN
              RETURN
            ELSE
              ISLOW = IPR(111) - 1
              ISTEP = 1
            END IF
          ELSE
            ISLOW = 0
            ISTEP = IPR(111)
          END IF
          IF (ISTEP > NINC) ISTEP = NINC
        END IF
      ELSE
C * LDRAW = IDRAW
        IF (ISLOW > 0) THEN
          ISTEP = 1
          ISLOW = ISLOW -1
        ELSE
          ISTEP = IPR(111)
          IF (ISTEP > NINC) ISTEP = NINC
        END IF
      END IF
      IF (NINC == 0) IDRAW = 3
      LDRAW = IDRAW
      IF (IDRAW == 2) THEN
        IF (IDOWN == 3) THEN
C * NOTE THE STARTING POINT OF A LINE SEGMENT AT THIS POINT (XA,YA,ZA).
          XA = X
          YA = Y
          IF (MODE == 0 .OR. M == 0) THEN
            ZA = Z
          ELSE
            ZA = ZM
          END IF
          IDOWN = 2
        END IF
      ELSE
C * OBSCURING OCCURS AT THIS POINT. DRAW LINE SEGMENT (XA,YA) TO (X,Y)
C * THEN LIFT THE PEN
        IF (IDOWN == 2) THEN
          CALL GGIP (XA, YA, ZA, 3)
          CALL GGIP (X,  Y,  Z,  2)
          IDOWN = 3
        END IF
        IF (NINC <= 0) RETURN
      END IF
      IF (NINC == 1) THEN
        NINC  = 0
        DELXN = DELX
        DELYN = DELY
        DELZN = DELZ
      ELSE
        NINC  = NINC - ISTEP
        DELXN = DELX * ISTEP
        DELYN = DELY * ISTEP
        DELZN = DELZ * ISTEP
      END IF
   80 X = X + DELXN
      Y = Y + DELYN
      IF (M /= 0) THEN
C * CALCULATE NEW Z COORDINATE ON THE SPHERE SURFACE
        DXM = DXM + DELXN
        DYM = DYM + DELYN
        DZS = RMS - DXM**2 - DYM**2
        Z   = ZM  + SQRT (ABS (DZS))
      ELSE
        Z = Z + DELZN
      END IF
      GO TO 50
      END SUBROUTINE PLUT19
 
      SUBROUTINE PLUT20 (XDL1, XRJ, XRI, XDL2, XRM, XRN, XPHI, XXT,
     1                   XYT, IT, XOVRL)
C * SUBROUTINE TESTS FOR TWO DIMENSIONAL INTERSECTION OF BOND/BOND AND
C * BOND/ATOM OVERLAP SITUATIONS.
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: L
      INTEGER :: IX
      INTEGER :: IY
      INTEGER :: IT
      INTEGER :: IBX
      INTEGER :: IBY
      REAL :: X
      REAL :: Y
      REAL :: BX
      REAL :: BY
      REAL :: XRJ
      REAL :: XRI
      REAL :: XRM
      REAL :: XRN
      REAL :: XXT
      REAL :: XYT
      REAL :: CSPH
      REAL :: SNPH
      REAL :: XDL1
      REAL :: XDL2
      REAL :: XPHI
      REAL :: XOVRL
      REAL :: X0CSPH
      REAL :: X0SNPH
      REAL :: Y0CSPH
      REAL :: Y0SNPH
C *---------------------------------------------------------------------C
C *                                                                     C
C *          -1,+1     I           0,+1          I     +1,+1           C
C *                    I                         I                     C
C *        ------------I-------------------------I------------         C
C *                    I                         I                     C
C *          -1, 0     I           0, 0          I     +1, 0           C
C *                    I                         I                     C
C *        ------------I-------------------------I------------         C
C *                    I                         I                     C
C *          -1,-1     I           0,-1          I     +1,-1           C
C *                                                                    C
C *--------------------------------------------------------------------C
C * IT = 0 : NO OVERLAP
C * IT = 1 : OVERLAP
      X0CSPH = 0.0
      X0SNPH = 0.0
      IX     = 0
      IY     = 0
      IT     = 1
      IBX    = 0
      IBY    = 0
      IF (ABS (XPHI) < 0.0001) THEN
        CSPH = 1.0
        SNPH = 0.0
      ELSE
        CSPH = COS (XPHI)
        SNPH = SIN (XPHI)
      END IF
      DO 10 L = 1, 3, 2
        IF (L == 1) THEN
          X0CSPH = -XDL2 * CSPH
          X0SNPH = -XDL2 * SNPH
          Y0CSPH = -XRN  * CSPH
          Y0SNPH = -XRN  * SNPH
        ELSE
          X0CSPH = -X0CSPH
          X0SNPH = -X0SNPH
          Y0CSPH = -XRM * CSPH
          Y0SNPH = -XRM * SNPH
        END IF
        DO K = 1, 3, 2
          IF (K == 1) THEN
            X = X0CSPH - Y0SNPH + XXT
            Y = X0SNPH + Y0CSPH + XYT
          ELSE
            X = X0CSPH + Y0SNPH + XXT
            Y = X0SNPH - Y0CSPH + XYT
          END IF
          IF (XDL1 < 0.0) THEN
C * ATOM/BOND CASE
            BX = XRJ
            BY = XRJ
C * HANDLE INSIDE SPHERE ENCLOSURE/OUTSIDE SPHERE CASE
            IF (ABS (X) < XRJ .AND. ABS (Y) < XRJ) THEN
              IF (X**2 + Y**2 > XRJ**2) THEN
                IF (X > 0) THEN
                  IBX = 2
                ELSE
                  IBX = -2
                END IF
                IF (Y > 0) THEN
                  IBY = 2
                ELSE
                  IBY = -2
                END IF
              ELSE
                IBX = 0
                IBY = 0
                GO TO 10
              END IF
            END IF
          ELSE
C * BOND/BOND CASE
            BX = XDL1
            BY = ((XRJ + XRI) + (XRJ - XRI) * X / XDL1) / 2.0 + XOVRL
            IF (BY < 0.0) BY = 0.0
          END IF
          IF (X > BX) THEN
            IX = IX + 1
          ELSE IF (X + BX < 0.0) THEN
            IX = IX - 1
          END IF
          IF (Y > BY) THEN
            IY = IY + 1
          ELSE IF (Y + BY < 0.0) THEN
            IY = IY - 1
          END IF
        END DO
   10 CONTINUE
      IF (IBX == 0) THEN
        IF (IABS (IX) == 4 .OR. IABS (IY) == 4) IT = 0
      ELSE
        IF (IX == IBX .AND. IY == IBY) IT = 0
      END IF
      RETURN
      END SUBROUTINE PLUT20
 
      SUBROUTINE PLUT21 (MODE)
      USE files
      USE parameters
      USE atomdata
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: N10
      INTEGER :: N20
      INTEGER :: JP1
      INTEGER :: JPL
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: IRB
      INTEGER :: ITO
      INTEGER :: KNB
      INTEGER :: NRF
      INTEGEr :: ITOH
      INTEGER :: MODR
      INTEGER :: MODE
      INTEGER :: IDASH
      INTEGER :: ITOCG
      INTEGER :: NSPEC
      INTEGER :: ITOMET
      REAL :: RB
      REAL :: RMIN
      REAL :: XDUM
      CHARACTER(len=2) :: J212
      CHARACTER(len=3) :: JJ13
      CHARACTER(len=3) :: J313
C * RADII CARD. THIS SETS RADII FOR ATOMS AND BONDS. THERE ARE SEVERAL
C * OPTIONS FOR BOND SPECIFICATION, ATOM TYPE, INTERMOLECULAR, TO
C * LIST, SPECIFIC ATOM PAIR.  WE ALSO ENTER NUMBER OF LINES FOR BOND.
C * TAPERING OF BONDS MAY BE CONTROLLED ALSO.
C * MODE = -1 : AUTOMATIC (SOLID/STRAW/ROD) RADII ASSIGNMENT
C * MODE =  0 : HANDLE RADII INSTRUCTION
C * MODE =  1 : AUTOMATIC CPK RADII ASSIGNMENT
      N1     = 0
      N2     = 0
      ITOH   = 0
      ITOMET = 0
      ITOCG  = 0
      KL = IPR(220)
      KN = IPR(221)
      IPR(72) = 0
      MODR    = MODE
      IF (MODR == 0) THEN
        IPR(130) = 0
        IF (KL < 3) THEN
          IPR(72) = 32
          RETURN
        END IF
        N = 0
        J212 = IFL(2)(1:2)
C * TEST SUB-KEYWORD BONDS
        IF (J212 == 'BO') THEN
          IDASH = 1
          DO J = 3, KL
            JJ13 = IFL(J)(1:3)
C * TEST FOR SUB-KEYWORD DASH
            IF (JJ13 == 'DAS') THEN
              IDASH = -1
              CYCLE
            END IF
C * TEST SUB-KEYWORD TAPERING
            IF (JJ13 == 'TAP') THEN
              IF (KN == 0) THEN
                IPR(72) = 33
              ELSE
                PAR(44) = FN(1)
              END IF
              RETURN
            END IF
C * TEST SUB-KEYWORD ALL
            IF (JJ13 == 'ALL') THEN
C * CHANGE DEFAULT SETTINGS FOR RADIUS AND LINES OF ALL BONDS
              IF (KN == 0) THEN
                IPR(72) = 34
              ELSE
                IPR(41) = 0
                PAR(38) = FN(1)
                IF (KN >= 2) IPR(12) = NINT (ABS (FN(2)) * IDASH)
              END IF
              RETURN
            END IF
C * SUB-KEYWORD NORMAL
            IF (JJ13 == 'NOR') THEN
C * CHANGE DEFAULT SETTINGS FOR RADIUS AND LINES OF NORMAL BONDS
              IF (KN == 0) THEN
                IPR(72) = 35
              ELSE
                PAR(38) = FN(1)
                IF (KN >= 2) IPR(12) = NINT (ABS (FN(2)) * IDASH)
              END IF
              RETURN
            END IF
            IF (JJ13 == 'TO') THEN
C * KEYWORD  -TO-  FOLLOWED BY ATOM NAME OR ATOM TYPE
              JPL = - J - 1
              CALL PLUT13 (0, JPL, M, XDUM)
              IF (M == 0) THEN
                IPR(72) = 36
              ELSE
                N1 = 0
                N2 = M
              END IF
              EXIT
C * INTER
            ELSE IF (JJ13 == 'INT') THEN
C * KEYWORD INTER FOR ALL INTERMOLECULAR BONDS
              N1 = -1
              N2 = 0
              EXIT
            ELSE
              JP1 = J + 1
              CALL PLUT13 (0, J,   IAT, XDUM)
              CALL PLUT13 (0, JP1, JAT, XDUM)
              IF (IAT > 0 .AND. JAT > 0) THEN
C * SPECIFIC BOND NAMED HERE
                N1 = MIN (IAT, JAT)
                N2 = MAX (IAT, JAT)
                EXIT
              ELSE
                IPR(72) = 37
              END IF
            END IF
          END DO
          IF (IPR(72) == 0) THEN
C * TEST FOR ARU
            IF (KN > 0) THEN
              KNB = 0
              IF (FN(1) > 1.0) THEN
                KNB = 1
                IF (KN == 1) THEN
                  KN    = 3
                  FN(2) = 0.02
                  FN(3) = 5.0
                END IF
              END IF
C * STORE BOND RADIUS AND NUMBER OF LINES (IF NO-PREVIOUS ERROR DETECTED)
 
              IF (KN > KNB) THEN
                RB = FN(KNB + 1)
              ELSE
                RB = PAR(38)
              END IF
              IF (KN > KNB + 1) THEN
                L = NINT (FN(KNB + 2))
              ELSE
                L = IPR(12)
              END IF
            END IF
            L = IABS (L) * IDASH
            IF (L == 1) THEN
              IRB = 1
            ELSE
              IRB = NINT (RB * 1000.0)
            END IF
            N3    = ISIGN (1000 * IABS(L) + IRB, L)
            NSPEC = IPR(41)
            NRF   = IPR(80)
            DO I = 1, NSPEC
              N10 = NINT (RA(NRF))
              N20 = NINT (RA(NRF - 1))
              IF (N1 == N10 .AND. N2 == N20)  GO TO 10
              NRF = NRF - 3
            END DO
            IF (IPR(41) >= IPR(76)) THEN
              WRITE (LU6, 99999, IOSTAT = IOST)
              RETURN
            END IF
            IPR(41)     = IPR(41) + 1
            RA(NRF)     = N1
            RA(NRF - 1) = N2
   10       RA(NRF - 2) = N3
C * STORE NEW -TO H- VALUES FOR FUTURE USE
            IF (NRF == IPR(80)) THEN
              IF (IPR(4) == 1) THEN
                IPR(103) = N3
              ELSE IF (IPR(4) == 2) THEN
                IPR(104) = N3
              ELSE IF (IPR(4) == 4) THEN
                IPR(106) = N3
              END IF
            END IF
          END IF
C * TEST KEYWORD ATOMS
        ELSE IF (J212 == 'AT') THEN
          J313  = IFL(3)(1:3)
C * ATOM RADIUS SPECIFICATION HERE
          IF (KL < 3) THEN
            GO TO 30
          ELSE IF (KL > 3) THEN
            GO TO 20
          END IF
          IF (J313 == 'ALL') THEN
C * RADII ATOMS ALL
            IF (KN == 0) THEN
              IPR(72) = 38
            ELSE
              DO I = 1, IAN
                 IF (KN >= 1) THEN
                   RADR(I, 1) = FN(1)
                 ELSE
                   RADR(I, 1) = PAR(70)
                 END IF
              END DO
              IPR(99) = 1
            END IF
            RETURN
          END IF
          IPR(99) = 2
C * RADII ATOMS AUTO
          IF (J313 == 'AUT') THEN
            IF (IABS (IPR(4)) == 3) THEN
              MODR   = 1
            ELSE
              MODR   = -1
              IPR(4) = 1
            END IF
             GO TO 30
C * RADII ATOMS COVALENT
          ELSE IF (J313 == 'COV') THEN
            MODR   = -1
            IPR(4) = 1
            GO TO 30
C * RADII ATOMS CPK
          ELSE IF (J313 == 'CPK')  THEN
            MODR   = 1
            GO TO 30
          END IF
   20     DO K = 3, KL
            CALL PLUT13 (0, -K, IAT, XDUM)
C * RADII FOR ATOM TYPES
            IF (IAT < 0) THEN
              M = - IAT
              N = N + 1
              IF (N > KN) THEN
                IPR(72) = 39
                RETURN
              ELSE
                RADR(M, 1) = FN(N)
              END IF
C * RADII FOR INDIVIDUAL ATOMS
            ELSE
              N = N + 1
              IF (N > KN) THEN
                IPR(72) = 39
                RETURN
              END IF
              RA(IAT * NP43 + 11) = FN(N)
            END IF
          END DO
          IPR(99) = 2
        ELSE
          IPR(72) = 41
        END IF
      END IF
   30 IF (MODR < 0) THEN
C * SET UP DEFAULT SPECIAL BOND LIST : RA() = (NL + RB) * 1000
C * NEGATIVE ENTRY = DASHED BOND
C * SET :  RADII INTER 0.020 5 (DASHED)
        RA(IPR(80)    ) = -1
        RA(IPR(80) - 1) = 0
        RA(IPR(80) - 2) = -5020
        IPR(41)         = 1
C * AUTOMATIC ASSIGNMENT OF NORMAL BOND RADII
        IF (IPR(4) == 0) THEN
          CALL GEN074 (RADR, 1, IAN, 0.0)
        ELSE
          IF (IPR(4) == 1) THEN
C * SOLID RADII RESET
            PAR(38) = 0.05
            IPR(12) = 30
            PAR(21) = PAR(351)
            ITOH    = IPR(103)
            ITOMET  = 2040
            ITOCG   = -6040
          ELSE IF (IPR(4) == 2) THEN
C * ROD MODE RADII RESET
            PAR(38) = 0.2
            IPR(12) = 8
            PAR(21) = PAR(352)
            ITOH    = IPR(104)
            ITOMET  = 2040
            ITOCG   = -6040
          ELSE IF (IPR(4) == 4) THEN
C * STRAW MODE RADII RESET
            PAR(38) = 0.12
            IPR(12) = 2
            PAR(21) = PAR(354)
            ITOH    = IPR(106)
            ITOMET  = -6040
            ITOCG   = -6040
          END IF
          RMIN            = MOD(ITOH, 1000) / 1000.0
C * SET :  RADII BONDS TO METAL 0.04 2 (0.12 20 for STRAW)
C * SET :  RADII BONDS TO CG    0.06 6 DASH
          DO I = 1, IAN
C * TO CG-'ATOM'
            IF (IEN(I) == 106) THEN
              ITO = ITOCG
C * TO Q-ATOM
            ELSE IF (IEN(I) == 111) THEN
              ITO = 1010
C * TO METAL
            ELSE IF (IATPR(IEN(I)) >= 0) THEN
              ITO = ITOMET
            ELSE
              ITO = 0
            END IF
            IF (ITO /= 0) THEN
              RA(IPR(80) - IPR(41) * 3)     = 0
              RA(IPR(80) - IPR(41) * 3 - 1) = -I
              RA(IPR(80) - IPR(41) * 3 - 2) = ITO
              IPR(41)                       = IPR(41) + 1
            END IF
C * AUTOMATIC ASSIGNMENT OF SOLID/ROD/STRAW RADII BASED ON COVALENT RADII
            RADR(I, 1) = MAX (PAR(21) * RADR(I, 3), RMIN)
          END DO
C * (RE)SET: RADII BONDS TO H (SOLID: 0.035 4, ROD: 0.07 3, STRAW: 0.10 2)
          RA(IPR(80) - IPR(41) * 3)     = 0
          RA(IPR(80) - IPR(41) * 3 - 1) = -1
          RA(IPR(80) - IPR(41) * 3 - 2) = ITOH
          IPR(41)                       = IPR(41) + 1
          IPR(94)                       = IPR(41)
          IPR(77)                       = 3
          WRITE (LU6, 99998, IOSTAT = IOST) PAR(21)
        END IF
      ELSE IF (MODR > 0) THEN
        DO I = 1, IAN
          RADR(I, 1) = ABS (VDWR(IEN(I)))
        END DO
        WRITE (LU6, 99997, IOSTAT = IOST)
        PAR(38) = 0.0
        IPR(12) = 0
        IPR(4)  = 3
        IPR(77) = 3
        IPR(41) = 0
      END IF
      RETURN
99999 FORMAT (':: Not enough storage, Request IGNORED',/)
99998 FORMAT (':: Atom Radii (RE)SET to ', F5.2, ' x Covalent Radii')
99997 FORMAT (':: Atom Radii (RE)SET to van der Waals Radii')
      END SUBROUTINE PLUT21
 
      SUBROUTINE PLUT22 (I, J, D)
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L
      REAL :: D
      D = 0
      DO L = 4, 6
        D = D + (RA(I * NP43 + L) - RA(J * NP43 + L))**2
      END DO
      D = SQRT (ABS (D))
      RETURN
      END SUBROUTINE PLUT22
 
      SUBROUTINE PLUT23 (MODE)
C * ORTHOGONALIZATION
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: MODE
      REAL :: ARG
      REAL :: DET
      REAL :: AXHI
      REAL :: AXLO
C * MODE <   0 : IPR(51) = 1 + ORTHOGON. MATRIX
C * MODE =>  0 : ORTHOGONALIZE X, Y, Z ATOM MODE
C * PAR(101) = A
C * PAR(102) = B
C * PAR(103) = C
C * PAR(104) = COS(ALPHA)
C * PAR(105) = COS(BETA)
C * PAR(106) = COS(GAMMA)
C * PAR(107) = SIN(ALPHA)
C * PAR(108) = SIN(BETA)
C * PAR(109) = SIN(GAMMA)
C * PAR(110) = COS(ALPHA*)
C * PAR(111) = COS(BETA*)
C * PAR(112) = COS(GAMMA*)
C * PAR(113) = 1/A*
C * PAR(114) = 1/B*
C * PAR(115) = 1/C*
C * PAR(116) =
C * PAR(117) =
C * PAR(118) =
C * PAR(119) = ALPHA
C * PAR(120) = BETA
C * PAR(121) = GAMMA
C * PAR(126) = VOLUME
      IF (MODE >= 0) THEN
C * CALCULATE ORTHOGONAL COORDINATES FOR ATOM 'MODE'
        I = MODE * NP43
        DO J = 1, 3
          RA(I + J + 3) = 0.0
          DO K = J, 3
             RA(I + J + 3) = RA(I + J + 3) + OM(J, K) * RA(I + K)
          END DO
        END DO
C * ORTHOGONALISE
      ELSE
C * CHECK FOR ANGSTROM DATA CASE
        IF (IABS (IPR(50)) == 1) THEN
C * TEST FOR NO EXPLICIT ANGSTROM CASE
          IF (IPR(50) == 1) THEN
            WRITE (LU6, 99999, IOSTAT = IOST)
          ELSE
C * RESET TO POSITIVE
            IPR(50) = 1
          END IF
          IPR(37)  = 0
C * SET CELL FLAG (1, 1, 1, 90, 90, 90)
          IPR(52)  = 0
          IPR(53)  = 0
          IPR(68)  = 0
          IPR(69)  = 0
          IGBL(30) = 1
          IGBL(33) = 0
          CALL GEN074 (PAR, 101, 103, 1.0)
          PAR(148) = 90.0
        END IF
        IPR(51) = 1
        IF (PAR(104) == 0.0) PAR(104) = 90.0
        IF (PAR(105) == 0.0) PAR(105) = 90.0
        IF (PAR(106) == 0.0) PAR(106) = PAR(148)
C * CALCULATE METRIC (TEMP STORE IN OM)
        CALL GEN026 (1, OM, PAR(101))
C * APPLY AXES TRANSFORMATION
        IF (IPR(127) > 0) THEN
          CALL GEN001 (1, TMX, OM, ROM)
          CALL GEN026 (-1, ROM, PAR(101))
          WRITE (LU6, 99998, IOSTAT = IOST) (PAR(J), J = 101, 106)
        END IF
C * APPLY SYMMETRY CONSTRAINTS ON CELL DIMENSIONS
        CALL GEN066 (0, PAR(101), PAR(107), SPGRNM(1)(12:12), IPR(783))
C * DUNITZ TYPE ORTHOGONALISATION
        CALL GEN044 (PAR(101), OM, 1)
C * GET INVERSE MATRIX FOR ORTHOG. TO FRACT. TRANSFORMATION
        CALL GEN003 (OM, ROM, DET, 0)
        ARG = 1.0
        DO J = 4, 6
          PAR(115 + J) = PAR(100 + J)
          PAR(103 + J) = SIN (PAR(100 + J) / RGBL(6))
          PAR(100 + J) = COS (PAR(100 + J) / RGBL(6))
          ARG          = ARG - PAR(100 + J)**2
        END DO
        PAR(126) = PAR(101) * PAR(102) * PAR(103) *
     1  SQRT (ARG + 2.0 * PAR(104) * PAR(105) * PAR(106))
        PAR(110) = (PAR(105) * PAR(106) - PAR(104)) /
     1             (PAR(108) * PAR(109))
        PAR(111) = (PAR(104) * PAR(106) - PAR(105)) /
     1             (PAR(107) * PAR(109))
        PAR(112) = (PAR(104) * PAR(105) - PAR(106)) /
     1             (PAR(107) * PAR(108))
C * SET UP LIMITS FOR TESTING IF ATOM IN RANGE FOR DISTANCE CALCULATION
        PAR(113) = PAR(126) / (PAR(102) * PAR(103) * PAR(107))
        PAR(114) = PAR(126) / (PAR(101) * PAR(103) * PAR(108))
        PAR(115) = PAR(126) / (PAR(101) * PAR(102) * PAR(109))
        PAR(116) = 2.0 * PAR(110) / (PAR(114) * PAR(115))
        PAR(117) = 2.0 * PAR(111) / (PAR(113) * PAR(115))
        PAR(118) = 2.0 * PAR(112) / (PAR(113) * PAR(114))
        DO I = 7, 9
          PAR(100 + I) = 1.0 / PAR(106 + I)**2
        END DO
C * DECIDE ORDER OF AXES IN DESCENDING AXIAL LENGTH.
        DO I = 1, 3
          PAR(97 + I) = PAR(100 + I)
        END DO
        IF (PAR(101) == PAR(102) .OR. PAR(101) == PAR(103))
     1    PAR(98) = PAR(101) + 0.0002
        IF (PAR(102) == PAR(103)) PAR(99) = PAR(102) + 0.0001
        AXHI = MAX (PAR(98), PAR(99), PAR(100))
        AXLO = MIN (PAR(98), PAR(99), PAR(100))
        DO K = 1, 3
          IF (PAR(97 + K) == AXHI) THEN
            IPR(120 + K) = 1
          ELSE IF (PAR(97 + K) == AXLO) THEN
            IPR(120 + K) = 3
          ELSE
            IPR(120 + K) = 2
          END IF
        END DO
      END IF
      RETURN
99999 FORMAT (':: No CELL card given, Angstrom data assumed')
99998 FORMAT (':: New Cell', 3F8.4, 3F7.2)
      END SUBROUTINE PLUT23
 
      SUBROUTINE PLUT24 (MODE, JATM, MNCODE)
C * AD_HOC GEOMETRY CALCULATION
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: NA
      INTEGER :: NB
      INTEGER :: NG
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: KAT
      INTEGER :: LAT
      INTEGER :: MET
      INTEGER :: NMET
      INTEGER :: IATK
      INTEGER :: JATK
      INTEGER :: JNCL
      INTEGER :: KNCL
      INTEGER :: IDUM
      INTEGER :: MJAT
      INTEGER :: MODE
      INTEGER :: JATM
      INTEGER :: IDUM1
      INTEGER :: MADDR
      INTEGER :: MNCODE
      REAL :: D
      REAL :: D1
      REAL :: D2
      REAL :: ANG
      REAL :: XNM
      REAL :: SANG
      REAL :: XDUM
      REAL :: XMOL
      REAL :: ANGM
      REAL :: ANGLE
      REAL :: DUMMY
      REAL :: OMEGA
      CHARACTER(len=80), SAVE, DIMENSION(10) :: GEOM
C * MODE = -3 - NEGATIVE WRITE/DELETE
C * MODE = -2 - CLEAR GEOM
C * MODE = -1 - HFIX
C * MODE =  1 - GEOM/COORDN
C * MODE =  2 - BOND DISTANCE
C * MODE =  3 - BOND ANGLE
C * MODE =  4 - TORSION ANGLE
C * CLEAR GEOM-LISTING
      IF (MODE == -3) THEN
        DO I = 1, 10
          CALL PLA439 (0.0, GEOM(I), 80, 0.3, 0, 2, -PAR(64) + 1.0,
     1             PAR(65) - 1.0 - I * 0.5)
        END DO
C * CLEAR GEOM
      ELSE IF (MODE == -2) THEN
        DO I = 2, 10
          CALL GEN038 (GEOM(I), 1, 80)
        END DO
      ELSE
C * TEST FOR PREVIOUS JOIN INSTRUCTION EXECUTED, OTHERWISE DO SO
        IF (IPR(17) == 0) THEN
          CALL PLUT05
C * CALL EXIT/STOP
          IF (IPR(72) /= 0) CALL GEN127 ('311')
        END IF
        IF (ABS (MODE) == IPR(220) - 1) THEN
C * GET SERIAL NUMBER FOR THIS ATOM
          CALL PLUT13 (0, 2, IAT, XDUM)
C * GET LABEL
          CALL PLUT25 (1, IAT, IATK)
          IF (IAT > 0) THEN
C * GEOM/COORDN CASE
            IF (ABS (MODE) == 1) THEN
              NB   = 0
              SANG = 0.0
              ANGM = 0.0
              NMET = 0
C * CREATE GEOM HEADER
              WRITE (GEOM(1), 99999, IOSTAT = IOST)
C * CLEAR GEOM DISPLAY LIST
              DO I = 2, 10
                CALL PLA439 (0.0, GEOM(I), 80, 0.3, 0, 2, -PAR(64)
     1               + 1.0, PAR(65) - 1.0 - I * 0.5)
                CALL GEN038 (GEOM(I), 1, 80)
              END DO
              NG = 1
              DO JAT = IPR(69) + 1, JATM
                CALL PLUT15 (-1, JAT, 27, JNCL)
                IF (JNCL == 1 .OR. IPR(163) == 1
     1               .OR. JAT > IPR(39)) THEN
C * TEST WHETHER THIS IS A BOND
                  CALL PLUT16 (-5, IDUM, IAT, JAT, DUMMY, IDUM1)
                  IF (IDUM > 0) THEN
                    NB = NB + 1
C * GET DISTANCE
                    CALL PLUT22 (IAT, JAT, D)
                    IF (NB == 1) D1 = D
                    IF (NB == 2) THEN
                      D2 = D
                      IF (D2 < D1) CALL GEN018 (D1, D2)
                    END IF
C * GET LABEL
                    CALL PLUT25 (2, JAT, JATK)
C * METAL ?
                    CALL PLUT15 (-1, JAT, 17, MET)
                    NMET = NMET + MET
C * GET SYMMETRY OPERATION
                    CALL PLUT15 (-6, JAT, 11, MADDR)
                    XMOL = IARU(1, MADDR + 1) / PAR(42)
                    NA   = 0
                    IF (NB > 1) THEN
                      MJAT = MIN (JAT - 1, IPR(38))
                      DO KAT = IPR(69) + 1, MJAT
C * TEST WHETHER THIS ATOM IS INCLUDED
                        CALL PLUT15 (-1, KAT, 27, KNCL)
                        IF (KNCL == 1 .OR. IPR(163) == 1
     1                      .OR. KAT > IPR(39)) THEN
C * TEST WHETHER THIS IS A BOND
                          CALL PLUT16 (-5, IDUM, IAT, KAT, DUMMY, IDUM1)
                          IF (IDUM > 0) THEN
                            CALL PLUT37 (KAT, IAT, JAT, 0, ANG)
                            ANGM = MAX (ANGM, ANG)
                            IF (NA < 12) THEN
                              NA      = NA + 1
                              SGY(NA) = ANG
                              SANG    = SANG + ANG
                            END IF
                          END IF
                        END IF
                      END DO
                    END IF
                    IF (NG < 10) THEN
                      NG = NG + 1
                      CALL GEN020 (-1, NQ1, 2, 2)
                      CALL GEN020 (-1, NQ2, 2, 2)
                      WRITE (GEOM(NG), 99998, IOSTAT = IOST)
     1                  NQ1, NQ2, XMOL, D, (SGY(I), I = 1, NA)
                    END IF
                  END IF
                END IF
              END DO
C * DISPLAY GEOM LIST
              DO I = 1, NG
                CALL PLA439 (0.0, GEOM(I), 80, 0.3, 5 + IGBL(68), 2,
     1               - PAR(64) + 1.0, PAR(65) - 1.0 - I * 0.5)
              END DO
C * HFIX (MODE = -1)
              IF (MODE == -1) THEN
                CALL PLUT42 (NB, IATK, JATK, SANG, ANGM, NMET, D, D1,
     1            D2, MNCODE)
              END IF
            ELSE
C * GET SEQUENCE NUMBER 'JAT' FOR SECOND ATOM
              CALL PLUT13 (0, 3, JAT, XDUM)
              IF (JAT > 0) THEN
C * (BOND) DISTANCE CASE
                IF (MODE == 2) THEN
                  IF (IPR(221) == 1) THEN
                    XNM = FN(1)
                    IF (XNM < 0.0) THEN
                      M = - NINT (XNM)
                      XNM = NINT (RA(IPR(159) + 1  - M))
                    END IF
                    CALL PLUT28 (IAT, JAT, XNM)
                    CALL PLUT15 (4, JAT, 37, 1)
                  END IF
                  CALL PLUT22 (IAT, JAT, D)
                  WRITE (SBCD, 99997, IOSTAT = IOST)
     1              (IFL(I), I = 1, 3), D, CHAR (0)
                  IF (IGBL(32) == 0)
     1              WRITE (LU6, 99994, IOSTAT = IOST) SBCD
                ELSE
                  CALL PLUT13 (0, 4, KAT, XDUM)
                  IF (KAT > 0) THEN
C * (BOND) ANGLE CASE
                    IF (MODE == 3) THEN
                      CALL PLUT37 (IAT, JAT, KAT, 0, ANGLE)
                      WRITE (SBCD, 99996, IOSTAT = IOST)
     1                  (IFL(I), I = 1, 4), ANGLE, CHAR (0)
                      IF (IGBL(32) == 0)
     1                  WRITE (LU6, 99994, IOSTAT = IOST) SBCD
                    ELSE
                      CALL PLUT13 (0, 5, LAT, XDUM)
                      IF (LAT > 0) THEN
C * TORSION ANGLE CASE
                        IF (MODE == 4) THEN
                          CALL PLUT37 (IAT, JAT, KAT, LAT, OMEGA)
                          WRITE (SBCD, 99995, IOSTAT = IOST)
     1                      (IFL(I), I = 1, 5), OMEGA * IPR(65),
     2                      CHAR (0)
                          IF (IGBL(32) == 0)
     1                      WRITE (LU6, 99994, IOSTAT = IOST) SBCD
                        END IF
                      ELSE
                        IPR(72) = 42
                      END IF
                    END IF
                  ELSE
                    IPR(72) = 43
                  END IF
                END IF
              ELSE
                IPR(72) = 44
              END IF
            END IF
          ELSE
            IPR(72) = 45
          END IF
        ELSE
          IPR(72) = 46
        END IF
        IPR(163) = 0
      END IF
      RETURN
99999 FORMAT ('Geom/Coord', 8X, '[   ARU   ]    Dist Angle(s)')
99998 FORMAT (A, ' - ', A, ' [', F9.2, '] =', F6.3, 8F5.0)
99997 FORMAT (3(A, 1X), ' =', F8.3, A)
99996 FORMAT (4(A, 1X), ' =', F8.2, A)
99995 FORMAT (5(A, 1X), ' =', F8.2, A)
99994 FORMAT (A)
      END SUBROUTINE PLUT24
 
      SUBROUTINE PLUT25 (MD, IAT, IATK)
C * RECOVER ATOMLABEL : INQNR + SYMM_FLAG----> NQ  INCLUDING PARENTHESES
      USE parameters
      USE atomdata
      USE cchar
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: J3
      INTEGER :: MD
      INTEGER :: NAT
      INTEGER :: JX0
      INTEGER :: JX1
      INTEGER :: JX2
      INTEGER :: JX3
      INTEGER :: IAT
      INTEGER :: NSS
      INTEGER :: NPAR
      INTEGER :: IATK
      INTEGER :: MODE
      INTEGER :: INQNR
      INTEGER :: MSUBST
      INTEGER, DIMENSION(4) :: NUM
      CHARACTER(len=NP64) :: NQ
C * ABS(MD) = 0    - GET ATOM TYPE
C * ABS(MD) = 1, 2 - OUTPUT IN NQ1 OR NQ2 RESPECTIVELY
      IF (MD >= 0) THEN
        MODE = MD
        NPAR = IPR(71)
      ELSE
        MODE = - MD
        NPAR = 0
      END IF
      NAT = IABS (IAT)
      IF (NAT > IPR(37)) THEN
        N = MOD (NAT - IPR(69) - 1, IPR(37) - IPR(69)) + IPR(69) + 1
      ELSE
        N = NAT
      END IF
      INQNR = NINT (RA(N * NP43 + 7))
C * GET SYMMETRY (STARTING FROM IPR(75))
      CALL PLUT15 (-6, N, 11, JX3)
      IF (IPR(75) > 0) THEN
        JX3 = JX3 - IPR(75) + 1
      ELSE
        JX3 = 0
      END IF
      IF (MODE /= 0) THEN
        I = 1
        IF (INQNR >= 0.0) THEN
          JX1 = INQNR / 64000
          JX2 = INQNR - JX1 * 64000
          NSS = MOD (JX2, 32)
          JX2 = JX2 / 32
          JX0 = JX1 + 1
          JX1 = IEL(IEN(JX0))
          J1  = JX1 / 100
          J2  = JX1 - J1 * 100
          IF (IAT > 0 .OR. JX0 > 2) THEN
            NQ(I:I) = CHAR (ICHAR ('A') - 1 + J1)
            I = I + 1
            IF (J2 /= 0) THEN
              NQ(I:I) = CHAR (ICHAR ('a') - 1 + J2)
              I = I + 1
            END IF
          END IF
          IF (JX2 == 0) NPAR = 0
          IF (NPAR /= 0) THEN
            NQ(I : I) = '('
            I = I + 1
          END IF
          J2 = JX2 / 10
          NUM(4) = MOD (JX2, 10)
          J3     = J2 / 10
          NUM(3) = MOD (J2, 10)
          NUM(1) = J3 / 10
          NUM(2) = MOD (J3, 10)
          J2     = 0
          DO J = 1, 4
            IF (NUM(J) > 0 .OR. J2 > 0) THEN
              NQ(I : I) = CHAR (ICHAR ('0') + NUM(J))
              I = I + 1
              J2 = J2 + 1
            END IF
          END DO
          IF (NSS /= 0) THEN
            IF (NSS == 1) THEN
              NQ(I : I) = ''''
            ELSE IF (NSS == 2) THEN
              NQ(I : I) = '"'
            ELSE IF (NSS == 3) THEN
              NQ(I : I) = '#'
            ELSE IF (NSS > 3) THEN
              NQ(I : I) = CHAR (ICHAR ('A') + NSS - 4)
            END IF
            I = I + 1
          END IF
          IF (NPAR /= 0) THEN
            NQ(I : I) = ')'
            I = I + 1
          END IF
          IF (JX3 > 0) THEN
            IF (NPAR == 0) THEN
              NQ(I : I) = '_'
              I = I + 1
            END IF
            IF (JX3 < 27) THEN
              NQ(I : I) = CHAR (ICHAR ('a') - 1 + JX3)
            ELSE IF (JX3 == 27 .OR. JX3 > 53) THEN
              NQ(I : I) = '*'
            ELSE
              NQ(I : I) = CHAR (ICHAR ('a') + JX3 - 28)
            END IF
            I = I + 1
          END IF
        END IF
        IF (I <= NP64) THEN
          CALL GEN038 (NQ, I, NP64)
        END IF
C * HANDLE ALIASES
        MSUBST = 0
        IF (IGBL(55) == 0) THEN
          MSUBST = 0
          CALL PLA281 (-1, NQ, MSUBST)
        END IF
        IF (MODE /= 2) THEN
          NQ1 = NQ
        ELSE
          NQ2 = NQ
        END IF
      END IF
      IATK = INQNR / 64000 + 1
      RETURN
      END SUBROUTINE PLUT25
 
      SUBROUTINE PLUT26 (M, NATL, XI, YI, ZI, RI, XL, YL, ZL, RL, XSH)
C * SUBROUTINE GENERATES LABEL POSITIONS WITH REFERENCE TO ATOM POSITIONS
      USE parameters
      IMPLICIT NONE
      INTEGER :: M
      INTEGER :: IASU
      INTEGER :: NATL
      INTEGER :: NPROP
      REAL :: CA
      REAL :: SA
      REAL :: XI
      REAL :: YI
      REAL :: ZI
      REAL :: RI
      REAL :: XL
      REAL :: YL
      REAL :: ZL
      REAL :: RL
      REAL :: RIX
      REAL :: ANG
      REAL :: XSH
C *-------------------------------------------------------------------C
C *                                                                   C
C *                          4                                        C
C *                  5       I       3                                C
C *                    \     I     /                LABEL             C
C *                      \   I   /                  POSITION          C
C *                        \ I /                    NUMBERS           C
C *               6 ------- 10 ------- 2            M                 C
C *                        / I \                                      C
C *                      /   I   \                                    C
C *                    /     I     \                                  C
C *                  7       I       9                                C
C *                          8                                        C
C *                                                                   C
C *-------------------------------------------------------------------C
      XL = XI
      YL = YI
      IF (IPR(116) /= 0) THEN
        ZL = ZI
      ELSE
        IF (PAR(48) /= 0.0) THEN
          ZL = ZI
        ELSE
          ZL = ZI + PAR(60)
        END IF
      END IF
      RL = MAX (PAR(28), PAR(40))
      IF (M < 10) THEN
        ANG = RGBL(5) * (M - 2) / 8
        CA  = COS (ANG)
        SA  = SIN (ANG)
        RIX = RI + XSH
        XL  = XL + RIX * CA
        YL  = YL + RIX * SA
        IF (ABS (CA) > 0.1) XL = XL + PAR(40) * CA / ABS (CA)
        IF (ABS (SA) > 0.1) YL = YL + PAR(28) * SA / ABS (SA)
      END IF
      NPROP = 0
      IASU  = 0
      CALL PLUT14 (1, NATL, IASU, NPROP, XL, YL, ZL, RL)
      RETURN
      END SUBROUTINE PLUT26
 
      SUBROUTINE PLUT27 (IAJAT, IAT, JAT, RBO, NLI)
C * ROUTINE ALLOCATES BOND RADIUS AND NUMBER OF LINES FOR BOND IAT-JAT
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: N3
      INTEGER :: NRF
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: NLI
      INTEGER :: IHAT
      INTEGER :: JHAT
      INTEGER :: IAIO
      INTEGER :: IAJO
      INTEGER :: IDIS
      INTEGER :: JDIS
      INTEGER :: NSPEC
      INTEGER :: IAJAT
      INTEGER :: NRESI
      INTEGER :: NRESJ
      INTEGER :: ITYPE
      INTEGER :: JTYPE
      REAL :: RBO
C * TEST FOR STICK/NON-STICK MODE
      IF (IPR(4) > 0) THEN
C * NON-STICK MODE
        IF (IAT > IPR(69)) THEN
C * GET RESIDUE AND ATOM PROPERTIES FOR IAT & JAT
          CALL PLUT15 (-6, IAT, 5,  NRESI)
          CALL PLUT15 (-6, JAT, 5,  NRESJ)
          ITYPE = INT (RA(IAT * NP43 + 7) / 64000)
          JTYPE = INT (RA(JAT * NP43 + 7) / 64000)
          CALL PLUT15 (-1, IAT, 44, IHAT)
          CALL PLUT15 (-1, JAT, 44, JHAT)
C * HANDLE D-ATOMS AS H-ATOMS
          IF (IHAT == 1) ITYPE = 0
          IF (JHAT == 1) JTYPE = 0
          L     = -1
          NSPEC = IPR(41)
          NRF   = IPR(80) + 1
C * LOOP OVER SPECIAL BOND TYPES
          DO K = 1, NSPEC
            NRF = NRF - 3
            N1  = NINT (RA(NRF + 2))
            N2  = NINT (RA(NRF + 1))
            N3  = NINT (RA(NRF    ))
            IF (N1 < 0) THEN
C * INTERMOLECULAR BOND SPECIFICATION
              IF (IAJAT > IPR(53)) L = N3
              IF (NRESI /= NRESJ)  L = N3
            ELSE IF (N1 == 0) THEN
C * TO - BOND SPECIFICATION
              IF (N2 < 0) THEN
C * TO ATOM-TYPE
                IAIO = - ITYPE - 1
                IAJO = - JTYPE - 1
              ELSE
C * TO ATOM-NAME
                IAIO = IAT
                IAJO = JAT
              END IF
              IF (IAIO == N2 .OR. IAJO == N2) THEN
C * ONLY THE FIRST NON-DEFAULT SETTING WILL BE EFFECTIVE
                IF (L == -1) THEN
                  L = N3
                END IF
              END IF
            ELSE
C * SPECIFIC BOND
              IF (N1 == IAT .AND. N2 == JAT) THEN
                L = N3
              ELSE IF (N1 == JAT .AND. N2 == IAT) THEN
                L = N3
              END IF
            END IF
          END DO
          IF (L /= -1) THEN
C * NON-DEFAULT BOND RADII SETTINGS
            RBO = 0.001 * FLOAT (MOD (IABS (L), 1000))
            NLI = ISIGN (IABS (L) / 1000, L)
          ELSE
C * DEFAULT BOND RADII SETTINGS
            RBO = PAR(38)
            NLI = IPR(12)
          END IF
C * HANDLE MAJOR/MINOR DISORDER
          CALL PLUT15 (-4, IAT, 28, IDIS)
          CALL PLUT15 (-4, JAT, 28, JDIS)
          IDIS = IPPR(IDIS + 1, 1)
          JDIS = IPPR(JDIS + 1, 1)
          IF (IDIS < 5000 .OR. JDIS < 5000) NLI = - IABS (NLI)
        ELSE
C * UNITCELL
          RBO = PAR(75)
          NLI = IPR(107)
        END IF
      ELSE
C * STICK - MODE
        NLI = 1
        RBO = 0.0
      END IF
      RETURN
      END SUBROUTINE PLUT27
 
      SUBROUTINE PLUT28 (IAT, JAT, XML)
C * HANDLE SPECIAL JOIN/LABEL/VIEW/DIST ARU
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cchar
      USE pluto
      USE sgxyz
      IMPLICIT NONE
      INTEGER  :: I
      INTEGER  :: J
      INTEGER  :: NR
      INTEGER  :: NS
      INTEGER  :: IAT
      INTEGER  :: JAT
      INTEGER  :: KAT
      INTEGER  :: ITX
      INTEGER  :: ITY
      INTEGER  :: ITZ
      INTEGER  :: MPM
      INTEGER  :: IVAL
      INTEGER  :: JDUM
      INTEGER  :: MADDR
      REAL :: XM2
      REAL :: XM3
      REAL :: XML
      MADDR = 0
      IF (NINT (XML) /= 0) THEN
C * STORE THIS ARU IN ARU-LIST
        CALL PLUT17 (-1, XML, MADDR, LU6)
C * UNPACK ARU
        MPM = NINT (XML * PAR(42))
        CALL GEN098 (MPM, PAR(42), NS, ITX, ITY, ITZ, NR)
        SGX(4) = ITX
        SGX(5) = ITY
        SGX(6) = ITZ
        DO I = 1, 3
          SGX(I) = RA(JAT * NP43 + I)
        END DO
        CALL SGSM (3, ICL, SGX, NS, LU6, IERR)
C * TEST FOR DUPLICATION OF ATOM IN COORDINATE LIST
        DO 10 KAT = IPR(69) + 1, IPR(37)
          DO J = 1, 3
            IF (ABS (RA(KAT * NP43 + J) - SGX(6 + J)) *
     1          PAR(100 + J) >= PAR(22)) GO TO 10
          END DO
          JAT = KAT
          RETURN
   10   CONTINUE
        IPR(37) = IPR(37) + 1
        IPR(38) = IPR(38) + 1
        KAT     = JAT
        JAT     = IPR(37)
        DO I = 1, 3
          RA(JAT * NP43 + I) = SGX(6 + I)
        END DO
C * ORTHOGONALIZE
        CALL PLUT23 (JAT)
C * SET FLAGS
        DO I = 8, 10
          RA(JAT * NP43 + I)  = RA(KAT * NP43 + I)
        END DO
        IF (IAT > 0) THEN
          CALL PLUT15 (-6, IAT,  5, IVAL)
          CALL PLUT15 ( 6, JAT,  5, IVAL)
        END IF
        IVAL = 0
        CALL PLUT15 ( 1, JAT, 27, IVAL)
C * COPY LABEL
        RA(JAT * NP43 + 7) = RA(KAT * NP43 + 7)
        CALL PLUT15 (6, JAT, 11, MADDR)
        CALL PLUT25 (1, JAT, JDUM)
        WRITE (LU6, 99999, IOSTAT = IOST) NQ1
C * SET TRNS
        XM2 = RA(KAT * NP43 + 12) * 1000.0
        CALL PLA270 (XML, XM2, XM3)
C * CALL EXIT/STOP
        IF (IPR(2) /= 0) CALL GEN127 ('101')
        RA(JAT * NP43 + 12) = XM3 / 1000.0
        RA(JAT * NP43 + 11) = RA(IAT * NP43 + 11)
      END IF
      RETURN
99999 FORMAT (':: ', A, ' added to coordinate list.')
      END SUBROUTINE PLUT28
 
      SUBROUTINE PLUT29 (MODE, LINE, NQ, NRFIX, LU)
C * RENAME/DELETE ETC RES-FILE
      USE files
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: IS
      INTEGER :: NR
      INTEGER :: NR0
      INTEGER :: NRES
      INTEGER :: NBLK
      INTEGER :: LENM
      INTEGER :: LRES
      INTEGER :: MODE
      INTEGER :: ISF1
      INTEGER :: ISF2
      INTEGER :: IDEL
      INTEGER :: NRFIX
      CHARACTER(len=*)  :: LINE
      CHARACTER(len=80) :: LIN
      CHARACTER(len=*)  :: NQ
      CHARACTER(len=2)  :: LTYPE
      CHARACTER(len=2)  :: SLT
      CHARACTER(len=4)  :: CRDT
      CHARACTER(len=4)  :: KEY
      CHARACTER(len=4)  :: RESD
      CHARACTER(len=4)  :: LYN
C * RES-ONLY
      IF (IABS(IGBL(8)) == 3 .AND. IGBL(3) == 8) RETURN
      LENM = MIN (80, LEN(LINE))
C * IPR(200) - START OF .RES STORAGE
C * IPR(201) - END   OF .RES STORAGE
C * MODE =  0 - INIT
C *      =  1 - ADD LINE
C *      =  2 - RENAME
C *      =  3 - HFIX
C *      =  4 - DELETE
C *      =  5 - ANIS
C *      = -1 - OUTPUT (MODIFIED) .RES (=NEW)
C * ADD LINE
      IF (MODE == 1) THEN
        IF (IPR(201) > IPR(80) + 80) THEN
          LIN = LINE(1:LENM)
          CALL GEN020 (1, LIN, 1, 4)
          NBLK = -1
          DO I = 1, 80
            IPR(201)     = IPR(201) - 1
            RA(IPR(201)) = ICHAR (LIN(I:I))
            IF (LIN(I:I) /= ' ') NBLK = 0
          END DO
          IPR(201)     = IPR(201) - 1
          RA(IPR(201)) = 0
          IPR(201)     = IPR(201) - 1
          RA(IPR(201)) = NBLK
          IPR(201)     = IPR(201) - 1
          RA(IPR(201)) = 0
C * DO/DONOT (IPR(176) SKIP Q-PEAKS)
          IF (LIN(1:1) == 'Q') IGBL(26) = IGBL(26) + IPR(176)
        ELSE
          WRITE (LU6, 99992) MODE
          STOP
        END IF
C * RENAME - MODE
      ELSE IF (MODE == 2) THEN
C * OVERRULE POSSIBLE Q-PEAK NON-DELETE
C * UPPER-CASE CHAR # 2
        CALL GEN020 (1, LINE, 2, 2)
        CALL GEN020 (1, NQ, 1, 4)
        I = IPR(200)
   10   IF (I - 83 >= IPR(201)) THEN
          WRITE (KEY, 99994, IOSTAT = IOST)
     1      (CHAR (NINT (RA(I - J))), J = 1, 4)
          IF (KEY == 'SADI') THEN
            DO K = 1, 4
              RA(I - K) = 32.0
            END DO
          END IF
          IF (KEY /= LINE(1:4)) THEN
            I = I - 83
            GO TO 10
          END IF
          IGBL(26) = IGBL(26) + 1
          DO J = 1, 4
            RA(I - J) = ICHAR (NQ(J:J))
          END DO
          RA(I - 82) = 0
          CALL GEN020 (1, NQ, 1, 2)
          LTYPE = NQ(1:1)//' '
          DO J =  ICHAR ('A'), ICHAR ('Z')
            IF (NQ(2:2) == CHAR (J)) THEN
              LTYPE = NQ(1:2)
              EXIT
            END IF
          END DO
          DO K = 1, NSF
            SLT = SFC(K)
            CALL GEN020 (1, SLT, 1, 2)
            IF (LTYPE == SLT) GO TO 20
          END DO
          NSF      = NSF + 1
          K        = NSF
          SFC(K)   = LTYPE
          NUNIT(K) = 1
C * REPLACE SCATTERING TYPE
   20     ISF1 = K / 10
          ISF2 = MOD (K, 10)
          DO J = 6, 20
            L = J
            IF (RA(I - J) /= ICHAR (' ')) THEN
              IF (RA(I - J - 1) /= ICHAR (' ')) THEN
                RA(I - J) = ICHAR (' ')
                L = L + 1
              END IF
              RA(I - L) = ICHAR ('0') + ISF2
              IF (ISF1 /= 0) RA(I - L + 1) = ICHAR ('1')
              GO TO 30
            END IF
          END DO
          GO TO 30
        END IF
C * HFIX MODE
      ELSE IF (MODE == 3) THEN
        NRES = 0
        I    = IPR(200)
        DO WHILE (I - 83 >= IPR(201))
          I = I - 83
          WRITE (KEY, 99994, IOSTAT = IOST)
     1      (CHAR (NINT (RA(I + 83 - J))), J = 1, 4)
          IF (KEY == 'RESI') THEN
            WRITE (RESD, 99994, IOSTAT = IOST)
     1        (CHAR (NINT (RA(I + 83 - J))), J = 5, 8)
            READ (RESD, *) NRES
            CYCLE
          END IF
          IF (NRES /= 0) THEN
            N = INDEX (LINE, '_')
            IF (N > 0) THEN
              READ (LINE(N +1:), *) LRES
              IF (LRES /= NRES) CYCLE
              LINE(N:) = ' '
            END IF
          END IF
          IF (KEY == LINE(1:4)) THEN
            IGBL(26)     = IGBL(26) + 1
            RA(I + 2)   = NRFIX
            IF (NFHAT == 0) THEN
              NSF        = NSF + 1
              SFC(NSF)   = 'H '
              NUNIT(NSF) = 1
              NFHAT      = 1
            END IF
          END IF
        END DO
C * DELETE ATOMS
      ELSE IF (MODE == 4) THEN
        CALL GEN020 (1, LINE, 1, 7)
        I = IPR(200)
        DO WHILE (I - 83 >= IPR(201))
          I = I - 83
          WRITE (KEY, 99994, IOSTAT = IOST)
     1      (CHAR (NINT (RA(I + 83 - J))), J = 1, 4)
          IF (KEY == LINE(1:4)) THEN
            IGBL(26)  = IGBL(26) + 1
            RA(I + 1) = -1
C * HANDLE EXTENSIONS (INDICATED BY '=')
            DO J = 1, 80
              IF (RA(I + 83 - J) == ICHAR ('=')) THEN
                I         = I - 83
                RA(I + 1) = -1
                EXIT
              END IF
            END DO
          END IF
        END DO
C * ANIS - MODE
      ELSE IF (MODE == 5) THEN
        I = IPR(200)
        DO WHILE (I - 83 >= IPR(201))
          I = I - 83
          WRITE (KEY, 99994, IOSTAT = IOST)
     1      (CHAR (NINT (RA(I + 83 - J))), J = 1, 4)
          IF (KEY == LINE(1:4)) THEN
            IGBL(26) = IGBL(26) + 1
            RA(I)    = 1
          END IF
        END DO
 
C * OUTPUT UPDATED RES-FILE
      ELSE IF (MODE == -1) THEN
        IDEL = 0
        NR0  = -1
        I    = IPR(200)
        DO WHILE (I - 83 >= IPR(201))
          I = I - 83
          DO J = 1, 80
            LIN(J:J) = CHAR (NINT (RA(I + 83 - J)))
          END DO
          CRDT = LIN(1:4)
          IF (CRDT == 'SFAC') THEN
            IF (IDEL == 0)
     1        WRITE (LU, 99999, IOSTAT = IOST) (SFC(K), K = 1, NSF)
            IDEL = 1
          ELSE IF (CRDT == 'UNIT') THEN
            WRITE (LU, 99998, IOSTAT = IOST) (NUNIT(K), K = 1, NSF)
            IDEL = 0
          ELSE IF (CRDT == 'AFIX') THEN
            READ (LIN(5:80), *) NR0
          ELSE IF (CRDT == 'FVAR') THEN
C * HFIX LOOP
            K = I
            DO WHILE (K - 83 >= IPR(201))
              K = K - 83
              DO J = 1, 4
                LYN(J:J) = CHAR (NINT (RA(K + 83 -J)))
              END DO
              NR = NINT (RA(K + 2))
              IF (NR /= 0)
     1          WRITE (LU, 99997, IOSTAT = IOST) NR, LYN(1:4)
            END DO
            WRITE (LU, 99993, IOSTAT = IOST) LIN
          ELSE IF (CRDT == 'HKLF') THEN
            NR0 = 0
            WRITE (LU, 99996, IOSTAT = IOST) NR0
            WRITE (LU, 99993, IOSTAT = IOST) LIN
            NR0 = -1
          ELSE
            IF (NINT (RA(I + 1)) /= 0) CYCLE
            IF (IPR(176) == 1 .AND. LIN(1:1) == 'Q') CYCLE
            IF (IDEL == 0) THEN
              NR = NINT (RA(I))
              IF (NR /= 0) THEN
                CALL PLA280 (LIN)
                CALL PLA006 (1, IS)
                WRITE (LIN (6:), 99995, IOSTAT = IOST) NINT (FN(1)),
     1            (FN(K), K = 2, 6), FN(6), FN(6), 0.0, 0.0, 0.0
              END IF
C * AVOID OUTPUT OF REDUNDANT AFIX LINES
              IF (NR0 >= 0) THEN
                WRITE (LU, 99996, IOSTAT = IOST) NR0
                NR0 = -1
              END IF
              WRITE (LU, 99993, IOSTAT = IOST) LIN
            ELSE IF (IDEL < 0) THEN
              IDEL = 0
            END IF
          END IF
        END DO
      ELSE IF (MODE == 0 .AND. LINE(1:3) /= 'END') THEN
        IPR(200) = NP49 - 6
        IPR(201) = IPR(200)
        IGBL(26) = 0
        NSF      = 0
      END IF
   30 IF (IABS (IGBL(8)) == 2 .AND. IPR(80) > IPR(201)) THEN
C * CALL EXIT/STOP
        CALL GEN127 ('PLUT29')
      END IF
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT ('SFAC', 16(2X, A))
99998 FORMAT ('UNIT', 2I5, 14I4)
99997 FORMAT ('HFIX', I5, 2X, A)
99996 FORMAT ('AFIX', I5)
99995 FORMAT (I3, 7F8.4, 3F4.1)
99994 FORMAT (4A)
99993 FORMAT (A)
99992 FORMAT (/, ':: Storage Overflow in PLUT29 (MODE =', I3, ')', /)
      END SUBROUTINE PLUT29
 
      SUBROUTINE PLUT30 (ITS, ITF)
C * ACTUAL CIRCLE PLOTTING
      USE parameters
      USE pluto
      IMPLICIT NONE
 
      INTEGER :: I
      INTEGER :: N
      INTEGER :: ITS
      INTEGER :: ITF
      INTEGER :: IUP
      INTEGER :: ITFF
      REAL :: XO
      REAL :: YO
      REAL :: ZO
      REAL :: XP
      REAL :: YP
      REAL :: ZP
      REAL :: RO
      REAL :: ROC
      REAL :: ROS
      REAL :: DTH1
      REAL :: DTH2
      REAL :: DTHS
      IF (IPR(114) > 0) THEN
        ITFF = MIN (ITF, IPR(114))
      ELSE
        ITFF = ITF
      END IF
      IF (ITS < ITFF) THEN
C * GET BEGIN AND END THETA VALUES
        DTH1     = PAR(57) + ITS  * PAR(55)
        DTH2     = PAR(57) + ITFF * PAR(55)
C * GET STEP SIZE
        N        = MAX (1, NINT((DTH2 - DTH1) / PAR(56)))
        DTHS     = (DTH2 - DTH1) / N
        IPR(129) = IPR(129) + N
C * GET CENTRE AND RADIUS OF CIRCLE
        XO       = PAR(71)
        YO       = PAR(72)
        ZO       = PAR(73)
        RO       = PAR(74)
        IUP      = 1
        DO I = 0, N
          ROC = RO * COS (DTH1)
          ROS = RO * SIN (DTH1)
          XP  = XO + ROC * ZU(1) + ROS * ZU(4)
          YP  = YO + ROC * ZU(2) + ROS * ZU(5)
          ZP  = ZO + ROC * ZU(3) + ROS * ZU(6)
          CALL GGIP (XP, YP, ZP, 2 + IUP)
          IUP  = 0
C * NEXT POINT OF CIRCL
          DTH1 = DTH1 + DTHS
        END DO
      END IF
      RETURN
      END SUBROUTINE PLUT30
 
      SUBROUTINE PLUT31 (K, COLR)
C * PUT DIAMOND
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      REAL :: X
      REAL :: Y
      REAL :: COL
      REAL :: DSH
      REAL :: COLR
      DSH = 0.15
      I   = K + NP0
      X   = RA(I - 3)
      Y   = RA(I - 2)
      COL = COLR
      IF (COL >= 0.0) CALL GGIP (0.0, COL, 0.0, 0)
C * PLOT MARKER
      CALL PLA406 (X, Y, DSH, -1.0)
      RETURN
      END SUBROUTINE PLUT31
 
      SUBROUTINE PLUT32
C * EXPLICIT RELABELLING ATOM LABELS IN RES FILE
      USE files
      USE parameters
      USE atomdata
      USE cchar
      USE cggt
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: M
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: IS
      INTEGER :: NS
      INTEGER :: NA
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: NEE
      INTEGER :: NEI
      INTEGER :: IER
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: NAX
      INTEGER :: NQX
      INTEGER :: NSS
      INTEGER :: IVAL
      INTEGER :: IAT1
      INTEGER :: IATK
      INTEGER :: NATL
      INTEGER :: IBEG
      INTEGER :: ICOL
      INTEGER :: IDUM
      INTEGER :: IEND
      INTEGER :: IASU
      INTEGER :: IREN
      INTEGER :: NIEN
      INTEGER :: NQSM
      INTEGER :: IXPK1
      INTEGER :: IXPK2
      INTEGER :: NPROP
      INTEGER :: INQNR
      INTEGER :: JNQNR
      INTEGER :: MSUBST
      REAL :: XL
      REAL :: YL
      REAL :: ZL
      REAL :: RL
      REAL :: XDUM
      REAL :: YUNK
      REAL :: PAR40
      CHARACTER(len=NP64) :: RIFL2
      CHARACTER(len=NP64) :: RIFL3
      IGBL(105) = 1
      KL        = IPR(220)
C * HANDLE ALIASES
      IF (KL > 1) THEN
        MSUBST = 0
        CALL PLA281 (1, IFL(2), MSUBST)
      END IF
      IF (KL > 2) THEN
        DO I = 3, KL, 2
          CALL PLUT13 (0, I - 1, IAT, XDUM)
          IF (IAT > 0) THEN
            CALL PLA046 (8, IFL(I - 1), NEI, NA, NAX, NS,
     1                   IXPK1, IXPK2, NIEN)
C * CHECK FOR UNIQUENESS OF NEW NAME
   10       CALL PLUT13 (1, I, JAT, XDUM)
            CALL PLA046 (9, IFL(I), NEE, NQX, NSS, NQSM,
     1                       INQNR, JNQNR, NIEN)
            IF (JAT <= 0) THEN
              IF (IFL(I)(1:3) == 'REN') THEN
                WRITE (LU6, 99997, IOSTAT = IOST) IFL(I)
                RETURN
              ELSE
                IF (NEE /= NEI) IPR(170) = 2
                YUNK = RA (IAT * NP43 + 7)
                DO J = 1, IPR(37)
                  IF (RA(J * NP43 + 7) == YUNK)
     1                RA(J * NP43 + 7) = INQNR
                END DO
                IF (RADR(NEE, 3) < 0.001) RADR(NEE, 3) =
     1              REL(IEN(NEE))
C * WRITE RENAME INSTRUCTION TO .pjn
                WRITE (LU22, 99996, IOSTAT = IOST) IFL(I - 1), IFL(I)
                IF (IABS (IGBL(8)) == 2)
     1            CALL PLUT29 (2, IFL(I - 1), IFL(I), 0, 0)
                CALL PLUT15 (1, IAT, 47, 1)
              END IF
            ELSE
C * SUBSTITUTE GENERATED LABEL
              IER = 0
              CALL PLUT41 (JAT, NEE, IER)
              IF (IER == 0) GO TO 10
              RETURN
            END IF
          ELSE
            WRITE (LU6, 99998, IOSTAT = IOST) IFL(I)
            RETURN
          END IF
        END DO
C * ENUMERATED RELABELING
      ELSE IF (KL <= 2) THEN
C * CLEAR GEOMETRY
        CALL PLUT24 (-2, IPR(38), IDUM)
        NCNT = 0
        IAT1 = 0
        IF (KL == 2) CALL PLUT13 (0, 2, IAT1, XDUM)
        IF (IAT1 > 0) THEN
          IBEG = IAT1
          IEND = IAT1
        ELSE
          IBEG = IPR(69) + 1
          IEND = IPR(39)
        END IF
        DO 50 I = IBEG, IEND
C * TEST FOR LABELLING TYPE ( 0 = NOLABELLING OF THIS ATOM)
          CALL PLUT15 (-4, I, 37, M)
          IF (M > 1) THEN
C * TEST FOR RESIDUE
            IF (IPR(140) /= 0) THEN
              CALL PLUT15 (-6, I, 5, IVAL)
              IF (IVAL /= IPR(140)) GO TO 50
            END IF
            IAT = I
            CALL PLUT25 (1, IAT, IATK)
            IF (IAT1 >= 0 .OR. -IAT1 == IATK) THEN
              IFL(2) = NQ1
              IFL(3) = NQ1
              CALL PLA046 (8, NQ1, NEI, NA, NAX, NS,
     1                     IXPK1, IXPK2, NIEN)
              NB = 1
              NE = 7
              CALL GEN039 (1, IFL(2), 1, 7, NB, NE)
              IPR(220) = 2
              KL       = IPR(220)
              CALL PLUT24 (1, IPR(38), IDUM)
              IFL(3) = NQ1
              RIFL2  = IFL(2)
              RIFL3  = IFL(3)
   20         IF (IWIN == 1) THEN
C * PAR40 IS THE HALF WIDTH OF THE LABEL IN CM.
                PAR40 = NE * PAR(349) * PAR(19) / 2.0
                NATL  = IPR(62) + I
                CALL PLUT14 (-1, NATL, IASU, NPROP, XL, YL, ZL, RL)
                CALL PLA439 (0.0, RIFL2, NE, PAR(349), 2, 2,
     1            XL - PAR40, YL - PAR(28))
                SBCD = 'Rename '//RIFL2(1:NE)//' (NewName/Quit['
                SBCD(23 + NE:) = RIFL3(1:NE)//'])'//CHAR (0)
C * MOUSE/KEYBOARD LOOP
C * WHAT NEXT ?
   30           CALL PLA012 (0, 1)
                SELECT CASE (IGGT(1:4))
C * RENAME
                  CASE ('REN ', 'RENA')
                    IF (IGGT(8:8) /= ' ') GO TO 30
                    IGGT(1:5)   = '     '
                    IFL(3)(1:1) = IFL(2)(1:1)
C * !
                  CASE ('!   ')
                    IF (LRET == 2) THEN
                      CALL PLUT02
                      GO TO 20
                    END IF
C * VIEW
                  CASE ('VIEW')
                    CALL PLA006 (1, IS)
                    CALL PLUT06
                    CALL PLUT02
                    GO TO 20
C * PLOT
                  CASE ('PLOT')
                    CALL PLUT02
                    GO TO 20
                  CASE ('LAB ', 'LABL')
                    GO TO 20
                  CASE ('ARU ')
                    GO TO 20
                  CASE ('OMI ', 'OMIT')
                    GO TO 20
                  CASE ('HFI ', 'HFIX')
                    GO TO 20
C * END
                  CASE ('END ')
                    IFL(3)(1:4) = 'QUIT'
C * EXIT
                  CASE ('EXIT')
                    IFL(3)(1:4) = 'QUIT'
                  CASE DEFAULT
C * SEARCH FOR NUMERAL IN POSITION #1
                    CALL GEN105 (3, IGGT(1:1), N)
                    IF (N < 0) THEN
                      IFL(3) = IGGT(1:7)
                    ELSE
C * SEARCH FOR NUMERAL IN POSITION #2
                      CALL GEN105 (3, IFL(2)(2:2), N)
                      IF (IFL(2)(2:2) == ' ' .OR. N >= 0) THEN
                        IFL(3) = IFL(2)(1:1)//IGGT(1:6)
                      ELSE
                        IFL(3) = IFL(2)(1:2)//IGGT(1:5)
                      END IF
                    END IF
                    CALL GEN038 (IGGT, 1, 80)
                END SELECT
              ELSE
                WRITE (LU6, 99999, ADVANCE = 'NO', IOSTAT = IOST)
     1            IFL(2), IFL(2)
                READ  (LU5, 99995) IFL(3)
              END IF
C * UPPER CASE
              CALL GEN020 (1, IFL(3), 1, 7)
              IF (IFL(3)(1:4) == 'QUIT' .OR. IFL(3)(1:3) == 'END')
     1          THEN
                CALL PLA280 ('PLOT')
                IPR(335) = 1
                CALL PLA015 (335, 1)
                RETURN
              END IF
C * LOWER CASE SECOND CHARACTER
              CALL GEN020 (-1, IFL(3), 2, 2)
              NEE = NEI
              IF (IFL(3) /= IFL(2) .AND. IFL(3)(1:1) /= ' ') THEN
   40           CALL PLUT13 (1, 3, JAT, XDUM)
                CALL PLA046 (9, IFL(3), NEE, NQX, NSS, NQSM,
     1                       INQNR, JNQNR, NIEN)
                IF (JAT <= 0) THEN
                  IF (NIEN >= 0) THEN
                    IF (NEE /= NEI) IPR(170) = 2
                    YUNK = RA (IAT * NP43 + 7)
                    DO J = 1, IPR(37)
                      IF (RA(J * NP43 + 7) == YUNK)
     1                    RA(J * NP43 + 7) = INQNR
                    END DO
                    IF (RADR(NEE, 3) < 0.001)
     1                  RADR(NEE, 3) = REL(IEN(NEE))
C * WRITE RENAME INSTRUCTION TO .pjn
                    WRITE (LU22, 99996, IOSTAT = IOST) IFL(2), IFL(3)
                    IF (IABS(IGBL(8)) == 2)
     1                CALL PLUT29 (2, IFL(2), IFL(3), 0, 0)
                    CALL PLA439 (0.0, IFL(2), NE, PAR(349), 0, 2,
     1                XL - PAR40, YL - PAR(28))
                    CALL PLUT15 (1, IAT, 47, 1)
                    CALL GEN039 (1, IFL(3), 1, 7, NB, NE)
                    PAR40 = NE * PAR(349) * PAR(19) / 2.0
                  ELSE
C * NO SUBSTITUTION (CONFLICT/ERROR)
                    CALL PLA015 (0, 28)
                    GO TO 20
                  END IF
                ELSE
C * SUBSTITUTE GENERATED LABEL
                  IER = 0
                  CALL PLUT41 (JAT, NEE, IER)
                  IF (IER /= 0) GO TO 20
                  GO TO 40
                END IF
              END IF
              IF (NEE /= NEI) THEN
                CALL PLUT02
              ELSE
C * LOWER CASE SECOND CHARACTER
                CALL GEN020 (-1, IFL(3), 2, 2)
                CALL PLUT15 (-1, IAT, 47, IREN)
                ICOL = 1
                IF (IREN == 1) ICOL = 3
                CALL PLA439 (0.0, IFL(3), NE, PAR(349), ICOL, 2,
     1                       XL - PAR40, YL - PAR(28))
              END IF
            END IF
          END IF
   50   CONTINUE
        IF (IEND > IBEG) THEN
          IPR(332)  = 1
          CALL PLA015 (335, 1)
C * RESET TO 'NO-RENAME'
          IF (IPR(308) /= 0) IGBL(3) = 8
        END IF
C * TERMINATE RENAME AT END OF LOOP
      END IF
      RETURN
99999 FORMAT (/, 'Rename ', A, ' (NewName/Quit[', A, '])')
99998 FORMAT (':: No Substitution: Unsuitable Old Label: ', A)
99997 FORMAT (':: No Substitution: Unsuitable New Label: ', A)
99996 FORMAT ('RENAME', 2(1X, A))
99995 FORMAT (A)
      END SUBROUTINE PLUT32
 
      SUBROUTINE PLUT33
C * LOAD UNITCELL PLOT DATA
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: N0
      INTEGER :: ND
      INTEGER :: NN
      INTEGER :: NEL
      INTEGER :: ID1
      INTEGER :: ID2
      INTEGER :: IDUM0
      INTEGER :: IDUM2
      REAL :: DUM1
      REAL, DIMENSION(NP43) :: YANK
      IPR(64)  = IPR(80) - IPR(76) * 3
      IPR(100) = 1
C * SET UP CELL CONNECTIVITY HERE
      ID1      = 0
      ID2      = 0
      IF (IPR(50) == 0)
     1  CALL PLUT16 (-2, IDUM0, ID1, ID2, DUM1, IDUM2)
      IF (IGBL(33) == 1) THEN
C * SORT ATOM ARRAY
        N0      = IPR(69) + 1
        N       = IPR(37)
C * SORT FROM N0 TO N (SMALL TO LARGE)
        NEL     = N - N0 + 1
        IF (NEL <= 1) RETURN
        NN      = INT (ALOG (FLOAT (NEL)) / ALOG (2.0))
        ND      = 2**NN - 1
   10   IF (ND <= 0) RETURN
        I       = N0
   20   J       = I
        DO K = 1, NP43
          YANK(K) = RA((I + ND) * NP43 + K)
        END DO
   30   IF (YANK(6) >= RA(J * NP43 + 6)) GO TO 40
        DO K = 1, NP43
          RA((J + ND) * NP43 + K) = RA(J * NP43 + K)
        END DO
        J = J - ND
        IF (J >= N0) GO TO 30
   40   DO K = 1, NP43
          RA((J + ND) * NP43 + K) = YANK(K)
        END DO
        I = I + 1
        IF (I + ND <= N) GO TO 20
        ND = (ND - 1) / 2
        GO TO 10
      END IF
      RETURN
      END SUBROUTINE PLUT33
 
      SUBROUTINE PLUT35 (XMOL, MODE)
C * EXPAND ARU/MOLECULE
      USE files
      USE parameters
      USE pluto
      USE sgxyz
      IMPLICIT  NONE
      INTEGER :: I
      INTEGER :: M3
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: ITX
      INTEGER :: ITY
      INTEGER :: ITZ
      INTEGER :: MPM
      INTEGER :: MR2
      INTEGER :: MS2
      INTEGER :: MS3
      INTEGER :: MS1
      INTEGER :: MT1
      INTEGER :: MT2
      INTEGER :: MT3
      INTEGER :: MR1
      INTEGER :: NARU
      INTEGER :: MT13
      INTEGER :: MT23
      INTEGER :: MT33
      INTEGER :: MSGN
      INTEGER :: MODE
      INTEGER :: MADDR
      REAL :: XM3
      REAL :: XMOL
      CHARACTER(len=NP45) :: ICLL
C * DO-NOT FOR INFINITE STRUCTURES AND GLOBAL ARU INSTRUCTION
      IF (ABS(XMOL) <= IPR(75) .OR. IGBL(127) /= 0) THEN
        MADDR = 0
        CALL PLUT17 (MODE, XMOL, MADDR, LU6)
        RETURN
      END IF
      IF (XMOL > 0) THEN
        MSGN = 1
      ELSE
        MSGN = -1
      END IF
C * COPY RELATED ARU'S
      NARU = NINT (ABS(XMOL) * PAR(42))
      CALL GEN098 (NARU, PAR(42), MS1, MT1, MT2, MT3, MR1)
      IF (MR1 /= 0) THEN
        NB = MR1
        NE = MR1
      ELSE
        NB = 1
        NE = IPR(75)
      END IF
      DO MR1 = NB, NE
        DO I = 1, IPR(43)
          MPM = IARU(1, I)
          CALL GEN098 (MPM, PAR(42), MS2, ITX, ITY, ITZ, MR2)
          SGZ(6) = ITX
          SGZ(7) = ITY
          SGZ(8) = ITZ
          IF (MR2 == MR1) THEN
            SGZ(1) = MS1
            SGZ(2) = MT1
            SGZ(3) = MT2
            SGZ(4) = MT3
            SGZ(5) = MS2
            CALL SGSM (8, ICLL, SGZ, 0, LU6, IERR)
            IF (IERR /= 0) THEN
              WRITE (LU6, 99999, IOSTAT = IOST) XMOL
              RETURN
            END IF
            MS3  = NINT (SGZ(9))
            MT13 = NINT (SGZ(10))
            MT23 = NINT (SGZ(11))
            MT33 = NINT (SGZ(12))
            M3   = (MS3 * 1000 + MT13 * 100 + MT23 * 10 + MT33 + 555)
            M3   = NINT (M3 * PAR(42)) + MR1
            XM3  = (M3 / PAR(42)) * MSGN
            MADDR = 0
            CALL PLUT17 (MODE, XM3, MADDR, LU6)
          END IF
        END DO
      END DO
      RETURN
99999 FORMAT ('Multiply Problem with ARU = ', F10.2)
      END SUBROUTINE PLUT35
 
      SUBROUTINE PLUT36 (MODE, ISHADE)
C * SHADE MODE
      USE parameters
      USE pluto
      IMPLICIT NONE
      INTEGER :: NN
      INTEGER :: ISH
      INTEGER :: MODE
      INTEGER :: IHOR
      INTEGER :: IANG2
      INTEGER :: ICOL2
      INTEGER :: ISHADE
      REAL :: YS
      REAL :: R0
      REAL :: R1
      REAL :: CA
      REAL :: CB
      REAL :: SB
      REAL :: R0K
      REAL :: RSQ
      REAL :: XPL1
      REAL :: XPL2
      REAL :: XPL4
      REAL :: XPL5
      REAL :: ANG3
      REAL :: DISP
C * SHADE MODE OF ATOM MODE
      DO ISH = 1, ISHADE
C * DRAW SHADE LINES ON SURFACE OF SPHERE.
C * LIGHT SOURCE AT YROT, ZROT GIVEN BY (ANG1, ANG2)
        ICOL2 = MOD (IPR(88), 100)
        IF (ICOL2 > 8) ICOL2 = 0
        IANG2 = IPR(88) / 100
        ANG3  = PAR(8) + MOD (IANG2, 100)
        IANG2 = IANG2 / 100
        IHOR  = 1
        IF (ANG3 /= 0.0) THEN
          ANG3 = ANG3 / RGBL(6)
          CB   = COS (ANG3)
          SB   = SIN (ANG3)
          IHOR = 0
        ELSE
          CB   = 1.0
          SB   = 0.0
        END IF
        IF (PAR(7) /= 0.0) THEN
          CA   = COS (PAR(7) / RGBL(6))
          IHOR = 0
        ELSE
          CA = 1.0
        END IF
        NN   = 1
        DISP = PAR(6)
C * HANDLE DISP PERSPECTIVE
        IF (PAR(48) > 0.0)
     1    DISP = DISP * PAR(48) / (PAR(48) - XYZK(3))
        DISP = MAX (DISP, PAR(23))
        IF (IPR(346) > 0) THEN
          CALL GGIP (0.0, FLOAT (ICOL2), 0.0, 0)
        END IF
        R0  = XYZK(4)
        R0K = R0**2
        YS  = - R0
C * ONCE THROUGH THIS LOOP FOR EACH SHADING LINE TO BE DRAWN
        DO
          RSQ = R0K - YS**2
          IF (RSQ > 0.0001) THEN
            R1 = SQRT (RSQ)
C * SET UP END-POINTS OF LINE
            IF (IHOR == 1) THEN
              XPL1 =   R1
              XPL2 =   YS
              XPL4 = - R1
              XPL5 =   YS
            ELSE
              XPL1 =   CB * CA * R1 + SB * YS
              XPL2 = - SB * CA * R1 + CB * YS
              XPL4 = - CB * R1 + SB * YS
              XPL5 =   SB * R1 + CB * YS
            END IF
            XYZPL(1) = XPL1 + XYZK(1)
            XYZPL(2) = XPL2 + XYZK(2)
            XYZPL(3) = SQRT (ABS (R0K - XPL1**2 - XPL2**2))
     1               +   XYZK(3)
            XYZPL(4) = XPL4 + XYZK(1)
            XYZPL(5) = XPL5 + XYZK(2)
            XYZPL(6) = XYZK(3)
C * PLOT THIS LINE AND TEST FOR OBSCURATIONS BY ATOMS/BONDS
            CALL PLUT19 (MODE, NN)
C * DRAW NEXT LINE IN REVERSE DIRECTION
            NN = - NN
          END IF
C * END OF LOOP FOR SHADING
          YS = YS + DISP
          IF (YS >= R0) EXIT
        END DO
        IF (IPR(346) > 0) CALL GGIP (0.0, FLOAT (IPR(19)), 0.0, 0)
        PAR(8) = PAR(8) + 90.0
      END DO
      RETURN
      END SUBROUTINE PLUT36
 
      SUBROUTINE PLUT37 (IAT, JAT, KAT, LAT, OMEGA)
      USE parameters
      USE pluto
C * BOND ANGLE
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IAT
      INTEGER :: JAT
      INTEGER :: KAT
      INTEGER :: LAT
      REAL :: VA
      REAL :: VB
      REAL :: DAB
      REAL :: DAK
      REAL :: DBK
      REAL :: COSW
      REAL :: OMEGA
      REAL :: GEN009
      IF (LAT == 0) THEN
        DAK = 0
        DBK = 0
        DAB = 0
        DO I = 4, 6
          VA  = RA(IAT * NP43 + I) - RA(JAT * NP43 + I)
          VB  = RA(KAT * NP43 + I) - RA(JAT * NP43 + I)
          DAK = DAK + VA**2
          DBK = DBK + VB**2
          DAB = DAB + VA*VB
        END DO
        IF (DAK <= 0.0 .OR. DBK <= 0.0) THEN
          OMEGA = 0.0
        ELSE
          DAB   = MAX (-1.0, MIN (1.0, DAB / SQRT (DAK * DBK)))
          OMEGA = ACOS (DAB) * RGBL(6)
        END IF
      ELSE
C * TORSION ANGLE
        DO I = 1, 3
          ZU(I)     = RA(JAT * NP43 + I + 3) - RA(IAT * NP43 + I + 3)
          ZU(I + 3) = RA(KAT * NP43 + I + 3) - RA(JAT * NP43 + I + 3)
          ZU(I + 6) = RA(LAT * NP43 + I + 3) - RA(KAT * NP43 + I + 3)
        END DO
        CALL GEN008 (ZU(1),  ZU(4),  ZU(10), 1)
        CALL GEN008 (ZU(4),  ZU(7),  ZU(13), 1)
        CALL GEN008 (ZU(10), ZU(13), ZU(1),  1)
        COSW  = MAX (-1.0, MIN (1.0, GEN009 (ZU(10), ZU(13))))
        OMEGA = ACOS (COSW) * RGBL(6)
        IF (GEN009 (ZU(1), ZU(4)) < 0.0) OMEGA = - OMEGA
      END IF
      RETURN
      END SUBROUTINE PLUT37
 
      SUBROUTINE PLUT38 (NER, NERR, LU)
C * ERROR HANDLING
      IMPLICIT NONE
      INTEGER :: LU
      INTEGER :: NER
      INTEGER :: NERR
      INTEGER :: IOST
      SELECT CASE (NER)
        CASE (1)
          WRITE (LU, 99999, IOSTAT = IOST)
        CASE (2)
        CASE (3)
          WRITE (LU, 99997, IOSTAT = IOST)
        CASE (4)
          WRITE (LU, 99996, IOSTAT = IOST)
          WRITE (LU, 99995, IOSTAT = IOST)
        CASE (5)
          WRITE (LU, 99994, IOSTAT = IOST)
        CASE (6)
          WRITE (LU, 99993, IOSTAT = IOST) CHAR (7)
        CASE (7)
          WRITE (LU, 99998, IOSTAT = IOST)
        CASE (8)
        CASE (9)
        CASE (10)
      END SELECT
C * CALL EXIT/STOP
      IF (NERR == 1) CALL GEN127 (' FATAL PROBLEM')
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT (/'>>> PROBLEM TOO LARGE; INCREASE ARRAY SIZE (NP49) <<<')
99998 FORMAT (/':: Too Many FVAR - Parameters')
99997 FORMAT (/'>>> STACK1 OVERFLOW;  INCREASE ARRAY SIZE (NP49) <<<')
99996 FORMAT (/'>>> PROBLEM WITH SHELX-STYLE INPUT <<<')
99995 FORMAT (/'    CHECK FVAR-FREE VARIABLES CONSISTENCY !')
99994 FORMAT (/':: Problem Too Large to fit in scratch array (Ignored)'
     1        )
99993 FORMAT (/':: Parameter outside acceptable range (ignored)', A)
      END SUBROUTINE PLUT38
 
      SUBROUTINE PLUT39
C * PACK RANGE/PLAN INSTRUCTIONS
      USE files
      USE parameters
      USE pluto
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      INTEGER :: KL
      INTEGER :: KN
      INTEGER :: MML
      INTEGER :: NRS
      INTEGER :: NSYM
      INTEGER :: MODE
      INTEGER :: NRES
      INTEGER :: ITKK
      INTEGER :: MADDR
      REAL :: XML
      REAL :: CMAX
      REAL :: CMIN
      REAL :: CMIA
      REAL :: DHKL
      REAL :: XDUM
      CHARACTER(len=1) :: N1
C * MODE =   0 : PACK RANGE CALCULATION WITH C.G.
C * MODE = > 1 :  ,,    ,,     ,,        ,,  ATOM
      MODE     = 0
C * SET REBUILD
      IPR(130) = 0
      NSYM     = IPR(48)
      NRES     = IPR(75)
      KL       = IPR(220)
      KN       = IPR(221)
C * TEST FOR PACK RANGE MODE (=0)
C * SET DEFAULT PACK RANGE
      CALL GEN074 (PAR, 119, 121, -0.01)
      CALL GEN074 (PAR, 122, 124,  0.01)
C * SET DEFAULT MAXIMUM TO PLANE DISTANCES
      RA(IPR(80) + 5) = -1.5
      RA(IPR(80) + 6) =  1.5
C * GET PACK RANGE PARAMETERS
      I = 0
      IF (KL > 1) THEN
        DO L = 2, KL
          N1 = IFL(L)(1:1)
C * PACK RANGE PARAMETERS
          IF (N1 == 'R') THEN
            DO J = 1, 3
              IF (I + 2 <= KN) THEN
                PAR(118 + J) = FN(I + 1)
                PAR(121 + J) = FN(I + 2)
              END IF
              I = I + 2
            END DO
            IPR(126) = 1
C * PACK PLAN H K L PARAMETERS
          ELSE IF (N1 == 'P') THEN
            IPR(36) = 1
            IF ((KN - 3) < I) CYCLE
            DO K = 1, 3
              I = I + 1
              IPR(31 + K) = NINT (FN(I))
            END DO
            IF ((KN - 2) < I) CYCLE
C * MAXIMUM TO PLANE DISTANCES
            RA(IPR(80) + 5) = FN(I + 1)
            RA(IPR(80) + 6) = FN(I + 2)
            I = I + 2
          ELSE IF (N1 == 'C') THEN
            IPR(31) = 1
            CALL PLUT13 (0, KL, MODE, XDUM)
            IPR(220) = IPR(220) - 1
            KL       = IPR(220)
            IF (MODE <= 0) GO TO 50
          END IF
        END DO
      END IF
C * FIND MOLECULES HAVING THEIR CENTRE WITHIN THE RANGE GIVEN
      IF (IPR(126) == 0) THEN
C * TEST FOR PLANE MODE
        IF (IPR(36) > 0) THEN
          CMIA = 0
        ELSE
          CMIA = 2
        END IF
        CMIN = -2
        CMAX =  3
        DO K = 1, 3
          PAR(118 + K) = CMIN + CMIA
          PAR(121 + K) = CMAX - CMIA
        END DO
      END IF
C * UNIQUE AND HBOND ARU INACTIVE
      MADDR = 0
      CALL PLUT17 (3, 0.0, MADDR, LU6)
      DO NRS = 1, NRES
        DO K = 1, 3
          SGX(K + 3) = 0.0
          IF (MODE == 0) THEN
            SGX(K) = RCG(K, NRS)
          ELSE
            SGX(K) = RA(MODE * NP43 + K)
          END IF
          SGY(K) = SGX(K)
        END DO
        IF (IPR(36) > 0) THEN
          DHKL = IPR(32) * IPR(32) * PAR(107)
     1         + IPR(33) * IPR(33) * PAR(108)
     2         + IPR(34) * IPR(34) * PAR(109)
     3         + IPR(32) * IPR(33) * PAR(118)
     4         + IPR(32) * IPR(34) * PAR(117)
     5         + IPR(33) * IPR(34) * PAR(116)
          DHKL = SQRT (DHKL)
          RA(IPR(80) + 4) = 0.0
          DO K = 1, 3
            RA(IPR(80) + K) = FLOAT (IPR(K + 31)) / DHKL
            RA(IPR(80) + 4) = RA(IPR(80) + 4) +
     1                        RA(IPR(80) + K) * SGY(K)
          END DO
        END IF
C * GENERATE AND TEST ARU'S FOR BEING WITHIN PACK RANGE
        DO N = 1, NSYM
          CALL SGSM (3, ICL, SGX, N, LU6, IERR)
          DO K = 1, 3
            T(K)     = 0.0
            XYZOR(K) = SGX(K + 6)
          END DO
          K = 1
   10     IF (XYZOR(K) < PAR(K + 118))  GO TO 20
          XYZOR(K) = XYZOR(K) - 1.0
          T(K) = T(K) - 1.0
          GO TO 10
   20     XYZOR(K) = XYZOR(K) + 1.0
          T(K)     = T(K) + 1.0
          IF (XYZOR(K) > PAR(K + 121))  GO TO 40
          K = K + 1
          IF (K <= 3)  GO TO 10
          DO J = 1, 3
            ITKK = NINT (T(J))
C * T(KK) TO BE WITHIN THE RANGE -5:4
            IF (ITKK > 4 .OR. ITKK < -5) GO TO 30
          END DO
          MML = N * 1000 + NINT (T(1)) * 100 + NINT (T(2)) * 10
     1        + NINT(T(3)) + 555
          XML = MML + NRS / PAR(42)
C * COPY ALL TRANSFORMED ARU'S FOR NRS
          CALL PLUT35 (XML, 0)
   30     K = K - 1
          GO TO 20
   40     K = K - 1
          IF (K > 0)  GO TO 20
        END DO
      END DO
   50 IPR(36) = 0
      RETURN
      END SUBROUTINE PLUT39
 
      SUBROUTINE PLUT40 (I, J, N, ISW)
C * TEST FOR D-H
      USE files
      USE parameters
      USE pluto
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: I0
      INTEGER :: J0
      INTEGER :: IDH
      INTEGER :: JDH
      INTEGER :: ISW
      INTEGER :: IHAT
      INTEGER :: NATO
      REAL :: D
      REAL :: ANG
      NATO = IPR(39)
      ISW  = -1
C * TEST FOR H-ATOM
      CALL PLUT15 (-1, I, 44, IHAT)
      IF (IHAT == 1) THEN
C * TEST FOR D-H ATOM
        IF (IPR(109) == 1) THEN
          CALL PLUT15 (-1, I, 32, IDH)
        ELSE
          IDH = 1
        END IF
        IF (IDH > 0) THEN
C * PUT TRANSFORMED COORDINATES FOR J IN 0
          DO K = 1, 3
            SGX(K)     = RA(J * NP43 + K)
            SGX(K + 3) = T(IPR(120 + K))
          END DO
          CALL SGSM (3, ICL, SGX, N, LU6, IERR)
          DO K = 1, 3
            RA(K) = SGX(K + 6)
          END DO
          CALL PLUT23 (0)
C * FIND DONOR ATOM BONDED TO I
          DO I0 = IPR(69) + 1, NATO
            CALL PLUT22 (I0, I, D)
            IF (D < 1.25) THEN
              CALL PLUT37 (I0, I, 0, 0, ANG)
              IF (ANG >= PAR(97)) ISW = 1
              RETURN
            END IF
          END DO
        END IF
      ELSE
C * TEST FOR D-H ATOM
        CALL PLUT15 (-1, J, 32, JDH)
        IF (JDH > 0) THEN
C * GET INVERSE OPERATION TO APPLY ON ATOM I
          SGX(1) = N
          DO K = 1, 3
            SGX(K + 1) = T(IPR(120 + K))
          END DO
          CALL SGSM (9, ICL, SGX, 0, LU6, IERR)
          DO K = 1, 3
            SGX(K)     = RA(I * NP43 + K)
            SGX(K + 3) = SGX(9 + K)
          END DO
          M = NINT (SGX(9))
          CALL SGSM (3, ICL, SGX, M, LU6, IERR)
          DO K = 1, 3
            RA(K) = SGX(6 + K)
          END DO
          CALL PLUT23 (0)
          DO J0 = IPR(69) + 1, NATO
            CALL PLUT22 (J0, J, D)
            IF (D < 1.25) THEN
              CALL PLUT37 (J0, J, 0, 0, ANG)
              IF (ANG >= PAR(97)) ISW = 1
              RETURN
            END IF
          END DO
        END IF
      END IF
      RETURN
      END SUBROUTINE PLUT40
 
      SUBROUTINE PLUT41 (JAT, NEE, IER)
C * SUPPORT RENAME/SUBSTITUTION FUNCTION
      USE files
      USE parameters
      USE atomdata
      USE pluto
      IMPLICIT NONE
      INTEGER :: J
      INTEGER :: K
      INTEGER :: J1
      INTEGER :: J2
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: JM
      INTEGER :: JAT
      INTEGER :: KAT
      INTEGER :: NEE
      INTEGER :: NQX
      INTEGER :: IER
      INTEGER :: NE4
      INTEGER :: NSS
      INTEGER :: IASU
      INTEGER :: NATZ
      INTEGER :: NQSM
      INTEGER :: NIEN
      INTEGER :: NPROP
      INTEGER :: INQNR
      INTEGER :: JNQNR
      REAL :: ZL
      REAL :: RL
      REAL :: XLZ
      REAL :: YLZ
      REAL :: XDUM
      REAL :: YUNK
      REAL :: PAR40
C * SUBSTITUTE TEMPORARY NEW LABEL
      NB = 1
      NE = 7
      J1 = IEL(IEN(NEE)) / 100
      J2 = MOD (IEL(IEN(NEE)), 100)
      IF (J2 == 0) THEN
        JM = 900
      ELSE
        JM = 90
      END IF
      DO J = 1, JM
        IF (J2 == 0) THEN
          WRITE (IFL(4), 99999, IOSTAT = IOST)
     1      CHAR (ICHAR ('A') + J1 - 1), 1000 - J
        ELSE
          WRITE (IFL(4), 99998, IOSTAT = IOST)
     1      CHAR (ICHAR ('A') + J1 - 1), CHAR (ICHAR ('a') + J2 - 1),
     2      100 - J
        END IF
        CALL PLUT13 (1, 4, KAT, XDUM)
        IF (KAT <= 0) THEN
          CALL PLA046 (9, IFL(4), NE4, NQX, NSS, NQSM,
     1                 INQNR, JNQNR, NIEN)
        YUNK = RA (JAT * NP43 + 7)
        DO K = 1, IPR(37)
          IF (RA(K * NP43 + 7) == YUNK)
     1    RA(K * NP43 + 7) = INQNR
        END DO
C * WRITE RENAME INSTRUCTION TO .pjn
        WRITE (LU22, 99997, IOSTAT = IOST) IFL(3), IFL(4)
        IF (IABS (IGBL(8)) == 2) CALL PLUT29 (2, IFL(3), IFL(4), 0, 0)
          CALL PLA015 (0, 53)
          CALL GEN039 (1, IFL(3), 1, 7, NB, NE)
          PAR40 = NE * PAR(349) * PAR(19) / 2.0
          NATZ  = IPR(62) + JAT
          CALL PLUT14 (-1, NATZ, IASU, NPROP, XLZ, YLZ, ZL, RL)
          CALL PLA439 (0.0, IFL(3), NE, PAR(349), 0, 2,
     1                 XLZ - PAR40, YLZ - PAR(28))
          CALL GEN039 (1, IFL(4), 1, 7, NB, NE)
          PAR40 = NE * PAR(349) * PAR(19) / 2.0
          CALL PLA439 (0.0, IFL(4), NE, PAR(349), 1, 2,
     1                 XLZ - PAR40, YLZ - PAR(28))
          RETURN
        END IF
      END DO
C * NO SUBSTITUTION (CONFLICT)
      CALL PLA015 (0, 8)
      WRITE (LU6, 99996, IOSTAT = IOST) IFL(3), IFL(2), CHAR(7)
      IER = 1
      RETURN
99999 FORMAT (A, I3)
99998 FORMAT (2A, I2)
99997 FORMAT ('RENAME', 2(1X, A))
99996 FORMAT (':: No Substitution: New Label: ', A, 'for: ', A,
     1        'conflicts with label in list', A)
      END SUBROUTINE PLUT41
 
      SUBROUTINE PLUT42 (NB, IATK, JATK, SANG, ANGM, NMET, D, D1, D2,
     1  MNCODE)
C * SUPPORT RES HFIX
      USE atomdata
      IMPLICIT NONE
      INTEGER :: NB
      INTEGER :: IATK
      INTEGER :: IATL
      INTEGER :: JATK
      INTEGER :: JATL
      INTEGER :: NMET
      INTEGER :: MNCODE
      REAL :: SANG
      REAL :: ANGM
      REAL :: D
      REAL :: D1
      REAL :: D2
      IF (NB == 0) THEN
        MNCODE = -1
      ELSE
        IATL   = IATNR(IEN(IATK))
        JATL   = IATNR(IEN(JATK))
        MNCODE = 0
C * HOST = Boron
        IF (IATL == 5) THEN
          IF (NB == 4) THEN
            IF (ANGM < 130) THEN
              MNCODE = -1
            ELSE
              MNCODE = 153
            END IF
          ELSE IF (NB == 5) THEN
            MNCODE = 153
          END IF
C * HOST = Carbon
        ELSE IF (IATL == 6) THEN
C * FOUR BONDS - NO ATTACHED H-ATOMS
          IF (NB == 4) THEN
            MNCODE = -1
          ELSE IF (NB == 3) THEN
            IF (SANG < 340.0) THEN
              IF (NMET == 1) THEN
                MNCODE = 43
              ELSE
                MNCODE = 13
              END IF
            ELSE IF (SANG > 350) THEN
              MNCODE = -1
            END IF
          ELSE IF (NB == 2) THEN
            IF (SANG < 115) THEN
              IF (D1 > 1.45) THEN
                MNCODE = 23
              ELSE
                MNCODE = 43
              END IF
            ELSE IF (SANG > 150.0) THEN
              MNCODE = -1
            ELSE
              IF (D1 > 1.45 .AND. D2 > 2.0) THEN
                MNCODE = 23
              ELSE
                MNCODE = 43
              END IF
            END IF
C * TERMINAL CH3 - FREE ROTATOR
          ELSE IF (NB == 1) THEN
            IF (D > 1.4) THEN
              MNCODE = 137
            ELSE IF (D > 1.25) THEN
              MNCODE = 93
            ELSE
              MNCODE = 163
            END IF
          END IF
C * HOST = Nitrogen
        ELSE IF (IATL == 7) THEN
          IF (NB == 1) THEN
            IF (D > 1.35) MNCODE = 93
          END IF
C * HOST = Oxygen
        ELSE IF (IATL == 8) THEN
          IF (NB == 1) THEN
C * TEST FOR BONDED TO P OR S
            IF (JATL == 15 .OR. JATL == 16) THEN
              IF (D > 1.5)  MNCODE = 83
            ELSE
              IF (D > 1.27) MNCODE = 83
            END IF
          ELSE
            MNCODE = -1
          END IF
        ELSE
          MNCODE = -1
        END IF
      END IF
      RETURN
      END SUBROUTINE PLUT42
 
      SUBROUTINE PLUT43 (IB, IBEG, IEND, X, Y, DELMIN, IASU, IMIN)
C * FIND NEAREST ITEM
      USE pluto
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IB
      INTEGER :: IBEG
      INTEGER :: IEND
      INTEGER :: IASU
      INTEGER :: IMIN
      REAL :: X
      REAL :: Y
      REAL :: DEL
      REAL :: DELMIN
      DO I = IBEG, IEND
        IB  = IB + NP0
        DEL = (RA(IB - 3) - X)**2 + (RA(IB - 2) - Y)**2
        IF (DEL < DELMIN - 0.001) THEN
          IASU   = NINT (RA(IB - 5))
          IMIN   = I
          DELMIN = DEL
        END IF
      END DO
      RETURN
      END SUBROUTINE PLUT43
