     1                               -1, 0, 0, 0, -1, 0,  0, 0, -1,
     2                               -1, 0, 0, 0, -1, 0,  0, 0,  1,
     3                                1, 0, 0, 0, -1, 0, -2, 0, -1,
     4                                0, 1, 0, 1,  0, 0,  0, 0, -1/
     5                                ),  (/9, 4/))
      REAL, DIMENSION(3, 3)    :: TM
