      SUBROUTINE S
 
      USE scom
      IMPLICIT NONE
C * IGBL(50) = -1  - REMOVE
C *          =  0  - GUIDED MODE
C *          =  1  - NQA    - (Graphics)MODE
C *          =  2  - NQA/-F - (Silent)MODE
C * SYSTEM-S STARTUP
      CALL S010
C * SYSTEM-S MAIN INSTRUCTION LOOP
      DO WHILE (ISW == 0)
C * DECIDE ON/SUGGEST NEXT STEP
        CALL S030 (0)
C * GET/EXECUTE NEXT INSTRUCTION
        CALL S050
      END DO
      RETURN
      END SUBROUTINE S
 
      SUBROUTINE S010
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: IB
      INTEGER :: ID0
      INTEGER :: ID1
      INTEGER :: ID2
      INTEGER :: ID3
      INTEGER :: JVERS
      INTEGER :: FINDEXE
      REAL :: XSH
      REAL :: YVRT
      CHARACTER(len=256) :: LIN
      LOGICAL :: DINQ
      IGBL(1) = 4
C * CHECK FOR NON-ROOT USER
      CALL GET_ENVIRONMENT_VARIABLE ('LOGNAME', VALUE = LIN)
      IF (LIN(1:4) == 'root') THEN
        WRITE (LIN, 99998)
        CALL PRINTX (LU6, LIN(1:80), 2, 2)
        ISW = -1
        RETURN
      END IF
C * CHECK FOR X-WINDOW MODE - IF NOT QUIT  (EXCEPT FOR -F MODE)
      IF (IGBL(50) < 2) THEN
C * CHECK FOR X11 GRAPHICS
        IF (IGBL(32) /= 1) THEN
          WRITE (LIN, 99997)
          CALL PRINTX (LU6, LIN(1:80), 2, 2)
          ISW = -1
          RETURN
        ELSE
          IWIN = 1
          VRTS = 0.74
          VRT  = VERT
          YVRT = VRTS * VERT
          XSH  = HORS - YVRT
          XSH0 = XSH  - (1.0 - VRTS) * VERT / 2.0
          YSH0 =      - (1.0 - VRTS) * VERT / 2.0
        END IF
      END IF
C * CHECK FOR SHELXL/XL EXECUTABLE - IF NOT: QUIT
      IGBL(110) = IABS (IGBL(110))
      IF (IGBL(110) == 0) THEN
        WRITE (LIN, 99996)
        CALL PRINTX (LU6, LIN(1:80), 2, 2)
        ISW = -1
        RETURN
      END IF
C * CHECK FOR PLATON EXECUTABLE - IF NOT: QUIT
      IF (IGBL(80) == 0) THEN
        WRITE (LIN, 99995)
        CALL PRINTX (LU6, LIN(1:80), 2, 2)
        ISW = -1
        RETURN
      END IF
C * CHECK WHETHER THE INVOKED & 'PATH'-PLATON VERSIONS ARE IDENTICAL
C * IF NOT: QUIT.
      JVERS = 0
      KERR  = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -z > version.log', 0, .true.,
     1  KERR)
      IF (KERR == 0) THEN
        OPEN (LU61, FILE = 'version.log', STATUS = 'OLD', IOSTAT = IOST)
        IF (IOST == 0) THEN
          DO
            READ (LU61, 99994, IOSTAT = IOST) LINE
            IF (LINE(1:6) == 'PLATON') THEN
              READ (LINE, 99993) JVERS
              EXIT
            END IF
          END DO
          CLOSE (UNIT = LU61, STATUS = 'DELETE')
          IF (IGBL(4) /= JVERS) THEN
            WRITE (LIN, 99992)  JVERS, IGBL(4)
            CALL PRINTX (LU6, LIN(1:80), 2, 2)
            ISW = -1
            RETURN
          END IF
        ELSE
          WRITE (LIN, 99999)
          CALL PRINTX (LU6, LIN(1:80), 2, 2)
          ISW = -1
          RETURN
        END IF
      ELSE
        WRITE (LIN, 99988)
        CALL PRINTX (LU6, LIN(1:80), 2, 2)
        ISW = -1
        RETURN
      END IF
C * CHECK FOR SHELXS/SHELXL,PLATON etc PATH'S
C * CHECK FOR SHELXS97/XS
      IGBL(111) = FINDEXE ('SHSEXE', SHSPATH, 'shelxs')
      IF (IGBL(111) == 0)
     1    IGBL(111) = FINDEXE ('SHSEXE', SHSPATH, 'xs')
C * CHECK FOR SHELXD97/XD
      IGBL(112) = FINDEXE ('SHDEXE', SHDPATH, 'shelxd')
      IF (IGBL(112) == 0)
     1    IGBL(112) = FINDEXE ('SHDEXE', SHDPATH, 'xm')
C * CHECK FOR SIR97
      IGBL(113) = FINDEXE ('SIREXE', SIR97PATH, 'sir97')
C * CHECK FOR SIR2004
      IGBL(114) = FINDEXE ('SIR04EXE', SIR04PATH, 'sir2004')
C * CHECK FOR SIR2011
      IGBL(120) = FINDEXE ('SIR11EXE', SIR11PATH, 'sir2011')
C * CHECK FOR DIRDIF
      IGBL(115) = FINDEXE ('DIREXE', DIRPATH, 'dirdif')
C * CHECK FOR QUEST
      IGBL(118) = FINDEXE ('QUESTEXE', LINE, 'cqbatch')
C * GENERAL INIT / RESTART IN CONTEXT
      IB        = 1
      IGBL(6)   = 17
      IGBL(38)  = 1
      IGBL(40)  = 1
      IGBL(41)  = 1
      IGBL(117) = 1
C * SIR-WINDOW
      IGBL(122) = 1
      CPR(105)  = 'START'
      CPR(106)  = CPR(200)
      CALL GEN038 (DATAORG, 1, 80)
      CALL GEN038 (LIJN1, 1, 16)
      CALL GEN038 (LIJN2, 1, 16)
      CALL GEN038 (LIJN3, 1, 16)
      CALL GEN038 (LIJN4, 1, 21)
      CALL GEN038 (LIJN5, 1, 16)
      CALL GEN038 (VALIDATION, 1, 45)
C * WHICH EDITOR (LOOK FOR ENVIRONMENT VARIABLE)
      N = FINDEXE ('EDITOR', EDITOR, 'nedit')
      IF (N == 0) N = FINDEXE ('EDITOR', EDITOR, 'vi')
C * GET LASER PRINTER COMMAND FROM ENVIRONMENT VARIABLE
      CALL GET_ENVIRONMENT_VARIABLE ('PSLASER', VALUE = PSLASER)
      IF (PSLASER(1:1) == CHAR (32)) PSLASER = 'laser2x '
C * GET PSVIEWER COMMAND FROM ENVIRONMENT VARIABLE
      N = FINDEXE ('PSVIEWER', PSVIEWER, 'ghostview')
      IF (N == 0) THEN
        N = FINDEXE ('PSVIEWER', PSVIEWER, 'gv')
        IF (N /= 0) PSVIEWER(N+1:) = ' --orientation=seascape'
      ELSE
        PSVIEWER(N+1:) = ' -seascape'
      END IF
C * GET CURRENT WORKING DIRECTORY AND WIDTH = IW
      CALL GET_ENVIRONMENT_VARIABLE ('PWD', VALUE = WORKDIR)
      IW = 254
      CALL GEN039 (1, WORKDIR, 1, 254, IB, IW)
      IF (IW <= 1) THEN
        WRITE (LIN, 99991)
        CALL PRINTX (LU6, LIN(1:80), 2, 2)
        ISW = -1
        RETURN
      END IF
C * GET USERPATH AND WIDTH = IU
      CALL GET_ENVIRONMENT_VARIABLE ('HOME', VALUE = USRPATH)
      IU = 254
      CALL GEN039 (1, USRPATH, 1, 254, IB, IU)
C * CHECK FOR/CREATE DIR s UNDER USER-ROOT OR WORKDIR (IF NOT)
      FNM = USRPATH(1:IU)//'/s/'
      IF (.NOT.  DINQ (FNM(1:IU + 2))) THEN
        USRPATH = WORKDIR
        IU      = IW
        FNM     = USRPATH(1:IU)//'/s/'
        IF (.NOT. DINQ (FNM(1:IU + 2)) ) THEN
          KERR = 0
          CALL SPAWN ('mkdir '//FNM(1:IU + 2), 0, .true., KERR)
        END IF
      END IF
C * GET COMMAND LINE ARGUMENT COMPOUND NAME (IF ANY)
      JARGB = 0
      JARG  = COMMAND_ARGUMENT_COUNT()
      IF (JARG > 0) THEN
        CALL GET_COMMAND_ARGUMENT (1, COMPD)
C * CHECK FOR (SILENT/NQA = -F) s-MODE
        IF (COMPD(1:2) == '-s' .OR. COMPD(1:2) == '-F') THEN
          JARGB = 1
          CALL GEN038 (COMPD, 1, 10)
        END IF
        IF ((JARG - JARGB) > 0) THEN
          CALL GEN038 (COMPD, 1, 10)
          CALL GET_COMMAND_ARGUMENT (1 + JARGB, LINE)
C * SEARCH FOR FILENAME EXTENSION(S) '.ins', '.res', '.fcf' or 'cif'
          IC = 40
C * GET COMPOUND-NAME LENGTH
          CALL GEN039 (1, LINE, 1, 40, IB, IC)
          ID = INDEX (LINE(1:IC), '.') - 1
C * CHECK FOR COMPOUND NAME WITH A MAXIMUM OF 10 CHARACTERS
          IF (ID < 11) THEN
            COMPD(1:ID) = LINE(1:ID)
            CALL GEN020 (-1, COMPD, 1, ID)
C * CHECK FOR LOWER CASE COMPOUND NAME (REQUIRED)
            IF (COMPD(1:ID) /= LINE(1:ID)) THEN
               WRITE (LIN, 99989) LINE(1:ID)
               CALL PRINTX (LU6, LIN(1:80), 2, 2)
               ISW = -1
               RETURN
             END IF
          ELSE
            WRITE (LIN, 99990) LINE(1:IC)
            CALL PRINTX (LU6, LIN(1:80), 2, 2)
            ISW = -1
            RETURN
          END IF
C * TEST FOR CIF INPUT / CREATE .ins & .hkl
          ID3 = INDEX (LINE(1:IC), '.cif')
          IF (ID3 > 0) THEN
            CALL SPAWN (PLAPATH(1:IGBL(80))//' -H '//LINE(1:IC)//
     1     ' > platon.log', 0, .true., KERR)
            IC = IC + 3
            LINE(ID3:IC) = '_sx.ins'
            ISPR(1) = 4
C * INS
            ISPR(340) = 1
          ENDIF
          ID1 = INDEX (LINE(1:IC), '.ins')
          IF (ID1 == 0) ID1 = - INDEX (LINE(1:IC), '.res')
          ID2 = INDEX (LINE(1:IC), '.fcf')
          ID0 = MAX (IABS (ID1), ID2)
          IF (ID0 > ID) THEN
C * TEST FOR FCF OR INS
            IF (ID2 /= 0) THEN
C * FCF
              ISPR(340) = 2
            ELSE
C * INS
              ISPR(340) = ISIGN (1, ID1)
            END IF
          ELSE
            WRITE (LIN, 99990) LINE(1:IC)
            CALL PRINTX (LU6, LIN(1:80), 2, 2)
            ISW = -1
            RETURN
          END IF
        END IF
      END IF
      COMPDFL = LINE(1:IC)
C * CHECK FOR NQA/GUIDED MODE
      IF (IGBL(50) /= 2) THEN
        IF ((JARG - JARGB) > 1) THEN
          IGBL(50) = 1
          CALL GET_COMMAND_ARGUMENT (JARGB + 2, LINE)
          CALL GEN020 (1, LINE, 1, 6)
          IF (LINE(1:4) == 'AUTO' .OR. LINE(1:3) == 'NQA')
     1      JARG = JARG - 1
          IF (LINE(1:6) == 'REMOVE') IGBL(50) = -1
        ELSE
          IGBL(50) = 0
        END IF
      END IF
C * SKIP COMPID INPUT DIALOG SECTION WHEN COMPID GIVEN ON CALLING LINE
      IF ((JARG - JARGB) > 0) THEN
        KL     = 0
        KN     = 0
        CPR(1) = 'COMPID'
        CPR(2) = COMPD
C * FILE INIT
        CALL S020
      END IF
      RETURN
99999 FORMAT ('>>> Cannot OPEN file version.log !!')
99998 FORMAT ('>>> System-S will not run for USER=root !!')
99997 FORMAT ('>>> System-S runs in X-Windows mode only !!')
99996 FORMAT ('>>> No PATH to a SHELXL executable found !!')
99995 FORMAT ('>>> No PATH to a PLATON executable found !!')
99994 FORMAT (A)
99993 FORMAT (15X, I10)
99992 FORMAT ('>>> Spawned PLATON', I7, ' version differs from that',
     1           ' of Spawner', I7, ': QUIT')
99991 FORMAT ('>>> No Usable environment variable value for PWD !!')
99990 FORMAT ('UNSUITABLE FILENAME or NAME > 10 CHAR: ', A)
99989 FORMAT ( '>>> Compound Filename EXPECTED in  Lower Case !!', A)
99988 FORMAT ('>>> Cannot SPAWN PLATON -z option !!')
      END SUBROUTINE S010
 
      SUBROUTINE S020
C * FILES & INIT ROUTINE
      USE files
      USE parameters
      USE mentry
      USE ccom
      USE scom
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: JJ
      INTEGER :: KK
      INTEGER :: IP
      INTEGER :: IS
      INTEGER :: IB
      INTEGER :: IC1
      INTEGER :: IER
      INTEGER :: NUM
      INTEGER :: NREF
      INTEGER :: ITYPE
      INTEGER :: IFOBS
      INTEGER :: MODUS
      INTEGER :: NERROR
      INTEGER :: IBATNR
      INTEGER :: IRTYPE
      INTEGER :: ISFOBS
      INTEGER :: CHDIR
      REAL :: D
      REAL :: DI1
      REAL :: DI2
      REAL :: DI3
      REAL :: DO1
      REAL :: DO2
      REAL :: DO3
      REAL :: OBS
      REAL :: SCF
      REAL :: FMAX
      REAL :: FOBS
      REAL :: SOBS
      REAL :: SMAX
      REAL :: XWIN
      REAL :: SFOBS
      CHARACTER(len=6) :: VERSION, NQ
      CHARACTER(len=2) :: DUM
      LOGICAL :: DINQ
      LOGICAL :: SEXST
      LOGICAL :: SSEXST
      WRITE (VERSION, 99978, IOSTAT = IOST) IGBL(4)
      EXST  = .FALSE.
      SEXST = .FALSE.
      IERR  = 0
      MODUS = -1
      TITL(1:10) = COMPD
      CALL GEN038 (TITL, 11, 36)
C * SAVE COMPD in FILE .compid IN USRPATH/s as future default
      OPEN (UNIT = LU61, FILE = FNM(1:IU+3)//'.compid',
     1      STATUS = 'UNKNOWN')
      WRITE (LU61, 99979, IOSTAT = IOST) COMPD
      CLOSE (UNIT = LU61)
C * COMPOUND-NAME LENGTH
      IB = 1
      IC = 10
      CALL GEN039 (1, COMPD, 1, 10, IB, IC)
      INZ = 4 + IU + IC
      CALL GEN039 (1, COMPDFL, 1, 13, IB, IC1)
C * CREATE FULL DIRECTORY PATH TO COMPOUND DIRECTORY
      FNM(IU + 3 : INZ) = '/'//COMPD(1:IC)//'/'
C * REMOVE DIRECTORY FOR IGBL(50) = -1
      IF (IGBL(50) == -1 .OR. IGBL(50) == 2) THEN
        IF (DINQ (FNM(1:IU+3)//COMPD(1:IC))) THEN
          KERR = 0
          CALL SPAWN ('rm -r '//FNM(1:IU+3)//COMPD(1:IC), 0, .true.,
     1      KERR)
          WRITE (LU6, 99977, IOSTAT = IOST) FNM(1:IU+3)//COMPD(1:IC)
        END IF
C * CALL EXIT/STOP
        IF (CHDIR (WORKDIR) /= 0) CALL GEN127 (' ')
C * CALL EXIT/STOP
        IF (IGBL(50) == -1) CALL GEN127 (' ')
      END IF
C * CHECK WHETHER SUBDIRECTORY ALREADY EXISTS
      SSEXST = DINQ (FNM(1:INZ - 1))
C * RESTART IN CONTEXT
      IF (SSEXST) THEN
        IF (CHDIR(FNM(1:INZ - 1)) /= 0) CALL S925(1)
C * DIRECTORY S/COMPD PRESENT
        CPR(104) = '00/000/000'
        CALL S915
     1  ('General Restart in Context (s-version='//VERSION//')')
      ELSE
C * STARTUP WITH EITHER .RES, .INS, .FCF, OR .CIF DETERMINED FROM EXTENSION ID
        IF (ID /= 0) THEN
C * CHECK ISPR(340) WHETHER .res(=-1), .ins(=1), or .fcf(=2)  EXISTS
          DO I = -1, 3
            IF (I < 3) THEN
              IF (I /= 0) THEN
                IF (ISPR(340) == I) THEN
                  INQUIRE (FILE = COMPDFL(1:IC1), EXIST = SEXST)
                  IF (SEXST) THEN
C * HANDLE THE CASE OF SUPPLIED CIF OR FCF
                    IF (I == 2) THEN
                      OPEN (LU61, FILE = COMPD(1:IC1),
     1                  STATUS = 'UNKNOWN')
C * CREATE INS,(HKL) FOR CIF & FCF
                      IF (.NOT. SSEXST) THEN
                        OPEN (LU62, FILE = COMPD(1:IC)//'.ins',
     1                    STATUS = 'UNKNOWN')
C * WRITE TITL
                        WRITE (LU62, 99986, IOSTAT = IOST) COMPD(1:IC)
                        IGBL(5)  = LU61
                        CALL GEN108 (LU61, 0)
                        IGBL(8)  = 3
                        IPR(499) = 0
                        IPR(39)  = 0
                        ITYPE    = 0
                        DO
                          CALL PLA006 (0, IS)
                          IF (IS == -1) EXIT
C * WRITE CELL & ZERR
                          IF (IS == 30) THEN
                            WRITE (LU62, 99985, IOSTAT = IOST)
     1                        (FN(K), K = 1, 12)
C * WRITE RADN
                          ELSE IF (IS == 71) THEN
                            WRITE (LU62, 99984, IOSTAT = IOST) FN(1)
C * WRITE FACE
                          ELSE IF (IS == 85) THEN
                            WRITE (LU62, 99983, IOSTAT = IOST)
     1                      NINT (FN(1)), NINT (FN(2)), NINT (FN(3)),
     2                      FN(4)
C * WRITE TEMP
                          ELSE IF (IS == 132) THEN
                            WRITE (LU62, 99982, IOSTAT = IOST)
     1                        FN(1) - 273
C * FSUM
                          ELSE IF (IS == 163) THEN
                            N = INDEX (ICL, '''')
                            IF (N > 2) THEN
                              CALL GEN072 (ICL, JFL, FN, KL, KN, 0, LU6,
     1                          1, 1, N - 1, 10, NP17)
                              DO JJ = 1, KL
C * MANIPULATE THE CHEMICAL FORMULA
                                CALL GEN111 (JFL(JJ), DUM(1:2), 7, M)
                                IF (M == 0) THEN
                                  IF (DUM(2:2) == ' ') THEN
                                    JFL(JJ) = DUM(1:1)//'1'
                                  ELSE
                                    JFL(JJ) = DUM(1:2)//'1'
                                  END IF
                                END IF
                              END DO
C * WRITE FSUM
                              WRITE (LU62, 99981, IOSTAT = IOST)
     1                          (JFL(KK)(1:5), KK = 1, KL)
                            END IF
                          ELSE IF (IS == -2) THEN
C * CHECK FOR FCF
                            IF (ISPR(340) == 2) EXIT
                            WRITE (LU62, 99991, IOSTAT = IOST)
                            ITYPE = 0
                            DO
                              READ (LU61, 99979, IOSTAT = IOST)
     1                          ICL(1:80)
                              IF (IOST /= 0) THEN
                                WRITE (LU62, '(/)', IOSTAT = IOST)
C * CIF
                                ISPR(340) = 3
                                GO TO 10
                              END IF
                              IF (INDEX (ICL(1:80),
     1                          '_refln_F_squared_sigma')
     2                          /= 0) THEN
                                ITYPE = 1
                                CLOSE (UNIT = LU62)
                              ELSE IF (INDEX (ICL(1:80),
     1                          '_diffracted_cos_cstar') /= 0) THEN
                                ITYPE = 2
                                CLOSE (UNIT = LU62)
                              ELSE IF (ICL(1:1) == ' ' .AND.
     1                          ICL(21:21) == '.') THEN
                                BACKSPACE LU61
                                EXIT
                              END IF
                            END DO
                            OPEN (LU62, FILE = COMPD(1:IC)//'.xxx',
     1                        STATUS = 'UNKNOWN')
                            DO
                              READ (LU61, '(I4, 2I5, 2F9.0, I5)',
     1                          IOSTAT = IOST)
     1                          IH, IK, IL, OBS, SOBS, IBATNR
                              IF (IOST /= 0) THEN
                                WRITE (LU62, '(/)', IOSTAT = IOST)
C * CIF
                                ISPR(340) = 3
                                GO TO 10
                              END IF
                              IF (ITYPE == 2) THEN
                                READ (LU61, 99968, IOSTAT = IOST)
     1                             DI1, DO1, DI2, DO2, DI3, DO3
                                IF (IOST /= 0) THEN
                                  WRITE (LU62, '(/)', IOSTAT = IOST)
C * CIF
                                  ISPR(340) = 3
                                  GO TO 10
                                END IF
                                WRITE (LU62, 99970, IOSTAT = IOST)
     1                            IH, IK, IL, NINT (OBS * 100.0),
     2                            NINT (SOBS * 100.0), IBATNR, DI1,
     3                            DO1, DI2, DO2, DI3, DO3
                              ELSE
                                WRITE (LU62, 99969, IOSTAT = IOST)
     1                            IH, IK, IL, NINT (OBS * 100.0),
     2                            NINT (SOBS * 100.0), 1
                              END IF
                            END DO
                            WRITE (LU62, '(/)', IOSTAT = IOST)
C * CIF
                            ISPR(340) = 3
                            GO TO 10
                          END IF
                        END DO
                        IF (PAR(304) > 0.0)
     1                    WRITE (LU62, 99992, IOSTAT = IOST)
     2                      (PAR(K), K = 302, 304)
                        WRITE (LU62, 99991, IOSTAT = IOST)
                        CLOSE (UNIT = LU62)
                        CLOSE (UNIT = LU61)
C * FCF
                        IF (ISPR(340) == 2) THEN
                          OPEN (LU61, FILE = COMPD(1:IC)//'.fcf',
     1                    STATUS = 'UNKNOWN')
                        END IF
C * CIF
                        IF (ISPR(340) == 3) THEN
                            INQUIRE (FILE = COMPD(1:IC)//'.fcf',
     1                        EXIST = SEXST)
                          IF (SEXST) THEN
                            OPEN (LU61, FILE = COMPD(1:IC)//'.fcf',
     1                        STATUS = 'UNKNOWN')
                          ELSE
                            INQUIRE (FILE = COMPD(1:IC)//'.hkl',
     1                        EXIST = SEXST)
                            IF (SEXST) THEN
                              OPEN (LU61, FILE = COMPD(1:IC)//'.hkl',
     1                          STATUS = 'UNKNOWN')
                            ELSE
C * CALL EXIT/STOP
                              CALL GEN127 ('No HKL-Data Found')
                            END IF
                          END IF
                        END IF
                        OPEN (LU62, FILE = COMPD(1:IC)//'.xxx',
     1                    STATUS = 'UNKNOWN')
C * DETERMINE FCF-TYPE
                        IGBL(54) = 1
                        CALL PLA010 (LU61, IRTYPE, IER)
                        IGBL(9)             = IRTYPE
                        IENTRY(IGBL(54), 3) = IRTYPE
                        IENTRY(IGBL(54), 4) = 5
                        CALL PLA139 (LU6, LU61, LU62, IPR(384))
   10                   CLOSE (UNIT = LU62)
                        CLOSE (UNIT = LU61)
                      END IF
                    END IF
                    EXIT
                  ELSE
                    WRITE (LU6, 99997, IOSTAT = IOST)
     1                COMPD(1:IC)//FTYPE(I)
C * ERROR HANDLING
                    CALL S925 (3)
C * CALL EXIT/STOP
                    CALL GEN127 (' ')
                  END IF
                END IF
              END IF
            ELSE
C * ERROR HANDLING
              CALL S925 (3)
C * CALL EXIT/STOP
              CALL GEN127 (' ')
            END IF
          END DO
C * CREATE DIR COMPD UNDER s
          KERR = 0
          CALL SPAWN ('mkdir '//FNM(1:INZ - 1), 0, .true., KERR)
C * COPY .ins/res AND .hkl ONLY WHEN DIRECTORY COMPD IS NEW
          IF (ISPR(340) == -1) THEN
            KERR = 0
            CALL SPAWN
     1        ('cp '//COMPDFL(1:IC1)//' '//FNM(1:INZ)//'shelx.ins',
     2        0, .true., KERR)
          ELSE
            KERR = 0
            CALL SPAWN
     1        ('cp '//COMPDFL(1:IC1)//' '//FNM(1:INZ)//'shelx.ins',
     2          0, .true., KERR)
          END IF
C * TEST FOR RES/INS
          IF (IABS(ISPR(340)) == 1) THEN
            INQUIRE (FILE = COMPDFL(1:IC1-3)//'hkl', EXIST = SEXST)
            IF (SEXST) THEN
              KERR = 0
              CALL SPAWN
     1        ('cp '//COMPDFL(1:IC1-3)//'hkl '//FNM(1:INZ)//'shelx.hkl',
     2          0, .true., KERR)
              DATAORG =
     1     'Shelx-data from '//WORKDIR(1:IW)//'/'//COMPD(1:IC)//'.hkl'
            ELSE
              WRITE (LU6, '(''No HKL data found'')', IOSTAT = IOST)
            END IF
C * TEST FOR FCF
          ELSE IF (ISPR(340) == 2) THEN
            KERR = 0
            CALL SPAWN
     1        ('cp '//COMPD(1:IC)//'.fcf '//FNM(1:INZ)//'shelx.fcf',
     2          0, .true., KERR)
            KERR = 0
            CALL SPAWN
     1        ('mv '//COMPD(1:IC)//'.xxx '//FNM(1:INZ)//'shelx.hkl',
     2          0, .true., KERR)
            DATAORG =
     1    'Shelx-data from '//WORKDIR(1:IW)//'/'//COMPD(1:IC)//'.fcf'
C * CHECK FOR CIF
          ELSE IF (ISPR(340) == 3) THEN
            KERR = 0
            CALL SPAWN
     1        ('cp '//COMPD(1:IC)//'.cif '//FNM(1:INZ)//'shelx.cif',
     2          0, .true., KERR)
            KERR = 0
            CALL SPAWN
     1        ('mv '//COMPD(1:IC)//'.xxx '//FNM(1:INZ)//'shelx.hkl',
     2          0, .true., KERR)
            DATAORG =
     1    'Shelx-data from '//WORKDIR(1:IW)//'/'//COMPD(1:IC)//'.cif'
          END IF
C * CHANGE TO COMPOUND DIRECTORY
C * ERROR HANDLING
          IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * LOG INIT
          CPR(104) = '00/000/000'
          CALL S915 (
     1    COMPD(1:IC)//' Create & Init (s-version='//VERSION//')')
          CALL S915 (DATAORG(1:21+IW+IC))
        END IF
      END IF
C * CHECK FOR .s.dbf PRESENT  (= STATUS/CONTEXT)
      INQUIRE (FILE = '.s.dbf', EXIST = EXST)
      IF (.NOT. EXST) THEN
C * CHECK FOR CIF
        IF (ISPR(340) == 3) THEN
          DATAORG = 'Reflection data from '//COMPD(1:IC)//'.cif'
C * TEST FOR FCF
        ELSE IF (ISPR(340) == 2) THEN
          DATAORG = 'Reflection data from '//COMPD(1:IC)//'.fcf'
C * TEST FOR INS
        ELSE IF (ISPR(340) == 1) THEN
          DATAORG = 'Reflection data from '//COMPD(1:IC)//'.hkl'
        END IF
C * CHECK FOR SHELX.HKL (TYPE HKLF 4) TYPE DATA
        ISPR(37) = 0
        INQUIRE (FILE = 'shelx.hkl', EXIST = EXST)
        IF (EXST) THEN
          IF (DATAORG(1:1) == ' ') THEN
            DATAORG = 'Reflection Data from shelx.hkl'
            CALL S915 (DATAORG(1:30))
          END IF
        ELSE
C * CHECK FOR REFL.CIF
          INQUIRE (FILE = 'shelx.fcf', EXIST = EXST)
          IF (EXST) THEN
            ISPR(1) = 4
            DATAORG = 'Reflection Data from shelx.fcf'
            CALL S915 (DATAORG(1:30))
            OPEN (LU61, FILE = 'shelx.fcf', STATUS = 'UNKNOWN')
            OPEN (LU62, FILE = 'shelx.hkl', STATUS = 'UNKNOWN')
C * GENERATE HKL FROM FCF (SHELXL-STYLE ONLY)
            CALL PLA139 (LU6, LU61, LU62, IPR(384))
            CLOSE (UNIT = LU61)
            CLOSE (UNIT = LU62)
            KERR = 0
          ELSE
            INQUIRE (FILE = 'shelx.cif', EXIST = EXST)
            IF (EXST) THEN
              ISPR(1) = 4
              DATAORG = 'Reflection Data from shelx.cif'
              CALL S915 (DATAORG(1:30))
              OPEN (LU61, FILE = 'shelx.cif', STATUS = 'UNKNOWN')
              OPEN (LU62, FILE = 'shelx.hkl', STATUS = 'UNKNOWN')
              ITYPE = 0
              DO
                READ (LU61, 99979, IOSTAT = IOST) LINE
                IF (IOST == -1) GO TO 20
                IF (INDEX (LINE, '_refln_F_squared_sigma') /= 0)
     1            THEN
                  ITYPE = 1
                ELSE IF (INDEX (LINE, '_diffracted_cos_cstar')
     1          /= 0) THEN
                  ITYPE = 2
                ELSE IF (LINE(1:1) == ' ' .AND.
     1            LINE(21:21) == '.') THEN
                  BACKSPACE LU61
                  EXIT
                END IF
              END DO
              DO
                READ (LU61, 99967, IOSTAT = IOST)
     1          IH, IK, IL, OBS, SOBS, IBATNR
                IF (IOST /= 0) EXIT
                IF (ITYPE == 2) THEN
                  READ (LU61, 99966, IOSTAT = IOST)
     1              DI1, DO1, DI2, DO2, DI3, DO3
                  IF (IOST /= 0) EXIT
                  WRITE (LU62, 99965, IOSTAT = IOST) IH, IK, IL,
     1              NINT (OBS * 100.0), NINT (SOBS * 100.0), IBATNR,
     2              DI1, DO1, DI2, DO2, DI3, DO3
                ELSE
                  WRITE (LU62, 99964, IOSTAT = IOST)
     1            IH, IK, IL, NINT (OBS * 100.0),
     2            NINT (SOBS * 100.0), 1
                END IF
              END DO
   20         WRITE (LU62, '(/)', IOSTAT = IOST)
              CLOSE (UNIT = LU61)
              CLOSE (UNIT = LU62)
            ELSE
C * ERROR HANDLING
              CALL S925 (3)
C * CALL EXIT/STOP
              CALL GEN127 (' ')
            END IF
          END IF
        END IF
      ELSE
        MODUS = 1
C * RECOVER DATA FROM S.DBF
        CALL S920 (-1)
C * CHECK/UPDATE REFINEMENT DATA
        CALL S927 (0)
C * RECOVER SPACEGROUP SYMMETRY
        IF (CPR(100) /= '          ') THEN
          LINE(1:20)  = 'SPGR '//CPR(100)//'     '
          LINE(21:50) = '                              '
          LINE(51:80) = LINE(21:50)
          CALL SGSM (0,  LINE, SGX, 0, 0, IERR)
          CALL SGSM (18, LINE, SGX, 0, 0, IERR)
          ISPR(102) = NINT (SGX(9))
        END IF
      END IF
C * DATA INIT
      IF (MODUS == -1) THEN
C * GENERAL INIT
        CALL S915 ('Files & Init')
C * CREATE DEFAULT FILES IN COMPOUND DIRECTORY
 
C * CREATE PRIMARY DATA SOURCE DIRECTORY FOR .hkl
        KERR = 0
        CALL SPAWN ('mkdir hklf', 0, .true., KERR)
        KERR = 0
        CALL SPAWN ('ln -s /dev/null hklf/shelx.hkl', 0, .true., KERR)
C * CREATE DEFAULT SUBDIRECTORIES
        CALL S932 (1)
C * INIT
        CALL GEN021 (TM, 1.0)
        DO I = 2, NPS2
          ISPR(I) = 0
        END DO
        CALL GEN074 (SPAR, 1, NPS1, 0.0)
        DO I = 1, NPS3
          CALL GEN038 (CPR(I), 1, 10)
        END DO
C * SET CELL DEFAULTS
        CALL GEN074 (SPAR, 104, 106,  90.0)
        CALL GEN074 (SPAR, 108, 110, 0.001)
        CALL GEN074 (SPAR, 111, 113,  0.01)
        ISPR(119) = 1
C * STARTING POINT PARAMETER SAVE DIRECTORIES
        CPR(104) = '00/000/000'
C * POP CRIT
        SPAR(1)   = 0.33
C * R-CRITERIUM FOR CHANGE OF PHASING METHOD
        SPAR(2)   = 0.25
C * SET SIN(TH)/LAMBDA-MIN FOR EXOR-L.S.
        SPAR(56)  = 0.2
C * SET SIN(TH)/LAMBDA-MAX FOR EXOR
        SPAR(57)  = 0.6
C * OMIT CRITERIUM (ON I)
        SPAR(200) = 0.0
C * FLACK
        SPAR(225) = -1000.0
C * EXTI
        SPAR(227) = -1000.0
        SPAR(228) =     0.0
C * MOVE DEFAULT SPAR(160-163)
        SPAR(163) = 1.0
C * REFINEMENT STATUS OF COORDINATE SET
        ISPR(6)  = -1
C * SET STATUS = CREATE
        ISPR(11) =  1
C * DEFAULT SHELXD NTRY
        ISPR(28)  = 50
C * HANDLE SHELX HKLF 4/3 STYLE INPUT
        IF (ISPR(1) == 0 .OR. ISPR(1) == 4) THEN
C * LOOK FOR SHELX.INS
          INQUIRE (FILE = 'shelx.ins', EXIST = EXST)
          IF (EXST) THEN
            OPEN (LU61, FILE = 'shelx.ins', STATUS = 'OLD')
            DO
              CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80,
     1                   10, NP17)
              SELECT CASE (JFL(1)(1:4))
C * GET (LAMBDA) A, B, C, ALPHA, BETA, GAMMA
                CASE ('CELL')
                  IF (KN >= 6) THEN
                    IF (KN == 7) THEN
                      SPAR(80) = FN(1)
                      IB = 2
                    ELSE
                      IB = 1
                    END IF
                    DO I = IB, KN
                      SPAR(I + 101 - IB) = FN(I)
                    END DO
                    ISPR(38) = 4
                  ELSE
                    WRITE (LU6, 99972, IOSTAT = IOST)
                    EXIT
                  END IF
C * ZERR
                CASE ('ZERR')
                  IF (KN == 7) THEN
                    ISPR(119) = NINT (FN(1))
                    DO I = 2, 7
                      SPAR(106 + I) = FN(I)
                    END DO
                  ELSE IF (KN == 6) THEN
                    DO I = 1, 6
                      SPAR(107 + I) = FN(I)
                    END DO
                  ELSE
                    WRITE (LU6, 99971, IOSTAT = IOST)
                    CYCLE
                  END IF
C * SFAC
                CASE ('SFAC')
                  IB = 1
                  DO I = 2, KL
                    SFC(I - 1) = JFL(I)(1:2)
                    LINE(IB:) = SFC(I - 1)
                    IB        = IB + 1
                    IF (SFC(I - 1)(2:2) /= ' ') IB = IB + 1
                    CALL GEN040 (1, NQ, IP)
                    LINE(IB:) = NQ
                    IB        = IB + IP
                  END DO
                  IF (IGBL(50) /= 0) THEN
                    OPEN (LU62, FILE = '.formula', STATUS = 'UNKNOWN')
                    WRITE (LU62, 99979, IOSTAT = IOST) LINE
                    CLOSE (UNIT = LU62)
                  END IF
C * RADN
                CASE ('RADN')
                  SPAR(80) = FN(1)
C * FORMULA
                CASE ('FSUM')
                  OPEN (LU62, FILE = '.formula', STATUS = 'UNKNOWN')
                  WRITE (LU62, 99979, IOSTAT = IOST) LINE(6:80)
C * UNIT
                CASE ('UNIT')
                  IB = 1
                  DO I = 1, KN
                    LINE(IB:) = SFC(I)
                    IB        = IB + 1
                    IF (SFC(I)(2:2) /= ' ') IB = IB + 1
                    NUM = NINT (FN(I) / ISPR(119))
                    CALL GEN040 (NUM, NQ, IP)
                    LINE(IB:) = NQ
                    IB        = IB + IP
                  END DO
                  OPEN (LU62, FILE = '.formula', STATUS = 'UNKNOWN')
                  WRITE (LU62, 99979, IOSTAT = IOST) LINE
C * CHIRAL
                CASE ('CHIR')
                  ISPR(8) = 1
C * TEMP ([C]/K))
                CASE ('TEMP')
                  IF (JFL(2)(1:1) == 'K') THEN
                    SPAR(10) = FN(1)
                  ELSE
                    SPAR(10) = FN(1) + 273
                  END IF
C * SIZE
                CASE ('SIZE')
                  IF (KN == 3) THEN
                    CALL GEN034 (FN, 1, 3)
                    SPAR(11) = FN(1)
                    SPAR(12) = FN(2)
                    SPAR(13) = FN(3)
                  END IF
C * SET
                CASE ('SET ')
C * SET REVERSE
                  IF (JFL(2)(1:3) == 'REV') THEN
                    IGBL(68) = MOD (IGBL(68) + 1, 2)
                    CALL GGIP (-999.0, FLOAT (IGBL(68)), IGBL(62) * 0.25
     1                         , 9)
C * SET IPR/PAR/IGBL/RGBL
                  ELSE IF (KL == 2 .AND. KN == 2) THEN
                    CALL PLA206 (1, JFL(2)(1:3))
                  END IF
C * FACE
                CASE ('FACE')
                  IH = NINT (FN(1))
                  IK = NINT (FN(2))
                  IL = NINT (FN(3))
                  D  = FN(4)
                  CALL S080 (4, IH, IK, IL, D)
C * MU
                CASE ('MU  ')
                  IF (KN == 1) THEN
                    D = FN(1)
                    CALL S080 (1, 0, 0, 0, D)
                  END IF
C * HKLF
                CASE ('HKLF')
                  IF (KN == 1 .OR. KN == 2) ISPR(1) = NINT (FN(1))
C * ORGANIC
                CASE ('ORGA')
                  IGBL(97) = 1
C * INORGANIC
                CASE ('INOR')
                  IGBL(97) = 0
C * SHELXS
                CASE ('SHEL')
                  IF (IGBL(111) /= 0) IGBL(73) = 2
C * SIR
                CASE ('SIR ', 'SIR9', 'SIR2')
                  IF (IGBL(113) /= 0) IGBL(73) = 3
C * END
                CASE ('END')
                  EXIT
C * EOF
                CASE ('EOF')
                  EXIT
              END SELECT
            END DO
            CLOSE (UNIT = LU61)
            CLOSE (UNIT = LU62)
            KERR = 0
            CALL SPAWN ('mv shelx.ins hklf',0, .true., KERR)
          ELSE
C * LOOK FOR SCALE.LOG (KAPPACCD/DENZO
            INQUIRE (FILE = 'scale.out', EXIST = EXST)
            IF (EXST) THEN
              OPEN (LU61, FILE = 'scale.out', STATUS = 'OLD')
              DO
                READ (LU61, '(A)', IOSTAT = IOST) LINE
                IF (IOST /= 0) EXIT
                IF (LINE(1:6) == ' CELL ') THEN
                  READ (LINE,'(5X, 6F9.0)') (SPAR(100 + I), I = 1, 6)
                ELSE IF (LINE(1:4) == ' A  ') THEN
                  READ (LINE, 99996) SPAR(108)
                ELSE IF (LINE(1:4) == ' B  ') THEN
                  READ (LINE, 99996) SPAR(109)
                ELSE IF (LINE(1:4) == ' C  ') THEN
                  READ (LINE, 99996) SPAR(110)
                ELSE IF (LINE(1:6) == ' ALPHA') THEN
                  READ (LINE, 99980) SPAR(111)
                ELSE IF (LINE(1:6) == ' BETA ') THEN
                  READ (LINE, 99980) SPAR(112)
                ELSE IF (LINE(1:6) == ' GAMMA') THEN
                  READ (LINE, 99980) SPAR(113)
                END IF
              END DO
              CLOSE (UNIT = LU61)
              ISPR(38) = 3
            END IF
          END IF
          IF (ISPR(1) == 0) THEN
            CALL GGIP (-999.0, 0.0, XWIN, 1)
            IF (XWIN /= 0.0) THEN
C * WHAT NEXT ?
C * DEFAULT: SHELX.HKL file found. FORMAT = HKLF 4 (y/n[y])
             CALL PLA012 (12, 1)
             LINE = IGGT
            ELSE
              CALL GEN125 (1, LU6,
     1         'SHELX.HKL file found. FORMAT = HKLF 4 (y/n[y])')
              READ  (LU5, 99979) LINE
            END IF
          ELSE IF (ISPR(1) == 3) THEN
            LINE(1:1) = 'N'
          ELSE
            LINE(1:1) = 'Y'
          END IF
          CALL GEN020 (1, LINE, 1, 1)
          IF (LINE(1:1) == 'n' .OR. LINE(1:1) == 'N') THEN
            WRITE (LU6, 99974, IOSTAT = IOST)
            KERR = 0
            CALL SPAWN ('mv shelx.hkl shelx.hkl3', 0, .true., KERR)
            OPEN (LU61, FILE = 'shelx.hkl3', STATUS = 'UNKNOWN')
            OPEN (LU62, FILE = 'shelx.hkl',  STATUS = 'UNKNOWN')
            NREF   = 0
            FMAX   = 0.0
            SMAX   = 0.0
            NERROR = -1
   30       NERROR = NERROR + 1
            IF (NERROR < 100) THEN
              DO
                READ (LU61, 99973, IOSTAT = IOST)
     1                IH, IK, IL, FOBS, SFOBS
                IF (IOST /= 0) THEN
                  IF (IOST == -1) THEN
                    GO TO 40
                  ELSE
                    GO TO 30
                  END IF
                END IF
                IF (IH == 0 .AND. IK == 0 .AND. IL == 0) EXIT
                IF (SFOBS > 0.0) THEN
                  NREF = NREF + 1
                  FMAX = MAX (FMAX, FOBS ** 2)
                  SMAX = MAX (SMAX, SFOBS * FOBS * 2.0)
                END IF
              END DO
            END IF
   40       CALL GEN108 (LU61, 0)
C * MAKE SURE THAT NEW DATA FIT WITHIN HKLF 4 FORMAT
            SCF =  MIN (9999999.0 / FMAX, 9999999.0 / SMAX)
            DO I = 1, NREF
              READ (LU61, 99987) IH, IK, IL, FOBS, SFOBS
              IF (SFOBS > 0.0) THEN
                IFOBS  = NINT (SCF * FOBS ** 2)
                ISFOBS = NINT (SCF * 2.0 * FOBS * SFOBS)
                IF (ISFOBS > 0) THEN
                  WRITE (LU62, 99989, IOSTAT = IOST)
     1              IH, IK, IL, IFOBS, ISFOBS, 1
                END IF
              END IF
            END DO
            WRITE (LU62, 99990, IOSTAT = IOST)
            CLOSE (UNIT = LU61)
            CLOSE (UNIT = LU62)
          END IF
          ISPR(1) = 4
          KERR = 0
          CALL SPAWN ('mv shelx.hkl hklf', 0, .true., KERR)
        ELSE
          WRITE (LU6, 99999, IOSTAT = IOST)
        END IF
C * SET CONTEXT LEVEL TO COMPOUND SUBDIRECTORY
        ISPR(10) = 1
C * SET WHAT NEXT
        CPR(105) = 'COMPID'
        CPR(106) = CPR(200)
      END IF
C * FIND OUT ABOUT DIRCOS AND PSI-SCAN DATA
      IF (ISPR(1) /= 1 .AND. ISPR(1) /= 2) CALL S904
      CALL S915 ('Start Input Cycle')
      RETURN
99999 FORMAT ('No .doc file found.', /)
99997 FORMAT (/, 'The file ', A, ' not found in current directory', /)
99996 FORMAT (18X, F9.0)
99992 FORMAT ('SIZE', 3F10.3)
99991 FORMAT ('HKLF 4')
99990 FORMAT (1X)
99989 FORMAT (3I4, 2I8, I4)
99987 FORMAT (3I4, 2F8.0)
99986 FORMAT ('TITL ', A)
99985 FORMAT ('CELL ', 6F10.5, /, 'ZERR 1', 6F10.5)
99984 FORMAT ('RADN', F10.5)
99983 FORMAT ('FACE', 3I5, F10.4)
99982 FORMAT ('TEMP', F10.1)
99981 FORMAT ('FSUM ', 15A)
99980 FORMAT (22X, F9.0)
99979 FORMAT (A)
99978 FORMAT (I6)
99977 FORMAT (/, 'Current Directory ', A, ' Removed')
99974 FORMAT (/, ':: HKLF 3 converted to HKLF 4 type SHELX.HKL file')
99973 FORMAT (3I4, 2F8.0)
99972 FORMAT ('CELL Record Error')
99971 FORMAT ('ZERR Record Error')
99970 FORMAT (3I4, 2I8, I4, 6F8.5)
99969 FORMAT (3I4, 2I8, I4)
99968 FORMAT (F8.5,5F9.5)
99967 FORMAT (I4, 2I5, 2F9.0, I5)
99966 FORMAT (F8.5,5F9.5)
99965 FORMAT (3I4, 2I8, I4, 6F8.5)
99964 FORMAT (3I4, 2I8, I4)
      END SUBROUTINE S020
 
      SUBROUTINE S030 (ISKIP)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: ISKIP
 
      CHARACTER(len=10) :: FROM
      FROM = CPR(105)
C * HANDLE SKIP INSTRUCTION
      IF (ISKIP == 1) THEN
        IF (CPR(1)(1:6) == 'ABSPSI') THEN
          CPR(1)(1:6) = 'TRMX  '
          GO TO 40
        ELSE IF (CPR(1)(1:6) == 'MULABS') THEN
          CPR(1)  = 'ADDSYM'
          CPR(2)  = ' '
          ISPR(5) = -1
          GO TO 40
        ELSE IF (CPR(1)(1:6) == 'ELTREF') THEN
          CPR(1)    = 'ADDSYM'
          CPR(2)    = ' '
          IGBL(117) = 0
        ELSE IF (CPR(1)(1:6) == 'ADDSYM') THEN
          CPR(1)  = 'SHELXL    '
          CPR(2)  = 'ANISO     '
          ISPR(7) = 1
          GO TO 40
        ELSE IF (CPR(1)(1:4) == 'TRMX') THEN
          IF (ISPR(6) > 0) THEN
            CPR(1)  = 'SHELXL    '
            CPR(2)  = 'ANISO     '
            ISPR(7) = 1
            GO TO 40
          END IF
        ELSE IF (CPR(1)(1:6) == 'RENAME') THEN
          IF (ISPR(112) > 0) THEN
            IF (SPAR(3) < 36) THEN
              CPR(1)  = 'HDIF'
            ELSE
              CPR(1)  = 'HFIX'
            END IF
          END IF
          GO TO 40
        ELSE IF (CPR(1)(1:5) == 'VALID') THEN
          ISPR(6) = 7
          CPR(1)  = ' '
        END IF
      END IF
C * SET WHAT TO DO NEXT
      CALL GEN038 (CPR(1), 1, 10)
      CALL GEN038 (CPR(2), 1, 10)
C * START --> COMPID
   10 IF (FROM(1:5) == 'START') THEN
        IF (COMPD == ' ') THEN
C * GET LAST-ENTERED COMPID AND SUGGEST IT AS DEFAULT CHOICE
          OPEN (LU61, FILE = FNM(1:IU + 3)//'.compid',
     1          STATUS = 'UNKNOWN')
          READ (LU61, 99999, IOSTAT = IOST) COMPD
          IF (IOST == -1) CLOSE (UNIT = LU61)
        END IF
        CPR(1) = 'COMPID'
        CPR(2) =  COMPD
        GO TO 50
C * COMPID --> CELL
      ELSE IF (FROM(1:6) == 'COMPID') THEN
        CPR(1) = 'CELL'
C * CELL --> HELENA, ABSPSI, TRMX
      ELSE IF (FROM(1:4) == 'CELL') THEN
        IF (ISPR(1) == 1 .OR. ISPR(1) == 2) THEN
          CPR(1) = 'HELENA'
        ELSE
          IF (ISPR(37) > 1) THEN
            CPR(1) = 'ABSPSI'
          ELSE
            CPR(1) = 'TRMX'
          END IF
        END IF
C * HELENA --> ABSPSI, TRMX
      ELSE IF (FROM(1:6) == 'HELENA') THEN
        IF (ISPR(37) > 1) THEN
          CPR(1) = 'ABSPSI'
        ELSE
          CPR(1) = 'TRMX'
        END IF
C * ABSPSI,ABSNONE --> TRMX, SHELXL
      ELSE IF (FROM(1:6) == 'ABSPSI' .OR.
     1         FROM(1:7) == 'ABSNONE') THEN
        IF (ISPR(6) <= 0) THEN
          CPR(1) = 'TRMX'
        ELSE
          CPR(1) = 'SHELXL'
          IF (ISPR(6) == 1) THEN
            CPR(2) = 'ISO'
          ELSE
            CPR(2) = 'ANISO'
          END IF
        END IF
C * TRMX --> SPGR
      ELSE IF (FROM(1:4) == 'TRMX') THEN
        CPR(1) = 'SPGR'
C * SPGR --> FORMULA
      ELSE IF (FROM(1:4) == 'SPGR') THEN
        IF (ISPR(6) < 0) THEN
          IGBL(6) = 17
          CPR(1) = 'FORMULA'
        ELSE IF (ISPR(6) > 0) THEN
          FROM = 'SHELXL'
          GO TO 10
        END IF
C * FORMULA --> Z
      ELSE IF (FROM(1:7) == 'FORMULA') THEN
        CPR(1) = 'Z'
C * Z --> PHASE(SHELXS86 etc), SHELXL
      ELSE IF (FROM(1:2) == 'Z ') THEN
        IF (ISPR(11) < 4) THEN
C * IMPORT .res data
          INQUIRE (FILE = 'tm/sg/.newsym.res', EXIST = EXST)
          IF (EXST) THEN
            KERR = 0
            CALL SPAWN ('mv tm/sg/.newsym.res tm/sg/pn/s.res', 0,
     1        .true., KERR)
            ISPR(11) = 4
            CPR(1)   = 'SHELXL'
            CPR(2)   = 'ISO'
            ISPR(97) = 1
            INQUIRE (FILE = 'tm/sg/.newsym.sav', EXIST = EXST)
            IF (EXST) THEN
              OPEN (LU64, FILE = 'tm/sg/.newsym.sav',
     1              STATUS = 'UNKNOWN')
              READ (LU64, 99997) (CPR(I), I = 201, 204)
              CLOSE (UNIT = LU64)
              KERR = 0
              CALL SPAWN ('mv tm/sg/.newsym.sav tm/sg/pn/newsym.sav',
     1          0, .true., KERR)
            END IF
          ELSE
C * SET DEFAULT SHELXS PATH FOR LIGHT ATOM STRUCTURES
C * USE DIRDIF (WHEN AVAILABLE) FOR HEAVY ATOM STRUCTURES
            CALL S921 (-1)
          END IF
        END IF
C * PHASE --> EXOR, SHELXL
      ELSE IF (FROM(1:5) == 'PHASE') THEN
C * CHECK FOR SHELXS86/SHELXS97/SHELXD
        IF (ISPR(16) == 1 .OR. ISPR(16) == 2 .OR. ISPR(16) == 6)
     1    THEN
          CPR(1) = 'EXOR'
          CPR(2) = 'REFINE'
C * CHECK FOR SIR/SIR2004/DIRDIF
        ELSE IF (ISPR(16) == 3 .OR. ISPR(16) == 4
     1                           .OR. ISPR(16) == 5) THEN
          CPR(1) = 'EXOR'
          CPR(2) = ' '
        ELSE
          CPR(1) = 'SHELXL'
          CPR(2) = 'ISO'
        END IF
C * EXOR -- > SHELXL ISO
      ELSE IF (FROM(1:4) == 'EXOR') THEN
        CPR(1) = 'SHELXL'
        CPR(2) = 'ISO'
C * SAVE DATABASE
        CALL S920 (1)
C * ADDSYM --> TRMX, SHELXL
      ELSE IF (FROM(1:6) == 'ADDSYM') THEN
C * IMPLEMENT ADDSYM PROPOSAL
        IF (ISPR(98) == 1) THEN
          CPR(1)    = 'TRMX'
          CPR(2)    = ' '
          ISPR(223) = 0
          ISPR(98)  = 0
        ELSE
          FROM = 'SHELXL'
          GO TO 10
        END IF
C * FROM ANIS --> SHELXL
      ELSE IF (FROM(1:4) == 'ANIS') THEN
        CPR(1)  = 'SHELXL'
        CPR(2)  = ' '
        ISPR(7) = 0
C * SHOW RESULTS /  LIST STATUS
C * SHELXL -->
      ELSE IF (FROM(1:6) == 'SHELXL') THEN
   30   IF (ISPR(6) == 1) THEN
          IF (SPAR(3) > 8.5 .AND. ISPR(15) == 0 .AND.
     1        ISPR(5) == 0  .AND. ISPR(37) > 0 .AND.
     2        ISPR(71) > 0  .AND. ISPR(70) > ISPR(71) * 2) THEN
              CPR(1) = 'MULABS'
          ELSE
            IF (ISPR(97) == 1) THEN
              ISPR(97) = 0
              CPR(1)   = 'EXOR'
              CPR(2)   = ' '
            ELSE
C * ELTREF CHECK
              IF (IGBL(117) == 1) THEN
                CPR(1) = 'ELTREF'
                CPR(2) = ' '
C * ADDSYM CHECK
              ELSE IF (IGBL(41) == 1) THEN
                CPR(1) = 'ADDSYM'
                CPR(2) = ' '
              ELSE
                CPR(1)    = 'SHELXL'
                CPR(2)    = 'ANISO'
                ISPR(7)   = 1
                IGBL(117) = 1
              END IF
            END IF
          END IF
        ELSE IF (ISPR(6) == 2) THEN
C * ELTREF
          IF (IGBL(117) == 1) THEN
            CPR(1) = 'ELTREF'
            CPR(2) = ' '
C * RENAME
          ELSE IF (ISPR(92) == 0 .AND. IGBL(50) == 0) THEN
            CPR(1) = 'RENAME'
          ELSE
            IF (ISPR(112) > 0) THEN
              IF (SPAR(3) < 36) THEN
                CPR(1) = 'HDIF'
              ELSE
                CPR(1) = 'HFIX'
              END IF
            ELSE
              ISPR(6) = 3
              GO TO 30
            END IF
          END IF
        ELSE IF (ISPR(6) == 3) THEN
          IF (ISPR(92) == 0 .AND. ISPR(93) == 0) THEN
            ISPR(93) = 1
            CPR(1) = 'RENUM'
            CPR(2) = ' '
          ELSE
            CPR(1)  = 'SHELXL'
            CPR(2)  = 'WEIGHT'
            ISPR(7) = 1
          END IF
        ELSE IF (ISPR(6) == 4) THEN
          IF (FROM(1:6) == 'SHELXL') THEN
            CPR(1) = 'VALID'
            CPR(2) = ' '
          ELSE
            ISPR(6) = 5
            GO TO 30
          END IF
        ELSE IF (ISPR(6) == 5) THEN
          IF (IGBL(50) /= 2) THEN
            CPR(1)  = 'PLATON'
            CPR(2)  = 'ADP'
            ISPR(6) = 6
          ELSE
            CPR(1)  = 'EXIT'
            CPR(2)  = ' '
          END IF
        ELSE IF (ISPR(6) == 6) THEN
          CPR(1)  = 'PLUTON'
          CPR(2)  = ' '
          ISPR(6) = 7
        ELSE IF (ISPR(6) == 7) THEN
          CPR(1)  = 'REPORT'
          CPR(2)  = ' '
          ISPR(6) = 8
        ELSE IF (ISPR(6) == 8) THEN
          CPR(1) = 'EXIT'
          CPR(2) = ' '
        END IF
        ISPR(16) = 0
C * MULABS --> SHELXL
      ELSE IF (FROM(1:6) == 'MULABS') THEN
        CPR(1) = 'SHELXL'
        IF (ISPR(6) == 1) THEN
          CPR(2) = 'ISO'
        ELSE
          CPR(2) = 'ANISO'
        END IF
C * HDIF, HFIX --> SHELXL HATS
      ELSE IF (FROM(1:4) == 'HDIF' .OR.
     1         FROM(1:4) == 'HFIX') THEN
        CPR(1)  = 'SHELXL'
        CPR(2)  = 'HATS'
        ISPR(7) = 1
      END IF
C * INVERT
      IF (ISKIP == 0) THEN
        IF (ISPR(6) > 2) THEN
          IF (SPAR(225) > 0.5 .AND. SPAR(226) < 0.5 .AND.
     1        ISPR(14) /= 8) THEN
            CPR(1) = 'INVERT'
            CPR(2) = ' '
          END IF
        END IF
      END IF
C * SAVE .s.dbf
   40 CALL S920 (1)
   50 IF (IGBL(50) < 2) WRITE (LU6, 99998, IOSTAT = IOST)
     1  FROM, CPR(1)
      RETURN
99999 FORMAT(A)
99998 FORMAT (/, ':: FROM ', A, ' TO ', A)
99997 FORMAT (6X, A)
      END SUBROUTINE S030
 
      SUBROUTINE S040
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      USE lplat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IB
      INTEGER :: IE
      INTEGER :: IP
      INTEGER :: KP
      INTEGER :: L1
      INTEGER :: L2
      INTEGER :: N40
      INTEGER :: N80
      INTEGER :: M80
      INTEGER :: K80
      INTEGER :: L80
      INTEGER :: MPCOL
      CHARACTER(len=5)  :: PTYPE
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=80), DIMENSION(41) :: TXT
      CHARACTER(len=8),  DIMENSION(6)  :: ABSTYPE
      ABSTYPE = (/'ABSNONE ', '  ABSPSI', '  MULABS', '        ',
