          CALL GEN038 (LIJN, 10, 30)
          CALL GEN038 (LIJN, 43, 47)
          CALL GEN038 (LIJN, 68, 80)
          CALL PLA439 (0.0, LIJN, N, 0.35, 5 + IGBL(68), 2, 0.5, 7.5)
C * AV ABS (E**2-1)
          IF (SPAR(15) /= 0.0) THEN
            IF (ISPR(99) < IGBL(89)) THEN
              PTYPE = 'EQUAL'
            ELSE
              PTYPE = 'HEAVY'
            END IF
            WRITE (LIJN, 99972, IOSTAT = IOST)
     1        SPAR(15), PTYPE, SPAR(16)
            CALL PLA439 (0.0, LIJN, 48, 0.35, 1, 2, 0.5, 7.0)
            CALL GEN038 (LIJN, 15, 19)
            CALL GEN038 (LIJN, 32, 36)
            CALL PLA439 (0.0, LIJN, 42, 0.35, 5 + IGBL(68), 2, 0.5, 7.0)
          END IF
          CALL PLA439 (0.0, PROBLEM, 80, 0.35, 2, 2, 0.5, 6.5)
C * LIST OBSERVED VERSUS SINTH/LAMBDA
          IF (ISPR(3) == 0) THEN
            INQUIRE (FILE = 'latt/latt.lis', EXIST = EXST)
            IF (EXST) THEN
              VRT = 16.0
              N   = 0
              OPEN (LU61, FILE = 'latt/latt.lis', STATUS = 'UNKNOWN')
  30          READ (LU61, 99971, IOSTAT = IOST) LIJN
              IF (IOST == 0) THEN
                IF (LIJN(1:3) /= 'sh ') GO TO 30
                VRT = VRT - 0.5
                CALL PLA439 (0.0, LIJN, 80, 0.25, -1, 2, 7.7, VRT)
                READ (LU61, 99971, IOSTAT = IOST)
                IF (IOST == 0) THEN
  40              READ (LU61, 99971, IOSTAT = IOST) LIJN
                  IF (IOST == 0) THEN
                    IF (LIJN(1:2) /= '  ') THEN
                      VRT = VRT - 0.5
                      N   = N + 1
                      CALL PLA439 (0.0, LIJN, 80, 0.25, -1, 2, 7.7, VRT)
                      IF (N < 22) GO TO 40
                    END IF
                  END IF
                END IF
              END IF
            ELSE
C * LIST FACES (IF ANY AND NO OTHER ABSORPTION CORRECTION DONE)
              IF (ISPR(15) == 0) CALL S080 (-1, 0, 0, 0, 0.0)
            END IF
          END IF
        ELSE
          CALL S910
          IF (IGBL(50) == 0) GO TO 10
        END IF
      END IF
C * SHORT INSTRUCTION INFO DISPLAY FOR SUGGESTED INSTRUCTION
      IF (IGBL(50) == 0) THEN
        IB = 0
        IE = 0
        SELECT CASE (CPR(1)(1:6))
          CASE ('COMPID')
            IB = 2
            IE = 3
          CASE ('HELENA')
            IB = 4
            IE = 5
          CASE ('CELL  ')
            IB = 6
            IE = 6
          CASE ('ABSPSI')
            IB = 33
            IE = 33
          CASE ('TRMX  ')
            IB = 7
            IE = 10
          CASE ('SPGR  ')
            IB = 11
            IE = 12
          CASE ('FORMUL')
            IB = 13
            IE = 14
          CASE ('Z     ')
            IB = 15
            IE = 16
          CASE ('DIRDIF')
            IB = 17
            IE = 19
          CASE ('EXOR  ')
            IB = 20
            IE = 22
          CASE ('SHELXS')
            IB = 23
            IE = 25
          CASE ('SHELXL')
            IB = 26
            IE = 27
          CASE ('RENAME')
            IB = 27
            IE = 27
          CASE ('HDIF  ')
            IB = 28
            IE = 29
          CASE ('MULABS')
            IB = 39
            IE = 39
          CASE ('HFIX  ')
            IB = 31
            IE = 31
          CASE ('PLUTON')
            IB = 32
            IE = 32
          CASE ('VALID ')
            IB = 34
            IE = 34
          CASE ('REPORT')
            IB = 35
            IE = 35
          CASE ('PLATON')
            IF (CPR(2)(1:3) == 'ADP')  THEN
              IB = 36
              IE = 36
            END IF
          CASE ('EXIT  ')
            IB = 37
            IE = 37
          CASE ('INVERT')
            IB = 38
            IE = 38
          CASE ('ADDSYM')
            IB = 40
            IE = 40
          CASE ('ELTREF')
            IB = 41
            IE = 41
        END SELECT
        VRT = (IE - IB + 1) * 0.7 + 0.5
        CALL GGIP (0.0, 1.0, 0.0, 0)
        VRT = VRT + 0.6
        CALL GGIP (0.0,  VRT, 0.0, 3)
        CALL GGIP (HORS, VRT, 0.0, 2)
C * SHOW VALIDATION RESULT
        IF (VALIDATION(1:8) /= '        ') THEN
          CALL PLA439 (0.0, 'VALIDATION :'//VALIDATION, 57, 0.35,
     1                 2, 2, 0.5, 6.0)
        END IF
        IF (CPR(105)(1:5) /= 'START') THEN
          DO I = 1, 2
            CALL PLA439 (0.0, LNKS(I), 80, 0.375, 3, 2, 0.5,
     1                   VRT + 1.4 - I * 0.6)
          END DO
        END IF
        CALL GGIP (0.0,  VRT + 1.3, 0.0, 3)
        CALL GGIP (HORS, VRT + 1.3, 0.0, 2)
        IF (ISPR(48) == 0) THEN
          CALL PLA439 (0.0, DATAORG, 80, 0.375, 3, 2, 0.5, VRT + 1.5)
        ELSE
C * LIST PROGRAMS USED
          LIJN(1:42)  = 'DataRed  AbsCorr  Phasing  Workup   Refine'
          LIJN(43:80) = '   H-Atoms  Labels   Solv-Dis Transfer'
          CALL PLA439 (0.0, LIJN, 80, 0.35, 5 + IGBL(68), 2, 0.5,
     1                 VRT + 2.1)
          WRITE (LIJN, 99986, IOSTAT = IOST)
     1      (CPR(200 + I)(1:9), I = 1, 8), CPR(209)(1:8)
          CALL PLA439 (0.0,  LIJN, 80, 0.35, 1, 2, 0.5, VRT + 1.5)
          CALL GGIP (0.0,  VRT + 2.6, 0.0, 3)
          CALL GGIP (HORS, VRT + 2.6, 0.0, 2)
          IF (ISPR(15) /= 0) THEN
            IF (ISPR(15) == 6) THEN
            ELSE
              WRITE (LIJN, 99989, IOSTAT = IOST)
     1          ABSTYPE(ISPR(15)), SPAR(126), SPAR(127)
            END IF
            CALL PLA439 (0.0,  LIJN, 80, 0.35, -1, 2, 0.5, VRT + 2.8)
          END IF
          IF (ISPR(223) > 0) THEN
            WRITE (LIJN, 99979, IOSTAT = IOST)
     1        ISPR(223), ISPR(220), ISPR(221),
     1             ISPR(222), SPAR(141), SPAR(142), SPAR(140)
            CALL PLA439 (0.0,  LIJN, 80, 0.35, 2, 2, 0.5, VRT + 3.3)
          END IF
        END IF
      ELSE
C * BOX
        CALL GGIP (0.0,   1.0, 0.0, 0)
        CALL GGIP (0.0,   0.0, 0.0, 3)
        CALL GGIP (HORS,  0.0, 0.0, 2)
        CALL GGIP (HORS, VERT, 0.0, 2)
        BCD =
     1    'N.Q.A. - M O D E  --  SIT BACK, SEE WHAT HAPPENS'//CHAR(0)
        CALL GGIP (-999.0, 3.0, 60.0, 112)
      END IF
      K  = 1
      KP = 1
      DO I = 1, 2
        DO J = 1, 8
          IF (CPR(I)(9 - J:9 - J) /= ' ') THEN
            KP = K + 8 - J
            LINE(K:KP) = CPR(I)(1:9 - J)
            LINE(KP + 1:KP + 1) = ' '
            K = KP + 2
            GO TO 60
          END IF
        END DO
   60   CONTINUE
      END DO
      IF (IGBL(50) == 0) THEN
C * DISPLAY SUGGESTED INSTRUCTION
        CALL GEN038 (LINE, KP + 1, 80)
        IF (IB /= 0) THEN
          SBCD  = 's['//LINE(1:KP)//']'//CHAR (0)
          VRT = VRT - 0.6
          DO I = IB, IE
            CALL PLA439 (0.0, TXT(I), 77, 0.375, 2, 2, 0.5, VRT)
            VRT = VRT - 0.7
          END DO
          LIJN(1:36)  = 'Click on ACCEPT or Hit ENTER Key to '
          LIJN(37:73) = 'accept suggested default shown in [].'
          CALL PLA439 (0.0,  LIJN, 73, 0.375, 5 + IGBL(68), 2, 0.5,
     1                 0.5)
        END IF
      ELSE
        CALL GGIP (0.0, 0.0, 0.0, -1)
      END IF
      RETURN
99999 FORMAT ('Status = ', A, ' for ', A, 'From tm/sg/pn/ = ', A,
     1 ' - ', A, A)
99998 FORMAT ('Temp(K)', 8X, I6, 3X, 'Form ', 2I4, 14I3)
99997 FORMAT ('a    ', F8.4, '(', F6.4, ')   Unit ', 2I4, 14I3)
99996 FORMAT ('b    ', F8.4, '(', F6.4, ')   Cont ', 2I4, 14I3)
99995 FORMAT ('c    ', F8.4, '(', F6.4, ')   Faces', I6, 3X,
     1        'Nmeas  Nuniq   Nobs', 3X, 'Rint ', F5.3, 5X, F5.3)
99994 FORMAT ('alpha', F8.3, '(', F6.3, ')   mu(mm)', F5.2, I8,
     1 2I7, 3X, 'I gt', F5.1, ' * Sigma(I)')
99993 FORMAT ('beta ', F8.3, '(', F6.3, ')   d(x)', F7.3,
     1 3X, 'Space Group', A, A, 3X, 'Nref', I6, I10)
99992 FORMAT ('gamma', F8.3, '(', F6.3, ')   AtVol', F6.1,
     1 3X, 'Nsym', I4, 2X, 'Npar', I5, 3X, 'R', F9.3, ' wR2', F6.3)
99991 FORMAT ('Vol', F12.2, '(', F4.2, ')', '   Z', I10,
     1 3X, 'OldW:', F7.4, F7.3, 3X, 'Rec.W:', F7.4, F7.3)
99990 FORMAT (' HKLF - TRMX', 9F6.3, 4X, 'Npar', I5)
99989 FORMAT (15X, A, ' Absorption Correction:',
     1 ' - Transm. Min. Max = ', 2F6.3)
99987 FORMAT ('Resid. Dens. Extrema:', 2X, 2F6.2, 2X,
     1        ' Mean & Max Shift/Err: ', F5.3, F7.3, ' S', F6.2)
99986 FORMAT (9A)
99985 FORMAT (60X, A, F7.2, '(', F4.2, ')')
99984 FORMAT (60X, A, F7.4, '(', F7.4, ')')
99981 FORMAT ('Vol', F12.2, '(', F4.2, ')', '   Z', I10)
99979 FORMAT (I3, ' Outliers:MaxH,K,L', 3I3,' Fo^2=',F10.2,
     1        ' Fc^2=', F10.2, ' Del/Sig=',F8.2)
99978 FORMAT ('THmin,THmax =', 4F5.1)
99977 FORMAT ('Hmin, Hmax  =', 4I5, 14X, 3I3)
99976 FORMAT ('Kmin, Kmax  =', 4I5, 3X, 'TWIN', 7X, 3I3)
99975 FORMAT ('Lmin, Lmax  =', 4I5, 14X, 3I3)
99974 FORMAT ('Size (mm) ', F5.2, ' x', F5.2, ' x', F5.2,
     1 2X, 'Mean(I/sig)', F5.1, 13X, 'BASF', F9.3, '(', F5.3, ')')
99973 FORMAT (
     1 'WaveLength ', F10.5, 3X, 'Elem', 1X, 2(2X, A), 14(1X, A))
99972 FORMAT ('Av Abs(E**2-1)', F5.2, 2X, 'PATT TYPE ', A, 2X,
     1        'U =', F6.3)
99971 FORMAT (A)
      END SUBROUTINE S040
 
      SUBROUTINE S050
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: L1
      INTEGER :: L2
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: IND
      INTEGER :: IER
      INTEGER :: IP2
      INTEGER :: IP3
      INTEGER :: IP4
      INTEGER :: NDIF
      INTEGER :: IVAL
      INTEGER :: IVLO
      INTEGER :: IERR
      INTEGER :: ICGLS
      INTEGER :: CHDIR
      REAL :: D
      REAL :: VAL
      REAL :: VALO
      CHARACTER(len=256) :: LIN
      IERR = 0
      EXST = .FALSE.
C * LIST CURRENT STATUS
   10 CALL S040
C * GET NEXT INSTRUCTION
   20 CALL GEN038 (IGGT, 1, 80)
      IF (IGBL(50) == 0 .AND. ISPR(47) == 0) THEN
C * WHAT NEXT ?
        CALL PLA012 (0, 0)
        LIN = IGGT
        CALL GEN020 (1, IGGT, 1, 80)
        IF (LRET == 2 .OR. IGGT(1:3) == 'REF' .OR.
     1      IGGT(1:4) == 'PLOT') GO TO 10
C * JUMP OVER 'NEXT'-INSTRUCTIONS WHEN APPROPRIATE
        IF (IGGT(1:4) == 'SKIP') THEN
          CALL S030 (1)
          GO TO 10
        END IF
        IF (IGGT(1:1) /= CHAR (32) .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
        END IF
        CALL GEN020 (1, LINE, 1, 6)
        IF (CPR(1)(1:6) == 'COMPID' .AND. LINE(1:6) /= 'COMPID')
     1    THEN
          IGGT = LINE
          LINE = CPR(1)//LIN(1:70)
          CALL GEN038 (IGGT, 1, 80)
        END IF
        CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 0, 1, 0, 10, NP17)
C * ADAPT/MODIFY COMPID INFO (NOTE S592C IS SPLIT INTO 'S592 C')
        IF (JFL(1)(1:6) == 'COMPID' .AND. KL > 1) THEN
          KL     = 2
          CALL GEN038 (JFL(2), 1, 10)
          NB = 7
          NE = 80
          CALL GEN039 (0, LINE, 7, 80, NB, NE)
          JFL(2) = LINE(NB:NE)
          IF (JFL(2)(1:2) /= '-s') THEN
            CPR(2) = JFL(2)
            COMPD  = CPR(2)
          END IF
C * GENERATE FORMULA LINE WHEN 'FORMULA' IS MISSING
        ELSE IF (CPR(1)(1:7) == 'FORMULA' .AND. KL > 0) THEN
          DO I = 2, 3
            CALL GEN105 (3, JFL(1)(I:I), J)
            IF (J >= 0) THEN
              DO N = 1, KL
                JFL(KL + 2 - N) = JFL(KL + 1 - N)
              END DO
              JFL(1) = 'FORMULA'
              KL = KL + 1
              GO TO 30
            END IF
          END DO
        END IF
      ELSE
        CALL GGIP (0.0, 0.0, 0.0, -1)
        KL = 0
        KN = 0
        ISPR(47) = 0
      END IF
C * ACCEPT SUGGESTED INSTRUCTION
   30 IPR(221) = KN
      IF (KL == 0) THEN
        JFL(1) = CPR(1)
        KL     = 1
        IF (CPR(2) /= ' ') THEN
          JFL(2) = CPR(2)
          KL     = 2
        END IF
      END IF
      IF (IGBL(50) == 0) THEN
        LIN = 'EXEC='//JFL(1)
        CALL PLA439 (0.0, LIN, 17, 0.7, 4, 4, 18.1, 14.6)
        CALL PLA439 (0.0, LIN, 17, 0.7, 2, 4, 18.0, 14.5)
        CALL GGIP (0.0, 0.0, 0.0, 6)
        SBCD = CHAR (0)
      END IF
C * COMPID SPECIFICATION
      IF (JFL(1)(1:6) == 'COMPID') THEN
        CALL S020
C * CHECK/GET WAVELENGTH AND UNIT CELL PARAMETERS
      ELSE IF (JFL(1)(1:4) == 'CELL') THEN
        ISPR(48) = 1
        CALL S060
C * ASYM
      ELSE IF (JFL(1)(1:4) == 'ASYM') THEN
        CALL S110
C * ABSGAUSS
      ELSE IF (JFL(1)(1:8) == 'ABSGAUSS') THEN
        CALL S140
C * ABSTOMPA
      ELSE IF (JFL(1)(1:8) == 'ABSTOMPA') THEN
        CALL S150
C * ABSNONE
      ELSE IF (JFL(1)(1:7) == 'ABSNONE') THEN
        CALL S155
C * TRMX - SELECT LATTICE
      ELSE IF (JFL(1)(1:4) == 'TRMX') THEN
        CALL S160
C * SELECT SPACE GROUP SYMMETRY
      ELSE IF (JFL(1)(1:4) == 'SPGR') THEN
        CALL S170
C * DEFINE UNIT CELL CONTENT (FORMULA)
      ELSE IF (JFL(1)(1:7) == 'FORMULA') THEN
        CALL S180 (0)
C * Z
      ELSE IF (JFL(1)(1:2) == 'Z ') THEN
        CALL S190 (0, IER)
C * STRUCTURE DETERMINATION METHODS
C * SHELXS (86/97) (TREF/TEXP/PATT)
      ELSE IF (JFL(1)(1:6) == 'SHELXS') THEN
        CPR(52) = 'TREF'
        IF (KL > 1) THEN
          IF (JFL(2)(1:4) == 'PATT') THEN
            CPR(52) = 'PATT'
          ELSE IF (JFL(2)(1:4) == 'TEXP') THEN
            CPR(52) = 'TEXP'
          END IF
        END IF
        IF (JFL(1)(7:8) == '86') THEN
          ISPR(16) = 1
        ELSE
          ISPR(16) = 2
        END IF
        CALL S200
C * SIR(97/2004/2011)
      ELSE IF (JFL(1)(1:3) == 'SIR') THEN
        IF (JFL(1)(4:5) == '  ' .OR. JFL(1)(4:5) == '97') THEN
          IF (IGBL(113) /= 0) ISPR(16) = 3
        ELSE IF (JFL(1)(4:7) == '2004') THEN
          IF (IGBL(114) /= 0) ISPR(16) = 4
        ELSE IF (JFL(1)(4:7) == '2011') THEN
          IF (IGBL(120) /= 0) ISPR(16) = 9
        END IF
        IF (ISPR(16) == 3 .OR. ISPR(16) == 4 .OR. ISPR(16) == 9)
     1    THEN
          CALL S200
        ELSE
          CALL PLA015 (0, 57)
          IGBL(107) = IGBL(107) -1
          GO TO 10
        END IF
C * DIRDIF08 (PATTY/PHASEX/ORIENT)
      ELSE IF (JFL(1)(1:6) == 'DIRDIF') THEN
        CPR(62) = 'PATTY'
        IF (KL > 1) THEN
          IF (JFL(2)(1:6) == 'ORIENT') THEN
            CPR(62) = 'ORIENT'
          ELSE IF (JFL(2)(1:6) == 'PHASEX') THEN
            CPR(62) = 'PHASEX'
        END IF
        IF (CPR(62)(1:5) == 'PATTY' .AND. SPAR(3) < 15) THEN
            CALL PLA015 (0, 11)
            GO TO 70
          END IF
        END IF
        IF (IGBL(115) /= 0) THEN
          ISPR(16) = 5
          CALL S200
        END IF
C * SHELXD
      ELSE IF (JFL(1)(1:6) == 'SHELXD') THEN
        IF (IGBL(112) /= 0) THEN
          ISPR(16) = 6
          CALL S200
        END IF
C * FLIPPER
      ELSE IF (JFL(1)(1:7) == 'FLIPPER') THEN
        ISPR(16) = 7
        CALL S200
C * SHELXT
      ELSE IF (JFL(1)(1:6) == 'SHELXT') THEN
        ISPR(16) = 8
        CALL S200
C * SIR2011
      ELSE IF (JFL(1)(1:7) == 'SIR2011') THEN
        ISPR(16) = 9
        CALL S200
C * REMOVE GHOSTS AND INTERPRET PEAKLIST (EXOR)
      ELSE IF (JFL(1)(1:5) == 'EXOR ') THEN
C * CHECK FOR s.res, run by default SHELXS first otherwise
        INQUIRE (FILE = FNM(1:INZ)//'s.res', EXIST = EXST)
        IF (.NOT. EXST) THEN
          ISPR(16) = 1
          CALL S200
        END IF
        IF (JFL(2)(1:6) == 'REFINE') THEN
          IP2 = 4
          IP3 = 3
          IP4 = 2
        ELSE
          IP2 = 5
          IP3 = 4
          IP4 = 0
        END IF
        IF (KN > 0) IP2 = NINT (FN(1))
        IF (KN > 1) IP3 = NINT (FN(2))
        IF (KN > 2) IP4 = NINT (FN(3))
        CALL S300 (IP2, IP3, IP4)
C * REMOVE GHOSTS (USING SIR97) AND INTERPRET   (EXORS)
      ELSE IF (JFL(1)(1:5) == 'EXORS') THEN
C * CHECK FOR s.res, run by default SHELXS first otherwise
        INQUIRE (FILE = FNM(1:INZ)//'s.res', EXIST = EXST)
        IF (.NOT. EXST) THEN
          ISPR(16) = 1
          CALL S200
        END IF
        IF (IGBL(113) /= 0) CALL S301 (IERR)
C * REMOVE GOSTS (USING DIRDIF99) AND INTERPRET   (EXORD)
      ELSE IF (JFL(1)(1:5) == 'EXORD') THEN
C * CHECK FOR s.res, run by default SHELXS first otherwise
        INQUIRE (FILE = FNM(1:INZ)//'s.res', EXIST = EXST)
        IF (.NOT. EXST) THEN
          ISPR(16) = 1
          CALL S200
        END IF
        IF (IGBL(115) /= 0) CALL S302 (IERR)
C * CHECK ATOM TYPE ASSIGNMENT
      ELSE IF (JFL(1)(1:6) == 'ELTREF') THEN
        IGBL(117) = 0
        FN(1)     = 0.0
        FN(2)     = 0.0
        CALL S305 (1, 2)
C * REFINE STRUCTURE - SHELXL2014
      ELSE IF (JFL(1)(1:6) == 'SHELXL' .OR.
     1         JFL(1)(1:4) == 'CGLS') THEN
        IF (JFL(1)(1:4) == 'CGLS') THEN
          ICGLS = 1
        ELSE
          ICGLS = 0
        END IF
        ISPR(7) = 0
        IF (ISPR(11) >= 4) THEN
          IF (KL > 1) THEN
            IF (JFL(2)(1:3) == 'ISO') THEN
              IF (ISPR(6) == 0) THEN
                ISPR(7) = 1
              ELSE
                ISPR(6) = 1
                ISPR(7) = 0
              END IF
            ELSE IF (JFL(2)(1:5) == 'ANISO') THEN
              IF (ISPR(6) == 1) THEN
                ISPR(7) = 1
              ELSE
                ISPR(6) = 2
                ISPR(7) = 0
              END IF
            ELSE IF (JFL(2)(1:4) == 'HATS') THEN
              IF (ISPR(6) == 2) THEN
                ISPR(7) = 1
              ELSE
                ISPR(6) = 3
                ISPR(7) = 0
              END IF
            ELSE IF (JFL(2)(1:6) == 'WEIGHT') THEN
              IF (ISPR(6) == 3) THEN
                ISPR(7) = 1
              ELSE
                ISPR(6) = 4
                ISPR(7) = 0
              END IF
            END IF
          END IF
C * SHELXL REFINEMENT
          CALL S310 (ICGLS, IERR)
C * ANALYSE FOR CONTENT FORMULA in s.res
          CALL S926
        ELSE
          GO TO 40
        END IF
C * ADDSYM
      ELSE IF (JFL(1)(1:6) == 'ADDSYM') THEN
        CALL S420 ('ADDSYM')
        IGBL(41) = 0
C * INVERT STRUCTURE
      ELSE IF (JFL(1)(1:6) == 'INVERT') THEN
        CALL S175
C * HFREE
      ELSE IF (JFL(1)(1:5) == 'HFREE') THEN
        ISPR(90) = 1
        CPR(206) = 'HFREE     '
C * ABSPSI
      ELSE IF (JFL(1)(1:6) == 'ABSPSI') THEN
        IF (ISPR(37) > 0) THEN
          IF (ISPR(37) > 1) CALL S120
        ELSE
          CALL PLA015 (0, 35)
        END IF
C * MULABS PROCEDURE
      ELSE IF (JFL(1)(1:6) == 'MULABS') THEN
        IF (ISPR(37) > 0) THEN
          CALL S130
        ELSE
          CALL PLA015 (0, 35)
        END IF
C * SQUEEZE PROCEDURE
      ELSE IF (JFL(1)(1:7) == 'SQUEEZE') THEN
        IF (ISPR(11) >= 4)  THEN
          CALL S340
        ELSE
          GO TO 40
        END IF
C * TWINROTMAT
      ELSE IF (JFL(1)(1:7) == 'TWINMAT') THEN
        CALL S350
C * H-ATOMS PICKUP PROCEDURE
      ELSE IF (JFL(1)(1:4) == 'HDIF') THEN
        IF (ISPR(11) >= 5) THEN
          ISPR(7) = 1
          CALL S330
        ELSE
          GO TO 40
        END IF
C * SHOW STRUCTURE (PLUTON)
      ELSE IF (JFL(1)(1:6) == 'PLUTON') THEN
        NDIF = 0
        IF (KN > 0) THEN
          NDIF = NINT (FN(1))
        END IF
        IGBL(50) = 0
        CALL S410 (NDIF)
        CALL S926
C * PLUTON/RENAME
      ELSE IF (JFL(1)(1:6) == 'RENAME') THEN
        ISPR(92) = 1
        NDIF     = -1
        CALL S410 (NDIF)
        CPR(207) = 'RENAME'
        CALL S926
C * PLUTON/HFIX
      ELSE IF (JFL(1)(1:4) == 'HFIX') THEN
        NDIF = -2
        CALL S410 (NDIF)
        ISPR(7)  = 1
        CPR(206) = 'HFIX'
        CALL S926
C * PLUTON/ANIS
      ELSE IF (JFL(1)(1:4) == 'ANIS') THEN
        NDIF = -3
        CALL S410 (NDIF)
        IGBL(6)  = 19
        CPR(105) = 'ANIS'
        CPR(106) = CPR(200)
        CALL S926
C * PLATON/AUTORENUM
      ELSE IF (JFL(1)(1:4) == 'RENU') THEN
        CALL S937
        CPR(207) = 'RENUM'
C * CALL R-PLUTO FOR RES/CIF
      ELSE IF (JFL(1)(1:6) == 'RPLUTO') THEN
        CALL S411
C * ANALYSE STRUCTURE - PLATON
      ELSE IF (JFL(1)(1:6) == 'PLATON') THEN
        IF (KL == 1) JFL(2)(1:) = ' '
        CALL S420 (JFL(2))
C * CONTOUR PLOTS
      ELSE IF (JFL(1)(1:7) == 'CONTOUR') THEN
        CALL S430
C * SAVE AND EOF/END/EXIT/QUIT PROCEDURE
      ELSE IF (JFL(1)(1:3) == 'EOF')  THEN
        GO TO 50
      ELSE IF (JFL(1)(1:3) == 'END')  THEN
        GO TO 50
      ELSE IF (JFL(1)(1:4) == 'EXIT') THEN
        GO TO 50
      ELSE IF (JFL(1)(1:4) == 'QUIT') THEN
        GO TO 50
C * EDIT-RES
      ELSE IF (JFL(1)(1:7) == 'EDITRES') THEN
        KERR = 0
        CALL SPAWN (EDITOR//' s.res', 0, .true., KERR)
        CALL GEN038 (IGGT, 1, 80)
        CALL GEN038 (LINE, 1, 80)
        GO TO 10
C * UTILITIES
      ELSE IF (JFL(1)(1:3) == 'SET') THEN
        IF (JFL(2)(1:3) == 'REV') THEN
          IGBL(68) = MOD (IGBL(68) + 1, 2)
          CALL GGIP (-999.0, FLOAT (IGBL(68)), IGBL(62) * 0.25, 9)
        ELSE
          IND  = NINT (FN(1))
          VAL  = FN(2)
          IVAL = NINT (VAL)
          IF (KL > 1) THEN
            IF (JFL(2)(1:4) == 'ISPR') THEN
              IF (IND < 1 .OR. IND > NPS2) THEN
                WRITE (LU6, 99983, IOSTAT = IOST)
              ELSE
                IVLO     = ISPR(IND)
                ISPR(IND) = IVAL
                WRITE (LU6, 99982, IOSTAT = IOST) IND, IVLO, IVAL
              END IF
            ELSE IF (JFL(2)(1:4) == 'SPAR') THEN
              IF (IND < 1 .OR. IND > NPS1) THEN
                WRITE (LU6, 99983, IOSTAT = IOST)
              ELSE
                VALO     = SPAR(IND)
                SPAR(IND) = VAL
                WRITE (LU6, 99981, IOSTAT = IOST) IND, VALO, VAL
              END IF
            ELSE IF (JFL(2)(1:3) == 'CPR') THEN
              IF (IND < 1 .OR. IND > NPS3) THEN
                WRITE (LU6, 99983, IOSTAT = IOST)
              ELSE
                WRITE (LU6, 99980, IOSTAT = IOST)
     1            IND, CPR(IND), JFL(3)
                CPR(IND) = JFL(3)
              END IF
            ELSE IF (JFL(2)(1:4) == 'IGBL') THEN
              CALL PLA206 (1, 'IGB')
            ELSE IF (JFL(2)(1:4) == 'RGBL') THEN
              CALL PLA206 (1, 'RGB')
            ELSE IF (JFL(2)(1:3) == 'IPR') THEN
              CALL PLA206 (1, 'IPR')
            ELSE IF (JFL(2)(1:4) == 'PAR') THEN
              CALL PLA206 (1, 'PAR')
            END IF
          END IF
          GO TO 20
        END IF
C * TWIN
      ELSE IF (JFL(1)(1:5) == 'TWIN ') THEN
        CALL S905
        GO TO 10
      ELSE IF (JFL(1)(1:2) == 'CD') THEN
        WRITE (LU6, 99999, IOSTAT = IOST) JFL(1)(1:2)
      ELSE IF (JFL(1)(1:3) == 'LOG') THEN
        CALL S915 ('LOG')
      ELSE IF (JFL(1)(1:4) == 'LRES') THEN
        CALL S916
      ELSE IF (JFL(1)(1:6) == 'SHXLPS') THEN
        INQUIRE (FILE = 'tm/sg/shelxl/shelxl.lst', EXIST = EXST)
        IF (EXST) THEN
          OPEN (LU64, FILE = 'tm/sg/shelxl/shelxl.lst',
     1          STATUS = 'UNKNOWN')
          OPEN (LU65, FILE = 'tm/sg/shelxl/shelxl.lps',
     1          STATUS = 'UNKNOWN')
C * CONVERT TO POSTSCRIPT
          CALL GEN089 (LU64, LU65, 100, IGBL(102))
          CLOSE (UNIT = LU64)
          CLOSE (UNIT = LU65)
          KERR = 0
          CALL SPAWN (PSVIEWER//'tm/sg/shelxl/shelxl.lps', 0, .true.,
     1      KERR)
        END IF
      ELSE IF (JFL(1)(1:4) == 'HELP') THEN
        CALL PLA300 (0, 7, 0)
      ELSE IF (JFL(1)(1:4) == 'LIST') THEN
        IF (KL > 1 .AND. (JFL(2)(1:4) == 'ISPR' .OR.
     1    JFL(2)(1:4) == 'SPAR' .OR. JFL(2)(1:3) == 'CPR' .OR.
     2    JFL(2)(1:4) == 'IGBL' .OR. JFL(2)(1:3) == 'IPR' .OR.
     3    JFL(2)(1:3) == 'PAR')) THEN
          IF (KN >= 1) THEN
            N1 = NINT (FN(1))
          ELSE
            N1 = 1
          END IF
          IF (KN >= 2) THEN
            N2 = NINT (FN(2))
          ELSE
            N2 = N1
          END IF
          IF (N2 < N1) N2 = N1
          IF (JFL(2)(1:2) == 'SP') THEN
            IF (KN < 1) N2 = NPS1
            WRITE (LU6, 99996, IOSTAT = IOST)
     1        (' ', I, SPAR(I), I = N1, N2)
          ELSE IF (JFL(2)(1:2) == 'IS') THEN
            IF (KN < 1) N2 = NPS2
            WRITE (LU6, 99995, IOSTAT = IOST)
     1        (' ', I, ISPR(I), I = N1, N2)
          ELSE IF (JFL(2)(1:2) == 'CP') THEN
            IF (KN < 1) N2 = NPS3
            WRITE (LU6, 99994, IOSTAT = IOST)
     1        (' ', I, CPR(I), I = N1, N2)
          ELSE IF (JFL(2)(1:2) == 'IG') THEN
            CALL PLA206 (-1, 'IGB')
          ELSE IF (JFL(2)(1:2) == 'RG') THEN
            CALL PLA206 (-1, 'RGB')
          ELSE IF (JFL(2)(1:2) == 'PA') THEN
            CALL PLA206 (-1, 'PAR')
          ELSE IF (JFL(2)(1:2) == 'IP') THEN
            CALL PLA206 (-1, 'IPR')
          END IF
          GO TO 20
        ELSE IF (KL > 1 .AND. JFL(2)(1:5) == 'FACES'
     1            .AND. ISPR(350) >  0) THEN
          DO I = 1, ISPR(350)
            WRITE (LU6, 99989, IOSTAT = IOST)
     1        ISPR(348 + I * 3), ISPR(349 + I * 3),
     2        ISPR(350 + I * 3), SPAR(500 + I)
          END DO
        END IF
        GO TO 10
      ELSE IF (JFL(1)(1:4) == 'TREE') THEN
        CALL S914
        GO TO 10
      ELSE IF (JFL(1)(1:5) == 'PRINT') THEN
        CALL S918
      ELSE IF (JFL(1)(1:6) == 'RELINK') THEN
        CALL S928
      ELSE IF (JFL(1)(1:6) == 'REPORT') THEN
        CALL S500
      ELSE IF (JFL(1)(1:6) == 'VALID') THEN
        CALL S520 (1)
C * REMOVE/PRUNE
      ELSE IF (JFL(1)(1:5) == 'PRUNE' .OR.
     1         JFL(1)(1:6) == 'REMOVE') THEN
        CALL S934
C * BROWSE
      ELSE IF (JFL(1)(1:6) == 'BROWSE') THEN
        IF (KL > 1) THEN
          IF (JFL(2)(1:3) == 'LPS') THEN
            CALL S935 (1)
          ELSE IF (JFL(2)(1:3) == 'LIS') THEN
            CALL S935 (0)
          ELSE IF (JFL(2)(1:2) == 'PS') THEN
            CALL S936
          END IF
        ELSE
          CALL S935 (0)
        END IF
C * LASER
      ELSE IF (JFL(1)(1:5) == 'LASER') THEN
        CALL S935 (-1)
C * BOUNDING FACES
      ELSE IF (JFL(1)(1:4) == 'FACE') THEN
        IH = NINT (FN(1))
        IK = NINT (FN(2))
        IL = NINT (FN(3))
        D  = FN(4)
        IF (KL == 4) THEN
          CALL S080 (4, IH, IK, IL, D)
        ELSE
          CALL S080 (0, 0, 0, 0, 0.0)
        END IF
C * MU
      ELSE IF (JFL(1)(1:2) == 'MU') THEN
        IF (KN == 1) THEN
          D = FN(1)
          CALL S080 (1, 0, 0, 0, D)
        ELSE
          CALL S080 (0, 0, 0, 0, 0.0)
        END IF
C * THMX
      ELSE IF (JFL(1)(1:4) == 'THMX') THEN
        SPAR(55) = FN(1)
C * STLM
      ELSE IF (JFL(1)(1:4) == 'STLM') THEN
        SPAR(55) = ASIN (SPAR(80) * FN(1)) * RGBL(6)
C * CHIRAL
      ELSE IF (JFL(1)(1:4) == 'CHIR') THEN
        ISPR(8) = 1
C * TEMP ([C]/K)
      ELSE IF (JFL(1)(1:4) == 'TEMP') THEN
        IF (JFL(2)(1:1) == 'K') THEN
          SPAR(10) = FN(1)
        ELSE
          SPAR(10) = FN(1) + 273
        END IF
C * SIZE
      ELSE IF (JFL(1)(1:4) == 'SIZE') THEN
        IF (KN == 3) THEN
          CALL GEN034 (FN, 1, 3)
          SPAR(11) = FN(1)
          SPAR(12) = FN(2)
          SPAR(13) = FN(3)
        END IF
C * XTAL
      ELSE IF (JFL(1)(1:4) == 'XTAL') THEN
        CALL S070
C * AUTO
      ELSE IF (JFL(1)(1:4) == 'AUTO' .OR.
     1         JFL(1)(1:3) == 'NQA') THEN
        IGBL(50) = 1
        CALL GEN038 (IGGT, 1, 80)
      ELSE
C * EXECUTE NON-s COMMAND
        L1 = 1
        L2 = 80
        IF (LINE(1:1) == '#' .OR. LINE(1:1) == '!') L1 = 2
        KERR = 0
        CALL SPAWN('sh -c '''//LINE(L1:L2)//' '' ', 0, .true., KERR)
        GO TO 10
      END IF
      GO TO 70
C * UNSUITABLE INSTRUCTION AT THIS POINT
   40 CALL PLA015 (0, 28)
      GO TO 70
C * SAVE CURRENT CONTEXT
   50 CALL S920 (1)
      IF (CHDIR (WORKDIR) /= 0) GO TO 60
   60 IF (IGBL(50) == 2) THEN
        FNM(INZ + 1: INZ + 20) = 'tm/sg/pn/shelxl.cif '
        LIN =
     1 'cp '//FNM(1:INZ + 20)//WORKDIR(1:IW)//'/'//COMPD(1:IC)//'_s.cif'
        KERR = 0
        CALL SPAWN (LIN, 0, .true., KERR)
        WRITE (LU6, 99976, IOSTAT = IOST)
     1    WORKDIR(1:IW)//'/'//COMPD(1:IC)//'_s.cif'
        FNM(INZ + 1: INZ + 6) = 's.res '
        LIN =
     1 'cp '//FNM(1:INZ + 6)//WORKDIR(1:IW)//'/'//COMPD(1:IC)//'_s.res'
        KERR = 0
        CALL SPAWN (LIN, 0, .true., KERR)
        WRITE (LU6, 99975, IOSTAT = IOST)
     1    WORKDIR(1:IW)//'/'//COMPD(1:IC)//'_s.res'
        FNM(INZ + 1: INZ + 22) = 'tm/sg/valid/valid.chk '
        LIN =
     1 'cp '//FNM(1:INZ + 22)//WORKDIR(1:IW)//'/'//COMPD(1:IC)//'_s.chk'
        KERR = 0
        CALL SPAWN (LIN, 0, .true., KERR)
        WRITE (LU6, 99973, IOSTAT = IOST)
     1    WORKDIR(1:IW)//'/'//COMPD(1:IC)//'_s.chk'
        WRITE (LU6, 99974, IOSTAT = IOST) FNM(1:INZ - 1)
      END IF
      ISW = -1
   70 RETURN
99999 FORMAT ('s: UNIX-SHELL Command ', A, ' not allowed in s')
99996 FORMAT (1(3(A, 'SPAR[', I3, ']=', F10.4, ',')))
99995 FORMAT (1(4(A, 'ISPR[', I3, ']=', I8   , ',')))
99994 FORMAT (1(3(A, 'CPR[', I3, ']=', A    , ',')))
99989 FORMAT ('Face ', 3I5, F10.5)
99983 FORMAT (':: INDEX OUT_OF_RANGE')
99982 FORMAT (':: ISPR(', I3, ') Old value =', I8, ' New value =', I8)
99981 FORMAT (':: SPAR(', I3, ') Old value =', F10.4, ' New value =',
     1        F10.4)
99980 FORMAT (':: CPR(', I3, ') Old value =', A    , ' New value =', A)
99976 FORMAT (/, 'Tentative Result on: ', A)
99975 FORMAT (   '                and: ', A)
99974 FORMAT (/, 'Details may be found in: ', A, /)
99973 FORMAT (   'Validation   Report: ', A)
      END SUBROUTINE S050
 
      SUBROUTINE S060
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: ICELL
      INTEGER :: ICESD
      REAL :: VOL
      REAL :: GEN068
      REAL, DIMENSION(3, 3) :: AA
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=5),  DIMENSION(6)    :: CAX
      CHARACTER(len=12), DIMENSION(6)    :: SCAX
      LOGICAL :: DINQ
      CAX  = (/'a    ', 'b    ', 'c    ', 'alpha', 'beta ', 'gamma'/)
      SCAX = (/'sigma(a)    ', 'sigma(b)    ', 'sigma(c)    ',
     1  'sigma(alpha)', 'sigma(beta) ', 'sigma(gamma)'/)
   10 BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      IF (IGBL(50) == 0) CALL GGIP (HORS, VERT, 0.0, 1)
C * CHECK/GET UNIT CELL
      ICELL = 1
      ICESD = 1
      IF (SPAR(101) > 0.0) THEN
        IF (IGBL(50) == 0) THEN
   20     LIJN = 'GET CELL PARAMETERS'
          CALL PLA439 (0.0, LIJN, 71, 1.2, 5 + IGBL(68), 5, 3.0,
     1                 VERT - 2.0)
          LIJN = 'Compound = '//COMPD(1:IC)
          CALL PLA439 (0.0, LIJN, 11 + IC, 0.5, 3, 2, 8.5, VERT - 3.5)
          CALL GEN038 (LIJN, 1, 80)
          LIJN = 'Cell Data from:'
          IF (ISPR(38) == 3) THEN
            LIJN(17:) = 'scale.out'
          ELSE IF (ISPR(38) == 4) THEN
            LIJN(17:) = 'shelx.ins'
          END IF
          CALL PLA439 (0.0, LIJN, 27, 0.5, 3, 2, 8.5, VERT - 5.0)
          WRITE (LIJN, '(''Lambda = '', F8.5, '' Ang'')',
     1      IOSTAT = IOST) SPAR(80)
          CALL PLA439 (0.0, LIJN, 21, 0.5, 3, 2, 8.5, VERT - 6.5)
          IF (ISPR(38) == 4) THEN
            WRITE (LIJN, 99996, IOSTAT = IOST)
     1        'Cell:', (SPAR(100 + I), I = 1, 6)
            CALL PLA439 (0.0, LIJN, 80, 0.375, 1, 2, 0.5, VERT - 8.0)
            WRITE (LIJN, 99996, IOSTAT = IOST)
     1        ' Esd:', (SPAR(107 + I), I = 1, 6)
            CALL PLA439 (0.0, LIJN, 80, 0.375, -1, 2, 0.5, Vert - 9.0)
            WRITE (LIJN, 99997, IOSTAT = IOST)
     1        ((TM(I, J), J = 1, 3), I = 1, 3)
            CALL GEN065 (0, LIJN, 1, 80, 5)
            CALL PLA439 (0.0, LIJN(1:11),  11, 0.35, 5 + IGBL(68), 2,
     1                   5.0, VERT - 12.0)
            CALL PLA439 (0.0, LIJN(12:29), 18, 0.35, 1, 2,
     1                   9.0, VERT - 11.0)
            CALL PLA439 (0.0, LIJN(30:47), 18, 0.35, 1, 2,
     1                   9.0, VERT - 12.0)
            CALL PLA439 (0.0, LIJN(48:65), 18, 0.35, 1, 2,
     1                   9.0, VERT - 13.0)
          END IF
          LIJN = 'Note: Cell Parameters as retrieved may need '//
     1      'modification to better reflect '
          CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.5, 5.0)
          LIJN = 'the proper lattice symmetry.  (Needed for '//
     1      'automatic space group determination)'
          CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.5, 4.0)
          WRITE (LIJN, '(A, 3F8.4, 3F8.3)', IOSTAT = IOST)
     1    'Current Cell:', (SPAR(100 + I), I = 1, 6)
          CALL PLA439 (0.0, LIJN, 80, 0.375, 1, 2, 0.5, 2.0)
          WRITE (LIJN, '(A, 3F8.4, 3F8.3)', IOSTAT = IOST)
     1    '         Esd:', (SPAR(107 + I), I = 1, 6)
          CALL PLA439 (0.0, LIJN, 80, 0.375, -1, 2, 0.5, 1.0)
C * WHAT NEXT ?
C * Default: Cell and CellEsd O.K. Y/N[Y]
          CALL PLA012 (13, 1)
          IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 20
          IF (IGGT(1:4) == 'EXIT') GO TO 60
          LINE = IGGT
          IF (LINE(1:1) == 'N') ICELL = 0
        END IF
      ELSE
        ICELL = 0
      END IF
      IF (SPAR(108) == 0.0 .AND. IGBL(50) == 0) ICESD = 0
      IF (ICELL == 0) THEN
        ICESD = 0
        DO I = 1, 6
   30     CALL GGIP (0.0, 5.0 + FLOAT (IGBL(68)), 0.0, 0)
          WRITE (SBCD, 99998, IOSTAT = IOST)
     1      CAX(I), SPAR(100 + I), CHAR (0)
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 30
          IF (IGGT(1:4) == 'EXIT') GO TO 60
          IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
            LINE = IGGT
            CALL GEN038 (IGGT, 1, 80)
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 0, 1, 80, 10,
     1                   NP17)
            IF (KN > 0) SPAR(100 + I) = FN(1)
          END IF
        END DO
      END IF
      IF (ICESD == 0) THEN
        DO I = 1, 6
   40     CALL GGIP (0.0, 5.0 + FLOAT (IGBL(68)), 0.0, 0)
          WRITE (SBCD, 99998, IOSTAT = IOST)
     1      SCAX(I), SPAR(107 + I), CHAR (0)
C * WHAT NEXT ?
          CALL PLA012 (0, 1)
          IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 40
          IF (IGGT(1:4) == 'EXIT') GO TO 60
          IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
            LINE = IGGT
            CALL GEN038 (IGGT, 1, 80)
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 0, 1, 80, 10,
     1                   NP17)
            IF (KN > 0) SPAR(107 + I) = FN(1)
          END IF
        END DO
        GO TO 10
      END IF
      DO I = 81, 94
        SPAR(I) = SPAR(I + 20)
      END DO
      IF (DINQ ('latt')) THEN
        KERR = 0
        CALL SPAWN ('rm -r latt', 0, .true., KERR)
      END IF
C * CHECK/GET RADIATION
      IF (SPAR(80) == 0.0) THEN
   50   WRITE (SBCD, 99999, IOSTAT = IOST) CHAR (0)
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 50
        IF (IGGT(1:4) == 'EXIT') GO TO 60
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          WRITE (LINE, 99995, IOSTAT = IOST) 0.71073
        END IF
        CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
        SPAR(80) = FN(1)
      END IF
C * SETUP METRIC
      CALL GEN026 (1, AA, SPAR(81))
      CALL GEN003 (AA, RBB, VOL, 0)
      SPAR(87)  = SQRT (VOL)
      SPAR(107) = SQRT (VOL)
      SPAR(114) = GEN068 (SPAR(101), SPAR(108), 1)
C * THETA-MAX-Cu-Sphere Default
      IF (ABS (SPAR(80) - 0.71073) < 0.0005) THEN
        SPAR(55) = 27.5
      ELSE
        SPAR(55) = ASIN (MIN (1.0, SPAR(80) / 1.5418)) * RGBL(6)
      END IF
C * LOG CELL
      CALL S915 ('Cell Data Entry/Verification')
C * SET WHAT TO DO NEXT
      CPR(105) = 'CELL'
      CPR(106) = CPR(200)
   60 RETURN
99999 FORMAT ('Enter Wavelength [0.71073]: ', A)
99998 FORMAT (A, ' = [', F8.4, '] ', A)
99997 FORMAT (' PRE - TRMX', 9F6.3)
99996 FORMAT (8X, A, 3F8.4, 3F8.3)
99995 FORMAT (F10.5)
      END SUBROUTINE S060
 
      SUBROUTINE S070
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: CHDIR
      CALL S915 ('Run XTAL')
      CALL S929 (-1)
C * CHECK FOR/CREATE XTAL-DIR UNDER /USER/S/COMPOUNDNAME
      CALL S909 (FNM(1:INZ)//'xtal')
      OPEN (LU61, FILE = 'xtal.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99999, IOSTAT = IOST)
     1  COMPD, (SPAR(80 + I), I = 1, 6)
      DO I = 1, ISPR(350)
        WRITE (LU61, 99998, IOSTAT = IOST) (FACE(I, J), J = 1, 4)
      END DO
      WRITE (LU61, 99997, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' xtal.ins', 0, .true., KERR)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR(FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * SAVE DATABASE
      CALL S920 (1)
      RETURN
99999 FORMAT ('TITL ', A, /, 'CELL ', 6F10.4)
99998 FORMAT ('FACE ', 3F5.0, F10.5)
99997 FORMAT ('XTAL')
      END SUBROUTINE S070
 
      SUBROUTINE S080 (MODE, JH, JK, JL, D)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: MODE
      REAL :: D
      CHARACTER(len=80) :: LIJN
C * LOOK FOR STORED FACES IN FILE .faces
      IH = JH
      IK = JK
      IL = JL
      CALL S929 (-1)
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
   10 IF (MODE >= 0 .AND. IGBL(50) == 0)
     1  CALL GGIP (HORS, VERT, 0.0, 1)
      IF (MODE <= 0 .AND. ISPR(350) > 0) THEN
        WRITE (LIJN, 99998, IOSTAT = IOST) SPAR(123)
        CALL PLA439 (0.0, LIJN, 30, 0.3, 1, 2, 8.0, 15.5)
C * LIST CURRENT FACE LIST
        VRT = 14.3
        HRT = 0.0
        VRT = 14.5
        DO I = 1, ISPR(350)
          K = MOD (I - 1, 10)
          IF (K == 0) THEN
            HRT = HRT + 8.0
            VRT = 14.5
            WRITE (LIJN, 99997, IOSTAT = IOST)
            CALL PLA439 (0.0, LIJN, 30, 0.3, 5 + IGBL(68), 2,
     1                     HRT, VRT)
            VRT = VRT - 0.2
          END IF
          WRITE (LIJN, 99996, IOSTAT = IOST)
     1      I, (NINT (FACE(I, J)), J = 1, 3), FACE(I, 4)
          VRT = VRT - 0.6
          CALL PLA439 (0.0, LIJN, 30, 0.3, 1, 2, HRT, VRT)
        END DO
      END IF
      KN = MODE
      IF (KN == 4) THEN
        FN(1) = IH
        FN(2) = IK
        FN(3) = IL
        FN(4) = D
        GO TO 20
      ELSE IF (KN == 1) THEN
        SPAR(123) = D
        GO TO 60
      END IF
      GO TO 40
   20 IF (KN == 4) THEN
        IH = NINT (FN(1))
        IK = NINT (FN(2))
        IL = NINT (FN(3))
        IF (ISPR(350) > 0) THEN
          DO I = 1, ISPR(350)
            IF (NINT (FACE(I, 1)) == IH .AND.
     1          NINT (FACE(I, 2)) == IK .AND.
     2          NINT (FACE(I, 3)) == IL) GO TO 30
          END DO
        END IF
        ISPR(350)  = ISPR(350) + 1
        I          = ISPR(350)
   30   FACE(I, 1) = IH
        FACE(I, 2) = IK
        FACE(I, 3) = IL
        FACE(I, 4) = FN(4)
      END IF
      IF (MODE == 0) GO TO 10
      IF (MODE > 0) GO TO 60
   40 IF (MODE < 0) GO TO 70
   50 WRITE (SBCD, 99999, IOSTAT = IOST) CHAR (0)
C * WHAT NEXT ?
      CALL PLA012 (0, 1)
      IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT' .OR.
     1                     IGGT(1:4) == 'EXIT') GO TO 10
      IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
        LINE = IGGT
        CALL GEN038 (IGGT, 1, 80)
      ELSE
        GO TO 60
      END IF
      CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
      IF (KN == 4) THEN
        GO TO 20
      ELSE IF (KN == 1 .AND. JFL(1)(1:2) == 'MU') THEN
        SPAR(123) = FN(1)
        GO TO 10
      ELSE
        GO TO 50
      END IF
C * SAVE FACES IN FILE .faces
   60 CALL S929 (1)
   70 RETURN
99999 FORMAT ('MU/FACE [Return = Quit]', A)
99998 FORMAT ('Current Mu =', F8.3, ' mm ^ -1')
99997 FORMAT ('Faces : nr h k l d (mm)')
99996 FORMAT (I4, 3I3, F10.4)
      END SUBROUTINE S080
 
      SUBROUTINE S110
      USE files
      USE parameters
      USE ccom
      USE scom
      USE spgrdata
      USE lplat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: CHDIR
      CHARACTER(len=7) :: CHSPGR
      CALL S915 ('Run Platon/ASYM')
C * LIST STATUS
      IF (ISPR(10) == 3) THEN
C * CHECK FOR/CREATE-CHANGE TO ASYM-DIR UNDER user/s/compoundname/tm/sg
        CALL S909 ('tm/sg/asym')
        CHSPGR = CPR(100)(1:7)
      ELSE IF (ISPR(10) == 2) THEN
C * CHECK FOR/CREATE-CHANGE TO ASYM-DIR UNDER user/s/compoundname/tm
        CALL S909 ('tm/asym')
        CHSPGR = BLATT(NRLT)//NLAUE(LLAUE(NRLT))//' '
C * EDIT
        IF (CHSPGR(1:6) == 'R -3m1') CHSPGR(6:6) = ' '
      ELSE IF (ISPR(10) == 1) THEN
C * CHECK FOR/CREATE-CHANGE TO ASYM-DIR UNDER user/s/compoundname/tm
        CALL S909 ('asym')
        CHSPGR = 'P-1    '
      ELSE
        GO TO 10
      END IF
C * RE/LINK TO s.hkl
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl asym.hkl', 0, .true., KERR)
C * PREPARE AND RUN ASYM JOB
      IF (JFL(2)(1:4) == 'VIEW') THEN
        KERR = 0
        CALL SPAWN ('ln -s -f ../s.res asym.ins', 0, .true., KERR)
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -l asym.ins > asym.log',
     1    0, .true., KERR)
      ELSE
        OPEN (LU61, FILE = 'asym.ins', STATUS = 'UNKNOWN')
        WRITE (LU61, 99998, IOSTAT = IOST)
     1    TITL, ((TM(I, J), J = 1, 3), I = 1, 3),
     2    SPAR(80), (SPAR(80 + I), I = 1, 6), CHSPGR
        CLOSE (UNIT = LU61)
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' asym.ins > asym.log',
     1    0, .true., KERR)
      END IF
C * RETURN TO COMPOUND DIRECTORY
C *nERROR HANDLING
      IF (CHDIR(FNM(1:INZ - 1)) /= 0) CALL S925 (1)
   10 RETURN
99998 FORMAT ('TITL ', A, /,
     1        'TRMX ', 9F6.2, /,
     2        'CELL ', 7F10.4, /,
     3        'SPGR [', A, ']', /,
     4        'ASYM AVF')
      END SUBROUTINE S110
 
      SUBROUTINE S120
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: CHDIR
      CALL S915 ('Run Platon/ABSPSI')
C * LIST STATUS
      EXST = .FALSE.
C * CHECK FOR/CREATE-CHANGE TO ABSPSI SUB-DIRECTORY
      CALL S909 ('absp')
C * RE/LINK TO shelx.hkl
      INQUIRE (FILE = 'absp.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../hklf/shelx.hkl absp.hkl', 0, .true., KERR)
C * PREPARE AND RUN ABSPSI JOB
        OPEN (LU61, FILE = 'absp.ins', STATUS = 'UNKNOWN')
        WRITE (LU61, 99998, IOSTAT = IOST)
     1    TITL, SPAR(80), (SPAR(80 + I), I = 1, 6)
        CLOSE (UNIT = LU61)
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -o absp.ins > absp.log',
     1    0, .true., KERR)
C * CORRECTION RANGE
        OPEN (LU61, FILE = 'absp.log', STATUS = 'UNKNOWN')
   10   READ (LU61, 99999, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 20
        IF (LINE(1:6) == ':: MIN') THEN
          READ (LINE, 99997) SPAR(126)
        ELSE IF (LINE(1:6) == ':: MAX') THEN
          READ (LINE, 99997) SPAR(127)
          GO TO 20
        END IF
        GO TO 10
   20   CLOSE (UNIT = LU61)
      ELSE
        SPAR(151) = SPAR(152)
      END IF
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      CPR(202) = 'ABSPSI    '
      CPR(105) = 'ABSPSI    '
      CPR(106) = CPR(200)
C * REGISTER ABSPSI
      ISPR(14) = 2
      ISPR(15) = 2
C * SAVE DATABASE & RELINK
      CALL S924 (1)
      RETURN
99999 FORMAT (A)
99998 FORMAT ('TITL ', A, /,
     1        'CELL ', 7F10.4, /,
     2        'SET DISPLAY OFF', /,
     3        'ABSPSI')
99997 FORMAT (22X, F8.0)
      END SUBROUTINE S120
 
      SUBROUTINE S130
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: CHDIR
      REAL :: RADIUS
C * CHECK/CREATE-CHANGE TO MULABS DIRECTORY
      CALL S909 ('tm/sg/mulabs')
C * AUTOMATIC MULABS - PROCEDURE SEQUENCE
C * CREATE LINK TO s.hkl
      KERR = 0
      CALL SPAWN ('ln -s -f '//'../../../hklf/shelx.hkl s.hkl',
     1  0, .true., KERR)
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.res s.res', 0, .true., KERR)
C * PREPARE PLATON /MULABS
      OPEN (LU61, FILE = 'mulabs.ins', STATUS = 'UNKNOWN')
      RADIUS = (SPAR(11) * SPAR(12) * SPAR(13)) ** 0.33333
      IF (RADIUS < 0.0001) RADIUS = 0.3
      WRITE (LU61, 99997, IOSTAT = IOST) SPAR(123), RADIUS
      CLOSE (UNIT = LU61)
      KERR = 0
      CALL SPAWN
     1    (PLAPATH(1:IGBL(80))//' -o s.res < mulabs.ins > mulabs.log',
     2     0, .true., KERR)
      KERR = 0
      CALL SPAWN ('mv s.lis mulabs.lis', 0, .true., KERR)
C * CORRECTION RANGE
      OPEN (LU61, FILE = 'mulabs.log', STATUS = 'UNKNOWN')
      DO
        READ (LU61, 99999, IOSTAT = IOST) LINE
        IF (IOST == -1) EXIT
        IF (LINE(1:6) == ':: MIN') THEN
          READ (LINE, 99998) SPAR(126)
        ELSE IF (LINE(1:6) == ':: MAX') THEN
          READ (LINE, 99998) SPAR(127)
          EXIT
        END IF
      END DO
      CLOSE (UNIT = LU61)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * REGISTER MULABS
      ISPR(14) = 3
      ISPR(15) = 3
C * REGISTER MULABS
      CPR(202) = 'MULABS    '
      ISPR(5)  = ISPR(6)
      ISPR(7)  = 0
C * NEXT
      CPR(105) = 'MULABS'
      CPR(106) = CPR(200)
C * SAVE DATABASE
      CALL S924 (1)
      CALL S915 ('Run PLATON/MULABS')
      RETURN
99999 FORMAT (A)
99998 FORMAT (22X, F8.0)
99997 FORMAT ('MULABS', 2F10.3)
      END SUBROUTINE S130
 
      SUBROUTINE S140
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      LOGICAL :: DINQ
      INTEGER :: I
      INTEGER :: J
      INTEGER :: CHDIR
      EXST = .FALSE.
      CALL S915 ('Run PLATON/ABSGAUSS')
      CALL S929 (-1)
      IF (ISPR(350) == 0) THEN
        WRITE (LU6, 99995, IOSTAT = IOST)
        GO TO 10
      END IF
C * CHECK FOR/CREATE ABSGAUSS-DIR UNDER /USER/S/COMPOUNDNAME
      IF (.NOT. DINQ (FNM(1:INZ)//'absgauss')) THEN
        CALL SPAWN ('mkdir '//FNM(1:INZ)//'absgauss', 0, .true., KERR)
      END IF
C * CHANGE TO absgauss sub-DIRECTORY
C * LINKS
      INQUIRE (FILE = 'absgauss.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        CALL SPAWN ('ln -s ../hklf/shelx.hkl absgauss.hkl', 0, .true.,
     1    KERR)
      END IF
C * PREPARE AND RUN ABSGAUSS JOB
      OPEN (LU61, FILE = 'absgauss.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99998, IOSTAT = IOST) TITL, (SPAR(80 + I), I = 1, 6)
      DO I = 1, ISPR(350)
        WRITE (LU61, 99997, IOSTAT = IOST) (FACE(I, J), J = 1, 4)
      END DO
      WRITE (LU61, 99996, IOSTAT = IOST) SPAR(123)
      CLOSE (UNIT = LU61)
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' absgauss.ins > absgauss.log',
     1  0, .true., KERR)
C * new link
      KERR = 0
      CALL SPAWN ('rm -f ../hklf/shelx.hkl', 0, .true., KERR)
      KERR = 0
      CALL SPAWN ('ln -s ../absgauss/absgauss.hkp ../hklf/shelx.hkl',
     1  0, .true., KERR)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * MERGE AND SETUP NEW BIN-FILE
      CPR(202) = 'ABSGAUSS'
      CALL S924 (1)
   10 RETURN
99998 FORMAT ('TITL ', A, /,
     1        'CELL ', 3F10.4, 3F10.2)
99997 FORMAT ('FACE ', 3F5.0, F10.5)
99996 FORMAT ('ABSG', F10.2)
99995 FORMAT (':: No Crystal Description Available')
      END SUBROUTINE S140
 
      SUBROUTINE S150
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      LOGICAL :: DINQ
      INTEGER :: I
      INTEGER :: J
      INTEGER :: CHDIR
      EXST = .FALSE.
      CALL S915 ('Run PLATON/ABSTOMPA')
      CALL S929 (-1)
      IF (ISPR(350) == 0) THEN
        CALL PLA015 (0, 19)
        GO TO 20
      END IF
      IF (SPAR(81) == 0.0) THEN
        CALL PLA015 (0, 20)
        GO TO 20
      END IF
      IF (.NOT. DINQ (FNM(1:INZ)//'abst')) THEN
        CALL SPAWN ('mkdir '//FNM(1:INZ)//'abst', 0, .true., KERR)
      END IF
      IF (CHDIR (FNM(1:INZ)//'abst') /= 0) CALL S925 (1)
      INQUIRE (FILE = 'abst.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../hklf/shelx.hkl abst.hkl', 0, .true., KERR)
      END IF
      OPEN (LU61, FILE = 'abst.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99998, IOSTAT = IOST)
     1  TITL, SPAR(80), (SPAR(80 + I), I = 1, 6)
      DO I = 1, ISPR(350)
        WRITE (LU61, 99997, IOSTAT = IOST) (FACE(I, J), J = 1, 4)
      END DO
      WRITE (LU61, 99996, IOSTAT = IOST) SPAR(123)
      CLOSE (UNIT = LU61)
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' abst.ins > abst.log',
     1 0, .true., KERR)
      OPEN (LU61, FILE = 'abst.log', STATUS = 'UNKNOWN')
      DO
        READ (LU61, 99994, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 10
        IF (LINE(1:6) == ':: MIN') THEN
          READ (LINE, 99995) SPAR(126)
        ELSE IF (LINE(1:6) == ':: MAX') THEN
          READ (LINE, 99995) SPAR(127)
          GO TO 10
        END IF
      END DO
   10 CLOSE (UNIT = LU61)
C * REGISTER ABSTOMPA
      ISPR(14) = 5
      ISPR(15) = 5
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * MERGE AND SETUP NEW BIN-FILE
      CPR(202) = 'ABSTOMPA'
      CALL S924 (1)
   20 RETURN
99998 FORMAT ('TITL ', A, /,
     1        'CELL ', F10.5, 3F10.4, 3F10.2)
99997 FORMAT ('FACE ', 3F5.0, F10.5)
99996 FORMAT ('ABST', F10.2)
99995 FORMAT (22X, F8.0)
99994 FORMAT (A)
      END SUBROUTINE S150
 
