      SUBROUTINE S160
      USE files
      USE parameters
      USE ccom
      USE scom
      USE lplat
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: KNN
      INTEGER :: LRET0
      INTEGER :: CHDIR
      REAL :: CRAXL
      REAL :: CRMET
      CHARACTER(len=2) :: CTR
      LOGICAL :: DINQ
      EXST  = .FALSE.
      EXST1 = .FALSE.
C * RESET VALIDATION MODE
      IGBL(34)   = 0
      VALIDATION = ' '
      KNN   = 0
      IF (KN == 9) KNN = KN
C * SETUP latt SUBDIRECTORY
      IF (.NOT. DINQ ('latt')) THEN
        KERR = 0
        CALL SPAWN ('mkdir latt', 0, .true., KERR)
C * ERROR HANDLING
        IF (CHDIR ('latt') /= 0) CALL S925 (1)
        KERR = 0
        CALL SPAWN ('ln -s -f ../tm/s.hkl latt.hkl', 0, .true., KERR)
C * CREATE INPUT FOR LATTICE DETERMINATION VIA PLATON
        OPEN (LU61, FILE = 'latt.ins', STATUS = 'UNKNOWN')
        IF (IGBL(50) == 0) THEN
          CRMET = 0.4
          CRAXL = 0.4
        ELSE
          CRMET = 0.2
          CRAXL = 0.2
        END IF
        WRITE (LU61, 99999, IOSTAT = IOST)
     1    COMPD, SPAR(80), (SPAR(80 + I), I = 1, 6), CRMET, CRAXL
        CLOSE (UNIT = LU61)
C * RUN PLATON FOR TRMX
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' latt.ins > log', 0, .true.,
     1    KERR)
        KERR = 0
        CALL SPAWN ('rm log', 0, .true., KERR)
C * IMPORT/INTERPRETE PLATON ANALYSIS RESULTS
        OPEN (LU61, FILE = 'latt.trm', STATUS = 'UNKNOWN',
     1    FORM = 'UNFORMATTED')
        READ (LU61) NRLT0, NRLT, NREXT, AVIOS, RMAX,
     1        RVL, NTL, TLATT, XCELL, LLAUE, RVAL, CLATT, BLATT, ELATT
        CLOSE (UNIT = LU61)
C * ERROR HANDLING
        IF (CHDIR (FNM(1 : INZ - 1)) /= 0) CALL S925 (1)
      ELSE
C * RELINK s.dbf to default
        KERR = 0
        CALL SPAWN ('rm tm', 0, .true., KERR)
        KERR = 0
        CALL SPAWN ('ln -s 00 tm', 0, .true., KERR)
        CALL S920 (-1)
      END IF
C * LIST SELECTIONS
      LRET0 = 0
      OPEN (LU62, FILE = 'latt/latt.par', STATUS = 'UNKNOWN')
      OPEN (LU63, FILE = 'latt/trmx.lis', STATUS = 'UNKNOWN')
      CALL PLA432 (LRET0, TM, LU62, LU63, ISPR(47), SPAR, KNN)
      CLOSE (UNIT = LU62)
      CLOSE (UNIT = LU63)
      IF (LRET0 /= 1) THEN
C * SAVE STATUS & LAST CHOISE
        CALL S920 (1)
C * SAVE (NEW) TRANSFORMATION MATRIX FILE
        OPEN (LU61, FILE = 'latt/latt.trm', STATUS = 'UNKNOWN',
     1        FORM = 'UNFORMATTED')
        WRITE (LU61) NRLT0, NRLT, NREXT, AVIOS, RMAX,
     1         RVL, NTL, TLATT, XCELL, LLAUE, RVAL, CLATT, BLATT, ELATT
        CLOSE (UNIT = LU61)
        IF (NRLT > 9) THEN
          WRITE (CTR, 99998, IOSTAT = IOST) NRLT
        ELSE
          WRITE (CTR, 99997, IOSTAT = IOST) NRLT
        END IF
        CPR(104) = CTR//'/000/000'
C * CREATE SUBDIRECTORY FOR THIS TRANSFORMATION
        EXST1 = DINQ (CTR)
        IF (.NOT. EXST1) THEN
          KERR = 0
          CALL SPAWN ('mkdir '//CTR, 0, .true., KERR)
          CALL S915 ('Create Transformation Directory # tm = '//CTR)
        END IF
        CALL DLNK (CTR, 'tm')
        INQUIRE (FILE = '.newsym.nsg', EXIST = EXST)
        IF (EXST) THEN
          KERR = 0
          CALL SPAWN ('mv .newsym.nsg tm', 0, .true., KERR)
          KERR = 0
          CALL SPAWN ('mv .newsym.res tm', 0, .true., KERR)
          KERR = 0
          CALL SPAWN ('mv .newsym.sav tm', 0, .true., KERR)
        END IF
        IF (.NOT. EXST1) THEN
C * CREATE BASE SYMMETRY DIRECTORY
          CALL S932 (2)
          INQUIRE (FILE = 'tm/spgr', EXIST = EXST)
          EXST = DINQ ('tm/spgr')
          IF (.NOT. EXST) THEN
C * DEFAULT ACTIVE SPACEGROUP LIST
            DO I = 1, NP42
              CALL GEN038 (TSPGR(I), 1, 50)
            END DO
            KERR = 0
            CALL SPAWN ('mkdir tm/spgr', 0, .true., KERR)
            OPEN (LU61, FILE = './tm/spgr/.spgr', STATUS = 'UNKNOWN',
     1            FORM = 'UNFORMATTED')
            WRITE (LU61) TSPGR
            CLOSE (UNIT = LU61)
          END IF
C * GET CURRENT (TRANSFORMED) CELL
          DO I = 1, 9
            K = (I - 1) / 3 + 1
            J = MOD (I - 1, 3) + 1
            TM(K, J) = TLATT(I, NRLT)
          END DO
C * TRANSFORM CELL & SU
          CALL S931
        ELSE
          KERR = 0
          CALL SPAWN ('ln -s -f tm/.s.dbf .s.dbf', 0, .true., KERR)
          CALL S920 (-1)
        END IF
C * SET LEVEL TO TRMX - DIRECTORY
        ISPR(10) = 2
        IGBL(38) = 1
C * NEXT STEP
        CPR(105) = 'TRMX'
        CPR(106) = CPR(200)
      END IF
      RETURN
99999 FORMAT ('TITL ', A, /,
     1        'CELL', F9.5, 3F8.3, 3F8.2, /,
     2        'SET PAR 441', F10.2, /,
     3        'SET PAR 383', F10.2, /,
     4        'SET IPR 548 1', /,
     5        'SPGR 1')
99998 FORMAT (I2)
99997 FORMAT ('0', I1)
      END SUBROUTINE S160
 
 
      SUBROUTINE S170
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      USE lplat
      USE latice
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NX
      INTEGER :: JMN
      INTEGER :: JMX
      INTEGER :: IP1
      INTEGER :: KEXT
      INTEGER :: NEWSG
      INTEGER :: NAVER
      INTEGER :: IFREQ
      INTEGER :: IPCNT
      INTEGER :: ISGNR
      INTEGER :: JSGNR
      INTEGER :: ISPGR
      INTEGER :: ISPGRA
      INTEGER :: ISPGRC
      INTEGER :: ISPGRH
      INTEGER :: IPCNTC
      INTEGER :: CHDIR
      REAL :: ECRIT
      REAL :: RAVER
      REAL :: SAVEVRT
      REAL, DIMENSION(3, 3) :: YUNK
      CHARACTER(len=7)  :: DSPGR
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=5)  :: XCHIR
      CHARACTER(len=1)  :: CHIRAL
      LOGICAL :: DINQ
      EXST  = .FALSE.
      NEWSG = 0
C * RESET VALIDATION MODE
      IGBL(34)   = 0
      VALIDATION = ' '
C * MAKE DEFAULT LINKS FROM COMPOUND DIRECTORY
      CALL DLNK ('000', 'tm/sg')
C * GET CONTEXT
C * DETERMINE SPACE GROUP FROM shelx.hkl EXTINCTIONS
      INQUIRE (FILE = 'tm/spgr/spgr.par', EXIST = EXST)
      IF (KN > 0) THEN
        ECRIT = FN(1)
        IF (EXST) THEN
          KERR = 0
          CALL SPAWN ('rm tm/spgr/spgr.par', 0, .true., KERR)
          EXST = .FALSE.
        END IF
      ELSE
        ECRIT = 5.0
      END IF
      IF (.NOT. EXST) THEN
        CALL S915 ('Analyse Space Group Extinctions')
        IF (.NOT. DINQ ('tm/spgr')) THEN
          KERR = 0
          CALL SPAWN ('mkdir tm/spgr', 0, .true., KERR)
        ENDIF
C * ERROR HANDLING
        IF (CHDIR ('tm/spgr') /= 0) CALL S925 (1)
        KERR = 0
        CALL SPAWN ('ln -s -f ../s.hkl spgr.hkl', 0, .true., KERR)
C * PREPARE INPUT FILE FOR PLATON/SPGR
        OPEN  (LU61, FILE = 'spgr.ins', STATUS = 'UNKNOWN')
        WRITE (LU61, 99990, IOSTAT = IOST) COMPD
        WRITE (LU61, 99989, IOSTAT = IOST) (TLATT(J, NRLT), J = 1, 9),
     1   CLATT(NRLT), BLATT(NRLT), LLAUE(NRLT), ELATT(NRLT)
        WRITE (LU61, 99988, IOSTAT = IOST)
     1    SPAR(80), (SPAR(80 + I), I = 1, 6), ECRIT
        CLOSE (UNIT = LU61)
C * RUN PLATON/SPGR JOB
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' spgr.ins > log', 0, .true.,
     1    KERR)
        KERR = 0
        CALL SPAWN ('rm log', 0, .true., KERR)
C * ERROR HANDLING
        IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      END IF
      JSGNR = 230
      DO J = 231, NP42
        IF (TSPGR(J)(1:2) /= '  ') JSGNR = J
      END DO
      GO TO 40
C * SAVE TSPGR as a FILE .spgr
   20 OPEN (LU61, FILE = './tm/spgr/.spgr', STATUS = 'UNKNOWN',
     1      FORM = 'UNFORMATTED')
      WRITE (LU61) TSPGR
      CLOSE (UNIT = LU61)
C * (RE)LOAD TO DEFAULT s-database / READ DEFAULT DATABASE
   30 CALL S920 (-1)
   40 NSPGR = 0
      ISPGR = 0
      ISGNR = 0
      JSGNR = 230
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      IF (IGBL(50) == 0) CALL GGIP (HORS, VERT, 0.0, 1)
C * COPY/INTERPRET SPACEGROUP NAME (WHEN GIVEN)
      IF (KL > 1) THEN
        CALL GEN020 (1, LINE, 1, 80)
        NX = INDEX (LINE, ':')
        IF (NX == 0) THEN
          CPR(2) = ' '
          J      = 0
          DO I = 6, 20
            IF (LINE(I:I) /= ' ' .AND. J < 10) THEN
              J = J + 1
              CPR(2)(J:J) = LINE(I:I)
            END IF
          END DO
          JFL(2) = 'ABC  '
          NX     = 13
        ELSE
          CPR(2) = LINE(6:NX - 1)
          JFL(2) = LINE(NX+1:NX+5)
        END IF
        CALL GEN038 (LINE, NX, 80)
        CALL GEN020 (-1, CPR(2), 2, 9)
C * GET SPGR-NUMBER
        CALL SGSM (0, LINE, SGX, 0, 0, IERR)
        IF (IERR == 0) THEN
          CALL SGSM (18, LINE, SGX, 0, 0, IERR)
          ISGNR = NINT(SGX(1))
        END IF
C * CHECK FOR ACCEPTABLE SPACEGROUP
        IF (ISGNR == 0) THEN
          CALL PLA015 (0, 22)
        ELSE
          TSPGR(JSGNR + 1)(1:14) = CPR(2)(1:8)//':'//JFL(2)(1:5)
          IF (TSPGR(ISGNR)(1:2) == '  ') THEN
            TSPGR(ISGNR) = TSPGR(JSGNR + 1)(1:14)
            CALL GEN038 (TSPGR(JSGNR + 1), 1, 50)
          ELSE
            DO K = 1, JSGNR
              IF (TSPGR(JSGNR + 1)(1:14) == TSPGR(K)(1:14)) THEN
                ISGNR = K
                CALL GEN038 (TSPGR(JSGNR + 1), 1, 50)
                GO TO 70
              END IF
            END DO
            JSGNR = JSGNR + 1
          END IF
        END IF
   70   KL    = 1
        ISPGR = ISGNR
        IF (ISPGR == 0) GO TO 20
        GO TO 180
      END IF
C * TEST FOR PRECEDING HELENA RUN
      IF (ISPGR == 0) THEN
C * GET CANDIDATE SPACE GROUPS FROM FILE SPGR.PAR
        OPEN (LU61, FILE = 'tm/spgr/spgr.par', STATUS = 'OLD')
        KEXT = 0
        VRT  = 17.0
   80   READ (LU61, 99996, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 110
C * GET TRANSFORMATION MATRIX
        IF (LINE(1:4) == 'TRMX') THEN
          CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10,
     1                 NP17)
          TM(1, 1) = FN(1)
          TM(1, 2) = FN(2)
          TM(1, 3) = FN(3)
          TM(2, 1) = FN(4)
          TM(2, 2) = FN(5)
          TM(2, 3) = FN(6)
          TM(3, 1) = FN(7)
          TM(3, 2) = FN(8)
          TM(3, 3) = FN(9)
C * GET/REPORT SYSTEMATIC ABSENCES
        ELSE IF (LINE(1:4) == 'EXTI') THEN
          KEXT = KEXT + 1
          IF (IGBL(50) == 0) THEN
            IF (KEXT == 1) THEN
              LIJN =
     1         'Extinction Statistics for (transformed) Reflection file'
              CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.1, 18.8)
              CALL GGIP (0.0, 18.5, 0.0, 3)
              CALL GGIP (HORS, 18.5, 0.0, 2)
              LIJN = '    Ex. Condition    av[I/sig(I)]  Number of '//
     1               'Refl I/sigI             .T./.F.'
              CALL PLA439 (0.0, LIJN, 80, 0.35, 5 + IGBL(68), 2,
     1                     0.1, 18.0)
              LIJN = '                    .True. .False. .True. '//
     1               '.False.  Max.F    H  K  L   Ratio'
              CALL PLA439 (0.0, LIJN, 80, 0.35, 5 + IGBL(68), 2,
     1                     0.1, 17.5)
              CALL GGIP (0.0,  17.2, 0.0, 3)
              CALL GGIP (HORS, 17.2, 0.0, 2)
            END IF
            VRT = VRT - 0.45
            WRITE (LIJN, 99996, IOSTAT = IOST) LINE(6:80)
            CALL PLA439 (0.0, LIJN, 80, 0.375, 1, 2, 0.1, VRT)
          END IF
C * GET COMPATIBLE SPACE GROUPS
        ELSE IF (LINE(1:4) == 'SPGR') THEN
          NSPGR = NSPGR + 1
          READ (LINE, 99999) IP1, IP1, IP1, DSPGR, ISGNR, IFREQ,
     1      TSPGR(JSGNR + 1)(1:14), RAVER, NAVER, IP1, CHIRAL
          IPCNT = IP1
          IF (TSPGR(ISGNR)(1:2) == '  ') THEN
            TSPGR(ISGNR) = TSPGR(JSGNR + 1)(1:14)
            CALL GEN038 (TSPGR(JSGNR + 1), 1, 50)
          ELSE
            DO K = 1, JSGNR
              IF (TSPGR(JSGNR + 1)(1:14) == TSPGR(K)(1:14)) THEN
                ISGNR = K
                CALL GEN038 (TSPGR(JSGNR + 1), 1, 50)
                GO TO 100
              END IF
            END DO
            JSGNR = JSGNR + 1
            ISGNR = JSGNR
          END IF
  100     WRITE (TSPGR(ISGNR)(16:24), '(''= '', A)', IOSTAT = IOST)
     1      DSPGR
          WRITE (TSPGR(ISGNR)(25:30), '(F6.2)', IOSTAT = IOST) RAVER
          WRITE (TSPGR(ISGNR)(31:36), '(I6)', IOSTAT = IOST)   NAVER
          WRITE (TSPGR(ISGNR)(37:42), '(I6)', IOSTAT = IOST)   IFREQ
          WRITE (TSPGR(ISGNR)(43:46), '(I4)', IOSTAT = IOST)   IPCNT
          IF (CHIRAL == 'C') THEN
            WRITE (TSPGR(ISGNR)(47:48), '('' c'')', IOSTAT = IOST)
          END IF
          IF (DSPGR(1:3) == 'Pn ' .OR.
     1        DSPGR(1:5) == 'P2/n ' .OR.
     2        DSPGR(1:6) == 'P21/n ') THEN
            JSGNR              = JSGNR + 1
            TSPGR(JSGNR)       = TSPGR(ISGNR)
            TSPGR(JSGNR)(1:14) = DSPGR//' :ABC'
          END IF
          IF (NSPGR == 1) ISPGR = ISGNR
C * GET PROPOSED SPACE GROUP NUMBER
        ELSE IF (LINE(1:4) == 'SGNR') THEN
          READ (LINE, 99998) ISPGRC, ISPGRA, ISPGRH, IPCNTC
        END IF
        GO TO 80
  110   CLOSE (UNIT = LU61)
C * TEST FOR 'CHIRAL' CHIRAL => ISPR(8) = 1
        IF (ISPR(8) == 0) THEN
          IF (ISPGRC /= 0) THEN
            IF (IPCNTC > 45 .OR. NSPGR == 1) THEN
              ISPGR = ISPGRC
            ELSE
              ISPGR = ISPGRA
            END IF
          ELSE IF (ISPGRA /= 0) THEN
            ISPGR = ISPGRA
          ELSE
            ISPGR = 0
          END IF
C * FORCE CHIRAL
        ELSE
          ISPGR = ISPGRH
        END IF
C * HANDLE CASES WHERE SPACE GROUP ROUTINE HAS DIFFICULTIES
        IF (NSPGR == 0) THEN
          CALL PLA015 (0, 25)
          IGBL(50) = 0
        END IF
      END IF
C * GET SPACE GROUP
C * CHECK FOR SPECIAL TRANSFER PATH (ADDSYM OR FRIEDEL)
      INQUIRE (FILE = 'tm/.newsym.nsg', EXIST = EXST)
      IF (EXST) THEN
        OPEN (LU61, FILE = 'tm/.newsym.nsg', STATUS = 'UNKNOWN')
        READ (LU61, 99996) LINE
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
        LINE(13:16) = ':ABC'
        NEWSG = 1
        KL    = 2
        GO TO 30
      END IF
      SAVEVRT = VRT
  120 IF (IGBL(50) == 0 .AND. NEWSG == 0) THEN
        VRT = SAVEVRT
        N = 0
        DO I = 1, NP42
          IF (TSPGR(I)(1:1) /= ' ') THEN
            CALL S923 (CPR(104), 2, I)
            EXST = DINQ ('tm/'//CPR(104)(4:6))
            N = N + 1
            IF (N == 1) THEN
              LIJN = 'Candidate Space Groups '//
     1               ' (defined already by number)'
              VRT = VRT - 1
              CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.1, VRT)
              VRT = VRT - 0.3
              CALL GGIP (0.0, VRT, 0.0, 3)
              CALL GGIP (HORS, VRT, 0.0, 2)
              LIJN = ' #  E StdSet  :Transf  '//
     1        'SpGr    R(av)%  N AbsFreq  A/C-Prob'
              VRT = VRT - 0.5
              CALL PLA439 (0.0, LIJN, 80, 0.375, 5 + IGBL(68), 2,
     1                     0.1, VRT)
              VRT = VRT - 0.3
              CALL GGIP (0.0,  VRT, 0.0, 3)
              CALL GGIP (HORS, VRT, 0.0, 2)
              PAR(360) = VRT
              PAR(361) = 0.5
            END IF
            IF (TSPGR(I)(48:48) == 'c') THEN
              XCHIR = 'hiral'
            ELSE
              XCHIR = '     '
            END IF
            IF (EXST) THEN
              WRITE (LIJN, 99995, IOSTAT = IOST)
     1          I, '*', TSPGR(I)(1:48)//XCHIR
            ELSE
              WRITE (LIJN, 99995, IOSTAT = IOST)
     1          I, ' ', TSPGR(I)(1:48)//XCHIR
            END IF
            VRT = VRT - 0.5
            CALL PLA439 (0.0, LIJN, 80, 0.375, -1, 2, 0.1, VRT)
          END IF
        END DO
C * SELECT
  140   WRITE (SBCD, 99992, IOSTAT = IOST) ISPGR, CHAR (0)
        IGBL(28) = 2
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IGBL(28) = 0
C * REFRESH
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
          KL = 1
          GO TO 20
        END IF
        IF (IGGT(1:4) == 'EXIT') GO TO 220
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          WRITE (LINE, '(I3, 77X)', IOSTAT = IOST) ISPGR
        END IF
        CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
C * EXPLICIT NUMBER GIVEN
        IF (KL == 0 .AND. KN /= 0) THEN
          ISGNR = NINT (FN(1))
C * TRANSLATE 'CLICK-# INTO SGNR
          IF (ISGNR < 0) THEN
            M     = 0
            ISGNR = - ISGNR
            DO I = 1, NP42
              IF (TSPGR(I)(1:1) /= ' ') THEN
                M = M + 1
                IF (M == ISGNR) THEN
                  ISGNR = I
                  GO TO 160
                END IF
              END IF
            END DO
            ISGNR = 0
          END IF
C * CHECK AGAINST ACCEPTABLE RANGE
  160     IF (ISGNR == 0 .OR. ABS (ISGNR) > NP42) THEN
            CALL PLA015 (0, 23)
            GO TO 140
          END IF
          IF (TSPGR(ISGNR) == '               ') GO TO 140
          ISPGR = ISGNR
        END IF
C * HANDLE EXPLICIT SPACEGROUP SPECIFICATION
        IF (KL /= 0) THEN
C * REMOVE 'SPGR'
          JFL(3) = LINE(1:4)
          CALL GEN020 (1, JFL(3), 1, 4)
          IF (JFL(3)(1:4) == 'SPGR') THEN
            JMN = 5
          ELSE
            JMN = 1
          END IF
          NX = INDEX (LINE, ':')
          IF (NX == 0) THEN
            JMX = 9 + JMN
            JFL(2) = 'ABC  '
          ELSE
            JMX = NX - 1
            JFL(2) = LINE(NX+1:NX+5)
          END IF
          JFL(1) = ' '
          J      = 0
          DO I = JMN, JMX
            IF (LINE(I:I) /= ' ') THEN
              J           = J + 1
              JFL(1)(J:J) = LINE(I:I)
            END IF
          END DO
          LINE(1:18)  = 'SPGR '//JFL(1)(1:J)//':'//JFL(2)(1:5)
          KL = 2
          GO TO 20
        END IF
      END IF
  180 CPR(100) = TSPGR(ISPGR)(1:7)//'   '
C * HANDLE ADDITIONAL NON-STANDARD TO STANDARD CELL TRANSFORMATION
      DO I = 2, 8
        IF (TSPGR(ISPGR)(10:14) == TRTYP(I))  GO TO 200
      END DO
      GO TO 210
C * MULTIPLY MATRICES
  200 CALL GEN004 (TRDAT(1, 1, I), TM, YUNK)
      CALL GEN052 (YUNK, TM)
  210 LINE(1:20) = 'SPGR '//CPR(100)
      CALL GEN038 (LINE, 16, 80)
      CALL SGSM (0,  LINE, SGX, 0, 6, IERR)
      IF (IERR /= 0) GO TO 120
      CALL SGSM (18, LINE, SGX, 0, 0, IERR)
      ISPR(102) = NINT (SGX(9))
C * CREATE LINK TO tm/sg_SUBDIR-NAME
      CALL S923 (CPR(104), 2, ISPGR)
      CALL DLNK (CPR(104)(4:6), 'tm/sg')
C * SAVE TSPGR as a FILE .spgr
      OPEN (LU61, FILE = './tm/spgr/.spgr', STATUS = 'UNKNOWN',
     1      FORM = 'UNFORMATTED')
      WRITE (LU61) TSPGR
      CLOSE (UNIT = LU61)
C * TEST/CREATE SPGR SPECIFIC DIRECTORY
      IF (.NOT. DINQ ('tm/'//CPR(104)(4:6))) THEN
        ISPR(11) = 3
        KERR = 0
        CALL SPAWN ('mkdir tm/'//CPR(104)(4:6), 0, .true., KERR)
        CALL S915 ('Select Space Group # sg = '//CPR(104)(4:6))
C * CREATE PARAMETER DIRECTORIES
        CALL S932 (3)
        OPEN (LU61, FILE = 'tm/'//CPR(104)(4:6)//'/.save_nr',
     1      STATUS = 'UNKNOWN')
        WRITE (LU61, '(I3)', IOSTAT = IOST) 0
        CLOSE (UNIT = LU61)
C * (RE-INIT FLACK)
        SPAR(225) = -1000.0
        ISPR(310) = 0
        ISPR(6)   = -1
C * RESET OUTLIER #
        ISPR(223) = 0
        IGBL(107) = 0
C * RESET 'VALIDATION'
        VALIDATION = ' '
      ELSE
C * (RE)READ DATA-BASE AND RESUME IN SAVED CONTEXT
        CALL S920 (-1)
        GO TO 220
      END IF
      CALL SGSM (18, LINE, SGX, 0, 0, IERR)
      CPR(103)  = LINE(12:21)
      ISPR(100) = NINT (SGX(8))
      ISPR(101) = NINT (SGX(4))
      ISPR(103) = NINT (SGX(5))
      ISPR(104) = NINT (SGX(6))
      ISPR(105) = NINT (SGX(2))
      CPR(101)  = LINE(15:24)
C * STORE LOWER-CASE SPACEGROUP NAME
      CPR(102) = CPR(101)
      CALL GEN020 (-1, CPR(102), 1, 10)
C * TRANSFORM CELL & ESD
      CALL S931
      IF (NEWSG == 1) THEN
        CPR(209) = 'ADDSYM    '
        KERR = 0
        CALL SPAWN ('mv tm/.newsym.res tm/sg/.newsym.res', 0,
     1    .true., KERR)
        KERR = 0
        CALL SPAWN ('mv tm/.newsym.sav tm/sg/.newsym.sav', 0,
     1    .true., KERR)
      END IF
      IGBL(38) = 1
C * REGISTER SPGR SELECTED
      ISPR(3) = 1
C * SET LEVEL TO SPGR SUBDIRECTORY
      ISPR(10) = 3
C * NEXT INSTRUCTION
  220 CPR(105) = 'SPGR'
      CPR(106) = CPR(200)
      RETURN
99999 FORMAT (5X, 3I2, 1X, A, I4, I6, 2X, A, F8.0, I6, I5, 2(1X, A))
99998 FORMAT (4X, 6I5)
99996 FORMAT (A)
99995 FORMAT (I3, 1X, A, 1X, A)
99992 FORMAT ('CLICK/ENTER StdSet:Transf, SpGr-name or SPGR number ',
     1         '(when defined above)[', I3, ']:', A)
99990 FORMAT ('TITL ', A)
99989 FORMAT ('TRMX', 9F7.4, 1X, A, A, I3, 1X, A)
99988 FORMAT ('CELL ', F8.4, 3F8.3, 3F8.2, /,
     1        'SET IPR 548 1', /,
     2        'SPGR 2', F10.1 )
      END SUBROUTINE S170
 
      SUBROUTINE S175
      USE files
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IER
      CHARACTER(len=6)  :: XSPGR
      CHARACTER(len=80) :: LINE
      CHARACTER(len=6), DIMENSION(22) :: ESPGR
      ESPGR = (/
     1 'P41   ', 'P43   ', 'P4122 ', 'P4322 ',
     2 'P41212', 'P43212', 'P31   ', 'P32   ', 'P3121 ', 'P3221 ',
     3 'P3112 ', 'P3212 ', 'P61   ', 'P65   ', 'P62   ', 'P64   ',
     4 'P6122 ', 'P6522 ', 'P6222 ', 'P6422 ', 'P4132 ', 'P4332 '/)
      IF (ISPR(103) == 1) THEN
        IER = 0
        CALL S929 (-1)
        XSPGR = CPR(100)(1:6)
C * DO NOT INVERT FOR ENANTIOMERIC SPACEGROUPS
        DO I = 1, 22
          IF (XSPGR == ESPGR(I)) THEN
            J = I + 1 - 2 * MOD (I + 1, 2)
            CALL PLA015 (0, 21)
            OPEN (LU61, FILE = 'tm/.newsym.nsg', STATUS = 'UNKNOWN')
            WRITE (LU61, 99999, IOSTAT = IOST) ESPGR(J)
            CLOSE (UNIT = LU61)
            OPEN (LU61, FILE = 's.res',      STATUS = 'UNKNOWN')
            OPEN (LU62, FILE = '.newsym.res', STATUS = 'UNKNOWN')
   10       READ (LU61, 99997, IOSTAT = IOST) LINE
            IF (IOST == -1) GO TO 20
            IF (LINE(1:4) == 'LATT') THEN
              WRITE (LU62, 99998, IOSTAT = IOST) ESPGR(J)
            ELSE IF (LINE(1:4) /= 'SYMM') THEN
              WRITE (LU62, 99997, IOSTAT = IOST) LINE
            END IF
            GO TO 10
   20       CLOSE (UNIT = LU61)
            CLOSE (UNIT = LU62)
            KERR = 0
            CALL SPAWN ('mv .newsym.res tm/.newsym.res', 0,
     1        .true., KERR)
            CALL S170
            CALL S180 (1)
            CALL S190 (1, IER)
            GO TO 30
          END IF
        END DO
        SPAR(225) =  1.0 - SPAR(225)
        SPAR(160) =  1.0
        SPAR(161) =  1.0
        SPAR(162) =  1.0
        SPAR(163) = -1.0
        ISPR(91)  = MOD (ISPR(91) + 1, 2)
        SELECT CASE (XSPGR)
          CASE ('Fdd2  ')
            SPAR(160) = 0.25
            SPAR(161) = 0.25
          CASE ('I41   ')
            SPAR(161) = 0.5
          CASE ('I4122 ')
            SPAR(161) = 0.5
            SPAR(162) = 0.25
          CASE ('I41md ')
            SPAR(161) = 0.5
          CASE ('I41cd ')
            SPAR(161) = 0.5
          CASE ('I-42d ')
            SPAR(161) = 0.5
            SPAR(162) = 0.25
          CASE ('F4132 ')
            SPAR(160) = 0.25
            SPAR(161) = 0.25
            SPAR(162) = 0.25
        END SELECT
        CALL S929 (1)
      END IF
   30 RETURN
99999 FORMAT ('SPGR ', A)
99998 FORMAT ('SPGR ', A, ' 1 1 1 -1')
99997 FORMAT (A)
      END SUBROUTINE S175
 
      SUBROUTINE S180 (MODE)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: NB
      INTEGER :: KM
      INTEGER :: ID0
      INTEGER :: NSC
      INTEGER :: MODE
      INTEGER :: NSCAT
      INTEGER :: NLOOP
      INTEGER :: NEWCONT
      CHARACTER(len=80) :: DUM
      EXST = .FALSE.
      IF (ISPR(3) == 0) CALL S170
      NEWCONT = 0
      IF (MODE == 0) THEN
        IGBL(6) = 17
C * GET COMMAND LINE ARGUMENT FORMULA (IF ANY)
        IF (ISPR(110) == 0) THEN
          IF ((JARG - JARGB) > 1) THEN
            L = 0
            CALL GEN038 (LINE, 1, 80)
            DO 10 J = 2 + JARGB, JARG
              CALL GET_COMMAND_ARGUMENT (J, DUM)
              CALL GEN020 (1, DUM, 1, 80)
              IF (DUM(1:3) == 'NQA' .OR. DUM(1:4) == 'AUTO')
     1          GO TO 10
              DO K = 1, 80
                IF (DUM(K:K) == ' ') GO TO 10
                L = L + 1
                LINE(L:L) = DUM(K:K)
              END DO
   10       CONTINUE
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 0, 10,
     1                   NP17)
            JARG      = 1
            ISPR(110) = KL
            NEWCONT   = 1
          END IF
        END IF
C * FORMULA LINE
        IF (JFL(1)(1:7) == 'FORMULA') THEN
          IF (KL > 1) THEN
            DO I = 2, KL
              JFL(I - 1) = JFL(I)
            END DO
            KL       = KL - 1
            NEWCONT  = 1
            CALL GEN020 (1, LINE, 1, 80)
C * REMOVE 'FORMULA' FROM LINE AND SHIFT CONTENT
            IF (LINE(1:4) == 'FORM') THEN
              DO I = 1, 80
                IF (LINE(I:I) == ' ') GO TO 20
              END DO
   20         I = I + 1
              DO J = I, 80
                IF (LINE(J:J) /= ' ') GO TO 30
              END DO
   30         I = 0
              DO K = J, 80
                I = I + 1
                LINE(I:I) = LINE(K:K)
              END DO
              I = I + 1
              CALL GEN038 (LINE, I, 80)
            END IF
          ELSE
            KL = 0
            NEWCONT = 0
          END IF
          ISPR(110) = KL
        END IF
      END IF
C * GET FORMULA C10 H12 or C10H12
      IF (ISPR(110) <= 0) THEN
        IF (ISPR(110) == 0) THEN
          INQUIRE (FILE = '.formula', EXIST = EXST)
          IF (EXST) THEN
   40       OPEN (LU61, FILE = '.formula', STATUS = 'UNKNOWN')
            READ (LU61, '(A)') LINE
            CLOSE (UNIT = LU61)
            DO I = 1, 80
              IF (LINE(81 - I:81 - I) /= ' ') GO TO 50
            END DO
            CALL GEN038 (LINE, 82 - I, 80)
   50       IF (IGBL(50) == 0 .AND. MODE == 0) THEN
              WRITE (SBCD, 99999, IOSTAT = IOST)
     1          LINE(1:81 - I), CHAR (0)
C * WHAT NEXT ?
              CALL PLA012 (0, 1)
              IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
                CALL S040
                GO TO 40
              END IF
              IF (IGGT(1:4) == 'EXIT') GO TO 100
              IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
                LINE = IGGT
                CALL GEN038 (IGGT, 1, 80)
              END IF
            ELSE
              KL = 0
            END IF
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 0, 10,
     1                   NP17)
C * MANIPULATE THE CHEMICAL FORMULA
            CALL GEN111 (JFL(1), DUM(1:2), 7, M)
 
            IF (M == 0) THEN
              BCD = 'Syntax Error in Formula. Try again'//CHAR (0)
              CALL GGIP (-999.0, 2.0, 80.0, 112)
              GO TO 40
            END IF
          ELSE
   60       WRITE (SBCD, 99999, IOSTAT = IOST) 'C1H2', CHAR (0)
            IGBL(50) = 0
            CALL GEN038 (LINE, 1, 80)
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
            IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
              CALL S040
              GO TO 60
            END IF
            IF (IGGT(1:4) == 'EXIT') GO TO 100
            IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
              LINE = IGGT
              CALL GEN038 (IGGT, 1, 80)
            END IF
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 0, 10,
     1                   NP17)
          END IF
        ELSE
C * ASK FOR NEW CONTENT (I.E. UPDATED FORMULA)
          KM = IABS (ISPR(110))
          WRITE (BCD, 99998, IOSTAT = IOST)
     1      (SFAC(I), I = 1, KM), CHAR (0)
          CALL GGIP (-999.0, 3.0, 80.0, 112)
          CALL GEN039 (1, LINE, 1, 80, NB, ID0)
          NLOOP = 0
          DUM   = LINE
   70     NLOOP = NLOOP + 1
          WRITE (SBCD, 99999, IOSTAT = IOST) LINE(1:ID0), CHAR (0)
          IF (IGBL(50) > 0) THEN
            IGGT = '!'
          ELSE
C * WHAT NEXT ?
            CALL PLA012 (0, 1)
          END IF
C * CHECK FOR REFRESH
          IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
            CALL S040
            GO TO 70
          END IF
          IF (IGGT(1:4) == 'EXIT') GO TO 100
          IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
            LINE = IGGT
            CALL GEN038 (IGGT, 1, 80)
          END IF
          CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 0, 10, NP17)
          IF (KL > 0 .AND. KN == 0) THEN
C * MANIPULATE THE CHEMICAL FORMULA
            CALL GEN111 (JFL(1), DUM(1:2), 7, M)
            IF (M == 0) THEN
              LINE  = DUM
              NLOOP = NLOOP - 1
              GO TO 70
            END IF
          END IF
          IF (KL == KM .AND. KL == KN) THEN
            J = 0
            DO I = 1, KL
              IF (FN(I) > 0) THEN
                J      = J + 1
                FN(J)  = FN(I)
                JFL(J) = JFL(I)
              END IF
            END DO
            KL = J
            KM = J
          END IF
          IF (KL < KM) THEN
            CALL PLA015 (0, 26)
            IF (NLOOP == 1) GO TO 70
          END IF
        END IF
        IF (KL == 0) THEN
          KL     = 2
          JFL(1) = 'C1'
          JFL(2) = 'H2'
          LINE   = 'C1H2'
        END IF
        ISPR(110) = KL
        NEWCONT   = 1
      END IF
      IF (NEWCONT > 0) THEN
C * SAVE FORMULA
        OPEN (LU61, FILE = '.formula', STATUS = 'UNKNOWN')
        WRITE (LU61, 99994, IOSTAT = IOST) LINE
        CLOSE (UNIT = LU61)
C * PARSE FORMULA
        SPAR(3)   = 0
        ISPR(96)  = 0
        ISPR(111) = 0
        ISPR(112) = 0
        NSCAT     = ISPR(110)
        NSC       = 1
        IGBL(97) = 0
        DO I = 1, NSCAT
          SFAC(NSC)       = '  '
          ISPR(152 + NSC) = 0
C * MANIPULATE THE CHEMICAL FORMULA
          CALL GEN111 (JFL(I), SFC(NSC), 7, ISPR(NSC + 120))
          IF (ISPR(NSC + 120) /= 1) ISPR(96) = ISPR(96) + 1
C * HANDLE D AS H
          IF (SFC(NSC) == 'D ') SFC(NSC) = 'H '
C * REGISTER INORG/ORGANIC
          IF (SFC(NSC) == 'H ') IGBL(97) = 1
          ISPR(NSC + 120) = MAX (ISPR(NSC + 120), 1)
          IF (SFC(NSC) /= 'H ') THEN
            ISPR(111) = ISPR(111) + ISPR(NSC + 120)
          ELSE
            ISPR(112) = ISPR(112) + ISPR(NSC + 120)
          END IF
          SFAC(NSC)  = SFC(NSC)
C * HANDLE ELEMENT DUPLICATIONS
          IF (NSC > 1) THEN
            DO J = 1, NSC - 1
              IF (SFC(J) == SFC(NSC)) THEN
                ISPR(J + 120) = ISPR(J + 120) + ISPR(NSC + 120)
                GO TO 80
              END IF
            END DO
          END IF
          J   = NSC
          NSC = NSC + 1
   80     ISPR(J + 136) = ISPR(J + 120)
        END DO
        ISPR(110) = NSC - 1
C * GET SCATTERING FACTORS FOR SPECIFIED ELEMENTS (FUDGE WITH PLATON)
        OPEN (LU61, FILE = 'sfac.spf', STATUS = 'UNKNOWN')
        WRITE (LU61, 99997, IOSTAT = IOST) SPAR(80)
        DO I = 1, ISPR(110)
          WRITE (LU61, 99996, IOSTAT = IOST) SFAC(I), I * 0.01
        END DO
        WRITE (LU61, 99995, IOSTAT = IOST)
        CLOSE (UNIT = LU61)
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' sfac.spf > sfac.log',
     1    0, .true., KERR)
        OPEN (LU61, FILE = 'sfac_pl.res', STATUS = 'UNKNOWN')
        I = 0
   90   CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80, 10,
     1               NP17)
        IF (JFL(1)(1:4) == 'SFAC') THEN
          I = I + 1
          SFAC(I) = JFL(2)(1:2)
          DO J = 1, 14
            SPAR(235 + J + 15 * I) = FN(J)
          END DO
          J = 235 + 15 * I
          SPAR(15 + J) = SPAR(1 + J) + SPAR(3 + J) + SPAR(5 + J)
     1                + SPAR(7 + J) + SPAR(9 + J)
          SPAR(3) = MAX (SPAR(3), SPAR(15 + J))
          DO J = 1, ISPR(110)
            IF (SFAC(I) == SFC(J)) THEN
              ISPR(I + 136) = ISPR(J + 120)
              ISPR(J + 120) = 0
            END IF
          END DO
        END IF
        IF (LINE(1:4) /= 'UNIT') GO TO 90
        KERR = 0
        CALL SPAWN ('rm sfac.spf',    0, .true., KERR)
        KERR = 0
        CALL SPAWN ('rm sfac.log',    0, .true., KERR)
        CALL SPAWN ('rm sfac_pl.res', 0, .true., KERR)
        CALL SPAWN ('rm sfac.lis',    0, .true., KERR)
      END IF
C * DECIDE WHAT TO DO NEXT
      CPR(105) = 'FORMULA'
      CPR(106) = CPR(200)
      CALL S915 ('Define Formula')
  100 RETURN
99999 FORMAT ('Enter Formula (e.g. CU1C15H10) [', A, ']:', A)
99998 FORMAT ('New Formula:', 16(1X, A))
99997 FORMAT ('TITL SFAC', /,
     1       'CELL ', F10.5, ' 170.0 10.0 10.0 90.0 90.0 90.0')
99996 FORMAT (A, F10.3, ' 0.0 0.0')
99995 FORMAT ('SET IGBL 70 0', /, 'CALC SHELX', /, 'END')
99994 FORMAT (A)
      END SUBROUTINE S180
 
      SUBROUTINE S190 (MODE, IER)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: NQ
      INTEGER :: IER
      INTEGER :: MODE
      INTEGER :: IMAN
      REAL :: Z
      REAL :: AV
      REAL :: DENS
      REAL :: MOLWT
      REAL :: DENSMX
      REAL :: XATVOL
      IMAN = 0
      IER  = 0
      NQ   = 0
      DENS = 0.0
      AV   = 0.60225
      IF (MODE == 1) THEN
        OPEN (LU61, FILE = '.Z', STATUS = 'UNKNOWN')
        READ (LU61, 99997) Z
        CLOSE (UNIT = LU61)
      ELSE
        IF (KN == 0) THEN
C * ORGANIC/INORGANIC ?
          IF (IGBL(97) == 1) THEN
            XATVOL = 18.0
          ELSE
            XATVOL = 15.0
          END IF
          Z  = MAX (1, ISPR(104) * NINT (SPAR(107) /
     1         (XATVOL * ISPR(111) * ISPR(104))))
          IF (Z /= 1) THEN
            IF (ABS (ISPR(102) - Z) <= MAX (1.0, ISPR(102) / 3.0)) THEN
              Z = ISPR(102)
            END IF
            IF (NINT (Z / ISPR(102)) == 2) Z = 2 * ISPR(102)
          END IF
        ELSE
          Z    = FN(1)
          NQ   = 1
          IMAN = 1
        END IF
      END IF
   10 MOLWT = 0.0
      XATVOL = 100.0
      IF (Z * ISPR(111) > 0.0) THEN
        XATVOL = SPAR(107) / (ISPR(111) * Z)
      ELSE
        GO TO 30
      END IF
      DO I = 1, ISPR(110)
        ISPR(I + 120) = NINT (ISPR(I + 136) * Z)
        MOLWT         = MOLWT + ISPR(I + 120) * SPAR(249 + 15 * I)
      END DO
      DENS = MOLWT / (SPAR(107) * AV)
      IF (IMAN == 0) THEN
        IF (SPAR(3) < 40) THEN
          DENSMX = 2.4
        ELSE
          DENSMX = 3.0
        END IF
        IF (DENS > DENSMX .AND. MOD (NINT (Z), 2) == 0) THEN
          Z = Z / 2.0
          GO TO 10
        END IF
        IF (DENS < 0.8 .AND. Z == 1 .AND. ISPR(102) == 1) THEN
          Z = 2.0
          GO TO 10
        END IF
        IF (ISPR(103) == 2 .AND. MOD (NINT (Z), 2) == 1) THEN
          IF (Z > 4.0) THEN
            Z = Z + 1.0
            GO TO 10
          END IF
        END IF
      END IF
      SPAR(121) = DENS
      SPAR(122) = XATVOL
      ISPR(120) = MAX (1, NINT (Z))
      IF (IGBL(50) == 0 .AND. NQ == 0 .AND. MODE == 0) THEN
   20   WRITE (BCD, 99999, IOSTAT = IOST) DENS, ISPR(120), CHAR (0)
        CALL GGIP (-999.0, 5.0 + FLOAT (IGBL(68)), 60.0, 112)
        WRITE (SBCD, 99998, IOSTAT = IOST) ISPR(120), CHAR (0)
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') THEN
          CALL S040
          GO TO 20
        END IF
        IF (IGGT(1:4) == 'EXIT') GO TO 30
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
          CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10,
     1                 NP17)
          IF (KN == 1) THEN
            Z    = FN(1)
            IMAN = 1
            GO TO 10
          END IF
        END IF
      END IF
C * REGISTER CONTENT DEFINED
      ISPR(4) = 1
      CALL S915 ('Z - Defined')
      OPEN (LU61, FILE = '.Z', STATUS = 'UNKNOWN')
      WRITE (LU61, 99997, IOSTAT = IOST) Z
      CLOSE (UNIT = LU61)
      CALL S921 (0)
C * BIN-SETUP
      CALL S922 (IER)
C * DECIDE ON WHAT NEXT
      IF (IER /= 0) THEN
        CPR(105) = 'SPGR'
      ELSE
        CPR(105) = 'Z'
      END IF
      CPR(106) = CPR(200)
   30 RETURN
99999 FORMAT ('Density =', F6.3, ' for Z =', I3, A)
99998 FORMAT ('Z[', I3, ' ] ', A)
99997 FORMAT (F10.2)
      END SUBROUTINE S190
 
      SUBROUTINE S200
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: INA
      INTEGER :: NER
      INTEGER :: IERROR
      INTEGER :: MODE
      INTEGER :: CHDIR
      CHARACTER(len=80) :: PHM
      EXST = .FALSE.
      MODE = ISPR(16)
      CALL S915 ('Run Phase')
      IF (ISPR(3)  == 0) CALL S170
      IF (ISPR(4)  == 0) CALL S180 (0)
      IF (ISPR(12) == 0) CALL S922 (NER)
 
C * RESET VALIDATION MODE
      IGBL(34)   = 0
      VALIDATION = ' '
C * RESET REFINEMENT STATUS
      ISPR(6)  = -1
      ISPR(91) = 0
      DO I = 3, 7
        CALL GEN038 (CPR(200 + I), 1, 10)
      END DO
C * CREATE NEW DATA-CONTEXT (tm/sg/pn)
      IF (ISPR(14) == 6) THEN
        ISPR(14) = 0
        ISPR(15) = 0
      END IF
      CALL S924 (0)
C * (RE)LINK REFLECTION FILE TO hklf_ DIRECTORY
C * CHECK FOR/CREATE-CHANGE TO PHASING METHOD-DIR UNDER user/s/compoundname/sg?
      INA          = ISTATB(MODE)
      PHM(1 : INA) = SSTATB(MODE)(1 : INA)
      CALL S909 ('tm/sg/'//PHM(1:INA))
C * CLEANUP WHEN NECESSARY
      INQUIRE (FILE = 'exor', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('rm -r exor', 0, .true., KERR)
      END IF
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.res s.res', 0, .true., KERR)
C * CALL SELECTED STRUCTURE DETERMINATION PACKAGE
      IERROR = 0
      SELECT CASE (ISPR(16))
C * SHELXS86
        CASE (1)
          CALL S210 (IERROR)
C * SHELXS97
        CASE (2)
          CALL S210 (IERROR)
C * SIR97
        CASE (3)
          CALL S220 (IERROR)
C * SIR2004
        CASE (4)
          CALL S220 (IERROR)
C * DIRDIF99
        CASE (5)
          CALL S230 (IERROR)
C * SHELXD
        CASE (6)
          CALL S240 (IERROR)
C * FLIPPER
        CASE (7)
          CALL S250 (IERROR)
C * SHELXT
        CASE (8)
          CALL S260 (IERROR)
C * SIR2011
        CASE (9)
          CALL S220 (IERROR)
      END SELECT
 
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      IF (IERROR == 1) THEN
        IF (IGBL(50) == 0)
     1  WRITE (LU6, '(''ERROR in PHASE SOLUTION STAGE '')',
     2    IOSTAT = IOST)
        CPR(105) ='Z'
        CPR(106) = CPR(200)
      ELSE
        ISPR(6)  = 0
        ISPR(7)  = 1
        CPR(105) = 'PHASE'
        ISPR(11) = 4
        CALL S920 (1)
        IF (IGBL(50) == 0 .AND. ISPR(50) == 0) CALL S410 (0)
      END IF
      RETURN
      END SUBROUTINE S200
 
 
      SUBROUTINE S210 (IERROR)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE cggt
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NR
      INTEGER :: NR1
      INTEGER :: NR2
      INTEGER :: NAT
      INTEGER :: NUMS
      INTEGER :: MOLE
      INTEGER :: IOMIT
      INTEGER :: GEN135
      INTEGER :: IERROR
      REAL :: TNP
      CHARACTER(len=9) :: CTREF
      IF (KL == 1) THEN
         CPR(2)(1:4) = 'TREF'
         FN(1)       = 500
         FN(2)       = 2
      END IF
C * ENTER LOG
      IF (ISPR(16) == 2) THEN
        CALL S915 ('Run SHELXS97'//CPR(2))
        CPR(106) = 'SHELXS97'
      ELSE
        IF (CPR(2)(1:4) == 'TEXP' .OR. CPR(2)(1:4) == 'PATT')
     1     THEN
             IERROR = 1
             GO TO 70
        END IF
        CALL S915 ('Run Stripped SHELXS86/TREF')
        CPR(106) = 'SHELXS86'
      END IF
      CPR(2) = CPR(52)
C * LINK TO REFLECTION DATA
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl shelxs.hkl', 0, .true., KERR)
C * PREPARE SHELXS -JOB
      IF (CPR(2)(1:4) == 'TEXP') THEN
C * SHELXS97/TEXP
        OPEN (LU62, FILE = 'shelxs.res', STATUS = 'UNKNOWN')
        OPEN (LU61, FILE = 'shelxs.ins', STATUS = 'UNKNOWN')
        NAT = -1
   10   READ (LU62, 99996) LINE
        IF (LINE(1:4) == 'L.S.') GO TO 10
        IF (LINE(1:4) == 'BOND') GO TO 10
        IF (LINE(1:4) == 'FMAP') GO TO 10
        IF (LINE(1:4) == 'PLAN') THEN
          NAT = 0
          GO TO 10
        END IF
        IF (LINE(1:4) == 'HKLF') THEN
          WRITE (LU61, 99988, IOSTAT = IOST)  'TEXP', 200, NAT
          WRITE (LU61, 99996, IOSTAT = IOST) LINE
          GO TO 40
        END IF
        IF (NAT > -1 .AND. LINE(1:1) /= ' ') NAT = NAT + 1
        WRITE (LU61, 99996, IOSTAT = IOST) LINE
        GO TO 10
      ELSE
C * SHELXS TREF/PATT
        OPEN  (LU61, FILE = 'shelxs.ins', STATUS = 'UNKNOWN')
        WRITE (LU61, 99999, IOSTAT = IOST)
     1    TITL(1:6), CPR(106), CPR(52), SPAR(80), (SPAR(100 + I),
     2      I = 1, 6)
        WRITE (LU61, 99993, IOSTAT = IOST) ISPR(100)
        DO I = 2, ISPR(101)
          NUMS = I
          CALL SGSM (17, LINE, SGX, NUMS, 0, IERR)
          WRITE (LU61, 99992, IOSTAT = IOST) LINE(1:60)
        END DO
        DO I = 1, ISPR(110)
          WRITE (LU61, 99991, IOSTAT = IOST) SFAC(I),
     1          (SPAR(235 + J + 15 * I), J = 1, 14)
        END DO
        WRITE (LU61, 99998, IOSTAT = IOST)
     1    (ISPR(I + 120), I = 1, ISPR(110))
        IF (KN > 0 .AND. FN(1) /= 0.0) THEN
          WRITE (CTREF, 99987, IOSTAT = IOST) NINT (FN(1))
          TNP = FN(1)
        ELSE
          CTREF = ' '
          TNP   = 250
        END IF
        IF (FN(2) /= 0.0) THEN
          IOMIT = NINT (FN(2))
        ELSE
          IOMIT = 4
        END IF
        WRITE (LU61, 99997, IOSTAT = IOST) CPR(2)(1:7), CTREF, IOMIT
C * TEST FOR UNIT MATRIX
        IF (GEN135 (TM) == 1) THEN
          WRITE (LU61, 99995, IOSTAT = IOST)
        ELSE
          WRITE (LU61, 99994, IOSTAT = IOST)
     1      ((TM(I, J), J = 1, 3), I = 1, 3)
        END IF
        CLOSE (UNIT = LU61)
      END IF
   40 IF (IGBL(50) == 0) THEN
        WRITE (BCD, 99990, IOSTAT = IOST)
     1    CPR(2)(1:4), CTREF, IOMIT, CHAR (0)
        CALL GGIP (-999.0, 2.0, 80.0, 112)
      END IF
      IF (ISPR(16) == 2) THEN
C * OPTIONALLY EDIT SHELXS-INPUT
        IF (IGBL(44) == 1) THEN
          KERR = 0
          CALL SPAWN (EDITOR//' shelxl.ins', 0, .true., KERR)
        END IF
        KERR = 0
        CALL SPAWN (SHSPATH//' shelxs > sjob3.log', 0, .true., KERR)
        KERR = 0
        CALL SPAWN ('rm sjob3.log', 0, .true., KERR)
      ELSE
        CALL PLA155 (TNP)
      END IF
C * PREPARE s.res FILE FROM shelxs.res
      OPEN (LU61, FILE = 'shelxs.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 's.res',  STATUS = 'UNKNOWN')
      NR1  = 0
      NR2  = 0
      MOLE = 0
   50 READ (LU61, 99996, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 60
      IF (ISPR(16) == 1 .AND. LINE(1:4) == 'OMIT' .OR.
     1    ISPR(16) == 2 .AND. LINE(1:4) == 'MOLE') THEN
C * WRITE FVAR
        IF (MOLE == 0) WRITE (LU62, 99989, IOSTAT = IOST)
        MOLE = 1
        GO TO 50
      END IF
      IF (LINE(1:4) == 'HKLF') THEN
        WRITE (LU62, 99996, IOSTAT = IOST) LINE
        GO TO 60
      END IF
      IF (LINE(1:4) == 'OMIT') GO TO 50
      IF (CPR(2)(1:4) == 'PATT') THEN
        IF (LINE(1:4) == 'PLAN') THEN
          WRITE (LU62, 99996, IOSTAT = IOST) LINE
          WRITE (LU62,  99989, IOSTAT = IOST)
          GO TO 50
        END IF
      END IF
      IF (LINE(1:3) == 'END') THEN
        WRITE (LU62, 99996, IOSTAT = IOST) LINE
        GO TO 60
      END IF
      IF (MOLE == 1) THEN
C * SEARCH FOR NUMERAL
        CALL GEN105 (3, LINE(2:2), I)
        IF (I >= 0) THEN
          LINE(2:2) = ' '
          IF (NR1 < 999) THEN
            NR1 = NR1 + 1
            NR  = NR1
          ELSE
            GO TO 50
          END IF
        ELSE
          IF (NR2 < 99) THEN
            NR2 = NR2 + 1
            NR  = NR2
          ELSE
            GO TO 50
          END IF
        END IF
C * MODIFY LABELS
        NR = NR + 1
        CALL GEN058 (LINE(1:4), NR)
      END IF
      WRITE (LU62, 99996, IOSTAT = IOST) LINE
      GO TO 50
   60 CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
C * REGISTER SHELXS TYPE DONE
      IF (CPR(2) == 'TREF      ') THEN
        ISPR(18) = 2
      ELSE
        ISPR(18) = 3
      END IF
      IF (ISPR(16) == 2) THEN
        CPR(203) = 'SHELXS97  '
      ELSE
        CPR(203) = 'SHELXS86  '
      END IF
   70 RETURN
99999 FORMAT ('TITL ', A, 1X, A, 1X, A, /,
     1        'CELL ', F7.5, 6F10.4)
99998 FORMAT ('UNIT ', 2I5, 14I4)
99997 FORMAT (A, 1X, A, /, 'OMIT ', I3)
99996 FORMAT (A)
99995 FORMAT ('HKLF 4')
99994 FORMAT ('HKLF 4 1', 9F7.4)
99993 FORMAT ('LATT ', I3)
99992 FORMAT ('SYMM ', A)
99991 FORMAT ('SFAC ', A, 1X, 5F12.5, ' =', /, 8X, 4F12.5, ' =',
     1 /, 8X, 5F12.5)
99990 FORMAT ('===>> run SHELXS (structure determination)',
     1        ' mode = ', 2A, ' OMIT =', I2, A)
99989 FORMAT ('FVAR 1.0')
99988 FORMAT (A, 2I5)
99987 FORMAT (I9)
      END SUBROUTINE S210
 
      SUBROUTINE S220 (IERROR)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: IFVR
      INTEGER :: NUMS
      INTEGER :: NLINE
      INTEGER :: MAXTR
      INTEGER :: IERROR
      REAL, DIMENSION(12) :: XYZ
      CHARACTER(len=80) :: BUFF
      CHARACTER(len=9)  :: WIND
      EXST = .FALSE.
      IF (ISPR(16) == 4) THEN
C * CHECK FOR SIR2004 AVAILABLE
        IF (IGBL(114) == 0) THEN
          CALL PLA015 (0, 54)
          IERROR = 1
          GO TO 50
        END IF
        CALL S915 ('Run SIR2004')
        CPR(106) = 'SIR2004'
      ELSE IF (ISPR(16) == 9) THEN
C * CHECK FOR SIR2011 AVAILABLE
        IF (IGBL(120) == 0) THEN
          CALL PLA015 (0, 60)
          IERROR = 1
          GO TO 50
        END IF
        CALL S915 ('Run SIR2011')
        CPR(106) = 'SIR2011'
      ELSE
C * CHECK FOR SIR AVAILABLE
        IF (IGBL(113) == 0) THEN
          CALL PLA015 (0, 16)
          IERROR = 1
          GO TO 50
        END IF
        CALL S915 ('Run SIR97')
        CPR(106) = 'SIR97'
      END IF
      IF (KL > 1 .AND. JFL(2)(1:6) == 'RANDOM') THEN
        CPR(72) = 'RANDOM    '
      ELSE
        CPR(72) = 'DEFAULT   '
      END IF
C * INIT LABEL
      I = 0
      CALL S930 (0, LINE(1:4), I)
      CPR(2) = CPR(72)
      IF (KN > 0) THEN
        MAXTR = NINT (FN(1))
      ELSE
        MAXTR = 100
      END IF
C * PREPARE SIR97/SIR2004/SIR2011 - JOB
      OPEN (LU61, FILE = 'sir.sir', STATUS = 'UNKNOWN')
      IF (IGBL(50) == 0 .AND. IGBL(122) /= 0) THEN
        WIND = '%Window  '
      ELSE
        WIND = '%Nowindow'
      END IF
      WRITE (LU61, 99999, IOSTAT = IOST)
     1   WIND, TITL, (SPAR(100 + I), I = 1, 6), CPR(102)
      WRITE (BUFF, 99998, IOSTAT = IOST)
     1  (SFAC(I), ISPR(I + 120), I = 1, ISPR(110))
      CALL GEN020 (-1, BUFF, 5, 80)
      WRITE (LU61, 99982, IOSTAT = IOST) BUFF
      WRITE (LU61, 99997, IOSTAT = IOST)
      IF (IGBL(50) < 2) THEN
        IF (CPR(2) == 'RANDOM    ') THEN
          WRITE (LU61, 99988, IOSTAT = IOST) maxtr
          WRITE (LU6, 99983, IOSTAT = IOST) CPR(2), maxtr
        ELSE
          WRITE (LU6, 99985, IOSTAT = IOST) CPR(2)
        END IF
      END IF
      WRITE (LU61, 99996, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      INQUIRE (FILE = 's.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../s.hkl s.hkl', 0, .true., KERR)
      END IF
C * TRANSFORM s.hkl TO SIR.HKL
      CALL S902 (0, TM, LU61, LU62, 'sir.hkl')
      IF (ISPR(16) == 3) THEN
        KERR = 0
        CALL SPAWN (SIR97PATH//' sir', 0, .true., KERR)
      ELSE IF (ISPR(16) == 4) THEN
        CALL SPAWN (SIR04PATH//' sir', 0, .true., KERR)
        KERR = 0
      ELSE IF (ISPR(16) == 9) THEN
        KERR = 0
        CALL SPAWN (SIR11PATH//' sir', 0, .true., KERR)
      END IF
C * READ SIR-OUTPUT - sir.out
      IERROR = 0
      OPEN (LU61, FILE = 'sir.out', STATUS = 'OLD')
   10 READ (LU61, 99982, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 20
      IF (INDEX (LINE, 'ends in error') /= 0) THEN
        CALL PLA015 (0, 32)
        IERROR = 1
        GO TO 50
      ELSE
        GO TO 10
      END IF
C * GENERATE s.res file
   20 NLINE = 0
      IF (ISPR(16) == 3) THEN
        OPEN (LU61, FILE = 'sir.ins', STATUS = 'UNKNOWN')
      ELSE
        OPEN (LU61, FILE = 'sir.res', STATUS = 'UNKNOWN')
      END IF
      OPEN (LU62, FILE = 's.res', STATUS = 'UNKNOWN')
      IF (ISPR(16) == 3) THEN
        WRITE (LU62, 99987, IOSTAT = IOST) TITL(1:6)
      ELSE
        WRITE (LU62, 99986, IOSTAT = IOST) TITL(1:7)
      END IF
      WRITE (LU62, 99995, IOSTAT = IOST)
     1   SPAR(80), (SPAR(100 + I), I = 1, 6)
      WRITE (LU62, 99994, IOSTAT = IOST) ISPR(100)
      DO I = 2, ISPR(101)
        NUMS = I
        CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
        WRITE (LU62, 99993, IOSTAT = IOST) LINE(1:60)
      END DO
      WRITE (LU62, 99990, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
      WRITE (LU62, 99989, IOSTAT = IOST)
     1  (ISPR(I + 120), I = 1, ISPR(110))
      IFVR = 0
   30 READ  (LU61, 99982, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 40
      NLINE = NLINE + 1
      CALL GEN020 (1, LINE, 1, 80)
      IF (LINE(1:4) == 'FVAR') THEN
        WRITE (LU62, 99991, IOSTAT = IOST) LINE(5:80)
        IFVR = 1
        GO TO 30
      END IF
      IF (IFVR == 0) GO TO 30
      IF (LINE(1:4) == '    ') GO TO 30
      IF (LINE(1:4) == 'HKLF') GO TO 40
      IF (LINE(1:4) == 'OMIT') GO TO 40
C * ADAPT LABEL
      CALL S930 (1, LINE(1:4), I)
      WRITE (LU62, 99982, IOSTAT = IOST) LINE
      GO TO 30
   40 IF (NLINE == 0) THEN
        IERROR = 1
        GO TO 50
      END IF
      WRITE (LU62, 99992, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      KERR = 0
      CALL SPAWN ('rm sir.bin', 0, .true., KERR)
      INQUIRE (FILE = 'sir.plt', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('rm sir.plt', 0, .true., KERR)
      END IF
C * REGISTER SIR97/SIR2004/SIR2011 DONE
      CPR(203) = 'SIR       '
      ISPR(6)  = 0
   50 RETURN
99999 FORMAT (A, /,
     1        '%struc sir', /,
     2        '%init', /,
     3        '%job ', A, /,
     4        '%data', /,
     5        'cell ', 6F10.4, /,
     6        'space ', A)
99998 FORMAT ('cont', 11(1X, A, I4))
99997 FORMAT ('fosquare', /,
     1        'refl sir.hkl', /,
     2        'format (3i4, 2f8.0)')
99996 FORMAT ('%continue')
99995 FORMAT ('CELL ', F7.5, 6F10.4)
99994 FORMAT ('LATT ', I3)
99993 FORMAT ('SYMM ', A)
99992 FORMAT ('END')
99991 FORMAT ('FVAR', A)
99990 FORMAT ('SFAC ', 16(A, 1X))
99989 FORMAT ('UNIT ', 2I5, 14I4)
99988 FORMAT ('%normal', /,
     1        '%invar', /,
     2        '%phase', /,
     3        'random', /,
     4        'maxtrial ', I10)
99987 FORMAT ('TITL ', A, ' - SIR97')
99986 FORMAT ('TITL ', A, ' - SIR2004')
99985 FORMAT (/, '===>> run SIR (structure determination)',
     1        ' mode = ', A, /)
99983 FORMAT (/, '===>> run SIR (structure determination)',
     1        ' mode = ', A, ' - maxtr = ', I5, /)
99982 FORMAT (A)
      END SUBROUTINE S220
 
      SUBROUTINE S230 (IERR)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IFN1
      INTEGER :: IERR
      INTEGER :: NLIN
      INTEGER :: NUMS
      INTEGER :: IFVAR
      REAL, DIMENSION(12) :: XYZ
      CHARACTER(len=2) :: WL
      EXST = .FALSE.
C * CHECK FOR DIRDIF AVAILABLE
      IF (IGBL(115) == 0) THEN
        CALL PLA015 (0, 14)
        IERR = 1
        RETURN
      END IF
      I = 0
      CALL S930 (0, LINE(1:4), I)
      CPR(2) = CPR(62)
C * ENTER LOG
      CALL S915 ('Run DIRDIF08')
      CPR(106) = 'DIRDIF'
C * PREPARE DIRDIF - JOB
      OPEN  (LU61, FILE = 'crysin', STATUS = 'UNKNOWN')
      WRITE (LU61, 99999, IOSTAT = IOST)
     1  (SPAR(100 + I), I = 1, 6), (SPAR(107 + I), I = 1, 6), CPR(101)
      WRITE (LU61, 99998, IOSTAT = IOST)
     1  (SFAC(I), ISPR(I + 120), I = 1, ISPR(110))
      IF (SPAR(80) > 1.0) THEN
        WL = 'CU'
      ELSE
        WL = 'MO'
      END IF
      WRITE (LU61, 99997, IOSTAT = IOST)
     1  WL, ((TM(I, J), J = 1, 3), I = 1, 3)
      CLOSE (UNIT = LU61)
      INQUIRE (FILE = 'drdf.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../s.hkl drdf.hkl', 0, .true., KERR)
      END IF
C * HANDLE ORIENT OPTION
      IF (CPR(2)(1:6) == 'ORIENT') THEN
        NLIN = 0
        KERR = 0
        CALL SPAWN ('rm -f model',                 0, .true., KERR)
        CALL SPAWN ('rm -f atmod',                 0, .true., KERR)
        CALL SPAWN ('ln -s ../../../.model model', 0, .true., KERR)
        OPEN (LU61, FILE = 'model', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 'atmod', STATUS = 'UNKNOWN')
   10   CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80, 10,
     1               NP17)
        IF (JFL(1)(1:3) == 'EOF') GO TO 20
        WRITE (LU62, 99996, IOSTAT = IOST) LINE
        NLIN = NLIN + 1
        GO TO 10
   20   CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        IF (NLIN == 0) THEN
          IF (IGBL(50) == 0) THEN
            WRITE (BCD, 99984, IOSTAT = IOST)
     1          'No Model Found. ORBASE run in ASCII Window', CHAR (0)
            CALL GGIP (-999.0, 2.0, 80.0, 112)
C * FLUSH
            CALL GGIP (0.0, 0.0, 0.0, 6)
          END IF
          KERR = 0
          CALL SPAWN ('rm -f atmod',       0, .true., KERR)
          CALL SPAWN (DIRPATH//' ORBASE ', 0, .true., KERR)
        END IF
      END IF
C * SPAWN DIRDIF JOB
      KERR = 0
      CALL SPAWN (DIRPATH//'  '//CPR(2)//' > df.log 2> df.log', 0,
     1  .true., KERR)
C * TEST FOR ERRORS
      OPEN (LU61, FILE = 'df.log', STATUS = 'UNKNOWN')
   30 READ (LU61, 99996, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 40
      IF (INDEX (LINE(1:20), 'ERROR') /= 0) THEN
        GO TO 40
      ELSE
        IF (INDEX (LINE, 'DRDF.res') == 0 .AND.
     1      INDEX (LINE, 'drdf.res') == 0) GO TO 30
        GO TO 50
      END IF
   40 CALL PLA015 (0, 13)
      IERR  = 1
   50 CLOSE (UNIT = LU61)
      IF (IERR == 0) THEN
C * GENERATE s.res file from DIRDIF-Result File (on drdf.res)
        IFVAR = 0
        OPEN (LU61, FILE = 'drdf.res', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 's.res', STATUS = 'UNKNOWN')
        WRITE (LU62, 99995, IOSTAT = IOST) TITL(1:6), SPAR(80),
     1                      (SPAR(100 + I), I = 1, 6)
C * SFAC/UNIT
        WRITE (LU62, 99986, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
        WRITE (LU62, 99985, IOSTAT = IOST)
     1    (ISPR(I + 120), I = 1, ISPR(110))
        WRITE (LU62, 99994, IOSTAT = IOST) ISPR(100)
        DO I = 2, ISPR(101)
          NUMS = I
          CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
          WRITE (LU62, 99993, IOSTAT = IOST) LINE(1:60)
        END DO
C * COPY COORDINATES
   70   READ  (LU61, 99996, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 90
        IF (LINE(1:4) == 'FVAR') THEN
          IFVAR = 1
          GO TO 80
        END IF
C * SKIP 'BLANK' LINES
        IF (LINE(1:1) == ' ') GO TO 70
        IF (LINE(1:4) == 'HKLF') GO TO 70
        IF (LINE(1:3) == 'END') THEN
          WRITE (LU62, 99991, IOSTAT = IOST)
     1    ((TM(I, J), J = 1, 3), I = 1, 3)
          GO TO 80
        END IF
        IF (IFVAR == 1) THEN
          READ (LINE, 99992) IFN1
          IF (SFAC(IFN1) == 'H ') GO TO 70
          CALL S930 (1, LINE(1:4), I)
        ELSE
          GO TO 70
        END IF
   80   WRITE (LU62, 99996, IOSTAT = IOST) LINE
        GO TO 70
   90   CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
C * REGISTER DIRDIF DONE
        CPR(203) = 'DIRDIF    '
      END IF
      RETURN
99999 FORMAT ('CRYSIN DRDF', /, 'TITLE ', /, 'CELL ', 6F10.4, /,
     1        'CELLSD ', 6F10.4, /, 'SPGR ', A)
99998 FORMAT ('FORMUL', 11(1X, A, I4))
99997 FORMAT ('Z    1', /, 'WAVE ', A, /,
     1        'HKLF 4 1', 9F7.4, /,  'END')
99996 FORMAT (A)
99995 FORMAT ('TITL ', A, ' - DIRDIF  ', /, 'CELL ', F7.5, 6F10.4)
99994 FORMAT ('LATT ', I3)
99993 FORMAT ('SYMM ', A)
99992 FORMAT (7X, I2)
99991 FORMAT ('HKLF 4 1', 9F7.4)
99986 FORMAT ('SFAC ', 16(A, 1X))
99985 FORMAT ('UNIT ', 2I5, 14I4)
99984 FORMAT (2A)
      END SUBROUTINE S230
 
      SUBROUTINE S240 (IERR)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: NR
      INTEGER :: NR1
      INTEGER :: NR2
      INTEGER :: NUMS
      INTEGER :: IERR
      INTEGER :: GEN135
      REAL :: AEXP
      REAL :: PEXP
      REAL, DIMENSION(12) :: XYZ
      IF (IGBL(112) == 0) THEN
        CALL PLA015 (0, 55)
        IGBL(50) = 0
        IERR     = 1
        GO TO 20
      END IF
C * GET # TRIALS WHEN NON-ZERO
      IF (KN > 0) ISPR(28) = NINT (FN(1))
C * ENTER LOG
      CALL S915 ('Run SHELXD')
      CPR(106) = 'SHELXD'
C * LINK TO REFLECTION DATA
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl shelxd.hkl', 0, .true., KERR)
C * PREPARE SHELXD -JOB
      INQUIRE (FILE = 'shelxd.res', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('rm shelxd.res', 0, .true., KERR)
      END IF
      OPEN  (LU61, FILE = 'shelxd.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99999, IOSTAT = IOST) TITL(1:6), CPR(106),
     1                    SPAR(80), (SPAR(100 + I), I = 1, 6)
      WRITE (LU61, 99993, IOSTAT = IOST) ISPR(100)
      DO I = 2, ISPR(101)
        NUMS = I
        CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
        WRITE (LU61, 99992, IOSTAT = IOST) LINE(1:60)
      END DO
      WRITE (LU61, 99991, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
      WRITE (LU61, 99998, IOSTAT = IOST)
     1  (ISPR(I + 120), I = 1, ISPR(110))
      AEXP = FLOAT (ISPR(111) * ISPR(120)) / ISPR(102)
      PEXP = 0.20
      WRITE (LU61, 99997, IOSTAT = IOST)
     1  (NINT ((1.0 - PEXP) * AEXP)), NINT (AEXP),
     1                    NINT ((1.0 + PEXP) * AEXP), ISPR(28)
C * TEST FOR UNIT MATRIX
      IF (GEN135 (TM) == 1) THEN
        WRITE (LU61, 99995, IOSTAT = IOST)
      ELSE
        WRITE (LU61, 99994, IOSTAT = IOST)
     1    ((TM(I, J), J = 1, 3), I = 1, 3)
      END IF
      CLOSE (UNIT = LU61)
      IF (IGBL(50) == 0) THEN
        WRITE (BCD, 99990, IOSTAT = IOST) CHAR (0)
        CALL GGIP (-999.0, 2.0, 80.0, 112)
      END IF
C * OPTIONALLY EDIT SHELXD-INPUT
      IF (IGBL(44) == 1) THEN
        KERR = 0
        CALL SPAWN (EDITOR//' shelxd.ins', 0, .true., KERR)
      END IF
      KERR = 0
      CALL SPAWN (SHDPATH//' shelxd  > sjob3.log', 0, .true., KERR)
 
C * PREPARE s.res FILE FROM shelxd.res
      INQUIRE (FILE = 'shelxd.res', EXIST = EXST)
      IF (.NOT. EXST) THEN
        IERR = 1
        GO TO 20
      END IF
      OPEN (LU61, FILE = 'shelxd.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 's.res',  STATUS = 'UNKNOWN')
      NR1  = 0
      NR2  = 0
      DO
        READ (LU61, 99989, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 10
        IF (LINE(1:4) == 'HKLF') THEN
          WRITE (LU62, 99989, IOSTAT = IOST) LINE
          GO TO 10
        END IF
        IF (LINE(1:4) /= 'OMIT') THEN
          IF (LINE(1:3) == 'END') THEN
            WRITE (LU62, 99989, IOSTAT = IOST) LINE
            GO TO 10
          END IF
          CALL GEN105 (3, LINE(3:3), N)
          IF (N >= 0) THEN
C * LOOK FOR NUMERAL
            CALL GEN105 (3, LINE(2:2), I)
            IF (I >= 0) THEN
              LINE(2:2) = ' '
              NR1 = NR1 + 1
              NR  = NR1
            ELSE
              NR2 = NR2 + 1
              NR  = NR2
            END IF
C * MODIFY LABELS
            NR = NR + 1
            CALL GEN058 (LINE(1:4), NR)
          END IF
          WRITE (LU62, 99989, IOSTAT = IOST) LINE
        END IF
      END DO
   10 CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
C * REGISTER SHELXD TYPE DONE
      CPR(203) = 'SHELXD'
   20 RETURN
99999 FORMAT ('TITL ', A, 1X, A, /,
     1        'CELL ', F7.5, 6F10.4)
99998 FORMAT ('UNIT ', 2I5, 14I4)
99997 FORMAT ('FIND', I5, /,
     1        'PLOP', 2I5, /,
     2        'NTRY', I5)
99995 FORMAT ('HKLF 4')
99994 FORMAT ('HKLF 4 1', 9F7.4)
99993 FORMAT ('LATT ', I3)
99992 FORMAT ('SYMM ', A)
99991 FORMAT ('SFAC', 16(1X, A))
99990 FORMAT ('===>> run SHELXD (structure determination)', A)
99989 FORMAT (A)
      END SUBROUTINE S240
 
      SUBROUTINE S250 (IERR)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: NR
      INTEGER :: NR1
      INTEGER :: NR2
      INTEGER :: IERR
      INTEGER :: MOLE
      INTEGER :: NUMS
      INTEGER :: GEN135
      REAL, DIMENSION(12) :: XYZ
      CHARACTER(len=9) :: CTREF
      CTREF = ' '
C * ENTER LOG
      CALL S915 ('Run FLIPPER')
      CPR(106) = 'FLIPPER'
      CPR(2) = CPR(52)
C * LINK TO REFLECTION DATA
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl flip.hkl', 0, .true., KERR)
C * PREPARE FLIPPER-JOB
      OPEN  (LU61, FILE = 'flip.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99999) TITL(1:6), CPR(106), CPR(52),
     1                      SPAR(80), (SPAR(100 + I), I = 1, 6)
      WRITE (LU61, 99993) ISPR(100)
      DO I = 2, ISPR(101)
        NUMS = I
        CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
        WRITE (LU61, 99992) LINE(1:60)
      END DO
      DO I = 1, ISPR(110)
        WRITE (LU61, 99991) SFAC(I),
     1        (SPAR(235 + J + 15 * I), J = 1, 14)
      END DO
      WRITE (LU61, 99998) (ISPR(I + 120), I = 1, ISPR(110))
C * TEST FOR UNIT MATRIX
      IF (GEN135 (TM) == 1) THEN
        WRITE (LU61, 99995)
      ELSE
        WRITE (LU61, 99994) ((TM(I, J), J = 1, 3), I = 1, 3)
      END IF
      WRITE (LU61, 99987)
      CLOSE (UNIT = LU61)
      IF (IGBL(50) == 0) THEN
        WRITE (BCD, 99990) CPR(2)(1:4), CTREF, CHAR (0)
        CALL GGIP (-999.0, 2.0, 80.0, 112)
      END IF
      KERR = 0
      CALL SPAWN (PLAPATH//' flip.ins > sjob3.log', 0, .true., KERR)
C * PREPARE s.res FILE FROM flip.res
      OPEN (LU61, FILE = 'flip.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 's.res',    STATUS = 'UNKNOWN')
      NR1  = 0
      NR2  = 0
      MOLE = 0
   10 READ (LU61, 99996, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 20
      IF (LINE(1:4) == 'HKLF') THEN
        WRITE (LU62, 99996) LINE
        GO TO 20
      END IF
      IF (LINE(1:3) == 'END') THEN
        WRITE (LU62, 99996) LINE
        GO TO 20
      END IF
      IF (MOLE == 1) THEN
C * SEARCH FOR NUMERAL
        CALL GEN105 (3, LINE(2:2), I)
        IF (I >= 0) THEN
          LINE(2:2) = ' '
          IF (NR1 < 999) THEN
            NR1 = NR1 + 1
            NR  = NR1
          ELSE
            GO TO 10
          END IF
        ELSE
          IF (NR2 < 99) THEN
            NR2 = NR2 + 1
            NR  = NR2
          ELSE
            GO TO 10
          END IF
        END IF
C * MODIFY LABELS
        NR = NR + 1
        CALL GEN058 (LINE(1:4), NR)
      END IF
      WRITE (LU62, 99996) LINE
      GO TO 10
   20 CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      CPR(203) = 'FLIPPER   '
      RETURN
99999 FORMAT ('TITL ', A, 1X, A, 1X, A, /,
     1        'CELL ', F7.5, 6F10.4)
99998 FORMAT ('UNIT ', 2I5, 14I4)
99996 FORMAT (A)
99995 FORMAT ('HKLF 4')
99994 FORMAT ('HKLF 4 1', 9F7.4)
99993 FORMAT ('LATT ', I3)
99992 FORMAT ('SYMM ', A)
99991 FORMAT ('SFAC ', A, 1X, 5F12.5, ' =', /, 8X, 4F12.5, ' =',
     1 /, 8X, 5F12.5)
99990 FORMAT ('===>> run FLIPPER (structure determination)',
     1        ' mode = ', 2A, A)
99987 FORMAT ('FLIP 5 250 2 AUTO')
      END SUBROUTINE S250
 
      SUBROUTINE S260 (IERR)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IERR
      INTEGER :: NUMS
      INTEGER :: GEN135
      REAL, DIMENSION(12) :: XYZ
C * SHELXT
      IF (IGBL(119) == 0) THEN
C * REPORT WHEN SHELXT IS NOT ACCESSIBLE
        CALL PLA015 (0, 59)
        IGBL(50) = 0
        IERR     = 1
        RETURN
      END IF
C * ENTER LOG
      CALL S915 ('Run SHELXT')
      CPR(106) = 'SHELXT'
C * LINK TO REFLECTION DATA
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl shelxt.hkl', 0, .true., KERR)
C * PREPARE SHELXT -JOB
      OPEN  (LU61, FILE = 'shelxt.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99999, IOSTAT = IOST) TITL(1:6), CPR(106), CPR(52),
     1                    SPAR(80), (SPAR(100 + I), I = 1, 6)
      WRITE (LU61, 99993, IOSTAT = IOST) ISPR(100)
      DO I = 2, ISPR(101)
        NUMS = I
        CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
        WRITE (LU61, 99992, IOSTAT = IOST) LINE(1:60)
      END DO
      WRITE (LU61, 99991, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
      WRITE (LU61, 99998, IOSTAT = IOST)
     1  (ISPR(I + 120), I = 1, ISPR(110))
C * TEST FOR UNIT MATRIX
      IF (GEN135 (TM) == 1) THEN
        WRITE (LU61, 99995, IOSTAT = IOST)
      ELSE
        WRITE (LU61, 99994, IOSTAT = IOST)
     1    ((TM(I, J), J = 1, 3), I = 1, 3)
      END IF
      CLOSE (UNIT = LU61)
      IF (IGBL(50) == 0) THEN
        WRITE (BCD, 99990, IOSTAT = IOST)
        CALL GGIP (-999.0, 2.0, 80.0, 112)
      END IF
      KERR = 0
      CALL SPAWN (SHTPATH//' shelxt > sjob3.log', 0, .true., KERR)
      KERR = 0
      CALL SPAWN ('rm sjob3.log', 0, .true., KERR)
C * PREPARE s.res FILE FROM shelxt_a.res
      OPEN (LU61, FILE = 'shelxt_a.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 's.res',  STATUS = 'UNKNOWN')
   50 READ (LU61, 99996, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 60
      WRITE (LU62, 99996, IOSTAT = IOST) LINE
      GO TO 50
   60 CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
C * REGISTER SHELXT TYPE DONE
      CPR(203) = 'SHELXT    '
      RETURN
99999 FORMAT ('TITL ', A, 1X, A, 1X, A, /,
     1        'CELL ', F7.5, 6F10.4)
99998 FORMAT ('UNIT ', 2I5, 14I4)
99996 FORMAT (A)
99995 FORMAT ('HKLF 4')
99994 FORMAT ('HKLF 4 1', 9F7.4)
99993 FORMAT ('LATT ', I3)
99992 FORMAT ('SYMM ', A)
99991 FORMAT ('SFAC ', 16(A, 1X))
99990 FORMAT ('===>> run SHELXT (structure determination)')
      END SUBROUTINE S260
 
      SUBROUTINE S300 (IP2, IP3, NEXOR)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IN2
      INTEGER :: IN3
      INTEGER :: IP2
      INTEGER :: IP3
      INTEGER :: IIP3
      INTEGER :: MODE
      INTEGER :: NEXOR
      INTEGER :: CHDIR
      INTEGER :: GEN135
      REAL :: P1
      CHARACTER(len=4) :: AUTO
      IF (IGBL(50) > 0) THEN
        AUTO = 'AUTO'
      ELSE
        AUTO = ' '
      END IF
      EXST   = .FALSE.
      P1     = 0.0
C * GET EXOR PARAMETERS
      IF (KL > 1 .AND. KL == KN + 1) THEN
        DO I = 2, KL
          IF (JFL(I)(1:4) == 'OMIT') THEN
            SPAR(200) = FN(I - 1)
          END IF
        END DO
      END IF
C * CHECK FOR/CREATE-CHANGE TO EXOR-DIR UNDER user/s/compoundname/tm/sg/source
      MODE = ISPR(16)
      IF (MODE == 0) THEN
        IN2           = INZ + 17
        FNM(INZ + 1:IN2) = 'tm/sg/shelxl/exor'
      ELSE
        IN3           = ISTATB(MODE)
        IN2           = INZ + 11 + IN3
        FNM(INZ + 1:IN2) = 'tm/sg/'//SSTATB(MODE)(1:IN3)//'/exor'
      END IF
      CALL S909 (FNM(1:IN2))
C * CHECK/MAKE LINKS TO DATA
      KERR = 0
      CALL SPAWN ('ln -s -f ../../setup/s.bin s.bin', 0, .true., KERR)
      CALL SPAWN ('ln -s -f ../../s.hkl shelxl.hkl',  0, .true., KERR)
C * ANALYSE LS, SHELXS, SIR, DIRDIF etc. RESULTS (s.res)
      OPEN (LU61, FILE = '../s.res', STATUS = 'UNKNOWN')
   20 OPEN (LU62, FILE = 's.ins', STATUS = 'UNKNOWN')
   30 READ (LU61, 99995, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 40
      IF (LINE(1:3) == 'END') THEN
        GO TO 40
      ELSE IF (LINE(1:3) == 'HKL') THEN
        GO TO 40
C * SPECIAL CONTINUATION LINE TREATMENT FOR SFAC - RECORD
      ELSE IF (LINE(1:4) == 'SFAC') THEN
        BACKSPACE LU61
        CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80, 10,
     1               NP17)
        GO TO 30
      ELSE
        IF (LINE(1:4) == 'UNIT') WRITE (LU62, 99993, IOSTAT = IOST)
     1   (SFAC(I), I = 1, ISPR(110))
        WRITE (LU62, 99995, IOSTAT = IOST) LINE
        GO TO 30
      END IF
   40 IF (IGBL(68) == 1) WRITE (LU62, 99999, IOSTAT = IOST) IGBL(82)
      IF (NEXOR > 0) THEN
        IIP3 = -IP3
      ELSE
        IIP3 = IP3
      END IF
      WRITE (LU62, 99992, IOSTAT = IOST)
     1  SPAR(200), SPAR(56), SPAR(57), P1, IP2,
     1                    IIP3, 1, 1, AUTO
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
C * EXOR-LOOP
      KERR = 0
      CALL SPAWN ('sh -c '''//PLAPATH(1:IGBL(80))//' s.ins  '' ', 0,
     1  .true., KERR)
C * CHECK FOR 'NEXT' CONTENT
      INQUIRE (FILE = 'NEXT', EXIST = EXST)
      IF (EXST) THEN
        OPEN (LU61, FILE = 'NEXT', STATUS = 'UNKNOWN')
        READ (LU61, 99995) LINE
        IF (LINE(1:4) == 'SKIP') NEXOR = 0
        CLOSE (UNIT = LU61, STATUS = 'DELETE')
      END IF
C * ANALYZE s.res (refined population + difmap peaks)
      INQUIRE (FILE = 's.res', EXIST = EXST)
      IF (EXST) THEN
C * SUBSTITUTE ORIGINAL HKLF
        KERR = 0
        CALL SPAWN ('mv s.res s.rese', 0, .true., KERR)
        OPEN (LU61, FILE = 's.rese', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 's.res', STATUS = 'UNKNOWN')
   50   READ (LU61, 99995, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 60
        IF (LINE(1:4) /= 'HKLF') THEN
          IF (LINE(1:4) == 'FVAR') WRITE (LU62, 99997, IOSTAT = IOST)
          WRITE (LU62, 99995, IOSTAT = IOST) LINE
          GO TO 50
        END IF
C * TEST FOR UNIT MATRIX
   60   IF (GEN135 (TM) == 1) THEN
          WRITE (LU62, 99996, IOSTAT = IOST)
        ELSE
          WRITE (LU62, 99998, IOSTAT = IOST)
     1      ((TM(I, J), J = 1, 3), I = 1, 3)
        END IF
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        IF (NEXOR > 0) THEN
          IF (IGBL(25) * IGBL(32) == 1 .AND. IGBL(50) == 0) THEN
            CALL PLA439 (0.0, 'Refine x,y,z,U', 14, 1.5, 2, 8, 3.0,
     1                   8.0)
            CALL GGIP (0.0, 0.0, 0.0, 6)
          END IF
          KERR = 0
          CALL SPAWN ('mv s.res shelxl.ins',           0, .true., KERR)
          CALL SPAWN (SHLPATH//' shelxl > shelxl.log', 0, .true., KERR)
          OPEN (LU61, FILE = 'shelxl.res', STATUS = 'UNKNOWN')
          NEXOR = NEXOR - 1
          GO TO 20
        END IF
C * CREATE NEW DATA LINK
        CALL S924 (0)
        KERR = 0
        CALL SPAWN ('cp s.res ../../s.res', 0, .true., KERR)
        CALL SPAWN ('rm s.rese',            0, .true., KERR)
C * GET R-VALUE'S
        OPEN (LU61, FILE = 's_log', STATUS = 'UNKNOWN')
   70   READ (LU61, 99995, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 80
        IF (LINE(1:7) /= ':: RVAL') GO TO 70
        READ (LINE, 99994, IOSTAT = IOST) SPAR(202), SPAR(203)
        IF (IOST == -1) GO TO 80
   80   CLOSE(LU61)
        CPR(204) = 'EXOR'
C * ENTER LOG
        CALL S915 ('Run PLATON/EXOR')
C * REGISTER EXOR-DONE
        ISPR(17) = 1
C * SHOW RESULT
        ISPR(6)  = 0
        CPR(105) = 'EXOR'
        CPR(106) = CPR(200)
      END IF
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1 : INZ - 1)) /= 0) CALL S925 (1)
      IF (EXST .AND. IGBL(50) == 0) CALL S410 (0)
      RETURN
99999 FORMAT ('SET IGBL 82', I3, /, 'SET REVERSE')
99998 FORMAT ('HKLF 4 1', 9F7.4, /, 'END')
99997 FORMAT ('L.S. 3')
99996 FORMAT ('HKLF 4', /, 'END')
99995 FORMAT (A)
99994 FORMAT (8X, 2F10.3, 2I10)
99993 FORMAT ('SFAC ', 16(1X, A))
99992 FORMAT ('EXOR', 4F8.2, 4I5, 1X, A )
      END SUBROUTINE S300
 
      SUBROUTINE S301 (IERR)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: IN2
      INTEGER :: IN3
      INTEGER :: NAT
      INTEGER :: NUMS
      INTEGER :: IERR
      INTEGER :: IFVR
      INTEGER :: IPAT
      INTEGER :: MODE
      INTEGER :: IFVAR
      INTEGER :: CHDIR
      REAL :: SJ
      REAL :: YY
      REAL :: RPI
      REAL, DIMENSION(12) :: XYZ
      REAL, DIMENSION(50) :: RP
      CHARACTER(len=80) :: BUFF
      CHARACTER(len=9)  :: WIND
C * CHECK FOR SIR AVAILABLE
      IF (IGBL(113) == 0) THEN
        CALL PLA015 (0, 16)
        IERR = 1
        RETURN
      END IF
C * ENTER LOG
      CALL S915 ('Run SIR/EXORS')
      EXST    = .FALSE.
C * REGISTER EXORS-DONE
      ISPR(17) = 2
      I        = 0
      CALL S930 (0, LINE(1:4), I)
C * CHECK FOR/CREATE-CHANGE TO EXORS-DIR UNDER user/s/compoundname/tm/sg/source
      MODE = ISPR(16)
      IF (MODE == 0) THEN
        IN2       = INZ + 18
        FNM(INZ + 1:IN2) = 'tm/sg/shelxl/exors'
      ELSE
        IN3 = ISTATB(MODE)
        IN2 = INZ + 12 + IN3
        FNM(INZ + 1:IN2) = 'tm/sg/'//SSTATB(MODE)(1:IN3)//'/exors'
      END IF
      CALL S909 (FNM(1:IN2))
C * CHECK/MAKE LINKS TO DATA
      WRITE (LU6, 99979, IOSTAT = IOST)
      NAT  = 0
      IPAT = 0
C * ANALYSE LS, SHELXS, SIR, DIRDIF etc. RESULTS (s.res)
      OPEN (LU62, FILE = 'sir.frg',  STATUS = 'UNKNOWN')
      OPEN (LU61, FILE = '../s.res', STATUS = 'UNKNOWN')
      IFVAR = 0
   10 CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80, 10,
     1             NP17)
      IF (JFL(1)(1:4) == 'FVAR') THEN
        DO I = 1, KN
          RP(I) = FN(I)
        END DO
        RP(1) = 1.0
        IFVAR = 1
        GO TO 10
      ELSE IF (JFL(1)(1:4) == 'TITL') THEN
        IF (LINE(24:27) == 'PATT') IPAT = 1
        GO TO 10
      ELSE IF (JFL(1)(1:4) == 'MOLE') THEN
        RP(1) = 1.0
        IFVAR = 1
        GO TO 10
      ELSE IF (JFL(1)(1:3) == 'END') THEN
        GO TO 20
      ELSE IF (JFL(1)(1:3) == 'HKL') THEN
        GO TO 20
      ELSE IF (JFL(1)(1:3) == 'EOF') THEN
        GO TO 20
      ELSE IF (JFL(1)(1:4) == 'PLAN') THEN
        IF (IPAT == 1) THEN
          READ (LU61, 99992) LINE
          IFVAR = 1
        END IF
        GO TO 10
      ELSE IF (IFVAR == 1 .AND. KN >= 4) THEN
        NAT = NAT + 1
C * HANDLE FREE VARIABLES
        DO K = 2, 4
          YY = FN(K)
          IF (ABS (YY) > 5.0) THEN
            I = NINT (ABS (YY) * 0.1)
            RPI = RP(I)
            SJ = SIGN (0.5, YY)
            YY = (YY - I * SJ * 20.0) * (RPI + SJ - 0.5)
          END IF
          FN(K) = YY
        END DO
        WRITE (LU62, 99969, IOSTAT = IOST) (FN(I), I = 2, 4)
      END IF
      GO TO 10
   20 CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
C * PREPARE SIR97 - JOB
      OPEN (LU61, FILE = 'sir.sir', STATUS = 'UNKNOWN')
      IF (IGBL(50) == 0) THEN
        WIND = '%Window  '
      ELSE
        WIND = '%Nowindow'
      END IF
      WRITE (LU61, 99999, IOSTAT = IOST)
     1  WIND, TITL, (SPAR(100 + I), I = 1, 6),
     1 CPR(102)
      WRITE (BUFF, 99998, IOSTAT = IOST)
     1  (SFAC(I), ISPR(I + 120), I = 1, ISPR(110))
      CALL GEN020 (-1, BUFF, 5, 80)
      WRITE (LU61, 99992, IOSTAT = IOST) BUFF
      WRITE (LU61, 99997, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      INQUIRE (FILE = 's.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../../s.hkl s.hkl', 0, .true., KERR)
      END IF
C * TRANSFORM s.hkl TO SIR.HKL
      CALL S902 (0, TM, LU61, LU62, 'sir.hkl')
C * CREATE NEW DATA LINK
      KERR = 0
      CALL SPAWN (SIR97PATH//' sir', 0, .true., KERR)
C * READ SIR-OUTPUT - sir.lis
      IERR = 0
      OPEN (LU61, FILE = 'sir.out', STATUS = 'OLD')
      DO
        READ (LU61, 99992, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 30
        IF (LINE(2:18) == 'sir ends in error') THEN
          WRITE (LU6, 99988, IOSTAT = IOST) LINE
          WRITE (LU6, '('' See exors/sir.lis, Acknowledge '')',
     1      IOSTAT = IOST)
          IERR = 1
          READ (LU5, 99992) LINE
          GO TO 60
        END IF
      END DO
C * GENERATE s.res file
   30 OPEN (LU61, FILE = 'sir.ins', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 's.res', STATUS = 'UNKNOWN')
      WRITE (LU62, 99995, IOSTAT = IOST)
     1  TITL(1:6), SPAR(80), (SPAR(100 + I), I = 1, 6)
      WRITE (LU62, 99994, IOSTAT = IOST) ISPR(100)
      DO I = 2, ISPR(101)
        NUMS = I
        CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
        WRITE (LU62, 99993, IOSTAT = IOST) LINE(1:60)
      END DO
      DO I = 1, ISPR(110)
        WRITE (LU62, 99990, IOSTAT = IOST)
     1    SFAC(I), (SPAR(235 + J + 15 * I), J = 1, 14)
      END DO
      WRITE (LU62, 99989, IOSTAT = IOST)
     1  (ISPR(I + 120), I = 1, ISPR(110))
      IFVR = 0
   40 READ  (LU61, 99992, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 50
      CALL GEN020 (1, LINE, 1, 80)
      IF (LINE(1:4) == 'FVAR') THEN
        WRITE (LU62, 99991, IOSTAT = IOST) LINE(5:80)
        IFVR = 1
        GO TO 40
      END IF
      IF (IFVR == 1) THEN
        IF (LINE(1:4) == '    ') GO TO 40
        IF (LINE(1:4) == 'HKLF') GO TO 50
        CALL S930 (1, LINE(1:4), I)
        WRITE (LU62, 99992, IOSTAT = IOST) LINE
      END IF
      GO TO 40
   50 WRITE (LU62, 99992, IOSTAT = IOST) LINE
      WRITE (LU62, 99996, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      KERR = 0
      CALL SPAWN ('rm sir.bin',           0, .true., KERR)
      CALL SPAWN ('rm sir.plt',           0, .true., KERR)
      CALL SPAWN ('cp s.res ../../s.res', 0, .true., KERR)
C * REGISTER EXOR
      CPR(204) = 'EXORS'
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * SHOW RESULT
      ISPR(6)  = 0
      CPR(105) = 'EXORS'
      CPR(106) = CPR(200)
      IF (IGBL(50) == 0) CALL S410 (0)
   60 RETURN
99999 FORMAT (A, /,
     1        '%struc sir', /,
     2        '%init', /,
     3        '%job ', A, /,
     4        '%data', /,
     5        'cell ', 6F10.4, /,
     6        'space ', A)
99998 FORMAT ('cont', 11(1X, A, I4))
99997 FORMAT ('fosquare', /,
     1        'refl sir.hkl', /,
     2        'format (3i4, 2f8.0)', /,
     3        '%normal', /,
     3        '%fourier', /
     4        'fragment sir.frg', /,
     5        '%continue')
 
99996 FORMAT ('END')
99995 FORMAT ('TITL ', A, ' - EXORS', /, 'CELL ', F7.5, 6F10.4)
99994 FORMAT ('LATT ', I3)
99993 FORMAT ('SYMM ', A)
99992 FORMAT (A)
99991 FORMAT ('FVAR', A)
99990 FORMAT ('SFAC ', A, 1X, 5F12.5, ' =', /, 8X, 4F12.5, ' =',
     1        /, 8X, 5F12.5)
99989 FORMAT ('UNIT ', 2I5,14I4)
99988 FORMAT (/, A, /)
99979 FORMAT (/, '===>> run exorcise - sir', /)
99969 FORMAT ('C ', 3F10.4)
      END SUBROUTINE S301
 
      SUBROUTINE S302 (IERR)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: IN2
      INTEGER :: IN3
      INTEGER :: NAT
      INTEGER :: IPAT
      INTEGER :: IFN1
      INTEGER :: IERR
      INTEGER :: MODE
      INTEGER :: NUMS
      INTEGER :: IFVAR
      INTEGER :: NEXPMX
      INTEGER :: CHDIR
      REAL :: SJ
      REAL :: YY
      REAL :: RPI
      REAL, DIMENSION(12) :: XYZ
      REAL, DIMENSION(50) :: RP
      CHARACTER(len=2) :: WL
C * CHECK FOR DIRDIF AVAILABLE
      IF (IGBL(115) == 0) THEN
        CALL PLA015 (0, 14)
        IERR = 1
        RETURN
      END IF
C * ENTER LOG
      CALL S915 ('Run DIRDIF/EXORD')
      EXST     = .FALSE.
C * REGISTER EXORD-DONE
      ISPR(17) = 3
      I = 0
      CALL S930 (0, LINE(1:4), I)
C * CHECK FOR/CREATE-CHANGE TO EXORD-DIR UNDER user/s/compoundname/tm/sg/source
      MODE = ISPR(16)
      IF (MODE == 0) THEN
        IN2       = INZ + 18
        FNM(INZ + 1:IN2) = 'tm/sg/shelxl/exord'
      ELSE
        IN3 = ISTATB(MODE)
        IN2 = INZ + 12 + IN3
        FNM(INZ + 1:IN2) = 'tm/sg/'//SSTATB(MODE)(1:IN3)//'/exord'
      END IF
      CALL S909 (FNM(1:IN2))
C * CHECK/MAKE LINKS TO DATA
      WRITE (LU6, 99979, IOSTAT = IOST)
      NAT  = 0
      IPAT = 0
      NEXPMX = NINT (SPAR(107) / (15.0 * ISPR(102)))
C * ANALYSE LS, SHELXS, SIR, DIRDIF etc. RESULTS (s.res)
      OPEN (LU61, FILE = '../s.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 'atoms', STATUS = 'UNKNOWN')
      WRITE (LU62, 99988, IOSTAT = IOST)
      IFVAR = 0
   10 CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80, 10, NP17)
      IF (JFL(1)(1:4) == 'FVAR') THEN
        DO I = 1, KN
          RP(I) = FN(I)
        END DO
        RP(1) = 1.0
        IFVAR = 1
        GO TO 10
      ELSE IF (JFL(1)(1:4) == 'TITL') THEN
        IF (LINE(24:27) == 'PATT') IPAT = 1
        GO TO 10
      ELSE IF (JFL(1)(1:4) == 'MOLE') THEN
        RP(1) = 1.0
        IFVAR = 1
        GO TO 10
      ELSE IF (JFL(1)(1:3) == 'REM') THEN
        GO TO 10
      ELSE IF (JFL(1)(1:4) == 'AFIX') THEN
        GO TO 10
      ELSE IF (JFL(1)(1:3) == 'END') THEN
        GO TO 40
      ELSE IF (JFL(1)(1:3) == 'HKL') THEN
        GO TO 40
      ELSE IF (JFL(1)(1:3) == 'EOF') THEN
        GO TO 40
      ELSE IF (JFL(1)(1:4) == 'PLAN') THEN
        IF (IPAT == 1) THEN
          READ (LU61, '(A)') LINE
          IFVAR = 1
        END IF
        GO TO 10
      ELSE IF (IFVAR == 1 .AND. KN >= 4) THEN
        NAT = NAT + 1
C * HANDLE FREE VARIABLES
        DO K = 2, 4
          YY = FN(K)
          IF (ABS (YY) > 5.0) THEN
            I = NINT (ABS (YY) * 0.1)
            RPI = RP(I)
            SJ = SIGN (0.5, YY)
            YY = (YY - I * SJ * 20.0) * (RPI + SJ - 0.5)
          END IF
          FN(K) = YY
        END DO
        IF (NAT <= NEXPMX) THEN
          IF (JFL(1)(1:1) == 'Q') JFL(1)(1:1) ='C'
          WRITE (LU62, 99969, IOSTAT = IOST) JFL(1), (FN(I), I = 2, 4)
        END IF
      END IF
      GO TO 10
   40 WRITE (LU62, 99996, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
C * PREPARE DIRDIF08 - JOB
      OPEN  (LU61, FILE = 'crysin', STATUS = 'UNKNOWN')
      WRITE (LU61, 99999, IOSTAT = IOST) (SPAR(100 + I), I = 1, 6),
     1                    (SPAR(107 + I), I = 1, 6), CPR(101)
      WRITE (LU61, 99998, IOSTAT = IOST)
     1  (SFAC(I), ISPR(I + 120), I = 1, ISPR(110))
      IF (SPAR(80) > 1.0) THEN
        WL = 'CU'
      ELSE
        WL = 'MO'
      END IF
      WRITE (LU61, 99997, IOSTAT = IOST)
     1  WL, ((TM(I, J), J = 1, 3), I = 1, 3)
      CLOSE (UNIT = LU61)
      INQUIRE (FILE = 'drdf.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../../s.hkl drdf.hkl', 0, .true., KERR)
      END IF
C * SPAWN DIRDIF JOB
      KERR = 0
      CALL SPAWN (DIRPATH//' PHASEX > df.log 2> df.log', 0, .true.,
     1  KERR)
C * TEST FOR ERRORS: READ df.log
      OPEN (LU61, FILE = 'df.log', STATUS = 'UNKNOWN')
   50 READ (LU61, 99990, IOSTAT = IOST) LINE
      IF (IOST == -1) GO TO 60
      IF (INDEX (LINE(1:20), 'ERROR') /= 0) THEN
        GO TO 60
      ELSE
        IF (INDEX (LINE, 'DRDF.res') == 0 .AND.
     1      INDEX (LINE, 'drdf.res') == 0) GO TO 50
        GO TO 70
      END IF
   60 CALL PLA015 (0, 13)
      IERR  = 1
   70 CLOSE (UNIT = LU61)
      IF (IERR == 0) THEN
C * GENERATE s.res file from DIRDIF-Result File (on drdf.res)
        IFVAR = 0
        OPEN (LU61, FILE = 'drdf.res', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 's.res', STATUS = 'UNKNOWN')
        WRITE (LU62, 99995, IOSTAT = IOST) TITL(1:6), SPAR(80),
     1                      (SPAR(100 + I), I = 1, 6)
C * SFAC/UNIT
        WRITE (LU62, 99986, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
        WRITE (LU62, 99989, IOSTAT = IOST)
     1    (ISPR(I + 120), I = 1, ISPR(110))
        WRITE (LU62, 99994, IOSTAT = IOST) ISPR(100)
        DO I = 2, ISPR(101)
          NUMS = I
          CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
          WRITE (LU62, 99993, IOSTAT = IOST) LINE(1:60)
        END DO
C * COPY COORDINATES
   90   READ  (LU61, 99990, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 110
        IF (LINE(1:4) == 'FVAR') THEN
          IFVAR = 1
          GO TO 100
        END IF
C * SKIP 'BLANK' LINES
        IF (LINE(1:1) == ' ') GO TO 90
        IF (LINE(1:4) == 'HKLF') GO TO 90
        IF (LINE(1:3) == 'END') THEN
          WRITE (LU62, 99992, IOSTAT = IOST)
     1      ((TM(I, J), J = 1, 3), I = 1, 3)
          GO TO 100
        END IF
        IF (IFVAR == 1) THEN
          READ (LINE, 99991) IFN1
          IF (SFAC(IFN1) == 'H ') GO TO 90
          CALL S930 (1, LINE(1:4), I)
        ELSE
          GO TO 90
        END IF
  100   WRITE (LU62, 99990, IOSTAT = IOST) LINE
        GO TO 90
  110   CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN ('cp s.res ../../s.res', 0, .true., KERR)
        CPR(204) = 'EXORD'
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
        IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * SHOW RESULT
        ISPR(6)  = 0
        CPR(105) = 'EXORD'
        CPR(106) = CPR(200)
        IF (IGBL(50) == 0) CALL S410 (0)
      END IF
      RETURN
99999 FORMAT ('CRYSIN drdf', /, 'TITLE ', /,
     1        'CELL ', 6F10.4, /, 'CELLSD ', 6F10.4, /,
     2 'SPGR ', A)
99998 FORMAT ('FORMUL', 11(1X, A, I4))
99997 FORMAT ('Z    1', /, 'WAVE ', A, /,
     1        'HKLF 4 1', 9F7.4, /,  'END')
99996 FORMAT ('END')
99995 FORMAT ('TITL ', A, ' - EXORD', /, 'CELL ', F7.5, 6F10.4)
99994 FORMAT ('LATT ', I3)
99993 FORMAT ('SYMM ', A)
99992 FORMAT ('HKLF 4 1', 9F7.4)
99991 FORMAT (7X, I2)
99990 FORMAT (A)
99986 FORMAT ('SFAC ', 16(A, 1X))
99989 FORMAT ('UNIT ', 2I5,14I4)
99988 FORMAT ('ATOMS drdf')
99979 FORMAT (/, '===>> run exorcise - dirdif08', /)
99969 FORMAT ('ATOM ', A, 3F10.4)
      END SUBROUTINE S302
 
      SUBROUTINE S305 (ICTEST, NLOOP)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: M
      INTEGER :: N
      INTEGER :: M0
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: NSC
      INTEGER :: NTX
      INTEGER :: NVR
      INTEGER :: NLP
      INTEGER :: NTXT
      INTEGER :: NSAT
      INTEGER :: NCHG
      INTEGER :: NLABL
      INTEGER :: MLABL
      INTEGER :: NLOOP
      INTEGER :: NPSCL
      INTEGER :: NSCAT
      INTEGER :: ICTEST
      INTEGER :: CHDIR
      INTEGER, DIMENSION(3, 16)  :: LPPSCL
      INTEGER, DIMENSION(2, 500) :: NATRP
      REAL :: X
      REAL :: Y
      REAL :: R1
      REAL :: WR2
      REAL :: STL
      REAL :: STLMN
      REAL :: RCOMB1
      REAL :: RCOMB2
      REAL :: GEN095
      CHARACTER(len=80) :: TXRES
      CHARACTER(len=80) :: TXRES1
      CHARACTER(len=16) :: OBSSIG
      CHARACTER(len=40) :: TEXT
      CHARACTER(len=4)  :: NEWLAB
      CHARACTER(len=80), DIMENSION(520) :: STEXT
      CALL S915 ('Run ELTREF')
      TEXT = ' '
C * CHECK FOR/CREATE-CHANGE TO eltref-DIR UNDER user/s/compoundname/tm/sg
      CALL S909 ('tm/sg/eltref')
C * OMIT INNER REFLECTION SPHERE
      STLMN = FN(1)
C * INITIALIZE ATOM TYPE TEST ARRAY
      DO J = 1, 16
        DO I = 1, 3
          LPPSCL(I, J) = 0
        END DO
      END DO
C * IDENTIFY ATOM TYPES TO BE TESTED
      DO I = 1, ISPR(110)
        IF (SFAC(I) == 'C ' .AND. ICTEST /= 0) THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'B ' .OR. SFAC(J) == 'N ') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        ELSE IF (SFAC(I) == 'N ') THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'O ' .OR. SFAC(J) == 'C ') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        ELSE IF (SFAC(I) == 'O ') THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'N ' .OR. SFAC(J) == 'F ') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        ELSE IF (SFAC(I) == 'F ') THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'O ') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        ELSE IF (SFAC(I) == 'P ') THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'SI' .OR. SFAC(J) == 'S ') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        ELSE IF (SFAC(I) == 'S ') THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'P ' .OR. SFAC(J) == 'CL') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        ELSE IF (SFAC(I) == 'CL') THEN
          NPSCL        = 1
          LPPSCL(1, I) = I
          DO J = 1, ISPR(110)
            IF (SFAC(J) == 'S ') THEN
              NPSCL            = NPSCL + 1
              LPPSCL(NPSCL, I) = J
            END IF
          END DO
        END IF
      END DO
C * CHECK/LINK TO s.hkl
      IF (STLMN > 0.0) THEN
        KERR = 0
        CALL SPAWN ('ln -s -f ../s.hkl s.hkl', 0, .true., KERR)
        OPEN (LU61, FILE = 's.hkl', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 'shelxl.hkl', STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99992, IOSTAT = IOST) IH, IK, IL, OBSSIG
          IF (IOST /= 0) GO TO 10
          IF (IH == 0 .AND. IK == 0 .AND. IL == 0) GO TO 10
          STL = SQRT (GEN095 (SPAR(95), IH, IK, IL))
          IF (STL > STLMN) WRITE (LU62, 99992, IOSTAT = IOST)
     1      IH, IK, IL, OBSSIG
        END DO
   10   WRITE (LU62, 99990, IOSTAT = IOST)
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
      ELSE
        KERR = 0
        CALL SPAWN ('ln -s -f ../s.hkl shelxl.hkl', 0, .true., KERR)
      END IF
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.res s.res', 0, .true., KERR)
C * REPEAT ELTREF LOOP TWICE
      DO NLP = 1, NLOOP
C * LOAD CURRENT .RES IN CTEXT ARRAY
        IF (NLP == 1) THEN
          OPEN (LU61, FILE = 's.res', STATUS = 'UNKNOWN')
        ELSE
          OPEN (LU61, FILE = 'shelxl.res', STATUS = 'UNKNOWN')
        END IF
        NTXT = 1
        NVR  = 0
        NSAT = 0
        NCHG = 0
        DO
          READ (LU61, 99999, IOSTAT = IOST) STEXT(NTXT)
          IF (IOST /= 0) EXIT
          IF (STEXT(NTXT)(1:4) == 'HKLF') EXIT
          IF (STEXT(NTXT)(1:4) /= 'REM ' .AND.
     1        STEXT(NTXT)(1:4) /= 'AFIX' .AND.
     2        STEXT(NTXT)(1:4) /= 'BLOC') THEN
            IF (STEXT(NTXT)(1:4) == 'FVAR') THEN
              NVR = 1
            ELSE IF (NVR /= 0) THEN
              IF (STEXT(NTXT)(1:4) /= '    ') THEN
C * GET SCATTERING TYPE FOR THIS ATOM
                READ (STEXT(NTXT)(6:7), 99993) NSCAT
C * DETERMINE WHETHER THERE IS A REGISTRATED ALTERNATIVE SCAT TYPE TO TEST
                IF (LPPSCL(2, NSCAT) /= 0) THEN
                  NSAT = NSAT + 1
                  IF (NSAT > 500) GO TO 90
                  NATRP(1, NSAT) = NTXT
                  NATRP(2, NSAT) = NSCAT
                END IF
              END IF
            END IF
            NTXT = NTXT + 1
            IF (NTXT > 520) GO TO 90
          END IF
        END DO
        CLOSE (UNIT = LU61)
C * LOOP OVER ATOMS TO BE TESTED FOR ELEMENT TYPE
        IF (NSAT > 0) THEN
          NLABL = 0
          MLABL = 0
          DO I = 1, NSAT
            NTX    = NATRP(1, I)
            NSC    = NATRP(2, I)
            RCOMB1 = 100.0
            RCOMB2 = 100.0
            M0     = 0
            TXRES1 = ' '
            DO J = 1, 3
              M = LPPSCL(J, NSC)
              IF (M /= 0) THEN
                WRITE (STEXT(NTX)(6:7), 99993, IOSTAT = IOST) M
                OPEN (LU61, FILE = 'shelxl.ins', STATUS = 'UNKNOWN')
                DO 30 K = 1, NTXT
                  IF (STEXT(K)(1:4) == 'ACTA') GO TO 30
                  IF (STEXT(K)(1:4) == 'PLAN') GO TO 30
                  IF (STEXT(K)(1:4) == 'BLOC') GO TO 30
                  IF (STEXT(K)(1:4) == 'FVAR')
     1              WRITE (LU61, 99991, IOSTAT = IOST) STEXT(NTX)(1:4)
                  WRITE (LU61, 99999, IOSTAT = IOST) STEXT(K)
   30           CONTINUE
                CLOSE (UNIT = LU61)
C * RUN SHELXL REFINEMENT
                KERR = 0
                CALL SPAWN (SHLPATH//' shelxl > shelxl.log', 0, .true.,
     1            KERR)
                OPEN (LU61, FILE = 'shelxl.log', STATUS = 'UNKNOWN')
C * ANALYSE RESULT
                DO
                  READ (LU61, 99999, IOSTAT = IOST) LINE
                  IF (IOST == -1) GO TO 60
                  N = INDEX (LINE, 'wR2 =')
                  IF (N /= 0) THEN
                    READ(LINE(N+5:N+13), *, IOSTAT = IOST) WR2
                    CYCLE
                  END IF
                  N = INDEX (LINE, 'R1 =')
                  IF (N > 0) THEN
                    READ(LINE(N+4:N+12), *, IOSTAT = IOST) R1
                    EXIT
                  END IF
                END DO
                IF (IGBL(50) == 1) THEN
                  X = HORS - 13.0
                  Y = VERT - 4.5
                ELSE
                  X = HORS - 11.0
                  Y = 0.3 * VERT
                END IF
                CALL PLA439 (0.0, TEXT, 40, 0.30, 0, 1, X, Y)
                WRITE (TEXT, 99994, IOSTAT = IOST)
     1            NLP, I, J - 1, STEXT(NTX)(1:4), R1, WR2
                CALL PLA439 (0.0, TEXT, 40, 0.30, 1, 1, X, Y)
                CALL GGIP (0.0, 0.0, 0.0, 6)
                IF (R1  < RCOMB1 .AND. WR2 < RCOMB2 ) THEN
                  RCOMB1 = R1
                  RCOMB2 = WR2
                  M0     = M
                  OPEN (LU62, FILE = 'shelxl.res', STATUS = 'UNKNOWN')
                  DO
                    READ (LU62, 99999) TXRES
                    N = INDEX (TXRES, '=')
                    IF (N /= 0) READ (LU62, 99999) TXRES1
                    IF (STEXT(NTX)(1:4) == TXRES(1:4)) GO TO 50
                  END DO
   50             CLOSE (UNIT = LU62)
                END IF
   60           CLOSE (UNIT = LU61)
              END IF
            END DO
            STEXT(NTX) = TXRES
            IF (INDEX (TXRES, '=') /= 0)  STEXT(NTX + 1) = TXRES1
            IF (M0 == NATRP(2, I)) THEN
              WRITE (STEXT(NTX)(6:7), 99993, IOSTAT = IOST) M0
            ELSE
   70         IF (SFAC(M0)(2:2) == ' ') THEN
                NLABL = NLABL + 1
                WRITE (NEWLAB, 99998, IOSTAT = IOST)
     1            SFAC(M0)(1:1), 500 + NLABL
              ELSE
                MLABL = MLABL + 1
                WRITE (NEWLAB, 99997, IOSTAT = IOST)
     1            SFAC(M0)(1:2), 50 + MLABL
              END IF
              DO J = 1, NTXT
                IF (STEXT(J)(1:4) == NEWLAB) GO TO 70
              END DO
              NCHG = NCHG + 1
              WRITE (STEXT(NTX)(1:7), 99998, IOSTAT = IOST) NEWLAB, M0
            END IF
          END DO
          OPEN (LU61, FILE = 'shelxl.ins', STATUS = 'UNKNOWN')
          DO K = 1, NTXT
            IF (STEXT(K)(1:4) /= 'BLOC')
     1        WRITE (LU61, 99999, IOSTAT = IOST) STEXT(K)
          END DO
          CLOSE (UNIT = LU61)
C * RUN REFINEMENT
          KERR = 0
          CALL SPAWN (SHLPATH//' shelxl > shelxl.log', 0, .true., KERR)
        ELSE
          GO TO 90
        END IF
        IF (NCHG == 0) GO TO 80
      END DO
C * CREATE NEW DATA CONTEXT pn
   80 CALL S924 (0)
      KERR = 0
      CALL SPAWN ('cp shelxl.res ../pn/s.res',      0, .true., KERR)
      CALL SPAWN ('cp shelxl.lst ../pn/shelxl.lst', 0, .true., KERR)
      CALL SPAWN ('cp shelxl.cif ../pn/shelxl.cif', 0, .true., KERR)
      CALL SPAWN ('cp shelxl.fcf ../pn/shelxl.fcf', 0, .true., KERR)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
   90 IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      IF (IGBL(50) == 0) CALL S410(0)
      RETURN
99999 FORMAT (A)
99998 FORMAT (A, I3)
99997 FORMAT (A, I2)
99994 FORMAT (I1, ',', I3, ',', I1, 1X, A, 2F10.4)
99993 FORMAT (I2)
99992 FORMAT (3I4, A)
99991 FORMAT ('BLOC 1 -1 ', A)
99990 FORMAT (1X)
      END SUBROUTINE S305
 
      SUBROUTINE S310 (ICGLS, IERR)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: N1
      INTEGER :: J1
      INTEGER :: NDF
      INTEGER :: NLS
      INTEGER :: NUMS
      INTEGER :: NDEL
      INTEGER :: ITEL
      INTEGER :: ISF1
      INTEGER :: ISF2
      INTEGER :: ICOP
      INTEGER :: IERR
      INTEGER :: MODE
      INTEGER :: IEND
      INTEGER :: IVAR
      INTEGER :: IYUNK
      INTEGER :: ICGLS
      INTEGER :: GEN135
      INTEGER :: CHDIR
      REAL :: W1
      REAL :: W2
      REAL :: W3
      REAL :: W4
      REAL :: W13
      REAL :: W24
      REAL :: UISO
      REAL, DIMENSION(12) :: XYZ
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=2)  :: LTYPE
      CHARACTER(len=12) :: SGXX1
      CHARACTER(len=17) :: SGXX2
      W3 = 0.0
      W4 = 0.0
C * CHECK ACCESSIBILITY OF SHELXL
      IF (IGBL(110) == 0) THEN
        CALL PLA015 (0, 29)
        IERR = 1
        RETURN
      END IF
      CALL GEN038 (PROBLEM, 1, 80)
C * SET STRUCTURE DETERMINATION PHASE TO REFINEMENT STAGE
      ISPR(11) = 5
C * DETERMINE NEW REFINEMENT MODE
      MODE = MAX (1, ISPR(6) + ISPR(7))
      IF (MODE == 1) THEN
        CPR(106) = 'ISO'
      ELSE IF (MODE == 2) THEN
        CPR(106) = 'ANISO'
      ELSE IF (MODE == 3) THEN
        CPR(106)  = 'HATS  '
        ISPR(215) = 0
      ELSE IF (MODE == 4) THEN
        CPR(106) = 'WEIGHT'
      ELSE
        CPR(106) = CPR(200)
      END IF
C * GET NUMBER OF LEAST-SQUARES CYCLES
      IF (KN > 0) THEN
        NLS = NINT (FN(1))
      ELSE
          NLS = 5
      END IF
C * CHECK FOR/CREATE-CHANGE TO SHELXL-DIR UNDER user/s/compoundname/tm/sg
      CALL S909 ('tm/sg/shelxl')
C * CHECK/LINK TO s.hkl
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl '//COMPD(1:IC)//'.hkl', 0, .true.,
     1  KERR)
      CALL SPAWN ('ln -s -f ../s.res s.res',                 0, .true.,
     1  KERR)
C * CHECK WHETHER shelxl_pl.res and s.res DIFFER
      KERR = 0
      CALL SPAWN ('rm -f diff.lis', 0, .true., KERR)
      INQUIRE (FILE = 'shelxl_pl.res', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('diff shelxl_pl.res save.res > diff.lis', 0, .true.,
     1    KERR)
        OPEN (LU61, FILE = 'diff.lis', STATUS = 'UNKNOWN')
        READ (LU61, 99972, IOSTAT = IOST) LINE
        IF (IOST /= 0) GO TO 10
        WRITE (BCD, 99972, IOSTAT = IOST)
     1'shelxl_pl.res and s.res differ ! Use shelxl.res (y/n[y]'//CHAR(0)
        CALL GGIP (-999.0, 5.0 + FLOAT (IGBL(68) * IGBL(82)), 80.0, 110)
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IF (IGGT(1:1) == 'Y') THEN
          KERR = 0
          CALL SPAWN ('cp shelxl_pl.res s.res', 0, .true., KERR)
        END IF
        CLOSE (UNIT = LU61)
        GO TO 20
   10   CLOSE (UNIT = LU61, STATUS = 'DELETE')
      END IF
C * CHECK s.res
   20 ITEL = 0
      OPEN (LU61, FILE = 's.res', STATUS = 'UNKNOWN')
      DO
        CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 0, 1, 80, 10,
     1               NP17)
        IF (JFL(1)(1:3) == 'EOF') THEN
          IF (ITEL < 2) THEN
            PROBLEM = 'FILE s.res EMPTY or INCOMPLETE'
            NDF = 0
            GO TO 200
          ELSE
            EXIT
          END IF
        END IF
        ITEL = ITEL + 1
      END DO
      CLOSE (UNIT = LU61)
C * CONVERT s.res FORMAT TO shelxl.ins AT START OF REFINEMENT PROCEDURE
      IF (ISPR(6) == 0 .OR. MODE == 2) THEN
        OPEN (LU61, FILE = 's.res',      status = 'unknown')
        OPEN (LU62, FILE = 'shelxl.ins', status = 'unknown')
C * USE PLATON TO GENERATE PROPERLY SORTED FILE FOR SHELXL
        DO
          READ (LU61, 99972, IOSTAT = IOST) LINE
          IF (IOST /= 0) GO TO 40
C * TRANSFORM TO UPPER CASE
          CALL GEN020 (1, LINE, 1, 80)
C * SKIP SFAC + CONTINUATION LINES
          IF (LINE(1:4) == 'SFAC') THEN
   30       IF (INDEX (LINE, '=') /= 0) THEN
              READ (LU61, 99972, IOSTAT = IOST) LINE
              IF (IOST /= 0) GO TO 40
              GO TO 30
            END IF
            CYCLE
          END IF
          IF (LINE(1:4) == 'UNIT') CYCLE
          IF (LINE(1:4) == 'ZERR') CYCLE
          IF (LINE(1:3) == 'END')  GO TO 40
          IF (LINE(1:4) == 'FVAR') THEN
            WRITE (LU62, 99995, IOSTAT = IOST)
            CYCLE
          END IF
          IF (LINE(1:1) == 'Q') THEN
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, 0, 1, 1, 0, 10, NP17)
            IF (SFAC(1)(2:2) == ' ') THEN
              JFL(1)(1:1) = SFAC(1)(1:1)
            ELSE
              JFL(1)(1:2) = SFAC(1)
            END IF
            FN(1) = 1
            WRITE (LU62, '(A, I5, 6F10.4)', IOSTAT = IOST)
     1        JFL(1), NINT (FN(1)),(FN(I), I = 2, KN)
          ELSE
            WRITE (LU62, 99972, IOSTAT = IOST) LINE
          END IF
          IF (LINE(1:4) == 'CELL') THEN
            WRITE (LU62, 99988, IOSTAT = IOST)
     1        ISPR(120), (SPAR(I), I = 108, 113)
C * SFAC/UNIT
            WRITE (LU62, 99993, IOSTAT = IOST)
     1        (SFAC(I), I = 1, ISPR(110))
            WRITE (LU62, 99992, IOSTAT = IOST)
     1        (ISPR(I + 120), I = 1, ISPR(110))
          END IF
        END DO
   40   WRITE (LU62, 99999, IOSTAT = IOST)
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' shelxl.ins > shelxl.log',
     1    0, .true., KERR)
        CALL SPAWN ('cp shelxl_pl.res s.res', 0, .true., KERR)
        CALL SPAWN ('rm -f shelxl.log',       0, .true., KERR)
        IF (ISPR(6) == 0) ISPR(6) = 1
      END IF
C * WEIGHT OPTIMIZATION (MODE = 4)
      W1   = 0.1
      W2   = 0.0
      IF (MODE == 4) THEN
        IEND = 0
        OPEN (LU61, FILE = 's.res', status = 'unknown')
        DO
          CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 0, 1, 80, 10,
     1                 NP17)
          IF (JFL(1)(1:3) == 'EOF') EXIT
          IF (LINE(1:3) == 'END') THEN
            IEND = 1
          ELSE IF (LINE(1:4) == 'WGHT') THEN
            IF (IEND == 1) THEN
C * AFTER END
              W1 = FN(1)
              W2 = FN(2)
              EXIT
            END IF
          END IF
        END DO
        CLOSE (UNIT = LU61)
      END IF
C * FILTER s.res TO shelxl.ins
      OPEN (LU61, FILE = 's.res',      status = 'unknown')
      OPEN (LU62, FILE = 'shelxl.ins', status = 'unknown')
      IVAR = 0
   50 READ (LU61, 99972, IOSTAT = IOST) LINE
      IF (IOST /= 0) GO TO 100
      CALL GEN020 (1, LINE, 1, 4)
      IF (LINE(1:4) == 'TITL') THEN
        WRITE (LU62, 99990, IOSTAT = IOST) TITL(1:6)
        GO TO 50
C * ADAPT SFAC/UNIT LINES
      ELSE IF (LINE(1:4) == 'SFAC') THEN
   60   IF (INDEX (LINE, '=') /= 0) THEN
          READ (LU61, 99972, IOSTAT = IOST) LINE
          IF (IOST /= 0) GO TO 100
          GO TO 60
        END IF
        GO TO 50
      ELSE IF (LINE(1:4) == 'UNIT') THEN
        WRITE (LU62, 99993, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
        WRITE (LU62, 99992, IOSTAT = IOST)
     1    (ISPR(I + 120), I = 1, ISPR(110))
        GO TO 50
      ELSE IF (LINE(1:4) == 'SPGR') THEN
        CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 0, 1, 80, 10, NP17)
C * TRANFER FRIEDEL INVERT
        IF (KN == 4) THEN
          DO I = 1, 4
            SPAR(159 + I) = FN(I)
          END DO
        END IF
        WRITE (LU62, 99986, IOSTAT = IOST) ISPR(100)
        DO I = 2, ISPR(101)
          NUMS = I
          CALL SGSM (17, LINE, XYZ, NUMS, 0, IERR)
          WRITE (LU62, 99985, IOSTAT = IOST) LINE(1:60)
        END DO
      ELSE IF (LINE(1:4) == 'FVAR') THEN
        IVAR = 1
        WRITE (LU62, 99989, IOSTAT = IOST) W1, W2
        GO TO 70
      ELSE IF (LINE(1:4) == 'RESI') THEN
        GO TO 50
      END IF
      IF (IVAR == 1) THEN
C * CHECK FOR HFREE
        IF (LINE(1:4) == 'AFIX') THEN
          IF (ISPR(90) == 1) THEN
            GO TO 50
          ELSE
            GO TO 90
          END IF
        END IF
        IF (LINE(1:4) == 'HFIX') GO TO 90
C * ADAPT SCATTERING TYPE FROM PLATON TO S SFAC-TYPE
        LTYPE = LINE(1:1)//' '
        IF (LTYPE /= '  ') THEN
          CALL GEN105 (1, LINE(2:2), J)
          IF (J > 0) LTYPE = LINE(1:2)
          DO K = 1, ISPR(110)
            IF (LTYPE == SFAC(K)) EXIT
          END DO
C * REPLACE SCATTERING TYPE
          ISF1 = K / 10
          ISF2 = MOD (K, 10)
          DO J = 6, 20
            IF (LINE(J : J) /= ' ') THEN
              J1 = J
              IF (LINE(J + 1:J + 1) /= ' ') THEN
                J1 = J1 + 1
                LINE (J : J1) = '  '
              END IF
              LINE(J1 : J1) = CHAR (ICHAR ('0') + ISF2)
              IF (ISF1 /= 0) LINE(J : J) = '1'
              EXIT
            END IF
          END DO
        END IF
      END IF
   70 SELECT CASE (LINE(1:4))
        CASE ('L.S.', 'CGLS')
          GO TO 50
        CASE ('ZERR')
          WRITE (LU62, 99988, IOSTAT = IOST)
     1      ISPR(120), (SPAR(I), I = 108, 113)
          GO TO 50
        CASE ('FMAP', 'EXTI', 'TEMP', 'SIZE')
          GO TO 50
        CASE ('TWIN', 'BASF', 'MERG')
          GO TO 50
        CASE ('OMIT')
          CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 0, 1, 80, 10,
     1                 NP17)
          IF (KN < 3) THEN
            GO TO 50
          ELSE IF (KN == 3) THEN
            IF (IGBL(51) == 0) GO TO 50
          END IF
        CASE ('PLAN', 'ACTA', 'REM ', 'BOND')
          GO TO 50
        CASE ('CONF', 'HTAB')
          GO TO 50
        CASE ('HKLF', 'END ')
          GO TO 100
        CASE ('FVAR')
          IF (IGBL(51) > 0) THEN
            INQUIRE (FILE = 'omit.hkl', EXIST = EXST)
            IF (EXST) THEN
              OPEN (LU63, FILE = 'omit.hkl', STATUS = 'UNKNOWN')
              DO
                READ (LU63, 99972, IOSTAT = IOST) LIJN
                IF (IOST /= 0) GO TO 80
                WRITE (LU62, 99972, IOSTAT = IOST) LIJN
              END DO
   80         CLOSE (UNIT = LU63, STATUS = 'DELETE')
            END IF
          END IF
          IF (SPAR(227) > -1.0 .AND. IGBL(96) == 1) THEN
            WRITE (LU62, 99982, IOSTAT = IOST) SPAR(227)
          END IF
          IF (ISPR(310) > 0) THEN
            WRITE (LU62, 99980, IOSTAT = IOST)
     1        (ISPR(310 + I), I = 1, 9), SPAR(229)
          ELSE IF (ISPR(310) < 0) THEN
            WRITE (LU62, 99978, IOSTAT = IOST) SPAR(229)
          END IF
          IF (ISPR(14) == 8) THEN
            WRITE (LU62, 99970, IOSTAT = IOST) 0.0
          END IF
          WRITE (LU62, 99984, IOSTAT = IOST) 2 * SPAR(55)
          IF (SPAR(10) /= 0.0)
     1      WRITE (LU62, 99983, IOSTAT = IOST) SPAR(10) - 273
          WRITE (LU62, 99981, IOSTAT = IOST) (SPAR(I), I = 11, 13)
C * SET # FOURIER PEAKS IN PEAK SEARCH
          IF (NLS > 0 .AND. ICGLS == 0) THEN
            WRITE (LU62, 99994, IOSTAT = IOST) - (IGBL(124) + 1) * 30
          ELSE
            WRITE (LU62, 99991, IOSTAT = IOST)  - (IGBL(124) + 1) * 30
          END IF
C * MERG 2 / NO FLACK
          IF (ISPR(14) == 8) THEN
            N = 0
          ELSE
            N = 2
          END IF
          IF (MODE >= 3) THEN
            IF (IGBL(91) == 1) THEN
              WRITE (LU62, 99971, IOSTAT = IOST) N
              SPAR(225) = -1000.0
            END IF
          END IF
C * BOND $H, CONF, HTAB
          IF (MODE >= 4) THEN
            WRITE (LU62, 99979, IOSTAT = IOST)
          END IF
          IF (ICGLS == 1) THEN
            WRITE (LU62, 99977, IOSTAT = IOST) NLS
          ELSE
            WRITE (LU62, 99976, IOSTAT = IOST) NLS
          END IF
          WRITE (LU62, 99998, IOSTAT = IOST) SPAR(160), SPAR(161),
     1                        SPAR(162), SPAR(163)
C * ANISOTROPIC REFINEMENT ( MODE = 2)
          IF (MODE == 2) WRITE (LU62, 99996, IOSTAT = IOST) 1000
      END SELECT
   90 WRITE (LU62, 99972, IOSTAT = IOST) LINE
      GO TO 50
C * HKLF/END
  100 IF (ISPR(14) == 8) THEN
        N = 5
      ELSE
        N = 4
      END IF
C * TEST FOR UNIT MATRIX
      IF (GEN135 (TM) == 1 .OR. N == 5) THEN
        WRITE (LU62, 99973, IOSTAT = IOST) N
      ELSE
        WRITE (LU62, 99997, IOSTAT = IOST)
     1    N, ((TM(I, J), J = 1, 3), I = 1, 3)
      END IF
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
 
C * RESET MOVE INSTRUCTION
      SPAR(160) = 0.0
      SPAR(161) = 0.0
      SPAR(162) = 0.0
      SPAR(163) = 1.0
C * OPTIONALLY EDIT SHELXL-INPUT
      IF (IGBL(44) == 1) THEN
        KERR = 0
        CALL SPAWN (EDITOR//' shelxl.ins', 0, .true., KERR)
      END IF
C * RUN SHELXL REFINEMENT
  110 KERR = 0
      CALL SPAWN ('cp shelxl.ins '//COMPD(1:IC)//'.ins',      0, .true.,
     1  KERR)
      CALL SPAWN (SHLPATH//' '//COMPD(1:IC)//' > shelxl.log', 0, .true.,
     1  KERR)
C * CHECK FOR ERRORS & WARNINGS
      OPEN (LU61, FILE = 'shelxl.log', status = 'unknown')
      DO
        READ (LU61, 99972, IOSTAT = IOST) LINE
        IF (IOST /= 0) GO TO 120
        IYUNK = 0
        IF (LINE(1:4) == ' ** ') THEN
          IYUNK = 4
        END IF
        IF (IYUNK > 0) THEN
          CALL GEN020 (1, LINE, IYUNK + 1 , 80)
          IF (LINE(IYUNK + 1:IYUNK + 7) == 'WARNING' .OR.
     1        LINE(IYUNK + 1:IYUNK + 8) == 'ABSOLUTE' .OR.
     2        LINE(IYUNK + 1:IYUNK +10) == 'EXTINCTION' .OR.
     3        LINE(IYUNK + 1:IYUNK +13) == 'CELL CONTENTS' .OR.
     4        LINE(IYUNK + 1:IYUNK +18) == 'POSSIBLE INVERSION') THEN
            CYCLE
          ELSE
            PROBLEM = 'SHELXL WARNING:'//LINE(1:50)
            N = INDEX (LINE, 'REFINEMENT UNSTABLE')
            IF (N /= 0) THEN
              IGBL(50) = 0
              IERR     = 1
              NDF      = 0
              GO TO 200
            END IF
            N = INDEX (LINE, 'BAD AFIX')
            IF (N /= 0) THEN
              IGBL(50) = 0
              IERR     = 1
              NDF      = 0
              GO TO 200
            END IF
            IF (LINE(5:8) == 'Exti' .OR.
     1         LINE(14:20) == 'racemic') THEN
              IF (LINE(14:20) == 'racemic') THEN
                IF (ISPR(310) == 0) ISPR(310) = -1
              END IF
              CYCLE
            ELSE
              NDF = 0
              CALL PLA015 (0, 38)
C * HFIX PROBLEM
              IF (INDEX (LINE, 'NOT BONDED') /= 0) THEN
                ISPR(6) = 5
              END IF
              CLOSE (UNIT = LU61)
              GO TO 200
            END IF
          END IF
        END IF
      END DO
  120 CLOSE (UNIT = LU61)
C *
      KERR = 0
      CALL SPAWN ('mv '//COMPD(1:IC)//'.res shelxl_pl.res', 0, .true.,
     1  KERR)
      CALL SPAWN ('mv '//COMPD(1:IC)//'.cif shelxl.cif',    0, .true.,
     1  KERR)
      CALL SPAWN ('mv '//COMPD(1:IC)//'.fcf shelxl.fcf',    0, .true.,
     1  KERR)
      CALL SPAWN ('mv '//COMPD(1:IC)//'.lst shelxl.lst',    0, .true.,
     1  KERR)
      CALL SPAWN ('rm -f '//COMPD(1:IC)//'.ins',            0, .true.,
     1  KERR)
      CALL SPAWN ('ln -s -f ../s.hkl shelxl.hkl',           0, .true.,
     1  KERR)
C * CHECK FOR WEIGHT RECYCLING
      W1   = 0.1
      W2   = 0.0
      ITEL = 0
      IEND = 0
      IVAR = 0
      NDEL = 0
      OPEN (LU61, FILE = 'shelxl_pl.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 'shelxl.ins', STATUS = 'UNKNOWN')
      DO
        CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 0, 1, 80, 10,
     1               NP17)
        IF (JFL(1)(1:3) == 'EOF') THEN
          IF (ITEL < 2) THEN
            PROBLEM = 'FILE shelxl_pl.res EMPTY or INCOMPLETE'
            GO TO 200
          ELSE
            GO TO 140
          END IF
        END IF
        ITEL = ITEL + 1
        IF (LINE(1:3) == 'END') THEN
          IEND = 1
        ELSE IF (LINE(1:4) == 'WGHT') THEN
          IF (IEND == 0) THEN
C * BEFORE END LINE
            W3 = FN(1)
            W4 = FN(2)
            SPAR(220) = W3
            SPAR(221) = W4
          ELSE
C * AFTER END LINE
            W1 = FN(1)
            W2 = FN(2)
            SPAR(222) = W1
            SPAR(223) = W2
            GO TO 140
          END IF
        ELSE IF (LINE(1:4) == 'FVAR') THEN
          IVAR = 1
          GO TO 130
        ELSE IF (LINE(1:4) == 'L.S.') THEN
          LINE = 'L.S. 5'
        ELSE IF (LINE(1:4) == 'HKLF') THEN
          GO TO 130
        ELSE IF (LINE(1:4) == '    ') THEN
          CYCLE
        ELSE IF (LINE(1:4) == 'REM ') THEN
          CYCLE
        END IF
        IF (MODE == 1 .AND. IVAR == 1 .AND. IPR(591) == 0) THEN
          READ (LINE(56:66), 99969) UISO
          IF (UISO > 0.25) THEN
            WRITE (LU6, 99968, IOSTAT = IOST) LINE(1:66)
            NDEL = NDEL + 1
            CYCLE
          END IF
        END IF
  130   IF (MODE == 1) WRITE (LU62, 99972, IOSTAT = IOST) LINE
      END DO
  140 CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      IF (MODE == 1 .AND. NDEL > 0) THEN
        NLS = 5
        GO TO 110
      END IF
C * MODE 4
      IF (MODE == 4) THEN
        W13 = W1 + W3
        IF (W13 /= 0.0) THEN
          IF (2 * ABS (W1 - W3) / W13 > 0.05) GO TO 150
        END IF
        W24 = W2 + W4
        IF (W24 /= 0.0) THEN
          IF (2 * ABS (W2 - W4) / W24 > 0.05) GO TO 150
        END IF
        ISPR(215) = 0
        GO TO 160
  150   IF (ISPR(215) < 4) THEN
          ISPR(215) = ISPR(215) + 1
          MODE = 3
        ELSE
          ISPR(215) = 0
        END IF
      END IF
C * CREATE NEW DATA CONTEXT pn
  160 CALL S924 (0)
C * SAVE NEW REFINE STATUS
      ISPR(6) = MODE
C * READ SHELXL.LST / UPDATE DATABASE
C * SHOW RESULTS
      IF (IGBL(50) == 0 .AND. ISPR(6) >= 0) THEN
  170   BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
        IF (IGBL(50) == 0) CALL GGIP (HORS, VERT, 0.0, 1)
        CALL S927 (1)
C * SUGGEST NUMBER OF PEAKS IN DIFF MAP HIGHER THAN 2.0 E/A3
        IF (ISPR(6) < 2) THEN
C * ISOTROPIC
          NDF = ISPR(302)
        ELSE
          NDF = 0
        END IF
        LIJN = 'PERTINENT INFORMATION ON THE CURRENT REFINEMENT'
        CALL PLA439 (0.0, LIJN, 50, 0.6, 5 + IGBL(68), 2, 1.0, 18.5)
        CALL GGIP (0.0,  1.6, 0.0, 3)
        CALL GGIP (HORS, 1.6, 0.0, 2)
        LIJN =
     1'Peaks from the difference map may be included (RENAME) in .res'
        CALL PLA439 (0.0, LIJN, 80, 0.375, 2, 2, 0.1, 1.0)
        LIJN = 'Q-Peaks not renamed will be deleted automatically'
        CALL PLA439 (0.0, LIJN, 80, 0.375, 1, 2, 0.1, 0.3)
        WRITE (SBCD, 99987, IOSTAT = IOST) NDF, CHAR (0)
C * WHAT NEXT ?
        CALL PLA012 (0, 1)
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 170
        IF (IGGT(1:4) == 'EXIT') THEN
          NDF = 0
          GO TO 180
        END IF
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
        ELSE
          WRITE (LINE, '(I3, 77X)', IOSTAT = IOST) NDF
        END IF
        CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
        IF (KL == 0 .AND. KN > 0) NDF = NINT (FN(1))
        IF (KL == 1 .AND. JFL(1)(1:4) == 'SKIP') NDF = 0
      ELSE
        CALL S927 (0)
        NDF = 0
      END IF
  180 KERR = 0
      CALL SPAWN ('cp shelxl_pl.res ../pn/s.res',   0, .true.,
     1  KERR)
      CALL SPAWN ('cp shelxl_pl.res save.res',      0, .true.,
     1  KERR)
      CALL SPAWN ('cp shelxl.lst ../pn/shelxl.lst', 0, .true.,
     1  KERR)
      CALL SPAWN ('rm -f '//COMPD(1:IC)//'.hkl',    0, .true.,
     1  KERR)
      INQUIRE (FILE = 'shelxl.cif', EXIST = EXST)
C * EDIT/COPY CIF
      IF (EXST) THEN
        OPEN (LU61, FILE = 'shelxl.cif', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 'new.cif', STATUS = 'UNKNOWN')
        ICOP = 0
        DO
          READ  (LU61, 99972, IOSTAT = IOST) LINE
          IF (IOST /= 0) GO TO 190
          IF (ICOP == 0) THEN
            N1 = INDEX (LINE, '_symmetry_space_group_name_H-M')
            IF (N1 /= 0) THEN
              CALL SGSM (18, LINE, XYZ, 0, 0, IERR)
              SGXX1 = LINE(15:26)
              IF (LINE(44:44) == ' ') THEN
                SGXX2 = LINE(45:60)
              ELSE
                SGXX2 = LINE(44:60)
              END IF
              LINE = '_symmetry_space_group_name_H-M '''//SGXX1//''''
              CALL GEN020 (-1, LINE, 34, 47)
              WRITE (LU62, 99972, IOSTAT = IOST) LINE
              LINE = '_symmetry_space_group_name_Hall '''//SGXX2//''''
              WRITE (LU62, 99972, IOSTAT = IOST) LINE
              CYCLE
            END IF
            N1 = INDEX (LINE, '_exptl_absorpt_correction_type')
            IF (N1 /= 0) THEN
              IF (CPR(202)(1:4) == 'ABST') THEN
                LINE = '_exptl_absorpt_correction_type    analytical'
              ELSE IF (CPR(202) == 'ABSP') THEN
                LINE = '_exptl_absorpt_correction_type    psi-scan'
              ELSE IF (CPR(202) == 'MULA') THEN
                LINE = '_exptl_absorpt_correction_type    multi-scan'
              ELSE IF (CPR(202) == 'DELA') THEN
                LINE = '_exptl_absorpt_correction_type    refdelf'
              ELSE
                LINE = '_exptl_absorpt_correction_type    none'
              END IF
              WRITE (LU62, 99972, IOSTAT = IOST) LINE
              CYCLE
            END IF
            N1 = INDEX (LINE, '_computing_structure_solution')
            IF (N1 /= 0) THEN
              WRITE (LU62, '(''_computing_structure_solution'',5X, A)',
     1          IOSTAT = IOST)
     1                     CPR(203)
              CYCLE
            END IF
            IF (ISPR(15) /= 0) THEN
              N1 = INDEX (LINE, '_exptl_absorpt_correction_T_min')
              IF (N1 /= 0) THEN
                WRITE (LU62, 99975, IOSTAT = IOST) SPAR(126)
                CYCLE
              END IF
              N1 = INDEX (LINE, '_exptl_absorpt_correction_T_max')
              IF (N1 /= 0) THEN
                WRITE (LU62, 99974, IOSTAT = IOST) SPAR(127)
                CYCLE
              END IF
            END IF
          END IF
          WRITE (LU62, 99972, IOSTAT = IOST) LINE
        END DO
  190   CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN ('rm -f shelxl.cif',                0, .true., KERR)
        CALL SPAWN ('mv new.cif shelxl.cif',           0, .true., KERR)
        CALL SPAWN ('cp shelxl.cif  ../pn/shelxl.cif', 0, .true., KERR)
        CALL SPAWN ('cp shelxl.fcf  ../pn/shelxl.fcf', 0, .true., KERR)
      END IF
C * ENTER LOG
      CALL S915 ('Run SHELXL/'//CPR(106))
C * REGISTER SHELXL
      CPR(205) = 'SHELXL'
C * DETERMINE WHAT NEXT
C * CHANGE PHASING METHOD ?
      IF (SPAR(202) > SPAR(2) .AND. IGBL(50) /= 0) THEN
        CPR(105) ='Z'
        CPR(106) = CPR(200)
        ISPR(11) = 3
      ELSE
        CPR(105) = 'SHELXL'
      END IF
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
  200 IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      IF (IGBL(34) == 1) THEN
        LIJN    = 'EXEC = VALID'
        CALL PLA439 (0.0, LIJN, 17, 0.7, 4, 4, 16.5, 6.4)
        CALL PLA439 (0.0, LIJN, 17, 0.7, 2, 4, 16.4, 6.3)
        CALL GGIP (0.0, 0.0, 0.0, 6)
        CALL S520 (0)
      END IF
      IF (NDF > 0 .AND. IGBL(50) == 0) CALL S410 (NDF)
      RETURN
99999 FORMAT ('SET IGBL 70  0', /, 'CALC SHELX NOSF', /, 'QUIT')
99998 FORMAT ('MOVE', 4F8.2)
99997 FORMAT ('HKLF', I2, ' 1', 9F7.4, /, 'END')
99996 FORMAT ('ANIS', I5)
99995 FORMAT ('FVAR 1.0')
99994 FORMAT ('ACTA', /, 'PLAN', I5, /, 'BOND $H')
99993 FORMAT ('SFAC ', 16(1X, A))
99992 FORMAT ('UNIT ', 2I5, 14I4)
99991 FORMAT ('FMAP 2', /, 'PLAN', I5, /, 'CONF')
99990 FORMAT ('TITL ', A, ' - SHELXL')
99989 FORMAT ('WGHT', 2F10.3)
99988 FORMAT ('ZERR ', I5, 6F10.4)
99987 FORMAT ('Click SKIP or Enter nr. of diff_map peaks to be ',
     1        'appended for PLUTON [', I3, '] ', A)
99986 FORMAT ('LATT ', I3)
99985 FORMAT ('SYMM ', A)
99984 FORMAT ('OMIT -2', F10.2)
99983 FORMAT ('TEMP ', F6.0)
99982 FORMAT ('EXTI ', F8.5)
99981 FORMAT ('SIZE ', 3F10.3)
99980 FORMAT ('TWIN ', 9I5, /, 'BASF', F10.3)
99979 FORMAT ('CONF', /, 'HTAB')
99978 FORMAT ('TWIN', /, 'BASF', F10.4)
99977 FORMAT ('CGLS ', I5)
99976 FORMAT ('L.S. ', I5)
99975 FORMAT ('_exptl_absorpt_correction_T_min', F8.3)
99974 FORMAT ('_exptl_absorpt_correction_T_max', F8.3)
99973 FORMAT ('HKLF', I5, /, 'END')
99972 FORMAT (A)
99971 FORMAT ('MERG', I5)
99970 FORMAT ('BASF', F10.3, /, 'MERG 0')
99969 FORMAT (F11.0)
99968 FORMAT (':: DELETE ', A, ' <<<')
      END SUBROUTINE S310
 
      SUBROUTINE S330
      USE files
      USE parameters
      USE ccom
      USE scom
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NB
      INTEGER :: NC
      INTEGER :: NA
      INTEGER :: NAT
      INTEGER :: KNP1
      INTEGER :: LOOP
      INTEGER :: IVAR
      INTEGER :: NSFC
      INTEGER :: NHAT
      INTEGER :: MHAT
      INTEGER :: NCONM
      INTEGER :: NHAT0
      INTEGER :: NHKLF
      INTEGER :: IYUNK
      INTEGER :: GEN135
      INTEGER :: CHDIR
      INTEGER, DIMENSION(500) :: IATC
      REAL :: D
      REAL :: ANG
      REAL :: TTH
      REAL :: DMAX
      REAL :: S901
      REAL, DIMENSION(500)    :: DATC
      REAL, DIMENSION(500, 5) :: ATP
      CHARACTER(len=4)   :: LABI
      CHARACTER(len=133) :: LIN
      CHARACTER(len=2)   :: CKNP1
      CHARACTER(len=80)  :: XLINE
      CHARACTER(len=4), DIMENSION(500) :: CATC
C * FIND H-ATOMS BASED OF SHELXL97 DIFFERENCE MAP
      CALL S915 ('Run Hdif')
C * EXPECTED NUMBER OF H-ATOMS
      MHAT = ISPR(122) / ISPR(102)
C * CHECK FOR/CREATE-CHANGE TO hdif-DIR UNDER user/s/compoundname/tm/sg
      CALL S909 ('tm/sg/hdif')
C * CHECK/LINK TO s.hkl
      KERR = 0
      CALL SPAWN ('ln -s -f ../s.hkl shelxl.hkl', 0, .true., KERR)
C * DIFFERENCE MAP /SETUP
C * FILTER s.res TO shelxl.ins for DIFMAP WITH SHELXL
      OPEN (LU61, FILE = '../s.res',   STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = 'shelxl.ins', STATUS = 'UNKNOWN')
C * IVAR = 1: COPY LINE, IVAR = 0 : DO NOT COPY LINE FROM .res TO .ins
      IVAR  = 0
      XLINE = 'SFAC'
      NSFC  = 6
      KNP1  = 2
      DO
        READ (LU61, 99994, IOSTAT = IOST) LINE
        IF (IOST /= 0) GO TO 10
C * TITL
        IF (LINE(1:4) == 'TITL') THEN
          WRITE (LU62, 99979, IOSTAT = IOST) TITL(1:6)
          IVAR = 1
          CYCLE
C * SFAC
        ELSE IF (LINE(1:4) == 'SFAC') THEN
          BACKSPACE LU61
          CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1, 80, 10,
     1                 NP17)
          IF (KN == 0) THEN
            XLINE = LINE
C * SEARCH FOR SCATTERING NUMBER FOR H-ATOMS
            DO K = 1, KL
              IF (JFL(K)(1:4) == 'H   ') KNP1 = K - 1
            END DO
          ELSE
            XLINE(NSFC:) = JFL(2)(1:4)
            NSFC         = NSFC + 4
            IF (JFL(2)(1:2) == 'H ') KNP1 = (NSFC - 6) / 4
          END IF
          CYCLE
C * UNIT
        ELSE IF (LINE(1:4) == 'UNIT') THEN
          WRITE (LU62, 99994, IOSTAT = IOST) XLINE
          WRITE (LU62, 99994, IOSTAT = IOST) LINE
C * LIMIT RESOLUTION
          TTH = ASIN (0.40 * SPAR(80)) * 90.0 / ATAN (1.0)
          WRITE (LU62, 99983, IOSTAT = IOST) TTH
          IVAR = 0
C * FVAR
        ELSE IF (LINE(1:4) == 'FVAR') THEN
          IVAR = 1
C * END
        ELSE IF (LINE(1:3) == 'END') THEN
          EXIT
        END IF
C * COPY LINE TO .res
        IF (IVAR == 1) WRITE (LU62, 99994, IOSTAT = IOST) LINE
      END DO
   10 LOOP  = 0
      NHAT0 = -1
      NHAT  = 0
C * RUN SHELXL/DIFMAP
C * POPULATION PARAMETER REFINEMENT OF H-ATOMS (FOR LOOP > 1)
   40 LOOP = LOOP + 1
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      KERR = 0
      CALL SPAWN (SHLPATH//' shelxl > shelxl.log', 0, .true., KERR)
      IF (LOOP <= 5) THEN
        IF (LOOP > 1) THEN
          IF (NHAT == NHAT0) GO TO 140
          NHAT0 = NHAT
        END IF
C * ANALYSE SHELXL LISTING
        OPEN (LU61, FILE = 'shelxl.lst', STATUS = 'UNKNOWN')
C * TOTAL # OF PEAKS
        N     = 0
C * NR OF NON-HATOMS
        NA    = 0
C * TOTAL NUMBER OF REFINED ATOMS
        NB    = 0
        NHKLF = 0
   50   READ (LU61, 99994, IOSTAT = IOST) LIN(1:133)
        IF (IOST /= 0) GO TO 70
C * PICK UP REFINEMENT RESULTS
        IF (LIN(2:5) == 'HKLF') THEN
          NHKLF = 1
C * GET INPUT ATOM SET (After ATOM x y z sof U11 etc
        ELSE IF (LIN(2:5) /= '    ' .AND. LIN(15:15) == '.'
     1   .AND. LIN(5:5) /= '.' .AND. NHKLF /= 0) THEN
C * COUNT NON-H ATOMS
          CALL GEN020 (1, LIN, 2, 3)
          IF (LIN(2:2) /= 'H' .OR.  LIN(2:3) == 'HG' .OR.
     1        LIN(2:3) == 'HF' .OR. LIN(2:3) == 'HE' .OR.
     2        LIN(2:3) == 'HO') NA = NA + 1
          NB      = NB + 1
          N       = N  + 1
          NCON(N) = 0
          READ (LIN, 99991) CATC(N), (PEAK(N, J), J = 1, 4)
          SGX(1)  = PEAK(N, 1)
          SGX(2)  = PEAK(N, 2)
          SGX(3)  = PEAK(N, 3)
          SGX(10) = 0.0
          CALL SGSM (19, LINE, SGX, 0, LU6, IERR)
          PEAK(N, 6) = SGX(10)
          PEAK(N, 4) = PEAK(N, 4) / SGX(10)
C * SET PEAK-HEIGHT = 0.0
          PEAK(N, 5) = 0.0
C * AVOID SHORT Met-H PEAKS
          CALL GEN020 (1, CATC(N), 1, 2)
          CALL GEN105 (3, CATC(N)(2:2), IYUNK)
          IF (IYUNK > -1) THEN
            IYUNK = 1
          ELSE
            IYUNK = 2
          END IF
          DO J = 1, ISPR(110)
            IF (SFAC(J)(1:IYUNK) == CATC(N)(1:IYUNK)) THEN
              IATC(N) = NINT (SPAR(250 + J * 15))
              GO TO 50
            END IF
          END DO
C * PICK UP PEAKS FROM WEIGHTED DIFFERENCE MAP
        ELSE IF (LIN(2:2) == 'Q' .AND. LIN(7:9) == ' 1 ') THEN
          READ (LIN, 99990) (PEAK(N + 1, J), J = 1, 5)
          IF (PEAK(N + 1, 5) < 0.15) GO TO 50
          N          = N + 1
          NCON(N)    = 0
          WRITE (CATC(N), '(A, I3)', IOSTAT = IOST) LIN(2:2), 100 + N
C * SET SOF = 0.0 FOR Q-PEAKS
          PEAK(N, 4) = 0.0
          IATC(N)    = 0
        END IF
C * GET NR ELECTRONS
        GO TO 50
   70   CLOSE (UNIT = LU61)
C *    I....Non-H....I....H....I.....Q.....I     (ATOM STORAGE)
C *    1             NA        NB          N
C * GET BONDS
        CALL S900 (N)
        DO I = 1, N
C * PICKUP HATOMS BONDED TO NON-H ATOMS ABOVE PICK-UP LEVEL
C * TEST SOF-VALUE
          IF (PEAK(I, 4) > SPAR(1)) THEN
            IF (NCON(I) > 0) THEN
              DO 100 J = 1, NCON(I)
                K = ICON(I, J)
C * LOOK FOR Q-PEAKS
                IF (K > NB) THEN
C * CHECK FOR H-X-Y > 90
                  D = PEAK(I, 6 + J)
                  IF (D < 0.0) GO TO 100
                  IF (D < 1.2 .AND. I <= NB .AND. J > 1) THEN
                    DO M = 1, J - 1
                      L   = ICON(I, M)
                      IF (L <= NB) THEN
                        ANG = S901(K, I, L)
                        IF (ANG < 90.0) THEN
                          PEAK(I, 6 + J) = - ABS (PEAK(I, 6 + J))
                          PEAK(K, 4) = 0.0
                          GO TO 100
                        END IF
                      END IF
                    END DO
                  END IF
C * SEE WHETHER Q-PEAK IS CLOSE TO ONLY ONE OTHER ATOM
                  NC = 0
                  DO L = 1, NCON(K)
                    D = PEAK(K, 6 + L)
                    IF (D < 0.0) GO TO 100
                    IF (ICON(K, L) < NA) THEN
                      DMAX = 1.5
                    ELSE
                      DMAX = 1.25
                    END IF
                    IF (D < DMAX) THEN
                      IF (ICON(K, L) <= NB) NC = NC + 1
                      IF (NC > 1 .OR. IATC(I) >= 17) THEN
                        PEAK(I, 6 + L) = - ABS (PEAK(I, 6 + L))
                        PEAK(K, 4)     = 0.0
                        GO TO 100
                      END IF
                    END IF
                  END DO
                  D = PEAK(I, 6 + J)
                  IF (D < 0.0) GO TO 100
                  IF (I <= NA) THEN
                    IF (ABS (D - 0.95) < 0.3)
     1                PEAK(K, 4) = PEAK(K, 4) + 1.0
                  ELSE IF (I <= NB) THEN
                    IF (D < 1.5) PEAK(K, 4) = 0
                  END IF
                END IF
  100         CONTINUE
            END IF
C * AVOID H-ATOMS BONDED TO MORE THAN 1 NON-H ATOM
            IF (I > NB .AND. PEAK(I, 4) > 1.0) PEAK(I, 4) = 0.0
            IF (IGBL(50) == 0 .AND. ISPR(49) == 1) THEN
              IF (I == 1) WRITE (LU6, 99980, IOSTAT = IOST)
              NCONM = MIN (NCON(I), 5)
              WRITE (LU6, 99982, IOSTAT = IOST) I, CATC(I),
     1              (PEAK(I, J), J = 1, 6 + NCONM)
              WRITE (LU6, 99981, IOSTAT = IOST)
     1          (CATC(ICON(I, J)), J = 1, NCONM)
            END IF
          END IF
        END DO
C * APPEND H-ATOMS
        OPEN (LU61, FILE = 'shelxl.res', status = 'unknown')
        OPEN (LU62, FILE = 'shelxl.ins', status = 'unknown')
        NAT  = -1000
        IVAR = 0
  120   READ (LU61, 99994) LINE
        IF (LINE(1:3) == 'REM') GO TO 120
        IF (LINE(1:4) == 'HKLF') THEN
C * ADD BLOC LINE , ADD H-ATOMS
          L = 0
          DO I = NA + 1, N
            IF (PEAK(I, 4) > 0.01) THEN
              L = L + 1
              LABI = 'H   '
              CALL GEN058 (LABI, L)
              WRITE (LU62, 99986, IOSTAT = IOST)
     1          LABI, KNP1, (PEAK(I, J), J = 1, 3), PEAK(I, 4)
            END IF
          END DO
          NHAT = L
          WRITE (LU62, 99997, IOSTAT = IOST) LABI
          WRITE (LU62, 99994, IOSTAT = IOST) LINE
          WRITE (LU62, 99985, IOSTAT = IOST)
          GO TO 40
        ELSE IF (LINE(1:4) == 'L.S.') THEN
          WRITE (LU62, 99995, IOSTAT = IOST) 3
          GO TO 120
        ELSE IF (LINE(1:4) == 'FVAR') THEN
          IVAR = 1
        ELSE IF (IVAR == 1) THEN
C * ADD BLOC LINE BEFORE NON-ATOMS (DO NOT REFINE NON-H'S)
          IVAR = 0
          NAT  = 0
        END IF
        IF (LINE(2:5) /= '    ') NAT = NAT + 1
        IF (NAT < 0) THEN
          WRITE (LU62, 99994, IOSTAT = IOST) LINE
        ELSE IF (NAT <= NA .AND. PEAK(NAT, 4) > SPAR(1)) THEN
          WRITE (LU62, 99994, IOSTAT = IOST) LINE
        END IF
        GO TO 120
      END IF
C * RESULTS TO pn/s.res
  140 CALL S924 (0)
      OPEN (LU61, FILE = 'shelxl.res', STATUS = 'UNKNOWN')
      OPEN (LU62, FILE = '../pn/s.res', STATUS = 'UNKNOWN')
C * REMOVE FAINT H-ATOMS
      NHAT = 0
      WRITE (CKNP1, 99984, IOSTAT = IOST) KNP1
  150 READ (LU61, 99994) LINE
      IF (LINE(1:1) == 'H' .AND. LINE(6:7) == CKNP1) THEN
        BACKSPACE LU61
        CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 0, 1, 80, 10,
     1               NP17)
        NHAT = NHAT + 1
        DO I = 1, 5
          ATP(NHAT, I) = FN(I)
        END DO
        DATC(NHAT) = 1000.0 - FN(5)
        IATC(NHAT) = NHAT
        CATC(NHAT) = LINE(1:4)
        GO TO 150
      ELSE IF (LINE(1:4) == 'BLOC') THEN
        GO TO 150
      ELSE IF (LINE(1:4) == 'HKLF') THEN
        GO TO 170
      END IF
      WRITE (LU62, 99994, IOSTAT = IOST) LINE
      GO TO 150
  170 L = 0
      CALL GEN036 (DATC, IATC, 1, NHAT)
      DO I = 1, NHAT
        K = IATC(I)
        IF (ATP(K, 5) > 0.2 .OR. L < MHAT) THEN
          L = L + 1
          LABI = 'H'
          CALL GEN058 (LABI, L)
          WRITE (LU62, 99992, IOSTAT = IOST)
     1      LABI, (ATP(K, J), J = 2, 4)
        ELSE
          IF (IGBL(50) == 0 .AND. ISPR(49) == 1)
     1      WRITE (LU6, 99993, IOSTAT = IOST)
     2        CATC(K), (ATP(K, J), J = 2, 5)
        END IF
      END DO
C * TEST FOR UNIT MATRIX
      IF (GEN135 (TM) == 1) THEN
        WRITE (LU62, 99999, IOSTAT = IOST)
      ELSE
        WRITE (LU62, 99998, IOSTAT = IOST)
     1    ((TM(I, J), J = 1, 3), I = 1, 3)
      END IF
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      KERR = 0
      CALL SPAWN ('cp ../pn/s.res shelxl.res', 0, .true., KERR)
      CALL SPAWN ('cp ../pn/s.res save.res',   0, .true., KERR)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1 : INZ - 1)) /= 0) CALL S925 (1)
      CPR(206) = 'HDIF'
C * SHOW RESULTS
      CALL S920 (1)
      IF (IGBL(50) == 0) CALL S410 (0)
C * DETERMINE WHAT NEXT
      CPR(105) = 'HDIF'
      CPR(106) = CPR(200)
      RETURN
99999 FORMAT ('HKLF 4', /, 'END')
99998 FORMAT ('HKLF 4 1', 9F7.4, /, 'END')
99997 FORMAT ('BLOC -1 H501 > ', A)
99995 FORMAT ('L.S. ', I5)
99994 FORMAT (A)
99993 FORMAT ('Exorcised: ', A, 4F10.4)
99992 FORMAT (A, '   2', 3F10.4, ' 11.0 0.05')
99991 FORMAT (1X, A, 5X, 3F10.0, F12.0)
99990 FORMAT (9X, 3F8.0, F10.0, 6X, F8.0)
99986 FORMAT (A, I3, 4F10.4, '  10.05')
99985 FORMAT ('END')
99984 FORMAT (I2)
99983 FORMAT ('L.S. 0', /, 'OMIT -3 ', F10.1, /, 'FMAP 2 ', /,
     1        'PLAN 30 ')
99982 FORMAT (I3, 1X, A, 3F7.3, F6.3, F7.2, 9F6.3)
99981 FORMAT (47X, 9(2X, A))
99980 FORMAT (' NR LABEL     X', 6X, 'Y', 6X, 'Z   POP    RHO   SOF',
     1        ' BONDS(D/NR)')
99979 FORMAT ('TITL ', A, ' - HATOM')
      END SUBROUTINE S330
 
      SUBROUTINE S340
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: CHDIR
      EXST = .FALSE.
      CALL S915 ('Run PLATON/SQUEEZE')
      WRITE (LU6, 99975, IOSTAT = IOST)
C * CHECK/CREATE-CHANGE TO SQUEEZE DIRECTORY
      CALL S909 ('tm/sg/squeeze')
C * CREATE LINK TO SHELX.HKL AND S.RES
      INQUIRE (FILE = 'squeeze.hkl', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s '//'../s.hkl squeeze.hkl', 0, .true., KERR)
      END IF
      INQUIRE (FILE = '../s.res', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../s.res squeeze.res', 0, .true., KERR)
      ELSE
        WRITE (LU6, 99994, IOSTAT = IOST)
        GO TO 10
      END IF
      KERR = 0
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -q squeeze.res', 0, .true.,
     1  KERR)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
   10 IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * REGISTER SQUEEZE
      CPR(208) = 'SQUEEZE   '
      ISPR(7)  = 0
      IGBL(38) = 1
      ISPR(14) = 7
C * SAVE DATABASE
      CALL S924  (1)
      RETURN
99994 FORMAT ('Error: File s.res not found in Compound Directory')
99975 FORMAT (/, '>> Automatic PLATON/SQUEEZE procedure', /)
      END SUBROUTINE S340
 
      SUBROUTINE S350
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: CHDIR
 
      EXST = .FALSE.
C * TWINROTMAT
      CALL S915 ('Run PLATON/TwinRotMat')
C * CHECK/CREATE-CHANGE TO TWINROTMAT DIRECTORY
      CALL S909 ('tm/sg/twinrotmat')
C * CREATE LINK TO S .cif & .fcf
      INQUIRE (FILE = 'shelxl.fcf', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s '//'../shelxl/shelxl.fcf', 0, .true., KERR)
      END IF
      INQUIRE (FILE = 'shelxl.cif', EXIST = EXST)
      IF (.NOT. EXST) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../shelxl/shelxl.cif', 0, .true., KERR)
      END IF
      KERR = 0
      CALL SPAWN ('rm -f shelxl.hkp', 0, .true., KERR)
      IF (IGBL(50) == 1) THEN
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -M shelxl.cif', 0, .true.,
     1    KERR)
      ELSE
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' -L shelxl.cif', 0, .true.,
     1    KERR)
      END IF
      INQUIRE (FILE = 'shelxl.hkp', EXIST = EXST)
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      ISPR(7)  = 0
      IGBL(38) = 1
C * SET REFLECTION LINK TYPE
      IF (EXST) ISPR(14) = 8
C * SAVE DATABASE
      CALL S924 (1)
      RETURN
      END SUBROUTINE S350
 
      SUBROUTINE S410 (NDIFF)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IP
      INTEGER :: KM
      INTEGER :: NS
      INTEGER :: NZ
      INTEGER :: NS1
      INTEGER :: NS3
      INTEGER :: KM0
      INTEGER :: ID0
      INTEGER :: IER
      INTEGER :: IFV
      INTEGER :: NDF
      INTEGER :: NEW
      INTEGER :: NDIF
      INTEGER :: IEND
      INTEGER :: NAFIX
      INTEGER :: NDIFF
      INTEGER :: GEN135
      INTEGER :: CHDIR
      INTEGER, DIMENSION(16) :: NFC
      REAL :: CHARSIZ
      CHARACTER(len=7)  :: NQX1
      CHARACTER(len=6)  :: COLOUR
      CHARACTER(len=6)  :: CONTOUR
      CHARACTER(len=5)  :: STYLE
      CHARACTER(len=3)  :: OVERLAP
      CHARACTER(len=10) :: SAV105
      CHARACTER(len=10) :: SAV106
      CHARACTER(len=80) :: WGHT
      CHARACTER(len=2), DIMENSION(16) :: XFC
      CALL S915 ('Run PLUTON')
      CALL GEN097 (NFC, 1, 16, 0)
      EXST     = .FALSE.
      WGHT     = 'WGHT 1 0'
      NDIF     = 0
      NEW      = 0
      KM0      = 0
C * SET 'S-mode' for PLUTON
      IGBL(92) = 1
      IGBL(3)  = 8
      IGBL(67) = 0
      IF (NDIFF > 0) THEN
        NDIF = NDIFF
        IGBL(50) = 0
C * RENAME MODE
      ELSE IF (NDIFF == -1) THEN
        IGBL(3)  = 12
        IGBL(50) = 0
C * HFIX MODE
      ELSE IF (NDIFF == -2) THEN
        IGBL(3) = 13
C * ANIS MODE
      ELSE IF (NDIFF == -3) THEN
        IGBL(3) = 26
      END IF
C * CHECK FOR/CREATE-CHANGE TO PLUTON-DIR UNDER user/s/compoundname
      CALL S909 ('tm/sg/pluton')
 
C * PREPARE PLUTON JOB FROM s.res
      NDF     = -99999
      COLOUR  = 'COLOR'
      CONTOUR = 'CONT 0'
C * CHECK COORDINATE/REFINEMENT STATUS
      IF (ISPR(6) > -1) THEN
C * READ CURRENT s.res, GENERATE satom.spf FOR PLUTON
        OPEN (LU61, FILE = '../s.res', STATUS = 'UNKNOWN')
        READ (LU61, 99986, IOSTAT = IOST) LINE
        IF (IOST .NE. 0) GO TO 10
        BACKSPACE LU61
        IF (ISPR(6) == 0) THEN
        ELSE IF (ISPR(6) > 0) THEN
          IF (IGBL(50) > 0) THEN
            COLOUR = 'COLOR'
          ELSE
            COLOUR = 'COLOR'
          END IF
        END IF
        IF (ISPR(6) == 0 .OR. NDIF > 0) THEN
          STYLE   = 'SOLID'
          OVERLAP = 'OFF'
        ELSE
          STYLE   = 'STRAW'
          CONTOUR = '      '
          OVERLAP = 'ON '
        END IF
        OPEN (LU62, FILE = 'satom.spf', STATUS = 'UNKNOWN')
C * COPY AND OPTIONALLY ADD PEAKS FROM DIFFERENCE MAP
        IEND = -1
        NAFIX = 0
        DO
          READ (LU61, 99986, IOSTAT = IOST) LINE
          IF (IOST .NE. 0) EXIT
          IF (LINE(1:4) == 'HKLF') CYCLE
          IF (LINE(1:4) == 'WGHT') THEN
            IF (IEND >= 0) THEN
              WGHT = LINE
              CYCLE
            END IF
          ELSE IF (LINE(1:3) == 'END') THEN
            IEND = 0
            NDF  = 0
            CYCLE
          ELSE IF (LINE(1:1) == 'Q' .AND. IEND /= 1) THEN
            IF (NDF < NDIF) THEN
              IF (NDF == 1 .AND. NAFIX /= 0)
     1          WRITE (LU62, 99992, IOSTAT = IOST)
              NDF = NDF + 1
            ELSE
C * TEST FOR UNIT MATRIX
              IF (GEN135 (TM) == 1) THEN
                WRITE (LU62, 99987, IOSTAT = IOST)
              ELSE
                WRITE (LU62, 99993, IOSTAT = IOST)
     1            ((TM(I, J), J = 1, 3), I = 1, 3)
              END IF
              WRITE (LU62, 99994, IOSTAT = IOST) WGHT
              IEND = 1
            END IF
          END IF
          IF (LINE(1:4)  == 'AFIX') READ (LINE (5:80), *) NAFIX
          WRITE (LU62, 99986, IOSTAT = IOST) LINE
        END DO
        IF (IEND /= 1) THEN
C * TEST FOR UNIT MATRIX
          IF (GEN135 (TM) == 1) THEN
            WRITE (LU62, 99987, IOSTAT = IOST)
          ELSE
            WRITE (LU62, 99993, IOSTAT = IOST)
     1        ((TM(I, J), J = 1, 3), I = 1, 3)
          END IF
          WRITE (LU62, 99994, IOSTAT = IOST) WGHT
        END IF
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
C * GENERATE .def
        CHARSIZ = 0.25
        OPEN (LU62, FILE = 'satom.def', STATUS = 'UNKNOWN')
        IF (ISPR(6) == 0) WRITE (LU62, 99998, IOSTAT = IOST)
        WRITE (LU62, 99988, IOSTAT = IOST)
        IF (ISPR(6) < 1) THEN
          WRITE (LU62, 99999, IOSTAT = IOST)
        ELSE IF (ISPR(6) < 3) THEN
          WRITE (LU62, 99990, IOSTAT = IOST)
        END IF
        WRITE (LU62, 99991, IOSTAT = IOST)
     1    STYLE, COLOUR, CONTOUR, OVERLAP
        IF (IGBL(50) == 0) WRITE (LU62, 99989, IOSTAT = IOST) CHARSIZ
        IF (ISPR(6)  < 4) WRITE (LU62, 99997, IOSTAT = IOST)
        IF (IGBL(50) > 0) WRITE (LU62, 99996, IOSTAT = IOST)
        WRITE (LU62, 99995, IOSTAT = IOST)
        CLOSE (UNIT = LU62)
C * VIEW/MODIFY
        IGBL(8) = 1
        CALL PLUTON (0)
C * REGISTER RENAMES
        CALL GEN108 (LU22, 1)
        DO
          READ (LU22, 99986, IOSTAT = IOST) LINE
          IF (IOST .NE. 0) EXIT
          IF (LINE(1:6) == 'RENAME') ISPR(92) = 1
        END DO
        IGBL(6) = 17
        CLOSE (UNIT = LU1)
        CLOSE (UNIT = LU23)
        CALL PLUT29 (-1, LINE, NQX1, 0, LU21)
        IF (IGBL(26) == 0 .AND. IPR(175) == 0) THEN
          CLOSE (UNIT = LU21, STATUS = 'DELETE')
        ELSE
          CLOSE (UNIT = LU21)
          EXST = .TRUE.
        END IF
        CLOSE (UNIT = LU22)
      END IF
      NEW = 0
      KM  = ISPR(110)
      IF (EXST) THEN
C * CREATE NEW DATA LINK (tm/sg/pn)
        CALL S924 (0)
        OPEN (LU61, FILE = 'satom.new', STATUS = 'UNKNOWN')
        IFV = 0
        KM0 = 0
        DO
          CALL GEN072 (LINE, JFL, FN, KL, KN, LU61, LU6, 1, 1,
     1      80, 10, NP17)
          IF (JFL(1)(1:3) == 'EOF') EXIT
C * CHECK FOR NEW SCATTERING TYPES
          IF (IFV == 0) THEN
            IF (JFL(1)(1:4) == 'SFAC') THEN
              DO I = 2, KL
                CALL GEN020 (1, JFL(I), 1, 7)
                IF (JFL(I)(1:2) /= 'Q ') THEN
                  KM0 = KM0 + 1
                  XFC(KM0) = JFL(I)(1:2)
                END IF
                IF (KL > KM + 1) NEW = 1
              END DO
            ELSE IF (JFL(1)(1:4) == 'FVAR') THEN
              IFV = 1
            END IF
          ELSE
            CALL GEN020 (1, JFL(1), 1, 7)
            IF (JFL(1)(1:4) == 'HFIX') THEN
              CYCLE
            ELSE IF (JFL(1)(1:4) == 'AFIX') THEN
              CYCLE
            ELSE IF (JFL(1)(1:3) == 'REM') THEN
              CYCLE
            ELSE IF (JFL(1)(1:4) == 'HKLF') THEN
C * ELIMINATE REDUNDANT ELEMENTS
              IF (ISPR(6) > 0) THEN
                J = 0
                DO I = 1, KM0
                  IF (NFC(I) > 0 .OR. XFC(I)(1:2) == 'H ') THEN
                    J = J + 1
                    XFC(J) = XFC(I)
                    NFC(J) = NFC(I)
                  END IF
                END DO
                IF (J < KM0) THEN
                  KM0 = J
                  NEW = 1
                END IF
              ELSE
                J = KM0
              END IF
              EXIT
            ELSE
              NS = NINT (FN(1))
              IF (NS > 0) THEN
                NZ = NINT ((FN(5) - 10.0) * ISPR(101) * ISPR(103))
                NFC(NS) = NFC(NS) + NZ
              END IF
            END IF
          END IF
        END DO
        CLOSE (UNIT = LU61)
        ISPR(7) = 0
        KERR = 0
        CALL SPAWN ('cp satom.new ../s.res', 0, .true., KERR)
        CALL SPAWN ('mv satom.new satom.nw', 0, .true., KERR)
        CPR(106) = 'PLUTON'
      END IF
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
   10 IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * CHECK AND ACT ON NEW ELEMENT TYPES
C * ADD SCATTERING FACTOR FOR H WHEN APPROPRIATE
      IF (NEW. EQ. 1) THEN
        ID0 = 1
        NS1 = 1
        DO I = 1, KM0
          IF (MOD (NFC(I), ISPR(101)) /= 0) GO TO 20
        END DO
        NS1 = ISPR(101)
   20   NS3 = 1
        DO I = 1, KM0
          IF (MOD (NFC(I), ISPR(103)) /= 0) GO TO 30
        END DO
        NS3 = ISPR(103)
   30   NS  = NS1 * NS3
        DO I = 1, KM0
          SFAC(I)    = XFC(I)
          NFC(I)     = NFC(I) / NS
          LINE(ID0:) = SFAC(I)
          ID0        = ID0 + 1
          IF (LINE(ID0:ID0) /= ' ') ID0 = ID0 + 1
          IF (NFC(I) == 0) NFC(I) = 2 * NFC(1)
          CALL GEN040 (NFC(I), LINE(ID0:), IP)
          ID0 = ID0 + IP
        END DO
        ISPR(110) = - KM0
C * UPDATE CONTENT / Z  ETC.
        SAV105 = CPR(105)
        SAV106 = CPR(106)
        CALL S180 (0)
        KN = 0
        CALL S190 (0, IER)
        IF (IER /= 0) RETURN
        CPR(105) = SAV105
        CPR(106) = SAV106
      END IF
      IF (NDIFF == -2) THEN
        CPR(105) = 'HFIX  '
        CPR(106) = CPR(200)
      END IF
      IF (ISPR(6) == 5) ISPR(6) = 6
C * SAVE DATABASE
      CALL S920 (1)
      RETURN
99999 FORMAT ('JOIN RADII UNIQUE TOLE 0')
99998 FORMAT ('SET IPR 176 0', /, 'SET IGBL 23 3')
99997 FORMAT ('PUT ATOM S')
99996 FORMAT ('SET PAR 18 1.0', /, 'SET PAR 13 0.65', /,
     1        'BOX OFF')
99995 FORMAT ('PLOT DISPLAY')
99994 FORMAT ('END', /, A)
99993 FORMAT ('HKLF 4 1', 9F7.4)
99992 FORMAT ('AFIX 0')
99991 FORMAT ( A, 1X, A, 1X, A, /,
     1        'OVERLAP ', A, /,
     2        'RADII ATOMS Q 0.1')
99990 FORMAT ('JOIN RADII UNIQUE')
99989 FORMAT ('LABEL', /, 'SIZE 0 CHAR ', F10.2)
99988 FORMAT ('SET RGBL 25 0.5')
99987 FORMAT ('HKLF 4')
99986 FORMAT (A)
      END SUBROUTINE S410
 
