      SUBROUTINE S420 (TYP)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: CHDIR
      CHARACTER(len=19) :: FIL1
      CHARACTER(len=*)  :: TYP
      EXST = .FALSE.
      CALL S915 ('Run PLATON')
C * PREPARE PLATON JOB FROM .CIF (WHEN AVAILABLE)
      FIL1 = 'tm/sg/pn/shelxl.cif'
      INQUIRE (FILE = FIL1, EXIST = EXST)
      IF (.NOT. EXST) THEN
C * PREPARE PLATON JOB FROM SHELX.RES/SHELXL.RES
        FIL1 = 'tm/sg/pn/s.res     '
      END IF
      IF (ISPR(6) > -1) THEN
        IF (TYP(1:1) == ' ') THEN
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/platon')
          KERR = 0
          CALL SPAWN ('cp ../'//FIL1(7:19)//' platon.spf',  0, .true.,
     1      KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//'  platon.spf ', 0, .true.,
     1      KERR)
          CALL SPAWN (PSVIEWER//'platon.lps', 0, .true., KERR)
        ELSE IF (TYP(1:4) == 'SOLV') THEN
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/solv')
          KERR = 0
          CALL SPAWN ('cp ../'//FIL1(7:19)//' solv.spf', 0, .true.,
     1      KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -v solv.spf > solv.log ',
     1      0, .true., KERR)
          OPEN (LU63, FILE = 'solv.log', STATUS = 'UNKNOWN')
          DO
            READ (LU63, 99999, IOSTAT = IOST) LINE
            IF (IOST == -1) GO TO 10
            IF (INDEX (LINE, 'NO Residual') /= 0) GO TO 20
          END DO
   10     KERR = 0
          CALL SPAWN (PSVIEWER//'solv.lps', 0, .true., KERR)
   20     CLOSE (UNIT = LU63)
C * ADDSYM SHELX
        ELSE IF (TYP(1:6) == 'ADDSYM') THEN
 
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/addsym')
          KERR = 0
          CALL SPAWN ('cp ../s.res addsym.spf', 0, .true., KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -N addsym.spf > a.log',
     1      0, .true., KERR)
          OPEN (LU63, FILE = 'addsym_pl.res', STATUS = 'UNKNOWN')
          DO
            READ (LU63, 99999, IOSTAT = IOST) LINE
            IF (IOST == -1) GO TO 30
            IF (LINE(1:8) == 'REM TRMX') THEN
              OPEN (LU64, FILE = 'addsym.ntr', STATUS = 'UNKNOWN')
              WRITE (LU64, 99999, IOSTAT = IOST) LINE(5:80)
              CLOSE (UNIT = LU64)
              KERR = 0
              CALL SPAWN ('cp addsym_pl.res ../../../.newsym.res',
     1          0, .true., KERR)
              CALL SPAWN ('cp addsym.ntr ../../../.newsym.ntr', 0,
     1          .true., KERR)
C * WRITE FILE WITH INFO TO BE TRANSFERRED TO NEW SETTING
              OPEN (LU64, FILE = 'addsym.sav', STATUS = 'UNKNOWN')
              WRITE (LU64, 99998, IOSTAT = IOST)
     1          (I, CPR(I), I = 201, 204)
              CLOSE (UNIT = LU64)
              KERR = 0
              CALL SPAWN ('cp addsym.sav ../../../.newsym.sav', 0,
     1          .true., KERR)
              ISPR(98) = 1
            ELSE IF (LINE(1:8) == 'REM SPGR') THEN
              OPEN (LU64, FILE = 'addsym.nsg', STATUS = 'UNKNOWN')
              WRITE (LU64, 99999, IOSTAT = IOST) LINE(5:80)
              CLOSE (UNIT = LU64)
              KERR = 0
              CALL SPAWN ('cp addsym.nsg ../../../.newsym.nsg', 0,
     1          .true., KERR)
            END IF
          END DO
   30     CLOSE (UNIT = LU63)
          CPR(105) = 'ADDSYM'
        ELSE IF (TYP(1:4) == 'CALC') THEN
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/calc')
          KERR = 0
          CALL SPAWN ('cp ../'//FIL1(7:19)//' calc.spf',    0,
     1      .true., KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -c calc.spf ', 0,
     1      .true., KERR)
          CALL SPAWN (PSVIEWER//'calc.lps',                 0,
     1      .true.,  KERR)
        ELSE IF (TYP(1:3) == 'ADP') THEN
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/adp')
          KERR = 0
          CALL SPAWN ('cp ../'//FIL1(7:19)//' adp.spf',    0, .true.,
     1      KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -a adp.spf ', 0, .true.,
     1      KERR)
        ELSE IF (TYP(1:3) == 'CSD') THEN
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/csd')
          KERR = 0
          CALL SPAWN ('cp ../'//FIL1(7:19)//' csd.spf',    0,
     1      .true., KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -b csd.spf ', 0,
     1      .true., KERR)
        ELSE IF (TYP(1:4) == 'ASYM') THEN
C * CHECK FOR/CREATE-CHANGE TO PLATON-DIR UNDER USER/S/COMPOUNDNAME/tm/sg
          CALL S909 ('tm/sg/asym')
          KERR = 0
          CALL SPAWN ('cp ../s.res  .',                 0,
     1      .true., KERR)
          CALL SPAWN ('cp ../s.hkl .',                  0,
     1      .true., KERR)
          CALL SPAWN (PLAPATH(1:IGBL(80))//' -l s.res', 0,
     1      .true., KERR)
        END IF
      END IF
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      RETURN
99999 FORMAT (A)
99998 FORMAT ('CPR',I3, A)
      END SUBROUTINE S420
 
