      SUBROUTINE S900 (NAT)
      USE scom
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: M
      INTEGER :: N
      INTEGER :: NS
      INTEGER :: NAT
      INTEGER :: NSYM
      REAL :: DMX
      REAL :: DTR
      REAL :: GAM
      REAL :: XLNG
      REAL :: DIST
      REAL :: BETA
      REAL :: SINA
      REAL :: SINB
      REAL :: SING
      REAL :: COSA
      REAL :: COSB
      REAL :: COSG
      REAL :: ALPHA
      REAL :: SINAS
      REAL :: SINBS
      REAL :: SINGS
      REAL :: COSAS
      REAL :: COSBS
      REAL :: COSGS
      REAL :: GEN009
      REAL, DIMENSION(3) :: D
      REAL, DIMENSION(3) :: V
      REAL, DIMENSION(3) :: W
      CHARACTER(len=80) :: LINE
      DTR  = ATAN (1.0) / 45.0
      NSYM = ISPR(102)
C * FIND DISTANCES BETWEEN ATOMS - ROLLETT, COMP. METH. IN CRYST. 1965
      ALPHA = SPAR(104)
      BETA  = SPAR(105)
      GAM   = SPAR(106)
      COSA  = COS(ALPHA * DTR)
      COSB  = COS(BETA  * DTR)
      COSG  = COS(GAM   * DTR)
      SINA  = SIN(ALPHA * DTR)
      SINB  = SIN(BETA  * DTR)
      SING  = SIN(GAM   * DTR)
      COSGS = (COSA * COSB - COSG) / (SINA * SINB)
      SINGS = SQRT(1.0 - COSGS**2)
      COSBS = (COSG * COSA - COSB) / (SING * SINA)
      SINBS = SQRT(1.0 - COSBS**2)
      COSAS = (COSB * COSG - COSA) / (SINB * SING)
      SINAS = SQRT(1.0 - COSAS**2)
      DMX  = 2.0
      D(1) = DMX / (SPAR(101) * SINB * SINGS)
      D(2) = DMX / (SPAR(102) * SING * SINAS)
      D(3) = DMX / (SPAR(103) * SINA * SINBS)
C * GET ORTHOGONALISATION MATRIX
      CALL GEN044 (SPAR(101), OL, 1)
C * RESET NR OF BONDS TO ATOM TO ZERO
      CALL GEN097 (NCON, 1, NAT, 0)
C * LOOP
      DO I = 1, NAT
        DO J = I, NAT
          DO 120 N = 1, NSYM
            IF (J == I .AND. N == 1) GO TO  120
            DO K = 1, 3
              SGX(K) = PEAK(J, K)
              SGX(K + 3) = 0.0
            END DO
            NS = N
            CALL SGSM (3, LINE, SGX, NS, 6, IERR)
            K = 1
            GO TO 30
   20       SGX(6 + K) = SGX(6 + K) - 1.0
   30       IF ((PEAK(I, K) - SGX(6 + K)) <= D(K)) GO TO 20
            GO TO 50
   40       IF (ABS (PEAK(I, K) - SGX(6 + K)) <= D(K)) GO TO 60
   50       SGX(6 + K) = SGX(6 + K) + 1.0
            IF ((PEAK(I, K)  - SGX(6 + K)) >= - D(K)) GO TO 40
            K = K - 1
            IF (K == 0) GO TO 120
            GO TO 50
   60       K = K + 1
            IF (K > 3) THEN
              DO L = 1, 3
                V(L) = PEAK(I, L) - SGX(6 + L)
              END DO
              CALL GEN002 (1, OL, V, W, XLNG)
              DIST = SQRT (GEN009 (W, W))
              IF (DIST < DMX) THEN
                IF (I /= J .OR. DIST > 0.05) THEN
                  IF (NCON(I) > 0) THEN
                    DO M = 1, NCON(I)
                      IF (ICON(I, M) == J) GO TO 90
                    END DO
                  END IF
                  IF (NCON(I) < 40) THEN
                    NCON(I)              = NCON(I) + 1
                    PEAK(I, 6 + NCON(I)) = DIST
                    ICON(I, NCON(I))     = J
                  END IF
   90             IF (NCON(J) > 0) THEN
                    DO M = 1, NCON(J)
                      IF (ICON(J, M) == I) GO TO 110
                    END DO
                  END IF
                  IF (NCON(J) < 40) THEN
                    NCON(J)              = NCON(J) + 1
                    PEAK(J, 6 + NCON(J)) = DIST
                    ICON(J, NCON(J))     = I
                  END IF
                END IF
              END IF
              GO TO 110
            END IF
            GO TO 30
  110       K = K - 1
            GO TO 50
  120     CONTINUE
        END DO
      END DO
      RETURN
      END SUBROUTINE S900
 
      REAL FUNCTION S901 (I, J, K)
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: L
      INTEGER :: N
      REAL :: RTD
      REAL :: XLNG
      REAL :: GEN027
      REAL, DIMENSION(3) :: U
      REAL, DIMENSION(3) :: V
      REAL, DIMENSION(3) :: OU
      REAL, DIMENSION(3) :: OV
      REAL, DIMENSION(3, 3) :: OLW
      RTD  = 45.0 / ATAN (1.0)
      DO L = 1, 3
        U(L) = PEAK(I, L) - PEAK(J, L)
        V(L) = PEAK(K, L) - PEAK(J, L)
        DO N = 1, 3
          OLW(L, N) = OL(L, N)
        END DO
      END DO
      CALL GEN002 (2, OLW, U, OU, XLNG)
      CALL GEN002 (2, OLW, V, OV, XLNG)
      S901 = GEN027 (OU, OV, RTD)
      RETURN
      END FUNCTION S901
 
      SUBROUTINE S902 (MODE, TM, LU61, LU62, STRING)
      IMPLICIT NONE
      INTEGER :: IH
      INTEGER :: IK
      INTEGER :: IL
      INTEGER :: JH
      INTEGER :: JK
      INTEGER :: JL
      INTEGER :: LU61
      INTEGER :: LU62
      INTEGER :: MODE
      INTEGER :: IOST
      INTEGER :: NERROR
      REAL :: XH
      REAL :: XK
      REAL :: XL
      REAL, DIMENSION(3, 3) :: TM
      CHARACTER(len=*)  :: STRING
      CHARACTER(len=16) :: RISI
      OPEN (LU61, FILE = 's.hkl', STATUS = 'OLD')
      OPEN (LU62, FILE = STRING,  STATUS = 'UNKNOWN')
      IF (MODE == 1) WRITE (LU62, 99999, IOSTAT = IOST)
      CALL GEN108 (LU61, 0)
      NERROR = -1
   10 NERROR = NERROR + 1
      IF (NERROR < 100) THEN
   20   READ (LU61, 99994, IOSTAT = IOST) JH, JK, JL, RISI
        IF (IOST /= 0) THEN
          IF (IOST == -1) THEN
            GO TO 30
          ELSE
            GO TO 10
          END IF
        END IF
        IF (JH == 0 .AND. JK == 0 .AND. JL == 0) GO TO 20
        XH = TM(1, 1) * JH + TM(1, 2) * JK + TM(1, 3) * JL
        XK = TM(2, 1) * JH + TM(2, 2) * JK + TM(2, 3) * JL
        XL = TM(3, 1) * JH + TM(3, 2) * JK + TM(3, 3) * JL
        IH = NINT (XH)
        IK = NINT (XK)
        IL = NINT (XL)
        IF (ABS (XH - IH) > 0.01) GO TO 20
        IF (ABS (XK - IK) > 0.01) GO TO 20
        IF (ABS (XL - IL) > 0.01) GO TO 20
        WRITE (LU62, 99994, IOSTAT = IOST) IH, IK, IL, RISI
        GO TO 20
      END IF
   30 WRITE (LU62, 99998, IOSTAT = IOST)
      CLOSE (UNIT = LU61)
      CLOSE (UNIT = LU62)
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT ('HKLF 4')
99998 FORMAT (1X)
99994 FORMAT (3I4, A)
      END SUBROUTINE S902
 
      SUBROUTINE S903
C * REFERENCES LIST
      USE files
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: LU
      LU = LU61
      OPEN  (LU, FILE = COMPD(1:IC)//'.txt', STATUS = 'UNKNOWN')
      WRITE (LU, 99999, IOSTAT = IOST) COMPD(1:IC)
      WRITE (LU, 99910, IOSTAT = IOST) CHAR (12)
      WRITE (LU, 99911, IOSTAT = IOST)
      WRITE (LU, 99912, IOSTAT = IOST)
      WRITE (LU, 99914, IOSTAT = IOST)
      WRITE (LU, 99915, IOSTAT = IOST)
      WRITE (LU, 99921, IOSTAT = IOST)
      WRITE (LU, 99922, IOSTAT = IOST)
      WRITE (LU, 99924, IOSTAT = IOST)
      WRITE (LU, 99925, IOSTAT = IOST)
      WRITE (LU, 99927, IOSTAT = IOST)
      WRITE (LU, 99928, IOSTAT = IOST)
      WRITE (LU, 99930, IOSTAT = IOST)
      WRITE (LU, 99931, IOSTAT = IOST)
      RETURN
99999 FORMAT ('XRay Structure Determination of ', A, /)
99910 FORMAT (A, 5X, 'References',/)
99911 FORMAT (/, 5X,
     1 'Altomare, A., Cascarano, G., Giacovazzo,C. & Guagliardi, A.', /,
     2 '(1993). J. Appl. Cryst. 26, 343-350.')
