      SUBROUTINE S904
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: K
      INTEGER :: N
      CHARACTER(len=12) :: HKLP
      EXST = .FALSE.
C * FIND OUT ABOUT DIRECTION COSINES
      ISPR(37) = 0
      INQUIRE (FILE = 'hklf/shelx.hkl', EXIST = EXST)
      IF (EXST) THEN
        OPEN (LU61, FILE = 'hklf/shelx.hkl', STATUS = 'UNKNOWN')
        READ (LU61, 99999, IOSTAT = IOST) LINE
        IF (IOST > 0) GO TO 10
        DO K = 1, 48
          IF (LINE(81 - K:81 - K) /= ' ' .AND.
     1      LINE(81 - K:81 - K) /= CHAR (13)) THEN
            IF (K < 10) THEN
              ISPR(37) = 1
              GO TO 10
            END IF
          END IF
        END DO
   10   IF (ISPR(37) > 0) THEN
C * COUNT NUMBER OF PSI-SCANS
   20     READ (LU61, 99999, IOSTAT = IOST) LINE
          IF (IOST == -1) GO TO 30
          IF (LINE(1:5) /= '     ') GO TO 20
          N = 0
          DO
            READ (LU61, 99999, IOSTAT = IOST) LINE
            IF (IOST == -1) GO TO 30
            IF (N == 0) THEN
              N    = 1
              HKLP = LINE(1:12)
            ELSE
              IF (LINE(1:12) == HKLP) THEN
                N = N + 1
                IF (N == 36) ISPR(37) = ISPR(37) + 1
              ELSE
                N    = 1
                HKLP = LINE(1:12)
              END IF
            END IF
          END DO
   30     CONTINUE
        END IF
        CLOSE (UNIT = LU61)
      END IF
      RETURN
99999 FORMAT (A)
      END SUBROUTINE S904
 
      SUBROUTINE S905
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: N
      INTEGER :: IDET
      IF (KN /= 9) THEN
        ISPR(310) = 0
        BCD = 'TWIN-LAWS'//CHAR (0)
   10   CALL GGIP (HORS, VERT, 0.0, 1)
        CALL PLA439 (0.0,  BCD, 9, 1.0, 4, 8, 8.1, VERT - 1.3)
        CALL PLA439 (0.0,  BCD, 9, 1.0, 2, 8, 7.9, VERT - 1.4)
        DO I = 1, 4
          WRITE (LINE, 99999, IOSTAT = IOST) I, (ITWN(J, I), J = 1, 9)
          CALL PLA439 (0.0, LINE, 70, 0.35, 1, 2, 0.1,
     1         VERT - 2.5 - I * 0.5)
        END DO
C * WHAT NEXT ?
C * DEFAULT: Enter Twin matrix (9 components) or #[0]
        CALL PLA012 (14, 1)
        IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 10
        IF (IGGT(1:4) == 'EXIT') GO TO 20
        LINE = IGGT
        CALL GEN038 (IGGT, 1, 80)
        CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
        IF (KN == 1) THEN
          IF (FN(1) > 0 .AND. FN(1) <= 3) THEN
            N = NINT (FN(1))
            DO I = 1, 9
              FN(I) = ITWN(I, N)
            END DO
          ELSE
            GO TO 20
          END IF
        ELSE IF (KN /= 9) THEN
          GO TO 20
        END IF
      END IF
      CALL GEN010 (FN, IDET, 0)
      IF (IDET /= 0) THEN
        ISPR(310) = 1
        DO I = 1, 9
          ISPR(310 + I) = NINT (FN(I))
        END DO
      ELSE
        CALL PLA015 (0, 37)
      END IF
   20 RETURN
99999 FORMAT (I3, ' : ', 9I5)
      END SUBROUTINE S905
 
      SUBROUTINE S909 (STRING)
      IMPLICIT NONE
      INTEGER :: L
      INTEGER :: KERR
      INTEGER :: CHDIR
      CHARACTER(len=*)   :: STRING
      CHARACTER(len=256) :: P
      LOGICAL :: DINQ
      L = LEN(STRING)
      P = 'mkdir '//STRING(1:L)
C * INQUIRE WHETHER sub-DIRECTORY 'STRING' EXISTS
C * CREATE sub-DIRECTORY WHEN IT DOES NOT EXIST
      IF (.NOT. DINQ (STRING(1:L))) THEN
        KERR = 0
        CALL SPAWN (P, 0, .true., KERR)
      END IF
C * CHANGE TO sub-DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (STRING(1:L)) /= 0) CALL S925 (1)
      RETURN
      END SUBROUTINE S909
 
      SUBROUTINE S910
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: ICOL
      INTEGER :: NCOL
      INTEGER :: IOST
      REAL :: XSH
      REAL :: YVRT
      CHARACTER(len=80) :: LIJN
      YVRT = VRTS * VERT
      XSH  = HORS - YVRT
      CALL GGIP (0.0, 5.0 + FLOAT (IGBL(68)), 0.0, 0)
      CALL GGIP (0.0,         -2.0, 0.0, 0)
      CALL GGIP (XSH,         0.05, 0.0, 3)
      CALL GGIP (XSH,         YVRT, 0.0, 2)
      CALL GGIP (HORS - 0.05, YVRT, 0.0, 2)
      CALL GGIP (HORS - 0.05, 0.05, 0.0, 2)
      CALL GGIP (XSH,   0.05, 0.0, 2)
      CALL GGIP (0.0,   0.0,  0.0, 3)
      IF (ISPR(6) < 0) CALL PLA439 (0.0, '?', 1, 10.0, 5, 12,
     1                    (HORS + XSH) / 2.0 - 3.0, 3.0)
      VRT = VRT - 0.6
      IF (ISPR(110) > 0) THEN
        WRITE (LIJN, 99999, IOSTAT = IOST) (SFC(I), I = 1, ISPR(110))
        CALL PLA439 (0.0,  LIJN, 80, 0.35, 1, 2, 0.3, VRT)
        VRT = VRT - 0.6
        WRITE (LIJN, 99998, IOSTAT = IOST)
     1    (ISPR(I + 136), I = 1, ISPR(110))
        CALL PLA439 (0.0,  LIJN, 80, 0.35, 1, 2, 0.3, VRT)
        WRITE (LIJN, 99994, IOSTAT = IOST) CPR(1)
        CALL PLA439 (0.0,  LIJN, 7, 0.5, 2, 2, HORS - 3.2, VRT)
        VRT = VRT - 0.6
        WRITE (LIJN, 99997, IOSTAT = IOST)
     1    (ISPR(I + 120), I = 1, ISPR(110))
        CALL PLA439 (0.0,  LIJN, 80, 0.35, 1, 2, 0.3, VRT)
        VRT = VRT - 0.6
        WRITE (LIJN, 99996, IOSTAT = IOST)
     1    (ISPR(I + 152), I = 1, ISPR(110))
        CALL PLA439 (0.0,  LIJN, 80, 0.35, 1, 2, 0.3, VRT)
      ELSE
        VRT = VRT - 1.8
      END IF
      VRT  = VRT - 1.0
      LIJN = 'StrDetStage DETAILS '
      CALL PLA439 (0.0, LIJN, 40, 0.45, 5 + IGBL(68), 3, 0.3, VRT)
      VRT  = VRT - 1.5
      LIJN = 'SpaceGroup  '//CPR(100)
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(1)(1:4) == 'TRMX' .OR. CPR(1)(1:4) == 'SPGR') THEN
        ICOL = 2
      ELSE
        ICOL = 5 + IGBL(68)
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      VRT  = VRT - 1.0
      IF (ISPR(120) /= 0) WRITE (LIJN5, 99993, IOSTAT = IOST)
     1   ISPR(120)
      LIJN = 'Z           '//LIJN5
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(100)(1:6) /= '      ' .AND. ISPR(120) == 0) THEN
        ICOL = 2
      ELSE
        ICOL = 5 + IGBL(68)
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      VRT = VRT - 1.0
      LIJN = 'AbsCorrMetd '//CPR(202)
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      ICOL = 5 + IGBL(68)
      NCOL = 12
      CALL PLA439 (0.0, LIJN, NCOL, 0.45, ICOL, 2, 0.3, VRT)
      VRT  = VRT - 1.0
      LIJN = 'PhasingMetd '//CPR(203)
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(1)(1:6) == 'SHELXS' .OR.
     1    CPR(1)(1:6) == 'SHELXD' .OR.
     2    CPR(1)(1:6) == 'DIRDIF' .OR.
     2    CPR(1)(1:3) == 'SIR') THEN
        CALL PLA439 (0.0, LIJN, 40, 0.45, 0, 2, 0.3, VRT)
        ICOL = 2
        LIJN = 'PhasingMetd '//CPR(1)
        NCOL = 40
      ELSE
        ICOL = 5 + IGBL(68)
        NCOL = 12
      END IF
      CALL PLA439 (0.0, LIJN, NCOL, 0.45, ICOL, 2, 0.3, VRT)
      CALL GGIP (0.0, 0.0, 0.0, 6)
      VRT  = VRT - 1.0
      LIJN = 'Add H-Atoms '//CPR(206)
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(1)(1:4) == 'HDIF') THEN
        ICOL = 2
        LIJN = 'Add H-Atoms HDIF'
        NCOL = 40
      ELSE IF (CPR(1)(1:4) == 'HFIX') THEN
        ICOL = 2
        LIJN = 'Add H-Atoms HFIX'
        NCOL = 40
      ELSE
        IF (ISPR(112) > 0 .OR. ISPR(6) <= 0) THEN
          ICOL = 5 + IGBL(68)
        ELSE
          ICOL = 4
        END IF
      END IF
      CALL PLA439 (0.0, LIJN, NCOL, 0.45, 5 + IGBL(68), 2, 0.3, VRT)
      VRT = VRT - 1.0
      CALL PLA439 (0.0, '                R   wR2    S',
     1             28, 0.45, 5 + IGBL(68), 2, 0.3, VRT)
      VRT = VRT - 1.0
      ICOL = 1
      IF (ISPR(6) == 1) THEN
        WRITE (LIJN1, 99995, IOSTAT = IOST)
     1    SPAR(202), SPAR(203), SPAR(133)
      ELSE IF (ISPR(6) == 0) THEN
        ICOL = 0
      END IF
      LIJN = 'Iso   Refin '//LIJN1
      CALL PLA439 (0.0, LIJN, 40, 0.45, ICOL, 2, 0.3, VRT)
      IF (CPR(2)(1:3) == 'ISO') THEN
        ICOL = 2
      ELSE
        ICOL = 5 + IGBL(68)
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      VRT  = VRT - 1.0
      IF (ISPR(6) == 2 .OR.
     1 (ISPR(6) == 3 .AND. LIJN2(1:5) == '     '))
     2  WRITE (LIJN2, 99995, IOSTAT = IOST)
     3   SPAR(202), SPAR(203), SPAR(133)
      LIJN = 'Aniso Refin '//LIJN2
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(2)(1:5) == 'ANISO') THEN
        ICOL = 2
      ELSE
        ICOL = 5 + IGBL(68)
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      VRT  = VRT - 1.0
      IF (CPR(106)(1:4) == 'HATS')
     1  WRITE (LIJN3, 99995, IOSTAT = IOST)
     1    SPAR(202), SPAR(203), SPAR(133)
      LIJN = 'H-AtomRefin '//LIJN3
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(2)(1:4) == 'HATS') THEN
        ICOL = 2
      ELSE
        IF (ISPR(112) > 0 .OR. ISPR(6) <= 0) THEN
          ICOL = 5 + IGBL(68)
        ELSE
          ICOL = 4
        END IF
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      VRT  = VRT - 1.0
      IF (CPR(106)(1:6) == 'WEIGHT')
     1  WRITE (LIJN4, 99995, IOSTAT = IOST)
     2    SPAR(202), SPAR(203), SPAR(133)
      LIJN = 'WeightRefin '//LIJN4
      CALL PLA439 (0.0, LIJN, 40, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(2)(1:6) == 'WEIGHT') THEN
        ICOL = 2
      ELSE
        ICOL = 5 + IGBL(68)
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      VRT  = VRT - 1.5
      LIJN = 'Valid-Alert'//VALIDATION(2:)
      CALL PLA439 (0.0, LIJN, 29, 0.45, 1, 2, 0.3, VRT)
      IF (CPR(1)(1:5) == 'VALID') THEN
        ICOL = 2
      ELSE
          ICOL = 5 + IGBL(68)
      END IF
      CALL PLA439 (0.0, LIJN, 12, 0.45, ICOL, 2, 0.3, VRT)
      CALL GGIP (0.0, 0.0, 0.0, 6)
      IF (ISPR(50) == 0 .AND. CPR(105)(1:2) /= 'Z ') CALL S410 (0)
      IF (ISPR(6) >= 5) THEN
        IGBL(50) = 0
   10   CALL PLA297 (2)
        IF (IGGT(1:4) == 'CALC')  GO TO 10
C * DISPLAY VALIDATION REPORT
        CALL PLA235 (2)
      END IF
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT ('Elem ', 2(2X, A), 14(1X, A))
99998 FORMAT ('Form ', 2I4, 14I3)
99997 FORMAT ('Unit ', 2I4, 14I3)
99996 FORMAT ('Cont ', 2I4, 14I3)
99995 FORMAT (F5.3, F6.3, F5.2)
99994 FORMAT (A)
99993 FORMAT (I5)
      END SUBROUTINE S910
 
      INTEGER FUNCTION S913 (LINE)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      CHARACTER(len=80) :: LINE
      N = 0
C * COUNT FIELDS
      K = 0
      J = 0
      I = 0
   10 I = I + 1
      IF (I <= 80) THEN
        IF (LINE(I:I) /= ' ') THEN
          IF (J == 0) THEN
            K = K + 1
            IF (K == 9) THEN
              N = I - 1
              GO TO 20
            END IF
            J = 1
          END IF
        ELSE
          J = 0
        END IF
        GO TO 10
      END IF
   20 S913 = N
      RETURN
      END FUNCTION S913
 
      SUBROUTINE S914
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: M
      INTEGER :: N
      INTEGER :: LU
      INTEGER :: L1
      INTEGER :: L2
      INTEGER :: L3
      INTEGER :: L4
      INTEGER :: L5
      INTEGER :: L1M
      INTEGER :: L2M
      INTEGER :: L3M
      INTEGER :: L4M
      INTEGER :: L5M
      INTEGER :: LMX
      INTEGER :: N00
      INTEGER :: N000
      INTEGER :: IEND
      INTEGER :: NLEN1
      INTEGER :: NLEN2
      INTEGER :: NLEN3
      INTEGER :: NLEN4
      INTEGER :: NP000
      INTEGER :: LISDOT
      INTEGER :: CHDIR
      INTEGER :: S913
      REAL :: DSKUSE
      CHARACTER(len=80)  :: LIJN
      CHARACTER(len=132) :: LIN
      LISDOT = 0
      L1     = 0
      NP000  = 0
      IF (KL > 1) THEN
        IF (JFL(2)(1:3) == 'ALL') THEN
          LISDOT = 1
        END IF
      ELSE
        LISDOT = 0
      END IF
C * DISPLAY DIRECTORY STRUCTURE AND DISK USAGE
      LU   = 31
      N00  = 0
      KERR = 0
      CALL SPAWN ('du -s . > du.lis', 0, .true., KERR)
      OPEN (LU, FILE = 'du.lis', STATUS = 'UNKNOWN')
      CALL GEN072 (LINE, JFL, FN, KL, KN, LU, LU6, 1, 1, 80, 10, NP17)
      DSKUSE = FN(1) / 1024.0
      CLOSE (UNIT = LU)
      KERR = 0
      CALL SPAWN ('rm du.lis', 0, .true., KERR)
      OPEN (LU, FILE = 'tree.lis', STATUS = 'UNKNOWN')
      WRITE (LU, 99999, IOSTAT = IOST) FNM(1:INZ - 1), DSKUSE
      KERR = 0
      CALL SPAWN ('ls -al | sort -r -k 1,2 > tree.ls0', 0, .true., KERR)
      OPEN (LU61, FILE = 'tree.ls0', STATUS = 'UNKNOWN')
C * DETERMINE FILENAME POSITION
   10 READ (LU61, 99998, IOSTAT = IOST) LIN
      IF (IOST == -1) GO TO 20
      L1 = S913 (LIN)
      IF (L1 == 0) GO TO 10
   20 CALL GEN108 (LU61, 0)
C * LOOP OVER ENTRIES
   30 READ (LU61, 99998, IOSTAT = IOST) LIN
      IF (IOST == -1) GO TO 300
      L1M  = MIN (132, L1 + 80)
      LINE = LIN(L1 + 1: L1M)
C * SKIP IRRELEVANT ENTRIES
      IF (LISDOT == 0 .AND. LINE(1:1) == '.') GO TO 30
      IF (LINE(1:3) == '.  ') THEN
        GO TO 30
      ELSE IF (LINE(1:3) == '.. ') THEN
        GO TO 30
      ELSE IF (LINE(1:4) == 'tree') THEN
        GO TO 30
      ELSE IF (LINE(1:4) == '    ') THEN
        GO TO 30
      END IF
C * CHECK FOR DIRECTORY/NON-DIRECTORY ENTRY
      IF (LIN(1:1) /= 'd') THEN
        WRITE (LU, 99998, IOSTAT = IOST) LINE(1:79)
        GO TO 30
      ELSE
        IF (LINE(1:2) == '01') N00 = 1
        IF (LINE(1:2) == '00' .AND. N00 == 1) GO TO 30
        N000 = 0
        LMX = L1M - L1
        DO I = 1, LMX
          IF (LINE(LMX + 1 - I: LMX + 1 - I) /= ' ') GO TO 50
        END DO
   50   NLEN1 = LMX + 1 - I
        WRITE (LU, 99997, IOSTAT = IOST) LINE(1:NLEN1)
C * ERROR HANDLING
        IF (CHDIR (LINE(1:NLEN1)) /= 0) CALL S925 (1)
        KERR = 0
        CALL SPAWN ('ls -al | sort -r -k 1,2 > tree.ls1', 0,
     1    .true., KERR)
        OPEN (LU62, FILE = 'tree.ls1', STATUS = 'UNKNOWN')
   60   READ (LU62, 99998, IOSTAT = IOST) LIN
        IF (IOST == -1) GO TO 70
        L2 = S913 (LIN)
        IF (L2 == 0) GO TO 60
   70   CALL GEN108 (LU62, 0)
   80   READ (LU62, 99998, IOSTAT = IOST) LIN
        IF (IOST == -1) GO TO 290
        L2M  = MIN (132, L2 + 80)
        LINE = LIN(L2 + 1: L2M)
        IF (LISDOT == 0 .AND. LINE(1:1) == '.') GO TO 80
        IF (LINE(1:3) == '.  ') THEN
          GO TO 80
        ELSE IF (LINE(1:3) == '.. ') THEN
          GO TO 80
        ELSE IF (LINE(1:4) == 'tree') THEN
          GO TO 80
        ELSE IF (LINE(1:4) == '    ') THEN
          GO TO 80
        END IF
        IF (LIN(1:1) /= 'd') THEN
          WRITE (LU, '('' I-- '', A)', IOSTAT = IOST) LINE(1:74)
          GO TO 80
        ELSE
          READ (LINE(1:3), '(I3)', IOSTAT = IOST) N
          IF (IOST > 0) GO TO 90
          IF (N /= 0) N000 = 1
          IF (LINE(1:3) == '000' .AND. N000 == 1) GO TO 80
          NP000 = 0
   90     LMX = L2M - L2
          DO I = 1, LMX
            IF (LINE(LMX + 1 - I: LMX + 1 - I) /= ' ') GO TO 110
          END DO
  110     NLEN2 = LMX + 1 - I
          WRITE (LU, '('' I-- '', A, ''/'')', IOSTAT = IOST)
     1      LINE(1:NLEN2)
C * ERROR HANDLING
          IF (CHDIR (LINE(1:NLEN2)) /= 0) CALL S925 (1)
          KERR = 0
          CALL SPAWN ('ls -al | sort -r -k 1,2 > tree.ls2', 0,
     1      .true., KERR)
          OPEN (LU63, FILE = 'tree.ls2', STATUS = 'UNKNOWN')
  120     READ (LU63, 99998, IOSTAT = IOST) LIN
          IF (IOST == -1) GO TO 130
          L3 = S913(LIN)
          IF (L3 == 0) GO TO 120
  130     CALL GEN108 (LU63, 0)
  140     READ (LU63, 99998, IOSTAT = IOST) LIN
          IF (IOST == -1) GO TO 280
          L3M = MIN (132, L3 + 80)
          LINE = LIN(L3 + 1: L3M)
          IF (LISDOT == 0 .AND. LINE(1:1) == '.') GO TO 140
          IF (LINE(1:3) == '.  ') THEN
            GO TO 140
          ELSE IF (LINE(1:3) == '.. ') THEN
            GO TO 140
          ELSE IF (LINE(1:2) == '00') THEN
            GO TO 140
          ELSE IF (LINE(1:4) == '    ') THEN
            GO TO 140
          END IF
          IF (LIN(1:1) /= 'd') THEN
            WRITE (LU, '(6X, ''I-- '', A)', IOSTAT = IOST) LINE(1:69)
            GO TO 140
          ELSE
            READ (LINE(1:3), '(I3)', IOSTAT = IOST) M
            IF (IOST > 0) GO TO 150
            IF (M /= 0) NP000 = 1
            IF (LINE(1:3) == '000' .AND. NP000 == 1) GO TO 140
  150       LMX = L3M - L3
            DO I = 1, LMX
              IF (LINE(LMX + 1 - I: LMX + 1 - I) /= ' ') GO TO 170
            END DO
  170       NLEN3 = LMX + 1 - I
            WRITE (LU, '(6X, ''I-- '', A, ''/'')', IOSTAT = IOST)
     1        LINE(1:NLEN3)
C * ERROR HANDLING
            IF (CHDIR (LINE(1:NLEN3)) /= 0) CALL S925 (1)
            KERR = 0
            CALL SPAWN ('ls -al | sort -r -k 1,2 > tree.ls3', 0,
     1        .true., KERR)
            OPEN (LU64, FILE = 'tree.ls3', STATUS = 'UNKNOWN')
  180       READ (LU64, 99998, IOSTAT = IOST) LIN
            IF (IOST == -1) GO TO 190
            L4 = S913(LIN)
            IF (L4 == 0) GO TO 180
  190       CALL GEN108 (LU64, 0)
  200       READ (LU64, 99998, IOSTAT = IOST) LIN
            IF (IOST == -1) GO TO 270
            L4M = MIN (132, L4 + 80)
            LINE = LIN(L4 + 1: L4M)
            IF (LISDOT == 0 .AND. LINE(1:1) == '.') GO TO 200
            IF (LINE(1:3) == '.  ') THEN
              GO TO 200
            ELSE IF (LINE(1:3) == '.. ') THEN
              GO TO 200
            ELSE IF (LINE(1:4) == 'tree') THEN
              GO TO 200
            ELSE IF (LINE(1:4) == '    ') THEN
              GO TO 200
            END IF
            IF (LIN(1:1) /= 'd') THEN
              WRITE (LU, '(11X, ''I-- '', A)', IOSTAT = IOST) LINE(1:64)
              GO TO 200
            ELSE
              LMX = L4M - L4
              DO I = 1, LMX
                IF (LINE(LMX + 1 - I:LMX + 1 - I) /= ' ') GO TO 220
              END DO
  220         NLEN4 = LMX + 1 - I
              WRITE (LU, '(11X, ''I-- '', A, ''/'')', IOSTAT = IOST)
     1          LINE(1:NLEN4)
C * ERROR HANDLING
              IF (CHDIR (LINE(1:NLEN4)) /= 0) CALL S925 (1)
              KERR = 0
              CALL SPAWN ('ls -al | sort -r -k 1,2 > tree.ls4', 0,
     1          .true.,  KERR)
              OPEN (LU65, FILE = 'tree.ls4', STATUS = 'UNKNOWN')
  230         READ (LU65, 99998, IOSTAT = IOST) LIN
              IF (IOST == -1) GO TO 240
              L5 = S913(LIN)
              IF (L5 == 0) GO TO 230
  240         CALL GEN108 (LU65, 0)
  250         READ (LU65, 99998, IOSTAT = IOST) LIN
              IF (IOST == -1) GO TO 260
              L5M = MIN (132, L5 + 80)
              LINE = LIN(L5 + 1: L5M)
              IF (LISDOT == 0 .AND. LINE(1:1) == '.') GO TO 250
              IF (LINE(1:3) == '.  ') THEN
                GO TO 250
              ELSE IF (LINE(1:3) == '.. ') THEN
                GO TO 250
              ELSE IF (LINE(1:4) == 'tree') THEN
                GO TO 250
              ELSE IF (LINE(1:4) == '    ') THEN
                GO TO 250
              END IF
              WRITE (LU, '(16X, ''I-- '', A)', IOSTAT = IOST) LINE(1:59)
              GO TO 250
  260         CLOSE (UNIT = LU65)
              KERR = 0
              CALL SPAWN ('rm tree.ls4', 0, .true., KERR)
C * ERROR HANDLING
              IF (CHDIR ('..') /= 0) CALL S925 (1)
            END IF
            GO TO 200
  270       CLOSE (UNIT = LU64)
            KERR = 0
            CALL SPAWN ('rm tree.ls3', 0, .true., KERR)
C * ERROR HANDLING
            IF (CHDIR ('..') /= 0) CALL S925 (1)
          END IF
          GO TO 140
  280     CLOSE (UNIT = LU63)
          KERR = 0
          CALL SPAWN ('rm tree.ls2', 0, .true., KERR)
C * ERROR HANDLING
          IF (CHDIR ('..') /= 0) CALL S925 (1)
        END IF
        GO TO 80
  290   CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN ('rm tree.ls1', 0, .true., KERR)
C * ERROR HANDLING
        IF (CHDIR ('..') /= 0) CALL S925 (1)
      END IF
      GO TO 30
  300 CLOSE (UNIT = LU61)
      KERR = 0
      CALL SPAWN ('rm tree.ls0', 0, .true., KERR)
      CLOSE (UNIT = LU)
C * DISPLAY
      OPEN (UNIT = LU65, FILE = 'tree.lis',  STATUS = 'UNKNOWN')
  310 VRT = 19.4
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      CALL GGIP (HORS, VERT, 0.0, 1)
      IEND = 0
  320 READ (LU65, 99998, IOSTAT = IOST) LIJN
      IF (IOST == -1) GO TO 330
      N = INDEX (LIJN, '->')
      IF (N /= 0) LIJN(N:N+1) = 'to'
      VRT = VRT - 0.6
      CALL PLA439 (0.0, LIJN, 80, 0.375, 1, 2, 0.1, VRT)
      IF (VRT > 0.5) GO TO 320
      GO TO 340
  330 IEND = 1
C * WHAT NEXT ?
  340 CALL PLA012 (1, 1)
      IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
        IF (LRET == 2) THEN
          CALL GEN108 (LU65, 0)
          GO TO 310
        END IF
        LINE = IGGT
        CALL GEN038 (IGGT, 1, 80)
        IF (LINE(1:1) == 'N' .OR. LINE(1:1) == 'n') GO TO 350
      END IF
      IF (IEND == 0) GO TO 310
  350 CLOSE (UNIT = LU65)
      KERR = 0
      CALL SPAWN ('rm tree.lis', 0, .true., KERR)
      RETURN
99999 FORMAT ('Directory Structure for : ', A, ' - Disk Use = ',
     1         F6.2, ' Mb', /, 80('='))
99998 FORMAT (A)
99997 FORMAT (A, '/')
      END SUBROUTINE S914
 
      SUBROUTINE S915 (TEXT)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: IEND
      CHARACTER(len=*)  :: TEXT
      CHARACTER(len=80) :: LIJN
C * MANAGE LOG-FILE
      IF (TEXT(1:3) == 'LOG') THEN
        CLOSE (UNIT = LU60)
        OPEN (UNIT = LU60, FILE = FNM(1:INZ)//'s.log',
     1        STATUS = 'UNKNOWN')
   10   VRT = 18.8
        BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
        CALL GGIP (HORS, VERT, 0.0, 1)
        IEND = 0
        LIJN = 'Log Date       tm/sg/pn    Action'
        CALL PLA439 (0.0, LIJN, 33, 0.375, 5 + IGBL(68), 2, 2.5, VRT)
   20   READ (LU60, 99998, IOSTAT = IOST) LIJN
        IF (IOST == -1) GO TO 30
        VRT = VRT - 0.6
        CALL PLA439 (0.0, LIJN, 80, 0.375, -1, 2, 0.1, VRT)
        IF (VRT > 0.5) GO TO 20
        GO TO 40
   30   IEND = 1
C * WHAT NEXT ?
   40   CALL PLA012 (1, 1)
        IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
          IF (LRET == 2) THEN
            CALL GEN108 (LU60, 0)
            GO TO 10
          END IF
          LINE = IGGT
          CALL GEN038 (IGGT, 1, 80)
          IF (LINE(1:1) == 'N') GO TO 100
        END IF
        IF (IEND == 0) GO TO 10
  100   CLOSE (UNIT = LU60)
        OPEN (UNIT = LU60, FILE = FNM(1:INZ)//'s.log',
     1    POSITION = 'APPEND', FORM = 'FORMATTED', STATUS = 'UNKNOWN')
      ELSE
        CALL DATE_TIME (DATIJD)
C * HANDLE OPEN/APPEND LOG-FILE
        INQUIRE (LU60, OPENED = OPEND)
        IF (.NOT. OPEND) THEN
          OPEN (UNIT = LU60, FILE = FNM(1:INZ)//'s.log',
     1      POSITION = 'APPEND', FORM = 'FORMATTED', STATUS = 'UNKNOWN')
        END IF
        WRITE (LU60, 99999, IOSTAT = IOST) DATIJD, CPR(104), TEXT
      END IF
      RETURN
99999 FORMAT (A, 1X, A, ' : ', A)
99998 FORMAT (A)
      END SUBROUTINE S915
 
      SUBROUTINE S916
      USE files
      USE parameters
      USE cggt
      USE ccom
      IMPLICIT NONE
      INTEGER :: IEND
      CHARACTER(len=80)  :: LIJN
C * SHOW S.RES
      OPEN (UNIT = LU61, FILE = 's.res',  STATUS = 'UNKNOWN')
      READ (LU61, 99999, IOSTAT = IOST) LIJN
      IF (IOST == -1) GO TO 100
      CALL GEN108 (LU61, 0)
   10 VRT = 18.8
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      CALL GGIP (HORS, VERT, 0.0, 1)
      IEND = 0
      LIJN = 'LISTING OF CURRENT s.res CONTENTS'
      CALL PLA439 (0.0, LIJN, 33, 0.375, 5 + IGBL(68), 2, 6.5, VRT)
   20 READ (LU61, 99999, IOSTAT = IOST) LIJN
      IF (IOST == -1) GO TO 30
      VRT = VRT - 0.6
      CALL PLA439 (0.0, LIJN, 80, 0.375, -1, 2, 0.1, VRT)
      IF (VRT > 0.5) GO TO 20
      GO TO 40
   30 IEND = 1
C * WHAT NEXT ?
   40 CALL PLA012 (1, 1)
      IF (IGGT(1:1) /= ' ' .AND. IGGT(1:1) /= '!') THEN
        IF (LRET == 2) THEN
          CALL GEN108 (LU61, 0)
          GO TO 10
        END IF
        LINE = IGGT
        CALL GEN038 (IGGT, 1, 80)
        IF (LINE(1:1) == 'N') GO TO 100
      END IF
      IF (IEND == 0) GO TO 10
  100 CLOSE (UNIT = LU61)
      RETURN
99999 FORMAT (A)
      END SUBROUTINE S916
 
      SUBROUTINE S917
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: L1
      INTEGER :: L2
      INTEGER :: L3
      INTEGER :: L4
      INTEGER :: L5
      INTEGER :: IB
      INTEGER :: IFN
      INTEGER :: L1M
      INTEGER :: LMX
      INTEGER :: CHDIR
      INTEGER, DIMENSION(2) :: IFA
      CHARACTER(len=132) :: LIN
      CHARACTER(len=30)  :: FNAM
      CHARACTER(len=30), DIMENSION(2) :: FNAMA
      EXST = .FALSE.
      L1   = 0
C * RESOLVE LINKS
C * FIRST, DETERMINE STARTING POSITION OF FILENAME in FILENAME LISTING
      KERR = 0
      CALL SPAWN ('ls -l s.log > lsl.lis', 0, .true., KERR)
      OPEN (LU61, FILE = 'lsl.lis', STATUS = 'UNKNOWN')
      DO
        READ (LU61, 99998, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 30
        I = INDEX (LINE, ' s.log')
        IF (I > 0) GO TO 20
      END DO
   20 L1 = I
   30 CLOSE (UNIT = LU61)
      KERR = 0
      CALL SPAWN ('rm lsl.lis', 0, .true., KERR)
C * RESOLVE s.res, s.hkl and .s.dbf LINKS
      INQUIRE (FILE = FNM(1:INZ)//'tm/sg', EXIST = EXST)
      IF (EXST) THEN
        FNAMA(1)(1:5) = 's.res'
        IFA(1) = 5
        FNAMA(2)(1:5) = 's.hkl'
        IFA(2) = 5
        DO 110 J = 1, 2
          IFN  = IFA(J)
          FNAM = FNAMA(J)
          IF (CHDIR(FNM(1:INZ)//'tm/sg') /= 0) GO TO 120
   40     INQUIRE (FILE = FNAM(1:IFN), EXIST = EXST)
          IF (.NOT. EXST) GO TO 110
          KERR = 0
          CALL SPAWN
     1      ('ls -l '//FNAM(1:IFN)//' > '//FNM(1:INZ)//'lsl.lis',
     2       0, .true., KERR)
          OPEN (LU61, FILE = FNM(1:INZ)//'lsl.lis', STATUS = 'UNKNOWN')
          READ (LU61, 99998, IOSTAT = IOST) LIN
          IF (IOST == -1) GO TO 110
          CLOSE (UNIT = LU61)
          KERR = 0
          CALL SPAWN ('rm '//FNM(1:INZ)//'lsl.lis', 0, .true., KERR)
          L1M = MIN (132, L1 + 80)
          LINE = LIN(L1 + 1: L1M)
          LMX = L1M - L1
          DO I = 1, LMX
            IF (LINE(LMX + 1 - I: LMX + 1 - I) /= ' ') GO TO 60
          END DO
   60     L4 = LMX + 1 - I
          DO I = 1, L4 - 1
            IF (LINE(L4 - I: L4 - I) == ' ') GO TO 80
          END DO
          I  = L4
   80     L2 = L4 - I + 1
C * TEST FOR LINK "l"
          IF (LIN(1:1) == 'l') THEN
            DO I = L2 + 1, L4
              IF (LINE(L4 - I + L2:L4 -I + L2) == '/') GO TO 100
            END DO
  100       L3 = L4 + L2 - I
            IF (CHDIR(LINE (L2:L3-1)) /= 0) GO TO 120
            IFN = L4 - L3
            FNAM(1:IFN) = LINE(L3+1:L4)
            GO TO 40
          ELSE
            KERR = 0
            CALL SPAWN ('pwd > '//FNM(1:INZ)//'lsl.lis', 0,
     1        .true., KERR)
            OPEN (LU61, FILE =
     1        FNM(1:INZ)//'lsl.lis', STATUS = 'UNKNOWN')
            READ (LU61, 99998, IOSTAT = IOST) LIN
            IF (IOST == -1) GO TO 110
            CLOSE (UNIT = LU61)
            KERR = 0
            CALL SPAWN ('rm '//FNM(1:INZ)//'lsl.lis', 0, .true., KERR)
            IB = 1
            I  = 80
            CALL GEN039 (1, LIN, 1, 80, IB, I)
            L5 = I + 1
            LIN(L5:L5) = '/'
            LNKS(J)(1:1) = ' '
            WRITE (LNKS(J)(2:), 99999, IOSTAT = IOST)
     1        FNAMA(J)(1:IFA(J)), LIN(1:L5)//LINE(L2:L4)
          END IF
  110   CONTINUE
      END IF
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
  120 IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
      IGBL(38) = 0
      RETURN
99999 FORMAT (A, ' Resolves to File: ', A)
99998 FORMAT (A)
      END SUBROUTINE S917
 
      SUBROUTINE S918
      USE files
      USE ccom
      IMPLICIT NONE
C * LASER S.LOG
      CALL GEN125 (1, LU6, 'laser s.log      (y/n[n])')
      READ  (LU5, '(A)') LINE(1:1)
      IF (LINE(1:1) == 'y' .OR. LINE(1:1) == 'Y') THEN
        KERR = 0
        CALL SPAWN ('laser s.log', 0, .true., KERR)
      END IF
      RETURN
      END SUBROUTINE S918
 
      SUBROUTINE S920 (MODE)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE lplat
      IMPLICIT NONE
      INTEGER :: MODE
      INTEGER :: IGBL50
C * MODE =  1 - SAVE
C * MODE = -1 - RECOVER
      IF (MODE > 0) THEN
        OPEN (LU61, FILE = FNM(1:INZ)//'.s.dbf', FORM = 'UNFORMATTED',
     1              STATUS = 'UNKNOWN')
        WRITE (LU61) SPAR, ISPR, TM, OM, OX
        WRITE (LU61) TITL, SFAC, CPR, VALIDATION
        WRITE (LU61) IGBL
        CLOSE (UNIT = LU61)
      ELSE
        IGBL50 = IGBL(50)
C * RECOVER DATA FROM .s.dbf
        OPEN  (LU61, FILE = '.s.dbf', FORM = 'UNFORMATTED',
     1                                STATUS = 'OLD', IOSTAT = IOST)
        IF (IOST == 0) THEN
          READ  (LU61) SPAR, ISPR, TM, OM, OX
          READ  (LU61) TITL, SFAC, CPR, VALIDATION
          READ  (LU61) IGBL
          CLOSE (UNIT = LU61)
        END IF
C * RECOVER TSPGR from FILE .spgr
        INQUIRE (FILE = 'tm/spgr/.spgr', EXIST = EXST)
        IF (EXST) THEN
          OPEN (LU61, FILE = 'tm/spgr/.spgr', STATUS = 'UNKNOWN',
     1                FORM = 'UNFORMATTED')
          READ (LU61) TSPGR
          CLOSE (UNIT = LU61)
        END IF
C * RECOVER TLATT from FILE .latt
        INQUIRE (FILE = 'latt/latt.trm', EXIST = EXST)
        IF (EXST) THEN
          OPEN (LU61, FILE = 'latt/latt.trm', STATUS = 'UNKNOWN',
     1                FORM = 'UNFORMATTED')
          READ (LU61) NRLT0, NRLT, NREXT, AVIOS, RMAX,
     1     RVL, NTL, TLATT, XCELL, LLAUE, RVAL, CLATT, BLATT, ELATT
          CLOSE (UNIT = LU61)
        END IF
        IGBL(50) = IGBL50
        IGBL(38) = 1
      END IF
      RETURN
      END SUBROUTINE S920
 
      SUBROUTINE S921 (MODE)
      USE parameters
      USE scom
      IMPLICIT NONE
      INTEGER :: MODE
      INTEGER, SAVE, DIMENSION(10) :: METHOD
C * SET PHASING METHOD ORDER
      IF (MODE == 0) THEN
          IF (IGBL(73) <= 0) THEN
            IGBL(73) = 1
C * TEST FOR HEAVY ATOM
            IF (SPAR(3) >= 15.0 .AND. IGBL(115) /= 0) THEN
              METHOD(1) = 5
              IGBL(108) = 1
            END IF
C * ADD SHELXS86
            IGBL(108)         = IGBL(108) + 1
            METHOD(IGBL(108)) = 1
C * ADD SIR97
            IF (IGBL(113) /= 0) THEN
              IGBL(108)         = IGBL(108) + 1
              METHOD(IGBL(108)) = 3
            END IF
C * ADD SHELXS97
            IF (IGBL(111) /= 0) THEN
              IGBL(108)         = IGBL(108) + 1
              METHOD(IGBL(108)) = 2
            END IF
C * ADD SIR2004
            IF (IGBL(114) /= 0) THEN
              IGBL(108)         = IGBL(108) + 1
              METHOD(IGBL(108)) = 4
            END IF
C * ADD SHELXD97
            IF (IGBL(112) /= 0) THEN
              IGBL(108)         = IGBL(108) + 1
              METHOD(IGBL(108)) = 6
            END IF
C * SHELXS97
          ELSE IF (IGBL(73) == 2) THEN
            IGBL(108)         = IGBL(108) + 1
            METHOD(IGBL(108)) = 2
C * SIR97
          ELSE IF (IGBL(73) == 3) THEN
            IGBL(108)         = IGBL(108) + 1
            METHOD(IGBL(108)) = 3
          END IF
C * GET NEXT PHASING METHOD
      ELSE IF (MODE < 0) THEN
        CPR(1) = ' '
        IF (IGBL(107) < IGBL(108)) THEN
          IGBL(107) = IGBL(107) + 1
          IF (METHOD(IGBL(107)) == 1) THEN
            CPR(1)  = 'SHELXS86'
            CPR(52) = 'TREF'
          ELSE IF (METHOD(IGBL(107)) == 2) THEN
            CPR(1)  = 'SHELXS'
            CPR(52) = 'TREF'
          ELSE IF (METHOD(IGBL(107)) == 3) THEN
            CPR(1)  = 'SIR97'
            CPR(72) = 'DEFAULT'
          ELSE IF (METHOD(IGBL(107)) == 4) THEN
            CPR(1)  = 'SIR2004'
            CPR(72) = 'DEFAULT'
          ELSE IF (METHOD(IGBL(107)) == 5) THEN
            CPR(1)  = 'DIRDIF'
            CPR(62) = 'PATTY'
          ELSE IF (METHOD(IGBL(107)) == 6) THEN
            CPR(1)  = 'SHELXD'
          ELSE IF (METHOD(IGBL(107)) == 8) THEN
            CPR(1)  = 'SHELXT'
          ELSE IF (METHOD(IGBL(107)) == 9) THEN
            CPR(1)  = 'SIR2011'
            CPR(72) = 'DEFAULT'
          END IF
        END IF
        IF (CPR(1)(1:1) == ' ') IGBL(50) = 0
      END IF
      RETURN
      END SUBROUTINE S921
 
      SUBROUTINE S922 (IER)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE sgxyz
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: IER
      INTEGER :: NUMS
      INTEGER :: GEN135
      INTEGER :: CHDIR
      CHARACTER(len=4) :: AUTO
      CHARACTER(len=4) :: PATT
      IF (IGBL(50) > 0) THEN
        AUTO = 'AUTO'
      ELSE
          AUTO = '    '
      END IF
      INQUIRE (FILE = 'hklf/.patt', EXIST = EXST)
      IF (.NOT. EXST) THEN
        PATT = 'PATR'
      ELSE
        OPEN (LU61, FILE = 'hklf/.patt', STATUS = 'UNKNOWN')
        READ (LU61, 99981) ISPR(99)
        CLOSE (UNIT = LU61)
        PATT = '    '
      END IF
C * CHECK FOR/CREATE-CHANGE TO SETUP-DIR UNDER user/s/compoundname/tm/sg
      CALL S909 ('tm/sg/setup')
C * CREATE s.res
      IF (ISPR(6) < 0) THEN
        OPEN  (LU61, FILE = 's.res', STATUS = 'UNKNOWN')
        WRITE (LU61, 99997, IOSTAT = IOST) TITL(1:6)
        WRITE (LU61, 99998, IOSTAT = IOST)
     1    SPAR(80), (SPAR(100 + I), I = 1, 6)
        WRITE (LU61, 99999, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
        WRITE (LU61, 99995, IOSTAT = IOST)
     1    (ISPR(I + 120), I = 1, ISPR(110))
        WRITE (LU61, 99991, IOSTAT = IOST) ISPR(100)
        DO I = 2, ISPR(101)
          NUMS = I
          CALL SGSM (17, LINE, SGX, NUMS, 0, IERR)
          WRITE (LU61, 99990, IOSTAT = IOST) LINE(1:60)
        END DO
        WRITE (LU61, 99994, IOSTAT = IOST)
     1    ((TM(I, J), J = 1, 3), I = 1, 3)
        CLOSE (UNIT = LU61)
        KERR = 0
        CALL SPAWN ('rm ../pn/s.res', 0, .true., KERR)
        CALL SPAWN ('mv s.res ../pn', 0, .true., KERR)
      END IF
C * SET UP s.bin FILE
C * GENERATE AND RUN FILE WITH: CELL, SPGR, SFAC, UNIT, HKLF, SETUP
      OPEN  (LU61, FILE = 's.ins', STATUS = 'UNKNOWN')
      WRITE (LU61, 99997, IOSTAT = IOST) TITL(1:6)
      WRITE (LU61, 99998, IOSTAT = IOST)
     1   SPAR(80), (SPAR(100 + I), I = 1, 6)
      WRITE (LU61, 99992, IOSTAT = IOST) CPR(100)
      WRITE (LU61, 99999, IOSTAT = IOST) (SFAC(I), I = 1, ISPR(110))
      WRITE (LU61, 99995, IOSTAT = IOST)
     1   (ISPR(I + 120), I = 1, ISPR(110))
C * TEST FOR UNIT MATRIX
      IF (GEN135 (TM) == 1) THEN
        WRITE (LU61, 99989, IOSTAT = IOST)
      ELSE
        WRITE (LU61, 99994, IOSTAT = IOST)
     1   ((TM(I, J), J = 1, 3), I = 1, 3)
      END IF
C * SETUP
      WRITE (LU61, 99996, IOSTAT = IOST) 1, AUTO, PATT
      CLOSE (UNIT = LU61)
      INQUIRE (FILE = 's.bin', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('rm s.bin', 0, .true., KERR)
      END IF
      INQUIRE (FILE = 'hklf3.hkl', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('rm hklf3.hkl', 0, .true., KERR)
      END IF
      KERR = 0
      CALL SPAWN
     1  ('sh -c '''//PLAPATH(1:IGBL(80))//' s.ins > setup.lis'' ',
     2    0, .true., KERR)
      INQUIRE (FILE = 's.hkp', EXIST = EXST)
      IF (EXST) THEN
        KERR = 0
        CALL SPAWN ('mv s.hkp hklf3.hkl', 0, .true., KERR)
      END IF
C * EXTRACT DATAREDUCTION DATA FROM s.lis
      OPEN (LU61, FILE = 'setup.lis', STATUS = 'UNKNOWN')
      IER = 0
   10 READ (LU61, 99982, IOSTAT = IOST) LINE(1:80)
      IF (IOST == -1) GO TO 40
      IF (LINE(39:46) == 'Rejected') THEN
        READ (LINE(1:5), 99988, IOSTAT = IOST) ISPR(70)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(41:48) == 'Rejected') THEN
        READ (LINE(1:7), 99984, IOSTAT = IOST) ISPR(70)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(7:12) == 'Unique') THEN
        READ (LINE(1:36), 99983, IOSTAT = IOST) ISPR(71), SPAR(150)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:5) == 'IHMIN') THEN
        READ (LINE(15:24), 99988, IOSTAT = IOST) ISPR(51), ISPR(52)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:5) == 'IKMIN') THEN
        READ (LINE(15:24), 99988, IOSTAT = IOST) ISPR(53), ISPR(54)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:5) == 'ILMIN') THEN
        READ (LINE(15:24), 99988, IOSTAT = IOST) ISPR(55), ISPR(56)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:5) == 'THMIN') THEN
        READ (LINE(15:24), 99987, IOSTAT = IOST) SPAR(51), SPAR(52)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:5) == 'Aver ') THEN
        READ (LINE(19:23), 99986, IOSTAT = IOST) SPAR(15)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:9) == 'Estimated') THEN
        READ (LINE(14:19), 99980, IOSTAT = IOST) SPAR(16)
        IF (IOST > 0) GO TO 10
      ELSE IF (LINE(1:5) == 'PATT ') THEN
        READ (LINE(9:11) , 99985, IOSTAT = IOST) ISPR(99)
        IF (IOST > 0) GO TO 10
C * CHECK FOR ERROR
      ELSE IF (LINE(1:6) == 'E: Unk') THEN
        IER = 1
      ELSE IF (LINE(1:9) == 'PATTERSON') THEN
        OPEN (LU62, FILE = 'patt.lis', STATUS = 'UNKNOWN')
   20   READ (LU61, 99982, IOSTAT = IOST) LINE(1:80)
        IF (IOST == -1) GO TO 30
        WRITE (LU62, 99982, IOSTAT = IOST) LINE(1:80)
        GO TO 20
   30   CLOSE (UNIT = LU62)
        GO TO 40
      END IF
      GO TO 10
   40 CLOSE (UNIT = LU61)
      IF (ISPR(70) > 0) ISPR(12) = 1
C * RETURN TO COMPOUND DIRECTORY
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * SAVE 'PATT DONE'
      OPEN (LU61, FILE = 'hklf/.patt', STATUS = 'UNKNOWN')
      WRITE (LU61, '(''PATT'', I3)', IOSTAT = IOST) ISPR(99)
      CLOSE (UNIT = LU61)
C * SAVE DATABASE
      CALL S915 ('Setup s.bin')
      CALL S920 (1)
      RETURN
99999 FORMAT ('SFAC ', 17(1X, A))
99998 FORMAT ('CELL ', F7.5, 6F10.4)
99997 FORMAT ('TITL ', A)
99996 FORMAT ('SETUP ', I5, 1X, 2A)
99995 FORMAT ('UNIT', 2I5, 14I4)
99994 FORMAT ('HKLF 4 1', 9F7.4)
99992 FORMAT ('SPGR ', A)
99991 FORMAT ('LATT ', I3)
99990 FORMAT ('SYMM ', A)
99989 FORMAT ('HKLF 4')
99988 FORMAT (2I5)
99987 FORMAT (2F5.1)
99986 FORMAT (2F5.2)
99985 FORMAT (I3)
99984 FORMAT (I7)
99983 FORMAT (I5, 23X, F8.0)
99982 FORMAT (A)
99981 FORMAT (4X, I3)
99980 FORMAT (F6.3)
      END SUBROUTINE S922
 
      SUBROUTINE S923 (C, K, N)
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: IOST
      CHARACTER(len=*) :: C
      I = 0
      J = 0
      IF (K == 0) THEN
        I = 1
        J = 3
      ELSE IF (K == 2) THEN
        I = 4
        J = 6
        C(3 : 3) = '/'
      END IF
      WRITE (C(I:J), 99999, IOSTAT = IOST) N
      IF (IOST /= 0) RETURN
      RETURN
99999 FORMAT (I3.3)
      END SUBROUTINE S923
 
      SUBROUTINE S924 (MODE)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: NR
      INTEGER :: MODE
      CHARACTER(len=3) :: CPN
      NR = 0
      OPEN (LU61, FILE = FNM(1:INZ)//'tm/sg/.save_nr',
     1      STATUS = 'UNKNOWN')
      READ (LU61, 99998, IOSTAT = IOST) NR
      IF (IOST == -1) GO TO 10
   10 NR = NR + 1
      CLOSE (UNIT = LU61)
      CALL S923 (CPN, 0, NR)
      KERR = 0
      CALL SPAWN ('mkdir '//FNM(1:INZ)//'tm/sg/'//CPN, 0, .true., KERR)
      CALL SPAWN (
     1'cp '//FNM(1:INZ)//'tm/sg/pn/.s.dbf '//FNM(1:INZ)//'tm/sg/'//CPN,
     2 0, .true., KERR)
      CALL SPAWN ('touch '//FNM(1:INZ)//'tm/sg/'//CPN//'/s.res',
     1  0, .true., KERR)
C * CHANGE DATA-POINTERS po & pn
      KERR = 0
      CALL SPAWN ('rm '//FNM(1:INZ)//'tm/sg/pn',              0,
     1  .true., KERR)
      CALL SPAWN ('ln -s '//CPN//' '//FNM(1:INZ)//'tm/sg/pn', 0,
     1  .true., KERR)
      CALL SPAWN ('rm '//FNM(1:INZ)//'tm/sg/po', 0, .true., KERR)
      CALL SPAWN ('ln -s '//CPR(104)(8:10)//' '//FNM(1:INZ)//'tm/sg/po',
     1  0, .true., KERR)
      CPR(104)(7 : 10) = '/'//CPN
      CALL S915 ('New save-link pn = '//CPN//' Created')
      OPEN (LU61, FILE = FNM(1:INZ)//'tm/sg/.save_nr',
     1      STATUS = 'UNKNOWN')
      WRITE (LU61, 99998, IOSTAT = IOST) NR
      CLOSE (UNIT = LU61)
 
C * CREATE NEW .s.dbf
      CALL S920 (1)
C * LINK TO REFLECTION FILE
      SELECT CASE (ISPR(14))
        CASE (0)
          CALL SPAWN
     1   ('ln -s ../../../hklf/shelx.hkl '//FNM(1:INZ)//'tm/sg/pn/s.hkl'
     2   , 0, .true., KERR)
        CASE (1)
        CASE (2)
          KERR = 0
          CALL SPAWN ('ln -s '//FNM(1:INZ)//'absp/absp.hkp '//
     1                 FNM(1:INZ)//'tm/sg/pn/s.hkl', 0, .true., KERR)
        CASE (3)
          KERR = 0
          CALL SPAWN
     1    ('ln -s ../mulabs/s.hkp '//FNM(1:INZ)//'tm/sg/pn/s.hkl',
     2      0, .true.,  KERR)
        CASE (4)
        CASE (5)
          KERR = 0
          CALL SPAWN ('ln -s '//FNM(1:INZ)//'abst/abst.hkp '//
     1                 FNM(1:INZ)//'tm/sg/pn/s.hkl', 0, .true., KERR)
        CASE (6)
          KERR = 0
          CALL SPAWN
     1    ('ln -s ../delabs/delabs.hkp '//FNM(1:INZ)//'tm/sg/pn/s.hkl',
     2      0, .true., KERR)
        CASE (7)
          KERR = 0
          CALL SPAWN
     1    ('ln -s ../squeeze/squeeze.hkp '//FNM(1:INZ)//'tm/sg/pn/s.hkl'
     2    ,  0, .true., KERR)
        CASE (8)
          INQUIRE (FILE = 'tm/sg/twinrotmat/shelxl.hkp', EXIST = EXST)
          IF (EXST) THEN
            KERR = 0
            CALL SPAWN
     1  ('ln -s ../twinrotmat/shelxl.hkp '//FNM(1:INZ)//'tm/sg/pn/s.hkl'
     2   , 0, .true., KERR)
          END IF
      END SELECT
      IGBL(38) = 1
C * SAVE COPY OF CURRENT .res
      IF (MODE == 1) THEN
        OPEN (LU61, FILE = 'tm/sg/po/s.res', STATUS = 'UNKNOWN')
        READ (LU61, 99999, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 20
        CLOSE (UNIT = LU61)
        IF (LINE(1:4) == 'TITL') THEN
C * SAVE COPY OF CURRENT .res
          KERR = 0
          CALL SPAWN ('cp tm/sg/po/s.res tm/sg/pn/s.res', 0,
     1      .true., KERR)
          GO TO 30
        END IF
   20   KERR = 0
        CALL SPAWN ('rm -f tm/sg/pn/s.res',           0, .true., KERR)
        CALL SPAWN ('ln -s /dev/null tm/sg/pn/s.res', 0, .true., KERR)
      END IF
   30 RETURN
99999 FORMAT (A)
99998 FORMAT (I3)
      END SUBROUTINE S924
 
      SUBROUTINE S925 (N)
      USE files
      USE parameters
      USE ccom
      IMPLICIT NONE
      INTEGER :: N
      IF (N == 0) THEN
      ELSE IF (N == 1) THEN
        WRITE (LU6, 99999, IOSTAT = IOST)
      ELSE IF (N == 2) THEN
        WRITE (LU6, 99998, IOSTAT = IOST) COMPD
      ELSE IF (N == 3) THEN
        WRITE (LU6, 99997, IOSTAT = IOST)
        KERR = 0
        CALL SPAWN ('ls -l | more', 0, .true., KERR)
      END IF
99999 FORMAT (':: Cannot do CHANGEDIR', /)
99998 FORMAT (' ?? Cannot find any SHELX or CAD4 data for: ',
     1         A, ' in known depositories', /)
99997 FORMAT (/, 3X, 'No .s.dbf or shelx.hkl present;',
     1        ' List Files in Dir:', /, 80('-'), /)
      END SUBROUTINE S925
 
      SUBROUTINE S926
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER, DIMENSION(16) :: ISFAC
      CHARACTER(len=132) :: LIN
C * ANALYSE FOR CONTENT FORMULA in s.res
      IF (ISPR(6) > 0) THEN
        OPEN (LU61, FILE = 's.res',   STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 'ipl.spf', STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99997, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          IF (LINE(1:3) == 'END') THEN
            WRITE (LU62, 99999, IOSTAT = IOST)
            EXIT
          ELSE
            WRITE (LU62, 99997, IOSTAT = IOST) LINE
          END IF
        END DO
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN (PLAPATH(1:IGBL(80))//' ipl.spf > ipl.log', 0,
     1    .true., KERR)
        CALL SPAWN ('rm ipl.spf', 0, .true., KERR)
        CALL SPAWN ('rm ipl.log', 0, .true., KERR)
        OPEN (LU61, FILE = 'ipl.lis', STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99997, IOSTAT = IOST) LIN
          IF (IOST == -1) GO TO 30
          IF (LIN(34:39) == 'Mol.Wt') THEN
            LINE = 'Z'//LIN(54:132)
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10,
     1                   NP17)
            DO 20 I = 2, KL
              DO J = 1, ISPR(110)
                IF (JFL(I)(1:2) == SFAC(J)) THEN
                  ISFAC(I - 1) = J
                  GO TO 20
                END IF
              END DO
              WRITE (LU6, 99998, IOSTAT = IOST) JFL(I)(1:2)
              CALL PLA015 (0, 33)
              RETURN
   20       CONTINUE
          ELSE IF (LIN(18:24) == ' Weight') THEN
            LINE = 'Z'//LIN(51:129)
            CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10,
     1                   NP17)
            DO I = 1, KN
              ISPR(152 + ISFAC(I)) = NINT (FN(I))
            END DO
          ELSE IF (LIN(23:25) == 'mu(') THEN
            READ (LIN(52:59), 99996) SPAR(123)
          END IF
        END DO
   30   CLOSE (UNIT = LU61)
        KERR = 0
        CALL SPAWN ('rm ipl.lis',    0, .true., KERR)
        CALL SPAWN ('rm ipl_pl.spf', 0, .true., KERR)
      END IF
      CALL S920 (1)
      RETURN
99999 FORMAT ('CALC GEOM NOMOVE', /, 'QUIT')
99998 FORMAT ('Error - SFAC-Element ', A, ' Not in Formula')
99997 FORMAT (A)
99996 FORMAT (F8.0)
      END SUBROUTINE S926
 
      SUBROUTINE S927 (ISHOW)
      USE files
      USE parameters
      USE ccom
      USE scom
      USE cggt
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: N1
      INTEGER :: N2
      INTEGER :: NK0
      INTEGER :: NSPL
      INTEGER :: MODE
      INTEGER :: ISHOW
      REAL :: R1
      REAL :: R2
      REAL :: VAL
      REAL :: YUNK
      REAL :: DENS
      CHARACTER(len=60) :: TXT1
      CHARACTER(len=60) :: TXT2
      CHARACTER(len=80) :: LIJN
      EXST = .FALSE.
      R1   = 0.0
      R2   = 0.0
      N1   = 0
      N2   = 0
      NSPL = 0
      MODE = ISPR(6) + ISPR(7)
      ISPR(223) = 0
      SPAR(140) = 0.0
      INQUIRE (FILE = FNM(1:INZ)//'tm/sg/shelxl/shelxl.lst',
     1         EXIST = EXST)
      IF (EXST .AND. MODE >= 0) THEN
        OPEN (LU61, FILE = FNM(1:INZ)//'tm/sg/shelxl/shelxl.lst',
     1        STATUS = 'UNKNOWN')
   10   READ (LU61, 99999, IOSTAT = IOST) LINE
        IF (IOST == -1) GO TO 30
        IF (LINE(2:11) == 'Mean shift') THEN
          TXT1 = LINE(1:60)
          READ (LINE(18:), 99992, IOSTAT = IOST) SPAR(131), SPAR(132)
          IF (IOST > 0) GO TO 10
        ELSE IF (LINE(2:5) == 'Max.') THEN
          TXT2 = LINE(1:60)
        ELSE IF (LINE(16:27) == 'before cycle') THEN
          READ (LINE, 99995, IOSTAT = IOST) N2
          IF (IOST > 0) GO TO 10
          ISPR(202) = N2
        ELSE IF (LINE(12:27) == 'Reflections read') THEN
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0,  LINE, 80, 0.35, -1, 2, 0.0, 17.4)
          END IF
          READ (LINE, 99996, IOSTAT = IOST) ISPR(70)
          IF (IOST > 0) GO TO 10
        ELSE IF (LINE(12:29) == 'Unique reflections') THEN
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0,  LINE, 80, 0.35, -1, 2, 0.0, 16.8)
          END IF
          READ (LINE, 99996, IOSTAT = IOST) ISPR(71)
          IF (IOST > 0) GO TO 10
        ELSE IF (LINE(1:9) == ' R(int) =') THEN
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0,  LINE, 80, 0.35, -1, 2, 0.0, 16.2)
          END IF
          IF (SPAR(126) == 0.0) THEN
            READ (LINE, 99994, IOSTAT = IOST) SPAR(150)
            IF (IOST > 0) GO TO 10
            SPAR(151) = SPAR(150)
          ELSE
            READ (LINE, 99994, IOSTAT = IOST) SPAR(151)
            IF (IOST > 0) GO TO 10
            IF (ISPR(14) == 2) SPAR(152) = SPAR(151)
          END IF
        ELSE IF (LINE(5:9) == ' =< h') THEN
          READ (LINE, 99993) (ISPR(56 + I), I = 1, 6), SPAR(54)
          SPAR(54) = SPAR(54) / 2.0
          SPAR(53) = SPAR(51)
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0,  LINE, 80, 0.35, -1, 2, 0.0, 15.6)
          END IF
C * SHELXL97 & SHELXL201n, 2019  FORMAT RESP.
        ELSE IF (LINE(52:58) == 'for all' .OR.
     1           LINE(53:59) == 'for all' .OR.
     1           LINE(54:60) == 'for all' .OR.
     2           LINE(48:54) == 'for all' .OR.
     2           LINE(47:53) == 'for all') THEN
          IF (LINE(47:53) == 'for all') THEN
            READ (LINE, 99991, IOSTAT = IOST) R1, N1
            IF (IOST > 0) GO TO 10
          ELSE IF (LINE(48:54) == 'for all') THEN
            READ (LINE, 99991, IOSTAT = IOST) R1, N1
            IF (IOST > 0) GO TO 10
          ELSE IF (LINE(52:58) == 'for all') THEN
            READ (LINE, 99990, IOSTAT = IOST) R1, N1
            IF (IOST > 0) GO TO 10
          ELSE
            READ (LINE, 99989, IOSTAT = IOST) R1, N1
            IF (IOST > 0) GO TO 10
          END IF
          SPAR(202) = R1
          ISPR(201) = N1
          ISPR(72)  = N1
          IF (ISHOW /= 0) THEN
            IF (R1 >= 0.07) CALL GGIP (0.0, 2.0, 0.0, 0)
            CALL PLA439 (0.0, LINE, 80, 0.35, -1, 2, 0.0, 14.6)
          END IF
        ELSE IF (LINE(18:27) == 'GooF = S =' .OR.
     1           LINE(16:25) == 'GooF = S =') THEN
          IF (LINE(18:27) == 'GooF = S =') THEN
            READ (LINE, 99988, IOSTAT = IOST) R2, SPAR(133)
            IF (IOST > 0) GO TO 10
          ELSE
            READ (LINE, 99987, IOSTAT = IOST) R2, SPAR(133)
            IF (IOST > 0) GO TO 10
          END IF
          SPAR(203) = R2
          IF (ISHOW /= 0) THEN
            IF (R2 >= 0.15) CALL GGIP (0.0, 2.0, 0.0, 0)
            CALL PLA439 (0.0, LINE, 80, 0.35, -1, 2, 0.0, 14.0)
            CALL PLA439 (0.0, TXT2, 60, 0.35, 1, 2, 0.0, 12.8)
            READ (TXT1(39:46), 99998, IOSTAT = IOST) YUNK
            IF (IOST > 0) GO TO 10
            IF (ABS (YUNK) >= 0.05) CALL GGIP (0.0, 2.0, 0.0, 0)
            CALL PLA439 (0.0, TXT1, 60, 0.35, -1, 2, 0.0, 13.4)
          END IF
        ELSE IF (Line(2:7) == 'Weight') THEN
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0, LINE, 65, 0.35, -1, 2, 0.0, 12.2)
          END IF
        ELSE IF (Line(2:12) == 'Recommended') THEN
          IF (ISHOW /= 0) THEN
            IF (ISPR(215) > 0) CALL GGIP (0.0, 2.0, 0.0, 0)
            CALL PLA439 (0.0, LINE, 80, 0.35, -1, 2, 0.0, 11.6)
          END IF
        ELSE IF (LINE(2:6) == 'Flack') THEN
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0, LINE, 80, 0.35, -1, 2, 0.0, 11.0)
          END IF
          READ (LINE, 99984, IOSTAT = IOST) SPAR(225), SPAR(226)
            IF (IOST > 0) GO TO 10
        ELSE IF (LINE(23:32) == 'parameters') THEN
          READ (LINE, 99985, IOSTAT = IOST) ISPR(203)
            IF (IOST > 0) GO TO 10
        ELSE IF (LINE(44:47) == 'BASF') THEN
          IF (ISPR(310) == 0) THEN
            READ (LINE, 99986, IOSTAT = IOST) SPAR(225), SPAR(226)
            IF (IOST > 0) GO TO 10
          ELSE
            READ (LINE, 99986, IOSTAT = IOST) SPAR(229), SPAR(230)
            IF (IOST > 0) GO TO 10
          END IF
        ELSE IF (LINE(44:47) == 'EXTI') THEN
          READ (LINE, 99986, IOSTAT = IOST) SPAR(227), SPAR(228)
          IF (IOST > 0) GO TO 10
          IF (SPAR(227) < 3.0 * SPAR(228) .OR. IGBL(96) == 0) THEN
            SPAR(227) = -1000.0
            SPAR(228) =     0.0
          END IF
C * OUTLIERS
        ELSE IF (LINE(6:10) == 'h   k') THEN
          IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0, LINE, 80, 0.35, 1, 2, 0.0, 10.0)
          END IF
        ELSE IF (LINE(51:51) == '.' .AND. LINE(54:54) == ' ') THEN
          READ (LINE(48:53), 99981, IOSTAT = IOST) VAL
          IF (IOST > 0) GO TO 10
          IF (VAL > 8.0) THEN
            ISPR(223) = ISPR(223) + 1
            IF (IGBL(51) > 0) THEN
              IF (ISPR(223) == 1) THEN
                OPEN (LU63, FILE = 'omit.hkl', STATUS = 'UNKNOWN')
              END IF
              WRITE (LU63, 99997, IOSTAT = IOST) LINE(1:14)
            END IF
            IF (ISPR(223) < 6) THEN
              IF (ISHOW /= 0) THEN
                CALL PLA439 (0.0, LINE, 80, 0.35, 2, 2, 0.0,
     1               (6 - ISPR(223)) * 0.6 + 6.2)
              END IF
            END IF
            IF (VAL > SPAR(140)) THEN
              SPAR(140) = VAL
              READ (LINE, 99983, IOSTAT = IOST) (ISPR(I), I = 220, 222),
     1              SPAR(141), SPAR(142)
              IF (IOST > 0) GO TO 10
            END IF
          END IF
        ELSE IF (LINE(2:13) == 'Highest peak') THEN
          IF (ISHOW /= 0) THEN
            READ (LINE(14:21), 99998, IOSTAT = IOST) YUNK
            IF (IOST > 0) GO TO 10
            NK0 = 1
            IF (YUNK >= 1.0) NK0 = 2
            CALL PLA439 (0.0, LINE, 80, 0.35, NK0, 2, 0.0, 6.0)
          END IF
          READ (LINE, 99982, IOSTAT = IOST) SPAR(130)
          IF (IOST > 0) GO TO 10
        ELSE IF (LINE(2:13) == 'Deepest hole') THEN
          IF (ISHOW /= 0) THEN
            READ (LINE(14:21), 99998, IOSTAT = IOST) YUNK
            IF (IOST > 0) GO TO 10
            NK0 = 1
            IF (YUNK < -1.0) NK0 = 2
            CALL PLA439 (0.0, LINE, 80, 0.35, NK0, 2, 0.0, 5.4)
          END IF
          READ (LINE, 99982, IOSTAT = IOST) SPAR(129)
          IF (IOST > 0) GO TO 10
C * WARNINGS
        ELSE IF (LINE(5:14) == 'Extinction') THEN
          IF (IGBL(96) == 0) THEN
            IF (IGBL(50) == 0) THEN
              WRITE (BCD, 99999, IOSTAT = IOST)
     1      'Implement Proposed Extinction Refinement (y/n[y]'//CHAR (0)
              CALL GGIP (-999.0, 5.0 + FLOAT (IGBL(68) * IGBL(82)),
     1        80.0, 110)
C * WHAT NEXT ?
              CALL PLA012 (0, 1)
              IF (IGGT(1:1) /= 'Y' .AND. IGGT(1:1) /= '!') GO TO 20
            END IF
            IGBL(96) = 1
          END IF
          IF (SPAR(227) < 0.0) SPAR(227) = 0.0
   20     IF (ISHOW /= 0) THEN
            CALL PLA439 (0.0, LINE, 80, 0.35, 2, 2, 0.0, 2.0)
          END IF
        ELSE IF (LINE(38:50) == ' may be split') THEN
          IF (ISHOW /= 0) THEN
            LIJN(1:14) = LINE (38:50)//':'
            IF (NSPL < 13) THEN
            NSPL = NSPL + 1
              LIJN (10 + NSPL * 5:) = LINE(30:34)
              CALL PLA439 (0.0, LIJN, 80, 0.35, 2, 2, 0.0, 2.6)
            END IF
          END IF
        END IF
        GO TO 10
   30   CLOSE (UNIT = LU61)
        IF (IGBL(51) > 0) CLOSE (UNIT = LU63)
        CALL S920 (1)
      END IF
C * SUBSTITUTE COMPOUND-NAME
      INQUIRE (FILE = FNM(1:INZ)//'tm/sg/shelxl/shelxl.cif',
     1         EXIST = EXST)
      IF (EXST .AND. MODE > 0) THEN
        OPEN (LU61, FILE = FNM(1:INZ)//'tm/sg/shelxl/shelxl.cif',
     1        STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 's.cif', STATUS = 'UNKNOWN')
        DO
          READ  (LU61, 99999, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          IF (LINE(1:11) == 'data_shelxl') LINE(1:15) = 'data_'//COMPD
          WRITE (LU62, 99999, IOSTAT = IOST) LINE
        END DO
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN ('mv s.cif '//FNM(1:INZ)//'tm/sg/shelxl/shelxl.cif',
     1    0, .true., KERR)
      END IF
C * ANALYSE .res
      ISPR(300) = 0
      ISPR(301) = 0
      ISPR(302) = 0
      ISPR(303) = 0
      IF (IGBL(51) * ISPR(223) > 0)
     1    CLOSE (UNIT = LU63, STATUS = 'DELETE')
      INQUIRE (FILE = FNM(1:INZ)//'tm/sg/shelxl/shelxl.res',
     1         EXIST = EXST)
      IF (EXST) THEN
        OPEN (LU61, FILE = FNM(1:INZ)//'tm/sg/shelxl/shelxl.res',
     1        STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99999, IOSTAT = IOST) LINE
          IF (IOST == -1) GO TO 50
          IF (LINE(1:1) == 'Q') THEN
            READ (LINE(49:56), 99998) DENS
            IF (DENS > 0.5) ISPR(300) = ISPR(300) + 1
            IF (DENS > 1.0) ISPR(301) = ISPR(301) + 1
            IF (DENS > 2.0) ISPR(302) = ISPR(302) + 1
            IF (DENS > 5.0) ISPR(303) = ISPR(303) + 1
          END IF
        END DO
   50   CLOSE (UNIT = LU61)
      END IF
      RETURN
99999 FORMAT (A)
99998 FORMAT (F8.0)
99997 FORMAT ('OMIT ', A)
99996 FORMAT (I9)
99995 FORMAT (35X, I7)
99994 FORMAT (9X, F6.0)
99993 FORMAT (1X, 3(I3, 8X, I3, 5X), 13X, F8.2)
99992 FORMAT (F8.0, 13X, F8.0)
99991 FORMAT (5X, F7.0, 4X, I5)
99990 FORMAT (5X, F9.0, 4X, I5)
99989 FORMAT (5X, F8.0, 4X, I5)
99988 FORMAT (6X, F8.0, 13X, F8.0)
99987 FORMAT (6X, F7.0, 12X, F5.0)
99986 FORMAT (6X, 2F12.0)
99985 FORMAT (34X, I6)
99984 FORMAT (20X, F9.0, 11X, F8.0)
99983 FORMAT (I6, 2I4, 2F14.2)
99982 FORMAT (13X, F8.2)
99981 FORMAT (F6.2)
 
      END  SUBROUTINE S927
 
      SUBROUTINE S928
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: N
      INTEGER :: NR
      CHARACTER(len=3) :: CPN
      EXST = .FALSE.
      INQUIRE (FILE = FNM(1:INZ)//'tm/sg/.save_nr',EXIST = EXST)
      IF (EXST) THEN
        OPEN (LU61, FILE = FNM(1:INZ)//'tm/sg/.save_nr',
     1        STATUS = 'UNKNOWN')
        READ (LU61, 99999) NR
        CLOSE (UNIT = LU61)
        IF (KN > 0) THEN
          N = NINT (FN(1))
        ELSE
          READ (CPR(104)(8:10), 99998) N
          IF (KL == 1 .OR.
     1        KL > 1 .AND. JFL(2)(1:4) == 'BACK') THEN
            N = N - 1
          ELSE
            N = N + 1
          END IF
        END IF
        CALL S923 (CPN, 0, N)
        IF (N >= 0 .AND. N <= NR) THEN
C * RELINK
          CALL DLNK (CPN, 'tm/sg/pn')
          CPR(104)(8 : 10) = CPN
C * READ DATA-BASE
          CALL S920 (-1)
          CALL S915 ('Relink to : '//CPR(104))
        END IF
      END IF
      IGBL(38) = 1
      RETURN
99999 FORMAT (I4)
99998 FORMAT (I3)
      END SUBROUTINE S928
 
      SUBROUTINE S929 (MODE)
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: MODE
      EXST = .FALSE.
      IF (MODE == -1) THEN
        INQUIRE (FILE = FNM(1:INZ)//'.faces',EXIST = EXST)
        I = 0
        IF (EXST) THEN
          OPEN (LU65, FILE = FNM(1:INZ)//'.faces', STATUS = 'UNKNOWN')
   10     CALL GEN072 (LINE, JFL, FN, KL, KN, LU65, LU6, 1, 1, 80, 10,
     1                 NP17)
          IF (JFL(1)(1:3) == 'EOF') THEN
            GO TO 20
          ELSE IF (JFL(1)(1:2) == 'MU') THEN
            SPAR(123) = FN(1)
          ELSE IF (JFL(1)(1:4) == 'FACE') THEN
            I = I + 1
            DO J = 1, 4
              FACE(I, J) = FN(J)
            END DO
          END IF
          GO TO 10
   20     CLOSE (UNIT = LU65)
        END IF
        ISPR(350) = I
      ELSE IF (MODE == 1) THEN
        OPEN  (LU65, FILE = FNM(1:INZ)//'.faces', STATUS = 'UNKNOWN')
        WRITE (LU65, '(''MU'', F10.2)', IOSTAT = IOST) SPAR(123)
        DO I = 1, ISPR(350)
          WRITE (LU65, '(''FACE'', 3F5.0, F8.5)', IOSTAT = IOST)
     1      (FACE(I, J), J = 1, 4)
        END DO
        CLOSE (UNIT = LU65)
      END IF
      RETURN
      END SUBROUTINE S929
 
      SUBROUTINE S930 (MODE, LIN, ISNR)
      USE scom
      IMPLICIT NONE
      INTEGER :: I
      INTEGER :: J
      INTEGER :: JB
      INTEGER :: MODE
      INTEGER :: ISNR
      INTEGER :: IOST
      INTEGER, SAVE, DIMENSION(16) :: NSFC
      CHARACTER(len=4) :: LIN
      IF (MODE > 0) THEN
        DO I = 1, ISPR(110)
C * CHECK FOR NUMERAL
          CALL GEN105 (3, LIN(2:2), J)
          IF (J >= 0) LIN(2:2) = ' '
          IF (LIN(1:2) == SFAC(I)) THEN
            IF (LIN(2:2) == ' ') THEN
              IF (NSFC(I) == 0) NSFC(I) = 500
              JB = 2
            ELSE
              IF (NSFC(I) == 0) NSFC(I) = 50
              JB = 3
            END IF
            NSFC(I) = NSFC(I) + 1
            ISNR    = I
            IF (JB == 3) THEN
              WRITE (LIN(JB:4), 99998, IOSTAT = IOST) NSFC(I)
            ELSE
              WRITE (LIN(JB:4), 99999, IOSTAT = IOST) NSFC(I)
            END IF
            IF (IOST /= 0) RETURN
            RETURN
          END IF
        END DO
      ELSE
        CALL GEN097 (NSFC, 1, 16, 0)
      END IF
      RETURN
99999 FORMAT (I3)
99998 FORMAT (I2)
      END SUBROUTINE S930
 
      SUBROUTINE S931
      USE scom
      IMPLICIT NONE
      INTEGER :: LKLS
      REAL :: DET
      REAL :: GEN068
      REAL, DIMENSION(3, 3) :: T
      REAL, DIMENSION(3, 3) :: AA
      REAL, DIMENSION(3, 3) :: BB
      CHARACTER(len=1) :: KS
C * TRANSFORM CELL-PARAMETERS
      CALL GEN026 (1, AA, SPAR(81))
      CALL GEN003 (AA, BB, DET, 0)
      SPAR(95)  = BB(1, 1)
      SPAR(96)  = BB(2, 2)
      SPAR(97)  = BB(3, 3)
      SPAR(98)  = BB(2, 3)
      SPAR(99)  = BB(1, 3)
      SPAR(100) = BB(1, 2)
      CALL GEN001 (1, TM, AA, BB)
      CALL GEN026 (-1, BB, SPAR(101))
      CALL GEN003 (BB, AA, DET, 0)
      SPAR(107) = SQRT (DET)
C * TRANSFORM CELL-ESD'S
      CALL GEN067 (TM, SPAR(81), SPAR(101), SPAR(88), SPAR(108))
      SPAR(114) = GEN068 (SPAR(101), SPAR(108), 1)
 
C * TRANSFORM ORIENTATION MATRIX
      CALL GEN003 (TM, T, DET, 0)
      CALL GEN004 (OM, T, OX)
C * APPLY SYMMETRY CONSTRAINTS ON CELL DIMENSIONS
C * MONOCLINIC
      LKLS = ISPR(105)
      KS   = 'a'
      IF (LKLS == 2) THEN
        KS = 'm'
C * ORTHORHOMBIC
      ELSE IF (LKLS == 3) THEN
        KS = 'o'
C * TETRAGONAL
      ELSE IF (LKLS == 4) THEN
        KS = 't'
C * TRIGONAL (RHOMBOHEDRAL)
      ELSE IF (LKLS == 5 .AND. CPR(103)(1:1) == 'r') THEN
        KS = 'r'
C * HEXAGONAL (TRIGONAL)
      ELSE IF (LKLS == 6 .OR.
     1    (LKLS == 5 .AND. CPR(103)(1:1) == 'h')) THEN
        KS = 'h'
C * CUBIC
      ELSE IF (LKLS == 7) THEN
        KS = 'c'
      END IF
      CALL GEN066 (2, SPAR(101), SPAR(108), KS, 0)
      RETURN
      END SUBROUTINE S931
 
      SUBROUTINE S932 (MODE)
      USE scom
      IMPLICIT NONE
      INTEGER :: MODE
      INTEGER :: KERR
C * MODE 1 : CREATE BASE TRANSFORMATION MATRIX DIRECTORY
      IF (MODE == 1) THEN
        KERR = 0
        CALL SPAWN ('mkdir 00',               0, .true., KERR)
        CALL SPAWN ('ln -s 00 tm',            0, .true., KERR)
        CALL SPAWN ('ln -s tm/s.res s.res',   0, .true., KERR)
        CALL SPAWN ('ln -s tm/s.hkl s.hkl',   0, .true., KERR)
        CALL SPAWN ('ln -s tm/.s.dbf .s.dbf', 0, .true., KERR)
      END IF
C * MODE 1,2 : CREATE BASE SYMMETRY DIRECTORY
      IF (MODE <= 2) THEN
        KERR = 0
        CALL SPAWN ('mkdir tm/000',              0, .true., KERR)
        CALL SPAWN ('ln -s 000 tm/sg',           0, .true., KERR)
        CALL SPAWN ('ln -s sg/s.res tm/s.res',   0, .true., KERR)
        CALL SPAWN ('ln -s sg/s.hkl tm/s.hkl',   0, .true., KERR)
        CALL SPAWN ('ln -s sg/.s.dbf tm/.s.dbf', 0, .true., KERR)
      END IF
C * MODE 1,2,3 : CREATE BASE PARAMETER DIRECTORY
      KERR = 0
      CALL SPAWN ('mkdir tm/sg/000',              0, .true., KERR)
      CALL SPAWN ('ln -s 000 tm/sg/po',           0, .true., KERR)
      CALL SPAWN ('ln -s 000 tm/sg/pn',           0, .true., KERR)
      CALL SPAWN ('ln -s pn/.s.dbf tm/sg/.s.dbf', 0, .true., KERR)
      CALL SPAWN ('ln -s pn/s.res  tm/sg/s.res',  0, .true., KERR)
      CALL SPAWN ('ln -s pn/s.hkl  tm/sg/s.hkl',  0, .true., KERR)
      CALL SPAWN ('mkdir tm/sg/setup',            0, .true., KERR)
      IF (ISPR(14) == 2) THEN
        KERR = 0
        CALL SPAWN ('ln -s ../../../absp/absp.hkp  tm/sg/pn/s.hkl',
     1    0, .true., KERR)
      ELSE
        KERR = 0
        CALL SPAWN ('ln -s ../../../hklf/shelx.hkl tm/sg/pn/s.hkl',
     1    0, .true., KERR)
      END IF
      KERR = 0
      CALL SPAWN ('ln -s ../pn/s.hkl tm/sg/setup/s.hkl', 0, .true.,
     1  KERR)
      CALL SPAWN ('ln -s  /dev/null tm/sg/pn/s.res', 0, .true., KERR)
      RETURN
      END SUBROUTINE S932
 
C * WHAT NEXT ?
 
      SUBROUTINE S934
C * PRUNE
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: CHDIR
      CHARACTER(len=80) :: LIJN
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      CALL GGIP (HORS, VERT, 0.0, 1)
   10 LIJN = 'PRUNE S-DIRECTORY STRUCTURE'
      CALL PLA439 (0.0, LIJN, 71, 1.0, 5 + IGBL(68), 5, 1.5,
     1             VERT - 2.5)
      CALL GEN038 (LIJN, 1, 80)
      LIJN =  'Directory = '//FNM(1:IU + 3)//COMPD(1:IC)
      CALL PLA439 (0.0, LIJN, 65, 0.5, 3, 2, 4.0, 7.0)
      IF (CHDIR (FNM(1:IU+2)) /= 0) GO TO 20
      SBCD = 'Remove '//COMPD(1:IC)//' (y/n[n])'//CHAR (0)
C * WHAT NEXT ?
      CALL PLA012 (0, 1)
      IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 10
      IF (IGGT(1:4) == 'EXIT') GO TO 20
      LINE = IGGT
      CALL GEN038 (IGGT, 1, 80)
      IF (LINE(1:1) == 'Y') THEN
        KERR = 0
        CALL SPAWN ('rm -r '//COMPD(1:IC), 0, .true., KERR)
        WRITE (LU6, '(''Current Directory '', A, '' Removed'')',
     1    IOSTAT = IOST) FNM(1:IU+3)//COMPD(1:IC)
C * CALL EXIT/STOP
        IF (CHDIR (WORKDIR) /= 0) CALL GEN127 (' ')
      ELSE
        LINE = '   '
C * CALL EXIT/STOP
        IF (CHDIR (FNM(1:IU+3)//COMPD(1:IC)) /= 0)
     1    CALL GEN127 (' ')
        IGBL(6) = 17
        GO TO 20
      END IF
C * CALL EXIT/STOP
      CALL GEN127 (' ')
   20 RETURN
      END SUBROUTINE S934
 
      SUBROUTINE S935 (MODE)
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER, PARAMETER :: NLS = 22
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: KM
      INTEGER :: MODE
      INTEGER, DIMENSION(NLS) :: NB
      INTEGER, DIMENSION(NLS) :: MB
      INTEGER, DIMENSION(NLS) :: LB
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=40), DIMENSION(NLS) :: CB
      NB = (/32, 30, 28, 28, 31, 40, 40, 38, 32, 36, 39, 35, 38, 38,
     1       37, 38, 34, 34, 34, 40, 36, 20/)
      CB =  (/
     1 '                                        ',
     2 '                                        ',
     3 '   - ABSPSI    absp/absp.lis            ',
     4 '   - LATT      latt/latt.lis            ',
     5 '   - SPGR      tm/spgr/spgr.lis         ',
     6 '   - SHELXS86  tm/sg/shelxs86/shelxs.lis',
     7 '   - SHELXS97  tm/sg/shelxs97/shelxs.lst',
     8 '   - SHELXD97  tm/sg/shelxd/shelxd.lst  ',
     9 '   - SIR97     tm/sg/sir/sir.out        ',
     * '   - SIR2004   tm/sg/sir2004/sir.out    ',
     1 '   - DIRDIF08  tm/sg/dirdif08/lis1      ',
     2 '   -                                    ',
     3 '   -                                    ',
     4 '   - SHELXL97  tm/sg/shelxl/shelxl.lst  ',
     5 '   - PLATON    tm/sg/platon/calc.lis    ',
     6 '   - ADDSYM    tm/sg/addsym/addsym.lis  ',
     7 '   - SOLV      tm/sg/solv/solv.lis      ',
     8 '   - CALC      tm/sg/calc/calc.lis      ',
     9 '   - ASYM      tm/sg/asym/asym.lis      ',
     * '   - SQUEEZE   tm/sg/squeeze/squeeze.lis',
     1 '   - VALID     tm/sg/valid/valid.chk    ',
     2 '   - LOG       s.log                    '/)
C * SPECIAL FIX FOR DIRDIF
      CB(9)(29:) = COMPD(1:IC)//'.lis2'
      NB(9)      = 33 + IC
      KM         = 0
      IGBL(28)   = 1
      DO I = 1, NLS
        INQUIRE (FILE = CB(I)(16:NB(I)), EXIST = EXST)
        IF (EXST) THEN
          MB(I)  = NB(I)
          KM     = KM + 1
          LB(KM) = I
        ELSE
          MB(I)  = 15
        END IF
      END DO
C * BROWSE
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      CALL GGIP (HORS, VERT, 0.0, 1)
   10 IF (MODE < 0) THEN
        LIJN = 'Laser Listing Files'
      ELSE
        LIJN = 'Browse Listing Files'
      END IF
      CALL PLA439 (0.0, LIJN, 71, 1.0, 5 + IGBL(68), 3, 1.5,
     1             VERT - 1.5)
      DO K = 1, KM
        J = LB(K)
        WRITE (CB(J)(1:2), 99999, IOSTAT = IOST) K
        CALL PLA439 (0.0, CB(J), MB(J), 0.4, 1, 2, 1.5,
     1       VERT - 2.0 - K)
      END DO
C * WHAT NEXT ?
C * DEFAULT: Enter #[0]
      CALL PLA012 (15, 1)
      IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 10
      IF (IGGT(1:4) == 'EXIT') GO TO 20
      LINE = IGGT
      CALL GEN038 (IGGT, 1, 80)
      CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
      IF (KL > 0) THEN
        CALL PLA280 (LINE)
        IGBL(42) = 0
        IGBL(43) = 0
        GO TO 20
      END IF
      N = NINT (FN(1))
      IF (N > 0 .AND. N <= KM) THEN
        N = LB(N)
        IF (MB(N) > 15) THEN
          IF (IABS (MODE) == 1) THEN
            OPEN (LU64, FILE = CB(N)(16:NB(N)), STATUS = 'UNKNOWN')
            OPEN (LU65, FILE = 'lps.lps',STATUS = 'UNKNOWN')
C * CONVERT TO POSTSCRIPT
            CALL GEN089 (LU64, LU65, 100, IGBL(102))
            CLOSE (UNIT = LU64)
            CLOSE (UNIT = LU65)
            IF (MODE > 0) THEN
              KERR = 0
              CALL SPAWN (PSVIEWER//'lps.lps', 0, .true., KERR)
            ELSE
              KERR = 0
              CALL SPAWN (PSLASER//'lps.lps', 0, .true., KERR)
            END IF
            KERR = 0
            CALL SPAWN ('rm lps.lps', 0, .true., KERR)
          ELSE
            KERR = 0
            CALL SPAWN (EDITOR//' '//CB(N)(16:NB(N)), 0, .true., KERR)
          END IF
        END IF
        GO TO 10
      ELSE
        LINE    = '   '
        IGBL(6) = 17
        GO TO 20
      END IF
   20 IGBL(28) = 0
      RETURN
99999 FORMAT (I2)
      END SUBROUTINE S935
 
      SUBROUTINE S936
      USE files
      USE parameters
      USE cggt
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER, PARAMETER :: NLS = 6
      INTEGER :: I
      INTEGER :: J
      INTEGER :: K
      INTEGER :: N
      INTEGER :: KM
      INTEGER, DIMENSION(NLS) :: NB
      INTEGER, DIMENSION(NLS) :: MB
      INTEGER, DIMENSION(NLS) :: LB
      CHARACTER(len=80) :: LIJN
      CHARACTER(len=37), DIMENSION(NLS) :: CB
      NB = (/31, 27, 37, 32, 37, 31/)
      CB = (/
     1 '                                     ',
     2 '   - ABSPSI    absp/absp.ps          ',
     3 '   -                                 ',
     4 '   - PLUTON    tm/sg/pluton/s.ps     ',
     5 '   - PLATON    tm/sg/platon/platon.ps',
     6 '   - ADP       tm/sg/adp/adp.ps      '/)
      KM       = 0
      IGBL(28) = 1
      DO I = 1, NLS
        INQUIRE (FILE = CB(I)(16:NB(I)), EXIST = EXST)
        IF (EXST) THEN
          MB(I)  = NB(I)
          KM     = KM + 1
          LB(KM) = I
        ELSE
          MB(I)  = 15
        END IF
      END DO
C * BROWSE
      BCD(1:16) = 'S.Y.S.T.E.M - S'//CHAR (0)
      CALL GGIP (HORS, VERT, 0.0, 1)
   10 LIJN = 'Browse PostScript Plots'
      CALL PLA439 (0.0, LIJN, 71, 1.0, 5 + IGBL(68), 3, 1.5,
     1             VERT - 1.5)
      DO K = 1, KM
        J = LB(K)
        WRITE (CB(J)(1:2), 99999, IOSTAT = IOST) K
        CALL PLA439 (0.0, CB(J), MB(J), 0.4, 1, 2, 1.5,
     1       VERT - 2.0 - K)
      END DO
C * WHAT NEXT ?
C * Enter #[0]
      CALL PLA012 (16, 1)
      IF (LRET == 2 .OR. IGGT(1:4) == 'PLOT') GO TO 10
      IF (IGGT(1:4) == 'EXIT') GO TO 20
      LINE = IGGT
      CALL GEN038 (IGGT, 1, 80)
      CALL GEN072 (LINE, JFL, FN, KL, KN, 0, LU6, 1, 1, 80, 10, NP17)
      IF (KL > 0) THEN
        CALL PLA280 (LINE)
        IGBL(42) = 0
        IGBL(43) = 0
        GO TO 20
      END IF
      N = NINT (FN(1))
      IF (N > 0 .AND. N <= NLS) THEN
        N = LB(N)
        IF (MB(N) > 15) THEN
          KERR = 0
          CALL SPAWN (PSVIEWER//CB(N)(16:NB(N)), 0, .true., KERR)
        END IF
        GO TO 10
      ELSE
        LINE    = '   '
        IGBL(6) = 17
        GO TO 20
      END IF
   20 IGBL(28) = 0
      RETURN
99999 FORMAT (I2)
      END SUBROUTINE S936
 
      SUBROUTINE S937
C * CHECK FOR/CREATE-CHANGE TO PLUTON-DIR UNDER user/s/compoundname
      USE files
      USE parameters
      USE ccom
      USE scom
      IMPLICIT NONE
      INTEGER :: CHDIR
      CALL S909 ('tm/sg/renum')
      KERR = 0
      CALL SPAWN ('cp ../s.res renum.ins', 0, .true., KERR)
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -R renum.ins > renum.log',
     1  0, .true., KERR)
      CALL SPAWN ('cp renum_pl.res sort.ins', 0, .true., KERR)
      CALL SPAWN (PLAPATH(1:IGBL(80))//' -g sort.ins > sort.log',
     1  0, .true., KERR)
      ISPR(92) = 1
C * CREATE NEW DATA LINK (tm/sg/pn)
      CALL S924 (0)
      IF (CPR(206)(1:4) == 'HFIX') THEN
        KERR = 0
        CALL SPAWN ('cp sort_pl.res ../s.res', 0, .true., KERR)
      ELSE
        OPEN (LU61, FILE = 'sort_pl.res', STATUS = 'UNKNOWN')
        OPEN (LU62, FILE = 's.res',    STATUS = 'UNKNOWN')
        DO
          READ (LU61, 99999, IOSTAT = IOST) LINE
          IF (IOST /= 0) EXIT
          IF (LINE(1:4) /= 'AFIX') THEN
            WRITE (LU62, 99999, IOSTAT = IOST) LINE
          END IF
        END DO
        CLOSE (UNIT = LU61)
        CLOSE (UNIT = LU62)
        KERR = 0
        CALL SPAWN ('cp s.res ../s.res', 0, .true., KERR)
      END IF
      CALL S920 (1)
C * ERROR HANDLING
      IF (CHDIR (FNM(1:INZ - 1)) /= 0) CALL S925 (1)
C * ENTER LOG
      CALL S915 ('Run PLATON/RENUM')
      RETURN
99999 FORMAT (A)
      END SUBROUTINE S937
 
      LOGICAL FUNCTION DINQ (FNM)
      USE files
      USE scom
      IMPLICIT NONE
      INTEGER :: NB
      INTEGER :: NE
      INTEGER :: KER
      CHARACTER(len=*)   :: FNM
      CHARACTER(len=1)   :: ICH
      CHARACTER(len=255) :: LINE
      LINE = FNM
      DINQ = .FALSE.
      NB   = 1
      NE   = 255
      CALL GEN039 (1, LINE, 1, 255, NB, NE)
      DO
        IF (MDNQ == 0) THEN
          INQUIRE (FILE = LINE(1:NE), EXIST = DINQ)
          RETURN
        ELSE IF (MDNQ == 1) THEN
          KER = 0
          CALL SPAWN ('ls -ld '//LINE(1:NE)//' > .exist 2> .error',
     1      0, .true., KERR)
          IF (KER /= 0) THEN
            OPEN (80, FILE = '.error', STATUS = 'UNKNOWN')
            READ (80, 99999, IOSTAT = IOST) LINE
            IF (IOST == 0) THEN
              IF (LINE(1:3) /= 'ls:')
     1          WRITE (*, 99999, IOSTAT = IOST) LINE(1:80)
            END IF
            CLOSE (UNIT = 80)
          END IF
          OPEN (80, FILE = '.exist', STATUS = 'UNKNOWN')
          READ (80, 99999, IOSTAT = IOST) ICH
          IF (IOST /= 0) RETURN
          CLOSE (UNIT = 80, STATUS = 'DELETE')
          IF (ICH == 'd') DINQ = .TRUE.
          KER = 0
          CALL SPAWN ('rm -f .error', 0, .true., KER)
          RETURN
        ELSE
          INQUIRE (FILE = '/bin', EXIST = EXST)
          IF (EXST) THEN
            MDNQ = 0
          ELSE
            MDNQ = 1
          END IF
        END IF
      END DO
99999 FORMAT (A)
      END FUNCTION DINQ
 
      SUBROUTINE DLNK (A, B)
      IMPLICIT NONE
      INTEGER :: KERR
      CHARACTER(len=*)  :: A
      CHARACTER(len=*)  :: B
      CHARACTER(len=80) :: P
      CHARACTER(len=80) :: Q
      P = A//' '//B
      Q = B
      KERR = 0
      CALL SPAWN ('rm -f '//Q, 0, .true., KERR)
      CALL SPAWN ('ln -s '//P, 0, .true., KERR)
      RETURN
      END SUBROUTINE DLNK
 
C STRIP_END
